      return {
        [6101703] = {
            ["Content"] = "“嗨，亲爱的旅人！请问你掉的是这个黄金提灯，还是这个木头提灯，又或者是这个普通提灯呢？”",
            ["ContentFR"] = "« Dis-moi, {性别:voyageur|voyageuse} ! Laquelle est la tienne ? La lanterne d’or, la lanterne de bois, ou la simple lanterne ? »",
            ["DialogueId"] = 6101703,
            ["GUID"] = "0F4664A6",
            ["NextOptions"] = {
                [1] = 6101704,
                [2] = 6101707,
                [3] = 6101710,
                },
            ["RougeTalkActorType"] = 1,
            ["SpeakNpcId"] = 910005,
            ["SpeakNpcName"] = "RougeLike_Room317_Char01",
            },
        [6101704] = {
            ["Content"] = "黄金提灯。",
            ["ContentFR"] = "<I>La lanterne d’or</>",
            ["DialogueId"] = 6101704,
            ["GUID"] = "0F4664D0",
            ["IsKeyOption"] = true,
            ["NextDialogue"] = 6101705,
            ["RougeTalkActorType"] = 2,
            },
        [6101705] = {
            ["Content"] = "“啊哈哈哈！”他发出一阵夸张的大笑，“很好，我很欣赏你！见到好东西，就该不择手段地争取才对！”\
“尽管拿走吧，亲爱的！谁不喜欢亮闪闪的金子呢——你说是吧！”",
            ["ContentFR"] = "« Ahahaha ! » Il éclate d’un grand rire tonitruant, son corps secoué d’exagération.\
« Splendide ! J’aime ton style ! Devant un trésor, il faut savoir tendre la main ! »\
« Prends-la, {性别:voyageur|voyageuse} ! Qui résiste à l’éclat de l’or, hein ? »",
            ["DialogueId"] = 6101705,
            ["GUID"] = "0F4664FA",
            ["NextDialogue"] = 6101706,
            ["RougeTalkActorType"] = 1,
            ["SpeakNpcId"] = 910005,
            ["SpeakNpcName"] = "RougeLike_Room317_Char01",
            },
        [6101706] = {
            ["Content"] = "那人一头扎进水中，水面随即消失了。\
你发现提灯还好好地摆在你的脚下，但它的周围却散落着一地余烬。",
            ["ContentFR"] = "L’homme plonge tête la première dans l’eau, et aussitôt, la surface se referme, comme si elle n’avait jamais existé.\
Tu baisses les yeux : la lanterne repose intacte à tes pieds, entourée de Braises.",
            ["DialogueId"] = 6101706,
            ["GUID"] = "0F466524",
            ["RougeTalkActorType"] = 3,
            },
        [6101707] = {
            ["Content"] = "木头提灯。",
            ["ContentFR"] = "<I>La lanterne de bois</>",
            ["DialogueId"] = 6101707,
            ["GUID"] = "0F46654E",
            ["IsKeyOption"] = true,
            ["NextDialogue"] = 6101708,
            ["RougeTalkActorType"] = 2,
            },
        [6101708] = {
            ["Content"] = "“嗯哼？你……很有趣！”他歪着脑袋，黑色的眼窝深不可测，“木头显然不能用来做提灯——但为什么不能呢？这里可是深渊啊，没有什么事是不可能的！”\
“祝福你，亲爱的！你一定会踏上一段有趣的旅途。”",
            ["ContentFR"] = "« Hein ? Toi... tu es drôle ! » Il penche la tête, et ses orbites noires semblent sans fond.\
« Le bois fait une piètre lanterne... mais pourquoi pas ? Ici, dans l’Abysse, rien n’est impossible ! »\
« Bénédictions sur toi, {性别:voyageur|voyageuse} ! Un chemin singulier t’attend. »",
            ["DialogueId"] = 6101708,
            ["GUID"] = "0F466578",
            ["NextDialogue"] = 6101709,
            ["RougeTalkActorType"] = 1,
            ["SpeakNpcId"] = 910005,
            ["SpeakNpcName"] = "RougeLike_Room317_Char01",
            },
        [6101709] = {
            ["Content"] = "那人一头扎进水中，水面随即消失了。\
你发现提灯还好好地摆在你的脚下，但它的旁边却多了一件遗物。",
            ["ContentFR"] = "L’homme plonge tête la première dans l’eau, et la surface se referme aussitôt, comme si rien n’avait jamais été.\
À tes pieds repose la lanterne, intacte. Tout près, un Artéfact luit faiblement dans l’ombre.",
            ["DialogueId"] = 6101709,
            ["GUID"] = "0F4665A2",
            ["RougeTalkActorType"] = 3,
            },
        [6101710] = {
            ["Content"] = "普通提灯。",
            ["ContentFR"] = "<I>La lanterne ordinaire</>",
            ["DialogueId"] = 6101710,
            ["GUID"] = "0F4665CC",
            ["IsKeyOption"] = true,
            ["NextDialogue"] = 6101711,
            ["RougeTalkActorType"] = 2,
            },
        [6101711] = {
            ["Content"] = "“唉，唉，你们都被传颂会那帮家伙教傻了。”他连连叹气，似乎对你的答案很不满意，“实话实说多无趣啊——你难道就不想换个其他样式的提灯？”",
            ["ContentFR"] = "« Pff, vous voilà tous rendus ternes par l’Église Élyséenne... » Il pousse plusieurs soupirs théâtraux, l’air profondément déçu.\
« L’honnêteté est si... ennuyeuse. Tu ne voudrais pas plutôt échanger ta lanterne ? »",
            ["DialogueId"] = 6101711,
            ["GUID"] = "0F4665F6",
            ["NextDialogue"] = 6101712,
            ["RougeTalkActorType"] = 1,
            ["SpeakNpcId"] = 910005,
            ["SpeakNpcName"] = "RougeLike_Room317_Char01",
            },
        [6101712] = {
            ["Content"] = "“也罢，也罢。”他摇了摇头，“诚实是美德，对吧？我就按故事说的那样，给你一点奖励吧。”",
            ["ContentFR"] = "« Soit... L’honnêteté est une vertu, paraît-il. Voilà ta récompense, comme dans l’histoire. »",
            ["DialogueId"] = 6101712,
            ["GUID"] = "0F466620",
            ["NextDialogue"] = 6101713,
            ["RougeTalkActorType"] = 1,
            ["SpeakNpcId"] = 910005,
            ["SpeakNpcName"] = "RougeLike_Room317_Char01",
            },
        [6101713] = {
            ["Content"] = "那人一头扎进水中，水面随即消失了。\
你发现提灯还好好地摆在你的脚下，但其中的烛光却变得更明亮了。",
            ["ContentFR"] = "L’homme plonge tête la première dans l’eau, et la surface se referme aussitôt.\
À tes pieds, la lanterne repose intacte, sa flamme, plus vive qu’avant.",
            ["DialogueId"] = 6101713,
            ["GUID"] = "0F46664A",
            ["RougeTalkActorType"] = 3,
            },
        [6101801] = {
            ["Content"] = "你在篝火旁坐下休息。\
忽然间，你注意到了一种奇怪的响声。一开始它好像就在你耳畔，然后渐渐远了一点，移到了头顶。\
声音越来越响，窸窸窣窣，似乎是某种柔软的东西在互相摩擦。",
            ["ContentFR"] = "Tu t’assieds près du feu pour te reposer.\
Soudain, un bruit étrange effleure ton oreille... puis s’éloigne, monte au-dessus de ta tête.\
Il enfle, de plus en plus clair : un froissement doux, comme des ailes de velours qui se frôlent.",
            ["DialogueId"] = 6101801,
            ["GUID"] = "0F4674BA",
            ["NextDialogue"] = 6101802,
            ["RougeTalkActorType"] = 3,
            },
        [6101802] = {
            ["Content"] = "“嗨！幸运的旅人！”",
            ["ContentFR"] = "« Hé ! {性别:Petit veinard|Petite veinarde} ! »",
            ["DialogueId"] = 6101802,
            ["GUID"] = "0F4674E4",
            ["NextDialogue"] = 6101803,
            ["RougeTalkActorType"] = 1,
            ["SpeakNpcId"] = 910005,
            ["SpeakNpcName"] = "RougeLike_Room381_Char01",
            },
        [6101803] = {
            ["Content"] = "色彩斑斓的羽毛从头顶落下来。你从来没有一次在深渊里同时看到这么多颜色。\
现在，你被包围在一地羽毛中间，好像被街头玩整蛊游戏的小家伙们偶然选中的倒霉路人，尴尬中还透着一丝微妙的可悲。",
            ["ContentFR"] = "Une pluie de plumes chatoyantes descend sur toi. Jamais, dans l’Abysse, tu n’as vu autant de couleurs à la fois.\
Bientôt, tu te retrouves enseveli sous cet amas bariolé, ridicule pantin d’une farce de rue, oscillant entre le comique et le pathétique.",
            ["DialogueId"] = 6101803,
            ["GUID"] = "0F46750E",
            ["NextDialogue"] = 6101804,
            ["RougeTalkActorType"] = 3,
            },
        [6101804] = {
            ["Content"] = "“我说，你怎么一点反应也没有？你在深渊里待这么久了，不觉得无聊吗？”\
戴着滑稽的鸟头面具的人从上方倒立着缓缓降落下来，让自己的视线与你齐平。\
你不知道他是怎么保持这个动作的，但这不重要，重要的是他面具上的尖嘴快要戳到你的脸了。",
            ["ContentFR"] = "« Quoi, pas de réaction ? Tu traînes ici depuis si longtemps... tu ne t’ennuies pas ? »\
Un homme avec un masque grotesque d’oiseau apparaît, suspendu la tête en bas.\
Il descend lentement jusqu’à ce que ses yeux soient au même niveau que les tiens.\
Comment il tient cette posture, tu n’en sais rien. Mais ce qui compte, c’est que le bec de son masque vacille dangereusement, prêt à heurter ton visage.",
            ["DialogueId"] = 6101804,
            ["GUID"] = "0F467538",
            ["NextOptions"] = {
                [1] = 6101805,
                },
            ["RougeTalkActorType"] = 1,
            ["SpeakNpcId"] = 910005,
            ["SpeakNpcName"] = "RougeLike_Room381_Char01",
            },
        [6101805] = {
            ["Content"] = "我没空陪你胡闹。",
            ["ContentFR"] = "<I>« Je n’ai pas le temps de jouer. »</>",
            ["DialogueId"] = 6101805,
            ["GUID"] = "0F467562",
            ["NextDialogue"] = 6101806,
            ["RougeTalkActorType"] = 2,
            },
        [6101806] = {
            ["Content"] = "“别这么冷淡嘛，传颂会的老家伙们应该教过你吧，日行一善会有好报的。”\
“跟我<H>玩个游戏</>，赢了就给你奖励，输了也没有惩罚。稳赚不赔，怎么样？”",
            ["ContentFR"] = "« Allons, ne sois pas si {性别:froid|froide}. Les vieux de l’Église Élyséenne ne t’ont-ils pas appris ? Une bonne action chaque jour attire la chance !\
Allez, <H>joue avec moi</>. Si tu gagnes, je t’offre une récompense, si tu perds... rien du tout. Pas de punition. Alors ? »",
            ["DialogueId"] = 6101806,
            ["GUID"] = "0F46758C",
            ["NextOptions"] = {
                [1] = 6101807,
                [2] = 6101808,
                },
            ["RougeTalkActorType"] = 1,
            ["SpeakNpcId"] = 910005,
            ["SpeakNpcName"] = "RougeLike_Room381_Char01",
            },
        [6101807] = {
            ["Content"] = "好吧。",
            ["ContentFR"] = "<I>« D’accord. »</>",
            ["DialogueId"] = 6101807,
            ["GUID"] = "0F4675B6",
            ["IsKeyOption"] = true,
            ["RougeTalkActorType"] = 2,
            },
        [6101808] = {
            ["Content"] = "我真的没空。",
            ["ContentFR"] = "<I>« Non, vraiment, je n’ai pas le temps. »</>",
            ["DialogueId"] = 6101808,
            ["GUID"] = "0F4675E0",
            ["IsKeyOption"] = true,
            ["NextDialogue"] = 6101809,
            ["RougeTalkActorType"] = 2,
            },
        [6101809] = {
            ["Content"] = "“好吧，好吧，我也不是什么强人所难的坏家伙嘛。”\
“那我们下次再见！”",
            ["ContentFR"] = "« Bon, bon, inutile de forcer. Je ne suis pas un mauvais bougre, après tout. »\
« La prochaine fois, peut-être ! »",
            ["DialogueId"] = 6101809,
            ["GUID"] = "0F46760A",
            ["RougeTalkActorType"] = 1,
            ["SpeakNpcId"] = 910005,
            ["SpeakNpcName"] = "RougeLike_Room381_Char01",
            },
        [6101901] = {
            ["Content"] = "篝火映出一位老人皱缩的面庞。\
老人手中拿着一把铁锤，脚下散落着几柄武器。\
看见你，他的眼中浮现一丝惊喜。",
            ["ContentFR"] = "La lueur du feu éclaire le visage ridé d’un vieil homme.\
Un marteau de fer repose dans sa main, et à ses pieds gisent des armes éparpillées.\
Quand ses yeux croisent les tiens, une étincelle de joie y brille un instant.",
            ["DialogueId"] = 6101901,
            ["GUID"] = "0F468522",
            ["NextDialogue"] = 6101902,
            ["RougeTalkActorType"] = 3,
            },
        [6101902] = {
            ["Content"] = "“年轻人，你知道艾利西安在哪个方向吗？”\
老人开口，声音枯哑。\
“我在这附近转了几圈，怎么也找不见回家的路……”",
            ["ContentFR"] = "« Jeune {性别:voyageur|voyageuse}... saurais-tu m’indiquer la route d’Élysium ? »\
Sa voix est rauque, éteinte.\
« J’ai tourné en rond si longtemps par ici... mais je n’arrive plus à retrouver le chemin de ma maison... »",
            ["DialogueId"] = 6101902,
            ["GUID"] = "0F46854C",
            ["NextOptions"] = {
                [1] = 6101903,
                },
            ["RougeTalkActorType"] = 1,
            ["SpeakNpcId"] = 910005,
            ["SpeakNpcName"] = "RougeLike_Room319_Char01",
            },
        [6101903] = {
            ["Content"] = "沉默。",
            ["ContentFR"] = "<I>Garder le silence</>",
            ["DialogueId"] = 6101903,
            ["GUID"] = "0F468576",
            ["NextDialogue"] = 6101904,
            ["RougeTalkActorType"] = 2,
            },
        [6101904] = {
            ["Content"] = "“是吗……你也迷路了吗。唉……”\
老人长叹一声，垂下了头。",
            ["ContentFR"] = "« Je vois... toi aussi, tu es perdu, n’est-ce pas ? »\
Le vieillard pousse un long soupir et baisse la tête.",
            ["DialogueId"] = 6101904,
            ["GUID"] = "0F4685A0",
            ["NextOptions"] = {
                [1] = 6101905,
                },
            ["RougeTalkActorType"] = 1,
            ["SpeakNpcId"] = 910005,
            ["SpeakNpcName"] = "RougeLike_Room319_Char01",
            },
        [6101905] = {
            ["Content"] = "询问他是否可以给你一件武器。",
            ["ContentFR"] = "<I>Demander s’il peut te donner une arme</>",
            ["DialogueId"] = 6101905,
            ["GUID"] = "0F4685CA",
            ["NextDialogue"] = 6101906,
            ["RougeTalkActorType"] = 2,
            },
        [6101906] = {
            ["Content"] = "“武器？你是说地上的这些？”\
“噢……我想起来了，我是……一名铁匠。”\
“我为一些人制造了武器，帮助他们逃离，然后——”",
            ["ContentFR"] = "« Une arme ? Tu parles de celles-là, par terre ? »\
« Ah... oui... je me souviens à présent. J’étais... forgeron. »\
« J’ai forgé des armes pour quelques âmes, afin qu’elles s’enfuient, et puis— »",
            ["DialogueId"] = 6101906,
            ["GUID"] = "0F4685F4",
            ["NextDialogue"] = 6101907,
            ["RougeTalkActorType"] = 1,
            ["SpeakNpcId"] = 910005,
            ["SpeakNpcName"] = "RougeLike_Room319_Char01",
            },
        [6101907] = {
            ["Content"] = "老人的目光黯淡了一瞬，似是终于想起了自己来到此地的缘由。\
随后，他轻轻摇了摇头，向你报以一个沧桑的笑容。",
            ["ContentFR"] = "Son regard se voile, comme s’il venait enfin de se rappeler pourquoi il était venu en ce lieu.\
Puis, il secoue doucement la tête et t’adresse un sourire fatigué.",
            ["DialogueId"] = 6101907,
            ["GUID"] = "0F46861E",
            ["NextDialogue"] = 6101908,
            ["RougeTalkActorType"] = 3,
            },
        [6101908] = {
            ["Content"] = "“当然可以，孩子。”\
“请随意挑选吧，希望它能护你平安。”",
            ["ContentFR"] = "« Bien sûr, mon enfant. »\
« Choisis celle qui te plaît. Qu’elle te protège. »",
            ["DialogueId"] = 6101908,
            ["GUID"] = "0F468648",
            ["NextOptions"] = {
                [1] = 6101909,
                [2] = 6101910,
                },
            ["RougeTalkActorType"] = 1,
            ["SpeakNpcId"] = 910005,
            ["SpeakNpcName"] = "RougeLike_Room319_Char01",
            },
        [6101909] = {
            ["Content"] = "从老人左手边的武器中挑选。",
            ["ContentFR"] = "<I>Choisir parmi les armes à sa gauche</>",
            ["DialogueId"] = 6101909,
            ["GUID"] = "0F468672",
            ["IsKeyOption"] = true,
            ["NextDialogue"] = 6101911,
            ["RougeTalkActorType"] = 2,
            },
        [6101910] = {
            ["Content"] = "从老人右手边的武器中挑选。",
            ["ContentFR"] = "<I>Choisir parmi les armes à sa droite</>",
            ["DialogueId"] = 6101910,
            ["GUID"] = "0F46869C",
            ["IsKeyOption"] = true,
            ["NextDialogue"] = 6101911,
            ["RougeTalkActorType"] = 2,
            },
        [6101911] = {
            ["Content"] = "你将挑选的武器收入囊中。\
老人似乎已经忘了你的存在，只是一言不发地注视着手中的铁锤，似是陷入了思考。",
            ["ContentFR"] = "Tu ranges l’arme choisie.\
Déjà, le vieillard semble t’avoir oublié : ses yeux demeurent fixés sur le marteau dans sa main, perdu dans de sombres pensées.",
            ["DialogueId"] = 6101911,
            ["GUID"] = "0F4686C6",
            ["RougeTalkActorType"] = 3,
            },
        [6102001] = {
            ["Content"] = "你听见金属撞击的声音。火花飞溅，融化在篝火的光明中。\
你循着声音的方向看去，老人在简陋的锻造台边用力挥动着铁锤，汗珠从他的额前滴落。",
            ["ContentFR"] = "Un martèlement métallique résonne. Des étincelles jaillissent, se fondant dans la lumière du feu.\
En suivant le bruit, tu découvres le vieil homme devant une forge de fortune, son marteau s’abattant avec force. La sueur perle à son front.",
            ["DialogueId"] = 6102001,
            ["GUID"] = "0F46958A",
            ["NextDialogue"] = 6102002,
            ["RougeTalkActorType"] = 3,
            },
        [6102002] = {
            ["Content"] = "“年轻人，你好啊！”\
见到你，老人热情地打招呼。",
            ["ContentFR"] = "« Bonjour, jeune {性别:voyageur|voyageuse} ! »\
Il te salue d’une voix pleine de chaleur.",
            ["DialogueId"] = 6102002,
            ["GUID"] = "0F4695B4",
            ["NextOptions"] = {
                [1] = 6102003,
                },
            ["RougeTalkActorType"] = 1,
            ["SpeakNpcId"] = 910005,
            ["SpeakNpcName"] = "RougeLike_Room318_Char01",
            },
        [6102003] = {
            ["Content"] = "您好。",
            ["ContentFR"] = "<I>Bonjour</>",
            ["DialogueId"] = 6102003,
            ["GUID"] = "0F4695DE",
            ["NextDialogue"] = 6102004,
            ["RougeTalkActorType"] = 2,
            },
        [6102004] = {
            ["Content"] = "“看样子，你也被困在这地方了吧？”老人指了指自己，“我也是。”",
            ["ContentFR"] = "« On dirait que toi aussi, tu es coincé dans cet endroit, hein ? »\
Il se désigne d’un geste, un sourire en coin. « Moi aussi. »",
            ["DialogueId"] = 6102004,
            ["GUID"] = "0F469608",
            ["NextOptions"] = {
                [1] = 6102005,
                },
            ["RougeTalkActorType"] = 1,
            ["SpeakNpcId"] = 910005,
            ["SpeakNpcName"] = "RougeLike_Room318_Char01",
            },
        [6102005] = {
            ["Content"] = "我们又见面了。",
            ["ContentFR"] = "<I>Nous nous retrouvons</>",
            ["DialogueId"] = 6102005,
            ["GUID"] = "0F469632",
            ["NextDialogue"] = 6102006,
            ["RougeTalkActorType"] = 2,
            },
        [6102006] = {
            ["Content"] = "“我们见过面吗？”老人有些困惑，“我倒是不记得了，最近记性越来越差……”",
            ["ContentFR"] = "« Nous nous sommes déjà rencontrés ? » dit-il, troublé.\
« Ma mémoire me joue des tours... je n’arrive plus à me souvenir de grand-chose, ces derniers temps... »",
            ["DialogueId"] = 6102006,
            ["GUID"] = "0F46965C",
            ["NextDialogue"] = 6102007,
            ["RougeTalkActorType"] = 1,
            ["SpeakNpcId"] = 910005,
            ["SpeakNpcName"] = "RougeLike_Room318_Char01",
            },
        [6102007] = {
            ["Content"] = "“这地方危险，我造了些武器，你挑一件带走吧。”\
老人爽朗地向你展示他的作品。\
“我想着，横竖都找不到出去的路，不如做回老本行。说不定哪天，我造的武器能帮到某位了不得的骑士大人，把我们带出这个鬼地方。”",
            ["ContentFR"] = "Il rit d’un air franc, puis désigne la forge :\
« Cet endroit est dangereux. J’ai forgé quelques armes : prends-en une. »\
« Puisque je ne trouve pas de sortie, autant revenir à mon métier. Qui sait ? Peut-être qu’un jour, l’une de ces lames tombera entre les mains d’un grand chevalier, et qu’il nous mènera enfin hors de cet enfer. »",
            ["DialogueId"] = 6102007,
            ["GUID"] = "0F469686",
            ["NextOptions"] = {
                [1] = 6102008,
                [2] = 6102009,
                [3] = 6102010,
                },
            ["RougeTalkActorType"] = 1,
            ["SpeakNpcId"] = 910005,
            ["SpeakNpcName"] = "RougeLike_Room318_Char01",
            },
        [6102008] = {
            ["Content"] = "从刚铸成的新武器中挑选。",
            ["ContentFR"] = "<I>Choisir parmi les armes fraîchement forgées</>",
            ["DialogueId"] = 6102008,
            ["GUID"] = "0F4696B0",
            ["IsKeyOption"] = true,
            ["NextDialogue"] = 6102011,
            ["RougeTalkActorType"] = 2,
            },
        [6102009] = {
            ["Content"] = "从排列整齐的成品中挑选。",
            ["ContentFR"] = "<I>Choisir parmi les pièces terminées, soigneusement rangées</>",
            ["DialogueId"] = 6102009,
            ["GUID"] = "0F4696DA",
            ["IsKeyOption"] = true,
            ["NextDialogue"] = 6102011,
            ["RougeTalkActorType"] = 2,
            },
        [6102010] = {
            ["Content"] = "从蒙尘的储藏角落中挑选。",
            ["ContentFR"] = "<I>Choisir dans le coin poussiéreux de l’atelier</>",
            ["DialogueId"] = 6102010,
            ["GUID"] = "0F469704",
            ["IsKeyOption"] = true,
            ["NextDialogue"] = 6102011,
            ["RougeTalkActorType"] = 2,
            },
        [6102011] = {
            ["Content"] = "带着挑选的武器，你在老人亲切的道别声中继续前进。",
            ["ContentFR"] = "Tu repars avec l’arme choisie, tandis que la chaleureuse voix du vieillard t’accompagne encore quelque temps.",
            ["DialogueId"] = 6102011,
            ["GUID"] = "0F46972E",
            ["RougeTalkActorType"] = 3,
            },
        [6102101] = {
            ["Content"] = "篝火明灭，勾勒出诗人低垂的侧脸。\
她半跪在篝火旁，伸出手指，在烟灰中缓缓勾勒出蜿蜒的纹路。",
            ["ContentFR"] = "La lueur vacillante du feu dessine le profil penché d’une poétesse.\
À demi agenouillée près des flammes, elle tend la main et trace lentement de sinueux motifs dans la cendre.",
            ["DialogueId"] = 6102101,
            ["GUID"] = "0F46A5F2",
            ["NextDialogue"] = 6102102,
            ["RougeTalkActorType"] = 3,
            },
        [6102102] = {
            ["Content"] = "“若无处可逃，那便接受命运吧；”\
“若文字无法成为刺破谎言的利刃，那便让它成为砌筑美梦的砖瓦吧——”\
诗人停顿了一下，微微抬起指尖。\
“唔……”",
            ["ContentFR"] = "« S’il n’existe nulle échappatoire... alors accepte ton destin. »\
« Si les mots ne peuvent être des lames pour percer le mensonge, qu’ils deviennent les briques de nos songes... »\
Elle s’interrompt, son doigt suspendu dans l’air.\
« Hmm... »",
            ["DialogueId"] = 6102102,
            ["GUID"] = "0F46A61C",
            ["NextDialogue"] = 6102103,
            ["RougeTalkActorType"] = 1,
            ["SpeakNpcId"] = 910005,
            ["SpeakNpcName"] = "RougeLike_Room320_Char01",
            },
        [6102103] = {
            ["Content"] = "脑海中的回忆忽然被唤醒，你确信自己曾经听过这首诗。\
一缕烟灰拂过脸颊，几乎是下意识地，你轻声念出了那空缺的最后一句——",
            ["ContentFR"] = "Un souvenir s’éveille au fond de ta mémoire : tu es {性别:certain|certaine} d’avoir déjà entendu ce poème.\
Une volute de cendre effleure ta joue, et presque malgré toi, tu souffles la phrase manquante—",
            ["DialogueId"] = 6102103,
            ["GUID"] = "0F46A646",
            ["NextOptions"] = {
                [1] = 6102104,
                },
            ["RougeTalkActorType"] = 3,
            },
        [6102104] = {
            ["Content"] = "“书写一个谎言，点燃一束不熄的火光。”",
            ["ContentFR"] = "<I>« Écrire un mensonge, et allumer une flamme qui jamais ne s’éteindra. »</>",
            ["DialogueId"] = 6102104,
            ["GUID"] = "0F46A670",
            ["NextDialogue"] = 6102105,
            ["RougeTalkActorType"] = 2,
            },
        [6102105] = {
            ["Content"] = "“嗯……？！”\
诗人抬起头来，惊喜地看着你。\
“多么美妙的词句啊，这正是我想要的结尾！没想到竟能在这里遇上一位知己，真是幸运。”",
            ["ContentFR"] = "« ... ! »\
Elle lève la tête, ses yeux s’illuminent d’un étonnement joyeux.\
« Quelle phrase merveilleuse... c’est le vers final que j’attendais ! Quelle chance de rencontrer {性别:un|une} semblable en ce lieu. »",
            ["DialogueId"] = 6102105,
            ["GUID"] = "0F46A69A",
            ["NextOptions"] = {
                [1] = 6102106,
                },
            ["RougeTalkActorType"] = 1,
            ["SpeakNpcId"] = 910005,
            ["SpeakNpcName"] = "RougeLike_Room320_Char01",
            },
        [6102106] = {
            ["Content"] = "“其实这是另一个时间的你写下的。”",
            ["ContentFR"] = "<I>« En vérité, c’est toi qui l’as écrit... dans un autre temps. »</>",
            ["DialogueId"] = 6102106,
            ["GUID"] = "0F46A6C4",
            ["NextDialogue"] = 6102107,
            ["RougeTalkActorType"] = 2,
            },
        [6102107] = {
            ["Content"] = "“‘另一个时间’……？”\
诗人先是露出讶异的神情，然后目光很快变得明亮，像是被那篝火点燃了一般。\
“原来如此……您是特别的——是这首叙事诗的主角，是我将在时间的其他方向再度遇见的人，对吗？”",
            ["ContentFR"] = "« Un autre... temps ? »\
La surprise passe sur son visage, vite remplacée par une lueur ardente, comme attisée par les flammes.\
« Je comprends... Tu es le cœur de cette épopée. {性别:Celui|Celle} que je rencontrerai encore, au détour d’une autre trame du temps, n’est-ce pas ? »",
            ["DialogueId"] = 6102107,
            ["GUID"] = "0F46A6EE",
            ["NextOptions"] = {
                [1] = 6102108,
                },
            ["RougeTalkActorType"] = 1,
            ["SpeakNpcId"] = 910005,
            ["SpeakNpcName"] = "RougeLike_Room320_Char01",
            },
        [6102108] = {
            ["Content"] = "点头。",
            ["ContentFR"] = "<I>Hocher la tête</>",
            ["DialogueId"] = 6102108,
            ["GUID"] = "0F46A718",
            ["NextDialogue"] = 6102109,
            ["RougeTalkActorType"] = 2,
            },
        [6102109] = {
            ["Content"] = "“那么这句诗究竟算是您写的，还是我写的呢？呵呵……真是个迷人的疑问，我想圣树学院的学者们也会为您的故事倾倒。”\
诗人咯咯地笑起来。\
“下次见面的时候，还请允许我为您作一首诗。现在，请伸出手来，收下我的祝福吧。”",
            ["ContentFR"] = "« Alors ce poème... est-ce le tien, ou le mien ? Charmant paradoxe... Les érudits de l’Académie de l’Arbre Sacré en perdraient la raison ! »\
Elle rit doucement.\
« Quand nous nous reverrons, permets-moi de composer un poème pour toi. Pour l’heure, tends-moi ta main, que je t’offre ma bénédiction. »",
            ["DialogueId"] = 6102109,
            ["GUID"] = "0F46A742",
            ["NextOptions"] = {
                [1] = 6102110,
                [2] = 6102111,
                },
            ["RougeTalkActorType"] = 1,
            ["SpeakNpcId"] = 910005,
            ["SpeakNpcName"] = "RougeLike_Room320_Char01",
            },
        [6102110] = {
            ["Content"] = "伸出左手。",
            ["ContentFR"] = "<I>Tendre la main gauche</>",
            ["DialogueId"] = 6102110,
            ["GUID"] = "0F46A76C",
            ["IsKeyOption"] = true,
            ["NextDialogue"] = 6102112,
            ["RougeTalkActorType"] = 2,
            },
        [6102111] = {
            ["Content"] = "伸出右手。",
            ["ContentFR"] = "<I>Tendre la main droite</>",
            ["DialogueId"] = 6102111,
            ["GUID"] = "0F46A796",
            ["IsKeyOption"] = true,
            ["NextDialogue"] = 6102112,
            ["RougeTalkActorType"] = 2,
            },
        [6102112] = {
            ["Content"] = "诗人用指尖残留的烟灰在你的手心写下了什么。\
你依旧无法理解这些文字的含义，但你能感觉到它鲜明的温度，热烈却不至于将人灼伤。\
当你再次抬头，诗人已经不知所踪。",
            ["ContentFR"] = "Avec la cendre qui lui reste au bout des doigts, la poétesse inscrit quelques signes dans ta paume.\
Tu ne saurais en déchiffrer le sens, mais leur chaleur vive pulse encore, ardente sans brûler.\
Quand tu relèves les yeux, elle a disparu.",
            ["DialogueId"] = 6102112,
            ["GUID"] = "0F46A7C0",
            ["RougeTalkActorType"] = 3,
            },
        [6102201] = {
            ["Content"] = "“那无常的命运之神啊，时而令我们欢喜，时而令我们苦痛……”\
“常怀虔诚之心……祂洁白的纺线终会将我们与那众天之天的乐土连缀……”\
少年认真而虔诚地朗读着书本上的词句，对你的出现浑然不觉。",
            ["ContentFR"] = "« Ô dieu changeant des destins, tantôt nous donnes-tu la joie, tantôt nous abandonnes-tu à la douleur... »\
« Gardons toujours un cœur pieux... Car ton fil immaculé nous liera, au bout du chemin, au Paradis des Paradis... »\
Le garçon lit avec une ferveur appliquée, inconscient de ta présence.",
            ["DialogueId"] = 6102201,
            ["GUID"] = "0F46B65A",
            ["NextDialogue"] = 6102202,
            ["RougeTalkActorType"] = 1,
            ["SpeakNpcId"] = 910005,
            ["SpeakNpcName"] = "RougeLike_Room321_Char01",
            },
        [6102202] = {
            ["Content"] = "你悄然走到少年身边，飞快地瞥了一眼他手中的书。\
如你记忆中那般，书页上的圣歌被充满恶意的漆黑文字覆盖。\
那文字扭动着，似要挣脱出纸面。",
            ["ContentFR"] = "Tu t’approches en silence, jetant un coup d’œil rapide à l’ouvrage.\
Comme dans tes souvenirs, les pages de l’hymnaire sont maculées d’une écriture noire, tordue, qui semble vouloir s’arracher au papier.",
            ["DialogueId"] = 6102202,
            ["GUID"] = "0F46B684",
            ["NextDialogue"] = 6102203,
            ["RougeTalkActorType"] = 3,
            },
        [6102203] = {
            ["Content"] = "“您好……您也想看书吗？”\
少年终于注意到你，好奇地抬起了头。",
            ["ContentFR"] = "« Oh... bonjour. Toi aussi, tu veux lire ? »\
Enfin il te remarque, levant les yeux avec curiosité.",
            ["DialogueId"] = 6102203,
            ["GUID"] = "0F46B6AE",
            ["NextOptions"] = {
                [1] = 6102204,
                [2] = 6102208,
                },
            ["RougeTalkActorType"] = 1,
            ["SpeakNpcId"] = 910005,
            ["SpeakNpcName"] = "RougeLike_Room321_Char01",
            },
        [6102204] = {
            ["Content"] = "阻止他继续读下去。",
            ["ContentFR"] = "<I>Empêcher de lire</>",
            ["DialogueId"] = 6102204,
            ["GUID"] = "0F46B6D8",
            ["IsKeyOption"] = true,
            ["NextDialogue"] = 6102205,
            ["RougeTalkActorType"] = 2,
            },
        [6102205] = {
            ["Content"] = "你将那本书从少年的手中抽出，用力地合上。",
            ["ContentFR"] = "Tu arraches le livre de ses mains et le refermes d’un geste sec.",
            ["DialogueId"] = 6102205,
            ["GUID"] = "0F46B702",
            ["NextDialogue"] = 6102206,
            ["RougeTalkActorType"] = 3,
            },
        [6102206] = {
            ["Content"] = "“您没事吧？！”\
少年担忧地站起来，随机又茫然地看向自己空无一物的双手。\
“咦？我……不用再读书了吗？我……自由了吗？”",
            ["ContentFR"] = "« Qu’est-ce que... !? »\
Il se redresse, inquiet, puis baisse les yeux vers ses paumes vides.\
« Attends... je n’ai plus besoin de lire ? Je... je suis libre ? »",
            ["DialogueId"] = 6102206,
            ["GUID"] = "0F46B72C",
            ["NextDialogue"] = 6102207,
            ["RougeTalkActorType"] = 1,
            ["SpeakNpcId"] = 910005,
            ["SpeakNpcName"] = "RougeLike_Room321_Char01",
            },
        [6102207] = {
            ["Content"] = "你忍住指尖的痛楚，微笑着向他点了点头，然后将那本书扔进篝火里。\
火焰猛然升起，黑色的荆棘席卷着火舌一起向你袭来——",
            ["ContentFR"] = "Tu ignores la douleur qui te brûle les doigts, et lui adresses un sourire discret.\
Puis tu jettes le livre au feu.\
Les flammes s’élancent d’un coup, des ronces noires s’y mêlent, te fondant dessus comme une tempête.",
            ["DialogueId"] = 6102207,
            ["GUID"] = "0F46B756",
            ["RougeTalkActorType"] = 3,
            },
        [6102208] = {
            ["Content"] = "沉默。",
            ["ContentFR"] = "<I>Garder le silence</>",
            ["DialogueId"] = 6102208,
            ["GUID"] = "0F46B780",
            ["IsKeyOption"] = true,
            ["NextDialogue"] = 6102209,
            ["RougeTalkActorType"] = 2,
            },
        [6102209] = {
            ["Content"] = "你知道，无论你在此刻做出怎样的行动，都无法真正改变少年的命运。\
你还有更重要的事去做——收集琉璃，彻底结束这个漫长的噩梦。",
            ["ContentFR"] = "Tu le sais : rien de ce que tu pourrais faire ne changerait son destin.\
Un autre devoir t’attend — rassembler les Lumistellas, et mettre fin à ce cauchemar sans fin.",
            ["DialogueId"] = 6102209,
            ["GUID"] = "0F46B7AA",
            ["NextDialogue"] = 6102210,
            ["RougeTalkActorType"] = 3,
            },
        [6102210] = {
            ["Content"] = "顷刻间，黑色的荆棘蔓延，吞噬了少年的身影。\
你轻轻地叹息一声，继续前进。",
            ["ContentFR"] = "En un instant, les ronces noires surgissent et engloutissent l’enfant.\
Tu pousses un léger soupir... et poursuis ta route.",
            ["DialogueId"] = 6102210,
            ["GUID"] = "0F46B7D4",
            ["RougeTalkActorType"] = 3,
            },
        [6102301] = {
            ["Content"] = "“孩子……快看，这里有一堆篝火。”\
火光的对面，孑然一身的女人微笑着抬起头，火光映出她憔悴的容颜。\
“真暖和呀，谢谢您，好心的陌生人。”",
            ["ContentFR"] = "« Regarde, mon enfant... il y a un feu de camp ici. »\
De l’autre côté des flammes, une femme solitaire relève la tête et sourit. La lumière dévoile son visage émacié.\
« Comme c’est doux... merci, {性别:étranger bienveillant|étrangère bienveillante}. »",
            ["DialogueId"] = 6102301,
            ["GUID"] = "0F46C6C2",
            ["NextOptions"] = {
                [1] = 6102302,
                },
            ["RougeTalkActorType"] = 1,
            ["SpeakNpcId"] = 910005,
            ["SpeakNpcName"] = "RougeLike_Room322_Char01",
            },
        [6102302] = {
            ["Content"] = "询问她所说的孩子在哪里。",
            ["ContentFR"] = "<I>Demander où est son enfant</>",
            ["DialogueId"] = 6102302,
            ["GUID"] = "0F46C6EC",
            ["NextDialogue"] = 6102303,
            ["RougeTalkActorType"] = 2,
            },
        [6102303] = {
            ["Content"] = "“我的孩子就在这里呀，您看。”",
            ["ContentFR"] = "« Mon enfant est juste là... »",
            ["DialogueId"] = 6102303,
            ["GUID"] = "0F46C716",
            ["NextDialogue"] = 6102304,
            ["RougeTalkActorType"] = 1,
            ["SpeakNpcId"] = 910005,
            ["SpeakNpcName"] = "RougeLike_Room322_Char01",
            },
        [6102304] = {
            ["Content"] = "顺着女人示意的方向，你看到了一块半人高的、覆满青苔的岩石。\
在岩石中央偏上的部分，一枚亮闪闪的胸针被镶嵌在石缝间，四周爬满了细密的青苔围绕，如同一颗被埋葬的心。\
女人温柔地爱抚着岩石的表面，对手上沾染的泥土浑然不觉。",
            ["ContentFR"] = "Tu suis son geste. \
Devant toi, une pierre haute comme un enfant, couverte de mousse.\
Près de son sommet, serti dans une fissure, brille un bijou, une broche étincelante, que la verdure enlace comme un cœur enseveli.\
La femme caresse tendrement la surface humide, insensible à la boue qui lui colle aux doigts.",
            ["DialogueId"] = 6102304,
            ["GUID"] = "0F46C740",
            ["NextOptions"] = {
                [1] = 6102305,
                [2] = 6102308,
                },
            ["RougeTalkActorType"] = 3,
            },
        [6102305] = {
            ["Content"] = "指出真相。",
            ["ContentFR"] = "<I>Dire la vérité</>",
            ["DialogueId"] = 6102305,
            ["GUID"] = "0F46C76A",
            ["IsKeyOption"] = true,
            ["NextDialogue"] = 6102306,
            ["RougeTalkActorType"] = 2,
            },
        [6102306] = {
            ["Content"] = "“您在胡说什么？！”\
女人的眼中瞬间升起尖锐的敌意，她紧紧地将那块岩石护在身后，歇斯底里地大叫起来。\
“这就是我的孩子……她就在这里，我再也不会让任何人带走她……不会……”",
            ["ContentFR"] = "« Quelles absurdités dis-tu là ?! »\
Une rage soudaine embrase son regard. Elle s’interpose devant la pierre, la protégeant de tout son corps, et crie d’une voix déchirée :\
« C’est mon enfant… elle est là ! Personne ne me la prendra… jamais ! »",
            ["DialogueId"] = 6102306,
            ["GUID"] = "0F46C794",
            ["NextDialogue"] = 6102307,
            ["RougeTalkActorType"] = 1,
            ["SpeakNpcId"] = 910005,
            ["SpeakNpcName"] = "RougeLike_Room322_Char01",
            },
        [6102307] = {
            ["Content"] = "你一时哑然。\
或许不该戳破这个美梦的，你早知这毫无意义。\
于是你起身离开，将篝火留给了女人和她的“孩子”。与此同时，潜伏在黑暗中的幽影伺机向你袭来——",
            ["ContentFR"] = "Tu restes muet.\
Tu aurais dû savoir que briser ce rêve ne changerait rien.\
Alors tu te relèves et t’éloignes, laissant le feu à la femme et à son \"enfant\".\
Mais dans l’ombre qui guette, un Umbré tapi bondit sur toi—",
            ["DialogueId"] = 6102307,
            ["GUID"] = "0F46C7BE",
            ["RougeTalkActorType"] = 3,
            },
        [6102308] = {
            ["Content"] = "附和她。",
            ["ContentFR"] = "<I>Aller dans son sens</>",
            ["DialogueId"] = 6102308,
            ["GUID"] = "0F46C7E8",
            ["IsKeyOption"] = true,
            ["NextDialogue"] = 6102309,
            ["RougeTalkActorType"] = 2,
            },
        [6102309] = {
            ["Content"] = "“谢谢您。这孩子从小就怕生，但她好像很喜欢您呢。”\
女人语气和蔼，双手仍时不时轻抚那块岩石。\
“您是一个人出门的吗？这可不行，您的家人会担心的……快回家去吧。”",
            ["ContentFR"] = "« Merci... Elle est craintive, mais elle t’apprécie, je le sens. »\
Sa voix est douce, ses mains continuent de caresser machinalement la pierre.\
« Tu es {性别:parti seul|partie seule} ? Ce n’est pas bien... Ta famille doit s’inquiéter. Rentre vite chez toi. »",
            ["DialogueId"] = 6102309,
            ["GUID"] = "0F46C812",
            ["NextDialogue"] = 6102310,
            ["RougeTalkActorType"] = 1,
            ["SpeakNpcId"] = 910005,
            ["SpeakNpcName"] = "RougeLike_Room322_Char01",
            },
        [6102310] = {
            ["Content"] = "你礼貌地向她道谢，随后便起身继续前进。\
女人和她的“孩子”的身影，渐渐模糊在篝火的阴影中。",
            ["ContentFR"] = "Tu la remercies poliment, puis reprends ta route.\
Derrière toi, la femme et son \"enfant\" s’estompent, avalés par les ombres au-delà du cercle de lumière.",
            ["DialogueId"] = 6102310,
            ["GUID"] = "0F46C83C",
            ["RougeTalkActorType"] = 3,
            },
        [6102401] = {
            ["Content"] = "“不见了……不见了……”\
少女睁着空洞的双眼，匍匐在地上摸索着，指甲几乎要嵌入地面。",
            ["ContentFR"] = "« ... disparues... disparues... »\
La jeune fille, les yeux vides, rampe à même le sol, ses doigts griffant la terre, les ongles prêts à s’y briser.",
            ["DialogueId"] = 6102401,
            ["GUID"] = "0F46D72A",
            ["NextOptions"] = {
                [1] = 6102402,
                },
            ["RougeTalkActorType"] = 1,
            ["SpeakNpcId"] = 910005,
            ["SpeakNpcName"] = "RougeLike_Room323_Char01",
            },
        [6102402] = {
            ["Content"] = "询问她在找什么。",
            ["ContentFR"] = "<I>Demander ce qu’elle cherche</>",
            ["DialogueId"] = 6102402,
            ["GUID"] = "0F46D754",
            ["NextDialogue"] = 6102403,
            ["RougeTalkActorType"] = 2,
            },
        [6102403] = {
            ["Content"] = "“我的石头……石头……之前明明就在这里的……”\
她喃喃说着，几乎是绝望地注视着你脚下的篝火。\
“我的火焰……要熄灭了……怎么办……怎么办……”",
            ["ContentFR"] = "« Mes pierres... mes pierres... elles étaient là, juste là... »\
Elle murmure, le désespoir fixé sur le feu de camp à tes pieds.\
« Ma flamme... elle s’éteint... que faire... que faire... »",
            ["DialogueId"] = 6102403,
            ["GUID"] = "0F46D77E",
            ["NextOptions"] = {
                [1] = 6102404,
                [2] = 6102408,
                },
            ["RougeTalkActorType"] = 1,
            ["SpeakNpcId"] = 910005,
            ["SpeakNpcName"] = "RougeLike_Room323_Char01",
            },
        [6102404] = {
            ["Content"] = "帮助她。",
            ["ContentFR"] = "<I>Aider la jeune fille</>",
            ["DialogueId"] = 6102404,
            ["GUID"] = "0F46D7A8",
            ["IsKeyOption"] = true,
            ["NextDialogue"] = 6102405,
            ["RougeTalkActorType"] = 2,
            },
        [6102405] = {
            ["Content"] = "你试着回忆她喜欢的那些石子的模样。虽然不确定它们的来历，但你判断用火焰魔法应该能制造出相似的东西。\
于是你试着利用篝火，凝聚力量——\
顷刻间，金黄色亮闪闪的小石头如同流星一般坠落，互相碰撞发出清脆悦耳的声响。",
            ["ContentFR"] = "Tu essaies de te souvenir de l’éclat de ces pierres qu’elle chérissait. Leur origine t’échappe, mais ton instinct te souffle qu’avec un peu de magie de feu, tu pourrais en recréer.\
Alors, concentrant ton pouvoir dans les flammes du feu de camp...\
En un éclair, de minuscules gemmes dorées chutent comme des étoiles filantes, tintant doucement en heurtant le sol, pures comme des clochettes.",
            ["DialogueId"] = 6102405,
            ["GUID"] = "0F46D7D2",
            ["NextDialogue"] = 6102406,
            ["RougeTalkActorType"] = 3,
            },
        [6102406] = {
            ["Content"] = "“啊……！我的石头——这就是我的石头！谢谢您，神明的使者！”\
少女如获至宝地一颗颗捡起那些石头，小心翼翼地用裙摆兜起来。",
            ["ContentFR"] = "« Ah... ! Mes pierres — ce sont mes pierres ! Merci, messager des dieux ! »\
Elle les ramasse une à une, ravie comme une enfant, les serrant contre elle dans le pli de sa robe.",
            ["DialogueId"] = 6102406,
            ["GUID"] = "0F46D7FC",
            ["NextDialogue"] = 6102407,
            ["RougeTalkActorType"] = 1,
            ["SpeakNpcId"] = 910005,
            ["SpeakNpcName"] = "RougeLike_Room323_Char01",
            },
        [6102407] = {
            ["Content"] = "那些结晶确实和你此前在少女怀中见到的石子一模一样，你不禁开始怀疑它们是否从一开始就是你在某次旅途中不经意间留下的痕迹。\
无论如何，少女已经再次找回了她的“确定”，而你，也必须继续踏上旅途。",
            ["ContentFR"] = "Elles sont identiques aux cristaux que tu avais aperçus autrefois dans ses bras. Tu ne peux t’empêcher de songer : étaient-elles depuis toujours les traces oubliées d’un de tes anciens voyages ?\
Qu’importe. Elle a retrouvé sa \"certitude\". Toi, tu dois poursuivre ton voyage.",
            ["DialogueId"] = 6102407,
            ["GUID"] = "0F46D826",
            ["RougeTalkActorType"] = 3,
            },
        [6102408] = {
            ["Content"] = "告诉她世事本就不可能一直如我们所愿。",
            ["ContentFR"] = "<I>Dire que le monde ne peut pas toujours céder à nos désirs</>",
            ["DialogueId"] = 6102408,
            ["GUID"] = "0F46D850",
            ["IsKeyOption"] = true,
            ["NextDialogue"] = 6102409,
            ["RougeTalkActorType"] = 2,
            },
        [6102409] = {
            ["Content"] = "“我知道……我知道。”\
“所以我已经放弃了……我不再看那些书，不再思考魔法的起源，也不再追问那座塔里有什么了……”\
“现在我想要的只是一片火光而已，连这也不可以吗？”",
            ["ContentFR"] = "« Je sais... je sais. »\
« C’est pour cela que j’ai renoncé... Je n’ouvre plus les livres, je ne questionne plus l’origine de la magie, je ne demande plus ce qui se cache dans la tour... »\
« Tout ce que je veux, maintenant, c’est un peu de lumière... même cela m’est refusé ? »",
            ["DialogueId"] = 6102409,
            ["GUID"] = "0F46D87A",
            ["NextDialogue"] = 6102410,
            ["RougeTalkActorType"] = 1,
            ["SpeakNpcId"] = 910005,
            ["SpeakNpcName"] = "RougeLike_Room323_Char01",
            },
        [6102410] = {
            ["Content"] = "你无言以对。\
少女忽然站了起来，在你来得及做出反应之前，毅然踏进了火焰之中。\
慢慢地，少女的身影与火光融为一体，消失不见。\
你转过身，继续踏上旅途。",
            ["ContentFR"] = "Tu restes muet.\
D’un geste brusque, elle se relève. Avant que tu ne puisses réagir, elle franchit le brasier d’un pas résolu.\
Son corps se fond lentement aux flammes, jusqu’à disparaître.\
Tu détournes ton regard... et continues ta route.",
            ["DialogueId"] = 6102410,
            ["GUID"] = "0F46D8A4",
            ["RougeTalkActorType"] = 3,
            },
        [6102501] = {
            ["Content"] = "篝火安静地燃烧着，这一次你并未看到任何幻象。\
就在你打算离去的时候，地面上一些闪闪发光的东西引起了你的注意——\
那是一些金黄色的小石子，一颗一颗散落在地，仿若坠入凡尘的星星。",
            ["ContentFR"] = "Le feu brûle paisiblement. Cette fois, aucune vision n’y danse.\
Alors que tu t’apprêtes à partir, ton regard s’accroche à de minuscules éclats scintillants—\
De petites pierres dorées, éparpillées sur le sol, pareilles à des étoiles tombées sur la terre.",
            ["DialogueId"] = 6102501,
            ["GUID"] = "0F46E792",
            ["NextOptions"] = {
                [1] = 6102502,
                [2] = 6102506,
                },
            ["RougeTalkActorType"] = 3,
            },
        [6102502] = {
            ["Content"] = "捡起石子扔进火焰中。",
            ["ContentFR"] = "<I>Ramasser les pierres et les jeter dans le feu</>",
            ["DialogueId"] = 6102502,
            ["GUID"] = "0F46E7BC",
            ["IsKeyOption"] = true,
            ["NextDialogue"] = 6102503,
            ["RougeTalkActorType"] = 2,
            },
        [6102503] = {
            ["Content"] = "火焰越烧越旺，然后开始反常地向侧面延伸。\
你谨慎地退后了一步，忽然间，一个身影从火焰中显现出来，你这才看清楚，那向侧面延伸的光芒并非火焰，而是少女的发丝。",
            ["ContentFR"] = "La flamme s’élève, plus vive, puis s’étend étrangement de côté.\
Tu recules d’un pas prudent, soudain, une silhouette surgit du brasier. Ce qui se déploie autour d’elle n’est pas du feu, mais des mèches étincelantes de chevelure.",
            ["DialogueId"] = 6102503,
            ["GUID"] = "0F46E7E6",
            ["NextDialogue"] = 6102504,
            ["RougeTalkActorType"] = 3,
            },
        [6102504] = {
            ["Content"] = "“您好！您发现了我的小石子，是吗？”\
少女从篝火中跳出来，晃了晃脑袋，金色的石子噼里啪啦地坠落在地。\
“我再也不用去外面找了——您看，只要走进这火里，我就可以自己制造小石子了！”",
            ["ContentFR"] = "« Bonjour ! Tu as trouvé mes pierres, n’est-ce pas ? »\
Elle bondit hors du feu, secouant la tête : de ses cheveux jaillissent des fragments dorés qui tintent joyeusement en tombant.\
« Plus besoin de chercher dehors — regarde ! Il me suffit d’entrer dans le feu, et je peux en créer moi-même ! »",
            ["DialogueId"] = 6102504,
            ["GUID"] = "0F46E810",
            ["NextDialogue"] = 6102505,
            ["RougeTalkActorType"] = 1,
            ["SpeakNpcId"] = 910005,
            ["SpeakNpcName"] = "RougeLike_Room324_Char01",
            },
        [6102505] = {
            ["Content"] = "“请原谅我没有时间与您多作寒暄——我还没有收集满一百四十六颗呢。”\
“不过我倒是发现了一些或许对您有用的东西或许，请收下吧，祝您旅途顺利！”\
少女将什么东西塞到你的手中，然后转身消失在了火焰里。",
            ["ContentFR"] = "« Pardonne-moi, je n’ai pas le temps de bavarder, il m’en faut encore cent quarante-six. »\
« Mais tiens, j’ai découvert ceci. Peut-être cela t’aidera-t-il. Prends-le, et que ton voyage soit sûr et rapide ! »\
Elle glisse un objet dans ta main, puis retourne se fondre dans les flammes.",
            ["DialogueId"] = 6102505,
            ["GUID"] = "0F46E83A",
            ["NextDialogue"] = 6102510,
            ["RougeTalkActorType"] = 1,
            ["SpeakNpcId"] = 910005,
            ["SpeakNpcName"] = "RougeLike_Room324_Char01",
            },
        [6102506] = {
            ["Content"] = "安静地观察。",
            ["ContentFR"] = "<I>Observer en silence</>",
            ["DialogueId"] = 6102506,
            ["GUID"] = "0F46E864",
            ["IsKeyOption"] = true,
            ["NextDialogue"] = 6102507,
            ["RougeTalkActorType"] = 2,
            },
        [6102507] = {
            ["Content"] = "火焰仍在静静燃烧，恍惚间，你似乎从中听到了一个声音。",
            ["ContentFR"] = "La flamme continue de brûler, paisible. Dans le murmure du feu, il te semble entendre une voix.",
            ["DialogueId"] = 6102507,
            ["GUID"] = "0F46E88E",
            ["NextDialogue"] = 6102508,
            ["RougeTalkActorType"] = 3,
            },
        [6102508] = {
            ["Content"] = "“是的……是的。我记住了。”\
少女平静而幸福的声音透过火焰传来。\
“疑问要适可而止。火是神明的馈赠，不是物质的反应。就像这些小石子，它们是神明赐予我的宝物，让我能够安然入睡……”",
            ["ContentFR"] = "« Oui... oui. J’ai compris. »\
La voix paisible de la jeune fille résonne, empreinte de douceur.\
« Les questions doivent savoir où s’arrêter. Le feu est un don des dieux, non une réaction de matière. Comme ces petites pierres : des trésors divins, qui m’offrent un sommeil apaisé... »",
            ["DialogueId"] = 6102508,
            ["GUID"] = "0F46E8B8",
            ["NextDialogue"] = 6102509,
            ["RougeTalkActorType"] = 1,
            ["SpeakNpcId"] = 910005,
            ["SpeakNpcName"] = "RougeLike_Room324_Char01",
            },
        [6102509] = {
            ["Content"] = "你沉默地转身离开，一颗石子恰巧滚落在道路前方，你无意间将它踩碎成了粉末。\
神明赐予的宝物，原来如此脆弱。",
            ["ContentFR"] = "Tu tournes les talons sans un mot. Une pierre roule devant toi, ton pas l’écrase en poussière sans que tu y prennes garde.\
Ainsi donc, les trésors des dieux... sont aussi fragiles.",
            ["DialogueId"] = 6102509,
            ["GUID"] = "0F46E8E2",
            ["NextDialogue"] = 6102510,
            ["RougeTalkActorType"] = 3,
            },
        [6102510] = {
            ["Content"] = "你忽然想，那片火焰到底是为少女带来幸福的“确定”，还是将她永远困在这里的“枷锁”呢？\
或许，这二者本来就没什么区别。",
            ["ContentFR"] = "Et tu songes : cette flamme était-elle la \"certitude\" de son bonheur, ou bien le \"carcan\" qui la retient prisonnière ?\
Peut-être n’y a-t-il jamais eu de différence.",
            ["DialogueId"] = 6102510,
            ["GUID"] = "0F46E90C",
            ["RougeTalkActorType"] = 3,
            },
        [6102601] = {
            ["Content"] = "“对不起，都是我的错……我太笨了，记不全圣歌……我太懒了，没有坚持听完布道……”\
“神明大人，请原谅我……”",
            ["ContentFR"] = "« Pardon... tout est ma faute... Je suis trop bête, je n’ai pas retenu les hymnes... Trop paresseuse pour écouter les sermons jusqu’au bout... »\
« Ô dieux... pardonnez-moi... »",
            ["DialogueId"] = 6102601,
            ["GUID"] = "0F46F7FA",
            ["NextDialogue"] = 6102602,
            ["RougeTalkActorType"] = 1,
            ["SpeakNpcId"] = 910005,
            ["SpeakNpcName"] = "RougeLike_Room325_Char01",
            },
        [6102602] = {
            ["Content"] = "女孩旁若无人地忏悔着——又或许，是她已经看不见旁人了。\
她的病情看上去比上次更加糟糕，连双眼都变得黯淡无光。",
            ["ContentFR"] = "Elle confesse dans le vide, ou peut-être ne distingue-t-elle plus les vivants.\
Elle paraît encore plus affaiblie que la dernière fois : ses yeux eux-mêmes se sont ternis.",
            ["DialogueId"] = 6102602,
            ["GUID"] = "0F46F824",
            ["NextDialogue"] = 6102603,
            ["RougeTalkActorType"] = 3,
            },
        [6102603] = {
            ["Content"] = "“您是……那位旅人……已经……过去很久了吗？”\
女孩终于注意到你，慢慢地转过头来。\
“旅人……请您告诉我……为什么，我日夜不停地向神明祈祷，神明却从来不回应我？”",
            ["ContentFR"] = "« Vous... {性别:le voyageur|la voyageuse}... déjà... tant de temps passé ? »\
Enfin, elle vous aperçoit, sa tête se tourne avec lenteur.\
« {性别:Voyageur|Voyageuse}... dites-moi... pourquoi ? Pourquoi, malgré mes prières jour et nuit, les dieux ne me répondent-ils jamais ? »",
            ["DialogueId"] = 6102603,
            ["GUID"] = "0F46F84E",
            ["NextOptions"] = {
                [1] = 6102604,
                [2] = 6102608,
                },
            ["RougeTalkActorType"] = 1,
            ["SpeakNpcId"] = 910005,
            ["SpeakNpcName"] = "RougeLike_Room325_Char01",
            },
        [6102604] = {
            ["Content"] = "鼓励她继续祈祷。",
            ["ContentFR"] = "<I>Encourager à continuer de prier</>",
            ["DialogueId"] = 6102604,
            ["GUID"] = "0F46F878",
            ["IsKeyOption"] = true,
            ["NextDialogue"] = 6102605,
            ["RougeTalkActorType"] = 2,
            },
        [6102605] = {
            ["Content"] = "既然还没到改写结局的时刻，那么将谎言延续下去也无妨……至少，那也是一种“希望”。\
你告诉她，只要继续祈祷，总有一天你们都能得到拯救。\
这不完全是谎话——你相信深渊终会被战胜，只不过她的祈祷无关紧要，真正的答案在于你手中的这盏提灯。",
            ["ContentFR"] = "Ce n’est pas encore l’heure de réécrire son destin. Alors, tu prolonges le mensonge, car parfois, un mensonge est encore une forme d’espérance.\
Tu lui assures que si elle continue de prier, un jour, le salut viendra.\
Et ce n’est pas tout à fait faux : tu crois que l’Abysse sera vaincue. Mais ses prières n’y changeront rien. La vérité repose non dans le rite, mais dans la lanterne que tu tiens.",
            ["DialogueId"] = 6102605,
            ["GUID"] = "0F46F8A2",
            ["NextDialogue"] = 6102606,
            ["RougeTalkActorType"] = 3,
            },
        [6102606] = {
            ["Content"] = "“我明白了……我相信您。”\
女孩双手交握，继续低声祈祷，声音中多出了几分坚定。",
            ["ContentFR"] = "« Je comprends... Je vous crois. »\
Elle joint les mains et reprend sa prière, sa voix plus ferme.",
            ["DialogueId"] = 6102606,
            ["GUID"] = "0F46F8CC",
            ["NextDialogue"] = 6102607,
            ["RougeTalkActorType"] = 1,
            ["SpeakNpcId"] = 910005,
            ["SpeakNpcName"] = "RougeLike_Room325_Char01",
            },
        [6102607] = {
            ["Content"] = "你轻叹了一口气，握紧手中的提灯，继续前行。",
            ["ContentFR"] = "Tu pousses un soupir discret, serres la lanterne, et reprends ta marche.",
            ["DialogueId"] = 6102607,
            ["GUID"] = "0F46F8F6",
            ["RougeTalkActorType"] = 3,
            },
        [6102608] = {
            ["Content"] = "告诉她神明不会回应。",
            ["ContentFR"] = "<I>Dire que les dieux ne répondent pas</>",
            ["DialogueId"] = 6102608,
            ["GUID"] = "0F46F920",
            ["IsKeyOption"] = true,
            ["NextDialogue"] = 6102609,
            ["RougeTalkActorType"] = 2,
            },
        [6102609] = {
            ["Content"] = "“神明……不会回应我吗？”\
“是因为我的罪孽太深，已经不值得拯救了吗？”\
女孩绝望地看着你，泪水顺着她布满脓疮的脸颊滑落。",
            ["ContentFR"] = "« Les dieux... ne me répondront pas ?\
Est-ce à cause de mes péchés ? Parce que je ne mérite pas d’être sauvée ? »\
Ses yeux se noient de désespoir, des larmes glissent sur ses joues couvertes de plaies.",
            ["DialogueId"] = 6102609,
            ["GUID"] = "0F46F94A",
            ["NextOptions"] = {
                [1] = 6102610,
                },
            ["RougeTalkActorType"] = 1,
            ["SpeakNpcId"] = 910005,
            ["SpeakNpcName"] = "RougeLike_Room325_Char01",
            },
        [6102610] = {
            ["Content"] = "“是因为你本来就没有罪。”",
            ["ContentFR"] = "<I>« Parce que tu n’as jamais péché. »</>",
            ["DialogueId"] = 6102610,
            ["GUID"] = "0F46F974",
            ["NextDialogue"] = 6102611,
            ["RougeTalkActorType"] = 2,
            },
        [6102611] = {
            ["Content"] = "“咦……？”\
女孩愣住了，眼中浮现出深深的困惑。",
            ["ContentFR"] = "« Hein... ? »\
Elle reste figée, la confusion dans le regard.",
            ["DialogueId"] = 6102611,
            ["GUID"] = "0F46F99E",
            ["NextDialogue"] = 6102612,
            ["RougeTalkActorType"] = 1,
            ["SpeakNpcId"] = 910005,
            ["SpeakNpcName"] = "RougeLike_Room325_Char01",
            },
        [6102612] = {
            ["Content"] = "你对她露出一个坚定的微笑，告诉她，你一定会找到办法结束她的痛苦。\
女孩看着你，似懂非懂地点了点头。这时你注意到，她的伤口不再流血了。\
于是，你向她挥手作别，握紧手中的提灯，继续前行。",
            ["ContentFR"] = "Tu lui offres un sourire résolu, promettant que tu trouveras un moyen de mettre fin à sa souffrance.\
Elle acquiesce vaguement... et tu remarques alors que ses plaies ne saignent plus.\
Tu lui fais un signe d’adieu, serres la lanterne... et reprends ton chemin.",
            ["DialogueId"] = 6102612,
            ["GUID"] = "0F46F9C8",
            ["RougeTalkActorType"] = 3,
            },
        [6102701] = {
            ["Content"] = "“芙萨，满月女神——\
“辉光足迹的主宰，命运丝线的编织者……\
“穹顶与月华为证，虔信颂歌向你献上……”",
            ["ContentFR"] = "« Fusa, Déesse de la Pleine Lune — »\
« Souveraine des sentiers radieux, tisseuse des fils du destin... »\
« Sous la coupole céleste et dans l’éclat de la lune, reçois notre hymne fervent... »",
            ["DialogueId"] = 6102701,
            ["GUID"] = "0F470862",
            ["NextDialogue"] = 6102702,
            ["RougeTalkActorType"] = 1,
            ["SpeakNpcId"] = 910005,
            ["SpeakNpcName"] = "RougeLike_Room326_Char01",
            },
        [6102702] = {
            ["Content"] = "人们的身形自火中浮现，他们齐声念着献给神明的祷言。",
            ["ContentFR"] = "Des silhouettes se dressent dans le feu, leurs voix unies en une prière solennelle.",
            ["DialogueId"] = 6102702,
            ["GUID"] = "0F47088C",
            ["NextDialogue"] = 6102703,
            ["RougeTalkActorType"] = 3,
            },
        [6102703] = {
            ["Content"] = "“你是谁？一位迷路的旅人？”\
一位祈祷者看见了你，她笑着向你伸出手。\
“与我们一起向满月女神祈祷吧，祂定会为你的前路赐福！”",
            ["ContentFR"] = "« Qui es-tu ? {性别:Un voyageur égaré|Une voyageuse égarée} ? »\
L’une d’elles se tourne vers toi, un doux sourire aux lèvres, la main tendue.\
« Viens prier avec nous la Déesse de la Pleine Lune. Elle bénira sûrement ton chemin. »",
            ["DialogueId"] = 6102703,
            ["GUID"] = "0F4708B6",
            ["NextDialogue"] = 6102704,
            ["RougeTalkActorType"] = 1,
            ["SpeakNpcId"] = 910005,
            ["SpeakNpcName"] = "RougeLike_Room326_Char01",
            },
        [6102704] = {
            ["Content"] = "他们的颂歌献给<H>第九位神明</>，命运之神<H>芙萨</>。\
祂是满月的主宰，祂抽引月华，织成命运之线。",
            ["ContentFR"] = "Ils élèvent leur chant vers <H>Fusa</>, Déesse du Destin, la <H>Neuvième des Divinités</>.\
Maîtresse de la pleine lune, elle tire à elle l’argent de sa lumière pour en tresser les fils du destin.",
            ["DialogueId"] = 6102704,
            ["GUID"] = "0F4708E0",
            ["NextOptions"] = {
                [1] = 6102705,
                [2] = 6102709,
                },
            ["RougeTalkActorType"] = 3,
            },
        [6102705] = {
            ["Content"] = "加入他们的祈祷。",
            ["ContentFR"] = "<I>Joindre ta voix à leur prière</>",
            ["DialogueId"] = 6102705,
            ["GUID"] = "0F47090A",
            ["IsKeyOption"] = true,
            ["NextDialogue"] = 6102706,
            ["RougeTalkActorType"] = 2,
            },
        [6102706] = {
            ["Content"] = "这是幼时的你最不喜欢的场合。你不喜欢那些空洞的溢美之词，背下来转头就忘记。但如今，你却生出一丝怀念。\
你加入了他们的祈祷。",
            ["ContentFR"] = "C’était le genre d’assemblée que tu détestais enfant, ces louanges creuses, apprises par cœur et vite oubliées.\
Pourtant, une étrange nostalgie t’envahit.\
Tu baisses la tête et te joins à leur prière.",
            ["DialogueId"] = 6102706,
            ["GUID"] = "0F470934",
            ["NextDialogue"] = 6102707,
            ["RougeTalkActorType"] = 3,
            },
        [6102707] = {
            ["Content"] = "“芙萨，命运无序乱流中恒常划过天幕的满月之神。\
“向你致敬，愿你护佑你的信徒，\
“赐予我们无可挑剔的…………幸运与幸福。”",
            ["ContentFR"] = "« Fusa, Déesse de la Pleine Lune, constante à travers les cieux, au sein des flux et reflux du destin... »\
« À toi, nous rendons hommage. Protège tes fidèles... »\
« Accorde-nous une félicité sans ombre. »",
            ["DialogueId"] = 6102707,
            ["GUID"] = "0F47095E",
            ["NextDialogue"] = 6102708,
            ["RougeTalkActorType"] = 2,
            ["SpeakNpcId"] = 910004,
            },
        [6102708] = {
            ["Content"] = "你闭上双眼，跟着虔诚的信众默念。\
最后一句念完，你睁开眼，他们的身影已经消失不见。",
            ["ContentFR"] = "Les yeux clos, tu reprends en silence la dévotion des croyants.\
Quand tu les rouvres, leurs silhouettes se sont évanouies.",
            ["DialogueId"] = 6102708,
            ["GUID"] = "0F470988",
            ["RougeTalkActorType"] = 3,
            },
        [6102709] = {
            ["Content"] = "不愿加入他们的祈祷。",
            ["ContentFR"] = "<I>Refuser leur prière</>",
            ["DialogueId"] = 6102709,
            ["GUID"] = "0F4709B2",
            ["IsKeyOption"] = true,
            ["NextDialogue"] = 6102710,
            ["RougeTalkActorType"] = 2,
            },
        [6102710] = {
            ["Content"] = "“拒绝？你——为什么？”\
祈祷者尖利地叫出声。\
“异端者——莫非你是暗月派的信徒？涅法的追随者？”",
            ["ContentFR"] = "« Refuser ? Mais... pourquoi ? »\
Sa voix s’éraille, se fait tranchante.\
« Hérétique ! Serais-tu {性别:un|une} adepte du Noctilunisme ? {性别:Un|Une} disciple de Nepha ? »",
            ["DialogueId"] = 6102710,
            ["GUID"] = "0F4709DC",
            ["NextDialogue"] = 6102711,
            ["RougeTalkActorType"] = 1,
            ["SpeakNpcId"] = 910005,
            ["SpeakNpcName"] = "RougeLike_Room326_Char01",
            },
        [6102711] = {
            ["Content"] = "听到那个禁忌的名字，信徒们齐齐转过脸来，他们的面孔变得扭曲而狰狞。\
你叹了口气——你得想办法从他们的团团包围中抽身了。",
            ["ContentFR"] = "À ce nom interdit, tous les regards se braquent sur toi. Leurs visages se distordent, se muant en masques hideux de haine.\
Tu soupires : impossible d’éviter le combat. Il te faut briser le cercle qui t’oppresse.",
            ["DialogueId"] = 6102711,
            ["GUID"] = "0F470A06",
            ["RougeTalkActorType"] = 3,
            },
        [6102801] = {
            ["Content"] = "“命运纺线之剪，永恒寂静的主宰者……\
“深渊与长夜为证，请聆听我卑微的祷言……”",
            ["ContentFR"] = "« Ô ciseaux qui tranchent le fil du destin, souveraine du silence éternel... »\
« Par l’Abysse et la longue nuit pour témoins, écoute ma prière... »",
            ["DialogueId"] = 6102801,
            ["GUID"] = "0F4718CA",
            ["NextDialogue"] = 6102802,
            ["RougeTalkActorType"] = 1,
            ["SpeakNpcId"] = 910005,
            ["SpeakNpcName"] = "RougeLike_Room327_Char01",
            },
        [6102802] = {
            ["Content"] = "人们的身形自火中浮现，他们齐声念着献给神明的祷言。\
你静静聆听着。那是你并不熟悉的祷文。",
            ["ContentFR"] = "À nouveau, des silhouettes surgissent des flammes, récitant en chœur une litanie que tu ne connais pas.",
            ["DialogueId"] = 6102802,
            ["GUID"] = "0F4718F4",
            ["NextDialogue"] = 6102803,
            ["RougeTalkActorType"] = 3,
            },
        [6102803] = {
            ["Content"] = "“你是谁？一位迷路的旅人？”\
一位祈祷者看见了你，她笑着向你伸出手。\
“还是说，你也同样窥破了天机，想要同我们一起投入真正的救主——涅法的怀抱？”",
            ["ContentFR"] = "« Qui es-tu ? {性别:Un voyageur égaré|Une voyageuse égarée} ? »\
Une fidèle t’aperçoit, elle sourit et te tend la main.\
« Ou bien as-tu, toi aussi, entrevu la vérité cachée, et viens-tu chercher l’étreinte de la véritable salvatrice — Nepha ? »",
            ["DialogueId"] = 6102803,
            ["GUID"] = "0F47191E",
            ["NextDialogue"] = 6102804,
            ["RougeTalkActorType"] = 1,
            ["SpeakNpcId"] = 910005,
            ["SpeakNpcName"] = "RougeLike_Room327_Char01",
            },
        [6102804] = {
            ["Content"] = "<H>涅法</>——你记得这个名字。\
它不常出现在艾利西安正教信众的笔下，你只在尘封的古老尺牍间见过这个名字。这是一个禁忌的名字，早已被遗忘的<H>第十位神明</>。",
            ["ContentFR"] = "<H>Nepha</>... tu te souviens.\
Un nom absent des textes orthodoxes d’Élysium, à peine lisible dans de vieux manuscrits effacés par le temps.\
Un nom interdit : la <H>Dixième Divinité</> oubliée.",
            ["DialogueId"] = 6102804,
            ["GUID"] = "0F471948",
            ["NextDialogue"] = 6102805,
            ["RougeTalkActorType"] = 3,
            },
        [6102805] = {
            ["Content"] = "祂是满月与命运之神芙萨的姊妹，暗月与死亡之神。\
她的同胞姐姐纺织命运丝线，她则剪断命运。\
两位神明无休止的争斗带来月相盈虚，卷动潮汐。\
那么，祂的信徒，便应该是……",
            ["ContentFR"] = "Sœur cadette de Fusa, Déesse de la Pleine Lune et du Destin, Nepha est la Déesse de la Lune Noire et de la Mort.\
L’aînée tisse le fil, la cadette le tranche.\
De leur lutte sans fin sont nés les cycles de la lune, le flux des marées.\
Et si ces gens la vénèrent, alors ce sont des...",
            ["DialogueId"] = 6102805,
            ["GUID"] = "0F471972",
            ["NextOptions"] = {
                [1] = 6102806,
                },
            ["RougeTalkActorType"] = 3,
            },
        [6102806] = {
            ["Content"] = "询问他们的信仰。",
            ["ContentFR"] = "<I>Demander leur foi</>",
            ["DialogueId"] = 6102806,
            ["GUID"] = "0F47199C",
            ["NextDialogue"] = 6102807,
            ["RougeTalkActorType"] = 2,
            },
        [6102807] = {
            ["Content"] = "“既然出现在这儿，你应该已经知晓，这片深渊不是死物。它活着，不断生长，不断延伸。\
“骑士团的黄金圣剑无法击退黑暗的浪潮，满月的光辉不能穿透幽邃的寂静。\
“正如一切光芒都向着熄灭飞驰，一切活物都终有一死——消亡是唯一可以确定的东西。我们的深渊，才是世界本真的模样。\
“欢迎加入<H>暗月教派</>，亲爱的旅人。”",
            ["ContentFR"] = "« Si tu es ici, tu le sais déjà : l’Abysse n’est pas un gouffre mort. Il vit, il croît, il s’étend sans fin.\
Ni l’épée sacrée des chevaliers, ni la lumière de la Pleine Lune ne peuvent retenir sa marée obscure.\
Toute lumière court vers son extinction, toute vie vers sa fin. La seule certitude, c’est la disparition. L’Abysse est la vraie forme du monde.\
Bienvenue, {性别:cher voyageur|chère voyageuse}, parmi les fidèles du <H>Noctilunisme</>. »",
            ["DialogueId"] = 6102807,
            ["GUID"] = "0F4719C6",
            ["NextOptions"] = {
                [1] = 6102808,
                [2] = 6102811,
                },
            ["RougeTalkActorType"] = 1,
            ["SpeakNpcId"] = 910005,
            ["SpeakNpcName"] = "RougeLike_Room327_Char02",
            },
        [6102808] = {
            ["Content"] = "回应他们的邀请。",
            ["ContentFR"] = "<I>Accepter à leur invitation</>",
            ["DialogueId"] = 6102808,
            ["GUID"] = "0F4719F0",
            ["IsKeyOption"] = true,
            ["NextDialogue"] = 6102809,
            ["RougeTalkActorType"] = 2,
            },
        [6102809] = {
            ["Content"] = "即使只是虚影，你也不想触怒他们，增加无谓的纠缠。\
于是你开始煞有介事地复述起你听过的那些关于暗月教派的传言——“死亡的本能”啦，“涅法的救赎”啦，“深渊即永恒”啦……人们的脸上露出微笑，他们不住地点头，附和起你的高谈阔论。",
            ["ContentFR"] = "Même face à de simples spectres, tu n’as nulle envie de provoquer de nouveaux conflits.\
Alors tu prends un air grave et récites quelques bribes des dogmes du Noctilunisme que tu avais vaguement entendues : « L’instinct de mort »... « La rédemption de Nepha »... « L’Abysse est l’éternité »...\
Leurs traits se détendent, ils hochent la tête avec approbation, séduits par tes paroles.",
            ["DialogueId"] = 6102809,
            ["GUID"] = "0F471A1A",
            ["NextDialogue"] = 6102810,
            ["RougeTalkActorType"] = 3,
            },
        [6102810] = {
            ["Content"] = "“你的博学令我们感叹，你的智慧令我们折服。请收下这些礼物吧，陌生的朋友！”\
你蒙混过关了。还好，你并非少时的每一场布道和论辩都在走神。",
            ["ContentFR"] = "« Ton savoir nous impressionne, ta sagesse nous subjugue. Reçois ces présents, {性别:ami inconnu|amie inconnue} ! »\
Tu as su les tromper. Finalement, toutes les sermons de ton enfance ne t’étaient pas inutiles.",
            ["DialogueId"] = 6102810,
            ["GUID"] = "0F471A44",
            ["RougeTalkActorType"] = 1,
            ["SpeakNpcId"] = 910005,
            ["SpeakNpcName"] = "RougeLike_Room327_Char02",
            },
        [6102811] = {
            ["Content"] = "拒绝他们的邀请。",
            ["ContentFR"] = "<I>Refuser leur invitation</>",
            ["DialogueId"] = 6102811,
            ["GUID"] = "0F471A6E",
            ["IsKeyOption"] = true,
            ["NextDialogue"] = 6102812,
            ["RougeTalkActorType"] = 2,
            },
        [6102812] = {
            ["Content"] = "在这场漫长的苦旅中，你也曾多次思考过生的意义，死的意义。你也曾相信死亡便是唯一的解。\
但<H>那几次意外的相逢</>让你坚定了你无数次行走在黑暗中的意义——\
你要驱散这片黑暗，以自己的躯壳为薪柴。即使只是短暂的光，你也将灼烧这片凝滞的不朽。",
            ["ContentFR"] = "Au long de ta route, toi aussi, tu as souvent songé au sens de la vie, au sens de la mort. Parfois, tu as cru que la mort était la seule délivrance.\
Mais ces rencontres imprévues ont rallumé en toi la raison de marcher encore dans les ténèbres.\
Tu brûleras ton propre corps comme bûche, s’il le faut, pour illuminer ce monde figé. Même l’espace d’un instant, tu brilleras contre l’éternité morte.",
            ["DialogueId"] = 6102812,
            ["GUID"] = "0F471A98",
            ["NextDialogue"] = 6102813,
            ["RougeTalkActorType"] = 3,
            },
        [6102813] = {
            ["Content"] = "“深渊并非永恒，你们只是生者留下的虚影。\
你举起武器。\
“回到你该去的地方吧，亡者们——”",
            ["ContentFR"] = "« L’Abysse n’est pas éternité. Vous n’êtes que des échos, ombres d’êtres disparus. »\
Tu lèves ton arme.\
« Retournez là où est votre place, âmes des trépassés— »",
            ["DialogueId"] = 6102813,
            ["GUID"] = "0F471AC2",
            ["RougeTalkActorType"] = 2,
            ["SpeakNpcId"] = 910004,
            },
        [6102901] = {
            ["Content"] = "你在篝火旁坐下休息。\
忽然间，你注意到了一种奇怪的响声。一开始它好像就在你耳畔，然后渐渐远了一点，移到了头顶。\
声音越来越响，窸窸窣窣，似乎是某种柔软的东西在互相摩擦。",
            ["ContentFR"] = "Tu t’assieds près du feu pour te reposer.\
Soudain, un bruit étrange effleure ton oreille... puis s’éloigne, monte au-dessus de ta tête.\
Il enfle, de plus en plus clair : un froissement doux, comme des ailes de velours qui se frôlent.",
            ["DialogueId"] = 6102901,
            ["GUID"] = "0F472932",
            ["NextDialogue"] = 6102902,
            ["RougeTalkActorType"] = 3,
            },
        [6102902] = {
            ["Content"] = "“嗨！幸运的旅人！”",
            ["ContentFR"] = "« Hé ! {性别:Petit veinard|Petite veinarde} ! »",
            ["DialogueId"] = 6102902,
            ["GUID"] = "0F47295C",
            ["NextDialogue"] = 6102903,
            ["RougeTalkActorType"] = 1,
            ["SpeakNpcId"] = 910005,
            ["SpeakNpcName"] = "RougeLike_Room381_Char01",
            },
        [6102903] = {
            ["Content"] = "色彩斑斓的羽毛从头顶落下来。你从来没有一次在深渊里同时看到这么多颜色。\
现在，你被包围在一地羽毛中间，好像被街头玩整蛊游戏的小家伙们偶然选中的倒霉路人，尴尬中还透着一丝微妙的可悲。",
            ["ContentFR"] = "Une pluie de plumes chatoyantes descend sur toi. Jamais, dans l’Abysse, tu n’as vu autant de couleurs à la fois.\
Bientôt, tu te retrouves enseveli sous cet amas bariolé, ridicule pantin d’une farce de rue, oscillant entre le comique et le pathétique.",
            ["DialogueId"] = 6102903,
            ["GUID"] = "0F472986",
            ["NextDialogue"] = 6102904,
            ["RougeTalkActorType"] = 3,
            },
        [6102904] = {
            ["Content"] = "“我说，你怎么一点反应也没有？你在深渊里待这么久了，不觉得无聊吗？”\
戴着滑稽的鸟头面具的人从上方倒立着缓缓降落下来，让自己的视线与你齐平。\
你不知道他是怎么保持这个动作的，但这不重要，重要的是他面具上的尖嘴快要戳到你的脸了。",
            ["ContentFR"] = "« Quoi, pas de réaction ? Tu traînes ici depuis si longtemps... tu ne t’ennuies pas ? »\
Un homme avec un masque grotesque d’oiseau apparaît, suspendu la tête en bas.\
Il descend lentement jusqu’à ce que ses yeux soient au même niveau que les tiens.\
Comment il tient cette posture, tu n’en sais rien. Mais ce qui compte, c’est que le bec de son masque vacille dangereusement, prêt à heurter ton visage.",
            ["DialogueId"] = 6102904,
            ["GUID"] = "0F4729B0",
            ["NextOptions"] = {
                [1] = 6102905,
                },
            ["RougeTalkActorType"] = 1,
            ["SpeakNpcId"] = 910005,
            ["SpeakNpcName"] = "RougeLike_Room381_Char01",
            },
        [6102905] = {
            ["Content"] = "我没空陪你胡闹。",
            ["ContentFR"] = "<I>« Je n’ai pas le temps de jouer. »</>",
            ["DialogueId"] = 6102905,
            ["GUID"] = "0F4729DA",
            ["NextDialogue"] = 6102906,
            ["RougeTalkActorType"] = 2,
            },
        [6102906] = {
            ["Content"] = "“别这么冷淡嘛，传颂会的老家伙们应该教过你吧，日行一善会有好报的。”\
“跟我<H>玩个游戏</>，赢了就给你奖励，输了也没有惩罚。稳赚不赔，怎么样？”",
            ["ContentFR"] = "« Allons, ne sois pas si {性别:froid|froide}. Les vieux de l’Église Élyséenne ne t’ont-ils pas appris ? Une bonne action chaque jour attire la chance !\
Allez, <H>joue avec moi</>. Si tu gagnes, je t’offre une récompense, si tu perds... rien du tout. Pas de punition. Alors ? »",
            ["DialogueId"] = 6102906,
            ["GUID"] = "0F472A04",
            ["NextOptions"] = {
                [1] = 6102907,
                },
            ["RougeTalkActorType"] = 1,
            ["SpeakNpcId"] = 910005,
            ["SpeakNpcName"] = "RougeLike_Room381_Char01",
            },
        [6102907] = {
            ["Content"] = "好吧。",
            ["ContentFR"] = "<I>« D’accord. »</>",
            ["DialogueId"] = 6102907,
            ["GUID"] = "0F472A2E",
            ["IsKeyOption"] = true,
            ["RougeTalkActorType"] = 2,
            },
        [6103001] = {
            ["Content"] = "“哦，让我们唱一首歌儿给<H>沙利叶</>吧！\
“他是艾利西安的圣者。\
“他聆听芙萨的启示，教给世人慈悲、宽恕与爱，\
“让那朱红的艾利西安大地，重绽和平的新枝。”",
            ["ContentFR"] = "« Ô, chantons un hymne à <H>Shaliel</> !\
« Il est le Saint d’Élysium. »\
« Il reçut les révélations de Fusa, enseigna aux hommes miséricorde, pardon et amour,\
et fit refleurir, sur la terre cramoisie d’Élysium, les jeunes rameaux de la paix. »",
            ["DialogueId"] = 6103001,
            ["GUID"] = "0F47399A",
            ["NextDialogue"] = 6103002,
            ["RougeTalkActorType"] = 1,
            ["SpeakNpcId"] = 910005,
            ["SpeakNpcName"] = "RougeLike_Room328_Char01",
            },
        [6103002] = {
            ["Content"] = "你看到一位吟游诗人打扮的老者正摩挲着一截断壁。\
这处断壁相对完整，借着微弱的灯光，你看到了一幅巨大的壁画，画的正是诗人口中的<H>沙利叶</>。\
两千年的圣者，最初的<H>七美德</>之一，“节制”席。\
诗人径自唱着歌，对你的到来充耳不闻。",
            ["ContentFR"] = "Un vieil homme, vêtu en ménestrel, caresse du bout des doigts une paroi brisée.\
Malgré ses fissures, le mur demeure intact : à la lueur de ta lanterne, une fresque se révèle, immense — l’image même de <H>Shaliel</> que le poète exalte.\
Saint de deux millénaires passés, premier siège des <H>Sept Vertus</>, celui de la Tempérance.\
Le poète chante sans fin, ignorant ta présence.",
            ["DialogueId"] = 6103002,
            ["GUID"] = "0F4739C4",
            ["NextOptions"] = {
                [1] = 6103003,
                },
            ["RougeTalkActorType"] = 3,
            },
        [6103003] = {
            ["Content"] = "继续听下去。",
            ["ContentFR"] = "<I>Continuer d’écouter</>",
            ["DialogueId"] = 6103003,
            ["GUID"] = "0F4739EE",
            ["NextDialogue"] = 6103004,
            ["RougeTalkActorType"] = 2,
            },
        [6103004] = {
            ["Content"] = "“但圣者的心却始终因一事而痛楚，\
“那便是芙萨给世人的应许，那众天之天。\
“终于有一天，他在碧波之畔静坐七十又七日后，\
“他于满月之下洞悉真理，于湖中抵达永恒。”",
            ["ContentFR"] = "« Mais le cœur du Saint demeurait blessé, par la promesse que Fusa fit aux mortels — le Paradis des Paradis. »\
« Et lorsqu’un jour, au bord des flots d’azur, il demeura soixante-dix-sept jours en silence, sous la pleine lune il contempla la vérité, et dans les eaux sacrées, il toucha l’Éternité. »",
            ["DialogueId"] = 6103004,
            ["GUID"] = "0F473A18",
            ["NextDialogue"] = 6103005,
            ["RougeTalkActorType"] = 1,
            ["SpeakNpcId"] = 910005,
            ["SpeakNpcName"] = "RougeLike_Room328_Char01",
            },
        [6103005] = {
            ["Content"] = "你知道他在唱什么。\
沙利叶在湖畔得到满月与命运女神芙萨的启示，他的灵魂从此前往众天之天，得到了“永恒”。他也成为第一位“神选者”。\
自他之后，又陆续有人身上显现出圣痕，那是被神选中的徽记。他们陆续经由圣湖，抵达应许之地。\
这些早期传颂会历史你并不陌生。",
            ["ContentFR"] = "Tu comprends son chant.\
Au bord du lac, Shaliel reçut la révélation de Fusa, Déesse du Destin. Son âme quitta ce monde pour le Paradis des Paradis, atteignant l’Éternité. Ainsi devint-il le premier Élu.\
D’autres ensuite portèrent la marque divine, le stigmate des dieux. Un à un, ils traversèrent le Lac Sacré et gagnèrent la terre promise.\
Ces récits des premiers temps de l’Église d’Élysium, tu les connais bien.",
            ["DialogueId"] = 6103005,
            ["GUID"] = "0F473A42",
            ["NextOptions"] = {
                [1] = 6103006,
                },
            ["RougeTalkActorType"] = 3,
            },
        [6103006] = {
            ["Content"] = "继续听下去。",
            ["ContentFR"] = "<I>Continuer d’écouter</>",
            ["DialogueId"] = 6103006,
            ["GUID"] = "0F473A6C",
            ["NextDialogue"] = 6103007,
            ["RougeTalkActorType"] = 2,
            },
        [6103007] = {
            ["Content"] = "“可两千年后，当我站在起伏的山峦凝望圣湖，\
“为何那里只剩下漆黑的漩涡？\
“沙利叶啊，我们智慧的圣者——\
“告诉我，女神应许的乐园究竟在何处？”",
            ["ContentFR"] = "« Et pourtant, deux mille ans plus tard, quand je contemple, des collines, le Lac Sacré,\
pourquoi n’y reste-t-il qu’un gouffre noir et tourbillonnant ? »\
« Ô Shaliel, Saint de la Sagesse, dis-moi : où donc se trouve le paradis qu’avait promis la Déesse ? »",
            ["DialogueId"] = 6103007,
            ["GUID"] = "0F473A96",
            ["NextDialogue"] = 6103008,
            ["RougeTalkActorType"] = 1,
            ["SpeakNpcId"] = 910005,
            ["SpeakNpcName"] = "RougeLike_Room328_Char01",
            },
        [6103008] = {
            ["Content"] = "诗人边唱着，边落下泪来。他终于从遥远的历史，唱到了眼前的现在——这片幽暗的深渊。\
不知从何时起，传颂会两千年来最神圣洁净的圣湖，一夜之间突然为这污浊的混沌所取代。\
就像一千年前那些弃教的堕落者所言的那样——“九神已死！”\
要继续听下去吗？",
            ["ContentFR"] = "Le poète pleure en chantant.\
Son récit glisse de la gloire passée à l’abîme présent.\
Nul ne sait quand cela commença — une nuit, sans prévenir, le Lac Sacré, jadis le plus pur sanctuaire des fidèles d’Élysium, fut englouti par l’Abysse.\
Comme l’avaient clamé les apostats mille ans plus tôt : « Les Neuf Dieux sont morts ! »\
Continuer d’écouter ?",
            ["DialogueId"] = 6103008,
            ["GUID"] = "0F473AC0",
            ["NextOptions"] = {
                [1] = 6103009,
                [2] = 6103013,
                },
            ["RougeTalkActorType"] = 3,
            },
        [6103009] = {
            ["Content"] = "继续听下去。",
            ["ContentFR"] = "<I>Continuer d’écouter</>",
            ["DialogueId"] = 6103009,
            ["GUID"] = "0F473AEA",
            ["IsKeyOption"] = true,
            ["NextDialogue"] = 6103010,
            ["RougeTalkActorType"] = 2,
            },
        [6103010] = {
            ["Content"] = "“为何那秽浊的深渊没有言语？\
“那满月的银辉遍照我身，为何女神不曾回答？\
“沙利叶啊，难道真的如暗月派的信徒所言——\
“你从未前往众天之天，而是背向着明月，成为了魔鬼？”",
            ["ContentFR"] = "« Pourquoi l’Abysse immonde demeure-t-elle muette ? »\
« Pourquoi, sous l’argent pur de la pleine lune, la Déesse se tait ? »\
« Ô Shaliel... est-il vrai, comme le murmurent les disciples du Noctilunisme,\
que jamais tu n’atteignis le Paradis des Paradis — mais que tu tournas le dos à la lune,\
pour devenir un démon ? »",
            ["DialogueId"] = 6103010,
            ["GUID"] = "0F473B14",
            ["NextDialogue"] = 6103011,
            ["RougeTalkActorType"] = 1,
            ["SpeakNpcId"] = 910005,
            ["SpeakNpcName"] = "RougeLike_Room328_Char01",
            },
        [6103011] = {
            ["Content"] = "“请等一下——你说什么？”\
诗人唱出了你始料未及的词句，那是流传于异端者中最隐秘的流言——圣湖从不曾神圣，所谓的由沙利叶而始的神选从一开始就是一场盛大的献祭。\
从<H>某个人</>口中，你听过相同的推测。",
            ["ContentFR"] = "« Attends... qu’as-tu dit ? »\
Ses mots t’assaillent.\
C’est la plus terrible rumeur des hérétiques : le lac n’aurait jamais été sacré, et Shaliel, premier des Élus, n’aurait pas été sauvé... mais sacrifié.\
Tu te rappelles que <H>quelqu’un</> t’avait déjà soufflé cette même suspicion.",
            ["DialogueId"] = 6103011,
            ["GUID"] = "0F473B3E",
            ["NextDialogue"] = 6103012,
            ["RougeTalkActorType"] = 2,
            ["SpeakNpcId"] = 910004,
            },
        [6103012] = {
            ["Content"] = "可诗人只是继续旁若无人地拨弄着他的七弦琴，开始唱下一首歌谣，仿佛你并不存在于他的时空。\
他的声音越来越远，直到身影消失不见。",
            ["ContentFR"] = "Mais le poète poursuit, effleurant son luth comme si tu n’existais pas.\
Sa voix s’éloigne, s’éteint... et lui disparaît.",
            ["DialogueId"] = 6103012,
            ["GUID"] = "0F473B68",
            ["RougeTalkActorType"] = 3,
            },
        [6103013] = {
            ["Content"] = "离开此地。",
            ["ContentFR"] = "<I>Quitter cet endroit</>",
            ["DialogueId"] = 6103013,
            ["GUID"] = "0F473B92",
            ["IsKeyOption"] = true,
            ["NextDialogue"] = 6103014,
            ["RougeTalkActorType"] = 2,
            },
        [6103014] = {
            ["Content"] = "你打了几声招呼，尝试吸引诗人的注意。你想和他聊聊，但他只是兀自唱着那首古老的歌谣。\
大概无法从他口中得到什么有价值的情报了，于是你转身离开。",
            ["ContentFR"] = "Tu l’appelles à plusieurs reprises pour attirer son attention. Tu voudrais lui parler, mais il poursuit son antique hymne, comme si tu n’existais pas. Tu comprends qu’il n’y a rien d’utile à tirer de lui, tu te détournes et t’éloignes.",
            ["DialogueId"] = 6103014,
            ["GUID"] = "0F473BBC",
            ["RougeTalkActorType"] = 3,
            },
        [6200101] = {
            ["Content"] = "数位年轻人的交谈声从不远处传来，你已经很久没在深渊中听到这样的声音了——热烈的、鲜活的、尚未被深渊的黑暗侵染的声音。\
你很确信这声音的来源并非亡灵，也不是幻影，而是活生生的人类。而且，从谈话的气氛可以推断出，他们一定才刚来到这里不久。",
            ["ContentFR"] = "Le brouhaha de jeunes voix résonne au loin, un son que tu n’avais pas entendu depuis bien longtemps dans l’Abysse.\
Des voix ardentes, vibrantes, encore indemnes de la noirceur rampante.\
Tu en es sûr : ce ne sont ni des spectres, ni des illusions, mais bien des humains de chair et d’os.\
À les entendre, ils n’ont pas dû mettre les pieds ici depuis bien longtemps.",
            ["DialogueId"] = 6200101,
            ["GUID"] = "0F857412",
            ["NextDialogue"] = 6200102,
            ["RougeTalkActorType"] = 3,
            },
        [6200102] = {
            ["Content"] = "你忍不住循着声音所在的方向走去。环绕四周的迷雾逐渐散开，你见到了四位年轻的骑士。\
他们的衣着和装备各自有别，但身上都佩戴着象征艾利西安的圣鸢尾徽章。",
            ["ContentFR"] = "Tu suis le son malgré toi. Peu à peu, la brume se déchire, et tu aperçois quatre jeunes chevaliers.\
Chacun porte armes et atours différents, mais tous arborent l’iris sacré d’Élysium sur leur poitrine.",
            ["DialogueId"] = 6200102,
            ["GUID"] = "0F85743C",
            ["NextDialogue"] = 6200103,
            ["RougeTalkActorType"] = 3,
            },
        [6200103] = {
            ["Content"] = "“是这个方向没错吗，队长？”\
年轻的金发女骑士三步并作两步跨上古旧的台阶，又一口气跳了下来。\
“这看起来只是一座废墟而已。”",
            ["ContentFR"] = "« Capitaine, on est bien dans la bonne direction ? »\
La jeune chevalière blonde grimpe trois marches d’un vieil escalier, bondit d’un élan, et redescend aussitôt.\
« Ça ne ressemble qu’à des ruines... »",
            ["DialogueId"] = 6200103,
            ["GUID"] = "0F857466",
            ["NextDialogue"] = 6200104,
            ["RougeTalkActorType"] = 1,
            ["SpeakNpcName"] = "StoryEvent11_Char01",
            },
        [6200104] = {
            ["Content"] = "“至少我确定我们没来过这里。”\
被称作队长的青年骑士迈着沉稳的步伐从她身边走过。\
“在圣湖里很难辨别方向，现在也只能走一步算一步了。”",
            ["ContentFR"] = "« Une chose est sûre : on n’est encore jamais venus ici. »\
Le jeune capitaine avance d’un pas posé, dépassant Cathy.\
« Dans le Lac Sacré, on perd vite tout repère. Il ne reste qu’à avancer pas à pas. »",
            ["DialogueId"] = 6200104,
            ["GUID"] = "0F857490",
            ["NextDialogue"] = 6200105,
            ["RougeTalkActorType"] = 1,
            ["SpeakNpcName"] = "StoryEvent11_Char02",
            },
        [6200105] = {
            ["Content"] = "“还有——你这么上蹿下跳的不累吗，凯希？”\
看着自己那位活泼的同伴，青年无奈地叹了一口气。\
“这里的环境凶险，还是谨慎为好，别在战斗之外的事情上消耗体力。”",
            ["ContentFR"] = "« Et toi, Cathy, tu ne te fatigues pas à sautiller comme ça ? »\
Il laisse échapper un soupir résigné en voyant son amie virevolter.\
« Ménage tes forces. Ce lieu est dangereux, inutile de gaspiller ton énergie hors du combat. »",
            ["DialogueId"] = 6200105,
            ["GUID"] = "0F8574BA",
            ["NextDialogue"] = 6200106,
            ["RougeTalkActorType"] = 1,
            ["SpeakNpcName"] = "StoryEvent11_Char02",
            },
        [6200106] = {
            ["Content"] = "“一点也不累！我又不像你，拿着那么重的长剑和盾牌。”\
女孩轻巧地用食指勾住手枪，在空中转了个圈。\
“说起来，这里为什么叫‘圣湖’？我看这里到处都是秽兽和诡异的幻象，实在不怎么神圣呀。”",
            ["ContentFR"] = "« Fatiguée ? Pas du tout ! Je n’ai pas ton épée et ton bouclier énormes à traîner. »\
Elle fait tourner son pistolet sur son doigt avec aisance.\
« D’ailleurs... pourquoi ça s’appelle \"Lac Sacré\" ? Entre ces Souillés et ces illusions, je ne vois rien de bien sacré. »",
            ["DialogueId"] = 6200106,
            ["GUID"] = "0F8574E4",
            ["NextDialogue"] = 6200107,
            ["RougeTalkActorType"] = 1,
            ["SpeakNpcName"] = "StoryEvent11_Char01",
            },
        [6200107] = {
            ["Content"] = "“凯希，注意你的言辞。”\
手执长杖的男性卡戎司祭一脸严肃地开口。\
“圣湖是受神选召之人蒙受神恩的圣地，如今虽被黑暗侵染，可我们身为艾利西安的一羽，仍应心怀敬畏。”",
            ["ContentFR"] = "« Cathy, modère tes paroles. »\
Le prêtre Charon, tenant son bâton, prend un air grave.\
« Le Lac Sacré est un lieu béni, choisi par les dieux pour les élus. Même corrompu par les ténèbres, il demeure un sanctuaire que nous, enfants d’Élysium, devons respecter. »",
            ["DialogueId"] = 6200107,
            ["GUID"] = "0F85750E",
            ["NextDialogue"] = 6200108,
            ["RougeTalkActorType"] = 1,
            ["SpeakNpcName"] = "StoryEvent11_Char03",
            },
        [6200108] = {
            ["Content"] = "四人之中的最后一位——身披斗篷、背着一张长弓的女术士听到他的话，不以为然地轻笑了一声。黑色的兜帽遮住了她的面庞，你看不清她的表情。",
            ["ContentFR"] = "La quatrième, une sorcière drapée d’un manteau sombre, un long arc dans le dos, ricane doucement, d’un ton moqueur. Son capuchon noir dissimule son visage, rendant toute expression invisible.",
            ["DialogueId"] = 6200108,
            ["GUID"] = "0F857538",
            ["NextDialogue"] = 6200109,
            ["RougeTalkActorType"] = 3,
            },
        [6200109] = {
            ["Content"] = "似是想要缓解尴尬，身为队长的青年张了张嘴，却什么也说不出来。正当他左右为难的时候，他注意到了你。",
            ["ContentFR"] = "Flynn s’apprête à intervenir pour apaiser la tension, mais ses mots se meurent.\
C’est alors qu’il te remarque.",
            ["DialogueId"] = 6200109,
            ["GUID"] = "0F857562",
            ["NextDialogue"] = 6200110,
            ["RougeTalkActorType"] = 3,
            },
        [6200110] = {
            ["Content"] = "“阁下看起来不像是骑士团的人，莫非是误入此地的平民？”",
            ["ContentFR"] = "« Vous n’avez pas l’air de faire partie de l’Ordre. Seriez-vous {性别:un voyageur égaré|une voyageuse égarée} en ces lieux ? »",
            ["DialogueId"] = 6200110,
            ["GUID"] = "0F85758C",
            ["NextOptions"] = {
                [1] = 6200111,
                },
            ["RougeTalkActorType"] = 1,
            ["SpeakNpcName"] = "StoryEvent11_Char02",
            },
        [6200111] = {
            ["Content"] = "我是一位旅人。",
            ["ContentFR"] = "Je suis {性别:un voyageur|une voyageuse}.",
            ["DialogueId"] = 6200111,
            ["GUID"] = "0F8575B6",
            ["NextDialogue"] = 6200112,
            ["RougeTalkActorType"] = 2,
            },
        [6200112] = {
            ["Content"] = "“旅人……？”青年的脸上掠过一瞬的困惑，又旋即恢复温和的劝诫，“那么，或许您有所不知，此处是艾利西安的圣地，目前由于一些原因变得非常危险，并不适宜旅行。”",
            ["ContentFR"] = "« {性别:Un voyageur|Une voyageuse}... ? » L’étonnement traverse son visage, vite remplacé par une douceur prévenante.\
« Alors sans doute ignorez-vous que ce lieu, la terre sainte d’Élysium, est aujourd’hui trop dangereux pour s’y aventurer. »",
            ["DialogueId"] = 6200112,
            ["GUID"] = "0F8575E0",
            ["NextDialogue"] = 6200113,
            ["RougeTalkActorType"] = 1,
            ["SpeakNpcName"] = "StoryEvent11_Char02",
            },
        [6200113] = {
            ["Content"] = "“我叫弗林，是艾利西安传颂会下属飞羽骑士团的骑士，这几位都是我的同伴。如果您不介意的话，我们可以护送您离开此地。”",
            ["ContentFR"] = "« Je me présente : Flynn, chevalier de l’Ordre des Plumes-Célestes, sous l’Église Élyséenne. »\
Il désigne ses compagnons.\
« Nous pourrions vous raccompagner si vous le souhaitez. »",
            ["DialogueId"] = 6200113,
            ["GUID"] = "0F85760A",
            ["NextOptions"] = {
                [1] = 6200114,
                },
            ["RougeTalkActorType"] = 1,
            ["SpeakNpcName"] = "StoryEvent11_Char02",
            },
        [6200114] = {
            ["Content"] = "不必了，我还有未完成的目标。",
            ["ContentFR"] = "Inutile. J’ai encore quelque chose à accomplir ici.",
            ["DialogueId"] = 6200114,
            ["GUID"] = "0F857634",
            ["NextDialogue"] = 6200115,
            ["RougeTalkActorType"] = 2,
            },
        [6200115] = {
            ["Content"] = "“我必须提醒您，这里不止是圣地，也是禁地。作为骑士，我们有义务驱逐外来者。”",
            ["ContentFR"] = "« Alors je dois vous prévenir : cette terre sainte est aussi un lieu interdit. Notre devoir nous commande d’en chasser les intrus. »",
            ["DialogueId"] = 6200115,
            ["GUID"] = "0F85765E",
            ["NextDialogue"] = 6200116,
            ["RougeTalkActorType"] = 1,
            ["SpeakNpcName"] = "StoryEvent11_Char03",
            },
        [6200116] = {
            ["Content"] = "“……怎么驱逐？”伴随一声不屑的冷笑，身披斗篷的女术士终于开口，“难道不是连我们自己都不知道该怎么出去吗？”\
她的话语冰凉，如寒冬的雪粒擦过脸颊。",
            ["ContentFR"] = "La sorcière en capuchon éclate d’un rire amer.\
« Chasser ? Et comment, je te prie ? Même nous, nous ne savons pas comment en sortir. »\
Ses mots tombent, glacials, comme des flocons qui fouettent le visage.",
            ["DialogueId"] = 6200116,
            ["GUID"] = "0F857688",
            ["NextDialogue"] = 6200117,
            ["RougeTalkActorType"] = 1,
            ["SpeakNpcName"] = "StoryEvent11_Char04",
            },
        [6200117] = {
            ["Content"] = "“呃……好啦好啦。”金发的女骑士打起了圆场，“我看这位‘客人’身手还不错，也不像是渎神者。反正不影响我们的任务，就当做没看见吧？”",
            ["ContentFR"] = "« Allez, allez. » La jeune chevalière blonde s’interpose pour calmer le jeu.\
« Ce {性别:voyageur n’est pas un blasphémateur|voyageuse n’est pas une blasphématrice}, et {性别:il|elle} se débrouille visiblement très bien. Autant faire comme si on n’avait rien vu. »",
            ["DialogueId"] = 6200117,
            ["GUID"] = "0F8576B2",
            ["NextDialogue"] = 6200118,
            ["RougeTalkActorType"] = 1,
            ["SpeakNpcName"] = "StoryEvent11_Char01",
            },
        [6200118] = {
            ["Content"] = "“对了对了，旅人阁下。”她推开弗林，挤到你面前，“您有没有见过一位大约十三四岁，粉色长发，手持一柄巨剑的女剑士？”",
            ["ContentFR"] = "Puis, avec une étincelle dans les yeux, elle se penche vers toi :\
« D’ailleurs, {性别:voyageur|voyageuse}, auriez-vous aperçu une épéiste de treize ou quatorze ans, aux cheveux roses et portant une immense épée dans le dos ? »",
            ["DialogueId"] = 6200118,
            ["GUID"] = "0F8576DC",
            ["NextOptions"] = {
                [1] = 6200119,
                },
            ["RougeTalkActorType"] = 1,
            ["SpeakNpcName"] = "StoryEvent11_Char01",
            },
        [6200119] = {
            ["Content"] = "……没有。",
            ["ContentFR"] = "... Non.",
            ["DialogueId"] = 6200119,
            ["GUID"] = "0F857706",
            ["NextDialogue"] = 6200120,
            ["RougeTalkActorType"] = 2,
            },
        [6200120] = {
            ["Content"] = "“是吗……那么，如果您之后遇见了她，请帮忙转告一声——就说<H>静默黄昏</>小队正在找她，好吗？拜托您了！”",
            ["ContentFR"] = "« Je vois... Alors, si vous la croisez, dites-lui que l’escouade du <H>Crépuscule Silencieux</> la recherche. Vous nous rendriez un grand service ! »",
            ["DialogueId"] = 6200120,
            ["GUID"] = "0F857730",
            ["NextOptions"] = {
                [1] = 6200121,
                },
            ["RougeTalkActorType"] = 1,
            ["SpeakNpcName"] = "StoryEvent11_Char01",
            },
        [6200121] = {
            ["Content"] = "你们为什么要找她？",
            ["ContentFR"] = "Pourquoi la cherchez-vous ?",
            ["DialogueId"] = 6200121,
            ["GUID"] = "0F85775A",
            ["NextDialogue"] = 6200122,
            ["RougeTalkActorType"] = 2,
            },
        [6200122] = {
            ["Content"] = "“虽然有些难以启齿，但她算是我们的……指挥官。呃，我也不能说得太多，否则米尔顿又该数落我了。”",
            ["ContentFR"] = "« Eh bien... c’est, disons, notre commandante. Mais chut, je n’en dirai pas plus, ou Milton me fera la morale. »",
            ["DialogueId"] = 6200122,
            ["GUID"] = "0F857784",
            ["NextDialogue"] = 6200123,
            ["RougeTalkActorType"] = 1,
            ["SpeakNpcName"] = "StoryEvent11_Char01",
            },
        [6200123] = {
            ["Content"] = "“既然知道就别多嘴。”司祭皱起了眉头。“别再横生枝节了，任务要紧，我们走吧。”",
            ["ContentFR"] = "« Ça suffit, Cathy. » Le prêtre fronce les sourcils.\
« Finissons notre mission. »",
            ["DialogueId"] = 6200123,
            ["GUID"] = "0F8577AE",
            ["NextDialogue"] = 6200124,
            ["RougeTalkActorType"] = 1,
            ["SpeakNpcName"] = "StoryEvent11_Char03",
            },
        [6200124] = {
            ["Content"] = "“您真的不需要帮助吗？”青年再次担忧地看向你，“这里真的非常危险，或许您可以和我们同路前行。”",
            ["ContentFR"] = "« Êtes-vous sûr de ne pas vouloir de notre aide ? Ce lieu est dangereux, peut-être pourriez-vous marcher avec nous... »",
            ["DialogueId"] = 6200124,
            ["GUID"] = "0F8577D8",
            ["NextOptions"] = {
                [1] = 6200125,
                },
            ["RougeTalkActorType"] = 1,
            ["SpeakNpcName"] = "StoryEvent11_Char02",
            },
        [6200125] = {
            ["Content"] = "真的不需要。",
            ["ContentFR"] = "Non, je préfère avancer {性别:seul|seule}.",
            ["DialogueId"] = 6200125,
            ["GUID"] = "0F857802",
            ["NextDialogue"] = 6200126,
            ["RougeTalkActorType"] = 2,
            },
        [6200126] = {
            ["Content"] = "“好吧。既然您坚定如此……”",
            ["ContentFR"] = "« Bien. Puisque telle est votre volonté... »",
            ["DialogueId"] = 6200126,
            ["GUID"] = "0F85782C",
            ["NextOptions"] = {
                [1] = 6200127,
                },
            ["RougeTalkActorType"] = 1,
            ["SpeakNpcName"] = "StoryEvent11_Char02",
            },
        [6200127] = {
            ["Content"] = "既然这么危险，你们不害怕吗？",
            ["ContentFR"] = "Et dans un endroit pareil, vous n’avez pas peur ?",
            ["DialogueId"] = 6200127,
            ["GUID"] = "0F857856",
            ["IsKeyOption"] = true,
            ["NextDialogue"] = 6200128,
            ["RougeTalkActorType"] = 2,
            },
        [6200128] = {
            ["Content"] = "“心怀信仰，自然不会畏惧。”青年露出了笃定的笑容，“有缘再会，阁下，愿满月之神护佑您的旅途。”",
            ["ContentFR"] = "Il esquisse un sourire sûr de lui.\
« La foi écarte la peur. Jusqu’à notre prochaine rencontre, {性别:voyageur|voyageuse}, que le Dieu de la Pleine Lune veille sur votre route. »",
            ["DialogueId"] = 6200128,
            ["GUID"] = "0F857880",
            ["NextDialogue"] = 6200129,
            ["RougeTalkActorType"] = 1,
            ["SpeakNpcName"] = "StoryEvent11_Char02",
            },
        [6200129] = {
            ["Content"] = "骑士们结伴离开了，你的眼前又只剩下延绵不绝的迷雾。",
            ["ContentFR"] = "Les chevaliers s’éloignent ensemble, te laissant {性别:seul|seule} face à la brume infinie.",
            ["DialogueId"] = 6200129,
            ["GUID"] = "0F8578AA",
            ["RougeTalkActorType"] = 3,
            },
        [6200201] = {
            ["Content"] = "年轻的女骑士从黑暗中现身，金色发丝如同一道流泻的灯光照亮了混沌。\
她和上一次见面时不太一样了——她的衣摆多了几道破损之处，沾上了一些暗红色的痕迹。",
            ["ContentFR"] = "La chevalière blonde surgit des ténèbres, sa chevelure d’or traçant dans l’ombre un sillage lumineux.\
Mais elle n’est plus tout à fait la même : son vêtement est déchiré, taché d’un rouge sombre.",
            ["DialogueId"] = 6200201,
            ["GUID"] = "0F85847A",
            ["NextDialogue"] = 6200202,
            ["RougeTalkActorType"] = 3,
            },
        [6200202] = {
            ["Content"] = "“是你呀，旅人阁下，又见面了！”她似是有些疲惫，却依旧打起精神向你用力挥手。",
            ["ContentFR"] = "« Ah, {性别:voyageur|voyageuse}... nos chemins se croisent à nouveau ! »\
Elle agite la main, fatiguée mais joyeuse.",
            ["DialogueId"] = 6200202,
            ["GUID"] = "0F8584A4",
            ["NextOptions"] = {
                [1] = 6200203,
                },
            ["RougeTalkActorType"] = 1,
            ["SpeakNpcName"] = "StoryEvent12_Char01",
            },
        [6200203] = {
            ["Content"] = "你的同伴们呢？",
            ["ContentFR"] = "Et vos compagnons ?",
            ["DialogueId"] = 6200203,
            ["GUID"] = "0F8584CE",
            ["NextDialogue"] = 6200204,
            ["RougeTalkActorType"] = 2,
            },
        [6200204] = {
            ["Content"] = "“唔……刚才我们遇到了好些秽兽，还有很多幽灵——我是说，那些黑暗里的影子……”",
            ["ContentFR"] = "« Eh bien... des Souillés, des spectres — enfin, ces ombres, nous sont tombés dessus. »",
            ["DialogueId"] = 6200204,
            ["GUID"] = "0F8584F8",
            ["NextDialogue"] = 6200205,
            ["RougeTalkActorType"] = 1,
            ["SpeakNpcName"] = "StoryEvent12_Char01",
            },
        [6200205] = {
            ["Content"] = "“我拼命驱逐了它们，回过神来，大家就都不见了。你见到他们了吗？”",
            ["ContentFR"] = "« Je les ai combattus, mais quand tout s’est dissipé... ils avaient disparu. Vous ne les auriez pas vus ? »",
            ["DialogueId"] = 6200205,
            ["GUID"] = "0F858522",
            ["NextOptions"] = {
                [1] = 6200206,
                },
            ["RougeTalkActorType"] = 1,
            ["SpeakNpcName"] = "StoryEvent12_Char01",
            },
        [6200206] = {
            ["Content"] = "没有。",
            ["ContentFR"] = "Non.",
            ["DialogueId"] = 6200206,
            ["GUID"] = "0F85854C",
            ["NextDialogue"] = 6200207,
            ["RougeTalkActorType"] = 2,
            },
        [6200207] = {
            ["Content"] = "凯希垂下了眼眸，像一朵浮云飘过，遮住了太阳。",
            ["ContentFR"] = "Son regard se baisse, tel un voile qui recouvre le soleil.",
            ["DialogueId"] = 6200207,
            ["GUID"] = "0F858576",
            ["NextDialogue"] = 6200208,
            ["RougeTalkActorType"] = 3,
            },
        [6200208] = {
            ["Content"] = "“弗林总是念叨说，战斗的时候要注意队形，要互相照应……唉，如果我听他的话，不那么随性就好了。”",
            ["ContentFR"] = "« Flynn me répète toujours de rester en formation... Si seulement je l’avais écouté, au lieu de foncer tête baissée... »",
            ["DialogueId"] = 6200208,
            ["GUID"] = "0F8585A0",
            ["NextDialogue"] = 6200209,
            ["RougeTalkActorType"] = 1,
            ["SpeakNpcName"] = "StoryEvent12_Char01",
            },
        [6200209] = {
            ["Content"] = "“我根本不知道圣湖是这样的地方。平时我就算不小心掉队，也很快就能找到他们。可是这里……明明是刚才走过的地方，回头一看已经完全不一样了。就像是……”\
她攥紧了拳头。\
“就像是那些影子把大家带走了……连他们留下的痕迹也一并抹除了。”",
            ["ContentFR"] = "« Je n’aurais jamais imaginé que le Lac Sacré soit un endroit pareil... D’ordinaire, même si je me perds, je finis toujours par retrouver les autres. Mais ici... Les lieux changent dès qu’on détourne les yeux. Ce chemin, je viens pourtant de l’emprunter, et il est déjà devenu méconnaissable. C’est comme si... »\
Ses poings se serrent.\
« Comme si ces ombres les avaient emportés... effaçant jusqu’à la moindre trace de leur passage. »",
            ["DialogueId"] = 6200209,
            ["GUID"] = "0F8585CA",
            ["NextOptions"] = {
                [1] = 6200210,
                },
            ["RougeTalkActorType"] = 1,
            ["SpeakNpcName"] = "StoryEvent12_Char01",
            },
        [6200210] = {
            ["Content"] = "别担心，你们一定会再次相遇的，就像你遇见我一样。",
            ["ContentFR"] = "« Ne vous inquiétez pas. Vous finirez par les retrouver... Comme vous m’avez trouvé. »",
            ["DialogueId"] = 6200210,
            ["GUID"] = "0F8585F4",
            ["NextDialogue"] = 6200211,
            ["RougeTalkActorType"] = 2,
            },
        [6200211] = {
            ["Content"] = "凯希有些惊讶地眨了眨眼，盯着你看了一会儿。",
            ["ContentFR"] = "Elle cligne des yeux, un peu surprise.",
            ["DialogueId"] = 6200211,
            ["GUID"] = "0F85861E",
            ["NextDialogue"] = 6200212,
            ["RougeTalkActorType"] = 3,
            },
        [6200212] = {
            ["Content"] = "“我们以前见过吗？”\
她明亮的双眸中倒映出你的容颜。那容颜让你觉得陌生。",
            ["ContentFR"] = "« Nous nous serions déjà rencontrés ? »\
Ses yeux brillants reflètent ton visage, un reflet qui t’apparaît étrangement étranger.",
            ["DialogueId"] = 6200212,
            ["GUID"] = "0F858648",
            ["NextDialogue"] = 6200213,
            ["RougeTalkActorType"] = 1,
            ["SpeakNpcName"] = "StoryEvent12_Char01",
            },
        [6200213] = {
            ["Content"] = "“我总觉得，你身上有种似曾相识的感觉——我不是说上次见面，而是更早之前，在我们还没进入圣湖的时候……”",
            ["ContentFR"] = "« J’ai l’impression de vous avoir croisé bien avant notre rencontre au Lac Sacré... »",
            ["DialogueId"] = 6200213,
            ["GUID"] = "0F858672",
            ["NextOptions"] = {
                [1] = 6200214,
                },
            ["RougeTalkActorType"] = 1,
            ["SpeakNpcName"] = "StoryEvent12_Char01",
            },
        [6200214] = {
            ["Content"] = "只是错觉吧。",
            ["ContentFR"] = "Juste une impression.",
            ["DialogueId"] = 6200214,
            ["GUID"] = "0F85869C",
            ["NextDialogue"] = 6200215,
            ["RougeTalkActorType"] = 2,
            },
        [6200215] = {
            ["Content"] = "“嗯，也对。”\
她勾起嘴角笑了笑，像被遮蔽的阳光努力穿越云层透出了一丝光亮。",
            ["ContentFR"] = "« Oui, sans doute. »\
Un sourire discret, comme un rayon qui perce les nuages.",
            ["DialogueId"] = 6200215,
            ["GUID"] = "0F8586C6",
            ["NextDialogue"] = 6200216,
            ["RougeTalkActorType"] = 1,
            ["SpeakNpcName"] = "StoryEvent12_Char01",
            },
        [6200216] = {
            ["Content"] = "“和他们失散以后，我已经一个人走了很久、很久。如果不是遇到了你，我都要怀疑自己是受到神罚，掉进什么地狱了呢。”",
            ["ContentFR"] = "« Après m’être perdue, j’ai marché seule si longtemps… Vous rencontrer m’a prouvé que je n’étais pas condamnée à errer seule dans cet enfer. »",
            ["DialogueId"] = 6200216,
            ["GUID"] = "0F8586F0",
            ["NextDialogue"] = 6200217,
            ["RougeTalkActorType"] = 1,
            ["SpeakNpcName"] = "StoryEvent12_Char01",
            },
        [6200217] = {
            ["Content"] = "“也许我只是对<H>活着的生命</>的气息产生了怀念吧。”",
            ["ContentFR"] = "« Peut-être que ce n’est qu’un désir... le souffle d’une autre <H>vie vivante</>. »",
            ["DialogueId"] = 6200217,
            ["GUID"] = "0F85871A",
            ["NextOptions"] = {
                [1] = 6200218,
                },
            ["RougeTalkActorType"] = 1,
            ["SpeakNpcName"] = "StoryEvent12_Char01",
            },
        [6200218] = {
            ["Content"] = "希望你能早日和同伴会合。",
            ["ContentFR"] = "J’espère que vous retrouverez vite vos compagnons.",
            ["DialogueId"] = 6200218,
            ["GUID"] = "0F858744",
            ["IsKeyOption"] = true,
            ["NextDialogue"] = 6200219,
            ["RougeTalkActorType"] = 2,
            },
        [6200219] = {
            ["Content"] = "“嗯，谢谢！没关系啦，他们都是非常厉害的骑士。就算没有我在，也一定没问题的。是我必须要找到他们才行……”",
            ["ContentFR"] = "« Merci. Ne vous inquiétez pas, ce sont des chevaliers d’exception. Même sans moi, ils s’en sortiront. C’est à moi de les retrouver... »",
            ["DialogueId"] = 6200219,
            ["GUID"] = "0F85876E",
            ["NextDialogue"] = 6200220,
            ["RougeTalkActorType"] = 1,
            ["SpeakNpcName"] = "StoryEvent12_Char01",
            },
        [6200220] = {
            ["Content"] = "“再见，旅人阁下。祝你也能实现自己的目标。”",
            ["ContentFR"] = "Elle t’adresse un dernier sourire :\
« Adieu, {性别:voyageur|voyageuse}. Que vous puissiez, vous aussi, accomplir ce qui vous attend. »",
            ["DialogueId"] = 6200220,
            ["GUID"] = "0F858798",
            ["NextDialogue"] = 6200221,
            ["RougeTalkActorType"] = 1,
            ["SpeakNpcName"] = "StoryEvent12_Char01",
            },
        }
  end },
  { MinKey = 6200221, MaxKey = 6201601, Loader = function()
      return {
