            ["DialogueId"] = 6200309,
            ["GUID"] = "0F859632",
            ["NextOptions"] = {
                [1] = 6200310,
                },
            ["RougeTalkActorType"] = 3,
            },
        [6200310] = {
            ["Content"] = "于是你明白了：她和你一样来晚了。",
            ["ContentFR"] = "Alors tu comprends. Comme toi, elle est arrivée trop tard.",
            ["DialogueId"] = 6200310,
            ["GUID"] = "0F85965C",
