            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 100012,
            ["VoiceName"] = "voice/$Locale$/story/1002/100127/1910D56B",
            },
        [10012706] = {
            ["Camera"] = "116.4375,-210.523438,168.495239,0.000323,-19.201778,29.174892,35.0,100000.0,false,Manual,22.0",
            ["Content"] = "你是说——我还活着？",
            ["ContentFR"] = "Tu veux dire... que je suis encore en vie ?",
            ["DefaultLookAt"] = "KeepState",
            ["DialogueId"] = 10012706,
            ["Duration"] = 5,
            ["ExStoryInfo"] = "Player",
            ["FinalCamera"] = "136.882812,-238.855469,168.495239,0.000319,-18.601807,42.176678,35.0,100000.0,false,Manual,22.0",
            ["GUID"] = "1910D594",
            ["LookAt"] = {
                [1] = "100001:n(100014)",
                },
            ["NextDialogue"] = 10012712,
            ["SpeakNpcId"] = 100001,
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/1002/100127/1910D594",
            },
        [10012707] = {
            ["Camera"] = "524.417969,-273.097656,72.024963,0.000254,10.998483,156.973907,35.0,100000.0,false,Manual,22.0",
            ["Content"] = "……时间到了。让我给你最后一份助力吧。",
            ["ContentFR"] = "... Le temps est venu. Laisse-moi t’offrir mon dernier cadeau.",
            ["DialogueId"] = 10012707,
            ["Duration"] = 5,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1910D595",
            ["NextDialogue"] = 10012708,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 100012,
            ["VoiceName"] = "voice/$Locale$/story/1002/100127/1910D595",
            },
        [10012708] = {
            ["Camera"] = "524.417969,-273.097656,72.024963,0.000254,10.998483,156.973907,35.0,100000.0,false,Manual,22.0",
            ["Content"] = "把手给我，{nickname}。",
            ["ContentFR"] = "Donne-moi la main, {nickname}.",
            ["DialogueId"] = 10012708,
            ["Duration"] = 5,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1910D599",
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 100012,
            ["VoiceName"] = "voice/$Locale$/story/1002/100127/1910D599",
            },
        [10012709] = {
            ["Camera"] = "524.417969,-273.097656,72.024963,0.000254,10.998483,156.973907,35.0,100000.0,false,Manual,22.0",
            ["Content"] = "这些砂砾是你我二人的，连接着过去、现在、与未来的“记忆”。",
            ["ContentFR"] = "Ces grains de sable sont à nous deux, ils relient le passé, le présent et l’avenir... nos \"souvenirs\".",
            ["DialogueId"] = 10012709,
            ["Duration"] = 4,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1910D59A",
            ["NextDialogue"] = 10012710,
            ["RelatedWikiId"] = {
                [1] = 304001,
                [2] = 204001,
                [3] = 201001,
                [4] = 304002,
                },
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 100012,
            },
        [10012710] = {
            ["Camera"] = "524.417969,-273.097656,72.024963,0.000254,10.998483,156.973907,35.0,100000.0,false,Manual,22.0",
            ["Content"] = "从中寻觅吧……寻觅那些我们或许已经熟悉，或许将在未来相遇的身影。",
            ["ContentFR"] = "Dans ce flux de mémoire, tu trouveras la force pour ton voyage.",
            ["DialogueId"] = 10012710,
            ["Duration"] = 4,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1910D59B",
            ["NextDialogue"] = 10012711,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 100012,
            ["VoiceName"] = "voice/$Locale$/story/1002/100127/1910D59B",
            },
        [10012711] = {
            ["Content"] = "愿他们成为你此行的助力。",
            ["DialogueId"] = 10012711,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1910D59C",
            ["NextDialogue"] = 10012712,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 100012,
            ["VoiceName"] = "voice/$Locale$/story/1002/100127/1910D59C",
            },
        [10012712] = {
            ["Camera"] = "524.417969,-273.097656,72.024963,0.000254,10.998483,156.973907,35.0,100000.0,false,Manual,22.0",
            ["Content"] = "该出发了。",
            ["ContentFR"] = "Il est temps de partir.",
            ["DialogueId"] = 10012712,
            ["Duration"] = 5,
            ["ExStoryInfo"] = "EXPlayer",
            ["FinalCamera"] = "511.515625,-301.914062,72.024963,0.000255,10.998483,151.374451,35.0,100000.0,false,Manual,22.0",
            ["GUID"] = "1910D596",
            ["NextDialogue"] = 10012713,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 100012,
            ["ToFinalCameraBlendTime"] = 6,
            ["VoiceName"] = "voice/$Locale$/story/1002/100127/1910D596",
            },
        [10012713] = {
            ["Camera"] = "317.9375,-203.148438,165.504761,0.000249,2.998658,152.974579,35.0,100000.0,false,Manual,22.0",
            ["Content"] = "……{nickname}。生命是航行在无尽长夜里的孤船。河流泪水满溢，夹岸荆棘丛生。",
            ["ContentFR"] = "... {nickname}. La vie est une croisière solitaire dans l’obscurité infinie de la nuit. La rivière déborde de larmes, et les ronces qui bordent ses rives en sont le témoignage. ",
            ["DialogueId"] = 10012713,
            ["Duration"] = 5,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1910D597",
            ["NextDialogue"] = 10012714,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 100012,
            ["VoiceName"] = "voice/$Locale$/story/1002/100127/1910D597",
            },
        [10012714] = {
            ["Camera"] = "317.9375,-203.148438,165.504761,0.000249,2.998658,152.974579,35.0,100000.0,false,Manual,22.0",
            ["Content"] = "我会一直注视着……彼岸的你，将驶向何方。",
            ["ContentFR"] = "Je veillerai sur toi... l’âme de l’autre rive, pour voir jusqu’où tu iras.",
            ["DialogueId"] = 10012714,
            ["Duration"] = 5,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1910D598",
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 100012,
            ["VoiceName"] = "voice/$Locale$/story/1002/100127/1910D598",
            },
        [10012801] = {
            ["Content"] = "这是我第一次来科赛托斯省。看来这里的待客之道，颇为独特啊。",
            ["ContentFR"] = "C’est ma première visite dans la Région de Cocytus. Apparemment, l’accueil ici est... particulier.",
            ["DialogueId"] = 10012801,
            ["Duration"] = 8.1,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1910E52A",
            ["RelatedWikiId"] = {
                [1] = 408002,
                },
            ["SnapShot"] = "MYSTERIOUS",
            ["SpeakNpcId"] = 100012,
            ["VoiceName"] = "voice/$Locale$/story/1002/100128/1910E52A",
            },
        [10012802] = {
            ["Content"] = "我没有任何恶意，只是想同你做一笔……小小的交易。",
            ["ContentFR"] = "Je n’ai aucune mauvaise intention, je souhaite simplement... conclure un petit marché avec toi. ",
            ["DialogueId"] = 10012802,
            ["Duration"] = 6.1,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1910E57E",
            ["SnapShot"] = "MYSTERIOUS",
            ["SpeakNpcId"] = 100012,
            ["VoiceName"] = "voice/$Locale$/story/1002/100128/1910E57E",
            },
        [10012803] = {
            ["Content"] = "我会付给你无法拒绝的报酬，而你要做的，非常简单。",
            ["ContentFR"] = "Je te proposerai une récompense que tu ne pourras pas refuser. Et toi... tu n’auras qu’à faire quelque chose de très simple.",
            ["DialogueId"] = 10012803,
            ["Duration"] = 6.5,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1910E5A8",
            ["SnapShot"] = "MYSTERIOUS",
            ["SpeakNpcId"] = 100012,
            ["VoiceName"] = "voice/$Locale$/story/1002/100128/1910E5A8",
            },
        [10017801] = {
            ["Content"] = "......",
            ["DialogueId"] = 10017801,
            ["Duration"] = 1,
            ["GUID"] = "1914197A",
            ["RelatedWikiId"] = {
                [1] = 408001,
                [2] = 201001,
                [3] = 303001,
                [4] = 401001,
                [5] = 403001,
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/100178/1914197A",
            },
        [10017901] = {
            ["Content"] = "飞艇在山顶。稍微修整一下，就继续往上走吧。",
            ["ContentFR"] = "Le dirigeable est au sommet. On se repose un instant, puis on continue.",
            ["DialogueId"] = 10017901,
            ["DisableMouth"] = 1,
            ["Duration"] = 5,
            ["GUID"] = "191429E2",
            ["SpeakNpcId"] = 100003,
            ["VoiceName"] = "voice/$Locale$/story/1001/100179/191429E2",
            },
        [10017902] = {
            ["Content"] = "……这么快，就要和净界岛告别了。",
            ["ContentFR"] = "... Déjà... on va devoir dire adieu à l’Île du Purgatoire.",
            ["DialogueId"] = 10017902,
            ["DisableMouth"] = 1,
            ["Duration"] = 3.5,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "19142A0C",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1001/100179/19142A0C",
            },
        [10017903] = {
            ["Content"] = "……真是片刻也不让人清净。",
            ["ContentFR"] = "... Même une minute de répit, on n’y a pas droit.",
            ["DialogueId"] = 10017903,
            ["DisableMouth"] = 1,
            ["Duration"] = 5.5,
            ["GUID"] = "19142A0D",
            ["SpeakNpcId"] = 100003,
            ["VoiceName"] = "voice/$Locale$/story/1001/100179/19142A0D",
            },
        [10018001] = {
            ["Content"] = "走。",
            ["DialogueId"] = 10018001,
            ["Duration"] = 2,
            ["GUID"] = "19143A4A",
            ["SpeakNpcId"] = 100003,
            ["VoiceName"] = "voice/$Locale$/story/1001/100180/19143A4A",
            },
        [10018101] = {
            ["DialogueId"] = 10018101,
            ["Duration"] = 1,
            ["GUID"] = "19144AB2",
            ["SpeakNpcId"] = 100003,
            ["VoiceName"] = "voice/$Locale$/story/1001/100181/19144AB2",
            },
        [10018201] = {
            ["Content"] = "那天，在毁灭之前，我睁开双眼。瞳孔所见之景，是“无限”。",
            ["DialogueId"] = 10018201,
            ["DialoguePanelType"] = "None",
            ["Duration"] = 13,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "19145B1A",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1001/100182/19145B1A",
            },
        [10018202] = {
            ["Content"] = "第一次，我感受到了，我是如此真实地活着。",
            ["DialogueId"] = 10018202,
            ["DialoguePanelType"] = "None",
            ["Duration"] = 7,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "19145B44",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1001/100182/19145B44",
            },
        [10018301] = {
            ["Content"] = "下坠。我本应朝着漆黑的深渊下坠。",
            ["DialogueId"] = 10018301,
            ["Duration"] = 2.5,
            ["GUID"] = "19146B82",
            ["NextDialogue"] = 10018302,
            ["VoiceName"] = "voice/$Locale$/story/1001/100183/19146B82",
            },
        [10018302] = {
            ["Content"] = "但，我却感觉自己在晨雾的怀抱里飘浮。",
            ["DialogueId"] = 10018302,
            ["Duration"] = 2.5,
            ["GUID"] = "19146BAC",
            ["NextDialogue"] = 10018303,
            ["VoiceName"] = "voice/$Locale$/story/1001/100183/19146BAC",
            },
        [10018303] = {
            ["Content"] = "周身被冰冷的触感包围，但意外的是，那种冰冷并不令人恐惧。",
            ["DialogueId"] = 10018303,
            ["Duration"] = 4,
            ["GUID"] = "19146BD6",
            ["NextDialogue"] = 10018304,
            ["VoiceName"] = "voice/$Locale$/story/1001/100183/19146BD6",
            },
        [10018304] = {
            ["Content"] = "而是一种，奇特的触感……亲切，甚至令人怀念。",
            ["DialogueId"] = 10018304,
            ["Duration"] = 3,
            ["GUID"] = "19146C00",
            ["VoiceName"] = "voice/$Locale$/story/1001/100183/19146C00",
            },
        [10018401] = {
            ["Content"] = "回答我的，只有不尽流泻的无垠白沙；以及……",
            ["ContentFR"] = "Et jusqu’à présent, personne n’a jamais répondu. Seulement l’écoulement infini d’un sable blanc... et puis...",
            ["DialogueId"] = 10018401,
            ["Duration"] = 0.5,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "19147BEA",
            ["NextDialogue"] = 10018402,
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1001/100184/19147BEA",
            },
        [10018402] = {
            ["Content"] = "{性别：她|他}。",
            ["ContentFR"] = "{性别:elle|lui}.",
            ["DialogueId"] = 10018402,
            ["Duration"] = 1.5,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "19147C14",
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1001/100184/19147C14",
            },
        [10018501] = {
            ["Content"] = "占位文本",
            ["DialogueId"] = 10018501,
            ["GUID"] = "19148C52",
            ["VoiceName"] = "voice/$Locale$/story/1001/100185/19148C52",
            },
        [10018601] = {
            ["Content"] = "不要……",
            ["ContentFR"] = "Non...",
            ["DialogueId"] = 10018601,
            ["Duration"] = 2,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "19149CBA",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1001/100186/19149CBA",
            },
        [10018602] = {
            ["Content"] = "不要……把……她……",
            ["ContentFR"] = "Ne... l’emmenez pas...",
            ["DialogueId"] = 10018602,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "19149CE4",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1001/100186/19149CE4",
            },
        [10018603] = {
            ["Content"] = "滚开。",
            ["DialogueId"] = 10018603,
            ["Duration"] = 2,
            ["GUID"] = "19144AB3",
            ["SpeakNpcId"] = 100003,
            ["VoiceName"] = "voice/$Locale$/story/1001/100181/19144AB3",
            },
        [10018701] = {
            ["Content"] = "——“我是谁？”",
            ["ContentFR"] = "« Qui suis-je ? »",
            ["DialogueId"] = 10018701,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "1914AD22",
            ["SpeakNpcId"] = 100001,
            },
        [10018801] = {
            ["DialogueId"] = 10018801,
            ["Duration"] = 1,
            ["GUID"] = "1914BD8A",
            ["VoiceName"] = "voice/$Locale$/story/1001/100188/1914BD8A",
            },
        [10018901] = {
            ["Camera"] = "445.776367,-604.509766,186.644531,0.000533,7.394103,84.717964,24.0,500.0,false,Disable,22.0",
            ["Content"] = "出海指望不上了。看来只能试试那个……",
            ["ContentFR"] = "On peut oublier la mer... Il nous reste une autre option.",
            ["DefaultLookAt"] = "KeepState",
            ["DialogueId"] = 10018901,
            ["FacialId"] = {
                [1] = "100003:Confident01",
                },
            ["FinalCamera"] = "504.098145,26.331055,268.859863,0.000533,7.394103,84.717964,24.0,500.0,false,Disable,22.0",
            ["GUID"] = "190F9D5E",
            ["NextDialogue"] = 10018902,
            ["RelatedWikiId"] = {
                [1] = 408001,
                [2] = 201001,
                [3] = 303001,
                },
            ["SpeakNpcId"] = 100003,
            ["TalkActionId"] = {
                [1] = "100001:Think_End",
                },
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/1001/100108/190F9D5E",
            },
        [10018902] = {
            ["Camera"] = "38.842773,139.664062,126.450684,0.000293,2.606147,-116.596527,40.0,195.358566,false,Manual,2.799999",
            ["Content"] = "听我说，这座岛上其实还有一艘“船”，就在山上的遗迹里。",
            ["ContentFR"] = "Écoute-moi. Sur cette île, il existe un autre \"bateau\"... dans les ruines, là-haut, dans la montagne.",
            ["DefaultLookAt"] = "KeepState",
            ["DialogueId"] = 10018902,
            ["GUID"] = "190FAD72",
            ["LookAt"] = {
                [1] = "100001:n(100003)",
                [2] = "100003:n(100001)",
                },
            ["NextDialogue"] = 10018903,
            ["SpeakNpcId"] = 100003,
            ["TurnTo"] = {
                [1] = "100003:p(-40)",
                },
            ["VoiceName"] = "voice/$Locale$/story/1001/100109/190FAD72",
            },
        [10018903] = {
            ["Camera"] = "-180.119751,-33.829102,148.040039,0.000356,-7.595668,15.806756,35.000008,201.418701,false,Manual,2.8",
            ["Content"] = "船——山上的？",
            ["ContentFR"] = "Un bateau... en haut de la montagne ?",
            ["DefaultLookAt"] = "KeepState",
            ["DialogueId"] = 10018903,
            ["ExStoryInfo"] = "Player",
            ["FacialId"] = {
                [1] = "100001:Shock01",
                },
            ["GUID"] = "190FAD9C",
            ["NextDialogue"] = 10018904,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1001/100109/190FAD9C",
            },
        [10018904] = {
            ["Camera"] = "-719.279663,652.294922,186.867676,0.000371,-7.196232,-42.994892,35.0,131.625381,false,Disable,8.286504",
            ["Content"] = "嗯，可以飞在天上的“船”。跟我来。",
            ["ContentFR"] = "Oui. Un \"bateau\" qui vole. Suis-moi.",
            ["DefaultLookAt"] = "KeepState",
            ["DialogueId"] = 10018904,
            ["FinalCamera"] = "-767.170166,696.94043,195.135254,0.000371,-7.196232,-42.994892,35.0,131.625381,false,Disable,8.286504",
            ["GUID"] = "190FAD9E",
            ["SpeakNpcId"] = 100003,
            ["TalkActionId"] = {
                [1] = "100003:Agree",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/story/1001/100109/190FAD9E",
            },
        [10019001] = {
            ["Content"] = "村子里什么人声都没有，恐怕他们已经……",
            ["ContentFR"] = "Le village est plongé dans un silence de mort... J’ai bien peur qu’ils soient déjà...",
            ["DialogueId"] = 10019001,
            ["Duration"] = 1.8,
            ["GUID"] = "1914DE5A",
            ["NextDialogue"] = 10019002,
            ["SpeakNpcId"] = 100003,
            ["VoiceName"] = "voice/$Locale$/story/1001/100190/1914DE5A",
            },
        [10019002] = {
            ["Content"] = "……！！",
            ["ContentFR"] = "... !",
            ["DialogueId"] = 10019002,
            ["Duration"] = 2,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "1914DE84",
            ["NextDialogue"] = 10019003,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1001/100190/1914DE84",
            },
        [10019003] = {
            ["Content"] = "……我的意思是，他们大多应该乘船逃走了。",
            ["ContentFR"] = "... Je veux dire, la plupart ont sûrement pris la fuite par bateau.",
            ["DialogueId"] = 10019003,
            ["Duration"] = 2.5,
            ["GUID"] = "1914DEAE",
            ["NextDialogue"] = 10019004,
            ["SpeakNpcId"] = 100003,
            ["VoiceName"] = "voice/$Locale$/story/1001/100190/1914DEAE",
            },
        [10019004] = {
            ["Content"] = "抓紧回家拿到武器，然后去码头吧。这里现在还很危险。",
            ["ContentFR"] = "On doit vite rentrer récupérer les armes, puis filer au quai. Ici, ça reste trop dangereux.",
            ["DialogueId"] = 10019004,
            ["Duration"] = 2.5,
            ["GUID"] = "1914DEAF",
            ["NextDialogue"] = 10019005,
            ["SpeakNpcId"] = 100003,
            ["VoiceName"] = "voice/$Locale$/story/1001/100190/1914DEAF",
            },
        [10019005] = {
            ["Content"] = "（……我们现在赤手空拳，得尽量避开秽兽。）",
            ["ContentFR"] = "<I>On est complètement désarmés... Il faut éviter les Souillés à tout prix.</>",
            ["DialogueId"] = 10019005,
            ["Duration"] = 2.5,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "1914DEB1",
            ["NextDialogue"] = 10019006,
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1001/100190/1914DEB1",
            },
        [10019006] = {
            ["Content"] = "还差一点……家就在前面了。",
            ["ContentFR"] = "Encore un peu... la maison est juste devant.",
            ["DialogueId"] = 10019006,
            ["Duration"] = 2.5,
            ["GUID"] = "1914DEB2",
            ["SpeakNpcId"] = 100003,
            ["VoiceName"] = "voice/$Locale$/story/1001/100190/1914DEB2",
            },
        [10019007] = {
            ["Content"] = "（……我们现在赤手空拳，得尽量避开秽兽。）",
            ["DialogueId"] = 10019007,
            ["Duration"] = 2.5,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "1914DEB3",
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1001/100190/1914DEB1",
            },
        [10019008] = {
            ["Content"] = "还差一点……家就在前面了。",
            ["DialogueId"] = 10019008,
            ["Duration"] = 2.5,
            ["GUID"] = "1914DEB4",
            ["SpeakNpcId"] = 100003,
            ["VoiceName"] = "voice/$Locale$/story/1001/100190/1914DEB2",
            },
        [10019101] = {
            ["Content"] = "想起▇▇……▇▇，你必须▇▇▇……",
            ["ContentFR"] = "Souviens-toi de ▇▇... ▇▇, tu dois ▇▇▇...",
            ["DialogueId"] = 10019101,
            ["DisableMouth"] = 1,
            ["Duration"] = 5,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1914EEC2",
            ["RelatedWikiId"] = {
                [1] = 304001,
                [2] = 204001,
                },
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 100012,
            ["VoiceName"] = "voice/$Locale$/story/1001/100191/1914EEC2",
            },
        [10019102] = {
            ["Content"] = "你的▇▇……▇▇之力……",
            ["ContentFR"] = "Ton ▇▇... le pouvoir de ▇▇...",
            ["DialogueId"] = 10019102,
            ["DisableMouth"] = 1,
            ["Duration"] = 5,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1914EEEC",
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 100012,
            ["VoiceName"] = "voice/$Locale$/story/1001/100191/1914EEEC",
            },
        [10019103] = {
            ["Content"] = "▇▇▇渴望▇▇……这一切……",
            ["ContentFR"] = "▇▇▇ désire ▇▇... tout cela...",
            ["DialogueId"] = 10019103,
            ["DisableMouth"] = 1,
            ["Duration"] = 5,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1914EF16",
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 100012,
            ["VoiceName"] = "voice/$Locale$/story/1001/100191/1914EF16",
            },
        [10019104] = {
            ["Content"] = "你在说什么……",
            ["ContentFR"] = "Qu’est-ce que tu racontes... ? Je n’entends pas...",
            ["DialogueId"] = 10019104,
            ["DisableMouth"] = 1,
            ["Duration"] = 5,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "1914EF17",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1001/100191/1914EF17",
            },
        [10019201] = {
            ["Content"] = "关于那柄剑……除了它从小就在身边之外，我一无所知。",
            ["DialogueId"] = 10019201,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "1914FF2A",
            ["NextDialogue"] = 10019202,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1001/100192/1914FF2A",
            },
        [10019202] = {
            ["Content"] = "正如我不知道自己从何而来——我没有与贝蕾相遇之前的任何记忆。",
            ["DialogueId"] = 10019202,
            ["Duration"] = 3.5,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "1914FF54",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1001/100192/1914FF54",
            },
        [10019301] = {
            ["Content"] = "秽兽没完没了的……",
            ["ContentFR"] = "Ces Souillés... ça n’en finit pas...",
            ["DialogueId"] = 10019301,
            ["Duration"] = 3.5,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "19150F92",
            ["NextDialogue"] = 10019302,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1001/100193/19150F92",
            },
        [10019302] = {
            ["Content"] = "向上跑。甩掉它们。",
            ["ContentFR"] = "Monte. On doit les semer.",
            ["DialogueId"] = 10019302,
            ["Duration"] = 4,
            ["GUID"] = "19150FBC",
            ["SpeakNpcId"] = 100003,
            ["VoiceName"] = "voice/$Locale$/story/1001/100193/19150FBC",
            },
        [10019401] = {
            ["Content"] = "这是我第一次来科赛托斯省。看来，这里的待客之道颇为独特啊。",
            ["DialogueId"] = 10019401,
            ["Duration"] = 8,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "19151FFA",
            ["RelatedWikiId"] = {
                [1] = 408002,
                },
            ["SpeakNpcId"] = 100012,
            ["VoiceName"] = "voice/$Locale$/story/1001/100194/19151FFA",
            },
        [10019402] = {
            ["Content"] = "我没有任何恶意，只是想同你做一笔……小小的交易。",
            ["DialogueId"] = 10019402,
            ["Duration"] = 5.3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "19152024",
            ["SpeakNpcId"] = 100012,
            ["VoiceName"] = "voice/$Locale$/story/1001/100194/19152024",
            },
        [10019403] = {
            ["Content"] = "我会付给你无法拒绝的报酬，而你要做的，非常简单。",
            ["DialogueId"] = 10019403,
            ["Duration"] = 6.9,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1915204E",
            ["SpeakNpcId"] = 100012,
            ["VoiceName"] = "voice/$Locale$/story/1001/100194/1915204E",
            },
        [10019501] = {
            ["Content"] = "？？？：不杀了{性别：他|她}吗？",
            ["DialogueId"] = 10019501,
            ["Duration"] = 2.5,
            ["GUID"] = "19153057.0",
            ["SpeakNpcId"] = 100012,
            ["VoiceName"] = "voice/$Locale$/story/1001/100195/19153057",
            },
        [10019502] = {
            ["Content"] = "？？？：{性别：他|她}和您一样，拥有决定历史轨迹的力量。不要忘记，您的使命。",
            ["DialogueId"] = 10019502,
            ["Duration"] = 9,
            ["GUID"] = "19153058.0",
            ["SpeakNpcId"] = 100012,
            ["VoiceName"] = "voice/$Locale$/story/1001/100195/19153058",
            },
        [10019503] = {
            ["Content"] = "？？？：我会处理。但，现在还不是时候。",
            ["DialogueId"] = 10019503,
            ["Duration"] = 4,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "19153059.0",
            ["SpeakNpcId"] = 100012,
            ["VoiceName"] = "voice/$Locale$/story/1001/100195/19153059",
            },
        [10019504] = {
            ["Content"] = "？？？：收到。将如实提交您的答复。",
            ["DialogueId"] = 10019504,
            ["Duration"] = 5,
            ["GUID"] = "19153060.0",
            ["SpeakNpcId"] = 100012,
            ["VoiceName"] = "voice/$Locale$/story/1001/100195/19153060",
            },
        [10019505] = {
            ["Content"] = "？？？：……听着，{NickName}。",
            ["DialogueId"] = 10019505,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "19153061.0",
            ["SpeakNpcId"] = 100012,
            ["VoiceName"] = "voice/$Locale$/story/1001/100195/19153061",
            },
        [10019506] = {
            ["Content"] = "？？？：“生命是航行在无尽长夜里的孤船。”",
            ["DialogueId"] = 10019506,
            ["Duration"] = 4,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "19153062.0",
            ["SpeakNpcId"] = 100012,
            ["VoiceName"] = "voice/$Locale$/story/1001/100195/19153062",
            },
        [10019507] = {
            ["Content"] = "？？？：“河流泪水满溢，夹岸荆棘丛生。”",
            ["DialogueId"] = 10019507,
            ["Duration"] = 4,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1915308C",
            ["SpeakNpcId"] = 100012,
            ["VoiceName"] = "voice/$Locale$/story/1001/100195/1915308C",
            },
        [10019508] = {
            ["Content"] = "？？？：“我会一直注视着……”",
            ["DialogueId"] = 10019508,
            ["Duration"] = 4,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "191530B6",
            ["SpeakNpcId"] = 100012,
            ["VoiceName"] = "voice/$Locale$/story/1001/100195/191530B6",
            },
        [10019509] = {
            ["Content"] = "？？？：“来自彼岸之人，你将驶向何方。”",
            ["DialogueId"] = 10019509,
            ["Duration"] = 5,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "191530E0",
            ["SpeakNpcId"] = 100012,
            ["VoiceName"] = "voice/$Locale$/story/1001/100195/191530E0",
            },
        [10019510] = {
            ["Content"] = "（是谁……）",
            ["DialogueId"] = 10019510,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1915310A",
            ["SpeakNpcId"] = 100012,
            ["VoiceName"] = "voice/$Locale$/story/1001/100195/1915310A",
            },
        [10025701] = {
            ["Content"] = "这场逃亡，是从那场奇异的梦开始的；从小到大，我一直重复着相似的梦。",
            ["ContentFR"] = "Cette fuite... elle a commencé avec ce rêve étrange. Depuis mon enfance, je suis {性别:hanté|hantée} par des rêves similaires.",
            ["DialogueId"] = 10025701,
            ["Duration"] = 3,
            ["GUID"] = "19192992",
            ["NextDialogue"] = 10025702,
            ["VoiceName"] = "voice/$Locale$/story/1002/100257/19192992",
            },
        [10025702] = {
            ["Content"] = "但不容回想，我知道此刻有更急迫的事——",
            ["ContentFR"] = "Mais ce n’est pas le moment de se perdre dans le passé. Il y a plus urgent, à présent...",
            ["DialogueId"] = 10025702,
            ["Duration"] = 3,
            ["GUID"] = "191929BC",
            ["NextDialogue"] = 10025703,
            ["VoiceName"] = "voice/$Locale$/story/1002/100257/191929BC",
            },
        [10025703] = {
            ["Content"] = "必须和贝蕾妮卡一起逃离这座叫做“净界岛”的小岛，即使这是我们一起长大的地方。",
            ["ContentFR"] = "Berry et moi devons fuir l’Île du Purgatoire, même si c’est ici que nous avons grandi ensemble.",
            ["DialogueId"] = 10025703,
            ["Duration"] = 4,
            ["GUID"] = "191929E6",
            ["VoiceName"] = "voice/$Locale$/story/1002/100257/191929E6",
            },
        [10025704] = {
            ["Content"] = "因为我们平静的生活，早已被秽兽的利爪撕碎……",
            ["ContentFR"] = "Car notre vie paisible a déjà été déchirée, mise en pièces par les griffes impies des Souillés.",
            ["DialogueId"] = 10025704,
            ["Duration"] = 3,
            ["GUID"] = "19192A10",
            ["VoiceName"] = "voice/$Locale$/story/1002/100257/19192A10",
            },
        [10025801] = {
            ["Content"] = "这些秽兽……死了？",
            ["ContentFR"] = "Ces Souillés... sont morts ?",
            ["DialogueId"] = 10025801,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "191939FA",
            ["NextDialogue"] = 10025802,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1001/100258/191939FA",
            },
        [10025802] = {
            ["Content"] = "看来在我们之前，这里就有人和秽兽战斗过。而且，还没过去太久。",
            ["ContentFR"] = "Quelqu’un les a déjà affrontés... juste avant notre arrivée.",
            ["DialogueId"] = 10025802,
            ["GUID"] = "19193A24",
            ["NextDialogue"] = 10025803,
            ["SpeakNpcId"] = 100003,
            ["VoiceName"] = "voice/$Locale$/story/1001/100258/19193A24",
            },
        [10025803] = {
            ["Content"] = "难道有村民逃到了这里……不，那扇门是我们打开的才对。",
            ["ContentFR"] = "Serait-ce un villageois qui a trouvé refuge ici... ? Non. Cette porte, c’est nous qui l’avons ouverte.",
            ["DialogueId"] = 10025803,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "19193A4E",
            ["NextDialogue"] = 10025804,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1001/100258/19193A4E",
            },
        [10025804] = {
            ["Content"] = "不过好在有他帮忙清理，否则秽兽就更难对付了。",
            ["ContentFR"] = "Enfin... grâce à lui, le passage est dégagé. Sinon, ça aurait été encore plus difficile.",
            ["DialogueId"] = 10025804,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "19193A78",
            ["NextDialogue"] = 10025805,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1001/100258/19193A78",
            },
        [10025805] = {
            ["Content"] = "无论是谁，他的实力都不容小觑。我们也要留心。",
            ["ContentFR"] = "Qui que ce soit, il ne faut pas le sous-estimer. Restons sur nos gardes.",
            ["DialogueId"] = 10025805,
            ["GUID"] = "19193AA2",
            ["SpeakNpcId"] = 100003,
            ["VoiceName"] = "voice/$Locale$/story/1001/100258/19193AA2",
            },
        [10025806] = {
            ["Content"] = "这些秽兽……断气了？",
            ["DialogueId"] = 10025806,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "19193AA3",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1001/100258/19193AA3",
            },
        [10027501] = {
            ["Content"] = "在不远处……",
            ["DialogueId"] = 10027501,
            ["Duration"] = 2,
            ["GUID"] = "191A50E2",
            ["VoiceName"] = "voice/$Locale$/story/1001/100275/191A50E2",
            },
        [10029301] = {
            ["Content"] = "无数次，螺旋般往复的梦中，我一遍又一遍地问着。",
            ["ContentFR"] = "Dans mes rêves qui se répètent en spirales, je me pose cette question encore et encore.",
            ["DialogueId"] = 10029301,
            ["Duration"] = 0.5,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "1914AD4C",
            ["NextDialogue"] = 10018401,
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/100293/1914AD4C",
            },
        [10029309] = {
            ["Content"] = "恭喜你起名完成啦！！！！！",
            ["DialogueId"] = 10029309,
            ["Duration"] = 3,
            ["GUID"] = "1914AD4D",
            ["VoiceName"] = "voice/$Locale$/story/1002/100293/",
            },
        [10029401] = {
            ["Content"] = "要再休息一会儿吗？",
            ["ContentFR"] = "Veux-tu te reposer encore un peu ?",
            ["DialogueId"] = 10029401,
            ["GUID"] = "1914AD4E",
            ["SpeakNpcId"] = 100003,
            },
        [10030101] = {
            ["Content"] = "呼…呼…",
            ["ContentFR"] = "Haa... haa...",
            ["DialogueId"] = 10030101,
            ["Duration"] = 3,
            ["GUID"] = "191BFB72",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1003/100301/191BFB72",
            },
        [10030201] = {
            ["DialogueId"] = 10030201,
            ["Duration"] = 3,
            ["GUID"] = "191C0BDA",
            ["VoiceName"] = "voice/$Locale$/story/1003/100302/191C0BDA",
            },
        [10030202] = {
            ["Content"] = "打开推理小游戏",
            ["DialogueId"] = 10030202,
            ["GUID"] = "191C0BDB",
            },
        [10030301] = {
            ["Camera"] = "-229.695435,48.554688,189.588501,0.000025,-8.400114,39.796463,35.0,100000.0,false,Manual,22.0",
            ["Content"] = "……卡米拉？",
            ["ContentFR"] = "... Camilla ?",
            ["DialogueId"] = 10030301,
            ["GUID"] = "191C1C42",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1003/100303/191C1C42",
            },
        [10030302] = {
            ["Content"] = "嘴里的药，先咽下去。",
            ["ContentFR"] = "Avale le médicament d’abord.",
            ["DialogueId"] = 10030302,
            ["GUID"] = "191C1C6C",
            ["SpeakNpcId"] = 200003,
            ["VoiceName"] = "voice/$Locale$/story/1003/100303/191C1C6C",
            },
        [10030401] = {
            ["Camera"] = "67.060974,63.269043,215.128113,0.000134,-36.998093,133.003891,35.000015,115.415909,false,Manual,2.8",
            ["Content"] = "你……我这是……",
            ["ContentFR"] = "Vous... J’étais...",
            ["DialogueId"] = 10030401,
            ["FacialId"] = {
                [1] = "100001:Sad01",
                },
            ["FinalCamera"] = "58.562622,72.381348,205.739349,0.000134,-36.998093,133.003891,35.000015,115.415909,false,Manual,2.8",
            ["GUID"] = "191C2CAA",
            ["LookAt"] = {
                [1] = "100001:n(200003)",
