            ["NextDialogue"] = 10030402,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Explain02_Start",
                },
            ["ToFinalCameraBlendTime"] = 4,
            ["VoiceName"] = "voice/$Locale$/story/1003/100304/191C2CAA",
            },
        [10030402] = {
            ["Camera"] = "86.758911,282.283203,92.856476,0.000175,5.190773,-113.187576,35.000011,284.956726,false,Manual,2.8",
            ["Content"] = "睡了五天，运气不错。再多一天，这辈子可能都醒不过来了。",
            ["ContentFR"] = "Tu as dormi cinq jours. Tu as eu de la chance, un de plus, et tu ne te serais sans doute jamais réveillé.",
            ["DialogueId"] = 10030402,
            ["FinalCamera"] = "86.758911,282.283203,92.856476,0.00018,11.790866,-114.790039,35.000011,284.956726,false,Manual,2.8",
            ["GUID"] = "191C2CD4",
            ["NextDialogue"] = 10030403,
            ["SpeakNpcId"] = 200003,
            ["TalkActionId"] = {
                [1] = "200003:Talk03_Start",
                },
            ["ToFinalCameraBlendTime"] = 4,
            ["VoiceName"] = "voice/$Locale$/story/1003/100304/191C2CD4",
            },
        [10030403] = {
            ["Camera"] = "86.758911,282.283203,92.856476,0.000164,14.190912,-114.991394,35.000008,284.956726,false,Manual,2.8",
            ["Content"] = "所以，这些天是你在……谢……",
            ["ContentFR"] = "Alors... pendant tout ce temps, c’est vous qui... merci...",
            ["DialogueId"] = 10030403,
            ["FacialId"] = {
                [1] = "100001:None",
                },
            ["GUID"] = "191C2CFE",
            ["NextDialogue"] = 10030404,
            ["SpeakNpcId"] = 100001,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/story/1003/100304/191C2CFE",
            },
        [10030404] = {
            ["Camera"] = "68.587265,188.526855,131.323135,0.000194,3.19883,-111.220688,35.000015,153.176254,false,Manual,2.8",
            ["Content"] = "不用谢我。你现在可今非昔比了，因为上次群星绮晶的事，现在可有不少委托指名让你去呢。",
            ["ContentFR"] = "Pas besoin de me remercier. Tu n’es plus {性别:le|la} même qu’avant. Depuis l’affaire de l’Éclat stellaire, il y a pas mal de missions qui te demandent en particulier.",
            ["DialogueId"] = 10030404,
            ["FinalCamera"] = "68.587265,188.526855,131.323135,0.000192,7.598797,-111.820282,35.000015,153.176254,false,Manual,2.8",
            ["GUID"] = "191C2D28",
            ["NextDialogue"] = 10030405,
            ["SpeakNpcId"] = 200003,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/story/1003/100304/191C2D28",
            },
        [10030405] = {
            ["Camera"] = "98.511124,-16.412109,172.841675,0.000205,-11.603302,130.15361,35.000019,202.161392,false,Manual,2.8",
            ["Content"] = "可别活还没干完，人先没了。",
            ["ContentFR"] = "Assure-toi juste de rester en vie assez longtemps pour finir le travail.",
            ["DialogueId"] = 10030405,
            ["GUID"] = "191C2D52",
            ["NextOptions"] = {
                [1] = 10030406,
                [2] = 10030408,
                },
            ["SpeakNpcId"] = 200003,
            ["TalkActionId"] = {
                [1] = "200003:Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100304/191C2D52",
            },
        [10030406] = {
            ["Content"] = "卡米拉女士真是嘴硬心软。",
            ["ContentFR"] = "<I>Camilla, vous êtes vraiment dure en apparence... mais douce à l’intérieur.</>",
            ["DialogueId"] = 10030406,
            ["GUID"] = "191C2D7C",
            ["ImprPlusId"] = 1008,
            ["NextDialogue"] = 10030407,
            },
        [10030407] = {
            ["Camera"] = "42.419052,245.519531,108.856918,0.000246,12.994878,-104.423546,35.000015,203.457535,false,Manual,2.8",
            ["Content"] = "油嘴滑舌。跟奥特赛德学的？",
            ["ContentFR"] = "Quelle langue bien pendue. Tu as appris ça de l’Étranger ?",
            ["DialogueId"] = 10030407,
            ["GUID"] = "191C2DA6",
            ["LookAt"] = {
                [1] = "200003:n(100001)",
                },
            ["NextDialogue"] = 10030411,
            ["SpeakNpcId"] = 200003,
            ["TalkActionId"] = {
                [1] = "200003:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100304/191C2DA6",
            },
        [10030408] = {
            ["Content"] = "……要不，还是让我死一会儿？",
            ["ContentFR"] = "<I>... Peut-être que j’aurais mieux fait de rester {性别:mort|morte} encore un peu.</>",
            ["DialogueId"] = 10030408,
            ["GUID"] = "191C2DD0",
            ["ImprPlusId"] = 1010,
            ["NextDialogue"] = 10030409,
            },
        [10030409] = {
            ["Camera"] = "42.419052,245.519531,108.856918,0.000246,12.994892,-104.423515,35.000015,243.87735,false,Manual,2.8",
            ["Content"] = "呵，现在后悔被我救下也来不及了。",
            ["ContentFR"] = "Eh. Trop tard pour regretter de t’avoir sauvé.",
            ["DialogueId"] = 10030409,
            ["GUID"] = "191C2DFA",
