            ["VoiceName"] = "voice/$Locale$/story/1003/100306/191C4EA0",
            },
        [10030609] = {
            ["Content"] = "很好，我就知道“不死的白色骑士，重生的夜航之星，被赐福的恶魔伯爵”不会随便抛下魔王大人不管的！",
            ["ContentFR"] = "Parfait ! Je savais bien que \"{性别:le Chevalier Blanc immortel, l’Étoile renaissante des Vagabonds de la Nuit, le Comte Démon béni|la Chevalière Blanche immortelle, l’Étoile renaissante des Vagabonds de la Nuit, la Comtesse Démon bénie}\" n’abandonnerait jamais son Roi Démon !",
            ["DialogueId"] = 10030609,
            ["FacialId"] = {
                [1] = "200002:Happy02",
                },
            ["GUID"] = "191C4ECA",
            ["NextDialogue"] = 10030610,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1003/100306/191C4ECA",
            },
        [10030610] = {
            ["Content"] = "你坐在这里不要动，我去给你拿点水果补补身子！",
            ["ContentFR"] = "Ne bouge pas d’ici, j’vais te chercher des fruits bien frais pour reprendre des forces !",
            ["DialogueId"] = 10030610,
            ["FacialId"] = {
                [1] = "200002:None",
                },
            ["GUID"] = "191C4EF4",
            ["NextDialogue"] = 10030631,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Confident_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100306/191C4EF4",
            },
        [10030611] = {
            ["Camera"] = "-205.596069,-83.395508,180.607422,0.000125,-12.400939,31.862019,35.282173,323.045349,false,Manual,6.0",
            ["Content"] = "（怎么称呼变长以后，爵位反而更低了！等等……不能被白奇怪的称呼拐走话题。）",
            ["ContentFR"] = "<I>Comment ça, plus le titre est long, plus le rang baisse ?! ... Non, je dois pas me laisser distraire par ses bêtises.</>",
            ["DialogueId"] = 10030611,
            ["DisableMouth"] = 1,
            ["GUID"] = "191C4F1E",
            ["LookAt"] = {
                [1] = "100001:n(200021)",
                },
            ["NextDialogue"] = 10030612,
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1003/100306/191C4F1E",
            },
        [10030612] = {
            ["Camera"] = "-205.596069,-83.395508,180.607422,0.000125,-12.400939,31.862019,35.282173,323.045349,false,Manual,6.0",
            ["Content"] = "刚才你们在说什么……<H>卡戎狩猎</>？那是什么？",
            ["ContentFR"] = "Tout à l’heure, vous parliez d’une... <H>Traque aux Charons</> ? C’est quoi exactement ?",
            ["DialogueId"] = 10030612,
            ["GUID"] = "191C4F48",
            ["LookAt"] = {
                [1] = "100001:n(200021)",
                },
            ["NextDialogue"] = 10030613,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100306/191C4F48",
            },
        [10030613] = {
            ["Camera"] = "190.638672,10.195312,120.152344,0.000129,5.198969,171.649796,35.282173,291.788361,false,Manual,6.0",
            ["Content"] = "是桩你逃不开的大麻烦。",
            ["ContentFR"] = "Un sacré pétrin, dont tu pourras pas t’échapper.",
            ["DialogueId"] = 10030613,
            ["FacialId"] = {
                [1] = "200021:Angry01",
                },
            ["GUID"] = "191C4F72",
            ["LookAt"] = {
