        [10030615] = {
            ["Content"] = "呜哇！",
            ["ContentFR"] = "Hiiih !",
            ["DialogueId"] = 10030615,
            ["FacialId"] = {
                [1] = "200002:Shock02",
                },
            ["GUID"] = "191C4FC6",
            ["LookAt"] = {
                [1] = "200002:n(100304)",
                },
            ["NextDialogue"] = 10030616,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Shock_Start",
                [2] = "200021:Explain01_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100306/191C4FC6",
            },
        [10030616] = {
            ["Camera"] = "1297.798462,-671.682617,65.072266,0.000065,-0.601719,155.368057,35.000008,116.489357,false,Manual,3.0",
            ["Content"] = "喏，来了来了。麻烦一蹬腿不动弹了——麻烦死喽。",
            ["ContentFR"] = "Tiens, la voilà... Le pétrin en personne. Et elle est pas du genre à lâcher l’affaire.",
            ["DialogueId"] = 10030616,
            ["FacialId"] = {
                [1] = "200002:None",
                },
            ["FinalCamera"] = "1297.798462,-671.682617,65.072266,0.000066,-0.601685,155.368103,35.000008,2653.720459,false,Manual,3.0",
            ["GUID"] = "191C4FF0",
            ["LookAt"] = {
                [1] = "200021:n(100304)",
                [2] = "100001:n(100304)",
                },
            ["NextDialogue"] = 10030617,
            ["SpeakNpcId"] = 200021,
            ["TalkActionId"] = {
                [1] = "200021:Confident_Start",
                },
            ["ToFinalCameraBlendTime"] = 4,
            ["TurnTo"] = {
                [1] = "100001:n(100304)",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100306/191C4FF0",
            },
        [10030617] = {
            ["Camera"] = "230.647583,-1.03125,119.628906,0.000082,4.597776,170.360352,35.0,130.051529,false,DoNotOverride,3.0",
            ["Content"] = "……黎瑟·费西尔？",
            ["ContentFR"] = "... Rhythm Fischer ?",
            ["DialogueId"] = 10030617,
            ["GUID"] = "191C501A",
            ["NextDialogue"] = 10030618,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Explain01_End",
                [2] = "200002:Shock_End",
                [3] = "200021:Confident_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100306/191C501A",
            },
        [10030618] = {
            ["Content"] = "对，又来了。她基本每天这个点都要来问一次。",
            ["ContentFR"] = "Ouais. Elle débarque presque tous les jours, à la même heure, pour prendre des nouvelles.",
            ["DialogueId"] = 10030618,
            ["GUID"] = "191C5044",
            ["NextDialogue"] = 10030619,
            ["SpeakNpcId"] = 200021,
            ["TalkActionId"] = {
                [1] = "200021:AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100306/191C5044",
            },
        [10030619] = {
            ["Content"] = "……既然你说了“又”，那就说明这几天已经应付过她很多次了。交给你了，奥特赛德，加油，你可以的。",
            ["ContentFR"] = "... Vu que tu dis « tous les jours », ça veut dire que tu t’en es déjà occupé plusieurs fois. Je te la laisse. Allez, courage, tu gères.",
            ["DialogueId"] = 10030619,
            ["GUID"] = "191C506E",
            ["LookAt"] = {
                [1] = "200021:n(100001)",
                [2] = "100001:n(200021)",
                },
            ["NextDialogue"] = 10030620,
            ["SpeakNpcId"] = 100001,
            ["TurnTo"] = {
                [1] = "100001:n(200021)",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100306/191C506E",
            },
        [10030620] = {
            ["Content"] = "等等，先别走。唉，我说过，这麻烦你逃不掉的。",
            ["ContentFR"] = "Minute, pas si vite. Je te l’ai dit, ce genre de pétrin, tu pourras pas l’esquiver.",
            ["DialogueId"] = 10030620,
            ["GUID"] = "191C5098",
            ["LookAt"] = {
                [1] = "200002:n(100001)",
                },
            ["NextDialogue"] = 10030621,
            ["SpeakNpcId"] = 200021,
            ["TalkActionId"] = {
                [1] = "200021:DisagreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100306/191C5098",
            },
        [10030621] = {
            ["Content"] = "<W>卡戎狩猎</>是近期发生在外城的<W>连环凶案</>，你作为唯一幸存者不可能不被军团问话，时间早晚而已。",
            ["ContentFR"] = "La <W>Traque aux Charons</>... ce sont des <W>meurtres en série</> qui secouent la cité extérieure. Comme tu es l’unique {性别:survivant|survivante}, la Légion ne peut pas faire autrement que de t’interroger. La question, c’était juste quand.",
            ["DialogueId"] = 10030621,
            ["GUID"] = "191C50C2",
            ["NextDialogue"] = 10030622,
            ["SpeakNpcId"] = 200021,
            ["TalkActionId"] = {
                [1] = "200021:Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100306/191C50C2",
            },
        [10030622] = {
            ["Content"] = "我看这位黎瑟女士还挺好说话的，这在军团可不多见。要是换个凶神恶煞的来，还不如她呢。",
            ["ContentFR"] = "Et franchement, tomber sur elle, c’est pas le pire. Dans la Légion, t’en as des bien plus brutaux. Crois-moi, tu préféreras encore avoir affaire à cette Fischer plutôt qu’à d’autres.",
            ["DialogueId"] = 10030622,
            ["GUID"] = "191C50EC",
            ["NextOptions"] = {
                [1] = 10030623,
                [2] = 10030624,
                },
            ["SpeakNpcId"] = 200021,
            ["VoiceName"] = "voice/$Locale$/story/1003/100306/191C50EC",
            },
        [10030623] = {
            ["Content"] = "…………",
            ["ContentFR"] = "<I>...</>",
            ["DialogueId"] = 10030623,
            ["GUID"] = "191C5116",
            ["NextDialogue"] = 10030625,
            },
        [10030624] = {
            ["Content"] = "……我不太想见她。",
            ["ContentFR"] = "<I>... Je n’ai pas trop envie de la voir.</>",
            ["DialogueId"] = 10030624,
            ["GUID"] = "191C5140",
            ["NextDialogue"] = 10030625,
            },
        [10030625] = {
            ["Content"] = "好吧，你的意思我懂了。既然你还没做好准备，那就还是先由我——",
            ["ContentFR"] = "D’accord, j’ai compris. Si tu n’es pas {性别:prêt|prête}, je peux encore essayer de—",
            ["DialogueId"] = 10030625,
            ["GUID"] = "191C516A",
            ["NextDialogue"] = 10030626,
            ["SpeakNpcId"] = 200021,
            ["TalkActionId"] = {
                [1] = "200021:Talk01_End",
                },
            ["TurnTo"] = {
                [1] = "100304:n(100001)",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100306/191C516A",
            },
        [10030626] = {
            ["Camera"] = "3.56424,135.133789,143.957031,0.000086,-7.202332,-42.028748,35.000008,998.946716,false,Manual,3.0",
            ["Content"] = "{nickname}，你终于醒了。我有件重要的事，希望你配合——",
            ["ContentFR"] = "{nickname}, enfin {性别:réveillé|réveillée} ! J’ai une affaire importante, j’aurais besoin de votre coopération.",
            ["DialogueId"] = 10030626,
            ["GUID"] = "191C5194",
            ["NextDialogue"] = 10030627,
            ["SpeakNpcId"] = 100304,
            ["TalkActionId"] = {
                [1] = "100304:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100306/191C5194",
            },
        [10030627] = {
            ["Camera"] = "3.56424,135.133789,143.957031,0.000086,-7.202332,-42.028748,35.000008,998.946716,false,Manual,3.0",
            ["Content"] = "……她看到了！",
            ["ContentFR"] = "... {性别:Elle m’a vu|Elle m’a vue} !",
            ["DialogueId"] = 10030627,
            ["FacialId"] = {
                [1] = "100001:Unhappy01",
                },
            ["GUID"] = "191C51BE",
