            },
        [10030628] = {
            ["Camera"] = "230.647583,-1.03125,119.628906,0.000082,4.597776,170.360352,35.0,130.051529,false,DoNotOverride,3.0",
            ["Content"] = "那就没办法了，去吧{性别：兄弟|朋友}，该来的总会来的。",
            ["ContentFR"] = "Eh ben voilà. Courage, mon {性别:ami|amie}, ce qui doit arriver finit toujours par arriver.",
            ["DialogueId"] = 10030628,
            ["GUID"] = "191C51E8",
            ["LookAt"] = {
                [1] = "200021:n(100304)",
