            ["VoiceName"] = "voice/$Locale$/story/1003/100306/191C51E8",
            },
        [10030629] = {
            ["Content"] = "唉，真是甩不掉的麻烦啊。",
            ["ContentFR"] = "Pff... impossible de s’en débarrasser, ce pétrin-là.",
            ["DialogueId"] = 10030629,
            ["FacialId"] = {
                [1] = "100001:None",
                },
            ["GUID"] = "191C5212",
            ["LookAt"] = {
