            },
        [10030719] = {
            ["Camera"] = "-159.366272,-113.829102,114.5625,0.000285,10.592653,64.027985,35.000019,242.113937,false,Manual,6.0",
            ["Content"] = "喂，发什么呆呢？",
            ["ContentFR"] = "Eh, tu attends quoi ?",
            ["DialogueId"] = 10030719,
            ["GUID"] = "191C5F08",
            ["LookAt"] = {
                [1] = "100001:n(100304)",
                [2] = "200021:n(100001)",
                [3] = "200002:n(100001)",
                },
            ["NextDialogue"] = 10030720,
            ["Scripts"] = "SetLocation{ActorId{100304},TargetPoint{\"lise_03_leave\"},Visibility{\"Hide\"}}",
            ["SpeakNpcId"] = 200021,
            ["TalkActionId"] = {
