                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1003/100310/191C8F1A",
            },
        [10031002] = {
            ["Content"] = "嗯，记得。",
            ["ContentFR"] = "<I>Oui, je m’en souviens.</>",
            ["DetectiveQuestionId"] = 1001,
            ["DialogueId"] = 10031002,
            ["GUID"] = "191C8F44",
            ["ImprPlusId"] = 1007,
            ["NextDialogue"] = 10031004,
            },
        [10031003] = {
            ["Content"] = "要是你走在路上被人敲一闷棍也不可能忘吧。",
            ["ContentFR"] = "<I>Si on vous assomme en pleine rue, ça ne s’oublie pas.</>",
            ["DetectiveQuestionId"] = 1001,
            ["DialogueId"] = 10031003,
            ["GUID"] = "191C8F6E",
            ["ImprPlusId"] = 1010,
            ["NextDialogue"] = 10031004,
            },
        [10031004] = {
            ["Camera"] = "90.230469,-472.615723,119.978027,0.000191,-0.400393,102.218979,40.0,941.904541,false,DoNotOverride,1.2",
            ["Content"] = "那么，你还记得遇袭的大致时间吗？",
            ["ContentFR"] = "Alors, vous souvenez-vous de l’heure approximative de l’attaque ?",
            ["DetectiveQuestionId"] = 1001,
            ["DialogueId"] = 10031004,
            ["FacialId"] = {
                [1] = "100304:Doubt01",
                },
            ["FinalCamera"] = "90.230469,-472.615723,130.0,0.000199,-0.400393,102.219009,40.0,941.904541,false,DoNotOverride,1.2",
            ["GUID"] = "191C8F98",
            ["NextDialogue"] = 10031005,
            ["Scripts"] = "LookAt{_delay{2},LookAtDescription{\"100304:n(100001)\"}}",
            ["SpeakNpcId"] = 100304,
            ["TalkActionId"] = {
                [1] = "100304:Explain01_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1003/100310/191C8F98",
            },
        [10031005] = {
            ["Camera"] = "-64.777344,-47.655518,128.217285,0.000165,-0.000854,-48.591522,40.0,941.904541,false,DoNotOverride,1.2",
            ["Content"] = "不记得。那时我……心情不太好。觉得回家也多半睡不着，就想着在城里散散心。",
            ["ContentFR"] = "Non... Pas vraiment. À ce moment-là, je ne me sentais pas très bien. Je savais que je ne trouverais pas le sommeil, alors j’ai {性别:préféré|préférée} marcher un peu en ville.",
            ["DetectiveQuestionId"] = 1001,
            ["DialogueId"] = 10031005,
            ["FacialId"] = {
                [1] = "100001:None",
                },
            ["FinalCamera"] = "-66.598633,-49.306152,128.217285,0.000165,-0.000854,-46.391235,40.0,941.904541,false,DoNotOverride,1.2",
            ["GUID"] = "191C8FC2",
            ["NextDialogue"] = 10031006,
            ["Scripts"] = "PlayAnimation{_delay{3},ActorId{100001},AnimationId{\"ScratchHead_End\"},Duration{2}}",
