            ["TalkActionId"] = {
                [1] = "100001:ScratchHead_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1003/100310/191C8FC2",
            },
        [10031006] = {
            ["Camera"] = "-401.587891,135.657227,245.506836,0.000158,-15.000843,-35.580502,35.0,941.904541,false,DoNotOverride,22",
            ["Content"] = "具体的时间……我……当时在想其他事，不记得了。",
            ["ContentFR"] = "Pour l’heure exacte... j’étais préoccupé, mes pensées étaient ailleurs. Je ne m’en rappelle pas.",
            ["DetectiveQuestionId"] = 1001,
            ["DialogueId"] = 10031006,
            ["FacialId"] = {
                [1] = "100001:Think01",
                },
            ["FinalCamera"] = "-408.319336,125.966064,245.506836,0.000153,-15.000843,-32.580688,35.0,941.904541,false,DoNotOverride,22",
            ["GUID"] = "191C8FEC",
