            },
        [10031010] = {
            ["Camera"] = "120.47168,-462.604004,186.308594,0.000047,-12.402864,110.025742,35.0,941.904541,false,DoNotOverride,1.903106",
            ["Content"] = "（把这个信息告诉黎瑟吧。）",
