            },
        [10031106] = {
            ["Camera"] = "5.640625,-44.589111,120.307129,0.000218,2.797017,-73.17907,35.000015,324.824371,false,DoNotOverride,22",
            ["Content"] = "等等，还有一件事！",
            ["ContentFR"] = "Attendez, si ! Il y a encore une chose !",
            ["DialogueId"] = 10031106,
            ["FacialId"] = {
                [1] = "100001:Shock01",
