            },
        [10031107] = {
            ["Content"] = "请说！",
            ["ContentFR"] = "Je vous écoute !",
            ["DialogueId"] = 10031107,
            ["FacialId"] = {
                [1] = "100001:None",
                },
            ["GUID"] = "191CA07E",
