        [10031703] = {
            ["Camera"] = "-86.515625,-65.973633,106.226318,0.000065,7.599678,-10.196134,35.000011,1068.077393,false,DoNotOverride,1.2",
            ["Content"] = "（那是什么味道啊！）",
            ["ContentFR"] = "<I>C’est quoi, cette description d’odeur !</>",
            ["DetectiveQuestionId"] = 1004,
            ["DialogueId"] = 10031703,
            ["DisableMouth"] = 1,
            ["FacialId"] = {
                [1] = "100001:Doubt01",
