        [10031803] = {
            ["Camera"] = "-132.708008,65.039062,117.88916,0.000001,4.998906,-11.002963,35.000008,100000.0,false,Manual,22.0",
            ["Content"] = "长官，你之前不是管这一带的吧，最近刚调过来的？",
            ["ContentFR"] = "Officier, vous n’étiez pas en charge de ce secteur auparavant, pas vrai ? Vous venez d’être affectée ici ?",
            ["DialogueId"] = 10031803,
            ["FacialId"] = {
                [1] = "200021:Smile01",
                },
            ["FinalCamera"] = "-179.000977,74.04187,113.763672,0.0,4.598903,-11.002993,35.000008,100000.0,false,Manual,22.0",
            ["GUID"] = "191D12AE",
            ["NextDialogue"] = 10031804,
            ["SpeakNpcId"] = 200021,
            ["TalkActionId"] = {
                [1] = "200021:Confident_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1003/100318/191D12AE",
            },
        [10031804] = {
            ["Camera"] = "-16.977539,46.6698,125.709717,0.000075,6.600018,-144.78064,35.000011,100000.0,false,DoNotOverride,22",
            ["Content"] = "是的，我以前在西区做其他差事。上个月我升任准尉，长官把我调到了这里，负责东区的安全。",
            ["ContentFR"] = "Oui. Avant, je travaillais dans le quartier ouest. Le mois dernier, j’ai été promue adjudante et on m’a transférée ici, responsable de la sécurité du quartier est.",
            ["DialogueId"] = 10031804,
            ["FacialId"] = {
                [1] = "100304:Confident01",
                },
            ["FinalCamera"] = "-19.689453,50.511108,125.709717,0.000077,6.600018,-142.580902,35.000011,100000.0,false,DoNotOverride,22",
            ["GUID"] = "191D12D8",
            ["NextDialogue"] = 10031805,
            ["Scripts"] = "PARA{SEQ{CameraMoveTo{_delay{3},TargetPosition{\"204.946777,101.599731,159.530762,0.000074,-7.599855,-152.38298,35.000008,100000.0,false,Manual,22.0\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"207.978027,96.109253,159.530762,0.000074,-7.599855,-152.383148,35.000008,100000.0,false,Manual,22.0\"},duration{5}}},PlayAnimation{_delay{3},ActorId{100304},AnimationId{\"Talk03_Start\"},Duration{2}}}",
