        [10031906] = {
            ["Camera"] = "225.256836,170.580078,47.830078,0.000078,9.399993,-157.992004,40.0,676.431458,false,DoNotOverride,3.853879",
            ["Content"] = "我去工厂吧，我的身份调查起来更方便，而且那里有我一些老相识。",
            ["ContentFR"] = "Je vais prendre la zone industrielle. Mon statut facilitera l’enquête là-bas, et j’y connais encore quelques anciens camarades.",
