        [10031910] = {
            ["Camera"] = "-585.371094,624.871887,401.661133,0.000048,-17.12187,-52.0401,30.0,100000.0,false,Manual,22.0",
            ["Content"] = "算了，不说这些了，我们也动身吧，队长。",
            ["ContentFR"] = "Enfin, bref. Allons-y aussi, capitaine.",
