        [10032107] = {
            ["Camera"] = "-293.615234,-376.854492,46.109375,0.000463,6.997617,64.301308,35.000008,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "对演员来说，完成演出就是在诠释生命，这比生命本身更加璀璨耀眼。不让他们演出，才是要了他们的命。",
            ["ContentFR"] = "Pour un comédien, jouer une pièce, c’est incarner la vie elle-même. Plus éclatante, plus radieuse que la vie en soi. Leur interdire la scène, ce serait pire que la mort.",
            ["DialogueId"] = 10032107,
            ["FinalCamera"] = "-299.095703,-374.287598,46.109375,0.000462,6.997617,63.701469,35.000008,100000.0,false,DoNotOverride,22.0",
            ["GUID"] = "191D448E",
            ["NextDialogue"] = 10032108,
            ["Scripts"] = "SEQ{CameraMoveTo{_delay{7},TargetPosition{\"102.716476,171.84108,50.386719,0.000454,10.197875,-148.500732,35.0,100000.0,false,DoNotOverride,22.0\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"102.716476,171.84108,55.585938,0.000454,9.397876,-148.300888,35.0,100000.0,false,DoNotOverride,22.0\"},duration{8}}}",
            ["SpeakNpcId"] = 100313,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1003/100321/191D448E",
            },
        [10032108] = {
            ["Camera"] = "-601.805847,769.078125,-62.539062,-3.000002,9.000303,-56.889706,35.000008,945.516907,false,DoNotOverride,1.608127",
            ["Content"] = "所有人准备，今天第三场排练五分钟后开始。",
            ["ContentFR"] = "Tout le monde en place ! Troisième répétition dans cinq minutes !",
            ["DialogueId"] = 10032108,
            ["FinalCamera"] = "-601.805847,769.078125,-32.179688,-3.000001,7.000288,-56.890057,35.000008,945.516907,false,DoNotOverride,1.608127",
            ["GUID"] = "191D44B8",
            ["LookAt"] = {
                [1] = "100313:n(100313)",
                },
            ["Scripts"] = "PlayAnimation{_delay{4},ActorId{100313},AnimationId{\"Confident_Start\"},Duration{2}}",
            ["SpeakNpcId"] = 100313,
            ["ToFinalCameraBlendTime"] = 10,
            ["TurnTo"] = {
                [1] = "100313:p(180)",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100321/191D44B8",
            },
        [10032109] = {
            ["Content"] = "……呜，真是一点都不肯配合呢。",
            ["ContentFR"] = "... Pff, elle ne veut vraiment rien savoir.",
            ["DialogueId"] = 10032109,
            ["GUID"] = "191D44E2",
            ["NextDialogue"] = 10032110,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1003/100321/191D44E2",
            },
        [10032110] = {
            ["Content"] = "分头问问看吧，至少她老人家没阻止我们。",
            ["ContentFR"] = "Séparons-nous pour poser des questions. Au moins, elle ne nous a pas empêchés d’enquêter.",
            ["DialogueId"] = 10032110,
            ["GUID"] = "191D450C",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1003/100321/191D450C",
            },
        [10032111] = {
            ["Content"] = "跟你们说过多少次，灯用完记得关！再忘了关灯或者没把道具放回仓库，我就把这些道具通通塞到你们的嘴里！",
            ["ContentFR"] = "Combien de fois je dois vous le répéter ? Quand vous avez fini, éteignez les lumières ! Et si j’en attrape encore un qui oublie d’éteindre ou de remettre les accessoires en réserve, je lui fais avaler tout l’entrepôt !",
            ["DialogueId"] = 10032111,
            ["Duration"] = 17,
            ["GUID"] = "191D4536",
            ["SpeakNpcId"] = 100329,
            ["VoiceName"] = "voice/$Locale$/story/1003/100321/191D4536",
            },
        [10032112] = {
            ["Content"] = "诶，钉子呢，怎么偏偏在加固舞台架子的时候找不到了。",
            ["ContentFR"] = "Hein ? Les clous ? Pourquoi c’est toujours quand je dois renforcer la scène qu’ils disparaissent...",
            ["DialogueId"] = 10032112,
            ["Duration"] = 9,
            ["GUID"] = "191D450D",
            ["VoiceName"] = "voice/$Locale$/story/1003/100321/191D450D",
            },
        [10032113] = {
            ["Content"] = "丹尼斯呢？还有几天就正式上台了，就差他没试妆拍定妆照了。",
            ["ContentFR"] = "Dennis ? Où est Dennis ? La première approche ! Il est le seul à ne pas avoir encore fait ses essais de maquillage et ses photos de scène.",
            ["DialogueId"] = 10032113,
            ["Duration"] = 10,
            ["GUID"] = "191D450E",
            ["VoiceName"] = "voice/$Locale$/story/1003/100321/191D450E",
            },
        [10032114] = {
            ["Content"] = "“秉烛起舞，放声歌唱在这个雪夜。”",
            ["ContentFR"] = "« À la lueur des chandelles, dansons et chantons sous cette nuit de neige. »",
            ["DialogueId"] = 10032114,
            ["Duration"] = 6,
            ["GUID"] = "191D450F",
            ["SpeakNpcId"] = 100370,
            ["VoiceName"] = "voice/$Locale$/story/1003/100321/191D450F",
            },
        [10032115] = {
            ["Content"] = "第三幕的灯光设计得改一下。我们要模拟的是蜡烛被逐个点亮的光线变化，明白吗？逐、个、点、亮！",
            ["ContentFR"] = "La lumière de la troisième scène doit être revue. On simule l’allumage progressif des chandelles. Compris ? Une... à... une !",
            ["DialogueId"] = 10032115,
            ["Duration"] = 15,
            ["GUID"] = "191D4510",
            ["VoiceName"] = "voice/$Locale$/story/1003/100321/191D4510",
            },
        [10032116] = {
            ["Content"] = "你又抢拍子了，打算几天后就用这种状态上台吗？重来。",
            ["ContentFR"] = "Tu as encore sauté une mesure. Tu comptes monter sur scène dans cet état ? Reprends.",
            ["DialogueId"] = 10032116,
            ["Duration"] = 9,
            ["GUID"] = "191D4511",
            ["VoiceName"] = "voice/$Locale$/story/1003/100321/191D4511",
            },
        [10032117] = {
            ["Content"] = "抱歉……",
            ["ContentFR"] = "Désolée...",
            ["DialogueId"] = 10032117,
            ["Duration"] = 2,
            ["GUID"] = "191D4512",
            ["VoiceName"] = "voice/$Locale$/story/1003/100321/191D4512",
            },
        [10032118] = {
            ["Content"] = "贝尔，这些东西等会排练要用，帮忙搬一下。",
            ["ContentFR"] = "Bell ! Ces affaires sont pour la répétition, aide-moi à les déplacer.",
            ["DialogueId"] = 10032118,
            ["Duration"] = 7,
            ["GUID"] = "191D4513",
            ["VoiceName"] = "voice/$Locale$/story/1003/100321/191D4513",
            },
        [10032119] = {
            ["Content"] = "来了来了。",
            ["ContentFR"] = "J’arrive, j’arrive !",
            ["DialogueId"] = 10032119,
            ["Duration"] = 2,
            ["GUID"] = "191D4514",
            ["VoiceName"] = "voice/$Locale$/story/1003/100321/191D4514",
            },
        [10032201] = {
            ["Camera"] = "-414.882477,353.665741,414.34375,0.000202,-30.196259,-52.800652,35.000015,284.991394,false,DoNotOverride,3.584893",
            ["Content"] = "你好，请问……",
            ["ContentFR"] = "Bonjour, excusez-moi, est-ce que je pourrais vous...",
            ["DialogueId"] = 10032201,
            ["FinalCamera"] = "-414.882477,353.665741,414.34375,0.000206,-28.996235,-53.8008,35.000015,284.991394,false,DoNotOverride,3.584893",
            ["GUID"] = "191D53FA",
            ["LookAt"] = {
                [1] = "200021:n(100329)",
                [2] = "200002:n(100329)",
                [3] = "100001:n(100329)",
                },
            ["NextDialogue"] = 10032202,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100329:Think_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1003/100322/191D53FA",
            },
        [10032202] = {
            ["Camera"] = "-207.049316,184.011703,115.789062,0.000259,1.803177,-63.821884,35.000015,284.991394,false,DoNotOverride,3.584893",
            ["Content"] = "……花冠15顶，没问题，马靴9双，没问题……好了，我这边清点完了，你是谁，什么事？",
            ["ContentFR"] = "... Quinze couronnes de fleurs, c’est bon. Neuf paires de bottes cavalières, c’est bon. Voilà, inventaire terminé. Bon, et vous, vous êtes qui ? Qu’est-ce que vous voulez ?",
            ["DialogueId"] = 10032202,
            ["FacialId"] = {
                [1] = "100329:CM_Angry01",
                },
            ["FinalCamera"] = "-207.049316,184.011703,115.789062,0.000259,4.003139,-64.023117,35.000015,284.991394,false,DoNotOverride,3.584893",
            ["GUID"] = "191D5424",
            ["NextDialogue"] = 10032203,
            ["Scripts"] = "PARA{\
SEQ{\
PlayAnimation{_delay{4},ActorId{100329},AnimationId{\"Think_End\"},Duration{2}},\
TurnTo{_delay{3},TurnToDescription{\"100329:n(100001)\"}}\
},\
SEQ{\
CameraMoveTo{_delay{7},TargetPosition{\"-58.123032,-61.803299,184.066406,0.000091,-16.1978,122.415901,35.000011,155.949936,false,DoNotOverride,22.0\"},duration{0}},\
CameraMoveTo{_delay{0},TargetPosition{\"-68.912094,-67.938797,184.066406,0.000075,-16.997759,119.416306,35.000015,155.949936,false,DoNotOverride,22.0\"},duration{6}}}\
}",
            ["SpeakNpcId"] = 100329,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1003/100322/191D5424",
            },
        [10032203] = {
            ["Camera"] = "-51.966774,-30.787083,127.144531,0.000101,1.200146,-113.183083,35.000015,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "这块布料是剧院的吗？",
            ["ContentFR"] = "Pouvez-vous me dire si ce morceau de tissu provient du théâtre ?",
            ["DialogueId"] = 10032203,
            ["FacialId"] = {
                [1] = "100001:Doubt01",
                },
            ["FinalCamera"] = "-51.966774,-30.787083,124.570312,0.000114,3.000078,-113.18206,35.000015,100000.0,false,DoNotOverride,22.0",
            ["GUID"] = "191D544E",
            ["NextDialogue"] = 10032204,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Explain01_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1003/100322/191D544E",
            },
        [10032204] = {
            ["Camera"] = "-38.398422,-255.859344,70.714844,0.000165,6.599745,108.419289,40.0,340.239532,false,Manual,3.429005",
            ["Content"] = "针脚不对，花纹不对，盖雷亚剧院才不会用这种劣质货。谁派你来的？你是不是哪里的小报记者，想造谣我们布景低劣？",
            ["ContentFR"] = "Les coutures ne tiennent pas, le motif est grossier... Le Théâtre Galea n’utiliserait jamais une camelote pareille. Qui vous envoie ? Vous êtes un de ces journaleux à ragots ? Vous voulez salir notre réputation en disant qu’on utilise des décors de pacotille ?",
            ["DialogueId"] = 10032204,
            ["FinalCamera"] = "-38.398422,-255.859344,70.714844,0.000166,7.799755,108.219391,40.0,340.239532,false,Manual,3.429005",
            ["GUID"] = "191D5478",
            ["NextDialogue"] = 10032205,
            ["SpeakNpcId"] = 100329,
            ["TalkActionId"] = {
                [1] = "100329:Disagree",
                [2] = "100001:Explain01_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1003/100322/191D5478",
            },
        [10032205] = {
            ["Camera"] = "-103.923096,98.783195,108.738281,0.000139,7.197059,-62.586468,35.000011,284.991394,false,DoNotOverride,3.584893",
            ["Content"] = "啊不是不是，别激动，这是我们在“卡戎狩猎”案发现场捡到的，就问问而已。",
            ["ContentFR"] = "Hé, du calme ! Rien de tout ça. On a trouvé ce tissu sur une scène de crime liée à la \"Traque aux Charons\", on vient juste vérifier, c’est tout.",
            ["DialogueId"] = 10032205,
            ["FacialId"] = {
                [1] = "200021:Smile01",
                },
            ["FinalCamera"] = "-96.228012,102.699203,108.738281,0.000139,7.197059,-64.586884,35.000011,284.991394,false,DoNotOverride,3.584893",
            ["GUID"] = "191D54A2",
            ["NextDialogue"] = 10032206,
            ["SpeakNpcId"] = 200021,
            ["TalkActionId"] = {
                [1] = "200021:Talk01_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1003/100322/191D54A2",
            },
        [10032206] = {
            ["Camera"] = "134.718857,678.446716,706.917969,-0.001009,-39.19453,-108.145706,40.0,340.239532,false,DoNotOverride,3.429005",
            ["Content"] = "……你这小报记者，是想抹黑剧院，说我们和杀人案有关？！",
            ["ContentFR"] = "... Alors maintenant, vous insinuez qu’on est mêlés à un meurtre ?! Vous n’êtes que des foutus journaleux !",
            ["DialogueId"] = 10032206,
            ["FacialId"] = {
                [1] = "200021:Confident01",
                },
            ["FinalCamera"] = "161.966888,668.893982,706.917969,-0.001007,-39.194515,-110.545403,40.0,340.239532,false,DoNotOverride,3.429005",
            ["GUID"] = "191D54CC",
            ["NextOptions"] = {
                [1] = 10032207,
                [2] = 10032208,
                },
            ["Scripts"] = "SEQ{CameraMoveTo{_delay{3},TargetPosition{\"-36.183578,-243.968689,115.859375,0.000218,2.599987,118.410843,35.000008,100000.0,false,Manual,22.0\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-36.183578,-243.968689,121.722656,0.000225,1.199948,118.210846,35.000008,100000.0,false,Manual,22.0\"},duration{5}}}",
            ["SpeakNpcId"] = 100329,
            ["TalkActionId"] = {
                [1] = "100329:Angry01_Start",
                [2] = "200021:Talk01_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1003/100322/191D54CC",
            },
        [10032207] = {
            ["Content"] = "都说了我们不是小报记者了！",
            ["ContentFR"] = "<I>On vous a dit qu’on n’était pas des journalistes !</>",
            ["DialogueId"] = 10032207,
            ["GUID"] = "191D54F6",
            ["ImprPlusId"] = 1007,
            ["NextDialogue"] = 10032209,
            },
        [10032208] = {
            ["Content"] = "再污蔑我，就把这块在垃圾桶里抹了一圈的布条塞到你嘴里。",
            ["ContentFR"] = "<I>Répète encore une fois « journaleux », et je t’enfonce ce chiffon sorti tout droit des poubelles... dans la gorge.</>",
            ["DialogueId"] = 10032208,
            ["GUID"] = "191D5520",
            ["ImprPlusId"] = 1010,
            ["NextDialogue"] = 10032209,
            },
        [10032209] = {
            ["Camera"] = "-91.937477,-19.004244,138.511719,0.000139,-2.397847,-94.204163,35.000008,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "我们是来协助卫戍部队调查“卡戎狩猎”事件的，我们在案发现场捡到了这块疑似出自剧院的绒布，请你配合调查。",
            ["ContentFR"] = "Nous assistons les Veilleurs dans l’enquête sur la \"Traque aux Charons\". Nous avons trouvé ce velours sur les lieux de l’attaque, et nous devons vérifier son origine. Merci de bien vouloir coopérer.",
            ["DialogueId"] = 10032209,
            ["FacialId"] = {
                [1] = "100001:Confident01",
                },
            ["FinalCamera"] = "-85.894508,-19.564302,138.511719,0.000138,-2.597869,-96.603889,35.000008,100000.0,false,DoNotOverride,22.0",
            ["GUID"] = "191D5521",
            ["NextDialogue"] = 10032210,
            ["Scripts"] = "PlayAnimation{_delay{3},ActorId{100001},AnimationId{\"Confident_Start\"},Duration{2}}",
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "200021:Talk01_End",
                [2] = "100001:DisagreeHead",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1003/100322/191D5521",
            },
        [10032210] = {
            ["Camera"] = "-82.898415,-30.874966,169.933594,0.000135,-14.003205,122.032799,45.000011,284.991394,false,DoNotOverride,3.584893",
            ["Content"] = "好吧，看来是我太敏感了，不好意思啊。",
            ["ContentFR"] = "... Les Veilleurs ? D’accord, j’ai réagi trop vite. Désolé.",
            ["DialogueId"] = 10032210,
            ["FacialId"] = {
                [1] = "100329:CM_Idle",
                },
            ["FinalCamera"] = "-82.898415,-30.874966,167.605469,0.000139,-12.403131,121.633614,45.000023,284.991394,false,DoNotOverride,3.584893",
            ["GUID"] = "191D554A",
            ["NextDialogue"] = 10032211,
            ["SpeakNpcId"] = 100329,
            ["TalkActionId"] = {
                [1] = "100329:Angry01_End",
                [2] = "100001:Confident_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1003/100322/191D554A",
            },
        [10032211] = {
            ["Camera"] = "195.853271,-530.033142,237.539062,7.201614,-13.600497,120.839867,45.0,284.991394,false,DoNotOverride,3.584893",
            ["Content"] = "自从两年前那件破事开始，就总有该死的小报记者给剧团造谣，说剧团都是骗子，还害得团长她老人家大病一场。",
            ["ContentFR"] = "Depuis cette histoire, il y a deux ans, on a des rumeurs qui nous collent à la peau... Ces foutus journaleux racontaient que la troupe n’était qu’une bande d’imposteurs. Ça a rendu notre directrice malade au point de rester alitée des semaines.",
            ["DialogueId"] = 10032211,
            ["FacialId"] = {
                [1] = "100329:CM_Sad01",
                },
            ["FinalCamera"] = "208.112061,-522.162048,239.332031,7.201801,-13.600518,122.240273,45.0,284.991394,false,DoNotOverride,3.584893",
            ["GUID"] = "191D5574",
            ["NextDialogue"] = 10032212,
            ["SpeakNpcId"] = 100329,
            ["TalkActionId"] = {
                [1] = "100329:Sigh_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1003/100322/191D5574",
            },
        [10032212] = {
            ["Camera"] = "-110.570213,148.667206,110.816406,0.000218,-0.000676,-90.985168,35.000011,315.079285,false,Manual,3.120782",
            ["Content"] = "反正这布肯定不是我们剧院的，道具清单都在那边放着，信不过你们就自己去看，我该继续干活了！",
            ["ContentFR"] = "En tout cas, ce tissu n’est pas à nous. Les registres des accessoires sont là-bas, vous pouvez les consulter si vous voulez. Moi, je dois retourner bosser.",
            ["DialogueId"] = 10032212,
            ["FacialId"] = {
                [1] = "100329:CM_Angry01",
                },
            ["FinalCamera"] = "-107.103416,148.607758,112.542969,0.000218,0.199332,-92.38517,35.000011,315.079285,false,Manual,3.120782",
            ["GUID"] = "191D559E",
            ["NextDialogue"] = 10032213,
            ["Scripts"] = "PlayAnimation{_delay{2},ActorId{100329},AnimationId{\"Disagree\"},Duration{2}}",
            ["SpeakNpcId"] = 100329,
            ["TalkActionId"] = {
                [1] = "100329:Sigh_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1003/100322/191D559E",
            },
        [10032213] = {
            ["Camera"] = "-1017.098938,642.821167,548.960938,0.000052,-21.599352,-39.762207,55.000011,1185.884644,false,Manual,1.2",
            ["Content"] = "喂，你们几个臭小子，假发摘了就给我放回头模上，别跑，我今天非得把这些假发缝你们头皮上不可！",
            ["ContentFR"] = "Hé, vous, les morveux ! Quand vous enlevez les perruques, vous les remettez sur les mannequins ! Revenez ici tout de suite ou je vous les couds directement sur le crâne !",
            ["DialogueId"] = 10032213,
            ["FinalCamera"] = "-1008.682922,652.714722,548.960938,0.000058,-21.199362,-42.361965,55.000011,1185.884644,false,Manual,1.2",
            ["GUID"] = "191D55C8",
            ["LookAt"] = {
                [1] = "100329:n(100329)",
                },
            ["Scripts"] = "MoveTo{_delay{3},ActorId{100329},TargetPoint{\"cp2fixsimple13Point01\"},MoveSpeed{80},Visibility{\"Show\"}}",
            ["SpeakNpcId"] = 100329,
            ["ToFinalCameraBlendTime"] = 10,
            ["TurnTo"] = {
                [1] = "100329:p(90)",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100322/191D55C8",
            },
        [10032214] = {
            ["ContentFR"] = "08 oct.\
Préparés : costumes et sacs de couchage.\
Confirmé par : Mondry\
(Note : Les réserves de nourriture s’épuisent. <H>Pour le mois intensif de répétitions à venir, il faudra demander une nouvelle livraison.</>)\
...\
12 nov.\
Remplacés : trois microphones.\
Confirmé par : Grinde\
(Note : L’un d’eux émet un son beaucoup trop fort, mais la directrice Putsch a insisté pour le garder tel quel.)\
14 nov.\
Installé : rideau rouge. Le rideau doré a été renvoyé à l’entrepôt.\
Confirmé par : Bell\
