        [10032317] = {
            ["Camera"] = "160.525391,-52.564697,106.691406,0.00035,9.3942,-138.753281,45.0,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "哈哈，人啊，不就是平时越憋得透不过气，就越想大声喊叫出来么。",
            ["ContentFR"] = "Haha, justement. Plus on se retient au quotidien, plus on a besoin de tout lâcher et de hurler à plein poumons, de temps en temps.",
            ["DialogueId"] = 10032317,
