        [10032524] = {
            ["Content"] = "工人。",
            ["ContentFR"] = "<I>Un ouvrier.</>",
            ["DialogueId"] = 10032524,
            ["GUID"] = "191D88CE",
            ["ImprPlusId"] = 1016,
            ["NextDialogue"] = 10032525,
            },
        [10032525] = {
            ["Camera"] = "-52.859375,-596.512695,69.789795,0.000565,3.798207,76.587906,45.000011,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "我询问过那里的工人，他们当晚所有人都有不在场证明……结合鱼叉和鱼油这两条线索，我觉得嫌疑人最有可能是“渔夫”。",
            ["ContentFR"] = "Je les ai déjà blanchis, tous avaient un alibi solide. Avec le harpon et l’huile, le suspect le plus probable reste un pêcheur.",
            ["DialogueId"] = 10032525,
            ["FacialId"] = {
                [1] = "100304:Confident01",
                },
            ["FinalCamera"] = "-43.747559,-598.684082,69.789795,0.000566,3.798207,77.987732,45.000011,100000.0,false,DoNotOverride,22.0",
