            ["VoiceName"] = "voice/$Locale$/story/1003/100325/191D88F8",
            },
        [10032526] = {
            ["Content"] = "渔夫。",
            ["ContentFR"] = "<I>Un pêcheur.</>",
            ["DialogueId"] = 10032526,
            ["GUID"] = "191D8922",
            ["ImprPlusId"] = 1008,
            ["NextDialogue"] = 10032527,
            },
        [10032527] = {
