                [2] = "200021:Sigh_End",
                },
            ["ToFinalCameraBlendTime"] = 0.5,
            ["VoiceName"] = "voice/$Locale$/story/1003/100325/191D89CA",
            },
        [10032531] = {
            ["Camera"] = "26.899658,-53.543457,109.033691,0.000668,3.801936,71.611046,35.000008,459.907166,false,DoNotOverride,3.252207",
            ["Content"] = "冰湖城的渔夫大多居住在雾区，也就是贫民窟。事不宜迟，我们到那里找找看吧。",
            ["ContentFR"] = "La plupart des pêcheurs d’ici vivent dans Brumelac, les taudis de la ville. Allons-y sans perdre de temps.",
            ["DialogueId"] = 10032531,
            ["FacialId"] = {
                [1] = "100304:Confident01",
                },
            ["FinalCamera"] = "24.10376,-52.599609,109.033691,0.000668,4.201932,71.410896,35.000008,459.907166,false,DoNotOverride,3.252207",
            ["GUID"] = "191D89F4",
            ["LookAt"] = {
                [1] = "100304:n(100304)",
                },
            ["Scripts"] = "SEQ{CameraMoveTo{_delay{3},TargetPosition{\"564.560242,341.522949,164.406982,0.000664,-6.397831,-142.585052,35.0,459.907166,false,Manual,3.252207\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"571.416809,346.806641,165.377197,0.000665,-6.397831,-142.385117,35.0,459.907166,false,Manual,3.252207\"},duration{5}}}",
            ["SpeakNpcId"] = 100304,
            ["TalkActionId"] = {
                [1] = "100304:AgreeHead",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1003/100325/191D89F4",
            },
        [10032601] = {
            ["Content"] = "这一片住着的都是渔夫，长官你要先从哪家找起？",
            ["ContentFR"] = "Cette zone est remplie de pêcheurs. Officier Fischer, par où commence-t-on ?",
            ["DialogueId"] = 10032601,
            ["GUID"] = "191D959A",
            ["SpeakNpcId"] = 200021,
            ["VoiceName"] = "voice/$Locale$/story/1003/100326/191D959A",
            },
        [10032602] = {
            ["Content"] = "喵——喵——",
            ["ContentFR"] = "Miaou— miaou !",
            ["DialogueId"] = 10032602,
            ["GUID"] = "191D95C4",
            ["SpeakNpcId"] = 100320,
            ["SpeakNpcName"] = "Cp2CharacterName29",
            ["VoiceName"] = "voice/$Locale$/story/1003/100326/191D95C4",
            },
        [10032603] = {
            ["Content"] = "喵……呜喵？",
            ["ContentFR"] = "Miaou... miaou ?",
            ["DialogueId"] = 10032603,
            ["GUID"] = "191D95EE",
            ["NextDialogue"] = 10032604,
            ["SpeakNpcId"] = 100320,
            ["SpeakNpcName"] = "Cp2CharacterName29",
            ["VoiceName"] = "voice/$Locale$/story/1003/100326/191D95EE",
            },
        [10032604] = {
            ["Content"] = "（这只猫一直在盯着黎瑟看……是闻到了什么特别的味道吗？）",
            ["ContentFR"] = "<I>Ce chat fixe Rhythm depuis un moment... Il aurait senti quelque chose d’inhabituel ?</>",
            ["DialogueId"] = 10032604,
            ["DisableMouth"] = 1,
            ["GUID"] = "191D9618",
            ["NextDialogue"] = 10032605,
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1003/100326/191D9618",
            },
        [10032605] = {
            ["Content"] = "黎瑟长官，那罐鱼油借用一下。",
            ["ContentFR"] = "Officier Fischer, puis-je emprunter ce flacon d’huile de poisson un instant ?",
            ["DialogueId"] = 10032605,
            ["GUID"] = "191D9642",
            ["NextDialogue"] = 10032606,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1003/100326/191D9642",
            },
        [10032606] = {
            ["Content"] = "给，你是发现什么了吗？",
            ["ContentFR"] = "Tiens. Vous avez découvert quelque chose ?",
            ["DialogueId"] = 10032606,
            ["GUID"] = "191D966C",
            ["NextDialogue"] = 10032607,
            ["SpeakNpcId"] = 100304,
            ["VoiceName"] = "voice/$Locale$/story/1003/100326/191D966C",
            },
        [10032607] = {
            ["Content"] = "嗯，我确认一下。",
            ["ContentFR"] = "Oui, je veux juste vérifier une hypothèse.",
            ["DialogueId"] = 10032607,
            ["GUID"] = "191D9696",
            ["NextDialogue"] = 10032608,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1003/100326/191D9696",
            },
        [10032608] = {
            ["Content"] = "喵——喵喵！",
            ["ContentFR"] = "Miaou— miaou miaou !",
            ["DialogueId"] = 10032608,
            ["GUID"] = "191D96C0",
            ["SpeakNpcId"] = 100320,
            ["SpeakNpcName"] = "Cp2CharacterName29",
            ["VoiceName"] = "voice/$Locale$/story/1003/100326/191D96C0",
            },
        [10032609] = {
            ["Content"] = "我们跟着那只猫走吧，它似乎想带我们去什么地方。",
            ["ContentFR"] = "Suivons ce chat, il semble vouloir nous montrer quelque chose.",
            ["DialogueId"] = 10032609,
            ["GUID"] = "191D96EA",
            ["NextDialogue"] = 10032610,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1003/100326/191D96EA",
            },
        [10032610] = {
            ["Content"] = "真敏锐，不愧是驯兽师出身。",
            ["ContentFR"] = "Vraiment perspicace... pas étonnant pour quelqu’un ayant été {性别:dresseur d’animaux|dresseuse d’animaux}.",
            ["DialogueId"] = 10032610,
            ["GUID"] = "191D96EB",
            ["NextDialogue"] = 10032611,
            ["SpeakNpcId"] = 100304,
            ["VoiceName"] = "voice/$Locale$/story/1003/100326/191D96EB",
            },
        [10032611] = {
            ["Content"] = "（……奥特赛德，我谢谢你。）",
            ["ContentFR"] = "<I>... Merci, l’Étranger.</>",
            ["DialogueId"] = 10032611,
            ["DisableMouth"] = 1,
            ["GUID"] = "191D96EC",
            ["NextDialogue"] = 10032612,
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1003/100326/191D96EC",
            },
        [10032612] = {
            ["Content"] = "喵——喵喵喵喵！",
            ["ContentFR"] = "Miaou— miaou miaou miaou !",
            ["DialogueId"] = 10032612,
            ["GUID"] = "191D9714",
            ["SpeakNpcId"] = 100320,
            ["SpeakNpcName"] = "Cp2CharacterName29",
            ["VoiceName"] = "voice/$Locale$/story/1003/100326/191D9714",
            },
        [10032613] = {
            ["Content"] = "猫咪消失在了前方。",
            ["ContentFR"] = "Le chat a disparu au loin.",
            ["DialogueId"] = 10032613,
            ["GUID"] = "191D973E",
            ["VoiceName"] = "voice/$Locale$/story/1003/100326/191D973E",
            },
        [10032614] = {
            ["Content"] = "你这个伤害小仆从的坏家伙，居然藏在这里！",
            ["ContentFR"] = "Toi, le méchant qui a blessé mon petit larbin ! Tu pensais vraiment pouvoir te cacher ? La Justice est là !",
            ["DialogueId"] = 10032614,
            ["GUID"] = "191D9768",
            ["NextDialogue"] = 10032615,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1003/100326/191D9768",
            },
        [10032615] = {
            ["Content"] = "啊？卫戍部队的？别打我别打我，我招，我招！",
            ["ContentFR"] = "Hein ? Les Veilleurs ? Non... non me frappez pas ! Je... je vais parler !",
            ["DialogueId"] = 10032615,
            ["GUID"] = "191D9792",
            ["SpeakNpcId"] = 100314,
            ["VoiceName"] = "voice/$Locale$/story/1003/100326/191D9792",
