        [10032719] = {
            ["Camera"] = "172.011246,780.197266,362.796875,0.000117,0.202092,125.372826,25.000006,100000.0,false,Manual,22.0",
            ["Content"] = "等等，各位长官不会怀疑卡戎狩猎是我干的吧！给我十个胆子我也干不出这种事啊！",
            ["ContentFR"] = "Attendez, vous ne croyez pas que c’est moi le responsable, hein ? Même avec dix fois plus de courage, je ne pourrais pas faire ça !",
            ["DialogueId"] = 10032719,
            ["FacialId"] = {
                [1] = "100314:CM_Shock01",
                },
            ["FinalCamera"] = "163.694839,774.321289,362.796875,0.000117,0.202092,125.172852,25.000006,100000.0,false,Manual,22.0",
            ["GUID"] = "191DA8F6",
