            ["ToFinalCameraBlendTime"] = 8.5,
            ["VoiceName"] = "voice/$Locale$/story/1003/100327/191DA8F6",
            },
        [10032720] = {
            ["Camera"] = "55.330933,1065.099609,369.362305,0.000144,7.601577,-134.201859,25.000006,91.688835,false,Manual,3.0",
            ["Content"] = "……情况我知道了，盗窃帝国公共财产，按照《海伯利亚刑事法典》第33条，应判处十年监禁。",
            ["ContentFR"] = "... J’ai compris. Le vol de propriété impériale est passible de dix ans de prison selon l’article 33 du Code Pénal Hyperboréen.",
            ["DialogueId"] = 10032720,
            ["FacialId"] = {
                [1] = "100304:Close",
                },
