            ["GUID"] = "191DAA1C",
            ["LookAt"] = {
                [1] = "100304:n(100314)",
                },
            ["NextDialogue"] = 10032727,
            ["Scripts"] = "PlayAnimation{_delay{2},ActorId{100314},AnimationId{\"Talk01_Start\"},Duration{2}}",
            ["SpeakNpcId"] = 100314,
            ["ToFinalCameraBlendTime"] = 7.5,
