            },
        [10032729] = {
            ["Camera"] = "7.246655,1098.832031,376.648438,0.000195,5.001645,-96.442291,25.0,100000.0,false,Manual,22.0",
            ["Content"] = "我保证，不会让那只怪物伤害到你。",
            ["ContentFR"] = "Je te le promets. Cette créature ne te touchera pas.",
            ["DialogueId"] = 10032729,
            ["FinalCamera"] = "6.774265,1094.647461,377.016602,0.000194,5.201646,-96.242355,25.0,100000.0,false,Manual,22.0",
            ["GUID"] = "191DAA9A",
