                [2] = "\
100314:Explain02_End",
                },
            ["ToFinalCameraBlendTime"] = 4,
            ["VoiceName"] = "voice/$Locale$/story/1003/100327/191DAA9A",
            },
        [10032730] = {
            ["Camera"] = "-3.580261,1060.973633,409.661621,0.000202,-4.198271,88.156929,25.0,100000.0,false,Manual,22.0",
            ["Content"] = "好，好。那晚我在机车厂里，捡了两罐月髓液就打算开溜……但就在我翻墙离开的时候，我看到了、看到了……",
            ["ContentFR"] = "D-D’accord, cette nuit-là à l’usine, après avoir pris les deux conteneurs, je voulais partir... mais en escaladant le mur, j’ai vu...",
            ["DialogueId"] = 10032730,
            ["FinalCamera"] = "-2.966713,1078.547852,408.523438,0.000198,-3.198168,83.556847,25.000002,100000.0,false,Manual,22.0",
            ["GUID"] = "191DAAC4",
            ["NextDialogue"] = 10032731,
            ["Scripts"] = "PlayAnimation{_delay{6},ActorId{100314},AnimationId{\"Sigh_Start\"},Duration{2}}",
            ["SpeakNpcId"] = 100314,
            ["TalkActionId"] = {
                [1] = "100314:Agree",
                },
            ["ToFinalCameraBlendTime"] = 13,
            ["VoiceName"] = "voice/$Locale$/story/1003/100327/191DAAC4",
            },
        [10032731] = {
            ["Camera"] = "39.773964,990.78125,331.155762,0.000091,18.20233,103.582535,25.000002,100000.0,false,Manual,22.0",
            ["Content"] = "我看到了一只怪物，从我眼前的下水道钻了出来！它有两人那么高，秽兽一样的脑袋，像熊一样强壮……它的眼睛和嘴里都喷着火焰……",
            ["ContentFR"] = "Un monstre est sorti des égouts juste devant moi ! Deux fois la taille d’un homme, une tête de Souillé, la force d’un ours... et du feu jaillissait de ses yeux et de sa bouche !",
            ["DialogueId"] = 10032731,
            ["FinalCamera"] = "28.134758,1028.376953,382.807129,0.000107,5.802635,101.982338,25.000002,100000.0,false,Manual,22.0",
            ["GUID"] = "191DAAEE",
            ["NextDialogue"] = 10032732,
            ["Scripts"] = "PARA{\
PlayAnimation{ActorId{100314},AnimationId{\"Sigh_End\"},Duration{2}},\
PlayAnimation{_delay{3},ActorId{100314},AnimationId{\"Talk01_Start\"},Duration{2}}\
}",
            ["SpeakNpcId"] = 100314,
            ["ToFinalCameraBlendTime"] = 14,
            ["VoiceName"] = "voice/$Locale$/story/1003/100327/191DAAEE",
            },
        [10032732] = {
            ["Camera"] = "80.654564,1001.875,379.909668,0.000229,0.202536,-121.235329,25.000006,100000.0,false,Manual,22.0",
            ["Content"] = "这个描述，莫非是秽兽？",
            ["ContentFR"] = "Ce... ce serait un Souillé ?",
            ["DialogueId"] = 10032732,
            ["FacialId"] = {
                [1] = "100001:Doubt01",
                },
            ["FinalCamera"] = "78.132179,1001.040039,379.916016,0.000229,0.202536,-121.235329,25.000006,100000.0,false,Manual,22.0",
            ["GUID"] = "191DAB18",
            ["NextDialogue"] = 10032733,
            ["Scripts"] = "SetLocation{ActorId{200021},TargetPoint{\"cp2fixsimple17_aoteHide\"},Visibility{\"Hide\"}}",
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
