                [2] = "\
100314:Talk01_End",
                [3] = "\
100001:Think_End",
                },
            ["ToFinalCameraBlendTime"] = 11,
            ["VoiceName"] = "voice/$Locale$/story/1003/100327/191DAB42",
            },
        [10032734] = {
            ["Camera"] = "26.018082,1022.058594,419.480957,0.00025,-9.196863,101.955841,25.000006,100000.0,false,Manual,22.0",
            ["Content"] = "我当时吓破了胆，光顾着把手里的东西一股脑丢过去，防身的鱼叉啊，月髓液啊……唉，辛辛苦苦搞来的月髓液全都砸它身上了，一分钱也没捞到。",
            ["ContentFR"] = "J’étais terrifié et j’ai balancé tout ce que j’avais pour me défendre, mon harpon, le Phoxichor... tout ! Tout ce pour quoi j’avais risqué ma vie, disparu en un instant !",
            ["DialogueId"] = 10032734,
            ["FinalCamera"] = "24.513016,1021.863281,422.244141,0.000247,-9.196863,99.756096,27.0,100000.0,false,Manual,22.0",
            ["GUID"] = "191DAB6C",
            ["NextDialogue"] = 10032735,
            ["Scripts"] = "SEQ{\
PlayAnimation{_delay{10},ActorId{100314},AnimationId{\"Talk02_End\"},Duration{2}},\
PlayAnimation{ActorId{100314},AnimationId{\"Sigh_Start\"},Duration{2}},\
PlayAnimation{_delay{4},ActorId{100314},AnimationId{\"Sigh_End\"},Duration{2}},\
}",
            ["SpeakNpcId"] = 100314,
            ["TalkActionId"] = {
                [1] = "100314:Talk02_Start",
                [2] = "\
100304:Think_End",
                },
            ["ToFinalCameraBlendTime"] = 15,
            ["VoiceName"] = "voice/$Locale$/story/1003/100327/191DAB6C",
            },
        [10032735] = {
            ["Camera"] = "90.650497,1262.787109,464.490234,0.000251,-20.997215,-118.24427,25.0,100000.0,false,Manual,22.0",
            ["Content"] = "难怪它身上会沾着这么多月髓液。然后呢，它怎样了？",
            ["ContentFR"] = "Ça explique pourquoi il était couvert de Phoxichor. Et après ?",
            ["DialogueId"] = 10032735,
            ["FacialId"] = {
                [1] = "100304:Think01",
                },
            ["FinalCamera"] = "90.650497,1262.787109,456.999512,0.000264,-18.797083,-118.044243,25.0,100000.0,false,Manual,22.0",
            ["GUID"] = "191DAB96",
            ["NextDialogue"] = 10032736,
            ["SpeakNpcId"] = 100304,
            ["TalkActionId"] = {
                [1] = "100304:Talk03_Start",
                },
            ["ToFinalCameraBlendTime"] = 5.5,
            ["VoiceName"] = "voice/$Locale$/story/1003/100327/191DAB96",
            },
        [10032736] = {
            ["Camera"] = "384.150787,1358.378906,320.59082,0.000264,2.402717,-144.638229,25.0,100000.0,false,Manual,22.0",
            ["Content"] = "我哪知道，我回过神来吓得连裤子都湿了，拔腿就跑，根本不敢回头看……",
            ["ContentFR"] = "Je... je ne sais pas. J’étais tellement effrayé que j’ai couru en abandonnant tout et... je n’ai même pas osé regarder derrière moi.",
            ["DialogueId"] = 10032736,
            ["FacialId"] = {
                [1] = "100304:None",
                },
            ["FinalCamera"] = "391.812073,1347.450195,320.59082,0.000264,2.402717,-145.238098,25.0,100000.0,false,Manual,22.0",
            ["GUID"] = "191DABC0",
            ["NextDialogue"] = 10032737,
            ["SpeakNpcId"] = 100314,
            ["TalkActionId"] = {
                [1] = "100314:Disagree",
                },
            ["ToFinalCameraBlendTime"] = 10.5,
            ["VoiceName"] = "voice/$Locale$/story/1003/100327/191DABC0",
            },
        [10032737] = {
            ["Camera"] = "10.431229,1056.774414,422.860352,0.000264,-14.396945,91.352699,25.000002,100000.0,false,Manual,22.0",
            ["Content"] = "唉，我全都、全都告诉你们了！各位长官，你们要说话算话，你们要救救我！我和那怪物打过照面，一直躲在这里也是怕它找上门来……",
            ["ContentFR"] = "Voilà, je vous ai tout raconté ! Officiers, tenez parole ! Je l’ai vu ce monstre... si je n’étais pas resté caché, il m’aurait trouvé...",
            ["DialogueId"] = 10032737,
            ["FinalCamera"] = "10.431229,1056.774414,422.860352,0.000264,-14.396945,91.352699,25.000002,100000.0,false,Manual,22.0",
            ["GUID"] = "191DABEA",
            ["LookAt"] = {
                [1] = "100314:n(100314)",
                },
            ["NextDialogue"] = 10032738,
            ["SpeakNpcId"] = 100314,
            ["TalkActionId"] = {
                [1] = "100314:Sigh_Start",
                },
            ["ToFinalCameraBlendTime"] = 14,
            ["VoiceName"] = "voice/$Locale$/story/1003/100327/191DABEA",
            },
        [10032738] = {
            ["Camera"] = "118.877075,858.798828,345.73584,0.000268,5.002854,122.155495,25.000002,327.751526,false,Manual,8.0",
            ["Content"] = "长官你看这个情报，和我那月、月髓液的事……",
            ["ContentFR"] = "S’il vous plaît, à propos du Phoxichor. Si je suis inculpé...",
            ["DialogueId"] = 10032738,
            ["FinalCamera"] = "116.053726,857.193359,345.73584,0.000266,4.60285,125.156082,25.000002,327.751526,false,Manual,8.0",
