        [10032739] = {
            ["Camera"] = "12.610016,1093.600586,371.847168,0.000261,4.202765,-97.048279,25.000002,100000.0,false,Manual,22.0",
            ["Content"] = "我会如实汇报。你盗窃的罪行确凿——不过，根据《海伯利亚刑事法典》，因为你提供了怪物藏身处这一关键线索，量刑上会酌情减免。",
            ["ContentFR"] = "Je ferai un rapport complet. Ton vol est avéré, mais comme tu nous as fourni des renseignements cruciaux, ta peine sera réduite conformément au Code Pénal Hyperboréen.",
            ["DialogueId"] = 10032739,
            ["FinalCamera"] = "12.383255,1091.765625,369.847656,0.000261,5.202746,-97.248253,25.000002,100000.0,false,Manual,22.0",
            ["GUID"] = "191DAC3E",
            ["NextDialogue"] = 10032740,
            ["Scripts"] = "PARA{\
PlayAnimation{ActorId{100304},AnimationId{\"AgreeHead\"},Duration{2}},\
PlayAnimation{_delay{4.5},ActorId{100304},AnimationId{\"Talk03ToTalkL_Start\"},Duration{2}},\
}",
            ["SpeakNpcId"] = 100304,
            ["TalkActionId"] = {
                [1] = "100314:Explain01_End",
                },
            ["ToFinalCameraBlendTime"] = 13.5,
            ["VoiceName"] = "voice/$Locale$/story/1003/100327/191DAC3E",
            },
