            ["ToFinalCameraBlendTime"] = 2,
            ["VoiceName"] = "voice/$Locale$/story/1003/100327/191DAC68",
            },
        [10032741] = {
            ["Camera"] = "417.617523,1340.390625,517.765137,0.000245,-18.19628,-145.447281,25.0,100000.0,false,Manual,22.0",
            ["Content"] = "走吧，我们去治安署吧，那里暂时是安全的。",
            ["ContentFR"] = "Allons-y. Nous allons t’emmener au Bureau de la Sécurité, c’est l’endroit le plus sûr pour toi en ce moment.",
            ["DialogueId"] = 10032741,
            ["FinalCamera"] = "423.821808,1344.560547,557.297852,0.000245,-21.596436,-146.647812,25.0,100000.0,false,Manual,22.0",
