        [10033202] = {
            ["Camera"] = "-541.734375,-327.196777,3.390259,3.001632,10.582551,61.37484,15.000005,63.55685,false,Manual,5.0",
            ["Content"] = "怪物，是那怪物的声音，它要来了！！！",
            ["ContentFR"] = "Ce cri... C’est lui ! Le monstre ! Il arrive !",
            ["DialogueId"] = 10033202,
            ["FinalCamera"] = "-539.808594,-323.669922,4.1409,3.001632,10.582551,61.37484,15.000005,63.55685,false,Manual,5.0",
