            ["ToFinalCameraBlendTime"] = 1.5,
            ["VoiceName"] = "voice/$Locale$/story/1003/100332/191DF834",
            },
        [10033203] = {
            ["Camera"] = "-371.019531,-64.671387,163.679413,3.000862,-12.218163,76.165932,20.000011,144.671875,false,Manual,2.8",
            ["Content"] = "喂，你们两个别乱跑啊，再碰到秽兽怎么办。",
            ["ContentFR"] = "Hé, vous deux ! Ne courez pas n’importe où ! Et si vous tombez encore sur des Souillés ?",
            ["DialogueId"] = 10033203,
            ["FacialId"] = {
