        [10033505] = {
            ["Camera"] = "-112.908203,-136.419312,107.219604,0.000322,13.597683,-108.007072,35.000023,100000.0,false,Manual,22.0",
            ["Content"] = "感谢各位对军团的协助，要不是你们，卫戍部队的伤亡恐怕会更惨重。",
            ["ContentFR"] = "Merci à vous. Sans votre aide, les pertes des Veilleurs auraient été bien plus lourdes.",
            ["DialogueId"] = 10033505,
            ["FinalCamera"] = "-107.800781,-138.011902,107.219604,0.000322,13.397675,-110.206947,35.000023,100000.0,false,Manual,22.0",
            ["GUID"] = "191E29EA",
