            ["Scripts"] = "PARA{SetLocation{ActorId{200021},TargetPoint{\"Point1\"},Visibility{\"Show\"}},SetLocation{ActorId{200002},TargetPoint{\"Point2\"},Visibility{\"Show\"}},SetRotation{SetRotationDescription{\"100311:n(100001)\"}},SetRotation{SetRotationDescription{\"100001:n(100311)\"}},SEQ{CameraMoveTo{_delay{3},TargetPosition{\"-235.177734,-315.901123,148.828979,0.00035,-3.202812,42.790451,40.0,412.833496,false,Manual,4.354144\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-238.75,-312.088318,148.828979,0.000349,-3.202819,40.790806,40.0,412.833496,false,Manual,4.354144\"},duration{10}}}}",
            ["SpeakNpcId"] = 100311,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1003/100335/191E29EA",
            },
        [10033506] = {
            ["Content"] = "举手之劳。",
            ["ContentFR"] = "<I>Je n’ai fait que ma part.</>",
            ["DialogueId"] = 10033506,
            ["GUID"] = "191E2A14",
            ["NextDialogue"] = 10033507,
            },
        [10033507] = {
            ["Camera"] = "1902.650391,-988.80188,108.232178,0.000259,-0.801236,149.196533,35.000011,3157.576416,false,Manual,1.376868",
            ["Content"] = "嗯，感谢你们帮的这些忙。我联系下队友，让他们送你们出去。",
            ["ContentFR"] = "Quoi qu’il en soit, nous vous sommes redevables. Je vais prévenir mes camarades pour qu’ils vous raccompagnent.",
            ["DialogueId"] = 10033507,
            ["FinalCamera"] = "1898.128906,-996.384766,108.232178,0.000259,-0.801236,149.596466,35.000011,3157.576416,false,Manual,1.376868",
            ["GUID"] = "191E2A3E",
            ["NextDialogue"] = 10033508,
            ["SpeakNpcId"] = 100311,
            ["TalkActionId"] = {
                [1] = "100001:Talk03_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1003/100335/191E2A3E",
            },
        [10033508] = {
            ["Camera"] = "-138.914062,-208.657227,182.986816,-0.000002,-38.999802,-104.019676,35.000023,100000.0,false,Manual,22.0",
            ["Content"] = "啧，通讯器故障了吗……算了，反正你们走一会儿就能见到他们了。我们得封锁你们进来时的整条通道，你们就自己往那边走吧。",
            ["ContentFR"] = "Tch... Mon émetteur déconne encore ? Tant pis. Vous les croiserez sur la route. Nous devons sceller toute la section par laquelle vous êtes arrivés. Prenez ce passage-là, vous tomberez vite sur eux.",
            ["DialogueId"] = 10033508,
            ["FinalCamera"] = "-125.476562,-154.847595,227.898438,18.000706,-38.999802,-104.019608,35.000023,100000.0,false,Manual,22.0",
            ["GUID"] = "191E2A68",
            ["LookAt"] = {
                [1] = "200021:n(100311)",
                [2] = "200002:n(100311)",
                },
            ["NextDialogue"] = 10033509,
            ["Scripts"] = "PARA{SEQ{CameraMoveTo{_delay{3},TargetPosition{\"-83.787109,-712.988647,30.291992,-0.001007,8.196595,93.593033,35.000023,505.590393,false,Manual,11.621747\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-104.068359,-713.623779,30.291992,-0.001008,9.196576,91.393059,35.000023,505.590393,false,Manual,11.621747\"},duration{10}}}}",
            ["SpeakNpcId"] = 100311,
            ["TalkActionId"] = {
                [1] = "100001:Talk03_End",
                },
            ["ToFinalCameraBlendTime"] = 0.3,
            ["VoiceName"] = "voice/$Locale$/story/1003/100335/191E2A68",
            },
        [10033509] = {
            ["Camera"] = "108.683594,-29.236145,139.334595,0.000065,-0.203772,172.19281,35.000011,100000.0,false,Manual,22.0",
            ["Content"] = "好惨，你这刚醒没多久，又马上被这么折腾一番，要不是黎瑟帮你挡了一下，怕是刚下床没多久又得回去躺着喽。",
            ["ContentFR"] = "Mon {性别:ami|amie}, t’as vraiment eu la vie dure. Tu viens de sortir du coma, et maintenant ça. Si Rhythm n’était pas intervenu, tu serais probablement en train de faire une autre longue sieste en ce moment.",
            ["DialogueId"] = 10033509,
            ["FinalCamera"] = "109.099609,-16.699524,139.334595,0.000065,-1.003785,179.992462,35.000011,100000.0,false,Manual,22.0",
            ["GUID"] = "191E2A92",
            ["LookAt"] = {
                [1] = "200021:n(100001)",
                [2] = "200002:n(100001)",
                },
            ["NextDialogue"] = 10033510,
            ["Scripts"] = "PlayAnimation{_delay{5},ActorId{200021},AnimationId{\"Sigh_End\"},Duration{2}}",
            ["SpeakNpcId"] = 200021,
            ["TalkActionId"] = {
                [1] = "200021:Sigh_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1003/100335/191E2A92",
            },
        [10033510] = {
            ["Camera"] = "-223.230469,-130.493103,71.03064,0.00022,14.995399,178.000687,35.000011,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "是啊是啊，刚才真是吓死白了！小仆从要是留下什么阿巴阿巴阿巴的后遗症了可怎么办呀！",
            ["ContentFR"] = "Exactement ! J’ai eu une peur bleue ! Si mon petit larbin s’était mis à baver partout, qu’est-ce que j’aurais fait, moi  ?! ",
            ["DialogueId"] = 10033510,
            ["FacialId"] = {
                [1] = "200002:Shock01",
                },
            ["FinalCamera"] = "-151.314453,-134.048645,51.274292,0.000221,13.395059,176.400452,35.000015,100000.0,false,DoNotOverride,22.0",
            ["GUID"] = "191E2ABC",
            ["NextOptions"] = {
