        [10033930] = {
            ["Camera"] = "97.116211,65.044434,109.430908,0.000174,12.026952,-158.303894,35.000011,183.766296,false,DoNotOverride,5.820475",
            ["Content"] = "都办好啦，有第六军团的任命书，工厂主也没法像以前那样刁难我了。",
            ["ContentFR"] = "Tout est réglé ! Avec ma lettre d’affectation pour la VIᵉ Légion, le patron n’osera plus jamais me chercher des noises.",
            ["DialogueId"] = 10033930,
            ["FinalCamera"] = "97.116211,65.044434,109.430908,0.000172,14.226867,-158.103928,35.000011,183.766296,false,DoNotOverride,5.820475",
            ["GUID"] = "191E6FA4",
            ["NextDialogue"] = 10033931,
            ["SpeakNpcId"] = 100358,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1003/100339/191E6FA4",
            },
        [10033931] = {
            ["Camera"] = "226.685547,179.624268,81.703613,0.000075,9.427033,-140.095993,35.000008,183.766296,false,DoNotOverride,5.820475",
            ["Content"] = "对了姐姐，你在卫戍部队还适应吗？",
            ["ContentFR"] = "Au fait, Rhythm, ça va ? Tu t’habitues aux Veilleurs ?",
            ["DialogueId"] = 10033931,
            ["FinalCamera"] = "236.081055,168.824707,81.703613,0.000074,9.427033,-143.29631,35.000008,183.766296,false,DoNotOverride,5.820475",
            ["GUID"] = "191E6FCE",
            ["LookAt"] = {
                [1] = "100358:n(100304)",
                },
            ["NextDialogue"] = 10033932,
            ["SpeakNpcId"] = 100358,
            ["TalkActionId"] = {
                [1] = "100358:Explain01_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1003/100339/191E6FCE",
            },
        [10033932] = {
            ["Camera"] = "-34.59082,61.33252,120.756836,0.000102,7.226237,-19.703157,29.0,121.00589,false,Manual,5.820475",
            ["Content"] = "哈哈……这才刚开始嘛，别着急。",
            ["ContentFR"] = "Haha... je viens juste de commencer, pas de quoi s’inquiéter.",
            ["DialogueId"] = 10033932,
            ["FacialId"] = {
                [1] = "100304:Think01",
                },
            ["FinalCamera"] = "-32.756836,66.453125,120.756836,0.000102,7.226237,-21.903011,29.0,121.00589,false,Manual,5.820475",
            ["GUID"] = "191E6FF8",
            ["LookAt"] = {
                [1] = "100358:n(100358)",
                },
            ["NextDialogue"] = 10033933,
            ["SpeakNpcId"] = 100304,
            ["TalkActionId"] = {
                [1] = "100358:Explain01_End",
                [2] = "100304:Confident_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1003/100339/191E6FF8",
            },
        [10033933] = {
            ["Camera"] = "52.249023,50.819092,164.266846,0.000087,-15.773091,-158.304077,35.0,68.717873,false,Manual,8.520827",
            ["Content"] = "那就是不太适应喽？唉，所以我说别急着加入卫戍部队，安心为明年的第六军团考核做准备多好。",
            ["ContentFR"] = "Donc... pas trop bien, hein ? Je te l’avais dit, fallait pas te précipiter de rejoindre les Veilleurs. T’aurais mieux fait de te concentrer sur les tests d’entrée de la VIᵉ Légion pour l’an prochain.",
            ["DialogueId"] = 10033933,
            ["FinalCamera"] = "53.777344,46.745605,164.266846,0.000087,-15.773057,-160.903915,35.0,68.717873,false,Manual,8.520827",
            ["GUID"] = "191E7022",
            ["NextDialogue"] = 10033934,
            ["Scripts"] = "SEQ{CameraMoveTo{_delay{5},TargetPosition{\"193.912109,109.49646,107.2229,0.000163,6.627189,-151.482452,40.000011,242.018341,false,Manual,3.778817\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"191.834961,114.103149,107.2229,0.00016,6.627189,-148.481476,40.000011,242.018341,false,Manual,3.778817\"},duration{5}}}",
            ["SpeakNpcId"] = 100358,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1003/100339/191E7022",
            },
        [10033934] = {
            ["Camera"] = "-231.121094,842.396484,7.90918,0.000122,8.226286,-68.883942,35.0,1199.737793,false,DoNotOverride,1.2",
            ["Content"] = "不用啦，我各项测验都差合格线很多，资质靠努力是弥补不了的。",
            ["ContentFR"] = "Pas la peine. Je suis bien en dessous de la moyenne dans tous les examens, et ça, l’effort ne suffit pas à compenser.",
            ["DialogueId"] = 10033934,
            ["FacialId"] = {
                [1] = "100304:Disappoint01",
                },
            ["FinalCamera"] = "-281.664062,822.878418,7.90918,0.000122,8.226286,-68.883942,35.0,1199.737793,false,DoNotOverride,1.2",
            ["GUID"] = "191E704C",
            ["NextDialogue"] = 10033935,
            ["Scripts"] = "SEQ{CameraMoveTo{_delay{5},TargetPosition{\"22.027344,47.885986,172.711914,0.000089,-26.171419,-23.268,35.000008,84.15313,false,Manual,5.91254\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"20.110352,43.316895,172.711914,0.000086,-25.971369,-20.267567,35.000008,84.15313,false,Manual,5.91254\"},duration{5}}}",
            ["SpeakNpcId"] = 100304,
            ["TalkActionId"] = {
                [1] = "100304:Confident_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1003/100339/191E704C",
            },
        [10033935] = {
            ["Camera"] = "-85.761719,55.762695,140.799561,0.002314,-2.075899,-18.472183,35.000019,176.232666,false,Manual,3.23825",
            ["Content"] = "如果能在卫戍部队做出点功绩，也有机会成为桂冠卡戎吧？而且，也多少能帮到冰湖城的人们……",
            ["ContentFR"] = "Mais si je me rends utile chez les Veilleurs, j’ai peut-être quand même une chance de devenir un jour une Charon Couronné. Et puis... ça me permet aussi d’aider un peu les gens de Givrelac.",
            ["DialogueId"] = 10033935,
            ["FinalCamera"] = "-85.06543,57.947021,140.799561,0.002315,-2.075899,-19.472168,35.000019,176.232666,false,Manual,3.23825",
            ["GUID"] = "191E7076",
            ["NextDialogue"] = 10033936,
            ["SpeakNpcId"] = 100304,
            ["TalkActionId"] = {
                [1] = "100304:Talk03_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1003/100339/191E7076",
            },
        [10033936] = {
            ["Camera"] = "11.327148,69.848389,135.454102,0.002309,0.323915,-35.471474,35.000019,207.040939,false,DoNotOverride,3.23825",
            ["Content"] = "能一起通过考核自然是好，但是没那个天分的话，也不能强求。就用笨方法摸索着走走看吧。",
            ["ContentFR"] = "Bien sûr, ça aurait été beau de réussir l’examen ensemble. Mais si je n’ai pas le talent qu’il faut, je ne vais pas forcer. Alors je ferai avec mes moyens, même si c’est plus dur.",
            ["DialogueId"] = 10033936,
            ["FacialId"] = {
                [1] = "100304:Doubt01",
                },
            ["FinalCamera"] = "13.211914,72.253418,135.454102,0.002309,0.323915,-38.071762,35.000019,207.040939,false,DoNotOverride,3.23825",
            ["GUID"] = "191E70A0",
            ["NextDialogue"] = 10033937,
            ["Scripts"] = "PARA{SEQ{CameraMoveTo{_delay{5},TargetPosition{\"-414.951172,1181.550537,153.929932,0.002262,-3.076201,-70.072845,35.0,1310.399902,false,Manual,1.2\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-442.080078,1171.2854,153.929932,0.002261,-3.076201,-69.272797,35.0,1310.399902,false,Manual,1.2\"},duration{10}}},PlayAnimation{_delay{6},ActorId{100304},AnimationId{\"Talk03_End\"},Duration{2}}}",
            ["SpeakNpcId"] = 100304,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1003/100339/191E70A0",
            },
        [10033937] = {
            ["Camera"] = "265.833984,-212.031494,174.978516,0.002239,3.122571,-41.861549,30.000002,7420.709473,false,Manual,2.157511",
            ["Content"] = "姐姐，你看，那是什么？",
            ["ContentFR"] = "Regarde là-bas. Tu vois quoi ?",
            ["DialogueId"] = 10033937,
            ["FinalCamera"] = "265.833984,-212.031494,174.978516,0.00224,7.322543,-39.261215,30.000002,7420.709473,false,Manual,2.157511",
            ["GUID"] = "191E70CA",
            ["LookAt"] = {
                [1] = "100304:p(cp2fixsimple25-26Point05)",
                [2] = "100358:p(cp2fixsimple25-26Point05)",
                },
            ["NextDialogue"] = 10033938,
            ["Scripts"] = "TurnTo{_delay{2},TurnToDescription{\"100304:p(120)\"}}",
            ["SpeakNpcId"] = 100358,
            ["ToFinalCameraBlendTime"] = 8,
            ["TurnTo"] = {
                [1] = "100358:p(-40)",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100339/191E70CA",
            },
        [10033938] = {
            ["Camera"] = "149.110352,-20.227783,132.325928,0.002244,5.324152,155.733917,30.000002,7420.709473,false,DoNotOverride,2.157511",
            ["Content"] = "是……房子？",
            ["ContentFR"] = "Euh... une maison ?",
            ["DialogueId"] = 10033938,
            ["FacialId"] = {
                [1] = "100304:Unacceptable01",
                },
            ["FinalCamera"] = "149.110352,-20.227783,132.325928,0.002245,8.324162,155.733551,30.000002,7420.709473,false,DoNotOverride,2.157511",
            ["GUID"] = "191E70F4",
            ["NextDialogue"] = 10033939,
            ["SpeakNpcId"] = 100304,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1003/100339/191E70F4",
            },
        [10033939] = {
            ["Camera"] = "230.985352,-152.731201,99.34082,0.002161,4.915304,136.528183,30.000008,7420.709473,false,DoNotOverride,2.157511",
            ["Content"] = "这个答案太笼统了！看，看我手指指的地方。",
            ["ContentFR"] = "Trop vague ! Pas là, là où je pointe du doigt.",
            ["DialogueId"] = 10033939,
            ["FinalCamera"] = "218.087891,-165.950195,99.34082,0.002162,4.915304,132.328186,30.000008,7420.709473,false,DoNotOverride,2.157511",
            ["GUID"] = "191E711E",
            ["NextDialogue"] = 10033940,
            ["Scripts"] = "PARA{SEQ{CameraMoveTo{_delay{4},TargetPosition{\"-98.920898,-91.486328,136.116943,0.002217,52.71476,1.336824,30.000008,7420.709473,false,DoNotOverride,2.157511\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-98.920898,-91.486328,136.116943,0.002217,55.114651,1.336824,30.000008,7420.709473,false,DoNotOverride,2.157511\"},duration{5}}},PlayAnimation{_delay{2},ActorId{100358},AnimationId{\"Explain01_Start\"},Duration{2}}}",
            ["SpeakNpcId"] = 100358,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1003/100339/191E711E",
            },
        [10033940] = {
            ["Camera"] = "148.391602,-30.790039,184.855225,0.002318,-29.476192,140.533157,50.0,91.877663,false,Manual,3.753203",
            ["Content"] = "……哨塔？",
            ["ContentFR"] = "... La tour de guet ?",
            ["DialogueId"] = 10033940,
            ["FacialId"] = {
                [1] = "100304:Think01",
                },
            ["FinalCamera"] = "144.614258,-35.229736,184.855225,0.002323,-29.476179,137.532928,50.0,91.877663,false,Manual,3.753203",
            ["GUID"] = "191E7148",
            ["NextDialogue"] = 10033941,
            ["SpeakNpcId"] = 100304,
            ["TalkActionId"] = {
                [1] = "100358:Explain01_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1003/100339/191E7148",
            },
        [10033941] = {
            ["Camera"] = "329.514648,-197.759277,252.08667,0.002183,-22.681835,142.327667,30.000008,7420.709473,false,DoNotOverride,2.157511",
            ["Content"] = "嗯嗯——确切来说，是哨塔上那盏灯。那是整座冰湖城最高的地方！",
            ["ContentFR"] = "Exactement ! Enfin... plus précisément, la lumière tout en haut. C’est le point le plus élevé de Givrelac !",
            ["DialogueId"] = 10033941,
            ["FinalCamera"] = "297.395508,-234.10498,252.08667,0.002188,-22.481806,132.727509,30.000008,7420.709473,false,DoNotOverride,2.157511",
            ["GUID"] = "191E7172",
            ["NextDialogue"] = 10033942,
            ["Scripts"] = "PlayAnimation{_delay{2},ActorId{100358},AnimationId{\"Talk01_Start\"},Duration{2}}",
            ["SpeakNpcId"] = 100358,
            ["TalkActionId"] = {
                [1] = "100358:AgreeHead",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1003/100339/191E7172",
            },
        [10033942] = {
            ["Camera"] = "272.657227,-228.072998,65.852295,0.002184,11.115211,134.331268,30.000008,7420.709473,false,DoNotOverride,2.157511",
            ["Content"] = "我每次站在这儿往内城看，都觉得它那么高，那么远，那么亮。就像书本上写的灯塔，只能远远看着，但永远都摸不到。",
            ["ContentFR"] = "À chaque fois que je la vois d’ici, elle me paraît si haute, si lointaine, si brillante. Comme un phare de conte... tout près, mais hors d’atteinte.",
            ["DialogueId"] = 10033942,
            ["FacialId"] = {
                [1] = "100304:Confident01",
                },
            ["FinalCamera"] = "272.657227,-228.072998,65.852295,0.002188,11.915223,137.931427,30.000008,7420.709473,false,DoNotOverride,2.157511",
            ["GUID"] = "191E719C",
            ["NextDialogue"] = 10033943,
            ["Scripts"] = "PARA{\
MoveTo{_delay{1.5},ActorId{100358},TargetPoint{\"cp2fixsimple25-26Point04\"},MoveSpeed{80},Visibility{\"Show\"}},\
SEQ{\
