        [10033947] = {
            ["Camera"] = "426.764648,-302.096436,133.729248,0.002049,-2.486148,142.138107,30.000008,521.877441,false,Manual,1.2",
            ["Content"] = "啊，对不起，我太激动了，嘿嘿……",
            ["ContentFR"] = "Ah, pardon... je me suis un peu emporté. Hé hé.",
            ["DialogueId"] = 10033947,
            ["FinalCamera"] = "444.470703,-315.862549,134.703125,0.002049,-2.486148,142.138107,30.000008,521.877441,false,Manual,1.2",
