        [10033956] = {
            ["Camera"] = "266.638672,58.79425,117.066406,0.000145,0.40126,172.603455,30.000008,383.911041,false,Manual,3.18767",
            ["Content"] = "我好像梦见……很多……从前的事……",
            ["ContentFR"] = "Je crois... que j’ai rêvé... à tant de choses passées...",
            ["DialogueId"] = 10033956,
            ["FinalCamera"] = "267.264648,63.618469,117.066406,0.000145,0.40126,174.603333,30.000008,383.911041,false,Manual,3.18767",
