        [10033959] = {
            ["Camera"] = "-286.618164,517.352295,362.435547,0.000032,-29.40173,-53.420368,30.000008,104.238808,false,DoNotOverride,2.390177",
            ["Content"] = "是你们……我记得刚才是在和布——不对，是和你们在下水道……抓……",
            ["ContentFR"] = "C’est vous... Je me souviens... j’étais avec Blu— non... avec vous, dans les égouts... à poursuivre ce—",
            ["DialogueId"] = 10033959,
            ["FinalCamera"] = "-258.114746,478.944214,335.484375,0.000035,-28.201666,-52.620518,30.000008,104.238808,false,DoNotOverride,2.390177",
