            },
        [10033961] = {
            ["Camera"] = "-0.458984,125.16803,121.416016,0.000119,15.798364,151.969162,35.000008,465.220367,false,DoNotOverride,7.813529",
            ["Content"] = "别急，别急，你都躺了两天了，先喝口水，吃点东西，慢慢说。",
            ["ContentFR"] = "Doucement, doucement. Vous êtes restée inconsciente deux jours. Buvez un peu d’eau, mangez quelque chose, et parlez après.",
            ["DialogueId"] = 10033961,
            ["FacialId"] = {
                [1] = "200021:Doubt01",
                [2] = "\
100360:Sad01",
