        [10033964] = {
            ["Camera"] = "131.790039,122.645935,122.564453,0.000205,6.79308,168.303848,35.000015,364.535095,false,DoNotOverride,1.2",
            ["Content"] = "别动别动别动，你不会又想自己跑一趟那个下水道吧？你们军团的人在那搜着呢，你还病着，别去添乱了。",
            ["ContentFR"] = "Hé, ne bougez pas ! Ne me dites pas que vous pensez déjà retourner dans ces égouts ? Ton équipe est encore en train de fouiller là-bas. Et vous, vous êtes blessée. Dans cet état, vous n’aiderez personne.",
            ["DialogueId"] = 10033964,
            ["FinalCamera"] = "133.391602,129.9245,122.564453,0.000205,6.79308,170.903305,35.000015,364.535095,false,DoNotOverride,1.2",
            ["GUID"] = "191E7538",
