            ["TalkActionId"] = {
                [1] = "200021:Talk02_Start",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/story/1003/100339/191E7538",
            },
        [10033965] = {
            ["Camera"] = "397.937012,-12.607971,226.421875,0.000144,-19.40346,157.524979,30.0,388.355713,false,Manual,4.2486",
            ["Content"] = "嗯。你已经尽力了，接下来就交给你的同伴吧。",
            ["ContentFR"] = "Oui. Vous avez déjà fait tout ce que vous pouviez. Laissez vos camarades prendre le relais.",
            ["DialogueId"] = 10033965,
            ["FinalCamera"] = "397.937012,-12.607971,226.421875,0.000143,-14.803314,156.525467,30.0,388.355713,false,Manual,4.2486",
