        [10033967] = {
            ["Camera"] = "-268.598145,387.694153,258.564453,0.000162,-20.205399,-40.091068,35.000015,364.535095,false,DoNotOverride,3.069153",
            ["Content"] = "抱歉，耽误了你们的时间，连之前答应帮你找亲人的承诺都没法立刻履行了。",
            ["ContentFR"] = "Pardon. Je vous fais perdre votre temps. Et je n’ai même pas été capable de tenir ma promesse... vous aider à retrouver votre famille.",
            ["DialogueId"] = 10033967,
            ["FinalCamera"] = "-290.066406,405.767212,268.894531,0.000162,-20.205399,-40.091068,35.000015,364.535095,false,DoNotOverride,3.069153",
