            },
        [10033968] = {
            ["Camera"] = "258.082031,16.400024,106.958984,0.000199,2.394418,147.306931,35.000011,364.535095,false,DoNotOverride,3.069153",
            ["Content"] = "嗯……对了。",
            ["ContentFR"] = "Ah... oui.",
            ["DialogueId"] = 10033968,
            ["FinalCamera"] = "258.082031,16.400024,106.958984,0.000199,3.994383,144.706436,35.000011,364.535095,false,DoNotOverride,3.069153",
