        [10034204] = {
            ["Camera"] = "-106.195312,289.816406,169.058594,0.000185,-23.795893,-51.580635,35.000008,527.224426,false,DoNotOverride,2.038203",
            ["Content"] = "黎瑟还小的时候……她父母被秽蚀者变成的秽兽害死了，那只秽兽还杀掉了很多人。",
            ["ContentFR"] = "Quand Rhythm était enfant, ses parents ont été tués par un Dégradé. Et ce même Dégradé a pris la vie de nombreuses autres personnes.",
            ["DialogueId"] = 10034204,
            ["FacialId"] = {
                [1] = "100001:Doubt01",
