        [10034303] = {
            ["Camera"] = "-17.708496,52.410095,156.064453,0.000103,-9.997668,-26.946836,25.0,164.471054,false,Manual,3.0",
            ["Content"] = "{nickname}{性别：先生|女士}，你家人的名字、失散的地点、外貌特征，失散时的衣服和携带的物品，请务必详细说明，不要有所遗漏。",
            ["ContentFR"] = "{性别:Monsieur|Mademoiselle} {nickname}, veuillez fournir le nom des membres de votre famille disparue, le lieu où vous avez été séparés, leur apparence, les vêtements qu’ils portaient et tout objet qu’ils pourraient avoir eu avec eux. Soyez aussi détaillé que possible, ne laissez rien de côté.",
            ["DialogueId"] = 10034303,
            ["FinalCamera"] = "-12.471191,49.746948,155.033203,0.000104,-9.997668,-26.946619,25.0,164.471054,false,Manual,3.0",
            ["GUID"] = "191EACD6",
