            },
        [10034313] = {
            ["Camera"] = "128.091309,254.743591,98.091797,0.0001,5.804568,-98.531677,35.0,223.242523,false,Manual,5.0",
            ["Content"] = "好。虽然她不在你身边，但我希望……不，我相信她一定正坚强地生活着，等着和你重逢的那天。就像我和布鲁斯一样。",
            ["ContentFR"] = "Bien. Même si elle n’est pas à vos côtés, je veux croire... non, je suis certaine qu’elle reste forte, en attendant le jour de vos retrouvailles. Tout comme moi et Blues.",
            ["DialogueId"] = 10034313,
            ["FacialId"] = {
                [1] = "100001:None",
                },
            ["FinalCamera"] = "134.226074,253.823425,98.091797,0.000101,5.804568,-98.531677,35.0,223.242523,false,Manual,5.0",
            ["GUID"] = "191EAE7A",
