        [10034314] = {
            ["Camera"] = "-146.145508,84.5,194.298828,0.000115,-17.393253,-11.726353,25.000002,211.201675,false,Manual,5.0",
            ["Content"] = "啊……抱歉之前可能没说过，布鲁斯是我弟弟，他现在正作为“桂冠卡戎”候补，在内城的第六军团服役。",
            ["ContentFR"] = "Ah... pardonnez-moi, je ne vous l’avais peut-être pas dit. Blues est mon frère cadet. Il sert actuellement dans la VIᵉ Légion, au sein de la cité intérieure, en tant que candidat au titre de Charon Couronné.",
            ["DialogueId"] = 10034314,
            ["FacialId"] = {
                [1] = "100361:Ahaha01",
                },
            ["FinalCamera"] = "-145.09082,89.584778,193.029297,0.000114,-17.193224,-12.92649,25.000002,211.201675,false,Manual,5.0",
            ["GUID"] = "191EAEA4",
            ["LookAt"] = {
                [1] = "100361:n(100001)",
                },
            ["NextDialogue"] = 10034315,
            ["SpeakNpcId"] = 100361,
            ["TalkActionId"] = {
                [1] = "100361:AgreeHead",
                },
            ["ToFinalCameraBlendTime"] = 12,
            ["VoiceName"] = "voice/$Locale$/story/1003/100343/191EAEA4",
            },
        [10034315] = {
            ["Camera"] = "142.187012,14.526367,158.126953,0.000148,-1.3962,155.668839,35.000011,185.386246,false,Manual,22.0",
            ["Content"] = "“桂冠卡戎”？这可不容易。拿到桂冠资格的都是强者中的强者。",
            ["ContentFR"] = "Un Charon Couronné ? Rien que ça... On n’y parvient qu’en étant l’élite des élites.",
            ["DialogueId"] = 10034315,
            ["FacialId"] = {
                [1] = "100361:None",
                },
            ["FinalCamera"] = "131.676758,19.278259,160.109375,0.000148,-1.596215,155.669006,35.000011,185.386246,false,Manual,22.0",
            ["GUID"] = "191EAECE",
            ["LookAt"] = {
