        [10034318] = {
            ["Camera"] = "-117.456543,432.085693,206.490234,0.000006,-14.597705,-63.5117,25.000002,649.314514,false,Manual,22.0",
            ["Content"] = "恭喜恭喜！万里挑一，就为了贵族老爷牙齿缝里抠出来的那几块骨头。",
            ["ContentFR"] = "Félicitations, vraiment. Tout ça pour quémander les restes que les nobles daignent laisser tomber de leur table...",
            ["DialogueId"] = 10034318,
