        [10034334] = {
            ["Camera"] = "78.430176,458.281433,156.322266,0.000271,-2.599297,-86.551003,45.0,402.692322,false,Manual,5.0",
            ["Content"] = "这种事本不该扯上你们平民。都怪第六军团这群不堪一用的废物。",
            ["ContentFR"] = "Des civils n’auraient jamais dû être mêlés à cela. Tout est la faute de ces incapables de la VIᵉ Légion.",
            ["DialogueId"] = 10034334,
