        [10034336] = {
            ["Camera"] = "133.126465,139.744141,172.181641,0.000278,-11.599545,-118.150055,35.0,167.578171,false,Manual,5.0",
            ["Content"] = "狩月人，既然已经卷进来了，有余力的话，继续协助我们。有些事还是交给本地人干更利索。",
            ["ContentFR"] = "Quant à vous, Chasseurs de Phoxène. Puisque vous êtes déjà impliqué, poursuivez l’assistance si vous en avez la force. Certaines choses sont mieux gérées par les locaux.",
            ["DialogueId"] = 10034336,
            ["FinalCamera"] = "133.126465,139.744141,168.591797,0.000281,-10.599483,-118.149986,35.0,170.237289,false,Manual,5.0",
            ["GUID"] = "191EB26A",
            ["NextDialogue"] = 10034337,
