        [10034512] = {
            ["Camera"] = "-82.986328,-110.776855,211.299805,0.000019,-16.392576,-1.394043,20.000011,100000.0,false,Manual,22.0",
            ["Content"] = "物资后续的事我来处理。你们去把这张任务清单上的事解决一下。",
            ["ContentFR"] = "Je m’occupe de la cargaison. Vous, prenez en charge les missions de cette liste.",
            ["DialogueId"] = 10034512,
            ["FinalCamera"] = "-82.824219,-104.039307,211.299805,0.000019,-16.392576,-1.394043,20.000011,100000.0,false,Manual,22.0",
