        [10034513] = {
            ["Camera"] = "138.911301,-61.80991,71.665039,0.000161,5.605085,43.786785,35.000008,140.267044,false,Manual,3.0",
            ["Content"] = "好，好长，有8、16、24个……好多任务，数不完了！呜，早知道不该接这委托的！",
            ["ContentFR"] = "Quoi !? Mais... mais c’est interminable ! Huit... seize... vingt-quatre... j’arrête pas de compter ! <I>Ouin,</> on n’aurait jamais dû accepter cette mission !",
            ["DialogueId"] = 10034513,
            ["FacialId"] = {
                [1] = "200002:Shock02",
                },
            ["FinalCamera"] = "138.911301,-61.80991,71.665039,0.000161,5.605085,43.786785,37.0,140.267044,false,Manual,3.0",
