        [10034514] = {
            ["Camera"] = "8.53927,-134.372421,196.63501,0.000081,-10.19379,0.797159,30.0,384.301636,false,Manual,3.0",
            ["Content"] = "长官，这么多任务我们做完都能原地入伍了吧。",
            ["ContentFR"] = "Monsieur, si on boucle tout ça, on gagne directement le droit de s’enrôler, non ?",
