        [10034515] = {
            ["Camera"] = "233.564697,18.109272,134.374268,0.000092,9.606441,-136.785706,45.0,243.950089,false,Manual,22.0",
            ["Content"] = "有时间阴阳怪气，不如早点开始干活。哼，若不是第六军团的渎职，也用不着十三军团来给这帮废物擦屁股。",
            ["ContentFR"] = "Moins de sarcasmes et mets cette langue bien pendue au travail. <I>Hmpf.</> Si la VIᵉ Légion ne faisait pas preuve d’autant de négligence, la XIIIᵉ Légion n’aurait pas à nettoyer derrière vous.",
            ["DialogueId"] = 10034515,
            ["FacialId"] = {
                [1] = "200021:None",
                },
            ["FinalCamera"] = "241.94809,8.809711,138.942383,0.000091,8.206417,-140.185257,45.0,243.950089,false,Manual,22.0",
