        [10034523] = {
            ["Camera"] = "411.256287,27.705805,132.101562,0.0002,4.006999,-150.270157,45.000023,100000.0,false,Manual,22.0",
            ["Content"] = "行了，谁该受罚有军事法庭操心，既然琳恩长官没说要拘押你，就去做你该做的事。",
            ["ContentFR"] = "Assez. C’est au tribunal militaire de décider qui doit être puni. Tant que le Major Lynn n’a pas ordonné votre arrestation, contentez-vous de faire votre travail.",
            ["DialogueId"] = 10034523,
            ["FinalCamera"] = "412.643616,25.277588,132.101562,0.0002,4.006999,-150.270157,45.000023,100000.0,false,Manual,22.0",
