            },
        [10034529] = {
            ["Camera"] = "76.509949,95.736488,35.371094,0.000062,15.598738,-23.400145,35.000011,544.895874,false,DoNotOverride,22",
            ["Content"] = "我们也有帮不少忙呀！",
            ["ContentFR"] = "Hé, on a quand même beaucoup aidé nous aussi !",
            ["DialogueId"] = 10034529,
            ["GUID"] = "191ED1EA",
