            },
        [10034530] = {
            ["Camera"] = "313.703003,-7.806791,124.205078,0.000106,14.197558,-47.393547,35.000015,116.556152,false,Manual,4.0",
            ["Content"] = "你是指搬弹药箱误触引爆，还是指堵管道时时撞坏水闸让大伙白忙活半天？",
            ["ContentFR"] = "Ah oui ? Tu veux dire quand tu as fait exploser la caisse de munitions en la portant, ou quand tu as pété la vanne en réparant la conduite d’eau, et qu’on a dû tout refaire à zéro ?",
            ["DialogueId"] = 10034530,
            ["FacialId"] = {
                [1] = "200021:Unhappy02",
                },
            ["GUID"] = "191ED214",
