            },
        [10034531] = {
            ["Camera"] = "426.979126,-187.174683,184.529053,0.000142,-24.601282,121.190933,35.000019,348.247833,false,Manual,2.8",
            ["Content"] = "呃……那些是意外，意外！",
            ["ContentFR"] = "Euh... c’étaient des accidents, des accidents ! De simples maladresses, rien de plus !",
            ["DialogueId"] = 10034531,
            ["FacialId"] = {
