            },
        [10034532] = {
            ["Camera"] = "379.26709,-408.699371,228.950928,0.000039,-18.000458,96.800278,35.000011,544.895874,false,Manual,22.0",
            ["Content"] = "话说黎瑟现在在哪儿呢？平时这个时间都会在停车场准时等我们的。",
            ["ContentFR"] = "Au fait... où est Rhythm ? D’habitude, à cette heure, elle nous attend déjà au parking.",
            ["DialogueId"] = 10034532,
            ["FacialId"] = {
                [1] = "200021:None",
                [2] = "200002:None",
