                [2] = "200002:n(100001)",
                [3] = "100001:n(200021)",
                },
            ["NextDialogue"] = 10034533,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "200002:ScratchHead_End",
                [2] = "100001:Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100345/191ED268",
            },
        [10034533] = {
            ["Content"] = "确实，那家伙连每天等我们的位置和姿势都不带变的。",
            ["ContentFR"] = "C’est vrai. Elle ne change jamais ni l’endroit ni la posture où elle nous attend.",
            ["DialogueId"] = 10034533,
            ["GUID"] = "191ED292",
            ["LookAt"] = {
                [1] = "200021:n(200021)",
                [2] = "200002:n(200021)",
                [3] = "100001:n(200021)",
                },
            ["NextDialogue"] = 10034534,
            ["SpeakNpcId"] = 200021,
            ["TalkActionId"] = {
                [1] = "100001:Talk02_End",
                [2] = "200021:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100345/191ED292",
            },
        [10034534] = {
            ["Camera"] = "240.401016,109.887741,127.815674,0.00013,3.595767,-46.793732,35.000011,296.605652,false,Manual,4.0",
            ["Content"] = "能让这么死板的家伙挪腾地方，怕是又出什么事了？四处找找吧。",
            ["ContentFR"] = "Si une personne aussi rigide change ses habitudes, c’est qu’il s’est passé quelque chose. Allons fouiller les environs.",
            ["DialogueId"] = 10034534,
            ["GUID"] = "191ED2BC",
            ["LookAt"] = {
                [1] = "200021:n(100001)",
                [2] = "200002:n(200021)",
                [3] = "100001:n(200021)",
                },
            ["SpeakNpcId"] = 200021,
            ["VoiceName"] = "voice/$Locale$/story/1003/100345/191ED2BC",
            },
        [10034535] = {
            ["Camera"] = "313.962891,-339.905273,217.369629,0.000059,-19.399368,135.380035,35.000008,100000.0,false,Manual,22.0",
            ["Content"] = "哇，你怎么又拿了张清单，不会军团又给你派活了吧。",
            ["ContentFR"] = "Oh, encore une liste ? Ne me dites pas que la Légion vous a encore refilé du boulot.",
            ["DialogueId"] = 10034535,
            ["FacialId"] = {
                [1] = "200021:Smile01",
                },
            ["FinalCamera"] = "313.962891,-339.905273,217.369629,0.000063,-13.999196,135.380676,35.000008,100000.0,false,Manual,22.0",
            ["GUID"] = "191ED2E6",
            ["NextDialogue"] = 10034536,
            ["RelatedWikiId"] = {
                [1] = 408003,
                [2] = 405005,
                [3] = 201011,
                [4] = 201024,
                },
            ["Scripts"] = "PARA{SEQ{CameraMoveTo{_delay{4},TargetPosition{\"26.724609,6.107422,129.455078,0.000083,-6.000642,155.993042,24.0,100000.0,false,Manual,22.0\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"14.828125,11.506348,128.541504,0.000083,-4.000551,155.593628,24.0,100000.0,false,Manual,22.0\"},duration{8}}},PlayAnimation{_delay{3},ActorId{200021},AnimationId{\"ConfidentLRToExplainR_Start\"},Duration{2}}}",
            ["SpeakNpcId"] = 200021,
            ["TalkActionId"] = {
                [1] = "200021:ConfidentLR_Start",
                },
            ["ToFinalCameraBlendTime"] = 6,
            ["VoiceName"] = "voice/$Locale$/story/1003/100345/191ED2E6",
            },
        [10034536] = {
            ["Camera"] = "-341.650391,-20.949707,145.34668,0.000154,-6.197078,11.655313,35.000015,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "不，这是我自己整理的物资清单。自从十三军团介入“卡戎狩猎”，市民们出行愈发不便。尤其是雾区的食物储备本来就不够，我想能给大家送点物资也是好的。",
            ["ContentFR"] = "Non. C’est un inventaire que j’ai établi moi-même. Depuis que la XIIIᵉ Légion a pris en charge cette affaire, les déplacements des citoyens sont devenus encore plus compliqués. Surtout à Brumelac, où les vivres manquent déjà cruellement.\
Alors... j’ai pensé qu’apporter un peu de provisions pourrait au moins aider.",
            ["DialogueId"] = 10034536,
            ["FacialId"] = {
                [1] = "100304:Think01",
                },
            ["FinalCamera"] = "-325.760742,-56.51709,144.594238,0.000154,-5.997029,18.256239,35.000015,100000.0,false,DoNotOverride,22.0",
            ["GUID"] = "191ED310",
            ["LookAt"] = {
                [1] = "100304:n(200021)",
                },
            ["NextDialogue"] = 10034537,
            ["Scripts"] = "PARA{SEQ{CameraMoveTo{_delay{5},TargetPosition{\"-132.125977,37.652344,136.237793,0.000147,-3.197143,9.206694,35.000011,100000.0,false,DoNotOverride,22.0\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-127.595703,16.415039,136.237793,0.000146,-3.197109,18.007582,35.000011,100000.0,false,DoNotOverride,22.0\"},duration{8}}},PlayAnimation{_delay{4},ActorId{100304},AnimationId{\"Talk03_End\"},Duration{2}},PlayAnimation{_delay{4},ActorId{200021},AnimationId{\"ConfidentLR_End\"},Duration{2}}}",
            ["SpeakNpcId"] = 100304,
            ["TalkActionId"] = {
                [1] = "100304:Talk03_Start",
                [2] = "200021:ConfidentLRToExplainR_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1003/100345/191ED310",
            },
        [10034537] = {
            ["Camera"] = "64.092773,19.856934,138.348145,0.000255,-4.402309,155.469559,30.000002,198.150391,false,Manual,2.669626",
            ["Content"] = "你还真是半点都闲不下来啊——好了停，我知道你又要“职责所在”了。",
            ["ContentFR"] = "Vous ne savez vraiment pas rester tranquille, hein ? Stop, je vois venir votre sempiternel « C’est mon devoir ».",
            ["DialogueId"] = 10034537,
            ["FacialId"] = {
                [1] = "200021:Smile01",
                },
            ["FinalCamera"] = "59.726562,11.441406,138.348145,0.000256,-4.202267,153.069778,30.000002,198.150391,false,Manual,2.669626",
            ["GUID"] = "191ED33A",
            ["LookAt"] = {
                [1] = "100001:n(100304)",
                [2] = "200021:n(100304)",
                },
            ["NextOptions"] = {
                [1] = 10034538,
                [2] = 10034541,
                },
            ["SpeakNpcId"] = 200021,
            ["TalkActionId"] = {
                [1] = "200021:Talk03_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1003/100345/191ED33A",
            },
        [10034538] = {
            ["Content"] = "我们也来帮忙吧。",
            ["ContentFR"] = "<I>Aidons-la, nous aussi.</>",
            ["DialogueId"] = 10034538,
            ["GUID"] = "191ED364",
            ["ImprPlusId"] = 1007,
            ["NextDialogue"] = 10034539,
            },
        [10034539] = {
            ["Camera"] = "-145.116211,-92.38623,122.953613,0.000255,0.797418,50.270557,35.000008,198.150391,false,DoNotOverride,2.669626",
            ["Content"] = "谢……啊，不是，麻烦大家了。",
            ["ContentFR"] = "Je... Merci. Je veux dire... désolée de vous déranger.",
            ["DialogueId"] = 10034539,
            ["FacialId"] = {
                [1] = "100304:Disappoint01",
                },
            ["FinalCamera"] = "-141.902344,-95.058105,122.953613,0.000255,0.997412,51.070686,35.000008,198.150391,false,DoNotOverride,2.669626",
            ["GUID"] = "191ED38E",
            ["LookAt"] = {
                [1] = "100304:n(100001)",
                },
            ["NextDialogue"] = 10034540,
            ["Scripts"] = "PlayAnimation{_delay{4},ActorId{100304},AnimationId{\"Sigh_End\"},Duration{2}}",
            ["SpeakNpcId"] = 100304,
            ["TalkActionId"] = {
                [1] = "100304:Sigh_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1003/100345/191ED38E",
            },
        [10034540] = {
            ["Camera"] = "275.59668,-135.068359,262.251953,0.000129,-23.202957,151.422806,35.000015,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "这才对嘛，这么久了还说谢，就太见外了。",
            ["ContentFR"] = "Voilà qui est mieux. Après tout, nous avons traversé beaucoup de choses ensemble.",
            ["DialogueId"] = 10034540,
            ["FacialId"] = {
                [1] = "200021:Ahaha01",
                [2] = "100304:Sad01",
                },
            ["FinalCamera"] = "241.146484,-116.370117,245.611328,0.000129,-23.002949,151.8228,35.000015,100000.0,false,DoNotOverride,22.0",
            ["GUID"] = "191ED3B8",
            ["NextDialogue"] = 10034545,
            ["SpeakNpcId"] = 200021,
            ["TalkActionId"] = {
                [1] = "200021:Talk03_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1003/100345/191ED3B8",
            },
        [10034541] = {
            ["Content"] = "我也缺，能帮我搞点月石吗？",
            ["ContentFR"] = "<I>Moi aussi je manque de provisions. Je peux avoir un peu de Phoxène ?</>",
            ["DialogueId"] = 10034541,
            ["GUID"] = "191ED3E2",
            ["ImprPlusId"] = 1010,
            ["NextDialogue"] = 10034542,
            },
        [10034542] = {
            ["Camera"] = "-145.116211,-92.38623,122.953613,0.000255,0.797418,50.270557,35.000008,198.150391,false,DoNotOverride,2.669626",
            ["Content"] = "如果对你来说是必需品的话。",
            ["ContentFR"] = "Si c’est vraiment indispensable pour vous, je verrai ce que je peux faire.",
            ["DialogueId"] = 10034542,
            ["FacialId"] = {
                [1] = "100304:Doubt01",
                },
            ["FinalCamera"] = "-141.902344,-95.058105,122.953613,0.000255,0.997412,51.070686,35.000008,198.150391,false,DoNotOverride,2.669626",
            ["GUID"] = "191ED40C",
            ["LookAt"] = {
                [1] = "100304:n(100001)",
                },
            ["NextDialogue"] = 10034543,
            ["Scripts"] = "PlayAnimation{_delay{4},ActorId{100304},AnimationId{\"Talk01_End\"},Duration{2}}",
            ["SpeakNpcId"] = 100304,
            ["TalkActionId"] = {
                [1] = "100304:Talk01_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1003/100345/191ED40C",
            },
        [10034543] = {
            ["Camera"] = "47.226562,105.367188,139.936523,0.000253,-8.199676,-117.541321,35.000011,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "别当真别当真，小仆从就是随口一说啦，我们还是看看你还缺什么东西吧。",
            ["ContentFR"] = "Ne {性别:le|la} prenez pas au sérieux ! Mon petit larbin plaisantait. Allez, voyons plutôt ce qui reste sur ta liste.",
            ["DialogueId"] = 10034543,
            ["FinalCamera"] = "47.226562,105.367188,139.936523,0.000257,-12.799651,-114.540627,35.000011,100000.0,false,DoNotOverride,22.0",
            ["GUID"] = "191ED436",
            ["LookAt"] = {
                [1] = "100304:n(200002)",
                },
            ["NextDialogue"] = 10034544,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Confident_Start",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/story/1003/100345/191ED436",
            },
        [10034544] = {
            ["Camera"] = "20.209961,-161.042969,88.688477,0.000263,5.556803,128.063461,35.000015,291.948975,false,Manual,4.0",
            ["Content"] = "你就只是单纯想继续跑去玩吧！",
            ["ContentFR"] = "Avoue, tu cherches juste une excuse pour aller t’amuser encore.",
            ["DialogueId"] = 10034544,
            ["FacialId"] = {
                [1] = "200021:Doubt01",
                },
            ["FinalCamera"] = "23.350586,-158.584473,88.688477,0.000264,5.556803,129.063293,35.000015,291.948975,false,Manual,4.0",
            ["GUID"] = "191ED460",
            ["LookAt"] = {
                [1] = "200021:n(200002)",
                [2] = "100304:n(100304)",
                [3] = "100001:n(100001)",
                },
            ["NextDialogue"] = 10034545,
            ["Scripts"] = "LookAt{_delay{2},LookAtDescription{\"200002:n(200021)\"}}",
            ["SpeakNpcId"] = 200021,
            ["TalkActionId"] = {
                [1] = "200021:Confident_End",
                },
            ["ToFinalCameraBlendTime"] = 4,
            ["VoiceName"] = "voice/$Locale$/story/1003/100345/191ED460",
            },
        [10034545] = {
            ["Camera"] = "58.495117,-31.134766,130.94043,0.000255,1.197216,122.468346,35.0,198.150391,false,DoNotOverride,2.669626",
            ["Content"] = "我看看……嗯，物资清单上还有最后一项，送到雾区的鱼。",
            ["ContentFR"] = "Voyons... oui, il ne reste plus qu’une dernière chose, livrer du poisson à Brumelac.",
            ["DialogueId"] = 10034545,
            ["FacialId"] = {
                [1] = "200021:Confident01",
                [2] = "100304:Unhappy01",
                },
            ["FinalCamera"] = "62.019531,-28.944824,130.94043,0.000255,0.997201,121.468498,35.0,198.150391,false,DoNotOverride,2.669626",
            ["GUID"] = "191ED48A",
            ["LookAt"] = {
                [1] = "200002:n(200002)",
                [2] = "100001:n(100304)",
                [3] = "200021:n(100304)",
                [4] = "100304:n(100001)",
                },
            ["NextDialogue"] = 10034546,
            ["Scripts"] = "PARA{SEQ{CameraMoveTo{_delay{3},TargetPosition{\"-155.210938,-117.219727,121.275391,0.000203,-0.800443,54.851498,35.000015,100000.0,false,DoNotOverride,22.0\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-150.672852,-120.304688,121.275391,0.000203,-0.800443,53.851078,35.000015,100000.0,false,DoNotOverride,22.0\"},duration{8}}},PlayAnimation{_delay{4},ActorId{100304},AnimationId{\"Explain01_Start\"},Duration{2}}}",
            ["SpeakNpcId"] = 100304,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1003/100345/191ED48A",
            },
        [10034546] = {
            ["Camera"] = "-12.336914,-66.583008,102.745605,0.000291,-9.999444,-97.554825,35.000008,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "哇，是钓鱼诶——我也要钓我也要钓！",
            ["ContentFR"] = "Ouah ! De la pêche ?! Moi aussi je veux pêcher, moi aussi, moi aussi !",
            ["DialogueId"] = 10034546,
            ["FacialId"] = {
                [1] = "200002:Smile02",
                },
            ["FinalCamera"] = "5.630859,58.565918,130.43457,0.000288,-14.59942,-97.35498,35.000008,100000.0,false,DoNotOverride,22.0",
            ["GUID"] = "191ED4B4",
            ["LookAt"] = {
                [1] = "100304:n(200002)",
                [2] = "100001:n(200002)",
                [3] = "200021:n(200002)",
                },
            ["Scripts"] = "SEQ{CameraMoveTo{_delay{1.5},TargetPosition{\"33.922852,-373.008789,157.193848,0.000295,-13.007589,102.518494,25.0,198.150391,false,DoNotOverride,2.669626\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"28.636719,-349.197754,151.557129,0.000295,-13.007589,102.518494,25.0,198.150391,false,DoNotOverride,2.669626\"},duration{8}}}",
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "100304:Explain01_End",
                [2] = "200002:Confident_Start",
                },
            ["ToFinalCameraBlendTime"] = 0.5,
            ["VoiceName"] = "voice/$Locale$/story/1003/100345/191ED4B4",
            },
        [10034601] = {
            ["Content"] = "呵呵……",
            ["ContentFR"] = "... Héhé.",
            ["DialogueId"] = 10034601,
            ["GUID"] = "191EDDBA",
            ["NextDialogue"] = 10034602,
            ["SpeakNpcId"] = 100304,
            ["VoiceName"] = "voice/$Locale$/story/1003/100346/191EDDBA",
            },
        [10034602] = {
            ["Content"] = "你笑什么？",
            ["ContentFR"] = "Qu’est-ce qui vous fait sourire ?",
            ["DialogueId"] = 10034602,
            ["GUID"] = "191EDDE4",
            ["NextDialogue"] = 10034603,
            ["SpeakNpcId"] = 200021,
            ["VoiceName"] = "voice/$Locale$/story/1003/100346/191EDDE4",
            },
        [10034603] = {
            ["Content"] = "我想起上次这样在湖边钓鱼，还是三年前和布鲁斯一起。",
            ["ContentFR"] = "Je repensais à la dernière fois que j’ai pêché ici... c’était il y a trois ans, avec Blues.",
            ["DialogueId"] = 10034603,
            ["GUID"] = "191EDE0E",
            ["NextDialogue"] = 10034604,
            ["SpeakNpcId"] = 100304,
            ["VoiceName"] = "voice/$Locale$/story/1003/100346/191EDE0E",
            },
        [10034604] = {
            ["Content"] = "那家伙虽然聪明，但太好动了，根本坐不住。所以他钓一整天，篓子都是空的。",
            ["ContentFR"] = "Il est intelligent, mais tellement turbulent qu’il ne tenait pas en place. Il a pêché toute la journée et s’est retrouvé avec un panier vide.",
            ["DialogueId"] = 10034604,
            ["GUID"] = "191EDE38",
            ["NextDialogue"] = 10034605,
            ["SpeakNpcId"] = 100304,
            ["VoiceName"] = "voice/$Locale$/story/1003/100346/191EDE38",
            },
        [10034605] = {
            ["Content"] = "……不知道他现在在内城过得怎么样了，有没有学会钓鱼。",
            ["ContentFR"] = "... Je me demande comment il vit aujourd’hui, dans la cité intérieure. Peut-être qu’il a enfin appris à pêcher.",
            ["DialogueId"] = 10034605,
            ["GUID"] = "191EDE62",
            ["NextDialogue"] = 10034606,
            ["SpeakNpcId"] = 100304,
            ["VoiceName"] = "voice/$Locale$/story/1003/100346/191EDE62",
            },
        [10034606] = {
            ["Content"] = "哼哼，你们这些凡人啊，总被这些乱七八糟的感情羁绊，不像本魔王大人。",
            ["ContentFR"] = "Hmpf, vous les mortels, toujours prisonniers de vos attachements dérisoires. Prenez exemple sur moi, le Roi Démon, cool et détaché de tout !",
            ["DialogueId"] = 10034606,
            ["GUID"] = "191EDE8C",
            ["NextDialogue"] = 10034607,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1003/100346/191EDE8C",
            },
        [10034607] = {
            ["Content"] = "没事的小矮子，我们也是你的家人。只要你开心，让我管你叫奶奶都行。",
            ["ContentFR"] = "C’est bon, Petit Champi, nous sommes ta famille, nous aussi. Si ça peut te faire plaisir, je peux même t’appeler mamie.",
            ["DialogueId"] = 10034607,
            ["GUID"] = "191EDEB6",
            ["NextDialogue"] = 10034608,
            ["SpeakNpcId"] = 200021,
            ["VoiceName"] = "voice/$Locale$/story/1003/100346/191EDEB6",
            },
        [10034608] = {
            ["Content"] = "你，你怎么突然这么好……",
            ["ContentFR"] = "Hein ? Mais... pourquoi tu es si gentil tout à coup... ?",
            ["DialogueId"] = 10034608,
            ["GUID"] = "191EDEE0",
            ["NextDialogue"] = 10034609,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1003/100346/191EDEE0",
            },
        [10034609] = {
            ["Content"] = "奶奶，我饿，给点零用钱。",
            ["ContentFR"] = "Mamie, j’ai faim. Tu me donnes un peu d’argent de poche ?",
            ["DialogueId"] = 10034609,
            ["GUID"] = "191EDF0A",
            ["NextDialogue"] = 10034610,
            ["SpeakNpcId"] = 200021,
            ["VoiceName"] = "voice/$Locale$/story/1003/100346/191EDF0A",
            },
        [10034610] = {
            ["Content"] = "可恶！",
            ["ContentFR"] = "Aaaargh ! Je le savais !",
            ["DialogueId"] = 10034610,
            ["GUID"] = "191EDF34",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1003/100346/191EDF34",
            },
        [10034611] = {
            ["Content"] = "这样就齐了，把物资送到雾区吧。",
            ["ContentFR"] = "Ça devrait suffire. Allons livrer tout ça à Brumelac.",
            ["DialogueId"] = 10034611,
            ["GUID"] = "191EDF5E",
            ["SpeakNpcId"] = 100304,
            ["VoiceName"] = "voice/$Locale$/story/1003/100346/191EDF5E",
            },
        [10034612] = {
            ["Content"] = "宵禁期间禁止通行，请各位市民配合！",
            ["ContentFR"] = "La circulation est interdite pendant le couvre-feu. Merci de votre coopération !",
            ["DialogueId"] = 10034612,
            ["GUID"] = "191EDF60",
            ["VoiceName"] = "voice/$Locale$/story/1003/100346/191EDF60",
            },
        [10034613] = {
            ["Content"] = "（<H>地面都被士兵封锁了</>……或许可以试试别的路——比如<H>楼顶</>？）",
            ["ContentFR"] = "<H>Le sol est entièrement bouclé par les soldats</>... Peut-être vaudrait-il mieux tenter un autre chemin — par exemple, les <H>toits</> ?",
            ["DialogueId"] = 10034613,
            ["GUID"] = "191EDF61",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1003/100346/191EDF61",
            },
        [10034701] = {
