        [10034705] = {
            ["Camera"] = "183.185303,-145.604492,137.870605,0.000083,-4.397877,148.777023,36.000004,436.538635,false,Manual,15.0",
            ["Content"] = "不过你们短短几天居然和军团的长官打上交道了？怎么办到的呀，教教我教教我——",
            ["ContentFR"] = "Mais dites-moi, comment vous avez fait pour sympathiser aussi vite avec une officière de la Légion ? Apprenez-moi, apprenez-moi !",
            ["DialogueId"] = 10034705,
            ["FinalCamera"] = "190.307617,-133.589844,137.870605,0.000081,-4.197875,150.976791,36.000004,436.538635,false,Manual,15.0",
