        [10034715] = {
            ["Content"] = "各个区域都有士兵驻守，是已经完成了封锁吗？",
            ["ContentFR"] = "Il y a des soldats à chaque coin... Est-ce que cela veut dire que la zone est déjà bloquée ?",
            ["DialogueId"] = 10034715,
            ["GUID"] = "191EF06E",
            ["NextDialogue"] = 10034716,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1003/100347/191EF06E",
            },
        [10034716] = {
            ["Content"] = "看来是。接下来随时可能遇敌。目标的身手我们是领教过的，务必当心。",
            ["ContentFR"] = "On dirait bien. Nous pouvons tomber sur la cible d’un instant à l’autre. Vous connaissez sa dangerosité, restez sur vos gardes.",
            ["DialogueId"] = 10034716,
            ["GUID"] = "191EF098",
            ["SpeakNpcId"] = 100304,
            ["VoiceName"] = "voice/$Locale$/story/1003/100347/191EF098",
            },
        [10034717] = {
            ["Content"] = "先去找克莱夫留下的标记吧。",
