            },
        [10034824] = {
            ["Camera"] = "-9.942383,21.341797,132.388428,0.000254,0.805327,76.790901,33.0,16827.542969,false,Manual,22.0",
            ["Content"] = "来听听克莱夫有什么新指示吧。",
            ["ContentFR"] = "Retournons voir Clive et voyons s’il a de nouvelles instructions.",
            ["DialogueId"] = 10034824,
            ["FinalCamera"] = "-9.302246,24.06543,132.428711,0.000254,0.805327,76.790901,33.0,16827.542969,false,Manual,22.0",
            ["GUID"] = "191F0250",
