            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/story/1003/100348/191F0250",
            },
        [10034825] = {
            ["Content"] = "小仆从，这里有个奇奇怪怪的机关诶！",
            ["ContentFR"] = "Petit larbin ! Regarde, un mécanisme bizarre !",
            ["DialogueId"] = 10034825,
            ["GUID"] = "191F0101",
            ["NextDialogue"] = 10034826,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1003/100348/191F0101",
            },
        [10034826] = {
            ["Content"] = "小矮子先别碰，当心有诈！……嗯，还好，只是普通的升降机。",
            ["ContentFR"] = "Ne touche à rien, Petit Champi ! Ça pourrait être un piège... ah. Non, ce n’est qu’un simple monte-charge.",
            ["DialogueId"] = 10034826,
            ["GUID"] = "191F0102",
            ["SpeakNpcId"] = 200021,
            ["VoiceName"] = "voice/$Locale$/story/1003/100348/191F0102",
            },
        [10034827] = {
            ["Content"] = "出现了新的路诶！简直像变魔术一样！",
            ["ContentFR"] = "Oooh ! Un passage ! Comme par magie !",
            ["DialogueId"] = 10034827,
            ["GUID"] = "191F0103",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1003/100348/191F0103",
            },
        [10034828] = {
            ["Content"] = "嘁，什么都没有嘛，我还以为会突然蹦出来啥。",
            ["ContentFR"] = "Tch. Rien du tout. J’étais presque sûr que quelque chose allait bondir.",
            ["DialogueId"] = 10034828,
            ["GUID"] = "191F0104",
            ["NextDialogue"] = 10034829,
            ["SpeakNpcId"] = 200021,
            ["VoiceName"] = "voice/$Locale$/story/1003/100348/191F0104",
            },
        [10034829] = {
            ["Content"] = "呸呸呸，不许乌鸦嘴！",
            ["ContentFR"] = "Eh ! Ne porte pas malheur !",
            ["DialogueId"] = 10034829,
            ["GUID"] = "191F0105",
            ["NextDialogue"] = 10034830,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1003/100348/191F0105",
            },
        [10034830] = {
            ["Content"] = "继续向上吧。",
            ["ContentFR"] = "Continuons à avancer.",
            ["DialogueId"] = 10034830,
            ["GUID"] = "191F0106",
            ["NextDialogue"] = 10034832,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1003/100348/191F0106",
            },
        [10034831] = {
            ["Content"] = "嚯，一下就亮起来了。边边角角都看得一清二楚。",
            ["ContentFR"] = "Oooh ! Tout s’est éclairé d’un coup... On distingue le moindre recoin.",
            ["DialogueId"] = 10034831,
            ["GUID"] = "191F0107",
            ["SpeakNpcId"] = 200021,
            ["VoiceName"] = "voice/$Locale$/story/1003/100348/191F0107",
            },
        [10034832] = {
            ["Content"] = "不得不说，这地方布置得还挺有艺术感的，简直像个缩小版的剧院舞台。",
            ["ContentFR"] = "Je dois avouer que l’endroit a de l’allure. On dirait un théâtre miniature.",
            ["DialogueId"] = 10034832,
            ["GUID"] = "191F0108",
            ["SpeakNpcId"] = 200021,
            ["VoiceName"] = "voice/$Locale$/story/1003/100348/191F0108",
            },
        [10034833] = {
            ["Content"] = "看样子这里没有什么陷阱。回去报告黎瑟长官吧。",
            ["ContentFR"] = "A priori, il n’y a pas de pièges. Retournons faire notre rapport à l’Officier Fischer.",
            ["DialogueId"] = 10034833,
            ["GUID"] = "191F0109",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1003/100348/191F0109",
            },
        [10034901] = {
            ["Camera"] = "-15.305176,154.117188,133.735596,0.000155,3.200162,-93.18692,35.0,100000.0,false,Manual,22.0",
            ["Content"] = "我是黎瑟·费西尔。报告长官，我们已抵达银色和平广场下方，已完成搜查，此地暂无异常，请求下一步指示。",
            ["ContentFR"] = "Ici Rhythm Fischer. Rapport : nous avons atteint la zone sous la Place de la Paix d’Argent. Fouille complète, aucun élément suspect relevé. En attente de directives.",
            ["DialogueId"] = 10034901,
            ["FinalCamera"] = "-12.03125,153.935547,133.735596,0.000155,3.200162,-93.78685,35.0,100000.0,false,Manual,22.0",
