        [10035008] = {
            ["Content"] = "嘁，二流货色。",
            ["ContentFR"] = "Tss, de la racaille de seconde zone.",
            ["DialogueId"] = 10035008,
            ["GUID"] = "191F2080",
            ["NextDialogue"] = 10035009,
            ["SpeakNpcId"] = 200022,
            ["VoiceName"] = "voice/$Locale$/story/1003/100350/191F2080",
            },
        [10035009] = {
            ["Content"] = "琳恩长官，我来协助您！",
            ["ContentFR"] = "Major Lynn, je viens vous assister !",
            ["DialogueId"] = 10035009,
            ["GUID"] = "191F20AA",
            ["NextDialogue"] = 10035010,
            ["SpeakNpcId"] = 100304,
            ["VoiceName"] = "voice/$Locale$/story/1003/100350/191F20AA",
            },
        [10035010] = {
            ["Content"] = "我们也上吧。",
            ["ContentFR"] = "Allons-y aussi.",
            ["DialogueId"] = 10035010,
            ["GUID"] = "191F20D4",
            ["NextDialogue"] = 10035011,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1003/100350/191F20D4",
            },
        [10035011] = {
            ["Content"] = "像上次那样，奥特赛德灵活牵制，我来寻找机会。",
            ["ContentFR"] = "L’Étranger, comme la dernière fois, occupe-le, je vais chercher une ouverture.",
            ["DialogueId"] = 10035011,
            ["GUID"] = "191F20FE",
            ["NextDialogue"] = 10035012,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1003/100350/191F20FE",
            },
        [10035012] = {
            ["Content"] = "没问题。",
            ["ContentFR"] = "Oui, oui, capitaine !",
            ["DialogueId"] = 10035012,
            ["GUID"] = "191F2128",
            ["SpeakNpcId"] = 200021,
            ["VoiceName"] = "voice/$Locale$/story/1003/100350/191F2128",
            },
        [10035013] = {
            ["Content"] = "默契的配合。你们证明了自己的价值，值得嘉奖。",
            ["ContentFR"] = "Bonne coordination. Vous avez prouvé votre valeur.",
            ["DialogueId"] = 10035013,
            ["GUID"] = "191F2152",
            ["NextDialogue"] = 10035014,
            ["SpeakNpcId"] = 200022,
            ["VoiceName"] = "voice/$Locale$/story/1003/100350/191F2152",
            },
        [10035014] = {
            ["Content"] = "那我就再教你们一个新的道理吧。",
            ["ContentFR"] = "En guise de récompense, je vais vous enseigner une leçon.",
            ["DialogueId"] = 10035014,
            ["GUID"] = "191F217C",
            ["NextDialogue"] = 10035015,
            ["SpeakNpcId"] = 200022,
            ["VoiceName"] = "voice/$Locale$/story/1003/100350/191F217C",
            },
        [10035015] = {
