            },
        [10035232] = {
            ["Camera"] = "-514.289307,44.722595,247.631836,0.000043,-15.820329,-3.607711,35.0,612.436279,false,Manual,22.0",
            ["Content"] = "抱歉，拉着你们絮叨了这么多陈年旧事……该继续行动了！趁着天色还不晚。",
            ["ContentFR"] = "Désolée de vous avoir assommés avec ces vieux souvenirs... Il est temps d’y aller, tant qu’il fait jour.",
            ["DialogueId"] = 10035232,
            ["FacialId"] = {
                [1] = "100304:Disappoint01",
                },
            ["FinalCamera"] = "-511.032501,44.516754,237.636963,0.000039,-14.420188,-4.007435,35.0,612.436279,false,Manual,22.0",
            ["GUID"] = "191F4540",
            ["LookAt"] = {
                [1] = "100304:n(100001)",
                },
            ["NextOptions"] = {
                [1] = 10035233,
                [2] = 10035234,
                },
            ["SpeakNpcId"] = 100304,
            ["TalkActionId"] = {
                [1] = "100304:Explain02_End",
                [2] = "\
200021:Talk03_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1003/100352/191F4540",
            },
        [10035233] = {
            ["Content"] = "一起去吧。我不会让你再留下遗憾。",
            ["ContentFR"] = "<I>Allons-y ensemble. Je ne vous laisserai pas repartir avec de nouveaux regrets.</>",
            ["DialogueId"] = 10035233,
            ["GUID"] = "191F456A",
            ["ImprPlusId"] = 1009,
            ["NextDialogue"] = 10035235,
            },
        [10035234] = {
            ["Content"] = "只有我们几个人行动吗？",
            ["ContentFR"] = "<I>Vous comptez y aller seulement avec nous ?</>",
            ["DialogueId"] = 10035234,
            ["GUID"] = "191F4594",
            ["ImprPlusId"] = 1006,
            ["NextDialogue"] = 10035235,
            },
        [10035235] = {
            ["Camera"] = "-152.189682,50.255051,133.710449,0.000057,0.579876,-3.407065,35.000008,194.348434,false,Manual,5.0",
            ["Content"] = "这是我自己的选择，而且我已经没有其他可以调动的下属了。所以各位不必陪我继续涉险。",
            ["ContentFR"] = "C’est mon choix. Je n’ai plus de subordonnés à mobiliser. Vous n’êtes pas obligés de risquer votre vie pour moi.",
            ["DialogueId"] = 10035235,
            ["FacialId"] = {
                [1] = "100001:None",
                [2] = "\
200021:None",
                },
            ["FinalCamera"] = "-144.869965,49.820297,133.784424,0.000057,0.579876,-3.407065,35.000008,194.348434,false,Manual,5.0",
            ["GUID"] = "191F45BE",
            ["NextDialogue"] = 10035236,
            ["SpeakNpcId"] = 100304,
            ["TalkActionId"] = {
                [1] = "100304:Talk01_Start",
                },
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/1003/100352/191F45BE",
            },
        [10035236] = {
            ["Camera"] = "-66.625938,-133.03833,203.941406,0.00007,-24.019957,54.40028,20.0,136.574539,false,Manual,5.0",
            ["Content"] = "说什么呢，都到这份上了，还想抛下我们自个儿揽功？总是为他人送去炭火的人，我们也必然不会让她冻死在雪里。",
            ["ContentFR"] = "Qu’est-ce que vous racontez ? Après tout ça, vous voulez partir seule et vous accaparer les honneurs ? Non. Comme si on allait laisser une bonne personne qui apporte de la chaleur aux autres geler dehors dans la neige.",
            ["DialogueId"] = 10035236,
            ["FinalCamera"] = "-66.625938,-133.03833,199.980713,0.000071,-23.21991,54.600311,20.0,136.574539,false,Manual,5.0",
            ["GUID"] = "191F45E8",
