        [10035244] = {
            ["Content"] = "我们现在需要确认凶手的下落和凶手的身份，但能用的线索似乎都断掉了。",
            ["ContentFR"] = "Nous devons encore découvrir à la fois l’identité et la localisation du coupable... mais avec les indices que nous avons, j’ai l’impression d’être dans une impasse.",
            ["DialogueId"] = 10035244,
            ["GUID"] = "191F4738",
            ["NextDialogue"] = 10035245,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1003/100352/191F4738",
            },
        [10035245] = {
            ["Content"] = "重新整理一下目前的线索，看看有没有什么被我们遗漏的吧。",
            ["ContentFR"] = "Récapitulons ce que nous avons trouvé jusque-là. Peut-être qu’on est passé à côté de quelque chose d’important.",
            ["DialogueId"] = 10035245,
            ["GUID"] = "191F4762",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1003/100352/191F4762",
            },
        [10035246] = {
            ["Camera"] = "10.279533,-79.354004,133.750244,0.000094,0.196983,102.649895,30.000008,100000.0,false,Manual,22.0",
            ["Content"] = "我们之前根据帷幕这条线索推测凶手可能与歌剧院有关，但工作人员的嫌疑已经被排除了。",
            ["ContentFR"] = "On avait d’abord pensé, avec l’indice du rideau, que le coupable avait un lien avec l’opéra. Mais on a déjà écarté le personnel.",
            ["DialogueId"] = 10035246,
            ["FinalCamera"] = "-2.861729,-18.827354,135.044922,0.000094,1.196997,102.249947,30.000008,100000.0,false,Manual,22.0",
            ["GUID"] = "191F478C",
            ["LookAt"] = {
                [1] = "200021:n(100001)",
                [2] = "200002:n(100001)",
                [3] = "100304:n(100001)",
                },
            ["NextDialogue"] = 10035247,
            ["Scripts"] = "PARA{\
SetLocation{ActorId{100001},TargetPoint{\"nvzhu_48_location\"},Visibility{\"Show\"}},\
SetLocation{ActorId{100304},TargetPoint{\"lise_48_location\"},Visibility{\"Show\"}},\
