                },
            ["NextDialogue"] = 10035250,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100352/191F480A",
            },
        [10035250] = {
            ["Camera"] = "-83.064827,-13.434433,122.876221,0.000078,11.996905,-30.740709,30.000013,100000.0,false,Manual,22.0",
            ["Content"] = "这么高雅的东西就别看我啦。",
            ["ContentFR"] = "Ne me regarde pas. C’est bien trop sophistiqué pour mes oreilles.",
            ["DialogueId"] = 10035250,
            ["FacialId"] = {
                [1] = "200021:Ahaha01",
                [2] = "100304:None",
                },
            ["GUID"] = "191F4834",
