            ["NextDialogue"] = 10035251,
            ["SpeakNpcId"] = 200021,
            ["TalkActionId"] = {
                [1] = "200021:ScratchHead_Start",
                [2] = "100001:Talk02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100352/191F4834",
            },
        [10035251] = {
            ["Camera"] = "230.964554,123.720169,183.445557,0.000094,-14.6028,-143.350281,30.000008,100000.0,false,Manual,22.0",
            ["Content"] = "唔，我也不会……黎瑟长官呢？",
            ["ContentFR"] = "Euh... moi non plus. Et toi, Rhythm ?",
            ["DialogueId"] = 10035251,
            ["FacialId"] = {
                [1] = "200021:None",
                },
