        [10035309] = {
            ["Content"] = "透气去了。",
            ["ContentFR"] = "Elle est sortie prendre l’air.",
            ["DialogueId"] = 10035309,
            ["GUID"] = "191F51E2",
            ["SpeakNpcId"] = 200021,
            ["TalkActionId"] = {
                [1] = "200021:Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100353/191F51E2",
            },
        [10035310] = {
            ["Camera"] = "27.261719,-48.188965,98.787598,0.000046,5.787246,58.397362,35.000008,100000.0,false,Manual,22.0",
            ["Content"] = "“……无言的白雪啊，苍穹的女儿……为那无名的孩子献上祝福……他和雪花跳起轻快的舞……”",
            ["ContentFR"] = "« ... Ô neige silencieuse, fille des cieux... Accorde ta bénédiction à l’enfant sans nom... Qu’il danse en liesse parmi les flocons légers... »",
            ["DialogueId"] = 10035310,
            ["FinalCamera"] = "42.640625,-23.193359,101.764648,0.000046,5.787246,58.397282,35.000008,100000.0,false,Manual,22.0",
            ["GUID"] = "191F520C",
            ["LookAt"] = {
                [1] = "200021:n(100304)",
                [2] = "200002:n(100304)",
                [3] = "100001:n(100304)",
                },
            ["NextDialogue"] = 10035311,
            ["RelatedWikiId"] = {
                [1] = 408003,
                [2] = 405005,
                [3] = 201011,
                [4] = 201024,
                },
            ["SpeakNpcId"] = 100304,
            ["TalkActionId"] = {
                [1] = "100304:Lise_Sing_Start",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/story/1003/100353/191F520C",
            },
        [10035311] = {
            ["Camera"] = "106.324219,18.061035,129.950195,0.000045,-7.413487,-143.597916,35.000008,100000.0,false,Manual,22.0",
            ["Content"] = "……就是这个！就是这个旋律。它叫什么，唱的什么意思？",
            ["ContentFR"] = "... C’est ça ! C’est cette mélodie ! Comment elle s’appelle ? Qu’est-ce que ça raconte ?",
            ["DialogueId"] = 10035311,
            ["FacialId"] = {
                [1] = "100001:Shock01",
                },
            ["GUID"] = "191F5236",
            ["LookAt"] = {
                [1] = "200021:n(100304)",
                [2] = "200002:n(100001)",
                [3] = "100001:n(100304)",
                },
            ["NextDialogue"] = 10035312,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100353/191F5236",
            },
        [10035312] = {
            ["Camera"] = "-158.65625,-332.602051,130.729492,0.000072,-4.813562,57.80043,35.000008,100000.0,false,Manual,22.0",
            ["Content"] = "咦？这个吗……我没留意，下意识就哼出来了。我想一下……",
            ["ContentFR"] = "Hein ? Celle que je viens de fredonner ? J’y ai même pas pensé... ça m’est venu tout seul. Attends...",
            ["DialogueId"] = 10035312,
            ["FacialId"] = {
                [1] = "100001:None",
                [2] = "100304:Shock01",
                },
            ["GUID"] = "191F5260",
            ["LookAt"] = {
                [1] = "200021:n(100304)",
                [2] = "200002:n(100304)",
                [3] = "100001:n(100304)",
                [4] = "100304:n(100001)",
                },
            ["NextDialogue"] = 10035313,
            ["SpeakNpcId"] = 100304,
            ["TalkActionId"] = {
                [1] = "100304:Lise_Sing_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100353/191F5260",
            },
        [10035313] = {
            ["Content"] = "这首是布鲁斯教给我的，叫《致无名者的安魂曲》，是歌剧《雪国的孩子》里的唱段。不过我唱的歌词不太对，真正的歌词应该会更悲伤一点。",
            ["ContentFR"] = "C’est Blues qui me l’a apprise. Ça s’appelle <I>Requiem pour les sans-nom</>. Un air de l’opéra <I>Né du blizzard</>. Mais les paroles que je chantais ne sont pas les vraies. Les originales sont bien plus tristes.",
            ["DialogueId"] = 10035313,
            ["FacialId"] = {
                [1] = "100304:None",
                },
            ["GUID"] = "191F528A",
            ["NextDialogue"] = 10035314,
            ["SpeakNpcId"] = 100304,
            ["TalkActionId"] = {
                [1] = "100001:Talk02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100353/191F528A",
            },
        [10035314] = {
            ["Content"] = "那首歌本来好像讲的是……一只无名的妖精，为了救它的朋友而牺牲，但朋友直到最后都不知道这件事，只有白雪记住了一切。",
            ["ContentFR"] = "Ça raconte l’histoire d’un esprit sans nom, qui se sacrifie pour sauver ses amis. Mais ceux-ci ne découvrent jamais la vérité. Seule la neige s’en souvient.",
            ["DialogueId"] = 10035314,
            ["GUID"] = "191F52B4",
            ["LookAt"] = {
                [1] = "100304:n(100304)",
                },
            ["NextDialogue"] = 10035315,
            ["SpeakNpcId"] = 100304,
            ["TalkActionId"] = {
                [1] = "100304:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100353/191F52B4",
            },
        [10035315] = {
            ["Camera"] = "43.828125,-22.387695,88.140137,0.000079,8.586326,60.000477,35.0,100000.0,false,Manual,22.0",
            ["Content"] = "不过布鲁斯不喜欢这个结局，所以自作主张把歌词改成了一个快乐的版本。他熟到能把这首歌倒着演奏，所以没录过这首……",
            ["ContentFR"] = "Blues n’aimait pas cette fin. Alors il avait réécrit les paroles, en version heureuse. Il connaissait cet air par cœur, il pouvait même le jouer à l’envers. C’est pour ça qu’il ne l’a jamais enregistré.",
            ["DialogueId"] = 10035315,
            ["FacialId"] = {
                [1] = "100304:Think01",
                },
            ["GUID"] = "191F52DE",
            ["LookAt"] = {
                [1] = "200021:n(100304)",
                [2] = "200002:n(100304)",
                [3] = "100001:n(100304)",
                },
            ["NextDialogue"] = 10035316,
            ["SpeakNpcId"] = 100304,
            ["VoiceName"] = "voice/$Locale$/story/1003/100353/191F52DE",
            },
        [10035316] = {
            ["Content"] = "你是说，你听到的就是它……？",
            ["ContentFR"] = "Tu veux dire... que c’est bien cette mélodie que tu as entendue ?",
            ["DialogueId"] = 10035316,
            ["FacialId"] = {
                [1] = "100304:None",
                },
            ["GUID"] = "191F5308",
            ["LookAt"] = {
                [1] = "100304:n(100001)",
                },
            ["NextDialogue"] = 10035317,
            ["SpeakNpcId"] = 100304,
            ["TalkActionId"] = {
                [1] = "100304:Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100353/191F5308",
            },
        [10035317] = {
            ["Camera"] = "138.671875,16.285156,67.811523,7.200567,11.981702,-152.809799,35.000008,100000.0,false,Manual,22.0",
            ["Content"] = "对，我遇袭当晚听到的就是这个旋律！",
            ["ContentFR"] = "Oui. C’est exactement celle que j’ai entendue la nuit de l’attaque.",
            ["DialogueId"] = 10035317,
            ["GUID"] = "191F5332",
            ["NextDialogue"] = 10035318,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100353/191F5332",
            },
        [10035318] = {
            ["Camera"] = "43.828125,-22.387695,88.140137,0.000081,6.1863,60.000423,35.0,100000.0,false,Manual,22.0",
            ["Content"] = "…………",
            ["ContentFR"] = "...",
            ["DialogueId"] = 10035318,
            ["FacialId"] = {
                [1] = "100304:Think01",
                },
            ["FinalCamera"] = "43.828125,-22.387695,88.140137,0.000079,8.586326,60.000477,35.0,100000.0,false,Manual,22.0",
            ["GUID"] = "191F535C",
            ["LookAt"] = {
                [1] = "100304:p(lise_50_ditou)",
                },
            ["NextDialogue"] = 10035319,
            ["SpeakNpcId"] = 100304,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/story/1003/100353/191F535C",
            },
        [10035319] = {
            ["Content"] = "虽然是新的线索，但很遗憾，这条线索指向的范围太广了。《雪国的孩子》在盖雷亚剧院已经上演了几十年，曾经是非常热门的剧，所以这里很多人都会唱。",
            ["ContentFR"] = "C’est un nouvel indice... mais malheureusement, il est trop large. <I>Né du blizzard</> a été joué au Théâtre Galéa pendant des dizaines d’années. C’était extrêmement populaire. Beaucoup d’habitants savent le fredonner.",
            ["DialogueId"] = 10035319,
            ["FacialId"] = {
                [1] = "100304:None",
                },
            ["GUID"] = "191F5386",
            ["LookAt"] = {
                [1] = "100304:n(100001)",
                },
            ["NextDialogue"] = 10035320,
            ["Scripts"] = "PlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt03/0071_lise_secret\"},RelatedRegionId{101103}}",
            ["SpeakNpcId"] = 100304,
            ["VoiceName"] = "voice/$Locale$/story/1003/100353/191F5386",
            },
        [10035320] = {
            ["Camera"] = "-47.433594,-302.833496,184.461426,0.000141,-15.616298,71.198349,25.000002,100000.0,false,Manual,22.0",
            ["Content"] = "有一次，我和布鲁斯攒了大半年的钱，好不容易才买到那场剧的门票，却在现场被冤枉成偷了别人的票，被赶了出来。",
            ["ContentFR"] = "Un jour, Blues et moi avions économisé pendant six mois pour acheter deux places. Mais une fois sur place, quelqu’un nous a accusés d’avoir volé ses billets. On a été mis dehors avant que la pièce commence.",
            ["DialogueId"] = 10035320,
            ["FacialId"] = {
                [1] = "100304:Sad01",
                },
            ["FinalCamera"] = "-43.898438,-292.427002,181.38916,0.000141,-15.616298,71.198349,25.000002,100000.0,false,Manual,22.0",
            ["GUID"] = "191F53B0",
            ["NextDialogue"] = 10035321,
            ["SpeakNpcId"] = 100304,
            ["TalkActionId"] = {
                [1] = "100304:Talk02_Start",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/story/1003/100353/191F53B0",
            },
        [10035321] = {
            ["Content"] = "那夜我靠着剧院的墙坐了很久，心情糟透了。布鲁斯却像变魔术一样掏出口琴，吹起了那首歌的旋律。原来，他自己早就练会了这首曲子……",
            ["ContentFR"] = "J’étais dévastée. Je suis restée assise des heures contre le mur du théâtre. Et là, Blues a sorti son vieil harmonica et a joué cet air. Il l’avait appris en cachette...",
            ["DialogueId"] = 10035321,
            ["GUID"] = "191F53DA",
            ["NextDialogue"] = 10035322,
            ["SpeakNpcId"] = 100304,
            ["VoiceName"] = "voice/$Locale$/story/1003/100353/191F53DA",
            },
        [10035322] = {
            ["Camera"] = "69.078125,-79.48877,262.419922,0.000194,-37.617821,73.187332,35.000008,100000.0,false,Manual,22.0",
            ["Content"] = "他吹着吹着，在墙的另一边，突然就有个男孩子跟着唱起来了。他的歌喉好动听，像云雀一样。",
            ["ContentFR"] = "Et soudain, de l’autre côté du mur, un garçon s’est mis à chanter. Sa voix... magnifique, comme une alouette.",
            ["DialogueId"] = 10035322,
            ["FinalCamera"] = "75.945312,-56.791992,244.148438,0.000194,-37.617821,73.187332,35.000008,100000.0,false,Manual,22.0",
            ["GUID"] = "191F5404",
            ["NextDialogue"] = 10035323,
            ["SpeakNpcId"] = 100304,
            ["TalkActionId"] = {
                [1] = "100304:Talk02_End",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/story/1003/100353/191F5404",
            },
        [10035323] = {
            ["Camera"] = "292.566406,182.274902,118.647949,0.000237,-2.417996,-149.207611,35.000008,100000.0,false,Manual,22.0",
            ["Content"] = "那一晚，因为有布鲁斯的口琴，还有那个陌生人的跟唱，我好开心，都快忘了自己被赶出来的事。",
            ["ContentFR"] = "Ce soir-là, grâce à Blues et à cet inconnu, j’ai presque oublié qu’on nous avait chassés.",
            ["DialogueId"] = 10035323,
            ["GUID"] = "191F542E",
            ["NextDialogue"] = 10035324,
            ["SpeakNpcId"] = 100304,
            ["VoiceName"] = "voice/$Locale$/story/1003/100353/191F542E",
            },
        [10035324] = {
            ["Camera"] = "72.292969,-58.250488,84.757324,0.000228,9.781732,71.391068,35.000008,100000.0,false,Manual,22.0",
            ["Content"] = "抱歉，不好意思，自顾自地说起来了。我的意思是，这首歌会的人太多了，无法成为指向性的证据。",
            ["ContentFR"] = "... Désolée, je me suis laissée emporter. Ce que je veux dire, c’est que cette chanson est trop répandue. Elle ne peut pas servir de preuve.",
            ["DialogueId"] = 10035324,
            ["FacialId"] = {
                [1] = "100304:None",
                },
            ["GUID"] = "191F5458",
            ["NextDialogue"] = 10035325,
            ["SpeakNpcId"] = 100304,
            ["TalkActionId"] = {
                [1] = "100304:ScratchHead_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100353/191F5458",
            },
        [10035325] = {
            ["Camera"] = "35.425781,210.5625,76.637207,0.000075,18.182783,-57.792496,35.000011,100000.0,false,Manual,22.0",
            ["Content"] = "那，这出戏近期会上演吗？没准我们可以蹲点试试。",
            ["ContentFR"] = "Alors, cette pièce sera rejouée bientôt ? On pourrait essayer de guetter au théâtre.",
            ["DialogueId"] = 10035325,
            ["FinalCamera"] = "35.425781,210.5625,76.637207,0.000069,11.982678,-57.391754,35.000011,100000.0,false,Manual,22.0",
            ["GUID"] = "191F5482",
            ["LookAt"] = {
                [1] = "200021:n(100304)",
                [2] = "200002:n(200021)",
                [3] = "100001:n(200021)",
                },
            ["NextDialogue"] = 10035326,
            ["SpeakNpcId"] = 200021,
            ["TalkActionId"] = {
                [1] = "200021:Talk03_Start",
                },
            ["ToFinalCameraBlendTime"] = 4,
            ["VoiceName"] = "voice/$Locale$/story/1003/100353/191F5482",
            },
        [10035326] = {
            ["Camera"] = "46.15625,-202.915527,167.463867,0.000052,-11.016801,66.199203,35.000011,100000.0,false,Manual,22.0",
            ["Content"] = "近期吗……我不太清楚。不过据我所知，这出剧这两年已经停演了，因为一起发生在盖雷亚剧院的<H>事故</>。",
            ["ContentFR"] = "Je ne sais pas. D’après ce que j’ai lu, l’opéra a été suspendu il y a deux ans, après un <H>incident</>.",
            ["DialogueId"] = 10035326,
            ["GUID"] = "191F54AC",
            ["LookAt"] = {
                [1] = "200021:n(100304)",
                [2] = "200002:n(100304)",
                [3] = "100001:n(100304)",
                [4] = "100304:n(200021)",
                },
            ["NextDialogue"] = 10035327,
            ["SpeakNpcId"] = 100304,
            ["TalkActionId"] = {
                [1] = "100304:ScratchHead_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100353/191F54AC",
            },
        [10035327] = {
            ["Camera"] = "109.480469,38.969727,114.763672,0.000073,-0.616664,-141.401657,35.0,100000.0,false,Manual,22.0",
            ["Content"] = "事故？",
            ["ContentFR"] = "Un incident ?",
            ["DialogueId"] = 10035327,
            ["FacialId"] = {
                [1] = "100001:Think01",
                },
            ["GUID"] = "191F54D6",
            ["LookAt"] = {
                [1] = "200021:n(100001)",
                [2] = "200002:n(100001)",
                [3] = "100001:n(100304)",
                },
            ["NextDialogue"] = 10035328,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "200021:Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100353/191F54D6",
            },
        [10035328] = {
            ["Camera"] = "-151.640625,-339.61792,161.115723,0.000086,-9.217005,58.195625,35.000008,100000.0,false,Manual,22.0",
            ["Content"] = "嗯，之前整理案卷的时候，在笔录里看到的。倒不是什么大事，只是两年前演出现场的一起斗殴。",
            ["ContentFR"] = "Oui. Je suis tombée sur le rapport en classant des dossiers. Ce n’était pas énorme, juste une bagarre lors d’une représentation.",
            ["DialogueId"] = 10035328,
            ["GUID"] = "191F5500",
            ["LookAt"] = {
                [1] = "100304:n(100001)",
                },
            ["NextDialogue"] = 10035329,
            ["SpeakNpcId"] = 100304,
            ["VoiceName"] = "voice/$Locale$/story/1003/100353/191F5500",
            },
        [10035329] = {
            ["Camera"] = "24.625,-15.047363,93.071777,0.000097,8.781772,53.395985,35.000008,100000.0,false,Manual,22.0",
            ["Content"] = "但普奇剧团长说，因为这起事故中主演受了伤，“魔笛”剧团将暂停《雪国的孩子》的后续演出。",
            ["ContentFR"] = "La directrice de la troupe, Letizia Putsch, a déclaré qu’un des acteurs principaux avait été blessé. Depuis, la troupe de la Flûte Enchantée a suspendu les représentations de <I>Né du blizzard</>.",
            ["DialogueId"] = 10035329,
            ["GUID"] = "191F552A",
            ["NextDialogue"] = 10035330,
            ["SpeakNpcId"] = 100304,
            ["VoiceName"] = "voice/$Locale$/story/1003/100353/191F552A",
            },
        [10035330] = {
            ["Content"] = "我翻翻本子——嗯，还有当时抄的笔记。",
            ["ContentFR"] = "Laisse-moi vérifier mes notes... Voilà.",
            ["DialogueId"] = 10035330,
            ["GUID"] = "191F5554",
            ["NextDialogue"] = 10035331,
            ["SpeakNpcId"] = 100304,
            ["VoiceName"] = "voice/$Locale$/story/1003/100353/191F5554",
            },
        [10035331] = {
            ["Content"] = "盖雷亚剧院斗殴事件\
\
时间：10月9日晚8:30\
\
报案人：莱蒂齐娅·普奇（“魔笛”剧团团长）\
\
参与斗殴双方：帕西法尔·斯诺菲尔德（主演）、苏珊娜·罗西（主演）……\
马修·伯纳德（观众）、菲利·弗兰西斯科（观众）……\
\
事件：疑似剧团成员与前排观众就剧目发生冲突？疑似观众殴打演员？（部分笔录内页被撕掉了）\
\
结论：证据不足，不予立案\
\
备注：《雪国的孩子》暂时停演，演出时间不定。\
很想和布鲁斯弥补一下当年看不成剧的遗憾，但似乎短时间内没有机会了。",
            ["ContentFR"] = "Affaire : Bagarre au Théâtre Galea\
Date : 9 octobre, 20 h 30\
\
Dépositaire de plainte : Letizia Putsch, directrice de la troupe de la Flûte Enchantée\
\
Parties impliquées :\
Parsifal Snowfield (comédien principal)\
Susanna Rossi (comédienne principale)\
Mathew Bernard (spectateur)\
Feeley Francisco (spectateur)\
...\
Résumé de l’incident : Une altercation aurait éclaté entre des membres de la troupe et des spectateurs du premier rang. Témoignages évoquant des coups portés aux comédiens par les spectateurs. (Certaines pages du rapport officiel ont été arrachées.)\
\
Conclusion : Preuves insuffisantes. Aucune suite judiciaire.\
\
Remarques : Les représentations de Né du blizzard sont suspendues jusqu’à nouvel ordre, sans date de reprise annoncée.\
J’aurais tant voulu voir cette pièce avec Blues, pour effacer le regret de ne pas l’avoir vue autrefois. Mais il semble que ce ne soit pas pour bientôt...",
            ["DialogueId"] = 10035331,
            ["DialoguePanelType"] = "{type:showtext;topic:READ_NAME_2000049;content:READ_TEXT_2000049}",
            ["GUID"] = "191F557E",
            ["NextDialogue"] = 10035332,
            ["VoiceName"] = "voice/$Locale$/story/1003/100353/191F557E",
            },
        [10035332] = {
            ["Camera"] = "-175.097656,-375.326904,138.394531,0.000041,-5.200041,58.387745,35.000011,100000.0,false,Manual,22.0",
            ["Content"] = "不过，除了继续调查下水道之外，眼下也只有这一条新线索了……",
            ["ContentFR"] = "À part replonger dans les égouts, c’est notre seule piste actuelle...",
            ["DialogueId"] = 10035332,
            ["FacialId"] = {
                [1] = "100304:Think01",
                },
            ["FinalCamera"] = "-159.128906,-349.168457,135.712402,0.000042,-5.000033,59.587662,35.000011,100000.0,false,Manual,22.0",
            ["GUID"] = "191F55A8",
            ["LookAt"] = {
                [1] = "200021:n(100304)",
                [2] = "200002:n(100304)",
