            },
        [10035333] = {
            ["Content"] = "你刚才提醒了我，如果《雪国的孩子》对凶手的确有特殊意义，那的确可以考虑引蛇出洞。",
            ["ContentFR"] = "Tu as raison. Si<I> Né du blizzard </>a une signification particulière pour l’agresseur, on peut peut-être l’attirer avec ça.",
            ["DialogueId"] = 10035333,
            ["FacialId"] = {
                [1] = "100304:None",
                },
            ["GUID"] = "191F55D2",
            ["LookAt"] = {
                [1] = "100304:n(100001)",
                },
            ["NextDialogue"] = 10035334,
            ["SpeakNpcId"] = 100304,
            ["TalkActionId"] = {
                [1] = "100304:Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100353/191F55D2",
            },
        [10035334] = {
            ["Content"] = "对喽。咱们去剧院问问普奇剧团长，看看她老人家能不能帮个忙，放个假消息吧。",
            ["ContentFR"] = "Exactement. Allons voir la directrice Putsch, et demandons-lui de diffuser une fausse annonce.",
            ["DialogueId"] = 10035334,
            ["GUID"] = "191F55FC",
            ["LookAt"] = {
                [1] = "200021:n(100304)",
                [2] = "200002:n(200021)",
                [3] = "100001:n(200021)",
                [4] = "100304:n(200021)",
                },
            ["NextDialogue"] = 10035335,
            ["SpeakNpcId"] = 200021,
            ["VoiceName"] = "voice/$Locale$/story/1003/100353/191F55FC",
            },
        [10035335] = {
            ["Content"] = "愚蠢。",
            ["ContentFR"] = "Stupide...",
            ["DialogueId"] = 10035335,
            ["GUID"] = "191F5626",
