        [10035401] = {
            ["Content"] = "……凶手果然还活着！",
            ["ContentFR"] = "... L’agresseur est encore en vie !",
            ["DialogueId"] = 10035401,
            ["GUID"] = "191F60FA",
            ["NextDialogue"] = 10035402,
            ["SpeakNpcId"] = 100304,
            ["VoiceName"] = "voice/$Locale$/story/1003/100354/191F60FA",
            },
        [10035402] = {
            ["Content"] = "好家伙，自己找上门来了……",
            ["ContentFR"] = "Eh ben, il vient de lui-même cette fois.",
            ["DialogueId"] = 10035402,
            ["GUID"] = "191F6124",
            ["NextDialogue"] = 10035403,
            ["SpeakNpcId"] = 200021,
            ["VoiceName"] = "voice/$Locale$/story/1003/100354/191F6124",
            },
        [10035403] = {
            ["Content"] = "“凶手”……",
            ["ContentFR"] = "« Agresseur »... ?",
            ["DialogueId"] = 10035403,
            ["GUID"] = "191F614E",
            ["NextDialogue"] = 10035404,
            ["SpeakNpcId"] = 100327,
            ["SpeakNpcName"] = "Cp2CharacterName01",
            ["VoiceName"] = "voice/$Locale$/story/1003/100354/191F614E",
            },
        [10035404] = {
            ["Content"] = "看来，直到最后，他们也，没告诉你，真相。果然十三军团，也是，一丘之貉。",
            ["ContentFR"] = "Il faut croire qu’ils ne t’ont jamais dit la vérité... Même le XIIIᵉ Légion n’est qu’une bande d’hypocrites.",
            ["DialogueId"] = 10035404,
            ["GUID"] = "191F6178",
            ["NextDialogue"] = 10035405,
            ["SpeakNpcId"] = 100327,
            ["SpeakNpcName"] = "Cp2CharacterName01",
            ["VoiceName"] = "voice/$Locale$/story/1003/100354/191F6178",
            },
        [10035405] = {
            ["Content"] = "真相？你在说什么……",
            ["ContentFR"] = "La vérité ? De quoi parlez-vous ?",
            ["DialogueId"] = 10035405,
            ["GUID"] = "191F61A2",
            ["NextDialogue"] = 10035406,
            ["SpeakNpcId"] = 100304,
            ["VoiceName"] = "voice/$Locale$/story/1003/100354/191F61A2",
            },
        [10035406] = {
            ["Content"] = "这怪物在拖延时间，先制服它！",
            ["ContentFR"] = "Il nous fait perdre du temps. Abattons-le d’abord !",
            ["DialogueId"] = 10035406,
            ["GUID"] = "191F61CC",
            ["SpeakNpcId"] = 200021,
            ["VoiceName"] = "voice/$Locale$/story/1003/100354/191F61CC",
            },
        [10035407] = {
            ["Camera"] = "-315.066406,-84.020996,106.125488,0.000016,9.398941,7.940432,30.0,100000.0,false,Manual,7.44259",
            ["Content"] = "别来无恙，姐姐。",
            ["ContentFR"] = "Cela fait longtemps... ma sœur.",
            ["DialogueId"] = 10035407,
            ["FinalCamera"] = "-309.679688,-83.179199,106.931641,0.000015,8.998944,8.140003,30.0,100000.0,false,Manual,7.44259",
