            },
        [10035801] = {
            ["Content"] = "测试开始。这次的敌人比较罕见，做好数据记录。",
            ["ContentFR"] = "Le test commence. Les cibles assignées au sujet cette fois sont rares. Assurez-vous que les données soient enregistrées avec précision.",
            ["DialogueId"] = 10035801,
            ["GUID"] = "191FA29A",
            ["NextDialogue"] = 10035802,
            ["SpeakNpcName"] = "Cp2CharacterName04",
            ["VoiceName"] = "voice/$Locale$/story/1003/100358/191FA29A",
            },
        [10035802] = {
            ["Content"] = "是，老师！",
            ["ContentFR"] = "Oui, professeur !",
            ["DialogueId"] = 10035802,
            ["GUID"] = "191FA2C4",
            ["SpeakNpcName"] = "Cp2CharacterName05",
            ["VoiceName"] = "voice/$Locale$/story/1003/100358/191FA2C4",
            },
        [10035803] = {
            ["Content"] = "虽然我们被抓了，但是敢给我们武器，那就让你们尝尝神的怒火！",
            ["ContentFR"] = "Nous sommes prisonniers, oui... mais puisque vous avez osé nous donner des armes, goûtez donc à la colère des dieux !",
            ["DialogueId"] = 10035803,
            ["GUID"] = "191FA2EE",
            ["NextDialogue"] = 10035804,
            ["SpeakNpcName"] = "Cp2CharacterName31",
            ["VoiceName"] = "voice/$Locale$/story/1003/100358/191FA2EE",
            },
        [10035804] = {
            ["Content"] = "海伯利亚人，堕落的亵渎者，竟然造出这样的怪物！杀了它！",
            ["ContentFR"] = "Hyperboréens ! Dégénérés impies ! Oser créer une pareille abomination ! Tuez ce monstre !",
            ["DialogueId"] = 10035804,
            ["GUID"] = "191FA318",
            ["SpeakNpcName"] = "Cp2CharacterName31",
            ["VoiceName"] = "voice/$Locale$/story/1003/100358/191FA318",
            },
        [10035805] = {
            ["Content"] = "放，放过我们，我们明明已经投降了啊！",
            ["ContentFR"] = "A... attendez ! Épargnez-nous ! Nous nous sommes déjà rendus !",
            ["DialogueId"] = 10035805,
            ["GUID"] = "191FA342",
            ["NextDialogue"] = 10035806,
            ["SpeakNpcName"] = "Cp2CharacterName31",
            ["VoiceName"] = "voice/$Locale$/story/1003/100358/191FA342",
            },
        [10035806] = {
            ["Content"] = "…………",
            ["ContentFR"] = "...",
            ["DialogueId"] = 10035806,
            ["GUID"] = "191FA36C",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10035807,
            ["SpeakNpcId"] = 100328,
            ["SpeakNpcName"] = "Cp2CharacterName02",
            ["VoiceName"] = "voice/$Locale$/story/1003/100358/191FA36C",
            },
        [10035807] = {
            ["Content"] = "九神啊……！请怜悯我，赐我智慧，赐我力量，赐我庇护……！",
            ["ContentFR"] = "Ô Neuf Dieux... ! Ayez pitié de moi... accordez-moi sagesse, force, délivrance... !",
            ["DialogueId"] = 10035807,
            ["GUID"] = "191FA396",
            ["NextDialogue"] = 10035808,
            ["SpeakNpcName"] = "Cp2CharacterName31",
            ["VoiceName"] = "voice/$Locale$/story/1003/100358/191FA396",
            },
        [10035808] = {
            ["Content"] = "抱歉。",
            ["ContentFR"] = "Désolé.",
            ["DialogueId"] = 10035808,
            ["GUID"] = "191FA3C0",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10035809,
            ["SpeakNpcId"] = 100331,
            ["SpeakNpcName"] = "Cp2CharacterName03",
            ["VoiceName"] = "voice/$Locale$/story/1003/100358/191FA3C0",
            },
        [10035809] = {
            ["Content"] = "啊啊……宽恕我，宽恕我……",
            ["ContentFR"] = "Ô dieux miséricordieux... accordez-moi le pardon, accordez-moi l’absolution...",
            ["DialogueId"] = 10035809,
            ["GUID"] = "191FA3EA",
            ["SpeakNpcName"] = "Cp2CharacterName31",
            ["VoiceName"] = "voice/$Locale$/story/1003/100358/191FA3EA",
            },
        [10035810] = {
            ["Content"] = "上啊，让我看看你们到底谁才是真正的恶魔，哈哈哈。",
            ["ContentFR"] = "Allez, encore ! Voyons donc lequel de vous mérite vraiment le nom de démon, hahaha !",
            ["DialogueId"] = 10035810,
            ["GUID"] = "191FA414",
            ["NextDialogue"] = 10035811,
            ["SpeakNpcName"] = "Cp2CharacterName05",
            ["VoiceName"] = "voice/$Locale$/story/1003/100358/191FA414",
            },
        [10035811] = {
            ["Content"] = "真好用，配合这段时间注射的抑制剂，稳定性也高了不少。",
            ["ContentFR"] = "Excellent. Avec les inhibiteurs injectés, la stabilité s’est nettement améliorée.",
            ["DialogueId"] = 10035811,
            ["GUID"] = "191FA43E",
            ["NextDialogue"] = 10035812,
            ["SpeakNpcName"] = "Cp2CharacterName05",
            ["VoiceName"] = "voice/$Locale$/story/1003/100358/191FA43E",
            },
        [10035812] = {
            ["Content"] = "这样下去把改造实验推广向其他军团也指日可待了。",
            ["ContentFR"] = "À ce rythme, il ne faudra guère attendre avant de généraliser ces expériences aux autres Légions.",
            ["DialogueId"] = 10035812,
            ["GUID"] = "191FA468",
            ["SpeakNpcName"] = "Cp2CharacterName04",
            ["VoiceName"] = "voice/$Locale$/story/1003/100358/191FA468",
            },
        [10035813] = {
            ["Content"] = "实验数据采集完成，你们自己回去吧，我要去给老师提交报告。",
            ["ContentFR"] = "Données complètes. Rentrez seuls, j’ai un rapport à remettre au professeur.",
            ["DialogueId"] = 10035813,
            ["GUID"] = "191FA492",
            ["SpeakNpcName"] = "Cp2CharacterName05",
            ["VoiceName"] = "voice/$Locale$/story/1003/100358/191FA492",
            },
        [10035814] = {
            ["Content"] = "各项数据都在波动范围之内，这次很有希望！",
            ["ContentFR"] = "Toutes les données restent dans la marge de tolérance. Celui-là a de vraies chances !",
            ["DialogueId"] = 10035814,
            ["GUID"] = "191F942B",
            ["SpeakNpcName"] = "Cp2CharacterName22",
            ["VoiceName"] = "voice/$Locale$/story/1003/100358/191F942B",
            },
        [10035815] = {
            ["Content"] = "怎么还是比不上36号和47号，到底哪里出了问题……",
            ["ContentFR"] = "Toujours pas au niveau des sujets 36 et 47... qu’est-ce qui cloche ?",
            ["DialogueId"] = 10035815,
            ["GUID"] = "191F942C",
            ["SpeakNpcName"] = "Cp2CharacterName22",
            ["VoiceName"] = "voice/$Locale$/story/1003/100358/191F942C",
            },
        [10035816] = {
            ["Content"] = "可以考虑加大剂量了。",
            ["ContentFR"] = "Il faudrait songer à augmenter la dose.",
            ["DialogueId"] = 10035816,
            ["GUID"] = "191F942D",
            ["SpeakNpcName"] = "Cp2CharacterName22",
            ["VoiceName"] = "voice/$Locale$/story/1003/100358/191F942D",
            },
        [10035817] = {
            ["Content"] = "还是得强化近身作战能力。",
            ["ContentFR"] = "Et renforcer ses capacités au corps-à-corps.",
            ["DialogueId"] = 10035817,
            ["GUID"] = "191F942E",
            ["SpeakNpcName"] = "Cp2CharacterName22",
            ["VoiceName"] = "voice/$Locale$/story/1003/100358/191F942E",
            },
        [10035901] = {
            ["Camera"] = "200.15918,-392.126953,346.192383,0.000001,-2.401979,-21.215986,20.000011,335.406189,false,DoNotOverride,1.2",
            ["Content"] = "（无言的白雪啊……苍穹的女儿……）",
            ["ContentFR"] = "« ... Ô neige silencieuse, fille des cieux... »",
            ["DialogueId"] = 10035901,
            ["DisableMouth"] = 1,
