            },
        [10036202] = {
            ["Camera"] = "602.476562,-249.944336,360.538574,0.000065,-25.800716,151.990204,20.0,100000.0,false,Manual,22.0",
            ["Content"] = "怎会……为什么……布鲁斯……你……",
            ["ContentFR"] = "Impossible... pourquoi Blues... pourquoi toi...",
