            },
        [10036203] = {
            ["Camera"] = "255.566406,-24.741699,131.422363,0.000058,0.598905,163.386917,35.0,100000.0,false,Manual,22.0",
            ["Content"] = "……还痛吗？",
            ["ContentFR"] = "... Tu as encore mal ?",
            ["DialogueId"] = 10036203,
            ["FacialId"] = {
                [1] = "100304:Disappoint01",
                },
            ["FinalCamera"] = "223.371094,-15.542969,131.395508,0.000058,1.398898,162.986725,35.0,100000.0,false,Manual,22.0",
