            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 100328,
            ["SpeakNpcName"] = "Cp2CharacterName06",
            ["ToFinalCameraBlendTime"] = 4,
            ["VoiceName"] = "voice/$Locale$/story/1003/100362/191FEA76",
            },
        [10036240] = {
            ["Camera"] = "419.355469,-129.479492,225.521484,-0.000548,-20.001587,145.330276,25.0,389.646332,false,Manual,2.8",
            ["Content"] = "我还有，未竟之事。",
            ["ContentFR"] = "J’ai encore... une tâche à accomplir.",
            ["DialogueId"] = 10036240,
            ["FacialId"] = {
                [1] = "100304:Unacceptable01",
                },
            ["FinalCamera"] = "413.167969,-138.438477,274.373047,-0.000549,-20.001587,145.330292,25.0,389.646332,false,Manual,2.8",
            ["GUID"] = "191FEAA0",
            ["NextDialogue"] = 10036241,
            ["SpeakNpcId"] = 100327,
            ["SpeakNpcName"] = "Cp2CharacterName06",
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/story/1003/100362/191FEAA0",
            },
        [10036241] = {
            ["Content"] = "布鲁斯！",
            ["ContentFR"] = "Blues !",
            ["DialogueId"] = 10036241,
            ["FacialId"] = {
                [1] = "100304:Shock01",
                },
            ["GUID"] = "191FEACA",
            ["NextDialogue"] = 10036242,
            ["Scripts"] = "MoveTo{ActorId{100327},TargetPoint{\"tuosi02_57_walk01\"},MoveSpeed{150},Visibility{\"Show\"}}",
            ["SpeakNpcId"] = 100304,
            ["TalkActionId"] = {
                [1] = "100304:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100362/191FEACA",
            },
        [10036242] = {
            ["Camera"] = "1270.355469,72.632324,16.277832,-0.000549,15.796513,-175.065521,35.000011,100000.0,false,Manual,22.0",
            ["Content"] = "不要跟来。",
            ["ContentFR"] = "Ne me suis pas.",
            ["DialogueId"] = 10036242,
            ["FinalCamera"] = "1270.355469,72.632324,16.277832,-0.000549,3.996487,-174.865509,35.000011,100000.0,false,Manual,22.0",
            ["GUID"] = "191FEAF4",
            ["Scripts"] = "MoveTo{ActorId{100327},TargetPoint{\"tuosi02_57_walk02\"},MoveSpeed{150},Visibility{\"Show\"}}",
            ["SpeakNpcId"] = 100327,
            ["SpeakNpcName"] = "Cp2CharacterName06",
            ["ToFinalCameraBlendTime"] = 3,
            ["VoiceName"] = "voice/$Locale$/story/1003/100362/191FEAF4",
            },
        [10036301] = {
            ["Content"] = "哇，看他看他，好酷的行头。",
            ["ContentFR"] = "Ouah, regardez-moi ça ! Trop stylé son attirail !",
            ["DialogueId"] = 10036301,
            ["Duration"] = 5,
            ["GUID"] = "191FF4A2",
            ["SpeakNpcId"] = 100366,
            ["VoiceName"] = "voice/$Locale$/story/1003/100363/191FF4A2",
            },
        [10036302] = {
            ["Content"] = "这盔甲，这头套！哪里定做的，我也想要！",
            ["ContentFR"] = "Cette armure, ce masque ! Où t’as trouvé ça ? J’en veux un aussi !",
            ["DialogueId"] = 10036302,
            ["Duration"] = 7,
            ["GUID"] = "191FF4CC",
            ["SpeakNpcId"] = 100368,
            ["VoiceName"] = "voice/$Locale$/story/1003/100363/191FF4CC",
            },
        [10036303] = {
            ["Content"] = "哈哈哈哈你看那边，还有人装扮成神弃者和秽兽呢，不要命啦。",
            ["ContentFR"] = "Hahaha ! Regardez là-bas, y’en a même qui se sont déguisés en Déchus et en Souillés ! Ils sont suicidaires ?",
            ["DialogueId"] = 10036303,
            ["Duration"] = 10,
            ["GUID"] = "191FF4F6",
            ["SpeakNpcId"] = 100367,
            ["VoiceName"] = "voice/$Locale$/story/1003/100363/191FF4F6",
            },
        [10036304] = {
            ["Content"] = "怕什么，在这里我们没有身份，没有名字，没有种族！只有狂欢，彻夜狂欢！",
            ["ContentFR"] = "Mais on s’en fout ! Ici, plus d’identité, plus de nom, plus de race ! Juste des masques, de la musique, et la fête jusqu’à l’aube !",
            ["DialogueId"] = 10036304,
            ["Duration"] = 12,
            ["GUID"] = "191FF520",
            ["SpeakNpcId"] = 100369,
            ["VoiceName"] = "voice/$Locale$/story/1003/100363/191FF520",
            },
        [10036305] = {
            ["Content"] = "（盖雷亚剧院，我回来了。）",
            ["ContentFR"] = "<I>Théâtre Galea... me revoilà.</>",
            ["DialogueId"] = 10036305,
            ["DisableMouth"] = 1,
            ["GUID"] = "191FF54A",
            ["NextDialogue"] = 10036306,
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 100327,
            ["SpeakNpcName"] = "Cp2CharacterName06",
            ["VoiceName"] = "voice/$Locale$/story/1003/100363/191FF54A",
            },
        [10036306] = {
            ["Content"] = "（只可惜是在这愚蠢的狂欢日……这群疯狂的家伙对这儿是一种玷污。）",
            ["ContentFR"] = "<I>Dommage que ce soit le jour de cette mascarade grotesque... Cette folie souille la dignité du lieu.</>",
            ["DialogueId"] = 10036306,
            ["DisableMouth"] = 1,
            ["GUID"] = "191FF574",
            ["NextDialogue"] = 10036307,
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 100327,
            ["SpeakNpcName"] = "Cp2CharacterName06",
            ["VoiceName"] = "voice/$Locale$/story/1003/100363/191FF574",
            },
        [10036307] = {
            ["Content"] = "（……现在不是思考这个的时候。去和同盟的那家伙碰面吧。）",
            ["ContentFR"] = "<I>Assez. Pas le moment de penser à ça. Je dois retrouver le contact des Déchus.</>",
            ["DialogueId"] = 10036307,
            ["DisableMouth"] = 1,
            ["GUID"] = "191FF59E",
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 100327,
            ["SpeakNpcName"] = "Cp2CharacterName06",
            ["VoiceName"] = "voice/$Locale$/story/1003/100363/191FF59E",
            },
        [10036308] = {
            ["Camera"] = "64.748032,73.186905,141.25,0.000034,-0.801086,-95.817291,35.000008,100000.0,false,Manual,22.0",
            ["Content"] = "居然叫我来这种地方，你还有这般雅兴。",
            ["ContentFR"] = "Vraiment ? Me faire venir dans un endroit pareil ? Je ne t’imaginais pas amateur de ce genre de futilités.",
            ["DialogueId"] = 10036308,
            ["FinalCamera"] = "59.996071,26.498751,140.589844,0.000034,-0.801086,-95.817314,35.000008,100000.0,false,Manual,22.0",
            ["GUID"] = "191FF5C8",
            ["NextDialogue"] = 10036309,
            ["Scripts"] = "PlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/mute\"},RelatedRegionId{101901}}",
            ["SpeakNpcId"] = 100326,
            ["SpeakNpcName"] = "Cp2CharacterName08",
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/story/1003/100363/191FF5C8",
            },
        [10036309] = {
            ["Camera"] = "47.290932,-282.748688,98.773438,0.000223,12.987468,99.416245,20.0,100000.0,false,Manual,22.0",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "我不是说过如无必要减少碰面吗？现在十三军团也撤走了，我们得尽快完成此前的约定才是。",
            ["ContentFR"] = "Et je t’avais dit de limiter les rencontres au strict nécessaire. Maintenant que la XIIIᵉ Légion s’est retirée, il faut boucler notre accord au plus vite.",
            ["DialogueId"] = 10036309,
            ["FinalCamera"] = "153.951035,-298.556122,92.078125,-2.0,9.185791,119.818588,20.0,100000.0,false,Manual,22.0",
            ["GUID"] = "191FF5F2",
            ["NextDialogue"] = 10036310,
            ["SpeakNpcId"] = 100326,
            ["SpeakNpcName"] = "Cp2CharacterName08",
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/1003/100363/191FF5F2",
            },
        [10036310] = {
            ["Camera"] = "48.10738,-52.516705,168.945312,0.00015,15.595841,97.983627,35.000008,100000.0,false,Manual,22.0",
            ["Content"] = "没错，可以完成，约定了。",
            ["ContentFR"] = "Oui. Il est temps... d’honorer notre marché.",
            ["DialogueId"] = 10036310,
            ["GUID"] = "191FF61C",
            ["NextDialogue"] = 10036311,
            ["SpeakNpcId"] = 100327,
            ["SpeakNpcName"] = "Cp2CharacterName06",
            ["VoiceName"] = "voice/$Locale$/story/1003/100363/191FF61C",
            },
        [10036311] = {
            ["Camera"] = "59.996071,26.498751,140.589844,0.000034,-0.801086,-95.817314,35.000008,100000.0,false,Manual,22.0",
            ["Content"] = "…………？！",
            ["ContentFR"] = "... ?!",
            ["DialogueId"] = 10036311,
            ["GUID"] = "191FF646",
            ["SpeakNpcId"] = 100326,
            ["SpeakNpcName"] = "Cp2CharacterName08",
            ["VoiceName"] = "voice/$Locale$/story/1003/100363/191FF646",
            },
        [10036312] = {
            ["Content"] = "你……怎么……唔……呃——！",
            ["ContentFR"] = "Tu... qu’est-ce que... urgh... aaargh !",
            ["DialogueId"] = 10036312,
            ["GUID"] = "191FF670",
            ["NextDialogue"] = 10036313,
            ["SpeakNpcId"] = 100326,
            ["SpeakNpcName"] = "Cp2CharacterName08",
            ["VoiceName"] = "voice/$Locale$/story/1003/100363/191FF670",
            },
        [10036313] = {
            ["Content"] = "协助你，借此引来，十三军团，目的，达到。",
            ["ContentFR"] = "Je n’ai... coopéré avec vous... que pour attirer... la XIIIᵉ Légion. Désormais... c’est chose faite.",
            ["DialogueId"] = 10036313,
            ["GUID"] = "191FF69A",
            ["NextDialogue"] = 10036314,
            ["SpeakNpcId"] = 100327,
            ["SpeakNpcName"] = "Cp2CharacterName06",
            ["VoiceName"] = "voice/$Locale$/story/1003/100363/191FF69A",
            },
        [10036314] = {
            ["Content"] = "但十三军团，拒绝，揭露真相。",
            ["ContentFR"] = "Mais la XIIIᵉ Légion... a refusé... de révéler la vérité.",
            ["DialogueId"] = 10036314,
            ["GUID"] = "191FF6C4",
            ["NextDialogue"] = 10036315,
            ["SpeakNpcId"] = 100327,
            ["SpeakNpcName"] = "Cp2CharacterName06",
            ["VoiceName"] = "voice/$Locale$/story/1003/100363/191FF6C4",
            },
        [10036315] = {
            ["Content"] = "那么你，就没有，利用价值。",
            ["ContentFR"] = "Alors toi... tu n’as plus... la moindre utilité.",
            ["DialogueId"] = 10036315,
            ["GUID"] = "191FF6EE",
            ["NextDialogue"] = 10036316,
            ["SpeakNpcId"] = 100327,
            ["SpeakNpcName"] = "Cp2CharacterName06",
            ["VoiceName"] = "voice/$Locale$/story/1003/100363/191FF6EE",
            },
        [10036316] = {
            ["Content"] = "神弃者，也是，祸患。",
            ["ContentFR"] = "Les Déchus... ne sont qu’un fléau... de plus à éradiquer.",
            ["DialogueId"] = 10036316,
            ["GUID"] = "191FF718",
            ["SpeakNpcId"] = 100327,
            ["SpeakNpcName"] = "Cp2CharacterName06",
            ["VoiceName"] = "voice/$Locale$/story/1003/100363/191FF718",
            },
        [10036317] = {
            ["Content"] = "酷啊！这次的演出比往年还逼真！",
            ["ContentFR"] = "Génial ! Cette année, le spectacle est encore plus réaliste !",
            ["DialogueId"] = 10036317,
            ["GUID"] = "191FF742",
            ["NextDialogue"] = 10036318,
            ["SpeakNpcName"] = "Cp2CharacterName33",
            ["VoiceName"] = "voice/$Locale$/story/1003/100363/191FF742",
            },
        [10036318] = {
            ["Content"] = "喂，怎么还有人装扮成军团士兵的模样啊？看手里那家伙，跟真的一样啊！",
            ["ContentFR"] = "Hé, regarde ! Y en a qui ont carrément choisi un costume de soldat ! Et ce matos... on dirait un vrai !",
            ["DialogueId"] = 10036318,
            ["GUID"] = "191FF76C",
            ["NextDialogue"] = 10036319,
            ["SpeakNpcName"] = "Cp2CharacterName33",
            ["VoiceName"] = "voice/$Locale$/story/1003/100363/191FF76C",
            },
        [10036319] = {
            ["Content"] = "他们是在演什么战争戏吗？打起来，打起来！",
            ["ContentFR"] = "C’est une pièce sur la guerre ou quoi ? Allez, qu’on voit un peu d’action !",
            ["DialogueId"] = 10036319,
            ["GUID"] = "191FF796",
            ["NextDialogue"] = 10036320,
            ["SpeakNpcName"] = "Cp2CharacterName33",
            ["VoiceName"] = "voice/$Locale$/story/1003/100363/191FF796",
            },
        [10036320] = {
            ["Content"] = "…………",
            ["ContentFR"] = "...",
            ["DialogueId"] = 10036320,
            ["GUID"] = "191FF7C0",
            ["NextDialogue"] = 10036321,
            ["SpeakNpcId"] = 100310,
            ["SpeakNpcName"] = "Cp2CharacterName25",
            ["VoiceName"] = "voice/$Locale$/story/1003/100363/191FF7C0",
            },
        [10036321] = {
            ["Content"] = "我*，这枪声，演得太真了吧！",
            ["ContentFR"] = "Bordel ! Tu as entendu ça ? Mec, les effets sonores sont parfaits !",
            ["DialogueId"] = 10036321,
            ["GUID"] = "191FF7EA",
            ["NextDialogue"] = 10036322,
            ["SpeakNpcName"] = "Cp2CharacterName33",
            ["VoiceName"] = "voice/$Locale$/story/1003/100363/191FF7EA",
            },
        [10036322] = {
            ["Content"] = "哥们，好样的！再来一个！",
            ["ContentFR"] = "Bien joué ! Encore !",
            ["DialogueId"] = 10036322,
            ["GUID"] = "191FF814",
            ["NextDialogue"] = 10036323,
            ["SpeakNpcName"] = "Cp2CharacterName33",
            ["VoiceName"] = "voice/$Locale$/story/1003/100363/191FF814",
            },
        [10036323] = {
            ["Content"] = "唉……",
            ["ContentFR"] = "<I>Soupir...</>",
            ["DialogueId"] = 10036323,
            ["GUID"] = "191FF83E",
            ["NextDialogue"] = 10036324,
            ["SpeakNpcId"] = 100310,
            ["SpeakNpcName"] = "Cp2CharacterName25",
            ["VoiceName"] = "voice/$Locale$/story/1003/100363/191FF83E",
            },
        [10036324] = {
            ["Content"] = "第十三军团执行公务，枪弹无眼，再不滚就死！",
            ["ContentFR"] = "La XIIIᵉ Légion est en mission officielle ! Munitions réelles. Bougez-vous, ou vous allez mourir !",
            ["DialogueId"] = 10036324,
            ["GUID"] = "191FF868",
            ["NextDialogue"] = 10036325,
            ["SpeakNpcId"] = 100310,
            ["SpeakNpcName"] = "Cp2CharacterName25",
            ["VoiceName"] = "voice/$Locale$/story/1003/100363/191FF868",
            },
        [10036325] = {
            ["Content"] = "等、等下……是真家伙？！",
            ["ContentFR"] = "A-Attendez... c’est pas du faux ?!",
            ["DialogueId"] = 10036325,
            ["GUID"] = "191FF892",
            ["NextDialogue"] = 10036326,
            ["SpeakNpcName"] = "Cp2CharacterName33",
            ["VoiceName"] = "voice/$Locale$/story/1003/100363/191FF892",
            },
        [10036326] = {
            ["Content"] = "是军团，真的军团！！",
            ["ContentFR"] = "C’est la Légion ! La vraie Légion !",
            ["DialogueId"] = 10036326,
            ["GUID"] = "191FF8BC",
            ["NextDialogue"] = 10036327,
            ["SpeakNpcName"] = "Cp2CharacterName33",
            ["VoiceName"] = "voice/$Locale$/story/1003/100363/191FF8BC",
            },
        [10036327] = {
            ["Content"] = "阿诺德、托马斯、疏散群众！",
            ["ContentFR"] = "Arnold, Thomas, évacuez les civils !",
            ["DialogueId"] = 10036327,
            ["GUID"] = "191FF8E6",
            ["NextDialogue"] = 10036328,
            ["SpeakNpcId"] = 100310,
            ["SpeakNpcName"] = "Cp2CharacterName25",
            ["VoiceName"] = "voice/$Locale$/story/1003/100363/191FF8E6",
            },
        [10036328] = {
            ["Content"] = "其他人，继续压制。",
            ["ContentFR"] = "Les autres, continuez la pression !",
            ["DialogueId"] = 10036328,
            ["GUID"] = "191FF910",
            ["SpeakNpcId"] = 100310,
            ["SpeakNpcName"] = "Cp2CharacterName25",
            ["VoiceName"] = "voice/$Locale$/story/1003/100363/191FF910",
            },
        [10036329] = {
            ["Camera"] = "121.195312,-974.079346,173.230469,-15.056557,1.40581,111.026299,20.0,348.470978,false,Manual,2.8",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "狂欢现场发现目标。初步判定为神弃者同盟“渡鸦”。在场的市民已经驱离，抓捕行动进展顺利。",
            ["ContentFR"] = "Cible repérée dans une fête. Évaluation préliminaire, il s’agit d’un \"Corvin\" des Déchus. Les civils ont été évacués. L’opération d’arrestation progresse sans encombre.",
            ["DialogueId"] = 10036329,
            ["FinalCamera"] = "160.929688,-958.805359,173.886719,-15.056557,1.40581,111.026299,20.0,100000.0,false,Manual,2.8",
            ["GUID"] = "191FF93A",
            ["NextDialogue"] = 10036330,
            ["RelatedWikiId"] = {
                [1] = 101004,
                },
            ["Scripts"] = "SEQ{\
CameraMoveTo{_delay{4},TargetPosition{\"113.824219,12.355896,129.007812,-15.085212,8.603217,125.227028,20.0,100000.0,false,Manual,22.0\"},duration{0}},   \
CameraMoveTo{_delay{0},TargetPosition{\"111.667969,10.832886,137.609375,-15.085212,8.603217,125.227028,20.0,100000.0,false,Manual,22.0\"},duration{4}}\
}",
            ["SpeakNpcId"] = 100310,
            ["ToFinalCameraBlendTime"] = 4,
            ["VoiceName"] = "voice/$Locale$/story/1003/100363/191FF93A",
            },
        [10036330] = {
            ["Camera"] = "83.970703,135.913513,189.65625,-15.112432,-9.397861,141.623428,15.0,175.398438,false,Manual,2.8",
            ["Content"] = "……好……其他人也……向盖雷亚剧院集合……",
            ["ContentFR"] = "... Bien... les autres... rejoignez... le Théâtre Galea...",
            ["DialogueId"] = 10036330,
            ["GUID"] = "191FF964",
            ["NextDialogue"] = 10036331,
            ["SnapShot"] = "TELEPHONE",
            ["SpeakNpcId"] = 200022,
            ["VoiceName"] = "voice/$Locale$/story/1003/100363/191FF964",
            },
        [10036331] = {
            ["Camera"] = "303.613281,-279.919189,8.132812,0.000071,9.59102,112.143921,25.0,668.989929,false,Manual,3.0",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "队长，我们还在尽力抢救，但这同盟的家伙快不行了！二号目标怎么办？",
            ["ContentFR"] = "Capitaine, nous faisons encore de notre mieux pour le sauver, mais le Déchu est en train de mourir ! Que faisons-nous avec la cible n° 2 ?",
            ["DialogueId"] = 10036331,
            ["FinalCamera"] = "269.648438,-293.739441,8.132812,0.000071,9.59102,112.143982,25.0,668.989929,false,Manual,3.0",
            ["GUID"] = "191FF98E",
            ["LookAt"] = {
                [1] = "100340:n(100310)",
                [2] = "100310:n(100340)",
                },
            ["NextDialogue"] = 10036332,
            ["Scripts"] = "SetLocation{ActorId{100342},TargetPoint{\"Point2\"},Visibility{\"Show\"}}",
            ["SpeakNpcId"] = 100340,
            ["ToFinalCameraBlendTime"] = 6,
            ["VoiceName"] = "voice/$Locale$/story/1003/100363/191FF98E",
            },
        [10036332] = {
            ["Camera"] = "4.361328,31.762268,100.789062,0.000065,25.399736,88.416191,35.000011,169.259979,false,Manual,2.8",
            ["Content"] = "直接击毙。",
            ["ContentFR"] = "Exécution immédiate.",
            ["DialogueId"] = 10036332,
            ["FinalCamera"] = "4.966797,64.343872,117.113281,0.00006,27.199732,89.016098,35.000011,169.259979,false,Manual,2.8",
            ["GUID"] = "191FF9B8",
            ["LookAt"] = {
                [1] = "100310:n(100310)",
                },
            ["SpeakNpcId"] = 100310,
            ["TalkActionId"] = {
                [1] = "100310:Angry01_Start",
                },
            ["ToFinalCameraBlendTime"] = 4,
            ["VoiceName"] = "voice/$Locale$/story/1003/100363/191FF9B8",
            },
        [10036333] = {
            ["DialogueId"] = 10036333,
            ["GUID"] = "191FF719",
            },
        [10036334] = {
            ["Content"] = "帅家伙，等会要跟我跳支舞吗？",
            ["ContentFR"] = "Hé, beau gosse ! Ça te dit une danse plus tard ?",
            ["DialogueId"] = 10036334,
            ["Duration"] = 5,
            ["GUID"] = "191FF521",
            ["VoiceName"] = "voice/$Locale$/story/1003/100363/191FF521",
            },
        [10036335] = {
            ["Content"] = "嘿，我这枪看着很真吧，还能打出软弹呢，厉不厉害！",
            ["ContentFR"] = "Mate mon flingue, on dirait un vrai, non ? Il tire même des balles en mousse, c'est pas cool, ça ?",
            ["DialogueId"] = 10036335,
            ["Duration"] = 8,
            ["GUID"] = "191FF522",
            ["VoiceName"] = "voice/$Locale$/story/1003/100363/191FF522",
            },
        [10036336] = {
            ["Content"] = "我，我没醉！你们看，我，我还能在地上滚个舞步呢。",
            ["ContentFR"] = "Hein, moi saoul ? Pas du tout ! Regardez, je peux encore faire un roulé-boulé !",
            ["DialogueId"] = 10036336,
            ["Duration"] = 8,
            ["GUID"] = "191FF523",
            ["VoiceName"] = "voice/$Locale$/story/1003/100363/191FF523",
            },
        [10036337] = {
            ["Content"] = "今年怎么没人打扮成水蠊了啊，我还蛮期待的。",
            ["ContentFR"] = "Eh, cette année, personne n’a osé se déguiser en punaise d’eau ? Dommage, j’attendais ça.",
            ["DialogueId"] = 10036337,
            ["Duration"] = 7,
            ["GUID"] = "191FF524",
            ["VoiceName"] = "voice/$Locale$/story/1003/100363/191FF524",
            },
        [10036338] = {
            ["Content"] = "嗷嗷嗷嗷，我是秽兽，嗷嗷嗷嗷，咬你。",
            ["ContentFR"] = "Grrrrr ! Je suis un Souillé ! Grrrrr ! Je vais te croquer !",
            ["DialogueId"] = 10036338,
            ["Duration"] = 6,
            ["GUID"] = "191FF525",
            ["VoiceName"] = "voice/$Locale$/story/1003/100363/191FF525",
            },
        [10036339] = {
            ["Content"] = "别踩我，我在扮演尸体。",
            ["ContentFR"] = "Fais attention où tu marches, je joue le cadavre.",
            ["DialogueId"] = 10036339,
            ["Duration"] = 4,
            ["GUID"] = "191FF526",
            ["VoiceName"] = "voice/$Locale$/story/1003/100363/191FF526",
            },
        [10036340] = {
            ["Content"] = "这位舞伴是我先邀请的，你什么意思，想打架是吧？",
            ["ContentFR"] = "Eh ! C’est moi qui l’ai invitée à danser ! Tu cherches la bagarre ou quoi ?",
            ["DialogueId"] = 10036340,
            ["Duration"] = 8,
            ["GUID"] = "191FF527",
            ["VoiceName"] = "voice/$Locale$/story/1003/100363/191FF527",
            },
        [10036341] = {
            ["Content"] = "剧院禁止斗殴，就算是银烛狂欢期间也不行！",
            ["ContentFR"] = "Pas de bagarre ici ! Même en pleine Fête de la Chandelle d’Argent, les règles sont les règles !",
            ["DialogueId"] = 10036341,
            ["Duration"] = 7,
            ["GUID"] = "191FF528",
            ["VoiceName"] = "voice/$Locale$/story/1003/100363/191FF528",
            },
        [10036342] = {
            ["Content"] = "好强壮的身材！能让我摸摸你的腹肌吗？",
            ["ContentFR"] = "Quelle carrure ! Je peux toucher tes abdos ?",
            ["DialogueId"] = 10036342,
            ["Duration"] = 6,
            ["GUID"] = "191FF529",
            ["VoiceName"] = "voice/$Locale$/story/1003/100363/191FF529",
            },
        [10036343] = {
            ["Content"] = "刚才的演出太精彩了，有人能帮我把这封信递给优雅的主演小姐吗？",
            ["ContentFR"] = "La représentation tout à l’heure était incroyable... Quelqu’un peut donner cette lettre à la sublime actrice principale pour moi ?",
            ["DialogueId"] = 10036343,
            ["Duration"] = 10,
            ["GUID"] = "191FF52A",
            ["VoiceName"] = "voice/$Locale$/story/1003/100363/191FF52A",
            },
        [10036344] = {
            ["Content"] = "跳得好！",
            ["ContentFR"] = "Superbe danse ! Bravo !",
            ["DialogueId"] = 10036344,
            ["Duration"] = 2,
            ["GUID"] = "191FF52B",
            ["VoiceName"] = "voice/$Locale$/story/1003/100363/191FF52B",
            },
        [10036345] = {
            ["Content"] = "我这个秽兽气球怎么样，很逼真吧。",
            ["ContentFR"] = "Matez mon ballon Souillé, on dirait un vrai, hein ?",
            ["DialogueId"] = 10036345,
            ["Duration"] = 6,
            ["GUID"] = "191FF52C",
            ["VoiceName"] = "voice/$Locale$/story/1003/100363/191FF52C",
            },
        [10036346] = {
            ["Content"] = "这才几点啊，起来继续！今晚统统都别想睡，哈哈哈哈哈哈！",
            ["ContentFR"] = "Mais il est tôt encore ! Allez, on continue ! Cette nuit, personne ne dort ! Hahahaha !",
            ["DialogueId"] = 10036346,
            ["Duration"] = 9,
            ["GUID"] = "191FF52D",
            ["VoiceName"] = "voice/$Locale$/story/1003/100363/191FF52D",
            },
        [10036401] = {
            ["Content"] = "什么人！",
            ["ContentFR"] = "Qui va là ?!",
            ["DialogueId"] = 10036401,
            ["GUID"] = "1920050A",
            ["SpeakNpcId"] = 100310,
            ["VoiceName"] = "voice/$Locale$/story/1003/100364/1920050A",
            },
        [10036402] = {
            ["Content"] = "上。",
            ["ContentFR"] = "Feu !",
            ["DialogueId"] = 10036402,
            ["GUID"] = "19200534",
            ["SpeakNpcId"] = 100310,
            },
        [10036501] = {
            ["Camera"] = "239.951172,-477.602203,105.097656,0.000085,9.599236,-122.180763,15.000005,100000.0,false,Manual,22.0",
            ["Content"] = "各位，请先住手！我们可以谈谈！",
            ["ContentFR"] = "Assez ! Baissez vos armes, nous pouvons discuter !",
            ["DialogueId"] = 10036501,
            ["FacialId"] = {
                [1] = "100001:Shock02",
                [2] = "200021:Angry01",
