            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/story/1003/100365/1920159C",
            },
        [10036503] = {
            ["Camera"] = "106.291016,-60.851074,45.765625,14.408816,17.79439,114.413322,25.0,100000.0,false,Manual,22.0",
            ["Content"] = "费西尔准尉、狩月人？你们这是在——包庇那怪物、“卡戎狩猎”的凶手？！",
            ["ContentFR"] = "Officier Fischer et les Chasseurs de Phoxène ? Vous osez protéger ce monstre ? Le meurtrier de la \"Traque aux Charons\" ?!",
            ["DialogueId"] = 10036503,
            ["FinalCamera"] = "106.291016,-60.851048,45.765625,14.408128,21.19454,114.414146,25.0,100000.0,false,Manual,22.0",
            ["GUID"] = "192015C6",
            ["LookAt"] = {
                [1] = "100304:n(100310)",
                [2] = "100001:n(100310)",
                [3] = "200021:n(100310)",
                [4] = "100327:n(100310)",
                },
            ["NextDialogue"] = 10036504,
            ["SpeakNpcId"] = 100310,
            ["TalkActionId"] = {
                [1] = "100310:Talk02_Start",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/story/1003/100365/192015C6",
            },
        [10036504] = {
            ["Camera"] = "352.181641,-1420.943481,295.125,10.817314,-10.006131,108.659332,25.0,100000.0,false,Manual,22.0",
            ["Content"] = "你们也和先前那群人一样，被愚蠢的狂欢冲烂了脑子？",
            ["ContentFR"] = "Vous aussi, comme ces fêtards décérébrés, vous avez perdu la tête ?!",
            ["DialogueId"] = 10036504,
            ["FinalCamera"] = "315.181641,-1309.563599,274.621094,10.818109,-9.806095,108.059586,25.0,100000.0,false,Manual,22.0",
            ["GUID"] = "192015F0",
            ["NextDialogue"] = 10036505,
            ["Scripts"] = "PlayAnimation{_delay{3},ActorId{100304},AnimationId{\"Explain02_Start\"},Duration{1}}",
            ["SpeakNpcId"] = 100310,
            ["TalkActionId"] = {
                [1] = "100304:Lise_Story_Protect_End",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/story/1003/100365/192015F0",
            },
        [10036505] = {
            ["Camera"] = "67.845703,-302.296021,112.21875,0.00005,11.194864,-117.729912,35.0,100000.0,false,Manual,22.0",
            ["Content"] = "……凶手的身份和动机还未确认，直接击毙无法向冰湖城的受害者交代！",
            ["ContentFR"] = "... L’identité et les motivations du coupable n’ont pas encore été confirmées. L’exécuter ici n’apportera aucune justice aux victimes de Givrelac !",
            ["DialogueId"] = 10036505,
            ["FacialId"] = {
                [1] = "100304:Doubt01",
                },
            ["FinalCamera"] = "87.982422,-255.8255,86.699219,0.000067,11.194679,-117.325897,35.000008,100000.0,false,Manual,22.0",
            ["GUID"] = "1920161A",
            ["LookAt"] = {
                [1] = "100304:n(100310)",
                [2] = "100001:n(100304)",
                [3] = "200021:n(100304)",
                [4] = "100327:n(100304)",
                },
            ["NextDialogue"] = 10036506,
            ["SpeakNpcId"] = 100304,
            ["TalkActionId"] = {
                [1] = "100304:Lise_Story_Denny_Start",
                },
            ["ToFinalCameraBlendTime"] = 0.6,
            ["VoiceName"] = "voice/$Locale$/story/1003/100365/1920161A",
            },
        [10036506] = {
            ["Camera"] = "58.804688,311.518188,10.246094,0.000066,8.195646,-99.136841,25.0,100000.0,false,Manual,22.0",
            ["Content"] = "击毙就是最好的交代，你不是应该出现在这个舞台上的演员。守好规矩，退后！",
            ["ContentFR"] = "La justice, c’est une balle dans le crâne ! Officier Fischer, tu n’as rien à faire sur cette scène. Respecte les règles. Recule !",
            ["DialogueId"] = 10036506,
            ["FinalCamera"] = "54.523438,283.006348,14.398438,0.000068,8.195646,-98.136887,20.0,100000.0,false,Manual,22.0",
            ["GUID"] = "19201644",
