}",
            ["SpeakNpcId"] = 100304,
            ["VoiceName"] = "voice/$Locale$/story/1003/100365/19201ADC",
            },
        [10036535] = {
            ["Camera"] = "49.683594,-662.985046,208.816406,0.000342,11.184892,-92.797089,25.000006,100000.0,false,Manual,22.0",
            ["Content"] = "……好吧，我答应。但姐姐也要，答应我一件事。",
            ["ContentFR"] = "... D’accord. Mais, ma sœur... promets-moi une chose, toi aussi.",
            ["DialogueId"] = 10036535,
            ["GUID"] = "19201B06",
            ["LookAt"] = {
                [1] = "100304:n(100327)",
                },
            ["NextDialogue"] = 10036536,
            ["SpeakNpcId"] = 100327,
            ["SpeakNpcName"] = "Cp2CharacterName06",
            ["TalkActionId"] = {
                [1] = "100327:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100365/19201B06",
            },
        [10036536] = {
            ["Camera"] = "4.595703,-794.21521,263.113281,0.000379,-25.013517,80.21476,25.000006,405.778778,false,Manual,6.0",
            ["Content"] = "无论发生什么，好好，活下去。",
            ["ContentFR"] = "Quoi qu’il arrive... tiens bon... et vis.",
            ["DialogueId"] = 10036536,
            ["FacialId"] = {
                [1] = "100304:None",
                },
            ["GUID"] = "19201B30",
            ["Scripts"] = "MoveTo{_delay{1},ActorId{100327},MoveSpeed{90},TargetPoint{\"tuosi_61_walk\"}}",
            ["SpeakNpcId"] = 100327,
            ["SpeakNpcName"] = "Cp2CharacterName06",
            ["VoiceName"] = "voice/$Locale$/story/1003/100365/19201B30",
            },
        [10036537] = {
            ["Camera"] = "74.642578,-746.150818,201.730469,0.000171,-10.817749,163.628052,35.000011,100000.0,false,Manual,22.0",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "袭击了，军团，等待你们的只会是，无尽的折磨，或者死亡。",
            ["ContentFR"] = "Vous avez attaqué... la Légion. Dorénavant, il ne vous attend plus qu’une torture sans fin... ou la mort.",
            ["DialogueId"] = 10036537,
            ["FacialId"] = {
                [1] = "100304:Close",
                },
