        [10036538] = {
            ["Camera"] = "186.582031,-576.712708,255.765625,0.00004,-10.219206,-124.926338,35.000008,100000.0,false,Manual,22.0",
            ["Content"] = "我也还有，愿望，没实现。所以抱歉，接下来的路，就请你一个人走了。",
            ["ContentFR"] = "J’ai encore... une chose... à faire. Désolé... mais à partir de maintenant, ce sera sans moi.",
            ["DialogueId"] = 10036538,
