        [10036539] = {
            ["Camera"] = "-84.908203,-799.53894,226.914062,0.000093,-17.818331,25.074604,35.000011,416.171539,false,Manual,4.0",
            ["Content"] = "冰湖城的，狩月人。能委托你们吗。把她……",
            ["ContentFR"] = "Chasseurs de Phoxène de Givrelac... puis-je vous confier... ma sœur ?",
            ["DialogueId"] = 10036539,
            ["GUID"] = "19201BAE",
            ["LookAt"] = {
                [1] = "100327:n(100001)",
                },
            ["NextDialogue"] = 10036540,
