        [10036577] = {
            ["Camera"] = "451.453125,-616.61145,77.289062,-6.000039,10.974379,-171.489777,25.000006,100000.0,false,Manual,22.0",
            ["Content"] = "有机会的话，我也想听你讲你的故事，<H>你自己的故事</>。所以，保重。",
