        [10036590] = {
            ["Content"] = "背叛军团的只有我一人，狩月人小队是无端卷进来的，还请长官不要为难他们。",
            ["ContentFR"] = "C’est moi qui ai trahi la Légion. Les Chasseurs de Phoxène ont simplement été impliqués sans raison, ils sont innocents. S’il vous plaît, monsieur... ne les punissez pas pour mon erreur.",
            ["DialogueId"] = 10036590,
            ["GUID"] = "19201AB3",
            ["NextDialogue"] = 10036534,
            ["SpeakNpcId"] = 100304,
            ["VoiceName"] = "voice/$Locale$/story/1003/100365/19201AB3",
            },
