            ["SpeakNpcId"] = 100328,
            ["SpeakNpcName"] = "Cp2CharacterName07",
            ["TalkActionId"] = {
                [1] = "100351:Onground02",
                [2] = "100348:Onground02",
                [3] = "100348:Onground02",
                [4] = "100349:Onground02",
                [5] = "100350:Onground02",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["TurnTo"] = {
                [1] = "100327:p(160)",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100368/192046AA",
            },
        [10036802] = {
            ["Camera"] = "-466.845703,-310.563477,241.335938,-0.000153,18.977612,-31.780825,30.000002,444.161255,false,Manual,1.2",
            ["Content"] = "黎瑟不会知道，你真正的死因。",
            ["ContentFR"] = "Rhythm... elle ne saura jamais... la vraie cause de ta mort.",
            ["DialogueId"] = 10036802,
