        [10037005] = {
            ["Camera"] = "-217.015625,-417.861572,145.90625,0.000107,0.251966,-149.747757,50.0,211.694366,false,DoNotOverride,12.0",
            ["Content"] = "怎么还在发呆？该轮到你登场了。",
            ["ContentFR"] = "À quoi tu rêves encore ? C’est ton tour d’entrer en scène.",
            ["DialogueId"] = 10037005,
            ["FinalCamera"] = "-212.519531,-425.290039,145.90625,0.000107,0.251966,-148.548309,50.0,211.694366,false,DoNotOverride,12.0",
