            ["ContentFR"] = "Je comprends.",
            ["DialogueId"] = 10037509,
            ["FacialId"] = {
                [1] = "100001:Confident01",
                },
            ["FinalCamera"] = "-18.958984,221.722656,133.278076,0.000082,-1.618529,-81.201332,45.0,350.173065,false,Manual,3.649603",
