        [10037616] = {
            ["Camera"] = "-74.585449,-334.603027,303.736328,0.000029,-30.799992,50.183781,55.000008,226.791183,false,DoNotOverride,5.297672",
            ["Content"] = "多漂亮啊，这枚象征着荣耀的勋章。多亏了它，你才能活着站在这里。",
            ["ContentFR"] = "Quelle beauté, n’est-ce pas ? Une médaille, symbole de gloire. C’est grâce à elle que tu es là aujourd’hui, debout et en vie.",
            ["DialogueId"] = 10037616,
            ["FacialId"] = {
                [1] = "100005:Smile01",
                },
            ["FinalCamera"] = "-83.352539,-327.132324,303.736328,0.000028,-30.799992,48.183453,55.000008,226.791183,false,DoNotOverride,5.297672",
            ["GUID"] = "1920CC60",
            ["NextDialogue"] = 10037617,
