        [10037619] = {
            ["Camera"] = "45.312988,-104.004883,152.789062,0.000086,-0.80237,-13.8263,40.0,226.791183,false,DoNotOverride,5.297672",
            ["Content"] = "琳恩。",
            ["ContentFR"] = "Lynn.",
            ["DialogueId"] = 10037619,
            ["FacialId"] = {
                [1] = "100005:Unhappy01",
                },
            ["FinalCamera"] = "46.97998,-97.228516,152.789062,0.000086,-0.80237,-13.8263,40.0,226.791183,false,DoNotOverride,5.297672",
            ["GUID"] = "1920CCDE",
