            },
        [10037620] = {
            ["Camera"] = "15.744629,-256.473145,148.130859,0.000105,-2.202511,65.579247,40.000011,226.791183,false,DoNotOverride,5.297672",
            ["Content"] = "我年轻的时候，也会和你有同样的想法。",
            ["ContentFR"] = "... Quand j’avais ton âge, je pensais exactement comme toi.",
            ["DialogueId"] = 10037620,
            ["FacialId"] = {
                [1] = "200022:Doubt01",
                },
            ["FinalCamera"] = "9.604492,-253.686523,148.130859,0.000105,-2.202511,64.379684,40.000011,226.791183,false,DoNotOverride,5.297672",
            ["GUID"] = "1920CD08",
