            },
        [10037626] = {
            ["Camera"] = "-287.92749,318.541992,203.541016,0.000088,-12.598714,-58.597427,35.000008,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "怎么还有！我的假期——",
            ["ContentFR"] = "Quoi, encore ?! Mais mes vacances—",
            ["DialogueId"] = 10037626,
            ["FacialId"] = {
                [1] = "100006:Shock01",
                },
