                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1003/100376/1920CE2E",
            },
        [10037628] = {
            ["Camera"] = "-826.894287,-529.407959,71.751953,0.000124,2.401009,35.401825,35.000008,938.158691,false,Manual,1.2",
            ["Content"] = "我们在二号目标的身上发现了这个——这字条皱巴巴的，上面都是一些乱七八糟啰啰嗦嗦的字。",
            ["ContentFR"] = "Sur la dépouille de la cible n° 2, on a trouvé ça, un vieux bout de papier froissé, couvert de gribouillis.",
            ["DialogueId"] = 10037628,
            ["FacialId"] = {
                [1] = "200022:Confident01",
                },
            ["FinalCamera"] = "-817.608398,-544.271484,71.751953,0.000123,2.401009,37.001122,35.000008,938.158691,false,Manual,1.2",
            ["GUID"] = "1920CE58",
            ["NextDialogue"] = 10037629,
            ["SpeakNpcId"] = 200022,
            ["TalkActionId"] = {
                [1] = "200022:Give",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1003/100376/1920CE58",
            },
        [10037629] = {
            ["Camera"] = "-136.407715,-217.994629,158.533203,0.000115,-3.999,74.389717,35.000008,938.158691,false,DoNotOverride,1.2",
            ["Content"] = "这些文绉绉的东西我也看不太懂，你研究下吧，别是还有没发现的密信什么的。",
            ["ContentFR"] = "C’est du charabia, je pige rien. À toi de voir si c’est pas un message codé.",
            ["DialogueId"] = 10037629,
            ["FacialId"] = {
                [1] = "200022:Syouganai01",
                },
            ["FinalCamera"] = "-141.900879,-216.459717,158.533203,0.000116,-3.999,72.789558,35.000008,938.158691,false,DoNotOverride,1.2",
            ["GUID"] = "1920CE82",
            ["NextDialogue"] = 10037630,
            ["SpeakNpcId"] = 200022,
            ["TalkActionId"] = {
                [1] = "200022:Talk03_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1003/100376/1920CE82",
            },
        [10037630] = {
            ["Camera"] = "-117.756836,88.672852,108.013672,0.000201,6.600804,-84.378052,35.0,938.158691,false,DoNotOverride,1.2",
            ["Content"] = "行吧，我看看……“无言的白雪啊，苍穹的女儿”……",
            ["ContentFR"] = "D’accord, je vais jeter un coup d'œil... « ... Ô neige silencieuse, fille des cieux... »",
            ["DialogueId"] = 10037630,
            ["FacialId"] = {
                [1] = "200022:Confident01",
                },
            ["FinalCamera"] = "-131.584961,87.343506,108.013672,0.000202,6.600804,-81.177704,35.0,938.158691,false,DoNotOverride,1.2",
            ["GUID"] = "1920CEAC",
            ["NextDialogue"] = 10037631,
            ["Scripts"] = "SEQ{CameraMoveTo{_delay{5},TargetPosition{\"-96.188477,-92.051025,148.0,0.000183,0.401035,-92.385239,40.000011,938.158691,false,DoNotOverride,1.2\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-93.185547,-92.176514,148.0,0.000183,0.201033,-92.385246,40.000011,938.158691,false,DoNotOverride,1.2\"},duration{5}}}",
            ["SpeakNpcId"] = 100006,
            ["TalkActionId"] = {
                [1] = "100006:Talk01_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1003/100376/1920CEAC",
            },
        [10037631] = {
            ["Camera"] = "-155.327637,225.379883,147.050781,0.000117,-3.19924,-74.194122,35.000008,938.158691,false,DoNotOverride,1.2",
            ["Content"] = "这好像是，呃，一首诗？还是什么歌的歌词？",
            ["ContentFR"] = "On dirait... une poésie ? Ou peut-être les paroles d’une vieille chanson ?",
            ["DialogueId"] = 10037631,
            ["FinalCamera"] = "-164.984863,223.086426,147.050781,0.000122,-3.19924,-71.59314,35.000008,938.158691,false,DoNotOverride,1.2",
            ["GUID"] = "1920CED6",
            ["Scripts"] = "SEQ{CameraMoveTo{_delay{5},TargetPosition{\"-737.840088,1471.36792,204.878906,0.000128,-1.998384,-68.190025,35.000008,1775.077148,false,Manual,1.527685\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-791.514893,1605.49646,209.912109,0.000128,-1.998384,-68.190025,35.000008,1775.077148,false,Manual,1.527685\"},duration{5}}}",
            ["SpeakNpcId"] = 100006,
            ["TalkActionId"] = {
                [1] = "100006:Talk01_End",
                [2] = "200022:Talk03_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1003/100376/1920CED6",
            },
        [10037701] = {
            ["Content"] = "无言的白雪啊，苍穹的女儿——",
            ["ContentFR"] = "Ô neige silencieuse, fille des cieux...",
            ["DialogueId"] = 10037701,
            ["GUID"] = "1920DA52",
            ["NextDialogue"] = 10037702,
            ["VoiceName"] = "voice/$Locale$/story/1003/100377/1920DA52",
            },
        [10037702] = {
            ["Content"] = "为那无名的孩子献上祈祷吧！",
            ["ContentFR"] = "Prie pour l’enfant sans nom.",
            ["DialogueId"] = 10037702,
            ["GUID"] = "1920DA53",
            ["NextDialogue"] = 10037703,
            },
        [10037703] = {
            ["Content"] = "他已深眠于冻土之下。",
            ["ContentFR"] = "Qui repose déjà sous le givre éternel.",
            ["DialogueId"] = 10037703,
            ["GUID"] = "1920DA54",
            ["NextDialogue"] = 10037704,
            },
        [10037704] = {
            ["Content"] = "请记得他的歌谣，他最初的模样，",
            ["ContentFR"] = "Souviens-toi de son chant, de son visage d’antan,",
            ["DialogueId"] = 10037704,
            ["GUID"] = "1920DA55",
            ["NextDialogue"] = 10037705,
            },
        [10037705] = {
            ["Content"] = "还有那颗，璀璨无垢的心脏。",
            ["ContentFR"] = "et de son cœur, éclatant et immaculé.",
            ["DialogueId"] = 10037705,
            ["GUID"] = "1920DA56",
            ["NextDialogue"] = 10037706,
            },
        [10037706] = {
            ["Content"] = "——《致无名者的安魂曲》",
            ["ContentFR"] = "<I>Requiem pour les sans-nom</>",
            ["DialogueId"] = 10037706,
            ["GUID"] = "1920DA57",
            },
        [10037801] = {
            ["Content"] = "黎瑟·费西尔，进去找到我在墙壁上留下的<H>刻痕</>，等待下一步指示。",
            ["DialogueId"] = 10037801,
            ["DialoguePanelType"] = "{type:Guide;style:Communicator}",
            ["GUID"] = "1920EABA",
            ["NextDialogue"] = 10037802,
            ["SpeakNpcId"] = 100310,
            ["VoiceName"] = "voice/$Locale$/story/1003/100378/1920EABA",
            },
        [10037802] = {
            ["Content"] = "刻痕……刻痕……",
            ["DialogueId"] = 10037802,
            ["GUID"] = "1920EAE4",
            ["NextDialogue"] = 10037803,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1003/100378/1920EAE4",
            },
        [10037803] = {
            ["Content"] = "找到了，那边墙壁上有刀划过的痕迹。",
            ["DialogueId"] = 10037803,
            ["GUID"] = "1920EB0E",
            ["NextDialogue"] = 10037804,
            ["SpeakNpcId"] = 100304,
            ["VoiceName"] = "voice/$Locale$/story/1003/100378/1920EB0E",
            },
        [10037804] = {
            ["Content"] = "在哪在哪？",
            ["DialogueId"] = 10037804,
            ["GUID"] = "1920EB38",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1003/100378/1920EB38",
            },
        [10037805] = {
            ["Content"] = "快到了，银色和平广场下方……嗯，就是前面的区域。",
            ["ContentFR"] = "On y est presque... oui, juste devant, le passage sous la Place de la Paix d’Argent.",
            ["DialogueId"] = 10037805,
            ["GUID"] = "1920EB62",
            ["NextDialogue"] = 10037806,
            ["SpeakNpcId"] = 100304,
            ["VoiceName"] = "voice/$Locale$/story/1003/100378/1920EB62",
            },
        [10037806] = {
            ["Content"] = "前面吗？可是过道都被淹了诶……对了！垃圾桶公主说过可以用<H>水阀</>！",
            ["ContentFR"] = "Devant ? Mais le couloir est complètement inondé ! ... Attends ! La Princesse des Déchets a parlé d’une <H>vanne</> !",
            ["DialogueId"] = 10037806,
            ["GUID"] = "1920EB8C",
            ["NextDialogue"] = 10037807,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1003/100378/1920EB8C",
            },
        [10037807] = {
            ["Content"] = "嗯，启动那边的<H>水阀</>排干净水再过去吧。",
            ["ContentFR"] = "En effet. Activons cette <H>vanne</> pour drainer l’eau. Nous pourrons passer après.",
            ["DialogueId"] = 10037807,
            ["GUID"] = "1920EBB6",
            ["SpeakNpcId"] = 100304,
            ["VoiceName"] = "voice/$Locale$/story/1003/100378/1920EBB6",
            },
        [10037808] = {
            ["Content"] = "有秽兽，大家小心。",
            ["ContentFR"] = "Des Souillés ! Restez vigilants !",
            ["DialogueId"] = 10037808,
            ["GUID"] = "1920EBE0",
            ["NextDialogue"] = 10037809,
            ["SpeakNpcId"] = 100304,
            ["VoiceName"] = "voice/$Locale$/story/1003/100378/1920EBE0",
            },
        [10037809] = {
            ["Content"] = "不是说帝国这些年很注重地下设施，怎么下水道随便敲一杆子，都能敲出来秽兽啊。",
            ["ContentFR"] = "N’était-ce pas censé être mieux entretenu ? Depuis des années l’Empire se vante de renforcer les infrastructures souterraines... et il suffit de taper un tuyau pour faire sortir plus de Souillés que d’eaux usées. Magnifique.",
            ["DialogueId"] = 10037809,
            ["GUID"] = "1920EC0A",
            ["NextDialogue"] = 10037810,
            ["SpeakNpcId"] = 200021,
            ["VoiceName"] = "voice/$Locale$/story/1003/100378/1920EC0A",
            },
        [10037810] = {
            ["Content"] = "抱歉……任务结束后我一定加强下水道的巡逻工作……",
            ["ContentFR"] = "Désolée... Je renforcerai la surveillance des égouts une fois la mission terminée...",
            ["DialogueId"] = 10037810,
            ["GUID"] = "1920EC34",
            ["NextDialogue"] = 10037811,
            ["SpeakNpcId"] = 100304,
            ["VoiceName"] = "voice/$Locale$/story/1003/100378/1920EC34",
            },
        [10037811] = {
            ["Content"] = "唉，我不是说你——算了算了，先赶紧解决它们吧。",
            ["ContentFR"] = "Je ne parlais pas de vous— ... oubliez ça. Occupons-nous d’eux.",
            ["DialogueId"] = 10037811,
            ["GUID"] = "1920EC5E",
            ["SpeakNpcId"] = 200021,
            ["VoiceName"] = "voice/$Locale$/story/1003/100378/1920EC5E",
            },
        [10037812] = {
            ["Content"] = "呼，好了。那边还有另一个水阀。",
            ["ContentFR"] = "Voilà. Il reste encore une vanne, là-bas.",
            ["DialogueId"] = 10037812,
            ["GUID"] = "1920EC88",
            ["SpeakNpcId"] = 100304,
            ["VoiceName"] = "voice/$Locale$/story/1003/100378/1920EC88",
            },
        [10037813] = {
            ["Content"] = "好了，现在可以进去了。",
            ["ContentFR"] = "C’est bon, on peut avancer.",
            ["DialogueId"] = 10037813,
            ["GUID"] = "1920ECB2",
            ["SpeakNpcId"] = 100304,
            ["VoiceName"] = "voice/$Locale$/story/1003/100378/1920ECB2",
            },
        [10037995] = {
            ["Content"] = "无论他们让我们做什么，都别忘了，我们，不是怪物。",
            ["ContentFR"] = "Peu importe ce qu’ils exigent de nous... n’oublie jamais : nous ne sommes pas des monstres.",
            ["DialogueId"] = 10037995,
            ["GUID"] = "19210B11",
            ["SpeakNpcId"] = 100328,
            ["VoiceName"] = "voice/$Locale$/story/1003/100379/19210B11",
            },
        [10037996] = {
            ["Content"] = "克莱夫在城门外停车场附近，去那里找他吧。",
            ["ContentFR"] = "Clive traîne souvent près du Quai du Vent-Murmure. Allez le trouver là-bas.",
            ["DialogueId"] = 10037996,
            ["GUID"] = "19210B10",
            ["SpeakNpcId"] = 200022,
            ["VoiceName"] = "voice/$Locale$/story/1003/100379/19210B10",
            },
        [10037997] = {
            ["Content"] = "纸笔我来拜托医生帮忙，印章就麻烦你们去取一趟了。抱歉……这身伤还是拖累大家了。",
            ["ContentFR"] = "Je demanderai au docteur de s’occuper du papier et de l’encre. Quant au sceau, je compte sur vous pour aller le récupérer. Désolée... cette blessure finit vraiment par vous ralentir.",
            ["DialogueId"] = 10037997,
            ["GUID"] = "19210B0G",
            ["SpeakNpcId"] = 100304,
            ["VoiceName"] = "voice/$Locale$/story/1003/100379/19210B0G",
            },
