        [10038001] = {
            ["Content"] = "长官们……当心……",
            ["ContentFR"] = "Officiers... faites attention...",
            ["DialogueId"] = 10038001,
            ["GUID"] = "191DEA43",
            ["NextDialogue"] = 10038002,
            ["SpeakNpcId"] = 100322,
            ["VoiceName"] = "voice/$Locale$/story/1003/100380/191DEA43",
            },
        [10038002] = {
            ["Content"] = "小宝贝们又来了，真是一会儿也不得闲。",
            ["ContentFR"] = "Encore eux... Pas une minute de répit avec ces saletés.",
            ["DialogueId"] = 10038002,
            ["GUID"] = "191DEA44",
            ["SpeakNpcId"] = 200021,
            ["VoiceName"] = "voice/$Locale$/story/1003/100380/191DEA44",
            },
        [10038004] = {
            ["Content"] = "好，下一个。",
            ["ContentFR"] = "Bien, à la suivante.",
            ["DialogueId"] = 10038004,
            ["GUID"] = "191DEA46",
            ["SpeakNpcId"] = 100304,
            ["VoiceName"] = "voice/$Locale$/story/1003/100380/191DEA46",
            },
        [10038006] = {
            ["Content"] = "好……好难转……我累啦，小仆从，接下来你加油……",
            ["ContentFR"] = "Pff, elle est coincée cette fichue vanne... Je suis épuisée... À toi de jouer, petit larbin, je te laisse le soin de prouver ta force...",
            ["DialogueId"] = 10038006,
            ["GUID"] = "191DEA48",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1003/100380/191DEA48",
            },
        [10038007] = {
            ["Content"] = "看样子是最后一个了。",
            ["ContentFR"] = "Ça doit être la dernière.",
            ["DialogueId"] = 10038007,
            ["GUID"] = "191DEA49",
            ["NextDialogue"] = 10038008,
            ["SpeakNpcId"] = 100304,
            ["VoiceName"] = "voice/$Locale$/story/1003/100380/191DEA49",
            },
        }
  end },
  { MinKey = 10038008, MaxKey = 10101813, Loader = function()
      return {
        [10038008] = {
            ["Content"] = "好耶……终于要搞定啦！",
            ["ContentFR"] = "Hourra... Enfin !",
            ["DialogueId"] = 10038008,
            ["GUID"] = "191DEA4A",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1003/100380/191DEA4A",
            },
        [10038009] = {
            ["Content"] = "控制台恢复运转了，用它停下防御机关吧。",
            ["ContentFR"] = "Le panneau est de nouveau opérationnel. Utilisons-le pour couper le système de défense.",
            ["DialogueId"] = 10038009,
            ["GUID"] = "191DEA4B",
            ["SpeakNpcId"] = 100304,
            ["VoiceName"] = "voice/$Locale$/story/1003/100380/191DEA4B",
            },
        [10038012] = {
            ["Content"] = "迈尔斯，再给我拿两个弹匣过来！喂，听得见吗！啧……通讯器又出问题了？",
            ["DialogueId"] = 10038012,
            ["GUID"] = "191EF0C3",
            ["NextDialogue"] = 10038013,
            ["SpeakNpcId"] = 100340,
            ["VoiceName"] = "voice/$Locale$/story/1003/100380/191EF0C3",
            },
        [10038013] = {
            ["Content"] = "嗯？是你们啊。",
            ["DialogueId"] = 10038013,
            ["GUID"] = "191EF0C4",
            ["NextDialogue"] = 10038014,
            ["SpeakNpcId"] = 100340,
            ["TurnTo"] = {
                [1] = "100341:n(0)",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100380/191EF0C4",
            },
        [10038014] = {
            ["Content"] = "你们的行动地点不是在前面吗？快去吧，这次行动决不允许有任何闪失。",
            ["DialogueId"] = 10038014,
            ["GUID"] = "191EF0C5",
            ["NextDialogue"] = 10038015,
            ["SpeakNpcId"] = 100340,
            ["VoiceName"] = "voice/$Locale$/story/1003/100380/191EF0C5",
            },
        [10038015] = {
            ["Content"] = "收到。",
            ["DialogueId"] = 10038015,
            ["GUID"] = "191EF0C6",
            ["SpeakNpcId"] = 100304,
            ["VoiceName"] = "voice/$Locale$/story/1003/100380/191EF0C6",
            },
        [10038101] = {
            ["Content"] = "冰湖城宵禁期间，此处禁止通行",
            ["ContentFR"] = "Pendant le couvre-feu de Givrelac, la circulation est strictement interdite dans cette zone.",
            ["DialogueId"] = 10038101,
            ["GUID"] = "19210B0D",
            },
        [10038102] = {
            ["Content"] = "下水道防御机关也启动了，能帮点忙。",
            ["ContentFR"] = "Le système de défense des égouts s’est enclenché. Il devrait nous prêter main forte.",
            ["DialogueId"] = 10038102,
            ["GUID"] = "191DE875",
            ["NextDialogue"] = 10038103,
            ["SpeakNpcId"] = 100304,
            ["VoiceName"] = "voice/$Locale$/story/1003/100381/191DE875",
            },
        [10038103] = {
            ["Content"] = "为什么下水道这种地方会有防御机关啊！",
            ["ContentFR"] = "Il y a un système de défense dans un endroit comme celui-ci ?!",
            ["DialogueId"] = 10038103,
            ["GUID"] = "191DE876",
            ["NextDialogue"] = 10038104,
            ["SpeakNpcId"] = 200021,
            ["VoiceName"] = "voice/$Locale$/story/1003/100381/191DE876",
            },
        [10038104] = {
            ["Content"] = "下水道很多设备都是工程炼金院添置的，他们只说别多问。",
            ["ContentFR"] = "Beaucoup d’équipements ont été installés par les Éolipyliens. Ils nous ont simplement dit de ne pas poser de questions.",
            ["DialogueId"] = 10038104,
            ["GUID"] = "191DE877",
            ["NextDialogue"] = 10038105,
            ["SpeakNpcId"] = 100304,
            ["VoiceName"] = "voice/$Locale$/story/1003/100381/191DE877",
            },
        [10038105] = {
            ["Content"] = "下水道里放军事设施……他们到底有什么打算啊……",
            ["ContentFR"] = "Ils installent du matériel militaire dans les égouts... qu’est-ce qu’ils mijotent encore...",
            ["DialogueId"] = 10038105,
            ["GUID"] = "191DE878",
            ["SpeakNpcId"] = 200021,
            ["VoiceName"] = "voice/$Locale$/story/1003/100381/191DE878",
            },
        [10038201] = {
            ["DialogueId"] = 10038201,
            ["DialoguePanelType"] = "None",
            ["Duration"] = 1,
            ["GUID"] = "19210B0E",
            ["NextOptions"] = {
                [1] = 10038202,
                },
