        [10038202] = {
            ["Content"] = "进入军团医院",
            ["ContentFR"] = "Entrée de l’Hôpital de la Légion",
            ["DialogueId"] = 10038202,
            ["GUID"] = "19210B0F",
            },
        [10038301] = {
            ["Camera"] = "-352.324951,420.12915,199.878906,0.000157,-10.802886,-58.593517,35.000008,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "哎呀，这不是听说你伤得不轻，特地来慰问一下嘛。",
            ["ContentFR"] = "Allons, allons... J’ai juste entendu dire que tu avais été salement amochée, alors je viens gentiment prendre de tes nouvelles.",
            ["DialogueId"] = 10038301,
            ["FinalCamera"] = "-377.254883,404.907959,199.878906,0.000155,-10.602905,-55.19278,35.000008,100000.0,false,DoNotOverride,22.0",
            ["GUID"] = "1920CA15",
