        [10100211] = {
            ["Camera"] = "321.105469,367.106934,155.726562,0.001201,-4.999698,-131.971817,50.0,560.205811,false,Manual,3.0",
            ["Content"] = "那你们知道一个叫西比尔的女人吗？其他人叫她“军团长”，她应该就在这个国家……我想去找她。",
            ["ContentFR"] = "Alors vous connaissez... Une femme, qui s’appelle Sibylle. Certains l’appellent « Commandante ». Elle doit se trouver dans ce pays... Je dois la retrouver.",
            ["DialogueId"] = 10100211,
            ["ExStoryInfo"] = "Player",
            ["FacialId"] = {
                [1] = "100001:None",
                },
            ["GUID"] = "1948E9B4",
