            },
        [10100302] = {
            ["Content"] = "没什么，已经不痛了。",
            ["ContentFR"] = "Ça va. Je ne sens déjà plus la douleur.",
            ["DialogueId"] = 10100302,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "1948F8CC",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
