            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101003/1948F8CC",
            },
        [10100303] = {
            ["Content"] = "你是不是遇到了很倒霉的事……不过不用怕！",
            ["ContentFR"] = "T’as dû vivre un sacré cauchemar... Mais pas d’inquiétude !",
            ["DialogueId"] = 10100303,
            ["GUID"] = "1948F8F6",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10100304,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101003/1948F8F6",
            },
        [10100304] = {
            ["Content"] = "现在有我罩着你啦！毕竟白可是——",
            ["ContentFR"] = "Désormais, Snow te protège ! Moi, la grandiose, l’unique, la radieuse Snow, je suis—",
            ["DialogueId"] = 10100304,
