        [10100604] = {
            ["Camera"] = "-203.636719,184.543945,111.635254,0.001264,1.499944,-37.499977,40.0,435.0,false,Manual,5.0",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "听不见吗，一只眼的？跑那么快，是想赶着去治安署坐坐？",
