        [10100807] = {
            ["Camera"] = "-41.894531,-35.158691,105.682129,0.001197,-6.101988,37.254318,35.000008,182.792282,false,Manual,4.0",
            ["Content"] = "没错！就在昨天这个月黑风高的夜晚，有只一身白光的恶魔，潜入了卡米拉的酒馆，威胁她——",
            ["ContentFR"] = "Exact ! Hier soir, sous un ciel noir et venteux, un spectre drapé de lumière blanche a fait irruption dans la taverne de Camilla et l’a menacée—",
            ["DialogueId"] = 10100807,
            ["FacialId"] = {
                [1] = "200002:Happy01",
                [2] = "100001:Doubt01",
                },
            ["GUID"] = "19494BA6",
