        [10100811] = {
            ["Camera"] = "-196.237305,-18.549316,146.658691,0.001187,-2.999962,0.843019,35.000008,264.133331,false,Manual,6.0",
            ["Content"] = "他裹得严严实实，神秘得很——你也不知道？",
            ["ContentFR"] = "Non, il était emmitouflé de la tête aux pieds. Très mystérieux. Tu ne le connais pas non plus ?",
            ["DialogueId"] = 10100811,
            ["GUID"] = "19494C4E",
