            ["NextDialogue"] = 101008062,
            ["Scripts"] = "PARA{\
StopNormalSound{EventKey{\"talk_engine_roaring\"}},\
PlayAnimation{_delay{4.5},ActorId{100001},AnimationId{\"Think_End\"},Duration{1}}\
}",
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Think_Start",
                [2] = "200002:Confident_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1002/101008/19494E46",
            },
        [10100824] = {
            ["Camera"] = "-312.145508,-248.166504,147.804199,0.00115,-6.100185,35.0606,35.000008,524.896545,false,Manual,4.0",
            ["Content"] = "到此为止吧。我出去这么久，水仙平原怕不是又多了好些乱子。",
            ["ContentFR"] = "Bon, ça suffit. Je suis partie trop longtemps, et les Asphodèles doivent déjà être en proie à de nouveaux troubles.",
            ["DialogueId"] = 10100824,
            ["FacialId"] = {
                [1] = "200003:Uninterested01",
                },
            ["FinalCamera"] = "-316.333984,-242.202637,147.804199,0.00115,-6.100219,35.060589,35.000008,512.693665,false,Manual,4.0",
            ["GUID"] = "19494E70",
            ["LookAt"] = {
                [1] = "200003:n(200003)",
                [2] = "200002:n(200003)",
                [3] = "100001:n(200003)",
                },
            ["NextDialogue"] = 10100825,
            ["SpeakNpcId"] = 200003,
            ["ToFinalCameraBlendTime"] = 8,
            ["TurnTo"] = {
                [1] = "200003:p(200)",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101008/19494E70",
            },
        [10100825] = {
            ["Content"] = "…………",
            ["ContentFR"] = "...",
            ["DialogueId"] = 10100825,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "19494E9A",
            ["NextDialogue"] = 10100826,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101008/19494E9A",
            },
        [10100826] = {
            ["Camera"] = "243.654297,-17.984863,184.813477,0.00001,-12.0,-177.54332,40.0,144.905365,false,Manual,5.0",
            ["CameraBlendCurve"] = "easeInQuad",
            ["Content"] = "想办法自己活下去吧。",
            ["ContentFR"] = "Débrouille-toi pour survivre par tes propres moyens.",
            ["DialogueId"] = 10100826,
            ["FinalCamera"] = "243.705078,-18.997559,184.813477,0.00001,-12.0,-177.54332,40.0,144.905365,false,Manual,5.0",
            ["GUID"] = "19494EC4",
            ["NextDialogue"] = 10100827,
            ["SpeakNpcId"] = 200003,
            ["ToFinalCameraBlendTime"] = 4,
            ["VoiceName"] = "voice/$Locale$/story/1002/101008/19494EC4",
            },
        [10100827] = {
            ["Camera"] = "243.705078,-18.997559,184.813477,0.00001,-12.0,-177.54332,40.0,144.905365,false,Manual,5.0",
            ["CameraBlendCurve"] = "easeInQuad",
            ["Content"] = "如果这都做不到，就再也别提什么管西比尔要东西之类的疯话。",
            ["ContentFR"] = "Si tu n’en es même pas capable, alors oublie ces folies de réclamer quoi que ce soit à Sibylle.",
            ["DialogueId"] = 10100827,
            ["FacialId"] = {
                [1] = "200003:None",
                },
            ["FinalCamera"] = "243.705078,-18.997559,184.813477,0.00001,-12.0,-177.54332,40.0,322.049652,false,Manual,4.0",
            ["GUID"] = "19494EEE",
            ["NextDialogue"] = 10100828,
            ["Scripts"] = "PlayAnimation{_delay{2.3},ActorId{200003},AnimationId{\"Disagree\"},Duration{1}}",
            ["SpeakNpcId"] = 200003,
            ["ToFinalCameraBlendTime"] = 2,
            ["VoiceName"] = "voice/$Locale$/story/1002/101008/19494EEE",
            },
        [10100828] = {
            ["Camera"] = "9226.649414,237.270508,2393.015137,0.001301,-4.701137,91.655624,12.0,100000.0,false,DoNotOverride,2.8",
            ["CameraBlendCurve"] = "easeInQuad",
            ["Content"] = "……北边最高处有一间叫“修普诺斯之家”的旅馆，也许愿意收留你这种来路不明的人借宿。",
            ["ContentFR"] = "... Au nord, il y a une auberge qu’on appelle la Maison d’Hypnos. Peut-être accepteront-ils d’héberger quelqu’un avec un passé aussi flou que le tien.",
            ["DialogueId"] = 10100828,
            ["FinalCamera"] = "9226.649414,237.270508,2683.057129,0.001305,-1.701017,91.455482,13.5,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "19494F18",
            ["LookAt"] = {
                [1] = "200002:n(200003)",
                },
            ["NextDialogue"] = 10100829,
            ["SpeakNpcId"] = 200003,
            ["ToFinalCameraBlendTime"] = 12,
            ["VoiceName"] = "voice/$Locale$/story/1002/101008/19494F18",
            },
        [10100829] = {
            ["Camera"] = "-48.555664,-40.226562,104.655273,0.001197,-6.101961,37.254295,35.000008,176.661667,false,Manual,4.0",
            ["Content"] = "你是说——那幢阴森森的“鬼宅”？",
            ["ContentFR"] = "Tu veux dire... ce vieux \"manoir hanté\" ?",
            ["DialogueId"] = 10100829,
            ["FacialId"] = {
                [1] = "200002:Unacceptable01",
                },
            ["GUID"] = "19494F42",
            ["NextDialogue"] = 10100830,
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{200002},AnimationId{\"Shock_Start\"},Duration{1.7}},\
PlayAnimation{ActorId{200002},AnimationId{\"Shock_End\"},Duration{0.5}},\
PlayAnimation{ActorId{200002},AnimationId{\"Talk01_Start\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101008/19494F42",
            },
        [10100830] = {
            ["Camera"] = "549.845703,44.259766,152.453613,0.00125,-3.698793,-176.199417,50.0,661.213013,false,Manual,8.0",
            ["Content"] = "除了那栋连士兵都懒得搜查嫌晦气的宅子，还有哪儿能收留一个没有通行证的卡戎之民？",
            ["ContentFR"] = "À part cet endroit si mal famé que même les soldats s’abstiennent d’y fouiller, qui accepterait d’accueillir un Charon sans permis de circulation ?",
            ["DialogueId"] = 10100830,
            ["GUID"] = "19494F6C",
            ["NextDialogue"] = 10100831,
            ["SpeakNpcId"] = 200003,
            ["TalkActionId"] = {
                [1] = "200002:Talk01_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101008/19494F6C",
            },
        [10100831] = {
            ["Camera"] = "549.845703,44.259766,152.453613,0.00125,-3.698793,-176.199417,50.0,661.213013,false,Manual,8.0",
            ["Content"] = "我知道了，谢谢。",
            ["ContentFR"] = "Je comprends, merci.",
            ["DialogueId"] = 10100831,
            ["ExStoryInfo"] = "Player",
            ["FinalCamera"] = "425.745117,36.01416,155.745605,0.001252,-3.698793,-176.199371,85.0,529.144958,false,Manual,8.0",
            ["GUID"] = "19494F96",
            ["LookAt"] = {
                [1] = "200002:n(200003)",
                },
            ["NextDialogue"] = 10100832,
            ["Scripts"] = "MoveTo{_delay{1.5},ActorId{200003},TargetPoint{\"P101008Kami\"},MoveSpeed{60}}",
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:AgreeHead",
                },
            ["ToFinalCameraBlendTime"] = 16,
            ["VoiceName"] = "voice/$Locale$/story/1002/101008/19494F96",
            },
        [10100832] = {
            ["Camera"] = "-216.379883,-128.320312,189.390137,0.00122,-17.30224,36.452347,50.0,370.186615,false,Manual,4.0",
            ["Content"] = "……嗯……好吧！看你一个人可怜兮兮的，就让我来带你去那个修普诺斯之家一探究竟！",
            ["ContentFR"] = "Bon... Très bien ! Puisque tu as l’air {性别:tout seul et perdu|toute seule et perdue}, je vais t’y emmener, à cette Maison d’Hypnos !",
            ["DialogueId"] = 10100832,
            ["FacialId"] = {
                [1] = "200002:Unhappy02",
                },
            ["FinalCamera"] = "-230.984375,-107.061035,189.390137,0.001221,-17.30224,32.253994,50.0,351.443298,false,Manual,6.0",
            ["GUID"] = "19494FC0",
            ["LookAt"] = {
                [1] = "100001:n(200002)",
                },
            ["Scripts"] = "SEQ{\
PARA{\
LookAt{LookAtDescription{\"200002:n(100001)\"}},\
PlayAnimation{_delay{0.2},ActorId{200002},AnimationId{\"Sigh_Start\"},Duration{2.1}}\
},\
PlayAnimation{ActorId{200002},AnimationId{\"Sigh_End\"},Duration{0.4}},\
PlayAnimation{ActorId{200002},AnimationId{\"Think_Start\"},Duration{1.3}},\
PlayAnimation{ActorId{200002},AnimationId{\"Confident_Start\"},Duration{3.6}},\
PlayAnimation{ActorId{200002},AnimationId{\"SpecialConfident_Start\"},Duration{2.5}},\
PlayAnimation{ActorId{200002},AnimationId{\"Explain01_Start\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 200002,
            ["ToFinalCameraBlendTime"] = 15,
            ["VoiceName"] = "voice/$Locale$/story/1002/101008/19494FC0",
            },
        [10100901] = {
            ["Content"] = "你刚才说的“鬼宅”，是什么意思？",
            ["ContentFR"] = "Ce \"manoir hanté\" dont tu parlais, qu’est-ce que c’est au juste ?",
            ["DialogueId"] = 10100901,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "19495B12",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10100902,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101009/19495B12",
            },
        [10100902] = {
            ["Content"] = "是水仙平原的客人说的，时不时就会有人抱怨——",
            ["ContentFR"] = "C’est ce que disent les clients des Asphodèles. On entend toujours les mêmes histoires...",
            ["DialogueId"] = 10100902,
            ["GUID"] = "19495B3C",
            ["GuideFacialId"] = "Confident",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10100903,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101009/19495B3C",
            },
        [10100903] = {
            ["Content"] = "比如说明明那么大的旅馆，但是门每天都关得紧紧的，所有去投宿的外乡旅客都被赶走……",
            ["ContentFR"] = "C’est une auberge immense, mais les portes restent fermées jour et nuit, et les voyageurs de passage sont toujours refoulés.",
            ["DialogueId"] = 10100903,
            ["GUID"] = "19495B66",
            ["GuideFacialId"] = "Sad",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10100904,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101009/19495B66",
            },
        [10100904] = {
            ["Content"] = "比如说旅馆的住客从不出门，里面还偶尔会飘出奇奇怪怪、说不上来的味道……",
            ["ContentFR"] = "Les pensionnaires n’en sortent jamais et parfois, une odeur étrange, difficile à décrire, s’en dégage...",
            ["DialogueId"] = 10100904,
            ["GUID"] = "19495B90",
            ["GuideFacialId"] = "Sad",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10100905,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101009/19495B90",
            },
        [10100905] = {
            ["Content"] = "比如说那个店主的脸比泪湖的水还要冰，好像他开的不是旅馆，是棺材店！",
            ["ContentFR"] = "Ou encore, la mine de l’aubergiste est plus glaciale que les eaux du Lac du Deuil, on dirait qu’il tient une boutique de cercueils plutôt qu’une auberge !",
            ["DialogueId"] = 10100905,
            ["GUID"] = "19495BBA",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10100906,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101009/19495BBA",
            },
        [10100906] = {
            ["Content"] = "听起来也算不上太坏。我还以为里面塞满了秽兽和西比尔。",
            ["ContentFR"] = "Ça n’a pas l’air si terrible. Je croyais qu’elle grouillait de Souillés et de Sibylles.",
            ["DialogueId"] = 10100906,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "19495BE4",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10100907,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101009/19495BE4",
            },
        [10100907] = {
            ["Content"] = "但是，既然他们不接待外乡人，那我恐怕也……",
            ["ContentFR"] = "Mais, puisqu’ils n’accueillent pas les étrangers, je crains de ne pas pouvoir...",
            ["DialogueId"] = 10100907,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "19495C0E",
            ["GuideFacialId"] = "Sad",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10100908,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101009/19495C0E",
            },
        [10100908] = {
            ["Content"] = "不过，看起来卡米拉·斯卡雷特女士在这里颇有些声望。嗯……或许可以借一下她的名头。",
            ["ContentFR"] = "Enfin, il semble que Madame Camilla Scarlet jouisse d’une certaine réputation, ici. Peut-être que je pourrais m’en servir...",
            ["DialogueId"] = 10100908,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "19495C38",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10100909,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101009/19495C38",
            },
        [10100909] = {
            ["Content"] = "不用不用，白的名头借给你用就好了。从今以后你就是我关照的人了，小仆从！",
            ["ContentFR"] = "Pas besoin, pas besoin ! Tu peux dire que tu es avec Snow. Dès aujourd’hui, tu es sous ma protection, mon petit larbin !",
            ["DialogueId"] = 10100909,
            ["GUID"] = "19495C62",
            ["GuideFacialId"] = "Confident",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10100910,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101009/19495C62",
            },
        [10100910] = {
            ["Content"] = "谢谢你，但是，“仆从”是什么？",
            ["ContentFR"] = "Merci, mais... « larbin », c’est quoi ?",
            ["DialogueId"] = 10100910,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "19495C8C",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10100911,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101009/19495C8C",
            },
        [10100911] = {
            ["Content"] = "是流行小说中受魔王大人眷顾的跟班！",
            ["ContentFR"] = "C’est le mot qu’on utilise dans les romans, pour désigner l’acolyte favori du grand Roi Démon !",
            ["DialogueId"] = 10100911,
            ["GUID"] = "19495CB6",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10100912,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101009/19495CB6",
            },
        [10100912] = {
            ["Content"] = "世界上有那么多皎皎之民，为什么偏偏是白长了角呢？显然我命中注定会成为魔王大人！",
            ["ContentFR"] = "Il y a tant de Luno dans le monde... Pourquoi crois-tu que seule Snow a hérité de ces magnifiques cornes ? C’est bien la preuve que je suis destinée à devenir un Roi Démon !",
            ["DialogueId"] = 10100912,
            ["GUID"] = "19495CE0",
            ["GuideFacialId"] = "Confident",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10100913,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101009/19495CE0",
            },
        [10100913] = {
            ["Content"] = "而我是听到了神秘声音的指引找到了你，所以你一定是上天安排给我的仆从！",
            ["ContentFR"] = "Et puis, ce sont ces mystérieuses voix qui m’ont guidée jusqu’à toi. Donc tu es forcément le larbin que le destin m’a envoyé !",
            ["DialogueId"] = 10100913,
            ["GUID"] = "19495D0A",
            ["GuideFacialId"] = "Confident",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10100914,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101009/19495D0A",
            },
        [10100914] = {
            ["Content"] = "所以所以，我决定了——要以我的智慧，指引你走上正确的道路！",
            ["ContentFR"] = "Aaaalors voilà ! J’ai pris ma décision : grâce à ma grande sagesse, je vais te guider sur la bonne voie !",
            ["DialogueId"] = 10100914,
            ["GUID"] = "19495D34",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10100915,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101009/19495D34",
            },
        [10100915] = {
            ["Content"] = "…………",
            ["ContentFR"] = "...",
            ["DialogueId"] = 10100915,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "19495D5E",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10100916,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101009/19495D5E",
            },
        [10100916] = {
            ["Content"] = "（“<H>皎皎之民</>大多对人抱有亲近感”……书本没有骗我。）",
            ["ContentFR"] = "<I>« Les Lunariens sont généralement proches des humains »... Finalement, les livres disaient vrai.</>",
            ["DialogueId"] = 10100916,
            ["DisableMouth"] = 1,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "19495D88",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10100917,
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101009/19495D88",
            },
        [10100917] = {
            ["Content"] = "那间旅馆就在北边！不要发呆啦，快~跟~上！",
            ["ContentFR"] = "L’auberge est juste au nord ! Ne reste pas planté là, viens, suiiis-mooi !",
            ["DialogueId"] = 10100917,
            ["GUID"] = "19495DB2",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10100918,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101009/19495DB2",
            },
        [10100918] = {
            ["Content"] = "（……就、就是这位似乎有点亲近过头了。）",
            ["ContentFR"] = "<I>... Celle-ci est peut-être un peu trop proche.</>",
            ["DialogueId"] = 10100918,
            ["DisableMouth"] = 1,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "19495DDC",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101009/19495DDC",
            },
        [10101001] = {
            ["Content"] = "到啦！站在这儿等着！",
            ["ContentFR"] = "On y est ! Attends-moi là !",
            ["DialogueId"] = 10101001,
            ["GUID"] = "19496B7A",
            ["GuideFacialId"] = "Confident",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101010/19496B7A",
            },
        [10101100] = {
            ["DialogueId"] = 10101100,
            ["Duration"] = 2,
            ["GUID"] = "19497BB8",
            ["VoiceName"] = "voice/$Locale$/story/1002/101011/19497BB8",
            },
        [10101101] = {
            ["Content"] = "谁？",
            ["ContentFR"] = "Qui ?",
            ["DialogueId"] = 10101101,
            ["Duration"] = 1.3,
            ["GUID"] = "19497BE2",
            ["SpeakNpcId"] = 200005,
            ["SpeakNpcName"] = "UI_Npc_Name_Man_14",
            ["VoiceName"] = "voice/$Locale$/story/1002/101011/19497BE2",
            },
        [10101102] = {
            ["Content"] = "嗯，咳！我乃纯白的救赎☆光之魔王大人。听好了，这个人……",
