            ["VoiceName"] = "voice/$Locale$/story/1002/101014/1949ADC2",
            },
        [10101406] = {
            ["Content"] = "您要是一直这样，对谁都冷冰冰的，宅子就真的卖不掉啦。",
            ["ContentFR"] = "Si vous continuez à être aussi froid avec tout le monde, vous ne trouverez jamais d’acheteur pour cet endroit.",
