        [10101501] = {
            ["Content"] = "那座宅子就在南边，跟我走吧！",
            ["ContentFR"] = "La maison est juste au sud, viens avec moi !",
            ["DialogueId"] = 10101501,
            ["GUID"] = "1949BD82",
            ["GuideFacialId"] = "Smile",
