        [10101602] = {
            ["Camera"] = "-104.615982,62.744629,161.785751,0.001225,-15.299227,-48.170513,20.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "好诶！",
            ["ContentFR"] = "Trop bien !",
            ["DialogueId"] = 10101602,
            ["FacialId"] = {
                [1] = "100001:Satisfy01",
                [2] = "200002:Smile02",
                },
            ["GUID"] = "1949CE14",
            ["LookAt"] = {
