                [1] = "200002:Confident_Start",
                [2] = "200006:Explain01_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101016/1949CE14",
            },
        [10101603] = {
            ["Camera"] = "9.080318,-196.48999,134.954025,0.001162,-2.098801,82.004311,35.000008,182.297424,false,Manual,1.993266",
            ["Content"] = "你不要生气，其实恩里克叔叔并没有那么贪财。只是我们最近实在拮据，不然他也不会打算卖掉老宅补贴家用。",
            ["ContentFR"] = "Ne le prends pas mal, en réalité Monsieur Henrik n’est pas si avide d’argent. C’est juste que nous avons eu beaucoup de soucis ces derniers temps... Sinon, il n’aurait jamais pensé à vendre le vieux manoir pour joindre les deux bouts.",
            ["DialogueId"] = 10101603,
            ["FacialId"] = {
                [1] = "200002:Smile01",
                },
            ["FinalCamera"] = "9.080318,-196.48999,134.954025,0.001162,-0.498747,82.004166,35.000008,182.297424,false,Manual,1.993266",
            ["GUID"] = "1949CE3E",
            ["LookAt"] = {
