                },
            ["NextDialogue"] = 10101604,
            ["Scripts"] = "SEQ{\
PlayAnimation{_delay{3.2},ActorId{200006},AnimationId{\"DisagreeHead\"},Duration{2.2}},\
PlayAnimation{ActorId{200006},AnimationId{\"Explain01_Start\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 200006,
            ["SpeakNpcName"] = "UI_Npc_Name_Woman_5",
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/1002/101016/1949CE3E",
            },
        [10101604] = {
            ["Camera"] = "514.823242,883.764648,19.116735,0.001284,15.399822,113.199203,20.000008,100000.0,false,DoNotOverride,2.8",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "这里虽然荒废了几年，但打扫完之后还不错，至少能挡住外面的寒风，对吧！",
            ["ContentFR"] = "Il est resté à l’abandon quelques années, mais après un bon coup de balai, ça va encore. Au moins, Il te protégera du froid !",
            ["DialogueId"] = 10101604,
            ["FacialId"] = {
                [1] = "200006:Smile01",
                },
            ["FinalCamera"] = "514.823242,883.764648,19.116735,0.001299,21.399582,117.397598,20.000008,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "1949CE68",
            ["LookAt"] = {
                [1] = "200006:n(200002)",
                },
            ["NextDialogue"] = 10101605,
            ["SpeakNpcId"] = 200006,
            ["SpeakNpcName"] = "UI_Npc_Name_Woman_5",
            ["TalkActionId"] = {
                [1] = "200006:Explain01_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1002/101016/1949CE68",
            },
        [10101605] = {
            ["Camera"] = "-2.861805,-359.476807,84.442955,0.001134,6.300248,88.226242,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "哦对了，还没告诉你们我的名字。我叫赛琪，是“修普诺斯之家”的住客，有时也会帮忙打打下手。",
            ["ContentFR"] = "Oh, j’ai oublié de me présenter. Je m’appelle Psyche. Je vis à la Maison d’Hypnos, et j’aide parfois Monsieur Henrik dans ses tâches.",
            ["DialogueId"] = 10101605,
            ["FacialId"] = {
                [1] = "100001:Smile01",
                },
            ["GUID"] = "1949CE92",
            ["NextOptions"] = {
                [1] = 101016051,
                },
            ["RelatedWikiId"] = {
                [1] = 201007,
                },
