            ["VoiceName"] = "voice/$Locale$/story/1002/101016/1949CEBC",
            },
        [10101607] = {
            ["Camera"] = "1.366581,-117.323242,128.956024,0.001123,6.301252,86.81572,30.0,246.598358,false,DoNotOverride,6.0",
            ["Content"] = "叔叔说你不是本地人，那你是从哪儿来的？你的装扮，我也没怎么见过。",
            ["ContentFR"] = "Monsieur Henrik a dit que tu n’es pas d’ici. Alors, d’où viens-tu ? Et tes vêtements... je n’en ai jamais vu de pareils.",
            ["DialogueId"] = 10101607,
            ["FacialId"] = {
                [1] = "200006:Smile01",
                },
            ["FinalCamera"] = "-3.820999,-117.098145,128.956009,0.001121,6.301252,83.615379,30.0,246.598358,false,DoNotOverride,6.0",
            ["GUID"] = "1949CEE6",
            ["NextDialogue"] = 10101608,
            ["Scripts"] = "SEQ{\
