            ["VoiceName"] = "voice/$Locale$/story/1002/101016/1949CEE6",
            },
        [10101608] = {
            ["Camera"] = "-119.057526,53.523438,152.974731,0.001128,-7.099667,-35.000065,35.0,216.15033,false,Manual,4.0",
            ["CameraBlendCurve"] = "easeInQuad",
            ["Content"] = "一座小岛，在很远很远的南方。",
            ["ContentFR"] = "D’une petite île, très loin au sud.",
            ["DialogueId"] = 10101608,
            ["ExStoryInfo"] = "Player",
            ["FacialId"] = {
                [1] = "100001:Smile02",
                },
            ["FinalCamera"] = "-142.615875,70.019287,156.556641,0.001128,-7.099694,-35.000011,35.0,235.859222,false,Manual,6.0",
            ["GUID"] = "1949CF10",
            ["NextDialogue"] = 10101609,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Explain02_Start",
                },
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/1002/101016/1949CF10",
            },
        [10101609] = {
            ["Camera"] = "-501.263092,171.315674,65.855347,0.001166,3.698513,-26.395926,35.0,608.684143,false,Manual,2.494663",
            ["Content"] = "南方——我知道的，是有四季，有春天的地方！还有小岛，你一定也见过“大海”。听说它比一百片泪湖连起来还……",
            ["ContentFR"] = "Le sud... je vois ! L’endroit où il y a toutes les saisons, même le printemps ! Et une île... alors tu as sûrement vu l’océan. On raconte qu’il est plus vaste qu’une centaine de Lacs du Deuil réunis...",
            ["DialogueId"] = 10101609,
            ["FacialId"] = {
                [1] = "200006:Happy01",
                },
            ["FinalCamera"] = "-503.960846,165.880859,65.855438,0.001167,3.698513,-23.395102,35.0,608.684143,false,Manual,2.494663",
