        [10101611] = {
            ["Camera"] = "-104.615982,62.744629,161.785751,0.001222,-16.499994,-51.000015,20.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "才、才不是我！皎皎之民才没你们这么脆弱，动不动就饿肚子。",
            ["ContentFR"] = "M... même pas ! Le peuple Luno n’est pas aussi fragile que vous, on n’a pas le ventre vide pour si peu !",
            ["DialogueId"] = 10101611,
            ["FacialId"] = {
                [1] = "200002:Unacceptable01",
                },
