            },
        [10101612] = {
            ["Camera"] = "19.240356,-248.929688,148.129822,0.001204,-4.699122,90.242226,35.000008,232.110077,false,Manual,6.0",
            ["Content"] = "……你们饿了吗？那我去帮你找点吃的，稍等一会儿！",
            ["ContentFR"] = "... Vous avez faim ? Attendez un peu, je vais vous chercher de quoi manger !",
            ["DialogueId"] = 10101612,
            ["FacialId"] = {
