            ["NextDialogue"] = 10102108,
            ["SpeakNpcId"] = 200008,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1002/101021/194A20EE",
            },
        [10102108] = {
            ["Camera"] = "-119.224854,-52.406082,82.172852,0.000047,14.206512,-47.991478,45.857548,255.974915,false,Manual,2.325034",
            ["Content"] = "哎，要不你学几声狗叫，给咱们听听？",
            ["ContentFR"] = "Hé, et si tu nous aboyais un coup, pour voir ?",
            ["DialogueId"] = 10102108,
            ["GUID"] = "194A2118",
            ["SpeakNpcId"] = 200010,
            ["VoiceName"] = "voice/$Locale$/story/1002/101021/194A2118",
            },
        [10102201] = {
            ["Content"] = "不，不行……",
            ["ContentFR"] = "Non... tu ne peux pas.",
            ["DialogueId"] = 10102201,
            ["Duration"] = 2,
            ["GUID"] = "194A305A",
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101022/194A305A",
            },
        [10102202] = {
            ["Content"] = "嗯？看什么看，小崽子。",
            ["ContentFR"] = "Hein ? Qu’est-ce que tu fixes, {性别:morveux|morveuse} ?",
            ["DialogueId"] = 10102202,
            ["Duration"] = 1.5,
            ["GUID"] = "194A3084",
            ["SpeakNpcName"] = "UI_Npc_Name_Man_5",
            ["VoiceName"] = "voice/$Locale$/story/1002/101022/194A3084",
            },
        [10102203] = {
            ["Content"] = "你不会给我惹什么麻烦的——对吧？",
            ["ContentFR"] = "Tu ne m’attireras pas de problèmes... pas vrai ?",
            ["DialogueId"] = 10102203,
            ["Duration"] = 4,
            ["GUID"] = "194A30AE",
            ["SpeakNpcId"] = 200003,
            ["VoiceName"] = "voice/$Locale$/story/1002/101022/194A30AE",
            },
        [10102204] = {
            ["Content"] = "父、父亲……",
            ["ContentFR"] = "P... Père !",
            ["DialogueId"] = 10102204,
            ["Duration"] = 1.8,
            ["GUID"] = "194A3102",
            ["SpeakNpcName"] = "UI_Npc_Name_Man_13",
            ["VoiceName"] = "voice/$Locale$/story/1002/101022/194A3102",
            },
        [10102205] = {
            ["Content"] = "你们这群混蛋！",
            ["ContentFR"] = "Bande d’ordures !",
            ["DialogueId"] = 10102205,
            ["Duration"] = 1.5,
            ["GUID"] = "194A312C",
            ["SpeakNpcName"] = "UI_Npc_Name_Man_13",
            ["VoiceName"] = "voice/$Locale$/story/1002/101022/194A312C",
            },
        [10102206] = {
            ["Content"] = "你想干什么？！",
            ["ContentFR"] = "Qu’est-ce que tu crois faire ?!",
            ["DialogueId"] = 10102206,
            ["Duration"] = 1,
            ["GUID"] = "194A3156",
            ["SpeakNpcName"] = "UI_Npc_Name_Man_5",
            ["VoiceName"] = "voice/$Locale$/story/1002/101022/194A3156",
            },
        [10102401] = {
            ["Content"] = "……快走。",
            ["ContentFR"] = "... Vite, allons-nous-en.",
            ["DialogueId"] = 10102401,
            ["GUID"] = "194A40C2",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 10102402,
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101023/194A40C2",
