        [10102501] = {
            ["Camera"] = "-237.39502,-776.429688,380.287109,0.000219,-20.598696,70.000015,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "……然后，他趁我没防备袭击了我，抢走了刚到手的钱。狗东西，连卖废品的都不放过！那可是给贫民窟几家子筹措的生活费！",
            ["ContentFR"] = "Et puis, il m’a prise par surprise et m’a piqué l’argent que je venais de gagner. Cet imbécile, il ne laisse même pas les récupérateurs tranquilles ! Cet argent était pour plusieurs familles des taudis !",
            ["DialogueId"] = 10102501,
            ["FacialId"] = {
                [1] = "200011:Angry01",
                },
            ["FinalCamera"] = "-264.857361,-766.555664,380.287109,0.000222,-20.598696,70.000008,35.000008,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "194A6192",
            ["NextDialogue"] = 10102502,
            ["Scripts"] = "PARA{\
PlayAnimation{_delay{3},ActorId{200011},AnimationId{\"Angry01_Start\"},Duration{2}}\
}",
            ["SpeakNpcId"] = 200011,
            ["SpeakNpcName"] = "UI_Npc_Name_NervouseMaer",
            ["TalkActionId"] = {
                [1] = "200011:Explain02_End",
                },
            ["ToFinalCameraBlendTime"] = 6,
            ["VoiceName"] = "voice/$Locale$/story/1002/101025/194A6192",
            },
        [10102502] = {
            ["Camera"] = "78.0,-7.4375,131.521484,0.000191,-2.398646,-161.013702,35.000008,175.980392,false,Manual,4.0",
            ["Content"] = "没了那袋子铜币，那群老老少少下个月都要喝西北风了。唉，小贼不知道跑哪儿去了，我得找个人帮我一起堵他。",
            ["ContentFR"] = "Sans ce sac de pièces, tous, jeunes et vieux, devront se serrer la ceinture le mois prochain. Je ne sais pas où ce voleur a filé... Il me faut quelqu’un pour m’aider à le coincer.",
            ["DialogueId"] = 10102502,
            ["FacialId"] = {
                [1] = "200011:Sad01",
                },
            ["GUID"] = "194A61BC",
            ["LookAt"] = {
                [1] = "200003:n(200011)",
                },
            ["NextDialogue"] = 10102503,
            ["Scripts"] = "PlayAnimation{_delay{3},ActorId{200011},AnimationId{\"Sigh_Start\"},Duration{2}}",
            ["SpeakNpcId"] = 200011,
            ["SpeakNpcName"] = "UI_Npc_Name_NervouseMaer",
            ["TalkActionId"] = {
                [1] = "200011:Angry01_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101025/194A61BC",
            },
        [10102503] = {
            ["Camera"] = "-197.983643,-228.263672,131.707031,0.000195,0.20134,50.188034,50.0,454.857483,false,Manual,5.0",
            ["Content"] = "这是治安署分内的事吧？",
            ["ContentFR"] = "Ce n’est pas plutôt le travail du Bureau de la Sécurité ?",
            ["DialogueId"] = 10102503,
            ["FacialId"] = {
                [1] = "200003:Uninterested01",
                },
            ["GUID"] = "194A61E6",
            ["LookAt"] = {
                [1] = "200003:n(200003)",
                },
            ["NextDialogue"] = 10102504,
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{200003},AnimationId{\"SpecialUnInterested_Start\"},Duration{2}}\
}",
            ["SpeakNpcId"] = 200003,
            ["VoiceName"] = "voice/$Locale$/story/1002/101025/194A61E6",
            },
        [10102504] = {
            ["Camera"] = "281.375,129.460938,170.882812,0.000218,-5.998777,-154.617096,62.0,422.431763,false,Manual,5.0",
            ["Content"] = "哎呀等治安署腾出手来管咱们卡戎的事，泪湖的冰都要化干净啦！",
            ["ContentFR"] = "Ah, d’ici que le Bureau de la Sécurité se préoccupe de nous, pauvres Charons, la glace du Lac du Deuil aura déjà fondu !",
            ["DialogueId"] = 10102504,
            ["FacialId"] = {
                [1] = "200011:Unacceptable01",
                },
            ["GUID"] = "194A6210",
            ["LookAt"] = {
                [1] = "200011:n(200003)",
                },
            ["NextDialogue"] = 10102505,
            ["SpeakNpcId"] = 200011,
            ["SpeakNpcName"] = "UI_Npc_Name_NervouseMaer",
            ["TalkActionId"] = {
                [1] = "200011:Sigh_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101025/194A6210",
            },
        [10102505] = {
            ["Camera"] = "-298.685974,-953.163086,100.919922,0.000218,0.201115,68.990013,50.0,1215.570923,false,Manual,6.0",
            ["Content"] = "我说最最善良美丽的卡米拉大姐，能不能麻烦您这里的狩月人帮个小忙……嗯，就一个小忙！我知道您人最好了。",
            ["ContentFR"] = "Je vous en supplie, la plus gentille et belle Camilla... pourriez-vous demander à quelques Chasseurs de Phoxène de nous donner un petit coup de main... juste un tout petit coup de main ! Je sais que vous êtes la meilleure.",
            ["DialogueId"] = 10102505,
            ["FacialId"] = {
                [1] = "200011:Unacceptable01",
                },
            ["FinalCamera"] = "-302.263062,-951.791992,100.919922,0.000218,0.201115,68.990013,50.0,1215.570923,false,Manual,6.0",
            ["GUID"] = "194A623A",
            ["NextDialogue"] = 10102506,
            ["SpeakNpcId"] = 200011,
            ["SpeakNpcName"] = "UI_Npc_Name_NervouseMaer",
            ["TalkActionId"] = {
                [1] = "200011:Explain02_Start",
                [2] = "200003:SpecialUnInterested_End",
                },
            ["ToFinalCameraBlendTime"] = 6,
            ["VoiceName"] = "voice/$Locale$/story/1002/101025/194A623A",
            },
        [10102506] = {
            ["Camera"] = "10.047852,-140.40625,117.429688,0.000236,8.800841,67.194237,56.354355,240.957672,false,Manual,6.0",
            ["Content"] = "别撒娇。你应该知道，在这里讨要的东西，从来都不是免费的。",
            ["ContentFR"] = "Arrête de faire la charmeuse. Tu sais très bien que rien ici ne se fait gratuitement.",
            ["DialogueId"] = 10102506,
            ["GUID"] = "194A6264",
            ["NextDialogue"] = 10102507,
            ["SpeakNpcId"] = 200003,
            ["TalkActionId"] = {
                [1] = "200003:Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101025/194A6264",
            },
        [10102507] = {
            ["Camera"] = "81.471924,-18.664062,159.626953,0.000213,-10.598773,-163.809616,48.734837,175.980392,false,Manual,4.0",
            ["Content"] = "那能不能稍微……那个，便宜点……或者用其他的东西交换也可以！我想想，那句话怎么说来着——",
            ["ContentFR"] = "Alors… pourriez-vous au moins… proposer un petit arrangement… ou accepter un autre échange ? Attendez, comment disait-on déjà...",
            ["DialogueId"] = 10102507,
            ["GUID"] = "194A628E",
            ["NextDialogue"] = 10102508,
            ["Scripts"] = "PARA{\
PlayAnimation{_delay{1},ActorId{200011},AnimationId{\"SpecialHoldHelmet_Start\"},Duration{1}},\
PlayAnimation{_delay{4},ActorId{200011},AnimationId{\"SpecialHoldHelmet_End\"},Duration{1}},\
PlayAnimation{_delay{5.5},ActorId{200011},AnimationId{\"Think_Start\"},Duration{2}}\
}",
            ["SpeakNpcId"] = 200011,
            ["SpeakNpcName"] = "UI_Npc_Name_NervouseMaer",
            ["TalkActionId"] = {
                [1] = "200011:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101025/194A628E",
            },
        [10102508] = {
            ["Camera"] = "-200.542847,-222.323242,136.585938,0.000182,1.001258,46.588379,70.000015,435.191498,false,Manual,6.0",
            ["Content"] = "“情报就是金钱”！对对对，全冰湖城的垃圾桶都归我管，如果我以后翻到什么好玩的消息，第一时间告诉您，可以吧？",
            ["ContentFR"] = "« L’information, c’est de l’or » ! Oui c’est ça, je gère tous les poubelles de Givrelac, alors si je tombe sur des infos intéressantes, vous serez la première à les savoir, d’accord ?",
            ["DialogueId"] = 10102508,
            ["FacialId"] = {
                [1] = "200003:Smile01",
                },
            ["GUID"] = "194A62B8",
            ["Scripts"] = "PARA{\
PlayAnimation{_delay{4},ActorId{200011},AnimationId{\"Give\"},Duration{2}},\
LookAt{_delay{7},LookAtDescription{\"200003:p(P10102508Kami)\"}}\
}",
            ["SpeakNpcId"] = 200011,
            ["SpeakNpcName"] = "UI_Npc_Name_NervouseMaer",
            ["TalkActionId"] = {
                [1] = "200011:Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101025/194A62B8",
            },
        [10102601] = {
            ["Camera"] = "-383.403992,-193.522461,142.960938,0.00126,-1.698579,31.40027,50.0,551.857117,false,DoNotOverride,4.0",
            ["CameraBlendCurve"] = "easeOutQuad",
            ["Content"] = "是你。还有你是那个……弗莱伊家的女儿？是叫……赛琪吧？",
            ["ContentFR"] = "C’est toi. Et toi, tu es... la fille des Frey ? Psyche, c’est bien ça ?",
