            },
        [10102609] = {
            ["Camera"] = "291.657104,98.844727,170.599609,0.001316,-5.498842,-164.352921,52.422081,496.264801,false,Manual,4.0",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "丑话说在前头，这不是小孩子玩闹，更不是什么轻松活计。这里是不问来历、不问出身，但你得到的每一枚回报，都伴随着相应的危险。",
            ["ContentFR"] = "Pour être claire, ce n’est pas un jeu d’enfants, et ce n’est pas facile non plus. Ici, personne ne demandera ton passé ni tes origines, mais chaque récompense a son risque.",
            ["DialogueId"] = 10102609,
            ["FacialId"] = {
                [1] = "200011:Unhappy01",
                },
            ["FinalCamera"] = "231.961548,82.132812,164.626953,0.001316,-5.498842,-164.352844,52.422081,430.432526,false,Manual,4.0",
            ["GUID"] = "194A734A",
            ["LookAt"] = {
                [1] = "200011:n(200003)",
                [2] = "200006:n(200003)",
