        [10103214] = {
            ["Camera"] = "-73.458984,66.246094,173.626251,0.000079,-9.200067,-16.192541,43.073463,212.641296,false,DoNotOverride,10.0",
            ["Content"] = "好好好，我记住了……",
            ["ContentFR"] = "Je... Je m’en souviendrai...",
            ["DialogueId"] = 10103214,
