            },
        [10103215] = {
            ["Content"] = "卡米拉女士？你跟到这儿，是来帮我们的？",
            ["ContentFR"] = "Madame Camilla ? Vous êtes venue exprès pour nous aider ?",
            ["DialogueId"] = 10103215,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "194AD507",
            ["LookAt"] = {
                [1] = "200011:n(200003)",
                [2] = "\
200003:n(200061)",
                },
            ["NextDialogue"] = 10103216,
            ["SpeakNpcId"] = 200061,
            ["TalkActionId"] = {
                [1] = "200061:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101032/194AD507",
            },
        [10103216] = {
            ["Camera"] = "161.710938,-228.921875,139.269562,0.000084,-0.599397,96.330261,40.000023,212.641296,false,DoNotOverride,10.0",
            ["Content"] = "你那么大老远来了冰湖城，要是第一天就在这种臭烘烘的地方闹出个三长两短，未免过于凄惨。",
            ["ContentFR"] = "Tu as traversé la moitié du monde pour venir à Givrelac. Si tu devais finir dès ton premier jour dans ce trou à rats, ce serait un peu pathétique, non ?",
            ["DialogueId"] = 10103216,
            ["FacialId"] = {
                [1] = "200011:None",
                },
            ["GUID"] = "194AD566",
            ["NextDialogue"] = 10103217,
            ["Scripts"] = "SetLocation{ActorId{200002},TargetPoint{\"101032Bai3\"},Visibility{\"Show\"}}",
            ["SpeakNpcId"] = 200003,
            ["TalkActionId"] = {
                [1] = "200061:Explain02_End",
                [2] = "200003:Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101032/194AD566",
            },
        [10103217] = {
            ["Camera"] = "-224.279297,-53.761719,138.360504,0.000002,-6.599731,-7.001203,20.000008,396.617218,false,DoNotOverride,5.0",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "嘁，我当是哪个人模狗样的，原来是开酒馆的大婶。你又能拿老子怎么样？叫士兵来抓？你不会真以为那些老爷会管卡戎的破事——",
            ["ContentFR"] = "Tss, et moi qui croyais que c’était quelqu’un d’important... juste la vieille tenancière de taverne. Tu crois faire quoi ? Appeler la garde ? Tu penses vraiment que les hauts placés se soucient d’un foutu Charon—",
            ["DialogueId"] = 10103217,
            ["FacialId"] = {
                [1] = "200011:Unhappy02",
                },
            ["FinalCamera"] = "-289.886719,-45.707031,146.008194,-0.0,-6.599731,-7.001234,20.000011,115.779877,false,DoNotOverride,5.0",
            ["GUID"] = "194AD567",
