        [10103502] = {
            ["Camera"] = "-135.308594,-179.244141,147.530365,0.000016,-7.258025,49.643944,35.000008,1.5,false,Disable,1.2",
            ["Content"] = "那个小偷也是，突然就吓得浑身哆嗦，原来治安署是这么恐怖的地方吗！",
            ["ContentFR"] = "Et ce voleur aussi, il tremblait de partout d’un coup. Le Bureau de la Sécurité, c’est si effrayant que ça ?",
            ["DialogueId"] = 10103502,
            ["FacialId"] = {
                [1] = "200002:Shock01",
                },
            ["GUID"] = "194AF570",
            ["NextDialogue"] = 10103503,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Shock_Start",
                [2] = "200011:Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101034/194AF570",
            },
        [10103503] = {
            ["Camera"] = "-37.669922,74.164062,136.618378,0.000016,-4.258083,-78.357025,35.000011,1.5,false,Disable,1.2",
            ["Content"] = "看来他应该会被好好教训一番了。唉，我本来只是想追回钱袋，再敲他几下脑壳就行，没想闹那么大的……",
            ["ContentFR"] = "On dirait qu’il va prendre cher, en tout cas. Moi, je voulais juste récupérer mon argent et lui asséner deux-trois coups, pas déclencher tout ça...",
            ["DialogueId"] = 10103503,
            ["FacialId"] = {
                [1] = "200011:Unhappy01",
                },
            ["GUID"] = "194AF571",
            ["NextDialogue"] = 10103504,
            ["SpeakNpcId"] = 200011,
            ["TalkActionId"] = {
                [1] = "200002:Shock_End",
                [2] = "200011:SpecialHoldHelmet_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101034/194AF571",
            },
        [10103504] = {
            ["Camera"] = "-165.324219,313.250977,140.767822,0.000018,-4.657957,-60.556728,41.027447,1.5,false,Disable,1.2",
            ["Content"] = "啊，差点忘了，报酬报酬！给你！",
            ["ContentFR"] = "Ah, j’allais oublier, ta récompense ! Tiens !",
            ["DialogueId"] = 10103504,
            ["FacialId"] = {
                [1] = "200011:Smile01",
                },
            ["GUID"] = "194AF572",
            ["NextDialogue"] = 10103505,
            ["Scripts"] = "PlayAnimation{_delay{2},ActorId{200011},AnimationId{\"Give\"},Duration{1}}",
            ["SpeakNpcId"] = 200011,
            ["TalkActionId"] = {
                [1] = "200011:SpecialHoldHelmet_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101034/194AF572",
            },
        [10103505] = {
            ["Content"] = "嘿嘿，真是谢谢你啦，我的大恩人，我的异父异母的{性别：亲兄弟|亲姐妹}！",
            ["ContentFR"] = "Héhé, merci infiniment ! Tu m’as sauvé la vie, {性别:mon frère d’une autre mère|ma sœur d'un autre père} !",
            ["DialogueId"] = 10103505,
            ["ExStoryInfo"] = "Player",
            ["FacialId"] = {
                [1] = "200011:Smile02",
                },
            ["GUID"] = "194AF573",
            ["NextDialogue"] = 10103506,
            ["SpeakNpcId"] = 200011,
            ["TalkActionId"] = {
                [1] = "200011:Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101034/194AF573",
            },
        [10103506] = {
            ["Camera"] = "-33.322266,90.494141,136.335449,0.000018,-4.258083,-78.357025,35.000011,1.5,false,Disable,1.2",
            ["Content"] = "我先赶紧回去把铜币分给大伙儿了。我呀，平常就在冰湖城到处“进货”，你跟贫民窟的人报我玛尔洁的名号，准能找到我。",
            ["ContentFR"] = "Bon, je dois vite redistribuer ces pièces. Moi, d’habitude, je \"m’approvisionne\" un peu partout à Givrelac. Si tu as besoin de moi, il suffit de donner mon nom dans les taudis, et ils t'aideront à me trouver.",
            ["DialogueId"] = 10103506,
            ["GUID"] = "194AF574",
            ["Scripts"] = "PlayAnimation{_delay{2},ActorId{200011},AnimationId{\"Explain02_Start\"},Duration{1}}",
            ["SpeakNpcId"] = 200011,
            ["TalkActionId"] = {
                [1] = "200011:Talk02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101034/194AF574",
            },
        [10103507] = {
            ["Content"] = "小仆从，我们也快点回去找卡米拉吧！",
            ["ContentFR"] = "Allez, petit larbin, allons vite revoir Camilla !",
            ["DialogueId"] = 10103507,
            ["GUID"] = "194AF575",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101034/194AF575",
            },
        [10103601] = {
            ["Content"] = "“水仙平原”就在南边。",
            ["ContentFR"] = "Les Asphodèles sont juste au sud.",
            ["DialogueId"] = 10103601,
            ["Duration"] = 3,
            ["GUID"] = "194B160A",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10103602,
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101036/194B160A",
            },
        [10103602] = {
            ["Content"] = "快来快来！白在广场等你们！",
            ["ContentFR"] = "Dépêchez-vous ! Snow vous attend sur la place !",
            ["DialogueId"] = 10103602,
            ["Duration"] = 4,
            ["GUID"] = "194B1634",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101036/194B1634",
            },
        [10103701] = {
            ["Content"] = "这边，狩月人所有的委托都在这边的告示板上！",
            ["ContentFR"] = "Viens voir, toutes les missions des Chasseurs de Phoxène sont affichées sur ce panneau !",
            ["DialogueId"] = 10103701,
            ["Duration"] = 3,
            ["GUID"] = "194B2672",
            ["GuideFacialId"] = "Confident",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101037/194B2672",
            },
        [10103801] = {
            ["Camera"] = "172.692993,-479.681641,69.009766,0.001296,4.999999,95.0,25.000006,357.352783,false,DoNotOverride,1.2",
            ["Content"] = "哟，这不是白嘛，又在给狩月人帮忙？是不是又抓了几百个大盗，挫败了十几起惊天大阴谋呀？",
            ["ContentFR"] = "Eh, mais c’est Snow ! Encore en train d’aider les Chasseurs de Phoxène ? Et cette fois, qu’as-tu fait ? T’as arrêté quelques centaines de bandits et déjoué une dizaine de complots infernaux ?",
            ["DefaultLookAt"] = "TalkNpc",
