PlayAnimation{ActorId{200065},AnimationId{\"Explain01_Start\"},Duration{5}},\
PlayAnimation{ActorId{200065},AnimationId{\"Explain01_End\"},Duration{2.1}},\
PlayAnimation{_delay{2.6},ActorId{200065},AnimationId{\"Talk01_Start\"},Duration{0.5}}\
}",
            ["SpeakNpcId"] = 200065,
            ["TalkActionId"] = {
                [1] = "100001:Talk02_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1002/101038/194B3800",
            },
        [10103809] = {
            ["Camera"] = "294.89917,204.099609,233.652344,0.001298,-17.702196,-144.748398,54.403389,386.499695,false,Manual,2.0",
            ["Content"] = "那我努努力，多向前辈学习——",
            ["ContentFR"] = "Alors je vais m’appliquer et apprendre des professionnels comme vous.",
            ["DialogueId"] = 10103809,
            ["ExStoryInfo"] = "Player",
            ["FacialId"] = {
                [1] = "100001:None",
                },
            ["GUID"] = "194B382A",
            ["NextDialogue"] = 10103810,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Explain02_Start",
                [2] = "200065:Talk01_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101038/194B382A",
            },
        [10103810] = {
            ["Camera"] = "-35.028076,37.188477,139.802734,0.00134,1.999114,2.708401,30.000002,206.157364,false,Manual,1.6",
            ["CameraBlendCurve"] = "easeOutQuad",
            ["Content"] = "学习？先消停会儿吧！好好思考，想想清楚，自己为什么会走上这条路。",
            ["ContentFR"] = "Apprendre ? Donne-moi un peu de répit ! Réfléchis bien et demande-toi pourquoi tu t’es {性别:retrouvé|retrouvée} sur cette voie, c’est ce que tu devrais faire.",
