        [10103817] = {
            ["Camera"] = "-903.175842,661.294922,132.769531,0.00128,-1.799468,-25.584341,60.000004,184.96936,false,Manual,10.0",
            ["Content"] = "抱歉抱歉，想喝点什么？去跟卡米拉说一声，我请你，就当作赔礼。",
            ["ContentFR"] = "Désolé, désolé... Tu veux boire quelque chose ? Va le dire à Camilla, c’est moi qui régale, considère ça comme mes excuses.",
            ["DialogueId"] = 10103817,
            ["FinalCamera"] = "-896.797668,674.62207,132.769531,0.001278,-1.799468,-25.585255,60.000004,184.96936,false,Manual,10.0",
            ["GUID"] = "194B39CE",
            ["SpeakNpcId"] = 200065,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1002/101038/194B39CE",
            },
        [10103901] = {
            ["Content"] = "太好了，你的第一个委托比我想象中还要顺利呢。",
            ["ContentFR"] = "Génial ! Ta première mission s’est mieux passée que je ne l’imaginais.",
            ["DialogueId"] = 10103901,
            ["GUID"] = "194B4742",
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101039/194B4742",
            },
        [10103902] = {
            ["Content"] = "和卡米拉说一声吧，我请客。",
