        [10104004] = {
            ["Camera"] = "-751.572632,-799.925781,445.150391,0.001331,-15.60022,38.201538,20.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "正好我也跟{性别：他|她}讲一讲现在的行情，老实说，最近咱们这行可不太好过，稍微值点钱的委托都得用抢的。",
            ["ContentFR"] = "Oh, et je peux te mettre au courant du marché actuel. Pour être franc, ces derniers temps, c’est dur, pour un travail qui vaut un peu, il faut batailler.",
            ["DialogueId"] = 10104004,
            ["ExStoryInfo"] = "Player",
            ["FinalCamera"] = "-771.009277,-775.231445,445.150391,0.001331,-15.60022,38.201538,20.0,100000.0,false,DoNotOverride,2.8",
