        [10104005] = {
            ["Camera"] = "1019.142822,-738.232422,198.009766,-0.0,0.200002,87.801537,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "今天的委托我刚看过，净是吃力不讨好的小活。除了那个烫手山芋……",
            ["ContentFR"] = "J’ai regardé les missions du jour, que des petites corvées ingrates. Sauf cette patate chaude...",
            ["DialogueId"] = 10104005,
            ["FinalCamera"] = "1021.591187,-674.18457,195.511719,-0.0,0.200002,87.801537,35.0,100000.0,false,DoNotOverride,2.8",
