        [10104006] = {
            ["Camera"] = "206.755127,354.53418,169.501953,0.000076,-7.199996,-92.795441,30.000002,292.884125,false,Manual,2.0",
            ["Content"] = "一个麻烦委托，找一块见鬼的石头——唉，跟你说也没用，这活连我们这些老手都没人接，何况是你这样新来的。",
            ["ContentFR"] = "Une mission compliquée, trouver une pierre maudite — eh, inutile de t’en parler, même nous, les vétérans, on ose à peine, alors toi, en tant que {性别:débutant|débutante}.",
            ["DialogueId"] = 10104006,
            ["FacialId"] = {
                [1] = "100001:Think01",
                },
            ["GUID"] = "194B587C",
            ["LookAt"] = {
                [1] = "200003:n(100001)",
                [2] = "200002:n(200065)",
                },
            ["NextOptions"] = {
                [1] = 101040061,
                },
            ["Scripts"] = "SEQ{\
