        [10104402] = {
            ["Camera"] = "214.22168,-132.881836,141.021973,0.000037,-1.199094,134.199219,35.0,230.308487,false,Manual,4.0",
            ["Content"] = "赛琪？你怎么跟上来了？",
            ["ContentFR"] = "Psyche ? Que fais-tu ici ?",
            ["DefaultLookAt"] = "TalkNpc",
