            },
        }
  end },
  { MinKey = 10104502, MaxKey = 10106214, Loader = function()
      return {
        [10104502] = {
            ["Content"] = "落满雪的针叶林，望不到边的冰湖……高个子山峰被天空按住了脑袋……很喜欢。",
            ["ContentFR"] = "Les conifères recouverts de neige, le lac à perte de vue... les sommets des montagnes plongés dans les nuages... j’adore.",
            ["DialogueId"] = 10104502,
            ["Duration"] = 3,
            ["GUID"] = "194BA9DC",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10104503,
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101045/194BA9DC",
            },
        [10104503] = {
            ["Content"] = "白还是更喜欢城里面！如果郊外没有那些到处巡逻的秽兽就好啦。",
            ["ContentFR"] = "Snow a plutôt l’âme d’une citadine ! Si seulement ces Souillés ne rôdaient pas à l’extérieur...",
            ["DialogueId"] = 10104503,
            ["Duration"] = 3,
            ["GUID"] = "194BAA06",
            ["GuideFacialId"] = "Afraid",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10104504,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101045/194BAA06",
            },
        [10104504] = {
            ["Content"] = "里面更安全些。但是，我喜欢这里的……空气。",
            ["ContentFR"] = "C’est plus sûr à l’intérieur, c’est vrai. Mais j’aime bien… l’air ici.",
            ["DialogueId"] = 10104504,
            ["Duration"] = 3,
            ["GUID"] = "194BAA30",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10104505,
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101045/194BAA30",
            },
        [10104505] = {
            ["Content"] = "有区别吗？我闻起来都差不多耶……",
            ["ContentFR"] = "Il y a une différence ? Moi, ça sent pareil...",
            ["DialogueId"] = 10104505,
            ["Duration"] = 3,
            ["GUID"] = "194BAA5A",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10104506,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101045/194BAA5A",
            },
        [10104506] = {
            ["Content"] = "嗯……冰湖城的空气总是带着腥味，带着哭声。",
            ["ContentFR"] = "Mmm... l’air de Givrelac est toujours chargé de sang et de pleurs.",
            ["DialogueId"] = 10104506,
            ["Duration"] = 3,
            ["GUID"] = "194BAA84",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10104507,
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101045/194BAA84",
            },
        [10104507] = {
            ["Content"] = "而这里是森林的味道，浮冰的味道，还有驶向远方的汽笛。这里偶尔能看到雪白的鹿从林间窜出——",
            ["ContentFR"] = "Ici, c’est l’odeur de la forêt, de la glace flottante, et le sifflement lointain des locomotives. Parfois, on aperçoit des cerfs blancs surgir de la forêt...",
            ["DialogueId"] = 10104507,
            ["Duration"] = 3,
            ["GUID"] = "194BAAAE",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10104508,
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101045/194BAAAE",
            },
        [10104508] = {
            ["Content"] = "而冰湖城街道的角落窜出来的，是小偷、强盗……或者呜咽的乞丐。",
            ["ContentFR"] = "Alors qu’au détour des rues de Givrelac, ce sont des voleurs, des brigands... ou des mendiants qui gémissent.",
            ["DialogueId"] = 10104508,
            ["Duration"] = 3,
            ["GUID"] = "194BAAD8",
            ["GuideFacialId"] = "Sad",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10104509,
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101045/194BAAD8",
            },
        [10104509] = {
            ["Content"] = "{nickname}，你呢？讲讲你的故乡吧！那座海岛是怎样的？",
            ["ContentFR"] = "Et toi, {nickname} ? Parle-nous de ta ville natale ! Cette île, elle est comment ?",
            ["DialogueId"] = 10104509,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "194BAB02",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10104510,
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101045/194BAB02",
            },
        [10104510] = {
            ["Content"] = "那里的“空气”是金色的砂砾，海岸的迷迭香……",
            ["ContentFR"] = "L’air est fait de gravier doré et de romarin sur la côte...",
            ["DialogueId"] = 10104510,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "194BAB2C",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10104511,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101045/194BAB2C",
            },
        [10104511] = {
            ["Content"] = "是深夜朦胧的海雾，是我和贝……和家人每天眺望的巨大天之树。",
            ["ContentFR"] = "C’est la brume marine de minuit et l’immense Arbre Céleste que Berr... ma famille et moi regardions chaque jour.",
            ["DialogueId"] = 10104511,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "194BAB56",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10104512,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101045/194BAB56",
            },
        [10104512] = {
            ["Content"] = "嗯……那如果你什么时候回去故乡，请代我向它们问候~",
            ["ContentFR"] = "Mmm... si jamais tu retournes là-bas, transmets-leur mes salutations.",
            ["DialogueId"] = 10104512,
            ["Duration"] = 3,
            ["GUID"] = "194BAB80",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
