            ["VoiceName"] = "voice/$Locale$/story/1002/101045/194BAB80",
            },
        [10104513] = {
            ["Content"] = "……唔唔，你们两个的话好难懂哦……",
            ["ContentFR"] = "... Hmm, vous deux, c’est pas facile à suivre...",
            ["DialogueId"] = 10104513,
            ["Duration"] = 3,
            ["GUID"] = "194BABAA",
            ["GuideFacialId"] = "Sad",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10104514,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101045/194BABAA",
            },
        [10104514] = {
            ["Content"] = "等你再长大一些就明白啦。",
            ["ContentFR"] = "Tu comprendras mieux quand tu seras plus grande.",
            ["DialogueId"] = 10104514,
            ["Duration"] = 3,
            ["GUID"] = "194BABD4",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
