        [10104701] = {
            ["Content"] = "锁住了？看我给它敲开！",
            ["ContentFR"] = "C’est verrouillé ? Regarde, je vais la fracasser !",
            ["DialogueId"] = 10104701,
            ["Duration"] = 3,
            ["GUID"] = "194BCA82",
