            },
        [10105402] = {
            ["Camera"] = "-72.519531,598.007812,133.294922,0.001335,-3.398285,-86.062561,30.0,755.136902,false,Manual,8.0",
            ["Content"] = "它就在这儿，也没长嘴喊谁“主人”。咱们狩月人干活又不是排队买面包，哪有什么先来后到。",
            ["ContentFR"] = "Il était juste là, sans qu’aucun nom ne soit dessus, non ? Allez, chez nous, dans notre boulot, y a pas de « premier arrivé, premier servi ».",
            ["DialogueId"] = 10105402,
            ["FacialId"] = {
                [1] = "200021:Blink",
                },
            ["FinalCamera"] = "-72.117188,591.96875,132.942383,0.001335,-3.398285,-86.062561,30.000002,717.98114,false,Manual,8.0",
            ["GUID"] = "194C3D84",
            ["LookAt"] = {
                [1] = "200021:n(200021)",
                },
            ["NextDialogue"] = 10105403,
            ["Scripts"] = "PlayAnimation{_delay{0.5},ActorId{200021},AnimationId{\"Talk03_Start\"},Duration{1}}",
            ["SpeakNpcId"] = 200021,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1002/101054/194C3D84",
            },
        [10105403] = {
            ["Camera"] = "-86.927734,166.710938,157.334961,0.001335,-1.398345,-77.243843,50.0,303.408173,false,Manual,8.0",
            ["Content"] = "你看着面生，新来的吧？这个道理总会有人教给你们，而我只是凑巧成为了你们的老师。要不，这颗绮晶就当交学费喽？",
            ["ContentFR"] = "Toi, tu es {性别:nouveau|nouvelle}, non ? Cette leçon, quelqu’un devait bien te la donner, et il se trouve que c’est moi aujourd’hui. On dira que cet Éclat stellaire, c’est ton droit d’entrée.",
            ["DialogueId"] = 10105403,
            ["FacialId"] = {
                [1] = "200021:Smile02",
                },
            ["FinalCamera"] = "-85.015625,158.255859,157.125977,0.001334,-1.398345,-77.242615,50.0,303.408173,false,Manual,8.0",
            ["GUID"] = "194C3DAE",
