        [10105425] = {
            ["Camera"] = "-1043.257812,-1602.347656,78.117188,0.001387,-0.599458,57.977047,50.0,1941.626953,false,Manual,10.0",
            ["Content"] = "“水仙平原”所有人都认识我奥特赛德，跑不了的。你们先回去吧，我还得留在这里忙上一阵。",
            ["ContentFR"] = "Rassurez-vous, tout le monde aux Asphodèles me connaît. Bon, j’ai encore quelques affaires à régler ici. Vous pouvez y aller sans moi.",
            ["DialogueId"] = 10105425,
            ["FacialId"] = {
                [1] = "200021:None",
                },
            ["FinalCamera"] = "-1020.1875,-1634.185547,78.268555,0.001395,-0.599458,57.97691,50.000008,1941.626953,false,Manual,10.0",
