        [10105429] = {
            ["Camera"] = "-132.814453,-357.947266,210.344727,0.001424,-14.199464,73.163467,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我想看看能不能辨认出他们的身份，把遗物交还给他们家人……既然到这儿了，总不能就这么放着不管。",
            ["ContentFR"] = "Je veux voir si je peux identifier leurs propriétaires et restituer leurs affaires à leur famille... maintenant que je suis là, je ne peux pas les laisser traîner.",
            ["DialogueId"] = 10105429,
            ["FinalCamera"] = "-130.597656,-350.683594,191.751953,0.001424,-11.999413,72.962524,35.000008,100000.0,false,DoNotOverride,2.8",
