                [2] = "\
200061:Think_End",
                },
            ["ToFinalCameraBlendTime"] = 7,
            ["VoiceName"] = "voice/$Locale$/story/1002/101054/194C421C",
            },
        [10105436] = {
            ["Camera"] = "-457.835938,550.085938,190.137695,0.001318,-9.39989,-51.879406,35.0,100000.0,false,DoNotOverride,2.8",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "哼，我才不和你这种小角色计较！小仆从，来，本魔王讲给你听。",
            ["ContentFR"] = "Hmpf, je ne vais pas me rabaisser à discuter avec un petit personnage comme toi ! Viens ici, mon petit larbin, laisse ton Roi Démon t’éclairer. ",
            ["DialogueId"] = 10105436,
            ["FinalCamera"] = "-465.341797,544.189453,190.137695,0.001318,-9.399897,-51.879646,35.000008,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "194C4246",
            ["LookAt"] = {
