            ["TurnTo"] = {
                [1] = "200006:n(200002)",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101054/194C4246",
            },
        [10105437] = {
            ["Camera"] = "-353.777344,-47.939453,40.262695,0.001464,14.798335,24.421301,40.0,345.303528,false,Manual,2.8",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "简单来说呢，“觉醒”是每个卡戎之民都会经历的成长阶段，大多都发生在成年前后。觉醒的瞬间，身上会发出很亮很亮的光——你肯定有印象的！",
            ["ContentFR"] = "En bref, \"l’Éveil\" est une étape de croissance que tout Charon traverse, en général à l’âge adulte. Au moment de l’Éveil, le corps émet une lumière très intense, tu dois sûrement t’en souvenir !",
            ["DialogueId"] = 10105437,
            ["FinalCamera"] = "-360.898438,-30.494141,40.262695,0.001463,14.598415,21.022375,40.0,345.303528,false,Manual,2.8",
            ["GUID"] = "194C4270",
            ["LookAt"] = {
                [1] = "200061:n(200002)",
                },
            ["NextDialogue"] = 10105438,
            ["Scripts"] = "PARA{\
PlayAnimation{_delay{5.2},ActorId{200002},AnimationId{\"Explain01_Start\"},Duration{4.8}},\
PlayAnimation{_delay{10},ActorId{200002},AnimationId{\"Explain01_End\"},Duration{1.8}},\
PlayAnimation{_delay{11.8},ActorId{200002},AnimationId{\"Talk02_Start\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200061:ScratchHead_Start",
                },
            ["ToFinalCameraBlendTime"] = 11,
            ["VoiceName"] = "voice/$Locale$/story/1002/101054/194C4270",
            },
        [10105438] = {
            ["Camera"] = "-101.375,79.515625,124.116211,0.001489,-19.999441,-142.798492,35.0,124.912491,false,Manual,8.0",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "在觉醒之后呢，有些卡戎会变强大许多——就像你们一样，还会使用特别的魔法！他们就是“骸”。",
            ["ContentFR"] = "Après l’Éveil, certains Charons deviennent beaucoup plus forts, comme toi, et peuvent utiliser une magie spéciale ! Ce sont les \"Daimons\".",
            ["DialogueId"] = 10105438,
            ["FinalCamera"] = "-101.375,79.515625,124.116211,0.001489,-19.999441,-142.798492,37.0,124.912491,false,Manual,8.0",
            ["GUID"] = "194C429A",
