        [10105804] = {
            ["Camera"] = "-7.569336,200.742188,104.007324,0.000081,5.400091,-89.397034,20.0,136.349091,false,DoNotOverride,5.0",
            ["Content"] = "告诉我，你们去了哪儿？",
            ["ContentFR"] = "Alors, dites-moi. Où êtes-vous allés ?",
            ["DialogueId"] = 10105804,
            ["GUID"] = "194C7F78",
