                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1002/101058/194C819A",
            },
        [10105901] = {
            ["Content"] = "恩里克这家伙，一开口还是这么让人火大……",
            ["ContentFR"] = "Pff, Henrik... toujours aussi insupportable dès qu’il ouvre la bouche...",
            ["DialogueId"] = 10105901,
            ["Duration"] = 3,
            ["GUID"] = "194C8F62",
            ["GuideFacialId"] = "Angry",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10105902,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101059/194C8F62",
            },
        [10105902] = {
            ["Content"] = "但愿他不会责骂赛琪。",
            ["ContentFR"] = "Pourvu qu’il ne soit pas trop dur avec Psyche...",
            ["DialogueId"] = 10105902,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "194C8F8C",
            ["GuideFacialId"] = "Afraid",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10105903,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101059/194C8F8C",
            },
        [10105903] = {
            ["Content"] = "至于是不是住在宅子里的最后一晚，得要去找奥特赛德了。",
            ["ContentFR"] = "Quant à moi, si c’est vraiment ma dernière nuit dans cette maison... je dois aller parler à l’Étranger.",
            ["DialogueId"] = 10105903,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "194C8FB6",
            ["GuideFacialId"] = "Sad",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10105904,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101059/194C8FB6",
            },
        [10105904] = {
            ["Content"] = "要绕开我说悄悄话对吧？奥特赛德事儿真多。",
            ["ContentFR"] = "Alors quoi, vous allez encore comploter en cachette sans moi ? Sérieux, cet Étranger est vraiment un pot-de-colle...",
            ["DialogueId"] = 10105904,
            ["Duration"] = 3,
            ["GUID"] = "194C8FE0",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10105905,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101059/194C8FE0",
            },
        [10105905] = {
            ["Content"] = "哼，我还不稀罕听呢！你走吧，我要去水仙平原玩了。",
            ["ContentFR"] = "Pff, comme si ça m’intéressait ! Vas-y, file. Moi, je vais traîner du côté des Asphodèles.",
            ["DialogueId"] = 10105905,
            ["Duration"] = 3,
            ["GUID"] = "194C900A",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101059/194C900A",
            },
        [10106001] = {
            ["Camera"] = "314.686646,-189.882812,143.371094,0.000135,1.011373,-179.604111,25.0,100000.0,false,Disable,2.8",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "“♪断翅的夜莺，不要继续哭泣……",
