            },
        [10106105] = {
            ["Camera"] = "392.718933,-45.626953,133.417969,0.000022,-8.587979,133.589279,20.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "你好！我是菲娜，奥特赛德的妹妹……咳、咳！",
            ["ContentFR"] = "Bonjour ! Moi, c’est Fina. La petite sœur de l’Étranger... <I>kof, kof !</>",
            ["DialogueId"] = 10106105,
            ["FacialId"] = {
