        [10106112] = {
            ["Camera"] = "476.360107,-433.447266,145.050781,0.000096,-1.787993,57.580418,20.000008,177.3125,false,Manual,4.42362",
            ["Content"] = "咳，就是喝水……你就听她的，别在意细节。",
