        [10106310] = {
            ["Camera"] = "-801.484619,-220.195312,860.855957,0.000049,-21.199219,35.871891,30.000008,2029.508545,false,Manual,1.2",
            ["Content"] = "十八年前，在弗莱格桑省，出过一起群星绮晶用于医药导致的严重事故，大半个城市陷入了混乱。绮晶贸易禁令也是在那个时候颁布的。",
            ["ContentFR"] = "Il y a eu un cas grave de négligence médicale impliquant l’Éclat stellaire dans la province de Flagson. La moitié de la ville a sombré dans le chaos. C’est à ce moment-là que le commerce des Éclats stellaires a été interdit.",
            ["DialogueId"] = 10106310,
            ["FinalCamera"] = "-801.484619,-220.195312,902.421387,0.000049,-21.199219,35.871891,30.000008,2029.508545,false,Manual,1.2",
            ["GUID"] = "194CD1D4",
            ["NextOptions"] = {
                [1] = 10106311,
                },
            ["RelatedWikiId"] = {
                [1] = 408005,
                [2] = 301004,
                },
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{200021},AnimationId{\"Talk03_End\"},Duration{2}},\
PlayAnimation{_delay{2},ActorId{200021},AnimationId{\"Talk02_Start\"},Duration{2}}\
}",
            ["SpeakNpcId"] = 200021,
            ["TalkActionId"] = {
                [1] = "100001:Think_End",
                },
            ["ToFinalCameraBlendTime"] = 15,
            ["VoiceName"] = "voice/$Locale$/story/1002/101063/194CD1D4",
            },
        [10106311] = {
            ["Content"] = "他违背了禁令。这件事我听说了。",
            ["ContentFR"] = "<I>Donc il enfreint l’interdiction. J’en avais entendu parler.</>",
            ["DialogueId"] = 10106311,
            ["GUID"] = "10106311.0",
            ["NextDialogue"] = 10106312,
            },
        [10106312] = {
            ["Camera"] = "0.102539,187.96582,195.69873,0.00013,-12.400058,-82.534454,30.000008,282.315033,false,Manual,2.2",
            ["Content"] = "只是这样也就罢了。冰湖城大街上站着的，有几个人手里真的干干净净？关键在于，另一些关于“修普诺斯之家”的流言。",
            ["ContentFR"] = "Et encore... ça ne serait qu’un détail. À Givrelac, rares sont ceux qui ont vraiment les mains propres. Ce qui me trouble, ce sont les rumeurs autour de la Maison d’Hypnos.",
            ["DialogueId"] = 10106312,
            ["FacialId"] = {
                [1] = "200021:Doubt01",
                },
            ["FinalCamera"] = "-0.895264,195.582031,197.388184,0.00013,-12.400058,-82.534454,30.000008,282.315033,false,Manual,2.2",
            ["GUID"] = "194CD1FE",
            ["NextDialogue"] = 10106313,
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{200021},AnimationId{\"Talk02_End\"},Duration{1}},\
PlayAnimation{ActorId{200021},AnimationId{\"DisagreeHead\"},Duration{1}},\
PlayAnimation{_delay{3},ActorId{200021},AnimationId{\"Explain01_Start\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 200021,
            ["TalkActionId"] = {
                [1] = "100001:Talk03_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1002/101063/194CD1FE",
            },
        [10106313] = {
            ["Camera"] = "-2526.490234,772.758789,582.1875,0.000011,-9.199978,-15.202279,45.000023,2420.254639,false,Manual,1.2",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "附近的人说，恩里克和那里的住客行事怪异，他们向来不与外人交往。虽然打着旅店的名义，但是它所有的住客都是由恩里克<H>挑选</>。",
            ["ContentFR"] = "Les habitants disent aussi qu’Henrik et ses pensionnaires se comportent bizarrement, qu’ils évitent tout contact avec l’extérieur. Officiellement, c’est une auberge... mais en réalité, tous ceux qui y logent sont <H>choisis par Henrik lui-même</>.",
            ["DialogueId"] = 10106313,
            ["FinalCamera"] = "-2536.047363,737.591797,582.1875,0.000011,-9.199978,-15.202335,45.000023,2420.254639,false,Manual,1.2",
            ["GUID"] = "194CD228",
            ["NextDialogue"] = 10106314,
            ["SpeakNpcId"] = 200021,
            ["TalkActionId"] = {
                [1] = "200021:Think_Start",
                },
            ["ToFinalCameraBlendTime"] = 20,
            ["VoiceName"] = "voice/$Locale$/story/1002/101063/194CD228",
            },
        [10106314] = {
            ["Camera"] = "-118.642822,-24.229492,136.930176,0.000165,10.799492,27.794773,35.0,170.938126,false,Manual,1.623207",
            ["Content"] = "有人偷瞧过几眼，里面都是些不到二十岁的年轻人。更奇怪的是，那里的住客向来只见进去，不见出来。没人知道那些住客最后去了哪里。",
            ["ContentFR"] = "Certains ont réussi à jeter un œil à l’intérieur : que des jeunes de moins de vingt ans. Plus étrange encore... on les voit entrer, jamais ressortir. Nul ne sait ce qu’ils deviennent.",
            ["DialogueId"] = 10106314,
            ["FinalCamera"] = "-87.214844,-7.525391,144.353027,0.000166,11.999521,27.99498,35.0,150.986908,false,Manual,1.623207",
            ["GUID"] = "194CD252",
            ["NextDialogue"] = 10106315,
            ["Scripts"] = "SEQ{\
PlayAnimation{_delay{3},ActorId{200021},AnimationId{\"Think_End\"},Duration{1}},\
PlayAnimation{_delay{2.5},ActorId{200021},AnimationId{\"Talk02_Start\"},Duration{1}},\
PlayAnimation{_delay{2},ActorId{200021},AnimationId{\"Talk02_End\"},Duration{1}},\
PlayAnimation{ActorId{200021},AnimationId{\"DisagreeHead\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 200021,
            ["TalkActionId"] = {
                [1] = "100001:Talk03_End",
                },
            ["ToFinalCameraBlendTime"] = 12,
            ["VoiceName"] = "voice/$Locale$/story/1002/101063/194CD252",
            },
        [10106315] = {
            ["Camera"] = "1.409424,177.989258,193.487305,0.000134,-12.400058,-82.534454,30.000002,263.612305,false,Manual,2.2",
            ["Content"] = "我也听说过一些“鬼宅”之类的传言，这么一说就更……",
            ["ContentFR"] = "J’ai entendu, moi aussi, des rumeurs de \"manoir hanté\"... mais dit comme ça, c’est encore plus... inquiétant.",
            ["DialogueId"] = 10106315,
            ["ExStoryInfo"] = "Player",
            ["FacialId"] = {
                [1] = "100001:Think01",
                },
            ["GUID"] = "194CD27C",
            ["NextDialogue"] = 10106316,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Think_Start",
                [2] = "200021:AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101063/194CD27C",
            },
        [10106316] = {
            ["Content"] = "说起来，你为什么会调查到这个？",
            ["ContentFR"] = "Au fait, pourquoi t’intéresser à tout ça ?",
            ["DialogueId"] = 10106316,
            ["ExStoryInfo"] = "Player",
            ["FacialId"] = {
                [1] = "100001:None",
                },
            ["GUID"] = "194CD27D",
            ["NextDialogue"] = 10106317,
            ["Scripts"] = "PlayAnimation{_delay{0.5},ActorId{100001},AnimationId{\"Think_End\"},Duration{1}}",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101063/194CD27D",
            },
        [10106317] = {
            ["Camera"] = "-118.512451,-182.769531,140.193848,0.000153,4.599757,50.000011,35.0,272.898132,false,Manual,2.264544",
            ["Content"] = "我有个搭过几次伙的年轻狩月人，叫亨特的小兄弟。一个月前他失踪了，城里的拾荒小妹是最后一个见过他的人——在“修普诺斯之家”门口。",
            ["ContentFR"] = "J’avais un camarade Chasseur de Phoxène, un jeune nommé Hunt. Il a disparu il y a un mois. La dernière à l’avoir vu est une petite récupératrice de la cité... devant la Maison d’Hypnos.",
            ["DialogueId"] = 10106317,
            ["FacialId"] = {
                [1] = "200021:None",
                },
            ["GUID"] = "194CD2A6",
            ["NextDialogue"] = 10106318,
            ["Scripts"] = "SEQ{\
CameraMoveTo{_delay{5.01},TargetPosition{\"-637.433105,247.024414,212.966797,0.000224,14.600731,161.606003,15.000005,272.898132,false,DoNotOverride,2.264544\"},duration{0}},\
CameraMoveTo{TargetPosition{\"-637.433105,247.024414,91.351562,0.000223,6.600879,161.406097,15.000005,272.898132,false,DoNotOverride,2.264544\"},duration{12}}\
}",
            ["SpeakNpcId"] = 200021,
            ["TalkActionId"] = {
                [1] = "200021:Sigh_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101063/194CD2A6",
            },
        [10106318] = {
            ["Camera"] = "-599.96167,1241.567383,973.956787,0.000164,-31.200064,-54.605648,35.0,179.039703,false,DoNotOverride,7.148376",
            ["Content"] = "前几天我去了那个旅馆，和恩里克大吵了一架。结果呢，匕首都架在那家伙脖子上了，他还是不肯说出亨特的下落。",
            ["ContentFR"] = "Il y a quelques jours, je suis allé affronter Henrik. Même avec ma dague sous sa gorge, il a refusé de dire où se trouvait Hunt.",
            ["DialogueId"] = 10106318,
            ["FacialId"] = {
                [1] = "200021:Sad01",
                },
            ["FinalCamera"] = "-650.708252,1312.987305,1027.01709,0.000164,-31.200064,-54.605648,35.000008,179.039703,false,DoNotOverride,7.148376",
            ["GUID"] = "194CD2D0",
            ["NextDialogue"] = 10106319,
            ["Scripts"] = "SEQ{\
PlayAnimation{_delay{1},ActorId{200021},AnimationId{\"Sigh_End\"},Duration{1}},\
PlayAnimation{ActorId{200021},AnimationId{\"Talk03_Start\"},Duration{1}},\
PlayAnimation{_delay{2.5},ActorId{200021},AnimationId{\"Talk03_End\"},Duration{1}},\
PlayAnimation{_delay{1},ActorId{200021},AnimationId{\"Angry01_Start\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 200021,
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/1002/101063/194CD2D0",
            },
        [10106319] = {
            ["Camera"] = "-62.165771,-132.756836,145.641602,0.000175,5.599655,57.998493,35.0,179.039703,false,Manual,7.148376",
            ["Content"] = "他只是在那儿冷笑，“卡戎之民谋害索拉人是什么下场，你比我更懂。我知道你有个妹妹。为了她，少管闲事。”",
            ["ContentFR"] = "Il s’est contenté de ricaner : « Tu sais mieux que moi ce qu’il en coûte à un Charon de s’en prendre à un Sola. Je sais que tu as une sœur... Si tu tiens à elle, mêle-toi de tes affaires. »",
            ["DialogueId"] = 10106319,
            ["FinalCamera"] = "-57.103516,-124.65625,146.576172,0.000175,5.599648,57.998432,35.0,179.039703,false,Manual,7.148376",
            ["GUID"] = "194CD2FA",
            ["NextDialogue"] = 10106320,
            ["Scripts"] = "PARA{\
PlayFacial{_delay{8.01},ActorId{100001},FacialId{\"Sad01\"}},\
SEQ{\
PlayAnimation{ActorId{200021},AnimationId{\"Angry01_End\"},Duration{1}},\
PlayAnimation{ActorId{200021},AnimationId{\"DisagreeHead\"},Duration{1}}\
},\
SEQ{\
CameraMoveTo{_delay{8.01},TargetPosition{\"33.62793,178.25293,208.352539,0.000216,-11.998771,-94.401909,55.000008,276.918182,false,Manual,7.148376\"},duration{0}},\
CameraMoveTo{TargetPosition{\"31.643555,152.46875,202.856445,0.000216,-11.998771,-94.401909,55.000008,246.001785,false,Manual,7.148376\"},duration{8}}\
}\
}",
            ["SpeakNpcId"] = 200021,
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/1002/101063/194CD2FA",
            },
        [10106320] = {
            ["Camera"] = "3519.108887,1585.492188,-165.398438,0.0,0.0,-94.298676,15.0,506.047913,false,DoNotOverride,1.2",
            ["Content"] = "他*的！真想把他扔进泪湖喂鱼。总之，我必须查清楚亨特的下落，还有恩里克的底细。",
            ["ContentFR"] = "Ce fumier ! J’aurais voulu le jeter dans le Lac du Deuil, qu’il serve de festin aux poissons. Mais je dois découvrir ce qu’il a fait de Hunt... et quels secrets cache Henrik.",
            ["DialogueId"] = 10106320,
            ["FacialId"] = {
                [1] = "200021:Angry01",
                },
            ["GUID"] = "194CD324",
            ["NextOptions"] = {
                [1] = 10106321,
                },
            ["SpeakNpcId"] = 200021,
            ["TalkActionId"] = {
                [1] = "200021:Angry01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101063/194CD324",
            },
        [10106321] = {
            ["Content"] = "你对朋友还挺仗义的。",
            ["ContentFR"] = "<I>Tu tiens vraiment à ton ami.</>",
            ["DialogueId"] = 10106321,
            ["GUID"] = "10106321.0",
            ["NextDialogue"] = 10106322,
            },
        [10106322] = {
            ["Camera"] = "-113.647461,-178.358398,144.197266,0.000174,3.999752,51.800861,35.0,272.898132,false,Manual,3.476349",
            ["Content"] = "……不只是为了亨特，更是为了菲娜。我不想再看见亲人生活在恐惧之中。",
            ["ContentFR"] = "... Ce n’est pas que pour Hunt. C’est surtout pour Fina. Je refuse de voir un proche vivre à nouveau dans la peur.",
            ["DialogueId"] = 10106322,
            ["FacialId"] = {
                [1] = "200021:None",
                },
            ["GUID"] = "194CD3A0",
            ["NextDialogue"] = 10106323,
            ["Scripts"] = "PARA{\
PlayAnimation{_delay{3.5},ActorId{200021},AnimationId{\"Talk01_End\"},Duration{1}},\
PlayAnimation{_delay{1.5},ActorId{200021},AnimationId{\"DisagreeHead\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 200021,
            ["TalkActionId"] = {
                [1] = "200021:Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101063/194CD3A0",
            },
        [10106323] = {
            ["Camera"] = "31.643555,152.46875,202.856445,0.000216,-11.998804,-94.401909,55.0,248.159653,false,Manual,7.148376",
            ["Content"] = "这么说来，我也有个担心的人……你提到的绿衣服女孩，赛琪。",
            ["ContentFR"] = "Je comprends... Moi aussi, il y a quelqu’un qui m’inquiète, la fille en vert dont tu as parlé, Psyche.",
            ["DialogueId"] = 10106323,
            ["ExStoryInfo"] = "Player",
            ["FacialId"] = {
                [1] = "100001:Sad01",
                },
            ["GUID"] = "194CD3A1",
            ["NextDialogue"] = 10106346,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101063/194CD3A1",
            },
        [10106325] = {
            ["Camera"] = "-72.05835,-160.591797,149.589355,0.000178,4.599668,58.198891,45.0,272.898132,false,Manual,5.157309",
            ["Content"] = "那更好了，看来我们已经有了共同的目标。",
            ["ContentFR"] = "Parfait. On dirait qu’on a un objectif commun.",
            ["DialogueId"] = 10106325,
            ["FacialId"] = {
                [1] = "200021:Confident01",
                },
            ["GUID"] = "194CD3CC",
            ["NextDialogue"] = 10106326,
            ["Scripts"] = "PlayAnimation{_delay{1},ActorId{100001},AnimationId{\"AgreeHead\"},Duration{1}}",
            ["SpeakNpcId"] = 200021,
            ["TalkActionId"] = {
                [1] = "200021:AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101063/194CD3CC",
            },
        [10106326] = {
            ["Content"] = "我原本是打算去废矿弄来群星绮晶，再借着拿绮晶跟恩里克上门赔罪的由头，进旅馆里面瞧瞧。",
            ["ContentFR"] = "À l’origine, je comptais récupérer un Éclat stellaire dans la fosse, et m’en servir comme prétexte pour présenter mes excuses à Henrik. Ça m’aurait permis d’entrer dans l’auberge et d’observer les lieux.",
            ["DialogueId"] = 10106326,
            ["FacialId"] = {
                [1] = "200021:None",
                },
            ["GUID"] = "194CD3F6",
            ["NextDialogue"] = 10106327,
            ["Scripts"] = "PlayAnimation{ActorId{200021},AnimationId{\"Think_Start\"},Duration{2}}",
            ["SpeakNpcId"] = 200021,
            ["VoiceName"] = "voice/$Locale$/story/1002/101063/194CD3F6",
            },
        [10106327] = {
            ["Camera"] = "-1467.822266,2680.921875,479.816895,0.000082,-22.999664,-48.185631,35.0,565.117065,false,Manual,2.0",
            ["CameraBlendCurve"] = "easeInQuad",
            ["Content"] = "我本来想着那委托肯定没人会接，就先去找路子买蛋糕了——结果没想到碰上你们这么不按套路出牌的新人。所以，要不要做个交易？",
            ["ContentFR"] = "Je pensais que personne n’accepterait cette mission, alors j’étais parti chercher un gâteau... Et voilà que vous, les {性别:petits nouveaux|petites nouvelles}, venez tout chambouler. Alors ? On fait affaire ?",
            ["DialogueId"] = 10106327,
            ["FacialId"] = {
                [1] = "200021:Smile02",
                },
            ["FinalCamera"] = "-1442.544678,2703.53418,479.816895,0.000082,-22.999664,-48.186123,35.0,565.117065,false,Manual,2.0",
            ["GUID"] = "194CD420",
            ["NextDialogue"] = 10106328,
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{200021},AnimationId{\"Think_Start\"},Duration{1}},\
PlayAnimation{_delay{2},ActorId{200021},AnimationId{\"Sigh_Start\"},Duration{1}},\
PlayAnimation{_delay{1.5},ActorId{200021},AnimationId{\"Sigh_End\"},Duration{1}},\
PlayAnimation{_delay{0.5},ActorId{200021},AnimationId{\"Explain01_Start\"},Duration{0}}\
}",
            ["SpeakNpcId"] = 200021,
            ["ToFinalCameraBlendTime"] = 12,
            ["VoiceName"] = "voice/$Locale$/story/1002/101063/194CD420",
            },
        [10106328] = {
            ["Camera"] = "15.664551,9.075195,174.650879,0.000171,-3.399993,66.602043,25.000002,54.401806,false,Manual,3.0",
            ["Content"] = "我可以弄到一个你心心念念的东西——",
            ["ContentFR"] = "Je peux t’obtenir quelque chose de bien plus précieux que de l’argent...",
            ["DialogueId"] = 10106328,
            ["FacialId"] = {
                [1] = "200021:Smile01",
                },
            ["GUID"] = "194CD44A",
            ["NextDialogue"] = 10106329,
            ["SpeakNpcId"] = 200021,
            ["TalkActionId"] = {
                [1] = "100001:Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101063/194CD44A",
            },
        [10106329] = {
            ["Camera"] = "123.56665,72.790039,133.77002,0.000115,0.599902,-138.799866,30.0,88.840363,false,Manual,2.0",
            ["CameraBlendCurve"] = "easeOutQuad",
            ["Content"] = "“身份”。一个能让你在海伯利亚畅通无阻的身份。当然，哨塔后面高高的内城除外，它的城门只留给那些大人物。",
            ["ContentFR"] = "Une \"identité\". Un permis de circulation qui te permet de circuler librement en Hyperborea, sauf dans la cité intérieure, derrière les grandes tours de garde, réservée aux élites.  ",
            ["DialogueId"] = 10106329,
            ["FacialId"] = {
                [1] = "200021:Confident01",
                },
            ["FinalCamera"] = "127.988281,67.745117,133.77002,0.00011,0.599889,-138.799866,30.0,218.134293,false,Manual,2.0",
            ["GUID"] = "194CD474",
            ["NextDialogue"] = 10106330,
            ["SpeakNpcId"] = 200021,
            ["ToFinalCameraBlendTime"] = 2,
            ["VoiceName"] = "voice/$Locale$/story/1002/101063/194CD474",
            },
        [10106330] = {
            ["Camera"] = "52.672607,-14.748047,167.826172,0.000079,-9.000058,-136.99884,30.000008,96.40477,false,Manual,1.828295",
            ["Content"] = "很多人会愿意给你银币，但很少有人愿意冒着性命危险给你这个。",
            ["ContentFR"] = "Beaucoup seraient prêts à te payer en argent. Peu oseraient risquer leur vie pour t’offrir ça.",
            ["DialogueId"] = 10106330,
            ["FacialId"] = {
                [1] = "100001:Doubt01",
                },
            ["GUID"] = "194CD49E",
            ["NextOptions"] = {
                [1] = 10106331,
                [2] = 10106334,
                },
            ["SpeakNpcId"] = 200021,
            ["TalkActionId"] = {
                [1] = "200021:Explain01_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101063/194CD49E",
            },
        [10106331] = {
            ["Content"] = "你怎么知道我需要这个……",
            ["ContentFR"] = "<I>Comment as-tu su que j’en avais besoin... ?</>",
            ["DialogueId"] = 10106331,
            ["GUID"] = "10106331.0",
            ["NextDialogue"] = 10106332,
            },
        [10106332] = {
            ["Camera"] = "1.812988,-141.155273,152.519043,0.000166,0.799924,88.794739,25.0,179.039703,false,Manual,4.301303",
            ["Content"] = "当然是——猜的。所以你真没有通行证啊？哎，还好遇到了我，否则你在海伯利亚可有罪受喽，哪儿都去不了。",
            ["ContentFR"] = "J’ai juste deviné. Donc tu n’as vraiment pas de permis de circulation ? Heureusement que tu es tombé sur moi, sinon à Hyperborea tu aurais été fichu... à moins de rester caché dans un coin sombre toute la journée.",
            ["DialogueId"] = 10106332,
            ["FacialId"] = {
                [1] = "200021:Smile02",
                },
            ["GUID"] = "194CD4C8",
            ["NextDialogue"] = 10106333,
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{200021},AnimationId{\"Talk01_Start\"},Duration{1}},\
PlayAnimation{_delay{3.5},ActorId{200021},AnimationId{\"Talk01_End\"},Duration{1}},\
PlayAnimation{_delay{1},ActorId{200021},AnimationId{\"AgreeHead\"},Duration{2}}\
}",
            ["SpeakNpcId"] = 200021,
            ["TalkActionId"] = {
                [1] = "100001:Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101063/194CD4C8",
            },
        [10106333] = {
            ["Camera"] = "45.434082,-29.058594,162.999512,0.000143,-4.198688,-134.496765,35.000008,88.220627,false,Manual,3.628265",
            ["Content"] = "（……他在试图套我的话。）",
            ["ContentFR"] = "<I>... Il essaie de me soutirer des infos.</>",
            ["DialogueId"] = 10106333,
            ["DisableMouth"] = 1,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "194CD4F2",
            ["NextOptions"] = {
                [1] = 10106337,
                [2] = 10106338,
                },
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101063/194CD4F2",
            },
        [10106334] = {
            ["Content"] = "通行证是吧。那你能怎么搞到？",
            ["ContentFR"] = "<I>Un permis de circulation, donc. Et toi, comment tu t’en procures un ?</>",
            ["DialogueId"] = 10106334,
            ["GUID"] = "10106334",
            ["NextDialogue"] = 10106335,
            },
        [10106335] = {
            ["Camera"] = "1.812988,-141.155273,152.519043,0.000166,0.799924,88.794739,25.0,179.039703,false,Manual,4.301303",
            ["Content"] = "你要怎么搞到呢，你和冰湖城的卫兵很熟？",
            ["ContentFR"] = "Comment tu t’en procures un ? Tu t’entends bien avec les gardes de Givrelac ?",
            ["DialogueId"] = 10106335,
            ["ExStoryInfo"] = "Player",
            ["FacialId"] = {
                [1] = "200021:None",
                },
            ["GUID"] = "194CD51C",
            ["NextDialogue"] = 10106336,
            ["Scripts"] = "SEQ{\
PlayAnimation{_delay{2},ActorId{100001},AnimationId{\"Talk02_Start\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101063/194CD51C",
            },
        [10106336] = {
            ["Content"] = "熟倒是谈不上，但是狩月人自然有一些自己的小小方式。",
            ["ContentFR"] = "Bien m’entendre, c’est beaucoup dire... Mais nous autres Chasseurs de Phoxène avons nos petites façons.",
            ["DialogueId"] = 10106336,
            ["FacialId"] = {
                [1] = "200021:Confident01",
                },
            ["GUID"] = "194CD546",
            ["NextOptions"] = {
                [1] = 10106337,
                [2] = 10106338,
                },
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{200021},AnimationId{\"DisagreeHead\"},Duration{1}},\
PlayAnimation{_delay{1.5},ActorId{200021},AnimationId{\"Talk03_Start\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 200021,
            ["TalkActionId"] = {
                [1] = "100001:Talk02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101063/194CD546",
            },
        [10106337] = {
            ["Content"] = "哦，我知道了。办张假的对吧。",
            ["ContentFR"] = "<I>Oh, je vois... Tu parles d’un faux, pas vrai ?</>",
            ["DialogueId"] = 10106337,
            ["GUID"] = "10106337",
            ["NextDialogue"] = 10106339,
            },
        [10106338] = {
            ["Content"] = "那我自己去找人办一份不就行了？",
            ["ContentFR"] = "<I>Alors je peux très bien trouver quelqu’un d’autre pour m’en fabriquer un.</>",
            ["DialogueId"] = 10106338,
            ["GUID"] = "10106338",
            ["NextDialogue"] = 10106339,
            },
        [10106339] = {
            ["Camera"] = "123.935547,5.261719,672.55127,0.001522,-78.772713,-167.208313,25.0,326.395905,false,DoNotOverride,2.217901",
            ["CameraBlendCurve"] = "easeInQuad",
            ["Content"] = "在这座城市，有些东西是银币和铜币买不到的——尤其是那些可能会引火烧身的东西。能买到它的，是人与人之间那一根“看不见的线”。",
            ["ContentFR"] = "Dans cette ville, il est des choses que l’argent n’achète pas, surtout celles qui peuvent te brûler les doigts. Ce qui permet de les obtenir, c’est ce fil invisible qu’on appelle les connexions entre les gens.",
            ["DialogueId"] = 10106339,
            ["FacialId"] = {
                [1] = "200021:None",
                [2] = "100001:None",
                },
            ["FinalCamera"] = "140.303955,8.964844,757.100586,0.001522,-78.772713,-167.208313,25.0,326.395905,false,DoNotOverride,2.217901",
            ["GUID"] = "194CD570",
            ["NextDialogue"] = 10106340,
            ["Scripts"] = "PARA{\
CameraMoveTo{_delay{4.1},TargetPosition{\"-39.0,7.46582,5875.651855,0.000019,-90.0,0.000027,20.0,326.395905,false,DoNotOverride,2.217901\"},duration{0}},\
CameraMoveTo{_delay{4.2},TargetPosition{\"-39.0,7.46582,6107.878906,0.000248,-90.0,-0.000109,20.0,326.395905,false,DoNotOverride,2.217901\"},blend{\"easeOutQuad\"},duration{4}}\
}",
            ["SpeakNpcId"] = 200021,
            ["ToFinalCameraBlendTime"] = 6,
            ["VoiceName"] = "voice/$Locale$/story/1002/101063/194CD570",
            },
        [10106340] = {
            ["Camera"] = "45.434082,-29.058594,162.999512,0.000143,-4.198688,-134.496765,35.000008,88.220627,false,Manual,3.628265",
            ["Content"] = "（在海伯利亚……没有通行证的确举步维艰。）",
            ["ContentFR"] = "<I>En Hyperborea... sans permis de circulation, impossible d’avancer.</>",
            ["DialogueId"] = 10106340,
            ["DisableMouth"] = 1,
            ["ExStoryInfo"] = "Player",
            ["FacialId"] = {
                [1] = "100001:Think01",
                },
            ["GUID"] = "194CD59A",
            ["NextDialogue"] = 10106341,
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Think_Start",
                [2] = "200021:Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101063/194CD59A",
            },
        [10106341] = {
            ["Camera"] = "45.434082,-29.058594,162.999512,0.000143,-4.198688,-134.496765,35.000008,88.220627,false,Manual,3.628265",
            ["CameraBlendCurve"] = "easeOutQuad",
            ["Content"] = "这个交易，你想要我做什么？群星绮晶让给你？",
            ["ContentFR"] = "Cet échange, qu’est-ce que tu veux en retour ? Que je t’offre l’Éclat stellaire ?",
            ["DialogueId"] = 10106341,
            ["ExStoryInfo"] = "Player",
            ["FinalCamera"] = "66.709229,-7.40918,165.228027,0.000144,-5.398807,-135.095779,35.000008,114.245468,false,Manual,3.628265",
            ["GUID"] = "194CD59B",
            ["NextDialogue"] = 10106342,
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{100001},AnimationId{\"Think_End\"},Duration{1}},\
PlayAnimation{ActorId{100001},AnimationId{\"Explain01_Start\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 100001,
            ["ToFinalCameraBlendTime"] = 2.5,
            ["VoiceName"] = "voice/$Locale$/story/1002/101063/194CD59B",
            },
        [10106342] = {
            ["Camera"] = "16.160889,-237.400391,148.03125,0.000132,1.599944,92.399918,35.0,306.557922,false,Manual,2.071165",
            ["Content"] = "不，绮晶当然是你的，用它和恩里克换银币就是。我想要你做的，是想办法进旅馆去，看看里面到底有什么。",
            ["ContentFR"] = "Non. L’éclat est à toi, tu peux toujours l’échanger contre des pièces d’argent auprès d’Henrik. Ce que je veux... c’est que tu trouves un moyen d’entrer dans la Maison d’Hypnos, et que tu découvres ce qu’ils cachent.",
            ["DialogueId"] = 10106342,
            ["FacialId"] = {
                [1] = "200021:Confident01",
                },
            ["GUID"] = "194CD59C",
            ["NextDialogue"] = 10106343,
            ["Scripts"] = "SEQ{\
PlayAnimation{_delay{1},ActorId{200021},AnimationId{\"Explain01_Start\"},Duration{1}},\
PlayAnimation{ActorId{100001},AnimationId{\"Explain01_End\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 200021,
            ["TalkActionId"] = {
                [1] = "200021:DisagreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101063/194CD59C",
            },
        [10106343] = {
            ["Camera"] = "70.744141,-0.792969,168.705566,0.000141,-7.000274,-136.200241,35.0,121.432114,false,Manual,2.071165",
            ["Content"] = "你是外乡人，他对你想必不会太警惕，没准真能查出来点东西。",
            ["ContentFR"] = "Tu n’es pas d’ici. Il ne se méfiera pas de toi. Peut-être que tu réussiras à découvrir quelque chose.",
            ["DialogueId"] = 10106343,
            ["FinalCamera"] = "65.674561,-5.65332,167.844727,0.000145,-7.000274,-136.200256,35.000008,121.432114,false,Manual,2.071165",
            ["GUID"] = "194CD59D",
            ["NextDialogue"] = 10106344,
            ["SpeakNpcId"] = 200021,
            ["TalkActionId"] = {
                [1] = "200021:Explain01_End",
                },
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/1002/101063/194CD59D",
            },
        [10106344] = {
            ["Content"] = "这倒是简单。换通行证……也不算亏。",
            ["ContentFR"] = "Ça me paraît simple. Troquer un peu d’espionnage contre un permis de circulation... marché conclu.",
            ["DialogueId"] = 10106344,
            ["ExStoryInfo"] = "Player",
            ["FacialId"] = {
                [1] = "100001:Confident02",
                },
            ["GUID"] = "194CD59E",
            ["NextDialogue"] = 10106345,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:AgreeHead",
                [2] = "100001:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101063/194CD59E",
            },
        [10106345] = {
            ["Camera"] = "766.177124,137.326172,160.495605,0.000145,-2.799988,-174.8013,30.0,821.970154,false,Manual,1.2",
            ["Content"] = "嗯，虽说简单，但还是要提防着些。明天中午十二点，我在这里等你消息。",
            ["ContentFR"] = "Simple, oui. Mais sois {性别:prudent|prudente}. Demain midi, reviens ici avec ce que tu auras appris.",
            ["DialogueId"] = 10106345,
            ["FinalCamera"] = "843.248169,144.335938,164.278809,0.000145,-2.799988,-174.8013,30.0,821.970154,false,Manual,1.2",
            ["GUID"] = "194CD59F",
            ["Scripts"] = "PARA{\
PlayAnimation{ActorId{200021},AnimationId{\"AgreeHead\"},Duration{2}},\
PlayAnimation{_delay{4},ActorId{200021},AnimationId{\"Talk02_Start\"},Duration{1}}}",
            ["SpeakNpcId"] = 200021,
            ["TalkActionId"] = {
                [1] = "100001:Think_End",
                },
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/1002/101063/194CD59F",
            },
        [10106346] = {
            ["Content"] = "如果耽误了正事，或者被旁人看出来什么……你知道后果。",
            ["ContentFR"] = "Si tu compromets nos affaires, ou si quelqu’un commence à se poser des questions... tu sais ce que ça entraînerait.",
            ["DialogueId"] = 10106346,
            ["GUID"] = "194CD3A3",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10106346.T_Story_Recall_10106346'",
            ["NextDialogue"] = 10130001,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 200005,
            ["VoiceName"] = "voice/$Locale$/story/1002/101058/194C8021",
            },
        [10106401] = {
            ["Content"] = "早点休息吧。明天中午十二点，我在这里等你消息。",
            ["ContentFR"] = "Repose-toi. Demain, à midi, je t’attends ici.",
            ["DialogueId"] = 10106401,
            ["GUID"] = "194CE16A",
            ["SpeakNpcId"] = 200021,
            ["VoiceName"] = "voice/$Locale$/story/1002/101064/194CE16A",
            },
        [10106501] = {
            ["Camera"] = "1342.068604,-1311.530273,220.426514,-0.001037,-2.0155,135.017212,35.000008,130.587296,false,DoNotOverride,1.200001",
            ["Content"] = "贝蕾……今天发生了很多、很多事。",
            ["ContentFR"] = "Berry... tant de choses se sont passées aujourd’hui.",
            ["DialogueId"] = 10106501,
            ["ExStoryInfo"] = "Player",
            ["FacialId"] = {
                [1] = "100001:Sad01",
                },
            ["FinalCamera"] = "1296.370605,-1357.253906,220.427002,-0.001037,-2.0155,135.017212,35.000008,130.587296,false,DoNotOverride,1.200001",
