            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "200006:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101070/194D4650",
            },
        [10107018] = {
            ["Camera"] = "-239.527344,-76.267822,140.667969,0.000016,-1.799352,15.204823,35.000008,357.107239,false,Manual,4.7",
            ["Content"] = "昨晚恩里克先生的脸色很差。他没有凶你吧？",
            ["ContentFR"] = "Hier soir, Monsieur Henrik avait l’air très contrarié. Il ne t’a pas mal parlé, au moins ?",
            ["DialogueId"] = 10107018,
            ["ExStoryInfo"] = "Player",
            ["FacialId"] = {
                [1] = "100001:Angry01",
                [2] = "200006:None",
                },
            ["FinalCamera"] = "-258.751953,-81.134766,141.289062,0.000016,-1.799365,14.20413,35.000008,357.107239,false,Manual,4.773073",
            ["GUID"] = "194D467A",
            ["NextDialogue"] = 10107019,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Explain02_Start",
                },
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/1002/101070/194D467A",
            },
        [10107019] = {
            ["Camera"] = "98.041016,134.36499,152.681641,0.000016,-2.19958,-125.604164,55.000008,235.416611,false,Manual,10.570968",
            ["Content"] = "没有没有。恩里克叔叔只是有些……不善言辞。毕竟他大多数时间都一个人闷在办公室里搞他的研究，很少和别人说话……",
            ["ContentFR"] = "Non, non, pas du tout. Monsieur Henrik est seulement un peu... maladroit avec les mots. Il passe presque tout son temps enfermé dans son bureau, plongé dans ses recherches... il parle rarement aux autres.",
            ["DialogueId"] = 10107019,
            ["FinalCamera"] = "114.261719,157.031006,153.753906,0.000001,-2.199615,-125.60421,55.0,235.416611,false,Manual,4.291738",
            ["GUID"] = "194D46A4",
            ["NextDialogue"] = 10107020,
            ["Scripts"] = "PARA{\
PlayAnimation{_delay{1.5},ActorId{200006},AnimationId{\"DisagreeHead\"},Duration{0.1}},\
PlayAnimation{_delay{4.5},ActorId{200006},AnimationId{\"Talk02_Start\"},Duration{0.1}}\
}",
            ["SpeakNpcId"] = 200006,
            ["TalkActionId"] = {
                [1] = "100001:Explain02_End",
                },
            ["ToFinalCameraBlendTime"] = 15,
            ["VoiceName"] = "voice/$Locale$/story/1002/101070/194D46A4",
            },
        [10107020] = {
