        [10107101] = {
            ["Camera"] = "-123.40625,-31.072693,50.783203,0.000002,5.499996,-2.799134,20.0,536.5802,false,Manual,1.2",
            ["Content"] = "（办公室的门已经有些年头，但光洁锃亮，一丝不染。门把手拧下去纹丝不动。显然，它被反锁了。）",
            ["ContentFR"] = "<I>La porte du bureau a déjà quelques années, mais elle est impeccable, luisante, sans une trace de poussière. Le bouton ne bouge pas d’un poil. Évidemment, elle est verrouillée de l’intérieur.</>",
            ["DialogueId"] = 10107101,
            ["DisableMouth"] = 1,
            ["FinalCamera"] = "-123.40625,-31.072693,60.292969,0.000002,7.500012,-2.799135,20.0,536.5802,false,Manual,1.2",
            ["GUID"] = "194D546B",
            ["LookAt"] = {
