                },
            ["ToFinalCameraBlendTime"] = 6,
            },
        [10107102] = {
            ["Camera"] = "-81.755859,184.659851,161.341797,0.000044,-6.200008,-36.196159,40.0,349.444244,false,Manual,5.0",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "……不要碰那扇门。",
            ["ContentFR"] = "... Ne touche pas à cette porte.",
            ["DialogueId"] = 10107102,
            ["FacialId"] = {
