        [10107111] = {
            ["Content"] = "削苹果时苹果皮不能断掉。从盥洗室走到办公室的步数必须是偶数。每个月一定会在20日晚8点出门，且离开后一定要再次返回确认门锁三次。",
            ["ContentFR"] = "Quand il épluche une pomme, la peau ne doit pas se casser. Le nombre de pas entre la salle de bain et le bureau doit être pair. Chaque mois, il sort exactement à vingt heures le 20 du mois, puis revient pour vérifier trois fois la porte.",
            ["DialogueId"] = 10107111,
            ["GUID"] = "194D55E6",
            ["NextDialogue"] = 10107112,
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{200019},AnimationId{\"Think_End\"},Duration{1.5}},\
PlayAnimation{ActorId{200019},AnimationId{\"Talk02_Start\"},Duration{2.3}},\
PlayAnimation{ActorId{200019},AnimationId{\"Talk02_End\"},Duration{0.5}},\
PlayAnimation{ActorId{200019},AnimationId{\"Explain01_Start\"},Duration{3.5}},\
PlayAnimation{ActorId{200019},AnimationId{\"Explain01_End\"},Duration{0.5}},\
PlayAnimation{ActorId{200019},AnimationId{\"Talk01_Start\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 200019,
            ["VoiceName"] = "voice/$Locale$/story/1002/101071/194D55E6",
            },
        [10107112] = {
            ["Content"] = "……但我想，这些习惯太私人了，对你来说可能没有什么学习的价值……",
            ["ContentFR"] = "... Mais je pense que ces habitudes sont trop personnelles, elles n’ont probablement pas beaucoup de valeur pour toi...",
            ["DialogueId"] = 10107112,
