        [10107812] = {
            ["Camera"] = "542.043457,-395.053711,99.608398,0.0,0.0,139.199432,30.0,357.262421,false,Manual,3.0",
            ["CameraBlendCurve"] = "easeOutQuad",
            ["Content"] = "我跟那里的住客套了话。恩里克有一个特别的习惯，他一定会在每个月20日晚8点出门。",
            ["ContentFR"] = "En discutant avec les pensionnaires, j’ai appris qu’il a une habitude particulière : chaque 20 du mois, à vingt heures, il sort du manoir.",
            ["DialogueId"] = 10107812,
            ["ExStoryInfo"] = "Player",
            ["FinalCamera"] = "559.420654,-374.921875,99.608398,0.0,0.0,139.199432,30.0,616.33313,false,Manual,3.0",
            ["GUID"] = "194DC8E8",
            ["NextDialogue"] = 10107813,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Explain01_Start",
                },
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/1002/101078/194DC8E8",
            },
        [10107813] = {
            ["Content"] = "很好。也就是说，这是我们调查他的好机会。得想办法跟踪他……或者潜入修普诺斯之家……",
            ["ContentFR"] = "Parfait. Autrement dit, c’est notre fenêtre d’action pour l’observer... ou nous introduire dans la Maison d’Hypnos.",
            ["DialogueId"] = 10107813,
            ["GUID"] = "194DC912",
            ["NextDialogue"] = 10107822,
            ["Scripts"] = "SEQ{\
PlayAnimation{_delay{2},ActorId{200021},AnimationId{\"Think_Start\"},Duration{1}},\
PlayAnimation{_delay{2},ActorId{200021},AnimationId{\"Think_End\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 200021,
            ["TalkActionId"] = {
                [1] = "100001:Explain01_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101078/194DC912",
            },
        [10107814] = {
            ["Camera"] = "14.019775,37.094727,157.077148,0.000169,-2.399801,-97.506111,50.0,127.094246,false,Manual,5.0",
            ["Content"] = "……所以，我们的计划已经很明确了。本月20日，趁恩里克出门，想办法从烟囱潜入上锁的办公室。那个房间只有恩里克能进，所以不会有人发现我们。",
            ["ContentFR"] = "... Bien. Alors le plan est clair : le 20 de ce mois, pendant qu’Henrik sera dehors, nous tenterons de pénétrer dans son bureau verrouillé par la cheminée. Personne n’y a accès à part lui, nous ne serons pas découverts.",
            ["DialogueId"] = 10107814,
            ["FinalCamera"] = "14.019775,37.094727,157.077148,0.00017,-2.599795,-98.306206,55.0,127.094246,false,Manual,5.0",
            ["GUID"] = "194DC93C",
            ["NextDialogue"] = 10107815,
            ["SpeakNpcId"] = 200021,
            ["TalkActionId"] = {
                [1] = "200021:Explain01_Start",
                },
            ["ToFinalCameraBlendTime"] = 14,
            ["VoiceName"] = "voice/$Locale$/story/1002/101078/194DC93C",
            },
        [10107815] = {
            ["Camera"] = "35.024658,132.529297,133.211426,0.000002,3.599892,-103.6017,50.0,237.958099,false,Manual,8.0",
            ["CameraBlendCurve"] = "easeOutQuad",
            ["Content"] = "{nickname}，你的脑筋蛮灵光嘛，我都想和你长期搭伙了。说起来，既然你们能打败矿坑那怪物，你本人应该还是挺擅长体术的吧？",
            ["ContentFR"] = "Tu as l’esprit affûté, {nickname}. J’en viendrais presque à envisager un partenariat à long terme. D’ailleurs, puisque vous avez réussi à éliminer le monstre dans la fosse, tu dois avoir de solides compétences au combat rapproché, non ?",
            ["DialogueId"] = 10107815,
            ["ExStoryInfo"] = "Player",
            ["FacialId"] = {
                [1] = "200021:Smile01",
                },
            ["FinalCamera"] = "41.333984,130.958008,133.211426,0.000002,3.599892,-105.001938,50.0,237.958099,false,Manual,8.0",
            ["GUID"] = "194DC966",
            ["NextDialogue"] = 10107816,
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{200021},AnimationId{\"Explain01_End\"},Duration{1}},\
PlayAnimation{_delay{2},ActorId{200021},AnimationId{\"Explain01_Start\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 200021,
            ["ToFinalCameraBlendTime"] = 12,
            ["VoiceName"] = "voice/$Locale$/story/1002/101078/194DC966",
            },
        [10107816] = {
            ["Camera"] = "40.309082,-165.490234,149.889648,0.000082,-6.199803,104.007965,35.000008,251.467529,false,Manual,8.0",
            ["Content"] = "过去体格并不算好，但是最近开始有所长进了。",
            ["ContentFR"] = "J’étais plutôt faible autrefois... mais j’ai fait des progrès récemment.",
            ["DialogueId"] = 10107816,
            ["ExStoryInfo"] = "Player",
            ["FacialId"] = {
                [1] = "100001:Ahaha02",
                },
            ["GUID"] = "194DC990",
            ["NextDialogue"] = 10107817,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Talk03_Start",
                [2] = "200021:Explain01_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101078/194DC990",
            },
        [10107817] = {
            ["Camera"] = "66.280518,143.457031,91.727539,0.000016,11.199843,-111.197601,35.000008,244.047409,false,Manual,5.0",
            ["Content"] = "好。那么接下来的几天，我也教你一些格斗的技巧吧——有备无患。",
            ["ContentFR"] = "Bien. Dans les jours qui viennent, je t’enseignerai quelques techniques de combat, mieux vaut être préparé.",
            ["DialogueId"] = 10107817,
            ["FacialId"] = {
                [1] = "200021:Confident01",
                },
            ["FinalCamera"] = "71.202881,141.490234,91.727539,0.000025,10.999807,-112.396538,35.000008,244.047409,false,Manual,5.0",
            ["GUID"] = "194DC9BA",
