            },
        [10107818] = {
            ["Camera"] = "132.594971,-312.742188,219.181152,0.00003,-16.799854,113.80175,35.000008,268.59845,false,DoNotOverride,3.0",
            ["Content"] = "就从明天开始吧。",
            ["ContentFR"] = "Alors on commencera dès demain.",
