            },
        [10107820] = {
            ["Camera"] = "-9.021729,-26.742188,128.609863,0.000102,5.600222,80.398033,35.0,95.583733,false,Manual,5.0",
            ["Content"] = "（……时候还早，或许我可以看看有没有什么能接的委托……）",
            ["ContentFR"] = "<I>... Il est encore tôt. Je pourrais peut-être voir s’il y a des missions disponibles aux Asphodèles...</>",
            ["DialogueId"] = 10107820,
            ["DisableMouth"] = 1,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "194DD782",
            ["LookAt"] = {
