            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101079/194DD782",
            },
        [10107821] = {
            ["Content"] = "（……还有，赛琪看起来有些孤独。有机会的话，离开冰湖城之前，也去陪她说说话吧。）",
            ["ContentFR"] = "<I>Et puis, Psyche avait l’air un peu seule. Avant de quitter Givrelac, je devrais trouver un moment pour lui tenir compagnie.</>",
            ["DialogueId"] = 10107821,
