            },
        [10108010] = {
            ["Camera"] = "-88.675293,985.40918,-40.296875,0.000035,6.0,-81.79319,50.0,1142.016846,false,Manual,5.0",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "如果真的得到了{性别：他|她}……也就是和鸣之力的宿体，您打算如何处置？",
            ["DialogueId"] = 10108010,
            ["ExStoryInfo"] = "Player",
            ["FinalCamera"] = "-88.675293,985.40918,-28.716797,0.000035,3.999765,-81.793198,50.0,1142.016846,false,Manual,5.0",
            ["GUID"] = "194DE964",
            ["NextDialogue"] = 10108011,
            ["SpeakNpcId"] = 100006,
            ["TalkActionId"] = {
                [1] = "100005:Explain02_End",
                },
            ["ToFinalCameraBlendTime"] = 4.5,
            ["VoiceName"] = "voice/$Locale$/story/1002/101080/194DE964",
            },
        [10108011] = {
            ["Camera"] = "-80.04834,-432.792969,122.105469,0.000063,-7.999989,81.205322,50.0,772.028992,false,Manual,5.5",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "据我所知，与零号不同，海伯利亚并不能有效利用这一力量——甚至可能会起到相反的作用……毕竟，理想状态下，和鸣之力可以对一切“骸”施加干预……",
            ["DialogueId"] = 10108011,
            ["FinalCamera"] = "-80.04834,-432.792969,139.992188,0.000063,-9.999997,81.205353,50.0,772.028992,false,Manual,5.5",
