            },
        [10108013] = {
            ["Camera"] = "-1487.203369,2515.675293,1424.984375,0.00003,-29.70046,-53.591125,35.0,198.622971,false,DoNotOverride,3.0",
            ["Content"] = "是关于您让我调查的另一件事。",
            ["ContentFR"] = "C’est au sujet de l’autre affaire que vous m’aviez confiée.",
            ["DialogueId"] = 10108013,
            ["FinalCamera"] = "-1590.206055,2655.341553,1523.966797,0.00003,-29.70046,-53.591125,35.0,198.622971,false,DoNotOverride,3.0",
            ["GUID"] = "194DE9E2",
            ["NextDialogue"] = 10108014,
            ["SpeakNpcId"] = 100006,
            ["TalkActionId"] = {
                [1] = "100005:Talk03_End",
                },
            ["ToFinalCameraBlendTime"] = 15,
            ["VoiceName"] = "voice/$Locale$/story/1002/101080/194DE9E2",
            },
        [10108014] = {
            ["Content"] = "在搜寻过程中，我在附近的荒岛遇到了乘船逃亡至此的村民——然后，我们发现了一个有趣的“小东西”。",
            ["ContentFR"] = "Pendant les recherches, j’ai croisé sur une île déserte des villageois réfugiés là par bateau... et nous avons découvert une petite chose très intéressante.",
            ["DialogueId"] = 10108014,
            ["GUID"] = "194DEA0C",
            ["NextDialogue"] = 10108015,
            ["Scripts"] = "SEQ{\
CameraMoveTo{_delay{6},TargetPosition{\"-88.142578,691.203125,6.554688,0.000085,-16.999535,59.401443,35.000008,210.882507,false,DoNotOverride,6.0\"},duration{0}},\
CameraMoveTo{TargetPosition{\"-89.819336,688.370605,7.554688,0.000085,-16.999535,59.401443,35.000008,210.882507,false,DoNotOverride,6.0\"},duration{6}}\
}",
            ["SpeakNpcId"] = 100006,
            ["TalkActionId"] = {
                [1] = "100006:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101080/194DEA0C",
            },
        [10108015] = {
            ["Content"] = "就像是您正品尝着司空见惯的浓汤，却发现刚放进去的汤匙突然褪去漂亮的银，变成了可怖的漆黑——",
            ["ContentFR"] = "Comme si vous goûtiez une soupe bien ordinaire, et qu’en y trempant votre cuillère, son bel argent brillant se changeait soudain en un noir affreux...",
            ["DialogueId"] = 10108015,
            ["FacialId"] = {
                [1] = "100006:Shock01",
                },
            ["GUID"] = "194DEA36",
            ["NextDialogue"] = 10108016,
            ["Scripts"] = "PARA{\
SEQ{\
PlayAnimation{ActorId{100006},AnimationId{\"Shock_Start\"},Duration{1}},\
PlayAnimation{_delay{6},ActorId{100005},AnimationId{\"Think_End\"},Duration{1}}\
},\
CameraMoveTo{_delay{5.5},TargetPosition{\"-136.59082,629.249023,-7.123047,0.000071,-11.799984,57.1945,30.0,195.345673,false,Manual,3.030511\"},duration{0}}\
}",
            ["SpeakNpcId"] = 100006,
            ["TalkActionId"] = {
                [1] = "100005:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101080/194DEA36",
            },
        [10108016] = {
            ["Camera"] = "-90.080566,-82.443359,112.785156,0.000359,8.403502,-64.220345,35.000008,161.292053,false,Manual,6.0",
            ["Content"] = "挑重点说，省去那些花里胡哨的。",
            ["ContentFR"] = "Abrège. Épargne-moi tes détours.",
            ["DialogueId"] = 10108016,
            ["FacialId"] = {
                [1] = "100005:Angry01",
                },
            ["GUID"] = "194DEA60",
            ["NextDialogue"] = 10108017,
            ["SpeakNpcId"] = 100005,
            ["TalkActionId"] = {
                [1] = "100005:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101080/194DEA60",
            },
        [10108017] = {
            ["Camera"] = "-136.59082,629.249023,-7.123047,0.000071,-11.799984,57.1945,30.0,195.345673,false,Manual,3.030511",
            ["Content"] = "啊……是、是。那个有趣的小东西，便是<H>“时间差”</>。",
            ["ContentFR"] = "Ah... oui, Commandante. Cette petite curiosité, c’était un <H>décalage temporel</>.",
            ["DialogueId"] = 10108017,
            ["FinalCamera"] = "-128.663086,624.128906,1.964844,0.000055,-11.999959,57.393639,30.000002,195.345673,false,Manual,3.030511",
            ["GUID"] = "194DEA8A",
            ["NextDialogue"] = 10108018,
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{100006},AnimationId{\"Shock_End\"},Duration{1}},\
PlayFacial{_delay{1},ActorId{100006},FacialId{\"None\"}},\
PlayAnimation{_delay{4},ActorId{100006},AnimationId{\"Explain02_Start\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 100006,
            ["TalkActionId"] = {
                [1] = "100005:Explain01_End",
                },
            ["ToFinalCameraBlendTime"] = 1,
            ["VoiceName"] = "voice/$Locale$/story/1002/101080/194DEA8A",
            },
        [10108018] = {
            ["Camera"] = "-432.941406,1929.711914,30.550781,0.000332,-3.300006,-73.81044,30.0,174.408691,false,DoNotOverride,3.236185",
            ["Content"] = "村民们告诉我，净界岛的秽兽此前一直住在山里，并没有表现出强烈的攻击性；但在我们抵达的<H>两天前</>，却突然发疯般地攻击村民。",
            ["ContentFR"] = "Les villageois m’ont dit que les Souillés de l’Île du Purgatoire vivaient d’ordinaire dans les montagnes, sans grande agressivité. Mais <H>deux jours avant</> notre arrivée, ils se sont mis à attaquer les habitants comme des bêtes enragées.",
            ["DialogueId"] = 10108018,
            ["FinalCamera"] = "-432.941406,1929.711914,67.210938,0.000332,-3.300019,-73.810356,30.0,174.408691,false,DoNotOverride,3.236185",
            ["GUID"] = "194DEAB4",
            ["NextDialogue"] = 10108019,
            ["SpeakNpcId"] = 100006,
            ["TalkActionId"] = {
                [1] = "100006:Explain02_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1002/101080/194DEAB4",
            },
        [10108019] = {
            ["Camera"] = "-44.418457,-154.999023,169.058594,0.000032,-19.399868,-78.186974,30.000002,78.537529,false,Manual,4.0",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "“两天前”……",
            ["ContentFR"] = "Deux jours avant notre arrivée...",
            ["DialogueId"] = 10108019,
            ["FinalCamera"] = "-40.415039,-174.143066,162.169922,0.00003,-19.399921,-78.187599,30.000002,58.681007,false,Manual,4.0",
            ["GUID"] = "194DEADE",
            ["NextDialogue"] = 10108020,
            ["SpeakNpcId"] = 100005,
            ["TalkActionId"] = {
                [1] = "100005:Think_Start",
                },
            ["ToFinalCameraBlendTime"] = 1.5,
            ["VoiceName"] = "voice/$Locale$/story/1002/101080/194DEADE",
            },
        [10108020] = {
            ["Camera"] = "-65.008301,620.166992,-9.789062,0.00008,-5.799861,76.39901,50.000011,165.188309,false,Manual,2.775071",
            ["Content"] = "……看来您已经猜到了。这太巧合了，不是吗？因为计划临时有变，我们刚好比原定的登岛时期迟了两天。",
            ["ContentFR"] = "... Vous l’avez déjà compris, n’est-ce pas ? C’est trop beau pour être une coïncidence. À cause d’un contretemps, nous avons accosté justement avec deux jours de retard sur le plan initial.",
            ["DialogueId"] = 10108020,
            ["GUID"] = "194DEB08",
            ["NextDialogue"] = 10108021,
            ["SpeakNpcId"] = 100006,
            ["TalkActionId"] = {
                [1] = "100005:Think_End",
                [2] = "100006:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101080/194DEB08",
            },
        [10108021] = {
            ["Content"] = "而有能力操纵秽兽行刺的，只有<W>神弃者同盟</>。",
            ["ContentFR"] = "Et les seuls capables de manipuler des Souillés pour les lancer dans une attaque... ce sont bien les <W>Déchus</>.",
            ["DialogueId"] = 10108021,
            ["GUID"] = "194DEB32",
            ["NextDialogue"] = 10108022,
            ["RelatedWikiId"] = {
                [1] = 101004,
                },
            ["Scripts"] = "PlayAnimation{delay{4},ActorId{100006},AnimationId{\"Think_End\"},Duration{1}}",
            ["SpeakNpcId"] = 100006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101080/194DEB32",
            },
        [10108022] = {
            ["Camera"] = "-94.642578,-318.927246,96.927734,8.007288,17.396826,65.810257,20.000008,110.446434,false,Manual,6.0",
            ["Content"] = "……无论是不是同盟，十三军团都混进了不该有的东西。",
            ["ContentFR"] = "... Qu’ils soient ou non impliqués, la XIIIᵉ Légion a laissé s’infiltrer ce qui n’aurait jamais dû s’y trouver.",
            ["DialogueId"] = 10108022,
            ["FinalCamera"] = "-100.751465,-332.528809,92.259766,8.007426,17.396826,65.810616,20.000008,110.446434,false,Manual,6.0",
            ["GUID"] = "194DEB5C",
            ["NextDialogue"] = 10108023,
            ["Scripts"] = "TurnTo{_delay{1},TurnToDescription{\"100005:p(-180)\"}}",
            ["SpeakNpcId"] = 100005,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1002/101080/194DEB5C",
            },
        [10108023] = {
            ["Content"] = "这么多年过去，虫子们又开始不安分起来……",
            ["ContentFR"] = "Après toutes ces années, ces vermines recommencent à s’agiter...",
            ["DialogueId"] = 10108023,
            ["GUID"] = "194DEB86",
            ["LookAt"] = {
                [1] = "100005:n(100005)",
                },
            ["NextDialogue"] = 10108024,
            ["SpeakNpcId"] = 100005,
            ["TalkActionId"] = {
                [1] = "100005:Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101080/194DEB86",
            },
        [10108024] = {
            ["Camera"] = "-267.375,-231.39209,11.626953,3.599992,2.500006,0.199989,35.000008,198.622971,false,Manual,3.0",
            ["Content"] = "该彻底踩碎了。",
            ["ContentFR"] = "Il est temps de les écraser pour de bon.",
            ["DialogueId"] = 10108024,
            ["FinalCamera"] = "-324.33252,-231.588867,9.132812,3.599993,2.500006,0.199989,35.000008,198.622971,false,Manual,3.0",
            ["GUID"] = "194DEBB0",
            ["Scripts"] = "MoveTo{_delay{3},ActorId{100005},TargetPoint{\"P101080Xibi1\"},MoveSpeed{80},Visibility{\"Show\"}}",
            ["SpeakNpcId"] = 100005,
            ["TalkActionId"] = {
                [1] = "100005:Talk03_End",
                },
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/1002/101080/194DEBB0",
            },
        [10108101] = {
            ["Content"] = "如猎犬终于走出蛰伏的巢穴，十三军团在缄默中展开了漆黑的狩猎。",
            ["ContentFR"] = "Comme un prédateur sortant enfin de sa tanière, la XIIIᵉ Légion lança dans le silence sa chasse obscure.",
            ["DialogueId"] = 10108101,
            ["Duration"] = 4,
            ["GUID"] = "194DF852",
            ["NextDialogue"] = 10108102,
            ["Scripts"] = "PlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/mute\"}}",
            },
        [10108102] = {
            ["Content"] = "而在远方的冰湖城，",
            ["ContentFR"] = "Pendant ce temps, à la lointaine Givrelac,",
            ["DialogueId"] = 10108102,
            ["Duration"] = 4,
            ["GUID"] = "194DF87C",
            ["NextDialogue"] = 10108103,
            },
        [10108103] = {
            ["Content"] = "一位新手也在慢慢熟悉如何成为可靠的猎人。",
            ["ContentFR"] = "{性别:un novice|une novice} apprenait doucement ce que signifie devenir {性别:un chasseur digne de confiance|une chasseuse digne de confiance}.",
            ["DialogueId"] = 10108103,
            ["Duration"] = 4,
            ["GUID"] = "194DF8A6",
            ["Scripts"] = "PlayOrStopBGM{PlayType{\"Stop\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/mute\"}}",
            },
        [10108201] = {
            ["Content"] = "我得先调试一下“那玩意儿”。时候还早，你先随便拿路边的野兽练练手吧。小矮子还在城里帮我们放哨，别走太远。",
            ["ContentFR"] = "Je dois d’abord ajuster \"cette chose\". Il est encore tôt, alors profites-en pour t’entraîner sur les Souillés autour. Le Petit Champi est toujours en ville pour surveiller les alentours, ne t’éloigne pas trop.",
            ["DialogueId"] = 10108201,
            ["GUID"] = "194E08BA",
            ["LookAt"] = {
                [1] = "200021:n(0)",
                },
            ["NextDialogue"] = 10108202,
            ["SpeakNpcId"] = 200021,
            ["TalkActionId"] = {
                [1] = "200021:Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101082/194E08BA",
            },
        [10108202] = {
            ["Content"] = "我提前布置了些陷阱。别看是废品做的，可好使了。",
            ["ContentFR"] = "J’ai déjà installé quelques pièges. Même si ça a l’air de bric-à-brac, ça fonctionne plutôt bien.",
            ["DialogueId"] = 10108202,
            ["GUID"] = "194E08BB",
            ["NextDialogue"] = 10108203,
            ["SpeakNpcId"] = 200021,
            ["TalkActionId"] = {
                [1] = "200021:Talk01_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101082/194E08BB",
            },
        [10108203] = {
            ["Content"] = "不过你省着点用，毕竟材料不太结实，一不留神踩碎了也是有可能的，哈哈……",
            ["ContentFR"] = "Mais fais attention à ne pas trop les utiliser, le matériel n’est pas très solide, il pourrait se casser si tu marches dessus... Haha.",
            ["DialogueId"] = 10108203,
            ["GUID"] = "194E08BC",
            ["SpeakNpcId"] = 200021,
            ["TalkActionId"] = {
                [1] = "200021:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101082/194E08BC",
            },
        [10108301] = {
            ["Camera"] = "820.816406,636.059082,465.740234,0.000086,-21.70013,-141.791962,50.0,437.971283,false,DoNotOverride,2.0",
            ["CameraBlendCurve"] = "easeOutQuad",
            ["Content"] = "呼……呼……",
            ["ContentFR"] = "Haa... haa...",
            ["DialogueId"] = 10108301,
            ["ExStoryInfo"] = "Player",
            ["FinalCamera"] = "854.382812,662.485352,482.745117,0.000086,-21.70013,-141.791962,50.0,437.971283,false,DoNotOverride,2.0",
            ["GUID"] = "194E1922",
            ["LookAt"] = {
                [1] = "200021:n(100001)",
                },
            ["NextDialogue"] = 10108302,
            ["Scripts"] = "PlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt01/0033_story_humour\"}}",
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Sigh_Start",
                },
            ["ToFinalCameraBlendTime"] = 4,
            ["VoiceName"] = "voice/$Locale$/story/1002/101083/194E1922",
            },
        [10108302] = {
            ["Camera"] = "243.050781,-58.478027,50.348633,0.000132,11.999521,161.197205,35.0,321.520721,false,Manual,4.0",
            ["CameraBlendCurve"] = "easeOutQuad",
            ["Content"] = "不错，这几天进步很快！不过，还有提升的空间。",
            ["ContentFR"] = "Pas mal ! Tu progresses vite ces derniers jours ! Mais il y a encore du potentiel à exploiter.",
            ["DialogueId"] = 10108302,
            ["FacialId"] = {
                [1] = "200021:Smile01",
                },
            ["FinalCamera"] = "241.128906,-63.912598,50.348633,0.000133,12.199516,158.997177,35.0,321.520721,false,Manual,4.0",
            ["GUID"] = "194E194C",
            ["LookAt"] = {
                [1] = "100001:n(200021)",
                },
            ["NextDialogue"] = 10108303,
            ["SpeakNpcId"] = 200021,
            ["TalkActionId"] = {
                [1] = "200021:AgreeHead",
                [2] = "100001:Sigh_End",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/story/1002/101083/194E194C",
            },
        [10108303] = {
            ["Camera"] = "3226.708984,-329.703857,-858.430176,-0.0,2.99999,145.59549,15.0,100000.0,false,Disable,2.8",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "比如那些大型的野兽啊秽兽啊，跑得快但体格笨重。你就可以找墙壁、树干什么的，站在前面挑衅，它冲过来就马上闪开，让它自己一头撞晕。",
            ["ContentFR"] = "Par exemple, ces gros Souillés... rapides mais maladroits. Tu peux te placer devant un mur ou un tronc, les provoquer pour qu’ils foncent sur toi, puis esquiver leur charge et les laisser s’étourdir en se cognant tout seuls.",
            ["DialogueId"] = 10108303,
            ["FinalCamera"] = "3120.359375,-484.996094,-858.430176,-0.0,2.99999,145.59549,15.0,100000.0,false,Disable,2.8",
            ["GUID"] = "194E19A0",
            ["NextOptions"] = {
                [1] = 10108304,
                [2] = 10108305,
                },
            ["Scripts"] = "CameraMoveTo{_delay{6},TargetPosition{\"82.828125,-22.881592,132.529785,0.000104,-1.397983,140.189499,35.000008,161.268082,false,Manual,4.0\"},duration{0}}",
            ["SpeakNpcId"] = 200021,
            ["ToFinalCameraBlendTime"] = 12,
            ["VoiceName"] = "voice/$Locale$/story/1002/101083/194E19A0",
            ["bForbidSkipOptions"] = true,
            },
        [10108304] = {
            ["Content"] = "嗯，很不错的手段。",
            ["ContentFR"] = "<I>Eh bien, c’est une technique astucieuse.</>",
            ["DialogueId"] = 10108304,
            ["GUID"] = "10108304",
            ["ImprPlusId"] = 1006,
            ["NextDialogue"] = 10108306,
            },
        [10108305] = {
            ["Content"] = "呃……好卑鄙的手段。",
            ["ContentFR"] = "<I>Hmm... c’est une technique un peu sournoise.</>",
            ["DialogueId"] = 10108305,
            ["GUID"] = "10108305",
            ["ImprPlusId"] = 1007,
            ["NextDialogue"] = 10108308,
            },
        [10108306] = {
            ["Camera"] = "352.355469,-143.926758,113.639648,0.000176,0.800027,154.399246,50.000008,466.962006,false,Manual,8.0",
            ["CameraBlendCurve"] = "easeOutQuad",
            ["Content"] = "哈，那当然。这可是我从小到大摸爬滚打锻炼出的妙招。而对付敌人也是类似的道理，暴怒的人，和野兽没多大区别。",
            ["ContentFR"] = "Haha, évidemment. C’est un truc que j’ai appris en me débrouillant depuis mon enfance. Et avec les ennemis, c’est pareil : une personne en colère n’est pas très différente d’un Souillé.",
            ["DialogueId"] = 10108306,
            ["FacialId"] = {
                [1] = "200021:Smile02",
                },
            ["FinalCamera"] = "354.804688,-138.704834,113.639648,0.000176,0.80002,155.399689,50.000008,466.962006,false,Manual,8.0",
            ["GUID"] = "194E19CA",
            ["NextDialogue"] = 10108307,
            ["SpeakNpcId"] = 200021,
            ["TalkActionId"] = {
                [1] = "200021:Talk03_Start",
                },
            ["ToFinalCameraBlendTime"] = 11,
            ["VoiceName"] = "voice/$Locale$/story/1002/101083/194E19CA",
            },
        [10108307] = {
            ["Camera"] = "1436.363281,-566.314941,420.743164,0.000009,-12.299579,153.401611,20.0,489.882812,false,DoNotOverride,1.2",
            ["CameraBlendCurve"] = "easeInQuad",
            ["Content"] = "好了，这些本来也不是你的对手。接下来得来个大的……",
            ["ContentFR"] = "Bon, ces petites créatures n’étaient pas vraiment un défi. Maintenant, passons à du sérieux...",
            ["DialogueId"] = 10108307,
            ["FinalCamera"] = "1506.460938,-601.418945,437.838379,0.000008,-12.299579,153.401855,20.0,489.882812,false,DoNotOverride,1.2",
            ["GUID"] = "194E19F4",
            ["NextDialogue"] = 10108311,
            ["SpeakNpcId"] = 200021,
            ["TalkActionId"] = {
                [1] = "200021:Talk03_End",
                },
            ["ToFinalCameraBlendTime"] = 6,
            ["VoiceName"] = "voice/$Locale$/story/1002/101083/194E19F4",
            },
        [10108308] = {
            ["Camera"] = "352.355469,-143.926758,113.639648,0.000176,0.800027,154.399246,50.000008,466.962006,false,Manual,8.0",
            ["CameraBlendCurve"] = "easeOutQuad",
            ["Content"] = "这叫生活常识，你该不会看见别人雨天撑着伞也要说“卑鄙”吧。",
            ["ContentFR"] = "C’est juste du bon sens. Tu ne dirais pas qu’utiliser un parapluie sous la pluie est \"sournois\", si ?",
            ["DialogueId"] = 10108308,
            ["FinalCamera"] = "354.804688,-138.704834,113.639648,0.000176,0.80002,155.399689,50.000008,466.962006,false,Manual,8.0",
            ["GUID"] = "194E1A1E",
            ["NextDialogue"] = 10108309,
            ["SpeakNpcId"] = 200021,
            ["TalkActionId"] = {
                [1] = "200021:Talk01_Start",
                },
            ["ToFinalCameraBlendTime"] = 11,
            ["VoiceName"] = "voice/$Locale$/story/1002/101083/194E1A1E",
            },
        [10108309] = {
            ["Camera"] = "-32.097656,61.484131,137.130859,0.00022,-3.49942,-43.808128,50.0,142.954285,false,Manual,5.0",
            ["CameraBlendCurve"] = "easeOutQuad",
            ["Content"] = "只是因为是你说出来的所以听起来格外卑鄙一些……",
            ["ContentFR"] = "C’est juste que venant de toi, ça sonne encore plus sournois...",
            ["DialogueId"] = 10108309,
