        [10108508] = {
            ["Camera"] = "116.26709,-175.134766,180.025146,0.000202,-11.999685,135.292267,50.0,217.784042,false,Manual,8.0",
            ["Content"] = "……按原计划行事。我和白负责跟踪恩里克，奥特赛德从烟囱潜入恩里克的办公室。事成后，在奥特赛德家门口会面。",
            ["ContentFR"] = "... On suit le plan initial. Snow et moi, on suit Henrik, et l’Étranger, tu passes par la cheminée pour entrer dans son bureau. On se retrouve ensuite devant chez toi.",
            ["DialogueId"] = 10108508,
            ["ExStoryInfo"] = "Player",
            ["FacialId"] = {
