            },
        [10108705] = {
            ["Content"] = "（这是一个漂亮的雕花匣子，拿在手中沉甸甸的。但正如白所言，里面空无一物。）",
            ["ContentFR"] = "Une boîte finement sculptée, lourde à tenir. Mais comme dit Snow, elle est vide.",
            ["DialogueId"] = 10108705,
            ["DisableMouth"] = 1,
            ["GUID"] = "194E5B40",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 10108706,
            ["Scripts"] = "PARA{\
