        [10109002] = {
            ["Camera"] = "296.376221,434.72168,221.220703,0.000066,-12.002404,-123.593864,35.000008,100000.0,false,Disable,2.8",
            ["Content"] = "失踪的亨特就出现在了那份名单上……我猜他的下场多半不太妙。而且，你那个叫赛琪的朋友很可能是下一个。",
            ["ContentFR"] = "Hunt est sur cette liste après sa disparition... Je crains que son sort n’ait pas été heureux. Et ton amie Psyche pourrait bien être la suivante.",
            ["DialogueId"] = 10109002,
            ["FacialId"] = {
                [1] = "200021:Doubt01",
                },
            ["FinalCamera"] = "294.126709,431.435547,200.367188,0.000066,-9.602358,-123.99411,35.000008,100000.0,false,Disable,2.8",
            ["GUID"] = "194E8C24",
