            ["VoiceName"] = "voice/$Locale$/story/1002/101090/194E8C24",
            },
        [10109003] = {
            ["Camera"] = "143.380615,51.583008,147.531738,0.000069,-1.199982,-144.201019,40.0,274.454834,false,Manual,5.0",
            ["Content"] = "啧，恩里克回来的真不是时候，如果能再多几分钟……怪我，撬烟囱锁浪费了太长时间。这**养的！我就知道他不是什么好东西。",
            ["ContentFR"] = "Mmh... Henrik est revenu au pire moment. Si j’avais eu juste quelques minutes de plus... C’est de ma faute, à trop traîner sur cette serrure de cheminée. Ce... fumier ! Je savais qu’il n’était pas un homme de confiance.",
            ["DialogueId"] = 10109003,
            ["FacialId"] = {
                [1] = "200021:Angry01",
                },
            ["FinalCamera"] = "132.862061,65.048828,147.531738,0.00007,-1.199941,-138.801163,40.0,274.454834,false,Manual,5.0",
