            },
        [10109703] = {
            ["Camera"] = "109.730469,-1.478516,30.498047,0.000287,12.399074,142.316772,50.0,278.758331,false,Manual,5.0",
            ["Content"] = "你来把它打开吧。",
            ["ContentFR"] = "Tu peux l’ouvrir ?",
            ["DialogueId"] = 10109703,
            ["FacialId"] = {
                [1] = "200006:Smile01",
                },
            ["GUID"] = "194EFEFC",
            ["NextDialogue"] = 10109704,
            ["SpeakNpcId"] = 200006,
            ["TalkActionId"] = {
                [1] = "200006:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101097/194EFEFC",
            },
        [10109704] = {
            ["Camera"] = "-96.394531,130.861328,78.214844,0.000252,-8.00076,-17.689077,25.0,125.918678,false,Manual,3.0",
            ["Content"] = "这是……",
            ["ContentFR"] = "C’est...",
            ["DialogueId"] = 10109704,
            ["DialoguePanelType"] = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_Chapter01_Camera.T_Guide_Chapter01_Camera'}",
            ["ExStoryInfo"] = "Player",
            ["FacialId"] = {
                [1] = "100001:Shock01",
                },
            ["GUID"] = "194EFF26",
            ["NextDialogue"] = 10109705,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101097/194EFF26",
            },
        [10109705] = {
            ["Camera"] = "330.355469,-963.607422,7.018555,-5.000005,1.19807,109.312668,50.0,1184.560059,false,Manual,3.0",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "它叫“照相机”，是很了不起的宝物。",
            ["ContentFR"] = "C’est un appareil photo, un trésor inestimable.",
            ["DialogueId"] = 10109705,
            ["FacialId"] = {
                [1] = "200006:Smile02",
                [2] = "100001:None",
                },
            ["FinalCamera"] = "320.921875,-966.865234,7.888672,-5.000004,1.19807,108.912674,50.0,1184.560059,false,Manual,3.0",
            ["GUID"] = "194EFF50",
            ["NextDialogue"] = 10109706,
            ["SpeakNpcId"] = 200006,
            ["TalkActionId"] = {
                [1] = "200006:Talk02_Start",
                },
            ["ToFinalCameraBlendTime"] = 4,
            ["VoiceName"] = "voice/$Locale$/story/1002/101097/194EFF50",
            },
        [10109706] = {
            ["Camera"] = "-513.90625,86.755859,248.274414,-3.000002,-22.199732,4.520242,50.0,589.274902,false,Manual,12.0",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "这是四岁那年爸爸送我的。那年他培育出了很漂亮的泪湖铃兰，内城的大富豪很高兴，就随手送了这个给他，他又当做礼物送给了我。",
            ["ContentFR"] = "Mon père me l’avait offert pour mes quatre ans. Cette année-là, il avait réussi à faire pousser de magnifiques clochettes du Lac du Deuil. Un riche citadin de la cité intérieure, émerveillé, lui avait offert cet appareil en remerciement. Papa me l’avait donné comme cadeau d’anniversaire.",
            ["DialogueId"] = 10109706,
            ["FacialId"] = {
                [1] = "200006:Happy02",
                },
            ["FinalCamera"] = "-513.90625,86.755859,228.629883,-3.000002,-19.999599,4.520289,50.0,589.274902,false,Manual,12.0",
            ["GUID"] = "194EFF7A",
            ["NextDialogue"] = 10109707,
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{200006},AnimationId{\"Talk02_End\"},Duration{2}},\
PlayAnimation{ActorId{200006},AnimationId{\"Explain01_Start\"},Duration{2}},\
\
}",
            ["SpeakNpcId"] = 200006,
            ["ToFinalCameraBlendTime"] = 13,
            ["VoiceName"] = "voice/$Locale$/story/1002/101097/194EFF7A",
            },
        [10109707] = {
            ["Camera"] = "97.855469,26.320312,46.532227,-1.0,10.398955,146.71611,50.0,242.458954,false,Manual,8.0",
            ["Content"] = "可我舍不得用。我想，既然是珍贵的宝物，如果埋在土里，等到收获的时节，就能长出好多个相机了。那时家里就会富有起来，爸爸妈妈也就不用那么辛苦。",
            ["ContentFR"] = "Mais je l’aimais trop pour oser m’en servir. Je croyais qu’en l’enterrant, il pousserait... et que nous aurions plein d’appareils photo à la récolte. Alors, notre famille deviendrait riche, et mes parents n’auraient plus besoin de se tuer à la tâche.",
            ["DialogueId"] = 10109707,
            ["FacialId"] = {
                [1] = "200006:None",
                },
            ["FinalCamera"] = "95.832031,23.208984,46.592773,-1.0,10.398955,145.715927,50.0,242.458954,false,Manual,8.0",
            ["GUID"] = "194EFFA4",
            ["NextDialogue"] = 10109708,
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{200006},AnimationId{\"Explain01_End\"},Duration{2}},\
PlayAnimation{ActorId{200006},AnimationId{\"DisagreeHead\"},Duration{2}},\
PlayAnimation{ActorId{200006},AnimationId{\"Explain02_Start\"},Duration{2}}\
}",
            ["SpeakNpcId"] = 200006,
            ["ToFinalCameraBlendTime"] = 13,
            ["VoiceName"] = "voice/$Locale$/story/1002/101097/194EFFA4",
            },
        [10109708] = {
            ["Camera"] = "17.835938,30.003906,75.855469,0.000003,5.999706,139.000046,50.0,172.869095,false,Manual,5.0",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "所以我悄悄把它“种”在了这里。……那个时候的我，真是傻乎乎的。",
            ["ContentFR"] = "Alors je l’ai caché là, comme si je l’avais \"planté\"... Quelle enfant naïve j’étais, à ce moment-là.",
            ["DialogueId"] = 10109708,
            ["FinalCamera"] = "17.835938,30.003906,75.855469,0.000003,6.399723,139.000046,53.0,172.869095,false,Manual,5.0",
            ["GUID"] = "194EFFCE",
            ["NextDialogue"] = 10109709,
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{200006},AnimationId{\"Explain02_End\"},Duration{1.5}},\
LookAt{LookAtDescription{\"200006:p(Point101097)\"}}\
}",
            ["SpeakNpcId"] = 200006,
            ["ToFinalCameraBlendTime"] = 7,
            ["VoiceName"] = "voice/$Locale$/story/1002/101097/194EFFCE",
            },
        [10109709] = {
            ["Camera"] = "-167.960938,132.5625,94.099609,0.000283,-8.400545,-7.686968,50.0,217.697235,false,Manual,8.0",
            ["Content"] = "不过爸爸妈妈后来并没有责怪我，而是对我说，“那就等你成年那天再把它挖出来吧，就当是给未来自己的礼物。”",
            ["ContentFR"] = "Plus tard, quand mes parents l’ont découvert, ils n’ont pas été fâchés. Ils m’ont dit : « Alors, garde-le enterré jusqu’à ton passage à l’âge adulte. Ce sera ton cadeau pour l’avenir. »",
            ["DialogueId"] = 10109709,
            ["FacialId"] = {
                [1] = "200006:Smile01",
                },
            ["FinalCamera"] = "-167.53125,135.693359,94.099609,0.000283,-8.400545,-8.887018,50.0,217.697235,false,Manual,8.0",
            ["GUID"] = "194EFFF8",
            ["LookAt"] = {
                [1] = "200006:n(100001)",
                },
            ["NextOptions"] = {
                [1] = 10109710,
                [2] = 10109711,
                },
            ["SpeakNpcId"] = 200006,
            ["TalkActionId"] = {
                [1] = "100001:Think_Start",
                },
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/1002/101097/194EFFF8",
            },
        [10109710] = {
            ["Content"] = "是很可爱的想法。",
            ["ContentFR"] = "<I>C’était une idée adorable.</>",
            ["DialogueId"] = 10109710,
            ["GUID"] = "10109710.0",
            ["NextDialogue"] = 10109712,
            },
        [10109711] = {
            ["Content"] = "大家小时候都做过傻事。",
            ["ContentFR"] = "<I>On fait tous des choses un peu idiotes, quand on est enfant.</>",
            ["DialogueId"] = 10109711,
            ["GUID"] = "10109711.0",
            ["NextDialogue"] = 10109712,
            },
        [10109712] = {
            ["Camera"] = "95.253906,26.408203,53.023438,-1.0,8.100427,144.515015,40.000011,249.648575,false,Manual,8.0",
            ["Content"] = "{nickname}，谢谢你这些天陪我，但我没有什么值钱的东西。这个相机，就当做送给你的礼物吧。",
            ["ContentFR"] = "{nickname}... Merci pour ces jours passés ensemble. Je n’ai rien de précieux à t’offrir... Mais prends cet appareil photo, je voudrais qu’il soit ton cadeau.",
            ["DialogueId"] = 10109712,
            ["ExStoryInfo"] = "Player",
            ["FacialId"] = {
                [1] = "200006:Smile01",
                },
            ["FinalCamera"] = "93.351562,23.771484,53.079102,-0.999999,8.100427,144.115082,40.000011,249.648575,false,Manual,8.0",
            ["GUID"] = "194F0022",
            ["NextOptions"] = {
                [1] = 10109713,
                [2] = 10109714,
                },
            ["SpeakNpcId"] = 200006,
            ["TalkActionId"] = {
                [1] = "100001:Think_End",
                },
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/1002/101097/194F0022",
            },
        [10109713] = {
            ["Content"] = "这不是你的宝物吗？太贵重了。",
            ["ContentFR"] = "<I>Mais c’est ton trésor ! Je ne peux pas accepter, c’est trop précieux.</>",
            ["DialogueId"] = 10109713,
            ["GUID"] = "10109713.0",
            ["NextDialogue"] = 10109715,
            },
        [10109714] = {
            ["Content"] = "你给过我礼物了——那朵花。它是无价之宝。",
            ["ContentFR"] = "<I>Tu m’as déjà offert un cadeau... Cette fleur. Elle n’a pas de prix.</>",
            ["DialogueId"] = 10109714,
            ["GUID"] = "10109714.0",
            ["NextDialogue"] = 10109715,
            },
        [10109715] = {
            ["Camera"] = "15.8125,94.824219,78.226562,0.000262,7.799119,158.600952,50.0,140.419205,false,Manual,8.0",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "我的眼睛已经不再需要它，但你的旅途还很漫长。",
            ["ContentFR"] = "Mes yeux n’en auront plus l’usage... Mais ton voyage est encore long.",
            ["DialogueId"] = 10109715,
            ["FacialId"] = {
                [1] = "200006:Happy02",
                },
            ["FinalCamera"] = "15.8125,94.824219,78.226562,0.000262,7.799119,159.000992,52.0,140.419205,false,Manual,8.0",
            ["GUID"] = "194F004C",
            ["NextDialogue"] = 10109716,
            ["SpeakNpcId"] = 200006,
            ["TalkActionId"] = {
                [1] = "200006:Explain02_Start",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/story/1002/101097/194F004C",
            },
        [10109716] = {
            ["Camera"] = "-73.710938,92.207031,66.693359,0.000262,3.399228,-0.487854,50.0,93.129883,false,Manual,5.0",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "用你的眼睛，替我继续看看这个世界吧。",
            ["ContentFR"] = "Alors, regarde ce monde à ma place.",
            ["DialogueId"] = 10109716,
            ["FinalCamera"] = "-73.710938,92.207031,66.693359,0.000262,3.399228,-0.487854,52.0,93.129883,false,Manual,5.0",
            ["GUID"] = "194F0076",
            ["NextDialogue"] = 10109717,
            ["SpeakNpcId"] = 200006,
            ["TalkActionId"] = {
                [1] = "200006:Explain02_End",
                },
            ["ToFinalCameraBlendTime"] = 4.5,
            ["VoiceName"] = "voice/$Locale$/story/1002/101097/194F0076",
            },
        [10109717] = {
            ["Camera"] = "-380.574219,-471.193359,463.862305,-5.000005,-33.000675,60.310459,50.0,928.722656,false,DoNotOverride,3.0",
            ["Content"] = "…………",
            ["ContentFR"] = "...",
            ["DialogueId"] = 10109717,
            ["ExStoryInfo"] = "Player",
            ["FacialId"] = {
                [1] = "200006:None",
                },
            ["GUID"] = "194F00A0",
            ["NextDialogue"] = 10109718,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101097/194F00A0",
            },
        [10109718] = {
            ["Camera"] = "198.785156,-175.792969,10.463867,-3.000001,7.397299,129.297333,35.0,447.397217,false,Manual,3.0",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "难得出来一趟，我们就在湖上随便走走吧？",
            ["ContentFR"] = "Puisque nous sommes là, promenons-nous encore un peu sur le lac, veux-tu ?",
            ["DialogueId"] = 10109718,
            ["FinalCamera"] = "207.707031,-186.716797,8.631836,-3.000001,7.397299,129.297287,35.0,479.576324,false,Manual,3.0",
            ["GUID"] = "194F00CA",
            ["SpeakNpcId"] = 200006,
            ["TalkActionId"] = {
                [1] = "200006:Talk02_Start",
                },
            ["ToFinalCameraBlendTime"] = 4.5,
            ["VoiceName"] = "voice/$Locale$/story/1002/101097/194F00CA",
            },
        [10109801] = {
            ["Content"] = "在我很小的时候，爸爸偶尔会带我来湖边散步。",
            ["ContentFR"] = "Quand j’étais petite, mon père m’amenait parfois me promener au bord du lac.",
            ["DialogueId"] = 10109801,
            ["GUID"] = "194F0F3A",
            ["NextDialogue"] = 10109802,
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101098/194F0F3A",
            },
        [10109802] = {
            ["Content"] = "虽然时不时要和秽兽捉迷藏，但我总是很期待来这里。",
            ["ContentFR"] = "Même si nous devions parfois jouer à cache-cache avec les Souillés, j’attendais toujours ces moments avec impatience.",
            ["DialogueId"] = 10109802,
            ["GUID"] = "194F0F64",
            ["NextDialogue"] = 10109803,
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101098/194F0F64",
            },
        [10109803] = {
            ["Content"] = "因为我喜欢这里的浮冰和山峰，更因为，我喜欢看列车呼啸而过。",
            ["ContentFR"] = "J’aimais les plaques de glace flottantes et les montagnes… mais ce que je préférais, c’était voir les trains passer en grondant.",
            ["DialogueId"] = 10109803,
            ["GUID"] = "194F0F8E",
            ["NextDialogue"] = 10109804,
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101098/194F0F8E",
            },
        [10109804] = {
            ["Content"] = "你喜欢列车？",
            ["ContentFR"] = "Tu aimes les trains ?",
            ["DialogueId"] = 10109804,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "194F0FB8",
            ["NextDialogue"] = 10109805,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101098/194F0FB8",
            },
        [10109805] = {
            ["Content"] = "嗯。我喜欢它开去的地方……“南方”。",
            ["ContentFR"] = "Oui. Ce qui me fascine, c’est leur destination... le sud.",
            ["DialogueId"] = 10109805,
            ["GUID"] = "194F0FE2",
            ["NextDialogue"] = 10109806,
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101098/194F0FE2",
            },
        [10109806] = {
            ["Content"] = "书上写，南方和冰湖城不一样。",
            ["ContentFR"] = "Dans les livres, il est écrit que là-bas, rien ne ressemble à Givrelac.",
            ["DialogueId"] = 10109806,
            ["GUID"] = "194F100C",
            ["NextDialogue"] = 10109807,
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101098/194F100C",
            },
        [10109807] = {
            ["Content"] = "那里的太阳更加温暖，那里有四季变换。",
            ["ContentFR"] = "Le soleil y est plus chaud, et l’on peut voir les saisons changer.",
            ["DialogueId"] = 10109807,
            ["GUID"] = "194F1036",
            ["NextDialogue"] = 10109808,
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101098/194F1036",
            },
        [10109808] = {
            ["Content"] = "当春天来临，冰雪就会融去，即使在旷野，也会有大片繁花盛开。",
            ["ContentFR"] = "Quand vient le printemps, la glace et la neige disparaissent, et des fleurs éclosent partout, jusque dans les plaines sauvages.",
            ["DialogueId"] = 10109808,
            ["GUID"] = "194F1060",
            ["NextDialogue"] = 10109809,
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101098/194F1060",
            },
        [10109809] = {
            ["Content"] = "当时我就想，如果我也能乘上列车，就可以抵达那里了。",
            ["ContentFR"] = "Je me disais toujours : si seulement je pouvais monter dans l’un de ces trains, j’arriverais enfin là-bas...",
            ["DialogueId"] = 10109809,
            ["GUID"] = "194F108A",
            ["NextDialogue"] = 10109810,
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101098/194F108A",
            },
        [10109810] = {
            ["Content"] = "但是爸爸告诉我，这个心愿太奢侈了。",
            ["ContentFR"] = "Mais mon père m’a dit que c’était un vœu trop ambitieux.",
            ["DialogueId"] = 10109810,
            ["GUID"] = "194F10B4",
            ["NextDialogue"] = 10109811,
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101098/194F10B4",
            },
        [10109811] = {
            ["Content"] = "因为……卡戎之民的缘故？",
            ["ContentFR"] = "Parce que... vous êtes des Charons ?",
            ["DialogueId"] = 10109811,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "194F10DE",
            ["NextDialogue"] = 10109812,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101098/194F10DE",
            },
        [10109812] = {
            ["Content"] = "是的。而且爸爸和妈妈只是最普通的花匠，我们很清贫，没有乘上那辆列车的资格。",
            ["ContentFR"] = "Oui. Et puis Papa et Maman n’étaient que de simples fleuristes. Nous étions pauvres, et n’avions pas les moyens d’acheter un billet.",
            ["DialogueId"] = 10109812,
            ["GUID"] = "194F1108",
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101098/194F1108",
            },
        [10109901] = {
            ["Camera"] = "43.035156,-369.824219,5.117188,0.00037,9.794949,103.195534,15.0,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "所以，你敲开“修普诺斯之家”大门的那一天，我是那么惊喜……因为我几乎从未和冰湖城之外的人打过交道。",
            ["ContentFR"] = "Alors, le jour où tu as frappé à la porte de la Maison d’Hypnos, j’ai été si surprise... car je n’avais presque jamais rencontré quelqu’un venant d’ailleurs que Givrelac.",
            ["DialogueId"] = 10109901,
            ["FacialId"] = {
                [1] = "200027:Smile02",
                },
            ["FinalCamera"] = "50.992188,-403.761719,-0.895508,0.00037,9.794949,103.195534,15.0,100000.0,false,DoNotOverride,22.0",
            ["GUID"] = "194F1FA2",
            ["LookAt"] = {
                [1] = "100001:n(200027)",
                [2] = "200027:n(100001)",
                },
            ["NextDialogue"] = 10109902,
            ["RelatedWikiId"] = {
                [1] = 408003,
                [2] = 301005,
                [3] = 405002,
                [4] = 201007,
                [5] = 201006,
                [6] = 201001,
                },
            ["Scripts"] = "SEQ{\
PARA{\
TurnTo{TurnToDescription{\"200027:p(45)\"}},\
TurnTo{TurnToDescription{\"100001:p(-45)\"}},\
LookAt{LookAtDescription{\"200027:n(100001)\"}},\
LookAt{LookAtDescription{\"200027:n(100001)\"}}\
},\
PlayAnimation{ActorId{200027},AnimationId{\"Explain01_Start\"},Duration{2}}\
}",
            ["SpeakNpcId"] = 200027,
            ["ToFinalCameraBlendTime"] = 12,
            ["VoiceName"] = "voice/$Locale$/story/1002/101099/194F1FA2",
            },
        [10109902] = {
            ["Camera"] = "-194.089844,43.5625,83.087891,0.000346,-1.60116,21.496424,40.0,226.073593,false,Manual,8.0",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "我一直在悄悄想，你口中的故乡究竟是一个怎样的地方？你是不是亲眼见过大海？它是不是像一百片湖连起来那样一望无际？",
            ["ContentFR"] = "Depuis, je me demande en secret : à quoi ressemble ton pays natal ? As-tu vu l’océan de tes propres yeux ? Est-il vraiment vaste comme cent lacs réunis ?",
            ["DialogueId"] = 10109902,
            ["FinalCamera"] = "-148.476562,62.945312,79.891602,0.000346,-0.001072,17.102312,40.000011,162.126846,false,Manual,4.0",
            ["GUID"] = "194F1FCC",
            ["LookAt"] = {
                [1] = "200027:n(100001)",
                },
            ["NextDialogue"] = 10109903,
            ["Scripts"] = "\
SEQ{\
PlayAnimation{ActorId{200027},AnimationId{\"Explain01_End\"},Duration{1}},\
PlayAnimation{ActorId{200027},AnimationId{\"Talk02_Start\"},Duration{1}}\
}\
",
            ["SpeakNpcId"] = 200027,
            ["ToFinalCameraBlendTime"] = 18,
