        [10110201] = {
            ["Camera"] = "556.611328,700.994141,428.892578,0.000123,-21.00264,-125.02404,30.0,294.274872,false,Manual,22.0",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "啊啊……别打了，我投降！但真的不是我干的！！",
