        [10110206] = {
            ["Camera"] = "74.595703,85.75,141.061523,0.000114,1.99839,-111.626167,35.0,100000.0,false,Disable,2.8",
            ["Content"] = "停手停手，钱袋还你！我也是好几天没吃顿饱饭了，一时糊涂才……唉，我错了我错了！",
            ["ContentFR"] = "Arrête, arrête ! Voici ton sac d’argent ! Ça fait plusieurs jours que je n’ai pas eu un vrai repas, je me suis laissé emporter... Ah, j’ai eu tort, désolé !",
            ["DialogueId"] = 10110206,
