        [10110212] = {
            ["Camera"] = "32.447266,-94.166016,150.726562,0.000106,-6.001796,98.975403,35.000011,165.117889,false,Manual,4.0",
            ["CameraBlendCurve"] = "easeOutQuad",
            ["Content"] = "“秽蚀”到底是什么？",
            ["ContentFR"] = "Dégradation ? Qu’est-ce que c’est exactement ?",
