            ["ImprPlusId"] = 1007,
            ["NextDialogue"] = 10110215,
            },
        [10110215] = {
            ["Camera"] = "65.837891,244.282227,142.673828,0.000048,-1.002317,-107.633041,35.000015,374.558105,false,Manual,4.0",
            ["Content"] = "哦对，卡米拉提到过，那也难怪吧。",
            ["ContentFR"] = "Ah oui, Camilla en avait parlé, ça s’explique alors.",
            ["DialogueId"] = 10110215,
            ["GUID"] = "194F52FC",
