                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101102/194F52FC",
            },
        [10110216] = {
            ["Content"] = "再多问，小心我把今天的事…… ",
            ["ContentFR"] = "<I>Tu poses trop de questions... fais gaffe, sinon je vais raconter ce que j’ai vu aujourd’hui à...</>",
            ["DialogueId"] = 10110216,
            ["GUID"] = "10110216",
            ["ImprPlusId"] = 1010,
            ["NextDialogue"] = 10110217,
            },
        [10110217] = {
            ["Camera"] = "65.837891,244.282227,142.673828,0.000048,-1.002317,-107.633041,35.000015,374.558105,false,Manual,4.0",
            ["Content"] = "啊啊不问了不问了，你千万别说出去啊！",
            ["ContentFR"] = "Ah ! Non, non, je ne poserai plus de questions, s’il te plaît, ne le dis à personne !",
            ["DialogueId"] = 10110217,
            ["FacialId"] = {
                [1] = "200004:Sad01",
