            },
        [10110219] = {
            ["Camera"] = "59.294922,60.157227,158.963867,0.000116,1.398187,-107.029724,35.0,201.991119,false,Manual,6.0",
            ["Content"] = "你们这群人，差不多十几岁的时候吧，都会觉醒个什么力量，但也不是每个人都那么顺利。",
            ["ContentFR"] = "Vers l’adolescence, la plupart d’entre vous éveillent un pouvoir. Mais parfois, ça tourne mal.",
            ["DialogueId"] = 10110219,
            ["FinalCamera"] = "54.453125,61.650391,158.963867,0.000116,1.398222,-105.829933,35.0,197.159012,false,Manual,6.0",
            ["GUID"] = "194F537A",
            ["NextDialogue"] = 10110220,
            ["Scripts"] = "PARA{\
CameraMoveTo{_delay{4.1},TargetPosition{\"14.539062,-57.106445,149.019531,0.000111,-4.801684,98.370796,35.0,159.591751,false,Manual,6.0\"},duration{0}},\
CameraMoveTo{_delay{4.2},TargetPosition{\"24.572266,-55.670898,149.019531,0.000112,-5.201646,97.571365,35.000008,165.538956,false,Manual,6.0\"},duration{4}}\
}",
            ["SpeakNpcId"] = 200004,
            ["TalkActionId"] = {
                [1] = "200004:Talk01_End",
                },
            ["ToFinalCameraBlendTime"] = 4,
            ["VoiceName"] = "voice/$Locale$/story/1002/101102/194F537A",
            },
        [10110220] = {
            ["Content"] = "总有几个倒霉蛋不知道哪根筋搭错了，变成<W>秽兽</>——但要说威力啊，外面的普通秽兽连它们一根指头都不如，卫戍部队一整支小队都未必能搞定。",
            ["ContentFR"] = "Il y a toujours quelques pauvres malheureux qui, d’une manière ou d’une autre, ratent leur éveil et deviennent des <W>Souillés</>. Mais à la différence des Souillés ordinaires, ils sont bien plus puissants, une seule de ces créatures pourrait mettre en difficulté toute une escouade de Veilleurs.",
            ["DialogueId"] = 10110220,
            ["GUID"] = "194F53A4",
            ["NextDialogue"] = 10110221,
            ["RelatedWikiId"] = {
                [1] = 303003,
                },
            ["SpeakNpcId"] = 200004,
            ["VoiceName"] = "voice/$Locale$/story/1002/101102/194F53A4",
            },
        [10110221] = {
            ["Camera"] = "582.199219,778.926758,7556.786133,0.000033,22.586451,-62.627708,15.000007,179.344406,false,DoNotOverride,22.0",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "要是秽蚀者出现在城里，那附近一大片人都要自求多福喽。",
            ["ContentFR"] = "Si un Dégradé apparaît en ville... c’est tout le quartier qui est condamné.",
            ["DialogueId"] = 10110221,
            ["FinalCamera"] = "731.279297,485.125,7697.886719,0.000031,23.186407,-63.027958,15.000007,179.344406,false,DoNotOverride,22.0",
            ["GUID"] = "194F53CE",
            ["NextDialogue"] = 10110222,
            ["SpeakNpcId"] = 200004,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1002/101102/194F53CE",
            },
        [10110222] = {
            ["Camera"] = "3.785156,91.553711,146.086914,0.000141,3.197669,-91.427162,35.000011,214.337555,false,Manual,6.0",
            ["Content"] = "所以你明白为什么那么多索拉人恨卡戎了吧？大家都说是因为卡戎的血管里流淌着邪恶的魔力，所以才会招惹来这种祸端。而秽蚀者，就是所有卡戎中最邪恶的。",
            ["ContentFR"] = "Voilà pourquoi tant de Solariens haïssent les Charons. Ils disent que c’est le sang impur qui attire le malheur... Et les Dégradés sont vus comme les pires démons parmi les Charons.",
            ["DialogueId"] = 10110222,
            ["FacialId"] = {
                [1] = "200004:None",
                },
            ["GUID"] = "194F53F8",
            ["NextDialogue"] = 10110223,
            ["Scripts"] = "PlayAnimation{_delay{1},ActorId{200004},AnimationId{\"Talk01_Start\"},Duration{1}}",
            ["SpeakNpcId"] = 200004,
            ["TalkActionId"] = {
                [1] = "200004:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101102/194F53F8",
            },
        [10110223] = {
            ["Camera"] = "3.785156,91.553711,146.086914,0.000141,3.197669,-91.427162,35.000011,214.337555,false,Manual,6.0",
            ["Content"] = "这话吧，说实话我也不是那么信，但是……唉！总之，这么稀罕的事，怎么就摊在哈尔头上了呢。",
            ["ContentFR"] = "Franchement, j’y crois pas complètement. Mais... pourquoi fallait-il que ça tombe sur Hal ?",
            ["DialogueId"] = 10110223,
            ["GUID"] = "194F5422",
            ["NextDialogue"] = 10110224,
            ["Scripts"] = "SEQ{\
LookAt{LookAtDescription{\"200004:p(P101102Bag)\"}},\
PlayAnimation{ActorId{200004},AnimationId{\"Disagree\"},Duration{2}},\
LookAt{_delay{2},LookAtDescription{\"200004:n(100001)\"}}\
}",
            ["SpeakNpcId"] = 200004,
            ["TalkActionId"] = {
                [1] = "200004:Talk01_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101102/194F5422",
            },
        [10110224] = {
            ["Camera"] = "59.203125,-199.486328,172.362305,0.000048,-11.20041,106.99884,35.000008,100000.0,false,Disable,4.0",
            ["Content"] = "半月前那家伙慌慌张张来找我，但我哪敢收留他！包庇秽蚀者跟包庇神奇同盟一样是重罪，一不留神小命就丢了。我只能给点吃的，让他自己想办法去。",
            ["ContentFR"] = "Il y a deux semaines, il est venu me voir, paniqué. Mais je ne pouvais pas le cacher. Protéger un Dégradé, c’est comme abriter un membre des Déchus, peine capitale assurée. Alors je lui ai juste donné de quoi manger, et je l’ai renvoyé.",
            ["DialogueId"] = 10110224,
            ["GUID"] = "194F544C",
            ["NextDialogue"] = 10110225,
            ["Scripts"] = "CameraMoveTo{_delay{11},TargetPosition{\"74.595703,85.75,141.061523,0.000111,4.598363,-113.225594,35.0,100000.0,false,Disable,2.8\"},duration{0}}",
            ["SpeakNpcId"] = 200004,
            ["TalkActionId"] = {
                [1] = "200004:Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101102/194F544C",
            },
        [10110225] = {
            ["Camera"] = "81.287109,-34.47168,231.873047,0.000089,-31.399204,-132.789673,35.000008,100000.0,false,Disable,4.0",
            ["Content"] = "后来听说他偷人家东西被人抓了现行，又被发现是秽蚀者，直接送治安署去了。",
            ["ContentFR"] = "Plus tard, j’ai appris qu’il s’était fait prendre en train de voler. Et quand ils ont découvert ce qu’il était... ils l’ont livré direct au Bureau de la Sécurité.",
            ["DialogueId"] = 10110225,
            ["GUID"] = "194F5476",
            ["NextOptions"] = {
                [1] = 10110226,
                },
            ["SpeakNpcId"] = 200004,
            ["TalkActionId"] = {
                [1] = "200004:Talk01_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101102/194F5476",
            },
        [10110226] = {
            ["Content"] = "送去治安署会发生什么？",
            ["ContentFR"] = "<I>Que se passe-t-il lorsque tu es envoyé au Bureau de la Sécurité ?</>",
            ["DialogueId"] = 10110226,
            ["GUID"] = "194F5477",
            ["NextDialogue"] = 10110227,
            },
        [10110227] = {
            ["Camera"] = "777.373047,-100.292969,25.057617,0.000009,4.599859,172.998215,40.000011,332.596619,false,Manual,22.0",
            ["Content"] = "都说了秽蚀者是无药可救的，还能发生什么？自然是移交给我们卫戍部队，然后……唉。",
            ["ContentFR"] = "Je t’ai déjà dit qu’il n’y avait aucun remède pour les Dégradés. Tu crois qu’il va lui arriver quoi ? On le transfère aux Veilleurs et ensuite... eh bien, tu vois.",
            ["DialogueId"] = 10110227,
            ["GUID"] = "194F54A0",
            ["NextDialogue"] = 10110228,
            ["SpeakNpcId"] = 200004,
            ["TalkActionId"] = {
                [1] = "200004:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101102/194F54A0",
            },
        [10110228] = {
            ["Camera"] = "-30.980469,-249.970703,249.849609,0.000058,-40.098839,61.201523,20.000011,207.029022,false,Manual,3.5",
            ["Content"] = "虽然这家伙也算自作自受……但好歹也当过几年朋友，我不忍心让他躺在冰冷的殓房，就把他偷……带了出来，打算把他葬在泪湖边上，埋他母亲的地方。",
            ["ContentFR"] = "Il l’a bien cherché, d’une certaine manière... Mais il avait été mon ami quelques années. Je ne pouvais pas supporter l’idée de le laisser dans une morgue glaciale. Alors je l’ai... sorti discrètement. Mon intention était de l’enterrer au bord du Lac du Deuil, là où repose sa mère.",
            ["DialogueId"] = 10110228,
            ["FinalCamera"] = "-23.003906,-235.451172,235.890625,0.000058,-40.098839,61.201523,20.000011,207.029022,false,Manual,3.5",
            ["GUID"] = "194F54CA",
            ["NextDialogue"] = 10110229,
            ["Scripts"] = "PARA{\
LookAt{LookAtDescription{\"200004:p(P101102Bag)\"}},\
SetLocation{ActorId{100001},TargetPoint{\"P101102Nvzhu2\"},Visibility{\"Show\"}}\
}",
            ["SpeakNpcId"] = 200004,
            ["ToFinalCameraBlendTime"] = 4,
            ["TurnTo"] = {
                [1] = "200004:p(-110)",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101102/194F54CA",
            },
        [10110229] = {
            ["Camera"] = "49.005859,-190.758789,170.493164,0.000064,-9.500171,103.609756,40.000023,322.94809,false,Manual,3.0",
            ["Content"] = "等等，我想知道……从秽蚀出现征兆，到秽蚀发生……这期间会有什么症状？",
            ["ContentFR"] = "Attends. Je veux savoir... Entre les premiers signes de la Dégradation et sa manifestation complète... il se passe quoi ? Quels symptômes apparaissent ?",
            ["DialogueId"] = 10110229,
            ["ExStoryInfo"] = "Player",
            ["FacialId"] = {
                [1] = "100001:Think01",
                },
            ["GUID"] = "194F54F4",
            ["NextDialogue"] = 10110230,
            ["Scripts"] = "PARA{\
LookAt{_delay{1},LookAtDescription{\"200004:n(100001)\"}}\
}",
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101102/194F54F4",
            },
        [10110230] = {
            ["Camera"] = "29.394531,154.411133,135.935547,0.000082,4.298655,-102.209503,40.000011,300.548492,false,Manual,4.0",
            ["Content"] = "我哪知道啊？哦，之前好像听说过有些家伙会变得特别狂躁，也有一些可怜家伙会逐渐失去正常的感知，比如瞎了聋了之类的？",
            ["ContentFR"] = "Comment veux-tu que je sache ? Enfin... j’ai entendu dire que certains deviennent extrêmement violents. D’autres, plus malheureux, commencent à perdre peu à peu leurs sens : la vue, l’ouïe, ce genre de choses.",
            ["DialogueId"] = 10110230,
            ["FacialId"] = {
                [1] = "200004:Sad01",
                },
            ["GUID"] = "194F551E",
            ["NextDialogue"] = 10110231,
            ["RelatedWikiId"] = {
                [1] = 303006,
                },
            ["Scripts"] = "SEQ{\
TurnTo{TurnToDescription{\"200004:n(100001)\"}},\
PlayAnimation{_delay{1.5},ActorId{200004},AnimationId{\"Think_Start\"},Duration{1}},\
PlayAnimation{_delay{5},ActorId{200004},AnimationId{\"Think_End\"},Duration{1}},\
}",
            ["SpeakNpcId"] = 200004,
            ["TalkActionId"] = {
                [1] = "100001:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101102/194F551E",
            },
        [10110231] = {
            ["Content"] = "我只是听说啊，你要对这个感兴趣，自己问医生去。不过我看你已经觉醒成功了，担心这个干吗。",
            ["ContentFR"] = "Ce n’est que ce qu’on raconte. Si ça t’intéresse vraiment, demande plutôt à un médecin. Mais toi, tu as déjà survécu à l’éveil. Alors pourquoi t’inquiéter de ça ?",
            ["DialogueId"] = 10110231,
            ["FacialId"] = {
                [1] = "200004:None",
                },
            ["GUID"] = "194F5548",
            ["NextDialogue"] = 10110232,
            ["Scripts"] = "PlayAnimation{_delay{3},ActorId{200004},AnimationId{\"Talk01_Start\"},Duration{2}}\
",
            ["SpeakNpcId"] = 200004,
            ["VoiceName"] = "voice/$Locale$/story/1002/101102/194F5548",
            },
        [10110232] = {
            ["Camera"] = "71.007812,-49.522461,222.453125,0.000127,-26.599911,112.772514,37.500008,159.011261,false,Manual,22.0",
            ["CameraBlendCurve"] = "easeInQuad",
            ["Content"] = "……",
            ["ContentFR"] = "...",
            ["DialogueId"] = 10110232,
            ["ExStoryInfo"] = "Player",
            ["FacialId"] = {
                [1] = "100001:Unacceptable01",
                },
            ["FinalCamera"] = "60.40625,-24.273438,208.739258,0.000127,-26.599911,112.772514,37.500008,159.011261,false,Manual,22.0",
            ["GUID"] = "194F5572",
            ["NextDialogue"] = 10110233,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Think_Start",
                [2] = "200004:Talk01_End",
                },
            ["ToFinalCameraBlendTime"] = 3,
            ["VoiceName"] = "voice/$Locale$/story/1002/101102/194F5572",
            },
        [10110233] = {
            ["Content"] = "嗯！我刚刚有些头晕，没看清台阶，多谢啦。",
            ["ContentFR"] = "Ah ! J’ai eu un petit vertige, j’ai raté la marche. Merci de m’avoir rattrapée !",
            ["DialogueId"] = 10110233,
            ["GUID"] = "194F559C",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10110233.T_Story_Recall_10110233'",
            ["NextDialogue"] = 10110234,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101013/19499D06",
            },
        [10110234] = {
            ["Content"] = "刚刚突然看不清东西，没想到竟然惊动了它……抱歉！",
            ["ContentFR"] = "Tout à coup, ma vue s’est troublée... et j’ai fini par affoler cette créature. Je suis désolée...",
            ["DialogueId"] = 10110234,
            ["GUID"] = "10110234.0",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10110234.T_Story_Recall_10110234'",
            ["NextDialogue"] = 10110235,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101049/194BEBA6",
            },
        [10110235] = {
            ["Content"] = "你的眼睛……是什么时候看不清的？",
            ["ContentFR"] = "Psyche... Depuis quand est-ce que tu ne vois plus clair ?",
            ["DialogueId"] = 10110235,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "10110235.0",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10110235.T_Story_Recall_10110235'",
            ["NextDialogue"] = 10110236,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101094/194ECE42",
            },
        [10110236] = {
            ["Content"] = "什么时候……",
            ["ContentFR"] = "Depuis quand... exactement... ?",
            ["DialogueId"] = 10110236,
            ["GUID"] = "10110236.0",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10110236.T_Story_Recall_10110236'",
            ["NextDialogue"] = 10110237,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101094/194ECE6C",
            },
        [10110237] = {
            ["Camera"] = "19.232422,44.570312,117.50293,0.000166,18.198389,104.808296,35.000008,162.592728,false,Manual,22.0",
            ["CameraBlendCurve"] = "easeOutQuad",
            ["Content"] = "（……难道赛琪的眼疾是“秽蚀”的症状……难道说，修普诺斯之家的所有“住客”都是秽蚀者？）",
            ["ContentFR"] = "<I>... Et si la cécité de Psyche était un symptôme de la Dégradation ? Se pourrait-il que tous les \"pensionnaires\" de la Maison d’Hypnos soient des Dégradés ?</>",
            ["DialogueId"] = 10110237,
            ["DisableMouth"] = 1,
            ["ExStoryInfo"] = "Player",
            ["FacialId"] = {
                [1] = "100001:Shock01",
                },
            ["FinalCamera"] = "29.253906,6.640625,104.633789,0.000168,17.198368,104.608376,35.000008,162.592728,false,Manual,22.0",
            ["GUID"] = "194F5644",
            ["NextDialogue"] = 10110238,
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Shock_Start",
                },
            ["ToFinalCameraBlendTime"] = 1,
            ["VoiceName"] = "voice/$Locale$/story/1002/101102/194F5644",
            },
        [10110238] = {
            ["Camera"] = "37.144531,202.914062,126.870117,0.000128,3.900086,-105.196716,40.0,278.887787,false,Manual,3.0",
            ["CameraBlendCurve"] = "easeInQuad",
            ["Content"] = "长官，我向您打听一个人，希望您如实回答。看到这个照相机了吗？如果您拒绝，我就把它交到治安署，那里的长官想必会喜欢的。",
            ["ContentFR"] = "Monsieur, je veux me renseigner sur quelqu’un, et j’espère que tu me répondras honnêtement. Tu vois cet appareil photo ? Si tu refuses, je pourrais très bien en confier la pellicule au Bureau de la Sécurité, je suis {性别:sûr|sûre} qu’ils sauraient quoi en faire.",
            ["DialogueId"] = 10110238,
            ["ExStoryInfo"] = "Player",
            ["FacialId"] = {
                [1] = "100001:Doubt01",
                },
            ["FinalCamera"] = "50.792969,198.213867,126.870117,0.000126,3.900086,-107.797836,40.0,278.887787,false,Manual,3.0",
            ["GUID"] = "194F566E",
            ["NextDialogue"] = 10110239,
            ["Scripts"] = "PARA{\
CameraMoveTo{_delay{4.1},TargetPosition{\"72.476562,-210.320312,168.837891,0.000193,-9.201282,108.579414,35.000008,371.235565,false,Manual,3.0\"},duration{0}},\
CameraMoveTo{_delay{4.2},TargetPosition{\"59.669922,-214.0625,168.837891,0.000192,-9.801321,105.5793,35.000008,371.235565,false,Manual,3.0\"},blend{\"easeOutQuad\"},duration{4}},\
PlayAnimation{_delay{4.2},ActorId{100001},AnimationId{\"Talk03_Start\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Shock_End",
                },
            ["ToFinalCameraBlendTime"] = 4,
            ["VoiceName"] = "voice/$Locale$/story/1002/101102/194F566E",
            },
        [10110239] = {
            ["Camera"] = "62.695312,-35.460938,197.44043,0.000168,-15.401721,-165.42247,35.000008,239.561539,false,Manual,22.0",
            ["Content"] = "天呐，饶了我吧，你就算想打听什么军团机密，也犯不着找我这样的大头兵啊——我就一看门的！",
            ["ContentFR"] = "Par pitié, épargne-moi... Si tu veux percer des secrets militaires, tu n’as pas besoin de harceler un simple soldat comme moi, je fais juste le guet !",
            ["DialogueId"] = 10110239,
            ["FacialId"] = {
                [1] = "200004:Sad01",
                },
            ["FinalCamera"] = "78.841797,-97.880859,197.44043,0.000168,-18.601685,-166.822098,35.000011,239.561539,false,Manual,22.0",
            ["GUID"] = "194F5698",
            ["NextDialogue"] = 10110240,
            ["SpeakNpcId"] = 200004,
            ["TalkActionId"] = {
                [1] = "100001:Talk02_End",
                },
            ["ToFinalCameraBlendTime"] = 0.5,
            ["VoiceName"] = "voice/$Locale$/story/1002/101102/194F5698",
            },
        [10110240] = {
            ["Camera"] = "24.123047,-69.332031,126.121094,0.000172,2.398667,98.17495,35.000011,177.910553,false,Manual,4.0",
            ["Content"] = "城北“修普诺斯之家”的店主恩里克·埃塞尔莱德，您知道他些什么？有一件算一件，希望您如实告诉我。",
            ["ContentFR"] = "Henrik Ethelred, le tenancier de la Maison d’Hypnos, au nord de Givrelac. Qu’est-ce que tu sais de lui ? Je veux tout entendre, sans exception.",
            ["DialogueId"] = 10110240,
            ["ExStoryInfo"] = "Player",
            ["FacialId"] = {
                [1] = "100001:None",
                },
            ["GUID"] = "194F56C2",
            ["NextDialogue"] = 10110241,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101102/194F56C2",
            },
        [10110241] = {
            ["Camera"] = "121.794922,416.958008,140.132812,0.000136,-2.801443,-106.219742,35.000008,100000.0,false,Disable,2.8",
            ["Content"] = "恩里克·埃塞尔莱德……不就是个开旅馆的吗？我想想，我长官倒是跟他有些交情。这人……虽说有过案底，但这些年也算老老实实的，没犯过什么事儿。",
            ["ContentFR"] = "Henrik Ethelred... Ce n’est pas juste un aubergiste ? L’un de mes supérieurs le connaît un peu. Il a eu quelques démêlés avec la justice autrefois, mais ces dernières années, il est resté tranquille. Rien à signaler.",
            ["DialogueId"] = 10110241,
            ["FacialId"] = {
                [1] = "200004:None",
                },
            ["FinalCamera"] = "182.132812,391.785156,140.132812,0.00013,-3.201432,-116.019501,35.000008,100000.0,false,Disable,2.8",
            ["GUID"] = "194F56EC",
            ["NextDialogue"] = 10110242,
            ["Scripts"] = "PlayAnimation{_delay{1},ActorId{200004},AnimationId{\"Think_Start\"},Duration{2}}\
",
            ["SpeakNpcId"] = 200004,
            ["TalkActionId"] = {
                [1] = "100001:Talk02_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1002/101102/194F56EC",
            },
        [10110242] = {
            ["Camera"] = "182.132812,391.785156,140.132812,0.00013,-3.201432,-116.019501,35.000008,100000.0,false,Disable,2.8",
            ["Content"] = "哦，那家伙脾气挺臭的，不止一次把去投宿的外乡人赶跑。不过这个嘛，据说之前他干老本行的时候，脾气也不怎么样，不过那时候至少还有家里人管着。",
            ["ContentFR"] = "Oh, par contre, il a fichu caractère. Plus d’une fois, il a jeté dehors des voyageurs venus loger chez lui. Mais bon... paraît que déjà, à l’époque où il exerçait son vrai métier, il n’était pas commode. Sauf qu’à ce moment-là, il avait encore sa famille pour le tempérer.",
            ["DialogueId"] = 10110242,
            ["GUID"] = "194F5716",
            ["NextDialogue"] = 10110261,
            ["SpeakNpcId"] = 200004,
            ["TalkActionId"] = {
                [1] = "200004:Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101102/194F5716",
            },
        [10110243] = {
            ["Content"] = "请详细说一下“案底”。",
            ["ContentFR"] = "<I>Parle-moi en détail de \"ses antécédents\".</>",
            ["DialogueId"] = 10110243,
            ["GUID"] = "10110243",
            ["NextDialogue"] = 10110246,
            },
        [10110244] = {
            ["Content"] = "请详细说一下“他的老本行”。",
            ["ContentFR"] = "<I>Parle-moi de \"son ancien métier\".</>",
            ["DialogueId"] = 10110244,
            ["GUID"] = "10110244.0",
            ["NextDialogue"] = 10110251,
            },
        [10110245] = {
            ["Content"] = "请详细说一下“他的家人”。",
            ["ContentFR"] = "<I>Parle-moi de \"sa famille\".</>",
            ["DialogueId"] = 10110245,
            ["GUID"] = "10110245.0",
            ["NextDialogue"] = 10110254,
            },
        [10110246] = {
            ["Camera"] = "182.132812,391.785156,140.132812,0.00013,-3.201432,-116.019501,35.000008,100000.0,false,Disable,2.8",
            ["Content"] = "这个啊……我想想，十几年前来着？大概十四、五年前吧，恩里克·埃塞尔莱德在弗莱格桑省的<H>丹流城</>犯下了一起谋杀案。",
            ["ContentFR"] = "<I>Voyons... Ça remonte à quoi... quatorze, quinze ans ? Henrik Ethelred a commis un meurtre à Rougerive, dans la province de Flagson.</>",
            ["DialogueId"] = 10110246,
            ["GUID"] = "194F5740",
            ["NextDialogue"] = 10110247,
            ["RelatedWikiId"] = {
                [1] = 408006,
                },
            ["Scripts"] = "PlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt02/0043_story_empire\"}}",
            ["SpeakNpcId"] = 200004,
            ["TalkActionId"] = {
                [1] = "200004:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101102/194F5740",
            },
        [10110247] = {
            ["Camera"] = "48.828125,-238.466797,197.088867,0.000132,-14.601796,105.386505,35.000008,394.862823,false,Manual,4.0",
            ["Content"] = "被害者是个卡戎，哦对，还是个出现了征兆的<W>秽蚀者</>——就咱们刚才说到的。这不算什么重罪，所以他只坐了几个月牢就放出来了。",
            ["ContentFR"] = "La victime était un Charon. Oui, et un Charon déjà atteint par la <W>Dégradation</> ... Comme on vient d’en parler. Ce n’était pas considéré comme un crime grave, donc il n’a fait que quelques mois de prison avant d’être libéré.",
            ["DialogueId"] = 10110247,
            ["GUID"] = "194F576A",
            ["NextDialogue"] = 10110248,
            ["SpeakNpcId"] = 200004,
            ["TalkActionId"] = {
                [1] = "200004:Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101102/194F576A",
            },
        [10110248] = {
            ["Camera"] = "11.783203,35.181641,158.039062,0.000169,-12.8009,95.373573,35.000008,83.272263,false,Manual,5.0",
            ["Content"] = "他为什么要这么做？",
            ["ContentFR"] = "Pourquoi il a fait ça ?",
            ["DialogueId"] = 10110248,
            ["ExStoryInfo"] = "Player",
            ["FacialId"] = {
                [1] = "100001:Angry01",
                },
            ["GUID"] = "194F5794",
            ["NextDialogue"] = 10110249,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101102/194F5794",
            },
        [10110249] = {
            ["Camera"] = "781.091797,122.442383,14.25293,0.00013,1.998233,-169.017654,25.0,182.242599,false,Manual,22",
            ["Content"] = "……不知道。不过，是个人类就会害怕、憎恶秽蚀者，这也没什么奇怪的吧？",
            ["ContentFR"] = "... Aucune idée. Mais enfin, c’est humain d’avoir peur, et même de haïr les Dégradés, non ?",
            ["DialogueId"] = 10110249,
            ["FacialId"] = {
                [1] = "100001:None",
                },
            ["FinalCamera"] = "781.091797,122.442383,33.219727,0.00013,0.0,-169.01709,25.0,182.242599,false,Manual,22",
            ["GUID"] = "194F57BE",
            ["NextDialogue"] = 10110250,
            ["SpeakNpcId"] = 200004,
            ["TalkActionId"] = {
                [1] = "200004:Disagree",
                [2] = "100001:Think_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1002/101102/194F57BE",
            },
        [10110250] = {
            ["Camera"] = "31.501953,148.584961,134.270508,0.000126,2.597808,-102.621628,35.000008,314.487457,false,Manual,4.0",
            ["Content"] = "这件事我也是听长官说起的，毕竟过去那么多年了，又不是发生在本地，所以冰湖城也没几个人知道，要是说错了你不要怪我啊！",
            ["ContentFR"] = "Je tiens ça de mon supérieur. Et puis, ça date, et ce n’est pas arrivé ici. Alors si je me trompe sur les détails, tu ne m’en veux pas, hein ?",
            ["DialogueId"] = 10110250,
            ["GUID"] = "194F57E8",
            ["NextDialogue"] = 10110261,
            ["Scripts"] = "PlayAnimation{_delay{4},ActorId{200004},AnimationId{\"Talk01_End\"},Duration{1}}",
            ["SpeakNpcId"] = 200004,
            ["TalkActionId"] = {
                [1] = "200004:Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101102/194F57E8",
            },
        [10110251] = {
            ["Camera"] = "31.501953,148.584961,134.270508,0.000126,2.597808,-102.621628,35.000008,314.487457,false,Manual,4.0",
            ["Content"] = "冰湖城上了岁数的人都知道，恩里克曾经是冰湖城远近闻名的<H>医生</>。他医术挺高明的，是连内城的贵族老爷都会找他看病的那种。",
            ["ContentFR"] = "Tous les anciens de Givrelac savent qu’Henrik a été, autrefois, un <H>médecin</> très réputé. Un vrai praticien de talent, au point que même les nobles de la cité intérieure venaient le consulter.",
            ["DialogueId"] = 10110251,
            ["GUID"] = "194F5812",
            ["NextDialogue"] = 10110252,
            ["Scripts"] = "PlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt02/0043_story_empire\"}}",
            ["SpeakNpcId"] = 200004,
            ["TalkActionId"] = {
                [1] = "200004:Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101102/194F5812",
            },
        [10110252] = {
            ["Camera"] = "327.693359,662.063477,356.859375,0.000096,-19.999989,-112.616272,35.0,100000.0,false,Disable,2.8",
            ["Content"] = "但后来不知发生了什么事，他在声名最显赫的时候关了医馆，又过了两年，医馆再次开张，但招牌却变成了“旅馆”。",
            ["ContentFR"] = "Mais un jour, sans qu’on sache trop pourquoi, il a fermé son cabinet au sommet de sa renommée. Deux ans plus tard, il l’a rouvert... mais la plaque indiquait \"auberge\".",
            ["DialogueId"] = 10110252,
            ["FinalCamera"] = "350.828125,717.59375,368.043945,0.000096,-19.999989,-112.616272,35.0,100000.0,false,Disable,2.8",
            ["GUID"] = "194F583C",
            ["NextDialogue"] = 10110253,
            ["Scripts"] = "PlayAnimation{_delay{1},ActorId{200004},AnimationId{\"Think_Start\"},Duration{1}}",
            ["SpeakNpcId"] = 200004,
            ["TalkActionId"] = {
                [1] = "200004:Talk01_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1002/101102/194F583C",
            },
        [10110253] = {
            ["Camera"] = "62.0,13.855469,151.842773,0.000098,1.998315,-117.01268,35.000008,143.588394,false,Manual,5.149117",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "哦，仔细想想，好像刚好就是他在丹流城犯事前后那两年……",
            ["ContentFR"] = "D’ailleurs... en y repensant, c’était à peu près à l’époque où il a eu ses ennuis à Rougerive...",
            ["DialogueId"] = 10110253,
            ["FinalCamera"] = "100.847656,-14.870117,151.862305,0.000107,6.598201,-135.012131,35.000011,143.588394,false,Manual,5.149117",
            ["GUID"] = "194F5866",
            ["NextDialogue"] = 10110261,
            ["SpeakNpcId"] = 200004,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/story/1002/101102/194F5866",
            },
        [10110254] = {
            ["Camera"] = "37.912109,160.816406,132.972656,0.000113,2.998043,-103.822327,35.000008,305.385315,false,Manual,2.8",
            ["Content"] = "一个妻子，一个女儿，普普通通的三口之家。他妻子很早就过世了，是他自己把女儿拉扯大的。",
            ["ContentFR"] = "Il avait une femme et une fille. Une famille ordinaire, rien de spécial. Sa femme est morte très tôt, et c’est lui qui a élevé sa fille seul.",
            ["DialogueId"] = 10110254,
            ["GUID"] = "194F5890",
            ["NextDialogue"] = 10110255,
            ["Scripts"] = "PlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt02/0043_story_empire\"}}",
            ["SpeakNpcId"] = 200004,
            ["TalkActionId"] = {
                [1] = "200004:Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101102/194F5890",
            },
        [10110255] = {
            ["Camera"] = "67.521484,-246.492188,192.460938,0.000153,-11.802217,107.784149,35.000011,445.644928,false,Manual,4.0",
            ["Content"] = "至于他女儿……叫什么来着？海蒂？海莉？记不清了——总之那姑娘当年和恩里克一起去了丹流城旅行，但并没有跟他一起回来。",
            ["ContentFR"] = "Quant à sa fille... comment elle s’appelait déjà ? Heidi ? Hayley ? J’ai oublié. Bref, elle était partie avec lui en voyage à Rougerive, mais elle n’en est jamais revenue.",
            ["DialogueId"] = 10110255,
            ["GUID"] = "194F58BA",
            ["NextDialogue"] = 10110256,
            ["RelatedWikiId"] = {
                [1] = 201006,
                },
            ["SpeakNpcId"] = 200004,
            ["TalkActionId"] = {
                [1] = "200004:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101102/194F58BA",
            },
        [10110256] = {
            ["Camera"] = "67.521484,-246.492188,192.460938,0.000153,-11.802217,107.784149,35.000011,445.644928,false,Manual,4.0",
            ["Content"] = "他从不提起他的女儿，有一年我长官和他喝酒的时候，问起了那女孩的下落，他当场就摔杯子走了。",
            ["ContentFR"] = "Il n’évoque jamais sa fille. Un jour, mon supérieur lui en a parlé autour d’un verre... Henrik a brisé son verre et s’est levé en claquant la porte.",
            ["DialogueId"] = 10110256,
            ["GUID"] = "194F58E4",
            ["NextDialogue"] = 10110261,
            ["SpeakNpcId"] = 200004,
            ["VoiceName"] = "voice/$Locale$/story/1002/101102/194F58E4",
            },
        [10110257] = {
            ["Camera"] = "68.076172,242.375977,133.895508,0.000118,1.598292,-108.029732,35.000008,377.188965,false,Manual,4.0",
            ["Content"] = "唉，我发誓，所有我知道的听说过的都告诉你了。你能不能放过我啊，至少把胶片给我——*的，你说你这外乡人长得怪和善的，怎么人就这么卑鄙呢。",
            ["ContentFR"] = "Pfiu... Je te jure, je t’ai dit tout ce que je savais et tout ce que j’avais entendu. Tu pourrais me laisser tranquille, maintenant ? Rends-moi au moins la pellicule... Bon sang, toi qui as l’air si aimable, comment tu peux être aussi {性别:sournois|sournoise} ?",
            ["DialogueId"] = 10110257,
            ["GUID"] = "194F590E",
            ["NextOptions"] = {
                [1] = 10110258,
                [2] = 10110259,
                },
            ["Scripts"] = "SEQ{\
TurnTo{TurnToDescription{\"200004:n(100001)\"}},\
PlayAnimation{ActorId{200004},AnimationId{\"Talk01_Start\"},Duration{2}},\
}",
            ["SpeakNpcId"] = 200004,
            ["VoiceName"] = "voice/$Locale$/story/1002/101102/194F590E",
            },
        [10110258] = {
            ["Content"] = "刚才多有得罪。其实我是开玩笑的，我并没有真的拍您…… ",
            ["ContentFR"] = "<I>{性别:Désolé|Désolée} pour tout à l’heure. En fait, je plaisantais. Je ne t’ai pas vraiment pris en photo...</>",
            ["DialogueId"] = 10110258,
            ["GUID"] = "10110258",
            ["ImprPlusId"] = 1009,
            ["NextDialogue"] = 10110260,
            },
        [10110259] = {
            ["Content"] = "胶片我先带走了。等我下次从您这里打听消息的时候再还吧，尊敬的长官。",
            ["ContentFR"] = "<I>Je garde la pellicule pour l’instant. Je te la rendrai la prochaine fois que je viendrai chercher des infos.</>",
            ["DialogueId"] = 10110259,
            ["GUID"] = "10110259",
            ["ImprPlusId"] = 1006,
            ["NextDialogue"] = 10110260,
            },
        [10110260] = {
            ["Camera"] = "68.076172,242.375977,133.895508,0.000118,1.598292,-108.029732,35.000008,377.188965,false,Manual,4.0",
            ["Content"] = "回见，凯文长官。",
            ["ContentFR"] = "À la prochaine.",
            ["DialogueId"] = 10110260,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "194F5938",
            ["Scripts"] = "PARA{\
CameraMoveTo{_delay{4.2},TargetPosition{\"201.574219,-68.02832,168.996094,0.000123,-2.201465,-165.821976,35.000008,243.340027,false,Manual,4.0\"},duration{0}},\
SEQ{\
LookAt{LookAtDescription{\"100001:n(100001)\"}},\
TurnTo{TurnToDescription{\"100001:p(180)\"}},   \
MoveTo{ActorId{100001},TargetPoint{\"P101102Nvzhu3\"},MoveSpeed{80},Visibility{\"Show\"}}\
}\
}",
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "200004:Talk01_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101102/194F5938",
            },
        [10110261] = {
            ["DialogueId"] = 10110261,
            ["DialoguePanelType"] = "None",
            ["Duration"] = 0.1,
            ["FinalDialogueId"] = 10110257,
            ["GUID"] = "194F5717",
            ["NextOptions"] = {
                [1] = 10110243,
                [2] = 10110244,
                [3] = 10110245,
                },
            },
        [10110301] = {
            ["Content"] = "喂，怎么这就走了？你去哪儿啊，喂！",
            ["ContentFR"] = "Hein ? Tu pars comme ça ? Où est-ce que tu vas, hé !",
            ["DialogueId"] = 10110301,
            ["GUID"] = "194F6142",
            ["NextDialogue"] = 10110302,
            ["SpeakNpcId"] = 200004,
            ["VoiceName"] = "voice/$Locale$/story/1002/101103/194F6142",
            },
        [10110302] = {
            ["Content"] = "你答应过不会说出去的吧？！你得说话算话——",
            ["ContentFR"] = "Tu m’as promis de ne rien répéter, pas vrai ? Tu dois tenir parole...",
            ["DialogueId"] = 10110302,
            ["GUID"] = "194F616C",
            ["SpeakNpcId"] = 200004,
            ["VoiceName"] = "voice/$Locale$/story/1002/101103/194F616C",
            },
        [10110401] = {
            ["Content"] = "……你你、你怎么还在这儿？！吓死我了。",
            ["ContentFR"] = "... Hé, mais... mais qu’est-ce que tu fais encore là ? Tu m’as foutu une de ces trouilles !",
            ["DialogueId"] = 10110401,
            ["GUID"] = "194F71AA",
            ["SpeakNpcId"] = 200004,
            ["VoiceName"] = "voice/$Locale$/story/1002/101104/194F71AA",
            },
        [10110501] = {
            ["Camera"] = "668.771606,50.456543,139.82666,0.000123,-1.999995,86.357468,45.0,207.220764,false,Manual,2.5",
            ["Content"] = "都备妥了。",
            ["ContentFR"] = "Tout est prêt.",
            ["DialogueId"] = 10110501,
            ["FacialId"] = {
                [1] = "200021:Confident01",
                },
            ["GUID"] = "194F8212",
            ["LookAt"] = {
                [1] = "200021:n(100001)",
                [2] = "100001:n(100001)",
                },
            ["NextDialogue"] = 10110502,
            ["RelatedWikiId"] = {
                [1] = 201006,
                [2] = 201007,
                [3] = 405002,
                [4] = 303006,
                },
            ["Scripts"] = "PARA{\
PlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/mute\"}},\
SEQ{\
