        [10110521] = {
            ["Camera"] = "67.095459,-243.466309,147.307129,0.00015,0.999987,94.153214,20.0,355.68277,false,Manual,6.0",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "尖叫声——修普诺斯之家的方向！",
            ["ContentFR"] = "Ces cris... ils viennent de la Maison d’Hypnos !",
            ["DialogueId"] = 10110521,
            ["FinalCamera"] = "62.456299,-179.568848,96.763916,0.00015,6.0,94.153214,25.0,8628.139648,false,Manual,6.0",
            ["GUID"] = "194F84DC",
