        [10110602] = {
            ["Camera"] = "-58.66626,184.545898,58.416016,0.000013,9.599646,-71.385262,25.000002,245.13945,false,Manual,22.0",
            ["Content"] = "刚才不会是你在鬼叫吧？出什么事了？",
            ["ContentFR"] = "C’était toi qui poussais des cris tout à l’heure ? Qu’est-ce qui s’est passé ?",
            ["DialogueId"] = 10110602,
            ["FacialId"] = {
                [1] = "200002:None",
                },
            ["GUID"] = "194F92A4",
            ["LookAt"] = {
