        [10110902] = {
            ["Camera"] = "-231.873047,-73.172028,160.285156,0.000103,-6.596924,20.794041,40.000011,446.663574,false,Manual,5.5",
            ["Content"] = "请你们带上这个。",
            ["ContentFR"] = "S’il vous plaît, prenez ceci.",
            ["DialogueId"] = 10110902,
            ["DialoguePanelType"] = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_Chapter01_Flower_1.T_Guide_Chapter01_Flower_1'}",
            ["GUID"] = "194FC3DC",
            ["NextDialogue"] = 10110903,
            ["SpeakNpcId"] = 200045,
            ["TalkActionId"] = {
                [1] = "200045:Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101109/194FC3DC",
            },
        [10110903] = {
            ["Camera"] = "64.572266,91.821472,278.037109,0.0,0.0,89.999992,30.0,100000.0,false,DoNotOverride,22",
            ["Content"] = "赛琪会经常送花给我们，即使我们有的人已经不太闻得出花的香味，不太看得清花的轮廓，她还是会说，花可以给人带来好运，坚持这么做。",
            ["ContentFR"] = "Psyche nous offrait souvent des fleurs. Même si certains d’entre nous ne pouvaient plus vraiment en sentir le parfum, ni même en distinguer les contours, elle continuait de le faire, en disant que les fleurs portent chance.",
            ["DialogueId"] = 10110903,
            ["FinalCamera"] = "64.572266,141.821472,278.037109,0.0,0.0,89.999992,30.0,100000.0,false,DoNotOverride,22",
            ["GUID"] = "194FC406",
            ["LookAt"] = {
                [1] = "200045:p(P10106801)",
                },
            ["NextDialogue"] = 10110904,
            ["SpeakNpcId"] = 200045,
            ["TalkActionId"] = {
                [1] = "200045:Talk02_End",
                },
            ["ToFinalCameraBlendTime"] = 7.5,
            ["VoiceName"] = "voice/$Locale$/story/1002/101109/194FC406",
            },
        [10110904] = {
            ["Camera"] = "-64.513672,-54.797607,154.447266,0.000147,-5.19662,21.383118,35.000008,170.88736,false,Manual,3.0",
            ["Content"] = "……但当我想要回应的时候，已经来不及了。",
            ["ContentFR"] = "... Mais quand j’ai voulu lui rendre sa gentillesse, il était déjà trop tard.",
            ["DialogueId"] = 10110904,
            ["GUID"] = "194FC430",
            ["NextDialogue"] = 10110905,
            ["SpeakNpcId"] = 200045,
            ["TalkActionId"] = {
                [1] = "200045:Sigh_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101109/194FC430",
            },
        [10110905] = {
            ["Camera"] = "-230.103516,-78.412262,153.914062,0.000093,-5.797054,21.191561,35.000008,351.556366,false,Manual,4.0",
            ["Content"] = "请你们把这朵花带给她吧，这是她最喜欢的花。",
            ["ContentFR"] = "Apportez-lui cette fleur, je vous en prie. C’est sa préférée.",
            ["DialogueId"] = 10110905,
            ["GUID"] = "194FC45A",
            ["LookAt"] = {
                [1] = "200045:n(100001)",
                },
            ["NextDialogue"] = 10110906,
            ["SpeakNpcId"] = 200045,
            ["TalkActionId"] = {
                [1] = "200045:Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101109/194FC45A",
            },
        [10110906] = {
            ["Camera"] = "-7.181641,-249.865479,233.710938,0.000057,-29.099882,93.194183,15.000005,100000.0,false,DoNotOverride,22.0",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "请告诉她，修普诺斯之家的每个人，都在等着她……",
            ["ContentFR"] = "Et dites-lui... que tous les pensionnaires de la Maison d’Hypnos l’attendent...",
            ["DialogueId"] = 10110906,
            ["FinalCamera"] = "-4.027344,-306.261597,265.148438,0.000057,-29.099882,93.194183,15.000005,100000.0,false,DoNotOverride,22.0",
            ["GUID"] = "194FC484",
