            },
        [10110907] = {
            ["Camera"] = "262.748047,-120.47818,147.644531,0.000102,-4.196898,153.589691,35.000008,434.590698,false,Manual,3.0",
            ["Content"] = "我会的。我一定会救下她。",
            ["ContentFR"] = "Je le ferai. Je sauverai Psyche.",
            ["DialogueId"] = 10110907,
            ["ExStoryInfo"] = "Player",
            ["FacialId"] = {
                [1] = "100001:Sad01",
                },
            ["GUID"] = "194FC4AE",
            ["NextDialogue"] = 10110908,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101109/194FC4AE",
            },
        [10110908] = {
            ["Camera"] = "51.148438,0.197876,149.753906,0.000102,-4.600037,179.58815,35.000011,140.0,false,DoNotOverride,22",
            ["Content"] = "或者至少……阻止她做出违背自己心愿的事。",
            ["ContentFR"] = "Ou du moins... je l’empêcherai de commettre quelque chose qu’elle regretterait.",
            ["DialogueId"] = 10110908,
            ["ExStoryInfo"] = "Player",
            ["FacialId"] = {
                [1] = "100001:Confident01",
                },
            ["FinalCamera"] = "38.595703,0.288055,150.865234,0.000102,-4.600037,179.58815,35.000011,140.0,false,Manual,DoNotOverride,22",
            ["GUID"] = "194FC4D8",
            ["Scripts"] = "PARA{\
CameraMoveTo{_delay{2.1},TargetPosition{\"-22.845703,1.761353,150.835938,0.000102,-4.600037,179.58815,35.000011,65.552429,false,DoNotOverride,22\"},duration{0}},\
CameraMoveTo{_delay{2.2},TargetPosition{\"-27.648438,1.795654,150.466797,0.000102,-4.600037,179.58815,35.000011,65.552429,false,DoNotOverride,22\"},duration{2}}\
}",
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Explain02_End",
                },
            ["ToFinalCameraBlendTime"] = 3,
            ["VoiceName"] = "voice/$Locale$/story/1002/101109/194FC4D8",
            },
        [10111001] = {
            ["Content"] = "呼……呼……呼……",
            ["ContentFR"] = "Haa... haa... haa...",
            ["DialogueId"] = 10111001,
            ["Duration"] = 3,
            ["GUID"] = "194FD41A",
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101110/194FD41A",
            },
        [10111002] = {
            ["Content"] = "啊……",
            ["ContentFR"] = "Ah...",
            ["DialogueId"] = 10111002,
            ["Duration"] = 1,
            ["GUID"] = "194FD444",
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101110/194FD444",
            },
        [10111003] = {
            ["Content"] = "对……不……",
            ["DialogueId"] = 10111003,
            ["Duration"] = 0.5,
            ["GUID"] = "194FD46E",
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101110/194FD46E",
            },
        [10111004] = {
            ["Content"] = "回来，危险！",
            ["ContentFR"] = "Argh— !!",
            ["DialogueId"] = 10111004,
            ["Duration"] = 0.5,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "194FD498",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101110/194FD498",
            },
        [10111005] = {
            ["Content"] = "风太大了，我没法靠近……！",
            ["ContentFR"] = "Le vent est trop fort... je ne peux pas m’approcher... !",
            ["DialogueId"] = 10111005,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "194FD499",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101110/194FD499",
            },
        [10111006] = {
            ["Content"] = "该死，这样下去我们都会送命的……",
            ["ContentFR"] = "Reviens, c’est trop dangereux ! Merde... si ça continue, nous allons tous y rester...",
            ["DialogueId"] = 10111006,
            ["Duration"] = 4.5,
            ["GUID"] = "194FD500",
            ["SpeakNpcId"] = 200021,
            ["VoiceName"] = "voice/$Locale$/story/1002/101110/194FD500",
            },
        [10111007] = {
            ["Content"] = "她失去理智了，应战！",
            ["ContentFR"] = "Elle a perdu la raison. Préparez-vous au combat !",
            ["DialogueId"] = 10111007,
            ["Duration"] = 2.5,
            ["GUID"] = "194FD516",
            ["SpeakNpcId"] = 200021,
            ["VoiceName"] = "voice/$Locale$/story/1002/101110/194FD516",
            },
        [10111101] = {
            ["Content"] = "赛琪，听得见我的声音吗？",
            ["ContentFR"] = "Psyche, tu m’entends ?",
            ["DialogueId"] = 10111101,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "194FE482",
            ["NextDialogue"] = 10111102,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101111/194FE482",
            },
        [10111102] = {
            ["Content"] = "回答我……",
            ["ContentFR"] = "Réponds-moi...",
            ["DialogueId"] = 10111102,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "194FE4AC",
            ["NextDialogue"] = 10111103,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101111/194FE4AC",
            },
        [10111103] = {
            ["Content"] = "你说过的，你明明还有那么多想做的事……",
            ["ContentFR"] = "Tu l’as dit toi-même... il y a tant de choses que tu veux encore accomplir...",
            ["DialogueId"] = 10111103,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "194FE4D6",
            ["NextDialogue"] = 10111104,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101111/194FE4D6",
            },
        [10111104] = {
            ["Content"] = "你会离开这里，去那些你前所未见的地方——",
            ["ContentFR"] = "Tu quitteras Givrelac, pour découvrir d’autres horizons...",
            ["DialogueId"] = 10111104,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "194FE500",
            ["NextDialogue"] = 10111105,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101111/194FE500",
            },
        [10111105] = {
            ["Content"] = "……你可以去一座小岛，在那里盖几间房子……",
            ["ContentFR"] = "... Tu iras sur une petite île, y bâtir une maison au bord de la mer...",
            ["DialogueId"] = 10111105,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "194FE52A",
            ["NextDialogue"] = 10111106,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101111/194FE52A",
            },
        [10111106] = {
            ["Content"] = "……在房子边上种满白色的花……",
            ["ContentFR"] = "... Tu planteras des fleurs blanches autour de cette maison...",
            ["DialogueId"] = 10111106,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "194FE554",
            ["NextDialogue"] = 10111107,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101111/194FE554",
            },
        [10111107] = {
            ["Content"] = "……一边用大大的帽檐遮住太阳，一边和友人说起冰湖城的雪……",
            ["ContentFR"] = "... Et sous un large chapeau, tu parleras à tes amis de la neige de Givrelac...",
            ["DialogueId"] = 10111107,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "194FE57E",
            ["NextDialogue"] = 10111108,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101111/194FE57E",
            },
        [10111108] = {
            ["Content"] = "……回答我……",
            ["ContentFR"] = "Réponds-moi, Psyche...",
            ["DialogueId"] = 10111108,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "194FE5A8",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101111/194FE5A8",
            },
        [10111201] = {
            ["Content"] = "赛琪，我来带你回家。",
            ["ContentFR"] = "Psyche, je suis venu te ramener à la maison.",
            ["DialogueId"] = 10111201,
            ["Duration"] = 4,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "194FF4EA",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101127/1950EB02",
            },
        [10111301] = {
            ["Content"] = "这是……我家？",
            ["ContentFR"] = "C’est... ma maison ?",
            ["DialogueId"] = 10111301,
            ["GUID"] = "191B889A",
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101113/191B889A",
            },
        [10111401] = {
            ["Content"] = "亲爱的，看，赛琪在对我们笑呢。",
            ["ContentFR"] = "Chéri, regarde... Psyche nous sourit.",
            ["DialogueId"] = 10111401,
            ["GUID"] = "191B88C4",
            ["NextDialogue"] = 10111402,
            ["SpeakNpcId"] = 200039,
            ["VoiceName"] = "voice/$Locale$/story/1002/101114/191B88C4",
            },
        [10111402] = {
            ["Content"] = "……不知道这孩子来到世上，究竟是幸运还是不幸。",
            ["ContentFR"] = "... Je me demande si la venue de cet enfant au monde est une bénédiction... ou une malédiction.",
            ["DialogueId"] = 10111402,
            ["GUID"] = "191B88EE",
            ["NextDialogue"] = 10111403,
            ["SpeakNpcId"] = 200038,
            ["VoiceName"] = "voice/$Locale$/story/1002/101114/191B88EE",
            },
        [10111403] = {
            ["Content"] = "……是的，我们并不是带着祝福降生的。",
            ["ContentFR"] = "... Oui. Nous ne sommes pas venus au monde sous une pluie de bénédictions.",
            ["DialogueId"] = 10111403,
            ["GUID"] = "191B8918",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101114/191B8918",
            },
        [10111501] = {
            ["Content"] = "妈妈！我答应过赛琪，今天带她来家里堆积木……",
            ["ContentFR"] = "Maman ! J’avais promis à Psyche de l’inviter aujourd’hui pour jouer avec mes blocs...",
            ["DialogueId"] = 10111501,
            ["GUID"] = "191BB9D2",
            ["NextDialogue"] = 10111502,
            ["SpeakNpcId"] = 200040,
            ["VoiceName"] = "voice/$Locale$/story/1002/101115/191BB9D2",
            },
        [10111502] = {
            ["Content"] = "谁让你和她玩的？说过多少次，少碰那些不干不净的，你想被邪恶的魔法害死吗？",
            ["ContentFR"] = "Qui t’a dit de jouer avec elle ? Je t’ai répété mille fois d’éviter ces gens impurs. Tu veux mourir, frappé par la magie noire ?",
            ["DialogueId"] = 10111502,
            ["GUID"] = "191BB9FC",
            ["NextDialogue"] = 10111503,
            ["SpeakNpcId"] = 200041,
            ["VoiceName"] = "voice/$Locale$/story/1002/101115/191BB9FC",
            },
        [10111503] = {
            ["Content"] = "哎呀，好好的积木都弄脏了，快扔掉！",
            ["ContentFR"] = "Regarde-moi ça... les blocs sont tous salis. Jette-les immédiatement !",
            ["DialogueId"] = 10111503,
            ["GUID"] = "191BBA26",
            ["SpeakNpcId"] = 200041,
            ["VoiceName"] = "voice/$Locale$/story/1002/101115/191BBA26",
            },
        [10111601] = {
            ["Content"] = "那天，怀着委屈与不解，我花了一整晚时间洗澡，直到皮肤流出鲜血。",
            ["ContentFR"] = "Ce jour-là... pleine d’injustice et d’incompréhension, je me suis lavée toute la nuit... jusqu’à ce que ma peau se mette à saigner.",
            ["DialogueId"] = 10111601,
            ["GUID"] = "191BBA50",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101116/191BBA50",
            },
        [10111701] = {
            ["Content"] = "不是的长官，我的女儿一向懂事，她绝不会偷窃顾客的项链，更没有藏在花盆里！",
            ["ContentFR"] = "Non, monsieur, vous vous trompez ! Ma fille a toujours été raisonnable, elle n’aurait jamais volé le collier d’un client, encore moins l’avoir caché dans un pot de fleurs !",
            ["DialogueId"] = 10111701,
            ["GUID"] = "191BCA3A",
            ["NextDialogue"] = 10111702,
            ["SpeakNpcId"] = 200039,
            ["VoiceName"] = "voice/$Locale$/story/1002/101117/191BCA3A",
            },
        [10111702] = {
            ["Content"] = "狡辩什么，卡戎崽子有几个手脚干净的？",
            ["ContentFR"] = "Assez ! Y a-t-il seulement un seul gosse de Charon qui ait les mains propres ?",
            ["DialogueId"] = 10111702,
            ["GUID"] = "191BCA64",
            ["NextDialogue"] = 10111703,
            ["SpeakNpcId"] = 200043,
            ["VoiceName"] = "voice/$Locale$/story/1002/101117/191BCA64",
            },
        [10111703] = {
            ["Content"] = "这样吧，不是说没偷没藏吗，那就让她自己把店里那些花一盆盆砸了，证明清白。",
            ["ContentFR"] = "Bon, puisqu’elle est si innocente, qu’elle le prouve : qu’elle brise elle-même tous ces pots de fleurs. Et on verra bien.",
            ["DialogueId"] = 10111703,
            ["GUID"] = "191BCA8E",
            ["NextDialogue"] = 10111704,
            ["SpeakNpcId"] = 200044,
            ["VoiceName"] = "voice/$Locale$/story/1002/101117/191BCA8E",
            },
        [10111704] = {
            ["Content"] = "……因为，我们生而是“恶魔的孩子”。",
            ["ContentFR"] = "... Parce que nous sommes des \"Enfants du Démon\".",
            ["DialogueId"] = 10111704,
            ["GUID"] = "191BDAA2",
            ["GuideFacialId"] = "Sad",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101117/191BDAA2",
            },
        [10111801] = {
            ["Content"] = "啊啊……为什么……",
            ["ContentFR"] = "Aaah... pourquoi... ?",
            ["DialogueId"] = 10111801,
            ["GUID"] = "191BDACC",
            ["NextDialogue"] = 10111802,
            ["SpeakNpcId"] = 200039,
            ["VoiceName"] = "voice/$Locale$/story/1002/101118/191BDACC",
            },
        [10111802] = {
            ["Content"] = "她那么善良，我们一家也本本分分，没做过任何坏事……为什么这种事会落在我们头上？",
            ["ContentFR"] = "Elle est si gentille... et nous, nous avons toujours vécu droitement, sans jamais faire de mal à personne... Pourquoi tout ça est tombé sur nous ?",
            ["DialogueId"] = 10111802,
            ["GUID"] = "191BDAF6",
            ["NextDialogue"] = 10111803,
            ["SpeakNpcId"] = 200039,
            ["VoiceName"] = "voice/$Locale$/story/1002/101118/191BDAF6",
            },
        [10111803] = {
            ["Content"] = "……事到如今，只能去请求恩里克·埃塞尔莱德医生了。这是我们最后能为她做的。",
            ["ContentFR"] = "... À présent, il ne nous reste plus qu’à aller demander l’aide du docteur Henrik Ethelred. C’est la dernière chose que nous pouvons encore faire pour elle.",
            ["DialogueId"] = 10111803,
            ["GUID"] = "191BDB20",
            ["NextDialogue"] = 10111804,
            ["SpeakNpcId"] = 200038,
            ["VoiceName"] = "voice/$Locale$/story/1002/101118/191BDB20",
            },
        [10111804] = {
            ["Content"] = "爸爸，妈妈，对不起……",
            ["ContentFR"] = "Papa, maman... je suis désolée...",
            ["DialogueId"] = 10111804,
            ["GUID"] = "191BDB4A",
            ["GuideFacialId"] = "Sad",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101118/191BDB4A",
            },
        [10111901] = {
            ["Content"] = "……没有任何意义。",
            ["ContentFR"] = "... Ça n’a aucun sens.",
            ["DialogueId"] = 10111901,
            ["GUID"] = "191BEB0A",
            ["NextDialogue"] = 10111902,
            ["SpeakNpcId"] = 200045,
            ["VoiceName"] = "voice/$Locale$/story/1002/101119/191BEB0A",
            },
        [10111902] = {
            ["Content"] = "你每天送这种东西给我，又能改变什么呢。",
            ["ContentFR"] = "Tu peux bien m’apporter ça chaque jour... qu’est-ce que ça change ?",
            ["DialogueId"] = 10111902,
            ["GUID"] = "191BEB34",
            ["NextDialogue"] = 10111903,
            ["SpeakNpcId"] = 200045,
            ["VoiceName"] = "voice/$Locale$/story/1002/101119/191BEB34",
            },
        [10111903] = {
            ["Content"] = "赛琪。你应该知道，来到“修普诺斯之家”意味着什么。",
            ["ContentFR"] = "Psyche. Tu sais très bien ce que signifie être envoyée ici, à la Maison d’Hypnos.",
            ["DialogueId"] = 10111903,
            ["GUID"] = "191BEB5E",
            ["NextDialogue"] = 10111904,
            ["SpeakNpcId"] = 200046,
            ["VoiceName"] = "voice/$Locale$/story/1002/101119/191BEB5E",
            },
        [10111904] = {
            ["Content"] = "嗯，我都明白。",
            ["ContentFR"] = "Oui. Je comprends.",
            ["DialogueId"] = 10111904,
            ["GUID"] = "191BEB88",
            ["GuideFacialId"] = "Sad",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10111905,
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101119/191BEB88",
            },
        [10111905] = {
            ["Content"] = "……但我们是为了什么“意义”才活着吗？",
            ["ContentFR"] = "... Mais est-ce qu’on vit vraiment pour \"un sens\" ?",
            ["DialogueId"] = 10111905,
            ["GUID"] = "191BEBB2",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101119/191BEBB2",
            },
        [10112001] = {
            ["Content"] = "……赛琪……",
            ["ContentFR"] = "... Psyche...",
            ["DialogueId"] = 10112001,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "191B9902",
            ["NextDialogue"] = 10112002,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101120/191B9902",
            },
        [10112002] = {
            ["Content"] = "……能听见我的声音吗……",
            ["ContentFR"] = "Est-ce que tu m’entends... ?",
            ["DialogueId"] = 10112002,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "191B992C",
            ["NextDialogue"] = 10112003,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101120/191B992C",
            },
        [10112003] = {
            ["Content"] = "……回答我……",
            ["ContentFR"] = "... Réponds-moi...",
            ["DialogueId"] = 10112003,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "191B9956",
            ["NextDialogue"] = 10112004,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101120/191B9956",
            },
        [10112004] = {
            ["Content"] = "有什么人在呼唤我吗……",
            ["ContentFR"] = "Quelqu’un... m’appelle ?",
            ["DialogueId"] = 10112004,
            ["GUID"] = "191B9980",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10112005,
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101120/191B9980",
            },
        [10112005] = {
            ["Content"] = "是在告诉我，不要就这样睡着吗……",
            ["ContentFR"] = "Il... veut m’empêcher de m’endormir à jamais ?",
            ["DialogueId"] = 10112005,
            ["GUID"] = "191B99AA",
            ["GuideFacialId"] = "Sad",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101120/191B99AA",
            },
        [10112100] = {
            ["Content"] = "赛琪……醒醒……",
            ["ContentFR"] = "Psyche... réveille-toi...",
            ["DialogueId"] = 10112100,
            ["GUID"] = "19508891",
            ["VoiceName"] = "voice/$Locale$/story/1002/101121/19508891",
            },
        [10112101] = {
            ["Camera"] = "-1315.217285,639.65625,36.358154,-0.0,-14.999996,-34.000755,14.0,100000.0,false,DoNotOverride,2.8",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "你已经看到了自己的一生。怀抱诅咒的来，毫无意义的去。",
            ["ContentFR"] = "Tu as déjà contemplé toute ta vie. Une naissance marquée du sceau de la malédiction... et une fin vide de sens.",
            ["DialogueId"] = 10112101,
            ["FacialId"] = {
                [1] = "200052:Smile01",
                [2] = "200006:Shock01",
                },
            ["FinalCamera"] = "-1353.548462,665.503906,107.660645,-0.0,-8.800411,-34.000824,12.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "19508892",
            ["LookAt"] = {
                [1] = "200052:n(200006)",
                [2] = "200006:n(200052)",
                },
            ["NextDialogue"] = 10112102,
