            },
        [10112102] = {
            ["Camera"] = "-1207.813599,500.523438,177.099365,0.000065,-6.399019,-1.789612,35.0,229.405197,false,Manual,6.0",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "毫无意义——你永远以虚伪的笑脸逢迎他人，你那么无私吗？不，你只是卑怯地乞求他们垂怜你，记住你——记住你还是个人时的模样！",
            ["ContentFR"] = "Tout cela n’a aucun sens, toujours ce sourire factice pour complaire aux autres. Crois-tu être si désintéressée ? Non... tu mendiais lâchement leur pitié, leur mémoire... qu’ils se souviennent encore de toi, comme avant !",
            ["DialogueId"] = 10112102,
            ["FinalCamera"] = "-1212.987305,506.90625,177.723389,0.000065,-6.399019,-3.700013,35.0,229.405197,false,Manual,6.0",
            ["GUID"] = "195088BC",
            ["NextDialogue"] = 10112103,
            ["Scripts"] = "SEQ{\
