        [10113011] = {
            ["Camera"] = "-413.662109,-507.15625,157.617188,0.000528,-7.39734,53.794216,25.0,603.134277,false,Manual,4.0",
            ["Content"] = "他们、他们没准就是秽蚀者的同伙！这些低贱的家伙，一个个净是邪恶的魔法师，没有一个好东西！我看全都得……",
            ["ContentFR"] = "Ils... ils sont peut-être les complices du Dégradé ! Ces minables, toujours des mages impurs, aucun n’est digne de confiance ! À mon avis, il faudrait tous les—",
            ["DialogueId"] = 10113011,
            ["GUID"] = "19511DB4",
            ["LookAt"] = {
                [1] = "100001:n(700065)",
                [2] = "700108:n(200021)",
                },
            ["NextDialogue"] = 10113012,
