                [1] = "200021:Talk02_Start",
                [2] = "100304:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101130/1951202A",
            },
        [10113026] = {
            ["Content"] = "（冷静下来，保持沉默——你不能继续引起军团怀疑了。） ",
            ["ContentFR"] = "<I>– Rester calme et se taire, inutile d’attirer plus encore l’attention de la Légion.</>",
            ["DialogueId"] = 10113026,
            ["GUID"] = "10113026",
            ["ImprPlusId"] = 1006,
            ["NextDialogue"] = 10113027,
            },
        [10113027] = {
            ["Camera"] = "-139.688477,-91.050781,121.101562,-4.000003,8.402478,-13.154885,35.0,104.579765,false,Manual,4.0",
            ["Content"] = "……我们走吧。",
            ["ContentFR"] = "... Partons.",
            ["DialogueId"] = 10113027,
            ["ExStoryInfo"] = "Player",
            ["FacialId"] = {
                [1] = "100001:Sad01",
                },
            ["GUID"] = "1951202B",
            ["LookAt"] = {
