        [10113032] = {
            ["Camera"] = "-238.606445,-234.828125,126.856445,0.000532,0.099973,-152.555771,16.0,165.460846,false,Manual,1.90943",
            ["Content"] = "你在说什么鬼话，你护着秽兽？黎瑟长官，这独眼龙真的有问题，得抓回去好好审审——",
            ["ContentFR"] = "De quoi tu parles ? Tu prends la défense d’une Souillé ? Madame, {性别:ce|cette} borgne est louche, il faudrait l’emmener et l’interroger—",
            ["DialogueId"] = 10113032,
            ["GUID"] = "1951202F",
            ["LookAt"] = {
                [1] = "100001:n(700065)",
                },
            ["NextDialogue"] = 10113033,
