        [10113108] = {
            ["Camera"] = "166.950943,133.818985,133.208984,-1.5,-19.999264,-177.415726,30.0,246.856323,false,Manual,3.0",
            ["Content"] = "不过，还有另外一件重要的事。",
            ["ContentFR"] = "Mais il y a une chose encore plus importante.",
            ["DialogueId"] = 10113108,
            ["FacialId"] = {
                [1] = "200021:None",
                },
            ["GUID"] = "19512D9F",
            ["LookAt"] = {
