                [1] = "200021:Think_Start",
                },
            ["ToFinalCameraBlendTime"] = 2.5,
            ["VoiceName"] = "voice/$Locale$/story/1002/101131/19512DA0",
            },
        [10113110] = {
            ["Camera"] = "-246.400757,844.10083,-61.849609,-3.000001,7.500012,-65.621231,25.0,178.229309,false,DoNotOverride,3.0",
            ["Content"] = "她……是被你唤醒的？那时你用的魔法是……<H>和鸣之力</>。对吗？",
            ["ContentFR"] = "C’est toi... qui l’as éveillée ? La magie que tu as utilisée... c’était bien la <H>Résonance</> ?",
            ["DialogueId"] = 10113110,
            ["GUID"] = "19512DA1",
            ["NextDialogue"] = 10113111,
            ["SpeakNpcId"] = 200021,
            ["TalkActionId"] = {
                [1] = "200021:Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101131/19512DA1",
            },
        [10113111] = {
            ["Camera"] = "84.234695,111.816925,115.09082,3.000676,-18.599718,162.972107,35.000011,144.631561,false,Manual,4.5",
            ["Content"] = "……！你是怎么……",
            ["ContentFR"] = "... ! Comment tu—",
            ["DialogueId"] = 10113111,
