}",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101131/19512DA2",
            },
        [10113112] = {
            ["Camera"] = "503.927185,-581.604065,75.886719,3.000298,-2.200072,111.878609,30.0,144.631561,false,DoNotOverride,4.5",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "别紧张，我不会追问你的过去。但接下来这件事，你要牢记——",
            ["ContentFR"] = "Pas de panique. Je ne chercherai pas à fouiller ton passé. Mais grave bien mes mots...",
            ["DialogueId"] = 10113112,
            ["FacialId"] = {
                [1] = "200021:None",
                },
            ["FinalCamera"] = "531.06842,-592.664917,77.799805,3.000269,-2.200072,113.980644,30.0,144.631561,false,DoNotOverride,4.5",
