}",
            ["SpeakNpcId"] = 200054,
            ["VoiceName"] = "voice/$Locale$/story/1002/101173/1953DDB2",
            },
        [10117303] = {
            ["Camera"] = "99.868393,-250.259125,175.274902,0.000025,-25.999838,135.993896,35.0,246.462189,false,Manual,2.6",
            ["Content"] = "我不是小妹！是魔王！",
            ["ContentFR"] = "Je ne suis pas une acolyte ! Je suis le Roi Démon !",
            ["DialogueId"] = 10117303,
            ["FacialId"] = {
                [1] = "200002:Shock02",
                },
            ["GUID"] = "1953DDDC",
            ["LookAt"] = {
                [1] = "200011:n(200002)",
                [2] = "200054:n(200002)",
                },
            ["NextDialogue"] = 10117304,
            ["Scripts"] = "PlayAnimation{_delay{1.5},ActorId{100001},AnimationId{\"Talk03_Start\"},Duration{1}}",
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Angry01_Start",
                [2] = "200011:Sigh_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101173/1953DDDC",
            },
        [10117304] = {
            ["Camera"] = "-84.425522,47.435509,57.425781,0.000151,11.599348,-73.994087,35.000008,278.919617,false,Manual,3.0",
            ["Content"] = "哦……那就是垃圾桶小魔王？",
            ["ContentFR"] = "Ah... alors tu es le \"Roi Démon des Déchets\" ?",
            ["DialogueId"] = 10117304,
            ["GUID"] = "1953DE06",
            ["LookAt"] = {
                [1] = "200011:n(200002)",
                },
            ["NextDialogue"] = 10117305,
            ["SpeakNpcId"] = 200054,
            ["TalkActionId"] = {
                [1] = "200011:Sigh_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101173/1953DE06",
            },
        [10117305] = {
            ["Camera"] = "206.001495,-142.157104,81.942383,0.000148,2.199983,176.390671,35.000008,303.843719,false,DoNotOverride,1.715777",
            ["Content"] = "不是啦，是“光之魔王”！",
            ["ContentFR"] = "Non ! C’est le \"Roi Démon de la Lumière\" !",
            ["DialogueId"] = 10117305,
            ["FacialId"] = {
                [1] = "200002:Doubt01",
                },
            ["GUID"] = "1953DE30",
            ["LookAt"] = {
                [1] = "100001:n(200011)",
                [2] = "200011:n(100001)",
                },
            ["NextDialogue"] = 10117306,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Confident_Start",
                [2] = "200011:Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101173/1953DE30",
            },
        [10117306] = {
            ["Camera"] = "114.257248,-212.611359,148.254395,0.000174,-12.397339,160.570602,24.0,208.790619,false,Manual,2.5",
            ["Content"] = "啊哈哈哈……先别管这个了，爷爷啊，您看没看到一个黑头发、蓝衣服的卡戎男人从这里跑过去？",
            ["ContentFR"] = "Ahahaha... laissons ça de côté pour l’instant. Monsieur Badi, vous n’avez pas vu un Charon aux cheveux noirs et au haut bleu passer par ici ?",
            ["DialogueId"] = 10117306,
            ["FacialId"] = {
                [1] = "200011:Ahaha02",
                },
            ["GUID"] = "1953DE5A",
            ["LookAt"] = {
                [1] = "200054:n(200011)",
                [2] = "100001:n(200054)",
                },
            ["NextDialogue"] = 10117307,
            ["Scripts"] = "SEQ{\
LookAt{_delay{1},LookAtDescription{\"200011:n(200054)\"}},\
PlayAnimation{_delay{1},ActorId{200011},AnimationId{\"Explain01_Start\"},Duration{2}}\
}",
            ["SpeakNpcId"] = 200011,
            ["TalkActionId"] = {
                [1] = "100001:Talk03_End",
                [2] = "200011:Talk01_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101173/1953DE5A",
            },
        [10117307] = {
            ["Content"] = "刚刚确实有个小伙子跑过去了。年轻人冒冒失失的，走路也不看路，直冲着<H>雾区</>堆垃圾那块儿去了！呀，他该不会是——要抢你生意？",
            ["ContentFR"] = "Oui, un jeune homme vient juste de passer. Tout maladroit, sans regarder où il marchait, il est allé droit vers la poubelle dans <H>Brumelac</> ! Attends... il ne serait pas en train de te piquer ton gagne-pain ?",
            ["DialogueId"] = 10117307,
            ["GUID"] = "1953DE84",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10117307.T_Story_Recall_10117307'",
            ["NextDialogue"] = 10117308,
            ["SpeakNpcId"] = 200054,
            ["VoiceName"] = "voice/$Locale$/story/1002/101173/1953DE84",
            },
        [10117308] = {
            ["Content"] = "呃……算是吧！谢啦，我这就追他去。",
            ["ContentFR"] = "Euh... en quelque sorte ! Merci, je le poursuis.",
            ["DialogueId"] = 10117308,
            ["FacialId"] = {
                [1] = "200011:Happy01",
                },
            ["GUID"] = "1953DEAE",
            ["Scripts"] = "SEQ{\
PlayAnimation{_delay{2},ActorId{200011},AnimationId{\"Explain01_End\"},Duration{1}},\
PlayAnimation{ActorId{200011},AnimationId{\"AgreeHead\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 200011,
            ["TalkActionId"] = {
                [1] = "100001:AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101173/1953DEAE",
            },
        [10117401] = {
            ["Content"] = "雾区堆放垃圾的地方……",
            ["ContentFR"] = "La poubelle dans Brumelac...",
            ["DialogueId"] = 10117401,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "1953EE1A",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10117402,
            ["SpeakNpcId"] = 100001,
            },
        [10117402] = {
            ["Content"] = "他说的是3号大垃圾箱！跟我来！",
            ["ContentFR"] = "Il veut dire la grosse poubelle n° 3 ! Suis-moi !",
            ["DialogueId"] = 10117402,
            ["Duration"] = 3,
            ["GUID"] = "1953EE44",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200011,
            ["VoiceName"] = "voice/$Locale$/story/1002/101174/1953EE44",
            },
        [10117501] = {
            ["Content"] = "去吧去吧……老话怎么说的来着？“早起的鸟儿有垃圾捡！”",
            ["ContentFR"] = "Allez, filez... comme on dit, « le monde appartient à ceux qui fouillent les poubelles tôt le matin ! »",
            ["DialogueId"] = 10117501,
            ["GUID"] = "1953FE82",
            ["SpeakNpcId"] = 200054,
            ["VoiceName"] = "voice/$Locale$/story/1002/101175/1953FE82",
            },
        [10117601] = {
            ["Content"] = "这一带没有人。",
            ["ContentFR"] = "Il n’y a personne par ici.",
            ["DialogueId"] = 10117601,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "19540EEA",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10117602,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101176/19540EEA",
            },
        [10117602] = {
            ["Content"] = "……没关系！灵敏的“侦探”嗅觉告诉我，这附近一定能找到线索！",
            ["ContentFR"] = "... Pas de souci ! Mon flair de détective me dit qu’il y a un indice dans le coin !",
            ["DialogueId"] = 10117602,
            ["Duration"] = 3,
            ["GUID"] = "19540F14",
            ["GuideFacialId"] = "Confident",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200011,
            ["VoiceName"] = "voice/$Locale$/story/1002/101176/19540F14",
            },
        [10117701] = {
            ["Camera"] = "-410.567871,424.552368,74.604492,0.000115,4.799778,-44.802727,25.000002,100000.0,false,Disable,2.8",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "涂鸦墙边的箱子叠了两层……底层箱子被斜过来了，表面还有凌乱的成年男性脚印——哼哼，被我看穿了！",
            ["ContentFR"] = "Deux caisses empilées... celle du bas est de travers, avec des traces de pas d’adulte un peu partout — <I>hum hum,</> c’est évident !",
            ["DialogueId"] = 10117701,
            ["FinalCamera"] = "-410.567871,424.552368,74.604492,0.000105,8.599781,-41.002731,25.000002,100000.0,false,Disable,2.8",
            ["GUID"] = "19541F52",
            ["NextDialogue"] = 10117702,
            ["Scripts"] = "PlayAnimation{_delay{1.5},ActorId{200011},AnimationId{\"Think_Start\"},Duration{1}}",
            ["SpeakNpcId"] = 200011,
            ["TalkActionId"] = {
                [1] = "100001:Talk03_Start",
                },
            ["ToFinalCameraBlendTime"] = 3.5,
            ["VoiceName"] = "voice/$Locale$/story/1002/101177/19541F52",
            },
        [10117702] = {
            ["Content"] = "咳，根据证人玛尔洁的证词，今天早上她来3号大垃圾箱“进货”的时候，才刚把这边的箱子横着摆好。",
            ["ContentFR"] = "<I>Hum,</> d’après le témoignage de Margie, la témoin, elle venait juste de remettre ces caisses à l’horizontale ce matin en faisant ses \"courses\" à la grosse poubelle n° 3. ",
            ["DialogueId"] = 10117702,
            ["GUID"] = "19541F7C",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10117702.T_Story_Recall_10117702'",
            ["NextDialogue"] = 10117703,
            ["SpeakNpcId"] = 200011,
            ["TalkActionId"] = {
                [1] = "100001:Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101177/19541F7C",
            },
        [10117703] = {
            ["Camera"] = "83.220734,36.439808,97.523438,0.000132,10.199651,-171.604935,35.0,144.288223,false,Manual,2.5",
            ["Content"] = "所以，“缄默侦探”玛尔洁的推理显而易见——小贼情急之下把这些箱子叠了起来，踩着它们爬上了墙！他很可能藏在天台上！",
            ["ContentFR"] = "Donc, déduction de Margie, la Détective Taciturne, le voleur a empilé ces caisses à la hâte pour grimper au mur ! Il doit sûrement être sur le toit ! ",
            ["DialogueId"] = 10117703,
            ["FinalCamera"] = "48.795158,31.354404,106.438965,0.000132,10.199651,-171.604935,35.0,107.665878,false,Manual,2.5",
            ["GUID"] = "19541FA6",
            ["NextDialogue"] = 10117704,
            ["Scripts"] = "SEQ{\
PlayAnimation{_delay{3},ActorId{200011},AnimationId{\"Think_End\"},Duration{1}},\
PlayAnimation{ActorId{200011},AnimationId{\"Talk03_Start\"},Duration{1}},\
PlayFacial{_delay{6},ActorId{200011},FacialId{\"Happy01\"}}\
}",
            ["SpeakNpcId"] = 200011,
            ["ToFinalCameraBlendTime"] = 15,
            ["VoiceName"] = "voice/$Locale$/story/1002/101177/19541FA6",
            },
        [10117704] = {
            ["Camera"] = "-2114.584229,613.182617,98.33252,0.000144,1.892338,-19.423639,35.000008,732.249939,false,DoNotOverride,1.2",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "哦！有道理耶！我们也爬上去看看吧。",
            ["ContentFR"] = "Oh ! Ça tient la route ! Allons voir là-haut !",
            ["DialogueId"] = 10117704,
            ["FinalCamera"] = "-2097.467041,661.715881,98.33252,0.000144,1.892338,-19.423639,35.000008,732.249939,false,DoNotOverride,1.2",
            ["GUID"] = "19541FD0",
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200011:Talk03_End",
                [2] = "200002:Confident_Start",
                },
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/1002/101177/19541FD0",
            },
        [10117801] = {
            ["Content"] = "原来“缄默侦探”就是玛尔洁的称号啊，还挺威风的……只可惜有点短，气势上输了一截！",
            ["ContentFR"] = "Donc \"Détective Taciturne\", c’est ton titre, Margie ? Pas mal... mais un peu court, ça manque d’impact !",
            ["DialogueId"] = 10117801,
            ["Duration"] = 3,
            ["GUID"] = "19542FBA",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10117802,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101178/19542FBA",
            },
        [10117802] = {
            ["Content"] = "有道理！那魔王小妹你有什么主意吗？",
            ["ContentFR"] = "Pas faux ! Alors, Roi Démon, une idée ?",
            ["DialogueId"] = 10117802,
            ["Duration"] = 3,
            ["GUID"] = "19542FE4",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10117803,
            ["SpeakNpcId"] = 200011,
            ["VoiceName"] = "voice/$Locale$/story/1002/101178/19542FE4",
            },
        [10117803] = {
            ["Content"] = "刚才那个老爷爷说的“垃圾桶公主”就挺不错的？",
            ["ContentFR"] = "Le vieil homme tout à l’heure t’a appelé \"Princesse des Déchets\"... Pas mal comme titre, non ?",
            ["DialogueId"] = 10117803,
            ["Duration"] = 3,
            ["GUID"] = "1954300E",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10117804,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101178/1954300E",
            },
        [10117804] = {
            ["Content"] = "“缄默侦探☆垃圾桶公主”，气势是不是突然就上去啦！",
            ["ContentFR"] = "\"Princesse des Déchets ☆ La Détective Taciturne\", ça claque non !",
            ["DialogueId"] = 10117804,
            ["Duration"] = 3,
            ["GUID"] = "19543038",
            ["GuideFacialId"] = "Confident",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10117805,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101178/19543038",
            },
        [10117805] = {
            ["Content"] = "啊——！不要不要，不要再提那几个字了，丢死人了！",
            ["ContentFR"] = "Ah—! Non, non, stop ! Ne répète plus ce surnom, c’est trop embarrassant !",
            ["DialogueId"] = 10117805,
            ["Duration"] = 3,
            ["GUID"] = "19543062",
            ["GuideFacialId"] = "Afraid",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200011,
            ["VoiceName"] = "voice/$Locale$/story/1002/101178/19543062",
            },
        [10117901] = {
            ["Camera"] = "441.521088,-620.674683,187.3125,0.000037,-5.799861,111.19696,25.0,850.802856,false,Manual,1.2",
            ["CameraBlendCurve"] = "easeOutQuad",
            ["Content"] = "怎么了，垃圾桶里有什么吗？",
            ["ContentFR"] = "Quoi ? Il y a quelque chose dans la poubelle ?",
            ["DialogueId"] = 10117901,
            ["FinalCamera"] = "441.521088,-620.674683,164.277588,0.000037,-5.799861,111.19696,25.0,850.802856,false,Manual,1.2",
            ["GUID"] = "19544022",
            ["NextDialogue"] = 10117902,
            ["SpeakNpcId"] = 200011,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/story/1002/101179/19544022",
            },
        [10117902] = {
            ["Camera"] = "25.164871,87.383209,131.531006,0.000057,-2.19986,-60.40377,25.0,225.91423,false,Manual,1.6",
            ["Content"] = "我只是想确认一下他有没有藏在——",
            ["ContentFR"] = "Je voulais juste vérifier s’il ne se cachait pas...",
            ["DialogueId"] = 10117902,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "1954404C",
            ["LookAt"] = {
                [1] = "200011:n(100001)",
                [2] = "100001:n(200011)",
                },
            ["NextDialogue"] = 10117903,
            ["Scripts"] = "SetLocation{ActorId{200002},TargetPoint{\"P101179Bai1\"},Visibility{\"Hide\"}}",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101179/1954404C",
            },
        [10117903] = {
            ["Camera"] = "14.791107,54.489399,135.432129,0.000058,-2.399801,-63.204136,35.0,189.973221,false,Manual,4.0",
            ["Content"] = "啊——！那是……半瓶葡萄酒和一枚古董胸针？！天哪，难道你就是被垃圾桶之神眷顾的天选之人？！",
            ["ContentFR"] = "Ouuuah ! C’est... une demi-bouteille de vin et une broche antique ?! Bon sang, tu serais donc l’{性别:élu|élue} du dieu des poubelles ?!",
            ["DialogueId"] = 10117903,
            ["FacialId"] = {
                [1] = "200011:Shock01",
                },
            ["GUID"] = "19544076",
            ["LookAt"] = {
                [1] = "200011:n(200011)",
                },
            ["NextDialogue"] = 10117904,
            ["SpeakNpcId"] = 200011,
            ["TalkActionId"] = {
                [1] = "200011:Shock_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101179/19544076",
            },
        [10117904] = {
            ["Camera"] = "282.696777,274.406219,171.463379,0.000081,-11.800018,-126.601822,20.0,385.634796,false,Manual,1.2",
            ["Content"] = "可恶，偏偏在这个节骨眼上……你等我一下！",
            ["ContentFR"] = "Mince... pile au mauvais moment... Attends-moi ! ",
            ["DialogueId"] = 10117904,
            ["FacialId"] = {
                [1] = "100001:Shock01",
                [2] = "200002:Shock01",
                },
            ["GUID"] = "195440A0",
            ["LookAt"] = {
                [1] = "200002:n(200011)",
                },
            ["NextDialogue"] = 10117905,
            ["Scripts"] = "PARA{\
