            ["SpeakNpcId"] = 200011,
            ["TalkActionId"] = {
                [1] = "200011:Shock_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101179/195440A0",
            },
        [10117905] = {
            ["Content"] = "（玛尔洁从废品堆里扯出两张旧报纸，把刚找到的宝贝小心翼翼地包了起来，放在角落里。）",
            ["ContentFR"] = "Margie extirpe deux vieux journaux d’un tas de rebuts, enveloppe avec le plus grand soin les petits trésors qu’elle vient de trouver, puis les dépose dans un coin.",
            ["DialogueId"] = 10117905,
            ["DisableMouth"] = 1,
            ["Duration"] = 4,
            ["GUID"] = "195440CA",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 10117906,
            ["Scripts"] = "PARA{\
SetLocation{ActorId{200002},TargetPoint{\"P101179Bai2\"},Visibility{\"Show\"}},\
PlayNormalSound{_delay{2},EventPath{\"event:/sfx/common/story/01/searchtrash\"},PlayAs2D{true}}\
}",
            ["VoiceName"] = "voice/$Locale$/story/1002/101179/195440CA",
            },
        [10117906] = {
            ["Camera"] = "-97.681335,235.033142,214.595215,0.000114,-15.999267,-53.001629,35.0,124.611694,false,DoNotOverride,2.2",
            ["Content"] = "好嘞，这样就没问题了！等我抓完小贼再回来收货。见者有份，等小贼的事儿搞定，葡萄酒也分你一半！",
            ["ContentFR"] = "Voilà, c’est bon ! Je reviendrai les chercher après avoir attrapé le voleur. Ce que tu trouves, c’est pour toi. Une fois le voleur arrêté, je partagerai le vin avec toi !",
            ["DialogueId"] = 10117906,
            ["FacialId"] = {
                [1] = "200011:Smile02",
                },
            ["GUID"] = "195440F4",
            ["LookAt"] = {
                [1] = "100001:n(200011)",
                [2] = "200002:n(200011)",
                },
            ["NextDialogue"] = 10117907,
            ["SpeakNpcId"] = 200011,
            ["TalkActionId"] = {
                [1] = "200011:SpecialHoldHelmet_Start",
                [2] = "200002:SpecialHappy_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101179/195440F4",
            },
        [10117907] = {
            ["Content"] = "呃……这个就不用了！",
            ["ContentFR"] = "Euh... je pense que je vais passer mon tour, merci.",
            ["DialogueId"] = 10117907,
            ["ExStoryInfo"] = "Player",
            ["FacialId"] = {
                [1] = "100001:Ahaha02",
                },
            ["GUID"] = "1954411E",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101179/1954411E",
            },
        [10118001] = {
            ["Content"] = "才刚有个人爬上来，怎么又来三个？",
            ["ContentFR"] = "Quelqu’un vient juste de monter, et maintenant trois autres ? Que se passe-t-il ?",
            ["DialogueId"] = 10118001,
            ["Duration"] = 3,
            ["GUID"] = "1954508A",
            ["SpeakNpcId"] = 200055,
            ["VoiceName"] = "voice/$Locale$/story/1002/101180/1954508A",
            },
        [10118101] = {
            ["Content"] = "最近这是怎么了，总有人在城里飞檐走壁。冰湖城是有什么运动赛吗？爬得快有奖那种？",
            ["ContentFR"] = "C’est quoi ce délire ? Tout le monde grimpe partout dans Givrelac. Y a un concours ou quoi ?",
            ["DialogueId"] = 10118101,
            ["GUID"] = "195460F2",
            ["NextDialogue"] = 10118102,
            ["SpeakNpcId"] = 200055,
            ["VoiceName"] = "voice/$Locale$/story/1002/101181/195460F2",
            },
        [10118102] = {
            ["Content"] = "呃……这么说来，好像确实有个皎皎前辈设过类似的挑战？",
            ["ContentFR"] = "Euh... à ce qu’il paraît, un vieux Luno avait organisé un défi similaire...",
            ["DialogueId"] = 10118102,
            ["GUID"] = "1954611C",
            ["NextDialogue"] = 10118103,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101181/1954611C",
            },
        [10118103] = {
            ["Content"] = "那你们快追吧！刚才那位选手都跑过去半天啦。",
            ["ContentFR"] = "Alors dépêchez-vous ! L’autre participant est déjà parti depuis un moment.",
            ["DialogueId"] = 10118103,
            ["GUID"] = "19546146",
            ["SpeakNpcId"] = 200055,
            ["VoiceName"] = "voice/$Locale$/story/1002/101181/19546146",
            },
        [10118201] = {
            ["Content"] = "啊，快看，就是前面屋顶上那家伙！",
            ["ContentFR"] = "Ah, regardez, c’est lui là-bas sur le toit !",
            ["DialogueId"] = 10118201,
            ["Duration"] = 3,
            ["GUID"] = "1954715A",
            ["GuideFacialId"] = "Angry",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200011,
            ["VoiceName"] = "voice/$Locale$/story/1002/101182/1954715A",
            },
        [10118202] = {
            ["Camera"] = "-476.057983,-45.540398,533.046387,0.000058,-4.400117,156.809341,35.000008,241.278336,false,Manual,4.2",
            ["Content"] = "你、你……至于追到这种地方来吗？你说你那钱本来就是拿来分给别人的，那分老子一点怎么了？",
            ["ContentFR"] = "Tu... tu devais vraiment me poursuivre jusqu’ici ? Tu as dit que tu allais partager l’argent avec les pauvres de toute façon, alors pourquoi je ne peux pas en avoir une part ?",
            ["DialogueId"] = 10118202,
            ["GUID"] = "19547184",
            ["LookAt"] = {
                [1] = "200002:n(200053)",
                [2] = "200053:n(100001)",
                [3] = "100001:n(200053)",
                [4] = "200011:n(200053)",
                },
            ["NextDialogue"] = 10118203,
            ["Scripts"] = "PARA{\
MoveTo{ActorId{100001},TargetPoint{\"P101182Nvzhu1\"},MoveSpeed{220},Visibility{\"Show\"}},\
MoveTo{ActorId{200011},TargetPoint{\"P101182Maer1\"},MoveSpeed{240},Visibility{\"Show\"}},\
MoveTo{ActorId{200002},TargetPoint{\"P101182Bai1\"},MoveSpeed{210},Visibility{\"Show\"}}\
}",
            ["SpeakNpcId"] = 200053,
            ["SpeakNpcName"] = "UI_Npc_Name_Man_12",
            ["TalkActionId"] = {
                [1] = "200053:Angry01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101182/19547184",
            },
        [10118203] = {
            ["Camera"] = "-845.377014,-25.232204,629.145264,0.000027,-33.600269,4.611965,28.874323,1077.120361,false,Manual,4.2",
            ["Content"] = "你有困难我可以帮你，但直接上手抢，那就吃我一铲！",
            ["ContentFR"] = "Si tu es dans le pétrin, je peux t’aider. Mais si tu touches à l’argent des gens, tu vas goûter à ma pelle !",
            ["DialogueId"] = 10118203,
            ["FacialId"] = {
                [1] = "200011:Angry01",
                },
            ["GUID"] = "195471AE",
            ["SpeakNpcId"] = 200011,
            ["TalkActionId"] = {
                [1] = "200011:Angry01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101182/195471AE",
            },
        [10118204] = {
            ["Content"] = "（青年似乎找不到反驳的话，气急败坏地跳下了墙。）",
            ["ContentFR"] = "Le jeune homme, visiblement à court d’arguments, saute du mur dans un accès de dépit.",
            ["DialogueId"] = 10118204,
            ["DisableMouth"] = 1,
            ["GUID"] = "195471D8",
            ["VoiceName"] = "voice/$Locale$/story/1002/101182/195471D8",
            },
        [10118301] = {
            ["Content"] = "又、又不见了？他是幽灵吗？",
            ["ContentFR"] = "Encore... encore disparu ? C’est quoi, un fantôme ?",
            ["DialogueId"] = 10118301,
            ["Duration"] = 3,
            ["GUID"] = "195481C2",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10118303,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101183/195481C2",
            },
        [10118302] = {
            ["Content"] = "不……你们看，这面井盖有被挪动过的痕迹。",
            ["ContentFR"] = "Non... regardez. Cette plaque d’égout a été déplacée.",
            ["DialogueId"] = 10118302,
            ["Duration"] = 3,
            ["GUID"] = "195481EC",
            ["GuideFacialId"] = "Angry",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10118303,
            ["SpeakNpcId"] = 200011,
            ["VoiceName"] = "voice/$Locale$/story/1002/101183/195481EC",
            },
        [10118303] = {
            ["Content"] = "以我的推测，他一定钻进了下水道！",
            ["ContentFR"] = "À mon avis, il s’est glissé dans les égouts !",
            ["DialogueId"] = 10118303,
            ["Duration"] = 3,
            ["GUID"] = "19548216",
            ["GuideFacialId"] = "Confident",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200011,
            ["VoiceName"] = "voice/$Locale$/story/1002/101183/19548216",
            },
        [10118401] = {
            ["Content"] = "这么深的水……根本就过不去吧！他怎么做到的？",
            ["DialogueId"] = 10118401,
            ["Duration"] = 3,
            ["GUID"] = "1954922A",
            ["GuideFacialId"] = "Afraid",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10118402,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101184/1954922A",
            },
        [10118402] = {
            ["Content"] = "别急，这种时候就该动用本“缄默侦探”的情报网了！",
            ["DialogueId"] = 10118402,
            ["Duration"] = 3,
            ["GUID"] = "19549254",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10118403,
            ["SpeakNpcId"] = 200011,
            ["VoiceName"] = "voice/$Locale$/story/1002/101184/19549254",
            },
        [10118403] = {
            ["Content"] = "根据8号小桶产出的《下水道维修手册》，这里的水位是可以人为控制的！机关一定就在附近。",
            ["DialogueId"] = 10118403,
            ["Duration"] = 3,
            ["GUID"] = "1954927E",
            ["GuideFacialId"] = "Confident",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200011,
            ["VoiceName"] = "voice/$Locale$/story/1002/101184/1954927E",
            },
        [10118501] = {
            ["Content"] = "哇——真的有排水机关。垃圾桶公主☆缄默侦探，你好有本领！",
            ["DialogueId"] = 10118501,
            ["Duration"] = 3,
            ["GUID"] = "1954A292",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10118502,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101185/1954A292",
            },
        [10118502] = {
            ["Content"] = "去掉前面那半，拜托了……呜呜。",
            ["DialogueId"] = 10118502,
            ["Duration"] = 3,
            ["GUID"] = "1954A2BC",
            ["GuideFacialId"] = "Sad",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10118503,
            ["SpeakNpcId"] = 200011,
            ["VoiceName"] = "voice/$Locale$/story/1002/101185/1954A2BC",
            },
        [10118503] = {
            ["Content"] = "水位下降了一部分，找找还有没有类似的开关吧。",
            ["DialogueId"] = 10118503,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "1954A2E6",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101185/1954A2E6",
            },
        [10118601] = {
            ["Content"] = "快看，下边真有路哎！",
            ["DialogueId"] = 10118601,
            ["Duration"] = 3,
            ["GUID"] = "1954B2FA",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101186/1954B2FA",
            },
        [10118602] = {
            ["Content"] = "对了，《下水道维修手册》里写过，下水道偶尔会招来一些喜欢温暖湿润的秽兽栖身。",
            ["DialogueId"] = 10118602,
            ["Duration"] = 3,
            ["GUID"] = "1954B324",
            ["GuideFacialId"] = "Afraid",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200011,
            ["VoiceName"] = "voice/$Locale$/story/1002/101186/1954B324",
            },
        [10118603] = {
            ["Content"] = "虽然这些秽兽是体格最弱小的那种，快跟猫猫狗狗差不多了，但如果成群结队行动，还是会有点危险……",
            ["ContentFR"] = "Ils sont pas bien gros, à peu près comme des chats ou des chiens, mais en meute, ça peut devenir dangereux...",
            ["DialogueId"] = 10118603,
            ["Duration"] = 3,
            ["GUID"] = "1954B34E",
            ["GuideFacialId"] = "Sad",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10118604,
            ["SpeakNpcId"] = 200011,
            ["VoiceName"] = "voice/$Locale$/story/1002/101186/1954B34E",
            },
        [10118604] = {
            ["Content"] = "我们准备好再前进吧！",
            ["ContentFR"] = "Préparons-nous bien avant d’avancer plus loin !",
            ["DialogueId"] = 10118604,
            ["Duration"] = 3,
            ["GUID"] = "1954B378",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200011,
            ["VoiceName"] = "voice/$Locale$/story/1002/101186/1954B378",
            },
        [10118701] = {
            ["Content"] = "乖乖站住！不许跑！",
            ["DialogueId"] = 10118701,
            ["Duration"] = 3,
            ["GUID"] = "1954C362",
            ["GuideFacialId"] = "Angry",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10118702,
            ["SpeakNpcId"] = 200011,
            ["VoiceName"] = "voice/$Locale$/story/1002/101187/1954C362",
            },
        [10118702] = {
            ["Content"] = "呼……呼……你们几个腿长的……等等我……",
            ["DialogueId"] = 10118702,
            ["Duration"] = 3,
            ["GUID"] = "1954C38C",
            ["GuideFacialId"] = "Afraid",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101187/1954C38C",
            },
        [10118801] = {
            ["Content"] = "咳、咳……呛死我了……好卑鄙……",
            ["DialogueId"] = 10118801,
            ["Duration"] = 3,
            ["GUID"] = "1954D3CA",
            ["GuideFacialId"] = "Sad",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200011,
            ["VoiceName"] = "voice/$Locale$/story/1002/101188/1954D3CA",
            },
        [10118901] = {
            ["Content"] = "听到脚步声了，这边这边！",
            ["DialogueId"] = 10118901,
            ["Duration"] = 3,
            ["GUID"] = "1954E432",
            ["GuideFacialId"] = "Confident",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200011,
            ["VoiceName"] = "voice/$Locale$/story/1002/101189/1954E432",
            },
        [10119001] = {
            ["Content"] = "刚才有什么飞过来了……",
            ["DialogueId"] = 10119001,
            ["Duration"] = 3,
            ["GUID"] = "1954F49A",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10119002,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101190/1954F49A",
            },
        [10119002] = {
            ["Content"] = "呜啊……疼疼疼！是石头！",
            ["DialogueId"] = 10119002,
            ["Duration"] = 3,
            ["GUID"] = "1954F4C4",
            ["GuideFacialId"] = "Afraid",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101190/1954F4C4",
            },
        [10119101] = {
            ["Content"] = "他在高处！哼，这次我不会再被砸到——呜哇！",
            ["DialogueId"] = 10119101,
            ["Duration"] = 3,
            ["GUID"] = "19550502",
            ["GuideFacialId"] = "Afraid",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10119102,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101191/19550502",
            },
        [10119102] = {
            ["Content"] = "真是的……这么爱扔石头，他是猴子变的吗？",
            ["DialogueId"] = 10119102,
            ["Duration"] = 3,
            ["GUID"] = "1955052C",
            ["GuideFacialId"] = "Angry",
