        [10120401] = {
            ["Content"] = "那边是泪湖诶，我们不是说好要进城吗？",
            ["ContentFR"] = "Hé, là-bas c’est le Lac du Deuil ! On n’avait pas dit qu’on allait en ville ?",
            ["DialogueId"] = 10120401,
            ["GUID"] = "1955DA4A",
            ["NextDialogue"] = 10120402,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101204/1955DA4A",
            },
        [10120402] = {
            ["Content"] = "一个人乱转很危险的！快回来，白在这儿等你！",
            ["ContentFR"] = "Errer {性别:tout seul|toute seule} comme ça, c’est dangereux ! Reviens vite, Snow t’attend ici !",
            ["DialogueId"] = 10120402,
            ["GUID"] = "1955DA74",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101204/1955DA74",
            },
        [10120501] = {
            ["Content"] = "你要去哪儿呀，我们不是说好要进城吗？",
            ["ContentFR"] = "Hé, où tu vas ? La ville, c’est de ce côté !",
            ["DialogueId"] = 10120501,
            ["GUID"] = "1955EAB2",
            ["NextDialogue"] = 10120502,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101205/1955EAB2",
            },
        [10120502] = {
            ["Content"] = "那边有好多好多秽兽，你会被吃掉的！快到白这边来！",
            ["ContentFR"] = "Là-bas, c’est infesté de Souillés, ils vont t’avaler tout cru ! Viens vite par ici !",
            ["DialogueId"] = 10120502,
            ["GUID"] = "1955EADC",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101205/1955EADC",
            },
        [10120601] = {
            ["Content"] = "（这就是“城市”吗，还是第一次见到……）",
            ["ContentFR"] = "<I>Alors c’est ça, une \"cité\"... Je n’en avais jamais vu avant.</>",
            ["DialogueId"] = 10120601,
            ["DisableMouth"] = 1,
            ["GUID"] = "1955FB1A",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10120602,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101206/1955FB1A",
            },
        [10120602] = {
            ["Content"] = "（可接下来去哪儿，完全没有头绪……还是先找到白和那位卡米拉女士吧。）",
            ["ContentFR"] = "<I>Mais où aller maintenant ?... Je ferais mieux de retrouver Snow et cette Madame Camilla.</>",
            ["DialogueId"] = 10120602,
            ["DisableMouth"] = 1,
            ["GUID"] = "1955FB44",
            ["GuideFacialId"] = "Sad",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101206/1955FB44",
            },
        [10120701] = {
            ["Content"] = "呜哇哇，过不去了！怎么回事，连下水道也在和我们作对……",
            ["DialogueId"] = 10120701,
            ["GUID"] = "19560B82",
            ["GuideFacialId"] = "Sad",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10120702,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101207/19560B82",
            },
        [10120702] = {
            ["Content"] = "让“缄默侦探”看看——这里有个水阀！他一定对水阀做了手脚！",
            ["DialogueId"] = 10120702,
            ["GUID"] = "19560BAC",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10120703,
            ["SpeakNpcId"] = 200011,
            ["VoiceName"] = "voice/$Locale$/story/1002/101207/19560BAC",
            },
        [10120703] = {
