            ["GUID"] = "19560BD6",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101207/19560BD6",
            },
        [10120801] = {
