            },
        [10121201] = {
            ["Content"] = "这些湿漉漉的脚印，看尺寸，应该就是那个贼留下的吧。",
            ["DialogueId"] = 10121201,
            ["GUID"] = "19565D8A",
            ["GuideFacialId"] = "Angry",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10121202,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101212/19565D8A",
            },
        [10121202] = {
            ["Content"] = "唔，这些秽兽是被刚刚的爆炸声引来的吗？",
            ["DialogueId"] = 10121202,
            ["GUID"] = "19565D8B",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101212/19565D8B",
            },
        [10121301] = {
            ["Content"] = "总觉得这块木板怪怪的，也许不要踩为好。",
            ["DialogueId"] = 10121301,
            ["GUID"] = "19566DF2",
            ["GuideFacialId"] = "Sad",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101213/19566DF2",
            },
        [10121302] = {
            ["Content"] = "是爆炸声！小仆从，你也中陷阱了吗？！",
            ["DialogueId"] = 10121302,
            ["GUID"] = "19566DF3",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10121303,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101213/19566DF3",
            },
        [10121303] = {
            ["Content"] = "没事！咳，我只是想试试这块木板牢不牢固。",
            ["DialogueId"] = 10121303,
            ["GUID"] = "19566DF4",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101213/19566DF4",
            },
        [10121401] = {
            ["Camera"] = "178.257812,-350.6875,109.97998,0.000151,-7.200406,133.796951,12.0,269.704346,false,DoNotOverride,10.0",
            ["Content"] = "又是你们？！逼老子动真格的？",
            ["DialogueId"] = 10121401,
            ["GUID"] = "19567E5A",
            ["SpeakNpcId"] = 200053,
            ["VoiceName"] = "voice/$Locale$/story/1002/101214/19567E5A",
            },
        [10121501] = {
            ["Content"] = "咳、咳……！呛死我了……",
            ["DialogueId"] = 10121501,
            ["GUID"] = "19568EC2",
            ["GuideFacialId"] = "Sad",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10121502,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101215/19568EC2",
            },
        [10121502] = {
            ["Content"] = "（这家伙是个移动杂货铺吗，身上什么都有。该不会把冰湖城偷了个遍吧？）",
            ["DialogueId"] = 10121502,
