            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Think_Start",
                [2] = "200006:AgreeHead",
                },
            ["ToFinalCameraBlendTime"] = 6,
            ["VoiceName"] = "voice/$Locale$/story/1002/101223/19571202",
            },
        [10122302] = {
            ["Camera"] = "1613.404053,381.626953,486.294678,0.000123,-12.201046,-168.596786,35.0,464.479523,false,DoNotOverride,2.8",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "原来这里探险的狩月人是用<H>引路灯</>和<H>指示牌</>为后面的人指引安全的道路吗……",
            ["DialogueId"] = 10122302,
            ["FacialId"] = {
                [1] = "200006:Smile01",
                },
            ["FinalCamera"] = "1761.427734,411.505371,518.932861,0.000123,-12.201046,-168.596741,35.000008,464.479523,false,DoNotOverride,2.8",
            ["GUID"] = "1957122C",
            ["NextDialogue"] = 10122303,
            ["SpeakNpcId"] = 200006,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1002/101223/1957122C",
            },
        [10122303] = {
            ["Camera"] = "23.476318,138.433594,140.942383,0.000156,-2.000911,-106.794113,35.0,275.996185,false,Manual,2.8",
            ["Content"] = "有余力的话，我们也帮忙维护一下这些引路灯吧！",
            ["DialogueId"] = 10122303,
            ["FacialId"] = {
                [1] = "200006:Smile02",
                },
            ["FinalCamera"] = "32.779297,169.258789,142.067383,0.000156,-2.000911,-106.794113,35.000008,275.996185,false,DoNotOverride,2.8",
            ["GUID"] = "19571256",
            ["SpeakNpcId"] = 200006,
            ["TalkActionId"] = {
                [1] = "200006:Talk02_Start",
                },
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/1002/101223/19571256",
            },
        [10122401] = {
            ["Content"] = "灯又亮起来了耶~",
            ["DialogueId"] = 10122401,
            ["GUID"] = "1957226A",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101224/1957226A",
            },
        [10122402] = {
            ["Content"] = "嗯，这样大家应该就不会走错路了吧。",
            ["DialogueId"] = 10122402,
            ["GUID"] = "19572294",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101224/19572294",
            },
        [10122501] = {
            ["Content"] = "这样一来就全部搞定啦，干得漂亮！",
            ["DialogueId"] = 10122501,
            ["GUID"] = "195732D2",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101225/195732D2",
            },
        [10122601] = {
            ["Content"] = "它好像很喜欢你呢，{nickname}。",
            ["DialogueId"] = 10122601,
            ["GUID"] = "1957433A",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10122602,
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101226/1957433A",
            },
        [10122602] = {
            ["Content"] = "好可爱，让我也摸一摸！",
            ["DialogueId"] = 10122602,
            ["GUID"] = "19574364",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101226/19574364",
            },
        [10122701] = {
            ["Content"] = "“前有掠夺了很多财宝的秽兽千万不要靠近啊”——告示牌写好啦！",
            ["DialogueId"] = 10122701,
            ["GUID"] = "195753A2",
            ["GuideFacialId"] = "Confident",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10122702,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101227/195753A2",
            },
        [10122702] = {
            ["Content"] = "怎么回事，总觉得更想去看看了……",
            ["ContentFR"] = "Étrange... ce panneau donne presque envie d’aller voir ce qu’il cache.",
            ["DialogueId"] = 10122702,
            ["GUID"] = "195753CC",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101227/195753CC",
            },
        [10122801] = {
            ["Content"] = "嗯？那些黄色的“刺”亮晶晶的，难道是……",
            ["DialogueId"] = 10122801,
            ["GUID"] = "1957640A",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10122802,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101228/1957640A",
            },
        [10122802] = {
            ["Content"] = "不是哦，恩里克叔叔说，群星绮晶是星星形状的<H>紫色</>晶体……",
            ["DialogueId"] = 10122802,
            ["GUID"] = "19576434",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101228/19576434",
            },
        [10122901] = {
            ["Content"] = "小心！！",
            ["DialogueId"] = 10122901,
            ["GUID"] = "19577472",
            ["GuideFacialId"] = "Afraid",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10122902,
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101229/19577472",
            },
        [10122902] = {
            ["Content"] = "呼，还好没事……咦，前面有路了！",
            ["DialogueId"] = 10122902,
            ["GUID"] = "1957749C",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101229/1957749C",
            },
        [10123001] = {
            ["Content"] = "对了，路上的那些引路灯是你点亮的，对吧？我替后面的狩月人谢谢你。",
            ["ContentFR"] = "Au fait — ces lampes de guidage sur la route, c’est toi qui les as allumées, non ?\
Merci, au nom de tous les Chasseurs de Phoxène qui passeront derrière nous.",
            ["DialogueId"] = 10123001,
            ["GUID"] = "195784DA",
            ["NextDialogue"] = 10123002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101230/195784DA",
            },
        [10123002] = {
            ["Content"] = "这些小东西，就当是谢礼吧。",
            ["ContentFR"] = "Tiens, prends ça en guise de remerciement.",
            ["DialogueId"] = 10123002,
            ["GUID"] = "19578504",
            ["VoiceName"] = "voice/$Locale$/story/1002/101230/19578504",
            },
        [10123101] = {
            ["Content"] = "小仆从，快跟上来！",
            ["ContentFR"] = "Petit larbin, dépêche-toi !",
            ["DialogueId"] = 10123101,
            ["GUID"] = "19579542",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10123102,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101231/19579542",
            },
        [10123102] = {
            ["Content"] = "嘘——小点声，让他发现就不妙了。",
            ["ContentFR"] = "Chut... doucement. S’il nous remarque, ça va mal finir.",
            ["DialogueId"] = 10123102,
            ["GUID"] = "1957956C",
            ["GuideFacialId"] = "Sad",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101231/1957956C",
            },
        [10123201] = {
            ["Content"] = "都几点了，接货的怎么还不来……",
            ["ContentFR"] = "Mais il est quelle heure ? Pourquoi il n’est toujours pas arrivé...",
            ["DialogueId"] = 10123201,
            ["GUID"] = "1957A5AA",
            ["VoiceName"] = "voice/$Locale$/story/1002/101232/1957A5AA",
            },
        [10123301] = {
            ["Content"] = "等等——我们好像太近啦！",
            ["ContentFR"] = "Attends... on est beaucoup trop proches !",
            ["DialogueId"] = 10123301,
            ["GUID"] = "1957B612",
            ["GuideFacialId"] = "Afraid",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101233/1957B612",
            },
        [10123401] = {
            ["Content"] = "是你们？鬼鬼祟祟跟着我，想干什么？",
            ["ContentFR"] = "Vous encore ? Vous me suivez en cachette... vous voulez quoi ?",
            ["DialogueId"] = 10123401,
            ["GUID"] = "1957C67A",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 10123402,
            ["SpeakNpcId"] = 200005,
            ["VoiceName"] = "voice/$Locale$/story/1002/101234/1957C67A",
            },
        [10123402] = {
            ["Content"] = "不不不不，我们只是回酒馆路过的！",
            ["ContentFR"] = "Non, non, non ! On rentrait juste à la taverne ! Par pure coïncidence !",
            ["DialogueId"] = 10123402,
            ["GUID"] = "1957C6A4",
            ["IsBlack"] = 1,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101234/1957C6A4",
            },
        [10123403] = {
            ["Content"] = "糟糕，被恩里克发现了！",
            ["ContentFR"] = "Zut... Henrik nous a repérés !",
            ["DialogueId"] = 10123403,
            ["GUID"] = "10123403.0",
            ["IsBlack"] = 1,
            },
        [10123404] = {
            ["Content"] = "恩里克消失在了视线外……似乎是跟丢了。",
            ["ContentFR"] = "Henrik a disparu de votre champ de vision... Vous semblez l’avoir perdu de vue.",
            ["DialogueId"] = 10123404,
            ["GUID"] = "1957C6A5",
            },
        [10123405] = {
            ["Content"] = "恩里克走进了一间花店，你们决定在一旁的咖啡厅稍作等待。",
            ["ContentFR"] = "Henrik est entré dans une boutique de fleurs. Vous décidez de l’attendre un moment dans le café voisin.",
            ["DialogueId"] = 10123405,
            ["GUID"] = "1957C6A6",
            },
        [10123501] = {
            ["Content"] = "慢慢走，排好队——",
            ["ContentFR"] = "Doucement, en rang...",
            ["DialogueId"] = 10123501,
            ["GUID"] = "1957D6E2",
            ["NextDialogue"] = 10123502,
            ["VoiceName"] = "voice/$Locale$/story/1002/101235/1957D6E2",
            },
        [10123502] = {
            ["Content"] = "慢慢走，牵小手——",
            ["ContentFR"] = "Doucement, tiens la main de ton voisin...",
            ["DialogueId"] = 10123502,
            ["GUID"] = "1957D70C",
            ["VoiceName"] = "voice/$Locale$/story/1002/101235/1957D70C",
            },
        [10123601] = {
            ["Content"] = "（恩里克停下了……得找个地方躲一下。）",
            ["ContentFR"] = "<I>Henrik s’est arrêté... il faut qu’on se cache un peu.</>",
            ["DialogueId"] = 10123601,
            ["DisableMouth"] = 1,
            ["GUID"] = "1957E74A",
            ["GuideFacialId"] = "Afraid",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101236/1957E74A",
            },
        [10123602] = {
            ["Content"] = "这玩意又坏了？！",
            ["ContentFR"] = "Cette chose est encore en panne ?!",
            ["DialogueId"] = 10123602,
            ["GUID"] = "1957E774",
            ["VoiceName"] = "voice/$Locale$/story/1002/101236/1957E774",
            },
        [10123701] = {
            ["Content"] = "我有一个主意！我们藏在这个大家伙里面，就可以无声无息地跟上去了！",
            ["ContentFR"] = "J’ai une idée ! On se cache dans ce gros machin et on le suit sans faire de bruit !",
            ["DialogueId"] = 10123701,
            ["GUID"] = "1957F7B2",
            ["GuideFacialId"] = "Confident",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10123702,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101237/1957F7B2",
            },
        [10123702] = {
            ["Content"] = "那我问你，你要怎么在士兵眼皮子底下钻进去？",
            ["ContentFR"] = "Et comment tu comptes y entrer sans que les soldats te voient ?",
            ["DialogueId"] = 10123702,
            ["GUID"] = "1957F7DC",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10123703,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101237/1957F7DC",
            },
        [10123703] = {
            ["Content"] = "这个……唔……诶，恩里克走了，快来快来！",
            ["ContentFR"] = "Euh... bon... hmm... Ah, Henrik part ! Vite, vite !",
            ["DialogueId"] = 10123703,
            ["GUID"] = "1957F806",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10123501,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101237/1957F806",
            },
        [10123801] = {
            ["Content"] = "那家店……“牵念之花”，看名字好像是间花店。",
            ["DialogueId"] = 10123801,
            ["GUID"] = "1958081A",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10123802,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101238/1958081A",
            },
        [10123802] = {
            ["Content"] = "他去买花了吗……诶？！难道他是要去约会？",
            ["DialogueId"] = 10123802,
            ["GUID"] = "19580844",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101238/19580844",
            },
        [10123901] = {
            ["Content"] = "喂，你们两个。",
            ["DialogueId"] = 10123901,
            ["GUID"] = "19581882",
            ["NextDialogue"] = 10123902,
            ["SpeakNpcName"] = "UI_Npc_Name_AlertWoker",
            ["VoiceName"] = "voice/$Locale$/story/1002/101239/19581882",
            },
        [10123902] = {
            ["Content"] = "对，就是你们两个。你们俩，鬼鬼祟祟在人家屋顶坐着干什么？",
            ["DialogueId"] = 10123902,
            ["GUID"] = "195818AC",
            ["SpeakNpcName"] = "UI_Npc_Name_AlertWoker",
            ["VoiceName"] = "voice/$Locale$/story/1002/101239/195818AC",
            },
        [10123903] = {
            ["Camera"] = "-192.838379,86.913574,147.084473,0.000721,-6.203888,-37.222317,35.0,325.416962,false,Manual,1.997252",
            ["Content"] = "哪有，我们明明是光明正大坐着看风景！你看今天晚上的太阳多好啊。",
            ["DialogueId"] = 10123903,
            ["FacialId"] = {
                [1] = "200002:Unhappy02",
                },
            ["GUID"] = "195818D6",
            ["NextDialogue"] = 10123904,
            ["Scripts"] = "PARA{\
PlayAnimation{_delay{4},ActorId{200002},AnimationId{\"Confident_End\"},Duration{1}},\
PlayAnimation{_delay{5},ActorId{200002},AnimationId{\"Talk01_Start\"},Duration{1}},\
CameraMoveTo{_delay{5.5},TargetPosition{\"923.483887,-2454.475342,127.318726,0.000752,4.994986,122.379768,30.0,662.570679,false,Manual,1.997252\"},duration{0}},\
CameraMoveTo{_delay{5.6},TargetPosition{\"884.15332,-2479.414307,127.318726,0.000752,4.994986,122.379768,30.0,662.570679,false,Manual,1.997252\"},duration{4}}\
}",
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Confident_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101239/195818D6",
            },
        [10123904] = {
            ["Camera"] = "56.511719,-167.835693,119.327148,0.000756,2.594707,118.379005,35.0,218.031204,false,Manual,3.0",
            ["Content"] = "什么太阳月亮的，我要修屋顶，麻烦让一让。",
            ["DialogueId"] = 10123904,
            ["GUID"] = "19581900",
            ["NextDialogue"] = 10123905,
            ["SpeakNpcName"] = "UI_Npc_Name_AlertWoker",
            ["TalkActionId"] = {
                [1] = "200019:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101239/19581900",
            },
        [10123905] = {
            ["Camera"] = "-161.023438,20.044434,118.390259,0.000759,-2.805302,-37.617157,35.0,267.49585,false,Manual,3.0",
            ["Content"] = "走吧。",
            ["DialogueId"] = 10123905,
            ["GUID"] = "1958192A",
            ["LookAt"] = {
                [1] = "100001:n(200002)",
                },
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101239/1958192A",
            },
        [10123906] = {
            ["Content"] = "呜呜，我们好像跟丢了……",
            ["DialogueId"] = 10123906,
            ["GUID"] = "19581954",
            ["NextDialogue"] = 10123907,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101239/19581954",
            },
        [10123907] = {
            ["Content"] = "去问问花店的店主碰碰运气吧。",
            ["DialogueId"] = 10123907,
            ["GUID"] = "19581955",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101239/19581955",
            },
        [10124000] = {
            ["Content"] = "十分钟后。",
            ["ContentFR"] = "Dix minutes plus tard.",
            ["DialogueId"] = 10124000,
            ["GUID"] = "10124000.0",
            ["IsBlack"] = 1,
            },
        [10124001] = {
            ["Content"] = "你好你好！我们捡到一枚银币，是刚才那位叔叔掉的！我想还给他……",
            ["ContentFR"] = "Bonjour ! On a trouvé cette pièce d’argent, je crois que c’est celle que cet homme venait de laisser tomber ! On voulait la lui rendre...",
            ["DialogueId"] = 10124001,
            ["GUID"] = "195828EA",
            ["NextDialogue"] = 10124002,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101240/195828EA",
            },
        [10124002] = {
            ["Content"] = "咦，阿姨你怎么在哭？不会是那家伙说了什么难听话吧！",
            ["ContentFR"] = "Ah, madame, pourquoi vous pleurez ? Il vous a dit quelque chose de méchant ?",
            ["DialogueId"] = 10124002,
            ["GUID"] = "19582914",
            ["NextDialogue"] = 10124003,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101240/19582914",
            },
        [10124003] = {
            ["Content"] = "啊……没有没有。眼睛里进了紫露花的花粉而已。",
            ["ContentFR"] = "Ah... non, c’est juste du pollen de Rosée pourpre dans mes yeux. Merci de demander.",
            ["DialogueId"] = 10124003,
            ["GUID"] = "1958293E",
            ["NextDialogue"] = 10124004,
            ["SpeakNpcName"] = "UI_Npc_Name_FlowerShoper",
            ["VoiceName"] = "voice/$Locale$/story/1002/101240/1958293E",
            },
        [10124004] = {
            ["Content"] = "如果您说的是那位白衣服的先生，他现在……可能会在东北方向侧门的水潭那儿。",
            ["ContentFR"] = "Si vous parlez de l’homme en blanc... il est probablement près de l’étang, au nord-est.",
            ["DialogueId"] = 10124004,
            ["GUID"] = "19582968",
            ["NextDialogue"] = 10124005,
            ["SpeakNpcName"] = "UI_Npc_Name_FlowerShoper",
            ["VoiceName"] = "voice/$Locale$/story/1002/101240/19582968",
            },
        [10124005] = {
            ["Content"] = "知道了，谢谢。",
            ["ContentFR"] = "Compris, merci.",
            ["DialogueId"] = 10124005,
            ["GUID"] = "19582992",
            ["NextDialogue"] = 10124006,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101240/19582992",
            },
        [10124006] = {
            ["Content"] = "等一下，您……",
            ["ContentFR"] = "Attendez... vous...",
            ["DialogueId"] = 10124006,
            ["GUID"] = "195829BC",
            ["NextDialogue"] = 10124007,
            ["SpeakNpcName"] = "UI_Npc_Name_FlowerShoper",
            ["VoiceName"] = "voice/$Locale$/story/1002/101240/195829BC",
            },
        [10124007] = {
            ["Content"] = "嗯？您叫我吗？",
            ["ContentFR"] = "Oui ? Vous parlez à moi ?",
            ["DialogueId"] = 10124007,
            ["GUID"] = "195829E6",
            ["NextDialogue"] = 10124008,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101240/195829E6",
            },
        [10124008] = {
            ["Content"] = "……不，我也许认错人了。抱歉……您收下这个吧。",
            ["ContentFR"] = "... Non, je me suis peut-être trompé de personne. Désolée... Prenez ceci.",
            ["DialogueId"] = 10124008,
            ["GUID"] = "19582A10",
            ["NextDialogue"] = 10124101,
            ["SpeakNpcName"] = "UI_Npc_Name_FlowerShoper",
            ["VoiceName"] = "voice/$Locale$/story/1002/101240/19582A10",
            },
        [10124101] = {
            ["Content"] = "这是……白送的？",
            ["ContentFR"] = "Vous me donnez ça... gratuitement ?",
            ["DialogueId"] = 10124101,
            ["GUID"] = "19583952",
            ["NextDialogue"] = 10124102,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101241/19583952",
            },
        [10124102] = {
            ["Content"] = "嗯。您也有着红宝石一样的漂亮眼睛，与这朵紫露花很相称……愿您度过快乐的一天。",
            ["ContentFR"] = "Oui. Vos yeux brillent comme des rubis, parfaitement assortis à cette fleur... Passez une excellente journée.",
            ["DialogueId"] = 10124102,
            ["GUID"] = "1958397C",
            ["NextDialogue"] = 10124103,
            ["SpeakNpcName"] = "UI_Npc_Name_FlowerShoper",
            ["VoiceName"] = "voice/$Locale$/story/1002/101241/1958397C",
            },
        [10124103] = {
            ["Content"] = "谢谢，那我就收下了。",
            ["ContentFR"] = "Merci, je l’accepte volontiers.",
            ["DialogueId"] = 10124103,
            ["GUID"] = "195839A6",
            ["NextDialogue"] = 10124104,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101241/195839A6",
            },
        [10124104] = {
            ["Content"] = "竟然有意外收获，小仆从真是魅力非凡！",
            ["ContentFR"] = "Un cadeau d’une inconnue ? Mon petit larbin est irrésistible !",
            ["DialogueId"] = 10124104,
            ["GUID"] = "195839D0",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101241/195839D0",
            },
        [10124201] = {
            ["Content"] = "应该就是这个水潭了……他果然在！",
            ["ContentFR"] = "Ça doit être cet étang... et voilà, il est bien là !",
            ["DialogueId"] = 10124201,
            ["GUID"] = "195849BA",
            ["GuideFacialId"] = "Confident",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101242/195849BA",
            },
        [10124301] = {
            ["Content"] = "这一定就是他的惊天大秘密！只是，这么冷的水，就算是卡戎之民，下去捞也会着凉吧？",
            ["ContentFR"] = "Ça doit être son terrible secret ! Mais... l’eau est glaciale. Même pour un Charon, plonger là-dedans, ça serait risqué.",
            ["DialogueId"] = 10124301,
            ["GUID"] = "19585A22",
            ["NextDialogue"] = 10124302,
            ["VoiceName"] = "voice/$Locale$/story/1002/101243/19585A22",
            },
        [10124302] = {
            ["Content"] = "那就只能交给万能的皎皎了！白豁出去了——诶，小仆从你这是在……",
            ["ContentFR"] = "On dirait bien que la toute-puissante Luno doit intervenir ! Snow se sacrifie... Eh, petit larbin, tu fais quoi là... ?",
            ["DialogueId"] = 10124302,
            ["GUID"] = "19585A4C",
            ["NextDialogue"] = 10124303,
            ["VoiceName"] = "voice/$Locale$/story/1002/101243/19585A4C",
            },
        [10124303] = {
            ["Content"] = "只要这样改装一下钓竿……嗯，好了。",
            ["ContentFR"] = "Je n’ai qu’à ajuster un peu la canne à pêche... Voilà.",
            ["DialogueId"] = 10124303,
            ["GUID"] = "19585A76",
            ["NextDialogue"] = 10124304,
            ["VoiceName"] = "voice/$Locale$/story/1002/101243/19585A76",
            },
        [10124304] = {
            ["Content"] = "交给我吧。只要是水里的东西，就算是鲨鱼，我也能钓上来。",
            ["ContentFR"] = "Laisse-moi faire. Si c’est dans l’eau, trésor ou requin, je le ramène.",
            ["DialogueId"] = 10124304,
            ["GUID"] = "19585AA0",
            ["VoiceName"] = "voice/$Locale$/story/1002/101243/19585AA0",
            },
        [10124401] = {
            ["Content"] = "天啊，小仆从，莫非你就是艾利西安掌管水产的神？",
            ["ContentFR"] = "Impossible... Petit larbin, tu serais {性别:le Dieu Élyséen|la Déesse Élyséenne} de la pêche, par hasard ?",
            ["DialogueId"] = 10124401,
            ["GUID"] = "19586A8A",
            ["NextDialogue"] = 10124402,
            ["VoiceName"] = "voice/$Locale$/story/1002/101244/19586A8A",
            },
        [10124402] = {
            ["Content"] = "用石块垒起的石堆，旁边放着一束白花。看起来似乎有某种纪念意义。",
            ["ContentFR"] = "Un petit cairn de pierres. Un bouquet de fleurs blanches repose à côté, comme un hommage silencieux.",
            ["DialogueId"] = 10124402,
            ["GUID"] = "19586AB4",
            ["NextDialogue"] = 10124403,
            ["VoiceName"] = "voice/$Locale$/story/1002/101244/19586AB4",
            },
        [10124403] = {
            ["Content"] = "你看你看，这花像不像恩里克从花店买的那束？",
            ["ContentFR"] = "Regarde ! Ce bouquet de fleur ressemble à celui qu’Henrik a acheté à la boutique !",
            ["DialogueId"] = 10124403,
            ["GUID"] = "19586ADE",
            ["VoiceName"] = "voice/$Locale$/story/1002/101244/19586ADE",
            },
        [10124500] = {
