        [10124503] = {
            ["Camera"] = "3063.935547,12923.142578,-474.020508,0.000079,7.19919,116.986656,20.0,133.732285,false,DoNotOverride,2.0",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "嗯，很漂亮。",
            ["ContentFR"] = "Oui... c’est splendide.",
            ["DialogueId"] = 10124503,
            ["FacialId"] = {
                [1] = "100001:Smile01",
                },
            ["FinalCamera"] = "3104.400391,12843.65625,-485.285156,0.000079,7.19919,116.986656,20.0,133.732285,false,DoNotOverride,2.0",
