            },
        [10124504] = {
            ["Camera"] = "-170.298828,286.62207,6.517578,0.000065,-0.600066,81.802094,30.000002,715.44751,false,Manual,2.5",
            ["Content"] = "我们一起到湖边走走，好吗？",
            ["ContentFR"] = "Allons marcher un peu le long de la rive, veux-tu ?",
            ["DialogueId"] = 10124504,
            ["FinalCamera"] = "-167.683594,286.25,6.517578,0.000065,-0.600066,81.802094,30.000002,715.44751,false,Manual,2.5",
            ["GUID"] = "19587B70",
            ["SpeakNpcId"] = 200006,
            ["ToFinalCameraBlendTime"] = 3,
            ["TurnTo"] = {
                [1] = "100001:n(200006)",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101245/19587B70",
            },
        [10124601] = {
            ["Content"] = "这边的积雪有些厚，小心。",
            ["ContentFR"] = "Attention, la neige est épaisse ici.",
            ["DialogueId"] = 10124601,
            ["GUID"] = "19588B5A",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10124602,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101246/19588B5A",
            },
        [10124602] = {
            ["Content"] = "嗯……那你走在前，我在后面。",
            ["ContentFR"] = "Hmm... dans ce cas, marche devant. Je suivrai tes pas.",
            ["DialogueId"] = 10124602,
            ["GUID"] = "19588B84",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10124603,
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101246/19588B84",
            },
        [10124603] = {
            ["Content"] = "如果踩在你的脚印上就不会摔倒啦。",
            ["ContentFR"] = "Si je mets mes pieds dans tes traces, je ne risquerai pas de tomber.",
            ["DialogueId"] = 10124603,
            ["GUID"] = "19588BAE",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101246/19588BAE",
            },
        [10124701] = {
            ["Camera"] = "1995.472656,-1570.600586,129.378906,0.000124,-10.399994,89.393982,12.0,100000.0,false,DoNotOverride,22",
            ["Content"] = "这条河会流向哪里呢？",
            ["ContentFR"] = "Tu crois que cette rivière se jette où ?",
            ["DialogueId"] = 10124701,
            ["FacialId"] = {
                [1] = "100001:Think01",
                },
            ["GUID"] = "19589BC2",
            ["LookAt"] = {
