            ["Content"] = "我不知道……也许是大海？",
            ["ContentFR"] = "Je ne sais pas... peut-être dans la mer ?",
            ["DialogueId"] = 10124702,
            ["FacialId"] = {
                [1] = "100001:None",
                [2] = "200006:Happy02",
                },
            ["GUID"] = "19589BEC",
