            ["TalkActionId"] = {
                [1] = "200006:DisagreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101247/19589BEC",
            },
        [10124703] = {
            ["Camera"] = "3394.880859,-590.107422,3505.388672,0.000188,-4.999999,115.388802,10.0,615.599121,false,Manual,22",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "不对……书上说大海的水是咸咸的，那么连着大海的河一定也是咸咸的吧？",
            ["ContentFR"] = "... Non, ça ne peut pas être ça. Les livres disent que l’eau de mer est salée. Si cette rivière rejoint la mer, son eau devrait l’être aussi, non ?",
            ["DialogueId"] = 10124703,
            ["FacialId"] = {
                [1] = "200006:None",
                },
            ["FinalCamera"] = "3297.427734,-384.805664,3431.786133,0.000189,4.999999,115.388718,10.0,615.599121,false,Manual,22",
