            },
        [10124704] = {
            ["Camera"] = "409.0625,59.248047,1.302734,0.000228,13.598858,-173.415344,35.0,522.283813,false,Manual,4.0",
            ["Content"] = "可是这条河的水我偷偷尝过，是淡淡的。",
            ["ContentFR"] = "Mais je l’ai déjà goûtée en cachette... et elle était douce.",
            ["DialogueId"] = 10124704,
            ["GUID"] = "19589C40",
            ["NextDialogue"] = 10124705,
            ["SpeakNpcId"] = 200006,
            ["TalkActionId"] = {
                [1] = "200006:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101247/19589C40",
            },
        [10124705] = {
