        [10124801] = {
            ["Camera"] = "-421.605469,-245.255859,131.046875,-0.0,-7.500012,23.199612,12.0,62.967312,false,DoNotOverride,1.2",
            ["Content"] = "这么冷的天，还有人在钓鱼呀。赛琪，你喜欢钓鱼吗？",
            ["ContentFR"] = "Pêcher par un froid pareil... quelle détermination ! Dis-moi, Psyche, tu aimes ça, la pêche ?",
            ["DialogueId"] = 10124801,
            ["FinalCamera"] = "-416.654297,-243.136719,130.335938,-0.0,-7.500012,23.199612,12.0,62.967312,false,DoNotOverride,1.2",
