        [10124802] = {
            ["Camera"] = "-302.291016,-73.060547,140.873047,0.000007,-1.800076,-100.001617,35.0,185.688477,false,Manual,2.5",
            ["Content"] = "诶？我有兴趣的，只是我家不是捕鱼的，所以不太擅长……",
            ["ContentFR"] = "Hein ? Ça m’intéresse, mais ma famille ne vivait pas de ça... alors je ne suis pas très douée.",
            ["DialogueId"] = 10124802,
            ["GUID"] = "1958AC54",
            ["LookAt"] = {
                [1] = "200006:n(100001)",
                },
            ["NextDialogue"] = 10124803,
            ["Scripts"] = "PARA{\
PlayAnimation{_delay{1},ActorId{200006},AnimationId{\"Think_Start\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 200006,
            ["TalkActionId"] = {
                [1] = "100001:Explain01_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101248/1958AC54",
            },
        [10124803] = {
            ["Camera"] = "-211.847656,-261.972656,151.822266,0.000013,-7.799987,151.599762,35.0,185.688477,false,Manual,2.5",
            ["Content"] = "没关系没关系，改天我教你，超好玩的！我能坐一整天。",
            ["ContentFR"] = "Pas de souci, je t’apprendrai la prochaine fois ! C’est super amusant. Moi je peux passer une journée entière à ça.",
            ["DialogueId"] = 10124803,
            ["GUID"] = "1958AC7E",
            ["NextDialogue"] = 10124804,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Explain02_Start",
                [2] = "200006:Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101248/1958AC7E",
            },
        [10124804] = {
            ["Camera"] = "717.636719,237.269531,92.487305,0.000039,0.000007,-165.6008,40.0,199.075928,false,Manual,4.533308",
            ["Content"] = "好！如果有机会……",
            ["ContentFR"] = "D’accord... alors, c’est promis.",
            ["DialogueId"] = 10124804,
            ["FinalCamera"] = "718.5625,233.65625,92.487305,0.000039,0.000007,-165.6008,40.0,583.132141,false,Manual,3.808652",
            ["GUID"] = "1958ACA8",
            ["SpeakNpcId"] = 200006,
            ["TalkActionId"] = {
                [1] = "200006:AgreeHead",
                },
            ["ToFinalCameraBlendTime"] = 4,
            ["VoiceName"] = "voice/$Locale$/story/1002/101248/1958ACA8",
            },
        [10124901] = {
            ["Content"] = "小时候我总是想着，只要一直往前跑，就能离开冰湖城了。",
            ["ContentFR"] = "Quand j’étais petite, je croyais que si je courais assez loin, je pourrais quitter Givrelac.",
            ["DialogueId"] = 10124901,
            ["GUID"] = "1958BC92",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10124902,
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101249/1958BC92",
            },
        [10124902] = {
            ["Content"] = "但我跑呀，跑呀，却发现湖的尽头还是湖，就像山的那边还是山……",
            ["ContentFR"] = "Mais plus je courais, plus je me retrouvais devant le même lac... comme derrière une montagne, il y a toujours une autre montagne.",
            ["DialogueId"] = 10124902,
            ["GUID"] = "1958BCBC",
            ["GuideFacialId"] = "Sad",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101249/1958BCBC",
            },
        [10125001] = {
            ["Camera"] = "187.345703,453.548828,53.723633,0.0,0.0,-113.610939,25.0,3663.129883,false,Manual,1.2",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "这朵花有点眼熟。",
            ["ContentFR"] = "Cette fleur me dit quelque chose...",
            ["DialogueId"] = 10125001,
            ["FinalCamera"] = "183.400391,455.277344,53.723633,0.0,0.0,-113.610863,25.0,425.805145,false,Manual,2.325369",
            ["GUID"] = "1958CCFA",
            ["LookAt"] = {
                [1] = "100001:p(P101250Flower)",
                [2] = "200006:p(P101250Flower)",
                },
            ["NextDialogue"] = 10125002,
            ["SpeakNpcId"] = 100001,
            ["ToFinalCameraBlendTime"] = 3,
            ["VoiceName"] = "voice/$Locale$/story/1002/101250/1958CCFA",
            },
        [10125002] = {
            ["Camera"] = "-5.208984,20.542969,81.288086,0.000032,-7.199948,52.000679,30.0,79.292412,false,Manual,4.0",
            ["CameraBlendCurve"] = "easeInQuad",
            ["Content"] = "是吗，让我摸一摸……是星霜百合，花瓣更小，香味也更淡……但它确实和我房间那盆花是相同的品种。",
            ["ContentFR"] = "Vraiment ? Laisse-moi la toucher... Oui, c’est un Lys givre-étoilé. Les pétales sont plus petits, le parfum plus léger... mais c’est bien la même espèce que celle dans ma chambre.",
            ["DialogueId"] = 10125002,
            ["FacialId"] = {
                [1] = "200006:Smile01",
                },
            ["FinalCamera"] = "3.671875,19.353516,80.720703,0.000016,-7.199975,54.899391,30.0,182.280197,false,Manual,4.0",
            ["GUID"] = "1958CD24",
            ["NextDialogue"] = 10125003,
            ["Scripts"] = "PARA{\
MoveTo{ActorId{200006},MoveSpeed{120},TargetPoint{\"P101250Saiqi\"}}\
}",
            ["SpeakNpcId"] = 200006,
            ["ToFinalCameraBlendTime"] = 2.5,
            ["VoiceName"] = "voice/$Locale$/story/1002/101250/1958CD24",
            },
        [10125003] = {
            ["Camera"] = "153.019531,416.476562,54.358398,0.000051,4.999835,-100.502174,30.0,326.873077,false,Manual,22",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "要摘一朵留念吗？",
            ["ContentFR"] = "Tu veux en cueillir une, comme souvenir ?",
            ["DialogueId"] = 10125003,
            ["FinalCamera"] = "160.480469,456.728516,50.777344,0.000051,4.999835,-100.502174,30.0,326.873077,false,Manual,22",
            ["GUID"] = "1958CD4E",
