            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Explain02_Start",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/story/1002/101250/1958CD4E",
            },
        [10125004] = {
            ["Camera"] = "1505.365234,-1424.457031,158.464844,0.000052,7.500012,126.697205,20.0,139.363022,false,Manual,4.0",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "不，不用，这样就好。",
            ["ContentFR"] = "Non... pas besoin. Savoir qu’elle est ici me suffit.",
