        [10125103] = {
            ["Camera"] = "-383.175781,979.316406,15.928711,0.000024,1.699392,-58.39698,30.0,937.541016,false,Manual,1.2",
            ["CameraBlendCurve"] = "easeInQuad",
            ["Content"] = "来，{nickname}，再给我拍一张照吧，要把冰湖城拍进去哦。",
            ["ContentFR"] = "Allez, {nickname}, prends encore une photo de moi. Mais veille à ce que Givrelac soit dans le cadre.",
            ["DialogueId"] = 10125103,
            ["FacialId"] = {
                [1] = "200027:Smile01",
                },
            ["FinalCamera"] = "-383.175781,979.316406,35.485352,0.000037,3.600001,-55.999863,30.000002,923.619934,false,Manual,1.2",
            ["GUID"] = "1958DDB6",
            ["LookAt"] = {
                [1] = "200027:n(100001)",
                },
            ["NextDialogue"] = 10125104,
            ["SpeakNpcId"] = 200027,
