            },
        [10125104] = {
            ["Camera"] = "-2408.292969,-1634.121094,1839.698242,0.000074,24.496656,-29.79982,15.0,937.541016,false,DoNotOverride,1.2",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "我不喜欢这座城市，讨厌它淡淡的腥味儿，讨厌它山一样高的城墙，讨厌卫兵们的厚皮靴，讨厌每个街角传来的哭泣。",
            ["ContentFR"] = "Je n’aime pas cette ville. Je déteste l’odeur métallique qui flotte dans l’air, ses murailles hautes comme des montagnes, les lourdes bottes des gardes... et les sanglots qui résonnent à chaque coin de rue.",
            ["DialogueId"] = 10125104,
            ["FacialId"] = {
                [1] = "200027:None",
                },
            ["FinalCamera"] = "-3675.546875,-915.507812,781.563477,0.000088,25.896593,-29.799929,15.0,937.541016,false,DoNotOverride,1.2",
            ["GUID"] = "1958DDE0",
            ["LookAt"] = {
                [1] = "200027:n(200027)",
                },
            ["NextDialogue"] = 10125105,
            ["SpeakNpcId"] = 200027,
            ["ToFinalCameraBlendTime"] = 14,
            ["TurnTo"] = {
                [1] = "200027:p(-120)",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101251/1958DDE0",
            },
        [10125105] = {
            ["Camera"] = "93.558594,213.8125,52.767578,0.00006,13.824869,-124.447884,50.0,134.6604,false,Manual,5.0",
            ["CameraBlendCurve"] = "easeOutQuad",
            ["Content"] = "但它也是我长大的地方……我唯一的家。",
            ["ContentFR"] = "... Mais c’est aussi l’endroit où j’ai grandi. <H>Mon seul et unique foyer</>.",
            ["DialogueId"] = 10125105,
            ["FinalCamera"] = "89.410156,207.765625,54.574219,0.000061,13.824869,-124.447868,50.0,126.754227,false,Manual,5.0",
            ["GUID"] = "1958DE0A",
            ["NextDialogue"] = 10125106,
            ["SpeakNpcId"] = 200027,
            ["ToFinalCameraBlendTime"] = 4.5,
            ["VoiceName"] = "voice/$Locale$/story/1002/101251/1958DE0A",
            },
        [10125106] = {
            ["Camera"] = "-124.773438,102.035156,16.120117,0.000002,25.225302,-10.450226,20.000008,91.0,false,DoNotOverride,5.0",
            ["CameraBlendCurve"] = "easeOutQuad",
            ["Content"] = "所以，我想再和它合个影……",
            ["ContentFR"] = "Alors, je voudrais prendre une dernière photo avec elle.",
            ["DialogueId"] = 10125106,
            ["FacialId"] = {
                [1] = "200027:Satisfy01",
                },
            ["FinalCamera"] = "-149.609375,81.59375,-7.086914,7.00087,29.425505,-7.648393,20.000008,91.0,false,DoNotOverride,5.0",
