        [10125905] = {
            ["Camera"] = "-119.442383,-114.433594,183.290039,0.000117,-11.966764,48.943577,50.000011,448.770081,false,Manual,3.0",
            ["Content"] = "我旅行至此，听见此地彷徨灵魂的絮语，因此前来指引“她”回归雾海。",
            ["ContentFR"] = "J’ai entendu les murmures d’une âme égarée en ce lieu. Je suis venue la guider vers la Mer du Silence.",
            ["DialogueId"] = 10125905,
            ["FacialId"] = {
                [1] = "200076:Sad01",
                },
            ["GUID"] = "1959614A",
