            },
        [10125906] = {
            ["Content"] = "彷徨的灵魂？",
            ["ContentFR"] = "Une âme égarée ?",
            ["DialogueId"] = 10125906,
            ["FacialId"] = {
                [1] = "100001:Shock01",
                },
            ["GUID"] = "19596174",
