        [10125909] = {
            ["Camera"] = "119.579102,263.601562,98.743164,0.000002,16.597837,-82.594849,50.000008,464.774139,false,DoNotOverride,3.5",
            ["Content"] = "我的双眼能看到灵魂所思之物。",
            ["ContentFR"] = "Mes yeux perçoivent ce que les âmes désirent.",
            ["DialogueId"] = 10125909,
            ["FacialId"] = {
                [1] = "200076:Smile01",
                },
