            ["SpeakNpcId"] = 200076,
            ["SpeakNpcName"] = "UI_Npc_Name_Nifu",
            ["VoiceName"] = "voice/$Locale$/story/1002/101259/195961F2",
            },
        [10125910] = {
            ["Camera"] = "110.996094,65.115234,147.691406,0.000015,-10.00217,80.202942,50.000011,464.774139,false,DoNotOverride,3.5",
            ["Content"] = "方才，在引导她归去之时，我看到了她牵念的一切，其中便有你的身影。",
            ["ContentFR"] = "Tandis que je la conduisais, j’ai aperçu ce qui lui tenait le plus à cœur. Et parmi ces visions... ton visage est apparu.",
            ["DialogueId"] = 10125910,
            ["GUID"] = "1959621C",
            ["NextDialogue"] = 10125911,
            ["Scripts"] = "SetLocation{ActorId{100001},TargetPoint{\"P_101259Nvzhu2\"},Visibility{\"Show\"}}",
            ["SpeakNpcId"] = 200076,
            ["SpeakNpcName"] = "UI_Npc_Name_Nifu",
            ["VoiceName"] = "voice/$Locale$/story/1002/101259/1959621C",
            },
        [10125911] = {
            ["Camera"] = "95.520508,198.755859,124.03125,5.001531,-13.799672,57.99501,20.000008,46.651825,false,Manual,4.0",
            ["Content"] = "……她是我的朋友。",
            ["ContentFR"] = "... C’était mon amie.",
            ["DialogueId"] = 10125911,
            ["FacialId"] = {
                [1] = "100001:Sad01",
                },
            ["GUID"] = "19596246",
            ["LookAt"] = {
                [1] = "100001:n(100001)",
                },
            ["NextDialogue"] = 10125912,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101259/19596246",
            },
        [10125912] = {
            ["Content"] = "我……没能保护好她。她或许是……对我感到失望。",
            ["ContentFR"] = "Je... je n’ai pas su la protéger. Elle doit être... déçue de moi.",
            ["DialogueId"] = 10125912,
            ["GUID"] = "19596270",
            ["NextDialogue"] = 10125913,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:DisagreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101259/19596270",
            },
        [10125913] = {
            ["Camera"] = "96.016602,285.619141,103.054688,0.000066,7.001299,-64.589752,25.0,76.61264,false,Manual,22.0",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "不，恰恰相反。我曾见过许多怀抱着强烈的遗憾与怨恨归去的灵魂，他们的恸哭悲号，如浓雾一般溢满河岸。",
            ["ContentFR"] = "Non. Bien au contraire. J’ai vu tant d’âmes partir avec la rancune au ventre, noyées de regrets, leurs cris emplissant la rive comme une brume étouffante.",
            ["DialogueId"] = 10125913,
            ["FinalCamera"] = "150.009766,289.806641,103.926758,0.000063,7.80125,-105.588699,25.0,76.61264,false,Manual,22.0",
            ["GUID"] = "1959629A",
            ["LookAt"] = {
                [1] = "100001:n(200076)",
                },
            ["NextDialogue"] = 10125914,
            ["SpeakNpcId"] = 200076,
            ["SpeakNpcName"] = "UI_Npc_Name_Nifu",
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/story/1002/101259/1959629A",
            },
        [10125914] = {
            ["Camera"] = "1647.097656,1629.320312,80.411133,0.000092,-1.000056,-134.800735,50.000011,655.091675,false,Manual,22.0",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "但是，那个灵魂的声音非常温柔。没有哀叹，也没有愤怒与不甘，而是在诉说感谢以及……祝福。",
            ["ContentFR"] = "Mais la sienne... était douce. Ni plainte, ni colère, ni ressentiment. Seulement des paroles de gratitude... et de bénédiction.",
            ["DialogueId"] = 10125914,
            ["FinalCamera"] = "1720.431641,1626.798828,101.317383,0.000085,-1.000022,-137.800919,50.000008,655.091675,false,Manual,22.0",
            ["GUID"] = "195962C4",
            ["LookAt"] = {
                [1] = "200076:p(P_101259Nifu3)",
                },
            ["NextDialogue"] = 10125915,
            ["SpeakNpcId"] = 200076,
            ["SpeakNpcName"] = "UI_Npc_Name_Nifu",
            ["ToFinalCameraBlendTime"] = 6,
            ["VoiceName"] = "voice/$Locale$/story/1002/101259/195962C4",
            },
        [10125915] = {
            ["Camera"] = "1720.431641,1626.798828,101.317383,0.000085,-1.000022,-137.800919,50.000008,655.091675,false,Manual,22.0",
            ["Content"] = "或许，那便是她所为你留下的。",
            ["ContentFR"] = "Peut-être était-ce là son dernier cadeau pour toi.",
            ["DialogueId"] = 10125915,
            ["GUID"] = "195962EE",
            ["NextDialogue"] = 10125916,
            ["SpeakNpcId"] = 200076,
            ["SpeakNpcName"] = "UI_Npc_Name_Nifu",
            ["VoiceName"] = "voice/$Locale$/story/1002/101259/195962EE",
            },
        }
  end },
