            ["GUID"] = "1B898F80",
            ["SpeakNpcId"] = 0,
            },
        [11010001] = {
            ["Content"] = "Smile01",
            ["DialogueId"] = 11010001,
            ["GUID"] = "1B8FF84A",
            ["SpeakNpcId"] = 110005,
            },
        [11010101] = {
            ["Camera"] = "-3847.1875,2457.945312,-1282.195801,0.000086,16.599463,-32.207474,28.0,502.63504,false,Manual,10.963819",
            ["Content"] = "（我……又做了这个梦……）",
            ["ContentFR"] = "<I>Je... je fais encore ce rêve...</>",
            ["DialogueId"] = 11010101,
            ["DisableMouth"] = 1,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["FacialId"] = {
                [1] = "110022:Pain01",
