            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 110022,
            ["TalkActionId"] = {
                [1] = "110022:Sigh_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1002/110101/1B9008B2",
            },
        [11010102] = {
            ["Camera"] = "102.601562,206.410156,117.232056,0.000039,-23.600208,-132.594559,28.0,179.473755,false,Manual,10.963819",
            ["Content"] = "<W>……那只巨兽正拦在你的去路，扼住你的咽喉。</>",
            ["ContentFR"] = "<W>... Cette bête géante bloque ton chemin, serrant ta gorge.</>",
            ["DialogueId"] = 11010102,
            ["DisableMouth"] = 1,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["FinalCamera"] = "89.054688,191.6875,108.48584,0.000039,-23.600208,-132.594559,28.0,179.473755,false,Manual,10.963819",
