        [11010208] = {
            ["Camera"] = "2388.339844,-2981.808594,458.513428,-15.00156,-8.397245,129.407578,25.0,2843.594727,false,Manual,1.2",
            ["Content"] = "<W>湿滑黏腻的污物沾满了你的双手，你分不清那是秽兽的黏液还是内脏。你唯一知道的是，它们令你欣悦，连灵魂都为之震颤。</>",
            ["ContentFR"] = "<W>Tes mains sont couvertes de ce liquide gluant, tu ne sais plus si c’est du mucus du Souillé ou ses entrailles. Pourtant, une étrange joie parcourt ton âme.</>",
            ["DialogueId"] = 11010208,
            ["DisableMouth"] = 1,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["FinalCamera"] = "2351.246094,-2936.632812,449.885864,-15.00156,-8.397245,129.407578,25.0,2843.594727,false,Manual,1.2",
