            ["SnapShot"] = "MONSTER",
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["TalkActionId"] = {
                [1] = "110022:Sigh_Start",
                },
            ["ToFinalCameraBlendTime"] = 15,
            ["VoiceName"] = "voice/$Locale$/story/1002/110102/1B901A40",
            },
        [11010209] = {
            ["Content"] = "（给我闭嘴！我没有！）",
            ["ContentFR"] = "<I>– Tais-toi ! Ce n’est pas ce que je ressens !</>",
            ["DialogueId"] = 11010209,
            ["GUID"] = "1B901A6A",
            ["NextDialogue"] = 11010210,
            },
        [11010210] = {
            ["Camera"] = "-299.773438,-22.185547,-5.160034,-18.018326,38.192356,-12.391366,30.0,100.319092,false,DoNotOverride,22.0",
            ["Content"] = "<W>不要抗拒。因为我是真正的你，是你的死之本能。终有一日你会遵从我的指引，遵从亘古的意志……</>",
            ["ContentFR"] = "<W>Ne résiste pas. Je suis ce que tu es vraiment, ton instinct de mort. Un jour, tu suivras mon chemin et obéiras à la volonté ancestrale...</>",
            ["DialogueId"] = 11010210,
            ["DisableMouth"] = 1,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["FinalCamera"] = "-298.789062,-47.498047,-11.343872,-18.018387,40.392326,-2.390289,30.000002,100.319092,false,DoNotOverride,22.0",
            ["GUID"] = "1B901A94",
            ["NextOptions"] = {
                [1] = 11010211,
                },
            ["Scripts"] = "PARA{PlayNormalSound{EventPath{\"event:/sfx/common/story/ex01/evilvo\"},PlayAs2D{true}},PostProcess{MaterailInstance{\"MaterialInstanceConstant'/Game/Asset/Scene/common/PP/MI_PP_Demon_01.MI_PP_Demon_01'\"}}\
}",
            ["SnapShot"] = "MONSTER",
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["ToFinalCameraBlendTime"] = 20,
            ["VoiceName"] = "voice/$Locale$/story/1002/110102/1B901A94",
            },
        [11010211] = {
            ["Content"] = "（你不愿再听它的胡言乱语，努力维持理智。）",
            ["ContentFR"] = "<I>Refuser de se laisser emporter par ses délires et s’efforcer de rester lucide</>",
            ["DialogueId"] = 11010211,
            ["GUID"] = "1B901ABE",
            ["NextDialogue"] = 11010212,
            },
        [11010212] = {
            ["Camera"] = "-241.761719,-58.371094,187.967773,0.000089,-23.197569,-2.984956,35.000008,116.737953,false,Manual,4.707314",
            ["Content"] = "…………",
            ["ContentFR"] = "...",
            ["DialogueId"] = 11010212,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["FacialId"] = {
                [1] = "110022:Pain01",
                },
            ["FinalCamera"] = "-253.742188,-57.75,193.109009,0.000089,-23.197569,-2.984956,35.000008,129.145432,false,Manual,5.70814",
            ["GUID"] = "1B901AE8",
            ["Scripts"] = "PostProcess{MaterailInstance{\"None\"}}",
            ["SpeakNpcId"] = 110022,
            ["TalkActionId"] = {
                [1] = "110022:Sigh_End",
                },
            ["ToFinalCameraBlendTime"] = 6,
            ["VoiceName"] = "voice/$Locale$/story/1002/110102/1B901AE8",
            },
        [11010215] = {
            ["Content"] = "（……这讨厌的声音终于停下来了。）",
            ["ContentFR"] = "<I>... Cette voix agaçante s'est enfin tue.</>",
            ["DialogueId"] = 11010215,
            ["DisableMouth"] = 1,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B901B66",
            ["NextDialogue"] = 11010216,
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110102/1B901B66",
            },
        [11010216] = {
            ["Content"] = "快去看看其他人的情况吧。",
            ["ContentFR"] = "Je ferais mieux de vérifier ce qui est arrivé aux autres.",
            ["DialogueId"] = 11010216,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B901B90",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110102/1B901B90",
            },
        [11010221] = {
            ["Content"] = "嘶……达芙涅医生，我们这样算是完成任务了吧？",
            ["ContentFR"] = "Hfff... Docteur Daphne, on peut considérer notre mission terminée, non ? ",
            ["DialogueId"] = 11010221,
            ["Duration"] = 3,
            ["GUID"] = "1B901C62",
            ["SpeakNpcId"] = 110019,
            ["VoiceName"] = "voice/$Locale$/story/1002/110102/1B901C62",
            },
        [11010222] = {
            ["Content"] = "……不，好好活着回去，我们的任务才算完成！",
            ["ContentFR"] = "... Non, tant qu’on ne rentre pas vivant, la mission n’est pas finie !",
            ["DialogueId"] = 11010222,
            ["Duration"] = 3,
            ["GUID"] = "1B901C8C",
            ["SpeakNpcId"] = 110005,
            ["VoiceName"] = "voice/$Locale$/story/1002/110102/1B901C8C",
            },
        [11010223] = {
            ["Content"] = "没关系的，达芙涅。冷静下来，没关系的。",
            ["ContentFR"] = "Ça va, Daphne. Calme-toi... ça va aller, respire...",
            ["DialogueId"] = 11010223,
            ["Duration"] = 3,
            ["GUID"] = "1B901CB6",
            ["SpeakNpcId"] = 110005,
            ["VoiceName"] = "voice/$Locale$/story/1002/110102/1B901CB6",
            },
        [11010224] = {
            ["Content"] = "您回来了！",
            ["ContentFR"] = "Ah ! Vous êtes revenu !",
            ["DialogueId"] = 11010224,
            ["Duration"] = 3,
            ["GUID"] = "1B901CE0",
            ["SpeakNpcId"] = 110005,
            ["VoiceName"] = "voice/$Locale$/story/1002/110102/1B901CE0",
            },
        [11010225] = {
            ["Content"] = ".....快醒醒！！！这样下去你会死的！",
            ["ContentFR"] = "... Vite, réveille-toi ! Si ça continue, tu vas mourir !",
            ["DialogueId"] = 11010225,
            ["Duration"] = 3,
            ["GUID"] = "1B90191A",
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["VoiceName"] = "voice/$Locale$/story/1002/110102/1B90191A",
            },
        [11010226] = {
            ["Content"] = "队长！",
            ["ContentFR"] = "Capitaine !",
            ["DialogueId"] = 11010226,
            ["Duration"] = 3,
            ["GUID"] = "1B901944",
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["VoiceName"] = "voice/$Locale$/story/1002/110102/1B901944",
            },
        [11010227] = {
            ["Content"] = "啊，队长醒了！",
            ["ContentFR"] = "Ah, {性别2:le capitaine est réveillé|la capitaine est réveillée} !",
            ["DialogueId"] = 11010227,
            ["Duration"] = 3,
            ["GUID"] = "1B901945",
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["VoiceName"] = "voice/$Locale$/story/1002/110102/1B901945",
            },
        [11010301] = {
