        [11010702] = {
            ["Content"] = "（将药剂交给达芙涅。）",
            ["ContentFR"] = "<I>Remettre les médicaments à Daphne</>",
            ["DialogueId"] = 11010702,
            ["GUID"] = "1B906B4C",
            ["NextDialogue"] = 11010703,
            },
        [11010703] = {
            ["Camera"] = "-362.734375,-126.394531,148.611084,0.000269,-5.800961,36.800026,35.0,396.962982,false,Manual,22.0",
            ["Content"] = "好，这样多少能让伤员的情况稳定一些。",
            ["ContentFR"] = "Parfait, cela devrait aider à stabiliser les blessés.",
            ["DialogueId"] = 11010703,
            ["Duration"] = 3,
            ["FinalCamera"] = "-358.041016,-122.882812,148.015259,0.000269,-5.800961,36.800026,35.0,396.962982,false,Manual,22.0",
            ["GUID"] = "1B906B76",
