        [11010806] = {
            ["Content"] = "玩法教学预留",
            ["DialogueId"] = 11010806,
            ["Duration"] = 3,
            ["GUID"] = "1B907C5C",
            ["SpeakNpcId"] = 110005,
            ["VoiceName"] = "voice/$Locale$/story/1002/110108/1B907C5C",
            },
        [11010901] = {
            ["Content"] = "是秽兽！",
            ["ContentFR"] = "Des Souillés !",
            ["DialogueId"] = 11010901,
            ["Duration"] = 3,
            ["GUID"] = "1B908BF2",
            ["SpeakNpcId"] = 110005,
            ["VoiceName"] = "voice/$Locale$/story/1002/110109/1B908BF2",
            },
        [11010902] = {
            ["Content"] = "达芙涅，保护伤员。",
            ["ContentFR"] = "Daphne, protégez les blessés.",
            ["DialogueId"] = 11010902,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B908C1C",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110109/1B908C1C",
            },
        [11010903] = {
            ["Content"] = "……是！",
            ["ContentFR"] = "Oui, Capitaine !",
            ["DialogueId"] = 11010903,
            ["Duration"] = 3,
            ["GUID"] = "1B908C46",
            ["SpeakNpcId"] = 110005,
            ["VoiceName"] = "voice/$Locale$/story/1002/110109/1B908C46",
            },
        [11011001] = {
            ["Content"] = "坚持住，我再试试联系“雪狼”分队！",
            ["ContentFR"] = "Tenez bon ! J’essaie encore de contacter les Loups Blancs !",
            ["DialogueId"] = 11011001,
            ["Duration"] = 3,
            ["GUID"] = "1B909C5A",
            ["GuideFacialId"] = "Afraid",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 11011002,
            ["Scripts"] = "PlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/mute\"},RelatedRegionId{102101}}",
            ["SnapShot"] = "OUTDOOR",
            ["SpeakNpcId"] = 110005,
            ["VoiceName"] = "voice/$Locale$/story/1002/110110/1B909C5A",
            },
        [11011002] = {
            ["Content"] = "还是……没反应……",
            ["ContentFR"] = "Rien... toujours aucun retour...",
            ["DialogueId"] = 11011002,
            ["Duration"] = 3,
            ["GUID"] = "1B909C84",
            ["GuideFacialId"] = "Afraid",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 11011003,
            ["SnapShot"] = "OUTDOOR",
            ["SpeakNpcId"] = 110005,
            ["VoiceName"] = "voice/$Locale$/story/1002/110110/1B909C84",
            },
        [11011003] = {
            ["Content"] = "喂？喂？",
            ["ContentFR"] = "Allô ? Vous me recevez ?",
            ["DialogueId"] = 11011003,
            ["Duration"] = 3,
            ["GUID"] = "1B909CAE",
            ["NextDialogue"] = 11011004,
            ["Scripts"] = "PlayNormalSound{EventPath{\"event:/snapshot/story/ex01_vo_behind_door\"},PlayAs2D{true}}",
            ["SnapShot"] = "OUTDOOR",
            ["SpeakNpcId"] = 110010,
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["VoiceName"] = "voice/$Locale$/story/1002/110110/1B909CAE",
            },
        [11011004] = {
            ["Content"] = "接通了……！",
            ["ContentFR"] = "La liaison... enfin !",
            ["DialogueId"] = 11011004,
            ["Duration"] = 3,
            ["GUID"] = "1B909CD8",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 11011005,
            ["SnapShot"] = "OUTDOOR",
            ["SpeakNpcId"] = 110005,
            ["VoiceName"] = "voice/$Locale$/story/1002/110110/1B909CD8",
            },
        [11011005] = {
            ["Content"] = "<H>海伯利亚今日天气怎么样？</>",
            ["ContentFR"] = "<H>Quel temps fait-il aujourd’hui en Hyperborea ?</>",
            ["DialogueId"] = 11011005,
            ["Duration"] = 3,
            ["GUID"] = "1B909D02",
            ["NextDialogue"] = 11011006,
            ["SnapShot"] = "OUTDOOR",
            ["SpeakNpcId"] = 110010,
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["VoiceName"] = "voice/$Locale$/story/1002/110110/1B909D02",
            },
        [11011006] = {
            ["Content"] = "<H>迪斯玛尼亚今夜有雨。</>",
            ["ContentFR"] = "<H>Il pleut ce soir sur Dismania.</>",
            ["DialogueId"] = 11011006,
            ["Duration"] = 3,
            ["GUID"] = "1B909D2C",
            ["GuideFacialId"] = "Confident",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 11011007,
            ["SnapShot"] = "OUTDOOR",
            ["SpeakNpcId"] = 110005,
            ["VoiceName"] = "voice/$Locale$/story/1002/110110/1B909D2C",
            },
        [11011007] = {
            ["Content"] = "我是阿瓦尔·赫德兰中校。对面的“狮鹫”小队队员，你们在哪里？",
            ["ContentFR"] = "Ici le lieutenant-colonel Avar Hrodland. Des Griffons, donnez votre position.",
            ["DialogueId"] = 11011007,
            ["Duration"] = 3,
            ["GUID"] = "1B909D56",
            ["NextDialogue"] = 11011008,
            ["Scripts"] = "PlayNormalSound{EventPath{\"event:/sfx/common/story/ex01/signal_off\"},PlayAs2D{true}}",
            ["SnapShot"] = "OUTDOOR",
            ["SpeakNpcId"] = 110010,
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["VoiceName"] = "voice/$Locale$/story/1002/110110/1B909D56",
            },
        [11011008] = {
            ["Content"] = "医务员达芙涅·塞奥多尔请求支援。我们当前正位于……",
            ["ContentFR"] = "Ici l’infirmière Daphne Theodore, je demande assistance. Nous sommes actuellement à...",
            ["DialogueId"] = 11011008,
            ["Duration"] = 3,
            ["GUID"] = "1B909D80",
            ["NextDialogue"] = 11011009,
            ["SnapShot"] = "OUTDOOR",
            ["SpeakNpcId"] = 110005,
            ["VoiceName"] = "voice/$Locale$/story/1002/110110/1B909D80",
            },
        [11011009] = {
            ["Content"] = "没完没了……",
            ["ContentFR"] = "Encore eux... ils n’arrêtent jamais...",
            ["DialogueId"] = 11011009,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B909DAA",
            ["Scripts"] = "StopNormalSound{EventPath{\"event:/snapshot/story/ex01_vo_behind_door\"},PlayAs2D{true}}",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110110/1B909DAA",
            },
        [11011010] = {
            ["Content"] = "小鬼，撑住！",
            ["ContentFR"] = "Tiens bon, {性别2:gamin|gamine} !",
            ["DialogueId"] = 11011010,
            ["Duration"] = 3,
            ["GUID"] = "1B909DD4",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110110/1B909DD4",
            },
        [11011011] = {
            ["Content"] = "阿瓦尔老师！",
            ["ContentFR"] = "Commandant Avar !",
            ["DialogueId"] = 11011011,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B909DFE",
            ["NextDialogue"] = 11011012,
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110110/1B909DFE",
            },
        [11011012] = {
            ["Content"] = "嗯，有我呢。你专心应付眼前，背后交给我就是。",
            ["ContentFR"] = "Hmm. Je suis là. Concentre-toi sur ce qui est devant toi, je couvre tes arrières.",
            ["DialogueId"] = 11011012,
            ["GUID"] = "1B909E28",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110110/1B909E28",
            },
        [11011013] = {
            ["Content"] = "我们暂时击退了来袭的秽兽，清理出一个临时休整点，不过这边也坚持不了太久。",
            ["ContentFR"] = "Nous avons repoussé les Souillés et sécurisé un point de repli... mais il ne tiendra pas longtemps.",
            ["DialogueId"] = 11011013,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B909E52",
            ["NextDialogue"] = 11011014,
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110110/1B909E52",
            },
        [11011014] = {
            ["Content"] = "达芙涅紧急救治了伤员，但据伤情判断，他们已经暂时丧失了作战能力。",
            ["ContentFR"] = "Daphne a prodigué les premiers soins, mais vu l’état des blessés, ils sont hors de combat pour le moment.",
            ["DialogueId"] = 11011014,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B909E7C",
            ["NextDialogue"] = 11011015,
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110110/1B909E7C",
            },
        [11011015] = {
            ["Content"] = "……好。你们也辛苦了。",
            ["ContentFR"] = "... Bien. Vous vous en êtes très bien sortis {性别2:tous|toutes} les deux.",
            ["DialogueId"] = 11011015,
            ["GUID"] = "1B909EA6",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110110/1B909EA6",
            },
        [11011016] = {
            ["Content"] = "阿瓦尔长官！哈、哈……你来了！你一定会带着大家……攻下这座要塞……",
            ["ContentFR"] = "Commandant Avar ! Ha... ha... vous êtes venu ! Je le savais... vous allez mener l’assaut... prendre cette maudite forteresse...",
            ["DialogueId"] = 11011016,
            ["GUID"] = "1B909ED0",
            ["NextDialogue"] = 11011017,
            ["SpeakNpcId"] = 110019,
            ["VoiceName"] = "voice/$Locale$/story/1002/110110/1B909ED0",
            },
        [11011017] = {
            ["Content"] = "你们都是好样的，你们的勇敢对得起胸口的徽章，帝国不会让你们在这里白白流血。",
            ["ContentFR"] = "Vous êtes tous de braves soldats. Votre courage honore l’insigne impérial que vous portez. L'Empire ne laissera pas vos efforts être vains.",
            ["DialogueId"] = 11011017,
            ["DialoguePanelType"] = "{type:Guide;style:Communicator}",
            ["GUID"] = "1B909EFA",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110110/1B909EFA",
            },
        [11011018] = {
            ["Content"] = "长官，“雪狼”那边怎么样了？",
            ["ContentFR"] = "Commandant, qu’en est-il des Loups Blancs ?",
            ["DialogueId"] = 11011018,
            ["GUID"] = "1B909F24",
            ["NextDialogue"] = 11011019,
            ["SpeakNpcId"] = 110013,
            ["VoiceName"] = "voice/$Locale$/story/1002/110110/1B909F24",
            },
        [11011019] = {
            ["Content"] = "雪狼分队一切正常。我已经联系上了总指挥官，你们尽管放心休息，接下来就交给我们。",
            ["ContentFR"] = "Ils poursuivent leur mission. J’ai établi contact avec le commandement. Reposez-vous, à présent, c’est notre tour de tenir le front.",
            ["DialogueId"] = 11011019,
            ["DialoguePanelType"] = "{type:Guide;style:Communicator}",
            ["GUID"] = "1B909F4E",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110110/1B909F4E",
            },
        [11011020] = {
            ["Content"] = "阿瓦尔长官？我……在做梦吗……",
            ["ContentFR"] = "Commandant Avar... ? Est-ce que je... rêve... ?",
            ["DialogueId"] = 11011020,
            ["GUID"] = "1B909F78",
            ["NextDialogue"] = 11011021,
            ["SpeakNpcId"] = 110027,
            ["SpeakNpcName"] = "UI_Npc_Hurtsoldier",
            ["VoiceName"] = "voice/$Locale$/story/1002/110110/1B909F78",
            },
        [11011021] = {
            ["Content"] = "这不是梦。坚持住，别睡着。",
            ["ContentFR"] = "Non, ce n’est pas un rêve. Accroche-toi, ne t’endors pas.",
            ["DialogueId"] = 11011021,
            ["DialoguePanelType"] = "{type:Guide;style:Communicator}",
            ["GUID"] = "1B909FA2",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110110/1B909FA2",
            },
        [11011022] = {
            ["Content"] = "向您致意……长官……荣耀……尽归吾皇……",
            ["ContentFR"] = "Mes respects... Commandant... Toute gloire... à l’Empereur...",
            ["DialogueId"] = 11011022,
            ["GUID"] = "1B909FCC",
            ["NextDialogue"] = 11011023,
            ["SpeakNpcId"] = 110028,
            ["SpeakNpcName"] = "UI_Npc_Hurtsoldier",
            ["VoiceName"] = "voice/$Locale$/story/1002/110110/1B909FCC",
            },
        [11011023] = {
            ["Content"] = "荣耀尽归吾皇。",
            ["ContentFR"] = "Toute gloire à l’Empereur.",
            ["DialogueId"] = 11011023,
            ["DialoguePanelType"] = "{type:Guide;style:Communicator}",
            ["GUID"] = "1B909FF6",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110110/1B909FF6",
            },
        [11011024] = {
            ["Content"] = "长官，以你们的判断，这次作战还有希望吗？",
            ["ContentFR"] = "Capitaine... Commandant... selon vous... avons-nous encore une chance... ?",
            ["DialogueId"] = 11011024,
            ["GUID"] = "1B90A020",
            ["NextDialogue"] = 11011025,
            ["SpeakNpcId"] = 110026,
            ["SpeakNpcName"] = "UI_Npc_Hurtsoldier",
            ["VoiceName"] = "voice/$Locale$/story/1002/110110/1B90A020",
            },
        [11011025] = {
            ["Content"] = "以当前的战况来看——",
            ["ContentFR"] = "Au vu de la situation—",
            ["DialogueId"] = 11011025,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B90A04A",
            ["NextDialogue"] = 11011026,
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110110/1B90A04A",
            },
        [11011026] = {
            ["Content"] = "以当前的战况来看，援军就在路上。我们很快会夺下要塞，把那群混蛋打得头破血流。",
            ["ContentFR"] = "Au vu de la situation, les renforts sont déjà en route. Bientôt nous prendrons cette forteresse... et nous écraserons ces ordures.",
            ["DialogueId"] = 11011026,
            ["DialoguePanelType"] = "{type:Guide;style:Communicator}",
            ["GUID"] = "1B90A074",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110110/1B90A074",
            },
        [11011101] = {
            ["Camera"] = "320.033203,-633.472656,260.888916,0.000053,-14.19958,121.341087,35.0,100000.0,false,Manual,22.0",
            ["Content"] = "我看过大家的情况了。",
            ["ContentFR"] = "J’ai vu l’état de tout le monde.",
            ["DialogueId"] = 11011101,
