            },
        [11011104] = {
            ["Camera"] = "12.376953,-125.480469,170.74292,0.000094,-16.799561,120.343758,35.0,156.802643,false,Manual,22.0",
            ["Content"] = "…………",
            ["ContentFR"] = "...",
            ["DialogueId"] = 11011104,
            ["Duration"] = 2,
            ["ExStoryInfo"] = "EXPlayer",
            ["FinalCamera"] = "55.464844,75.96875,136.202271,0.000162,-0.799071,-141.863129,35.0,100000.0,false,Manual,22.0",
            ["GUID"] = "1B90AD40",
            ["LookAt"] = {
                [1] = "110022:n(110010)",
                },
            ["NextDialogue"] = 11011105,
            ["SpeakNpcId"] = 110022,
            ["TalkActionId"] = {
                [1] = "110010:Talk01_End",
                [2] = "110022:Talk03_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1002/110111/1B90AD40",
            },
        [11011105] = {
            ["Camera"] = "188.898438,-212.304688,167.597046,0.000095,-7.799229,148.346283,35.0,156.802643,false,Manual,22.0",
            ["Content"] = "……你们经历的事，我多少能猜到。牺牲的士兵，一路上我也都看见了。",
            ["ContentFR"] = "... Je peux deviner ce que vous avez traversé. J’ai croisé bien des corps de nos frères d’armes en chemin.",
            ["DialogueId"] = 11011105,
            ["GUID"] = "1B90AD6A",
            ["LookAt"] = {
                [1] = "110022:n(110010)",
                [2] = "110010:n(110022)",
                },
            ["NextDialogue"] = 11011106,
            ["SpeakNpcId"] = 110010,
            ["TalkActionId"] = {
                [1] = "110010:Angry01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110111/1B90AD6A",
            },
        [11011106] = {
            ["Camera"] = "69.240234,215.199219,99.495483,0.000099,4.600453,-108.653275,35.000011,156.802643,false,Manual,22.0",
            ["Content"] = "但你们是军人。哀悼的话，留到平安下了战场之后再说。",
            ["ContentFR"] = "Mais vous êtes des soldats. Le deuil, vous le ferez une fois rentrés vivants à la maison.",
            ["DialogueId"] = 11011106,
            ["GUID"] = "1B90AD94",
            ["NextDialogue"] = 11011107,
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110111/1B90AD94",
            },
        [11011107] = {
            ["Camera"] = "406.134766,-770.574219,382.053101,0.000118,-19.199175,118.339554,35.000008,393.038635,false,Manual,22.0",
            ["Content"] = "所以，你们两个还好吗？",
            ["ContentFR"] = "Alors, vous tenez le coup, {性别2:tous|toutes} les deux ?",
            ["DialogueId"] = 11011107,
            ["GUID"] = "1B90ADBE",
            ["NextDialogue"] = 11011108,
            ["Scripts"] = "SEQ{\
LookAt{_delay{0},LookAtDescription{\"110010:n(110005)\"}}\
}",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110111/1B90ADBE",
            },
        [11011108] = {
            ["Content"] = "…………",
            ["ContentFR"] = "...",
            ["DialogueId"] = 11011108,
            ["Duration"] = 1,
            ["GUID"] = "1B90ADE8",
            ["NextDialogue"] = 11011109,
            ["SpeakNpcId"] = 110005,
            ["VoiceName"] = "voice/$Locale$/story/1002/110111/1B90ADE8",
            },
        [11011109] = {
            ["Camera"] = "200.347656,-143.699219,122.130127,0.000149,0.401171,130.725189,40.0,393.038635,false,Manual,22.0",
            ["Content"] = "当然，我们很好。只是按上头的命令办事，差点全都死在这儿而已，没什么不好，有劳长官您挂心了。",
            ["ContentFR"] = "Bien sûr. Tout va bien. Nous avons seulement obéi aux ordres d’en haut et failli tous mourir ici. Merci de votre sollicitude, mon commandant.",
            ["DialogueId"] = 11011109,
            ["FacialId"] = {
                [1] = "110005:Unhappy01",
                },
            ["GUID"] = "1B90AE12",
            ["LookAt"] = {
                [1] = "110010:n(110005)",
                },
            ["NextDialogue"] = 11011110,
            ["Scripts"] = "SEQ{PlayAnimation{_delay{2},ActorId{110005},AnimationId{\"Explain02_End\"},Duration{2}},PlayAnimation{_delay{2},ActorId{110005},AnimationId{\"Talk03_Start\"},Duration{2}}\
}",
            ["SpeakNpcId"] = 110005,
            ["VoiceName"] = "voice/$Locale$/story/1002/110111/1B90AE12",
            },
        [11011110] = {
            ["Camera"] = "165.154297,-152.988281,127.279175,0.000189,3.000673,168.357956,40.000023,209.628448,false,Manual,22.0",
            ["Content"] = "你这小鬼——算了。",
            ["ContentFR"] = "Petite... tss. Laisse tomber.",
            ["DialogueId"] = 11011110,
            ["GUID"] = "1B90AE3C",
            ["NextDialogue"] = 11011111,
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{110010},AnimationId{\"Sigh_Start\"},Duration{2}},\
PlayAnimation{ActorId{110010},AnimationId{\"Sigh_End\"},Duration{2}}\
}",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110111/1B90AE3C",
            },
        [11011111] = {
            ["Camera"] = "-3.65625,147.421875,116.083008,0.000099,3.800829,-101.856186,35.000008,156.802643,false,Manual,22.0",
            ["Content"] = "{nickname2}，你来报告。",
            ["ContentFR"] = "{nickname2}, fais ton rapport.",
            ["DialogueId"] = 11011111,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B90AE66",
            ["LookAt"] = {
                [1] = "110010:n(110022)",
                [2] = "110005:n(110022)",
                },
            ["NextDialogue"] = 11011112,
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110111/1B90AE66",
            },
        [11011112] = {
            ["Camera"] = "150.466797,-241.613281,146.286743,0.000109,-4.599121,138.34343,35.0,720.519287,false,Manual,22.0",
            ["Content"] = "是。“狮鹫”分队原本按照计划，与您所在的“雪狼”分队分两路向龙莎要塞发起攻势——这是您知道的。但在潜入要塞后，我们遭遇了伏击。",
            ["ContentFR"] = "Oui, mon commandant. Le plan prévoyait une attaque conjointe : les Griffons et les Loups Blancs devaient prendre la Forteresse de Lonza par deux voies. Mais à peine infiltrés, nous sommes tombés dans une embuscade.",
            ["DialogueId"] = 11011112,
            ["ExStoryInfo"] = "EXPlayer",
            ["FinalCamera"] = "156.564453,-234.769531,146.286743,0.000109,-4.599121,138.34343,35.0,720.519287,false,Manual,22.0",
            ["GUID"] = "1B90AE90",
            ["LookAt"] = {
                [1] = "110022:n(110010)",
                },
            ["NextDialogue"] = 11011113,
            ["RelatedWikiId"] = {
                [1] = 408007,
                },
            ["Scripts"] = "SEQ{PlayAnimation{ActorId{110022},AnimationId{\"Explain02_Start\"},Duration{2}},PlayAnimation{_delay{6},ActorId{110022},AnimationId{\"Explain02_End\"},Duration{2}}\
}",
            ["SpeakNpcId"] = 110022,
            ["TalkActionId"] = {
                [1] = "110005:Explain02_End",
                },
            ["ToFinalCameraBlendTime"] = 15,
            ["VoiceName"] = "voice/$Locale$/story/1002/110111/1B90AE90",
            },
        [11011113] = {
            ["Camera"] = "350.375,-614.980469,260.890625,0.000052,-14.19958,121.341087,35.0,100000.0,false,Manual,22.0",
            ["Content"] = "各区域间的通道被封锁，我方小部分队员失联，其余则伤亡惨重。向外的通讯也被切断了——我们被困在了这里。",
            ["ContentFR"] = "Les couloirs reliant les secteurs ont été scellés. Nous avons perdu le contact avec certains camarades. Les autres sont morts ou grièvement blessés. Nos communications vers l’extérieur ont aussi été coupées : nous sommes piégés.",
            ["DialogueId"] = 11011113,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B90AEBA",
            ["NextDialogue"] = 11011114,
            ["Scripts"] = "SEQ{\
PlayAnimation{_delay{0},ActorId{110022},AnimationId{\"Talk02_Start\"},Duration{2}},\
PlayAnimation{_delay{0.5},ActorId{110022},AnimationId{\"Talk02_End\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110111/1B90AEBA",
            },
        [11011114] = {
            ["Camera"] = "54.410156,219.574219,135.06189,0.000141,-1.200686,-103.445839,35.0,209.628448,false,Manual,22.0",
            ["Content"] = "“雪狼”分队的情况和你们差不多。情况你们自己知道，先别讲给伤员。",
            ["ContentFR"] = "Les Loups Blancs ont subi le même sort. Mais inutile d’alarmer les blessés.",
            ["DialogueId"] = 11011114,
            ["FacialId"] = {
                [1] = "110005:Iyada01",
                },
            ["FinalCamera"] = "81.892578,211.804688,135.06189,0.000141,-1.00067,-109.046188,35.0,209.628448,false,Manual,22.0",
            ["GUID"] = "1B90AEE4",
            ["NextDialogue"] = 11011115,
            ["SpeakNpcId"] = 110010,
            ["TalkActionId"] = {
                [1] = "110010:Think_Start",
                },
            ["ToFinalCameraBlendTime"] = 15,
            ["VoiceName"] = "voice/$Locale$/story/1002/110111/1B90AEE4",
            },
        [11011115] = {
            ["Content"] = "嗯……现在整个“狮鹫”分队能行动的，只剩下你们俩了吗……",
            ["ContentFR"] = "Hmm... donc il ne reste plus que vous deux de valides, côté Griffons...",
            ["DialogueId"] = 11011115,
            ["GUID"] = "1B90AF0E",
            ["LookAt"] = {
                [1] = "110010:n(110005)",
                [2] = "110005:n(110010)",
                },
            ["NextDialogue"] = 11011116,
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110111/1B90AF0E",
            },
        [11011116] = {
            ["Content"] = "达芙涅，刚才我们打通了仓储区和加工区的通路，中间有片区域还算安全。我给出了信号，待会儿会有人护送你们过去休整。",
            ["ContentFR"] = "Daphne, nous avons rouvert la voie entre les entrepôts et la zone de traitement. Au milieu, il y a un secteur relativement sûr. J’ai donné le signal, une escorte viendra vous y conduire pour souffler un peu.",
            ["DialogueId"] = 11011116,
            ["GUID"] = "1B90AF38",
            ["LookAt"] = {
                [1] = "110010:n(110005)",
                },
            ["NextDialogue"] = 11011117,
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110111/1B90AF38",
            },
        [11011117] = {
            ["Camera"] = "-163.324219,118.648438,119.937622,0.000208,2.601052,-56.642597,35.000008,209.628448,false,Manual,22.0",
            ["Content"] = "{nickname2}，你跟我走，继续行动。",
            ["ContentFR"] = "{nickname2}, toi tu viens avec moi. Nous continuons la mission.",
            ["DialogueId"] = 11011117,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B90AF62",
            ["LookAt"] = {
                [1] = "110010:n(110022)",
                },
            ["NextDialogue"] = 11011118,
            ["SpeakNpcId"] = 110010,
            ["TalkActionId"] = {
                [1] = "110010:Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110111/1B90AF62",
            },
        [11011118] = {
            ["Camera"] = "-231.441406,-234.425781,161.725586,0.00019,-6.598844,42.156822,35.000008,209.628448,false,Manual,22.0",
            ["Content"] = "我也可以行动，请让我——唔！",
            ["ContentFR"] = "Je peux encore me battre ! Laissez-moi venir— ah !",
            ["DialogueId"] = 11011118,
            ["Duration"] = 1,
            ["FacialId"] = {
                [1] = "110005:Iyada01",
                },
            ["GUID"] = "1B90AF8C",
