  { MinKey = 11011135, MaxKey = 11011841, Loader = function()
      return {
        [11011135] = {
            ["Content"] = "……好好休息。听老师的话，去休整点吧。",
            ["ContentFR"] = "... Repose-toi. Suis les ordres du Commandant Avar, rends-toi au point de repli.",
            ["DialogueId"] = 11011135,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
