            ["NextDialogue"] = 11011136,
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110111/1B90B256",
            },
        [11011136] = {
            ["Content"] = "等回皇都，我会去看你。",
            ["ContentFR"] = "Quand nous serons rentrés dans la capitale, j’irai te voir.",
            ["DialogueId"] = 11011136,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B90B280",
            ["NextDialogue"] = 11011137,
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110111/1B90B280",
            },
        [11011137] = {
            ["Content"] = "嗯。长官都那么说了，我也没有别的选择。但是，我总担心……",
            ["ContentFR"] = "Hmm. Puisque le commandant l’a dit, je n’ai pas le choix... mais je reste inquiète.",
            ["DialogueId"] = 11011137,
