            ["Duration"] = 3,
            ["GUID"] = "1B90BD54",
            ["NextDialogue"] = 11011203,
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110112/1B90BD54",
            },
        [11011203] = {
            ["Content"] = "要是同盟是野蛮人，那帝国让人家占了大半年要塞，岂不是还不如野蛮人？",
            ["ContentFR"] = "Si ce sont des sauvages... alors comment expliquer qu’ils contrôlent cette forteresse depuis plus de six mois ? Cela ferait de l’Empire quelque chose de pire encore.",
            ["DialogueId"] = 11011203,
            ["Duration"] = 3,
            ["GUID"] = "1B90BD7E",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 11011204,
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110112/1B90BD7E",
            },
        [11011204] = {
            ["Content"] = "嗯……高层太轻敌了。",
            ["ContentFR"] = "Oui... les haut-gradés ont été bien trop confiants.",
            ["DialogueId"] = 11011204,
