            },
        [11011205] = {
            ["Content"] = "论“指挥的艺术”，没人比富尔维斯在行。",
            ["ContentFR"] = "Pour ce qui est de \"l’art du commandement\", personne ne surpasse Fulvis.",
            ["DialogueId"] = 11011205,
            ["Duration"] = 3,
            ["GUID"] = "1B90BDD2",
            ["NextDialogue"] = 11011206,
            ["SpeakNpcId"] = 110010,
