            ["VoiceName"] = "voice/$Locale$/story/1002/110114/1B90E01C",
            },
        [11011415] = {
            ["Content"] = "任务继续。",
            ["ContentFR"] = "On continue.",
            ["DialogueId"] = 11011415,
            ["Duration"] = 3,
            ["GUID"] = "1B90E046",
            ["GuideFacialId"] = "Angry",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 11011418,
            ["SnapShot"] = "TELEPHONE",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110114/1B90E046",
            },
        [11011416] = {
            ["Content"] = "除了独立供能的中央控制室，整座要塞运转需要的月髓液都在这里。",
            ["DialogueId"] = 11011416,
            ["Duration"] = 3,
            ["GUID"] = "1B90E047",
            ["GuideFacialId"] = "Angry",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 11011417,
            ["SnapShot"] = "TELEPHONE",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110114/1B90E047",
            },
        [11011417] = {
            ["Content"] = "破坏这里的动力装置，要塞中的大部分机关就会停止运转。",
            ["DialogueId"] = 11011417,
            ["Duration"] = 3,
            ["GUID"] = "1B90E048",
            ["GuideFacialId"] = "Angry",
            ["HeadIconType"] = "Npc",
            ["SnapShot"] = "TELEPHONE",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110114/1B90E048",
            },
        [11011418] = {
            ["Content"] = "我们必须让那些机关瘫痪掉……维克不能白白牺牲。",
            ["ContentFR"] = "Ces systèmes doivent tomber... Vic ne doit pas mourir pour rien.",
            ["DialogueId"] = 11011418,
            ["Duration"] = 3,
            ["GUID"] = "1B90E0C4",
            ["GuideFacialId"] = "Angry",
            ["HeadIconType"] = "Npc",
            ["SnapShot"] = "TELEPHONE",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110114/1B90E0C4",
            },
        [11011419] = {
            ["Content"] = "哦？已经处理好一个了吗，小心些，我好像听到秽兽靠过来的声音了。",
            ["DialogueId"] = 11011419,
            ["Duration"] = 3,
            ["GUID"] = "1B90E0EE",
            ["SnapShot"] = "TELEPHONE",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110114/1B90E0EE",
            },
        [11011420] = {
            ["Content"] = "好，{nickname2}，动力链接已经断开了，我们得趁现在去把整个动力装置都毁了。",
            ["DialogueId"] = 11011420,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B90E118",
            ["NextDialogue"] = 11011421,
            ["SnapShot"] = "TELEPHONE",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110114/1B90E118",
            },
        [11011421] = {
            ["Content"] = "核心的动力炉就在下面，小心些……",
            ["DialogueId"] = 11011421,
            ["Duration"] = 3,
            ["GUID"] = "1B90E142",
            ["NextDialogue"] = 11011422,
            ["SnapShot"] = "TELEPHONE",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110114/1B90E142",
            },
        [11011422] = {
            ["Content"] = "有些脏东西围过来了……事办妥了再上来集合！",
            ["DialogueId"] = 11011422,
            ["Duration"] = 3,
            ["GUID"] = "1B90E16C",
            ["NextDialogue"] = 11011423,
            ["SnapShot"] = "TELEPHONE",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110114/1B90E16C",
            },
        [11011423] = {
            ["Content"] = "好……",
            ["DialogueId"] = 11011423,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B90E196",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110114/1B90E196",
            },
        [11011424] = {
            ["Content"] = "我会逐个解锁防护屏障，等信号亮起，你就把月髓舱打碎！",
            ["DialogueId"] = 11011424,
            ["Duration"] = 3,
            ["GUID"] = "1B90E1C0",
            ["NextDialogue"] = 11011425,
            ["SnapShot"] = "TELEPHONE",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110114/1B90E1C0",
            },
        [11011425] = {
            ["Content"] = "有些月髓舱可能会配备自毁装置，如果听到倒计时响起，就终止行动，马上离开。",
            ["DialogueId"] = 11011425,
            ["Duration"] = 3,
            ["GUID"] = "1B90E1C1",
            ["SnapShot"] = "TELEPHONE",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110114/1B90E1C1",
            },
        [11011426] = {
            ["Content"] = "就是现在，打碎它！",
            ["DialogueId"] = 11011426,
            ["Duration"] = 3,
            ["GUID"] = "1B90E1C2",
            ["SnapShot"] = "TELEPHONE",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110114/1B90E1C2",
            },
        [11011427] = {
            ["Content"] = "干得不错，我们还有两个要处理。",
            ["DialogueId"] = 11011427,
            ["Duration"] = 3,
            ["GUID"] = "1B90E1C3",
            ["SnapShot"] = "TELEPHONE",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110114/1B90E1C3",
            },
        [11011428] = {
            ["Content"] = "2号月髓舱的屏障解锁了，上吧！",
            ["DialogueId"] = 11011428,
            ["Duration"] = 3,
            ["GUID"] = "1B90E1C4",
            ["SnapShot"] = "TELEPHONE",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110114/1B90E1C4",
            },
        [11011429] = {
            ["Content"] = "呼……还有最后一个，你那儿还行吗？",
            ["DialogueId"] = 11011429,
            ["Duration"] = 3,
            ["GUID"] = "1B90E1C5",
            ["NextDialogue"] = 11011430,
            ["SnapShot"] = "TELEPHONE",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110114/1B90E1C5",
            },
        [11011430] = {
            ["Content"] = "没问题。",
