            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B90E1C6",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110114/1B90E1C6",
            },
        [11011432] = {
