            ["GUID"] = "1B90E2E7",
            ["SnapShot"] = "TELEPHONE",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110114/1B90E2E7",
            },
        [11011433] = {
