        [11011540] = {
            ["Camera"] = "-355.052734,1504.162109,650.109497,0.000091,-19.999565,-79.788002,28.000006,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "队长、队长！",
            ["ContentFR"] = "Capitaine ! Capitaine !",
            ["DialogueId"] = 11011540,
            ["DialoguePanelType"] = "{type:Guide;style:Communicator}",
            ["FinalCamera"] = "-330.253906,1366.505859,599.202942,0.00009,-19.999557,-79.787865,28.000006,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "1B90F4C8",
            ["NextDialogue"] = 11011541,
            ["Scripts"] = "PlayNormalSound{EventPath{\"event:/sfx/common/story/ex01/signal_on\"},PlayAs2D{true}}",
            ["SnapShot"] = "TELEPHONE",
