                [1] = "110022:Call_Start",
                },
            ["ToFinalCameraBlendTime"] = 15,
            ["VoiceName"] = "voice/$Locale$/story/1002/110115/1B90F4C8",
            },
        [11011541] = {
            ["Content"] = "我是“狮鹫”分队的西蒙，队长，你在吗？",
            ["ContentFR"] = "Ici Simon des Griffons, capitaine, vous me recevez ?",
            ["DialogueId"] = 11011541,
            ["DialoguePanelType"] = "{type:Guide;style:Communicator}",
            ["GUID"] = "1B90F4F2",
            ["NextDialogue"] = 11011542,
            ["SnapShot"] = "TELEPHONE",
            ["SpeakNpcName"] = "UI_Npc_HelpVoice",
            ["VoiceName"] = "voice/$Locale$/story/1002/110115/1B90F4F2",
            },
        [11011542] = {
            ["Camera"] = "-140.854004,198.513672,147.002014,1.0,-9.599516,-74.977852,28.000006,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我在听。西蒙，你在哪里？",
            ["ContentFR"] = "Je vous écoute. Simon, où êtes‑vous ?",
            ["DialogueId"] = 11011542,
            ["ExStoryInfo"] = "EXPlayer",
            ["FinalCamera"] = "-133.268555,200.566406,146.866943,0.999995,-9.599516,-74.977119,28.000006,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "1B90F51C",
            ["NextDialogue"] = 11011543,
            ["SpeakNpcId"] = 110022,
            ["ToFinalCameraBlendTime"] = 20,
            ["VoiceName"] = "voice/$Locale$/story/1002/110115/1B90F51C",
            },
        [11011543] = {
            ["Content"] = "轨道线一带有大片秽兽，大家被困在里面，请求支援！",
            ["ContentFR"] = "Sur la ligne de rails, entourés par une horde de Souillés. On est coincés, besoin de renforts !",
            ["DialogueId"] = 11011543,
            ["DialoguePanelType"] = "{type:Guide;style:Communicator}",
            ["GUID"] = "1B90F546",
            ["NextDialogue"] = 11011544,
            ["SnapShot"] = "TELEPHONE",
            ["SpeakNpcName"] = "UI_Npc_HelpVoice",
            ["VoiceName"] = "voice/$Locale$/story/1002/110115/1B90F546",
            },
        [11011544] = {
            ["Content"] = "拜托……你了！",
            ["ContentFR"] = "S’il vous plaît... Capitaine !",
            ["DialogueId"] = 11011544,
            ["DialoguePanelType"] = "{type:Guide;style:Communicator}",
            ["GUID"] = "1B90F570",
            ["NextDialogue"] = 11011545,
            ["SnapShot"] = "TELEPHONE",
            ["SpeakNpcName"] = "UI_Npc_HelpVoice",
            ["VoiceName"] = "voice/$Locale$/story/1002/110115/1B90F570",
            },
        [11011545] = {
            ["Camera"] = "-3.358398,-61.634766,129.081787,0.000143,-6.799275,-81.393707,28.000006,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "…………",
            ["ContentFR"] = "...",
            ["DialogueId"] = 11011545,
            ["ExStoryInfo"] = "EXPlayer",
            ["FacialId"] = {
                [1] = "110022:Angry01",
                },
            ["GUID"] = "1B90F59A",
            ["NextDialogue"] = 11011546,
            ["Scripts"] = "PlayNormalSound{EventPath{\"event:/sfx/common/story/ex01/signal_off\"},PlayAs2D{true}}",
            ["SpeakNpcId"] = 110022,
            ["TalkActionId"] = {
                [1] = "110022:Call_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110115/1B90F59A",
            },
        [11011546] = {
            ["Camera"] = "170.827637,-188.957031,121.458923,0.000164,-2.399261,154.39566,28.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我也收到了另一队士兵汇报位置的信号，就在刚结束富尔维斯通讯的时候。{nickname2}，你怎么打算？",
            ["ContentFR"] = "J’ai reçu le signal d’une autre escouade juste après ton appel avec Fulvis. {nickname2}, que proposes‑tu ?",
            ["DialogueId"] = 11011546,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B90F5C4",
            ["LookAt"] = {
                [1] = "110010:n(110022)",
                },
            ["NextOptions"] = {
                [1] = 11011547,
                [2] = 11011549,
                },
            ["SpeakNpcId"] = 110010,
            ["TalkActionId"] = {
                [1] = "110010:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110115/1B90F5C4",
            },
        [11011547] = {
            ["Content"] = "我想先去救援士兵们，现在的情况，只靠我们没什么胜算。",
            ["ContentFR"] = "<I>Je veux aller secourir les soldats d’abord. Seuls, nous n’avons aucune chance.</>",
            ["DialogueId"] = 11011547,
            ["GUID"] = "1B90F5EE",
            ["ImprPlusId"] = 1009,
            ["NextDialogue"] = 11011548,
            },
        [11011548] = {
            ["Camera"] = "170.827637,-188.957031,121.458923,0.000164,-2.399261,154.39566,28.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "你啊……我果然没看错你。",
            ["ContentFR"] = "Je le savais... je ne me suis pas trompé sur toi.",
            ["DialogueId"] = 11011548,
            ["Duration"] = 3,
            ["GUID"] = "1B90F618",
            ["LookAt"] = {
                [1] = "110010:n(110022)",
                },
            ["NextDialogue"] = 11011550,
            ["SpeakNpcId"] = 110010,
            ["TalkActionId"] = {
                [1] = "110010:Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110115/1B90F618",
            },
        [11011549] = {
            ["Content"] = "我认为即使胜算不大，也应该执行总指挥官的命令。",
            ["ContentFR"] = "<I>Même si les chances sont faibles, on doit suivre les ordres du Commandant en Chef.</>",
            ["DialogueId"] = 11011549,
            ["GUID"] = "1B90F642",
            ["ImprPlusId"] = 1007,
            ["NextDialogue"] = 11011550,
            },
        [11011550] = {
            ["Camera"] = "276.480469,1274.542969,240.643982,0.000117,-3.999116,-107.394035,28.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "富尔维斯傲慢又好大喜功，他高高在上地指挥你，靠的不过是富尔维斯家族在元老院中的世袭席位。",
            ["ContentFR"] = "Fulvis n’est qu’un prétentieux avide de pouvoir. C’est uniquement grâce à sa lignée sénatoriale qu’il est là-haut, à t’aboyer des ordres.",
            ["DialogueId"] = 11011550,
            ["Duration"] = 3,
            ["FinalCamera"] = "236.748047,1279.9375,274.560486,0.000103,-3.999116,-107.394089,28.000006,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "1B90F66C",
            ["LookAt"] = {
                [1] = "110010:n(110022)",
                },
            ["NextDialogue"] = 11011551,
            ["SpeakNpcId"] = 110010,
            ["TalkActionId"] = {
                [1] = "110010:Talk03_Start",
                },
            ["ToFinalCameraBlendTime"] = 25,
            ["VoiceName"] = "voice/$Locale$/story/1002/110115/1B90F66C",
            },
        [11011551] = {
            ["Content"] = "士兵们在他眼里是汇报书里的一串数字，勋章上的一块铁，唯独不是活生生的人。",
            ["ContentFR"] = "Pour lui, les soldats ne sont que des chiffres ou des médailles, pas des êtres humains.",
            ["DialogueId"] = 11011551,
            ["Duration"] = 3,
            ["GUID"] = "1B90F696",
            ["NextDialogue"] = 11011552,
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110115/1B90F696",
            },
        [11011552] = {
            ["Camera"] = "-23.271973,-38.910156,134.332947,0.000116,-1.398891,154.005493,28.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "更何况，战场瞬息万变，他空对着一张地图又能知道什么？",
            ["ContentFR"] = "Et sur un champ de bataille en perpétuel mouvement, que peut-il savoir en regardant une carte ?",
            ["DialogueId"] = 11011552,
            ["Duration"] = 3,
            ["GUID"] = "1B90F6C0",
            ["NextDialogue"] = 11011553,
            ["SpeakNpcId"] = 110010,
            ["TalkActionId"] = {
                [1] = "110010:Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110115/1B90F6C0",
            },
        [11011553] = {
            ["Camera"] = "-116.939453,59.931641,129.807434,0.000084,-6.599089,-65.392105,28.000008,100000.0,false,Manual,8.0",
            ["Content"] = "去救你的战友，{nickname2}。富尔维斯事后问责起来，就说是我的命令。",
            ["ContentFR"] = "Va secourir tes camarades, {nickname2}. Si Fulvis cherche à blâmer quelqu’un après, considère que c’est un ordre direct de ma part.",
            ["DialogueId"] = 11011553,
            ["Duration"] = 3,
            ["GUID"] = "1B90F6EA",
            ["NextDialogue"] = 11011554,
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110115/1B90F6EA",
            },
        [11011554] = {
            ["Content"] = "是。",
            ["ContentFR"] = "Oui, commandant.",
            ["DialogueId"] = 11011554,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B90F714",
            ["NextDialogue"] = 11011555,
            ["SpeakNpcId"] = 110022,
            ["TalkActionId"] = {
                [1] = "110022:AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110115/1B90F714",
            },
        [11011555] = {
            ["Camera"] = "57.235352,-148.5625,119.510437,0.000097,-0.398992,145.808975,28.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我和莫妮卡也出发去救援另一群士兵，他们被困在了4号炮台附近。",
            ["ContentFR"] = "Monica et moi allons secourir une autre escouade coincée près de la tourelle 4.",
            ["DialogueId"] = 11011555,
            ["Duration"] = 3,
            ["GUID"] = "1B90F73E",
            ["NextDialogue"] = 11011556,
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110115/1B90F73E",
            },
        [11011556] = {
            ["Content"] = "……我们刚刚解除了动力，炮台的自动防御应该停止了……或许可以考虑先攻下炮台……",
            ["ContentFR"] = "Nous venons de neutraliser l’alimentation, l’autodéfense de la tourelle devrait être hors service... On pourrait envisager de la prendre en premier.",
            ["DialogueId"] = 11011556,
            ["Duration"] = 3,
            ["GUID"] = "1B90F768",
            ["NextDialogue"] = 11011557,
            ["SpeakNpcId"] = 110010,
            ["TalkActionId"] = {
                [1] = "110010:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110115/1B90F768",
            },
        [11011557] = {
            ["Content"] = "……这样一来，我们还能用月髓炮轰开中心区的防御设施。",
            ["ContentFR"] = "Ainsi, nous pourrons utiliser le Canon Phoxichor pour détruire les défenses autour de la zone centrale.",
            ["DialogueId"] = 11011557,
            ["Duration"] = 3,
            ["GUID"] = "1B90F769",
            ["NextDialogue"] = 11011558,
            ["SpeakNpcId"] = 110010,
            ["TalkActionId"] = {
                [1] = "110010:Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110115/1B90F769",
            },
        [11011558] = {
            ["Camera"] = "-3.358398,-61.634766,129.081787,0.000143,-6.799255,-81.393669,28.000006,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "就这么办吧。如果你那边顺利，等下就到4号炮台来。",
            ["ContentFR"] = "C’est décidé. Si tout se passe bien pour toi, rejoins‑moi à la tourelle 4.",
            ["DialogueId"] = 11011558,
            ["GUID"] = "1B90F76A",
            ["SpeakNpcId"] = 110010,
            ["TalkActionId"] = {
                [1] = "110022:AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110115/1B90F76A",
            },
        [11011601] = {
