        [11011705] = {
            ["Content"] = "……喂？",
            ["ContentFR"] = "... Allô ?",
            ["DialogueId"] = 11011705,
            ["Duration"] = 3,
            ["GUID"] = "1B910FDA",
            ["NextDialogue"] = 11011706,
            ["Scripts"] = "PlayNormalSound{EventPath{\"event:/sfx/common/story/ex01/signal_on\"},PlayAs2D{true}}",
            ["SnapShot"] = "TELEPHONE",
            ["SpeakNpcId"] = 110005,
            ["VoiceName"] = "voice/$Locale$/story/1002/110117/1B910FDA",
            },
        [11011706] = {
            ["Content"] = "喂？我是“狮鹫”分队医务员达芙涅·塞奥多尔。",
            ["ContentFR"] = "Allô ? Ici Daphne Theodore, médecin des Griffons.",
            ["DialogueId"] = 11011706,
            ["Duration"] = 3,
            ["GUID"] = "1B911004",
            ["NextDialogue"] = 11011707,
            ["SnapShot"] = "TELEPHONE",
            ["SpeakNpcId"] = 110005,
            ["VoiceName"] = "voice/$Locale$/story/1002/110117/1B911004",
            },
        [11011707] = {
            ["Content"] = "……{nickname2}？是你吗？为什么不说话？你受伤了？",
            ["ContentFR"] = "... {nickname2} ? C’est vous ? Pourquoi ne dites-vous rien ? Vous êtes {性别2:blessé|blessée} ?",
            ["DialogueId"] = 11011707,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B91102E",
            ["NextDialogue"] = 11011708,
            ["SnapShot"] = "TELEPHONE",
            ["SpeakNpcId"] = 110005,
            ["VoiceName"] = "voice/$Locale$/story/1002/110117/1B91102E",
            },
        [11011708] = {
            ["Content"] = "你在哪儿？我马上申请赶过去……",
            ["ContentFR"] = "Où êtes-vous ? Je peux demander l’autorisation de venir vous chercher...",
            ["DialogueId"] = 11011708,
            ["Duration"] = 3,
            ["GUID"] = "1B911058",
            ["NextDialogue"] = 11011709,
            ["SnapShot"] = "TELEPHONE",
            ["SpeakNpcId"] = 110005,
            ["VoiceName"] = "voice/$Locale$/story/1002/110117/1B911058",
            },
        [11011709] = {
            ["Content"] = "我……只是想听听你们的声音。我没事，你们还好吗？",
            ["ContentFR"] = "Je... je voulais juste entendre ta voix. Je vais bien. Et toi ?",
            ["DialogueId"] = 11011709,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B911082",
            ["NextDialogue"] = 11011710,
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110117/1B911082",
            },
        [11011710] = {
            ["Content"] = "“雪狼”的残兵和我们会合了，我们这里暂时还算安稳。你那边呢？",
            ["ContentFR"] = "Les rescapés des Loups Blancs nous ont rejoints. Nous sommes en sécurité pour l’instant. Et vous ?",
            ["DialogueId"] = 11011710,
            ["Duration"] = 3,
            ["GUID"] = "1B9110AC",
            ["NextDialogue"] = 11011711,
            ["SnapShot"] = "TELEPHONE",
            ["SpeakNpcId"] = 110005,
            ["VoiceName"] = "voice/$Locale$/story/1002/110117/1B9110AC",
            },
        [11011711] = {
            ["Content"] = "……我……也很好。我继续执行任务了，再见。",
            ["ContentFR"] = "... Je vais bien aussi. Mais je dois continuer. À plus tard.",
            ["DialogueId"] = 11011711,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B9110D6",
            ["NextDialogue"] = 11011712,
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110117/1B9110D6",
            },
        [11011712] = {
            ["Content"] = "请多保重……我们会在迪斯玛尼亚平安重逢。",
            ["ContentFR"] = "Je vous en prie, soyez prudent... Nous nous retrouverons sains et saufs à Dismania.",
            ["DialogueId"] = 11011712,
            ["Duration"] = 3,
            ["GUID"] = "1B911100",
            ["Scripts"] = "PlayNormalSound{EventPath{\"event:/sfx/common/story/ex01/signal_off\"},PlayAs2D{true}}",
            ["SnapShot"] = "TELEPHONE",
            ["SpeakNpcId"] = 110005,
            ["VoiceName"] = "voice/$Locale$/story/1002/110117/1B911100",
            },
        [11011801] = {
            ["Content"] = "队长！嗨——在这里！",
            ["ContentFR"] = "Capitaine ! Hé ! Par ici !",
            ["DialogueId"] = 11011801,
            ["Duration"] = 3,
            ["GUID"] = "1B911F9A",
            ["SpeakNpcId"] = 110015,
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["VoiceName"] = "voice/$Locale$/story/1002/110118/1B911F9A",
            },
        [11011802] = {
            ["Camera"] = "-485.80957,430.660156,148.512939,0.000044,-2.39937,-69.002335,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "啊，队长，我亲爱的队长！！终于找到你了！！我们的联络频段突然出现异常，这一路谁也联系不上，西蒙就跑出去求救了。",
            ["ContentFR"] = "Ah, capitaine ! Enfin ! Nos communications ont lâché, impossible de joindre qui que ce soit. Simon est parti chercher de l’aide...",
            ["DialogueId"] = 11011802,
            ["FinalCamera"] = "-485.80957,430.660156,123.858765,0.000044,-2.39937,-69.002335,35.000008,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "1B911FC4",
