            ["ToFinalCameraBlendTime"] = 6,
            ["VoiceName"] = "voice/$Locale$/story/1002/110118/1B911FC4",
            },
        [11011803] = {
            ["Content"] = "我刚就一直跟大家鼓劲儿，队长那么厉害心眼儿又好，肯定“唰”的一下就跑过来帮咱们了。",
            ["ContentFR"] = "J’essayais juste de faire en sorte que tout le monde garde son calme. Je leur ai dit combien vous étiez {性别2:compétent|compétente}, et que vous viendriez nous tirer de ce mauvais pas.",
            ["DialogueId"] = 11011803,
            ["GUID"] = "1B911FEE",
