        [11011809] = {
            ["Camera"] = "-656.783203,291.84375,130.419189,0.000108,-4.000244,-31.220165,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "……你说得对……他拼命跑出去求救，可不是为了让我们像废物一样在这里哭。",
            ["ContentFR"] = "Vous avez raison. Simon n’a pas donné sa vie en partant chercher de l’aide pour que nous restions là à pleurer.",
            ["DialogueId"] = 11011809,
            ["GUID"] = "1B9120EA",
            ["NextDialogue"] = 11011810,
            ["SpeakNpcId"] = 110016,
            ["TalkActionId"] = {
                [1] = "110016:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110118/1B9120EA",
            },
        [11011810] = {
            ["Camera"] = "-237.097656,-159.654297,134.053345,0.000085,-4.599852,112.993782,40.0,100000.0,false,DoNotOverride,2.8",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "准备好了就走吧，我中途遇到了阿瓦尔长官。我们计划在4号炮台处会合。",
            ["ContentFR"] = "Préparez-vous à bouger. J’ai croisé le Commandant Avar en chemin, nous devons le rejoindre à la tourelle 4.",
            ["DialogueId"] = 11011810,
            ["ExStoryInfo"] = "EXPlayer",
            ["FinalCamera"] = "-275.418945,-69.328125,129.340332,0.000085,-4.599852,112.993782,40.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "1B912114",
            ["NextDialogue"] = 11011811,
            ["SpeakNpcId"] = 110022,
            ["TalkActionId"] = {
                [1] = "110022:AgreeHead",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1002/110118/1B912114",
            },
        [11011811] = {
            ["Camera"] = "-525.013672,462.529297,124.264893,0.000065,-3.199527,-67.400917,35.000008,100000.0,false,DoNotOverride,2.8",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "4号炮台？队长你确定吗？离这里还挺远的，路上不知道有多少秽兽。就咱几个，能行吗？",
            ["ContentFR"] = "La tourelle 4 ? Capitaine, vous êtes {性别2:sûr|sûre} ? Avec toutes ces hordes de Souillés en chemin... à si peu, on n’y arrivera jamais.",
            ["DialogueId"] = 11011811,
            ["FinalCamera"] = "-571.740234,443.087891,124.264893,0.000065,-3.199527,-67.400917,35.000008,100000.0,false,DoNotOverride,2.8",
