            },
        [11011824] = {
            ["Camera"] = "-474.881836,186.248047,147.918213,0.00014,-7.60077,-47.196186,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "开什么玩笑——同盟对自己的同胞下手？",
            ["ContentFR"] = "Quoi ?! Les Déchus réduisent leur propre peuple en esclavage ?",
            ["DialogueId"] = 11011824,
            ["GUID"] = "1B912360",
            ["NextDialogue"] = 11018401,
            ["SpeakNpcId"] = 110016,
