        [11011839] = {
            ["Camera"] = "-331.882812,3.074219,121.966187,0.000118,-1.199463,-90.33371,35.000019,244.838531,false,Manual,2.8",
            ["Content"] = "老人家，既然你对水道熟悉，那来带路吧。",
            ["ContentFR"] = "Vieil homme, puisque vous connaissez bien les égouts, montrez-nous le chemin.",
            ["DialogueId"] = 11011839,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B9125D6",
