            },
        [11012410] = {
            ["Content"] = "不用喊了，没有人会理你的。",
            ["ContentFR"] = "<I>Inutile de crier, personne ne t’écoutera.</>",
            ["DialogueId"] = 11012410,
            ["GUID"] = "1B918384",
            ["ImprPlusId"] = 1006,
            ["NextDialogue"] = 11012411,
            },
        [11012411] = {
            ["Camera"] = "54.121704,-48.700684,112.361572,0.000127,17.4041,-101.210175,35.0,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "呜呜呜，这可真是太令人悲伤了，呜呜呜。",
            ["ContentFR"] = "Oh non... Quelle tristesse... Bouhouhou...",
            ["DialogueId"] = 11012411,
