            ["SpeakNpcId"] = 110009,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1002/110124/1B918480",
            },
        [11012417] = {
            ["Content"] = "（给她一拳，让她少说两句。）",
            ["ContentFR"] = "<I>Donner un coup de poing en pleine figure pour la faire taire</>",
            ["DialogueId"] = 11012417,
