            },
        [11012423] = {
            ["Camera"] = "67.383972,-41.145508,109.074097,0.000133,16.40362,124.389236,35.0,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "被你摆了这么一遭，总得告诉我是为什么吧？这是针对海伯利亚士兵的袭击，还是针对我个人的刺杀？",
            ["ContentFR"] = "Après tout ça, j’ai bien droit à une explication. Tu voulais frapper la Légion Hyperboréenne ? Ou bien c’était moi que tu visais ?",
            ["DialogueId"] = 11012423,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["FacialId"] = {
                [1] = "110022:None",
                },
            ["FinalCamera"] = "59.581787,-46.003906,109.074097,0.000143,15.403538,117.789177,35.0,100000.0,false,DoNotOverride,22.0",
            ["GUID"] = "1B9185A6",
            ["NextDialogue"] = 11012424,
