        [11012446] = {
            ["Camera"] = "43.091187,-31.208008,198.673462,-0.002777,-40.807617,-92.394653,15.610328,100000.0,false,Manual,22.0",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "快猜呀——猜呀猜呀！当然，就算猜出来，我也不会告诉你的！",
            ["ContentFR"] = "Allez, devine encore ! Même si tu tombes juste, je ne te révélerai pas la vérité de toute façon !",
            ["DialogueId"] = 11012446,
            ["Duration"] = 3,
            ["FacialId"] = {
                [1] = "110009:Happy01",
                },
