            },
        [11012447] = {
            ["Camera"] = "17.73999,15.974609,99.406067,-0.00278,-44.606674,-61.595421,15.610328,100000.0,false,Manual,22.0",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "<W>不要再犹豫了！快用你的剑！它在呼唤着你，它在等待着血肉赐予的甜蜜与欢愉！</>",
            ["ContentFR"] = "<W>Ne tergiverse plus ! Ton épée t’appelle ! Elle réclame la douce ivresse que seule la chair et le sang peuvent lui offrir.</>",
            ["DialogueId"] = 11012447,
            ["DisableMouth"] = 1,
            ["Duration"] = 3,
