        [11012451] = {
            ["Camera"] = "-203.119934,-210.255371,286.285492,-0.002775,-34.405323,36.012363,15.610331,100000.0,false,DoNotOverride,22.0",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "闭嘴！！别再说了！！",
