            ["TurnTo"] = {
                [1] = "110015:n(110022)",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110124/1B918A68",
            },
        [11012453] = {
            ["Camera"] = "-362.915283,260.68457,366.26709,-0.002777,-29.005312,-39.177933,15.610332,100000.0,false,Manual,22.0",
            ["Content"] = "……莱昂，看好她。把她完好无损地带回去，别让她自尽。必要的话，用弗兰克的命来威胁。",
            ["ContentFR"] = "... Leon, surveille-la. Ramène-la entière, qu’elle ne s’amuse pas à se donner la mort. Si nécessaire, utilise Frank comme moyen de pression.",
            ["DialogueId"] = 11012453,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["FacialId"] = {
                [1] = "110022:None",
                },
            ["FinalCamera"] = "-362.915283,260.68457,366.26709,-0.002778,-31.005327,-39.777187,15.610332,100000.0,false,Manual,22.0",
            ["GUID"] = "1B918A92",
