        [11012455] = {
            ["Camera"] = "11.781921,-87.581543,154.120667,0.000135,-24.800552,-42.592556,45.0,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "等一下！",
            ["ContentFR"] = "Attends !",
