        [11012702] = {
            ["Camera"] = "-205.521912,-260.586914,112.591187,0.000046,-3.599892,36.394058,45.0,344.311523,false,Manual,6.0",
            ["Content"] = "最终目标中央控制室就在前面了。要继续前进吗？同盟的“信使”大概就在里面……",
            ["ContentFR"] = "La salle de commande centrale est juste devant. On continue ? Le Messager des Déchus y est peut-être...",
            ["DialogueId"] = 11012702,
            ["Duration"] = 3,
            ["FinalCamera"] = "-187.628693,-247.398438,111.409241,0.000046,-3.599892,36.394058,45.0,344.311523,false,Manual,6.0",
