        [11012703] = {
            ["Camera"] = "-12.380791,280.555664,122.310181,0.000131,-5.199953,-55.185879,35.0,351.159821,false,Manual,8.87682",
            ["Content"] = "而她这样的埋伏，前面不知道还有多少。",
            ["ContentFR"] = "Je ne sais pas combien d’assassins comme elle nous attendent encore.",
            ["DialogueId"] = 11012703,
            ["Duration"] = 3,
            ["FinalCamera"] = "-12.380791,280.555664,122.310181,0.000131,-3.199909,-54.185669,35.0,1881.420654,false,Manual,8.87682",
