}}\
",
            ["SpeakNpcId"] = 110010,
            ["TalkActionId"] = {
                [1] = "110010:Think_End",
                [2] = "110022:Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110127/1B91B414",
            },
        [11012707] = {
