                [1] = "110010:Awa_Story_Operate01_Loop",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110134/1B922644",
            },
        [11013403] = {
            ["Camera"] = "-1366.088501,-4102.904297,1084.964233,0.000416,-10.394857,69.806015,30.172316,215.162598,false,DoNotOverride,2.8",
            ["Content"] = "尊敬的阿瓦尔·赫德兰中校，下午好！海伯利亚军团箴言第十六条：当敌人在你的射程内，别忘了你也在敌人的射程内。",
            ["ContentFR"] = "Bonjour, lieutenant-colonel Avar Hrodland ! Précepte n° 16 de la Légion Hyperboréenne : Quand l’ennemi est à portée de ton arme, n’oublie pas que tu es aussi à portée de la sienne.",
            ["DialogueId"] = 11013403,
            ["Duration"] = 1,
            ["FinalCamera"] = "-1366.088501,-4102.904297,1026.309692,0.000416,-10.394857,69.806015,30.172316,215.162598,false,DoNotOverride,2.8",
            ["GUID"] = "1B92266E",
            ["NextDialogue"] = 11013404,
            ["SnapShot"] = "ELECTRIC",
            ["SpeakNpcName"] = "UI_Npc_MechVoice",
            ["ToFinalCameraBlendTime"] = 20,
            ["VoiceName"] = "voice/$Locale$/story/1002/110134/1B92266E",
            },
        [11013404] = {
            ["Camera"] = "-991.410645,-3133.832031,853.562988,0.000037,12.600312,-63.598225,37.326954,211.74176,false,Manual,22.0",
            ["Content"] = "……搞定了。",
            ["ContentFR"] = "Enfin... c’est fait.",
            ["DialogueId"] = 11013404,
            ["Duration"] = 1,
            ["FacialId"] = {
                [1] = "110010:Confident01",
                },
            ["FinalCamera"] = "-978.536255,-3159.746094,858.094727,0.000037,12.600312,-63.598225,37.326958,168.678696,false,Manual,22.0",
            ["GUID"] = "1B922698",
            ["NextDialogue"] = 11013405,
            ["SpeakNpcId"] = 110010,
            ["TalkActionId"] = {
                [1] = "110010:AgreeHead",
                },
            ["ToFinalCameraBlendTime"] = 20,
            ["VoiceName"] = "voice/$Locale$/story/1002/110134/1B922698",
            },
        [11013405] = {
            ["Content"] = "嗨，打了半辈子仗了，头一次这么汗流浃背的！哈哈，我还担心再也见不到达芙涅和克劳迪娅了。",
            ["ContentFR"] = "Ouf... J’ai mené des batailles toute ma vie, mais jamais je n’avais été aussi nerveux ! Haha... J’ai bien cru que je ne reverrais plus jamais Daphne ni Claudia.",
            ["DialogueId"] = 11013405,
            ["Duration"] = 1,
            ["GUID"] = "1B9226C2",
            ["NextDialogue"] = 11013406,
            ["Scripts"] = "PlayAnimation{_delay{4},ActorId{110010},AnimationId{\"Talk03_Start\"},Duration{3}}",
