        [11013602] = {
            ["Camera"] = "167.782227,328.865234,78.688873,-5.000004,0.40139,-85.618973,15.0,570.333496,false,DoNotOverride,20.0",
            ["Content"] = "这些伪证都是你搞出来的吧？我还以为你们这些元老院贵族不会染指这种下三滥的招数，看来是我看走眼了。",
            ["ContentFR"] = "Tous ces faux documents, c’est ton œuvre, n’est-ce pas ? J’avais cru que vous autres aristocrates du Sénat ne vous abaisseriez pas à de telles manigances. Visiblement, je m’étais trompé.",
            ["DialogueId"] = 11013602,
            ["Duration"] = 3,
            ["FacialId"] = {
                [1] = "110022:Close",
                },
            ["FinalCamera"] = "157.87233,328.103516,77.819336,-5.000004,0.40139,-85.618973,15.0,570.333496,false,DoNotOverride,20.0",
            ["GUID"] = "1B924714",
