                [1] = "110022:Die",
                },
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/1002/110136/1B924714",
            },
        [11013603] = {
            ["Camera"] = "132.141647,116.539062,60.872101,-15.005561,5.400951,-79.810699,35.000011,570.333496,false,DoNotOverride,20.0",
            ["Content"] = "我和那些老顽固不一样，对实用主义者来说，办法能用就行。",
            ["ContentFR"] = "Je ne suis pas comme ces vieux fossiles. Pour un pragmatique comme moi, peu importe le moyen, du moment qu’il fonctionne.",
