        [11013625] = {
            ["Camera"] = "-62.074799,-566.730469,491.808014,-0.001556,-31.999592,75.647636,16.661533,100000.0,false,Manual,22.0",
            ["Content"] = "我们来谈谈另一件事吧……<H>“零号”</>。",
            ["ContentFR"] = "Parlons d’autre chose... <H>n° 0</>.",
            ["DialogueId"] = 11013625,
            ["Duration"] = 3,
            ["FacialId"] = {
                [1] = "110011:None",
                },
            ["GUID"] = "1B924AB0",
