            ["Scripts"] = "CameraMoveTo{_delay{2},TargetPosition{\"175.50206,126.912109,133.876068,-0.001556,-18.199461,67.248505,40.000011,100000.0,false,DoNotOverride,22.0\"},duration{0}}",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110136/1B924AB0",
            },
        [11013626] = {
            ["Camera"] = "151.601776,151.322266,102.676727,-0.001556,-4.801548,-108.713249,23.660721,100000.0,false,Manual,22.0",
            ["Content"] = "……嗯？",
            ["ContentFR"] = "... Oh ?",
            ["DialogueId"] = 11013626,
            ["Duration"] = 3,
            ["GUID"] = "1B924ADA",
            ["NextDialogue"] = 11013627,
            ["Scripts"] = "TurnTo{_delay{2},TurnToDescription{\"110011:p(180)\"}}",
            ["SpeakNpcId"] = 110011,
            ["VoiceName"] = "voice/$Locale$/story/1002/110136/1B924ADA",
            },
        [11013627] = {
            ["Camera"] = "63.279358,-238.914062,88.206848,-0.002014,-2.614016,77.062973,23.660721,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "她是十三军团最宝贝的兵刃。如今西比尔虽然得到了她，但想要完成<H>“第二新枝”计划</>，还少了最关键的<H>“触媒”</>……",
            ["ContentFR"] = "Elle est l’arme la plus précieuse de la XIIIᵉ Légion. Sibylle la détient, certes. Mais pour mener à bien le <H>Projet Nouvel Héritier</>, il manque encore l’élément essentiel : le <H>\"Catalyseur\"</>.",
            ["DialogueId"] = 11013627,
            ["Duration"] = 3,
            ["FinalCamera"] = "-60.852264,-120.474609,97.3927,-0.002014,-5.013919,43.262783,23.660721,100000.0,false,DoNotOverride,22.0",
            ["GUID"] = "1B924B04",
            ["NextDialogue"] = 11013628,
            ["RelatedWikiId"] = {
                [1] = 403003,
                },
            ["SpeakNpcId"] = 110010,
            ["ToFinalCameraBlendTime"] = 15,
            ["VoiceName"] = "voice/$Locale$/story/1002/110136/1B924B04",
            },
        [11013628] = {
            ["Camera"] = "155.250778,120.773438,83.251434,10.002668,12.003586,50.623306,21.125479,95.12989,false,Manual,2.8",
            ["Content"] = "西比尔命你在弗莱格桑省搜寻“触媒”，但好像过程不怎么顺利啊。",
            ["ContentFR"] = "Sibylle t’a envoyé chercher le Catalyseur à Flagson, mais il me semble que tes recherches n’ont pas été très fructueuses.",
            ["DialogueId"] = 11013628,
            ["Duration"] = 3,
            ["FinalCamera"] = "159.07251,125.427734,84.532227,10.002668,12.003586,50.623306,21.125483,89.517586,false,Manual,2.8",
            ["GUID"] = "1B924B2E",
            ["NextDialogue"] = 11013629,
            ["SpeakNpcId"] = 110010,
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/1002/110136/1B924B2E",
            },
        [11013629] = {
            ["Camera"] = "99.726173,78.669922,83.391571,-10.008635,12.003312,-82.168861,21.125483,99.930809,false,Manual,2.8",
            ["Content"] = "你想说什么？别绕弯子。",
            ["ContentFR"] = "Qu’est-ce que tu essaies de dire ? Va droit au but.",
            ["DialogueId"] = 11013629,
            ["Duration"] = 3,
            ["FinalCamera"] = "100.516411,72.925781,84.624756,-10.008635,12.003312,-82.168861,21.125483,99.930809,false,Manual,2.8",
            ["GUID"] = "1B924B58",
            ["NextDialogue"] = 11013630,
            ["SpeakNpcId"] = 110011,
            ["TalkActionId"] = {
                [1] = "110011:Talk03_Start",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/story/1002/110136/1B924B58",
            },
        [11013630] = {
            ["Camera"] = "-540.700623,825.572266,22.562286,-5.000006,2.003171,-46.767361,40.000023,271.651154,false,DoNotOverride,10.0",
            ["Content"] = "富尔维斯，成为军团长的道路不止一条。就算你真靠演这一出赶走西比尔，你能保证陛下就一定会任命你接替她吗？",
            ["ContentFR"] = "Fulvis, il existe plus d’un chemin vers le commandement. Même si ton petit numéro parvient à écarter Sibylle, qui te dit que l’Empereur te choisira pour la remplacer ?",
            ["DialogueId"] = 11013630,
            ["Duration"] = 3,
            ["FinalCamera"] = "-522.103577,843.160156,24.800446,-5.000006,2.003171,-46.767361,40.000023,271.651154,false,DoNotOverride,10.0",
            ["GUID"] = "1B924B82",
            ["NextDialogue"] = 11013631,
            ["Scripts"] = "PlayAnimation{_delay{6},ActorId{110010},AnimationId{\"Talk01_End\"},Duration{0}}",
            ["SpeakNpcId"] = 110010,
            ["TalkActionId"] = {
                [1] = "110010:Talk01_Start",
                },
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/1002/110136/1B924B82",
            },
        [11013631] = {
            ["Camera"] = "188.38916,374.509766,107.291229,-10.011471,-3.196467,-95.968758,40.000011,271.651154,false,DoNotOverride,13.0",
            ["Content"] = "真正能推你到那个位子的，是一份无可替代的“功劳”。",
            ["ContentFR"] = "Ce qu’il te faut, c’est un mérite unique, inégalable.",
            ["DialogueId"] = 11013631,
            ["Duration"] = 3,
            ["FinalCamera"] = "186.448547,355.947266,106.248871,-10.011503,-3.196467,-95.968758,40.000011,271.651154,false,DoNotOverride,13.0",
            ["GUID"] = "1B924BAC",
            ["NextDialogue"] = 11013632,
            ["SpeakNpcId"] = 110010,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/story/1002/110136/1B924BAC",
            },
        [11013632] = {
            ["Camera"] = "96.940521,78.816406,89.251038,-10.007017,12.402838,-85.163452,40.000023,271.651154,false,DoNotOverride,10.0",
            ["Content"] = "继续。",
            ["ContentFR"] = "Continue.",
            ["DialogueId"] = 11013632,
            ["Duration"] = 3,
            ["GUID"] = "1B924BD6",
            ["NextDialogue"] = 11013633,
            ["SpeakNpcId"] = 110011,
            ["VoiceName"] = "voice/$Locale$/story/1002/110136/1B924BD6",
            },
        [11013633] = {
            ["Camera"] = "-2118.515137,-306.582031,571.609009,0.00001,-10.997062,16.436613,40.0,271.651154,false,DoNotOverride,10.0",
            ["Content"] = "“第二新枝”计划对帝国来说太重要了，胜过一百个龙莎要塞。如果你找到“触媒”，完成计划的最后一块拼图，那时整个皇都都会高呼你的名字——安东尼·富尔维斯。",
            ["ContentFR"] = "Le Projet Nouvel Héritier est vital pour l’Empire. Il vaut bien plus qu’une centaine de forteresses de Lonza. Si tu trouves le Catalyseur, la dernière pièce du puzzle, la capitale tout entière scandera ton nom, Antonius Fulvis.",
            ["DialogueId"] = 11013633,
            ["Duration"] = 3,
            ["FinalCamera"] = "-2147.418945,-208.613281,571.609009,0.00001,-10.997062,16.436708,40.0,271.651154,false,DoNotOverride,10.0",
            ["GUID"] = "1B924C00",
            ["NextDialogue"] = 11013634,
            ["SpeakNpcId"] = 110010,
            ["ToFinalCameraBlendTime"] = 12,
            ["VoiceName"] = "voice/$Locale$/story/1002/110136/1B924C00",
            },
        [11013634] = {
            ["Camera"] = "206.033554,354.041016,73.645569,0.000024,1.20283,-101.165855,40.0,271.651154,false,DoNotOverride,10.0",
            ["Content"] = "这对你来说正是无可替代的功劳。而我之前碰巧在机缘巧合之下，知道了它的下落。现在，我愿意将这份功劳让给你。",
            ["ContentFR"] = "Voilà l’exploit qui te propulsera au sommet. Et, par un heureux hasard, j’en connais l’emplacement. Aujourd’hui, je suis prêt à te le céder.",
            ["DialogueId"] = 11013634,
            ["Duration"] = 3,
            ["FinalCamera"] = "201.324173,330.189453,74.156342,0.000024,1.20283,-101.165855,40.0,271.651154,false,DoNotOverride,10.0",
            ["GUID"] = "1B924C2A",
            ["NextDialogue"] = 11013635,
            ["Scripts"] = "SEQ{\
CameraMoveTo{_delay{8},TargetPosition{\"-29.667725,-114.439453,111.371826,0.000021,-2.396822,48.637676,60.0,271.651154,false,DoNotOverride,10.0\"},duration{0}},CameraMoveTo{TargetPosition{\"-10.139755,-92.255859,109.041138,0.000021,-2.396822,48.637676,60.0,271.651154,false,DoNotOverride,10.0\"},duration{8}}\
}",
            ["SpeakNpcId"] = 110010,
            ["TalkActionId"] = {
                [1] = "110011:Talk03_End",
                },
            ["ToFinalCameraBlendTime"] = 20,
            ["VoiceName"] = "voice/$Locale$/story/1002/110136/1B924C2A",
            },
        [11013635] = {
            ["Camera"] = "85.258636,144.519531,44.719849,0.000028,19.801844,-82.964874,40.000027,271.651154,false,DoNotOverride,10.0",
            ["Content"] = "这倒是有点意思。",
            ["ContentFR"] = "Là, tu commences à m’intéresser.",
            ["DialogueId"] = 11013635,
            ["Duration"] = 3,
            ["FinalCamera"] = "86.617958,133.511719,48.716034,0.000028,19.801844,-82.964874,40.000027,271.651154,false,DoNotOverride,10.0",
            ["GUID"] = "1B924C54",
            ["NextDialogue"] = 11013636,
            ["SpeakNpcId"] = 110011,
            ["TalkActionId"] = {
                [1] = "110011:Think_Start",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/story/1002/110136/1B924C54",
            },
        [11013636] = {
            ["Camera"] = "99.722374,88.037109,96.940674,0.000021,2.40286,43.238102,40.0,271.651154,false,DoNotOverride,10.0",
            ["Content"] = "这便是我的“交易”。我需要你的承诺——放我和外面那些先遣小队的士兵一条生路。",
            ["ContentFR"] = "C’est ma proposition. En échange, je veux ta promesse : épargne-moi, ainsi que mes soldats.",
            ["DialogueId"] = 11013636,
            ["Duration"] = 3,
            ["GUID"] = "1B924C7E",
            ["NextDialogue"] = 11013637,
            ["Scripts"] = "SEQ{\
CameraMoveTo{_delay{8},TargetPosition{\"150.76915,147.746094,105.232941,0.000021,2.40286,43.238102,40.0,271.651154,false,DoNotOverride,10.0\"},duration{0}},CameraMoveTo{TargetPosition{\"157.346924,153.925781,105.611877,0.000021,2.40286,43.238102,40.0,271.651154,false,DoNotOverride,10.0\"},duration{8}}\
}",
            ["SpeakNpcId"] = 110010,
            ["TalkActionId"] = {
                [1] = "110011:Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110136/1B924C7E",
            },
        [11013637] = {
            ["Camera"] = "116.448387,93.667969,95.850342,0.000025,5.602879,-99.561935,40.0,271.651154,false,DoNotOverride,10.0",
            ["Content"] = "真是大家的好长官！好吧，就在此地、此刻，告诉我“触媒”的下落，别耍任何花招，你没有谈判的条件。",
            ["ContentFR"] = "Quel brave commandant, toujours soucieux de ses hommes ! Très bien. Alors, dis-moi ici et maintenant où se trouve le Catalyseur. Pas de ruse, pas de délai. Tu n’as aucun moyen de négocier.",
            ["DialogueId"] = 11013637,
            ["Duration"] = 3,
            ["GUID"] = "1B924CA8",
            ["NextDialogue"] = 11013638,
            ["Scripts"] = "SEQ{\
CameraMoveTo{_delay{5},TargetPosition{\"-608.948547,3198.607422,754.886475,0.000048,-12.996736,-70.159851,40.0,271.651154,false,DoNotOverride,10.0\"},duration{0}},CameraMoveTo{TargetPosition{\"-547.46936,3220.791016,754.886475,0.000048,-12.996736,-70.159851,40.0,271.651154,false,DoNotOverride,10.0\"},duration{8}}\
}",
            ["SpeakNpcId"] = 110011,
            ["TalkActionId"] = {
                [1] = "110011:Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110136/1B924CA8",
            },
        [11013638] = {
            ["Camera"] = "56.335129,-55.574219,108.552826,0.000057,-1.196704,55.040733,60.0,271.651154,false,Manual,20.0",
            ["Content"] = "好吧。它就在……",
            ["ContentFR"] = "D’accord. Il est...",
            ["DialogueId"] = 11013638,
            ["Duration"] = 3,
            ["FinalCamera"] = "61.549301,-48.115234,108.362793,0.000057,-1.196704,55.040733,60.0,271.651154,false,Manual,20.0",
            ["GUID"] = "1B924CD2",
            ["NextDialogue"] = 11013639,
            ["SpeakNpcId"] = 110010,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/story/1002/110136/1B924CD2",
            },
        [11013639] = {
            ["Camera"] = "116.628403,103.859375,152.601593,0.000028,-21.397213,-99.75634,60.000019,271.651154,false,DoNotOverride,20.0",
            ["Content"] = "嗯，我知道了。接下来，只要……",
            ["ContentFR"] = "Hmm. Je vois. Et maintenant, il ne me reste plus qu’une dernière chose à faire...",
            ["DialogueId"] = 11013639,
            ["Duration"] = 3,
            ["FinalCamera"] = "114.449196,91.181641,147.562653,0.000028,-21.397213,-99.75634,60.000019,271.651154,false,DoNotOverride,20.0",
            ["GUID"] = "1B924CFC",
            ["SpeakNpcId"] = 110011,
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/1002/110136/1B924CFC",
            },
        [11013640] = {
            ["DialogueId"] = 11013640,
            ["DialoguePanelType"] = "None",
            ["Duration"] = 6,
            ["GUID"] = "1B924811",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 11013609,
            },
        [11013701] = {
            ["Content"] = "阿瓦尔，别太信任一个实用主义者。",
            ["ContentFR"] = "Souviens-toi, Avar, on ne fait jamais confiance à un pragmatique.",
            ["DialogueId"] = 11013701,
            ["Duration"] = 3,
            ["GUID"] = "1B925752",
            ["SpeakNpcId"] = 110011,
            ["VoiceName"] = "voice/$Locale$/story/1002/110137/1B925752",
            },
        [11013702] = {
            ["Content"] = "法露茜，你留下，处理干净。",
            ["ContentFR"] = "Falsi, tu restes. Nettoie-moi ça.",
            ["DialogueId"] = 11013702,
            ["Duration"] = 3,
            ["GUID"] = "1B92577C",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 11013703,
            ["SpeakNpcId"] = 110011,
            ["VoiceName"] = "voice/$Locale$/story/1002/110137/1B92577C",
            },
        [11013703] = {
            ["Content"] = "是。",
            ["ContentFR"] = "À vos ordres.",
            ["DialogueId"] = 11013703,
            ["Duration"] = 3,
            ["GUID"] = "1B9257A6",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 11019301,
            ["SpeakNpcId"] = 110012,
            ["VoiceName"] = "voice/$Locale$/story/1002/110137/1B9257A6",
            },
        [11013705] = {
            ["Content"] = "……小型录音设备……{性别2：他|她}还带了这个？",
            ["ContentFR"] = "... Un micro-enregistreur ? {性别2:Il|Elle} avait ça sur {性别2:lui|elle} ?",
            ["DialogueId"] = 11013705,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B9257FA",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 11013706,
            ["Scripts"] = "StopNormalSound{EventPath{\"event:/sfx/common/story/ex01/searchcloth\"},PlayAs2D{true}}",
            ["SpeakNpcId"] = 110012,
