}}",
            ["SnapShot"] = "MONSTER",
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["VoiceName"] = "voice/$Locale$/story/1002/110138/1B9267BA",
            },
        [11013802] = {
