}}",
            ["SnapShot"] = "MONSTER",
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["VoiceName"] = "voice/$Locale$/story/1002/110138/1B92680E",
            },
        [11013901] = {
