        [11014305] = {
            ["Camera"] = "188.189941,22.199753,132.788391,0.000101,5.599874,20.424314,50.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "要小心这里的士兵。这里很可能已经没有“战友”，只有“敌人”了。",
            ["ContentFR"] = "Faites attention aux soldats. Ici, il n’y a sans doute plus de \"camarades\"... seulement des \"ennemis\".",
            ["DialogueId"] = 11014305,
            ["Duration"] = 3,
            ["GUID"] = "1B92BA6A",
            ["LookAt"] = {
                [1] = "110005:n(110022)",
                },
            ["Scripts"] = "PARA{\
SEQ{\
CameraMoveTo{_delay{2},TargetPosition{\"264.104858,4.391851,125.635437,0.000112,7.79972,139.222382,50.0,100000.0,false,DoNotOverride,2.8\"},duration{0}},CameraMoveTo{TargetPosition{\"249.126114,17.308903,128.344788,0.000113,7.79972,139.222321,50.000008,100000.0,false,DoNotOverride,2.8\"},duration{8}}\
},PlayAnimation{_delay{5},ActorId{110022},AnimationId{\"AgreeHead\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 110005,
            ["VoiceName"] = "voice/$Locale$/story/1002/110143/1B92BA6A",
            },
        [11014306] = {
            ["Content"] = "警告，无通行权限，无通行权限。",
            ["ContentFR"] = "Avertissement. Accès refusé. Accès refusé.",
            ["DialogueId"] = 11014306,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "ELECTRIC",
            ["GUID"] = "1B92BA94",
            ["NextDialogue"] = 11014307,
            ["SpeakNpcName"] = "UI_Npc_MechVoice",
            ["VoiceName"] = "voice/$Locale$/story/1002/110143/1B92BA94",
            },
        [11014307] = {
            ["Content"] = "……他们这么快就删除了我们的权限……",
            ["ContentFR"] = "... Ils ont déjà supprimé nos autorisations...",
            ["DialogueId"] = 11014307,
            ["Duration"] = 3,
            ["GUID"] = "1B92BABE",
            ["NextDialogue"] = 11014308,
            ["SpeakNpcId"] = 110005,
            ["VoiceName"] = "voice/$Locale$/story/1002/110143/1B92BABE",
            },
        [11014308] = {
            ["Content"] = "发现目标了！在这里！",
            ["ContentFR"] = "Cibles repérées ! Par ici !",
            ["DialogueId"] = 11014308,
            ["Duration"] = 3,
            ["GUID"] = "1B92BAE8",
            ["NextDialogue"] = 11014309,
            ["SpeakNpcName"] = "UI_Npc_WhaleSoldier",
            ["VoiceName"] = "voice/$Locale$/story/1002/110143/1B92BAE8",
            },
        [11014309] = {
            ["Content"] = "…………",
            ["ContentFR"] = "...",
            ["DialogueId"] = 11014309,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B92BB12",
            ["NextDialogue"] = 11014310,
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110143/1B92BB12",
            },
        [11014310] = {
            ["Content"] = "打晕他们，用他们的秘钥开门。",
            ["ContentFR"] = "Assommons-les. On prendra leur clé d’accès.",
            ["DialogueId"] = 11014310,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B92BB3C",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110143/1B92BB3C",
            },
        [11014401] = {
            ["Camera"] = "-289.811768,-1059.867188,474.80188,0.000159,-16.39455,82.10141,35.000011,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "哈、哈、哈……",
            ["ContentFR"] = "Haa... haa... haa...",
            ["DialogueId"] = 11014401,
            ["Duration"] = 2,
            ["FacialId"] = {
                [1] = "110005:Pain01",
                },
            ["FinalCamera"] = "-289.811768,-1059.867188,408.181274,0.000159,-16.39455,82.10141,35.000011,100000.0,false,DoNotOverride,22.0",
            ["GUID"] = "1B92CA2A",
