            ["VoiceName"] = "voice/$Locale$/story/1002/110144/1B92CA2A",
            },
        [11014402] = {
            ["Camera"] = "37.388428,234.120605,23.369995,-9.010153,3.999574,178.72345,13.358559,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "说实在的，我……我现在脑袋很乱，很乱。",
            ["ContentFR"] = "Pour être honnête... ma tête est complètement embrouillée. Tout est confus.",
            ["DialogueId"] = 11014402,
            ["FacialId"] = {
                [1] = "110005:Sad01",
                },
            ["FinalCamera"] = "27.15918,234.347656,24.085571,-9.010153,3.999574,178.72345,13.358559,100000.0,false,DoNotOverride,22.0",
            ["GUID"] = "1B92CA54",
            ["NextDialogue"] = 11014403,
            ["Scripts"] = "SEQ{PlayAnimation{ActorId{110005},AnimationId{\"Sigh_End\"},Duration{2}},PlayAnimation{ActorId{110005},AnimationId{\"DisagreeHead\"},Duration{1}}}",
            ["SpeakNpcId"] = 110005,
            ["ToFinalCameraBlendTime"] = 15,
            ["VoiceName"] = "voice/$Locale$/story/1002/110144/1B92CA54",
            },
        [11014403] = {
            ["Camera"] = "3.711914,201.639648,77.724976,0.000011,-22.200401,-176.477524,38.709583,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "他死了，父……阿瓦尔长官。死了。外边的士兵，海伯利亚的士兵，要杀掉我。他们说，我是间谍。我不知道……我不知道……",
            ["ContentFR"] = "Il est mort... mon p... le Commandant Avar est... mort. Les soldats dehors... les soldats hyperboréens... ils veulent me tuer. Ils disent que je suis une espionne. Je... je ne comprends pas... je ne comprends rien...",
            ["DialogueId"] = 11014403,
            ["Duration"] = 1,
            ["FacialId"] = {
                [1] = "110005:Sad01",
                },
            ["FinalCamera"] = "3.711914,201.639648,88.750854,0.000011,-22.200401,-176.477524,38.709583,100000.0,false,DoNotOverride,22.0",
            ["GUID"] = "1B92CA7E",
            ["NextDialogue"] = 11014404,
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{110005},AnimationId{\"Sigh_Start\"},Duration{2}},\
PlayAnimation{_delay{1},ActorId{110005},AnimationId{\"DisagreeHead\"},Duration{1}},\
PlayAnimation{ActorId{110005},AnimationId{\"Sigh_End\"},Duration{2}},\
LookAt{LookAtDescription{\"110005:p(P11014403)\"}},\
PlayAnimation{ActorId{110005},AnimationId{\"Explain02_Start\"},Duration{2}},\
PlayAnimation{_delay{8},ActorId{110005},AnimationId{\"DisagreeHead\"},Duration{1}},\
LookAt{_delay{1},LookAtDescription{\"110005:n(110022)\"}}\
}",
            ["SpeakNpcId"] = 110005,
            ["TalkActionId"] = {
                [1] = "110005:DisagreeHead",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1002/110144/1B92CA7E",
            },
        [11014404] = {
            ["Camera"] = "-88.27002,103.208984,34.547974,0.000074,-7.599576,87.918869,13.462664,136.822205,false,Manual,22.0",
            ["Content"] = "我请求您……请求您告诉我……我可以信任您……只要您这么说，我就会相信。",
            ["ContentFR"] = "Je vous en supplie... dites-moi que je peux vous faire confiance... Si vous le dites, je vous croirai.",
            ["DialogueId"] = 11014404,
            ["GUID"] = "1B92CAA8",
            ["NextOptions"] = {
                [1] = 11014405,
                [2] = 11014406,
                },
            ["Scripts"] = "SEQ{PlayAnimation{_delay{1},ActorId{110005},AnimationId{\"Explain02_End\"},Duration{1}},CameraMoveTo{_delay{3},TargetPosition{\"5.080566,190.669922,1.12085,3.600006,16.199665,176.318161,35.000008,128.714386,false,Manual,22.0\"},duration{0}}}",
            ["SpeakNpcId"] = 110005,
            ["VoiceName"] = "voice/$Locale$/story/1002/110144/1B92CAA8",
            },
        [11014405] = {
            ["Content"] = "（轻轻拥抱她。告诉她可以信任你。）",
            ["ContentFR"] = "<I>Faire un câlin doucement et lui montrer qu’elle peut te faire confiance</>",
            ["DialogueId"] = 11014405,
            ["GUID"] = "1B92CAD2",
            ["ImprPlusId"] = 1009,
            ["NextDialogue"] = 110144071,
            },
        [11014406] = {
            ["Content"] = "（她太依赖自己了——让她靠自己的力量坚强起来。）",
            ["ContentFR"] = "<I>Dire qu’elle doit être forte et se relever par ses propres moyens</>",
            ["DialogueId"] = 11014406,
            ["GUID"] = "1B92CAFC",
            ["ImprPlusId"] = 1006,
            ["NextDialogue"] = 11014407,
            },
        [11014407] = {
            ["Camera"] = "24.679199,230.498535,34.460815,0.000049,-0.400242,-167.066864,35.000011,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "…………",
            ["ContentFR"] = "...",
            ["DialogueId"] = 11014407,
            ["FacialId"] = {
                [1] = "110005:Pain01",
                },
            ["GUID"] = "1B92CB26",
            ["LookAt"] = {
                [1] = "110005:p(P11014402)",
                },
            ["NextDialogue"] = 11014408,
            ["Scripts"] = "PARA{\
PlayAnimation{ActorId{110005},AnimationId{\"Explain02_Start\"},Duration{2}},\
SetLocation{ActorId{110022},TargetPoint{\"nanzhu_hugset2\"},Visibility{\"Show\"}}\
}",
            ["SpeakNpcId"] = 110005,
            ["VoiceName"] = "voice/$Locale$/story/1002/110144/1B92CB26",
            },
        [11014408] = {
            ["Camera"] = "366.595215,-356.056641,24.533936,0.00005,-2.200284,127.312248,35.000011,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "我、我冷静下来了。抱歉，明明是您受了这么重的伤……",
            ["ContentFR"] = "Je... je me suis calmée. Désolée, vous êtes si gravement {性别2:blessé|blessée}... et c’est moi qui fonds en larmes...",
            ["DialogueId"] = 11014408,
            ["FacialId"] = {
                [1] = "110005:None",
                },
            ["GUID"] = "1B92CB50",
            ["LookAt"] = {
                [1] = "110005:n(110022)",
                },
            ["NextDialogue"] = 11014409,
            ["Scripts"] = "PlayAnimation{_delay{2},ActorId{110005},AnimationId{\"AgreeHead\"},Duration{2}}",
            ["SpeakNpcId"] = 110005,
            ["TalkActionId"] = {
                [1] = "110005:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110144/1B92CB50",
            },
        [11014409] = {
            ["Camera"] = "124.651611,286.081543,35.425293,0.000024,-1.799925,-163.283066,35.000011,498.109375,false,Manual,22.0",
            ["Content"] = "之前您帮我找的药剂还留有一些。我来为您紧急处理一下伤口。",
            ["ContentFR"] = "Il reste encore un peu des médicaments que vous m’aviez donnés. Je vais vous aider à soigner vos blessures.",
            ["DialogueId"] = 11014409,
            ["FacialId"] = {
                [1] = "110005:Smile01",
                },
            ["GUID"] = "1B92CB7A",
            ["NextDialogue"] = 11014410,
            ["SpeakNpcId"] = 110005,
            ["TalkActionId"] = {
                [1] = "110005:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110144/1B92CB7A",
            },
        [11014410] = {
            ["Content"] = "先不要走，药剂生效还需要些时间……我先告诉您外面发生的事吧。",
            ["ContentFR"] = "Ne bougez pas, le médicament doit agir... je vais vous raconter ce qui s’est passé dehors.",
            ["DialogueId"] = 11014410,
            ["FacialId"] = {
                [1] = "110005:None",
                },
            ["GUID"] = "1B92CBA4",
            ["NextDialogue"] = 11014411,
            ["SpeakNpcId"] = 110005,
            ["TalkActionId"] = {
                [1] = "110005:Explain01_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110144/1B92CBA4",
            },
        [11014411] = {
            ["Content"] = "没处理干净？漏了一个？",
            ["ContentFR"] = "Pas complètement nettoyé ? Il en reste un ?",
            ["DialogueId"] = 11014411,
            ["GUID"] = "1B92CBCE",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11014413.T_Story_Recall_11014413'",
            ["NextDialogue"] = 11014412,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 110012,
            ["TalkActionId"] = {
                [1] = "110005:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110144/1B92CBCE",
            },
        [11014412] = {
            ["Content"] = "是，一名女性医务员，达芙涅·塞奥多尔。先遣小队的伤兵不要命地拖延时间，让她跑了。",
            ["ContentFR"] = "Oui, une femme, l’infirmière Daphne Theodore. Les blessés du détachement ont retardé le combat, elle a pu s’échapper.",
            ["DialogueId"] = 11014412,
            ["GUID"] = "1B92CBF8",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11014413.T_Story_Recall_11014413'",
            ["NextDialogue"] = 11014413,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcName"] = "UI_Npc_EnemySoldier",
            ["VoiceName"] = "voice/$Locale$/story/1002/110144/1B92CBF8",
            },
        [11014413] = {
            ["Content"] = "现在“一角鲸”分队已经开始陆续进入要塞，但清理先遣小队的事不能让我们之外的人知道。一旦达芙涅向他们求助，事情就难办了。",
            ["ContentFR"] = "Maintenant, les Narvals commencent à entrer dans la forteresse, mais personne d’autre ne doit savoir que nous avons éliminé l’avant-garde. Si Daphne demande de l’aide, la situation se compliquera.",
            ["DialogueId"] = 11014413,
            ["GUID"] = "1B92CC22",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11014411.T_Story_Recall_11014411'",
            ["NextDialogue"] = 11014414,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcName"] = "UI_Npc_EnemySoldier",
            ["VoiceName"] = "voice/$Locale$/story/1002/110144/1B92CC22",
            },
        [11014414] = {
            ["Content"] = "而且，因为战局不顺，西比尔军团长也在赶来龙莎要塞的路上。情况现在有些棘手，不过好在最关键的阿瓦尔已经死了。",
            ["ContentFR"] = "De plus, la situation est délicate : la Commandante Sibylle arrive à la Forteresse de Lonza. Heureusement, le plus important, Avar, est déjà hors-jeu.",
            ["DialogueId"] = 11014414,
            ["GUID"] = "1B92CC4C",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11014411.T_Story_Recall_11014411'",
            ["NextDialogue"] = 11014415,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcName"] = "UI_Npc_EnemySoldier",
            ["VoiceName"] = "voice/$Locale$/story/1002/110144/1B92CC4C",
            },
        [11014415] = {
            ["Content"] = "至于达芙涅这个人，您的意思是……",
            ["ContentFR"] = "Quant à Daphne... vous voulez qu’on fasse quoi exactement ?",
            ["DialogueId"] = 11014415,
            ["Duration"] = 1,
            ["GUID"] = "1B92CC76",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11014411.T_Story_Recall_11014411'",
            ["NextDialogue"] = 11014416,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcName"] = "UI_Npc_EnemySoldier",
            ["VoiceName"] = "voice/$Locale$/story/1002/110144/1B92CC76",
            },
        [11014416] = {
            ["Content"] = "传富尔维斯指挥官的命令下去，要塞全面戒严，搜寻并处决达芙涅·塞奥多尔。理由……一样吧，“勾结神弃者同盟，以间谍身份潜入军团，扰乱要塞进攻计划”。",
            ["ContentFR"] = "Transmettez l’ordre du Commandant Fulvis : verrouillage total de la forteresse, recherche et élimination de Daphne Theodore. Motif : elle a conspiré avec les Déchus, infiltré la Légion comme espionne et compromis le plan d’assaut.",
            ["DialogueId"] = 11014416,
            ["GUID"] = "1B92CCA0",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11014416.T_Story_Recall_11014416'",
            ["NextDialogue"] = 11014417,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 110012,
            ["VoiceName"] = "voice/$Locale$/story/1002/110144/1B92CCA0",
            },
        [11014417] = {
            ["Content"] = "是。",
            ["ContentFR"] = "Reçu.",
            ["DialogueId"] = 11014417,
            ["Duration"] = 1,
            ["GUID"] = "1B92CCCA",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11014416.T_Story_Recall_11014416'",
            ["NextDialogue"] = 11014418,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcName"] = "UI_Npc_EnemySoldier",
            ["VoiceName"] = "voice/$Locale$/story/1002/110144/1B92CCCA",
            },
        [11014418] = {
            ["Camera"] = "21.570557,242.439941,39.389038,0.000078,-1.799837,-165.480621,35.000008,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "……在那之后……",
            ["ContentFR"] = "... Après ça...",
            ["DialogueId"] = 11014418,
            ["Duration"] = 1,
            ["GUID"] = "1B92CCF4",
            ["NextDialogue"] = 11014419,
            ["SpeakNpcId"] = 110005,
            ["VoiceName"] = "voice/$Locale$/story/1002/110144/1B92CCF4",
            },
        [11014419] = {
            ["Camera"] = "-398.801025,-793.505371,51.414673,0.000073,6.400146,-113.874435,35.0,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "我一边一路上确认分队同伴们的状况，一边往中央控制室的方向走。还算幸运——这一路我躲过了所有士兵。",
            ["ContentFR"] = "J’ai vérifié l’état de mes coéquipiers tout en me dirigeant vers la salle de commande centrale. J’ai eu de la chance, j’ai évité tous les soldats.",
            ["DialogueId"] = 11014419,
            ["FinalCamera"] = "-325.535645,-825.931152,51.414673,0.000073,6.400146,-113.870964,35.0,100000.0,false,DoNotOverride,22.0",
            ["GUID"] = "1B92CD1E",
            ["NextDialogue"] = 11014420,
            ["SpeakNpcId"] = 110005,
            ["TalkActionId"] = {
                [1] = "110005:Explain02_Start",
                },
            ["ToFinalCameraBlendTime"] = 20,
            ["VoiceName"] = "voice/$Locale$/story/1002/110144/1B92CD1E",
            },
        [11014420] = {
            ["Camera"] = "182.500244,280.225098,23.764893,0.000076,0.00127,-168.670517,35.000008,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "但无论我怎么救治，同伴们都回不来了。他们身上的伤大多都是一击致命——多讽刺啊……最完美无缺的射击，不是来自敌人，而是来自自己人的子弹！",
            ["ContentFR"] = "Mais peu importaient mes soins, mes coéquipiers étaient perdus. La plupart avaient été touchés par un tir fatal, ironie du sort... le tir parfait ne venait pas de l’ennemi, mais de nos propres hommes !",
            ["DialogueId"] = 11014420,
            ["FacialId"] = {
                [1] = "110005:Sad01",
                },
            ["GUID"] = "1B92CD48",
            ["NextDialogue"] = 11014421,
            ["SpeakNpcId"] = 110005,
            ["TalkActionId"] = {
                [1] = "110005:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110144/1B92CD48",
            },
        [11014421] = {
            ["Camera"] = "11.563477,253.448242,41.453857,0.0,-1.000336,-159.073059,44.319668,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "这就是我知道的全部了……现在，轮到您告诉我了，中央控制室里发生了什么？",
            ["ContentFR"] = "Voilà tout ce que je sais... Maintenant, c’est à vous de me raconter ce qui s’est passé dans la salle de commande.",
            ["DialogueId"] = 11014421,
            ["FacialId"] = {
                [1] = "110005:Unacceptable01",
                },
            ["GUID"] = "1B92CD72",
            ["NextDialogue"] = 11014422,
            ["SpeakNpcId"] = 110005,
            ["VoiceName"] = "voice/$Locale$/story/1002/110144/1B92CD72",
            },
        [11014422] = {
            ["Camera"] = "-156.207275,-25.750488,52.009644,0.000024,-6.59982,73.919052,35.000011,498.109375,false,Manual,22.0",
            ["Content"] = "我会告诉你，但现在还不行。",
            ["ContentFR"] = "Je te dirai plus tard, ce n’est pas le moment.",
            ["DialogueId"] = 11014422,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B92CD9C",
            ["NextDialogue"] = 11014423,
            ["Scripts"] = "PlayAnimation{_delay{2},ActorId{110022},AnimationId{\"DisagreeHead\"},Duration{2}}",
            ["SpeakNpcId"] = 110022,
            ["TalkActionId"] = {
                [1] = "110022:AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110144/1B92CD9C",
            },
        [11014423] = {
