        [11016502] = {
            ["Camera"] = "43.549805,139.308594,128.25798,0.001613,-1.609104,-101.194138,36.903526,100000.0,false,Manual,22.0",
            ["Content"] = "……怎么突然醒了？我正问到最关键的部分！",
            ["ContentFR"] = "... Pourquoi t’es-tu réveillé ? J’allais atteindre un point crucial de mon interrogatoire !",
            ["DialogueId"] = 11016502,
            ["FacialId"] = {
                [1] = "110022:None",
                },
            ["FinalCamera"] = "52.8125,137.478516,128.257767,0.001613,-1.209135,-100.994232,36.903526,100000.0,false,Manual,22.0",
            ["GUID"] = "1B9422DC",
            ["LookAt"] = {
                [1] = "110022:n(110039)",
                },
            ["NextDialogue"] = 11016503,
            ["SpeakNpcId"] = 110039,
            ["TalkActionId"] = {
                [1] = "110022:Weita_Story_Awake_End",
                },
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/1002/110165/1B9422DC",
            },
        [11016503] = {
            ["Camera"] = "67.43457,-649.426758,129.53125,0.001605,-4.809197,104.412491,36.90353,100000.0,false,Manual,22.0",
            ["Content"] = "没关系，典狱长大人。我还记得我在梦中对你说了什么。",
            ["ContentFR"] = "Ce n’est rien, Madame la Geôlière. Je me souviens de tout ce que j’ai dit dans mes rêves. Mais c'est confidentiel, je demande à vous parler en privé.",
            ["DialogueId"] = 11016503,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B942306",
            ["NextDialogue"] = 11016504,
            ["Scripts"] = "SitOrStand{ActorId{110022},State{\"Sit\"}}",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110165/1B942306",
            },
        [11016504] = {
            ["Camera"] = "-5.238281,-133.301758,125.070312,0.001531,-4.805598,92.405151,36.903526,105.270081,false,Manual,22.0",
            ["Content"] = "我会将那天的真相原原本本地告诉你，也希望你听过之后，能凭借你心中的那份“正义”做出选择。",
            ["ContentFR"] = "Je vais vous révéler exactement ce qui s’est passé ce jour-là. Et j’espère qu’après avoir entendu la vérité, vous laisserez votre propre justice guider votre jugement.",
            ["DialogueId"] = 11016504,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B942330",
            ["NextDialogue"] = 11016505,
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110165/1B942330",
            },
        [11016505] = {
            ["Camera"] = "32.214844,139.163086,128.258286,0.001612,-2.00912,-97.193909,36.903526,100000.0,false,Manual,22.0",
            ["Content"] = "你说吧。",
            ["ContentFR"] = "Parle.",
            ["DialogueId"] = 11016505,
            ["GUID"] = "1B94235A",
            ["NextDialogue"] = 11016506,
            ["SpeakNpcId"] = 110039,
            ["TalkActionId"] = {
                [1] = "110039:Sit_Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110165/1B94235A",
            },
        [11016506] = {
            ["Camera"] = "-1.37793,-810.395508,591.001038,0.001542,-46.808487,89.804596,16.538609,100000.0,false,Manual,22.0",
            ["Content"] = "那天……",
            ["ContentFR"] = "Ce jour-là...",
            ["DialogueId"] = 11016506,
            ["ExStoryInfo"] = "EXPlayer",
            ["FinalCamera"] = "-0.708984,-729.607422,508.35968,0.001516,-44.60828,88.804398,16.538609,100000.0,false,Manual,22.0",
            ["GUID"] = "1B942384",
            ["NextDialogue"] = 11016601,
            ["SpeakNpcId"] = 110022,
            ["TalkActionId"] = {
                [1] = "110039:Sit_Talk02_End",
                },
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/1002/110165/1B942384",
            },
        [11016601] = {
            ["Content"] = "让我们好好谈一谈吧。",
            ["ContentFR"] = "Nous devons avoir une vraie discussion.",
            ["DialogueId"] = 11016601,
            ["GUID"] = "1B94331A",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016601.T_Story_Recall_11016601‘",
            ["NextDialogue"] = 11016602,
            ["Scripts"] = "PARA{\
PlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt02/0043_story_empire\"},RelatedRegionId{102104}}\
}",
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110166/1B94331A",
            },
        [11016602] = {
            ["Content"] = "我长话短说。我们没有多少时间了，如果接下来还是联络不上外面，我就用这把枪向你射击，而你要做的是——装死。",
            ["ContentFR"] = "Je vais être bref, le temps presse. Si nous ne pouvons toujours pas accéder à l'extérieur... je tirerai sur toi avec cette arme. Et toi, tu devras... faire semblant d’être {性别2:mort|morte}.",
            ["DialogueId"] = 11016602,
            ["GUID"] = "1B943344",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016602.T_Story_Recall_11016602'",
            ["NextDialogue"] = 11016603,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110166/1B943344",
            },
        [11016603] = {
            ["Content"] = "为了把戏做足，我会打得更真一点。虽然不是要害，但可能会很疼。你一定要忍住，别出声。",
            ["ContentFR"] = "Pour que la mise en scène soit crédible, il faudra que la balle atteigne sa cible. Pas les points vitaux, mais la douleur sera réelle. Tu dois tenir bon. Pas un cri.",
            ["DialogueId"] = 11016603,
            ["GUID"] = "1B94336E",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016602.T_Story_Recall_11016602'",
            ["NextDialogue"] = 11016604,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110166/1B94336E",
            },
        [11016604] = {
            ["Content"] = "您要做什么？",
            ["ContentFR"] = "Que comptez-vous faire ?",
            ["DialogueId"] = 11016604,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B943398",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016604.T_Story_Recall_11016604'",
            ["NextDialogue"] = 11016605,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110166/1B943398",
            },
        [11016605] = {
            ["Content"] = "我们被困在这道门里，和外面的通讯全被切断了。富尔维斯就在路上……算算时间，这会儿他应该已经把持了整座要塞。",
            ["ContentFR"] = "Nous sommes coincés derrière cette porte, sans aucun contact avec l’extérieur. Fulvis est déjà en marche... à cette heure, il a probablement pris le contrôle de toute la forteresse.",
            ["DialogueId"] = 11016605,
            ["GUID"] = "1B9433C2",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016605.T_Story_Recall_11016605'",
            ["NextDialogue"] = 11016606,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110166/1B9433C2",
            },
        [11016606] = {
            ["Content"] = "死人才不会辩解，富尔维斯一定会要我的命。你和我一起行动，又目睹了他构陷的经过，他想必也不会让你活着回去。",
            ["ContentFR"] = "Seuls les morts restent silencieux pour toujours. Fulvis va me tuer, c’est certain. Quant à toi... tu as vu son complot, son faux dossier. Il ne te laissera jamais repartir {性别2:vivant|vivante}.",
            ["DialogueId"] = 11016606,
            ["GUID"] = "1B9433EC",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016605.T_Story_Recall_11016605'",
            ["NextDialogue"] = 11016607,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110166/1B9433EC",
            },
        [11016607] = {
            ["Content"] = "…………！！",
            ["ContentFR"] = "... !",
            ["DialogueId"] = 11016607,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B943416",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016607.T_Story_Recall_11016607'",
            ["NextDialogue"] = 11016608,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110166/1B943416",
            },
        [11016608] = {
            ["Content"] = "没关系，有我呢。",
            ["ContentFR"] = "Calme-toi. Je suis là.",
            ["DialogueId"] = 11016608,
            ["GUID"] = "1B943440",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016608.T_Story_Recall_11016608'",
            ["NextDialogue"] = 11016609,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110166/1B943440",
            },
        [11016609] = {
            ["Content"] = "……如果我“杀了你”，假借内讧向他投诚，他就有可能放松警惕，放过你……这是能让你活下去的唯一方式了。",
            ["ContentFR"] = "Si je \"t’abats\" et que je fais mine de rallier son camp... il baissera peut-être sa garde. Tu auras une chance de survivre. C’est ton seul espoir.",
            ["DialogueId"] = 11016609,
            ["GUID"] = "1B94346A",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016608.T_Story_Recall_11016608'",
            ["NextDialogue"] = 11016610,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110166/1B94346A",
            },
        [11016610] = {
            ["Content"] = "不……老师，等他们打开门，我们就一起杀出去！",
            ["ContentFR"] = "Non ! Commandant Avar, dès que la porte s’ouvrira, nous nous battrons ensemble !",
            ["DialogueId"] = 11016610,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B943494",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016610.T_Story_Recall_11016610'",
            ["NextDialogue"] = 11016622,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110166/1B943494",
            },
        [11016612] = {
            ["Content"] = "等会儿我会试着先和富尔维斯谈判。当然，多半是谈不拢的，所以别抱希望。我去和他谈判，只是为了一个重要的东西——",
            ["ContentFR"] = "J’irai parlementer avec Fulvis. Évidemment, ce sera sans doute inutile. Mais je ne veux pas négocier pour rien... je veux obtenir une chose essentielle.",
            ["DialogueId"] = 11016612,
            ["GUID"] = "1B9434E8",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016611.T_Story_Recall_11016611'",
            ["NextDialogue"] = 11016613,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110166/1B9434E8",
            },
        [11016613] = {
            ["Content"] = "“证据”。",
            ["ContentFR"] = "Des preuves.",
            ["DialogueId"] = 11016613,
            ["Duration"] = 3,
            ["GUID"] = "1B943512",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016613.T_Story_Recall_11016613'",
            ["NextDialogue"] = 11016614,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110166/1B943512",
            },
        [11016614] = {
            ["Content"] = "这是录音设备，你贴身带着。它会成为你日后扳倒富尔维斯的铁证。",
            ["ContentFR"] = "Tiens, prends cet enregistreur. Garde-le sur toi. Ce sera la pièce maîtresse qui fera tomber Fulvis.",
            ["DialogueId"] = 11016614,
            ["GUID"] = "1B94353C",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016614.T_Story_Recall_11016614'",
            ["NextDialogue"] = 11016615,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110166/1B94353C",
            },
        [11016615] = {
            ["Content"] = "决不能让士兵们冤屈的哭号，永远在龙莎要塞上空徘徊。",
            ["DialogueId"] = 11016615,
            ["GUID"] = "1B943566",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016614.T_Story_Recall_11016614'",
            ["NextDialogue"] = 11016616,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110191/1B95CD42",
            },
        [11016616] = {
            ["Content"] = "……老师……",
            ["ContentFR"] = "... Commandant Avar...",
            ["DialogueId"] = 11016616,
            ["Duration"] = 1,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B943590",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016616.T_Story_Recall_11016616'",
            ["NextDialogue"] = 11016617,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110166/1B943590",
            },
        [11016617] = {
            ["Content"] = "别苦着脸，笑一个！战士哪怕面对千万发炮弹，也要笑着一步步向前啊。",
            ["ContentFR"] = "Pourquoi cette tête ? Courage, {性别2:petit|petite} ! Un vrai soldat rit face à l’adversité.",
            ["DialogueId"] = 11016617,
            ["GUID"] = "1B9435BA",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016617.T_Story_Recall_11016617'",
            ["NextDialogue"] = 11016618,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110166/1B9435BA",
            },
        [11016618] = {
            ["Content"] = "…………",
            ["ContentFR"] = "...",
            ["DialogueId"] = 11016618,
            ["Duration"] = 2,
            ["GUID"] = "1B9435E4",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016617.T_Story_Recall_11016617'",
            ["NextDialogue"] = 11016619,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110166/1B9435E4",
            },
        [11016619] = {
            ["Content"] = "……{nickname2}，我引以为傲的学生啊……抱歉，连累你卷进了这种事。",
            ["ContentFR"] = "{nickname2}, mon élève dont je suis si fier... pardonne-moi de t’avoir mêlée à tout ça.",
            ["DialogueId"] = 11016619,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B94360E",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016619.T_Story_Recall_11016619'",
            ["NextDialogue"] = 11016620,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110166/1B94360E",
            },
        [11016620] = {
            ["Content"] = "但你一定要活下去，原原本本地将这里的真相带给军团长，带给陛下。你要让全帝国的人知道，这里的每一个士兵，都为了他们的信条与使命，战至最后一刻。",
            ["ContentFR"] = "Mais tu dois survivre. Tu dois transmettre toute la vérité à la Commandante Sibylle, et à Sa Majesté. L’Empire tout entier doit savoir que chaque soldat ici a combattu jusqu’au dernier souffle, fidèle à son serment et à sa mission.",
            ["DialogueId"] = 11016620,
            ["GUID"] = "1B943638",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016620.T_Story_Recall_11016620'",
            ["NextDialogue"] = 11016621,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110166/1B943638",
            },
        [11016621] = {
            ["Content"] = "……荣耀尽归吾皇。",
            ["ContentFR"] = "... Toute gloire à l’Empereur !",
            ["DialogueId"] = 11016621,
            ["GUID"] = "1B943662",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016621.T_Story_Recall_11016621'",
            ["NextDialogue"] = 11016701,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110166/1B943662",
            },
        [11016622] = {
            ["Content"] = "那以你估计，经过这一路的消耗，再加上坐困在此的形势，你我现在和富尔维斯的亲兵硬碰硬，有几成胜算？",
            ["ContentFR"] = "Réfléchis. Dans notre état, encerclés comme nous le sommes, crois-tu vraiment que nous avons la moindre chance face aux gardes personnels de Fulvis ?",
            ["DialogueId"] = 11016622,
            ["GUID"] = "1B943495",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016611.T_Story_Recall_11016611'",
            ["NextDialogue"] = 11016623,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110166/1B943495",
            },
        [11016623] = {
            ["Content"] = "对方合围的话……胜算接近于零。但大不了就是一死——",
            ["ContentFR"] = "Si nous sommes cernés... nos chances frôlent le néant. Mais tant pis, quitte à mourir, autant—",
            ["DialogueId"] = 11016623,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B943496",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016611.T_Story_Recall_11016611'",
            ["NextDialogue"] = 11016624,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110166/1B943496",
            },
        [11016624] = {
            ["Content"] = "死很容易，带着使命活下去却很难。但，{nickname2}，我命令你这么做，这个任务也只有你能完成。",
            ["ContentFR"] = "Mourir, c’est facile. Continuer à vivre, mener à bien la mission, voilà ce qui est difficile. {nickname2}, c’est un ordre : toi {性别2:seul|seule} peux mener cette mission à bien.",
            ["DialogueId"] = 11016624,
            ["GUID"] = "1B943497",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016611.T_Story_Recall_11016611'",
            ["NextDialogue"] = 11016625,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110166/1B943497",
            },
        [11016625] = {
            ["Content"] = "至于我……呵，我这条命比你想象中宝贵，还有别的用呢。",
            ["ContentFR"] = "Quant à moi... hmpf. Ma vie n’est pas encore fini. J’ai encore un rôle à jouer.",
            ["DialogueId"] = 11016625,
            ["GUID"] = "1B943498",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016611.T_Story_Recall_11016611'",
            ["NextDialogue"] = 11016612,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110166/1B943498",
            },
        [11016701] = {
            ["Camera"] = "-5.238281,-133.301758,125.070312,0.001531,-4.805598,92.405151,36.903526,109.538574,false,Manual,22.0",
            ["Content"] = "……这就是那天在中央控制室发生的事。",
            ["ContentFR"] = "Voilà ce qui s’est passé ce jour-là, dans la salle de commande centrale.",
            ["DialogueId"] = 11016701,
            ["ExStoryInfo"] = "EXPlayer",
            ["FinalCamera"] = "-3.560547,-173.319336,128.433594,0.001531,-4.805598,92.405151,36.903526,145.652008,false,Manual,22.0",
            ["GUID"] = "1B944382",
            ["NextDialogue"] = 11016702,
            ["Scripts"] = "PlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/mute\"},RelatedRegionId{102104}}",
            ["SpeakNpcId"] = 110022,
            ["TalkActionId"] = {
                [1] = "110039:Sit_Talk03_Start",
                },
            ["ToFinalCameraBlendTime"] = 6,
            ["VoiceName"] = "voice/$Locale$/story/1002/110167/1B944382",
            },
        [11016702] = {
            ["Camera"] = "570.384766,-248.601562,159.607712,0.001551,-7.005765,175.00383,19.596729,100000.0,false,Manual,22.0",
            ["Content"] = "阿瓦尔老师在最后一刻，面对比他强大千万倍的阴谋和子弹，用自己的生命留下了决定性的证据——这便是他坚守正义的方式。",
            ["ContentFR"] = "Commandant Avar, jusqu’à son dernier instant, a affronté un complot d’une ampleur démesurée. Il a sacrifié sa vie pour laisser derrière lui une preuve décisive... son ultime façon de servir la justice.",
            ["DialogueId"] = 11016702,
            ["ExStoryInfo"] = "EXPlayer",
            ["FinalCamera"] = "566.180664,-300.931641,159.606354,0.001551,-7.005704,175.403824,19.596729,100000.0,false,Manual,22.0",
            ["GUID"] = "1B9443AC",
            ["NextDialogue"] = 11016703,
            ["SpeakNpcId"] = 110022,
            ["ToFinalCameraBlendTime"] = 12,
            ["VoiceName"] = "voice/$Locale$/story/1002/110167/1B9443AC",
            },
        [11016703] = {
            ["Camera"] = "-3.560547,-173.319336,123.261719,0.001521,-4.805598,92.405113,36.90353,148.063751,false,Manual,22.0",
            ["Content"] = "只可惜他还是低估了敌人的缜密。我半昏迷时，隐约感觉到，富尔维斯的副官法露茜带走了那支录音设备。",
            ["ContentFR"] = "Mais l’ennemi avait prévu chaque détail. À demi {性别2:inconscient|inconsciente}, j’ai senti l’adjudante de Fulvis, Falsi, m’arracher l’enregistreur.",
            ["DialogueId"] = 11016703,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B9443D6",
            ["NextDialogue"] = 11016704,
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110167/1B9443D6",
            },
        [11016704] = {
            ["Camera"] = "299.907227,-246.0,95.800987,-0.000854,42.006584,-179.996628,36.931984,100000.0,false,Manual,22.0",
            ["Content"] = "醒来后，富尔维斯已经接管了整座要塞，此时和他们硬拼只会让我和达芙涅送命……真相也将石沉大海。",
            ["ContentFR"] = "Quand j’ai repris mes esprits, Fulvis contrôlait déjà toute la forteresse. Le défier alors, cela aurait été me condamner, Daphne et moi... et condamner la vérité à disparaître avec nous.",
            ["DialogueId"] = 11016704,
            ["ExStoryInfo"] = "EXPlayer",
            ["FinalCamera"] = "299.907227,-268.0,95.800987,-0.000854,42.006584,-179.996628,36.931984,100000.0,false,Manual,22.0",
            ["GUID"] = "1B944400",
            ["NextDialogue"] = 11019102,
            ["SpeakNpcId"] = 110022,
            ["ToFinalCameraBlendTime"] = 12,
            ["VoiceName"] = "voice/$Locale$/story/1002/110167/1B944400",
            },
        [11016705] = {
            ["Camera"] = "76.907227,-660.533203,98.932999,-0.000916,-2.393981,100.607307,48.616428,100000.0,false,Manual,22.0",
            ["Content"] = "所以，我们选择用这种方式来见你。我相信，以你的手段，一定能得到那份证据，或者至少，得到法露茜的供词。",
            ["DialogueId"] = 11016705,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B94442A",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110167/1B94442A",
            },
        [11016706] = {
            ["Camera"] = "101.0,-126.956055,72.582031,-0.000917,13.404778,137.606186,36.480843,158.868011,false,Manual,22.0",
            ["Content"] = "海尔法典狱长，你言必称正义，我想你应该明白应当怎么坚守你的正义了。去抓捕法露茜吧，你想要的真相就在那里。",
            ["ContentFR"] = "Madame la Geôlière, vous parlez sans cesse de justice. Alors je vous le demande : arrêtez Falsi. C’est elle qui détient la vérité.",
            ["DialogueId"] = 11016706,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B944454",
            ["NextDialogue"] = 11019104,
            ["Scripts"] = "CameraMoveTo{_delay{8},TargetPosition{\"75.275391,226.958008,101.472656,-0.000915,-0.995684,-100.79319,52.299137,718.026855,false,Manual,22.0\"},duration{0}}",
            ["SpeakNpcId"] = 110022,
            ["TalkActionId"] = {
                [1] = "110022:Sit_Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110167/1B944454",
            },
        [11016707] = {
            ["Camera"] = "15.709961,-308.188477,107.445312,-0.000916,-1.595662,-98.792236,35.182564,169.208145,false,Manual,22.0",
            ["Content"] = "海伯利亚是一架巨大的机器，它需要能让每颗螺钉都正确运转的规律。",
            ["ContentFR"] = "Hyperborea est une vaste machine. Chaque pièce doit tourner selon la loi qui lui est assignée.",
            ["DialogueId"] = 11016707,
            ["GUID"] = "1B94447E",
            ["NextDialogue"] = 11016708,
            ["SpeakNpcId"] = 110039,
            ["TalkActionId"] = {
                [1] = "110022:Sit_Talk02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110167/1B94447E",
            },
        [11016708] = {
            ["Camera"] = "-23.03125,453.560547,337.066406,-0.000917,-19.995569,-87.991684,27.483999,100000.0,false,Manual,22.0",
            ["Content"] = "我的职责便是保护这条规律，保护海伯利亚订下的“正义”。如果有人想要利用我的手摧毁这条规律，我便会让他付出应有的代价。",
            ["ContentFR"] = "Mon rôle est de protéger cette loi, de protéger la justice qu’Hyperborea a établie. Et si quelqu’un tente de m’instrumentaliser pour la détourner, il en paiera le prix.",
            ["DialogueId"] = 11016708,
            ["FinalCamera"] = "-17.12207,284.929688,275.703125,-0.000917,-19.995569,-87.991684,27.483999,100000.0,false,Manual,22.0",
            ["GUID"] = "1B9444A8",
            ["NextDialogue"] = 11016709,
            ["SpeakNpcId"] = 110039,
            ["ToFinalCameraBlendTime"] = 12,
            ["VoiceName"] = "voice/$Locale$/story/1002/110167/1B9444A8",
            },
        [11016709] = {
            ["Camera"] = "-5.833984,-339.387695,101.292969,-0.000916,-0.200104,-90.570984,21.509014,135.908142,false,Manual,22.0",
            ["Content"] = "我会去调查法露茜。但如果你在用谎言拖延时间，想必你清楚后果。",
            ["ContentFR"] = "J’irai enquêter sur Falsi. Mais si tu mens pour gagner du temps... tu connais les conséquences.",
            ["DialogueId"] = 11016709,
            ["FinalCamera"] = "-6.027344,-359.292969,101.292969,-0.000916,-0.200104,-90.570984,21.509014,119.777908,false,Manual,22.0",
            ["GUID"] = "1B9444D2",
            ["NextDialogue"] = 11016710,
            ["Scripts"] = "PlayAnimation{ActorId{110039},AnimationId{\"Sit_Talk02_Start\"},Duration{8}}",
            ["SpeakNpcId"] = 110039,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1002/110167/1B9444D2",
            },
