            },
        [11017113] = {
            ["Camera"] = "3.826172,76.46582,165.292969,0.000128,-0.600066,-114.184586,31.194523,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "你短期可能回不了军团了。你的嫌疑并未真的洗清，现在回军团只怕身份会尴尬。",
            ["ContentFR"] = "Pour le moment, tu ne pourras pas retourner à la Légion. Ton statut reste délicat, y revenir maintenant serait compliqué.",
            ["DialogueId"] = 11017113,
            ["Duration"] = 3,
            ["GUID"] = "1B94871A",
            ["NextDialogue"] = 11019115,
            ["Scripts"] = "PARA{\
