            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1002/110171/1B948798",
            },
        [11017117] = {
            ["Camera"] = "-38.605469,-123.583984,167.742188,0.000094,-5.999843,78.991455,31.194527,446.287842,false,Manual,11.834087",
            ["Content"] = "我知道你在担心什么。西比尔·梅森和达芙涅有些故交，且在这起事件中，她明显更相信你们无辜，所以她至少会保证达芙涅的安全。",
            ["ContentFR"] = "Je sais ce qui te préoccupe. Sibylle Mason a des liens anciens avec Daphne, et dans cette affaire, elle croit manifestement en votre innocence. Elle veillera donc, au minimum, à ce que Daphne soit en sécurité.",
            ["DialogueId"] = 11017117,
            ["Duration"] = 3,
            ["FinalCamera"] = "-45.6875,-122.178711,167.742188,0.000092,-6.199858,78.391617,31.194527,446.287842,false,Manual,11.834087",
            ["GUID"] = "1B9487C2",
            ["NextDialogue"] = 11019119,
            ["SpeakNpcId"] = 110018,
            ["ToFinalCameraBlendTime"] = 15,
            ["VoiceName"] = "voice/$Locale$/story/1002/110171/1B9487C2",
            },
        [11017119] = {
            ["Camera"] = "653.830078,-1243.886719,875.824219,0.000136,-26.201082,109.391876,31.194523,1682.25708,false,Manual,1.2",
            ["Content"] = "……哈，你知道我最厌恶那些老家伙的繁文缛节。不过，你总算有心情开玩笑了，这很好。",
            ["ContentFR"] = "... Allez, tu sais bien que je déteste ces coutumes et ces règles de bienséance inutiles. Mais tu es d’humeur à plaisanter maintenant, ce qui est bon signe.",
            ["DialogueId"] = 11017119,
            ["Duration"] = 3,
            ["FacialId"] = {
                [1] = "110018:Smile01",
                },
            ["FinalCamera"] = "619.453125,-1255.985352,875.824219,0.000136,-26.201082,109.391876,31.194523,1682.25708,false,Manual,1.2",
            ["GUID"] = "1B948816",
            ["NextDialogue"] = 11019121,
            ["Scripts"] = "PlayAnimation{_delay{3},ActorId{110022},AnimationId{\"Explain02_End\"},Duration{3}}",
            ["SpeakNpcId"] = 110018,
            ["TalkActionId"] = {
                [1] = "110018:Talk03_End",
                },
            ["ToFinalCameraBlendTime"] = 15,
            ["VoiceName"] = "voice/$Locale$/story/1002/110171/1B948816",
            },
        [11017201] = {
            ["Content"] = "{nickname2}，你就什么都不问？",
            ["ContentFR"] = "{nickname2}, tu ne comptes vraiment rien me demander ?",
            ["DialogueId"] = 11017201,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B9488C0",
            ["NextDialogue"] = 11017202,
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110172/1B9488C0",
            },
        [11017202] = {
            ["Content"] = "您刚说过，军人要无条件服从命令。",
            ["ContentFR"] = "Vous venez de dire qu’un soldat doit obéir sans condition.",
            ["DialogueId"] = 11017202,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B9488C1",
            ["NextDialogue"] = 11017203,
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110172/1B9488C1",
            },
        [11017203] = {
            ["Content"] = "都这个份上了，你怎么还是老样子，像块木雕似的。",
            ["ContentFR"] = "Après tout ça, tu restes toujours aussi raide... comme un fichu morceau de bois.",
            ["DialogueId"] = 11017203,
            ["Duration"] = 3,
            ["GUID"] = "1B9488C2",
            ["NextDialogue"] = 11017204,
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110172/1B9488C2",
            },
        [11017204] = {
            ["Content"] = "老师，您还说过，作战时必须集中注意力。",
            ["ContentFR"] = "Vous avez aussi dit qu’en combat, il faut rester concentré.",
            ["DialogueId"] = 11017204,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B9488C3",
            ["NextDialogue"] = 11017205,
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110172/1B9488C3",
            },
        [11017205] = {
            ["Content"] = "现在情况并不安全，分心批评我，会增加您的伤亡概率。",
            ["ContentFR"] = "La situation n’est pas sûre. Si vous perdez du temps à me faire des reproches, vous augmentez vos chances d’être touché.",
            ["DialogueId"] = 11017205,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B9488C4",
            ["NextDialogue"] = 11017206,
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110172/1B9488C4",
            },
        [11017206] = {
            ["Content"] = "你这小鬼！",
            ["ContentFR"] = "{性别2:Petit insolent|Petite insolente} !",
            ["DialogueId"] = 11017206,
            ["Duration"] = 3,
            ["GUID"] = "1B9488C5",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110172/1B9488C5",
            },
        [11017301] = {
            ["Content"] = "“狮鹫”该不会就剩你一个了？其他人什么情况？",
            ["ContentFR"] = "Ne me dis pas qu’il ne reste plus que toi des Griffons. Où est le reste de ton escouade ?",
            ["DialogueId"] = 11017301,
            ["Duration"] = 3,
            ["GUID"] = "1B909E29",
            ["NextDialogue"] = 11017302,
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110110/1B909E29",
            },
        [11017302] = {
            ["Content"] = "他们在前面，大多伤得不轻。跟我来。",
            ["ContentFR"] = "Ils sont plus loin. La plupart sont grièvement blessés. Suivez-moi.",
            ["DialogueId"] = 11017302,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B909E30",
            ["NextDialogue"] = 11011013,
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110110/1B909E30",
            },
        [11017401] = {
            ["DialogueId"] = 11017401,
            ["Duration"] = 2,
            ["GUID"] = "1B94B65A",
            ["VoiceName"] = "voice/$Locale$/story/1002/110174/1B94B65A",
            },
        [11017402] = {
            ["Content"] = "达芙涅对伤员们进行了治疗",
            ["ContentFR"] = "Daphne a soigné les blessés.",
            ["DialogueId"] = 11017402,
            ["Duration"] = 2,
            ["GUID"] = "1B94B684",
            ["VoiceName"] = "voice/$Locale$/story/1002/110174/1B94B684",
            },
        [11017403] = {
            ["Content"] = "带着卡嘉一行人离开了此处……",
            ["ContentFR"] = "Tu emmènes Katya et les autres loin de cet endroit...",
            ["DialogueId"] = 11017403,
            ["Duration"] = 2,
            ["GUID"] = "1B94B6AE",
            ["VoiceName"] = "voice/$Locale$/story/1002/110174/1B94B6AE",
            },
        [11017404] = {
            ["Content"] = "这是……继电器，总之先关闭一个",
            ["ContentFR"] = "<I>Un... relais ? Quoi qu’il en soit, commençons par en couper un.</>",
            ["DialogueId"] = 11017404,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B94B6D8",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110174/1B94B6D8",
            },
        [11017405] = {
            ["DialogueId"] = 11017405,
            ["Duration"] = 2,
            ["GUID"] = "1B94B702",
            ["VoiceName"] = "voice/$Locale$/story/1002/110174/1B94B702",
            },
        [11017406] = {
            ["Content"] = "不要动！",
            ["ContentFR"] = "Pas un geste !",
            ["DialogueId"] = 11017406,
            ["Duration"] = 2,
            ["GUID"] = "1B909E34",
            ["GuideFacialId"] = "Afraid",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 110005,
            ["VoiceName"] = "voice/$Locale$/story/1002/110110/1B909E34",
            },
        [11017407] = {
            ["Content"] = "水位降不下去！",
            ["ContentFR"] = "L’eau ne descend pas !",
            ["DialogueId"] = 11017407,
            ["Duration"] = 2,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B94B756",
            ["GuideFacialId"] = "Afraid",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 11017408,
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110174/1B94B756",
            },
        [11017408] = {
            ["Content"] = "从边上绕过去吧。",
            ["ContentFR"] = "Contournons par le côté.",
            ["DialogueId"] = 11017408,
            ["Duration"] = 2,
            ["GUID"] = "1B94B780",
            ["SpeakNpcId"] = 110005,
            ["VoiceName"] = "voice/$Locale$/story/1002/110174/1B94B780",
            },
        [11017409] = {
            ["DialogueId"] = 11017409,
            ["Duration"] = 2,
            ["GUID"] = "1B94B7AA",
            ["VoiceName"] = "voice/$Locale$/story/1002/110174/1B94B7AA",
            },
        [11017410] = {
            ["Camera"] = "402.354004,84.89209,149.571686,0.000074,4.19976,-153.080948,21.458063,100000.0,false,Manual,22.0",
            ["Content"] = "权限确认，请通行。",
            ["ContentFR"] = "Accès autorisé. Veuillez poursuivre.",
            ["DialogueId"] = 11017410,
            ["Duration"] = 3,
            ["FinalCamera"] = "353.715454,60.211914,153.577911,0.000074,4.19976,-153.080948,21.458063,100000.0,false,Manual,22.0",
            ["GUID"] = "1B94B7D4",
            ["SpeakNpcName"] = "UI_Npc_MechVoice",
            ["ToFinalCameraBlendTime"] = 20,
            ["VoiceName"] = "voice/$Locale$/story/1002/110174/1B94B7D4",
            },
        [11017411] = {
            ["Content"] = "好，月髓连接上了【废弃】",
            ["DialogueId"] = 11017411,
            ["DialoguePanelType"] = "{type:Guide;style:Communicator}",
            ["Duration"] = 3,
            ["GUID"] = "1B94B7FE",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110174/1B94B7FE",
            },
        [11017412] = {
            ["Content"] = "咦，被挡住了，看起来要绕一下路呢……",
            ["ContentFR"] = "Hein ? Bloqué. Il faudra faire un détour...",
            ["DialogueId"] = 11017412,
            ["Duration"] = 5,
            ["GUID"] = "1B94B828",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 110034,
            ["VoiceName"] = "voice/$Locale$/story/1002/110174/1B94B828",
            },
        [11017413] = {
            ["Content"] = "开关还打不开，先启动相连的髓动轮吧。",
            ["ContentFR"] = "L’interrupteur ne fonctionne pas encore. Je devrais peut-être d’abord activer la roue connectée.",
            ["DialogueId"] = 11017413,
            ["Duration"] = 5,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B94B852",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110174/1B94B852",
            },
        [11017414] = {
            ["Content"] = "（……要抓紧时间打开开关。）",
            ["ContentFR"] = "<I>... Il faut vite activer l’interrupteur.</>",
            ["DialogueId"] = 11017414,
            ["DisableMouth"] = 1,
            ["Duration"] = 5,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B94B87C",
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110174/1B94B87C",
            },
        [11017415] = {
            ["Content"] = "炮台的能源已经全部连通，回来汇合吧。【废弃】",
            ["DialogueId"] = 11017415,
            ["DialoguePanelType"] = "{type:Guide;style:Communicator}",
            ["Duration"] = 5,
            ["GUID"] = "1B94B8A6",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110174/1B94B8A6",
            },
        [11017416] = {
            ["Content"] = "准备好了，就激活髓动轮出发吧。",
            ["DialogueId"] = 11017416,
            ["DialoguePanelType"] = "{type:Guide;style:Communicator}",
            ["GUID"] = "1B94B8D0",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110174/1B94B8D0",
            },
        [11017417] = {
            ["Content"] = "（顺着这些线缆找到髓动轮吧。）",
            ["ContentFR"] = "<I>Suivons ces câbles jusqu’aux Roues Phoxynamo.</>",
            ["DialogueId"] = 11017417,
            ["DisableMouth"] = 1,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B94B8FA",
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110174/1B94B8FA",
            },
        [11017418] = {
            ["Content"] = "好厉害……",
            ["ContentFR"] = "Impressionnant...",
            ["DialogueId"] = 11017418,
            ["GUID"] = "1B94B924",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 110034,
            ["VoiceName"] = "voice/$Locale$/story/1002/110174/1B94B924",
            },
        [11017419] = {
            ["Content"] = "（找到了……启动它吧。）",
            ["ContentFR"] = "<I>Trouvé... activons-la.</>",
            ["DialogueId"] = 11017419,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B94B94E",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110174/1B94B94E",
            },
        [11017420] = {
            ["Content"] = "他们管这里叫“模拟战场”，说什么……“这次的主题是冰湖城防卫战”。",
            ["ContentFR"] = "Ils appellent ça le « Champ de Bataille Simulé », et ils disent... « Cette fois, le thème est la défense de la cité de Givrelac ».",
            ["DialogueId"] = 11017420,
            ["GUID"] = "1B94B978",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 11017421,
            ["SpeakNpcId"] = 110034,
            ["VoiceName"] = "voice/$Locale$/story/1002/110174/1B94B978",
            },
        [11017421] = {
            ["Content"] = "听说那个冰湖城，到处都是冰天雪地的。我还没见过雪呢……真想去看看！",
            ["ContentFR"] = "J’ai entendu que cette cité était recouverte de neige. Je n’ai jamais vu de neige... J’aimerais tellement...",
            ["DialogueId"] = 11017421,
            ["GUID"] = "1B94B9A2",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 11017422,
            ["SpeakNpcId"] = 110034,
            ["VoiceName"] = "voice/$Locale$/story/1002/110174/1B94B9A2",
            },
        [11017422] = {
            ["Content"] = "……我是说，如果，我能活着回家。",
            ["ContentFR"] = "... Enfin, si j’arrive à rentrer vivante.",
            ["DialogueId"] = 11017422,
            ["GUID"] = "1B94B9CC",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 110034,
            ["VoiceName"] = "voice/$Locale$/story/1002/110174/1B94B9CC",
            },
        [11017423] = {
            ["Content"] = "好了。",
            ["ContentFR"] = "<I>C’est fait.</>",
            ["DialogueId"] = 11017423,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B94B9F6",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110174/1B94B9F6",
            },
        [11017501] = {
            ["Content"] = "动力室是整座要塞的“心脏”，维持要塞运转的能源都来自里面那台月髓舱。",
            ["ContentFR"] = "La salle des machines est le \"cœur\" de toute la forteresse. Toute l’énergie qui la maintient en fonctionnement vient du réservoir de Phoxichor.",
            ["DialogueId"] = 11017501,
            ["DialoguePanelType"] = "{type:Guide;style:Communicator}",
            ["GUID"] = "1B94C6C2",
            ["NextDialogue"] = 11017502,
            ["Scripts"] = "PlayNormalSound{EventPath{\"event:/sfx/common/story/ex01/signal_on\"},PlayAs2D{true}}",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110175/1B94C6C2",
            },
        [11017502] = {
            ["Content"] = "但直接攻击月髓舱会引起爆炸，你得先去关掉四周的<H>髓动轮</>。",
            ["ContentFR"] = "Mais attaquer directement le réservoir provoquerait une explosion. Tu dois d’abord désactiver les <H>Roues Phoxynamo</> autour.",
            ["DialogueId"] = 11017502,
            ["DialoguePanelType"] = "{type:Guide;style:Communicator}",
            ["GUID"] = "1B94C6EC",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110175/1B94C6EC",
            },
        [11017503] = {
            ["Camera"] = "804.818848,157.511719,744.295471,0.000002,-8.800173,-4.800692,23.868748,100000.0,false,Manual,22.0",
            ["Content"] = "那些髓动轮，蓝色的，你应该能认得出来吧？你现在要做的是把它们变成黄色。",
            ["ContentFR"] = "Regarde ces roues, les bleues. Tu sais ce que tu as à faire : les passer au jaune.",
            ["DialogueId"] = 11017503,
            ["DialoguePanelType"] = "{type:Guide;style:Communicator}",
            ["GUID"] = "1B94C716",
            ["NextDialogue"] = 11017504,
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110175/1B94C716",
            },
        [11017504] = {
            ["Content"] = "老师，我早毕业了，不用这样一步一步指导的。",
            ["ContentFR"] = "Commandant, maîtriser les bases, ça fait longtemps que je sais faire, pas besoin de me tenir la main à chaque étape.",
            ["DialogueId"] = 11017504,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B94C740",
            ["NextDialogue"] = 11017505,
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110175/1B94C740",
            },
        [11017505] = {
            ["Content"] = "那你见机行事吧，必要时我再联络你。",
            ["ContentFR"] = "... {性别2:Petit impertinent|Petite impertinente} ! Alors débrouille-toi, je te contacterai si besoin.",
            ["DialogueId"] = 11017505,
            ["DialoguePanelType"] = "{type:Guide;style:Communicator}",
            ["GUID"] = "1B94C76A",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110175/1B94C76A",
            },
        [11017506] = {
            ["Content"] = "（顺着地上这些线缆，应该能顺利找到那些髓动轮。但愿它们不要藏得太刁钻。）",
            ["ContentFR"] = "<I>Suivant les câbles au sol, je devrais pouvoir atteindre les Roues Phoxynamo. Espérons qu’elles ne soient pas trop bien cachées.</>",
            ["DialogueId"] = 11017506,
            ["DisableMouth"] = 1,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B94C794",
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110175/1B94C794",
            },
        [11017507] = {
            ["Content"] = "（先处理这台吧。）",
            ["ContentFR"] = "<I>Je commence par celle-ci.</>",
            ["DialogueId"] = 11017507,
            ["DisableMouth"] = 1,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B94C7BE",
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110175/1B94C7BE",
            },
        [11017508] = {
            ["Content"] = "（好，关停了。）",
            ["ContentFR"] = "<I>Bien, celle-ci est désactivée. Allons chercher les autres.</>",
            ["DialogueId"] = 11017508,
            ["DisableMouth"] = 1,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B94C7E8",
            ["NextDialogue"] = 11018203,
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110175/1B94C7E8",
            },
        [11017509] = {
            ["Content"] = "正东方向的门搞定，可以通过了。",
            ["ContentFR"] = "La porte à l’est est maintenant ouverte. Tu peux passer.",
            ["DialogueId"] = 11017509,
            ["DialoguePanelType"] = "{type:Guide;style:Communicator}",
            ["GUID"] = "1B94C812",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110175/1B94C812",
            },
        [11017510] = {
            ["Content"] = "（把髓动轮塞在这么古怪的位置，龙莎的工程师还真不嫌麻烦。）",
            ["ContentFR"] = "<I>Ils ont mis ces Roues Phoxynamo dans des endroits complètement tordus... Ces ingénieurs ne font jamais simple.</>",
            ["DialogueId"] = 11017510,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B94C83C",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110175/1B94C83C",
            },
        [11017511] = {
            ["Content"] = "（这样就可以了。）",
            ["ContentFR"] = "<I>Celle-ci est désactivée.</>",
            ["DialogueId"] = 11017511,
            ["DisableMouth"] = 1,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B94C866",
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110175/1B94C866",
            },
        [11017512] = {
            ["Content"] = "（真麻烦……）",
            ["ContentFR"] = "<I>Encore trois à faire...</>",
