            ["SpeakNpcId"] = 110010,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1002/110175/1B94C9E0",
            },
        [11017521] = {
            ["Camera"] = "992.544189,397.238281,178.074951,-0.0,-8.599126,-138.38974,40.000011,100000.0,false,DoNotOverride,20.0",
            ["Content"] = "您指的是……利用过载炸毁月髓舱？我知道了。",
            ["ContentFR"] = "Vous voulez dire... provoquer l’explosion du réservoir par surcharge ? Compris.",
            ["DialogueId"] = 11017521,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B94CA0A",
            ["Scripts"] = "PlayNormalSound{_delay{5},EventPath{\"event:/sfx/common/story/ex01/signal_off\"},PlayAs2D{true}}",
            ["SnapShot"] = "TELEPHONE",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110175/1B94CA0A",
            },
        [11017601] = {
            ["Content"] = "1号备用髓动轮可以操作了，启动吧。",
            ["ContentFR"] = "La Roue Phoxynamo de secours n° 1 est prête. Active-la.",
            ["DialogueId"] = 11017601,
            ["GUID"] = "1B94D72A",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110176/1B94D72A",
            },
        [11017602] = {
            ["Content"] = "干得好，我会把剩下三台的髓动轮的操作权限一一解锁。",
            ["ContentFR"] = "Bien joué. Je débloque les trois autres Roues Phoxynamo de secours.",
            ["DialogueId"] = 11017602,
            ["GUID"] = "1B94D754",
            ["NextDialogue"] = 11017603,
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110176/1B94D754",
            },
        [11017603] = {
            ["Content"] = "等黄色灯光亮起，你就启动它。",
            ["ContentFR"] = "Quand la lumière jaune s’allume, tu les actives.",
            ["DialogueId"] = 11017603,
            ["GUID"] = "1B94D77E",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110176/1B94D77E",
            },
        [11017604] = {
            ["Content"] = "（髓动轮亮了，看来老师那边已经解决了。）",
            ["ContentFR"] = "<I>La lumière est allumée. Apparemment, le Commandant Avar a réussi de son côté.</>",
            ["DialogueId"] = 11017604,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B94D7A8",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110176/1B94D7A8",
            },
        [11017605] = {
            ["Content"] = "<W>警告：月髓舱负荷过大，已过载50%。请立即停止髓动轮设备使用，不得擅自撤离。</>",
            ["ContentFR"] = "<W>AVERTISSEMENT : Surcharge du réservoir de Phoxichor à 50 %. Arrêtez immédiatement l’utilisation des Roues Phoxynamo, départ non autorisé interdit.</>",
            ["DialogueId"] = 11017605,
            ["GUID"] = "1B94D7D2",
            ["NextDialogue"] = 11017606,
            ["SnapShot"] = "BROADCAST",
            ["SpeakNpcName"] = "UI_Npc_MechVoice",
            ["VoiceName"] = "voice/$Locale$/story/1002/110176/1B94D7D2",
            },
        [11017606] = {
            ["Content"] = "（……要尽快了。）",
            ["ContentFR"] = "<I>... Il faut que je me dépêche.</>",
            ["DialogueId"] = 11017606,
            ["DisableMouth"] = 1,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B94D7FC",
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110176/1B94D7FC",
            },
        [11017607] = {
            ["Content"] = "3号也可以了，去吧！",
            ["ContentFR"] = "La n° 3 est prête, vas-y !",
            ["DialogueId"] = 11017607,
            ["DialoguePanelType"] = "{type:Guide;style:Communicator}",
            ["GUID"] = "1B94D826",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110176/1B94D826",
            },
        [11017608] = {
            ["Content"] = "（呼……）",
            ["ContentFR"] = "<I>Pfiou...</>",
            ["DialogueId"] = 11017608,
            ["DisableMouth"] = 1,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B94D850",
            ["NextDialogue"] = 11017609,
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110176/1B94D850",
            },
        [11017609] = {
            ["Content"] = "干净利落，做得漂亮。",
            ["ContentFR"] = "Net et rapide, bien joué, {性别2:petit|petite} !",
            ["DialogueId"] = 11017609,
            ["DialoguePanelType"] = "{type:Guide;style:Communicator}",
            ["GUID"] = "1B94D87A",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110176/1B94D87A",
            },
        [11017610] = {
            ["Content"] = "权限激活了，这是最后一台！",
            ["ContentFR"] = "L’autorité de contrôle est déverrouillée. La dernière roue est prête !",
            ["DialogueId"] = 11017610,
            ["DialoguePanelType"] = "{type:Guide;style:Communicator}",
            ["GUID"] = "1B94D8A4",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110176/1B94D8A4",
            },
        [11017611] = {
            ["Content"] = "<W>警告：月髓舱即将损毁，请自首。</>",
            ["ContentFR"] = "<W>AVERTISSEMENT : Sabotage du réservoir de Phoxichor détecté. Toute personne responsable doit se dénoncer.</>",
            ["DialogueId"] = 11017611,
            ["GUID"] = "1B94D8CE",
            ["SnapShot"] = "BROADCAST",
            ["SpeakNpcName"] = "UI_Npc_MechVoice",
            ["VoiceName"] = "voice/$Locale$/story/1002/110176/1B94D8CE",
            },
        [11017612] = {
            ["Content"] = "快！撤到安全门后面去！",
            ["ContentFR"] = "Vite ! Mets-toi derrière la porte de sécurité !",
            ["DialogueId"] = 11017612,
            ["DialoguePanelType"] = "{type:Guide;style:Communicator}",
            ["GUID"] = "1B94D8F8",
            ["NextDialogue"] = 11017613,
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110176/1B94D8F8",
            },
        [11017613] = {
            ["Content"] = "<W>警告：月髓舱即将损毁，请自首。</>",
            ["ContentFR"] = "<W>AVERTISSEMENT : Sabotage du réservoir de Phoxichor détecté. Toute personne responsable doit se dénoncer.</>",
            ["DialogueId"] = 11017613,
            ["GUID"] = "1B94D922",
            ["SnapShot"] = "BROADCAST",
            ["SpeakNpcName"] = "UI_Npc_MechVoice",
            ["VoiceName"] = "voice/$Locale$/story/1002/110176/1B94D922",
            },
        [11017701] = {
            ["Content"] = "长官，请走这边……",
            ["ContentFR"] = "Capitaine, suivez-moi par ici...",
            ["DialogueId"] = 11017701,
            ["GUID"] = "1B94E792",
            ["SpeakNpcId"] = 110017,
            ["VoiceName"] = "voice/$Locale$/story/1002/110177/1B94E792",
            },
        [11017702] = {
            ["Content"] = "长官，从这里下去，就是地下水道了。",
            ["ContentFR"] = "Capitaine, par ici... on peut descendre dans les égouts.",
            ["DialogueId"] = 11017702,
            ["GUID"] = "1B94E7BC",
            ["NextDialogue"] = 11017703,
            ["SpeakNpcId"] = 110017,
            ["VoiceName"] = "voice/$Locale$/story/1002/110177/1B94E7BC",
            },
        [11017703] = {
            ["Content"] = "卡戎人，你走前面。",
            ["ContentFR"] = "Vas-y en premier, Charon.",
            ["DialogueId"] = 11017703,
            ["GUID"] = "1B94E7E6",
            ["NextDialogue"] = 11017704,
            ["SpeakNpcId"] = 110016,
            ["VoiceName"] = "voice/$Locale$/story/1002/110177/1B94E7E6",
            },
        [11017704] = {
            ["Content"] = "是、是……",
            ["ContentFR"] = "O-Oui...",
            ["DialogueId"] = 11017704,
            ["GUID"] = "1B94E810",
            ["SpeakNpcId"] = 110017,
            ["VoiceName"] = "voice/$Locale$/story/1002/110177/1B94E810",
            },
        [11017705] = {
            ["Content"] = "这股热气是……",
            ["ContentFR"] = "Cette vapeur...",
            ["DialogueId"] = 11017705,
            ["GUID"] = "1B94E83A",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 11017706,
            ["SpeakNpcId"] = 110034,
            ["VoiceName"] = "voice/$Locale$/story/1002/110177/1B94E83A",
            },
        [11017706] = {
            ["Content"] = "当心！前面有一台冷凝机，靠太近的话会受伤的！",
            ["ContentFR"] = "Attention ! Il y a un condenseur devant. Trop près, vous risquez de vous blesser !",
            ["DialogueId"] = 11017706,
            ["GUID"] = "1B94E864",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 110034,
            ["VoiceName"] = "voice/$Locale$/story/1002/110177/1B94E864",
            },
        [11017707] = {
            ["Content"] = "各位长官……冷凝机的蒸汽很危险，千万不要久留。",
            ["ContentFR"] = "Capitaine... La vapeur du condenseur est très dangereuse. Nous ne devons pas y rester trop longtemps.",
            ["DialogueId"] = 11017707,
            ["GUID"] = "1B94E88E",
            ["SpeakNpcId"] = 110017,
            ["VoiceName"] = "voice/$Locale$/story/1002/110177/1B94E88E",
            },
        [11017708] = {
            ["Content"] = "呼、呼……好热……长官，您没事吧？",
            ["ContentFR"] = "Haa... haa... Il fait tellement chaud... Capitaine, vous allez bien ?",
            ["DialogueId"] = 11017708,
            ["GUID"] = "1B94E8B8",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 110034,
            ["VoiceName"] = "voice/$Locale$/story/1002/110177/1B94E8B8",
            },
        [11017709] = {
            ["Content"] = "长官，请走这边……",
            ["ContentFR"] = "Capitaine, par ici...",
            ["DialogueId"] = 11017709,
            ["GUID"] = "1B94E8E2",
            ["NextDialogue"] = 11017710,
            ["SpeakNpcId"] = 110017,
            ["VoiceName"] = "voice/$Locale$/story/1002/110177/1B94E8E2",
            },
        [11017710] = {
            ["Content"] = "秽、秽兽……！",
            ["ContentFR"] = "Des So-Souillés... !",
            ["DialogueId"] = 11017710,
            ["GUID"] = "1B94E90C",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 11017711,
            ["SpeakNpcId"] = 110034,
            ["VoiceName"] = "voice/$Locale$/story/1002/110177/1B94E90C",
            },
        [11017711] = {
            ["Content"] = "平民都退到我身后去。",
            ["ContentFR"] = "Les civils derrière moi.",
            ["DialogueId"] = 11017711,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B94E936",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110177/1B94E936",
            },
        [11017712] = {
            ["Content"] = "谢谢您救了我们！原来也不是所有帝国士兵都……",
            ["ContentFR"] = "Merci de nous avoir sauvés ! Finalement, tous les soldats impériaux ne sont pas...",
            ["DialogueId"] = 11017712,
            ["GUID"] = "1B94E960",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 11017713,
            ["SpeakNpcId"] = 110034,
            ["VoiceName"] = "voice/$Locale$/story/1002/110177/1B94E960",
            },
        [11017713] = {
            ["Content"] = "啊，抱歉！我是说，我曾经以为帝国士兵都和同盟的家伙一样蛮横粗暴，但现在我知道了，不是我想的那样！",
            ["ContentFR"] = "Ah, pardon ! Je voulais dire, je pensais autrefois que les soldats impériaux étaient aussi brutaux que les Déchus. Mais maintenant, je sais que je me trompais !",
            ["DialogueId"] = 11017713,
            ["GUID"] = "1B94E98A",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 110034,
            ["VoiceName"] = "voice/$Locale$/story/1002/110177/1B94E98A",
            },
        [11017714] = {
            ["Content"] = "前面那个是……阿瓦尔长官！",
            ["ContentFR"] = "Là-bas... c’est le Commandant Avar !",
            ["DialogueId"] = 11017714,
            ["GUID"] = "1B94E9B4",
            ["NextDialogue"] = 11017715,
            ["SpeakNpcId"] = 110015,
            ["VoiceName"] = "voice/$Locale$/story/1002/110177/1B94E9B4",
            },
        [11017715] = {
            ["Content"] = "（好，总算是平安会合了。）",
            ["ContentFR"] = "<I>Bien, nous voilà enfin tous réunis et sains et saufs.</>",
            ["DialogueId"] = 11017715,
            ["DisableMouth"] = 1,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B94E9DE",
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110177/1B94E9DE",
            },
        [11017801] = {
            ["Content"] = "停下吧。",
            ["ContentFR"] = "Halte.",
            ["DialogueId"] = 11017801,
            ["GUID"] = "1B94F7FA",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110178/1B94F7FA",
            },
        [11017802] = {
            ["Content"] = "视野不错，就在这儿轰击中央控制室吧。",
            ["ContentFR"] = "Belle vue... C’est l’endroit parfait pour ouvrir le feu sur la salle de commande centrale.",
            ["DialogueId"] = 11017802,
            ["GUID"] = "1B94F824",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110178/1B94F824",
            },
        [11017803] = {
            ["Content"] = "该死……",
            ["ContentFR"] = "Mince...",
            ["DialogueId"] = 11017803,
            ["GUID"] = "1B94F84E",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110178/1B94F84E",
            },
        [11017804] = {
            ["Content"] = "先处理掉秽兽，别让它们干扰到你！",
            ["ContentFR"] = "Occupe-toi des Souillés d’abord ! Ne les laisse pas te gêner !",
            ["DialogueId"] = 11017804,
            ["GUID"] = "1B94F878",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110178/1B94F878",
            },
        [11017805] = {
            ["Content"] = "好，清理干净了。",
            ["ContentFR"] = "Bien. Le secteur est sûr.",
            ["DialogueId"] = 11017805,
            ["GUID"] = "1B94F8A2",
            ["NextDialogue"] = 11017806,
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110178/1B94F8A2",
            },
        [11017806] = {
            ["Content"] = "接下来，就从相对薄弱的<H>侧门</>开始轰击吧。",
            ["ContentFR"] = "Maintenant, concentrons le tir sur la <H>porte latérale</>, elle est plus fragile.",
            ["DialogueId"] = 11017806,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B94F8CC",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110178/1B94F8CC",
            },
        [11017807] = {
            ["Content"] = "不要停，继续轰击！记得用高爆弹。",
            ["ContentFR"] = "Continue ! Utilise les Obus explosifs !",
            ["DialogueId"] = 11017807,
            ["GUID"] = "1B94F8F6",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110178/1B94F8F6",
            },
        [11017808] = {
            ["Content"] = "差不多了！过去看看吧。",
            ["ContentFR"] = "Ça suffit ! Allons-y.",
            ["DialogueId"] = 11017808,
            ["GUID"] = "1B94F920",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110186/1B957C0C",
            },
        [11017809] = {
            ["Content"] = "别发愣啊，快轰！",
            ["ContentFR"] = "Ne reste pas planté là ! Tire !",
            ["DialogueId"] = 11017809,
            ["GUID"] = "1B94F94A",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110178/1B94F94A",
            },
        [11017810] = {
            ["Content"] = "你还好吧？别是哪儿受伤了？",
            ["ContentFR"] = "Tout va bien ? Tu es {性别2:blessé|blessée} ?",
            ["DialogueId"] = 11017810,
            ["GUID"] = "1B94F974",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110178/1B94F974",
            },
        [11017811] = {
            ["Content"] = "等你把这门敲破，我小女儿都变成老奶奶了！回去开炮。",
            ["ContentFR"] = "Si tu continues comme ça, ma fille sera grand-mère avant que tu ne l’aies ouverte ! Retourne au canon.",
            ["DialogueId"] = 11017811,
            ["GUID"] = "1B94F99E",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110178/1B94F99E",
            },
        [11017812] = {
            ["DialogueId"] = 11017812,
            ["GUID"] = "1B94F9C8",
            ["IsBlack"] = 1,
            ["VoiceName"] = "voice/$Locale$/story/1002/110178/1B94F9C8",
            },
        [11017901] = {
            ["Content"] = "去吧，保持联络，听我指示。",
            ["ContentFR"] = "Allez. Restez en contact et soyez prudent.",
            ["DialogueId"] = 11017901,
            ["GUID"] = "1B950862",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110179/1B950862",
            },
        [11017902] = {
            ["Content"] = "维克……",
            ["ContentFR"] = "Vic...",
            ["DialogueId"] = 11017902,
            ["GUID"] = "1B95088C",
            ["SpeakNpcId"] = 110020,
            ["VoiceName"] = "voice/$Locale$/story/1002/110179/1B95088C",
            },
        [11017903] = {
            ["Content"] = "准备好了，就激活髓动轮出发吧。",
            ["ContentFR"] = "Dès que vous êtes {性别2:prêt|prête}, activez les Roues Phoxynamo et on se met en route.",
            ["DialogueId"] = 11017903,
            ["GUID"] = "1B9508B6",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110179/1B9508B6",
            },
        [11018001] = {
            ["Camera"] = "-1102.632935,-197.335449,128.499756,0.000169,-1.399683,12.991217,50.0,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "等一下。",
            ["ContentFR"] = "Attends.",
            ["DialogueId"] = 11018001,
            ["GUID"] = "1B9518CA",
            ["LookAt"] = {
                [1] = "110022:n(110010)",
                [2] = "110034:n(110010)",
                [3] = "110015:n(110010)",
                [4] = "110017:n(110010)",
                },
            ["NextDialogue"] = 11018002,
            ["RelatedWikiId"] = {
                [1] = 204001,
                [2] = 201013,
                [3] = 201015,
                [4] = 408007,
                [5] = 101004,
                },
            ["Scripts"] = "PARA{\
MoveTo{ActorId{110017},MoveSpeed{150},TargetPoint{\"fulankemoVe\"}},\
MoveTo{ActorId{110010},MoveSpeed{150},TargetPoint{\"fix30awa\"}},\
MoveTo{ActorId{110022},MoveSpeed{150},TargetPoint{\"qiannanzhumoVe\"}},\
MoveTo{ActorId{110034},MoveSpeed{150},TargetPoint{\"kajiamoVe\"}}\
}",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110180/1B9518CA",
            },
        [11018002] = {
            ["Camera"] = "436.131592,1.919922,136.800903,0.000139,-1.999415,173.000534,35.0,100000.0,false,Manual,22.0",
            ["Content"] = "接下来的任务容不得出任何错，我们还是得排除风险——小姑娘和老人家不能跟着了。",
            ["ContentFR"] = "À partir de maintenant, aucune erreur n’est permise. On doit éliminer les risques. La fillette et le vieil homme ne nous accompagnent pas plus loin.",
            ["DialogueId"] = 11018002,
            ["GUID"] = "1B9518F4",
            ["LookAt"] = {
                [1] = "110010:n(110034)",
                },
            ["NextDialogue"] = 11018003,
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110180/1B9518F4",
            },
        [11018003] = {
            ["Camera"] = "27.165649,69.382324,136.855469,0.000141,-0.199305,10.000502,35.0,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "……为什么？刚才您也看到了，到处都是秽兽，如果在这里和你们分开，我和爷爷一定会没命的！",
            ["ContentFR"] = "Quoi ? Vous l’avez vu, les Souillés rôdent partout ! Si vous nous laissez ici, Monsieur Frank et moi, on est condamnés !",
            ["DialogueId"] = 11018003,
            ["FacialId"] = {
                [1] = "110034:Sad01",
                },
            ["GUID"] = "1B95191E",
            ["LookAt"] = {
                [1] = "110034:n(110010)",
                [2] = "110022:n(110034)",
                },
            ["NextDialogue"] = 11018004,
            ["Scripts"] = "CameraMoveTo{_delay{8},TargetPosition{\"-263.419067,35.512207,120.94928,0.000142,0.800758,5.202505,30.0,100000.0,false,DoNotOverride,22.0\"},duration{0}}",
            ["SpeakNpcId"] = 110034,
            ["VoiceName"] = "voice/$Locale$/story/1002/110180/1B95191E",
            },
        [11018004] = {
            ["Camera"] = "-143.649597,-86.15332,142.109314,0.000144,-2.799244,26.800621,35.000008,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "长官，我帮过您的！您想，我刚刚给您带路，帮您顺利会合……求求您……求求您不要抛下我们！",
            ["ContentFR"] = "Capitaine, je vous ai aidé ! Je vous ai guidé jusqu’à vos alliés... Je vous en prie... ne nous abandonnez pas !",
            ["DialogueId"] = 11018004,
            ["GUID"] = "1B951948",
            ["LookAt"] = {
                [1] = "110034:n(110022)",
                [2] = "110017:n(110010)",
                },
            ["NextOptions"] = {
                [1] = 11018005,
                [2] = 11018008,
                },
            ["Scripts"] = "LookAt{_delay{1},LookAtDescription{\"110022:n(110034)\"}}",
            ["SpeakNpcId"] = 110034,
            ["VoiceName"] = "voice/$Locale$/story/1002/110180/1B951948",
            },
        [11018005] = {
            ["Content"] = "信任卡嘉",
            ["ContentFR"] = "Faire confiance à Katya",
            ["DialogueId"] = 11018005,
            ["GUID"] = "1B951972",
            ["ImprPlusId"] = 1009,
            ["NextDialogue"] = 11018006,
            },
        [11018006] = {
            ["Camera"] = "-372.804108,82.572754,153.340088,0.000149,-3.999233,-7.999348,50.000011,450.777496,false,DoNotOverride,7.0",
            ["Content"] = "老师也许多虑了。如果他们是敌人，那么在地下水道故意带错路会是更好的选择，但他们没有这么做。",
            ["ContentFR"] = "Commandant, peut-être que vous exagérez. S’ils avaient voulu nous piéger, ils nous auraient perdus dans les égouts. Mais ils ne l’ont pas fait.",
            ["DialogueId"] = 11018006,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B95199C",
            ["LookAt"] = {
                [1] = "110022:n(110010)",
                [2] = "110010:n(110010)",
                },
            ["NextDialogue"] = 11018007,
            ["SpeakNpcId"] = 110022,
            ["TalkActionId"] = {
                [1] = "110022:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110180/1B95199C",
            },
        [11018007] = {
            ["Camera"] = "32.585205,14.534668,146.054871,0.00015,-1.399219,162.798279,50.0,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "如果他们另有打算呢。你不觉得，刚才这一路，他们“过于了解”这座要塞了吗？",
            ["ContentFR"] = "Et s’ils avaient d’autres plans ? Ne trouves-tu pas qu’ils connaissent trop bien cette forteresse ?",
            ["DialogueId"] = 11018007,
            ["GUID"] = "1B9519C6",
            ["LookAt"] = {
                [1] = "110010:n(110022)",
                },
            ["NextDialogue"] = 11018011,
            ["SpeakNpcId"] = 110010,
            ["TalkActionId"] = {
                [1] = "110022:Explain01_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110180/1B9519C6",
            },
        [11018008] = {
            ["Content"] = "不信任卡嘉",
            ["ContentFR"] = "Ne pas faire confiance à Katya",
            ["DialogueId"] = 11018008,
            ["GUID"] = "1B9519F0",
            ["ImprPlusId"] = 1008,
            ["NextDialogue"] = 11018009,
            },
        [11018009] = {
            ["Camera"] = "209.203857,228.964844,146.143616,0.000167,-4.599087,-120.406746,45.000011,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "……我赞同老师的判断。",
            ["ContentFR"] = "... Je suis d’accord avec le Commandant Avar.",
            ["DialogueId"] = 11018009,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B951A1A",
            ["LookAt"] = {
                [1] = "110022:n(110034)",
                },
            ["NextDialogue"] = 11018010,
            ["Scripts"] = "SetRotation{SetRotationDescription{\"110022:n(110034)\"}}",
            ["SpeakNpcId"] = 110022,
            ["TalkActionId"] = {
                [1] = "110022:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110180/1B951A1A",
            },
        [11018010] = {
            ["Camera"] = "-127.301941,-114.787598,142.109314,0.000143,-1.599302,31.20196,35.0,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "如果是进中央控制室之前，我还可以勉强信任你；但是现在看来你似乎“过于了解”这座要塞了。",
            ["ContentFR"] = "J’aurais pu vous faire confiance si nous n’étions pas entrés dans la salle de commande. Mais maintenant, j’ai l'impression que vous connaissez trop bien cette forteresse.",
            ["DialogueId"] = 11018010,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B951A44",
            ["LookAt"] = {
                [1] = "110010:n(110022)",
                [2] = "110022:n(110034)",
                },
            ["NextDialogue"] = 11018011,
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110180/1B951A44",
            },
        [11018011] = {
            ["Camera"] = "414.556763,7.735352,138.894348,0.000155,-2.599324,169.392776,50.000008,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "中央控制室是龙莎要塞的中枢，就算是同盟，也不会允许路边随便抓来的苦力来这种核心区域闲逛。",
            ["ContentFR"] = "Exact. La salle de commande est le cœur de la Forteresse de Lonza. Même les Déchus ne laisseraient pas de simples esclaves traîner dans un lieu pareil.",
            ["DialogueId"] = 11018011,
            ["GUID"] = "1B951A6E",
            ["LookAt"] = {
                [1] = "110010:n(110010)",
                },
            ["NextDialogue"] = 11018012,
            ["SpeakNpcId"] = 110010,
            ["TurnTo"] = {
                [1] = "110022:n(110010)",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110180/1B951A6E",
            },
        [11018012] = {
            ["Content"] = "你不该对里面的路线也如此轻车熟路。",
            ["ContentFR"] = "Et toi, petite, tu ne devrais pas en connaître le plan comme ta poche.",
            ["DialogueId"] = 11018012,
            ["GUID"] = "1B951A98",
            ["LookAt"] = {
                [1] = "110010:n(110034)",
                },
            ["NextDialogue"] = 11018013,
            ["SpeakNpcId"] = 110010,
            ["TalkActionId"] = {
                [1] = "110010:Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110180/1B951A98",
            },
        [11018013] = {
            ["Camera"] = "-38.761108,62.896484,133.47168,0.000157,0.600497,8.994007,50.000008,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "呃……那是因为——",
            ["ContentFR"] = "Je... c’est parce que—",
            ["DialogueId"] = 11018013,
            ["GUID"] = "1B951AC2",
            ["LookAt"] = {
                [1] = "110034:n(110010)",
                },
            ["NextDialogue"] = 11018014,
            ["SpeakNpcId"] = 110034,
            ["TalkActionId"] = {
                [1] = "110022:Explain01_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110180/1B951AC2",
            },
        [11018014] = {
            ["Camera"] = "528.188843,-8.837402,130.242065,0.000159,-1.599541,172.787582,50.000008,824.380615,false,Manual,10.0",
            ["Content"] = "小姑娘，这么喜欢演戏，还是去皇都的大剧院演吧。",
            ["ContentFR"] = "Si tu aimes tant jouer la comédie, va donc au Grand Théâtre de la capitale impériale.",
            ["DialogueId"] = 11018014,
            ["GUID"] = "1B951AEC",
            ["LookAt"] = {
                [1] = "110010:n(110010)",
                },
            ["NextDialogue"] = 11018015,
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110180/1B951AEC",
            },
        [11018015] = {
            ["Camera"] = "-1102.632935,-197.335449,128.499756,0.000169,-1.399683,12.991217,50.0,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "时间不多了，我们走。莱昂，留下来看好他们。",
            ["ContentFR"] = "Assez perdu de temps. On avance. Leon, tu restes ici pour les surveiller.",
            ["DialogueId"] = 11018015,
            ["GUID"] = "1B951B16",
            ["SpeakNpcId"] = 110010,
            ["TalkActionId"] = {
                [1] = "110010:Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110180/1B951B16",
            },
        [11018101] = {
            ["Content"] = "年轻的士兵半倚着冰冷的墙壁，已经没了气息。一道巨大的爪痕穿过他的胸口，将他贯穿。在刚刚的巨型秽兽面前，普通人类的力量太微弱了。",
            ["ContentFR"] = "Le jeune soldat repose contre le mur froid, sans vie. Une énorme trace de griffes traverse son torse. Face à ce Souillé, un humain ordinaire n’avait aucune chance.",
            ["DialogueId"] = 11018101,
            ["GUID"] = "1B952932",
            ["VoiceName"] = "voice/$Locale$/story/1002/110181/1B952932",
            },
        [11018102] = {
            ["Content"] = "（……安息。）",
            ["ContentFR"] = "<I>... Repose en paix.</>",
            ["DialogueId"] = 11018102,
            ["DisableMouth"] = 1,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B95295C",
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110181/1B95295C",
            },
        [11018201] = {
            ["Content"] = "先解决那个神弃者！这群秽兽受他操弄！",
            ["ContentFR"] = "Commence par éliminer ce Déchu ! C’est lui qui manipule ces Souillés !",
            ["DialogueId"] = 11018201,
            ["GUID"] = "1B95399A",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110182/1B95399A",
            },
        [11018202] = {
            ["Content"] = "维克，莫妮卡，撑住……我们很快就到。",
            ["ContentFR"] = "Vic, Monica... tenez bon. Nous arrivons.",
            ["DialogueId"] = 11018202,
            ["GUID"] = "1B9539C4",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110182/1B9539C4",
            },
        [11018203] = {
            ["Content"] = "（好，关停了。去找其他几台髓动轮吧。）",
            ["DialogueId"] = 11018203,
            ["DisableMouth"] = 1,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B9539EE",
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110182/1B9539EE",
            },
        [11018204] = {
            ["Content"] = "男人崭新的军装被撕碎，透过褴褛的布条，无数爪迹和齿痕清晰可辨；显然，他是被相当数量的秽兽撕咬致死的。他指节青白的手仍紧紧握着断刃，似是最后一刻仍在与群兽角力。",
            ["ContentFR"] = "L’uniforme de l’homme, flambant neuf, est en lambeaux. Sous le tissu déchiré, les griffures et morsures sont nombreuses. Il a clairement été déchiqueté par une horde de Souillés. Ses mains crispées sur la lame brisée témoignent qu’il s’est battu jusqu’au bout.",
            ["DialogueId"] = 11018204,
            ["GUID"] = "1B953A18",
            ["NextDialogue"] = 11018205,
            ["VoiceName"] = "voice/$Locale$/story/1002/110182/1B953A18",
            },
        [11018205] = {
            ["Content"] = "在他的身旁静静地躺着一枚铭牌，你认得出来，那是军团为每一位新兵颁发的铭牌。铭牌的正面是他的名字，维克·吉拉德。背面则用小刀刻着一行小字：“莫妮卡，下次射击比赛我一定会赢过你。”",
            ["ContentFR"] = "À côté de lui, une plaque d’identité repose silencieusement. Tu la reconnais immédiatement : standard pour les nouvelles recrues. Au recto, son nom : Vic Girard. Au verso, un message gravé au couteau : « Monica, la prochaine fois, je te bats au concours de tir. »",
            ["DialogueId"] = 11018205,
            ["GUID"] = "1B953A42",
            ["VoiceName"] = "voice/$Locale$/story/1002/110182/1B953A42",
            },
        [11018206] = {
            ["Content"] = "（月髓舱炸毁后，这些机关都瘫痪了。）",
            ["ContentFR"] = "<I>On dirait que la destruction du réservoir Phoxichor a tout mis hors service.</>",
            ["DialogueId"] = 11018206,
            ["DisableMouth"] = 1,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B953A6C",
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110182/1B953A6C",
            },
        [11018207] = {
            ["Content"] = "就是这些畜生……把大家……",
            ["ContentFR"] = "Ces monstres... ce sont eux qui... !",
            ["DialogueId"] = 11018207,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B953A96",
            ["NextDialogue"] = 11018208,
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110182/1B953A96",
            },
        [11018208] = {
            ["Content"] = "<W>不错，正是如此。仇恨刺痛着你的心脏，你从未如此渴求着鲜血。</>",
            ["ContentFR"] = "<W>Oui... exactement. Laisse la haine brûler ton cœur. Tu n’as jamais désiré le sang comme aujourd’hui.</>",
            ["DialogueId"] = 11018208,
            ["DisableMouth"] = 1,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B953AC0",
            ["NextDialogue"] = 11018209,
            ["SnapShot"] = "MONSTER",
            ["VoiceName"] = "voice/$Locale$/story/1002/110182/1B953AC0",
            },
        [11018209] = {
            ["Content"] = "<W>你只恨这些怪物无血无泪，它们无法感受你的愤怒与悲辛。</>",
            ["ContentFR"] = "<W>Ils ne pleurent pas. Ils ne sentent rien. Mais toi, tu veux leur faire payer...</>",
            ["DialogueId"] = 11018209,
            ["DisableMouth"] = 1,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B953AEA",
            ["NextDialogue"] = 11018210,
            ["SnapShot"] = "MONSTER",
            ["VoiceName"] = "voice/$Locale$/story/1002/110182/1B953AEA",
            },
        [11018210] = {
            ["Content"] = "<W>但是没有关系，你只需要挥剑、挥剑、挥剑——</>",
            ["ContentFR"] = "<W>Alors frappe. Encore... et encore... et encore...</>",
            ["DialogueId"] = 11018210,
            ["DisableMouth"] = 1,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B953B14",
            ["NextDialogue"] = 11018211,
            ["SnapShot"] = "MONSTER",
            ["VoiceName"] = "voice/$Locale$/story/1002/110182/1B953B14",
            },
        [11018211] = {
            ["Content"] = "（……不行！）",
            ["ContentFR"] = "<I>Non ! Je ne peux pas...</>",
