            },
        [11018301] = {
            ["Content"] = "坚持住，队长就快来了！",
            ["ContentFR"] = "Tenez bon, {性别2:le|la} capitaine arrive !",
            ["DialogueId"] = 11018301,
            ["GUID"] = "1B954A02",
            ["SpeakNpcId"] = 110016,
            ["VoiceName"] = "voice/$Locale$/story/1002/110183/1B954A02",
            },
        [11018302] = {
            ["Content"] = "神弃者同盟的人改造要塞要苦力，就派人到我们镇子，把我们强行绑过来。他们甚至不要索拉之民，而是专挑我们卡戎之民……",
            ["ContentFR"] = "Quand ils ont eu besoin d’ouvriers, ils nous ont arrachés à nos foyers et nous ont forcés à aider à reconstruire cette forteresse. Ils ont laissé les Solariens en paix et n’ont emmené que les Charons...",
            ["DialogueId"] = 11018302,
            ["FacialId"] = {
                [1] = "110034:Sad01",
                },
            ["GUID"] = "1B954A2C",
            ["NextDialogue"] = 11011824,
            ["RelatedWikiId"] = {
                [1] = 201015,
                },
            ["SpeakNpcId"] = 110034,
            ["VoiceName"] = "voice/$Locale$/story/1002/110183/1B954A2C",
            },
        [11018401] = {
            ["Camera"] = "-274.711914,194.082031,124.856079,0.00015,-1.800322,-91.197739,35.000008,229.080856,false,Manual,2.8",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "没错，仅仅因为我们比索拉之民力气更大，更不怕严寒暑热——也许在您的眼中我们是同类，但同盟从未把我们当过“同胞”。",
            ["ContentFR"] = "Exactement. Ils nous exploitent parce que les Charons sont plus forts et résistent mieux aux températures extrêmes que les Solariens. Vous pensez peut-être que nous sommes comme les Déchus, mais ils ne nous ont jamais acceptés comme les leurs.",
            ["DialogueId"] = 11018401,
            ["FacialId"] = {
                [1] = "110034:None",
                },
            ["FinalCamera"] = "-275.310547,165.044922,123.943848,0.00015,-1.800322,-91.197739,35.000008,208.205566,false,Manual,2.8",
            ["GUID"] = "1B955A6A",
