        [11018806] = {
            ["Content"] = "（我真的要按下这个按钮吗？）",
            ["ContentFR"] = "<I>Suis-je vraiment en train d’envisager d’appuyer là-dessus ?</>",
            ["DialogueId"] = 11018806,
