            },
        [11018906] = {
            ["Camera"] = "-20.442005,40.117725,126.334839,0.000017,-0.000307,6.615975,50.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "……都是被一发子弹击中的，没有挣扎或抵抗痕迹。",
            ["ContentFR"] = "... Une seule balle chacun. Pas de lutte, aucune trace de résistance.",
