            ["VoiceName"] = "voice/$Locale$/story/1002/110189/1B95AD44",
            },
        [11018907] = {
            ["Camera"] = "-20.442005,40.117725,126.334839,0.000017,-0.000307,6.615975,50.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "他们是被信任的人杀害的……看血迹，是我们被困在中央控制室的时候……富尔维斯这混蛋……",
            ["ContentFR"] = "Ils ont été tués par quelqu’un en qui ils avaient confiance... D’après les traces de sang, ça a dû se passer pendant qu’on était piégés dans la salle centrale... Ce traître de Fulvis...",
            ["DialogueId"] = 11018907,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["FinalCamera"] = "-27.532495,36.781734,125.492981,0.000016,5.199693,15.214883,50.0,100000.0,false,DoNotOverride,2.8",
