        [11018910] = {
            ["Content"] = "秘钥不在他身上，继续找。",
            ["ContentFR"] = "Rien sur lui. On continue.",
            ["DialogueId"] = 11018910,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B95ADEC",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110189/1B95ADEC",
            },
        [11018911] = {
            ["Content"] = "还是不对……",
            ["ContentFR"] = "Toujours rien...",
            ["DialogueId"] = 11018911,
            ["GUID"] = "1B95AE16",
            ["SpeakNpcId"] = 110005,
            ["VoiceName"] = "voice/$Locale$/story/1002/110189/1B95AE16",
            },
        [11018912] = {
            ["Content"] = "找到秘钥了，在这里！",
            ["ContentFR"] = "Trouvé ! La clé est là !",
            ["DialogueId"] = 11018912,
            ["Duration"] = 3,
            ["GUID"] = "1B95AE40",
            ["SpeakNpcId"] = 110005,
            ["VoiceName"] = "voice/$Locale$/story/1002/110189/1B95AE40",
            },
        [11018913] = {
            ["Content"] = "走！",
            ["ContentFR"] = "Vite, allons-y !",
            ["DialogueId"] = 11018913,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B95AE6A",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110189/1B95AE6A",
            },
        [11018914] = {
            ["Content"] = "水位一直在上涨，必须赶在被淹没之前离开这儿！",
            ["ContentFR"] = "Le niveau de l’eau ne cesse de monter, il faut sortir avant d’être engloutis !",
            ["DialogueId"] = 11018914,
            ["GUID"] = "1B95AE94",
            ["SpeakNpcId"] = 110005,
            ["VoiceName"] = "voice/$Locale$/story/1002/110189/1B95AE94",
            },
        [11018915] = {
            ["Content"] = "这里刻着使用说明：“同时开启储水池外围的三个辅助水阀可加速排水……”",
            ["ContentFR"] = "Ici, c’est gravé : « Ouvrir simultanément les trois vannes auxiliaires autour du réservoir accélérera la vidange... »",
            ["DialogueId"] = 11018915,
            ["GUID"] = "1B95AEBE",
            ["NextDialogue"] = 11014803,
            ["SpeakNpcId"] = 110005,
            ["VoiceName"] = "voice/$Locale$/story/1002/110189/1B95AEBE",
            },
        [11018916] = {
            ["Content"] = "好，可以出去了……",
            ["ContentFR"] = "Parfait, on peut sortir d’ici...",
            ["DialogueId"] = 11018916,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B95AEE8",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110189/1B95AEE8",
            },
        [11018917] = {
            ["Content"] = "他们……要烧毁这里？",
            ["ContentFR"] = "Ils... vont tout réduire en cendres... ?",
            ["DialogueId"] = 11018917,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B95AC72",
            ["NextDialogue"] = 11018902,
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110189/1B95AC72",
            },
        [11019005] = {
            ["Camera"] = "14.98733,-14.154265,30.628906,0.000071,5.795005,178.84024,45.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "海尔法典狱长，我一直在等待你亲自审问。这些真相，我必须亲口讲给你听。",
            ["ContentFR"] = "Geôlière Vulcera, j’attendais votre interrogatoire. Il fallait que je vous dise la vérité en face.",
            ["DialogueId"] = 11019005,
            ["Duration"] = 7,
            ["ExStoryInfo"] = "EXPlayer",
            ["FinalCamera"] = "2.373075,-13.902337,31.914062,0.000071,5.795005,178.84024,45.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "1B95BD82",
            ["NextDialogue"] = 11015315,
            ["SpeakNpcId"] = 110022,
            ["TalkActionId"] = {
                [1] = "110039:Sit_Talk02_End",
                },
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95BD82",
            },
        [11019006] = {
            ["Content"] = "想起来了……刚刚是，典狱长在说……“审讯”……",
            ["ContentFR"] = "Ça me revient... tout à l’heure, la geôlière parlait... d’un interrogatoire...",
            ["DialogueId"] = 11019006,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B95BDAC",
            ["NextDialogue"] = 11019007,
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95BDAC",
            },
        [11019007] = {
            ["Content"] = "那位审讯官提到了“催眠药剂”……",
            ["ContentFR"] = "Cet interrogateur a aussi évoqué... un sérum hypnotique...",
            ["DialogueId"] = 11019007,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B95BDD6",
            ["NextDialogue"] = 11019008,
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95BDD6",
            },
        [11019008] = {
            ["Content"] = "这里……应该不是真实的世界。我想我现在正在梦中。",
            ["ContentFR"] = "Alors... cet endroit... ce n’est sans doute pas le monde réel. Je dois être... en plein rêve.",
            ["DialogueId"] = 11019008,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B95BE00",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95BE00",
            },
        [11019009] = {
            ["Content"] = "（“老师”和“达芙涅”都消失了……）",
            ["ContentFR"] = "<I>\"Commandant Avar\"... et \"Daphne\"... ils ont disparu...</>",
            ["DialogueId"] = 11019009,
            ["DisableMouth"] = 1,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B95BE2A",
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95BE2A",
            },
        [11019010] = {
            ["Content"] = "（神弃者同盟……？）",
            ["ContentFR"] = "<I>Les... Déchus ?</>",
            ["DialogueId"] = 11019010,
            ["DisableMouth"] = 1,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B95BE54",
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95BE54",
            },
        [11019011] = {
            ["Content"] = "先遣小队全军覆没。",
            ["ContentFR"] = "Les escouades d’avant-garde sont anéanties.",
            ["DialogueId"] = 11019011,
            ["GUID"] = "1B95BE7E",
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95BE7E",
            },
        [11019012] = {
            ["Content"] = "干得漂亮，朋友。",
            ["ContentFR"] = "Beau travail, mon ami.",
            ["DialogueId"] = 11019012,
            ["GUID"] = "1B95BEA8",
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95BEA8",
            },
        [11019013] = {
            ["Content"] = "这就是军团狗应得的下场。",
            ["ContentFR"] = "Voilà le sort que méritaient ces chiens de l’Empire.",
            ["DialogueId"] = 11019013,
            ["GUID"] = "1B95BED2",
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95BED2",
            },
        [11019014] = {
            ["Content"] = "为我们的合作干杯！",
            ["ContentFR"] = "À notre fructueuse alliance !",
            ["DialogueId"] = 11019014,
            ["GUID"] = "1B95BEFC",
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95BEFC",
            },
        [11019015] = {
            ["Content"] = "一起庆祝吧，亲爱的~",
            ["ContentFR"] = "À la tienne",
            ["DialogueId"] = 11019015,
            ["GUID"] = "1B95BF26",
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95BF26",
            },
        [11019016] = {
            ["Content"] = "……从我的梦里滚出去。",
            ["ContentFR"] = "... Dégagez de mon rêve.",
            ["DialogueId"] = 11019016,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B95BF50",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95BF50",
            },
        [11019017] = {
            ["Camera"] = "-4.504883,1095.012207,226.371094,-0.000824,-13.200255,-89.031578,17.134987,100000.0,false,Manual,22.0",
            ["Content"] = "第一个问题，作为帝国的士兵，你是否背叛了帝国？",
            ["ContentFR"] = "Première question : en tant que soldat impérial, as-tu {性别2:trahi|trahie} l’Empire en livrant des informations aux Déchus ?",
            ["DialogueId"] = 11019017,
            ["Duration"] = 3,
            ["GUID"] = "1B95BF7A",
            ["NextDialogue"] = 11019018,
            ["SnapShot"] = "MONSTER",
            ["SpeakNpcId"] = 110032,
            ["SpeakNpcName"] = "UI_Npc_Wardenry",
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95BF7A",
            },
        [11019018] = {
            ["Content"] = "若你背叛了帝国的正义，就被秽兽的利爪撕碎！",
            ["ContentFR"] = "Si tu trahis la justice de l’Empire, ces Souillés te déchireront de leurs griffes !",
            ["DialogueId"] = 11019018,
            ["Duration"] = 3,
            ["GUID"] = "1B95BFA4",
            ["NextDialogue"] = 11019019,
            ["SnapShot"] = "MONSTER",
            ["SpeakNpcId"] = 110032,
            ["SpeakNpcName"] = "UI_Npc_Wardenry",
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95BFA4",
            },
        [11019019] = {
            ["Content"] = "（……这个问题很容易回答。）",
            ["ContentFR"] = "<I>... Cette question est facile.</>",
            ["DialogueId"] = 11019019,
            ["DisableMouth"] = 1,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B95BFCE",
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95BFCE",
            },
        [11019020] = {
            ["Content"] = "（呃——！身体突然变得好沉重……我不该承认那些指控。）",
            ["ContentFR"] = "<I>Argh ! Mon corps... devient si lourd... je n’aurais pas dû avouer ces accusations...</>",
            ["DialogueId"] = 11019020,
            ["DisableMouth"] = 1,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B95BFF8",
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95BFF8",
            },
        [11019021] = {
            ["Content"] = "（为什么这里也有秽兽……！）",
            ["ContentFR"] = "<I>Pourquoi il y a des Souillés ici... !?</>",
            ["DialogueId"] = 11019021,
            ["DisableMouth"] = 1,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B95C022",
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95C022",
            },
        [11019022] = {
            ["Content"] = "（不……冷静下来。它们不过是虚影而已。）",
            ["ContentFR"] = "<I>Non... reste calme. Ce ne sont que des illusions.</>",
            ["DialogueId"] = 11019022,
            ["DisableMouth"] = 1,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B95C04C",
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95C04C",
            },
        [11019023] = {
            ["Content"] = "（没错。绝不能承认那些指控。）",
            ["ContentFR"] = "<I>C’est ça. Je ne vais pas avouer un mensonge.</>",
            ["DialogueId"] = 11019023,
            ["DisableMouth"] = 1,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B95C076",
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95C076",
            },
        [11019024] = {
            ["Content"] = "（秽兽……）",
            ["ContentFR"] = "<I>Des Souillés...</>",
            ["DialogueId"] = 11019024,
            ["DisableMouth"] = 1,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B95C0A0",
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95C0A0",
            },
        [11019025] = {
            ["Content"] = "（不，它们只是虚影而已……）",
            ["ContentFR"] = "<I>Non... ce ne sont que des illusions.</>",
            ["DialogueId"] = 11019025,
            ["DisableMouth"] = 1,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B95C0CA",
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95C0CA",
            },
        [11019026] = {
            ["Camera"] = "-13.981445,564.373535,123.75,0.00011,3.399125,89.793884,17.134987,100000.0,false,Manual,22.0",
            ["Content"] = "第二个问题，龙莎一役中，先遣队伍全军覆没，是否与你有关？",
            ["ContentFR"] = "Deuxième question : lors de la bataille de la Forteresse de Lonza, les avant-gardes ont été anéanties. Cela a-t-il un lien avec toi ?",
            ["DialogueId"] = 11019026,
            ["GUID"] = "1B95C0F4",
            ["NextDialogue"] = 11019027,
            ["SnapShot"] = "MONSTER",
            ["SpeakNpcId"] = 110032,
            ["SpeakNpcName"] = "UI_Npc_Wardenry",
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95C0F4",
            },
        [11019027] = {
            ["Camera"] = "-4.504883,1095.012207,226.371094,-0.000824,-13.200255,-89.031578,17.134987,100000.0,false,Manual,22.0",
            ["Content"] = "若你背弃了同胞的正义，就溅血于自己的锋刃！",
            ["ContentFR"] = "Si tu trahis la justice de tes camarades, ta propre lame répandra ton sang !",
            ["DialogueId"] = 11019027,
            ["GUID"] = "1B95C11E",
            ["NextDialogue"] = 11019028,
            ["SnapShot"] = "MONSTER",
            ["SpeakNpcId"] = 110032,
            ["SpeakNpcName"] = "UI_Npc_Wardenry",
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95C11E",
            },
        [11019028] = {
            ["Camera"] = "13.287109,114.423828,114.03125,-0.000825,14.198904,-86.82589,17.134987,100000.0,false,Manual,22.0",
            ["Content"] = "（无需迷惘，坚定地做出选择吧。）",
            ["ContentFR"] = "<I>Pas de doute. Je dois choisir avec conviction.</>",
            ["DialogueId"] = 11019028,
            ["DisableMouth"] = 1,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B95C148",
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95C148",
            },
        [11019029] = {
            ["Content"] = "（呃——！身体突然变得好沉重……我不该承认那些指控。）",
            ["ContentFR"] = "<I>Argh ! Mon corps... devient si lourd... je n’aurais pas dû avouer ces accusations...</>",
            ["DialogueId"] = 11019029,
            ["DisableMouth"] = 1,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B95C172",
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95C172",
            },
        [11019030] = {
            ["Content"] = "（你是……谁？！）",
            ["ContentFR"] = "<I>Qui es-tu... ?</>",
            ["DialogueId"] = 11019030,
            ["DisableMouth"] = 1,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B95C19C",
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95C19C",
            },
        [11019031] = {
            ["Content"] = "（不……{性别2：他|她}不是我。）",
            ["ContentFR"] = "<I>Non... ce n’est pas moi.</>",
            ["DialogueId"] = 11019031,
            ["DisableMouth"] = 1,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B95C1C6",
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95C1C6",
            },
        [11019032] = {
            ["Content"] = "（是的，我必须走出这里，把真相……）",
            ["ContentFR"] = "<I>Oui... je dois continuer... la vérité doit éclater...</>",
            ["DialogueId"] = 11019032,
            ["DisableMouth"] = 1,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B95C1F0",
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95C1F0",
            },
        [11019033] = {
            ["Content"] = "（你不是我。你只是一个愚蠢的赝品。）",
            ["ContentFR"] = "<I>Tu n’es pas moi. Tu n’es qu’une vulgaire imitation.</>",
            ["DialogueId"] = 11019033,
            ["DisableMouth"] = 1,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B95C21A",
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95C21A",
            },
        [11019034] = {
            ["Content"] = "消失吧。",
            ["ContentFR"] = "Disparais.",
            ["DialogueId"] = 11019034,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B95C244",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95C244",
            },
        [11019035] = {
            ["Content"] = "（前面好像走不通了……要回头吗？）",
            ["ContentFR"] = "<I>Le passage est bloqué... dois-je faire demi-tour ?</>",
            ["DialogueId"] = 11019035,
            ["DisableMouth"] = 1,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B95C26E",
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95C26E",
            },
        [11019036] = {
            ["Content"] = "坚称无罪之人，你会因愤怒动摇吗？",
            ["ContentFR"] = "Toi qui prétends être {性别2:innocent|innocente}... vacilleras-tu sous la colère ?",
            ["DialogueId"] = 11019036,
            ["GUID"] = "1B95C298",
            ["SpeakNpcId"] = 110032,
            ["SpeakNpcName"] = "UI_Npc_Wardenry",
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95C298",
            },
        [11019037] = {
            ["Content"] = "善后得怎么样了？",
            ["ContentFR"] = "Le nettoyage, c’est fait ?",
            ["DialogueId"] = 11019037,
            ["GUID"] = "1B95C2C2",
            ["NextDialogue"] = 11019038,
            ["SpeakNpcId"] = 110011,
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95C2C2",
            },
        [11019038] = {
            ["Content"] = "干干净净，如您所见。",
            ["ContentFR"] = "Impeccable. Comme vous pouvez le voir.",
            ["DialogueId"] = 11019038,
            ["GUID"] = "1B95C2EC",
            ["SpeakNpcId"] = 110012,
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95C2EC",
            },
        [11019039] = {
            ["Content"] = "（是他们两个……！）",
            ["ContentFR"] = "<I>Ce sont eux... Fulvis et Falsi !</>",
            ["DialogueId"] = 11019039,
            ["DisableMouth"] = 1,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B95C316",
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95C316",
            },
        [11019040] = {
            ["Content"] = "坚称无罪之人，你会因悲哀动摇吗？",
            ["ContentFR"] = "Toi qui prétends être {性别2:innocent|innocente}... vacilleras-tu sous le chagrin ?",
            ["DialogueId"] = 11019040,
            ["GUID"] = "1B95C340",
            ["SpeakNpcId"] = 110032,
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95C340",
            },
        [11019041] = {
            ["Content"] = "{nickname2}，我的学生……",
            ["ContentFR"] = "{nickname2}... mon élève...",
            ["DialogueId"] = 11019041,
            ["GUID"] = "1B95C36A",
            ["NextDialogue"] = 11019042,
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95C36A",
            },
        [11019042] = {
            ["Content"] = "阿瓦尔老师？！",
            ["ContentFR"] = "Commandant Avar !",
            ["DialogueId"] = 11019042,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B95C394",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95C394",
            },
        [11019043] = {
            ["Content"] = "唔——！",
            ["ContentFR"] = "Argh !",
            ["DialogueId"] = 11019043,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B95C3BE",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95C3BE",
            },
        [11019044] = {
            ["Content"] = "（这是一张全然陌生的脸。）",
            ["ContentFR"] = "<I>Ce visage... je ne le connais pas.</>",
            ["DialogueId"] = 11019044,
            ["GUID"] = "1B95C3E8",
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95C3E8",
            },
        [11019045] = {
            ["Content"] = "坚称无罪之人，你会因迷惘动摇吗？",
            ["ContentFR"] = "Toi qui prétends être {性别2:innocent|innocente}... vacilleras-tu sous le poids du doute ?",
            ["DialogueId"] = 11019045,
            ["GUID"] = "1B95C412",
            ["NextDialogue"] = 11019046,
            ["SpeakNpcId"] = 110032,
            ["SpeakNpcName"] = "UI_Npc_Wardenry",
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95C412",
            },
        [11019046] = {
            ["Content"] = "亲爱的长官，我来为您指路……",
            ["ContentFR"] = "{性别2:Mon cher capitaine|Ma chère capitaine}... je vais vous montrer le chemin...",
            ["DialogueId"] = 11019046,
            ["GUID"] = "1B95C43C",
            ["NextDialogue"] = 11019047,
            ["SpeakNpcId"] = 110009,
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95C43C",
            },
        [11019047] = {
            ["Content"] = "是……通向地狱的路……",
            ["ContentFR"] = "Oui... le chemin vers l’enfer...",
            ["DialogueId"] = 11019047,
            ["GUID"] = "1B95C466",
            ["SpeakNpcId"] = 110009,
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95C466",
            },
        [11019048] = {
            ["Content"] = "典狱长大人，够了……！请停下吧！",
            ["ContentFR"] = "Assez, Madame la Geôlière... ! Arrêtez !",
            ["DialogueId"] = 11019048,
            ["GUID"] = "1B95C490",
            ["NextDialogue"] = 11019049,
            ["SpeakNpcId"] = 110005,
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95C490",
            },
        [11019049] = {
            ["Content"] = "{nickname2}，请跟我来，我带您离开这里！",
            ["ContentFR"] = "{nickname2}, suivez-moi, je vais vous sortir d’ici !",
            ["DialogueId"] = 11019049,
            ["GUID"] = "1B95C4BA",
            ["SpeakNpcId"] = 110005,
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95C4BA",
            },
        [11019050] = {
            ["Content"] = "无论前方等待您的是什么……请记得……",
            ["ContentFR"] = "Quoi qu’il arrive... souvenez-vous...",
            ["DialogueId"] = 11019050,
            ["GUID"] = "1B95C4E4",
            ["SpeakNpcId"] = 110005,
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95C4E4",
            },
        [11019051] = {
            ["Content"] = "我会和您一起活下去！",
            ["ContentFR"] = "Nous survivrons à cela, ensemble !",
            ["DialogueId"] = 11019051,
            ["GUID"] = "1B95C50E",
            ["SpeakNpcId"] = 110005,
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95C50E",
            },
        [11019052] = {
            ["Content"] = "（这就是她对我意志的最后试炼了。）",
            ["ContentFR"] = "<I>C’est donc cela... l’ultime épreuve de ma volonté.</>",
            ["DialogueId"] = 11019052,
            ["DisableMouth"] = 1,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B95C538",
            ["NextDialogue"] = 11019053,
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95C538",
            },
        [11019053] = {
            ["Content"] = "（必须撑过这场审判的梦……必须把真相亲口告诉她！）",
            ["ContentFR"] = "<I>Je dois survivre... Je dois lui dire la vérité en face !</>",
            ["DialogueId"] = 11019053,
            ["DisableMouth"] = 1,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B95C562",
            ["NextDialogue"] = 11019054,
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95C562",
            },
        [11019054] = {
            ["Content"] = "坚称无罪之人，若你仍不曾动摇，就把胸中意志熔铸成锋刃——",
            ["ContentFR"] = "Toi qui prétends être {性别2:innocent|innocente}... si ta détermination est toujours intacte, transforme cette volonté en lame...",
            ["DialogueId"] = 11019054,
            ["DisableMouth"] = 1,
            ["GUID"] = "1B95C58C",
            ["NextDialogue"] = 11019055,
            ["SnapShot"] = "MONSTER",
            ["SpeakNpcId"] = 110032,
            ["SpeakNpcName"] = "UI_Npc_Wardenry",
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95C58C",
            },
        [11019055] = {
            ["Content"] = "用你手中的剑回答我！",
            ["ContentFR"] = "Et réponds-moi de ton épée !",
            ["DialogueId"] = 11019055,
            ["DisableMouth"] = 1,
            ["GUID"] = "1B95C5B6",
            ["SnapShot"] = "MONSTER",
            ["SpeakNpcId"] = 110032,
            ["SpeakNpcName"] = "UI_Npc_Wardenry",
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95C5B6",
            },
        [11019056] = {
            ["Content"] = "是",
            ["ContentFR"] = "Oui",
            ["DialogueId"] = 11019056,
            ["GUID"] = "1B95C5E0",
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95C5E0",
            },
        [11019057] = {
            ["Content"] = "否",
            ["ContentFR"] = "Non",
            ["DialogueId"] = 11019057,
            ["GUID"] = "1B95C60A",
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95C60A",
            },
        [11019101] = {
            ["Content"] = "决不能让士兵们冤屈的哭号，永远在龙莎要塞上空徘徊。",
            ["ContentFR"] = "Nous ne pouvons pas laisser les cris des soldats injustement sacrifiés résonner éternellement dans la Forteresse de Lonza.",
            ["DialogueId"] = 11019101,
            ["GUID"] = "1B95CD42",
            ["SpeakNpcId"] = 110005,
            ["VoiceName"] = "voice/$Locale$/story/1002/110191/1B95CD42",
            },
        [11019102] = {
            ["Camera"] = "582.071289,-479.369141,593.910156,-0.000856,-38.992104,162.400696,15.284281,100000.0,false,Manual,22.0",
            ["Content"] = "所以，我们选择用这种方式来见你。",
            ["ContentFR"] = "Voilà pourquoi nous sommes venus à vous.",
            ["DialogueId"] = 11019102,
            ["ExStoryInfo"] = "EXPlayer",
            ["FinalCamera"] = "476.848633,-672.017578,593.910156,-0.000855,-39.992191,138.000839,15.284281,100000.0,false,Manual,22.0",
            ["GUID"] = "1B95CD6C",
            ["NextDialogue"] = 11019103,
            ["SpeakNpcId"] = 110022,
            ["ToFinalCameraBlendTime"] = 25,
            ["VoiceName"] = "voice/$Locale$/story/1002/110191/1B95CD6C",
            },
        [11019103] = {
            ["Content"] = "富尔维斯陷害阿瓦尔真正的目的，是排除帝国高层的卡戎之民。你明白，如果他的计划得逞，对帝国，以及对<H>你本人</>而言又意味着什么。",
            ["ContentFR"] = "Le véritable but de Fulvis, en accusant Avar, était d’écarter les Charons des hautes sphères impériales. Vous comprenez ce que cela signifierait, pour l’Empire... et pour <H>vous</>.",
            ["DialogueId"] = 11019103,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B95CD96",
            ["NextDialogue"] = 11016706,
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110191/1B95CD96",
            },
        [11019104] = {
            ["Content"] = "幸运的话，你会得到一份决定性的证据。即使证据不幸被销毁，她的证言也有极大价值。请让我和她在你的主持下当面对质。",
            ["ContentFR"] = "Avec un peu de chance, vous obtiendrez une preuve irréfutable. Si elle a été détruite, son témoignage aura déjà un poids immense. Laissez-moi l’affronter sous vos yeux, et la vérité jaillira d’elle-même.",
            ["DialogueId"] = 11019104,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B95CDC0",
            ["NextDialogue"] = 11016707,
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110191/1B95CDC0",
            },
        [11019105] = {
            ["Content"] = "嗯。等你休息好了，我再仔细说给你听。",
            ["ContentFR"] = "Oui. Quand tu seras {性别2:reposé|reposée}, je t’expliquerai tout.",
            ["DialogueId"] = 11019105,
            ["GUID"] = "1B95CDEA",
            ["NextDialogue"] = 11019106,
            ["SpeakNpcId"] = 110018,
            ["TalkActionId"] = {
                [1] = "110018:AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110191/1B95CDEA",
            },
        [11019106] = {
            ["Camera"] = "-201.890625,-407.858398,414.960938,0.000216,-22.600248,41.391022,18.0,254.013382,false,DoNotOverride,7.801928",
            ["Content"] = "我讨厌这座监狱里的血腥味儿，准备好了我们就走吧。",
            ["ContentFR"] = "Je déteste cette odeur de sang dans la prison. Quand tu seras {性别2:prêt|prête}, nous partirons.",
            ["DialogueId"] = 11019106,
            ["FinalCamera"] = "-251.734375,-451.791016,442.613281,0.000208,-22.000229,41.39093,18.0,254.013382,false,DoNotOverride,7.801928",
            ["GUID"] = "1B95CE14",
            ["SpeakNpcId"] = 110018,
            ["ToFinalCameraBlendTime"] = 15,
            ["VoiceName"] = "voice/$Locale$/story/1002/110191/1B95CE14",
            },
        [11019107] = {
            ["Content"] = "五日后",
            ["ContentFR"] = "Cinq jours plus tard...",
            ["DialogueId"] = 11019107,
            ["GUID"] = "1B95CE3E",
            ["NextDialogue"] = 11019108,
            ["VoiceName"] = "voice/$Locale$/story/1002/110191/1B95CE3E",
            },
        [11019108] = {
            ["Content"] = "皇都·迪斯玛尼亚 皇家大剧院",
            ["ContentFR"] = "Capitale Impériale, Dismania – Grand Théâtre Royal",
            ["DialogueId"] = 11019108,
            ["GUID"] = "1B95CE68",
            ["VoiceName"] = "voice/$Locale$/story/1002/110191/1B95CE68",
            },
        [11019109] = {
