            },
        [11019302] = {
            ["Content"] = "法露茜……直接……毁……制室……",
            ["ContentFR"] = "Falsi... fais... sauter... salle... commande...",
            ["DialogueId"] = 11019302,
            ["GUID"] = "1B95EE3C",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 11019303,
            ["Scripts"] = "SEQ{\
