            ["SnapShot"] = "TELEPHONE",
            ["SpeakNpcId"] = 110011,
            ["VoiceName"] = "voice/$Locale$/story/1002/110193/1B95EE3C",
            },
        [11019303] = {
            ["Content"] = "是。",
            ["ContentFR"] = "À vos ordres.",
            ["DialogueId"] = 11019303,
            ["GUID"] = "1B95EE66",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 11019304,
