        [12000412] = {
            ["Camera"] = "210.601685,277.546875,150.097656,0.000214,2.402225,109.397453,35.0,312.341827,false,DoNotOverride,10.0",
            ["Content"] = "千万别。",
            ["ContentFR"] = "Pas question.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12000412,
            ["GUID"] = "1E0AB198",
            ["NextDialogue"] = 12000413,
            ["SpeakNpcId"] = 200003,
            ["VoiceName"] = "voice/$Locale$/story/1200/120004/1E0AB198",
            },
        [12000413] = {
            ["Content"] = "今天我有位难得的大客户要接待。你要是待在这儿，人家还以为我放着好好的酒馆生意不做，转头开幼儿园了呢。",
            ["ContentFR"] = "Aujourd’hui j’ai une cliente importante. Si tu restes là à gesticuler, elle va croire que j’ai transformé ma taverne en garderie.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12000413,
            ["FacialId"] = {
                [1] = "200003:Uninterested01",
                },
            ["GUID"] = "1E0AB1C2",
            ["NextDialogue"] = 12000414,
            ["SpeakNpcId"] = 200003,
            ["TalkActionId"] = {
                [1] = "200003:Talk03_End",
                [2] = "100001:Disagree",
