        [12000422] = {
            ["Camera"] = "454.580322,142.229492,148.949219,0.000098,-0.399197,139.819107,55.0,768.236572,false,DoNotOverride,16.14603",
            ["Content"] = "上次她来的时候眼睛里都是使不完的牛劲儿，信誓旦旦说要抓凶手。这次不知怎的，像那群整天酗酒的醉汉一样，满眼血丝，走路都怕她一不小心跌倒。",
            ["ContentFR"] = "La dernière fois qu’elle est venue, elle débordait d’énergie, jurant qu’elle mettrait la main sur le coupable. Mais hier... on aurait dit une ivrogne, les yeux rouges, chancelante, comme si elle allait s’effondrer à chaque pas.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12000422,
            ["FinalCamera"] = "424.985596,167.219727,148.683594,0.000098,-0.399197,139.819107,55.0,768.236572,false,DoNotOverride,16.14603",
            ["GUID"] = "1E0AB33C",
            ["NextDialogue"] = 12000423,
            ["Scripts"] = "PARA{\
