            },
        [12000425] = {
            ["Camera"] = "876.919189,-283.1875,139.324219,0.0002,-2.281304,140.793442,45.0,390.38385,false,Manual,10.0",
            ["Content"] = "好了，不用说了。看你的表情，一定是什么只能藏在心底的秘密——那还是不说为好。",
            ["ContentFR"] = "Pas besoin d’en dire plus. Ton visage dit déjà que c’est un secret qui doit rester enfoui. Je ne poserai pas de questions.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12000425,
            ["FinalCamera"] = "887.011963,-270.8125,139.324219,0.0002,-2.281304,140.793442,45.0,390.38385,false,Manual,10.0",
            ["GUID"] = "1E0AB3BA",
            ["NextDialogue"] = 12000426,
            ["Scripts"] = "PARA{\
