        [12000801] = {
            ["Camera"] = "-170.109375,317.277344,120.285156,0.000179,8.798184,-120.996368,35.0,1500.0,false,DoNotOverride,10.0",
            ["Content"] = "她在这边站了好久……是在等什么人吗？",
            ["ContentFR"] = "Elle reste plantée là depuis un moment... Elle attend quelqu’un ?",
            ["DialogueId"] = 12000801,
            ["FinalCamera"] = "-170.007812,317.214844,125.261719,0.000179,8.798184,-120.996368,35.0,1500.0,false,DoNotOverride,10.0",
            ["GUID"] = "1E0AF16A",
