            },
        [12000903] = {
            ["Camera"] = "782.886719,-1307.572754,160.4375,0.000041,8.400169,167.798965,30.0,500.702026,false,Manual,10.0",
            ["Content"] = "哪来的卡戎崽种，滚出去，别把这里的地毯弄脏了。",
            ["ContentFR"] = "Et depuis quand les sales Charons se croient les bienvenus ici ? Dehors ! Avant que vous ne salissiez nos tapis.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12000903,
            ["FinalCamera"] = "805.789062,-1312.524902,156.980469,0.000031,8.400169,167.798874,30.000002,500.702026,false,Manual,10.0",
            ["GUID"] = "1E0B0226",
            ["NextOptions"] = {
                [1] = 12000904,
                [2] = 12000905,
                },
            ["Scripts"] = "PlayAnimation{_delay{1},ActorId{200002},AnimationId{\"Shock_Start\"},Duration{1}}",
            ["SpeakNpcId"] = 220010,
            ["TalkActionId"] = {
                [1] = "220010:Angry01_Start",
                [2] = "100001:Confident_End",
                },
            ["ToFinalCameraBlendTime"] = 0.2,
            ["VoiceName"] = "voice/$Locale$/story/1200/120009/1E0B0226",
            },
        [12000904] = {
            ["Content"] = "你们的规定写了观众凭票入场，可没限定其他的。",
            ["ContentFR"] = "Votre règlement dit clairement : l’entrée se fait sur présentation de billets. Je n’ai rien lu sur l’exclusion de certains groupes.",
            ["DialogueId"] = 12000904,
            ["GUID"] = "1E0B0250",
            ["ImprPlusId"] = 1008,
            ["NextDialogue"] = 12000906,
            },
        [12000905] = {
            ["Content"] = "你这是什么态度？我要找你上司投诉。",
            ["ContentFR"] = "C’est quoi cette attitude ? Je vais en référer à votre supérieur.",
            ["DialogueId"] = 12000905,
            ["GUID"] = "1E0B027A",
            ["ImprPlusId"] = 1010,
            ["NextDialogue"] = 12000906,
            },
        [12000906] = {
            ["Camera"] = "863.048828,-1966.588867,802.714844,3.000484,-35.395828,125.389961,30.0,500.702026,false,Manual,10.0",
            ["Content"] = "……要我说，剧院没有把“卡戎和秽兽禁止入场”写进规章制度里，就是天底下最滑稽的一件事情。",
            ["ContentFR"] = "Hmpf... À mon avis, le plus ridicule, c’est que ce théâtre n’ait pas encore gravé noir sur blanc : interdit aux Charons et aux Souillés.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12000906,
            ["FinalCamera"] = "854.712891,-1972.905762,802.285156,3.000485,-35.39579,125.389961,30.0,500.702026,false,Manual,10.0",
            ["GUID"] = "1E0B02A4",
            ["NextDialogue"] = 12000907,
            ["Scripts"] = "PARA{\
PlayAnimation{_delay{1},ActorId{220010},AnimationId{\"Talk01_Start\"},Duration{1}},\
PlayAnimation{_delay{3},ActorId{100001},AnimationId{\"Talk03_Start\"},Duration{1}},\
PlayAnimation{_delay{6},ActorId{220010},AnimationId{\"Talk01_End\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 220010,
            ["TalkActionId"] = {
                [1] = "220010:Angry01_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1200/120009/1E0B02A4",
            },
        [12000907] = {
            ["Camera"] = "492.046875,-1336.085938,227.90625,0.000058,5.800442,163.211411,35.000011,240.0,false,Manual,10.0",
            ["Content"] = "算了。拿来吧，票。",
            ["ContentFR"] = "Bon. Montrez-moi ces billets.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12000907,
            ["GUID"] = "1E0B02CE",
            ["SpeakNpcId"] = 220010,
            ["TalkActionId"] = {
                [1] = "220010:Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1200/120009/1E0B02CE",
            },
        [12001101] = {
            ["Content"] = "在你们面前，检票员慢条斯理地戴上了单片眼镜。翻来覆去地打量手上两张单薄的票。",
            ["ContentFR"] = "Le contrôleur ajuste lentement son monocle, inspecte les deux billets sous toutes les coutures.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001101,
            ["Duration"] = 3,
            ["GUID"] = "1E0B22A2",
            ["VoiceName"] = "voice/$Locale$/story/1200/120011/1E0B22A2",
            },
        [12001102] = {
            ["Camera"] = "472.220703,-1396.854004,227.90625,0.00006,5.200376,142.810028,35.000015,240.0,false,Manual,10.0",
            ["Content"] = "哈……给我找着了。",
            ["ContentFR"] = "Ha... Je le savais.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001102,
            ["FacialId"] = {
                [1] = "220010:CM_Ahaha01",
                },
            ["FinalCamera"] = "497.951172,-1415.679199,170.234375,0.000072,16.800051,143.810089,35.000015,240.0,false,Manual,10.0",
            ["GUID"] = "1E0B22CC",
            ["NextDialogue"] = 12001103,
            ["SpeakNpcId"] = 220010,
            ["TalkActionId"] = {
                [1] = "220010:Talk01_Start",
                },
            ["ToFinalCameraBlendTime"] = 1,
            ["VoiceName"] = "voice/$Locale$/story/1200/120011/1E0B22CC",
            },
        [12001103] = {
            ["Camera"] = "219.5,-1363.567383,271.265625,0.000139,-9.198488,34.811485,30.0,240.0,false,Manual,10.0",
            ["Content"] = "以为用墨水描了日期就能用过期票混进去吗？成天把脑筋动在这种小偷小摸的事情上，逃不过我的眼睛！",
            ["ContentFR"] = "Vous pensiez berner qui ? Retracer une date à l’encre et passer avec des billets périmés ? Des petites frappes comme vous, je les repère à des kilomètres.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001103,
            ["FacialId"] = {
                [1] = "220010:CM_Idle",
                [2] = "200002:Angry01",
