        [12001104] = {
            ["Content"] = "在确凿证据前，你们哑口无言。",
            ["ContentFR"] = "Devant ces \"preuves\", vous restez sans voix.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001104,
