        [12001201] = {
            ["Camera"] = "408.910156,-1367.649414,276.621094,28.797125,-46.400139,-77.170898,35.000011,240.0,false,DoNotOverride,10.0",
            ["Content"] = "给，这是我的凭据。",
            ["ContentFR"] = "Voici ma confirmation de réservation.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001201,
            ["GUID"] = "1E0B330A",
