        [12001311] = {
            ["Camera"] = "-76.600586,-142.378418,145.878906,0.000066,2.400094,55.591667,35.000011,210.0,false,Manual,10.0",
            ["Content"] = "呵呵……不用这么拘谨。你可以直接称呼我的名字。",
            ["ContentFR"] = "Héhé... Inutile d’être si cérémonieux. Appelle-moi simplement Zhiliu.",
            ["DialogueId"] = 12001311,
            ["FacialId"] = {
                [1] = "210004:Smile01",
                },
            ["FinalCamera"] = "-73.668945,-138.096191,146.089844,0.000078,2.400094,55.59174,35.000008,210.0,false,Manual,10.0",
            ["GUID"] = "1E0B4516",
