            ["TalkActionId"] = {
                [1] = "210004:Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1200/120013/1E0B4594",
            },
        [12001315] = {
            ["Camera"] = "-228.251953,-342.149658,218.3125,0.000205,-10.998899,54.599339,35.0,210.445709,false,DoNotOverride,10.0",
            ["Content"] = "那……止流掌柜，您应该是在等什么人吧？我们在这儿，会不会打扰到您？",
            ["ContentFR"] = "Alors... Patronne Zhiliu, vous attendiez quelqu’un, n’est-ce pas ? Nous n’allons pas vous déranger ?",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001315,
            ["FacialId"] = {
