            },
        [12001316] = {
            ["Camera"] = "22.512695,93.567383,162.910156,0.000092,-4.399099,-96.009109,35.000008,201.567627,false,Manual,10.0",
            ["Content"] = "原来你在意的是这个呀，真可爱。",
            ["ContentFR"] = "Oh, c’est donc ça qui te tracassait ? Que c’est adorablement attentionné de ta part.",
            ["DefaultLookAt"] = "TalkNpc",
