            ["VoiceName"] = "voice/$Locale$/story/1200/120013/1E0B463C",
            },
        [12001319] = {
            ["Camera"] = "-39.875977,-172.393066,112.152344,0.000143,-4.597844,106.196785,30.000008,106.771988,false,Manual,10.0",
            ["Content"] = "小仆从，竟然有人会辜负这么有钱又出手大方的漂亮姐姐，还让她伤心……真是太没眼光了！",
            ["ContentFR"] = "Petit larbin ! Tu te rends compte ? Quel idiot faut-il être pour laisser tomber une dame aussi belle, aussi riche et aussi généreuse... et la laisser se morfondre ?!",
            ["DialogueId"] = 12001319,
            ["FacialId"] = {
                [1] = "200002:Doubt01",
                },
            ["GUID"] = "1E0B4666",
            ["LookAt"] = {
