        [12001320] = {
            ["Camera"] = "-157.03418,-238.744385,135.445312,0.000194,-1.198671,55.205051,29.855673,334.603516,false,DoNotOverride,10.0",
            ["Content"] = "在我的家乡，人与人之间的相遇相识被称为“缘分”。缘分来之不易，既然出现了就不如珍惜，你觉得呢？",
            ["ContentFR"] = "Dans mon pays, les rencontres entre les personnes sont ce qu’on appelle le destin. Ces instants sont rares et précieux, et lorsqu’ils se présentent, il convient de les chérir. Qu’en penses-tu ? ",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001320,
            ["FinalCamera"] = "2.482422,-380.777344,275.316406,0.000165,-21.198877,95.206535,29.855673,334.603516,false,DoNotOverride,10.0",
            ["GUID"] = "1E0B4690",
