            ["Camera"] = "4572.582031,245.40918,-1846.019531,0.000001,19.997604,-90.387962,20.000008,878.773254,false,Manual,1.2",
            ["Content"] = "演出即将开始。还在走动的客人请尽快入座。",
            ["ContentFR"] = "Mesdames et messieurs, le spectacle va commencer. Les retardataires, merci de prendre rapidement place.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001324,
            ["FinalCamera"] = "4562.724609,-667.667236,-1513.722656,0.000001,19.997604,-90.387962,20.000008,878.773254,false,Manual,1.2",
            ["GUID"] = "1E0B4738",
