            ["ToFinalCameraBlendTime"] = 13,
            ["VoiceName"] = "voice/$Locale$/story/1200/120013/1E0B4738",
            },
        [12001325] = {
            ["Content"] = "接下来，请您欣赏盖雷亚歌剧团带来的精彩表演——",
            ["ContentFR"] = "Et maintenant, profitez du magnifique spectacle présenté par la troupe d’opéra de Galea !",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001325,
            ["GUID"] = "1E0B4762",
