            },
        [12001326] = {
            ["Camera"] = "-213.078125,597.674805,707.015625,0.000202,-11.600912,-178.603836,40.000023,1102.562866,false,Manual,1.2",
            ["Content"] = "很久以前，雪国城堡里，冰霜的妖精被两个孩子唤醒……",
            ["ContentFR"] = "Il y a bien longtemps... dans un château de glace, au cœur d’un pays enneigé...\
Une fée des neiges s’éveilla au rire de deux enfants.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001326,
            ["FinalCamera"] = "-211.563477,535.948242,707.015625,0.000202,-11.600912,-178.603836,40.000023,1102.562866,false,Manual,1.2",
            ["GUID"] = "1E0B478C",
            ["NextDialogue"] = 12001327,
            ["Scripts"] = "PlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt03/0069_boss_devil_linen\"}}",
            ["ToFinalCameraBlendTime"] = 25,
            ["VoiceName"] = "voice/$Locale$/story/1200/120013/1E0B478C",
            },
        [12001327] = {
            ["Camera"] = "7325.71875,5494.020508,541.855469,0.000293,22.789042,-159.560425,20.0,500.0,false,Manual,10.0",
            ["Content"] = "渺小的妖精飞向巨兽……",
            ["ContentFR"] = "Alors, la frêle fée s’élança contre les monstres...",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001327,
            ["FinalCamera"] = "7183.162109,5440.892578,605.769531,0.000291,26.788889,-155.961044,20.0,500.0,false,Manual,10.0",
            ["GUID"] = "1E0B47B6",
            ["NextDialogue"] = 12001328,
            ["ToFinalCameraBlendTime"] = 15,
            ["VoiceName"] = "voice/$Locale$/story/1200/120013/1E0B47B6",
            },
        [12001328] = {
            ["Content"] = "但巨兽稍稍用力，就折断了它的四肢……",
            ["ContentFR"] = "Mais leurs griffes brisèrent d’un rien ses membres fragiles.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001328,
            ["FacialId"] = {
                [1] = "220041:Sad03",
                },
            ["GUID"] = "1E0B47E0",
