            },
        [12001329] = {
            ["Camera"] = "32.304688,240.658203,114.476562,0.000086,-2.603053,-135.186905,30.000002,132.470917,false,Manual,6.527582",
            ["Content"] = "它听到心脏的声音，第一次鼓动着，呐喊着它的命运——",
            ["ContentFR"] = "Pourtant, pour la toute première fois... son cœur battit. Il battit... il hurla son propre destin !",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001329,
            ["Duration"] = 5,
