            },
        [12001334] = {
            ["Camera"] = "617.853516,615.266602,211.964844,0.00002,-9.801267,-144.203323,50.0,799.630554,false,Manual,1.2",
            ["Content"] = "无论地域，无论年代，各处都经久不衰地上演着相同的故事。故事里的主角用死亡和牺牲，去换取某些更为宏大崇高的事物。",
            ["ContentFR"] = "Peu importe le lieu, peu importe l’époque, la même histoire se répète. Les héros échangent leur vie et leur sacrifice pour quelque chose de plus grand, de plus noble.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001334,
            ["FacialId"] = {
                [1] = "220041:Zhiliu_SpecialSad",
                },
            ["FinalCamera"] = "728.994141,695.423828,235.628906,0.00002,-9.801267,-144.203323,50.0,930.356812,false,Manual,1.2",
