            ["VoiceName"] = "voice/$Locale$/story/1200/120013/1E0B48DC",
            },
        [12001335] = {
            ["Camera"] = "-46.225586,57.569824,112.15625,0.00005,-1.201355,80.793785,45.000023,91.94062,false,Manual,4.511572",
            ["Content"] = "但是……用性命换得的东西，真的值得用性命衡量吗？",
            ["ContentFR"] = "Mais... ces choses pour lesquelles on échange sa vie, valent-elles vraiment ce prix ?",
