            },
        [12001345] = {
            ["Camera"] = "-123.167969,340.399414,92.625,0.00017,-21.796923,-52.159969,40.000011,81.737244,false,DoNotOverride,5.0",
            ["Content"] = "…………",
            ["ContentFR"] = "...",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001345,
            ["DisableMouth"] = 1,
            ["GUID"] = "1E0B4AAA",
            ["SpeakNpcId"] = 220014,
