        [12001360] = {
            ["Content"] = "在你看来，会是哪种情况呢？",
            ["ContentFR"] = "À ton avis, laquelle est la bonne ?",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001360,
            ["GUID"] = "1E0B4D20",
            ["LookAt"] = {
                [1] = "220014:n(220018)",
