            },
        [12001508] = {
            ["Camera"] = "-1.962891,363.010254,80.773438,0.000094,-10.804443,-134.590561,35.000011,200.0,false,DoNotOverride,10.0",
            ["Content"] = "这香是我们华胥特有的珍贵物产。它对存在于月髓原液中的某种特殊物质有极高的亲和力，只需碰到一星半点，烟迹就会发生变化。",
            ["ContentFR"] = "Cet encens est une rare spécialité de Huaxu. Il réagit fortement à une substance présente dans le Phoxichor pur. Même un contact minime modifie le tracé de la fumée.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001508,
            ["GUID"] = "1E0B6568",
            ["NextDialogue"] = 12001509,
            ["SpeakNpcId"] = 220014,
            ["ToFinalCameraBlendTime"] = 6,
            ["VoiceName"] = "voice/$Locale$/story/1200/120015/1E0B6568",
            },
        [12001509] = {
            ["Camera"] = "26.769531,320.916504,68.851562,0.000117,-2.605321,-158.169327,58.891438,116.774818,false,Manual,10.0",
            ["Content"] = "……看这烟迹，他带来的货连最次的次品都不如。",
            ["ContentFR"] = "... À en juger par la fumée, le Phoxichor qu’il a apporté est pire que même la plus basse qualité.",
