        [12001519] = {
            ["Camera"] = "-79.387329,-101.302734,236.034424,0.000077,-24.5979,142.995789,37.000004,300.0,false,Manual,10.0",
            ["Content"] = "没关系没关系，我们小仆从本来就是走到哪儿麻烦就跟到哪儿的体质！",
            ["ContentFR"] = "Pas grave, pas grave ! Mon petit larbin a un vrai don pour attirer les ennuis partout où {性别:il|elle} passe !",
            ["DefaultLookAt"] = "TalkNpc",
