        [12001530] = {
            ["Camera"] = "-7.876221,306.707031,115.128906,0.000392,-12.597136,-157.65332,19.845514,128.396683,false,Manual,10.0",
            ["Content"] = "这就是你说的“难得的大客户”是吧，哼哼——你们聊你们聊，成熟又可靠的白要自己玩去了！",
            ["ContentFR"] = "Alors c’est elle, ta fameuse \"cliente importante\" ? <I>Hum hum !</> Très bien, très bien... vous, discutez entre adultes. La très mature et très fiable Snow va aller s’amuser ailleurs !",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001530,
