            ["Camera"] = "29.821655,178.912109,118.074219,0.000363,10.003126,-166.241898,35.0,162.47998,false,Manual,10.0",
            ["Content"] = "出发前，我曾卜上一卦。",
            ["ContentFR"] = "Avant de partir, j’avais tiré un présage.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001532,
            ["FinalCamera"] = "10.149536,174.098633,125.015625,0.000363,10.003126,-166.241898,35.0,162.47998,false,Manual,10.0",
