                [1] = "210004:Give",
                },
            ["ToFinalCameraBlendTime"] = 15,
            ["VoiceName"] = "voice/$Locale$/story/1200/120015/1E0B6958",
            },
        [12001533] = {
            ["Content"] = "卦象曰，由颐，厉吉，利涉大川。意思是过程看似凶险波折，但最终还是能够导向好的结果。",
            ["ContentFR"] = "Le présage disait : « Nourris-toi de prudence dans le danger, et la fortune te suivra. Il est favorable de franchir le grand fleuve. » Cela annonçait un chemin semé d’embûches, mais promettait une issue heureuse.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001533,
            ["GUID"] = "1E0B6982",
            ["NextDialogue"] = 12001534,
            ["Scripts"] = "PARA{\
PlayAnimation{_delay{8},ActorId{210004},AnimationId{\"Think_Start\"},Duration{1}},\
PlayFacial{_delay{8},ActorId{210004},FacialId{\"Smile01\"}}\
}",
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1200/120015/1E0B6982",
            },
        [12001534] = {
            ["Camera"] = "42.346802,185.667969,155.265625,0.000507,-2.996301,60.343025,35.000008,241.62059,false,Manual,10.0",
            ["Content"] = "看来你有所收获，内情我就不多过问了。接下来呢，你有什么打算？",
            ["ContentFR"] = "Je vois... tu sembles avoir trouvé ce que tu cherchais. Je n’insisterai pas. Et maintenant, que comptes-tu faire ?",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001534,
            ["FacialId"] = {
                [1] = "100001:None",
                },
            ["GUID"] = "1E0B69AC",
            ["LookAt"] = {
                [1] = "210004:n(200003)",
                [2] = "100001:n(210004)",
                },
            ["NextDialogue"] = 12001535,
            ["SpeakNpcId"] = 200003,
            ["TalkActionId"] = {
                [1] = "210004:Think_End",
                [2] = "200002:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1200/120015/1E0B69AC",
            },
        [12001535] = {
            ["Camera"] = "373.522949,453.332031,158.96875,0.000385,-4.596492,-152.252457,46.909203,114.727348,false,DoNotOverride,10.0",
            ["Content"] = "回程的商船几日后才会启程。在这期间，我打算顺带收购一批其他材料。或许需要在你这里叨扰一阵了。",
            ["ContentFR"] = "Le navire de commerce qui doit me ramener ne lèvera l’ancre que dans quelques jours. En attendant, j’ai l’intention d’acquérir d’autres matériaux. Je vais donc probablement abuser un peu de ton hospitalité.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001535,
            ["GUID"] = "1E0B69D6",
            ["NextDialogue"] = 12001536,
            ["Scripts"] = "MoveTo{ActorId{210004},TargetPoint{\"NewTargetPoint12000209Zhiliu3\"},MoveSpeed{70},Visibility{\"Show\"}}",
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1200/120015/1E0B69D6",
            },
        [12001536] = {
            ["Content"] = "说到这里……你有办事利索的狩月人能够推荐给我吗？",
            ["ContentFR"] = "D’ailleurs... aurais-tu quelques Chasseurs de Phoxène fiables à me recommander ?",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001536,
            ["GUID"] = "1E0B6A00",
            ["NextDialogue"] = 12001537,
            ["SpeakNpcId"] = 210004,
            ["TalkActionId"] = {
                [1] = "210004:Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1200/120015/1E0B6A00",
            },
        [12001537] = {
            ["Camera"] = "90.069214,202.158203,145.142578,0.000401,0.403022,69.749039,35.0,207.094284,false,Manual,10.0",
            ["Content"] = "办事利索的狩月人？喏，他们俩随你差遣。正巧，他们早上还在和我抱怨没活可干呢。",
            ["ContentFR"] = "Des Chasseurs de Phoxène efficaces ? Eh bien, les voilà. Ce matin encore, ils se plaignaient de n’avoir rien à faire.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001537,
            ["GUID"] = "1E0B6A2A",
            ["LookAt"] = {
                [1] = "210004:n(100001)",
                },
            ["NextDialogue"] = 12001538,
            ["Scripts"] = "SEQ{\
PlayAnimation{_delay{2},ActorId{200003},AnimationId{\"Talk02_Start\"},Duration{1}},\
CameraMoveTo{_delay{4.5},TargetPosition{\"149.119507,365.365234,153.390625,0.000422,-4.79663,-148.648407,40.212906,303.12265,false,Manual,10.0\"},duration{0}},\
CameraMoveTo{TargetPosition{\"120.565918,347.96875,150.585938,0.000422,-4.79663,-148.648407,40.212906,312.589752,false,Manual,10.0\"},duration{10}}\
}",
            ["SpeakNpcId"] = 200003,
            ["TalkActionId"] = {
                [1] = "210004:Talk02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1200/120015/1E0B6A2A",
            },
        [12001538] = {
            ["Content"] = "他俩看着或许有些不靠谱，狩猎的手艺还算勉勉强强。",
            ["ContentFR"] = "Ils n’ont peut-être pas l’air très fiables, mais pour le travail, ils se débrouillent plutôt bien.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001538,
            ["GUID"] = "1E0B6A54",
            ["LookAt"] = {
                [1] = "210004:n(100001)",
                [2] = "200002:p(LookatBai)",
                },
            ["NextDialogue"] = 12001539,
            ["SpeakNpcId"] = 200003,
            ["TalkActionId"] = {
                [1] = "200002:Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1200/120015/1E0B6A54",
            },
        [12001539] = {
