            },
        [12001552] = {
            ["Camera"] = "-646.596497,493.004883,151.15625,0.000393,-22.975636,-135.875137,35.000008,181.619598,false,Manual,10.0",
            ["Content"] = "剑上的纹路……啊，白想起来了，这不是小仆从的那把“稀世神兵”嘛！",
            ["ContentFR"] = "Les gravures sur la lame... Ah, je me souviens ! Ce n’est pas ton \"arme légendaire\" ?",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001552,
            ["FinalCamera"] = "-669.792358,470.508789,137.451172,0.000393,-22.975636,-135.875137,35.000008,139.75914,false,Manual,10.0",
            ["GUID"] = "1E0B6CA0",
            ["NextDialogue"] = 12001553,
            ["Scripts"] = "PlayFacial{_delay{2.5},ActorId{200002},FacialId{\"Shock01\"}}",
            ["SpeakNpcId"] = 200002,
            ["ToFinalCameraBlendTime"] = 25,
            ["VoiceName"] = "voice/$Locale$/story/1200/120015/1E0B6CA0",
            },
        [12001553] = {
            ["Content"] = "今日午夜归还……发布这则寻物启事的人怎么这么傻，万一没被看到，这个人岂不是要在电话亭里枯等一夜。你说是吧，小仆从？",
            ["ContentFR"] = "Ce soir à minuit... Comment l’auteur de cette annonce a‑t‑il pu être si bête ? Si personne ne la voit, cette personne risque de rester à la cabine toute la nuit. J’ai raison, petit larbin ?",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001553,
            ["FacialId"] = {
                [1] = "200002:Unacceptable01",
                },
            ["GUID"] = "1E0B6CCA",
            ["NextDialogue"] = 12001554,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1200/120015/1E0B6CCA",
            },
        [12001554] = {
            ["Camera"] = "-464.445679,605.799805,172.630859,0.000425,-12.175925,-151.479797,35.000008,287.978119,false,Manual,10.0",
            ["Content"] = "……小仆从，你怎么突然这么安静？喂、喂……你怎么了？",
            ["ContentFR"] = "... Petit larbin, pourquoi es-tu si {性别:silencieux|silencieuse} tout d’un coup ? Hé ! Hé... tu vas bien ?",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001554,
            ["FacialId"] = {
                [1] = "200002:Confident01",
                },
            ["FinalCamera"] = "-440.479553,548.991211,172.630859,0.000429,-12.375913,-162.080276,35.000008,287.978119,false,Manual,10.0",
            ["GUID"] = "1E0B6CF4",
            ["NextDialogue"] = 12001555,
            ["Scripts"] = "PlayAnimation{_delay{3},ActorId{200002},AnimationId{\"Confident_Start\"},Duration{1}}",
            ["SpeakNpcId"] = 200002,
            ["ToFinalCameraBlendTime"] = 15,
            ["TurnTo"] = {
                [1] = "200002:n(100001)",
                },
            ["VoiceName"] = "voice/$Locale$/story/1200/120015/1E0B6CF4",
            },
        [12001555] = {
            ["Camera"] = "-715.893799,240.316406,68.830078,0.000409,9.823683,97.518883,35.0,265.0,false,Manual,10.0",
            ["Content"] = "呃、哦……我突然有点不舒服，先回去休息了……",
            ["ContentFR"] = "Euh... je ne me sens pas très bien, je vais rentrer me reposer un peu...",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001555,
            ["FacialId"] = {
                [1] = "100001:Unhappy01",
                },
            ["GUID"] = "1E0B6D1E",
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1200/120015/1E0B6D1E",
            },
        [12001556] = {
            ["Content"] = "我弄丢了一把剑，那是一把很珍贵的剑，我和我的至亲走散了，失散时{性别：他|她}身上正带着这把剑。",
            ["ContentFR"] = "J’ai perdu une épée, très précieuse. J’ai été séparée d’{性别:un|une} membre de ma famille, et l’épée était avec {性别:lui|elle} au moment de notre séparation.",
            ["DialogueId"] = 12001556,
            ["Duration"] = 2,
            ["GUID"] = "1E0B6C23",
            ["NextDialogue"] = 12001557,
            ["VoiceName"] = "voice/$Locale$/story/1200/120015/1E0B6C23",
            },
        [12001557] = {
            ["Content"] = "请知道这把剑消息的人于今日午夜在广场前的红色电话亭处进行归还，必有重酬……",
            ["ContentFR"] = "Toute personne ayant des informations est priée de se présenter ce soir à minuit à la cabine téléphonique rouge sur la place. Une généreuse récompense sera offerte...",
            ["DialogueId"] = 12001557,
            ["Duration"] = 4,
            ["GUID"] = "1E0B6C24",
            ["VoiceName"] = "voice/$Locale$/story/1200/120015/1E0B6C24",
            },
        [12001601] = {
            ["Content"] = "（暂时休息一下吧……）",
            ["ContentFR"] = "<I>... Je devrais faire une pause.</>",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001601,
            ["GUID"] = "1E0B74AA",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1200/120016/1E0B74AA",
            },
        [12001602] = {
            ["Content"] = "（即将开始连续剧情内容，建议做好充分准备后进行体验。）",
            ["ContentFR"] = "Pour la suite de l’histoire. Il est recommandé de prévoir suffisamment de temps pour en profiter pleinement.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001602,
            ["GUID"] = "1E0B74D4",
            ["VoiceName"] = "voice/$Locale$/story/1200/120016/1E0B74D4",
            },
        [12001700] = {
            ["Content"] = "【过场动画】玩家蹑手蹑脚地关上休憩所的门，一转身，和守在门外本来摆着装逼抱胸姿势的白相撞。白吃痛捂住额头。",
            ["DialogueId"] = 12001700,
            ["GUID"] = "1E0B8511",
            },
        [12001701] = {
            ["Camera"] = "-138.622559,507.972168,78.030762,0.000004,0.99994,-73.992325,35.000011,110.363411,false,Manual,10.0",
            ["Content"] = "痛痛痛痛痛……",
            ["ContentFR"] = "Aïe... aïe... aïe... ça fait mal !",
