            ["ToFinalCameraBlendTime"] = 15,
            ["VoiceName"] = "voice/$Locale$/story/1200/120017/1E0B8590",
            },
        [12001705] = {
            ["Content"] = "看你今天一整天魂都丢了的样子，连晚饭都没吃几口，白一眼就看穿了。",
            ["ContentFR"] = "Regarde-toi, tu as été {性别:absent|absente} toute la journée, et tu as à peine touché à ton dîner. Je l’ai tout de suite vu venir.",
            ["DialogueId"] = 12001705,
            ["GUID"] = "1E0B85BA",
