            },
        [12001706] = {
            ["Camera"] = "-182.647461,379.094727,120.482178,0.000029,-26.199799,-40.567471,23.066504,99.404587,false,Manual,10.0",
            ["Content"] = "想丢下本魔王大人自己一个人去冒险？没门！",
            ["ContentFR"] = "Tu pensais pouvoir te débarrasser de moi et partir à l'aventure {性别:tout seul|toute seule} ? Pas question !",
            ["DialogueId"] = 12001706,
            ["FacialId"] = {
                [1] = "200002:Unhappy02",
                },
            ["GUID"] = "1E0B85E4",
            ["NextDialogue"] = 12001707,
            ["Scripts"] = "PlayAnimation{_delay{2.5},ActorId{200002},AnimationId{\"Confident_End\"},Duration{1}}",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1200/120017/1E0B85E4",
            },
        [12001707] = {
            ["Camera"] = "-26.722656,319.375977,59.239258,0.000077,19.398317,164.820892,35.000011,187.953278,false,Manual,10.0",
            ["Content"] = "……我不是故意不带你。只是，这次可能会惹到海伯利亚的士兵，我不能为了自己的事把你卷进去。",
            ["ContentFR"] = "... Je ne voulais pas t’emmener contre ton gré. C’est juste que cette fois, je risque de croiser les soldats hyperboréens. Je ne veux pas t’entraîner dans mes ennuis.",
            ["DialogueId"] = 12001707,
            ["FacialId"] = {
                [1] = "100001:Sad01",
                },
            ["GUID"] = "1E0B860E",
            ["NextDialogue"] = 12001708,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:DisagreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/story/1200/120017/1E0B860E",
            },
        [12001708] = {
            ["Camera"] = "-182.111328,611.16748,189.450439,0.000017,-21.399889,-85.183884,35.000011,306.042999,false,Manual,10.0",
            ["Content"] = "那个……好像咱们也不是第一次招惹海伯利亚的士兵了吧？",
            ["ContentFR"] = "Hé... on a déjà foutu le bazar avec les soldats hyperboréens combien de fois, hein ?",
            ["DialogueId"] = 12001708,
