            ["Content"] = "止流女士——不，止流掌柜，你怎么会在这里？",
            ["ContentFR"] = "Madame... euh, Patronne Zhiliu ! Que faites-vous ici ?",
            ["DialogueId"] = 12001758,
            ["FacialId"] = {
                [1] = "100001:Shock02",
