            ["VoiceName"] = "voice/$Locale$/story/1200/120017/1E0B8E6C",
            },
        [12001759] = {
            ["Camera"] = "263.743164,-274.392456,127.796387,0.00015,-2.60013,101.20816,35.0,400.0,false,Manual,10.0",
            ["Content"] = "本来是特意找你道别的……现在看来，倒是没有这个必要了。",
            ["ContentFR"] = "Je venais pour te dire au revoir... mais il semble que ce ne soit plus nécessaire.",
            ["DialogueId"] = 12001759,
            ["FacialId"] = {
                [1] = "100001:None",
                [2] = "200002:None",
                },
            ["GUID"] = "1E0B8E96",
            ["NextDialogue"] = 12001760,
            ["SpeakNpcId"] = 210004,
            ["TalkActionId"] = {
                [1] = "210004:Talk03ToTalkL_End",
