            },
        [12001761] = {
            ["Camera"] = "217.206543,35.907349,156.063477,0.000065,-9.400607,-97.392738,35.000015,163.255356,false,Manual,15.0",
            ["Content"] = "……我明白了！",
            ["ContentFR"] = "... Compris !",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001761,
            ["FacialId"] = {
                [1] = "100001:None",
