}",
            },
        [12002002] = {
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12002002,
            ["FinalCamera"] = "53.868408,-304.266663,97.972412,0.00009,-2.799961,136.199478,35.0,100000.0,False,Manual,10.0",
            ["GUID"] = "1E0BB674",
            },
        [12002003] = {
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12002003,
            ["FinalCamera"] = "-114.279785,-254.552246,92.543457,0.000091,2.400053,125.79911,35.0,100000.0,False,Manual,10.0",
            ["GUID"] = "1E0BB69E",
            },
        [12002100] = {
            ["Content"] = "假装潜行玩法",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12002100,
            ["GUID"] = "1E0BC688",
            },
        [12003001] = {
            ["Content"] = "假装这里坐下来了，后面k一个Sequence",
            ["DialogueId"] = 12003001,
            ["GUID"] = "1E0C5A5A",
            },
        [12003101] = {
            ["Content"] = "假装把止流带走",
            ["DialogueId"] = 12003101,
            ["GUID"] = "1E0C6AC2",
            },
        [12003201] = {
            ["Content"] = "假装2D图",
            ["DialogueId"] = 12003201,
            ["GUID"] = "1E0C7B2A",
            },
        [12003301] = {
            ["Content"] = "这里就把玩家传到东国了",
            ["DialogueId"] = 12003301,
            ["GUID"] = "1E0C8B92",
            },
        [12003401] = {
            ["Content"] = "假装开车出城的Sequence",
            ["DialogueId"] = 12003401,
            ["GUID"] = "1E0C9BFA",
            },
        [12004001] = {
            ["Camera"] = "127.357666,-54.3125,106.762451,0.000013,7.799898,-163.400085,35.0,100000.0,False,Manual,10.0",
            ["Content"] = "选A还是B",
            ["DialogueId"] = 12004001,
            ["GUID"] = "1E0CFE6A",
            ["SpeakNpcId"] = 100001,
            },
        [12004002] = {
            ["Content"] = "A",
            ["DialogueId"] = 12004002,
            ["GUID"] = "1E0CFE94",
            ["SpeakNpcId"] = 100001,
            },
        [12004003] = {
            ["Content"] = "B",
            ["DialogueId"] = 12004003,
            ["GUID"] = "1E0CFEBE",
            ["SpeakNpcId"] = 200002,
            },
        [12004101] = {
            ["Content"] = "……哇，好多人哦。大家都是来看剧的吗？",
            ["ContentFR"] = "Ouah... Il y a tellement de monde ! Tout ça, c’est pour le spectacle ?",
            ["DialogueId"] = 12004101,
            ["GUID"] = "1E0AE102",
            ["NextDialogue"] = 12004102,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1200/120007/1E0AE102",
            },
        [12004102] = {
            ["Content"] = "他们好像在聊一些很有意思的事情，小仆从，我们去听听看吧。",
            ["ContentFR"] = "Ils ont l’air de discuter de choses passionnantes. Petit larbin, allons écouter !",
            ["DialogueId"] = 12004102,
            ["GUID"] = "1E0D0EFC",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1200/120041/1E0D0EFC",
            },
        [12004201] = {
            ["Content"] = "止流姐姐，你去水仙平原，莫非是要见什么人？",
            ["ContentFR"] = "Dis, grande sœur Zhiliu... tu vas aux Asphodèles pour voir quelqu’un, pas vrai ?",
            ["DialogueId"] = 12004201,
            ["GUID"] = "1E0D1F3A",
            ["NextDialogue"] = 12004202,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1200/120042/1E0D1F3A",
            },
        [12004202] = {
            ["Content"] = "让白猜猜……该不会是一位金色大波浪、说起话来凶巴巴的老板娘吧！",
            ["ContentFR"] = "Laisse-moi deviner... ce ne serait pas une patronne aux cheveux blonds bouclés, avec une langue bien acérée ?",
            ["DialogueId"] = 12004202,
            ["GUID"] = "1E0D1F64",
            ["NextDialogue"] = 12004203,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1200/120042/1E0D1F64",
            },
        [12004203] = {
            ["Content"] = "呵呵，这都被你猜中了。",
            ["ContentFR"] = "Héhé... tu as visé juste.",
            ["DialogueId"] = 12004203,
            ["GUID"] = "1E0D1F8E",
            ["NextDialogue"] = 12004204,
            ["SpeakNpcId"] = 220014,
            ["VoiceName"] = "voice/$Locale$/story/1200/120042/1E0D1F8E",
            },
        [12004204] = {
            ["Content"] = "魔王大人当然是料事如神啦！",
            ["ContentFR"] = "Évidemment ! Le Roi Démon ne se trompe jamais.",
            ["DialogueId"] = 12004204,
            ["GUID"] = "1E0D1FB8",
            ["NextDialogue"] = 12004205,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1200/120042/1E0D1FB8",
            },
        [12004205] = {
            ["Content"] = "啊，不过，刚刚的话，可千万别对卡米拉说哦……不然今天的零花钱又要被扣光了。",
            ["ContentFR"] = "Ah, mais... surtout, ne répète pas ce que je viens de dire à Camilla, d’accord ? Sinon, adieu mon argent de poche...",
            ["DialogueId"] = 12004205,
            ["GUID"] = "1E0D1FE2",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1200/120042/1E0D1FE2",
            },
        [12004206] = {
            ["Content"] = "我们到啦——",
            ["ContentFR"] = "Voilà, on est arrivés !",
            ["DialogueId"] = 12004206,
            ["GUID"] = "1E0D200C",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1200/120042/1E0D200C",
            },
        [12004301] = {
            ["Content"] = "皎皎气呼呼地跑走了。",
            ["ContentFR"] = "Snow s’éloigne en bougonnant.",
            ["DialogueId"] = 12004301,
            ["Duration"] = 2,
            ["GUID"] = "1E0D2FA2",
            ["VoiceName"] = "voice/$Locale$/story/1200/120043/1E0D2FA2",
            },
        [12004401] = {
            ["Content"] = "那边的机器奇奇怪怪的……唔，总觉得绕开它们比较好！",
            ["ContentFR"] = "Ces machines là-bas ont l’air bizarres... Hum, vaut mieux qu’on les évite !",
            ["DialogueId"] = 12004401,
            ["GUID"] = "1E0D400A",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1200/120044/1E0D400A",
            },
        [12004402] = {
            ["Content"] = "它转过去啦，就是现在——",
            ["ContentFR"] = "Elles se sont tournées ! Maintenant !",
            ["DialogueId"] = 12004402,
            ["GUID"] = "1E0D4034",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1200/120044/1E0D4034",
            },
        [12004501] = {
            ["Content"] = "<W>发现追捕目标，发现追捕目标。</>",
            ["ContentFR"] = "<W>Cible repérée. Cible repérée.</>",
            ["DialogueId"] = 12004501,
            ["GUID"] = "1E0D5072",
            ["NextDialogue"] = 12004502,
            ["SnapShot"] = "BROADCAST",
            ["VoiceName"] = "voice/$Locale$/story/1200/120045/1E0D5072",
            },
        [12004502] = {
            ["Content"] = "哇啊……我们的行踪好像暴露了！",
            ["ContentFR"] = "Aaah... on s’est fait repérer !",
            ["DialogueId"] = 12004502,
            ["GUID"] = "1E0D509C",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1200/120045/1E0D509C",
            },
        [12004503] = {
            ["Content"] = "任务失败，请重新开始。",
            ["ContentFR"] = "Échec de la quête. Veuillez recommencer.",
            ["DialogueId"] = 12004503,
            ["GUID"] = "1E0D509D",
            ["SpeakNpcId"] = 200002,
            },
        [12004504] = {
            ["Content"] = "被动失败",
            ["DialogueId"] = 12004504,
            ["GUID"] = "1E0D509E",
            ["SpeakNpcId"] = 200002,
            },
        [12010000] = {
            ["Content"] = "收帆——归港咯——",
            ["ContentFR"] = "Affalez les voiles — on entre au port !",
            ["DialogueId"] = 12010000,
            ["Duration"] = 5,
            ["GUID"] = "1E10D6A0",
            ["VoiceName"] = "voice/$Locale$/story/1201/120100/1E10D6A0",
            },
        [12010001] = {
            ["Content"] = "一路上，从敞篷车换飞艇再坐船，白的屁股都坐痛了……",
            ["ContentFR"] = "Entre la calèche, le dirigeable et maintenant le bateau... j’ai les fesses en compote...",
            ["DialogueId"] = 12010001,
            ["GUID"] = "1E10D6CA",
            ["NextDialogue"] = 12010002,
            ["RelatedWikiId"] = {
                [1] = 408010,
                [2] = 408011,
                [3] = 203001,
                },
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120100/1E10D6CA",
            },
        [12010002] = {
            ["Content"] = "呵呵……毕竟从华胥到海伯利亚，隔了千百里之遥。能将广阔的距离缩减为一日之内的行程，已经是月石技术的伟力了。",
            ["ContentFR"] = "Héhé... De Huaxu jusqu’à Hyperborea, la distance se compte en milliers de lieues. Réduire un tel voyage à une seule journée est déjà une prouesse — celle de la technologie Phoxichorique.",
            ["DialogueId"] = 12010002,
            ["GUID"] = "1E10D6F4",
            ["NextDialogue"] = 12010003,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120100/1E10D6F4",
            },
        [12010003] = {
            ["Content"] = "说的也是。白还从没来过这么远的地方呢！",
            ["ContentFR"] = "Vu comme ça... C’est vrai que je n’ai jamais voyagé aussi loin !",
            ["DialogueId"] = 12010003,
            ["GUID"] = "1E10D71E",
            ["NextDialogue"] = 12010004,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120100/1E10D71E",
            },
        [12010004] = {
            ["Content"] = "能看到这么绿的山峰，这趟算是来对了！要是还待在冰湖城，就只能和雪地里的冰原狼大眼瞪小眼。",
            ["ContentFR"] = "Ces montagnes toutes vertes... et ces arbres rouges et dorés... On a bien fait de venir ! À Givrelac, je n’aurais eu que les loups des neiges pour me tenir compagnie.",
            ["DialogueId"] = 12010004,
            ["GUID"] = "1E10D748",
            ["NextDialogue"] = 12010005,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120100/1E10D748",
            },
        [12010005] = {
            ["Content"] = "小仆从，这就是你们经常说的南方吧。这里和你的家乡像吗？",
            ["ContentFR"] = "Petit larbin, c’est donc ça, le « sud » dont tu parles tout le temps ? Ça ressemble à ton pays ?",
            ["DialogueId"] = 12010005,
            ["GUID"] = "1E10D772",
            ["NextDialogue"] = 12010006,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120100/1E10D772",
            },
        [12010006] = {
            ["Content"] = "有点相似，但又有很多不一样的地方。",
            ["ContentFR"] = "Un peu... mais c’est très différent, aussi.",
            ["DialogueId"] = 12010006,
            ["GUID"] = "1E10D79C",
            ["NextDialogue"] = 12010007,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120100/1E10D79C",
            },
        [12010007] = {
            ["Content"] = "净界岛是个袖珍的小岛，就算是最高点，对于小孩子来说铆足了劲就能一口气冲上去，然后就能看见碧蓝的大海……",
            ["ContentFR"] = "L’Île du Purgatoire est minuscule. Même son point culminant, un enfant peut l’escalader d’une traite... Et tout en haut, il n’y a que le bleu de l’océan à perte de vue.",
            ["DialogueId"] = 12010007,
            ["GUID"] = "1E10D7C6",
            ["NextDialogue"] = 12010008,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120100/1E10D7C6",
            },
        [12010008] = {
            ["Content"] = "止流掌柜，华胥是个怎样的国家呢？",
            ["ContentFR"] = "Patronne Zhiliu, comment est Huaxu, en tant que nation ?",
            ["DialogueId"] = 12010008,
            ["GUID"] = "1E10D7F0",
            ["NextDialogue"] = 12010009,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120100/1E10D7F0",
            },
        [12010009] = {
            ["Content"] = "让我想想……你们所见的，只是华胥的一小部分区域。",
            ["ContentFR"] = "Voyons voir... Ce que vous avez aperçu n’en est qu’une infime parcelle.",
            ["DialogueId"] = 12010009,
            ["GUID"] = "1E10D81A",
            ["NextDialogue"] = 12010010,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120100/1E10D81A",
            },
        [12010010] = {
            ["Content"] = "昔日，华胥先人依靠团结一致的伟力，解决了肆虐于这片土地的秽兽危机。然后扎根下来，逐渐地繁衍生息、开疆拓土。",
            ["ContentFR"] = "Autrefois, nos ancêtres ont uni leurs forces pour mettre fin aux ravages des Souillés.\
Ils se sont ensuite enracinés ici, se sont multipliés... et ont étendu leurs frontières.",
            ["DialogueId"] = 12010010,
            ["GUID"] = "1E10D844",
            ["NextDialogue"] = 12010011,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120100/1E10D844",
            },
        [12010011] = {
            ["Content"] = "如今，这处入海口已经成为了旧都。在华胥广袤的版图中，它只占了一小块，却拥有不容忽视的影响力。",
            ["ContentFR"] = "Aujourd’hui, cet estuaire est devenu l’ancienne capitale. Une simple fraction du territoire de Huaxu, certes... mais une fraction à l’influence considérable.",
            ["DialogueId"] = 12010011,
            ["GUID"] = "1E10D86E",
            ["NextDialogue"] = 12010012,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120100/1E10D86E",
            },
        [12010012] = {
            ["Content"] = "就整个华胥而言，这里地产富足，风景秀美，四季常青，由织星客领衔的贸易发达……",
            ["ContentFR"] = "Dans l’ensemble, Huaxu est une terre fertile, verdoyante toute l’année, où le commerce prospère sous l’égide des Tisse-Étoiles...",
            ["DialogueId"] = 12010012,
            ["GUID"] = "1E10D898",
            ["NextDialogue"] = 12010013,
            ["RelatedWikiId"] = {
                [1] = 405007,
                },
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120100/1E10D898",
            },
        [12010013] = {
            ["Content"] = "呵呵，怎么一脸凝重，莫非是我的介绍太官方了？",
            ["ContentFR"] = "Héhé... Pourquoi cet air si sérieux ? Mon discours était-il trop... officiel ?",
            ["DialogueId"] = 12010013,
            ["GUID"] = "1E10D8C2",
            ["NextOptions"] = {
                [1] = 120100131,
                [2] = 120100132,
                },
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120100/1E10D8C2",
            },
        [12010014] = {
            ["Content"] = "这样吧，说点你们可能感兴趣的。华胥是<H>不动干戈，世无纷争</>的和睦之乡。",
            ["ContentFR"] = "Dans ce cas, parlons de quelque chose de plus marquant. Huaxu est un pays où <H>nul ne lève l’arme, et où les conflits n’ont pas droit de cité</>.",
            ["DialogueId"] = 12010014,
            ["GUID"] = "1E10D8EC",
            ["NextDialogue"] = 12010015,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120100/1E10D8EC",
            },
        [12010015] = {
            ["Content"] = "什么干什么戈……白好像没太听懂！",
            ["ContentFR"] = "Lever quoi... et quel conflit ? Euh... je n’ai rien compris !",
            ["DialogueId"] = 12010015,
            ["GUID"] = "1E10D916",
            ["NextDialogue"] = 12010016,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120100/1E10D916",
            },
        [12010016] = {
            ["Content"] = "唔，意思是，这里没有战争，人们也不会像冰湖城那样动不动打架？",
            ["ContentFR"] = "Elle veut dire... qu’ici, il n’y a pas de guerre. Et que les gens ne se battent pas à tout bout de champ, comme à Givrelac.",
            ["DialogueId"] = 12010016,
            ["GUID"] = "1E10D940",
            ["NextDialogue"] = 12010017,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120100/1E10D940",
            },
        [12010017] = {
            ["Content"] = "嗯。就连鸡鸣狗盗之恶，华胥也早已杜绝。",
            ["ContentFR"] = "Exactement. Même les larcins et les méfaits les plus insignifiants ont disparu depuis longtemps.",
            ["DialogueId"] = 12010017,
            ["GUID"] = "1E10D96A",
            ["NextDialogue"] = 12010018,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120100/1E10D96A",
            },
        [12010018] = {
            ["Content"] = "你该不会是说——华胥没人犯罪？我才不信咧，这种话就是哄小孩子的吧！",
            ["ContentFR"] = "Attends, attends... Tu veux dire qu’il n’y a aucun crime à Huaxu ? Ça ressemble plutôt à une histoire pour enfants !",
            ["DialogueId"] = 12010018,
            ["GUID"] = "1E10D994",
            ["NextDialogue"] = 12010019,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120100/1E10D994",
            },
        [12010019] = {
            ["Content"] = "呵呵……是吗？",
            ["ContentFR"] = "Héhé... Vraiment ?",
            ["DialogueId"] = 12010019,
            ["GUID"] = "1E10D9BE",
            ["NextDialogue"] = 12010020,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120100/1E10D9BE",
            },
        [12010020] = {
            ["Content"] = "止流大当家——",
            ["ContentFR"] = "Patronne Zhiliu — !",
            ["DialogueId"] = 12010020,
            ["GUID"] = "1E10D9E8",
            ["NextDialogue"] = 12010021,
            ["SpeakNpcName"] = "UI_Npc_Name_FarawayVoice",
            ["VoiceName"] = "voice/$Locale$/story/1201/120100/1E10D9E8",
            },
        [12010021] = {
            ["Content"] = "好像码头上有人在叫您。",
            ["ContentFR"] = "On dirait que quelqu’un vous appelle depuis le quai.",
            ["DialogueId"] = 12010021,
            ["GUID"] = "1E10DA12",
            ["NextDialogue"] = 12010022,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120100/1E10DA12",
            },
        [12010022] = {
            ["Content"] = "嗯，我听到了。我们先下船去看看吧。",
            ["ContentFR"] = "Oui. Allons voir.",
            ["DialogueId"] = 12010022,
            ["GUID"] = "1E10DA3C",
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120100/1E10DA3C",
            },
        [12010101] = {
            ["Content"] = "止流大当家。今次的卸货名单，该找哪位清点核对呢？",
            ["ContentFR"] = "Patronne Zhiliu. Pour la liste de déchargement, à qui devons-nous confier la vérification ?",
            ["DialogueId"] = 12010101,
            ["GUID"] = "1E10E732",
            ["NextDialogue"] = 12010102,
            ["SpeakNpcId"] = 210030,
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10E732",
            },
        [12010102] = {
            ["Content"] = "杜立没来吗？我嘱咐过他提早前来接应的。",
            ["ContentFR"] = "Du Li n’est pas venu ? Je lui avais pourtant demandé d’arriver en avance.",
            ["DialogueId"] = 12010102,
            ["GUID"] = "1E10E75C",
            ["NextDialogue"] = 12010103,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10E75C",
            },
        [12010103] = {
            ["Content"] = "这趟运回来了好些贵重货物，有些需要特殊的储运手法，有他盯着，我放心些。",
            ["ContentFR"] = "Cette cargaison contient plusieurs marchandises précieuses. Certaines exigent des conditions de stockage particulières. Sa présence m’aurait rassurée.",
            ["DialogueId"] = 12010103,
            ["GUID"] = "1E10E786",
            ["NextDialogue"] = 12010104,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10E786",
            },
        [12010104] = {
            ["Content"] = "兄弟们打听了一圈，今天码头上没人见过杜管事。",
            ["ContentFR"] = "Nous avons interrogé tout le quai... Personne n’a vu l’intendant Du aujourd’hui.",
            ["DialogueId"] = 12010104,
            ["GUID"] = "1E10E7B0",
            ["NextDialogue"] = 12010105,
            ["SpeakNpcId"] = 210030,
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10E7B0",
            },
        [12010105] = {
            ["Content"] = "嗯……我明白了。他或许是被什么事情拖住了，先在这里等候一下吧。",
            ["ContentFR"] = "Je vois... Il a sans doute été retenu. Attendons ici pour le moment.",
            ["DialogueId"] = 12010105,
            ["GUID"] = "1E10E7DA",
            ["NextDialogue"] = 12010106,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10E7DA",
            },
        [12010106] = {
            ["Content"] = "新鲜出炉的烤鱼嘞——不好吃不要钱——",
            ["ContentFR"] = "Poisson grillé tout juste sorti du feu — pas satisfait, pas payé !",
            ["DialogueId"] = 12010106,
            ["GUID"] = "1E10E804",
            ["NextDialogue"] = 12010107,
            ["SpeakNpcId"] = 210031,
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10E804",
            },
        [12010107] = {
            ["Content"] = "哇——好香啊！",
            ["ContentFR"] = "Ouaaah — ça sent trop bon !",
            ["DialogueId"] = 12010107,
            ["GUID"] = "1E10E82E",
            ["NextDialogue"] = 12010108,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10E82E",
            },
        [12010108] = {
            ["Content"] = "刚刚才在船上吃了小点心，现在又馋了吗？",
            ["ContentFR"] = "Tu as mangé il y a à peine un instant sur le bateau...",
            ["DialogueId"] = 12010108,
            ["GUID"] = "1E10E858",
            ["NextDialogue"] = 12010109,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10E858",
            },
        [12010109] = {
            ["Content"] = "烤鱼是很香没错啦！但感觉空气里还有一股说不上来的香味。",
            ["ContentFR"] = "Le poisson, oui ! Mais il y a autre chose dans l’air... Un parfum étrange...",
            ["DialogueId"] = 12010109,
            ["GUID"] = "1E10E882",
            ["NextDialogue"] = 12010110,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10E882",
            },
        [12010110] = {
            ["Content"] = "有点像花香，又有点像清晨的霜的味道……总之很好闻就是了！",
            ["ContentFR"] = "Un peu floral... un peu comme le givre du matin... Bref, ça sent merveilleusement bon !",
            ["DialogueId"] = 12010110,
            ["GUID"] = "1E10E8AC",
            ["NextDialogue"] = 12010111,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10E8AC",
            },
        [12010111] = {
            ["Content"] = "也是巧合，本该前来接应的人迟到了。{nickname}，你们初来乍到，我就陪你们逛逛吧。",
            ["ContentFR"] = "Une coïncidence opportune. Puisque notre contact se fait attendre, je vais vous accompagner. Après tout, vous venez à peine d’arriver à Huaxu, {nickname}.",
            ["DialogueId"] = 12010111,
            ["GUID"] = "1E10E8D6",
            ["NextDialogue"] = 12010112,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10E8D6",
            },
        [12010112] = {
            ["Content"] = "好耶！那白想看看那边的小吃摊子，那个拨浪鼓看起来也好有意思……还有那里！",
            ["ContentFR"] = "Youpi ! Alors je veux voir ces échoppes là-bas ! Et ce tambourin ! Et... hé, c’est quoi, ça ?!",
            ["DialogueId"] = 12010112,
            ["GUID"] = "1E10E900",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10E900",
            },
        [12010113] = {
            ["Camera"] = "315.296692,492.476501,203.203613,0.000004,-9.399719,-124.991638,35.000011,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "针头线脑、香脂香囊，我这儿样样齐全。客官，要来一份吗？",
            ["ContentFR"] = "Aiguilles, fils, baumes et sachets parfumés. J’ai tout ce qu’il faut. Quelque chose vous intéresse ?",
            ["DialogueId"] = 12010113,
            ["FacialId"] = {
                [1] = "210031:Cin_Smile01",
                },
            ["FinalCamera"] = "311.297241,486.82547,183.789551,0.000005,-7.199613,-125.391396,35.000011,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "1E10E92A",
            ["LookAt"] = {
                [1] = "210031:n(100001)",
                },
            ["NextDialogue"] = 12010114,
            ["RelatedWikiId"] = {
                [1] = 408010,
                [2] = 408011,
                [3] = 203001,
                },
            ["SpeakNpcId"] = 210031,
            ["TalkActionId"] = {
                [1] = "210031:Talk01_Start",
                },
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10E92A",
            },
        [12010114] = {
            ["Content"] = "看中了什么？直接拿吧，我来付账。",
            ["ContentFR"] = "Si quelque chose vous plaît, prenez-le. Je réglerai la note.",
            ["DialogueId"] = 12010114,
            ["FacialId"] = {
                [1] = "210004:Smile01",
                },
            ["GUID"] = "1E10E954",
            ["LookAt"] = {
                [1] = "210004:n(100001)",
                },
            ["NextDialogue"] = 12010115,
            ["SpeakNpcId"] = 210004,
            ["TalkActionId"] = {
                [1] = "210031:Talk01_End",
                [2] = "\
210004:ConfidentR_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10E954",
            },
        [12010115] = {
            ["Camera"] = "-300.496887,-107.604889,166.557129,0.000039,-5.799308,31.399658,50.0,441.88739,false,DoNotOverride,8.0",
            ["Content"] = "你们在华胥的所有开销都由我包揽了，尽管花，让他们记在百年春的账上就行。",
            ["ContentFR"] = "Toutes vos dépenses à Huaxu sont à ma charge. Qu’ils les inscrivent simplement sur le compte d’Éternel Printemps.",
            ["DialogueId"] = 12010115,
            ["FinalCamera"] = "-302.217896,-104.770386,166.557129,0.000039,-5.799308,31.399658,50.0,441.88739,false,DoNotOverride,8.0",
            ["GUID"] = "1E10E97E",
            ["LookAt"] = {
                [1] = "100001:n(210004)",
                },
            ["NextOptions"] = {
                [1] = 120101151,
                [2] = 120101152,
                },
            ["SpeakNpcId"] = 210004,
            ["TalkActionId"] = {
                [1] = "210004:ConfidentRToTalk_Start",
                },
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10E97E",
            },
        [12010116] = {
            ["Camera"] = "-166.510681,150.144012,125.549805,0.000042,2.600478,-8.198592,50.0,257.556915,false,DoNotOverride,8.0",
            ["Content"] = "呵呵……放心。这些小钱，我供得起。",
            ["ContentFR"] = "Héhé... ne t’inquiète pas. Ces sommes sont négligeables pour moi.",
            ["DialogueId"] = 12010116,
            ["GUID"] = "1E10E9A8",
            ["NextDialogue"] = 12010117,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10E9A8",
            },
        [12010117] = {
            ["Camera"] = "-258.889587,722.140747,375.999023,0.000044,-22.399721,-67.201347,35.0,257.556915,false,DoNotOverride,8.0",
            ["Content"] = "止流大当家！您办事归来了。原来这位<H>有龙氏</>是您邀请的客人。",
            ["ContentFR"] = "Patronne Zhiliu ! Vous voilà de retour après vos affaires. Ainsi, {性别:ce <H>Descendant draconique</> est votre invité|cette <H>Descendante draconique</> est votre invitée} ?",
            ["DialogueId"] = 12010117,
            ["GUID"] = "1E10E9D2",
            ["LookAt"] = {
                [1] = "210031:n(210004)",
                [2] = "\
210004:n(210031)",
                [3] = "\
100001:n(210031)",
                },
            ["NextDialogue"] = 12010118,
            ["RelatedWikiId"] = {
                [1] = 405008,
                },
            ["SpeakNpcId"] = 210031,
            ["TalkActionId"] = {
                [1] = "210004:ConfidentRToTalk_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10E9D2",
            },
        [12010118] = {
            ["Camera"] = "-148.47049,-63.694336,115.687988,0.000015,3.201023,52.205986,50.000008,354.199371,false,DoNotOverride,8.0",
            ["Content"] = "瞧{性别：他|她}的角，小巧、坚硬又有光泽，一看便有成龙之相。真是优秀的后生，让人看着就心生欢喜。",
            ["ContentFR"] = "Regardez-moi ses cornes : petites, solides, brillantes... Un signe de grandeur à venir. Une jeune personne qui inspire naturellement la bienveillance.",
            ["DialogueId"] = 12010118,
            ["FinalCamera"] = "-145.448669,-59.758316,115.963867,0.000015,3.201023,52.205986,50.000008,354.199371,false,DoNotOverride,8.0",
            ["GUID"] = "1E10E9FC",
            ["NextDialogue"] = 12010119,
            ["SpeakNpcId"] = 210031,
            ["TalkActionId"] = {
                [1] = "210004:ConfidentR_End",
                },
            ["ToFinalCameraBlendTime"] = 11,
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10E9FC",
            },
        [12010119] = {
            ["Camera"] = "-23.817619,-70.792191,153.86084,0.00002,-4.399809,81.994202,50.0,147.841843,false,DoNotOverride,8.0",
            ["Content"] = "有龙氏……止流掌柜，你们是在说我吗？",
            ["ContentFR"] = "« {性别:Descendant draconique|Descendante draconique} »... Patronne Zhiliu, vous parliez de moi ?",
            ["DialogueId"] = 12010119,
            ["FacialId"] = {
                [1] = "100001:Curious",
                },
            ["FinalCamera"] = "-23.817619,-70.792191,153.86084,0.00002,-4.399809,81.994202,53.0,147.841843,false,DoNotOverride,8.0",
            ["GUID"] = "1E10EA26",
            ["NextDialogue"] = 12010120,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:ScratchHead_Start",
                },
            ["ToFinalCameraBlendTime"] = 6,
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10EA26",
            },
        [12010120] = {
            ["Camera"] = "-166.510681,150.144012,125.549805,0.000042,2.600478,-8.198592,50.0,257.556915,false,DoNotOverride,8.0",
            ["Content"] = "忘了告诉你，有龙氏是华胥文化中对于卡戎的称呼。不同于海伯利亚的歧视与打压，在这里，卡戎被视为护佑国家的祥瑞种族。",
            ["ContentFR"] = "J’ai omis de vous le préciser. À Huaxu, Descendant draconique est le nom que nous donnons aux Charons. Contrairement à l’Empire Hyperboréen, où ils sont discriminés et opprimés, ici, ils sont considérés comme une lignée de bon augure, vouée à protéger la nation.",
            ["DialogueId"] = 12010120,
            ["GUID"] = "1E10EA50",
            ["LookAt"] = {
                [1] = "210004:n(100001)",
                [2] = "100001:n(210004)",
                },
            ["NextDialogue"] = 12010121,
            ["SpeakNpcId"] = 210004,
            ["TalkActionId"] = {
                [1] = "100001:ScratchHead_End",
                [2] = "210004:Explain01L_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10EA50",
            },
        [12010121] = {
            ["Content"] = "当初我遇见你时，看见年幼的有龙氏被旁人刁难，忍不住照拂了一下。",
            ["ContentFR"] = "Lorsque je vous ai {性别:rencontré|rencontrée} pour la première fois, voir {性别:un jeune Descendant draconique pris|une jeune Descendante draconique prise} à partie par les autres m’a été difficile à ignorer. J’ai donc choisi d’intervenir.",
            ["DialogueId"] = 12010121,
            ["FacialId"] = {
                [1] = "210004:Smile02",
                },
            ["GUID"] = "1E10EA7A",
            ["NextDialogue"] = 12010122,
            ["SpeakNpcId"] = 210004,
            ["TalkActionId"] = {
                [1] = "210004:Explain01L_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10EA7A",
            },
        [12010122] = {
            ["Camera"] = "-68.049751,89.252998,97.667969,0.000073,16.599312,8.000803,35.0,176.801208,false,DoNotOverride,8.0",
            ["Content"] = "这样说来……止流掌柜也是卡戎——啊，有龙氏。我那时就好奇过您的身份，您看起来地位并不普通。",
            ["ContentFR"] = "Dans ce cas... Patronne Zhiliu, vous êtes aussi une Charon — pardon, une Descendante draconique. Je me doutais bien que votre statut n’était pas ordinaire.",
            ["DialogueId"] = 12010122,
            ["FinalCamera"] = "-68.049751,89.252998,97.667969,0.000073,16.599312,8.000803,38.0,176.801208,false,DoNotOverride,8.0",
            ["GUID"] = "1E10EAA4",
            ["NextDialogue"] = 12010123,
            ["SpeakNpcId"] = 100001,
            ["ToFinalCameraBlendTime"] = 6,
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10EAA4",
            },
        [12010123] = {
            ["Camera"] = "-258.889587,722.140747,375.999023,0.000044,-22.399721,-67.201347,35.0,257.556915,false,DoNotOverride,8.0",
            ["Content"] = "呵呵……{性别：小弟弟|小妹妹}，你觉得止流大当家是什么身份？",
            ["ContentFR"] = "Héhé... {性别:jeune homme|jeune femme}, à votre avis, qui est vraiment la Patronne Zhiliu ?",
            ["DialogueId"] = 12010123,
            ["GUID"] = "1E10EACE",
            ["LookAt"] = {
                [1] = "210031:n(100001)",
                [2] = "\
210004:n(210031)",
                [3] = "\
100001:n(210031)",
                },
            ["NextOptions"] = {
                [1] = 120101231,
                [2] = 120101232,
                },
            ["SpeakNpcId"] = 210031,
            ["TalkActionId"] = {
                [1] = "210031:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10EACE",
            },
        [12010124] = {
            ["Camera"] = "-300.496887,-107.604889,166.557129,0.000039,-5.799308,31.399658,50.0,441.88739,false,DoNotOverride,8.0",
            ["Content"] = "她可是年纪尚轻时，就获得了天命青睐，当上了<H>龙渊上卿</>。如今她司掌天禄司，就是说呀，咱们华胥所有贸易、财政、收税都归她管。",
            ["ContentFR"] = "Figurez-vous qu’elle a été choisie par le Mandat Céleste alors qu’elle était encore bien jeune, et qu’elle est devenue le Haut Chancelier de Longyuan. À Huaxu, le commerce, les finances, les taxes... tout passe par elle.",
            ["DialogueId"] = 12010124,
            ["FacialId"] = {
                [1] = "210004:Smile01",
                },
            ["FinalCamera"] = "-302.217896,-104.770386,166.557129,0.000039,-5.799308,31.399658,50.0,441.88739,false,DoNotOverride,8.0",
            ["GUID"] = "1E10EAF8",
            ["NextDialogue"] = 12010125,
            ["RelatedWikiId"] = {
                [1] = 407005,
                },
            ["SpeakNpcId"] = 210031,
            ["TalkActionId"] = {
                [1] = "210004:Talk03_Start",
                },
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10EAF8",
            },
        [12010125] = {
            ["Content"] = "只是，止流大当家为人平易近人，平日里不准我们称呼她的官职，只愿我们以大当家的头衔相称。在这里做生意的人，多多少少都承过她的人情。",
            ["ContentFR"] = "Pourtant, elle nous interdit de l’appeler par son titre officiel. Ici, elle n’est que la « Patronne ». Tous les commerçants de Huaxu lui doivent quelque chose.",
            ["DialogueId"] = 12010125,
            ["GUID"] = "1E10EB22",
            ["NextDialogue"] = 12010126,
            ["SpeakNpcId"] = 210031,
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10EB22",
            },
        [12010126] = {
            ["Content"] = "……只是没有刻意提起的必要罢了。毕竟，以势压人，不如以理服人来得妥当。",
            ["ContentFR"] = "... Il n’y avait simplement aucune raison d’en faire état. L’autorité impose, mais la raison convainc.",
            ["DialogueId"] = 12010126,
            ["GUID"] = "1E10EB4C",
            ["NextDialogue"] = 12010127,
            ["SpeakNpcId"] = 210004,
            ["TalkActionId"] = {
                [1] = "210004:DisagreeHead",
                [2] = "210031:Explain01_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10EB4C",
            },
        [12010127] = {
            ["Camera"] = "-68.959076,68.54129,118.671875,0.000075,7.399253,11.199726,35.0,165.19751,false,DoNotOverride,8.0",
            ["Content"] = "商人这个身份，进可织星揽月，退可通权达变。比起一官半职来，倒是更符合我的喜好。",
            ["ContentFR"] = "Être marchande me convient mieux. Avancer permet de tisser les étoiles... Reculer, d’ajuster les leviers du pouvoir.",
            ["DialogueId"] = 12010127,
            ["FinalCamera"] = "-68.959076,68.54129,118.671875,0.000075,7.399253,11.199726,38.0,165.19751,false,DoNotOverride,8.0",
            ["GUID"] = "1E10EB76",
            ["NextDialogue"] = 12010128,
            ["SpeakNpcId"] = 210004,
            ["TalkActionId"] = {
                [1] = "210004:Talk03ToTalkL_Start",
                },
            ["ToFinalCameraBlendTime"] = 6,
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10EB76",
            },
        [12010128] = {
            ["Camera"] = "315.296692,492.476501,203.203613,0.000004,-9.399719,-124.991638,35.000011,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "来，{性别：小弟弟|小妹妹}。止流大当家难得带贵客来。这件香囊你就作为见面礼收下吧。",
            ["ContentFR"] = "Tenez, {性别:jeune homme|jeune femme}. Puisque vous êtes l’invité de la Patronne, acceptez ce cadeau de bienvenue.",
            ["DialogueId"] = 12010128,
            ["FinalCamera"] = "311.297241,486.82547,183.789551,0.000005,-7.199613,-125.391396,35.000011,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "1E10EBA0",
            ["NextOptions"] = {
                [1] = 120101281,
                [2] = 120101282,
                },
            ["SpeakNpcId"] = 210031,
            ["TalkActionId"] = {
                [1] = "210004:Talk03ToTalkL_End",
                [2] = "210031:Give",
                },
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10EBA0",
            },
        [12010129] = {
            ["Content"] = "<H>香</>在华胥可是有着大作用。定气凝神，防身护体，个中妙用，你很快就能体悟到了。",
            ["ContentFR"] = "À Huaxu, le <H>parfum</> joue un rôle essentiel. Il stabilise le souffle, apaise l’esprit et protège le corps. Quant à ses usages les plus subtils... vous ne tarderez pas à les comprendre.",
            ["DialogueId"] = 12010129,
            ["FacialId"] = {
                [1] = "210031:Cin_Happy01",
                },
            ["GUID"] = "1E10EBCA",
            ["RelatedWikiId"] = {
                [1] = 403005,
                },
            ["SpeakNpcId"] = 210031,
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10EBCA",
            },
        [12010130] = {
            ["Content"] = "烤鱿鱼还是香喷喷的小银鱼干，唔，好难选哦……",
            ["ContentFR"] = "Calmars grillés ou petits poissons argentés séchés... <I>Gnh...</> je sais pas quoi prendre...",
            ["DialogueId"] = 12010130,
            ["Duration"] = 3,
            ["GUID"] = "1E10EBF4",
            ["NextDialogue"] = 12010131,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10EBF4",
            },
        [12010131] = {
            ["Content"] = "老板，一样来一份好了！多来点酱汁！",
            ["ContentFR"] = "Patron ! Les deux ! Et plein de sauce !",
            ["DialogueId"] = 12010131,
            ["GUID"] = "1E10EC1E",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10EC1E",
            },
        [12010132] = {
            ["Content"] = "咦，白跑到哪里去了……",
            ["ContentFR"] = "Tiens... où est passée Snow... ?",
            ["DialogueId"] = 12010132,
            ["GUID"] = "1E10EC48",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10EC48",
            },
        [12010201] = {
            ["Camera"] = "26.601562,-263.371094,126.632324,0.0,-8.000487,77.603035,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "所以说，梦想是很重要的——比如白的梦想，就是成为世界第一的大魔王！",
            ["ContentFR"] = "Voilà pourquoi les rêves sont si importants ! Par exemple, mon rêve à moi, c’est de devenir le plus grand Roi Démon du monde !",
            ["DialogueId"] = 12010201,
            ["GUID"] = "1E10F79A",
            ["NextDialogue"] = 12010202,
            ["RelatedWikiId"] = {
                [1] = 408010,
                [2] = 408011,
                },
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10F79A",
            },
        [12010202] = {
            ["Content"] = "哇，说的太好了！",
            ["ContentFR"] = "Ouaaah... c’est tellement inspirant !",
            ["DialogueId"] = 12010202,
            ["GUID"] = "1E10F7C4",
            ["NextDialogue"] = 12010203,
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10F7C4",
            },
        [12010203] = {
            ["Content"] = "你看，华胥的这片码头有这么大对吧。今后本魔王大人的宫殿要比它大十倍！",
            ["ContentFR"] = "Regarde ce quai de Huaxu. Il est immense, pas vrai ? Eh bien, un jour, le palais du Roi Démon sera dix fois plus grand encore !",
            ["DialogueId"] = 12010203,
            ["GUID"] = "1E10F7EE",
            ["NextDialogue"] = 12010204,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10F7EE",
            },
        [12010204] = {
            ["Content"] = "等梦想实现后，白每天就能睡到下午三点，然后从长一百米的大床上醒来，享用搜罗了全世界所有小蛋糕的豪华下午茶！",
            ["ContentFR"] = "Et quand mon rêve se réalisera, je dormirai tous les jours jusqu’à quinze heures pile...\
Je me réveillerai dans un lit long de cent mètres... Et je prendrai un goûter somptueux, avec tous les petits gâteaux du monde !",
            ["DialogueId"] = 12010204,
            ["GUID"] = "1E10F818",
            ["NextDialogue"] = 12010205,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10F818",
            },
        [12010205] = {
            ["Content"] = "那……我要成为青史留名的织星客，在人类的史书上，写下皎皎一族的名字！",
            ["ContentFR"] = "Alors... moi aussi, je veux entrer dans l’Histoire ! Je deviendrai une Tisse-Étoiles légendaire, et j’inscrirai le nom de mon peuple dans les chroniques humaines !",
            ["DialogueId"] = 12010205,
            ["GUID"] = "1E10F842",
            ["NextDialogue"] = 12010206,
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10F842",
            },
        [12010206] = {
            ["Content"] = "到时候，从现在这里到遥远的对岸，整个码头都要铺满我的货物。每个集装箱上都要画一个硕大的皎皎涂鸦！",
            ["ContentFR"] = "D’ici jusqu’à l’autre rive, tout le quai sera couvert de mes marchandises ! Et sur chaque conteneur, il y aura un gigantesque graffiti Luno !",
            ["DialogueId"] = 12010206,
            ["GUID"] = "1E10F86C",
            ["NextDialogue"] = 12010207,
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10F86C",
            },
        [12010207] = {
            ["Content"] = "很好，就要这个气势！大声喊出来，皎皎之民征服世界——",
            ["ContentFR"] = "Parfait ! Voilà l’esprit qu’il faut ! Allez, dis-le à pleine voix : les Lunariens à la conquête du monde— !",
            ["DialogueId"] = 12010207,
            ["GUID"] = "1E10F896",
            ["NextDialogue"] = 12010208,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10F896",
            },
        [12010208] = {
            ["Content"] = "呜呜……早上起床时，我向白龙神君祈愿，希望今天可以撞见好运。",
            ["ContentFR"] = "Ou... ouiiiin... Ce matin, j’ai prié le Seigneur Dragon d’Argent, en espérant que la chance me sourirait aujourd’hui...",
            ["DialogueId"] = 12010208,
            ["GUID"] = "1E10F8C0",
            ["NextDialogue"] = 12010209,
            ["RelatedWikiId"] = {
                [1] = 303008,
                },
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10F8C0",
            },
        [12010209] = {
            ["Content"] = "本来只是指望来码头进货时，可以从那些抠门织星客手中再抢下几个单子。没想到，有生之年，竟然能让我看到活的有角皎皎……",
            ["ContentFR"] = "Je voulais juste obtenir quelques contrats de plus, en marchandant avec ces Tisse-Étoiles radins... Je n’aurais jamais cru que, de mon vivant, je rencontrerais une véritable Luno cornue...",
            ["DialogueId"] = 12010209,
            ["GUID"] = "1E10F8EA",
            ["NextDialogue"] = 12010210,
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10F8EA",
            },
        [12010210] = {
            ["Camera"] = "345.640625,-174.457031,104.969238,0.000003,-0.600497,140.202652,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "看来白龙神君大人终于回应我的诚心了……那个，尊贵的魔王殿下，可以让我再摸一下你的角吗？",
            ["ContentFR"] = "On dirait que le Seigneur Dragon d’Argent a enfin répondu à mes prières... Euh... Votre Majesté le Roi Démon, est-ce que je peux... toucher vos cornes encore une fois ?",
            ["DialogueId"] = 12010210,
            ["GUID"] = "1E10F914",
            ["LookAt"] = {
                [1] = "100001:n(200002)",
                },
            ["NextOptions"] = {
                [1] = 120102101,
                [2] = 120102102,
                },
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10F914",
            },
        [12010211] = {
            ["Content"] = "小仆从，你怎么来了……你、你都听见了？",
            ["ContentFR"] = "P-Petit larbin ?! D-Depuis quand est-ce que tu es là... ? T-Tu as tout entendu ?!",
            ["DialogueId"] = 12010211,
            ["GUID"] = "1E10F93E",
            ["NextOptions"] = {
                [1] = 120102111,
                [2] = 120102112,
                },
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10F93E",
            },
        [12010212] = {
            ["Content"] = "咳咳……这就是本魔王麾下的得力大将，{nickname}。",
            ["ContentFR"] = "<I>Ahem...</> Voici mon plus fidèle général, le pilier de mon armée démoniaque... {nickname} !",
            ["DialogueId"] = 12010212,
            ["GUID"] = "1E10F968",
            ["NextDialogue"] = 12010213,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10F968",
            },
        [12010213] = {
            ["Content"] = "哇——不愧是魔王大人，竟然能吸引一位有龙氏前来效忠。幸会，我是即将成为华胥第一织星客的锦鲤皎皎！",
            ["ContentFR"] = "Ouaaah ! Votre Majesté est incroyable ! Même {性别:un <H>Descendant draconique</> a juré|une <H>Descendante draconique</> a juré} de vous servir ! Enchantée ! Je suis Luno, la carpe — future première Tisse-Étoiles de Huaxu !",
            ["DialogueId"] = 12010213,
            ["GUID"] = "1E10F992",
            ["NextDialogue"] = 12010214,
            ["RelatedWikiId"] = {
                [1] = 203002,
                },
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10F992",
            },
        [12010214] = {
            ["Camera"] = "422.453125,1255.105469,437.982422,0.00003,-8.400634,-104.197899,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "白，止流掌柜还在等着我们呢。玩够了就赶紧回去吧。",
            ["ContentFR"] = "Snow, la Patronne Zhiliu nous attend toujours. Si tu as fini de jouer, on devrait y retourner.",
            ["DialogueId"] = 12010214,
            ["GUID"] = "1E10F9BC",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10F9BC",
            },
        [12010215] = {
            ["Camera"] = "-387.542969,474.4375,151.621582,0.000187,-2.20303,-35.42408,35.0,100000.0,false,Manual,12.0",
            ["Content"] = "止流掌柜——我把白找回来了。",
            ["ContentFR"] = "Patronne Zhiliu... j’ai ramené Snow.",
            ["DialogueId"] = 12010215,
            ["GUID"] = "1E10F9E6",
            ["NextDialogue"] = 12010216,
            ["RelatedWikiId"] = {
                [1] = 408010,
                [2] = 408011,
                [3] = 203001,
                },
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10F9E6",
            },
        [12010216] = {
            ["Content"] = "……一群**养的！没完没了！",
            ["ContentFR"] = "... Bande de saletés élevées comme du bétail ! Ça suffit !",
            ["DialogueId"] = 12010216,
            ["GUID"] = "1E10FA10",
            ["NextDialogue"] = 12010217,
            ["SpeakNpcId"] = 210002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10FA10",
            },
        [12010217] = {
            ["Camera"] = "192.5,215.453125,162.744141,0.000181,-5.402953,-76.421349,35.0,100000.0,false,Manual,12.0",
            ["Content"] = "……小心！！！",
            ["ContentFR"] = "... Attention !",
            ["DialogueId"] = 12010217,
            ["GUID"] = "1E10FA3A",
            ["NextDialogue"] = 12010218,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10FA3A",
            },
        [12010218] = {
            ["Camera"] = "999.449219,-469.097656,578.913574,0.000173,-25.402763,150.978256,35.0,100000.0,false,Manual,12.0",
            ["Content"] = "喂，你就是这里的舵手吧？赶紧驾船带老子离开这个鬼地方，越快越好！",
            ["ContentFR"] = "Hé, toi, le timonier ! Tu vas me faire quitter ce fichu endroit, et vite ! J’en ai rien à faire d’où !",
            ["DialogueId"] = 12010218,
            ["GUID"] = "1E10FA64",
            ["NextDialogue"] = 12010219,
            ["SpeakNpcId"] = 210002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10FA64",
            },
        [12010219] = {
            ["Content"] = "胆敢轻举妄动，或者做什么手脚，老子一刀嘎了你。",
            ["ContentFR"] = "Essaie quoi que ce soit... et je t’ouvre la gorge.",
            ["DialogueId"] = 12010219,
            ["GUID"] = "1E10FA8E",
            ["NextDialogue"] = 12010220,
            ["SpeakNpcId"] = 210002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10FA8E",
            },
        [12010220] = {
            ["Content"] = "放开他！",
            ["ContentFR"] = "Lâche-le !",
            ["DialogueId"] = 12010220,
            ["GUID"] = "1E10FAB8",
            ["NextDialogue"] = 12010221,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10FAB8",
            },
        [12010221] = {
            ["Camera"] = "-863.470703,299.425781,276.108887,0.000178,-7.60267,-14.021979,35.0,100000.0,false,Manual,12.0",
            ["Content"] = "冷静点，{nickname}，不用出手。",
            ["ContentFR"] = "Du calme, {nickname}. Inutile d’intervenir.",
            ["DialogueId"] = 12010221,
            ["GUID"] = "1E10FAE2",
            ["NextDialogue"] = 12010222,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10FAE2",
            },
        [12010222] = {
            ["Content"] = "可是刀都架在船夫的脖子上了！明明是这么紧急的情况，你们怎么还能这么淡定！",
            ["ContentFR"] = "Mais... il a un couteau sous la gorge du batelier ! Comment pouvez-vous rester aussi calmes ?!",
            ["DialogueId"] = 12010222,
            ["GUID"] = "1E10FB0C",
            ["NextDialogue"] = 12010223,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10FB0C",
            },
        [12010223] = {
            ["Content"] = "这位劫匪大约是外来者，尚未熟悉这里的规矩。",
            ["ContentFR"] = "Cet individu est sans doute un étranger, encore ignorant des règles en vigueur ici.",
            ["DialogueId"] = 12010223,
            ["GUID"] = "1E10FB36",
            ["NextDialogue"] = 12010224,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10FB36",
            },
        [12010224] = {
            ["Content"] = "记得我先前所说吗？华胥是<H>止戈之乡</>。也好，让你们有机会亲眼见证——",
            ["ContentFR"] = "Vous souvenez-vous de ce que je vous ai dit ? Huaxu est une <H>terre où l’on ne lève pas les armes</>. Voilà qui vous offrira l’occasion de le constater de vos propres yeux—",
            ["DialogueId"] = 12010224,
            ["GUID"] = "1E10FB60",
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10FB60",
            },
        [12010225] = {
            ["Content"] = "嗷呜——",
            ["ContentFR"] = "Rrraah— !",
            ["DialogueId"] = 12010225,
            ["GUID"] = "1E10FB8A",
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10FB8A",
            },
        }
  end },
  { MinKey = 12010226, MaxKey = 12010909, Loader = function()
      return {
        [12010226] = {
            ["Content"] = "又是这些东西，怎么阴魂不散的！",
            ["ContentFR"] = "Encore ces saletés... Pourquoi est-ce que— ?!",
            ["DialogueId"] = 12010226,
            ["GUID"] = "1E10FBB4",
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10FBB4",
            },
        [12010227] = {
            ["Camera"] = "-78.574219,498.462891,113.020996,0.000014,-0.99994,-74.596542,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "那、那是什么……？",
            ["ContentFR"] = "C-Qu’est-ce que... c’était... ?",
            ["DialogueId"] = 12010227,
            ["GUID"] = "1E10FBDE",
            ["NextDialogue"] = 12010228,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10FBDE",
            },
        [12010228] = {
            ["Content"] = "小仆从，看到了吗！那个家伙只用了一招就让坏人消失了诶。",
            ["ContentFR"] = "Petit larbin, tu as vu ça ?! Il l’a fait disparaître en un seul coup ! C’était... c’était incroyable !",
            ["DialogueId"] = 12010228,
            ["GUID"] = "1E10FC08",
            ["NextDialogue"] = 12010229,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10FC08",
            },
        [12010229] = {
            ["Content"] = "<H>大风有隧，有空大谷。有兽狴犴，乘风而行。香尘扰扰，缘有罪因。</>这是华胥子民从牙牙学语时便能念诵的歌谣。",
            ["ContentFR"] = "<H>« Dans les couloirs du vent, s’ouvrent les vallées du vide. Le Bi’an chevauche les rafales. La poussière parfumée s’élève — née du péché et de la faute. »</> C’est une comptine que les enfants de Huaxu apprennent dès leurs premiers mots.",
            ["DialogueId"] = 12010229,
            ["GUID"] = "1E10FC32",
            ["NextDialogue"] = 12010230,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10FC32",
            },
        [12010230] = {
            ["Content"] = "歌谣中的“狴犴”，便是你们所见之物——华胥的守护者。",
            ["ContentFR"] = "Le Bi’an de cette chanson... est le gardien que vous venez de voir.",
            ["DialogueId"] = 12010230,
            ["GUID"] = "1E10FC5C",
            ["NextDialogue"] = 12010231,
            ["RelatedWikiId"] = {
                [1] = 303009,
                },
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10FC5C",
            },
        [12010231] = {
            ["Content"] = "华胥全境被一种无声无形、但又恒常流转之法则，<H>大风九章</>所统御。任何人只要踏入了华胥的界域，就会进入大风九章的保护范围内。",
            ["ContentFR"] = "Huaxu tout entier est régi par une loi invisible, constante, connue sous le nom des <H>Neuf Chapitres de Dafeng</>. Quiconque pénètre sur cette terre se trouve aussitôt sous sa protection.",
            ["DialogueId"] = 12010231,
            ["GUID"] = "1E10FC86",
            ["NextDialogue"] = 12010232,
            ["RelatedWikiId"] = {
                [1] = 304003,
                },
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10FC86",
            },
        [12010232] = {
            ["Content"] = "对于触犯诫律者，狴犴会从凛风中突现，施以惩戒。",
            ["ContentFR"] = "Et lorsque quelqu’un enfreint ses préceptes... le Bi’an surgit des vents pour rendre jugement.",
            ["DialogueId"] = 12010232,
            ["GUID"] = "1E10FCB0",
            ["NextDialogue"] = 12010233,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10FCB0",
            },
        [12010233] = {
            ["Content"] = "原来，这就是这里完全杜绝犯罪的理由……",
            ["ContentFR"] = "Alors... c’est pour ça qu’il n’y a vraiment aucun crime ici...",
            ["DialogueId"] = 12010233,
            ["GUID"] = "1E10FCDA",
            ["NextDialogue"] = 12010234,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10FCDA",
            },
        [12010234] = {
            ["Content"] = "只是不知何故，出现了不懂规矩的外来者。看来，这一趟办事归来，倒是有些“惊喜”等着我呢。",
            ["ContentFR"] = "Pourtant, certains étrangers semblent encore ignorer ces règles. Il semblerait que, durant mon absence, quelques \"surprises\" aient été laissées derrière moi.",
            ["DialogueId"] = 12010234,
            ["GUID"] = "1E10FD04",
            ["NextDialogue"] = 12010235,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10FD04",
            },
        [12010235] = {
            ["Content"] = "大当家——不好意思，属下来迟了——",
            ["ContentFR"] = "Patronne— ! Veuillez m’excuser pour ce retard !",
            ["DialogueId"] = 12010235,
            ["GUID"] = "1E10FD2E",
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10FD2E",
            },
        [12010301] = {
            ["Camera"] = "-156.389893,790.13324,235.143555,0.00015,-10.001431,-71.777824,50.0,856.361206,false,DoNotOverride,2.8",
            ["Content"] = "幸好歹人已经被截获了……他竟然跑到这里来，惊扰到了您。",
            ["ContentFR"] = "Heureusement... le malfaiteur a déjà été intercepté... Il a réussi à venir jusqu’ici et vous a causé du trouble. Je vous prie de m’en excuser.",
            ["DialogueId"] = 12010301,
            ["FacialId"] = {
                [1] = "210032:Cin_Sad01",
                },
            ["FinalCamera"] = "-137.076416,731.468506,224.247559,0.00015,-10.001431,-71.777466,50.0,856.361206,false,DoNotOverride,2.8",
            ["GUID"] = "1E110802",
            ["LookAt"] = {
                [1] = "100001:n(210032)",
                [2] = "210004:n(210032)",
                [3] = "210003:n(210032)",
                },
            ["NextDialogue"] = 12010302,
            ["RelatedWikiId"] = {
                [1] = 408010,
                [2] = 408011,
                [3] = 203001,
                [4] = 303009,
                [5] = 304003,
                },
            ["SpeakNpcId"] = 210032,
            ["TalkActionId"] = {
                [1] = "210032:Explain02_Start",
                [2] = "210004:ConfidentR_Start",
                },
            ["ToFinalCameraBlendTime"] = 6,
            ["VoiceName"] = "voice/$Locale$/story/1201/120103/1E110802",
            },
        [12010302] = {
            ["Camera"] = "-53.126144,-142.106125,132.289062,0.000153,-0.802465,48.999199,50.0,257.290894,false,DoNotOverride,2.8",
            ["Content"] = "杜立，不用急。调顺了气息再说话。",
            ["ContentFR"] = "Du Li, inutile de vous presser ainsi. Reprenez votre souffle avant de parler.",
            ["DialogueId"] = 12010302,
            ["FacialId"] = {
                [1] = "210004:Unhappy01",
                },
            ["FinalCamera"] = "-24.557076,-109.239418,131.683594,0.000153,-0.802465,48.999199,50.0,257.290894,false,DoNotOverride,2.8",
            ["GUID"] = "1E11082C",
            ["NextDialogue"] = 12010303,
            ["SpeakNpcId"] = 210004,
            ["TalkActionId"] = {
                [1] = "210032:Explain02_End",
                [2] = "210004:ConfidentRToExplain_Start",
                },
            ["ToFinalCameraBlendTime"] = 6,
            ["VoiceName"] = "voice/$Locale$/story/1201/120103/1E11082C",
            },
        [12010303] = {
            ["Content"] = "你迟来的理由，和这个歹徒有关吗？",
            ["ContentFR"] = "Votre retard... est-il lié à cet individu ?",
            ["DialogueId"] = 12010303,
            ["GUID"] = "1E110856",
            ["NextDialogue"] = 12010304,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120103/1E110856",
            },
        [12010304] = {
            ["Camera"] = "80.523117,233.023392,157.48584,0.000134,-5.002382,-84.793343,35.0,422.948425,false,DoNotOverride,2.8",
            ["Content"] = "……确是如此。",
            ["ContentFR"] = "... Oui. C’est bien le cas.",
            ["DialogueId"] = 12010304,
            ["FinalCamera"] = "83.662094,198.468262,154.45166,0.000134,-5.002382,-84.793343,35.0,422.948425,false,DoNotOverride,2.8",
            ["GUID"] = "1E110880",
            ["LookAt"] = {
                [1] = "210032:n(210004)",
                },
            ["NextDialogue"] = 12010305,
            ["SpeakNpcId"] = 210032,
            ["TalkActionId"] = {
                [1] = "210004:ConfidentRToExplain_End",
                [2] = "210032:Agree",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1201/120103/1E110880",
            },
        [12010305] = {
            ["Content"] = "最近<W>烛阴之灾</>势头愈烈。部分织星客对禁行令不满，绕开我们百年春，私自从外界雇了护卫，欲与险境一搏。",
            ["ContentFR"] = "Ces derniers temps, le <H>Fléau de Zhuyin</> gagne en intensité. Certains Tisse-Étoiles, mécontents du Décret d’Interdiction, ont contourné Éternel Printemps. Ils ont engagé des gardes venus de l’extérieur, décidés à braver les zones dangereuses.",
            ["DialogueId"] = 12010305,
            ["GUID"] = "1E1108AA",
            ["NextDialogue"] = 12010306,
            ["RelatedWikiId"] = {
                [1] = 304004,
                },
            ["SpeakNpcId"] = 210032,
            ["TalkActionId"] = {
                [1] = "210032:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120103/1E1108AA",
            },
        [12010306] = {
            ["Content"] = "结果找来了个品行不端的，就有了现在这个结果。",
            ["ContentFR"] = "Malheureusement, ils ont recruté quelqu’un de peu recommandable... et cela a mené à la situation que vous venez de voir.",
            ["DialogueId"] = 12010306,
            ["GUID"] = "1E1108D4",
            ["NextDialogue"] = 12010307,
            ["SpeakNpcId"] = 210032,
            ["VoiceName"] = "voice/$Locale$/story/1201/120103/1E1108D4",
            },
        [12010307] = {
            ["Camera"] = "-24.557076,-109.239418,131.683594,0.000153,-0.802465,48.999199,50.0,257.290894,false,DoNotOverride,2.8",
            ["Content"] = "我赶来前，商人们还在为这事争执不休，吵得百年春前那叫一个沸反盈天。恐怕还需要您赶紧出面，从中调解一下。",
            ["ContentFR"] = "Avant mon départ, les marchands se disputaient encore violemment à ce sujet. Devant Éternel Printemps, le tumulte était tel qu’il en devenait assourdissant. Je crains que votre intervention ne soit nécessaire pour apaiser les esprits.",
            ["DialogueId"] = 12010307,
            ["GUID"] = "1E1108FE",
            ["NextDialogue"] = 12010308,
            ["SpeakNpcId"] = 210032,
            ["VoiceName"] = "voice/$Locale$/story/1201/120103/1E1108FE",
            },
        [12010308] = {
            ["Content"] = "嗯，大致情况我了解了。",
            ["ContentFR"] = "Hm... Je comprends l’essentiel de la situation.",
            ["DialogueId"] = 12010308,
            ["FacialId"] = {
                [1] = "210004:None",
                },
            ["GUID"] = "1E110928",
            ["NextDialogue"] = 12010309,
            ["SpeakNpcId"] = 210004,
            ["TalkActionId"] = {
                [1] = "210032:Explain02_End",
                [2] = "210004:AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120103/1E110928",
            },
        [12010309] = {
            ["Camera"] = "-158.883514,-85.465759,136.083008,0.000155,-2.202388,31.597618,50.0,257.290894,false,DoNotOverride,2.8",
            ["Content"] = "抱歉，{nickname}……总有这些事务缠身。看来能陪伴你的时间已经结束了。",
            ["ContentFR"] = "Pardonne-moi, {nickname}... Ces affaires ne cessent jamais de s’accumuler. Il semble que je doive m’arrêter ici.",
            ["DialogueId"] = 12010309,
            ["FacialId"] = {
                [1] = "210004:Smile01",
                },
            ["FinalCamera"] = "-143.195038,-56.148727,137.883789,0.000157,-2.602418,27.796841,50.0,257.290894,false,DoNotOverride,2.8",
            ["GUID"] = "1E110952",
            ["LookAt"] = {
                [1] = "210004:n(100001)",
                [2] = "100001:n(210004)",
                [3] = "200002:n(210004)",
                [4] = "210003:n(210004)",
                [5] = "210032:n(100001)",
                },
            ["NextOptions"] = {
                [1] = 120103091,
                [2] = 120103092,
                },
            ["SpeakNpcId"] = 210004,
            ["TalkActionId"] = {
                [1] = "210004:ConfidentR_End",
                },
            ["ToFinalCameraBlendTime"] = 8,
            ["TurnTo"] = {
                [1] = "210032:n(100001)",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120103/1E110952",
            },
        [12010310] = {
            ["Content"] = "只是，有一件要紧的事尚未交代你们。",
            ["ContentFR"] = "Toutefois, il reste une chose importante que je dois encore vous confier.",
            ["DialogueId"] = 12010310,
            ["FacialId"] = {
                [1] = "210004:Nervous",
                },
            ["GUID"] = "1E11097C",
            ["NextDialogue"] = 12010311,
            ["SpeakNpcId"] = 210004,
            ["TalkActionId"] = {
                [1] = "210004：Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120103/1E11097C",
            },
        [12010311] = {
            ["Camera"] = "-570.646729,-313.165039,402.481445,0.000143,-22.602468,31.792645,46.756084,257.290894,false,DoNotOverride,2.8",
            ["Content"] = "初入华胥者，必须了解<H>九诫</>的内容。若是不慎触犯了大风九章的诫律，或许就落得像刚刚歹人那般的下场。",
            ["ContentFR"] = "Toute personne entrant pour la première fois à Huaxu se doit de connaître le contenu des <H>Neuf Préceptes</>. Quiconque enfreint les préceptes des Neuf Chapitres de Dafeng... pourrait bien connaître le même sort que ce malfaiteur à l’instant.",
            ["DialogueId"] = 12010311,
            ["FinalCamera"] = "-606.82959,-335.576965,420.213379,0.000143,-22.602468,31.792645,46.756084,257.290894,false,DoNotOverride,2.8",
            ["GUID"] = "1E1109A6",
            ["NextDialogue"] = 12010312,
            ["SpeakNpcId"] = 210004,
            ["TalkActionId"] = {
                [1] = "210004:Talk03ToThink_Start",
                },
            ["ToFinalCameraBlendTime"] = 12,
            ["VoiceName"] = "voice/$Locale$/story/1201/120103/1E1109A6",
            },
        [12010312] = {
            ["Camera"] = "202.094421,-70.305641,138.647461,0.000175,-12.601808,127.792175,50.000008,318.602966,false,DoNotOverride,2.8",
            ["Content"] = "放心，止流掌柜！我会带他们去看诫碑的，就包在本皎皎身上吧！",
            ["ContentFR"] = "Comptez sur moi, Patronne Zhiliu ! Je les emmènerai voir la <H>Stèle de l’Admonition</>. Laissez ça à Luno, la carpe !",
            ["DialogueId"] = 12010312,
            ["FacialId"] = {
                [1] = "210003:Confident01",
                },
            ["GUID"] = "1E1109D0",
            ["LookAt"] = {
                [1] = "210004:n(210003)",
                [2] = "100001:n(210003)",
                [3] = "210032:n(210003)",
                [4] = "200002:n(210003)",
                },
            ["NextDialogue"] = 12010313,
            ["SpeakNpcId"] = 210003,
            ["TalkActionId"] = {
                [1] = "210004:Think_End",
                [2] = "210003:Excited02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120103/1E1109D0",
            },
        [12010313] = {
            ["Camera"] = "-525.948059,104.858734,227.421875,0.000185,-12.003141,1.202763,50.0,572.522461,false,DoNotOverride,2.8",
            ["Content"] = "咦……你们两位已经认识了？",
            ["ContentFR"] = "Oh... Vous vous connaissez déjà, toutes les deux ?",
            ["DialogueId"] = 12010313,
            ["FacialId"] = {
                [1] = "210004:Doubt01",
                },
            ["GUID"] = "1E1109FA",
            ["LookAt"] = {
                [1] = "200002:n(210004)",
                },
            ["NextDialogue"] = 12010314,
            ["SpeakNpcId"] = 210004,
            ["TalkActionId"] = {
                [1] = "210004:Explain02_Start",
                [2] = "210003:Excited02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120103/1E1109FA",
            },
        [12010314] = {
            ["Camera"] = "202.094421,-70.305641,138.647461,0.000175,-12.601808,127.792175,50.000008,318.602966,false,DoNotOverride,2.8",
            ["Content"] = "这就是光之魔王大人走到哪里散发到哪里的人格魅力！",
            ["ContentFR"] = "C’est ça, le charisme irrésistible du Roi Démon de la Lumière ! Partout où je vais, je fais des rencontres !",
            ["DialogueId"] = 12010314,
            ["FacialId"] = {
                [1] = "200002:Confident02",
                },
            ["FinalCamera"] = "202.094421,-70.305641,138.647461,0.000182,-12.401793,125.792969,50.000011,318.602966,false,DoNotOverride,2.8",
            ["GUID"] = "1E110A24",
            ["LookAt"] = {
                [1] = "200002:n(210004)",
                },
            ["NextDialogue"] = 12010315,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Confident_Start",
                },
            ["ToFinalCameraBlendTime"] = 6,
            ["VoiceName"] = "voice/$Locale$/story/1201/120103/1E110A24",
            },
        [12010315] = {
            ["Content"] = "这位冰湖城来的魔王大人和本皎皎可是拜把子的交情！我会担起东道主的责任，好好带领他们，让他们宾至如归的！",
            ["ContentFR"] = "Le Roi Démon venu de Givrelac et moi, on est comme sœurs Luno ! Je vais remplir mon rôle d’hôtesse comme il se doit et faire en sorte qu’ils se sentent ici comme chez eux !",
            ["DialogueId"] = 12010315,
            ["GUID"] = "1E110A4E",
            ["NextDialogue"] = 12010316,
            ["SpeakNpcId"] = 210003,
            ["TalkActionId"] = {
                [1] = "210003:SpecialHappy_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120103/1E110A4E",
            },
        [12010316] = {
            ["Camera"] = "-525.948059,104.858734,227.421875,0.000185,-12.003141,1.202763,50.0,572.522461,false,DoNotOverride,2.8",
            ["Content"] = "嗯，你对这片地界熟悉，交给你我却是放心。那你们随后到<H>百年春</>来找我就行。",
            ["ContentFR"] = "Très bien. Vous connaissez ces lieux, je vous confie donc cette tâche en toute confiance. Ensuite, retrouvez-moi à <H>Éternel Printemps</>.",
            ["DialogueId"] = 12010316,
            ["FacialId"] = {
                [1] = "210004:Smile01",
                },
            ["GUID"] = "1E110A78",
            ["NextDialogue"] = 12010317,
            ["SpeakNpcId"] = 210004,
            ["TalkActionId"] = {
                [1] = "210004:AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120103/1E110A78",
            },
        [12010317] = {
            ["Camera"] = "-197.656311,99.099442,143.551758,0.000188,-4.202909,-1.79672,50.000008,572.522461,false,DoNotOverride,2.8",
            ["Content"] = "{nickname}，路上注意安全。逛得尽兴了再来即可。先前提到的委托，等你来了，我再把细节交代与你。",
            ["ContentFR"] = "{nickname}, prends garde en chemin. Profite de ta promenade, puis viens me voir. Nous reparlerons alors du mandat évoqué plus tôt.",
            ["DialogueId"] = 12010317,
            ["FacialId"] = {
                [1] = "210004:Smile01",
                },
            ["GUID"] = "1E110AA2",
            ["LookAt"] = {
                [1] = "210004:n(100001)",
                [2] = "100001:n(210004)",
                [3] = "210032:n(100001)",
                [4] = "200002:n(210004)",
                },
            ["NextDialogue"] = 12010318,
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{210004},AnimationId{\"Explain02_End\"},Duration{1}},\
PlayAnimation{ActorId{210004},AnimationId{\"Explain01_Start\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120103/1E110AA2",
            },
        [12010318] = {
            ["Camera"] = "221.316528,188.197891,147.143066,0.000172,-5.802731,-150.999084,50.000011,338.357025,false,DoNotOverride,2.8",
            ["Content"] = "我明白了。止流掌柜，您快去忙吧！",
            ["ContentFR"] = "J’ai compris. Patronne Zhiliu, je vous laisse à vos affaires.",
            ["DialogueId"] = 12010318,
            ["FacialId"] = {
                [1] = "100001:Smile01",
                },
            ["GUID"] = "1E110ACC",
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120103/1E110ACC",
            },
        [12010401] = {
            ["Camera"] = "1510.199219,3684.390625,1778.458984,0.000038,-13.800717,-84.392624,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "这就是你们说的诫碑了吧，让我瞧瞧——",
            ["ContentFR"] = "Alors c’est ça, la stèle dont vous parliez ? Voyons voir—",
            ["DialogueId"] = 12010401,
            ["GUID"] = "1E11186A",
            ["NextDialogue"] = 12010402,
            ["RelatedWikiId"] = {
                [1] = 408010,
                [2] = 408011,
                [3] = 304003,
                [4] = 203002,
                [5] = 405009,
                },
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120104/1E11186A",
            },
        [12010402] = {
            ["Camera"] = "696.953125,-317.017578,277.799805,0.000066,-12.201128,149.811142,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "怎、怎么办，白完全看不懂……",
            ["ContentFR"] = "H-Hein... ? Je ne comprends absolument rien...",
            ["DialogueId"] = 12010402,
            ["GUID"] = "1E111894",
            ["NextDialogue"] = 12010403,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120104/1E111894",
            },
        [12010403] = {
            ["Camera"] = "-185.355469,366.291016,89.310547,0.00007,1.398802,-55.587837,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我来给你们翻译——锦鲤皎皎的大风九章小课堂开始！为了在华胥玩得开心，大家一定要认真听哦！",
            ["ContentFR"] = "Pas de panique ! Je vais vous traduire. Le cours accéléré de Luno, la carpe, sur les Neuf Chapitres de Dafeng commence maintenant ! Si vous voulez bien profiter de Huaxu, ouvrez bien vos oreilles !",
            ["DialogueId"] = 12010403,
            ["GUID"] = "1E1118BE",
            ["NextDialogue"] = 12010404,
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120104/1E1118BE",
            },
        [12010404] = {
            ["Content"] = "最上面这行是<H>戕身害命，不可为也</>。任何伤害别人的行为在华胥都是绝对禁止的！",
            ["ContentFR"] = "Tout en haut, il est écrit : <H>« La grande vertu du Ciel porte le nom de Vie ; Attenter au corps ou ôter la vie — cela est proscrit. »</> À Huaxu, toute forme de violence est absolument prohibée !",
            ["DialogueId"] = 12010404,
            ["GUID"] = "1E1118E8",
            ["NextDialogue"] = 12010405,
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120104/1E1118E8",
            },
        [12010405] = {
            ["Content"] = "这条的惩罚最为严重，一定一定要小心哦。不然就会像刚刚看到的坏强盗一样，被一下子定在原地，化作晶尘。",
            ["ContentFR"] = "C’est la règle la plus sévèrement punie, alors soyez vraiment prudents. Sinon, vous finirez comme ce vil bandit... figé sur place, puis réduit en poussière cristalline.",
            ["DialogueId"] = 12010405,
            ["GUID"] = "1E111912",
            ["NextDialogue"] = 12010406,
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120104/1E111912",
            },
        [12010406] = {
            ["Content"] = "哇，这么吓人……",
            ["ContentFR"] = "Ouaaah... c’est terrifiant...",
            ["DialogueId"] = 12010406,
            ["GUID"] = "1E11193C",
            ["NextDialogue"] = 12010407,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120104/1E11193C",
            },
        [12010407] = {
            ["Content"] = "放心，只有坏人才需要害怕啦，好人才不用担心呢！",
            ["ContentFR"] = "Mais rassurez-vous ! Seuls les méchants ont de quoi trembler. Les gens bien n’ont rien à craindre !",
            ["DialogueId"] = 12010407,
            ["GUID"] = "1E111966",
            ["NextDialogue"] = 12010408,
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120104/1E111966",
            },
        [12010408] = {
            ["Content"] = "多亏了大风九章，现在的华胥压根就不会有什么战争呀犯罪呀，大家都和睦融融的。我听说外面的世界可不是这样。",
            ["ContentFR"] = "Grâce aux Neuf Chapitres de Dafeng, il n’y a plus ni guerre ni criminalité à Huaxu. Tout le monde vit en harmonie. D’après ce que j’ai entendu, le monde extérieur est loin d’être aussi paisible...",
            ["DialogueId"] = 12010408,
            ["GUID"] = "1E111990",
            ["NextDialogue"] = 12010409,
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120104/1E111990",
            },
        [12010409] = {
            ["Content"] = "这倒是。要是在冰湖城，有人犯了事，就只能指望治安署那些趾高气昂的士兵。",
            ["ContentFR"] = "C’est sûr... À Givrelac, quand quelqu’un commet un crime, on ne peut compter que sur les soldats arrogants du Bureau de la Sécurité.",
            ["DialogueId"] = 12010409,
            ["GUID"] = "1E1119BA",
            ["NextDialogue"] = 12010410,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120104/1E1119BA",
            },
        [12010410] = {
            ["Content"] = "而且他们很少管卡戎和穷人的事，最后还是得靠我们自己去抓犯人。前几天好不容易遇到一个靠谱的大姐姐，最后还跑掉不干了……",
            ["ContentFR"] = "Et encore, ils se soucient rarement des Charons ou des pauvres. Au final, c’est souvent à nous d’attraper les criminels. Il n’y a pas longtemps, on avait enfin rencontré une jeune officière fiable... et elle a fini par tout laisser tomber.",
            ["DialogueId"] = 12010410,
            ["GUID"] = "1E1119E4",
            ["NextDialogue"] = 12010411,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120104/1E1119E4",
            },
        [12010411] = {
            ["Content"] = "华胥这些长得像冰原狼一样的，叫毕、毕什么的威风猛兽，可比冰湖城的治安署靠谱多啦！",
            ["ContentFR"] = "En comparaison, vos bêtes féroces qui ressemblent à des loups des neiges — les Bi... Bi-trucs — sont bien plus fiables que le Bureau de la Sécurité de Givrelac !",
            ["DialogueId"] = 12010411,
            ["GUID"] = "1E111A0E",
            ["NextDialogue"] = 12010412,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120104/1E111A0E",
            },
        [12010412] = {
            ["Content"] = "是狴犴，不要再记错它们的名字了！",
            ["ContentFR"] = "Bi’an ! Ne te trompe plus de nom !",
            ["DialogueId"] = 12010412,
            ["GUID"] = "1E111A38",
            ["NextOptions"] = {
                [1] = 120104121,
                [2] = 120104122,
                },
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120104/1E111A38",
            },
        [12010413] = {
            ["Content"] = "当然，狴犴可是天命的使者！",
            ["ContentFR"] = "Évidemment ! Les Bi’an sont des messagers du Mandat Céleste !",
            ["DialogueId"] = 12010413,
            ["GUID"] = "1E111A62",
            ["NextDialogue"] = 12010415,
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120104/1E111A62",
            },
        [12010414] = {
            ["Content"] = "这可不行！狴犴可是天命的使者。",
            ["ContentFR"] = "Bien sûr que non ! Les Bi’an sont des messagers du Mandat Céleste !",
            ["DialogueId"] = 12010414,
            ["GUID"] = "1E111A8C",
            ["NextDialogue"] = 12010415,
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120104/1E111A8C",
            },
        [12010415] = {
            ["Content"] = "这就要说到，为什么有龙氏是大家都很敬仰的存在啦。",
            ["ContentFR"] = "Et c’est justement pour cela que les Descendants draconiques sont si respectés ici.",
            ["DialogueId"] = 12010415,
            ["GUID"] = "1E111AB6",
            ["NextDialogue"] = 12010416,
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120104/1E111AB6",
            },
        [12010416] = {
            ["Content"] = "别卖关子啦，快说快说——",
            ["ContentFR"] = "Allez, raconte ! Ne nous fais pas attendre !",
            ["DialogueId"] = 12010416,
            ["GUID"] = "1E111AE0",
            ["NextDialogue"] = 12010417,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120104/1E111AE0",
            },
        [12010417] = {
            ["Content"] = "一部分有龙氏到了成年左右的时间，会感应天命，被大风九章蒙召，化为狴犴。",
            ["ContentFR"] = "À l’approche de l’âge adulte, certains Descendants draconiques résonnent avec le Mandat Céleste. Appelés par les Neuf Chapitres de Dafeng, ils se transforment en Bi’an.",
            ["DialogueId"] = 12010417,
            ["GUID"] = "1E111B0A",
            ["NextDialogue"] = 12010418,
            ["RelatedWikiId"] = {
                [1] = 303009,
                },
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120104/1E111B0A",
            },
        [12010418] = {
            ["Content"] = "（嗯？卡戎……<H>成年左右</>？）",
            ["ContentFR"] = "<I>Hein... ? Des Charons... à l’âge adulte ?</>",
            ["DialogueId"] = 12010418,
            ["DisableMouth"] = 1,
            ["GUID"] = "1E111B34",
            ["NextDialogue"] = 12010419,
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120104/1E111B34",
            },
        [12010419] = {
            ["Content"] = "再附赠一个知识点，其实狴犴只是大风九章最普通的执法者。",
            ["ContentFR"] = "Et pour finir, un petit savoir bonus ! Les Bi’an ne sont que les exécutants les plus ordinaires des Neuf Chapitres.",
            ["DialogueId"] = 12010419,
            ["GUID"] = "1E111B5E",
            ["NextDialogue"] = 12010420,
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120104/1E111B5E",
            },
        [12010420] = {
            ["Content"] = "有一些更厉害的有龙氏，能够直接以人身进入大风九章，作为<H>应天尉</>活动着，代天命威慑躲在暗中的坏人，让他们不敢造次！",
            ["ContentFR"] = "Les Descendants draconiques les plus exceptionnels peuvent, eux, entrer dans les Neuf Chapitres tout en conservant leur forme humaine, et agir en tant que <H>Magistrats de Yingtian</> ! Ils brandissent l’autorité du Mandat Céleste pour dissuader les criminels tapis dans l’ombre et les empêcher de commettre le moindre méfait !",
            ["DialogueId"] = 12010420,
            ["GUID"] = "1E111B88",
            ["NextDialogue"] = 12010421,
            ["RelatedWikiId"] = {
                [1] = 405010,
                },
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120104/1E111B88",
            },
        [12010421] = {
            ["Content"] = "对于那种非常棘手的坏人，应天尉就会出动，将他们缉拿，威风凛凛！",
            ["ContentFR"] = "Et face aux pires criminels... les Magistrats de Yingtian interviennent en personne, majestueux et implacables !",
            ["DialogueId"] = 12010421,
            ["GUID"] = "1E111BB2",
            ["NextDialogue"] = 12010422,
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120104/1E111BB2",
            },
        [12010422] = {
            ["Content"] = "不过……当然还是希望你们永远不要遇到应天尉！",
            ["ContentFR"] = "Mais... évidemment, j’espère que vous n’aurez jamais à les rencontrer !",
            ["DialogueId"] = 12010422,
            ["GUID"] = "1E111BDC",
            ["NextDialogue"] = 12010423,
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120104/1E111BDC",
            },
        [12010423] = {
            ["Content"] = "好啦，对于第一条诫律的解说到此为止！接下来——",
            ["ContentFR"] = "Voilà pour l’explication du premier Précepte ! Passons maintenant au suivant—",
            ["DialogueId"] = 12010423,
            ["GUID"] = "1E111C06",
            ["NextDialogue"] = 12010424,
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120104/1E111C06",
            },
        [12010424] = {
            ["Content"] = "眩晕屏幕特效",
            ["ContentFR"] = "(L’écran ondule. La vision du joueur se trouble.)",
            ["DialogueId"] = 12010424,
            ["GUID"] = "1E111C30",
            ["NextDialogue"] = 12010425,
            ["VoiceName"] = "voice/$Locale$/story/1201/120104/1E111C30",
            },
        [12010425] = {
            ["Content"] = "…………？",
            ["ContentFR"] = "... ?",
            ["DialogueId"] = 12010425,
            ["GUID"] = "1E111C5A",
            ["NextDialogue"] = 12010426,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120104/1E111C5A",
            },
        [12010426] = {
            ["Content"] = "（总觉得……那块诫碑，像是在<H>呼唤</>我一样……）",
            ["ContentFR"] = "<I>J’ai l’étrange impression... que cette stèle m’appelle...</>",
            ["DialogueId"] = 12010426,
            ["DisableMouth"] = 1,
            ["GUID"] = "1E111C84",
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120104/1E111C84",
            },
        [12010427] = {
            ["Content"] = "你触摸了诫碑，忽然你的脑内传来了一阵眩晕。",
            ["ContentFR"] = "Vous posez la main sur la Stèle de l’Admonition. L’instant d’après, une violente sensation de vertige vous submerge... et une voix, grave et lointaine, résonne dans votre esprit.",
            ["DialogueId"] = 12010427,
            ["GUID"] = "1E111CAE",
            ["VoiceName"] = "voice/$Locale$/story/1201/120104/1E111CAE",
            },
        [12010428] = {
            ["DialogueId"] = 12010428,
            ["GUID"] = "1E111CD8",
            ["VoiceName"] = "voice/$Locale$/story/1201/120104/1E111CD8",
            },
        [12010429] = {
            ["Camera"] = "265.414062,55.289062,169.237793,0.000002,-24.800047,-172.198669,11.88,100000.0,false,Manual,2.8",
            ["Content"] = "接下来，我要来讲第二条啦！大风九章的第二条即是——",
            ["ContentFR"] = "Et voilà ! Passons maintenant au deuxième Précepte des Neuf Chapitres de Dafeng—",
            ["DialogueId"] = 12010429,
            ["GUID"] = "1E111D02",
            ["NextOptions"] = {
                [1] = 120104291,
                [2] = 120104292,
                },
            ["RelatedWikiId"] = {
                [1] = 408010,
                [2] = 408011,
                [3] = 304003,
                [4] = 405009,
                [5] = 203002,
                },
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120104/1E111D02",
            },
        [12010432] = {
            ["Content"] = "完全正确！",
            ["ContentFR"] = "Exactement ! Bien vu !",
            ["DialogueId"] = 12010432,
            ["GUID"] = "1E111D80",
            ["NextDialogue"] = 12010433,
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120104/1E111D80",
            },
        [12010433] = {
            ["Content"] = "小仆从，你什么时候偷偷学会了华胥文字？白都不知道！",
            ["ContentFR"] = "Dis donc, petit larbin... Depuis quand tu comprends les écritures de Huaxu ? Même moi, je ne savais pas !",
            ["DialogueId"] = 12010433,
            ["GUID"] = "1E111DAA",
            ["NextDialogue"] = 12010434,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120104/1E111DAA",
            },
        [12010434] = {
            ["Content"] = "不，我不认识这些文字……",
            ["ContentFR"] = "Non... je ne sais pas les lire.",
            ["DialogueId"] = 12010434,
            ["GUID"] = "1E111DD4",
            ["NextDialogue"] = 12010435,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120104/1E111DD4",
            },
        [12010435] = {
            ["Content"] = "刚刚我靠近诫碑时，脑海里突然冒出来了一个声音，告诉了我这些内容。你知道这是什么情况吗？",
            ["ContentFR"] = "Quand je me suis approché de la stèle, une voix est apparue dans mon esprit... Elle m’a transmis le sens des inscriptions. Tu as déjà entendu parler de quelque chose comme ça ?",
            ["DialogueId"] = 12010435,
            ["GUID"] = "1E111DFE",
            ["NextDialogue"] = 12010436,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120104/1E111DFE",
            },
        [12010436] = {
            ["Content"] = "从来没有听说过这种事情……不对，等等！",
            ["ContentFR"] = "Jamais... Enfin— non, attends !",
            ["DialogueId"] = 12010436,
            ["GUID"] = "1E111E28",
            ["NextDialogue"] = 12010437,
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120104/1E111E28",
            },
        [12010437] = {
            ["Content"] = "有过这样的传说，大风九章的奠基者，也是悬衡派的创始人<H>飏</>，在史书中留下了“天人相感，阴阳相和”的评价。",
            ["ContentFR"] = "Il existe bien une ancienne légende. La fondatrice des Neuf Chapitres de Dafeng, et créatrice de la Secte Xuanheng, <H>Yang</> a été décrite dans les chroniques par ces mots : <H>« Le Ciel et l’Homme résonnent ensemble ; le Yin et le Yang s’accordent en harmonie. »</>",
            ["DialogueId"] = 12010437,
            ["GUID"] = "1E111E52",
            ["NextDialogue"] = 12010438,
            ["RelatedWikiId"] = {
                [1] = 203003,
                },
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120104/1E111E52",
            },
        [12010438] = {
            ["Content"] = "据说，她能够与上天，与世间万物相感应，挟飞仙以遨游！好像和你的情况有点相似。",
            ["ContentFR"] = "On raconte qu’elle pouvait entrer en communion avec le Ciel et avec toute chose existante... qu’elle parcourait les cieux portée par les immortels. Ce que tu viens de vivre... y ressemble étrangement.",
            ["DialogueId"] = 12010438,
            ["GUID"] = "1E111E7C",
            ["NextDialogue"] = 12010439,
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120104/1E111E7C",
            },
        [12010439] = {
            ["Content"] = "正是这位先辈，最后带着很多德高望重的祖先一起，祭献了身躯，化为大风九章流转不息的根基。",
            ["ContentFR"] = "C’est elle, ainsi que de nombreux anciens vertueux, qui ont offert leur propre existence... pour devenir le fondement éternel des Neuf Chapitres de Dafeng.",
            ["DialogueId"] = 12010439,
            ["GUID"] = "1E111EA6",
            ["NextDialogue"] = 12010440,
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120104/1E111EA6",
            },
        [12010440] = {
            ["Content"] = "白突然有了一个想法！莫非，小仆从就是这位前辈的不知道第几十代曾曾曾曾孙？",
            ["ContentFR"] = "Hé... j’ai une idée complètement folle ! Et si, par hasard... mon petit larbin était {性别:le descendant|la descendante} — genre, la centième génération — de cette grande fondatrice ?",
            ["DialogueId"] = 12010440,
            ["GUID"] = "1E111ED0",
            ["NextOptions"] = {
                [1] = 120104401,
                [2] = 120104402,
                },
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120104/1E111ED0",
            },
        [12010441] = {
            ["Content"] = "诶，是吗？但是{性别：他|她}看着也不像华胥人呢……",
            ["ContentFR"] = "Hein... vraiment ? Mais {性别:il|elle} ne ressemble pas du tout à quelqu’un de Huaxu...",
            ["DialogueId"] = 12010441,
            ["GUID"] = "1E111EFA",
            ["NextDialogue"] = 12010443,
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120104/1E111EFA",
            },
        [12010442] = {
            ["Content"] = "总而言之，大风九章的内容就是以上这些啦。止流大当家交代我的任务完成了，接下来，我带你们去百年春吧！",
            ["ContentFR"] = "Bref ! Voilà pour les Neuf Chapitres de Dafeng ! La mission confiée par la Patronne Zhiliu est accomplie. Maintenant, direction Éternel Printemps !",
            ["DialogueId"] = 12010442,
            ["GUID"] = "1E111F24",
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120104/1E111F24",
            },
        [12010443] = {
            ["Content"] = "一段时间后……",
            ["ContentFR"] = "Après un certain temps...",
            ["DialogueId"] = 12010443,
            ["GUID"] = "1E111EFB",
            ["NextDialogue"] = 12010442,
            },
        [12010451] = {
            ["Content"] = "跟我来！诫碑在这个方向哦！",
            ["ContentFR"] = "Par ici ! La stèle est de ce côté !",
            ["DialogueId"] = 12010451,
            ["Duration"] = 4,
            ["GUID"] = "1E111F26",
            ["NextDialogue"] = 12010452,
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120104/1E111F26",
            },
        [12010452] = {
            ["Content"] = "锦鲤皎皎，他们刚刚提到的烛什么阴之灾……是什么呀？",
            ["ContentFR"] = "Dis, Luno, la carpe, ils ont parlé tout à l’heure du Fléau de... Zhuyin, c’est ça ? C’est quoi, au juste ?",
            ["DialogueId"] = 12010452,
            ["Duration"] = 4,
            ["GUID"] = "1E111F27",
            ["NextDialogue"] = 12010453,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120104/1E111F27",
            },
        [12010453] = {
            ["Content"] = "唔，简而言之，就是一个害得大家没法好好做生意的很坏很坏的灾害。",
            ["ContentFR"] = "Hmm... pour faire simple, c’est une catastrophe très très méchante qui empêche tout le monde de faire du commerce tranquillement.",
            ["DialogueId"] = 12010453,
            ["Duration"] = 4,
            ["GUID"] = "1E111F28",
            ["NextDialogue"] = 12010454,
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120104/1E111F28",
            },
        [12010454] = {
            ["Content"] = "不过你们放心，止流大当家已经在着手解决了！只要大当家一出手，事情都会咻的一下好起来的！",
            ["ContentFR"] = "Mais rassurez-vous ! La Patronne Zhiliu s’en occupe déjà ! Quand elle agit, tout s’arrange en un éclair, <I>fiuu !</>",
            ["DialogueId"] = 12010454,
            ["Duration"] = 4,
            ["GUID"] = "1E111F29",
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120104/1E111F29",
            },
        [12010500] = {
            ["Content"] = "一直听你们说百年春，那里到底是什么样的地方哇？",
            ["ContentFR"] = "On parle sans arrêt d’Éternel Printemps... C’est comment, exactement ?",
            ["DialogueId"] = 12010500,
            ["Duration"] = 2,
            ["GUID"] = "1E1128A8",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 12010501,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120105/1E1128A8",
            },
        [12010501] = {
            ["Content"] = "那可是织星客在烟津渡的最大据点，囊括了来自五湖四海的商品，可气派啦。",
            ["ContentFR"] = "C’est la plus grande chambre de commerce des Tisse-Étoiles à Port-des-Brumes. Des marchandises venues des quatre coins du monde y sont rassemblées. C’est impressionnant, vraiment !",
            ["DialogueId"] = 12010501,
            ["Duration"] = 2,
            ["GUID"] = "1E1128D2",
            ["NextDialogue"] = 12010502,
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120105/1E1128D2",
            },
        [12010502] = {
            ["Content"] = "说起来，开旅游团好像也是一门不错的生意经……没错没错，赶紧记在小本本上。",
            ["ContentFR"] = "D’ailleurs... organiser des visites guidées pour étrangers, ce serait peut-être une idée de commerce intéressante... Oui, oui, je note ça quelque part !",
            ["DialogueId"] = 12010502,
            ["Duration"] = 2,
            ["GUID"] = "1E1128FC",
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120105/1E1128FC",
            },
        [12010503] = {
            ["Content"] = "吼————",
            ["ContentFR"] = "Rooooaaar— !",
            ["DialogueId"] = 12010503,
            ["Duration"] = 2,
            ["GUID"] = "1E112926",
            ["NextDialogue"] = 12010504,
            ["SnapShot"] = "ECHO",
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["VoiceName"] = "voice/$Locale$/story/1201/120105/1E112926",
            },
        [12010504] = {
            ["Content"] = "（刚刚那是……？）",
            ["ContentFR"] = "<I>C’était... quoi, ça ?</>",
            ["DialogueId"] = 12010504,
            ["Duration"] = 2,
            ["GUID"] = "1E112950",
            ["GuideFacialId"] = "Angry",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 12010505,
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120105/1E112950",
            },
        [12010505] = {
            ["Content"] = "糟糕——是玄色狴犴！",
            ["ContentFR"] = "Mauvaise nouvelle— C’était un Bi’an obscur !",
            ["DialogueId"] = 12010505,
            ["Duration"] = 2,
            ["GUID"] = "1E11297A",
            ["NextDialogue"] = 12010506,
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120105/1E11297A",
            },
        [12010506] = {
            ["Content"] = "那是什么？！——诶，人呢？",
            ["ContentFR"] = "Hein ?! C’est quoi ça— Attends... où est-elle passée ?!",
            ["DialogueId"] = 12010506,
            ["Duration"] = 4,
            ["GUID"] = "1E1129A4",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120105/1E1129A4",
            },
        [12010507] = {
            ["Content"] = "咤——走、赶紧走开 ——",
            ["ContentFR"] = "Aah— ! P-Partez... vite ! Éloignez-vous !",
            ["DialogueId"] = 12010507,
            ["Duration"] = 3,
            ["GUID"] = "1E1129CE",
            ["SpeakNpcId"] = 210033,
            ["VoiceName"] = "voice/$Locale$/story/1201/120105/1E1129CE",
            },
        [12010508] = {
            ["Camera"] = "-2086.416992,-1506.259277,1044.228516,0.000102,-15.798794,37.99028,28.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "上天庇佑，白龙神君庇佑！你们还好吗？",
            ["ContentFR"] = "Que le Ciel vous protège... que le Seigneur Dragon d’Argent veille sur vous. Êtes-vous tous sains et saufs ?",
            ["DialogueId"] = 12010508,
            ["FinalCamera"] = "-2543.464355,680.419128,896.21582,0.000097,-15.59871,-11.41056,28.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "1E1129F8",
            ["LookAt"] = {
                [1] = "210033:n(100001)",
                },
            ["NextDialogue"] = 12010509,
            ["RelatedWikiId"] = {
                [1] = 408010,
                [2] = 408011,
                [3] = 304003,
                [4] = 303008,
                [5] = 303009,
                },
            ["SpeakNpcId"] = 210033,
            ["SpeakNpcName"] = "UI_Npc_CMName_LuGuoXingShang",
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1201/120105/1E1129F8",
            },
        [12010509] = {
            ["Content"] = "你还好吗？你的声音都在颤抖……明明自己也怕得要死，怎么还来凑热闹呀！",
            ["ContentFR"] = "Tu vas bien ? Ta voix tremble encore... Tu avais tellement peur, et malgré ça, tu es quand même venue nous aider !",
            ["DialogueId"] = 12010509,
            ["GUID"] = "1E112A22",
            ["NextDialogue"] = 12010510,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120105/1E112A22",
            },
        [12010510] = {
            ["Camera"] = "-309.597839,264.643616,19.609375,0.000098,-13.798676,-30.610697,28.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我并无大碍，只是被那骇人的双目瞪上一眼，腿有点麻，缓缓就好了。但你们看起来是刚来此地的外乡人，不能将你们置之不理。",
            ["ContentFR"] = "Je ne suis pas blessée. Ce n’est rien... ce sont ses yeux, simplement leur regard était si terrifiant que mes jambes en sont restées engourdies. Cela passera. Mais vous sembliez être des étrangers fraîchement arrivés... Je ne pouvais décemment pas vous laisser en danger.",
            ["DialogueId"] = 12010510,
            ["GUID"] = "1E112A4C",
            ["NextOptions"] = {
                [1] = 120105101,
                [2] = 120105102,
                },
            ["SpeakNpcId"] = 210033,
            ["SpeakNpcName"] = "UI_Npc_CMName_LuGuoXingShang",
            ["VoiceName"] = "voice/$Locale$/story/1201/120105/1E112A4C",
            },
        [12010511] = {
            ["Content"] = "其实你再晚来两步，小仆从唰唰两下就能解决啦，{性别：他|她}很厉害的！",
            ["ContentFR"] = "De toute façon, si tu étais arrivée deux secondes plus tard, mon petit larbin l’aurait réglé en deux coups bien nets ! {性别:Il est super fort|Elle est super forte} !",
            ["DialogueId"] = 12010511,
            ["GUID"] = "1E112A76",
            ["NextDialogue"] = 12010512,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120105/1E112A76",
            },
        [12010512] = {
            ["Content"] = "这样吗，那太好了……",
            ["ContentFR"] = "Vraiment ?... Alors tant mieux.",
            ["DialogueId"] = 12010512,
            ["GUID"] = "1E112AA0",
            ["NextDialogue"] = 12010513,
            ["SpeakNpcId"] = 210033,
            ["SpeakNpcName"] = "UI_Npc_CMName_LuGuoXingShang",
            ["VoiceName"] = "voice/$Locale$/story/1201/120105/1E112AA0",
            },
        [12010513] = {
            ["Content"] = "但是，刚刚那是怎么回事？白没认错吧，华胥的执法者怎么突然冒出来攻击我们？！",
            ["ContentFR"] = "Mais quand même... qu’est-ce qui vient de se passer ? Je ne me trompe pas, hein ? Pourquoi un exécuteur de Huaxu nous a attaqués d’un coup ?!",
            ["DialogueId"] = 12010513,
            ["GUID"] = "1E112ACA",
            ["NextDialogue"] = 12010514,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120105/1E112ACA",
            },
        [12010514] = {
            ["Content"] = "事先说明，白可没有做什么违法乱纪的坏事——虽然现在说这个好像也已经晚了……",
            ["ContentFR"] = "Je précise tout de suite : je n’ai rien fait d’illégal ! ... Même si, dit comme ça, c’est peut-être déjà trop tard...",
            ["DialogueId"] = 12010514,
            ["GUID"] = "1E112AF4",
            ["NextDialogue"] = 12010515,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120105/1E112AF4",
            },
        [12010515] = {
            ["Content"] = "怎、怎么办，小仆从，我们是不是得赶紧潜逃？你的水性怎么样？",
            ["ContentFR"] = "Q-Qu’est-ce qu’on fait, petit larbin ? On... on s’enfuit ? Dis, tu sais bien nager, au moins ?",
            ["DialogueId"] = 12010515,
            ["GUID"] = "1E112B1E",
            ["NextDialogue"] = 12010516,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120105/1E112B1E",
            },
        [12010516] = {
            ["Content"] = "噗嗤……烟津渡周围的水域如此广阔，光靠游，一天一夜也游不出几里。",
            ["ContentFR"] = "Les eaux autour de Port-des-Brumes sont vastes. Même en nageant jour et nuit, vous ne parcourriez que quelques lieues.",
            ["DialogueId"] = 12010516,
            ["GUID"] = "1E112B48",
            ["NextDialogue"] = 12010517,
            ["SpeakNpcId"] = 210033,
            ["SpeakNpcName"] = "UI_Npc_CMName_LuGuoXingShang",
            ["VoiceName"] = "voice/$Locale$/story/1201/120105/1E112B48",
            },
        [12010517] = {
            ["Content"] = "你们不必惊慌。玄色狴犴与狴犴仅仅是外形近似，但它们并非华胥的执法者，而是<H>烛阴之灾</>影响下紊乱失序的产物。",
            ["ContentFR"] = "N’ayez crainte. Le Bi’an obscur et les Bi’an se ressemblent en apparence, mais ils ne sont pas les exécuteurs de Huaxu. Ce sont des aberrations nées du Fléau de Zhuyin, des êtres plongés dans le chaos et la perte de contrôle.",
            ["DialogueId"] = 12010517,
            ["GUID"] = "1E112B72",
            ["NextDialogue"] = 12010518,
            ["RelatedWikiId"] = {
                [1] = 303010,
                },
            ["SpeakNpcId"] = 210033,
            ["SpeakNpcName"] = "UI_Npc_CMName_LuGuoXingShang",
            ["VoiceName"] = "voice/$Locale$/story/1201/120105/1E112B72",
            },
        [12010518] = {
            ["Content"] = "这些玄色狴犴神志浑浊暴虐，不受大风九章的控制。攻击它们不会招致责罚。\
",
            ["ContentFR"] = "Ces Bi’an obscurs sont violents, privés de raison, et ne sont plus soumis aux Neuf Chapitres de Dafeng. Les attaquer n’entraîne aucune sanction.",
            ["DialogueId"] = 12010518,
            ["GUID"] = "1E112B9C",
            ["NextDialogue"] = 12010519,
            ["SpeakNpcId"] = 210033,
            ["SpeakNpcName"] = "UI_Npc_CMName_LuGuoXingShang",
            ["VoiceName"] = "voice/$Locale$/story/1201/120105/1E112B9C",
            },
        [12010519] = {
            ["Content"] = "只是最近这玄色狴犴袭人事件，是愈来愈频发了。我刚刚续上的香，这就又用完了……",
            ["ContentFR"] = "Ces derniers temps, leurs agressions se multiplient... L’encens que je venais à peine de renouveler s’est déjà consumé.",
            ["DialogueId"] = 12010519,
            ["GUID"] = "1E112BC6",
            ["NextDialogue"] = 12010520,
            ["SpeakNpcId"] = 210033,
            ["SpeakNpcName"] = "UI_Npc_CMName_LuGuoXingShang",
            ["VoiceName"] = "voice/$Locale$/story/1201/120105/1E112BC6",
            },
        [12010520] = {
            ["Content"] = "玉笙姐姐！",
            ["ContentFR"] = "Grande sœur Yusheng !",
            ["DialogueId"] = 12010520,
            ["GUID"] = "1E112BF0",
            ["NextDialogue"] = 12010521,
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120105/1E112BF0",
            },
        [12010521] = {
            ["Content"] = "锦鲤皎皎，你怎在此处？",
            ["ContentFR"] = "Luno, la carpe ? Que fais-tu ici ?",
            ["DialogueId"] = 12010521,
            ["GUID"] = "1E112C1A",
            ["NextDialogue"] = 12010522,
            ["SpeakNpcId"] = 210033,
            ["SpeakNpcName"] = "UI_Npc_CMName_LuGuoXingShang",
            ["VoiceName"] = "voice/$Locale$/story/1201/120105/1E112C1A",
            },
        [12010522] = {
            ["Content"] = "这两位是止流大当家从异国带来的贵客，我正在招待他们呢！只是途中发生了一些……咳咳、小变故。",
            ["ContentFR"] = "Ces deux-là sont des invités de marque amenés par la Patronne Zhiliu depuis des terres étrangères ! Je les guidais justement... quand il y a eu, hum... un petit imprévu.",
            ["DialogueId"] = 12010522,
            ["GUID"] = "1E112C44",
            ["NextDialogue"] = 12010523,
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120105/1E112C44",
            },
        [12010523] = {
            ["Content"] = "玉笙姐姐，你要去百年春前续香吗？我们一起同行吧！",
            ["ContentFR"] = "Tu allais renouveler ton encens devant Éternel Printemps, non ? Allons-y ensemble !",
            ["DialogueId"] = 12010523,
            ["GUID"] = "1E112C6E",
            ["NextDialogue"] = 12010524,
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120105/1E112C6E",
            },
        [12010524] = {
            ["Content"] = "<H>香</>？",
            ["ContentFR"] = "L’<H>encens</> ?",
            ["DialogueId"] = 12010524,
            ["GUID"] = "1E112C98",
            ["NextDialogue"] = 12010525,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120105/1E112C98",
            },
        [12010525] = {
            ["Content"] = "说起来，刚刚战斗时，好像有一阵异香飘过，然后仿佛有某种力量，帮我抵挡了对面的攻击……这就是你们说的香吗？",
            ["ContentFR"] = "Maintenant que j’y pense... pendant le combat, j’ai senti un parfum étrange. Et juste après, j’ai eu l’impression qu’une force invisible bloquait les attaques ennemies... C’était ça, l’encens ?",
            ["DialogueId"] = 12010525,
            ["GUID"] = "1E112CC2",
            ["NextDialogue"] = 12010526,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120105/1E112CC2",
            },
        [12010526] = {
            ["Content"] = "确是如此。",
            ["ContentFR"] = "Exactement.",
            ["DialogueId"] = 12010526,
            ["GUID"] = "1E112CEC",
            ["NextDialogue"] = 12010527,
            ["SpeakNpcId"] = 210033,
            ["SpeakNpcName"] = "UI_Npc_CMName_LuGuoXingShang",
            ["VoiceName"] = "voice/$Locale$/story/1201/120105/1E112CEC",
            },
        [12010527] = {
            ["Content"] = "哎呀，原来你们还不知道<H>香</>的妙用，是我这个东道主失职了！",
            ["ContentFR"] = "Oh ! Vous ne connaissiez pas encore les vertus de l’<H>encens</> ? Voilà une grave négligence de ma part en tant qu’hôtesse !",
            ["DialogueId"] = 12010527,
            ["GUID"] = "1E112D16",
            ["NextDialogue"] = 12010528,
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120105/1E112D16",
            },
        [12010528] = {
            ["Content"] = "在华胥，香可不仅仅是装饰。它维持着大风九章的运转，也能让我们得到上天的庇佑。",
            ["ContentFR"] = "À Huaxu, l’encens n’est pas un simple ornement. Il soutient le fonctionnement des Neuf Chapitres de Dafeng et nous permet de recevoir la protection du Ciel.",
            ["DialogueId"] = 12010528,
            ["GUID"] = "1E112D40",
            ["NextDialogue"] = 12010529,
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120105/1E112D40",
            },
        [12010529] = {
            ["Content"] = "刚刚，我见你们受袭心急，便将身上佩戴的香囊扔了出去，希望能对你们有所裨益。",
            ["ContentFR"] = "Lorsque je vous ai vus attaqués, j’ai lancé la bourse d’encens que je portais sur moi, en espérant vous offrir un répit.",
            ["DialogueId"] = 12010529,
            ["GUID"] = "1E112D6A",
            ["NextDialogue"] = 12010530,
            ["SpeakNpcId"] = 210033,
            ["VoiceName"] = "voice/$Locale$/story/1201/120105/1E112D6A",
            },
        [12010530] = {
            ["Content"] = "它虽然无法杀伤玄色狴犴，但足以帮我们抵挡一阵子。只是，香的作用发挥之后，必须到白龙祠堂去重新获取赐福。",
            ["ContentFR"] = "Elle ne peut pas blesser un Bi’an obscur, mais elle suffit à nous protéger un moment. Une fois son effet dissipé, il faut cependant retourner au Temple du Dragon d’Argent pour recevoir une nouvelle bénédiction.",
            ["DialogueId"] = 12010530,
            ["GUID"] = "1E112D94",
            ["NextDialogue"] = 12010531,
            ["RelatedWikiId"] = {
                [1] = 403005,
                },
            ["SpeakNpcId"] = 210033,
            ["VoiceName"] = "voice/$Locale$/story/1201/120105/1E112D94",
            },
        [12010531] = {
            ["Content"] = "懂了懂了——也就是去白龙祠堂祈福，我们就不用那么害怕坏狴犴了，对吧！",
            ["ContentFR"] = "Je vois ! Donc tant qu’on va prier au Temple du Dragon d’Argent, on n’a plus besoin d’avoir peur de ces méchants Bi’an, c’est ça !",
            ["DialogueId"] = 12010531,
            ["GUID"] = "1E112DBE",
            ["NextDialogue"] = 12010532,
            ["RelatedWikiId"] = {
                [1] = 405011,
                },
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120105/1E112DBE",
            },
        [12010532] = {
            ["Content"] = "当然，白龙祠堂前的香火可旺盛啦。走吧，带你们一起去见识见识！",
            ["ContentFR"] = "Exactement ! L’encens y brûle en permanence. Venez, je vous y emmène — ça vaut vraiment le détour !",
            ["DialogueId"] = 12010532,
            ["GUID"] = "1E112DE8",
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120105/1E112DE8",
            },
        [12010533] = {
            ["Content"] = "喂喂，刚刚打起来之后，你怎么一溜烟地就跑不见了。",
            ["ContentFR"] = "Hé, au fait... tout à l’heure, quand le combat a éclaté, tu as disparu en un éclair.",
            ["DialogueId"] = 12010533,
            ["GUID"] = "1E112E12",
            ["GuideFacialId"] = "Confident",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 12010534,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120105/1E112E12",
            },
        [12010534] = {
            ["Content"] = "毕竟我手无缚鸡之力……帮不上什么忙嘛。但是我有在一旁为你们摇旗呐喊哦！",
            ["ContentFR"] = "Eh bien... je n’ai pas la force de me battre... Je n’aurais servi à rien. Mais j’étais là, à vous encourager de toutes mes forces ! Le soutien moral, c’est important aussi !",
            ["DialogueId"] = 12010534,
            ["GUID"] = "1E112E3C",
            ["NextDialogue"] = 12010535,
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120105/1E112E3C",
            },
        [12010535] = {
            ["Content"] = "这样说起来，第一次遇到白的时候，好像也发生过类似的事情呢。",
            ["ContentFR"] = "Maintenant que tu le dis... la première fois que j’ai rencontré Snow, il s’est passé quelque chose de similaire, non ?",
            ["DialogueId"] = 12010535,
            ["GUID"] = "1E112E66",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 12010536,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120105/1E112E66",
            },
        [12010536] = {
            ["Content"] = "噗嗤，原来白魔王大人也这么不拘小节。",
            ["ContentFR"] = "Ah ah... Ainsi, même le grand Roi Démon n’est pas toujours très regardant sur les détails.",
            ["DialogueId"] = 12010536,
            ["GUID"] = "1E112E90",
            ["NextDialogue"] = 12010537,
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120105/1E112E90",
            },
        [12010537] = {
            ["Content"] = "小、小仆从，你不要搞错了，那明明是在考验你的实力……",
            ["ContentFR"] = "H-Hé ! Petit larbin, ne te méprends pas ! C’était évidemment pour tester ta force... !",
            ["DialogueId"] = 12010537,
            ["GUID"] = "1E112EBA",
            ["GuideFacialId"] = "Angry",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120105/1E112EBA",
            },
        [12010601] = {
            ["Camera"] = "362.59375,523.266724,128.501953,0.000092,0.196914,-127.178719,35.000011,100000.0,false,Manual,2.8",
            ["Content"] = "前面就是啦，位于巨木之根，烟津渡区域规模最大的商会——百年春！",
            ["ContentFR"] = "Nous y voilà ! Sous les racines du grand arbre se dresse la plus grande guilde marchande de Port-des-Brumes : Éternel Printemps !",
            ["DialogueId"] = 12010601,
            ["Duration"] = 4,
            ["GUID"] = "1E11393A",
            ["NextDialogue"] = 12010602,
            ["RelatedWikiId"] = {
                [1] = 408010,
                [2] = 408011,
                [3] = 304003,
                [4] = 303008,
                },
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120106/1E11393A",
            },
        [12010602] = {
            ["Content"] = "愿此香华云，直达太皓处，恳求大慈悲，施与众生乐。",
            ["ContentFR"] = "Que ces nuées parfumées atteignent Taihao. Puisse la grande compassion accorder paix et joie à tous les êtres.",
            ["DialogueId"] = 12010602,
            ["GUID"] = "1E113964",
            ["NextDialogue"] = 12010603,
            ["SpeakNpcName"] = "UI_CMName_Name_DevoutPilgrims",
            ["VoiceName"] = "voice/$Locale$/story/1201/120106/1E113964",
            },
        [12010603] = {
            ["Content"] = "这么多人在祈愿……白龙神君回应得过来吗？",
            ["ContentFR"] = "Il y a tellement de gens qui prient... Le Dragon d’Argent peut vraiment entendre tout le monde ?",
            ["DialogueId"] = 12010603,
            ["GUID"] = "1E11398E",
            ["NextDialogue"] = 12010604,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120106/1E11398E",
            },
        [12010604] = {
            ["Content"] = "呵呵，<H>奉香</>可不能视为众人向白龙神君进行索取的仪式。",
            ["ContentFR"] = "Il ne faut pas voir l’<H>offrande d’encens</> comme une demande adressée au Seigneur Dragon d’Argent.",
            ["DialogueId"] = 12010604,
            ["GUID"] = "1E1139B8",
            ["NextDialogue"] = 12010605,
            ["SpeakNpcId"] = 210033,
            ["VoiceName"] = "voice/$Locale$/story/1201/120106/1E1139B8",
            },
        [12010605] = {
            ["Content"] = "先前说过，大风九章需要以“香”为介质去维持运转。",
            ["ContentFR"] = "Comme je l’ai dit, les Neuf Chapitres de Dafeng utilisent l’encens comme médium pour se maintenir.",
            ["DialogueId"] = 12010605,
            ["GUID"] = "1E1139E2",
            ["NextDialogue"] = 12010606,
            ["RelatedWikiId"] = {
                [1] = 403005,
                },
            ["SpeakNpcId"] = 210033,
            ["VoiceName"] = "voice/$Locale$/story/1201/120106/1E1139E2",
            },
        [12010606] = {
            ["Content"] = "人们向上天奉香维持着大风九章，大风九章的意志则化形为白龙神君。人们尊奉神君的意志，祂又通过香庇佑人们。",
            ["ContentFR"] = "Le peuple offre l’encens au Ciel pour soutenir les Neuf Chapitres. La volonté des Préceptes se manifeste alors sous la forme du Seigneur Dragon d’Argent, qui, à son tour, protège le peuple par l’encens.",
            ["DialogueId"] = 12010606,
            ["GUID"] = "1E113A0C",
            ["NextDialogue"] = 12010607,
            ["SpeakNpcId"] = 210033,
            ["VoiceName"] = "voice/$Locale$/story/1201/120106/1E113A0C",
            },
        [12010607] = {
            ["Content"] = "愿望要靠勤耕不辍去一步步实现，白龙神君只是见证这一过程，千年皆是如此。",
            ["ContentFR"] = "Les vœux ne se réalisent qu’au prix d’efforts constants. Le Seigneur Dragon d’Argent n’est que le témoin silencieux de ce chemin, depuis des millénaires.",
            ["DialogueId"] = 12010607,
            ["GUID"] = "1E113A36",
            ["NextDialogue"] = 12010608,
            ["SpeakNpcId"] = 210033,
            ["VoiceName"] = "voice/$Locale$/story/1201/120106/1E113A36",
            },
        [12010608] = {
            ["Content"] = "不过，偶尔也会出现几位福星，能够得到白龙神君的青睐，获得意想不到的好处呢。",
            ["ContentFR"] = "Cela dit... il arrive que quelques rares élus reçoivent sa faveur et obtiennent une bénédiction inattendue.",
            ["DialogueId"] = 12010608,
            ["GUID"] = "1E113A60",
            ["NextDialogue"] = 12010609,
            ["SpeakNpcId"] = 210033,
            ["VoiceName"] = "voice/$Locale$/story/1201/120106/1E113A60",
            },
        [12010609] = {
            ["Content"] = "哎？白有点好奇。来都来了，白也想体验一下！",
            ["ContentFR"] = "Oh ? Maintenant, je suis curieuse ! Puisqu’on est là, je veux essayer aussi !",
            ["DialogueId"] = 12010609,
            ["GUID"] = "1E113A8A",
            ["NextDialogue"] = 12010610,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120106/1E113A8A",
            },
        [12010610] = {
            ["Content"] = "那，你去找香案边上的那位！他是<H>悬衡派</>的香官，负责主持祠堂的秩序。",
            ["ContentFR"] = "Dans ce cas, adresse-toi à l’officiant près de l’autel. C’est un responsable de la <H>Secte Xuanheng</> — il veille à l’ordre du sanctuaire.",
            ["DialogueId"] = 12010610,
            ["GUID"] = "1E113AB4",
            ["NextDialogue"] = 12010611,
            ["RelatedWikiId"] = {
                [1] = 407006,
                },
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120106/1E113AB4",
            },
        [12010611] = {
            ["Content"] = "悬衡派……你好像说过，是那位“天人相感”的大风九章奠基者开创的门派？",
            ["ContentFR"] = "La Secte Xuanheng... Celle fondée par la personne capable de communier avec le Ciel, la fondatrice des Neuf Chapitres ?",
            ["DialogueId"] = 12010611,
            ["GUID"] = "1E113ADE",
            ["NextDialogue"] = 12010612,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120106/1E113ADE",
            },
        [12010612] = {
            ["Content"] = "没错！看来{nickname}有认真听课，我很欣慰哦。",
            ["ContentFR"] = "Exactement ! On dirait bien que {nickname} a suivi la leçon avec attention — ça me fait vraiment plaisir !",
            ["DialogueId"] = 12010612,
            ["GUID"] = "1E113B08",
            ["NextDialogue"] = 12010613,
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120106/1E113B08",
            },
        [12010613] = {
            ["Content"] = "在上古时期，悬衡派最先发现了香的神奇功效，并作为独门秘方一直传承了下来。",
            ["ContentFR"] = "Dans les temps anciens, la Secte Xuanheng fut la première à découvrir les propriétés mystiques de l’encens, et elle en a préservé le secret comme un savoir exclusif.",
            ["DialogueId"] = 12010613,
            ["GUID"] = "1E113B32",
            ["NextDialogue"] = 12010614,
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120106/1E113B32",
            },
        [12010614] = {
            ["Content"] = "直至今日，悬衡派也一直负责着华胥境内的奉香事宜。一路上看到的香炉都是他们的手笔。",
            ["ContentFR"] = "Aujourd’hui encore, elle gère toutes les offrandes d’encens à Huaxu. Tous les encensoirs que vous avez vus ? Leur œuvre.",
            ["DialogueId"] = 12010614,
            ["GUID"] = "1E113B5C",
            ["NextDialogue"] = 12010615,
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120106/1E113B5C",
            },
        [12010615] = {
            ["Content"] = "每人每天能找悬衡派的官员无偿领取三支香。你们也去试试看吧！",
            ["ContentFR"] = "Chaque personne peut recevoir gratuitement trois bâtons d’encens par jour. Allez essayer !",
            ["DialogueId"] = 12010615,
            ["GUID"] = "1E113B86",
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120106/1E113B86",
            },
        [12010616] = {
            ["Content"] = "愿你善根常驻。",
            ["ContentFR"] = "Que votre vertu demeure.",
            ["DialogueId"] = 12010616,
            ["GUID"] = "1E113BB0",
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{210034},AnimationId{\"Pray_Start\"},Duration{1.83}},\
PlayAnimation{ActorId{210034},AnimationId{\"Pray_Loop\"},Duration{1}},\
PlayAnimation{ActorId{210034},AnimationId{\"Pray_End\"},Duration{1.87}}\
}",
            ["SpeakNpcId"] = 210034,
            ["VoiceName"] = "voice/$Locale$/story/1201/120106/1E113BB0",
            },
        [12010617] = {
            ["Content"] = "来，最后一段路啦！",
            ["ContentFR"] = "Allez, dernière ligne droite !",
            ["DialogueId"] = 12010617,
            ["Duration"] = 2,
            ["GUID"] = "1E113BDA",
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120106/1E113BDA",
            },
        [12010701] = {
            ["Camera"] = "520.380859,617.213379,-28.979492,0.000073,13.797665,-129.582932,35.000008,100000.0,false,Manual,2.8",
            ["Content"] = "前面就是百年春的办事处！止流大当家现在估计就在上面等着你们呢。我就带路到这里了，你们自己上去吧。",
            ["ContentFR"] = "Voilà le bureau d’Éternel Printemps ! La Patronne Zhiliu doit vous attendre là-haut. Je m’arrête ici — à vous de continuer.",
            ["DialogueId"] = 12010701,
            ["GUID"] = "1E1149A2",
            ["NextDialogue"] = 12010702,
            ["RelatedWikiId"] = {
                [1] = 408010,
                [2] = 408011,
                [3] = 304003,
                [4] = 406004,
                },
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120107/1E1149A2",
            },
        [12010702] = {
            ["Camera"] = "325.501953,283.450684,112.541016,0.000078,0.797322,-149.78244,35.000008,100000.0,false,Manual,2.8",
            ["Content"] = "我的铺位在这里，有空要来找我玩哦。如果想买什么，给你们打九九九八折！",
            ["ContentFR"] = "Mon étal est juste là. Passez me voir quand vous voulez ! Je vous ferai... une remise de 0,02 % !",
            ["DialogueId"] = 12010702,
            ["GUID"] = "1E1149CC",
            ["NextDialogue"] = 12010703,
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120107/1E1149CC",
            },
        [12010703] = {
            ["Content"] = "等等——多少？我没听错吧？怎么这么小气！",
            ["ContentFR"] = "Hein ? Combien ?! J’ai bien entendu ? Quelle pingrerie !",
            ["DialogueId"] = 12010703,
            ["GUID"] = "1E1149F6",
            ["NextDialogue"] = 12010704,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120107/1E1149F6",
            },
        [12010704] = {
            ["Content"] = "毕竟约定过了，要成为华胥第一的织星客嘛！",
            ["ContentFR"] = "J’ai promis de devenir la première Tisse-Étoiles de Huaxu !",
            ["DialogueId"] = 12010704,
            ["GUID"] = "1E114A20",
            ["NextDialogue"] = 12010705,
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120107/1E114A20",
            },
        [12010705] = {
            ["Content"] = "锦鲤皎皎没有角，已经输在起跑线上了。如果不加倍地投机取巧，锱铢必较，勤能补拙，是达不到这个目标的！",
            ["ContentFR"] = "Sans cornes, je pars avec un handicap. Alors il faut ruser, compter chaque détail et redoubler d’efforts !",
            ["DialogueId"] = 12010705,
            ["GUID"] = "1E114A4A",
            ["NextDialogue"] = 12010706,
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120107/1E114A4A",
            },
        [12010706] = {
            ["Content"] = "原、原来是这样吗……",
            ["ContentFR"] = "A-Ah... Je vois...",
            ["DialogueId"] = 12010706,
            ["GUID"] = "1E114A74",
            ["NextDialogue"] = 12010707,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120107/1E114A74",
            },
        [12010707] = {
            ["Content"] = "让你到处带坏别的皎皎，这下知道错了吧。",
            ["ContentFR"] = "Voilà ce qui arrive quand tu influences les autres Luno n’importe comment.",
            ["DialogueId"] = 12010707,
            ["GUID"] = "1E114A9E",
            ["NextDialogue"] = 12010708,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120107/1E114A9E",
            },
        [12010708] = {
            ["Content"] = "咳咳……小仆从，我们赶紧走吧，别让金主大人久等了！",
            ["ContentFR"] = "H-Humph ! Allez, petit larbin, on y va ! Ne faisons pas attendre notre généreuse mécène !",
            ["DialogueId"] = 12010708,
            ["GUID"] = "1E114AC8",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120107/1E114AC8",
            },
        [12010709] = {
            ["Camera"] = "-10.451172,-172.71875,172.462891,0.000043,-13.01181,100.396614,24.0,100000.0,false,Manual,22.0",
            ["Content"] = "……适才情绪激动，如今冷静下来仔细想想，确是我做得不妥了。",
            ["ContentFR"] = "... Tout à l’heure, l’émotion m’a emporté. À présent que j’ai repris mes esprits, je dois bien admettre que j’ai agi de façon inconsidérée.",
            ["DialogueId"] = 12010709,
            ["FacialId"] = {
                [1] = "210006:CM_Sad01",
                },
            ["GUID"] = "1E114AF2",
            ["LookAt"] = {
                [1] = "210005:n(210006)",
                [2] = "210033:n(210006)",
                },
            ["NextDialogue"] = 12010710,
            ["RelatedWikiId"] = {
                [1] = 408010,
                [2] = 408011,
                [3] = 304003,
                [4] = 406004,
                },
            ["SpeakNpcId"] = 210005,
            ["TalkActionId"] = {
                [1] = "210006:Sigh_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120107/1E114AF2",
            },
        [12010710] = {
            ["Content"] = "实在是我病急乱投医，昏了头才会从外面雇来个底细不清的人，还想凭一己之力闯一闯，将货物运到对面去。",
            ["ContentFR"] = "J’ai paniqué, perdu tout discernement... Au point d’engager à l’extérieur quelqu’un dont je ne connaissais rien, en espérant forcer le passage et acheminer mes marchandises par mes propres moyens.",
            ["DialogueId"] = 12010710,
            ["GUID"] = "1E114B1C",
            ["NextDialogue"] = 12010711,
            ["SpeakNpcId"] = 210005,
            ["VoiceName"] = "voice/$Locale$/story/1201/120107/1E114B1C",
            },
        [12010711] = {
            ["Camera"] = "-23.115234,32.113281,166.745117,0.000075,-7.412141,88.993202,35.0,100000.0,false,Manual,22.0",
            ["Content"] = "结果那武人是个花架子，非但应付不来玄色狴犴，还是个心术不正、鸡鸣狗盗之徒，平白惹出这么多事端。我在这里给乡亲父老们赔礼了！",
            ["ContentFR"] = "Et voilà le résultat : un pseudo-guerrier sans réelle compétence, incapable de tenir tête à un Bi’an obscur, et pire encore, un individu malhonnête, prompt aux larcins. J’ai causé bien des troubles inutiles... Je présente mes excuses à tous.",
            ["DialogueId"] = 12010711,
            ["GUID"] = "1E114B46",
            ["LookAt"] = {
                [1] = "210006:n(210005)",
                },
            ["NextDialogue"] = 12010712,
            ["SpeakNpcId"] = 210005,
            ["TalkActionId"] = {
                [1] = "210006:Sigh_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120107/1E114B46",
            },
        [12010712] = {
            ["Camera"] = "142.71875,232.458008,189.438477,0.000114,-18.212145,-157.608566,24.0,100000.0,false,Manual,22.0",
            ["Content"] = "您也不必如此自责。大家这些天心急如焚，百年春都看在眼里。",
            ["ContentFR"] = "Ne vous accablez pas outre mesure. Ces derniers jours ont été éprouvants pour tout le monde. Éternel Printemps en est parfaitement conscient.",
            ["DialogueId"] = 12010712,
            ["GUID"] = "1E114B70",
            ["LookAt"] = {
                [1] = "210005:n(210033)",
                [2] = "210006:n(210033)",
                },
            ["NextDialogue"] = 12010713,
            ["SpeakNpcId"] = 210022,
            ["TalkActionId"] = {
                [1] = "210033:Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120107/1E114B70",
            },
        [12010713] = {
            ["Content"] = "目前我们也在积极寻找对策，早日化解当下的危机，让大家的生意可以重回正轨。",
            ["ContentFR"] = "Nous cherchons activement des solutions. Dès que la crise actuelle sera surmontée, le commerce pourra reprendre son cours normal.",
            ["DialogueId"] = 12010713,
            ["GUID"] = "1E114B9A",
            ["NextDialogue"] = 12010714,
            ["SpeakNpcId"] = 210022,
            ["TalkActionId"] = {
                [1] = "210033:Talk02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120107/1E114B9A",
            },
        [12010714] = {
            ["Camera"] = "-47.478516,-40.796875,121.547852,0.000145,2.387158,110.985695,35.0,100000.0,false,Manual,22.0",
            ["Content"] = "只是，这禁行令还要延续多久呢？我们织星客等得起，货可等不起啊……",
            ["ContentFR"] = "Mais... combien de temps ce Décret d’Interdiction va-t-il encore durer ? Nous, Tisse-Étoiles, pouvons attendre... mais pas nos marchandises.",
            ["DialogueId"] = 12010714,
            ["FacialId"] = {
                [1] = "210005:Unacceptable01",
                },
            ["GUID"] = "1E114BC4",
            ["LookAt"] = {
                [1] = "210006:n(210005)",
                [2] = "210033:n(210005)",
                },
            ["NextDialogue"] = 12010715,
            ["RelatedWikiId"] = {
                [1] = 407007,
                },
            ["SpeakNpcId"] = 210006,
            ["TalkActionId"] = {
                [1] = "210005:Angry01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120107/1E114BC4",
            },
        [12010715] = {
            ["Content"] = "这个时节的药草，要趁刚摘下来，还沾着露水的新鲜劲，才能卖出个好价钱。放在篮子里，那是日日都在贬值啊。",
            ["ContentFR"] = "Les plantes médicinales de saison doivent être vendues sitôt cueillies, encore perlées de rosée, pour atteindre leur juste valeur. Chaque jour passé dans un panier, leur prix s’effondre.",
            ["DialogueId"] = 12010715,
            ["FacialId"] = {
                [1] = "210005:CM_Idle",
                },
            ["GUID"] = "1E114BEE",
            ["NextDialogue"] = 12010716,
            ["SpeakNpcId"] = 210006,
            ["VoiceName"] = "voice/$Locale$/story/1201/120107/1E114BEE",
            },
        [12010716] = {
            ["Camera"] = "-53.175781,137.40918,147.086914,0.000151,-8.01328,-123.215157,35.0,100000.0,false,Manual,22.0",
            ["Content"] = "这……烛阴之灾肆虐。它何时能偃旗息鼓，恐怕没人能给出承诺。",
            ["ContentFR"] = "... Le Fléau de Zhuyin sévit encore. Quant à la date de son apaisement... nul ne saurait s’y engager.",
            ["DialogueId"] = 12010716,
            ["FacialId"] = {
                [1] = "210033:CM_Sad01",
                },
            ["GUID"] = "1E114C18",
            ["NextDialogue"] = 12010717,
            ["SpeakNpcId"] = 210022,
            ["TalkActionId"] = {
                [1] = "210005:Angry01_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120107/1E114C18",
            },
        [12010717] = {
            ["Camera"] = "257.292969,-47.435547,8.095703,0.000389,-3.810276,90.187614,35.0,100000.0,false,Manual,22.0",
            ["Content"] = "——放心，最多三日，必有解法。",
            ["ContentFR"] = "Rassurez-vous. Trois jours. Pas davantage. Une solution sera trouvée.",
            ["DialogueId"] = 12010717,
            ["FacialId"] = {
                [1] = "210033:CM_Idle",
                [2] = "210005:CM_Idle",
                [3] = "210006:CM_Idle",
                },
            ["FinalCamera"] = "257.292969,-47.435547,8.095703,0.000394,-5.410247,120.785744,35.0,100000.0,false,Manual,22.0",
            ["GUID"] = "1E114C42",
            ["LookAt"] = {
                [1] = "210005:n(210004)",
                [2] = "210033:n(210004)",
                [3] = "210006:n(210004)",
                [4] = "210004:n(210005)",
                },
            ["NextDialogue"] = 12010718,
            ["Scripts"] = "PARA{\
MoveTo{ActorId{210004},MoveSpeed{90},TargetPoint{\"zhiliu_walkin_14\"}},\
SetRotation{SetRotationDescription{\"210005:n(210004)\"}},\
SetRotation{SetRotationDescription{\"210006:n(210004)\"}},\
