SEQ{\
CameraMoveTo{_delay{1},TargetPosition{\"-335.083984,163.441406,56.609375,0.000274,-3.011751,-7.796738,24.0,100000.0,false,Manual,22.0\"},duration{0}},\
CameraMoveTo{_delay{0},TargetPosition{\"-335.083984,163.441406,56.609375,0.000274,8.988139,-7.595475,24.0,100000.0,false,Manual,22.0\"},duration{1.5}},\
}\
}",
            ["SpeakNpcId"] = 210004,
            ["ToFinalCameraBlendTime"] = 1.5,
            ["VoiceName"] = "voice/$Locale$/story/1201/120107/1E114C42",
            },
        [12010718] = {
            ["Camera"] = "-335.083984,163.441406,56.609375,0.000274,8.988139,-7.595475,24.0,100000.0,false,Manual,22.0",
            ["Content"] = "止流大当家，您回来了！",
            ["ContentFR"] = "Patronne Zhiliu, vous voilà de retour !",
            ["DialogueId"] = 12010718,
            ["GUID"] = "1E114C6C",
            ["LookAt"] = {
                [1] = "210004:n(210033)",
                },
            ["NextDialogue"] = 12010719,
            ["SpeakNpcId"] = 210022,
            ["TalkActionId"] = {
                [1] = "210033:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120107/1E114C6C",
            },
        [12010719] = {
            ["Content"] = "听您刚刚话中的意思……您找到办法了？",
            ["ContentFR"] = "À vous entendre... auriez-vous déjà une piste ?",
            ["DialogueId"] = 12010719,
            ["GUID"] = "1E114C96",
            ["LookAt"] = {
                [1] = "210004:n(210006)",
                },
            ["NextDialogue"] = 12010720,
            ["SpeakNpcId"] = 210006,
            ["TalkActionId"] = {
                [1] = "210006:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120107/1E114C96",
            },
        [12010720] = {
            ["Content"] = "嗯，我这趟出门，正是为此。目前算是有些眉目了。",
            ["ContentFR"] = "Oui. C’était précisément l’objet de mon déplacement. Les choses commencent à se préciser.",
            ["DialogueId"] = 12010720,
            ["GUID"] = "1E114CC0",
            ["LookAt"] = {
                [1] = "210004:n(210004)",
                },
            ["NextDialogue"] = 12010721,
            ["SpeakNpcId"] = 210004,
            ["TalkActionId"] = {
                [1] = "210004:AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120107/1E114CC0",
            },
        [12010721] = {
            ["Camera"] = "-77.384766,173.716797,147.136719,0.000315,-7.212358,-15.157565,24.0,175.226349,false,Manual,3.0",
            ["Content"] = "你们也不必心焦。对于那些有时效性的货物，百年春愿意出市价八折收购。无论货物多少，照单全收。",
            ["ContentFR"] = "Inutile de céder à la panique. Pour les marchandises sensibles au temps, Éternel Printemps est disposé à les racheter à 80 % du prix du marché, sans limitation de quantité.",
            ["DialogueId"] = 12010721,
            ["GUID"] = "1E114CEA",
            ["NextDialogue"] = 12010722,
            ["SpeakNpcId"] = 210004,
            ["TalkActionId"] = {
                [1] = "210004:Think_Start",
                [2] = "210033:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120107/1E114CEA",
            },
        [12010722] = {
            ["Content"] = "考虑到途中的运输损耗、以及分销的资金回转周期，这应当是个相当公道的价格。",
            ["ContentFR"] = "En tenant compte des pertes liées au transport et des délais de redistribution, il s’agit là d’une proposition parfaitement équitable.",
            ["DialogueId"] = 12010722,
            ["GUID"] = "1E114D14",
            ["LookAt"] = {
                [1] = "210004:n(210005)",
                },
            ["NextDialogue"] = 12010723,
            ["SpeakNpcId"] = 210004,
            ["TalkActionId"] = {
                [1] = "210004:Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120107/1E114D14",
            },
        [12010723] = {
            ["Camera"] = "108.34375,-30.554688,146.777344,0.000405,-14.413454,127.619759,14.0,175.226349,false,Manual,22.0",
            ["Content"] = "烛阴之灾的影响结束后，如果你们有意，可以用同样的价格购回。",
            ["ContentFR"] = "Une fois l’influence du Fléau dissipée, vous pourrez, si vous le souhaitez, racheter ces biens au même tarif.",
            ["DialogueId"] = 12010723,
            ["GUID"] = "1E114D3E",
            ["NextDialogue"] = 12010724,
            ["SpeakNpcId"] = 210004,
            ["TalkActionId"] = {
                [1] = "210004:Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120107/1E114D3E",
            },
        [12010724] = {
            ["Camera"] = "-25.605469,65.655273,156.426758,0.000454,-11.014889,15.216454,35.000008,175.226349,false,Manual,22.0",
            ["Content"] = "倘若有人还想雇佣护卫，自行闯荡，百年春不会拦着。",
            ["ContentFR"] = "Quant à ceux qui persisteraient à vouloir engager des gardes et tenter leur chance seuls... Éternel Printemps ne s’y opposera pas.",
            ["DialogueId"] = 12010724,
            ["GUID"] = "1E114D68",
            ["NextDialogue"] = 12010725,
            ["SpeakNpcId"] = 210004,
            ["TalkActionId"] = {
                [1] = "210006:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120107/1E114D68",
            },
        [12010725] = {
            ["Camera"] = "62.994141,74.545898,142.055664,0.00016,-16.819853,47.249294,24.0,59.213684,false,Manual,22.0",
            ["Content"] = "若是雇来了些下三滥的货色，触犯了诫律，不用百年春禁止，狴犴自会出手。到时候万一人财两空，可别怪我没把话说在前头。",
            ["ContentFR"] = "Toutefois, si vous recrutez des individus douteux, enfreignant les Préceptes, je n’aurai nul besoin d’intervenir. Les Bi’an s’en chargeront. Et si vous y perdez à la fois vos hommes et vos biens... ne dites pas que je ne vous avais pas prévenus.",
            ["DialogueId"] = 12010725,
            ["GUID"] = "1E114D92",
            ["LookAt"] = {
                [1] = "210004:n(210004)",
                },
            ["NextDialogue"] = 12010726,
            ["SpeakNpcId"] = 210004,
            ["TalkActionId"] = {
                [1] = "210004:Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120107/1E114D92",
            },
        [12010726] = {
            ["Camera"] = "101.078125,42.186523,136.551758,0.000141,-1.41695,124.660164,24.0,59.21368,false,Manual,22.0",
            ["Content"] = "不敢不敢，已经吃到教训了……",
            ["ContentFR"] = "Nous n’oserions plus... La leçon a été amplement retenue.",
            ["DialogueId"] = 12010726,
            ["FacialId"] = {
                [1] = "210005:CM_Shock01",
                },
            ["GUID"] = "1E114DBC",
            ["LookAt"] = {
                [1] = "210004:n(210005)",
                },
            ["NextDialogue"] = 12010727,
            ["SpeakNpcId"] = 210005,
            ["TalkActionId"] = {
                [1] = "210005:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120107/1E114DBC",
            },
        [12010727] = {
            ["Content"] = "听了您这番话，我们便安心了。这种时候，还得是止流大当家，给大伙儿一颗定心丸啊。",
            ["ContentFR"] = "Vos paroles nous apaisent. En de telles circonstances, il n’y a que vous, Patronne Zhiliu, pour apaiser les esprits.",
            ["DialogueId"] = 12010727,
            ["FacialId"] = {
                [1] = "210006:CM_Smile01",
                },
            ["GUID"] = "1E114DE6",
            ["NextDialogue"] = 12010728,
            ["SpeakNpcId"] = 210006,
            ["TalkActionId"] = {
                [1] = "210006:Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120107/1E114DE6",
            },
        [12010728] = {
            ["Camera"] = "-335.083984,163.441406,56.609375,0.000274,8.988139,-7.595475,24.0,100000.0,false,Manual,22.0",
            ["Content"] = "你们近日担惊受怕，都辛苦了。若无其他要事，先回去休整一下，静候佳音吧。",
            ["ContentFR"] = "Vous avez tous vécu dans la crainte ces derniers jours. Reposez-vous. Attendez les nouvelles en toute sérénité.",
            ["DialogueId"] = 12010728,
            ["GUID"] = "1E114E10",
            ["SpeakNpcId"] = 210004,
            ["TalkActionId"] = {
                [1] = "210004:Talk03_End",
                [2] = "210006:Talk01_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120107/1E114E10",
            },
        [12010801] = {
            ["Camera"] = "304.855316,544.535767,34.631836,0.000097,7.994593,-130.562805,50.0,100000.0,false,Manual,22",
            ["Content"] = "你们来了？玩得怎么样？",
            ["ContentFR"] = "Vous voilà. Alors... comment s’est déroulée votre promenade ?",
            ["DialogueId"] = 12010801,
            ["FinalCamera"] = "279.991364,515.381226,40.009766,0.000097,7.994593,-129.962708,50.0,100000.0,false,Manual,22",
            ["GUID"] = "1E115A0A",
            ["LookAt"] = {
                [1] = "100001:n(210004)",
                [2] = "200002:n(210004)",
                },
            ["NextDialogue"] = 12010802,
            ["RelatedWikiId"] = {
                [1] = 408010,
                [2] = 408011,
                [3] = 304003,
                [4] = 406004,
                },
            ["SpeakNpcId"] = 210004,
            ["ToFinalCameraBlendTime"] = 4,
            ["TurnTo"] = {
                [1] = "210004:n(100001)",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120108/1E115A0A",
            },
        [12010802] = {
            ["Camera"] = "-683.570435,-204.253418,151.115234,0.000145,-5.40716,26.220837,35.000008,811.822876,false,Manual,6.0",
            ["Content"] = "嗯，大家都很热情好客。华胥的风光和人们，都和冰湖城大不一样……",
            ["ContentFR"] = "Les habitants se sont montrés très accueillants. Les paysages comme les gens de Huaxu... tout est si différent de Givrelac.",
            ["DialogueId"] = 12010802,
            ["GUID"] = "1E115A34",
            ["LookAt"] = {
                [1] = "210004:n(100001)",
                [2] = "100001:n(210004)",
                [3] = "200002:n(210004)",
                },
            ["NextDialogue"] = 12010803,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120108/1E115A34",
            },
        [12010803] = {
            ["Content"] = "刚刚这里发生的事情我们都看到了！不愧是止流姐姐，三下五除二就把那些人摆平了！",
            ["ContentFR"] = "On a tout vu ! Franchement, Zhiliu, en quelques phrases tu as calmé tout le monde. Impressionnant !",
            ["DialogueId"] = 12010803,
            ["GUID"] = "1E115A5E",
            ["LookAt"] = {
                [1] = "210004:n(200002)",
                [2] = "100001:n(200002)",
                [3] = "200002:n(210004)",
                },
            ["NextDialogue"] = 12010804,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Excited02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120108/1E115A5E",
            },
        [12010804] = {
            ["Camera"] = "-186.132004,148.349823,117.378906,0.000099,12.793374,-73.770279,35.0,167.978699,false,Manual,6.0",
            ["Content"] = "呵呵，做生意就是琢磨如何和人打交道。这种小场面，我早就习以为常了。反倒是在冰湖城和你们结交，更为难得。",
            ["ContentFR"] = "Héhé... Le commerce consiste avant tout à comprendre les hommes. Ce genre de situation ne m’est plus étrangère. En revanche, vous rencontrer à Givrelac... voilà qui est plus rare.",
            ["DialogueId"] = 12010804,
            ["GUID"] = "1E115A88",
            ["NextDialogue"] = 12010805,
            ["Scripts"] = "SEQ{\
PlayFacial{ActorId{210004},FacialId{\"Ahaha01\"}},\
PlayFacial{_delay{2},ActorId{210004},FacialId{\"None\"}},\
LookAt{LookAtDescription{\"210004:n(100001)\"}}\
}",
            ["SpeakNpcId"] = 210004,
            ["TalkActionId"] = {
                [1] = "210004:Confident_Start",
                [2] = "200002:Excited02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120108/1E115A88",
            },
        [12010805] = {
            ["Content"] = "好啦，该切入正题了。我这次雇佣你们，是为了解决<H>烛阴之灾</>而做准备。至于这烛阴之灾是何物……",
            ["ContentFR"] = "Bien. Entrons dans le vif du sujet. Si je vous ai engagés, c’est pour préparer une réponse au Fléau de Zhuyin. Quant à sa véritable nature...",
            ["DialogueId"] = 12010805,
            ["GUID"] = "1E115AB2",
            ["LookAt"] = {
                [1] = "210004:n(100001)",
                [2] = "100001:n(210004)",
                [3] = "200002:n(210004)",
                },
            ["NextDialogue"] = 12010806,
            ["Scripts"] = "PlayAnimation{_delay{2},ActorId{210004},AnimationId{\"Explain02_Start\"},Duration{1}}",
            ["SpeakNpcId"] = 210004,
            ["TalkActionId"] = {
                [1] = "210004:Confident_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120108/1E115AB2",
            },
        [12010806] = {
            ["Camera"] = "-220.036377,-24.106567,165.826172,0.000193,-11.806978,37.620747,25.0,356.590881,false,Manual,6.0",
            ["Content"] = "我们已经有所了解啦！",
            ["ContentFR"] = "Oh, on en a déjà appris un peu !",
            ["DialogueId"] = 12010806,
            ["GUID"] = "1E115ADC",
            ["LookAt"] = {
                [1] = "210004:n(200002)",
                [2] = "100001:n(200002)",
                [3] = "200002:n(210004)",
                },
            ["NextDialogue"] = 12010807,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Confident_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120108/1E115ADC",
            },
        [12010807] = {
            ["Content"] = "哦？说来听听。",
            ["ContentFR"] = "Vraiment ? Expliquez-moi.",
            ["DialogueId"] = 12010807,
            ["GUID"] = "1E115B06",
            ["NextDialogue"] = 12010808,
            ["SpeakNpcId"] = 210004,
            ["TalkActionId"] = {
                [1] = "210004:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120108/1E115B06",
            },
        [12010808] = {
            ["Camera"] = "-156.516678,87.370865,141.241211,0.000193,-1.207092,50.224213,35.000008,157.917465,false,Manual,6.0",
            ["Content"] = "过来的路上，我们遭遇了玄色狴犴的袭击。幸好有位过路的行商相助，我们击退了它，没有受伤。",
            ["ContentFR"] = "Sur la route, nous avons été attaqués par un Bi’an obscur. Une marchande de passage nous a aidés à nous en débarrasser, sans blessés.",
            ["DialogueId"] = 12010808,
            ["GUID"] = "1E115B30",
            ["LookAt"] = {
                [1] = "210004:n(100001)",
                [2] = "100001:n(210004)",
                [3] = "200002:n(210004)",
                },
            ["NextDialogue"] = 12010809,
            ["Scripts"] = "SEQ{\
PlayFacial{ActorId{100001},FacialId{\"Sad01\"}},\
PlayFacial{_delay{3},ActorId{100001},FacialId{\"None\"}},\
LookAt{LookAtDescription{\"100001:n(210004)\"}}\
}",
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120108/1E115B30",
            },
        [12010809] = {
            ["Camera"] = "-77.715431,89.802849,133.813477,0.000236,-18.807245,30.218388,35.000008,141.948105,false,Manual,6.0",
            ["Content"] = "行商姐姐告诉我们，就是这个什么烛阴之灾，会诞生很多像玄色狴犴一样的坏东西，然后它们四处咬人，让大家的日子很难过！",
            ["ContentFR"] = "Elle nous a dit que ce Fléau engendrait plein de monstres comme ça, qui s’en prennent aux gens et rendent la vie impossible !",
            ["DialogueId"] = 12010809,
            ["FacialId"] = {
                [1] = "200002:Think02",
                },
            ["GUID"] = "1E115B5A",
            ["NextDialogue"] = 12010810,
            ["Scripts"] = "PlayAnimation{_delay{2},ActorId{200002},AnimationId{\"Think_Start\"},Duration{1}}",
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Confident_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120108/1E115B5A",
            },
        [12010810] = {
            ["Camera"] = "-172.129272,202.076614,182.18457,0.000255,-10.007812,-82.578522,35.0,230.644745,false,Manual,6.0",
            ["Content"] = "不错。玄色狴犴出现之前，你们可曾看到或听到什么异象？",
            ["ContentFR"] = "C’est exact. Avant son apparition, avez-vous perçu un phénomène particulier ?",
            ["DialogueId"] = 12010810,
            ["FacialId"] = {
                [1] = "200002:None",
                },
            ["GUID"] = "1E115B84",
            ["NextDialogue"] = 12010811,
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{210004},AnimationId{\"AgreeHead\"},Duration{1}},\
PlayAnimation{ActorId{210004},AnimationId{\"Talk02_Start\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 210004,
            ["TalkActionId"] = {
                [1] = "200002:Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120108/1E115B84",
            },
        [12010811] = {
            ["Camera"] = "-115.231911,95.112503,138.404297,0.000265,2.191896,62.419701,35.000008,144.229248,false,Manual,6.0",
            ["Content"] = "好像……从虚空中传来过某种异兽吼叫的声音。",
            ["ContentFR"] = "Oui... Un rugissement. Comme venu du vide.",
            ["DialogueId"] = 12010811,
            ["FacialId"] = {
                [1] = "100001:Doubt01",
                },
            ["GUID"] = "1E115BAE",
            ["NextDialogue"] = 12010812,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120108/1E115BAE",
            },
        [12010812] = {
            ["Camera"] = "-62.248718,279.597717,140.96582,0.000271,0.991805,-101.18074,35.0,357.667114,false,Manual,6.0",
            ["Content"] = "是了。那便是数载前被封印的恶蛟，如今正在复苏中的<H>烛阴</>发出的嘶吼。",
            ["ContentFR"] = "Alors il ne fait aucun doute. C’était le cri de Zhuyin, le dragon maléfique jadis scellé, désormais en train de s’éveiller.",
            ["DialogueId"] = 12010812,
            ["FacialId"] = {
                [1] = "100001:None",
                },
            ["GUID"] = "1E115BD8",
            ["NextDialogue"] = 12010813,
            ["RelatedWikiId"] = {
                [1] = 303011,
                },
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{210004},AnimationId{\"AgreeHead\"},Duration{1}},\
PlayAnimation{ActorId{210004},AnimationId{\"Talk02_End\"},Duration{1}},\
}",
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120108/1E115BD8",
            },
        [12010813] = {
            ["Content"] = "烛阴是华胥远古传说中，与白龙神君相敌对的恶神。它失智、狂乱的力量泄露而出，使恶兽横行。部分区域受其影响，也变得草木不生。",
            ["ContentFR"] = "Dans les légendes antiques de Huaxu, Zhuyin est l’ennemi juré du Seigneur Dragon d’Argent. Sa puissance démente s’échappe, donnant naissance à des bêtes corrompues. Les terres qu’il souille deviennent stériles.",
            ["DialogueId"] = 12010813,
            ["FacialId"] = {
                [1] = "210004:Angry01",
                },
            ["GUID"] = "1E115C02",
            ["NextDialogue"] = 12010814,
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{210004},AnimationId{\"Talk03_Start\"},Duration{1}},\
LookAt{LookAtDescription{\"210004:n(200002)\"}},\
LookAt{_delay{3},LookAtDescription{\"210004:n(100001)\"}}\
}",
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120108/1E115C02",
            },
        [12010814] = {
            ["Content"] = "百年之前，在烟津渡区域，烛阴之灾初显端倪。时人只能仓皇应对，损失惨重，集结了众多人力物力才将其降服。",
            ["ContentFR"] = "Il y a cent ans, à Port-des-Brumes, le Fléau s’est manifesté pour la première fois. À l’époque, on ne l’a contenu qu’au prix de sacrifices immenses.",
            ["DialogueId"] = 12010814,
            ["FacialId"] = {
                [1] = "210004:Think01",
                },
            ["GUID"] = "1E115C2C",
            ["LookAt"] = {
                [1] = "210004:n(210004)",
                },
            ["NextDialogue"] = 12010815,
            ["Scripts"] = "LookAt{_delay{2},LookAtDescription{\"210004:n(100001)\"}}",
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120108/1E115C2C",
            },
        [12010815] = {
            ["Content"] = "如今，烛阴再度从封印中复苏。这次，我打算未雨绸缪，早做准备，避免重蹈上次的覆辙。",
            ["ContentFR"] = "Aujourd’hui, il se réveille de nouveau. Et cette fois, je refuse de répéter les erreurs du passé.",
            ["DialogueId"] = 12010815,
            ["FacialId"] = {
                [1] = "210004:Think01",
                },
            ["GUID"] = "1E115C56",
            ["LookAt"] = {
                [1] = "210004:n(100001)",
                [2] = "100001:n(210004)",
                [3] = "200002:n(210004)",
                },
            ["NextDialogue"] = 12010816,
            ["SpeakNpcId"] = 210004,
            ["TalkActionId"] = {
                [1] = "210004:Talk03ToTalkL_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120108/1E115C56",
            },
        [12010816] = {
            ["Camera"] = "-186.98848,-7.478424,161.543945,0.000262,-16.208401,29.619329,35.0,357.667114,false,Manual,6.0",
            ["Content"] = "哇，对手真的是一条龙耶，魔王大人已经热血沸腾起来了！那需要我和小仆从做什么呢？",
            ["ContentFR"] = "Un vrai dragon à affronter ! Le sang du Roi Démon bout déjà ! Alors, que devons-nous faire ?",
            ["DialogueId"] = 12010816,
            ["FacialId"] = {
                [1] = "210004:None",
                },
            ["GUID"] = "1E115C80",
            ["LookAt"] = {
                [1] = "210004:n(200002)",
                [2] = "100001:n(200002)",
                [3] = "200002:n(210004)",
                },
            ["NextDialogue"] = 12010817,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Excited01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120108/1E115C80",
            },
        [12010817] = {
            ["Camera"] = "-159.628098,156.141693,211.294922,0.000275,-23.008387,-83.780457,35.000008,179.894089,false,Manual,6.0",
            ["Content"] = "华胥禁武。纵是走南闯北的织星客，也少有人精通防身的一招半式。",
            ["ContentFR"] = "Huaxu proscrit le combat. Même les Tisse-Étoiles les plus aguerris savent à peine se défendre.",
            ["DialogueId"] = 12010817,
            ["GUID"] = "1E115CAA",
            ["LookAt"] = {
                [1] = "210004:n(100001)",
                [2] = "100001:n(210004)",
                [3] = "200002:n(210004)",
                },
            ["NextDialogue"] = 12010818,
            ["SpeakNpcId"] = 210004,
            ["TalkActionId"] = {
                [1] = "210004:Talk03ToTalkL_End",
                [2] = "200002:Excited01_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120108/1E115CAA",
            },
        [12010818] = {
            ["Content"] = "所以，这次我要委托你们的，便是孤身深入已彻底浊化的尘漠石海，将其中的<W>三片烛阴鳞</>取来，好为重新封印这个孽兽做准备。",
            ["ContentFR"] = "Je vous confie donc une mission : pénétrer seuls dans la Mer de Poussière, entièrement corrompue, et en rapporter <W>trois Écailles de Zhuyin</>. Elles sont indispensables au rituel de scellement.",
            ["DialogueId"] = 12010818,
            ["GUID"] = "1E115CD4",
            ["NextDialogue"] = 12010819,
            ["RelatedWikiId"] = {
                [1] = 301007,
                },
            ["SpeakNpcId"] = 210004,
            ["TalkActionId"] = {
                [1] = "210004:Talk03ToThink_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120108/1E115CD4",
            },
        [12010819] = {
            ["Camera"] = "-199.111633,-43.304016,157.180664,0.000239,-5.408567,52.814674,35.000008,332.602295,false,Manual,6.0",
            ["Content"] = "止流掌柜，可以问您一个问题吗？",
            ["ContentFR"] = "Patronne Zhiliu... Puis-je vous poser une question ?",
            ["DialogueId"] = 12010819,
            ["GUID"] = "1E115CFE",
            ["NextDialogue"] = 12010820,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120108/1E115CFE",
            },
        [12010820] = {
            ["Content"] = "这么重要的任务，您为何放心交给我一个名不经传的外来者去完成？",
            ["ContentFR"] = "Une tâche aussi cruciale... pourquoi la confier à {性别:un étranger|une étrangère} sans renommée ?",
            ["DialogueId"] = 12010820,
            ["FacialId"] = {
                [1] = "100001:Think01",
                },
            ["GUID"] = "1E115D28",
            ["NextDialogue"] = 12010821,
            ["Scripts"] = "PlayAnimation{_delay{1.5},ActorId{100001},AnimationId{\"Talk02_End\"},Duration{1}}",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120108/1E115D28",
            },
        [12010821] = {
            ["Camera"] = "-105.761864,145.154953,174.711914,0.00001,-19.008606,49.811211,35.0,101.71228,false,Manual,6.0",
            ["Content"] = "我只是一个涉世未深的狩月人。比我身手更好的想必还有很多。",
            ["ContentFR"] = "Je ne suis {性别:qu’un Chasseur de Phoxène encore inexpérimenté|qu’une Chasseuse de Phoxène encore inexpérimentée}. Il existe sûrement des combattants plus compétents.",
            ["DialogueId"] = 12010821,
            ["GUID"] = "1E115D52",
            ["NextDialogue"] = 12010822,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Talk02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120108/1E115D52",
            },
        [12010822] = {
            ["Content"] = "那时候在剧院，当我触碰香炉时，烟迹像是被吸引了一样，朝我倾斜……您委托我，和这件事有关系吗？",
            ["ContentFR"] = "Au théâtre, lorsque j’ai touché l’encensoir, la fumée semblait attirée par moi... Est-ce lié à votre décision ?",
            ["DialogueId"] = 12010822,
            ["GUID"] = "1E115D7C",
            ["NextDialogue"] = 12010823,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120108/1E115D7C",
            },
        [12010823] = {
            ["Camera"] = "-22.771553,316.24408,146.336914,0.000276,0.989838,-110.393227,120.000038,348.983032,false,Manual,6.0",
            ["Content"] = "……你却是敏锐。",
            ["ContentFR"] = "... Ton sens de l’observation est affûté.",
            ["DialogueId"] = 12010823,
            ["FacialId"] = {
                [1] = "210004:Zhiliu_SpecialDoubt",
                },
            ["FinalCamera"] = "-31.808182,319.469513,146.336914,0.000276,1.189867,-108.592857,120.000038,348.983032,false,Manual,6.0",
            ["GUID"] = "1E115DA6",
            ["NextDialogue"] = 12010824,
            ["SpeakNpcId"] = 210004,
            ["TalkActionId"] = {
                [1] = "210004:Talk03ToThink_End",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/story/1201/120108/1E115DA6",
            },
        [12010824] = {
            ["Content"] = "相信有人告诫过你了吧，你的能力很特殊，也很珍贵。而珍贵之物往往会引来觊觎。稍有不慎，就会为持有者招致灾难。",
            ["ContentFR"] = "On t’a sans doute déjà prévenu : ton don est rare. Et ce qui est rare attire la convoitise. Mal maîtrisé, il devient une source de péril.",
            ["DialogueId"] = 12010824,
            ["GUID"] = "1E115DD0",
            ["NextDialogue"] = 12010825,
            ["SpeakNpcId"] = 210004,
            ["TalkActionId"] = {
                [1] = "210004:AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120108/1E115DD0",
            },
        [12010825] = {
            ["Camera"] = "-135.171982,109.97921,130.675781,0.000303,10.789028,-97.396179,25.000002,108.903717,false,Manual,6.0",
            ["Content"] = "烛阴鳞并非常规手段可以采摘。需要一种高浓度活性物质与之共鸣，软化其束缚。",
            ["ContentFR"] = "Les Écailles de Zhuyin ne peuvent être extraites par des moyens ordinaires. Elles nécessitent une résonance avec une substance hautement active, capable d’en assouplir la contrainte.",
            ["DialogueId"] = 12010825,
            ["GUID"] = "1E115DFA",
            ["LookAt"] = {
                [1] = "210004:n(210004)",
                },
            ["NextDialogue"] = 12010826,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120108/1E115DFA",
            },
        [12010826] = {
            ["Content"] = "我此次前往冰湖城，本是为了试试帝国炼金院的高纯度月髓液是否可以生效，却无意间发现了你的存在——弥足珍贵的“和鸣者”。",
            ["ContentFR"] = "Je me rendais à Givrelac pour tester le Phoxichor de haute pureté de l’Académie d’Alchimie... et c’est ainsi que je t’ai {性别:rencontré. Un Résonant|rencontrée. Une Résonante} d’une valeur inestimable.",
            ["DialogueId"] = 12010826,
            ["GUID"] = "1E115E24",
            ["LookAt"] = {
                [1] = "210004:n(100001)",
                [2] = "100001:n(210004)",
                [3] = "200002:n(210004)",
                },
            ["NextDialogue"] = 12010827,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120108/1E115E24",
            },
        [12010827] = {
            ["Camera"] = "-63.153351,333.275513,163.25,0.000279,-12.610932,-89.191231,18.000004,386.075989,false,Manual,6.0",
            ["Content"] = "我需要借助你的能力去软化烛阴鳞。当然，你随时拥有拒绝的权利。一切还是以你的安危为最优先。",
            ["ContentFR"] = "J’ai besoin de ton pouvoir. Mais tu restes libre de refuser. Ta sécurité demeure prioritaire.",
            ["DialogueId"] = 12010827,
            ["GUID"] = "1E115E4E",
            ["NextDialogue"] = 12010828,
            ["RelatedWikiId"] = {
                [1] = 203001,
                },
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120108/1E115E4E",
            },
        [12010828] = {
            ["Camera"] = "-101.410286,105.261276,144.950195,0.000291,0.388911,66.010345,35.000008,115.940376,false,Manual,6.0",
            ["Content"] = "不。止流掌柜，感谢您的答案。这个任务，我接下了。",
            ["ContentFR"] = "Non. Merci pour votre franchise. J’accepte cette mission.",
            ["DialogueId"] = 12010828,
            ["FacialId"] = {
                [1] = "100001:Doubt01",
                },
            ["GUID"] = "1E115E78",
            ["NextDialogue"] = 12010829,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120108/1E115E78",
            },
        [12010829] = {
            ["Camera"] = "-135.763824,120.127022,133.164062,0.000261,7.987448,-98.385017,35.000011,132.596771,false,Manual,6.0",
            ["Content"] = "……你有没有想过，我对你伸出援手，或许也是看到了你的价值，从而别有用心？",
            ["ContentFR"] = "... As-tu envisagé que mon aide initiale relevait peut-être d’un calcul ?",
            ["DialogueId"] = 12010829,
            ["FacialId"] = {
                [1] = "100001:Think01",
                },
            ["GUID"] = "1E115EA2",
            ["NextDialogue"] = 12010830,
            ["SpeakNpcId"] = 210004,
            ["TalkActionId"] = {
                [1] = "100001:Explain02_End",
                [2] = "210004:Talk03ToTalkR_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120108/1E115EA2",
            },
        [12010830] = {
            ["Camera"] = "-233.40567,-36.296333,167.799805,0.000267,-10.612488,39.615959,25.0,351.067688,false,Manual,6.0",
            ["Content"] = "我想过，但这改变不了您帮助过我的事实。况且，我也有自己的私心。",
            ["ContentFR"] = "Oui. J’y ai pensé. Mais cela ne change rien au fait que vous m’avez aidé. Et j’ai, moi aussi, mes propres intérêts.",
            ["DialogueId"] = 12010830,
            ["FacialId"] = {
                [1] = "100001:Confident01",
                },
            ["GUID"] = "1E115ECC",
            ["LookAt"] = {
                [1] = "210004:n(100001)",
                [2] = "100001:n(210004)",
                [3] = "200002:n(100001)",
                },
            ["NextDialogue"] = 12010831,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:AgreeHead",
                [2] = "210004:Talk03ToTalkR_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120108/1E115ECC",
            },
        [12010831] = {
            ["Camera"] = "-143.548096,187.029388,180.547852,0.000277,-26.612356,2.415056,25.0,173.153748,false,Manual,6.0",
            ["Content"] = "我在寻找自己的家人，但我一个人的力量过于渺小。为了达到这个目的，我会抓住一切可以凭借的外力。",
            ["ContentFR"] = "Je cherche ma famille. {性别:Seul|Seule}, je n’y parviendrai pas. Pour cela, j’utiliserai toute aide disponible.",
            ["DialogueId"] = 12010831,
            ["GUID"] = "1E115EF6",
            ["NextDialogue"] = 12010832,
            ["Scripts"] = "PlayFacial{_delay{1.5},ActorId{200002},FacialId{\"Sad03\"}}",
            ["SpeakNpcId"] = 100001,
            ["TurnTo"] = {
                [1] = "200002:n(100001)",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120108/1E115EF6",
            },
        [12010832] = {
            ["Content"] = "如果帮助您可以换取未来某些时刻的援手，我想这是一笔相当划算的交易。",
            ["ContentFR"] = "Si vous assister aujourd’hui me vaut votre soutien demain, alors c’est un échange équitable.",
            ["DialogueId"] = 12010832,
            ["GUID"] = "1E115F20",
            ["NextDialogue"] = 12010833,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120108/1E115F20",
            },
        [12010833] = {
            ["Camera"] = "-51.572311,328.859131,154.874023,0.000277,-4.212703,-99.382347,35.000011,410.635406,false,Manual,6.0",
            ["Content"] = "更何况，您当初帮我解围之时，我对您而言只是一个随处可见的路人。您帮了我，我也想为您做点什么。",
            ["ContentFR"] = "D’autant plus qu’à l’époque, j’étais {性别:un parfait inconnu|une parfaite inconnue} à vos yeux. Vous m’avez aidé malgré tout. À présent, c’est à mon tour.",
            ["DialogueId"] = 12010833,
            ["GUID"] = "1E115F4A",
            ["NextDialogue"] = 12010834,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120108/1E115F4A",
            },
        [12010834] = {
            ["Camera"] = "-127.131332,108.307777,133.397461,0.000372,7.585963,-100.998802,25.000006,108.903717,false,Manual,6.0",
            ["Content"] = "呵呵……话都被你说尽了，我却没什么可说的了。看来假以时日，你也会成为一个优秀的“商人”。",
            ["ContentFR"] = "Héhé... Tu ne m’as laissé aucune réplique. Avec le temps, tu feras {性别:un excellent marchand|une excellente marchande}.",
            ["DialogueId"] = 12010834,
            ["FacialId"] = {
                [1] = "210004:Smile03",
                },
            ["GUID"] = "1E115F74",
            ["NextDialogue"] = 12010835,
            ["Scripts"] = "PlayFacial{_delay{3},ActorId{210004},FacialId{\"Smile01\"}}",
            ["SpeakNpcId"] = 210004,
            ["TalkActionId"] = {
                [1] = "210004:Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120108/1E115F74",
            },
        [12010835] = {
            ["Content"] = "在你出发前，那边桌子上有给你准备的盘缠。随意花，不够了再来向我要。",
            ["ContentFR"] = "Avant ton départ, une bourse t’attend sur la table. Utilise-la à ta guise. Si elle ne suffit pas, reviens me voir.",
            ["DialogueId"] = 12010835,
            ["FacialId"] = {
                [1] = "210004:None",
                },
            ["GUID"] = "1E115F9E",
            ["LookAt"] = {
                [1] = "210004:n(100001)",
                [2] = "100001:n(210004)",
                [3] = "200002:n(100001)",
                },
            ["SpeakNpcId"] = 210004,
            ["TalkActionId"] = {
                [1] = "210004:Explain01L_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120108/1E115F9E",
            },
        [12010901] = {
            ["Camera"] = "276.747314,112.712646,37.357422,0.00115,11.20263,-175.58313,25.0,199.450333,false,Manual,4.0",
            ["Content"] = "让白掂量掂量……哇，沉甸甸的钱包，这么多！止流老板太大气了！",
            ["ContentFR"] = "Laisse-moi voir ça... Oho ! C’est lourd ! Patronne Zhiliu, tu ne lésines vraiment pas !",
            ["DialogueId"] = 12010901,
            ["DialoguePanelType"] = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_Chapter_FullMoneyBag.T_Guide_Chapter_FullMoneyBag'}",
            ["GUID"] = "1E116A72",
            ["LookAt"] = {
                [1] = "210004:n(200002)",
                [2] = "100001:n(200002)",
                [3] = "200002:n(200002)",
                },
            ["NextDialogue"] = 12010902,
            ["Scripts"] = "PlayAnimation{_delay{0},ActorId{200002},AnimationId{\"Please01_Loop\"},Duration{1}},",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120109/1E116A72",
            },
        [12010902] = {
            ["Camera"] = "276.747314,112.712646,37.357422,0.00115,11.20263,-175.58313,25.0,199.450333,false,Manual,4.0",
            ["Content"] = "只是些小钱罢了。你们放心支配，不必拘谨。",
            ["ContentFR"] = "Ce n’est qu’une broutille. Servez-vous sans vous gêner.",
            ["DialogueId"] = 12010902,
            ["FinalCamera"] = "276.747314,112.712646,37.357422,0.001156,11.002628,-173.182861,25.0,410.377594,false,Manual,4.0",
            ["GUID"] = "1E116A9C",
