            },
        [12010903] = {
            ["Camera"] = "117.907089,99.72242,100.063477,0.001367,9.598478,-161.603653,50.000008,218.943039,false,Manual,4.0",
            ["Content"] = "采摘烛阴鳞需要用到<W>某种特制的工具</>，我先前托一些……道上的朋友准备了。",
            ["ContentFR"] = "Pour extraire les Écailles, il te faudra un outil spécial. J’ai demandé à certains... contacts de s’en charger.",
            ["DialogueId"] = 12010903,
            ["GUID"] = "1E116AC6",
