        [12010904] = {
            ["Camera"] = "-91.798035,-58.921486,145.460938,0.001206,-6.398227,74.011063,35.0,283.8638,false,Manual,4.0",
            ["Content"] = "但由于玄色狴犴肆虐，通讯断绝，至今还未送来。可能需要你亲自去取。",
            ["ContentFR"] = "Mais les communications ont été coupées par les Bi’an obscurs. Il ne t’est pas encore parvenu. Tu devras aller le récupérer toi-même.",
            ["DialogueId"] = 12010904,
            ["FacialId"] = {
                [1] = "100001:Doubt01",
                },
            ["GUID"] = "1E116AC7",
