            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120110/1E117ADA",
            },
        [12011002] = {
            ["Content"] = "白还记得和小仆从第一次探险，也是下洞窟，仿佛就像昨天刚刚发生一样！",
            ["ContentFR"] = "Tu te souviens, petit larbin ? Notre toute première exploration, c’était aussi dans une grotte... J’ai l’impression que c’était hier !",
            ["DialogueId"] = 12011002,
            ["Duration"] = 4,
            ["GUID"] = "1E117B04",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 12011003,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120110/1E117B04",
            },
        [12011003] = {
            ["Content"] = "谁想到转眼间，我们就来到这么远的地方，肩负这么激动人心的大使命——",
            ["ContentFR"] = "Et dire qu’en un clin d’œil, nous voilà si loin de chez nous, investis d’une mission aussi palpitante—",
