            ["NextDialogue"] = 12011004,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120110/1E117B2E",
            },
        [12011004] = {
            ["Content"] = "……嗯。那次遇到了奥特赛德，敲了他一顿竹杠。赛琪……也还在。",
            ["ContentFR"] = "... Oui. On y avait rencontré l’Étranger, et on lui avait soutiré pas mal de choses. Et Psyche... était encore avec nous.",
