            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 12011005,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120110/1E117B58",
            },
        [12011005] = {
            ["Content"] = "白、白说错话了……",
            ["ContentFR"] = "J-Je... j’ai dit quelque chose qu’il ne fallait pas...",
