            ["VoiceName"] = "voice/$Locale$/story/1201/120110/1E117B82",
            },
        [12011006] = {
            ["Content"] = "没关系。等我们回去，再到泪湖边去，把华胥的见闻说给她听吧。",
            ["ContentFR"] = "Ce n’est rien. Quand nous rentrerons, nous irons au Lac du Deuil lui raconter ce que nous avons vu à Huaxu.",
