            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E118B42",
            },
        [12011102] = {
            ["Content"] = "看，小仆从！这里黑布隆冬的，说话还会有回音耶。你会怕黑吗？",
            ["ContentFR"] = "Regarde, petit larbin ! Il fait tout noir ici, et nos voix résonnent partout ! Tu n’as pas peur du noir ?",
