        [12011414] = {
            ["Camera"] = "15.423389,62.95097,58.172363,0.000279,14.786286,-172.234375,35.000011,215.125885,false,Manual,6.0",
            ["Content"] = "黑市、谈生意？两位若非要与鸡鸣狗盗之辈为伍，我也无话可说。",
            ["ContentFR"] = "Le marché noir... des affaires ? Si vous choisissez de frayer avec des voleurs et des vauriens, je n’ai rien à ajouter.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12011414,
            ["FacialId"] = {
                [1] = "210007:Angry01",
                },
            ["GUID"] = "1E11BE9C",
            ["LookAt"] = {
                [1] = "210007:n(210007)",
                [2] = "100001:n(210007)",
                [3] = "200002:n(210007)",
                },
            ["NextDialogue"] = 12011415,
            ["SpeakNpcId"] = 210007,
            ["SpeakNpcName"] = "UI_Npc_Name_Yingtianwei",
            ["TalkActionId"] = {
                [1] = "210007:Talk03_Start",
                [2] = "200002:Confident_End",
