            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E11BE9C",
            },
        [12011415] = {
            ["Camera"] = "-20.366999,-42.464127,13.334961,0.000288,25.588646,77.37146,35.000011,257.516388,false,Manual,14.0",
            ["Content"] = "怎、怎么办，小仆从？！我们好像被他误解了……",
            ["ContentFR"] = "M-Mince... petit larbin, il a tout compris de travers...",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12011415,
            ["FacialId"] = {
                [1] = "200002:Shock02",
                },
            ["GUID"] = "1E11BEC6",
            ["LookAt"] = {
                [1] = "100001:n(200002)",
                [2] = "200002:n(100001)",
                },
            ["NextDialogue"] = 12011416,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Shock03_Start",
                [2] = "100001:Explain01L_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E11BEC6",
            },
        [12011416] = {
            ["Content"] = "事情不是你想的那样。我们受止流掌柜雇佣，为了解决玄色狴犴肆虐的问题，需要去黑市取一样工具。",
            ["ContentFR"] = "Ce n’est pas ce que tu crois. Nous avons été engagés par la Patronne Zhiliu pour résoudre la crise des Bi’an obscurs. Nous devons récupérer un outil au marché noir, rien de plus.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12011416,
            ["FacialId"] = {
                [1] = "100001:Doubt01",
                },
            ["GUID"] = "1E11BEF0",
            ["LookAt"] = {
                [1] = "210007:n(100001)",
                [2] = "100001:n(210007)",
                [3] = "200002:n(210007)",
                },
            ["NextDialogue"] = 12011417,
            ["Scripts"] = "CameraMoveTo{_delay{1},TargetPosition{\"65.418396,174.380295,125.57373,0.000325,-3.813841,-158.644958,35.000011,319.544312,false,Manual,6.0\"},duration{0}},",
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E11BEF0",
            },
        [12011417] = {
            ["Camera"] = "-74.738007,65.379562,128.82251,0.000274,-25.813593,17.363806,35.000011,115.267303,false,Manual,6.0",
            ["Content"] = "就是，才不是去做什么偷鸡摸狗的事情呢！",
            ["ContentFR"] = "Voilà ! On n’est pas là pour faire des coups tordus !",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12011417,
            ["FacialId"] = {
                [1] = "200002:Angry01",
                },
            ["GUID"] = "1E11BF1A",
            ["NextDialogue"] = 12011418,
            ["Scripts"] = "PlayAnimation{_delay{2},ActorId{200002},AnimationId{\"Explain02_Start\"},Duration{1}},",
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Shock03_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E11BF1A",
            },
        [12011418] = {
            ["Camera"] = "-35.568024,20.937334,182.430664,0.000227,-24.613787,173.365738,35.000011,196.696289,false,Manual,6.0",
            ["Content"] = "……抱歉。是我武断了。",
            ["ContentFR"] = "... Je vous présente mes excuses. J’ai tiré des conclusions hâtives.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12011418,
            ["FacialId"] = {
                [1] = "210007:Sad01",
                },
            ["GUID"] = "1E11BF44",
            ["LookAt"] = {
                [1] = "210007:n(210007)",
                },
            ["NextDialogue"] = 12011419,
            ["SpeakNpcId"] = 210007,
            ["SpeakNpcName"] = "UI_Npc_Name_Yingtianwei",
            ["TalkActionId"] = {
                [1] = "210007:Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E11BF44",
            },
        [12011419] = {
            ["Content"] = "话虽如此，黑市之人鱼龙混杂，你们需当心甄别，莫被欺瞒利用了。",
            ["ContentFR"] = "Cela dit, le marché noir regorge de gens aux intentions troubles. Restez vigilants, et ne vous laissez pas tromper.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12011419,
            ["FacialId"] = {
                [1] = "210007:None",
                },
            ["GUID"] = "1E11BF6E",
            ["NextDialogue"] = 12011420,
            ["SpeakNpcId"] = 210007,
            ["SpeakNpcName"] = "UI_Npc_Name_Yingtianwei",
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E11BF6E",
            },
        [12011420] = {
            ["Camera"] = "189.114975,196.35614,114.457275,0.000178,-3.606934,-159.432861,25.000006,417.040405,false,Manual,22.0",
            ["Content"] = "此地不安全，让我护送你们过去吧。",
            ["ContentFR"] = "Cet endroit est dangereux. Je vais vous escorter jusqu’à la sortie.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12011420,
            ["GUID"] = "1E11BF98",
            ["Scripts"] = "PlayAnimation{_delay{0},ActorId{200002},AnimationId{\"Explain02_End\"},Duration{1}},",
            ["SpeakNpcId"] = 210007,
            ["SpeakNpcName"] = "UI_Npc_Name_Yingtianwei",
            ["TalkActionId"] = {
                [1] = "210007:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E11BF98",
            },
        [12011501] = {
            ["Content"] = "应天尉就是华胥的卫戍部队吧！你们有工资拿吗，待遇怎么样呀？",
            ["ContentFR"] = "Les Magistrats de Yingtian, c’est un peu les Veilleurs de Huaxu, non ? Dites... vous êtes payés au moins ? Les avantages sont bons ?",
            ["DialogueId"] = 12011501,
            ["Duration"] = 3,
            ["GUID"] = "1E11CCE2",
            ["GuideFacialId"] = "Confident",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 12011502,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120115/1E11CCE2",
            },
        [12011502] = {
            ["Content"] = "……",
            ["ContentFR"] = "...",
            ["DialogueId"] = 12011502,
            ["Duration"] = 1,
            ["GUID"] = "1E11CD0C",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 12011503,
            ["SpeakNpcId"] = 210007,
            ["SpeakNpcName"] = "UI_Npc_Name_Yingtianwei",
            ["VoiceName"] = "voice/$Locale$/story/1201/120115/1E11CD0C",
            },
        [12011503] = {
            ["Content"] = "好啦好啦。白知道了，白不问这些了。",
            ["ContentFR"] = "Bon, bon... d’accord, je ne pose plus de questions.",
            ["DialogueId"] = 12011503,
            ["Duration"] = 2,
            ["GUID"] = "1E11CD36",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 12011504,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120115/1E11CD36",
            },
        [12011504] = {
            ["Content"] = "我为应天尉，只愿济苍生，安黎元，并非为那些身外俗物。",
            ["ContentFR"] = "En tant que Magistrat de Yingtian, je n’agis ni pour la richesse ni pour la récompense. Mon seul vœu est de protéger le peuple et de préserver l’ordre.",
            ["DialogueId"] = 12011504,
            ["Duration"] = 2,
            ["GUID"] = "1E11CD60",
            ["GuideFacialId"] = "Afraid",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 12011505,
            ["SpeakNpcId"] = 210007,
            ["SpeakNpcName"] = "UI_Npc_Name_Yingtianwei",
            ["VoiceName"] = "voice/$Locale$/story/1201/120115/1E11CD60",
            },
        [12011505] = {
            ["Content"] = "……小仆从你听，就是不发工资的意思咯？比帝国还抠门！",
            ["ContentFR"] = "... Tu entends, petit larbin ? Ça veut dire qu’ils ne sont même pas payés. Encore plus radins que l’Empire...",
            ["DialogueId"] = 12011505,
            ["Duration"] = 2,
            ["GUID"] = "1E11CD8A",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120115/1E11CD8A",
            },
        [12011601] = {
            ["Content"] = "前方恐有玄色狴犴蛰伏，由我开路。请两位紧随我身后。",
            ["ContentFR"] = "Des Bi’an obscurs pourraient être embusqués plus loin. Je prendrai la tête. Restez bien derrière moi.",
            ["DialogueId"] = 12011601,
            ["Duration"] = 3,
            ["GUID"] = "1E11DD4A",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 210007,
            ["SpeakNpcName"] = "UI_Npc_Name_Yingtianwei",
            ["VoiceName"] = "voice/$Locale$/story/1201/120116/1E11DD4A",
            },
