            },
        [12011707] = {
            ["Content"] = "那、那个，小仆从，我觉得……",
            ["ContentFR"] = "A-Alors... petit larbin, je me disais...",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12011707,
            ["FacialId"] = {
