            ["VoiceName"] = "voice/$Locale$/story/1201/120121/1E123078",
            },
        [12012109] = {
            ["Content"] = "哎哟喂，是我有眼不识泰山了。不知两位是哪路人马，有这兴致过来。莫非是——钓鱼执法？！",
            ["ContentFR"] = "Oh là... j’ai mal jugé la situation. Vous roulez pour qui, au juste ? Dites-moi pas que c’est un coup monté...",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12012109,
