            },
        [12012111] = {
            ["Camera"] = "30.108398,-132.445312,151.695312,0.000212,-8.401153,95.996559,40.000023,452.333679,false,Manual,3.746801",
            ["Content"] = "您误会了。我们是百年春止流掌柜的朋友，受托来这里办事。",
            ["ContentFR"] = "Vous vous méprenez. Nous sommes des proches de la Patronne Zhiliu d’Éternel Printemps. Elle nous a chargés d’une affaire.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12012111,
            ["GUID"] = "1E1230F6",
            ["LookAt"] = {
