        [12012114] = {
            ["Camera"] = "-144.614258,249.075195,179.435547,0.000213,-26.201075,8.196909,40.000011,243.196228,false,Manual,3.746801",
            ["Content"] = "怎、怎么办，小仆从？感觉今天做什么都不顺利，这就是华胥俗称的“点背”嘛！",
            ["ContentFR"] = "N-Non mais... petit larbin, on dirait que rien ne marche aujourd’hui... C’est ça, la « poisse » dont parlent les gens de Huaxu ?!",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12012114,
