            ["TalkActionId"] = {
                [1] = "210010:Explain01_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120135/1E1316A6",
            },
        [12013512] = {
            ["Content"] = "……",
            ["ContentFR"] = "...",
            ["DialogueId"] = 12013512,
            ["GUID"] = "1E1316D0",
            ["NextDialogue"] = 12013513,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120135/1E1316D0",
            },
        [12013513] = {
            ["Camera"] = "779.264404,211.306061,366.683594,0.000056,-11.199543,179.402878,50.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "好了好了。俗话说得好，无恒久之友，亦无恒久之敌。这天下熙熙，皆为利来利往。只有利益永流转呀——",
            ["ContentFR"] = "Très bien, très bien. Disons-le autrement. Il n’existe ni ennemis éternels, ni alliés éternels — seuls les intérêts demeurent. Dans ce monde en perpétuel tumulte, tout converge vers le profit.",
            ["DialogueId"] = 12013513,
            ["GUID"] = "1E1316FA",
            ["LookAt"] = {
                [1] = "100001:n(210010)",
                [2] = "200002:n(210010)",
                },
            ["NextDialogue"] = 12013514,
            ["SpeakNpcId"] = 210010,
            ["TalkActionId"] = {
                [1] = "210010:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120135/1E1316FA",
            },
        [12013514] = {
            ["Camera"] = "-70.775307,-50.397655,304.739258,0.000104,-11.399626,52.60202,35.0,383.266479,false,DoNotOverride,2.8",
            ["Content"] = "听你话里的意思，你能拿出让我心动的报酬？",
            ["ContentFR"] = "Autrement dit... vous avez une récompense capable de m’intéresser ?",
            ["DialogueId"] = 12013514,
            ["FacialId"] = {
                [1] = "100001:Doubt01",
                [2] = "210010:Cin_Smile01",
                },
            ["GUID"] = "1E131724",
            ["NextDialogue"] = 12013515,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:ConfidentLRToTalk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120135/1E131724",
            },
        [12013515] = {
            ["Camera"] = "236.166168,300.864075,264.609375,0.000073,0.600435,-149.201889,35.000008,370.433502,false,DoNotOverride,2.8",
            ["Content"] = "钱自不用说。我们家老板一向出手慷慨。",
            ["ContentFR"] = "L’argent va de soi. Mon patron est réputé pour sa générosité.",
            ["DialogueId"] = 12013515,
            ["FacialId"] = {
                [1] = "200002:Curious",
                },
            ["GUID"] = "1E13174E",
            ["NextDialogue"] = 12013516,
            ["SpeakNpcId"] = 210010,
            ["TalkActionId"] = {
                [1] = "100001:Talk01_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120135/1E13174E",
            },
        [12013516] = {
            ["Content"] = "还有一项报酬，想必是合您心意的……",
            ["ContentFR"] = "Mais il existe un autre avantage... qui devrait davantage retenir votre attention.",
            ["DialogueId"] = 12013516,
            ["GUID"] = "1E131778",
            ["NextDialogue"] = 12013517,
            ["SpeakNpcId"] = 210010,
            ["VoiceName"] = "voice/$Locale$/story/1201/120135/1E131778",
            },
        [12013517] = {
            ["Camera"] = "-70.775307,-50.397655,304.739258,0.000104,-11.399626,52.60202,35.0,383.266479,false,DoNotOverride,2.8",
            ["Content"] = "说来听听。",
            ["ContentFR"] = "Je vous écoute.",
            ["DialogueId"] = 12013517,
            ["FacialId"] = {
                [1] = "100001:Think01",
                [2] = "200002:Smile01",
                },
            ["GUID"] = "1E1317A2",
            ["NextDialogue"] = 12013518,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120135/1E1317A2",
            },
        [12013518] = {
            ["Content"] = "您或许不知，我们家老板的生意足迹遍布世界各地，与海伯利亚帝国也有盘根错节的联系……您可曾听说过格林威治考古协会？",
            ["ContentFR"] = "Vous l’ignorez peut-être, mais les affaires de mon patron s’étendent aux quatre coins du monde — jusque dans l’Empire Hyperboréen. Avez-vous déjà entendu parler de la Société archéologique de Gréniche ?",
            ["DialogueId"] = 12013518,
            ["GUID"] = "1E1317CC",
            ["NextDialogue"] = 12013519,
            ["RelatedWikiId"] = {
                [1] = 406005,
                },
            ["SpeakNpcId"] = 210010,
            ["TalkActionId"] = {
                [1] = "200002:Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120135/1E1317CC",
            },
        [12013519] = {
            ["Camera"] = "-105.901047,-11.516113,305.875977,0.000081,-16.399591,37.201481,50.0,374.245361,false,DoNotOverride,2.8",
            ["Content"] = "哇，我听卡米拉讲过！那是一个号称要让古迹重见天日的组织，很有名的！",
            ["ContentFR"] = "C’est une organisation célèbre, dédiée à la redécouverte des vestiges anciens !",
            ["DialogueId"] = 12013519,
            ["FacialId"] = {
                [1] = "200002:Shock01",
                },
            ["GUID"] = "1E1317F6",
            ["NextDialogue"] = 12013520,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Shock03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120135/1E1317F6",
            },
        [12013520] = {
            ["Camera"] = "236.166168,300.864075,264.609375,0.000073,0.600435,-149.201889,35.000008,370.433502,false,DoNotOverride,2.8",
            ["Content"] = "呵呵，我家老板就是它背后的投资人之一。",
            ["ContentFR"] = "Hé hé... Mon patron en est l’un des principaux investisseurs.",
            ["DialogueId"] = 12013520,
            ["FacialId"] = {
                [1] = "210010:Cin_Happy01",
                },
            ["GUID"] = "1E131820",
            ["NextDialogue"] = 12013521,
            ["RelatedWikiId"] = {
                [1] = 203005,
                },
            ["SpeakNpcId"] = 210010,
            ["TalkActionId"] = {
                [1] = "200002:Shock03_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120135/1E131820",
            },
        [12013521] = {
            ["Camera"] = "-105.901047,-11.516113,305.875977,0.000081,-16.399591,37.201481,50.0,374.245361,false,DoNotOverride,2.8",
            ["Content"] = "哎？！传闻中从不露面的格林威治考古协会幕后金主……竟然就藏在华胥！",
            ["ContentFR"] = "Quoi ?! Le mystérieux mécène de la Société archéologique de Gréniche... serait caché ici, à Huaxu ?!",
            ["DialogueId"] = 12013521,
            ["FacialId"] = {
                [1] = "200002:Shock02",
                },
            ["FinalCamera"] = "-105.901047,-11.516113,305.875977,0.000081,-16.399591,37.201481,60,374.245361,false,DoNotOverride,2.8",
            ["GUID"] = "1E13184A",
            ["NextDialogue"] = 12013522,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Excited01_Start",
                },
            ["ToFinalCameraBlendTime"] = 3,
            ["VoiceName"] = "voice/$Locale$/story/1201/120135/1E13184A",
            },
        [12013522] = {
            ["Camera"] = "49.970024,127.262115,278.185547,0.000111,-6.199612,60.402637,35.0,190.711807,false,DoNotOverride,2.8",
            ["Content"] = "{nickname}，您在找某位失散的朋友，对吧？",
            ["ContentFR"] = "{nickname}... vous êtes à la recherche d’une personne qui vous est chère, n’est-ce pas ?",
            ["DialogueId"] = 12013522,
            ["GUID"] = "1E131874",
