            },
        [12013523] = {
            ["Camera"] = "34.974609,-135.861816,425.904297,0.000123,-26.199484,77.799515,35.0,491.753998,false,DoNotOverride,2.8",
            ["Content"] = "……你怎么知道的？",
            ["ContentFR"] = "... Comment le savez-vous ?",
            ["DialogueId"] = 12013523,
            ["FacialId"] = {
                [1] = "100001:Shock02",
                },
            ["GUID"] = "1E13189E",
            ["NextDialogue"] = 12013524,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Shock04_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120135/1E13189E",
            },
        [12013524] = {
            ["Camera"] = "779.264404,211.306061,366.683594,0.000056,-11.199543,179.402878,50.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我如何知道这件事不要紧。要紧的是，考古协会提供的情报和人脉，在日后某一天说不定就能成为您达成心愿的助力。",
            ["ContentFR"] = "Peu importe comment. Ce qui compte, c’est que les réseaux et les informations de la Société archéologique pourraient, un jour, vous aider à accomplir ce souhait.",
            ["DialogueId"] = 12013524,
            ["GUID"] = "1E1318C8",
            ["NextDialogue"] = 120135070,
            ["SpeakNpcId"] = 210010,
            ["TalkActionId"] = {
                [1] = "100001:Shock04_End",
                [2] = "210010:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120135/1E1318C8",
            },
        [12013526] = {
            ["Camera"] = "779.264404,211.306061,366.683594,0.000056,-11.199543,179.402878,50.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "人们总是对我们黑市中人有些偏见，冯某十分理解。",
            ["ContentFR"] = "Je comprends vos réserves. Les gens du marché noir ont mauvaise réputation.",
            ["DialogueId"] = 12013526,
            ["FacialId"] = {
                [1] = "100001:Doubt01",
                [2] = "210010:CM_Idle",
                },
            ["GUID"] = "1E13191C",
            ["NextDialogue"] = 12013528,
            ["SpeakNpcId"] = 210010,
            ["TalkActionId"] = {
                [1] = "210010:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120135/1E13191C",
            },
        [12013528] = {
            ["Content"] = "但就算是我们，也会有一颗保卫家园的拳拳之心，偶尔想做些为民除害的好事！",
            ["ContentFR"] = "Mais même nous, il nous arrive de vouloir protéger notre foyer... et d’éliminer certaines menaces.",
            ["DialogueId"] = 12013528,
            ["GUID"] = "1E131970",
            ["NextDialogue"] = 12013529,
            ["SpeakNpcId"] = 210010,
            ["VoiceName"] = "voice/$Locale$/story/1201/120135/1E131970",
            },
        [12013529] = {
            ["Camera"] = "-70.775307,-50.397655,304.739258,0.000104,-11.399626,52.60202,35.0,383.266479,false,DoNotOverride,2.8",
            ["Content"] = "……听起来更可疑了。",
            ["ContentFR"] = "... Vous rendez ça encore plus suspect.",
            ["DialogueId"] = 12013529,
            ["FacialId"] = {
                [1] = "100001:Think01",
                [2] = "200002:Doubt01",
                },
            ["GUID"] = "1E13199A",
            ["NextDialogue"] = 12013530,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120135/1E13199A",
            },
        [12013530] = {
            ["Camera"] = "236.166168,300.864075,264.609375,0.000073,0.600435,-149.201889,35.000008,370.433502,false,DoNotOverride,2.8",
            ["Content"] = "况且，这行动是止流掌柜嘱托给我们老板的，也是化解烛阴之灾布局的一子呢。",
            ["ContentFR"] = "À vrai dire, cette opération répond à une demande directe de la Patronne Zhiliu. Elle fait partie de sa stratégie pour résoudre le Fléau de Zhuyin.",
            ["DialogueId"] = 12013530,
            ["GUID"] = "1E1319C4",
            ["NextDialogue"] = 12013531,
            ["SpeakNpcId"] = 210010,
            ["VoiceName"] = "voice/$Locale$/story/1201/120135/1E1319C4",
            },
        [12013531] = {
            ["Camera"] = "-70.775307,-50.397655,304.739258,0.000104,-11.399626,52.60202,35.0,383.266479,false,DoNotOverride,2.8",
            ["Content"] = "……止流的委托？好吧。“猎物”是什么？",
            ["ContentFR"] = "... Une requête de Zhiliu ? Très bien. Alors... quelle est la « proie » ?",
            ["DialogueId"] = 12013531,
            ["FacialId"] = {
                [1] = "100001:Doubt01",
                },
            ["GUID"] = "1E1319EE",
            ["NextDialogue"] = 12013532,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120135/1E1319EE",
            },
        [12013532] = {
            ["Content"] = "这个冯某暂时无法透露，您可以视为玄色狴犴的同类。",
            ["ContentFR"] = "Je ne peux pas encore vous le révéler. Disons simplement qu’elle est de la même nature que les Bi’an obscurs.",
            ["DialogueId"] = 12013532,
            ["FacialId"] = {
                [1] = "210010:Cin_Smile01",
                },
            ["GUID"] = "1E131A18",
            ["NextDialogue"] = 12013533,
            ["SpeakNpcId"] = 210010,
            ["VoiceName"] = "voice/$Locale$/story/1201/120135/1E131A18",
            },
        [12013533] = {
            ["Content"] = "等您看到了再决定也不迟。毕竟，您随时有退出的权利。",
            ["ContentFR"] = "Vous pourrez toujours vous retirer après l’avoir vue de vos propres yeux. Rien ne vous oblige à continuer.",
            ["DialogueId"] = 12013533,
            ["GUID"] = "1E131A42",
            ["NextDialogue"] = 120135070,
            ["SpeakNpcId"] = 210010,
            ["TalkActionId"] = {
                [1] = "100001:Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120135/1E131A42",
            },
        [12013534] = {
            ["Camera"] = "-70.775307,-50.397655,304.739258,0.000104,-11.399626,52.60202,35.0,383.266479,false,DoNotOverride,2.8",
            ["Content"] = "……我先跟你们去看看吧。",
            ["ContentFR"] = "... Très bien. Je vais vous suivre et voir de quoi il retourne.",
            ["DialogueId"] = 12013534,
            ["GUID"] = "1E131A6C",
            ["NextDialogue"] = 12013535,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Talk01_Start",
                [2] = "210010:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120135/1E131A6C",
            },
        [12013535] = {
            ["Camera"] = "779.264404,211.306061,366.683594,0.000056,-11.199543,179.402878,50.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "这就好，不枉冯某费这一番口舌！",
            ["ContentFR"] = "Excellente décision ! Je n’aurai pas parlé en vain.",
            ["DialogueId"] = 12013535,
            ["FacialId"] = {
                [1] = "210010:Cin_Happy01",
                },
            ["GUID"] = "1E131A96",
            ["NextDialogue"] = 12013536,
            ["SpeakNpcId"] = 210010,
            ["TalkActionId"] = {
                [1] = "100001:Talk01_End",
                [2] = "210010:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120135/1E131A96",
            },
        [12013536] = {
            ["Content"] = "待您有空时，去沉船内找我们老板就好。等您来了，万事俱备，我们再开始！",
            ["ContentFR"] = "Lorsque vous serez prêt, rendez-vous à l’intérieur de l’épave. Mon patron vous y attendra — et alors, tout sera en place.",
            ["DialogueId"] = 12013536,
            ["GUID"] = "1E131AC0",
            ["NextDialogue"] = 12013537,
            ["SpeakNpcId"] = 210010,
            ["TalkActionId"] = {
                [1] = "210010:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120135/1E131AC0",
            },
        [12013537] = {
            ["Content"] = "那冯某就先告退啦。",
            ["ContentFR"] = "Sur ce, je vous laisse.",
            ["DialogueId"] = 12013537,
            ["FacialId"] = {
                [1] = "210010:Cin_Smile01",
                },
            ["GUID"] = "1E131AEA",
            ["SpeakNpcId"] = 210010,
            ["TalkActionId"] = {
                [1] = "210010:Salute_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120135/1E131AEA",
            },
        [12013601] = {
            ["Camera"] = "-130.490814,92.101395,310.104492,0.000114,-12.999571,27.802591,35.000008,190.711807,false,DoNotOverride,2.8",
            ["Content"] = "希望他们这次不要再有什么坏心思……",
            ["ContentFR"] = "Espérons qu’ils n’aient pas encore de mauvaises intentions...",
            ["DialogueId"] = 12013601,
            ["Duration"] = 3,
            ["FacialId"] = {
                [1] = "100001:Think01",
                },
            ["GUID"] = "1E13256A",
            ["LookAt"] = {
                [1] = "200002:n(100001)",
                },
            ["NextDialogue"] = 12013602,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "100001:Think_Start",
                [2] = "200002:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120136/1E13256A",
            },
        [12013602] = {
            ["Content"] = "拜访扶疏还是帮助虬老板……先去哪里呢？小仆从，你决定吧！",
            ["ContentFR"] = "Alors ? Aller voir Fushu... ou aider Maître Qiu ? À toi de décider, petit larbin !",
            ["DialogueId"] = 12013602,
            ["Duration"] = 3,
            ["GUID"] = "1E132594",
            ["LookAt"] = {
                [1] = "100001:n(200002)",
                },
            ["NextOptions"] = {
                [1] = 120136021,
                [2] = 120136022,
                },
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120136/1E132594",
            },
        [12013701] = {
            ["Content"] = "杏林环绕中的医馆……看来就是这幢建筑了。",
            ["ContentFR"] = "Un pavillon médical entouré d’un bosquet d’abricotiers... Cela doit être ici.",
            ["DialogueId"] = 12013701,
            ["Duration"] = 3,
            ["GUID"] = "1E1335D2",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120137/1E1335D2",
            },
        [12013702] = {
            ["Content"] = "不知道扶疏和那个被狴犴打伤的女孩子有没有好些。",
            ["ContentFR"] = "Je me demande comment vont Fushu et la jeune femme blessée par le Bi’an...",
            ["DialogueId"] = 12013702,
            ["Duration"] = 3,
            ["GUID"] = "1E1335FC",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120137/1E1335FC",
            },
        [12013801] = {
            ["Camera"] = "-231.900192,-180.60968,20.349609,0.000026,10.599401,43.608379,35.000008,100000.0,false,DoNotOverride,2.8",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "扶疏——我们来找你玩啦！",
            ["ContentFR"] = "Fushu ! On est {性别:venus|venues} te voir !",
            ["DialogueId"] = 12013801,
            ["FinalCamera"] = "-261.574127,-208.011398,11.34375,0.000024,12.799425,42.608479,35.000008,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "1E13463A",
            ["LookAt"] = {
