            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/story/1201/120138/1E13463A",
            },
        [12013802] = {
            ["Camera"] = "-261.574127,-208.011398,11.34375,0.000024,12.799425,42.608479,35.000008,100000.0,false,DoNotOverride,2.8",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "好像……没有人在家？",
            ["ContentFR"] = "On dirait... qu’il n’y a personne ?",
            ["DialogueId"] = 12013802,
            ["Duration"] = 1,
            ["FinalCamera"] = "-211.680801,-147.53064,37.373047,0.000018,11.199153,51.210159,35.000011,100000.0,false,DoNotOverride,2.8",
