PlayAnimation{_delay{1.1},ActorId{100001},AnimationId{\"Talk03_Start\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 100001,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/story/1201/120138/1E134664",
            },
        [12013803] = {
            ["Camera"] = "-112.108292,-52.482899,103.758789,0.000038,0.798579,-177.772751,25.000002,100000.0,false,DoNotOverride,2.8",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "小仆从，我们先进去看看吧。",
            ["ContentFR"] = "Allez, petit larbin, entrons jeter un coup d’œil !",
            ["DialogueId"] = 12013803,
            ["FinalCamera"] = "-190.457108,-94.858833,111.126953,0.000037,-12.000703,-148.576523,25.000002,100000.0,false,DoNotOverride,2.8",
