                },
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/story/1201/120138/1E13468E",
            },
        [12013901] = {
            ["Content"] = "这里也太整洁了吧！空空荡荡的……",
            ["ContentFR"] = "C’est... incroyablement propre ! Et complètement vide...",
            ["DialogueId"] = 12013901,
            ["Duration"] = 3,
            ["GUID"] = "1E1356A2",
            ["NextDialogue"] = 12013902,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120139/1E1356A2",
            },
        [12013902] = {
            ["Content"] = "就好像……完全没有人居住一样。",
            ["ContentFR"] = "On dirait presque... que personne n’a jamais vécu ici.",
            ["DialogueId"] = 12013902,
            ["Duration"] = 2,
            ["GUID"] = "1E1356CC",
            ["NextDialogue"] = 12013903,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120139/1E1356CC",
            },
        [12013903] = {
            ["Content"] = "小仆从你你你不要随便讲鬼故事——扶疏她的确住在这里，没错吧……？",
            ["ContentFR"] = "Hé ! N’invente pas d’histoires de fantômes ! Fushu habite bien ici... pas vrai ?",
            ["DialogueId"] = 12013903,
            ["Duration"] = 3,
            ["GUID"] = "1E1356F6",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120139/1E1356F6",
            },
        [12014001] = {
            ["Camera"] = "428.589844,98.277344,126.54541,0.0,0.0,-179.794739,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "唔……",
            ["ContentFR"] = "Mm...",
            ["DialogueId"] = 12014001,
            ["GUID"] = "1E13670A",
            ["NextDialogue"] = 12014002,
            ["RelatedWikiId"] = {
                [1] = 405013,
                [2] = 203006,
                },
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120140/1E13670A",
            },
        [12014002] = {
            ["Content"] = "{nickname}，是你们来了。",
            ["ContentFR"] = "{nickname}... Snow. Vous êtes venues.",
            ["DialogueId"] = 12014002,
            ["GUID"] = "1E136734",
            ["NextDialogue"] = 12014003,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120140/1E136734",
            },
        [12014003] = {
            ["Camera"] = "-148.077026,-18.083099,128.862305,0.000068,-0.798572,36.407757,40.0,100000.0,false,DoNotOverride,2.8",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "你该不会彻夜照料她，自己没顾得上休息吧？",
            ["ContentFR"] = "Ne me dis pas que tu es restée éveillée toute la nuit sans te reposer...",
            ["DialogueId"] = 12014003,
            ["FacialId"] = {
                [1] = "100001:Unhappy01",
                [2] = "200002:Unhappy01",
                [3] = "210056:Cin_Close01",
                },
            ["FinalCamera"] = "-148.077026,-18.083099,128.862305,0.000068,3.401434,33.608273,40.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "1E13675E",
            ["LookAt"] = {
                [1] = "210013:n(100001)",
                [2] = "100001:n(210013)",
                },
            ["NextDialogue"] = 12014004,
