                },
            ["ToFinalCameraBlendTime"] = 3,
            ["VoiceName"] = "voice/$Locale$/story/1201/120140/1E13675E",
            },
        [12014004] = {
            ["Camera"] = "-32.965408,-8.578339,142.960938,0.000083,-21.59716,-172.189392,35.000011,144.691895,false,Manual,8.0",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "家训有言，祝由应渡尽天下苍生……有什么不妥吗？",
            ["ContentFR"] = "Les préceptes familiaux enseignent que le Zhuyou doit sauver tous les êtres vivants. Y a-t-il là quelque chose de répréhensible ?",
            ["DialogueId"] = 12014004,
            ["FacialId"] = {
                [1] = "210013:Shy",
                },
            ["FinalCamera"] = "-32.965408,-8.578339,142.960938,0.00009,-1.597711,-174.588303,35.000011,144.691895,false,Manual,8.0",
            ["GUID"] = "1E136788",
            ["NextDialogue"] = 12014005,
            ["Scripts"] = "PlayAnimation{_delay{5.1},ActorId{210013},AnimationId{\"TilteHead_Start\"},Duration{1}}\
",
            ["SpeakNpcId"] = 210013,
            ["TalkActionId"] = {
                [1] = "210013:Explain02_Start",
                [2] = "200002:Talk03_End",
                },
            ["ToFinalCameraBlendTime"] = 4,
            ["VoiceName"] = "voice/$Locale$/story/1201/120140/1E136788",
            },
        [12014005] = {
            ["Camera"] = "-139.686951,3.986969,127.750977,0.000168,-21.198324,-6.583653,40.000011,135.565475,false,Manual,6.0",
            ["Content"] = "当然不对劲啦！再怎么样，也要先保证自己的身体，再考虑别人吧？",
            ["ContentFR"] = "Bien sûr que oui ! Comment soigner les autres si tu t’épuises toi-même ?!",
            ["DialogueId"] = 12014005,
            ["FinalCamera"] = "-139.686951,3.986969,131.131836,0.000168,-21.198324,-6.583653,40.000011,130.4021,false,Manual,6.0",
            ["GUID"] = "1E1367B2",
            ["LookAt"] = {
                [1] = "210013:n(200002)",
                [2] = "200002:n(210013)",
                },
            ["NextDialogue"] = 12014006,
            ["Scripts"] = "PlayAnimation{ActorId{210013},AnimationId{\"TilteHead_End\"},Duration{1}}\
",
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Confident_Start",
                },
            ["ToFinalCameraBlendTime"] = 0.5,
            ["VoiceName"] = "voice/$Locale$/story/1201/120140/1E1367B2",
            },
        [12014006] = {
            ["Camera"] = "266.129486,-304.112732,99.563477,0.000088,1.401568,140.811783,35.000011,519.066956,false,Manual,6.0",
            ["Content"] = "我能以秘法排解体内浊气，所以无妨……",
            ["ContentFR"] = "Je dispose de techniques secrètes pour expulser les miasmes de mon corps. Il n’y a pas lieu de s’inquiéter...",
            ["DialogueId"] = 12014006,
            ["FinalCamera"] = "250.848297,-322.864258,99.563477,0.000088,1.201567,138.411911,35.000011,523.788696,false,Manual,6.0",
            ["GUID"] = "1E1367DC",
            ["NextDialogue"] = 12014007,
            ["Scripts"] = "PlayAnimation{_delay{3.1},ActorId{210013},AnimationId{\"Explain02_End\"},Duration{1}}",
            ["SpeakNpcId"] = 210013,
            ["TalkActionId"] = {
                [1] = "210013:DisagreeHead",
                },
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/1201/120140/1E1367DC",
            },
        [12014007] = {
            ["Camera"] = "-175.21283,-47.460327,141.867188,0.000072,-20.001566,12.022709,45.000057,176.925766,false,Manual,6.0",
            ["Content"] = "那也不行，哎呀，怎么这么犟。和你真是说不通！",
            ["ContentFR"] = "Mais enfin, non ! Pfff... pourquoi tu es aussi têtue ? C’est impossible de te faire entendre raison !",
            ["DialogueId"] = 12014007,
            ["FacialId"] = {
                [1] = "200002:Doubt01",
                },
            ["FinalCamera"] = "-189.266571,-50.447128,147.098633,0.000072,-20.001566,12.022709,45.000065,190.961273,false,Manual,6.0",
