        [12014008] = {
            ["Camera"] = "-220.412903,-680.490723,295.292969,0.000105,-16.397665,79.819618,30.000002,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "你先前说收了我的竹笛，就答应帮我做一件事，没错吧？",
            ["ContentFR"] = "Tu avais dit qu’en acceptant ma flûte, tu me devais une faveur... n’est-ce pas ?",
            ["DialogueId"] = 12014008,
            ["FinalCamera"] = "-256.274719,-674.050476,295.292969,0.000105,-16.397665,79.819618,30.000002,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "1E136830",
            ["LookAt"] = {
                [1] = "100001:n(100001)",
                },
            ["NextDialogue"] = 12014009,
            ["Scripts"] = "SEQ{\
MoveTo{_delay{1},ActorId{100001},TargetPoint{\"BP_FixSimple_37_nvzhu02\"},MoveSpeed{75},Visibility{\"Show\"}},\
PlayAnimation{ActorId{100001},AnimationId{\"Talk03_Start\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 100001,
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/1201/120140/1E136830",
            },
        [12014009] = {
            ["Content"] = "确然。",
            ["ContentFR"] = "C’est exact.",
            ["DialogueId"] = 12014009,
            ["Duration"] = 1,
            ["GUID"] = "1E13685A",
            ["LookAt"] = {
                [1] = "200002:n(100001)",
