}",
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120140/1E13685A",
            },
        [12014010] = {
            ["Camera"] = "-8.599365,-111.106323,114.814453,0.000091,8.002468,157.225708,40.000011,192.971207,false,Manual,8.0",
            ["Content"] = "那我希望你可以好好照顾自己。",
            ["ContentFR"] = "Alors je te demande ceci : prends soin de toi.",
            ["DialogueId"] = 12014010,
            ["Duration"] = 3,
            ["FacialId"] = {
