                [1] = "210013:n(100001)",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120140/1E1368AE",
            },
        [12014012] = {
            ["Content"] = "我有个相依为命的家人也是这样，她总是不把自己的身体当回事，无论是被欺负了还是受伤了，都装出一副若无其事的样子。但我不喜欢她这样。",
            ["ContentFR"] = "J’ai quelqu’un de très cher... Elle te ressemble beaucoup. Toujours à négliger sa propre santé, quoi qu’il lui arrive. Je n’aime pas la voir ainsi.",
            ["DialogueId"] = 12014012,
            ["FacialId"] = {
                [1] = "100001:Sad03",
                },
            ["GUID"] = "1E1368D8",
            ["LookAt"] = {
                [1] = "100001:n(100001)",
                },
            ["NextDialogue"] = 12014013,
            ["Scripts"] = "PARA{\
