            },
        [12014014] = {
            ["Camera"] = "-195.013611,-319.483887,133.03418,0.000073,-0.997713,80.626976,40.0,272.017151,false,Manual,10.0",
            ["Content"] = "这个世界上，肯定有某个人像我担心她一样担心你。所以，照顾好自己，不要让那个人难过。",
            ["ContentFR"] = "Il existe forcément quelqu’un qui s’inquiète pour toi de la même façon. Alors... ne lui inflige pas cette peine.",
            ["DialogueId"] = 12014014,
            ["Duration"] = 1,
            ["FacialId"] = {
                [1] = "210013:Sad03",
                },
            ["FinalCamera"] = "-208.24704,-317.102356,133.03418,0.000073,-0.397701,79.626984,40.0,257.81076,false,Manual,10.0",
