        [12014029] = {
            ["Camera"] = "-121.7556,4.822418,91.928711,0.000113,-4.796657,-10.953535,35.0,104.130783,false,Manual,8.0",
            ["Content"] = "……话说回来，那个什么什么此界彼界的玄乎地方，是哪儿来着？",
            ["ContentFR"] = "Euh... au fait... Ce lieu entre deux mondes, là... il est où, déjà ?",
            ["DialogueId"] = 12014029,
            ["GUID"] = "1E136BA2",
            ["LookAt"] = {
                [1] = "100001:n(210013)",
