        [12014201] = {
            ["Content"] = "……未想到此处也被这些尘漠影响了。",
            ["ContentFR"] = "... Je ne m’attendais pas à ce que la Poussière-corrompue atteigne même cet endroit.",
            ["DialogueId"] = 12014201,
            ["Duration"] = 3,
            ["GUID"] = "1E1387DA",
            ["NextDialogue"] = 12014202,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120142/1E1387DA",
            },
        [12014202] = {
            ["Content"] = "放心，我有办法解决。",
            ["ContentFR"] = "Ne t’inquiète pas. Je sais comment m’en occuper.",
            ["DialogueId"] = 12014202,
            ["Duration"] = 2,
            ["GUID"] = "1E138804",
            ["NextDialogue"] = 12014203,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120142/1E138804",
            },
        [12014203] = {
            ["Content"] = "哼哼，毕竟现在白和小仆从可是出师的机枢派荣誉学徒！你就看好了！",
            ["ContentFR"] = "Héhé... Après tout, Snow et le petit larbin sont désormais de véritables Apprentis d’honneur de la Secte Jishu ! Regarde bien !",
            ["DialogueId"] = 12014203,
            ["Duration"] = 2,
            ["GUID"] = "1E13882E",
            ["NextDialogue"] = 12014204,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120142/1E13882E",
            },
        [12014204] = {
            ["Content"] = "机枢派……？这个门派式微已久，你们怎与他们产生了交集？",
            ["ContentFR"] = "La Secte Jishu... ? Voilà un nom que l’on n’entend plus depuis bien longtemps. Comment avez-vous croisé leur chemin ?",
            ["DialogueId"] = 12014204,
            ["Duration"] = 2,
            ["GUID"] = "1E138858",
            ["NextDialogue"] = 12014205,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120142/1E138858",
            },
        [12014205] = {
            ["Content"] = "哼哼，这就是小说里常说的奇遇！",
            ["ContentFR"] = "Héhé ! Voilà ce que les romans appellent une \"rencontre du destin\", rien que ça !",
            ["DialogueId"] = 12014205,
            ["Duration"] = 3,
            ["GUID"] = "1E138882",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120142/1E138882",
            },
        [12014301] = {
            ["Camera"] = "428.589844,98.277344,126.54541,0.0,0.0,-179.794739,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "啊，是白色妖怪！",
            ["ContentFR"] = "Ah ! Des monstres blancs !",
            ["DialogueId"] = 12014301,
            ["GUID"] = "1E139842",
            ["NextDialogue"] = 12014302,
            ["RelatedWikiId"] = {
                [1] = 408013,
                [2] = 303012,
                [3] = 203006,
                },
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210016,
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["VoiceName"] = "voice/$Locale$/story/1201/120143/1E139842",
            },
        [12014302] = {
            ["Content"] = "呜、呜哇——谁在说话？幽灵？！救命啊，小仆从！",
            ["ContentFR"] = "Ou— ouah— ! Qui a parlé ?! Un fantôme ?! À l’aide, petit larbin !",
            ["DialogueId"] = 12014302,
            ["GUID"] = "1E13986C",
            ["NextDialogue"] = 12014303,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120143/1E13986C",
            },
        [12014303] = {
            ["Content"] = "无需惊慌，小白。这就是我先前所说的<H>无由生</>。只是未受它们邀请的人看不到它们的身形。",
            ["ContentFR"] = "Inutile de paniquer, Snow. C’est l’un des Wishen dont je t’ai parlé. Ceux qui n’ont pas reçu leur invitation ne peuvent pas voir leur véritable forme.",
            ["DialogueId"] = 12014303,
            ["GUID"] = "1E139896",
            ["NextDialogue"] = 12014304,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120143/1E139896",
            },
        [12014304] = {
            ["Content"] = "畏生，这二位是我的朋友。我们有事拜访长老，可以请你现身，为{性别：他|她}们指明前路吗？",
            ["ContentFR"] = "Wei Shen, ces deux-là sont mes amis. Nous souhaitons rencontrer l’Ainé. Pourrais-tu te montrer et leur indiquer le chemin ?",
            ["DialogueId"] = 12014304,
            ["GUID"] = "1E1398C0",
            ["NextDialogue"] = 12014305,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120143/1E1398C0",
            },
        [12014305] = {
            ["Content"] = "扶疏的朋友？那也是畏生的朋友！",
            ["ContentFR"] = "Les amis de Fushu sont aussi les amis de Wei Shen !",
            ["DialogueId"] = 12014305,
            ["GUID"] = "1E1398EA",
            ["NextDialogue"] = 12014306,
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210016,
            ["VoiceName"] = "voice/$Locale$/story/1201/120143/1E1398EA",
            },
        }
  end },
  { MinKey = 12014306, MaxKey = 12018001, Loader = function()
      return {
        [12014306] = {
            ["Content"] = "哇……这就是无由生吗？小家伙长得圆溜溜的，还挺可爱的！",
            ["ContentFR"] = "Ouah... alors c’est ça, un Wishen ? Il est tout rond... et plutôt mignon !",
            ["DialogueId"] = 12014306,
            ["GUID"] = "1E139914",
            ["NextDialogue"] = 12014307,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120143/1E139914",
            },
        [12014307] = {
            ["Content"] = "你怎不在祠台，跑到外面来了？",
            ["ContentFR"] = "Pourquoi n’étais-tu pas à l’autel ? Que faisais-tu ici ?",
            ["DialogueId"] = 12014307,
            ["GUID"] = "1E13993E",
            ["NextDialogue"] = 12014308,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120143/1E13993E",
            },
        [12014308] = {
            ["Content"] = "灰茫茫的尘漠从地里生出来……灰茫茫的尘漠畔住了畏生的脚！畏生走不动，也跑不动……",
            ["ContentFR"] = "La Poussière-corrompue... elle est sortie de la terre... Elle a coincé les pieds de Wei Shen... Je ne pouvais plus marcher... ni courir...",
            ["DialogueId"] = 12014308,
            ["GUID"] = "1E139968",
            ["NextDialogue"] = 12014309,
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210016,
            ["VoiceName"] = "voice/$Locale$/story/1201/120143/1E139968",
            },
        [12014309] = {
            ["Content"] = "没能在天黑之前回家，阿娘要记挂了……",
            ["ContentFR"] = "Je ne suis pas rentré avant la nuit... Maman doit s’inquiéter...",
            ["DialogueId"] = 12014309,
            ["GUID"] = "1E139992",
            ["NextDialogue"] = 12014310,
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210016,
            ["VoiceName"] = "voice/$Locale$/story/1201/120143/1E139992",
            },
        [12014310] = {
            ["Content"] = "放心吧，我们带你回家。包在白身上！",
            ["ContentFR"] = "Ne t’en fais pas ! On va te ramener chez toi. Laisse ça à Snow !",
            ["DialogueId"] = 12014310,
            ["GUID"] = "1E1399BC",
            ["NextDialogue"] = 12014311,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120143/1E1399BC",
            },
        [12014311] = {
            ["Content"] = "家……畏生的家丢了！哪里都找不见阿娘，畏生没有地方可以去！",
            ["ContentFR"] = "Chez moi... la maison de Wei Shen a disparu... Je ne trouve plus Maman... Je n’ai nulle part où aller...",
            ["DialogueId"] = 12014311,
            ["GUID"] = "1E1399E6",
            ["NextDialogue"] = 12014312,
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210016,
            ["VoiceName"] = "voice/$Locale$/story/1201/120143/1E1399E6",
            },
        [12014312] = {
            ["Content"] = "呜哇，它怎么一下子激动了起来？",
            ["ContentFR"] = "Oh non... pourquoi il s’énerve d’un coup ?",
            ["DialogueId"] = 12014312,
            ["GUID"] = "1E139A10",
            ["NextDialogue"] = 12014313,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120143/1E139A10",
            },
        [12014313] = {
            ["Content"] = "小白，让我来吧。",
            ["ContentFR"] = "Snow, laisse-moi faire.",
            ["DialogueId"] = 12014313,
            ["GUID"] = "1E139A3A",
            ["NextDialogue"] = 12014314,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120143/1E139A3A",
            },
        [12014314] = {
            ["Content"] = "在外面待了这么久，你一定已经疲惫不堪了吧。我们先回祠台歇脚，可好？",
            ["ContentFR"] = "Tu es resté dehors bien trop longtemps. Tu dois être épuisé. Revenons d’abord à l’autel, d’accord ?",
            ["DialogueId"] = 12014314,
            ["GUID"] = "1E139A64",
            ["NextDialogue"] = 12014315,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120143/1E139A64",
            },
        [12014315] = {
            ["Content"] = "……嗯！",
            ["ContentFR"] = "... D’accord !",
            ["DialogueId"] = 12014315,
            ["GUID"] = "1E139A8E",
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210016,
            ["VoiceName"] = "voice/$Locale$/story/1201/120143/1E139A8E",
            },
        [12014316] = {
            ["Content"] = "姐姐带畏生回家！",
            ["ContentFR"] = "Wei Shen rentre à la maison !",
            ["DialogueId"] = 12014316,
            ["GUID"] = "1E139A8F",
            ["VoiceName"] = "voice/$Locale$/story/1201/120143/1E139A8F",
            },
        [12014401] = {
            ["Camera"] = "787.018799,197.117432,202.770752,0.000005,-7.400913,-173.19368,35.000011,100000.0,false,DoNotOverride,2.8",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "——谢谢你们！",
            ["ContentFR"] = "Merci à vous !",
