            },
        [12014403] = {
            ["Content"] = "这只小无由生，大约是生前偷偷跑出家门玩耍，却不慎失足坠亡。从那之后，“回家”成为了它的执念。",
            ["ContentFR"] = "Celui-ci devait être un enfant qui s’était enfui de chez lui pour jouer... Puis il a chuté, et a perdu la vie. Depuis lors, « rentrer à la maison » est devenu son obsession.",
            ["DialogueId"] = 12014403,
            ["Duration"] = 1,
            ["GUID"] = "1E13A8FE",
            ["NextDialogue"] = 12014404,
            ["SpeakNpcId"] = 210013,
            ["TalkActionId"] = {
                [1] = "210013:Baiheng_Story_Special03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120144/1E13A8FE",
            },
        [12014404] = {
            ["Camera"] = "69.47644,193.072845,103.465088,0.000062,22.596144,-171.999283,45.000023,78.807327,false,Manual,7.461847",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "可惜它年纪尚幼，不记得家的方位。光阴荏苒，它的亲人大约也……无处可寻了。",
            ["ContentFR"] = "Hélas, il était trop jeune pour se souvenir du chemin. Et avec le temps... sa famille est sans doute introuvable désormais.",
            ["DialogueId"] = 12014404,
            ["Duration"] = 1,
            ["FinalCamera"] = "66.714828,163.37291,100.481201,0.000061,24.395912,161.600143,45.000027,78.807327,false,Manual,7.461847",
            ["GUID"] = "1E13A928",
            ["LookAt"] = {
                [1] = "210013:p(BP_FixSimple_39_fushu)",
                },
            ["NextDialogue"] = 12014405,
            ["SpeakNpcId"] = 210013,
            ["TalkActionId"] = {
                [1] = "210013:Baiheng_Story_Special03_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1201/120144/1E13A928",
            },
        [12014405] = {
            ["Camera"] = "95.111908,170.19989,184.635742,0.000034,-28.601601,178.796585,35.000011,248.150375,false,Manual,10.0",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "哇……无由生真的是幽灵！不过，好像没有故事书里写的那么可怕！还有点可怜……",
            ["ContentFR"] = "Alors les Wishen sont vraiment des fantômes... Mais ils ne font pas peur comme dans les livres. Ils font plutôt... de la peine.",
            ["DialogueId"] = 12014405,
            ["FacialId"] = {
                [1] = "200002:Curious",
                },
            ["FinalCamera"] = "94.933746,161.763794,184.635742,0.000033,-28.801596,176.59642,35.000011,248.150375,false,Manual,10.0",
            ["GUID"] = "1E13A952",
            ["LookAt"] = {
                [1] = "210013:n(200002)",
                },
            ["NextDialogue"] = 12014406,
            ["Scripts"] = "PlayFacial{_delay{4.5},ActorId{200002},FacialId{\"Sad01\"}}",
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Explain02_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1201/120144/1E13A952",
            },
        [12014406] = {
            ["Camera"] = "787.018799,197.117432,202.770752,0.000005,-7.400913,-173.19368,35.000011,100000.0,false,DoNotOverride,2.8",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "此处本还有两只无由生，恐怕也被尘漠波及了。去寻觅它们的踪迹吧。",
            ["ContentFR"] = "Il devrait encore y avoir deux autres Wishen. Ils ont sans doute, eux aussi, été affectés par la Poussière-corrompue. Allons chercher leur trace.",
            ["DialogueId"] = 12014406,
            ["FinalCamera"] = "789.158203,179.179382,202.770752,0.000005,-7.400913,-173.19368,35.000011,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "1E13A97C",
            ["LookAt"] = {
                [1] = "210013:n(100001)",
                },
            ["Scripts"] = "PlayAnimation{_delay{4.5},ActorId{210013},AnimationId{\"Explain01_Start\"},Duration{1}}",
            ["SpeakNpcId"] = 210013,
            ["TalkActionId"] = {
                [1] = "200002:Explain02_End",
                [2] = "100001:AgreeHead",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1201/120144/1E13A97C",
            },
        [12014501] = {
            ["Content"] = "“一二三，木头人……”",
            ["ContentFR"] = "« Un, deux, trois... on ne bouge plus... »",
            ["DialogueId"] = 12014501,
            ["Duration"] = 2,
            ["GUID"] = "1E13B912",
            ["NextDialogue"] = 12014502,
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210017,
            ["SpeakNpcName"] = "UI_CMName_Name_WuyouShengSY",
            ["VoiceName"] = "voice/$Locale$/story/1201/120145/1E13B912",
            },
        [12014502] = {
            ["Content"] = "山洞中应是有一只小无由生。但是落石堵住了通路……",
            ["ContentFR"] = "Il y a un Wishen à l’intérieur... mais l’accès est bloqué.",
            ["DialogueId"] = 12014502,
            ["Duration"] = 3,
            ["GUID"] = "1E13B93C",
            ["NextDialogue"] = 12014503,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120145/1E13B93C",
            },
        [12014503] = {
            ["Content"] = "了解！拆迁作业小队上线喽——",
            ["ContentFR"] = "Reçu ! Équipe de démolition du Roi Démon, en action !",
            ["DialogueId"] = 12014503,
            ["Duration"] = 2,
            ["GUID"] = "1E13B966",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120145/1E13B966",
            },
        [12014601] = {
            ["Content"] = "“我们都是木头人，不许说话不许动……”",
            ["ContentFR"] = "« On est tous des statues... pas le droit de parler, pas le droit de bouger... »",
            ["DialogueId"] = 12014601,
            ["Duration"] = 3,
            ["GUID"] = "1E13C97A",
            ["NextDialogue"] = 12014602,
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210017,
            ["VoiceName"] = "voice/$Locale$/story/1201/120146/1E13C97A",
            },
        [12014602] = {
            ["Content"] = "它在哪里呢？",
            ["ContentFR"] = "Il est où, alors ?",
            ["DialogueId"] = 12014602,
            ["Duration"] = 1,
            ["GUID"] = "1E13C9A4",
            ["NextDialogue"] = 12014605,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120146/1E13C9A4",
            },
        [12014603] = {
            ["Content"] = "或许是这里的气味让它感到陌生，所以不愿意显现身形。",
            ["ContentFR"] = "L’odeur étrangère le rend méfiant... il refuse de se montrer.",
            ["DialogueId"] = 12014603,
            ["Duration"] = 3,
            ["GUID"] = "1E13C9CE",
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120146/1E13C9CE",
            },
        [12014604] = {
            ["Content"] = "点燃香炉试试吧，熟悉的香味能够给它带来安心感。",
            ["ContentFR"] = "Allumons l’encens. Le parfum familier devrait le rassurer.",
            ["DialogueId"] = 12014604,
            ["Duration"] = 2,
            ["GUID"] = "1E13C9F8",
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120146/1E13C9F8",
            },
        [12014605] = {
            ["Content"] = "……这里的花苞受尘漠侵蚀，散发出一股异样的香气。我想，它恐怕是因此不愿意显现身形。",
            ["ContentFR"] = "... Ces bourgeons ont été contaminés par la Poussière-corrompue. Ils dégagent une odeur inhabituelle. Cela doit l’effrayer.",
            ["DialogueId"] = 12014605,
            ["GUID"] = "1E13C9F9",
            ["NextDialogue"] = 12014606,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120146/1E13C9F9",
            },
        [12014606] = {
            ["Content"] = "清除这些花苞试试看吧。",
            ["ContentFR"] = "Essayons de les éliminer.",
            ["DialogueId"] = 12014606,
            ["GUID"] = "1E13CA11",
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120146/1E13CA11",
            },
        [12014701] = {
            ["Content"] = "被你找到啦！",
            ["ContentFR"] = "Tu m’as trouvé !",
            ["DialogueId"] = 12014701,
            ["Duration"] = 2,
            ["GUID"] = "1E13D9E2",
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210017,
            ["VoiceName"] = "voice/$Locale$/story/1201/120147/1E13D9E2",
            },
        [12014801] = {
            ["Content"] = "“……我、我是木头人！你看不到我，也不能打我！”",
            ["ContentFR"] = "« ... Je— je suis une statue ! Tu ne peux pas me voir... ni me frapper ! »",
            ["DialogueId"] = 12014801,
            ["Duration"] = 3,
            ["GUID"] = "1E13EA4A",
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210017,
            ["VoiceName"] = "voice/$Locale$/story/1201/120148/1E13EA4A",
            },
        [12014802] = {
            ["Content"] = "祠台就在前面，我认得路了……谢谢你们！",
            ["ContentFR"] = "Je reconnais le chemin... l’autel est juste devant. Merci !",
            ["DialogueId"] = 12014802,
            ["GUID"] = "1E13EA4B",
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210017,
            ["VoiceName"] = "voice/$Locale$/story/1201/120148/1E13EA4B",
            },
        [12014901] = {
            ["Content"] = "那个石碑上好像写着什么字！",
            ["ContentFR"] = "Hé ! Il y a quelque chose d’écrit sur cette stèle !",
            ["DialogueId"] = 12014901,
            ["Duration"] = 2,
            ["GUID"] = "1E13FAB2",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120149/1E13FAB2",
            },
        [12014902] = {
            ["Content"] = "<H>高高在上</>俯众生，<H>渐渐低下</>归于尘。无声无息随风去，谁能知晓它踪迹？",
            ["ContentFR"] = "<H>Haut dans les cieux</>, il observe les vivants. <H>Peu à peu plus bas</>, il retourne à la poussière. Silencieux, invisible, porté par le vent... Qui peut retrouver sa trace ?",
            ["DialogueId"] = 12014902,
            ["GUID"] = "1E13FADC",
            ["VoiceName"] = "voice/$Locale$/story/1201/120149/1E13FADC",
            },
        [12015001] = {
            ["Content"] = "别玩了，快跟着我们回去啦！",
            ["ContentFR"] = "Allez, assez joué ! On rentre !",
            ["DialogueId"] = 12015001,
            ["Duration"] = 2,
            ["GUID"] = "1E140B1A",
            ["NextDialogue"] = 12015002,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120150/1E140B1A",
            },
        [12015002] = {
            ["Content"] = "不行，还没有玩够！谜底，必须先解开谜底才可以！",
            ["ContentFR"] = "Non ! Pas encore ! Il faut d’abord résoudre l’énigme !",
            ["DialogueId"] = 12015002,
            ["Duration"] = 3,
            ["GUID"] = "1E140B44",
            ["NextDialogue"] = 12015003,
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210017,
            ["VoiceName"] = "voice/$Locale$/story/1201/120150/1E140B44",
            },
        [12015003] = {
            ["Content"] = "真是头疼……这是什么意思呢，{nickname}？",
            ["ContentFR"] = "Argh... qu’est-ce que ça veut dire, {nickname} ?",
            ["DialogueId"] = 12015003,
            ["Duration"] = 2,
            ["GUID"] = "1E140B6E",
            ["NextDialogue"] = 12015004,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120150/1E140B6E",
            },
        [12015004] = {
            ["Content"] = "“高高在上，渐渐低下”……我想，或许这些花苞需要用自上而下的顺序击打才可以？",
            ["ContentFR"] = "« Haut dans les cieux, peu à peu plus bas »... Peut-être faut-il activer ces bourgeons de haut en bas.",
            ["DialogueId"] = 12015004,
            ["GUID"] = "1E140B6F",
            ["NextDialogue"] = 12015005,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120150/1E140B6F",
            },
        [12015005] = {
            ["Content"] = "有道理哦，小仆从，我们赶紧试试！",
            ["ContentFR"] = "Bonne idée ! Essayons vite, petit larbin !",
            ["DialogueId"] = 12015005,
            ["GUID"] = "1E140B71",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120150/1E140B71",
            },
        [12015101] = {
            ["Camera"] = "428.628632,87.300842,126.54541,0.0,0.0,-179.794601,30.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "怎么样，你们现在有答案了吗？",
            ["ContentFR"] = "Alors ? Vous avez trouvé la réponse ?",
            ["DialogueId"] = 12015101,
            ["FinalCamera"] = "427.964111,58.333099,126.54541,0.0,0.0,178.205566,30.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "1E141B82",
            ["LookAt"] = {
                [1] = "100001:n(210013)",
                [2] = "100001:n(210039)",
                },
            ["NextDialogue"] = 12015102,
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210017,
            ["TalkActionId"] = {
                [1] = "210039:Wuyou_Born",
                },
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/1201/120151/1E141B82",
            },
        [12015102] = {
            ["Camera"] = "-296.378662,-545.068665,191.578613,0.000033,-5.400473,67.00705,40.000023,644.465149,false,Manual,8.26397",
            ["Content"] = "俯瞰众生，却又渺无形踪，归于尘土……你想说的或许是云朵吧。",
            ["ContentFR"] = "Observer d’en haut, disparaître sans laisser de trace, retourner à la poussière... Tu parles sans doute des nuages.",
            ["DialogueId"] = 12015102,
            ["FinalCamera"] = "-331.210388,-529.07074,191.578613,0.000035,-5.400439,63.406521,40.000023,644.465149,false,Manual,8.26397",
            ["GUID"] = "1E141BAC",
            ["LookAt"] = {
                [1] = "210013:n(100001)",
                },
            ["NextDialogue"] = 12015103,
            ["Scripts"] = "LookAt{_delay{3.1},LookAtDescription{\"210013:n(210039)\"}}",
            ["SpeakNpcId"] = 210013,
            ["TalkActionId"] = {
                [1] = "100001:Think_Start",
                [2] = "210013:Shy03_Start",
                [3] = "200002:Think_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1201/120151/1E141BAC",
            },
        [12015103] = {
            ["Camera"] = "428.628632,87.300842,126.54541,0.0,0.0,-179.794601,30.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "嘻嘻，姐姐真聪明！我尽兴啦，我们回去吧！",
            ["ContentFR"] = "Hihi ! La grande sœur est trop forte ! J’ai bien joué, on peut rentrer !",
            ["DialogueId"] = 12015103,
            ["FinalCamera"] = "427.964111,58.333099,126.54541,0.0,0.0,178.205566,30.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "1E141BD6",
            ["LookAt"] = {
                [1] = "100001:n(210039)",
                },
            ["Scripts"] = "PlayAnimation{_delay{4.1},ActorId{210039},AnimationId{\"Wuyou_Disappear\"},Duration{1}}",
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210017,
            ["TalkActionId"] = {
                [1] = "100001:Think_End",
                [2] = "210039:Wuyou_Agree",
                [3] = "200002:Think_End",
                },
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/1201/120151/1E141BD6",
            },
        [12015201] = {
            ["Camera"] = "920.312744,232.194031,104.525879,0.000081,-0.59857,-171.306732,30.000008,100000.0,false,DoNotOverride,2.8",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "终于找齐了三个小无由生……真是把魔王大人累得够呛！",
            ["ContentFR"] = "Enfin... on a retrouvé les trois petits Wishen. Même le Roi Démon est épuisé !",
            ["DialogueId"] = 12015201,
            ["FacialId"] = {
                [1] = "200002:Syouganai01",
                },
            ["FinalCamera"] = "935.710205,90.954773,104.525879,0.000081,-0.59857,-176.506149,30.000008,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "1E142BEA",
            ["NextDialogue"] = 12015202,
            ["Scripts"] = "PlayAnimation{_delay{3.01},ActorId{200002},AnimationId{\"BaiTX_Story_Tired_End\"},Duration{1}},\
",
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:BaiTX_Story_Tired_Loop",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1201/120152/1E142BEA",
            },
        [12015202] = {
            ["Camera"] = "38.708542,27.845192,156.223022,0.000037,4.201495,162.893906,30.000008,100000.0,false,DoNotOverride,2.8",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "听好了，从现在起，你们都乖乖待在这里，不许说话，也不许乱跑！",
            ["ContentFR"] = "Écoutez bien ! À partir de maintenant, vous restez ici, sans bavarder ni partir en cachette !",
            ["DialogueId"] = 12015202,
            ["FacialId"] = {
                [1] = "200002:Angry01",
                },
            ["FinalCamera"] = "99.139954,-31.090532,153.350342,0.000036,2.801416,161.096512,30.000008,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "1E142C14",
            ["LookAt"] = {
                [1] = "200002:n(210038)",
                },
            ["NextDialogue"] = 12015203,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Confident_Start",
                [2] = "100001:Confident_Start",
                },
            ["ToFinalCameraBlendTime"] = 15,
            ["VoiceName"] = "voice/$Locale$/story/1201/120152/1E142C14",
            },
        [12015203] = {
            ["Content"] = "好啦，小白，莫再逗弄它们了。小心它们生气，不愿为你叩响通往虞泉的门扉。",
            ["ContentFR"] = "Allons, Snow. Ne les embête pas davantage. S’ils se fâchent, ils pourraient refuser d’ouvrir la porte menant à la Source de Yu.",
            ["DialogueId"] = 12015203,
            ["FacialId"] = {
                [1] = "200002:None",
                },
            ["GUID"] = "1E142C3E",
            ["LookAt"] = {
                [1] = "200002:n(210013)",
                },
            ["NextDialogue"] = 12015204,
            ["SpeakNpcId"] = 210013,
            ["TalkActionId"] = {
                [1] = "200002:Confident_End",
                [2] = "210013:Explain01_Start",
                [3] = "100001:Confident_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120152/1E142C3E",
            },
        [12015204] = {
            ["Camera"] = "133.228226,-647.736572,205.264771,0.000173,-8.198883,105.089806,30.000002,100000.0,false,DoNotOverride,2.8",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "你的意思是……我们还没有抵达真正的虞泉？",
            ["ContentFR"] = "Hein ?! Attends... tu veux dire qu’on n’y est pas encore ?",
            ["DialogueId"] = 12015204,
            ["FacialId"] = {
                [1] = "200002:Think01",
                },
            ["FinalCamera"] = "155.219604,-729.304077,217.437256,0.000173,-8.198883,105.089806,30.000002,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "1E142C68",
            ["LookAt"] = {
                [1] = "200002:n(100001)",
                [2] = "100001:n(200002)",
                },
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "100001:Think_Start",
                [2] = "200002:Shy03_Start",
                [3] = "210013:Explain01_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1201/120152/1E142C68",
            },
        [12015301] = {
            ["Content"] = "哇……！",
            ["ContentFR"] = "Ouah... !",
            ["DialogueId"] = 12015301,
            ["GUID"] = "1E143C52",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120153/1E143C52",
            },
        [12015401] = {
            ["Content"] = "呜，姐姐……姐姐不见了……",
            ["ContentFR"] = "<I>Bouh...</> grande sœur... grande sœur a disparu...",
            ["DialogueId"] = 12015401,
            ["GUID"] = "1E144CBA",
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210019,
            ["VoiceName"] = "voice/$Locale$/story/1201/120154/1E144CBA",
            },
        [12015402] = {
            ["Content"] = "在你们面前，一个异样又光怪陆离的，属于无由生那一边的世界，徐徐展开……",
            ["ContentFR"] = "Devant vous se déploie lentement un monde étrange et chatoyant... Un royaume appartenant aux Wishen, dissimulé au regard ordinaire.",
            ["DialogueId"] = 12015402,
            ["GUID"] = "1E144CBB",
            },
        [12015501] = {
            ["Camera"] = "362.349304,617.265076,20.103271,0.000049,3.644691,-117.98333,30.0,50.546654,false,Manual,13.930334",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "果然，只要还能晒太阳的日子足够久，便能好事常在，笑口常开。",
            ["ContentFR"] = "Ah... tant qu’il nous reste des jours assez longs pour sentir le soleil sur notre peau, le bonheur finit toujours par revenir, et les sourires aussi.",
            ["DialogueId"] = 12015501,
            ["FinalCamera"] = "379.79364,607.996277,20.103271,0.000049,3.644691,-117.983383,30.000002,548.337769,false,Manual,13.930334",
            ["GUID"] = "1E145D22",
            ["LookAt"] = {
                [1] = "200002:n(210040)",
                [2] = "100001:n(210040)",
                [3] = "210013:n(210040)",
                },
            ["NextDialogue"] = 12015502,
            ["RelatedWikiId"] = {
                [1] = 408013,
                [2] = 303012,
                [3] = 203006,
                },
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210018,
            ["TalkActionId"] = {
                [1] = "100001:Talk03_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1201/120155/1E145D22",
            },
        [12015502] = {
            ["Camera"] = "63.533028,163.058304,86.610718,0.000035,20.601974,-118.808426,35.000008,100000.0,false,DoNotOverride,2.8",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "我这把老骨头还能见到故知，值了。祝由大人，还有两位化外之客。幸会！",
            ["ContentFR"] = "Que ces vieux os puissent revoir une connaissance d’autrefois... ça valait le coup. Dame Zhuyou, et deux hôtes venus d’au-delà. Soyez les bienvenus.",
            ["DialogueId"] = 12015502,
            ["FinalCamera"] = "80.940094,151.962341,86.610718,0.000031,20.202141,-123.608315,35.000008,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "1E145D4C",
            ["NextDialogue"] = 12015503,
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210018,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1201/120155/1E145D4C",
            },
        [12015503] = {
            ["Camera"] = "-357.707886,104.663635,262.303223,0.000057,-18.755178,-8.789527,30.0,100000.0,false,DoNotOverride,2.8",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "您太客气了，扶疏当不起这个尊称。",
            ["ContentFR"] = "Vous êtes trop aimable. Je ne mérite pas un tel titre.",
            ["DialogueId"] = 12015503,
            ["FinalCamera"] = "-357.707886,104.663635,262.303223,0.000051,-20.955013,-7.790245,30.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "1E145D76",
            ["NextDialogue"] = 12015504,
            ["SpeakNpcId"] = 210013,
            ["TalkActionId"] = {
                [1] = "210013:Baiheng_Story_Special01_Start",
                },
            ["ToFinalCameraBlendTime"] = 15,
            ["VoiceName"] = "voice/$Locale$/story/1201/120155/1E145D76",
            },
        [12015504] = {
            ["Content"] = "呵呵……百年之前的疫疠，在下受过祝由大人的恩惠，没齿难忘。几位有什么需要尽管开口。",
            ["ContentFR"] = "Héhé... lors de l’épidémie d’il y a cent ans, j’ai reçu les bienfaits de vos soins. Je ne l’ai jamais oublié. Dites-moi donc ce dont vous avez besoin.",
            ["DialogueId"] = 12015504,
            ["FacialId"] = {
                [1] = "200002:Nervous",
                },
            ["GUID"] = "1E145DA0",
            ["NextDialogue"] = 12015505,
            ["RelatedWikiId"] = {
                [1] = 401004,
                },
            ["Scripts"] = "SEQ{\
LookAt{_delay{6.1},LookAtDescription{\"200002:n(210013)\"}},\
LookAt{_delay{2.1},LookAtDescription{\"200002:n(210040)\"}},\
PlayAnimation{delay{1.5},ActorId{200002},AnimationId{\"Think_End\"},Duration{1}}\
}",
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210018,
            ["TalkActionId"] = {
                [1] = "200002:Think_Start",
                [2] = "210013:Baiheng_Story_Special01_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120155/1E145DA0",
            },
        [12015505] = {
            ["Camera"] = "115.516785,197.20285,91.707275,0.000133,-32.198425,-53.396206,30.0,140.374573,false,Manual,8.366085",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "等等，小仆从，你不觉得他们的交谈有哪里不对劲吗？！",
            ["ContentFR"] = "Attends, petit larbin... tu trouves pas qu’il y a un truc qui cloche dans ce qu’ils viennent de dire ?!",
            ["DialogueId"] = 12015505,
            ["FinalCamera"] = "105.107033,219.02327,94.781616,0.000144,-27.398195,-54.795994,30.0,166.458572,false,Manual,11.745219",
            ["GUID"] = "1E145DCA",
            ["LookAt"] = {
                [1] = "200002:n(100001)",
                [2] = "100001:n(200002)",
                },
            ["NextOptions"] = {
                [1] = 120155051,
                [2] = 120155052,
                },
            ["SpeakNpcId"] = 200002,
            ["ToFinalCameraBlendTime"] = 10,
            ["TurnTo"] = {
                [1] = "200002:n(100001)",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120155/1E145DCA",
            },
        [12015507] = {
            ["Content"] = "你没有听明白吗小仆从！按他话里的意思，扶疏至少活了一百年那么久！",
            ["ContentFR"] = "Mais tu n’as pas compris ?! D’après ce qu’il dit, Fushu a au moins cent ans !",
            ["DialogueId"] = 12015507,
            ["FacialId"] = {
                [1] = "200002:Shock01",
                },
            ["GUID"] = "1E145E1E",
            ["NextDialogue"] = 12015509,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120155/1E145E1E",
            },
        [12015509] = {
            ["Camera"] = "105.107033,219.02327,94.781616,0.000144,-27.398195,-54.795994,30.0,166.458572,false,Manual,11.745219",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "压根就看不出来！原来华胥的医术已经进化到长生不老的水平了吗？！",
            ["ContentFR"] = "Ça ne se voit absolument pas ! Ne me dis pas que la médecine de Huaxu a déjà percé le secret de l’immortalité ?!",
            ["DialogueId"] = 12015509,
            ["FinalCamera"] = "131.587952,179.929916,89.484497,0.000167,-4.597933,-58.195728,30.0,166.458572,false,Manual,11.745219",
            ["GUID"] = "1E145E72",
            ["LookAt"] = {
                [1] = "200002:n(210013)",
                [2] = "100001:n(210013)",
                },
            ["NextDialogue"] = 12015510,
            ["Scripts"] = "SEQ{\
LookAt{delay{2.5},LookAtDescription{\"210013:n(100001)\"}},\
TurnTo{TurnToDescription{\"210013:n(100001)\"}},\
PlayAnimation{delay{2.5},ActorId{210013},AnimationId{\"Explain02_Start\"},Duration{1}},\
}",
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "100001:Talk03_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["TurnTo"] = {
                [1] = "200002:n(210013)",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120155/1E145E72",
            },
        [12015510] = {
            ["Content"] = "……并非你们所想的那样。",
            ["ContentFR"] = "... Ce n’est pas ce que vous imaginez.",
            ["DialogueId"] = 12015510,
            ["GUID"] = "1E145E9C",
            ["LookAt"] = {
                [1] = "210013:n(100001)",
                },
            ["NextDialogue"] = 12015511,
            ["Scripts"] = "PlayAnimation{delay{2.5},ActorId{210013},AnimationId{\"DisagreeHead\"},Duration{1}}",
            ["SpeakNpcId"] = 210013,
            ["TalkActionId"] = {
                [1] = "210013:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120155/1E145E9C",
            },
        [12015511] = {
            ["Content"] = "长生无得者，举世如蜉蝣。我只是比别人多掌握了枯荣之术，但并未逃出生老病死的自然规律。",
            ["ContentFR"] = "L’immortalité n’appartient à personne : aux yeux du monde, nous ne sommes que des éphémères. J’ai seulement appris l’Art de l’Éphémère... sans pouvoir échapper aux lois naturelles de la naissance, de l’âge et de la mort.",
            ["DialogueId"] = 12015511,
            ["GUID"] = "1E145EC6",
            ["NextDialogue"] = 12015512,
            ["Scripts"] = "SEQ{\
PlayAnimation{delay{0.5},ActorId{210013},AnimationId{\"Talk01_Start\"},Duration{3}},\
PlayAnimation{ActorId{210013},AnimationId{\"Talk01_End\"},Duration{5}},\
PlayAnimation{delay{0.5},ActorId{210013},AnimationId{\"DisagreeHead\"},Duration{3}},\
LookAt{LookAtDescription{\"210013:p(BP_FixSimple_42_fushu01)\"}}\
}",
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120155/1E145EC6",
            },
        [12015512] = {
            ["Camera"] = "113.025772,32.107635,18.959473,0.000157,29.397686,10.806211,30.000008,12977.529297,false,Manual,12.571992",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "百年前的大疫中，我奔走救治时不慎……染上恶疾。家姐通过某种方式将我的躯体冻结，从而暂缓了疾病进程。",
            ["ContentFR"] = "Lors de la Grande Épidémie, il y a cent ans... en soignant les malades, j’ai été imprudente et j’ai... contracté un mal terrible. Ma sœur a figé mon corps par un procédé qui lui était propre, afin de ralentir la progression de la maladie.",
            ["DialogueId"] = 12015512,
            ["Duration"] = 2,
            ["FinalCamera"] = "177.948578,52.488884,107.528198,0.000187,49.996937,27.204828,30.000013,12977.529297,false,Manual,12.571992",
            ["GUID"] = "1E145EF0",
            ["NextDialogue"] = 12015513,
            ["SpeakNpcId"] = 210013,
            ["ToFinalCameraBlendTime"] = 20,
            ["VoiceName"] = "voice/$Locale$/story/1201/120155/1E145EF0",
            },
        [12015513] = {
            ["Camera"] = "117.45327,198.753036,53.425415,0.000171,6.802288,-52.19939,30.000008,184.001556,false,Manual,14.564116",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "直至不久之前，家姐传人将我从沉眠中唤醒，并用最新研制出的药物将我体内的疾病祛除，我才重新行走于世间。",
            ["ContentFR"] = "Ce n’est que récemment qu’un disciple de ma sœur m’a tirée de ce long sommeil. À l’aide d’un remède nouvellement mis au point, il a purgé la maladie de mon corps… et j’ai pu revenir parmi les vivants.",
            ["DialogueId"] = 12015513,
            ["FinalCamera"] = "99.263199,221.05603,50.602173,0.000163,5.602271,-50.799461,30.000008,246.6875,false,Manual,14.564116",
            ["GUID"] = "1E145F1A",
            ["LookAt"] = {
                [1] = "210013:n(100001)",
                },
            ["NextDialogue"] = 12015514,
            ["SpeakNpcId"] = 210013,
            ["ToFinalCameraBlendTime"] = 10,
            ["TurnTo"] = {
                [1] = "100001:n(210013)",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120155/1E145F1A",
            },
        [12015514] = {
            ["Camera"] = "193.710571,70.915855,75.647705,0.000229,-10.198722,104.400436,30.000023,100.823143,false,Manual,12.571992",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "难怪你的家干干净净，看起来像从未住过人一样……",
            ["ContentFR"] = "Je comprends mieux pourquoi ton pavillon était si impeccablement rangé... on aurait dit qu’il n’avait jamais été habité.",
            ["DialogueId"] = 12015514,
            ["FacialId"] = {
                [1] = "100001:Shy",
                },
            ["FinalCamera"] = "191.586731,79.1856,74.111816,0.000238,-10.198688,104.400826,30.000023,79.899963,false,Manual,12.571992",
            ["GUID"] = "1E145F44",
            ["NextDialogue"] = 12015515,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Explain02_Start",
                },
            ["ToFinalCameraBlendTime"] = 15,
            ["VoiceName"] = "voice/$Locale$/story/1201/120155/1E145F44",
            },
        [12015515] = {
            ["Content"] = "一百年过去了，那你的姐姐……她还活着吗？",
            ["ContentFR"] = "Cent ans ont passé... et ta sœur ? Est-elle encore en vie ?",
            ["DialogueId"] = 12015515,
            ["FacialId"] = {
                [1] = "100001:Sad03",
                },
            ["GUID"] = "1E145F6E",
            ["LookAt"] = {
                [1] = "210013:n(210013)",
                },
            ["NextDialogue"] = 12015516,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120155/1E145F6E",
            },
        [12015516] = {
            ["Camera"] = "141.07724,117.392189,94.321289,0.000034,-5.756408,-48.184006,40.0,105.288483,false,Manual,8.191999",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "醒来后，我经过多方打听，得知家姐已于数年前溘然长逝。",
            ["ContentFR"] = "Après mon réveil, j’ai cherché, longtemps... J’ai appris que ma sœur s’était éteinte, il y a déjà quelques années.",
            ["DialogueId"] = 12015516,
            ["FacialId"] = {
                [1] = "210013:Sad03",
                },
            ["FinalCamera"] = "137.903931,114.5532,94.321289,0.000034,-5.756408,-48.184006,40.0,105.288483,false,Manual,8.191999",
            ["GUID"] = "1E145F98",
            ["NextDialogue"] = 12015517,
            ["SpeakNpcId"] = 210013,
            ["TalkActionId"] = {
                [1] = "210013:Explain02_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1201/120155/1E145F98",
            },
        [12015517] = {
            ["Camera"] = "528.575195,399.370605,61.019653,0.000049,2.244195,-139.985504,30.0,100000.0,false,DoNotOverride,2.8",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "这也没什么大不了的啦。人皆有一死，如同草木枯荣，云起云落。你们生者无需为此感到伤神。",
            ["ContentFR"] = "Oh, ce n’est rien de tragique. Les gens meurent, comme les plantes se fanent et refleurissent, comme les nuages se lèvent et se dissipent. Vous autres, les vivants, n’avez pas à en porter le chagrin.",
            ["DialogueId"] = 12015517,
            ["FinalCamera"] = "555.92688,361.963898,61.019653,0.000049,2.644185,-144.785583,30.000002,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "1E145FC2",
            ["LookAt"] = {
                [1] = "200002:n(210040)",
                [2] = "100001:n(210040)",
                [3] = "210013:n(210040)",
                },
            ["NextDialogue"] = 12015518,
            ["Scripts"] = "TurnTo{delay{3},TurnToDescription{\"210013:n(210040)\"}}",
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210018,
            ["TalkActionId"] = {
                [1] = "210013:Explain02_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["TurnTo"] = {
                [1] = "200002:n(210040)",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120155/1E145FC2",
            },
        [12015518] = {
            ["Camera"] = "41.130356,69.325104,81.061401,0.000038,-30.356098,-0.185585,30.000002,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "对哦，差点忘了……无由生也是死者耶。",
            ["ContentFR"] = "Ah oui, j’avais oublié... Les Wishen, eux aussi, sont des morts...",
            ["DialogueId"] = 12015518,
            ["FacialId"] = {
                [1] = "200002:Nervous",
                },
            ["GUID"] = "1E145FEC",
            ["NextDialogue"] = 12015519,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Shock03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120155/1E145FEC",
            },
        [12015519] = {
            ["Camera"] = "41.130356,69.325104,81.061401,0.000038,-30.356098,-0.185532,30.000002,148.839142,false,Manual,5.737342",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "嗯。家姐生前得偿所愿，她所醉心的草药学说也发扬光大，学徒众多，成为华胥的一门显学……所以无需为她感到遗憾。",
            ["ContentFR"] = "Oui. Ma sœur a obtenu ce qu’elle désirait de son vivant. Son étude des remèdes et des plantes s’est transmise, a prospéré, et compte désormais de nombreux disciples... Il n’y a donc pas lieu de la regretter.",
            ["DialogueId"] = 12015519,
            ["FacialId"] = {
                [1] = "210013:None",
                },
            ["FinalCamera"] = "41.130405,69.32515,81.061401,0.000048,-0.555725,-10.785604,30.000008,173.391495,false,Manual,4.750704",
            ["GUID"] = "1E146016",
            ["LookAt"] = {
                [1] = "100001:n(210013)",
                },
            ["NextDialogue"] = 12015520,
            ["Scripts"] = "SEQ{\
LookAt{LookAtDescription{\"200002:n(210013)\"}},\
