            },
        [12015524] = {
            ["Camera"] = "141.07724,117.392189,94.321289,0.000034,-5.756408,-48.184006,40.0,105.288483,false,Manual,8.191999",
            ["Content"] = "那就多谢你们了。",
            ["ContentFR"] = "Merci. Je m’en remets à vous, mes {性别:amis|amies}.",
            ["DialogueId"] = 12015524,
            ["FacialId"] = {
                [1] = "100001:None",
                [2] = "210013:Smile01",
                },
            ["GUID"] = "1E1460E8",
