            },
        [12015529] = {
            ["Camera"] = "63.533028,163.058304,86.610718,0.000035,20.601974,-118.808426,35.000008,100000.0,false,DoNotOverride,2.8",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "对了，如果你们是往那个方向走，可以帮我留神一件事吗？",
            ["ContentFR"] = "Au fait, puisque vous prenez ce chemin... pourrais-je vous demander une chose ?",
            ["DialogueId"] = 12015529,
            ["FinalCamera"] = "80.940094,151.962341,86.610718,0.000031,20.202141,-123.608315,35.000008,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "1E1461BA",
            ["NextDialogue"] = 12015530,
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210018,
            ["TalkActionId"] = {
                [1] = "210013:Think_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1201/120155/1E1461BA",
            },
        [12015530] = {
            ["Content"] = "您说。",
            ["ContentFR"] = "Je vous écoute.",
            ["DialogueId"] = 12015530,
            ["GUID"] = "1E1461E4",
            ["LookAt"] = {
                [1] = "100001:n(210040)",
                },
            ["NextDialogue"] = 12015531,
