            },
        [12015603] = {
            ["Camera"] = "60.763,225.503906,204.802368,0.000088,-28.598343,-74.769676,30.0,117.073692,false,Manual,6.747885",
            ["Content"] = "挑那些花期正至，根色鲜泽的，药效会更好些。",
            ["ContentFR"] = "Choisis celles qui sont en pleine floraison, avec des racines vives : leur vertu sera meilleure.",
            ["DialogueId"] = 12015603,
            ["FinalCamera"] = "73.483093,228.381836,204.802368,0.000087,-28.798365,-81.168892,30.0,117.073692,false,Manual,6.747885",
            ["GUID"] = "1E146DDE",
            ["LookAt"] = {
                [1] = "210013:n(200002)",
                },
            ["NextDialogue"] = 12015604,
            ["SpeakNpcId"] = 210013,
            ["TalkActionId"] = {
                [1] = "210013:Shy03_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1201/120156/1E146DDE",
            },
        [12015604] = {
            ["Camera"] = "315.013123,-16.664062,87.76709,0.000089,7.94519,113.863701,40.000011,248.711517,false,DoNotOverride,6.747885",
            ["Content"] = "好嘞，包在我们身上！",
            ["ContentFR"] = "Bien reçu ! Compte sur nous !",
            ["DialogueId"] = 12015604,
            ["FinalCamera"] = "307.165344,-20.133789,87.76709,0.000089,7.94519,113.863922,40.000011,248.711517,false,DoNotOverride,6.747885",
