            },
        [12015701] = {
            ["Content"] = "喂——小仆从，你快过来看看！",
            ["ContentFR"] = "Hé— ! Petit larbin, viens vite voir par ici !",
            ["DialogueId"] = 12015701,
            ["Duration"] = 3,
            ["GUID"] = "1E147DF2",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120157/1E147DF2",
            },
        [12015801] = {
            ["Camera"] = "428.589844,98.277344,126.54541,0.0,0.0,-179.794739,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "……难道是白幻听了吗？小仆从，你来帮我确认一下，是不是有什么声音从这边传过来？",
            ["ContentFR"] = "Dis donc, est-ce que c’est moi qui hallucine ? Petit larbin, viens confirmer pour moi... Tu n’entends rien, par ici ?",
            ["DialogueId"] = 12015801,
            ["GUID"] = "1E148E5A",
            ["NextDialogue"] = 12015802,
            ["RelatedWikiId"] = {
                [1] = 408013,
                [2] = 303012,
                [3] = 203006,
                },
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120158/1E148E5A",
            },
        [12015802] = {
            ["Content"] = "好。",
            ["ContentFR"] = "D’accord.",
            ["DialogueId"] = 12015802,
            ["GUID"] = "1E148E84",
            ["NextDialogue"] = 12015803,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120158/1E148E84",
            },
        [12015803] = {
            ["Content"] = "……救救……救救……",
            ["ContentFR"] = "... À l’aide... à l’aide...",
            ["DialogueId"] = 12015803,
            ["GUID"] = "1E148EAE",
            ["NextDialogue"] = 12015804,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 210028,
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["VoiceName"] = "voice/$Locale$/story/1201/120158/1E148EAE",
            },
        [12015804] = {
            ["Content"] = "是有什么人在说话，那个人好像在向路过的人求助。",
            ["ContentFR"] = "J’entends quelqu’un. On dirait une personne qui appelle à l’aide.",
            ["DialogueId"] = 12015804,
            ["GUID"] = "1E148ED8",
            ["NextDialogue"] = 12015805,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120158/1E148ED8",
            },
        [12015805] = {
            ["Content"] = "那人在喊……“舅舅”？她也是在找自己的亲人吗？",
            ["ContentFR"] = "Elle a dit... « tonton » ? Elle cherche sa famille, elle aussi ?",
            ["DialogueId"] = 12015805,
            ["GUID"] = "1E148F02",
            ["NextDialogue"] = 12015806,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120158/1E148F02",
            },
        [12015806] = {
            ["Content"] = "不能消失……我还有……",
            ["ContentFR"] = "Je ne peux pas... disparaître... Il me reste...",
            ["DialogueId"] = 12015806,
            ["GUID"] = "1E148F2C",
            ["NextDialogue"] = 12015807,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 210028,
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["VoiceName"] = "voice/$Locale$/story/1201/120158/1E148F2C",
            },
        [12015807] = {
            ["Content"] = "在……之前……请让我……",
            ["ContentFR"] = "Avant... que... laisse-moi...",
            ["DialogueId"] = 12015807,
            ["GUID"] = "1E148F56",
            ["NextDialogue"] = 12015808,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 210028,
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["VoiceName"] = "voice/$Locale$/story/1201/120158/1E148F56",
            },
        [12015808] = {
            ["Content"] = "对吧对吧，白没有听错！就是说嘛，本魔王的听力，连水仙平原最细微角落的悄悄话都能听得一清二楚！",
            ["ContentFR"] = "Tu vois, tu vois ! Je n’ai pas rêvé ! Évidemment ! Les oreilles du grand Roi Démon captent même les murmures les plus discrets des Asphodèles !",
            ["DialogueId"] = 12015808,
            ["GUID"] = "1E148F80",
            ["NextDialogue"] = 12015809,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120158/1E148F80",
            },
        [12015809] = {
            ["Content"] = "明白了，下次有什么不能带你商量的事，一定让你走远点。",
            ["ContentFR"] = "Je prends note. La prochaine fois que j’aurai un secret, je t’enverrai marcher très loin devant.",
            ["DialogueId"] = 12015809,
            ["GUID"] = "1E148FAA",
            ["NextDialogue"] = 12015810,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120158/1E148FAA",
            },
        [12015810] = {
            ["Content"] = "喂，太过分了！！",
            ["ContentFR"] = "Hé ! C’est vraiment méchant !",
            ["DialogueId"] = 12015810,
            ["GUID"] = "1E148FD4",
            ["NextDialogue"] = 12015811,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120158/1E148FD4",
            },
        [12015811] = {
            ["Content"] = "……话说回来，这个声音的主人在哪里，我们又该怎么找到它呢？",
            ["ContentFR"] = "Mais au fait, cette voix... d’où elle vient ? Et comment est-ce qu’on est censés la retrouver ?",
            ["DialogueId"] = 12015811,
            ["GUID"] = "1E148FFE",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120158/1E148FFE",
            },
        [12015901] = {
            ["Camera"] = "428.589844,98.277344,126.54541,0.0,0.0,-179.794739,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "小仆从，刚刚什么动静？",
            ["ContentFR"] = "Petit larbin ! C’était quoi, ce bruit ?!",
            ["DialogueId"] = 12015901,
            ["GUID"] = "1E149EC2",
            ["NextDialogue"] = 12015902,
            ["RelatedWikiId"] = {
                [1] = 408013,
                [2] = 303012,
                [3] = 203006,
                },
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120159/1E149EC2",
            },
        [12015902] = {
            ["Content"] = "小仆从，小仆从？……{nickname}？！",
            ["ContentFR"] = "Petit larbin ? ... Petit larbin ?! ... {nickname} ?!",
            ["DialogueId"] = 12015902,
            ["GUID"] = "1E149EEC",
            ["NextDialogue"] = 12015903,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120159/1E149EEC",
            },
        [12015903] = {
            ["Camera"] = "428.589844,98.277344,126.54541,0.0,0.0,-179.794739,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "你、你怎么不说话呀……",
            ["ContentFR"] = "Hé— hé, parle-moi... !",
            ["DialogueId"] = 12015903,
            ["GUID"] = "1E149F16",
            ["NextDialogue"] = 12015904,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120159/1E149F16",
            },
        [12015904] = {
            ["Content"] = "怎么办！扶疏，扶疏，大事不好啦——",
            ["ContentFR"] = "Qu’est-ce que je fais... Fushu ! Fushu, catastrophe— !",
            ["DialogueId"] = 12015904,
            ["GUID"] = "1E149F40",
            ["NextDialogue"] = 12015905,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120159/1E149F40",
            },
        [12015905] = {
            ["Content"] = "发生了什么？",
            ["ContentFR"] = "Que se passe-t-il ?",
            ["DialogueId"] = 12015905,
            ["GUID"] = "1E149F6A",
            ["NextDialogue"] = 12015906,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120159/1E149F6A",
            },
        [12015906] = {
            ["Content"] = "呜哇……刚刚有什么人在看不见的地方说话，我和小仆从准备去找找看，可是刚刚突然有一道光闪过，“滋溜”一声，小仆从就变成了这个呆呆的样子！",
            ["ContentFR"] = "Bouhou... Il y avait quelqu’un qui parlait d’un endroit invisible... On est allés voir, et là— un flash ! « <I>Ziiip</> » ! Et mon petit larbin est devenu tout... tout figé !",
            ["DialogueId"] = 12015906,
            ["GUID"] = "1E149F94",
            ["NextDialogue"] = 12015907,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120159/1E149F94",
            },
        [12015907] = {
            ["Content"] = "怎么喊都不答应……就像是灵魂被抽走了一样！",
            ["ContentFR"] = "J’ai beau l’appeler, {性别:il|elle} ne répond pas... Comme si son âme avait été arrachée !",
            ["DialogueId"] = 12015907,
            ["GUID"] = "1E149FBE",
            ["NextDialogue"] = 12015908,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120159/1E149FBE",
            },
        [12015908] = {
            ["Content"] = "小白，你先镇定下来，焦急于情势无补。安心，有我在。",
            ["ContentFR"] = "Snow, calme-toi. L’agitation n’aidera en rien. Respire. Je suis là.",
            ["DialogueId"] = 12015908,
            ["GUID"] = "1E149FE8",
            ["NextDialogue"] = 12015910,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120159/1E149FE8",
            },
        [12015910] = {
            ["Content"] = "你是说……你最后一次看到正常的{nickname}，是在这里吗？",
            ["ContentFR"] = "Tu dis que... la dernière fois que {nickname} allait bien, c’était ici ?",
            ["DialogueId"] = 12015910,
            ["GUID"] = "1E14A03C",
            ["NextDialogue"] = 12015912,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120159/1E14A03C",
            },
        [12015912] = {
            ["Content"] = "这是什么？{nickname}该不会有危险吧？！",
            ["ContentFR"] = "C’est quoi, ce truc ?! {nickname} n’est pas en danger, hein ?!",
            ["DialogueId"] = 12015912,
            ["GUID"] = "1E14A090",
            ["NextDialogue"] = 12015913,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120159/1E14A090",
            },
        [12015913] = {
            ["Content"] = "如果我没有猜错，{性别：他|她}的精神被<H>往隙</>吞噬了。",
            ["ContentFR"] = "Si je ne me trompe pas... son esprit a été englouti par la <H>Faille de l’Oubli</>.",
            ["DialogueId"] = 12015913,
            ["GUID"] = "1E14A0BA",
            ["NextDialogue"] = 12015914,
            ["RelatedWikiId"] = {
                [1] = 304008,
                },
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120159/1E14A0BA",
            },
        [12015914] = {
            ["Content"] = "往隙……那是什么？听你的语气好像很不妙！",
            ["ContentFR"] = "La Faille de l’Oubli... ?! Rien que le nom fait peur ! C’est quoi, exactement ?",
            ["DialogueId"] = 12015914,
            ["GUID"] = "1E14A0E4",
            ["NextDialogue"] = 12015915,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120159/1E14A0E4",
            },
        [12015915] = {
            ["Content"] = "倘若虞泉是由人的执念交织形成的彼界……那么虞泉受烛阴之灾影响，便生出往隙——令一切忘却消弭的无光之地。",
            ["ContentFR"] = "Si la Source de Yu est un monde tissé des attachements humains... alors, corrompue par le Fléau de Zhuyin, elle engendre la Faille de l’Oubli. Un lieu sans lumière, où souvenirs et conscience se dissolvent.",
            ["DialogueId"] = 12015915,
            ["GUID"] = "1E14A10E",
            ["NextDialogue"] = 12015916,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120159/1E14A10E",
            },
        [12015916] = {
            ["Content"] = "失足坠入的行者，若是没有在往隙生成后的一个时辰内及时返回，其魂魄就会永久迷失在其中，不得归途。",
            ["ContentFR"] = "Quiconque y chute doit en ressortir dans l’heure suivant son apparition. Passé ce délai... l’âme s’y perd à jamais, sans retour possible.",
            ["DialogueId"] = 12015916,
            ["GUID"] = "1E14A138",
            ["NextDialogue"] = 12015917,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120159/1E14A138",
            },
        [12015917] = {
            ["Content"] = "那……",
            ["ContentFR"] = "Alors... alors qu’est-ce qu’on fait ?!",
            ["DialogueId"] = 12015917,
            ["GUID"] = "1E14A162",
            ["NextDialogue"] = 12015918,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120159/1E14A162",
            },
        [12015918] = {
            ["Content"] = "不用心慌，我现在去带{性别：他|她}回来。你在原地等着我们。",
            ["ContentFR"] = "Ne panique pas. J’y vais maintenant pour {性别:le|la} ramener. Reste ici et attends-nous.",
            ["DialogueId"] = 12015918,
            ["GUID"] = "1E14A18C",
            ["NextDialogue"] = 12015919,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120159/1E14A18C",
            },
        [12015919] = {
            ["Content"] = "……白也要跟着一起去！",
            ["ContentFR"] = "... Je viens avec toi !",
            ["DialogueId"] = 12015919,
            ["GUID"] = "1E14A1B6",
            ["NextDialogue"] = 12015920,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120159/1E14A1B6",
            },
        [12015920] = {
            ["Content"] = "不行，往隙凶险异常。若是连你也陷于其中，事态只会更加失控。",
            ["ContentFR"] = "Non. La Faille est extrêmement dangereuse. Si toi aussi tu t’y perds, la situation deviendra incontrôlable.",
            ["DialogueId"] = 12015920,
            ["GUID"] = "1E14A1E0",
            ["NextDialogue"] = 12015921,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120159/1E14A1E0",
            },
        [12015921] = {
            ["Content"] = "但、但是，白只能在这里干等着，什么事情都做不了，也不知道里面是什么情况，小仆从到底怎么样了……",
            ["ContentFR"] = "Mais... mais rester ici à attendre, sans rien savoir... sans savoir comment va mon petit larbin... c’est insupportable...",
            ["DialogueId"] = 12015921,
            ["GUID"] = "1E14A20A",
            ["NextDialogue"] = 12015922,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120159/1E14A20A",
            },
        [12015922] = {
            ["Content"] = "呜，这种感觉……太难受了……",
            ["ContentFR"] = "<I>Bouhou...</> c’est trop dur...",
            ["DialogueId"] = 12015922,
            ["GUID"] = "1E14A234",
            ["NextDialogue"] = 12015923,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120159/1E14A234",
            },
        [12015923] = {
            ["Content"] = "小白，来，手给我。",
            ["ContentFR"] = "Snow... viens. Donne-moi la main.",
            ["DialogueId"] = 12015923,
            ["GUID"] = "1E14A25E",
            ["NextDialogue"] = 12015924,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120159/1E14A25E",
            },
        [12015924] = {
            ["Content"] = "这……这是……",
            ["ContentFR"] = "Hein ? C’est quoi, ça... ?",
            ["DialogueId"] = 12015924,
            ["GUID"] = "1E14A288",
            ["NextDialogue"] = 12015925,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120159/1E14A288",
            },
        [12015925] = {
            ["Content"] = "家姐说过，药苦的话，吃枚蜜饯就会甜起来。我想，心里苦也是一样的。",
            ["ContentFR"] = "Ma sœur disait toujours : « Quand un remède est amer, une douceur aide à le supporter. » Je pense que pour le cœur, c’est pareil.",
            ["DialogueId"] = 12015925,
            ["GUID"] = "1E14A2B2",
            ["NextDialogue"] = 12015926,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120159/1E14A2B2",
            },
        [12015926] = {
            ["Content"] = "别哭了，好吗？我一定会平安带着{性别：他|她}归来的，这是约定。",
            ["ContentFR"] = "Ne pleure plus, d’accord ? Je te promets de revenir avec {nickname}, {性别:sain et sauf|saine et sauve}. C’est une promesse.",
            ["DialogueId"] = 12015926,
            ["GUID"] = "1E14A2DC",
            ["NextDialogue"] = 12015927,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120159/1E14A2DC",
            },
        [12015927] = {
            ["Content"] = "那……你赶紧去吧！我帮你们盯着这个什么缝隙，让它不要一下子关上！",
            ["ContentFR"] = "A-alors... dépêche-toi ! Je surveille cette vilaine fissure ! Pas question qu’elle se referme !",
            ["DialogueId"] = 12015927,
            ["GUID"] = "1E14A306",
            ["NextDialogue"] = 12015928,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120159/1E14A306",
            },
        [12015928] = {
            ["Content"] = "整天说自己是什么魔王大人，结果连我的小仆从都护不住……",
            ["ContentFR"] = "Je passe mon temps à dire que je suis le Roi Démon... et je n’arrive même pas à protéger mon petit larbin...",
            ["DialogueId"] = 12015928,
            ["GUID"] = "1E14A330",
            ["NextDialogue"] = 12015929,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120159/1E14A330",
            },
        [12015929] = {
            ["Content"] = "坏东西，白看住你了，不许消失！",
            ["ContentFR"] = "Espèce de truc moche ! Je te surveille, alors ne bouge pas d’un poil !",
            ["DialogueId"] = 12015929,
            ["GUID"] = "1E14A35A",
            ["NextDialogue"] = 12015930,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120159/1E14A35A",
            },
        [12015930] = {
            ["Content"] = "笨蛋仆从，你一定要好好地回来哦！不然罚你给卡米拉打一年……不对，十年，一百年工！",
            ["ContentFR"] = "Et toi, imbécile de larbin... reviens-moi en pleine forme ! Sinon je te condamne à travailler pour Camilla pendant un an— non, dix— non, cent ans !",
            ["DialogueId"] = 12015930,
            ["GUID"] = "1E14A384",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120159/1E14A384",
            },
        [12016001] = {
            ["Content"] = "（这里是……哪里……）",
            ["ContentFR"] = "<I>Où suis-je... ?</>",
            ["DialogueId"] = 12016001,
            ["Duration"] = 2,
            ["GUID"] = "1E14AF2A",
            ["NextDialogue"] = 12016002,
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120160/1E14AF2A",
            },
        [12016002] = {
            ["Content"] = "（谁也不在，什么声音都没有，安静到只能听见自己的心跳声……）",
            ["ContentFR"] = "<I>Il n’y a personne. Aucun bruit. Un silence si profond que je n’entends plus que les battements de mon propre cœur...</>",
            ["DialogueId"] = 12016002,
            ["Duration"] = 3,
            ["GUID"] = "1E14AF54",
            ["NextDialogue"] = 12016003,
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120160/1E14AF54",
            },
        [12016003] = {
            ["Content"] = "（就像是……回到了白沙倾泻而下的原点，如同一切从未发生。）",
            ["ContentFR"] = "<I>Comme si j’étais revenu à l’origine même où le sable blanc s’écoule... comme si rien de tout cela n’avait jamais existé.</>",
            ["DialogueId"] = 12016003,
            ["Duration"] = 3,
            ["GUID"] = "1E14AF7E",
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120160/1E14AF7E",
            },
        [12016101] = {
            ["Content"] = "{nickname}，听得到我的声音吗？",
            ["ContentFR"] = "{nickname}... Est-ce que tu entends ma voix ?",
            ["DialogueId"] = 12016101,
            ["Duration"] = 3,
            ["GUID"] = "1E14BF92",
            ["NextDialogue"] = 12016102,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120161/1E14BF92",
            },
        [12016102] = {
            ["Content"] = "扶疏？是你吗，你在哪里？！",
            ["ContentFR"] = "Fushu ? C’est toi ? Où est-ce que tu te trouves ?!",
            ["DialogueId"] = 12016102,
            ["Duration"] = 2,
            ["GUID"] = "1E14BFBC",
            ["NextDialogue"] = 12016103,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120161/1E14BFBC",
            },
        [12016103] = {
            ["Content"] = "我所处的位置和你有一段间隔。但这里是特殊的场域，人与人的思绪在此处得以相通。因而我能够看到你，把声音传达过去。",
            ["ContentFR"] = "Il y a une distance entre nous. Mais cet endroit est un domaine particulier : ici, les pensées peuvent se rejoindre, au-delà des corps. C’est ainsi que je peux te voir... et te parler.",
            ["DialogueId"] = 12016103,
            ["Duration"] = 5,
            ["GUID"] = "1E14BFE6",
            ["NextDialogue"] = 12016104,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120161/1E14BFE6",
            },
        [12016104] = {
            ["Content"] = "不用担忧，已经没事了。接下来我会引导你离开这里，回到安全的地方。",
            ["ContentFR"] = "N’aie crainte. Tout va bien désormais. Je vais te guider hors d’ici, et te ramener vers un lieu sûr.",
            ["DialogueId"] = 12016104,
            ["Duration"] = 4,
            ["GUID"] = "1E14C010",
            ["NextDialogue"] = 12016105,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120161/1E14C010",
            },
        [12016105] = {
            ["Content"] = "……嗯，我明白了！",
            ["ContentFR"] = "... D’accord. Je comprends.",
            ["DialogueId"] = 12016105,
            ["Duration"] = 2,
            ["GUID"] = "1E14C03A",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120161/1E14C03A",
            },
        [12016201] = {
            ["Content"] = "看到那些灯花了吗？生者会将祈愿寄托于河灯之上，放入幽深的河水中，期望它们将思念载往亡者之域。",
            ["ContentFR"] = "Vois-tu ces Fleurs-lanternes ? Les vivants confient leurs prières à des lanternes flottantes, qu’ils laissent dériver sur des eaux profondes et silencieuses, dans l’espoir que leurs pensées atteignent le royaume des morts.",
            ["DialogueId"] = 12016201,
            ["Duration"] = 4,
            ["GUID"] = "1E14CFFA",
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120162/1E14CFFA",
            },
        [12016202] = {
            ["Content"] = "烛火的照耀可以护佑你，不受往隙的侵蚀。",
            ["ContentFR"] = "La lueur de ces flammes te protégera... et empêchera la Faille de l’Oubli de t’éroder.",
            ["DialogueId"] = 12016202,
            ["Duration"] = 3,
            ["GUID"] = "1E14D024",
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120162/1E14D024",
            },
        [12016251] = {
            ["Content"] = "扶疏，我应该怎么离开这里？",
            ["ContentFR"] = "Fushu... comment est-ce que je peux sortir d’ici ?",
            ["DialogueId"] = 12016251,
            ["Duration"] = 3,
            ["GUID"] = "1E14D026",
            ["NextDialogue"] = 12016303,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120162/1E14D026",
            },
        [12016301] = {
            ["Content"] = "小心身旁的河水。那是忘川，沾染到它会使人的存在逐渐淡薄，失去生之欲望。",
            ["ContentFR"] = "Prends garde à la rivière qui t’entoure. C’est le Fleuve de l’Oubli — celui qui efface l’existence. Si ses eaux te touchent, ton être s’amenuisera peu à peu... et ton désir de vivre s’éteindra.",
            ["DialogueId"] = 12016301,
            ["Duration"] = 3,
            ["GUID"] = "1E14E062",
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120163/1E14E062",
            },
        [12016302] = {
            ["Content"] = "……可是周围都是河水，没有路了。该怎么办？",
            ["ContentFR"] = "... Mais il n’y a que de l’eau autour de moi. Il n’y a plus de chemin. Que dois-je faire ?",
            ["DialogueId"] = 12016302,
            ["Duration"] = 3,
            ["GUID"] = "1E14E08C",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120163/1E14E08C",
            },
        [12016303] = {
            ["Content"] = "{nickname}，你有无论如何都要完成的心愿吗？",
            ["ContentFR"] = "{nickname}, existe-t-il un vœu que tu dois absolument accomplir, quoi qu’il arrive ?",
            ["DialogueId"] = 12016303,
            ["Duration"] = 3,
            ["GUID"] = "1E14E0B6",
            ["NextDialogue"] = 12016401,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120163/1E14E0B6",
            },
        [12016304] = {
            ["Content"] = "那就是你与此世的牵绊。对着前方的占风铎，默念你的心愿。",
            ["ContentFR"] = "C’est ce vœu qui te relie encore à ce monde. Fais face au Carillon des Vents devant toi... et murmure-le en silence.",
            ["DialogueId"] = 12016304,
            ["Duration"] = 3,
            ["GUID"] = "1E14E0E0",
            ["NextDialogue"] = 12016305,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120163/1E14E0E0",
            },
        [12016305] = {
            ["Content"] = "它会唤来风，将你的执念送往更高更远处，助你重返生者之界。",
            ["ContentFR"] = "Il appellera le vent, portera ton attachement vers des hauteurs lointaines... et t’aidera à regagner le monde des vivants.",
            ["DialogueId"] = 12016305,
            ["Duration"] = 3,
            ["GUID"] = "1E14E10A",
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120163/1E14E10A",
            },
        [12016401] = {
            ["Content"] = "（……无论如何都要去完成的事情。）",
            ["ContentFR"] = "<I>Quelque chose que je dois accomplir... coûte que coûte.</>",
            ["DialogueId"] = 12016401,
            ["Duration"] = 2,
            ["GUID"] = "1E14F0CA",
            ["NextDialogue"] = 12016402,
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120164/1E14F0CA",
            },
        [12016402] = {
            ["Content"] = "（贝蕾还在等着我……我要救出她，所以不能在这里止步！）",
            ["ContentFR"] = "<I>Berry m’attend encore... Je dois la sauver. Je ne peux pas m’arrêter ici.</>",
            ["DialogueId"] = 12016402,
            ["Duration"] = 3,
            ["GUID"] = "1E14F0F4",
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120164/1E14F0F4",
            },
        [12016501] = {
            ["Content"] = "……！灯亮起来了，好美。",
            ["ContentFR"] = "... Les lumières s’allument. C’est... magnifique.",
            ["DialogueId"] = 12016501,
            ["Duration"] = 2,
            ["GUID"] = "1E150132",
            ["NextDialogue"] = 12016502,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120165/1E150132",
            },
        [12016502] = {
            ["Content"] = "那些祈天灯的火焰，应当可以点燃灯花，帮你开辟新的道路。",
            ["ContentFR"] = "Les flammes des Lanternes célestes devraient pouvoir éveiller les Fleurs-lanternes... et ouvrir devant toi un nouveau passage.",
            ["DialogueId"] = 12016502,
            ["Duration"] = 3,
            ["GUID"] = "1E15015C",
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120165/1E15015C",
            },
        [12016601] = {
            ["Content"] = "{nickname}，是你吗？",
            ["ContentFR"] = "{nickname}... c’est toi ?",
            ["DialogueId"] = 12016601,
            ["Duration"] = 2,
            ["GUID"] = "1E15119A",
            ["NextDialogue"] = 12016602,
            ["SnapShot"] = "ECHO",
            ["SpeakNpcId"] = 210024,
            ["TalkActionId"] = {
                [1] = "210024:Explain01_Start",
                },
            ["TurnTo"] = {
                [1] = "210024:n(0)",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120166/1E15119A",
            },
        [12016602] = {
            ["Content"] = "……贝蕾！",
            ["ContentFR"] = "... Berry !",
            ["DialogueId"] = 12016602,
            ["Duration"] = 2,
            ["GUID"] = "1E1511C4",
            ["NextDialogue"] = 12016603,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "210024:Explain01_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120166/1E1511C4",
            },
        [12016603] = {
            ["Content"] = "我们一定能够再次相逢的。在那之前，照顾好自己，不要受伤。",
            ["ContentFR"] = "Nous nous reverrons. J’en suis certaine. D’ici là... prends soin de toi. Ne te blesse pas.",
            ["DialogueId"] = 12016603,
            ["Duration"] = 3,
            ["GUID"] = "1E1511EE",
            ["NextDialogue"] = 12016604,
            ["SnapShot"] = "ECHO",
            ["SpeakNpcId"] = 210024,
            ["TalkActionId"] = {
                [1] = "210024:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120166/1E1511EE",
            },
        [12016604] = {
            ["Content"] = "现在往前走吧，不要停下脚步。我会一直守望你的背影。",
            ["ContentFR"] = "Avance maintenant. Ne t’arrête pas. Je veillerai toujours sur ton chemin.",
            ["DialogueId"] = 12016604,
            ["Duration"] = 3,
            ["GUID"] = "1E151218",
            ["SnapShot"] = "ECHO",
            ["SpeakNpcId"] = 210024,
            ["TalkActionId"] = {
                [1] = "210024:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120166/1E151218",
            },
        [12016701] = {
            ["Content"] = "她就是你曾提及的“家人”吧。",
            ["ContentFR"] = "C’est elle... la « famille » dont tu m’as parlé.",
            ["DialogueId"] = 12016701,
            ["Duration"] = 2,
            ["GUID"] = "1E152202",
            ["NextDialogue"] = 12016702,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120167/1E152202",
            },
        [12016702] = {
            ["Content"] = "话虽扫兴……此处的她只是心愿和思念凝成的实体，并非真人。",
            ["ContentFR"] = "Je dois toutefois te prévenir : ce que tu viens de voir n’est qu’une forme née du vœu et du souvenir... pas la véritable personne.",
            ["DialogueId"] = 12016702,
            ["Duration"] = 3,
            ["GUID"] = "1E15222C",
            ["NextDialogue"] = 12016703,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120167/1E15222C",
            },
        [12016703] = {
            ["Content"] = "我明白的。",
            ["ContentFR"] = "Je le sais.",
            ["DialogueId"] = 12016703,
            ["Duration"] = 2,
            ["GUID"] = "1E152256",
            ["NextDialogue"] = 12016704,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120167/1E152256",
            },
        [12016704] = {
            ["Content"] = "就算如此，能在这里看到她，相信她还在世界上某个地方等我……我会安心许多。",
            ["ContentFR"] = "Même ainsi... la voir ici, croire qu’elle m’attend quelque part dans ce monde... ça m’apaise. Ça me donne la force d’avancer.",
            ["DialogueId"] = 12016704,
            ["Duration"] = 4,
            ["GUID"] = "1E152280",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120167/1E152280",
            },
        [12016801] = {
            ["Content"] = "又是新的占风铎。{nickname}，你知道该怎么做。",
            ["ContentFR"] = "Encore un Carillon des Vents. Tu sais ce qu’il te reste à faire, {nickname}.",
            ["DialogueId"] = 12016801,
            ["Duration"] = 3,
            ["GUID"] = "1E15326A",
            ["NextDialogue"] = 12016802,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120168/1E15326A",
            },
        [12016802] = {
            ["Content"] = "（我要平安回到冰湖城……大家还在等着我，我不能就此停下脚步！）",
            ["ContentFR"] = "<I>Je dois rentrer {性别:sain et sauf|saine et sauve} à Givrelac... Tout le monde m’y attend. Je ne peux pas m’arrêter maintenant.</>",
            ["DialogueId"] = 12016802,
            ["Duration"] = 3,
            ["GUID"] = "1E153294",
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120168/1E153294",
            },
        [12016901] = {
            ["Content"] = "好久不见，{nickname}。",
            ["ContentFR"] = "Ça fait longtemps, {nickname}.",
            ["DialogueId"] = 12016901,
            ["Duration"] = 2,
            ["GUID"] = "1E1542D2",
            ["NextDialogue"] = 12016902,
            ["SnapShot"] = "ECHO",
            ["SpeakNpcId"] = 210025,
            ["TalkActionId"] = {
                [1] = "210024:Explain02_Start",
                },
            ["TurnTo"] = {
                [1] = "210025:n(0)",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120169/1E1542D2",
            },
        [12016902] = {
            ["Content"] = "你是不是去了什么地方……一个我从未听过的、陌生又新鲜的地方？",
            ["ContentFR"] = "Tu es allé loin, n’est-ce pas ? Un endroit étrange, nouveau... que je ne connaîtrai sans doute jamais.",
            ["DialogueId"] = 12016902,
            ["Duration"] = 3,
            ["GUID"] = "1E1542FC",
            ["NextDialogue"] = 12016903,
            ["SnapShot"] = "ECHO",
            ["SpeakNpcId"] = 210025,
            ["TalkActionId"] = {
                [1] = "210024:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120169/1E1542FC",
            },
        [12016903] = {
            ["Content"] = "如果可以的话，等你什么时候回来冰湖城，可以讲给我听听吗？",
            ["ContentFR"] = "Quand tu reviendras à Givrelac... si tu en as envie... tu me raconteras ?",
            ["DialogueId"] = 12016903,
            ["Duration"] = 3,
            ["GUID"] = "1E154326",
            ["NextDialogue"] = 12016904,
            ["SnapShot"] = "ECHO",
            ["SpeakNpcId"] = 210025,
            ["TalkActionId"] = {
                [1] = "210024:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120169/1E154326",
            },
        [12016904] = {
            ["Content"] = "虽然这个愿望有点奢侈……可以的话，请不要忘记我。",
            ["ContentFR"] = "Je sais que c’est peut-être égoïste... mais s’il te plaît, ne m’oublie pas.",
            ["DialogueId"] = 12016904,
            ["GUID"] = "1E154350",
            ["SnapShot"] = "ECHO",
            ["SpeakNpcId"] = 210025,
            ["VoiceName"] = "voice/$Locale$/story/1201/120169/1E154350",
            },
        [12017001] = {
            ["Content"] = "小仆从，快跟上来，怎么这么慢！魔王大人还要带你一起去征服世界呢！",
            ["ContentFR"] = "Petit larbin ! Dépêche-toi ! Pourquoi tu traînes comme ça ? Le Roi Démon a encore un monde entier à conquérir avec toi !",
            ["DialogueId"] = 12017001,
            ["Duration"] = 4,
            ["GUID"] = "1E15533A",
            ["NextDialogue"] = 12017002,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 200002,
            ["SpeakNpcName"] = "UI_CMName_Name_BaiPhantom",
            ["VoiceName"] = "voice/$Locale$/story/1201/120170/1E15533A",
            },
        [12017002] = {
            ["Content"] = "到底去哪儿了，让我好找。快回来吧，菲娜还想听你给她讲故事。",
            ["ContentFR"] = "Où est-ce que tu t’es encore {性别:fourré|fourrée} ? Reviens vite... Fina attend toujours tes histoires.",
            ["DialogueId"] = 12017002,
            ["GUID"] = "1E155364",
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 100401,
            ["SpeakNpcName"] = "UI_CMName_Name_AotePhantom",
            ["VoiceName"] = "voice/$Locale$/story/1201/120170/1E155364",
            },
        [12017003] = {
            ["Content"] = "别在外面折断腿了。干完了活计就回水仙平原吧，我为你留了杯热饮，放凉了可就不好了。",
            ["ContentFR"] = "Ne va pas te casser une jambe dehors. Quand tu auras fini ton travail, rentre aux Asphodèles. Je t’ai gardé une boisson chaude — mais elle ne t’attendra pas éternellement.",
            ["DialogueId"] = 12017003,
            ["Duration"] = 3,
            ["GUID"] = "1E15538E",
            ["NextDialogue"] = 12017004,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 200003,
            ["SpeakNpcName"] = "UI_CMName_Name_KamiPhantom",
            ["VoiceName"] = "voice/$Locale$/story/1201/120170/1E15538E",
            },
        [12017004] = {
            ["Content"] = "挣钱固然重要。要是有命赚钱没命花，可就得不偿失了。",
            ["ContentFR"] = "Gagner sa vie, c’est important. Mais si on a l’argent sans le temps de le vivre... à quoi bon ?",
            ["DialogueId"] = 12017004,
            ["Duration"] = 3,
            ["GUID"] = "1E1553B8",
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 200003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120170/1E1553B8",
            },
        [12017005] = {
            ["Content"] = "看来，你有许多关心你、和你建立起牵绊的人……真好。",
            ["ContentFR"] = "On dirait que beaucoup de personnes tiennent à toi... que tu as tissé de nombreux liens. C’est une belle chose.",
            ["DialogueId"] = 12017005,
            ["Duration"] = 3,
            ["GUID"] = "1E1553E2",
            ["NextDialogue"] = 12017006,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120170/1E1553E2",
            },
        [12017006] = {
            ["Content"] = "出路就在前方了。趟过忘川，踏上眼前的奈何桥，它会渡你回彼岸。",
            ["ContentFR"] = "La sortie est juste devant. Traverse le Fleuve de l’Oubli... puis emprunte le Pont du Retour. Il te ramènera sur l’autre rive.",
            ["DialogueId"] = 12017006,
            ["GUID"] = "1E15540C",
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120170/1E15540C",
            },
        [12017101] = {
            ["Content"] = "……呼，{nickname}平安无虞了。",
            ["ContentFR"] = "... Ouf. {nickname} est {性别:sain et sauf|saine et sauve}.",
            ["DialogueId"] = 12017101,
            ["Duration"] = 3,
            ["GUID"] = "1E1563A2",
            ["NextDialogue"] = 12017102,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120171/1E1563A2",
            },
        [12017102] = {
            ["Content"] = "往隙与此世的联系正在逐渐关闭……得抓紧出去了。",
            ["ContentFR"] = "Le lien entre la Faille de l’Oubli et ce monde est en train de se refermer... je dois sortir au plus vite.",
            ["DialogueId"] = 12017102,
            ["Duration"] = 3,
            ["GUID"] = "1E1563CC",
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120171/1E1563CC",
            },
        [12017201] = {
            ["Content"] = "咿咿呀——",
            ["ContentFR"] = "Yi.... ya...",
            ["DialogueId"] = 12017201,
            ["GUID"] = "1E15740A",
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210017,
            ["VoiceName"] = "voice/$Locale$/story/1201/120172/1E15740A",
            },
        [12017202] = {
            ["Content"] = "小家伙，你怎么在这里……？",
            ["ContentFR"] = "Petit être... que fais-tu ici... ?",
            ["DialogueId"] = 12017202,
            ["GUID"] = "1E157434",
            ["NextDialogue"] = 12017203,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120172/1E157434",
            },
        [12017203] = {
            ["Content"] = "咿呀，咿！",
            ["ContentFR"] = "Yi-ya... yi !",
            ["DialogueId"] = 12017203,
            ["GUID"] = "1E15745E",
            ["NextDialogue"] = 12017204,
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210017,
            ["VoiceName"] = "voice/$Locale$/story/1201/120172/1E15745E",
            },
        [12017204] = {
            ["Content"] = "……被此界侵染太久，已经失去说话的能力了吗？真可怜。",
            ["ContentFR"] = "... Être resté trop longtemps dans ce monde t’a privé de la parole... le pauvre.",
            ["DialogueId"] = 12017204,
            ["GUID"] = "1E157488",
            ["NextDialogue"] = 12017205,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120172/1E157488",
            },
        [12017205] = {
            ["Content"] = "跟紧我，我也会将你带至安全的地方。",
            ["ContentFR"] = "Reste près de moi. Je te conduirai, toi aussi, en lieu sûr.",
            ["DialogueId"] = 12017205,
            ["GUID"] = "1E1574B2",
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120172/1E1574B2",
            },
        [12017206] = {
            ["Content"] = "咿！",
            ["ContentFR"] = "Yi !",
            ["DialogueId"] = 12017206,
            ["GUID"] = "1E1574DC",
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210017,
            ["VoiceName"] = "voice/$Locale$/story/1201/120172/1E1574DC",
            },
        [12017301] = {
            ["Content"] = "（扶疏平生所愿，仅有以枯荣之术渡尽天下苍生。唯有此誓，不敢悖离。）",
            ["ContentFR"] = "<I>Le seul vœu de toute ma vie fut d’user de l’Art de l’Éphémère pour sauver les êtres. Ce serment — jamais je n’ai osé le trahir.</>",
            ["DialogueId"] = 12017301,
            ["Duration"] = 3,
            ["GUID"] = "1E158472",
            ["NextDialogue"] = 12017302,
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120173/1E158472",
            },
        [12017302] = {
            ["Content"] = "烛火的颜色，有些不对劲……",
            ["ContentFR"] = "La couleur de la flamme, elle n’est pas normale...",
            ["DialogueId"] = 12017302,
            ["Duration"] = 2,
            ["GUID"] = "1E15849C",
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120173/1E15849C",
            },
        [12017401] = {
            ["Content"] = "我好痛啊……我的疮口在流脓，痛到彻夜难眠……",
            ["ContentFR"] = "J’ai si mal... mes plaies suppurent... la douleur m’empêche de dormir, nuit après nuit..",
            ["DialogueId"] = 12017401,
            ["Duration"] = 2,
            ["GUID"] = "1E1594DA",
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcName"] = "UI_CMName_Name_HuanzhePhantom",
            ["VoiceName"] = "voice/$Locale$/story/1201/120174/1E1594DA",
            },
        [12017402] = {
            ["Content"] = "我……已经没有活路了吧。祝由大人，给我一个了断吧……",
            ["ContentFR"] = "Je n’ai plus d’issue, n’est-ce pas... Dame Zhuyou... accordez-moi une fin...",
            ["DialogueId"] = 12017402,
            ["Duration"] = 3,
            ["GUID"] = "1E159504",
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcName"] = "UI_CMName_Name_HuanzhePhantom",
            ["VoiceName"] = "voice/$Locale$/story/1201/120174/1E159504",
            },
        [12017403] = {
            ["Content"] = "我的孩儿刚出生，她都还没有开口唤过一声“阿娘”啊！求求您，救救她，救救她！",
            ["ContentFR"] = "Mon enfant vient de naître... elle n’a même pas encore appelé « maman » une seule fois ! Je vous en supplie — sauvez-la ! Sauvez-la !",
            ["DialogueId"] = 12017403,
            ["Duration"] = 3,
            ["GUID"] = "1E15952E",
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcName"] = "UI_CMName_Name_HuanzhePhantom",
            ["VoiceName"] = "voice/$Locale$/story/1201/120174/1E15952E",
            },
        [12017404] = {
            ["Content"] = "传闻中的扶氏不是手到病除吗？快治啊，莫非你不愿出力？",
            ["ContentFR"] = "On dit que les Fushu guérissent tout d’un geste ! Alors pourquoi hésites-tu ? Tu refuses d’aider ?!",
            ["DialogueId"] = 12017404,
            ["Duration"] = 4,
            ["GUID"] = "1E159558",
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcName"] = "UI_CMName_Name_HuanzhePhantom",
            ["VoiceName"] = "voice/$Locale$/story/1201/120174/1E159558",
            },
        [12017405] = {
            ["Content"] = "那是……百年之前的大疫。",
            ["ContentFR"] = "... C’était la Grande Épidémie d’il y a cent ans.",
            ["DialogueId"] = 12017405,
            ["Duration"] = 1,
            ["GUID"] = "1E159582",
            ["GuideFacialId"] = "Sad",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 12017406,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120174/1E159582",
            },
        [12017406] = {
            ["Content"] = "我四处奔走，精疲力尽，却只能眼睁睁地看着患者在绝望苦痛中死去。",
            ["ContentFR"] = "Je courais sans relâche, jusqu’à l’épuisement... Et malgré tout, je ne pouvais que regarder les malades mourir — consumés par la douleur et le désespoir.",
            ["DialogueId"] = 12017406,
            ["Duration"] = 3,
            ["GUID"] = "1E1595AC",
            ["GuideFacialId"] = "Sad",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120174/1E1595AC",
            },
        [12017407] = {
            ["Content"] = "（烛火的回应……原来我的内心早有动摇吗？）",
            ["ContentFR"] = "<I>La réaction de la flamme... Alors mon cœur vacillait déjà à cette époque...</>",
            ["DialogueId"] = 12017407,
            ["Duration"] = 2,
            ["GUID"] = "1E1595D6",
            ["NextDialogue"] = 12017501,
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120174/1E1595D6",
            },
        [12017501] = {
            ["Content"] = "（我所牵挂的，不止是被病痛折磨的人们吗？）",
            ["ContentFR"] = "<I>Ce qui me hante... n’est-ce vraiment que la souffrance des autres ?</>",
            ["DialogueId"] = 12017501,
            ["Duration"] = 3,
            ["GUID"] = "1E15A542",
            ["NextDialogue"] = 12017502,
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120175/1E15A542",
            },
        [12017502] = {
            ["Content"] = "（但我平生所学，所践行，唯有枯荣之术。若是心不静了，我又该如何走出此地……）",
            ["ContentFR"] = "Tout ce que j’ai appris, tout ce que j’ai pratiqué, n’a toujours été que l’Art de l’Éphémère. Si mon cœur n’est plus en paix... comment pourrais-je quitter cet endroit...",
            ["DialogueId"] = 12017502,
            ["Duration"] = 4,
            ["GUID"] = "1E15A56C",
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120175/1E15A56C",
            },
        [12017601] = {
            ["Content"] = "……不出所料。",
            ["ContentFR"] = "... Comme je m’y attendais.",
            ["DialogueId"] = 12017601,
            ["Duration"] = 1,
            ["GUID"] = "1E15B5AA",
            ["GuideFacialId"] = "Confident",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 12017602,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120176/1E15B5AA",
            },
        [12017602] = {
            ["Content"] = "抱歉，说了带你出去，看来要食言了。",
            ["ContentFR"] = "Pardonne-moi. Je t’avais promis de te mener hors d’ici... Il semble que je ne pourrai pas tenir parole.",
            ["DialogueId"] = 12017602,
            ["Duration"] = 2,
            ["GUID"] = "1E15B5D4",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120176/1E15B5D4",
            },
        [12017701] = {
            ["Content"] = "咿呀，咿咿呀，咿！",
            ["ContentFR"] = "Yi—ya... yi-yi—ya... yi !",
            ["DialogueId"] = 12017701,
            ["Duration"] = 1,
            ["GUID"] = "1E15C612",
            ["NextDialogue"] = 12017702,
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210017,
            ["VoiceName"] = "voice/$Locale$/story/1201/120177/1E15C612",
            },
        [12017702] = {
            ["Content"] = "……！你将自己作为燃料吗？这样下去，你会彻底消散无形……",
            ["ContentFR"] = "... ! Tu te consumes comme combustible ? Si tu continues... tu disparaîtras entièrement, sans laisser de trace...",
            ["DialogueId"] = 12017702,
            ["Duration"] = 3,
            ["GUID"] = "1E15C63C",
            ["NextDialogue"] = 12017703,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120177/1E15C63C",
            },
        [12017703] = {
            ["Content"] = "咿！",
            ["ContentFR"] = "Yi !",
            ["DialogueId"] = 12017703,
            ["Duration"] = 1,
            ["GUID"] = "1E15C666",
            ["NextDialogue"] = 12017704,
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210017,
            ["VoiceName"] = "voice/$Locale$/story/1201/120177/1E15C666",
            },
        [12017704] = {
            ["Content"] = "……我明白了，我会尽力护佑你。",
            ["ContentFR"] = "... J’ai compris. Je ferai tout pour te protéger.",
            ["DialogueId"] = 12017704,
            ["Duration"] = 2,
            ["GUID"] = "1E15C690",
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120177/1E15C690",
            },
        [12017801] = {
            ["Content"] = "扶疏，我听闻你救治别人时倒下，千里迢迢赶回来看你……你不能继续使用枯荣之术了。",
            ["ContentFR"] = "Fushu... j’ai appris que tu t’étais effondrée en soignant des malades. J’ai traversé mille lieues pour te voir... Tu dois arrêter l’Art de l’Éphémère.",
            ["DialogueId"] = 12017801,
            ["GUID"] = "1E15D67A",
            ["NextDialogue"] = 12017802,
            ["SnapShot"] = "ECHO",
            ["SpeakNpcId"] = 210028,
            ["VoiceName"] = "voice/$Locale$/story/1201/120178/1E15D67A",
            },
        [12017802] = {
            ["Content"] = "多谢关心。我已经无恙，姐姐请回吧。",
            ["ContentFR"] = "Merci de t’inquiéter pour moi. Je vais bien désormais. S’il te plaît, rentre chez toi, grande sœur.",
            ["DialogueId"] = 12017802,
            ["GUID"] = "1E15D6A4",
            ["NextDialogue"] = 12017803,
            ["SnapShot"] = "ECHO",
            ["SpeakNpcId"] = 210029,
            ["VoiceName"] = "voice/$Locale$/story/1201/120178/1E15D6A4",
            },
        [12017803] = {
            ["Content"] = "无恙？！如此不爱惜自己，真要连性命都丢了才罢休吗？",
            ["ContentFR"] = "« Bien » ?! Tu te détruis toi-même — attends-tu vraiment de perdre la vie pour t’arrêter ?",
            ["DialogueId"] = 12017803,
            ["GUID"] = "1E15D6CE",
            ["NextDialogue"] = 12017804,
            ["SnapShot"] = "ECHO",
            ["SpeakNpcId"] = 210028,
            ["VoiceName"] = "voice/$Locale$/story/1201/120178/1E15D6CE",
            },
        [12017804] = {
            ["Content"] = "救治苍生本就是大风九章赋予扶氏的使命。你要我看人们受病痛煎熬，却置若罔闻吗？",
            ["ContentFR"] = "Sauver les êtres est la mission que les Neuf Chapitres de Dafeng ont confiée à notre lignée. Devrais-je détourner le regard pendant que les gens souffrent ?",
            ["DialogueId"] = 12017804,
            ["GUID"] = "1E15D6F8",
            ["NextDialogue"] = 12017805,
            ["SnapShot"] = "ECHO",
            ["SpeakNpcId"] = 210029,
            ["VoiceName"] = "voice/$Locale$/story/1201/120178/1E15D6F8",
            },
        [12017805] = {
            ["Content"] = "若不是姐姐当初执意要去研究什么<H>药理</>，弃家传枯荣术于不顾，我又何苦将自己逼至此境地？",
            ["ContentFR"] = "Si tu n’avais pas insisté pour abandonner l’art ancestral au profit de la <H>médecine des remèdes</>, aurais-je seulement été contrainte de me pousser à une telle extrémité ?",
            ["DialogueId"] = 12017805,
            ["GUID"] = "1E15D722",
            ["NextDialogue"] = 12017806,
            ["SnapShot"] = "ECHO",
            ["SpeakNpcId"] = 210029,
            ["VoiceName"] = "voice/$Locale$/story/1201/120178/1E15D722",
            },
        [12017806] = {
            ["Content"] = "恕我做不到像姐姐一般惜命。",
            ["ContentFR"] = "Pardonne-moi... mais je ne peux pas chérir ma propre vie comme tu le fais.",
            ["DialogueId"] = 12017806,
            ["GUID"] = "1E15D74C",
            ["NextDialogue"] = 12017901,
            ["SnapShot"] = "ECHO",
            ["SpeakNpcId"] = 210029,
            ["VoiceName"] = "voice/$Locale$/story/1201/120178/1E15D74C",
            },
        [12017901] = {
            ["Content"] = "……扶疏。原来，你心中一直是这般想我。",
            ["ContentFR"] = "... Fushu. Ainsi, voilà ce que tu pensais de moi.",
            ["DialogueId"] = 12017901,
            ["Duration"] = 2,
            ["GUID"] = "1E15E6E2",
            ["SnapShot"] = "ECHO",
            ["SpeakNpcId"] = 210028,
            ["VoiceName"] = "voice/$Locale$/story/1201/120179/1E15E6E2",
            },
        [12017902] = {
            ["Content"] = "（那些话并非我本意。但我一开口，恶语竟如泉涌，滔滔而出。）",
            ["ContentFR"] = "<I>Ces paroles n’étaient pas ce que je voulais dire. Mais une fois prononcées, elles ont jailli — cruelles, incontrôlables.</>",
            ["DialogueId"] = 12017902,
            ["Duration"] = 3,
            ["GUID"] = "1E15E70C",
            ["NextDialogue"] = 12017903,
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120179/1E15E70C",
            },
        [12017903] = {
            ["Content"] = "（最后，我不知如何面对姐姐，夺路而逃。那也是我与姐姐的最后一次交谈。）",
            ["ContentFR"] = "<I>Je n’ai pas su lui faire face. J’ai fui. Ce fut notre dernière conversation.</>",
            ["DialogueId"] = 12017903,
            ["Duration"] = 3,
            ["GUID"] = "1E15E736",
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120179/1E15E736",
            },
        [12018001] = {
            ["Camera"] = "-361.291565,868.035156,176.938965,0.000062,-2.401447,-174.821503,35.0,506.121063,false,Manual,2.8",
            ["Content"] = "扶疏……你正当英年，姐姐不允许你就这般离世……",
            ["ContentFR"] = "Fushu... tu es encore jeune. Je ne te laisserai pas mourir ainsi.",
            ["DialogueId"] = 12018001,
            ["Duration"] = 3,
            ["GUID"] = "1E15F74A",
            ["NextDialogue"] = 12018002,
            ["SnapShot"] = "ECHO",
            ["SpeakNpcId"] = 210028,
            ["VoiceName"] = "voice/$Locale$/story/1201/120180/1E15F74A",
            },
        }
  end },
  { MinKey = 12018002, MaxKey = 12019814, Loader = function()
      return {
        [12018002] = {
            ["Content"] = "我定会研制出能救你的药物，就算耗尽余生也在所不惜……等着我。",
            ["ContentFR"] = "Je créerai un remède pour te sauver. Même si cela me coûte le reste de ma vie... je le ferai. Attends-moi.",
            ["DialogueId"] = 12018002,
            ["Duration"] = 2,
            ["GUID"] = "1E15F774",
            ["SnapShot"] = "ECHO",
            ["SpeakNpcId"] = 210028,
            ["VoiceName"] = "voice/$Locale$/story/1201/120180/1E15F774",
            },
        [12018003] = {
            ["Content"] = "…………",
            ["ContentFR"] = "...",
            ["DialogueId"] = 12018003,
            ["GUID"] = "1E15F775",
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120180/1E15F775",
            },
        [12018004] = {
            ["DialogueId"] = 12018004,
            ["GUID"] = "1E15F776",
            },
        [12018101] = {
            ["Content"] = "……姐姐……",
            ["ContentFR"] = "... Grande sœur...",
            ["DialogueId"] = 12018101,
            ["Duration"] = 2,
            ["GUID"] = "1E1607B2",
            ["GuideFacialId"] = "Sad",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 12018102,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120181/1E1607B2",
            },
        [12018102] = {
            ["Content"] = "姐姐曾以至诚之心待我，我却未能珍视其意。",
            ["ContentFR"] = "Elle m’a toujours offert son cœur avec sincérité... Et je n’ai pas su en reconnaître la valeur.",
            ["DialogueId"] = 12018102,
            ["Duration"] = 3,
            ["GUID"] = "1E1607DC",
            ["GuideFacialId"] = "Sad",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 12018103,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120181/1E1607DC",
            },
        [12018103] = {
            ["Content"] = "我想和姐姐再见一面……哪怕只是说一句“对不起”……",
            ["ContentFR"] = "Je voudrais la revoir une fois encore... Ne serait-ce que pour lui dire « pardon »...",
            ["DialogueId"] = 12018103,
            ["Duration"] = 2,
            ["GUID"] = "1E160806",
            ["GuideFacialId"] = "Sad",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120181/1E160806",
            },
        [12018201] = {
            ["Content"] = "咿！咿！",
            ["ContentFR"] = "Yi ! Yi !",
            ["DialogueId"] = 12018201,
            ["Duration"] = 1,
            ["GUID"] = "1E16181A",
            ["SpeakNpcId"] = 210017,
            ["SpeakNpcName"] = "UI_CMName_Name_WuyouWuyan",
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E16181A",
            },
        [12018202] = {
            ["Content"] = "扶疏！我还以为你……",
            ["ContentFR"] = "Fushu ! J’ai cru que tu...",
            ["DialogueId"] = 12018202,
            ["GUID"] = "1E161844",
            ["NextDialogue"] = 12018203,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E161844",
            },
        [12018203] = {
            ["Content"] = "抱歉，使你担心了。",
            ["ContentFR"] = "Pardonne-moi de t’avoir inquiété.",
            ["DialogueId"] = 12018203,
            ["GUID"] = "1E16186E",
            ["NextDialogue"] = 12018204,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E16186E",
            },
        [12018204] = {
            ["Content"] = "多亏了这位不知名无由生的帮助，我才未在往隙中迷失。渡人亦是渡己，古语诚不欺我……",
            ["ContentFR"] = "C’est grâce à l’aide de ce Wishen sans nom que je ne me suis pas égarée dans la Faille de l’Oubli. Sauver autrui, c’est aussi se sauver soi-même... Les anciens ne mentaient donc pas.",
            ["DialogueId"] = 12018204,
            ["GUID"] = "1E161898",
            ["NextDialogue"] = 12018205,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E161898",
            },
        [12018205] = {
            ["Content"] = "咿，咿呀咿，咿！",
            ["ContentFR"] = "Yi ! Yi-ya-yi !",
            ["DialogueId"] = 12018205,
            ["GUID"] = "1E1618C2",
            ["NextDialogue"] = 12018206,
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210017,
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E1618C2",
            },
        [12018206] = {
            ["Content"] = "太好了。能与你会合，我就放心了许多。",
            ["ContentFR"] = "Tant mieux... Te retrouver saine et sauve me rassure vraiment.",
            ["DialogueId"] = 12018206,
            ["GUID"] = "1E1618EC",
            ["NextDialogue"] = 12018207,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E1618EC",
            },
        [12018207] = {
            ["Content"] = "我们现在尚未脱离险境。虽已走出了最凶险的地带，但还不能松懈。随我尽早离开这里，回到此世吧。",
            ["ContentFR"] = "Nous ne sommes pas encore hors de danger. Le pire est derrière nous, mais ce n’est pas le moment de relâcher notre vigilance. Viens — quittons cet endroit au plus vite et regagnons ce monde.",
            ["DialogueId"] = 12018207,
            ["GUID"] = "1E161916",
            ["NextDialogue"] = 12018208,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E161916",
            },
        [12018208] = {
            ["Content"] = "嗯，我明白了！",
            ["ContentFR"] = "Oui. Je te suis.",
            ["DialogueId"] = 12018208,
            ["GUID"] = "1E161940",
            ["NextDialogue"] = 12018209,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E161940",
            },
        [12018209] = {
            ["Content"] = "先顺着这些辉玉前行吧，它们会指引生路的方向。",
            ["ContentFR"] = "Suis ces Jades lumineux. Ils indiquent la voie du retour.",
            ["DialogueId"] = 12018209,
            ["GUID"] = "1E16196A",
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E16196A",
            },
        [12018210] = {
            ["Content"] = "扶疏，你刚刚在忘川中看见了什么？",
            ["ContentFR"] = "Fushu... tout à l’heure, dans le Fleuve de l’Oubli... qu’as-tu vu ?",
            ["DialogueId"] = 12018210,
            ["GUID"] = "1E161994",
            ["NextDialogue"] = 12018211,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E161994",
            },
        [12018211] = {
            ["Content"] = "只是一些过往的人事物……都已随时间故去了。",
            ["ContentFR"] = "Des fragments du passé. Des visages, des instants déjà emportés par le temps.",
            ["DialogueId"] = 12018211,
            ["GUID"] = "1E1619BE",
            ["NextDialogue"] = 12018212,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E1619BE",
            },
        [12018212] = {
            ["Content"] = "看来并不是什么愉快的回忆……",
            ["ContentFR"] = "Ce n’étaient pas de bons souvenirs, on dirait...",
            ["DialogueId"] = 12018212,
            ["GUID"] = "1E1619E8",
            ["NextDialogue"] = 12018213,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E1619E8",
            },
        [12018213] = {
            ["Content"] = "救命——",
            ["ContentFR"] = "À l’aide— !",
            ["DialogueId"] = 12018213,
            ["GUID"] = "1E161A12",
            ["NextDialogue"] = 12018214,
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210017,
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E161A12",
            },
        [12018214] = {
            ["Content"] = "咿呀，咿！",
            ["ContentFR"] = "Yi-ya ! Yi !",
            ["DialogueId"] = 12018214,
            ["GUID"] = "1E161A3C",
            ["NextDialogue"] = 12018215,
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210017,
            ["SpeakNpcName"] = "UI_CMName_Name_WuyouWuyan",
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E161A3C",
            },
        [12018215] = {
            ["Content"] = "那边好像有求救的声音，我们赶紧过去看看！",
            ["ContentFR"] = "J’ai entendu un appel ! Allons voir !",
            ["DialogueId"] = 12018215,
            ["GUID"] = "1E161A66",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E161A66",
            },
        [12018216] = {
            ["Content"] = "谢谢，好心人！",
            ["ContentFR"] = "Merci... merci, âme bienveillante !",
            ["DialogueId"] = 12018216,
            ["GUID"] = "1E161A90",
            ["NextDialogue"] = 12018217,
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210017,
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E161A90",
            },
        [12018217] = {
            ["Content"] = "还有，更多的，同伴，散落了。",
            ["ContentFR"] = "D’autres... d’autres compagnons sont encore dispersés...",
            ["DialogueId"] = 12018217,
            ["GUID"] = "1E161ABA",
            ["NextDialogue"] = 12018218,
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210017,
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E161ABA",
            },
        [12018218] = {
            ["Content"] = "这个地方，不好，赶紧逃出去。离开这里，需要，大家的力量！",
            ["ContentFR"] = "Cet endroit est mauvais. Il faut partir. Pour s’enfuir... il faut unir nos forces !",
            ["DialogueId"] = 12018218,
            ["GUID"] = "1E161AE4",
            ["NextDialogue"] = 12018219,
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210017,
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E161AE4",
            },
        [12018219] = {
            ["Content"] = "还有更多的无由生被困在这里吗？我明白了，我会留意的。",
            ["ContentFR"] = "Il y a donc encore des Wishen prisonniers... D’accord. Je resterai attentif.",
            ["DialogueId"] = 12018219,
            ["GUID"] = "1E161B0E",
            ["NextDialogue"] = 12018220,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E161B0E",
            },
        [12018220] = {
            ["Content"] = "谢谢，谢谢！力量，借给你！",
            ["ContentFR"] = "Merci ! Merci ! Prends... ma force !",
            ["DialogueId"] = 12018220,
            ["GUID"] = "1E161B38",
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210017,
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E161B38",
            },
        [12018221] = {
            ["Content"] = "黯淡的石头，力量，发光！",
            ["ContentFR"] = "Pierres ternes... avec la force... briller !",
            ["DialogueId"] = 12018221,
            ["GUID"] = "1E161B62",
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210017,
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E161B62",
            },
        [12018222] = {
            ["Content"] = "前方的路被荆棘挡住了……",
            ["ContentFR"] = "Le passage est bloqué...",
            ["DialogueId"] = 12018222,
            ["GUID"] = "1E161B8C",
            ["NextDialogue"] = 12018223,
            ["SpeakNpcId"] = 100001,
            },
        [12018223] = {
            ["Content"] = "观察一下附近吧，或许有什么玄机。",
            ["ContentFR"] = "Observons les alentours. Il doit y avoir un mécanisme dissimulé.",
            ["DialogueId"] = 12018223,
            ["GUID"] = "1E161BB6",
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E161BB6",
            },
        [12018224] = {
            ["Content"] = "黯淡的石头，同时，发光！",
            ["ContentFR"] = "Pierres ternes... toutes... briller ensemble !",
            ["DialogueId"] = 12018224,
            ["GUID"] = "1E161BE0",
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210017,
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E161BE0",
            },
        [12018225] = {
            ["Content"] = "哇啊……！是祝由大人，还有陌生的人类！",
            ["ContentFR"] = "Ouah... ! Dame Zhuyou ! Et... {性别:un humain inconnu|une humaine inconnue} !",
            ["DialogueId"] = 12018225,
            ["GUID"] = "1E161C0A",
            ["NextDialogue"] = 12018226,
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210017,
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E161C0A",
            },
        [12018226] = {
            ["Content"] = "看着回到虞泉的出口，好远好远。不知不觉就泄气，走不动路了……",
            ["ContentFR"] = "La sortie vers la Source de Yu semble si loin. Je suis épuisé... je n’arrive plus à avancer...",
            ["DialogueId"] = 12018226,
            ["GUID"] = "1E161C34",
            ["NextDialogue"] = 12018227,
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210017,
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E161C34",
            },
        [12018227] = {
            ["Content"] = "好像在这里一觉睡过去，忘记一切，就此消失也无所谓了……",
            ["ContentFR"] = "Parfois, j’ai envie de m’endormir ici... D’oublier... et de disparaître...",
            ["DialogueId"] = 12018227,
            ["GUID"] = "1E161C5E",
            ["NextDialogue"] = 12018228,
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210017,
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E161C5E",
            },
        [12018228] = {
            ["Content"] = "但是，既然同伴来了，就应当迈开脚步继续向前了吧！",
            ["ContentFR"] = "Mais puisque nos compagnons sont là, nous devons continuer à marcher !",
            ["DialogueId"] = 12018228,
            ["GUID"] = "1E161C88",
            ["NextDialogue"] = 12018229,
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210017,
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E161C88",
            },
        [12018229] = {
            ["Content"] = "在忘川中跋涉了许久，是否觉得灵魂有些沉重呢？我来减轻你们的负担，让你们身轻如燕吧！",
            ["ContentFR"] = "Vous avez longtemps foulé le Fleuve de l’Oubli... Vos âmes sont lourdes, n’est-ce pas ? Laisse-moi les alléger — vous serez légers comme le vent !",
            ["DialogueId"] = 12018229,
            ["GUID"] = "1E161CB2",
            ["NextDialogue"] = 12018230,
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210017,
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E161CB2",
            },
        [12018230] = {
            ["Content"] = "那，我来帮你们扫清远处的障碍，让你们的行动更加灵活！",
            ["ContentFR"] = "Et moi, je balaierai les obstacles devant vous ! Vous avancerez sans entrave !",
            ["DialogueId"] = 12018230,
            ["GUID"] = "1E161CDC",
            ["NextDialogue"] = 12018231,
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210017,
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E161CDC",
            },
        [12018231] = {
            ["Content"] = "咿，咿呀！这下完全没问题了，我们赶紧出发吧！",
            ["ContentFR"] = "Yi-ya ! Parfait ! En route !",
            ["DialogueId"] = 12018231,
            ["GUID"] = "1E161D06",
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210017,
            ["SpeakNpcName"] = "UI_Npc_Name_WuyoushengA&B",
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E161D06",
            },
        [12018232] = {
            ["Content"] = "咿咿，呀！",
            ["ContentFR"] = "Yi-ya ! Ya !",
            ["DialogueId"] = 12018232,
            ["GUID"] = "1E161D30",
            ["NextDialogue"] = 12018233,
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210017,
            ["SpeakNpcName"] = "UI_Npc_Name_WuyoushengShoukun",
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E161D30",
            },
        [12018233] = {
            ["Content"] = "坏花困住了同伴，赶紧去帮忙！",
            ["ContentFR"] = "Les mauvaises fleurs ont capturé nos amis ! Aidez-les !",
            ["DialogueId"] = 12018233,
            ["GUID"] = "1E161D5A",
            ["NextDialogue"] = 12018234,
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210017,
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E161D5A",
            },
        [12018234] = {
            ["Content"] = "我在古籍上见过此种异花。当其花瓣闭合时，刀枪难入，只能等候其绽开的时机。",
            ["ContentFR"] = "J’ai déjà vu ce type de fleur dans les anciens écrits. Lorsque ses pétales sont fermés, rien ne peut les entamer. Il faut attendre le moment où elle s’ouvrira.",
            ["DialogueId"] = 12018234,
            ["GUID"] = "1E161D84",
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E161D84",
            },
        [12018235] = {
            ["Content"] = "花蕊暴露在外了，就趁现在！",
            ["ContentFR"] = "Le cœur est à découvert — maintenant !",
            ["DialogueId"] = 12018235,
            ["GUID"] = "1E161DAE",
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E161DAE",
            },
        [12018236] = {
            ["Content"] = "祝由大人，还有没见过的白发勇者，谢谢你们！",
            ["ContentFR"] = "Dame Zhuyou ! Et {性别:le vaillant guerrier|la vaillante guerrière} aux cheveux blancs ! Merci !",
            ["DialogueId"] = 12018236,
            ["GUID"] = "1E161DD8",
            ["NextDialogue"] = 12018237,
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcName"] = "UI_Npc_Name_WuyoushengShoukun",
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E161DD8",
            },
        [12018237] = {
            ["Content"] = "俺也来助你们一臂之力！俺的铁头槌，连大地都能砸的梆梆作响哟！",
            ["ContentFR"] = "Je viens aussi prêter main-forte ! Mon coup de tête d’acier peut fendre la terre !",
            ["DialogueId"] = 12018237,
            ["GUID"] = "1E161E02",
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcName"] = "UI_Npc_Name_WuyoushengShoukun",
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E161E02",
            },
        [12018238] = {
            ["Content"] = "最后的同伴，最后的同伴！",
            ["ContentFR"] = "Les derniers compagnons ! Les derniers !",
            ["DialogueId"] = 12018238,
            ["GUID"] = "1E161E2C",
            ["NextDialogue"] = 12018239,
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcName"] = "UI_Npc_Name_WuyoushengA",
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E161E2C",
            },
        [12018239] = {
            ["Content"] = "还是先前那种异花。{nickname}，趁其绽开的时机，将花蕊连着枝蔓一举荡清吧。",
            ["ContentFR"] = "Encore cette fleur souillée. {nickname}, attends qu’elle s’épanouisse, puis élimine d’un seul coup le cœur et les lianes.",
            ["DialogueId"] = 12018239,
            ["GUID"] = "1E161E56",
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E161E56",
            },
        [12018240] = {
            ["Content"] = "以老夫平生武艺，竟险些折在了此处。惭愧，惭愧……",
            ["ContentFR"] = "Avec toute mon expérience martiale... j’ai bien failli périr ici. Quelle honte...",
            ["DialogueId"] = 12018240,
            ["GUID"] = "1E161E80",
            ["NextDialogue"] = 12018241,
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcName"] = "UI_CMName_Name_MatureWuyou",
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E161E80",
            },
        [12018241] = {
            ["Content"] = "这样一来，同伴就集齐啦！没有人被落下，没有人被落下！",
            ["ContentFR"] = "Cette fois, tout le monde est là ! Personne n’a été laissé derrière !",
            ["DialogueId"] = 12018241,
            ["GUID"] = "1E161EAA",
            ["NextDialogue"] = 12018242,
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcName"] = "UI_Npc_Name_WuyoushengA",
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E161EAA",
            },
        [12018242] = {
            ["Content"] = "前方为一巨花秽兽所盘踞，其把持了前往此世之出口。让老夫随你们同去，降妖除魔，清源正本！",
            ["ContentFR"] = "Un immense Souillé bloque la sortie vers ce monde. Laissez-moi combattre à vos côtés et purifiez cet endroit !",
            ["DialogueId"] = 12018242,
            ["GUID"] = "1E161ED4",
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcName"] = "UI_CMName_Name_MatureWuyou",
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E161ED4",
            },
        [12018243] = {
            ["Content"] = "{nickname}，忘川即将崩塌了，必须赶紧结束这一战！",
            ["ContentFR"] = "{nickname} ! Le Fleuve de l’Oubli s’effondre — il faut en finir !",
            ["DialogueId"] = 12018243,
            ["GUID"] = "1E161EFE",
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E161EFE",
            },
        [12018244] = {
            ["Content"] = "趁现在，把手递给我。",
            ["ContentFR"] = "Maintenant. Donne-moi la main.",
            ["DialogueId"] = 12018244,
            ["GUID"] = "1E161F28",
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E161F28",
            },
        [12018300] = {
            ["Content"] = "多谢两位救命之恩，以后必将回报。我们便先离去啦！",
            ["ContentFR"] = "Merci pour nous avoir sauvés. Nous n’oublierons jamais cette dette. À bientôt !",
            ["DialogueId"] = 12018300,
            ["GUID"] = "1E162858",
            ["NextDialogue"] = 12018301,
            ["RelatedWikiId"] = {
                [1] = 408013,
                [2] = 303012,
                [3] = 203006,
                },
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210017,
            ["SpeakNpcName"] = "UI_Npc_Name_Wuyoushengmen",
            ["VoiceName"] = "voice/$Locale$/story/1201/120183/1E162858",
            },
        [12018301] = {
            ["Content"] = "……呜呜……扶疏，{nickname}，你们终于回来了！我都快急坏了……",
            ["ContentFR"] = "<I>Bouhou...</> Fushu ! {nickname} ! Vous êtes enfin revenus ! J’étais morte d’inquiétude !",
            ["DialogueId"] = 12018301,
            ["GUID"] = "1E162882",
            ["NextDialogue"] = 12018302,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120183/1E162882",
            },
        [12018302] = {
            ["Content"] = "我还以为差一点就……呸呸呸！坏话不说出来就不会灵验！",
            ["ContentFR"] = "J’ai cru que vous alliez... non non non ! Si je ne le dis pas, ça n’arrivera pas !",
            ["DialogueId"] = 12018302,
            ["GUID"] = "1E1628AC",
            ["NextDialogue"] = 12018303,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120183/1E1628AC",
            },
        [12018303] = {
            ["Content"] = "扶疏，谢谢你以身涉险，把我带出来。",
            ["ContentFR"] = "Fushu... merci d’avoir pris tous ces risques pour me ramener.",
            ["DialogueId"] = 12018303,
            ["GUID"] = "1E1628D6",
            ["NextDialogue"] = 12018304,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120183/1E1628D6",
            },
        [12018304] = {
            ["Content"] = "这是我应做的。",
            ["ContentFR"] = "C’était mon devoir.",
            ["DialogueId"] = 12018304,
            ["GUID"] = "1E162900",
            ["NextDialogue"] = 12018305,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120183/1E162900",
            },
        [12018305] = {
            ["Content"] = "你没事吧？你看起来脸色好像不太好……",
            ["ContentFR"] = "Tu es sûre que ça va ? Tu es toute pâle...",
            ["DialogueId"] = 12018305,
            ["GUID"] = "1E16292A",
            ["NextDialogue"] = 12018306,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120183/1E16292A",
            },
        [12018306] = {
            ["Content"] = "我身体无大碍。只是心有点乱，需要静一静，整理一下思绪。",
            ["ContentFR"] = "Mon corps va bien. C’est mon esprit qui a besoin de calme... et d’un peu d’ordre.",
            ["DialogueId"] = 12018306,
            ["GUID"] = "1E162954",
            ["NextDialogue"] = 12018307,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120183/1E162954",
            },
        [12018307] = {
            ["Content"] = "好……如果你有什么烦恼想找别人倾诉，我随时在。",
            ["ContentFR"] = "D’accord. Si tu as besoin de parler, je serai là.",
            ["DialogueId"] = 12018307,
            ["GUID"] = "1E16297E",
            ["NextDialogue"] = 12018308,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120183/1E16297E",
            },
        [12018308] = {
            ["Content"] = "那是自然。毕竟经此一遭，你们便是我在世界上唯二的友人了。",
            ["ContentFR"] = "Évidemment. Après ce que nous avons traversé... vous êtes mes deux {性别:seuls amis|seules amies} en ce monde.",
            ["DialogueId"] = 12018308,
            ["GUID"] = "1E1629A8",
            ["NextDialogue"] = 12018309,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120183/1E1629A8",
            },
        [12018309] = {
            ["Content"] = "呜呜，扶疏……",
            ["ContentFR"] = "<I>Bouhou...</> Fushu...",
            ["DialogueId"] = 12018309,
            ["GUID"] = "1E1629D2",
            ["NextDialogue"] = 12018310,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120183/1E1629D2",
            },
        [12018310] = {
            ["Content"] = "好啦。虽然过程有所波折，但所需的药草已经采摘到了。趁着露水还未褪去，我要尽早将其带回，研磨入药。",
            ["ContentFR"] = "Bien. Malgré les détours, nous avons récolté les herbes nécessaires. Je dois rentrer avant que la rosée ne s’évapore, pour les préparer.",
            ["DialogueId"] = 12018310,
            ["GUID"] = "1E1629FC",
            ["NextDialogue"] = 12018311,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120183/1E1629FC",
            },
        [12018311] = {
            ["Content"] = "咿！",
            ["ContentFR"] = "Yi !",
            ["DialogueId"] = 12018311,
            ["GUID"] = "1E162A26",
            ["NextDialogue"] = 12018312,
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210036,
            ["VoiceName"] = "voice/$Locale$/story/1201/120183/1E162A26",
            },
        [12018312] = {
            ["Content"] = "哇啊，你从哪里冒出来的！吓我一跳！",
            ["ContentFR"] = "Aaah ! D’où tu sors, toi ?! Tu m’as fait peur !",
            ["DialogueId"] = 12018312,
            ["GUID"] = "1E162A50",
            ["NextDialogue"] = 12018313,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120183/1E162A50",
            },
        [12018313] = {
            ["Content"] = "你竟没有与它们一同离去……",
            ["ContentFR"] = "Tu n’es pas parti avec les autres...",
            ["DialogueId"] = 12018313,
            ["GUID"] = "1E162A7A",
            ["NextDialogue"] = 12018314,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120183/1E162A7A",
            },
        [12018314] = {
            ["Content"] = "我在往隙深处偶遇了它，将它顺手带出。这也是一种萍水相逢的缘分吧。",
            ["ContentFR"] = "Je l’ai rencontré au plus profond de la Faille de l’Oubli. Je l’ai ramené avec moi... une rencontre fugace, mais précieuse.",
            ["DialogueId"] = 12018314,
            ["GUID"] = "1E162AA4",
            ["NextDialogue"] = 12018315,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120183/1E162AA4",
            },
        [12018315] = {
            ["Content"] = "咿！咿！",
            ["ContentFR"] = "Yi ! Yi !",
            ["DialogueId"] = 12018315,
            ["GUID"] = "1E162ACE",
            ["NextDialogue"] = 12018316,
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210036,
            ["SpeakNpcName"] = "UI_CMName_Name_WuyouWuyan",
            ["VoiceName"] = "voice/$Locale$/story/1201/120183/1E162ACE",
            },
        [12018316] = {
            ["Content"] = "它看起来好像格外亲近你。",
            ["ContentFR"] = "Il a l’air très attaché à toi.",
            ["DialogueId"] = 12018316,
            ["GUID"] = "1E162AF8",
            ["NextDialogue"] = 12018317,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120183/1E162AF8",
            },
        [12018317] = {
            ["Content"] = "这可有些头疼了……我接下来需要集中精神，治疗患者的过程中不好受外界打扰。",
            ["ContentFR"] = "Voilà qui est un peu délicat... Je vais devoir me concentrer pleinement sur le traitement du patient. Durant les soins, je ne peux me permettre d’être dérangée.",
            ["DialogueId"] = 12018317,
            ["GUID"] = "1E162B22",
            ["NextDialogue"] = 12018318,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120183/1E162B22",
            },
        [12018318] = {
            ["Content"] = "{nickname}，可以拜托你先照料它一段时间吗？",
            ["ContentFR"] = "{nickname}, pourrais-tu t’occuper de lui un moment ?",
            ["DialogueId"] = 12018318,
            ["GUID"] = "1E162B4C",
            ["NextDialogue"] = 12018319,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120183/1E162B4C",
            },
        [12018319] = {
            ["Content"] = "小跟班的小跟班……那岂不是小跟班二号！",
            ["ContentFR"] = "Le petit larbin... du petit larbin ? Alors tu seras le petit larbin numéro deux !",
            ["DialogueId"] = 12018319,
            ["GUID"] = "1E162B76",
            ["NextDialogue"] = 12018320,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120183/1E162B76",
            },
        [12018320] = {
            ["Content"] = "咿呀咿！咿咿！",
            ["ContentFR"] = "Yi-ya-yi ! Yi-yi !",
            ["DialogueId"] = 12018320,
            ["GUID"] = "1E162BA0",
            ["NextDialogue"] = 12018321,
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210036,
            ["SpeakNpcName"] = "UI_CMName_Name_WuyouWuyan",
            ["VoiceName"] = "voice/$Locale$/story/1201/120183/1E162BA0",
            },
        [12018321] = {
            ["Content"] = "它看起来似乎不太乐意的样子。",
            ["ContentFR"] = "On dirait qu’il n’aime pas trop cette idée...",
            ["DialogueId"] = 12018321,
            ["GUID"] = "1E162BCA",
            ["NextDialogue"] = 12018322,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120183/1E162BCA",
            },
        [12018322] = {
            ["Content"] = "……抱歉，是我轻慢了你的想法。既然你我有缘，从今往后，你就跟着我吧。我不会信手将你落下，可好？",
            ["ContentFR"] = "... Pardonne-moi. J’ai été maladroite. Puisque le destin nous a liés, reste avec moi. Je ne t’abandonnerai pas. D’accord ?",
            ["DialogueId"] = 12018322,
            ["GUID"] = "1E162BF4",
            ["NextDialogue"] = 12018323,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120183/1E162BF4",
            },
        [12018323] = {
            ["Content"] = "咿！",
            ["ContentFR"] = "Yi !",
            ["DialogueId"] = 12018323,
            ["GUID"] = "1E162C1E",
            ["NextDialogue"] = 12018324,
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210036,
            ["SpeakNpcName"] = "UI_CMName_Name_WuyouWuyan",
            ["VoiceName"] = "voice/$Locale$/story/1201/120183/1E162C1E",
            },
        [12018324] = {
            ["Content"] = "{nickname}，无由生长老处也烦请你去回报了。待患者的病情稍有好转，我会再与你们见面的。",
            ["ContentFR"] = "{nickname}, je te confie aussi un message pour l’Aîné Wishen. Quand la patiente ira mieux, nous nous reverrons.",
            ["DialogueId"] = 12018324,
            ["GUID"] = "1E162C48",
            ["NextDialogue"] = 12018325,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120183/1E162C48",
            },
        [12018325] = {
            ["Content"] = "那就一言为定了！",
            ["ContentFR"] = "Marché conclu !",
            ["DialogueId"] = 12018325,
            ["GUID"] = "1E162C72",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120183/1E162C72",
            },
        [12018401] = {
            ["Camera"] = "-82.743599,-22.173996,191.510315,0.000107,-18.000362,104.812141,25.000002,269.56311,false,Manual,6.0",
            ["Content"] = "小友来了？出发吧。",
            ["ContentFR"] = "Ah... te voilà, {性别:mon jeune ami|ma jeune amie}. Allons-y.",
            ["DialogueId"] = 12018401,
            ["FacialId"] = {
                [1] = "210012:Smile01",
                },
            ["FinalCamera"] = "-85.275848,-12.593918,188.29126,0.000105,-18.000381,104.811234,25.000002,269.806946,false,Manual,6.0",
            ["GUID"] = "1E1638EA",
