            },
        [12018602] = {
            ["Camera"] = "-136.252167,91.878937,113.345459,0.000122,16.784575,27.185421,35.000011,182.757812,false,Manual,4.0",
            ["Content"] = "情况如何了？",
            ["ContentFR"] = "Faites le point.",
            ["DialogueId"] = 12018602,
            ["FacialId"] = {
                [1] = "210012:Doubt01",
                },
            ["GUID"] = "1E1659E4",
            ["NextDialogue"] = 12018603,
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120186/1E1659E4",
            },
        [12018603] = {
            ["Camera"] = "32.268948,257.847717,186.833252,0.00014,-8.414738,-115.807419,35.000011,279.251068,false,Manual,6.0",
            ["Content"] = "如您所料，那猎物负了伤，已被逼入了听鸦原。这儿四面环海，呈孤岛之势，它逃不掉的。接下来只要瓮中捉鳖就好了！",
            ["ContentFR"] = "Comme vous l’aviez prévu, la proie est blessée. Nous l’avons acculée dans la Plaine des Corbeaux. La zone est cernée par la mer — une île naturelle. Elle n’a nulle part où fuir. Il ne reste plus qu’à refermer le piège.",
            ["DialogueId"] = 12018603,
            ["FacialId"] = {
                [1] = "210010:CM_Idle",
                },
            ["GUID"] = "1E165A0E",
            ["NextDialogue"] = 12018604,
            ["SpeakNpcId"] = 210010,
            ["SpeakNpcName"] = "UI_CMName_Name_HeiShiXiaoDi",
            ["TalkActionId"] = {
                [1] = "210010:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120186/1E165A0E",
            },
        [12018604] = {
            ["Camera"] = "-13.461863,151.743454,164.995361,0.000152,9.581034,39.99184,24.0,21.207821,false,Manual,6.0",
            ["Content"] = "听鸦原？这是谁的主意。",
            ["ContentFR"] = "La Plaine des Corbeaux ? Qui a pris cette décision ?",
            ["DialogueId"] = 12018604,
