        [12018606] = {
            ["Camera"] = "-103.426682,207.213165,221.943604,0.000147,-24.816774,-27.574326,35.000008,245.026596,false,Manual,22.0",
            ["Content"] = "这地方，有什么不妥吗？",
            ["ContentFR"] = "Cet endroit pose problème ?",
            ["DialogueId"] = 12018606,
            ["FacialId"] = {
                [1] = "100001:Doubt01",
                },
            ["GUID"] = "1E165A8C",
