            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120186/1E165A8C",
            },
        [12018607] = {
            ["Camera"] = "-14.455,160.474716,158.683838,0.000099,-0.817505,-128.967682,35.0,196.648346,false,Manual,6.0",
            ["Content"] = "属下寻思这里是古战场遗址，平时阴风阵阵的，路人都会绕着走。在这儿行动不容易受打扰……",
            ["ContentFR"] = "Eh bien... c’est un ancien champ de bataille. Le vent y gémit sans cesse, personne n’ose s’y aventurer... On pensait que ça éviterait les interférences...",
            ["DialogueId"] = 12018607,
            ["FacialId"] = {
                [1] = "210010:CM_Sad01",
                },
            ["GUID"] = "1E165AB6",
            ["NextDialogue"] = 12018608,
            ["SpeakNpcId"] = 210010,
            ["TalkActionId"] = {
                [1] = "210010:Shock_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120186/1E165AB6",
            },
        [12018608] = {
            ["Camera"] = "-208.853943,31.453308,168.279785,0.00011,-6.41742,16.636448,25.0,316.576935,false,Manual,6.0",
            ["Content"] = "这里是黍离之战的交战场所没错。你可知此地更之前的用途吗？",
            ["ContentFR"] = "C’est bien là que s’est déroulée la Bataille de Shuli. Mais sais-tu ce que cet endroit était auparavant ?",
            ["DialogueId"] = 12018608,
            ["GUID"] = "1E165AE0",
            ["LookAt"] = {
                [1] = "100001:n(210010)",
                },
            ["NextDialogue"] = 12018609,
            ["SpeakNpcId"] = 210012,
            ["TalkActionId"] = {
                [1] = "210012:Angry01_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120186/1E165AE0",
            },
        [12018609] = {
            ["Content"] = "呃，确实没听说过……还请头儿提点。",
            ["ContentFR"] = "Euh... non, chef. J’ignore tout de ça.",
            ["DialogueId"] = 12018609,
            ["GUID"] = "1E165B0A",
            ["NextDialogue"] = 12018610,
            ["SpeakNpcId"] = 210010,
            ["TalkActionId"] = {
                [1] = "210010:Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120186/1E165B0A",
            },
        [12018610] = {
            ["Camera"] = "-2403.743896,115.38797,1248.473267,0.00005,-28.217525,2.442638,25.0,316.576935,false,Manual,22.0",
            ["Content"] = "上古时期，机枢派的研究重地就立于此地。直至数百年前，悬衡派怀疑此地有叛乱嫌疑，引重兵前来镇压。",
            ["ContentFR"] = "Autrefois, ce lieu était un centre de recherche majeur de la Secte Jishu. Il y a quelques siècles, la Secte Xuanheng, soupçonnant une rébellion, y envoya de lourdes troupes pour mater toute résistance.",
            ["DialogueId"] = 12018610,
            ["FinalCamera"] = "-2292.674805,-508.969971,1248.90564,0.000039,-28.817556,18.043545,25.0,316.576935,false,Manual,22.0",
            ["GUID"] = "1E165B34",
            ["LookAt"] = {
