            },
        [12018613] = {
            ["Content"] = "此地的机巧奥义已经失传，万一被不慎触发，恐会带来变数。",
            ["ContentFR"] = "Les mécanismes de ce lieu sont perdus depuis longtemps. S’ils venaient à s’activer par inadvertance... les conséquences seraient imprévisibles.",
            ["DialogueId"] = 12018613,
            ["GUID"] = "1E165BB2",
            ["LookAt"] = {
                [1] = "210012:n(210010)",
                },
            ["NextDialogue"] = 12018614,
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120186/1E165BB2",
            },
        [12018614] = {
