        [12018616] = {
            ["Camera"] = "-23.822756,171.231598,179.708496,0.000069,-23.820496,-31.151937,25.000006,168.752274,false,Manual,6.0",
            ["Content"] = "既然{nickname}替你们说话，此事便揭过了。从现在起，你们需要谨慎行事，切忌打草惊蛇。",
            ["ContentFR"] = "Puisque {nickname} prend leur défense, je passe l’éponge. Mais à partir de maintenant — prudence absolue. Ne faites rien qui puisse alerter la proie.",
            ["DialogueId"] = 12018616,
            ["FacialId"] = {
                [1] = "210012:None",
