        [12018621] = {
            ["Content"] = "开始收网吧。{nickname}，你跟在我身后。",
            ["ContentFR"] = "Il est temps de refermer le filet. {nickname}, reste dans mon sillage.",
            ["DialogueId"] = 12018621,
