            },
        [12018701] = {
            ["Content"] = "追！",
            ["ContentFR"] = "Poursuivez-le !",
            ["DialogueId"] = 12018701,
            ["GUID"] = "1E166A22",
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120187/1E166A22",
            },
        [12018801] = {
            ["Content"] = "这这这是什么从大地里苏醒了……？！好壮观的机关阵！",
            ["ContentFR"] = "M-mais... qu’est-ce qui sort de terre comme ça ?! C’est énorme... Un gigantesque réseau de mécanismes ?!",
            ["DialogueId"] = 12018801,
            ["GUID"] = "1E167A8A",
            ["NextDialogue"] = 12018802,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120188/1E167A8A",
            },
        [12018802] = {
            ["Content"] = "虬先生在前面。我们去找他问个明白。",
            ["ContentFR"] = "Maître Qiu est passé devant. Allons le rejoindre et lui demander des explications.",
            ["DialogueId"] = 12018802,
            ["GUID"] = "1E167AB4",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120188/1E167AB4",
            },
        [12018901] = {
            ["Camera"] = "1602.116455,-389.513306,871.401367,0.000128,-28.607693,165.210678,18.0,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "有趣，十足有趣……看来数百年的光阴，也未能将这些上古机括战阵摧折。至今尚能运转如常。",
            ["ContentFR"] = "Fascinant... absolument fascinant. Des siècles se sont écoulés, et pourtant ces formations mécaniques antiques fonctionnent encore sans faillir.",
            ["DialogueId"] = 12018901,
            ["FacialId"] = {
                [1] = "210012:Smile01",
                },
            ["FinalCamera"] = "1640.834229,-8.196655,871.401367,0.000124,-28.807701,-179.789062,18.0,100000.0,false,DoNotOverride,22.0",
