            },
        [12018902] = {
            ["Camera"] = "-34.330143,72.500282,189.90625,0.000091,6.999919,-141.000183,35.0,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "机枢派的先人曾打造出如此鬼斧神工之伟业，如今却因大风九章的禁令而寂寂无名了，你们不觉惋惜吗？",
            ["ContentFR"] = "Les anciens de la Secte Jishu ont bâti de tels chefs-d’œuvre... Et aujourd’hui, à cause des interdictions des Neuf Chapitres de Dafeng, tout cela est tombé dans l’oubli. N’éprouvez-vous aucun regret face à une telle perte ?",
            ["DialogueId"] = 12018902,
            ["FacialId"] = {
                [1] = "100001:Doubt01",
                [2] = "210012:Angry01",
                },
            ["FinalCamera"] = "14.608597,109.413803,133.554688,0.00009,13.399642,-139.400177,35.0,100000.0,false,DoNotOverride,22.0",
            ["GUID"] = "1E168B1C",
            ["NextDialogue"] = 12018903,
            ["Scripts"] = "PlayAnimation{_delay{2},ActorId{210012},AnimationId{\"Confident_Start\"},Duration{2}},",
            ["SpeakNpcId"] = 210012,
            ["TalkActionId"] = {
                [1] = "210012:Talk01_End",
                },
            ["ToFinalCameraBlendTime"] = 6,
            ["VoiceName"] = "voice/$Locale$/story/1201/120189/1E168B1C",
            },
        [12018903] = {
            ["Camera"] = "-85.09005,-41.354012,187.742188,0.000135,-16.999964,79.203743,25.000002,265.992188,false,Manual,6.0",
            ["Content"] = "现在是什么情况，我们该怎么出去？",
            ["ContentFR"] = "Quelle est la situation, exactement ? Comment est-ce qu’on sort d’ici ?",
            ["DialogueId"] = 12018903,
            ["GUID"] = "1E168B46",
            ["NextDialogue"] = 12018904,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120189/1E168B46",
            },
        [12018904] = {
            ["Camera"] = "25.055338,-3.090464,104.582031,0.000121,-7.799625,60.402626,35.0,125.585297,false,Manual,6.0",
            ["Content"] = "就是！别说这些有的没的啦，白可不想被困在这里。",
            ["ContentFR"] = "Voilà ! On s’en fiche de l’histoire, d’accord ? Je n’ai aucune envie de rester coincée dans cet endroit !",
            ["DialogueId"] = 12018904,
            ["FacialId"] = {
                [1] = "200002:Angry01",
                },
            ["FinalCamera"] = "25.055338,-3.090464,104.582031,0.000121,-7.799625,62.202351,35.000008,125.585297,false,Manual,6.0",
            ["GUID"] = "1E168B70",
            ["LookAt"] = {
                [1] = "100001:n(210012)",
                [2] = "210012:n(200002)",
                [3] = "200002:n(210012)",
                },
            ["NextDialogue"] = 12018905,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Angry02_Start",
                },
            ["ToFinalCameraBlendTime"] = 0.8,
            ["VoiceName"] = "voice/$Locale$/story/1201/120189/1E168B70",
            },
        [12018905] = {
            ["Camera"] = "99.821701,41.477108,120.901367,0.00014,11.999624,-174.197815,35.000008,210.213547,false,Manual,6.0",
            ["Content"] = "哼，不解风情。徒费古物之美。",
            ["ContentFR"] = "Tss... aucun sens de l’esthétique. Quelle tristesse de gaspiller ainsi la beauté des vestiges anciens.",
            ["DialogueId"] = 12018905,
            ["FacialId"] = {
                [1] = "200002:None",
                [2] = "210012:Doubt01",
                },
            ["GUID"] = "1E168B9A",
            ["NextDialogue"] = 12018906,
            ["Scripts"] = "PlayAnimation{_delay{2},ActorId{210012},AnimationId{\"Confident_End\"},Duration{2}},",
            ["SpeakNpcId"] = 210012,
            ["TalkActionId"] = {
                [1] = "210012:DisagreeHead",
                [2] = "200002:Angry02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120189/1E168B9A",
            },
        [12018906] = {
            ["Camera"] = "99.821701,41.477108,120.901367,0.00014,11.999624,-174.197815,35.000008,210.213547,false,Manual,6.0",
            ["Content"] = "凡是机关，必留有后手……比如说，眼前这座醒世碑，不觉得它看起来就像是等待人敲的样子吗？",
            ["ContentFR"] = "Tout mécanisme prévoit toujours une issue. Regardez cette Stèle de l’Éveil... ne dirait-on pas qu’elle attend qu’on la frappe ?",
            ["DialogueId"] = 12018906,
            ["GUID"] = "1E168BC4",
            ["LookAt"] = {
                [1] = "210012:n(210012)",
                },
            ["NextDialogue"] = 12018907,
            ["Scripts"] = "PARA{\
CameraMoveTo{_delay{2},TargetPosition{\"-2599.537109,-2099.010498,495.693359,0.00015,-8.80078,40.403954,18.0,256766.0625,false,DoNotOverride,22.0\"},duration{0}},\
CameraMoveTo{_delay{2.1},TargetPosition{\"-2722.54248,-2203.702393,520.700195,0.00015,-8.80078,40.403954,18.0,256766.0625,false,DoNotOverride,22.0\"},duration{8}},\
CameraMoveTo{_delay{4.5},TargetPosition{\"-6405.689453,-5441.508301,1031.489258,0.000213,13.197038,-140.794937,18.000008,256766.0625,false,DoNotOverride,22.0\"},duration{0}},\
CameraMoveTo{_delay{4.6},TargetPosition{\"-6437.628906,-5467.57373,1041.154297,0.000213,13.197038,-140.794937,18.000008,256766.0625,false,DoNotOverride,22.0\"},duration{6}}\
}",
            ["SpeakNpcId"] = 210012,
            ["TalkActionId"] = {
                [1] = "100001:Explain01_End",
                },
            ["TurnTo"] = {
                [1] = "210012:p(-179)",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120189/1E168BC4",
            },
        [12018907] = {
            ["Camera"] = "-94.359398,-63.731007,207.273438,0.000093,-26.399609,66.203903,20.0,285.160034,false,Manual,6.0",
            ["Content"] = "喂喂，万一猜错了怎么办？！",
            ["ContentFR"] = "Hé, hé ! Et si tu te trompes, hein ?!",
            ["DialogueId"] = 12018907,
            ["FacialId"] = {
                [1] = "200002:Shock02",
                },
            ["GUID"] = "1E168BEE",
            ["NextDialogue"] = 12018908,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Confident_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120189/1E168BEE",
            },
        [12018908] = {
            ["Content"] = "呵呵……那就得仰仗{nickname}矫健的身手了。",
            ["ContentFR"] = "Hé hé... Dans ce cas, nous compterons sur l’agilité de {nickname}.",
            ["DialogueId"] = 12018908,
            ["FacialId"] = {
                [1] = "210012:Ahaha01",
                },
            ["GUID"] = "1E168C18",
            ["SpeakNpcId"] = 210012,
            ["TurnTo"] = {
                [1] = "210012:n(100001)",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120189/1E168C18",
            },
        [12019001] = {
            ["Content"] = "我曾听闻，机枢派以赤色为尊。",
            ["ContentFR"] = "J’ai entendu dire que la Secte Jishu honorait particulièrement la couleur rouge.",
            ["DialogueId"] = 12019001,
            ["GUID"] = "1E169B5A",
            ["NextDialogue"] = 12019002,
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120190/1E169B5A",
            },
        [12019002] = {
            ["Content"] = "也就是说，红色的道路是安全的。",
            ["ContentFR"] = "Donc... la voie rouge est la plus sûre.",
            ["DialogueId"] = 12019002,
            ["GUID"] = "1E169B84",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120190/1E169B84",
            },
        [12019050] = {
            ["Content"] = "好像有些机关块亮起来了……小仆从，这是什么意思？",
            ["ContentFR"] = "Oh ! Certaines dalles se sont mises à briller... Petit larbin, ça veut dire quoi ?",
            ["DialogueId"] = 12019050,
            ["GUID"] = "1E169B85",
            ["NextDialogue"] = 12019051,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120190/1E169B85",
            },
        [12019051] = {
            ["Content"] = "用意很明显了。顺着机关块亮起的顺序前行，就能破解当下的困局。",
            ["ContentFR"] = "L’intention est limpide. Avancez en suivant l’ordre dans lequel les dalles s’illuminent, et vous dénouerez cette impasse.",
            ["DialogueId"] = 12019051,
            ["GUID"] = "1E169B86",
            ["NextDialogue"] = 12019052,
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120190/1E169B86",
            },
        [12019052] = {
            ["Content"] = "……这种事情不需要你提醒，我们小仆从也知道！",
            ["ContentFR"] = "... Pas besoin que tu nous le dises ! Mon petit larbin avait déjà compris !",
            ["DialogueId"] = 12019052,
            ["GUID"] = "1E169B87",
            ["NextDialogue"] = 12019053,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120190/1E169B87",
            },
        [12019053] = {
            ["Content"] = "好，那我试试。",
            ["ContentFR"] = "Très bien. Je vais essayer.",
            ["DialogueId"] = 12019053,
            ["GUID"] = "1E169B88",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120190/1E169B88",
            },
        [12019054] = {
            ["Content"] = "哇啊啊啊啊，这些机关块怎么还会动，要是不小心踩空就摔下去了！",
            ["ContentFR"] = "Aaaah ! Les dalles bougent maintenant ?! Si on rate un pas, on tombe dans le vide !",
            ["DialogueId"] = 12019054,
            ["GUID"] = "1E169B89",
            ["NextDialogue"] = 12019055,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120190/1E169B89",
            },
        [12019055] = {
            ["Content"] = "魔王大人英明一世，差点阴沟里翻船……实在是太阴险了！",
            ["ContentFR"] = "Le Roi Démon a bien failli se ridiculiser à cause de ça... C’est vraiment sournois !",
            ["DialogueId"] = 12019055,
            ["GUID"] = "1E169B91",
            ["NextDialogue"] = 12019056,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120190/1E169B91",
            },
        [12019056] = {
            ["Content"] = "呵呵。若是难度不升级，何谈挑战呢？",
            ["ContentFR"] = "Hé hé. Sans montée en difficulté, peut-on encore parler de défi ?",
            ["DialogueId"] = 12019056,
            ["GUID"] = "1E169B92",
            ["NextDialogue"] = 12019057,
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120190/1E169B92",
            },
        [12019057] = {
            ["Content"] = "哼，轮不到你来说！",
            ["ContentFR"] = "<I>Tch ! </>On ne t’a rien demandé !",
            ["DialogueId"] = 12019057,
            ["GUID"] = "1E169B93",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120190/1E169B93",
            },
        [12019058] = {
            ["Content"] = "呀！哪里冒出来的家伙，会动……还打我们！",
            ["ContentFR"] = "Hein ?! D’où sortent ces trucs ?! Ils bougent... et ils nous attaquent !",
            ["DialogueId"] = 12019058,
            ["GUID"] = "1E169B94",
            ["NextDialogue"] = 12019059,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120190/1E169B94",
            },
        [12019059] = {
            ["Content"] = "想必是此地设计之初留下来的守备力量，用以防御外来的入侵者。",
            ["ContentFR"] = "Sans doute les forces de garde laissées lors de la création de ce lieu, destinées à repousser les intrus.",
            ["DialogueId"] = 12019059,
            ["GUID"] = "1E169B95",
            ["NextDialogue"] = 12019060,
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120190/1E169B95",
            },
        [12019060] = {
            ["Content"] = "提起精神应对他们，{nickname}。",
            ["ContentFR"] = "Reste sur tes gardes, {nickname}.",
            ["DialogueId"] = 12019060,
            ["GUID"] = "1E169B96",
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120190/1E169B96",
            },
        [12019101] = {
            ["Content"] = "咦，同时出现了两座一模一样的醒世碑……",
            ["ContentFR"] = "Hein ? Deux stèles identiques en même temps... ?",
            ["DialogueId"] = 12019101,
            ["GUID"] = "1E16ABC2",
            ["NextDialogue"] = 12019102,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120191/1E16ABC2",
            },
        [12019102] = {
            ["Content"] = "嗯……莫非是需要二人分处两地，同时敲响。",
            ["ContentFR"] = "Hm... Peut-être faut-il les activer simultanément, depuis deux positions différentes.",
            ["DialogueId"] = 12019102,
            ["GUID"] = "1E16ABEC",
            ["NextDialogue"] = 12019103,
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120191/1E16ABEC",
            },
        [12019103] = {
            ["Content"] = "{nickname}，且与我一试。",
            ["ContentFR"] = "{nickname}, essayons ensemble.",
            ["DialogueId"] = 12019103,
            ["GUID"] = "1E16AC16",
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120191/1E16AC16",
            },
        [12019201] = {
            ["Content"] = "哇啊啊啊啊啊啊啊——白、白的屁股，摔得好痛！",
            ["ContentFR"] = "AAAAAH— ! Mon derrière... ça fait super mal !",
            ["DialogueId"] = 12019201,
            ["GUID"] = "1E16BC2A",
            ["NextDialogue"] = 12019202,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120192/1E16BC2A",
            },
        [12019202] = {
            ["Content"] = "虬先生不知道掉到哪里去了……",
            ["ContentFR"] = "Et Maître Qiu ?! Je ne le vois plus nulle part !",
            ["DialogueId"] = 12019202,
            ["GUID"] = "1E16BC54",
            ["NextDialogue"] = 12019203,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120192/1E16BC54",
            },
        [12019203] = {
            ["Content"] = "难道说，这个机关战阵的用意就是把同行者分开……？",
            ["ContentFR"] = "... Ce mécanisme aurait-il été conçu pour séparer ceux qui avancent ensemble... ?",
            ["DialogueId"] = 12019203,
            ["GUID"] = "1E16BC7E",
            ["NextDialogue"] = 12019204,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120192/1E16BC7E",
            },
        [12019204] = {
            ["Content"] = "等等，小仆从！前面有人！",
            ["ContentFR"] = "Attends, petit larbin ! Il y a quelqu’un devant nous !",
            ["DialogueId"] = 12019204,
            ["GUID"] = "1E16BCA8",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120192/1E16BCA8",
            },
        [12019301] = {
            ["Content"] = "真好，有人来了！这下不仅是我一人困在这里了。",
            ["ContentFR"] = "Ah ! Magnifique, voilà du monde ! Comme ça, je ne suis plus le seul coincé ici !",
            ["DialogueId"] = 12019301,
            ["GUID"] = "1E16CC92",
            ["NextDialogue"] = 12019302,
            ["SpeakNpcId"] = 210021,
            ["SpeakNpcName"] = "UI_CMName_Name_SaTuoBuJi",
            ["VoiceName"] = "voice/$Locale$/story/1201/120193/1E16CC92",
            },
        [12019302] = {
            ["Content"] = "我名刻舟，华胥一介飘零人是也。敢问两位姓名？",
            ["ContentFR"] = "Je m’appelle Kezhou — un vagabond sans attaches de Huaxu. Et vous deux, à qui ai-je l’honneur ?",
            ["DialogueId"] = 12019302,
            ["GUID"] = "1E16CCBC",
            ["NextDialogue"] = 12019303,
            ["RelatedWikiId"] = {
                [1] = 203007,
                },
            ["SpeakNpcId"] = 210021,
            ["VoiceName"] = "voice/$Locale$/story/1201/120193/1E16CCBC",
            },
        [12019303] = {
            ["Content"] = "那……我是纯白的救赎☆光之魔王大人，简称白。如你所见，是一名魔王！征服世界的事找我就对了！",
            ["ContentFR"] = "Alors... <I>hum ! </>Je suis le Rédempteur Immaculé ☆ Roi Démon de la Lumière ! Tu peux m’appeler Snow. Comme tu le vois, je suis un Roi Démon ! Si tu veux conquérir le monde, c’est à moi qu’il faut t’adresser !",
            ["DialogueId"] = 12019303,
            ["GUID"] = "1E16CCE6",
            ["NextDialogue"] = 12019304,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120193/1E16CCE6",
            },
        [12019304] = {
            ["Content"] = "这位是我的小仆从，{nickname}。{性别：他|她}是仅次于白的最厉害的人！",
            ["ContentFR"] = "Et voici mon petit larbin, {nickname}. {性别:Il|Elle} est la personne la plus forte du monde... juste après moi !",
            ["DialogueId"] = 12019304,
            ["GUID"] = "1E16CD10",
            ["NextDialogue"] = 12019305,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120193/1E16CD10",
            },
        [12019305] = {
            ["Content"] = "哦哦……！原来如此！难怪我以随身的枪戟剑林将此地翻来覆去轰了几遍，都没能撼动分毫……竟是要敲击这里。话说回来，这机枢派的造物可真结实。",
            ["ContentFR"] = "Oh— ! Je comprends mieux ! Pas étonnant que j’aie retourné cet endroit à coups de hallebardes, de lances et d’épées sans rien obtenir... Il fallait frapper ici, tout simplement. Cela dit... les créations de la Secte Jishu sont vraiment solides.",
            ["DialogueId"] = 12019305,
            ["GUID"] = "120193141.0",
            ["SpeakNpcId"] = 210021,
            ["VoiceName"] = "voice/$Locale$/story/1201/120193/120193141",
            },
        [12019306] = {
            ["Content"] = "幸会幸会……原来华胥之外的地方，还有如此拉风的职业！相逢即是有缘，何不结伴一程？",
            ["DialogueId"] = 12019306,
            ["GUID"] = "120193051.0",
            ["SpeakNpcId"] = 210021,
            ["VoiceName"] = "voice/$Locale$/story/1201/120193/120193051",
            },
        [12019307] = {
            ["Content"] = "既然你如此仰慕魔王大人，那当然好！哼哼，还是华胥人有品位！",
            ["ContentFR"] = "Puisque tu admires autant le Roi Démon, évidemment que c’est d’accord ! Héhé... décidément, les gens de Huaxu ont du goût !",
            ["DialogueId"] = 12019307,
            ["GUID"] = "1E16CD8E",
            ["NextDialogue"] = 12019308,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120193/1E16CD8E",
            },
        [12019308] = {
            ["Content"] = "这样吧，白册封你为“黑白毛色的侠客，不羁的剑歌浪子，魔王国驻华胥外交大使”！",
            ["ContentFR"] = "Dans ce cas, je te nomme officiellement : « Chevalier à la lame noir et blanc, Barde errant de l’épée indomptée, et Ambassadeur du Royaume Démon à Huaxu » !",
            ["DialogueId"] = 12019308,
            ["GUID"] = "1E16CDB8",
            ["NextDialogue"] = 12019309,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120193/1E16CDB8",
            },
        [12019309] = {
            ["Content"] = "哈哈……结交两位，刻舟心中痛快不已！若不是困于此处，简直想舞剑助兴，与君畅饮至天明！",
            ["ContentFR"] = "Ha ha... vous rencontrer {性别:tous|toutes} les deux me met de fort bonne humeur ! Si nous n’étions pas coincés ici, je dégainerais pour fêter ça et boirais avec vous jusqu’à l’aube !",
            ["DialogueId"] = 12019309,
            ["GUID"] = "1E16CDE2",
            ["NextDialogue"] = 12019310,
            ["SpeakNpcId"] = 210021,
            ["VoiceName"] = "voice/$Locale$/story/1201/120193/1E16CDE2",
            },
        [12019310] = {
            ["Content"] = "对了，你们来时，有见过一名与我年岁相仿的男子吗？我好不容易追他的踪迹到这里。他黑发，穿一身墨色衣服，很好认的！",
            ["ContentFR"] = "Au fait... Sur votre route, n’auriez-vous pas croisé un homme à peu près de mon âge ? Cheveux noirs, vêtu entièrement de sombre — impossible à rater. J’ai suivi sa trace jusqu’ici.",
            ["DialogueId"] = 12019310,
            ["GUID"] = "1E16CE0C",
            ["NextDialogue"] = 12019311,
            ["SpeakNpcId"] = 210021,
            ["VoiceName"] = "voice/$Locale$/story/1201/120193/1E16CE0C",
            },
        [12019311] = {
            ["Content"] = "这样的人，满大街都是吧……",
            ["ContentFR"] = "Euh... ce genre de description, on en croise à tous les coins de rue...",
            ["DialogueId"] = 12019311,
            ["GUID"] = "1E16CE36",
            ["NextDialogue"] = 12019312,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120193/1E16CE36",
            },
        [12019312] = {
            ["Content"] = "我们来的路上，没见到别人。",
            ["ContentFR"] = "Nous n’avons vu personne d’autre en venant.",
            ["DialogueId"] = 12019312,
            ["GUID"] = "1E16CE60",
            ["NextDialogue"] = 12019313,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120193/1E16CE60",
            },
        [12019313] = {
            ["Content"] = "唉……罢了。找了四年了，也不差这一时半会儿。那你们知道该如何从这儿出去吗？",
            ["ContentFR"] = "Ah... tant pis. Ça fait quatre ans que je le cherche — ce n’est pas une attente de plus qui changera quoi que ce soit. Mais dites-moi : vous savez comment sortir d’ici ?",
            ["DialogueId"] = 12019313,
            ["GUID"] = "1E16CE8A",
            ["NextOptions"] = {
                [1] = 12019314,
                },
            ["SpeakNpcId"] = 210021,
            ["VoiceName"] = "voice/$Locale$/story/1201/120193/1E16CE8A",
            },
        [12019314] = {
            ["Content"] = "（告知机关诀窍）",
            ["ContentFR"] = "<I>Expliquer le fonctionnement du mécanisme</>",
            ["DialogueId"] = 12019314,
            ["GUID"] = "1E16CEB4",
            ["NextDialogue"] = 120193141,
            },
        [12019315] = {
            ["Content"] = "你好。",
            ["ContentFR"] = "<I>Bonjour.</>",
            ["DialogueId"] = 12019315,
            ["GUID"] = "12019315",
            },
        [12019316] = {
            ["Content"] = "好暴力狂的发言！",
            ["ContentFR"] = "Quelle mentalité de bourrin !",
            ["DialogueId"] = 12019316,
            ["GUID"] = "1E16CF08",
            ["NextDialogue"] = 12019317,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120193/1E16CF08",
            },
        [12019317] = {
            ["Content"] = "要是凡事都真能靠打一架解决就好了……那一切就简单多了。",
            ["ContentFR"] = "Si seulement tous les problèmes pouvaient se régler à coups de poing... la vie serait tellement plus simple.",
            ["DialogueId"] = 12019317,
            ["GUID"] = "1E16CF32",
            ["NextDialogue"] = 12019318,
            ["SpeakNpcId"] = 210021,
            ["VoiceName"] = "voice/$Locale$/story/1201/120193/1E16CF32",
            },
        [12019318] = {
            ["Content"] = "唉，多说无益，我们还是赶紧逃出去吧。",
            ["ContentFR"] = "Bref, inutile de bavarder davantage. Sortons d’ici au plus vite.",
            ["DialogueId"] = 12019318,
            ["GUID"] = "1E16CF5C",
            ["SpeakNpcId"] = 210021,
            ["VoiceName"] = "voice/$Locale$/story/1201/120193/1E16CF5C",
            },
        [12019401] = {
            ["Content"] = "机关块活过来了！{nickname}，不愧是你。",
            ["ContentFR"] = "Les blocs mécaniques se sont activés ! Bien joué, {nickname}.",
            ["DialogueId"] = 12019401,
            ["GUID"] = "1E16DCFA",
            ["NextDialogue"] = 12019402,
            ["SpeakNpcId"] = 210021,
            ["VoiceName"] = "voice/$Locale$/story/1201/120194/1E16DCFA",
            },
        [12019402] = {
            ["Content"] = "诶，它们排列的图案……是什么意思呢？",
            ["ContentFR"] = "Hé... regarde la disposition de ces dalles. Ça signifie quoi, à ton avis ?",
            ["DialogueId"] = 12019402,
            ["GUID"] = "1E16DD24",
            ["NextDialogue"] = 12019403,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120194/1E16DD24",
            },
        [12019403] = {
            ["Content"] = "如果踩上对应的机关块……或许可以到对岸去？",
            ["ContentFR"] = "Si l’on marche sur les blocs correspondants... on devrait pouvoir atteindre l’autre rive.",
            ["DialogueId"] = 12019403,
            ["GUID"] = "1E16DD4E",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120194/1E16DD4E",
            },
        [12019501] = {
            ["Content"] = "活动筋骨的时候到了！",
            ["ContentFR"] = "Ha ! Enfin l’occasion de dérouiller un peu mes muscles !",
            ["DialogueId"] = 12019501,
            ["GUID"] = "1E16ED62",
            ["NextDialogue"] = 12019502,
            ["SpeakNpcId"] = 210021,
            ["VoiceName"] = "voice/$Locale$/story/1201/120195/1E16ED62",
            },
        [12019502] = {
            ["Content"] = "此前被关在这，做什么都不得劲……要说打架我可就不困了！{nickname}，你看好了！",
            ["ContentFR"] = "Être coincé ici m’a complètement rouillé... Mais dès qu’il s’agit de se battre, je ne connais plus la fatigue ! Regarde bien, {nickname} !",
            ["DialogueId"] = 12019502,
            ["GUID"] = "1E16ED8C",
            ["SpeakNpcId"] = 210021,
            ["VoiceName"] = "voice/$Locale$/story/1201/120195/1E16ED8C",
            },
        [12019601] = {
            ["Content"] = "这些机关块的排列……怎么越来越复杂了？看得我头晕眼花的。",
            ["ContentFR"] = "Ces configurations deviennent de plus en plus complexes... Ça me donne le tournis.",
            ["DialogueId"] = 12019601,
            ["GUID"] = "1E16FDCA",
            ["NextDialogue"] = 12019602,
            ["SpeakNpcId"] = 210021,
            ["VoiceName"] = "voice/$Locale$/story/1201/120196/1E16FDCA",
            },
        [12019602] = {
            ["Content"] = "哼哼……大个子只会用蛮力，还得我们小仆从来！",
            ["ContentFR"] = "Hmph ! Les grands costauds ne savent que cogner — pour réfléchir, il faut notre petit larbin !",
            ["DialogueId"] = 12019602,
            ["GUID"] = "1E16FDF4",
            ["NextDialogue"] = 12019603,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120196/1E16FDF4",
            },
        [12019603] = {
            ["Content"] = "对对，全仰仗你了，{nickname}！",
            ["ContentFR"] = "Exactement, exactement ! On compte sur toi, {nickname} !",
            ["DialogueId"] = 12019603,
            ["GUID"] = "1E16FE1E",
            ["NextDialogue"] = 12019604,
            ["SpeakNpcId"] = 210021,
            ["VoiceName"] = "voice/$Locale$/story/1201/120196/1E16FE1E",
            },
        [12019604] = {
            ["Content"] = "……真拿你们没办法。",
            ["ContentFR"] = "... Vous êtes insortables.",
            ["DialogueId"] = 12019604,
            ["GUID"] = "1E16FE48",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120196/1E16FE48",
            },
        [12019605] = {
            ["Content"] = "小仆从，空中悬着的那个球看起来有点奇怪。要不要用牵机方枢试试看？",
            ["ContentFR"] = "Petit larbin, tu vois cette sphère suspendue dans les airs ? Elle a l’air louche... Et si on essayait avec le Nexus mécanique ?",
            ["DialogueId"] = 12019605,
            ["GUID"] = "1E16FE72",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120196/1E16FE72",
            },
        [12019606] = {
            ["Content"] = "竟一下就飞跃过来了，畅快！",
            ["ContentFR"] = "Oh ! D’un coup, on est déjà de l’autre côté — quel pied !",
            ["DialogueId"] = 12019606,
            ["GUID"] = "1E16FE9C",
            ["SpeakNpcId"] = 210021,
            ["VoiceName"] = "voice/$Locale$/story/1201/120196/1E16FE9C",
            },
        [12019610] = {
            ["Content"] = "好眼熟……小仆从，这不是公尚师傅教过我们的机关吗？竟然在这里也出现了！",
            ["ContentFR"] = "Mais... Ce mécanisme me dit quelque chose... Ce n’est pas celui que Maître Gongshang nous avait enseigné ?",
            ["DialogueId"] = 12019610,
            ["GUID"] = "1E16FE9F",
            ["NextDialogue"] = 12019611,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120196/1E16FE9F",
            },
        [12019611] = {
            ["Content"] = "我们赶紧用那个牵机方枢试试看吧！",
            ["ContentFR"] = "Essayons vite avec le Nexus mécanique !",
            ["DialogueId"] = 12019611,
            ["GUID"] = "1E16FF11",
            ["NextDialogue"] = 12019612,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120196/1E16FF11",
            },
        [12019612] = {
            ["Content"] = "千机……方什么输？这莫非是某柄上等宝剑的名字？",
            ["ContentFR"] = "Le... Nexus méca-quoi ? Ce serait pas le nom d’une épée légendaire, par hasard ?",
            ["DialogueId"] = 12019612,
            ["GUID"] = "1E16FF12",
            ["NextDialogue"] = 12019613,
            ["SpeakNpcId"] = 210021,
            ["VoiceName"] = "voice/$Locale$/story/1201/120196/1E16FF12",
            },
        [12019613] = {
            ["Content"] = "没文化，这可是最新最劲的机枢派造物！你就站着瞧吧！",
            ["ContentFR"] = "Inculte ! C’est la toute dernière invention de la Secte Jishu ! Contente-toi de regarder !",
            ["DialogueId"] = 12019613,
            ["GUID"] = "1E16FF13",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120196/1E16FF13",
            },
        [12019616] = {
            ["Content"] = "如此轻易就能化解谜题，跟你们可真是跟对人了！",
            ["ContentFR"] = "Résoudre ces énigmes devient presque trop facile avec vous deux. J’ai vraiment bien fait de vous suivre !",
            ["DialogueId"] = 12019616,
            ["GUID"] = "1E16FF14",
            ["NextDialogue"] = 12019617,
            ["SpeakNpcId"] = 210021,
            ["VoiceName"] = "voice/$Locale$/story/1201/120196/1E16FF14",
            },
        [12019617] = {
            ["Content"] = "哼哼，那可不！",
            ["ContentFR"] = "Héhé... évidemment !",
            ["DialogueId"] = 12019617,
            ["GUID"] = "1E16FF15",
            ["NextDialogue"] = 12019618,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120196/1E16FF15",
            },
        [12019618] = {
            ["Content"] = "大个子，你要紧紧跟好我们。你要是走丢了，我们可帮不了你。",
            ["ContentFR"] = "Hé, le grand dadais, colle-toi bien à nous. Si tu te perds, on ne viendra pas te chercher.",
            ["DialogueId"] = 12019618,
            ["GUID"] = "1E16FF16",
            ["NextDialogue"] = 12019619,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120196/1E16FF16",
            },
        [12019619] = {
            ["Content"] = "（不妙，白好像越来越得意了……她的尾巴都要翘到天上了！）",
            ["ContentFR"] = "<I>Pas bon... Snow prend clairement confiance. Un peu trop, même.</>",
            ["DialogueId"] = 12019619,
            ["GUID"] = "1E16FF17",
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120196/1E16FF17",
            },
        [12019701] = {
            ["Content"] = "又出现了……这醒世碑需要两人同时敲击，之后脚下平台会翻转，让我们掉到不同的地方。",
            ["ContentFR"] = "Encore ces Stèles de l’Éveil... Il faudra que deux personnes les frappent en même temps. Ensuite, la plateforme se retournera et nous dispersera.",
            ["DialogueId"] = 12019701,
            ["GUID"] = "1E170E32",
            ["NextDialogue"] = 12019702,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120197/1E170E32",
            },
        [12019702] = {
            ["Content"] = "那先就此别过啦。多谢两位带我一路，改日再会！",
            ["ContentFR"] = "Alors c’est ici que nos chemins se séparent. Merci pour la compagnie — nous nous reverrons !",
            ["DialogueId"] = 12019702,
            ["GUID"] = "1E170E5C",
            ["SpeakNpcId"] = 210021,
            ["VoiceName"] = "voice/$Locale$/story/1201/120197/1E170E5C",
            },
        [12019800] = {
            ["Content"] = "虬先生就在前面。【废弃】",
            ["DialogueId"] = 12019800,
            ["GUID"] = "1E170E5D",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120198/1E170E5D",
            },
        [12019801] = {
            ["Content"] = "将分开时的经历告知了虬先生。",
            ["ContentFR"] = "Vous racontez à Maître Qiu ce qui s’est passé pendant votre séparation.",
            ["DialogueId"] = 12019801,
            ["GUID"] = "1E171E9A",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120198/1E171E9A",
            },
        [12019802] = {
            ["Content"] = "竟这般节外生枝……呵呵，这场捕猎，越来越趣味横生了。",
            ["ContentFR"] = "Encore des imprévus, à ce que je vois... Hm. Cette chasse devient de plus en plus savoureuse.",
            ["DialogueId"] = 12019802,
            ["GUID"] = "1E171EC4",
            ["NextDialogue"] = 12019803,
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120198/1E171EC4",
            },
        [12019803] = {
            ["Content"] = "在这里待久了，也有些腻味了。我们还是动身向前，趁早离开此地吧。",
            ["ContentFR"] = "J’ai passé assez de temps dans cet endroit. Continuons d’avancer — quittons ces ruines au plus vite.",
            ["DialogueId"] = 12019803,
            ["GUID"] = "1E171EEE",
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120198/1E171EEE",
            },
        [12019804] = {
            ["Content"] = "呵呵……瞧你们使用这机枢派的宝贝，是越来越熟练了。怎么样，还喜欢不？",
            ["ContentFR"] = "Ha ha... Vous maniez de mieux en mieux les jouets de la Secte Jishu. Alors ? Toujours aussi divertissant ?",
            ["DialogueId"] = 12019804,
            ["Duration"] = 3,
            ["GUID"] = "1E171F18",
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120198/1E171F18",
            },
        [12019805] = {
            ["Content"] = "眼前看来就是最后的考验了。走吧，{nickname}。该结束这一切了。",
            ["ContentFR"] = "Il semble que nous soyons arrivés à l’épreuve ultime. Allons-y, {nickname}. Il est temps d’en finir.",
            ["DialogueId"] = 12019805,
            ["Duration"] = 2,
            ["GUID"] = "1E171F42",
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120198/1E171F42",
            },
        [12019810] = {
            ["Content"] = "这个青铜大家伙是什么？！",
            ["ContentFR"] = "C’est quoi... ce gigantesque colosse de bronze ?!",
            ["DialogueId"] = 12019810,
            ["GUID"] = "1E171F43",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120198/1E171F43",
            },
        [12019811] = {
            ["Content"] = "此乃上古机枢派造物，名为<H>巨阙</>。",
            ["ContentFR"] = "Voici le <H>Terracolosse</> — une création antique de la Secte Jishu.",
            ["DialogueId"] = 12019811,
            ["GUID"] = "1E171F44",
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120198/1E171F44",
            },
        [12019812] = {
            ["Content"] = "传闻中，机枢派曾想研制出能让人类驾驶的巨大人形机傀，巨阙是这种尝试留下的痕迹之一。",
            ["ContentFR"] = "On raconte que la Secte Jishu tenta jadis de concevoir des automates humanoïdes géants pilotables par l’homme. Terracolosse est l’un des vestiges de cette ambition.",
            ["DialogueId"] = 12019812,
            ["GUID"] = "1E171F45",
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120198/1E171F45",
            },
        [12019813] = {
            ["Content"] = "诶，听起来还有点拉风呢……",
            ["ContentFR"] = "Eh... Ça a l’air plutôt stylé, en fait...",
            ["DialogueId"] = 12019813,
            ["GUID"] = "1E171F46",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120198/1E171F46",
            },
        [12019814] = {
            ["Content"] = "要是有那种能驾驶的机傀存在，魔王大人也想试一试！",
            ["ContentFR"] = "S’il existe vraiment des machines que l’on peut piloter, le Roi Démon aimerait beaucoup essayer !",
            ["DialogueId"] = 12019814,
            ["GUID"] = "1E171F47",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120198/1E171F47",
            },
        }
  end },
  { MinKey = 12019901, MaxKey = 12022514, Loader = function()
      return {
        [12019901] = {
