            },
        [12019904] = {
            ["Content"] = "你所说的“狴犴”，难不成就是他？",
            ["ContentFR"] = "Le \"Bi’an\" dont vous parliez... C’était lui, depuis le début ?",
            ["DialogueId"] = 12019904,
            ["GUID"] = "1E172F80",
            ["NextDialogue"] = 12019905,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120199/1E172F80",
            },
        [12019905] = {
            ["Content"] = "又玩文字游戏是吧。对不起，我不干了。",
            ["ContentFR"] = "Encore un tour de passe-passe verbal. {性别:Désolé|Désolée}, mais moi, j’arrête là.",
            ["DialogueId"] = 12019905,
            ["GUID"] = "1E172FAA",
