            ["DialogueId"] = 12023808,
            ["Duration"] = 4,
            ["GUID"] = "1E19B000",
            },
        [12023809] = {
            ["Content"] = "【战斗】烛阴BOSS战",
            ["DialogueId"] = 12023809,
            ["Duration"] = 4,
            ["GUID"] = "1E19B02A",
            },
        [12023810] = {
            ["Content"] = "【机关】采集黑龙鳞",
            ["DialogueId"] = 12023810,
            ["Duration"] = 4,
            ["GUID"] = "1E19B054",
            },
        [12023811] = {
            ["Content"] = "【系统（战斗轮盘）-引导需求】\
1.UI：引导打开军械库轮盘装备<牵机公枢>\
2.UI：引导打开探索背包启用<牵机关公枢>",
            ["DialogueId"] = 12023811,
            ["Duration"] = 4,
            ["GUID"] = "1E19B07E",
            },
        [12023812] = {
            ["Content"] = "【玩法（吸收晶垢-引导需求】\
1.图文:使用机关对着晶垢吸，去除晶垢",
            ["DialogueId"] = 12023812,
            ["Duration"] = 4,
            ["GUID"] = "1E19B0A8",
            },
        [12023850] = {
            ["Content"] = "烟津掠影蔽香尘",
            ["ContentFR"] = "Port-des-Brumes – Voile parfumé",
            ["DialogueId"] = 12023850,
            ["GUID"] = "1E19B0A1",
            },
        [12023851] = {
            ["Content"] = "终",
            ["ContentFR"] = "Fin",
            ["DialogueId"] = 12023851,
            ["GUID"] = "1E19B0A2",
            },
        [12023852] = {
            ["Content"] = "未完待续",
            ["ContentFR"] = "À suivre...",
            ["DialogueId"] = 12023852,
            ["GUID"] = "1E19B0A3",
            },
        [12025001] = {
            ["Content"] = "又一船货物到了！兄弟们，清点好名单再搬运，切莫急躁，心急吃不到热豆腐哟。",
            ["ContentFR"] = "Encore une cargaison qui arrive ! Allez, les gars, vérifiez bien la liste avant de décharger. Pas de précipitation : trop se presser ne fait jamais gagner du temps.",
            ["DialogueId"] = 12025001,
            ["GUID"] = "1E1A73BA",
            ["SpeakNpcId"] = 210112,
            },
        [12025101] = {
            ["Content"] = "针头线脑，香脂香囊，走过路过不要错过——",
            ["ContentFR"] = "Aiguilles, fils, baumes parfumés, sachets d’encens ! Approchez, regardez, ne ratez pas l’occasion !",
            ["DialogueId"] = 12025101,
            ["GUID"] = "1E1A8422",
            ["SpeakNpcId"] = 210113,
            },
        [12025201] = {
            ["Content"] = "哟，{性别：小弟弟|小妹妹}，你来啦。看中了什么随便挑，你是止流大当家的客人，那便也是我的客人。",
            ["ContentFR"] = "Oh, te voilà. Si quelque chose te plaît, fais-toi plaisir. Tu es l’{性别:invité|invitée} de la Patronne Zhiliu... et les invités de Zhiliu sont aussi les miens.",
            ["DialogueId"] = 12025201,
            ["GUID"] = "1E1A948A",
            ["NextOptions"] = {
                [1] = 12025203,
                [2] = 12025212,
                },
            ["SpeakNpcId"] = 210113,
            },
        [12025203] = {
            ["Content"] = "你在码头卖这些，生意好吗？",
            ["ContentFR"] = "<I>Demander si les affaires marchent bien au port</>",
            ["DialogueId"] = 12025203,
            ["GUID"] = "1E1A94DE",
            ["NextDialogue"] = 12025204,
            },
        [12025204] = {
            ["Content"] = "哈哈，做生意，无非是一个找到客户需求，满足客户需求的过程。这便是织星客上路的第一门诀窍。",
            ["ContentFR"] = "Ha ha ! Le commerce, au fond, c’est simple : comprendre ce dont les gens ont besoin... et le leur fournir. Voilà la toute première leçon que tout Tisse-Étoiles apprend avant de prendre la mer.",
            ["DialogueId"] = 12025204,
            ["GUID"] = "1E1A9508",
            ["NextDialogue"] = 12025205,
            ["SpeakNpcId"] = 210113,
            },
        [12025205] = {
            ["Content"] = "织星客远航出海，在船上常常一待就要带上个把月。",
            ["ContentFR"] = "Quand les Tisse-Étoiles partent au large, ils restent souvent coincés sur leur navire pendant un mois ou deux.",
            ["DialogueId"] = 12025205,
            ["GUID"] = "1E1A9532",
            ["NextDialogue"] = 12025206,
            ["SpeakNpcId"] = 210113,
            },
        [12025206] = {
            ["Content"] = "总有些冒失鬼，临到出航前才发现这没带那没带。我这些生活杂货呀，就起到一个江湖救急的作用——当然，价格那也是绝对实惠，童叟无欺！",
            ["ContentFR"] = "Il y a toujours quelques têtes en l’air qui réalisent, juste avant le départ, qu’ils ont oublié ceci ou cela. Mes bricoles servent justement à les dépanner à la dernière minute — et bien sûr, à des prix honnêtes, parole de marchand !",
            ["DialogueId"] = 12025206,
            ["GUID"] = "1E1A955C",
            ["NextDialogue"] = 12025207,
            ["SpeakNpcId"] = 210113,
            },
        [12025207] = {
            ["Content"] = "离开华胥的游客，在等渡船的过程中，也往往要带上几样特色纪念品。销量这不就来了？",
            ["ContentFR"] = "Quant aux voyageurs qui quittent Huaxu, pendant qu’ils attendent le ferry, ils aiment bien emporter quelques souvenirs typiques. Et voilà comment les ventes décollent.",
            ["DialogueId"] = 12025207,
            ["GUID"] = "1E1A9586",
            ["NextDialogue"] = 12025208,
            ["SpeakNpcId"] = 210113,
            },
        [12025208] = {
            ["Content"] = "更何况，本小店还有一个赚钱的独家诀窍——",
            ["ContentFR"] = "Et puis... mon échoppe possède aussi un petit secret très rentable —",
            ["DialogueId"] = 12025208,
            ["GUID"] = "1E1A95B0",
            ["NextOptions"] = {
                [1] = 12025209,
                },
            ["SpeakNpcId"] = 210113,
            },
        [12025209] = {
            ["Content"] = "什么诀窍？",
            ["ContentFR"] = "<I>Quel genre de secret ?</>",
            ["DialogueId"] = 12025209,
            ["GUID"] = "1E1A95DA",
            ["NextDialogue"] = 12025210,
            },
        [12025210] = {
            ["Content"] = "{性别：小弟弟|小妹妹}，刚刚我送你的香囊，可不是什么普通物什，而是获得悬衡派授权的独家限量版香囊。",
            ["ContentFR"] = "Mon {性别:ami|amie}, le sachet d’encens que je t’ai offert tout à l’heure n’est pas un objet ordinaire. C’est une édition limitée, officiellement autorisée par la Secte Xuanheng.",
            ["DialogueId"] = 12025210,
            ["GUID"] = "1E1A9604",
            ["NextDialogue"] = 12025211,
            ["SpeakNpcId"] = 210113,
            },
        [12025211] = {
            ["Content"] = "类似的香囊在华胥各地只有几家能贩售，款式还各有不同，香囊爱好者自然是趋之若鹜。我这摊子在烟津渡到此必游的清单里，也是榜上有名呢！",
            ["ContentFR"] = "Dans tout Huaxu, seules quelques boutiques peuvent en vendre, chacune avec ses propres modèles. Les amateurs d’encens s’arrachent ces pièces. Mon étal figure même sur la liste des incontournables du Port-des-Brumes !",
            ["DialogueId"] = 12025211,
            ["GUID"] = "1E1A962E",
            ["SpeakNpcId"] = 210113,
            },
        [12025212] = {
            ["Content"] = "你也承过止流掌柜的人情吗？",
            ["ContentFR"] = "<I>Donc toi aussi, tu as une dette envers la Patronne Zhiliu ?</>",
            ["DialogueId"] = 12025212,
            ["GUID"] = "1E1A9658",
            ["NextDialogue"] = 12025213,
            },
        [12025213] = {
            ["Content"] = "当年我押上全部身家的一船货物不小心遇到海难，全翻了。我这半辈子的积蓄一夜之间打了水漂。",
            ["ContentFR"] = "Il y a des années, j’avais mis toutes mes économies dans une cargaison. Une tempête a frappé en mer... et tout a sombré. En une nuit, une vie d’économies s’est envolée.",
            ["DialogueId"] = 12025213,
            ["GUID"] = "1E1A9682",
            ["NextDialogue"] = 12025214,
            ["SpeakNpcId"] = 210113,
            },
        [12025214] = {
            ["Content"] = "我去百年春延期借款时偶遇了止流大当家。她听了我的遭遇后，把我的借款一笔勾销了，还额外给我了笔启动资金。",
            ["ContentFR"] = "Je m’étais rendu à Éternel Printemps pour demander un délai de remboursement, et c’est là que j’ai croisé la Patronne Zhiliu. Après avoir entendu mon histoire, elle a effacé ma dette d’un trait... et m’a même donné de quoi recommencer.",
            ["DialogueId"] = 12025214,
            ["GUID"] = "1E1A96AC",
            ["NextDialogue"] = 12025215,
            ["SpeakNpcId"] = 210113,
            },
        [12025215] = {
            ["Content"] = "对她而言，这可能只是一点不值一提的小恩惠，却是实实在在地改变了我的人生。",
            ["ContentFR"] = "Pour elle, ce n’était sans doute qu’un petit geste. Pour moi, ça a changé toute ma vie.",
            ["DialogueId"] = 12025215,
            ["GUID"] = "1E1A96D6",
            ["NextDialogue"] = 12025216,
            ["SpeakNpcId"] = 210113,
            },
        [12025216] = {
            ["Content"] = "后来那笔钱我早就还上了，但止流大当家的人情我可是一直记在心里。{性别：小弟弟|小妹妹}，要是你以后有什么忙需要我帮，直接开口，千万不用客气哈。",
            ["ContentFR"] = "J’ai depuis longtemps remboursé cette somme, mais sa bienveillance, je ne l’ai jamais oubliée. Mon {性别:ami|amie}, si un jour tu as besoin de moi, n’hésite pas. Vraiment.",
            ["DialogueId"] = 12025216,
            ["GUID"] = "1E1A9700",
            ["SpeakNpcId"] = 210113,
            },
        [12025301] = {
            ["Content"] = "是你啊。怎么样，对百年春这边还算熟悉起来了吗？",
            ["ContentFR"] = "Ah, c’est toi. Alors, tu commences à te familiariser avec Éternel Printemps ?",
            ["DialogueId"] = 12025301,
            ["GUID"] = "1E1AA4F2",
            ["NextDialogue"] = 12025302,
            ["SpeakNpcId"] = 210114,
            },
        [12025302] = {
            ["Content"] = "若是有什么人生地不熟的不便之处，来找我，我会尽力帮你解决。",
            ["ContentFR"] = "Si quelque chose te semble compliqué, ou si tu te sens un peu {性别:perdu|perdue}, viens me voir. Je ferai de mon mieux pour t’aider.",
            ["DialogueId"] = 12025302,
            ["GUID"] = "1E1AA51C",
            ["SpeakNpcId"] = 210114,
            },
        [12025401] = {
            ["Content"] = "{nickname}，还有什么问题想问我吗？尽管开口，我会逐一解答。",
            ["ContentFR"] = "{nickname}, as-tu encore quelque chose à me demander ? N’hésite pas. Je te répondrai dans la mesure du possible.",
            ["DialogueId"] = 12025401,
            ["GUID"] = "1E1AB55A",
            ["NextDialogue"] = 12025425,
            ["SpeakNpcId"] = 210115,
            },
        [12025402] = {
            ["Content"] = "你好像是个大人物。",
            ["ContentFR"] = "<I>Vous avez l’air de quelqu’un d’important.</>",
            ["DialogueId"] = 12025402,
            ["GUID"] = "1E1AB584",
            ["NextDialogue"] = 12025403,
            },
        [12025403] = {
            ["Content"] = "呵呵，都是些身外之名罢了。我已经过了为一些浮名薄利而沾沾自喜的年龄。",
            ["ContentFR"] = "Hm... ce ne sont que des titres sans réelle substance. J’ai depuis longtemps dépassé l’âge où l’on se réjouit de la gloire ou de profits éphémères.",
            ["DialogueId"] = 12025403,
            ["GUID"] = "1E1AB5AE",
            ["NextDialogue"] = 12025404,
            ["SpeakNpcId"] = 210115,
            },
        [12025404] = {
            ["Content"] = "止流掌柜，我可以冒昧问一句，你今年多大了吗？",
            ["ContentFR"] = "Patronne Zhiliu... puis-je me permettre une question indiscrète ? Quel âge avez-vous ?",
            ["DialogueId"] = 12025404,
            ["GUID"] = "1E1AB5D8",
            ["NextDialogue"] = 12025405,
            ["SpeakNpcId"] = 100001,
            },
        [12025405] = {
            ["Content"] = "嗯，这可是个危险的问题……卡米拉没有教过你这个道理吗？还是让我们之间保留一些神秘感吧。",
            ["ContentFR"] = "Hmm... voilà une question dangereuse. Camilla ne t’a donc jamais enseigné ce principe ? Gardons plutôt une part de mystère entre nous.",
            ["DialogueId"] = 12025405,
            ["GUID"] = "1E1AB602",
            ["NextDialogue"] = 12025425,
            ["SpeakNpcId"] = 210115,
            },
        [12025406] = {
            ["Content"] = "百年春是个什么样的商会？",
            ["ContentFR"] = "<I>Quel genre de guilde est Éternel Printemps ?</>",
            ["DialogueId"] = 12025406,
            ["GUID"] = "1E1AB62C",
            ["NextDialogue"] = 12025407,
            },
        [12025407] = {
            ["Content"] = "它的历史与织星客一般悠久，可以上溯到华胥立国之初。",
            ["ContentFR"] = "Son histoire est aussi ancienne que celle des Tisse-Étoiles. Elle remonte aux premiers jours de la fondation de Huaxu.",
            ["DialogueId"] = 12025407,
            ["GUID"] = "1E1AB656",
            ["NextDialogue"] = 12025408,
            ["SpeakNpcId"] = 210115,
            },
        [12025408] = {
            ["Content"] = "起先，百年春只是诸多民间商会之一。但随着历史演变，它逐渐承担起了如同织星客行会一般的影响力。",
            ["ContentFR"] = "À l’origine, Éternel Printemps n’était qu’une chambre de commerce parmi d’autres. Mais avec le temps, elle a fini par exercer une influence comparable à celle d’une véritable guilde des Tisse-Étoiles.",
            ["DialogueId"] = 12025408,
            ["GUID"] = "1E1AB680",
            ["NextDialogue"] = 12025409,
            ["SpeakNpcId"] = 210115,
            },
        [12025409] = {
            ["Content"] = "再后来，天禄司将其收编国有，百年春肩负起了给织星客颁发贸易许可、拨发借款等诸多社会功能。",
            ["ContentFR"] = "Plus tard, l’État l’a intégrée à son administration. Éternel Printemps s’est alors vu confier de nombreuses fonctions publiques : délivrer des permis de commerce, accorder des prêts... et bien davantage encore.",
            ["DialogueId"] = 12025409,
            ["GUID"] = "1E1AB6AA",
            ["NextDialogue"] = 12025410,
            ["SpeakNpcId"] = 210115,
            },
        [12025410] = {
            ["Content"] = "更具体的情况，你可以去问我的秘书望春。她会为你详细解答。",
            ["ContentFR"] = "Pour les détails précis, tu peux t’adresser à ma secrétaire, Wangchun. Elle saura t’expliquer tout cela en profondeur.",
            ["DialogueId"] = 12025410,
            ["GUID"] = "1E1AB6D4",
            ["NextDialogue"] = 12025425,
            ["SpeakNpcId"] = 210115,
            },
        [12025411] = {
            ["Content"] = "烛阴之灾能顺利解决吗？",
            ["ContentFR"] = "<I>Le Fléau de Zhuyin peut-il vraiment être résolu ?</>",
            ["DialogueId"] = 12025411,
            ["GUID"] = "1E1AB6FE",
            ["NextDialogue"] = 12025412,
            },
        [12025412] = {
            ["Content"] = "比起给你一个确切的答案，我更愿意相信事在人为。",
            ["ContentFR"] = "Plutôt que de te donner une réponse toute faite, je préfère croire que tout dépend de l’action humaine.",
            ["DialogueId"] = 12025412,
            ["GUID"] = "1E1AB728",
            ["NextDialogue"] = 12025413,
            ["SpeakNpcId"] = 210115,
            },
        [12025413] = {
            ["Content"] = "不过……虽然烛阴之灾来势汹汹，但百年春众人已经做了足够多的筹备，如今还有了你的加入。所以我相信它能够顺利解决。",
            ["ContentFR"] = "Cela dit... même si le Fléau de Zhuyin est redoutable, les membres d’Éternel Printemps ont effectué de longs préparatifs. Et désormais, tu es à nos côtés. Pour toutes ces raisons, je pense que la situation peut être maîtrisée.",
            ["DialogueId"] = 12025413,
            ["GUID"] = "1E1AB752",
            ["NextDialogue"] = 12025414,
            ["SpeakNpcId"] = 210115,
            },
        [12025414] = {
            ["Content"] = "止流掌柜，你好像很有把握的样子。",
            ["ContentFR"] = "Vous semblez très sûre de vous.",
            ["DialogueId"] = 12025414,
            ["GUID"] = "1E1AB77C",
            ["NextDialogue"] = 12025415,
            ["SpeakNpcId"] = 100001,
            },
        [12025415] = {
            ["Content"] = "你想做成的事情，至今没有失败过的吗？这使我有点好奇。",
            ["ContentFR"] = "Y a-t-il quelque chose que vous n’avez jamais réussi à accomplir ? Cela m’intrigue.",
            ["DialogueId"] = 12025415,
            ["GUID"] = "1E1AB7A6",
            ["NextDialogue"] = 12025416,
            ["SpeakNpcId"] = 100001,
            },
        [12025416] = {
            ["Content"] = "呵呵……你猜？",
            ["ContentFR"] = "Hmm... à ton avis ?",
            ["DialogueId"] = 12025416,
            ["GUID"] = "1E1AB7D0",
            ["NextDialogue"] = 12025425,
            ["SpeakNpcId"] = 210115,
            },
        [12025417] = {
            ["Content"] = "我应该怎么去黑市拿工具？",
            ["ContentFR"] = "<I>Comment puis-je me rendre au marché noir pour récupérer les outils ?</>",
            ["DialogueId"] = 12025417,
            ["GUID"] = "1E1AB7FA",
            ["NextDialogue"] = 12025418,
            },
        [12025418] = {
            ["Content"] = "初次造访黑市的人，要从沿海洞窟行出，腰上佩饰特定的挂坠。他们见着这“暗号”对上了，就会知道你是自己人。",
            ["ContentFR"] = "Lors d’une première visite, il est impératif de passer par la grotte côtière, en portant à la ceinture un pendentif bien précis. S’ils reconnaissent ce signe, ils sauront que tu es des leurs.",
            ["DialogueId"] = 12025418,
            ["GUID"] = "1E1AB824",
            ["NextDialogue"] = 12025419,
            ["SpeakNpcId"] = 210115,
            },
        [12025419] = {
            ["Content"] = "为什么一定要从沿海洞穴过去，不能从大路走吗？",
            ["ContentFR"] = "Pourquoi ce détour par la grotte ? Impossible d’emprunter la route principale ?",
            ["DialogueId"] = 12025419,
            ["GUID"] = "1E1AB84E",
            ["NextDialogue"] = 12025420,
            ["SpeakNpcId"] = 100001,
            },
        [12025420] = {
            ["Content"] = "如我所说，这是暗号的一环。",
            ["ContentFR"] = "Comme je l’ai dit, cela fait partie du code.",
            ["DialogueId"] = 12025420,
            ["GUID"] = "1E1AB878",
            ["NextDialogue"] = 12025421,
            ["SpeakNpcId"] = 210115,
            },
        [12025421] = {
            ["Content"] = "想以各种理由混入黑市的无关人士不在少数。如果没有一些用来分辨“自己人”的手段，他们的老大也会很头疼呢。",
            ["ContentFR"] = "Nombreux sont ceux qui tentent de s’infiltrer au marché noir sous divers prétextes. Sans un moyen fiable d’identifier les initiés, leur chef aurait bien du mal à maintenir l’ordre.",
            ["DialogueId"] = 12025421,
            ["GUID"] = "1E1AB8A2",
            ["NextDialogue"] = 12025425,
            ["SpeakNpcId"] = 210115,
            },
        [12025422] = {
            ["Content"] = "没什么想问的。",
            ["ContentFR"] = "<I>Je n’ai plus de questions.</>",
            ["DialogueId"] = 12025422,
            ["GUID"] = "1E1AB8CC",
            ["NextDialogue"] = 12025423,
            },
        [12025423] = {
            ["Content"] = "{nickname}，你要出发了吗？",
            ["ContentFR"] = "{nickname}, tu pars déjà ?",
            ["DialogueId"] = 12025423,
            ["GUID"] = "1E1AB8F6",
            ["NextDialogue"] = 12025424,
            ["SpeakNpcId"] = 210115,
            },
        [12025424] = {
            ["Content"] = "一路小心，我等着你平安归来。",
            ["ContentFR"] = "Prends garde à toi. Je t’attendrai ici, à ton retour.",
            ["DialogueId"] = 12025424,
            ["GUID"] = "1E1AB920",
            ["SpeakNpcId"] = 210115,
            },
        [12025425] = {
            ["DialogueId"] = 12025425,
            ["DialoguePanelType"] = "None",
            ["Duration"] = 0,
            ["FinalDialogueId"] = 12025423,
            ["GUID"] = "1E1AB921",
            ["NextOptions"] = {
                [1] = 12025402,
                [2] = 12025406,
                [3] = 12025411,
                [4] = 12025417,
                [5] = 12025422,
                },
            },
        [12025501] = {
            ["Content"] = "您就是止流大当家从帝国不远千里请来的贵客吧。没想到您这么年轻俊俏……啊不，年轻有为！",
            ["ContentFR"] = "Vous êtes donc l’illustre {性别:invité|invitée} que la Patronne Zhiliu a fait venir d’Hyperborea, au prix d’un long voyage... Je ne m’attendais pas à ce que vous soyez si jeune et si {性别:élégant... ah— non, pardon, si jeune et si accompli !|élégante... ah— non, pardon, si jeune et si accomplie !}",
            ["DialogueId"] = 12025501,
            ["GUID"] = "1E1AC5C2",
            ["NextDialogue"] = 12025502,
            ["SpeakNpcId"] = 210116,
            },
        [12025502] = {
            ["Content"] = "止流大当家平时太忙了，总有事务缠身，很少能有闲下来的时候。要是有什么照顾不周的地方，您来找我，我都会帮您处理！",
            ["ContentFR"] = "La Patronne Zhiliu est habituellement très occupée, toujours prise par les affaires, et elle a rarement un moment de répit. Si jamais quelque chose vous semble manquer ou vous cause le moindre désagrément, venez me voir : je m’en chargerai personnellement.",
            ["DialogueId"] = 12025502,
            ["GUID"] = "1E1AC5EC",
            ["NextDialogue"] = 12025521,
            ["SpeakNpcId"] = 210116,
            },
        [12025503] = {
            ["Content"] = "百年春是个什么样的商会？",
            ["ContentFR"] = "<I>Quel genre de guilde est Éternel Printemps ?</>",
            ["DialogueId"] = 12025503,
            ["GUID"] = "1E1AC616",
            ["NextDialogue"] = 12025504,
            },
        [12025504] = {
            ["Content"] = "不仅在烟津渡，对于整个皓京来说，百年春都是这里规模最大的商会了。",
            ["ContentFR"] = "Non seulement à Port-des-Brumes, mais dans toute Haojing, Éternel Printemps est la plus grande des chambres de commerce.",
            ["DialogueId"] = 12025504,
            ["GUID"] = "1E1AC640",
            ["NextDialogue"] = 12025505,
            ["SpeakNpcId"] = 210116,
            },
        [12025505] = {
            ["Content"] = "华胥人的生活更是离不开百年春，无论是采购日用品，抑或西洋舶来的珍贵货物，再到香料的运输供给，正式成为一名织星客……都与我们百年春脱不开干系。",
            ["ContentFR"] = "La vie des habitants de Huaxu en dépend profondément : qu’il s’agisse de produits du quotidien, de marchandises rares venues d’outre-mer, de l’acheminement des épices, ou même des démarches pour devenir Tisse-Étoiles... tout passe par Éternel Printemps.",
            ["DialogueId"] = 12025505,
            ["GUID"] = "1E1AC66A",
            ["NextDialogue"] = 12025506,
            ["SpeakNpcId"] = 210116,
            },
        [12025506] = {
            ["Content"] = "如您面前所见，百年春前各个摊贩售卖着天南海北的商品，您可以自由采购。这里的交易受到天禄司和大风九章的担保。",
            ["ContentFR"] = "Comme vous pouvez le constater, les étals devant nous proposent des marchandises venues des quatre coins du monde. Vous êtes libre d’y faire vos achats. Toutes les transactions sont garanties par le Bureau de la Fortune Céleste et les Neuf Chapitres de Dafeng.",
            ["DialogueId"] = 12025506,
            ["GUID"] = "1E1AC694",
            ["NextDialogue"] = 12025507,
            ["SpeakNpcId"] = 210116,
            },
        [12025507] = {
            ["Content"] = "如果您想成为一名织星客，也可以去旁边的窗口递交手续。我们针对织星客推出了很多扶持计划，不仅能出借起始资金，还有航海技术的全套免费培训。",
            ["ContentFR"] = "Et si vous souhaitez devenir Tisse-Étoiles, un guichet se trouve juste à côté pour déposer votre dossier. Nous proposons de nombreux programmes de soutien : prêts de départ, formations complètes à la navigation commerciale... le tout sans frais.",
            ["DialogueId"] = 12025507,
            ["GUID"] = "1E1AC6BE",
            ["NextDialogue"] = 12025521,
            ["SpeakNpcId"] = 210116,
            },
        [12025508] = {
            ["Content"] = "禁行令对大家的影响很大吗？",
            ["ContentFR"] = "<I>Le Décret d’Interdiction a-t-il eu un fort impact sur la population ?</>",
            ["DialogueId"] = 12025508,
            ["GUID"] = "1E1AC6E8",
            ["NextDialogue"] = 12025509,
            },
        [12025509] = {
            ["Content"] = "禁行令是给众人带来了一些不便……但这也是无奈之举，它主要针对受玄色狴犴影响的内陆区域。",
            ["ContentFR"] = "Il a certes causé quelques désagréments... mais c’était inévitable. Il vise principalement les régions intérieures affectées par les Bi’an obscurs.",
            ["DialogueId"] = 12025509,
            ["GUID"] = "1E1AC712",
            ["NextDialogue"] = 12025510,
            ["SpeakNpcId"] = 210116,
            },
        [12025510] = {
            ["Content"] = "毕竟，各位的性命安危是百年春首先需要保障的。我相信等到大当家找到方法重新封印烛阴后，大家的生活会很快恢复如初。",
            ["ContentFR"] = "Après tout, la sécurité de chacun est la priorité absolue d’Éternel Printemps. Je suis convaincue que, lorsque la patronne aura trouvé un moyen de sceller de nouveau Zhuyin, la vie reprendra rapidement son cours normal.",
            ["DialogueId"] = 12025510,
            ["GUID"] = "1E1AC73C",
            ["NextDialogue"] = 12025511,
            ["SpeakNpcId"] = 210116,
            },
        [12025511] = {
            ["Content"] = "有了您的帮助，这一天很快就会到来吧。",
            ["ContentFR"] = "Avec votre aide, ce jour arrivera sans doute bien plus tôt.",
            ["DialogueId"] = 12025511,
            ["GUID"] = "1E1AC766",
            ["NextDialogue"] = 12025521,
            ["SpeakNpcId"] = 210116,
            },
        [12025512] = {
            ["Content"] = "止流掌柜是什么样的人？",
            ["ContentFR"] = "<I>Comment est la Patronne Zhiliu, au juste ?</>",
            ["DialogueId"] = 12025512,
            ["GUID"] = "1E1AC790",
            ["NextDialogue"] = 12025513,
            },
        [12025513] = {
            ["Content"] = "大当家她呀，特别厉害！无论多么棘手的事务，她都能轻易化解。",
            ["ContentFR"] = "Oh, la patronne est... incroyable ! Peu importe la difficulté, elle trouve toujours une solution, et sans jamais perdre son sang-froid.",
            ["DialogueId"] = 12025513,
            ["GUID"] = "1E1AC7BA",
            ["NextDialogue"] = 12025514,
            ["SpeakNpcId"] = 210116,
            },
        [12025514] = {
            ["Content"] = "她身为龙渊上卿，协理天禄司，又管着百年春，我们一般人简直想象不到有多少事务等着她去处理。这些事情要是堆在同一个人身上，早就把那个人压垮了！",
            ["ContentFR"] = "Elle est le Haut Chancelier de Longyuan, assiste le Bureau de la Fortune Céleste, et dirige Éternel Printemps... Rien que d’y penser, on peine à imaginer tout ce qu’elle doit gérer. À la place de quiconque d’autre, le poids serait déjà écrasant.",
            ["DialogueId"] = 12025514,
            ["GUID"] = "1E1AC7E4",
            ["NextDialogue"] = 12025515,
            ["SpeakNpcId"] = 210116,
            },
        [12025515] = {
            ["Content"] = "但对于大当家来说，这好像都不是什么大事。无论什么时候看到她，她都是那么从容不迫，做什么事都游刃有余的样子，让人心里一下子就能安定下来。",
            ["ContentFR"] = "Mais pour elle, tout cela semble aller de soi. Chaque fois que je la vois, elle est calme, assurée, parfaitement maîtresse de la situation. Rien que sa présence apaise les esprits.",
            ["DialogueId"] = 12025515,
            ["GUID"] = "1E1AC80E",
            ["NextDialogue"] = 12025516,
            ["SpeakNpcId"] = 210116,
            },
        [12025516] = {
            ["Content"] = "呀，我好像一下子滔滔不绝了起来。",
            ["ContentFR"] = "Ah... je me rends compte que je parle sans m’arrêter.",
            ["DialogueId"] = 12025516,
            ["GUID"] = "1E1AC838",
            ["NextDialogue"] = 12025517,
            ["SpeakNpcId"] = 210116,
            },
        [12025517] = {
            ["Content"] = "说出来有点不好意思，我其实非常崇拜大当家……",
            ["ContentFR"] = "C’est un peu embarrassant à admettre, mais... j’admire profondément la patronne.",
            ["DialogueId"] = 12025517,
            ["GUID"] = "1E1AC862",
            ["NextDialogue"] = 12025518,
            ["SpeakNpcId"] = 210116,
            },
        [12025518] = {
            ["Content"] = "她好像特别青睐于您。大当家的客人，就是我们百年春的客人！所以您有什么要求尽管说，我会尽量满足的。",
            ["ContentFR"] = "Elle semble d’ailleurs vous porter une attention toute particulière. Or, les invités de la patronne sont les invités d’Éternel Printemps. Alors n’hésitez pas : si vous avez besoin de quoi que ce soit, je ferai tout mon possible pour vous aider.",
            ["DialogueId"] = 12025518,
            ["GUID"] = "1E1AC88C",
            ["NextDialogue"] = 12025521,
            ["SpeakNpcId"] = 210116,
            },
        [12025519] = {
            ["Content"] = "没什么想问的。",
            ["ContentFR"] = "<I>Je n’ai plus de questions.</>",
            ["DialogueId"] = 12025519,
            ["GUID"] = "1E1AC8B6",
            ["NextDialogue"] = 12025520,
            },
        [12025520] = {
            ["Content"] = "如果有需要，随时再来找我！我会一直在这里为您提供服务。",
            ["ContentFR"] = "Si jamais vous avez besoin de quoi que ce soit, revenez me voir. Je serai toujours ici pour vous assister.",
            ["DialogueId"] = 12025520,
            ["GUID"] = "1E1AC8E0",
            ["SpeakNpcId"] = 210116,
            },
        [12025521] = {
            ["DialogueId"] = 12025521,
            ["DialoguePanelType"] = "None",
            ["Duration"] = 0,
            ["FinalDialogueId"] = 12025520,
            ["GUID"] = "1E1AC8E1",
            ["NextOptions"] = {
                [1] = 12025503,
                [2] = 12025508,
                [3] = 12025512,
                [4] = 12025519,
                },
            },
        [12025601] = {
            ["Content"] = "…………",
            ["ContentFR"] = "...",
            ["DialogueId"] = 12025601,
            ["GUID"] = "1E1AD62A",
            ["NextDialogue"] = 12025602,
            ["SpeakNpcId"] = 210117,
            },
        [12025602] = {
            ["Content"] = "（这位负伤的应天尉在你眼前沉沉睡去，眉头紧蹙，似乎一时半会不会醒来……）",
            ["ContentFR"] = "N’ayant plus la force de lutter, le Magistrat de Yingtian grièvement blessé s’endort profondément sous vos yeux. Son front reste crispé : il semble peu probable qu’il se réveille de sitôt...",
            ["DialogueId"] = 12025602,
            ["GUID"] = "1E1AD654",
            ["NextDialogue"] = 12025603,
            },
        [12025603] = {
            ["Content"] = "（应天尉也会做梦吗？他在自己的梦境中又会看到什么？你不禁开始思考。）",
            ["ContentFR"] = "Les Magistrats de Yingtian rêvent-ils eux aussi ? Que peut-il bien voir, prisonnier de ses songes ? Malgré vous, la question s’impose à votre esprit.",
            ["DialogueId"] = 12025603,
            ["GUID"] = "1E1AD67E",
            ["NextDialogue"] = 12025604,
            },
        [12025604] = {
            ["Content"] = "怎么了小仆从，在欣赏本魔王的大作吗？",
            ["ContentFR"] = "Alors, petit larbin... tu admires l’œuvre magistrale de ton Roi Démon ?",
            ["DialogueId"] = 12025604,
            ["GUID"] = "1E1AD6A8",
            ["NextDialogue"] = 12025605,
            ["SpeakNpcName"] = "UI_Npc_Name_Bai",
            },
        [12025605] = {
            ["Content"] = "想要的话，我也可以给你脸上画一个皎皎涂鸦哟！只要是小仆从的要求，白都会满足！",
            ["ContentFR"] = "Si tu veux, je peux aussi te dessiner un magnifique graffiti Luno sur le visage ! Après tout, tant que ça vient de mon petit larbin, aucun souhait n’est trop extravagant !",
            ["DialogueId"] = 12025605,
            ["GUID"] = "1E1AD6D2",
            ["NextDialogue"] = 12025606,
            ["SpeakNpcName"] = "UI_Npc_Name_Bai",
            },
        [12025606] = {
            ["Content"] = "……谢了，白。我们还是赶紧走吧。",
            ["ContentFR"] = "... Merci, Snow. Allons-y maintenant. Il vaut mieux ne pas traîner.",
            ["DialogueId"] = 12025606,
            ["GUID"] = "1E1AD6FC",
            ["SpeakNpcId"] = 100001,
            },
        }
  end },
  { MinKey = 12025701, MaxKey = 12030511, Loader = function()
      return {
        [12025701] = {
            ["Content"] = "嘿，我说你们俩——还真是止流掌柜的客人。",
            ["ContentFR"] = "Hé, vous deux... Alors comme ça, vous êtes vraiment des {性别:invités|invitées} de la Patronne Zhiliu.",
            ["DialogueId"] = 12025701,
            ["GUID"] = "1E1AE692",
            ["NextDialogue"] = 12025702,
            ["SpeakNpcId"] = 210118,
            },
        [12025702] = {
            ["Content"] = "我天天在这儿望风，想混进黑市的人可真不少，各种借口我都听得耳朵起茧子了。但像你们这么冒失的我还是头一回见。",
            ["ContentFR"] = "Je monte la garde ici tous les jours. Des gens qui essaient de s’infiltrer au marché noir, j’en vois à la pelle — j’ai entendu toutes les excuses possibles. Mais des gens aussi téméraires que vous, c’est une première.",
            ["DialogueId"] = 12025702,
            ["GUID"] = "1E1AE6BC",
            ["NextDialogue"] = 12025703,
            ["SpeakNpcId"] = 210118,
            },
        [12025703] = {
            ["Content"] = "既然你们现在已经是虬先生的座上宾了……嘿嘿，能不能帮我在老大面前美言两句。就说他手下的张三，愿意鞍前马后为他老人家效劳！",
            ["ContentFR"] = "Puisque vous êtes désormais des hôtes de marque de Maître Qiu... héhé... Vous pourriez pas glisser un petit mot en ma faveur auprès du patron ? Dites-lui que Zhang San, l’un de ses hommes, est prêt à se dévouer corps et âme pour lui !",
            ["DialogueId"] = 12025703,
            ["GUID"] = "1E1AE6E6",
            ["NextDialogue"] = 12025704,
            ["SpeakNpcId"] = 210118,
            },
        [12025704] = {
            ["Content"] = "你们说，我天天在这儿望着，连潮声岩穴的对侧都快望穿了，按照风水轮流转的道理，也该轮到些能捞油水的位置了。",
            ["ContentFR"] = "Ça fait des lustres que je monte la garde ici, à fixer l’entrée de Chant-des-Marées jusqu’à en avoir les yeux qui brûlent. Avec la roue du destin qui tourne, ça devrait bien être mon tour de décrocher un poste un peu plus... rentable, non ?",
            ["DialogueId"] = 12025704,
            ["GUID"] = "1E1AE710",
            ["NextDialogue"] = 12025705,
            ["SpeakNpcId"] = 210118,
            },
        [12025705] = {
            ["Content"] = "总不能苦活都给我一个人干了吧，是不是这个理？",
            ["ContentFR"] = "On ne va quand même pas me refiler tout le sale boulot éternellement... pas vrai ?",
            ["DialogueId"] = 12025705,
            ["GUID"] = "1E1AE73A",
            ["SpeakNpcId"] = 210118,
            },
        [12025801] = {
            ["Content"] = "小友，你来了，坐。",
            ["ContentFR"] = "Ah... te voilà, {性别:mon jeune ami|ma jeune amie}. Assieds-toi.",
            ["DialogueId"] = 12025801,
            ["GUID"] = "1E1AF6FA",
            ["NextDialogue"] = 12025802,
            ["SpeakNpcId"] = 210119,
            },
        [12025802] = {
            ["Content"] = "百年的陈皮，刚沏好的，润润嗓子再来与我分享旅途的见闻吧。",
            ["ContentFR"] = "De l’écorce de mandarine affinée cent ans, tout juste infusée. Humecte-toi la gorge, puis raconte-moi ton voyage.",
            ["DialogueId"] = 12025802,
            ["GUID"] = "1E1AF724",
            ["NextDialogue"] = 12025828,
            ["SpeakNpcId"] = 210119,
            },
        [12025803] = {
            ["Content"] = "你为什么收藏这么多古董？",
            ["ContentFR"] = "<I>Pourquoi collectionnez-vous autant d’antiquités ?</>",
            ["DialogueId"] = 12025803,
            ["GUID"] = "1E1AF74E",
            ["NextDialogue"] = 12025804,
            },
        [12025804] = {
            ["Content"] = "物欲深重，想要自然就要得到，这是所有活物最真实的本能。",
            ["ContentFR"] = "Le désir est une chose profonde. Vouloir, c’est chercher à posséder — c’est l’instinct le plus sincère de toute forme de vie.",
            ["DialogueId"] = 12025804,
            ["GUID"] = "1E1AF778",
            ["NextDialogue"] = 12025805,
            ["SpeakNpcId"] = 210119,
            },
        [12025805] = {
            ["Content"] = "更何况，古董并非仅是眼前的死物，它们都曾经在他人的故事中活过，说是牵连着千百个春秋，也不为过。",
            ["ContentFR"] = "Et puis, les antiquités ne sont pas de simples objets inertes. Chacune a vécu dans l’histoire de quelqu’un. Dire qu’elles portent en elles des siècles entiers n’a rien d’exagéré.",
            ["DialogueId"] = 12025805,
            ["GUID"] = "1E1AF7A2",
            ["NextDialogue"] = 12025806,
            ["SpeakNpcId"] = 210119,
            },
        [12025806] = {
            ["Content"] = "听着玄之又玄，怪难懂的。",
            ["ContentFR"] = "C’est... assez abstrait. Pas facile à saisir.",
            ["DialogueId"] = 12025806,
            ["GUID"] = "1E1AF7CC",
            ["NextDialogue"] = 12025807,
            ["SpeakNpcId"] = 100001,
            },
        [12025807] = {
            ["Content"] = "这柄短剑，抵御过外敌，刺杀过君主，最后是殉了主。这碎茶盏呢，迎接了游子，送别了挚爱，最后是在赌书时被打翻在地。",
            ["ContentFR"] = "Cette dague, par exemple : elle a repoussé des envahisseurs, assassiné un souverain, puis suivi son maître dans la mort.\
Et ce bol fêlé : il a accueilli un voyageur, vu partir un être cher, avant d’être renversé lors d’un pari littéraire.",
            ["DialogueId"] = 12025807,
            ["GUID"] = "1E1AF7F6",
            ["NextDialogue"] = 12025808,
            ["SpeakNpcId"] = 210119,
            },
        [12025808] = {
            ["Content"] = "当我触碰到这些古物时，好像此间并非只有你我二人，而是有七八幕景，十二三人，几百年事。这就是为什么我要收集它们，绝不收手。",
            ["ContentFR"] = "Quand je touche ces objets, j’ai l’impression que nous ne sommes pas seuls ici.\
Sept ou huit scènes, une douzaine de visages, des siècles entiers réunis dans une même pièce. Voilà pourquoi je les collectionne. Et pourquoi je ne m’arrêterai jamais.",
            ["DialogueId"] = 12025808,
            ["GUID"] = "1E1AF820",
            ["NextDialogue"] = 12025828,
            ["SpeakNpcId"] = 210119,
            },
        [12025809] = {
            ["Content"] = "听说你很贪得无厌。",
            ["ContentFR"] = "<I>On dit que vous êtes d’une avidité sans bornes.</>",
            ["DialogueId"] = 12025809,
            ["GUID"] = "1E1AF84A",
            ["NextDialogue"] = 12025810,
            },
        [12025810] = {
            ["Content"] = "贪得无厌？我喜欢这个评价。",
            ["ContentFR"] = "Sans bornes ? J’aime beaucoup ce qualificatif.",
            ["DialogueId"] = 12025810,
            ["GUID"] = "1E1AF874",
            ["NextDialogue"] = 12025811,
            ["SpeakNpcId"] = 210119,
            },
        [12025811] = {
            ["Content"] = "我若不贪，便是暴殄天物，无数珍宝与秘密将被埋葬于过去，永世无人知晓。",
            ["ContentFR"] = "Si je n’étais pas avide, ce serait un gâchis. D’innombrables trésors et secrets resteraient enfouis dans le passé, à jamais oubliés.",
            ["DialogueId"] = 12025811,
            ["GUID"] = "1E1AF89E",
            ["NextDialogue"] = 12025812,
            ["SpeakNpcId"] = 210119,
            },
        [12025812] = {
            ["Content"] = "人若不贪，便是有违这世间最朴素的道理：物欲，才是让人前行的动力，让万物演进的根本。",
            ["ContentFR"] = "Refuser le désir, c’est nier la loi la plus simple de ce monde : le désir fait avancer l’homme, il est le moteur même de l’évolution.",
            ["DialogueId"] = 12025812,
            ["GUID"] = "1E1AF8C8",
            ["NextDialogue"] = 12025813,
            ["SpeakNpcId"] = 210119,
            },
        [12025813] = {
            ["Content"] = "可并不是所有人都这么想。",
            ["ContentFR"] = "Tout le monde ne partage pas ce point de vue.",
            ["DialogueId"] = 12025813,
            ["GUID"] = "1E1AF8F2",
            ["NextDialogue"] = 12025814,
            ["SpeakNpcId"] = 100001,
            },
        [12025814] = {
            ["Content"] = "无所谓，你大可以说这是厚颜无耻的诡辩，但我更喜欢将它描述为，顺应自我，随心所欲。",
            ["ContentFR"] = "Peu importe. Tu peux appeler cela une justification éhontée. Moi, j’y vois simplement une fidélité à soi-même, une liberté assumée.",
            ["DialogueId"] = 12025814,
            ["GUID"] = "1E1AF91C",
            ["NextDialogue"] = 12025815,
            ["SpeakNpcId"] = 210119,
            },
        [12025815] = {
            ["Content"] = "大部分人想成为虬先生，但是却不会做虬先生，不敢做虬先生。最终连自己也做不成，只会躲在道理规矩背后谩骂我，可怜呐。",
            ["ContentFR"] = "Beaucoup rêvent de devenir comme moi... mais n’osent pas l’être. À force de se cacher derrière règles et principes, ils ne deviennent même plus eux-mêmes. Ils préfèrent m’insulter de loin. Pathétique.",
            ["DialogueId"] = 12025815,
            ["GUID"] = "1E1AF946",
            ["NextDialogue"] = 12025802,
            ["SpeakNpcId"] = 210119,
            },
        [12025816] = {
            ["Content"] = "公尚师傅是谁？",
            ["ContentFR"] = "<I>Qui est Maître Gongshang ?</>",
            ["DialogueId"] = 12025816,
            ["GUID"] = "1E1AF970",
            ["NextDialogue"] = 12025817,
            },
        [12025817] = {
            ["Content"] = "我资助的一位机枢派奇人。",
            ["ContentFR"] = "Un prodige excentrique de la Secte Jishu... que je soutiens financièrement.",
            ["DialogueId"] = 12025817,
            ["GUID"] = "1E1AF99A",
            ["NextDialogue"] = 12025818,
            ["SpeakNpcId"] = 210119,
            },
        [12025818] = {
            ["Content"] = "俗语说“人无癖不可交”。他便是我所见之人中癖好最为深重，行事最为乖张的一位了。",
            ["ContentFR"] = "On dit qu’un homme sans obsession n’est pas digne de compagnie. Et lui est, de tous ceux que j’ai rencontrés, le plus obsessionnel... et le plus déviant.",
            ["DialogueId"] = 12025818,
            ["GUID"] = "1E1AF9C4",
            ["NextDialogue"] = 12025819,
            ["SpeakNpcId"] = 210119,
            },
        [12025819] = {
            ["Content"] = "人不怕性情怪异，怕的是平庸。他那打造机枢的手艺，当世也没几位比得上的。要不是他看不上天梁司的做派，也不会流落民间受我资助。",
            ["ContentFR"] = "L’excentricité ne me dérange pas. La médiocrité, si. Son talent en matière de mécanismes est sans égal. S’il n’avait pas méprisé les méthodes du Bureau des Travaux, il n’aurait jamais quitté leurs rangs... ni eu besoin de moi.",
            ["DialogueId"] = 12025819,
            ["GUID"] = "1E1AF9EE",
            ["NextDialogue"] = 12025820,
            ["SpeakNpcId"] = 210119,
            },
        [12025820] = {
            ["Content"] = "这等性情的奇人，就算当着面骂我，我也只会一笑了之。",
            ["ContentFR"] = "Un homme comme lui pourrait m’insulter en face que je n’en rirais que davantage.",
            ["DialogueId"] = 12025820,
            ["GUID"] = "1E1AFA18",
            ["NextDialogue"] = 12025828,
            ["SpeakNpcId"] = 210119,
            },
        [12025821] = {
            ["Content"] = "你和止流掌柜是合作关系吗？",
            ["ContentFR"] = "<I>Êtes-vous allié à la Patronne Zhiliu ?</>",
            ["DialogueId"] = 12025821,
            ["GUID"] = "1E1AFA42",
            ["NextDialogue"] = 12025822,
            },
        [12025822] = {
            ["Content"] = "你如果这样定义各取所需，那便是。",
            ["ContentFR"] = "Si tu appelles « alliance » une relation fondée sur l’intérêt mutuel... alors oui.",
            ["DialogueId"] = 12025822,
            ["GUID"] = "1E1AFA6C",
            ["NextDialogue"] = 12025823,
            ["SpeakNpcId"] = 210119,
            },
        [12025823] = {
            ["Content"] = "那要是有一天她不再能提供你需要的东西，你会背叛她吗？",
            ["ContentFR"] = "Et si un jour elle ne pouvait plus vous offrir ce que vous cherchez... la trahiriez-vous ?",
            ["DialogueId"] = 12025823,
            ["GUID"] = "1E1AFA96",
            ["NextDialogue"] = 12025824,
            ["SpeakNpcId"] = 100001,
            },
        [12025824] = {
            ["Content"] = "哈哈，小友这个问题有些天真了！世上无恒久之友，也无恒久之敌。人与人之间的立场流动不定，又何来背不背叛一说呢？",
            ["ContentFR"] = "Ha ha ! Voilà une question bien naïve, {性别:mon jeune ami|ma jeune amie}. Il n’existe ni amis éternels, ni ennemis éternels. Les positions changent sans cesse. Parler de trahison n’a donc guère de sens.",
            ["DialogueId"] = 12025824,
            ["GUID"] = "1E1AFAC0",
            ["NextDialogue"] = 12025825,
            ["SpeakNpcId"] = 210119,
            },
        [12025825] = {
            ["Content"] = "不过有一件事你大可放心。你们止流掌柜是个聪明人，她会用利益将别人紧紧和她捆绑在一条战船上。你说的那一天，大抵是不会发生的。",
            ["ContentFR"] = "Mais sois rassuré : ta Patronne Zhiliu est une femme avisée. Elle sait lier les autres à elle par l’intérêt, solidement, sur un même navire. Le jour que tu évoques n’arrivera probablement jamais.",
            ["DialogueId"] = 12025825,
            ["GUID"] = "1E1AFAEA",
            ["NextDialogue"] = 12025828,
            ["SpeakNpcId"] = 210119,
            },
        [12025826] = {
            ["Content"] = "我先走了。",
            ["ContentFR"] = "<I>Je vais y aller.</>",
            ["DialogueId"] = 12025826,
            ["GUID"] = "1E1AFB14",
            ["NextDialogue"] = 12025827,
            },
        [12025827] = {
            ["Content"] = "慢走，不送。",
            ["ContentFR"] = "Va. Je ne te raccompagne pas.",
            ["DialogueId"] = 12025827,
            ["GUID"] = "1E1AFB3E",
            ["SpeakNpcId"] = 210119,
            },
        [12025828] = {
            ["DialogueId"] = 12025828,
            ["DialoguePanelType"] = "None",
            ["Duration"] = 0,
            ["FinalDialogueId"] = 12025827,
            ["GUID"] = "1E1AFB3F",
            ["NextOptions"] = {
                [1] = 12025803,
                [2] = 12025809,
                [3] = 12025816,
                [4] = 12025821,
                [5] = 51155701,
                [6] = 12025826,
                },
            },
        [12025901] = {
            ["Content"] = "恩人……谢……谢你…………",
            ["ContentFR"] = "Merci... merci...",
            ["DialogueId"] = 12025901,
            ["GUID"] = "1E1B0762",
            ["NextDialogue"] = 12025902,
            ["SpeakNpcId"] = 210120,
            },
        [12025902] = {
            ["Content"] = "（你眼前的姑娘面色苍白，额头上冒出豆大的汗珠，却还在勉力向你道谢。被狴犴惩戒后，她明显需要休息。）",
            ["ContentFR"] = "La jeune femme devant vous est d’une pâleur extrême. De grosses gouttes de sueur perlent sur son front, et pourtant, elle s’efforce encore de vous remercier. Après avoir subi le châtiment du Bi’an, elle a manifestement besoin de repos.",
            ["DialogueId"] = 12025902,
            ["GUID"] = "1E1B078C",
            ["NextDialogue"] = 12025903,
            },
        [12025903] = {
            ["Content"] = "您放心，您放心，大家都是朋友！我一定把她照顾得妥妥帖帖，一根毫毛都不会伤到！",
            ["ContentFR"] = "Rassurez-vous, rassurez-vous ! Ici, on est entre amis ! Je veillerai sur elle comme sur la prunelle de mes yeux, pas un cheveu ne sera déplacé, je vous le jure !",
            ["DialogueId"] = 12025903,
            ["GUID"] = "1E1B07B6",
            ["NextDialogue"] = 12025904,
            ["SpeakNpcName"] = "UI_Npc_Name_Badshangren",
            },
        [12025904] = {
            ["Content"] = "哎呀，我的{性别：姑爷爷|姑奶奶}，算我求求您，赶紧去见虬先生吧，别让他老人家久等。您们在这里，她也没法安心休息呀。",
            ["ContentFR"] = "Oh, par pitié, je vous en supplie... allez donc voir Maître Qiu. Ne le faites pas attendre trop longtemps. Tant que vous restez ici, elle n’arrivera pas à se reposer tranquillement.",
            ["DialogueId"] = 12025904,
            ["GUID"] = "1E1B07E0",
            ["SpeakNpcName"] = "UI_Npc_Name_Badshangren",
            },
        [12026001] = {
            ["Content"] = "这位荣誉学徒，有什么想向我请教的？",
            ["ContentFR"] = "Alors, honorable {性别:apprenti|apprentie}, qu’est-ce que tu souhaites me demander ?",
            ["DialogueId"] = 12026001,
            ["GUID"] = "1E1B17CA",
            ["NextDialogue"] = 12026025,
            ["SpeakNpcId"] = 210121,
            },
        [12026002] = {
            ["Content"] = "可以再说明一下什么是尘漠吗？",
            ["ContentFR"] = "<I>Peux-tu m’expliquer à nouveau ce qu’est la Poussière-corrompue ?</>",
            ["DialogueId"] = 12026002,
            ["GUID"] = "1E1B17F4",
            ["NextDialogue"] = 12026003,
            },
        [12026003] = {
            ["Content"] = "唉，遥想当初，过目不忘可是入门我机枢派的最基础。资质愚钝者，早在娃娃之时就被刷下去了。",
            ["ContentFR"] = "Ah... autrefois, une mémoire infaillible était la base même pour entrer dans la Secte Jishu. Les esprits trop lents étaient recalés dès l’enfance.",
            ["DialogueId"] = 12026003,
            ["GUID"] = "1E1B181E",
            ["NextDialogue"] = 12026004,
            ["SpeakNpcId"] = 210121,
            },
        [12026004] = {
            ["Content"] = "罢了罢了。做人不能强求，你有这份求知欲，也算是很珍贵了。我就再给你说明一次吧。",
            ["ContentFR"] = "Enfin... inutile de s’acharner. On ne force pas le talent. Ta soif de savoir n’est pas chose commune. Je vais donc te l’expliquer une fois encore.",
            ["DialogueId"] = 12026004,
            ["GUID"] = "1E1B1848",
            ["NextDialogue"] = 12026005,
            ["SpeakNpcId"] = 210121,
            },
        [12026005] = {
            ["Content"] = "这空气中弥漫着一种名为太虚，看不见摸不着的物质。这时你就要问了，既然是看不见摸不着，那怎么确定它存在呢？",
            ["ContentFR"] = "L’air est imprégné d’une substance appelée Taixu, invisible et intangible. Et naturellement, tu te demandes : puisqu’on ne peut ni la voir ni la toucher, comment être certain qu’elle existe ?",
            ["DialogueId"] = 12026005,
            ["GUID"] = "1E1B1872",
            ["NextDialogue"] = 12026006,
            ["SpeakNpcId"] = 210121,
            },
        [12026006] = {
            ["Content"] = "我们研究者自有各种手段去侧面观察它。这尘漠，便是太虚存在的最好佐证——",
            ["ContentFR"] = "Nous, chercheurs, disposons de méthodes pour l’observer indirectement. Et la Poussière-corrompue en est la preuve la plus manifeste—",
            ["DialogueId"] = 12026006,
            ["GUID"] = "1E1B189C",
            ["NextDialogue"] = 12026007,
            ["SpeakNpcId"] = 210121,
            },
        [12026007] = {
            ["Content"] = "空气中的太虚受烛阴之灾影响，其性质发生转变，固化成蒙于物体表面的粉末。这对一般生命有害的粉末便是尘漠。这样一说，你可懂了？",
            ["ContentFR"] = "Sous l’influence du Fléau de Zhuyin, le Taixu présent dans l’air se transforme, se solidifie, et devient cette fine poudre qui se dépose à la surface des objets. Cette substance, nocive pour la plupart des formes de vie, voilà ce que nous appelons la Poussière-corrompue. Est-ce plus clair, à présent ?",
            ["DialogueId"] = 12026007,
            ["GUID"] = "1E1B18C6",
            ["NextDialogue"] = 12026025,
            ["SpeakNpcId"] = 210121,
            },
        [12026008] = {
            ["Content"] = "可以再说明一下牵机方枢的用法吗？",
            ["ContentFR"] = "<I>Peux-tu réexpliquer comment utiliser le Nexus mécanique ?</>",
            ["DialogueId"] = 12026008,
            ["GUID"] = "1E1B18F0",
            ["NextDialogue"] = 12026009,
            },
        [12026009] = {
            ["Content"] = "嗯？我手写的数百页使用说明书与牵机方枢一并存放于秦虬那里，他没有交给你们吗？",
            ["ContentFR"] = "Hmm ? J’ai rédigé des centaines de pages de manuel, conservées avec le Nexus mécanique chez Qin Qiu. Il ne vous les a pas transmises ?",
            ["DialogueId"] = 12026009,
            ["GUID"] = "1E1B191A",
            ["NextDialogue"] = 12026010,
            ["SpeakNpcId"] = 210121,
            },
        [12026010] = {
            ["Content"] = "没有。他只让我来请教你。",
            ["ContentFR"] = "Non. Il m’a simplement envoyé te poser la question.",
            ["DialogueId"] = 12026010,
            ["GUID"] = "1E1B1944",
            ["NextDialogue"] = 12026011,
            ["SpeakNpcId"] = 100001,
            },
        [12026011] = {
            ["Content"] = "……那老东西，我就知道。他一定觉得你会字多不看，没必要把这洋洋洒洒数十万字的说明书交给你。我机枢派的荣誉学徒，能是这种品性的人吗？",
            ["ContentFR"] = "... Ce vieux renard. Je le savais. Il s’est sans doute dit que tu ne lirais pas un manuel aussi long, et qu’il était inutile de te le donner. Comme si {性别:un apprenti d’honneur de la Secte Jishu pouvait être aussi peu sérieux|une apprentie d’honneur de la Secte Jishu pouvait être aussi peu sérieuse} !",
            ["DialogueId"] = 12026011,
            ["GUID"] = "1E1B196E",
            ["NextDialogue"] = 12026012,
            ["SpeakNpcId"] = 210121,
            },
        [12026012] = {
            ["Content"] = "算了，我就简单解说一下吧。很简单，按下这个按钮，对着尘漠，吸。完事了。",
            ["ContentFR"] = "Peu importe. Je vais faire simple. C’est très facile : tu appuies sur ce bouton, tu vises la Poussière-corrompue... et tu aspires. Voilà.",
            ["DialogueId"] = 12026012,
            ["GUID"] = "1E1B1998",
            ["NextDialogue"] = 12026013,
            ["SpeakNpcId"] = 210121,
            },
        [12026013] = {
            ["Content"] = "就这样？",
            ["ContentFR"] = "C’est tout ?",
            ["DialogueId"] = 12026013,
            ["GUID"] = "1E1B19C2",
            ["NextDialogue"] = 12026014,
            ["SpeakNpcId"] = 100001,
            },
        [12026014] = {
            ["Content"] = "就这样。你莫非还要我从原理开始解说不成？",
            ["ContentFR"] = "C’est tout. Tu t’attendais à ce que je t’explique aussi les principes théoriques, peut-être ?",
            ["DialogueId"] = 12026014,
            ["GUID"] = "1E1B19EC",
            ["NextDialogue"] = 12026015,
            ["SpeakNpcId"] = 210121,
            },
        [12026015] = {
            ["Content"] = "没有没有，这样就很好了。谢谢师父！",
            ["ContentFR"] = "Non, non, ça me va très bien comme ça. Merci, maître !",
            ["DialogueId"] = 12026015,
            ["GUID"] = "1E1B1A16",
            ["NextDialogue"] = 12026025,
            },
        [12026016] = {
            ["Content"] = "机枢派为什么没落了？",
            ["ContentFR"] = "<I>Pourquoi la Secte Jishu a-t-elle décliné ?</>",
            ["DialogueId"] = 12026016,
            ["GUID"] = "1E1B1A40",
            ["NextDialogue"] = 12026017,
            },
        [12026017] = {
            ["Content"] = "我机枢派的人，首先要学会用辨证的思维看待事物——何为没落？",
            ["ContentFR"] = "Dans la Secte Jishu, la première chose que l’on apprend, c’est à observer le monde avec un esprit dialectique. Dis-moi donc : qu’appelles-tu un déclin ?",
            ["DialogueId"] = 12026017,
            ["GUID"] = "1E1B1A6A",
            ["NextDialogue"] = 12026018,
            ["SpeakNpcId"] = 210121,
            },
        [12026018] = {
            ["Content"] = "机枢派的造物从南向北遍布整个华胥，哪个码头见不到搬运货物的木走马？天梁司还高居华胥三大司之一，这能叫没落吗？",
            ["ContentFR"] = "Nos créations sont disséminées dans tout Huaxu, du sud au nord. Quel port n’emploie pas des chevaux mécaniques pour le transport des marchandises ? Et le Bureau des Travaux demeure l’un des trois grands bureaux de l’Empire. Appelles-tu cela un déclin ?",
            ["DialogueId"] = 12026018,
            ["GUID"] = "1E1B1A94",
            ["NextDialogue"] = 12026019,
            ["SpeakNpcId"] = 210121,
            },
        [12026019] = {
            ["Content"] = "那个……机枢派没落了招不到学生，好像是你和我说的？",
            ["ContentFR"] = "Euh... mais n’est-ce pas toi qui m’as dit que la Secte Jishu peinait à recruter de nouveaux disciples ?",
            ["DialogueId"] = 12026019,
            ["GUID"] = "1E1B1ABE",
            ["NextDialogue"] = 12026020,
            ["SpeakNpcId"] = 100001,
            },
        [12026020] = {
            ["Content"] = "聪明，这就是辨证思维的另一面了。",
            ["ContentFR"] = "Bien vu. Voilà l’autre facette du raisonnement dialectique.",
            ["DialogueId"] = 12026020,
            ["GUID"] = "1E1B1AE8",
            ["NextDialogue"] = 12026021,
            ["SpeakNpcId"] = 210121,
            },
        [12026021] = {
            ["Content"] = "世人失去了求知欲，无人愿意考入机枢派，天梁司那些老东西只知道闭门造车，不再去穷事物之极理——这是没落。",
            ["ContentFR"] = "Le monde a perdu son désir d’apprendre. Plus personne ne souhaite rejoindre la Secte Jishu. Quant aux vieillards du Bureau des Travaux, ils se contentent de travailler en vase clos, sans plus chercher à comprendre les lois ultimes des choses... voilà le véritable déclin.",
            ["DialogueId"] = 12026021,
            ["GUID"] = "1E1B1B12",
            ["NextDialogue"] = 12026022,
            ["SpeakNpcId"] = 210121,
            },
        [12026022] = {
            ["Content"] = "现在我回答你的问题，机枢派为什么没落？是悬衡派那些家伙干的，因为他们害怕知识带来的力量会超出他们的掌控，所以让机枢派没落了。就这么简单。",
            ["ContentFR"] = "Alors, pourquoi la Secte Jishu a-t-elle décliné ? À cause de la Secte Xuanheng. Ils redoutent que la puissance née du savoir échappe à leur contrôle. Ils ont donc affaibli la Secte Jishu. C’est aussi simple que cela.",
            ["DialogueId"] = 12026022,
            ["GUID"] = "1E1B1B3C",
            ["NextDialogue"] = 12026025,
            ["SpeakNpcId"] = 210121,
            },
        [12026023] = {
            ["Content"] = "还有好多问题，我想想。",
            ["ContentFR"] = "<I>J’ai encore beaucoup de questions... laisse-moi réfléchir.</>",
            ["DialogueId"] = 12026023,
            ["GUID"] = "1E1B1B66",
            ["NextDialogue"] = 12026024,
            },
        [12026024] = {
            ["Content"] = "打破砂锅问到底，是个好苗子。好了，我要忙去了，你也不要疏忽了日常功课啊。",
            ["ContentFR"] = "Tu ne lâches pas prise tant que tu n’as pas compris le fond des choses... voilà un bon potentiel. Bien. J’ai à faire, et toi, n’oublie pas tes exercices quotidiens.",
            ["DialogueId"] = 12026024,
            ["GUID"] = "1E1B1B90",
            ["SpeakNpcId"] = 210121,
            },
        [12026025] = {
            ["DialogueId"] = 12026025,
            ["DialoguePanelType"] = "None",
            ["Duration"] = 0,
            ["FinalDialogueId"] = 12026024,
            ["GUID"] = "1E1B1B91",
            ["NextOptions"] = {
                [1] = 12026002,
                [2] = 12026008,
                [3] = 12026016,
                [4] = 12026023,
                },
            },
        [12026101] = {
            ["Content"] = "瞧瞧是谁来了——原来是帮百年春化解危机的大英雄{nickname}！",
            ["ContentFR"] = "Eh bien, qui voilà — {性别:le grand héros {nickname}, celui|la grande héroïne {nickname}, celle} qui a aidé Éternel Printemps à traverser la crise !",
            ["DialogueId"] = 12026101,
            ["GUID"] = "1E1B2832",
            ["NextDialogue"] = 12026102,
            ["SpeakNpcId"] = 210122,
            },
        [12026102] = {
            ["Content"] = "哪里哪里。我只是做了一些微小的工作，主要还是靠止流掌柜和大家的力量。",
            ["ContentFR"] = "Allons, allons... je n’ai fait que peu de chose. Le mérite revient surtout à la Patronne Zhiliu et à tout le monde ici.",
            ["DialogueId"] = 12026102,
            ["GUID"] = "1E1B285C",
            ["NextDialogue"] = 12026103,
            ["SpeakNpcId"] = 100001,
            },
        [12026103] = {
            ["Content"] = "倒是你经历了这些之后，现在还好吗？",
            ["ContentFR"] = "Et toi ? Après tout ce qui s’est passé, comment te sens-tu ?",
            ["DialogueId"] = 12026103,
            ["GUID"] = "1E1B2886",
            ["NextDialogue"] = 12026104,
            ["SpeakNpcId"] = 100001,
            },
        [12026104] = {
            ["Content"] = "呵呵，说出来不怕你笑话……现在比起后怕，我心里反而激荡着一种能够保卫家园的兴奋感，甚至感觉身体里充满了力量。",
            ["ContentFR"] = "Ha ha... ça va peut-être te faire rire, mais au lieu d’être effrayée après coup, je ressens surtout une étrange exaltation. Avoir pu défendre notre foyer m’a donné l’impression qu’une force nouvelle s’était éveillée en moi.",
            ["DialogueId"] = 12026104,
            ["GUID"] = "1E1B28B0",
            ["NextDialogue"] = 12026105,
            ["SpeakNpcId"] = 210122,
            },
        [12026105] = {
            ["Content"] = "我甚至动了学几招防身手段的念头，这样以后去别的危险地区行商，也不用光等着护卫来保护自己了。",
            ["ContentFR"] = "J’envisage même d’apprendre quelques techniques de défense, histoire de ne plus dépendre uniquement des gardes lorsque je voyagerai dans des régions dangereuses.",
            ["DialogueId"] = 12026105,
            ["GUID"] = "1E1B28DA",
            ["NextDialogue"] = 12026106,
            ["SpeakNpcId"] = 210122,
            },
        [12026106] = {
            ["Content"] = "不过这种念头终归是不符合大风九章的吧……",
            ["ContentFR"] = "Mais... ce genre de pensée n’est sans doute pas conforme aux Neuf Chapitres de Dafeng...",
            ["DialogueId"] = 12026106,
            ["GUID"] = "1E1B2904",
            ["SpeakNpcId"] = 210122,
            },
        [12026201] = {
            ["Content"] = "怎么了，{nickname}？有什么事吗？",
            ["ContentFR"] = "Que se passe-t-il, {nickname} ? Tu voulais me parler ?",
            ["DialogueId"] = 12026201,
            ["GUID"] = "1E1B389A",
            ["NextDialogue"] = 12026202,
            ["SpeakNpcId"] = 210123,
            },
        [12026202] = {
            ["Content"] = "（止流的举止一如往常，但你总觉得她有些不易察觉的疲惫……是错觉吗？）",
            ["ContentFR"] = "L’attitude de Zhiliu ne diffère guère de l’ordinaire. Et pourtant, vous croyez percevoir chez elle une fatigue subtile... Est-ce seulement votre imagination ?",
            ["DialogueId"] = 12026202,
            ["GUID"] = "1E1B38C4",
            ["NextDialogue"] = 12026213,
            },
        [12026203] = {
            ["Content"] = "止流掌柜，你接下来有什么安排？",
            ["ContentFR"] = "<I>Patronne Zhiliu, quels sont vos projets à présent ?</>",
            ["DialogueId"] = 12026203,
            ["GUID"] = "1E1B38EE",
            ["NextDialogue"] = 12026204,
            },
        [12026204] = {
            ["Content"] = "有了你采来的这些烛阴鳞，封印烛阴的准备也算是完毕了。接下来我便要先筹备此事，可能暂时无法分神接待你们了，先说一句抱歉。",
            ["ContentFR"] = "Grâce aux Écailles de Zhuyin que tu as rapportées, les préparatifs pour le scellement sont achevés. Je dois désormais m’y consacrer pleinement. Il se peut donc que je ne puisse pas vous recevoir pendant un temps. Permets-moi de m’en excuser par avance.",
            ["DialogueId"] = 12026204,
            ["GUID"] = "1E1B3918",
            ["NextDialogue"] = 12026205,
            ["SpeakNpcId"] = 210123,
            },
        [12026205] = {
            ["Content"] = "真的不需要我帮忙吗？",
            ["ContentFR"] = "Êtes-vous certaine de ne pas avoir besoin de mon aide ?",
            ["DialogueId"] = 12026205,
            ["GUID"] = "1E1B3942",
            ["NextDialogue"] = 12026206,
            ["SpeakNpcId"] = 100001,
            },
        [12026206] = {
            ["Content"] = "呵呵，你倒是有心了。也不能总让你一个人忙前忙后。若出现了难以搞定的事情，我会再来委托你们的。",
            ["ContentFR"] = "Hé hé... ton intention est louable. Mais je ne peux pas te laisser tout assumer seul.\
Si une situation réellement épineuse se présente, je ferai de nouveau appel à vous.",
            ["DialogueId"] = 12026206,
            ["GUID"] = "1E1B396C",
            ["NextDialogue"] = 12026213,
            ["SpeakNpcId"] = 210123,
            },
        [12026207] = {
            ["Content"] = "刚刚百年春的危机真是凶险。",
            ["ContentFR"] = "<I>La crise qu’a traversée Éternel Printemps était vraiment dangereuse.</>",
            ["DialogueId"] = 12026207,
            ["GUID"] = "1E1B3996",
            ["NextDialogue"] = 12026208,
            },
        [12026208] = {
            ["Content"] = "嗯。这场危机化解也有你的一份功劳。多谢了，{nickname}。",
            ["ContentFR"] = "En effet. Et tu y as largement contribué. Je te remercie, {nickname}.",
            ["DialogueId"] = 12026208,
            ["GUID"] = "1E1B39C0",
            ["NextDialogue"] = 12026209,
            ["SpeakNpcId"] = 210123,
            },
        [12026209] = {
            ["Content"] = "我没做什么，主要还是靠你组织起来了大家，你当时的应对好迅速。",
            ["ContentFR"] = "Je n’ai pas fait grand-chose. C’est vous qui avez su rassembler tout le monde, et réagir avec une telle rapidité.",
            ["DialogueId"] = 12026209,
            ["GUID"] = "1E1B39EA",
            ["NextDialogue"] = 12026210,
            ["SpeakNpcId"] = 100001,
            },
        [12026210] = {
            ["Content"] = "呵呵，做事若是畏手畏脚，瞻前顾后，又怎能负起众人之望呢？",
            ["ContentFR"] = "Hé hé... hésiter à chaque pas, craindre d’agir... comment pourrait-on alors répondre aux attentes de tous ?",
            ["DialogueId"] = 12026210,
            ["GUID"] = "1E1B3A14",
            ["NextDialogue"] = 12026213,
            ["SpeakNpcId"] = 210123,
            },
        [12026211] = {
            ["Content"] = "……",
            ["ContentFR"] = "<I>...</>",
            ["DialogueId"] = 12026211,
            ["GUID"] = "1E1B3A3E",
            ["NextDialogue"] = 12026212,
            },
        [12026212] = {
            ["Content"] = "我要先去筹备封印烛阴的相关事宜了。你现在得了空闲，去逛逛吧。有什么开销记在我账上就行，不用对我客气。",
            ["ContentFR"] = "Je vais maintenant m’occuper des dernières étapes du scellement de Zhuyin. Tu es libre pour le moment : va donc te promener. Tout ce que tu dépenseras sera porté à mon compte. N’aie aucune retenue.",
            ["DialogueId"] = 12026212,
            ["GUID"] = "1E1B3A68",
            ["SpeakNpcId"] = 210123,
            },
        [12026213] = {
            ["DialogueId"] = 12026213,
            ["DialoguePanelType"] = "None",
            ["Duration"] = 0,
            ["FinalDialogueId"] = 12026212,
            ["GUID"] = "1E1B3A69",
            ["NextOptions"] = {
                [1] = 12026203,
                [2] = 12026207,
                [3] = 12026211,
                },
            },
        [12026301] = {
            ["Content"] = "恩人，你来看望我了……",
            ["ContentFR"] = "Merci... m-merci... Vous êtes venu me voir...",
            ["DialogueId"] = 12026301,
            ["GUID"] = "1E1B4902",
            ["NextDialogue"] = 12026302,
            ["SpeakNpcId"] = 210124,
            },
        [12026302] = {
            ["Content"] = "你现在好点了吗？",
            ["ContentFR"] = "Vous sentez-vous un peu mieux ?",
            ["DialogueId"] = 12026302,
            ["GUID"] = "1E1B492C",
            ["NextDialogue"] = 12026303,
            ["SpeakNpcId"] = 100001,
            },
        [12026303] = {
            ["Content"] = "多亏了您和扶疏大人为我采回来的药，现在我的伤势已经稳定，再过一两天就能下床走动了。",
            ["ContentFR"] = "Grâce aux remèdes que vous et Dame Fushu avez rapportés pour moi, mon état s’est stabilisé. D’ici un jour ou deux, je pourrai même me lever et marcher un peu.",
            ["DialogueId"] = 12026303,
            ["GUID"] = "1E1B4956",
            ["NextDialogue"] = 12026304,
            ["SpeakNpcId"] = 210124,
            },
        [12026304] = {
            ["Content"] = "这一遭下来，不知道受了您的多少恩惠……除了言谢之外，我、我想不到别的方式可以报答你。以后有需要我做的，尽管开口，千万不用客气。",
            ["ContentFR"] = "Après tout ce que j’ai traversé... j’ai reçu tant de bonté de votre part... Je... je ne sais pas comment vous rendre la pareille. Si jamais vous avez besoin de moi, dites-le-moi. Je ferai tout ce qui est en mon pouvoir.",
            ["DialogueId"] = 12026304,
            ["GUID"] = "1E1B4980",
            ["SpeakNpcId"] = 210124,
            },
        [12026401] = {
            ["Content"] = "如果你们在瀑布附近看到了受困的无由生，还请施以援手……多谢二位了。",
            ["ContentFR"] = "Si vous croisez des Wishen coincés près de la cascade, je vous en prie, portez-leur secours... Je vous remercie tous les deux.",
            ["DialogueId"] = 12026401,
            ["GUID"] = "1E1B596A",
            ["SpeakNpcId"] = 210125,
            },
        [12026501] = {
            ["Content"] = "多谢二位，失踪的无由生都被救回来了！真是功德一桩呐！",
            ["ContentFR"] = "Merci infiniment. Tous les Wishen disparus ont été sauvés, sains et saufs. Nous vous en sommes profondément reconnaissants.",
            ["DialogueId"] = 12026501,
            ["GUID"] = "1E1B69D2",
            ["SpeakNpcId"] = 210126,
            },
        [12026601] = {
            ["Content"] = "{nickname}，你来了。",
            ["ContentFR"] = "{nickname}, te voilà.",
            ["DialogueId"] = 12026601,
            ["GUID"] = "1E1B7A3A",
            ["NextDialogue"] = 12026602,
            ["SpeakNpcId"] = 210127,
            },
        [12026602] = {
            ["Content"] = "我性喜清净，这枯荣阁中没什么可以用来招待你的，只有半壁医书，一壶茗茶……希望不会使你感到枯燥。",
            ["ContentFR"] = "J’ai toujours préféré le calme. En ces lieux du Pavillon de l’Éphémère, je n’ai rien de bien luxueux pour te recevoir : quelques traités médicaux, une théière... J’espère que cela ne t’ennuiera pas.",
            ["DialogueId"] = 12026602,
            ["GUID"] = "1E1B7A64",
            ["NextDialogue"] = 12026603,
            ["SpeakNpcId"] = 210127,
            },
        [12026603] = {
            ["Content"] = "你可以随意走动，把这里当做自己家一般便好。",
            ["ContentFR"] = "Tu peux te promener librement. Considère cet endroit comme ta propre demeure.",
            ["DialogueId"] = 12026603,
            ["GUID"] = "1E1B7A8E",
            ["NextDialogue"] = 12026640,
            ["SpeakNpcId"] = 210127,
            },
        [12026604] = {
            ["Content"] = "除了治病救人，你在闲暇时间还会做些什么？",
            ["ContentFR"] = "<I>En dehors de soigner les gens, que fais-tu pendant ton temps libre ?</>",
            ["DialogueId"] = 12026604,
            ["GUID"] = "1E1B7AB8",
            ["NextDialogue"] = 12026605,
            },
        [12026605] = {
            ["Content"] = "照料病人往往已占据我大部分时间。若是偷得浮生半日闲……我许是会研究家姐留下的医书吧。",
            ["ContentFR"] = "Prendre soin des patients occupe la majeure partie de mes journées. Si, par hasard, il m’arrive de voler quelques instants de répit... je relis les ouvrages médicaux que ma sœur a laissés derrière elle.",
            ["DialogueId"] = 12026605,
            ["GUID"] = "1E1B7AE2",
            ["NextDialogue"] = 12026606,
            ["SpeakNpcId"] = 210127,
            },
        [12026606] = {
            ["Content"] = "那不还是治病救人吗？！",
            ["ContentFR"] = "Mais... c’est encore soigner des gens, non ?",
            ["DialogueId"] = 12026606,
            ["GUID"] = "1E1B7B0C",
            ["NextDialogue"] = 12026607,
            ["SpeakNpcId"] = 100001,
            },
        [12026607] = {
            ["Content"] = "若是病人就在眼前，我往往心思急切，无法沉下心去研究药理关联。反倒是漫无目的翻开某页医书，细细研究其晦涩之语时，能体会到一种茅塞顿开的喜悦。",
            ["ContentFR"] = "Lorsque le malade est devant moi, mon esprit s’agite et peine à se poser. Il m’est alors difficile d’étudier sereinement les liens subtils entre les remèdes. En revanche, ouvrir un livre au hasard, m’attarder sur ses passages obscurs... et soudain comprendre — cette sensation-là est une joie à part entière.",
            ["DialogueId"] = 12026607,
            ["GUID"] = "1E1B7B36",
            ["NextDialogue"] = 12026608,
            ["SpeakNpcId"] = 210127,
            },
        [12026608] = {
            ["Content"] = "你就没有这之外的爱好了吗？",
            ["ContentFR"] = "Tu n’as vraiment pas d’autres loisirs ?",
            ["DialogueId"] = 12026608,
            ["GUID"] = "1E1B7B60",
            ["NextDialogue"] = 12026609,
            ["SpeakNpcId"] = 100001,
            },
        [12026609] = {
            ["Content"] = "待我想想……抚上一首琴曲，或是与云螭嬉戏，这都是我少时的乐趣。",
            ["ContentFR"] = "Laisse-moi réfléchir... jouer quelques airs au qin, ou passer du temps à m’amuser avec Yunchi. C’étaient là les plaisirs de ma jeunesse.",
            ["DialogueId"] = 12026609,
            ["GUID"] = "1E1B7B8A",
            ["NextDialogue"] = 12026610,
            ["SpeakNpcId"] = 210127,
            },
        [12026610] = {
            ["Content"] = "那下次弹首琴曲给我听吧。",
            ["ContentFR"] = "Alors, la prochaine fois, joue-moi un morceau.",
            ["DialogueId"] = 12026610,
            ["GUID"] = "1E1B7BB4",
            ["NextDialogue"] = 12026611,
            ["SpeakNpcId"] = 100001,
            },
        [12026611] = {
            ["Content"] = "……是了，我怎么忘了呢。最大的乐趣还是与友人共处，无论赏曲或是谈天说地，都别有一份逸趣。",
            ["ContentFR"] = "... Oui. Comment ai-je pu l’oublier ? Le plus grand des plaisirs reste finalement la compagnie d’un ami. Qu’il s’agisse d’écouter de la musique ou de discuter librement, tout cela a une saveur particulière.",
            ["DialogueId"] = 12026611,
            ["GUID"] = "1E1B7BDE",
            ["NextDialogue"] = 12026612,
            ["SpeakNpcId"] = 210127,
            },
        [12026612] = {
            ["Content"] = "{nickname}，你随时可以来枯荣阁找我打发闲暇。我会很乐意你来访。",
            ["ContentFR"] = "{nickname}, tu peux venir me rendre visite ici quand tu le souhaites. Ta présence me fera plaisir.",
            ["DialogueId"] = 12026612,
            ["GUID"] = "1E1B7C08",
            ["NextDialogue"] = 12026613,
            ["SpeakNpcId"] = 210127,
            },
        [12026613] = {
            ["Content"] = "那就一言为定！",
            ["ContentFR"] = "Marché conclu !",
            ["DialogueId"] = 12026613,
            ["GUID"] = "1E1B7C32",
            ["NextDialogue"] = 12026640,
            ["SpeakNpcId"] = 100001,
            },
        [12026614] = {
            ["Content"] = "我最近有些不舒服。",
            ["ContentFR"] = "<I>Ces derniers temps, je ne me sens pas très bien.</>",
            ["DialogueId"] = 12026614,
            ["GUID"] = "1E1B7C5C",
            ["NextDialogue"] = 12026615,
            },
        [12026615] = {
            ["Content"] = "怎么了？哪里痛，还是在烟津渡奔行时不慎受伤了？快把手递给我，我帮你细细查探一番。",
            ["ContentFR"] = "Que se passe-t-il ? As-tu mal quelque part ? Te serais-tu {性别:blessé|blessée} en courant dans Port-des-Brumes ? Donne-moi ta main, je vais examiner cela attentivement.",
            ["DialogueId"] = 12026615,
            ["GUID"] = "1E1B7C86",
            ["NextDialogue"] = 12026616,
            ["SpeakNpcId"] = 210127,
            },
        [12026616] = {
            ["Content"] = "噗嗤，扶疏，你好紧张。",
            ["ContentFR"] = "Haha... Fushu, tu es vraiment tendue.",
            ["DialogueId"] = 12026616,
            ["GUID"] = "1E1B7CB0",
            ["NextDialogue"] = 12026617,
            ["SpeakNpcId"] = 100001,
            },
        [12026617] = {
            ["Content"] = "没有那么严重，只是睡醒时常常感觉腰酸背痛而已。",
            ["ContentFR"] = "Rien de grave, je me réveille juste souvent avec le dos et les épaules endoloris.",
            ["DialogueId"] = 12026617,
            ["GUID"] = "1E1B7CDA",
            ["NextDialogue"] = 12026618,
            ["SpeakNpcId"] = 100001,
            },
        [12026618] = {
            ["Content"] = "健康乃大事，就算是小病小痛也不可随意对待。我这里有一套强身健体的五禽戏可以传授于你，助你活络筋骨。",
            ["ContentFR"] = "La santé est une affaire sérieuse. Même les petits maux ne doivent pas être négligés. Je peux t’enseigner les Cinq Jeux des Animaux, une pratique qui assouplit le corps et renforce la vitalité.",
            ["DialogueId"] = 12026618,
            ["GUID"] = "1E1B7D04",
            ["NextDialogue"] = 12026619,
            ["SpeakNpcId"] = 210127,
            },
        [12026619] = {
            ["Content"] = "为了充分领略五禽的形意，这套拳法须在鸡犬鸣叫，夜色将褪未褪之时开始练习。待到旭阳将出，清风拂面，你必定能感受到锻炼带来的身心舒畅……",
            ["ContentFR"] = "Pour en saisir pleinement l’esprit, cet exercice doit commencer à l’aube, lorsque les coqs chantent et que la nuit n’a pas encore tout à fait cédé sa place. Quand le soleil se lèvera et que la brise du matin effleurera ton visage, tu ressentiras un bien-être profond, du corps comme de l’esprit...",
            ["DialogueId"] = 12026619,
            ["GUID"] = "1E1B7D2E",
            ["NextDialogue"] = 12026620,
            ["SpeakNpcId"] = 210127,
            },
        [12026620] = {
            ["Content"] = "不、不用了！",
            ["ContentFR"] = "N-non, ça ira !",
            ["DialogueId"] = 12026620,
            ["GUID"] = "1E1B7D58",
            ["NextDialogue"] = 12026621,
            ["SpeakNpcId"] = 100001,
            },
        [12026621] = {
            ["Content"] = "我又想了想，我很好，再好不过了，我从来没有这么健康过！所以你的好意我就心领了，千万不用实践。",
            ["ContentFR"] = "En y repensant, je vais très bien. Même mieux que jamais ! Je n’ai jamais été aussi en forme de toute ma vie. Alors... merci pour ta proposition, mais inutile de la mettre en pratique !",
            ["DialogueId"] = 12026621,
            ["GUID"] = "1E1B7D82",
            ["NextDialogue"] = 12026622,
            ["SpeakNpcId"] = 100001,
            },
        [12026622] = {
            ["Content"] = "唉，你呀……",
            ["ContentFR"] = "<I>Soupir...</> franchement.",
            ["DialogueId"] = 12026622,
            ["GUID"] = "1E1B7DAC",
            ["NextDialogue"] = 12026623,
            ["SpeakNpcId"] = 210127,
            },
        [12026623] = {
            ["Content"] = "这次便让你逃过去了。但若再遇到身体不适的情况，千万不要硬撑，我会为你排忧解难。",
            ["ContentFR"] = "Très bien, pour cette fois, je te laisse t’en tirer ainsi. Mais si tu te sens de nouveau mal, ne fais pas preuve d’un courage inutile. Viens me voir, je m’en occuperai.",
            ["DialogueId"] = 12026623,
            ["GUID"] = "1E1B7DD6",
            ["NextDialogue"] = 12026640,
            ["SpeakNpcId"] = 210127,
            },
        [12026624] = {
            ["Content"] = "你离开往隙之后好像有什么烦恼。",
            ["ContentFR"] = "<I>Depuis que tu es revenue de la Faille de l’Oubli, quelque chose semble te tracasser.</>",
            ["DialogueId"] = 12026624,
            ["GUID"] = "1E1B7E00",
            ["NextDialogue"] = 12026625,
            },
        [12026625] = {
            ["Content"] = "这也被你察觉到了……多谢你牵挂着我。",
            ["ContentFR"] = "Tu l’as remarqué... Merci de t’en soucier.",
            ["DialogueId"] = 12026625,
            ["GUID"] = "1E1B7E2A",
            ["NextDialogue"] = 12026626,
            ["SpeakNpcId"] = 210127,
            },
        [12026626] = {
            ["Content"] = "{nickname}，你也有对你而言意义重大的家人吧。倘若你犯下了言语过失，伤了那人的心，你会怎么做？",
            ["ContentFR"] = "{nickname}, toi aussi, tu as sans doute des proches qui comptent plus que tout pour toi. Si, par maladresse, tu disais quelque chose qui blessait l’un d’eux... que ferais-tu ?",
            ["DialogueId"] = 12026626,
            ["GUID"] = "1E1B7E54",
            ["NextDialogue"] = 12026627,
            ["SpeakNpcId"] = 210127,
            },
        [12026627] = {
            ["Content"] = "既然是家人，肯定不会有化解不了的矛盾。我想如果有一天真的发生了那种事情，我会很努力地去道歉，那样她一定会接受的。",
            ["ContentFR"] = "Quand il s’agit de la famille, aucun conflit n’est impossible à résoudre. Si cela arrivait, je ferais tout pour m’excuser. Je suis {性别:sûr|sûre} qu’elle finirait par me pardonner.",
            ["DialogueId"] = 12026627,
            ["GUID"] = "1E1B7E7E",
            ["NextDialogue"] = 12026628,
            ["SpeakNpcId"] = 100001,
            },
        [12026628] = {
            ["Content"] = "但若是伊人已逝，此时再想道歉，也无人聆听……那又该如何是好？",
            ["ContentFR"] = "Et si cette personne n’était plus de ce monde... si tes excuses n’avaient plus d’oreille pour les entendre... que ferais-tu alors ?",
            ["DialogueId"] = 12026628,
            ["GUID"] = "1E1B7EA8",
            ["NextDialogue"] = 12026629,
            ["SpeakNpcId"] = 210127,
            },
        [12026629] = {
            ["Content"] = "扶疏…………",
            ["ContentFR"] = "Fushu...",
            ["DialogueId"] = 12026629,
            ["GUID"] = "1E1B7ED2",
            ["NextDialogue"] = 12026630,
            ["SpeakNpcId"] = 100001,
            },
        [12026630] = {
            ["Content"] = "抱歉。不小心竟将自己的愁绪强加于你了。",
            ["ContentFR"] = "Pardonne-moi. Je n’aurais pas dû t’imposer mes propres tourments.",
            ["DialogueId"] = 12026630,
            ["GUID"] = "1E1B7EFC",
            ["NextDialogue"] = 12026631,
            ["SpeakNpcId"] = 210127,
            },
        [12026631] = {
            ["Content"] = "没关系，如果你有什么不开心的，都可以来和我说，我随时在这里。",
            ["ContentFR"] = "Ce n’est rien. Si quelque chose te pèse, viens m’en parler. Je serai toujours là.",
            ["DialogueId"] = 12026631,
            ["GUID"] = "1E1B7F26",
            ["NextDialogue"] = 12026640,
            ["SpeakNpcId"] = 100001,
            },
        [12026632] = {
            ["Content"] = "你真的是百年之前的人吗？",
            ["ContentFR"] = "<I>Tu viens vraiment d’il y a cent ans ?</>",
            ["DialogueId"] = 12026632,
            ["GUID"] = "1E1B7F50",
            ["NextDialogue"] = 12026633,
            },
        [12026633] = {
            ["Content"] = "嗯……如我先前所说，家姐为了延缓我的疾病进程，将我的躯体冻结。直至最近，我才被从百年的沉眠中唤醒。",
            ["ContentFR"] = "Oui... Comme je te l’ai déjà expliqué, afin de ralentir l’évolution de ma maladie, ma sœur a scellé mon corps dans le sommeil. Ce n’est que récemment que je me suis éveillée après cent années de torpeur.",
            ["DialogueId"] = 12026633,
            ["GUID"] = "1E1B7F7A",
            ["NextDialogue"] = 12026634,
            ["SpeakNpcId"] = 210127,
            },
        [12026634] = {
            ["Content"] = "这个世界会让你感到陌生吗？",
            ["ContentFR"] = "Ce monde te paraît-il étranger, désormais ?",
            ["DialogueId"] = 12026634,
            ["GUID"] = "1E1B7FA4",
            ["NextDialogue"] = 12026635,
            ["SpeakNpcId"] = 100001,
            },
        [12026635] = {
            ["Content"] = "或许吧。我刚刚醒来时，只感觉这世上的云卷云舒，一草一木，都不再和我有半分关联。",
            ["ContentFR"] = "Peut-être. À mon réveil, j’avais l’impression que les nuages, les herbes, chaque chose sous le ciel... n’avaient plus rien à voir avec moi.",
            ["DialogueId"] = 12026635,
            ["GUID"] = "1E1B7FCE",
            ["NextDialogue"] = 12026636,
            ["SpeakNpcId"] = 210127,
            },
        [12026636] = {
            ["Content"] = "但随着时间发展，我也慢慢结识了你这样的友人。",
            ["ContentFR"] = "Mais avec le temps, j’ai fini par rencontrer des {性别:amis|amies} comme toi.",
            ["DialogueId"] = 12026636,
            ["GUID"] = "1E1B7FF8",
            ["NextDialogue"] = 12026637,
            ["SpeakNpcId"] = 210127,
            },
        [12026637] = {
            ["Content"] = "现今世间百态，抑或是医理发展，都使我感到新奇。换个角度来看，也是一件幸事。",
            ["ContentFR"] = "Les multiples visages du monde actuel, tout comme les progrès de la médecine, éveillent en moi une certaine curiosité. En y regardant autrement... c’est aussi une chance.",
            ["DialogueId"] = 12026637,
            ["GUID"] = "1E1B8022",
            ["NextDialogue"] = 12026640,
            ["SpeakNpcId"] = 210127,
            },
        [12026638] = {
            ["Content"] = "我先走了。",
            ["ContentFR"] = "<I>Je vais y aller.</>",
            ["DialogueId"] = 12026638,
            ["GUID"] = "1E1B804C",
            ["NextDialogue"] = 12026639,
            },
        [12026639] = {
            ["Content"] = "你且去忙吧，注意身体。",
            ["ContentFR"] = "Va t’occuper de tes affaires. Et prends soin de ta santé.",
            ["DialogueId"] = 12026639,
            ["GUID"] = "1E1B8076",
            ["SpeakNpcId"] = 210127,
            },
        [12026640] = {
            ["DialogueId"] = 12026640,
            ["DialoguePanelType"] = "None",
            ["Duration"] = 0,
            ["FinalDialogueId"] = 12026639,
            ["GUID"] = "1E1B8077",
            ["NextOptions"] = {
                [1] = 12026604,
                [2] = 12026614,
                [3] = 12026624,
                [4] = 12026632,
                [5] = 12026638,
                },
            },
        [12026701] = {
            ["Content"] = "咿呀，咿咿呀，咿！",
            ["ContentFR"] = "Yi—ya... yi-yi—ya... yi !",
            ["DialogueId"] = 12026701,
            ["GUID"] = "1E1B8AA2",
            ["NextDialogue"] = 12026702,
            ["SpeakNpcId"] = 210128,
            },
        [12026702] = {
            ["Content"] = "（它跟在扶疏身边，好像很开心的样子。）",
            ["ContentFR"] = "<I>Il flotte près de Fushu, l’air visiblement heureux.</>",
            ["DialogueId"] = 12026702,
            ["GUID"] = "1E1B8ACC",
            ["SpeakNpcId"] = 100001,
            },
        [12026801] = {
            ["Content"] = "猎物已经入网，此时行事须格外慎重，切忌打草惊蛇。",
            ["ContentFR"] = "La proie est déjà prise au filet. À partir de maintenant, chaque geste doit être mesuré. Surtout, ne l’alarmez pas.",
            ["DialogueId"] = 12026801,
            ["GUID"] = "1E1B9B0A",
            ["NextDialogue"] = 12026802,
            },
        [12026802] = {
            ["Content"] = "{nickname}，你若已经准备好了，我们就继续向前吧。",
            ["ContentFR"] = "{nickname}, si tu es {性别:prêt|prête}, poursuivons.",
            ["DialogueId"] = 12026802,
            ["GUID"] = "1E1B9B34",
            },
        [12026901] = {
            ["Content"] = "如果我没有猜错，这上古机括战阵，其真名为千枢狩阵。取千枢为引，万隙囚光之意。",
            ["ContentFR"] = "Si mon intuition est juste, cette antique formation mécanique porte le nom de Formation des Mille-Serrures. Mille pivots pour amorcer le piège, dix mille interstices pour emprisonner jusqu’à la lumière elle-même.",
            ["DialogueId"] = 12026901,
            ["GUID"] = "1E1BAB72",
            ["NextDialogue"] = 12026902,
            },
        [12026902] = {
            ["Content"] = "古物于我们面前重焕生机……不觉得这景象很壮观吗？",
            ["ContentFR"] = "Voir une relique antique reprendre vie sous nos yeux... n’est-ce pas un spectacle grandiose ?",
            ["DialogueId"] = 12026902,
            ["GUID"] = "1E1BAB9C",
            },
        [12027001] = {
            ["Content"] = "您可以去尘漠石海最高处的位置，那里通往烛阴祭坛的临时道路已经搭建完毕。",
            ["ContentFR"] = "Vous pouvez vous rendre au point culminant de la Mer de Poussière. La voie provisoire menant à l’Autel de Zhuyin est désormais achevée.",
            ["DialogueId"] = 12027001,
            ["GUID"] = "1E1BBBDA",
            ["NextDialogue"] = 12027002,
            ["SpeakNpcId"] = 210129,
            },
        [12027002] = {
            ["Content"] = "封印仪式一旦开启，烛阴极有可能受刺激狂化。祭坛周围危机四伏，不可大意。",
            ["ContentFR"] = "Une fois le rituel de scellement engagé, Zhuyin risque d’entrer en frénésie. Les abords de l’autel seront extrêmement dangereux. Soyez sur vos gardes.",
            ["DialogueId"] = 12027002,
            ["GUID"] = "1E1BBC04",
            ["NextDialogue"] = 12027003,
            ["SpeakNpcId"] = 210129,
            },
        [12027003] = {
            ["Content"] = "狩月人，您务必要小心，您的安危才是第一位的。我在这里等待您顺利归来。",
            ["ContentFR"] = "{性别:Chasseur de Phoxène|Chasseuse de Phoxène}, prenez soin de vous. Votre sécurité est notre priorité absolue. Je resterai ici et attendrai votre retour sain et sauf.",
            ["DialogueId"] = 12027003,
            ["GUID"] = "1E1BBC2E",
            ["SpeakNpcId"] = 210129,
            },
        [12027101] = {
            ["Content"] = "姐姐不在菱生身边了……但是姐姐现在很高兴，菱生能感觉得到。",
            ["ContentFR"] = "Ma sœur n’est plus auprès de Lingsheng... Mais elle est heureuse, maintenant. Lingsheng peut le sentir.",
            ["DialogueId"] = 12027101,
            ["GUID"] = "1E1BCC42",
            ["SpeakNpcId"] = 210130,
            },
        [12030001] = {
            ["Content"] = "那是不久之前，发生在冰湖城的一段故事——",
            ["ContentFR"] = "Il n’y a pas si longtemps, à Givrelac, une petite histoire a pris racine...",
            ["DialogueId"] = 12030001,
            ["Duration"] = 4,
            ["GUID"] = "1E1DA80A",
            ["NextDialogue"] = 12030002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DA80A",
            },
        [12030002] = {
            ["Content"] = "当一只小夜莺，决定勇敢地飞出它温暖的巢穴。",
            ["ContentFR"] = "Celle d’un rossignol minuscule, qui, un jour, trouva le courage de quitter son nid chaud et étroit... pour s’élancer dans le vaste monde.",
            ["DialogueId"] = 12030002,
            ["Duration"] = 4,
            ["GUID"] = "1E1DA834",
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DA834",
            },
        [12030003] = {
            ["Content"] = "菲娜坐在家里，看着故事书",
            ["DialogueId"] = 12030003,
            ["GUID"] = "1E1DA85E",
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DA85E",
            },
        [12030101] = {
            ["Content"] = "菲娜，晚上光线太暗，看书伤眼睛，还是早点睡吧。",
            ["DialogueId"] = 12030101,
            ["GUID"] = "1E1DB872",
            ["NextDialogue"] = 12030102,
            ["SpeakNpcId"] = 211002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DB872",
            },
        [12030102] = {
            ["Content"] = "唔……",
            ["DialogueId"] = 12030102,
            ["GUID"] = "1E1DB89C",
            ["NextDialogue"] = 12030103,
            ["SpeakNpcId"] = 211001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DB89C",
            },
        [12030103] = {
            ["Content"] = "怎么了？",
            ["DialogueId"] = 12030103,
            ["GUID"] = "1E1DB8C6",
            ["NextDialogue"] = 12030104,
            ["SpeakNpcId"] = 211002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DB8C6",
            },
        [12030104] = {
            ["Content"] = "奥特赛德，菲娜……菲娜有一个愿望！",
            ["DialogueId"] = 12030104,
            ["GUID"] = "1E1DB8F0",
            ["NextDialogue"] = 12030105,
            ["SpeakNpcId"] = 211001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DB8F0",
            },
        [12030105] = {
            ["Content"] = "是吗？你说，是什么愿望？",
            ["DialogueId"] = 12030105,
            ["GUID"] = "1E1DB91A",
            ["NextDialogue"] = 12030106,
            ["SpeakNpcId"] = 211002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DB91A",
            },
        [12030106] = {
            ["Content"] = "菲娜想出去看看。",
            ["DialogueId"] = 12030106,
            ["GUID"] = "1E1DB944",
            ["NextDialogue"] = 12030107,
            ["SpeakNpcId"] = 211001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DB944",
            },
        [12030107] = {
            ["Content"] = "出去……？现在吗？",
            ["DialogueId"] = 12030107,
            ["GUID"] = "1E1DB96E",
            ["NextDialogue"] = 12030108,
            ["SpeakNpcId"] = 211002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DB96E",
            },
        [12030108] = {
            ["Content"] = "不是的，菲娜的意思是，菲娜也想像你和独角兽{性别：先生|小姐}一样，去外面的世界，认识很多的新朋友……",
            ["DialogueId"] = 12030108,
            ["GUID"] = "1E1DB998",
            ["NextDialogue"] = 12030109,
            ["SpeakNpcId"] = 211001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DB998",
            },
        [12030109] = {
            ["Content"] = "这可不行，外面很危险的。我和{nickname}大多数时候遇到的都不是朋友，而是秽——怪兽，和很多坏——坏巫师，对，那些坏巫师可吓人了。",
            ["DialogueId"] = 12030109,
            ["GUID"] = "1E1DB9C2",
            ["NextDialogue"] = 12030110,
            ["SpeakNpcId"] = 211002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DB9C2",
            },
        [12030110] = {
            ["Content"] = "所以，你还是待在家里最安全。",
            ["DialogueId"] = 12030110,
            ["GUID"] = "1E1DB9EC",
            ["NextDialogue"] = 12030111,
            ["SpeakNpcId"] = 211002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DB9EC",
            },
        [12030111] = {
            ["Content"] = "呜……",
            ["DialogueId"] = 12030111,
            ["GUID"] = "1E1DBA16",
            ["SpeakNpcId"] = 211001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DBA16",
            },
        [12030112] = {
            ["Content"] = "转场，菲娜在睡觉，奥特赛德看到桌上的故事书",
            ["ContentFR"] = "Nuit — Intérieur de la maison de Fina.\
Fina dort paisiblement. L’Étranger remarque sur la table un livre d’histoires ouvert, laissé par Fina.",
            ["DialogueId"] = 12030112,
            ["GUID"] = "1E1DBA40",
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DBA40",
            },
        [12030201] = {
            ["Camera"] = "-345.501678,523.378906,124.574219,0.000322,-4.833527,90.822472,35.000008,77.550713,false,Manual,4.0",
            ["Content"] = "“大魔法师总是说，巢穴外的世界充满了危险，呆在巢穴里才是最安全的……可是小小的巢穴虽然温暖，却只能看到一小片方形的天空。”",
            ["ContentFR"] = "« Le Grand Magicien répétait sans cesse : le monde au-delà du nid est rempli de dangers, rester à l’intérieur est la seule sécurité. Mais ce nid, aussi chaud soit-il, n’offrait qu’un carré de ciel. »",
            ["DialogueId"] = 12030201,
            ["FinalCamera"] = "-351.068237,428.320312,123.277344,0.000143,-3.242031,91.01268,35.000008,212.663025,false,Manual,2.8",
            ["GUID"] = "1E1DC8DA",
            ["LookAt"] = {
                [1] = "211002:p(pFeina_FixSimple02_LookAt01)",
                },
            ["NextDialogue"] = 12030202,
            ["TalkActionId"] = {
                [1] = "211024:Feina_Story_Lieidle",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DC8DA",
            },
        [12030202] = {
            ["Camera"] = "-351.068237,428.320312,123.277344,0.000143,-3.242031,91.01268,35.000008,212.663025,false,Manual,2.8",
            ["Content"] = "“有一天，从很远很远的地方漂流而来的独角兽{性别：先生|小姐}来到了小夜莺的巢穴，为小夜莺捎来了远方的故事……”",
            ["ContentFR"] = "« Un jour, {性别:Monsieur|Mademoiselle} Licorne venue de contrées lointaines vint rendre visite au Rossignol, lui apportant des récits des horizons perdus... »",
            ["DialogueId"] = 12030202,
            ["FinalCamera"] = "-445.522095,482.669922,106.667969,0.000118,8.757859,54.209782,35.000008,212.663025,false,Manual,2.8",
            ["GUID"] = "1E1DC904",
            ["NextDialogue"] = 12030203,
            ["ToFinalCameraBlendTime"] = 7,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DC904",
            },
        [12030203] = {
            ["Camera"] = "-93.792816,296.109375,123.785156,0.000262,-14.836967,-25.180407,28.0,180.0,false,Manual,3.5",
            ["Content"] = "“在巢穴之外那广阔的世界里，有枝条能挂在月亮上的大树，有怀抱着一百座小岛的大海……”",
            ["ContentFR"] = "« Un monde immense où des arbres dressaient leurs branches jusqu’à accrocher la lune, et où l’océan portait cent îles dans son étreinte... »",
            ["DialogueId"] = 12030203,
            ["FinalCamera"] = "-93.792816,296.109375,123.785156,0.000261,-34.236603,-38.179943,28.000006,63.699184,false,Manual,3.5",
            ["GUID"] = "1E1DC92E",
            ["NextDialogue"] = 12030204,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DC92E",
            },
        [12030204] = {
            ["Camera"] = "-93.792816,296.109375,123.785156,0.000249,-34.236633,-38.180016,28.0,180.0,false,Manual,3.5",
            ["Content"] = "“小夜莺也好想飞到大树的枝头，和每一朵绽放的花打招呼，去小松鼠的家里做客……”",
            ["ContentFR"] = "« Le petit Rossignol rêvait d’aller saluer les fleurs épanouies, de visiter la demeure des écureuils, de se percher sur les branches baignées de lune... »",
            ["DialogueId"] = 12030204,
            ["FinalCamera"] = "-222.147125,357.158203,220.230469,0.000264,-30.234377,-29.18161,35.0,180.0,false,Manual,3.5",
            ["GUID"] = "1E1DC958",
            ["NextDialogue"] = 12030205,
            ["Scripts"] = "SEQ{LookAt{LookAtDescription{\"211002:p(pFeina_FixSimple02_LookAt01)\"}}}",
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DC958",
            },
        [12030205] = {
            ["Camera"] = "-139.631927,210.423828,144.097656,0.000295,7.366509,66.22287,35.0,112.741165,false,Manual,4.0",
            ["Content"] = "“想乘上柔软的云，和掠过高空的海燕并肩翱翔，和跃出海面的鱼儿一起嬉戏……”",
            ["ContentFR"] = "« Il voulait chevaucher les nuages, voler aux côtés des hirondelles de mer, et plonger dans les vagues avec les poissons bondissants... »",
            ["DialogueId"] = 12030205,
            ["GUID"] = "1E1DC982",
            ["NextDialogue"] = 12030206,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DC982",
            },
        [12030206] = {
            ["Content"] = "……",
            ["ContentFR"] = "...",
            ["DialogueId"] = 12030206,
            ["GUID"] = "1E1DC9AC",
            ["SpeakNpcId"] = 211002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DC9AC",
            },
        [12030207] = {
            ["Content"] = "转场，白天",
            ["DialogueId"] = 12030207,
            ["GUID"] = "1E1DC9D6",
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DC9D6",
            },
        [12030300] = {
            ["Camera"] = "-201.678467,47.8125,111.152344,0.000102,20.154959,-60.375671,28.0,293.312073,false,Manual,2.8",
            ["DialogueId"] = 12030300,
            ["FinalCamera"] = "-214.884705,6.785156,112.378906,0.00011,6.354692,-2.17627,28.0,125.074371,false,Manual,2.8",
            ["GUID"] = "1E1DD941",
            ["NextDialogue"] = 12030301,
            ["ToFinalCameraBlendTime"] = 5,
            },
        [12030301] = {
            ["Camera"] = "-214.884705,6.785156,112.378906,0.00011,6.354692,-2.17627,28.0,125.074371,false,Manual,2.8",
            ["Content"] = "菲娜。",
            ["ContentFR"] = "Fina.",
            ["DialogueId"] = 12030301,
            ["FinalCamera"] = "-214.884705,6.785156,112.378906,0.00011,6.354692,-2.17627,28.0,324.258209,false,Manual,2.8",
            ["GUID"] = "1E1DD942",
            ["NextDialogue"] = 12030302,
            ["Scripts"] = "LookAt{LookAtDescription{\"211002:n(211001)\"}},\
",
            ["SpeakNpcId"] = 211002,
            ["ToFinalCameraBlendTime"] = 2,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DD942",
            },
        [12030302] = {
            ["Camera"] = "53.489204,-49.375,131.65625,0.000106,-4.241547,154.817291,35.0,172.252792,false,Manual,2.8",
            ["Content"] = "奥特赛德？你今天怎么回来得这么早……发生什么事了吗？",
            ["ContentFR"] = "L’Étranger ? Tu rentres si tôt aujourd’hui... Il s’est passé quelque chose ?",
            ["DialogueId"] = 12030302,
            ["FinalCamera"] = "26.751808,-36.806641,129.472656,0.00011,-4.24154,154.817642,35.0,132.363815,false,Manual,2.8",
            ["GUID"] = "1E1DD96C",
            ["NextDialogue"] = 12030303,
            ["Scripts"] = "SEQ{\
LookAt{LookAtDescription{\"211001:n(211002)\"}},\
PlayFacial{_delay{1.5},ActorId{211001},FacialId{\"Happy01\"}},\
PlayAnimation{_delay{1.5},ActorId{211001},AnimationId{\"Shy01_Start\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 211001,
            ["ToFinalCameraBlendTime"] = 10,
            ["TurnTo"] = {
                [1] = "211001:p(40)",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DD96C",
            },
        [12030303] = {
            ["Camera"] = "-10.235954,65.589844,155.683594,0.000051,-1.24011,-35.390144,35.000008,286.639435,false,Manual,2.8",
            ["Content"] = "确实有一件重要的事——今天是新手魔法师菲娜的第一次冒险之旅，我特地回来给她加油鼓劲。",
            ["ContentFR"] = "Non, rien de grave. Au contraire ! Aujourd’hui, c’est spécial : Fina, notre apprentie magicienne, part pour sa toute première aventure. Alors je me suis dit... fallait bien que je sois là pour l’encourager.",
            ["DialogueId"] = 12030303,
            ["FinalCamera"] = "4.515831,55.119141,155.300781,0.000051,-1.24011,-35.390144,35.000008,286.639435,false,Manual,2.8",
            ["GUID"] = "1E1DD996",
            ["NextDialogue"] = 12030304,
            ["Scripts"] = "PlayAnimation{ActorId{211002},AnimationId{\"ConfidentR_Start\"},Duration{1}}",
            ["SpeakNpcId"] = 211002,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DD996",
            },
        [12030304] = {
            ["Camera"] = "80.626434,-20.03125,162.339844,0.000114,-10.841299,166.216843,55.000008,178.363068,false,Manual,2.8",
            ["Content"] = "咦？",
            ["ContentFR"] = "Hein... ?",
            ["DialogueId"] = 12030304,
            ["GUID"] = "1E1DD9C0",
            ["NextDialogue"] = 12030305,
            ["Scripts"] = "PARA{\
PlayFacial{_delay{0.1},ActorId{211001},FacialId{\"None\"}},\
PlayAnimation{ActorId{211001},AnimationId{\"Shy01_End\"},Duration{1}},\
PlayAnimation{ActorId{211001},AnimationId{\"TilteHead_Start\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 211001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DD9C0",
            },
        [12030305] = {
            ["Camera"] = "-108.768295,398.734375,113.765625,0.000063,0.559174,-73.189148,28.0,366.148499,false,Manual,2.8",
            ["Content"] = "我看了你写的故事，你很想去外面的世界看看，对吧？我同意了，你现在就可以出门去冒险啦。",
            ["ContentFR"] = "J’ai lu ton histoire. Tu veux découvrir le monde, pas vrai ? Alors, c’est décidé : tu peux sortir. Ton aventure commence maintenant.",
            ["DialogueId"] = 12030305,
            ["FinalCamera"] = "-97.715012,362.148438,114.128906,0.000063,0.559174,-73.189117,28.000006,366.148499,false,Manual,2.8",
            ["GUID"] = "1E1DD9EA",
            ["NextDialogue"] = 12030306,
            ["Scripts"] = "\
SEQ{\
PlayAnimation{ActorId{211002},AnimationId{\"ConfidentRToExplain_Start\"},Duration{1}},\
PlayAnimation{ActorId{211001},AnimationId{\"TilteHead_End\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 211002,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DD9EA",
            },
        [12030306] = {
            ["Camera"] = "52.159672,-22.074219,168.640625,0.000079,-14.240568,163.610046,55.0,154.192795,false,Manual,2.8",
            ["Content"] = "可是，你不是说外面很危险，还有很多坏巫师吗……？",
            ["ContentFR"] = "Mais... tu n’avais pas dit qu’il y avait plein de dangers dehors ? Des... mauvais sorciers... ?",
            ["DialogueId"] = 12030306,
            ["FinalCamera"] = "37.80537,-17.855469,164.851562,0.000084,-14.240541,163.610001,55.0,138.46257,false,Manual,2.8",
            ["GUID"] = "1E1DDA14",
            ["NextDialogue"] = 12030307,
            ["Scripts"] = "PARA{\
PlayAnimation{ActorId{211001},AnimationId{\"Shy02_Start\"},Duration{1}},\
PlayFacial{ActorId{211001},FacialId{\"Sad01\"}}\
}\
\
",
            ["SpeakNpcId"] = 211001,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DDA14",
            },
        [12030307] = {
            ["Camera"] = "53.723839,-28.212891,158.828125,0.000089,-2.841516,-22.7857,28.000008,150.228668,false,Manual,2.8",
            ["Content"] = "不用担心，我这个“大魔法师”已经给你使用了最厉害的守护魔法，坏巫师根本不敢靠近。",
            ["ContentFR"] = "Ne t’inquiète pas. Moi, le \"Grand Magicien\", j’ai placé sur toi mon sort de protection le plus puissant. Ces sorciers n’oseront même pas s’approcher.",
            ["DialogueId"] = 12030307,
            ["FinalCamera"] = "68.022377,-34.214844,158.117188,0.000089,-2.6415,-22.785671,28.000008,150.228668,false,Manual,2.8",
            ["GUID"] = "1E1DDA3E",
            ["NextDialogue"] = 12030308,
            ["Scripts"] = "PARA{\
PlayAnimation{ActorId{211002},AnimationId{\"DisagreeHead\"},Duration{1}},\
PlayAnimation{ActorId{211002},AnimationId{\"ConfidentRToExplain_End\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 211002,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DDA3E",
            },
        [12030308] = {
            ["Content"] = "不过，就像故事书里说的，魔法不是永久的——所以你只能在白天出门，而且也不能走得太远，否则魔法就会失效了。",
            ["ContentFR"] = "Seulement voilà : la magie, ça ne dure pas éternellement. Tu pourras sortir pendant la journée, mais pas trop loin. Sinon, le sort disparaîtra.",
            ["DialogueId"] = 12030308,
            ["FinalCamera"] = "74.63475,-33.244141,159.617188,0.000087,-1.641288,-22.979761,28.000006,146.329025,false,Manual,2.8",
            ["GUID"] = "1E1DDA68",
            ["NextDialogue"] = 12030309,
            ["Scripts"] = "PlayAnimation{ActorId{211002},AnimationId{\"Talk02_Start\"},Duration{1}}",
            ["SpeakNpcId"] = 211002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DDA68",
            },
        [12030309] = {
            ["Camera"] = "68.511589,-59.673828,134.019531,0.000108,-2.441301,153.218155,55.0,178.363068,false,Manual,2.8",
            ["Content"] = "……好！",
            ["ContentFR"] = "... D’accord !",
            ["DialogueId"] = 12030309,
            ["FacialId"] = {
                [1] = "211001:Happy01",
                },
            ["GUID"] = "1E1DDA92",
            ["Scripts"] = "PARA{\
LookAt{LookAtDescription{\"211001:n(211002)\"}},\
PlayAnimation{ActorId{211001},AnimationId{\"Feina_Story_Wish_Start\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 211001,
            ["TalkActionId"] = {
                [1] = "211001:AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DDA92",
            },
        [12030310] = {
            ["Content"] = "菲娜拿着魔法书出门，奥特赛德看着她离开，随后主角入镜",
            ["ContentFR"] = "(Fina attrape son grimoire et sort en courant. L’Étranger la regarde s’éloigner. Le protagoniste entre dans le champ.)",
            ["DialogueId"] = 12030310,
            ["GUID"] = "1E1DDABC",
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DDABC",
            },
        [12030400] = {
            ["Camera"] = "1266.484619,-178.583984,366.181152,0.000043,-9.398552,-176.39032,35.000011,100000.0,false,Manual,4.0",
            ["Content"] = "冰湖城，上午【临时】",
            ["DialogueId"] = 12030400,
            ["Duration"] = 8,
            ["FinalCamera"] = "1301.278198,-365.192383,256.428711,0.000054,-9.198332,163.00029,35.000011,622.412903,false,Manual,4.0",
            ["GUID"] = "1E1DE9A9",
            ["NextDialogue"] = 12030401,
            ["ToFinalCameraBlendTime"] = 8,
            },
        [12030401] = {
            ["Camera"] = "1305.487793,-265.864258,306.96875,0.00014,-3.399658,179.117737,35.000008,272.126312,false,Manual,22.0",
            ["Content"] = "接下来就交给你了。",
            ["ContentFR"] = "À toi de jouer, maintenant.",
            ["DialogueId"] = 12030401,
            ["FinalCamera"] = "1354.122437,-266.613281,197.483887,0.00014,-2.999628,179.117737,35.000008,272.126312,false,Manual,22.0",
            ["GUID"] = "1E1DE9AA",
            ["NextDialogue"] = 12030402,
            ["Scripts"] = "PlayAnimation{ActorId{211001},AnimationId{\"Feina_Story_Look01_Start\"},Duration{1}}",
            ["SpeakNpcId"] = 211002,
            ["ToFinalCameraBlendTime"] = 3,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DE9AA",
            },
        [12030402] = {
            ["Camera"] = "699.66394,-379.948242,204.811523,0.000031,-5.9989,24.603928,35.000011,249.091507,false,Manual,4.0",
            ["Content"] = "你大概也猜到了，菲娜在过去经历过一些……很复杂的事情。虽说都过去了，但我还是有点担心她会被什么人认出来，引来不必要的麻烦。",
            ["ContentFR"] = "Tu l’as sûrement deviné : Fina a traversé... des choses compliquées. Même si tout cela est derrière elle, je crains toujours qu’on la reconnaisse et que des ennuis surgissent.",
            ["DialogueId"] = 12030402,
            ["FinalCamera"] = "729.398315,-366.335938,201.375,0.000031,-5.9989,24.603533,35.000011,249.091507,false,Manual,4.0",
            ["GUID"] = "1E1DE9D4",
            ["NextDialogue"] = 12030403,
            ["SpeakNpcId"] = 211002,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DE9D4",
            },
        [12030403] = {
            ["Content"] = "你为什么不自己跟着她呢？",
            ["ContentFR"] = "Et pourquoi ne pas l’accompagner toi-même ?",
            ["DialogueId"] = 12030403,
            ["GUID"] = "1E1DE9FE",
            ["NextDialogue"] = 12030404,
            ["Scripts"] = "LookAt{LookAtDescription{\"100001:n(211002)\"}}",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DE9FE",
            },
        [12030404] = {
            ["Camera"] = "775.80603,-164.087891,170.229492,0.000074,3.000078,-28.687651,39.289318,212.725189,false,Manual,2.8",
            ["Content"] = "毕竟是小朋友的娱乐活动，我跟着也不太合适……",
            ["ContentFR"] = "Parce que c’est une aventure d’enfant. Si je reste collé à elle, ça n’a plus de sens...",
            ["DialogueId"] = 12030404,
