            ["SpeakNpcId"] = 211002,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DEA7C",
            },
        [12030407] = {
            ["Content"] = "我看她挺喜欢你这个“独角兽{性别：先生|小姐}”的，你就当帮我个忙嘛，我的好队长！",
            ["ContentFR"] = "Et puis... elle t’aime bien, toi. « {性别:Monsieur|Mademoiselle} Licorne ». Alors fais-moi plaisir : prends soin d’elle, Capitaine.",
            ["DialogueId"] = 12030407,
            ["GUID"] = "1E1DEAA6",
            ["NextDialogue"] = 12030408,
            ["Scripts"] = "PlayAnimation{ActorId{211002},AnimationId{\"Talk02_Start\"},Duration{1}}",
            ["SpeakNpcId"] = 211002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DEAA6",
            },
        [12030408] = {
            ["Camera"] = "854.199219,-325.050781,195.624023,0.000087,-9.39987,37.314049,39.289318,140.252518,false,Manual,2.8",
            ["Content"] = "我可不是免费的哦。",
            ["ContentFR"] = "Je ne travaille pas gratuitement, tu sais.",
