            ["Content"] = "“吸血鬼妹妹”是什么？",
            ["ContentFR"] = "C’est quoi, une « sœur vampire » ?",
            ["DialogueId"] = 12030501,
            ["FacialId"] = {
                [1] = "211001:Think01",
                },
            ["FinalCamera"] = "511.094238,354.519531,386.642578,0.000122,-21.799442,-144.886139,35.000011,1094.441895,false,Manual,15.0",
            ["GUID"] = "1E1DFA12",
