            ["SpeakNpcId"] = 211010,
            ["ToFinalCameraBlendTime"] = 15,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DFA12",
            },
        [12030502] = {
            ["Content"] = "就是奥特赛德的妹妹呀！我从来没见过她出门。只有吸血鬼才会不敢出门吧？",
            ["ContentFR"] = "Ben, sa sœur ! Je l’ai jamais vue dehors. Les vampires, eux, n’osent pas sortir le jour, non ?",
            ["DialogueId"] = 12030502,
            ["GUID"] = "1E1DFA3C",
            ["NextDialogue"] = 12030503,
            ["Scripts"] = "PARA{\
LookAt{LookAtDescription{\"211011:n(211010)\"}},\
