}",
            ["SpeakNpcId"] = 211011,
            ["TalkActionId"] = {
                [1] = "211011:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DFA3C",
            },
        [12030503] = {
            ["Content"] = "真的吗？真的是吸血鬼吗？那她可以帮忙数清楚我们那些石子一共有几颗吗？我总觉得最近每天都会变少……",
            ["ContentFR"] = "Vraiment ? Tu crois que c’est une vraie vampire ? Tu crois qu’elle peut compter mes cailloux ? J’en perds tous les jours...",
            ["DialogueId"] = 12030503,
            ["GUID"] = "1E1DFA66",
            ["NextDialogue"] = 12030504,
            ["Scripts"] = "PlayAnimation{ActorId{211011},AnimationId{\"Explain01_End\"},Duration{1}}",
            ["SpeakNpcId"] = 211010,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DFA66",
            },
        [12030504] = {
            ["Camera"] = "-350.497559,574.898438,120.862305,0.000087,-5.199591,-70.882019,35.000015,1094.441895,false,Manual,15.0",
            ["Content"] = "可、可是……你不是说她从来不出门吗？现在她不是出来了……？",
            ["ContentFR"] = "M-Mais... si elle sort jamais, pourquoi elle est là maintenant... ?",
            ["DialogueId"] = 12030504,
            ["FinalCamera"] = "-328.568359,511.637695,114.770508,0.000087,-5.199591,-70.882019,35.000015,1094.441895,false,Manual,15.0",
            ["GUID"] = "1E1DFA90",
            ["NextDialogue"] = 12030505,
            ["Scripts"] = "LookAt{LookAtDescription{\"211011:n(211011)\"}}",
            ["SpeakNpcId"] = 211013,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DFA90",
            },
        [12030505] = {
            ["Content"] = "这个嘛……说不定她现在变得厉害了，就不怕出门了！",
            ["ContentFR"] = "Peut-être qu’elle est devenue super forte, et que le soleil ne lui fait plus peur !",
            ["DialogueId"] = 12030505,
