            ["Camera"] = "-21.348633,155.701172,136.172852,0.000172,-8.198392,-103.282524,24.419487,1094.441895,false,Manual,15.0",
            ["Content"] = "可是，如果你不是吸血鬼，为什么从来不出门呀？",
            ["ContentFR"] = "Mais... si t’es pas une vampire, pourquoi tu ne sors jamais ?",
            ["DialogueId"] = 12030512,
