        [12030514] = {
            ["Content"] = "什么，那也太可怜了吧……生病很难受的！",
            ["ContentFR"] = "Quoi ? Mais c’est trop triste ! Être malade, ça doit être horrible...",
            ["DialogueId"] = 12030514,
            ["GUID"] = "1E1DFC34",
