            },
        [12030515] = {
            ["Camera"] = "-59.737305,82.518555,113.938965,0.000173,-7.798696,-146.279343,24.419483,1094.441895,false,Manual,15.0",
            ["Content"] = "我妈妈说过，身体不好就应该多运动。",
            ["ContentFR"] = "Ma maman dit que si on est faible, faut faire du sport.",
            ["DialogueId"] = 12030515,
            ["GUID"] = "1E1DFC5E",
            ["NextDialogue"] = 12030516,
            ["SpeakNpcId"] = 211010,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DFC5E",
            },
        [12030516] = {
            ["Camera"] = "-59.737305,82.518555,113.938965,0.000173,-7.798696,-146.279343,24.419483,1094.441895,false,Manual,15.0",
            ["Content"] = "没错没错，菲娜姐姐，你只要你每天早上起来先绕着广场跑一百圈，身体肯定很快就会好起来的！",
            ["ContentFR"] = "Exactement ! Fina, si tu cours cent tours de la place chaque matin, tu seras vite en pleine forme !",
            ["DialogueId"] = 12030516,
            ["FinalCamera"] = "-59.737305,82.518555,113.938965,0.000178,-6.998655,-109.679207,24.419483,1094.441895,false,Manual,15.0",
            ["GUID"] = "1E1DFC88",
            ["NextDialogue"] = 12030517,
            ["SpeakNpcId"] = 211011,
            ["TalkActionId"] = {
                [1] = "211011:Agree",
                },
            ["ToFinalCameraBlendTime"] = 1,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DFC88",
            },
        [12030517] = {
            ["Camera"] = "-139.903809,-349.098633,119.885742,0.000172,-4.79846,81.120529,24.419483,1094.441895,false,Manual,15.0",
            ["Content"] = "啊……呵呵，谢谢你们的建议。不过，我不擅长跑步，只能在这附近走一走啦。",
            ["ContentFR"] = "Ah... héhé... merci du conseil. Mais courir, je... je ne peux pas. Marcher un peu ici, c’est déjà beaucoup pour moi.",
            ["DialogueId"] = 12030517,
            ["GUID"] = "1E1DFCB2",
            ["NextDialogue"] = 12030518,
            ["Scripts"] = "SEQ{\
