}",
            ["SpeakNpcId"] = 211001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DFCB2",
            },
        [12030518] = {
            ["Camera"] = "-123.172852,164.339844,119.664062,0.000143,-2.398284,-53.487343,24.419483,1094.441895,false,Manual,15.0",
            ["Content"] = "那……菲娜姐姐，你要不要和我们一起玩？玩应该也算一种运动吧……？",
            ["ContentFR"] = "Alors... Fina, tu veux jouer avec nous ? Jouer, c’est aussi du sport, non ?",
            ["DialogueId"] = 12030518,
