        [12030520] = {
            ["Camera"] = "-45.714355,-177.095703,117.589355,0.000137,-0.198854,82.011528,35.000019,218.878983,false,Manual,2.8",
            ["Content"] = "好呀！可是，“贪吃鬼”是什么游戏？我可能不会玩……",
            ["ContentFR"] = "D’accord ! Mais... c’est quoi, le \"Glouton\" ?",
            ["DialogueId"] = 12030520,
            ["FinalCamera"] = "-43.980469,-164.746094,117.545898,0.000137,-0.198854,82.011528,35.000019,218.878983,false,Manual,2.8",
