            ["SpeakNpcId"] = 211001,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DFEFE",
            },
        [12030532] = {
            ["Content"] = "转场，小孩们消失，出现三个调查点（没有先后顺序）",
            ["DialogueId"] = 12030532,
            ["GUID"] = "1E1DFF28",
