            ["DialogueId"] = 12030605,
            ["GUID"] = "1E1E0B22",
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1E0B22",
            },
        [12030610] = {
            ["Content"] = "这只是一块松动的木板……",
            ["ContentFR"] = "Oh... ce n’est qu’une planche branlante.",
            ["DialogueId"] = 12030610,
            ["GUID"] = "1E1E0BF4",
            ["SpeakNpcId"] = 211001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1E0BF4",
            },
        [12030615] = {
            ["Content"] = "调查第二处地点",
            ["ContentFR"] = "Point d’intérêt n° 2",
            ["DialogueId"] = 12030615,
            ["GUID"] = "1E1E0CC6",
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1E0CC6",
            },
        [12030620] = {
            ["Content"] = "嗯？小姑娘，有啥事吗？",
            ["ContentFR"] = "Hein ? Petite, tu veux quelque chose ?",
            ["DialogueId"] = 12030620,
            ["GUID"] = "1E1E0D98",
            ["NextDialogue"] = 12030621,
            ["SpeakNpcId"] = 211016,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1E0D98",
            },
        [12030621] = {
            ["Content"] = "抱歉，我找错人了……",
            ["ContentFR"] = "Ah ! Désolée... je t’ai pris pour une patate grillée...",
            ["DialogueId"] = 12030621,
            ["GUID"] = "1E1E0DC2",
            ["SpeakNpcId"] = 211001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1E0DC2",
            },
        [12030625] = {
            ["Content"] = "调查第三处地点",
            ["ContentFR"] = "Point d’intérêt n° 3",
            ["DialogueId"] = 12030625,
            ["GUID"] = "1E1E0E6A",
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1E0E6A",
            },
        [12030630] = {
            ["Content"] = "喵~~",
            ["ContentFR"] = "Miaouuu.",
            ["DialogueId"] = 12030630,
            ["GUID"] = "1E1E0F3C",
            ["NextDialogue"] = 12030631,
            ["SpeakNpcId"] = 211008,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1E0F3C",
            },
        [12030631] = {
            ["Content"] = "好可爱的小猫……喵喵~~啊，我要找的是烤土豆，差点忘记了！",
            ["ContentFR"] = "Oh, quel joli petit chat... Miaou, miaou... Ah ! Mais non, je dois chercher les patates grillées ! J’allais oublier !",
            ["DialogueId"] = 12030631,
            ["GUID"] = "1E1E0F66",
            ["SpeakNpcId"] = 211001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1E0F66",
            },
        [12030635] = {
            ["Content"] = "彩蛋调查点（放在比较远的某个墙角之类的地方，不挂指引）",
            ["ContentFR"] = "Point bonus caché : interaction avec le protagoniste",
            ["DialogueId"] = 12030635,
            ["GUID"] = "1E1E100E",
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1E100E",
            },
        [12030640] = {
            ["Content"] = "咦？独角兽{性别：先生|小姐}，你怎么在这里呀？",
            ["ContentFR"] = "Hein ? {性别:Monsieur|Mademoiselle} Licorne ? Qu’est-ce que tu fais là ?",
            ["DialogueId"] = 12030640,
            ["GUID"] = "1E1E10E0",
            ["SpeakNpcId"] = 211001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1E10E0",
            },
        [12030641] = {
            ["Content"] = "啊哈哈……菲娜，你好呀！我、我在这附近散步呢，好巧啊~",
            ["ContentFR"] = "Haha... Salut, Fina ! Je... je me promenais par ici. Quelle coïncidence, pas vrai ?",
            ["DialogueId"] = 12030641,
            ["GUID"] = "1E1E110A",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1E110A",
            },
        [12030642] = {
            ["Content"] = "原来是这样！很高兴见到你，不过，菲娜现在正在玩游戏。下次有机会我们再一起办茶会吧！",
            ["ContentFR"] = "Je vois ! Ravie de te croiser. Mais Fina joue à un jeu en ce moment. La prochaine fois, on fera un vrai goûter ensemble, d’accord ?",
            ["DialogueId"] = 12030642,
            ["GUID"] = "1E1E1134",
            ["SpeakNpcId"] = 211001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1E1134",
            },
        [12030643] = {
            ["Content"] = "嗯，好呀！",
            ["ContentFR"] = "Avec plaisir !",
            ["DialogueId"] = 12030643,
            ["GUID"] = "1E1E115E",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1E115E",
            },
        [12030645] = {
            ["Content"] = "三处调查完毕后",
            ["ContentFR"] = "(Les trois points d’intérêt sont explorés. L’écran s’assombrit légèrement.)",
            ["DialogueId"] = 12030645,
            ["GUID"] = "1E1E11B2",
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1E11B2",
            },
        [12030650] = {
            ["Content"] = "就这样，三分钟过去了……",
            ["ContentFR"] = "Et comme ça... trois minutes s’étaient déjà écoulées.",
