            },
        [12030901] = {
            ["Camera"] = "-69.249512,169.701172,119.054199,0.000114,2.200639,-59.584778,35.000011,113.605156,false,DoNotOverride,6.0",
            ["Content"] = "可是，故事里的主人公们总是充满勇气，无论遇到怎样的困难，都会和伙伴们一起克服……",
            ["ContentFR"] = "Mais dans les histoires... les héros n’abandonnent jamais. Peu importe les obstacles, avec leurs amis, ils trouvent toujours la force d’aller plus loin !",
            ["DialogueId"] = 12030901,
            ["GUID"] = "1E1E3BB2",
            ["NextDialogue"] = 12030902,
            ["Scripts"] = "PARA{\
PlayAnimation{ActorId{211001},AnimationId{\"Feina_Story_Wish_Start\"}},\
PlayFacial{ActorId{211001},FacialId{\"Think01\"}}\
}",
            ["SpeakNpcId"] = 211001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1E3BB2",
            },
        [12030902] = {
            ["Camera"] = "21.739258,184.106445,139.543457,0.000111,-7.199613,-110.180969,35.000011,113.605156,false,DoNotOverride,6.0",
            ["Content"] = "对了，伙伴！可以让菲娜的魔法朋友们来帮忙——大魔法师有着世界上最灵敏的鼻子，它一定可以帮我找到烤土豆的！",
            ["ContentFR"] = "Mais oui ! Des amis... Je peux demander de l’aide à mes amis magiques !\
Le Grand Magicien a le meilleur flair du monde entier... Lui, il saura retrouver ces patates grillées !",
            ["DialogueId"] = 12030902,
            ["GUID"] = "1E1E3BDC",
            ["NextDialogue"] = 12030903,
            ["Scripts"] = "SEQ{\
PARA{\
PlayAnimation{ActorId{211001},AnimationId{\"Feina_Story_Wish_End\"}},\
