        [12031101] = {
            ["Camera"] = "-402.343262,-349.166992,121.742188,0.000108,-5.19998,44.100159,35.000015,650.0,false,DoNotOverride,2.8",
            ["Content"] = "菲娜姐姐，你太厉害啦！第二次就吃掉了所有的烤土豆，你是世界上最厉害的贪吃鬼！",
            ["ContentFR"] = "Fina, tu es incroyable ! À ta deuxième partie, tu as croqué toutes les patates grillées ! Tu es la meilleure Gloutonne du monde !",
            ["DialogueId"] = 12031101,
            ["GUID"] = "1E1E5C82",
            ["LookAt"] = {
                [1] = "211011:n(211001)",
                [2] = "211001:n(211011)",
                [3] = "211010:n(211011)",
                [4] = "211013:n(211011)",
