            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1E5C82",
            },
        [12031102] = {
            ["Content"] = "我们再玩一局吧！",
            ["ContentFR"] = "Allez, encore une partie !",
            ["DialogueId"] = 12031102,
