        [12031104] = {
            ["Camera"] = "-604.65625,-135.828125,147.184082,0.000134,-7.399895,11.497485,35.000023,429.699768,false,DoNotOverride,2.8",
            ["Content"] = "菲娜姐姐，你以后也会来和我们玩吗？除了贪吃鬼，还有很多好玩的游戏……",
            ["ContentFR"] = "Fina, tu reviendras jouer avec nous, dis ? On connaît plein d’autres jeux que le Glouton...",
            ["DialogueId"] = 12031104,
            ["GUID"] = "1E1E5D00",
            ["LookAt"] = {
