PlayFacial{_delay{3},ActorId{211001},FacialId{\"Smile01\"}}\
}",
            ["SpeakNpcId"] = 211003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/1E1E7FC8",
            },
        [12031317] = {
            ["Camera"] = "-124.683594,50.607422,131.177734,0.000107,-7.000397,-33.257271,35.000015,231.188461,false,DoNotOverride,4.5",
            ["Content"] = "那么，“小助手”该做些什么呢？",
            ["ContentFR"] = "Alors... qu’est-ce que doit faire un Petit Assistant ?",
            ["DialogueId"] = 12031317,
            ["GUID"] = "1E1E7FF2",
