        [12031323] = {
            ["Content"] = "调查垃圾桶1（小垃圾桶）\
（这里如果想细节一些的话可以给地图上所有垃圾桶编个号，用于设计与玛尔洁相关的内容。不方便的话确保大小和文案描述一致就行了）",
            ["DialogueId"] = 12031323,
            ["GUID"] = "1E1E80EE",
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/1E1E80EE",
            },
        [12031350] = {
            ["Content"] = "湛蓝的天空【补充需求】",
            ["DialogueId"] = 12031350,
            ["GUID"] = "1E1E80EF",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 211001,
