        [12031501] = {
            ["Camera"] = "82.075974,-10.556297,110.049805,0.000183,0.601678,154.418808,35.000011,112.418152,false,DoNotOverride,12.0",
            ["Content"] = "小助手，你回来啦！快看，我又找到了一张带记号的报纸！这张报纸上写着剧院的广告，说不定强盗们的目标就是剧院。",
            ["ContentFR"] = "Te revoilà, Petit Assistant ! Regarde, moi j’ai trouvé un nouveau morceau de journal marqué d’un signe ! Et il y a une annonce pour une pièce de théâtre... Peut-être que les bandits visent le théâtre !",
            ["DialogueId"] = 12031501,
            ["GUID"] = "1E1E9E22",
            ["NextDialogue"] = 12031502,
