        [12031803] = {
            ["Camera"] = "-36.706543,9.34668,118.760742,0.000082,0.200609,152.505569,35.000011,130.228043,false,Manual,2.8",
            ["Content"] = "让我看看……这是一张地图呀！嗯……没错，就是这个记号。这和我之前找到的那张留言纸的材质一样，墨水颜色和笔迹也很相似。",
            ["ContentFR"] = "Laisse-moi voir... Ah ! C’est une carte ! Et ce signe... c’est le même que celui de mon autre indice. Le papier, l’encre, l’écriture... tout correspond !",
            ["DialogueId"] = 12031803,
            ["FinalCamera"] = "-51.039062,16.806396,118.817383,0.000082,0.000601,154.106216,35.000011,122.117645,false,Manual,2.8",
            ["GUID"] = "1E1ECFAE",
            ["NextDialogue"] = 12031804,
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{211003},AnimationId{\"Talk03_End\"},Duration{1}},\
PlayAnimation{ActorId{211003},AnimationId{\"Think_Start\"},Duration{1}},\
}",
            ["SpeakNpcId"] = 211003,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/1E1ECFAE",
            },
        [12031804] = {
            ["Content"] = "这上面标的是一条路线……？终点的位置在……这儿……难道说那就是他们的老巢？怪不得一直抓不住他们，原来是躲在城外啊！",
            ["ContentFR"] = "Regarde : cette ligne trace une route... et elle mène jusqu’ici. Attends... ce serait donc leur repaire ?! Pas étonnant qu’on ne les trouve jamais : ils se cachaient hors de la cité !",
            ["DialogueId"] = 12031804,
            ["GUID"] = "1E1ECFD8",
            ["NextDialogue"] = 12031805,
            ["Scripts"] = "PARA{\
PlayAnimation{ActorId{211003},AnimationId{\"Think_End\"},Duration{1}},\
PlayAnimation{ActorId{211003},AnimationId{\"AgreeHead\"},Duration{1}},\
PlayFacial{ActorId{211003},FacialId{\"Happy02\"}}\
}",
            ["SpeakNpcId"] = 211003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/1E1ECFD8",
            },
        [12031805] = {
            ["Content"] = "哼哼，小贼们，遇上本侦探，你们的好日子到头啦！我这就把线索交到治安署，把你们一网打尽！",
            ["ContentFR"] = "Héhéhé... Sales bandits, vos beaux jours sont finis ! Je vais livrer ça tout droit au Bureau de la Sécurité, et ils vous cueilleront tous d’un coup !",
            ["DialogueId"] = 12031805,
            ["GUID"] = "1E1ED002",
            ["NextDialogue"] = 12031806,
            ["Scripts"] = "PARA{\
PlayFacial{ActorId{211003},FacialId{\"None\"}},\
PlayAnimation{ActorId{211003},AnimationId{\"Confident_Start\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 211003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/1E1ED002",
            },
        [12031806] = {
            ["Camera"] = "-217.098145,47.609619,126.262695,0.000084,-4.199432,5.707355,35.000011,214.995621,false,Manual,2.8",
            ["Content"] = "小助手帮上缄默侦探的忙了吗？",
            ["ContentFR"] = "Alors... le Petit Assistant a été utile à la Détective Taciturne ?",
            ["DialogueId"] = 12031806,
            ["FinalCamera"] = "-206.445801,48.674194,125.477295,0.000084,-4.199432,5.707355,35.000011,214.995621,false,Manual,2.8",
            ["GUID"] = "1E1ED02C",
            ["NextDialogue"] = 12031807,
            ["SpeakNpcId"] = 211001,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/1E1ED02C",
            },
        [12031807] = {
            ["Camera"] = "238.666504,-163.661255,141.348145,0.000059,-5.199768,140.709946,35.000008,347.691833,false,Manual,8.0",
            ["Content"] = "当然啦，你帮了大忙呢！你是全冰湖城最厉害的小助手！",
            ["ContentFR"] = "Mais bien sûr ! Tu as été d’une aide précieuse. Tu es le meilleur Petit Assistant de tout Givrelac !",
            ["DialogueId"] = 12031807,
            ["GUID"] = "1E1ED056",
            ["NextDialogue"] = 12031808,
            ["Scripts"] = "\
PARA{\
PlayAnimation{ActorId{211003},AnimationId{\"Confident_End\"},Duration{1}},\
PlayAnimation{ActorId{211003},AnimationId{\"AgreeHead\"},Duration{1}},\
PlayFacial{ActorId{211003},FacialId{\"Happy01\"}}\
}",
            ["SpeakNpcId"] = 211003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/1E1ED056",
            },
        [12031808] = {
            ["Camera"] = "-171.109375,35.464111,115.783936,0.000085,-2.999511,5.50795,35.000011,172.605789,false,Manual,2.8",
            ["Content"] = "嘿嘿，其实我也有自己的小助手。多亏独角兽{性别：先生|小姐}的帮忙，我才找到了线索~",
            ["ContentFR"] = "Héhé... En fait, moi aussi j’avais un assistant. Grâce à {性别:Monsieur|Mademoiselle} Licorne, j’ai trouvé l’indice !",
            ["DialogueId"] = 12031808,
            ["GUID"] = "1E1ED080",
            ["NextDialogue"] = 12031809,
            ["Scripts"] = "SEQ{\
CameraMoveTo{_delay{1.5},TargetPosition{\"-169.878418,37.34729,116.223877,0.000086,-2.599365,35.30759,35.000011,172.605789,false,Manual,2.8\"},duration{0}},\
PlayAnimation{ActorId{211001},AnimationId{\"Explain01_Start\"},Duration{1}},\
PlayFacial{ActorId{211001},FacialId{\"Happy02\"}}\
}",
            ["SpeakNpcId"] = 211001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/1E1ED080",
            },
        [12031809] = {
            ["Camera"] = "175.731934,-151.405518,105.219238,0.000091,0.200432,138.907959,35.000008,302.772858,false,Manual,8.0",
            ["Content"] = "原来你还有这样的独家本领！看来你做小助手有点屈才呀，也许我们应该称呼你为——“童话侦探”！怎么样？",
            ["ContentFR"] = "Quoi ?! Tu as donc tes propres talents exclusifs ? Franchement, tu mérites mieux que le titre de simple assistant. À partir de maintenant, je t’appelle... la Détective des Contes de Fées ! Qu’en dis-tu ?",
            ["DialogueId"] = 12031809,
            ["GUID"] = "1E1ED0AA",
            ["NextDialogue"] = 12031810,
            ["Scripts"] = "PlayFacial{ActorId{211003},FacialId{\"Happy02\"}}",
            ["SpeakNpcId"] = 211003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/1E1ED0AA",
            },
        [12031810] = {
            ["Camera"] = "-407.130859,-297.810669,217.47583,0.000089,-17.199884,50.907177,24.0,302.772858,false,Manual,8.0",
            ["Content"] = "“童话侦探”……这是菲娜的新称号吗？我很喜欢！",
            ["ContentFR"] = "La... Détective des Contes de Fées ? C’est mon nouveau titre ? Oh, j’adore !",
            ["DialogueId"] = 12031810,
            ["FinalCamera"] = "-438.524414,-336.450806,232.88623,0.00009,-16.999876,50.907589,24.0,302.772858,false,Manual,8.0",
            ["GUID"] = "1E1ED0D4",
            ["NextDialogue"] = 12031811,
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{211001},AnimationId{\"Explain01_End\"},Duration{1}},\
PlayAnimation{ActorId{211001},AnimationId{\"AgreeHead\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 211001,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/1E1ED0D4",
            },
        [12031811] = {
            ["Content"] = "那么，“童话侦探”，我的朋友——让我们在下一个案件再会吧！本缄默侦探要趁治安署下班之前赶紧去报案啦。",
            ["ContentFR"] = "Alors, Détective des Contes de Fées, mon amie... à la prochaine enquête ! Moi, je file avant la fermeture du Bureau de la Sécurité !",
            ["DialogueId"] = 12031811,
            ["GUID"] = "1E1ED0FE",
            ["NextDialogue"] = 12031812,
            ["SpeakNpcId"] = 211003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/1E1ED0FE",
            },
        [12031812] = {
            ["Content"] = "好！",
            ["ContentFR"] = "Bonne chance !",
            ["DialogueId"] = 12031812,
            ["GUID"] = "1E1ED128",
            ["Scripts"] = "PlayAnimation{ActorId{211001},AnimationId{\"AgreeHead\"},Duration{1}}",
            ["SpeakNpcId"] = 211001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/1E1ED128",
            },
        [12031813] = {
            ["Content"] = "前往贫民窟，中途触发对话",
            ["ContentFR"] = "Sur le chemin du retour",
            ["DialogueId"] = 12031813,
            ["GUID"] = "1E1ED152",
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/1E1ED152",
            },
        [12031850] = {
            ["Content"] = "就凭一张纸？【待包装】",
            ["DialogueId"] = 12031850,
            ["GUID"] = "1E1ED153",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 12031851,
            ["SpeakNpcId"] = 211034,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/1E1ED153",
            },
        [12031851] = {
            ["Content"] = "混蛋，都说了强盗很有可能就在这里！【待包装】",
            ["DialogueId"] = 12031851,
            ["GUID"] = "1E1ED154",
            ["GuideFacialId"] = "Angry",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 12031852,
            ["SpeakNpcId"] = 211003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/1E1ED154",
            },
        [12031852] = {
            ["Content"] = "走开走开，再叫把你抓起来！【待包装】",
            ["DialogueId"] = 12031852,
            ["GUID"] = "1E1ED155",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 12031853,
            ["SpeakNpcId"] = 211034,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/1E1ED155",
            },
        [12031853] = {
            ["Content"] = "还是不要过去给缄默公主添麻烦了。【待包装】",
            ["DialogueId"] = 12031853,
            ["GUID"] = "1E1ED156",
            ["GuideFacialId"] = "Sad",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 211001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/1E1ED156",
            },
        [12031901] = {
            ["Content"] = "咴……？",
            ["ContentFR"] = "Hiiii... ?",
            ["DialogueId"] = 12031901,
            ["GUID"] = "1E1EDFC2",
            ["NextDialogue"] = 12031902,
            ["SpeakNpcId"] = 211006,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/1E1EDFC2",
            },
        [12031902] = {
            ["Content"] = "咦？那里还有什么线索吗？",
            ["ContentFR"] = "Hein ? Tu crois qu’il y a encore un indice par là ?",
            ["DialogueId"] = 12031902,
            ["GUID"] = "1E1EDFEC",
            ["SpeakNpcId"] = 211001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/1E1EDFEC",
            },
        [12031903] = {
            ["Content"] = "进入小巷，发现主角",
            ["ContentFR"] = "Ils s’engagent dans une ruelle, et tombent sur le protagoniste.",
            ["DialogueId"] = 12031903,
            ["GUID"] = "1E1EE016",
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/1E1EE016",
            },
        [12031910] = {
            ["Camera"] = "-368.086914,-195.031616,230.956543,0.000131,-2.199765,-78.467514,35.000011,179.686569,false,Manual,2.8",
            ["Content"] = "咦，独角兽{性别：先生|小姐}，你好！好巧呀~",
            ["ContentFR"] = "Oh, {性别:Monsieur|Mademoiselle} Licorne ! Quelle surprise de te croiser ici !",
            ["DialogueId"] = 12031910,
            ["FinalCamera"] = "-323.415833,-415.043671,62.797363,0.00013,-2.199765,-78.86747,35.000011,179.686569,false,Manual,22",
            ["GUID"] = "1E1EE13C",
            ["NextDialogue"] = 12031911,
            ["Scripts"] = "PARA{\
