        [12032203] = {
            ["Camera"] = "-2.594985,-240.799469,116.917969,0.000117,5.19819,119.91935,35.000008,206.443939,false,Manual,2.8",
            ["Content"] = "已经跑远了吧。那种傲慢的索拉之民我见得多了，都是虚张声势而已。",
            ["ContentFR"] = "Elle est déjà loin. Des Solariens arrogants comme elle, j’en ai vu à la pelle. Beaucoup de bruit, mais rien derrière.",
            ["DialogueId"] = 12032203,
            ["GUID"] = "1E1F114E",
            ["NextDialogue"] = 12032204,
            ["Scripts"] = "PlayAnimation{ActorId{100001},AnimationId{\"Talk02R_Start\"},Duration{1}}",
            ["SpeakNpcId"] = 100001,
