}\
",
            ["SpeakNpcId"] = 100001,
            ["ToFinalCameraBlendTime"] = 1,
            ["VoiceName"] = "voice/$Locale$/story/1201/120113/1E1F129E",
            },
        [12032212] = {
            ["Content"] = "在冰湖城广场找到卡珊德拉",
            ["ContentFR"] = "Place de Givrelac — Rencontre avec Cassandra",
            ["DialogueId"] = 12032212,
            ["GUID"] = "1E1F12C8",
            ["VoiceName"] = "voice/$Locale$/story/1201/120113/1E1F12C8",
            },
        [12032301] = {
            ["Camera"] = "334.360657,-587.908386,278.855469,0.000115,-14.00104,114.318268,35.000019,267.529114,false,Manual,22.0",
            ["Content"] = "你们……你们怎么还跟过来了？！我又没对你们怎么样……",
            ["ContentFR"] = "Vous... pourquoi vous me suivez encore ?! Je ne vous ai rien fait, pourtant !",
            ["DialogueId"] = 12032301,
            ["FinalCamera"] = "300.830353,-513.711609,258.553711,0.000115,-14.00104,114.318268,35.000019,267.529114,false,Manual,22.0",
            ["GUID"] = "1E1F2162",
            ["NextDialogue"] = 12032302,
            ["Scripts"] = "SEQ{\
LookAt{LookAtDescription{\"211012:n(100001)\"}},\
LookAt{LookAtDescription{\"211012:n(211001)\"}}\
}",
            ["SpeakNpcId"] = 211012,
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/1201/120113/1E1F2162",
            },
        [12032302] = {
            ["Camera"] = "-112.066307,156.878036,123.823242,0.000105,0.598953,-20.880886,35.000008,267.529114,false,Manual,22.0",
            ["Content"] = "你误会了，小妹妹。",
            ["ContentFR"] = "Tu te trompes, petite demoiselle.",
            ["DialogueId"] = 12032302,
            ["FinalCamera"] = "-88.106537,147.737793,124.091797,0.00011,0.598953,-20.880886,35.000011,267.529114,false,Manual,22.0",
