            },
        [12032303] = {
            ["Camera"] = "147.284775,-92.297577,143.766602,0.000095,-6.801092,105.718018,28.0,267.529114,false,Manual,12.0",
            ["Content"] = "我才不是小妹妹！",
            ["ContentFR"] = "Ne me parle pas comme si j’étais une enfant !",
            ["DialogueId"] = 12032303,
            ["FinalCamera"] = "151.795822,-108.326996,145.751953,0.000095,-6.801092,105.718018,28.0,267.529114,false,Manual,12.0",
            ["GUID"] = "1E1F21B6",
            ["NextDialogue"] = 12032304,
            ["Scripts"] = "PlayAnimation{ActorId{211012},AnimationId{\"Confident_Start\"},Duration{1}}",
            ["SpeakNpcId"] = 211012,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1201/120113/1E1F21B6",
            },
        [12032304] = {
            ["Camera"] = "5.529626,121.547981,133.878174,0.00013,-1.200856,-34.879982,35.000011,161.242813,false,Manual,2.8",
            ["Content"] = "唔……那你是希望被叫姐姐吗？",
            ["ContentFR"] = "Oh... alors tu préfères que je t’appelle madame ?",
            ["DialogueId"] = 12032304,
            ["FinalCamera"] = "24.18462,108.543846,133.4021,0.00013,-1.200856,-34.879948,35.000015,161.242813,false,Manual,2.8",
            ["GUID"] = "1E1F21E0",
            ["NextDialogue"] = 12032305,
            ["Scripts"] = "PARA{\
PlayAnimation{_delay{4},ActorId{211001},AnimationId{\"Shy01_Start\"},Duration{1}},\
PlayFacial{ActorId{211001},FacialId{\"Happy01\"}}\
}",
            ["SpeakNpcId"] = 211001,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1201/120113/1E1F21E0",
            },
        [12032305] = {
            ["Camera"] = "150.017807,-126.066467,137.447021,0.000129,-4.200894,101.319115,28.0,338.300903,false,Manual,2.8",
            ["Content"] = "不是，当然不是！",
            ["ContentFR"] = "Bien sûr que non !",
            ["DialogueId"] = 12032305,
            ["FinalCamera"] = "156.439041,-158.144165,139.850098,0.000129,-4.200894,101.319115,28.0,338.300903,false,Manual,2.8",
            ["GUID"] = "1E1F220A",
            ["NextDialogue"] = 12032306,
            ["Scripts"] = "PlayAnimation{ActorId{211012},AnimationId{\"Confident_End\"},Duration{1}}\
",
            ["SpeakNpcId"] = 211012,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1201/120113/1E1F220A",
            },
        [12032306] = {
            ["Camera"] = "-91.302147,156.300644,138.539307,0.000134,-4.600863,-24.48016,35.000008,274.79599,false,Manual,12.0",
            ["Content"] = "不是妹妹也不是姐姐，那到底该怎么叫你呢？",
            ["ContentFR"] = "Alors... comment dois-je t’appeler ?",
            ["DialogueId"] = 12032306,
            ["FinalCamera"] = "-78.309174,150.385452,137.390869,0.000135,-4.600863,-24.479845,35.000011,274.79599,false,Manual,12.0",
            ["GUID"] = "1E1F2234",
            ["NextDialogue"] = 12032307,
            ["Scripts"] = "PARA{\
PlayAnimation{ActorId{211001},AnimationId{\"Shy01_End\"},Duration{1}},\
PlayAnimation{_delay{2},ActorId{211001},AnimationId{\"TilteHead_Start\"},Duration{1}},\
PlayAnimation{_delay{2},ActorId{211001},AnimationId{\"Think_Start\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 211001,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1201/120113/1E1F2234",
            },
        [12032307] = {
            ["Camera"] = "90.149757,-15.050601,109.933594,0.000203,1.39984,114.12458,28.000008,220.298309,false,Manual,12.0",
            ["Content"] = "你——唉，算了！我就好心地把名字告诉你们吧，卡戎人。你们可以称呼我为卡珊德拉小姐。",
            ["ContentFR"] = "Toi... Argh, laissez tomber ! Je vais être gentille et vous dire mon nom. Je m’appelle Cassandra. Et vous pouvez m’appeler Mademoiselle Cassandra, les Charons.",
            ["DialogueId"] = 12032307,
            ["FinalCamera"] = "96.089043,-28.312765,109.579102,0.000203,1.39984,114.12458,28.000008,220.298309,false,Manual,12.0",
            ["GUID"] = "1E1F225E",
            ["NextDialogue"] = 12032308,
            ["Scripts"] = "SEQ{\
LookAt{LookAtDescription{\"211012:n(211012)\"}},\
PlayAnimation{ActorId{211012},AnimationId{\"Confident_Start\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 211012,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1201/120113/1E1F225E",
            },
        [12032308] = {
            ["Camera"] = "-52.819042,289.31662,211.429199,0.000155,-19.20089,-63.279915,28.000006,274.79599,false,Manual,12.0",
            ["Content"] = "嗯，你好呀，卡珊德拉小姐，我叫菲娜，很高兴认识你！",
            ["ContentFR"] = "Enchantée, Mademoiselle Cassandra ! Moi, c’est Fina. Ravie de faire ta connaissance !",
            ["DialogueId"] = 12032308,
            ["FinalCamera"] = "-35.368748,254.650131,197.914062,0.000155,-19.20089,-63.279915,28.000006,274.79599,false,Manual,12.0",
            ["GUID"] = "1E1F2288",
            ["NextDialogue"] = 12032309,
            ["Scripts"] = "PARA{\
PlayAnimation{ActorId{211001},AnimationId{\"Think_End\"},Duration{1}},\
PlayAnimation{ActorId{211001},AnimationId{\"TilteHead_End\"},Duration{1}},\
PlayAnimation{_delay{1},ActorId{211001},AnimationId{\"AgreeHead\"},Duration{1}},\
PlayAnimation{_delay{1},ActorId{211001},AnimationId{\"Talk02R_Start\"},Duration{1}},\
PlayFacial{ActorId{211001},FacialId{\"None\"}}\
}",
            ["SpeakNpcId"] = 211001,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1201/120113/1E1F2288",
            },
        [12032309] = {
            ["Camera"] = "-35.368748,254.650131,197.914062,0.000155,-19.20089,-63.279915,28.000006,274.79599,false,Manual,12.0",
            ["Content"] = "我是{nickname}。",
            ["ContentFR"] = "Salut. Moi, c’est {nickname}.",
            ["DialogueId"] = 12032309,
            ["FinalCamera"] = "-29.449783,242.889984,193.328857,0.000155,-19.20089,-63.279915,28.000006,274.79599,false,Manual,12.0",
            ["GUID"] = "1E1F22B2",
            ["NextDialogue"] = 12032310,
            ["Scripts"] = "PARA{\
