        [12032354] = {
            ["Camera"] = "-32.313416,-47.220013,131.783447,0.000189,-4.601532,19.305601,35.000008,216.250549,false,DoNotOverride,12.0",
            ["Content"] = "好呀！那么，独角兽{性别：先生|小姐}，我们三天后再见！我要抓紧时间回家练习魔法啦。",
            ["ContentFR"] = "D’accord ! Merci, {性别:Monsieur|Mademoiselle} Licorne ! Alors... à dans trois jours ! Je dois rentrer vite m’entraîner pour le sort !",
