        [12032602] = {
            ["Camera"] = "-186.127243,150.942657,125.94043,0.000122,-4.600433,-63.80492,35.000011,152.429199,false,DoNotOverride,4.8",
            ["Content"] = "嘿嘿，谢谢你的夸奖。我们赶紧出发去找卡珊德拉小姐吧！",
