        [12032705] = {
            ["Content"] = "菲娜召唤出蝴蝶小姐",
            ["ContentFR"] = "Fina fait apparaître à nouveau la Fée-Papillon, qui voltige doucement.",
            ["DialogueId"] = 12032705,
            ["GUID"] = "1E1F63AA",
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E1F63AA",
            },
        [12032801] = {
            ["Camera"] = "85.913834,-351.01944,152.814209,0.000095,-8.402006,104.905922,35.000008,267.529114,false,DoNotOverride,12.0",
            ["Content"] = "哇……居然真变出来了，好厉害……！",
            ["ContentFR"] = "Ouaah... incroyable, tu l’as vraiment fait ! Quelle puissance !",
            ["DialogueId"] = 12032801,
            ["GUID"] = "1E1F736A",
            ["NextDialogue"] = 12032802,
            ["Scripts"] = "PARA{\
LookAt{_delay{0.5},LookAtDescription{\"211001:n(211012)\"}},\
LookAt{_delay{0.5},LookAtDescription{\"100001:n(211012)\"}},\
PlayAnimation{_delay{0},ActorId{211012},AnimationId{\"Huanhu_Nv_Start\"}}\
}",
            ["SpeakNpcId"] = 211012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E1F736A",
            },
        [12032802] = {
            ["Content"] = "对了对了，我们先串个口供！等会儿你们假装成见过蝴蝶精灵的人，带着我朋友随便去个小巷子什么的，就说蝴蝶精灵会在那个地方出现。",
            ["ContentFR"] = "Bon, alors, révisons notre... euh... \"témoignage\". Dans un instant, je ramène mon ami. Vous, vous ferez semblant d’être des voyageurs qui ont déjà vu la Fée-Papillon, et vous l’emmènerez dans une petite ruelle en lui disant qu’elle apparaîtra là.",
            ["DialogueId"] = 12032802,
            ["GUID"] = "1E1F7394",
            ["NextDialogue"] = 12032803,
            ["Scripts"] = "SEQ{\
PlayAnimation{_delay{0},ActorId{211012},AnimationId{\"Confident_Start\"}},\
PlayAnimation{_delay{2},ActorId{211012},AnimationId{\"Confident_End\"}}\
}",
            ["SpeakNpcId"] = 211012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E1F7394",
            },
        [12032803] = {
            ["Content"] = "然后，在我们蹲守的时候，菲娜你就在后面悄悄把蝴蝶变出来。",
            ["ContentFR"] = "Ensuite, pendant qu’on attendra, Fina, toi tu te faufiles derrière et tu fais apparaître la Fée-Papillon en cachette !",
            ["DialogueId"] = 12032803,
            ["GUID"] = "1E1F73BE",
            ["NextDialogue"] = 12032804,
            ["SpeakNpcId"] = 211012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E1F73BE",
            },
        [12032804] = {
            ["Content"] = "“口供”这个词用得不太对吧……？",
            ["ContentFR"] = "\"Témoignage\" ? Tu veux plutôt dire \"plan\", non ?",
            ["DialogueId"] = 12032804,
            ["GUID"] = "1E1F73E8",
            ["NextDialogue"] = 12032805,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E1F73E8",
            },
        [12032805] = {
            ["Content"] = "为什么，口供不就是计划的意思吗？哎，反正你们记住就好啦，我现在就去把我朋友叫来！",
            ["ContentFR"] = "Bah... ça revient au même, non ? Retenez juste l’idée. Allez, je vais chercher mon ami !",
            ["DialogueId"] = 12032805,
            ["GUID"] = "1E1F7412",
            ["NextDialogue"] = 12032806,
            ["Scripts"] = "SEQ{\
PlayAnimation{_delay{0},ActorId{211012},AnimationId{\"Talk03_Start\"}},\
PlayAnimation{_delay{3},ActorId{211012},AnimationId{\"Talk03_End\"}}\
}",
            ["SpeakNpcId"] = 211012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E1F7412",
            },
        [12032806] = {
            ["Camera"] = "-51.861469,93.709923,122.964111,0.000101,0.197741,-44.90287,35.000008,267.529114,false,DoNotOverride,12.0",
            ["Content"] = "嗯嗯……我记住了！“口供”！",
            ["ContentFR"] = "Oui, oui ! Je retiens : \"témoignage\" !",
            ["DialogueId"] = 12032806,
            ["GUID"] = "1E1F743C",
            ["NextDialogue"] = 12032807,
            ["Scripts"] = "PARA{\
SEQ{\
PlayAnimation{_delay{0},ActorId{211001},AnimationId{\"AgreeHead\"}},\
PlayAnimation{_delay{1.5},ActorId{211001},AnimationId{\"Explain02_Start\"}}\
},\
PlayFacial{_delay{1.5},ActorId{211001},FacialId{\"Smile01\"}}\
}",
            ["SpeakNpcId"] = 211001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E1F743C",
