            },
        [12033103] = {
            ["Content"] = "菲娜？菲娜，快开门，是我！出大事了！",
            ["ContentFR"] = "Fina ! Vite, ouvre ! C’est moi, il est arrivé quelque chose de grave !",
            ["DialogueId"] = 12033103,
            ["GUID"] = "1E1FA520",
            ["SpeakNpcId"] = 211012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E1FA520",
            },
        [12033104] = {
            ["Content"] = "主角开门，门外站着卡珊德拉，后面跟着三小孩（芙蕾达、珂芮，戴维）",
            ["DialogueId"] = 12033104,
            ["GUID"] = "1E1FA521",
            },
        [12033201] = {
