        [12033202] = {
            ["Camera"] = "-195.357635,106.520752,127.771973,0.000041,-13.999544,116.397713,13.080085,123.93045,false,Manual,4.0",
            ["Content"] = "塞维欧他、他不见了！",
            ["ContentFR"] = "C’est Savio... il a disparu !",
            ["DialogueId"] = 12033202,
            ["GUID"] = "1E1FB534",
            ["NextDialogue"] = 12033203,
            ["Scripts"] = "PARA{\
PlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt02/0051_story_danger\"}},\
PlayAnimation{_delay{0},ActorId{211012},AnimationId{\"Sigh_End\"}}, \
PlayAnimation{_delay{3},ActorId{211012},AnimationId{\"Talk02_Start\"}},\
}",
            ["SpeakNpcId"] = 211012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E1FB534",
            },
        [12033203] = {
            ["Camera"] = "-206.954987,162.348816,128.731934,0.000059,4.800099,-85.600464,35.0,123.930466,false,Manual,4.0",
            ["Content"] = "什么……怎么回事？什么时候不见的？",
            ["ContentFR"] = "Quoi ? Comment ça ? Quand ?",
            ["DialogueId"] = 12033203,
            ["GUID"] = "1E1FB55E",
            ["NextDialogue"] = 12033204,
            ["Scripts"] = "PARA{\
PlayAnimation{_delay{0},ActorId{100001},AnimationId{\"Shock03_Start\"}},\
PlayFacial{ActorId{100001},FacialId{\"Shock01\"}}\
}",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E1FB55E",
            },
        [12033204] = {
            ["Camera"] = "-139.243134,14.521248,143.611816,0.000146,-15.199629,127.008095,18.0,272.20813,false,Manual,4.0",
            ["Content"] = "就是刚才，我追着你们走了一段，回头一看就发现他不见了！剧院那边我也找了，大家都说他没回去。呜呜，怎么办……",
            ["ContentFR"] = "Juste après vous ! J’ai couru un peu derrière vous, puis je me suis retournée... et il n’était plus là ! J’ai cherché autour du théâtre, mais personne ne l’a vu revenir... Qu’est-ce que je vais faire ?!",
            ["DialogueId"] = 12033204,
            ["GUID"] = "1E1FB588",
            ["NextDialogue"] = 12033205,
            ["Scripts"] = "PARA{\
PlayAnimation{_delay{0},ActorId{211012},AnimationId{\"Talk02_End\"}}, \
}",
            ["SpeakNpcId"] = 211012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E1FB588",
            },
        [12033205] = {
            ["Camera"] = "-265.27298,259.746368,105.448242,0.000154,-1.199613,-84.593338,18.0,272.20813,false,Manual,4.0",
            ["Content"] = "别急，他一个孩子也跑不了多远，我们先在附近找找看。",
            ["ContentFR"] = "Calme-toi. C’est un enfant, il n’a pas pu aller bien loin. On va fouiller les alentours.",
            ["DialogueId"] = 12033205,
            ["GUID"] = "1E1FB5B2",
            ["NextDialogue"] = 12033206,
            ["Scripts"] = "SEQ{\
PlayAnimation{_delay{0},ActorId{100001},AnimationId{\"Shock03_End\"}}, \
PlayAnimation{_delay{0},ActorId{100001},AnimationId{\"Talk01_Start\"}}\
}",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E1FB5B2",
            },
        [12033206] = {
            ["Camera"] = "24.507023,19.049276,123.163574,0.00017,-5.999515,-139.785721,25.0,272.20813,false,Manual,22.0",
