        [12033415] = {
            ["Camera"] = "-296.6315,90.475662,114.222412,0.000088,5.677895,23.727402,35.000011,177.889099,false,DoNotOverride,3.5",
            ["Content"] = "咦？！那、那你可以帮我一起去找吗！拜托了，那谁，啊不，{nickname}{性别：哥哥|姐姐}！我会付报酬的！",
            ["ContentFR"] = "Hein ?! Vraiment ?! Alors tu peux m’aider à chercher, n’est-ce pas ? Je t’en supplie, {性别:Monsieur|Mademoiselle} {nickname} ! Je paierai, promis !",
            ["DialogueId"] = 12033415,
            ["FinalCamera"] = "-296.6315,90.475662,114.222412,0.000088,5.07789,27.32766,35.000011,177.889099,false,DoNotOverride,3.5",
            ["GUID"] = "1E1FD826",
            ["NextDialogue"] = 12033416,
            ["Scripts"] = "PARA{\
