        [12033501] = {
            ["Content"] = "这么找效率太低了……卡珊德拉，你能猜到塞维欧可能会去哪里吗？或者他为什么要出城？",
            ["ContentFR"] = "Chercher au hasard, ça ne servira à rien... Cassandra, as-tu une idée d’où Savio pourrait aller ? Ou pourquoi il aurait quitté la cité ?",
            ["DialogueId"] = 12033501,
            ["GUID"] = "1E1FE642",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 12033502,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E1FE642",
            },
        [12033502] = {
            ["Content"] = "唔……说不定，他是去找蝴蝶了？前几天上课的时候，老师偶然提到泪湖附近栖息着蝴蝶，他追着问了好久……",
            ["ContentFR"] = "Hmm... Peut-être qu’il est parti chercher des papillons. L’autre jour, en classe, le maître a dit qu’il y en avait près du Lac du Deuil. Il n’arrêtait pas de poser des questions à ce sujet...",
            ["DialogueId"] = 12033502,
            ["GUID"] = "1E1FE66C",
            ["NextDialogue"] = 12033503,
            ["SpeakNpcId"] = 211012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E1FE66C",
            },
        [12033503] = {
            ["Content"] = "他到底为什么这么喜欢蝴蝶？是因为什么童话故事吗？",
            ["ContentFR"] = "Il est vraiment obsédé par les papillons... C’est à cause d’un conte ?",
            ["DialogueId"] = 12033503,
            ["GUID"] = "1E1FE696",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 12033504,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E1FE696",
            },
        [12033504] = {
            ["Content"] = "是因为发生在他小时候的一件事，他对我说过好多次——有一天他的爸爸妈妈忽然都不见了，他怎么找也找不到，害怕得哭了起来。",
            ["ContentFR"] = "Non... C’est à cause d’un souvenir. Il me l’a raconté plein de fois. Quand il était petit, un jour ses parents ont disparu. Il les cherchait partout, en pleurant.",
            ["DialogueId"] = 12033504,
            ["GUID"] = "1E1FE6C0",
            ["NextDialogue"] = 12033505,
            ["SpeakNpcId"] = 211012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E1FE6C0",
            },
        [12033505] = {
            ["Content"] = "蝴蝶精灵就在这个时候出现了，它们和他一起玩耍，陪着他等待，最后终于等到了他的爸爸妈妈回到家。",
            ["ContentFR"] = "Et c’est alors que des Fées-Papillons sont apparues. Elles ont joué avec lui, lui ont tenu compagnie... jusqu’à ce que ses parents rentrent enfin.",
            ["DialogueId"] = 12033505,
            ["GUID"] = "1E1FE6EA",
            ["NextDialogue"] = 12033506,
            ["SpeakNpcId"] = 211012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E1FE6EA",
            },
        [12033506] = {
            ["Content"] = "所以，我想，也许他是觉得，找到了蝴蝶精灵，他的爸爸妈妈就会回来吧……",
            ["ContentFR"] = "Alors... je crois qu’il espère qu’en les retrouvant, ses parents reviendront aussi...",
            ["DialogueId"] = 12033506,
            ["GUID"] = "1E1FE714",
            ["NextDialogue"] = 12033507,
            ["SpeakNpcId"] = 211012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E1FE714",
            },
        [12033507] = {
            ["Content"] = "……",
            ["ContentFR"] = "...",
            ["DialogueId"] = 12033507,
            ["GUID"] = "1E1FE73E",
            ["GuideFacialId"] = "Sad",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 211001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E1FE73E",
            },
        [12033508] = {
            ["Content"] = "到达调查点",
            ["ContentFR"] = "Un peu plus loin, ils découvrent quelque chose au sol.",
            ["DialogueId"] = 12033508,
            ["GUID"] = "1E1FE768",
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E1FE768",
            },
        [12033601] = {
            ["Camera"] = "1295.55542,310.961182,55.149414,0.000115,-6.200315,-148.689377,35.000015,267.529114,false,Manual,8.0",
            ["Content"] = "等等，那边地上的是……",
            ["ContentFR"] = "Attendez... là, par terre...",
            ["DialogueId"] = 12033601,
            ["FinalCamera"] = "1271.21228,296.156647,52.055664,0.000115,-6.200315,-148.689377,35.000015,267.529114,false,Manual,8.0",
