            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E1FF6AA",
            },
        [12033602] = {
            ["Content"] = "好像是一枚银币？",
            ["ContentFR"] = "On dirait... une pièce d’argent ?",
            ["DialogueId"] = 12033602,
            ["GUID"] = "1E1FF6D4",
            ["NextDialogue"] = 12033603,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E1FF6D4",
            },
        [12033603] = {
            ["Camera"] = "234.363953,-50.952301,24.949219,0.000154,-4.399441,4.909956,35.000015,244.392456,false,Manual,10.0",
            ["Content"] = "不，这是硬纸板，只是涂成了银币的颜色……这是之前我们玩游戏的时候，塞维欧亲手做的道具！",
            ["ContentFR"] = "Non, ce n’est que du carton, peint pour ressembler à une pièce d’argent... C’est Savio qui l’avait fabriqué de ses propres mains pour notre jeu !",
            ["DialogueId"] = 12033603,
            ["FinalCamera"] = "253.116959,-20.29356,23.308594,0.000155,-4.399441,4.909863,35.000015,244.392456,false,Manual,10.0",
            ["GUID"] = "1E1FF6FE",
            ["NextDialogue"] = 12033604,
            ["SpeakNpcId"] = 211012,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E1FF6FE",
            },
        [12033604] = {
            ["Camera"] = "620.08136,271.415924,29.961914,0.000183,-8.999266,-35.888649,35.000023,354.210571,false,Manual,10.0",
            ["Content"] = "他那么细心，绝对不会把这么重要的东西丢在地上的。他该不会……该不会是出了什么事吧……呜呜……",
            ["ContentFR"] = "Il y tenait tellement... Jamais il ne l’aurait laissée tomber. Ça veut dire que... il a dû lui arriver quelque chose... <I>snif...</>",
            ["DialogueId"] = 12033604,
            ["FinalCamera"] = "640.950745,256.320587,25.977539,0.000182,-8.799243,-35.888645,35.000023,354.210571,false,Manual,10.0",
            ["GUID"] = "1E1FF728",
            ["NextDialogue"] = 12033605,
            ["Scripts"] = "SEQ{\
LookAt{LookAtDescription{\"211012:n(100001)\"}},\
