}",
            ["SpeakNpcId"] = 211012,
            ["ToFinalCameraBlendTime"] = 10,
            ["TurnTo"] = {
                [1] = "211012:p(-60)",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E1FF728",
            },
        [12033605] = {
            ["Camera"] = "751.478516,230.02742,-0.833008,0.000126,1.799482,-67.086746,28.0,267.67627,false,Manual,2.8",
            ["Content"] = "啊——！我想起来了，缄默侦探阁下说过，她在追查的那伙强盗是专门绑架小孩子的……",
            ["ContentFR"] = "Ah ! Je me souviens ! La Détective Taciturne avait dit que les bandits qu’elle poursuivait... ils enlevaient des enfants !",
            ["DialogueId"] = 12033605,
            ["FinalCamera"] = "753.482544,225.280487,-0.672852,0.000128,1.799482,-67.086746,28.0,267.67627,false,Manual,2.8",
            ["GUID"] = "1E1FF752",
            ["NextDialogue"] = 12033606,
            ["Scripts"] = "\
