            ["SpeakNpcId"] = 211012,
            ["ToFinalCameraBlendTime"] = 10,
            ["TurnTo"] = {
                [1] = "211012:p(120)",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E1FF77C",
            },
        [12033607] = {
            ["Camera"] = "857.67926,35.406128,16.916992,0.000122,-9.799436,107.302444,35.000015,133.269669,false,Manual,2.8",
            ["Content"] = "菲娜，我记得你那时说，你找到了重要的线索。你还记得是什么吗？",
            ["ContentFR"] = "Fina, tu avais dit avoir trouvé un indice important ce jour-là. Tu t’en rappelles ?",
            ["DialogueId"] = 12033607,
            ["FinalCamera"] = "852.928162,50.662773,14.157227,0.000123,-9.799401,107.302452,35.000015,123.633568,false,Manual,2.8",
            ["GUID"] = "1E1FF7A6",
            ["NextDialogue"] = 12033608,
            ["Scripts"] = "PARA{\
