}",
            ["SpeakNpcId"] = 211001,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E1FF7D0",
            },
        [12033609] = {
            ["Camera"] = "855.435364,-250.186905,69.771484,0.000161,-14.201199,100.104431,28.000006,294.264496,false,Manual,22.0",
            ["Content"] = "那我们快过去吧！",
            ["ContentFR"] = "Alors allons-y vite !",
            ["DialogueId"] = 12033609,
            ["FinalCamera"] = "852.999023,-236.503036,66.25293,0.000161,-14.201199,100.104431,28.000006,294.264496,false,Manual,22.0",
            ["GUID"] = "1E1FF7FA",
            ["NextDialogue"] = 12033610,
            ["Scripts"] = "PARA{\
PlayAnimation{_delay{2},ActorId{211012},AnimationId{\"Talk01_Start\"},Duration{1}},\
PlayAnimation{_delay{1},ActorId{100001},AnimationId{\"Think_End\"},Duration{1}}\
