            ["SpeakNpcId"] = 211012,
            ["ToFinalCameraBlendTime"] = 10,
            ["TurnTo"] = {
                [1] = "211012:p(-60)",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E1FF7FA",
            },
        [12033610] = {
            ["Content"] = "不，我们不知道强盗有多少人，一起过去太冒险了。卡珊德拉，你还记得来这里的路吗？我需要你现在回到城里，去找治安署报案，你能做到吗？",
            ["ContentFR"] = "Non. On ne sait pas combien ils sont. C’est trop dangereux de foncer tous ensemble. Cassandra, tu te rappelles le chemin du retour ? Tu dois aller prévenir le Bureau de la Sécurité.",
            ["DialogueId"] = 12033610,
            ["GUID"] = "1E1FF824",
            ["NextDialogue"] = 12033611,
            ["Scripts"] = "PARA{\
LookAt{LookAtDescription{\"100001:n(211012)\"}},\
LookAt{LookAtDescription{\"211012:n(100001)\"}},\
