}",
            ["SpeakNpcId"] = 100001,
            ["TurnTo"] = {
                [1] = "100001:p(50)",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E1FF824",
            },
        [12033611] = {
            ["Content"] = "我记得，可是……",
            ["ContentFR"] = "Je... oui, je m’en souviens. Mais—",
            ["DialogueId"] = 12033611,
            ["GUID"] = "1E1FF84E",
