        [12033617] = {
            ["Content"] = "抵达洞窟外，主角偷偷观察里面，发现塞维欧被六七个强盗围着",
            ["ContentFR"] = "Au repaire des bandits. De loin, ils aperçoivent Savio encerclé par six ou sept bandits.",
            ["DialogueId"] = 12033617,
            ["GUID"] = "1E1FF94A",
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E1FF94A",
            },
        [12033701] = {
            ["Camera"] = "173.460236,214.176193,147.875977,0.000091,-9.0007,-142.292953,35.000008,267.529114,false,DoNotOverride,2.8",
            ["Content"] = "果然在这里……",
            ["ContentFR"] = "Le voilà...",
            ["DialogueId"] = 12033701,
            ["GUID"] = "1E200712",
            ["NextDialogue"] = 12033702,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E200712",
            },
        [12033702] = {
            ["Camera"] = "-2079.935303,-417.626953,280.476562,0.000107,-19.000505,-77.490654,35.000011,899.788879,false,DoNotOverride,2.8",
            ["Content"] = "对方人数倒也不算多，但是人质在他们手上，有点麻烦。如果能用什么办法引开他们就好了……",
            ["ContentFR"] = "Ils sont pas si nombreux. Mais avec l’otage, ça complique les choses. Il faudrait trouver un moyen de les distraire...",
            ["DialogueId"] = 12033702,
            ["GUID"] = "1E20073C",
            ["NextDialogue"] = 12033703,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E20073C",
            },
        [12033703] = {
            ["Camera"] = "-375.408356,-63.121277,64.066406,0.00011,4.599183,30.708393,35.000011,165.810257,false,DoNotOverride,2.8",
            ["Content"] = "菲娜有办法！",
            ["ContentFR"] = "J’ai une idée !",
            ["DialogueId"] = 12033703,
            ["GUID"] = "1E200766",
            ["Scripts"] = "PlayFacial{_delay{0.5},ActorId{211001},FacialId{\"Smile01\"}}",
            ["SpeakNpcId"] = 211001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E200766",
            },
        [12033704] = {
            ["Content"] = "菲娜在空地（从洞窟内能看见，但离洞窟有一定距离的地方）召唤出大魔法师和独角兽",
            ["ContentFR"] = "Elle invoque le Grand Magicien et la Licorne, de l’autre côté du camp.",
            ["DialogueId"] = 12033704,
            ["GUID"] = "1E200790",
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E200790",
            },
        [12033705] = {
            ["Camera"] = "-1684.510986,-4.19751,-121.415039,0.000114,-3.201071,-177.585098,35.000011,1074.249756,false,DoNotOverride,12.0",
            ["Content"] = "嗯？什么动静？",
            ["ContentFR"] = "Hein ?! Qu’est-ce que c’est que ça ?",
