        [12033709] = {
            ["Camera"] = "-2712.877686,127.540527,-141.259766,0.000156,0.998758,-172.586914,35.000011,544.833557,false,DoNotOverride,12.0",
            ["Content"] = "我也没见过，估计是比较稀有的品种吧。",
            ["ContentFR"] = "Moi non plus. Ça doit être une espèce rare.",
            ["DialogueId"] = 12033709,
            ["GUID"] = "1E200862",
            ["NextDialogue"] = 12033710,
            ["SpeakNpcId"] = 211037,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E200862",
            },
        [12033710] = {
            ["Camera"] = "-1975.500122,112.498108,-95.56543,0.000173,-4.801363,-175.988037,35.000011,544.833557,false,DoNotOverride,12.0",
            ["Content"] = "诶？我听道上的兄弟说，稀有的魔灵好像可以卖不少钱呢！要不咱们把它们抓了，说不定能多赚一笔？",
            ["ContentFR"] = "J’ai entendu dire que les rares, ça se revend très cher ! On devrait pas les capturer ? Ça rapporterait gros !",
            ["DialogueId"] = 12033710,
            ["GUID"] = "1E20088C",
            ["NextDialogue"] = 12033711,
            ["Scripts"] = "PlayAnimation{_delay{0.5},ActorId{211039},AnimationId{\"Talk02_Start\"}}",
            ["SpeakNpcId"] = 211039,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E20088C",
            },
        [12033711] = {
            ["Content"] = "还有这事？没想到你小子还挺机灵……好哇，兄弟们，抄家伙，把那两个魔灵抓起来！",
            ["ContentFR"] = "Pas bête, ça... T’as plus de cervelle que j’croyais. Allez les gars ! Armez-vous, on les chope !",
            ["DialogueId"] = 12033711,
            ["GUID"] = "1E2008B6",
            ["Scripts"] = "PlayAnimation{_delay{7.5},ActorId{211037},AnimationId{\"Angry01_Start\"}}",
            ["SpeakNpcId"] = 211037,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E2008B6",
            },
        [12033712] = {
            ["Content"] = "一部分强盗离开洞窟，留两个在里面看人质",
            ["ContentFR"] = "Une partie de la bande s’éloigne, laissant seulement deux gardes avec Savio.",
            ["DialogueId"] = 12033712,
            ["GUID"] = "1E2008E0",
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E2008E0",
            },
        [12033801] = {
