            ["ContentFR"] = "Venez, mes amis ! Ensemble, protégeons tout le monde !",
            ["DialogueId"] = 12033814,
            ["GUID"] = "1E20199C",
            ["SpeakNpcId"] = 211001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E20199C",
            },
        [12033815] = {
            ["Content"] = "菲娜正脸特写，四个召唤兽围在她身边",
            ["DialogueId"] = 12033815,
            ["GUID"] = "1E2019C6",
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E2019C6",
            },
        [12033816] = {
