            ["Scripts"] = "PARA{\
PlayFacial{ActorId{211001},FacialId{\"Sad01\"}},\
PlayAnimation{_delay{0},ActorId{211001},AnimationId{\"Shy02_Start\"}}\
}",
            ["SpeakNpcId"] = 211001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E2028B4",
            },
        [12033907] = {
            ["Camera"] = "188.955719,28.82197,97.71875,0.000149,-6.802458,149.992783,25.0,190.125488,false,Manual,4.0",
            ["Content"] = "我还认得这只蝴蝶……那一天，我找不到爸爸妈妈的时候，飞到我身边来的蝴蝶精灵……就和它长得一模一样。",
            ["ContentFR"] = "Et ce papillon... Je m’en souviens ! Ce jour-là, quand je n’arrivais pas à retrouver papa et maman, une nuée de fées-papillons est venue à mes côtés... elles ressemblaient exactement à celui-ci.",
            ["DialogueId"] = 12033907,
            ["GUID"] = "1E2028DE",
            ["NextDialogue"] = 12033908,
            ["Scripts"] = "PlayFacial{ActorId{211001},FacialId{\"CM_Idle\"}},",
            ["SpeakNpcId"] = 211015,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E2028DE",
            },
        [12033908] = {
            ["Content"] = "我想起来了，塞拉菲娜姐姐，那一天你也在院子里。是你变出了蝴蝶精灵来陪我玩，对不对？",
            ["ContentFR"] = "Je me rappelle aussi que tu étais dans le jardin, grande sœur Serafina. C’est toi qui as fait apparaître les papillons pour jouer avec moi, n’est-ce pas ?",
            ["DialogueId"] = 12033908,
            ["GUID"] = "1E202908",
            ["NextDialogue"] = 12033909,
            ["Scripts"] = "PlayAnimation{_delay{0},ActorId{211015},AnimationId{\"Explain02_End\"}}",
            ["SpeakNpcId"] = 211015,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E202908",
            },
        [12033909] = {
            ["Camera"] = "45.257626,67.690178,92.338867,0.000179,2.997155,-0.205472,35.0,119.632339,false,Manual,4.0",
            ["Content"] = "……是的，塞维欧，是我。但是，我现在的名字是菲娜。",
            ["ContentFR"] = "... Oui, Savio, c’était moi. Mais aujourd’hui, je m’appelle Fina.",
            ["DialogueId"] = 12033909,
            ["GUID"] = "1E202932",
            ["NextDialogue"] = 12033910,
            ["Scripts"] = "SEQ{\
PlayAnimation{_delay{0},ActorId{211001},AnimationId{\"Shy02_End\"}},\
PlayAnimation{_delay{0},ActorId{211001},AnimationId{\"Explain02_Start\"}}\
}",
            ["SpeakNpcId"] = 211001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E202932",
            },
        [12033910] = {
            ["Camera"] = "33.587769,17.520916,86.75293,0.000189,2.596879,109.192482,35.0,89.251617,false,Manual,4.0",
            ["Content"] = "原来，那个时候，我不是一个人……谢谢你，塞——菲娜姐姐！可是你后来为什么走了？你能回来吗？",
            ["ContentFR"] = "Alors, ce jour-là... je n’étais pas seul... Merci, Sera— enfin, Fina ! Mais pourquoi tu es partie ? Tu pourrais revenir à la maison ?",
            ["DialogueId"] = 12033910,
            ["GUID"] = "1E20295C",
            ["NextDialogue"] = 12033911,
            ["SpeakNpcId"] = 211015,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E20295C",
            },
        [12033911] = {
            ["Camera"] = "140.553329,-25.305544,97.136719,0.000184,0.796673,84.192825,35.0,89.251617,false,Manual,4.0",
            ["Content"] = "因为我是一个卡戎人……那座大宅邸不欢迎我，所以我必须离开，而且不能回去。不过，我现在也找到了一个新的家，你不用担心。",
            ["ContentFR"] = "Parce que je suis une Charon... Ce manoir n’acceptait pas les gens comme moi. Je devais partir, et je ne peux plus y retourner. Mais ne t’inquiète pas... j’ai trouvé une nouvelle maison, à moi.",
            ["DialogueId"] = 12033911,
            ["GUID"] = "1E202986",
            ["NextDialogue"] = 12033912,
            ["Scripts"] = "PARA{\
PlayAnimation{_delay{0},ActorId{211001},AnimationId{\"Explain02_End\"}},\
LookAt{LookAtDescription{\"100001:n(211001)\"}},\
SEQ{\
PlayFacial{ActorId{100001},FacialId{\"Sad02\"}},\
PlayAnimation{_delay{5},ActorId{100001},AnimationId{\"Explain02_Start\"}},\
}\
}",
            ["SpeakNpcId"] = 211001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E202986",
            },
        [12033912] = {
            ["Camera"] = "-121.710831,53.883701,100.163086,0.00019,-4.003509,10.785311,35.0,286.216858,false,Manual,6.0",
            ["Content"] = "那……那你知道爸爸妈妈去哪里了吗？为什么他们不回来了？",
            ["ContentFR"] = "Alors... tu sais où sont partis papa et maman ? Pourquoi ils ne reviennent pas ?",
            ["DialogueId"] = 12033912,
            ["GUID"] = "1E2029B0",
            ["NextDialogue"] = 12033913,
            ["Scripts"] = "PlayAnimation{_delay{0},ActorId{100001},AnimationId{\"Explain02_End\"}},",
            ["SpeakNpcId"] = 211015,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E2029B0",
            },
        [12033913] = {
            ["Content"] = "他们……呜……",
            ["ContentFR"] = "Ils... <I>snif...</>",
            ["DialogueId"] = 12033913,
            ["GUID"] = "1E2029DA",
            ["NextDialogue"] = 12034001,
            ["Scripts"] = "PARA{\
PlayFacial{_delay{0.5},ActorId{211001},FacialId{\"Sad01\"}},\
PlayAnimation{_delay{0},ActorId{211001},AnimationId{\"Shy01_Start\"}}\
}",
            ["SpeakNpcId"] = 211001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E2029DA",
            },
        [12033914] = {
            ["Content"] = "主角走过来解围",
            ["ContentFR"] = "(Le protagoniste intervient pour apaiser.)",
            ["DialogueId"] = 12033914,
            ["GUID"] = "1E202A04",
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E202A04",
            },
        [12034001] = {
            ["Camera"] = "139.785004,247.222656,148.624023,0.000206,-19.804255,-119.814819,25.0,286.216858,false,Manual,6.0",
            ["Content"] = "塞维欧，我来告诉你吧，我知道他们去哪里了。",
            ["ContentFR"] = "Savio, laisse-moi t’expliquer. Je sais où tes parents sont allés.",
            ["DialogueId"] = 12034001,
            ["GUID"] = "1E20384A",
            ["NextDialogue"] = 12034002,
            ["Scripts"] = "PARA{\
LookAt{_delay{0.5},LookAtDescription{\"100001:n(211015)\"}},\
LookAt{_delay{1},LookAtDescription{\"211001:n(100001)\"}},\
LookAt{_delay{0},LookAtDescription{\"211015:n(100001)\"}},\
MoveTo{ActorId{100001},TargetPoint{\"nvzhu_feina_37_walk\"},MoveSpeed{100},Visibility{\"Show\"}}\
}",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E20384A",
            },
        [12034002] = {
            ["Camera"] = "-60.111835,138.167587,81.243164,0.000218,5.395651,-9.014689,25.0,255.333679,false,Manual,6.0",
            ["Content"] = "这个世界上有一个我们看不见的可怕怪物，叫做“偏见”……它会让本应相亲相爱的人们互相憎恶、互相伤害。你们的爸爸妈妈就是被它带走了。",
            ["ContentFR"] = "Dans ce monde, il existe un monstre terrible qu’on ne peut pas voir : on l’appelle le « Préjugé ». Il pousse les gens qui devraient s’aimer à se haïr et à se blesser... Ce sont lui et ses griffes invisibles qui ont emporté ton père et ta mère.",
            ["DialogueId"] = 12034002,
            ["GUID"] = "1E203874",
            ["NextDialogue"] = 12034003,
            ["Scripts"] = "PlayAnimation{_delay{0},ActorId{100001},AnimationId{\"Explain02_Start\"}}",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E203874",
            },
        [12034003] = {
            ["Camera"] = "116.961861,174.154648,120.447266,0.000223,-16.204643,-136.614212,25.0,255.333679,false,Manual,6.0",
            ["Content"] = "那我要去把他们救回来！",
            ["ContentFR"] = "Alors je vais le combattre et les ramener !",
            ["DialogueId"] = 12034003,
            ["GUID"] = "1E20389E",
            ["NextDialogue"] = 12034004,
            ["Scripts"] = "PlayAnimation{_delay{0},ActorId{211015},AnimationId{\"Angry01_Start\"}}",
            ["SpeakNpcId"] = 211015,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E20389E",
            },
        [12034004] = {
            ["Camera"] = "-29.829901,107.802788,74.746094,0.00025,12.194851,5.783125,25.000002,153.736694,false,Manual,6.0",
            ["Content"] = "现在你还太小了，而且，那不是靠一个人就能打败的敌人。",
            ["ContentFR"] = "Tu es courageux, mais tu es encore trop jeune. Et ce monstre-là ne peut pas être battu à coups de poing.",
            ["DialogueId"] = 12034004,
            ["GUID"] = "1E2038C8",
            ["NextDialogue"] = 12034005,
            ["Scripts"] = "PlayAnimation{_delay{0},ActorId{100001},AnimationId{\"Explain02_End\"}}",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E2038C8",
            },
        [12034005] = {
            ["Content"] = "因为那个可怕的怪物是靠吸食人们的信念长大的，现在这座城市里有太多人受到它的蛊惑，成为了它的仆从，让它变得很强很强。",
            ["ContentFR"] = "Il se nourrit des peurs et des croyances des hommes... et dans cette cité, beaucoup ont succombé à ses murmures. C’est pour ça qu’il est devenu si fort.",
            ["DialogueId"] = 12034005,
            ["GUID"] = "1E2038F2",
            ["NextDialogue"] = 12034006,
            ["Scripts"] = "PlayAnimation{_delay{0},ActorId{100001},AnimationId{\"Talk02_Start\"}}",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E2038F2",
            },
        [12034006] = {
            ["Camera"] = "159.328293,-18.95005,85.956055,0.00025,5.194987,100.784615,25.000002,138.543365,false,Manual,6.0",
            ["Content"] = "但只要你不相信它、我不相信它，我们再告诉我们的朋友，让大家一起勇敢起来，拒绝它的蛊惑……那么它的力量就会变得越来越弱。",
            ["ContentFR"] = "Mais si toi, moi, et nos amis, on refuse de croire en lui... si on trouve la force d’être courageux et de dire non à ses mensonges, alors petit à petit, son pouvoir s’affaiblira.",
            ["DialogueId"] = 12034006,
            ["GUID"] = "1E20391C",
            ["NextDialogue"] = 12034007,
            ["Scripts"] = "PARA{\
LookAt{_delay{0.5},LookAtDescription{\"100001:n(211001)\"}},\
LookAt{_delay{1},LookAtDescription{\"211001:n(100001)\"}},\
PlayAnimation{_delay{0},ActorId{211001},AnimationId{\"AgreeHead\"}},\
PlayFacial{ActorId{211001},FacialId{\"Happy01\"}}\
}",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E20391C",
            },
        [12034007] = {
            ["Camera"] = "45.170029,149.59169,119.630859,0.000216,-11.604067,-24.416609,25.0,163.981354,false,Manual,6.0",
            ["Content"] = "然后，总有一天，它会彻底消失，再也不会有人被它带走。",
            ["ContentFR"] = "Et un jour, quand assez de gens se lèveront contre lui... le monstre disparaîtra. Plus personne ne sera jamais emporté.",
            ["DialogueId"] = 12034007,
            ["GUID"] = "1E203946",
            ["NextDialogue"] = 12034008,
            ["Scripts"] = "PARA{\
LookAt{_delay{0.5},LookAtDescription{\"100001:n(211015)\"}},\
LookAt{_delay{0},LookAtDescription{\"211001:n(211015)\"}}\
}",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E203946",
            },
        [12034008] = {
            ["Content"] = "到那个时候，爸爸妈妈就会回来了吗？",
            ["ContentFR"] = "Et... à ce moment-là, papa et maman reviendront ?",
            ["DialogueId"] = 12034008,
            ["GUID"] = "1E203970",
            ["NextDialogue"] = 12034009,
            ["Scripts"] = "PlayAnimation{_delay{0},ActorId{211015},AnimationId{\"Angry01_End\"}}",
            ["SpeakNpcId"] = 211015,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E203970",
            },
        [12034009] = {
            ["Camera"] = "233.281982,106.357674,119.521484,0.000222,-13.803983,-176.218384,22.0,253.785858,false,Manual,6.0",
            ["Content"] = "到那个时候……你就会拥有很多朋友、很多幸福和爱，即便爸爸妈妈不在，你也能好好地生活下去。",
            ["ContentFR"] = "À ce moment-là, tu auras plein d’amis, plein d’amour et de bonheur autour de toi. Même si papa et maman ne reviennent pas, tu ne seras plus jamais seul, et ta vie sera belle.",
            ["DialogueId"] = 12034009,
            ["GUID"] = "1E20399A",
            ["NextDialogue"] = 12034010,
            ["Scripts"] = "PlayAnimation{_delay{0},ActorId{100001},AnimationId{\"Talk02_End\"}}",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E20399A",
            },
        [12034010] = {
            ["Camera"] = "85.880272,91.637543,126.474609,0.000195,-26.403782,175.779465,22.0,117.791931,false,Manual,22.0",
            ["Content"] = "唔……",
            ["ContentFR"] = "Hmm...",
            ["DialogueId"] = 12034010,
            ["FinalCamera"] = "71.9813,92.660332,119.553711,0.000195,-26.403761,175.779602,22.0,117.791931,false,Manual,22.0",
            ["GUID"] = "1E2039C4",
            ["NextDialogue"] = 12034011,
            ["Scripts"] = "PARA{\
LookAt{_delay{0},LookAtDescription{\"211015:n(211015)\"}},\
PlayFacial{ActorId{211015},FacialId{\"CM_Sad01\"}}\
}",
            ["SpeakNpcId"] = 211015,
            ["ToFinalCameraBlendTime"] = 4,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E2039C4",
            },
        [12034011] = {
            ["Content"] = "那么……菲娜也要到那个时候才能重新变成我的姐姐吗？",
            ["ContentFR"] = "... Alors... Fina, il faudra attendre ce jour-là pour que tu redeviennes ma grande sœur ?",
            ["DialogueId"] = 12034011,
            ["GUID"] = "1E2039EE",
            ["NextDialogue"] = 12034012,
            ["Scripts"] = "PARA{\
LookAt{_delay{0},LookAtDescription{\"211015:n(211001)\"}},\
PlayFacial{ActorId{211015},FacialId{\"CM_Idle\"}}\
}",
            ["SpeakNpcId"] = 211015,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E2039EE",
            },
        [12034012] = {
            ["Camera"] = "-48.437469,142.583008,78.972656,0.000206,6.394313,-16.618864,22.0,218.840088,false,Manual,6.0",
            ["Content"] = "嗯，我想是的……不过，在那之前，我可以当你的朋友——就像我和卡珊德拉小姐是朋友一样！",
            ["ContentFR"] = "Je crois que oui... Mais, en attendant, je peux être ton amie — comme je suis amie avec Cassandra !",
            ["DialogueId"] = 12034012,
            ["GUID"] = "1E203A18",
            ["NextDialogue"] = 12034013,
            ["Scripts"] = "PARA{\
LookAt{_delay{0},LookAtDescription{\"211015:n(211001)\"}},\
PlayAnimation{_delay{0},ActorId{211001},AnimationId{\"AgreeHead\"}}\
}",
            ["SpeakNpcId"] = 211001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E203A18",
            },
        [12034013] = {
            ["Camera"] = "193.77005,92.50441,93.731445,0.000228,-8.205721,-167.416855,22.000006,201.064499,false,Manual,6.0",
            ["Content"] = "卡珊德拉？",
            ["ContentFR"] = "Cassandra... ?",
            ["DialogueId"] = 12034013,
            ["GUID"] = "1E203A42",
            ["SpeakNpcId"] = 211015,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E203A42",
            },
        [12034014] = {
            ["Content"] = "卡珊德拉和若干帝国兵出现",
            ["ContentFR"] = "L’arrivée des soldats (Cassandra arrive avec un groupe de soldats de l’Empire.)",
            ["DialogueId"] = 12034014,
            ["GUID"] = "1E203A6C",
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E203A6C",
            },
        [12034101] = {
            ["Camera"] = "-205.291214,228.958771,119.550781,0.000071,-1.759341,11.196725,40.0,130.993866,false,Manual,5.0",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "所有人不许动，我们是治安署的！",
            ["ContentFR"] = "Ne bougez plus ! Sécurité impériale !",
            ["DialogueId"] = 12034101,
            ["FinalCamera"] = "-205.172699,263.595032,126.101562,0.000074,-5.759399,3.396292,40.0,595.173035,false,Manual,5.0",
            ["GUID"] = "1E2048B2",
            ["LookAt"] = {
                [1] = "211015:n(100001)",
                [2] = "\
211001:n(100001)",
                },
            ["NextDialogue"] = 12034102,
            ["Scripts"] = "TurnTo{_delay{1},TurnToDescription{\"100001:n(211012)\"}}",
            ["SpeakNpcName"] = "UI_FNNpc_Name_SoldierPSD",
            ["ToFinalCameraBlendTime"] = 3,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E2048B2",
            },
        [12034102] = {
            ["Camera"] = "986.973083,1585.42395,715.091797,0.00005,-23.758293,-121.993103,35.0,1732.474731,false,Manual,1.2",
            ["CameraBlendCurve"] = "easeOutQuad",
            ["Content"] = "嗯……？这些强盗……已经被制服了？",
            ["ContentFR"] = "Hmm... ? Ces bandits sont déjà neutralisés ?",
            ["DialogueId"] = 12034102,
            ["FinalCamera"] = "977.238586,1591.515625,715.091797,0.00005,-23.758293,-121.993103,35.0,1732.474731,false,Manual,1.2",
            ["GUID"] = "1E2048DC",
            ["NextDialogue"] = 12034103,
            ["SpeakNpcName"] = "UI_FNNpc_Name_SoldierPSD",
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E2048DC",
            },
        [12034103] = {
            ["Camera"] = "483.208221,510.672333,132.758789,0.000056,-4.557485,-150.607956,50.0,557.577881,false,Manual,8.0",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "是的，我们是卡珊德拉小姐雇佣的狩月人，已经把强盗打倒了。",
            ["ContentFR"] = "Oui. Nous sommes des Chasseurs de Phoxènes, engagés par Mademoiselle Cassandra. Nous les avons vaincus.",
            ["DialogueId"] = 12034103,
            ["FinalCamera"] = "486.036987,505.621124,132.758789,0.000056,-4.557485,-150.607956,50.0,557.577881,false,Manual,8.0",
            ["GUID"] = "1E204906",
            ["NextDialogue"] = 12034104,
            ["Scripts"] = "SEQ{\
MoveTo{ActorId{100001},TargetPoint{\"Feina_FixSimple38_nvzhuMove1\"},MoveSpeed{40},Visibility{\"Show\"}},\
PlayAnimation{ActorId{100001},AnimationId{\"Explain01L_Start\"},Duration{1}}\
\
}",
            ["SpeakNpcId"] = 100001,
            ["ToFinalCameraBlendTime"] = 6,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E204906",
            },
        [12034104] = {
            ["Camera"] = "229.517212,445.407562,72.137695,-0.0,16.841286,-9.204861,50.0,173.055267,false,Manual,8.0",
            ["Content"] = "是吗？",
            ["ContentFR"] = "Vraiment... ?",
            ["DialogueId"] = 12034104,
            ["GUID"] = "1E204930",
            ["NextDialogue"] = 12034105,
            ["Scripts"] = "PlayAnimation{ActorId{100001},AnimationId{\"Explain01L_End\"},Duration{1}}",
            ["SpeakNpcName"] = "UI_FNNpc_Name_SoldierPSD",
            ["ToFinalCameraBlendTime"] = 3,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E204930",
            },
        [12034105] = {
            ["Camera"] = "-876.449036,601.317261,201.322266,0.000065,-11.157715,-19.005154,30.0,173.055267,false,DoNotOverride,8.0",
            ["Content"] = "没错没错，他们俩都是我雇的人，不是可疑人物！",
            ["ContentFR"] = "Exactement ! C’est moi qui les ai embauchés. Ce ne sont pas des méchants !",
            ["DialogueId"] = 12034105,
            ["FinalCamera"] = "-876.449036,601.317261,217.300781,0.000066,-10.35766,-19.005308,30.0,173.055267,false,DoNotOverride,8.0",
            ["GUID"] = "1E20495A",
            ["NextDialogue"] = 12034106,
            ["SpeakNpcId"] = 211012,
            ["ToFinalCameraBlendTime"] = 5,
            ["TurnTo"] = {
                [1] = "211012:p(-180)",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E20495A",
            },
        [12034106] = {
            ["Camera"] = "-261.812439,310.25946,99.939453,0.000086,-2.357686,-2.005544,35.0,688.037964,false,Manual,4.0",
            ["Content"] = "……好吧，那我们就把这些强盗带走了。",
            ["ContentFR"] = "... Très bien. Nous allons emmener ces bandits.",
            ["DialogueId"] = 12034106,
            ["FinalCamera"] = "-261.654846,314.867767,99.939453,0.000086,-2.357686,-1.605461,35.0,688.037964,false,Manual,4.0",
            ["GUID"] = "1E204984",
            ["NextDialogue"] = 12034107,
            ["SpeakNpcName"] = "UI_FNNpc_Name_SoldierPSD",
            ["ToFinalCameraBlendTime"] = 4.5,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E204984",
            },
        [12034107] = {
            ["Camera"] = "199.814636,389.031067,112.981445,0.000071,1.842389,7.599753,50.0,198.341919,false,Manual,5.0",
            ["Content"] = "之前有个臭捡垃圾的卡戎一直来署里吵着说什么泪湖有强盗，还以为她是瞎编的，没想到居然是真的……",
            ["ContentFR"] = "Hmpf... cette fichue Charon récupératrice qui arrêtait pas de venir nous bassiner avec ses histoires de brigands au Lac du Deuil... On pensait qu’elle radotait, mais finalement elle disait vrai.",
            ["DialogueId"] = 12034107,
            ["FinalCamera"] = "199.727524,389.644745,112.981445,0.000072,2.04239,8.399999,55.0,198.341919,false,Manual,5.0",
            ["GUID"] = "1E2049AE",
            ["SpeakNpcName"] = "UI_FNNpc_Name_SoldierPSD",
            ["ToFinalCameraBlendTime"] = 12,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E2049AE",
            },
        [12034108] = {
            ["Content"] = "转场，帝国兵和强盗消失",
            ["ContentFR"] = "(Les soldats s’éloignent, emportant les bandits. Cassandra et Savio se rapprochent.)",
            ["DialogueId"] = 12034108,
            ["GUID"] = "1E2049D8",
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E2049D8",
            },
        [12034201] = {
            ["Camera"] = "87.895348,214.805466,327.84668,0.000057,-19.94603,160.421906,50.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "卡珊德拉……是你让他们来找我的吗？",
            ["ContentFR"] = "Cassandra... c’est toi qui les as envoyés me chercher ?",
            ["DialogueId"] = 12034201,
            ["FinalCamera"] = "82.289337,199.953339,327.84668,0.000058,-19.546021,158.621765,50.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "1E20591A",
            ["LookAt"] = {
                [1] = "100001:n(211012)",
                [2] = "\
211001:n(211012)",
                },
            ["NextDialogue"] = 12034202,
            ["SpeakNpcId"] = 211015,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E20591A",
            },
        [12034202] = {
            ["Camera"] = "-942.397278,-54.10989,181.074219,0.000047,-11.546441,59.81805,50.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "当然了，不是我还能是谁？你为什么要跑到城外来呀，吓死我了！",
            ["ContentFR"] = "Bien sûr ! Qui d’autre ? Pourquoi t’es-tu aventuré hors de la cité ? Tu m’as fichu une de ces peurs !",
            ["DialogueId"] = 12034202,
            ["FinalCamera"] = "-947.833069,-50.950378,181.074219,0.000047,-11.546441,59.81805,50.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "1E205944",
            ["NextDialogue"] = 12034203,
            ["SpeakNpcId"] = 211012,
            ["TalkActionId"] = {
                [1] = "211012:Confident_Start",
                },
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E205944",
            },
        [12034203] = {
            ["Camera"] = "-317.916473,488.004974,97.504883,0.000046,-2.946106,-178.584473,50.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我……我还以为你也不想跟我玩了。如果谁都不想看见我，那我还不如不回学校了……",
            ["ContentFR"] = "Je... je croyais que tu ne voulais plus jouer avec moi. Et si plus personne ne voulait me voir... alors autant ne plus retourner à l’école.",
            ["DialogueId"] = 12034203,
            ["FinalCamera"] = "-317.916473,488.004974,90.661133,0.000046,-3.146053,-178.384689,50.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "1E20596E",
            ["NextDialogue"] = 12034204,
            ["SpeakNpcId"] = 211015,
            ["TalkActionId"] = {
                [1] = "211012:Confident_End",
                [2] = "\
211015:Sigh_Start",
                },
            ["ToFinalCameraBlendTime"] = 13,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E20596E",
            },
        [12034204] = {
            ["Camera"] = "-896.072571,82.03035,63.115234,0.00007,-0.346345,57.812359,50.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "说什么傻话呢，我们是朋友啊！你再把我想得和那些坏小孩一样，我可是会生气——啊，你受伤了吗？！",
            ["ContentFR"] = "N’importe quoi ! On est amis ! Si tu me compares encore à ces sales garnements, je vais me fâcher pour de vrai— attends... tu es blessé ?!",
            ["DialogueId"] = 12034204,
            ["FinalCamera"] = "-890.340332,78.4217,63.115234,0.00007,-0.346345,57.811806,50.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "1E205998",
            ["NextDialogue"] = 12034205,
            ["Scripts"] = "PlayAnimation{_delay{11},ActorId{211012},AnimationId{\"Angry01_End\"},Duration{1}}",
            ["SpeakNpcId"] = 211012,
            ["TalkActionId"] = {
                [1] = "211015:Sigh_End",
                [2] = "\
211012:Angry01_Start",
                },
            ["ToFinalCameraBlendTime"] = 12,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E205998",
            },
        [12034205] = {
            ["Camera"] = "-405.626709,506.263672,87.52832,0.000071,-1.545767,-172.392715,50.0,285.715515,false,Manual,8.0",
            ["Content"] = "没事的，只是一点擦伤。谢谢你，卡珊德拉。",
            ["ContentFR"] = "Ce n’est rien, juste des égratignures. Merci, Cassandra.",
            ["DialogueId"] = 12034205,
            ["GUID"] = "1E2059C2",
            ["NextDialogue"] = 12034206,
            ["SpeakNpcId"] = 211015,
            ["TalkActionId"] = {
                [1] = "211015:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E2059C2",
            },
        [12034206] = {
            ["Camera"] = "151.844269,80.657501,37.138672,0.000095,1.654081,151.40625,50.0,940.830017,false,Manual,8.0",
            ["Content"] = "多亏了你，我不仅得救了，而且……我终于找到蝴蝶精灵了。",
            ["ContentFR"] = "Grâce à toi, je suis sauf... et j’ai enfin trouvé la Fée-Papillon.",
            ["DialogueId"] = 12034206,
            ["FinalCamera"] = "149.475693,76.349304,37.138672,0.000096,1.654081,150.606277,50.0,940.830017,false,Manual,8.0",
            ["GUID"] = "1E2059EC",
            ["NextDialogue"] = 12034207,
            ["SpeakNpcId"] = 211015,
            ["TalkActionId"] = {
                [1] = "211015:Explain02_Start",
                },
            ["ToFinalCameraBlendTime"] = 7,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E2059EC",
            },
        [12034207] = {
            ["Camera"] = "-899.9151,108.874062,146.229492,0.000112,-9.546234,55.209587,50.0,552.772644,false,DoNotOverride,8.0",
            ["Content"] = "喔，那真是太好了！等回到学校，你一定要给我好好讲讲。",
            ["ContentFR"] = "Vraiment ?! Génial ! Tu devras tout me raconter en détail à l’école !",
            ["DialogueId"] = 12034207,
            ["FinalCamera"] = "-899.9151,108.874062,133.772461,0.000113,-8.146189,54.209774,50.0,552.772644,false,DoNotOverride,8.0",
            ["GUID"] = "1E205A16",
            ["NextDialogue"] = 12034208,
            ["SpeakNpcId"] = 211012,
            ["TalkActionId"] = {
                [1] = "211015:Explain02_End",
                [2] = "\
211012:Agree",
                },
            ["ToFinalCameraBlendTime"] = 6,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E205A16",
            },
        [12034208] = {
            ["Content"] = "嗯！",
            ["ContentFR"] = "Oui !",
            ["DialogueId"] = 12034208,
            ["GUID"] = "1E205A40",
            ["NextDialogue"] = 12034209,
            ["SpeakNpcId"] = 211015,
            ["TalkActionId"] = {
                [1] = "211015:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E205A40",
            },
        [12034209] = {
            ["Camera"] = "-690.500427,676.570496,85.366211,0.000123,0.853248,-66.382408,40.0,552.772644,false,DoNotOverride,8.0",
            ["Content"] = "菲娜，{nickname}{性别：哥哥|姐姐}，谢谢你们救了我的朋友！",
            ["ContentFR"] = "Fina, {性别:Monsieur|Mademoiselle} {nickname}, merci d’avoir sauvé mon ami !",
            ["DialogueId"] = 12034209,
            ["FinalCamera"] = "-706.813965,669.448181,85.366211,0.000124,1.053249,-65.382294,40.0,552.772644,false,DoNotOverride,8.0",
            ["GUID"] = "1E205A6A",
            ["NextDialogue"] = 12034210,
            ["Scripts"] = "PARA{\
MoveTo{ActorId{100001},TargetPoint{\"Feina_FixSimple39_nvzhuMove\"},MoveSpeed{60},Visibility{\"Show\"}},\
