            ["SpeakNpcId"] = 100001,
            ["ToFinalCameraBlendTime"] = 6,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E205C0E",
            },
        [12034227] = {
            ["Content"] = "回冰湖城广场",
            ["ContentFR"] = "Une invitation inattendue (De retour sur la place de Givrelac, juste derrière les portes de la cité.)",
            ["DialogueId"] = 12034227,
            ["GUID"] = "1E205D5E",
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E205D5E",
            },
        [12034301] = {
            ["Camera"] = "-191.809433,63.705963,132.844238,0.000047,-4.982602,40.37281,50.0,345.933563,false,Manual,8.0",
            ["Content"] = "那、那个……",
            ["ContentFR"] = "Euh... euh...",
