            ["DialogueId"] = 12034407,
            ["GUID"] = "1E207AE6",
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E207AE6",
            },
        [12034501] = {
            ["Camera"] = "211.434235,245.470703,131.753906,0.000086,-6.587157,-77.601845,35.000008,263.858795,false,DoNotOverride,2.8",
            ["Content"] = "菲娜姐姐，是我。",
            ["ContentFR"] = "Grande sœur Fina, c’est moi !",
            ["DialogueId"] = 12034501,
            ["GUID"] = "1E208A52",
            ["LookAt"] = {
