            ["TurnTo"] = {
                [1] = "211001:n(211015)",
                [2] = "211015:n(211001)",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E208A52",
            },
        [12034502] = {
            ["Camera"] = "159.932434,-91.392578,117.648438,0.000089,-1.587063,60.598072,35.000008,263.858795,false,DoNotOverride,2.8",
            ["Content"] = "塞维欧？你怎么一个人来了呀？",
            ["ContentFR"] = "Savio ? Pourquoi tu viens tout seul ? Cassandra n’est pas avec toi ?",
            ["DialogueId"] = 12034502,
            ["GUID"] = "1E208A7C",
            ["NextDialogue"] = 12034503,
            ["Scripts"] = "SEQ{\
