}",
            ["SpeakNpcId"] = 211015,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E208AA6",
            },
        [12034504] = {
            ["Content"] = "你看！",
            ["ContentFR"] = "Regarde !",
            ["DialogueId"] = 12034504,
            ["GUID"] = "1E208AD0",
