        [12034505] = {
            ["Content"] = "转场，菲娜和塞维欧站在房间里，菲娜的床上摆放白鸟玩偶",
            ["DialogueId"] = 12034505,
            ["GUID"] = "1E208AFA",
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E208AFA",
            },
        [12034601] = {
            ["Camera"] = "222.182312,78.296875,125.328125,0.000062,1.812971,58.197723,35.000011,70.022163,false,DoNotOverride,2.8",
            ["Content"] = "是白鸟先生……！",
            ["ContentFR"] = "C’est... Monsieur l’Oiseau blanc !",
            ["DialogueId"] = 12034601,
            ["GUID"] = "1E209ABA",
            ["NextDialogue"] = 12034602,
            ["Scripts"] = "SEQ{\
PlayFacial{_delay{0.1},ActorId{211001},FacialId{\"Shock01\"}},\
PlayFacial{_delay{1.1},ActorId{211001},FacialId{\"Smile01\"}}\
}",
            ["SpeakNpcId"] = 211001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E209ABA",
            },
        [12034602] = {
            ["Camera"] = "211.434235,245.470703,131.753906,0.000086,-6.587157,-77.601845,35.000008,263.858795,false,DoNotOverride,2.8",
            ["Content"] = "我知道这是菲娜姐姐最喜欢的玩偶，所以你走了以后，我一直把它藏在柜子里，想着等你回来再还给你……既然你现在有了新家，就让它过来陪你吧！",
            ["ContentFR"] = "Je savais que c’était ton jouet préféré. Alors quand tu es partie, je l’ai caché bien à l’abri dans mon armoire, en attendant ton retour... Maintenant que tu as une nouvelle maison, il doit être avec toi.",
            ["DialogueId"] = 12034602,
            ["GUID"] = "1E209AE4",
            ["NextDialogue"] = 12034603,
            ["SpeakNpcId"] = 211015,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E209AE4",
            },
        [12034603] = {
            ["Camera"] = "194.921234,126.091797,122.953125,0.000114,-5.587006,11.20279,35.000011,63.917503,false,DoNotOverride,2.8",
            ["Content"] = "呜……谢谢你，塞维欧！",
            ["ContentFR"] = "Oh... merci, Savio !",
            ["DialogueId"] = 12034603,
            ["GUID"] = "1E209B0E",
            ["NextDialogue"] = 12034604,
            ["Scripts"] = "PARA{\
PlayFacial{_delay{0.1},ActorId{211001},FacialId{\"Shock01\"}},\
PlayAnimation{_delay{1.5},ActorId{211001},AnimationId{\"Explain02_Start\"}}\
}",
            ["SpeakNpcId"] = 211001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E209B0E",
            },
        [12034604] = {
            ["Content"] = "菲娜姐姐……我现在想起来了，你在我们的家里总是不太开心。现在的这个家呢，你在这里开心吗？",
            ["ContentFR"] = "Grande sœur Fina... je me souviens, dans notre maison d’avant, tu n’avais pas l’air très heureuse. Et ici ? Dans ta nouvelle maison... tu l’es ?",
            ["DialogueId"] = 12034604,
            ["GUID"] = "1E209B38",
            ["NextDialogue"] = 12034605,
            ["Scripts"] = "PlayAnimation{_delay{4.5},ActorId{211001},AnimationId{\"Explain02_End\"}}",
            ["SpeakNpcId"] = 211015,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E209B38",
            },
        [12034605] = {
            ["Content"] = "嗯，菲娜很喜欢这个新家。",
            ["ContentFR"] = "Oui. J’aime beaucoup cette maison.",
            ["DialogueId"] = 12034605,
            ["GUID"] = "1E209B62",
