}",
            ["SpeakNpcId"] = 211012,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E20AB22",
            },
        [12034702] = {
            ["Camera"] = "-205.539246,392.728455,111.792969,0.000099,-0.029329,53.919659,28.0,261.24472,false,Manual,12.0",
            ["Content"] = "哇……好棒！",
            ["ContentFR"] = "Ouaaah... ça sent trop bon !",
            ["DialogueId"] = 12034702,
            ["GUID"] = "1E20AB4C",
            ["NextDialogue"] = 12034703,
