            },
        [12034703] = {
            ["Camera"] = "-92.674431,124.656555,142.015625,0.000104,-3.829591,70.910416,28.000006,296.759796,false,Manual,4.0",
            ["Content"] = "我怎么又变回“那谁”了……",
