            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E20ACC6",
            },
        [12034712] = {
            ["Camera"] = "-171.437988,175.135666,121.905762,0.000136,-1.629813,-72.084328,55.000008,167.31073,false,Manual,1.4",
            ["Content"] = "……嗯，一言为定！谢谢你，独角兽{性别：先生|小姐}。",
            ["ContentFR"] = "... D’accord. Promis ! Merci, {性别:Monsieur|Mademoiselle} Licorne.",
            ["DialogueId"] = 12034712,
            ["FinalCamera"] = "-164.531647,153.772919,121.268555,0.000136,-1.629813,-72.084328,55.000008,142.088089,false,Manual,1.4",
