            },
        [12034713] = {
            ["Camera"] = "-470.035645,260.954132,99.352539,0.000137,3.969959,-23.284956,35.0,150.137177,false,Manual,22.0",
            ["Content"] = "菲娜，那谁{性别：哥哥|姐姐}，你们怎么还在外面讲悄悄话呀？再不进来，我们可要把蛋糕都吃光咯？",
            ["ContentFR"] = "Fina ! {性别:Le Borgne|La Borgne} ! Vous allez bavarder dehors encore longtemps ? Si vous ne rentrez pas, on dévore tous les gâteaux sans vous !",
            ["DialogueId"] = 12034713,
            ["GUID"] = "1E20AD1A",
            ["NextDialogue"] = 12034714,
            ["Scripts"] = "PARA{\
