        [12034716] = {
            ["Camera"] = "404.343994,-127.544922,169.554688,0.000054,-7.335021,141.091019,28.0,100000.0,false,Manual,22.0",
            ["Content"] = "菲娜，我回来——呜哇……？！怎、怎么这么多小孩？",
            ["ContentFR"] = "Fina ? Je suis de ret—... Hein ?! Mais... c’est quoi tout ce troupeau de gamins ?!",
            ["DialogueId"] = 12034716,
            ["GUID"] = "1E20AD98",
            ["NextDialogue"] = 12034717,
            ["Scripts"] = "SEQ{\
