}",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E20ADC2",
            },
        [12034718] = {
            ["Content"] = "你故意的吧！",
            ["ContentFR"] = "... Tu l’as fait exprès !",
            ["DialogueId"] = 12034718,
            ["GUID"] = "1E20ADEC",
            ["NextDialogue"] = 12034719,
            ["Scripts"] = "PlayAnimation{ActorId{211002},AnimationId{\"Sigh_Start\"},Duration{1}}",
            ["SpeakNpcId"] = 211002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E20ADEC",
            },
        [12034719] = {
            ["Content"] = "奥特赛德，你回来啦！他们都是菲娜的新朋友，让我来给你介绍吧！",
            ["ContentFR"] = "L’Étranger, tu es rentré ! Laisse-moi te présenter mes nouveaux amis !",
            ["DialogueId"] = 12034719,
            ["GUID"] = "1E20AE16",
            ["Scripts"] = "PARA{\
CameraMoveTo{_delay{3},TargetPosition{\"190.968307,160.283203,134.253906,0.000142,-4.628075,112.713974,35.0,117.253952,false,Manual,1.4\"},duration{0}},\
