            },
        [12034720] = {
            ["Content"] = "下面这段茶会剧情希望能用动画的形式制作，但并不需要额外动作资源，打一个慢慢移动的全景镜头，五个角色站在一起做说话动作即可（效果不好的话也可以打空镜头放个暖色灯光）\
角色台词不显示在对话框里，作为背景音播放，每两句一组",
            ["DialogueId"] = 12034720,
            ["GUID"] = "1E20AE40",
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E20AE40",
            },
        [12034801] = {
            ["Content"] = "大魔法狗是什么？",
            ["ContentFR"] = "Grand Magi-Chien ? C’est quoi ça ?",
            ["DialogueId"] = 12034801,
            ["GUID"] = "1E20BB8A",
            ["NextDialogue"] = 12034802,
            ["SpeakNpcId"] = 211012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E20BB8A",
            },
        [12034802] = {
            ["Content"] = "是大魔法师哦。",
            ["ContentFR"] = "Non non, c’est Grand Magicien !",
            ["DialogueId"] = 12034802,
            ["GUID"] = "1E20BBB4",
            ["NextDialogue"] = 12034803,
            ["SpeakNpcId"] = 211001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E20BBB4",
            },
        [12034803] = {
            ["Content"] = "咳、咳……",
            ["ContentFR"] = "Kof, kof...",
            ["DialogueId"] = 12034803,
            ["GUID"] = "1E20BBDE",
            ["NextDialogue"] = 12034804,
            ["SpeakNpcId"] = 211015,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E20BBDE",
            },
        [12034804] = {
            ["Content"] = "没事吧？快喝点水——",
            ["ContentFR"] = "Ça va ? Bois un peu d’eau !",
            ["DialogueId"] = 12034804,
            ["GUID"] = "1E20BC08",
            ["NextDialogue"] = 12034805,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E20BC08",
            },
        [12034805] = {
            ["Content"] = "啾啾，白鸟先生！",
            ["ContentFR"] = "Piou-piou ! Je suis Monsieur l’Oiseau blanc !",
            ["DialogueId"] = 12034805,
            ["GUID"] = "1E20BC32",
            ["NextDialogue"] = 12034806,
            ["SpeakNpcId"] = 211001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E20BC32",
            },
        [12034806] = {
            ["Content"] = "嚯，好肥美……",
            ["ContentFR"] = "Ouah... il est énorme !",
            ["DialogueId"] = 12034806,
            ["GUID"] = "1E20BC5C",
            ["SpeakNpcId"] = 211002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E20BC5C",
            },
        [12034807] = {
            ["Content"] = "转场，茶会结束后，菲娜一个人坐在家里",
            ["DialogueId"] = 12034807,
            ["GUID"] = "1E20BC86",
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E20BC86",
            },
        [12034901] = {
            ["Camera"] = "-16.293289,323.111328,136.453125,0.000086,-7.199647,126.990501,35.0,69.843971,false,DoNotOverride,12.0",
            ["Content"] = "小夜莺飞出自己的巢穴，向未知的世界出发冒险……一路上，小夜莺见到了可爱的魔法烤土豆、机灵的缄默侦探阁下，还有许许多多的新朋友……",
            ["ContentFR"] = "« Le petit Rossignol quitta son nid et s’envola vers l’inconnu... En chemin, il rencontra l’ingénieuse Détective Taciturne, les joyeuses Patates magiques grillées, et plein, plein de nouveaux amis... »",
            ["DialogueId"] = 12034901,
            ["FinalCamera"] = "-29.425766,297.828125,134.542969,0.000094,-5.599942,111.788467,35.0,90.44413,false,DoNotOverride,12.0",
            ["GUID"] = "1E20CBF2",
            ["NextDialogue"] = 12034902,
            ["Scripts"] = "PARA{\
CameraMoveTo{_delay{8.01},TargetPosition{\"-42.475677,435.521484,112.582031,0.000114,6.399675,-88.810791,35.0,244.499649,false,DoNotOverride,12.0\"},duration{0}},\
CameraMoveTo{_delay{8.01},TargetPosition{\"-44.494888,523.302734,101.164062,0.000112,9.799627,-88.410698,35.0,244.499649,false,DoNotOverride,12.0\"},duration{12}},\
PARA{\
PlayFacial{_delay{2.5},ActorId{211001},FacialId{\"Smile01\"}}\
}\
}",
            ["SpeakNpcId"] = 211001,
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E20CBF2",
            },
        [12034902] = {
            ["Camera"] = "65.885368,364.457031,142.957031,0.000107,-13.200897,166.389648,35.0,111.809486,false,DoNotOverride,12.0",
            ["Content"] = "小夜莺不再害怕坏巫师，也不再担心被野兽追捕了。",
            ["ContentFR"] = "« Le Rossignol n’avait plus peur des mauvais sorciers, ni des bêtes sauvages qui le poursuivaient. »",
            ["DialogueId"] = 12034902,
            ["GUID"] = "1E20CC1C",
            ["NextDialogue"] = 12034903,
            ["Scripts"] = "PlayAnimation{ActorId{211001},AnimationId{\"Feina_Story_Wish_Start\"},Duration{1}}",
            ["SpeakNpcId"] = 211001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E20CC1C",
            },
        [12034903] = {
            ["Camera"] = "-31.965088,301.212891,134.277344,0.000101,-7.000998,109.790298,35.0,90.981918,false,DoNotOverride,12.0",
            ["Content"] = "因为，现在它知道，无论外面的世界多么阴森可怕……只要和朋友们手拉着手，就总能围出一个彩色的梦。",
            ["ContentFR"] = "« Car maintenant, il savait que, même si le monde dehors pouvait être sombre et effrayant... tant qu’il tenait la main de ses amis, il trouverait toujours le chemin vers un rêve aux mille couleurs. »",
            ["DialogueId"] = 12034903,
            ["FinalCamera"] = "-35.076675,309.947266,133.269531,0.000102,-5.800961,109.79023,35.0,70.654915,false,DoNotOverride,12.0",
            ["GUID"] = "1E20CC46",
            ["Scripts"] = "PARA{\
PlayFacial{_delay{2.5},ActorId{211001},FacialId{\"Satisfy01\"}},\
PlayFacial{_delay{5.5},ActorId{211001},FacialId{\"Smile02\"}},\
PlayFacial{_delay{8.5},ActorId{211001},FacialId{\"Smile01\"}}\
}",
            ["SpeakNpcId"] = 211001,
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E20CC46",
            },
        [12034904] = {
            ["Content"] = "解锁并完成玩法第四关",
            ["ContentFR"] = "(Quatrième mini-jeu débloqué. Terminez le jeu pour continuer.)",
            ["DialogueId"] = 12034904,
            ["GUID"] = "1E20CC70",
            ["NextDialogue"] = 12034905,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E20CC70",
            },
        [12034905] = {
            ["Content"] = "第四关通过后，直接进入收尾动画",
            ["ContentFR"] = "(La complétion mène à la cinématique de fin.)",
            ["DialogueId"] = 12034905,
            ["GUID"] = "1E20CC9A",
            ["NextDialogue"] = 12034906,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E20CC9A",
            },
        [12034906] = {
            ["Content"] = "菲娜拿着魔法书，四个召唤兽围绕在她身边。她微笑着合上书，召唤兽们也随之消失了。",
            ["ContentFR"] = "Fina, un grimoire entre les mains, referme doucement le livre avec un sourire. Autour d’elle, ses quatre compagnons invoqués l’entourent encore un instant... puis disparaissent dans la nuit.",
            ["DialogueId"] = 12034906,
            ["GUID"] = "1E20CCC4",
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E20CCC4",
            },
        [12034910] = {
            ["Content"] = "【过场1】菲娜抵御强盗Activty_Feina_SC001",
            ["DialogueId"] = 12034910,
            ["GUID"] = "1E20CCC5",
            },
        [12034911] = {
            ["Content"] = "【过场2】结局大合照Activty_Feina_SC002",
            ["DialogueId"] = 12034911,
            ["GUID"] = "1E20CCC6",
            },
        [12034912] = {
            ["Content"] = "【过场3】奥特赛德家的晚会Activty_Feina_SC003",
            ["DialogueId"] = 12034912,
            ["GUID"] = "1E20CCC7",
            },
        [12035001] = {
            ["Content"] = "今天还是不要走太远比较好。",
            ["DialogueId"] = 12035001,
            ["GUID"] = "1E20DC5A",
            },
        [12035002] = {
            ["Content"] = "巢穴之外，有着广阔的世界。",
            ["DialogueId"] = 12035002,
            ["GUID"] = "1E20DC84",
            },
        [12035003] = {
            ["Content"] = "这条河流，一路向着危险的秘境。",
            ["DialogueId"] = 12035003,
            ["GUID"] = "1E20DCAE",
            },
        [12035004] = {
            ["Content"] = "是点石成金的公主殿下！",
            ["DialogueId"] = 12035004,
            ["GUID"] = "1E20DCD8",
            },
        [12035005] = {
            ["Content"] = "公主殿下看上去似乎很忙，还是不要打扰她了。",
            ["DialogueId"] = 12035005,
            ["GUID"] = "1E20DD02",
            },
        [12035006] = {
            ["Content"] = "小夜莺与点石成金的公主殿下擦肩而过，继续踏上旅途。",
            ["DialogueId"] = 12035006,
            ["GUID"] = "1E20DD2C",
            },
        [12035007] = {
            ["Content"] = "穿过砖石和钢铁铸造的森林。",
            ["DialogueId"] = 12035007,
            ["GUID"] = "1E20DD56",
            },
        [12035008] = {
            ["Content"] = "前方还有什么在等待着她呢？",
            ["DialogueId"] = 12035008,
            ["GUID"] = "1E20DD80",
            },
        [12035009] = {
            ["Content"] = "就像是童话里魔龙的嘴。",
            ["DialogueId"] = 12035009,
            ["GUID"] = "1E20DDAA",
            },
        [12035010] = {
            ["Content"] = "吸血鬼？他们似乎在谈论菲娜的事。",
            ["DialogueId"] = 12035010,
            ["GUID"] = "1E20DDD4",
            },
        [12035011] = {
            ["Content"] = "怎么办！她过来了！",
            ["DialogueId"] = 12035011,
            ["GUID"] = "1E20DDFE",
            },
        [12035012] = {
            ["Content"] = "先往这个方向看看？",
            ["DialogueId"] = 12035012,
            ["GUID"] = "1E20DE28",
            },
        [12035013] = {
            ["Content"] = "似乎不在这里……",
            ["DialogueId"] = 12035013,
            ["GUID"] = "1E20DE52",
            },
        [12035014] = {
            ["Content"] = "也许……",
            ["DialogueId"] = 12035014,
            ["GUID"] = "1E20DE7C",
            },
        [12035015] = {
            ["Content"] = "是保卫水管的叔叔。",
            ["DialogueId"] = 12035015,
            ["GUID"] = "1E20DEA6",
            },
        [12035016] = {
            ["Content"] = "那边的是！",
            ["DialogueId"] = 12035016,
            ["GUID"] = "1E20DED0",
            },
        [12035017] = {
            ["Content"] = "好可爱！",
            ["DialogueId"] = 12035017,
            ["GUID"] = "1E20DEFA",
            },
        [12035050] = {
            ["Content"] = "这次，菲娜去这个方向找小土豆们！",
            ["DialogueId"] = 12035050,
            ["GUID"] = "1E20E464",
            },
        [12035051] = {
            ["Content"] = "难道说小土豆们钻到了井盖下面？",
            ["DialogueId"] = 12035051,
            ["GUID"] = "1E20E48E",
            },
        [12035052] = {
            ["Content"] = "果然不在这里……",
            ["DialogueId"] = 12035052,
            ["GUID"] = "1E20E4B8",
            },
        [12035053] = {
            ["Content"] = "不对不对，得先去找小土豆们。",
            ["DialogueId"] = 12035053,
            ["GUID"] = "1E20E4E2",
            },
        [12035054] = {
            ["Content"] = "那里有声音！",
            ["DialogueId"] = 12035054,
            ["GUID"] = "1E20E50C",
            },
        [12035055] = {
            ["Content"] = "小土豆肯定藏在这里。",
            ["DialogueId"] = 12035055,
            ["GUID"] = "1E20E536",
            },
        [12035056] = {
            ["Content"] = "是小猫！",
            ["DialogueId"] = 12035056,
            ["GUID"] = "1E20E560",
            },
        [12035075] = {
            ["Content"] = "这是我。",
            ["DialogueId"] = 12035075,
            ["GUID"] = "1E20E87E",
            },
        [12035076] = {
            ["Content"] = "菲娜。",
            ["DialogueId"] = 12035076,
            ["GUID"] = "1E20E8A8",
            },
        [12035077] = {
            ["Content"] = "是大魔法师。",
            ["DialogueId"] = 12035077,
            ["GUID"] = "1E20E8D2",
            },
        [12035101] = {
            ["Content"] = "熟悉的天花板。",
            ["DialogueId"] = 12035101,
            ["GUID"] = "1E20ECC2",
            },
        [12035102] = {
            ["Content"] = "夜莺",
            ["DialogueId"] = 12035102,
            ["GUID"] = "1E20ECEC",
            },
        [12035103] = {
            ["Content"] = "还有",
            ["DialogueId"] = 12035103,
            ["GUID"] = "1E20ED16",
            },
        [12035104] = {
            ["Content"] = "大魔法师",
            ["DialogueId"] = 12035104,
            ["GUID"] = "1E20ED40",
            },
        [12035105] = {
            ["Content"] = "太阳",
            ["DialogueId"] = 12035105,
            ["GUID"] = "1E20ED6A",
            },
        [12035106] = {
            ["Content"] = "好刺眼",
            ["DialogueId"] = 12035106,
            ["GUID"] = "1E20ED94",
            },
        [12035107] = {
            ["Content"] = "菲娜得起床了……",
            ["DialogueId"] = 12035107,
            ["GUID"] = "1E20EDBE",
            },
        [12035108] = {
            ["Content"] = "昨晚写的故事",
            ["DialogueId"] = 12035108,
            ["GUID"] = "1E20EDE8",
            },
        [12035109] = {
            ["Content"] = "头好重",
            ["DialogueId"] = 12035109,
            ["GUID"] = "1E20EE12",
            },
        [12035110] = {
            ["Content"] = "早起的鸟儿有虫吃",
            ["DialogueId"] = 12035110,
            ["GUID"] = "1E20EE3C",
            },
        [12035111] = {
            ["Content"] = "奥特赛德已经出门了",
            ["DialogueId"] = 12035111,
            ["GUID"] = "1E20EE66",
            },
        [12035113] = {
            ["Content"] = "你一觉睡到了下午，明天的事明天再说吧。",
            ["DialogueId"] = 12035113,
            ["GUID"] = "1E20EEBA",
            },
        [12035114] = {
            ["Content"] = "尝试起床",
            ["DialogueId"] = 12035114,
            ["GUID"] = "1E20EEE4",
            },
        [12035115] = {
            ["Content"] = "……",
            ["DialogueId"] = 12035115,
            ["GUID"] = "1E20EF0E",
            },
        [12035201] = {
            ["Content"] = "菲娜的书",
            ["DialogueId"] = 12035201,
            ["GUID"] = "1E20FD2A",
            },
        [12035202] = {
            ["Content"] = "温暖的火炉",
            ["DialogueId"] = 12035202,
            ["GUID"] = "1E20FD54",
            },
        [12035203] = {
            ["Content"] = "窗外的世界……",
            ["DialogueId"] = 12035203,
            ["GUID"] = "1E20FD7E",
            },
        [12035204] = {
            ["Content"] = "大魔法师和夜莺",
            ["DialogueId"] = 12035204,
            ["GUID"] = "1E20FDA8",
            },
        [12035205] = {
            ["Content"] = "大魔法师很早就会起床",
            ["DialogueId"] = 12035205,
            ["GUID"] = "1E20FDD2",
            },
        [12035206] = {
            ["Content"] = "很久没有出门了",
            ["DialogueId"] = 12035206,
            ["GUID"] = "1E20FDFC",
            },
        [12035301] = {
            ["Content"] = "大魔法师，有着敏锐的嗅觉。",
            ["DialogueId"] = 12035301,
            ["GUID"] = "1E210D92",
            },
        [12035302] = {
            ["Content"] = "他能做到很多不可思议的事情。",
            ["DialogueId"] = 12035302,
            ["GUID"] = "1E210DBC",
            },
        [12035303] = {
            ["Content"] = "大魔法的意思应该是让菲娜看看箱子后面？",
            ["DialogueId"] = 12035303,
            ["GUID"] = "1E210DE6",
            },
        [12035304] = {
            ["Content"] = "大魔法师说\"菲娜要尝试全力向上跳跃！\"",
            ["DialogueId"] = 12035304,
            ["GUID"] = "1E210E10",
            },
        [12035310] = {
            ["Camera"] = "-182.732056,402.138672,75.417969,0.000544,6.001974,107.204239,35.0,252.889053,false,Manual,8.0",
            ["Content"] = "（曾在冰冷的大宅邸中陪伴菲娜度过许多孤独时刻的可靠伙伴，拥有柔软羽毛和宽大翅膀的白鸟先生。）",
            ["DialogueId"] = 12035310,
            ["NextDialogue"] = 12035311,
            },
        [12035311] = {
            ["Content"] = "（虽然一度失散，但在塞维欧的帮助下，白鸟先生现在又重新回到了菲娜的身边，从今往后也会继续用它圆溜溜的眼睛一直守望着菲娜。）",
            ["DialogueId"] = 12035311,
            },
        [12040101] = {
            ["Content"] = "……一切难道就会完全按照<H>你</>的想法去发生吗？",
            ["ContentFR"] = "... Pensez-vous vraiment que tout se déroulera exactement comme <H>vous</> l’avez prévu ?",
            ["DialogueId"] = 12040101,
            ["GUID"] = "1E242112",
            ["NextDialogue"] = 12040102,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120401/1E242112",
            },
        [12040102] = {
            ["Content"] = "是的，{nickname}，这就是定数。定数是不可更改的。",
            ["ContentFR"] = "Oui, {nickname}. C’est là ce qu’on appelle le cours immuable du destin. Ce qui est décrété ne saurait être altéré.",
            ["DialogueId"] = 12040102,
            ["GUID"] = "1E24213C",
            ["NextDialogue"] = 12040103,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120401/1E24213C",
            },
        [12040103] = {
            ["Content"] = "人心、变量，难道一切都在你的算计中吗？我不信。人既然有着选择的自由，就不可能被所谓的预言摆布——",
            ["ContentFR"] = "Le cœur humain, les imprévus... tout cela entre aussi dans vos calculs ? Je n’y crois pas. Tant que l’homme conserve le pouvoir de choisir, aucune prophétie ne peut l’enchaîner—",
            ["DialogueId"] = 12040103,
            ["GUID"] = "1E242166",
            ["NextDialogue"] = 12040104,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120401/1E242166",
            },
        [12040104] = {
            ["Content"] = "呵呵……虽然和你聊天很愉快，但我们的时间已经所剩无几了。",
            ["ContentFR"] = "Héhé... Notre échange fut agréable, mais le temps nous est désormais compté.",
            ["DialogueId"] = 12040104,
            ["GUID"] = "1E242190",
            ["NextDialogue"] = 12040105,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120401/1E242190",
            },
        [12040105] = {
            ["Content"] = "接下来，<W>忘记我，忘记我们说过的一切</>，好吗？",
            ["ContentFR"] = "À présent... <W>oublie-moi. Oublie tout ce que nous nous sommes dit</>. D’accord ?",
            ["DialogueId"] = 12040105,
            ["GUID"] = "1E2421BA",
            ["NextDialogue"] = 12040106,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120401/1E2421BA",
            },
        [12040106] = {
            ["Content"] = "不，我拒绝——",
            ["ContentFR"] = "Non, je refuse—",
            ["DialogueId"] = 12040106,
            ["GUID"] = "1E2421E4",
            ["NextDialogue"] = 12040107,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120401/1E2421E4",
            },
        [12040107] = {
            ["Content"] = "……抱歉，{nickname}。命运的算筹已经掷下，我们都没有拒绝的资格。",
            ["ContentFR"] = "... Pardonne-moi, {nickname}. Le verdict du destin est déjà scellé. Ni toi ni moi n’avons le droit d’en contester l’issue.",
            ["DialogueId"] = 12040107,
            ["GUID"] = "1E24220E",
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120401/1E24220E",
            },
        [12040201] = {
            ["Content"] = "呵呵……也是正巧被你们赶上这时节了。<H>奉香大典</>可是华胥一年到头中顶顶热闹的日子。",
            ["ContentFR"] = "Héhé... Vous tombez d’ailleurs à une période fort opportune. La Cérémonie de l’Encens est le moment le plus fastueux de l’année à Huaxu.",
            ["DialogueId"] = 12040201,
            ["GUID"] = "1E24317A",
            ["NextDialogue"] = 12040202,
            ["RelatedWikiId"] = {
                [1] = 408010,
                [2] = 203001,
                [3] = 405014,
                },
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120402/1E24317A",
            },
        [12040202] = {
            ["Content"] = "临近节庆，四面八方的华胥民众都会汇聚到辇毂之下的皓京。种种节庆限定的美食、布景、仪典，都会在最近筹备起来。",
            ["ContentFR"] = "À l’approche des festivités, les habitants affluent de toutes parts vers Haojing, jadis Capitale de Huaxu. Mets saisonniers, décors cérémoniels, rites solennels... tout s’y prépare dès à présent.",
            ["DialogueId"] = 12040202,
            ["GUID"] = "1E2431A4",
            ["NextDialogue"] = 12040203,
            ["RelatedWikiId"] = {
                [1] = 408016,
                },
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120402/1E2431A4",
            },
        }
  end },
  { MinKey = 12040203, MaxKey = 12041806, Loader = function()
      return {
        [12040203] = {
            ["Content"] = "哇！那个什么限定美食听起来好有意思，止流姐姐能不能展开来讲讲？",
            ["ContentFR"] = "Ouaaah ! Des spécialités exclusives ?! Ça a l’air génial ! Zhiliu, raconte encore !",
            ["DialogueId"] = 12040203,
            ["GUID"] = "1E2431CE",
            ["NextDialogue"] = 12040204,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120402/1E2431CE",
            },
        [12040204] = {
            ["Content"] = "嗯，就比如说城东的八珍楼，在奉香大典前后会出售一种独特的香糕。因其用到了一种极难采集的花蕊，一天只供应十笼。",
            ["ContentFR"] = "Par exemple, à l’est de la ville, le Pavillon des Huit Trésors vend une pâtisserie aromatique exclusive durant la Cérémonie. Elle contient les étamines d’une fleur extrêmement rare — si bien que seuls dix paniers sont proposés chaque jour.",
            ["DialogueId"] = 12040204,
            ["GUID"] = "1E2431F8",
            ["NextDialogue"] = 12040205,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120402/1E2431F8",
            },
        [12040205] = {
            ["Content"] = "香糕一旦掀笼，香气四溢，使人没齿难忘。因此，每日排队的人络绎不绝，被吸引来的路人在店铺旁久久徘徊不去，也是城中一景呢。",
            ["ContentFR"] = "Dès que l’on soulève le couvercle du panier vapeur, son parfum se répand à des rues à la ronde. Une saveur que l’on n’oublie jamais. Les files d’attente commencent à l’aube, et les passants s’attardent longuement devant l’échoppe. C’est devenu l’un des spectacles emblématiques de la ville.",
            ["DialogueId"] = 12040205,
            ["GUID"] = "1E243222",
            ["NextDialogue"] = 12040206,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120402/1E243222",
            },
        [12040206] = {
            ["Content"] = "什么，要排队吗？！那我们走快点——",
            ["ContentFR"] = "Quoi ?! Il faut faire la queue ?! Alors on se dépêche !",
            ["DialogueId"] = 12040206,
            ["GUID"] = "1E24324C",
            ["NextDialogue"] = 12040207,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120402/1E24324C",
            },
        [12040207] = {
            ["Content"] = "{nickname}，你今天怎么走得这么慢？赶紧跟上来啦！",
            ["ContentFR"] = "{nickname}, pourquoi tu traînes comme ça aujourd’hui ? Allez, dépêche-toi !",
            ["DialogueId"] = 12040207,
            ["GUID"] = "1E243276",
            ["NextDialogue"] = 12040208,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120402/1E243276",
            },
        [12040208] = {
            ["Content"] = "…………",
            ["ContentFR"] = "...",
            ["DialogueId"] = 12040208,
            ["GUID"] = "1E2432A0",
            ["NextDialogue"] = 12040209,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120402/1E2432A0",
            },
        [12040209] = {
            ["Content"] = "小仆从，你还好吗？你的脸色看起来好苍白……",
            ["ContentFR"] = "Petit larbin... ça va ? T’as l’air super pâle...",
            ["DialogueId"] = 12040209,
            ["GUID"] = "1E2432CA",
            ["NextOptions"] = {
                [1] = 12040210,
                [2] = 12040211,
                },
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120402/1E2432CA",
            },
        [12040210] = {
            ["Content"] = "这里是哪……？",
            ["ContentFR"] = "<I>Où sommes-nous... ?</>",
            ["DialogueId"] = 12040210,
            ["GUID"] = "1E2432F4",
            ["NextDialogue"] = 12040212,
            },
        [12040211] = {
            ["Content"] = "我们怎么在这里……？",
            ["ContentFR"] = "<I>Comment sommes-nous arrivés ici... ?</>",
            ["DialogueId"] = 12040211,
            ["GUID"] = "1E24331E",
            ["NextDialogue"] = 12040212,
            },
        [12040212] = {
            ["Content"] = "诶诶诶——你可别吓我啊！",
            ["ContentFR"] = "Hein ?! H-Hé ! Ne me fais pas peur comme ça !",
            ["DialogueId"] = 12040212,
            ["GUID"] = "1E243348",
            ["NextDialogue"] = 12040213,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120402/1E243348",
            },
        [12040213] = {
            ["Content"] = "小仆从，你还能记起来多少东西？我们一起并肩作战打坏人的珍贵经历，白罩着你的那些日子，统统不记得了吗？！",
            ["ContentFR"] = "Petit larbin, tu te rappelles de quoi ? Nos combats héroïques côte à côte ? Les jours glorieux où l’incroyable Roi Démon veillait sur toi ?! Ne me dis pas que tu as tout oublié... ?!",
            ["DialogueId"] = 12040213,
            ["GUID"] = "1E243372",
            ["NextDialogue"] = 12040214,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120402/1E243372",
            },
        [12040214] = {
            ["Content"] = "完、完蛋了，这下该怎么办……一定是在开玩笑吧！白可不想失去小仆从这个朋友，呜呜……",
            ["ContentFR"] = "C-c’est pas possible... qu’est-ce qu’on va faire... Tu plaisantes, hein ?! Je ne veux pas perdre mon petit larbin... tu es mon {性别:ami le plus précieux|amie la plus précieuse}... <I>ouin...</>",
            ["DialogueId"] = 12040214,
            ["GUID"] = "1E24339C",
            ["NextOptions"] = {
                [1] = 12040215,
                [2] = 12040216,
                },
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120402/1E24339C",
            },
        [12040215] = {
            ["Content"] = "（捉弄白。）",
            ["ContentFR"] = "<I>Taquiner Snow</>",
            ["DialogueId"] = 12040215,
            ["GUID"] = "1E2433C6",
            ["ImprPlusId"] = 1205,
            ["NextDialogue"] = 12040217,
            },
        [12040216] = {
            ["Content"] = "（安慰白。）",
            ["ContentFR"] = "<I>Rassurer Snow</>",
            ["DialogueId"] = 12040216,
            ["GUID"] = "1E2433F0",
            ["ImprPlusId"] = 1204,
            ["NextDialogue"] = 12040222,
            },
        [12040217] = {
            ["Content"] = "是啊，都忘了。包括你说要罩着我，结果躲在我身后瑟瑟发抖的那件事，都忘得一干二净了。",
            ["ContentFR"] = "Oui, tout effacé. Même la fois où tu as juré me protéger... avant de te cacher derrière moi en tremblant comme une feuille. Disparu. Plus rien.",
            ["DialogueId"] = 12040217,
            ["GUID"] = "1E24341A",
            ["NextDialogue"] = 12040218,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120402/1E24341A",
            },
        [12040218] = {
            ["Content"] = "什么嘛！这不是该有不该有的记忆，统统都在嘛！",
            ["ContentFR"] = "Quoi ?! Ce n’est pas de l’amnésie, ça ! Tu te rappelles absolument tout !",
            ["DialogueId"] = 12040218,
            ["GUID"] = "1E243444",
            ["NextDialogue"] = 12040219,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120402/1E243444",
            },
        [12040219] = {
            ["Content"] = "小仆从整天就知道捉弄我，魔王大人也是有脾气的！",
            ["ContentFR"] = "Petit larbin insolent ! Le Roi Démon de la Lumière a aussi son caractère !",
            ["DialogueId"] = 12040219,
            ["GUID"] = "1E24346E",
            ["NextDialogue"] = 12040220,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120402/1E24346E",
            },
        [12040220] = {
            ["Content"] = "好啦好啦，白，听我说。",
            ["ContentFR"] = "Bon, bon... Snow, écoute-moi.",
            ["DialogueId"] = 12040220,
            ["GUID"] = "1E243498",
            ["NextDialogue"] = 12040221,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120402/1E243498",
            },
        [12040221] = {
            ["Content"] = "我记得你、记得止流掌柜，记得我们在冰湖城的日子，也记得我们一起来华胥的原因。",
            ["ContentFR"] = "Je me souviens de toi. Je me souviens de la Patronne Zhiliu. De nos jours à Givrelac. Et de la raison qui nous a conduits à Huaxu.",
            ["DialogueId"] = 12040221,
            ["GUID"] = "1E2434C2",
            ["NextDialogue"] = 12040223,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120402/1E2434C2",
            },
        [12040222] = {
            ["Content"] = "……白，别慌。",
            ["ContentFR"] = "... Snow, calme-toi.",
            ["DialogueId"] = 12040222,
            ["GUID"] = "1E2434EC",
            ["NextDialogue"] = 12040221,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120402/1E2434EC",
            },
        [12040223] = {
            ["Content"] = "只是印象里……我们明明在赶去祭坛解决烛阴之灾的路上。再往后的事情，我再怎么努力去想也想不起来。",
            ["ContentFR"] = "Je me rappelle que nous étions en route vers l’Autel de Zhuyin, pour mettre fin au Fléau de Zhuyin. Mais après cela... j’ai beau essayer d’y repenser, tout devient flou.",
            ["DialogueId"] = 12040223,
            ["GUID"] = "1E243516",
            ["NextDialogue"] = 12040224,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120402/1E243516",
            },
        [12040224] = {
            ["Content"] = "呼……还好还好，忘的不多。",
            ["ContentFR"] = "<I>Ouf...</> tu n’as pas tout perdu, c’est déjà ça.",
            ["DialogueId"] = 12040224,
            ["GUID"] = "1E243540",
            ["NextDialogue"] = 12040225,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120402/1E243540",
            },
        [12040225] = {
            ["Content"] = "你刚刚提到烛阴？那条恶龙早就被我们打败啦，就在昨天！",
            ["ContentFR"] = "Zhuyin ? On l’a vaincu hier, ce dragon maléfique !",
            ["DialogueId"] = 12040225,
            ["GUID"] = "1E24356A",
            ["NextDialogue"] = 12040226,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120402/1E24356A",
            },
        [12040226] = {
            ["Content"] = "之后，百年春还开了场庆功宴，表彰我们是为民除害的大英雄呢。当然，报酬自然也是少不了我们的！",
            ["ContentFR"] = "Ensuite, Éternel Printemps a organisé un banquet en notre honneur ! Ils nous ont proclamés héros du peuple ! Et bien sûr, la récompense était à la hauteur !",
            ["DialogueId"] = 12040226,
            ["GUID"] = "1E243594",
            ["NextDialogue"] = 12040227,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120402/1E243594",
            },
        [12040227] = {
            ["Content"] = "回冰湖城的飞艇还有几天才出发。闲着也是闲着，我干脆让止流姐姐带我们来附近的大城市逛逛——最近华胥在准备过节哦！",
            ["ContentFR"] = "Le dirigeable pour Givrelac ne part que dans quelques jours. Alors je me suis dit : autant demander à Zhiliu de nous faire visiter Haojing ! Huaxu est en plein préparatifs !",
            ["DialogueId"] = 12040227,
            ["GUID"] = "1E2435BE",
            ["NextDialogue"] = 12040228,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120402/1E2435BE",
            },
        [12040228] = {
            ["Content"] = "你还记得吗，这座城市叫皓京，是华胥曾经的首都，比烟津渡热闹多啦！",
            ["ContentFR"] = "Tu te rappelles ? Haojing était autrefois la capitale ! C’est bien plus animé que le Port-des-Brumes !",
            ["DialogueId"] = 12040228,
            ["GUID"] = "1E2435E8",
            ["NextDialogue"] = 12040229,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120402/1E2435E8",
            },
        [12040229] = {
            ["Content"] = "我们才刚刚坐小船到这儿，还没有开始玩呢，结果就发现你看起来好像不太舒服。",
            ["ContentFR"] = "On venait juste d’accoster en barque quand tu as commencé à te sentir mal...",
            ["DialogueId"] = 12040229,
            ["GUID"] = "1E243612",
            ["NextDialogue"] = 12040230,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120402/1E243612",
            },
        [12040230] = {
            ["Content"] = "怎么样，小仆从。我这样说，有没有让你回忆起来一点点？",
            ["ContentFR"] = "Alors ? Ça te revient un peu ?",
            ["DialogueId"] = 12040230,
            ["FinalDialogueId"] = 12040243,
            ["GUID"] = "1E24363C",
            ["NextOptions"] = {
                [1] = 12040231,
                [2] = 12040232,
                },
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120402/1E24363C",
            },
        [12040231] = {
            ["Content"] = "试图否认。",
            ["ContentFR"] = "<I>Pas vraiment.</>",
            ["DialogueId"] = 12040231,
            ["GUID"] = "1E243666",
            ["NextDialogue"] = 12040238,
            },
        [12040232] = {
            ["Content"] = "好像是这样……",
            ["ContentFR"] = "Oui... sans doute...",
            ["DialogueId"] = 12040232,
            ["GUID"] = "1E243690",
            ["NextDialogue"] = 12040243,
            },
        [12040238] = {
            ["Content"] = "（一种异样的陌生感冲刷着你的神经。哪里不对劲——你的内心有一个细小的声音如此呐喊着。）",
            ["ContentFR"] = "Une impression d’étrangeté vous submerge — comme si vos souvenirs eux-mêmes ne vous appartenaient plus. Quelque chose ne va pas. Au fond de votre esprit, une voix infime hurle en silence.",
            ["DialogueId"] = 12040238,
            ["GUID"] = "1E24378C",
            ["NextDialogue"] = 12040239,
            ["SpeakNpcId"] = 0,
            ["VoiceName"] = "voice/$Locale$/story/1204/120402/1E24378C",
            },
        [12040239] = {
            ["Content"] = "（烛阴果真被打败了吗？在烛阴祭坛上，是否还发生了什么？造成了某种让你惊愕，不可置信，并且不应忘记的危机？）",
            ["ContentFR"] = "Zhuyin a-t-il vraiment été vaincu ? À l’Autel de Zhuyin... ne s’est-il rien produit d’autre ? Quelque chose de terrible. D’inacceptable. Quelque chose que vous n’auriez jamais dû oublier.",
            ["DialogueId"] = 12040239,
            ["GUID"] = "1E2437B6",
            ["NextDialogue"] = 12040240,
            ["SpeakNpcId"] = 0,
            ["VoiceName"] = "voice/$Locale$/story/1204/120402/1E2437B6",
            },
        [12040240] = {
            ["Content"] = "（你试图回想起什么。几乎在一瞬间，钻心的疼痛刺痛了你的脑海。你在冰冷的战栗中忘记了如何思考。）",
            ["ContentFR"] = "Vous tentez de forcer le souvenir. Une douleur fulgurante vous transperce le crâne. Le froid vous envahit.",
            ["DialogueId"] = 12040240,
            ["GUID"] = "1E2437E0",
            ["NextDialogue"] = 12040241,
            ["SpeakNpcId"] = 0,
            ["VoiceName"] = "voice/$Locale$/story/1204/120402/1E2437E0",
            },
        [12040241] = {
            ["Content"] = "…………头、好疼……",
            ["ContentFR"] = "... Ma tête... ça me lance...",
            ["DialogueId"] = 12040241,
            ["GUID"] = "1E24380A",
            ["NextDialogue"] = 12040242,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120402/1E24380A",
            },
        [12040242] = {
            ["Content"] = "呜，小仆从，你的脸色看起来真的好差。",
            ["ContentFR"] = "Oh non... tu as vraiment mauvaise mine.",
            ["DialogueId"] = 12040242,
            ["GUID"] = "1E243834",
            ["NextDialogue"] = 12040230,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120402/1E243834",
            },
        [12040243] = {
            ["Content"] = "（你的记忆逐渐复苏……似乎确实如白所说，你们去了庆功宴，然后坐船来到这里……但这些记忆好像又朦朦胧胧隔着一层雾，看不真切。）",
            ["ContentFR"] = "Vos souvenirs se recomposent lentement. Le banquet. La traversée en bateau. Haojing. Tout correspond aux paroles de Snow... Mais ces images semblent voilées d’une brume étrangère, comme un rêve emprunté.",
            ["DialogueId"] = 12040243,
            ["GUID"] = "1E24385E",
            ["NextDialogue"] = 12040244,
            ["VoiceName"] = "voice/$Locale$/story/1204/120402/1E24385E",
            },
        [12040244] = {
            ["Content"] = "……啊！我想起来了，之前和那条坏龙打架的时候，掉了好多好多碎石块。",
            ["ContentFR"] = "Ah ! Je me souviens ! Quand on affrontait ce sale dragon, des tonnes de débris sont tombées !",
            ["DialogueId"] = 12040244,
            ["GUID"] = "1E243888",
            ["NextDialogue"] = 12040245,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120402/1E243888",
            },
        [12040245] = {
            ["Content"] = "会不会小仆从的脑袋在那时候不小心被石块击中了，才落下了后遗症……止流姐姐，你有什么解决办法吗？",
            ["ContentFR"] = "Peut-être qu’une pierre t’a touché la tête à ce moment-là ? Zhiliu, tu en penses quoi ?",
            ["DialogueId"] = 12040245,
            ["GUID"] = "1E2438B2",
            ["NextDialogue"] = 12040246,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120402/1E2438B2",
            },
        [12040246] = {
            ["Content"] = "嗯……确有这种可能。",
            ["ContentFR"] = "Hm... c’est en effet plausible.",
            ["DialogueId"] = 12040246,
            ["GUID"] = "1E2438DC",
            ["NextDialogue"] = 12040247,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120402/1E2438DC",
            },
        [12040247] = {
            ["Content"] = "抱歉，是我疏忽了。没有及时察觉到{nickname}身体抱恙，实在是东道主的失责。",
            ["ContentFR"] = "Je vous prie de m’excuser. Ne pas avoir remarqué plus tôt l’état de {nickname} est une faute indigne d’un hôte.",
            ["DialogueId"] = 12040247,
            ["GUID"] = "1E243906",
            ["NextDialogue"] = 12040248,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120402/1E243906",
            },
        [12040248] = {
            ["Content"] = "前方不远就是皓京近些年声名鹊起的药堂，泽生阁。其门专精药学，虽不如祝由扶氏那样手到病除，几如神迹，但常见的病痛都能及时治疗。",
            ["ContentFR"] = "Un peu plus loin se trouve la Pharmacie Zesheng, une officine récemment renommée à Haojing. Ils n’accomplissent pas les prodiges presque divins de la Maison Zhuyou, mais leurs remèdes sont fiables.",
            ["DialogueId"] = 12040248,
            ["GUID"] = "1E243930",
            ["NextDialogue"] = 12040249,
            ["RelatedWikiId"] = {
                [1] = 406006,
                },
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120402/1E243930",
            },
        [12040249] = {
            ["Content"] = "经年累月下来，在民众之间积累了不错的口碑。",
            ["ContentFR"] = "Au fil des années, ils ont acquis une solide réputation auprès des habitants.",
            ["DialogueId"] = 12040249,
            ["GUID"] = "1E24395A",
            ["NextDialogue"] = 12040250,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120402/1E24395A",
            },
        [12040250] = {
            ["Content"] = "我们可以去那里抓些药材，煎一味提神醒脑的汤药，看看能否好转。若是效果不佳，我们就立刻打道回府，不要耽误了{nickname}的病情。",
            ["ContentFR"] = "Nous pourrions y acheter quelques herbes et préparer une décoction destinée à éclaircir l’esprit. Si cela ne suffit pas, nous rentrerons sans tarder. Inutile de laisser ton état s’aggraver.",
            ["DialogueId"] = 12040250,
            ["GUID"] = "1E243984",
            ["NextDialogue"] = 12040251,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120402/1E243984",
            },
        [12040251] = {
            ["Content"] = "好，就按止流姐姐说的！那我们赶紧过去吧！",
            ["ContentFR"] = "Oui ! On fait comme ça !",
            ["DialogueId"] = 12040251,
            ["GUID"] = "1E2439AE",
            ["NextDialogue"] = 12040252,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120402/1E2439AE",
            },
        [12040252] = {
            ["Content"] = "小仆从，你慢慢走。不用着急，我就跟在你身后，看着你的状态。",
            ["ContentFR"] = "Petit larbin, marche doucement. Je reste juste derrière toi pour surveiller ton état.",
            ["DialogueId"] = 12040252,
            ["GUID"] = "1E2439D8",
            ["NextDialogue"] = 12040253,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120402/1E2439D8",
            },
        [12040253] = {
            ["Content"] = "要是你身体没有好起来，我也没心思玩。还是你比较重要，要是不行我们就先回去休息！",
            ["ContentFR"] = "Si tu ne vas pas mieux, je n’aurai aucune envie de m’amuser. Tu comptes plus que tout le reste. Et si ça ne va pas, on rentrera se reposer !",
            ["DialogueId"] = 12040253,
            ["GUID"] = "1E243A02",
            ["NextDialogue"] = 12040254,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120402/1E243A02",
            },
        [12040254] = {
            ["Content"] = "……嗯，我应该没什么大碍。我们走吧。",
            ["ContentFR"] = "... Oui. Je pense que ça ira. Allons-y.",
            ["DialogueId"] = 12040254,
            ["GUID"] = "1E243A2C",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120402/1E243A2C",
            },
        [12040301] = {
            ["Content"] = "竟、竟然有这么多人……这就是过节吗？",
            ["ContentFR"] = "I-Il y a autant de monde que ça... C’est donc ça, une fête à Huaxu ?",
            ["DialogueId"] = 12040301,
            ["GUID"] = "1E2441E2",
            ["NextDialogue"] = 12040302,
            ["RelatedWikiId"] = {
                [1] = 408010,
                [2] = 408016,
                [3] = 203001,
                [4] = 405014,
                [5] = 406006,
                },
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120403/1E2441E2",
            },
        [12040302] = {
            ["Content"] = "诶……那里！能休息的座位竟然只剩一个了！",
            ["ContentFR"] = "Ah... là-bas ! Il ne reste plus qu’une seule place assise !",
            ["DialogueId"] = 12040302,
            ["GUID"] = "1E24420C",
            ["NextDialogue"] = 12040303,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120403/1E24420C",
            },
        [12040303] = {
            ["Content"] = "小仆从，你赶紧过去占着位置，坐下先好好休息。我和止流姐姐去买药……",
            ["ContentFR"] = "Petit larbin, va vite t’installer et repose-toi un peu. Zhiliu et moi irons acheter les remèdes—",
            ["DialogueId"] = 12040303,
            ["GUID"] = "1E244236",
            ["NextDialogue"] = 12040304,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120403/1E244236",
            },
        [12040304] = {
            ["Content"] = "白，我去买药吧。",
            ["ContentFR"] = "Snow, laisse-moi y aller.",
            ["DialogueId"] = 12040304,
            ["GUID"] = "1E244260",
            ["NextDialogue"] = 12040305,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120403/1E244260",
            },
        [12040305] = {
            ["Content"] = "哎？小仆从，你身体不舒服，这种时候不应该到处乱跑吧？",
            ["ContentFR"] = "Hein ? Mais tu ne te sens pas bien... Ce n’est pas le moment d’aller courir partout, si ?",
            ["DialogueId"] = 12040305,
            ["GUID"] = "1E24428A",
            ["NextDialogue"] = 12040306,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120403/1E24428A",
            },
        [12040306] = {
            ["Content"] = "没事的，我感觉已经好一些了。走一走反而对身体有好处，你就放一万个心吧。",
            ["ContentFR"] = "Ce n’est rien. Je me sens déjà mieux. Marcher un peu me fera du bien, tu peux me croire.",
            ["DialogueId"] = 12040306,
            ["GUID"] = "1E2442B4",
            ["NextDialogue"] = 12040307,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120403/1E2442B4",
            },
        [12040307] = {
            ["Content"] = "嗯……你可别逞强哦。那你们速去速回，白就在那里等着你们。",
            ["ContentFR"] = "Hmm... Ne te force pas, d’accord ? Bon, très bien. Ne traînez pas trop, je vous attends là-bas.",
            ["DialogueId"] = 12040307,
            ["GUID"] = "1E2442DE",
            ["NextDialogue"] = 12040308,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120403/1E2442DE",
            },
        [12040308] = {
            ["Content"] = "跟我来，{nickname}。泽生阁就在前方。",
            ["ContentFR"] = "Suis-moi, {nickname}. La Pharmacie Zesheng se trouve un peu plus loin.",
            ["DialogueId"] = 12040308,
            ["GUID"] = "1E244308",
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120403/1E244308",
            },
        [12040401] = {
            ["Content"] = "两位客官安康。今日是来抓什么药的？",
            ["ContentFR"] = "Mes salutations, honorables clients. Quelle ordonnance souhaitez-vous aujourd’hui ?",
            ["DialogueId"] = 12040401,
            ["GUID"] = "1E24524A",
            ["NextDialogue"] = 12040402,
            ["RelatedWikiId"] = {
                [1] = 408010,
                [2] = 408016,
                [3] = 203001,
                [4] = 405014,
                [5] = 406006,
                },
            ["SpeakNpcId"] = 240003,
            ["VoiceName"] = "voice/$Locale$/story/1204/120404/1E24524A",
            },
        [12040402] = {
            ["Content"] = "劳烦您抓一剂川息茶，一剂辟秽正气散，再添四钱凉络根作为佐剂……",
            ["ContentFR"] = "Je vous serais reconnaissante de préparer une dose de Thé Chuanxi, une dose de Poudre de Rectitude Purificatrice... et d’y ajouter quatre qian de Racine de Liangluo en adjuvant.",
            ["DialogueId"] = 12040402,
            ["GUID"] = "1E245274",
            ["NextOptions"] = {
                [1] = 12040403,
                [2] = 12040404,
                },
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120404/1E245274",
            },
        [12040403] = {
            ["Content"] = "听他们交谈。",
            ["ContentFR"] = "<I>Écouter leur échange</>",
            ["DialogueId"] = 12040403,
            ["GUID"] = "1E24529E",
            ["NextDialogue"] = 12040405,
            },
        [12040404] = {
            ["Content"] = "打断止流，描述自己的症状。",
            ["ContentFR"] = "<I>Interrompre Zhiliu et décrire vos symptômes</>",
            ["DialogueId"] = 12040404,
            ["GUID"] = "1E2452C8",
            ["NextDialogue"] = 12040409,
            },
        [12040405] = {
            ["Content"] = "听这药方，您的家人或朋友是否有些头疼、体虚，甚至神志恍惚的毛病？",
            ["ContentFR"] = "À en juger par cette ordonnance... votre proche souffrirait-il de céphalées, d’une certaine faiblesse, peut-être même d’une légère confusion mentale ?",
            ["DialogueId"] = 12040405,
            ["GUID"] = "1E2452F2",
            ["NextDialogue"] = 12040406,
            ["SpeakNpcId"] = 240003,
            ["VoiceName"] = "voice/$Locale$/story/1204/120404/1E2452F2",
            },
        [12040406] = {
            ["Content"] = "呵呵……不愧是泽生阁，果真名不虚传。",
            ["ContentFR"] = "Héhé... La Pharmacie Zesheng n’a donc pas volé sa réputation.",
            ["DialogueId"] = 12040406,
            ["GUID"] = "1E24531C",
            ["NextDialogue"] = 12040407,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120404/1E24531C",
            },
        [12040407] = {
            ["Content"] = "客官过奖。瞧您这方子，在药理上倒是颇有几分造诣。是谁身体不舒服，您身边这位{性别：小兄弟|姑娘}吗？",
            ["ContentFR"] = "Vous me flattez. Votre prescription témoigne d’une connaissance solide des principes médicinaux. Serait-ce {性别:ce jeune homme|cette jeune demoiselle} qui se trouve à vos côtés ?",
            ["DialogueId"] = 12040407,
            ["GUID"] = "1E245346",
            ["NextDialogue"] = 12040408,
            ["SpeakNpcId"] = 240003,
            ["VoiceName"] = "voice/$Locale$/story/1204/120404/1E245346",
            },
        [12040408] = {
            ["Content"] = "嗯，我从早上开始就有点不太舒服，头一直隐隐作痛。",
            ["ContentFR"] = "Oui. Depuis ce matin, j’ai une douleur sourde à la tête... et elle ne me quitte pas.",
            ["DialogueId"] = 12040408,
            ["GUID"] = "1E245370",
            ["NextDialogue"] = 12040411,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120404/1E245370",
            },
        [12040409] = {
            ["Content"] = "您好。我今天有点头疼，而且好像有点健忘，老是想不起最近发生的事情。",
            ["ContentFR"] = "Bonjour. J’ai mal à la tête depuis ce matin... et je me sens un peu {性别:confus|confuse}. J’ai du mal à me souvenir des événements récents.",
            ["DialogueId"] = 12040409,
            ["GUID"] = "1E24539A",
            ["NextDialogue"] = 12040410,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120404/1E24539A",
            },
        [12040410] = {
            ["Content"] = "刚才这位客官所报的药方恰好对症，在药理上倒是颇有几分造诣。",
            ["ContentFR"] = "L’ordonnance que votre compagne a demandée correspond effectivement à ces symptômes. Elle a été formulée avec discernement.",
            ["DialogueId"] = 12040410,
            ["GUID"] = "1E2453C4",
            ["NextDialogue"] = 12040411,
            ["SpeakNpcId"] = 240003,
            ["VoiceName"] = "voice/$Locale$/story/1204/120404/1E2453C4",
            },
        [12040411] = {
            ["Content"] = "观您气色，虽有些虚汗神浮，但总体并无大碍。在刚刚的药方基础上，再加一钱茯神，服下后应当就能好转。",
            ["ContentFR"] = "Votre teint révèle une légère transpiration et un esprit quelque peu flottant, mais rien d’inquiétant. Je vais y ajouter un qian de Fushen. Une fois la décoction absorbée, votre esprit devrait s’éclaircir.",
            ["DialogueId"] = 12040411,
            ["GUID"] = "1E2453EE",
            ["NextDialogue"] = 12040412,
            ["SpeakNpcId"] = 240003,
            ["VoiceName"] = "voice/$Locale$/story/1204/120404/1E2453EE",
            },
        [12040412] = {
            ["Content"] = "那就多谢你了。",
            ["ContentFR"] = "Je vous remercie.",
            ["DialogueId"] = 12040412,
            ["GUID"] = "1E245418",
            ["NextDialogue"] = 12040413,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120404/1E245418",
            },
        [12040413] = {
            ["Content"] = "(你们在原地等待了一会儿，热腾腾的汤药被药师煎好，送到了你手上。棕黑色的液体散发出不容忽视的苦味。)",
            ["ContentFR"] = "Vous attendez un moment. La décoction, encore fumante, vous est remise. Le liquide brun sombre dégage une amertume difficile à ignorer.",
            ["DialogueId"] = 12040413,
            ["GUID"] = "1E245442",
            ["NextDialogue"] = 12040414,
            ["SpeakNpcId"] = 0,
            ["VoiceName"] = "voice/$Locale$/story/1204/120404/1E245442",
            },
        [12040414] = {
            ["Content"] = "{nickname}，汤药烫手，好拿吗？",
            ["ContentFR"] = "{nickname}, c’est brûlant. Peux-tu le tenir sans te brûler ?",
            ["DialogueId"] = 12040414,
            ["GUID"] = "1E24546C",
            ["NextDialogue"] = 12040415,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120404/1E24546C",
            },
        [12040415] = {
            ["Content"] = "嗯，没问题。",
            ["ContentFR"] = "Oui, ça ira.",
            ["DialogueId"] = 12040415,
            ["GUID"] = "1E245496",
            ["NextDialogue"] = 12040416,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120404/1E245496",
            },
        [12040416] = {
            ["Content"] = "走，去坐下，吹凉了再慢慢喝吧。",
            ["ContentFR"] = "Allons nous asseoir. Laisse-le tiédir avant de le boire.",
            ["DialogueId"] = 12040416,
            ["GUID"] = "1E2454C0",
            ["NextDialogue"] = 12040417,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120404/1E2454C0",
            },
        [12040417] = {
            ["Content"] = "（止流掌柜的药方确实是用来治头疼的。她的言行与往常一样，没有异样……）",
            ["ContentFR"] = "<I>La prescription de la Patronne Zhiliu correspond bien à mes symptômes. Son attitude est la même que d’habitude... rien d’anormal.</>",
            ["DialogueId"] = 12040417,
            ["GUID"] = "1E2454EA",
            ["NextDialogue"] = 12040418,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120404/1E2454EA",
            },
        [12040418] = {
            ["Content"] = "（奇怪，我今天怎么好像有些疑心病？是我多想了吗……？）",
            ["ContentFR"] = "<I>Étrange... Pourquoi cette méfiance aujourd’hui ? Est-ce moi qui me fais des idées... ?</>",
            ["DialogueId"] = 12040418,
            ["GUID"] = "1E245514",
            ["NextDialogue"] = 12040419,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120404/1E245514",
            },
        [12040419] = {
            ["Content"] = "（可能最近连续奔波，有些累到了……还是赶紧回去找白吧。）",
            ["ContentFR"] = "<I>Ces derniers jours ont dû m’épuiser... Retournons auprès de Snow.</>",
            ["DialogueId"] = 12040419,
            ["GUID"] = "1E24553E",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120404/1E24553E",
            },
        [12040501] = {
            ["Content"] = "哇，小仆从，看你喝了药，脸都皱成一团了。听说东方的药剂很苦，真有这么夸张吗？",
            ["ContentFR"] = "Ouah... regarde-moi cette grimace ! On dirait que c’est affreusement amer. Les remèdes de l’Est sont vraiment aussi amers ?",
            ["DialogueId"] = 12040501,
            ["GUID"] = "1E2462B2",
            ["NextOptions"] = {
                [1] = 12040502,
                [2] = 12040503,
                },
            ["RelatedWikiId"] = {
                [1] = 408010,
                [2] = 408016,
                [3] = 203001,
                [4] = 405014,
                [5] = 406006,
                },
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120405/1E2462B2",
            },
        [12040502] = {
            ["Content"] = "不苦，甜的，很好喝，你要不要来试试？",
            ["ContentFR"] = "<I>Pas du tout. C’est sucré. Tu veux goûter ?</>",
            ["DialogueId"] = 12040502,
            ["GUID"] = "1E2462DC",
            ["ImprPlusId"] = 1205,
            ["NextDialogue"] = 12040504,
            },
        [12040503] = {
            ["Content"] = "确实很苦，是尝过之后就很难忘记的味道……",
            ["ContentFR"] = "<I>Oui... C’est d’une amertume mémorable.</>",
            ["DialogueId"] = 12040503,
            ["GUID"] = "1E246306",
            ["ImprPlusId"] = 1202,
            ["NextDialogue"] = 12040505,
            },
        [12040504] = {
            ["Content"] = "还、还是算了吧……",
            ["ContentFR"] = "E-euh... je crois que je vais m’abstenir...",
            ["DialogueId"] = 12040504,
            ["GUID"] = "1E246330",
            ["NextDialogue"] = 12040505,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120405/1E246330",
            },
        [12040505] = {
            ["Content"] = "那，小仆从，你现在感觉怎么样了，有好一点吗？",
            ["ContentFR"] = "Alors ? Tu te sens mieux ?",
            ["DialogueId"] = 12040505,
            ["GUID"] = "1E24635A",
            ["NextDialogue"] = 12040506,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120405/1E24635A",
            },
        [12040506] = {
            ["Content"] = "嗯，头已经不疼了。大概只是昨晚没睡好吧。",
            ["ContentFR"] = "Oui. La douleur a disparu. J’ai sans doute simplement mal dormi.",
            ["DialogueId"] = 12040506,
            ["GUID"] = "1E246384",
            ["NextDialogue"] = 12040507,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120405/1E246384",
            },
        [12040507] = {
            ["Content"] = "那就好！我待会儿再去给你买点那个节庆限定的香糕，多吃点甜甜的东西，嘴里就不会苦了。",
            ["ContentFR"] = "Tant mieux ! Je t’achèterai un peu de ces pâtisseries aromatiques exclusives à la fête. Avec quelque chose de sucré, l’amertume passera plus vite.",
            ["DialogueId"] = 12040507,
            ["GUID"] = "1E2463AE",
            ["NextDialogue"] = 12040508,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120405/1E2463AE",
            },
        [12040508] = {
            ["Content"] = "今天你怎么对我这么好？我都有点意外了。",
            ["ContentFR"] = "Depuis quand es-tu si attentionnée ? Cela m’étonne presque.",
            ["DialogueId"] = 12040508,
            ["GUID"] = "1E2463D8",
            ["NextDialogue"] = 12040509,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120405/1E2463D8",
            },
        [12040509] = {
            ["Content"] = "哼哼，毕竟白是体贴下属的好魔王嘛！来，我们继续在这里休息一会儿，今天不赶时间，不着急。",
            ["ContentFR"] = "<I>Hmpf !</> Le Roi Démon sait se montrer magnanime envers ses fidèles serviteurs ! Restons encore un peu ici. Rien ne presse aujourd’hui.",
            ["DialogueId"] = 12040509,
            ["GUID"] = "1E246402",
            ["NextDialogue"] = 12040510,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120405/1E246402",
            },
        [12040510] = {
            ["Content"] = "你们坐在原地休息。过了一会儿，档口旁突然传来了兴高采烈的喧哗声。",
            ["ContentFR"] = "Vous restez assis à vous reposer. Au bout d’un moment, des exclamations enthousiastes s’élèvent d’un étal voisin.",
            ["DialogueId"] = 12040510,
            ["GUID"] = "1E24642C",
            ["NextDialogue"] = 12040511,
            ["SpeakNpcId"] = 0,
            ["VoiceName"] = "voice/$Locale$/story/1204/120405/1E24642C",
            },
        [12040511] = {
            ["Content"] = "我听说<H>奉香群英试</>的获胜者，可以登上执律阁，一览绝景风光，甚至让白龙神君亲口回答一个问题呢！",
            ["ContentFR"] = "J’ai entendu dire que le vainqueur du <H>Tournoi de l’Encens</> peut accéder au Pavillon de l’Arbitrage et contempler un panorama incomparable ! On raconte même que le Seigneur Dragon d’Argent répond en personne à une question !",
            ["DialogueId"] = 12040511,
            ["GUID"] = "1E246456",
            ["NextDialogue"] = 12040512,
            ["RelatedWikiId"] = {
                [1] = 405015,
                },
            ["SpeakNpcId"] = 240010,
            ["VoiceName"] = "voice/$Locale$/story/1204/120405/1E246456",
            },
        [12040512] = {
            ["Content"] = "哎？那边好吵，他们都在聊些什么呀？",
            ["ContentFR"] = "Hein ? Ils parlent de quoi, là-bas ?",
            ["DialogueId"] = 12040512,
            ["GUID"] = "1E246480",
            ["NextDialogue"] = 12040513,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120405/1E246480",
            },
        [12040513] = {
            ["Content"] = "执律阁就是白龙神君下榻的神所吧！与神近距离面对面，到底是什么感觉呢……好想知道啊。",
            ["ContentFR"] = "Le Pavillon de l’Arbitrage est bien le sanctuaire où réside le Seigneur Dragon d’Argent, n’est-ce pas ? Quelle sensation cela doit être, de se tenir face à une divinité...",
            ["DialogueId"] = 12040513,
            ["GUID"] = "1E2464AA",
            ["NextDialogue"] = 12040514,
            ["RelatedWikiId"] = {
                [1] = 407009,
                },
            ["SpeakNpcId"] = 240010,
            ["VoiceName"] = "voice/$Locale$/story/1204/120405/1E2464AA",
            },
        [12040514] = {
            ["Content"] = "我舅舅的好友的姑奶奶，就说她曾经登上过执律阁顶，那风景叫一个终生难忘！",
            ["ContentFR"] = "La grand-tante de l’ami de mon oncle y serait montée une fois ! Elle affirme que la vue là-haut est inoubliable !",
            ["DialogueId"] = 12040514,
            ["GUID"] = "1E2464D4",
            ["NextDialogue"] = 12040515,
            ["SpeakNpcId"] = 240011,
            ["VoiceName"] = "voice/$Locale$/story/1204/120405/1E2464D4",
            },
        [12040515] = {
            ["Content"] = "有道是：凌霄悬阁镇云关，瞰尽千城暮色间。龙鳞映日金波转，万仞秋光赤玉山。",
            ["ContentFR"] = "« Suspendu aux cieux, le Pavillon domine les nuées, Il embrasse mille cités au crépuscule. Les écailles du Dragon luisent sous l’or du soleil, Parmi les cimes d’automne aux reflets de jade. »",
            ["DialogueId"] = 12040515,
            ["GUID"] = "1E2464FE",
            ["NextDialogue"] = 12040516,
            ["SpeakNpcId"] = 240012,
            ["VoiceName"] = "voice/$Locale$/story/1204/120405/1E2464FE",
            },
        [12040516] = {
            ["Content"] = "执律归来再无阁，若是能有幸造访一番，也算是此生无憾了……",
            ["ContentFR"] = "Après avoir contemplé le Pavillon de l’Arbitrage, plus aucun édifice ne saurait l’égaler... Y poser le pied ne serait-ce qu’une fois — et l’on pourrait quitter ce monde sans regret.",
            ["DialogueId"] = 12040516,
            ["GUID"] = "1E246528",
            ["NextDialogue"] = 12040517,
            ["SpeakNpcId"] = 240012,
            ["VoiceName"] = "voice/$Locale$/story/1204/120405/1E246528",
            },
        [12040517] = {
            ["Content"] = "止流姐姐，那个执律阁真有他们说的那么神奇吗？",
            ["ContentFR"] = "Zhiliu, ce Pavillon de l’Arbitrage est-il vraiment aussi incroyable ?",
            ["DialogueId"] = 12040517,
            ["GUID"] = "1E246552",
            ["NextDialogue"] = 12040518,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120405/1E246552",
            },
        [12040518] = {
            ["Content"] = "呵呵，道听途说，未免有夸大之词。不过执律阁横跨两岳之巅，凌驾云霄之上，纵览皓京，气象万千。对于初访皓京的人，倒确实值得一看。",
            ["ContentFR"] = "Héhé... Les rumeurs enjolivent toujours la réalité. Cependant, le Pavillon s’étend entre deux sommets, au-dessus des nuages, dominant toute Haojing. Pour qui découvre la ville pour la première fois, la vue mérite effectivement le détour.",
            ["DialogueId"] = 12040518,
            ["GUID"] = "1E24657C",
            ["NextDialogue"] = 12040519,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120405/1E24657C",
            },
        [12040519] = {
            ["Content"] = "只可惜，执律阁是白龙神君降旨的要地，寻常民众和游客非传召不得进入。",
            ["ContentFR"] = "Mais il s’agit d’un lieu décrété sacré par le Seigneur Dragon d’Argent. Sans convocation officielle, nul n’est autorisé à y pénétrer.",
            ["DialogueId"] = 12040519,
            ["GUID"] = "1E2465A6",
            ["NextDialogue"] = 12040520,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120405/1E2465A6",
            },
        [12040520] = {
            ["Content"] = "这样哦……",
            ["ContentFR"] = "Oh... je vois...",
            ["DialogueId"] = 12040520,
            ["GUID"] = "1E2465D0",
            ["NextDialogue"] = 12040521,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120405/1E2465D0",
            },
        [12040521] = {
            ["Content"] = "不过，你们若是当真感兴趣，我这里倒恰好有个委托。",
            ["ContentFR"] = "Cela dit, si vous êtes réellement curieux, il se trouve que j’ai justement une mission.",
            ["DialogueId"] = 12040521,
            ["GUID"] = "1E2465FA",
            ["NextDialogue"] = 12040522,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120405/1E2465FA",
            },
        [12040522] = {
            ["Content"] = "临近奉香大典，天禄司事务繁忙，正需要差人去各司取了仪式所用的种种器具，送上执律阁。",
            ["ContentFR"] = "À l’approche de la Cérémonie de l’Encens, le Bureau de la Fortune Céleste est débordé. Il faut récupérer divers instruments rituels auprès de plusieurs administrations et les acheminer jusqu’au Pavillon de l’Arbitrage.",
            ["DialogueId"] = 12040522,
            ["GUID"] = "1E246624",
            ["NextDialogue"] = 12040523,
            ["RelatedWikiId"] = {
                [1] = 407010,
                },
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120405/1E246624",
            },
        [12040523] = {
            ["Content"] = "你们不妨为我跑上一趟，沿途恰好能感受这里的节日氛围。怎么样，考虑一下？",
            ["ContentFR"] = "Vous pourriez vous en charger pour moi. Ce serait l’occasion de goûter à l’atmosphère festive en chemin. Qu’en dites-vous ?",
            ["DialogueId"] = 12040523,
            ["GUID"] = "1E24664E",
            ["NextDialogue"] = 12040524,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120405/1E24664E",
            },
        [12040524] = {
            ["Content"] = "哎？这不就是那什么，瞌睡了刚好有人递枕头嘛！啊不过……小仆从，我们去不去还是看你的想法。",
            ["ContentFR"] = "Eh ?! Ça tombe à pic ! Mais... Petit larbin, c’est à toi de décider.",
            ["DialogueId"] = 12040524,
            ["GUID"] = "1E246678",
            ["NextDialogue"] = 12040525,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120405/1E246678",
            },
        [12040525] = {
            ["Content"] = "难得来一次，你如果真那么感兴趣，去看看也行。",
            ["ContentFR"] = "Nous ne venons pas ici tous les jours. Si cela t’intéresse tant, allons voir.",
            ["DialogueId"] = 12040525,
            ["GUID"] = "1E2466A2",
            ["NextDialogue"] = 12040526,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120405/1E2466A2",
            },
        [12040526] = {
            ["Content"] = "哇，就知道小仆从对我最好了！那还等什么，我们赶紧走吧！",
            ["ContentFR"] = "Je savais que je pouvais compter sur toi ! Alors qu’est-ce qu’on attend ? Allons-y !",
            ["DialogueId"] = 12040526,
            ["GUID"] = "1E2466CC",
            ["NextDialogue"] = 12040527,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120405/1E2466CC",
            },
        [12040527] = {
            ["Content"] = "呵呵……天禄司就在桥对岸的西城区，你们陪我走上一趟吧，我好将信物交予你们。",
            ["ContentFR"] = "Héhé... Le Bureau de la Fortune Céleste se trouve de l’autre côté du pont, dans le Quartier Ouest. Accompagnez-moi, je vous remettrai le gage officiel.",
            ["DialogueId"] = 12040527,
            ["GUID"] = "1E2466F6",
            ["NextDialogue"] = 12040528,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120405/1E2466F6",
            },
        [12040528] = {
            ["Content"] = "咦，那几人是……？",
            ["ContentFR"] = "Hm... Ces personnes à l’instant... ?",
            ["DialogueId"] = 12040528,
            ["GUID"] = "1E246720",
            ["NextDialogue"] = 12040529,
            ["SpeakNpcId"] = 240002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120405/1E246720",
            },
        [12040529] = {
            ["Content"] = "扶疏阁下，怎么了？",
            ["ContentFR"] = "Dame Fushu ? Quelque chose vous préoccupe ?",
            ["DialogueId"] = 12040529,
            ["GUID"] = "1E24674A",
            ["NextDialogue"] = 12040530,
            ["SpeakNpcId"] = 240003,
            ["VoiceName"] = "voice/$Locale$/story/1204/120405/1E24674A",
            },
        [12040530] = {
            ["Content"] = "无妨，她们应当不会走在一起，许是我看错了。还是说回正事吧。",
            ["ContentFR"] = "Non... Elles ne devraient pas se trouver ensemble. J’ai dû me méprendre. Revenons à notre sujet.",
            ["DialogueId"] = 12040530,
            ["GUID"] = "1E246774",
            ["NextDialogue"] = 12040531,
            ["SpeakNpcId"] = 240002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120405/1E246774",
            },
        [12040531] = {
            ["Content"] = "抱歉，扶疏阁下。这回魂散的功效简直闻所未闻。恕我才疏学浅，可能没法帮上您的忙。",
            ["ContentFR"] = "Je vous prie de m’excuser, Dame Fushu. Les effets de cette Poudre de Rappel de l’Âme me sont inconnus. Je crains de ne pouvoir vous être d’une grande aide.",
            ["DialogueId"] = 12040531,
            ["GUID"] = "1E24679E",
            ["NextDialogue"] = 12040532,
            ["SpeakNpcId"] = 240003,
            ["VoiceName"] = "voice/$Locale$/story/1204/120405/1E24679E",
            },
        [12040532] = {
            ["Content"] = "容我多说一句……人死灯灭，生者还请节哀。但这倒行逆施之事，望您能慎重考虑。",
            ["ContentFR"] = "Permettez-moi toutefois une parole franche... La vie s’éteint comme une lampe. Je vous conjure de peser avec prudence toute tentative d’aller à l’encontre de cet ordre.",
            ["DialogueId"] = 12040532,
            ["GUID"] = "1E2467C8",
            ["NextDialogue"] = 12040533,
            ["SpeakNpcId"] = 240003,
            ["VoiceName"] = "voice/$Locale$/story/1204/120405/1E2467C8",
            },
        [12040533] = {
            ["Content"] = "嗯……我明白了，多谢。",
            ["ContentFR"] = "... Je comprends. Merci.",
            ["DialogueId"] = 12040533,
            ["GUID"] = "1E2467F2",
            ["SpeakNpcId"] = 240002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120405/1E2467F2",
            },
        [12040601] = {
            ["Content"] = "这里就是天禄司，分管华胥经济、贸易、赋税的部门。你们在这里稍等片刻。",
            ["ContentFR"] = "Voici le Bureau de la Fortune Céleste. Il supervise l’économie, le commerce et la fiscalité de Huaxu. Attendez-moi ici un instant.",
            ["DialogueId"] = 12040601,
            ["GUID"] = "1E24731A",
            ["NextDialogue"] = 12040602,
            ["RelatedWikiId"] = {
                [1] = 408010,
                [2] = 408016,
                [3] = 203001,
                [4] = 405014,
                [5] = 407010,
                },
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120406/1E24731A",
            },
        [12040602] = {
            ["Content"] = "一会儿之后，止流拿着信物和地图走了出来。",
            ["ContentFR"] = "Après quelques instants, Zhiliu revient, tenant un gage officiel et une carte.",
            ["DialogueId"] = 12040602,
            ["GUID"] = "1E247344",
            ["NextDialogue"] = 12040603,
            ["SpeakNpcId"] = 0,
            ["VoiceName"] = "voice/$Locale$/story/1204/120406/1E247344",
            },
        [12040603] = {
            ["Content"] = "该去的地点我已经给你们标注在上面了。分别是西南方的<H>参商港</>，内城的<H>祀烟阁</>，以及与其临对的<H>匠矩阁</>。",
            ["ContentFR"] = "J’ai marqué sur cette carte les lieux où vous devrez vous rendre : le <H>Port des Astres Séparés</>, au sud-ouest ; le <H>Pavillon de l’Encens</>, dans la ville intérieure ; et, face à lui, le <H>Pavillon des Artisans</>.",
            ["DialogueId"] = 12040603,
            ["GUID"] = "1E24736E",
            ["NextDialogue"] = 12040604,
            ["RelatedWikiId"] = {
                [1] = 408017,
                [2] = 407011,
                [3] = 407012,
                },
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120406/1E24736E",
            },
        [12040604] = {
            ["Content"] = "他们看到这样信物，就知道你是天禄司差遣来的信使，会将东西交予你。",
            ["ContentFR"] = "Présentez ce gage. Ils comprendront que vous agissez pour le Bureau de la Fortune Céleste et vous remettront les objets.",
            ["DialogueId"] = 12040604,
            ["GUID"] = "1E247398",
            ["NextDialogue"] = 12040605,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120406/1E247398",
            },
        [12040605] = {
            ["Content"] = "好嘞，止流姐姐。那这些东西拿到之后，我们在哪里会合？",
            ["ContentFR"] = "Compris, Zhiliu ! Et une fois qu’on aura tout récupéré, on se retrouve où ?",
            ["DialogueId"] = 12040605,
            ["GUID"] = "1E2473C2",
            ["NextDialogue"] = 12040606,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120406/1E2473C2",
            },
        [12040606] = {
            ["Content"] = "……很遗憾。我有一些紧要事情需要去处理。接下来，你们或许会有一段时间见不到我。",
            ["ContentFR"] = "... Je crains d’avoir des affaires urgentes à régler. Il est possible que nous ne nous revoyions pas avant un certain temps.",
            ["DialogueId"] = 12040606,
            ["GUID"] = "1E2473EC",
            ["NextDialogue"] = 12040607,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120406/1E2473EC",
            },
        [12040607] = {
            ["Content"] = "等你们到了执律阁之上，只要说明来意，就会有专人与你们对接。",
            ["ContentFR"] = "Lorsque vous atteindrez le Pavillon de l’Arbitrage, exposez simplement votre mission. Quelqu’un viendra à votre rencontre.",
            ["DialogueId"] = 12040607,
            ["GUID"] = "1E247416",
            ["NextDialogue"] = 12040608,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120406/1E247416",
            },
        [12040608] = {
            ["Content"] = "哎？那好吧，没想到这么快就要和止流姐姐说再见了。",
            ["ContentFR"] = "Hein ? Déjà ? Je ne pensais pas qu’on se dirait au revoir si vite...",
            ["DialogueId"] = 12040608,
            ["GUID"] = "1E247440",
            ["NextDialogue"] = 12040609,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120406/1E247440",
            },
        [12040609] = {
            ["Content"] = "呵呵……华胥有句古话，叫做难得是欢聚，唯有别离多。{nickname}，在我们道别之前，我还有几句话想和你说。",
            ["ContentFR"] = "Héhé... À Huaxu, on dit : « Les rencontres sont rares ; les séparations, innombrables. » {nickname}... avant de nous quitter, j’ai encore quelques mots à t’adresser.",
            ["DialogueId"] = 12040609,
            ["GUID"] = "1E24746A",
            ["NextDialogue"] = 12040610,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120406/1E24746A",
            },
        [12040610] = {
            ["Content"] = "……？",
            ["ContentFR"] = "... ?",
            ["DialogueId"] = 12040610,
            ["GUID"] = "1E247494",
            ["NextDialogue"] = 12040611,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120406/1E247494",
            },
        [12040611] = {
            ["Content"] = "止流掌柜，你想说什么？",
            ["ContentFR"] = "Que souhaitez-vous me dire, Patronne Zhiliu ?",
            ["DialogueId"] = 12040611,
            ["GUID"] = "1E2474BE",
            ["NextDialogue"] = 12040612,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120406/1E2474BE",
            },
        [12040612] = {
            ["Content"] = "我为你卜了一卦，你当做是临行嘱托也好。未来几日，可能会发生一些出乎你意料的事情。",
            ["ContentFR"] = "J’ai tiré une divination à ton sujet. Considère-la comme un dernier conseil. Dans les jours à venir, certains événements pourraient te surprendre.",
            ["DialogueId"] = 12040612,
            ["GUID"] = "1E2474E8",
            ["NextDialogue"] = 12040613,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120406/1E2474E8",
            },
        [12040613] = {
            ["Content"] = "如果中途你有动摇的时候，稍微耐下心来，静候事态发展。最终，你会获得令你满意的报酬。",
            ["ContentFR"] = "Si le doute devait t’assaillir, prends le temps d’attendre. Laisse les choses suivre leur cours. Au bout du chemin, tu recevras une récompense qui te satisfera pleinement.",
            ["DialogueId"] = 12040613,
            ["GUID"] = "1E247512",
            ["NextDialogue"] = 12040614,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120406/1E247512",
            },
        [12040614] = {
            ["Content"] = "出乎意料的事情……令我满意的报酬？我听不太懂。",
            ["ContentFR"] = "Des événements surprenants... une récompense ? Je ne suis pas {性别:sûr|sûre} de comprendre.",
            ["DialogueId"] = 12040614,
            ["GUID"] = "1E24753C",
            ["NextDialogue"] = 12040615,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120406/1E24753C",
            },
        [12040615] = {
            ["Content"] = "卦象并不会将未来解释得如此清晰，它只能给出预测，或者说征兆。直到事情发生的一刻，卦象的寓意才能够得到解答。",
            ["ContentFR"] = "Une divination ne dévoile jamais l’avenir avec clarté. Elle n’en livre que des signes. Ce n’est qu’au moment où les faits se produisent que leur sens se révèle.",
            ["DialogueId"] = 12040615,
            ["GUID"] = "1E247566",
            ["NextDialogue"] = 12040616,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120406/1E247566",
            },
        [12040616] = {
            ["Content"] = "……虽然有点突兀，止流掌柜，我可以问你一个问题吗？",
            ["ContentFR"] = "... Puis-je vous poser une question ?",
            ["DialogueId"] = 12040616,
            ["GUID"] = "1E247590",
            ["NextDialogue"] = 12040617,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120406/1E247590",
            },
        [12040617] = {
            ["Content"] = "你说。",
            ["ContentFR"] = "Je t’écoute.",
            ["DialogueId"] = 12040617,
            ["GUID"] = "1E2475BA",
            ["NextOptions"] = {
                [1] = 12040618,
                },
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120406/1E2475BA",
            },
        [12040618] = {
            ["Content"] = "你是不是还有什么事情瞒着我？",
            ["ContentFR"] = "Me cachez-vous quelque chose ?",
            ["DialogueId"] = 12040618,
            ["GUID"] = "1E2475E4",
            ["NextDialogue"] = 12040619,
            ["VoiceName"] = "voice/$Locale$/story/1204/120406/1E2475E4",
            },
        [12040619] = {
            ["Content"] = "……",
            ["ContentFR"] = "...",
            ["DialogueId"] = 12040619,
            ["GUID"] = "1E24760E",
            ["NextDialogue"] = 12040620,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120406/1E24760E",
            },
        [12040620] = {
            ["Content"] = "我<H>现在</>还无法给出这个问题的答案。有些事，待时机到时，方见分晓。",
            ["ContentFR"] = "Je ne peux pas répondre à cette question... pas pour l’instant. Certaines vérités ne se révèlent qu’au moment venu.",
            ["DialogueId"] = 12040620,
            ["GUID"] = "1E247638",
            ["NextDialogue"] = 12040621,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120406/1E247638",
            },
        [12040621] = {
            ["Content"] = "诶，你们怎么了，怎么气氛突然那么沉重……没关系，以后还会见面啦！",
            ["ContentFR"] = "Eh ? Pourquoi vous avez l’air si graves, {性别:tous|toutes} les deux ? On se reverra, voyons !",
            ["DialogueId"] = 12040621,
            ["GUID"] = "1E247662",
            ["NextDialogue"] = 12040622,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120406/1E247662",
            },
        [12040622] = {
            ["Content"] = "止流姐姐，等我们回了冰湖城，就给你寄泪湖的明信片！泪湖水蓝汪汪的，可好看了。",
            ["ContentFR"] = "Zhiliu, quand on rentrera à Givrelac, je t’enverrai une carte du Lac du Deuil ! Son eau est d’un bleu incroyable !",
            ["DialogueId"] = 12040622,
            ["GUID"] = "1E24768C",
            ["NextDialogue"] = 12040623,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120406/1E24768C",
            },
        [12040623] = {
            ["Content"] = "好呀，我很期待。",
            ["ContentFR"] = "Héhé... J’en serai ravie.",
            ["DialogueId"] = 12040623,
            ["GUID"] = "1E2476B6",
            ["NextDialogue"] = 12040624,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120406/1E2476B6",
            },
        [12040624] = {
            ["Content"] = "那，使命必达小分队要出发了！小仆从，我们走！",
            ["ContentFR"] = "Mission express du Roi Démon, en route ! Petit larbin, on y va !",
            ["DialogueId"] = 12040624,
            ["GUID"] = "1E2476E0",
            ["NextDialogue"] = 12040625,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120406/1E2476E0",
            },
        [12040625] = {
            ["Content"] = "……",
            ["ContentFR"] = "...",
            ["DialogueId"] = 12040625,
            ["GUID"] = "1E24770A",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120406/1E24770A",
            },
        [12040701] = {
            ["Content"] = "你好，我们受天禄司所托，来取准备奉香大典需要的道具。这是我们的信物。",
            ["ContentFR"] = "Bonjour. Nous venons de la part du Bureau de la Fortune Céleste pour récupérer des fournitures destinées à la Cérémonie de l’Encens. Voici notre gage.",
            ["DialogueId"] = 12040701,
            ["GUID"] = "1E248382",
            ["NextDialogue"] = 12040702,
            ["RelatedWikiId"] = {
                [1] = 408010,
                [2] = 408016,
                [3] = 405014,
                [4] = 407010,
                [5] = 408017,
                },
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120407/1E248382",
            },
        [12040702] = {
            ["Content"] = "好嘞。您要拿的就是那些上等绸布是吧？早上刚刚清点完毕，现在都整整齐齐地码在仓库里了。",
            ["ContentFR"] = "Ah oui ! Vous êtes venus pour les soieries de première qualité, c’est bien ça ? On les a vérifiées ce matin. Elles sont toutes bien rangées dans l’entrepôt.",
            ["DialogueId"] = 12040702,
            ["GUID"] = "1E2483AC",
            ["NextDialogue"] = 12040703,
            ["SpeakNpcId"] = 240027,
            ["VoiceName"] = "voice/$Locale$/story/1204/120407/1E2483AC",
            },
        [12040703] = {
            ["Content"] = "抱歉啊，最近这奉香大典快到了，天南地北的船只都停在了参商港。我们这里人手不够，暂且抽不开身。可以请您去仓库里取一下吗？",
            ["ContentFR"] = "Avec la Cérémonie qui approche, des navires affluent de toutes parts vers le Port des Astres Séparés. Nous manquons de bras... Pourriez-vous aller les chercher vous-mêmes ?",
            ["DialogueId"] = 12040703,
            ["GUID"] = "1E2483D6",
            ["NextDialogue"] = 12040704,
            ["SpeakNpcId"] = 240027,
            ["TalkActionId"] = {
                [1] = "240027:Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120407/1E2483D6",
            },
        [12040704] = {
            ["Content"] = "没问题。您可以告诉我货物的特征吗？",
            ["ContentFR"] = "Bien sûr. À quoi ressemblent-elles ?",
            ["DialogueId"] = 12040704,
            ["GUID"] = "1E248400",
            ["NextDialogue"] = 12040705,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "240027:Talk01_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120407/1E248400",
            },
        [12040705] = {
            ["Content"] = "您朝着右手边的方向走下去，货物堆中贴着货签的那个箱子便是。真是多谢了啊。",
            ["ContentFR"] = "Prenez à droite et descendez. Cherchez une caisse portant une étiquette officielle. Vous ne pourrez pas la manquer.",
            ["DialogueId"] = 12040705,
            ["GUID"] = "1E24842A",
            ["SpeakNpcId"] = 240027,
            ["VoiceName"] = "voice/$Locale$/story/1204/120407/1E24842A",
            },
        [12040801] = {
            ["Content"] = "呜哇！好大一个箱子在空中飘着！",
            ["ContentFR"] = "Ouah ! Elle flotte !",
            ["DialogueId"] = 12040801,
            ["GUID"] = "1E2493EA",
            ["NextDialogue"] = 12040802,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120408/1E2493EA",
            },
        [12040802] = {
            ["Content"] = "看那上面贴着的封纸，莫非是我们要找的——",
            ["ContentFR"] = "Regarde le sceau... Ce serait celle qu’on cherche ?",
            ["DialogueId"] = 12040802,
            ["GUID"] = "1E249414",
            ["NextDialogue"] = 12040803,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120408/1E249414",
            },
        [12040803] = {
            ["Content"] = "绫罗绸缎，金樽玉盏，好不逍遥～",
            ["ContentFR"] = "Soieries chatoyantes, coupes d’or et jade précieux... Ah, quelle douce liberté~",
            ["DialogueId"] = 12040803,
            ["GUID"] = "1E24943E",
            ["NextDialogue"] = 12040804,
            ["SpeakNpcId"] = 240028,
            ["VoiceName"] = "voice/$Locale$/story/1204/120408/1E24943E",
            },
        [12040804] = {
            ["Content"] = "我逍遥生看中的美物，被你们这等俗人拿走，岂不是一桩憾事。且让我先行一步——",
            ["ContentFR"] = "Moi, Xiaoyao, je ne saurais laisser une telle merveille tomber entre des mains si ordinaires. Je me permets de l’emporter.",
            ["DialogueId"] = 12040804,
            ["GUID"] = "1E249468",
            ["NextDialogue"] = 12040805,
            ["SpeakNpcId"] = 240028,
            ["VoiceName"] = "voice/$Locale$/story/1204/120408/1E249468",
            },
        [12040805] = {
            ["Content"] = "喂，怎么说话的，看不起谁呢！",
            ["ContentFR"] = "Hé ! Pour qui tu nous prends ?!",
            ["DialogueId"] = 12040805,
            ["GUID"] = "1E249492",
            ["NextDialogue"] = 12040806,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120408/1E249492",
            },
        [12040806] = {
            ["Content"] = "不好，无由生拿着我们要的东西跑了！不能让它得逞，小仆从，我们快追！",
            ["ContentFR"] = "Il a pris notre cargaison ! On ne va pas le laisser faire — poursuis-le, vite !",
            ["DialogueId"] = 12040806,
            ["GUID"] = "1E2494BC",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120408/1E2494BC",
            },
        [12040901] = {
            ["Content"] = "无趣无趣，你们既然如此执着，这东西还给你们也罢。拿着吧——",
            ["ContentFR"] = "Quelle obstination... Si vous y tenez tant, reprenez donc votre bien.",
            ["DialogueId"] = 12040901,
            ["GUID"] = "1E24A452",
            ["NextDialogue"] = 12040902,
            ["SpeakNpcId"] = 240028,
            ["VoiceName"] = "voice/$Locale$/story/1204/120409/1E24A452",
            },
        [12040902] = {
            ["Content"] = "喂，以为这样就算了嘛？你还没向白魔王大人和小仆从道歉呢！",
            ["ContentFR"] = "Et tu crois que ça suffit ?! Tu nous dois des excuses !",
            ["DialogueId"] = 12040902,
            ["GUID"] = "1E24A47C",
            ["NextDialogue"] = 12040903,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120409/1E24A47C",
            },
        [12040903] = {
            ["Content"] = "哈哈！贪愚痴妄，转首空空，不如逍遥～二位，我们有缘再会！",
            ["ContentFR"] = "Haha ! Cupidité, ignorance, illusion... tout n’est que poussière. Mieux vaut vivre sans entraves~ Nous nous reverrons... si le destin le veut.",
            ["DialogueId"] = 12040903,
            ["GUID"] = "1E24A4A6",
            ["NextDialogue"] = 12040904,
            ["RelatedWikiId"] = {
                [1] = 203008,
                },
            ["SpeakNpcId"] = 240028,
            ["VoiceName"] = "voice/$Locale$/story/1204/120409/1E24A4A6",
            },
        [12040904] = {
            ["Content"] = "可恶，这家伙就这样跑掉了……下次再见到它，一定要给它点颜色看看！",
            ["ContentFR"] = "<I>Tss...</> Il s’est encore échappé. La prochaine fois, il ne s’en tirera pas si facilement !",
            ["DialogueId"] = 12040904,
            ["GUID"] = "1E24A4D0",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120409/1E24A4D0",
            },
        [12041001] = {
            ["Content"] = "你好，我们是来拿奉香大典需要的……",
            ["ContentFR"] = "Bonjour ! Nous venons récupérer les fournitures pour la Cérémonie—",
            ["DialogueId"] = 12041001,
            ["GUID"] = "1E24B4BA",
            ["NextDialogue"] = 12041002,
            ["RelatedWikiId"] = {
                [1] = 408010,
                [2] = 408016,
                [3] = 405014,
                [4] = 407010,
                [5] = 407011,
                },
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120410/1E24B4BA",
            },
        [12041002] = {
            ["Content"] = "喂喂，你这个皎皎怎么插队呢？明明是本姑娘先来的！",
            ["ContentFR"] = "Hé ! On ne double pas la file, Luno ! J’étais là avant !",
            ["DialogueId"] = 12041002,
            ["GUID"] = "1E24B4E4",
            ["NextDialogue"] = 12041003,
            ["SpeakNpcId"] = 240007,
            ["VoiceName"] = "voice/$Locale$/story/1204/120410/1E24B4E4",
            },
        [12041003] = {
            ["Content"] = "插队？没有没有，你搞错了，我们是过来拿……",
            ["ContentFR"] = "Doubler ? Pas du tout, nous sommes juste—",
            ["DialogueId"] = 12041003,
            ["GUID"] = "1E24B50E",
            ["NextDialogue"] = 12041004,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120410/1E24B50E",
            },
        [12041004] = {
            ["Content"] = "好好好，打住打住。这位皎皎，还有这位白衣服的朋友，本姑娘理解你们对于求香的渴望，但是请乖乖到队尾站好。",
            ["ContentFR"] = "Allons, allons... Toi, la Luno, et ton {性别:ami|amie} en blanc — je comprends votre impatience à obtenir de l’encens. Mais la file commence là-bas.",
            ["DialogueId"] = 12041004,
            ["GUID"] = "1E24B538",
            ["NextDialogue"] = 12041005,
            ["SpeakNpcId"] = 240007,
            ["VoiceName"] = "voice/$Locale$/story/1204/120410/1E24B538",
            },
        [12041005] = {
            ["Content"] = "喂，你这个人，怎么不听别人讲完话！",
            ["ContentFR"] = "Hé ! Laisse-moi finir !",
            ["DialogueId"] = 12041005,
            ["GUID"] = "1E24B562",
            ["NextDialogue"] = 12041006,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120410/1E24B562",
            },
        [12041006] = {
            ["Content"] = "这种招数，本姑娘见得多啦。临近奉香大典，为了在奉香群英试上拔得头筹，祀烟阁前全都是来求香博个好彩头的。",
            ["ContentFR"] = "À l’approche de la Cérémonie, tout le monde veut une faveur pour briller au Tournoi de l’Encens. Le Pavillon est bondé.",
            ["DialogueId"] = 12041006,
            ["GUID"] = "1E24B58C",
            ["NextDialogue"] = 12041007,
            ["SpeakNpcId"] = 240007,
            ["VoiceName"] = "voice/$Locale$/story/1204/120410/1E24B58C",
            },
        [12041007] = {
            ["Content"] = "但是！求香切记要心诚，想使小伎俩取巧逃避排队，那可是万、万、不、行——",
            ["ContentFR"] = "Mais l’encens ne répond qu’aux cœurs sincères ! Chercher à tricher — c’est absolument inacceptable !",
            ["DialogueId"] = 12041007,
            ["GUID"] = "1E24B5B6",
            ["NextDialogue"] = 12041008,
            ["SpeakNpcId"] = 240007,
            ["VoiceName"] = "voice/$Locale$/story/1204/120410/1E24B5B6",
            },
        [12041008] = {
            ["Content"] = "你们争执之时，突然有一阵大风刮来，吹得行人衣袂纷飞。",
            ["ContentFR"] = "Un vent violent se lève soudain. Les vêtements se soulèvent.",
            ["DialogueId"] = 12041008,
            ["GUID"] = "1E24B5E0",
            ["NextDialogue"] = 12041009,
            ["SpeakNpcId"] = 0,
            ["VoiceName"] = "voice/$Locale$/story/1204/120410/1E24B5E0",
            },
        [12041009] = {
            ["Content"] = "余光里，你好像看到什么轻飘飘的东西被大风卷起，直上云霄，最终落在了屋顶上。",
            ["ContentFR"] = "Vous apercevez du coin de l’œil un petit objet emporté par la bourrasque. Il tourbillonne jusqu’au toit d’un bâtiment voisin.",
            ["DialogueId"] = 12041009,
            ["GUID"] = "1E24B60A",
            ["NextDialogue"] = 12041010,
            ["SpeakNpcId"] = 0,
            ["VoiceName"] = "voice/$Locale$/story/1204/120410/1E24B60A",
            },
        [12041010] = {
            ["Content"] = "呜哇——本姑娘精心准备的节日限定版香囊！",
            ["ContentFR"] = "Aah ! Mon sachet d’encens que j’avais préparé spécialement pour la fête !",
            ["DialogueId"] = 12041010,
            ["GUID"] = "1E24B634",
            ["NextDialogue"] = 12041011,
            ["SpeakNpcId"] = 240007,
            ["VoiceName"] = "voice/$Locale$/story/1204/120410/1E24B634",
            },
        [12041011] = {
            ["Content"] = "……小仆从，看她好像很苦恼的样子。我们就大人有大量，帮她去把香囊捡回来吧。",
            ["ContentFR"] = "... Petit larbin, elle a l’air vraiment en détresse. Faisons preuve de générosité et allons le lui rapporter !",
            ["DialogueId"] = 12041011,
            ["GUID"] = "1E24B65E",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120410/1E24B65E",
            },
        [12041101] = {
            ["Content"] = "给，这是你的东西，别再弄丢了。",
            ["ContentFR"] = "Tiens. C’est à toi. Essaie de ne plus le laisser s’envoler.",
            ["DialogueId"] = 12041101,
            ["GUID"] = "1E24C522",
            ["NextDialogue"] = 12041102,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120411/1E24C522",
            },
        [12041102] = {
            ["Content"] = "……早就和你说了，我们才不是来插队的呢。魔王大人才不会做那种没素质的事情。",
            ["ContentFR"] = "... Je te l’avais dit, nous ne faisions pas la queue pour tricher. Le Roi Démon ne s’abaisserait jamais à une chose aussi vulgaire.",
            ["DialogueId"] = 12041102,
            ["GUID"] = "1E24C54C",
            ["NextDialogue"] = 12041103,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120411/1E24C54C",
            },
        [12041103] = {
            ["Content"] = "对不起……明明是我误会了你们，你们还不计前嫌地帮我取回香囊！",
            ["ContentFR"] = "Je suis désolée... Je vous ai mal jugés, et malgré cela, vous avez pris la peine de m’aider !",
            ["DialogueId"] = 12041103,
            ["GUID"] = "1E24C576",
            ["NextDialogue"] = 12041104,
            ["SpeakNpcId"] = 240007,
            ["VoiceName"] = "voice/$Locale$/story/1204/120411/1E24C576",
            },
        [12041104] = {
            ["Content"] = "……今天的新闻有素材了！我要把两位的善举整理成文章，刊登在《皓京市声报》上！",
            ["ContentFR"] = "Ah ! Voilà un excellent sujet pour le journal du jour ! Je vais relater votre bonne action dans <I>L’Écho de Haojing</> !",
            ["DialogueId"] = 12041104,
            ["GUID"] = "1E24C5A0",
            ["NextDialogue"] = 12041105,
            ["SpeakNpcId"] = 240007,
            ["VoiceName"] = "voice/$Locale$/story/1204/120411/1E24C5A0",
            },
        [12041105] = {
            ["Content"] = "呵呵……晚来一步，倒是见识了一则明德惟馨的佳话。",
            ["ContentFR"] = "Héhé... Me voilà arrivé un peu tard, mais à temps pour assister à un bel exemple de vertu.",
            ["DialogueId"] = 12041105,
            ["GUID"] = "1E24C5CA",
            ["NextDialogue"] = 12041106,
            ["SpeakNpcId"] = 240008,
            ["VoiceName"] = "voice/$Locale$/story/1204/120411/1E24C5CA",
            },
        [12041106] = {
            ["Content"] = "两位可是来领奉香大典所需的皓烟香？抱歉让你们久等了，在此原物奉上。",
            ["ContentFR"] = "Vous venez récupérer l’Encens de Fumée Argentée destiné à la Cérémonie ? Veuillez excuser l’attente. Le voici.",
            ["DialogueId"] = 12041106,
            ["GUID"] = "1E24C5F4",
            ["SpeakNpcId"] = 240008,
            ["VoiceName"] = "voice/$Locale$/story/1204/120411/1E24C5F4",
            },
        [12041201] = {
            ["Content"] = "对面忙得要命，这边反而都见不着几个人……好冷清哦。",
            ["ContentFR"] = "C’est étrange... Là-bas c’est bondé, mais ici ? Presque personne. Quel calme...",
            ["DialogueId"] = 12041201,
            ["GUID"] = "1E24D58A",
            ["NextDialogue"] = 12041202,
            ["RelatedWikiId"] = {
                [1] = 408010,
                [2] = 408016,
                [3] = 405014,
                [4] = 407010,
                [5] = 407012,
                },
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120412/1E24D58A",
            },
        [12041202] = {
            ["Content"] = "有点看不出谁才是匠矩阁的人。小仆从，我们在附近找找看吧。",
            ["ContentFR"] = "Difficile de savoir qui travaille ici. Petit larbin, cherchons autour.",
            ["DialogueId"] = 12041202,
            ["GUID"] = "1E24D5B4",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120412/1E24D5B4",
            },
        [12041301] = {
            ["Content"] = "你好，请问你是匠矩阁的人吗？",
            ["ContentFR"] = "Bonjour. Travaillez-vous pour le Pavillon des Artisans ?",
            ["DialogueId"] = 12041301,
            ["GUID"] = "1E24E5F2",
            ["NextDialogue"] = 12041302,
            ["RelatedWikiId"] = {
                [1] = 408010,
                [2] = 408016,
                [3] = 405014,
                [4] = 407010,
                [5] = 407012,
                },
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120413/1E24E5F2",
            },
        [12041302] = {
            ["Content"] = "匠矩阁？你说那帮神龙见首不见尾的人吗？我和他们不熟。",
            ["ContentFR"] = "Le Pavillon des Artisans ? Ces gens qu’on ne voit jamais ? Je ne les connais pas.",
            ["DialogueId"] = 12041302,
            ["GUID"] = "1E24E61C",
            ["SpeakNpcId"] = 240004,
            ["TalkActionId"] = {
                [1] = "240004:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120413/1E24E61C",
            },
        [12041401] = {
            ["Content"] = "你好，请问你是匠矩阁的人吗？",
            ["ContentFR"] = "Excusez-moi, faites-vous partie du Pavillon des Artisans ?",
            ["DialogueId"] = 12041401,
            ["GUID"] = "1E24F65A",
            ["NextDialogue"] = 12041402,
            ["RelatedWikiId"] = {
                [1] = 408010,
                [2] = 408016,
                [3] = 405014,
                [4] = 407010,
                [5] = 407012,
                },
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120414/1E24F65A",
            },
        [12041402] = {
            ["Content"] = "啊？不是，我就是看这儿清净，不像隔壁吵吵闹闹的。",
            ["ContentFR"] = "Moi ? Non. Je viens juste profiter du calme. Rien à voir avec le tumulte d’en face.",
            ["DialogueId"] = 12041402,
            ["GUID"] = "1E24F684",
            ["SpeakNpcId"] = 240005,
            ["TalkActionId"] = {
                [1] = "240005:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120414/1E24F684",
            },
        [12041501] = {
            ["Content"] = "你好，请问你是匠矩阁的人吗？",
            ["ContentFR"] = "Pardonnez-moi, êtes-vous du Pavillon des Artisans ?",
            ["DialogueId"] = 12041501,
            ["GUID"] = "1E2506C2",
            ["NextDialogue"] = 12041502,
            ["RelatedWikiId"] = {
                [1] = 408010,
                [2] = 408016,
                [3] = 405014,
                [4] = 407010,
                [5] = 407012,
                },
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120415/1E2506C2",
            },
        [12041502] = {
            ["Content"] = "呸呸呸，别乱说，我在准备会考呢。天禄司，天礼司，去哪都好，就是不能沾上这天梁司的晦气啊。",
            ["ContentFR"] = "<I>Pff !</> Ne dites pas ça si fort ! Je prépare l’examen des administrations. Fortune Céleste, Rites, peu importe... mais surtout pas le Bureau des Travaux ! Porte-malheur !",
            ["DialogueId"] = 12041502,
            ["GUID"] = "1E2506EC",
            ["SpeakNpcId"] = 240006,
            ["TalkActionId"] = {
                [1] = "240005:Angry01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120415/1E2506EC",
            },
        [12041601] = {
            ["Content"] = "问了一圈，结果都不是。那这里眼看着也没别人了……",
            ["ContentFR"] = "On a fait le tour... et personne. C’est vraiment désert ici.",
            ["DialogueId"] = 12041601,
            ["GUID"] = "1E25172A",
            ["NextDialogue"] = 12041602,
            ["RelatedWikiId"] = {
                [1] = 408010,
                [2] = 408016,
                [3] = 405014,
                [4] = 407010,
                [5] = 407012,
                },
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120416/1E25172A",
            },
        [12041602] = {
            ["Content"] = "喂？有——人——在——吗——",
            ["ContentFR"] = "Il y a quelqu’un—— ?",
            ["DialogueId"] = 12041602,
            ["GUID"] = "1E251754",
            ["NextDialogue"] = 12041603,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120416/1E251754",
            },
        [12041603] = {
            ["Content"] = "在呢，别扯嗓子吆喝了——来了来了。",
            ["ContentFR"] = "Oui, oui, inutile de hurler. J’arrive.",
            ["DialogueId"] = 12041603,
            ["GUID"] = "1E25177E",
            ["NextDialogue"] = 12041604,
            ["SpeakNpcId"] = 240009,
            ["VoiceName"] = "voice/$Locale$/story/1204/120416/1E25177E",
            },
        [12041604] = {
            ["Content"] = "看，这是天禄司的信物！我说大叔，你不是应该在这儿等着交接奉香大典的物资吗？怎么跑那么远啦，该不会是上班偷懒——",
            ["ContentFR"] = "Regardez ! Voici le gage du Bureau de la Fortune Céleste ! Dites-moi, vous n’étiez pas censé attendre ici pour remettre les fournitures de la Cérémonie ? Vous ne seriez pas en train de vous la couler douce, par hasard—",
            ["DialogueId"] = 12041604,
            ["GUID"] = "1E2517A8",
            ["NextDialogue"] = 12041605,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120416/1E2517A8",
            },
        [12041605] = {
            ["Content"] = "嘿，你这小豆丁怎么说话呢？人生在世屈指算，最多三万六千天。那自然是图个清净，开心一天算一天。",
            ["ContentFR"] = "Hé ! Petite crevette, surveille un peu tes paroles ! La vie d’un homme ne dépasse guère trente-six mille jours. Autant savourer chaque instant de tranquillité.",
            ["DialogueId"] = 12041605,
            ["GUID"] = "1E2517D2",
            ["NextDialogue"] = 12041606,
            ["SpeakNpcId"] = 240009,
            ["VoiceName"] = "voice/$Locale$/story/1204/120416/1E2517D2",
            },
        [12041606] = {
            ["Content"] = "当值的活都干完了，光人杵在这儿，有什么用？最瞧不起没活还要硬忙活的人了，净装样子，不干实事。",
            ["ContentFR"] = "Quand le travail est fait, rester planté là pour faire semblant d’être occupé ne sert à rien. Je n’ai jamais supporté ceux qui font du bruit pour paraître utiles.",
            ["DialogueId"] = 12041606,
            ["GUID"] = "1E2517FC",
            ["NextDialogue"] = 12041607,
            ["SpeakNpcId"] = 240009,
            ["VoiceName"] = "voice/$Locale$/story/1204/120416/1E2517FC",
            },
        [12041607] = {
            ["Content"] = "我们匠矩阁，光是修这个桥那个路，交付各式民用机傀，便要一个月忙活上二十几天，好不容易得了闲，休息片刻，还不行了？",
            ["ContentFR"] = "Au Pavillon des Artisans, nous passons nos journées à réparer ponts et routes, à livrer toutes sortes de mécanismes civils. Si nous avons enfin un moment de répit, pourquoi ne pas en profiter ?",
            ["DialogueId"] = 12041607,
            ["GUID"] = "1E251826",
            ["NextDialogue"] = 12041608,
            ["SpeakNpcId"] = 240009,
            ["VoiceName"] = "voice/$Locale$/story/1204/120416/1E251826",
            },
        [12041608] = {
            ["Content"] = "嗯……也是这个理！白赞同！",
            ["ContentFR"] = "Hmm... Ce n’est pas faux. Le Roi Démon approuve !",
            ["DialogueId"] = 12041608,
            ["GUID"] = "1E251850",
            ["NextDialogue"] = 12041609,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120416/1E251850",
            },
        [12041609] = {
            ["Content"] = "瞧你们还算讲道理的。喏，那就是奉香大典需要的奉香炉。早就放那台阶上了，你们去取吧。",
            ["ContentFR"] = "Je vois que vous êtes raisonnables. Le brûle-encens de la Cérémonie est posé là, sur les marches. Allez le prendre.",
            ["DialogueId"] = 12041609,
            ["GUID"] = "1E25187A",
            ["SpeakNpcId"] = 240009,
            ["VoiceName"] = "voice/$Locale$/story/1204/120416/1E25187A",
            },
        [12041701] = {
            ["Content"] = "咚——咚——咚——咚——",
            ["ContentFR"] = "<I>Dong—— Dong—— Dong—— Dong——</>",
            ["DialogueId"] = 12041701,
            ["GUID"] = "1E252792",
            ["NextDialogue"] = 12041702,
            ["RelatedWikiId"] = {
                [1] = 408010,
                [2] = 408016,
                [3] = 405014,
                [4] = 407009,
                },
            ["SpeakNpcId"] = 0,
            ["VoiceName"] = "voice/$Locale$/story/1204/120417/1E252792",
            },
        [12041702] = {
            ["Content"] = "这是什么动静？",
            ["ContentFR"] = "Qu’est-ce que c’était ?",
            ["DialogueId"] = 12041702,
            ["GUID"] = "1E2527BC",
            ["NextDialogue"] = 12041703,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120417/1E2527BC",
            },
        [12041703] = {
            ["Content"] = "邪门了……这是执律阁的钟声。今天可真是撞上太阳从西边出来了。",
            ["ContentFR"] = "Étrange... C’est la cloche du Pavillon de l’Arbitrage. Je n’aurais jamais cru l’entendre sonner de mon vivant.",
            ["DialogueId"] = 12041703,
            ["GUID"] = "1E2527E6",
            ["NextDialogue"] = 12041704,
            ["SpeakNpcId"] = 240009,
            ["VoiceName"] = "voice/$Locale$/story/1204/120417/1E2527E6",
            },
        [12041704] = {
            ["Content"] = "这钟平时很少敲响吗？",
            ["ContentFR"] = "Elle ne sonne presque jamais ?",
            ["DialogueId"] = 12041704,
            ["GUID"] = "1E252810",
            ["NextDialogue"] = 12041705,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120417/1E252810",
            },
        [12041705] = {
            ["Content"] = "何止是少有？我活了大半辈子，就从未听到它响起过！",
            ["ContentFR"] = "Presque jamais ? Je n’ai jamais entendu ce son auparavant !",
            ["DialogueId"] = 12041705,
            ["GUID"] = "1E25283A",
            ["NextDialogue"] = 12041706,
            ["SpeakNpcId"] = 240009,
            ["VoiceName"] = "voice/$Locale$/story/1204/120417/1E25283A",
            },
        [12041706] = {
            ["Content"] = "哎？！那是发生了什么大事吗？",
            ["ContentFR"] = "Hein ?! C’est donc grave ?",
            ["DialogueId"] = 12041706,
            ["GUID"] = "1E252864",
            ["NextDialogue"] = 12041707,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120417/1E252864",
            },
        [12041707] = {
            ["Content"] = "冰湖城进行军事演练的时候，就会在全城响起乌拉乌拉的刺耳警笛声，白每次听到都会吓一跳。这也是类似的情况吗？",
            ["ContentFR"] = "À Givrelac, quand on fait des exercices militaires, des sirènes assourdissantes retentissent dans toute la ville. Est-ce le même genre de situation ?",
            ["DialogueId"] = 12041707,
            ["GUID"] = "1E25288E",
            ["NextDialogue"] = 12041708,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120417/1E25288E",
            },
        [12041708] = {
            ["Content"] = "被你这样一说……",
            ["ContentFR"] = "Peut-être bien...",
            ["DialogueId"] = 12041708,
            ["GUID"] = "1E2528B8",
            ["NextDialogue"] = 12041709,
            ["SpeakNpcId"] = 240009,
            ["VoiceName"] = "voice/$Locale$/story/1204/120417/1E2528B8",
            },
        [12041709] = {
            ["Content"] = "我祖父好像从他的曾祖父那里听说过，在上古时期，若是有罪情复杂难辨之人出现，执律阁顶的钟声就会鸣响。",
            ["ContentFR"] = "Mon grand-père tenait cela de son propre arrière-grand-père : autrefois, lorsqu’une affaire devenait trop complexe à juger, la cloche du Pavillon sonnait.",
            ["DialogueId"] = 12041709,
            ["GUID"] = "1E2528E2",
            ["NextDialogue"] = 12041710,
            ["SpeakNpcId"] = 240009,
            ["VoiceName"] = "voice/$Locale$/story/1204/120417/1E2528E2",
            },
        [12041710] = {
            ["Content"] = "届时，龙神将与凡人一起，于执律阁巅<H>辩法</>，共商案情。但这已经是少有人知的传闻了。",
            ["ContentFR"] = "Alors, le Seigneur Dragon d’Argent descendait et tenait un <H>Rite de Délibération</> au sommet du Pavillon de l’Arbitrage, afin d’examiner l’affaire aux côtés des mortels. Mais ce ne sont plus que de vieilles légendes.",
            ["DialogueId"] = 12041710,
            ["GUID"] = "1E25290C",
            ["NextDialogue"] = 12041711,
            ["RelatedWikiId"] = {
                [1] = 407013,
                },
            ["SpeakNpcId"] = 240009,
            ["VoiceName"] = "voice/$Locale$/story/1204/120417/1E25290C",
            },
        [12041711] = {
            ["Content"] = "如今承蒙大风九章荫蔽，华胥海晏河清，罪徒早就被那狴犴降服了，哪里还用得着这老掉牙的辩法。",
            ["ContentFR"] = "Aujourd’hui, sous la protection des Neuf Chapitres de Dafeng, Huaxu connaît la paix. Les criminels sont maîtrisés par les Bi’an bien avant qu’on en arrive à ces méthodes anciennes.",
            ["DialogueId"] = 12041711,
            ["GUID"] = "1E252936",
            ["NextDialogue"] = 12041712,
            ["RelatedWikiId"] = {
                [1] = 304003,
                },
            ["SpeakNpcId"] = 240009,
            ["VoiceName"] = "voice/$Locale$/story/1204/120417/1E252936",
            },
        [12041712] = {
            ["Content"] = "嗐，尽在这瞎想也没用。无论内情如何，都会有相关榜文张贴在执律阁前广场的告示板上。想必那白纸黑字，比我在这儿空口无凭来得有用。",
            ["ContentFR"] = "Bah... inutile de spéculer. Si quelque chose d’important s’est produit, un avis officiel sera affiché sur la place devant le Pavillon de l’Arbitrage. Mieux vaut se fier à l’encre noire sur papier blanc qu’à mes souvenirs flous.",
            ["DialogueId"] = 12041712,
            ["GUID"] = "1E252960",
            ["NextDialogue"] = 12041713,
            ["SpeakNpcId"] = 240009,
            ["VoiceName"] = "voice/$Locale$/story/1204/120417/1E252960",
            },
        [12041713] = {
            ["Content"] = "执律阁前广场……啊，小仆从，那我们岂不是刚好顺路？",
            ["ContentFR"] = "La place devant le Pavillon... Petit larbin, c’est justement sur notre route !",
            ["DialogueId"] = 12041713,
            ["GUID"] = "1E25298A",
            ["NextDialogue"] = 12041714,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120417/1E25298A",
            },
        [12041714] = {
            ["Content"] = "去吧去吧，年轻人就是好奇心重。我一把老骨头，就不跟你们去凑热闹了。",
            ["ContentFR"] = "Allez donc satisfaire votre curiosité. Ces vieux os resteront ici.",
            ["DialogueId"] = 12041714,
            ["GUID"] = "1E2529B4",
            ["NextDialogue"] = 12041715,
            ["SpeakNpcId"] = 240009,
            ["VoiceName"] = "voice/$Locale$/story/1204/120417/1E2529B4",
            },
        [12041715] = {
            ["Content"] = "只希望，这次可别出什么大事哟……",
            ["ContentFR"] = "Espérons seulement que cela n’annonce rien de fâcheux...",
            ["DialogueId"] = 12041715,
            ["GUID"] = "1E2529DE",
            ["SpeakNpcId"] = 240009,
            ["VoiceName"] = "voice/$Locale$/story/1204/120417/1E2529DE",
            },
        [12041801] = {
            ["Content"] = "\"……竟然……",
            ["ContentFR"] = "... Incroyable... Comment a-t-il pu... ?",
            ["DialogueId"] = 12041801,
            ["GUID"] = "1E2537FA",
            ["NextDialogue"] = 12041803,
            ["RelatedWikiId"] = {
                [1] = 408010,
                [2] = 408016,
                [3] = 405014,
                [4] = 407009,
                [5] = 407013,
                [6] = 304003,
                },
            ["SpeakNpcId"] = 240004,
            ["VoiceName"] = "voice/$Locale$/story/1204/120418/1E2537FA",
            },
        [12041803] = {
            ["Content"] = "\"……闻所未闻……",
            ["ContentFR"] = "... Du jamais vu... À Huaxu, une chose pareille...",
            ["DialogueId"] = 12041803,
            ["GUID"] = "1E25384E",
            ["NextDialogue"] = 12041805,
            ["SpeakNpcId"] = 240005,
            ["VoiceName"] = "voice/$Locale$/story/1204/120418/1E25384E",
            },
        [12041805] = {
            ["Content"] = "……罪大恶极……这是他应得的……",
            ["ContentFR"] = "... Un crime impardonnable... Il mérite son sort...",
            ["DialogueId"] = 12041805,
            ["GUID"] = "1E2538A2",
            ["NextDialogue"] = 12041806,
            ["SpeakNpcId"] = 240006,
            ["VoiceName"] = "voice/$Locale$/story/1204/120418/1E2538A2",
            },
        [12041806] = {
            ["Content"] = "前面都被他们挡住了，什么都看不见……",
            ["ContentFR"] = "Ils bloquent tout devant ! On ne voit absolument rien...",
            ["DialogueId"] = 12041806,
            ["GUID"] = "1E2538CC",
            ["NextDialogue"] = 12041807,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120418/1E2538CC",
            },
        }
  end },
  { MinKey = 12041807, MaxKey = 12043326, Loader = function()
      return {
        [12041807] = {
            ["Content"] = "可恶！看我原地霹雳闪电跳！",
            ["ContentFR"] = "Très bien ! Place au Saut Foudroyant du Roi Démon !",
            ["DialogueId"] = 12041807,
            ["GUID"] = "1E2538F6",
            ["NextDialogue"] = 12041808,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120418/1E2538F6",
            },
        [12041808] = {
            ["Content"] = "在人群的推挤中，你努力踮起脚，往前看去。",
            ["ContentFR"] = "Ballotté par la foule, vous vous hissez sur la pointe des pieds.",
            ["DialogueId"] = 12041808,
            ["GUID"] = "1E253920",
            ["NextDialogue"] = 12041809,
            ["SpeakNpcId"] = 0,
            ["VoiceName"] = "voice/$Locale$/story/1204/120418/1E253920",
            },
        [12041809] = {
            ["Content"] = "视线好不容易越过人群，捕捉到了告示板上的内容。画像中熟悉的面容却让你和白齐齐一惊。",
            ["ContentFR"] = "Votre regard parvient enfin à dépasser les têtes... Et l’image affichée vous glace le sang.",
            ["DialogueId"] = 12041809,
            ["GUID"] = "1E25394A",
            ["NextDialogue"] = 12041810,
            ["SpeakNpcId"] = 0,
            ["VoiceName"] = "voice/$Locale$/story/1204/120418/1E25394A",
            },
        [12041810] = {
            ["Content"] = "怎么是他？！",
            ["ContentFR"] = "C’est lui ?!",
            ["DialogueId"] = 12041810,
            ["GUID"] = "1E253974",
            ["RelatedWikiId"] = {
                [1] = 203007,
                },
            ["SpeakNpcName"] = "UI_Npc_Name_ZhuJueBai",
            ["VoiceName"] = "voice/$Locale$/story/1204/120418/1E253974",
            },
        [12041901] = {
            ["Content"] = "怎么，终于忍不住露面了？",
            ["ContentFR"] = "Ah. Tu te décides enfin à sortir de ton trou ?",
            ["DialogueId"] = 12041901,
            ["GUID"] = "1E254862",
            ["NextDialogue"] = 12041902,
            ["RelatedWikiId"] = {
                [1] = 203007,
                [2] = 405010,
                [3] = 304003,
                },
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120419/1E254862",
            },
        [12041902] = {
            ["Content"] = "……鲜廉寡耻之徒。",
            ["ContentFR"] = "... Misérable sans honneur.",
            ["DialogueId"] = 12041902,
            ["GUID"] = "1E25488C",
            ["NextDialogue"] = 12041903,
            ["SpeakNpcId"] = 240103,
            ["VoiceName"] = "voice/$Locale$/story/1204/120419/1E25488C",
            },
        [12041903] = {
            ["Content"] = "尔等飘零人，本为天理所不容。因你们踪迹难寻，才暂且教你们苟且偷生。",
            ["ContentFR"] = "Vous autres vagabonds n’êtes pas tolérés par l’ordre céleste. Si vous avez survécu jusqu’ici, c’est seulement parce que vous savez vous dissimuler.",
            ["DialogueId"] = 12041903,
            ["GUID"] = "1E2548B6",
            ["NextDialogue"] = 12041904,
            ["SpeakNpcId"] = 240103,
            ["VoiceName"] = "voice/$Locale$/story/1204/120419/1E2548B6",
            },
        [12041904] = {
            ["Content"] = "如今竟自投罗网，当真以为大风九章的律法宽松至此，容得下你们这些人了？",
            ["ContentFR"] = "Et te voilà qui te livres de toi-même. Pensais-tu réellement que les Neuf Chapitres de Dafeng s’étaient ramollis au point d’accepter des gens comme toi ?",
            ["DialogueId"] = 12041904,
            ["GUID"] = "1E2548E0",
            ["NextDialogue"] = 12041905,
            ["SpeakNpcId"] = 240103,
            ["VoiceName"] = "voice/$Locale$/story/1204/120419/1E2548E0",
            },
        [12041905] = {
            ["Content"] = "哈哈……同僚都被击倒了，说这些大话，不觉得太早了吗？",
            ["ContentFR"] = "Haha ! Tes sbires sont déjà étendus dans la boue, et tu parles encore comme si tu me tenais. C’est presque touchant.",
            ["DialogueId"] = 12041905,
            ["GUID"] = "1E25490A",
            ["NextDialogue"] = 12041906,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120419/1E25490A",
            },
        [12041906] = {
            ["Content"] = "纵使你击退了这数十狴犴，又能说明什么？",
            ["ContentFR"] = "Même si tu as abattu ces dizaines de Bi’an, qu’est-ce que cela prouve ?",
            ["DialogueId"] = 12041906,
            ["GUID"] = "1E254934",
            ["NextDialogue"] = 12041907,
            ["SpeakNpcId"] = 240103,
            ["VoiceName"] = "voice/$Locale$/story/1204/120419/1E254934",
            },
        [12041907] = {
            ["Content"] = "但凡大风九章高悬一日，我等代行者便将前仆后继，不死不息，直至天理昭彰，尔等伏法方休。",
            ["ContentFR"] = "Tant que les Neuf Chapitres demeurent, nous, leurs exécutants, nous succéderons sans relâche — jusqu’à ce que la loi triomphe et que vous soyez mis à mort.",
            ["DialogueId"] = 12041907,
            ["GUID"] = "1E25495E",
            ["NextDialogue"] = 12041908,
            ["SpeakNpcId"] = 240103,
            ["VoiceName"] = "voice/$Locale$/story/1204/120419/1E25495E",
            },
        [12041908] = {
            ["Content"] = "以你一人之力，莫非还能敌得过大风九章天命之力？",
            ["ContentFR"] = "Crois-tu pouvoir lutter seul contre la volonté céleste ?",
            ["DialogueId"] = 12041908,
            ["GUID"] = "1E254988",
            ["NextDialogue"] = 12041909,
            ["SpeakNpcId"] = 240103,
            ["VoiceName"] = "voice/$Locale$/story/1204/120419/1E254988",
            },
        [12041909] = {
            ["Content"] = "说得好！",
            ["ContentFR"] = "Bien parlé.",
            ["DialogueId"] = 12041909,
            ["GUID"] = "1E2549B2",
            ["NextDialogue"] = 12041910,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120419/1E2549B2",
            },
        [12041910] = {
            ["Content"] = "干架是很痛快，可惜总是干架也解决不了事情。今天倒是要委屈我这把老伙计了。",
            ["ContentFR"] = "Se battre, c’est grisant. Mais frapper encore et encore ne règle rien. Aujourd’hui, je vais épargner à mon vieil ami un bain de sang supplémentaire.",
            ["DialogueId"] = 12041910,
            ["GUID"] = "1E2549DC",
            ["NextDialogue"] = 12041911,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120419/1E2549DC",
            },
        [12041911] = {
            ["Content"] = "喂，对面的，你也别紧张了，放轻松点。",
            ["ContentFR"] = "Toi, là. Détends-toi.",
            ["DialogueId"] = 12041911,
            ["GUID"] = "1E254A06",
            ["NextDialogue"] = 12041912,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120419/1E254A06",
            },
        [12041912] = {
            ["Content"] = "我刻舟，行不改名坐不改姓，这次是来申请<H>辩法</>的。",
            ["ContentFR"] = "Je m’appelle Kezhou. Et aujourd’hui, je viens réclamer un <H>Rite de Délibération</>.",
            ["DialogueId"] = 12041912,
            ["GUID"] = "1E254A30",
            ["NextDialogue"] = 12041913,
            ["RelatedWikiId"] = {
                [1] = 407013,
                },
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120419/1E254A30",
            },
        [12041913] = {
            ["Content"] = "<H>辩法</>……？",
            ["ContentFR"] = "... Un <H>Rite de Délibération</> ?",
            ["DialogueId"] = 12041913,
            ["GUID"] = "1E254A5A",
            ["NextDialogue"] = 12041914,
            ["SpeakNpcId"] = 240103,
            ["VoiceName"] = "voice/$Locale$/story/1204/120419/1E254A5A",
            },
        [12041914] = {
            ["Content"] = "你既然知晓这沉寂已久的上古礼法，便应当了解，如今的辩法已经名存实亡。",
            ["ContentFR"] = "Si tu connais cette antique procédure, tu sais aussi qu’elle n’est plus qu’un vestige sans substance.",
            ["DialogueId"] = 12041914,
            ["GUID"] = "1E254A84",
            ["NextDialogue"] = 12041915,
            ["SpeakNpcId"] = 240103,
            ["VoiceName"] = "voice/$Locale$/story/1204/120419/1E254A84",
            },
        [12041915] = {
            ["Content"] = "凡人早已将裁决的权力托付给神明，而白龙神君的意志一以贯之。于尔等狂徒而言，下场唯有伏诛。",
            ["ContentFR"] = "Les mortels ont confié le jugement aux dieux. La volonté du Seigneur Dragon d’Argent ne varie pas. Pour un forcené comme toi, l’issue ne peut être que l’exécution.",
            ["DialogueId"] = 12041915,
            ["GUID"] = "1E254AAE",
            ["NextDialogue"] = 12041916,
            ["SpeakNpcId"] = 240103,
            ["VoiceName"] = "voice/$Locale$/story/1204/120419/1E254AAE",
            },
        [12041916] = {
            ["Content"] = "哈哈！这种事情，不试上一试怎么知道？",
            ["ContentFR"] = "Si on ne tente pas, comment savoir ?",
            ["DialogueId"] = 12041916,
            ["GUID"] = "1E254AD8",
            ["NextDialogue"] = 12041917,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120419/1E254AD8",
            },
        [12041917] = {
            ["Content"] = "我刻舟自觉无罪。如今甘愿束手就擒，走上一趟程序，你也没有拒绝的理由吧？",
            ["ContentFR"] = "Je me sais innocent. Je me présente de mon plein gré pour en appeler à la procédure. Tu n’as aucune raison de refuser.",
            ["DialogueId"] = 12041917,
            ["GUID"] = "1E254B02",
            ["NextDialogue"] = 12041918,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120419/1E254B02",
            },
        [12041918] = {
            ["Content"] = "……呵。你执意赴死，我自当奉陪。",
            ["ContentFR"] = "... Très bien. Si tu tiens tant à marcher vers ta fin, je t’y accompagnerai.",
            ["DialogueId"] = 12041918,
            ["GUID"] = "1E254B2C",
            ["NextDialogue"] = 12041919,
            ["SpeakNpcId"] = 240103,
            ["VoiceName"] = "voice/$Locale$/story/1204/120419/1E254B2C",
            },
        [12041919] = {
            ["Content"] = "剑，交出来吧。",
            ["ContentFR"] = "Remets ton épée.",
            ["DialogueId"] = 12041919,
            ["GUID"] = "1E254B56",
            ["SpeakNpcId"] = 240103,
            ["VoiceName"] = "voice/$Locale$/story/1204/120419/1E254B56",
            },
        [12042001] = {
            ["Content"] = "“今有案犯刻舟，不服判决，审议辩法。定于公示次日午时，执律阁巅，叩准陈情圣裁。若情实无疑，则当场诛灭。”",
            ["ContentFR"] = "« Il est fait proclamation : Le prévenu Kezhou, contestant le jugement rendu, requiert un <H>Rite de Délibération</>. L’audience se tiendra demain à l’heure de midi, au sommet du Pavillon de l’Arbitrage, afin d’exposer ses arguments devant le Jugement sacré. Si les faits s’avèrent établis sans équivoque, l’exécution sera immédiate. »",
            ["DialogueId"] = 12042001,
            ["GUID"] = "1E2558CA",
            ["NextDialogue"] = 12042002,
            ["RelatedWikiId"] = {
                [1] = 203007,
                [2] = 407009,
                [3] = 407013,
                },
            ["SpeakNpcId"] = 240004,
            ["VoiceName"] = "voice/$Locale$/story/1204/120420/1E2558CA",
            },
        [12042002] = {
            ["Content"] = "“此示晓谕，各宜凛遵！”",
            ["ContentFR"] = "« Le présent avis est porté à la connaissance de tous. Qu’il soit observé avec la plus stricte solennité. »",
            ["DialogueId"] = 12042002,
            ["GUID"] = "1E2558F4",
            ["NextDialogue"] = 12042003,
            ["SpeakNpcId"] = 240004,
            ["VoiceName"] = "voice/$Locale$/story/1204/120420/1E2558F4",
            },
        [12042003] = {
            ["Content"] = "嚯，这么吓人！这个刻舟，不就是我们之前在听鸦原见过一面的那家伙吗？竟然还是个熟人。",
            ["ContentFR"] = "Ouah... Ça fait froid dans le dos. Kezhou... Ce n’est pas le type qu’on avait croisé à la Plaine des Corbeaux ? Incroyable qu’on le retrouve ici...",
            ["DialogueId"] = 12042003,
            ["GUID"] = "1E25591E",
            ["NextDialogue"] = 12042004,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120420/1E25591E",
            },
        [12042004] = {
            ["Content"] = "就是不知道他到底犯下了什么罪，画像都被放上通缉令了……",
            ["ContentFR"] = "Mais qu’est-ce qu’il a bien pu faire pour qu’on affiche son portrait comme ça...",
            ["DialogueId"] = 12042004,
            ["GUID"] = "1E255948",
            ["NextDialogue"] = 12042005,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120420/1E255948",
            },
        [12042005] = {
            ["Content"] = "……白，这里人太多了。我们去找个僻静的地方，我有话要和你说。",
            ["ContentFR"] = "... Snow. Il y a trop de monde ici. Allons quelque part de plus discret. J’ai quelque chose à te dire.",
            ["DialogueId"] = 12042005,
            ["GUID"] = "1E255972",
            ["NextDialogue"] = 12042006,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120420/1E255972",
            },
        [12042006] = {
            ["Content"] = "哎？搞得这么神秘兮兮的……哼哼，你成功勾起了我的兴趣！",
            ["ContentFR"] = "Oh ? À ce point-là mystérieux ? Héhé... Tu piques ma curiosité, là.",
            ["DialogueId"] = 12042006,
            ["GUID"] = "1E25599C",
            ["NextDialogue"] = 12042007,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120420/1E25599C",
            },
        [12042007] = {
            ["Content"] = "那，我们去那片树荫底下。那里看起来比较适合说悄悄话。",
            ["ContentFR"] = "Allons sous ces arbres. Ça a l’air parfait pour parler en secret.",
            ["DialogueId"] = 12042007,
            ["GUID"] = "1E2559C6",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120420/1E2559C6",
            },
        [12042101] = {
            ["Content"] = "好啦，旁边都没有人。小仆从，有什么话，你就放心大胆地说吧。",
            ["ContentFR"] = "Bon. Personne aux alentours. Petit larbin, je t’écoute.",
            ["DialogueId"] = 12042101,
            ["GUID"] = "1E256932",
            ["NextDialogue"] = 12042102,
            ["RelatedWikiId"] = {
                [1] = 203007,
                [2] = 407009,
                [3] = 407013,
                },
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120421/1E256932",
            },
        [12042102] = {
            ["Content"] = "白，听我说。那个刻舟……我们得想办法去救他。",
            ["ContentFR"] = "Snow... Écoute-moi bien. Kezhou... Il faut qu’on trouve un moyen de le sauver.",
            ["DialogueId"] = 12042102,
            ["GUID"] = "1E25695C",
            ["NextDialogue"] = 12042103,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120421/1E25695C",
            },
        [12042103] = {
            ["Content"] = "哎？！",
            ["ContentFR"] = "Quoi ?!",
            ["DialogueId"] = 12042103,
            ["GUID"] = "1E256986",
            ["NextDialogue"] = 12042104,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120421/1E256986",
            },
        [12042104] = {
            ["Content"] = "倒不是我不愿意啦……小仆从，我们和那家伙的交情有好到那个程度吗？",
            ["ContentFR"] = "Ce n’est pas que je sois contre... mais... On est si proches que ça, lui et nous ?",
            ["DialogueId"] = 12042104,
            ["GUID"] = "1E2569B0",
            ["NextDialogue"] = 12042105,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120421/1E2569B0",
            },
        [12042105] = {
            ["Content"] = "只是曾经在听鸦原见过一面而已，虽然他说话挺有意思的，但好像还犯不着为他这么冒险吧……",
            ["ContentFR"] = "On ne l’a croisé qu’une seule fois à la Plaine des Corbeaux. D’accord, il est intéressant... mais risquer gros pour lui ?",
            ["DialogueId"] = 12042105,
            ["GUID"] = "1E2569DA",
            ["NextDialogue"] = 12042106,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120421/1E2569DA",
            },
        [12042106] = {
            ["Content"] = "刚刚看到那张画像的时候，我的脑海中突然闪过一个念头：我们曾经和他在某处，一起商量过某些非常重要的事情。但更具体的，我都想不起来了。",
            ["ContentFR"] = "Quand j’ai vu son portrait... une pensée m’a traversé l’esprit. Comme si, à un moment, nous nous étions réunis avec lui quelque part... pour discuter d’une affaire capitale. Mais impossible de me rappeler quoi que ce soit de précis.",
            ["DialogueId"] = 12042106,
            ["GUID"] = "1E256A04",
            ["NextDialogue"] = 12042107,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120421/1E256A04",
            },
        [12042107] = {
            ["Content"] = "白，从今天早上开始，我一直若隐若现地觉得不太对劲，我不知道你有没有相同的感受……好像有什么很紧迫的事情被我们忘在脑后了。",
            ["ContentFR"] = "Depuis ce matin, j’ai ce sentiment diffus que quelque chose cloche. Comme si une urgence nous échappait... comme si nous avions laissé derrière nous quelque chose d’essentiel.",
            ["DialogueId"] = 12042107,
            ["GUID"] = "1E256A2E",
            ["NextDialogue"] = 12042108,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120421/1E256A2E",
            },
        [12042108] = {
            ["Content"] = "我一直说不出哪里不对劲，直到刚刚看到那张画像为止。我有一种预感，找到他可能是解开这个谜题的关键。",
            ["ContentFR"] = "Je n’arrivais pas à mettre le doigt sur ce malaise... jusqu’au moment où j’ai vu son portrait. J’ai alors eu l’intuition que le retrouver pourrait être la clé pour comprendre ce qui nous échappe.",
            ["DialogueId"] = 12042108,
            ["GUID"] = "1E256A58",
            ["NextDialogue"] = 12042109,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120421/1E256A58",
            },
        [12042109] = {
            ["Content"] = "不、对、对对、劲劲劲劲劲？",
            ["ContentFR"] = "Quelque chose... ne va—va—va—pas... ?",
            ["DialogueId"] = 12042109,
            ["GUID"] = "1E256A82",
            ["NextDialogue"] = 12042110,
            ["SnapShot"] = "ELECTRIC",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120421/1E256A82",
            },
        [12042110] = {
            ["Content"] = "白，你刚才……",
            ["ContentFR"] = "Snow ? À l’instant, tu...",
            ["DialogueId"] = 12042110,
            ["GUID"] = "1E256AAC",
            ["NextDialogue"] = 12042111,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120421/1E256AAC",
            },
        [12042111] = {
            ["Content"] = "我刚刚？哎，我，我怎么会那样子说话？！",
            ["ContentFR"] = "Moi ? Q-Qu’est-ce que j’ai fait ? Pourquoi je parlais comme ça ?!",
            ["DialogueId"] = 12042111,
            ["GUID"] = "1E256AD6",
            ["NextDialogue"] = 12042112,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120421/1E256AD6",
            },
        [12042112] = {
            ["Content"] = "难道说，真像小仆从你说的那样，我们身上发生了什么奇怪的事情？这该不会是中邪，或者被诅咒了吧？！",
            ["ContentFR"] = "Tu crois que... comme tu l’as dit... il nous est arrivé quelque chose ? On ne serait pas ensorcelés ? Ou maudits ?!",
            ["DialogueId"] = 12042112,
            ["GUID"] = "1E256B00",
            ["NextDialogue"] = 12042113,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120421/1E256B00",
            },
        [12042113] = {
            ["Content"] = "冒险小说里就有那种躲在沼泽里，发出阴森笑声的老巫婆，会一边搅着咕噜咕噜冒泡的药水，一边给别人下诅咒。难不成华胥也有？",
            ["ContentFR"] = "Dans les romans d’aventure, il y a toujours une vieille sorcière qui se cache dans un marais, à ricaner devant son chaudron en lançant des malédictions... Tu crois que Huaxu en cache une aussi ?!",
            ["DialogueId"] = 12042113,
            ["GUID"] = "1E256B2A",
            ["NextDialogue"] = 12042114,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120421/1E256B2A",
            },
        [12042114] = {
            ["Content"] = "虽然冒险小说大部分都是杜撰……不过这种可能性倒也不能排除。",
            ["ContentFR"] = "La plupart de ces histoires sont inventées... Mais je ne peux pas exclure cette possibilité.",
            ["DialogueId"] = 12042114,
            ["GUID"] = "1E256B54",
            ["NextDialogue"] = 12042115,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120421/1E256B54",
            },
        [12042115] = {
            ["Content"] = "哇，想想就后背发凉……！那，小仆从，我支持你的决定！",
            ["ContentFR"] = "Brr... rien que d’y penser, j’en ai des frissons ! D’accord. Petit larbin, je te suis.",
            ["DialogueId"] = 12042115,
            ["GUID"] = "1E256B7E",
            ["NextDialogue"] = 12042116,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120421/1E256B7E",
            },
        [12042116] = {
            ["Content"] = "海伯利亚的军团我们都交手过好几次了，这样想想，到执律阁顶兜一圈，好像也不是什么大不了的事情嘛。",
            ["ContentFR"] = "On s’est déjà frottés à la Légion Hyperboréenne plus d’une fois. Alors monter au sommet du Pavillon de l’Arbitrage ? Ce n’est pas ça qui va nous arrêter.",
            ["DialogueId"] = 12042116,
            ["GUID"] = "1E256BA8",
            ["NextDialogue"] = 12042117,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120421/1E256BA8",
            },
        [12042117] = {
            ["Content"] = "有信心是好事……不过我们要去的毕竟是华胥的重地，还是谨慎对待为好。",
            ["ContentFR"] = "Ton assurance fait plaisir à entendre... Mais nous allons pénétrer dans le cœur même de Huaxu. Restons prudents.",
            ["DialogueId"] = 12042117,
            ["GUID"] = "1E256BD2",
            ["NextDialogue"] = 12042118,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120421/1E256BD2",
            },
        [12042118] = {
            ["Content"] = "唔……你说得对！榜文上写了“明日午时辩法”。我们在那之前做好准备，再进去吧。",
            ["ContentFR"] = "Mmh... Tu as raison ! L’avis parle du « Rite de Délibération à midi demain ». Préparons-nous d’abord. Ensuite, nous monterons.",
            ["DialogueId"] = 12042118,
            ["GUID"] = "1E256BFC",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120421/1E256BFC",
            },
        [12042201] = {
            ["Content"] = "（即将开始连续剧情内容，建议做好充分准备后进行体验。）",
            ["ContentFR"] = "(Une longue séquence d’histoire va commencer. Assurez-vous d’avoir le temps nécessaire avant de poursuivre.)",
            ["DialogueId"] = 12042201,
            ["GUID"] = "1E25799A",
            ["SpeakNpcId"] = 0,
            ["VoiceName"] = "voice/$Locale$/story/1204/120422/1E25799A",
            },
        [12042202] = {
            ["Content"] = "准备好了",
            ["ContentFR"] = "<I>Je suis prêt.</>",
            ["DialogueId"] = 12042202,
            ["GUID"] = "1E2579C4",
            },
        [12042203] = {
            ["Content"] = "再准备一下",
            ["ContentFR"] = "<I>Encore un instant.</>",
            ["DialogueId"] = 12042203,
            ["GUID"] = "1E2579EE",
            },
        [12042301] = {
            ["Content"] = "烦请两位出示通行信物。",
            ["ContentFR"] = "Veuillez présenter votre gage d’accès.",
            ["DialogueId"] = 12042301,
            ["GUID"] = "1E258A02",
            ["SpeakNpcId"] = 240015,
            ["VoiceName"] = "voice/$Locale$/story/1204/120423/1E258A02",
            },
        [12042401] = {
            ["Content"] = "您好，我们是替止流掌柜来递交奉香大典所需的器具的。",
            ["ContentFR"] = "Bonjour. Nous venons remettre, au nom de la Patronne Zhiliu, les objets nécessaires à la Cérémonie de l’Encens.",
            ["DialogueId"] = 12042401,
            ["GUID"] = "1E259A6A",
            ["NextDialogue"] = 12042402,
            ["RelatedWikiId"] = {
                [1] = 405014,
                [2] = 407009,
                [3] = 407013,
                },
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120424/1E259A6A",
            },
        [12042402] = {
            ["Content"] = "奉香炉、皓烟香、绸布……清点完毕了，与清单上一致，多谢。辛苦你们跑这一趟了。",
            ["ContentFR"] = "Brûle-encens, Encens de Fumée Argentée, soieries... Tout est conforme à l’inventaire. Merci d’avoir effectué la livraison.",
            ["DialogueId"] = 12042402,
            ["GUID"] = "1E259A94",
            ["NextDialogue"] = 12042403,
            ["SpeakNpcId"] = 240016,
            ["VoiceName"] = "voice/$Locale$/story/1204/120424/1E259A94",
            },
        [12042403] = {
            ["Content"] = "姐姐，我们难得来一趟，可以在这四处逛逛吗？",
            ["ContentFR"] = "Puisque nous sommes là... pourrions-nous visiter un peu ?",
            ["DialogueId"] = 12042403,
            ["GUID"] = "1E259ABE",
            ["NextDialogue"] = 12042404,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120424/1E259ABE",
            },
        [12042404] = {
            ["Content"] = "两位来得不巧。今日执律阁顶从午时起封闭，期间一切无关人员禁止出入。",
            ["ContentFR"] = "Vous tombez mal. À compter de midi, le sommet du Pavillon est fermé. Toute personne non autorisée est strictement interdite d’accès.",
            ["DialogueId"] = 12042404,
            ["GUID"] = "1E259AE8",
            ["NextDialogue"] = 12042405,
            ["SpeakNpcId"] = 240016,
            ["VoiceName"] = "voice/$Locale$/story/1204/120424/1E259AE8",
            },
        [12042405] = {
            ["Content"] = "不过……远道而来即为客。大厅之中你们可以随意走动参观，只要不上两侧的楼梯便好。",
            ["ContentFR"] = "Toutefois, en tant que visiteurs, vous pouvez circuler librement dans le hall principal — à condition de ne pas emprunter les escaliers latéraux.",
            ["DialogueId"] = 12042405,
            ["GUID"] = "1E259B12",
            ["NextDialogue"] = 12042406,
            ["SpeakNpcId"] = 240016,
            ["VoiceName"] = "voice/$Locale$/story/1204/120424/1E259B12",
            },
        [12042406] = {
            ["Content"] = "嗯，我们明白啦！谢谢姐姐！",
            ["ContentFR"] = "Compris ! Merci !",
            ["DialogueId"] = 12042406,
            ["GUID"] = "1E259B3C",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120424/1E259B3C",
            },
        [12042501] = {
            ["Content"] = "前方禁地，阁下请止步。",
            ["ContentFR"] = "Zone interdite. Veuillez faire demi-tour.",
            ["DialogueId"] = 12042501,
            ["GUID"] = "1E25AAD2",
            ["SpeakNpcId"] = 240017,
            ["VoiceName"] = "voice/$Locale$/story/1204/120425/1E25AAD2",
            },
        [12042601] = {
            ["Content"] = "怎么办，小仆从，完全找不到突破口……",
            ["ContentFR"] = "Qu’est-ce qu’on fait ? Il n’y a aucune ouverture...",
            ["DialogueId"] = 12042601,
            ["GUID"] = "1E25BB3A",
            ["NextDialogue"] = 12042602,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120426/1E25BB3A",
            },
        [12042602] = {
            ["Content"] = "这里也太空旷了，那些守卫一眼就能看穿我们的小动作，都不好偷偷溜进去了。",
            ["ContentFR"] = "C’est trop dégagé ici. Au moindre geste suspect, ils nous repèrent. Impossible de passer en douce...",
            ["DialogueId"] = 12042602,
            ["GUID"] = "1E25BB64",
            ["NextDialogue"] = 12042603,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120426/1E25BB64",
            },
        [12042603] = {
            ["Content"] = "哔——哔——",
            ["ContentFR"] = "<I>BIP—— BIP——</>",
            ["DialogueId"] = 12042603,
            ["GUID"] = "1E25BB8E",
            ["NextDialogue"] = 12042604,
            ["SpeakNpcId"] = 240020,
            ["VoiceName"] = "voice/$Locale$/story/1204/120426/1E25BB8E",
            },
        [12042604] = {
            ["Content"] = "哪儿来的声音？",
            ["ContentFR"] = "C’était quoi, ça ?",
            ["DialogueId"] = 12042604,
            ["GUID"] = "1E25BBB8",
            ["NextDialogue"] = 12042605,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120426/1E25BBB8",
            },
        [12042605] = {
            ["Content"] = "薛兄，那机傀从早上起便频频无端作响，怕是损耗已久，该修理了。",
            ["ContentFR"] = "Cette méchapoupée fait du bruit sans raison depuis ce matin. Elle doit être bien usée.",
            ["DialogueId"] = 12042605,
            ["GUID"] = "1E25BBE2",
            ["NextDialogue"] = 12042606,
            ["SpeakNpcId"] = 240018,
            ["VoiceName"] = "voice/$Locale$/story/1204/120426/1E25BBE2",
            },
        [12042606] = {
            ["Content"] = "嗯。今日轮值结束后，顺手将其交给匠矩阁吧。",
            ["ContentFR"] = "À la fin de la relève, remettons-la au Pavillon des Artisans.",
            ["DialogueId"] = 12042606,
            ["GUID"] = "1E25BC0C",
            ["NextDialogue"] = 12042607,
            ["SpeakNpcId"] = 240019,
            ["VoiceName"] = "voice/$Locale$/story/1204/120426/1E25BC0C",
            },
        [12042607] = {
            ["Content"] = "……白，我有想法了。",
            ["ContentFR"] = "... Snow. J’ai une idée.",
            ["DialogueId"] = 12042607,
            ["GUID"] = "1E25BC36",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120426/1E25BC36",
            },
        [12042701] = {
            ["Content"] = "哔——哔——枢轮啮日月，铁骨镇山河——",
            ["ContentFR"] = "<I>BIP— BIP— !</> Roue maîtresse dévorant soleil et lune, charpente d’acier gardienne des monts et des fleuves— !",
            ["DialogueId"] = 12042701,
            ["GUID"] = "1E25CBA2",
            ["NextDialogue"] = 12042702,
            ["SpeakNpcId"] = 240020,
            ["VoiceName"] = "voice/$Locale$/story/1204/120427/1E25CBA2",
            },
        [12042702] = {
            ["Content"] = "……薛兄，机傀竟自己启动了！",
            ["ContentFR"] = "Quoi ?! Elle s’est activée toute seule !",
            ["DialogueId"] = 12042702,
            ["GUID"] = "1E25CBCC",
            ["NextDialogue"] = 12042703,
            ["SpeakNpcId"] = 240018,
            ["VoiceName"] = "voice/$Locale$/story/1204/120427/1E25CBCC",
            },
        [12042703] = {
            ["Content"] = "哔——犯界者，齑灭于此——",
            ["ContentFR"] = "<I>BIP— !</> Les transgresseurs seront réduits en poussière !",
            ["DialogueId"] = 12042703,
            ["GUID"] = "1E25CBF6",
            ["NextDialogue"] = 12042704,
            ["SpeakNpcId"] = 240020,
            ["VoiceName"] = "voice/$Locale$/story/1204/120427/1E25CBF6",
            },
        [12042704] = {
            ["Content"] = "糟糕！看它前进的方向，执律阁的内饰都要被殃及！赶紧去阻止它！",
            ["ContentFR"] = "Elle se dirige vers l’intérieur — elle va ravager le Pavillon ! Vite !",
            ["DialogueId"] = 12042704,
            ["GUID"] = "1E25CC20",
            ["NextDialogue"] = 12042705,
            ["SpeakNpcId"] = 240019,
            ["VoiceName"] = "voice/$Locale$/story/1204/120427/1E25CC20",
            },
        [12042705] = {
            ["Content"] = "他们的注意力被吸引走了！小仆从，就趁现在！",
            ["ContentFR"] = "Ils ont mordu à l’hameçon ! Petit larbin, maintenant !",
            ["DialogueId"] = 12042705,
            ["GUID"] = "1E25CC4A",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120427/1E25CC4A",
            },
        [12042801] = {
            ["Content"] = "白龙神君，要见上你一面可真是费劲啊……你给我听好了，今天我来这里，是为了——",
            ["ContentFR"] = "Seigneur Dragon d’Argent... Il m’aura fallu du temps pour t’obtenir face à face. Alors écoute bien. Si je suis venu aujourd’hui, c’est pour—",
            ["DialogueId"] = 12042801,
            ["GUID"] = "1E25DC0A",
            ["NextDialogue"] = 12042802,
            ["RelatedWikiId"] = {
                [1] = 203007,
                [2] = 303008,
                [3] = 407009,
                [4] = 407013,
                },
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120428/1E25DC0A",
            },
        [12042802] = {
            ["Content"] = "耻笑你。",
            ["ContentFR"] = "Me moquer de toi.",
            ["DialogueId"] = 12042802,
            ["GUID"] = "1E25DC34",
            ["NextDialogue"] = 12042803,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120428/1E25DC34",
            },
        [12042803] = {
            ["Content"] = "我笑你自蔽双眼，但见那匪徒施暴无辜者，竟不能即刻阻止，枉受众生供奉。",
            ["ContentFR"] = "Je me moque de ton regard voilé — des brigands qui frappent les innocents sous ton ciel, et toi qui ne les arrêtes pas.",
            ["DialogueId"] = 12042803,
            ["GUID"] = "1E25DC5E",
            ["NextDialogue"] = 12042804,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120428/1E25DC5E",
            },
        [12042804] = {
            ["Content"] = "我笑你好歹不分，有侠士杀贼寇为民除害，却判其杀生之罪，谈何正义之名？",
            ["ContentFR"] = "Je me moque de ta justice renversée —  un homme abat des bandits pour sauver le peuple, et tu le condamnes pour meurtre. Voilà donc ton équité ?",
            ["DialogueId"] = 12042804,
            ["GUID"] = "1E25DC88",
            ["NextDialogue"] = 12042805,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120428/1E25DC88",
            },
        [12042805] = {
            ["Content"] = "我刻舟自习武以来，行侠仗义，惩奸除恶，从未将剑尖对准过一个好人。却因制止一起强盗路劫，日日受狴犴追猎不休。",
            ["ContentFR"] = "Depuis que j’ai appris à manier l’épée, j’ai puni les criminels, protégé les faibles. Jamais ma lame ne s’est tournée vers un innocent. Et pourtant, pour avoir empêché un simple pillage, tes Bi’an me traquent jour et nuit.",
            ["DialogueId"] = 12042805,
            ["GUID"] = "1E25DCB2",
            ["NextDialogue"] = 12042806,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120428/1E25DCB2",
            },
        [12042806] = {
            ["Content"] = "伸张正义，究竟何罪之有？",
            ["ContentFR"] = "Dis-moi — en quoi défendre le faible est-il un crime ?",
            ["DialogueId"] = 12042806,
            ["GUID"] = "1E25DCDC",
            ["NextDialogue"] = 12042807,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120428/1E25DCDC",
            },
        [12042807] = {
            ["Content"] = "尔等口口声声为伸张正义，然私欲邪，大义邪？凡人行事，只在一念之差。",
            ["ContentFR"] = "Vous invoquez la justice... mais est-elle née d’un cœur pur, ou d’un désir déguisé ? Les mortels agissent en un battement de pensée.",
            ["DialogueId"] = 12042807,
            ["GUID"] = "1E25DD06",
            ["NextDialogue"] = 12042808,
            ["SpeakNpcId"] = 240024,
            ["VoiceName"] = "voice/$Locale$/story/1204/120428/1E25DD06",
            },
        [12042808] = {
            ["Content"] = "以心定法，则纲常崩毁，国将不国。",
            ["ContentFR"] = "Si la Loi se plie aux émotions humaines, l’ordre s’effondre. Les royaumes périssent.",
            ["DialogueId"] = 12042808,
            ["GUID"] = "1E25DD30",
            ["NextDialogue"] = 12042809,
            ["SpeakNpcId"] = 240024,
            ["VoiceName"] = "voice/$Locale$/story/1204/120428/1E25DD30",
            },
        [12042809] = {
            ["Content"] = "罪愆自有天命律法定夺。以凡人之身生杀予夺，是为越俎代庖。",
            ["ContentFR"] = "C’est à la Loi du Ciel de juger la faute. Un mortel qui décide de la vie et de la mort outrepasse sa condition.",
            ["DialogueId"] = 12042809,
            ["GUID"] = "1E25DD5A",
            ["NextDialogue"] = 12042810,
            ["SpeakNpcId"] = 240024,
            ["VoiceName"] = "voice/$Locale$/story/1204/120428/1E25DD5A",
            },
        [12042810] = {
            ["Content"] = "呵……意思是只有你认可的才是正义呗？我还以为你们神仙能有什么新鲜话，结果还是香官老儿们的陈词滥调，也罢。我自己的事先放一边。",
            ["ContentFR"] = "Ah... Donc seule la justice que tu approuves mérite ce nom ? Je pensais qu’un dieu aurait mieux à offrir que les sermons poussiéreux des vieux officiants de l’encens. Très bien. Laissons mon cas de côté.",
            ["DialogueId"] = 12042810,
            ["GUID"] = "1E25DD84",
            ["NextDialogue"] = 12042811,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120428/1E25DD84",
            },
        [12042811] = {
            ["Content"] = "你让应天尉执你的法，可曾问过他们的意见？我那师兄煜明，为何要被你日夜役使，满手罪孽，不得解脱？",
            ["ContentFR"] = "Quand tu ordonnes aux Magistrats de Yingtian d’appliquer ta Loi... leur as-tu seulement demandé leur avis ? Mon frère d’armes, Yuming — pourquoi doit-il servir sans repos, les mains couvertes de sang, sans jamais connaître la délivrance ?",
            ["DialogueId"] = 12042811,
            ["GUID"] = "1E25DDAE",
            ["NextDialogue"] = 12042812,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120428/1E25DDAE",
            },
        [12042812] = {
            ["Content"] = "大风九章之下，又为何常有不平之事？该死的人不死，正直之人却枉死！白龙，但凡你愿低头看看这世间的荒诞、错乱，便知我今日辩法为何！",
            ["ContentFR"] = "Sous tes Neuf Chapitres de Dafeng, pourquoi l’injustice prospère-t-elle encore ? Les coupables vivent. Les justes tombent. Seigneur Dragon d’Argent — si tu daignais seulement regarder ce monde tel qu’il est, tu comprendrais pourquoi je me tiens ici aujourd’hui.",
            ["DialogueId"] = 12042812,
            ["GUID"] = "1E25DDD8",
            ["NextDialogue"] = 12042813,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120428/1E25DDD8",
            },
        [12042813] = {
            ["Content"] = "不过是妄议天道，老生常谈。",
            ["ContentFR"] = "Vaines élucubrations sur la Voie Céleste. Une rengaine depuis longtemps ressassée.",
            ["DialogueId"] = 12042813,
            ["GUID"] = "1E25DE02",
            ["NextDialogue"] = 12042814,
            ["SpeakNpcId"] = 240024,
            ["VoiceName"] = "voice/$Locale$/story/1204/120428/1E25DE02",
            },
        [12042814] = {
            ["Content"] = "凡人为心所累，受情所扰。法却清正自明，如昭昭天理。",
            ["ContentFR"] = "Les mortels sont liés au désir, aveuglés par l’attachement. La Loi, elle, demeure claire comme le firmament.",
            ["DialogueId"] = 12042814,
            ["GUID"] = "1E25DE2C",
            ["NextDialogue"] = 12042815,
            ["SpeakNpcId"] = 240024,
            ["VoiceName"] = "voice/$Locale$/story/1204/120428/1E25DE2C",
            },
        [12042815] = {
            ["Content"] = "法无仁心，岂容怨戾撼分毫？",
            ["ContentFR"] = "La Loi n’a pas de cœur. Elle ne cède ni à la rancœur, ni à la colère.",
            ["DialogueId"] = 12042815,
            ["GUID"] = "1E25DE56",
            ["NextDialogue"] = 12042816,
            ["SpeakNpcId"] = 240024,
            ["VoiceName"] = "voice/$Locale$/story/1204/120428/1E25DE56",
            },
        [12042816] = {
            ["Content"] = "哈哈……好一个法无仁心。既然如此，也没什么好说的了。",
            ["ContentFR"] = "Haha... « La Loi n’a pas de cœur. » Alors il n’y a plus rien à dire.",
            ["DialogueId"] = 12042816,
            ["GUID"] = "1E25DE80",
            ["NextDialogue"] = 12042817,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120428/1E25DE80",
            },
        [12042817] = {
            ["Content"] = "你这天道教我乞求天降正义，教我做羔羊，做胆小鬼，做摇尾乞怜的狗。很可惜，我不愿。",
            ["ContentFR"] = "Ta Loi voudrait que je supplie le Ciel, que je vive comme un agneau docile, comme un chien implorant une caresse. Je refuse.",
            ["DialogueId"] = 12042817,
            ["GUID"] = "1E25DEAA",
            ["NextDialogue"] = 12042818,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120428/1E25DEAA",
            },
        [12042818] = {
            ["Content"] = "因为爹娘和师父从小便要我挺直脊梁，做一个堂堂正正的人！",
            ["ContentFR"] = "Mes parents. Mon maître. M’ont appris à me tenir droit. À vivre en homme digne.",
            ["DialogueId"] = 12042818,
            ["GUID"] = "1E25DED4",
            ["NextDialogue"] = 12042819,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120428/1E25DED4",
            },
        [12042819] = {
            ["Content"] = "听了你的亲口回答，也不枉我走上这一回了。",
            ["ContentFR"] = "J’ai entendu ta réponse. Cela me suffit.",
            ["DialogueId"] = 12042819,
            ["GUID"] = "1E25DEFE",
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120428/1E25DEFE",
            },
        [12042901] = {
            ["Content"] = "呼……暂时安全了……",
            ["ContentFR"] = "<I>Pfiou</>... On dirait qu’on est tranquilles... pour l’instant.",
            ["DialogueId"] = 12042901,
            ["GUID"] = "1E25EC72",
            ["NextDialogue"] = 12042902,
            ["RelatedWikiId"] = {
                [1] = 203007,
                [2] = 203008,
                [3] = 303012,
                },
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120429/1E25EC72",
            },
        [12042902] = {
            ["Content"] = "多谢阁下，带我们逃出生天！",
            ["ContentFR"] = "Merci, l’ami — tu nous as tirés d’un sacré mauvais pas !",
            ["DialogueId"] = 12042902,
            ["GUID"] = "1E25EC9C",
            ["NextDialogue"] = 12042903,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120429/1E25EC9C",
            },
        [12042903] = {
            ["Content"] = "既然你帮了我们的忙，上次你遛着我和小仆从到处跑的事情，就不和你计较了。",
            ["ContentFR"] = "Bon... puisque tu nous as sauvés cette fois... je ne reviendrai pas sur le coup où tu nous as fait courir partout, moi et mon petit larbin.",
            ["DialogueId"] = 12042903,
            ["GUID"] = "1E25ECC6",
            ["NextDialogue"] = 12042904,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120429/1E25ECC6",
            },
        [12042904] = {
            ["Content"] = "嘻嘻……大梦谁先觉？平生我自知！不如逍遥～",
            ["ContentFR"] = "Héhé... Qui s’éveille du grand songe ? Moi seul me connais. Libre comme le vent... quelle douce errance~",
            ["DialogueId"] = 12042904,
            ["GUID"] = "1E25ECF0",
            ["NextDialogue"] = 12042905,
            ["SpeakNpcId"] = 240028,
            ["VoiceName"] = "voice/$Locale$/story/1204/120429/1E25ECF0",
            },
        [12042905] = {
            ["Content"] = "……哈哈，刚刚可真是好一出畅快淋漓的过招！不虚此行！",
            ["ContentFR"] = "Hahaha ! Voilà un échange comme je les aime ! Ça, c’était du combat ! Je ne suis pas venu pour rien !",
            ["DialogueId"] = 12042905,
            ["GUID"] = "1E25ED1A",
            ["NextDialogue"] = 12042906,
            ["RelatedWikiId"] = {
                [1] = 203007,
                [2] = 203008,
                [3] = 303012,
                },
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120429/1E25ED1A",
            },
        [12042906] = {
            ["Content"] = "以后说出去，我刻舟也是与神明交手，最后全身而退、毫发无伤的传奇人士了！",
            ["ContentFR"] = "D’ici peu, on racontera partout : « Kezhou — l’homme qui a croisé le fer avec un dieu... et en est ressorti intact ! » Avoue que ça en jette.",
            ["DialogueId"] = 12042906,
            ["GUID"] = "1E25ED44",
            ["NextDialogue"] = 12042907,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120429/1E25ED44",
            },
        [12042907] = {
            ["Content"] = "当然，都是承蒙你出手相助。救命之恩，刻舟定不相忘。",
            ["ContentFR"] = "Bon... c’est surtout grâce à toi. Tu m’as arraché des griffes du Ciel. Je n’oublierai pas.",
            ["DialogueId"] = 12042907,
            ["GUID"] = "1E25ED6E",
            ["NextDialogue"] = 12042908,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120429/1E25ED6E",
            },
        [12042908] = {
            ["Content"] = "喂喂，先别急着得意啊！到底都是怎么一回事？",
            ["ContentFR"] = "Hé hé ! Doucement avec les grands discours ! Explique plutôt ce qui vient de se passer !",
            ["DialogueId"] = 12042908,
            ["GUID"] = "1E25ED98",
            ["NextDialogue"] = 12042909,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120429/1E25ED98",
            },
        [12042909] = {
            ["Content"] = "上次见你，可没看出你是个重刑犯……你、你都干过什么坏事啊！糟了，我和小仆从会不会有危……",
            ["ContentFR"] = "La dernière fois qu’on t’a vu, t’avais pas l’air d’un criminel recherché... T’as fait quoi exactement ?! Attends — mon petit larbin et moi, on n’est pas en danger, au moins ?!",
            ["DialogueId"] = 12042909,
            ["GUID"] = "1E25EDC2",
            ["NextDialogue"] = 12042910,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120429/1E25EDC2",
            },
        [12042910] = {
            ["Content"] = "喂喂，你这话说的，像是我是什么大奸大恶之徒一样。咳……既然你好奇，那我再重新做个自我介绍吧。",
            ["ContentFR"] = "Oh là, oh là... tu me dépeins comme le pire des scélérats. Hum... puisque tu insistes, reprenons depuis le début.",
            ["DialogueId"] = 12042910,
            ["GUID"] = "1E25EDEC",
            ["NextDialogue"] = 12042911,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120429/1E25EDEC",
            },
        [12042911] = {
            ["Content"] = "拒不随波逐流，飘零世事之外，仅为心中一杆尺而行。以天为被，以地为席，仗剑日月间，专管不平事——华胥<H>飘零人</>，刻舟！怎么样，是不是很拉风？",
            ["ContentFR"] = "Je refuse de suivre le courant. Je marche à contre-courant, avec ma propre règle pour seule boussole. Le ciel pour toit, la terre pour lit, l’épée pour compagne. Je tranche l’injustice où je la trouve. Je suis Kezhou — un <H>Vagabond</> de Huaxu. Alors ? Avoue que ça a de l’allure.",
            ["DialogueId"] = 12042911,
            ["GUID"] = "1E25EE16",
            ["NextOptions"] = {
                [1] = 12042912,
                [2] = 12042913,
                },
            ["RelatedWikiId"] = {
                [1] = 103001,
                },
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120429/1E25EE16",
            },
        [12042912] = {
            ["Content"] = "听起来很帅气。",
            ["ContentFR"] = "<I>Ça sonne plutôt impressionnant.</>",
            ["DialogueId"] = 12042912,
            ["GUID"] = "1E25EE40",
            ["ImprPlusId"] = 1204,
            ["NextDialogue"] = 12042914,
            },
        [12042913] = {
            ["Content"] = "懂了，就是法外狂徒呗。",
            ["ContentFR"] = "<I>Donc... un hors-la-loi.</>",
            ["DialogueId"] = 12042913,
            ["GUID"] = "1E25EE6A",
            ["ImprPlusId"] = 1205,
            ["NextDialogue"] = 12042915,
            },
        [12042914] = {
            ["Content"] = "那是自然。那些神仙香官自己对不公之事视而不见，还不准别人伸张正义，实属瞎眼！但，他们不管的，我们飘零人管。",
            ["ContentFR"] = "Évidemment. Quand les dieux et leurs officiants détournent le regard, quelqu’un doit bien agir. Et s’ils ne le font pas... nous, les Vagabonds, le ferons.",
            ["DialogueId"] = 12042914,
            ["GUID"] = "1E25EE94",
            ["NextDialogue"] = 12042916,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120429/1E25EE94",
            },
        [12042915] = {
            ["Content"] = "话可不能这么说，有道是“侠以武犯禁”，要不是那些神仙香官自己对不公之事视而不见，还不准别人伸张正义，哪会有我们飘零人。",
            ["ContentFR"] = "Un peu réducteur. Comme on dit : le juste manie l’épée, quitte à bousculer quelques règles. Si les puissants faisaient leur travail, on n’aurait pas besoin d’exister.",
            ["DialogueId"] = 12042915,
            ["GUID"] = "1E25EEBE",
            ["NextDialogue"] = 12042916,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120429/1E25EEBE",
            },
        [12042916] = {
            ["Content"] = "停停停！知道你不是故意犯事的大坏蛋了。",
            ["ContentFR"] = "Coupez ! Coupez ! J’ai compris ! T’es pas un super-méchant, ça va !",
            ["DialogueId"] = 12042916,
            ["GUID"] = "1E25EEE8",
            ["NextDialogue"] = 12042917,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120429/1E25EEE8",
            },
        [12042917] = {
            ["Content"] = "哈哈，头一次遇到自我介绍比白还长的，魔王大人这下算是遇到对手了。",
            ["ContentFR"] = "C’est la première fois que j’entends une présentation plus longue que celle du Roi Démon. On dirait que tu as trouvé un rival.",
            ["DialogueId"] = 12042917,
            ["GUID"] = "1E25EF12",
            ["NextDialogue"] = 12042918,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120429/1E25EF12",
            },
        [12042918] = {
            ["Content"] = "这家伙准是吹牛！要是真身手这么好，怎么会被那些应天尉抓去……丢人！",
            ["ContentFR"] = "<I>Pff !</> Il bluffe, c’est tout ! Si t’étais si fort, comment les Magistrats de Yingtian ont pu t’attraper ? Ça sent la fanfaronnade !",
            ["DialogueId"] = 12042918,
            ["GUID"] = "1E25EF3C",
            ["NextDialogue"] = 12042919,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120429/1E25EF3C",
            },
        [12042919] = {
            ["Content"] = "你可别误会了，我刻舟是主动送上门的。不然，再给那些家伙八百年的功夫，他们也奈何不了我！",
            ["ContentFR"] = "M’attraper ? Je me suis livré moi-même. Donne-leur huit cents ans de plus, ils n’y arriveraient toujours pas.",
            ["DialogueId"] = 12042919,
            ["GUID"] = "1E25EF66",
            ["NextDialogue"] = 12042920,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120429/1E25EF66",
            },
        [12042920] = {
            ["Content"] = "主动送上门？就为了骂白龙神君一顿吗？",
            ["ContentFR"] = "Tu t’es livré... juste pour insulter le Seigneur Dragon d’Argent ?",
            ["DialogueId"] = 12042920,
            ["GUID"] = "1E25EF90",
            ["NextDialogue"] = 12042921,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120429/1E25EF90",
            },
        [12042921] = {
            ["Content"] = "怎么可能，你把我刻舟的头脑想得太简单了。",
            ["ContentFR"] = "Allons donc. Tu me sous-estimes.",
            ["DialogueId"] = 12042921,
            ["GUID"] = "1E25EFBA",
            ["NextDialogue"] = 12042922,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120429/1E25EFBA",
            },
        [12042922] = {
            ["Content"] = "你还有别的目的？",
            ["ContentFR"] = "Alors il y avait autre chose ?",
            ["DialogueId"] = 12042922,
            ["GUID"] = "1E25EFE4",
            ["NextDialogue"] = 12042923,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120429/1E25EFE4",
            },
        [12042923] = {
            ["Content"] = "当然是为了——揍它一顿了！",
            ["ContentFR"] = "Bien sûr. Je voulais lui en coller une.",
            ["DialogueId"] = 12042923,
            ["GUID"] = "1E25F00E",
            ["NextDialogue"] = 12042924,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120429/1E25F00E",
            },
        [12042924] = {
            ["Content"] = "…………",
            ["ContentFR"] = "...",
            ["DialogueId"] = 12042924,
            ["GUID"] = "1E25F038",
            ["NextDialogue"] = 12042925,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120429/1E25F038",
            },
        [12042925] = {
            ["Content"] = "这头脑也没复杂到哪去吧！",
            ["ContentFR"] = "Oh ça va, génie incompris ! On a vu plus élaboré comme plan !",
            ["DialogueId"] = 12042925,
            ["GUID"] = "1E25F062",
            ["NextDialogue"] = 12042926,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120429/1E25F062",
            },
        [12042926] = {
            ["Content"] = "上次烛阴祭坛一别后，我一个人回去越想越乱，完全理不出头绪。最后我灵光一现：山不来就我，我便去就山。",
            ["ContentFR"] = "Après notre séparation à l’Autel de Zhuyin, je suis rentré avec la tête en vrac. Impossible d’ordonner mes pensées. Puis j’ai compris : si la montagne ne vient pas à moi... j’irai à la montagne.",
            ["DialogueId"] = 12042926,
            ["GUID"] = "1E25F08C",
            ["NextDialogue"] = 12042927,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120429/1E25F08C",
            },
        [12042927] = {
            ["Content"] = "无论她想用烛阴搞出什么名堂，只要那白龙受创，狴犴和应天尉群龙无首，大风九章失去力量，一切问题岂不是迎刃而解了？",
            ["ContentFR"] = "Quoi que Zhiliu trame avec Zhuyin, si je blessais le Dragon d’Argent, les Bi’an et les Magistrats de Yingtian se retrouveraient sans chef, les Neuf Chapitres vacilleraient... Et peut-être que tout s’éclaircirait.",
            ["DialogueId"] = 12042927,
            ["GUID"] = "1E25F0B6",
            ["NextDialogue"] = 12042928,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120429/1E25F0B6",
            },
        [12042928] = {
            ["Content"] = "正好我瞧那白龙不顺眼很久了，那该出手就出手，大不了就是一死嘛！只是……咳，神明还是神明，虽然是个死脑筋，但厉害还是怪厉害的。",
            ["ContentFR"] = "Et puis, pour être franc, ça faisait longtemps que j’avais envie de lui en coller une. Au pire ? Je mourais. Les dieux restent des dieux... entêtés, mais puissants.",
            ["DialogueId"] = 12042928,
            ["GUID"] = "1E25F0E0",
            ["NextDialogue"] = 12042929,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120429/1E25F0E0",
            },
        [12042929] = {
            ["Content"] = "要不是方才{nickname}出手相助，那就二十年后又是一条好汉喽。",
            ["ContentFR"] = "Si tu n’étais pas intervenu, {nickname}, je serais déjà poussière.",
            ["DialogueId"] = 12042929,
            ["GUID"] = "1E25F10A",
            ["NextDialogue"] = 12042930,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120429/1E25F10A",
            },
        [12042930] = {
            ["Content"] = "原来你知道会死啊！你差点害死我们小仆从了！",
            ["ContentFR"] = "Donc tu savais que tu pouvais mourir ?! Tu as failli faire tuer mon petit larbin !",
            ["DialogueId"] = 12042930,
            ["GUID"] = "1E25F134",
            ["NextDialogue"] = 12042931,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120429/1E25F134",
            },
        [12042931] = {
            ["Content"] = "我也不知道你们会出现在那儿，抱歉啦，反正结果皆大欢喜不是？你们要还是生气，改天我拿我师父宝贝了几十年的佳酿赔罪。",
            ["ContentFR"] = "Je ne savais pas que vous seriez là. Désolé. Enfin... tout est bien qui finit bien, non ? Et si tu boudes encore, je t’apporterai une des bouteilles que mon maître garde précieusement depuis des décennies.",
            ["DialogueId"] = 12042931,
            ["GUID"] = "1E25F15E",
            ["NextDialogue"] = 12042932,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120429/1E25F15E",
            },
        [12042932] = {
            ["Content"] = "哼，水仙平原有的是佳酿，我才不稀罕！不过看在白捡了个大宝贝的份上，不生你气啦。",
            ["ContentFR"] = "<I>Pff !</> Aux Asphodèles, on a des crus cent fois meilleurs ! Je m’en fiche ! Mais... vu que j’ai récupéré un trésor au passage... je te pardonne.",
            ["DialogueId"] = 12042932,
            ["GUID"] = "1E25F188",
            ["NextDialogue"] = 12042933,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120429/1E25F188",
            },
        [12042933] = {
            ["Content"] = "“大宝贝”？",
            ["ContentFR"] = "Un trésor ?",
            ["DialogueId"] = 12042933,
            ["GUID"] = "1E25F1B2",
            ["NextDialogue"] = 12042934,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120429/1E25F1B2",
            },
        [12042934] = {
            ["Content"] = "展示均天玉律图标",
            ["ContentFR"] = "(Icône : Demi-fragment du Jade de l’Équilibre)",
            ["DialogueId"] = 12042934,
            ["GUID"] = "1E25F1DC",
            ["NextDialogue"] = 12042935,
            ["SpeakNpcId"] = 0,
            ["VoiceName"] = "voice/$Locale$/story/1204/120429/1E25F1DC",
            },
        [12042935] = {
            ["Content"] = "这是刚刚那白龙飞走时掉下来的！神明的东西，想来肯定是了不起的宝贝！",
            ["ContentFR"] = "Il est tombé quand le Dragon d’Argent s’est enfui ! Un objet divin — ça vaut forcément une fortune !",
            ["DialogueId"] = 12042935,
            ["GUID"] = "1E25F206",
            ["NextDialogue"] = 12042936,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120429/1E25F206",
            },
        [12042936] = {
            ["Content"] = "这……不就是半块玉佩吗，看着也没甚稀奇。不过既然是白龙的东西，说不定黑市的老爷子会喜欢。",
            ["ContentFR"] = "Hm... on dirait juste la moitié d’un pendentif en jade. Rien d’extraordinaire. Mais s’il vient du Dragon d’Argent... le vieux du marché noir pourrait être intéressé.",
            ["DialogueId"] = 12042936,
            ["GUID"] = "1E25F230",
            ["NextDialogue"] = 12042937,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120429/1E25F230",
            },
        [12042937] = {
            ["Content"] = "那我就收好，等卖一大笔钱，就给小仆从当路费啦。",
            ["ContentFR"] = "Alors je le garde ! On le vendra, et ça fera les frais de voyage de mon petit larbin !",
            ["DialogueId"] = 12042937,
            ["GUID"] = "1E25F25A",
            ["NextDialogue"] = 12042938,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120429/1E25F25A",
            },
        [12042938] = {
            ["Content"] = "说起来，{nickname}，你刚刚做了什么？那可是神啊，我拼尽全力也动不得他分毫。你是怎么把它击伤的？",
            ["ContentFR"] = "À propos, {nickname}... qu’est-ce que tu as fait là-haut ? C’est un dieu. J’ai tout donné — je n’ai pas réussi à l’égratigner. Comment tu l’as blessé ?",
            ["DialogueId"] = 12042938,
            ["GUID"] = "1E25F284",
            ["NextDialogue"] = 12042939,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120429/1E25F284",
            },
        [12042939] = {
            ["Content"] = "说实话，我也不知道。而且我觉得不太对劲。",
            ["ContentFR"] = "Honnêtement... je n’en sais rien. Et ça m’inquiète.",
            ["DialogueId"] = 12042939,
            ["GUID"] = "1E25F2AE",
            ["NextDialogue"] = 12042940,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120429/1E25F2AE",
            },
        [12042940] = {
            ["Content"] = "当时白龙打过来，我唯一能做的只有拼死抵抗。但……不知为什么，我感到一种力量不受控制地从我身体里倾泻出来。",
            ["ContentFR"] = "Quand il a attaqué, je n’ai fait que résister de toutes mes forces. Puis... une puissance s’est déversée hors de moi. Sans que je la contrôle.",
            ["DialogueId"] = 12042940,
            ["GUID"] = "1E25F2D8",
            ["NextDialogue"] = 12042941,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120429/1E25F2D8",
            },
        [12042941] = {
            ["Content"] = "回闪一下CG中的金钱迷卦",
            ["ContentFR"] = "(Flash du motif de divination dorée.)",
            ["DialogueId"] = 12042941,
            ["GUID"] = "1E25F302",
            ["NextDialogue"] = 12042942,
            ["SpeakNpcId"] = 0,
            ["VoiceName"] = "voice/$Locale$/story/1204/120429/1E25F302",
            },
        [12042942] = {
            ["Content"] = "就像是……被什么操控了一样。",
            ["ContentFR"] = "C’était comme si... quelque chose agissait à ma place.",
            ["DialogueId"] = 12042942,
            ["GUID"] = "1E25F32C",
            ["NextDialogue"] = 12042943,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120429/1E25F32C",
            },
        [12042943] = {
            ["Content"] = "竟有此般蹊跷……",
            ["ContentFR"] = "Voilà qui devient inquiétant...",
            ["DialogueId"] = 12042943,
            ["GUID"] = "1E25F356",
            ["NextDialogue"] = 12042944,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120429/1E25F356",
            },
        [12042944] = {
            ["Content"] = "……想不明白的事还有很多。刻舟，你是不是说过，我们“在烛阴祭坛商量过对策”？可是我一点也想不起来——我不记得和你在那里说过话。",
            ["ContentFR"] = "Et il y a autre chose. Tu as dit qu’on avait discuté d’un plan à l’Autel de Zhuyin. Je ne m’en souviens pas. Je ne me rappelle même pas t’y avoir parlé.",
            ["DialogueId"] = 12042944,
            ["GUID"] = "1E25F380",
            ["NextDialogue"] = 12042945,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120429/1E25F380",
            },
        [12042945] = {
            ["Content"] = "不会吧？这么重要的事情，你都不记得了？当时我们……",
            ["ContentFR"] = "Quoi ? Un truc aussi important, et tu as tout oublié ? À ce moment-là, on—",
            ["DialogueId"] = 12042945,
            ["GUID"] = "1E25F3AA",
            ["NextDialogue"] = 12042946,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120429/1E25F3AA",
            },
        [12042946] = {
            ["Content"] = "噤声，附近有脚步声——",
            ["ContentFR"] = "Silence. J’entends des pas.",
            ["DialogueId"] = 12042946,
            ["GUID"] = "1E25F3D4",
            ["NextDialogue"] = 12042947,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120429/1E25F3D4",
            },
        [12042947] = {
            ["Content"] = "……那边……明白……",
            ["ContentFR"] = "Par là... Bien compris...",
            ["DialogueId"] = 12042947,
            ["GUID"] = "1E25F3FE",
            ["NextDialogue"] = 12042948,
            ["SpeakNpcName"] = "UI_Npc_Name_XiaoYaoShengWenHao",
            ["VoiceName"] = "voice/$Locale$/story/1204/120429/1E25F3FE",
            },
        [12042948] = {
            ["Content"] = "不知来者何人。{nickname}，先找个角落躲藏起来，我们见机行事。",
            ["ContentFR"] = "Je ne sais pas qui approche. {nickname}, trouve un coin où te cacher. On observe... et on avise.",
            ["DialogueId"] = 12042948,
            ["GUID"] = "1E25F428",
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120429/1E25F428",
            },
        [12043001] = {
            ["Content"] = "……无由生本因大风九章倒转天地之法则而创生。您身为祝由，天然可以调动大风九章的力量。",
            ["ContentFR"] = "Les Wishen sont nés lorsque les Neuf Chapitres de Dafeng ont renversé l’ordre naturel du Ciel et de la Terre. En tant que praticienne du Zhuyou, vous pouvez, par nature, mobiliser la puissance des Neuf Chapitres.",
            ["DialogueId"] = 12043001,
            ["GUID"] = "1E25FCDA",
            ["NextDialogue"] = 12043003,
            ["RelatedWikiId"] = {
                [1] = 203007,
                [2] = 203006,
                [3] = 303012,
                },
            ["SpeakNpcId"] = 210040,
            ["VoiceName"] = "voice/$Locale$/story/1204/120430/1E25FCDA",
            },
        [12043002] = {
            ["Content"] = "只要算出正确的时日，于虞渊之底动用泽生之术，届时，您想见之故人自当应召而来——前提是，她的灵魂还尚存于世。",
            ["ContentFR"] = "Si vous calculez la date propice et accomplissez l’Art de Zesheng au fond de l’Abysse de Yu, alors l’être que vous souhaitez revoir répondra à votre appel — à condition que son âme demeure encore en ce monde.",
            ["DialogueId"] = 12043002,
            ["GUID"] = "1E25FD04",
            ["NextDialogue"] = 12043003,
            ["SpeakNpcId"] = 210040,
            ["VoiceName"] = "voice/$Locale$/story/1204/120430/1E25FD04",
            },
        [12043003] = {
            ["Content"] = "只是这其中的代价……",
            ["ContentFR"] = "Cependant... le prix à payer...",
            ["DialogueId"] = 12043003,
            ["GUID"] = "1E25FD2E",
            ["NextDialogue"] = 12043004,
            ["SpeakNpcId"] = 210040,
            ["VoiceName"] = "voice/$Locale$/story/1204/120430/1E25FD2E",
            },
        [12043004] = {
            ["Content"] = "我已明白，无需多言。如今终于有眉目了，实在是感激不尽。",
            ["ContentFR"] = "J’ai compris. Nul besoin d’en dire davantage. J’entrevois enfin une piste... je vous en suis reconnaissante.",
            ["DialogueId"] = 12043004,
            ["GUID"] = "1E25FD58",
            ["NextDialogue"] = 12043005,
            ["SpeakNpcId"] = 240002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120430/1E25FD58",
            },
        [12043005] = {
            ["Content"] = "……扶疏姐姐，是你！",
            ["ContentFR"] = "... Fushu ?!",
            ["DialogueId"] = 12043005,
            ["GUID"] = "1E25FD82",
            ["NextDialogue"] = 12043006,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120430/1E25FD82",
            },
        [12043006] = {
            ["Content"] = "咦？小白，你怎么在这里，又怎生弄得如此狼狈？",
            ["ContentFR"] = "Snow ? Que fais-tu ici... et dans un état pareil ?",
            ["DialogueId"] = 12043006,
            ["GUID"] = "1E25FDAC",
            ["NextDialogue"] = 12043007,
            ["SpeakNpcId"] = 240002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120430/1E25FDAC",
            },
        [12043007] = {
            ["Content"] = "警报解除。{nickname}，不用躲了，出来吧。",
            ["ContentFR"] = "C’est dégagé. {nickname}, tu peux sortir.",
            ["DialogueId"] = 12043007,
            ["GUID"] = "1E25FDD6",
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120430/1E25FDD6",
            },
        [12043101] = {
            ["Content"] = "……原来外面闹得沸沸扬扬的执律阁行刺案，竟是你们所为。",
            ["ContentFR"] = "... Ainsi donc, l’affaire d’attentat qui agite tout le Pavillon de l’Arbitrage... c’était vous.",
            ["DialogueId"] = 12043101,
            ["GUID"] = "1E260D42",
            ["NextDialogue"] = 12043102,
            ["SpeakNpcId"] = 240002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120431/1E260D42",
            },
        [12043102] = {
            ["Content"] = "前后的来龙去脉，可以与我讲讲吗？",
            ["ContentFR"] = "Pourriez-vous m’en exposer les tenants et aboutissants — depuis le commencement ?",
            ["DialogueId"] = 12043102,
            ["GUID"] = "1E260D6C",
            ["NextDialogue"] = 12043103,
            ["SpeakNpcId"] = 240002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120431/1E260D6C",
            },
        [12043103] = {
            ["Content"] = "这说来可就话长了，得从今天早上，我和小仆从帮止流姐姐去各个地方跑腿取东西讲起……",
            ["ContentFR"] = "Oh là là... c’est une longue histoire ! Tout a commencé ce matin, quand petit larbin et moi faisions des courses pour Zhiliu...",
            ["DialogueId"] = 12043103,
            ["GUID"] = "1E260D96",
            ["NextDialogue"] = 12043104,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120431/1E260D96",
            },
        [12043104] = {
            ["Content"] = "止流掌柜？&那个女人？！",
            ["ContentFR"] = "Zhiliu ? Cette femme ?!",
            ["DialogueId"] = 12043104,
            ["GUID"] = "1E260DC0",
            ["NextDialogue"] = 12043105,
            ["RelatedWikiId"] = {
                [1] = 203001,
                },
            ["SpeakNpcName"] = "UI_Npc_Name_FuShuKeZhou",
            ["VoiceName"] = "voice/$Locale$/story/1204/120431/1E260DC0",
            },
        [12043105] = {
            ["Content"] = "恕我冒昧，上次降服烛阴时，止流掌柜应当已经与你们反目了。难道在那之后还有什么我们所不知的内情吗？",
            ["ContentFR"] = "Pardonne ma franchise. Lors de la subjugation de Zhuyin, il me semblait que vous aviez rompu avec elle. Y aurait-il eu des développements dont nous n’aurions pas connaissance ?",
            ["DialogueId"] = 12043105,
            ["GUID"] = "1E260DEA",
            ["NextDialogue"] = 12043106,
            ["SpeakNpcId"] = 240002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120431/1E260DEA",
            },
        [12043106] = {
            ["Content"] = "反目……？",
            ["ContentFR"] = "Rompu... ?",
            ["DialogueId"] = 12043106,
            ["GUID"] = "1E260E14",
            ["NextDialogue"] = 12043107,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120431/1E260E14",
            },
        [12043107] = {
            ["Content"] = "<H>白龙神君</>的时代，该结束了。而我，将执起祂的权柄。",
            ["ContentFR"] = "L’ère du <H>Seigneur Dragon d’Argent</> doit prendre fin. Et moi... j’en saisirai l’autorité.",
            ["DialogueId"] = 12043107,
            ["GUID"] = "1E260E3E",
            ["NextDialogue"] = 12043108,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120431/1E260E3E",
            },
        [12043108] = {
            ["Content"] = "接下来，<W>忘记我，忘记刚才这里发生的一切对话</>，好吗？",
            ["ContentFR"] = "À présent... <W>oublie-moi. Oublie tout ce que nous nous sommes dit</>. D’accord ?",
            ["DialogueId"] = 12043108,
            ["GUID"] = "1E260E68",
            ["NextDialogue"] = 12043109,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120431/1E260E68",
            },
        [12043109] = {
            ["Content"] = "（随着记忆的复苏，一阵前所未有的剧烈疼痛如同海啸般扑来，淹没了你的思维。你的每一根神经末梢都在惊涛骇浪中叫嚣。）",
            ["ContentFR"] = "À mesure que les souvenirs refont surface, une douleur fulgurante vous submerge — comme une marée déchaînée qui engloutit votre esprit. Chaque nerf se tend, battu par la tempête.",
            ["DialogueId"] = 12043109,
            ["GUID"] = "1E260E92",
            ["NextDialogue"] = 12043110,
            ["SpeakNpcId"] = 0,
            ["VoiceName"] = "voice/$Locale$/story/1204/120431/1E260E92",
            },
        [12043110] = {
            ["Content"] = "……疼！",
            ["ContentFR"] = "... Aïe !",
            ["DialogueId"] = 12043110,
            ["GUID"] = "1E260EBC",
            ["NextDialogue"] = 12043111,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120431/1E260EBC",
            },
        [12043111] = {
            ["Content"] = "{nickname}，你怎么了？！你的脉象怎如此杂乱？",
            ["ContentFR"] = "{nickname} ?! Ton pouls... il est chaotique.",
            ["DialogueId"] = 12043111,
            ["GUID"] = "1E260EE6",
            ["NextDialogue"] = 12043112,
            ["SpeakNpcId"] = 240002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120431/1E260EE6",
            },
        [12043112] = {
            ["Content"] = "忍耐片刻，我来为你调理。",
            ["ContentFR"] = "Reste immobile. Je vais rétablir l’équilibre.",
            ["DialogueId"] = 12043112,
            ["GUID"] = "1E260F10",
            ["SpeakNpcId"] = 240002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120431/1E260F10",
            },
        [12043201] = {
            ["Content"] = "……你把我带到这里，又是想说什么？",
            ["ContentFR"] = "... Pourquoi m’avez-vous amené ici ? Qu’attendez-vous de moi ?",
            ["DialogueId"] = 12043201,
            ["GUID"] = "1E261DAA",
            ["NextDialogue"] = 12043202,
            ["RelatedWikiId"] = {
                [1] = 203001,
                },
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120432/1E261DAA",
            },
        [12043202] = {
            ["Content"] = "呵呵。先前应对烛阴时有些仓促了，我们还没有坐下来好好聊过。若是就结束在这里，我想，对于你我来说，都是一种遗憾。",
            ["ContentFR"] = "Héhé... Notre échange à l’autel fut... précipité. Nous n’avons pas pris le temps d’une véritable conversation. Il aurait été regrettable d’en rester là.",
            ["DialogueId"] = 12043202,
            ["GUID"] = "1E261DD4",
            ["NextDialogue"] = 12043203,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120432/1E261DD4",
            },
        [12043203] = {
            ["Content"] = "你强行带我到这里，一句“仓促”就可以敷衍了事吗？",
            ["ContentFR"] = "Vous m’avez enlevé contre mon gré — et vous osez qualifier cela de « précipité » ?",
            ["DialogueId"] = 12043203,
            ["GUID"] = "1E261DFE",
            ["NextDialogue"] = 12043204,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120432/1E261DFE",
            },
        [12043204] = {
            ["Content"] = "{nickname}，我理解你的心情。你完全有理由感到愤怒。",
            ["ContentFR"] = "{nickname}, je comprends ce que tu ressens. Ta colère est légitime.",
            ["DialogueId"] = 12043204,
            ["GUID"] = "1E261E28",
            ["NextDialogue"] = 12043205,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120432/1E261E28",
            },
        [12043205] = {
            ["Content"] = "既然你已经选择撕破了脸，这种客套话还是不必了。",
            ["ContentFR"] = "Inutile de feindre la courtoisie. Ce masque est tombé depuis longtemps.",
            ["DialogueId"] = 12043205,
            ["GUID"] = "1E261E52",
            ["NextDialogue"] = 12043206,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120432/1E261E52",
            },
        [12043206] = {
            ["Content"] = "止流掌柜，刚刚在祭坛顶端，你为什么要不顾我的反对，强行吸收烛阴的力量？你真的是想<H>成神</>吗？",
            ["ContentFR"] = "Dites-moi, Zhiliu — au sommet de l’autel, pourquoi avez-vous absorbé la puissance de Zhuyin malgré mon opposition ? Était-ce réellement pour <H>devenir une divinité</> ?",
            ["DialogueId"] = 12043206,
            ["GUID"] = "1E261E7C",
            ["NextDialogue"] = 12043207,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120432/1E261E7C",
            },
        [12043207] = {
            ["Content"] = "既然你已经得偿所愿，又为什么要把我关在这里？",
            ["ContentFR"] = "Et maintenant que vous avez obtenu ce que vous vouliez... pourquoi m’enfermer ici ?",
            ["DialogueId"] = 12043207,
            ["GUID"] = "1E261EA6",
            ["NextDialogue"] = 12043208,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120432/1E261EA6",
            },
        [12043208] = {
            ["Content"] = "呵呵……开场的寒暄就到此为止吧，我们该进入正题了。",
            ["ContentFR"] = "Héhé... Laissons les civilités. Entrons dans le vif du sujet.",
            ["DialogueId"] = 12043208,
            ["GUID"] = "1E261ED0",
            ["NextDialogue"] = 12043209,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120432/1E261ED0",
            },
        [12043209] = {
            ["Content"] = "……",
            ["ContentFR"] = "...",
            ["DialogueId"] = 12043209,
            ["GUID"] = "1E261EFA",
            ["NextDialogue"] = 12043210,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120432/1E261EFA",
            },
        [12043210] = {
            ["Content"] = "你所谓的“好好聊聊”，似乎并没有多少诚意。",
            ["ContentFR"] = "Votre « conversation » manque singulièrement de sincérité.",
            ["DialogueId"] = 12043210,
            ["GUID"] = "1E261F24",
            ["NextDialogue"] = 12043211,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120432/1E261F24",
            },
        [12043211] = {
            ["Content"] = "耐心，{nickname}——你的疑问，接下来我会向你一一解释。但在那之前，有一件更加重要的事情。",
            ["ContentFR"] = "Patience, {nickname}. Je répondrai à chacune de tes questions. Mais avant cela... il est un point plus crucial encore.",
            ["DialogueId"] = 12043211,
            ["GUID"] = "1E261F4E",
            ["NextDialogue"] = 12043212,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120432/1E261F4E",
            },
        [12043212] = {
            ["Content"] = "你知道吗？未来的走向，在卦象之中是早已谱写好的。这三起卦象，便是我为你揭示的未来。",
            ["ContentFR"] = "Sais-tu que l’avenir est déjà inscrit dans les hexagrammes ? Ces trois tirages... sont les futurs que je révèle pour toi.",
            ["DialogueId"] = 12043212,
            ["GUID"] = "1E261F78",
            ["NextDialogue"] = 12043213,
            ["RelatedWikiId"] = {
                [1] = 203001,
                },
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120432/1E261F78",
            },
        [12043213] = {
            ["Content"] = "第一起，乾之太过：亢龙有悔，过涉灭顶。",
            ["ContentFR"] = "Le premier : excès du Qian — le dragon trop élevé connaîtra le regret ; qui franchit la mesure se noie.",
            ["DialogueId"] = 12043213,
            ["GUID"] = "1E261FA2",
            ["NextDialogue"] = 12043214,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120432/1E261FA2",
            },
        [12043214] = {
            ["Content"] = "{nickname}，<H>你将会前往极天之巅，与华胥的至高存在交手，并最终生还。</>",
            ["ContentFR"] = "{nickname}, <H>tu graviras les cimes ultimes, affronteras l’entité suprême de Huaxu... et survivras.</>",
            ["DialogueId"] = 12043214,
            ["GUID"] = "1E261FCC",
            ["NextDialogue"] = 12043215,
            ["RelatedWikiId"] = {
                [1] = 401005,
                },
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120432/1E261FCC",
            },
        [12043215] = {
            ["Content"] = "我？至高存在？交手？",
            ["ContentFR"] = "Moi ? Affronter l’entité suprême de Huaxu ?",
            ["DialogueId"] = 12043215,
            ["GUID"] = "1E261FF6",
            ["NextDialogue"] = 12043216,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120432/1E261FF6",
            },
        [12043216] = {
            ["Content"] = "我有什么理由做这件事吗？",
            ["ContentFR"] = "Et pourquoi ferais-je cela ?",
            ["DialogueId"] = 12043216,
            ["GUID"] = "1E262020",
            ["NextDialogue"] = 12043217,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120432/1E262020",
            },
        [12043217] = {
            ["Content"] = "呵呵……{nickname}。这是注定会发生的事情，你很快就会明白了。",
            ["ContentFR"] = "Héhé... Parce que cela doit advenir. Tu comprendras bientôt.",
            ["DialogueId"] = 12043217,
            ["GUID"] = "1E26204A",
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120432/1E26204A",
            },
        [12043301] = {
            ["Content"] = "{nickname}，你现在感觉怎样了？",
            ["ContentFR"] = "Comment te sens-tu à présent, {nickname} ?",
            ["DialogueId"] = 12043301,
            ["GUID"] = "1E262E12",
            ["NextDialogue"] = 12043302,
            ["RelatedWikiId"] = {
                [1] = 203007,
                [2] = 203006,
                [3] = 203001,
                [4] = 401005,
                },
            ["SpeakNpcId"] = 240002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120433/1E262E12",
            },
        [12043302] = {
            ["Content"] = "我……想起来了。止流向我预言了三件将要发生的事情。",
            ["ContentFR"] = "Je... me souviens. Zhiliu m’a annoncé trois prophéties à venir.",
            ["DialogueId"] = 12043302,
            ["GUID"] = "1E262E3C",
            ["NextDialogue"] = 12043303,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120433/1E262E3C",
            },
        [12043303] = {
            ["Content"] = "其中第一件，就是我会在执律阁上与白龙神君交手。这样看来，交手时的力量失控，可能是止流动的手脚。",
            ["ContentFR"] = "La première : que j’affronterais le Seigneur Dragon d’Argent au sommet du Pavillon de l’Arbitrage. Alors... cette perte de contrôle... ce n’était peut-être pas moi. Elle a pu la provoquer.",
            ["DialogueId"] = 12043303,
            ["GUID"] = "1E262E66",
            ["NextDialogue"] = 12043304,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120433/1E262E66",
            },
        [12043304] = {
            ["Content"] = "你提到三件事情，那还有两件事是什么？",
            ["ContentFR"] = "Tu parlais de trois prophéties. Les deux autres ?",
            ["DialogueId"] = 12043304,
            ["GUID"] = "1E262E90",
            ["NextDialogue"] = 12043305,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120433/1E262E90",
            },
        [12043305] = {
            ["Content"] = "我不记得了。",
            ["ContentFR"] = "Je ne m’en souviens pas.",
            ["DialogueId"] = 12043305,
            ["GUID"] = "1E262EBA",
            ["NextDialogue"] = 12043306,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120433/1E262EBA",
            },
        [12043306] = {
            ["Content"] = "我唯一能确定的是，剩下两样“预言”尚未发生。并且，必须在它们成真之前尽快阻止。",
            ["ContentFR"] = "Tout ce que je sais... c’est qu’elles ne se sont pas encore produites. Et qu’il faut les empêcher avant qu’elles ne se réalisent.",
            ["DialogueId"] = 12043306,
            ["GUID"] = "1E262EE4",
            ["NextDialogue"] = 12043307,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120433/1E262EE4",
            },
        [12043307] = {
            ["Content"] = "我有一种预感，最后一件事，是我极度不愿意看到它实现的。它会带来非常糟糕的后果。",
            ["ContentFR"] = "J’ai un mauvais pressentiment. La dernière... je ne veux absolument pas qu’elle advienne. Ses conséquences seraient désastreuses.",
            ["DialogueId"] = 12043307,
            ["GUID"] = "1E262F0E",
            ["NextDialogue"] = 12043308,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120433/1E262F0E",
            },
        [12043308] = {
            ["Content"] = "……{nickname}，如果我没有猜错的话，你所说的“预言”，并非是真正意义上的预测未来。",
            ["ContentFR"] = "... {nickname}. Ce que tu appelles « prophétie » n’est pas une véritable vision du futur.",
            ["DialogueId"] = 12043308,
            ["GUID"] = "1E262F38",
            ["NextDialogue"] = 12043309,
            ["SpeakNpcId"] = 240002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120433/1E262F38",
            },
        [12043309] = {
            ["Content"] = "没有人能断言自己可以勘破命运。止流所作出的预言，其实是扎根于你意识深层的咒印。或者换言之，一种<W>催眠</>。",
            ["ContentFR"] = "Nul ne peut percer le destin avec certitude. Ce que Zhiliu a implanté en toi... s’apparente davantage à une marque scellée au plus profond de ta conscience. Autrement dit... une <W>hypnose</>.",
            ["DialogueId"] = 12043309,
            ["GUID"] = "1E262F62",
            ["NextDialogue"] = 12043310,
            ["SpeakNpcId"] = 240002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120433/1E262F62",
            },
        [12043310] = {
            ["Content"] = "她用言语影响你对未来的认知，从而把命运拨弄到她期望的方向。你刚刚提到的“力量失控”就是很好的佐证。",
            ["ContentFR"] = "Par ses paroles, elle oriente ta perception de l’avenir. Et ce faisant, incline les événements dans la direction qu’elle désire. La perte de contrôle que tu décris... en est une preuve manifeste.",
            ["DialogueId"] = 12043310,
            ["GUID"] = "1E262F8C",
            ["NextDialogue"] = 12043311,
            ["SpeakNpcId"] = 240002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120433/1E262F8C",
            },
        [12043311] = {
            ["Content"] = "……原来是这样，难怪早上开始小仆从就感觉不对劲！",
            ["ContentFR"] = "... Voilà pourquoi le petit larbin se sentait étrange depuis ce matin !",
            ["DialogueId"] = 12043311,
            ["GUID"] = "1E262FB6",
            ["NextDialogue"] = 12043312,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120433/1E262FB6",
            },
        [12043312] = {
            ["Content"] = "扶疏，你有办法帮我找回记忆吗？",
            ["ContentFR"] = "Fushu... peux-tu m’aider à retrouver mes souvenirs ?",
            ["DialogueId"] = 12043312,
            ["GUID"] = "1E262FE0",
            ["NextDialogue"] = 12043313,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120433/1E262FE0",
            },
        [12043313] = {
            ["Content"] = "现在影响你的，并非是一种“疾病”，而是一种特殊的力量。",
            ["ContentFR"] = "Ce qui t’affecte n’est pas une maladie ordinaire. C’est une force singulière.",
            ["DialogueId"] = 12043313,
            ["GUID"] = "1E26300A",
            ["NextDialogue"] = 12043314,
            ["SpeakNpcId"] = 240002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120433/1E26300A",
            },
        [12043314] = {
            ["Content"] = "若只是通常疾病，我能将其渡之己身。但对于这种特殊的力量，我需要更多时间去寻找它的解法。可能短时间内无法对症治愈，抱歉。",
            ["ContentFR"] = "S’il s’agissait d’un mal commun, je pourrais le détourner sur moi-même. Mais une puissance de cette nature exige étude et discernement. Je crains de ne pouvoir te promettre une solution rapide.",
            ["DialogueId"] = 12043314,
            ["GUID"] = "1E263034",
            ["NextDialogue"] = 12043315,
            ["SpeakNpcId"] = 240002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120433/1E263034",
            },
        [12043315] = {
            ["Content"] = "要是这样的话，我们现在还在被全城通缉呢，一直待在这儿也不是个办法。{nickname}，和我回山外山吧。",
            ["ContentFR"] = "Dans ce cas, rester ici ne sert à rien — on est toujours recherchés dans toute la ville. {nickname}, viens avec moi aux Pics Extérieurs.",
            ["DialogueId"] = 12043315,
            ["GUID"] = "1E26305E",
            ["NextDialogue"] = 12043316,
            ["RelatedWikiId"] = {
                [1] = 408018,
                },
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120433/1E26305E",
            },
        [12043316] = {
            ["Content"] = "山外山？这又是什么地方？",
            ["ContentFR"] = "Les Pics Extérieurs ? C’est quoi encore ?",
            ["DialogueId"] = 12043316,
            ["GUID"] = "1E263088",
            ["NextDialogue"] = 12043317,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120433/1E263088",
            },
        [12043317] = {
            ["Content"] = "物不平则鸣。如今这世道，只是看上去平和，内里却是千疮百孔。人若是把这种种不公看在眼里，又怎会服气？",
            ["ContentFR"] = "Quand l’injustice résonne, quelqu’un finit toujours par répondre. Le monde paraît paisible... mais sous la surface, il est criblé de fissures. Ceux qui voient ces failles... comment pourraient-ils rester silencieux ?",
            ["DialogueId"] = 12043317,
            ["GUID"] = "1E2630B2",
            ["NextDialogue"] = 12043318,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120433/1E2630B2",
            },
        [12043318] = {
            ["Content"] = "有意对抗大风九章的能人异士，以飘零人的名号集结在了一起，山外山就是我们的秘密基地。信我，那里安全得很！",
            ["ContentFR"] = "Nous, les <H>Vagabonds</>, ceux qui refusent de plier devant les Neuf Chapitres, nous nous sommes rassemblés. Les Pics Extérieurs sont notre refuge secret. Crois-moi — on n’y craint rien.",
            ["DialogueId"] = 12043318,
            ["GUID"] = "1E2630DC",
            ["NextDialogue"] = 12043319,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120433/1E2630DC",
            },
        [12043319] = {
            ["Content"] = "对此我也有所耳闻。传言那山外山藏于云雾山隐之中，踪迹难寻。对于你们倒是个安全去处。",
            ["ContentFR"] = "J’en ai entendu parler. On dit qu’ils se cachent dans les montagnes voilées de brume, presque introuvables. Pour vous, ce serait en effet un abri sûr.",
            ["DialogueId"] = 12043319,
            ["GUID"] = "1E263106",
            ["NextDialogue"] = 12043320,
            ["SpeakNpcId"] = 240002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120433/1E263106",
            },
        [12043320] = {
            ["Content"] = "那就按你说的做吧。",
            ["ContentFR"] = "Alors allons-y.",
            ["DialogueId"] = 12043320,
            ["GUID"] = "1E263130",
            ["NextDialogue"] = 12043321,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120433/1E263130",
            },
        [12043321] = {
            ["Content"] = "一言为定！",
            ["ContentFR"] = "Marché conclu.",
            ["DialogueId"] = 12043321,
            ["GUID"] = "1E26315A",
            ["NextDialogue"] = 12043322,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120433/1E26315A",
            },
        [12043322] = {
            ["Content"] = "我随后先出去将追兵引开，为你们制造空隙。",
            ["ContentFR"] = "Je vais sortir le premier et détourner les poursuivants.",
            ["DialogueId"] = 12043322,
            ["GUID"] = "1E263184",
            ["NextDialogue"] = 12043323,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120433/1E263184",
            },
        [12043323] = {
            ["Content"] = "你们<H>去东郊野外，找到沿途的记号</>，一路跟着走。我待会儿给我姑奶奶苏乙传信，让她来接应你们。",
            ["ContentFR"] = "<H>Dirigez-vous vers les plaines à l’est et suivez les marques le long du chemin.</> Je transmettrai un message à ma grande-tante, Su Yi — elle viendra vous accueillir.",
            ["DialogueId"] = 12043323,
            ["GUID"] = "1E2631AE",
            ["NextDialogue"] = 12043324,
            ["RelatedWikiId"] = {
                [1] = 203009,
                },
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120433/1E2631AE",
            },
        [12043324] = {
            ["Content"] = "啊对了……我那姑奶奶特别讲规矩，接头暗号日日都要更换。你得一路沿着记号，在终点找到今日的暗号动作。你做了那个动作，才有人搭理你。",
            ["ContentFR"] = "Ah, oui — elle est pointilleuse. Le signal de reconnaissance change chaque jour. Suivez les marques jusqu’au bout et trouvez le signal du jour. Sans lui, personne ne vous adressera la parole.",
            ["DialogueId"] = 12043324,
            ["GUID"] = "1E2631D8",
            ["NextDialogue"] = 12043325,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120433/1E2631D8",
            },
        [12043325] = {
            ["Content"] = "哦还有，她脾气不太好，你见了她说话可要小心点，别把她惹火了。不过就算惹火了也有办法，只要使劲夸她几句，她就什么气都消了。",
            ["ContentFR"] = "Et... elle a le caractère un peu vif. Choisissez bien vos mots. Mais si vous la mettez en colère... flattez-la sans retenue. Ça marche à tous les coups.",
            ["DialogueId"] = 12043325,
            ["GUID"] = "1E263202",
            ["NextDialogue"] = 12043326,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120433/1E263202",
            },
        [12043326] = {
            ["Content"] = "要叮嘱的差不多就是这些，我且去了！我们在山外山见！",
            ["ContentFR"] = "Bon, je crois que c’est tout. On se retrouve aux Pics Extérieurs !",
            ["DialogueId"] = 12043326,
            ["GUID"] = "1E26322C",
            ["NextDialogue"] = 12043327,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120433/1E26322C",
            },
        }
  end },
  { MinKey = 12043327, MaxKey = 12044312, Loader = function()
      return {
        [12043327] = {
            ["Content"] = "小仆从，等我们准备好，也尽快出发吧！",
            ["ContentFR"] = "Petit larbin, préparons-nous — et mettons-nous en route !",
            ["DialogueId"] = 12043327,
            ["GUID"] = "1E263256",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120433/1E263256",
            },
        [12043401] = {
            ["Content"] = "你好，请问你认识一位叫做苏乙的老人家吗？",
            ["ContentFR"] = "Bonjour ! Tu connaîtrais une vieille dame qui s’appelle Su Yi ?",
            ["DialogueId"] = 12043401,
            ["GUID"] = "1E263E7A",
            ["NextDialogue"] = 12043402,
            ["RelatedWikiId"] = {
                [1] = 203007,
                [2] = 203009,
                [3] = 408018,
                [4] = 103001,
                },
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120434/1E263E7A",
            },
        [12043402] = {
            ["Content"] = "老、老人家？！",
            ["ContentFR"] = "V-Vieille dame ?!",
            ["DialogueId"] = 12043402,
            ["GUID"] = "1E263EA4",
            ["NextDialogue"] = 12043403,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120434/1E263EA4",
            },
        [12043403] = {
            ["Content"] = "不认识，你找错人了吧。",
            ["ContentFR"] = "Aucune idée. Tu te trompes de personne.",
            ["DialogueId"] = 12043403,
            ["GUID"] = "1E263ECE",
            ["NextDialogue"] = 12043404,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120434/1E263ECE",
            },
        [12043404] = {
            ["Content"] = "那，你是那个山什么的接头人……",
            ["ContentFR"] = "Alors... tu serais la personne de contact des Pi—",
            ["DialogueId"] = 12043404,
            ["GUID"] = "1E263EF8",
            ["NextDialogue"] = 12043405,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120434/1E263EF8",
            },
        [12043405] = {
            ["Content"] = "说了你找错人了，别再来问我了。",
            ["ContentFR"] = "J’ai dit que tu te trompais. Arrête de m’importuner.",
            ["DialogueId"] = 12043405,
            ["GUID"] = "1E263F22",
            ["NextDialogue"] = 12043406,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120434/1E263F22",
            },
        [12043406] = {
            ["Content"] = "我还没把话说完呢！再说了，正常人谁会在荒郊野岭晃来晃去啊！",
            ["ContentFR"] = "Hé ! J’avais pas fini ! Et puis franchement, qui se balade au milieu de nulle part comme ça ?!",
            ["DialogueId"] = 12043406,
            ["GUID"] = "1E263F4C",
            ["NextDialogue"] = 12043407,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120434/1E263F4C",
            },
        [12043407] = {
            ["Content"] = "这里又不是什么私家园林，无主之地而已。我就爱在这儿散步，越偏僻越能激发灵感，不行吗？",
            ["ContentFR"] = "Ce n’est pas un jardin privé. C’est un terrain sans maître. Moi, j’aime marcher ici. Plus c’est désert, plus ça m’inspire. Ça pose un problème ?",
            ["DialogueId"] = 12043407,
            ["GUID"] = "1E263F76",
            ["NextDialogue"] = 12043408,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120434/1E263F76",
            },
        [12043408] = {
            ["Content"] = "小仆从，难不成我们找错人了，她只是恰好路过？",
            ["ContentFR"] = "Petit larbin... on se serait trompés ? Elle passait juste par là ?",
            ["DialogueId"] = 12043408,
            ["GUID"] = "1E263FA0",
            ["NextDialogue"] = 12043409,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120434/1E263FA0",
            },
        [12043409] = {
            ["Content"] = "……白，刻舟还叮嘱过我们一些话。你忘了吗？",
            ["ContentFR"] = "... Snow, Kezhou nous a pourtant prévenus. Tu as oublié ?",
            ["DialogueId"] = 12043409,
            ["GUID"] = "1E263FCA",
            ["NextDialogue"] = 12043410,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120434/1E263FCA",
            },
        [12043410] = {
            ["Content"] = "啊……！我想起来了，要<H>一路沿着记号，找到今天的暗号动作。对过暗号，她才会搭理我们！</>",
            ["ContentFR"] = "Ah... ! C’est vrai ! Il fallait <H>suivre les marques jusqu’au bout et trouver le signal de reconnaissance du jour. Sans ça, elle ne nous adressera même pas la parole !</>",
            ["DialogueId"] = 12043410,
            ["GUID"] = "1E263FF4",
            ["NextDialogue"] = 12043411,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120434/1E263FF4",
            },
        [12043411] = {
            ["Content"] = "……哼，这么麻烦的规矩是谁定的，就喜欢让人跑来跑去是吧。",
            ["ContentFR"] = "... <I>Pff.</> C’est qui qui a inventé des règles aussi pénibles ? Ils adorent faire courir les gens, ou quoi ?",
            ["DialogueId"] = 12043411,
            ["GUID"] = "1E26401E",
            ["NextDialogue"] = 12043412,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120434/1E26401E",
            },
        [12043412] = {
            ["Content"] = "呵呵，小白莫要心急。华胥有句古话叫做好事多磨。耐心些，终点就在不远处了。",
            ["ContentFR"] = "Haha. Snow, ne t’impatiente pas. On dit à Huaxu que « les bonnes choses se méritent ». Encore un peu de patience... nous touchons au but.",
            ["DialogueId"] = 12043412,
            ["GUID"] = "1E264048",
            ["SpeakNpcId"] = 240002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120434/1E264048",
            },
        [12043501] = {
            ["Content"] = "跟我来吧，我就是你们要找的苏乙。",
            ["ContentFR"] = "Suivez-moi. Je suis Su Yi — celle que vous cherchez.",
            ["DialogueId"] = 12043501,
            ["GUID"] = "1E264EE2",
            ["NextDialogue"] = 12043502,
            ["RelatedWikiId"] = {
                [1] = 203007,
                [2] = 203009,
                [3] = 408018,
                [4] = 103001,
                },
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120435/1E264EE2",
            },
        [12043502] = {
            ["Content"] = "哎？你就是苏乙？！刻舟的姑奶奶不应该是个七八十岁的老人家吗！",
            ["ContentFR"] = "Hein ?! Toi, Su Yi ?! La grande-tante de Kezhou, ce n’était pas censé être une mamie de soixante-dix ou quatre-vingts ans ?!",
            ["DialogueId"] = 12043502,
            ["GUID"] = "1E264F0C",
            ["NextDialogue"] = 12043503,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120435/1E264F0C",
            },
        [12043503] = {
            ["Content"] = "我懂了……这一定是某种返老还童的神秘魔法力量……",
            ["ContentFR"] = "Je comprends... C’est forcément une magie mystérieuse de rajeunissement... !",
            ["DialogueId"] = 12043503,
            ["GUID"] = "1E264F36",
            ["NextDialogue"] = 12043504,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120435/1E264F36",
            },
        [12043504] = {
            ["Content"] = "咳咳，本姑娘只是辈分高而已。辈分又不一定和年龄挂钩！",
            ["ContentFR"] = "<I>Hum hum.</> La seule chose d’« élevée » chez moi, c’est le rang, d’accord ? Le rang n’a rien à voir avec l’âge !",
            ["DialogueId"] = 12043504,
            ["GUID"] = "1E264F60",
            ["NextDialogue"] = 12043505,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120435/1E264F60",
            },
        [12043505] = {
            ["Content"] = "自我介绍一下，我是山外山的司廪，机枢派第十七代传人。刻舟那家伙的师爷和我同辈，所以他得尊称我一声姑奶奶。接下来，我会为你们带路。",
            ["ContentFR"] = "Bon, je me présente : Su Yi, intendante des Pics Extérieurs, et héritière de la XVIIᵉ génération de la Secte Jishu. Le maître du maître de Kezhou est de ma génération, alors il est tenu de m’appeler « grande-tante ». À partir de maintenant, c’est moi qui vous guide.",
            ["DialogueId"] = 12043505,
            ["GUID"] = "1E264F8A",
            ["NextDialogue"] = 12043506,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120435/1E264F8A",
            },
        [12043506] = {
            ["Content"] = "你好，我是……",
            ["ContentFR"] = "{性别:Enchanté|Enchantée}, je suis—",
            ["DialogueId"] = 12043506,
            ["GUID"] = "1E264FB4",
            ["NextDialogue"] = 12043507,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120435/1E264FB4",
            },
        [12043507] = {
            ["Content"] = "不必介绍。你们几位的大名，我早有所耳闻啦。",
            ["ContentFR"] = "Inutile. Vos noms, je les connais déjà.",
            ["DialogueId"] = 12043507,
            ["GUID"] = "1E264FDE",
            ["NextDialogue"] = 12043508,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120435/1E264FDE",
            },
        [12043508] = {
            ["Content"] = "你是扶氏家主，于六十年前的大疫中沉睡，又于去年苏醒的祝由扶疏。",
            ["ContentFR"] = "Toi, tu es Fushu : cheffe de la Maison Zhuyou, endormie lors de la Grande Épidémie il y a soixante ans... et réveillée l’an dernier.",
            ["DialogueId"] = 12043508,
            ["GUID"] = "1E265008",
            ["NextDialogue"] = 12043509,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120435/1E265008",
            },
        [12043509] = {
            ["Content"] = "你是自称“纯白的救赎☆光之魔王大人”，虽然总是爱说大话，但其实心思简单的海伯利亚皎皎，白。",
            ["ContentFR"] = "Et toi... « Rédempteur Immaculé ☆ Roi Démon de la Lumière », la Luno d’Hyperborea : Snow. Tu parles fort, tu fanfaronnes... mais au fond, tu es d’une simplicité désarmante. Pas vrai ?",
            ["DialogueId"] = 12043509,
            ["GUID"] = "1E265032",
            ["NextDialogue"] = 12043510,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120435/1E265032",
            },
        [12043510] = {
            ["Content"] = "呜……你这人长得可可爱爱的，怎么说话和那个狗耳朵一样无情！",
            ["ContentFR"] = "<I>Grr...</> T’as une tête toute mignonne, mais tu parles comme Oreilles-de-chien : sans cœur !",
            ["DialogueId"] = 12043510,
            ["GUID"] = "1E26505C",
            ["NextDialogue"] = 12043511,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120435/1E26505C",
            },
        [12043511] = {
            ["Content"] = "嘻嘻……",
            ["ContentFR"] = "Héhé...",
            ["DialogueId"] = 12043511,
            ["GUID"] = "1E265086",
            ["NextDialogue"] = 12043512,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120435/1E265086",
            },
        [12043512] = {
            ["Content"] = "以及你……来历神秘，有着奇特能力的白发勇者，{nickname}。止流万里迢迢请来的座上宾，解决烛阴之灾的大功臣。我说得没错吧？",
            ["ContentFR"] = "Et toi... {nickname}. {性别:Un héros aux cheveux blancs, venu de nulle part, avec un pouvoir étrange. L’invité d’honneur que Zhiliu a fait venir de très loin... et celui|Une héroïne aux cheveux blancs, venue de nulle part, avec un pouvoir étrange. L’invitée d’honneur que Zhiliu a fait venir de très loin... et celle} qui a mis un terme au Fléau de Zhuyin. Je me trompe ?",
            ["DialogueId"] = 12043512,
            ["GUID"] = "1E2650B0",
            ["NextDialogue"] = 12043513,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120435/1E2650B0",
            },
        [12043513] = {
            ["Content"] = "对了，听说你超级厉害！之后有空，请务必来帮我测试机傀的实战数据，拜托你了！",
            ["ContentFR"] = "Au fait, on dit que tu es incroyablement {性别:fort|forte} ! Quand tu auras un moment, viens m’aider à tester les données de combat de mes méchapoupées. Je t’en prie !",
            ["DialogueId"] = 12043513,
            ["GUID"] = "1E2650DA",
            ["NextOptions"] = {
                [1] = 12043514,
                [2] = 12043515,
                },
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120435/1E2650DA",
            },
        [12043514] = {
            ["Content"] = "谬传而已，我只是帮了一点小忙。",
            ["ContentFR"] = "<I>Ce ne sont que des rumeurs. Je n’ai fait qu’aider un peu.<I>",
            ["DialogueId"] = 12043514,
            ["GUID"] = "1E265104",
            ["NextDialogue"] = 12043516,
            },
        [12043515] = {
            ["Content"] = "哦？原来我这么能打？",
            ["ContentFR"] = "<I>Ah bon ? Je suis si redoutable que ça ?<I>",
            ["DialogueId"] = 12043515,
            ["GUID"] = "1E26512E",
            ["NextDialogue"] = 12043516,
            },
        [12043516] = {
            ["Content"] = "原来你早就知道我们了！那刚刚干嘛还要装出一副不认识的样子？",
            ["ContentFR"] = "Donc... tu nous connaissais depuis le début ! Alors pourquoi jouer la comédie et faire semblant de ne pas nous reconnaître ?!",
            ["DialogueId"] = 12043516,
            ["GUID"] = "1E265158",
            ["NextDialogue"] = 12043517,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120435/1E265158",
            },
        [12043517] = {
            ["Content"] = "嘿嘿，刚刚真是对不起啦。消消气，苏乙给你赔罪可好？——就让这只小小乙鸟给你们表演一段飞行绝活吧！",
            ["ContentFR"] = "Héhé... désolée. Ne te fâche pas, d’accord ? Pour me faire pardonner, je vous offre un numéro : la « Voltige de l’Oiseau Yi » !",
            ["DialogueId"] = 12043517,
            ["GUID"] = "1E265182",
            ["NextDialogue"] = 12043518,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120435/1E265182",
            },
        [12043518] = {
            ["Content"] = "但是，确认暗号的步骤是必不可少的哦。如果疏忽了保密工作，因此带来不可控的风险，甚至导致有人殒命……我是不会让这种事情发生的。",
            ["ContentFR"] = "Mais... vérifier le signal était indispensable. La moindre faille de confidentialité peut engendrer un risque incontrôlable... et coûter des vies. Je ne laisserai jamais ça arriver.",
            ["DialogueId"] = 12043518,
            ["GUID"] = "1E2651AC",
            ["NextDialogue"] = 12043519,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120435/1E2651AC",
            },
        [12043519] = {
            ["Content"] = "嗯。你的顾虑我能够理解。",
            ["ContentFR"] = "Oui. Je comprends tes raisons.",
            ["DialogueId"] = 12043519,
            ["GUID"] = "1E2651D6",
            ["NextDialogue"] = 12043520,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120435/1E2651D6",
            },
        [12043520] = {
            ["Content"] = "如果是这种理由……那白也原谅你了！",
            ["ContentFR"] = "Si c’est pour ça... alors le Roi Démon te pardonne !",
            ["DialogueId"] = 12043520,
            ["GUID"] = "1E265200",
            ["NextDialogue"] = 12043521,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120435/1E265200",
            },
        [12043521] = {
            ["Content"] = "接下来这段路，有非常多的岔路口。通往基地的路线每日按周天大衍之数轮换，若是走错一步，便要迷失在荒郊野岭中了。",
            ["ContentFR"] = "La route qui suit est pleine d’embranchements. Le chemin vers la base change chaque jour selon un cycle précis — un seul pas de travers, et vous vous perdez dans ces terres.",
            ["DialogueId"] = 12043521,
            ["GUID"] = "1E26522A",
            ["NextDialogue"] = 12043522,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120435/1E26522A",
            },
        [12043522] = {
            ["Content"] = "你们可要跟紧了，别走丢哦！",
            ["ContentFR"] = "Alors restez bien derrière moi. Ne vous égarez pas, compris ?",
            ["DialogueId"] = 12043522,
            ["GUID"] = "1E265254",
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120435/1E265254",
            },
        [12043601] = {
            ["Content"] = "回来啦，小苏。外面还平安吗？",
            ["ContentFR"] = "Déjà de retour, Su. Tout va bien dehors ?",
            ["DialogueId"] = 12043601,
            ["GUID"] = "1E265F4A",
            ["NextDialogue"] = 12043602,
            ["RelatedWikiId"] = {
                [1] = 203007,
                [2] = 203009,
                [3] = 408018,
                [4] = 103001,
                },
            ["SpeakNpcId"] = 240029,
            ["VoiceName"] = "voice/$Locale$/story/1204/120436/1E265F4A",
            },
        [12043602] = {
            ["Content"] = "唐叔，你怎么出来了？你前几天测试“螺旋升天式斗笠试验机”时落下的腿伤还没好利索呢，还是要乖乖躺着才好——",
            ["ContentFR"] = "Oncle Tang, pourquoi tu es sorti ? Ta jambe n’a pas fini de guérir depuis l’essai du « Chapeau d’assaut à élévation spiralée » ! Tu devrais rester allongé !",
            ["DialogueId"] = 12043602,
            ["GUID"] = "1E265F74",
            ["NextDialogue"] = 12043603,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120436/1E265F74",
            },
        [12043603] = {
            ["Content"] = "呵呵，小伤，不碍事。倒是你，还是那么爱操心。",
            ["ContentFR"] = "Héhé... une broutille. Toi, en revanche, tu t’inquiètes toujours autant.",
            ["DialogueId"] = 12043603,
            ["GUID"] = "1E265F9E",
            ["NextDialogue"] = 12043604,
            ["SpeakNpcId"] = 240029,
            ["VoiceName"] = "voice/$Locale$/story/1204/120436/1E265F9E",
            },
        [12043604] = {
            ["Content"] = "还记得你刚来的时候，也就和天天抱着的牵机鸟一般高，一转眼，就成小大人喽。",
            ["ContentFR"] = "Je me souviens quand tu es arrivée... tu n’étais pas plus haute que l’oiseau mécanique que tu serrais tout le temps contre toi. Et te voilà déjà à jouer les grandes personnes.",
            ["DialogueId"] = 12043604,
            ["GUID"] = "1E265FC8",
            ["NextDialogue"] = 12043605,
            ["SpeakNpcId"] = 240029,
            ["VoiceName"] = "voice/$Locale$/story/1204/120436/1E265FC8",
            },
        [12043605] = {
            ["Content"] = "……唐叔！外人面前就别唠叨这些啦！",
            ["ContentFR"] = "... Oncle Tang ! Pas devant les invités !",
            ["DialogueId"] = 12043605,
            ["GUID"] = "1E265FF2",
            ["NextDialogue"] = 12043606,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120436/1E265FF2",
            },
        [12043606] = {
            ["Content"] = "哎呀，老了老了，眼神不好。原来是你们口中的那位{nickname}来了。刻舟那小子正念着你们呢。",
            ["ContentFR"] = "Ah... ces vieux yeux... Alors c’est vous, {nickname} dont on parle tant. Kezhou n’arrêtait pas de vous mentionner.",
            ["DialogueId"] = 12043606,
            ["GUID"] = "1E26601C",
            ["NextDialogue"] = 12043607,
            ["SpeakNpcId"] = 240029,
            ["VoiceName"] = "voice/$Locale$/story/1204/120436/1E26601C",
            },
        [12043607] = {
            ["Content"] = "刻舟？他已经回来了吗？",
            ["ContentFR"] = "Kezhou ? Il est déjà rentré ?",
            ["DialogueId"] = 12043607,
            ["GUID"] = "1E266046",
            ["NextDialogue"] = 12043608,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120436/1E266046",
            },
        [12043608] = {
            ["Content"] = "刚回来，他在前头等着你们呢。",
            ["ContentFR"] = "Oui. Il vous attend là-bas, devant.",
            ["DialogueId"] = 12043608,
            ["GUID"] = "1E266070",
            ["NextDialogue"] = 12043609,
            ["SpeakNpcId"] = 240029,
            ["VoiceName"] = "voice/$Locale$/story/1204/120436/1E266070",
            },
        [12043609] = {
            ["Content"] = "好啊，我可是有不少账要和他好好算算……{nickname}，我们走！",
            ["ContentFR"] = "Parfait. J’ai deux-trois comptes à régler avec lui... Allez, {nickname}, on y va !",
            ["DialogueId"] = 12043609,
            ["GUID"] = "1E26609A",
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120436/1E26609A",
            },
        [12043701] = {
            ["Content"] = "哟，你们来啦！怎么样，所谓云山深处更有洞天，我们这山外山的风景是不是很——",
            ["ContentFR"] = "Oh ! Vous voilà ! Alors, hein ? On dit que plus on s’enfonce dans les montagnes embrumées, plus on découvre un monde caché... Nos Pics Extérieurs, c’est pas—",
            ["DialogueId"] = 12043701,
            ["GUID"] = "1E266FB2",
            ["NextDialogue"] = 12043702,
            ["RelatedWikiId"] = {
                [1] = 203007,
                [2] = 203009,
                [3] = 408018,
                [4] = 103001,
                },
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E266FB2",
            },
        [12043702] = {
            ["Content"] = "刻——舟！",
            ["ContentFR"] = "KE—ZHOU !",
            ["DialogueId"] = 12043702,
            ["GUID"] = "1E266FDC",
            ["NextDialogue"] = 12043703,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E266FDC",
            },
        [12043703] = {
            ["Content"] = "刚瞒着大家在外面捅出天大的篓子，就装出一副若无其事的样子，这像话吗？啊？这像话吗？",
            ["ContentFR"] = "Tu sors faire une bêtise monstrueuse dehors, et tu reviens en sifflotant comme si de rien n’était ? Hein ?! C’est sérieux, ça ?!",
            ["DialogueId"] = 12043703,
            ["GUID"] = "1E267006",
            ["NextDialogue"] = 12043704,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E267006",
            },
        [12043704] = {
            ["Content"] = "哈哈……这不是知道姑奶奶办事熨帖，滴水不漏，让基地的大家都无后顾之忧吗？要是离了姑奶奶，这个家得散！",
            ["ContentFR"] = "Hahaha... Je savais que ma grande-tante fait tout impeccablement, sans la moindre faille. Comme ça, tout le monde ici dort tranquille ! Sans toi, la maison s’écroule !",
            ["DialogueId"] = 12043704,
            ["GUID"] = "1E267030",
            ["NextDialogue"] = 12043705,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E267030",
            },
        [12043705] = {
            ["Content"] = "别以为你说几句好话，我就能放过你。这次可没这么简单！",
            ["ContentFR"] = "Ne crois pas que trois flatteries vont te sauver. Cette fois, ça ne passera pas !",
            ["DialogueId"] = 12043705,
            ["GUID"] = "1E26705A",
            ["NextDialogue"] = 12043706,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E26705A",
            },
        [12043706] = {
            ["Content"] = "你招惹什么不好，非得招惹白龙那个狴犴头子！这下好了，外面全都是狴犴和应天尉，够你喝好几壶的！",
            ["ContentFR"] = "Tu ne pouvais pas choisir une cible moins explosive ? Non ! Il a fallu que tu t’attaques au Seigneur Dragon d’Argent en personne ! Maintenant, la ville est infestée de Bi’an et de Magistrats de Yingtian ! Tu te rends compte du chaos que tu as déclenché ?!",
            ["DialogueId"] = 12043706,
            ["GUID"] = "1E267084",
            ["NextDialogue"] = 12043707,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E267084",
            },
        [12043707] = {
            ["Content"] = "嘿嘿，我这不是全须全尾地回来山外山了么。有咱们<H>天罗拒风仪</>在，能切断大风九章的感应，那些蠢狼寻不过来的。",
            ["ContentFR"] = "Héhé... mais je suis revenu entier, non ? Avec notre <H>Voile de Tianluo</>, on coupe la résonance des Neuf Chapitres. Ces loups idiots ne pourront pas nous pister.",
            ["DialogueId"] = 12043707,
            ["GUID"] = "1E2670AE",
            ["NextDialogue"] = 12043708,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E2670AE",
            },
        [12043708] = {
            ["Content"] = "你还狡辩！要不是有{nickname}在，你的小命早就不知道丢哪里去了！",
            ["ContentFR"] = "Et en plus tu oses discuter ! Sans {nickname}, ta petite vie, tu l’aurais déjà laissée je ne sais où !",
            ["DialogueId"] = 12043708,
            ["GUID"] = "1E2670D8",
            ["NextDialogue"] = 12043709,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E2670D8",
            },
        [12043709] = {
            ["Content"] = "{nickname}，快，赶紧帮我求求情啊！",
            ["ContentFR"] = "{nickname} ! Allez, aide-moi... dis-lui un mot gentil, vite !",
            ["DialogueId"] = 12043709,
            ["GUID"] = "1E267102",
            ["NextDialogue"] = 12043710,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E267102",
            },
        [12043710] = {
            ["Content"] = "刻舟先前和我们说……",
            ["ContentFR"] = "Kezhou nous a dit que...",
            ["DialogueId"] = 12043710,
            ["GUID"] = "1E26712C",
            ["NextOptions"] = {
                [1] = 12043711,
                [2] = 12043712,
                },
            ["RelatedWikiId"] = {
                [1] = 203007,
                [2] = 203009,
                [3] = 408018,
                [4] = 103001,
                },
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E26712C",
            },
        [12043711] = {
            ["Content"] = "（附和刻舟）",
            ["ContentFR"] = "<I>Soutenir</>",
            ["DialogueId"] = 12043711,
            ["GUID"] = "1E267156",
            ["ImprPlusId"] = 1201,
            ["NextDialogue"] = 12043713,
            },
        [12043712] = {
            ["Content"] = "（揭穿刻舟）",
            ["ContentFR"] = "<I>Dénoncer</>",
            ["DialogueId"] = 12043712,
            ["GUID"] = "1E267180",
            ["ImprPlusId"] = 1202,
            ["NextDialogue"] = 12043716,
            },
        [12043713] = {
            ["Content"] = "他说你是举世无双的天才美少女，人很好，做事特别可靠，非常值得信赖！",
            ["ContentFR"] = "Il a dit que tu étais une génie sans pareille, la plus brillante de toutes... fiable, impeccable, digne de confiance !",
            ["DialogueId"] = 12043713,
            ["GUID"] = "1E2671AA",
            ["NextDialogue"] = 12043714,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E2671AA",
            },
        [12043714] = {
            ["Content"] = "哇，小仆从，你还真是脸不红心不跳，张口就来……",
            ["ContentFR"] = "Ouah... Petit larbin, tu débites ça sans même rougir...",
            ["DialogueId"] = 12043714,
            ["GUID"] = "1E2671D4",
            ["NextDialogue"] = 12043715,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E2671D4",
            },
        [12043715] = {
            ["Content"] = "够了够了，别再说啦——",
            ["ContentFR"] = "Ç-Ça suffit, ça suffit ! N’en rajoute pas !",
            ["DialogueId"] = 12043715,
            ["GUID"] = "1E2671FE",
            ["NextDialogue"] = 12043719,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E2671FE",
            },
        [12043716] = {
            ["Content"] = "他说你脾气不太好，规矩也多。只有耳根子软，只要说两句好话，就能把事情揭过去了。",
            ["ContentFR"] = "Il a dit que tu avais mauvais caractère, beaucoup trop de règles... et que tu étais très facile à attendrir : il suffit de te flatter un peu et tout passe.",
            ["DialogueId"] = 12043716,
            ["GUID"] = "1E267228",
            ["NextDialogue"] = 12043717,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E267228",
            },
        [12043717] = {
            ["Content"] = "喂喂喂，{nickname}，你还真是一点情面都不留啊……",
            ["ContentFR"] = "Hé, {nickname}... tu ne laisses vraiment aucune porte de sortie, toi...",
            ["DialogueId"] = 12043717,
            ["GUID"] = "1E267252",
            ["NextDialogue"] = 12043718,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E267252",
            },
        [12043718] = {
            ["Content"] = "呵，我就知道！我再也不会上他的当了！",
            ["ContentFR"] = "Ha ! Je le savais ! Je ne me ferai plus avoir par ses beaux discours !",
            ["DialogueId"] = 12043718,
            ["GUID"] = "1E26727C",
            ["NextDialogue"] = 12043719,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E26727C",
            },
        [12043719] = {
            ["Content"] = "哼，刻舟那小子的帐我之后再和他慢慢清算，还是先说回正事吧。",
            ["ContentFR"] = "<I>Hmpf.<I> Je réglerai le compte de ce bon à rien plus tard. Parlons plutôt de l’essentiel.",
            ["DialogueId"] = 12043719,
            ["GUID"] = "1E2672A6",
            ["NextDialogue"] = 12043720,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E2672A6",
            },
        [12043720] = {
            ["Content"] = "事情的前因后果我已经了解了，止流吸收了烛阴的力量，欲求成神……虽然暂时无法确认她的真实意图，但她很有可能成为山外山的潜在威胁。",
            ["ContentFR"] = "J’ai compris la situation : Zhiliu a absorbé la puissance de Zhuyin et cherche à devenir une divinité... On ne peut pas encore confirmer ses intentions, mais elle représente potentiellement une menace pour les Pics Extérieurs.",
            ["DialogueId"] = 12043720,
            ["GUID"] = "1E2672D0",
            ["NextDialogue"] = 12043721,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E2672D0",
            },
        [12043721] = {
            ["Content"] = "总之这次情况不容小觑。你们接下来有什么计划？",
            ["ContentFR"] = "Bref, c’est sérieux. Quel est votre plan ?",
            ["DialogueId"] = 12043721,
            ["GUID"] = "1E2672FA",
            ["NextDialogue"] = 12043722,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E2672FA",
            },
        [12043722] = {
            ["Content"] = "我不想被止流牵着鼻子走。我得尽快打破她的布局。",
            ["ContentFR"] = "Je ne veux pas avancer au rythme que Zhiliu a choisi. Je dois briser sa manœuvre au plus vite.",
            ["DialogueId"] = 12043722,
            ["GUID"] = "1E267324",
            ["NextDialogue"] = 12043723,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E267324",
            },
        [12043723] = {
            ["Content"] = "赞同！如今的当务之急，是早日找到那个女人的踪迹，也好对她下一步的谋划有所打算。",
            ["ContentFR"] = "Je suis d’accord ! L’urgence, c’est de retrouver la trace de cette femme, pour anticiper son prochain coup.",
            ["DialogueId"] = 12043723,
            ["GUID"] = "1E26734E",
            ["NextDialogue"] = 12043724,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E26734E",
            },
        [12043724] = {
            ["Content"] = "很遗憾……这点我早就想到了。",
            ["ContentFR"] = "Malheureusement... j’y ai pensé avant vous.",
            ["DialogueId"] = 12043724,
            ["GUID"] = "1E267378",
            ["NextDialogue"] = 12043725,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E267378",
            },
        [12043725] = {
            ["Content"] = "根据城中密探传回的消息，自从她昨日在天禄司门口现身后，整个皓京城，再无人目击到止流的踪迹，就连天上徘徊的机关鸟也无能为力。她就这样人间蒸发了。",
            ["ContentFR"] = "D’après nos informations : depuis qu’elle s’est montrée hier devant le Bureau de la Fortune Céleste, plus personne à Haojing ne l’a revue. Même nos oiseaux mécaniques qui patrouillent le ciel n’ont rien trouvé. Elle s’est... évaporée.",
            ["DialogueId"] = 12043725,
            ["GUID"] = "1E2673A2",
            ["NextDialogue"] = 12043726,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E2673A2",
            },
        [12043726] = {
            ["Content"] = "或许……我们现在的反应，也在她的预料之中。",
            ["ContentFR"] = "Peut-être que... notre réaction aussi faisait partie de ses calculs.",
            ["DialogueId"] = 12043726,
            ["GUID"] = "1E2673CC",
            ["NextDialogue"] = 12043727,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E2673CC",
            },
        [12043727] = {
            ["Content"] = "目前看来，比起找寻止流的下落，破解{nickname}身上的催眠，从而知道她接下来的布置，可能更加现实一点。",
            ["ContentFR"] = "Dans ce cas, plutôt que courir après Zhiliu, le plus réaliste serait de briser l’<W>hypnose</> qu’elle a implantée en {nickname}. Si on y parvient, on comprendra peut-être son prochain arrangement.",
            ["DialogueId"] = 12043727,
            ["GUID"] = "1E2673F6",
            ["NextDialogue"] = 12043728,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E2673F6",
            },
        [12043728] = {
            ["Content"] = "我……或许有些眉目。",
            ["ContentFR"] = "... J’ai peut-être une piste.",
            ["DialogueId"] = 12043728,
            ["GUID"] = "1E267420",
            ["NextDialogue"] = 12043729,
            ["SpeakNpcId"] = 240002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E267420",
            },
        [12043729] = {
            ["Content"] = "扶疏姐姐，你想到了什么吗？",
            ["ContentFR"] = "Fushu, tu as trouvé quelque chose ?",
            ["DialogueId"] = 12043729,
            ["GUID"] = "1E26744A",
            ["NextDialogue"] = 12043730,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E26744A",
            },
        [12043730] = {
            ["Content"] = "世人皆知悬衡、机枢两门显学。却少有人知，上古时期本是百家争鸣。其中不乏传承至今避世简出的旁门奇派，如秉烛、观微派……",
            ["ContentFR"] = "Tout le monde connaît les deux grandes sectes : Xuanheng et Jishu. Mais peu savent qu’autrefois, cent courants rivalisaient. Certains ont survécu jusqu’à aujourd’hui, reclus et discrets... comme Bingzhu ou Guanwei.",
            ["DialogueId"] = 12043730,
            ["GUID"] = "1E267474",
            ["NextDialogue"] = 12043731,
            ["SpeakNpcId"] = 240002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E267474",
            },
        [12043731] = {
            ["Content"] = "我明白了！",
            ["ContentFR"] = "Je vois !",
            ["DialogueId"] = 12043731,
            ["GUID"] = "1E26749E",
            ["NextDialogue"] = 12043732,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E26749E",
            },
        [12043732] = {
            ["Content"] = "卜卦奇算，窥伺未来，甚至于以特定手法操纵人心……你想说的，莫非是<H>无穷藏派</>？",
            ["ContentFR"] = "Divination, calculs étranges, lecture du futur... et même manipulation de l’esprit par des procédés précis... Tu penses à la <H>Secte de l’Insondable Trésor</>, n’est-ce pas ?",
            ["DialogueId"] = 12043732,
            ["GUID"] = "1E2674C8",
            ["NextDialogue"] = 12043733,
            ["RelatedWikiId"] = {
                [1] = 407014,
                },
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E2674C8",
            },
        [12043733] = {
            ["Content"] = "正是如此。",
            ["ContentFR"] = "Exactement.",
            ["DialogueId"] = 12043733,
            ["GUID"] = "1E2674F2",
            ["NextDialogue"] = 12043734,
            ["SpeakNpcId"] = 240002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E2674F2",
            },
        [12043734] = {
            ["Content"] = "先前为{nickname}把脉时，我便隐隐有些预感。未曾想到，身为龙渊上卿的止流竟是无穷藏派的传人。",
            ["ContentFR"] = "Quand j’ai pris le pouls de {nickname}, j’ai eu un pressentiment. Je n’aurais jamais imaginé que Zhiliu, <H>Haut Chancelier de Longyuan</>, puisse être issue de la Secte de l’Insondable Trésor.",
            ["DialogueId"] = 12043734,
            ["GUID"] = "1E26751C",
            ["NextDialogue"] = 12043735,
            ["SpeakNpcId"] = 240002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E26751C",
            },
        [12043735] = {
            ["Content"] = "接下来，我打算去城中寻访无穷藏派的隐居踪迹，好为{nickname}的记忆恢复做打算。",
            ["ContentFR"] = "Je compte retourner en ville pour chercher la trace de leur enclave recluse... et préparer un moyen de restaurer la mémoire de {nickname}.",
            ["DialogueId"] = 12043735,
            ["GUID"] = "1E267546",
            ["NextDialogue"] = 12043736,
            ["SpeakNpcId"] = 240002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E267546",
            },
        [12043736] = {
            ["Content"] = "我也跟你一起去。",
            ["ContentFR"] = "Alors je viens avec toi.",
            ["DialogueId"] = 12043736,
            ["GUID"] = "1E267570",
            ["NextDialogue"] = 12043737,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E267570",
            },
        [12043737] = {
            ["Content"] = "不妥。",
            ["ContentFR"] = "Non.",
            ["DialogueId"] = 12043737,
            ["GUID"] = "1E26759A",
            ["NextDialogue"] = 12043738,
            ["SpeakNpcName"] = "UI_Npc_Name_FuShuSuYi",
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E26759A",
            },
        [12043738] = {
            ["Content"] = "根据线报，城中如今风声正紧呢。你们在执律阁对白龙神大不敬，现在狴犴和应天尉都在四处抓捕你们。依我看，你们还是先待在这里暂避风头比较好。",
            ["ContentFR"] = "La ville est en état d’alerte. Après votre affront au Pavillon de l’Arbitrage, Bi’an et Magistrats de Yingtian vous traquent partout. Le mieux, c’est de rester ici et de laisser retomber la pression.",
            ["DialogueId"] = 12043738,
            ["GUID"] = "1E2675C4",
            ["NextDialogue"] = 12043739,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E2675C4",
            },
        [12043739] = {
            ["Content"] = "苏姑娘所言有理。{nickname}，先前你与太皓交手，力量过度消耗，正是应当静养的时候。",
            ["ContentFR"] = "Su Yi a raison. {nickname}, ton affrontement avec Taihao t’a {性别:vidé|vidée} de ta force. Tu dois te reposer.",
            ["DialogueId"] = 12043739,
            ["GUID"] = "1E2675EE",
            ["NextDialogue"] = 12043740,
            ["SpeakNpcId"] = 240002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E2675EE",
            },
        [12043740] = {
            ["Content"] = "此外，这趟我还有些私事要处理，可能不便与人同行……抱歉。",
            ["ContentFR"] = "Et... j’ai aussi une affaire personnelle à régler. Je préfère voyager seule. Pardonne-moi.",
            ["DialogueId"] = 12043740,
            ["GUID"] = "1E267618",
            ["NextOptions"] = {
                [1] = 12043741,
                [2] = 12043742,
                },
            ["SpeakNpcId"] = 240002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E267618",
            },
        [12043741] = {
            ["Content"] = "好吧，那我尊重你的想法。",
            ["ContentFR"] = "<I>D’accord. Je respecte ton choix.</>",
            ["DialogueId"] = 12043741,
            ["GUID"] = "1E267642",
            ["NextDialogue"] = 12043743,
            },
        [12043742] = {
            ["Content"] = "有点不甘心……",
            ["ContentFR"] = "<I>Ça me laisse un goût d’inachevé...</>",
            ["DialogueId"] = 12043742,
            ["GUID"] = "1E26766C",
            ["NextDialogue"] = 12043743,
            },
        [12043743] = {
            ["Content"] = "既然{nickname}暂时不方便露面，就让本人替你出去一转——",
            ["ContentFR"] = "Si {nickname} ne peut pas se montrer, alors je peux sortir à sa place—",
            ["DialogueId"] = 12043743,
            ["GUID"] = "1E267696",
            ["NextDialogue"] = 12043744,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E267696",
            },
        [12043744] = {
            ["Content"] = "你？你就给我好好待在山外山，别出去添乱了。别忘了，基地里的大小事宜都需要人手。谷底伤人的野兽清理了吗？破损的屋顶修缮了吗？",
            ["ContentFR"] = "Toi ? Tu restes ici, et tu évites d’aggraver la situation. Tu as oublié que la base a besoin de bras ? La bête qui attaque les gens au fond du ravin, elle est réglée ? Les toits endommagés, ils sont réparés ?",
            ["DialogueId"] = 12043744,
            ["GUID"] = "1E2676C0",
            ["NextDialogue"] = 12043745,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E2676C0",
            },
        [12043745] = {
            ["Content"] = "先前你满口打包票说要帮忙，这些空口支票还从来没兑现过呢。",
            ["ContentFR"] = "Tu avais promis monts et merveilles... et je n’ai encore rien vu.",
            ["DialogueId"] = 12043745,
            ["GUID"] = "1E2676EA",
            ["NextDialogue"] = 12043746,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E2676EA",
            },
        [12043746] = {
            ["Content"] = "咳咳，有一件事姑奶奶可能不知。这里的两位和我可是拜过把子的交情。很乐意替我代劳，一起为基地建设添砖加瓦。",
            ["ContentFR"] = "<I>Hum hum.</> Il y a une chose que ma grande-tante ignore : ces deux-là et moi, on a prêté serment ensemble. Ils seront ravis de m’aider et de contribuer à la base.",
            ["DialogueId"] = 12043746,
            ["GUID"] = "1E267714",
            ["NextDialogue"] = 12043747,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E267714",
            },
        [12043747] = {
            ["Content"] = "刻舟！你不想干活也就算了，怎么还推脱到别人身上！",
            ["ContentFR"] = "Kezhou ! Tu ne veux pas travailler, passe encore — mais ne reporte pas ça sur nos {性别:invités|invitées} !",
            ["DialogueId"] = 12043747,
            ["GUID"] = "1E26773E",
            ["NextDialogue"] = 12043748,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E26773E",
            },
        [12043748] = {
            ["Content"] = "非也。乍看之下，是我刻舟在找借口。但其实是姑奶奶听了{nickname}的事迹后，对你们仰慕已久。我为几位创造相处机会，可谓用心良苦——",
            ["ContentFR"] = "Mais non. On dirait que je cherche une excuse... alors qu’en réalité, ma grande-tante admire {nickname} depuis longtemps. Je ne fais que créer une belle occasion de vous rapprocher. On peut dire que je me dévoue—",
            ["DialogueId"] = 12043748,
            ["GUID"] = "1E267768",
            ["NextDialogue"] = 12043749,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E267768",
            },
        [12043749] = {
            ["Content"] = "……闭嘴！！真是的！{nickname}，你可别听那家伙的胡言乱语！他满嘴跑火车，就没一句是真的！",
            ["ContentFR"] = "... TAIS-TOI ! {nickname}, n’écoute pas ses sottises ! Il invente tout ! Il n’y a pas une seule phrase vraie dans ce qu’il raconte !",
            ["DialogueId"] = 12043749,
            ["GUID"] = "1E267792",
            ["NextOptions"] = {
                [1] = 12043750,
                },
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E267792",
            },
        [12043750] = {
            ["Content"] = "所以“仰慕已久”也是假的？",
            ["ContentFR"] = "<I>Donc la partie « admiration », c’est faux aussi ?</>",
            ["DialogueId"] = 12043750,
            ["GUID"] = "1E2677BC",
            ["NextDialogue"] = 12043751,
            },
        [12043751] = {
            ["Content"] = "那，我确实觉得你很厉害啦……不对，被他绕进去了！你们是客人，哪有让客人来干活的道理。",
            ["ContentFR"] = "B-Bah... je te trouve vraiment {性别:impressionnant, d’accord... Non ! Il m’a encore entraînée dans son délire ! Vous êtes nos invités|impressionnante, d’accord... Non ! Il m’a encore entraînée dans son délire ! Vous êtes nos invitées} : on ne fait pas travailler les invités !",
            ["DialogueId"] = 12043751,
            ["GUID"] = "1E2677E6",
            ["NextDialogue"] = 12043752,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E2677E6",
            },
        [12043752] = {
            ["Content"] = "哼哼，看在你如此仰慕白和小仆从的份上，也不是不能搭把手啦！",
            ["ContentFR"] = "Héhé ! Puisque tu admires autant Snow et son petit larbin... on peut bien donner un coup de main, alors !",
            ["DialogueId"] = 12043752,
            ["GUID"] = "1E267810",
            ["NextDialogue"] = 12043753,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E267810",
            },
        [12043753] = {
            ["Content"] = "我们留在这里，帮忙做点事也是应该的。",
            ["ContentFR"] = "Puisqu’on reste ici, aider un peu, c’est la moindre des choses.",
            ["DialogueId"] = 12043753,
            ["GUID"] = "1E26783A",
            ["NextDialogue"] = 12043754,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E26783A",
            },
        [12043754] = {
            ["Content"] = "你们愿意固然好啦……不要受那个家伙的话术影响就行！我先替山外山的大伙谢谢你们啦。",
            ["ContentFR"] = "Si vous insistez... tant mieux. Mais ne vous laissez pas embobiner par lui, c’est tout ! Au nom de tout le monde aux Pics Extérieurs... merci.",
            ["DialogueId"] = 12043754,
            ["GUID"] = "1E267864",
            ["NextDialogue"] = 12043755,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E267864",
            },
        [12043755] = {
            ["Content"] = "那我便先告辞了。若有了消息，我会第一时间赶回来。",
            ["ContentFR"] = "Alors je vais prendre congé. Si j’obtiens la moindre information, je reviendrai immédiatement.",
            ["DialogueId"] = 12043755,
            ["GUID"] = "1E26788E",
            ["NextDialogue"] = 12043756,
            ["SpeakNpcId"] = 240002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E26788E",
            },
        [12043756] = {
            ["Content"] = "好，扶疏姐姐，我们等着你！你一路上也要小心哦！",
            ["ContentFR"] = "D’accord, Fushu ! On t’attend ! Et sois prudente sur la route !",
            ["DialogueId"] = 12043756,
            ["GUID"] = "1E2678B8",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E2678B8",
            },
        [12043801] = {
            ["Content"] = "依我看，只要在那恶鸟大咧咧靠近之时，趁其不备，引弓长射，就能将它一击拿下！",
            ["ContentFR"] = "À mon avis, on attend que ce sale oiseau s’approche sans se méfier... et paf ! Une flèche bien tendue, un seul tir, et c’est réglé !",
            ["DialogueId"] = 12043801,
            ["GUID"] = "1E26801A",
            ["NextDialogue"] = 12043802,
            ["RelatedWikiId"] = {
                [1] = 203007,
                [2] = 203009,
                [3] = 408018,
                [4] = 103001,
                },
            ["SpeakNpcId"] = 240030,
            ["VoiceName"] = "voice/$Locale$/story/1204/120438/1E26801A",
            },
        [12043802] = {
            ["Content"] = "唉，可惜我的准头还是不太行……要是一箭射空，在这埋伏半天的功夫就白费了，身上这些豆大的蚊子包也白被咬了。",
            ["ContentFR"] = "... Sauf que mon tir n’est pas assez sûr. Si je rate, on aura poireauté pour rien... et je me serai fait dévorer par les moustiques pour rien.",
            ["DialogueId"] = 12043802,
            ["GUID"] = "1E268044",
            ["NextDialogue"] = 12043803,
            ["SpeakNpcId"] = 240030,
            ["VoiceName"] = "voice/$Locale$/story/1204/120438/1E268044",
            },
        [12043803] = {
            ["Content"] = "不行不行，还是得想想其他法子。",
            ["ContentFR"] = "Non, non... faut trouver une autre idée.",
            ["DialogueId"] = 12043803,
            ["GUID"] = "1E26806E",
            ["NextDialogue"] = 12043804,
            ["SpeakNpcId"] = 240030,
            ["VoiceName"] = "voice/$Locale$/story/1204/120438/1E26806E",
            },
        [12043804] = {
            ["Content"] = "嗯……师傅前几日刚教过感应机关的制备方法，正好适用于这种场景。",
            ["ContentFR"] = "Hm... mon maître m’a justement appris l’autre jour à fabriquer un mécanisme de détection. Ce serait parfait ici.",
            ["DialogueId"] = 12043804,
            ["GUID"] = "1E268098",
            ["NextDialogue"] = 12043805,
            ["SpeakNpcId"] = 240031,
            ["VoiceName"] = "voice/$Locale$/story/1204/120438/1E268098",
            },
        [12043805] = {
            ["Content"] = "但是要把它还原出来，还缺上几种材料。要等到找齐材料，这坏鸟早就吃饱喝足，抖抖羽毛飞走了。要是能在哪里找到制备好的现成机关就好了……",
            ["ContentFR"] = "Mais pour le refaire, il me manque encore quelques matériaux. Le temps de tout rassembler, ce sale oiseau aura déjà mangé, fait sa toilette, et filé... Si seulement on pouvait trouver un mécanisme tout prêt, quelque part...",
            ["DialogueId"] = 12043805,
            ["GUID"] = "1E2680C2",
            ["NextDialogue"] = 12043806,
            ["SpeakNpcId"] = 240031,
            ["VoiceName"] = "voice/$Locale$/story/1204/120438/1E2680C2",
            },
        [12043806] = {
            ["Content"] = "阿晨，小野，我说你们两个，现在还是课业时间吧。怎么不去上课习武，反而躲在这里偷懒了？",
            ["ContentFR"] = "Chen. Ye. Dites donc... ce n’est pas l’heure des cours, là ? Pourquoi vous n’êtes pas à vous entraîner, au lieu de vous cacher ici à paresser ?",
            ["DialogueId"] = 12043806,
            ["GUID"] = "1E2680EC",
            ["NextDialogue"] = 12043807,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120438/1E2680EC",
            },
        [12043807] = {
            ["Content"] = "哇啊啊——是苏乙姐姐！",
            ["ContentFR"] = "Aaaah— ! Grande sœur Yi !",
            ["DialogueId"] = 12043807,
            ["GUID"] = "1E268116",
            ["NextDialogue"] = 12043808,
            ["SpeakNpcId"] = 240030,
            ["VoiceName"] = "voice/$Locale$/story/1204/120438/1E268116",
            },
        [12043808] = {
            ["Content"] = "好的不学，偏学刻舟那家伙逃课是吧？被我逮了个正着，这下可有人要吃苦头咯。",
            ["ContentFR"] = "Et vous choisissez d’imiter Kezhou, en plus... manquer les cours, hein ? Je vous prends sur le fait. Il y en a qui vont passer un mauvais quart d’heure.",
            ["DialogueId"] = 12043808,
            ["GUID"] = "1E268140",
            ["NextDialogue"] = 12043809,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120438/1E268140",
            },
        [12043809] = {
            ["Content"] = "苏乙姐姐，你先听我们说完！",
            ["ContentFR"] = "Grande sœur Yi, attends ! Laisse-nous expliquer !",
            ["DialogueId"] = 12043809,
            ["GUID"] = "1E26816A",
            ["NextDialogue"] = 12043810,
            ["SpeakNpcId"] = 240031,
            ["VoiceName"] = "voice/$Locale$/story/1204/120438/1E26816A",
            },
        [12043810] = {
            ["Content"] = "那个，逃课是我们不对。但我前几天在药田里值勤时，飞来一只恶鸟。它不仅糟蹋田里面的药草，把叶子扯得到处都是，还耀武扬威地在我头上拉屎——",
            ["ContentFR"] = "D’accord... on n’aurait pas dû manquer les cours. Mais l’autre jour, quand je montais la garde au champ d’herbes, un oiseau affreux est arrivé. Il a tout saccagé, arraché les feuilles... et il a même fait ses besoins sur ma tête !",
            ["DialogueId"] = 12043810,
            ["GUID"] = "1E268194",
            ["NextDialogue"] = 12043811,
            ["SpeakNpcId"] = 240031,
            ["VoiceName"] = "voice/$Locale$/story/1204/120438/1E268194",
            },
        [12043811] = {
            ["Content"] = "我们飘零人，仗剑日月间，专管不平事，怎么能被一只鸟欺在头上？就算不为自己，为了朋友，我也得出了这口气！",
            ["ContentFR"] = "Nous, les Vagabonds, on tranche l’injustice l’épée au poing ! Comment on pourrait se laisser marcher dessus par un oiseau ? Même si ce n’est pas pour moi... pour mon ami, je devais lui rendre ça !",
            ["DialogueId"] = 12043811,
            ["GUID"] = "1E2681BE",
            ["NextDialogue"] = 12043812,
            ["SpeakNpcId"] = 240030,
            ["VoiceName"] = "voice/$Locale$/story/1204/120438/1E2681BE",
            },
        [12043812] = {
            ["Content"] = "就像这样，小野他听了这事之后就打包票说要来帮忙。但是那鸟浑身心眼子，警惕得很。我们在这里蹲守了好几天，都没捉住它的一根羽毛……",
            ["ContentFR"] = "Voilà... Ye a juré de m’aider. Sauf que cet oiseau est plein de ruses, hyper méfiant. On campe ici depuis des jours et... on n’a même pas attrapé une plume...",
            ["DialogueId"] = 12043812,
            ["GUID"] = "1E2681E8",
            ["NextDialogue"] = 12043813,
            ["SpeakNpcId"] = 240031,
            ["VoiceName"] = "voice/$Locale$/story/1204/120438/1E2681E8",
            },
        [12043813] = {
            ["Content"] = "那你们怎么不叫人帮忙？",
            ["ContentFR"] = "Et pourquoi vous n’avez pas demandé de l’aide ?",
            ["DialogueId"] = 12043813,
            ["GUID"] = "1E268212",
            ["NextDialogue"] = 12043814,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120438/1E268212",
            },
        [12043814] = {
            ["Content"] = "……要是连一只鸟都降服不住，以后还谈什么惩恶扬善，仗剑助人。我、我丢不起这个人。",
            ["ContentFR"] = "... Si on n’est même pas capables d’attraper un simple oiseau, comment on fera pour défendre les autres plus tard ? J... je ne voulais pas avoir l’air ridicule.",
            ["DialogueId"] = 12043814,
            ["GUID"] = "1E26823C",
            ["NextDialogue"] = 12043815,
            ["SpeakNpcId"] = 240030,
            ["VoiceName"] = "voice/$Locale$/story/1204/120438/1E26823C",
            },
        [12043815] = {
            ["Content"] = "唉，你们啊……算了，正巧{nickname}来了，就让{性别：他|她}给你们露一手吧。",
            ["ContentFR"] = "<I>Pff...</> vous alors... Bon. Justement, {nickname} est là. {性别:Il|Elle} va vous montrer comment on fait.",
            ["DialogueId"] = 12043815,
            ["GUID"] = "1E268266",
            ["NextDialogue"] = 12043816,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120438/1E268266",
            },
        [12043816] = {
            ["Content"] = "{nickname}？！难、难不成是和刻舟哥哥一起手撕烛阴、脚踩太皓的那位绝世{性别：大侠|女侠}？这下见到真人了！",
            ["ContentFR"] = "{nickname} ?! A-attends... ce serait pas l’incroyable {性别:héros|héroïne} qui, avec grand frère Kezhou, a déchiré Zhuyin à mains nues... et piétiné Taihao ?! J’en reviens pas... je te vois en vrai !",
            ["DialogueId"] = 12043816,
            ["GUID"] = "1E268290",
            ["NextOptions"] = {
                [1] = 12043817,
                [2] = 12043818,
                },
            ["SpeakNpcId"] = 240031,
            ["VoiceName"] = "voice/$Locale$/story/1204/120438/1E268290",
            },
        [12043817] = {
            ["Content"] = "他都给你们灌输了什么奇怪故事……",
            ["ContentFR"] = "<I>Qu’est-ce qu’il vous a raconté, encore...</>",
            ["DialogueId"] = 12043817,
            ["GUID"] = "1E2682BA",
            ["NextDialogue"] = 12043819,
            },
        [12043818] = {
            ["Content"] = "没错，正是本人！",
            ["ContentFR"] = "<I>Exact. C’est bien moi.</>",
            ["DialogueId"] = 12043818,
            ["GUID"] = "1E2682E4",
            ["NextDialogue"] = 12043819,
            },
        [12043819] = {
            ["Content"] = "这可是个难得的机会，你们可要好好观摩了。",
            ["ContentFR"] = "C’est une occasion rare. Ouvrez grand les yeux.",
            ["DialogueId"] = 12043819,
            ["GUID"] = "1E26830E",
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120438/1E26830E",
            },
        [12043901] = {
            ["Content"] = "坏鸟、坏鸟！叫你成天得意洋洋，这下阴沟里翻船了吧。以后不许再偷吃我们的药草！",
            ["ContentFR"] = "Sale oiseau ! Ça t’apprendra à faire le malin ! Tu t’attendais pas à ça, hein ? Et maintenant, tu touches plus à nos herbes !",
            ["DialogueId"] = 12043901,
            ["GUID"] = "1E269082",
            ["NextDialogue"] = 12043902,
            ["RelatedWikiId"] = {
                [1] = 203007,
                [2] = 203009,
                [3] = 408018,
                [4] = 103001,
                },
            ["SpeakNpcId"] = 240030,
            ["VoiceName"] = "voice/$Locale$/story/1204/120439/1E269082",
            },
        [12043902] = {
            ["Content"] = "欧——欧欧——",
            ["ContentFR"] = "<I>Ooo—ooooh—</>",
            ["DialogueId"] = 12043902,
            ["GUID"] = "1E2690AC",
            ["NextDialogue"] = 12043903,
            ["SpeakNpcId"] = 240032,
            ["VoiceName"] = "voice/$Locale$/story/1204/120439/1E2690AC",
            },
        [12043903] = {
            ["Content"] = "这只白身苍尾的云翎鸥在你们面前呜咽了两声，灰溜溜地飞走了。",
            ["ContentFR"] = "La Mouette nuageuse à plumage blanc et queue cendrée gémit deux fois... puis s’envole piteusement.",
            ["DialogueId"] = 12043903,
            ["GUID"] = "1E2690D6",
            ["NextDialogue"] = 12043904,
            ["SpeakNpcId"] = 0,
            ["VoiceName"] = "voice/$Locale$/story/1204/120439/1E2690D6",
            },
        [12043904] = {
            ["Content"] = "太厉害了，{nickname}{性别：哥哥|姐姐}！简直是闪电般的身手，我们还没看清楚动作就结束了！",
            ["ContentFR"] = "Incroyable, {性别:Monsieur|Mademoiselle} {nickname} ! C’était comme un éclair — on n’a même pas eu le temps de voir, et c’était fini !",
            ["DialogueId"] = 12043904,
            ["GUID"] = "1E269100",
            ["NextDialogue"] = 12043905,
            ["SpeakNpcId"] = 240031,
            ["VoiceName"] = "voice/$Locale$/story/1204/120439/1E269100",
            },
        [12043905] = {
            ["Content"] = "先别急着高兴——小小一只鸟儿，耗上几天功夫还捉不到。这说明了什么？只能说明你们现在学业不精。",
            ["ContentFR"] = "Pas si vite. Une petite bête comme ça, et vous y passez des jours sans y arriver... ça veut dire quoi ? Ça veut dire que votre niveau n’est pas au point.",
            ["DialogueId"] = 12043905,
            ["GUID"] = "1E26912A",
            ["NextDialogue"] = 12043906,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120439/1E26912A",
            },
        [12043906] = {
            ["Content"] = "阿晨，感应机关的制备材料明明有很多种替代方法。再不济，为牵机鸢加装射击模组，通过手动操控也能将鸟儿抓获。",
            ["ContentFR"] = "Chen. Pour un mécanisme de détection, les matériaux de substitution ne manquent pas. Et au pire, tu équipes un cerf-volant mécanique d’un module de tir, tu le pilotes à la main — et l’affaire est réglée.",
            ["DialogueId"] = 12043906,
            ["GUID"] = "1E269154",
            ["NextDialogue"] = 12043907,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120439/1E269154",
            },
        [12043907] = {
            ["Content"] = "要是思维不够灵活，拘泥于定式中，可没法成长为优秀的机傀师哦。",
            ["ContentFR"] = "Si ton esprit reste figé dans un seul schéma, tu ne deviendras jamais un bon artisan de méchapoupées.",
            ["DialogueId"] = 12043907,
            ["GUID"] = "1E26917E",
            ["NextDialogue"] = 12043908,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120439/1E26917E",
            },
        [12043908] = {
            ["Content"] = "是哦，我怎么没想到呢……",
            ["ContentFR"] = "C’est vrai... comment j’ai pu ne pas y penser...",
            ["DialogueId"] = 12043908,
            ["GUID"] = "1E2691A8",
            ["NextDialogue"] = 12043909,
            ["SpeakNpcId"] = 240031,
            ["VoiceName"] = "voice/$Locale$/story/1204/120439/1E2691A8",
            },
        [12043909] = {
            ["Content"] = "再说你，小野。高明的射手不用说这么近的目标，就算是高空之中几不可见的鸿雁，也能一气呵成地拉弓击坠。你近期的射靶是不是疏于练习了？",
            ["ContentFR"] = "Et toi, Ye. Un bon archer ne rate pas : même une oie à peine visible, haut dans le ciel, il l’abat d’une traite. Tu as négligé l’entraînement au tir, ces derniers temps ?",
            ["DialogueId"] = 12043909,
            ["GUID"] = "1E2691D2",
            ["NextDialogue"] = 12043910,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120439/1E2691D2",
            },
        [12043910] = {
            ["Content"] = "可能是有偷懒了那么几次啦……",
            ["ContentFR"] = "J... j’ai peut-être manqué...  deux-trois séances...",
            ["DialogueId"] = 12043910,
            ["GUID"] = "1E2691FC",
            ["NextDialogue"] = 12043911,
            ["SpeakNpcId"] = 240030,
            ["VoiceName"] = "voice/$Locale$/story/1204/120439/1E2691FC",
            },
        [12043911] = {
            ["Content"] = "自己去武场领三十组射靶训练吧。你们这功夫对上应天尉，连一招都撑不过。",
            ["ContentFR"] = "Trente séries de tir, au terrain d’entraînement. Avec votre niveau actuel, face à un Magistrat de Yingtian, vous ne tiendrez même pas un échange.",
            ["DialogueId"] = 12043911,
            ["GUID"] = "1E269226",
            ["NextDialogue"] = 12043912,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120439/1E269226",
            },
        [12043912] = {
            ["Content"] = "我、我明白了！",
            ["ContentFR"] = "O-oui !",
            ["DialogueId"] = 12043912,
            ["GUID"] = "1E269250",
            ["NextDialogue"] = 12043913,
            ["SpeakNpcId"] = 240030,
            ["VoiceName"] = "voice/$Locale$/story/1204/120439/1E269250",
            },
        [12043913] = {
            ["Content"] = "你们先回去上课吧，我待会儿会来检查你们有没有在好好听讲的。不许一副没精打采的样子，快去！",
            ["ContentFR"] = "Retour en cours. Et je passerai vérifier si vous écoutez correctement. Pas de mines d’enterrement — filez !",
            ["DialogueId"] = 12043913,
            ["GUID"] = "1E26927A",
            ["NextDialogue"] = 12043914,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120439/1E26927A",
            },
        [12043914] = {
            ["Content"] = "知道了，苏乙姐姐……",
            ["ContentFR"] = "D’accord, grande sœur Yi...",
            ["DialogueId"] = 12043914,
            ["GUID"] = "1E2692A4",
            ["NextDialogue"] = 12043915,
            ["SpeakNpcId"] = 240030,
            ["VoiceName"] = "voice/$Locale$/story/1204/120439/1E2692A4",
            },
        [12043915] = {
            ["Content"] = "一打岔差点忘了正事，{nickname}，不好意思，让你见笑了……",
            ["ContentFR"] = "À force d’être interrompue, j’en ai presque oublié pourquoi nous étions venus... {nickname}, désolée pour cette scène.",
            ["DialogueId"] = 12043915,
            ["GUID"] = "1E2692CE",
            ["NextDialogue"] = 12043916,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120439/1E2692CE",
            },
        [12043916] = {
            ["Content"] = "……{nickname}，小白，你们看我的眼神怎么这么犀利？",
            ["ContentFR"] = "... Pourquoi vous me regardez comme ça, {性别:tous|toutes} les deux ?",
            ["DialogueId"] = 12043916,
            ["GUID"] = "1E2692F8",
            ["NextOptions"] = {
                [1] = 12043917,
                [2] = 12043918,
                },
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120439/1E2692F8",
            },
        [12043917] = {
            ["Content"] = "还好我已经不需要上学了。",
            ["ContentFR"] = "<I>Heureusement que je n’ai plus besoin d’aller à l’école.</>",
            ["DialogueId"] = 12043917,
            ["GUID"] = "1E269322",
            ["NextDialogue"] = 12043919,
            },
        [12043918] = {
            ["Content"] = "苏乙，你一定能成为让人闻风丧胆的好老师！",
            ["ContentFR"] = "<I>Su Yi... tu ferais une professeur terrifiblement efficace.</>",
            ["DialogueId"] = 12043918,
            ["GUID"] = "1E26934C",
            ["NextDialogue"] = 12043919,
            },
        [12043919] = {
            ["Content"] = "咳咳，只是山外山的孩子们比较无拘无束。他们大多数因为大风九章失去了父母，所以我才会偶尔替师长管教一下他们……",
            ["ContentFR"] = "<I>Hum...</> Les enfants d’ici sont un peu trop libres. La plupart ont perdu leurs parents à cause des Neuf Chapitres... alors, de temps en temps, je remplace les anciens pour les recadrer.",
            ["DialogueId"] = 12043919,
            ["GUID"] = "1E269376",
            ["NextDialogue"] = 12043920,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120439/1E269376",
            },
        [12043920] = {
            ["Content"] = "好啦，不聊这些了。我们还是赶紧去采药吧！",
            ["ContentFR"] = "Bon, assez parlé. Allons cueillir ces herbes.",
            ["DialogueId"] = 12043920,
            ["GUID"] = "1E2693A0",
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120439/1E2693A0",
            },
        [12044001] = {
            ["Content"] = "唐叔——我和{nickname}去采了些摔伤的药草，特意给你带来了！",
            ["ContentFR"] = "Oncle Tang ! Avec {nickname}, on t’a rapporté des herbes pour les contusions.",
            ["DialogueId"] = 12044001,
            ["GUID"] = "1E26A0EA",
            ["NextDialogue"] = 12044002,
            ["RelatedWikiId"] = {
                [1] = 203007,
                [2] = 203009,
                [3] = 408018,
                [4] = 103001,
                },
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120440/1E26A0EA",
            },
        [12044002] = {
            ["Content"] = "把药草捣碎了和上姜黄粉，再敷上几回，伤就基本好了，你就也能自由走动了。",
            ["ContentFR"] = "Écrase-les, mélange avec de la poudre de curcuma, applique plusieurs fois : ta jambe ira beaucoup mieux. Tu pourras remarcher.",
            ["DialogueId"] = 12044002,
            ["GUID"] = "1E26A114",
            ["NextDialogue"] = 12044003,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120440/1E26A114",
            },
        [12044003] = {
            ["Content"] = "呵呵……小苏还这么记挂着我的伤，真是大家的贴心小棉袄。那我可得赶紧把伤养好，不能让小苏天天操心喽。",
            ["ContentFR"] = "Héhé... Yi se soucie encore de ma jambe. Quelle petite perle, toujours aux petits soins... Allez, je vais vite me remettre, je ne peux pas te laisser t’inquiéter tous les jours.",
            ["DialogueId"] = 12044003,
            ["GUID"] = "1E26A13E",
            ["NextDialogue"] = 12044004,
            ["SpeakNpcId"] = 240029,
            ["VoiceName"] = "voice/$Locale$/story/1204/120440/1E26A13E",
            },
        [12044004] = {
            ["Content"] = "来得正好，这天罗拒风仪的调校工具你也一并拿走吧。省得我再找别人捎给你了。",
            ["ContentFR"] = "Et tu arrives à point : prends aussi ces outils de réglage du Voile de Tianluo. Ça m’évitera d’envoyer quelqu’un te les porter.",
            ["DialogueId"] = 12044004,
            ["GUID"] = "1E26A168",
            ["NextDialogue"] = 12044005,
            ["SpeakNpcId"] = 240029,
            ["VoiceName"] = "voice/$Locale$/story/1204/120440/1E26A168",
            },
        [12044005] = {
            ["Content"] = "天罗拒风仪……那是什么呀？",
            ["ContentFR"] = "Le Voile de Tianluo... c’est quoi, ça ?",
            ["DialogueId"] = 12044005,
            ["GUID"] = "1E26A192",
            ["NextDialogue"] = 12044006,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120440/1E26A192",
            },
        [12044006] = {
            ["Content"] = "小白，快别问——！唉，来不及了。",
            ["ContentFR"] = "Snow, ne demande—! ... Trop tard.",
            ["DialogueId"] = 12044006,
            ["GUID"] = "1E26A1BC",
            ["NextDialogue"] = 12044007,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120440/1E26A1BC",
            },
        [12044007] = {
            ["Content"] = "那是机枢派的得意之作。就算是路边碰见的一条大黄狗，唐叔也得拉住它叨叨个半天原理。你这样一问，他更是三天三夜都说不完了。",
            ["ContentFR"] = "C’est le chef-d’œuvre de la Secte Jishu. Oncle Tang pourrait attraper un chien errant dans la rue juste pour lui expliquer le principe pendant des heures. Alors là... si tu lui poses la question, il en a pour trois jours et trois nuits.",
            ["DialogueId"] = 12044007,
            ["GUID"] = "1E26A1E6",
            ["NextDialogue"] = 12044008,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120440/1E26A1E6",
            },
        [12044008] = {
            ["Content"] = "哪有小苏说的这么夸张！",
            ["ContentFR"] = "Elle exagère !",
            ["DialogueId"] = 12044008,
            ["GUID"] = "1E26A210",
            ["NextDialogue"] = 12044009,
            ["SpeakNpcId"] = 240029,
            ["VoiceName"] = "voice/$Locale$/story/1204/120440/1E26A210",
            },
        [12044009] = {
            ["Content"] = "咳咳，不过年轻人有求知欲是好事。唐叔今天就给你们浅上一课，讲讲这天罗拒风仪的来龙去脉。话得从我年轻学艺时说起——",
            ["ContentFR"] = "<I>Hum !</> Mais la curiosité, c’est une qualité. Aujourd’hui, je vais vous faire un petit cours : l’histoire et le fonctionnement du Voile de Tianluo. Tout a commencé quand j’étais encore apprenti—",
            ["DialogueId"] = 12044009,
            ["GUID"] = "1E26A23A",
            ["NextDialogue"] = 12044010,
            ["SpeakNpcId"] = 240029,
            ["VoiceName"] = "voice/$Locale$/story/1204/120440/1E26A23A",
            },
        [12044010] = {
            ["Content"] = "天罗拒风仪是机枢派为了切断大风九章的感应能力，众人合力潜心研究出的装置。其原理是把区域中的香完全滤净，同时反制一种欺骗信号。",
            ["ContentFR"] = "Le Voile de Tianluo est un dispositif conçu par la Secte Jishu pour couper la capacité de repérage des Neuf Chapitres de Dafeng. Son principe : filtrer totalement l’encens de la zone, et émettre en parallèle un signal leurre.",
            ["DialogueId"] = 12044010,
            ["GUID"] = "1E26A264",
            ["NextDialogue"] = 12044011,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120440/1E26A264",
            },
        [12044011] = {
            ["Content"] = "大风九章失去了承载的介质，就失去了对这片区域的实际感知。而欺骗信号又能阻止龙神察觉到这片区域的空白。",
            ["ContentFR"] = "Sans ce support, les Neuf Chapitres perdent toute perception concrète de la zone. Et le signal leurre empêche le Seigneur Dragon d’Argent de remarquer ce « vide ».",
            ["DialogueId"] = 12044011,
            ["GUID"] = "1E26A28E",
            ["NextDialogue"] = 12044012,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120440/1E26A28E",
            },
        [12044012] = {
            ["Content"] = "有了这个装置，我们飘零人终于不用频繁转移地点，可以在山外山扎根发展了。好了唐叔，原理我替你讲完了。",
            ["ContentFR"] = "Grâce à ça, nous, les Vagabonds, on n’a plus besoin de déplacer la base sans arrêt : on peut enfin s’installer et bâtir ici. Voilà, Oncle Tang — j’ai fait le cours à ta place.",
            ["DialogueId"] = 12044012,
            ["GUID"] = "1E26A2B8",
            ["NextDialogue"] = 12044013,
            ["RelatedWikiId"] = {
                [1] = 403008,
                },
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120440/1E26A2B8",
            },
        [12044013] = {
            ["Content"] = "唉，小苏啊，唐叔生命中的乐趣都要被你剥夺了。",
            ["ContentFR"] = "Ah... Yi... tu me voles un des rares plaisirs de ma vie.",
            ["DialogueId"] = 12044013,
            ["GUID"] = "1E26A2E2",
            ["NextDialogue"] = 12044014,
            ["SpeakNpcId"] = 240029,
            ["VoiceName"] = "voice/$Locale$/story/1204/120440/1E26A2E2",
            },
        [12044014] = {
            ["Content"] = "不用这样说啦唐叔，人家只是怕你说的太累，帮你分担一下而已～",
            ["ContentFR"] = "Mais non, Oncle Tang~ J’avais juste peur que tu te fatigues. Je t’ai aidé, voilà tout~",
            ["DialogueId"] = 12044014,
            ["GUID"] = "1E26A30C",
            ["NextDialogue"] = 12044015,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120440/1E26A30C",
            },
        [12044015] = {
            ["Content"] = "算了算了，你们年轻人做事就是这么风风火火。你们赶紧去调校天罗拒风仪吧，之后得空了再来找唐叔，给你们细细上一上课。",
            ["ContentFR"] = "Bon, bon... vous autres, vous allez toujours trop vite. Allez régler le Voile de Tianluo. Et quand vous aurez du temps, revenez : je vous ferai le vrai cours, en détail.",
            ["DialogueId"] = 12044015,
            ["GUID"] = "1E26A336",
            ["NextDialogue"] = 12044016,
            ["SpeakNpcId"] = 240029,
            ["VoiceName"] = "voice/$Locale$/story/1204/120440/1E26A336",
            },
        [12044016] = {
            ["Content"] = "啊哈哈……有空一定。",
            ["ContentFR"] = "Ah ah... promis, quand on pourra.",
            ["DialogueId"] = 12044016,
            ["GUID"] = "1E26A360",
            ["NextDialogue"] = 12044017,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120440/1E26A360",
            },
        [12044017] = {
            ["Content"] = "那我们走啦，药你别忘了敷哟！",
            ["ContentFR"] = "Allez, on file ! Et n’oublie pas d’appliquer les herbes !",
            ["DialogueId"] = 12044017,
            ["GUID"] = "1E26A38A",
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120440/1E26A38A",
            },
        [12044101] = {
            ["Content"] = "好！这下就大功告成啦。",
            ["ContentFR"] = "Voilà ! Et c’est plié.",
            ["DialogueId"] = 12044101,
            ["GUID"] = "1E26B152",
            ["NextDialogue"] = 12044102,
            ["RelatedWikiId"] = {
                [1] = 203009,
                [2] = 408018,
                [3] = 103001,
                [4] = 403008,
                },
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120441/1E26B152",
            },
        [12044102] = {
            ["Content"] = "小苏，原来你在这儿。你现在有空吗？有件事我有些担忧……",
            ["ContentFR"] = "Yi, te voilà. Tu as un moment ? Il y a quelque chose qui m’inquiète...",
            ["DialogueId"] = 12044102,
            ["GUID"] = "1E26B17C",
            ["NextDialogue"] = 12044103,
            ["SpeakNpcId"] = 240033,
            ["VoiceName"] = "voice/$Locale$/story/1204/120441/1E26B17C",
            },
        [12044103] = {
            ["Content"] = "是阿晨小野那俩小子逃课的事吗？我刚刚在药田将他俩抓了个正着，叮嘱他们回去好好听课呢。",
            ["ContentFR"] = "Chen et Ye, encore ? Je les ai attrapés au champ : je les ai renvoyés en cours, et je leur ai passé un savon.",
            ["DialogueId"] = 12044103,
            ["GUID"] = "1E26B1A6",
            ["NextDialogue"] = 12044104,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120441/1E26B1A6",
            },
        [12044104] = {
            ["Content"] = "呵呵……他们和我说了，这两人倒还是一如既往没心没肺。要只是这种小事就好了。",
            ["ContentFR"] = "Héhé... ils me l’ont déjà dit. Toujours aussi insouciants. Si seulement ce n’était que ça...",
            ["DialogueId"] = 12044104,
            ["GUID"] = "1E26B1D0",
            ["NextDialogue"] = 12044105,
            ["SpeakNpcId"] = 240033,
            ["VoiceName"] = "voice/$Locale$/story/1204/120441/1E26B1D0",
            },
        [12044105] = {
            ["Content"] = "实不相瞒，我有些担心朴儿。他最近把自己关在山洞中，独来独往，也不与同龄人玩耍，只是没日没夜地扑在练武上。",
            ["ContentFR"] = "Pour être franche, je m’inquiète pour Pu. Il s’enferme dans la grotte, reste seul, ne joue plus avec les autres... il ne fait que s’entraîner, jour et nuit.",
            ["DialogueId"] = 12044105,
            ["GUID"] = "1E26B1FA",
            ["NextDialogue"] = 12044106,
            ["SpeakNpcId"] = 240033,
            ["VoiceName"] = "voice/$Locale$/story/1204/120441/1E26B1FA",
            },
        [12044106] = {
            ["Content"] = "这样下去，且不说练武过度会伤筋动骨，心……也会垮。",
            ["ContentFR"] = "À ce rythme, ce n’est pas seulement son corps qui va céder... c’est son cœur aussi.",
            ["DialogueId"] = 12044106,
            ["GUID"] = "1E26B224",
            ["NextDialogue"] = 12044107,
            ["SpeakNpcId"] = 240033,
            ["VoiceName"] = "voice/$Locale$/story/1204/120441/1E26B224",
            },
        [12044107] = {
            ["Content"] = "他为什么要这么拼命？",
            ["ContentFR"] = "Pourquoi il s’acharne autant ?",
            ["DialogueId"] = 12044107,
            ["GUID"] = "1E26B24E",
            ["NextDialogue"] = 12044108,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120441/1E26B24E",
            },
        [12044108] = {
            ["Content"] = "菡姐，这位是{nickname}，我新结识的朋友！{nickname}，这位是山外山中负责给大家讲学的菡姐，你们不要见外。",
            ["ContentFR"] = "Han, voici {nickname}, {性别:un ami|une amie} que je viens de rencontrer. {nickname}, voici Han : elle est chargée d’enseigner ici aux Pics Extérieurs. Inutile de faire des manières.",
            ["DialogueId"] = 12044108,
            ["GUID"] = "1E26B278",
            ["NextDialogue"] = 12044109,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120441/1E26B278",
            },
        [12044109] = {
            ["Content"] = "原来您便是刻舟的那位救命恩人，幸会。",
            ["ContentFR"] = "Alors vous êtes {性别:celui|celle} qui a sauvé Kezhou... enchantée.",
            ["DialogueId"] = 12044109,
            ["GUID"] = "1E26B2A2",
            ["NextDialogue"] = 12044110,
            ["SpeakNpcId"] = 240033,
            ["VoiceName"] = "voice/$Locale$/story/1204/120441/1E26B2A2",
            },
        [12044110] = {
            ["Content"] = "实不相瞒，山外山收留的尽是一些大风九章所不容之人。",
            ["ContentFR"] = "Pour être honnête... les Pics Extérieurs recueillent ceux que les Neuf Chapitres ne tolèrent pas.",
            ["DialogueId"] = 12044110,
            ["GUID"] = "1E26B2CC",
            ["NextDialogue"] = 12044111,
            ["SpeakNpcId"] = 240033,
            ["VoiceName"] = "voice/$Locale$/story/1204/120441/1E26B2CC",
            },
        [12044111] = {
            ["Content"] = "他们有些如刻舟，因自保或助人而触犯大风九章。有些因亲朋蒙冤，不得不投靠山外山，好比小苏。",
            ["ContentFR"] = "Certains, comme Kezhou, ont enfreint les Neuf Chapitres de Dafeng en se défendant ou en protégeant autrui. D’autres, comme Yi, ont dû se réfugier aux Pics Extérieurs après que leurs proches ont été injustement condamnés.",
            ["DialogueId"] = 12044111,
            ["GUID"] = "1E26B2F6",
            ["NextDialogue"] = 12044112,
            ["SpeakNpcId"] = 240033,
            ["VoiceName"] = "voice/$Locale$/story/1204/120441/1E26B2F6",
            },
        [12044112] = {
            ["Content"] = "朴儿也是后者，他的爹娘在他九岁时离世了。这些日子，朴儿总是念叨着要手刃白龙，为爹娘报仇，所以……",
            ["ContentFR"] = "Pu est de ceux-là. Il a perdu ses parents à neuf ans. Et ces temps-ci... il ne parle que de tuer le Seigneur Dragon d’Argent, pour les venger, alors...",
            ["DialogueId"] = 12044112,
            ["GUID"] = "1E26B320",
            ["NextDialogue"] = 12044113,
            ["SpeakNpcId"] = 240033,
            ["VoiceName"] = "voice/$Locale$/story/1204/120441/1E26B320",
            },
        [12044113] = {
            ["Content"] = "他现在还在山洞中练武吗？",
            ["ContentFR"] = "Il est encore dans la grotte à s’entraîner ?",
            ["DialogueId"] = 12044113,
            ["GUID"] = "1E26B34A",
            ["NextDialogue"] = 12044114,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120441/1E26B34A",
            },
        [12044114] = {
            ["Content"] = "嗯。今天天还没亮我就见他一头扎进去，到现在还没出来过。",
            ["ContentFR"] = "Oui. Il y est entré avant l’aube… et il n’en est pas ressorti.",
            ["DialogueId"] = 12044114,
            ["GUID"] = "1E26B374",
            ["NextDialogue"] = 12044115,
            ["SpeakNpcId"] = 240033,
            ["VoiceName"] = "voice/$Locale$/story/1204/120441/1E26B374",
            },
        [12044115] = {
            ["Content"] = "好，我和{nickname}去看看，要是之后有什么进展再告诉你。不用太担心了，这件事我们会妥善解决的。",
            ["ContentFR"] = "D’accord. {nickname} et moi, on va aller voir. S’il y a du nouveau, je te le dirai. Ne t’inquiète pas trop : on va régler ça convenablement.",
            ["DialogueId"] = 12044115,
            ["GUID"] = "1E26B39E",
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120441/1E26B39E",
            },
        [12044201] = {
            ["Content"] = "呵——哈——",
            ["ContentFR"] = "Hyaah— ! Hah— !",
            ["DialogueId"] = 12044201,
            ["GUID"] = "1E26C1BA",
            ["NextDialogue"] = 12044202,
            ["RelatedWikiId"] = {
                [1] = 203009,
                [2] = 408018,
                [3] = 103001,
                [4] = 403008,
                },
            ["SpeakNpcId"] = 240034,
            ["VoiceName"] = "voice/$Locale$/story/1204/120442/1E26C1BA",
            },
        [12044202] = {
            ["Content"] = "呼……呼……",
            ["ContentFR"] = "Hah... hah...",
            ["DialogueId"] = 12044202,
            ["GUID"] = "1E26C1E4",
            ["NextDialogue"] = 12044203,
            ["SpeakNpcId"] = 240034,
            ["VoiceName"] = "voice/$Locale$/story/1204/120442/1E26C1E4",
            },
        [12044203] = {
            ["Content"] = "已经站不起来了吗……",
            ["ContentFR"] = "Déjà incapable de te relever... ?",
            ["DialogueId"] = 12044203,
            ["GUID"] = "1E26C20E",
            ["NextDialogue"] = 12044204,
            ["SpeakNpcId"] = 240034,
            ["VoiceName"] = "voice/$Locale$/story/1204/120442/1E26C20E",
            },
        [12044204] = {
            ["Content"] = "要是连这点小事都办不到，还怎么祭奠阿爹阿娘的在天之灵？站起来继续啊，朱朴！",
            ["ContentFR"] = "Si tu n’es même pas capable de ça... comment honorer l’esprit de père et mère ? Relève-toi, Zhu Pu ! Continue !",
            ["DialogueId"] = 12044204,
            ["GUID"] = "1E26C238",
            ["NextDialogue"] = 12044205,
            ["SpeakNpcId"] = 240034,
            ["VoiceName"] = "voice/$Locale$/story/1204/120442/1E26C238",
            },
        [12044205] = {
            ["Content"] = "（鼓掌声）",
            ["ContentFR"] = "(Applaudissements.)",
            ["DialogueId"] = 12044205,
            ["GUID"] = "1E26C262",
            ["NextDialogue"] = 12044206,
            ["SpeakNpcId"] = 0,
            ["VoiceName"] = "voice/$Locale$/story/1204/120442/1E26C262",
            },
        [12044206] = {
            ["Content"] = "小小年纪能有如此决心，了不起。",
            ["ContentFR"] = "Un tel acharnement à ton âge... c’est impressionnant.",
            ["DialogueId"] = 12044206,
            ["GUID"] = "1E26C28C",
            ["NextDialogue"] = 12044207,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120442/1E26C28C",
            },
        [12044207] = {
            ["Content"] = "……苏乙姐，是你。",
            ["ContentFR"] = "... Grande sœur Yi.",
            ["DialogueId"] = 12044207,
            ["GUID"] = "1E26C2B6",
            ["NextDialogue"] = 12044208,
            ["SpeakNpcId"] = 240034,
            ["VoiceName"] = "voice/$Locale$/story/1204/120442/1E26C2B6",
            },
        [12044208] = {
            ["Content"] = "你也是听了菡姐的话，想过来阻止我的吗？你走吧，你们无论说什么话，我都不会听的。",
            ["ContentFR"] = "Han t’a envoyée pour m’arrêter, c’est ça ? Inutile d’insister. Peu importe ce que vous direz... je n’écouterai pas.",
            ["DialogueId"] = 12044208,
            ["GUID"] = "1E26C2E0",
            ["NextDialogue"] = 12044209,
            ["SpeakNpcId"] = 240034,
            ["VoiceName"] = "voice/$Locale$/story/1204/120442/1E26C2E0",
            },
        [12044209] = {
            ["Content"] = "别急——你不用擅自觉得我和他们是一伙的。",
            ["ContentFR"] = "Du calme — ne va pas croire que je suis venue te faire la leçon comme les autres.",
            ["DialogueId"] = 12044209,
            ["GUID"] = "1E26C30A",
            ["NextDialogue"] = 12044210,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120442/1E26C30A",
            },
        [12044210] = {
            ["Content"] = "你不是一直不满大家不允许你加入外出巡逻的队伍里吗？我现在破格给你一个机会。",
            ["ContentFR"] = "Tu n’arrêtais pas de te plaindre qu’on refuse de t’intégrer aux patrouilles, non ? Eh bien... je vais faire une exception.",
            ["DialogueId"] = 12044210,
            ["GUID"] = "1E26C334",
            ["NextDialogue"] = 12044211,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120442/1E26C334",
            },
        [12044211] = {
            ["Content"] = "只要你能在这位{nickname}{性别：哥哥|姐姐}手下撑过十招，我就认可你能够独当一面了。怎么样？这个要求不过分吧。",
            ["ContentFR"] = "Si tu tiens dix coups face à {nickname}, je reconnaîtrai que tu peux te débrouiller seul. Alors ? Ce n’est pas excessif comme condition.",
            ["DialogueId"] = 12044211,
            ["GUID"] = "1E26C35E",
            ["NextDialogue"] = 12044212,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120442/1E26C35E",
            },
        [12044212] = {
            ["Content"] = "……{nickname}，难道就是那位与太皓正面交过手的……！",
            ["ContentFR"] = "... {nickname} ? {性别:Celui|Celle} qui a affronté Taihao de face... ?",
            ["DialogueId"] = 12044212,
            ["GUID"] = "1E26C388",
            ["NextOptions"] = {
                [1] = 12044213,
                [2] = 12044214,
                },
            ["SpeakNpcId"] = 240034,
            ["VoiceName"] = "voice/$Locale$/story/1204/120442/1E26C388",
            },
        [12044213] = {
            ["Content"] = "刻舟该不会逢人就提我一嘴吧？",
            ["ContentFR"] = "<I>Kezhou raconte vraiment ça à tout le monde ?</>",
            ["DialogueId"] = 12044213,
            ["GUID"] = "1E26C3B2",
            ["NextDialogue"] = 12044215,
            },
        [12044214] = {
            ["Content"] = "怎么又要我出手了？",
            ["ContentFR"] = "<I>Pourquoi c’est toujours moi qui dois me battre... ?</>",
            ["DialogueId"] = 12044214,
            ["GUID"] = "1E26C3DC",
            ["NextDialogue"] = 12044216,
            },
        [12044215] = {
            ["Content"] = "那小子就是嘴上没个把门的，遇到兴奋的事就恨不得马上拿个大喇叭昭告全天下。",
            ["ContentFR"] = "Ce garçon n’a aucun filtre. Dès qu’un truc l’enthousiasme, il serait capable de prendre un mégaphone pour l’annoncer au monde entier.",
            ["DialogueId"] = 12044215,
            ["GUID"] = "1E26C406",
            ["NextDialogue"] = 12044217,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120442/1E26C406",
            },
        [12044216] = {
            ["Content"] = "拜托啦，这个年纪的孩子容易有逆反心理。这时候我们说上一百句话都不如你这外人挥一次剑来得有用。",
            ["ContentFR"] = "S’il te plaît. À cet âge-là, ils ont facilement l’esprit de contradiction. On aurait beau parler cent fois, ça n’aurait pas l’effet d’un seul échange d’épée avec toi.",
            ["DialogueId"] = 12044216,
            ["GUID"] = "1E26C430",
            ["NextDialogue"] = 12044217,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120442/1E26C430",
            },
        [12044217] = {
            ["Content"] = "我明白了，请您赐教。",
            ["ContentFR"] = "Je comprends. Je vous prie de m’enseigner.",
            ["DialogueId"] = 12044217,
            ["GUID"] = "1E26C45A",
            ["SpeakNpcId"] = 240034,
            ["VoiceName"] = "voice/$Locale$/story/1204/120442/1E26C45A",
            },
        [12044301] = {
            ["Content"] = "竟然……就这样输了……",
            ["ContentFR"] = "J’ai... perdu... aussi facilement... ?",
            ["DialogueId"] = 12044301,
            ["GUID"] = "1E26D222",
            ["NextDialogue"] = 12044302,
            ["RelatedWikiId"] = {
                [1] = 203009,
                [2] = 408018,
                [3] = 103001,
                [4] = 403008,
                },
            ["SpeakNpcId"] = 240034,
            ["VoiceName"] = "voice/$Locale$/story/1204/120443/1E26D222",
            },
        [12044302] = {
            ["Content"] = "朱朴，你太操之过急了。在{nickname}手底下，你连三招都撑不了。",
            ["ContentFR"] = "Zhu Pu, tu brûles les étapes. Face à {nickname}, tu n’as même pas tenu trois coups.",
            ["DialogueId"] = 12044302,
            ["GUID"] = "1E26D24C",
            ["NextDialogue"] = 12044303,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120443/1E26D24C",
            },
        [12044303] = {
            ["Content"] = "你现在还如此弱小。等你成长到能和白龙过招的水平，要多久？一个月？半年？一年？还是十年？这十年内，你便要日日如此度过吗？",
            ["ContentFR"] = "Tu es encore trop faible. Combien de temps te faudra-t-il avant de pouvoir seulement croiser le fer avec le Seigneur Dragon d’Argent ? Un mois ? Six ? Un an ? Dix ans ? Et pendant ces dix années... comptes-tu vivre chaque jour ainsi ?",
            ["DialogueId"] = 12044303,
            ["GUID"] = "1E26D276",
            ["NextDialogue"] = 12044304,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120443/1E26D276",
            },
        [12044304] = {
            ["Content"] = "太紧的弦会崩断。仇恨会蒙蔽你的双眼，影响你在战斗中的挥剑，让你无法再做出准确的判断。",
            ["ContentFR"] = "Une corde trop tendue finit par rompre. La haine trouble la vue, alourdit la main, et t’empêche de juger avec justesse.",
            ["DialogueId"] = 12044304,
            ["GUID"] = "1E26D2A0",
            ["NextDialogue"] = 12044305,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120443/1E26D2A0",
            },
        [12044305] = {
            ["Content"] = "给自己一些喘息的时间 ，答应我，好吗？",
            ["ContentFR"] = "Accorde-toi du temps pour respirer. Promets-le-moi.",
            ["DialogueId"] = 12044305,
            ["GUID"] = "1E26D2CA",
            ["NextDialogue"] = 12044306,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120443/1E26D2CA",
            },
        [12044306] = {
            ["Content"] = "在你们面前，少年恍然松开了手中的剑，跪在地上失声痛哭了起来。",
            ["ContentFR"] = "Devant vous, le garçon laisse tomber son épée. Elle résonne contre la pierre. Il s’effondre à genoux... et éclate en sanglots.",
            ["DialogueId"] = 12044306,
            ["GUID"] = "1E26D2F4",
            ["NextDialogue"] = 12044307,
            ["SpeakNpcId"] = 0,
            ["VoiceName"] = "voice/$Locale$/story/1204/120443/1E26D2F4",
            },
        [12044307] = {
            ["Content"] = "那我该怎么办，告诉我啊！我该怎么办！！",
            ["ContentFR"] = "Alors qu’est-ce que je dois faire ? Dis-le-moi ! Qu’est-ce que je dois faire ?!",
            ["DialogueId"] = 12044307,
            ["GUID"] = "1E26D31E",
            ["NextDialogue"] = 12044308,
            ["SpeakNpcId"] = 240034,
            ["VoiceName"] = "voice/$Locale$/story/1204/120443/1E26D31E",
            },
        [12044308] = {
            ["Content"] = "每次我看到小野、阿晨他们那种没心没肺的样子，我就打心底里怕——我怕自己像他们一样快乐，把至今为止的事情都忘得一干二净！",
            ["ContentFR"] = "Chaque fois que je vois Ye et Chen rire comme si tout allait bien... ça me terrifie. J’ai peur de devenir comme eux. Heureux... au point d’oublier.",
            ["DialogueId"] = 12044308,
            ["GUID"] = "1E26D348",
            ["NextDialogue"] = 12044309,
            ["SpeakNpcId"] = 240034,
            ["VoiceName"] = "voice/$Locale$/story/1204/120443/1E26D348",
            },
        [12044309] = {
            ["Content"] = "害得我们家破人亡的骗子还好端端地活在这世上，阿爹阿娘去讨说法，却被狴犴惩戒，就这么伤重不治走了。",
            ["ContentFR"] = "Ceux qui ont détruit notre famille vivent encore, tranquilles. Père et mère ont cherché justice — et ce sont les Bi’an qui les ont frappés... jusqu’à ce qu’ils ne se relèvent plus.",
            ["DialogueId"] = 12044309,
            ["GUID"] = "1E26D372",
            ["NextDialogue"] = 12044310,
            ["SpeakNpcId"] = 240034,
            ["VoiceName"] = "voice/$Locale$/story/1204/120443/1E26D372",
            },
        [12044310] = {
            ["Content"] = "而包庇坏人的大风九章、太皓，依然受到万人顶礼、万人膜拜！",
            ["ContentFR"] = "Et les Neuf Chapitres... Taihao... qui protègent les coupables... continuent d’être vénérés par tous !",
            ["DialogueId"] = 12044310,
            ["GUID"] = "1E26D39C",
            ["NextDialogue"] = 12044311,
            ["SpeakNpcId"] = 240034,
            ["VoiceName"] = "voice/$Locale$/story/1204/120443/1E26D39C",
            },
        [12044311] = {
            ["Content"] = "大家受大风九章的愚弄，偏偏把坏的说成好的，青的说成白的。阿爹阿娘的清白，也就这样洗不清了。",
            ["ContentFR"] = "On avale leurs mensonges sans broncher. On appelle le noir blanc, le mal bien... et le mensonge vérité. Et ainsi, le nom de mes parents restera à jamais souillé.",
            ["DialogueId"] = 12044311,
            ["GUID"] = "1E26D3C6",
            ["NextDialogue"] = 12044312,
            ["SpeakNpcId"] = 240034,
            ["VoiceName"] = "voice/$Locale$/story/1204/120443/1E26D3C6",
            },
        [12044312] = {
            ["Content"] = "我好害怕，苏乙姐，我怕我一觉醒来就忘了。我怕我这辈子都没有能力去报仇，我怕有一天我就像甘愿受大风九章庇护的人一样，度过庸庸碌碌的一生。",
            ["ContentFR"] = "J’ai peur, grande sœur Yi. Peur de me réveiller un jour et d’avoir tout oublié. Peur de ne jamais devenir assez fort pour me venger. Peur de finir comme ceux qui acceptent la protection des Neuf Chapitres... et de mener une vie vide.",
            ["DialogueId"] = 12044312,
            ["GUID"] = "1E26D3F0",
            ["NextDialogue"] = 12044313,
            ["SpeakNpcId"] = 240034,
            ["VoiceName"] = "voice/$Locale$/story/1204/120443/1E26D3F0",
            },
        }
  end },
  { MinKey = 12044313, MaxKey = 12045529, Loader = function()
      return {
        [12044313] = {
            ["Content"] = "到时候，我又该怎么和阿爹阿娘交代，怎么和曾经的自己交代……呜呜……告诉我，我该怎么办……",
            ["ContentFR"] = "Le jour où ça arrivera... comment regarderai-je mes parents en face ? Comment regarderai-je celui que j’étais avant ? ... Dis-moi... que dois-je faire...",
            ["DialogueId"] = 12044313,
            ["GUID"] = "1E26D41A",
            ["NextDialogue"] = 12044314,
            ["SpeakNpcId"] = 240034,
            ["VoiceName"] = "voice/$Locale$/story/1204/120443/1E26D41A",
            },
        [12044314] = {
            ["Content"] = "别哭，朱朴，别哭了……",
            ["ContentFR"] = "Ne pleure pas, Zhu Pu... ne pleure plus...",
            ["DialogueId"] = 12044314,
            ["GUID"] = "1E26D444",
            ["NextDialogue"] = 12044315,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120443/1E26D444",
            },
        [12044315] = {
            ["Content"] = "少年恸哭许久，终于在苏乙的安抚下渐渐平复了情绪。",
            ["ContentFR"] = "Le garçon sanglote longtemps. Peu à peu, sous les gestes apaisants de Su Yi, son souffle se calme.",
            ["DialogueId"] = 12044315,
            ["GUID"] = "1E26D46E",
            ["NextDialogue"] = 12044316,
            ["SpeakNpcId"] = 0,
            ["VoiceName"] = "voice/$Locale$/story/1204/120443/1E26D46E",
            },
        [12044316] = {
            ["Content"] = "朱朴，我懂你的感受……姑姑死之后的一段时间，我也和你有一样的想法。这里每个人都经历过这样夜不能寐的时刻。",
            ["ContentFR"] = "Zhu Pu... je comprends. Après la mort de ma tante... j’ai traversé la même chose. Ici, chacun a connu ces nuits où l’on ne trouve pas le sommeil.",
            ["DialogueId"] = 12044316,
            ["GUID"] = "1E26D498",
            ["NextDialogue"] = 12044317,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120443/1E26D498",
            },
        [12044317] = {
            ["Content"] = "相信我，这里不会有人忘记。飘零人的存在就是为了颠覆这些不公。",
            ["ContentFR"] = "Crois-moi. Personne n’oublie. Si les Vagabonds existent... c’est justement pour renverser ces injustices.",
            ["DialogueId"] = 12044317,
            ["GUID"] = "1E26D4C2",
            ["NextDialogue"] = 12044318,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120443/1E26D4C2",
            },
        [12044318] = {
            ["Content"] = "但是不忘记并不意味着仇恨就是飘零人的全部，更不意味着我们就丧失了快乐的资格。毕竟，大家离开大风九章就是为了更好的生活，不是吗？",
            ["ContentFR"] = "Mais ne pas oublier ne signifie pas se réduire à la haine. Cela ne signifie pas non plus que nous n’avons plus droit au bonheur. Si nous avons quitté les Neuf Chapitres... c’est pour vivre mieux. N’est-ce pas ?",
            ["DialogueId"] = 12044318,
            ["GUID"] = "1E26D4EC",
            ["NextDialogue"] = 12044319,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120443/1E26D4EC",
            },
        [12044319] = {
            ["Content"] = "答应我，照顾好自己的身体，好吗？健健康康地走下去，才能看到报仇雪恨的那天呀。",
            ["ContentFR"] = "Promets-moi de prendre soin de ton corps. Reste en vie. Reste fort. C’est seulement ainsi que tu verras le jour où justice sera rendue.",
            ["DialogueId"] = 12044319,
            ["GUID"] = "1E26D516",
            ["NextDialogue"] = 12044320,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120443/1E26D516",
            },
        [12044320] = {
            ["Content"] = "呜……呜……好的。我不该对菡姐说那些伤人的话，我之后会再找时间和她道歉……",
            ["ContentFR"] = "... D’accord... Je... je n’aurais pas dû parler ainsi à Han. Je m’excuserai auprès d’elle.",
            ["DialogueId"] = 12044320,
            ["GUID"] = "1E26D540",
            ["NextDialogue"] = 12044321,
            ["SpeakNpcId"] = 240034,
            ["VoiceName"] = "voice/$Locale$/story/1204/120443/1E26D540",
            },
        [12044321] = {
            ["Content"] = "放心吧，菡姐只希望你们每一个都平平安安长大，她不会把你的话记在心上的。",
            ["ContentFR"] = "Ne t’inquiète pas. Tout ce qu’elle souhaite, c’est que vous grandissiez en sécurité. Elle ne t’en voudra pas.",
            ["DialogueId"] = 12044321,
            ["GUID"] = "1E26D56A",
            ["NextDialogue"] = 12044322,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120443/1E26D56A",
            },
        [12044322] = {
            ["Content"] = "苏乙姐，还有这位远道而来的{性别：大哥哥|大姐姐}，真的谢谢你们……",
            ["ContentFR"] = "Grande sœur Yi… et vous aussi... merci. Vraiment.",
            ["DialogueId"] = 12044322,
            ["GUID"] = "1E26D594",
            ["NextDialogue"] = 12044323,
            ["SpeakNpcId"] = 240034,
            ["VoiceName"] = "voice/$Locale$/story/1204/120443/1E26D594",
            },
        [12044323] = {
            ["Content"] = "你、你们不用再管我了，我想一个人再静一静……",
            ["ContentFR"] = "Vous pouvez partir. J’aimerais rester seul un moment.",
            ["DialogueId"] = 12044323,
            ["GUID"] = "1E26D5BE",
            ["NextDialogue"] = 12044324,
            ["SpeakNpcId"] = 240034,
            ["VoiceName"] = "voice/$Locale$/story/1204/120443/1E26D5BE",
            },
        [12044324] = {
            ["Content"] = "我们走吧，{nickname}，给他留一些独处的时间。",
            ["ContentFR"] = "Allons-y, {nickname}. Laissons-lui un peu d’espace.",
            ["DialogueId"] = 12044324,
            ["GUID"] = "1E26D5E8",
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120443/1E26D5E8",
            },
        [12044401] = {
            ["Content"] = "这些狴犴，打退一波又来一波，简直没完没了……",
            ["ContentFR"] = "Ils n’en finissent pas... On les repousse, et ils reviennent encore !",
            ["DialogueId"] = 12044401,
            ["GUID"] = "1E26E28A",
            ["NextDialogue"] = 12044402,
            ["RelatedWikiId"] = {
                [1] = 203007,
                [2] = 203009,
                [3] = 408018,
                [4] = 103001,
                },
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120444/1E26E28A",
            },
        [12044402] = {
            ["Content"] = "这么多年来，山外山的坐标一直隐藏得很好。今日怎么会突然暴露？！小苏，你找到缘由了吗？",
            ["ContentFR"] = "On a gardé notre position secrète pendant des années... Comment ont-ils pu la découvrir ? Yi, tu as trouvé quelque chose ?",
            ["DialogueId"] = 12044402,
            ["GUID"] = "1E26E2B4",
            ["NextDialogue"] = 12044403,
            ["SpeakNpcId"] = 240035,
            ["VoiceName"] = "voice/$Locale$/story/1204/120444/1E26E2B4",
            },
        [12044403] = {
            ["Content"] = "我、我不知道……天罗拒风仪我今天还调校过，是完好的……",
            ["ContentFR"] = "Je... je ne comprends pas... J’ai calibré le Voile de Tianluo aujourd’hui même. Il fonctionnait parfaitement...",
            ["DialogueId"] = 12044403,
            ["GUID"] = "1E26E2DE",
            ["NextDialogue"] = 12044404,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120444/1E26E2DE",
            },
        [12044404] = {
            ["Content"] = "但必须防守好天罗拒风仪，要是它被破坏了，山外山的自保手段就要彻底失效了……！",
            ["ContentFR"] = "Quoi qu’il en soit, il faut protéger le Voile à tout prix. S’il est détruit, notre dernière défense tombe... !",
            ["DialogueId"] = 12044404,
            ["GUID"] = "1E26E308",
            ["NextDialogue"] = 12044424,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120444/1E26E308",
            },
        [12044405] = {
            ["Content"] = "你怎么来了？！",
            ["ContentFR"] = "Qu’est-ce que tu fais ici ?!",
            ["DialogueId"] = 12044405,
            ["GUID"] = "1E26E332",
            ["NextDialogue"] = 12044406,
            ["SpeakNpcId"] = 240035,
            ["VoiceName"] = "voice/$Locale$/story/1204/120444/1E26E332",
            },
        [12044406] = {
            ["Content"] = "……叛徒！！",
            ["ContentFR"] = "... Traître !",
            ["DialogueId"] = 12044406,
            ["GUID"] = "1E26E35C",
            ["NextDialogue"] = 12044407,
            ["SpeakNpcId"] = 240036,
            ["VoiceName"] = "voice/$Locale$/story/1204/120444/1E26E35C",
            },
        [12044407] = {
            ["Content"] = "师兄，这起袭击是你所策划的吗？",
            ["ContentFR"] = "Yuming... c’est toi qui as orchestré cette attaque ?",
            ["DialogueId"] = 12044407,
            ["GUID"] = "1E26E386",
            ["NextDialogue"] = 12044408,
            ["RelatedWikiId"] = {
                [1] = 203004,
                },
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120444/1E26E386",
            },
        [12044408] = {
            ["Content"] = "……我只是奉命而来。",
            ["ContentFR"] = "... Je ne fais qu’exécuter des ordres.",
            ["DialogueId"] = 12044408,
            ["GUID"] = "1E26E3B0",
            ["NextDialogue"] = 12044409,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120444/1E26E3B0",
            },
        [12044409] = {
            ["Content"] = "好你个煜明！出卖基地位置，向你的新主子求荣是吧？",
            ["ContentFR"] = "Yuming ! Tu as vendu notre position pour plaire à tes nouveaux maîtres, c’est ça ?!",
            ["DialogueId"] = 12044409,
            ["GUID"] = "1E26E3DA",
            ["NextDialogue"] = 12044430,
            ["SpeakNpcId"] = 240052,
            ["VoiceName"] = "voice/$Locale$/story/1204/120444/1E26E3DA",
            },
        [12044410] = {
            ["Content"] = "我已经回答过了，我是奉大风九章的旨意，前来征讨飘零人。此外的事，一概不知。",
            ["ContentFR"] = "Je l’ai déjà dit. Je viens sur ordre des Neuf Chapitres pour réprimer les Vagabonds. Pour le reste, je n’en sais rien.",
            ["DialogueId"] = 12044410,
            ["GUID"] = "1E26E404",
            ["NextDialogue"] = 12044411,
            ["SpeakNpcId"] = 210007,
            ["VoiceName"] = "voice/$Locale$/story/1204/120444/1E26E404",
            },
        [12044411] = {
            ["Content"] = "更何况，我皈依大风九章之后，你们不是已经把旧时入口尽数更换了吗？",
            ["ContentFR"] = "Et puis... après mon départ, n’avez-vous pas changé toutes les anciennes entrées ?",
            ["DialogueId"] = 12044411,
            ["GUID"] = "1E26E42E",
            ["NextDialogue"] = 12044412,
            ["SpeakNpcId"] = 210007,
            ["VoiceName"] = "voice/$Locale$/story/1204/120444/1E26E42E",
            },
        [12044412] = {
            ["Content"] = "……不用再说了。师兄，我信你。",
            ["ContentFR"] = "Ça suffit. Je te crois.",
            ["DialogueId"] = 12044412,
            ["GUID"] = "1E26E458",
            ["NextDialogue"] = 12044413,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120444/1E26E458",
            },
        [12044413] = {
            ["Content"] = "现在站在这里的，都是你曾经的同伴、师长、后辈。我们是否有罪，我相信你比任何人都更清楚。",
            ["ContentFR"] = "Tous ceux qui se tiennent ici sont tes anciens compagnons, tes maîtres, tes cadets. Si nous sommes vraiment coupables... tu le sais mieux que quiconque.",
            ["DialogueId"] = 12044413,
            ["GUID"] = "1E26E482",
            ["NextDialogue"] = 12044414,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120444/1E26E482",
            },
        [12044414] = {
            ["Content"] = "师兄，我只问你一次。你确定要对我们挥刀吗？",
            ["ContentFR"] = "Je ne te poserai la question qu’une fois. Es-tu vraiment décidé à lever ton arme contre nous ?",
            ["DialogueId"] = 12044414,
            ["GUID"] = "1E26E4AC",
            ["NextDialogue"] = 12044415,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120444/1E26E4AC",
            },
        [12044415] = {
            ["Content"] = "我……",
            ["ContentFR"] = "Je...",
            ["DialogueId"] = 12044415,
            ["GUID"] = "1E26E4D6",
            ["NextDialogue"] = 12044416,
            ["SpeakNpcId"] = 210007,
            ["VoiceName"] = "voice/$Locale$/story/1204/120444/1E26E4D6",
            },
        [12044416] = {
            ["Content"] = "我不要听大风九章的判断。师兄，我要听“你”出自本心的判断。",
            ["ContentFR"] = "Je ne veux pas entendre le verdict des Neuf Chapitres. Je veux entendre le tien. Celui qui vient du cœur.",
            ["DialogueId"] = 12044416,
            ["GUID"] = "1E26E500",
            ["NextDialogue"] = 12044417,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120444/1E26E500",
            },
        [12044417] = {
            ["Content"] = "飘零人虽屡触天律，但并未犯下大过，也不曾主动戕害无辜。目前的刑罚……重了。",
            ["ContentFR"] = "Les Vagabonds ont enfreint les lois, oui. Mais ils n’ont commis aucun crime grave. Ils n’ont jamais attaqué d’innocents. La sentence... est excessive.",
            ["DialogueId"] = 12044417,
            ["GUID"] = "1E26E52A",
            ["NextDialogue"] = 12044425,
            ["SpeakNpcId"] = 210007,
            ["VoiceName"] = "voice/$Locale$/story/1204/120444/1E26E52A",
            },
        [12044418] = {
            ["Content"] = "既然如此，回来吧，师兄！",
            ["ContentFR"] = "Alors reviens parmi nous, Yuming !",
            ["DialogueId"] = 12044418,
            ["GUID"] = "1E26E554",
            ["NextDialogue"] = 12044419,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120444/1E26E554",
            },
        [12044419] = {
            ["Content"] = "当初<H>那件事</>只是一时意外。若是你沉溺过往，终生被大风九章束缚住了，不夏一定也不想看到你现在这副颓唐模样的！",
            ["ContentFR"] = "Ce qui s’est passé <H>ce jour-là</> n’était qu’un accident. Si tu restes prisonnier du passé, enchaîné aux Neuf Chapitres... Buxia elle-même ne voudrait pas te voir ainsi.",
            ["DialogueId"] = 12044419,
            ["GUID"] = "1E26E57E",
            ["NextDialogue"] = 12044420,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120444/1E26E57E",
            },
        [12044420] = {
            ["Content"] = "……那件事？你竟还敢提那件事。",
            ["ContentFR"] = "... Comment oses-tu parler de ce jour-là ?",
            ["DialogueId"] = 12044420,
            ["GUID"] = "1E26E5A8",
            ["NextDialogue"] = 12044421,
            ["SpeakNpcId"] = 210007,
            ["VoiceName"] = "voice/$Locale$/story/1204/120444/1E26E5A8",
            },
        [12044421] = {
            ["Content"] = "师父、师妹的在天之灵尚未安奠息，一句轻飘飘的意外，难道就能让他们活过来吗？",
            ["ContentFR"] = "Notre maître... Buxia... leurs âmes ne reposent toujours pas en paix. Appeler cela un accident suffirait-il à les ramener ?",
            ["DialogueId"] = 12044421,
            ["GUID"] = "1E26E5D2",
            ["NextDialogue"] = 12044426,
            ["SpeakNpcId"] = 210007,
            ["VoiceName"] = "voice/$Locale$/story/1204/120444/1E26E5D2",
            },
        [12044422] = {
            ["Content"] = "刻舟，当初我叛出飘零人时，就与你提过：从此世上再无煜明，我只是一介无名无姓的应天尉罢了。",
            ["ContentFR"] = "Kezhou... le jour où j’ai quitté les Vagabonds, je te l’ai dit : Yuming n’existe plus. Je ne suis qu’un Magistrat de Yingtian, sans nom.",
            ["DialogueId"] = 12044422,
            ["GUID"] = "1E26E5FC",
            ["NextDialogue"] = 12044427,
            ["SpeakNpcId"] = 210007,
            ["VoiceName"] = "voice/$Locale$/story/1204/120444/1E26E5FC",
            },
        [12044423] = {
            ["Content"] = "拔出你们的剑吧，我不对无刃之人出手。",
            ["ContentFR"] = "Dégainons. Je ne frappe pas ceux qui restent désarmés.",
            ["DialogueId"] = 12044423,
            ["GUID"] = "1E26E626",
            ["SpeakNpcId"] = 210007,
            ["VoiceName"] = "voice/$Locale$/story/1204/120444/1E26E626",
            },
        [12044424] = {
            ["Content"] = "......",
            ["ContentFR"] = "... Incroyable... Comment a-t-il pu... ?",
            ["DialogueId"] = 12044424,
            ["GUID"] = "12044424.0",
            ["NextDialogue"] = 12044405,
            ["SpeakNpcId"] = 240035,
            ["VoiceName"] = "voice/$Locale$/story/1204/120418/1E2537FA",
            },
        [12044425] = {
            ["Content"] = "......",
            ["DialogueId"] = 12044425,
            ["GUID"] = "12044425.0",
            ["NextDialogue"] = 12044418,
            },
        [12044426] = {
            ["Content"] = "......",
            ["DialogueId"] = 12044426,
            ["GUID"] = "12044426.0",
            ["NextDialogue"] = 12044422,
            },
        [12044427] = {
            ["Content"] = "......",
            ["DialogueId"] = 12044427,
            ["GUID"] = "12044427.0",
            ["NextDialogue"] = 12044428,
            },
        [12044428] = {
            ["Content"] = "......",
            ["DialogueId"] = 12044428,
            ["GUID"] = "12044428.0",
            ["NextDialogue"] = 12044429,
            },
        [12044429] = {
            ["Content"] = "......",
            ["DialogueId"] = 12044429,
            ["GUID"] = "12044429.0",
            ["NextDialogue"] = 12044423,
            },
        [12044430] = {
            ["Content"] = "......",
            ["DialogueId"] = 12044430,
            ["GUID"] = "12044430.0",
            ["NextDialogue"] = 12044410,
            },
        [12044501] = {
            ["Content"] = "抱歉，突然把你拽来了这里。",
            ["ContentFR"] = "Désolée de t’avoir entraîné ici sans prévenir.",
            ["DialogueId"] = 12044501,
            ["FacialId"] = {
                [1] = "240026:Serious",
                },
            ["GUID"] = "1E26F2F2",
            ["NextDialogue"] = 12044502,
            ["SpeakNpcId"] = 240026,
            ["TalkActionId"] = {
                [1] = "240026:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120445/1E26F2F2",
            },
        [12044502] = {
            ["Content"] = "根据我的计算……继续抵抗下去，胜算不足一成。",
            ["ContentFR"] = "D’après mes calculs... si on continue à résister de front, nos chances de victoire ne dépassent pas dix pour cent.",
            ["DialogueId"] = 12044502,
            ["GUID"] = "1E26F31C",
            ["NextDialogue"] = 12044503,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120445/1E26F31C",
            },
        [12044503] = {
            ["Content"] = "对面是守卫执律阁和大风九章中枢的钧天铁卫，实力远非普通应天尉可比，而且大风九章会为他们提供源源不断的支持。",
            ["ContentFR"] = "En face, ce ne sont pas de simples Magistrats. Ce sont les Sentinelles de Fer de Juntian — l’élite qui protège le Pavillon de l’Arbitrage et le cœur des Neuf Chapitres. Leur puissance dépasse largement celle d’un Magistrat ordinaire, et les Neuf Chapitres leur fourniront des renforts sans relâche.",
            ["DialogueId"] = 12044503,
            ["GUID"] = "1E26F346",
            ["NextDialogue"] = 12044504,
            ["RelatedWikiId"] = {
                [1] = 405016,
                },
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120445/1E26F346",
            },
        [12044504] = {
            ["Content"] = "但飘零人都是血肉之躯，受了伤需要时间恢复……这样消耗下去，山外山很快就会支持不住的。",
            ["ContentFR"] = "Nous, les Vagabonds, sommes faits de chair et de sang. Une blessure demande du temps pour guérir... À ce rythme, les Pics Extérieurs ne tiendront pas longtemps.",
            ["DialogueId"] = 12044504,
            ["GUID"] = "1E26F370",
            ["NextDialogue"] = 12044505,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120445/1E26F370",
            },
        [12044505] = {
            ["Content"] = "我不想只能看着他们交手……我要兵行险着，赌一把。",
            ["ContentFR"] = "Je refuse de rester là à regarder les autres s’épuiser. Je vais tenter un coup risqué.",
            ["DialogueId"] = 12044505,
            ["FinalDialogueId"] = 12044514,
            ["GUID"] = "1E26F39A",
            ["NextOptions"] = {
                [1] = 12044506,
                [2] = 12044507,
                },
            ["SpeakNpcId"] = 240026,
            ["TalkActionId"] = {
                [1] = "240026:Explain01_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120445/1E26F39A",
            },
        [12044506] = {
            ["Content"] = "这里是什么地方？",
            ["ContentFR"] = "<I>Où sommes-nous exactement ?</>",
            ["DialogueId"] = 12044506,
            ["GUID"] = "1E26F3C4",
            ["NextDialogue"] = 12044508,
            },
        [12044507] = {
            ["Content"] = "你的办法是什么？",
            ["ContentFR"] = "<I>Quel est ton plan ?</>",
            ["DialogueId"] = 12044507,
            ["GUID"] = "1E26F3EE",
            ["NextDialogue"] = 12044511,
            },
        [12044508] = {
            ["Content"] = "这里是偃隐宫，机枢派先人铸造的地宫。",
            ["ContentFR"] = "Ici, c’est le Labyrinthe de Yanyin — un sanctuaire souterrain bâti par les anciens de la Secte Jishu.",
            ["DialogueId"] = 12044508,
            ["GUID"] = "1E26F418",
            ["NextDialogue"] = 12044509,
            ["RelatedWikiId"] = {
                [1] = 408019,
                },
            ["SpeakNpcId"] = 240026,
            ["TalkActionId"] = {
                [1] = "240026:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120445/1E26F418",
            },
        [12044509] = {
            ["Content"] = "上古鼎盛时期的机枢派能人辈出。那时最厉害的机傀大如鲲鹏，行于凌霄之上，足以遮天蔽日！可惜，那些伟大的造物，都在黍离之战后被毁之一炬了。",
            ["ContentFR"] = "À l’époque de sa splendeur, la Secte Jishu regorgeait de génies. Leurs plus puissantes créations étaient vastes comme des îles, planant dans les cieux et voilant le soleil de leur ombre. Hélas... ces merveilles furent réduites en cendres après la Bataille de Shuli.",
            ["DialogueId"] = 12044509,
            ["GUID"] = "1E26F442",
            ["NextDialogue"] = 12044510,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120445/1E26F442",
            },
        [12044510] = {
            ["Content"] = "这处地宫也是那时留下的遗产。我们飘零人正是为了破解它的奥秘，才把新基地建在这处悬崖峭壁之中。",
            ["ContentFR"] = "Ce labyrinthe souterrain est l’un des rares vestiges de cette époque. Si nous avons établi notre base dans ces falaises, c’est justement pour en percer les secrets.",
            ["DialogueId"] = 12044510,
            ["GUID"] = "1E26F46C",
            ["NextDialogue"] = 12044505,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120445/1E26F46C",
            },
        [12044511] = {
            ["Content"] = "传闻，在这偃隐宫的深处，机枢派的先人留下了某样足以扭转局势的宝物。",
            ["ContentFR"] = "On raconte qu’au plus profond du Labyrinthe de Yanyin, les anciens ont laissé un artefact capable de renverser le cours d’une bataille.",
            ["DialogueId"] = 12044511,
            ["GUID"] = "1E26F496",
            ["NextDialogue"] = 12044512,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120445/1E26F496",
            },
        [12044512] = {
            ["Content"] = "只是这么多年来，没有人能够成功破解防御机制，抵达终点。我之前尝试了几次，都以失败告终。",
            ["ContentFR"] = "Mais depuis des années, personne n’a réussi à franchir ses mécanismes de défense. J’ai essayé plusieurs fois... sans succès.",
            ["DialogueId"] = 12044512,
            ["GUID"] = "1E26F4C0",
            ["NextDialogue"] = 12044513,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120445/1E26F4C0",
            },
        [12044513] = {
            ["Content"] = "但现在有了你的帮助，我想再尝试一把……万一这次就成功了呢！",
            ["ContentFR"] = "Aujourd’hui, avec ton aide... je veux tenter à nouveau. Qui sait ? Peut-être que cette fois...",
            ["DialogueId"] = 12044513,
            ["GUID"] = "1E26F4EA",
            ["NextDialogue"] = 12044505,
            ["SpeakNpcId"] = 240026,
            ["TalkActionId"] = {
                [1] = "240026:Explain01_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120445/1E26F4EA",
            },
        [12044514] = {
            ["Content"] = "我明白了。",
            ["ContentFR"] = "Je comprends.",
            ["DialogueId"] = 12044514,
            ["GUID"] = "1E26F514",
            ["NextDialogue"] = 12044515,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120445/1E26F514",
            },
        [12044515] = {
            ["Content"] = "大家还在外面苦苦抵抗，时间紧迫，我们赶紧出发吧！",
            ["ContentFR"] = "Les autres se battent encore dehors. Chaque seconde compte — avançons.",
            ["DialogueId"] = 12044515,
            ["FacialId"] = {
                [1] = "240026:Smile01",
                },
            ["GUID"] = "1E26F53E",
            ["NextDialogue"] = 12044516,
            ["SpeakNpcId"] = 240026,
            ["TalkActionId"] = {
                [1] = "240026:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120445/1E26F53E",
            },
        [12044516] = {
            ["Content"] = "如果最终失败了，我只是说如果……那我们还来得及出去，重新加入他们的战线。",
            ["ContentFR"] = "Si nous échouons — je dis bien si — nous pourrons encore revenir les rejoindre.",
            ["DialogueId"] = 12044516,
            ["GUID"] = "1E26F568",
            ["NextDialogue"] = 12044517,
            ["SpeakNpcId"] = 240026,
            ["TalkActionId"] = {
                [1] = "240026:Explain01_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120445/1E26F568",
            },
        [12044517] = {
            ["Content"] = "这种时候就别说丧气话啦。魔王大人和小仆从搭档至今，就还没有破解不了的迷宫！放心，包在我们身上了！",
            ["ContentFR"] = "Hé ! Pas de discours défaitiste ! Le Roi Démon et son fidèle petit larbin n’ont jamais laissé un labyrinthe leur résister. Laisse-nous faire !",
            ["DialogueId"] = 12044517,
            ["GUID"] = "1E26F592",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120445/1E26F592",
            },
        [12044601] = {
            ["Content"] = "这……我曾在古籍中读过它的作用！",
            ["ContentFR"] = "Ceci... je l’ai lu dans les anciens traités !",
            ["DialogueId"] = 12044601,
            ["GUID"] = "1E27035A",
            ["NextDialogue"] = 12044602,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120446/1E27035A",
            },
        [12044602] = {
            ["Content"] = "它叫做牵机方枢·却邪。它射出的光束能激活别的机枢派造物，使其依照规则而变。",
            ["ContentFR"] = "Il s’agit du Nexus mécanique : Fléau des Souillures. Le rayon qu’il émet peut activer d’autres créations de la Secte Jishu et les transformer selon leurs lois internes.",
            ["DialogueId"] = 12044602,
            ["GUID"] = "1E270384",
            ["NextDialogue"] = 12044603,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120446/1E270384",
            },
        [12044603] = {
            ["Content"] = "好耶，是大宝贝！小仆从，我们赶紧试试它的效果吧！",
            ["ContentFR"] = "Youpi ! Un trésor ! Petit larbin, essayons-le tout de suite !",
            ["DialogueId"] = 12044603,
            ["GUID"] = "1E2703AE",
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120446/1E2703AE",
            },
        [12044701] = {
            ["Content"] = "\"吾平生碌碌，壮志不酬。追忆往昔，唯留憾恨。怀一密辛，关乎天下鼎革，恐言发而祸至，又不忍其泯于尘埃。遂藏之重楼，望后来者令其复启于天日。\
今汝既见此碑，必已通吾所设机枢之试。继之，<H>使塔中巨枢复位，玄机自现</>。吾毕生心血所铸神兵，亦当奉上。望汝持此神兵，匡时济世，勿蹈吾之覆辙。\"",
            ["ContentFR"] = "Toute ma vie, je me suis agité sans jamais accomplir mes grandes ambitions. Lorsque je me retourne sur le passé, il ne me reste que des regrets amers.\
Je porte un secret capable d’ébranler l’ordre du monde. Le révéler attirerait le malheur ; le laisser sombrer dans l’oubli m’est insupportable.\
Je l’ai donc scellé dans cette haute tour, espérant qu’un successeur digne le ramènerait un jour à la lumière.\
Vous qui lisez ces mots, vous avez franchi les épreuves que j’ai laissées derrière moi.\
À présent, <H>rétablissez le grand axe au cœur de la tour, et la vérité se dévoilera</>.\
L’arme divine façonnée par le labeur de toute ma vie vous sera également confiée.\
Puissiez-vous la brandir pour redresser votre temps et secourir les êtres sous le ciel — et ne pas suivre la voie qui mena à ma perte.",
            ["DialogueId"] = 12044701,
            ["GUID"] = "1E2713C2",
            ["NextDialogue"] = 12044703,
            ["SpeakNpcId"] = 0,
            ["VoiceName"] = "voice/$Locale$/story/1204/120447/1E2713C2",
            },
        [12044703] = {
            ["Content"] = "唔，抛开那些很难懂的部分不管……本魔王敏锐地察觉到了神兵的存在！",
            ["ContentFR"] = "Bon... je n’ai pas tout compris aux passages compliqués... mais mon radar de Roi Démon s’est activé : il y a une arme divine ici !",
            ["DialogueId"] = 12044703,
            ["GUID"] = "1E271416",
            ["NextDialogue"] = 12044704,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120447/1E271416",
            },
        [12044704] = {
            ["Content"] = "太好了，这说明我们来对地方了。",
            ["ContentFR"] = "Parfait. On est donc au bon endroit.",
            ["DialogueId"] = 12044704,
            ["GUID"] = "1E271440",
            ["NextDialogue"] = 12044705,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120447/1E271440",
            },
        [12044705] = {
            ["Content"] = "嗯，接下来只要<H>复原高塔的中轴</>，就能触及最后的答案了。",
            ["ContentFR"] = "Oui. Il ne nous reste plus qu’à <H>remettre en place l’axe central de la tour</>. Ensuite... la réponse finale se révélera.",
            ["DialogueId"] = 12044705,
            ["GUID"] = "1E27146A",
            ["NextDialogue"] = 12044706,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120447/1E27146A",
            },
        [12044706] = {
            ["Content"] = "走吧。大家还在外面和应天尉奋战，我们也要加快脚步！",
            ["ContentFR"] = "Allons-y. Les autres affrontent encore les Magistrats de Yingtian dehors. Nous devons accélérer.",
            ["DialogueId"] = 12044706,
            ["GUID"] = "1E271494",
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120447/1E271494",
            },
        [12044801] = {
            ["Content"] = "真是的，非要设置这么多重考验，还得是我和小仆从。要是一般人来，早就被拦在外面了。",
            ["ContentFR"] = "Sérieusement... avec toutes ces épreuves, seuls moi et mon petit larbin pouvions arriver jusque-là. Un aventurier ordinaire aurait abandonné depuis longtemps !",
            ["DialogueId"] = 12044801,
            ["GUID"] = "1E27242A",
            ["NextDialogue"] = 12044802,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120448/1E27242A",
            },
        [12044802] = {
            ["Content"] = "千辛万苦来到这儿，也该有点传说中的宝藏了吧？最好不要让白魔王大人失望！",
            ["ContentFR"] = "Après tant d’efforts, il y a intérêt à ce qu’un trésor légendaire nous attende. Ne déçois pas le Roi Démon !",
            ["DialogueId"] = 12044802,
            ["GUID"] = "1E272454",
            ["NextDialogue"] = 12044803,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120448/1E272454",
            },
        [12044803] = {
            ["ContentFR"] = "C’est... une autre stèle.",
            ["DialogueId"] = 12044803,
            ["GUID"] = "1E27247E",
            ["NextDialogue"] = 12044804,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120448/1E27247E",
            },
        [12044804] = {
            ["Content"] = "\"幸哉！汝既历劫至此，终抵此境。吾积年幽怀，亦可昭彰于天日矣。",
            ["ContentFR"] = "Heureux soyez-vous ! Après avoir traversé tant d’épreuves, vous voilà parvenu ici. Les regrets que j’ai portés durant des années peuvent enfin être exposés à la lumière du ciel. Lors de la Bataille de Shuli, les Sectes Jishu et Xuanheng subirent des pertes innombrables. Depuis la fondation de Huaxu, nul désastre n’avait été d’une telle ampleur. Le ciel semblait saigner, les montagnes prirent le deuil. Les Neuf Chapitres eux-mêmes durcirent leurs lois à la suite de cette tragédie.\
Le monde affirme que Jishu déclencha la guerre et mérita son sort. Mais ce jugement rétrospectif est erroné.\
Je me souviens encore : notre commandant, mortellement blessé, me transmit un dernier message.\
« Jamais Jishu n’a cherché la guerre. Ce jour-là, un épais brouillard recouvrait le champ de bataille. Un automate de guerre perdit le contrôle. Chaque camp, croyant l’autre responsable, dégaina dans la peur. Craignant l’anéantissement, tous combattirent sans retenue. Nul ne put arrêter l’engrenage du désastre. »\
Qui aurait cru une telle vérité ? La fracture entre Jishu et Xuanheng était déjà trop profonde. Parler n’aurait fait qu’accélérer ma mort.\
\
J’ai donc gardé le silence... et enfoui ce secret, en attendant un successeur.\
Cette moitié de Jade de l’Équilibre était jadis un symbole de Jishu. Son pouvoir étant épuisé, et refusant qu’elle tombe entre les mains de Xuanheng, je l’ai dissimulée ici.\
Le <H>Canon Céleste Mécanique</> — fruit de toute ma vie — repose hors des portes du Labyrinthe de Yanyin. Prenez la clé mécanique devant cette stèle et usez-en avec discernement. Nous n’aurons pas vécu assez longtemps pour voir la réconciliation des deux sectes. Mais j’espère que vous hériterez de cette volonté : réparer les fractures des hommes et restaurer l’harmonie des anciens temps.\
Je vous en conjure.",
            ["DialogueId"] = 12044804,
            ["DialoguePanelType"] = "{type:showtext;topic:READ_NAME_2000117;content:READ_TEXT_2000049}",
            ["GUID"] = "1E2724A8",
            ["NextDialogue"] = 12044813,
            ["SpeakNpcId"] = 0,
            ["VoiceName"] = "voice/$Locale$/story/1204/120448/1E2724A8",
            },
        [12044805] = {
            ["Content"] = "黍离之役，机枢与悬衡两派皆死伤无算。自华胥开国以来，未有此等大劫难，天地为之泣血。山川缟素，桃李含悲，大风九章亦由此易弦更张，为之一肃。",
            ["DialogueId"] = 12044805,
            ["GUID"] = "1E2724D2",
            ["NextDialogue"] = 12044806,
            ["SpeakNpcId"] = 0,
            ["VoiceName"] = "voice/$Locale$/story/1204/120448/1E2724D2",
            },
        [12044806] = {
            ["Content"] = "至于此难由何而起，世皆谓我机枢启衅，罪有应得。",
            ["DialogueId"] = 12044806,
            ["GUID"] = "1E2724FC",
            ["NextDialogue"] = 12044807,
            ["SpeakNpcId"] = 0,
            ["VoiceName"] = "voice/$Locale$/story/1204/120448/1E2724FC",
            },
        [12044807] = {
            ["Content"] = "然此乃后见之言，非是也。",
            ["DialogueId"] = 12044807,
            ["GUID"] = "1E272526",
            ["NextDialogue"] = 12044808,
            ["SpeakNpcId"] = 0,
            ["VoiceName"] = "voice/$Locale$/story/1204/120448/1E272526",
            },
        [12044808] = {
            ["Content"] = "犹记两派乱战，机枢一派领兵之主伤重将死，气息尚存之际传密讯于吾，曰：机枢一派从未妄开兵燹！皆因是日晦，雾如笼纱，恰一偃甲偶失制御，两派人马皆惊，以为宿怨激发，遂相互以白刃相见。方其时，两派俱恐为对方所灭，不敢不用其全力抗敌，无人可制，终有此劫。",
            ["DialogueId"] = 12044808,
            ["GUID"] = "1E272550",
            ["NextDialogue"] = 12044809,
            ["SpeakNpcId"] = 0,
            ["VoiceName"] = "voice/$Locale$/story/1204/120448/1E272550",
            },
        [12044809] = {
            ["Content"] = "然此间曲折，纵说与世人听之，孰可采信？机枢、悬衡二派，嫌隙已深，万难冰释。言出非但不能明志，徒惹杀身之祸。是以吾缄默不语，隐此秘辛，以俟来者。",
            ["DialogueId"] = 12044809,
            ["GUID"] = "1E27257A",
            ["NextDialogue"] = 12044810,
            ["SpeakNpcId"] = 0,
            ["VoiceName"] = "voice/$Locale$/story/1204/120448/1E27257A",
            },
        [12044810] = {
            ["Content"] = "此半壁均天玉律，本为机枢信物。余知其功用已尽，又不忍见没于悬衡之手，故藏于兹。",
            ["DialogueId"] = 12044810,
            ["GUID"] = "1E2725A4",
            ["NextDialogue"] = 12044811,
            ["SpeakNpcId"] = 0,
            ["VoiceName"] = "voice/$Locale$/story/1204/120448/1E2725A4",
            },
        [12044811] = {
            ["Content"] = "吾平生沥血所铸之<H>神机铳</>，长眠于偃隐宫外。得见此文者，可取碑前偃钥善用之。",
            ["DialogueId"] = 12044811,
            ["GUID"] = "1E2725CE",
            ["NextDialogue"] = 12044812,
            ["SpeakNpcId"] = 0,
            ["VoiceName"] = "voice/$Locale$/story/1204/120448/1E2725CE",
            },
        [12044812] = {
            ["Content"] = "吾辈避世抱憾，难见二派弥合，唯愿后人承此遗志，修世人之罅隙，复上古之敦睦！切望！\"",
            ["DialogueId"] = 12044812,
            ["GUID"] = "1E2725F8",
            ["NextDialogue"] = 12044813,
            ["SpeakNpcId"] = 0,
            ["VoiceName"] = "voice/$Locale$/story/1204/120448/1E2725F8",
            },
        [12044813] = {
            ["Content"] = "咦，小仆从，石碑前的这半块东西，和之前白龙受伤逃离时掉落的那玩意儿，好像刚刚好可以拼在一起耶！",
            ["ContentFR"] = "Eh, petit larbin ! Cette moitié de jade... c’est exactement la même que celle que le Seigneur Dragon d’Argent a laissée tomber quand il s’est enfui !",
            ["DialogueId"] = 12044813,
            ["GUID"] = "1E272622",
            ["NextDialogue"] = 12044814,
            ["RelatedWikiId"] = {
                [1] = 401003,
                },
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120448/1E272622",
            },
        [12044814] = {
            ["Content"] = "神机铳……难道说是……",
            ["ContentFR"] = "Le Canon Céleste... alors c’était bien cela.",
            ["DialogueId"] = 12044814,
            ["GUID"] = "1E27264C",
            ["NextDialogue"] = 12044815,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120448/1E27264C",
            },
        [12044815] = {
            ["Content"] = "苏乙，你找到你想要的东西了吗？",
            ["ContentFR"] = "Su Yi. As-tu trouvé ce que tu cherchais ?",
            ["DialogueId"] = 12044815,
            ["GUID"] = "1E272676",
            ["NextDialogue"] = 12044816,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120448/1E272676",
            },
        [12044816] = {
            ["Content"] = "没错，这一定就是致胜的奇招……太好了，{nickname}，果然有了你的帮助，我们就一定能够做到的！",
            ["ContentFR"] = "Oui. C’est l’atout décisif qu’il nous fallait. {nickname}... je le savais. Avec toi à nos côtés, nous y arriverions.",
            ["DialogueId"] = 12044816,
            ["GUID"] = "1E2726A0",
            ["NextOptions"] = {
                [1] = 12044817,
                [2] = 12044818,
                },
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120448/1E2726A0",
            },
        [12044817] = {
            ["Content"] = "还等什么？",
            ["ContentFR"] = "<I>Alors qu’attendons-nous ?</>",
            ["DialogueId"] = 12044817,
            ["GUID"] = "1E2726CA",
            ["NextDialogue"] = 12044819,
            },
        [12044818] = {
            ["Content"] = "我们走，去终结外面的战斗！",
            ["ContentFR"] = "<I>Allons mettre fin à la bataille dehors.</>",
            ["DialogueId"] = 12044818,
            ["GUID"] = "1E2726F4",
            ["NextDialogue"] = 12044819,
            },
        [12044819] = {
            ["Content"] = "哼哼，辛苦了这么久，白魔王大人也应该有一个潇洒帅气的亮相啦！好好记住我们的英姿吧！",
            ["ContentFR"] = "Héhé ! Après tant d’efforts, le Roi Démon mérite une entrée spectaculaire ! Qu’ils gravent bien notre éclat dans leur mémoire !",
            ["DialogueId"] = 12044819,
            ["GUID"] = "1E27271E",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120448/1E27271E",
            },
        [12044901] = {
            ["Content"] = "好样的，痛快！",
            ["ContentFR"] = "Bien joué ! C’est incroyable !",
            ["DialogueId"] = 12044901,
            ["GUID"] = "1E273492",
            ["NextDialogue"] = 12044902,
            ["RelatedWikiId"] = {
                [1] = 407008,
                [2] = 405010,
                },
            ["SpeakNpcId"] = 240036,
            ["VoiceName"] = "voice/$Locale$/story/1204/120449/1E273492",
            },
        [12044902] = {
            ["Content"] = "哈哈……我机枢派的上古造物终见天日了。怎么样，对面的应天尉，还有胆量来战吗？",
            ["ContentFR"] = "Ha ha... Une création antique de la Secte Jishu revient enfin à la lumière du jour. Alors, Magistrats de Yingtian... vous avez encore le cran de vous battre ?",
            ["DialogueId"] = 12044902,
            ["GUID"] = "1E2734BC",
            ["NextDialogue"] = 12044903,
            ["SpeakNpcId"] = 240035,
            ["VoiceName"] = "voice/$Locale$/story/1204/120449/1E2734BC",
            },
        [12044903] = {
            ["Content"] = "一时胜负，终不能左右大局。奇技淫巧，岂可抵天命昭昭。",
            ["ContentFR"] = "Une victoire passagère ne changera pas la marche du monde. Vos artifices ne sauraient s’opposer au Mandat Céleste.",
            ["DialogueId"] = 12044903,
            ["GUID"] = "1E2734E6",
            ["NextDialogue"] = 12044904,
            ["SpeakNpcId"] = 240014,
            ["VoiceName"] = "voice/$Locale$/story/1204/120449/1E2734E6",
            },
        [12044904] = {
            ["Content"] = "不好！",
            ["ContentFR"] = "Mauvais signe !",
            ["DialogueId"] = 12044904,
            ["GUID"] = "1E273510",
            ["NextDialogue"] = 12044905,
            ["SpeakNpcId"] = 240014,
            ["VoiceName"] = "voice/$Locale$/story/1204/120449/1E273510",
            },
        [12044905] = {
            ["Content"] = "太虚陵遇袭，速速回防、速速回防！",
            ["ContentFR"] = "Le Mausolée de Taixu est attaqué ! Repli immédiat — repli immédiat !",
            ["DialogueId"] = 12044905,
            ["GUID"] = "1E27353A",
            ["NextDialogue"] = 12044906,
            ["SpeakNpcId"] = 240014,
            ["VoiceName"] = "voice/$Locale$/story/1204/120449/1E27353A",
            },
        [12044906] = {
            ["Content"] = "随着城区传来的巨大震动，众应天尉整齐划一地退军。",
            ["ContentFR"] = "Portés par les secousses venant de la ville, les Magistrats de Yingtian se replient d’un seul mouvement, impeccables, à l’unisson.",
            ["DialogueId"] = 12044906,
            ["GUID"] = "1E273564",
            ["NextDialogue"] = 12044907,
            ["SpeakNpcId"] = 0,
            ["VoiceName"] = "voice/$Locale$/story/1204/120449/1E273564",
            },
        [12044907] = {
            ["Content"] = "片刻之后，山外山恢复了往常的清净，仿佛大军从未来袭。只有战斗留下的狼藉提醒你这一切并非幻觉。",
            ["ContentFR"] = "Quelques instants plus tard, les Pics Extérieurs retrouvent leur calme, comme si aucune armée n’était jamais venue. Seuls les débris du combat prouvent que ce n’était pas un rêve.",
            ["DialogueId"] = 12044907,
            ["GUID"] = "1E27358E",
            ["NextDialogue"] = 12044908,
            ["SpeakNpcId"] = 0,
            ["VoiceName"] = "voice/$Locale$/story/1204/120449/1E27358E",
            },
        [12044908] = {
            ["Content"] = "……第二起，贲之涣。白贲饰伪，涣群为引。泽涸于山，损一隅而全大势。",
            ["ContentFR"] = "Le deuxième : parure et dispersion — le blanc pare le faux, la dispersion sert d’appât ; l’étang se dessèche pour la montagne, perdre une part pour préserver l’ensemble.",
            ["DialogueId"] = 12044908,
            ["GUID"] = "1E2735B8",
            ["NextDialogue"] = 12044909,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120449/1E2735B8",
            },
        [12044909] = {
            ["Content"] = "（头又开始疼起来了。这种感觉，难道说……）",
            ["ContentFR"] = "<I>La douleur revient... Cette sensation... Se pourrait-il que... ?</>",
            ["DialogueId"] = 12044909,
            ["DisableMouth"] = 1,
            ["GUID"] = "1E2735E2",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120449/1E2735E2",
            },
        [12045001] = {
            ["Content"] = "刚刚那招实在是太帅了！优雅精准的弹道瞄准，兼以华丽的火力倾泻功率……",
            ["ContentFR"] = "Cette manœuvre était remarquable ! Une trajectoire élégante, un ciblage d’une précision irréprochable... et un déploiement de puissance absolument splendide—",
            ["DialogueId"] = 12045001,
            ["GUID"] = "1E2744FA",
            ["NextDialogue"] = 12045002,
            ["RelatedWikiId"] = {
                [1] = 203009,
                [2] = 203007,
                [3] = 407008,
                [4] = 405010,
                },
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120450/1E2744FA",
            },
        [12045002] = {
            ["Content"] = "喂喂，重点错了吧！你夸的到底是小仆从，还是你们机枢派的传奇机关造物？！",
            ["ContentFR"] = "Hé ! Tu t’es pas trompée de priorité, là ? Tu complimentes mon petit larbin... ou tu baves sur le joujou légendaire de ta secte ?!",
            ["DialogueId"] = 12045002,
            ["GUID"] = "1E274524",
            ["NextDialogue"] = 12045003,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120450/1E274524",
            },
        [12045003] = {
            ["Content"] = "嘻嘻，机枢派先人的造物，自然是鬼斧神工、集天地智慧之大成于一体……好了，还是不开玩笑啦。",
            ["ContentFR"] = "Héhé... les créations des anciens de la Secte Jishu, c’est forcément du grand art — le génie des cieux et de la terre condensé en un seul mécanisme... Bon. Assez plaisanté. Revenons au sérieux.",
            ["DialogueId"] = 12045003,
            ["GUID"] = "1E27454E",
            ["NextDialogue"] = 12045004,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120450/1E27454E",
            },
        [12045004] = {
            ["Content"] = "{nickname}，若是没有你，山外山的危机不会如此轻易度过。请容我郑重地说一句感谢。",
            ["ContentFR"] = "{nickname}... sans toi, les Pics Extérieurs n’auraient pas surmonté cette crise aussi aisément. Permets-moi de te remercier — sincèrement.",
            ["DialogueId"] = 12045004,
            ["GUID"] = "1E274578",
            ["NextDialogue"] = 12045005,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120450/1E274578",
            },
        [12045005] = {
            ["Content"] = "真不愧是你！这身手，我刻舟都要甘拜下风了……",
            ["ContentFR"] = "Ah, ça, c’est bien toi ! Franchement, avec un niveau pareil... même moi, Kezhou, je m’incline.",
            ["DialogueId"] = 12045005,
            ["GUID"] = "1E2745A2",
            ["NextDialogue"] = 12045006,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120450/1E2745A2",
            },
        [12045006] = {
            ["Content"] = "…………",
            ["ContentFR"] = "...",
            ["DialogueId"] = 12045006,
            ["GUID"] = "1E2745CC",
            ["NextDialogue"] = 12045007,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120450/1E2745CC",
            },
        [12045007] = {
            ["Content"] = "咦，{nickname}，你怎么看起来有些疲惫？刚刚没伤到哪里吧？",
            ["ContentFR"] = "Hein ? {nickname}, tu as l’air {性别:épuisé... Tu ne t’es pas blessé|épuisée... Tu ne t’es pas blessée}, j’espère ?",
            ["DialogueId"] = 12045007,
            ["GUID"] = "1E2745F6",
            ["NextDialogue"] = 12045008,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120450/1E2745F6",
            },
        [12045008] = {
            ["Content"] = "……小仆从，你还好吗？！……",
            ["ContentFR"] = "... Petit larbin ? Hé ! Réponds-moi ! … Ça va ?!",
            ["DialogueId"] = 12045008,
            ["GUID"] = "1E274620",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120450/1E274620",
            },
        [12045101] = {
            ["Content"] = "……第二起，贲之涣。白贲饰伪，涣群为引。泽涸于山，损一隅而全大势。",
            ["ContentFR"] = "Le deuxième : parure et dispersion — le blanc pare le faux, la dispersion sert d’appât ; l’étang se dessèche pour la montagne, perdre une part pour préserver l’ensemble.",
            ["DialogueId"] = 12045101,
            ["GUID"] = "1E275562",
            ["NextDialogue"] = 12045102,
            ["RelatedWikiId"] = {
                [1] = 203001,
                [2] = 401005,
                },
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120451/1E275562",
            },
        [12045102] = {
            ["Content"] = "{nickname}，<H>你将会匿入深山，使得山外山的位置暴露，并因此引来钧天铁卫。 </>",
            ["ContentFR"] = "{nickname}, <H>tu te cacheras au cœur des montagnes, exposant la position des Pics Extérieurs et attirant à leurs portes les Sentinelles de Fer de Juntian.</>",
            ["DialogueId"] = 12045102,
            ["GUID"] = "1E27558C",
            ["NextDialogue"] = 12045103,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120451/1E27558C",
            },
        [12045103] = {
            ["Content"] = "这只是借用你的行踪，暂且调开城区的守备。你们只要坚持片刻，对面就会撤军。",
            ["ContentFR"] = "Ce n’est qu’un leurre. Ton déplacement détourne temporairement la garde de la capitale. Tiens bon un instant... et ils se retireront.",
            ["DialogueId"] = 12045103,
            ["GUID"] = "1E2755B6",
            ["NextDialogue"] = 12045104,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120451/1E2755B6",
            },
        [12045104] = {
            ["Content"] = "我没兴趣听你这些预言。",
            ["ContentFR"] = "Je n’ai aucun intérêt pour vos « prophéties ».",
            ["DialogueId"] = 12045104,
            ["GUID"] = "1E2755E0",
            ["NextDialogue"] = 12045105,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120451/1E2755E0",
            },
        [12045105] = {
            ["Content"] = "如果结局都被你谱写好了，知道这些又有什么意义。放我出去。",
            ["ContentFR"] = "Si vous avez déjà écrit la fin, à quoi bon l’entendre ? Laissez-moi sortir.",
            ["DialogueId"] = 12045105,
            ["GUID"] = "1E27560A",
            ["NextDialogue"] = 12045106,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120451/1E27560A",
            },
        [12045106] = {
            ["Content"] = "别急——我们之间可能有很多误会。你的问题，我会一一解答。比如说，我的目标从来不是成神。",
            ["ContentFR"] = "Ne te précipite pas — il y a sans doute bien des malentendus entre nous. Je répondrai à tes questions, une à une. Commençons par ceci : je n’ai jamais cherché à devenir une divinité.",
            ["DialogueId"] = 12045106,
            ["GUID"] = "1E275634",
            ["NextDialogue"] = 12045107,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120451/1E275634",
            },
        [12045107] = {
            ["Content"] = "对于烛阴祭坛之事，我表示十分抱歉。{nickname}，我很重视你。纵使有迫不得已的情形，但我从未将你作为一枚用而后弃的棋子看待。",
            ["ContentFR"] = "Concernant l’Autel de Zhuyin... je te dois des excuses. {nickname}, tu es {性别:important|importante} pour moi. Même si certaines choses m’ont contrainte, je ne t’ai jamais considéré comme un pion à utiliser puis jeter.",
            ["DialogueId"] = 12045107,
            ["GUID"] = "1E27565E",
            ["NextDialogue"] = 12045108,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120451/1E27565E",
            },
        [12045108] = {
            ["Content"] = "那你的目标是什么？",
            ["ContentFR"] = "Alors quel est votre but ?",
            ["DialogueId"] = 12045108,
            ["GUID"] = "1E275688",
            ["NextDialogue"] = 12045109,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120451/1E275688",
            },
        [12045109] = {
            ["Content"] = "如今的华胥，神明漠视众生，凡人麻木不仁。这僵化的大风九章种种，你也见证过了。",
            ["ContentFR"] = "Huaxu, aujourd’hui... les dieux détournent le regard, et les mortels s’engourdissent. Tu l’as vu : les Neuf Chapitres de Dafeng se sont figés, dévoyés.",
            ["DialogueId"] = 12045109,
            ["GUID"] = "1E2756B2",
            ["NextDialogue"] = 12045110,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120451/1E2756B2",
            },
        [12045110] = {
            ["Content"] = "我想做的事情很简单——<W>将那神明，自高天之上击落</>。",
            ["ContentFR"] = "Ce que je veux est très simple — <W>faire tomber les dieux de leur hauteur</>.",
            ["DialogueId"] = 12045110,
            ["GUID"] = "1E2756DC",
            ["NextDialogue"] = 12045111,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120451/1E2756DC",
            },
        [12045111] = {
            ["Content"] = "击落神明？",
            ["ContentFR"] = "Faire tomber les dieux... ?",
            ["DialogueId"] = 12045111,
            ["GUID"] = "1E275706",
            ["NextDialogue"] = 12045112,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120451/1E275706",
            },
        [12045112] = {
            ["Content"] = "你的意思是……你要弑神？",
            ["ContentFR"] = "Vous voulez dire... les tuer ?",
            ["DialogueId"] = 12045112,
            ["GUID"] = "1E275730",
            ["NextDialogue"] = 12045113,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120451/1E275730",
            },
        [12045113] = {
            ["Content"] = "正是如此。",
            ["ContentFR"] = "Exactement.",
            ["DialogueId"] = 12045113,
            ["GUID"] = "1E27575A",
            ["NextDialogue"] = 12045114,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120451/1E27575A",
            },
        [12045114] = {
            ["Content"] = "然而大风九章之力，并非平常手段可以抗衡。除非，借助某些这世上绝无仅有的能力。",
            ["ContentFR"] = "Mais la puissance des Neuf Chapitres n’est pas quelque chose qu’on affronte par des moyens ordinaires. À moins de... recourir à une force absolument unique en ce monde.",
            ["DialogueId"] = 12045114,
            ["GUID"] = "1E275784",
            ["NextDialogue"] = 12045115,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120451/1E275784",
            },
        [12045115] = {
            ["Content"] = "……和鸣之力。这就是你找上我的原因。",
            ["ContentFR"] = "... La Résonance. Voilà pourquoi vous m’avez cherché.",
            ["DialogueId"] = 12045115,
            ["GUID"] = "1E2757AE",
            ["NextDialogue"] = 12045116,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120451/1E2757AE",
            },
        [12045116] = {
            ["Content"] = "呵呵……没错。我以为这份古老的力量早已埋没于古籍之间，直到偶然发现了你的存在。",
            ["ContentFR"] = "Héhé... oui. Je croyais cette force antique perdue dans les vieux traités... jusqu’au jour où j’ai découvert ton existence.",
            ["DialogueId"] = 12045116,
            ["GUID"] = "1E2757D8",
            ["NextDialogue"] = 12045117,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120451/1E2757D8",
            },
        [12045117] = {
            ["Content"] = "你或许还对和鸣之力的本质懵懂无知——这是一份“引导”与“操控”的力量。华胥先祖<H>飏</>正是以相同的力量创立“大风九章”，将肆虐的秽兽化为龙神的爪牙。",
            ["ContentFR"] = "Tu ignores peut-être encore la vraie nature de la Résonance : c’est une force d’orientation... et de contrôle. L’ancêtre de Huaxu, <H>Yang</>, a fondé les Neuf Chapitres de Dafeng par cette même force, transformant les Souillés déchaînés en griffes au service des Seigneurs Dragons.",
            ["DialogueId"] = 12045117,
            ["GUID"] = "1E275802",
            ["NextDialogue"] = 12045118,
            ["RelatedWikiId"] = {
                [1] = 304002,
                },
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120451/1E275802",
            },
        [12045118] = {
            ["Content"] = "因而，能够伤及太皓的，也便只有这份<H>同源的力量</>。",
            ["ContentFR"] = "Ainsi... la seule force capable de blesser Taihao est une <H>puissance de même origine</>.",
            ["DialogueId"] = 12045118,
            ["GUID"] = "1E27582C",
            ["NextDialogue"] = 12045119,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120451/1E27582C",
            },
        [12045119] = {
            ["Content"] = "借你之手重创太皓、引开钧天铁卫……便能在那肆虐的风暴中，撕开一道足以击落神明的缝隙。",
            ["ContentFR"] = "Par ta main, Taihao fut gravement atteint, et les Sentinelles de Fer de Juntian furent attirées ailleurs... Et au cœur de la tempête, nous avons ouvert une brèche — assez large pour faire chuter les dieux.",
            ["DialogueId"] = 12045119,
            ["GUID"] = "1E275856",
            ["NextDialogue"] = 12045120,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120451/1E275856",
            },
        [12045120] = {
            ["Content"] = "{nickname}，在这个结局中，也安排好了你的位置。不打算听听我能给出的报酬吗？",
            ["ContentFR"] = "{nickname}... même ta place est déjà prévue dans cette fin. Tu ne veux pas entendre le prix que je peux offrir ?",
            ["DialogueId"] = 12045120,
            ["GUID"] = "1E275880",
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120451/1E275880",
            },
        [12045201] = {
            ["Content"] = "嘘……听——是命运的车轮开始转动的声音。",
            ["ContentFR"] = "Chut... écoute. C’est le bruit des roues du destin... qui commencent à tourner.",
            ["DialogueId"] = 12045201,
            ["GUID"] = "1E2765CA",
            ["NextDialogue"] = 12045202,
            ["RelatedWikiId"] = {
                [1] = 203001,
                [2] = 401005,
                [3] = 304002,
                },
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120452/1E2765CA",
            },
        [12045202] = {
            ["Content"] = "如何？我所做的准备已经完毕。",
            ["ContentFR"] = "Alors ? Tout ce que j’ai préparé... est prêt.",
            ["DialogueId"] = 12045202,
            ["GUID"] = "1E2765F4",
            ["NextDialogue"] = 12045203,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120452/1E2765F4",
            },
        [12045203] = {
            ["Content"] = "如今太皓受创，守备空虚，接下来的关键，便是以你之力破开<H>太虚陵</>。",
            ["ContentFR"] = "Taihao est blessé, sa garde est clairsemée. La clé, désormais... c’est d’utiliser ton pouvoir pour ouvrir le <H>Mausolée de Taixu</>.",
            ["DialogueId"] = 12045203,
            ["GUID"] = "1E27661E",
            ["NextDialogue"] = 12045204,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120452/1E27661E",
            },
        [12045204] = {
            ["Content"] = "计划一旦开始，此后就是玉石俱焚，乾坤倒转。",
            ["ContentFR"] = "Une fois le plan lancé... ce sera l’anéantissement réciproque, le renversement du monde. Plus de retour possible.",
            ["DialogueId"] = 12045204,
            ["GUID"] = "1E276648",
            ["NextDialogue"] = 12045205,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120452/1E276648",
            },
        [12045205] = {
            ["Content"] = "烛阴，你可准备好了？",
            ["ContentFR"] = "Zhuyin... es-tu prêt ?",
            ["DialogueId"] = 12045205,
            ["GUID"] = "1E276672",
            ["NextDialogue"] = 12045206,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120452/1E276672",
            },
        [12045206] = {
            ["Content"] = "……自吾黜落之日，便久待此刻。",
            ["ContentFR"] = "... Depuis le jour de ma chute, j’attends cet instant.",
            ["DialogueId"] = 12045206,
            ["GUID"] = "1E27669C",
            ["NextDialogue"] = 12045207,
            ["SpeakNpcId"] = 240025,
            ["VoiceName"] = "voice/$Locale$/story/1204/120452/1E27669C",
            },
        [12045207] = {
            ["Content"] = "自晦朔以望月，度春秋而经岁，终俟此报偿之期。吾之决意，岂容质疑。",
            ["ContentFR"] = "De nouvelles lunes en saisons, de saisons en années… j’ai enduré jusqu’au jour du tribut. Ma résolution ne souffre aucun doute.",
            ["DialogueId"] = 12045207,
            ["GUID"] = "1E2766C6",
            ["NextDialogue"] = 12045208,
            ["SpeakNpcId"] = 240025,
            ["VoiceName"] = "voice/$Locale$/story/1204/120452/1E2766C6",
            },
        [12045208] = {
            ["Content"] = "反顾尔心，却似有不决。往昔之谊，竟使尔心志移易乎？",
            ["ContentFR"] = "Mais toi... ton cœur vacille. Les liens d’autrefois t’auraient-ils attendrie ?",
            ["DialogueId"] = 12045208,
            ["GUID"] = "1E2766F0",
            ["NextDialogue"] = 12045209,
            ["SpeakNpcId"] = 240025,
            ["VoiceName"] = "voice/$Locale$/story/1204/120452/1E2766F0",
            },
        [12045209] = {
            ["Content"] = "……烛阴，我当初与你在祭坛上定下<H>魂契</>，可不是为了让你窥探我的内心。",
            ["ContentFR"] = "... Zhuyin. Le <H>Pacte d’âmes</> que nous avons scellé à l’autel n’a jamais eu pour but de t’offrir l’accès à mon esprit.",
            ["DialogueId"] = 12045209,
            ["GUID"] = "1E27671A",
            ["NextDialogue"] = 12045210,
            ["RelatedWikiId"] = {
                [1] = 304009,
                },
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120452/1E27671A",
            },
        [12045210] = {
            ["Content"] = "不过，往昔之谊吗？或许吧……",
            ["ContentFR"] = "Cela dit... ces liens d’autrefois ? Peut-être.",
            ["DialogueId"] = 12045210,
            ["GUID"] = "1E276744",
            ["NextDialogue"] = 12045211,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120452/1E276744",
            },
        [12045211] = {
            ["Content"] = "不知{nickname}在那里，是否安好。{性别：他|她}现在一定十分憎恨我吧。",
            ["ContentFR"] = "Je me demande si {nickname}, là-bas, va bien. {性别:Il|Elle} doit me haïr, à présent.",
            ["DialogueId"] = 12045211,
            ["GUID"] = "1E27676E",
            ["NextDialogue"] = 12045212,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120452/1E27676E",
            },
        [12045212] = {
            ["Content"] = "<H>和鸣之力</>，这曾为大风九章奠基者所掌握的能力，却在千年之后，经由一位异国旅者重新回到这片大地上。",
            ["ContentFR"] = "La <H>Résonance</>... cette force tenue jadis par la fondatrice des Neuf Chapitres... Et mille ans plus tard, elle revient sur cette terre par {性别:un voyageur venu|une voyageuse venue} d’ailleurs.",
            ["DialogueId"] = 12045212,
            ["GUID"] = "1E276798",
            ["NextDialogue"] = 12045213,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120452/1E276798",
            },
        [12045213] = {
            ["Content"] = "这在冥冥之中意味着什么，烛阴，你有想过吗？",
            ["ContentFR"] = "Dis-moi, Zhuyin... t’es-tu demandé ce que cela signifie, au fond ?",
            ["DialogueId"] = 12045213,
            ["GUID"] = "1E2767C2",
            ["NextDialogue"] = 12045214,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120452/1E2767C2",
            },
        [12045214] = {
            ["Content"] = "……",
            ["ContentFR"] = "...",
            ["DialogueId"] = 12045214,
            ["GUID"] = "1E2767EC",
            ["NextDialogue"] = 12045215,
            ["SpeakNpcId"] = 240025,
            ["VoiceName"] = "voice/$Locale$/story/1204/120452/1E2767EC",
            },
        [12045215] = {
            ["Content"] = "呵呵。时移势迁，世人早已忘却神因何存在。若是他们回想起自己顶礼膜拜的尊神，不过是凡人的造物，不知会作何感想。",
            ["ContentFR"] = "Héhé. Le temps passe, et le monde a oublié pourquoi les dieux existent. S’ils apprenaient un jour que les divinités qu’ils vénèrent ne sont... que des œuvres façonnées par des mortels... je me demande ce qu’ils ressentiraient.",
            ["DialogueId"] = 12045215,
            ["GUID"] = "1E276816",
            ["NextDialogue"] = 12045216,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120452/1E276816",
            },
        [12045216] = {
            ["Content"] = "世人之念，非吾所顾。",
            ["ContentFR"] = "Les pensées des mortels ne m’importent pas.",
            ["DialogueId"] = 12045216,
            ["GUID"] = "1E276840",
            ["NextDialogue"] = 12045217,
            ["SpeakNpcId"] = 240025,
            ["VoiceName"] = "voice/$Locale$/story/1204/120452/1E276840",
            },
        [12045217] = {
            ["Content"] = "今吾所求者，唯有携太皓同烬，了却数百年之长恨！",
            ["ContentFR"] = "Ce que je poursuis n’est qu’une chose : entraîner Taihao dans l’embrasement — et mettre fin à une haine longue de plusieurs siècles !",
            ["DialogueId"] = 12045217,
            ["GUID"] = "1E27686A",
            ["NextDialogue"] = 12045218,
            ["SpeakNpcId"] = 240025,
            ["VoiceName"] = "voice/$Locale$/story/1204/120452/1E27686A",
            },
        [12045218] = {
            ["Content"] = "你我倒是各取所需。那么，走吧——",
            ["ContentFR"] = "Toi et moi obtenons chacun ce dont nous avons besoin. Alors... allons-y—",
            ["DialogueId"] = 12045218,
            ["GUID"] = "1E276894",
            ["NextDialogue"] = 12045219,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120452/1E276894",
            },
        [12045219] = {
            ["Content"] = "前往命运为我们设置的葬身之所吧……华胥这颠倒黑白的现状，也该在今日纠正过来了。",
            ["ContentFR"] = "Allons vers la tombe que le destin nous a réservée... Aujourd’hui, Huaxu — où le faux règne sous le masque du juste — sera enfin redressée.",
            ["DialogueId"] = 12045219,
            ["GUID"] = "1E2768BE",
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120452/1E2768BE",
            },
        [12045301] = {
            ["Content"] = "{nickname}，你休息得如何了？",
            ["ContentFR"] = "{nickname}, comment te sens-tu après ce repos ?",
            ["DialogueId"] = 12045301,
            ["GUID"] = "1E277632",
            ["NextDialogue"] = 12045302,
            ["RelatedWikiId"] = {
                [1] = 203001,
                [2] = 203006,
                [3] = 401005,
                [4] = 304009,
                },
            ["SpeakNpcId"] = 240002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120453/1E277632",
            },
        [12045302] = {
            ["Content"] = "谢谢你，现在头已经不疼了。",
            ["ContentFR"] = "Merci. Mon mal de tête a disparu.",
            ["DialogueId"] = 12045302,
            ["GUID"] = "1E27765C",
            ["NextDialogue"] = 12045303,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120453/1E27765C",
            },
        [12045303] = {
            ["Content"] = "此次我不在你的身旁，无法及时照看你，现在才迟迟赶回……止流的第二个预言，是否已经应验了？",
            ["ContentFR"] = "Cette fois, je n’étais pas à tes côtés pour veiller sur toi... Je ne suis revenue que tardivement. La seconde prophétie de Zhiliu... s’est-elle déjà accomplie ?",
            ["DialogueId"] = 12045303,
            ["GUID"] = "1E277686",
            ["NextDialogue"] = 12045304,
            ["SpeakNpcId"] = 240002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120453/1E277686",
            },
        [12045304] = {
            ["Content"] = "嗯。以我为饵，诱使应天尉袭击山外山，就是止流第二个预言的内容。",
            ["ContentFR"] = "Oui. Se servir de moi comme appât afin d’attirer les Magistrats de Yingtian à attaquer les Pics Extérieurs — tel était le contenu de sa seconde prophétie.",
            ["DialogueId"] = 12045304,
            ["GUID"] = "1E2776B0",
            ["NextDialogue"] = 12045305,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120453/1E2776B0",
            },
        [12045305] = {
            ["Content"] = "但她的目标并非摧毁山外山，而是调开应天尉和狴犴，以方便她在其他地方做手脚……",
            ["ContentFR"] = "Mais son véritable objectif n’était pas de détruire les Pics Extérieurs. Elle voulait détourner les Magistrats de Yingtian et les Bi’an, afin d’agir ailleurs en toute liberté...",
            ["DialogueId"] = 12045305,
            ["GUID"] = "1E2776DA",
            ["NextDialogue"] = 12045306,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120453/1E2776DA",
            },
        [12045306] = {
            ["Content"] = "原来如此，这就是应天尉突然撤离的原因吗……",
            ["ContentFR"] = "Je vois... Voilà donc pourquoi les Magistrats se sont retirés si brusquement...",
            ["DialogueId"] = 12045306,
            ["GUID"] = "1E277704",
            ["NextDialogue"] = 12045307,
            ["SpeakNpcId"] = 240002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120453/1E277704",
            },
        [12045307] = {
            ["Content"] = "事件发生之时，我恰好身在城区中，目睹了从执律阁顶传来的巨大震动，路人们惊骇不已。",
            ["ContentFR"] = "Au moment des faits, je me trouvais en ville. J’ai vu la violente secousse provenir du sommet du Pavillon de l’Arbitrage. Les passants étaient pétrifiés d’effroi.",
            ["DialogueId"] = 12045307,
            ["GUID"] = "1E27772E",
            ["NextDialogue"] = 12045308,
            ["SpeakNpcId"] = 240002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120453/1E27772E",
            },
        [12045308] = {
            ["Content"] = "我离开时，情况已经得到控制，但具体的内情却无人知晓。",
            ["ContentFR"] = "Lorsque j’ai quitté les lieux, la situation était maîtrisée. Toutefois, nul ne semblait connaître la vérité de ce qui s’était réellement produit.",
            ["DialogueId"] = 12045308,
            ["GUID"] = "1E277758",
            ["NextDialogue"] = 12045309,
            ["SpeakNpcId"] = 240002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120453/1E277758",
            },
        [12045309] = {
            ["Content"] = "抱歉，因为一些私事，我在城中有所逗留。若是我能更早赶回来……",
            ["ContentFR"] = "Pardonne-moi. Certaines affaires personnelles m’ont retenue en ville. Si j’étais revenue plus tôt...",
            ["DialogueId"] = 12045309,
            ["GUID"] = "1E277782",
            ["NextDialogue"] = 12045310,
            ["SpeakNpcId"] = 240002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120453/1E277782",
            },
        [12045310] = {
            ["Content"] = "扶疏，不用向我道歉。你有你自己要忙的事情，作为朋友，我只希望你能够完成你的心愿。",
            ["ContentFR"] = "Fushu, tu n’as pas à t’excuser. Tu as tes propres responsabilités. En tant qu’{性别:ami|amie}, je souhaite seulement que tu puisses accomplir ce que tu poursuis.",
            ["DialogueId"] = 12045310,
            ["GUID"] = "1E2777AC",
            ["NextDialogue"] = 12045311,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120453/1E2777AC",
            },
        [12045311] = {
            ["Content"] = "不过，如果你遇到了一个人没法解决的难题，一定要告诉我。我会帮你一起想办法的，好吗？",
            ["ContentFR"] = "Mais si un jour tu te trouves face à un problème que tu ne peux résoudre seule, promets-moi de m’en parler. Nous chercherons une solution ensemble. D’accord ?",
            ["DialogueId"] = 12045311,
            ["GUID"] = "1E2777D6",
            ["NextDialogue"] = 12045312,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120453/1E2777D6",
            },
        [12045312] = {
            ["Content"] = "……嗯。{nickname}，你这番话，我会记住的。",
            ["ContentFR"] = "... Oui. {nickname}, je me souviendrai de ces paroles.",
            ["DialogueId"] = 12045312,
            ["GUID"] = "1E277800",
            ["NextDialogue"] = 12045313,
            ["SpeakNpcId"] = 240002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120453/1E277800",
            },
        [12045313] = {
            ["Content"] = "解除催眠的线索我已经有所掌握，待人齐了，再一起细说。你若是感觉好些了，先出去转转吧。",
            ["ContentFR"] = "J’ai obtenu quelques pistes concernant la levée de l’hypnose. Nous en parlerons en détail lorsque tout le monde sera réuni. Si tu te sens mieux, va prendre l’air un moment.",
            ["DialogueId"] = 12045313,
            ["GUID"] = "1E27782A",
            ["SpeakNpcId"] = 240002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120453/1E27782A",
            },
        [12045401] = {
            ["Content"] = "苏姑娘，今天我就来讨个准话，那{nickname}，你是赶还是不赶？",
            ["ContentFR"] = "Su, aujourd’hui je veux une réponse claire. {nickname}, est-ce que tu {性别:le|la} chasses d’ici... oui ou non ?",
            ["DialogueId"] = 12045401,
            ["GUID"] = "1E27869A",
            ["NextDialogue"] = 12045402,
            ["RelatedWikiId"] = {
                [1] = 203009,
                [2] = 408018,
                [3] = 103001,
                },
            ["SpeakNpcId"] = 240052,
            ["VoiceName"] = "voice/$Locale$/story/1204/120454/1E27869A",
            },
        [12045402] = {
            ["Content"] = "我苏乙在这里用名誉担保，{nickname}绝不是什么悬衡派细作！",
            ["ContentFR"] = "Je le jure sur mon honneur : {nickname} n’est en aucun cas un espion de la Secte Xuanheng !",
            ["DialogueId"] = 12045402,
            ["GUID"] = "1E2786C4",
            ["NextDialogue"] = 12045403,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120454/1E2786C4",
            },
        [12045403] = {
            ["Content"] = "不是细作？哈，你说巧不巧，这些年来山外山入口从未暴露半分，{性别：他|她}这个外人刚一脚踏进门，那些恶狼就闻着味儿追上来了！",
            ["ContentFR"] = "Pas un espion ? Ah ! Comme par hasard, l’entrée des Pics Extérieurs est restée secrète toutes ces années — et à peine {性别:cet étranger met-il|cette étrangère met-elle} un pied ici que les loups accourent à l’odeur !",
            ["DialogueId"] = 12045403,
            ["GUID"] = "1E2786EE",
            ["NextDialogue"] = 12045404,
            ["SpeakNpcId"] = 240052,
            ["VoiceName"] = "voice/$Locale$/story/1204/120454/1E2786EE",
            },
        [12045404] = {
            ["Content"] = "我不信猜测。我相信的，只有亲眼所见的事实。",
            ["ContentFR"] = "Je ne crois pas aux suppositions. Je crois aux faits que je vois de mes propres yeux.",
            ["DialogueId"] = 12045404,
            ["GUID"] = "1E278718",
            ["NextDialogue"] = 12045405,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120454/1E278718",
            },
        [12045405] = {
            ["Content"] = "刚刚钧天铁卫袭来时，{性别：他|她}帮我们击退了敌人——这才是我看到的。",
            ["ContentFR"] = "Quand les Sentinelles de Fer de Juntian ont attaqué, {性别:il s’est battu|elle s’est battue} à nos côtés pour les repousser— voilà ce que j’ai vu.",
            ["DialogueId"] = 12045405,
            ["GUID"] = "1E278742",
            ["NextDialogue"] = 12045406,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120454/1E278742",
            },
        [12045406] = {
            ["Content"] = "你怎知{性别：他|她}不是在骗取你信任？",
            ["ContentFR"] = "Et comment sais-tu qu’{性别:il|elle} ne cherchait pas simplement à gagner ta confiance ?",
            ["DialogueId"] = 12045406,
            ["GUID"] = "1E27876C",
            ["NextDialogue"] = 12045407,
            ["SpeakNpcId"] = 240052,
            ["VoiceName"] = "voice/$Locale$/story/1204/120454/1E27876C",
            },
        [12045407] = {
            ["Content"] = "钧天铁卫是自己跑的，不是被我们打退的！山外山的位置已经暴露，那些走狗随时可能卷土重来！到时候，你还有信心打赢第二次吗？",
            ["ContentFR"] = "Les Sentinelles sont parties d’elles-mêmes — ce n’est pas nous qui les avons chassées ! L’emplacement des Pics Extérieurs est désormais exposé. Ces chiens reviendront tôt ou tard. Et quand ce jour viendra... auras-tu encore la certitude de l’emporter ?",
            ["DialogueId"] = 12045407,
            ["GUID"] = "1E278796",
            ["NextDialogue"] = 12045408,
            ["SpeakNpcId"] = 240052,
            ["VoiceName"] = "voice/$Locale$/story/1204/120454/1E278796",
            },
        [12045408] = {
            ["Content"] = "……",
            ["ContentFR"] = "...",
            ["DialogueId"] = 12045408,
            ["GUID"] = "1E2787C0",
            ["NextDialogue"] = 12045409,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120454/1E2787C0",
            },
        [12045409] = {
            ["Content"] = "我们机枢派如今衰颓至此，还不是因为你们这些人行事软弱，一退再退吗？！",
            ["ContentFR"] = "Si la Secte Jishu est tombée aussi bas, c’est à cause de votre lâcheté ! Toujours céder ! Toujours battre en retraite !",
            ["DialogueId"] = 12045409,
            ["GUID"] = "1E2787EA",
            ["NextDialogue"] = 12045410,
            ["SpeakNpcId"] = 240052,
            ["VoiceName"] = "voice/$Locale$/story/1204/120454/1E2787EA",
            },
        [12045410] = {
            ["Content"] = "当初我们在<H>黍离之战</>中被泼了污名，无人奋起反抗，任由那悬衡奸贼瓜分我派。后来他们对机括术百般打压，我们还是忍气吞声。",
            ["ContentFR"] = "Lors de la <H>Bataille de Shuli</>, notre nom fut traîné dans la boue, et personne ne s’est levé pour protester. Les traîtres de Xuanheng ont dépecé notre secte, puis ils ont réprimé nos arts mécaniques... et nous avons encore serré les dents en silence.",
            ["DialogueId"] = 12045410,
            ["GUID"] = "1E278814",
            ["NextDialogue"] = 12045411,
            ["SpeakNpcId"] = 240052,
            ["VoiceName"] = "voice/$Locale$/story/1204/120454/1E278814",
            },
        [12045411] = {
            ["Content"] = "如今机枢派后人不是在天梁司摇尾乞怜，就是龟缩在这不见天日的山外山，谁还记得我们机枢派曾是和悬衡派并立的华胥支柱？！",
            ["ContentFR"] = "Aujourd’hui, nos descendants soit rampent devant le Bureau des Travaux, soit se terrent dans ces montagnes privées de lumière. Qui se souvient encore que la Secte Jishu fut jadis l’un des piliers de Huaxu, à l’égal de la Secte Xuanheng ?!",
            ["DialogueId"] = 12045411,
            ["GUID"] = "1E27883E",
            ["NextDialogue"] = 12045412,
            ["SpeakNpcId"] = 240052,
            ["VoiceName"] = "voice/$Locale$/story/1204/120454/1E27883E",
            },
        [12045412] = {
            ["Content"] = "……够了。",
            ["ContentFR"] = "... Ça suffit.",
            ["DialogueId"] = 12045412,
            ["GUID"] = "1E278868",
            ["NextDialogue"] = 12045413,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120454/1E278868",
            },
        [12045413] = {
            ["Content"] = "徐泓，我知道你操心的一切都是为了机枢派，为了山外山。",
            ["ContentFR"] = "Xu Hong, je sais que tout ce qui t’inquiète, c’est l’avenir de la Secte Jishu et la sécurité des Pics Extérieurs.",
            ["DialogueId"] = 12045413,
            ["GUID"] = "1E278892",
            ["NextDialogue"] = 12045414,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120454/1E278892",
            },
        [12045414] = {
            ["Content"] = "但我更知道，“兼爱幽明，天地一心”……以心为本，兼爱世人，才是机枢派入门传授的第一课。",
            ["ContentFR"] = "Mais je sais aussi ceci : « Chérir l’ombre comme la lumière, unir Ciel et Terre en un seul cœur... » Agir avec le cœur, aimer le monde sans distinction — c’est la toute première leçon que la Secte Jishu enseigne à ses disciples.",
            ["DialogueId"] = 12045414,
            ["GUID"] = "1E2788BC",
            ["NextDialogue"] = 12045415,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120454/1E2788BC",
            },
        [12045415] = {
            ["Content"] = "{nickname}是我的朋友，也是方才帮了我们的恩人，如果在此时此刻弃之不顾，任由{性别：他|她}陷于危险之中，我们才是真正背叛了机枢之道！",
            ["ContentFR"] = "{nickname} est mon {性别:ami. Il|amie. Elle} vient tout juste de nous sauver. Si nous l’abandonnons maintenant, si nous {性别:le laissons seul|la laissons seule} face au danger, alors ce serait nous qui trahirions véritablement la voie de Jishu !",
            ["DialogueId"] = 12045415,
            ["GUID"] = "1E2788E6",
            ["NextDialogue"] = 12045416,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120454/1E2788E6",
            },
        [12045416] = {
            ["Content"] = "你……哼！",
            ["ContentFR"] = "Toi... <I>Hmpf !</>",
            ["DialogueId"] = 12045416,
            ["GUID"] = "1E278910",
            ["SpeakNpcId"] = 240052,
            ["VoiceName"] = "voice/$Locale$/story/1204/120454/1E278910",
            },
        [12045501] = {
            ["Content"] = "如果你们还是想劝我赶走{nickname}，就请回吧！我说过很多次——我不会答应的！",
            ["ContentFR"] = "Si vous êtes encore venus pour me convaincre de chasser {nickname}, vous pouvez repartir ! Je l’ai déjà dit mille fois — je n’accepterai pas !",
            ["DialogueId"] = 12045501,
            ["GUID"] = "1E279702",
            ["NextDialogue"] = 12045502,
            ["RelatedWikiId"] = {
                [1] = 203009,
                [2] = 408018,
                [3] = 103001,
                },
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120455/1E279702",
            },
        [12045502] = {
            ["Content"] = "苏乙姐姐……",
            ["ContentFR"] = "Su Yi...",
            ["DialogueId"] = 12045502,
            ["GUID"] = "1E27972C",
            ["NextDialogue"] = 12045503,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120455/1E27972C",
            },
        [12045503] = {
            ["Content"] = "哇啊啊啊，{nickname}，还有小白，原、原来是你们来了……",
            ["ContentFR"] = "Ouaah— {nickname} ! Et... et Snow ?!",
            ["DialogueId"] = 12045503,
            ["GUID"] = "1E279756",
            ["NextDialogue"] = 12045504,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120455/1E279756",
            },
        [12045504] = {
            ["Content"] = "你、你们不会都听到了吧？！",
            ["ContentFR"] = "V-Vous... vous avez tout entendu ?!",
            ["DialogueId"] = 12045504,
            ["GUID"] = "1E279780",
            ["NextDialogue"] = 12045505,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120455/1E279780",
            },
        [12045505] = {
            ["Content"] = "……嗯。",
            ["ContentFR"] = "... Oui.",
            ["DialogueId"] = 12045505,
            ["GUID"] = "1E2797AA",
            ["NextDialogue"] = 12045506,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120455/1E2797AA",
            },
        [12045506] = {
            ["Content"] = "……好吧，我本不希望你们知道这些。",
            ["ContentFR"] = "... D’accord. Je n’avais pas envie que vous sachiez tout ça.",
            ["DialogueId"] = 12045506,
            ["GUID"] = "1E2797D4",
            ["NextDialogue"] = 12045507,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120455/1E2797D4",
            },
        [12045507] = {
            ["Content"] = "是这样的，有些人认为你们故意泄露了基地的位置，与大风九章沆瀣一气……但是，不用担心！我已经和他们说过了！他们不会再来找麻烦的！",
            ["ContentFR"] = "Voilà ce qu’il se passe : certains pensent que vous avez délibérément révélé l’emplacement de la base, que vous êtes de mèche avec les Neuf Chapitres de Dafeng... Mais ne vous inquiétez pas ! Je leur ai déjà parlé. Ils ne viendront plus vous chercher des ennuis !",
            ["DialogueId"] = 12045507,
            ["GUID"] = "1E2797FE",
            ["NextDialogue"] = 12045508,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120455/1E2797FE",
            },
        [12045508] = {
            ["Content"] = "你们不要生气，那些人的说法是很过分，但他们只是太担心了……毕竟山外山是我们唯一的家。",
            ["ContentFR"] = "Ne vous fâchez pas. Leurs accusations sont injustes, oui... mais ils ont surtout peur. Après tout, les Pics Extérieurs... c’est notre seul foyer.",
            ["DialogueId"] = 12045508,
            ["GUID"] = "1E279828",
            ["NextDialogue"] = 12045509,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120455/1E279828",
            },
        [12045509] = {
            ["Content"] = "谢谢你。不过，有一点他们说的没错……钧天铁卫，确实是我引来的。",
            ["ContentFR"] = "Merci. Mais sur un point... ils n’avaient pas tort. Les Sentinelles de Fer de Juntian... je les ai bel et bien attirées ici.",
            ["DialogueId"] = 12045509,
            ["GUID"] = "1E279852",
            ["NextDialogue"] = 12045510,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120455/1E279852",
            },
        [12045510] = {
            ["Content"] = "什——",
            ["ContentFR"] = "Qu— Quoi...?!",
            ["DialogueId"] = 12045510,
            ["GUID"] = "1E27987C",
            ["NextDialogue"] = 12045511,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120455/1E27987C",
            },
        [12045511] = {
            ["Content"] = "止流在我身上做了特殊的手脚，引得此地坐标暴露于大风九章的监视下。这是她在第二卦中亲口告诉我的。所以，我不能继续留在这里了。",
            ["ContentFR"] = "Zhiliu a laissé une empreinte sur moi. Ma simple présence suffit à révéler cet endroit aux Neuf Chapitres de Dafeng. Elle me l’a annoncé elle-même, dans sa seconde prophétie. C’est pour cela... que je ne peux pas rester.",
            ["DialogueId"] = 12045511,
            ["GUID"] = "1E2798A6",
            ["NextDialogue"] = 12045512,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120455/1E2798A6",
            },
        [12045512] = {
            ["Content"] = "可、可是，你对这事并不知情，不是你的错……我再想想办法！",
            ["ContentFR"] = "M-Mais... tu n’y es pour rien ! Tu ne pouvais pas savoir... Attends ! Je vais trouver une solution !",
            ["DialogueId"] = 12045512,
            ["GUID"] = "1E2798D0",
            ["NextDialogue"] = 12045513,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120455/1E2798D0",
            },
        [12045513] = {
            ["Content"] = "没关系的，苏乙，你的心意我领会到了。但是山外山刚刚受袭，你还有很多更重要的事情要做。",
            ["ContentFR"] = "Ce n’est rien, Su Yi. Je sais que tu voulais m’aider. Mais les Pics Extérieurs viennent d’être attaqués. Tu as plus urgent à gérer.",
            ["DialogueId"] = 12045513,
            ["GUID"] = "1E2798FA",
            ["NextOptions"] = {
                [1] = 12045514,
                },
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120455/1E2798FA",
            },
        [12045514] = {
            ["Content"] = "（摸摸苏乙的头。）",
            ["ContentFR"] = "<I>Caresser la tête de Su Yi</>",
            ["DialogueId"] = 12045514,
            ["GUID"] = "1E279924",
            ["NextDialogue"] = 12045515,
            },
        [12045515] = {
            ["Content"] = "我也有自己的事要解决。我必须在止流的第三卦应验前找到她。约好了，我们会平安再见的，好吗？",
            ["ContentFR"] = "Moi aussi, j’ai quelque chose à accomplir. Je dois trouver Zhiliu avant que sa troisième prophétie ne se réalise. On se reverra. Sains et saufs. Promis... d’accord ?",
            ["DialogueId"] = 12045515,
            ["GUID"] = "1E27994E",
            ["NextDialogue"] = 12045516,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120455/1E27994E",
            },
        [12045516] = {
            ["Content"] = "……那你……不许食言！",
            ["ContentFR"] = "... Alors... t’as intérêt à tenir parole !",
            ["DialogueId"] = 12045516,
            ["GUID"] = "1E279978",
            ["NextDialogue"] = 12045517,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120455/1E279978",
            },
        [12045517] = {
            ["Content"] = "对了，刻舟那家伙不知道跑到哪儿去了，可能刚和煜明大吵一架，心情不太好吧。",
            ["ContentFR"] = "Ah, et au fait ! Kezhou a disparu je ne sais où. Il a sûrement eu une grosse dispute avec Yuming... alors il boude, j’imagine.",
            ["DialogueId"] = 12045517,
            ["GUID"] = "1E2799A2",
            ["NextDialogue"] = 12045518,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120455/1E2799A2",
            },
        [12045518] = {
            ["Content"] = "你找到他，带他一起出发吧。那家伙前头一直说，他欠你一条命，所以你的忙，他帮定了。",
            ["ContentFR"] = "Trouve-le, et pars avec lui. Il répète depuis un moment qu’il te doit la vie, alors ton affaire — il la prendra à cœur, c’est sûr.",
            ["DialogueId"] = 12045518,
            ["GUID"] = "1E2799CC",
            ["NextDialogue"] = 12045519,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120455/1E2799CC",
            },
        [12045519] = {
            ["Content"] = "城中现在暗潮汹涌，多个帮手总是好的。而且那个大块头还算能打。",
            ["ContentFR"] = "La ville est en pleine tourmente en ce moment. Plus on a d’alliés, mieux c’est. Et puis ce grand balèze... il se débrouille plutôt bien quand il faut se battre.",
            ["DialogueId"] = 12045519,
            ["GUID"] = "1E2799F6",
            ["NextDialogue"] = 12045520,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120455/1E2799F6",
            },
        [12045520] = {
            ["Content"] = "对了，还有！",
            ["ContentFR"] = "Ah ! Et encore une chose !",
            ["DialogueId"] = 12045520,
            ["GUID"] = "1E279A20",
            ["NextDialogue"] = 12045521,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120455/1E279A20",
            },
        [12045521] = {
            ["Content"] = "以后不许摸我脑袋！在我们华胥只有长辈可以摸小辈的头！我的脑袋只有我姑姑摸过！",
            ["ContentFR"] = "Ne me touche plus la tête ! À Huaxu, seuls les aînés ont le droit de poser la main sur celle des plus jeunes ! La mienne, seule ma tante l’a touchée !",
            ["DialogueId"] = 12045521,
            ["GUID"] = "1E279A4A",
            ["NextOptions"] = {
                [1] = 12045522,
                [2] = 12045523,
                },
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120455/1E279A4A",
            },
        [12045522] = {
            ["Content"] = "抱歉，失礼了。",
            ["ContentFR"] = "<I>Pardon... je me suis {性别:montré impoli|montrée impolie}.</>",
            ["DialogueId"] = 12045522,
            ["GUID"] = "1E279A74",
            ["ImprPlusId"] = 1202,
            ["NextDialogue"] = 12045524,
            },
        [12045523] = {
            ["Content"] = "好的，叫{性别：爸爸|姑奶奶}。",
            ["ContentFR"] = "<I>Parfait. Alors appelle-moi {性别:Papa|Grande-tante}, pour voir.</>",
            ["DialogueId"] = 12045523,
            ["GUID"] = "1E279A9E",
            ["ImprPlusId"] = 1205,
            ["NextDialogue"] = 12045525,
            },
        [12045524] = {
            ["Content"] = "好，好了……反正你也不是本地人，我也没那么介意啦！",
            ["ContentFR"] = "B-Bon... ça va... De toute façon, t’es pas d’ici. Je ne vais pas t’en faire un drame !",
            ["DialogueId"] = 12045524,
            ["GUID"] = "1E279AC8",
            ["NextDialogue"] = 12045528,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120455/1E279AC8",
            },
        [12045525] = {
            ["Content"] = "……？反了你了！",
            ["ContentFR"] = "... Hein ?! Non mais tu te crois où ?!",
            ["DialogueId"] = 12045525,
            ["GUID"] = "1E279AF2",
            ["NextDialogue"] = 12045526,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120455/1E279AF2",
            },
        [12045526] = {
            ["Content"] = "既然刻舟是你兄弟，你要跟着他一起喊姑奶奶——听到了没，姑，奶，奶！",
            ["ContentFR"] = "Puisque Kezhou est ton frère d’armes, tu m’appelles Grande-tante, toi aussi ! Allez, répète : Grande. Tante.",
            ["DialogueId"] = 12045526,
            ["GUID"] = "1E279B1C",
            ["NextDialogue"] = 12045527,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120455/1E279B1C",
            },
        [12045527] = {
            ["Content"] = "哈哈，你看上去总算精神些了。",
            ["ContentFR"] = "Ha ha... voilà la Su Yi que je connais.",
            ["DialogueId"] = 12045527,
            ["GUID"] = "1E279B46",
            ["NextDialogue"] = 12045528,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120455/1E279B46",
            },
        [12045528] = {
            ["Content"] = "唔，接下来我得先清点基地受损状况，给大家送药……晚点还要修整机关……",
            ["ContentFR"] = "... Bon. Je dois d’abord évaluer les dégâts à la base, distribuer des remèdes... et ensuite réparer les mécanismes.",
            ["DialogueId"] = 12045528,
            ["GUID"] = "1E279B70",
            ["NextDialogue"] = 12045529,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120455/1E279B70",
            },
        [12045529] = {
            ["Content"] = "你找到刻舟后，先过来汇总情报，确认一下之后的行动方向再出发。虽然我暂时抽不开身，没法支援你们，但提供些情报支持还是小事一桩。",
            ["ContentFR"] = "Quand tu auras trouvé Kezhou, reviens ici. On mettra nos infos en commun et on décidera de la suite avant de partir. Je ne peux pas vous accompagner pour l’instant, mais vous fournir des renseignements, ça, c’est facile.",
            ["DialogueId"] = 12045529,
            ["GUID"] = "1E279B9A",
            ["NextDialogue"] = 12045530,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120455/1E279B9A",
            },
        }
  end },
  { MinKey = 12045530, MaxKey = 12046431, Loader = function()
      return {
        [12045530] = {
            ["Content"] = "小仆从，你先去吧。我留在这里等你。",
            ["ContentFR"] = "Petit larbin, vas-y d’abord. Moi, je reste ici et je t’attends.",
            ["DialogueId"] = 12045530,
            ["GUID"] = "1E279BC4",
            ["NextDialogue"] = 12045531,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120455/1E279BC4",
            },
        [12045531] = {
            ["Content"] = "太阳从西边出来了么？你怎么突然不跟着我了？",
            ["ContentFR"] = "Eh bien ? C’est une première. Tu ne viens pas avec moi ?",
            ["DialogueId"] = 12045531,
            ["GUID"] = "1E279BEE",
            ["NextDialogue"] = 12045532,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120455/1E279BEE",
            },
        [12045532] = {
            ["Content"] = "我……我对刚刚他们吵架时提到的那些悬衡啊机枢啊黍离之战什么的很好奇，不行吗！我的好学之心现在正在熊熊燃烧！",
            ["ContentFR"] = "Je... je suis curieuse ! D’accord ? Tout à l’heure, ils ont parlé de Xuanheng, de Jishu, de la Bataille de Shuli... ça m’intrigue ! Mon esprit studieux brûle d’un feu sacré, voilà tout !",
            ["DialogueId"] = 12045532,
            ["GUID"] = "1E279C18",
            ["NextDialogue"] = 12045533,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120455/1E279C18",
            },
        [12045533] = {
            ["Content"] = "你该不会是今天一天走累了，想偷懒吧？",
            ["ContentFR"] = "Ou alors tu es juste fatiguée, et tu cherches une excuse pour te reposer.",
            ["DialogueId"] = 12045533,
            ["GUID"] = "1E279C42",
            ["NextDialogue"] = 12045534,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120455/1E279C42",
            },
        [12045534] = {
            ["Content"] = "我、我才不会呢！小仆从你快去找刻舟啦，别让那家伙溜了！",
            ["ContentFR"] = "M-Mais pas du tout ! Petit larbin, va chercher Kezhou, vite ! Ne le laisse pas filer !",
            ["DialogueId"] = 12045534,
            ["GUID"] = "1E279C6C",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120455/1E279C6C",
            },
        [12045601] = {
            ["Content"] = "说起来，苏乙姐姐，我和小仆从成为你们机枢派的荣誉学徒这么久，还对机枢派的过往一无所知呢。",
            ["ContentFR"] = "Au fait, Su Yi, ça fait un bon moment que mon Petit larbin et moi sommes vos {性别:apprentis|apprenties} d’honneur de la Secte Jishu... et pourtant, on ne sait rien du tout de votre passé !",
            ["DialogueId"] = 12045601,
            ["GUID"] = "1E27A76A",
            ["NextDialogue"] = 12045602,
            ["RelatedWikiId"] = {
                [1] = 203009,
                [2] = 407008,
                },
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27A76A",
            },
        [12045602] = {
            ["Content"] = "听起来，机枢派也有过很拉风的时候，非常配得上白魔王大人的身份！啊对，后来发生了什么哇？给我也讲讲吧！",
            ["ContentFR"] = "À t’entendre, la Secte Jishu a déjà eu une époque incroyablement classe... ce qui sied parfaitement au rang de Roi Démon que je suis ! Alors ? Qu’est-ce qui s’est passé ensuite ? Raconte-moi ! Raconte-moi !",
            ["DialogueId"] = 12045602,
            ["GUID"] = "1E27A794",
            ["NextDialogue"] = 12045603,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27A794",
            },
        [12045603] = {
            ["Content"] = "荣誉学徒？我明白了，一定是公尚师傅那家伙又在外面试图捡徒弟了。",
            ["ContentFR"] = "{性别:Apprentis|Apprenties} d’honneur... Je vois. C’est forcément Maître Gongshang. Il essaye encore de ramasser des disciples à droite à gauche.",
            ["DialogueId"] = 12045603,
            ["GUID"] = "1E27A7BE",
            ["NextDialogue"] = 12045604,
            ["SpeakNpcId"] = 240026,
            ["TalkActionId"] = {
                [1] = "240026:DisagreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27A7BE",
            },
        [12045604] = {
            ["Content"] = "既然如此，那本师姐可要好好说一说了，你就洗耳恭听吧！",
            ["ContentFR"] = "Très bien. En tant qu’aînée, je vais t’expliquer ça correctement. Ouvre grand les oreilles !",
            ["DialogueId"] = 12045604,
            ["FacialId"] = {
                [1] = "240026:Smile01",
                },
            ["GUID"] = "1E27A7E8",
            ["NextDialogue"] = 12045605,
            ["SpeakNpcId"] = 240026,
            ["TalkActionId"] = {
                [1] = "240026:Confident_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27A7E8",
            },
        [12045605] = {
            ["Content"] = "先问你一个问题，对于大风九章的来历，你知道多少？",
            ["ContentFR"] = "D’abord, une question : qu’est-ce que tu sais des origines des Neuf Chapitres de Dafeng ?",
            ["DialogueId"] = 12045605,
            ["GUID"] = "1E27A812",
            ["NextDialogue"] = 12045606,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27A812",
            },
        [12045606] = {
            ["Content"] = "我记得我记得！是一个很厉害的家伙创立的，那个人叫……",
            ["ContentFR"] = "Je sais, je sais ! C’est quelqu’un d’incroyable qui les a fondés ! Et cette personne s’appelait...",
            ["DialogueId"] = 12045606,
            ["GUID"] = "1E27A83C",
            ["NextOptions"] = {
                [1] = 12045607,
                [2] = 12045608,
                [3] = 12045609,
                },
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27A83C",
            },
        [12045607] = {
            ["Content"] = "是悬衡派的先人飏创立的。",
            ["ContentFR"] = "<I>C’est l’ancêtre de la Secte Xuanheng, Yang, qui les a fondés.</>",
            ["DialogueId"] = 12045607,
            ["GUID"] = "1E27A866",
            ["ImprPlusId"] = 1203,
            ["NextDialogue"] = 12045610,
            },
        [12045608] = {
            ["Content"] = "是光之魔王大人白女士穿越时空创立的！",
            ["ContentFR"] = "<I>C’est le Roi Démon de la Lumière, l’incroyable Snow, qui a traversé le temps pour les fonder !</>",
            ["DialogueId"] = 12045608,
            ["GUID"] = "1E27A890",
            ["ImprPlusId"] = 1205,
            ["NextDialogue"] = 12045611,
            },
        [12045609] = {
            ["Content"] = "我想不起来了……",
            ["ContentFR"] = "<I>Je ne m’en souviens plus...</>",
            ["DialogueId"] = 12045609,
            ["GUID"] = "1E27A8BA",
            ["ImprPlusId"] = 1202,
            ["NextDialogue"] = 12045612,
            },
        [12045610] = {
            ["Content"] = "哼，就知道悬衡派会把功劳全都揽到自己头上。",
            ["ContentFR"] = "<I>Hmpf.</> Bien sûr que la Secte Xuanheng s’attribue tout le mérite.",
            ["DialogueId"] = 12045610,
            ["FacialId"] = {
                [1] = "240026:Angry01",
                },
            ["GUID"] = "1E27A8E4",
            ["NextDialogue"] = 12045612,
            ["SpeakNpcId"] = 240026,
            ["TalkActionId"] = {
                [1] = "240026:DisagreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27A8E4",
            },
        [12045611] = {
            ["Content"] = "喂喂，回答太离谱可是会扣分的！",
            ["ContentFR"] = "Hé, hé ! Répondre n’importe quoi, c’est zéro pointé !",
            ["DialogueId"] = 12045611,
            ["FacialId"] = {
                [1] = "240026:Angry01",
                },
            ["GUID"] = "1E27A90E",
            ["NextDialogue"] = 12045612,
            ["SpeakNpcId"] = 240026,
            ["TalkActionId"] = {
                [1] = "240026:DisagreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27A90E",
            },
        [12045612] = {
            ["Content"] = "呀！小仆从你什么时候回来的！",
            ["ContentFR"] = "Hé ?! Petit larbin, tu étais là depuis quand ?!",
            ["DialogueId"] = 12045612,
            ["GUID"] = "1E27A938",
            ["NextDialogue"] = 12045613,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27A938",
            },
        [12045613] = {
            ["Content"] = "怎么啦，你能听师姐讲课，我就不能听了吗？",
            ["ContentFR"] = "Quoi ? Tu as le droit d’écouter le cours de notre aînée, mais pas moi ?",
            ["DialogueId"] = 12045613,
            ["FacialId"] = {
                [1] = "240026:None",
                },
            ["GUID"] = "1E27A962",
            ["NextDialogue"] = 12045614,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27A962",
            },
        [12045614] = {
            ["Content"] = "当然欢迎！那么，我继续讲——上古时期，秽兽频出，纷争不绝于境。",
            ["ContentFR"] = "Évidemment que tu es {性别:le bienvenu|la bienvenue}. Alors j’en étais où ? Ah oui. Aux temps anciens, les Souillés surgissaient partout, et les conflits ne s’arrêtaient jamais.",
            ["DialogueId"] = 12045614,
            ["FacialId"] = {
                [1] = "240026:Smile01",
                },
            ["GUID"] = "1E27A98C",
            ["NextDialogue"] = 12045615,
            ["SpeakNpcId"] = 240026,
            ["TalkActionId"] = {
                [1] = "240026:Confident_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27A98C",
            },
        [12045615] = {
            ["Content"] = "如何才能让华胥子民免受秽蚀和战争的困扰呢，开国先祖<H>矩</>和<H>飏</>二人进行了长足的思考。",
            ["ContentFR"] = "Comment libérer les gens de Huaxu de la Dégradation et de la guerre ? Les fondateurs du royaume, <H>Ju</> et <H>Yang</>, y ont longuement réfléchi.",
            ["DialogueId"] = 12045615,
            ["GUID"] = "1E27A9B6",
            ["NextDialogue"] = 12045616,
            ["SpeakNpcId"] = 240026,
            ["TalkActionId"] = {
                [1] = "240026:Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27A9B6",
            },
        [12045616] = {
            ["Content"] = "最终，大风九章横空出世，给华胥带来了绵延数百年的和平。",
            ["ContentFR"] = "Et puis... les Neuf Chapitres de Dafeng sont apparus, comme tombés du ciel, apportant à Huaxu des siècles de paix.",
            ["DialogueId"] = 12045616,
            ["GUID"] = "1E27A9E0",
            ["NextDialogue"] = 12045617,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27A9E0",
            },
        [12045617] = {
            ["Content"] = "这庇佑华胥全境的惊世之术，可不是光凭飏一人就能完成的，我们机枢派的先人<H>矩</>在此过程中也发挥了必不可少的作用。",
            ["ContentFR"] = "Mais cet art prodigieux qui protégeait tout le territoire ne pouvait pas être l’œuvre de Yang seule. L’ancêtre de notre Secte Jishu, <H>Ju</>, y a joué un rôle indispensable.",
            ["DialogueId"] = 12045617,
            ["GUID"] = "1E27AA0A",
            ["NextDialogue"] = 12045618,
            ["RelatedWikiId"] = {
                [1] = 203010,
                },
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27AA0A",
            },
        [12045618] = {
            ["Content"] = "你们或许知道，飏有一种特殊的能力，通过焚烧“香”这种介质，她能够影响和操控区域中的秽兽，让它们乖乖听话，不再伤人。",
            ["ContentFR"] = "Vous le savez peut-être : Yang possédait un don particulier. En brûlant de l’« encens » comme support, elle pouvait influencer les Souillés d’une zone, les contrôler... et les apaiser, pour qu’ils cessent d’attaquer.",
            ["DialogueId"] = 12045618,
            ["GUID"] = "1E27AA34",
            ["NextDialogue"] = 12045619,
            ["RelatedWikiId"] = {
                [1] = 203003,
                },
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27AA34",
            },
        [12045619] = {
            ["Content"] = "但是怎么才能将这种能力固定和放大呢？",
            ["ContentFR"] = "Mais comment rendre ce pouvoir permanent... et l’amplifier ?",
            ["DialogueId"] = 12045619,
            ["GUID"] = "1E27AA5E",
            ["NextDialogue"] = 12045620,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27AA5E",
            },
        [12045620] = {
            ["Content"] = "为了寻找这个答案，矩四处游学，甚至最远抵达了艾利西安的“塔”下，与你们海伯利亚的先祖展开了一场激动人心的史诗大冒险——咳咳，扯远了。",
            ["ContentFR"] = "Pour trouver la réponse, Ju a parcouru le monde, étudié partout — il serait même allé jusqu’au pied de la « Tour » d’Élysium, et aurait vécu une aventure épique avec vos ancêtres hyperboréens... Hum. Je m’égare.",
            ["DialogueId"] = 12045620,
            ["GUID"] = "1E27AA88",
            ["NextDialogue"] = 12045621,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27AA88",
            },
        [12045621] = {
            ["Content"] = "总之，矩最后找到了答案。他带着这个答案回到华胥，集齐人力物力，打造了一个巨大的工程。",
            ["ContentFR"] = "Bref. Ju a trouvé la réponse. Il est revenu à Huaxu, a rassemblé hommes et ressources, et a lancé un chantier colossal.",
            ["DialogueId"] = 12045621,
            ["GUID"] = "1E27AAB2",
            ["NextDialogue"] = 12045622,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27AAB2",
            },
        [12045622] = {
            ["Content"] = "然后，飏、矩，还有许多有龙氏先人，一起在这个工程内祭献了身躯，用生命让飏的分香术永久固定下来，这就形成了大风九章的根基。",
            ["ContentFR"] = "Puis Yang, Ju et de nombreux ancêtres des Descendants draconiques ont offert leurs corps en sacrifice au cœur de cet ouvrage. Par leur vie, ils ont fixé à jamais l’Art de la Division de l’Encens de Yang — et c’est ainsi qu’ont été posées les fondations des Neuf Chapitres de Dafeng.",
            ["DialogueId"] = 12045622,
            ["GUID"] = "1E27AADC",
            ["NextDialogue"] = 12045623,
            ["RelatedWikiId"] = {
                [1] = 304003,
                },
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27AADC",
            },
        [12045623] = {
            ["Content"] = "传闻中，那个工程的本体就藏在执律阁上方。其中原理以及用到的种种精妙术式，到今天已经失传了。",
            ["ContentFR"] = "On raconte que cet ouvrage se trouve encore au-dessus du Pavillon de l’Arbitrage. Mais ses principes, ses procédés, ses formules... tout a été perdu.",
            ["DialogueId"] = 12045623,
            ["GUID"] = "1E27AB06",
            ["NextDialogue"] = 12045624,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27AB06",
            },
        [12045624] = {
            ["Content"] = "要不是那里是常人无法进入的禁地，可真想进去看一看啊……",
            ["ContentFR"] = "Si seulement ce n’était pas une zone interdite où l’on ne peut pas mettre les pieds... j’aimerais tellement y entrer, ne serait-ce qu’une fois.",
            ["DialogueId"] = 12045624,
            ["GUID"] = "1E27AB30",
            ["NextDialogue"] = 12045625,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27AB30",
            },
        [12045625] = {
            ["Content"] = "飏和矩祭献了生命之后，太皓和烛阴作为他们意志的代行者，一直统领着华胥。他们所创立的悬衡和机枢两派，也携手在治理上出力。",
            ["ContentFR"] = "Après le sacrifice de Yang et Ju, Taihao et Zhuyin ont régné sur Huaxu en tant que dépositaires de leur volonté. Et les deux sectes qu’ils avaient fondées — Xuanheng et Jishu — ont gouverné ensemble, main dans la main.",
            ["DialogueId"] = 12045625,
            ["GUID"] = "1E27AB5A",
            ["NextDialogue"] = 12045626,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27AB5A",
            },
        [12045626] = {
            ["Content"] = "那时候，机枢派的弟子名册每年都是厚厚一大本，研究经费更是要多少有多少，可不用像现在这样紧巴巴地过日子……这或许就是祖上阔过吧。",
            ["ContentFR"] = "À l’époque, le registre des disciples de Jishu était un livre épais comme ça chaque année. Et le budget de recherche... on en avait autant qu’on voulait. Pas comme aujourd’hui, à vivre en serrant chaque pièce... On peut dire que nos ancêtres ne manquaient de rien.",
            ["DialogueId"] = 12045626,
            ["GUID"] = "1E27AB84",
            ["NextDialogue"] = 12045627,
            ["SpeakNpcId"] = 240026,
            ["TalkActionId"] = {
                [1] = "240026:Talk02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27AB84",
            },
        [12045627] = {
            ["Content"] = "原来机枢派曾经这么风光——那怎么沦落到现在这种地步了？",
            ["ContentFR"] = "Alors la Secte Jishu a vraiment connu la gloire... Comment a-t-elle pu tomber aussi bas ?",
            ["DialogueId"] = 12045627,
            ["GUID"] = "1E27ABAE",
            ["NextDialogue"] = 12045628,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27ABAE",
            },
        [12045628] = {
            ["Content"] = "苏乙，你刚刚提到了烛阴曾经是受人崇敬的神明，但现在它在大家眼里却是带来祸患的恶龙。机枢派的衰落与这个也有关系吗？",
            ["ContentFR"] = "Su Yi, tout à l’heure tu as dit que Zhuyin était autrefois un dieu vénéré... mais aujourd’hui, il est vu comme un dragon maléfique qui apporte le désastre. La chute de Jishu est-elle liée à ça ?",
            ["DialogueId"] = 12045628,
            ["GUID"] = "1E27ABD8",
            ["NextDialogue"] = 12045629,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27ABD8",
            },
        [12045629] = {
            ["Content"] = "很敏锐嘛，{nickname}，不愧是你。",
            ["ContentFR"] = "Tu es vraiment perspicace, {nickname}. Je m’y attendais de ta part.",
            ["DialogueId"] = 12045629,
            ["GUID"] = "1E27AC02",
            ["NextDialogue"] = 12045630,
            ["SpeakNpcId"] = 240026,
            ["TalkActionId"] = {
                [1] = "240026:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27AC02",
            },
        [12045630] = {
            ["Content"] = "黍离之战的剧变后，悬衡派的那些家伙将很多事实都隐瞒了。这个版本的历史，也只有我们这支机枢派的亲传保留了下来。所以接下来也要听好了哦。",
            ["ContentFR"] = "Après le bouleversement de la Bataille de Shuli, la Secte Xuanheng a dissimulé beaucoup de faits. Cette version de l’histoire, seuls nous — la lignée directe de Jishu — l’avons conservée. Alors écoute bien.",
            ["DialogueId"] = 12045630,
            ["GUID"] = "1E27AC2C",
            ["NextDialogue"] = 12045631,
            ["RelatedWikiId"] = {
                [1] = 407006,
                },
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27AC2C",
            },
        [12045631] = {
            ["Content"] = "说回上古时期，虽然悬衡和机枢派曾经共同治理华胥，但是双方的理念有所不同。那时候大风九章远不像现在这么死板——甚至人类是可以和神明共治华胥的。",
            ["ContentFR"] = "Revenons aux temps anciens. Même si Xuanheng et Jishu gouvernaient Huaxu ensemble, leurs visions différaient. Et les Neuf Chapitres de Dafeng n’étaient pas aussi rigides qu’aujourd’hui — à cette époque, les humains pouvaient même gouverner aux côtés des dieux.",
            ["DialogueId"] = 12045631,
            ["GUID"] = "1E27AC56",
            ["NextDialogue"] = 12045632,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27AC56",
            },
        [12045632] = {
            ["Content"] = "我们机枢派认为，应该以心为基准去衡量万物，悬衡派却坚持法不留情的原则，双方在很多案件的判定上有争执。这样日积月累下来，产生了很多摩擦。",
            ["ContentFR"] = "À Jishu, nous estimions que toute chose devait être jugée avec le cœur. Xuanheng, au contraire, défendait un principe inflexible : la loi ne laisse aucune place à la pitié. De jugement en jugement, les frictions se sont accumulées.",
            ["DialogueId"] = 12045632,
            ["GUID"] = "1E27AC80",
            ["NextDialogue"] = 12045633,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27AC80",
            },
        [12045633] = {
            ["Content"] = "当时积攒的种种矛盾，在黍离之战时被彻底引燃了。",
            ["ContentFR"] = "Et toutes ces contradictions ont fini par s’embraser... lors de la Bataille de Shuli.",
            ["DialogueId"] = 12045633,
            ["GUID"] = "1E27ACAA",
            ["NextDialogue"] = 12045634,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27ACAA",
            },
        [12045634] = {
            ["Content"] = "听鸦原所在的位置，曾经是机枢派的研究重地，却在内战中被彻底付之一炬。",
            ["ContentFR"] = "L’endroit où se trouve aujourd’hui la Plaine des Corbeaux était autrefois un centre de recherche majeur de Jishu — mais la guerre civile l’a réduit en cendres.",
            ["DialogueId"] = 12045634,
            ["GUID"] = "1E27ACD4",
            ["NextDialogue"] = 12045635,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27ACD4",
            },
        [12045635] = {
            ["Content"] = "当时的内情谁也不清楚。只知道悬衡派怀疑我们机枢派有叛乱风险，带兵前去探查，最后不知怎的就变成了战争，双方无一生还。",
            ["ContentFR"] = "Personne ne connaît la vérité exacte. On sait seulement que Xuanheng a soupçonné Jishu de préparer une rébellion, a envoyé des troupes enquêter... et, sans que l’on sache comment, cela s’est transformé en guerre. Il n’y eut aucun survivant.",
            ["DialogueId"] = 12045635,
            ["GUID"] = "1E27ACFE",
            ["NextDialogue"] = 12045636,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27ACFE",
            },
        [12045636] = {
            ["Content"] = "这个消息传来后，所有人都非常震惊。明明有了为祈愿和平而诞生的大风九章，却依然酿成了如此大的灾祸，这是无论如何也不能允许的。",
            ["ContentFR"] = "Quand la nouvelle s’est répandue, tout le monde a été bouleversé. Les Neuf Chapitres avaient été créés pour prier la paix... et pourtant, un désastre pareil avait eu lieu. C’était inacceptable.",
            ["DialogueId"] = 12045636,
            ["GUID"] = "1E27AD28",
            ["NextDialogue"] = 12045637,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27AD28",
            },
        [12045637] = {
            ["Content"] = "那时的悬衡派认为失控的愤怒和猜疑让人们割舍了理性，不再遵守秩序，从而引发了这场战争，因此心便是祸患之源。",
            ["ContentFR"] = "À l’époque, Xuanheng a décrété que la colère et la suspicion avaient fait perdre la raison aux gens, brisé l’ordre, et allumé la guerre. Ainsi, le cœur serait la source du malheur.",
            ["DialogueId"] = 12045637,
            ["GUID"] = "1E27AD52",
            ["NextDialogue"] = 12045638,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27AD52",
            },
        [12045638] = {
            ["Content"] = "最终他们将机枢派的守护神烛阴封印了起来。也正是从那时开始，大风九章开始失衡，太皓变得一味强调死板的诫律，也不再聆听人类的声音。",
            ["ContentFR"] = "Alors ils ont scellé Zhuyin, le dieu protecteur de la Secte Jishu. Et à partir de ce jour... les Neuf Chapitres ont commencé à se déséquilibrer. Taihao n’a plus fait que marteler des édits rigides, et n’a plus écouté la voix des mortels.",
            ["DialogueId"] = 12045638,
            ["GUID"] = "1E27AD7C",
            ["NextDialogue"] = 12045639,
            ["SpeakNpcId"] = 240026,
            ["TalkActionId"] = {
                [1] = "240026:Explain01_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27AD7C",
            },
        [12045639] = {
            ["Content"] = "机枢派受到打压，很多技术从此成为禁忌。人们还需要匠矩阁的机傀技术帮助生产建设，但却添加了重重限制和偏见。",
            ["ContentFR"] = "La Secte Jishu a été réprimée, et nombre de nos techniques ont été frappées d’interdit. Pourtant, on continuait d’avoir besoin des méchapoupées du Pavillon des Artisans pour produire et bâtir… mais toujours sous d’innombrables restrictions et un lourd préjugé.",
            ["DialogueId"] = 12045639,
            ["FacialId"] = {
                [1] = "240026:Sad03",
                },
            ["GUID"] = "1E27ADA6",
            ["NextDialogue"] = 12045640,
            ["SpeakNpcId"] = 240026,
            ["TalkActionId"] = {
                [1] = "240026:Sad02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27ADA6",
            },
        [12045640] = {
            ["Content"] = "有些机枢派传人不满大风九章的僵化，便单独分家出去，和飘零人一起找到这里作为藏身之处。这就是山外山的前身啦。",
            ["ContentFR"] = "Certains héritiers de la Secte Jishu, écœurés par la rigidité des Neuf Chapitres, ont fait scission. Ils sont partis avec les Vagabonds, et ont trouvé refuge ici. C’est l’origine des Pics Extérieurs.",
            ["DialogueId"] = 12045640,
            ["GUID"] = "1E27ADD0",
            ["NextDialogue"] = 12045641,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27ADD0",
            },
        [12045641] = {
            ["Content"] = "嗯……事情经过大概就是这些。怎么样，你们还有问题吗？",
            ["ContentFR"] = "Bon... voilà pour l’essentiel. Alors ? Des questions ?",
            ["DialogueId"] = 12045641,
            ["FacialId"] = {
                [1] = "240026:None",
                },
            ["GUID"] = "1E27ADFA",
            ["NextOptions"] = {
                [1] = 12045642,
                [2] = 12045643,
                [3] = 12045644,
                },
            ["SpeakNpcId"] = 240026,
            ["TalkActionId"] = {
                [1] = "240026:Sad02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27ADFA",
            },
        [12045642] = {
            ["Content"] = "提到烛阴的回忆。",
            ["ContentFR"] = "<I>Évoquer les souvenirs de Zhuyin</>",
            ["DialogueId"] = 12045642,
            ["GUID"] = "1E27AE24",
            ["NextDialogue"] = 12045645,
            },
        [12045643] = {
            ["Content"] = "提到偃隐宫中的卷轴。",
            ["ContentFR"] = "<I>Évoquer le parchemin trouvé dans le Labyrinthe de Yanyin</>",
            ["DialogueId"] = 12045643,
            ["GUID"] = "1E27AE4E",
            ["NextDialogue"] = 12045647,
            },
        [12045644] = {
            ["Content"] = "没什么想说的。",
            ["ContentFR"] = "<I>Je n’ai pas de questions.</>",
            ["DialogueId"] = 12045644,
            ["GUID"] = "1E27AE78",
            ["NextDialogue"] = 12045651,
            },
        [12045645] = {
            ["Content"] = "是吗……原来这些过往历史的碎片，你曾经在烛阴的记忆中看到过。",
            ["ContentFR"] = "Je vois... Alors tu avais déjà aperçu des fragments de cette histoire à travers les souvenirs de Zhuyin.",
            ["DialogueId"] = 12045645,
            ["GUID"] = "1E27AEA2",
            ["NextDialogue"] = 12045646,
            ["SpeakNpcId"] = 240026,
            ["TalkActionId"] = {
                [1] = "240026:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27AEA2",
            },
        [12045646] = {
            ["Content"] = "心理失衡，后患无穷……现在这风雨飘摇的现状，或许证明了当初悬衡派的做法过于激进吧。",
            ["ContentFR"] = "Quand l’équilibre du cœur se brise, les conséquences sont sans fin... L’état actuel, si instable, si chancelant... prouve peut-être que les mesures de Xuanheng étaient trop extrêmes.",
            ["DialogueId"] = 12045646,
            ["GUID"] = "1E27AECC",
            ["NextDialogue"] = 12045651,
            ["SpeakNpcId"] = 240026,
            ["TalkActionId"] = {
                [1] = "240026:Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27AECC",
            },
        [12045647] = {
            ["Content"] = "没错，那位建造偃隐宫的前辈所留下的手记，或许能成为解开黍离之战内情的关键线索。",
            ["ContentFR"] = "Oui. Les notes laissées par l’aîné qui a bâti le Labyrinthe de Yanyin pourraient être la clé... pour comprendre ce qui s’est réellement passé lors de la Bataille de Shuli.",
            ["DialogueId"] = 12045647,
            ["GUID"] = "1E27AEF6",
            ["NextDialogue"] = 12045648,
            ["SpeakNpcId"] = 240026,
            ["TalkActionId"] = {
                [1] = "240026:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27AEF6",
            },
        [12045648] = {
            ["Content"] = "要是如他所说……当时机枢派并没有主动挑起叛乱，在那个大雾弥漫、地磁紊乱的拂晓之中，某具机傀突然失灵了，让双方都以为对面先动了手。",
            ["ContentFR"] = "Si ce qu’il écrit est vrai... alors la Secte Jishu n’a jamais cherché la rébellion. Ce matin-là, dans un brouillard épais, au milieu d’un chaos magnétique... une méchapoupée a soudain dysfonctionnée, et chacun a cru que l’autre avait frappé le premier.",
            ["DialogueId"] = 12045648,
            ["GUID"] = "1E27AF20",
            ["NextDialogue"] = 12045649,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27AF20",
            },
        [12045649] = {
            ["Content"] = "数百年的打压和悲剧，竟是这种意外误解带来的。",
            ["ContentFR"] = "Des siècles de répression et de tragédies... nés d’un accident, d’un malentendu.",
            ["DialogueId"] = 12045649,
            ["GUID"] = "1E27AF4A",
            ["NextDialogue"] = 12045650,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27AF4A",
            },
        [12045650] = {
            ["Content"] = "事到如今，这个真相也失去了它本该拥有的意义……心与心之间的矛盾，并非是那么轻易就能弥合的。",
            ["ContentFR"] = "Mais aujourd’hui... même la vérité a perdu le sens qu’elle aurait dû avoir. Les fractures entre les cœurs ne se referment pas si facilement.",
            ["DialogueId"] = 12045650,
            ["GUID"] = "1E27AF74",
            ["NextDialogue"] = 12045651,
            ["SpeakNpcId"] = 240026,
            ["TalkActionId"] = {
                [1] = "240026:Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27AF74",
            },
        [12045651] = {
            ["Content"] = "呀，不知不觉就讲了这么长时间……总而言之，无论机枢派曾经是风光还是落寞，那都是过去的事情了！",
            ["ContentFR"] = "Ah... sans m’en rendre compte, j’ai parlé si longtemps... Enfin bref : que la Secte Jishu ait connu la gloire ou la déchéance, tout cela appartient au passé !",
            ["DialogueId"] = 12045651,
            ["GUID"] = "1E27AF9E",
            ["NextDialogue"] = 12045652,
            ["SpeakNpcId"] = 240026,
            ["TalkActionId"] = {
                [1] = "240026:Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27AF9E",
            },
        [12045652] = {
            ["Content"] = "比起那些陈年旧事，还是当下比较重要啦。还有这么多要务得赶紧去处理呢，可不是缅怀往事的时候。",
            ["ContentFR"] = "Les vieilles histoires peuvent attendre. C’est le présent qui compte. J’ai encore une montagne de choses à gérer... Ce n’est pas le moment de se perdre dans la nostalgie.",
            ["DialogueId"] = 12045652,
            ["GUID"] = "1E27AFC8",
            ["NextDialogue"] = 12045653,
            ["SpeakNpcId"] = 240026,
            ["TalkActionId"] = {
                [1] = "240026:DisagreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27AFC8",
            },
        [12045653] = {
            ["Content"] = "你们赶紧忙去吧。要是有什么问题，随时再来问我。本师姐会为你们好好答疑解惑的！",
            ["ContentFR"] = "Allez, filez {性别:tous|toutes} les deux. Et si quelque chose vous échappe, revenez me voir. Je vous ferai un vrai cours.",
            ["DialogueId"] = 12045653,
            ["GUID"] = "1E27AFF2",
            ["SpeakNpcId"] = 240026,
            ["TalkActionId"] = {
                [1] = "240026:Talk02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27AFF2",
            },
        [12045701] = {
            ["Content"] = "……{nickname}，你来了啊。",
            ["ContentFR"] = "... {nickname}. Te voilà.",
            ["DialogueId"] = 12045701,
            ["GUID"] = "1E27B7D2",
            ["NextDialogue"] = 12045702,
            ["RelatedWikiId"] = {
                [1] = 203007,
                [2] = 203004,
                },
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27B7D2",
            },
        [12045702] = {
            ["Content"] = "本欲来这竹林中练练剑，结果始终找不到手感。想来是我满心杂念，浑身不得劲，连剑老兄也看不过去了。",
            ["ContentFR"] = "Je suis venu m’entraîner un peu dans cette bambouseraie... mais impossible de retrouver mes sensations. J’ai la tête trop pleine, sans doute. Même mon épée doit en avoir marre.",
            ["DialogueId"] = 12045702,
            ["GUID"] = "1E27B7FC",
            ["NextDialogue"] = 12045703,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27B7FC",
            },
        [12045703] = {
            ["Content"] = "刻舟，你还好吗？看你平时总是大咧咧的，没想到也会有这样心事重重的时候。",
            ["ContentFR"] = "Kezhou... qu’est-ce qui t’arrive ? Toi qui plaisantes toujours, je ne t’ai jamais vu aussi pensif.",
            ["DialogueId"] = 12045703,
            ["GUID"] = "1E27B826",
            ["NextDialogue"] = 12045704,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27B826",
            },
        [12045704] = {
            ["Content"] = "……以前看不起别人在深夜多愁善感，没想到风水轮流转，这种不潇洒的事也轮到自己身上了。",
            ["ContentFR"] = "... Avant, je me moquais des gens qui se laissaient engloutir par la mélancolie, en pleine nuit. Comme quoi... la roue tourne. Voilà que ça me tombe dessus.",
            ["DialogueId"] = 12045704,
            ["GUID"] = "1E27B850",
            ["NextDialogue"] = 12045705,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27B850",
            },
        [12045705] = {
            ["Content"] = "我总想起当年的事，那时我也在这儿练剑，先是树枝，然后是木剑，最后才是真正的剑。",
            ["ContentFR"] = "Je repense à l’époque. Je m’entraînais déjà ici. D’abord avec des branches, puis avec une épée de bois... et seulement ensuite avec une vraie lame.",
            ["DialogueId"] = 12045705,
            ["GUID"] = "1E27B87A",
            ["NextDialogue"] = 12045706,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27B87A",
            },
        [12045706] = {
            ["Content"] = "师兄和不夏就站在你现在站的地方。师兄板着脸指点我招式，不夏就老在那儿上蹿下跳地喝彩，跳得老高。",
            ["ContentFR"] = "Mon frère d’armes et Buxia se tenaient là où tu es. Lui, visage fermé, corrigeait mes mouvements. Et Buxia... elle sautait partout, applaudissait, criait, bondissait si haut qu’on aurait dit qu’elle touchait la lune.",
            ["DialogueId"] = 12045706,
            ["GUID"] = "1E27B8A4",
            ["NextDialogue"] = 12045707,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27B8A4",
            },
        [12045707] = {
            ["Content"] = "可如今这大好月色，只能照我一个心有郁结的失意人，属实是浪费了。",
            ["ContentFR"] = "Et maintenant, avec cette si belle clarté... il n’y a que moi, avec mes nœuds dans le cœur. C’est du gâchis, honnêtement.",
            ["DialogueId"] = 12045707,
            ["GUID"] = "1E27B8CE",
            ["NextDialogue"] = 12045708,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27B8CE",
            },
        [12045708] = {
            ["Content"] = "“不夏”……这个名字，煜明白天和你吵架的时候也提到过。她是谁？",
            ["ContentFR"] = "« Buxia »... Yuming a prononcé ce nom quand vous vous disputiez, tout à l’heure. Qui était-elle ?",
            ["DialogueId"] = 12045708,
            ["GUID"] = "1E27B8F8",
            ["NextDialogue"] = 12045709,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27B8F8",
            },
        [12045709] = {
            ["Content"] = "是我和师兄从烟津渡捡来的小师妹，如今已经不在人世了。",
            ["ContentFR"] = "Notre petite sœur d’apprentissage. Moi et Yuming l’avons recueillie à Port-des-Brumes. Elle... elle n’est plus de ce monde.",
            ["DialogueId"] = 12045709,
            ["GUID"] = "1E27B922",
            ["NextDialogue"] = 12045710,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27B922",
            },
        [12045710] = {
            ["Content"] = "她是因为什么去世的？",
            ["ContentFR"] = "Comment est-elle morte ?",
            ["DialogueId"] = 12045710,
            ["GUID"] = "1E27B94C",
            ["NextDialogue"] = 12045711,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27B94C",
            },
        [12045711] = {
            ["Content"] = "因为“自由”。",
            ["ContentFR"] = "À cause de la « liberté ».",
            ["DialogueId"] = 12045711,
            ["GUID"] = "1E27B976",
            ["NextDialogue"] = 12045712,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27B976",
            },
        [12045712] = {
            ["Content"] = "说来可笑吧？我们飘零人终其一生追求的自由无拘，最终害死了她。",
            ["ContentFR"] = "Ironique, hein ? Nous, les Vagabonds, on passe une vie entière à courir après une liberté sans entraves... et au bout du compte, c’est cette liberté qui l’a tuée.",
            ["DialogueId"] = 12045712,
            ["GUID"] = "1E27B9A0",
            ["NextDialogue"] = 12045713,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27B9A0",
            },
        [12045713] = {
            ["Content"] = "你或许知道，华胥人打从一生下来就活在大风九章的条条框框之中。不许做这，不许做那。不许习武，不许打架，更不许对龙神不敬。",
            ["ContentFR"] = "Tu le sais sûrement : à Huaxu, dès la naissance, on vit dans les cadres des Neuf Chapitres de Dafeng. Interdiction de ceci, interdiction de cela. Interdiction de s’entraîner, interdiction de se battre... et surtout, interdiction de manquer de respect aux Seigneurs Dragons.",
            ["DialogueId"] = 12045713,
            ["GUID"] = "1E27B9CA",
            ["NextDialogue"] = 12045714,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27B9CA",
            },
        [12045714] = {
            ["Content"] = "那要是想争出一身自由怎么办？就只能想办法跳出这大风九章的重重束缚，这也正是飘零人一直以来追求的目标。",
            ["ContentFR"] = "Alors si tu veux arracher un peu de liberté... tu dois sortir de ces chaînes. C’est ça, notre but, depuis toujours.",
            ["DialogueId"] = 12045714,
            ["GUID"] = "1E27B9F4",
            ["NextDialogue"] = 12045715,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27B9F4",
            },
        [12045715] = {
            ["Content"] = "五年前，能将大风九章隔绝在外的天罗拒风仪发明出来了，我们终于做到了！",
            ["ContentFR"] = "Il y a cinq ans, on a mis au point un dispositif capable d’isoler les Neuf Chapitres : le Voile de Tianluo. Et on a enfin réussi.",
            ["DialogueId"] = 12045715,
            ["GUID"] = "1E27BA1E",
            ["NextDialogue"] = 12045716,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BA1E",
            },
        [12045716] = {
            ["Content"] = "山外山的每个人都高兴得紧，光是庆功宴就连着开了一场又一场。那阵子啊，隔着几米远就能闻到别人衣服上烤肉留下的烟熏味。",
            ["ContentFR"] = "À ce moment-là, tout le monde, aux Pics Extérieurs, était fou de joie. On a enchaîné les banquets, l’un après l’autre. À cette période, à quelques mètres, tu sentais déjà l’odeur de fumée et de viande grillée sur les vêtements des gens.",
            ["DialogueId"] = 12045716,
            ["GUID"] = "1E27BA48",
            ["NextDialogue"] = 12045717,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BA48",
            },
        [12045717] = {
            ["Content"] = "但我们谁都忘了。大风九章不仅仅是惩戒逾矩的家伙，它还有个重要的功能——将秽蚀隔绝于外。",
            ["ContentFR"] = "Mais on a tous oublié quelque chose. Les Neuf Chapitres ne se contentent pas de punir ceux qui dépassent les bornes... ils ont aussi une fonction capitale : tenir la Dégradation à l’écart.",
            ["DialogueId"] = 12045717,
            ["GUID"] = "1E27BA72",
            ["NextDialogue"] = 12045718,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BA72",
            },
        [12045718] = {
            ["Content"] = "难道说……？！",
            ["ContentFR"] = "Tu veux dire que... ?!",
            ["DialogueId"] = 12045718,
            ["GUID"] = "1E27BA9C",
            ["NextDialogue"] = 12045719,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BA9C",
            },
        [12045719] = {
            ["Content"] = "……正是你想的那样。",
            ["ContentFR"] = "... Oui. Exactement ce que tu imagines.",
            ["DialogueId"] = 12045719,
            ["GUID"] = "1E27BAC6",
            ["NextDialogue"] = 12045720,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BAC6",
            },
        [12045720] = {
            ["Content"] = "我们过了太久的太平日子，“秽蚀”这个对外国人来说很恐怖的词，在华胥这儿却只存在在古书里。",
            ["ContentFR"] = "On avait vécu trop longtemps en paix. « Dégradation »... un mot terrifiant pour les étrangers, mais à Huaxu, il n’existait plus que dans les vieux livres.",
            ["DialogueId"] = 12045720,
            ["GUID"] = "1E27BAF0",
            ["NextDialogue"] = 12045721,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BAF0",
            },
        [12045721] = {
            ["Content"] = "在大风九章治下，秽蚀者会直接化为狴犴，执行大风九章的意志。但当大风九章被我们隔绝之后，那些怪物……回来了。",
            ["ContentFR"] = "Sous l’ordre des Neuf Chapitres, les Dégradés se transformaient directement en Bi’an, pour exécuter la volonté des Neuf Chapitres. Mais quand nous les avons isolés... ces monstres... sont revenus.",
            ["DialogueId"] = 12045721,
            ["GUID"] = "1E27BB1A",
            ["NextDialogue"] = 12045722,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BB1A",
            },
        [12045722] = {
            ["Content"] = "不夏那时候快要成年了。就在成年的前一天，她变成了可怖的秽兽，袭击了我们的基地。很多人在那场事故中死去了，包括我们的师父。",
            ["ContentFR"] = "Buxia allait atteindre l’âge adulte. La veille de sa majorité, elle s’est changée en Souillé... et a attaqué notre base. Beaucoup sont morts ce jour-là. Notre maître, aussi.",
            ["DialogueId"] = 12045722,
            ["GUID"] = "1E27BB44",
            ["NextDialogue"] = 12045723,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BB44",
            },
        [12045723] = {
            ["Content"] = "她之前嚷嚷着头痛的时候，我们都没当回事，以为只是普通风寒，习武之人的身子骨硬朗，挺过去便是了。只有师兄细心，一人潜进城里药堂买药。",
            ["ContentFR"] = "Avant ça, elle se plaignait de maux de tête... mais on n’y a pas prêté attention. On a cru à un simple refroidissement. Un corps entraîné encaisse, on s’est dit que ça passerait. Seul Yuming a eu la prudence d’aller seul en ville, à l’officine, chercher des remèdes.",
            ["DialogueId"] = 12045723,
            ["GUID"] = "1E27BB6E",
            ["NextDialogue"] = 12045724,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BB6E",
            },
        [12045724] = {
            ["Content"] = "师兄让我留下来看住她的情况。我没听。一点城里杂耍班子的消息就把我勾走了。是啊，照看小师妹，哪里有进城看热闹来得有意思。",
            ["ContentFR"] = "Il m’a demandé de rester pour surveiller son état. Je ne l’ai pas écouté. Un bruit de troupe de spectacle en ville, et j’ai filé. Oui... garder une petite apprentie, c’était moins amusant que d’aller voir l’animation.",
            ["DialogueId"] = 12045724,
            ["GUID"] = "1E27BB98",
            ["NextDialogue"] = 12045725,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BB98",
            },
        [12045725] = {
            ["Content"] = "最后……怎么样了？",
            ["ContentFR"] = "Et ensuite... ?",
            ["DialogueId"] = 12045725,
            ["GUID"] = "1E27BBC2",
            ["NextDialogue"] = 12045726,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BBC2",
            },
        [12045726] = {
            ["Content"] = "几个时辰后，我回到山外山，只看到一地血泊……以及站在血泊中的师兄。那让人几欲呕吐的鲜红，我恐怕这辈子都忘不掉了。",
            ["ContentFR"] = "Quelques heures plus tard, je suis revenu aux Pics Extérieurs... et je n’ai vu qu’un lac de sang. Et Yuming, debout, au milieu. Ce rouge... ce rouge à en donner la nausée. Je ne l’oublierai jamais.",
            ["DialogueId"] = 12045726,
            ["GUID"] = "1E27BBEC",
            ["NextDialogue"] = 12045727,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BBEC",
            },
        [12045727] = {
            ["Content"] = "师兄亲手杀了她——这个我们亲手养大，视为妹妹的孩子。他求来的药洒了一地，和那些血混在一起。",
            ["ContentFR"] = "C’est lui qui l’a tuée de sa propre main... cette enfant que nous avions élevée, que nous avions considérée comme notre petite sœur. Les remèdes qu’il avait rapportés... étaient répandus à terre, mêlés au sang.",
            ["DialogueId"] = 12045727,
            ["GUID"] = "1E27BC16",
            ["NextDialogue"] = 12045728,
            ["RelatedWikiId"] = {
                [1] = 203011,
                },
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BC16",
            },
        [12045728] = {
            ["Content"] = "从那之后，师兄几乎再也没有笑过，人也变得更加寡言少语。后来，一个满月的夜晚，师兄独自离开了。再见面时，他已经变成了应天尉。",
            ["ContentFR"] = "Depuis ce jour, il a presque cessé de sourire. Il est devenu de plus en plus silencieux. Puis, une nuit de pleine lune... il est parti seul. Et quand je l’ai revu, il était devenu l’un des Magistrats de Yingtian.",
            ["DialogueId"] = 12045728,
            ["GUID"] = "1E27BC40",
            ["NextDialogue"] = 12045729,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BC40",
            },
        [12045729] = {
            ["Content"] = "我不知道他和白龙达成了什么交易，我只知道，那个小时候带着我偷溜出去买桂花糕，会手把手指导我剑术的师兄再也不会回来了。",
            ["ContentFR"] = "Je ne sais pas quel marché il a conclu avec le Dragon d’Argent. Je sais seulement que Yuming... celui qui, enfant, m’emmenait voler des gâteaux à l’osmanthe, celui qui me corrigeait l’épée de ses propres mains... ne reviendra plus jamais.",
            ["DialogueId"] = 12045729,
            ["GUID"] = "1E27BC6A",
            ["NextDialogue"] = 12045730,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BC6A",
            },
        [12045730] = {
            ["Content"] = "自那天起，我也再没看过一次杂耍。",
            ["ContentFR"] = "Depuis ce jour-là, je n’ai plus jamais regardé un spectacle.",
            ["DialogueId"] = 12045730,
            ["GUID"] = "1E27BC94",
            ["NextDialogue"] = 12045731,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BC94",
            },
        [12045731] = {
            ["Content"] = "……其实，师兄说的那些，我全都明白。白天他质问我为何“只破不立”时，我也确实回答不上来。",
            ["ContentFR"] = "... Au fond, je comprends ce qu’il voulait dire. Quand il m’a lancé qu’on ne savait que détruire sans rien bâtir... je n’ai pas su quoi dire.",
            ["DialogueId"] = 12045731,
            ["GUID"] = "1E27BCBE",
            ["NextDialogue"] = 12045732,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BCBE",
            },
        [12045732] = {
            ["Content"] = "这些年来，我总是懊悔，如果不夏秽蚀发作的那一刻，我和师兄在她身边……该有多好。或者再往前，要是我们没有隔绝大风九章，是不是这一切都不会发生？",
            ["ContentFR"] = "Toutes ces années, je n’ai pensé qu’à ça... Si, au moment où la Dégradation a frappé Buxia, Yuming et moi avions été près d’elle... Ou même avant : si nous n’avions jamais isolé les Neuf Chapitres... est-ce que tout ça n’aurait pas été évité ?",
            ["DialogueId"] = 12045732,
            ["GUID"] = "1E27BCE8",
            ["NextDialogue"] = 12045733,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BCE8",
            },
        [12045733] = {
            ["Content"] = "我们为了追求自由，却忽视了与之而来的危险。{nickname}，你说，难道从一开始，我们就做错了吗？",
            ["ContentFR"] = "Nous avons poursuivi la liberté... en fermant les yeux sur les dangers qu’elle traîne avec elle. Dis-moi, {nickname}... est-ce qu’on s’est trompés dès le début ?",
            ["DialogueId"] = 12045733,
            ["GUID"] = "1E27BD12",
            ["NextDialogue"] = 12045734,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BD12",
            },
        [12045734] = {
            ["Content"] = "……刻舟，我也有很要好的朋友因为秽蚀而去世了，所以我明白你的心情。",
            ["ContentFR"] = "... Kezhou, j’ai aussi perdu une amie très chère à cause de la Dégradation. Je comprends ce que tu ressens.",
            ["DialogueId"] = 12045734,
            ["GUID"] = "1E27BD3C",
            ["NextDialogue"] = 12045735,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BD3C",
            },
        [12045735] = {
            ["Content"] = "但是，这件事的根源不在于大风九章，也不在于你们，而是秽蚀的错。所以不要自责。",
            ["ContentFR"] = "Mais la racine du problème n’est ni dans les Neuf Chapitres... ni en vous. La faute appartient à la Dégradation. À elle seule. Alors ne te condamne pas.",
            ["DialogueId"] = 12045735,
            ["GUID"] = "1E27BD66",
            ["NextDialogue"] = 12045736,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BD66",
            },
        [12045736] = {
            ["Content"] = "就算在大风九章统治的地方，不夏照样会变成无神无志的狴犴，无法和亲人交谈……我想，那也并不算是活着。",
            ["ContentFR"] = "Même sous l’autorité des Neuf Chapitres, Buxia se serait transformée en Bi’an — sans âme, sans volonté, incapable de parler à ses proches... Et ça... ce n’est pas vraiment vivre.",
            ["DialogueId"] = 12045736,
            ["GUID"] = "1E27BD90",
            ["NextDialogue"] = 12045737,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BD90",
            },
        [12045737] = {
            ["Content"] = "是非对错，往往难以判断……但我唯一可以肯定的是，你想要保护他人的心，绝不是错误的。",
            ["ContentFR"] = "Le bien, le mal... sont souvent difficiles à départager. Mais une chose est sûre : ton désir de protéger les autres n’a rien d’une erreur.",
            ["DialogueId"] = 12045737,
            ["GUID"] = "1E27BDBA",
            ["NextDialogue"] = 12045738,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BDBA",
            },
        [12045738] = {
            ["Content"] = "…………",
            ["ContentFR"] = "...",
            ["DialogueId"] = 12045738,
            ["GUID"] = "1E27BDE4",
            ["NextDialogue"] = 12045739,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BDE4",
            },
        [12045739] = {
            ["Content"] = "我曾经的生活非常简单。在鱼钩挂上饵食就能吸引鱼群，野兔被猎枪打中就会死，一切都遵循着最简单不过的原则。",
            ["ContentFR"] = "Avant, ma vie était simple. Un hameçon avec un appât attirait les poissons. Un lièvre touché par le fusil tombait. Tout obéissait à des règles... presque enfantines.",
            ["DialogueId"] = 12045739,
            ["GUID"] = "1E27BE0E",
            ["NextDialogue"] = 12045740,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BE0E",
            },
        [12045740] = {
            ["Content"] = "直到我离开故乡、踏上旅途，我才意识到世界远比我想象得更加复杂，事情也常常会偏离自己的预料。",
            ["ContentFR"] = "Et puis j’ai quitté ma terre natale, j’ai pris la route... et j’ai compris que le monde était bien plus complexe que je ne l’imaginais, et que les choses déviaient sans cesse de nos attentes.",
            ["DialogueId"] = 12045740,
            ["GUID"] = "1E27BE38",
            ["NextDialogue"] = 12045741,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BE38",
            },
        [12045741] = {
            ["Content"] = "我认识一个医生，他一直想拯救人，可他做不到。为了让那些人不至于死得更痛苦，他不得不杀死那些人，最终他也失去了生命。",
            ["ContentFR"] = "J’ai connu un médecin. Il voulait sauver des vies... mais il n’y arrivait pas. Pour éviter à certains de mourir dans une souffrance plus atroce encore, il a dû les tuer de ses propres mains. Et finalement, il a perdu la sienne.",
            ["DialogueId"] = 12045741,
            ["GUID"] = "1E27BE62",
            ["NextDialogue"] = 12045742,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BE62",
            },
        [12045742] = {
            ["Content"] = "我听说过一个孩子，他只想实现幼时的梦想。可是他为了追逐梦想做出的选择，却让他万劫不复。他失去了人类的身躯，在怪物的躯壳里苟延残喘。",
            ["ContentFR"] = "J’ai entendu parler d’un enfant qui ne désirait qu’accomplir son rêve d’enfance. Mais les choix qu’il a faits pour le poursuivre l’ont précipité dans l’abîme. Il a perdu son corps humain, et n’a survécu que dans une coquille de monstre.",
            ["DialogueId"] = 12045742,
            ["GUID"] = "1E27BE8C",
            ["NextDialogue"] = 12045743,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BE8C",
            },
        [12045743] = {
            ["Content"] = "短短数天，我发现原来命运是这么无常的东西。即使你做出其他选择，结果也未必一定比今天更好。",
            ["ContentFR"] = "En quelques jours à peine, j’ai découvert à quel point le destin est inconstant. Même si tu avais fait d’autres choix, rien ne dit que l’issue aurait été meilleure.",
            ["DialogueId"] = 12045743,
            ["GUID"] = "1E27BEB6",
            ["NextDialogue"] = 12045744,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BEB6",
            },
        [12045744] = {
            ["Content"] = "所以我想，与其去哀叹无法挽回的过去，不如去做些还来得及的事情。比如，如果秽蚀再度发生，该如何保护这里的人们。",
            ["ContentFR"] = "Alors je me dis qu’au lieu de pleurer un passé irréparable... mieux vaut agir là où il en est encore temps. Par exemple : si la Dégradation frappe de nouveau, comment protéger les gens d’ici.",
            ["DialogueId"] = 12045744,
            ["GUID"] = "1E27BEE0",
            ["NextDialogue"] = 12045745,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BEE0",
            },
        [12045745] = {
            ["Content"] = "……但是，唯独不要停下脚步，因为躲在原地是解决不了任何问题的。",
            ["ContentFR"] = "... Mais surtout, ne t’arrête pas. Parce que rester immobile ne changera rien.",
            ["DialogueId"] = 12045745,
            ["GUID"] = "1E27BF0A",
            ["NextDialogue"] = 12045746,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BF0A",
            },
        [12045746] = {
            ["Content"] = "“不要停下脚步”……",
            ["ContentFR"] = "« Ne t’arrête pas »...",
            ["DialogueId"] = 12045746,
            ["GUID"] = "1E27BF34",
            ["NextDialogue"] = 12045747,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BF34",
            },
        [12045747] = {
            ["Content"] = "哈哈……是啊。光躲在这里自怨自艾有什么用。往事不可谏，但那来者，我刻舟还得去追上一追。",
            ["ContentFR"] = "Ha ha... oui. Tu as raison. À quoi bon se cacher ici et se ronger le cœur ? Le passé... on ne le retient pas. Mais ce qui vient, je peux encore le poursuivre.",
            ["DialogueId"] = 12045747,
            ["GUID"] = "1E27BF5E",
            ["NextDialogue"] = 12045748,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BF5E",
            },
        [12045748] = {
            ["Content"] = "多谢你了……{nickname}。",
            ["ContentFR"] = "Merci... {nickname}.",
            ["DialogueId"] = 12045748,
            ["GUID"] = "1E27BF88",
            ["NextDialogue"] = 12045749,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BF88",
            },
        [12045749] = {
            ["Content"] = "好啦，我们出来了这么久，姑奶奶嘴上不说，心中一定着急得很。我们还是赶紧回去商议正事吧，别让她老人家担心了！",
            ["ContentFR"] = "Bon. On est dehors depuis un moment. Ma grande-tante ne le dira jamais à voix haute, mais elle doit être morte d’inquiétude. Allez, on rentre, avant qu’elle ne se ronge jusqu’aux os !",
            ["DialogueId"] = 12045749,
            ["GUID"] = "1E27BFB2",
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BFB2",
            },
        [12045801] = {
            ["Content"] = "你们回来啦！",
            ["ContentFR"] = "Vous voilà !",
            ["DialogueId"] = 12045801,
            ["GUID"] = "1E27C83A",
            ["NextDialogue"] = 12045802,
            ["RelatedWikiId"] = {
                [1] = 203007,
                [2] = 203009,
                },
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120458/1E27C83A",
            },
        [12045802] = {
            ["Content"] = "怎么都哭丧着脸？不会还在为白天的事发愁吧？没事没事，那么多应天尉呼啦啦一起上，还能守半个时辰，四舍五入不就是咱们和白龙五五开！",
            ["ContentFR"] = "Pourquoi ces têtes d’enterrement ? Vous êtes encore en train de ruminer ce qui s’est passé aujourd’hui ? Allons, allons ! Autant de Magistrats de Yingtian qui déboulent en hurlant, et on a tenu une demi-heure ! Si on veut voir le bon côté des choses... ça veut dire qu’on a fait jeu égal avec le Dragon d’Argent !",
            ["DialogueId"] = 12045802,
            ["GUID"] = "1E27C864",
            ["NextDialogue"] = 12045803,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120458/1E27C864",
            },
        [12045803] = {
            ["Content"] = "谁沮丧了。我可是一直在这儿统计损失，修理机傀，可不像某些人躲去林子里偷偷哭鼻子。",
            ["ContentFR"] = "Qui rumine ? Moi, j’étais ici à recenser les pertes et à rafistoler des méchapoupées — pas à aller pleurnicher en douce dans la forêt, contrairement à certains.",
            ["DialogueId"] = 12045803,
            ["GUID"] = "1E27C88E",
            ["NextDialogue"] = 12045804,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120458/1E27C88E",
            },
        [12045804] = {
            ["Content"] = "倒是你，心情好点了没？可别拖我们的后腿哦。",
            ["ContentFR"] = "... Ça va mieux ?  Ne nous ralentis pas, hein.",
            ["DialogueId"] = 12045804,
            ["GUID"] = "1E27C8B8",
            ["NextDialogue"] = 12045805,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120458/1E27C8B8",
            },
        [12045805] = {
            ["Content"] = "哈哈，谢姑奶奶关心！",
            ["ContentFR"] = "Ha ha ! Merci de t’en soucier, grande-tante !",
            ["DialogueId"] = 12045805,
            ["GUID"] = "1E27C8E2",
            ["NextDialogue"] = 12045806,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120458/1E27C8E2",
            },
        [12045806] = {
            ["Content"] = "多亏了{nickname}的开解，师兄那个问题我想明白了——谁规定我们就一定要被大风九章保护了？",
            ["ContentFR"] = "Grâce à {nickname}, j’ai enfin compris ce que Yuming voulait dire. Qui a décrété qu’on devait forcément compter sur la protection des Neuf Chapitres ?",
            ["DialogueId"] = 12045806,
            ["GUID"] = "1E27C90C",
            ["NextDialogue"] = 12045807,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120458/1E27C90C",
            },
        [12045807] = {
            ["Content"] = "我刻舟一人除不完秽蚀。若是十人、百人联手起来，大家都拿起武器，众志成城，还怕打不过一两个秽蚀者？",
            ["ContentFR"] = "Je ne peux pas lutter contre la Dégradation à moi seul. Mais à dix... à cent... si chacun prend les armes et qu’on se tient côte à côte, on ne va quand même pas trembler devant un ou deux Dégradés ?",
            ["DialogueId"] = 12045807,
            ["GUID"] = "1E27C936",
            ["NextDialogue"] = 12045808,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120458/1E27C936",
            },
        [12045808] = {
            ["Content"] = "事在人为。先前输止流两招，下一局，我们就一举把赢面扳回来。不管她在谋划什么，只要干脆利落地统统打破就可以！",
            ["ContentFR"] = "Ça dépend de nous. Zhiliu a pris l’avantage, très bien. La prochaine fois, on renverse la situation. Peu importe ce qu’elle trame : on le brise net.",
            ["DialogueId"] = 12045808,
            ["GUID"] = "1E27C960",
            ["NextDialogue"] = 12045809,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120458/1E27C960",
            },
        [12045809] = {
            ["Content"] = "气势不错，但光有气势可不行。那么，商量一下接下来的计划吧。",
            ["ContentFR"] = "Belle énergie. Mais l’énergie ne suffit pas. Alors discutons de la suite.",
            ["DialogueId"] = 12045809,
            ["GUID"] = "1E27C98A",
            ["NextDialogue"] = 12045810,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120458/1E27C98A",
            },
        [12045810] = {
            ["Content"] = "我想，山外山如今要做的是协助{nickname}，等{性别：他|她}解开止流的第三卦再做打算。对了，扶疏姑娘那边……",
            ["ContentFR"] = "À mon avis, les Pics Extérieurs doivent aider {nickname}. Une fois qu’{性别:il|elle} aura dénoué la troisième prophétie de Zhiliu, on avisera. Au fait... et de votre côté Dame Fushu... ?",
            ["DialogueId"] = 12045810,
            ["GUID"] = "1E27C9B4",
            ["NextDialogue"] = 12045811,
            ["RelatedWikiId"] = {
                [1] = 401005,
                },
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120458/1E27C9B4",
            },
        [12045811] = {
            ["Content"] = "我已经寻访到了无穷藏派传人隐居的地方，就在皓京西郊的椒兰村。",
            ["ContentFR"] = "J’ai localisé l’endroit où vit l’héritier de la Secte de l’Insondable Trésor, retiré du monde : au Village de Jiaolan, dans la banlieue ouest de Haojing.",
            ["DialogueId"] = 12045811,
            ["GUID"] = "1E27C9DE",
            ["NextDialogue"] = 12045812,
            ["RelatedWikiId"] = {
                [1] = 408020,
                [2] = 407014,
                },
            ["SpeakNpcId"] = 240002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120458/1E27C9DE",
            },
        [12045812] = {
            ["Content"] = "椒兰村？巧了，这里恰好有一位“本地向导”可以为你们带路。",
            ["ContentFR"] = "Village de Jiaolan ? Quelle coïncidence : il se trouve justement qu’on a ici un guide local tout désigné pour vous y mener.",
            ["DialogueId"] = 12045812,
            ["GUID"] = "1E27CA08",
            ["NextDialogue"] = 12045813,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120458/1E27CA08",
            },
        [12045813] = {
            ["Content"] = "哎？难不成这个地方就是刻舟你的老家？",
            ["ContentFR"] = "Hein ? Attends... ce ne serait pas... ton village, Kezhou ?",
            ["DialogueId"] = 12045813,
            ["GUID"] = "1E27CA32",
            ["NextDialogue"] = 12045814,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120458/1E27CA32",
            },
        [12045814] = {
            ["Content"] = "许久没回去了，没想到却是以这样的理由。哈哈，也好！是时候故地重游了！",
            ["ContentFR"] = "Ça fait longtemps que je n’y ai pas remis les pieds. Je ne pensais pas y retourner pour une raison pareille. Ha ha... Tant mieux. Il est temps d’y refaire un tour.",
            ["DialogueId"] = 12045814,
            ["GUID"] = "1E27CA5C",
            ["NextDialogue"] = 12045815,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120458/1E27CA5C",
            },
        [12045815] = {
            ["Content"] = "根据线报，自从执律阁震动之后，原本追捕你们的应天尉已经全线回撤。如今你们回去不会引起太多注意，正是潜入调查的好时机。",
            ["ContentFR"] = "D’après nos infos, depuis la secousse au Pavillon de l’Arbitrage, les Magistrats de Yingtian qui vous traquaient se sont repliés sur toute la ligne. Si vous retournez en ville maintenant, vous n’attirerez pas trop l’attention — c’est le moment idéal pour infiltrer et enquêter.",
            ["DialogueId"] = 12045815,
            ["GUID"] = "1E27CA86",
            ["NextDialogue"] = 12045816,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120458/1E27CA86",
            },
        [12045816] = {
            ["Content"] = "好。待你们准备好了，我们就走吧。",
            ["ContentFR"] = "Bien. Quand vous serez {性别:prêts|prêtes}... on y va.",
            ["DialogueId"] = 12045816,
            ["GUID"] = "1E27CAB0",
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120458/1E27CAB0",
            },
        [12045901] = {
            ["Content"] = "小朋友，你知道村庄中关于“无穷藏派”的传闻吗？",
            ["ContentFR"] = "Dis-moi, tu as déjà entendu parler de la Secte de l’Insondable Trésor dans le village ?",
            ["DialogueId"] = 12045901,
            ["GUID"] = "1E27D8A2",
            ["NextDialogue"] = 12045902,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120459/1E27D8A2",
            },
        [12045902] = {
            ["Content"] = "虎子不太清楚……",
            ["ContentFR"] = "Je sais pas trop...",
            ["DialogueId"] = 12045902,
            ["GUID"] = "1E27D8CC",
            ["NextDialogue"] = 12045903,
            ["SpeakNpcId"] = 240037,
            ["TalkActionId"] = {
                [1] = "240037:Shy03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120459/1E27D8CC",
            },
        [12045903] = {
            ["Content"] = "对了，阿爸说过，不能和陌生人说话！你们是陌生人吗？",
            ["ContentFR"] = "Ah ! Papa a dit que je ne devais pas parler aux inconnus ! Vous êtes des inconnus ?",
            ["DialogueId"] = 12045903,
            ["GUID"] = "1E27D8F6",
            ["NextDialogue"] = 12045904,
            ["SpeakNpcId"] = 240037,
            ["VoiceName"] = "voice/$Locale$/story/1204/120459/1E27D8F6",
            },
        [12045904] = {
            ["Content"] = "哈哈，我们已经说过两句话，就是朋友，不能算陌生人了。",
            ["ContentFR"] = "Ha ha ! On a déjà échangé deux phrases, non ? Ça fait déjà de nous des amis.",
            ["DialogueId"] = 12045904,
            ["GUID"] = "1E27D920",
            ["NextDialogue"] = 12045905,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120459/1E27D920",
            },
        [12045905] = {
            ["Content"] = "对了，小朋友，你的阿爸现在在哪儿？",
            ["ContentFR"] = "Dis-moi, ton papa est où ?",
            ["DialogueId"] = 12045905,
            ["GUID"] = "1E27D94A",
            ["NextDialogue"] = 12045906,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120459/1E27D94A",
            },
        [12045906] = {
            ["Content"] = "阿爸不在家，早上就出去砍柴啦。如果有什么问题，问我阿娘吧，她就在对面那儿晒香呢！",
            ["ContentFR"] = "Il est parti couper du bois ce matin. Si vous avez besoin de quelque chose, demandez à maman ! Elle fait sécher de l’encens, là-bas !",
            ["DialogueId"] = 12045906,
            ["GUID"] = "1E27D974",
            ["SpeakNpcId"] = 240037,
            ["VoiceName"] = "voice/$Locale$/story/1204/120459/1E27D974",
            },
        [12046001] = {
            ["Content"] = "请问，您对村中隐居的无穷藏派有所了解吗？",
            ["ContentFR"] = "Excusez-moi, savez-vous si quelqu’un lié à la Secte de l’Insondable Trésor vit ici, en retrait du monde ?",
            ["DialogueId"] = 12046001,
            ["GUID"] = "1E27E90A",
            ["NextDialogue"] = 12046002,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120460/1E27E90A",
            },
        [12046002] = {
            ["Content"] = "无穷藏派？有些陌生……若说到能教经纶数算的先生，倒还能想起一二。",
            ["ContentFR"] = "Insondable Trésor ? Ça ne me dit rien... Mais si vous cherchez un maître qui enseigne les textes et le calcul, ça, peut-être.",
            ["DialogueId"] = 12046002,
            ["FacialId"] = {
                [1] = "240038:Cin_Think",
                },
            ["GUID"] = "1E27E934",
            ["NextDialogue"] = 12046003,
            ["SpeakNpcId"] = 240038,
            ["TalkActionId"] = {
                [1] = "240038:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120460/1E27E934",
            },
        [12046003] = {
            ["Content"] = "这些人精通卜算奇门之术，也就是说热爱捣鼓铜钱、龟壳这些玩意儿。这样说，能让你想起点什么吗？",
            ["ContentFR"] = "Quelqu’un qui pratique la divination, manipule des pièces de cuivre ou des carapaces de tortue... Ça vous évoque quelque chose ?",
            ["DialogueId"] = 12046003,
            ["GUID"] = "1E27E95E",
            ["NextDialogue"] = 12046004,
            ["SpeakNpcId"] = 240013,
            ["TalkActionId"] = {
                [1] = "240038:Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120460/1E27E95E",
            },
        [12046004] = {
            ["Content"] = "……刻舟，怎么是你？！",
            ["ContentFR"] = "... Kezhou ? C’est toi ?!",
            ["DialogueId"] = 12046004,
            ["FacialId"] = {
                [1] = "240038:Cin_Angry01",
                },
            ["GUID"] = "1E27E988",
            ["NextDialogue"] = 12046005,
            ["SpeakNpcId"] = 240038,
            ["TalkActionId"] = {
                [1] = "240038:Angry01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120460/1E27E988",
            },
        [12046005] = {
            ["Content"] = "啊，咳，是啊……香芸姐。那个，你们身体可还好？一别数年，孩子都这么高了——",
            ["ContentFR"] = "Ah... <I>hum.</> Oui... Xiangyun. Comment ça va, depuis le temps ? Ton fils a bien grandi...",
            ["DialogueId"] = 12046005,
            ["GUID"] = "1E27E9B2",
            ["NextDialogue"] = 12046006,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120460/1E27E9B2",
            },
        [12046006] = {
            ["Content"] = "虎子，不许在外面玩了，赶紧回家做功课去！小心沾染上什么不三不四的人。",
            ["ContentFR"] = "Huzi ! Rentre immédiatement faire tes devoirs ! Et ne traîne pas avec n’importe qui !",
            ["DialogueId"] = 12046006,
            ["GUID"] = "1E27E9DC",
            ["NextDialogue"] = 12046007,
            ["SpeakNpcId"] = 240038,
            ["VoiceName"] = "voice/$Locale$/story/1204/120460/1E27E9DC",
            },
        [12046007] = {
            ["Content"] = "恕我无话与各位可说。<H>罪人之后</>还是赶紧请回吧，可别把晦气带来村子了。",
            ["ContentFR"] = "Je n’ai rien à dire aux descendants d’un <H>criminel</>. Partez. Ne ramenez pas votre malchance ici.",
            ["DialogueId"] = 12046007,
            ["GUID"] = "1E27EA06",
            ["SpeakNpcId"] = 240038,
            ["TalkActionId"] = {
                [1] = "240038:Angry01_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120460/1E27EA06",
            },
        [12046101] = {
            ["Content"] = "李阿伯，我回来了。向你打听一件事可好？",
            ["ContentFR"] = "Oncle Li... c’est moi. Je peux vous poser une question ?",
            ["DialogueId"] = 12046101,
            ["GUID"] = "1E27F972",
            ["NextDialogue"] = 12046102,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120461/1E27F972",
            },
        [12046102] = {
            ["Content"] = "……你是，刻舟……你长高了，也壮实了……",
            ["ContentFR"] = "... Kezhou ? Tu as grandi... et pris des épaules...",
            ["DialogueId"] = 12046102,
            ["FacialId"] = {
                [1] = "240039:CM_Happy01",
                },
            ["GUID"] = "1E27F99C",
            ["NextDialogue"] = 12046103,
            ["SpeakNpcId"] = 240039,
            ["TalkActionId"] = {
                [1] = "240039:Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120461/1E27F99C",
            },
        [12046103] = {
            ["Content"] = "时隔十几年，你终于愿意回村看看了……",
            ["ContentFR"] = "Après tant d’années... tu as finalement décidé de revenir au village.",
            ["DialogueId"] = 12046103,
            ["GUID"] = "1E27F9C6",
            ["NextDialogue"] = 12046104,
            ["SpeakNpcId"] = 240039,
            ["VoiceName"] = "voice/$Locale$/story/1204/120461/1E27F9C6",
            },
        [12046104] = {
            ["Content"] = "我想向您打听个人。放心，我只是帮朋友个忙，问完就走，一刻钟都不多留。",
            ["ContentFR"] = "Je cherche quelqu’un. Juste pour aider des amis. On repartira aussitôt.",
            ["DialogueId"] = 12046104,
            ["GUID"] = "1E27F9F0",
            ["NextDialogue"] = 12046105,
            ["SpeakNpcId"] = 240013,
            ["TalkActionId"] = {
                [1] = "240039:Talk02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120461/1E27F9F0",
            },
        [12046105] = {
            ["Content"] = "唉，我不是这个意思……算了，你问吧。",
            ["ContentFR"] = "Ce n’est pas ce que je voulais dire... Enfin. Demande.",
            ["DialogueId"] = 12046105,
            ["FacialId"] = {
                [1] = "240039:CM_Sad01",
                },
            ["GUID"] = "1E27FA1A",
            ["NextDialogue"] = 12046106,
            ["SpeakNpcId"] = 240039,
            ["TalkActionId"] = {
                [1] = "240039:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120461/1E27FA1A",
            },
        [12046106] = {
            ["Content"] = "您知道有位无穷藏派高人在村里隐居吗？",
            ["ContentFR"] = "Un maître de la Secte de l’Insondable Trésor vivrait ici ?",
            ["DialogueId"] = 12046106,
            ["GUID"] = "1E27FA44",
            ["NextDialogue"] = 12046107,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120461/1E27FA44",
            },
        [12046107] = {
            ["Content"] = "你是说<H>静渊居士</>？断桥对面，崖边那处屋舍便是。",
            ["ContentFR"] = "Tu parles de <H>Maître Jingyuan</> ? Sa demeure est au-delà du pont brisé, près de la falaise.",
            ["DialogueId"] = 12046107,
            ["FacialId"] = {
                [1] = "240039:CM_Idle",
                },
            ["GUID"] = "1E27FA6E",
            ["NextDialogue"] = 12046108,
            ["SpeakNpcId"] = 240039,
            ["TalkActionId"] = {
                [1] = "240039:Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120461/1E27FA6E",
            },
        [12046108] = {
            ["Content"] = "哦！原来就是我以前总是绕着走的那块地儿！",
            ["ContentFR"] = "Ah ! L’endroit que j’évitais toujours quand j’étais gosse !",
            ["DialogueId"] = 12046108,
            ["GUID"] = "1E27FA98",
            ["NextDialogue"] = 12046109,
            ["SpeakNpcId"] = 240013,
            ["TalkActionId"] = {
                [1] = "240039:Talk02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120461/1E27FA98",
            },
        [12046109] = {
            ["Content"] = "我小时候到处上墙揭瓦，村里全都被我倒腾了个遍，每块石头在哪儿我都记得。唯有那里，我每次跑去，就迷迷瞪瞪，不知怎的就发现自己倒栽在树桩旁。",
            ["ContentFR"] = "Je connaissais chaque pierre du village... sauf cet endroit. Chaque fois que je m’en approchais, je me retrouvais étourdi... et je finissais la tête la première contre une souche.",
            ["DialogueId"] = 12046109,
            ["GUID"] = "1E27FAC2",
            ["NextDialogue"] = 12046110,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120461/1E27FAC2",
            },
        [12046110] = {
            ["Content"] = "若那是无穷藏派的地界，一切都说得通了！谢啦，伯伯。那我们就先告辞了——",
            ["ContentFR"] = "Si c’est le domaine de l’Insondable Trésor... tout s’explique. Merci, Oncle Li. On va y aller—",
            ["DialogueId"] = 12046110,
            ["GUID"] = "1E27FAEC",
            ["NextDialogue"] = 12046111,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120461/1E27FAEC",
            },
        [12046111] = {
            ["Content"] = "……刻舟，稍等片刻。",
            ["ContentFR"] = "... Kezhou. Attends.",
            ["DialogueId"] = 12046111,
            ["GUID"] = "1E27FB16",
            ["NextDialogue"] = 12046112,
            ["SpeakNpcId"] = 240039,
            ["VoiceName"] = "voice/$Locale$/story/1204/120461/1E27FB16",
            },
        [12046112] = {
            ["Content"] = "嗯？怎么了，阿伯？",
            ["ContentFR"] = "Oui ?",
            ["DialogueId"] = 12046112,
            ["GUID"] = "1E27FB40",
            ["NextDialogue"] = 12046113,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120461/1E27FB40",
            },
        [12046113] = {
            ["Content"] = "当初赶走你们，我自觉亏欠。这些年来，你过得可还好？",
            ["ContentFR"] = "Quand nous vous avons chassés... j’en ai toujours eu du remords. Comment as-tu vécu, toutes ces années ?",
            ["DialogueId"] = 12046113,
            ["GUID"] = "1E27FB6A",
            ["NextDialogue"] = 12046114,
            ["SpeakNpcId"] = 240039,
            ["TalkActionId"] = {
                [1] = "240039:Sigh_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120461/1E27FB6A",
            },
        [12046114] = {
            ["Content"] = "嗨呀，您千万别放在心上。我现在活得好好的，吃好喝好，逍遥自在。我爹心宽，也绝不会念你。",
            ["ContentFR"] = "Allons, ne vous en faites pas. Je vais très bien. Je mange à ma faim, je dors tranquille. Je vis libre. Mon père n’aurait jamais gardé rancune.",
            ["DialogueId"] = 12046114,
            ["GUID"] = "1E27FB94",
            ["NextDialogue"] = 12046115,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120461/1E27FB94",
            },
        [12046115] = {
            ["Content"] = "……唉。你爹他从始至终都是个好人。",
            ["ContentFR"] = "... Ton père était un homme bon.",
            ["DialogueId"] = 12046115,
            ["FacialId"] = {
                [1] = "240039:CM_Sad01",
                },
            ["GUID"] = "1E27FBBE",
            ["NextDialogue"] = 12046116,
            ["SpeakNpcId"] = 240039,
            ["VoiceName"] = "voice/$Locale$/story/1204/120461/1E27FBBE",
            },
        [12046116] = {
            ["Content"] = "可惜，可惜了。也怨我那时候没有站出来为你们说话……",
            ["ContentFR"] = "Je regrette de ne pas m’être levé pour vous défendre.",
            ["DialogueId"] = 12046116,
            ["GUID"] = "1E27FBE8",
            ["NextDialogue"] = 12046117,
            ["SpeakNpcId"] = 240039,
            ["VoiceName"] = "voice/$Locale$/story/1204/120461/1E27FBE8",
            },
        [12046117] = {
            ["Content"] = "别，您可千万别自责啊！我们家当初出事，您为我们送水送食，上下打点。我和我娘对您从来没有一分怨言。",
            ["ContentFR"] = "Non, surtout pas. Quand les choses ont mal tourné pour nous, vous nous avez apporté de l’eau, de la nourriture... vous avez fait ce que vous pouviez pour nous aider. Ma mère et moi ne vous en avons jamais voulu.",
            ["DialogueId"] = 12046117,
            ["GUID"] = "1E27FC12",
            ["NextDialogue"] = 12046118,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120461/1E27FC12",
            },
        [12046118] = {
            ["Content"] = "总是想那些过去的事情，会折寿的。您老可要放宽心，争取活到一百岁。到时候，我再来给您贺寿！",
            ["ContentFR"] = "Ressasser le passé ne fait que raccourcir la vie. Promettez-moi plutôt d’atteindre cent ans. Je reviendrai vous fêter ça !",
            ["DialogueId"] = 12046118,
            ["GUID"] = "1E27FC3C",
            ["NextDialogue"] = 12046119,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120461/1E27FC3C",
            },
        [12046119] = {
            ["Content"] = "这次真得走啦，以后再来找您叙旧。希望下次见到您，您还能这么精神矍铄。",
            ["ContentFR"] = "Bon... cette fois, on doit vraiment y aller. J’espère vous revoir aussi solide la prochaine fois.",
            ["DialogueId"] = 12046119,
            ["GUID"] = "1E27FC66",
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120461/1E27FC66",
            },
        [12046201] = {
            ["Content"] = "……你们终于来了。",
            ["ContentFR"] = "... Vous voilà enfin.",
            ["DialogueId"] = 12046201,
            ["GUID"] = "1E2809DA",
            ["NextDialogue"] = 12046202,
            ["SpeakNpcId"] = 240040,
            ["VoiceName"] = "voice/$Locale$/story/1204/120462/1E2809DA",
            },
        [12046202] = {
            ["Content"] = "今日自旭日初升，我便候在这棵梧桐树下，等着诸位的到访。",
            ["ContentFR"] = "Depuis les premières lueurs du jour, je vous attends sous cet arbre.",
            ["DialogueId"] = 12046202,
            ["GUID"] = "1E280A04",
            ["NextDialogue"] = 12046203,
            ["SpeakNpcId"] = 240040,
            ["VoiceName"] = "voice/$Locale$/story/1204/120462/1E280A04",
            },
        [12046203] = {
            ["Content"] = "您早已知道我们要来？",
            ["ContentFR"] = "Vous saviez que nous viendrions ?",
            ["DialogueId"] = 12046203,
            ["GUID"] = "1E280A2E",
            ["NextDialogue"] = 12046204,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120462/1E280A2E",
            },
        [12046204] = {
            ["Content"] = "无穷藏派自诩以卜算奇门之术窥测天命。虽凭凡人之身，妄言未来，终为枉然。但这无伤大雅的预测还未曾失了准头。",
            ["ContentFR"] = "La Secte de l’Insondable Trésor se targue de lire les fils du destin par l’art divinatoire. Il est vain pour un mortel de prétendre saisir l’avenir... Mais pour ce genre de présage, je ne me trompe guère.",
            ["DialogueId"] = 12046204,
            ["GUID"] = "1E280A58",
            ["NextDialogue"] = 12046205,
            ["SpeakNpcId"] = 240040,
            ["VoiceName"] = "voice/$Locale$/story/1204/120462/1E280A58",
            },
        [12046205] = {
            ["Content"] = "却未自我介绍。我是本代掌门，号静渊居士，我那逆徒止流承蒙你们照顾了。",
            ["ContentFR"] = "Permettez-moi de me présenter. Je suis Jingyuan, maître actuel de la secte. Ma disciple indocile, Zhiliu... semble vous avoir causé bien des tourments.",
            ["DialogueId"] = 12046205,
            ["GUID"] = "1E280A82",
            ["NextDialogue"] = 12046206,
            ["RelatedWikiId"] = {
                [1] = 203012,
                [2] = 203001,
                [3] = 407014,
                },
            ["SpeakNpcId"] = 240040,
            ["VoiceName"] = "voice/$Locale$/story/1204/120462/1E280A82",
            },
        [12046206] = {
            ["Content"] = "你说自己什么都能猜到，那让白考考你！你猜到我们此行的目的了吗？",
            ["ContentFR"] = "Tu dis pouvoir tout prévoir ? Alors dis-moi pourquoi on est là !",
            ["DialogueId"] = 12046206,
            ["GUID"] = "1E280AAC",
            ["NextDialogue"] = 12046207,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120462/1E280AAC",
            },
        [12046207] = {
            ["Content"] = "呵呵，放心。这位小友所中的迷卦，我随后就为你们化解。届时{性别：他|她}被遮蔽的记忆也将悉数复原。",
            ["ContentFR"] = "Rassurez-vous. L’hexagramme qui trouble votre compagnon sera bientôt dissipé. Une fois le voile levé, {性别:il|elle} retrouvera l’intégralité de ses souvenirs.",
            ["DialogueId"] = 12046207,
            ["GUID"] = "1E280AD6",
            ["NextDialogue"] = 12046208,
            ["SpeakNpcId"] = 240040,
            ["VoiceName"] = "voice/$Locale$/story/1204/120462/1E280AD6",
            },
        [12046208] = {
            ["Content"] = "但在那之前，可否赏光，先听一则故事呢？",
            ["ContentFR"] = "Mais avant cela... accepteriez-vous d’entendre une histoire ?",
            ["DialogueId"] = 12046208,
            ["GUID"] = "1E280B00",
            ["SpeakNpcId"] = 240040,
            ["VoiceName"] = "voice/$Locale$/story/1204/120462/1E280B00",
            },
        [12046301] = {
            ["Content"] = "您故事中的那个小女孩……就是止流吗？",
            ["ContentFR"] = "La petite fille de votre histoire... c’était Zhiliu, n’est-ce pas ?",
            ["DialogueId"] = 12046301,
            ["GUID"] = "1E281A42",
            ["NextDialogue"] = 12046302,
            ["RelatedWikiId"] = {
                [1] = 203012,
                [2] = 203001,
                [3] = 203007,
                [4] = 407014,
                },
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120463/1E281A42",
            },
        [12046302] = {
            ["Content"] = "正是。",
            ["ContentFR"] = "En effet.",
            ["DialogueId"] = 12046302,
            ["GUID"] = "1E281A6C",
            ["NextDialogue"] = 12046303,
            ["SpeakNpcId"] = 240040,
            ["VoiceName"] = "voice/$Locale$/story/1204/120463/1E281A6C",
            },
        [12046303] = {
            ["Content"] = "……原来老爹救下的那个小女孩，从来没有忘掉过这件事情。",
            ["ContentFR"] = "... Alors elle ne l’a jamais oublié. La petite que mon père a sauvée a gardé ce souvenir toutes ces années.",
            ["DialogueId"] = 12046303,
            ["GUID"] = "1E281A96",
            ["NextDialogue"] = 12046304,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120463/1E281A96",
            },
        [12046304] = {
            ["Content"] = "老爹若是知道他当年的见义勇为，会在十几年后掀起这么大的风波，恐怕在虞渊之底都会吓一大跳吧。",
            ["ContentFR"] = "Si mon vieux savait que son geste pour défendre la justice provoquerait, plus de dix ans plus tard, un tel tumulte... même au fond de l’Abîme de Yu, il en sursauterait.",
            ["DialogueId"] = 12046304,
            ["GUID"] = "1E281AC0",
            ["NextDialogue"] = 12046305,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120463/1E281AC0",
            },
        [12046305] = {
            ["Content"] = "我已出世。徒弟的是非对错，我无意评判。",
            ["ContentFR"] = "Je me suis retiré du monde. Les fautes et les mérites de ma disciple ne m’appartiennent plus à juger.",
            ["DialogueId"] = 12046305,
            ["GUID"] = "1E281AEA",
            ["NextDialogue"] = 12046306,
            ["SpeakNpcId"] = 240040,
            ["VoiceName"] = "voice/$Locale$/story/1204/120463/1E281AEA",
            },
        [12046306] = {
            ["Content"] = "{nickname}，我可为你解开你身上的迷卦。等你准备好，就与我说吧。",
            ["ContentFR"] = "{nickname}, je peux dissiper l’hexagramme qui t’entrave. Lorsque tu seras {性别:prêt|prête}, dis-le-moi.",
            ["DialogueId"] = 12046306,
            ["GUID"] = "1E281B14",
            ["SpeakNpcId"] = 240040,
            ["VoiceName"] = "voice/$Locale$/story/1204/120463/1E281B14",
            },
        [12046401] = {
            ["Content"] = "{nickname}，很抱歉把你卷入了这一切。",
            ["ContentFR"] = "{nickname}, je regrette de t’avoir entraîné dans tout cela.",
            ["DialogueId"] = 12046401,
            ["GUID"] = "1E282AAA",
            ["NextDialogue"] = 12046402,
            ["RelatedWikiId"] = {
                [1] = 203001,
                [2] = 401005,
                },
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282AAA",
            },
        [12046402] = {
            ["Content"] = "现在再说抱歉，是不是有点晚了？",
            ["ContentFR"] = "Vous ne trouvez pas que ces excuses arrivent un peu tard ?",
            ["DialogueId"] = 12046402,
            ["GUID"] = "1E282AD4",
            ["NextDialogue"] = 12046403,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282AD4",
            },
        [12046403] = {
            ["Content"] = "呵呵……说的也是呢。我并没有留给你选择的机会。",
            ["ContentFR"] = "Héhé... sans doute. Je ne t’ai jamais laissé le choix.",
            ["DialogueId"] = 12046403,
            ["GUID"] = "1E282AFE",
            ["NextDialogue"] = 12046404,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282AFE",
            },
        [12046404] = {
            ["Content"] = "我必须承认，从发现你的能力开始，我便谋划着如何将你带回华胥，让这份力量成为我的助力。",
            ["ContentFR"] = "Je dois l’admettre : dès l’instant où j’ai découvert ton pouvoir, j’ai réfléchi à la manière de te ramener à Huaxu... pour que cette force devienne un levier dans mon plan.",
            ["DialogueId"] = 12046404,
            ["GUID"] = "1E282B28",
            ["NextDialogue"] = 12046405,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282B28",
            },
        [12046405] = {
            ["Content"] = "怀璧其罪。你有着这份奇异的和鸣之力，便注定与平凡的命运无缘。敌人接踵而至，夹道荆棘丛生，你接下来的路，一定走得很艰难。",
            ["ContentFR"] = "Un trésor attire le malheur. Avec cette résonance singulière qui est la tienne, tu n’étais jamais destiné à une existence ordinaire. Les ennemis se succéderont. Les ronces barreront ta route. Le chemin qui t’attend sera âpre.",
            ["DialogueId"] = 12046405,
            ["GUID"] = "1E282B52",
            ["NextDialogue"] = 12046406,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282B52",
            },
        [12046406] = {
            ["Content"] = "那是我要面对的事情，与你无关。",
            ["ContentFR"] = "C’est mon affaire. Pas la vôtre.",
            ["DialogueId"] = 12046406,
            ["GUID"] = "1E282B7C",
            ["NextDialogue"] = 12046407,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282B7C",
            },
        [12046407] = {
            ["Content"] = "我并非想故意为难你，恰恰相反，我是在允诺你一份报酬。",
            ["ContentFR"] = "Je n’ai jamais voulu alourdir ton fardeau. Au contraire... je t’offre une compensation.",
            ["DialogueId"] = 12046407,
            ["GUID"] = "1E282BA6",
            ["NextDialogue"] = 12046408,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282BA6",
            },
        [12046408] = {
            ["Content"] = "憎恨我吗？认为我惺惺作态吗？",
            ["ContentFR"] = "Me hais-tu ? Penses-tu que je joue la comédie ?",
            ["DialogueId"] = 12046408,
            ["GUID"] = "1E282BD0",
            ["NextDialogue"] = 12046409,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282BD0",
            },
        [12046409] = {
            ["Content"] = "怎样都好……我只希望，接下来的这起卦象可以成为对你的部分补偿。",
            ["ContentFR"] = "Peu importe... J’espère seulement que cette troisième divination pourra constituer une part de réparation.",
            ["DialogueId"] = 12046409,
            ["GUID"] = "1E282BFA",
            ["NextDialogue"] = 12046410,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282BFA",
            },
        [12046410] = {
            ["Content"] = "第三起，革之明夷。大人虎变，晦若坠星，陵悬于虚，辰宿易主。",
            ["ContentFR"] = "Le troisième : renversement et lumière blessée — le grand change tel le tigre ; la clarté chute comme une étoile déclinante ; un mausolée suspendu dans le vide ; les constellations changent de maître.",
            ["DialogueId"] = 12046410,
            ["GUID"] = "1E282C24",
            ["NextDialogue"] = 12046411,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282C24",
            },
        [12046411] = {
            ["Content"] = "大风九章的中枢，其名为太虚陵，高悬于执律阁上方的穹顶之中。那里是一切之始。",
            ["ContentFR"] = "Le centre des Neuf Chapitres de Dafeng porte le nom de Mausolée de Taixu. Il flotte au-dessus du Pavillon de l’Arbitrage, dans la voûte céleste. C’est là que tout a commencé.",
            ["DialogueId"] = 12046411,
            ["GUID"] = "1E282C4E",
            ["NextDialogue"] = 12046412,
            ["RelatedWikiId"] = {
                [1] = 408021,
                },
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282C4E",
            },
        [12046412] = {
            ["Content"] = "弑神并非易事……凡人之力，岂可窥伺神明？",
            ["ContentFR"] = "Tuer un dieu n’est pas chose aisée. Les mortels ne sont pas faits pour lever la main sur le divin.",
            ["DialogueId"] = 12046412,
            ["GUID"] = "1E282C78",
            ["NextDialogue"] = 12046413,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282C78",
            },
        [12046413] = {
            ["Content"] = "即便太皓已被种种手段削弱，其力生生不息，与凡人之别，仍不啻天渊。能杀死神明的，唯有神明。",
            ["ContentFR"] = "Même affaibli, Taihao demeure une source inépuisable de puissance. La distance entre dieu et mortel reste un gouffre sans fond. Seul un dieu peut en abattre un autre.",
            ["DialogueId"] = 12046413,
            ["GUID"] = "1E282CA2",
            ["NextDialogue"] = 12046414,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282CA2",
            },
        [12046414] = {
            ["Content"] = "因此，当初在祭坛之上，我必须与烛阴缔结同生共死的契约。此棋不容有失。",
            ["ContentFR"] = "C’est pourquoi, sur l’autel, j’ai dû conclure avec Zhuyin un Pacte d’âmes — vie liée à vie, mort liée à mort. Ce coup ne souffrait aucun échec.",
            ["DialogueId"] = 12046414,
            ["GUID"] = "1E282CCC",
            ["NextDialogue"] = 12046415,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282CCC",
            },
        [12046415] = {
            ["Content"] = "魂契是亘古传下的几大术式其一。龙渊上卿的力量本为大风九章所授予，借助这点，我能成为承载魂契的容器，我的生命也从此与烛阴相连。",
            ["ContentFR"] = "Le Pacte d’âmes est l’un des rites primordiaux transmis depuis l’aube des temps. En tant que Haut Chancelier de Longyuan, j’ai reçu des Neuf Chapitres l’autorité nécessaire pour en devenir le réceptacle. Depuis lors, ma vie est indissociablement liée à celle de Zhuyin.",
            ["DialogueId"] = 12046415,
            ["GUID"] = "1E282CF6",
            ["NextDialogue"] = 12046416,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282CF6",
            },
        [12046416] = {
            ["Content"] = "烛阴久经封印，其力已衰。下一步，我将在天人陵墓之巅，燃烧己身性命，作为烛阴的祭牲，增幅其力量。",
            ["ContentFR"] = "Après tant d’années de scellé, sa puissance s’est amoindrie. La prochaine étape sera d’offrir ma propre vie au sommet du Mausolée, comme sacrifice destiné à raviver sa force.",
            ["DialogueId"] = 12046416,
            ["GUID"] = "1E282D20",
            ["NextDialogue"] = 12046417,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282D20",
            },
        [12046417] = {
            ["Content"] = "使烛阴归于巢，自相残杀，双龙同归于尽。这便是我能算出的解法。",
            ["ContentFR"] = "Que Zhuyin regagne son domaine. Que les deux dragons s’entredéchirent. Qu’ils périssent ensemble. C’est la seule issue que mes calculs révèlent.",
            ["DialogueId"] = 12046417,
            ["GUID"] = "1E282D4A",
            ["NextDialogue"] = 12046418,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282D4A",
            },
        [12046418] = {
            ["Content"] = "而你在这棋局中，要做的事情很简单：在祂们双双力竭之时，杀死我，终结这一切。如此一来，大风九章便能宣告颠覆。",
            ["ContentFR"] = "Quant à toi, ta tâche dans cette partie est simple : lorsqu’ils seront tous deux épuisés... tue-moi. Mets un terme à tout cela. Alors seulement les Neuf Chapitres pourront être renversés.",
            ["DialogueId"] = 12046418,
            ["GUID"] = "1E282D74",
            ["NextDialogue"] = 12046419,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282D74",
            },
        [12046419] = {
            ["Content"] = "……杀死你？",
            ["ContentFR"] = "... Vous tuer ?",
            ["DialogueId"] = 12046419,
            ["GUID"] = "1E282D9E",
            ["NextDialogue"] = 12046420,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282D9E",
            },
        [12046420] = {
            ["Content"] = "没错。",
            ["ContentFR"] = "Exactement.",
            ["DialogueId"] = 12046420,
            ["GUID"] = "1E282DC8",
            ["NextDialogue"] = 12046421,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282DC8",
            },
        [12046421] = {
            ["Content"] = "魂契的一方死亡时，另一方也无法逃过契约的反噬。",
            ["ContentFR"] = "Lorsque l’un des deux liés par le pacte meurt, l’autre subit inévitablement le contrecoup. C’est la loi du lien.",
            ["DialogueId"] = 12046421,
            ["GUID"] = "1E282DF2",
            ["NextDialogue"] = 12046422,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282DF2",
            },
        [12046422] = {
            ["Content"] = "太皓、烛阴本出同源，无法真正给对方带来了断，但魂契的反噬却由祂们共同承担。此时借助契约的力量，就能以我的死亡给一切划下终结。",
            ["ContentFR"] = "Taihao et Zhuyin partagent une origine commune ; ils ne peuvent véritablement s’anéantir l’un l’autre. Mais le contrecoup du pacte, lui, les frappera tous deux. Ma mort deviendra la clef qui scellera leur fin.",
            ["DialogueId"] = 12046422,
            ["GUID"] = "1E282E1C",
            ["NextDialogue"] = 12046423,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282E1C",
            },
        [12046423] = {
            ["Content"] = "鼎盛状态的神明，或许能够承受住契约的反噬。但力竭的神明可未必。",
            ["ContentFR"] = "Un dieu à l’apogée de sa puissance pourrait peut-être supporter une telle répercussion. Mais un dieu à bout de forces... rien n’est certain.",
            ["DialogueId"] = 12046423,
            ["GUID"] = "1E282E46",
            ["NextDialogue"] = 12046424,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282E46",
            },
        [12046424] = {
            ["Content"] = "而你，将收获名望，以及助力。",
            ["ContentFR"] = "Et toi, tu y gagneras renommée et soutien.",
            ["DialogueId"] = 12046424,
            ["GUID"] = "1E282E70",
            ["NextDialogue"] = 12046425,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282E70",
            },
        [12046425] = {
            ["Content"] = "华胥已被神明护佑近千年，一旦龙神陨落，必将群龙无首。这时候，需要一个人走出来鼓舞他们，将人心重新凝聚起来。这个英雄，就是你。",
            ["ContentFR"] = "Huaxu vit sous la protection des Seigneurs Dragons depuis près d’un millénaire. Lorsque les dieux tomberont, le monde se retrouvera sans guide. Quelqu’un devra se lever, rallier les cœurs, rendre au peuple une direction. Ce héros... ce sera toi.",
            ["DialogueId"] = 12046425,
            ["GUID"] = "1E282E9A",
            ["NextDialogue"] = 12046426,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282E9A",
            },
        [12046426] = {
            ["Content"] = "届时，英雄的名声能带来莫大的助力。这样的报酬，你满意吗？",
            ["ContentFR"] = "Le nom d’un héros porte un poids immense. N’est-ce pas là une récompense suffisante ?",
            ["DialogueId"] = 12046426,
            ["GUID"] = "1E282EC4",
            ["NextDialogue"] = 12046427,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282EC4",
            },
        [12046427] = {
            ["Content"] = "止流掌柜，你恐怕弄错了什么。",
            ["ContentFR"] = "Zhiliu... vous vous trompez sur un point.",
            ["DialogueId"] = 12046427,
            ["GUID"] = "1E282EEE",
            ["NextDialogue"] = 12046428,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282EEE",
            },
        [12046428] = {
            ["Content"] = "你利用我、强迫我，确实使我愤怒。但这并不意味着我愿意看着任何一个人死去。",
            ["ContentFR"] = "Oui, je suis en colère. Vous m’avez {性别:utilisé, contraint. Mais cela ne signifie pas que je sois prêt|utilisée, contrainte. Mais cela ne signifie pas que je sois prête} à regarder quelqu’un mourir.",
            ["DialogueId"] = 12046428,
            ["GUID"] = "1E282F18",
            ["NextDialogue"] = 12046429,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282F18",
            },
        [12046429] = {
            ["Content"] = "我们刚见面时，你问过我，究竟有什么值得用性命去衡量。你明明恐惧着死亡……又为何能如此轻易地献祭自己的生命。",
            ["ContentFR"] = "Lors de notre première rencontre, vous m’avez demandé ce qui méritait qu’on y mesure sa vie. Vous redoutez la mort... alors pourquoi parlez-vous de sacrifier la vôtre avec une telle légèreté ?",
            ["DialogueId"] = 12046429,
            ["GUID"] = "1E282F42",
            ["NextDialogue"] = 12046430,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282F42",
            },
        [12046430] = {
            ["Content"] = "……那只是随口一提，你却当真了。",
            ["ContentFR"] = "... Ce n’était qu’une remarque en l’air. Je ne pensais pas que tu la prendrais au sérieux.",
            ["DialogueId"] = 12046430,
            ["GUID"] = "1E282F6C",
            ["NextDialogue"] = 12046431,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282F6C",
            },
        [12046431] = {
            ["Content"] = "为了达成既定的结局，这一切牺牲都是必须的。你愿或不愿，都别无选择。",
            ["ContentFR"] = "Pour atteindre la fin que j’ai choisie, ce sacrifice est indispensable. Que je le veuille ou non, il n’existe pas d’autre voie.",
            ["DialogueId"] = 12046431,
            ["GUID"] = "1E282F96",
            ["NextDialogue"] = 12046432,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282F96",
            },
        }
  end },
  { MinKey = 12046432, MaxKey = 12048202, Loader = function()
      return {
        [12046432] = {
            ["Content"] = "若是我不死去，失控的太皓、烛阴将使华胥彻底陷入混乱。{nickname}，我只能寄希望于你去完成这最后一举。",
            ["ContentFR"] = "Si je ne meurs pas, Taihao et Zhuyin perdront tout contrôle et plongeront Huaxu dans le chaos. {nickname}, je ne peux confier cet ultime acte qu’à toi.",
            ["DialogueId"] = 12046432,
            ["GUID"] = "1E282FC0",
            ["NextDialogue"] = 12046433,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282FC0",
            },
        [12046433] = {
            ["Content"] = "倘若有任何后果或是骂名，都由我来背负……这样便好。",
            ["ContentFR"] = "Quelles qu’en soient les conséquences, quel que soit l’opprobre... je l’assumerai seule. Ainsi... tout sera en ordre.",
            ["DialogueId"] = 12046433,
            ["GUID"] = "1E282FEA",
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282FEA",
            },
        [12046501] = {
            ["Content"] = "烛阴的气息……是谁任由污秽沾染这神圣之地？",
            ["ContentFR"] = "L’aura de Zhuyin... Qui ose laisser la souillure profaner ce lieu sacré ?",
            ["DialogueId"] = 12046501,
            ["GUID"] = "1E283B12",
            ["NextDialogue"] = 12046502,
            ["RelatedWikiId"] = {
                [1] = 203001,
                [2] = 304003,
                [3] = 303008,
                [4] = 303011,
                [5] = 304004,
                },
            ["SpeakNpcId"] = 240072,
            ["VoiceName"] = "voice/$Locale$/story/1204/120465/1E283B12",
            },
        [12046502] = {
            ["Content"] = "奉香大典的仪式并未开始。止流，你何故现身于此？",
            ["ContentFR"] = "La Cérémonie de l’Encens n’a pas encore commencé. Zhiliu... pour quelle raison te présentes-tu ici ?",
            ["DialogueId"] = 12046502,
            ["GUID"] = "1E283B3C",
            ["NextDialogue"] = 12046503,
            ["SpeakNpcId"] = 240073,
            ["VoiceName"] = "voice/$Locale$/story/1204/120465/1E283B3C",
            },
        [12046503] = {
            ["Content"] = "呵呵……你们何必明知故问呢。",
            ["ContentFR"] = "Héhé... Pourquoi feindre l’ignorance ?",
            ["DialogueId"] = 12046503,
            ["GUID"] = "1E283B66",
            ["NextDialogue"] = 12046504,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120465/1E283B66",
            },
        [12046504] = {
            ["Content"] = "我在这里的原因，你我都心知肚明。我是来终结大风九章的。",
            ["ContentFR"] = "Vous connaissez déjà la réponse. Je suis venue mettre fin aux Neuf Chapitres de Dafeng.",
            ["DialogueId"] = 12046504,
            ["GUID"] = "1E283B90",
            ["NextDialogue"] = 12046505,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120465/1E283B90",
            },
        [12046505] = {
            ["Content"] = "大胆！你清楚自己在做什么吗？！",
            ["ContentFR"] = "Insolente ! As-tu seulement conscience de ce que tu fais ?!",
            ["DialogueId"] = 12046505,
            ["GUID"] = "1E283BBA",
            ["NextDialogue"] = 12046506,
            ["SpeakNpcId"] = 240072,
            ["VoiceName"] = "voice/$Locale$/story/1204/120465/1E283BBA",
            },
        [12046506] = {
            ["Content"] = "止流，吾辈从来对你寄予重望。龙渊上卿的殊荣和力量，可不是随便授于你身的！",
            ["ContentFR"] = "Zhiliu, nous avions placé en toi les plus hautes espérances. Le titre et la puissance de Haut Chancelier de Longyuan ne t’ont pas été confiés à la légère !",
            ["DialogueId"] = 12046506,
            ["GUID"] = "1E283BE4",
            ["NextDialogue"] = 12046507,
            ["SpeakNpcId"] = 240073,
            ["VoiceName"] = "voice/$Locale$/story/1204/120465/1E283BE4",
            },
        [12046507] = {
            ["Content"] = "放心。我既然站在这里，便已经做好了必死的觉悟。",
            ["ContentFR"] = "Si je me tiens ici aujourd’hui, c’est que j’en ai déjà accepté le prix — ma vie.",
            ["DialogueId"] = 12046507,
            ["GUID"] = "1E283C0E",
            ["NextDialogue"] = 12046508,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120465/1E283C0E",
            },
        [12046508] = {
            ["Content"] = "“承九鼎，济苍黎”，此为龙渊上卿应尽之职……虽九死其犹未悔。",
            ["ContentFR"] = "« Porter le poids du monde et sauver le peuple. » Tel est le devoir du Haut Chancelier de Longyuan... Et même au prix de mille morts, je n’en éprouverai nul regret.",
            ["DialogueId"] = 12046508,
            ["GUID"] = "1E283C38",
            ["NextDialogue"] = 12046509,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120465/1E283C38",
            },
        [12046509] = {
            ["Content"] = "你……！",
            ["ContentFR"] = "Toi... !",
            ["DialogueId"] = 12046509,
            ["GUID"] = "1E283C62",
            ["SpeakNpcId"] = 240072,
            ["VoiceName"] = "voice/$Locale$/story/1204/120465/1E283C62",
            },
        [12046601] = {
            ["Content"] = "若太皓陨落，万古秩序将毁于一旦！",
            ["ContentFR"] = "Si Taihao venait à tomber, l’ordre établi depuis les temps immémoriaux s’effondrerait avec lui !",
            ["DialogueId"] = 12046601,
            ["GUID"] = "1E284B7A",
            ["NextDialogue"] = 12046602,
            ["RelatedWikiId"] = {
                [1] = 203001,
                [2] = 304003,
                [3] = 303008,
                [4] = 303011,
                [5] = 304004,
                },
            ["SpeakNpcId"] = 240074,
            ["VoiceName"] = "voice/$Locale$/story/1204/120466/1E284B7A",
            },
        [12046602] = {
            ["Content"] = "止流，你缘何做出如此倒行逆施之举？",
            ["ContentFR"] = "Zhiliu, quelle folie t’a conduite à un tel renversement ?",
            ["DialogueId"] = 12046602,
            ["GUID"] = "1E284BA4",
            ["NextDialogue"] = 12046603,
            ["SpeakNpcId"] = 240074,
            ["VoiceName"] = "voice/$Locale$/story/1204/120466/1E284BA4",
            },
        [12046603] = {
            ["Content"] = "理由吗……",
            ["ContentFR"] = "Une folie... ?",
            ["DialogueId"] = 12046603,
            ["GUID"] = "1E284BCE",
            ["NextDialogue"] = 12046604,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120466/1E284BCE",
            },
        [12046604] = {
            ["Content"] = "现今的华胥，民众习惯了向神明祈求一切。",
            ["ContentFR"] = "Aujourd’hui, le peuple de Huaxu a pris l’habitude de tout remettre aux dieux.",
            ["DialogueId"] = 12046604,
            ["GUID"] = "1E284BF8",
            ["NextDialogue"] = 12046605,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120466/1E284BF8",
            },
        [12046605] = {
            ["Content"] = "他们放下武器，不再以双手守护自己。",
            ["ContentFR"] = "Ils ont déposé les armes. Ils ont cessé de se protéger de leurs propres mains.",
            ["DialogueId"] = 12046605,
            ["GUID"] = "1E284C22",
            ["NextDialogue"] = 12046606,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120466/1E284C22",
            },
        [12046606] = {
            ["Content"] = "他们闭目塞听，只顺从大风九章之音。",
            ["ContentFR"] = "Ils ferment les yeux et les oreilles, n’écoutant plus que la voix des Neuf Chapitres.",
            ["DialogueId"] = 12046606,
            ["GUID"] = "1E284C4C",
            ["NextDialogue"] = 12046607,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120466/1E284C4C",
            },
        [12046607] = {
            ["Content"] = "他们泯灭内心的想法，把善恶托付于天命裁决。",
            ["ContentFR"] = "Ils ont étouffé leur propre jugement, remettant le bien et le mal au verdict du destin.",
            ["DialogueId"] = 12046607,
            ["GUID"] = "1E284C76",
            ["NextDialogue"] = 12046608,
            ["SpeakNpcId"] = 240074,
            ["VoiceName"] = "voice/$Locale$/story/1204/120466/1E284C76",
            },
        [12046608] = {
            ["Content"] = "可神明真的能永远庇护华胥吗？烛阴之灾横生，太皓无力阻止，难道不是昭示着大风九章正在衰弱？",
            ["ContentFR"] = "Mais les dieux peuvent-ils protéger Huaxu éternellement ? Le Fléau de Zhuyin a éclaté, et Taihao fut impuissant à l’arrêter. N’est-ce pas là le signe que les Neuf Chapitres déclinent ?",
            ["DialogueId"] = 12046608,
            ["GUID"] = "1E284CA0",
            ["NextDialogue"] = 12046613,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120466/1E284CA0",
            },
        [12046610] = {
            ["Content"] = "糊涂！凡人一孔之见，岂能独当大局？",
            ["ContentFR"] = "Absurdité ! La vision étroite des mortels saurait-elle soutenir un tel fardeau ?",
            ["DialogueId"] = 12046610,
            ["GUID"] = "1E284CF4",
            ["NextDialogue"] = 12046611,
            ["SpeakNpcId"] = 240074,
            ["VoiceName"] = "voice/$Locale$/story/1204/120466/1E284CF4",
            },
        [12046611] = {
            ["Content"] = "呵呵……受缚于陶俑之中，你怎知你不是自己口中的凡人呢？",
            ["ContentFR"] = "Héhé... Enfermé dans cette enveloppe d’argile, comment sais-tu que tu n’es pas toi-même l’un de ces « mortels » que tu méprises ?",
            ["DialogueId"] = 12046611,
            ["GUID"] = "1E284D1E",
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120466/1E284D1E",
            },
        [12046613] = {
            ["Content"] = "看，大陆的另一端，帝国与传颂会的战争已经绵延千年。当大风九章彻底衰竭，神明不再能庇护这片土地，华胥人如何才能在纷争的涡旋中独善其身？",
            ["ContentFR"] = "Regardez l’autre extrémité du continent : l’Empire et l’Église Élyséenne se livrent une guerre qui dure depuis mille ans. Lorsque les Neuf Chapitres s’éteindront, lorsque les dieux ne pourront plus abriter cette terre, comment les habitants de Huaxu résisteront-ils à la tourmente ?",
            ["DialogueId"] = 12046613,
            ["GUID"] = "12046613.0",
            ["NextDialogue"] = 12046614,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120466/12046613",
            },
        [12046614] = {
            ["Content"] = "若是有一天，大风九章力量耗尽，人们应当如何用自己的双眼重新丈量世界？又当如何生存，如何抗争，如何明断善恶，如何重塑秩序？",
            ["ContentFR"] = "Si un jour leur pouvoir venait à se tarir, comment les hommes mesureront-ils de nouveau le monde de leurs propres yeux ? Comment vivront-ils ? Comment lutteront-ils ? Comment discerneront-ils le juste du faux ? Comment refonderont-ils l’ordre ?",
            ["DialogueId"] = 12046614,
            ["GUID"] = "12046614.0",
            ["NextDialogue"] = 12046610,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120466/12046614",
            },
        [12046701] = {
            ["Content"] = "止流，这样做的后果，你可想好了？你一个人担得起吗？",
            ["ContentFR"] = "Zhiliu... as-tu réellement mesuré les conséquences ? Peux-tu les assumer seule ?",
            ["DialogueId"] = 12046701,
            ["GUID"] = "1E285BE2",
            ["NextDialogue"] = 12046702,
            ["RelatedWikiId"] = {
                [1] = 203001,
                [2] = 304003,
                [3] = 303008,
                [4] = 303011,
                [5] = 304004,
                },
            ["SpeakNpcId"] = 240075,
            ["VoiceName"] = "voice/$Locale$/story/1204/120467/1E285BE2",
            },
        [12046702] = {
            ["Content"] = "自然是担得起。",
            ["ContentFR"] = "Oui. Je le peux.",
            ["DialogueId"] = 12046702,
            ["GUID"] = "1E285C0C",
            ["NextDialogue"] = 12046703,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120467/1E285C0C",
            },
        [12046703] = {
            ["Content"] = "竟自私至此！",
            ["ContentFR"] = "Quelle arrogance !",
            ["DialogueId"] = 12046703,
            ["GUID"] = "1E285C36",
            ["NextDialogue"] = 12046704,
            ["SpeakNpcId"] = 240075,
            ["VoiceName"] = "voice/$Locale$/story/1204/120467/1E285C36",
            },
        [12046704] = {
            ["Content"] = "你是可以闹完这出，两眼一闭，不管身后事了。但那些失去了大风九章庇护的民众呢？他们该如何自处？",
            ["ContentFR"] = "Tu pourrais mener ton drame à son terme, puis fermer les yeux et abandonner le monde derrière toi. Mais lorsque la protection des Neuf Chapitres aura disparu, que deviendront les gens ?",
            ["DialogueId"] = 12046704,
            ["GUID"] = "1E285C60",
            ["NextDialogue"] = 12046708,
            ["SpeakNpcId"] = 240075,
            ["VoiceName"] = "voice/$Locale$/story/1204/120467/1E285C60",
            },
        [12046705] = {
            ["Content"] = "人性没有你想的那么脆弱。当不再仰赖神明，人类便会重新学习如何用自己的双手应对秽蚀、战争、伤害、和罪恶。",
            ["ContentFR"] = "L’humanité n’est pas aussi fragile que vous le croyez. Privée des dieux, elle réapprendra à affronter la Dégradation — et avec elle, la guerre, la souffrance et le crime.",
            ["DialogueId"] = 12046705,
            ["GUID"] = "1E285C8A",
            ["NextDialogue"] = 12046708,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120467/1E285C8A",
            },
        [12046706] = {
            ["Content"] = "在这个过程中，或许会有阵痛，或许会出现牺牲，但这是剜骨疗伤所必须经历的一环。",
            ["ContentFR"] = "Il y aura de la douleur. Il y aura des sacrifices. Mais c’est le prix d’une guérison radicale — comme lorsqu’on incise jusqu’à l’os pour extirper le mal.",
            ["DialogueId"] = 12046706,
            ["GUID"] = "1E285CB4",
            ["NextDialogue"] = 12046707,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120467/1E285CB4",
            },
        [12046707] = {
            ["Content"] = "只有在病灶清除后，生命才能找寻新的出路。",
            ["ContentFR"] = "Ce n’est qu’après avoir ôté la gangrène que la vie peut trouver une voie nouvelle.",
            ["DialogueId"] = 12046707,
            ["GUID"] = "1E285CDE",
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120467/1E285CDE",
            },
        [12046708] = {
            ["Content"] = "那自愿悖离于大风九章之外的飘零人，不照样依靠机括术和传承下来的武艺庇护了自己吗？",
            ["ContentFR"] = "Les Vagabonds qui ont choisi de vivre hors des Neuf Chapitres n’ont-ils pas su se protéger par leurs propres arts et leurs traditions martiales ?",
            ["DialogueId"] = 12046708,
            ["GUID"] = "12046708.0",
            ["NextDialogue"] = 12046706,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120467/12046708",
            },
        [12046801] = {
            ["Content"] = "令人赞叹的谋划布局……止流，千古以来，能给中枢真正带来威胁的，你是第一人。",
            ["ContentFR"] = "Une stratégie admirable... Zhiliu, depuis les âges immémoriaux, tu es la première à menacer véritablement le Cœur.",
            ["DialogueId"] = 12046801,
            ["GUID"] = "1E286C4A",
            ["NextDialogue"] = 12046802,
            ["RelatedWikiId"] = {
                [1] = 203001,
                [2] = 304003,
                [3] = 303008,
                [4] = 303011,
                [5] = 304004,
                },
            ["SpeakNpcId"] = 240071,
            ["VoiceName"] = "voice/$Locale$/story/1204/120468/1E286C4A",
            },
        [12046802] = {
            ["Content"] = "当初选了你作为龙渊上卿，便是看中了你的才智，却未想到会带来这样的结局。",
            ["ContentFR"] = "Nous t’avons choisie comme Haut Chancelier pour ton intelligence. Je n’aurais jamais imaginé que cela nous mènerait ici.",
            ["DialogueId"] = 12046802,
            ["GUID"] = "1E286C74",
            ["NextDialogue"] = 12046803,
            ["SpeakNpcId"] = 240071,
            ["VoiceName"] = "voice/$Locale$/story/1204/120468/1E286C74",
            },
        [12046803] = {
            ["Content"] = "呵呵……未有机会感谢你对我的提拔，现在道谢也不算晚。",
            ["ContentFR"] = "Héhé... Je n’ai jamais eu l’occasion de vous remercier pour la confiance que vous m’avez accordée. Il n’est pas trop tard.",
            ["DialogueId"] = 12046803,
            ["GUID"] = "1E286C9E",
            ["NextDialogue"] = 12046804,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120468/1E286C9E",
            },
        [12046804] = {
            ["Content"] = "止流，你我都是聪明人。我不像那些蠢物一样和你大发雷霆，谈论那虚无缥缈的道德义务。",
            ["ContentFR"] = "Toi et moi sommes des esprits lucides. Je ne perdrai pas mon temps à t’accabler de grands discours moraux.",
            ["DialogueId"] = 12046804,
            ["GUID"] = "1E286CC8",
            ["NextDialogue"] = 12046805,
            ["SpeakNpcId"] = 240071,
            ["VoiceName"] = "voice/$Locale$/story/1204/120468/1E286CC8",
            },
        [12046805] = {
            ["Content"] = "道德只是对于庸人的束缚。而所谓龙神，不过是太虚凝结成的造物，幕后意志的代行者罢了。",
            ["ContentFR"] = "La morale n’est qu’une chaîne pour les médiocres. Quant aux Seigneurs Dragons... de simples créations issues du Vide, des instruments d’une volonté plus vaste.",
            ["DialogueId"] = 12046805,
            ["GUID"] = "1E286CF2",
            ["NextDialogue"] = 12046806,
            ["SpeakNpcId"] = 240071,
            ["VoiceName"] = "voice/$Locale$/story/1204/120468/1E286CF2",
            },
        [12046806] = {
            ["Content"] = "真正掌控大风九章的，是<W>吾辈</>——千年来列代祭献身躯，汇入中枢的时代精英所构成的共同意志。",
            ["ContentFR"] = "Ceux qui dirigent réellement les Neuf Chapitres, c’est <W>nous</> — les élites de chaque époque, qui ont offert leurs corps en sacrifice pour fusionner avec le Cœur.",
            ["DialogueId"] = 12046806,
            ["GUID"] = "1E286D1C",
            ["NextDialogue"] = 12046807,
            ["SpeakNpcId"] = 240071,
            ["VoiceName"] = "voice/$Locale$/story/1204/120468/1E286D1C",
            },
        [12046807] = {
            ["Content"] = "止流，以吾辈的意志，我向你发来真正的邀请。",
            ["ContentFR"] = "Zhiliu... au nom de cette volonté, je t’adresse une véritable invitation.",
            ["DialogueId"] = 12046807,
            ["GUID"] = "1E286D46",
            ["NextDialogue"] = 12046808,
            ["SpeakNpcId"] = 240071,
            ["VoiceName"] = "voice/$Locale$/story/1204/120468/1E286D46",
            },
        [12046808] = {
            ["Content"] = "你已经证明了自己的决心和才华。我可将你迎入中枢，加入<W>吾辈</>，你便能够以你的意志重塑华胥。",
            ["ContentFR"] = "Tu as prouvé ton génie et ta détermination. Je peux t’accueillir au sein du Cœur, te faire entrer parmi <W>nous</> — et te permettre de remodeler Huaxu selon ta volonté.",
            ["DialogueId"] = 12046808,
            ["GUID"] = "1E286D70",
            ["NextDialogue"] = 12046809,
            ["SpeakNpcId"] = 240071,
            ["VoiceName"] = "voice/$Locale$/story/1204/120468/1E286D70",
            },
        [12046809] = {
            ["Content"] = "如何，这份邀请，能让你满意吗？",
            ["ContentFR"] = "Alors ? Cette proposition te satisfait-elle ?",
            ["DialogueId"] = 12046809,
            ["GUID"] = "1E286D9A",
            ["NextDialogue"] = 12046810,
            ["SpeakNpcId"] = 240071,
            ["VoiceName"] = "voice/$Locale$/story/1204/120468/1E286D9A",
            },
        [12046810] = {
            ["Content"] = "你倒是比先前那些人更懂得谈判。不过……还是不必了。",
            ["ContentFR"] = "Vous négociez mieux que les précédents... Mais ce sera sans moi.",
            ["DialogueId"] = 12046810,
            ["GUID"] = "1E286DC4",
            ["NextDialogue"] = 12046811,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120468/1E286DC4",
            },
        [12046811] = {
            ["Content"] = "为何？无论你有怎样的诉求，引领民众也好，或是革新华胥也罢，这万人之巅的位置都能帮你实现。",
            ["ContentFR"] = "Pourquoi ? Tout ce que tu désires — guider le peuple, réformer Huaxu — ce pouvoir te le donnerait.",
            ["DialogueId"] = 12046811,
            ["GUID"] = "1E286DEE",
            ["NextDialogue"] = 12046812,
            ["SpeakNpcId"] = 240071,
            ["VoiceName"] = "voice/$Locale$/story/1204/120468/1E286DEE",
            },
        [12046812] = {
            ["Content"] = "你可能搞错了一点，我对成神从未有过欲求。",
            ["ContentFR"] = "Vous vous méprenez sur un point. Je n’ai jamais désiré m’élever au rang de dieu.",
            ["DialogueId"] = 12046812,
            ["GUID"] = "1E286E18",
            ["NextDialogue"] = 12046813,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120468/1E286E18",
            },
        [12046813] = {
            ["Content"] = "华胥，不应当再有新的神明了。",
            ["ContentFR"] = "Huaxu n’a plus besoin d’aucun dieu.",
            ["DialogueId"] = 12046813,
            ["GUID"] = "1E286E42",
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120468/1E286E42",
            },
        [12046901] = {
            ["Content"] = "我知道止流的完整计划了！",
            ["ContentFR"] = "Je connais désormais l’intégralité du plan de Zhiliu !",
            ["DialogueId"] = 12046901,
            ["GUID"] = "1E287CB2",
            ["NextDialogue"] = 12046902,
            ["RelatedWikiId"] = {
                [1] = 203001,
                [2] = 304003,
                [3] = 303008,
                [4] = 303011,
                [5] = 304004,
                },
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120469/1E287CB2",
            },
        [12046902] = {
            ["Content"] = "小仆从，这、这和我们头上突然出现的两条巨龙有关系吗？",
            ["ContentFR"] = "P-Petit larbin... dis-moi que ça n’a rien à voir avec les deux dragons géants au-dessus de nos têtes ?",
            ["DialogueId"] = 12046902,
            ["GUID"] = "1E287CDC",
            ["NextDialogue"] = 12046903,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120469/1E287CDC",
            },
        [12046903] = {
            ["Content"] = "现在阻止她还来得及！事情是这样的……",
            ["ContentFR"] = "Il est encore temps de l’arrêter ! Écoutez...",
            ["DialogueId"] = 12046903,
            ["GUID"] = "1E287D06",
            ["NextDialogue"] = 12046905,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120469/1E287D06",
            },
        [12046904] = {
            ["Content"] = "听苏乙说过一些。",
            ["ContentFR"] = "<I>J’en ai entendu parler par Su Yi.</>",
            ["DialogueId"] = 12046904,
            ["GUID"] = "1E287D30",
            ["NextDialogue"] = 12046912,
            },
        [12046905] = {
            ["Content"] = "{nickname}，你的意思莫非是……大风九章要终结了？！",
            ["ContentFR"] = "{nickname}... es-tu en train de dire que les Neuf Chapitres de Dafeng sont sur le point de s’effondrer ?!",
            ["DialogueId"] = 12046905,
            ["GUID"] = "1E287D5A",
            ["NextDialogue"] = 12046906,
            ["SpeakNpcId"] = 240002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120469/1E287D5A",
            },
        [12046906] = {
            ["Content"] = "惊才绝艳的想法，铤而走险的性格，苛责己身的执行力……这么多年了，她还是一如既往。",
            ["ContentFR"] = "Un esprit éclatant. Une audace qui frôle la folie. Une exigence envers elle-même plus sévère que n’importe quel ennemi... Toutes ces années, elle n’a pas changé.",
            ["DialogueId"] = 12046906,
            ["GUID"] = "1E287D84",
            ["NextDialogue"] = 12046907,
            ["SpeakNpcId"] = 240040,
            ["VoiceName"] = "voice/$Locale$/story/1204/120469/1E287D84",
            },
        [12046907] = {
            ["Content"] = "喂，现在可不是感慨的时候了，还有办法阻止她吗？！",
            ["ContentFR"] = "Hé ! Ce n’est pas le moment d’admirer son génie ! Il reste un moyen de l’arrêter ou pas ?!",
            ["DialogueId"] = 12046907,
            ["GUID"] = "1E287DAE",
            ["NextDialogue"] = 12046908,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120469/1E287DAE",
            },
        [12046908] = {
            ["Content"] = "若烛阴尚未封印，或许还有办法，但现在怕是已无计可施了……",
            ["ContentFR"] = "Si Zhuyin n’avait pas été scellé... peut-être. Mais à présent... je crains que la voie ne soit close.",
            ["DialogueId"] = 12046908,
            ["GUID"] = "1E287DD8",
            ["NextDialogue"] = 12046909,
            ["SpeakNpcId"] = 240040,
            ["VoiceName"] = "voice/$Locale$/story/1204/120469/1E287DD8",
            },
        [12046909] = {
            ["Content"] = "就算是最渺茫的希望也好，请告诉我！",
            ["ContentFR"] = "Même la plus infime possibilité suffit. Dites-le-moi !",
            ["DialogueId"] = 12046909,
            ["GUID"] = "1E287E02",
            ["NextDialogue"] = 12046910,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120469/1E287E02",
            },
        [12046910] = {
            ["Content"] = "这便要从大风九章的由来说起了。你对其中内情有多少了解？",
            ["ContentFR"] = "Alors il faut revenir à l’origine même des Neuf Chapitres. Que sais-tu réellement de leur fonctionnement ?",
            ["DialogueId"] = 12046910,
            ["GUID"] = "1E287E2C",
            ["NextOptions"] = {
                [1] = 12046904,
                [2] = 12046911,
                },
            ["SpeakNpcId"] = 240040,
            ["VoiceName"] = "voice/$Locale$/story/1204/120469/1E287E2C",
            },
        [12046911] = {
            ["Content"] = "不太了解。",
            ["ContentFR"] = "<I>Je n’en sais presque rien.</>",
            ["DialogueId"] = 12046911,
            ["GUID"] = "1E287E56",
            ["NextDialogue"] = 12046912,
            },
        [12046912] = {
            ["Content"] = "大风九章今日虽已被神化，究其本质，却是人为固定在这片土地上的巨型魔法仪式。",
            ["ContentFR"] = "Aujourd’hui, les Neuf Chapitres sont entourés d’une aura divine. Pourtant, à l’origine, il ne s’agissait que d’un immense rite magique ancré dans cette terre par des mains humaines.",
            ["DialogueId"] = 12046912,
            ["GUID"] = "1E287E80",
            ["NextDialogue"] = 12046913,
            ["SpeakNpcId"] = 240040,
            ["VoiceName"] = "voice/$Locale$/story/1204/120469/1E287E80",
            },
        [12046913] = {
            ["Content"] = "既是人为，在创立之初，便设置了规则和约定。狴犴，应天尉，乃至于太皓、烛阴，都是遵从着这规则而运转的。",
            ["ContentFR"] = "Puisqu’ils furent créés par l’homme, ils furent conçus avec des règles et des pactes. Les Bi’an, les Magistrats de Yingtian, Taihao, Zhuyin — tous agissent dans le cadre de ces lois.",
            ["DialogueId"] = 12046913,
            ["GUID"] = "1E287EAA",
            ["NextDialogue"] = 12046914,
            ["SpeakNpcId"] = 240040,
            ["VoiceName"] = "voice/$Locale$/story/1204/120469/1E287EAA",
            },
        [12046914] = {
            ["Content"] = "悬衡派的创立者<H>飏</>，以及机枢派的创立者<H>矩</>，他们二人献祭自身，将思想融于大风九章中枢，成为了太皓和烛阴最早的意志。",
            ["ContentFR"] = "La fondatrice de Xuanheng, <H>Yang</>, et le fondateur de Jishu, <H>Ju</>, sacrifièrent leurs propres vies. Leurs pensées furent fondues dans le Cœur des Neuf Chapitres. Ils devinrent les premières volontés de Taihao et de Zhuyin.",
            ["DialogueId"] = 12046914,
            ["GUID"] = "1E287ED4",
            ["NextDialogue"] = 12046915,
            ["SpeakNpcId"] = 240040,
            ["VoiceName"] = "voice/$Locale$/story/1204/120469/1E287ED4",
            },
        [12046915] = {
            ["Content"] = "上古时期，龙神并非高高在上，与凡人泾渭分明。彼时，凡人会于执律阁端，和龙神论辩律法，共商裁决。",
            ["ContentFR"] = "Aux temps anciens, les Seigneurs Dragons ne régnaient pas du haut des cieux. Les mortels pouvaient gravir le Pavillon de l’Arbitrage et débattre des lois avec eux.",
            ["DialogueId"] = 12046915,
            ["GUID"] = "1E287EFE",
            ["NextDialogue"] = 12046916,
            ["SpeakNpcId"] = 240040,
            ["VoiceName"] = "voice/$Locale$/story/1204/120469/1E287EFE",
            },
        [12046916] = {
            ["Content"] = "为预防仪式偏离初衷，日久生患，飏和矩设计了均天玉律这一信物。分为两份，由悬衡、机枢两派各执其一。",
            ["ContentFR"] = "Afin d’éviter que le rite ne dérive avec les siècles, Yang et Ju forgèrent un gage : le Jade de l’Équilibre. Il fut scindé en deux moitiés, confiées respectivement aux deux sectes.",
            ["DialogueId"] = 12046916,
            ["GUID"] = "1E287F28",
            ["NextDialogue"] = 12046917,
            ["RelatedWikiId"] = {
                [1] = 407015,
                },
            ["SpeakNpcId"] = 240040,
            ["VoiceName"] = "voice/$Locale$/story/1204/120469/1E287F28",
            },
        [12046917] = {
            ["Content"] = "于太虚陵之巅，将分开的均天玉律合二为一，即可踏入大风九章中枢，让这一仪式重归原点。",
            ["ContentFR"] = "Au sommet du Mausolée de Taixu, si les deux fragments sont réunis, le Cœur des Neuf Chapitres s’ouvre — et le rite peut être ramené à son état originel.",
            ["DialogueId"] = 12046917,
            ["GUID"] = "1E287F52",
            ["NextDialogue"] = 12046918,
            ["SpeakNpcId"] = 240040,
            ["VoiceName"] = "voice/$Locale$/story/1204/120469/1E287F52",
            },
        [12046918] = {
            ["Content"] = "重归原点？那样的话，止流进行的祭献仪式，是不是可以中断了？！",
            ["ContentFR"] = "Revenir à son état originel... Cela signifierait que le sacrifice de Zhiliu pourrait être interrompu ?!",
            ["DialogueId"] = 12046918,
            ["GUID"] = "1E287F7C",
            ["NextDialogue"] = 12046919,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120469/1E287F7C",
            },
        [12046919] = {
            ["Content"] = "不仅如此。",
            ["ContentFR"] = "Bien plus encore.",
            ["DialogueId"] = 12046919,
            ["GUID"] = "1E287FA6",
            ["NextDialogue"] = 12046920,
            ["SpeakNpcId"] = 240040,
            ["VoiceName"] = "voice/$Locale$/story/1204/120469/1E287FA6",
            },
        [12046920] = {
            ["Content"] = "如今大风九章僵化，究其原因，全为黍离之战后悬衡派一意孤行，封印烛阴所致。",
            ["ContentFR"] = "Les Neuf Chapitres se sont rigidifiés après la Bataille de Shuli, lorsque la Secte Xuanheng scella Zhuyin de son propre chef.",
            ["DialogueId"] = 12046920,
            ["GUID"] = "1E287FD0",
            ["NextDialogue"] = 12046921,
            ["SpeakNpcId"] = 240040,
            ["VoiceName"] = "voice/$Locale$/story/1204/120469/1E287FD0",
            },
        [12046921] = {
            ["Content"] = "“心”、“理”的平衡之道被打破，太皓逐渐变为绝对秩序的代名词，只问法条，不再听取子民的心声。",
            ["ContentFR"] = "L’équilibre entre « cœur » et « principe » fut brisé. Taihao devint l’incarnation d’un ordre absolu, ne répondant plus qu’aux articles de loi, sourd à la voix du peuple.",
            ["DialogueId"] = 12046921,
            ["GUID"] = "1E287FFA",
            ["NextDialogue"] = 12046922,
            ["SpeakNpcId"] = 240040,
            ["VoiceName"] = "voice/$Locale$/story/1204/120469/1E287FFA",
            },
        [12046922] = {
            ["Content"] = "而失去理性的烛阴则不断被心中愤怒驱使，为祸一方，使得烛阴之灾周而复返。",
            ["ContentFR"] = "Zhuyin, privé de raison, fut consumé par la colère. D’où le retour cyclique du Fléau de Zhuyin.",
            ["DialogueId"] = 12046922,
            ["GUID"] = "1E288024",
            ["NextDialogue"] = 12046923,
            ["SpeakNpcId"] = 240040,
            ["VoiceName"] = "voice/$Locale$/story/1204/120469/1E288024",
            },
        [12046923] = {
            ["Content"] = "若是一切重归原点，这僵化的现状，或许也能焕发新机。",
            ["ContentFR"] = "Si tout revenait à l’origine, cet état figé pourrait peut-être renaître autrement.",
            ["DialogueId"] = 12046923,
            ["GUID"] = "1E28804E",
            ["NextDialogue"] = 12046924,
            ["SpeakNpcId"] = 240040,
            ["VoiceName"] = "voice/$Locale$/story/1204/120469/1E28804E",
            },
        [12046924] = {
            ["Content"] = "然黍离一役中，机枢派持有的那份均天玉律下落不明，如今已是无迹可寻，这唯一的线索也就此断绝。",
            ["ContentFR"] = "Mais lors de la Bataille de Shuli, la moitié du Jade de l’Équilibre détenue par Jishu disparut. Elle est aujourd’hui introuvable.",
            ["DialogueId"] = 12046924,
            ["GUID"] = "1E288078",
            ["NextDialogue"] = 12046925,
            ["SpeakNpcId"] = 240040,
            ["VoiceName"] = "voice/$Locale$/story/1204/120469/1E288078",
            },
        [12046925] = {
            ["Content"] = "双份合二为一……",
            ["ContentFR"] = "Deux moitiés...",
            ["DialogueId"] = 12046925,
            ["GUID"] = "1E2880A2",
            ["NextDialogue"] = 12046926,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120469/1E2880A2",
            },
        [12046926] = {
            ["Content"] = "这位前辈，你说的那个均天玉律，是什么样子的？难不成，长这样？",
            ["ContentFR"] = "Maître Jingyuan... à quoi ressemble ce Jade de l’Équilibre ? Serait-ce... ceci ?",
            ["DialogueId"] = 12046926,
            ["GUID"] = "1E2880CC",
            ["NextDialogue"] = 12046927,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120469/1E2880CC",
            },
        [12046927] = {
            ["Content"] = "……你们，竟寻得了此物。",
            ["ContentFR"] = "... Vous l’avez retrouvé.",
            ["DialogueId"] = 12046927,
            ["GUID"] = "1E2880F6",
            ["NextDialogue"] = 12046928,
            ["SpeakNpcId"] = 240040,
            ["VoiceName"] = "voice/$Locale$/story/1204/120469/1E2880F6",
            },
        [12046928] = {
            ["Content"] = "晨起我算得一卦，谓“休复吉”。然复从何来？原来竟应在你们身上。",
            ["ContentFR"] = "Ce matin, j’ai tiré un présage : « Le retour apporte fortune. » Je me demandais d’où viendrait ce retour... Il reposait entre vos mains.",
            ["DialogueId"] = 12046928,
            ["GUID"] = "1E288120",
            ["NextDialogue"] = 12046929,
            ["SpeakNpcId"] = 240040,
            ["VoiceName"] = "voice/$Locale$/story/1204/120469/1E288120",
            },
        [12046929] = {
            ["Content"] = "有孚惠心者，非求而得，乃天授也……这局，合该由你来破。",
            ["ContentFR"] = "Un cœur sincère ne reçoit pas ce don en le cherchant, il lui est accordé par le Ciel... Cette impasse — c’est à toi de la briser.",
            ["DialogueId"] = 12046929,
            ["GUID"] = "1E28814A",
            ["NextDialogue"] = 12046930,
            ["SpeakNpcId"] = 240040,
            ["VoiceName"] = "voice/$Locale$/story/1204/120469/1E28814A",
            },
        [12046930] = {
            ["Content"] = "抛开听不懂的部分……总而言之，拿着这块免死券，冲上那个什么陵墓，就有机会中断止流的计划，是吗？",
            ["ContentFR"] = "Bon, si je résume sans les envolées mystiques... On prend ce truc, on grimpe au Mausolée, et on peut interrompre le plan de Zhiliu. C’est bien ça ?",
            ["DialogueId"] = 12046930,
            ["GUID"] = "1E288174",
            ["NextDialogue"] = 12046931,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120469/1E288174",
            },
        [12046931] = {
            ["Content"] = "吼——",
            ["ContentFR"] = "Rooooaaar— !",
            ["DialogueId"] = 12046931,
            ["GUID"] = "1E28819E",
            ["NextDialogue"] = 12046932,
            ["SpeakNpcId"] = 0,
            ["VoiceName"] = "voice/$Locale$/story/1204/120469/1E28819E",
            },
        [12046932] = {
            ["Content"] = "刻不容缓，{nickname}，我们走！",
            ["ContentFR"] = "On n’a plus une seconde ! {nickname}, on y va !",
            ["DialogueId"] = 12046932,
            ["GUID"] = "1E2881C8",
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120469/1E2881C8",
            },
        [12047001] = {
            ["Content"] = "来人——救命啊！",
            ["ContentFR"] = "À l’aide— !",
            ["DialogueId"] = 12047001,
            ["GUID"] = "1E288D1A",
            ["NextDialogue"] = 12047002,
            ["RelatedWikiId"] = {
                [1] = 408010,
                [2] = 304003,
                [3] = 303009,
                [4] = 303010,
                [5] = 303008,
                [6] = 303011,
                },
            ["SpeakNpcId"] = 240041,
            ["VoiceName"] = "voice/$Locale$/story/1204/120470/1E288D1A",
            },
        [12047002] = {
            ["Content"] = "白龙神君护佑，白龙神君护佑——",
            ["ContentFR"] = "Que le Seigneur Dragon d’Argent nous protège... que le Seigneur Dragon d’Argent nous protège—",
            ["DialogueId"] = 12047002,
            ["GUID"] = "1E288D44",
            ["NextDialogue"] = 12047003,
            ["SpeakNpcId"] = 240042,
            ["VoiceName"] = "voice/$Locale$/story/1204/120470/1E288D44",
            },
        [12047003] = {
            ["Content"] = "阿爷，囡囡没有不乖，为什么白色的大狼要来吃掉囡囡？",
            ["ContentFR"] = "Grand-père... Nannan a été sage... pourquoi le grand loup blanc veut-il manger Nannan ?",
            ["DialogueId"] = 12047003,
            ["GUID"] = "1E288D6E",
            ["NextDialogue"] = 12047004,
            ["SpeakNpcId"] = 240043,
            ["VoiceName"] = "voice/$Locale$/story/1204/120470/1E288D6E",
            },
        [12047004] = {
            ["Content"] = "囡囡，这是上天降下来的考验，是白龙神君给我们的考验！明白吗？你一定要心诚，才能度过此劫……",
            ["ContentFR"] = "Nannan, c’est une épreuve envoyée par le Ciel... une épreuve que nous impose le Seigneur Dragon d’Argent ! Tu comprends ? Ce n’est qu’avec un cœur sincère que nous pourrons traverser cette calamité...",
            ["DialogueId"] = 12047004,
            ["GUID"] = "1E288D98",
            ["NextDialogue"] = 12047005,
            ["SpeakNpcId"] = 240042,
            ["VoiceName"] = "voice/$Locale$/story/1204/120470/1E288D98",
            },
        [12047005] = {
            ["Content"] = "快躲开，爹，囡囡——",
            ["ContentFR"] = "Écartez-vous, père ! Nannan— !",
            ["DialogueId"] = 12047005,
            ["GUID"] = "1E288DC2",
            ["NextDialogue"] = 12047006,
            ["SpeakNpcId"] = 240044,
            ["VoiceName"] = "voice/$Locale$/story/1204/120470/1E288DC2",
            },
        [12047006] = {
            ["Content"] = "城里都乱成这样了，狴犴和玄色狴犴一同转过身来攻击大家了！爹，你怎么还有空在这里祈祷？！",
            ["ContentFR"] = "La ville est déjà plongée dans le chaos ! Les Bi’an et les Bi’an obscurs se sont retournés contre nous ! Père, comment peux-tu encore prier à un moment pareil ?!",
            ["DialogueId"] = 12047006,
            ["GUID"] = "1E288DEC",
            ["NextDialogue"] = 12047007,
            ["SpeakNpcId"] = 240044,
            ["VoiceName"] = "voice/$Locale$/story/1204/120470/1E288DEC",
            },
        [12047007] = {
            ["Content"] = "没人能保护我们了！赶紧带着囡囡快逃啊！",
            ["ContentFR"] = "Plus personne ne peut nous protéger ! Prends Nannan et fuis !",
            ["DialogueId"] = 12047007,
            ["GUID"] = "1E288E16",
            ["NextDialogue"] = 12047008,
            ["SpeakNpcId"] = 240044,
            ["VoiceName"] = "voice/$Locale$/story/1204/120470/1E288E16",
            },
        [12047008] = {
            ["Content"] = "住口！休要对狴犴不敬！",
            ["ContentFR"] = "Silence ! N’insulte pas les Bi’an !",
            ["DialogueId"] = 12047008,
            ["GUID"] = "1E288E40",
            ["NextDialogue"] = 12047009,
            ["SpeakNpcId"] = 240042,
            ["VoiceName"] = "voice/$Locale$/story/1204/120470/1E288E40",
            },
        [12047009] = {
            ["Content"] = "白龙神君谅解小女无心之言……",
            ["ContentFR"] = "Seigneur Dragon d’Argent, pardonnez les paroles irréfléchies de ma fille...",
            ["DialogueId"] = 12047009,
            ["GUID"] = "1E288E6A",
            ["NextDialogue"] = 12047010,
            ["SpeakNpcId"] = 240042,
            ["VoiceName"] = "voice/$Locale$/story/1204/120470/1E288E6A",
            },
        [12047010] = {
            ["Content"] = "吼——",
            ["ContentFR"] = "Rooooaaar— !",
            ["DialogueId"] = 12047010,
            ["GUID"] = "1E288E94",
            ["NextDialogue"] = 12047011,
            ["SpeakNpcId"] = 240045,
            ["VoiceName"] = "voice/$Locale$/story/1204/120470/1E288E94",
            },
        [12047011] = {
            ["Content"] = "呀！！",
            ["ContentFR"] = "Aaah— !!",
            ["DialogueId"] = 12047011,
            ["GUID"] = "1E288EBE",
            ["NextDialogue"] = 12047012,
            ["SpeakNpcId"] = 240043,
            ["VoiceName"] = "voice/$Locale$/story/1204/120470/1E288EBE",
            },
        [12047012] = {
            ["Content"] = "闪开——",
            ["ContentFR"] = "Écartez-vous— !",
            ["DialogueId"] = 12047012,
            ["GUID"] = "1E288EE8",
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120470/1E288EE8",
            },
        [12047101] = {
            ["Content"] = "小妹妹，你还好吗，有没有伤到哪里？",
            ["ContentFR"] = "Petite, tout va bien ? Tu n’es pas blessée ?",
            ["DialogueId"] = 12047101,
            ["GUID"] = "1E289D82",
            ["NextDialogue"] = 12047102,
            ["RelatedWikiId"] = {
                [1] = 408010,
                [2] = 304003,
                [3] = 303009,
                [4] = 303010,
                [5] = 303008,
                [6] = 303011,
                },
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120471/1E289D82",
            },
        [12047102] = {
            ["Content"] = "谢谢姐姐，囡囡没事！",
            ["ContentFR"] = "Merci ! Nannan va bien !",
            ["DialogueId"] = 12047102,
            ["GUID"] = "1E289DAC",
            ["NextDialogue"] = 12047103,
            ["SpeakNpcId"] = 240043,
            ["VoiceName"] = "voice/$Locale$/story/1204/120471/1E289DAC",
            },
        [12047103] = {
            ["Content"] = "囡囡——太好了，幸好你没出事……",
            ["ContentFR"] = "Nannan... ! Merci... tu n’as rien...",
            ["DialogueId"] = 12047103,
            ["GUID"] = "1E289DD6",
            ["NextDialogue"] = 12047104,
            ["SpeakNpcId"] = 240044,
            ["VoiceName"] = "voice/$Locale$/story/1204/120471/1E289DD6",
            },
        [12047104] = {
            ["Content"] = "城中竟然已经是这副乱象了……幸好我们赶来及时。",
            ["ContentFR"] = "Je ne pensais pas que la ville serait déjà dans un tel état... Heureusement que nous sommes arrivés à temps.",
            ["DialogueId"] = 12047104,
            ["GUID"] = "1E289E00",
            ["NextDialogue"] = 12047105,
            ["SpeakNpcId"] = 240035,
            ["VoiceName"] = "voice/$Locale$/story/1204/120471/1E289E00",
            },
        [12047105] = {
            ["Content"] = "大姐姐，你是上天派来救我们的使者吗？",
            ["ContentFR"] = "Mademoiselle... est-ce que le Ciel vous a envoyée pour nous sauver ?",
            ["DialogueId"] = 12047105,
            ["GUID"] = "1E289E2A",
            ["NextDialogue"] = 12047106,
            ["SpeakNpcId"] = 240043,
            ["VoiceName"] = "voice/$Locale$/story/1204/120471/1E289E2A",
            },
        [12047106] = {
            ["Content"] = "上天？你误会啦，我们是……",
            ["ContentFR"] = "Le Ciel ? Tu te trompes, nous sommes...",
            ["DialogueId"] = 12047106,
            ["GUID"] = "1E289E54",
            ["NextDialogue"] = 12047107,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120471/1E289E54",
            },
        [12047107] = {
            ["Content"] = "……快离开她！我认出来了，这些人是飘零人！沾上他们不会有什么好下场的！",
            ["ContentFR"] = "... Éloignez-vous d’elle ! Je vous reconnais — vous êtes des Vagabonds ! Rien de bon ne sort de vos fréquentations !",
            ["DialogueId"] = 12047107,
            ["GUID"] = "1E289E7E",
            ["NextDialogue"] = 12047108,
            ["SpeakNpcId"] = 240042,
            ["VoiceName"] = "voice/$Locale$/story/1204/120471/1E289E7E",
            },
        [12047108] = {
            ["Content"] = "你们这些离经叛道的家伙，赶紧放开我们家囡囡！",
            ["ContentFR"] = "Vous autres, hérétiques ! Lâchez ma petite-fille !",
            ["DialogueId"] = 12047108,
            ["GUID"] = "1E289EA8",
            ["NextDialogue"] = 12047109,
            ["SpeakNpcId"] = 240042,
            ["VoiceName"] = "voice/$Locale$/story/1204/120471/1E289EA8",
            },
        [12047109] = {
            ["Content"] = "爹，都这种时候了，你少说两句吧！",
            ["ContentFR"] = "Père, ce n’est vraiment pas le moment ! S’il te plaît, tais-toi !",
            ["DialogueId"] = 12047109,
            ["GUID"] = "1E289ED2",
            ["NextDialogue"] = 12047110,
            ["SpeakNpcId"] = 240044,
            ["VoiceName"] = "voice/$Locale$/story/1204/120471/1E289ED2",
            },
        [12047110] = {
            ["Content"] = "“不会有什么好下场”……？呵，你该不会搞错了吧。",
            ["ContentFR"] = "« Rien de bon », vraiment... ? Hm. Vous faites peut-être erreur.",
            ["DialogueId"] = 12047110,
            ["GUID"] = "1E289EFC",
            ["NextDialogue"] = 12047111,
            ["SpeakNpcId"] = 240034,
            ["VoiceName"] = "voice/$Locale$/story/1204/120471/1E289EFC",
            },
        [12047111] = {
            ["Content"] = "你口中离经叛道的，刚刚救了你的命。至于你对着祈祷的神，现在还不知道在哪里呢。",
            ["ContentFR"] = "Les hérétiques que vous méprisez viennent de vous sauver la vie. Quant au dieu que vous invoquez... nul ne sait où Il se trouve à présent.",
            ["DialogueId"] = 12047111,
            ["GUID"] = "1E289F26",
            ["NextDialogue"] = 12047112,
            ["SpeakNpcId"] = 240034,
            ["VoiceName"] = "voice/$Locale$/story/1204/120471/1E289F26",
            },
        [12047112] = {
            ["Content"] = "一切都乱套了，乱套了……华胥的天是要塌下来了呀！",
            ["ContentFR"] = "Tout s’effondre... tout s’effondre... Le ciel de Huaxu va nous tomber sur la tête !",
            ["DialogueId"] = 12047112,
            ["GUID"] = "1E289F50",
            ["NextDialogue"] = 12047113,
            ["SpeakNpcId"] = 240042,
            ["VoiceName"] = "voice/$Locale$/story/1204/120471/1E289F50",
            },
        [12047113] = {
            ["Content"] = "谁都好，来人，救救我啊——",
            ["ContentFR"] = "À l’aide— ! Quelqu’un, s’il vous plaît— !",
            ["DialogueId"] = 12047113,
            ["GUID"] = "1E289F7A",
            ["NextDialogue"] = 12047114,
            ["SpeakNpcId"] = 240041,
            ["VoiceName"] = "voice/$Locale$/story/1204/120471/1E289F7A",
            },
        [12047114] = {
            ["Content"] = "朱朴，不用和他多费口舌。这个节骨眼上，还是救人要紧。",
            ["ContentFR"] = "Zhu Pu, inutile d’argumenter. À cet instant, sauver des vies passe avant tout.",
            ["DialogueId"] = 12047114,
            ["GUID"] = "1E289FA4",
            ["NextDialogue"] = 12047115,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120471/1E289FA4",
            },
        [12047115] = {
            ["Content"] = "明白了，我们走。",
            ["ContentFR"] = "Compris. Allons-y.",
            ["DialogueId"] = 12047115,
            ["GUID"] = "1E289FCE",
            ["SpeakNpcId"] = 240034,
            ["VoiceName"] = "voice/$Locale$/story/1204/120471/1E289FCE",
            },
        [12047201] = {
            ["Content"] = "这些狴犴是暂且击退了，可下一批狴犴何时来袭还未曾可知……大风九章，究竟发生了怎样的异变？",
            ["ContentFR"] = "Nous avons repoussé ces Bi’an pour l’instant... mais qui sait quand la prochaine vague frappera ? Que se passe-t-il donc au sein des Neuf Chapitres de Dafeng... ?",
            ["DialogueId"] = 12047201,
            ["GUID"] = "1E28ADEA",
            ["NextDialogue"] = 12047202,
            ["RelatedWikiId"] = {
                [1] = 408010,
                [2] = 304003,
                [3] = 303009,
                [4] = 303010,
                [5] = 303008,
                [6] = 303011,
                },
            ["SpeakNpcId"] = 240034,
            ["VoiceName"] = "voice/$Locale$/story/1204/120472/1E28ADEA",
            },
        [12047202] = {
            ["Content"] = "只要与{nickname}会合，真相就能水落石出了，相信{性别：他|她}吧。大家齐心协力，一定能解决这场危机。",
            ["ContentFR"] = "Dès que nous aurons rejoint {nickname}, la vérité éclatera. Faisons-lui confiance. Si nous restons unis, nous surmonterons cette crise.",
            ["DialogueId"] = 12047202,
            ["GUID"] = "1E28AE14",
            ["NextDialogue"] = 12047203,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120472/1E28AE14",
            },
        [12047203] = {
            ["Content"] = "话音刚落，这就有了消息。他们几人正在赶往执律阁的途中，我们也赶紧前去支援吧。",
            ["ContentFR"] = "Justement, voilà des nouvelles. Ils sont en route vers le Pavillon de l’Arbitrage. Allons leur prêter main-forte.",
            ["DialogueId"] = 12047203,
            ["GUID"] = "1E28AE3E",
            ["NextDialogue"] = 12047204,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120472/1E28AE3E",
            },
        [12047204] = {
            ["Content"] = "那这里的局面……",
            ["ContentFR"] = "Et la situation ici... ?",
            ["DialogueId"] = 12047204,
            ["GUID"] = "1E28AE68",
            ["NextDialogue"] = 12047205,
            ["SpeakNpcId"] = 240035,
            ["VoiceName"] = "voice/$Locale$/story/1204/120472/1E28AE68",
            },
        [12047205] = {
            ["Content"] = "放心，我早有准备。孙宇，赵承，你们两位留在这里，防备陷入混乱的狴犴再流窜到附近。",
            ["ContentFR"] = "Ne vous inquiétez pas, j’y ai déjà pensé. Sun Yu, Zhao Cheng — restez ici et empêchez les Bi’an désorientés de rôder à nouveau dans le quartier.",
            ["DialogueId"] = 12047205,
            ["GUID"] = "1E28AE92",
            ["NextDialogue"] = 12047206,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120472/1E28AE92",
            },
        [12047206] = {
            ["Content"] = "此外，麻烦大家随我一起，将这些带来的备用武器分发给这里的居民，让他们也有自卫的力量。",
            ["ContentFR"] = "Quant aux autres, aidez-moi à distribuer les armes de réserve aux habitants. Ils doivent pouvoir se défendre eux-mêmes.",
            ["DialogueId"] = 12047206,
            ["GUID"] = "1E28AEBC",
            ["NextDialogue"] = 12047207,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120472/1E28AEBC",
            },
        [12047207] = {
            ["Content"] = "你是说让他们也拿起武器战斗？这真的可行吗？",
            ["ContentFR"] = "Les armer... pour qu’ils combattent ? Est-ce vraiment une bonne idée ?",
            ["DialogueId"] = 12047207,
            ["GUID"] = "1E28AEE6",
            ["NextDialogue"] = 12047208,
            ["SpeakNpcId"] = 240035,
            ["VoiceName"] = "voice/$Locale$/story/1204/120472/1E28AEE6",
            },
        [12047208] = {
            ["Content"] = "且不说未经训练的人能否发挥出战力，这些人一直生活在大风九章的规训之下，怕是压根不愿意碰半点武器吧……",
            ["ContentFR"] = "Même sans parler d’entraînement... ils ont grandi sous l’autorité des Neuf Chapitres. Beaucoup refuseront sans doute de toucher une arme.",
            ["DialogueId"] = 12047208,
            ["GUID"] = "1E28AF10",
            ["NextDialogue"] = 12047209,
            ["SpeakNpcId"] = 240036,
            ["VoiceName"] = "voice/$Locale$/story/1204/120472/1E28AF10",
            },
        [12047209] = {
            ["Content"] = "不仅白费力气，还要遭人冷眼，苏乙姐，我们真的要做这种吃力不讨好的事情吗？",
            ["ContentFR"] = "On va s’attirer des regards noirs pour rien... Mademoiselle Yi, vous êtes certaine ?",
            ["DialogueId"] = 12047209,
            ["GUID"] = "1E28AF3A",
            ["NextDialogue"] = 12047210,
            ["SpeakNpcId"] = 240034,
            ["VoiceName"] = "voice/$Locale$/story/1204/120472/1E28AF3A",
            },
        [12047210] = {
            ["Content"] = "那种事情，不试试怎么知道呢？",
            ["ContentFR"] = "Comment le savoir si l’on n’essaie pas ?",
            ["DialogueId"] = 12047210,
            ["GUID"] = "1E28AF64",
            ["NextDialogue"] = 12047211,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120472/1E28AF64",
            },
        [12047211] = {
            ["Content"] = "轻言放弃可不是飘零人的作风。拜托了，请和我一起尝试一下吧！",
            ["ContentFR"] = "Renoncer avant même d’avoir tenté — ce n’est pas la voie des Vagabonds. Je vous en prie... essayons.",
            ["DialogueId"] = 12047211,
            ["GUID"] = "1E28AF8E",
            ["NextDialogue"] = 12047212,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120472/1E28AF8E",
            },
        [12047212] = {
            ["Content"] = "既然你坚持……",
            ["ContentFR"] = "... Puisque vous insistez.",
            ["DialogueId"] = 12047212,
            ["GUID"] = "1E28AFB8",
            ["SpeakNpcId"] = 240036,
            ["VoiceName"] = "voice/$Locale$/story/1204/120472/1E28AFB8",
            },
        [12047301] = {
            ["Content"] = "问完一圈了，没人愿意收下……苏乙姐，我们还是别指望这些人了。",
            ["ContentFR"] = "Nous avons demandé à tout le monde... personne n’en veut. Mademoiselle Yi, inutile d’insister.",
            ["DialogueId"] = 12047301,
            ["GUID"] = "1E28BE52",
            ["NextDialogue"] = 12047302,
            ["RelatedWikiId"] = {
                [1] = 408010,
                [2] = 304003,
                [3] = 303009,
                [4] = 303010,
                [5] = 303008,
                [6] = 303011,
                },
            ["SpeakNpcId"] = 240034,
            ["VoiceName"] = "voice/$Locale$/story/1204/120473/1E28BE52",
            },
        [12047302] = {
            ["Content"] = "不要这么轻易下定论。要是仅仅通过一次实验就得出失败的结论，那机枢派的前辈们可发明不出那么多巧夺天工的造物。",
            ["ContentFR"] = "Ne tire pas de conclusion si vite. Si les anciens de la Secte Jishu avaient abandonné après un seul échec, ils n’auraient jamais créé tant de merveilles.",
            ["DialogueId"] = 12047302,
            ["GUID"] = "1E28BE7C",
            ["NextDialogue"] = 12047303,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120473/1E28BE7C",
            },
        [12047303] = {
            ["Content"] = "你……还是不愿意放弃他们吗……",
            ["ContentFR"] = "Vous... ne voulez toujours pas les abandonner ?",
            ["DialogueId"] = 12047303,
            ["GUID"] = "1E28BEA6",
            ["NextDialogue"] = 12047327,
            ["SpeakNpcId"] = 240036,
            ["VoiceName"] = "voice/$Locale$/story/1204/120473/1E28BEA6",
            },
        [12047304] = {
            ["Content"] = "在场的各位，请听我说——",
            ["ContentFR"] = "Écoutez-moi, je vous en prie—",
            ["DialogueId"] = 12047304,
            ["GUID"] = "1E28BED0",
            ["NextDialogue"] = 12047305,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120473/1E28BED0",
            },
        [12047305] = {
            ["Content"] = "现在大风九章正在陷入混乱，我们华胥面临着前所未有的变局。狴犴现在无法保护大家，反而有可能危害到大家的性命。",
            ["ContentFR"] = "Les Neuf Chapitres de Dafeng sont en plein désarroi. Huaxu traverse une épreuve sans précédent. Les Bi’an ne peuvent plus vous protéger — ils peuvent désormais vous blesser.",
            ["DialogueId"] = 12047305,
            ["GUID"] = "1E28BEFA",
            ["NextDialogue"] = 12047306,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120473/1E28BEFA",
            },
        [12047306] = {
            ["Content"] = "我们几位接下来还要奔赴别的战场，无法一直留在这里守护大家。在危机解除之前，能够为自己的生命负起责任的，如今只有各位自己了。",
            ["ContentFR"] = "Nous devons partir vers un autre front. Nous ne pouvons rester ici. Jusqu’à ce que la crise prenne fin, chacun d’entre vous doit assumer la responsabilité de sa propre vie.",
            ["DialogueId"] = 12047306,
            ["GUID"] = "1E28BF24",
            ["NextDialogue"] = 12047307,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120473/1E28BF24",
            },
        [12047307] = {
            ["Content"] = "没错，大风九章教谕我们不要戕身害命，伤害他人。但大风九章从未说过不能为了保卫自己的家园而举起武器！",
            ["ContentFR"] = "Oui, les Neuf Chapitres nous enseignent de ne pas nuire. Mais ils n’ont jamais interdit de défendre son foyer !",
            ["DialogueId"] = 12047307,
            ["GUID"] = "1E28BF4E",
            ["NextDialogue"] = 12047308,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120473/1E28BF4E",
            },
        [12047308] = {
            ["Content"] = "是非对错，除了一直以来接受的教谕，更要依靠自己的心去判断！",
            ["ContentFR"] = "Le juste et l’injuste ne se mesurent pas seulement à la doctrine — écoutez aussi votre propre cœur !",
            ["DialogueId"] = 12047308,
            ["GUID"] = "1E28BF78",
            ["NextDialogue"] = 12047309,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120473/1E28BF78",
            },
        [12047309] = {
            ["Content"] = "你们不妨问问自己的本心，为了保护亲朋好友而拿起武器，真的是罪恶的吗？",
            ["ContentFR"] = "Dites-moi... protéger ceux que vous aimez en prenant les armes... est-ce réellement un crime ?",
            ["DialogueId"] = 12047309,
            ["GUID"] = "1E28BFA2",
            ["NextDialogue"] = 12047310,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120473/1E28BFA2",
            },
        [12047310] = {
            ["Content"] = "……",
            ["ContentFR"] = "...",
            ["DialogueId"] = 12047310,
            ["GUID"] = "1E28BFCC",
            ["NextDialogue"] = 12047311,
            ["SpeakNpcId"] = 0,
            ["VoiceName"] = "voice/$Locale$/story/1204/120473/1E28BFCC",
            },
        [12047311] = {
            ["Content"] = "……",
            ["ContentFR"] = "...",
            ["DialogueId"] = 12047311,
            ["GUID"] = "1E28BFF6",
            ["NextDialogue"] = 12047312,
            ["SpeakNpcId"] = 0,
            ["VoiceName"] = "voice/$Locale$/story/1204/120473/1E28BFF6",
            },
        [12047312] = {
            ["Content"] = "也给我来一把武器吧。",
            ["ContentFR"] = "Donnez-m’en une.",
            ["DialogueId"] = 12047312,
            ["GUID"] = "1E28C020",
            ["NextDialogue"] = 12047313,
            ["SpeakNpcId"] = 240044,
            ["VoiceName"] = "voice/$Locale$/story/1204/120473/1E28C020",
            },
        [12047313] = {
            ["Content"] = "咦，你是刚刚的……",
            ["ContentFR"] = "Ah... vous êtes la mère de tout à l’heure...",
            ["DialogueId"] = 12047313,
            ["GUID"] = "1E28C04A",
            ["NextDialogue"] = 12047314,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120473/1E28C04A",
            },
        [12047314] = {
            ["Content"] = "恩人，你救了囡囡，我还未向你道谢呢。",
            ["ContentFR"] = "Vous avez sauvé ma fille. Je ne vous ai pas encore remerciée.",
            ["DialogueId"] = 12047314,
            ["GUID"] = "1E28C074",
            ["NextDialogue"] = 12047315,
            ["SpeakNpcId"] = 240044,
            ["VoiceName"] = "voice/$Locale$/story/1204/120473/1E28C074",
            },
        [12047315] = {
            ["Content"] = "要是囡囡出了什么事，我一定会在悔恨中度过一生。哪怕是未来遭到天罚，至少这一刻，我一定要保护我的囡囡！",
            ["ContentFR"] = "Si Nannan avait été blessée... je ne me serais jamais pardonnée. Même si le Ciel devait me punir plus tard... en cet instant, je protégerai ma fille !",
            ["DialogueId"] = 12047315,
            ["GUID"] = "1E28C09E",
            ["NextDialogue"] = 12047316,
            ["SpeakNpcId"] = 240044,
            ["VoiceName"] = "voice/$Locale$/story/1204/120473/1E28C09E",
            },
        [12047316] = {
            ["Content"] = "自己家人的性命，怎么能全寄托在别人身上。",
            ["ContentFR"] = "Comment pourrais-je confier la vie des miens entièrement à autrui ?",
            ["DialogueId"] = 12047316,
            ["GUID"] = "1E28C0C8",
            ["NextDialogue"] = 12047317,
            ["SpeakNpcId"] = 240044,
            ["VoiceName"] = "voice/$Locale$/story/1204/120473/1E28C0C8",
            },
        [12047317] = {
            ["Content"] = "说得好！武器来嘞，您接好咯！",
            ["ContentFR"] = "Voilà qui est bien dit ! Tenez — prenez celle-ci !",
            ["DialogueId"] = 12047317,
            ["GUID"] = "1E28C0F2",
            ["NextDialogue"] = 12047318,
            ["SpeakNpcId"] = 240034,
            ["VoiceName"] = "voice/$Locale$/story/1204/120473/1E28C0F2",
            },
        [12047318] = {
            ["Content"] = "这可是我师傅精心打造的连环弩，扣下扳机就能连珠发射弩箭，包您上手就能使用，没有任何门槛！",
            ["ContentFR"] = "C’est une arbalète à répétition forgée par mon maître. Une simple pression sur la détente, et les carreaux partent en rafale. Facile à manier !",
            ["DialogueId"] = 12047318,
            ["GUID"] = "1E28C11C",
            ["NextDialogue"] = 12047319,
            ["SpeakNpcId"] = 240034,
            ["VoiceName"] = "voice/$Locale$/story/1204/120473/1E28C11C",
            },
        [12047319] = {
            ["Content"] = "那，请给我也来一把……",
            ["ContentFR"] = "Alors... donnez-m’en une à moi aussi...",
            ["DialogueId"] = 12047319,
            ["GUID"] = "1E28C146",
            ["NextDialogue"] = 12047320,
            ["SpeakNpcId"] = 240046,
            ["VoiceName"] = "voice/$Locale$/story/1204/120473/1E28C146",
            },
        [12047320] = {
            ["Content"] = "我长一身腱子肉，怎么能眼睁睁看着别人杀敌，自己躲在后面。小伙子，给我也来一把！",
            ["ContentFR"] = "J’ai des bras faits pour me battre ! Je ne resterai pas en retrait pendant que d’autres se battent ! Hé, donnez-m’en une !",
            ["DialogueId"] = 12047320,
            ["GUID"] = "1E28C170",
            ["NextDialogue"] = 12047321,
            ["SpeakNpcId"] = 240047,
            ["VoiceName"] = "voice/$Locale$/story/1204/120473/1E28C170",
            },
        [12047321] = {
            ["Content"] = "呼、呼……这边的情况，如何了？",
            ["ContentFR"] = "Hah... hah... Quelle est la situation ici ?",
            ["DialogueId"] = 12047321,
            ["GUID"] = "1E28C19A",
            ["NextDialogue"] = 12047322,
            ["SpeakNpcId"] = 240048,
            ["VoiceName"] = "voice/$Locale$/story/1204/120473/1E28C19A",
            },
        [12047322] = {
            ["Content"] = "我们是自泽生阁赶来的草药学徒，若出现伤者，请交由我们照料。我们会尽自己所能，挽救每一条生命的！",
            ["ContentFR"] = "Nous venons de la Pharmacie Zesheng. S’il y a des blessés, confiez-les-nous. Nous ferons tout pour sauver chaque vie !",
            ["DialogueId"] = 12047322,
            ["GUID"] = "1E28C1C4",
            ["NextDialogue"] = 12047323,
            ["SpeakNpcId"] = 240049,
            ["VoiceName"] = "voice/$Locale$/story/1204/120473/1E28C1C4",
            },
        [12047323] = {
            ["Content"] = "哈哈！泽生阁的招牌，我放心！这下没有后顾之忧，可以放心御敌了！",
            ["ContentFR"] = "Haha ! Avec la Pharmacie Zesheng, nous n’avons plus rien à craindre ! Allons repousser l’ennemi !",
            ["DialogueId"] = 12047323,
            ["GUID"] = "1E28C1EE",
            ["NextDialogue"] = 12047324,
            ["SpeakNpcId"] = 240047,
            ["VoiceName"] = "voice/$Locale$/story/1204/120473/1E28C1EE",
            },
        [12047324] = {
            ["Content"] = "恩人，你们是否还有更要紧的事情？赶紧去吧。这边就放心交给我们好了！",
            ["ContentFR"] = "Bienfaitrice... vous avez sûrement des affaires plus urgentes. Partez. Nous tiendrons ici.",
            ["DialogueId"] = 12047324,
            ["GUID"] = "1E28C218",
            ["NextDialogue"] = 12047325,
            ["SpeakNpcId"] = 240044,
            ["VoiceName"] = "voice/$Locale$/story/1204/120473/1E28C218",
            },
        [12047325] = {
            ["Content"] = "大家……太好了！",
            ["ContentFR"] = "Vous tous... merci !",
            ["DialogueId"] = 12047325,
            ["GUID"] = "1E28C242",
            ["NextDialogue"] = 12047326,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120473/1E28C242",
            },
        [12047326] = {
            ["Content"] = "那我们先走了！放心吧，我的同伴们一定能尽早结束这场混乱，还大家一个平安！等我们的好消息！",
            ["ContentFR"] = "Alors nous partons. Rassurez-vous — mes compagnons mettront fin à ce chaos au plus vite. Attendez notre retour... avec de bonnes nouvelles !",
            ["DialogueId"] = 12047326,
            ["GUID"] = "1E28C26C",
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120473/1E28C26C",
            },
        [12047327] = {
            ["DialogueId"] = 12047327,
            ["NextDialogue"] = 12047304,
            },
        [12047401] = {
            ["Content"] = "哇，城里到处都是狴犴，乱糟糟的……白还从来没看过这种景象。",
            ["ContentFR"] = "Ouah ! Il y a des Bi’an partout... c’est un vrai chaos ! Je n’ai jamais vu ça !",
            ["DialogueId"] = 12047401,
            ["GUID"] = "1E28CEBA",
            ["NextDialogue"] = 12047402,
            ["RelatedWikiId"] = {
                [1] = 408010,
                [2] = 304003,
                [3] = 303009,
                [4] = 303010,
                [5] = 303008,
                [6] = 303011,
                },
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120474/1E28CEBA",
            },
        [12047402] = {
            ["Content"] = "不能再放任这种情况下去了！{nickname}，你带头，我殿后，我们杀出一条路来！",
            ["ContentFR"] = "On ne peut pas laisser ça durer ! {nickname}, ouvre la voie — je couvre l’arrière ! On se fraie un passage !",
            ["DialogueId"] = 12047402,
            ["GUID"] = "1E28CEE4",
            ["NextDialogue"] = 12047403,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120474/1E28CEE4",
            },
        [12047403] = {
            ["Content"] = "那这些平民该怎么办？",
            ["ContentFR"] = "Et les civils ?",
            ["DialogueId"] = 12047403,
            ["GUID"] = "1E28CF0E",
            ["NextDialogue"] = 12047404,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120474/1E28CF0E",
            },
        [12047404] = {
            ["Content"] = "——放心，有我们呢！",
            ["ContentFR"] = "— Laisse-nous faire !",
            ["DialogueId"] = 12047404,
            ["GUID"] = "1E28CF38",
            ["NextDialogue"] = 12047405,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120474/1E28CF38",
            },
        [12047405] = {
            ["Content"] = "姑奶奶，你来得真及时！",
            ["ContentFR"] = "Ah ! Grande-tante ! T’arrives pile au bon moment !",
            ["DialogueId"] = 12047405,
            ["GUID"] = "1E28CF62",
            ["NextDialogue"] = 12047406,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120474/1E28CF62",
            },
        [12047406] = {
            ["Content"] = "呵，你也不想想我是谁。城中一草一木的情报，都在我的掌控之中。得知城中异变，我可是一收拾好山外山的残局，就带着大家马不停蹄地赶来了。",
            ["ContentFR"] = "<I>Hmpf.</> Tu oublies à qui tu parles. Rien de ce qui se trame en ville ne m’échappe. Dès que j’ai appris les troubles, j’ai réglé les affaires aux Pics Extérieurs et j’ai accouru sans tarder.",
            ["DialogueId"] = 12047406,
            ["GUID"] = "1E28CF8C",
            ["NextDialogue"] = 12047407,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120474/1E28CF8C",
            },
        [12047407] = {
            ["Content"] = "{nickname}，你只管一直向前便是。这里的局面，我会处理好的，放心交给我吧！",
            ["ContentFR"] = "{nickname}, avance sans te retourner. Je m’occupe d’ici. Laisse-moi cette tâche.",
            ["DialogueId"] = 12047407,
            ["GUID"] = "1E28CFB6",
            ["NextDialogue"] = 12047408,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120474/1E28CFB6",
            },
        [12047408] = {
            ["Content"] = "那，小仆从，我们赶紧往前……",
            ["ContentFR"] = "Alors, petit larbin, allons de l’avant—",
            ["DialogueId"] = 12047408,
            ["GUID"] = "1E28CFE0",
            ["NextDialogue"] = 12047409,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120474/1E28CFE0",
            },
        [12047409] = {
            ["Content"] = "……稍等。",
            ["ContentFR"] = "... Attends.",
            ["DialogueId"] = 12047409,
            ["GUID"] = "1E28D00A",
            ["NextDialogue"] = 12047410,
            ["SpeakNpcId"] = 240002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120474/1E28D00A",
            },
        [12047410] = {
            ["Content"] = "抱歉，{nickname}，接下来的路，我……恐怕没法陪伴你了。",
            ["ContentFR"] = "Pardonne-moi, {nickname}... mais la route qui suit, je ne pourrai plus l’emprunter à tes côtés.",
            ["DialogueId"] = 12047410,
            ["GUID"] = "1E28D034",
            ["NextDialogue"] = 12047411,
            ["SpeakNpcId"] = 240002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120474/1E28D034",
            },
        [12047411] = {
            ["Content"] = "倘若大风九章即将告终，在一切成为定局之前，我有必须完成的夙愿……",
            ["ContentFR"] = "Si les Neuf Chapitres de Dafeng doivent vraiment s’achever, j’ai un vœu de longue date que je dois accomplir... avant que tout ne devienne irréversible.",
            ["DialogueId"] = 12047411,
            ["GUID"] = "1E28D05E",
            ["NextOptions"] = {
                [1] = 12047412,
                [2] = 12047413,
                },
            ["SpeakNpcId"] = 240002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120474/1E28D05E",
            },
        [12047412] = {
            ["Content"] = "我之前说过，你不用和我道歉。",
            ["ContentFR"] = "<I>Je te l’ai déjà dit. Tu n’as pas à t’excuser.</>",
            ["DialogueId"] = 12047412,
            ["GUID"] = "1E28D088",
            ["NextDialogue"] = 12047414,
            },
        [12047413] = {
            ["Content"] = "作为朋友，我希望你能完成你的心愿。",
            ["ContentFR"] = "<I>En tant qu’{性别:ami|amie}, je veux que tu accomplisses ton souhait.</>",
            ["DialogueId"] = 12047413,
            ["GUID"] = "1E28D0B2",
            ["NextDialogue"] = 12047414,
            },
        [12047414] = {
            ["Content"] = "……{nickname}，谢谢。",
            ["ContentFR"] = "... Merci, {nickname}.",
            ["DialogueId"] = 12047414,
            ["GUID"] = "1E28D0DC",
            ["NextDialogue"] = 12047415,
            ["SpeakNpcId"] = 240002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120474/1E28D0DC",
            },
        [12047415] = {
            ["Content"] = "我们走吧，去终结这一切！",
            ["ContentFR"] = "Allons-y. Mettons un terme à tout cela.",
            ["DialogueId"] = 12047415,
            ["GUID"] = "1E28D106",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120474/1E28D106",
            },
        [12047501] = {
            ["Content"] = "师兄，这次你也是来阻止我们的吗？",
            ["ContentFR"] = "Yuming... tu viens encore nous barrer la route ?",
            ["DialogueId"] = 12047501,
            ["GUID"] = "1E28DF22",
            ["NextDialogue"] = 12047502,
            ["RelatedWikiId"] = {
                [1] = 203007,
                [2] = 203004,
                },
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120475/1E28DF22",
            },
        [12047502] = {
            ["Content"] = "我……",
            ["ContentFR"] = "Je...",
            ["DialogueId"] = 12047502,
            ["GUID"] = "1E28DF4C",
            ["NextDialogue"] = 12047503,
            ["SpeakNpcId"] = 210007,
            ["VoiceName"] = "voice/$Locale$/story/1204/120475/1E28DF4C",
            },
        [12047503] = {
            ["Content"] = "“职责所在”是吧？你得护卫这大风九章核心区域，我懂，不用说了。",
            ["ContentFR"] = "« Tel est mon devoir », n’est-ce pas ? Tu dois défendre le cœur des Neuf Chapitres. Je comprends. Pas besoin d’en dire plus.",
            ["DialogueId"] = 12047503,
            ["GUID"] = "1E28DF76",
            ["NextDialogue"] = 12047504,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120475/1E28DF76",
            },
        [12047504] = {
            ["Content"] = "{nickname}，你们先走，别在这儿耽搁了。",
            ["ContentFR"] = "{nickname}, continue sans moi. Ne perds pas de temps ici.",
            ["DialogueId"] = 12047504,
            ["GUID"] = "1E28DFA0",
            ["NextDialogue"] = 12047505,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120475/1E28DFA0",
            },
        [12047505] = {
            ["Content"] = "好。",
            ["ContentFR"] = "Très bien.",
            ["DialogueId"] = 12047505,
            ["GUID"] = "1E28DFCA",
            ["NextDialogue"] = 12047506,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120475/1E28DFCA",
            },
        [12047506] = {
            ["Content"] = "师兄，拔出武器吧，在这里拦下你，也是我的职责！",
            ["ContentFR"] = "Yuming... dégaine. Te retenir ici, c’est aussi mon devoir.",
            ["DialogueId"] = 12047506,
            ["GUID"] = "1E28DFF4",
            ["NextDialogue"] = 12047507,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120475/1E28DFF4",
            },
        [12047507] = {
            ["Content"] = "先前我可能还心有动摇，但现在已经不会了！",
            ["ContentFR"] = "Peut-être ai-je hésité autrefois. Mais plus maintenant.",
            ["DialogueId"] = 12047507,
            ["GUID"] = "1E28E01E",
            ["NextDialogue"] = 12047508,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120475/1E28E01E",
            },
        [12047508] = {
            ["Content"] = "你问我的问题，我已经想明白了！是谁规定鱼和熊掌不可兼得？我刻舟偏就全都要！",
            ["ContentFR"] = "La question que tu m’as posée... j’ai trouvé ma réponse. Qui a décrété qu’on ne pouvait pas tout vouloir ? Moi, Kezhou, je refuse de choisir !",
            ["DialogueId"] = 12047508,
            ["GUID"] = "1E28E048",
            ["NextDialogue"] = 12047509,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120475/1E28E048",
            },
        [12047509] = {
            ["Content"] = "谁说了人非得为别人而战？若是人人拿起武器，齐心协力，别说区区秽蚀，还有什么能够抵挡其势？这样一个未来，我便证明给你看！",
            ["ContentFR"] = "Qui a dit qu’on devait toujours combattre pour les autres ? Si chacun prenait les armes et se dressait ensemble, la Dégradation elle-même ne pourrait rien contre nous ! Ce futur-là... je te le prouverai !",
            ["DialogueId"] = 12047509,
            ["GUID"] = "1E28E072",
            ["NextDialogue"] = 12047510,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120475/1E28E072",
            },
        [12047510] = {
            ["Content"] = "……",
            ["ContentFR"] = "...",
            ["DialogueId"] = 12047510,
            ["GUID"] = "1E28E09C",
            ["SpeakNpcId"] = 210007,
            ["VoiceName"] = "voice/$Locale$/story/1204/120475/1E28E09C",
            },
        [12047511] = {
            ["DialogueId"] = 12047511,
            ["GUID"] = "12047511.0",
            ["NextDialogue"] = 12047501,
            },
        [12047601] = {
            ["Content"] = "你们，不许再靠近我家囡囡一步！",
            ["ContentFR"] = "N’approchez pas de ma fille !",
            ["DialogueId"] = 12047601,
            ["GUID"] = "1E28EF8A",
            ["NextDialogue"] = 12047602,
            ["SpeakNpcId"] = 240044,
            ["VoiceName"] = "voice/$Locale$/story/1204/120476/1E28EF8A",
            },
        [12047602] = {
            ["Content"] = "我今天的英勇表现，怎么也能刊于那个《皓京市声报》上吧！不止是应天尉，我们普通人也能当英雄啊！",
            ["ContentFR"] = "Haha ! Avec ce que j’ai accompli aujourd’hui, mon nom figurera bien dans <I>L’Écho de Haojing</> ! Les héros ne sont pas que les Magistrats de Yingtian — nous aussi, simples citoyens, pouvons l’être !",
            ["DialogueId"] = 12047602,
            ["GUID"] = "1E28EFB4",
            ["NextDialogue"] = 12047603,
            ["SpeakNpcId"] = 240047,
            ["VoiceName"] = "voice/$Locale$/story/1204/120476/1E28EFB4",
            },
        [12047603] = {
            ["Content"] = "集中精神，这里再缠些绷带！今天，每一个伤者都务必照料好了！",
            ["ContentFR"] = "Concentrez-vous ! Encore un bandage ici ! Aucun blessé ne sera abandonné !",
            ["DialogueId"] = 12047603,
            ["GUID"] = "1E28EFDE",
            ["SpeakNpcId"] = 240048,
            ["VoiceName"] = "voice/$Locale$/story/1204/120476/1E28EFDE",
            },
        [12047701] = {
            ["Content"] = "狴犴纷纷在向执律阁涌来，苏乙姐，怎么会有如此之多……",
            ["ContentFR"] = "Les Bi’an affluent vers le Pavillon de l’Arbitrage... Mademoiselle Yi, comment peuvent-ils être si nombreux ?",
            ["DialogueId"] = 12047701,
            ["GUID"] = "1E28FFF2",
            ["NextDialogue"] = 12047702,
            ["SpeakNpcId"] = 240035,
            ["VoiceName"] = "voice/$Locale$/story/1204/120477/1E28FFF2",
            },
        [12047702] = {
            ["Content"] = "再坚持一下，{nickname}还在上方为我们战斗呢！曙光就在眼前了！",
            ["ContentFR"] = "Tenez bon ! {nickname} se bat là-haut pour nous ! On y est presque !",
            ["DialogueId"] = 12047702,
            ["GUID"] = "1E29001C",
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120477/1E29001C",
            },
        [12047801] = {
            ["Content"] = "一日未见，你的剑……竟变得如此凌厉。",
            ["ContentFR"] = "En si peu de temps... ta lame est devenue redoutable.",
            ["DialogueId"] = 12047801,
            ["GUID"] = "1E29105A",
            ["NextDialogue"] = 12047802,
            ["SpeakNpcId"] = 210007,
            ["VoiceName"] = "voice/$Locale$/story/1204/120478/1E29105A",
            },
        [12047802] = {
            ["Content"] = "哈哈！心无旁骛，剑法也自然轻快！师兄，我已找到了前进的方向，你呢？",
            ["ContentFR"] = "Haha ! Quand l’esprit est clair, l’épée frappe juste ! Yuming... j’ai trouvé ma voie. Et toi ?",
            ["DialogueId"] = 12047802,
            ["GUID"] = "1E291084",
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120478/1E291084",
            },
        [12047901] = {
            ["Content"] = "人之为人，皆因有心。以人为本，亦是以心为本。若要华胥万世太平，怎能忽视了心，使得本末倒置，阴阳颠倒？",
            ["ContentFR"] = "L’être humain est ce qu’il est parce qu’il possède un cœur. Mettre l’humain au centre, c’est honorer ce cœur. Si Huaxu aspire à une paix durable, comment pourrait-on ignorer le cœur sans renverser l’ordre des choses ?",
            ["DialogueId"] = 12047901,
            ["GUID"] = "1E2920C2",
            ["NextDialogue"] = 12047902,
            ["SpeakNpcId"] = 240050,
            ["VoiceName"] = "voice/$Locale$/story/1204/120479/1E2920C2",
            },
        [12047902] = {
            ["Content"] = "人心似川流，若无理之约束便会漫溢。法应如堤岸，顺应心之所向而不违其渊。",
            ["ContentFR"] = "Le cœur humain est semblable à un fleuve. Sans le cadre du principe, il déborde. La loi doit être comme une rive : guider le courant sans en trahir la source.",
            ["DialogueId"] = 12047902,
            ["GUID"] = "1E2920EC",
            ["NextDialogue"] = 12047903,
            ["SpeakNpcId"] = 240051,
            ["VoiceName"] = "voice/$Locale$/story/1204/120479/1E2920EC",
            },
        [12047903] = {
            ["Content"] = "心、理平衡，则道生，圣人以道莅天下，其治若水，不争而善应，不令而自正……",
            ["ContentFR"] = "Lorsque cœur et principe s’équilibrent, la Voie apparaît. Le sage gouverne alors comme l’eau : sans lutte, mais avec justesse ; sans contrainte, mais avec rectitude.",
            ["DialogueId"] = 12047903,
            ["GUID"] = "1E292116",
            ["NextDialogue"] = 12047904,
            ["SpeakNpcName"] = "UI_Npc_Name_JuYang",
            ["VoiceName"] = "voice/$Locale$/story/1204/120479/1E292116",
            },
        [12047904] = {
            ["Content"] = "此理，你们二位如何见得？",
            ["ContentFR"] = "Et vous deux... qu’en comprenez-vous ?",
            ["DialogueId"] = 12047904,
            ["GUID"] = "1E292140",
            ["NextDialogue"] = 12047905,
            ["SpeakNpcName"] = "UI_Npc_Name_JuYang",
            ["VoiceName"] = "voice/$Locale$/story/1204/120479/1E292140",
            },
        [12047905] = {
            ["Content"] = "两位莫非是……矩和飏先辈？",
            ["ContentFR"] = "Seriez-vous... les anciens maîtres Ju et Yang ?",
            ["DialogueId"] = 12047905,
            ["GUID"] = "1E29216A",
            ["NextDialogue"] = 12047906,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120479/1E29216A",
            },
        [12047906] = {
            ["Content"] = "呵呵……千年已逝，吾等意志运转过久，逐渐忘却自身存在，直到被尔等作为唤醒。",
            ["ContentFR"] = "Mille années ont passé. Nos volontés ont longtemps œuvré sans relâche, au point d’en oublier notre propre existence... Jusqu’à ce que vous nous rappeliez à nous-mêmes.",
            ["DialogueId"] = 12047906,
            ["GUID"] = "1E292194",
            ["NextDialogue"] = 12047907,
            ["SpeakNpcId"] = 240050,
            ["VoiceName"] = "voice/$Locale$/story/1204/120479/1E292194",
            },
        [12047907] = {
            ["Content"] = "大风九章极兴则人弱，骤亡则人危。舍弃一方以致心、理失衡固不可为，玉石俱焚亦非明德之举。止流，你看破大风九章的弊端，手法却过于极端。",
            ["ContentFR"] = "Lorsque les Neuf Chapitres s’imposent à l’excès, le peuple s’affaiblit. Lorsqu’ils s’effondrent brutalement, le peuple est en péril. Abandonner l’un des pôles et rompre l’équilibre de cœur et de principe est une erreur ; mais tout réduire en cendres n’est pas davantage une voie éclairée. Zhiliu, tu as discerné les failles des Neuf Chapitres... mais ton geste fut trop extrême.",
            ["DialogueId"] = 12047907,
            ["GUID"] = "1E2921BE",
            ["NextDialogue"] = 12047908,
            ["SpeakNpcId"] = 240051,
            ["VoiceName"] = "voice/$Locale$/story/1204/120479/1E2921BE",
            },
        [12047908] = {
            ["Content"] = "唯窥破“中庸”、“谐和”之道，方为智者。",
            ["ContentFR"] = "Seul celui qui comprend la voie de la mesure et de l’harmonie peut être appelé sage.",
            ["DialogueId"] = 12047908,
            ["GUID"] = "1E2921E8",
            ["NextDialogue"] = 12047909,
            ["SpeakNpcId"] = 240051,
            ["VoiceName"] = "voice/$Locale$/story/1204/120479/1E2921E8",
            },
        [12047909] = {
            ["Content"] = "使大风九章复归赤子，顺应万民之念。如此，可遂君愿？",
            ["ContentFR"] = "Ramener les Neuf Chapitres à leur pureté originelle, et les accorder à la volonté du peuple. Cela accomplirait-il ton souhait ?",
            ["DialogueId"] = 12047909,
            ["GUID"] = "1E292212",
            ["NextOptions"] = {
                [1] = 12047911,
                },
            ["SpeakNpcId"] = 240050,
            ["VoiceName"] = "voice/$Locale$/story/1204/120479/1E292212",
            },
        [12047910] = {
            ["Content"] = "二位，将手递与我罢。",
            ["ContentFR"] = "Alors... vous deux. Tendez-nous la main.",
            ["DialogueId"] = 12047910,
            ["GUID"] = "1E29223C",
            ["SpeakNpcName"] = "UI_Npc_Name_JuYang",
            ["VoiceName"] = "voice/$Locale$/story/1204/120479/1E29223C",
            },
        [12047911] = {
            ["Content"] = "我答应！",
            ["ContentFR"] = "<I>J’accepte !</>",
            ["DialogueId"] = 12047911,
            ["GUID"] = "1E292266",
            ["NextDialogue"] = 12047910,
            },
        [12048001] = {
            ["Content"] = "昔日华胥先人，见秽蚀频生，不忍之，故造大风九章之伟业。望心、理平衡，人、神共治，保华胥万世之安泰。",
            ["ContentFR"] = "Autrefois, voyant la Dégradation se répandre sans fin, les anciens de Huaxu, mus par la compassion, forgèrent les Neuf Chapitres de Dafeng. Ils espéraient établir l’équilibre entre cœur et principe, et permettre aux dieux et aux hommes de gouverner ensemble, afin que Huaxu connaisse la paix à travers les âges.",
            ["DialogueId"] = 12048001,
            ["GUID"] = "1E29312A",
            ["NextDialogue"] = 12048002,
            ["SpeakNpcId"] = 240024,
            ["VoiceName"] = "voice/$Locale$/story/1204/120480/1E29312A",
            },
        [12048002] = {
            ["Content"] = "然烛阴被封，吾独掌大风九章，渐忘四时有序之理。以天罚代仁心，借律典筑高墙……此乃吾之罪衍。",
            ["ContentFR"] = "Mais lorsque Zhuyin fut scellé, je restai seul à porter le rituel. Peu à peu, j’en vins à oublier l’ordre naturel des saisons. Je substituai le châtiment céleste à la bienveillance, et dressai des murs de lois rigides autour du monde. Telle est ma faute.",
            ["DialogueId"] = 12048002,
            ["GUID"] = "1E293154",
            ["NextDialogue"] = 12048003,
            ["SpeakNpcId"] = 240024,
            ["VoiceName"] = "voice/$Locale$/story/1204/120480/1E293154",
            },
        [12048003] = {
            ["Content"] = "孤阴不生，独阳不长，吾已一意孤行了太久。",
            ["ContentFR"] = "Le yin, seul, ne peut croître ; le yang, solitaire, ne peut prospérer. Trop longtemps ai-je agi seule.",
            ["DialogueId"] = 12048003,
            ["GUID"] = "1E29317E",
            ["NextDialogue"] = 12048004,
            ["SpeakNpcId"] = 240024,
            ["VoiceName"] = "voice/$Locale$/story/1204/120480/1E29317E",
            },
        [12048004] = {
            ["Content"] = "幸哉！尔以赤子之心，破吾迷障。",
            ["ContentFR"] = "Heureusement... par la pureté de ton cœur, tu as dissipé mon aveuglement.",
            ["DialogueId"] = 12048004,
            ["GUID"] = "1E2931A8",
            ["NextDialogue"] = 12048005,
            ["SpeakNpcId"] = 240024,
            ["VoiceName"] = "voice/$Locale$/story/1204/120480/1E2931A8",
            },
        [12048005] = {
            ["Content"] = "如今阴阳重调，烛阴归位，吾等将重振上古辩法之制，与凡人共治华胥。",
            ["ContentFR"] = "À présent que l’équilibre est rétabli et que Zhuyin a repris sa place, nous restaurerons l’antique système de débat : les dieux et les mortels délibéreront ensemble, et Huaxu sera gouvernée en commun.",
            ["DialogueId"] = 12048005,
            ["GUID"] = "1E2931D2",
            ["NextDialogue"] = 12048006,
            ["RelatedWikiId"] = {
                [1] = 304003,
                },
            ["SpeakNpcId"] = 240024,
            ["VoiceName"] = "voice/$Locale$/story/1204/120480/1E2931D2",
            },
        [12048006] = {
            ["Content"] = "{nickname}，此枚鳞片，愿君纳之。",
            ["ContentFR"] = "{nickname}, reçois cette écaille.",
            ["DialogueId"] = 12048006,
            ["GUID"] = "1E2931FC",
            ["NextDialogue"] = 12048007,
            ["SpeakNpcId"] = 240024,
            ["VoiceName"] = "voice/$Locale$/story/1204/120480/1E2931FC",
            },
        [12048007] = {
            ["Content"] = "他日君若有需，凡在华胥之土，凭此信物，吾必竭力以助。",
            ["ContentFR"] = "Si un jour tu as besoin d’aide, où que tu te trouves sur la terre de Huaxu, présente ce gage — et je viendrai t’assister de toutes mes forces.",
            ["DialogueId"] = 12048007,
            ["GUID"] = "1E293226",
            ["NextDialogue"] = 12048008,
            ["SpeakNpcId"] = 240024,
            ["VoiceName"] = "voice/$Locale$/story/1204/120480/1E293226",
            },
        [12048008] = {
            ["Content"] = "获得一条神龙的感激……这种感觉还蛮不错的诶！很符合魔王大人的身份！",
            ["ContentFR"] = "Obtenir la reconnaissance d’un Seigneur Dragon... voilà qui sied parfaitement à la grandeur du Roi Démon !",
            ["DialogueId"] = 12048008,
            ["GUID"] = "1E293250",
            ["NextDialogue"] = 12048009,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120480/1E293250",
            },
        [12048009] = {
            ["Content"] = "此间事毕。若无他务，君等可去矣。",
            ["ContentFR"] = "Notre affaire est achevée. Si vous n’avez plus rien à demander, vous pouvez partir.",
            ["DialogueId"] = 12048009,
            ["GUID"] = "1E29327A",
            ["SpeakNpcId"] = 240024,
            ["VoiceName"] = "voice/$Locale$/story/1204/120480/1E29327A",
            },
        [12048101] = {
            ["Content"] = "…………",
            ["ContentFR"] = "...",
            ["DialogueId"] = 12048101,
            ["GUID"] = "1E294192",
            ["NextDialogue"] = 12048102,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120481/1E294192",
            },
        [12048102] = {
            ["Content"] = "{nickname}……陪我去一个地方走走，好吗？",
            ["ContentFR"] = "{nickname}... accepterais-tu de marcher un peu avec moi ?",
            ["DialogueId"] = 12048102,
            ["GUID"] = "1E2941BC",
            ["NextDialogue"] = 12048103,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120481/1E2941BC",
            },
        [12048103] = {
            ["Content"] = "……倘若你还愿意。",
            ["ContentFR"] = "... Si tu en as encore le cœur.",
            ["DialogueId"] = 12048103,
            ["GUID"] = "1E2941E6",
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120481/1E2941E6",
            },
        [12048201] = {
            ["Content"] = "止流，我……",
            ["ContentFR"] = "Zhiliu, je...",
            ["DialogueId"] = 12048201,
            ["GUID"] = "1E2951FA",
            ["NextOptions"] = {
                [1] = 12048202,
                [2] = 12048203,
                [3] = 12048204,
                },
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120482/1E2951FA",
            },
        [12048202] = {
            ["Content"] = "（并没有生她的气。）",
            ["ContentFR"] = "<I>Ne pas lui en vouloir</>",
            ["DialogueId"] = 12048202,
            ["GUID"] = "1E295224",
            ["NextDialogue"] = 12048205,
            },
        }
  end },
  { MinKey = 12048203, MaxKey = 12049105, Loader = function()
      return {
        [12048203] = {
            ["Content"] = "（还没有能够原谅她。）",
            ["ContentFR"] = "<I>Ne pas lui pardonner</>",
            ["DialogueId"] = 12048203,
            ["GUID"] = "1E29524E",
            ["NextDialogue"] = 12048209,
            },
        [12048204] = {
            ["Content"] = "（让止流猜。）",
            ["ContentFR"] = "<I>Lui laisser deviner</>",
            ["DialogueId"] = 12048204,
            ["GUID"] = "1E295278",
            ["NextDialogue"] = 12048211,
            },
        [12048205] = {
            ["Content"] = "你突然这么拘谨，我好不习惯……放心吧，我早就不生气了。相反，我很感谢你让我成为英雄。",
            ["ContentFR"] = "Tu es devenue si prudente tout à coup que cela me déroute... Rassure-toi. Il y a longtemps que je ne suis plus en colère. Au contraire... je te suis {性别:reconnaissant|reconnaissante}. Tu m’as permis de devenir un héros.",
            ["DialogueId"] = 12048205,
            ["GUID"] = "1E2952A2",
            ["NextDialogue"] = 12048206,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120482/1E2952A2",
            },
        [12048206] = {
            ["Content"] = "倒是你坦诚得让我有些意外。我原本以为你会更……心安理得一些？",
            ["ContentFR"] = "Je dois dire que ta franchise m’étonne. Je pensais que tu serais plus... sereine avec toi-même.",
            ["DialogueId"] = 12048206,
            ["GUID"] = "1E2952CC",
            ["NextDialogue"] = 12048207,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120482/1E2952CC",
            },
        [12048207] = {
            ["Content"] = "如果我像计划中一样死在了太虚陵，或许会如此吧……我可以心安理得地告诉自己，在生命的筹码面前，一切都已经无足轻重。",
            ["ContentFR"] = "Si j’étais morte comme je l’avais prévu au Mausolée... peut-être l’aurais-je été. J’aurais pu me convaincre que, lorsque la vie est mise en jeu, tout le reste devient insignifiant.",
            ["DialogueId"] = 12048207,
            ["GUID"] = "1E2952F6",
            ["NextDialogue"] = 12048208,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120482/1E2952F6",
            },
        [12048208] = {
            ["Content"] = "但我未曾算到，我会托你的福活下来。",
            ["ContentFR"] = "Mais je n’avais pas prévu de survivre... grâce à toi.",
            ["DialogueId"] = 12048208,
            ["GUID"] = "1E295320",
            ["NextDialogue"] = 12048213,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120482/1E295320",
            },
        [12048209] = {
            ["Content"] = "你之前对我的利用，我还没能够原谅你。或许之后也不能。",
            ["ContentFR"] = "Je ne t’ai pas encore pardonné de m’avoir utilisé. Peut-être ne le pourrai-je jamais.",
            ["DialogueId"] = 12048209,
            ["GUID"] = "1E29534A",
            ["NextDialogue"] = 12048210,
            ["SpeakNpcId"] = 0,
            ["VoiceName"] = "voice/$Locale$/story/1204/120482/1E29534A",
            },
        [12048210] = {
            ["Content"] = "但是时间总是能够冲刷一切，以后的事情谁也无法断定。所以，让我们把这个问题交给未来吧。",
            ["ContentFR"] = "Mais le temps a le pouvoir d’éroder bien des choses. Laissons cette réponse à l’avenir.",
            ["DialogueId"] = 12048210,
            ["GUID"] = "1E295374",
            ["NextDialogue"] = 12048213,
            ["SpeakNpcId"] = 0,
            ["VoiceName"] = "voice/$Locale$/story/1204/120482/1E295374",
            },
        [12048211] = {
            ["Content"] = "你不是很擅长卜算人心吗？那来猜猜看吧，我究竟有没有原谅你。",
            ["ContentFR"] = "Toi qui te vantes de lire dans le cœur des gens... Alors devine. T’ai-je pardonnée... ou non ?",
            ["DialogueId"] = 12048211,
            ["GUID"] = "1E29539E",
            ["NextDialogue"] = 12048212,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120482/1E29539E",
            },
        [12048212] = {
            ["Content"] = "……呵呵。这是我遇到过最难的卜算，我恐怕要用毕生来寻找这个答案了。",
            ["ContentFR"] = "... Héhé. C’est sans doute la divination la plus difficile qu’il m’ait été donnée d’affronter. Il me faudra peut-être toute une vie pour en trouver la réponse.",
            ["DialogueId"] = 12048212,
            ["GUID"] = "1E2953C8",
            ["NextDialogue"] = 12048213,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120482/1E2953C8",
            },
        [12048213] = {
            ["Content"] = "止流，还有一件事我想告诉你……人心是复杂的。",
            ["ContentFR"] = "Zhiliu... il y a encore quelque chose que je veux te dire. Le cœur humain est complexe.",
            ["DialogueId"] = 12048213,
            ["GUID"] = "1E2953F2",
            ["NextDialogue"] = 12048214,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120482/1E2953F2",
            },
        [12048214] = {
            ["Content"] = "人有懦弱的一面，就有勇敢的一面。有为恶的一面，就有善良的一面。",
            ["ContentFR"] = "L’être humain porte en lui la faiblesse autant que le courage, l’ombre autant que la bonté.",
            ["DialogueId"] = 12048214,
            ["GUID"] = "1E29541C",
            ["NextDialogue"] = 12048215,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120482/1E29541C",
            },
        [12048215] = {
            ["Content"] = "人永远能够挣脱所谓的宿命和计划，创造出新的意外。",
            ["ContentFR"] = "Il peut toujours briser ce que l’on nomme destin ou plan immuable... Et créer un nouvel imprévu.",
            ["DialogueId"] = 12048215,
            ["GUID"] = "1E295446",
            ["NextDialogue"] = 12048216,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120482/1E295446",
            },
        [12048216] = {
            ["Content"] = "所以……你可以试着去更加信任别人，而不是自己背负起一切。",
            ["ContentFR"] = "Alors... essaie de faire davantage confiance aux autres. Ne porte plus tout cela seule.",
            ["DialogueId"] = 12048216,
            ["GUID"] = "1E295470",
            ["NextDialogue"] = 12048217,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120482/1E295470",
            },
        [12048217] = {
            ["Content"] = "从今往后，我不希望你随意将自己的生命作为筹码。活下去，见证华胥的未来，好吗？答应我。",
            ["ContentFR"] = "À l’avenir, je ne veux plus que tu mises ta vie comme une simple pièce. Vis. Reste en vie, et contemple l’avenir de Huaxu. Promets-le-moi.",
            ["DialogueId"] = 12048217,
            ["GUID"] = "1E29549A",
            ["NextDialogue"] = 12048218,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120482/1E29549A",
            },
        [12048218] = {
            ["Content"] = "…………",
            ["ContentFR"] = "...",
            ["DialogueId"] = 12048218,
            ["GUID"] = "1E2954C4",
            ["NextDialogue"] = 12048219,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120482/1E2954C4",
            },
        [12048219] = {
            ["Content"] = "虽然你大概早已不需要我的道谢……但是谢谢你，{nickname}。",
            ["ContentFR"] = "Tu n’as sans doute plus besoin de mes remerciements... Mais malgré tout — merci, {nickname}.",
            ["DialogueId"] = 12048219,
            ["GUID"] = "1E2954EE",
            ["NextDialogue"] = 12048220,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120482/1E2954EE",
            },
        [12048220] = {
            ["Content"] = "在冰湖城偶遇你，大约是命运对我最深的一次眷顾。",
            ["ContentFR"] = "Te rencontrer par hasard à Givrelac... fut peut-être la plus grande bienveillance que le destin m’ait accordée.",
            ["DialogueId"] = 12048220,
            ["GUID"] = "1E295518",
            ["NextDialogue"] = 12048221,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120482/1E295518",
            },
        [12048221] = {
            ["Content"] = "我们到了，陪我上完这柱香吧。",
            ["ContentFR"] = "Nous y sommes. Reste avec moi... le temps que cet encens se consume.",
            ["DialogueId"] = 12048221,
            ["GUID"] = "1E295542",
            ["NextDialogue"] = 12048222,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120482/1E295542",
            },
        [12048222] = {
            ["DialogueId"] = 12048222,
            ["GUID"] = "12048222.0",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12048201.T_Story_Recall_12048201'",
            ["bNotRecall"] = 1,
            },
        [12048223] = {
            ["DialogueId"] = 12048223,
            ["NextDialogue"] = 12048224,
            },
        [12048224] = {
            ["DialogueId"] = 12048224,
            ["NextDialogue"] = 12048201,
            },
        [12048304] = {
            ["Content"] = "你竟能做到如此地步……",
            ["ContentFR"] = "Que tu aies pu aller si loin... je ne l’avais pas prévu.",
            ["DialogueId"] = 12048304,
            ["GUID"] = "1E2962E0",
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120483/1E2962E0",
            },
        [12048305] = {
            ["Content"] = "{nickname}，虽然初次见面时，我便从你身上窥见了潜龙之姿，但你所做的一切，确是连我的算筹都未曾算到的。",
            ["ContentFR"] = "Dès notre première rencontre, j’ai perçu en toi une grandeur encore dissimulée. Mais ce que tu as accompli dépasse même mes calculs.",
            ["DialogueId"] = 12048305,
            ["GUID"] = "1E29630A",
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120483/1E29630A",
            },
        [12048306] = {
            ["Content"] = "怎么样，止流掌柜？现在愿意听进去我说的话了吗？",
            ["ContentFR"] = "Alors, Patronne Zhiliu... prête à m’écouter maintenant ?",
            ["DialogueId"] = 12048306,
            ["GUID"] = "1E296334",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120483/1E296334",
            },
        [12048307] = {
            ["Content"] = "……愿赌服输。",
            ["ContentFR"] = "... Je reconnais ma défaite.",
            ["DialogueId"] = 12048307,
            ["GUID"] = "1E29635E",
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120483/1E29635E",
            },
        [12048308] = {
            ["Content"] = "以和鸣之力干预我与烛阴的契约，借助祭献仪式将力量转移到自己身上，从而争取到使用均天玉律的一线之机……这般冒险的举动，也只有你才能做到了。",
            ["ContentFR"] = "Briser mon pacte avec Zhuyin par la Résonance, détourner l’énergie du sacrifice... pour gagner l’instant nécessaire à l’usage du Jade de l’Équilibre... seul toi pouvais oser un tel pari.",
            ["DialogueId"] = 12048308,
            ["GUID"] = "1E296388",
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120483/1E296388",
            },
        [12048309] = {
            ["Content"] = "但只有这一点还不够。机枢派的那半壁均天玉律，你又是从何处寻得？",
            ["ContentFR"] = "Mais cela ne suffit pas à tout expliquer. La moitié manquante du Jade de l’Équilibre détenue par la Secte Jishu... où l’as-tu trouvée ?",
            ["DialogueId"] = 12048309,
            ["GUID"] = "1E2963B2",
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120483/1E2963B2",
            },
        [12048310] = {
            ["Content"] = "山外山遇袭时，飘零人将我带去偃隐宫底寻找转机，均天玉律是在那里发现的。",
            ["ContentFR"] = "Lorsque les Pics Extérieurs furent attaqués, les Vagabonds m’ont conduit sous le Labyrinthe de Yanyin afin d’y chercher une issue. C’est là que je l’ai découverte.",
            ["DialogueId"] = 12048310,
            ["GUID"] = "1E2963DC",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120483/1E2963DC",
            },
        [12048311] = {
            ["Content"] = "我多年苦寻无果之物，原来藏在那里……也罢。我心中只留有毁灭的决意，这样的物件交由你，才是更好的选择。",
            ["ContentFR"] = "L’objet que je cherchais en vain depuis tant d’années... il reposait là. Soit. Mon cœur ne portait plus que la résolution de tout détruire. Un tel artefact est entre de meilleures mains auprès de toi.",
            ["DialogueId"] = 12048311,
            ["GUID"] = "1E296406",
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120483/1E296406",
            },
        [12048312] = {
            ["Content"] = "止流掌柜，有什么话待会再说吧。前面还有人在等着我们呢。",
            ["ContentFR"] = "Zhiliu... nous en reparlerons plus tard. Quelqu’un nous attend.",
            ["DialogueId"] = 12048312,
            ["GUID"] = "1E296430",
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120483/1E296430",
            },
        [12048313] = {
            ["Content"] = "其实那时在执律阁顶意外抗住太皓的一击……甚至更早之前，从伤及烛阴开始，我就非常意外。与神明交手，这种事情我以前连想都没想过。",
            ["ContentFR"] = "En repensant à ce jour, au sommet du Pavillon de l’Arbitrage... lorsque j’ai encaissé le coup de Taihao... et même plus tôt encore, lorsque j’ai blessé Zhuyin... j’en ai moi-même été surpris. Affronter des dieux... jamais je n’aurais imaginé en être capable.",
            ["DialogueId"] = 12048313,
            ["GUID"] = "12048313.0",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120483/12048313",
            },
        [12048314] = {
            ["Content"] = "是因为……和鸣之力与大风九章创立者的力量系出同源吗？",
            ["ContentFR"] = "Est-ce parce que... la Résonance partage la même origine que la puissance des fondateurs des Neuf Chapitres de Dafeng ?",
            ["DialogueId"] = 12048314,
            ["GUID"] = "12048314.0",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120483/12048314",
            },
        [12048315] = {
            ["Content"] = "不错。大风九章这一术式，从一开始便是为了放大飏的力量而布设。术式的加持，足以让你触及神明。",
            ["ContentFR"] = "En effet. Dès l’origine, les Neuf Chapitres de Dafeng furent conçus comme un vaste rituel destiné à amplifier la puissance de Yang. L’énergie de cette formation suffit à te permettre d’atteindre le domaine des dieux.",
            ["DialogueId"] = 12048315,
            ["GUID"] = "12048315.0",
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120483/12048315",
            },
        [12048401] = {
            ["Content"] = "这是什么不详的东西，不要给我，快拿走！",
            ["ContentFR"] = "Quelle est cette chose funeste ? Reprenez-la !",
            ["DialogueId"] = 12048401,
            ["FacialId"] = {
                [1] = "240067:Cin_Angry01",
                },
            ["GUID"] = "1E2972CA",
            ["SpeakNpcId"] = 240067,
            ["TalkActionId"] = {
                [1] = "240067:Angry01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120484/1E2972CA",
            },
        [12048402] = {
            ["Content"] = "我、我连一只鸡都没有杀过，更别提拿起武器抵抗敌人了……",
            ["ContentFR"] = "Je... je n’ai jamais tué quoi que ce soit... pas même une poule... Comment pourrais-je manier une arme... ?",
            ["DialogueId"] = 12048402,
            ["FacialId"] = {
                [1] = "240068:Cin_Nervous",
                },
            ["GUID"] = "1E2972F4",
            ["SpeakNpcId"] = 240068,
            ["TalkActionId"] = {
                [1] = "240068:Sad02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120484/1E2972F4",
            },
        [12048403] = {
            ["Content"] = "动了武就会触犯天条，这是万万不能拿呀呐！",
            ["ContentFR"] = "Prendre les armes, c’est violer les Préceptes célestes ! Je ne peux accepter cela !",
            ["DialogueId"] = 12048403,
            ["FacialId"] = {
                [1] = "240066:Cin_Angry02",
                },
            ["GUID"] = "1E29731E",
            ["SpeakNpcId"] = 240066,
            ["TalkActionId"] = {
                [1] = "240066:Angry01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120484/1E29731E",
            },
        [12048501] = {
            ["Content"] = "{nickname}，我就知道你能做到！",
            ["ContentFR"] = "{nickname} ! Je savais que tu y arriverais !",
            ["DialogueId"] = 12048501,
            ["FacialId"] = {
                [1] = "240026:Smile02",
                },
            ["GUID"] = "1E298332",
            ["NextDialogue"] = 12048502,
            ["SpeakNpcId"] = 240026,
            ["TalkActionId"] = {
                [1] = "240026:Excited02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120485/1E298332",
            },
        [12048502] = {
            ["Content"] = "白龙神君在前面……祂好像有话想和你说。",
            ["ContentFR"] = "Le Seigneur Dragon d’Argent t’attend devant... Il semble avoir quelque chose à te dire.",
            ["DialogueId"] = 12048502,
            ["FacialId"] = {
                [1] = "240026:None",
                },
            ["GUID"] = "1E29835C",
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120485/1E29835C",
            },
        [12048503] = {
            ["Content"] = "呼，想不到短短一天内发生了这么多事……我平时连做梦也不会梦到这样的景象。",
            ["ContentFR"] = "<I>Pfiou...<I> qui aurait cru qu’en une seule journée il se passerait autant de choses... Même dans mes rêves, je n’aurais jamais imaginé voir un tel spectacle.",
            ["DialogueId"] = 12048503,
            ["FacialId"] = {
                [1] = "240026:Smile01",
                },
            ["GUID"] = "1E298386",
            ["NextDialogue"] = 12048504,
            ["SpeakNpcId"] = 240026,
            ["TalkActionId"] = {
                [1] = "240026:Confident_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120485/1E298386",
            },
        [12048504] = {
            ["Content"] = "之后可要有的忙了。得把大家的陈年案情整理出来，一件件翻案。",
            ["ContentFR"] = "Nous avons du travail devant nous. Il faudra rouvrir les anciens dossiers, un par un.",
            ["DialogueId"] = 12048504,
            ["GUID"] = "1E2983B0",
            ["NextDialogue"] = 12048505,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120485/1E2983B0",
            },
        [12048505] = {
            ["Content"] = "若是见义勇为就既往不咎。当然，要真是有作奸犯科的家伙混进去，那可得让他好好地受罚！",
            ["ContentFR"] = "Ceux qui ont agi pour une juste cause seront pardonnés. Mais les véritables criminels devront répondre de leurs actes.",
            ["DialogueId"] = 12048505,
            ["GUID"] = "1E2983DA",
            ["NextDialogue"] = 12048506,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120485/1E2983DA",
            },
        [12048506] = {
            ["Content"] = "不过……我们平安再见了。{nickname}，这个约定，我们都做到了。",
            ["ContentFR"] = "Et... nous avons tenu notre promesse, {nickname}. Nous nous revoyons sains et saufs.",
            ["DialogueId"] = 12048506,
            ["GUID"] = "1E298404",
            ["SpeakNpcId"] = 240026,
            ["TalkActionId"] = {
                [1] = "240026:AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120485/1E298404",
            },
        [12048507] = {
            ["Content"] = "好样的，{nickname}！",
            ["ContentFR"] = "Pas mal du tout, {nickname} !",
            ["DialogueId"] = 12048507,
            ["FacialId"] = {
                [1] = "240013:Smile02",
                },
            ["GUID"] = "1E29842E",
            ["NextDialogue"] = 12048508,
            ["SpeakNpcId"] = 240013,
            ["TalkActionId"] = {
                [1] = "240013:ConfidentR_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120485/1E29842E",
            },
        [12048508] = {
            ["Content"] = "虽然早知道你是豪侠高手，但没想到你能以一人之力鏖战双龙还不落下风，不亏是我刻舟的{性别：兄弟|挚友}！",
            ["ContentFR"] = "Je savais que tu étais redoutable... mais affronter deux dragons à toi {性别:seul et tenir bon ? Voilà un ami|seule et tenir bon ? Voilà une amie} dont je peux me vanter !",
            ["DialogueId"] = 12048508,
            ["GUID"] = "1E298458",
            ["NextDialogue"] = 12048509,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120485/1E298458",
            },
        [12048509] = {
            ["Content"] = "看得我心痒痒的。之后得闲，我们再找个地方过两招吧！",
            ["ContentFR"] = "Ça m’a donné envie de me battre. Un jour, on se mesurera pour de vrai !",
            ["DialogueId"] = 12048509,
            ["GUID"] = "1E298482",
            ["SpeakNpcId"] = 240013,
            ["TalkActionId"] = {
                [1] = "240013:AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120485/1E298482",
            },
        [12048510] = {
            ["Content"] = "……{nickname}，未想到，你竟能完成如此壮举。",
            ["ContentFR"] = "... {nickname}. Je ne pensais pas te voir accomplir un tel exploit.",
            ["DialogueId"] = 12048510,
            ["FacialId"] = {
                [1] = "240100:Smile01",
                },
            ["GUID"] = "1E2984AC",
            ["NextDialogue"] = 12048511,
            ["SpeakNpcId"] = 240100,
            ["TalkActionId"] = {
                [1] = "240100:Explain01L_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120485/1E2984AC",
            },
        [12048511] = {
            ["Content"] = "我自皈依大风九章后，不过是随波逐流，如风中蓬草。期间所做所为，不乏违心之举。",
            ["ContentFR"] = "Depuis que je me suis voué aux Neuf Chapitres, je n’ai été qu’un brin d’herbe au vent... Il m’est arrivé d’agir contre ma propre conscience.",
            ["DialogueId"] = 12048511,
            ["GUID"] = "1E2984D6",
            ["NextDialogue"] = 12048512,
            ["SpeakNpcId"] = 240100,
            ["VoiceName"] = "voice/$Locale$/story/1204/120485/1E2984D6",
            },
        [12048512] = {
            ["Content"] = "说来惭愧，我本以为世事两难，大风九章不堪之处只能这样忍受过去了。从未想过大风九章竟有修正之法。",
            ["ContentFR"] = "Je croyais leurs défauts immuables, et qu’il ne me restait qu’à les supporter. Jamais je n’aurais imaginé qu’une correction fût possible.",
            ["DialogueId"] = 12048512,
            ["GUID"] = "1E298500",
            ["NextDialogue"] = 12048513,
            ["SpeakNpcId"] = 240100,
            ["TalkActionId"] = {
                [1] = "240100:DisagreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120485/1E298500",
            },
        [12048513] = {
            ["Content"] = "煜明，你打算回山外山看看吗？",
            ["ContentFR"] = "Comptes-tu retourner aux Pics Extérieurs, Yuming ?",
            ["DialogueId"] = 12048513,
            ["GUID"] = "1E29852A",
            ["NextDialogue"] = 12048514,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "240100:Explain01L_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120485/1E29852A",
            },
        [12048514] = {
            ["Content"] = "……我现在心如乱麻，需要一段时间理清头绪。",
            ["ContentFR"] = "... Mon esprit est encore troublé. Il me faudra du temps.",
            ["DialogueId"] = 12048514,
            ["FacialId"] = {
                [1] = "240100:Sad01",
                },
            ["GUID"] = "1E298554",
            ["NextDialogue"] = 12048515,
            ["SpeakNpcId"] = 240100,
            ["TalkActionId"] = {
                [1] = "240100:Sigh_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120485/1E298554",
            },
        [12048515] = {
            ["Content"] = "待我想清之时，或许吧。",
            ["ContentFR"] = "Peut-être... lorsque j’aurai trouvé ma réponse.",
            ["DialogueId"] = 12048515,
            ["GUID"] = "1E29857E",
            ["SpeakNpcId"] = 240100,
            ["VoiceName"] = "voice/$Locale$/story/1204/120485/1E29857E",
            },
        [12048601] = {
            ["Content"] = "演出目前还没有，请等候后续制作",
            ["DialogueId"] = 12048601,
            ["GUID"] = "1E29939A",
            ["VoiceName"] = "voice/$Locale$/story/1204/120486/1E29939A",
            },
        [12048602] = {
            ["Content"] = "玩法目前还没有，请等候后续制作",
            ["DialogueId"] = 12048602,
            ["GUID"] = "1E2993C4",
            ["VoiceName"] = "voice/$Locale$/story/1204/120486/1E2993C4",
            },
        [12048701] = {
            ["Content"] = "小仆从，我已经占好位置啦！你赶紧去买药吧，要快去快回哦。",
            ["ContentFR"] = "Petit larbin ! J’ai gardé la place ! Dépêche-toi d’aller chercher les remèdes, et reviens vite !",
            ["DialogueId"] = 12048701,
            ["FacialId"] = {
                [1] = "200002:Confident01",
                },
            ["GUID"] = "1E29A402",
            ["LookAt"] = {
                [1] = "200002:n(100001)",
                },
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Confident_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120487/1E29A402",
            },
        [12048702] = {
            ["Content"] = "原来如此！只要这样动一点小小的手脚……嘿嘿嘿……",
            ["ContentFR"] = "Ah ! Je comprends ! Il suffit de bidouiller un tout petit peu comme ça.... héhé...",
            ["DialogueId"] = 12048702,
            ["GUID"] = "1E29A42C",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120487/1E29A42C",
            },
        [12048703] = {
            ["Content"] = "干得好，小仆从！",
            ["ContentFR"] = "Bien joué !",
            ["DialogueId"] = 12048703,
            ["GUID"] = "1E29A456",
            ["NextDialogue"] = 12048704,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120487/1E29A456",
            },
        [12048704] = {
            ["Content"] = "这样就暂时不需要担心被它们发现了，还是你的办法多！",
            ["ContentFR"] = "Au moins, ces machines ne nous trahiront pas tout de suite. Tu as toujours un coup d’avance !",
            ["DialogueId"] = 12048704,
            ["GUID"] = "1E29A480",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120487/1E29A480",
            },
        [12048705] = {
            ["Content"] = "弄坏了这么多偃雀，该不会找我们索赔吧……小仆从，我们跑快点。",
            ["ContentFR"] = "On en a saboté pas mal... Ils ne vont pas nous demander réparation, j’espère ? Petit larbin, accélérons un peu.",
            ["DialogueId"] = 12048705,
            ["GUID"] = "1E29A4AA",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120487/1E29A4AA",
            },
        [12048707] = {
            ["Content"] = "哇啊啊啊……涌出来好多应天尉和狴犴，这个突然出现的大罩子又是什么！",
            ["ContentFR"] = "Ouaaah ! Ils arrivent de partout ! Et c’est quoi cette énorme barrière ?!",
            ["DialogueId"] = 12048707,
            ["GUID"] = "1E29A4FE",
            ["NextDialogue"] = 12048708,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120487/1E29A4FE",
            },
        [12048708] = {
            ["Content"] = "来的正好！{nickname}，你去想办法破坏那两座玄俑，我来会会这些刍狗！",
            ["ContentFR"] = "Parfait ! {nickname}, occupe-toi des deux <H>Sentinelles d’obsidienne</> ! Je m’occupe de ces cabots !",
            ["DialogueId"] = 12048708,
            ["GUID"] = "1E29A528",
            ["NextDialogue"] = 12048709,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120487/1E29A528",
            },
        [12048709] = {
            ["Content"] = "被绑了这么久，我刻某人正愁没有地方活动活动筋骨呢！",
            ["ContentFR"] = "Attaché aussi longtemps... j’avais bien besoin de me dégourdir un peu !",
            ["DialogueId"] = 12048709,
            ["GUID"] = "1E29A552",
            ["NextDialogue"] = 12048710,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120487/1E29A552",
            },
        [12048710] = {
            ["Content"] = "这个人的字典里到底有没有害怕这个词啊！",
            ["ContentFR"] = "Le mot « peur », ça existe dans son dictionnaire ?!",
            ["DialogueId"] = 12048710,
            ["GUID"] = "1E29A57C",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120487/1E29A57C",
            },
        [12048712] = {
            ["Content"] = "{nickname}，那座镇律玄俑快要充能完毕了，别让他们得逞！",
            ["ContentFR"] = "{nickname} ! Celle-ci est presque chargée ! Ne les laisse pas l’activer !",
            ["DialogueId"] = 12048712,
            ["GUID"] = "1E29A5D0",
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120487/1E29A5D0",
            },
        [12048713] = {
            ["Content"] = "小仆从，这边的玄俑也不太妙的样子！快想想办法！",
            ["ContentFR"] = "Petit larbin, celle-ci aussi devient critique ! Dépêche-toi !",
            ["DialogueId"] = 12048713,
            ["GUID"] = "1E29A5FA",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120487/1E29A5FA",
            },
        [12048714] = {
            ["Content"] = "干得好！就这样一鼓作气，把另一座玄俑也解决掉吧！",
            ["ContentFR"] = "Bien joué ! Finissons l’autre dans la foulée !",
            ["DialogueId"] = 12048714,
            ["GUID"] = "1E29A624",
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120487/1E29A624",
            },
        [12048716] = {
            ["Content"] = "完了完了，突然冒出来好多追兵跟在我们屁股后面……",
            ["ContentFR"] = "On est fichus, on est fichus ! Il y a une armée entière qui nous colle aux talons !",
            ["DialogueId"] = 12048716,
            ["GUID"] = "1E29A678",
            ["NextDialogue"] = 12048717,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120487/1E29A678",
            },
        [12048717] = {
            ["Content"] = "你不觉得他们那追又追不上的咬牙切齿的表情，欣赏起来别有一番乐趣吗？",
            ["ContentFR"] = "Tu ne trouves pas que leurs mines crispées, à courir sans jamais nous rattraper... ont quelque chose d’assez savoureux ?",
            ["DialogueId"] = 12048717,
            ["GUID"] = "1E29A6A2",
            ["NextDialogue"] = 12048718,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120487/1E29A6A2",
            },
        [12048718] = {
            ["Content"] = "我、我才没有这种闲工夫——小仆从，我们跑快点！",
            ["ContentFR"] = "Je— je n’ai pas le loisir d’admirer ce genre de choses ! Petit larbin, plus vite !",
            ["DialogueId"] = 12048718,
            ["GUID"] = "1E29A6CC",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120487/1E29A6CC",
            },
        [12048720] = {
            ["Content"] = "哼哼……坏鸟，汝等克星已至，还不快速速来降！",
            ["ContentFR"] = "<I>Hmpf...</> Oiseaux maléfiques ! Votre némésis est arrivée ! Rendez-vous sur-le-champ !",
            ["DialogueId"] = 12048720,
            ["GUID"] = "1E29A720",
            ["NextDialogue"] = 12048721,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120487/1E29A720",
            },
        [12048721] = {
            ["Content"] = "……白，你这又是从哪里学来的台词？鸟又听不懂你说话。",
            ["ContentFR"] = "... Snow, tu l’as sortie d’où, celle-là ? Les oiseaux ne comprennent pas ce que tu racontes.",
            ["DialogueId"] = 12048721,
            ["GUID"] = "1E29A74A",
            ["NextDialogue"] = 12048722,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120487/1E29A74A",
            },
        [12048722] = {
            ["Content"] = "诶嘿嘿，是刚刚听到有人在念“话本”，台词还挺威风的。被你听出来啦？",
            ["ContentFR"] = "Héhéhé ! J’ai entendu quelqu’un réciter un « récit » tout à l’heure. Les répliques étaient trop classe. Tu m’as démasquée ?",
            ["DialogueId"] = 12048722,
            ["GUID"] = "1E29A774",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120487/1E29A774",
            },
        [12048724] = {
            ["Content"] = "…………",
            ["ContentFR"] = "...",
            ["DialogueId"] = 12048724,
            ["GUID"] = "1E29A7C8",
            ["NextDialogue"] = 12048725,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120487/1E29A7C8",
            },
        [12048725] = {
            ["Content"] = "苏乙，怎么了？你是在担心他们吗？",
            ["ContentFR"] = "Su Yi ? Tu t’inquiètes pour eux ?",
            ["DialogueId"] = 12048725,
            ["GUID"] = "1E29A7F2",
            ["NextDialogue"] = 12048726,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120487/1E29A7F2",
            },
        [12048726] = {
            ["Content"] = "嗯……我在想这里能不能找到我要的东西，会不会只是无用功。",
            ["ContentFR"] = "Oui... Je me demande si ce que je cherche est vraiment ici... ou si tout cela n’est qu’une perte de temps.",
            ["DialogueId"] = 12048726,
            ["GUID"] = "1E29A81C",
            ["NextDialogue"] = 12048727,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120487/1E29A81C",
            },
        [12048727] = {
            ["Content"] = "但开弓没有回头箭。一旦下定决心，就要摈除杂念，全力以赴，这是姑姑教我的。",
            ["ContentFR"] = "Mais une flèche décochée ne revient pas. Une fois la décision prise, il faut chasser les doutes et avancer. C’est ce que ma tante m’a appris.",
            ["DialogueId"] = 12048727,
            ["GUID"] = "1E29A846",
            ["NextDialogue"] = 12048728,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120487/1E29A846",
            },
        [12048728] = {
            ["Content"] = "好。那让我们一起全力以赴吧！",
            ["ContentFR"] = "Alors allons-y. Ensemble, à fond.",
            ["DialogueId"] = 12048728,
            ["GUID"] = "1E29A870",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120487/1E29A870",
            },
        [12048730] = {
            ["Content"] = "这里的重力有点蹊跷……这也是机枢派先人的手笔吗？",
            ["ContentFR"] = "La gravité ici est étrange... Serait-ce encore l’œuvre des anciens de la Secte Jishu ?",
            ["DialogueId"] = 12048730,
            ["GUID"] = "1E29A8C4",
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120487/1E29A8C4",
            },
        [12048732] = {
            ["Content"] = "{nickname}，看到平台两旁的隼型机枢巨炮了吗？那就是神机铳！",
            ["ContentFR"] = "{nickname}, tu vois les deux énormes canons Jishu en forme de faucon, de chaque côté de la plateforme ? C’est le Canon Céleste Mécanique !",
            ["DialogueId"] = 12048732,
            ["GUID"] = "1E29A918",
            ["NextDialogue"] = 12048733,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120487/1E29A918",
            },
        [12048733] = {
            ["Content"] = "只要用却邪为它指明方位，神机铳就能提供从空中倾泻而下的火力支援！",
            ["ContentFR"] = "Il suffit d’utiliser le Fléau des Souillures pour lui indiquer une cible... et le Canon Céleste Mécanique fera pleuvoir le feu depuis les airs !",
            ["DialogueId"] = 12048733,
            ["GUID"] = "1E29A942",
            ["NextDialogue"] = 12048734,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120487/1E29A942",
            },
        [12048734] = {
            ["Content"] = "现在，好好感受炮火的威力吧！",
            ["ContentFR"] = "Maintenant... ressens la puissance de l’artillerie !",
            ["DialogueId"] = 12048734,
            ["GUID"] = "1E29A96C",
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120487/1E29A96C",
            },
        [12048736] = {
            ["Content"] = "爽快，实在爽快——",
            ["ContentFR"] = "Ahh ! Ça, c’est grisant !",
            ["DialogueId"] = 12048736,
            ["GUID"] = "1E29A9C0",
            ["NextDialogue"] = 12048737,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120487/1E29A9C0",
            },
        [12048737] = {
            ["Content"] = "你们从何处寻来这巨炮的启动方式？简直是天降奇兵啊！",
            ["ContentFR"] = "Vous avez trouvé comment réveiller un monstre pareil ? C’est carrément un miracle tombé du ciel !",
            ["DialogueId"] = 12048737,
            ["GUID"] = "1E29A9EA",
            ["NextDialogue"] = 12048738,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120487/1E29A9EA",
            },
        [12048738] = {
            ["Content"] = "有了它的支援，看我不把对面打个落花流水……哎哟！",
            ["ContentFR"] = "Avec ça, je vais les pulvériser... — Aïe !",
            ["DialogueId"] = 12048738,
            ["GUID"] = "1E29AA14",
            ["NextDialogue"] = 12048739,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120487/1E29AA14",
            },
        [12048739] = {
            ["Content"] = "……无聊至极！胜负未定，说这些大话还为时尚早。",
            ["ContentFR"] = "... Ridicule. Rien n’est encore décidé. Tes bravades sont prématurées.",
            ["DialogueId"] = 12048739,
            ["GUID"] = "1E29AA3E",
            ["NextDialogue"] = 12048740,
            ["SpeakNpcId"] = 240100,
            ["VoiceName"] = "voice/$Locale$/story/1204/120487/1E29AA3E",
            },
        [12048740] = {
            ["Content"] = "好啊，那就让我先打倒你再说！",
            ["ContentFR"] = "Très bien ! Alors je commence par toi !",
            ["DialogueId"] = 12048740,
            ["GUID"] = "1E29AA68",
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120487/1E29AA68",
            },
        [12048742] = {
            ["Content"] = "止流，既然你一心求死，就休怪我们不留情面！",
            ["ContentFR"] = "Puisque tu cherches la mort avec tant d’ardeur, ne nous reproche pas notre absence de clémence !",
            ["DialogueId"] = 12048742,
            ["GUID"] = "1E29AABC",
            ["NextDialogue"] = 12048743,
            ["SpeakNpcId"] = 240072,
            ["VoiceName"] = "voice/$Locale$/story/1204/120487/1E29AABC",
            },
        [12048743] = {
            ["Content"] = "妄图以一人之力对抗大风九章，愚蠢！愚蠢至极！",
            ["ContentFR"] = "Prétendre affronter seule les Neuf Chapitres de Dafeng — folie ! Folie absolue !",
            ["DialogueId"] = 12048743,
            ["GUID"] = "1E29AAE6",
            ["NextDialogue"] = 12048744,
            ["SpeakNpcId"] = 240073,
            ["VoiceName"] = "voice/$Locale$/story/1204/120487/1E29AAE6",
            },
        [12048744] = {
            ["Content"] = "住手吧，止流！你是聪明人，何必挑起一场双输的斗争！",
            ["ContentFR"] = "Cesse cela, Zhiliu ! Tu es intelligente — pourquoi provoquer une lutte où tous perdront ?",
            ["DialogueId"] = 12048744,
            ["GUID"] = "1E29AB10",
            ["NextDialogue"] = 12048745,
            ["SpeakNpcId"] = 240074,
            ["VoiceName"] = "voice/$Locale$/story/1204/120487/1E29AB10",
            },
        [12048745] = {
            ["Content"] = "……冥顽不灵！",
            ["ContentFR"] = "... Entêtement aveugle !",
            ["DialogueId"] = 12048745,
            ["GUID"] = "1E29AB3A",
            ["NextDialogue"] = 12048746,
            ["SpeakNpcId"] = 240075,
            ["VoiceName"] = "voice/$Locale$/story/1204/120487/1E29AB3A",
            },
        [12048746] = {
            ["Content"] = "呵呵……很快，一切就要结束了。",
            ["ContentFR"] = "... Encore un instant. Et tout prendra fin.",
            ["DialogueId"] = 12048746,
            ["GUID"] = "1E29AB64",
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120487/1E29AB64",
            },
        [12048748] = {
            ["Content"] = "小、小仆从，天色像世界末日一样……有种不详的感觉……",
            ["ContentFR"] = "P-Petit larbin... le ciel est rouge comme à la fin du monde... j’ai un très mauvais pressentiment...",
            ["DialogueId"] = 12048748,
            ["GUID"] = "1E29ABB8",
            ["NextDialogue"] = 12048749,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120487/1E29ABB8",
            },
        [12048749] = {
            ["Content"] = "加快脚步……一定还来得及！",
            ["ContentFR"] = "Dépêchons-nous... il est encore temps !",
            ["DialogueId"] = 12048749,
            ["GUID"] = "1E29ABE2",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120487/1E29ABE2",
            },
        [12048751] = {
            ["Content"] = "异样感似乎还在隐隐跳动，先走吧……",
            ["DialogueId"] = 12048751,
            ["Duration"] = 7,
            ["SpeakNpcId"] = 100001,
            },
        [12048801] = {
            ["DialogueId"] = 12048801,
            },
        [12048802] = {
            ["Content"] = "咦，小仆从……重力好像恢复正常了？",
            ["DialogueId"] = 12048802,
            ["SpeakNpcId"] = 100001,
            },
        [12049001] = {
            ["Content"] = "小仆从，你回来了！这里这里。",
            ["ContentFR"] = "Petit larbin ! Par ici !",
            ["DialogueId"] = 12049001,
            ["GUID"] = "1E29D53A",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29D53A",
            },
        [12049002] = {
            ["Content"] = "哇，这就是执律阁吗？果然非常厉害！",
            ["ContentFR"] = "Ouah... C’est donc ça, le Pavillon de l’Arbitrage ?! Il est encore plus impressionnant que je l’imaginais !",
            ["DialogueId"] = 12049002,
            ["GUID"] = "1E29D564",
            ["NextDialogue"] = 12049003,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29D564",
            },
        [12049003] = {
            ["Content"] = "小仆从，你说，站在那么高的地方，是不是能把地面上的东西看得一清二楚？我已经迫不及待了！",
            ["ContentFR"] = "Petit larbin, dis-moi... depuis une hauteur pareille, on doit voir le moindre détail au sol, non ? J’ai déjà hâte d’y monter !",
            ["DialogueId"] = 12049003,
            ["GUID"] = "1E29D58E",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29D58E",
            },
        [12049004] = {
            ["Content"] = "南边……嗯，就是这个方向。这张地图我完全看懂啦。",
            ["ContentFR"] = "Le sud... oui, par ici ! Cette carte est limpide comme de l’eau claire !",
            ["DialogueId"] = 12049004,
            ["GUID"] = "1E29D5B8",
            ["NextDialogue"] = 12049005,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29D5B8",
            },
        [12049005] = {
            ["Content"] = "小仆从，你就跟着我走吧。接下来请尽情享受白魔王大人的导、导、导航服服服务。",
            ["ContentFR"] = "Petit larbin, contente-toi de me suivre. Activation du service de gui—gui—guidage suprême du Roi Démon !",
            ["DialogueId"] = 12049005,
            ["GUID"] = "1E29D5E2",
            ["NextDialogue"] = 12049006,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29D5E2",
            },
        [12049006] = {
            ["Content"] = "……白，你说什么？",
            ["ContentFR"] = "... Snow ? Qu’est-ce que tu viens de dire ?",
            ["DialogueId"] = 12049006,
            ["GUID"] = "1E29D60C",
            ["NextDialogue"] = 12049007,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29D60C",
            },
        [12049007] = {
            ["Content"] = "嗯？我说沿着这条路一直往前面走，有什么不对吗？难道白带错了路？",
            ["ContentFR"] = "Hein ? J’ai dit qu’il fallait continuer tout droit. Pourquoi ? Je me suis trompée ?",
            ["DialogueId"] = 12049007,
            ["GUID"] = "1E29D636",
            ["NextDialogue"] = 12049008,
            ["SpeakNpcId"] = 200001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29D636",
            },
        [12049008] = {
            ["Content"] = "（刚刚那是怎么回事？）",
            ["ContentFR"] = "<I>Qu’est-ce que c’était, à l’instant... ?</>",
            ["DialogueId"] = 12049008,
            ["GUID"] = "1E29D660",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29D660",
            },
        [12049009] = {
            ["Content"] = "小仆从，那个人看起来像是管事的，我们去找他问问看吧！",
            ["ContentFR"] = "Petit larbin, cette personne là-bas a l’air responsable. Allons lui parler !",
            ["DialogueId"] = 12049009,
            ["GUID"] = "1E29D68A",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29D68A",
            },
        [12049010] = {
            ["Content"] = "哎，小仆从，头顶上是不是有什么亮晶晶的东西飞过去了？",
            ["ContentFR"] = "Petit larbin... tu as vu ? Quelque chose de brillant a traversé le ciel...",
            ["DialogueId"] = 12049010,
            ["GUID"] = "1E29D6B4",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29D6B4",
            },
        [12049011] = {
            ["Content"] = "一、一下子穿墙而过，还有点晕乎乎的……",
            ["ContentFR"] = "I-Il a traversé le mur... ça donne presque le vertige...",
            ["DialogueId"] = 12049011,
            ["GUID"] = "1E29D6DE",
            ["NextDialogue"] = 12049012,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29D6DE",
            },
        [12049012] = {
            ["Content"] = "无由生在往那个方向跑，小仆从，我们赶紧跟上去！",
            ["ContentFR"] = "Il file par là ! Dépêche-toi !",
            ["DialogueId"] = 12049012,
            ["GUID"] = "1E29D708",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29D708",
            },
        [12049013] = {
            ["Content"] = "无由生消失了……它肯定又附身在什么东西上了！一切都瞒不过英明神武的白魔王和小仆从的眼睛！",
            ["ContentFR"] = "Il s’est volatilisé... Il a dû se cacher dans quelque chose ! Mais rien n’échappe aux yeux perçants du Roi Démon et de son fidèle petit larbin !",
            ["DialogueId"] = 12049013,
            ["GUID"] = "1E29D732",
            ["NextDialogue"] = 12049301,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29D732",
            },
        [12049014] = {
            ["Content"] = "哼哼，逮住你了。",
            ["ContentFR"] = "Ha ! Je t’ai trouvé !",
            ["DialogueId"] = 12049014,
            ["GUID"] = "1E29D75C",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29D75C",
            },
        [12049015] = {
            ["Content"] = "还想跑？！",
            ["ContentFR"] = "Tu crois pouvoir fuir ?!",
            ["DialogueId"] = 12049015,
            ["GUID"] = "1E29D786",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29D786",
            },
        [12049016] = {
            ["Content"] = "真是的，不知不觉跑了好多路，都搞不清楚这里是哪里了。",
            ["ContentFR"] = "On a couru partout... Je ne sais même plus où on est.",
            ["DialogueId"] = 12049016,
            ["GUID"] = "1E29D7B0",
            ["NextDialogue"] = 12049017,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29D7B0",
            },
        [12049017] = {
            ["Content"] = "让我看看地图……嗯，白完全明白了！小仆从，我们赶紧出发去下一个地方吧！",
            ["ContentFR"] = "Voyons la carte... Parfait ! Petit larbin, en route pour la prochaine étape !",
            ["DialogueId"] = 12049017,
            ["GUID"] = "1E29D7DA",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29D7DA",
            },
        [12049018] = {
            ["Content"] = "这个大炉子好气派！还有这么多人进进出出，这里一定就是祀烟阁了！",
            ["ContentFR"] = "Quel énorme brûle-encens ! Et tout ce monde qui entre et sort... Ça doit être le Pavillon de l’Encens !",
            ["DialogueId"] = 12049018,
            ["GUID"] = "1E29D804",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29D804",
            },
        [12049019] = {
            ["Content"] = "这里的屋顶上也有亮晶晶的尘漠耶……",
            ["ContentFR"] = "Oh ! Il y a aussi de la Poussière-corrompue scintillante sur ces toits...",
            ["DialogueId"] = 12049019,
            ["GUID"] = "1E29D82E",
            ["NextDialogue"] = 12049020,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29D82E",
            },
        [12049020] = {
            ["Content"] = "香囊是不是掉在了这些尘漠堆里呢？小仆从，我们找找看吧！",
            ["ContentFR"] = "Tu crois que le sachet est tombé dans l’un de ces amas ? Petit larbin, cherchons bien !",
            ["DialogueId"] = 12049020,
            ["GUID"] = "1E29D858",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29D858",
            },
        [12049021] = {
            ["Content"] = "好啦，就剩下匠矩阁的东西还没有拿到手了。就在祀烟阁对面，小仆从，我们走！",
            ["ContentFR"] = "Parfait ! Il ne reste plus que le Pavillon des Artisans. C’est juste en face. Allons-y, petit larbin !",
            ["DialogueId"] = 12049021,
            ["GUID"] = "1E29D882",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29D882",
            },
        [12049022] = {
            ["Content"] = "哇，告示板前已经聚集了好多人，我们也过去看看！",
            ["ContentFR"] = "Ouah ! Il y a déjà foule devant le panneau ! Allons voir !",
            ["DialogueId"] = 12049022,
            ["GUID"] = "1E29D8AC",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29D8AC",
            },
        [12049023] = {
            ["Content"] = "来来回回都是这些蠢狼，我都杀腻了！",
            ["ContentFR"] = "Encore ces cabots écervelés... J’en ai presque assez de les découper.",
            ["DialogueId"] = 12049023,
            ["GUID"] = "1E29D8D6",
            ["NextDialogue"] = 12049024,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29D8D6",
            },
        [12049024] = {
            ["Content"] = "喂，躲在后面的应天尉！你能听清我这把剑在说什么吗？",
            ["ContentFR"] = "Hé ! Toi, le Magistrat de Yingtian, planqué derrière tes chiens ! Tu entends ce que dit mon épée ?",
            ["DialogueId"] = 12049024,
            ["GUID"] = "1E29D900",
            ["NextDialogue"] = 12049025,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29D900",
            },
        [12049025] = {
            ["Content"] = "它在说无聊，无趣，不过尔尔！",
            ["ContentFR"] = "Elle dit : ennuyeux. Sans intérêt. Rien d’exceptionnel.",
            ["DialogueId"] = 12049025,
            ["GUID"] = "1E29D92A",
            ["NextDialogue"] = 12049026,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29D92A",
            },
        [12049026] = {
            ["Content"] = "没想到你们这些刍狗，连正面对决的骨气都没有！可真让剑兄感到腻味啊！",
            ["ContentFR"] = "Je vous croyais capables d’un affrontement digne de ce nom... Vous décevez même mon vieux compagnon d’acier.",
            ["DialogueId"] = 12049026,
            ["GUID"] = "1E29D954",
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29D954",
            },
        [12049027] = {
            ["Content"] = "咚——咚——咚——咚——",
            ["ContentFR"] = "<I>Dong—— Dong—— Dong—— Dong——</>",
            ["DialogueId"] = 12049027,
            ["GUID"] = "1E29D97E",
            ["NextDialogue"] = 12049028,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29D97E",
            },
        [12049028] = {
            ["Content"] = "时间马上就要到了，小仆从，我们赶紧出发吧！",
            ["ContentFR"] = "C’est l’heure ! Petit larbin, en route !",
            ["DialogueId"] = 12049028,
            ["GUID"] = "1E29D9A8",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29D9A8",
            },
        [12049029] = {
            ["Content"] = "小仆从，那里看起来比较像是通往顶层的出口。",
            ["ContentFR"] = "Petit larbin, cette sortie semble mener vers l’étage supérieur.",
            ["DialogueId"] = 12049029,
            ["GUID"] = "1E29D9D2",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29D9D2",
            },
        [12049030] = {
            ["Content"] = "小仆从，原来你还有机械修理的天赋！我们这机枢派荣誉学徒的名号，真不是盖的。",
            ["ContentFR"] = "Petit larbin... je ne savais pas que tu avais un tel talent pour la mécanique ! Notre titre d’{性别:Apprenti|Apprentie} d’honneur de la Secte Jishu n’était donc pas usurpé !",
            ["DialogueId"] = 12049030,
            ["GUID"] = "1E29D9FC",
            ["NextDialogue"] = 12049031,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29D9FC",
            },
        [12049031] = {
            ["Content"] = "也只是试试，没想到今天运气这么好。",
            ["ContentFR"] = "J’ai {性别:improvisé|improvisée}... Nous avons simplement eu la chance de notre côté.",
            ["DialogueId"] = 12049031,
            ["GUID"] = "1E29DA26",
            ["NextDialogue"] = 12049032,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29DA26",
            },
        [12049032] = {
            ["Content"] = "希望好运气可以保佑我们一路顺顺利利，可别出什么突发事件啊——",
            ["ContentFR"] = "Espérons qu’elle ne nous quitte pas. Ce serait dommage qu’un imprévu surgisse maintenant...",
            ["DialogueId"] = 12049032,
            ["GUID"] = "1E29DA50",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29DA50",
            },
        [12049033] = {
            ["Content"] = "{nickname}，此时无需恋战，走为上计！",
            ["ContentFR"] = "{nickname}, inutile de s’attarder ! On se replie !",
            ["DialogueId"] = 12049033,
            ["GUID"] = "1E29DA7A",
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29DA7A",
            },
        [12049034] = {
            ["Content"] = "怎么办，四面八方都被他们堵住了……",
            ["ContentFR"] = "Ils nous encerclent... On est coincés !",
            ["DialogueId"] = 12049034,
            ["GUID"] = "1E29DAA4",
            ["NextDialogue"] = 12049035,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29DAA4",
            },
        [12049035] = {
            ["Content"] = "上天入地，无拘无束，好不逍遥～",
            ["ContentFR"] = "Monter au ciel, plonger sous terre — libre comme le vent~ !",
            ["DialogueId"] = 12049035,
            ["GUID"] = "1E29DACE",
            ["NextDialogue"] = 12049036,
            ["SpeakNpcName"] = "UI_Npc_Name_XiaoYaoShengWenHao",
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29DACE",
            },
        [12049036] = {
            ["Content"] = "哇！怎么是你！",
            ["ContentFR"] = "Quoi ?! Toi ?!",
            ["DialogueId"] = 12049036,
            ["GUID"] = "1E29DAF8",
            ["NextDialogue"] = 12049037,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29DAF8",
            },
        [12049037] = {
            ["Content"] = "哈哈！行至山穷水尽，必有柳暗花明，正是适合我逍遥生登场之时～",
            ["ContentFR"] = "Haha ! Quand toute issue semble close, une éclaircie apparaît~ Et voilà Xiaoyao !",
            ["DialogueId"] = 12049037,
            ["GUID"] = "1E29DB22",
            ["NextDialogue"] = 12049038,
            ["SpeakNpcId"] = 240028,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29DB22",
            },
        [12049038] = {
            ["Content"] = "若想求一线生机，就跟上来吧～",
            ["ContentFR"] = "Si vous voulez une chance de survie — suivez-moi~ !",
            ["DialogueId"] = 12049038,
            ["GUID"] = "1E29DB4C",
            ["SpeakNpcId"] = 240028,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29DB4C",
            },
        [12049039] = {
            ["Content"] = "下面黑压压一片都是追兵……我们只能先跟着这家伙走了。",
            ["ContentFR"] = "En bas, c’est noir de monde... des poursuivants partout. Bon... on n’a pas le choix, il faut suivre ce type !",
            ["DialogueId"] = 12049039,
            ["GUID"] = "1E29DB76",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29DB76",
            },
        [12049040] = {
            ["Content"] = "虽然这个什么逍遥生十分可恶！但不得不说，它的能力在这种时候还真能派上用场。",
            ["ContentFR"] = "Franchement, ce Xiaoyao est insupportable ! Mais... je dois reconnaître qu’en situation critique, ses tours ne sont pas inutiles.",
            ["DialogueId"] = 12049040,
            ["GUID"] = "1E29DBA0",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29DBA0",
            },
        [12049041] = {
            ["Content"] = "绝处必得逢生路，江湖有友来相助，不愧是我替天行道刻舟刻某人的运气！",
            ["ContentFR"] = "Coincé jusqu’au cou... et voilà qu’un camarade surgit à la rescousse ! Ha ! Il faut croire que la chance accompagne toujours ceux qui agissent au nom du Ciel.",
            ["DialogueId"] = 12049041,
            ["GUID"] = "1E29DBCA",
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29DBCA",
            },
        [12049042] = {
            ["Content"] = "前方……是死胡同，没有路了！",
            ["ContentFR"] = "Devant... c’est une impasse. On ne peut pas aller plus loin !",
            ["DialogueId"] = 12049042,
            ["GUID"] = "1E29DBF4",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29DBF4",
            },
        [12049043] = {
            ["Content"] = "兀那贼人，逮住你了！",
            ["ContentFR"] = "Bandits ! Vous êtes cernés !",
            ["DialogueId"] = 12049043,
            ["GUID"] = "1E29DC1E",
            ["SpeakNpcId"] = 240014,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29DC1E",
            },
        [12049044] = {
            ["Content"] = "我想起来了……烛阴之战结束后，止流在山脚迷昏了我，然后把我带到了这里……",
            ["ContentFR"] = "Je me souviens... Après la bataille contre Zhuyin, au pied de la montagne... Zhiliu m’a assommé... puis amené ici...",
            ["DialogueId"] = 12049044,
            ["GUID"] = "1E29DC48",
            ["NextDialogue"] = 12049045,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29DC48",
            },
        [12049045] = {
            ["Content"] = "这些……又是什么？",
            ["ContentFR"] = "Et ces choses... qu’est-ce que c’est ?",
            ["DialogueId"] = 12049045,
            ["GUID"] = "1E29DC72",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29DC72",
            },
        [12049046] = {
            ["Content"] = "追兵已经被引走了，但仍不可过于大意。",
            ["ContentFR"] = "Les poursuivants ont été détournés... mais ne relâchons pas notre vigilance.",
            ["DialogueId"] = 12049046,
            ["GUID"] = "1E29DC9C",
            ["NextDialogue"] = 12049047,
            ["SpeakNpcId"] = 240002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29DC9C",
            },
        [12049047] = {
            ["Content"] = "{nickname}，按照先前所约定的，一边寻找沿途的暗号，一边谨慎前进吧。",
            ["ContentFR"] = "{nickname}, comme convenu, avançons prudemment tout en repérant les signes le long du chemin.",
            ["DialogueId"] = 12049047,
            ["GUID"] = "1E29DCC6",
            ["SpeakNpcId"] = 240002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29DCC6",
            },
        [12049048] = {
            ["Content"] = "那块大石头上的涂鸦，一定是刻舟说的那什么暗号了吧。",
            ["ContentFR"] = "Ce gribouillage sur le gros rocher... c’est forcément le truc dont Kezhou parlait, non ?",
            ["DialogueId"] = 12049048,
            ["GUID"] = "1E29DCF0",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29DCF0",
            },
        [12049049] = {
            ["Content"] = "是秽兽……{nickname}，注意安全，我来护你左右。",
            ["ContentFR"] = "Des Souillés... {nickname}, reste sur tes gardes. Je te couvre.",
            ["DialogueId"] = 12049049,
            ["GUID"] = "1E29DD1A",
            ["SpeakNpcId"] = 240002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29DD1A",
            },
        [12049050] = {
            ["Content"] = "咦，这里怎么有人等着，难不成是派来接应我们的？",
            ["ContentFR"] = "Hein ? Quelqu’un nous attend ici... Ce serait notre contact ?",
            ["DialogueId"] = 12049050,
            ["GUID"] = "1E29DD44",
            ["NextDialogue"] = 12049051,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29DD44",
            },
        [12049051] = {
            ["Content"] = "但她看着也不像是刻舟的姑奶奶啊……不管了，向她打听一下吧！",
            ["ContentFR"] = "Mais elle n’a pas du tout l’air d’être la « grande-tante » de Kezhou... Tant pis, allons lui demander !",
            ["DialogueId"] = 12049051,
            ["GUID"] = "1E29DD6E",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29DD6E",
            },
        [12049052] = {
            ["Content"] = "这个机关白认得！",
            ["ContentFR"] = "Je reconnais ce mécanisme !",
            ["DialogueId"] = 12049052,
            ["GUID"] = "1E29DD98",
            ["NextDialogue"] = 12049053,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29DD98",
            },
        [12049053] = {
            ["Content"] = "我懂的，这就是所谓的考验啊试炼啊什么的……看我们轻松解决。上吧，小仆从！",
            ["ContentFR"] = "Je vois, je vois : une épreuve, un test, ce genre de chose... On va régler ça en deux temps trois mouvements. À toi, Petit larbin !",
            ["DialogueId"] = 12049053,
            ["GUID"] = "1E29DDC2",
            ["NextDialogue"] = 12049054,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29DDC2",
            },
        [12049054] = {
            ["Content"] = "呵呵，很有干劲呢。",
            ["ContentFR"] = "Haha... quelle ardeur.",
            ["DialogueId"] = 12049054,
            ["GUID"] = "1E29DDEC",
            ["SpeakNpcId"] = 240002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29DDEC",
            },
        [12049055] = {
            ["Content"] = "呼，终于找到了，这个暗号动作藏得也太深了……一路上翻山越岭的。",
            ["ContentFR"] = "<I>Pfiou</>... enfin ! Ce signal était caché beaucoup trop loin... On a escaladé des montagnes pour ça !",
            ["DialogueId"] = 12049055,
            ["GUID"] = "1E29DE16",
            ["NextDialogue"] = 12049056,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29DE16",
            },
        [12049056] = {
            ["Content"] = "既然接头暗号已经到手，事不宜迟，我们回去找那位接应人吧。",
            ["ContentFR"] = "À présent que nous avons le signal, ne traînons pas. Retournons voir notre contact.",
            ["DialogueId"] = 12049056,
            ["GUID"] = "1E29DE40",
            ["SpeakNpcId"] = 240002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29DE40",
            },
        [12049057] = {
            ["Content"] = "是对着她做出刚刚找到的那个动作，对吧？本魔王的记忆力可是很好的！",
            ["ContentFR"] = "Bon... c’est juste devant elle qu’on fait le signal, c’est ça ? La mémoire du Roi Démon, c’est du solide !",
            ["DialogueId"] = 12049057,
            ["GUID"] = "1E29DE6A",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29DE6A",
            },
        [12049058] = {
            ["Content"] = "我们到啦——这里就是山外山！",
            ["ContentFR"] = "Et voilà — les Pics Extérieurs !",
            ["DialogueId"] = 12049058,
            ["GUID"] = "1E29DE94",
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29DE94",
            },
        [12049059] = {
            ["Content"] = "哇，这里竟然是建在悬崖上的……我说，你们平时走路万一不小心掉下去该怎么办？",
            ["ContentFR"] = "Ouah... c’est construit sur une falaise ?! Et si quelqu’un glisse et tombe, vous faites quoi ?!",
            ["DialogueId"] = 12049059,
            ["GUID"] = "1E29DEBE",
            ["NextDialogue"] = 12049060,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29DEBE",
            },
        [12049060] = {
            ["Content"] = "白，你要是害怕了，就离我近一点。",
            ["ContentFR"] = "Snow, si tu as peur, reste près de moi.",
            ["DialogueId"] = 12049060,
            ["GUID"] = "1E29DEE8",
            ["NextDialogue"] = 12049061,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29DEE8",
            },
        [12049061] = {
            ["Content"] = "谁谁谁谁害怕了，魔王大人才不会恐高呢。小仆从你可不要乱说……",
            ["ContentFR"] = "Q-Qu-qui a peur ?! Le Roi Démon n’a pas le vertige ! Petit larbin, n’invente pas n’importe quoi...",
            ["DialogueId"] = 12049061,
            ["GUID"] = "1E29DF12",
            ["NextDialogue"] = 12049062,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29DF12",
            },
        [12049062] = {
            ["Content"] = "嘻嘻，我在这里住了这么久，早就习惯了。就算真掉下去了，也会有牵机鸢接住你们的。所以不用担心！",
            ["ContentFR"] = "Héhé. J’habite ici depuis longtemps, je m’y suis faite. Et si quelqu’un tombe vraiment, les cerfs-volants mécaniques l’attraperont. Donc pas d’inquiétude !",
            ["DialogueId"] = 12049062,
            ["GUID"] = "1E29DF3C",
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29DF3C",
            },
        [12049063] = {
            ["Content"] = "你们跟着我来吧！这也是个带你们参观山外山的好机会。",
            ["ContentFR"] = "Suivez-moi. Tant qu’à faire, ce sera l’occasion de vous faire visiter les Pics Extérieurs.",
            ["DialogueId"] = 12049063,
            ["GUID"] = "1E29DF66",
            ["NextDialogue"] = 12049064,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29DF66",
            },
        [12049064] = {
            ["Content"] = "唐叔最近腿摔伤了，我想去采些药草给他敷上，让他能快点好起来。",
            ["ContentFR"] = "Oncle Tang s’est blessé à la jambe en tombant. Je vais cueillir des herbes pour lui en appliquer, qu’il guérisse plus vite.",
            ["DialogueId"] = 12049064,
            ["GUID"] = "1E29DF90",
            ["NextDialogue"] = 12049065,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29DF90",
            },
        [12049065] = {
            ["Content"] = "机枢派的实验，风险有这么高吗？",
            ["ContentFR"] = "Les expériences de la Secte Jishu sont si risquées que ça ?",
            ["DialogueId"] = 12049065,
            ["GUID"] = "1E29DFBA",
            ["NextDialogue"] = 12049066,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29DFBA",
            },
        [12049066] = {
            ["Content"] = "嗯。但我们机枢派先祖<H>矩</>有训，“探新开物，虽险弗辞”——就算新的造物有风险，也要勇敢尝试。",
            ["ContentFR"] = "Oui. Mais notre fondateur, <H>Ju</>, a laissé un précepte : « Explorer et créer, sans reculer devant le danger. » Même si une invention comporte des risques... on tente.",
            ["DialogueId"] = 12049066,
            ["GUID"] = "1E29DFE4",
            ["NextDialogue"] = 12049067,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29DFE4",
            },
        [12049067] = {
            ["Content"] = "试验新式机傀易出意外，习武之人也时常受伤。因此我们特意开垦了一块药田，就在山巅高处。",
            ["ContentFR"] = "Tester de nouvelles méchapoupées, ça tourne vite à l’accident. Et ceux qui s’entraînent aux arts martiaux se blessent souvent. Alors on a aménagé un champ d’herbes médicinales, tout en haut, sur la crête.",
            ["DialogueId"] = 12049067,
            ["GUID"] = "1E29E00E",
            ["NextDialogue"] = 12049068,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29E00E",
            },
        [12049068] = {
            ["Content"] = "来，从前面穿过去就到啦。",
            ["ContentFR"] = "Allez, passez par là — on y est presque.",
            ["DialogueId"] = 12049068,
            ["GUID"] = "1E29E038",
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29E038",
            },
        [12049069] = {
            ["Content"] = "哎？！哪里来的声响？",
            ["ContentFR"] = "Hein ?! C’était quoi, ce bruit ?",
            ["DialogueId"] = 12049069,
            ["GUID"] = "1E29E062",
            ["NextDialogue"] = 12049070,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29E062",
            },
        [12049070] = {
            ["Content"] = "那边发生什么事了？！",
            ["ContentFR"] = "Qu’est-ce qu’il se passe là-bas ?!",
            ["DialogueId"] = 12049070,
            ["GUID"] = "1E29E08C",
            ["NextDialogue"] = 12049071,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29E08C",
            },
        [12049071] = {
            ["Content"] = "怎么到处都是狴犴和应天尉，小仆从，感觉好像很不妙……我们赶紧过去看看！",
            ["ContentFR"] = "Pourquoi il y a des Bi’an et des Magistrats de Yingtian partout ?! Petit larbin, ça sent très mauvais... Allons voir !",
            ["DialogueId"] = 12049071,
            ["GUID"] = "1E29E0B6",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29E0B6",
            },
        [12049072] = {
            ["Content"] = "来得正好！助我一臂之力！",
            ["ContentFR"] = "Juste à temps ! Donne-moi un coup de main !",
            ["DialogueId"] = 12049072,
            ["GUID"] = "1E29E0E0",
            ["NextDialogue"] = 12049073,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29E0E0",
            },
        [12049073] = {
            ["Content"] = "现在是什么情况？",
            ["ContentFR"] = "Qu’est-ce qu’il se passe ?",
            ["DialogueId"] = 12049073,
            ["GUID"] = "1E29E10A",
            ["NextDialogue"] = 12049074,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29E10A",
            },
        [12049074] = {
            ["Content"] = "山外山的位置突然暴露，应天尉打上门来了！",
            ["ContentFR"] = "La position des Pics Extérieurs a été révélée ! Les Magistrats de Yingtian attaquent !",
            ["DialogueId"] = 12049074,
            ["GUID"] = "1E29E134",
            ["NextDialogue"] = 12049075,
            ["SpeakNpcId"] = 240035,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29E134",
            },
        [12049075] = {
            ["Content"] = "此刻不可分神！更具体的事先将他们打退再说！",
            ["ContentFR"] = "Pas le moment de bavarder ! On les repousse d’abord !",
            ["DialogueId"] = 12049075,
            ["GUID"] = "1E29E15E",
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29E15E",
            },
        [12049076] = {
            ["Content"] = "师兄，你当真要攻过来吗？你可想好了？",
            ["ContentFR"] = "... Tu vas vraiment nous attaquer ? Tu en es certain ?",
            ["DialogueId"] = 12049076,
            ["GUID"] = "1E29E188",
            ["NextDialogue"] = 12049077,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29E188",
            },
        [12049077] = {
            ["Content"] = "你我之间，再无交情，只有立场。",
            ["ContentFR"] = "Entre toi et moi, il n’y a plus d’amitié. Seulement des positions opposées.",
            ["DialogueId"] = 12049077,
            ["GUID"] = "1E29E1B2",
            ["NextDialogue"] = 12049078,
            ["SpeakNpcId"] = 210007,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29E1B2",
            },
        [12049078] = {
            ["Content"] = "若你执意如此……我也不得不认真起来了！",
            ["ContentFR"] = "Si tu l’exiges... alors je me battrai sans retenue !",
            ["DialogueId"] = 12049078,
            ["GUID"] = "1E29E1DC",
            ["NextDialogue"] = 12049079,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29E1DC",
            },
        [12049079] = {
            ["Content"] = "有什么话，待到打出个高下后再说也不迟！",
            ["ContentFR"] = "On parlera quand il y aura un vainqueur !",
            ["DialogueId"] = 12049079,
            ["GUID"] = "1E29E206",
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29E206",
            },
        [12049080] = {
            ["Content"] = "走珠入瓯，这是机枢派常给入门弟子设置的一道考验。",
            ["ContentFR"] = "« Perle en coupe ». Une épreuve classique pour les novices de la Secte Jishu.",
            ["DialogueId"] = 12049080,
            ["GUID"] = "1E29E230",
            ["NextDialogue"] = 12049081,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29E230",
            },
        [12049081] = {
            ["Content"] = "看你们手法很熟练的样子，我就不多做解说啦。",
            ["ContentFR"] = "Vu votre aisance, inutile de vous faire un cours.",
            ["DialogueId"] = 12049081,
            ["GUID"] = "1E29E25A",
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29E25A",
            },
        [12049082] = {
            ["Content"] = "这里布置了御敌机傀……当心！",
            ["ContentFR"] = "Des méchapoupées de défense... soyez prudents !",
            ["DialogueId"] = 12049082,
            ["GUID"] = "1E29E284",
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29E284",
            },
        [12049083] = {
            ["Content"] = "哎？怎么看不到这里的机枢球？好奇怪。",
            ["ContentFR"] = "Hein ? Où sont passées les sphères mécaniques ? C’est étrange...",
            ["DialogueId"] = 12049083,
            ["GUID"] = "1E29E2AE",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29E2AE",
            },
        [12049084] = {
            ["Content"] = "小仆从，那边的装置好像有点蹊跷，要不要去看一看？",
            ["ContentFR"] = "Petit larbin, ce mécanisme là-bas a l’air suspect. On va voir ?",
            ["DialogueId"] = 12049084,
            ["GUID"] = "1E29E2D8",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29E2D8",
            },
        [12049085] = {
            ["Content"] = "整个偃隐宫都是浑然一体的吗……不愧是前人巧思。",
            ["ContentFR"] = "Tout le labyrinthe fonctionne comme un seul organisme... Les anciens avaient vraiment du génie.",
            ["DialogueId"] = 12049085,
            ["GUID"] = "1E29E302",
            ["NextDialogue"] = 12049086,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29E302",
            },
        [12049086] = {
            ["Content"] = "哇……是密室！",
            ["ContentFR"] = "Ouaah... une salle secrète !",
            ["DialogueId"] = 12049086,
            ["GUID"] = "1E29E32C",
            ["NextDialogue"] = 12049087,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29E32C",
            },
        [12049087] = {
            ["Content"] = "消失的机枢球一定藏在这里，小仆从，我们赶紧一鼓作气解开这里的机关吧！",
            ["ContentFR"] = "Les sphères disparues sont forcément ici ! Petit larbin, réglons ça d’un seul coup !",
            ["DialogueId"] = 12049087,
            ["GUID"] = "1E29E356",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29E356",
            },
        [12049088] = {
            ["Content"] = "好，这下第一个机枢球就到手了！接下来只要如法炮制，就能继续往前啦！",
            ["ContentFR"] = "Parfait. Première sphère en main. Encore quelques-unes et la voie s’ouvrira.",
            ["DialogueId"] = 12049088,
            ["GUID"] = "1E29E380",
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29E380",
            },
        [12049089] = {
            ["Content"] = "太好了，没想到我们进展如此神速！",
            ["ContentFR"] = "Incroyable... nous avançons bien plus vite que je ne l’espérais.",
            ["DialogueId"] = 12049089,
            ["GUID"] = "1E29E3AA",
            ["NextDialogue"] = 12049090,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29E3AA",
            },
        [12049090] = {
            ["Content"] = "按这个势头，一定能及时赶回支援大家的。",
            ["ContentFR"] = "À ce rythme, nous rejoindrons les autres à temps.",
            ["DialogueId"] = 12049090,
            ["GUID"] = "1E29E3D4",
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29E3D4",
            },
        [12049091] = {
            ["Content"] = "有巨阙镇守此处。{nickname}，这里一定有很重要的东西！",
            ["ContentFR"] = "Un Terracolosse garde cet endroit. {nickname}, ce qui se trouve ici doit être d’une importance capitale.",
            ["DialogueId"] = 12049091,
            ["GUID"] = "1E29E3FE",
            ["NextDialogue"] = 12049092,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29E3FE",
            },
        [12049092] = {
            ["Content"] = "玄铜为骨，机括藏锋。巨阙的攻击力道常人难以抵挡，尽量从侧面取巧吧。",
            ["ContentFR"] = "Os d’airain, mécanismes dissimulant des lames... Les coups d’un Terracolosse sont dévastateurs. Attaque-le de côté si tu peux.",
            ["DialogueId"] = 12049092,
            ["GUID"] = "1E29E428",
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29E428",
            },
        [12049093] = {
            ["Content"] = "有了这样造物，我们就能深入偃隐宫了。",
            ["ContentFR"] = "Avec un tel artefact, nous pouvons enfin pénétrer plus profondément dans le Labyrinthe de Yanyin.",
            ["DialogueId"] = 12049093,
            ["GUID"] = "1E29E452",
            ["NextDialogue"] = 12049094,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29E452",
            },
        [12049094] = {
            ["Content"] = "{nickname}，小白，你们准备好了吗？这是数百年无人踏足过的地界，不知道埋藏着怎样的密辛。",
            ["ContentFR"] = "{nickname}, Snow... préparez-vous. Personne n’a foulé ces lieux depuis des siècles. Les secrets qu’ils renferment ne seront peut-être pas accueillants.",
            ["DialogueId"] = 12049094,
            ["GUID"] = "1E29E47C",
            ["NextDialogue"] = 12049095,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29E47C",
            },
        [12049095] = {
            ["Content"] = "哼哼，这才是适合魔王大人的冒险故事！",
            ["ContentFR"] = "Héhé... voilà enfin une aventure digne du Roi Démon !",
            ["DialogueId"] = 12049095,
            ["GUID"] = "1E29E4A6",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29E4A6",
            },
        [12049096] = {
            ["Content"] = "好壮观……没想到山体里面竟然藏着这么大的空间！",
            ["ContentFR"] = "Quelle immensité... Je n’aurais jamais cru qu’un tel espace se cachait dans la montagne !",
            ["DialogueId"] = 12049096,
            ["GUID"] = "1E29E4D0",
            ["NextDialogue"] = 12049097,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29E4D0",
            },
        [12049097] = {
            ["Content"] = "那处高塔应当是偃隐宫的核心了，我们赶紧去一探究竟吧。",
            ["ContentFR"] = "Cette haute tour doit être le cœur du labyrinthe. Allons voir.",
            ["DialogueId"] = 12049097,
            ["GUID"] = "1E29E4FA",
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29E4FA",
            },
        [12049098] = {
            ["Content"] = "这些转轴看起来能带动邻近的机枢一起转动。",
            ["ContentFR"] = "Ces axes rotatifs semblent pouvoir entraîner les mécanismes voisins.",
            ["DialogueId"] = 12049098,
            ["GUID"] = "1E29E524",
            ["NextDialogue"] = 12049099,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29E524",
            },
        [12049099] = {
            ["Content"] = "{nickname}，思考它们之间的组合关系，制造出一条通路吧。",
            ["ContentFR"] = "{nickname}, observe leurs interactions. Crée un passage.",
            ["DialogueId"] = 12049099,
            ["GUID"] = "1E29E54E",
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29E54E",
            },
        [12049101] = {
            ["Content"] = "咦，飘浮的石块竟然复原成了画中的样子……！好神奇！",
            ["ContentFR"] = "Les blocs flottants se sont recomposés... exactement comme dans la fresque ! Incroyable !",
            ["DialogueId"] = 12049101,
            ["GUID"] = "1E29E5A2",
            ["NextDialogue"] = 12049102,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29E5A2",
            },
        [12049102] = {
            ["Content"] = "“巧构玲珑启万象”，我曾听说过这种神乎其神的技艺，没想到竟能在这里看到真迹……",
            ["ContentFR"] = "« D’un agencement subtil naissent mille formes »... J’avais entendu parler de cette technique légendaire. Je ne pensais pas en voir un jour la preuve.",
            ["DialogueId"] = 12049102,
            ["GUID"] = "1E29E5CC",
            ["NextDialogue"] = 12049103,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29E5CC",
            },
        [12049103] = {
            ["Content"] = "……真是的，要不是时间紧迫，我苏乙横竖也得在这里待上十天半个月，把它研究彻底了再出关！",
            ["ContentFR"] = "Si nous n’étions pas pressés, je m’enfermerais ici dix ou quinze jours pour tout étudier.",
            ["DialogueId"] = 12049103,
            ["GUID"] = "1E29E5F6",
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29E5F6",
            },
        [12049104] = {
            ["Content"] = "这是牵机鸟的原型……真怀念，我小时候天天对着画本临摹它的样子，想象自己乘着它翱翔于长空。",
            ["ContentFR"] = "C’est le prototype du cerf-volant mécanique... Quelle nostalgie. Petite, je le recopiais sans cesse dans mes carnets, en rêvant de voler à son bord.",
            ["DialogueId"] = 12049104,
            ["GUID"] = "1E29E620",
            ["NextDialogue"] = 12049105,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29E620",
            },
        [12049105] = {
            ["Content"] = "登上去吧，{nickname}，它会将你载往下一个地点。",
            ["ContentFR"] = "Monte, {nickname}. Il te mènera à l’étage suivant.",
            ["DialogueId"] = 12049105,
            ["GUID"] = "1E29E64A",
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29E64A",
            },
        }
  end },
  { MinKey = 12049106, MaxKey = 12060401, Loader = function()
      return {
        [12049106] = {
            ["Content"] = "通体以榫卯结构打造的高塔……真是令人惊叹。",
            ["ContentFR"] = "Une tour entièrement assemblée à tenons et mortaises... c’est prodigieux.",
            ["DialogueId"] = 12049106,
            ["GUID"] = "1E29E674",
            ["NextDialogue"] = 12049107,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29E674",
            },
        [12049107] = {
            ["Content"] = "苏乙，前方的石碑上，好像写着什么字。",
            ["ContentFR"] = "Su Yi, il y a des inscriptions sur la stèle devant nous.",
            ["DialogueId"] = 12049107,
            ["GUID"] = "1E29E69E",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29E69E",
            },
        [12049108] = {
            ["Content"] = "说起来，为什么你们机枢派的前辈，要费老大劲建这样一个地宫，来把东西藏起来呢？",
            ["ContentFR"] = "Dis-moi... pourquoi vos ancêtres ont-ils construit un labyrinthe entier juste pour cacher quelque chose ?",
            ["DialogueId"] = 12049108,
            ["GUID"] = "1E29E6C8",
            ["NextDialogue"] = 12049109,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29E6C8",
            },
        [12049109] = {
            ["Content"] = "值得这么大费周章，一定是很重要的秘密吧。",
            ["ContentFR"] = "Un tel déploiement... ça doit être un secret d’une importance capitale.",
            ["DialogueId"] = 12049109,
            ["GUID"] = "1E29E6F2",
            ["NextDialogue"] = 12049110,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29E6F2",
            },
        [12049110] = {
            ["Content"] = "嗯……根据史料考据，这座偃隐宫应当是在黍离之战后几十年内建起来的。",
            ["ContentFR"] = "Oui... D’après les archives, le Labyrinthe de Yanyin aurait été érigé dans les décennies qui ont suivi la Bataille de Shuli.",
            ["DialogueId"] = 12049110,
            ["GUID"] = "1E29E71C",
            ["NextDialogue"] = 12049111,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29E71C",
            },
        [12049111] = {
            ["Content"] = "黍离之战……我好像听别人提过好几次，但我始终不知道它是什么。",
            ["ContentFR"] = "La Bataille de Shuli... J’en ai entendu parler plusieurs fois, mais je n’ai jamais su ce que c’était vraiment.",
            ["DialogueId"] = 12049111,
            ["GUID"] = "1E29E746",
            ["NextDialogue"] = 12049112,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29E746",
            },
        [12049112] = {
            ["Content"] = "那是导致机枢派衰落，也让大风九章逐渐变质的一场战役。之后有机会，我再慢慢讲给你们听。",
            ["ContentFR"] = "C’est elle qui provoqua le déclin de la Secte Jishu... et le début de la dégradation des Neuf Chapitres. Si nous avons le temps un jour, je vous en raconterai l’histoire en détail.",
            ["DialogueId"] = 12049112,
            ["GUID"] = "1E29E770",
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29E770",
            },
        [12049113] = {
            ["Content"] = "我们正在接近最后的真相……越到这种时候，越不能放松警惕。",
            ["ContentFR"] = "Nous approchons de la vérité ultime... C’est justement dans ces moments-là qu’il faut rester sur ses gardes.",
            ["DialogueId"] = 12049113,
            ["GUID"] = "1E29E79A",
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29E79A",
            },
        [12049114] = {
            ["Content"] = "呜啊啊……小仆从，黑白两色的大狼灵怎么联手一起打我们了！感觉不太妙的样子！",
            ["ContentFR"] = "Aaaah ! Petit larbin ! Pourquoi font-ils équipe contre nous ?! Ils sont censés être ennemis ! Ce n’est pas bon du tout !",
            ["DialogueId"] = 12049114,
            ["GUID"] = "1E29E7C4",
            ["NextDialogue"] = 12049115,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29E7C4",
            },
        [12049115] = {
            ["Content"] = "它们并非是真正的狴犴，而是模仿狴犴外形制造出的仿生机傀！要小心了！",
            ["ContentFR"] = "Ce ne sont pas de véritables Bi’an ! Ce sont des méchapoupées biomimétiques conçues à leur image ! Restez sur vos gardes !",
            ["DialogueId"] = 12049115,
            ["GUID"] = "1E29E7EE",
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29E7EE",
            },
        [12049116] = {
            ["Content"] = "第二幅卦象也已经松动，这意味着预言已经实现了……",
            ["ContentFR"] = "Le deuxième hexagramme s’est desserré... Ça veut dire que la prophétie s’est réalisée...",
            ["DialogueId"] = 12049116,
            ["GUID"] = "1E29E818",
            ["NextDialogue"] = 12049117,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29E818",
            },
        [12049117] = {
            ["Content"] = "止流……你的图谋到底是什么？",
            ["ContentFR"] = "Zhiliu... qu’est-ce que vous manigancez exactement ?",
            ["DialogueId"] = 12049117,
            ["GUID"] = "1E29E842",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29E842",
            },
        [12049118] = {
            ["Content"] = "数十年不见，村门口的树苗竟然已经蹿这么高了！",
            ["ContentFR"] = "Des décennies que je ne suis pas revenu... et ces jeunes arbres ont déjà poussé si haut ?",
            ["DialogueId"] = 12049118,
            ["GUID"] = "1E29E86C",
            ["NextDialogue"] = 12049119,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29E86C",
            },
        [12049119] = {
            ["Content"] = "哈哈，小时候我老爱在这儿爬上爬下，和小孩斗蛐蛐，用树枝戳村里的大鹅，被大鹅撵得满地跑……",
            ["ContentFR"] = "Ha ha ! Quand j’étais gosse, je passais mon temps à grimper dessus. On faisait combattre des grillons, on taquinait les oies du village avec des branches... et on finissait à courir partout pour leur échapper !",
            ["DialogueId"] = 12049119,
            ["GUID"] = "1E29E896",
            ["NextDialogue"] = 12049120,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29E896",
            },
        [12049120] = {
            ["Content"] = "唉，也不知道如今乡亲们还认不认得我。",
            ["ContentFR"] = "<I>Pff...</> Je me demande si les gens d’ici me reconnaîtraient encore.",
            ["DialogueId"] = 12049120,
            ["GUID"] = "1E29E8C0",
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29E8C0",
            },
        [12049121] = {
            ["Content"] = "我只打探到无穷藏派的传人在此村中，但不知道具体姓甚名谁。",
            ["ContentFR"] = "Je sais seulement que l’héritier de la Secte de l’Insondable Trésor réside dans ce village. Son nom et son identité exacte me sont inconnus.",
            ["DialogueId"] = 12049121,
            ["GUID"] = "1E29E8EA",
            ["NextDialogue"] = 12049122,
            ["SpeakNpcId"] = 240002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29E8EA",
            },
        [12049122] = {
            ["Content"] = "说实话，我也不知道。你们先找人问问吧。",
            ["ContentFR"] = "Pour être honnête, moi non plus je n’en sais rien. Autant commencer par interroger les habitants.",
            ["DialogueId"] = 12049122,
            ["GUID"] = "1E29E914",
            ["NextDialogue"] = 12049123,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29E914",
            },
        [12049123] = {
            ["Content"] = "刻舟你这个本地向导来打听不是更方便吗？你该不会想偷懒！",
            ["ContentFR"] = "Mais toi, en tant que guide local, ce ne serait pas plus simple que tu demandes directement ? Ne me dis pas que tu comptes encore te défiler !",
            ["DialogueId"] = 12049123,
            ["GUID"] = "1E29E93E",
            ["NextDialogue"] = 12049124,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29E93E",
            },
        [12049124] = {
            ["Content"] = "还真不是这样……咳，你们等会儿就知道了。",
            ["ContentFR"] = "Ce n’est pas ça... <I>Hum.</> Vous comprendrez bien assez tôt.",
            ["DialogueId"] = 12049124,
            ["GUID"] = "1E29E968",
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29E968",
            },
        [12049125] = {
            ["Content"] = "刻舟，她怎么一见到你就变了脸色？",
            ["ContentFR"] = "Pourquoi elle a changé de visage dès qu’elle t’a reconnu ?",
            ["DialogueId"] = 12049125,
            ["GUID"] = "1E29E992",
            ["NextDialogue"] = 12049126,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29E992",
            },
        [12049126] = {
            ["Content"] = "谁知道呢？可能是我小时候天天追着她家的鸡撵吧。",
            ["ContentFR"] = "Qui sait ? Peut-être parce que je passais mon temps à courir après ses poules quand j’étais gamin.",
            ["DialogueId"] = 12049126,
            ["GUID"] = "1E29E9BC",
            ["NextDialogue"] = 12049127,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29E9BC",
            },
        [12049127] = {
            ["Content"] = "罢了，这样四处瞎打听也问不出什么。我带你们去找村长吧。",
            ["ContentFR"] = "Bon... On n’obtiendra rien en tournant autour du pot. Allons voir le chef du village.",
            ["DialogueId"] = 12049127,
            ["GUID"] = "1E29E9E6",
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29E9E6",
            },
        [12049128] = {
            ["Content"] = "最后一处卦象的封印松动了……一切的真相即将揭晓。",
            ["ContentFR"] = "Le dernier sceau... cède. Toute la vérité va enfin se révéler.",
            ["DialogueId"] = 12049128,
            ["GUID"] = "1E29EA10",
            ["NextDialogue"] = 12049129,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29EA10",
            },
        [12049129] = {
            ["Content"] = "止流，做出这些决定之时，你在想什么？",
            ["ContentFR"] = "Zhiliu... lorsque vous avez fait ces choix, à quoi pensiez-vous ?",
            ["DialogueId"] = 12049129,
            ["GUID"] = "1E29EA3A",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29EA3A",
            },
        [12049130] = {
            ["Content"] = "止流，你是要成为千古罪人吗？",
            ["ContentFR"] = "Zhiliu... veux-tu devenir la pécheresse des siècles à venir ?",
            ["DialogueId"] = 12049130,
            ["GUID"] = "1E29EA64",
            ["NextDialogue"] = 12049131,
            ["SpeakNpcName"] = "UI_Npc_Name_xianrennv1",
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29EA64",
            },
        [12049131] = {
            ["Content"] = "天地大德，祖宗之法，岂容汝等凡人悖逆？！",
            ["ContentFR"] = "La vertu du Ciel, les lois des ancêtres — oserais-tu, simple mortelle, les renverser ?!",
            ["DialogueId"] = 12049131,
            ["GUID"] = "1E29EA8E",
            ["SpeakNpcName"] = "UI_Npc_Name_xianrennan1",
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29EA8E",
            },
        [12049132] = {
            ["Content"] = "现在回头，为时不晚！",
            ["ContentFR"] = "Reviens tant qu’il est encore temps !",
            ["DialogueId"] = 12049132,
            ["GUID"] = "1E29EAB8",
            ["SpeakNpcName"] = "UI_Npc_Name_xianrennv2",
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29EAB8",
            },
        [12049133] = {
            ["Content"] = "停下，别再前进了！",
            ["ContentFR"] = "Arrête-toi !",
            ["DialogueId"] = 12049133,
            ["GUID"] = "1E29EAE2",
            ["SpeakNpcName"] = "UI_Npc_Name_xianrennan2",
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29EAE2",
            },
        [12049134] = {
            ["Content"] = "千秋万代之伟业，便要终结在你手上！",
            ["ContentFR"] = "Veux-tu vraiment voir l’œuvre de millénaires s’achever entre tes mains ?!",
            ["DialogueId"] = 12049134,
            ["GUID"] = "1E29EB0C",
            ["SpeakNpcName"] = "UI_Npc_Name_xianrennv3",
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29EB0C",
            },
        [12049135] = {
            ["Content"] = "止流，你当真想好了吗——",
            ["ContentFR"] = "Zhiliu — es-tu certaine de ton choix ?!",
            ["DialogueId"] = 12049135,
            ["GUID"] = "1E29EB36",
            ["SpeakNpcName"] = "UI_Npc_Name_xianrennan3",
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29EB36",
            },
        [12049136] = {
            ["Content"] = "成功了……！",
            ["ContentFR"] = "Ça a marché... !",
            ["DialogueId"] = 12049136,
            ["GUID"] = "1E29EB60",
            ["NextDialogue"] = 12049137,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29EB60",
            },
        [12049137] = {
            ["Content"] = "沿路的塑像都被打破了，止流一定就在前方！",
            ["ContentFR"] = "Toutes les statues sur le chemin ont été détruites... Zhiliu doit être devant !",
            ["DialogueId"] = 12049137,
            ["GUID"] = "1E29EB8A",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29EB8A",
            },
        [12049138] = {
            ["Content"] = "入侵者，可承天威之怒乎？",
            ["ContentFR"] = "Intrus... peux-tu supporter la colère du Ciel ?",
            ["DialogueId"] = 12049138,
            ["GUID"] = "1E29EBB4",
            ["SpeakNpcName"] = "UI_Npc_Name_ZhuYinTaiHao",
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29EBB4",
            },
        [12049139] = {
            ["Content"] = "这里是……？",
            ["ContentFR"] = "Où sommes-nous... ?",
            ["DialogueId"] = 12049139,
            ["GUID"] = "1E29EBDE",
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29EBDE",
            },
        [12049140] = {
            ["Content"] = "……万物负阴而抱阳，冲气以为和……",
            ["ContentFR"] = "... Tous les êtres portent le yin et embrassent le yang ; de leur union naît l’harmonie...",
            ["DialogueId"] = 12049140,
            ["GUID"] = "1E29EC08",
            ["SpeakNpcName"] = "UI_Npc_Name_ZhuYinTaiHao",
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29EC08",
            },
        [12049141] = {
            ["Content"] = "……持而盈之，不如其已；揣而锐之，不可长保……",
            ["ContentFR"] = "... Remplir un vase jusqu’au bord n’est pas sagesse ; aiguiser une lame à l’extrême ne saurait la préserver...",
            ["DialogueId"] = 12049141,
            ["GUID"] = "1E29EC32",
            ["SpeakNpcName"] = "UI_Npc_Name_ZhuYinTaiHao",
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29EC32",
            },
        [12049142] = {
            ["Content"] = "想不到，事情解决后，你来的第一个地方竟然是这里。",
            ["ContentFR"] = "De toutes les destinations possibles après la résolution de cette affaire... je ne pensais pas que tu viendrais ici.",
            ["DialogueId"] = 12049142,
            ["GUID"] = "1E29EC5C",
            ["NextDialogue"] = 12049143,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29EC5C",
            },
        [12049143] = {
            ["Content"] = "是想去那个人墓前看看吗？",
            ["ContentFR"] = "Tu souhaites te rendre sur sa tombe, n’est-ce pas ?",
            ["DialogueId"] = 12049143,
            ["GUID"] = "1E29EC86",
            ["NextDialogue"] = 12049144,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29EC86",
            },
        [12049144] = {
            ["Content"] = "……看来我那师父都告诉你们了啊。真是多此一举。",
            ["ContentFR"] = "... Il semblerait que mon maître vous ait tout raconté. Quelle indiscrétion inutile.",
            ["DialogueId"] = 12049144,
            ["GUID"] = "1E29ECB0",
            ["NextDialogue"] = 12049145,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29ECB0",
            },
        [12049145] = {
            ["Content"] = "不过，也正是多亏了她多管闲事，这场变局才得以圆满收场。",
            ["ContentFR"] = "Et pourtant... c’est aussi grâce à son intervention que cette crise a pu trouver une issue.",
            ["DialogueId"] = 12049145,
            ["GUID"] = "1E29ECDA",
            ["NextDialogue"] = 12049146,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29ECDA",
            },
        [12049146] = {
            ["Content"] = "那件事发生后，每一个下雨的夜晚，我都无法入睡。只要一闭眼，耳旁就会响起永无止境的水滴声。",
            ["ContentFR"] = "Depuis cet événement, chaque nuit de pluie m’est insupportable. À peine les yeux clos, j’entends le goutte-à-goutte interminable résonner à mes oreilles.",
            ["DialogueId"] = 12049146,
            ["GUID"] = "1E29ED04",
            ["NextDialogue"] = 12049147,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29ED04",
            },
        [12049147] = {
            ["Content"] = "我总是在噩梦中回到那个山洞，看到那些人冷漠的眼神。于是我不再信任旁人。",
            ["ContentFR"] = "Dans mes cauchemars, je retourne sans cesse dans cette grotte... et je revois les regards froids de ces gens. Alors, j’ai cessé de faire confiance aux autres.",
            ["DialogueId"] = 12049147,
            ["GUID"] = "1E29ED2E",
            ["NextDialogue"] = 12049148,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29ED2E",
            },
        [12049148] = {
            ["Content"] = "我选择去掌控一切，算计一切，归根结底，是因为我只能看到自己愿意相信的。",
            ["ContentFR"] = "J’ai choisi de tout contrôler, de tout calculer... Au fond, parce que je ne supportais de voir que ce que j’acceptais de croire.",
            ["DialogueId"] = 12049148,
            ["GUID"] = "1E29ED58",
            ["NextDialogue"] = 12049149,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29ED58",
            },
        [12049149] = {
            ["Content"] = "{nickname}，你或许还在生我的气吧……如果当初我选择多信任你一点，现在是否能更加坦然地面对你呢？",
            ["ContentFR"] = "{nickname}... peut-être m’en veux-tu encore. Si je t’avais accordé davantage de confiance... me serait-il plus facile de soutenir ton regard aujourd’hui ?",
            ["DialogueId"] = 12049149,
            ["GUID"] = "1E29ED82",
            ["NextDialogue"] = 12049150,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29ED82",
            },
        [12049150] = {
            ["Content"] = "呵呵，我也沉溺于这种无用的假设了。",
            ["ContentFR"] = "Héhé... me voilà à me perdre dans des hypothèses inutiles.",
            ["DialogueId"] = 12049150,
            ["GUID"] = "1E29EDAC",
            ["NextDialogue"] = 12049151,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29EDAC",
            },
        [12049151] = {
            ["Content"] = "不知不觉中，已经走到地方了啊……",
            ["ContentFR"] = "Sans même m’en apercevoir... nous sommes arrivés.",
            ["DialogueId"] = 12049151,
            ["GUID"] = "1E29EDD6",
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29EDD6",
            },
        [12049201] = {
            ["Content"] = "一段时间前……某处雨夜……",
            ["ContentFR"] = "Il y a quelque temps... Une nuit d’orage...",
            ["DialogueId"] = 12049201,
            ["GUID"] = "1E29F60A",
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29F60A",
            },
        [12049202] = {
            ["Content"] = "呵……就这点能耐吗？",
            ["ContentFR"] = "<I>Pff...</> C’est tout ce que vous savez faire ?",
            ["DialogueId"] = 12049202,
            ["GUID"] = "1E29F634",
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29F634",
            },
        [12049203] = {
            ["Content"] = "他就在那里！",
            ["ContentFR"] = "Il est là !",
            ["DialogueId"] = 12049203,
            ["GUID"] = "1E29F65E",
            ["RelatedWikiId"] = {
                [1] = 203007,
                [2] = 407009,
                [3] = 407013,
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29F65E",
            },
        [12049204] = {
            ["Content"] = "今敕尔等——目见天宪即俯首，耳闻法音当束心。",
            ["ContentFR"] = "Par décret céleste — que quiconque contemple la Loi s’incline. Que quiconque entende la Voix du Ciel apaise son cœur.",
            ["DialogueId"] = 12049204,
            ["GUID"] = "1E29F688",
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29F688",
            },
        [12049205] = {
            ["Content"] = "来者，何敢叩情辩法？",
            ["ContentFR"] = "Qui ose se présenter... et réclamer un Rite de Délibération ?",
            ["DialogueId"] = 12049205,
            ["GUID"] = "1E29F6B2",
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29F6B2",
            },
        [12049206] = {
            ["Content"] = "不自量力。",
            ["ContentFR"] = "Imprudent.",
            ["DialogueId"] = 12049206,
            ["GUID"] = "1E29F6DC",
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29F6DC",
            },
        [12049207] = {
            ["Content"] = "……{nickname}，怎么是你？",
            ["ContentFR"] = "... {nickname} ? Qu’est-ce que tu fais ici ?",
            ["DialogueId"] = 12049207,
            ["GUID"] = "1E29F706",
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29F706",
            },
        [12049208] = {
            ["Content"] = "好剑法！",
            ["ContentFR"] = "Belle parade !",
            ["DialogueId"] = 12049208,
            ["GUID"] = "1E29F730",
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29F730",
            },
        [12049209] = {
            ["Content"] = "师兄……原来你已经这么厉害了。",
            ["ContentFR"] = "Yuming... tu es devenu si fort.",
            ["DialogueId"] = 12049209,
            ["GUID"] = "1E29F75A",
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29F75A",
            },
        [12049210] = {
            ["Content"] = "刻舟，我问你。",
            ["ContentFR"] = "Kezhou. Réponds-moi.",
            ["DialogueId"] = 12049210,
            ["GUID"] = "1E29F784",
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29F784",
            },
        [12049211] = {
            ["Content"] = "飘零人只想过“破”，可曾想过“立”？",
            ["ContentFR"] = "Les Vagabonds ne pensent qu’à détruire. Avez-vous seulement réfléchi à ce que vous bâtirez ensuite ?",
            ["DialogueId"] = 12049211,
            ["GUID"] = "1E29F7AE",
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29F7AE",
            },
        [12049212] = {
            ["Content"] = "若是大风九章倾覆，秽兽横行四野，暴行无人约束，芸芸众生将如何得以保全性命？",
            ["ContentFR"] = "Si les Neuf Chapitres s’effondrent... si les Souillés envahissent les terres, si plus rien ne retient la violence... qui protégera le peuple ?",
            ["DialogueId"] = 12049212,
            ["GUID"] = "1E29F7D8",
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29F7D8",
            },
        [12049213] = {
            ["Content"] = "自有我们！否则大家苦练这一身武艺做什么？",
            ["ContentFR"] = "Nous le ferons ! Pourquoi crois-tu que nous nous sommes entraînés si durement toutes ces années ?",
            ["DialogueId"] = 12049213,
            ["GUID"] = "1E29F802",
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29F802",
            },
        [12049214] = {
            ["Content"] = "那<H>秽蚀者</>呢？",
            ["ContentFR"] = "Et les <H>Dégradés</> ?",
            ["DialogueId"] = 12049214,
            ["GUID"] = "1E29F82C",
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29F82C",
            },
        [12049215] = {
            ["Content"] = "秽蚀者已不复为人，杀了便是——",
            ["ContentFR"] = "Les Dégradés ne sont plus humains. On les abat.",
            ["DialogueId"] = 12049215,
            ["GUID"] = "1E29F856",
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29F856",
            },
        [12049216] = {
            ["Content"] = "……如果那秽蚀者是你的师长、挚友、骨肉至亲呢？",
            ["ContentFR"] = "... Et si le Dégradé était ton maître ? Ton ami le plus cher ? Un membre de ta famille ?",
            ["DialogueId"] = 12049216,
            ["GUID"] = "1E29F880",
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29F880",
            },
        [12049217] = {
            ["Content"] = "……可是——！",
            ["ContentFR"] = "... Mais— !",
            ["DialogueId"] = 12049217,
            ["GUID"] = "1E29F8AA",
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29F8AA",
            },
        [12049218] = {
            ["Content"] = "够了……！",
            ["ContentFR"] = "Ça suffit... !",
            ["DialogueId"] = 12049218,
            ["GUID"] = "1E29F8D4",
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29F8D4",
            },
        [12049219] = {
            ["Content"] = "拜托了，{nickname}，跟我来。一定还有别的解决方法！",
            ["ContentFR"] = "S’il te plaît, {nickname} — viens. Il doit exister une autre solution.",
            ["DialogueId"] = 12049219,
            ["GUID"] = "1E29F8FE",
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29F8FE",
            },
        [12049220] = {
            ["Content"] = "让开，我们来了！",
            ["ContentFR"] = "Écartez-vous — on arrive !",
            ["DialogueId"] = 12049220,
            ["GUID"] = "1E29F928",
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29F928",
            },
        [12049221] = {
            ["Content"] = "看来你心意已决。",
            ["ContentFR"] = "Il semble... que ta résolution ne vacille pas.",
            ["DialogueId"] = 12049221,
            ["GUID"] = "1E29F952",
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29F952",
            },
        [12049222] = {
            ["Content"] = "从今往后，正义将被交还到华胥每一个人的手中。",
            ["ContentFR"] = "À partir de ce jour, la justice sera rendue à chaque habitant de Huaxu.",
            ["DialogueId"] = 12049222,
            ["GUID"] = "1E29F97C",
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29F97C",
            },
        [12049223] = {
            ["Content"] = "华胥子民将怀勇毅之心，行公正之事，无畏罪恶，亦不惧怕灾难。他们……将成为自己的主人。",
            ["ContentFR"] = "Les habitants de Huaxu porteront le courage en leur cœur, agiront avec droiture, ne craindront ni le crime, ni la calamité. Ils... deviendront maîtres d’eux-mêmes.",
            ["DialogueId"] = 12049223,
            ["GUID"] = "1E29F9A6",
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29F9A6",
            },
        [12049224] = {
            ["Content"] = "白龙，那般的未来，你不想看看吗？",
            ["ContentFR"] = "Dragon d’Argent... ne souhaites-tu pas voir un tel avenir ?",
            ["DialogueId"] = 12049224,
            ["GUID"] = "1E29F9D0",
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29F9D0",
            },
        [12049225] = {
            ["Content"] = "吼——",
            ["ContentFR"] = "Rooooaaar— !",
            ["DialogueId"] = 12049225,
            ["GUID"] = "1E29F9FA",
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29F9FA",
            },
        [12049226] = {
            ["Content"] = "{nickname}，你来了。",
            ["ContentFR"] = "{nickname}... te voilà.",
            ["DialogueId"] = 12049226,
            ["GUID"] = "1E29FA24",
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29FA24",
            },
        [12049227] = {
            ["Content"] = "来，对着这里，捅下去，一剑贯穿。",
            ["ContentFR"] = "Ici. Enfonce la lame. Droit au cœur.",
            ["DialogueId"] = 12049227,
            ["GUID"] = "1E29FA4E",
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29FA4E",
            },
        [12049228] = {
            ["Content"] = "这不是我此行的目的。",
            ["ContentFR"] = "Ce n’est pas pour cela que je suis venu.",
            ["DialogueId"] = 12049228,
            ["GUID"] = "1E29FA78",
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29FA78",
            },
        [12049229] = {
            ["Content"] = "呵呵……事到如今，还有这种可爱的想法。",
            ["ContentFR"] = "Héhé... même maintenant, tu nourris encore une si charmante illusion.",
            ["DialogueId"] = 12049229,
            ["GUID"] = "1E29FAA2",
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29FAA2",
            },
        [12049230] = {
            ["Content"] = "止流掌柜，你先前说，你没有留给我选择。但你错了。",
            ["ContentFR"] = "Vous disiez que je n’avais pas le choix. Vous aviez tort.",
            ["DialogueId"] = 12049230,
            ["GUID"] = "1E29FACC",
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29FACC",
            },
        [12049231] = {
            ["Content"] = "我来这里，就是为了向你证明——",
            ["ContentFR"] = "Je suis venu vous prouver—",
            ["DialogueId"] = 12049231,
            ["GUID"] = "1E29FAF6",
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29FAF6",
            },
        [12049232] = {
            ["Content"] = "人是可以开辟出新的选项的。",
            ["ContentFR"] = "Que l’on peut toujours ouvrir une voie nouvelle.",
            ["DialogueId"] = 12049232,
            ["GUID"] = "1E29FB20",
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29FB20",
            },
        [12049233] = {
            ["Content"] = "和鸣之力……？",
            ["ContentFR"] = "La Résonance... ?",
            ["DialogueId"] = 12049233,
            ["GUID"] = "1E29FB4A",
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29FB4A",
            },
        [12049234] = {
            ["Content"] = "……我们还会在这里，被困多久？",
            ["ContentFR"] = "... Combien de temps allons-nous encore rester coincés ici ?",
            ["DialogueId"] = 12049234,
            ["GUID"] = "1E29FB74",
            ["NextDialogue"] = 12049235,
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29FB74",
            },
        [12049235] = {
            ["Content"] = "我们大人会找到出路的。安心，孩子，你现在要做的是好好休息，保存体力。",
            ["ContentFR"] = "Les adultes trouveront une issue. Ne t’inquiète pas, petite. Repose-toi. Garde tes forces.",
            ["DialogueId"] = 12049235,
            ["GUID"] = "1E29FB9E",
            ["NextDialogue"] = 12049236,
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29FB9E",
            },
        [12049236] = {
            ["Content"] = "好安静啊……我们会不会被所有人遗忘，就这样再也出不去了？",
            ["ContentFR"] = "C’est si silencieux... Et si nous restions ici pour toujours ? Et si tout le monde nous oubliait ?",
            ["DialogueId"] = 12049236,
            ["GUID"] = "1E29FBC8",
            ["NextDialogue"] = 12049237,
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29FBC8",
            },
        [12049237] = {
            ["Content"] = "你若是老想着这个问题，时间就会变得格外漫长。就像人平时习惯了待在屋檐底下，一旦屋檐失修，就会对迎面而来的雨水茫然失措。",
            ["ContentFR"] = "Si tu ne penses qu’à cela, le temps paraîtra interminable. C’est comme quelqu’un habitué à l’abri d’un toit : quand le toit se dégrade, il ne sait plus quoi faire face à la pluie.",
            ["DialogueId"] = 12049237,
            ["GUID"] = "1E29FBF2",
            ["NextDialogue"] = 12049238,
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29FBF2",
            },
        [12049238] = {
            ["Content"] = "不如换个视角，这跳出常规的雨水的滋味，在日常生活中可不多见。细细体验当下的感受，待日后被救出去了，不也是一桩不错的谈资？",
            ["ContentFR"] = "Essaie plutôt de voir les choses autrement. Ce goût de pluie hors du quotidien... on ne l’expérimente pas souvent. Savoure ce moment. Le jour où nous sortirons d’ici, ce sera une histoire à raconter.",
            ["DialogueId"] = 12049238,
            ["GUID"] = "1E29FC1C",
            ["NextDialogue"] = 12049239,
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29FC1C",
            },
        [12049239] = {
            ["Content"] = "事后想来，那一天的洞穴塌方，大约就是烛阴之灾初显的征兆。",
            ["ContentFR"] = "En y repensant... L’effondrement de cette grotte fut sans doute le premier signe du Fléau de Zhuyin.",
            ["DialogueId"] = 12049239,
            ["GUID"] = "1E29FC46",
            ["NextDialogue"] = 12049240,
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29FC46",
            },
        [12049240] = {
            ["Content"] = "虽然受困于此，实属不幸之事。但和这个生性乐观的人待在一起，好像也没那么难熬……这会成为一段终生难忘的经历吧，我如此想着。",
            ["ContentFR"] = "Être piégés ici était un malheur. Mais auprès de cet homme, si résolument optimiste... cela semblait presque supportable. Je pensais alors : ce serait un souvenir que je garderais toute ma vie.",
            ["DialogueId"] = 12049240,
            ["GUID"] = "1E29FC70",
            ["NextDialogue"] = 12049241,
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29FC70",
            },
        [12049241] = {
            ["Content"] = "……但随着时间推移，连续数日粒米未进后，我已经顾不上思考那么多事情了。",
            ["ContentFR"] = "Mais les jours ont passé. Après plusieurs jours sans la moindre bouchée de riz... je n’avais plus la force de réfléchir.",
            ["DialogueId"] = 12049241,
            ["GUID"] = "1E29FC9A",
            ["NextDialogue"] = 12049242,
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29FC9A",
            },
        [12049242] = {
            ["Content"] = "好饿……好饿……救援何时才能到来？",
            ["ContentFR"] = "J’ai faim... tellement faim... Quand les secours arriveront-ils ?",
            ["DialogueId"] = 12049242,
            ["GUID"] = "1E29FCC4",
            ["NextDialogue"] = 12049243,
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29FCC4",
            },
        [12049243] = {
            ["Content"] = "这山洞如此偏僻，等旁人发现我们失踪，再等救援队找过来，不知还要过上多少时日……",
            ["ContentFR"] = "Cette grotte est si isolée... Même s’ils remarquent notre disparition, combien de jours leur faudra-t-il pour nous trouver ?",
            ["DialogueId"] = 12049243,
            ["GUID"] = "1E29FCEE",
            ["NextDialogue"] = 12049244,
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29FCEE",
            },
        [12049244] = {
            ["Content"] = "啊啊……那，等他们寻过来，我们的尸骨不是都凉透了吗？",
            ["ContentFR"] = "Alors... quand ils viendront, nos corps seront déjà froids...",
            ["DialogueId"] = 12049244,
            ["GUID"] = "1E29FD18",
            ["NextDialogue"] = 12049245,
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29FD18",
            },
        [12049245] = {
            ["Content"] = "对了，我们有大风九章，我们还有大风九章不是吗？白龙神君总会庇佑祂的子民，对不对！",
            ["ContentFR"] = "Mais nous avons les Neuf Chapitres de Dafeng ! Le Seigneur Dragon d’Argent protège toujours Son peuple... n’est-ce pas ?",
            ["DialogueId"] = 12049245,
            ["GUID"] = "1E29FD42",
            ["NextDialogue"] = 12049246,
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29FD42",
            },
        [12049246] = {
            ["Content"] = "但应天尉的职责是惩恶除奸，他们真的会为我们而来吗……",
            ["ContentFR"] = "Les Magistrats de Yingtian sont là pour punir le mal... Viendraient-ils vraiment pour nous ?",
            ["DialogueId"] = 12049246,
            ["GUID"] = "1E29FD6C",
            ["NextDialogue"] = 12049247,
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29FD6C",
            },
        [12049247] = {
            ["Content"] = "可恶！若我们饿死在此处，便只能成为意外卷宗上的一行数字了吗？",
            ["ContentFR"] = "Assez ! Si nous mourons de faim ici, nous ne serons qu’un chiffre de plus dans un registre d’accidents !",
            ["DialogueId"] = 12049247,
            ["GUID"] = "1E29FD96",
            ["NextDialogue"] = 12049248,
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29FD96",
            },
        [12049248] = {
            ["Content"] = "你疯了？！",
            ["ContentFR"] = "Tu es fou ?!",
            ["DialogueId"] = 12049248,
            ["GUID"] = "1E29FDC0",
            ["NextDialogue"] = 12049249,
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29FDC0",
            },
        [12049249] = {
            ["Content"] = "你想干什么？！",
            ["ContentFR"] = "Qu’est-ce que tu fais ?!",
            ["DialogueId"] = 12049249,
            ["GUID"] = "1E29FDEA",
            ["NextDialogue"] = 12049250,
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29FDEA",
            },
        [12049250] = {
            ["Content"] = "上天保佑——勿滥杀，休行凶！这可是诫律啊，你怎么能违反诫律呢？！",
            ["ContentFR"] = "Par pitié ! Ne tue pas ! C’est interdit par les Préceptes ! Comment peux-tu les violer ?!",
            ["DialogueId"] = 12049250,
            ["GUID"] = "1E29FE14",
            ["NextDialogue"] = 12049251,
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29FE14",
            },
        [12049251] = {
            ["Content"] = "我不知道什么诫律——我只知道这里有活生生的食物！",
            ["ContentFR"] = "Je me moque des Préceptes ! Moi, je vois de la nourriture vivante !",
            ["DialogueId"] = 12049251,
            ["GUID"] = "1E29FE3E",
            ["NextDialogue"] = 12049252,
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29FE3E",
            },
        [12049252] = {
            ["Content"] = "你、你就不怕大风九章降下惩罚吗？！",
            ["ContentFR"] = "Tu n’as pas peur que les Neuf Chapitres te punissent ?!",
            ["DialogueId"] = 12049252,
            ["GUID"] = "1E29FE68",
            ["NextDialogue"] = 12049253,
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29FE68",
            },
        [12049253] = {
            ["Content"] = "应天尉也不是无所不能的。不是有那些什么飘零人吗？再不济，抢艘船，逃往海外去！",
            ["ContentFR"] = "Les Magistrats ne sont pas omniscients ! Et il y a les Vagabonds ! Au pire, je volerai un bateau et je fuirai au-delà des mers !",
            ["DialogueId"] = 12049253,
            ["GUID"] = "1E29FE92",
            ["NextDialogue"] = 12049254,
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29FE92",
            },
        [12049254] = {
            ["Content"] = "但首先得吃饱了肚子。我可不会像你们一样干等着！要是饿死在这里，一切免谈！",
            ["ContentFR"] = "Mais d’abord... je dois manger. Je ne vais pas attendre ici à mourir comme vous !",
            ["DialogueId"] = 12049254,
            ["GUID"] = "1E29FEBC",
            ["NextDialogue"] = 12049255,
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29FEBC",
            },
        [12049255] = {
            ["Content"] = "你、你…………",
            ["ContentFR"] = "T-Tu... tu...",
            ["DialogueId"] = 12049255,
            ["GUID"] = "1E29FEE6",
            ["NextDialogue"] = 12049256,
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29FEE6",
            },
        [12049256] = {
            ["Content"] = "就要死在这里了吗？尽管心中还留有对死亡的恐惧，但饥饿已经让我连一根手指都无法动弹。",
            ["ContentFR"] = "Allais-je mourir ici ? Je craignais encore la mort... mais la faim m’avait laissée trop faible pour lever un seul doigt.",
            ["DialogueId"] = 12049256,
            ["GUID"] = "1E29FF10",
            ["NextDialogue"] = 12049257,
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29FF10",
            },
        [12049257] = {
            ["Content"] = "此时此刻，唯一能做的，恐怕只有闭上双眼，不去见证自己死亡的一刻吧。",
            ["ContentFR"] = "À cet instant... je ne pouvais que fermer les yeux, pour ne pas voir ma propre fin.",
            ["DialogueId"] = 12049257,
            ["GUID"] = "1E29FF3A",
            ["NextDialogue"] = 12049258,
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29FF3A",
            },
        [12049258] = {
            ["Content"] = "——放开她！！",
            ["ContentFR"] = "— Lâche-la !",
            ["DialogueId"] = 12049258,
            ["GUID"] = "1E29FF64",
            ["NextDialogue"] = 12049259,
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29FF64",
            },
        [12049259] = {
            ["Content"] = "呀！！有人杀人啦！！！",
            ["ContentFR"] = "Il l’a tué ! Meurtre !",
            ["DialogueId"] = 12049259,
            ["GUID"] = "1E29FF8E",
            ["NextDialogue"] = 12049260,
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29FF8E",
            },
        [12049260] = {
            ["Content"] = "那时，我想到了自己各种可能的结局。饿死，或者被那些尖叫着的，昏了头的大人杀掉。",
            ["ContentFR"] = "J’imaginais toutes les fins possibles : mourir de faim... ou être tuée par ces adultes affolés.",
            ["DialogueId"] = 12049260,
            ["GUID"] = "1E29FFB8",
            ["NextDialogue"] = 12049261,
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29FFB8",
            },
        [12049261] = {
            ["Content"] = "我唯独没有想到的是，没过多久，我们就看到了刺眼的阳光，还有那天神一般的应天尉——是的，我们获救了，大风九章的代行者清理开塌方，我们得见天日。",
            ["ContentFR"] = "Je n’avais pas imaginé la lumière aveuglante du soleil. Les Magistrats de Yingtian sont apparus, tels des dieux. Oui — nous avons été sauvés. Les exécutants des Neuf Chapitres ont dégagé l’éboulement et nous ont rendus à la lumière.",
            ["DialogueId"] = 12049261,
            ["GUID"] = "1E29FFE2",
            ["NextDialogue"] = 12049262,
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29FFE2",
            },
        [12049262] = {
            ["Content"] = "我更没有想到的是，让他们赶来的，不是我们绝望的呼号……",
            ["ContentFR"] = "Mais je n’avais pas compris une chose. Ils n’étaient pas venus pour nos cris.",
            ["DialogueId"] = 12049262,
            ["GUID"] = "1E2A000C",
            ["NextDialogue"] = 12049263,
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E2A000C",
            },
        [12049263] = {
            ["Content"] = "而是那个触犯诫律之人。是的，他们来这儿，是为了处决那个男人——我的恩人。",
            ["ContentFR"] = "Ils étaient venus pour l’homme qui avait violé les Préceptes. Oui. Ils étaient venus l’exécuter. Mon sauveur.",
            ["DialogueId"] = 12049263,
            ["GUID"] = "1E2A0036",
            ["NextDialogue"] = 12049264,
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E2A0036",
            },
        [12049264] = {
            ["Content"] = "令夫虽有见义勇为之实，但诛人者受死，是大风九章定死的规矩。如今这下场，实属无奈……还请两位节哀顺变。",
            ["ContentFR"] = "Votre époux a certes agi au nom de la justice... mais ôter une vie est puni de mort. Telle est la loi immuable des Neuf Chapitres.",
            ["DialogueId"] = 12049264,
            ["GUID"] = "1E2A0060",
            ["NextDialogue"] = 12049265,
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E2A0060",
            },
        [12049265] = {
            ["Content"] = "阿爹是大英雄，有什么好节哀的！有爹这样的骄傲，我高兴还来不及！",
            ["ContentFR"] = "Mon père est un héros ! Pourquoi devrions-nous pleurer ? Je suis fier d’avoir un père comme lui !",
            ["DialogueId"] = 12049265,
            ["GUID"] = "1E2A008A",
            ["NextDialogue"] = 12049266,
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E2A008A",
            },
        [12049266] = {
            ["Content"] = "多谢您前后打点。只是，这墓上真不可留名吗？",
            ["ContentFR"] = "Merci pour votre aide... Mais... son nom ne peut vraiment pas être gravé sur la pierre ?",
            ["DialogueId"] = 12049266,
            ["GUID"] = "1E2A00B4",
            ["NextDialogue"] = 12049267,
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E2A00B4",
            },
        [12049267] = {
            ["Content"] = "抱歉，伏天诛之人不可在墓前留名……这是古往今来定下的规矩。",
            ["ContentFR"] = "Je suis désolé. Ceux condamnés par les Cieux ne peuvent laisser leur nom sur une tombe. C’est la règle depuis toujours.",
            ["DialogueId"] = 12049267,
            ["GUID"] = "1E2A00DE",
            ["NextDialogue"] = 12049268,
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E2A00DE",
            },
        [12049268] = {
            ["Content"] = "……我明白了。那我们也不给您再多添麻烦了，我随后便带舟儿移居他处。但这墓还请您多照看，别使杂草淹没了。",
            ["ContentFR"] = "... Je comprends. Nous quitterons le village bientôt. Je vous en prie... veillez sur sa tombe. Ne laissez pas les herbes l’engloutir.",
            ["DialogueId"] = 12049268,
            ["GUID"] = "1E2A0108",
            ["NextDialogue"] = 12049269,
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E2A0108",
            },
        [12049269] = {
            ["Content"] = "当得，当得。",
            ["ContentFR"] = "Je m’en occuperai.",
            ["DialogueId"] = 12049269,
            ["GUID"] = "1E2A0132",
            ["NextDialogue"] = 12049270,
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E2A0132",
            },
        [12049270] = {
            ["Content"] = "没想到村口那个叫刻铭的，平时看起来道貌岸然，却触犯了大风九章定下的诛人罪！",
            ["ContentFR"] = "Qui aurait cru que Keming... si respectable en apparence... ait enfreint la loi capitale des Neuf Chapitres ?",
            ["DialogueId"] = 12049270,
            ["GUID"] = "1E2A015C",
            ["NextDialogue"] = 12049271,
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E2A015C",
            },
        [12049271] = {
            ["Content"] = "我们椒兰村，向来安分守己，谁想到却出了这样一个罪人。真是以后说出去都脸上无光呀。",
            ["ContentFR"] = "Notre village était irréprochable... et voilà qu’un criminel en ternit le nom !",
            ["DialogueId"] = 12049271,
            ["GUID"] = "1E2A0186",
            ["NextDialogue"] = 12049272,
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E2A0186",
            },
        [12049272] = {
            ["Content"] = "赶走，赶紧把那一家人逐出村外！",
            ["ContentFR"] = "Qu’on les chasse ! Toute la famille !",
            ["DialogueId"] = 12049272,
            ["GUID"] = "1E2A01B0",
            ["NextDialogue"] = 12049273,
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E2A01B0",
            },
        [12049273] = {
            ["Content"] = "不是的！他不是罪人，他明明是见义勇为的英雄！",
            ["ContentFR"] = "Ce n’est pas vrai ! Ce n’était pas un criminel ! C’était un héros !",
            ["DialogueId"] = 12049273,
            ["GUID"] = "1E2A01DA",
            ["NextDialogue"] = 12049274,
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E2A01DA",
            },
        [12049274] = {
            ["Content"] = "见义勇为？华胥不需要这种东西。有了大风九章的庇佑，一切等待狴犴和应天尉来解决不就好？",
            ["ContentFR"] = "Un héros ? Huaxu n’a pas besoin de ce genre d’initiative. Les Neuf Chapitres veillent. Il suffit d’attendre que les Bi’an et les Magistrats interviennent.",
            ["DialogueId"] = 12049274,
            ["GUID"] = "1E2A0204",
            ["NextDialogue"] = 12049275,
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E2A0204",
            },
        [12049275] = {
            ["Content"] = "如果应天尉迟到了呢？！如果没有人能帮助受害者呢？",
            ["ContentFR"] = "Et s’ils arrivaient trop tard ? Et s’il n’y avait personne pour sauver les victimes ?",
            ["DialogueId"] = 12049275,
            ["GUID"] = "1E2A022E",
            ["NextDialogue"] = 12049276,
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E2A022E",
            },
        [12049276] = {
            ["Content"] = "迟到？不可能不可能！",
            ["ContentFR"] = "Trop tard ? Impossible !",
            ["DialogueId"] = 12049276,
            ["GUID"] = "1E2A0258",
            ["NextDialogue"] = 12049277,
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E2A0258",
            },
        [12049277] = {
            ["Content"] = "——但若是这种事情当真发生了，也只能算那个人运气不好吧。再怎么说，触犯戒律也是不对的呀！",
            ["ContentFR"] = "... Et même si cela arrivait... ce serait simplement de la malchance. Cela ne justifie pas de violer les Préceptes !",
            ["DialogueId"] = 12049277,
            ["GUID"] = "1E2A0282",
            ["NextDialogue"] = 12049278,
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E2A0282",
            },
        [12049278] = {
            ["Content"] = "若是径直走进这雨幕，就能体验到不一样的视角吗？我试图按他所言去尝试，却只感受到冰冷刺骨的雨水吞没了一切。",
            ["ContentFR"] = "Il disait qu’en marchant sous la pluie, on pouvait changer de perspective. J’ai essayé. Je n’ai senti que le froid. La pluie qui effaçait tout.",
            ["DialogueId"] = 12049278,
            ["GUID"] = "1E2A02AC",
            ["NextDialogue"] = 12049279,
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E2A02AC",
            },
        [12049279] = {
            ["Content"] = "那一天，我茫然地在雨中走着。这是歹徒的错吗？亦或是大风九章酿成的悲剧？还是如他们所说——仅仅是一次坏运气招致的差错？",
            ["ContentFR"] = "Ce jour-là, j’ai erré sous l’averse. Était-ce la faute de l’agresseur ? Des Neuf Chapitres ? Ou simplement... de la malchance ?",
            ["DialogueId"] = 12049279,
            ["GUID"] = "1E2A02D6",
            ["NextDialogue"] = 12049280,
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E2A02D6",
            },
        [12049280] = {
            ["Content"] = "不，不是这样的——我逐渐认识到。那些站在屋檐下的人，他们忘记了雨水的滋味。",
            ["ContentFR"] = "Non... ce n’était pas cela. Peu à peu, je l’ai compris. Ceux qui restent à l’abri sous les toits ont oublié le goût de la pluie.",
            ["DialogueId"] = 12049280,
            ["GUID"] = "1E2A0300",
            ["NextDialogue"] = 12049281,
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E2A0300",
            },
        [12049281] = {
            ["Content"] = "他们变得软弱、冷漠，无法再用自己的意志判断什么是正义，也无法用双手保护自己。屋檐庇护了他们太久，但这种情况不应当再持续下去了。",
            ["ContentFR"] = "Ils deviennent faibles. Indifférents. Incapables de juger le juste du faux. Incapables de se défendre eux-mêmes. L’abri les a protégés trop longtemps. Cela ne doit plus durer.",
            ["DialogueId"] = 12049281,
            ["GUID"] = "1E2A032A",
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E2A032A",
            },
        [12049301] = {
            ["Content"] = "这家伙一定留下了破绽，我们在附近找找看！",
            ["ContentFR"] = "Il a forcément laissé une trace. Cherchons !",
            ["DialogueId"] = 12049301,
            ["GUID"] = "12049301.0",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120493/12049301",
            },
        [12049302] = {
            ["Content"] = "这里什么都没有……再去其他地方看看吧。",
            ["ContentFR"] = "Rien ici... Allons voir ailleurs.",
            ["DialogueId"] = 12049302,
            ["GUID"] = "12049302.0",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120493/12049302",
            },
        [12049303] = {
            ["Content"] = "大功告成！小仆从，我们赶紧回去把香囊还给她吧！",
            ["ContentFR"] = "Mission accomplie ! Petit larbin, retournons vite le lui rendre !",
            ["DialogueId"] = 12049303,
            ["GUID"] = "12049303.0",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120493/12049303",
            },
        [12060101] = {
            ["Content"] = "书接上回，英雄出少年，只见那白发独眼的年轻人提刀出阵，群玄色狴犴便齐齐战栗，退步低吼——",
            ["ContentFR"] = "Reprenons le fil de notre histoire ! Le talent n’attend point le nombre des années ! Voyez cette silhouette aux cheveux d’argent et à l’œil unique : lame en main, elle s’avance au cœur de la mêlée ! Les Bi’an obscurs frémissent à l’unisson, reculant dans un grondement sourd...",
            ["DialogueId"] = 12060101,
            ["GUID"] = "1E30F252",
            ["NextDialogue"] = 12060102,
            ["RelatedWikiId"] = {
                [1] = 408010,
                [2] = 408016,
                [3] = 405014,
                [4] = 405015,
                },
            ["SpeakNpcId"] = 250007,
            ["VoiceName"] = "voice/$Locale$/story/1206/120601/1E30F252",
            },
        [12060102] = {
            ["Content"] = "号外——号外——华胥四年一度的至高盛事，奉香群英试今日召开。想看热门参赛队伍分析？尽在这份《皓京市声报》特刊中——",
            ["ContentFR"] = "Édition spéciale ! Édition spéciale ! L’événement suprême de Huaxu, célébré tous les quatre ans, ouvre aujourd’hui : le Tournoi de l’Encens ! Analyses des équipes favorites et pronostics exclusifs dans ce numéro spécial de <I>L’Écho de Haojing</> !",
            ["DialogueId"] = 12060102,
            ["GUID"] = "1E30F27C",
            ["NextDialogue"] = 12060103,
            ["VoiceName"] = "voice/$Locale$/story/1206/120601/1E30F27C",
            },
        [12060103] = {
            ["Content"] = "老板，小笼包再来一笼，要刚刚出锅皮薄馅大的！",
            ["ContentFR"] = "Patron ! Encore une corbeille de xiaolongbao ! Bien chauds, pâte fine et farce généreuse !",
            ["DialogueId"] = 12060103,
            ["GUID"] = "1E30F2A6",
            ["NextDialogue"] = 12060104,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120601/1E30F2A6",
            },
        [12060104] = {
            ["Content"] = "好嘞——",
            ["ContentFR"] = "Tout de suite !",
            ["DialogueId"] = 12060104,
            ["GUID"] = "1E30F2D0",
            ["NextDialogue"] = 12060105,
            ["SpeakNpcId"] = 250008,
            ["VoiceName"] = "voice/$Locale$/story/1206/120601/1E30F2D0",
            },
        [12060105] = {
            ["Content"] = "嘿嘿，他们要是知道那 “白发独眼”的大英雄就坐在这里，会不会吓一大跳？小仆从，这就是出名的感觉吗！",
            ["ContentFR"] = "Hé hé... S’ils savaient que la légende aux cheveux blancs et à l’œil unique est assise juste ici, ils en avaleraient leurs baguettes ! Alors, petit larbin... c’est ça, être célèbre ?",
            ["DialogueId"] = 12060105,
            ["GUID"] = "1E30F2FA",
            ["NextDialogue"] = 12060106,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120601/1E30F2FA",
            },
        [12060106] = {
            ["Content"] = "吹着小风，在皓京的街头吃吃早茶，听听人来人往的聊天。这才是我们在华胥应当过上的悠闲生活嘛！",
            ["ContentFR"] = "Une petite brise, un thé matinal dans les rues de Haojing, les conversations qui vont et viennent... Voilà la vie tranquille qu’on devrait mener à Huaxu !",
            ["DialogueId"] = 12060106,
            ["GUID"] = "1E30F324",
            ["NextDialogue"] = 12060107,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120601/1E30F324",
            },
        [12060107] = {
            ["Content"] = "…………",
            ["ContentFR"] = "...",
            ["DialogueId"] = 12060107,
            ["GUID"] = "1E30F34E",
            ["NextDialogue"] = 12060108,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120601/1E30F34E",
            },
        [12060108] = {
            ["Content"] = "喂——小仆从——",
            ["ContentFR"] = "Hé ! Petit larbin !",
            ["DialogueId"] = 12060108,
            ["GUID"] = "1E30F378",
            ["NextDialogue"] = 12060109,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120601/1E30F378",
            },
        [12060109] = {
            ["Content"] = "哎？啊，嗯……",
            ["ContentFR"] = "Hein ? Ah... oui ?",
            ["DialogueId"] = 12060109,
            ["GUID"] = "1E30F3A2",
            ["NextDialogue"] = 12060110,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120601/1E30F3A2",
            },
        [12060110] = {
            ["Content"] = "我说，你怎么有点心不在焉的样子？莫非是在担心黎瑟留给你的那个情报？",
            ["ContentFR"] = "T’as l’air complètement ailleurs. Me dis pas que tu penses encore aux infos que Rhythm t’a laissées ?",
            ["DialogueId"] = 12060110,
            ["GUID"] = "1E30F3CC",
            ["NextDialogue"] = 12060111,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120601/1E30F3CC",
            },
        [12060111] = {
            ["Content"] = "是有点……竟然被你看出来了。",
            ["ContentFR"] = "Un peu... Je pensais pas que ça se verrait.",
            ["DialogueId"] = 12060111,
            ["GUID"] = "1E30F3F6",
            ["NextDialogue"] = 12060112,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120601/1E30F3F6",
            },
        [12060112] = {
            ["Content"] = "明明我们在华胥只待了几天，但是发生太多太多事情了，像是过去了很长时间一样。",
            ["ContentFR"] = "On n’est à Huaxu que depuis quelques jours, mais il s’est passé tellement de choses... On dirait des mois.",
            ["DialogueId"] = 12060112,
            ["GUID"] = "1E30F420",
            ["NextDialogue"] = 12060113,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120601/1E30F420",
            },
        [12060113] = {
            ["Content"] = "这些天不在冰湖城，难免会担心会不会再有什么变数。",
            ["ContentFR"] = "Et loin de Givrelac, difficile de ne pas s’inquiéter d’un imprévu.",
            ["DialogueId"] = 12060113,
            ["GUID"] = "1E30F44A",
            ["NextDialogue"] = 12060114,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120601/1E30F44A",
            },
        [12060114] = {
            ["Content"] = "放心吧！止流姐姐拍着胸脯保证，三天后给我们加急安排回冰湖城的空艇一定会启程，这次风雨无阻，什么意外都阻止不了它！",
            ["ContentFR"] = "Mais non ! Zhiliu m’a promis — main sur le cœur — que dans trois jours, un dirigeable décollerait pour Givrelac en priorité absolue ! Cette fois, rien ne l’arrêtera. Ni tempête, ni accident, ni mauvais présage !",
            ["DialogueId"] = 12060114,
            ["GUID"] = "1E30F474",
            ["NextDialogue"] = 12060115,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120601/1E30F474",
            },
        [12060115] = {
            ["Content"] = "我谢谢你，白。本来没太担心的，被你这张乌鸦嘴一说，可就不一定了。",
            ["ContentFR"] = "Merci, Snow... Je n’étais pas si {性别:inquiet|inquiète}, mais maintenant que tu le dis...",
            ["DialogueId"] = 12060115,
            ["GUID"] = "1E30F49E",
            ["NextDialogue"] = 12060116,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120601/1E30F49E",
            },
        [12060116] = {
            ["Content"] = "我、我什么时候乌鸦嘴了，小仆从，你可别乱说话！魔王大人怎么会和那种晦气的属性挂钩！",
            ["ContentFR"] = "Q-quoi ? Depuis quand je porte la poisse ? Petit larbin, fais attention à ce que tu racontes ! Le Roi Démon ne saurait être associé à ce genre de mauvais augure !",
            ["DialogueId"] = 12060116,
            ["GUID"] = "1E30F4C8",
            ["NextDialogue"] = 12060117,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120601/1E30F4C8",
            },
        [12060117] = {
            ["Content"] = "话音刚落，不远处的巷尾就爆发出一阵激烈的争吵声。",
            ["ContentFR"] = "À peine ses mots prononcés, une dispute éclate au bout d’une ruelle.",
            ["DialogueId"] = 12060117,
            ["GUID"] = "1E30F4F2",
            ["NextDialogue"] = 12060118,
            ["VoiceName"] = "voice/$Locale$/story/1206/120601/1E30F4F2",
            },
        [12060118] = {
            ["Content"] = "……这、这是什么玩意？！……",
            ["ContentFR"] = "Q-qu’est-ce que c’est que ce truc ?! ...",
            ["DialogueId"] = 12060118,
            ["GUID"] = "1E30F51C",
            ["NextDialogue"] = 12060119,
            ["VoiceName"] = "voice/$Locale$/story/1206/120601/1E30F51C",
            },
        [12060119] = {
            ["Content"] = "哇，那边有人吵起来了，小仆从，我们赶紧去看看！去晚了可凑不上新鲜的热闹了！",
            ["ContentFR"] = "Oh ! Ça s’agite là-bas ! Viens, Petit larbin ! Si on traîne, on va rater le meilleur !",
            ["DialogueId"] = 12060119,
            ["GUID"] = "1E30F546",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120601/1E30F546",
            },
        [12060201] = {
            ["Content"] = "等等，你们听我解释，事情绝对不是你们想的那样——",
            ["ContentFR"] = "Attendez ! Laissez-moi vous expliquer, ce n’est pas du tout ce que vous croyez !",
            ["DialogueId"] = 12060201,
            ["GUID"] = "1E3102BA",
            ["NextDialogue"] = 12060202,
            ["RelatedWikiId"] = {
                [1] = 408010,
                [2] = 408016,
                [3] = 203009,
                [4] = 103001,
                [5] = 405014,
                [6] = 405015,
                },
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120602/1E3102BA",
            },
        [12060202] = {
            ["Content"] = "咳咳，苏乙姑娘，我突然想起来家里有点急事。",
            ["ContentFR"] = "Mademoiselle Su Yi... je viens de me souvenir d’une affaire urgente à régler.",
            ["DialogueId"] = 12060202,
            ["GUID"] = "1E3102E4",
            ["NextDialogue"] = 12060203,
            ["SpeakNpcId"] = 250009,
            ["VoiceName"] = "voice/$Locale$/story/1206/120602/1E3102E4",
            },
        [12060203] = {
            ["Content"] = "瞧我这脑子，早上出门前老娘还叮嘱过我呢，一转眼就忘了。我就先告辞了哈。",
            ["ContentFR"] = "Quelle tête en l’air je fais... Ma mère m’avait encore bien rappelé quelque chose avant que je parte ce matin, et je l’ai oublié en un clin d’œil... Je vais y aller. Excusez-moi.",
            ["DialogueId"] = 12060203,
            ["GUID"] = "1E31030E",
            ["NextDialogue"] = 12060204,
            ["SpeakNpcId"] = 250009,
            ["VoiceName"] = "voice/$Locale$/story/1206/120602/1E31030E",
            },
        [12060204] = {
            ["Content"] = "苏乙姑娘，我……",
            ["ContentFR"] = "Mademoiselle Su Yi, je...",
            ["DialogueId"] = 12060204,
            ["GUID"] = "1E310338",
            ["NextDialogue"] = 12060205,
            ["SpeakNpcId"] = 250010,
            ["VoiceName"] = "voice/$Locale$/story/1206/120602/1E310338",
            },
        [12060205] = {
            ["Content"] = "你又有什么借口，家中有事，还是突发恶疾？",
            ["ContentFR"] = "Et toi ? Une urgence ? Une maladie soudaine ?",
            ["DialogueId"] = 12060205,
            ["GUID"] = "1E310362",
            ["NextDialogue"] = 12060206,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120602/1E310362",
            },
        [12060206] = {
            ["Content"] = "……违心的话我说不出来，苏乙姑娘，我还是实情相告吧。和飘零人组队这种事情，我恐怕做不到。",
            ["ContentFR"] = "... Je ne peux pas vous mentir. Faire équipe avec une Vagabonde... je ne m’en sens pas capable.",
            ["DialogueId"] = 12060206,
            ["GUID"] = "1E31038C",
            ["NextDialogue"] = 12060207,
            ["SpeakNpcId"] = 250010,
            ["VoiceName"] = "voice/$Locale$/story/1206/120602/1E31038C",
            },
        [12060207] = {
            ["Content"] = "我知道飘零人并非什么十恶不赦的坏人，你们也有你们的苦衷。但稳妥起见，为了在这届群英试中拿到好名次，我不想招惹太多麻烦。",
            ["ContentFR"] = "Je sais que vous n’êtes pas des criminels. Mais je veux assurer mes chances au Tournoi de l’Encens. Je ne peux pas me permettre d’ennuis.",
            ["DialogueId"] = 12060207,
            ["GUID"] = "1E3103B6",
            ["NextDialogue"] = 12060208,
            ["SpeakNpcId"] = 250010,
            ["VoiceName"] = "voice/$Locale$/story/1206/120602/1E3103B6",
            },
        [12060208] = {
            ["Content"] = "呜……好吧，至少谢谢你愿意说出真话。",
            ["ContentFR"] = "... D’accord. Merci au moins pour ta franchise.",
            ["DialogueId"] = 12060208,
            ["GUID"] = "1E3103E0",
            ["NextDialogue"] = 12060209,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120602/1E3103E0",
            },
        [12060209] = {
            ["Content"] = "苏乙姑娘，我多嘴一句。你知道的，大家对飘零人多少还是有点……介怀，至少短时间内是这样。这次群英试，你的麻烦恐怕还在后头。",
            ["ContentFR"] = "Mademoiselle Su Yi... si je peux me permettre une remarque. Vous le savez... les gens restent malgré tout... un peu mal à l’aise avec les Vagabonds. Du moins, pour l’instant. Et pour le Tournoi de l’Encens... j’ai bien peur que vos difficultés ne soient encore devant vous.",
            ["DialogueId"] = 12060209,
            ["GUID"] = "1E31040A",
            ["NextDialogue"] = 12060210,
            ["SpeakNpcId"] = 250010,
            ["VoiceName"] = "voice/$Locale$/story/1206/120602/1E31040A",
            },
        [12060210] = {
            ["Content"] = "抱歉。祝你能找到称心如意的队友。",
            ["ContentFR"] = "Pardonnez-moi. Je vous souhaite de trouver des compagnons à votre mesure.",
            ["DialogueId"] = 12060210,
            ["GUID"] = "1E310434",
            ["NextDialogue"] = 12060211,
            ["SpeakNpcId"] = 250010,
            ["VoiceName"] = "voice/$Locale$/story/1206/120602/1E310434",
            },
        [12060211] = {
            ["Content"] = "唉，怎么会变成这样……",
            ["ContentFR"] = "Comment ça a pu tourner comme ça... ?",
            ["DialogueId"] = 12060211,
            ["GUID"] = "1E31045E",
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120602/1E31045E",
            },
        [12060301] = {
            ["Content"] = "你还好吗，苏乙？",
            ["ContentFR"] = "Ça va, Su Yi ?",
            ["DialogueId"] = 12060301,
            ["GUID"] = "1E311322",
            ["NextDialogue"] = 12060302,
            ["RelatedWikiId"] = {
                [1] = 408010,
                [2] = 408016,
                [3] = 203009,
                [4] = 103001,
                [5] = 405014,
                [6] = 405015,
                },
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120603/1E311322",
            },
        [12060302] = {
            ["Content"] = "哇啊啊！{nickname}，还有小白，你们怎么来了？刚才那一幕该不会都被你们看到了吧？！",
            ["ContentFR"] = "Aah ! {nickname} ?! Et Snow aussi ?! Ne me dis pas que vous avez tout vu... du début à la fin ?!",
            ["DialogueId"] = 12060302,
            ["GUID"] = "1E31134C",
            ["NextDialogue"] = 12060303,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120603/1E31134C",
            },
        [12060303] = {
            ["Content"] = "怎么老是被你们撞见落魄的时刻……比起这样，我还是更想在你们心中留下一些光辉形象……",
            ["ContentFR"] = "Sérieusement... pourquoi est-ce que vous tombez toujours sur moi pile dans ce genre de moment... ? J’aimerais quand même vous laisser une image un peu plus brillante de moi...",
            ["DialogueId"] = 12060303,
            ["GUID"] = "1E311376",
            ["NextOptions"] = {
                [1] = 12060304,
                [2] = 12060305,
                },
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120603/1E311376",
            },
        [12060304] = {
            ["Content"] = "所以发生了什么？",
            ["ContentFR"] = "<I>Qu’est-ce qu’il s’est passé ?</>",
            ["DialogueId"] = 12060304,
            ["GUID"] = "1E3113A0",
            ["ImprPlusId"] = 1204,
            ["NextDialogue"] = 12060307,
            },
        [12060305] = {
            ["Content"] = "抱歉，我突然想起来家里有点急事。",
            ["ContentFR"] = "<I>{性别:Désolé|Désolée}, je viens justement de me souvenir d’une affaire urgente.</>",
            ["DialogueId"] = 12060305,
            ["GUID"] = "1E3113CA",
            ["ImprPlusId"] = 1205,
            ["NextDialogue"] = 12060306,
            },
        [12060306] = {
            ["Content"] = "好了好了，知道你从一开始就在了——不用再戳一次本姑娘的伤心事啦！",
            ["ContentFR"] = "Oui, oui... je sais que t’as tout vu. Pas la peine d’en rajouter !",
            ["DialogueId"] = 12060306,
            ["GUID"] = "1E3113F4",
            ["NextDialogue"] = 12060307,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120603/1E3113F4",
            },
        [12060307] = {
            ["Content"] = "我听你们提到了群英试，刚刚的事情和这个有关吗？",
            ["ContentFR"] = "J’ai entendu parler du Tournoi. C’est lié à ça ?",
            ["DialogueId"] = 12060307,
            ["GUID"] = "1E31141E",
            ["NextDialogue"] = 12060308,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120603/1E31141E",
            },
        [12060308] = {
            ["Content"] = "哎？小白，{nickname}，你们难不成也知道今日要召开的<H>奉香群英试</>？",
            ["ContentFR"] = "Hein ? Snow, {nickname}... ne me dites pas que vous êtes au courant pour le <H>Tournoi de l’Encens</> d’aujourd’hui, vous aussi ?",
            ["DialogueId"] = 12060308,
            ["GUID"] = "1E311448",
            ["NextDialogue"] = 12060309,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120603/1E311448",
            },
        [12060309] = {
            ["Content"] = "当然知道啦，我已经听人们讨论了一早上了！这一定像银烛狂欢一样，是华胥这边很重要的节日吧，就算前面出了这么大的事，还是要如期举行呢。",
            ["ContentFR"] = "Bien sûr que oui ! On n’entend parler que de ça depuis ce matin ! Ça doit être un événement aussi important que la Fête de la Chandelle d’Argent, non ? Même après tout ce qui s’est passé, la cérémonie a lieu comme prévu !",
            ["DialogueId"] = 12060309,
            ["GUID"] = "1E311472",
            ["NextDialogue"] = 12060310,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120603/1E311472",
            },
        [12060310] = {
            ["Content"] = "嗯，虽然不确定你说的银烛狂欢具体是什么样的，但应该差不多！",
            ["ContentFR"] = "Hmm... je ne sais pas exactement à quoi ressemble ta fête, mais oui, ça doit être à peu près du même ordre !",
            ["DialogueId"] = 12060310,
            ["GUID"] = "1E31149C",
            ["NextDialogue"] = 12060311,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120603/1E31149C",
            },
        [12060311] = {
            ["Content"] = "<H>奉香大典</>可以追溯到大风九章建立之初，是非常古老的节日哦。每年，华胥人在“奉香人”的带领下，在执律阁向龙神奉香，祈求神明庇佑华胥海晏河清，永世太平。",
            ["ContentFR"] = "La Cérémonie de l’Encens remonte à la fondation des Neuf Chapitres de Dafeng. C’est une tradition très ancienne. Chaque année, sous la conduite de l’Émissaire de l’Encens, les habitants de Huaxu se rendent au Pavillon de l’Arbitrage pour offrir l’encens au Seigneur Dragon d’Argent et prier pour que règnent paix et prospérité éternelles.",
            ["DialogueId"] = 12060311,
            ["GUID"] = "1E3114C6",
            ["NextDialogue"] = 12060312,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120603/1E3114C6",
            },
        [12060312] = {
            ["Content"] = "而<H>奉香群英试</>则是为了选出一位最有资格带领华胥人与神明沟通的“奉香人”。对华胥人来说，这几乎是最光耀门楣，万众瞩目的事了。",
            ["ContentFR"] = "Quant au <H>Tournoi de l’Encens</>, il sert à choisir la personne la plus digne de mener la cérémonie et de parler au nom de Huaxu devant la divinité. Pour les habitants d’ici, c’est presque l’honneur suprême — celui qui illumine toute une lignée et attire tous les regards.",
            ["DialogueId"] = 12060312,
            ["GUID"] = "1E3114F0",
            ["NextDialogue"] = 12060313,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120603/1E3114F0",
            },
        [12060313] = {
            ["Content"] = "每届奉香大典前，群英试都会如期举办。不过每一届的赛事都不太一样，之前的我也不太清楚……不过我看了今年的赛事安排，居然连我们飘零人都能发挥所长呢！",
            ["ContentFR"] = "À chaque édition de la Cérémonie de l’Encens, le Tournoi se tient comme prévu. Mais les épreuves changent à chaque fois, alors je n’y avais jamais vraiment prêté attention... Cette année, pourtant... certaines épreuves semblent même permettre aux Vagabonds de faire valoir leurs talents.",
            ["DialogueId"] = 12060313,
            ["GUID"] = "1E31151A",
            ["NextDialogue"] = 12060314,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120603/1E31151A",
            },
        [12060314] = {
            ["Content"] = "所以，我也想试上一试。",
            ["ContentFR"] = "Alors... j’ai voulu tenter ma chance.",
            ["DialogueId"] = 12060314,
            ["GUID"] = "1E311544",
            ["NextDialogue"] = 12060315,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120603/1E311544",
            },
        [12060315] = {
            ["Content"] = "只是，今年的赛制需要三人结伴成队。我就偷偷瞒着山外山的人溜出来，拉了两个好奇的路人组队。哪知他们一听说我是飘零人，就脚底一抹油溜了……唉！",
            ["ContentFR"] = "Seulement voilà : cette année, il faut former une équipe de trois. Je me suis éclipsée des Pics Extérieurs sans rien dire, et j’ai essayé de recruter deux passants curieux. Mais dès qu’ils ont appris que j’étais une Vagabonde... ils ont filé sans demander leur reste... <I>pff !</>",
            ["DialogueId"] = 12060315,
            ["FinalDialogueId"] = 12060323,
            ["GUID"] = "1E31156E",
            ["NextOptions"] = {
                [1] = 12060316,
                [2] = 12060320,
                },
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120603/1E31156E",
            },
        [12060316] = {
            ["Content"] = "为什么要瞒着山外山？",
            ["ContentFR"] = "<I>Pourquoi le cacher aux Pics Extérieurs ?</>",
            ["DialogueId"] = 12060316,
            ["GUID"] = "1E311598",
            ["NextDialogue"] = 12060317,
            },
        [12060317] = {
            ["Content"] = "那、那个，唐叔那人你也知道，又唠叨又爱操心。要是和他说了我要参赛，他一定会搞得人尽皆知。到时候如果他带一群人来看热闹，我可丢不起这个人……",
            ["ContentFR"] = "Euh... tu connais Oncle Tang. Toujours à s’inquiéter, toujours à râler... Si je lui avais dit que je participais, tout le monde l’aurait su avant la fin de la journée. Et s’il débarquait avec une bande de curieux pour \"m’encourager\".. je ne m’en remettrais pas...",
            ["DialogueId"] = 12060317,
            ["GUID"] = "1E3115C2",
            ["NextDialogue"] = 12060318,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120603/1E3115C2",
            },
        [12060318] = {
            ["Content"] = "（又唠叨又爱操心……你确定说的不是自己吗？）",
            ["ContentFR"] = "<I>Toujours à râler et à s’inquiéter... tu es sûre que tu ne parles pas de toi ?</>",
            ["DialogueId"] = 12060318,
            ["DisableMouth"] = 1,
            ["GUID"] = "1E3115EC",
            ["NextDialogue"] = 12060319,
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120603/1E3115EC",
            },
        [12060319] = {
            ["Content"] = "而且，很多飘零人还是对山外山外面的世界有戒心，一时半会儿也不好改过来，免不了要反对我参赛。在给他们一个大大的惊喜之前，我就先不走露风声啦。",
            ["ContentFR"] = "Et puis beaucoup de Vagabonds restent méfiants envers le monde au-delà des Pics Extérieurs. Ça ne change pas du jour au lendemain. Ils auraient sûrement essayé de m’en dissuader. Alors avant de leur offrir une énorme surprise... je préfère garder ça pour moi.",
            ["DialogueId"] = 12060319,
            ["GUID"] = "1E311616",
            ["NextDialogue"] = 12060315,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120603/1E311616",
            },
        [12060320] = {
            ["Content"] = "参加奉香群英试有什么好处吗？",
            ["ContentFR"] = "<I>Participer au Tournoi de l’Encens, ça apporte quoi ?</>",
            ["DialogueId"] = 12060320,
            ["GUID"] = "1E311640",
            ["NextDialogue"] = 12060321,
            },
        [12060321] = {
            ["Content"] = "刚刚说了，在奉香群英试上夺魁是华胥的最高荣誉之一！",
            ["ContentFR"] = "Je viens de le dire ! Remporter le Tournoi de l’Encens, c’est l’un des plus grands honneurs de Huaxu !",
            ["DialogueId"] = 12060321,
            ["GUID"] = "1E31166A",
            ["NextDialogue"] = 12060322,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120603/1E31166A",
            },
        [12060322] = {
            ["Content"] = "我、我想让全华胥人看到……飘零人不是什么阴沟老鼠，什么法外狂徒，我们也可以非常非常了不起！",
            ["ContentFR"] = "Je... je veux que tous voient que les Vagabonds ne sont ni des rats d’égout ni des hors-la-loi. Nous aussi, on peut accomplir quelque chose de remarquable. De vraiment remarquable !",
            ["DialogueId"] = 12060322,
            ["GUID"] = "1E311694",
            ["NextDialogue"] = 12060315,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120603/1E311694",
            },
        [12060323] = {
            ["Content"] = "总而言之，今天出门真是诸事不顺。再这样下去，我都要考虑去算上一卦转转运了……",
            ["ContentFR"] = "Bref... aujourd’hui, rien ne va. Si ça continue, je vais finir par consulter un maître en divination pour changer ma chance...",
            ["DialogueId"] = 12060323,
            ["GUID"] = "1E3116BE",
            ["NextDialogue"] = 12060324,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120603/1E3116BE",
            },
        [12060324] = {
            ["Content"] = "说起来，飘零人三个字又没写在你脑门上，好好的怎么会身份暴露？难不成你现在也是城里的大名人了嘛？",
            ["ContentFR"] = "Attends... « Vagabonde » n’est pas écrit sur ton front. Comment ils ont su ? T’es devenue une célébrité locale ou quoi ? ",
            ["DialogueId"] = 12060324,
            ["GUID"] = "1E3116E8",
            ["NextDialogue"] = 12060325,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120603/1E3116E8",
            },
        [12060325] = {
            ["Content"] = "呜，那倒没有啦……这就要说到我为这次群英试特意准备的“矩子巡枢贰型·青鸾”了，简称青鸾贰型，这可是我的制胜绝招！",
            ["ContentFR"] = "Euh... non, pas du tout... C’est à cause de ce que j’ai spécialement préparé pour le Tournoi : le Module de Patrouille Juzi – Type II : Qingluan. En abrégé, Qingluan Type II. C’est mon atout décisif !",
            ["DialogueId"] = 12060325,
            ["GUID"] = "1E311712",
            ["NextDialogue"] = 12060326,
            ["RelatedWikiId"] = {
                [1] = 403009,
                },
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120603/1E311712",
            },
        [12060326] = {
            ["Content"] = "矩子什么什么……虽然不太明白，但是这么长的名字，一听就很有实力。魔王大人表示认可！",
            ["ContentFR"] = "Juzi... truc... machin... Je ne comprends pas un mot, mais avec un nom aussi long, ça ne peut qu’être puissant ! Le Roi Démon approuve !",
            ["DialogueId"] = 12060326,
            ["GUID"] = "1E31173C",
            ["NextDialogue"] = 12060327,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120603/1E31173C",
            },
        [12060327] = {
            ["Content"] = "（倒也不是名字越长就越拉风啦……）",
            ["ContentFR"] = "<I>Ce n’est pas parce qu’un nom est long que c’est plus impressionnant...</>",
            ["DialogueId"] = 12060327,
            ["DisableMouth"] = 1,
            ["GUID"] = "1E311766",
            ["NextDialogue"] = 12060328,
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120603/1E311766",
            },
        [12060328] = {
            ["Content"] = "我原本和队友们约定好，进了赛场就兵分两路，准备单独行动时再把青鸾贰型拿出来。所以用包袱皮将它裹得严严实实的。",
            ["ContentFR"] = "On avait prévu de se séparer une fois dans l’arène. Je ne devais sortir le Qingluan Type II que lorsque j’agirais seule. Je l’avais soigneusement enveloppé dans une toile pour le dissimuler.",
            ["DialogueId"] = 12060328,
            ["GUID"] = "1E311790",
            ["NextDialogue"] = 12060329,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120603/1E311790",
            },
        [12060329] = {
            ["Content"] = "结果包袱皮不知道怎么的突然散开了。我先前给它加装了一些……咳咳，重火力的先进模块，还没来得及掩饰。别人一看到就暴露了。",
            ["ContentFR"] = "Mais je ne sais pas comment... l’emballage s’est défait. Et j’y avais installé... hum... des modules d’artillerie avancés. Je n’avais pas encore eu le temps de les camoufler. Il a suffi d’un regard pour comprendre que j’étais une Vagabonde.",
            ["DialogueId"] = 12060329,
            ["GUID"] = "1E3117BA",
            ["NextDialogue"] = 12060330,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120603/1E3117BA",
            },
        [12060330] = {
            ["Content"] = "在哪里在哪里，这么有意思的东西，我也要看！",
            ["ContentFR"] = "Où ça, où ça ? Ça a l’air génial ! Je veux voir, moi aussi !",
            ["DialogueId"] = 12060330,
            ["GUID"] = "1E3117E4",
            ["NextDialogue"] = 12060331,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120603/1E3117E4",
            },
        [12060331] = {
            ["Content"] = "喏，就放在我背后的桌子上。",
            ["ContentFR"] = "Là, sur la table derrière moi.",
            ["DialogueId"] = 12060331,
            ["GUID"] = "1E31180E",
            ["NextDialogue"] = 12060332,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120603/1E31180E",
            },
        [12060332] = {
            ["Content"] = "苏乙，你说的那个青鸾贰型，难不成是一截章鱼触手的模样？",
            ["ContentFR"] = "Su Yi... ton Qingluan Type II... ça ne ressemblerait pas à une tentacule, par hasard ?",
            ["DialogueId"] = 12060332,
            ["GUID"] = "1E311838",
            ["NextDialogue"] = 12060333,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120603/1E311838",
            },
        [12060333] = {
            ["Content"] = "嗯，怎么可能？本姑娘的得意作品，自然是以乙鸟为原型。",
            ["ContentFR"] = "Hein ?! Bien sûr que non ! Mon chef-d’œuvre est inspiré de l’Oiseau Yi !",
            ["DialogueId"] = 12060333,
            ["GUID"] = "1E311862",
            ["NextDialogue"] = 12060334,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120603/1E311862",
            },
        [12060334] = {
            ["Content"] = "再说了，谁会选择章鱼触手作为机傀的外型啊。湿哒哒的满是粘液，仿生细节处理起来还很麻烦。只能说是没品味！",
            ["ContentFR"] = "Et puis franchement, qui choisirait une tentacule comme forme pour une méchapoupée ? C’est humide, gluant, et la biomimétique serait un cauchemar à ajuster. Il faut vraiment manquer de goût !",
            ["DialogueId"] = 12060334,
            ["GUID"] = "1E31188C",
            ["NextDialogue"] = 12060335,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120603/1E31188C",
            },
        [12060335] = {
            ["Content"] = "不好，是小贼！我倾注了无数个日夜的心血才造出来的青鸾贰型！",
            ["ContentFR"] = "Non... c’est un voleur ! J’ai consacré d’innombrables jours et nuits au Qingluan Type II !",
            ["DialogueId"] = 12060335,
            ["GUID"] = "1E3118B6",
            ["NextDialogue"] = 12060336,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120603/1E3118B6",
            },
        [12060336] = {
            ["Content"] = "触手往那个方向去了，我们快追！",
            ["ContentFR"] = "La tentacule est partie par là ! Vite, poursuivons-la !",
            ["DialogueId"] = 12060336,
            ["GUID"] = "1E3118E0",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120603/1E3118E0",
            },
        [12060337] = {
            ["Content"] = "地上有粘液，小贼一定来过这里！",
            ["ContentFR"] = "Il y a des traces de mucus au sol ! Le voleur est passé par ici !",
            ["DialogueId"] = 12060337,
            ["GUID"] = "1E31190A",
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120603/1E31190A",
            },
        [12060338] = {
            ["Content"] = "小仆从，好像不是这边……",
            ["ContentFR"] = "Petit larbin... je crois que ce n’est pas par là...",
            ["DialogueId"] = 12060338,
            ["GUID"] = "1E311934",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120603/1E311934",
            },
        [12060339] = {
            ["Content"] = "小贼逃进巷口了。{nickname}，小白，我们兵分两路！",
            ["ContentFR"] = "Le voleur a dû s’engouffrer dans cette ruelle. {nickname}, Snow, on se sépare !",
            ["DialogueId"] = 12060339,
            ["GUID"] = "1E31195E",
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120603/1E31195E",
            },
        [12060401] = {
            ["Content"] = "嘻嘻，你们来啦！那位大盗刚刚翻墙跑走了，你们赶紧追上去，我断后！",
            ["ContentFR"] = "Hihi, vous voilà ! Le grand voleur vient juste de franchir le mur ! Dépêchez-vous de le poursuivre, je couvre l’arrière !",
            ["DialogueId"] = 12060401,
            ["GUID"] = "1E31238A",
            ["NextDialogue"] = 12060402,
            ["SpeakNpcId"] = 250029,
            ["VoiceName"] = "voice/$Locale$/story/1206/120604/1E31238A",
            },
        }
  end },
  { MinKey = 12060402, MaxKey = 12061110, Loader = function()
      return {
        [12060402] = {
            ["Content"] = "苏乙，你说话怎么怪怪的？",
            ["ContentFR"] = "Su Yi... tu ne trouves pas que tu parles bizarrement ?",
            ["DialogueId"] = 12060402,
            ["GUID"] = "1E3123B4",
            ["NextDialogue"] = 12060403,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120604/1E3123B4",
            },
        [12060403] = {
            ["Content"] = "怪吗？大概是刚刚跑的太急，咬到舌头了。",
            ["ContentFR"] = "Bizarrement ? Peut-être que j’ai mordu ma langue en courant.",
            ["DialogueId"] = 12060403,
            ["GUID"] = "1E3123DE",
            ["NextDialogue"] = 12060404,
            ["SpeakNpcId"] = 250029,
            ["VoiceName"] = "voice/$Locale$/story/1206/120604/1E3123DE",
            },
        [12060404] = {
            ["Content"] = "不要在意这种细节啦，再耽误时间，那个家伙就要逃掉了！",
            ["ContentFR"] = "Ne t’arrête pas pour des détails ! Si on traîne, il va filer !",
            ["DialogueId"] = 12060404,
            ["GUID"] = "1E312408",
            ["NextDialogue"] = 12060405,
            ["SpeakNpcId"] = 250029,
            ["VoiceName"] = "voice/$Locale$/story/1206/120604/1E312408",
            },
        [12060405] = {
            ["Content"] = "……苏乙，你还记得我们在找的是什么吗？",
            ["ContentFR"] = "... Su Yi. Tu te souviens au moins de ce qu’on est en train de récupérer ?",
            ["DialogueId"] = 12060405,
            ["GUID"] = "1E312432",
            ["NextDialogue"] = 12060406,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120604/1E312432",
            },
        [12060406] = {
            ["Content"] = "当然记得啊，不就是一个怪模怪样的机关鸟吗？",
            ["ContentFR"] = "Bien sûr. Un machin d’oiseau mécanique bizarre, non ?",
            ["DialogueId"] = 12060406,
            ["GUID"] = "1E31245C",
            ["NextDialogue"] = 12060407,
            ["SpeakNpcId"] = 250029,
            ["VoiceName"] = "voice/$Locale$/story/1206/120604/1E31245C",
            },
        [12060407] = {
            ["Content"] = "什么机关鸟，那可是做了最新改装的“矩子巡枢贰型·青鸾”！",
            ["ContentFR"] = "« Machin d’oiseau mécanique » ?! C’est le Module de Patrouille Juzi – Type II : Qingluan, fraîchement amélioré !",
            ["DialogueId"] = 12060407,
            ["GUID"] = "1E312486",
            ["NextDialogue"] = 12060408,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120604/1E312486",
            },
        [12060408] = {
            ["Content"] = "不仅偷走我的东西，还装成本姑娘的样子说出这么没文化的话，简直不可饶恕！",
            ["ContentFR"] = "Non seulement tu voles ma création, mais en plus tu prends mon apparence pour débiter des absurdités pareilles ?! C’est impardonnable !",
            ["DialogueId"] = 12060408,
            ["GUID"] = "1E3124B0",
            ["NextDialogue"] = 12060409,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120604/1E3124B0",
            },
        [12060409] = {
            ["Content"] = "啧……真是难缠。",
            ["ContentFR"] = "<I>Tss...</> quelle plaie.",
            ["DialogueId"] = 12060409,
            ["GUID"] = "1E3124DA",
            ["SpeakNpcId"] = 250029,
            ["VoiceName"] = "voice/$Locale$/story/1206/120604/1E3124DA",
            },
        [12060501] = {
            ["Content"] = "束手就擒吧，小贼！",
            ["ContentFR"] = "Rends-toi, petite voleuse !",
            ["DialogueId"] = 12060501,
            ["GUID"] = "1E3133F2",
            ["NextDialogue"] = 12060502,
            ["RelatedWikiId"] = {
                [1] = 405014,
                [2] = 405015,
                [3] = 203009,
                [4] = 403009,
                },
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120605/1E3133F2",
            },
        [12060502] = {
            ["Content"] = "嘻嘻嘻……什么小贼、小贼的，我可是大名鼎鼎的恶魔大盗塔比瑟，别搞错了！",
            ["ContentFR"] = "Hihi... petite voleuse ? Fais attention à tes mots. Je suis le célèbre Démon Tabethe, la Main Rouge. Ne te trompe pas de titre !",
            ["DialogueId"] = 12060502,
            ["GUID"] = "1E31341C",
            ["NextDialogue"] = 12060503,
            ["RelatedWikiId"] = {
                [1] = 201029,
                },
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120605/1E31341C",
            },
        [12060503] = {
            ["Content"] = "恶魔大盗？吹得这么厉害，结果还不是我们小仆从的手下败将。要我说，含金量比不上光之魔王大人的一根毫毛！",
            ["ContentFR"] = "« Démon Tabethe, la Main Rouge », vraiment ? Avec un titre pareil, je m’attendais à mieux... Et te voilà déjà battue par mon petit larbin. Face au Roi Démon, tu n’es qu’un grain de poussière !",
            ["DialogueId"] = 12060503,
            ["GUID"] = "1E313446",
            ["NextDialogue"] = 12060504,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120605/1E313446",
            },
        [12060504] = {
            ["Content"] = "呜呜……你们两个大人一起欺负我这个柔弱可怜又无助的小女孩，这不公平！",
            ["ContentFR"] = "<I>Bouhou...</> vous êtes deux adultes à intimider une pauvre petite fille fragile, innocente et sans défense... c’est injuste !",
            ["DialogueId"] = 12060504,
            ["GUID"] = "1E313470",
            ["NextDialogue"] = 12060505,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120605/1E313470",
            },
        [12060505] = {
            ["Content"] = "要不我们单挑再试试？",
            ["ContentFR"] = "Si vous avez vraiment du cran... on règle ça en un contre un ?",
            ["DialogueId"] = 12060505,
            ["GUID"] = "1E31349A",
            ["NextOptions"] = {
                [1] = 12060506,
                [2] = 12060507,
                },
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120605/1E31349A",
            },
        [12060506] = {
            ["Content"] = "这招对我没用。",
            ["ContentFR"] = "<I>Cette comédie ne marche pas avec moi.</>",
            ["DialogueId"] = 12060506,
            ["GUID"] = "1E3134C4",
            ["ImprPlusId"] = 1203,
            ["NextDialogue"] = 12060508,
            },
        [12060507] = {
            ["Content"] = "嘤嘤嘤，我也是小孩子……",
            ["ContentFR"] = "<I>Bouhou... moi aussi je suis un enfant fragile...</>",
            ["DialogueId"] = 12060507,
            ["GUID"] = "1E3134EE",
            ["ImprPlusId"] = 1205,
            ["NextDialogue"] = 12060508,
            },
        [12060508] = {
            ["Content"] = "别想着蒙混过关。我的青鸾贰型呢？赶紧交出来。要是哪里的元件折了断了，十个你都赔不起！",
            ["ContentFR"] = "Épargne-nous ton numéro. Où est mon Qingluan Type II ? Rends-le-moi immédiatement. Et si une seule pièce est endommagée... tu n’auras pas de quoi payer les réparations.",
            ["DialogueId"] = 12060508,
            ["GUID"] = "1E313518",
            ["NextDialogue"] = 12060509,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120605/1E313518",
            },
        [12060509] = {
            ["Content"] = "嘻嘻……藏在哪里了呢？不如来猜一猜～猜中了有惊喜哟。",
            ["ContentFR"] = "Hihi... où ai-je bien pu le cacher ? Et si tu essayais de deviner ? Si tu trouves, il y aura peut-être une surprise~",
            ["DialogueId"] = 12060509,
            ["GUID"] = "1E313542",
            ["NextDialogue"] = 12060510,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120605/1E313542",
            },
        [12060510] = {
            ["Content"] = "先给你一个小小提示，恶魔大盗藏东西的伪装天衣无缝，你就算在原地跳脚，把这里翻个底朝天也找不出来哟～",
            ["ContentFR"] = "Un petit indice : les cachettes du Démon Tabethe sont sans la moindre faille. Même si tu trépignes sur place et retournes tout ce coin de fond en comble, tu ne trouveras rien~",
            ["DialogueId"] = 12060510,
            ["GUID"] = "1E31356C",
            ["NextDialogue"] = 12060511,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120605/1E31356C",
            },
        [12060511] = {
            ["Content"] = "……我说，我怎么感觉你好像有点针对我的意思？",
            ["ContentFR"] = "... Dis-moi, tu sembles avoir quelque chose contre moi, non ?",
            ["DialogueId"] = 12060511,
            ["GUID"] = "1E313596",
            ["NextDialogue"] = 12060512,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120605/1E313596",
            },
        [12060512] = {
            ["Content"] = "我们明明素不相识，那牵机鸢你拿着也不好销赃。你若是实在缺钱，我向你赎回来就是了。",
            ["ContentFR"] = "Nous ne nous connaissons même pas. Et ce genre d’objet n’est pas facile à écouler. Si tu manques d’argent, je peux simplement te le racheter.",
            ["DialogueId"] = 12060512,
            ["GUID"] = "1E3135C0",
            ["NextDialogue"] = 12060513,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120605/1E3135C0",
            },
        [12060513] = {
            ["Content"] = "但青鸾贰型是我的心血，对我来说非常重要，请你尽快还给我。",
            ["ContentFR"] = "Mais le Qingluan Type II représente tout mon travail. Il compte énormément pour moi. S’il te plaît, rends-le-moi.",
            ["DialogueId"] = 12060513,
            ["GUID"] = "1E3135EA",
            ["NextDialogue"] = 12060514,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120605/1E3135EA",
            },
        [12060514] = {
            ["Content"] = "嘁……你可别误会一点。恶魔大盗只偷坏人的东西，从来不欺负好人。",
            ["ContentFR"] = "<I>Tss...</> ne te méprends pas. Le Démon Tabethe, la Main Rouge ne vole que les mauvaises personnes. Je ne m’en prends jamais aux honnêtes gens.",
            ["DialogueId"] = 12060514,
            ["GUID"] = "1E313614",
            ["NextDialogue"] = 12060515,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120605/1E313614",
            },
        [12060515] = {
            ["Content"] = "在港口我就看见你鬼鬼祟祟地把那个机关鸟藏在包袱里带了进来。你就是那些人嘴里说的飘什么人是吧？",
            ["ContentFR"] = "Au port, je t’ai vue dissimuler ce machin sous ta toile, en regardant autour de toi comme si tu avais quelque chose à cacher. Tu fais partie de ces... Vagabonds, c’est ça ?",
            ["DialogueId"] = 12060515,
            ["GUID"] = "1E31363E",
            ["NextDialogue"] = 12060516,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120605/1E31363E",
            },
        [12060516] = {
            ["Content"] = "虽然不知道你到底想做什么，但想装成正义的受害者还是免了吧。恶魔大盗是不会上你的当的。",
            ["ContentFR"] = "Je ne sais pas ce que tu prépares, mais inutile de jouer les victimes devant moi. Je ne me laisse pas berner.",
            ["DialogueId"] = 12060516,
            ["GUID"] = "1E313668",
            ["NextDialogue"] = 12060517,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120605/1E313668",
            },
        [12060517] = {
            ["Content"] = "小仆从，怎么办，这个恶魔大盗好像对苏乙有不少误会……",
            ["ContentFR"] = "Petit larbin... qu’est-ce qu’on fait ? On dirait qu’elle se fait une drôle d’idée de Su Yi...",
            ["DialogueId"] = 12060517,
            ["GUID"] = "1E313692",
            ["NextDialogue"] = 12060518,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120605/1E313692",
            },
        [12060518] = {
            ["Content"] = "让我来试试说服她吧。",
            ["ContentFR"] = "Laisse-moi essayer de lui parler.",
            ["DialogueId"] = 12060518,
            ["GUID"] = "1E3136BC",
            ["NextOptions"] = {
                [1] = 12060519,
                [2] = 12060526,
                },
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120605/1E3136BC",
            },
        [12060519] = {
            ["Content"] = "晓之以理。",
            ["ContentFR"] = "<I>Essayer de la raisonner</>",
            ["DialogueId"] = 12060519,
            ["GUID"] = "1E3136E6",
            ["ImprPlusId"] = 1203,
            ["NextDialogue"] = 12060520,
            },
        [12060520] = {
            ["Content"] = "听你的口音，你应该也不是华胥本地人吧？",
            ["ContentFR"] = "À ton accent, on dirait que tu n’es pas originaire de Huaxu, n’est-ce pas ?",
            ["DialogueId"] = 12060520,
            ["GUID"] = "1E313710",
            ["NextDialogue"] = 12060521,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120605/1E313710",
            },
        [12060521] = {
            ["Content"] = "那你也许知道，在海伯利亚，有些卡戎为了避免被贵族老爷刁难，会把自己的角用帽子隐藏起来。你觉得这些卡戎是坏人，还是刁难他们的贵族老爷是坏人呢？",
            ["ContentFR"] = "Alors tu sais peut-être qu’en Hyperborea, certains Charons portent un chapeau pour cacher leurs cornes, afin d’éviter les brimades des nobles. À ton avis... qui est vraiment en tort ? Les Charons, ou ceux qui les persécutent ?",
            ["DialogueId"] = 12060521,
            ["GUID"] = "1E31373A",
            ["NextDialogue"] = 12060522,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120605/1E31373A",
            },
        [12060522] = {
            ["Content"] = "那还用说？当然是贵族老爷的问题了！仗着自己是人上人，天天欺负别人。最看不惯他们那副做派了，呸呸呸。",
            ["ContentFR"] = "Ça ne fait aucun doute ! Ce sont les nobles ! À se croire supérieurs et à écraser les autres... je ne supporte pas leur arrogance. <I>Pfah !</>",
            ["DialogueId"] = 12060522,
            ["GUID"] = "1E313764",
            ["NextDialogue"] = 12060523,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120605/1E313764",
            },
        [12060523] = {
            ["Content"] = "有些传闻说沿海区域有义贼出没，偷走富人的不义之财，接济吃不起饭的穷人。那么他是十恶不赦的大坏蛋吗？",
            ["ContentFR"] = "On raconte aussi qu’un voleur justicier rôde le long des côtes. Il dépouille les riches malhonnêtes pour nourrir les affamés. Est-ce un criminel impardonnable ?",
            ["DialogueId"] = 12060523,
            ["GUID"] = "1E31378E",
            ["NextDialogue"] = 12060524,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120605/1E31378E",
            },
        [12060524] = {
            ["Content"] = "义贼？嘻嘻嘻……那当然是响当当的大英雄！",
            ["ContentFR"] = "Un voleur justicier ? Hihi... Ça, c’est un héros digne de ce nom !",
            ["DialogueId"] = 12060524,
            ["GUID"] = "1E3137B8",
            ["NextDialogue"] = 12060525,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120605/1E3137B8",
            },
        [12060525] = {
            ["Content"] = "还需要我继续说下去吗？你只是受到了一些言论的误导，未必是事情的原貌。飘零人一向主张锄强扶弱，不是你以为的坏人。",
            ["ContentFR"] = "Alors tu comprends. Les rumeurs ne sont pas toujours la vérité. Les Vagabonds défendent les faibles et s’opposent aux puissants. Ils ne sont pas les monstres qu’on décrit.",
            ["DialogueId"] = 12060525,
            ["GUID"] = "1E3137E2",
            ["NextDialogue"] = 12060532,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120605/1E3137E2",
            },
        [12060526] = {
            ["Content"] = "动之以情。",
            ["ContentFR"] = "<I>Faire appel à son cœur</>",
            ["DialogueId"] = 12060526,
            ["GUID"] = "1E31380C",
            ["ImprPlusId"] = 1204,
            ["NextDialogue"] = 12060527,
            },
        [12060527] = {
            ["Content"] = "塔比瑟，你刚刚说自己只偷坏人的东西，从来不欺负好人。看来你也是个伸张正义的好侠盗，在这一点上，大家的心都是一样的。",
            ["ContentFR"] = "Tabethe, tu as dit que tu ne volais que les mauvaises personnes. Tu as ton propre sens de la justice. Sur ce point... nous nous ressemblons.",
            ["DialogueId"] = 12060527,
            ["GUID"] = "1E313836",
            ["NextDialogue"] = 12060528,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120605/1E313836",
            },
        [12060528] = {
            ["Content"] = "怎么？想用糖衣炮弹腐化本大盗？我吃不吃这一套呢……嘻嘻，你不如再多说点试试？",
            ["ContentFR"] = "Oh ? Tu essaies de m’amadouer ? Je me demande si je devrais m’y laisser prendre... hihi. Continue, je t’écoute~",
            ["DialogueId"] = 12060528,
            ["GUID"] = "1E313860",
            ["NextDialogue"] = 12060529,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120605/1E313860",
            },
        [12060529] = {
            ["Content"] = "飘零人也是一样的，他们向来都是锄强扶弱，没有做过伤天害理的事情。我可以为他们担保。",
            ["ContentFR"] = "Les Vagabonds suivent le même principe. Ils ne nuisent pas aux innocents. Je peux en répondre.",
            ["DialogueId"] = 12060529,
            ["GUID"] = "1E31388A",
            ["NextDialogue"] = 12060530,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120605/1E31388A",
            },
        [12060530] = {
            ["Content"] = "正义的伙伴往往会受到很多误解，相信你也明白这一点。但你依然坚持着自己的准则，说明你是个了不起的大盗。",
            ["ContentFR"] = "Les alliés de la justice sont souvent incompris. Mais tu continues à suivre tes règles. Ça fait de toi une grande voleuse.",
            ["DialogueId"] = 12060530,
            ["GUID"] = "1E3138B4",
            ["NextDialogue"] = 12060531,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120605/1E3138B4",
            },
        [12060531] = {
            ["Content"] = "所以这位了不起的大盗，你愿意再多相信一点我们吗？",
            ["ContentFR"] = "Alors, grande voleuse... accepterais-tu de nous accorder un peu de confiance ?",
            ["DialogueId"] = 12060531,
            ["GUID"] = "1E3138DE",
            ["NextDialogue"] = 12060532,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120605/1E3138DE",
            },
        [12060532] = {
            ["Content"] = "够了够了——再念下去，我的耳膜都要被你念穿啦！不就是一个机关鸟吗？这玩意儿我才不稀罕呢，还给你们就是了。",
            ["ContentFR"] = "Ça suffit, ça suffit ! Si tu continues, tu vas me percer les tympans ! Ce n’est qu’un oiseau mécanique, je ne vais pas me battre pour ça. Prenez-le, je m’en moque.",
            ["DialogueId"] = 12060532,
            ["GUID"] = "1E313908",
            ["NextDialogue"] = 12060533,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120605/1E313908",
            },
        [12060533] = {
            ["Content"] = "喏，就藏在那边的箱子里。你们自己拿吧。",
            ["ContentFR"] = "Il est caché dans la caisse là-bas. Servez-vous.",
            ["DialogueId"] = 12060533,
            ["GUID"] = "1E313932",
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120605/1E313932",
            },
        [12060534] = {
            ["Content"] = "机关鸟就藏在那边的箱子里。怎么？需不需要恶魔大盗给你带路？",
            ["DialogueId"] = 12060534,
            ["GUID"] = "1E313933",
            ["NextDialogue"] = 12060535,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120605/1E313933",
            },
        [12060535] = {
            ["Content"] = "这次我盯住你了，不要有什么小心思，也别想着轻举妄动！",
            ["DialogueId"] = 12060535,
            ["GUID"] = "1E313934",
            ["NextDialogue"] = 12060536,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120605/1E313934",
            },
        [12060536] = {
            ["Content"] = "嘻嘻，需要恶魔大盗表演一下从你眼皮底子下消失的魔术吗~这可是我的拿手绝活~",
            ["DialogueId"] = 12060536,
            ["GUID"] = "1E313935",
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120605/1E313935",
            },
        [12060601] = {
            ["Camera"] = "721.375,-25.105469,239.573486,0.000103,-12.201231,176.825256,28.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "外观没有损坏，功能也都完好……只是元件里落了不少尘土，之后细细清一下灰就好了。",
            ["ContentFR"] = "Aucun dégât extérieur. Les fonctions sont intactes... Il y a juste un peu de poussière dans les mécanismes. Un nettoyage minutieux suffira.",
            ["DialogueId"] = 12060601,
            ["GUID"] = "1E31445A",
            ["NextDialogue"] = 12060602,
            ["RelatedWikiId"] = {
                [1] = 405014,
                [2] = 405015,
                [3] = 203009,
                [4] = 403009,
                [5] = 201029,
                },
            ["Scripts"] = "SEQ{\
PARA{\
LookAt{LookAtDescription{\"250003:n(100001)\"}},\
LookAt{LookAtDescription{\"250006:n(100001)\"}},\
LookAt{LookAtDescription{\"200002:n(250003)\"}}\
},\
PlayAnimation{_delay{1.5},ActorId{250003},AnimationId{\"ConfidentR_Start\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120606/1E31445A",
            },
        [12060602] = {
            ["Content"] = "呼，还好我的青鸾贰型没有出事，真是不幸中的万幸。",
            ["ContentFR"] = "<I>Ouf...</> mon Qingluan Type II est sain et sauf. C’est un immense soulagement.",
            ["DialogueId"] = 12060602,
            ["GUID"] = "1E314484",
            ["NextDialogue"] = 12060603,
            ["Scripts"] = "SEQ{\
PlayAnimation{_delay{1.0},ActorId{250003},AnimationId{\"ConfidentRToSigh_Start\"},Duration{1}},\
PlayAnimation{_delay{2.0},ActorId{250003},AnimationId{\"ConfidentRToSigh_End\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120606/1E314484",
            },
        [12060603] = {
            ["Content"] = "唉，虽然失物是找回来了，但是离奉香群英试报名截止只有一个小时了。到哪里再找到两个队友呢……",
            ["ContentFR"] = "Hélas... l’inscription au Tournoi de l’Encens se termine dans une heure. Où vais-je trouver deux coéquipiers maintenant... ?",
            ["DialogueId"] = 12060603,
            ["GUID"] = "1E3144AE",
            ["NextDialogue"] = 12060604,
            ["Scripts"] = "SEQ{\
PlayAnimation{_delay{1.0},ActorId{250003},AnimationId{\"ConfidentR_End\"},Duration{1}},\
PlayAnimation{_delay{1.0},ActorId{250003},AnimationId{\"Think_Start\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120606/1E3144AE",
            },
        [12060604] = {
            ["Content"] = "咳咳……",
            ["ContentFR"] = "Hihi...",
            ["DialogueId"] = 12060604,
            ["GUID"] = "1E3144D8",
            ["NextDialogue"] = 12060605,
            ["Scripts"] = "PlayAnimation{_delay{0.2},ActorId{250006},AnimationId{\"Talk03_Start\"},Duration{1}}",
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120606/1E3144D8",
            },
        [12060605] = {
            ["Content"] = "如果你愿意承认章鱼触手是世界上最有品味，最优雅，最完美的造型，那本大盗也不是不能帮你一把。",
            ["ContentFR"] = "Si tu admets que la tentacule est la forme la plus élégante, la plus raffinée et la plus parfaite au monde... alors je pourrais envisager de t’aider~",
            ["DialogueId"] = 12060605,
            ["GUID"] = "1E314502",
            ["NextDialogue"] = 12060606,
            ["Scripts"] = "SEQ{\
LookAt{LookAtDescription{\"250006:n(250003)\"}},\
LookAt{LookAtDescription{\"200002:n(250006)\"}}\
}",
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120606/1E314502",
            },
        [12060606] = {
            ["Content"] = "好啊！刚刚你果然躲在一旁偷听我们说话！",
            ["ContentFR"] = "Ah ! Je le savais ! Tu nous espionnais depuis le début !",
            ["DialogueId"] = 12060606,
            ["GUID"] = "1E31452C",
            ["NextDialogue"] = 12060607,
            ["Scripts"] = "SEQ{\
PlayAnimation{_delay{0.2},ActorId{200002},AnimationId{\"Angry01_Start\"},Duration{1}},\
LookAt{LookAtDescription{\"250006:n(200002)\"}}\
}",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120606/1E31452C",
            },
        [12060607] = {
            ["Content"] = "嘻嘻……合格的大盗当然要回到犯罪现场，关注现场的每一丝风吹草动啦～",
            ["ContentFR"] = "Hihi... Un voleur digne de ce nom retourne toujours sur les lieux du crime. Il faut surveiller chaque frémissement~",
            ["DialogueId"] = 12060607,
            ["GUID"] = "1E314556",
            ["NextDialogue"] = 12060608,
            ["Scripts"] = "SEQ{\
PlayAnimation{_delay{0.2},ActorId{250006},AnimationId{\"Talk03_End\"},Duration{1}},\
PlayAnimation{_delay{0.8},ActorId{250006},AnimationId{\"Confident_Start\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120606/1E314556",
            },
        [12060608] = {
            ["Content"] = "你态度怎么突然一百八十度大转变了？该不会又想打什么鬼主意吧。",
            ["ContentFR"] = "Pourquoi ce changement d’attitude soudain ? Tu mijotes encore quelque chose ?",
            ["DialogueId"] = 12060608,
            ["GUID"] = "1E314580",
            ["NextDialogue"] = 12060609,
            ["Scripts"] = "SEQ{\
LookAt{LookAtDescription{\"250003:n(250006)\"}},\
PlayAnimation{_delay{0.2},ActorId{250003},AnimationId{\"Think_End\"},Duration{1}},\
PlayAnimation{_delay{2.5},ActorId{250003},AnimationId{\"Angry01_Start\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120606/1E314580",
            },
        [12060609] = {
            ["Content"] = "喂喂，我看你很苦恼的样子，难得提出要当你的队友。你怎么把别人的好意当成驴肝肺！",
            ["ContentFR"] = "Hé ! Je te vois désespérée, et je propose de devenir ton équipière. Et toi, tu traites ma bonne volonté comme du vent ?",
            ["DialogueId"] = 12060609,
            ["GUID"] = "1E3145AA",
            ["NextDialogue"] = 12060610,
            ["Scripts"] = "PARA{\
PlayAnimation{_delay{2.0},ActorId{250003},AnimationId{\"Angry01_End\"},Duration{1}},\
SEQ{\
PlayAnimation{_delay{0.2},ActorId{250006},AnimationId{\"Confident_End\"},Duration{1}},\
LookAt{LookAtDescription{\"250006:n(250003)\"}},\
PlayAnimation{_delay{0.2},ActorId{250006},AnimationId{\"Talk03_Start\"},Duration{1}}\
},\
PlayAnimation{_delay{0.2},ActorId{200002},AnimationId{\"Angry01_End\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120606/1E3145AA",
            },
        [12060610] = {
            ["Content"] = "莫非……你愧疚感上涌，想要弥补自己的过错了？",
            ["ContentFR"] = "À moins que... tu ne cherches à te racheter ?",
            ["DialogueId"] = 12060610,
            ["GUID"] = "1E3145D4",
            ["NextDialogue"] = 12060611,
            ["Scripts"] = "PARA{\
SEQ{\
PlayAnimation{_delay{1.2},ActorId{250006},AnimationId{\"Talk03_End\"},Duration{1}},\
LookAt{LookAtDescription{\"250006:n(100001)\"}}\
},\
PlayAnimation{_delay{0.2},ActorId{100001},AnimationId{\"Think_Start\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120606/1E3145D4",
            },
        [12060611] = {
            ["Content"] = "才不是呢，恶魔大盗行事随心所欲，哪里有什么过错！只是一直听你们把这个什么群英试吹得这么有意思，这种出风头的机会，我才不会放过！",
            ["ContentFR"] = "N’importe quoi ! Démon Tabethe agit selon son bon plaisir. Il n’y a rien à « racheter » ! C’est juste que vous avez rendu ce tournoi tellement excitant... et je ne laisse jamais passer une occasion de briller.",
            ["DialogueId"] = 12060611,
            ["GUID"] = "1E3145FE",
            ["NextDialogue"] = 12060612,
            ["Scripts"] = "SEQ{\
PlayAnimation{_delay{0.2},ActorId{250006},AnimationId{\"Angry01_Start\"},Duration{1}},\
PlayAnimation{_delay{2.2},ActorId{250006},AnimationId{\"Angry01_End\"},Duration{1}},\
PlayAnimation{_delay{0.2},ActorId{250006},AnimationId{\"Talk03_Start\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120606/1E3145FE",
            },
        [12060612] = {
            ["Content"] = "嗯……仔细想想，你能从本姑娘眼皮底下把东西偷走，说明胆识不错。和我们过了两招，身手也算过关。说不定你意外地适合群英试呢。",
            ["ContentFR"] = "Hmm... à bien y réfléchir... Tu as réussi à me dérober mon œuvre sous mes yeux. Ça demande du cran. Et tu ne t’es pas si mal débrouillée face à nous. Finalement... tu pourrais bien être faite pour le tournoi.",
            ["DialogueId"] = 12060612,
            ["GUID"] = "1E314628",
            ["NextDialogue"] = 12060613,
            ["Scripts"] = "SEQ{\
PlayAnimation{_delay{0.2},ActorId{250003},AnimationId{\"Talk03_Start\"},Duration{1}},\
LookAt{LookAtDescription{\"250006:n(250003)\"}}\
}",
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120606/1E314628",
            },
        [12060613] = {
            ["Content"] = "好吧，那我就勉强认可你了。",
            ["ContentFR"] = "Très bien. Je t’accepte.",
            ["DialogueId"] = 12060613,
            ["GUID"] = "1E314652",
            ["NextDialogue"] = 12060614,
            ["Scripts"] = "PARA{\
PlayAnimation{_delay{0.2},ActorId{250003},AnimationId{\"AgreeHead\"},Duration{1}},\
PlayAnimation{_delay{0.8},ActorId{250003},AnimationId{\"Talk03_End\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120606/1E314652",
            },
        [12060614] = {
            ["Content"] = "提前先说好，最后的奖品得三七分哦——你三我七。",
            ["ContentFR"] = "On met ça au clair : la récompense, c’est soixante-dix pour moi... trente pour toi.",
            ["DialogueId"] = 12060614,
            ["GUID"] = "1E31467C",
            ["NextDialogue"] = 12060615,
            ["Scripts"] = "PlayAnimation{_delay{0.2},ActorId{250006},AnimationId{\"Confident_Start\"},Duration{1}}",
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120606/1E31467C",
            },
        [12060615] = {
            ["Camera"] = "380.75,-18.171875,137.20459,0.000082,-5.200806,170.601486,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "这样一来就凑齐两个人了，只差最后的一名队友……",
            ["ContentFR"] = "Nous sommes deux... Il nous manque encore un dernier membre...",
            ["DialogueId"] = 12060615,
            ["GUID"] = "1E3146A6",
            ["NextDialogue"] = 12060616,
            ["Scripts"] = "PARA{\
SEQ{\
PlayAnimation{_delay{0.2},ActorId{250006},AnimationId{\"Confident_End\"},Duration{1}},\
PARA{\
LookAt{LookAtDescription{\"250003:n(100001)\"}},\
LookAt{LookAtDescription{\"250006:n(100001)\"}},\
PlayAnimation{_delay{1.2},ActorId{250003},AnimationId{\"Talk03_Start\"},Duration{1}},\
PlayAnimation{_delay{1.2},ActorId{250006},AnimationId{\"Talk03_Start\"},Duration{1}}\
}\
}\
}",
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120606/1E3146A6",
            },
        [12060616] = {
            ["Content"] = "哇啊啊，小仆从，她们俩怎么齐齐地盯着我们看。难不成是想要招揽——",
            ["ContentFR"] = "Petit larbin... pourquoi elles nous fixent toutes les deux comme ça ? Elles ne penseraient quand même pas à—",
            ["DialogueId"] = 12060616,
            ["GUID"] = "1E3146D0",
            ["NextOptions"] = {
                [1] = 12060617,
                [2] = 12060620,
                },
            ["Scripts"] = "PARA{\
LookAt{LookAtDescription{\"200002:n(100001)\"}},\
PlayAnimation{_delay{0.2},ActorId{200002},AnimationId{\"Shock02_Start\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120606/1E3146D0",
            },
        [12060617] = {
            ["Content"] = "白。",
            ["ContentFR"] = "<I>Snow.</>",
            ["DialogueId"] = 12060617,
            ["GUID"] = "1E3146FA",
            ["NextDialogue"] = 12060618,
            },
        [12060618] = {
            ["Content"] = "咳咳，光之魔王大人这么有实力的重量级选手。要是上场后一下子就结束了比赛，对其他选手不太公平吧……？",
            ["ContentFR"] = "Hum hum... Si le Roi Démon entrait en scène, la compétition serait réglée en un instant. Ce ne serait pas très équitable pour les autres, n’est-ce pas ?",
            ["DialogueId"] = 12060618,
            ["GUID"] = "1E314724",
            ["NextDialogue"] = 12060619,
            ["Scripts"] = "PARA{\
PARA{\
LookAt{LookAtDescription{\"250003:n(200002)\"}},\
LookAt{LookAtDescription{\"250006:n(200002)\"}}\
},\
SEQ{\
LookAt{LookAtDescription{\"200002:n(250003)\"}},\
PlayAnimation{_delay{0.2},ActorId{200002},AnimationId{\"Shock02_End\"},Duration{1}},\
PlayAnimation{_delay{0.2},ActorId{200002},AnimationId{\"Disagree\"},Duration{1}}\
}\
}",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120606/1E314724",
            },
        [12060619] = {
            ["Content"] = "我呢，其实是非常心系正义的一个好魔王，不想随随便便破坏比赛规则。还是把这个宝贵的机会让给别人吧。",
            ["ContentFR"] = "Je suis un démon profondément attaché à la justice. Je ne peux pas bouleverser l’équilibre d’un tournoi aussi noble. Je laisse ma place.",
            ["DialogueId"] = 12060619,
            ["GUID"] = "1E31474E",
            ["NextOptions"] = {
                [1] = 12060620,
                },
            ["Scripts"] = "SEQ{\
PlayAnimation{_delay{0.2},ActorId{200002},AnimationId{\"Confident_Start\"},Duration{1}},\
LookAt{_delay{3.2},LookAtDescription{\"200002:n(100001)\"}},\
PlayAnimation{_delay{2.2},ActorId{200002},AnimationId{\"Confident_End\"},Duration{1}},\
}",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120606/1E31474E",
            },
        [12060620] = {
            ["Content"] = "{nickname}。",
            ["ContentFR"] = "<I>{nickname}.</>",
            ["DialogueId"] = 12060620,
            ["GUID"] = "1E314778",
            ["NextDialogue"] = 12060621,
            },
        [12060621] = {
            ["Content"] = "对哦！有了小仆从的加入，她们岂不是像老虎长出了翅膀一样，所到之处完全没有敌手，轻轻松松拿下比赛！",
            ["ContentFR"] = "Voilà ! Avec mon petit larbin dans l’équipe, ce sera comme donner des ailes à un tigre ! Plus personne ne pourra leur tenir tête !",
            ["DialogueId"] = 12060621,
            ["GUID"] = "1E3147A2",
            ["NextDialogue"] = 12060622,
            ["Scripts"] = "PARA{\
PARA{\
LookAt{LookAtDescription{\"250003:n(100001)\"}},\
LookAt{LookAtDescription{\"250006:n(100001)\"}}\
},\
PlayAnimation{_delay{0.2},ActorId{200002},AnimationId{\"Confident_Start\"},Duration{1}},\
LookAt{_delay{1.2},LookAtDescription{\"200002:n(100001)\"}}\
}",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120606/1E3147A2",
            },
        [12060622] = {
            ["Content"] = "那叫如虎添翼啦——不过没想到你还多少学了点成语，看来你在华胥的日子也算有所收获了！",
            ["ContentFR"] = "On dit plutôt « ajouter des ailes à un tigre ». Mais je vois que tu t’appropries déjà nos expressions. Huaxu ne t’a pas laissée indifférente.",
            ["DialogueId"] = 12060622,
            ["GUID"] = "1E3147CC",
            ["NextDialogue"] = 12060623,
            ["Scripts"] = "PARA{\
SEQ{\
PlayAnimation{_delay{0.2},ActorId{250003},AnimationId{\"Talk03ToTalkL_Start\"},Duration{1}},\
PlayAnimation{_delay{3.2},ActorId{250003},AnimationId{\"Talk03ToTalkL_End\"},Duration{1}}\
},\
LookAt{_delay{1.2},LookAtDescription{\"250003:n(200002)\"}},\
LookAt{_delay{1.2},LookAtDescription{\"200002:n(250003)\"}}\
}",
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120606/1E3147CC",
            },
        [12060623] = {
            ["Content"] = "哼哼，那是当然！",
            ["ContentFR"] = "Héhé, évidemment !",
            ["DialogueId"] = 12060623,
            ["GUID"] = "1E3147F6",
            ["NextDialogue"] = 12060624,
            ["Scripts"] = "PlayAnimation{_delay{0.2},ActorId{200002},AnimationId{\"AgreeHead\"},Duration{1}}",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120606/1E3147F6",
            },
        [12060624] = {
            ["Content"] = "那现在只剩下一个难题需要解决了……我们三天后就要坐飞艇回冰湖城了，时间上会不会来不及呀？",
            ["ContentFR"] = "Il reste un détail... Notre dirigeable pour Givrelac part dans trois jours. On aura le temps ?",
            ["DialogueId"] = 12060624,
            ["GUID"] = "1E314820",
            ["NextDialogue"] = 12060625,
            ["Scripts"] = "SEQ{\
PlayAnimation{_delay{0.2},ActorId{200002},AnimationId{\"Think_Start\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120606/1E314820",
            },
        [12060625] = {
            ["Content"] = "完全没问题！奉香群英试为时两天，到明天日落之前就能决出最后的胜利队伍，绝对绝对不会耽误你们的回程。",
            ["ContentFR"] = "Aucun problème ! Le Tournoi de l’Encens dure deux jours. La finale aura lieu avant le coucher du soleil demain. Vous serez largement dans les temps.",
            ["DialogueId"] = 12060625,
            ["GUID"] = "1E31484A",
            ["NextDialogue"] = 12060626,
            ["Scripts"] = "SEQ{\
PARA{\
PlayAnimation{_delay{0.2},ActorId{250003},AnimationId{\"DisagreeHead\"},Duration{1}},\
PlayAnimation{_delay{0.2},ActorId{250003},AnimationId{\"Talk03_End\"},Duration{1}}\
},\
PlayAnimation{_delay{1.2},ActorId{250003},AnimationId{\"Explain01_Start\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120606/1E31484A",
            },
        [12060626] = {
            ["Content"] = "那我好像没有拒绝你的理由。待在华胥的最后几天，陪朋友一起玩玩也挺不错的。",
            ["ContentFR"] = "Dans ce cas... je n’ai aucune raison de refuser. Passer nos derniers jours à Huaxu à aider une amie... ça me va.",
            ["DialogueId"] = 12060626,
            ["GUID"] = "1E314874",
            ["NextDialogue"] = 12060627,
            ["Scripts"] = "SEQ{\
PlayAnimation{_delay{1.2},ActorId{100001},AnimationId{\"AgreeHead\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120606/1E314874",
            },
        [12060627] = {
            ["Content"] = "好耶，友谊第一比赛第二！不对不对——比赛也是很重要的，小仆从你可一定得给我拿个冠军回来！",
            ["ContentFR"] = "Génial ! L’amitié avant tout ! Non... enfin... la victoire aussi est importante ! Petit larbin, tu me décroches ce titre !",
            ["DialogueId"] = 12060627,
            ["GUID"] = "1E31489E",
            ["NextDialogue"] = 12060628,
            ["Scripts"] = "PARA{\
PlayAnimation{_delay{1.2},ActorId{100001},AnimationId{\"Think_End\"},Duration{1}},\
SEQ{\
PlayAnimation{_delay{0.2},ActorId{200002},AnimationId{\"SpecialHappy_Start\"},Duration{1}},\
PlayAnimation{_delay{4.2},ActorId{200002},AnimationId{\"SpecialHappy_End\"},Duration{1}},\
LookAt{_delay{1.2},LookAtDescription{\"200002:n(100001)\"}}\
}\
}",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120606/1E31489E",
            },
        [12060628] = {
            ["Content"] = "对啦。你那个机关鸟如果再暴露了会很麻烦的吧？既然这样，恶魔大盗来帮你掩饰一下~",
            ["ContentFR"] = "Au fait... si ton oiseau mécanique se fait encore repérer, ça risque d’attirer des ennuis, non ? Hihi... laisse-moi m’en charger.",
            ["DialogueId"] = 12060628,
            ["GUID"] = "1E3148C8",
            ["NextDialogue"] = 12060629,
            ["Scripts"] = "LookAt{_delay{1.2},LookAtDescription{\"250006:n(250003)\"}}",
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120606/1E3148C8",
            },
        [12060629] = {
            ["Content"] = "……你这一手倒是方便。",
            ["ContentFR"] = "... Cette capacité est plutôt pratique.",
            ["DialogueId"] = 12060629,
            ["GUID"] = "1E3148F2",
            ["NextDialogue"] = 12060630,
            ["Scripts"] = "PARA{\
LookAt{_delay{1.2},LookAtDescription{\"250003:n(250006)\"}},\
PlayAnimation{_delay{0.2},ActorId{250003},AnimationId{\"Agree\"},Duration{1}},\
PlayAnimation{_delay{0.5},ActorId{250003},AnimationId{\"Think_Start\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120606/1E3148F2",
            },
        [12060630] = {
            ["Content"] = "时候不早了，我们赶紧去报名处吧。",
            ["ContentFR"] = "Le temps presse. Allons nous inscrire.",
            ["DialogueId"] = 12060630,
            ["GUID"] = "1E31491C",
            ["Scripts"] = "SEQ{\
PlayAnimation{_delay{0.5},ActorId{250003},AnimationId{\"Think_End\"},Duration{1}},\
PARA{\
LookAt{LookAtDescription{\"250003:n(100001)\"}},\
LookAt{LookAtDescription{\"250006:n(100001)\"}}\
}\
}",
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120606/1E31491C",
            },
        [12060631] = {
            ["Content"] = "听好了，我们先约法三章。组队期间，你不许随便偷东西，不许到处乱跑，不许不听指挥。明白了吗？",
            ["ContentFR"] = "Bon, écoutez bien. On pose trois règles. Pendant qu’on fait équipe : pas de vol, pas d’escapade en solo, et tu suis mes consignes. C’est clair ?",
            ["DialogueId"] = 12060631,
            ["GUID"] = "1E314946",
            ["NextDialogue"] = 12060632,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120606/1E314946",
            },
        [12060632] = {
            ["Content"] = "好好好，明白了，苏乙妈妈——",
            ["ContentFR"] = "Oui, oui... bien reçu, Maman Su Yi—",
            ["DialogueId"] = 12060632,
            ["GUID"] = "1E314970",
            ["NextDialogue"] = 12060633,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120606/1E314970",
            },
        [12060633] = {
            ["Content"] = "喂，好敷衍的语气！你真的听进去了吗？",
            ["ContentFR"] = "Hé ! C’est quoi ce ton expédié ? Tu m’écoutes au moins ?",
            ["DialogueId"] = 12060633,
            ["GUID"] = "1E31499A",
            ["NextDialogue"] = 12060634,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120606/1E31499A",
            },
        [12060634] = {
            ["Content"] = "嘻嘻，你猜——？",
            ["ContentFR"] = "Hihi... à ton avis~ ?",
            ["DialogueId"] = 12060634,
            ["GUID"] = "1E3149C4",
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120606/1E3149C4",
            },
        [12060701] = {
            ["Content"] = "你好！我们是来报名参加群英试的！呼……应该赶上了吧？",
            ["ContentFR"] = "Bonjour ! Nous venons nous inscrire au Tournoi de l’Encens ! Ouf... nous arrivons à temps, j’espère ?",
            ["DialogueId"] = 12060701,
            ["GUID"] = "1E3154C2",
            ["NextDialogue"] = 12060702,
            ["RelatedWikiId"] = {
                [1] = 405014,
                [2] = 405015,
                [3] = 203009,
                [4] = 403009,
                [5] = 201029,
                },
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120607/1E3154C2",
            },
        [12060702] = {
            ["Content"] = "没问题，离报名结束还有半个时辰。请在这张报名表上签署几位的姓名和小队名称。",
            ["ContentFR"] = "Aucun souci. Il reste encore une demi-heure avant la clôture. Veuillez inscrire vos noms ici, ainsi que le nom de votre équipe.",
            ["DialogueId"] = 12060702,
            ["GUID"] = "1E3154EC",
            ["NextDialogue"] = 12060703,
            ["SpeakNpcId"] = 250011,
            ["VoiceName"] = "voice/$Locale$/story/1206/120607/1E3154EC",
            },
        [12060703] = {
            ["Content"] = "小队名称？糟糕糟糕，差点忘了！我们得现在赶紧想一个。",
            ["ContentFR"] = "Le nom de l’équipe ?! Oh non... j’ai complètement oublié ! Il faut en trouver un tout de suite !",
            ["DialogueId"] = 12060703,
            ["GUID"] = "1E315516",
            ["NextDialogue"] = 12060704,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120607/1E315516",
            },
        [12060704] = {
            ["Content"] = "“腕足很大”小队，这个怎么样，是不是很拉风？",
            ["ContentFR"] = "« Les Grandes Tentacules ». Alors ? Avoue que ça en jette !",
            ["DialogueId"] = 12060704,
            ["GUID"] = "1E315540",
            ["NextDialogue"] = 12060705,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120607/1E315540",
            },
        [12060705] = {
            ["Content"] = "你的品味还是一如既往的糟糕……要我说，不如“天工开物”小队吧。",
            ["ContentFR"] = "Tes goûts sont d’une constance affligeante... Je propose plutôt « Œuvre Céleste ».",
            ["DialogueId"] = 12060705,
            ["GUID"] = "1E31556A",
            ["NextDialogue"] = 12060706,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120607/1E31556A",
            },
        [12060706] = {
            ["Content"] = "什么嘛，老土！你起的名字明明也没有好到哪里去！",
            ["ContentFR"] = "<I>Pff,</> ringard ! Ton idée n’est pas meilleure !",
            ["DialogueId"] = 12060706,
            ["GUID"] = "1E315594",
            ["NextDialogue"] = 12060707,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120607/1E315594",
            },
        [12060707] = {
            ["Content"] = "……{nickname}，还是你来定吧。",
            ["ContentFR"] = "...{nickname}, décide pour nous.",
            ["DialogueId"] = 12060707,
            ["GUID"] = "1E3155BE",
            ["NextDialogue"] = 12060708,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120607/1E3155BE",
            },
        [12060708] = {
            ["Content"] = "小仆从，你有没有觉得这一幕似曾相识……",
            ["ContentFR"] = "Petit larbin... ça ne te rappelle pas quelque chose ?",
            ["DialogueId"] = 12060708,
            ["GUID"] = "1E3155E8",
            ["NextDialogue"] = 12060709,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120607/1E3155E8",
            },
        [12060709] = {
            ["Content"] = "也许人类的本质就是总是重复做相同的事……好吧，我瞧瞧。小队名字的话——",
            ["ContentFR"] = "Peut-être que l’humanité est condamnée à répéter les mêmes scènes... Très bien, voyons voir. Pour le nom—",
            ["DialogueId"] = 12060709,
            ["FinalDialogueId"] = 12060716,
            ["GUID"] = "1E315612",
            ["NextOptions"] = {
                [1] = 12060710,
                [2] = 12060713,
                [3] = 12060715,
                },
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120607/1E315612",
            },
        [12060710] = {
            ["Content"] = "光之魔王和她的三个跟班。",
            ["ContentFR"] = "<I>Le Roi Démon de Lumière et ses trois larbins.</>",
            ["DialogueId"] = 12060710,
            ["GUID"] = "1E31563C",
            ["NextDialogue"] = 12060711,
            },
        [12060711] = {
            ["Content"] = "跟班？不吉利不吉利，堂堂恶魔大盗怎么能当别人的跟班呢！",
            ["ContentFR"] = "Des « larbins » ? Certainement pas ! Démon Tabethe, la Main Rouge, ne sert personne !",
            ["DialogueId"] = 12060711,
            ["GUID"] = "1E315666",
            ["NextDialogue"] = 12060712,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120607/1E315666",
            },
        [12060712] = {
            ["Content"] = "喂喂，华胥的皎皎们排着队想拜入本魔王麾下呢，你不做有的是皎皎做！",
            ["ContentFR"] = "<I>Hmpf !</> Les Luno de Huaxu feraient la queue pour entrer sous ma bannière. Si tu refuses, d’autres prendront ta place !",
            ["DialogueId"] = 12060712,
            ["GUID"] = "1E315690",
            ["NextDialogue"] = 12060709,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120607/1E315690",
            },
        [12060713] = {
            ["Content"] = "夜航者小队华胥分队。",
            ["ContentFR"] = "<I>Les Vagabonds de la Nuit — Branche de Huaxu.</>",
            ["DialogueId"] = 12060713,
            ["GUID"] = "1E3156BA",
            ["NextDialogue"] = 12060714,
            },
        [12060714] = {
            ["Content"] = "咳咳……要不咱们再想想？",
            ["ContentFR"] = "Hum... et si on cherchait encore un peu ?",
            ["DialogueId"] = 12060714,
            ["GUID"] = "1E3156E4",
            ["NextDialogue"] = 12060709,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120607/1E3156E4",
            },
        [12060715] = {
            ["Content"] = "狩月逐香队。",
            ["ContentFR"] = "<I>Les Chasseurs d’Encens.</>",
            ["DialogueId"] = 12060715,
            ["GUID"] = "1E31570E",
            ["NextDialogue"] = 12060716,
            },
        [12060716] = {
            ["Content"] = "嗯，这个不错，就决定是它了！",
            ["ContentFR"] = "Oui, ça me plaît. Décidé !",
            ["DialogueId"] = 12060716,
            ["GUID"] = "1E315738",
            ["NextDialogue"] = 12060717,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120607/1E315738",
            },
        [12060717] = {
            ["Content"] = "久等了，这是我们的报名表。",
            ["ContentFR"] = "{性别:Désolé|Désolée} pour l’attente. Voici notre formulaire.",
            ["DialogueId"] = 12060717,
            ["GUID"] = "1E315762",
            ["NextDialogue"] = 12060718,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120607/1E315762",
            },
        [12060718] = {
            ["Content"] = "让我确认一下，苏乙女士、塔比瑟女士，以及……{nickname}，等等，我没有看错吧？",
            ["ContentFR"] = "Voyons... Mademoiselle Su Yi, Mademoiselle Tabethe... et... {nickname}. Un instant... je ne me trompe pas ?",
            ["DialogueId"] = 12060718,
            ["GUID"] = "1E31578C",
            ["NextDialogue"] = 12060719,
            ["SpeakNpcId"] = 250011,
            ["VoiceName"] = "voice/$Locale$/story/1206/120607/1E31578C",
            },
        [12060719] = {
            ["Content"] = "……您莫非就是此前在皓京乱象中，协助大风九章归位的那位少年英杰？",
            ["ContentFR"] = "Ne seriez-vous pas {性别:le jeune héros|la jeune héroïne} qui a contribué à rétablir les Neuf Chapitres de Dafeng lors des troubles de Haojing ?",
            ["DialogueId"] = 12060719,
            ["GUID"] = "1E3157B6",
            ["NextDialogue"] = 12060720,
            ["SpeakNpcId"] = 250011,
            ["VoiceName"] = "voice/$Locale$/story/1206/120607/1E3157B6",
            },
        [12060720] = {
            ["Content"] = "按照华胥人的说话方式应该是……“正是在下”？",
            ["ContentFR"] = "Si je devais parler comme à Huaxu... « En effet, c’est bien moi. »",
            ["DialogueId"] = 12060720,
            ["GUID"] = "1E3157E0",
            ["NextDialogue"] = 12060721,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120607/1E3157E0",
            },
        [12060721] = {
            ["Content"] = "看不出来，你在这里竟然还是个大人物。",
            ["ContentFR"] = "Toi ? Un grand nom à Huaxu ? Je ne l’aurais jamais deviné.",
            ["DialogueId"] = 12060721,
            ["GUID"] = "1E31580A",
            ["NextDialogue"] = 12060722,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120607/1E31580A",
            },
        [12060722] = {
            ["Content"] = "呵呵，既然是亲历者，那倒是省去了我介绍前因后果的工夫。",
            ["ContentFR"] = "Héhé. Dans ce cas, inutile de vous exposer tout le contexte.",
            ["DialogueId"] = 12060722,
            ["GUID"] = "1E315834",
            ["NextDialogue"] = 12060723,
            ["SpeakNpcId"] = 250011,
            ["VoiceName"] = "voice/$Locale$/story/1206/120607/1E315834",
            },
        [12060723] = {
            ["Content"] = "{nickname}{性别：先生|女士}，正因您参与推动的改制，如今人之力量成为重新被审视的课题。",
            ["ContentFR"] = "{性别:Monsieur|Mademoiselle} {nickname}, les réformes auxquelles vous avez contribué ont ravivé une question essentielle : celle de la force des simples mortels.",
            ["DialogueId"] = 12060723,
            ["GUID"] = "1E31585E",
            ["NextDialogue"] = 12060724,
            ["SpeakNpcId"] = 250011,
            ["VoiceName"] = "voice/$Locale$/story/1206/120607/1E31585E",
            },
        [12060724] = {
            ["Content"] = "故而这次的赛事鼓励人们拿起武器，与如今仍游荡在外，尚未被完全清除的混乱狴犴作战。",
            ["ContentFR"] = "Ainsi, cette année, les participants sont encouragés à prendre les armes pour affronter les Bi’an encore en liberté.",
            ["DialogueId"] = 12060724,
            ["GUID"] = "1E315888",
            ["NextDialogue"] = 12060725,
            ["SpeakNpcId"] = 250011,
            ["VoiceName"] = "voice/$Locale$/story/1206/120607/1E315888",
            },
        [12060725] = {
            ["Content"] = "意思是……这次比赛就是比谁打的怪物多，是嘛？",
            ["ContentFR"] = "Donc... c’est celui qui explose le plus de monstres qui gagne ?",
            ["DialogueId"] = 12060725,
            ["GUID"] = "1E3158B2",
            ["NextDialogue"] = 12060726,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120607/1E3158B2",
            },
        [12060726] = {
            ["Content"] = "并非如此。对于大部分未曾接触过武器的华胥人来说，直接比拼武艺还是有些一步登天了。",
            ["ContentFR"] = "Pas exactement. La majorité des habitants de Huaxu n’a jamais manié d’arme. Un simple tournoi martial serait trop abrupt.",
            ["DialogueId"] = 12060726,
            ["GUID"] = "1E3158DC",
            ["NextDialogue"] = 12060727,
            ["SpeakNpcId"] = 250011,
            ["VoiceName"] = "voice/$Locale$/story/1206/120607/1E3158DC",
            },
        [12060727] = {
            ["Content"] = "本次群英试的主题是“争锋”——简单来说您可以理解成“夺宝”。在指定的赛场中，布置了多处藏有宝物的器具。不同宝物对应着不同的文筹，清缴狴犴能够带来武筹。",
            ["ContentFR"] = "Le thème de cette édition est « Rivalité ». En d’autres termes : une chasse au trésor. Dans l’arène, divers artefacts sont dissimulés dans des dispositifs prévus à cet effet. Chaque trésor rapporte des Jetons stratégiques, tandis que vaincre des Bi’an permet d’obtenir des Jetons martiaux.",
            ["DialogueId"] = 12060727,
            ["GUID"] = "1E315906",
            ["NextDialogue"] = 12060728,
            ["SpeakNpcId"] = 250011,
            ["VoiceName"] = "voice/$Locale$/story/1206/120607/1E315906",
            },
        [12060728] = {
            ["Content"] = "赛事总共有五轮。每轮次会统计各个参赛队伍的总筹数，达到足够名次的队伍能够晋级。",
            ["ContentFR"] = "Il y aura cinq manches. À la fin de chacune, nous comptabiliserons le total des jetons. Les équipes les mieux classées avanceront.",
            ["DialogueId"] = 12060728,
            ["GUID"] = "1E315930",
            ["NextDialogue"] = 12060729,
            ["SpeakNpcId"] = 250011,
            ["VoiceName"] = "voice/$Locale$/story/1206/120607/1E315930",
            },
        [12060729] = {
            ["Content"] = "如何在抵御混乱狴犴的同时，搜集到足够多的宝物，就是本次夺魁的关键。",
            ["ContentFR"] = "Trouver l’équilibre entre contenir les Bi’an et collecter suffisamment de trésors sera la clé de la victoire.",
            ["DialogueId"] = 12060729,
            ["GUID"] = "1E31595A",
            ["NextDialogue"] = 12060730,
            ["SpeakNpcId"] = 250011,
            ["VoiceName"] = "voice/$Locale$/story/1206/120607/1E31595A",
            },
        [12060730] = {
            ["Content"] = "怎么样，关于这次的赛制还有问题吗？",
            ["ContentFR"] = "Des questions ?",
            ["DialogueId"] = 12060730,
            ["GUID"] = "1E315984",
            ["NextDialogue"] = 12060731,
            ["SpeakNpcId"] = 250011,
            ["VoiceName"] = "voice/$Locale$/story/1206/120607/1E315984",
            },
        [12060731] = {
            ["Content"] = "哇，本来只是好心帮人参赛，没想到歪打正着——竟然是这么有意思的赛制！",
            ["ContentFR"] = "Ouah... Je voulais juste rendre service, et je tombe sur un jeu pareil ? Ça a l’air incroyablement amusant !",
            ["DialogueId"] = 12060731,
            ["GUID"] = "1E3159AE",
            ["NextDialogue"] = 12060732,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120607/1E3159AE",
            },
        [12060732] = {
            ["Content"] = "把宝物放在地里让别人随意挖，我说你们华胥人都这么有钱，玩这么大嘛？太好了太好了，要发大财了！",
            ["ContentFR"] = "Vous enterrez des trésors pour que les gens viennent les déterrer ? Vous êtes vraiment si riches à Huaxu ? Hihi... voilà qui promet !",
            ["DialogueId"] = 12060732,
            ["GUID"] = "1E3159D8",
            ["NextDialogue"] = 12060733,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120607/1E3159D8",
            },
        [12060733] = {
            ["Content"] = "咳咳……这位外乡来的朋友，你可能有一些误解。这场赛事中所用的宝物都由某位不知名织星客友情赞助，仅供积分统计，赛后是要归还的。",
            ["ContentFR"] = "Hum... je crains un malentendu. Les « trésors » sont gracieusement fournis par un Tisse-Étoiles anonyme. Ils ne servent qu’au comptage des points et devront être restitués après la compétition.",
            ["DialogueId"] = 12060733,
            ["GUID"] = "1E315A02",
            ["NextDialogue"] = 12060734,
            ["SpeakNpcId"] = 250011,
            ["VoiceName"] = "voice/$Locale$/story/1206/120607/1E315A02",
            },
        [12060734] = {
            ["Content"] = "有借有还是吧，你不用解释，我懂我懂～",
            ["ContentFR"] = "Oui, oui... on emprunte et... on rend. Pas besoin de détailler, j’ai compris~",
            ["DialogueId"] = 12060734,
            ["GUID"] = "1E315A2C",
            ["NextDialogue"] = 12060735,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120607/1E315A2C",
            },
        [12060735] = {
            ["Content"] = "…………您确定您正确理解了这次的赛制吗？",
            ["ContentFR"] = "... Êtes-vous certaine d’avoir bien compris les règles ?",
            ["DialogueId"] = 12060735,
            ["GUID"] = "1E315A56",
            ["NextDialogue"] = 12060736,
            ["SpeakNpcId"] = 250011,
            ["VoiceName"] = "voice/$Locale$/story/1206/120607/1E315A56",
            },
        [12060736] = {
            ["Content"] = "放心吧。我会负起责任，看住她的！",
            ["ContentFR"] = "Rassurez-vous. Je la surveillerai personnellement.",
            ["DialogueId"] = 12060736,
            ["GUID"] = "1E315A80",
            ["NextDialogue"] = 12060737,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120607/1E315A80",
            },
        [12060737] = {
            ["Content"] = "嘁，没劲。",
            ["ContentFR"] = "<I>Tss.</> Quelle rabat-joie.",
            ["DialogueId"] = 12060737,
            ["GUID"] = "1E315AAA",
            ["NextDialogue"] = 12060738,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120607/1E315AAA",
            },
        [12060738] = {
            ["Content"] = "呵呵，那我就放下心来了。",
            ["ContentFR"] = "Très bien. Me voilà rassuré.",
            ["DialogueId"] = 12060738,
            ["GUID"] = "1E315AD4",
            ["NextDialogue"] = 12060739,
            ["SpeakNpcId"] = 250011,
            ["VoiceName"] = "voice/$Locale$/story/1206/120607/1E315AD4",
            },
        [12060739] = {
            ["Content"] = "赛事即将开始，待几位准备好，就和我说吧。祝您和您的小队旗开得胜。",
            ["ContentFR"] = "La compétition va débuter sous peu. Lorsque vous serez {性别:prêts|prêtes}, faites-le-moi savoir. Je vous souhaite, à vous et à votre équipe, un départ victorieux.",
            ["DialogueId"] = 12060739,
            ["GUID"] = "1E315AFE",
            ["SpeakNpcId"] = 250011,
            ["VoiceName"] = "voice/$Locale$/story/1206/120607/1E315AFE",
            },
        [12060740] = {
            ["Content"] = "准备好进入赛场了吗？",
            ["ContentFR"] = "Êtes-vous prêts à entrer dans l’arène ?",
            ["DialogueId"] = 12060740,
            ["GUID"] = "1E315B28",
            ["SpeakNpcId"] = 250011,
            ["VoiceName"] = "voice/$Locale$/story/1206/120607/1E315B28",
            },
        [12060741] = {
            ["Content"] = "我们走吧！",
            ["ContentFR"] = "<I>Allons-y !</>",
            ["DialogueId"] = 12060741,
            ["GUID"] = "1E315B52",
            },
        [12060742] = {
            ["Content"] = "等等，还有事情没有处理。",
            ["ContentFR"] = "<I>Attendez. Il nous reste quelque chose à régler.</>",
            ["DialogueId"] = 12060742,
            ["GUID"] = "1E315B7C",
            },
        [12060801] = {
            ["Content"] = "你们出来啦，我在观众席上看得一清二楚！按这个节奏下去，一定能稳拿冠军！",
            ["ContentFR"] = "Vous voilà ! J’ai tout suivi depuis les gradins ! À ce rythme-là, le titre est déjà dans la poche !",
            ["DialogueId"] = 12060801,
            ["GUID"] = "1E31652A",
            ["NextDialogue"] = 12060802,
            ["RelatedWikiId"] = {
                [1] = 405014,
                [2] = 405015,
                [3] = 203009,
                [4] = 403009,
                [5] = 201029,
                },
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120608/1E31652A",
            },
        [12060802] = {
            ["Content"] = "哼哼，简直轻轻松松！我就说嘛，这种“偷宝物”的比赛，简直就是恶魔大盗的专业领域！",
            ["ContentFR"] = "Héhé... trop facile ! Je vous l’avais dit : un tournoi où il faut « récupérer des trésors » ? C’est pile mon terrain de jeu !",
            ["DialogueId"] = 12060802,
            ["GUID"] = "1E316554",
            ["NextDialogue"] = 12060803,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120608/1E316554",
            },
        [12060803] = {
            ["Content"] = "明明是寻宝的赛制，竟然被你说成是“偷宝物”……还真是本性不改。",
            ["ContentFR"] = "C’est une chasse au trésor, pas un cambriolage... Tu ne changeras donc jamais.",
            ["DialogueId"] = 12060803,
            ["GUID"] = "1E31657E",
            ["NextDialogue"] = 12060804,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120608/1E31657E",
            },
        [12060804] = {
            ["Content"] = "嘻嘻……一般这种时候，要一群人一起去庆功的吧！我还只听别人说过，没有亲自体会过呢！我们一起去吃小吃吃到饱吧！",
            ["ContentFR"] = "Hihi... D’habitude, après une victoire, on sort fêter ça tous ensemble, non ? Je n’ai fait qu’en entendre parler... jamais vraiment vécu ! Allez, on va dévaliser les échoppes jusqu’à ne plus pouvoir bouger !",
            ["DialogueId"] = 12060804,
            ["GUID"] = "1E3165A8",
            ["NextDialogue"] = 12060805,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120608/1E3165A8",
            },
        [12060805] = {
            ["Content"] = "刚好，热身完差不多也消食了，再吃一顿也没问题！",
            ["ContentFR"] = "Parfait. Après l’échauffement, j’ai déjà digéré. On peut bien enchaîner.",
            ["DialogueId"] = 12060805,
            ["GUID"] = "1E3165D2",
            ["NextDialogue"] = 12060806,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120608/1E3165D2",
            },
        [12060806] = {
            ["Content"] = "喂喂我说你们俩……只是通过了海选赛而已，群英试强敌如云，还不到能大意的时候。",
            ["ContentFR"] = "Hé, vous deux... Ce n’était que les éliminatoires. Le Tournoi de l’Encens regorge d’équipes redoutables. Ce n’est pas le moment de fanfaronner.",
            ["DialogueId"] = 12060806,
            ["GUID"] = "1E3165FC",
            ["NextDialogue"] = 12060807,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120608/1E3165FC",
            },
        [12060807] = {
            ["Content"] = "现在小队的战术配合还有不少欠缺之处，所以刚刚我特意让青鸾贰型把我们赛中的表现录了下来。",
            ["ContentFR"] = "Notre coordination laisse encore à désirer. J’ai demandé au Qingluan Type II d’enregistrer la manche.",
            ["DialogueId"] = 12060807,
            ["GUID"] = "1E316626",
            ["NextDialogue"] = 12060808,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120608/1E316626",
            },
        [12060808] = {
            ["Content"] = "有道是温故而知新，我们如果用赛中的间隙复盘，一定能领先别人一步，让之后的成绩更上一层楼。",
            ["ContentFR"] = "On dit qu’en revenant sur le passé, on progresse. Si on analyse nos actions entre les manches, on prendra de l’avance.",
            ["DialogueId"] = 12060808,
            ["GUID"] = "1E316650",
            ["NextDialogue"] = 12060809,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120608/1E316650",
            },
        [12060809] = {
            ["Content"] = "呜哇，我最讨厌学习了——孤儿院的妈妈都没你能念叨，不听不听，王八念经！",
            ["ContentFR"] = "Aaaah non, tout sauf ça ! Même la surveillante de l’orphelinat ne me sermonnait pas autant ! Je n’écoute pas, je n’écoute pas !",
            ["DialogueId"] = 12060809,
            ["GUID"] = "1E31667A",
            ["NextDialogue"] = 12060810,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120608/1E31667A",
            },
        [12060810] = {
            ["Content"] = "顽冥不化！{nickname}，你帮我也说说这家伙！",
            ["ContentFR"] = "Incorrigible ! {nickname}, aide-moi à lui faire entendre raison !",
            ["DialogueId"] = 12060810,
            ["GUID"] = "1E3166A4",
            ["NextOptions"] = {
                [1] = 12060811,
                [2] = 12060812,
                },
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120608/1E3166A4",
            },
        [12060811] = {
            ["Content"] = "饿着肚子是没法赢的。",
            ["ContentFR"] = "<I>On ne gagne pas le ventre vide.</>",
            ["DialogueId"] = 12060811,
            ["GUID"] = "1E3166CE",
            ["ImprPlusId"] = 1203,
            ["NextDialogue"] = 12060813,
            },
        [12060812] = {
            ["Content"] = "妈——",
            ["ContentFR"] = "<I>Oui, Maman...</>",
            ["DialogueId"] = 12060812,
            ["GUID"] = "1E3166F8",
            ["ImprPlusId"] = 1205,
            ["NextDialogue"] = 12060813,
            },
        [12060813] = {
            ["Content"] = "{nickname}，怎么你也……",
            ["ContentFR"] = "...{nickname}, ne me dis pas que toi aussi ?",
            ["DialogueId"] = 12060813,
            ["GUID"] = "1E316722",
            ["NextDialogue"] = 12060814,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120608/1E316722",
            },
        [12060814] = {
            ["Content"] = "苏乙你操心太多啦，适当放松才有助于更好赢下比赛嘛。",
            ["ContentFR"] = "Tu en fais un peu trop, Su Yi. Se détendre un peu nous aidera aussi à gagner.",
            ["DialogueId"] = 12060814,
            ["GUID"] = "1E31674C",
            ["NextDialogue"] = 12060815,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120608/1E31674C",
            },
        [12060815] = {
            ["Content"] = "……唉，拿你们没办法。",
            ["ContentFR"] = "... Je n’ai vraiment aucune autorité sur vous.",
            ["DialogueId"] = 12060815,
            ["GUID"] = "1E316776",
            ["NextDialogue"] = 12060816,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120608/1E316776",
            },
        [12060816] = {
            ["Content"] = "走吧，今天我请客。毕竟是我拜托你们参赛在先。",
            ["ContentFR"] = "Très bien. Allons-y. Aujourd’hui, c’est moi qui invite. Après tout, c’est moi qui vous ai embarqués dans cette histoire.",
            ["DialogueId"] = 12060816,
            ["GUID"] = "1E3167A0",
            ["NextDialogue"] = 12060817,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120608/1E3167A0",
            },
        [12060817] = {
            ["Content"] = "请客？那岂不是意味着随便吃？好耶——记住你这句话了，要把我的八根腕足都喂饱才可以哟，这个我就先收下啦～",
            ["ContentFR"] = "Tu invites ? Ça veut dire... à volonté ? Parfait ! Tu l’as dit — il faudra rassasier mes huit tentacules ! Oh, et ça... je le garde~",
            ["DialogueId"] = 12060817,
            ["GUID"] = "1E3167CA",
            ["NextDialogue"] = 12060818,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120608/1E3167CA",
            },
        [12060818] = {
            ["Content"] = "……我的钱包！什么时候到你手上的！你给我等等！",
            ["ContentFR"] = "... Mon portefeuille ! Depuis quand il est dans tes mains ?! Reviens ici !",
            ["DialogueId"] = 12060818,
            ["GUID"] = "1E3167F4",
            ["NextDialogue"] = 12060819,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120608/1E3167F4",
            },
        [12060819] = {
            ["Content"] = "喂喂，她们怎么一溜烟就没影了，这也跑太快了……小仆从，我们也跟上去吧！",
            ["ContentFR"] = "Hé ! Elles ont disparu en un clin d’œil ?! Elles vont beaucoup trop vite ! Petit larbin, on y va !",
            ["DialogueId"] = 12060819,
            ["GUID"] = "1E31681E",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120608/1E31681E",
            },
        [12060820] = {
            ["Content"] = "听我的，押注“衡起天香”队伍。",
            ["ContentFR"] = "Croyez-moi : misez sur l’équipe « Ascendance Xuanheng ».",
            ["DialogueId"] = 12060820,
            ["GUID"] = "1E316848",
            ["NextDialogue"] = 12060827,
            ["SpeakNpcId"] = 250012,
            ["VoiceName"] = "voice/$Locale$/story/1206/120608/1E316848",
            },
        [12060821] = {
            ["Content"] = "狩月逐香队看起来也非常有潜力！",
            ["ContentFR"] = "Les Chasseurs d’Encens ont aussi du potentiel !",
            ["DialogueId"] = 12060821,
            ["GUID"] = "1E316872",
            ["NextDialogue"] = 12060828,
            ["SpeakNpcId"] = 250013,
            ["VoiceName"] = "voice/$Locale$/story/1206/120608/1E316872",
            },
        [12060822] = {
            ["Content"] = "不仅参赛的队伍很多，城里的大家也在积极讨论群英试的事情……华胥人对奉香大典还真是热情呢。",
            ["ContentFR"] = "Il y a tant d’équipes... et toute la ville ne parle que du tournoi. Les habitants de Huaxu vivent vraiment la Cérémonie de l’Encens avec passion.",
            ["DialogueId"] = 12060822,
            ["GUID"] = "1E31689C",
            ["NextDialogue"] = 12060823,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120608/1E31689C",
            },
        [12060823] = {
            ["Content"] = "毕竟是万众瞩目的赛事，大家的兴趣自然就会被吊起来嘛~",
            ["ContentFR"] = "C’est l’événement le plus attendu de l’année. Impossible que ça laisse qui que ce soit indifférent.",
            ["DialogueId"] = 12060823,
            ["GUID"] = "1E3168C6",
            ["NextDialogue"] = 12060824,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120608/1E3168C6",
            },
        [12060824] = {
            ["Content"] = "你们怎么走这么慢，赶紧过来排队！",
            ["ContentFR"] = "Hé ! Vous traînez ! Venez faire la queue !",
            ["DialogueId"] = 12060824,
            ["GUID"] = "1E3168F0",
            ["NextDialogue"] = 12060825,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120608/1E3168F0",
            },
        [12060825] = {
            ["Content"] = "就是啊！走路慢腾腾的，知不知道小吃只有刚刚出炉的才好吃！",
            ["ContentFR"] = "Exactement ! Les meilleures bouchées sont celles qui sortent tout juste du feu !",
            ["DialogueId"] = 12060825,
            ["GUID"] = "1E31691A",
            ["NextDialogue"] = 12060826,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120608/1E31691A",
            },
        [12060826] = {
            ["Content"] = "这两人在吃方面倒是莫名地有共同语言呢……",
            ["ContentFR"] = "Ces deux-là parlent soudain la même langue quand il s’agit de manger...",
            ["DialogueId"] = 12060826,
            ["GUID"] = "1E316944",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120608/1E316944",
            },
        [12060827] = {
            ["Content"] = "这支队伍由悬衡派弟子中的后起之秀组成，可谓是今年的全明星阵容，妥妥的夺冠热门选手——",
            ["ContentFR"] = "Ils sont composés des jeunes prodiges de la Secte Xuanheng. Leur formation est digne d’une finale.",
            ["DialogueId"] = 12060827,
            ["GUID"] = "1E316849",
            ["NextDialogue"] = 12060821,
            ["SpeakNpcId"] = 250012,
            ["VoiceName"] = "voice/$Locale$/story/1206/120608/1E316849",
            },
        [12060828] = {
            ["Content"] = "有那白发独眼单刀赴会的异国人助阵，绝对是本届群英试的一匹黑马！",
            ["ContentFR"] = "Avec {性别:cet étranger|cette étrangère} aux cheveux blancs et à un seul œil dans leurs rangs, ils pourraient bien être la surprise de cette édition !",
            ["DialogueId"] = 12060828,
            ["GUID"] = "1E316873",
            ["SpeakNpcId"] = 250013,
            ["VoiceName"] = "voice/$Locale$/story/1206/120608/1E316873",
            },
        [12060901] = {
            ["Content"] = "我说，华胥人是魔鬼吗，竟然把章鱼触手放在铁板上烤！",
            ["ContentFR"] = "Attendez... Les habitants de Huaxu sont des démons ou quoi ? Ils grillent des tentacules sur une plaque brûlante !",
            ["DialogueId"] = 12060901,
            ["GUID"] = "1E317592",
            ["NextDialogue"] = 12060902,
            ["RelatedWikiId"] = {
                [1] = 405014,
                [2] = 405015,
                [3] = 203009,
                [4] = 403009,
                [5] = 201029,
                },
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120609/1E317592",
            },
        [12060902] = {
            ["Content"] = "哼哼，这个我知道！锦鲤皎皎早就和本魔王说过了。华胥啊就是万物皆可吃，只有你想不到的菜，没有华胥人做不出来的菜！",
            ["ContentFR"] = "Ah, ça je sais ! Luno, la carpe, me l’a expliqué : à Huaxu, tout finit dans une assiette ! La seule limite, c’est ton imagination !",
            ["DialogueId"] = 12060902,
            ["GUID"] = "1E3175BC",
            ["NextDialogue"] = 12060903,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120609/1E3175BC",
            },
        [12060903] = {
            ["Content"] = "哇，那他们岂不是得有钢铁一样的肠胃……某种意义上还蛮厉害的。",
            ["ContentFR"] = "Leur estomac doit être en acier... Franchement, c’en est presque impressionnant.",
            ["DialogueId"] = 12060903,
            ["GUID"] = "1E3175E6",
            ["NextDialogue"] = 12060904,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120609/1E3175E6",
            },
        [12060904] = {
            ["Content"] = "老板，我现在有钱了，来一份……不对，给我来十份！",
            ["ContentFR"] = "Patron ! Aujourd’hui j’ai de l’argent. Une portion... non — dix !",
            ["DialogueId"] = 12060904,
            ["GUID"] = "1E317610",
            ["NextDialogue"] = 12060905,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120609/1E317610",
            },
        [12060905] = {
            ["Content"] = "喂喂，我说你可悠着点花啊！",
            ["ContentFR"] = "Hé ! Ne gaspille pas tout d’un coup !",
            ["DialogueId"] = 12060905,
            ["GUID"] = "1E31763A",
            ["NextDialogue"] = 12060906,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120609/1E31763A",
            },
        [12060906] = {
            ["Content"] = "哇，你看那个大叔手唰唰抖几下就画出了好大一条龙，动作简直快到看不清！",
            ["ContentFR"] = "Regarde ! Il a à peine bougé les poignets et voilà un immense dragon de sucre ! On ne distingue même pas ses gestes !",
            ["DialogueId"] = 12060906,
            ["GUID"] = "1E317664",
            ["NextDialogue"] = 12060907,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120609/1E317664",
            },
        [12060907] = {
            ["Content"] = "这是糖人张。他在皓京的孩子中间可是很受欢迎的，这铺位从我小的时候就开在这里了。",
            ["ContentFR"] = "C’est Maître Zhang, le confiseur. Il est très apprécié des enfants de Haojing. Son échoppe était déjà là quand j’étais petite.",
            ["DialogueId"] = 12060907,
            ["GUID"] = "1E31768E",
            ["NextDialogue"] = 12060908,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120609/1E31768E",
            },
        [12060908] = {
            ["Content"] = "好厉害……",
            ["ContentFR"] = "... C’est incroyable.",
            ["DialogueId"] = 12060908,
            ["GUID"] = "1E3176B8",
            ["NextDialogue"] = 12060909,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120609/1E3176B8",
            },
        [12060909] = {
            ["Content"] = "可惜食物很快就会坏掉……要是能带回海伯利亚，让别人也能尝尝就好了……",
            ["ContentFR"] = "Dommage que ça ne se conserve pas... Si je pouvais en rapporter à Hyperborea, pour que les autres puissent goûter…",
            ["DialogueId"] = 12060909,
            ["GUID"] = "1E3176E2",
            ["NextDialogue"] = 12060910,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120609/1E3176E2",
            },
        [12060910] = {
            ["Content"] = "我有个主意，要不我们来拍照吧。用照片就可以把这些记忆定格下来了。",
            ["ContentFR"] = "On peut en garder une trace. Prenons des photos.",
            ["DialogueId"] = 12060910,
            ["GUID"] = "1E31770C",
            ["NextDialogue"] = 12060911,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120609/1E31770C",
            },
        [12060911] = {
            ["Content"] = "原来你还有相机这种高档货！",
            ["ContentFR"] = "Tu as un appareil ? Ça, c’est du luxe.",
            ["DialogueId"] = 12060911,
            ["GUID"] = "1E317736",
            ["NextDialogue"] = 12060912,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120609/1E317736",
            },
        [12060912] = {
            ["Content"] = "那还等什么，赶紧赶紧，先拍一下那里的小吃！",
            ["ContentFR"] = "Alors ne traînons pas ! Commence par les plats !",
            ["DialogueId"] = 12060912,
            ["GUID"] = "1E317760",
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120609/1E317760",
            },
        [12060913] = {
            ["Content"] = "让我来看看……",
            ["ContentFR"] = "Voyons ça...",
            ["DialogueId"] = 12060913,
            ["FinalDialogueId"] = 12060918,
            ["GUID"] = "1E31778A",
            ["NextOptions"] = {
                [1] = 12060914,
                [2] = 12060916,
                },
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120609/1E31778A",
            },
        [12060914] = {
            ["Content"] = "苏乙，你的表情怎么这么严肃。",
            ["ContentFR"] = "<I>Su Yi, pourquoi cette expression si grave ?</>",
            ["DialogueId"] = 12060914,
            ["GUID"] = "1E3177B4",
            ["NextDialogue"] = 12060915,
            },
        [12060915] = {
            ["Content"] = "哎？！别人和我说拍照就应该摆这样的表情，难道不是吗？",
            ["ContentFR"] = "Hein ?! On m’a toujours dit qu’il fallait faire cette tête sur les photos... Ce n’est pas ça ?",
            ["DialogueId"] = 12060915,
            ["GUID"] = "1E3177DE",
            ["NextDialogue"] = 12060913,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120609/1E3177DE",
            },
        [12060916] = {
            ["Content"] = "塔比瑟，你的脸占了半张照片这么大。",
            ["ContentFR"] = "<I>Tabethe, ton visage occupe la moitié de la photo.</>",
            ["DialogueId"] = 12060916,
            ["GUID"] = "1E317808",
            ["NextDialogue"] = 12060917,
            },
        [12060917] = {
            ["Content"] = "这样才可以尽显恶魔大盗的风采嘛！",
            ["ContentFR"] = "C’est voulu ! Il faut bien que Démon Tabethe, la Main Rouge, soit au centre de l’attention !",
            ["DialogueId"] = 12060917,
            ["GUID"] = "1E317832",
            ["NextDialogue"] = 12060913,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120609/1E317832",
            },
        [12060918] = {
            ["Content"] = "哼哼～继续继续，小吃街的那一头还没有逛过呢！",
            ["ContentFR"] = "Hihi, allez, on continue ! On n’a pas encore exploré tout le quartier !",
            ["DialogueId"] = 12060918,
            ["GUID"] = "1E31785C",
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120609/1E31785C",
            },
        [12060919] = {
            ["Content"] = "小仆从小仆从，机会难得，不如趁这个机会来拍一张合影吧！",
            ["ContentFR"] = "Petit larbin ! Profitons-en pour faire une photo tous ensemble !",
            ["DialogueId"] = 12060919,
            ["GUID"] = "1E317886",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120609/1E317886",
            },
        [12061001] = {
            ["Content"] = "说书人叔叔，再给我们讲讲上回<H>飘零四杰</>的故事吧，我还想听！",
            ["ContentFR"] = "Monsieur ! Racontez encore l’histoire des <H>Quatre Vagabonds</> !",
            ["DialogueId"] = 12061001,
            ["GUID"] = "1E3185FA",
            ["NextDialogue"] = 12061002,
            ["RelatedWikiId"] = {
                [1] = 405014,
                [2] = 405015,
                [3] = 203009,
                [4] = 201029,
                [5] = 103001,
                },
            ["SpeakNpcId"] = 250014,
            ["VoiceName"] = "voice/$Locale$/story/1206/120610/1E3185FA",
            },
        [12061002] = {
            ["Content"] = "那好——书接上回，话说到那“飘零四杰” 在江边义结金兰，正是年少轻狂，意气风发之时！谁能料想到他们后来……",
            ["ContentFR"] = "Très bien — Là où nous en étions : les Quatre Vagabonds scellaient leur fraternité au bord du fleuve, jeunes et fougueux, l’avenir devant eux... Qui aurait cru que—",
            ["DialogueId"] = 12061002,
            ["GUID"] = "1E318624",
            ["NextDialogue"] = 12061003,
            ["SpeakNpcId"] = 250007,
            ["VoiceName"] = "voice/$Locale$/story/1206/120610/1E318624",
            },
        [12061003] = {
            ["Content"] = "真是太阳打西边出来——世风日下，还有人帮着飘零人说话了。什么“飘零四杰”，简直荒唐！",
            ["ContentFR"] = "Quelle époque pitoyable... On en est réduit à glorifier des Vagabonds ? « Quatre héros », vraiment ?",
            ["DialogueId"] = 12061003,
            ["GUID"] = "1E31864E",
            ["NextDialogue"] = 12061004,
            ["SpeakNpcId"] = 250015,
            ["SpeakNpcName"] = "UI_Npc_Name_Aoman",
            ["VoiceName"] = "voice/$Locale$/story/1206/120610/1E31864E",
            },
        [12061004] = {
            ["Content"] = "……这位客官。我们无冤无仇，您突然冒出来踢场子，这不妥当吧？",
            ["ContentFR"] = "Monsieur, nous n’avons aucun différend. Pourquoi interrompre mon récit ?",
            ["DialogueId"] = 12061004,
            ["GUID"] = "1E318678",
            ["NextDialogue"] = 12061005,
            ["SpeakNpcId"] = 250007,
            ["VoiceName"] = "voice/$Locale$/story/1206/120610/1E318678",
            },
        [12061005] = {
            ["Content"] = "妥当？那你在这里妖言惑众就妥当了？",
            ["ContentFR"] = "Et toi, est-il convenable de propager des rumeurs ?",
            ["DialogueId"] = 12061005,
            ["GUID"] = "1E3186A2",
            ["NextDialogue"] = 12061006,
            ["SpeakNpcId"] = 250015,
            ["SpeakNpcName"] = "UI_Npc_Name_Aoman",
            ["VoiceName"] = "voice/$Locale$/story/1206/120610/1E3186A2",
            },
        [12061006] = {
            ["Content"] = "那飘零四杰引河水浇灭百年不熄的香炉，纵火烧光了六座藏书阁，如此大的动作，当真没有人伤亡？",
            ["ContentFR"] = "Ces soi-disant héros ont détourné le fleuve pour éteindre un brûloir centenaire, puis incendié six pavillons d’archives. Et tu prétends qu’il n’y eut aucune victime ?",
            ["DialogueId"] = 12061006,
            ["GUID"] = "1E3186CC",
            ["NextDialogue"] = 12061007,
            ["SpeakNpcId"] = 250015,
            ["SpeakNpcName"] = "UI_Npc_Name_Aoman",
            ["VoiceName"] = "voice/$Locale$/story/1206/120610/1E3186CC",
            },
        [12061007] = {
            ["Content"] = "那“文竹衔环”在人门前悬挂文竹，行凶伤人。说是为了寻仇，但那手下亡魂就当真是罪有应得？谁给了她们裁决断罪的权力？",
            ["ContentFR"] = "Et ces « Bambou à l’Anneau de Jade » ? Elles accrochaient des branches de bambou aux portes de leurs cibles avant de passer à l’acte. Elles parlaient de vengeance... mais ceux qui sont tombés sous leurs coups méritaient-ils vraiment la mort ? Qui leur a donné le droit de juger et d’exécuter ?",
            ["DialogueId"] = 12061007,
            ["GUID"] = "1E3186F6",
            ["NextDialogue"] = 12061008,
            ["SpeakNpcId"] = 250015,
            ["SpeakNpcName"] = "UI_Npc_Name_Aoman",
            ["VoiceName"] = "voice/$Locale$/story/1206/120610/1E3186F6",
            },
        [12061008] = {
            ["Content"] = "还有那坠落在荒野郊外的机关巨鸟，你应当见过才是。那自天而降的庞然大物毁了多少段河堤，又淹了多少顷良田。此等行径的始作俑者，我说一句居心险恶不为过吧。",
            ["ContentFR"] = "Et ce gigantesque oiseau mécanique écrasé aux confins des plaines — ses débris ont brisé des digues et noyé des terres cultivées. Appelles-tu cela une œuvre vertueuse ?",
            ["DialogueId"] = 12061008,
            ["GUID"] = "1E318720",
            ["NextDialogue"] = 12061009,
            ["SpeakNpcId"] = 250015,
            ["SpeakNpcName"] = "UI_Npc_Name_Aoman",
            ["VoiceName"] = "voice/$Locale$/story/1206/120610/1E318720",
            },
        [12061009] = {
            ["Content"] = "什么飘零人，一群狼狈为奸的恶徒罢了！",
            ["ContentFR"] = "Des Vagabonds ? Une bande de criminels solidaires, voilà tout !",
            ["DialogueId"] = 12061009,
            ["GUID"] = "1E31874A",
            ["NextDialogue"] = 12061010,
            ["RelatedWikiId"] = {
                [1] = 203013,
                },
            ["SpeakNpcId"] = 250015,
            ["SpeakNpcName"] = "UI_Npc_Name_Aoman",
            ["VoiceName"] = "voice/$Locale$/story/1206/120610/1E31874A",
            },
        [12061010] = {
            ["Content"] = "一派胡言！",
            ["ContentFR"] = "Mensonges !",
            ["DialogueId"] = 12061010,
            ["GUID"] = "1E318774",
            ["NextDialogue"] = 12061011,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120610/1E318774",
            },
        [12061011] = {
            ["Content"] = "那灭蒙巨鸟本是为了清通沟渠，兴修水利，是为造福百姓而设计的造物！使它坠毁的另有其人！",
            ["ContentFR"] = "Le Grand Oiseau Miemeng avait été conçu pour dégager les canaux et améliorer l’irrigation — pour le bien du peuple ! Ce n’est pas son créateur qui l’a fait tomber. Quelqu’un d’autre en est responsable !",
            ["DialogueId"] = 12061011,
            ["GUID"] = "1E31879E",
            ["NextDialogue"] = 12061012,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120610/1E31879E",
            },
        [12061012] = {
            ["Content"] = "你不知道事情原委，就不要在这里信口开河，诋毁别人的身后名！",
            ["ContentFR"] = "Tu ignores les faits. Ne salis pas leur mémoire !",
            ["DialogueId"] = 12061012,
            ["GUID"] = "1E3187C8",
            ["NextDialogue"] = 12061013,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120610/1E3187C8",
            },
        [12061013] = {
            ["Content"] = "呵……这事情原委，我不知道，你反倒就知道了？难不成你也是那飘零人的一份子？",
            ["ContentFR"] = "Ah bon ? Toi, tu connaîtrais donc la vérité ? Serais-tu... l’une des leurs ?",
            ["DialogueId"] = 12061013,
            ["GUID"] = "1E3187F2",
            ["NextDialogue"] = 12061014,
            ["SpeakNpcId"] = 250015,
            ["SpeakNpcName"] = "UI_Npc_Name_Aoman",
            ["VoiceName"] = "voice/$Locale$/story/1206/120610/1E3187F2",
            },
        [12061014] = {
            ["Content"] = "（糟糕，如果苏乙的身份在此时暴露，被有心人做文章可能就麻烦了……！）",
            ["ContentFR"] = "<I>Si son identité est révélée ici, cela pourrait tourner à notre désavantage...</>",
            ["DialogueId"] = 12061014,
            ["DisableMouth"] = 1,
            ["GUID"] = "1E31881C",
            ["NextDialogue"] = 12061015,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120610/1E31881C",
            },
        [12061015] = {
            ["Content"] = "当然啦，大家都是道听途说嘛。这事情原委，就看谁编得更真——干脆举办一个讲故事大会好了！",
            ["ContentFR"] = "Mais enfin, tout le monde ne fait que répéter des rumeurs, n’est-ce pas ? Dans ce cas, autant organiser un concours : à qui racontera l’histoire la plus convaincante ?",
            ["DialogueId"] = 12061015,
            ["DisableMouth"] = 1,
            ["GUID"] = "1E318846",
            ["NextDialogue"] = 12061016,
            ["SpeakNpcId"] = 250015,
            ["SpeakNpcName"] = "UI_Npc_Name_AomanT",
            ["VoiceName"] = "voice/$Locale$/story/1206/120610/1E318846",
            },
        [12061016] = {
            ["Content"] = "哎呀，这样一想，万一我编的故事不好，听众会不会不喜欢我呀？不行不行，得赶紧对镜练习一下才行。",
            ["ContentFR"] = "Oh là là... et si mon histoire n’était pas assez bonne ? Et si le public cessait de m’admirer ? Non, non... il faut absolument que j’aille m’entraîner devant un miroir !",
            ["DialogueId"] = 12061016,
            ["DisableMouth"] = 1,
            ["GUID"] = "1E318870",
            ["NextDialogue"] = 12061017,
            ["SpeakNpcId"] = 250015,
            ["SpeakNpcName"] = "UI_Npc_Name_AomanT",
            ["VoiceName"] = "voice/$Locale$/story/1206/120610/1E318870",
            },
        [12061017] = {
            ["Content"] = "……这个人说话怎么颠三倒四的，难不成脑子不好？",
            ["ContentFR"] = "... Mais qu’est-ce qu’il raconte ? Il a perdu la tête ou quoi ?",
            ["DialogueId"] = 12061017,
            ["GUID"] = "1E31889A",
            ["NextDialogue"] = 12061018,
            ["SpeakNpcName"] = "UI_Npc_Name_Guanzhong",
            ["VoiceName"] = "voice/$Locale$/story/1206/120610/1E31889A",
            },
        [12061018] = {
            ["Content"] = "什么人？！竟然敢冒充我说话？！不成体统！",
            ["ContentFR"] = "Qui est là ?! Qui ose imiter ma voix ?! C’est inadmissible !",
            ["DialogueId"] = 12061018,
            ["GUID"] = "1E3188C4",
            ["NextDialogue"] = 12061019,
            ["SpeakNpcId"] = 250015,
            ["SpeakNpcName"] = "UI_Npc_Name_Aoman",
            ["VoiceName"] = "voice/$Locale$/story/1206/120610/1E3188C4",
            },
        [12061019] = {
            ["Content"] = "嘻嘻……什么人吵不过别人就开始反咬一口，惹人发笑！",
            ["ContentFR"] = "Hihi... Quand on ne sait plus quoi répondre, on se met à accuser les autres ? C’est pathétique.",
            ["DialogueId"] = 12061019,
            ["DisableMouth"] = 1,
            ["GUID"] = "1E3188EE",
            ["NextDialogue"] = 12061020,
            ["SpeakNpcId"] = 250015,
            ["SpeakNpcName"] = "UI_Npc_Name_AomanT",
            ["VoiceName"] = "voice/$Locale$/story/1206/120610/1E3188EE",
            },
        [12061020] = {
            ["Content"] = "你……！",
            ["ContentFR"] = "Toi... !",
            ["DialogueId"] = 12061020,
            ["GUID"] = "1E318918",
            ["NextDialogue"] = 12061021,
            ["SpeakNpcId"] = 250015,
            ["SpeakNpcName"] = "UI_Npc_Name_Aoman",
            ["VoiceName"] = "voice/$Locale$/story/1206/120610/1E318918",
            },
        [12061021] = {
            ["Content"] = "妈妈，你快过来看，这个大哥哥在和自己吵架耶！",
            ["ContentFR"] = "Maman ! Regarde ! Le monsieur se dispute tout seul !",
            ["DialogueId"] = 12061021,
            ["GUID"] = "1E318942",
            ["NextDialogue"] = 12061022,
            ["SpeakNpcName"] = "UI_Npc_Name_Guanzhong",
            ["VoiceName"] = "voice/$Locale$/story/1206/120610/1E318942",
            },
        [12061022] = {
            ["Content"] = "……怀远哥，围过来的路人越来越多了。这种时机引人注目，可能会带来不必要的麻烦，别耽误了大计。",
            ["ContentFR"] = "... Huaiyuan, la foule se rapproche. Attirer l’attention en ce moment pourrait nous créer des ennuis. Ne mettons pas nos plans en péril.",
            ["DialogueId"] = 12061022,
            ["GUID"] = "1E31896C",
            ["NextDialogue"] = 12061023,
            ["SpeakNpcId"] = 250016,
            ["VoiceName"] = "voice/$Locale$/story/1206/120610/1E31896C",
            },
        [12061023] = {
            ["Content"] = "算了，赛事在际，不和你纠缠。我们走！",
            ["ContentFR"] = "... <I>Tss.</> Le tournoi approche. Je ne vais pas m’attarder davantage. Nous partons.",
            ["DialogueId"] = 12061023,
            ["GUID"] = "1E318996",
            ["SpeakNpcId"] = 250015,
            ["SpeakNpcName"] = "UI_Npc_Name_Aoman",
            ["VoiceName"] = "voice/$Locale$/story/1206/120610/1E318996",
            },
        [12061101] = {
            ["Content"] = "抱歉，{nickname}。我刚刚没有控制住自己的情绪……",
            ["ContentFR"] = "{nickname}, je suis désolée. Tout à l’heure, je n’ai pas su maîtriser mes émotions...",
            ["DialogueId"] = 12061101,
            ["GUID"] = "1E319662",
            ["NextOptions"] = {
                [1] = 12061102,
                [2] = 12061103,
                },
            ["RelatedWikiId"] = {
                [1] = 405014,
                [2] = 405015,
                [3] = 203009,
                [4] = 201029,
                [5] = 103001,
                [6] = 203013,
                },
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120611/1E319662",
            },
        [12061102] = {
            ["Content"] = "不是你的问题，是那个人说话难听。",
            ["ContentFR"] = "<I>Ce n’est pas ta faute. C’est lui qui a dépassé les bornes.</>",
            ["DialogueId"] = 12061102,
            ["GUID"] = "1E31968C",
            ["NextDialogue"] = 12061104,
            },
        [12061103] = {
            ["Content"] = "冲动一下又怎么了。",
            ["ContentFR"] = "<I>Et alors ? Parfois, on agit sous le coup de l’émotion.</>",
            ["DialogueId"] = 12061103,
            ["GUID"] = "1E3196B6",
            ["NextDialogue"] = 12061104,
            },
        [12061104] = {
            ["Content"] = "那个人刚刚提到的灭蒙巨鸟，是我的姑姑苏暮鹧所造。",
            ["ContentFR"] = "Le Grand Oiseau Miemeng dont il parlait... c’est ma tante, Su Muzhe, qui l’a construit.",
            ["DialogueId"] = 12061104,
            ["GUID"] = "1E3196E0",
            ["NextDialogue"] = 12061105,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120611/1E3196E0",
            },
        [12061105] = {
            ["Content"] = "姑姑她一生都想着怎么用机傀术造福华胥，结果死后还要蒙受这样的冤名。我一时冲动就……",
            ["ContentFR"] = "Toute sa vie, ma tante n’a cherché qu’à utiliser l’art des méchapoupées pour le bien de Huaxu. Et pourtant, même après sa mort, son nom est encore traîné dans la boue... Alors, sur le moment, j’ai perdu mon sang-froid...",
            ["DialogueId"] = 12061105,
            ["GUID"] = "1E31970A",
            ["NextDialogue"] = 12061106,
            ["RelatedWikiId"] = {
                [1] = 203014,
                },
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120611/1E31970A",
            },
        [12061106] = {
            ["Content"] = "没关系的，我理解你。换我在你的位置上，我也会这样做。",
            ["ContentFR"] = "Ce n’est rien. Je comprends. À ta place, j’aurais réagi de la même manière.",
            ["DialogueId"] = 12061106,
            ["GUID"] = "1E319734",
            ["NextDialogue"] = 12061107,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120611/1E319734",
            },
        [12061107] = {
            ["Content"] = "……{nickname}，还好有你陪在我身边。",
            ["ContentFR"] = "... {nickname}. Je suis heureuse que tu sois là.",
            ["DialogueId"] = 12061107,
            ["GUID"] = "1E31975E",
            ["NextDialogue"] = 12061108,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120611/1E31975E",
            },
        [12061108] = {
            ["Content"] = "我呢我呢？是不是也该谢谢帮你解围的本大盗呀？",
            ["ContentFR"] = "Et moi alors ? Je n’ai même pas droit à un merci pour t’avoir tirée d’affaire ?",
            ["DialogueId"] = 12061108,
            ["GUID"] = "1E319788",
            ["NextDialogue"] = 12061109,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120611/1E319788",
            },
        [12061109] = {
            ["Content"] = "不仅帮你教训了一通那个人，我刚刚还偷偷跟了上去，从他们的背包里顺了点有意思的东西哟～怎么样，想不想看看？",
            ["ContentFR"] = "Je lui ai donné une bonne leçon... et après ça, je les ai suivis en douce. Au passage, j’ai récupéré un petit truc intéressant dans leur sac. Alors ? Tu veux voir ?",
            ["DialogueId"] = 12061109,
            ["GUID"] = "1E3197B2",
            ["NextDialogue"] = 12061110,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120611/1E3197B2",
            },
        [12061110] = {
            ["Content"] = "塔·比·瑟！我们不是约法三章了吗？不许偷别人的东西，就算对面是坏人也不能打破这个规矩！",
            ["ContentFR"] = "Ta-be-the ! Nous avions pourtant établi trois règles, non ? Pas de vol — même contre des gens peu recommandables ! On ne change pas les règles quand ça nous arrange !",
            ["DialogueId"] = 12061110,
            ["GUID"] = "1E3197DC",
            ["NextDialogue"] = 12061111,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120611/1E3197DC",
            },
        }
  end },
  { MinKey = 12061111, MaxKey = 12061732, Loader = function()
      return {
        [12061111] = {
            ["Content"] = "哎？人家明明帮了你，你怎么恩将仇报，好伤心……",
            ["ContentFR"] = "Hein ? J’étais pourtant en train de t’aider... et voilà comment tu me remercies ? Mon petit cœur a mal...",
            ["DialogueId"] = 12061111,
            ["GUID"] = "1E319806",
            ["NextDialogue"] = 12061112,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120611/1E319806",
            },
        [12061112] = {
            ["Content"] = "虽然不知道你是怎么躲过大风九章的感应，但那些狴犴和应天尉可不是随便招惹的，要是被他们盯上了，有你的好果子吃。",
            ["ContentFR"] = "Je ne sais pas comment tu as échappé à la vigilance des Neuf Chapitres de Dafeng... mais les Bi’an et les Magistrats de Yingtian ne sont pas des gens qu’on provoque impunément. S’ils commencent à s’intéresser à toi, tu risques de le regretter.",
            ["DialogueId"] = 12061112,
            ["GUID"] = "1E319830",
            ["NextDialogue"] = 12061113,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120611/1E319830",
            },
        [12061113] = {
            ["Content"] = "嘻嘻，原来你是在关心我呀！那你可放心吧，恶魔大盗自有妙计！",
            ["ContentFR"] = "Hihi... alors tu t’inquiètes pour moi ? Ne t’en fais pas. Démon Tabethe, la Main Rouge a toujours un plan !",
            ["DialogueId"] = 12061113,
            ["GUID"] = "1E31985A",
            ["NextDialogue"] = 12061114,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120611/1E31985A",
            },
        [12061114] = {
            ["Content"] = "真的不想看看吗？我在他们背包里找到的这个东西，和你的机关鸟非常相似呢！",
            ["ContentFR"] = "Tu ne veux vraiment pas regarder ? Ce que j’ai trouvé dans leur sac ressemble énormément à ton oiseau mécanique.",
            ["DialogueId"] = 12061114,
            ["GUID"] = "1E319884",
            ["NextDialogue"] = 12061115,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120611/1E319884",
            },
        [12061115] = {
            ["Content"] = "……这是！",
            ["ContentFR"] = "... C’est— !",
            ["DialogueId"] = 12061115,
            ["GUID"] = "1E3198AE",
            ["NextDialogue"] = 12061116,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120611/1E3198AE",
            },
        [12061116] = {
            ["Content"] = "“塔比瑟，不许偷别人的东西”，刚刚这话是谁说的？现在怎么不气急败坏了？",
            ["ContentFR"] = "« Tabethe, pas de vol »... C’était qui déjà, tout à l’heure ? Et maintenant, tu ne cries plus ?",
            ["DialogueId"] = 12061116,
            ["GUID"] = "1E3198D8",
            ["NextDialogue"] = 12061117,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120611/1E3198D8",
            },
        [12061117] = {
            ["Content"] = "一码归一码……现在有更要紧的问题。",
            ["ContentFR"] = "Chaque chose en son temps... Nous avons un problème plus urgent.",
            ["DialogueId"] = 12061117,
            ["GUID"] = "1E319902",
            ["NextDialogue"] = 12061118,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120611/1E319902",
            },
        [12061118] = {
            ["Content"] = "每位机傀师的造物都有自己独一无二的特征。我一眼就能看出，你手上拿着的牵机鸢是我姑姑的遗物。",
            ["ContentFR"] = "Chaque artisan de méchapoupée laisse une signature unique dans ses créations. Je peux l’affirmer sans hésiter... le cerf-volant mécanique que tu tiens appartenait à ma tante.",
            ["DialogueId"] = 12061118,
            ["GUID"] = "1E31992C",
            ["NextDialogue"] = 12061119,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120611/1E31992C",
            },
        [12061119] = {
            ["Content"] = "但这是怎么到他们手上的？他们又为什么会随身带着姑姑的牵机鸢……莫非这些人对飘零人的厌恶并非空穴来风，还有更深一层的关联……",
            ["ContentFR"] = "Mais comment cet objet s’est-il retrouvé entre leurs mains ? Et pourquoi l’avaient-ils avec eux... Peut-être que leur haine des Vagabonds ne vient pas de nulle part. Il y a sûrement autre chose derrière tout ça...",
            ["DialogueId"] = 12061119,
            ["GUID"] = "1E319956",
            ["NextDialogue"] = 12061120,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120611/1E319956",
            },
        [12061120] = {
            ["Content"] = "哎？也就是说本大盗立功了的意思？",
            ["ContentFR"] = "Hein ? Donc ça veut dire que j’ai rendu un grand service ?",
            ["DialogueId"] = 12061120,
            ["GUID"] = "1E319980",
            ["NextDialogue"] = 12061121,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120611/1E319980",
            },
        [12061121] = {
            ["Content"] = "那就再告诉你一件事——我刚刚想起来，我来到华胥码头上第一眼就撞见了这几个人。他们在那边小声议论着飘零人怎么怎么样，所以我才不小心误解了你。",
            ["ContentFR"] = "Ah, et une autre chose ! Je viens de me rappeler : quand je suis arrivée au port de Huaxu, ces types étaient les premiers que j’ai croisés. Ils murmuraient déjà des choses sur les Vagabonds... C’est pour ça que je t’avais mal jugée au début.",
            ["DialogueId"] = 12061121,
            ["GUID"] = "1E3199AA",
            ["NextDialogue"] = 12061122,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120611/1E3199AA",
            },
        [12061122] = {
            ["Content"] = "怎么样怎么样？本大盗提供的情报是不是很有用，赶紧夸夸我！",
            ["ContentFR"] = "Alors ? Alors ? Mes informations sont utiles, non ? Allez, félicite-moi !",
            ["DialogueId"] = 12061122,
            ["GUID"] = "1E3199D4",
            ["NextDialogue"] = 12061123,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120611/1E3199D4",
            },
        [12061123] = {
            ["Content"] = "……谢谢。",
            ["ContentFR"] = "... Merci.",
            ["DialogueId"] = 12061123,
            ["GUID"] = "1E3199FE",
            ["NextDialogue"] = 12061124,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120611/1E3199FE",
            },
        [12061124] = {
            ["Content"] = "哇！太阳从西边出来了！总是板着一张脸的苏乙竟然会对别人说谢谢！",
            ["ContentFR"] = "Quoi ?! Il va neiger ou quoi ? Su Yi vient de dire merci !",
            ["DialogueId"] = 12061124,
            ["GUID"] = "1E319A28",
            ["NextDialogue"] = 12061125,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120611/1E319A28",
            },
        [12061125] = {
            ["Content"] = "……你这话说的，好像我是什么洪水猛兽一样！受到别人帮助就要说谢谢，这是天经地义的事情，姑姑从小就是这样教我的！",
            ["ContentFR"] = "... Tu parles comme si j’étais un monstre ! Quand quelqu’un nous aide, on le remercie. C’est la moindre des choses. Ma tante m’a appris cela depuis que je suis enfant !",
            ["DialogueId"] = 12061125,
            ["GUID"] = "1E319A52",
            ["NextDialogue"] = 12061126,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120611/1E319A52",
            },
        [12061126] = {
            ["Content"] = "什么嘛！你对恶魔大盗的感激之情才持续了不到半分钟，没劲。",
            ["ContentFR"] = "Quoi ?! Ta gratitude envers moi n’a même pas tenu trente secondes. Pas drôle.",
            ["DialogueId"] = 12061126,
            ["GUID"] = "1E319A7C",
            ["NextDialogue"] = 12061127,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120611/1E319A7C",
            },
        [12061127] = {
            ["Content"] = "我说，小插曲到此为止，我们继续去庆功吧。这个摊子，那里，还有拐角那边，都没有吃过呢。",
            ["ContentFR"] = "Bon, assez parlé. Reprenons notre célébration ! Ce stand, celui-là, et celui au coin... on ne les a pas encore essayés !",
            ["DialogueId"] = 12061127,
            ["GUID"] = "1E319AA6",
            ["NextDialogue"] = 12061128,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120611/1E319AA6",
            },
        [12061128] = {
            ["Content"] = "{nickname}，塔比瑟，你们先去逛吧。",
            ["ContentFR"] = "{nickname}, Tabethe... allez-y sans moi.",
            ["DialogueId"] = 12061128,
            ["GUID"] = "1E319AD0",
            ["NextDialogue"] = 12061129,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120611/1E319AD0",
            },
        [12061129] = {
            ["Content"] = "离下午的赛事还有一段时间，我想研究一下姑姑的遗物，看看能不能获得什么有用的信息。",
            ["ContentFR"] = "Il reste encore un peu de temps avant la manche de l’après-midi. Je veux examiner de plus près le cerf-volant mécanique de ma tante et voir si je peux en tirer quelque chose.",
            ["DialogueId"] = 12061129,
            ["GUID"] = "1E319AFA",
            ["NextDialogue"] = 12061130,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120611/1E319AFA",
            },
        [12061130] = {
            ["Content"] = "反正我的钱包也在你手里了……但你们别吃太多了，影响下午的比赛状态，听到了吗？",
            ["ContentFR"] = "De toute façon, mon portefeuille est déjà entre tes mains... Mais n’abusez pas trop de la nourriture, d’accord ? Ce serait dommage d’arriver au tournoi avec l’estomac trop lourd.",
            ["DialogueId"] = 12061130,
            ["GUID"] = "1E319B24",
            ["NextDialogue"] = 12061131,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120611/1E319B24",
            },
        [12061131] = {
            ["Content"] = "知——道——啦——苏乙妈妈！",
            ["ContentFR"] = "Oui, oui, Mamaaan Su Yi !",
            ["DialogueId"] = 12061131,
            ["GUID"] = "1E319B4E",
            ["NextDialogue"] = 12061132,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120611/1E319B4E",
            },
        [12061132] = {
            ["Content"] = "好，那我们一会儿在赛场会合。",
            ["ContentFR"] = "Très bien. On se retrouve à l’arène tout à l’heure.",
            ["DialogueId"] = 12061132,
            ["GUID"] = "1E319B78",
            ["NextDialogue"] = 12061133,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120611/1E319B78",
            },
        [12061133] = {
            ["Content"] = "嗯，赛场见。",
            ["ContentFR"] = "D’accord. À tout à l’heure.",
            ["DialogueId"] = 12061133,
            ["GUID"] = "1E319BA2",
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120611/1E319BA2",
            },
        [12061134] = {
            ["DialogueId"] = 12061134,
            ["GUID"] = "1E319BCC",
            ["VoiceName"] = "voice/$Locale$/story/1206/120611/1E319BCC",
            },
        [12061135] = {
            ["Content"] = "地狱辣挑战火热进行中——能吃完这碗担担面的挑战者，不仅能够免单，还将获得本店专门准备的豪华大礼！",
            ["ContentFR"] = "Défi piment infernal ! Finissez ce bol de dandanmian et le repas est offert ! Et en prime, un gros lot de la maison !",
            ["DialogueId"] = 12061135,
            ["GUID"] = "1E319BF6",
            ["NextDialogue"] = 12061136,
            ["SpeakNpcId"] = 250031,
            ["VoiceName"] = "voice/$Locale$/story/1206/120611/1E319BF6",
            },
        [12061136] = {
            ["Content"] = "豪华大礼？",
            ["ContentFR"] = "Un grand lot ?",
            ["DialogueId"] = 12061136,
            ["GUID"] = "1E319C20",
            ["NextDialogue"] = 12061137,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120611/1E319C20",
            },
        [12061137] = {
            ["Content"] = "嘻嘻，说出口的事情可不能再反悔，算上我一个！",
            ["ContentFR"] = "Hihi. Une promesse est une promesse ! Compte sur moi !",
            ["DialogueId"] = 12061137,
            ["GUID"] = "1E319C4A",
            ["NextDialogue"] = 12061138,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120611/1E319C4A",
            },
        [12061138] = {
            ["Content"] = "好嘞！这就给您端上来！",
            ["ContentFR"] = "Très bien ! Je vous apporte ça tout de suite !",
            ["DialogueId"] = 12061138,
            ["GUID"] = "1E319C74",
            ["SpeakNpcId"] = 250031,
            ["VoiceName"] = "voice/$Locale$/story/1206/120611/1E319C74",
            },
        [12061201] = {
            ["Content"] = "一个小时后，奉香群英试报名处。",
            ["ContentFR"] = "Une heure plus tard — bureau d’inscription du Tournoi de l’Encens.",
            ["DialogueId"] = 12061201,
            ["GUID"] = "1E31A6CA",
            ["NextDialogue"] = 12061202,
            ["RelatedWikiId"] = {
                [1] = 405014,
                [2] = 405015,
                [3] = 203009,
                [4] = 201029,
                [5] = 103001,
                [6] = 203013,
                [7] = 203014,
                },
            ["VoiceName"] = "voice/$Locale$/story/1206/120612/1E31A6CA",
            },
        [12061202] = {
            ["Content"] = "塔比瑟那家伙呢，还没出现吗？！",
            ["ContentFR"] = "Où est passée Tabethe ?! Elle n’est toujours pas là ?",
            ["DialogueId"] = 12061202,
            ["GUID"] = "1E31A6F4",
            ["NextDialogue"] = 12061203,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120612/1E31A6F4",
            },
        [12061203] = {
            ["Content"] = "半小时前她跑去买吃的，然后就没看到过她了……要不我去找找她？",
            ["ContentFR"] = "Elle est partie acheter quelque chose à manger il y a une demi-heure... et je ne l’ai pas revue depuis. Tu veux que j’aille la chercher ?",
            ["DialogueId"] = 12061203,
            ["GUID"] = "1E31A71E",
            ["NextDialogue"] = 12061204,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120612/1E31A71E",
            },
        [12061204] = {
            ["Content"] = "好，你赶紧去。我们在这里等你的消息。",
            ["ContentFR"] = "Oui, vas-y. Nous t’attendons ici.",
            ["DialogueId"] = 12061204,
            ["GUID"] = "1E31A748",
            ["NextDialogue"] = 12061205,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120612/1E31A748",
            },
        [12061205] = {
            ["Content"] = "几位，入场时间快截止了，你们的队伍还没有到齐吗？",
            ["ContentFR"] = "Mesdemoiselles, messieurs. L’heure d’entrée va bientôt expirer. Votre équipe n’est toujours pas complète ?",
            ["DialogueId"] = 12061205,
            ["GUID"] = "1E31A772",
            ["NextDialogue"] = 12061206,
            ["SpeakNpcId"] = 250011,
            ["VoiceName"] = "voice/$Locale$/story/1206/120612/1E31A772",
            },
        [12061206] = {
            ["Content"] = "等等！这次赛事手册的一万三千字规则我都细细通读过，如果临时更换队员，可以申请十分钟的延迟入场，对吗？",
            ["ContentFR"] = "Attendez ! J’ai lu attentivement les treize mille mots du règlement. Si un membre de l’équipe est remplacé au dernier moment, il est possible de demander un délai d’entrée de dix minutes. C’est exact ?",
            ["DialogueId"] = 12061206,
            ["GUID"] = "1E31A79C",
            ["NextDialogue"] = 12061207,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120612/1E31A79C",
            },
        [12061207] = {
            ["Content"] = "呵呵，倒是少有人将赛事规则研究得这么细致。",
            ["ContentFR"] = "Hum. Peu de gens étudient les règles avec autant de soin.",
            ["DialogueId"] = 12061207,
            ["GUID"] = "1E31A7C6",
            ["NextDialogue"] = 12061208,
            ["SpeakNpcId"] = 250011,
            ["VoiceName"] = "voice/$Locale$/story/1206/120612/1E31A7C6",
            },
        [12061208] = {
            ["Content"] = "是有这个规定，那便依了你。但如果十分钟后你们的同伴还没有来，那就过时不候了。",
            ["ContentFR"] = "Effectivement, cette clause existe. Je peux vous accorder dix minutes supplémentaires. Mais si votre coéquipière n’est pas revenue d’ici là... il sera trop tard.",
            ["DialogueId"] = 12061208,
            ["GUID"] = "1E31A7F0",
            ["NextDialogue"] = 12061209,
            ["SpeakNpcId"] = 250011,
            ["VoiceName"] = "voice/$Locale$/story/1206/120612/1E31A7F0",
            },
        [12061209] = {
            ["Content"] = "那家伙，到底跑去哪里了……实在是让人不省心……",
            ["ContentFR"] = "Mais où est-elle passée... ? Cette fille est vraiment impossible...",
            ["DialogueId"] = 12061209,
            ["GUID"] = "1E31A81A",
            ["NextDialogue"] = 12061210,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120612/1E31A81A",
            },
        [12061210] = {
            ["Content"] = "大老远我就听到有谁在这里磨磨蹭蹭的，没想到竟是你。这叫什么，不是冤家不聚头吗？",
            ["ContentFR"] = "Je me demandais qui pouvait traîner ici en faisant perdre du temps à tout le monde. Quelle surprise... c’est toi. Comme on dit : les ennemis finissent toujours par se retrouver.",
            ["DialogueId"] = 12061210,
            ["GUID"] = "1E31A844",
            ["NextDialogue"] = 12061211,
            ["SpeakNpcId"] = 250015,
            ["VoiceName"] = "voice/$Locale$/story/1206/120612/1E31A844",
            },
        [12061211] = {
            ["Content"] = "别把希望寄托在虚无缥缈的事情上了。比赛都要开始了，你这同伴怕不是已经胆小逃跑了吧？",
            ["ContentFR"] = "Inutile de fonder tes espoirs sur quelque chose d’aussi incertain. La manche va commencer. Ta coéquipière s’est sans doute dégonflée et a pris la fuite.",
            ["DialogueId"] = 12061211,
            ["GUID"] = "1E31A86E",
            ["NextDialogue"] = 12061212,
            ["SpeakNpcId"] = 250015,
            ["VoiceName"] = "voice/$Locale$/story/1206/120612/1E31A86E",
            },
        [12061212] = {
            ["Content"] = "刚刚落荒而逃的明明是你吧？",
            ["ContentFR"] = "Curieux... car tout à l’heure, celui qui s’est enfui la queue entre les jambes, c’était toi.",
            ["DialogueId"] = 12061212,
            ["GUID"] = "1E31A898",
            ["NextDialogue"] = 12061213,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120612/1E31A898",
            },
        [12061213] = {
            ["Content"] = "落荒而逃？呵，看来苏暮鹧的支持者就和她本人一样，不分青红皂白，黑的都能说成白的。",
            ["ContentFR"] = "Fuir ? Hum... Les partisans de Su Muzhe sont bien comme elle : capables de faire passer le faux pour le vrai.",
            ["DialogueId"] = 12061213,
            ["GUID"] = "1E31A8C2",
            ["NextDialogue"] = 12061214,
            ["SpeakNpcId"] = 250015,
            ["VoiceName"] = "voice/$Locale$/story/1206/120612/1E31A8C2",
            },
        [12061214] = {
            ["Content"] = "……我奉劝你不要再说她半个字坏话！",
            ["ContentFR"] = "... Je te conseille de ne plus prononcer son nom avec mépris.",
            ["DialogueId"] = 12061214,
            ["GUID"] = "1E31A8EC",
            ["NextOptions"] = {
                [1] = 12061215,
                [2] = 12061216,
                },
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120612/1E31A8EC",
            },
        [12061215] = {
            ["Content"] = "（沉默地上前站在苏乙身旁。）",
            ["ContentFR"] = "<I>S’approcher silencieusement et se placer aux côtés de Su Yi</>",
            ["DialogueId"] = 12061215,
            ["GUID"] = "1E31A916",
            ["ImprPlusId"] = 1204,
            ["NextDialogue"] = 12061217,
            },
        [12061216] = {
            ["Content"] = "来，战啊！",
            ["ContentFR"] = "<I>Viens donc te battre !</>",
            ["DialogueId"] = 12061216,
            ["GUID"] = "1E31A940",
            ["ImprPlusId"] = 1205,
            ["NextDialogue"] = 12061217,
            },
        [12061217] = {
            ["Content"] = "何事在此喧闹？",
            ["ContentFR"] = "Que se passe-t-il ici ?",
            ["DialogueId"] = 12061217,
            ["GUID"] = "1E31A96A",
            ["NextDialogue"] = 12061218,
            ["RelatedWikiId"] = {
                [1] = 203004,
                },
            ["SpeakNpcId"] = 250005,
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["VoiceName"] = "voice/$Locale$/story/1206/120612/1E31A96A",
            },
        [12061218] = {
            ["Content"] = "……应天尉大人？",
            ["ContentFR"] = "... Un Magistrat de Yingtian ?",
            ["DialogueId"] = 12061218,
            ["GUID"] = "1E31A994",
            ["NextDialogue"] = 12061219,
            ["SpeakNpcId"] = 250015,
            ["VoiceName"] = "voice/$Locale$/story/1206/120612/1E31A994",
            },
        [12061219] = {
            ["Content"] = "煜明，你怎么来了？是来这里处理公务的吗？",
            ["ContentFR"] = "Yuming ? Que fais-tu ici ? Tu es en mission ?",
            ["DialogueId"] = 12061219,
            ["GUID"] = "1E31A9BE",
            ["NextDialogue"] = 12061220,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120612/1E31A9BE",
            },
        [12061220] = {
            ["Content"] = "并非，在下此行因私事前来。虽非在职之身，但若有纠纷，我可调解一二。",
            ["ContentFR"] = "Non. Je suis ici pour une affaire personnelle. Je ne suis pas en service, mais s’il y a un différend, je peux intervenir pour apaiser les choses.",
            ["DialogueId"] = 12061220,
            ["GUID"] = "1E31A9E8",
            ["NextDialogue"] = 12061221,
            ["SpeakNpcId"] = 250005,
            ["VoiceName"] = "voice/$Locale$/story/1206/120612/1E31A9E8",
            },
        [12061221] = {
            ["Content"] = "……只是些平常口角，还不需要劳烦应天尉大人出面。",
            ["ContentFR"] = "... Ce n’était qu’un échange de paroles. Il n’est pas nécessaire de vous déranger pour si peu.",
            ["DialogueId"] = 12061221,
            ["GUID"] = "1E31AA12",
            ["NextDialogue"] = 12061222,
            ["SpeakNpcId"] = 250015,
            ["VoiceName"] = "voice/$Locale$/story/1206/120612/1E31AA12",
            },
        [12061222] = {
            ["Content"] = "既然是不违背大风九章的争执，二位还请各退一步，息事宁人吧。如此可好？",
            ["ContentFR"] = "Puisqu’il s’agit d’un différend qui n’enfreint pas les Neuf Chapitres de Dafeng, je vous demanderai à tous deux de faire un pas en arrière et d’en rester là. Cela vous convient-il ?",
            ["DialogueId"] = 12061222,
            ["GUID"] = "1E31AA3C",
            ["NextDialogue"] = 12061223,
            ["SpeakNpcId"] = 250005,
            ["VoiceName"] = "voice/$Locale$/story/1206/120612/1E31AA3C",
            },
        [12061223] = {
            ["Content"] = "诸位，别来无恙。",
            ["ContentFR"] = "Cela faisait longtemps. J’espère que vous allez bien.",
            ["DialogueId"] = 12061223,
            ["GUID"] = "1E31AA66",
            ["NextDialogue"] = 12061224,
            ["SpeakNpcId"] = 250005,
            ["VoiceName"] = "voice/$Locale$/story/1206/120612/1E31AA66",
            },
        [12061224] = {
            ["Content"] = "…………",
            ["ContentFR"] = "...",
            ["DialogueId"] = 12061224,
            ["GUID"] = "1E31AA90",
            ["NextDialogue"] = 12061225,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120612/1E31AA90",
            },
        [12061225] = {
            ["Content"] = "小仆从小仆从，大事不好了！塔比瑟说她肚子不舒服来不了了——咦，煜明，你怎么在这里？",
            ["ContentFR"] = "Petit larbin ! Catastrophe ! Tabethe dit qu’elle a mal au ventre et qu’elle ne pourra pas venir — Hein ? Yuming ? Qu’est-ce que tu fais ici ?",
            ["DialogueId"] = 12061225,
            ["GUID"] = "1E31AABA",
            ["NextDialogue"] = 12061226,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120612/1E31AABA",
            },
        [12061226] = {
            ["Content"] = "在下受人所托，那位关注到你们的困境，特意委托我前来助你们参加群英试。公平起见，本次赛事中煜明不会借用大风九章的力量，仅以一身武艺参赛。",
            ["ContentFR"] = "Je suis ici à la demande de quelqu’un. Cette personne a appris que vous étiez en difficulté et m’a chargé de vous aider à participer au tournoi. Par souci d’équité, je n’emprunterai pas la puissance des Neuf Chapitres de Dafeng durant cette compétition. Je combattrai uniquement avec mes propres compétences.",
            ["DialogueId"] = 12061226,
            ["GUID"] = "1E31AAE4",
            ["NextDialogue"] = 12061227,
            ["SpeakNpcId"] = 250005,
            ["VoiceName"] = "voice/$Locale$/story/1206/120612/1E31AAE4",
            },
        [12061227] = {
            ["Content"] = "哇，是谁这么好心！",
            ["ContentFR"] = "Ouah ! Mais qui peut bien être aussi gentil ?",
            ["DialogueId"] = 12061227,
            ["GUID"] = "1E31AB0E",
            ["NextDialogue"] = 12061228,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120612/1E31AB0E",
            },
        [12061228] = {
            ["Content"] = "……受人所托？……我不需要谁的帮助，自己就能渡过难关。",
            ["ContentFR"] = "... À la demande de quelqu’un ? Je n’ai besoin de l’aide de personne. Je peux m’en sortir seule.",
            ["DialogueId"] = 12061228,
            ["GUID"] = "1E31AB38",
            ["NextDialogue"] = 12061229,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120612/1E31AB38",
            },
        [12061229] = {
            ["Content"] = "诶？苏乙……",
            ["ContentFR"] = "Hein ? Su Yi...",
            ["DialogueId"] = 12061229,
            ["GUID"] = "1E31AB62",
            ["NextDialogue"] = 12061230,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120612/1E31AB62",
            },
        [12061230] = {
            ["Content"] = "几位，抱歉打断你们的交谈。时限快到了，无论是更换队友继续参赛，还是在这里弃权，都需要你们尽快做出决定。",
            ["ContentFR"] = "Veuillez m’excuser d’interrompre votre conversation. Le temps est presque écoulé. Que vous décidiez de remplacer votre coéquipière et de continuer, ou d’abandonner ici, vous devez prendre votre décision immédiatement.",
            ["DialogueId"] = 12061230,
            ["GUID"] = "1E31AB8C",
            ["NextDialogue"] = 12061231,
            ["SpeakNpcId"] = 250011,
            ["VoiceName"] = "voice/$Locale$/story/1206/120612/1E31AB8C",
            },
        [12061231] = {
            ["Content"] = "呜啊，这就是糟糕的事情一定会同时发生的定律吧！怎么办，急得快团团转了！",
            ["ContentFR"] = "Aaaah... Pourquoi les ennuis arrivent toujours tous en même temps ?! Qu’est-ce qu’on fait ?!",
            ["DialogueId"] = 12061231,
            ["GUID"] = "1E31ABB6",
            ["NextDialogue"] = 12061232,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120612/1E31ABB6",
            },
        [12061232] = {
            ["Content"] = "苏乙，先开始比赛吧。有什么事赛后再说，好吗？",
            ["ContentFR"] = "Su Yi... commençons d’abord la manche. Nous réglerons le reste après, d’accord ?",
            ["DialogueId"] = 12061232,
            ["GUID"] = "1E31ABE0",
            ["NextDialogue"] = 12061233,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120612/1E31ABE0",
            },
        [12061233] = {
            ["Content"] = "……好，我答应你。",
            ["ContentFR"] = "... Très bien. Je te fais confiance.",
            ["DialogueId"] = 12061233,
            ["GUID"] = "1E31AC0A",
            ["NextDialogue"] = 12061234,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120612/1E31AC0A",
            },
        [12061234] = {
            ["Content"] = "煜明，接下来的比赛，还要拜托你了。",
            ["ContentFR"] = "Yuming, nous comptons sur toi pour la suite du tournoi.",
            ["DialogueId"] = 12061234,
            ["GUID"] = "1E31AC34",
            ["NextDialogue"] = 12061235,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120612/1E31AC34",
            },
        [12061235] = {
            ["Content"] = "愿为驱驰。",
            ["ContentFR"] = "Je ferai de mon mieux.",
            ["DialogueId"] = 12061235,
            ["GUID"] = "1E31AC5E",
            ["SpeakNpcId"] = 250005,
            ["VoiceName"] = "voice/$Locale$/story/1206/120612/1E31AC5E",
            },
        [12061301] = {
            ["Content"] = "明明比赛获胜了，大家怎么都板着脸一副不高兴的样子……",
            ["ContentFR"] = "On a gagné... alors pourquoi tout le monde tire une tête pareille ?",
            ["DialogueId"] = 12061301,
            ["GUID"] = "1E31B732",
            ["NextDialogue"] = 12061302,
            ["RelatedWikiId"] = {
                [1] = 203009,
                [2] = 203004,
                [3] = 201029,
                [4] = 103001,
                [5] = 203013,
                [6] = 203014,
                [7] = 408018,
                },
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120613/1E31B732",
            },
        [12061302] = {
            ["Content"] = "那个……虽然塔比瑟那家伙放鸽子了，但你们也不用这么生气吧。",
            ["ContentFR"] = "Euh... bon, d’accord, Tabethe nous a posé un lapin, mais vous n’avez pas besoin d’être aussi fâchés...",
            ["DialogueId"] = 12061302,
            ["GUID"] = "1E31B75C",
            ["NextDialogue"] = 12061303,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120613/1E31B75C",
            },
        [12061303] = {
            ["Content"] = "苏乙，赛前时间仓促，我无暇过问。但有一件事让我无法不挂心。",
            ["ContentFR"] = "Su Yi. Avant la manche, nous n’avons pas eu le temps de parler. Mais une chose me préoccupe.",
            ["DialogueId"] = 12061303,
            ["GUID"] = "1E31B786",
            ["NextDialogue"] = 12061304,
            ["SpeakNpcId"] = 250005,
            ["VoiceName"] = "voice/$Locale$/story/1206/120613/1E31B786",
            },
        [12061304] = {
            ["Content"] = "刚刚你和那人争执之时，提到了苏暮鹧的名字。你们的口角因何而起？事到如今，你……依然无法释怀吗？",
            ["ContentFR"] = "Tout à l’heure, lors de ton altercation avec cet homme, tu as mentionné Su Muzhe. Qu’est-ce qui a provoqué cette dispute ? Et... après tout ce temps, tu n’as toujours pas réussi à tourner la page ?",
            ["DialogueId"] = 12061304,
            ["GUID"] = "1E31B7B0",
            ["NextDialogue"] = 12061305,
            ["SpeakNpcId"] = 250005,
            ["VoiceName"] = "voice/$Locale$/story/1206/120613/1E31B7B0",
            },
        [12061305] = {
            ["Content"] = "有人侮辱了姑姑的名誉，我自然要还击。怎么，你有意见吗？",
            ["ContentFR"] = "Quelqu’un a insulté la mémoire de ma tante. Il était normal que je réponde. Pourquoi ? Tu as un problème avec ça ?",
            ["DialogueId"] = 12061305,
            ["GUID"] = "1E31B7DA",
            ["NextDialogue"] = 12061306,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120613/1E31B7DA",
            },
        [12061306] = {
            ["Content"] = "煜明无意多事。只是这样妄起争执，或许会让山外山的人担心。",
            ["ContentFR"] = "Je ne cherche pas à m’immiscer dans tes affaires. Je crains seulement que ce genre de scène n’attire l’attention sur les Pics Extérieurs.",
            ["DialogueId"] = 12061306,
            ["GUID"] = "1E31B804",
            ["NextDialogue"] = 12061307,
            ["SpeakNpcId"] = 250005,
            ["VoiceName"] = "voice/$Locale$/story/1206/120613/1E31B804",
            },
        [12061307] = {
            ["Content"] = "你的意思是让我在这个节骨眼上安分一点？觉得飘零人在这种敏感时候出风头会给山外山带来麻烦？",
            ["ContentFR"] = "Donc tu voudrais que je me fasse discrète dans un moment pareil ? Tu penses qu’un Vagabond qui attire l’attention dans une période aussi sensible va causer des ennuis aux Pics Extérieurs ?",
            ["DialogueId"] = 12061307,
            ["GUID"] = "1E31B82E",
            ["NextDialogue"] = 12061308,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120613/1E31B82E",
            },
        [12061308] = {
            ["Content"] = "抱歉，虽然不知道是谁拜托你来的，但是我拒绝。你或许能以身作则，说着什么“既往不咎”就转身投靠大风九章，但我做不到。",
            ["ContentFR"] = "Désolée. Je ne sais pas qui t’a demandé de venir, mais je refuse. Peut-être que toi, tu peux tourner la page et rejoindre les Neuf Chapitres de Dafeng comme si de rien n’était. Moi, je n’en suis pas capable.",
            ["DialogueId"] = 12061308,
            ["GUID"] = "1E31B858",
            ["NextDialogue"] = 12061309,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120613/1E31B858",
            },
        [12061309] = {
            ["Content"] = "…………苏乙，你可能有所误解。",
            ["ContentFR"] = "... Su Yi. Tu te méprends.",
            ["DialogueId"] = 12061309,
            ["GUID"] = "1E31B882",
            ["NextDialogue"] = 12061310,
            ["SpeakNpcId"] = 250005,
            ["VoiceName"] = "voice/$Locale$/story/1206/120613/1E31B882",
            },
        [12061310] = {
            ["Content"] = "这里的空气太闷了。下场赛事开始还要半个小时吧？中场休息时间我想出去走走。",
            ["ContentFR"] = "L’air est étouffant ici. La prochaine manche commence dans une demi-heure, n’est-ce pas ? Je vais prendre l’air pendant la pause.",
            ["DialogueId"] = 12061310,
            ["GUID"] = "1E31B8AC",
            ["NextDialogue"] = 12061311,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120613/1E31B8AC",
            },
        [12061311] = {
            ["Content"] = "{nickname}，这边就先交给你们了。",
            ["ContentFR"] = "{nickname}, je vous laisse vous en occuper.",
            ["DialogueId"] = 12061311,
            ["GUID"] = "1E31B8D6",
            ["NextDialogue"] = 12061312,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120613/1E31B8D6",
            },
        [12061312] = {
            ["Content"] = "呜，气氛怎么会变成这样……",
            ["ContentFR"] = "Aaaah... comment l’ambiance a pu devenir aussi bizarre...",
            ["DialogueId"] = 12061312,
            ["GUID"] = "1E31B900",
            ["NextDialogue"] = 12061313,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120613/1E31B900",
            },
        [12061313] = {
            ["Content"] = "……{nickname}，苏乙和我之间恐怕有着诸多误会。我若是继续失言，只会让她徒增烦恼。可否劳烦你去安抚她一二？",
            ["ContentFR"] = "... {nickname}. Il existe de nombreux malentendus entre Su Yi et moi. Si je parle davantage, je ne ferai que la contrarier davantage. Pourrais-tu aller lui parler ?",
            ["DialogueId"] = 12061313,
            ["GUID"] = "1E31B92A",
            ["NextDialogue"] = 12061314,
            ["SpeakNpcId"] = 250005,
            ["VoiceName"] = "voice/$Locale$/story/1206/120613/1E31B92A",
            },
        [12061314] = {
            ["Content"] = "嗯，不用你说我也会的。",
            ["ContentFR"] = "Même si tu ne l’avais pas demandé, j’y serais {性别:allé|allée}.",
            ["DialogueId"] = 12061314,
            ["GUID"] = "1E31B954",
            ["NextDialogue"] = 12061315,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120613/1E31B954",
            },
        [12061315] = {
            ["Content"] = "白，你和煜明在这里等着我好吗？我去带苏乙回来。",
            ["ContentFR"] = "Snow, reste ici avec Yuming. Je vais retrouver Su Yi.",
            ["DialogueId"] = 12061315,
            ["GUID"] = "1E31B97E",
            ["NextDialogue"] = 12061316,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120613/1E31B97E",
            },
        [12061316] = {
            ["Content"] = "好，小仆从，那你快去快回。",
            ["ContentFR"] = "D’accord, petit larbin. Reviens vite.",
            ["DialogueId"] = 12061316,
            ["GUID"] = "1E31B9A8",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120613/1E31B9A8",
            },
        [12061401] = {
            ["Content"] = "找你找了半天，没想到你一个人躲在这儿玩狗尾巴草。怎么样，这草好玩吗？",
            ["ContentFR"] = "Je t’ai cherchée partout... Je ne pensais pas te trouver ici, toute seule, à jouer avec un brin d’herbe. Alors ? C’est amusant ?",
            ["DialogueId"] = 12061401,
            ["GUID"] = "1E31C79A",
            ["NextDialogue"] = 12061402,
            ["RelatedWikiId"] = {
                [1] = 203009,
                [2] = 203004,
                [3] = 201029,
                [4] = 103001,
                [5] = 203013,
                [6] = 203014,
                [7] = 408018,
                },
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120614/1E31C79A",
            },
        [12061402] = {
            ["Content"] = "……不好玩。草的汁液全沾到手指缝里了，鼻腔里也都是土腥味，玩一会儿就腻了。",
            ["ContentFR"] = "... Pas vraiment. La sève me colle aux doigts et cette odeur de terre me remplit le nez. On s’en lasse vite.",
            ["DialogueId"] = 12061402,
            ["GUID"] = "1E31C7C4",
            ["NextDialogue"] = 12061403,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120614/1E31C7C4",
            },
        [12061403] = {
            ["Content"] = "不好玩你还在这里待这么久？",
            ["ContentFR"] = "Alors pourquoi rester ici aussi longtemps ?",
            ["DialogueId"] = 12061403,
            ["GUID"] = "1E31C7EE",
            ["NextDialogue"] = 12061404,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120614/1E31C7EE",
            },
        [12061404] = {
            ["Content"] = "呜，因为我没想好该怎么回去和那家伙道歉嘛……我刚一跑出来就已经后悔了。",
            ["ContentFR"] = "Eh bien... parce que je ne sais pas comment retourner lui présenter mes excuses... Dès que je suis sortie, j’ai regretté.",
            ["DialogueId"] = 12061404,
            ["GUID"] = "1E31C818",
            ["NextDialogue"] = 12061405,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120614/1E31C818",
            },
        [12061405] = {
            ["Content"] = "我也不知道自己刚刚为什么会那么冲动。{nickname}，感觉我一辈子的丢脸时刻都要被你看光了……",
            ["ContentFR"] = "Je ne comprends même pas pourquoi j’ai réagi si violemment. {nickname}... j’ai l’impression que tu vas assister à tous les moments les plus embarrassants de ma vie.",
            ["DialogueId"] = 12061405,
            ["GUID"] = "1E31C842",
            ["NextDialogue"] = 12061406,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120614/1E31C842",
            },
        [12061406] = {
            ["Content"] = "不过你愿意来找我，我很高兴。",
            ["ContentFR"] = "Mais... je suis contente que tu sois venu me chercher.",
            ["DialogueId"] = 12061406,
            ["GUID"] = "1E31C86C",
            ["NextDialogue"] = 12061407,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120614/1E31C86C",
            },
        [12061407] = {
            ["Content"] = "我知道原因。因为你很在乎他们一直提到的那个人，你的姑姑。她的名字是苏暮鹧，对吧？",
            ["ContentFR"] = "Je comprends. C’est parce qu’ils ont parlé de quelqu’un qui compte énormément pour toi... ta tante. Elle s’appelait Su Muzhe, n’est-ce pas ?",
            ["DialogueId"] = 12061407,
            ["GUID"] = "1E31C896",
            ["NextDialogue"] = 12061408,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120614/1E31C896",
            },
        [12061408] = {
            ["Content"] = "如果不介意的话，你可以对我多讲讲她的事情吗？我想这样或许能让你好受一些。",
            ["ContentFR"] = "Si cela ne te dérange pas... tu pourrais m’en parler ? Peut-être que ça te fera du bien.",
            ["DialogueId"] = 12061408,
            ["GUID"] = "1E31C8C0",
            ["NextDialogue"] = 12061409,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120614/1E31C8C0",
            },
        [12061409] = {
            ["Content"] = "……谢谢你，{nickname}。你没猜错，姑姑是我在这个世界上最重要的人。",
            ["ContentFR"] = "... Merci, {nickname}. Tu as raison. Ma tante était la personne la plus importante au monde pour moi.",
            ["DialogueId"] = 12061409,
            ["GUID"] = "1E31C8EA",
            ["NextDialogue"] = 12061410,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120614/1E31C8EA",
            },
        [12061410] = {
            ["Content"] = "让我想想，该从哪里说起呢……或许就从“天工苏氏”说起吧。",
            ["ContentFR"] = "Par où commencer... Peut-être par les Artisans Célestes du clan Su.",
            ["DialogueId"] = 12061410,
            ["GUID"] = "1E31C914",
            ["NextDialogue"] = 12061411,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120614/1E31C914",
            },
        [12061411] = {
            ["Content"] = "“天工苏氏”……这是你家族的名号吗？",
            ["ContentFR"] = "Les Artisans Célestes du clan Su... C’est le nom de ta lignée ?",
            ["DialogueId"] = 12061411,
            ["GUID"] = "1E31C93E",
            ["NextDialogue"] = 12061412,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120614/1E31C93E",
            },
        [12061412] = {
            ["Content"] = "嗯，天工苏氏曾经是机枢派最响亮的名号哦！……不过，都是黍离之战之前的事了。",
            ["ContentFR"] = "Oui. Autrefois, les Artisans Célestes du clan Su étaient le nom le plus prestigieux de la Secte Jishu... Mais tout cela remonte à avant la Bataille de Shuli.",
            ["DialogueId"] = 12061412,
            ["GUID"] = "1E31C968",
            ["NextDialogue"] = 12061413,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120614/1E31C968",
            },
        [12061413] = {
            ["Content"] = "我还记得，七岁那年，我照着父母藏在箱底的图纸造出一台机傀，举在头顶上一路跑去交给母亲，向她讨要奖赏。",
            ["ContentFR"] = "Je me souviens... j’avais sept ans. J’ai trouvé des plans que mes parents avaient cachés au fond d’un coffre. J’ai construit une méchapoupée en suivant ces plans, puis je suis allée voir ma mère en la brandissant au-dessus de ma tête, impatiente d’obtenir des compliments.",
            ["DialogueId"] = 12061413,
            ["GUID"] = "1E31C992",
            ["NextDialogue"] = 12061414,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120614/1E31C992",
            },
        [12061414] = {
            ["Content"] = "她接过那台机傀，反复把玩。我以为她会夸我，没想到她突然哭了。",
            ["ContentFR"] = "Elle a pris la méchapoupée et l’a examinée longuement. Je pensais qu’elle allait me féliciter... mais elle s’est mise à pleurer.",
            ["DialogueId"] = 12061414,
            ["GUID"] = "1E31C9BC",
            ["NextDialogue"] = 12061415,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120614/1E31C9BC",
            },
        [12061415] = {
            ["Content"] = "“我的女儿，她这般天赐的巧手，为何偏偏生在这个世道？”母亲一直这样自言自语——那时我不知她为什么哭，只能不停地帮她擦眼泪，答应她再也不摆弄机傀了。",
            ["ContentFR"] = "« Ma fille... avec des mains aussi habiles... pourquoi doit-elle être née en une époque pareille ? » Elle répétait cela sans cesse. Je ne comprenais pas pourquoi elle pleurait. Je me contentais d’essuyer ses larmes et je lui ai promis de ne plus jamais toucher aux méchapoupées.",
            ["DialogueId"] = 12061415,
            ["GUID"] = "1E31C9E6",
            ["NextDialogue"] = 12061416,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120614/1E31C9E6",
            },
        [12061416] = {
            ["Content"] = "后来我才知道，自黍离之战、机枢派衰落后，很多珍贵的技术被悬衡派视为不可触碰的禁忌，加以封存。",
            ["ContentFR"] = "Plus tard, j’ai compris. Après la Bataille de Shuli et le déclin de la Secte Jishu, de nombreuses techniques furent déclarées interdites par la Secte Xuanheng et scellées.",
            ["DialogueId"] = 12061416,
            ["GUID"] = "1E31CA10",
            ["NextDialogue"] = 12061417,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120614/1E31CA10",
            },
        [12061417] = {
            ["Content"] = "天工苏氏虽得以保全自身，但也只得将引以为傲的机傀术藏进箱底，如履薄冰地度日。",
            ["ContentFR"] = "Notre clan a survécu... mais nous avons dû cacher notre art des méchapoupées et vivre dans la plus grande prudence.",
            ["DialogueId"] = 12061417,
            ["GUID"] = "1E31CA3A",
            ["NextDialogue"] = 12061418,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120614/1E31CA3A",
            },
        [12061418] = {
            ["Content"] = "我曾以为自己也会像父母那样再不逾矩，平凡安稳地度过一生。直到有一天，姑姑神神秘秘地问我——“你其实很想学机傀术，是不是？那我来教你啊。”",
            ["ContentFR"] = "Je pensais que je finirais comme mes parents : vivre discrètement, sans jamais franchir les limites. Jusqu’au jour où ma tante m’a demandé en secret : « Tu veux vraiment apprendre l’art des méchapoupées, n’est-ce pas ? Alors laisse-moi t’enseigner. »",
            ["DialogueId"] = 12061418,
            ["GUID"] = "1E31CA64",
            ["NextDialogue"] = 12061419,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120614/1E31CA64",
            },
        [12061419] = {
            ["Content"] = "那时我就知道，我逃不掉了。",
            ["ContentFR"] = "À cet instant, j’ai compris que je ne pourrais pas fuir.",
            ["DialogueId"] = 12061419,
            ["GUID"] = "1E31CA8E",
            ["NextDialogue"] = 12061420,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120614/1E31CA8E",
            },
        [12061420] = {
            ["Content"] = "姑姑在工造局当值。只要有空，她就会来后院陪着我，教我机傀制造的技巧，还给我讲各种各样有意思的故事。",
            ["ContentFR"] = "Ma tante travaillait alors au Bureau des Arts Mécaniques. Dès qu’elle avait un moment libre, elle venait dans la cour arrière pour m’enseigner la fabrication des méchapoupées et me raconter toutes sortes d’histoires fascinantes.",
            ["DialogueId"] = 12061420,
            ["GUID"] = "1E31CAB8",
            ["NextDialogue"] = 12061421,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120614/1E31CAB8",
            },
        [12061421] = {
            ["Content"] = "你知道我为什么叫这个名字吗？",
            ["ContentFR"] = "Tu sais pourquoi je m’appelle Su Yi ?",
            ["DialogueId"] = 12061421,
            ["GUID"] = "1E31CAE2",
            ["NextDialogue"] = 12061422,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120614/1E31CAE2",
            },
        [12061422] = {
            ["Content"] = "姑姑那时候，总是和我描述一种从不归巢的燕子，叫做乙鸟。 它们翔于长空中，自由自在不受束缚。我可向往了。",
            ["ContentFR"] = "Ma tante me parlait souvent d’un oiseau appelé l’oiseau Yi, une hirondelle qui ne retourne jamais à son nid. Elle vole librement dans le ciel, sans entraves. Je l’enviais tellement.",
            ["DialogueId"] = 12061422,
            ["GUID"] = "1E31CB0C",
            ["NextDialogue"] = 12061423,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120614/1E31CB0C",
            },
        [12061423] = {
            ["Content"] = "向往“自由”的姑姑，逐渐被山外山的理想所吸引。为了创造一个机枢术不再处处受限的未来，她与飘零人开始进行书信往来。",
            ["ContentFR"] = "Ma tante, qui rêvait tant de liberté, s’est peu à peu laissée séduire par l’idéal des Pics Extérieurs. Pour créer un futur où l’art des méchapoupées ne serait plus entravé, elle a commencé à correspondre avec les Vagabonds.",
            ["DialogueId"] = 12061423,
            ["GUID"] = "1E31CB36",
            ["NextDialogue"] = 12061424,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120614/1E31CB36",
            },
        [12061424] = {
            ["Content"] = "后来有一天，姑姑与飘零人的联系暴露，于是她离开皓京加入山外山，像乙鸟一样去追寻那份自由了，只剩下留在原地的我。",
            ["ContentFR"] = "Un jour, ces échanges ont été découverts. Elle a quitté Haojing pour rejoindre les Pics Extérieurs. Comme l’oiseau Yi, elle est partie à la recherche de sa liberté... et moi, je suis restée derrière.",
            ["DialogueId"] = 12061424,
            ["GUID"] = "1E31CB60",
            ["NextDialogue"] = 12061425,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120614/1E31CB60",
            },
        [12061425] = {
            ["Content"] = "再后来，当我决心跟随姑姑的脚步离家加入山外山时，我将自己的名字改成了苏乙。可惜那时候姑姑已经再也看不到了……",
            ["ContentFR"] = "Plus tard, quand j’ai décidé de suivre ses traces et de rejoindre les Pics Extérieurs, j’ai changé mon nom pour devenir Su Yi. Mais à ce moment-là... ma tante n’était déjà plus là pour le voir.",
            ["DialogueId"] = 12061425,
            ["GUID"] = "1E31CB8A",
            ["NextOptions"] = {
                [1] = 12061426,
                [2] = 12061427,
                },
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120614/1E31CB8A",
            },
        [12061426] = {
            ["Content"] = "节哀……",
            ["ContentFR"] = "<I>Mes condoléances...</>",
            ["DialogueId"] = 12061426,
            ["GUID"] = "1E31CBB4",
            ["NextDialogue"] = 12061428,
            },
        [12061427] = {
            ["Content"] = "她发生了什么？",
            ["ContentFR"] = "<I>Que lui est-il arrivé ?</>",
            ["DialogueId"] = 12061427,
            ["GUID"] = "1E31CBDE",
            ["NextDialogue"] = 12061428,
            },
        [12061428] = {
            ["Content"] = "姑姑在工造局时期设计了一种用于疏通水路的灭蒙巨鸟。她走后，灭蒙巨鸟无人修缮，日久生患。",
            ["ContentFR"] = "Lorsque ma tante travaillait encore au Bureau des Arts Mécaniques, elle avait conçu un Grand Oiseau Miemeng destiné à dégager les voies d’eau. Après son départ, plus personne ne s’est occupé de l’entretenir, et avec le temps des dysfonctionnements sont apparus.",
            ["DialogueId"] = 12061428,
            ["GUID"] = "1E31CC08",
            ["NextDialogue"] = 12061429,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120614/1E31CC08",
            },
        [12061429] = {
            ["Content"] = "为了大家的安全，姑姑冒险离开山外山，赶回皓京城郊，却被应天尉当场诛杀。但这在某些人口中，竟被歪曲成了她试图操纵灭蒙、造成破坏。",
            ["ContentFR"] = "Pour la sécurité de tous, ma tante a pris le risque de quitter les Pics Extérieurs et de revenir en toute hâte aux abords de Haojing. Mais elle a été exécutée sur place par un Magistrat de Yingtian. Pourtant, certains ont déformé l’histoire et prétendent qu’elle cherchait à prendre le contrôle du Miemeng pour provoquer des destructions.",
            ["DialogueId"] = 12061429,
            ["GUID"] = "1E31CC32",
            ["NextDialogue"] = 12061430,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120614/1E31CC32",
            },
        [12061430] = {
            ["Content"] = "所以你没法接受别人诋毁她的所作所为，是吗？",
            ["ContentFR"] = "C’est pour cela que tu ne peux pas supporter que l’on salisse ce qu’elle a fait... n’est-ce pas ?",
            ["DialogueId"] = 12061430,
            ["GUID"] = "1E31CC5C",
            ["NextDialogue"] = 12061431,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120614/1E31CC5C",
            },
        [12061431] = {
            ["Content"] = "嗯……抱歉，之前一直没有告诉你我参加这次比赛的初衷，以及自己的私心，我应该更早对你全盘托出的。",
            ["ContentFR"] = "Oui... Désolée. Je ne t’avais jamais expliqué pourquoi j’ai décidé de participer à ce tournoi, ni les raisons personnelles qui m’y poussent. J’aurais dû tout te dire plus tôt.",
            ["DialogueId"] = 12061431,
            ["GUID"] = "1E31CC86",
            ["NextDialogue"] = 12061432,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120614/1E31CC86",
            },
        [12061432] = {
            ["Content"] = "我想在群英试中拨得头筹，想站在皓京的制高点，在万众瞩目之下，在龙神面前为我的姑姑苏暮鹧正名。告诉世人——她和她的理念没有错。",
            ["ContentFR"] = "Je veux remporter le Tournoi de l’Encens. Je veux me tenir au sommet de Haojing, sous le regard de tous, et réhabiliter le nom de ma tante Su Muzhe devant le Seigneur Dragon d’Argent. Je veux que le monde sache qu’elle n’avait pas tort — ni elle, ni ses idéaux.",
            ["DialogueId"] = 12061432,
            ["GUID"] = "1E31CCB0",
            ["NextDialogue"] = 12061433,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120614/1E31CCB0",
            },
        [12061433] = {
            ["Content"] = "当大风九章开始推动辩法改制后，我以为这个梦想已经触手可及了……但想法总是比现实美好。",
            ["ContentFR"] = "Quand les Neuf Chapitres de Dafeng ont commencé à promouvoir la réforme des lois par débat, j’ai cru que ce rêve était enfin à portée de main... Mais la réalité est toujours plus compliquée que ce que l’on imagine.",
            ["DialogueId"] = 12061433,
            ["GUID"] = "1E31CCDA",
            ["NextDialogue"] = 12061434,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120614/1E31CCDA",
            },
        [12061434] = {
            ["Content"] = "人们对飘零人的回归不知所措，皓京还爆发了抗议。面对这种天翻地覆的改变，他们会迷茫也是在所难免的吧。",
            ["ContentFR"] = "Les gens ne savent pas comment réagir au retour des Vagabonds. Il y a même eu des manifestations à Haojing. Face à des changements aussi brutaux, il est normal qu’ils se sentent perdus.",
            ["DialogueId"] = 12061434,
            ["GUID"] = "1E31CD04",
            ["NextDialogue"] = 12061435,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120614/1E31CD04",
            },
        [12061435] = {
            ["Content"] = "如果对面是狴犴，飘零人可以去争，可以去反抗。但当面对的是一种看不见摸不着的“大众偏见”的时候，那些激进的手段反而适得其反。",
            ["ContentFR"] = "Si l’ennemi était un Bi’an, les Vagabonds pourraient lutter, se battre. Mais face à quelque chose d’invisible et d’insaisissable comme les préjugés des gens... des méthodes trop radicales ne font qu’empirer les choses.",
            ["DialogueId"] = 12061435,
            ["GUID"] = "1E31CD2E",
            ["NextDialogue"] = 12061436,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120614/1E31CD2E",
            },
        [12061436] = {
            ["Content"] = "唐叔劝我先等等，但我等不及了。所以我偷偷跑出来，参加了这次群英试。",
            ["ContentFR"] = "Oncle Tang m’a conseillé d’attendre encore un peu. Mais je n’ai pas pu. Alors je me suis éclipsée en secret pour participer à ce Tournoi de l’Encens.",
            ["DialogueId"] = 12061436,
            ["GUID"] = "1E31CD58",
            ["NextDialogue"] = 12061437,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120614/1E31CD58",
            },
        [12061437] = {
            ["Content"] = "{nickname}，你说，姑姑如果看到我变得这么任性了，会很失望吗？",
            ["ContentFR"] = "{nickname}... Si ma tante voyait à quel point je suis devenue obstinée... crois-tu qu’elle serait déçue ?",
            ["DialogueId"] = 12061437,
            ["GUID"] = "1E31CD82",
            ["NextOptions"] = {
                [1] = 12061438,
                [2] = 12061439,
                },
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120614/1E31CD82",
            },
        [12061438] = {
            ["Content"] = "你不需要一个人扛起所有。",
            ["ContentFR"] = "<I>Tu n’as pas à porter tout cela toute seule.</>",
            ["DialogueId"] = 12061438,
            ["GUID"] = "1E31CDAC",
            ["NextDialogue"] = 12061440,
            },
        [12061439] = {
            ["Content"] = "就算任性也没有关系。",
            ["ContentFR"] = "<I>Même si c’est un peu capricieux, ce n’est pas grave.</>",
            ["DialogueId"] = 12061439,
            ["GUID"] = "1E31CDD6",
            ["NextDialogue"] = 12061440,
            },
        [12061440] = {
            ["Content"] = "苏乙，你有时候考虑太多了，其实你可以更加任性一点。",
            ["ContentFR"] = "Su Yi, tu réfléchis parfois trop. Tu pourrais te permettre d’être un peu plus obstinée.",
            ["DialogueId"] = 12061440,
            ["GUID"] = "1E31CE00",
            ["NextDialogue"] = 12061441,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120614/1E31CE00",
            },
        [12061441] = {
            ["Content"] = "能找到自己的目标并全力以赴去达成它，我觉得这是一件非常非常了不起的事情。",
            ["ContentFR"] = "Avoir un objectif et se donner corps et âme pour l’atteindre... je trouve que c’est quelque chose de vraiment admirable.",
            ["DialogueId"] = 12061441,
            ["GUID"] = "1E31CE2A",
            ["NextDialogue"] = 12061442,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120614/1E31CE2A",
            },
        [12061442] = {
            ["Content"] = "姑姑如果能看到现在的你，也一定会为你感到自豪的。",
            ["ContentFR"] = "Si ta tante pouvait te voir aujourd’hui, elle serait certainement fière de toi.",
            ["DialogueId"] = 12061442,
            ["GUID"] = "1E31CE54",
            ["NextDialogue"] = 12061443,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120614/1E31CE54",
            },
        [12061443] = {
            ["Content"] = "呼……{nickname}，和你聊完后，我感觉神清气爽了好多。",
            ["ContentFR"] = "<I>Pfiou...</> {nickname}, après t’avoir parlé, je me sens beaucoup plus légère.",
            ["DialogueId"] = 12061443,
            ["GUID"] = "1E31CE7E",
            ["NextDialogue"] = 12061444,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120614/1E31CE7E",
            },
        [12061444] = {
            ["Content"] = "我们回去吧，还得想办法和那家伙好好道歉呢。",
            ["ContentFR"] = "Allons-y. Il faut encore que je trouve comment présenter mes excuses.",
            ["DialogueId"] = 12061444,
            ["GUID"] = "1E31CEA8",
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120614/1E31CEA8",
            },
        [12061445] = {
            ["Content"] = "你、你们不要过来！",
            ["ContentFR"] = "V-Vous... ne vous approchez pas !",
            ["DialogueId"] = 12061445,
            ["GUID"] = "1E31CED2",
            ["NextDialogue"] = 12061446,
            ["SpeakNpcId"] = 250017,
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["VoiceName"] = "voice/$Locale$/story/1206/120614/1E31CED2",
            },
        [12061446] = {
            ["Content"] = "好像有孩子的求救声？！{nickname}，我们赶紧过去看看！",
            ["ContentFR"] = "On dirait un enfant qui appelle à l’aide ! {nickname}, dépêchons-nous d’aller voir !",
            ["DialogueId"] = 12061446,
            ["GUID"] = "1E31CEFC",
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120614/1E31CEFC",
            },
        [12061501] = {
            ["Content"] = "小朋友，你还好吗，有没有哪里受伤？",
            ["ContentFR"] = "Petit, tu vas bien ? Tu n’es pas blessé ?",
            ["DialogueId"] = 12061501,
            ["GUID"] = "1E31D802",
            ["NextDialogue"] = 12061502,
            ["RelatedWikiId"] = {
                [1] = 203009,
                [2] = 203004,
                [3] = 201029,
                [4] = 103001,
                [5] = 203013,
                [6] = 203014,
                [7] = 408018,
                },
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120615/1E31D802",
            },
        [12061502] = {
            ["Content"] = "小安没事，谢谢大姐姐！",
            ["ContentFR"] = "Je vais bien ! Merci, mademoiselle !",
            ["DialogueId"] = 12061502,
            ["GUID"] = "1E31D82C",
            ["NextDialogue"] = 12061503,
            ["SpeakNpcId"] = 250017,
            ["VoiceName"] = "voice/$Locale$/story/1206/120615/1E31D82C",
            },
        [12061503] = {
            ["Content"] = "外面危险，小朋友还是不要乱跑啦。之前大乱的影响还没完全消失，等到玄色狴犴都被扫除后，小安才能出来走动哦。",
            ["ContentFR"] = "C’est dangereux dehors. Tu ne devrais pas te promener seul, d’accord ? Les troubles récents ne sont pas encore complètement terminés. Attends que les Bi’an obscurs aient été éliminés avant de ressortir jouer.",
            ["DialogueId"] = 12061503,
            ["GUID"] = "1E31D856",
            ["NextDialogue"] = 12061504,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120615/1E31D856",
            },
        [12061504] = {
            ["Content"] = "小安！小安，你在那里吗？！",
            ["ContentFR"] = "An ! An, tu es là ?!",
            ["DialogueId"] = 12061504,
            ["GUID"] = "1E31D880",
            ["NextDialogue"] = 12061505,
            ["SpeakNpcId"] = 250018,
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["VoiceName"] = "voice/$Locale$/story/1206/120615/1E31D880",
            },
        [12061505] = {
            ["Content"] = "你这孩子，明明腿有旧疾，怎么还非要跑出来……",
            ["ContentFR"] = "Toi alors... Ta jambe te fait déjà souffrir, pourquoi as-tu quand même couru dehors ?",
            ["DialogueId"] = 12061505,
            ["GUID"] = "1E31D8AA",
            ["NextDialogue"] = 12061506,
            ["SpeakNpcId"] = 250018,
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["VoiceName"] = "voice/$Locale$/story/1206/120615/1E31D8AA",
            },
        [12061506] = {
            ["Content"] = "对不起，小安错了……",
            ["ContentFR"] = "Désolé... C’est ma faute...",
            ["DialogueId"] = 12061506,
            ["GUID"] = "1E31D8D4",
            ["NextDialogue"] = 12061518,
            ["SpeakNpcId"] = 250017,
            ["VoiceName"] = "voice/$Locale$/story/1206/120615/1E31D8D4",
            },
        [12061507] = {
            ["Content"] = "是你们救了小安吗？在下潇湘，目前于天梁司当职，以后若有要事，我定当回报。",
            ["ContentFR"] = "Est-ce vous qui avez sauvé An ? Je me nomme Xiaoxiang. Je travaille actuellement au Bureau des Travaux. Si vous avez besoin de quoi que ce soit à l’avenir, je me ferai un devoir de vous rendre la pareille.",
            ["DialogueId"] = 12061507,
            ["GUID"] = "1E31D8FE",
            ["NextDialogue"] = 12061508,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120615/1E31D8FE",
            },
        [12061508] = {
            ["Content"] = "举手之劳啦，不用放在心上。倒是小安的腿怎么了？",
            ["ContentFR"] = "Ce n’était rien. Mais que lui est-il arrivé à la jambe ?",
            ["DialogueId"] = 12061508,
            ["GUID"] = "1E31D928",
            ["NextDialogue"] = 12061509,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120615/1E31D928",
            },
        [12061509] = {
            ["Content"] = "……小安小时候曾经被卷入一场事故。",
            ["ContentFR"] = "... Quand An était petit, il a été pris dans un accident.",
            ["DialogueId"] = 12061509,
            ["GUID"] = "1E31D952",
            ["NextDialogue"] = 12061510,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120615/1E31D952",
            },
        [12061510] = {
            ["Content"] = "那场事故不仅让他落下了腿疾，还令他失去了父母，只能由我代为抚养。所以我一直对这孩子放不下心来。",
            ["ContentFR"] = "Cet accident lui a laissé une blessure permanente à la jambe, et il a perdu ses parents. C’est moi qui l’ai élevé depuis lors. Voilà pourquoi je m’inquiète toujours pour lui.",
            ["DialogueId"] = 12061510,
            ["GUID"] = "1E31D97C",
            ["NextDialogue"] = 12061511,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120615/1E31D97C",
            },
        [12061511] = {
            ["Content"] = "阿姨别再想那些伤心事了！小安有阿姨养大，所以小安非常幸福！",
            ["ContentFR"] = "Tata Xiaoxiang, ne pense plus à ces choses tristes ! J’ai grandi avec toi, alors je suis très heureux !",
            ["DialogueId"] = 12061511,
            ["GUID"] = "1E31D9A6",
            ["NextDialogue"] = 12061512,
            ["SpeakNpcId"] = 250017,
            ["VoiceName"] = "voice/$Locale$/story/1206/120615/1E31D9A6",
            },
        [12061512] = {
            ["Content"] = "……你这孩子。",
            ["ContentFR"] = "... Quel enfant.",
            ["DialogueId"] = 12061512,
            ["GUID"] = "1E31D9D0",
            ["NextDialogue"] = 12061513,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120615/1E31D9D0",
            },
        [12061513] = {
            ["Content"] = "看来小安很喜欢你呢，我能感受到他的这些话是发自内心的。",
            ["ContentFR"] = "On voit bien qu’il vous aime beaucoup. On sent que ses paroles viennent vraiment du cœur.",
            ["DialogueId"] = 12061513,
            ["GUID"] = "1E31D9FA",
            ["NextDialogue"] = 12061514,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120615/1E31D9FA",
            },
        [12061514] = {
            ["Content"] = "多谢二位了。比赛快要开始，就不耽误你们时间了。我家就在那座屋舍，二位若有机会一定要去坐坐。",
            ["ContentFR"] = "Merci à vous deux. La prochaine manche va bientôt commencer, je ne vais pas vous retenir davantage. Notre maison est celle-là, là-bas. Si vous en avez l’occasion, venez donc nous rendre visite.",
            ["DialogueId"] = 12061514,
            ["GUID"] = "1E31DA24",
            ["NextDialogue"] = 12061515,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120615/1E31DA24",
            },
        [12061515] = {
            ["Content"] = "没事，你快带小安回去吧。",
            ["ContentFR"] = "Ce n’est rien. Ramenez An à la maison.",
            ["DialogueId"] = 12061515,
            ["GUID"] = "1E31DA4E",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120615/1E31DA4E",
            },
        [12061516] = {
            ["Content"] = "他们的相处方式，有点让我想起曾经的我和姑姑……",
            ["ContentFR"] = "Les voir tous les deux... ça me rappelle un peu la relation que j’avais autrefois avec ma tante...",
            ["DialogueId"] = 12061516,
            ["GUID"] = "1E31DA78",
            ["NextDialogue"] = 12061517,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120615/1E31DA78",
            },
        [12061517] = {
            ["Content"] = "小安的心愿，一定是能一直一直和他的阿姨待在一起吧。就像当初的我一样……",
            ["ContentFR"] = "Il veut sûrement juste pouvoir rester toujours auprès de sa tante... Comme moi autrefois...",
            ["DialogueId"] = 12061517,
            ["GUID"] = "1E31DAA2",
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120615/1E31DAA2",
            },
        [12061518] = {
            ["Content"] = "在赶来的女子的帮助下，小安略显吃力地站了起来。",
            ["DialogueId"] = 12061518,
            ["GUID"] = "1E31DAA3",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 12061507,
            ["VoiceName"] = "voice/$Locale$/story/1206/120615/1E31DAA3",
            },
        [12061601] = {
            ["Content"] = "小仆从，你回来了！咳咳，“那件事情”办的怎么样了？",
            ["ContentFR"] = "Petit larbin, te voilà revenu ! Hum... alors, comment s’est passée « cette affaire » ?",
            ["DialogueId"] = 12061601,
            ["GUID"] = "1E31E86A",
            ["NextDialogue"] = 12061602,
            ["RelatedWikiId"] = {
                [1] = 203009,
                [2] = 203004,
                [3] = 201029,
                [4] = 103001,
                [5] = 203013,
                [6] = 203014,
                [7] = 408018,
                },
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120616/1E31E86A",
            },
        [12061602] = {
            ["Content"] = "如果顺利，你就眨眨眼。要是遇到什么问题需要白出马，你就……嗯，不如高呼“魔王大人万岁”吧！",
            ["ContentFR"] = "Si tout s’est bien passé, cligne des yeux. Et si quelque chose s’est mal passé et que tu as besoin que j’intervienne... eh bien... tu n’auras qu’à crier : « Gloire au Roi Démon ! »",
            ["DialogueId"] = 12061602,
            ["GUID"] = "1E31E894",
            ["NextDialogue"] = 12061603,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120616/1E31E894",
            },
        [12061603] = {
            ["Content"] = "白……你说话怎么也这么拐弯抹角了。放心，苏乙的心情已经平复下来了，她是回来找煜明道歉的。",
            ["ContentFR"] = "Snow... depuis quand parles-tu par énigmes ? Ne t’inquiète pas. Su Yi s’est calmée. Elle revient pour présenter ses excuses à Yuming.",
            ["DialogueId"] = 12061603,
            ["GUID"] = "1E31E8BE",
            ["NextDialogue"] = 12061604,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120616/1E31E8BE",
            },
        [12061604] = {
            ["Content"] = "呼……那就好那就好！",
            ["ContentFR"] = "Ouf... tant mieux, tant mieux !",
            ["DialogueId"] = 12061604,
            ["GUID"] = "1E31E8E8",
            ["NextDialogue"] = 12061605,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120616/1E31E8E8",
            },
        [12061605] = {
            ["Content"] = "苏乙，你是不是有话要和煜明说？去吧，他就在那里。",
            ["ContentFR"] = "Su Yi, tu avais quelque chose à dire à Yuming, non ? Vas-y. Il est juste là.",
            ["DialogueId"] = 12061605,
            ["GUID"] = "1E31E912",
            ["NextDialogue"] = 12061624,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120616/1E31E912",
            },
        [12061606] = {
            ["Content"] = "抱歉，煜明。你明明在紧急时刻帮了我，我却没有对你表达感谢，甚至反过来说了些很过分的话……真的非常非常对不起！",
            ["ContentFR"] = "Je suis désolée, Yuming. Tu m’as aidée dans un moment critique, et je ne t’ai même pas remercié. Pire encore, je t’ai dit des choses vraiment blessantes... Je te présente mes excuses les plus sincères.",
            ["DialogueId"] = 12061606,
            ["GUID"] = "1E31E93C",
            ["NextDialogue"] = 12061607,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120616/1E31E93C",
            },
        [12061607] = {
            ["Content"] = "无妨，只是些许龃龉，我并未介怀。",
            ["ContentFR"] = "Ce n’est rien. Ce n’était qu’une petite altercation. Je ne t’en tiens pas rigueur.",
            ["DialogueId"] = 12061607,
            ["GUID"] = "1E31E966",
            ["NextDialogue"] = 12061608,
            ["SpeakNpcId"] = 250005,
            ["VoiceName"] = "voice/$Locale$/story/1206/120616/1E31E966",
            },
        [12061608] = {
            ["Content"] = "但是，我还有一件很重要的事情要对你说……就算你不认可，我也必须告诉你。",
            ["ContentFR"] = "Mais il y a encore une chose importante que je dois te dire... Même si tu n’es pas d’accord, je dois te l’expliquer.",
            ["DialogueId"] = 12061608,
            ["GUID"] = "1E31E990",
            ["NextDialogue"] = 12061609,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120616/1E31E990",
            },
        [12061609] = {
            ["Content"] = "我是绝对不会放弃为姑姑正名的！就算遇到多少阻挠，经历多少困难，我也想向世人证明她的理念。",
            ["ContentFR"] = "Je ne renoncerai jamais à réhabiliter le nom de ma tante ! Peu importe les obstacles ou les difficultés, je veux prouver au monde que ses idéaux étaient justes.",
            ["DialogueId"] = 12061609,
            ["GUID"] = "1E31E9BA",
            ["NextDialogue"] = 12061610,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120616/1E31E9BA",
            },
        [12061610] = {
            ["Content"] = "只有这件事情，我绝对绝对不能让步。所以只能再说一次对不起了！",
            ["ContentFR"] = "Sur ce point, je ne céderai jamais. Alors je dois encore te dire pardon.",
            ["DialogueId"] = 12061610,
            ["GUID"] = "1E31E9E4",
            ["NextDialogue"] = 12061611,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120616/1E31E9E4",
            },
        [12061611] = {
            ["Content"] = "苏乙，先前已经说了，这件事你可能有所误解。我并未否定你为苏暮鹧正名的目标。",
            ["ContentFR"] = "Su Yi. Je te l’ai déjà dit : tu te méprends peut-être sur mes intentions. Je n’ai jamais rejeté ton objectif de réhabiliter le nom de Su Muzhe.",
            ["DialogueId"] = 12061611,
            ["GUID"] = "1E31EA0E",
            ["NextDialogue"] = 12061612,
            ["SpeakNpcId"] = 250005,
            ["VoiceName"] = "voice/$Locale$/story/1206/120616/1E31EA0E",
            },
        [12061612] = {
            ["Content"] = "更何况，我并没有资格阻挠你。放弃的代价，没有人比我更加清楚。",
            ["ContentFR"] = "Et d’ailleurs, je n’ai pas le droit de t’en empêcher. Personne ne connaît mieux que moi le prix qu’il faut payer lorsqu’on renonce à quelque chose.",
            ["DialogueId"] = 12061612,
            ["GUID"] = "1E31EA38",
            ["NextDialogue"] = 12061613,
            ["SpeakNpcId"] = 250005,
            ["VoiceName"] = "voice/$Locale$/story/1206/120616/1E31EA38",
            },
        [12061613] = {
            ["Content"] = "……谢谢你能理解我。",
            ["ContentFR"] = "... Merci de me comprendre.",
            ["DialogueId"] = 12061613,
            ["GUID"] = "1E31EA62",
            ["NextDialogue"] = 12061614,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120616/1E31EA62",
            },
        [12061614] = {
            ["Content"] = "既然你已认清此心所向，煜明定将尽己所能，竭力助你拿下赛事冠军。",
            ["ContentFR"] = "Puisque ton cœur a trouvé sa voie, je ferai tout mon possible pour t’aider à remporter ce tournoi.",
            ["DialogueId"] = 12061614,
            ["GUID"] = "1E31EA8C",
            ["NextDialogue"] = 12061615,
            ["SpeakNpcId"] = 250005,
            ["VoiceName"] = "voice/$Locale$/story/1206/120616/1E31EA8C",
            },
        [12061615] = {
            ["Content"] = "还有我。",
            ["ContentFR"] = "Moi aussi.",
            ["DialogueId"] = 12061615,
            ["GUID"] = "1E31EAB6",
            ["NextDialogue"] = 12061616,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120616/1E31EAB6",
            },
        [12061616] = {
            ["Content"] = "到了夺冠的时候，我会站在你身边，让你的姑姑看到小苏现在已经有了这么多朋友。这样她在九泉之下也能安心了。",
            ["ContentFR"] = "Quand tu gagneras, je serai à tes côtés. Ta tante verra que la petite Su n’est plus seule maintenant... Elle a des amis.",
            ["DialogueId"] = 12061616,
            ["GUID"] = "1E31EAE0",
            ["NextDialogue"] = 12061617,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120616/1E31EAE0",
            },
        [12061617] = {
            ["Content"] = "这种时候自然也少不了魔王大人的身影！包在我和小仆从身上吧！",
            ["ContentFR"] = "Et dans un moment pareil, comment le Roi Démon pourrait-il manquer à l’appel ! Laisse ça à moi et à mon petit larbin !",
            ["DialogueId"] = 12061617,
            ["GUID"] = "1E31EB0A",
            ["NextDialogue"] = 12061618,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120616/1E31EB0A",
            },
        [12061618] = {
            ["Content"] = "大家……有你们真好！",
            ["ContentFR"] = "Tout le monde... Je suis vraiment heureuse de vous avoir.",
            ["DialogueId"] = 12061618,
            ["GUID"] = "1E31EB34",
            ["NextDialogue"] = 12061619,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120616/1E31EB34",
            },
        [12061619] = {
            ["Content"] = "这种时候再说谢谢好像有点见外了，我们还是赶紧进入赛场吧！",
            ["ContentFR"] = "Si je continue à vous remercier comme ça, on dirait que nous venons à peine de nous rencontrer. Allons plutôt rejoindre l’arène.",
            ["DialogueId"] = 12061619,
            ["GUID"] = "1E31EB5E",
            ["NextDialogue"] = 12061625,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120616/1E31EB5E",
            },
        [12061620] = {
            ["Content"] = "“姑姑”……",
            ["ContentFR"] = "« Tante »...",
            ["DialogueId"] = 12061620,
            ["GUID"] = "1E31EB88",
            ["NextDialogue"] = 12061621,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120616/1E31EB88",
            },
        [12061621] = {
            ["Content"] = "苏暮鹧……你曾经天天挂在嘴边的侄女，现在也已经长这么大了啊。",
            ["ContentFR"] = "Su Muzhe... La nièce dont tu parlais sans cesse... elle est devenue grande.",
            ["DialogueId"] = 12061621,
            ["GUID"] = "1E31EBB2",
            ["NextDialogue"] = 12061622,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120616/1E31EBB2",
            },
        [12061622] = {
            ["Content"] = "和当年的你一样聪明、骄傲，以及……恬不知耻。",
            ["ContentFR"] = "Aussi intelligente que toi... aussi fière... et... tout aussi effrontée.",
            ["DialogueId"] = 12061622,
            ["GUID"] = "1E31EBDC",
            ["NextDialogue"] = 12061623,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120616/1E31EBDC",
            },
        [12061623] = {
            ["Content"] = "在这种时候认出她，这是命运对你我的安排吗……",
            ["ContentFR"] = "Et voilà que je la reconnais précisément en un moment pareil... Est-ce donc le destin que le ciel avait prévu pour nous ?",
            ["DialogueId"] = 12061623,
            ["GUID"] = "1E31EC06",
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120616/1E31EC06",
            },
        [12061624] = {
            ["DialogueId"] = 12061624,
            ["GUID"] = "1E31E913",
            ["NextDialogue"] = 12061606,
            },
        [12061625] = {
            ["DialogueId"] = 12061625,
            ["GUID"] = "1E31EB5F",
            ["NextDialogue"] = 12061620,
            },
        [12061701] = {
            ["Content"] = "呼……今天的赛事告一段落了。干得不错！如果明天能继续保持这个节奏，夺冠绝对是板上钉钉的事情！",
            ["ContentFR"] = "<I>Pfiou...</> Voilà qui conclut les épreuves d’aujourd’hui. Beau travail ! Si nous maintenons ce rythme demain, la victoire sera pratiquement assurée !",
            ["DialogueId"] = 12061701,
            ["GUID"] = "1E31F8D2",
            ["NextDialogue"] = 12061702,
            ["RelatedWikiId"] = {
                [1] = 203009,
                [2] = 203004,
                [3] = 201029,
                [4] = 103001,
                [5] = 203013,
                [6] = 203014,
                [7] = 408018,
                },
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120617/1E31F8D2",
            },
        [12061702] = {
            ["Content"] = "不负所望。",
            ["ContentFR"] = "Je ferai de mon mieux.",
            ["DialogueId"] = 12061702,
            ["GUID"] = "1E31F8FC",
            ["NextDialogue"] = 12061703,
            ["SpeakNpcId"] = 250005,
            ["VoiceName"] = "voice/$Locale$/story/1206/120617/1E31F8FC",
            },
        [12061703] = {
            ["Content"] = "是不是该开始想获胜致辞该怎么说了？你好，我是苏乙，今天很荣幸能站在这里……",
            ["ContentFR"] = "On devrait peut-être commencer à réfléchir à ton discours de victoire. « Bonjour, je m’appelle Su Yi, c’est un honneur pour moi de me tenir ici aujourd’hui... »",
            ["DialogueId"] = 12061703,
            ["GUID"] = "1E31F926",
            ["NextDialogue"] = 12061744,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120617/1E31F926",
            },
        [12061704] = {
            ["Content"] = "小仆从小仆从，你们终于出来了！那个，赛场氛围好像有点不太对劲……",
            ["ContentFR"] = "Petit larbin ! Vous voilà enfin ! Euh... l’ambiance dans l’arène est un peu étrange...",
            ["DialogueId"] = 12061704,
            ["GUID"] = "1E31F950",
            ["NextDialogue"] = 12061705,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120617/1E31F950",
            },
        [12061705] = {
            ["Content"] = "发生什么了？",
            ["ContentFR"] = "Que se passe-t-il ?",
            ["DialogueId"] = 12061705,
            ["GUID"] = "1E31F97A",
            ["NextDialogue"] = 12061745,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120617/1E31F97A",
            },
        [12061706] = {
            ["Content"] = "喂喂，听说有飘零人混入了比赛，是真的吗……？",
            ["ContentFR"] = "Hé, vous avez entendu ? On dit qu’un Vagabond s’est infiltré dans la compétition...",
            ["DialogueId"] = 12061706,
            ["GUID"] = "1E31F9A4",
            ["NextDialogue"] = 12061707,
            ["SpeakNpcName"] = "UI_Npc_Name_Siyu",
            ["VoiceName"] = "voice/$Locale$/story/1206/120617/1E31F9A4",
            },
        [12061707] = {
            ["Content"] = "飘零人？那些传说中青面獠牙，手持大棒的恶棍？他们该不会是专门趁这个风云变幻的时机，来搞什么破坏的吧？",
            ["ContentFR"] = "Un Vagabond ? Ceux des histoires, avec la peau verdâtre et des crocs, qui brandissent d’énormes massues ? Avec tous les changements récents à Huaxu... tu crois qu’ils sont venus semer le trouble ?",
            ["DialogueId"] = 12061707,
            ["GUID"] = "1E31F9CE",
            ["NextDialogue"] = 12061708,
            ["SpeakNpcName"] = "UI_Npc_Name_Siyu",
            ["VoiceName"] = "voice/$Locale$/story/1206/120617/1E31F9CE",
            },
        [12061708] = {
            ["Content"] = "原来飘零人这么可怕吗，我还只在小说话本中看到过呢……",
            ["ContentFR"] = "Les Vagabonds sont vraiment aussi effrayants ? Je n’en ai vu que dans des romans...",
            ["DialogueId"] = 12061708,
            ["GUID"] = "1E31F9F8",
            ["NextDialogue"] = 12061709,
            ["SpeakNpcName"] = "UI_Npc_Name_Siyu",
            ["VoiceName"] = "voice/$Locale$/story/1206/120617/1E31F9F8",
            },
        [12061709] = {
            ["Content"] = "我倒是也听说过飘零人行侠仗义的故事……不过创作归创作，在现实中果然还是不想遇到这些人。",
            ["ContentFR"] = "J’ai entendu dire que certains d’entre eux rendaient justice... mais bon, les histoires restent des histoires. Dans la vraie vie, je préférerais ne jamais en croiser.",
            ["DialogueId"] = 12061709,
            ["GUID"] = "1E31FA22",
            ["NextDialogue"] = 12061710,
            ["SpeakNpcName"] = "UI_Npc_Name_Siyu",
            ["VoiceName"] = "voice/$Locale$/story/1206/120617/1E31FA22",
            },
        [12061710] = {
            ["Content"] = "虽然不知道是怎么一回事，小仆从，你说我们要不要赶紧离开这里，暂时避一避风头——",
            ["ContentFR"] = "Je ne sais pas ce qui se passe, mais... on devrait peut-être partir d’ici et se faire discret un moment—",
            ["DialogueId"] = 12061710,
            ["GUID"] = "1E31FA4C",
            ["NextDialogue"] = 12061746,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120617/1E31FA4C",
            },
        [12061711] = {
            ["Content"] = "——呀，长官，我们是良民，我们什么都没说！",
            ["ContentFR"] = "—Ah ! Monsieur ! Nous sommes des citoyens honnêtes, nous n’avons rien dit !",
            ["DialogueId"] = 12061711,
            ["GUID"] = "1E31FA76",
            ["NextDialogue"] = 12061712,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120617/1E31FA76",
            },
        [12061712] = {
            ["Content"] = "不必惊慌。{nickname}是华胥的贵客，{性别：他|她}的同伴也需恭敬以待，此乃太皓的意志。",
            ["ContentFR"] = "Nul besoin de paniquer. {nickname} est {性别:un|une} hôte d’honneur de Huaxu, et ses compagnons doivent également être traités avec respect. C’est la volonté de Taihao.",
            ["DialogueId"] = 12061712,
            ["GUID"] = "1E31FAA0",
            ["NextDialogue"] = 12061713,
            ["SpeakNpcId"] = 250030,
            ["VoiceName"] = "voice/$Locale$/story/1206/120617/1E31FAA0",
            },
        [12061713] = {
            ["Content"] = "但仍有一事需叨扰几位——请问是苏乙姑娘吗？",
            ["ContentFR"] = "Cependant, nous devons vérifier une chose. Êtes-vous Mademoiselle Su Yi ?",
            ["DialogueId"] = 12061713,
            ["GUID"] = "1E31FACA",
            ["NextDialogue"] = 12061714,
            ["SpeakNpcId"] = 250030,
            ["VoiceName"] = "voice/$Locale$/story/1206/120617/1E31FACA",
            },
        [12061714] = {
            ["Content"] = "正是我。什么事？",
            ["ContentFR"] = "C’est bien moi. Que se passe-t-il ?",
            ["DialogueId"] = 12061714,
            ["GUID"] = "1E31FAF4",
            ["NextDialogue"] = 12061715,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120617/1E31FAF4",
            },
        [12061715] = {
            ["Content"] = "我们收到检举消息，有人怀疑你用于参赛的机傀不合用例，需要接受检查。抱歉，这是例行手续。",
            ["ContentFR"] = "Nous avons reçu un signalement selon lequel la méchapoupée que vous utilisez dans la compétition pourrait ne pas être conforme au règlement. Conformément aux procédures, nous devons procéder à une inspection. Veuillez nous excuser pour ce désagrément.",
            ["DialogueId"] = 12061715,
            ["GUID"] = "1E31FB1E",
            ["NextDialogue"] = 12061716,
            ["SpeakNpcId"] = 250030,
            ["VoiceName"] = "voice/$Locale$/story/1206/120617/1E31FB1E",
            },
        [12061716] = {
            ["Content"] = "原来是她！",
            ["ContentFR"] = "Alors c’est elle...",
            ["DialogueId"] = 12061716,
            ["GUID"] = "1E31FB48",
            ["NextDialogue"] = 12061717,
            ["SpeakNpcName"] = "UI_Npc_Name_Siyu",
            ["VoiceName"] = "voice/$Locale$/story/1206/120617/1E31FB48",
            },
        [12061717] = {
            ["Content"] = "看着文文弱弱一个小姑娘，没想到竟然是传说中的飘零人……但好像也没有传说中的那么可怕？",
            ["ContentFR"] = "Elle a l’air si fragile... une simple jeune fille. Et on dit que c’est une Vagabonde ? Elle n’a pourtant rien de terrifiant.",
            ["DialogueId"] = 12061717,
            ["GUID"] = "1E31FB72",
            ["NextDialogue"] = 12061718,
            ["SpeakNpcName"] = "UI_Npc_Name_Siyu",
            ["VoiceName"] = "voice/$Locale$/story/1206/120617/1E31FB72",
            },
        [12061718] = {
            ["Content"] = "我的青鸾贰型？喏，拿去吧。",
            ["ContentFR"] = "Mon Qingluan Type II ? Tenez. Prenez-le.",
            ["DialogueId"] = 12061718,
            ["GUID"] = "1E31FB9C",
            ["NextDialogue"] = 12061719,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120617/1E31FB9C",
            },
        [12061719] = {
            ["Content"] = "事先说好，我对照过本次赛事的条例，制作手法是百分百合规的。你们可以尽管检查。但请不要破坏它的结构，这其中每个零件都是机傀师的心血。",
            ["ContentFR"] = "Je précise que j’ai soigneusement vérifié les règles de cette compétition. Ma méthode de fabrication est parfaitement conforme. Vous pouvez inspecter autant que vous voulez — mais je vous prie de ne pas endommager sa structure. Chaque pièce représente le travail acharné d’un maître des méchapoupées.",
            ["DialogueId"] = 12061719,
            ["GUID"] = "1E31FBC6",
            ["NextDialogue"] = 12061720,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120617/1E31FBC6",
            },
        [12061720] = {
            ["Content"] = "感谢您的配合。这机傀由司事会代为保管，明早赛前即可交还，您请放心。",
            ["ContentFR"] = "Merci pour votre coopération. Cette méchapoupée sera placée sous la garde du conseil administratif et vous sera restituée demain matin avant le début des épreuves. Soyez rassurée.",
            ["DialogueId"] = 12061720,
            ["GUID"] = "1E31FBF0",
            ["NextDialogue"] = 12061747,
            ["SpeakNpcId"] = 250030,
            ["VoiceName"] = "voice/$Locale$/story/1206/120617/1E31FBF0",
            },
        [12061721] = {
            ["Content"] = "合规？这就是你们飘零人用以伪饰自己行为的借口吗？",
            ["ContentFR"] = "Conforme ? C’est donc ainsi que vous, les Vagabonds, maquillez vos agissements ?",
            ["DialogueId"] = 12061721,
            ["GUID"] = "1E31FC1A",
            ["NextDialogue"] = 12061722,
            ["SpeakNpcId"] = 250015,
            ["VoiceName"] = "voice/$Locale$/story/1206/120617/1E31FC1A",
            },
        [12061722] = {
            ["Content"] = "怎么还是你？阴魂不散的。这检举该不会也是你干的吧？",
            ["ContentFR"] = "Encore toi ? Tu ne lâches jamais l’affaire... Dis-moi, ce signalement ne viendrait pas de toi, par hasard ?",
            ["DialogueId"] = 12061722,
            ["GUID"] = "1E31FC44",
            ["NextDialogue"] = 12061723,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120617/1E31FC44",
            },
        [12061723] = {
            ["Content"] = "呵，先前与你打了几次照面，我早就有所预感。本以为你们这些不法之徒只敢像老鼠一样躲在大风九章的缝隙中，如今却敢混入奉香大典，不知有何企图。",
            ["ContentFR"] = "<I>Hmpf.</> Depuis que nos chemins se sont croisés, j’avais déjà des soupçons. Je pensais que vous autres hors-la-loi n’osiez vous cacher que dans les failles des Neuf Chapitres de Dafeng comme des rats... mais voilà que vous vous infiltrez dans la Cérémonie de l’Encens. Qu’espérez-vous accomplir ?",
            ["DialogueId"] = 12061723,
            ["GUID"] = "1E31FC6E",
            ["NextDialogue"] = 12061724,
            ["SpeakNpcId"] = 250015,
            ["VoiceName"] = "voice/$Locale$/story/1206/120617/1E31FC6E",
            },
        [12061724] = {
            ["Content"] = "若非有人明确指出你的身份，恐怕大家到现在还蒙在鼓里。",
            ["ContentFR"] = "Sans quelqu’un pour révéler ton identité, tout le monde serait encore dans l’ignorance.",
            ["DialogueId"] = 12061724,
            ["GUID"] = "1E31FC98",
            ["NextDialogue"] = 12061725,
            ["SpeakNpcId"] = 250015,
            ["VoiceName"] = "voice/$Locale$/story/1206/120617/1E31FC98",
            },
        [12061725] = {
            ["Content"] = "本姑娘行得端做得正，从未刻意掩饰过自己的身份，只是没有特意说出来的必要罢了。",
            ["ContentFR"] = "Je n’ai jamais rien fait dont j’aurais à rougir. Je n’ai simplement jamais jugé nécessaire de crier mon identité sur tous les toits.",
            ["DialogueId"] = 12061725,
            ["GUID"] = "1E31FCC2",
            ["NextDialogue"] = 12061726,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120617/1E31FCC2",
            },
        [12061726] = {
            ["Content"] = "说到底，飘零人怎么你了？",
            ["ContentFR"] = "Au fond, qu’est-ce que les Vagabonds t’ont fait ?",
            ["DialogueId"] = 12061726,
            ["GUID"] = "1E31FCEC",
            ["NextDialogue"] = 12061727,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120617/1E31FCEC",
            },
        [12061727] = {
            ["Content"] = "……飘零人怎么我了？前辈犯下的累累恶行竟被你说的如此轻巧。你们作恶多端，谁人不知？还需要我细数你们的一桩桩罪行吗？",
            ["ContentFR"] = "... Qu’est-ce qu’ils m’ont fait ? Tu parles des crimes accumulés par tes prédécesseurs comme si ce n’était rien. Les Vagabonds sont connus pour leurs méfaits. Veux-tu vraiment que je les énumère un par un ?",
            ["DialogueId"] = 12061727,
            ["GUID"] = "1E31FD16",
            ["NextDialogue"] = 12061728,
            ["SpeakNpcId"] = 250015,
            ["VoiceName"] = "voice/$Locale$/story/1206/120617/1E31FD16",
            },
        [12061728] = {
            ["Content"] = "那些以讹传讹、捉风捕影的罪行？你说再多又能证明什么？",
            ["ContentFR"] = "Des rumeurs sans fondement que les gens répètent sans réfléchir ? Même si tu les répétais mille fois, qu’est-ce que cela prouverait ?",
            ["DialogueId"] = 12061728,
            ["GUID"] = "1E31FD40",
            ["NextDialogue"] = 12061729,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120617/1E31FD40",
            },
        [12061729] = {
            ["Content"] = "（喧闹的议论声。）",
            ["ContentFR"] = "(La foule commence à murmurer bruyamment.)",
            ["DialogueId"] = 12061729,
            ["GUID"] = "1E31FD6A",
            ["NextDialogue"] = 12061748,
            ["VoiceName"] = "voice/$Locale$/story/1206/120617/1E31FD6A",
            },
        [12061730] = {
            ["Content"] = "我还以为何事引起嘈杂，原来是选手之间有些误会。",
            ["ContentFR"] = "Je me demandais d’où venait tout ce tumulte. Il semble qu’il s’agisse simplement d’un malentendu entre concurrents.",
            ["DialogueId"] = 12061730,
            ["GUID"] = "1E31FD94",
            ["NextDialogue"] = 12061731,
            ["RelatedWikiId"] = {
                [1] = 203001,
                },
            ["SpeakNpcId"] = 250004,
            ["VoiceName"] = "voice/$Locale$/story/1206/120617/1E31FD94",
            },
        [12061731] = {
            ["Content"] = "止流……？",
            ["ContentFR"] = "Zhiliu... ?",
            ["DialogueId"] = 12061731,
            ["GUID"] = "1E31FDBE",
            ["NextDialogue"] = 12061732,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120617/1E31FDBE",
            },
        [12061732] = {
            ["Content"] = "……我听闻那起风波后，现任龙渊上卿引起诸多非议，已经被迫请辞在家。这件事，恐怕不适合阁下来横插一脚吧？",
            ["ContentFR"] = "... J’ai entendu dire qu’après cet incident, l’actuel Haut Chancelier de Longyuan avait suscité de nombreuses critiques et qu’il avait été contraint de se retirer. Dans ces conditions, il ne serait peut-être pas très approprié que vous veniez vous mêler de cette affaire, n’est-ce pas ?",
            ["DialogueId"] = 12061732,
            ["GUID"] = "1E31FDE8",
            ["NextDialogue"] = 12061733,
            ["SpeakNpcId"] = 250015,
            ["VoiceName"] = "voice/$Locale$/story/1206/120617/1E31FDE8",
            },
        }
  end },
  { MinKey = 12061733, MaxKey = 12062517, Loader = function()
      return {
        [12061733] = {
            ["Content"] = "呵呵……很不巧，我虽已不是龙渊上卿，却仍肩负本次奉香群英试的协理职责。因而我依然有在这里发言的位置。",
            ["ContentFR"] = "Héhé... Malheureusement pour vous, même si je ne suis plus Haut Chancelier de Longyuan, j’assume toujours les fonctions de coordinatrice pour ce Tournoi de l’Encens. À ce titre, j’ai parfaitement le droit de prendre la parole ici.",
            ["DialogueId"] = 12061733,
            ["GUID"] = "1E31FE12",
            ["NextDialogue"] = 12061734,
            ["SpeakNpcId"] = 250004,
            ["VoiceName"] = "voice/$Locale$/story/1206/120617/1E31FE12",
            },
        [12061734] = {
            ["Content"] = "诸位的担忧我已知晓，即便是飘零人，也仍是我华胥民众。大风九章已既往不咎，若无作奸犯科之实，他们参加群英试并无不可。",
            ["ContentFR"] = "Je comprends les inquiétudes de chacun. Mais même les Vagabonds restent des citoyens de Huaxu. Les Neuf Chapitres de Dafeng ont déjà décidé de ne plus revenir sur le passé. Tant qu’aucun crime n’a été commis, rien ne s’oppose à leur participation au Tournoi de l’Encens.",
            ["DialogueId"] = 12061734,
            ["GUID"] = "1E31FE3C",
            ["NextDialogue"] = 12061735,
            ["SpeakNpcId"] = 250004,
            ["VoiceName"] = "voice/$Locale$/story/1206/120617/1E31FE3C",
            },
        [12061735] = {
            ["Content"] = "如今太皓神君已将裁决定夺之权重新托付于众人。因而诸位更要以自己的双眼去判定何者为伪，何者为真。",
            ["ContentFR"] = "À présent, Taihao a de nouveau confié au peuple le pouvoir de juger. Il vous appartient donc d’observer par vous-mêmes ce qui est vrai et ce qui ne l’est pas.",
            ["DialogueId"] = 12061735,
            ["GUID"] = "1E31FE66",
            ["NextDialogue"] = 12061736,
            ["SpeakNpcId"] = 250004,
            ["VoiceName"] = "voice/$Locale$/story/1206/120617/1E31FE66",
            },
        [12061736] = {
            ["Content"] = "在尚无证据之时就去断定这位苏乙姑娘居心叵测，恐怕有失偏颇吧？",
            ["ContentFR"] = "Accuser Mademoiselle Su Yi de mauvaises intentions alors qu’aucune preuve n’existe serait sans doute un peu hâtif, non ?",
            ["DialogueId"] = 12061736,
            ["GUID"] = "1E31FE90",
            ["NextDialogue"] = 12061737,
            ["SpeakNpcId"] = 250004,
            ["VoiceName"] = "voice/$Locale$/story/1206/120617/1E31FE90",
            },
        [12061737] = {
            ["Content"] = "哼，我没有证据不假。但总不能就此放任这些目无法纪的狂徒继续在这里招摇过市！要是纵容其人犯下罪行，到时候证据倒是确凿，可为时已晚了。",
            ["ContentFR"] = "<I>Hmpf.</> C’est vrai, je n’ai aucune preuve. Mais on ne peut pas non plus laisser ces gens sans foi ni loi parader ici comme si de rien n’était ! Si on attend qu’ils commettent un crime, les preuves seront peut-être irréfutables... mais il sera déjà trop tard.",
            ["DialogueId"] = 12061737,
            ["GUID"] = "1E31FEBA",
            ["NextDialogue"] = 12061738,
            ["SpeakNpcId"] = 250015,
            ["VoiceName"] = "voice/$Locale$/story/1206/120617/1E31FEBA",
            },
        [12061738] = {
            ["Content"] = "嗯，你的担忧也不无道理。",
            ["ContentFR"] = "Hm. Tes inquiétudes ne sont pas dénuées de fondement.",
            ["DialogueId"] = 12061738,
            ["GUID"] = "1E31FEE4",
            ["NextDialogue"] = 12061739,
            ["SpeakNpcId"] = 250004,
            ["VoiceName"] = "voice/$Locale$/story/1206/120617/1E31FEE4",
            },
        [12061739] = {
            ["Content"] = "喂喂，怎么突然向着那家伙说话了……！",
            ["ContentFR"] = "Hé, hé ! Pourquoi tu prends soudain le parti de ce type... !",
            ["DialogueId"] = 12061739,
            ["GUID"] = "1E31FF0E",
            ["NextDialogue"] = 12061740,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120617/1E31FF0E",
            },
        [12061740] = {
            ["Content"] = "赛事安全是本届群英试的重中之重，任何潜在的隐患都会引起重视。",
            ["ContentFR"] = "La sécurité du tournoi est la priorité absolue de cette édition. Toute menace potentielle doit être prise au sérieux.",
            ["DialogueId"] = 12061740,
            ["GUID"] = "1E31FF38",
            ["NextDialogue"] = 12061741,
            ["SpeakNpcId"] = 250004,
            ["VoiceName"] = "voice/$Locale$/story/1206/120617/1E31FF38",
            },
        [12061741] = {
            ["Content"] = "所以眼下还请几位随我走一遭，配合官方调查。在场的各位还请稍安勿躁，之后定会给诸位一个交代。",
            ["ContentFR"] = "Je vous demanderai donc de me suivre pour coopérer à l’enquête officielle. Quant aux autres, veuillez rester calmes. Une explication vous sera donnée par la suite.",
            ["DialogueId"] = 12061741,
            ["GUID"] = "1E31FF62",
            ["NextDialogue"] = 12061742,
            ["SpeakNpcId"] = 250004,
            ["VoiceName"] = "voice/$Locale$/story/1206/120617/1E31FF62",
            },
        [12061742] = {
            ["Content"] = "苏乙姑娘，没问题吧？",
            ["ContentFR"] = "Mademoiselle Su Yi, cela ne te pose pas de problème ?",
            ["DialogueId"] = 12061742,
            ["GUID"] = "1E31FF8C",
            ["NextDialogue"] = 12061743,
            ["SpeakNpcId"] = 250004,
            ["VoiceName"] = "voice/$Locale$/story/1206/120617/1E31FF8C",
            },
        [12061743] = {
            ["Content"] = "……知道了，依你便是。",
            ["ContentFR"] = "... Très bien. Fais comme tu veux.",
            ["DialogueId"] = 12061743,
            ["GUID"] = "1E31FFB6",
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120617/1E31FFB6",
            },
        [12061744] = {
            ["DialogueId"] = 12061744,
            ["GUID"] = "1E31FFB7",
            ["NextDialogue"] = 12061704,
            },
        [12061745] = {
            ["DialogueId"] = 12061745,
            ["GUID"] = "1E31FFB8",
            ["NextDialogue"] = 12061706,
            },
        [12061746] = {
            ["DialogueId"] = 12061746,
            ["GUID"] = "1E31FFB9",
            ["NextDialogue"] = 12061711,
            },
        [12061747] = {
            ["DialogueId"] = 12061747,
            ["GUID"] = "1E31FFBA",
            ["NextDialogue"] = 12061721,
            },
        [12061748] = {
            ["DialogueId"] = 12061748,
            ["GUID"] = "1E31FFBB",
            ["NextDialogue"] = 12061730,
            },
        [12061801] = {
            ["Content"] = "到这里应该就可以敞开说话了。",
            ["ContentFR"] = "Ici, nous pouvons parler plus librement.",
            ["DialogueId"] = 12061801,
            ["GUID"] = "1E32093A",
            ["NextDialogue"] = 12061802,
            ["RelatedWikiId"] = {
                [1] = 203009,
                [2] = 203001,
                [3] = 201029,
                [4] = 103001,
                [5] = 203013,
                [6] = 203014,
                [7] = 408018,
                },
            ["SpeakNpcId"] = 250004,
            ["VoiceName"] = "voice/$Locale$/story/1206/120618/1E32093A",
            },
        [12061802] = {
            ["Content"] = "抱歉，几位。刚刚的场合，即便是我也无法为苏乙姑娘进行担保，只能出此下策。",
            ["ContentFR"] = "Désolée, vous tous. Dans une situation comme celle-là, même moi je ne pouvais pas publiquement me porter garante de Mademoiselle Su Yi. Je n’avais pas d’autre choix.",
            ["DialogueId"] = 12061802,
            ["GUID"] = "1E320964",
            ["NextDialogue"] = 12061803,
            ["SpeakNpcId"] = 250004,
            ["VoiceName"] = "voice/$Locale$/story/1206/120618/1E320964",
            },
        [12061803] = {
            ["Content"] = "原、原来是这样啊，那是白错怪你了。",
            ["ContentFR"] = "A-Ah... je vois ! Alors c’est moi qui t’ai mal jugée !",
            ["DialogueId"] = 12061803,
            ["GUID"] = "1E32098E",
            ["NextDialogue"] = 12061804,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120618/1E32098E",
            },
        [12061804] = {
            ["Content"] = "……可以理解。",
            ["ContentFR"] = "... Je comprends.",
            ["DialogueId"] = 12061804,
            ["GUID"] = "1E3209B8",
            ["NextDialogue"] = 12061805,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120618/1E3209B8",
            },
        [12061805] = {
            ["Content"] = "对这种情况我早有预料，就算不被认可也没关系，我只为获胜而来。",
            ["ContentFR"] = "Je m’attendais déjà à ce genre de situation. Même si je ne suis pas acceptée, ce n’est pas grave. Je suis venue ici pour gagner, rien de plus.",
            ["DialogueId"] = 12061805,
            ["GUID"] = "1E3209E2",
            ["NextDialogue"] = 12061806,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120618/1E3209E2",
            },
        [12061806] = {
            ["Content"] = "止流，谢谢你出现得这么及时，为我们解围。",
            ["ContentFR"] = "Zhiliu, merci d’être arrivée à temps. Tu nous as vraiment tirés d’affaire.",
            ["DialogueId"] = 12061806,
            ["GUID"] = "1E320A0C",
            ["NextDialogue"] = 12061807,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120618/1E320A0C",
            },
        [12061807] = {
            ["Content"] = "呵呵……从你报名那刻起，我就一直关注着你们。",
            ["ContentFR"] = "Héhé... Depuis le moment où vous vous êtes inscrits, je garde un œil sur vous.",
            ["DialogueId"] = 12061807,
            ["GUID"] = "1E320A36",
            ["NextDialogue"] = 12061808,
            ["SpeakNpcId"] = 250004,
            ["VoiceName"] = "voice/$Locale$/story/1206/120618/1E320A36",
            },
        [12061808] = {
            ["Content"] = "本届群英试意义特殊。作为风波平息之后的首次大典，它被寄予了平定民心、彰显“人”之力量的厚望。",
            ["ContentFR"] = "Cette édition du Tournoi de l’Encens a une importance particulière. En tant que première grande cérémonie depuis que la tempête s’est apaisée, elle porte l’espoir d’apaiser les esprits et de montrer la force de l’humanité.",
            ["DialogueId"] = 12061808,
            ["GUID"] = "1E320A60",
            ["NextDialogue"] = 12061809,
            ["SpeakNpcId"] = 250004,
            ["VoiceName"] = "voice/$Locale$/story/1206/120618/1E320A60",
            },
        [12061809] = {
            ["Content"] = "昔日华胥人习惯于依靠太皓一成不变的力量，而引导大家审视自我，拥抱变化，是本届赛事举办的用意。",
            ["ContentFR"] = "Autrefois, les habitants de Huaxu avaient l’habitude de s’en remettre entièrement à la puissance immuable de Taihao. Amener chacun à se regarder lui-même et à accepter le changement est précisément l’objectif de cette compétition.",
            ["DialogueId"] = 12061809,
            ["GUID"] = "1E320A8A",
            ["NextDialogue"] = 12061810,
            ["SpeakNpcId"] = 250004,
            ["VoiceName"] = "voice/$Locale$/story/1206/120618/1E320A8A",
            },
        [12061810] = {
            ["Content"] = "{nickname}，我虽想过邀请你来参赛，但考虑到你归乡心切，便未能开口。不曾想你竟与苏乙姑娘一同组队，却是正中我下怀了。",
            ["ContentFR"] = "{nickname}, j’avais envisagé de t’inviter à participer. Mais comme je savais que tu étais {性别:pressé|pressée} de retourner à Givrelac, je n’ai finalement rien dit. Je ne pensais pas que tu formerais une équipe avec Mademoiselle Su Yi... mais je dois avouer que cela tombe parfaitement.",
            ["DialogueId"] = 12061810,
            ["GUID"] = "1E320AB4",
            ["NextDialogue"] = 12061811,
            ["SpeakNpcId"] = 250004,
            ["VoiceName"] = "voice/$Locale$/story/1206/120618/1E320AB4",
            },
        [12061811] = {
            ["Content"] = "啊！之前煜明说自己受人所托，及时出现帮我们解围。难不成……",
            ["ContentFR"] = "Ah ! Tout à l’heure, Yuming disait qu’il était venu nous aider à la demande de quelqu’un. Ne me dis pas que...",
            ["DialogueId"] = 12061811,
            ["GUID"] = "1E320ADE",
            ["NextDialogue"] = 12061812,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120618/1E320ADE",
            },
        [12061812] = {
            ["Content"] = "如你所想，正是止流掌柜托在下前来相助。",
            ["ContentFR"] = "Comme tu l’as deviné, c’est la Patronne Zhiliu qui m’a demandé de venir vous prêter main-forte.",
            ["DialogueId"] = 12061812,
            ["GUID"] = "1E320B08",
            ["NextDialogue"] = 12061813,
            ["SpeakNpcId"] = 250005,
            ["VoiceName"] = "voice/$Locale$/story/1206/120618/1E320B08",
            },
        [12061813] = {
            ["Content"] = "此前未能及时澄清，反倒引发误会，是煜明之过。",
            ["ContentFR"] = "Je n’ai pas clarifié la situation plus tôt, ce qui a provoqué un malentendu. J’en prends la responsabilité.",
            ["DialogueId"] = 12061813,
            ["GUID"] = "1E320B32",
            ["NextDialogue"] = 12061814,
            ["SpeakNpcId"] = 250005,
            ["VoiceName"] = "voice/$Locale$/story/1206/120618/1E320B32",
            },
        [12061814] = {
            ["Content"] = "大众和飘零人之间的偏见与对立由来已久。如何推动飘零人重新融入华胥，也是现今亟待解决的课题之一。",
            ["ContentFR"] = "Les préjugés et l’hostilité entre le public et les Vagabonds existent depuis longtemps. Trouver un moyen de permettre aux Vagabonds de se réintégrer à Huaxu est l’un des problèmes urgents auxquels nous devons faire face.",
            ["DialogueId"] = 12061814,
            ["GUID"] = "1E320B5C",
            ["NextDialogue"] = 12061815,
            ["SpeakNpcId"] = 250004,
            ["VoiceName"] = "voice/$Locale$/story/1206/120618/1E320B5C",
            },
        [12061815] = {
            ["Content"] = "目前你们正处于风口浪尖，众人情绪已经被煽动了起来，此时无论说什么都容易遭到曲解。不如先按下不表，等待时间抚平一切。",
            ["ContentFR"] = "Pour l’instant, vous êtes au cœur de la tempête. Les émotions de la foule ont déjà été attisées. Dans ces conditions, quoi que vous disiez risquerait d’être mal interprété. Le mieux est de patienter et de laisser le temps apaiser les choses.",
            ["DialogueId"] = 12061815,
            ["GUID"] = "1E320B86",
            ["NextDialogue"] = 12061816,
            ["SpeakNpcId"] = 250004,
            ["VoiceName"] = "voice/$Locale$/story/1206/120618/1E320B86",
            },
        [12061816] = {
            ["Content"] = "我稍后会出具一份调查说明为你们背书，有了这份说明，你们后续参加群英试就不会再受阻挠。",
            ["ContentFR"] = "Je ferai publier plus tard un rapport d’enquête attestant de votre bonne foi. Une fois ce document publié, votre participation au Tournoi de l’Encens ne devrait plus rencontrer d’obstacles.",
            ["DialogueId"] = 12061816,
            ["GUID"] = "1E320BB0",
            ["NextDialogue"] = 12061817,
            ["SpeakNpcId"] = 250004,
            ["VoiceName"] = "voice/$Locale$/story/1206/120618/1E320BB0",
            },
        [12061817] = {
            ["Content"] = "……多谢。",
            ["ContentFR"] = "... Merci.",
            ["DialogueId"] = 12061817,
            ["GUID"] = "1E320BDA",
            ["NextDialogue"] = 12061818,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120618/1E320BDA",
            },
        [12061818] = {
            ["Content"] = "呵呵，只是举手之劳。",
            ["ContentFR"] = "Héhé. Ce n’est vraiment pas grand-chose.",
            ["DialogueId"] = 12061818,
            ["GUID"] = "1E320C04",
            ["NextDialogue"] = 12061819,
            ["SpeakNpcId"] = 250004,
            ["VoiceName"] = "voice/$Locale$/story/1206/120618/1E320C04",
            },
        [12061819] = {
            ["Content"] = "今日的赛事已经结束了，你们先回去休息吧。",
            ["ContentFR"] = "Les épreuves d’aujourd’hui sont terminées. Vous devriez rentrer vous reposer.",
            ["DialogueId"] = 12061819,
            ["GUID"] = "1E320C2E",
            ["NextDialogue"] = 12061820,
            ["SpeakNpcId"] = 250004,
            ["VoiceName"] = "voice/$Locale$/story/1206/120618/1E320C2E",
            },
        [12061820] = {
            ["Content"] = "{nickname}，你可以稍微留一下吗？有一些话，我想单独嘱托给你。",
            ["ContentFR"] = "{nickname}, pourrais-tu rester un moment ? J’aimerais te dire quelques mots en privé.",
            ["DialogueId"] = 12061820,
            ["GUID"] = "1E320C58",
            ["SpeakNpcId"] = 250004,
            ["VoiceName"] = "voice/$Locale$/story/1206/120618/1E320C58",
            },
        [12061901] = {
            ["Content"] = "怎么了，止流掌柜？",
            ["ContentFR"] = "Qu’y a-t-il, Zhiliu ?",
            ["DialogueId"] = 12061901,
            ["GUID"] = "1E3219A2",
            ["NextDialogue"] = 12061902,
            ["RelatedWikiId"] = {
                [1] = 203009,
                [2] = 203001,
                [3] = 201029,
                [4] = 103001,
                [5] = 203013,
                [6] = 203014,
                [7] = 408018,
                },
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120619/1E3219A2",
            },
        [12061902] = {
            ["Content"] = "你的同伴……苏乙，她正在面临的是一场关于人心和自我的挑战。",
            ["ContentFR"] = "Ton amie... Su Yi. Elle fait face à une épreuve qui mettra les cœurs à nu... le sien compris.",
            ["DialogueId"] = 12061902,
            ["GUID"] = "1E3219CC",
            ["NextDialogue"] = 12061903,
            ["SpeakNpcId"] = 250004,
            ["VoiceName"] = "voice/$Locale$/story/1206/120619/1E3219CC",
            },
        [12061903] = {
            ["Content"] = "人心向来是看不见摸不着的东西。这不同于显性的斗争，那些藏于水面之下的仇恨、恐惧、偏见如同暗藻一样，会绊住每一个泅泳者，使其溺亡。",
            ["ContentFR"] = "Le cœur humain est une chose que l’on ne peut ni voir ni saisir. Contrairement aux conflits visibles, la haine, la peur et les préjugés dissimulés sous la surface ressemblent à des algues obscures : elles entravent ceux qui nagent et finissent par les entraîner au fond.",
            ["DialogueId"] = 12061903,
            ["GUID"] = "1E3219F6",
            ["NextDialogue"] = 12061904,
            ["SpeakNpcId"] = 250004,
            ["VoiceName"] = "voice/$Locale$/story/1206/120619/1E3219F6",
            },
        [12061904] = {
            ["Content"] = "古往今来，贸然向人心发起的挑战，往往会以悲剧收尾。",
            ["ContentFR"] = "Depuis toujours, ceux qui défient trop brusquement l’opinion des gens finissent souvent par connaître une fin tragique.",
            ["DialogueId"] = 12061904,
            ["GUID"] = "1E321A20",
            ["NextDialogue"] = 12061905,
            ["SpeakNpcId"] = 250004,
            ["VoiceName"] = "voice/$Locale$/story/1206/120619/1E321A20",
            },
        [12061905] = {
            ["Content"] = "这其中的关窍，不在于如何应对对面的恶意，而是挑战者的内心也会在不知不觉中被仇恨同化，最终以怨报怨，走向彻底的对抗。",
            ["ContentFR"] = "La véritable difficulté n’est pas seulement de faire face à la malveillance des autres. C’est que, sans s’en rendre compte, celui qui défie la haine finit parfois par être contaminé par elle... répondant à la haine par la haine, jusqu’à sombrer dans un affrontement total.",
            ["DialogueId"] = 12061905,
            ["GUID"] = "1E321A4A",
            ["NextDialogue"] = 12061906,
            ["SpeakNpcId"] = 250004,
            ["VoiceName"] = "voice/$Locale$/story/1206/120619/1E321A4A",
            },
        [12061906] = {
            ["Content"] = "如何审视自我，开辟一条新的道路……这场挑战注定会异常艰辛。",
            ["ContentFR"] = "Se regarder soi-même et ouvrir une nouvelle voie... Cette épreuve sera inévitablement difficile.",
            ["DialogueId"] = 12061906,
            ["GUID"] = "1E321A74",
            ["NextDialogue"] = 12061907,
            ["SpeakNpcId"] = 250004,
            ["VoiceName"] = "voice/$Locale$/story/1206/120619/1E321A74",
            },
        [12061907] = {
            ["Content"] = "谢谢你的提醒，止流。我相信她能做到的。",
            ["ContentFR"] = "Merci de m’avoir prévenu, Zhiliu. Je crois qu’elle en est capable.",
            ["DialogueId"] = 12061907,
            ["GUID"] = "1E321A9E",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120619/1E321A9E",
            },
        [12062001] = {
            ["Content"] = "虽然早想到可能会有飘零人在奉香大典期间混进来，但在这茫茫人海里找出他们也无异于大海捞针。幸亏你认出了那天工苏氏的后人。",
            ["ContentFR"] = "Je me doutais que certains Vagabonds se glisseraient dans la Cérémonie de l’Encens. Mais dans une foule pareille, les repérer revient presque à chercher une aiguille dans une botte de foin. Heureusement que tu as reconnu la descendante des Artisans Célestes du clan Su.",
            ["DialogueId"] = 12062001,
            ["GUID"] = "1E322A0A",
            ["NextDialogue"] = 12062002,
            ["RelatedWikiId"] = {
                [1] = 203009,
                [2] = 203001,
                [3] = 201029,
                [4] = 103001,
                [5] = 203013,
                [6] = 203014,
                [7] = 408018,
                },
            ["SpeakNpcId"] = 250015,
            ["VoiceName"] = "voice/$Locale$/story/1206/120620/1E322A0A",
            },
        [12062002] = {
            ["Content"] = "不过听你描述，你们似乎更早之前还有过碰面？",
            ["ContentFR"] = "Mais d’après ce que tu m’as raconté, vous vous étiez déjà rencontrés auparavant ?",
            ["DialogueId"] = 12062002,
            ["GUID"] = "1E322A34",
            ["NextDialogue"] = 12062003,
            ["SpeakNpcId"] = 250015,
            ["VoiceName"] = "voice/$Locale$/story/1206/120620/1E322A34",
            },
        [12062003] = {
            ["Content"] = "……小安在野外遭到玄色狴犴的袭击，被{性别：他|她}们二人所救。",
            ["ContentFR"] = "... An a été attaqué par un Bi’an obscur dans la nature. {性别:Ils l’ont sauvé tous les deux|Elles l’ont sauvé toutes les deux}.",
            ["DialogueId"] = 12062003,
            ["GUID"] = "1E322A5E",
            ["NextDialogue"] = 12062004,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120620/1E322A5E",
            },
        [12062004] = {
            ["Content"] = "救人？{性别：他|她}们？那位白发年轻人暂且不提，那个飘零人小姑娘去救人？可笑，不过是趁着如今华胥正当变局，惺惺作态而已。",
            ["ContentFR"] = "Sauvé ? Eux ? {性别:Le jeune homme|La jeune femme} aux cheveux blancs, passe encore... mais cette petite Vagabonde qui sauve des gens ? Ridicule. Elle ne fait que jouer la comédie pendant que Huaxu traverse une période de bouleversements.",
            ["DialogueId"] = 12062004,
            ["GUID"] = "1E322A88",
            ["NextDialogue"] = 12062005,
            ["SpeakNpcId"] = 250015,
            ["VoiceName"] = "voice/$Locale$/story/1206/120620/1E322A88",
            },
        [12062005] = {
            ["Content"] = "时候差不多了。西郊的那处<W>地宫</>，布置如何了？",
            ["ContentFR"] = "Le moment approche. Qu’en est-il de ce <W>complexe souterrain</> dans les collines de l’ouest ?",
            ["DialogueId"] = 12062005,
            ["GUID"] = "1E322AB2",
            ["NextDialogue"] = 12062006,
            ["SpeakNpcId"] = 250015,
            ["VoiceName"] = "voice/$Locale$/story/1206/120620/1E322AB2",
            },
        [12062006] = {
            ["Content"] = "万事俱备，只等决赛了。",
            ["ContentFR"] = "Tout est prêt. Nous n’attendons plus que la finale.",
            ["DialogueId"] = 12062006,
            ["GUID"] = "1E322ADC",
            ["NextDialogue"] = 12062007,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120620/1E322ADC",
            },
        [12062007] = {
            ["Content"] = "呵呵……恰巧在这个时间点上发现了掩藏在山体中的昔日机枢派地宫，这是不是说明这次连天意都站在我们这边？",
            ["ContentFR"] = "Héhé... Découvrir par hasard un ancien complexe souterrain de la Secte Jishu caché dans la montagne à un moment pareil... On dirait bien que même le destin est de notre côté cette fois.",
            ["DialogueId"] = 12062007,
            ["GUID"] = "1E322B06",
            ["NextDialogue"] = 12062008,
            ["SpeakNpcId"] = 250015,
            ["VoiceName"] = "voice/$Locale$/story/1206/120620/1E322B06",
            },
        [12062008] = {
            ["Content"] = "只要<W>计划顺利</>……那些飘零人就能滚回他们该回的地方了。",
            ["ContentFR"] = "Tant que le <W>plan se déroule comme prévu</>... ces Vagabonds retourneront d’où ils viennent.",
            ["DialogueId"] = 12062008,
            ["GUID"] = "1E322B30",
            ["NextDialogue"] = 12062009,
            ["SpeakNpcId"] = 250015,
            ["VoiceName"] = "voice/$Locale$/story/1206/120620/1E322B30",
            },
        [12062009] = {
            ["Content"] = "要怪，就怪她的那些前辈肆意妄为。要怪，就怪我们这些大人既胆怯又执拗，放不下这些糟心的过往吧。",
            ["ContentFR"] = "Si quelqu’un doit être blâmé, ce sont leurs prédécesseurs qui ont agi sans retenue. Et nous aussi... nous autres adultes, trop lâches et trop obstinés pour laisser ce passé derrière nous.",
            ["DialogueId"] = 12062009,
            ["GUID"] = "1E322B5A",
            ["NextDialogue"] = 12062010,
            ["SpeakNpcId"] = 250015,
            ["VoiceName"] = "voice/$Locale$/story/1206/120620/1E322B5A",
            },
        [12062010] = {
            ["Content"] = "你说，要是小安长大了，知道他母亲和叔叔阿姨们做的这些事，他会理解我们吗？",
            ["ContentFR"] = "Dis-moi... quand An sera grand et qu’il apprendra ce que sa mère et les autres ont fait... crois-tu qu’il nous comprendra ?",
            ["DialogueId"] = 12062010,
            ["GUID"] = "1E322B84",
            ["NextDialogue"] = 12062011,
            ["SpeakNpcId"] = 250015,
            ["VoiceName"] = "voice/$Locale$/story/1206/120620/1E322B84",
            },
        [12062011] = {
            ["Content"] = "我不是他的母亲。",
            ["ContentFR"] = "Je ne suis pas sa mère.",
            ["DialogueId"] = 12062011,
            ["GUID"] = "1E322BAE",
            ["NextDialogue"] = 12062012,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120620/1E322BAE",
            },
        [12062012] = {
            ["Content"] = "看我这脑子，差点都忘了。",
            ["ContentFR"] = "... Ah. J’avais presque oublié.",
            ["DialogueId"] = 12062012,
            ["GUID"] = "1E322BD8",
            ["NextDialogue"] = 12062013,
            ["SpeakNpcId"] = 250015,
            ["VoiceName"] = "voice/$Locale$/story/1206/120620/1E322BD8",
            },
        [12062013] = {
            ["Content"] = "还有，我希望小安永远都不要知道这些事。如果知道了，我希望他永远都不要理解我们——他已经经历了太多事情了。",
            ["ContentFR"] = "Et j’espère qu’An n’apprendra jamais tout cela. Et s’il l’apprend... j’espère qu’il ne nous comprendra jamais. Il a déjà traversé trop d’épreuves.",
            ["DialogueId"] = 12062013,
            ["GUID"] = "1E322C02",
            ["NextDialogue"] = 12062014,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120620/1E322C02",
            },
        [12062014] = {
            ["Content"] = "但愿如此吧。",
            ["ContentFR"] = "Espérons-le.",
            ["DialogueId"] = 12062014,
            ["GUID"] = "1E322C2C",
            ["SpeakNpcId"] = 250015,
            ["VoiceName"] = "voice/$Locale$/story/1206/120620/1E322C2C",
            },
        [12062015] = {
            ["Content"] = "一天的赛事终于结束了，不知道苏乙现在心情怎么样了……",
            ["ContentFR"] = "Une journée de compétition qui se termine enfin... Je me demande comment Su Yi se sent maintenant...",
            ["DialogueId"] = 12062015,
            ["GUID"] = "1E322C56",
            ["NextDialogue"] = 12062016,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120620/1E322C56",
            },
        [12062016] = {
            ["Content"] = "睡觉之前，去找找她吧……",
            ["ContentFR"] = "Avant d’aller dormir, je devrais aller la voir...",
            ["DialogueId"] = 12062016,
            ["GUID"] = "1E322C80",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120620/1E322C80",
            },
        [12062101] = {
            ["Content"] = "终于把姑姑留下的牵机鸢的大部分结构解析完毕了……",
            ["ContentFR"] = "J’ai enfin terminé d’analyser la majeure partie de la structure du cerf-volant mécanique que ma tante a laissé derrière elle...",
            ["DialogueId"] = 12062101,
            ["GUID"] = "1E323A72",
            ["NextDialogue"] = 12062102,
            ["RelatedWikiId"] = {
                [1] = 203009,
                [2] = 103001,
                [3] = 203013,
                [4] = 203014,
                [5] = 408018,
                },
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120621/1E323A72",
            },
        [12062102] = {
            ["Content"] = "原来姑姑早在十几年前就已经达到了这样的水平。我还要努力多久，才能追上姑姑的脚步呢……",
            ["ContentFR"] = "Dire qu’elle avait déjà atteint un tel niveau il y a plus de dix ans... Combien de temps devrai-je encore travailler pour rattraper ses pas... ?",
            ["DialogueId"] = 12062102,
            ["GUID"] = "1E323A9C",
            ["NextDialogue"] = 12062103,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120621/1E323A9C",
            },
        [12062103] = {
            ["Content"] = "只是这个强化机傀运动性能的组件在整个设计里格格不入，姑姑把它安装在这里，又是什么用意……",
            ["ContentFR"] = "Mais ce module destiné à renforcer les capacités de mouvement des méchapoupées ne correspond pas du tout au reste de la conception... Pourquoi ma tante l’aurait-elle installé ici... ?",
            ["DialogueId"] = 12062103,
            ["GUID"] = "1E323AC6",
            ["NextDialogue"] = 12062104,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120621/1E323AC6",
            },
        [12062104] = {
            ["Content"] = "苏乙，原来你在这里。",
            ["ContentFR"] = "Su Yi. Te voilà.",
            ["DialogueId"] = 12062104,
            ["GUID"] = "1E323AF0",
            ["NextDialogue"] = 12062105,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120621/1E323AF0",
            },
        [12062105] = {
            ["Content"] = "嗯？{nickname}，找我有什么事吗？",
            ["ContentFR"] = "Hm ? {nickname}, tu as besoin de quelque chose ?",
            ["DialogueId"] = 12062105,
            ["GUID"] = "1E323B1A",
            ["NextDialogue"] = 12062106,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120621/1E323B1A",
            },
        [12062106] = {
            ["Content"] = "来看看你现在心情怎么样了。",
            ["ContentFR"] = "Je voulais simplement voir comment tu te sentais.",
            ["DialogueId"] = 12062106,
            ["GUID"] = "1E323B44",
            ["NextDialogue"] = 12062107,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120621/1E323B44",
            },
        [12062107] = {
            ["Content"] = "我能有什么事……啊，你难不成是想为白天发生的事情来安慰我吗？",
            ["ContentFR"] = "Comment pourrais-je aller mal... ? Ah, ne me dis pas que tu es {性别:venu|venue} me réconforter à cause de ce qui s’est passé aujourd’hui ?",
            ["DialogueId"] = 12062107,
            ["GUID"] = "1E323B6E",
            ["NextDialogue"] = 12062108,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120621/1E323B6E",
            },
        [12062108] = {
            ["Content"] = "不需要为我担心，我没事的。甚至恰恰相反，我现在感觉前所未有的好。",
            ["ContentFR"] = "Ne t’inquiète pas pour moi, tout va bien. En réalité, je me sens même mieux que jamais.",
            ["DialogueId"] = 12062108,
            ["GUID"] = "1E323B98",
            ["NextDialogue"] = 12062109,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120621/1E323B98",
            },
        [12062109] = {
            ["Content"] = "……你确定吗，苏乙？",
            ["ContentFR"] = "... Tu es sûre, Su Yi ?",
            ["DialogueId"] = 12062109,
            ["GUID"] = "1E323BC2",
            ["NextDialogue"] = 12062110,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120621/1E323BC2",
            },
        [12062110] = {
            ["Content"] = "嗯，因为我已经想明白了一些事情。",
            ["ContentFR"] = "Oui. Parce que j’ai compris certaines choses.",
            ["DialogueId"] = 12062110,
            ["GUID"] = "1E323BEC",
            ["NextDialogue"] = 12062111,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120621/1E323BEC",
            },
        [12062111] = {
            ["Content"] = "换做从前的我，或许会不甘心吧。我没有办法接受前人的理想，他们的抗争……就这么被歪曲成毫无来由的恶意。",
            ["ContentFR"] = "Autrefois, j’aurais sans doute ressenti de l’amertume. Je n’arrivais pas à accepter que les idéaux et les luttes de ceux qui nous ont précédés soient déformés et présentés comme une simple malveillance.",
            ["DialogueId"] = 12062111,
            ["GUID"] = "1E323C16",
            ["NextDialogue"] = 12062112,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120621/1E323C16",
            },
        [12062112] = {
            ["Content"] = "但现在我明白了，有些偏见不是能轻易化解的。如果那些人选择蒙蔽自己的双眼，固步自封，只听从心中仇恨的教唆，那他们被时代抛下也是难免的。对此我无能为力。",
            ["ContentFR"] = "Mais maintenant, je comprends. Certains préjugés ne disparaissent pas facilement. Si certains choisissent de fermer les yeux, de rester enfermés dans leurs certitudes et d’écouter uniquement la haine qui habite leur cœur, alors il est inévitable qu’ils soient un jour laissés derrière par leur époque. Et je n’y peux rien.",
            ["DialogueId"] = 12062112,
            ["GUID"] = "1E323C40",
            ["NextDialogue"] = 12062113,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120621/1E323C40",
            },
        [12062113] = {
            ["Content"] = "现在的我不再想着去改变别人了。我只需要战胜他们，证明自己就可以。",
            ["ContentFR"] = "Alors je ne cherche plus à changer les autres. Il me suffit de les vaincre... et de prouver ce que je vaux.",
            ["DialogueId"] = 12062113,
            ["GUID"] = "1E323C6A",
            ["NextDialogue"] = 12062114,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120621/1E323C6A",
            },
        [12062114] = {
            ["Content"] = "苏乙…………",
            ["ContentFR"] = "Su Yi...",
            ["DialogueId"] = 12062114,
            ["GUID"] = "1E323C94",
            ["NextDialogue"] = 12062115,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120621/1E323C94",
            },
        [12062115] = {
            ["Content"] = "{nickname}，你怎么一副担心的表情？说过啦，我没事的，笑一笑嘛。无论在什么逆境下都要放声笑出来，这是姑姑教过我的。",
            ["ContentFR"] = "Pourquoi cette tête inquiète, {nickname} ? Je t’ai dit que ça allait. Allez, souris un peu. Ma tante disait toujours que, peu importe l’adversité, il fallait rire en face.",
            ["DialogueId"] = 12062115,
            ["GUID"] = "1E323CBE",
            ["NextDialogue"] = 12062116,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120621/1E323CBE",
            },
        [12062116] = {
            ["Content"] = "（远处传来了什么东西破碎的声音。）",
            ["ContentFR"] = "Un bruit violent résonne au loin.",
            ["DialogueId"] = 12062116,
            ["GUID"] = "1E323CE8",
            ["NextDialogue"] = 12062117,
            ["VoiceName"] = "voice/$Locale$/story/1206/120621/1E323CE8",
            },
        [12062117] = {
            ["Content"] = "那边好像有什么动静……你可以帮我去看看吗？",
            ["ContentFR"] = "On dirait qu’il se passe quelque chose par là-bas... Tu peux aller voir ?",
            ["DialogueId"] = 12062117,
            ["GUID"] = "1E323D12",
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120621/1E323D12",
            },
        [12062118] = {
            ["Content"] = "咦，刚刚路过这里的时候，有这么多箱子吗……？",
            ["ContentFR"] = "Tiens... Quand je suis passé ici tout à l’heure, il y avait déjà autant de caisses... ?",
            ["DialogueId"] = 12062118,
            ["GUID"] = "1E323D3C",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120621/1E323D3C",
            },
        [12062201] = {
            ["Content"] = "别打了别打了——是我，是唐叔啊！",
            ["ContentFR"] = "Arrête, arrête de frapper — c’est moi ! C’est Oncle Tang !",
            ["DialogueId"] = 12062201,
            ["GUID"] = "1E324ADA",
            ["NextDialogue"] = 12062202,
            ["RelatedWikiId"] = {
                [1] = 203009,
                [2] = 103001,
                [3] = 203013,
                [4] = 203014,
                [5] = 408018,
                },
            ["SpeakNpcId"] = 250024,
            ["SpeakNpcName"] = "UI_Npc_Name_250024",
            ["VoiceName"] = "voice/$Locale$/story/1206/120622/1E324ADA",
            },
        [12062202] = {
            ["Content"] = "哎哟喂我这一把老腰。你们年轻人倒好，一言不合就动刀动枪的，差点把我闪着了。",
            ["ContentFR"] = "Aïe, mon pauvre dos... Vous les jeunes, vous sortez vos armes au moindre mouvement. Vous avez failli me casser en deux.",
            ["DialogueId"] = 12062202,
            ["GUID"] = "1E324B04",
            ["NextOptions"] = {
                [1] = 12062203,
                [2] = 12062204,
                },
            ["SpeakNpcId"] = 250024,
            ["SpeakNpcName"] = "UI_Npc_Name_250024",
            ["VoiceName"] = "voice/$Locale$/story/1206/120622/1E324B04",
            },
        [12062203] = {
            ["Content"] = "对不起，我不知道是你。",
            ["ContentFR"] = "<I>{性别:Désolé|Désolée}, je ne savais pas que c’était vous.</>",
            ["DialogueId"] = 12062203,
            ["GUID"] = "1E324B2E",
            ["ImprPlusId"] = 1202,
            ["NextDialogue"] = 12062205,
            },
        [12062204] = {
            ["Content"] = "不能怪我，只能怪你自己行踪可疑。",
            ["ContentFR"] = "<I>Ce n’est pas ma faute, c’est vous qui aviez l’air louche.</>",
            ["DialogueId"] = 12062204,
            ["GUID"] = "1E324B58",
            ["ImprPlusId"] = 1201,
            ["NextDialogue"] = 12062205,
            },
        [12062205] = {
            ["Content"] = "你为什么要大半夜的躲在这个……箱子里？",
            ["ContentFR"] = "Pourquoi vous cachez-vous dans... une caisse au beau milieu de la nuit ?",
            ["DialogueId"] = 12062205,
            ["GUID"] = "1E324B82",
            ["NextDialogue"] = 12062206,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120622/1E324B82",
            },
        [12062206] = {
            ["Content"] = "自然是担心我们小苏了！",
            ["ContentFR"] = "Parce que je m’inquiète pour notre petite Su, évidemment !",
            ["DialogueId"] = 12062206,
            ["GUID"] = "1E324BAC",
            ["NextDialogue"] = 12062207,
            ["SpeakNpcId"] = 250024,
            ["SpeakNpcName"] = "UI_Npc_Name_250024",
            ["VoiceName"] = "voice/$Locale$/story/1206/120622/1E324BAC",
            },
        [12062207] = {
            ["Content"] = "唉，孩子大了不中留，我要是进去啊，她肯定得嘴硬把我轰出来。所以我就只好在外面偷摸张望一下。",
            ["ContentFR"] = "Ah... les enfants grandissent trop vite, on ne peut pas les retenir. Si j’étais entré, elle aurait sûrement fait la fière et m’aurait mis dehors. Alors je me suis contenté de jeter un coup d’œil discrètement depuis l’extérieur.",
            ["DialogueId"] = 12062207,
            ["GUID"] = "1E324BD6",
            ["NextDialogue"] = 12062208,
            ["SpeakNpcId"] = 250024,
            ["SpeakNpcName"] = "UI_Npc_Name_250024",
            ["VoiceName"] = "voice/$Locale$/story/1206/120622/1E324BD6",
            },
        [12062208] = {
            ["Content"] = "小苏这次参加比赛也是，一声不吭就跑了出去。她这点心思山外山上下谁人不知啊，明明大家都能理解她，但她自己别扭，过意不去。",
            ["ContentFR"] = "C’est pareil pour cette compétition. Elle s’est inscrite et est partie sans dire un mot. Tout le monde aux Pics Extérieurs sait très bien ce qu’elle porte dans son cœur. On la comprend tous... mais elle, elle est trop sensible et elle se sent coupable.",
            ["DialogueId"] = 12062208,
            ["GUID"] = "1E324C00",
            ["NextDialogue"] = 12062209,
            ["SpeakNpcId"] = 250024,
            ["SpeakNpcName"] = "UI_Npc_Name_250024",
            ["VoiceName"] = "voice/$Locale$/story/1206/120622/1E324C00",
            },
        [12062209] = {
            ["Content"] = "这孩子，平时身上的包袱太重了，觉得自己不应当如此任性，所以瞒着大家谁也不说。",
            ["ContentFR"] = "Cette enfant porte toujours un poids trop lourd sur ses épaules. Elle pense qu’elle ne devrait pas se montrer aussi obstinée, alors elle n’en parle à personne et essaie de tout porter seule.",
            ["DialogueId"] = 12062209,
            ["GUID"] = "1E324C2A",
            ["NextDialogue"] = 12062210,
            ["SpeakNpcId"] = 250024,
            ["SpeakNpcName"] = "UI_Npc_Name_250024",
            ["VoiceName"] = "voice/$Locale$/story/1206/120622/1E324C2A",
            },
        [12062210] = {
            ["Content"] = "好在小苏遇着了你，有你和她组队，我这提着的心啊才算是放下了一点。对了，她刚刚和你说什么了？",
            ["ContentFR"] = "Heureusement qu’elle t’a rencontré. Savoir que tu fais équipe avec elle m’a enfin un peu rassuré. Au fait, qu’est-ce qu’elle t’a dit tout à l’heure ?",
            ["DialogueId"] = 12062210,
            ["GUID"] = "1E324C54",
            ["NextOptions"] = {
                [1] = 12062211,
                },
            ["SpeakNpcId"] = 250024,
            ["SpeakNpcName"] = "UI_Npc_Name_250024",
            ["VoiceName"] = "voice/$Locale$/story/1206/120622/1E324C54",
            },
        [12062211] = {
            ["Content"] = "转述和苏乙的聊天。",
            ["ContentFR"] = "<I>Raconter la conversation avec Su Yi</>",
            ["DialogueId"] = 12062211,
            ["GUID"] = "1E324C7E",
            ["NextDialogue"] = 12062212,
            },
        [12062212] = {
            ["Content"] = "她说自己“前所未有的好”？完了完了。",
            ["ContentFR"] = "Elle a dit qu’elle se sentait « mieux que jamais » ? Oh non... ça, ce n’est pas bon.",
            ["DialogueId"] = 12062212,
            ["GUID"] = "1E324CA8",
            ["NextDialogue"] = 12062213,
            ["SpeakNpcId"] = 250024,
            ["SpeakNpcName"] = "UI_Npc_Name_250024",
            ["VoiceName"] = "voice/$Locale$/story/1206/120622/1E324CA8",
            },
        [12062213] = {
            ["Content"] = "小苏这丫头我看着长大的，我太了解她了。她呀，越生气的时候，表面看起来反而越冷静。如果说“前所未有的好”，那得是气急了。",
            ["ContentFR"] = "Je l’ai vue grandir, cette gamine. Je la connais trop bien. Plus elle est en colère, plus elle paraît calme. Si elle dit qu’elle n’a « jamais été aussi bien », c’est qu’elle est furieuse.",
            ["DialogueId"] = 12062213,
            ["GUID"] = "1E324CD2",
            ["NextDialogue"] = 12062214,
            ["SpeakNpcId"] = 250024,
            ["SpeakNpcName"] = "UI_Npc_Name_250024",
            ["VoiceName"] = "voice/$Locale$/story/1206/120622/1E324CD2",
            },
        [12062214] = {
            ["Content"] = "她平时表现得很成熟可靠，常常让人忘了她还只是一个半大的姑娘呢。这丫头啊，遇上她姑姑的事就会表现得很不冷静。",
            ["ContentFR"] = "La plupart du temps, elle se montre si mature et fiable qu’on en oublie qu’elle n’est encore qu’une gamine. Mais quand il s’agit de sa tante... elle perd complètement son sang-froid.",
            ["DialogueId"] = 12062214,
            ["GUID"] = "1E324CFC",
            ["NextDialogue"] = 12062215,
            ["SpeakNpcId"] = 250024,
            ["SpeakNpcName"] = "UI_Npc_Name_250024",
            ["VoiceName"] = "voice/$Locale$/story/1206/120622/1E324CFC",
            },
        [12062215] = {
            ["Content"] = "对了，小苏有和你说过她姑姑苏暮鹧的事情吗？这前后的来龙去脉你了解多少？",
            ["ContentFR"] = "Au fait, Su Yi t’a déjà parlé de sa tante, Su Muzhe ? Tu sais ce qui s’est réellement passé ?",
            ["DialogueId"] = 12062215,
            ["GUID"] = "1E324D26",
            ["NextDialogue"] = 12062216,
            ["SpeakNpcId"] = 250024,
            ["SpeakNpcName"] = "UI_Npc_Name_250024",
            ["VoiceName"] = "voice/$Locale$/story/1206/120622/1E324D26",
            },
        [12062216] = {
            ["Content"] = "她说过，她的姑姑为了修一架叫做“灭蒙巨鸟”的水利机傀，冒险赶回城里，但是被应天尉当场诛杀了。",
            ["ContentFR"] = "Elle m’a dit que sa tante était revenue en ville pour réparer une méchapoupée hydraulique appelée « Grand Oiseau Miemeng », mais qu’elle avait été exécutée sur place par un Magistrat de Yingtian.",
            ["DialogueId"] = 12062216,
            ["GUID"] = "1E324D50",
            ["NextDialogue"] = 12062217,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120622/1E324D50",
            },
        [12062217] = {
            ["Content"] = "连这个都说了？看来她真的很信任你。",
            ["ContentFR"] = "Elle t’a raconté jusque-là... ? Alors elle doit vraiment te faire confiance.",
            ["DialogueId"] = 12062217,
            ["GUID"] = "1E324D7A",
            ["NextDialogue"] = 12062218,
            ["SpeakNpcId"] = 250024,
            ["SpeakNpcName"] = "UI_Npc_Name_250024",
            ["VoiceName"] = "voice/$Locale$/story/1206/120622/1E324D7A",
            },
        [12062218] = {
            ["Content"] = "当时消息传来时，我们便都知道这是个死局。但没人劝得住她，她却还是去了。",
            ["ContentFR"] = "Quand nous avons appris la nouvelle à l’époque, nous savions tous que c’était une situation sans issue. Mais personne n’a réussi à la convaincre de renoncer. Elle y est allée quand même.",
            ["DialogueId"] = 12062218,
            ["GUID"] = "1E324DA4",
            ["NextDialogue"] = 12062219,
            ["SpeakNpcId"] = 250024,
            ["SpeakNpcName"] = "UI_Npc_Name_250024",
            ["VoiceName"] = "voice/$Locale$/story/1206/120622/1E324DA4",
            },
        [12062219] = {
            ["Content"] = "那灭蒙巨鸟最终没被控制住，将那东郊砸了个稀巴烂，和她前半生的理想背道而驰。小苏一直释怀不下。",
            ["ContentFR"] = "Et au final, elle n’a pas réussi à maîtriser le Grand Oiseau Miemeng. Il est devenu incontrôlable et a ravagé tout le quartier est de la ville... en totale contradiction avec les idéaux qu’elle avait défendus toute sa vie. Su Yi n’a jamais réussi à tourner la page.",
            ["DialogueId"] = 12062219,
            ["GUID"] = "1E324DCE",
            ["NextDialogue"] = 12062220,
            ["SpeakNpcId"] = 250024,
            ["SpeakNpcName"] = "UI_Npc_Name_250024",
            ["VoiceName"] = "voice/$Locale$/story/1206/120622/1E324DCE",
            },
        [12062220] = {
            ["Content"] = "我们这些老家伙都快半截入土了，操心不了年轻人的爱恨纠葛。希望小苏有一天能想明白，人不能总被过去的仇恨束缚住，还是得向前看哟……",
            ["ContentFR"] = "Nous autres, les vieux, on a déjà un pied dans la tombe. On ne peut pas s’immiscer dans les rancœurs et les blessures des jeunes. J’espère seulement qu’un jour Su Yi comprendra qu’on ne peut pas rester prisonnier du passé éternellement. Il faut continuer d’avancer...",
            ["DialogueId"] = 12062220,
            ["GUID"] = "1E324DF8",
            ["NextDialogue"] = 12062221,
            ["SpeakNpcId"] = 250024,
            ["SpeakNpcName"] = "UI_Npc_Name_250024",
            ["VoiceName"] = "voice/$Locale$/story/1206/120622/1E324DF8",
            },
        [12062221] = {
            ["Content"] = "（远处传来了什么东西破碎的声音。）",
            ["ContentFR"] = "Un nouveau fracas retentit au loin.",
            ["DialogueId"] = 12062221,
            ["GUID"] = "1E324E22",
            ["NextDialogue"] = 12062222,
            ["VoiceName"] = "voice/$Locale$/story/1206/120622/1E324E22",
            },
        [12062222] = {
            ["Content"] = "哇！什么动静？！",
            ["ContentFR"] = "Ouah ! C’était quoi, ça ?!",
            ["DialogueId"] = 12062222,
            ["GUID"] = "1E324E4C",
            ["NextDialogue"] = 12062223,
            ["SpeakNpcId"] = 250024,
            ["SpeakNpcName"] = "UI_Npc_Name_250024",
            ["VoiceName"] = "voice/$Locale$/story/1206/120622/1E324E4C",
            },
        [12062223] = {
            ["Content"] = "我刚刚追着这个声音出来，唐叔，这原来不是你弄出来的响动吗？",
            ["ContentFR"] = "Je suivais justement ce bruit. Ce n’était pas vous, Oncle Tang ?",
            ["DialogueId"] = 12062223,
            ["GUID"] = "1E324E76",
            ["NextDialogue"] = 12062224,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120622/1E324E76",
            },
        [12062224] = {
            ["Content"] = "我唐叔再不小心，也不会一下碰倒这么多东西，这声音不太寻常。听这动静，好像是从山外山入口处传来的。",
            ["ContentFR"] = "Même si je suis maladroit, je ne pourrais pas renverser autant de choses d’un coup. Ce bruit est étrange. On dirait que ça vient de l’entrée des Pics Extérieurs.",
            ["DialogueId"] = 12062224,
            ["GUID"] = "1E324EA0",
            ["NextDialogue"] = 12062225,
            ["SpeakNpcId"] = 250024,
            ["SpeakNpcName"] = "UI_Npc_Name_250024",
            ["VoiceName"] = "voice/$Locale$/story/1206/120622/1E324EA0",
            },
        [12062225] = {
            ["Content"] = "我知道了。晚上天凉，你早点回去歇着吧，我去看看就好。",
            ["ContentFR"] = "D’accord. La nuit est froide — vous devriez rentrer vous reposer. Je vais aller voir.",
            ["DialogueId"] = 12062225,
            ["GUID"] = "1E324ECA",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120622/1E324ECA",
            },
        [12062226] = {
            ["Content"] = "别打了别打了——是我，是唐叔啊！",
            ["DialogueId"] = 12062226,
            ["GUID"] = "1E324ECB",
            ["SpeakNpcId"] = 250024,
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["VoiceName"] = "voice/$Locale$/story/1206/120622/1E324ADA",
            },
        [12062301] = {
            ["Content"] = "………………",
            ["ContentFR"] = "...",
            ["DialogueId"] = 12062301,
            ["GUID"] = "1E325B42",
            ["NextDialogue"] = 12062302,
            ["RelatedWikiId"] = {
                [1] = 203004,
                [2] = 203009,
                [3] = 103001,
                [4] = 203013,
                [5] = 203014,
                [6] = 408018,
                },
            ["SpeakNpcId"] = 250005,
            ["VoiceName"] = "voice/$Locale$/story/1206/120623/1E325B42",
            },
        [12062302] = {
            ["Content"] = "好啊。上次钧天铁卫袭来之后，我就多长了个心眼，升级了警报装置。瞧瞧这逮住的是谁，真稀罕啊。",
            ["ContentFR"] = "Eh bien. Depuis la dernière fois que les Sentinelles de Fer de Juntian sont venues semer le trouble, j’ai pris quelques précautions et amélioré le système d’alarme. Et regarde donc qui nous avons attrapé... Voilà qui est rare.",
            ["DialogueId"] = 12062302,
            ["GUID"] = "1E325B6C",
            ["NextDialogue"] = 12062303,
            ["SpeakNpcId"] = 240052,
            ["VoiceName"] = "voice/$Locale$/story/1206/120623/1E325B6C",
            },
        [12062303] = {
            ["Content"] = "……我并非以应天尉之身前来。只是有要事需要告知苏乙和{nickname}两位，说完事了就走，绝不多叨扰。",
            ["ContentFR"] = "... Je ne suis pas venu ici en tant que Magistrat de Yingtian. J’ai simplement des informations urgentes à transmettre à Su Yi et à {nickname}. Une fois cela fait, je partirai immédiatement. Je ne vous causerai aucun trouble.",
            ["DialogueId"] = 12062303,
            ["GUID"] = "1E325B96",
            ["NextDialogue"] = 12062304,
            ["SpeakNpcId"] = 250005,
            ["VoiceName"] = "voice/$Locale$/story/1206/120623/1E325B96",
            },
        [12062304] = {
            ["Content"] = "你以为这山外山是你家后院，你想来就来，想走就走？",
            ["ContentFR"] = "Tu crois que les Pics Extérieurs sont ton jardin personnel ? Que tu peux entrer et sortir comme bon te semble ?",
            ["DialogueId"] = 12062304,
            ["GUID"] = "1E325BC0",
            ["NextDialogue"] = 12062305,
            ["SpeakNpcId"] = 240052,
            ["VoiceName"] = "voice/$Locale$/story/1206/120623/1E325BC0",
            },
        [12062305] = {
            ["Content"] = "闹了那么大的风波还能装作若无其事。你与其征询我的意见，不如先问问你死去的师父和师妹的在天之灵同不同意！",
            ["ContentFR"] = "Après tout le chaos que tu as provoqué, tu oses revenir comme si de rien n’était. Au lieu de me demander mon avis, tu ferais mieux de demander à ton maître et à ta cadette disparus s’ils l’approuvent !",
            ["DialogueId"] = 12062305,
            ["GUID"] = "1E325BEA",
            ["NextDialogue"] = 12062306,
            ["SpeakNpcId"] = 240052,
            ["VoiceName"] = "voice/$Locale$/story/1206/120623/1E325BEA",
            },
        [12062306] = {
            ["Content"] = "——我替他们同意了。",
            ["ContentFR"] = "Alors je réponds oui à leur place.",
            ["DialogueId"] = 12062306,
            ["GUID"] = "1E325C14",
            ["NextDialogue"] = 12062307,
            ["SpeakNpcId"] = 250002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120623/1E325C14",
            },
        [12062307] = {
            ["Content"] = "……你！",
            ["ContentFR"] = "... Toi !",
            ["DialogueId"] = 12062307,
            ["GUID"] = "1E325C3E",
            ["NextDialogue"] = 12062308,
            ["SpeakNpcId"] = 240052,
            ["VoiceName"] = "voice/$Locale$/story/1206/120623/1E325C3E",
            },
        [12062308] = {
            ["Content"] = "怎么，你觉得我说话不好使吗？要不这样好了，你去师父他老人家坟前上柱香，问问他的意见。要是他老人家吹胡子瞪眼睛从坟里面跳出来阻止，那我听你的。",
            ["ContentFR"] = "Quoi ? Tu trouves que mon avis ne vaut rien ? Dans ce cas, va brûler un bâton d’encens sur la tombe de notre maître et demande-lui directement. S’il sort de sa tombe en fulminant pour t’arrêter, très bien. On fera comme tu dis.",
            ["DialogueId"] = 12062308,
            ["GUID"] = "1E325C68",
            ["NextDialogue"] = 12062309,
            ["SpeakNpcId"] = 250002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120623/1E325C68",
            },
        [12062309] = {
            ["Content"] = "但要是那坟前静悄悄的没动静，我看就不如省了这功夫，我们前尘往事，一笔勾销，如何？",
            ["ContentFR"] = "Mais si la tombe reste bien tranquille... alors autant éviter ces simagrées. On efface le passé et on repart à zéro. Qu’en dis-tu ?",
            ["DialogueId"] = 12062309,
            ["GUID"] = "1E325C92",
            ["NextDialogue"] = 12062310,
            ["SpeakNpcId"] = 250002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120623/1E325C92",
            },
        [12062310] = {
            ["Content"] = "……哼。你想袒护他，那就遂了你的意吧。但要是闹出什么事来，少不了你的好果子吃！",
            ["ContentFR"] = "... <I>Hmpf.</> Si tu tiens tant à le couvrir, très bien. Mais si quelque chose tourne mal, tu en paieras les conséquences !",
            ["DialogueId"] = 12062310,
            ["GUID"] = "1E325CBC",
            ["NextDialogue"] = 12062311,
            ["SpeakNpcId"] = 240052,
            ["VoiceName"] = "voice/$Locale$/story/1206/120623/1E325CBC",
            },
        [12062311] = {
            ["Content"] = "……刻舟，多谢你解围。",
            ["ContentFR"] = "... Kezhou. Merci pour ton intervention.",
            ["DialogueId"] = 12062311,
            ["GUID"] = "1E325CE6",
            ["NextDialogue"] = 12062312,
            ["SpeakNpcId"] = 250005,
            ["VoiceName"] = "voice/$Locale$/story/1206/120623/1E325CE6",
            },
        [12062312] = {
            ["Content"] = "你这话说的，我们师兄弟之间，哪有什么谢来谢去的！倒是师兄你……你终于愿意回来看看了！",
            ["ContentFR"] = "Allons, entre frères d’armes, pas besoin de se remercier sans arrêt. Mais dis donc, Yuming... te voilà enfin revenu faire un tour ici !",
            ["DialogueId"] = 12062312,
            ["GUID"] = "1E325D10",
            ["NextDialogue"] = 12062313,
            ["SpeakNpcId"] = 250002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120623/1E325D10",
            },
        [12062313] = {
            ["Content"] = "煜明，分开时不是约好了明早在赛场见吗。你怎么赶来山外山了？发生了什么事吗？",
            ["ContentFR"] = "Yuming, nous n’avions pas convenu de nous retrouver demain matin à l’arène ? Pourquoi es-tu venu jusqu’aux Pics Extérieurs à cette heure-ci ? Il s’est passé quelque chose ?",
            ["DialogueId"] = 12062313,
            ["GUID"] = "1E325D3A",
            ["NextDialogue"] = 12062314,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120623/1E325D3A",
            },
        [12062314] = {
            ["Content"] = "被你不幸言中了。",
            ["ContentFR"] = "Malheureusement, ta crainte était fondée.",
            ["DialogueId"] = 12062314,
            ["GUID"] = "1E325D64",
            ["NextDialogue"] = 12062315,
            ["SpeakNpcId"] = 250005,
            ["VoiceName"] = "voice/$Locale$/story/1206/120623/1E325D64",
            },
        [12062315] = {
            ["DialogueId"] = 12062315,
            ["GUID"] = "1E325D8E",
            ["NextDialogue"] = 12062316,
            ["VoiceName"] = "voice/$Locale$/story/1206/120623/1E325D8E",
            },
        [12062316] = {
            ["Content"] = "这是……青鸾贰型！怎么坏成这样了？",
            ["ContentFR"] = "C’est... le Qingluan Type II ! Comment a-t-il pu être abîmé à ce point ?",
            ["DialogueId"] = 12062316,
            ["GUID"] = "1E325DB8",
            ["NextDialogue"] = 12062317,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120623/1E325DB8",
            },
        [12062317] = {
            ["Content"] = "白日的事端之后，需接受检查的青鸾贰型暂存在赛场库房中。半夜有贼人入侵，将其破坏。",
            ["ContentFR"] = "Après l’incident de la journée, le Qingluan Type II avait été placé dans l’entrepôt de l’arène pour inspection. Quelqu’un s’y est introduit cette nuit et l’a saboté.",
            ["DialogueId"] = 12062317,
            ["GUID"] = "1E325DE2",
            ["NextDialogue"] = 12062318,
            ["SpeakNpcId"] = 250005,
            ["VoiceName"] = "voice/$Locale$/story/1206/120623/1E325DE2",
            },
        [12062318] = {
            ["Content"] = "如今大风九章改制，新的律法尚未定下，狴犴凭兽性行事，由它们贸然执行旧日刑罚恐再生祸乱。故而太皓暂时召回了狴犴，仅由应天尉代为执法，才让这些人钻了空子。",
            ["ContentFR"] = "Les Neuf Chapitres de Dafeng sont en pleine réforme, et les nouvelles lois ne sont pas encore établies. Les Bi’an agissent selon leur instinct ; les laisser appliquer les anciennes sentences risquerait d’aggraver le chaos. Taihao les a donc temporairement rappelés, laissant l’application de la loi aux seuls Magistrats de Yingtian. Certains en ont profité.",
            ["DialogueId"] = 12062318,
            ["GUID"] = "1E325E0C",
            ["NextDialogue"] = 12062319,
            ["SpeakNpcId"] = 250005,
            ["VoiceName"] = "voice/$Locale$/story/1206/120623/1E325E0C",
            },
        [12062319] = {
            ["Content"] = "库房原不是什么要地。感知到案件发生后，我循着动静去追。却是迟了一步，让贼人逃了。",
            ["ContentFR"] = "L’entrepôt n’était pas considéré comme un lieu sensible, la surveillance y était donc légère. Lorsque j’ai senti qu’il se passait quelque chose, j’ai suivi le bruit pour poursuivre l’intrus... mais il était trop tard. Il s’est échappé.",
            ["DialogueId"] = 12062319,
            ["GUID"] = "1E325E36",
            ["NextDialogue"] = 12062320,
            ["SpeakNpcId"] = 250005,
            ["VoiceName"] = "voice/$Locale$/story/1206/120623/1E325E36",
            },
        [12062320] = {
            ["Content"] = "糟了糟了，我那姑奶奶知道一定会伤心异常的，她最宝贵这些玩意儿了。",
            ["ContentFR"] = "Aïe... ça, c’est mauvais. Très mauvais. Si ma chère tante apprend ça, elle sera dévastée. Elle tient à ces oiseaux mécaniques comme à la prunelle de ses yeux.",
            ["DialogueId"] = 12062320,
            ["GUID"] = "1E325E60",
            ["NextDialogue"] = 12062321,
            ["SpeakNpcId"] = 250002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120623/1E325E60",
            },
        [12062321] = {
            ["Content"] = "你们明天还得继续比赛呢，万一影响了心态怎么办？要我说，找个借口，让我刻舟背个黑锅得了。就说我耍剑时不小心，把它戳了个稀巴烂。",
            ["ContentFR"] = "Et vous avez encore des matchs demain ! Si ça lui reste en tête, ça pourrait la perturber. Tiens, j’ai une idée : inventons une excuse et je porterai le chapeau. On dira que je m’entraînais à l’épée et que je l’ai accidentellement transpercé.",
            ["DialogueId"] = 12062321,
            ["GUID"] = "1E325E8A",
            ["NextDialogue"] = 12062322,
            ["SpeakNpcId"] = 250002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120623/1E325E8A",
            },
        [12062322] = {
            ["Content"] = "……以谎圆谎，怕是不妥。",
            ["ContentFR"] = "... Mentir pour couvrir un mensonge ne me semble pas approprié.",
            ["DialogueId"] = 12062322,
            ["GUID"] = "1E325EB4",
            ["NextDialogue"] = 12062323,
            ["SpeakNpcId"] = 250005,
            ["VoiceName"] = "voice/$Locale$/story/1206/120623/1E325EB4",
            },
        [12062323] = {
            ["Content"] = "哎呀师兄你放心，俗话说得好，债多不压身嘛。反正惹她生气了这么多次，也不差这一回。",
            ["ContentFR"] = "Allons, Yuming, ne t’inquiète pas. Comme on dit : quand on a déjà beaucoup de dettes, une de plus ou de moins ne change rien. De toute façon, je l’ai déjà mise en colère tellement de fois... une fois de plus ne fera pas de différence.",
            ["DialogueId"] = 12062323,
            ["GUID"] = "1E325EDE",
            ["NextDialogue"] = 12062324,
            ["SpeakNpcId"] = 250002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120623/1E325EDE",
            },
        [12062324] = {
            ["Content"] = "没有那个必要。",
            ["ContentFR"] = "Ce ne sera pas nécessaire.",
            ["DialogueId"] = 12062324,
            ["GUID"] = "1E325F08",
            ["NextDialogue"] = 12062325,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120623/1E325F08",
            },
        [12062325] = {
            ["Content"] = "苏乙……你都听见了吗？",
            ["ContentFR"] = "Su Yi... tu as tout entendu ?",
            ["DialogueId"] = 12062325,
            ["GUID"] = "1E325F32",
            ["NextDialogue"] = 12062326,
            ["SpeakNpcId"] = 250005,
            ["VoiceName"] = "voice/$Locale$/story/1206/120623/1E325F32",
            },
        [12062326] = {
            ["Content"] = "你们这么吵，想不注意到都难。",
            ["ContentFR"] = "Vous étiez suffisamment bruyants pour que je n’aie aucun mal à comprendre.",
            ["DialogueId"] = 12062326,
            ["GUID"] = "1E325F5C",
            ["NextDialogue"] = 12062327,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120623/1E325F5C",
            },
        [12062327] = {
            ["Content"] = "想来是白天那伙人干的吧，以为这样就能让我打退堂鼓。",
            ["ContentFR"] = "J’imagine que ce sont les gens de tout à l’heure. Ils pensaient sans doute que cela suffirait à me faire renoncer.",
            ["DialogueId"] = 12062327,
            ["GUID"] = "1E325F86",
            ["NextDialogue"] = 12062328,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120623/1E325F86",
            },
        [12062328] = {
            ["Content"] = "他们没有料到的是，我早已打算把青鸾贰型拆装重组成更强大的机体。他们潜入破坏反而省了我这个功夫。",
            ["ContentFR"] = "Ce qu’ils ignorent, c’est que j’avais déjà l’intention de démonter entièrement le Qingluan Type II pour en reconstruire une version plus puissante. Leur sabotage m’a simplement évité de devoir le démonter moi-même.",
            ["DialogueId"] = 12062328,
            ["GUID"] = "1E325FB0",
            ["NextDialogue"] = 12062329,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120623/1E325FB0",
            },
        [12062329] = {
            ["Content"] = "在足够强的实力面前，什么伎俩都会不攻自破。",
            ["ContentFR"] = "Face à une puissance suffisante, tous ces stratagèmes tombent d’eux-mêmes.",
            ["DialogueId"] = 12062329,
            ["GUID"] = "1E325FDA",
            ["NextDialogue"] = 12062330,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120623/1E325FDA",
            },
        [12062330] = {
            ["Content"] = "苏乙……",
            ["ContentFR"] = "Su Yi...",
            ["DialogueId"] = 12062330,
            ["GUID"] = "1E326004",
            ["NextDialogue"] = 12062331,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120623/1E326004",
            },
        [12062331] = {
            ["Content"] = "好了，我要彻夜改装青鸾贰型了，你们也早点休息吧。晚安。",
            ["ContentFR"] = "Bien. Je vais passer la nuit à reconstruire le Qingluan Type II. Vous devriez aller vous reposer. Bonne nuit.",
            ["DialogueId"] = 12062331,
            ["GUID"] = "1E32602E",
            ["NextDialogue"] = 12062332,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120623/1E32602E",
            },
        [12062332] = {
            ["Content"] = "喂喂，姑奶奶这发言，好像不太对劲啊……！你们白天到底都经历了什么？",
            ["ContentFR"] = "Hé... vous avez entendu ça ? Ma chère tante n’a pas l’air dans son état normal... Qu’est-ce qui s’est passé aujourd’hui, au juste ?",
            ["DialogueId"] = 12062332,
            ["GUID"] = "1E326058",
            ["NextOptions"] = {
                [1] = 12062333,
                },
            ["SpeakNpcId"] = 250002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120623/1E326058",
            },
        [12062333] = {
            ["Content"] = "转述白天的遭遇。",
            ["ContentFR"] = "<I>Raconter les événements de la journée</>",
            ["DialogueId"] = 12062333,
            ["GUID"] = "1E326082",
            ["NextDialogue"] = 12062334,
            },
        [12062334] = {
            ["Content"] = "也难怪姑奶奶这样……",
            ["ContentFR"] = "Je comprends mieux pourquoi elle est dans cet état...",
            ["DialogueId"] = 12062334,
            ["GUID"] = "1E3260AC",
            ["NextDialogue"] = 12062335,
            ["SpeakNpcId"] = 250002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120623/1E3260AC",
            },
        [12062335] = {
            ["Content"] = "体悟不能由旁人代劳，必须她自己做出。此时旁人再做劝说也是徒劳。",
            ["ContentFR"] = "Certaines prises de conscience ne peuvent venir que d’elle-même. Personne ne peut les faire à sa place. Dans ces conditions, tenter de la raisonner maintenant serait inutile.",
            ["DialogueId"] = 12062335,
            ["GUID"] = "1E3260D6",
            ["NextDialogue"] = 12062336,
            ["SpeakNpcId"] = 250005,
            ["VoiceName"] = "voice/$Locale$/story/1206/120623/1E3260D6",
            },
        [12062336] = {
            ["Content"] = "以他们的不依不挠，破坏青鸾贰型恐怕并非终点。我会继续追查此事，{nickname}，你也需多加小心。",
            ["ContentFR"] = "Au vu de leur obstination, la destruction du Qingluan Type II n’est probablement pas la fin de l’histoire. Je vais poursuivre l’enquête. {nickname}, tu devrais toi aussi rester sur tes gardes.",
            ["DialogueId"] = 12062336,
            ["GUID"] = "1E326100",
            ["NextDialogue"] = 12062337,
            ["SpeakNpcId"] = 250005,
            ["VoiceName"] = "voice/$Locale$/story/1206/120623/1E326100",
            },
        [12062337] = {
            ["Content"] = "好，我也会把这件事告诉止流，让他们提高警惕。",
            ["ContentFR"] = "D’accord. Je vais également prévenir Zhiliu afin qu’ils redoublent de vigilance.",
            ["DialogueId"] = 12062337,
            ["GUID"] = "1E32612A",
            ["NextDialogue"] = 12062338,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120623/1E32612A",
            },
        [12062338] = {
            ["Content"] = "嗯，目前情报欠缺。只能见机行事，后发制人了。",
            ["ContentFR"] = "Hm. Nous manquons encore d’informations. Il faudra observer la situation et agir au moment opportun.",
            ["DialogueId"] = 12062338,
            ["GUID"] = "1E326154",
            ["NextDialogue"] = 12062339,
            ["SpeakNpcId"] = 250005,
            ["VoiceName"] = "voice/$Locale$/story/1206/120623/1E326154",
            },
        [12062339] = {
            ["Content"] = "{nickname}，今日多有操劳。你先回去休息，为明日的赛事养精蓄锐吧。",
            ["ContentFR"] = "{nickname}, tu as déjà beaucoup donné aujourd’hui. Va te reposer et économise tes forces pour les épreuves de demain.",
            ["DialogueId"] = 12062339,
            ["GUID"] = "1E32617E",
            ["SpeakNpcId"] = 250005,
            ["VoiceName"] = "voice/$Locale$/story/1206/120623/1E32617E",
            },
        [12062340] = {
            ["Content"] = "师兄，你终于愿意回来看看了！",
            ["ContentFR"] = "Yuming, te voilà enfin revenu nous rendre visite !",
            ["DialogueId"] = 12062340,
            ["GUID"] = "1E3261A8",
            ["NextDialogue"] = 12062341,
            ["SpeakNpcId"] = 250002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120623/1E3261A8",
            },
        [12062341] = {
            ["Content"] = "……只是此次群英试受人所托，不好半途而废。赛场上遭此变故，于情于理我都该陪着{nickname}与苏乙二位走完全程。",
            ["ContentFR"] = "... On m’a demandé d’assister à ce Tournoi de l’Encens. Je ne peux pas abandonner en cours de route. Après ce qui s’est passé à l’arène, il est de mon devoir d’accompagner {nickname} et Su Yi jusqu’au bout.",
            ["DialogueId"] = 12062341,
            ["GUID"] = "1E3261D2",
            ["NextDialogue"] = 12062342,
            ["SpeakNpcId"] = 250005,
            ["VoiceName"] = "voice/$Locale$/story/1206/120623/1E3261D2",
            },
        [12062342] = {
            ["Content"] = "有些话不好意思直接说出口是吧，我懂，我懂～是我不该这样问，我自罚一杯！",
            ["ContentFR"] = "Certaines choses sont difficiles à dire directement, pas vrai ? Je comprends, je comprends~ C’est moi qui ai été maladroit en posant la question. Je m’en punirai avec un verre !",
            ["DialogueId"] = 12062342,
            ["GUID"] = "1E3261FC",
            ["NextDialogue"] = 12062343,
            ["SpeakNpcId"] = 250002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120623/1E3261FC",
            },
        [12062343] = {
            ["Content"] = "师兄，我和你说啊，昨天我在山外山附近看到一只大红狐狸窜过去，嗬，那一身毛啊，油光水滑的！你说，它会不会就是咱们一起养过的小橙子？",
            ["ContentFR"] = "Dis donc, Yuming. Hier, près des Pics Extérieurs, j’ai vu passer un grand renard roux. Ah, son pelage était magnifique, tout lisse et brillant ! Tu crois que ça pourrait être Juju ? Celui qu’on nourrissait autrefois ?",
            ["DialogueId"] = 12062343,
            ["GUID"] = "1E326226",
            ["NextDialogue"] = 12062344,
            ["SpeakNpcId"] = 250002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120623/1E326226",
            },
        [12062344] = {
            ["Content"] = "还有啊，我和你说。上个月我睡得正熟呢，突然闪过一阵惊雷，恰好劈到我们一起练剑过的那片竹林上，你说邪不邪门？",
            ["ContentFR"] = "Et écoute ça : le mois dernier, j’étais profondément endormi quand un éclair a frappé en plein milieu de la bambouseraie où nous nous entraînions à l’épée. Tu ne trouves pas ça étrange ?",
            ["DialogueId"] = 12062344,
            ["GUID"] = "1E326250",
            ["NextDialogue"] = 12062345,
            ["SpeakNpcId"] = 250002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120623/1E326250",
            },
        [12062345] = {
            ["Content"] = "竹子被劈倒后，反而周围的花啊草啊都更茂盛了。那雷劈到竹子上的焦痕还在呢。来来来，我现在就带你去看看！",
            ["ContentFR"] = "Après que les bambous ont été frappés, les fleurs et l’herbe autour ont poussé encore plus abondamment. La trace de brûlure est toujours visible. Allez, viens ! Je vais te montrer ça !",
            ["DialogueId"] = 12062345,
            ["GUID"] = "1E32627A",
            ["NextDialogue"] = 12062346,
            ["SpeakNpcId"] = 250002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120623/1E32627A",
            },
        [12062346] = {
            ["Content"] = "………………",
            ["ContentFR"] = "...",
            ["DialogueId"] = 12062346,
            ["GUID"] = "1E3262A4",
            ["RelatedWikiId"] = {
                [1] = 203007,
                },
            ["SpeakNpcId"] = 250005,
            ["VoiceName"] = "voice/$Locale$/story/1206/120623/1E3262A4",
            },
        [12062347] = {
            ["Content"] = "翌日清晨，奉香群英试报名点处……",
            ["DialogueId"] = 12062347,
            ["GUID"] = "1E3262A5",
            ["IsBlack"] = 1,
            ["VoiceName"] = "voice/$Locale$/story/1206/120623/1E3262A5",
            },
        [12062401] = {
            ["Content"] = "早上好。哈——好困。",
            ["ContentFR"] = "Bonjour... Ha— je suis épuisée.",
            ["DialogueId"] = 12062401,
            ["GUID"] = "1E326BAA",
            ["NextDialogue"] = 12062402,
            ["RelatedWikiId"] = {
                [1] = 203009,
                [2] = 103001,
                [3] = 203013,
                [4] = 203014,
                [5] = 408018,
                },
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120624/1E326BAA",
            },
        [12062402] = {
            ["Content"] = "苏乙……你还好吗？你的黑眼圈看起来好重！",
            ["ContentFR"] = "Su Yi... ça va ? Tu as des cernes énormes !",
            ["DialogueId"] = 12062402,
            ["GUID"] = "1E326BD4",
            ["NextDialogue"] = 12062403,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120624/1E326BD4",
            },
        [12062403] = {
            ["Content"] = "不过是为了改造青鸾贰型一夜没睡。放心，熬夜对于机傀师来说只是稀松平常的小事。",
            ["ContentFR"] = "Je n’ai simplement pas dormi de la nuit pour modifier le Qingluan Type II. Ne t’inquiète pas, passer une nuit blanche est presque banal pour un maître des méchapoupées.",
            ["DialogueId"] = 12062403,
            ["GUID"] = "1E326BFE",
            ["NextDialogue"] = 12062404,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120624/1E326BFE",
            },
        [12062404] = {
            ["Content"] = "比起这个，重要的是青鸾贰型的性能已经全面升级完毕……",
            ["ContentFR"] = "Mais le plus important, c’est que les performances du Qingluan Type II ont été entièrement améliorées...",
            ["DialogueId"] = 12062404,
            ["GUID"] = "1E326C28",
            ["NextDialogue"] = 12062433,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120624/1E326C28",
            },
        [12062405] = {
            ["Content"] = "塔比瑟？！你怎么来了？",
            ["ContentFR"] = "Tabethe ?! Qu’est-ce que tu fais ici ?",
            ["DialogueId"] = 12062405,
            ["GUID"] = "1E326C52",
            ["NextDialogue"] = 12062406,
            ["RelatedWikiId"] = {
                [1] = 201029,
                },
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120624/1E326C52",
            },
        [12062406] = {
            ["Content"] = "哼哼哼，怎么样？吓了一跳吧！",
            ["ContentFR"] = "Hihi... Alors ? Je vous ai bien fait peur, non ?",
            ["DialogueId"] = 12062406,
            ["GUID"] = "1E326C7C",
            ["NextDialogue"] = 12062407,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120624/1E326C7C",
            },
        [12062407] = {
            ["Content"] = "没想到，总是趾高气扬的苏乙妈妈竟然连这点小计俩都没躲过，难不成是没睡醒？",
            ["ContentFR"] = "Je ne pensais pas que la grande Su Yi, si fière d’elle, tomberait dans un piège aussi basique. Tu es encore à moitié endormie, ou quoi ?",
            ["DialogueId"] = 12062407,
            ["GUID"] = "1E326CA6",
            ["NextDialogue"] = 12062408,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120624/1E326CA6",
            },
        [12062408] = {
            ["Content"] = "你你你，你怎么在这儿，上场比赛你怎么突然失踪了！",
            ["ContentFR"] = "T-Toi ! Qu’est-ce que tu fais là ? Et où est-ce que tu étais passée pendant la dernière manche ? On t’a cherché partout !",
            ["DialogueId"] = 12062408,
            ["GUID"] = "1E326CD0",
            ["NextDialogue"] = 12062409,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120624/1E326CD0",
            },
        [12062409] = {
            ["Content"] = "可别提了……有个小吃摊老板搞什么“地狱辣挑战”，说是挑战成功就能拿到豪华大礼，我想着光是辣能辣到哪里去嘛。",
            ["ContentFR"] = "Ne m’en parle pas... Il y avait un stand de nourriture qui proposait un « défi piment infernal ». Le patron disait que si on réussissait, on remportait un gros lot. Je me suis dit : bon, des piments, ça ne peut pas être si terrible.",
            ["DialogueId"] = 12062409,
            ["GUID"] = "1E326CFA",
            ["NextDialogue"] = 12062410,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120624/1E326CFA",
            },
        [12062410] = {
            ["Content"] = "结果吃了一半，吃得我鼻涕连泪一起流，肚子里像火烧一样，半天才缓过来。我再也不敢小瞧华胥的辣椒了……",
            ["ContentFR"] = "À mi-parcours, j’avais les larmes et le nez qui coulaient, et le ventre en feu. J’ai mis un temps fou à m’en remettre. Je ne sous-estimerai plus jamais les piments de Huaxu...",
            ["DialogueId"] = 12062410,
            ["GUID"] = "1E326D24",
            ["NextDialogue"] = 12062411,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120624/1E326D24",
            },
        [12062411] = {
            ["Content"] = "你你你，原来就因为这种事情……",
            ["ContentFR"] = "Q-Quoi ?! Tout ça juste pour une histoire de nourriture ?",
            ["DialogueId"] = 12062411,
            ["GUID"] = "1E326D4E",
            ["NextDialogue"] = 12062412,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120624/1E326D4E",
            },
        [12062412] = {
            ["Content"] = "还说我，你们也没多讲义气嘛，居然直接就抛下我和这个一身黑像乌鸦一样的怪家伙混在一起了！",
            ["ContentFR"] = "Et vous osez me faire la leçon ? Vous m’avez bien abandonnée sans hésiter pour traîner avec ce type tout en noir qui ressemble à un corbeau !",
            ["DialogueId"] = 12062412,
            ["GUID"] = "1E326D78",
            ["NextDialogue"] = 12062413,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120624/1E326D78",
            },
        [12062413] = {
            ["Content"] = "所以！作为抛下队友的惩罚，今天我要为你对面的队伍摇旗呐喊~歪歪歪！",
            ["ContentFR"] = "Alors voilà ! Pour vous punir d’avoir laissé tomber votre coéquipière, aujourd’hui je vais encourager l’équipe d’en face ! Allez, allez !",
            ["DialogueId"] = 12062413,
            ["GUID"] = "1E326DA2",
            ["NextDialogue"] = 12062414,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120624/1E326DA2",
            },
        [12062414] = {
            ["Content"] = "明明是你自己吃坏肚子，怎么还赖在我们头上！",
            ["ContentFR"] = "Mais c’est toi qui t’es rendu malade toute seule ! Pourquoi ce serait de notre faute ?",
            ["DialogueId"] = 12062414,
            ["GUID"] = "1E326DCC",
            ["NextDialogue"] = 12062415,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120624/1E326DCC",
            },
        [12062415] = {
            ["Content"] = "……够了。",
            ["ContentFR"] = "... Ça suffit.",
            ["DialogueId"] = 12062415,
            ["GUID"] = "1E326DF6",
            ["NextDialogue"] = 12062416,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120624/1E326DF6",
            },
        [12062416] = {
            ["Content"] = "苏乙？",
            ["ContentFR"] = "Su Yi ?",
            ["DialogueId"] = 12062416,
            ["GUID"] = "1E326E20",
            ["NextDialogue"] = 12062417,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120624/1E326E20",
            },
        [12062417] = {
            ["Content"] = "没什么好争执的。",
            ["ContentFR"] = "Il n’y a rien à discuter.",
            ["DialogueId"] = 12062417,
            ["GUID"] = "1E326E4A",
            ["NextDialogue"] = 12062418,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120624/1E326E4A",
            },
        [12062418] = {
            ["Content"] = "与其和没必要的人浪费时间，不如用实力向所有人证明自己。走吧，比赛要开始了。",
            ["ContentFR"] = "Plutôt que de perdre du temps avec des gens qui n’en valent pas la peine, je préfère prouver ce que je vaux par mes résultats. Allons-y. La manche va commencer.",
            ["DialogueId"] = 12062418,
            ["GUID"] = "1E326E74",
            ["NextDialogue"] = 12062419,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120624/1E326E74",
            },
        [12062419] = {
            ["Content"] = "谁是没必要的人呀，你回来——喂，给我说清楚！",
            ["ContentFR"] = "« Des gens qui n’en valent pas la peine » ? De qui tu parles ? Hé, reviens ! Explique-toi !",
            ["DialogueId"] = 12062419,
            ["GUID"] = "1E326E9E",
            ["NextDialogue"] = 12062420,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120624/1E326E9E",
            },
        [12062420] = {
            ["Content"] = "……这家伙，今天这是怎么了？",
            ["ContentFR"] = "... Qu’est-ce qui lui prend aujourd’hui ?",
            ["DialogueId"] = 12062420,
            ["GUID"] = "1E326EC8",
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120624/1E326EC8",
            },
        [12062421] = {
            ["Content"] = "青鸾贰型自检完成，执行积极作战模式。",
            ["ContentFR"] = "Auto-diagnostic du Qingluan Type II terminé. Activation du mode combat offensif.",
            ["DialogueId"] = 12062421,
            ["GUID"] = "1E326EF2",
            ["SnapShot"] = "ROBOT",
            ["SpeakNpcName"] = "UI_Npc_Name_Qingluan",
            ["VoiceName"] = "voice/$Locale$/story/1206/120624/1E326EF2",
            },
        [12062422] = {
            ["Content"] = "这样什么都证明不了……青鸾贰型，提高输出功率。",
            ["ContentFR"] = "Ça ne prouve rien... Qingluan Type II, augmente la puissance de sortie.",
            ["DialogueId"] = 12062422,
            ["GUID"] = "1E326F1C",
            ["NextDialogue"] = 12062423,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120624/1E326F1C",
            },
        [12062423] = {
            ["Content"] = "指令确认，输出功率提升至额定上限。",
            ["ContentFR"] = "Instruction confirmée. Puissance de sortie portée au maximum.",
            ["DialogueId"] = 12062423,
            ["GUID"] = "1E326F46",
            ["SnapShot"] = "ROBOT",
            ["SpeakNpcName"] = "UI_Npc_Name_Qingluan",
            ["VoiceName"] = "voice/$Locale$/story/1206/120624/1E326F46",
            },
        [12062424] = {
            ["Content"] = "还不够……继续。",
            ["ContentFR"] = "Ce n’est toujours pas suffisant... augmente encore.",
            ["DialogueId"] = 12062424,
            ["GUID"] = "1E326F70",
            ["NextDialogue"] = 12062425,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120624/1E326F70",
            },
        [12062425] = {
            ["Content"] = "警告，部件存在超载风险。",
            ["ContentFR"] = "Avertissement : risque de surcharge des composants.",
            ["DialogueId"] = 12062425,
            ["GUID"] = "1E326F9A",
            ["NextDialogue"] = 12062426,
            ["SnapShot"] = "ROBOT",
            ["SpeakNpcName"] = "UI_Npc_Name_Qingluan",
            ["VoiceName"] = "voice/$Locale$/story/1206/120624/1E326F9A",
            },
        [12062426] = {
            ["Content"] = "如果只能做到这个程度，那要怎么才能……继续！",
            ["ContentFR"] = "Si c’est tout ce que tu peux faire, alors comment suis-je censée... continue !",
            ["DialogueId"] = 12062426,
            ["GUID"] = "1E326FC4",
            ["NextDialogue"] = 12062427,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120624/1E326FC4",
            },
        [12062427] = {
            ["Content"] = "……苏乙，它的提示好像不太对劲……这样真的没问题吗？",
            ["ContentFR"] = "Su Yi... cet avertissement n’a pas l’air anodin. Tu es sûre que ça va aller ?",
            ["DialogueId"] = 12062427,
            ["GUID"] = "1E326FEE",
            ["NextDialogue"] = 12062428,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120624/1E326FEE",
            },
        [12062428] = {
            ["Content"] = "放心，我是青鸾贰型的制造者。我心中有数。",
            ["ContentFR"] = "Ne t’inquiète pas. C’est moi qui ai construit le Qingluan Type II. Je sais ce que je fais.",
            ["DialogueId"] = 12062428,
            ["GUID"] = "1E327018",
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120624/1E327018",
            },
        [12062429] = {
            ["Content"] = "警告、警告，功率过载。",
            ["ContentFR"] = "Avertissement. Avertissement. Surcharge de puissance.",
            ["DialogueId"] = 12062429,
            ["GUID"] = "1E327042",
