            ["NextDialogue"] = 12062520,
            ["SpeakNpcId"] = 250005,
            ["VoiceName"] = "voice/$Locale$/story/1206/120625/1E327F06",
            },
        [12062520] = {
            ["Content"] = "{nickname}，我出面转移观众注意力，你掩护苏乙先行退场吧。",
            ["ContentFR"] = "{nickname}, je vais attirer l’attention des spectateurs. Toi, emmène Su Yi et faites-la sortir d’ici.",
            ["DialogueId"] = 12062520,
            ["GUID"] = "1E327F30",
            ["SpeakNpcId"] = 250005,
            ["VoiceName"] = "voice/$Locale$/story/1206/120625/1E327F30",
            },
        [12062521] = {
            ["Content"] = "这么危险的东西，司事会怎么允许使用的……？",
            ["ContentFR"] = "Comment le conseil administratif a-t-il pu autoriser l’utilisation d’une chose aussi dangereuse ?",
            ["DialogueId"] = 12062521,
            ["GUID"] = "1E327F5A",
            ["SpeakNpcName"] = "UI_Npc_Name_Siyu",
            ["VoiceName"] = "voice/$Locale$/story/1206/120625/1E327F5A",
            },
        [12062522] = {
            ["Content"] = "那个机傀如果在人群里爆炸了，后果简直不堪设想……",
            ["ContentFR"] = "Si cette machine avait explosé au milieu de la foule... je n’ose même pas imaginer les conséquences.",
            ["DialogueId"] = 12062522,
            ["GUID"] = "1E327F84",
            ["SpeakNpcName"] = "UI_Npc_Name_Siyu",
            ["VoiceName"] = "voice/$Locale$/story/1206/120625/1E327F84",
            },
        [12062523] = {
            ["Content"] = "要是飘零人都是这样的危险份子，谁来保障我们的安全？！把他们赶出去！",
            ["ContentFR"] = "Si les Vagabonds sont tous aussi dangereux qu’elle, qui va garantir notre sécurité ?! Qu’on les chasse d’ici !",
            ["DialogueId"] = 12062523,
            ["GUID"] = "1E327FAE",
            ["SpeakNpcName"] = "UI_Npc_Name_Siyu",
            ["VoiceName"] = "voice/$Locale$/story/1206/120625/1E327FAE",
            },
        [12062524] = {
            ["Content"] = "苏乙，你不用太在意他们说了什么……",
            ["ContentFR"] = "Su Yi... ne fais pas trop attention à ce qu’ils disent...",
            ["DialogueId"] = 12062524,
            ["GUID"] = "1E327FD8",
            ["NextDialogue"] = 12062525,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120625/1E327FD8",
            },
        [12062525] = {
            ["Content"] = "……好。",
            ["ContentFR"] = "... D’accord.",
            ["DialogueId"] = 12062525,
            ["GUID"] = "1E328002",
            ["NextDialogue"] = 12062526,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120625/1E328002",
            },
        [12062526] = {
            ["Content"] = "出口就在前方了。",
            ["ContentFR"] = "La sortie est juste devant.",
            ["DialogueId"] = 12062526,
            ["GUID"] = "1E32802C",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120625/1E32802C",
            },
        [12062601] = {
            ["Content"] = "想装作无事发生，就这样视而不见地走过去吗？",
            ["ContentFR"] = "Tu comptes vraiment faire comme si rien ne s’était passé et passer devant moi sans me voir ?",
            ["DialogueId"] = 12062601,
            ["GUID"] = "1E328C7A",
            ["NextDialogue"] = 12062602,
            ["RelatedWikiId"] = {
                [1] = 203009,
                [2] = 201029,
                [3] = 103001,
                [4] = 203013,
                [5] = 203014,
                [6] = 408018,
                [7] = 403009,
                },
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120626/1E328C7A",
            },
        [12062602] = {
            ["Content"] = "…………",
            ["ContentFR"] = "...",
            ["DialogueId"] = 12062602,
            ["GUID"] = "1E328CA4",
            ["NextDialogue"] = 12062603,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120626/1E328CA4",
            },
        [12062603] = {
            ["Content"] = "呵，伤人却毫无悔意，你和你的姑姑苏暮鹧倒是如出一辙。",
            ["ContentFR"] = "<I>Hmpf.</> Blesser des gens sans le moindre remords... toi et ta tante Su Muzhe, vous êtes vraiment du même moule.",
            ["DialogueId"] = 12062603,
            ["GUID"] = "1E328CCE",
            ["NextDialogue"] = 12062604,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120626/1E328CCE",
            },
        [12062604] = {
            ["Content"] = "想来嘲笑我吗？随便你怎么说好了。我不会辩解。",
            ["ContentFR"] = "Tu es venue te moquer de moi ? Très bien. Dis ce que tu veux. Je ne chercherai pas à me justifier.",
            ["DialogueId"] = 12062604,
            ["GUID"] = "1E328CF8",
            ["NextDialogue"] = 12062605,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120626/1E328CF8",
            },
        [12062605] = {
            ["Content"] = "都是因为我过度改装青鸾贰号才导致它爆炸，这一点上我没什么可否认的。",
            ["ContentFR"] = "C’est bien moi qui ai poussé les modifications du Qingluan Type II trop loin, et c’est pour ça qu’il a explosé. Je ne le nie pas.",
            ["DialogueId"] = 12062605,
            ["GUID"] = "1E328D22",
            ["NextDialogue"] = 12062606,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120626/1E328D22",
            },
        [12062606] = {
            ["Content"] = "但这一切都与我姑姑无关。不要用我的错抹黑她……这是我唯一的底线。",
            ["ContentFR"] = "Mais tout cela n’a rien à voir avec ma tante. Ne salis pas sa mémoire à cause de mes erreurs... C’est la seule chose que je ne tolérerai pas.",
            ["DialogueId"] = 12062606,
            ["GUID"] = "1E328D4C",
            ["NextDialogue"] = 12062607,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120626/1E328D4C",
            },
        [12062607] = {
            ["Content"] = "抹黑？",
            ["ContentFR"] = "Salir sa mémoire ?",
            ["DialogueId"] = 12062607,
            ["GUID"] = "1E328D76",
            ["NextDialogue"] = 12062608,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120626/1E328D76",
            },
        [12062608] = {
            ["Content"] = "等等，难不成你真的不清楚苏暮鹧到底做过什么？",
            ["ContentFR"] = "Attends... ne me dis pas que tu ignores vraiment ce que Su Muzhe a fait ?",
            ["DialogueId"] = 12062608,
            ["GUID"] = "1E328DA0",
            ["NextDialogue"] = 12062609,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120626/1E328DA0",
            },
        [12062609] = {
            ["Content"] = "……你到底想说什么？",
            ["ContentFR"] = "... Qu’est-ce que tu veux dire ?",
            ["DialogueId"] = 12062609,
            ["GUID"] = "1E328DCA",
            ["NextDialogue"] = 12062610,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120626/1E328DCA",
            },
        [12062610] = {
            ["Content"] = "看来你真的不知道……",
            ["ContentFR"] = "Alors tu ne sais vraiment pas...",
            ["DialogueId"] = 12062610,
            ["GUID"] = "1E328DF4",
            ["NextDialogue"] = 12062611,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120626/1E328DF4",
            },
        [12062611] = {
            ["Content"] = "哈哈哈……原来你不知道……那个罪人的侄女，竟然不知道她的姑姑犯下的罪行！",
            ["ContentFR"] = "Hahaha... incroyable... La nièce de la criminelle qui ignore même les crimes de sa propre tante !",
            ["DialogueId"] = 12062611,
            ["GUID"] = "1E328E1E",
            ["NextDialogue"] = 12062612,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120626/1E328E1E",
            },
        [12062612] = {
            ["Content"] = "当我一天天在仇恨的怒火中辗转反侧，天色将明才勉强入睡时，她的侄女竟然能沉浸在恬不知耻的酣眠当中。",
            ["ContentFR"] = "Pendant que je passais nuit après nuit à me retourner dans mon lit, rongée par la haine, n’arrivant à dormir qu’à l’aube... sa nièce dormait paisiblement, sans la moindre honte.",
            ["DialogueId"] = 12062612,
            ["GUID"] = "1E328E48",
            ["NextDialogue"] = 12062613,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120626/1E328E48",
            },
        [12062613] = {
            ["Content"] = "你明明早已见过受害者——小安的腿疾就是苏暮鹧那个女人造成的！听到这里，你还能心安理得地为她辩护吗？",
            ["ContentFR"] = "Tu as pourtant déjà rencontré l’une des victimes — An. Sa jambe... c’est cette femme, Su Muzhe, qui en est responsable. Maintenant dis-moi : peux-tu encore la défendre la conscience tranquille ?",
            ["DialogueId"] = 12062613,
            ["GUID"] = "1E328E72",
            ["NextDialogue"] = 12062614,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120626/1E328E72",
            },
        [12062614] = {
            ["Content"] = "你说……什么？",
            ["ContentFR"] = "Tu... quoi ?",
            ["DialogueId"] = 12062614,
            ["GUID"] = "1E328E9C",
            ["NextDialogue"] = 12062615,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120626/1E328E9C",
            },
        [12062615] = {
            ["Content"] = "你没听错。",
            ["ContentFR"] = "Tu as très bien entendu.",
            ["DialogueId"] = 12062615,
            ["GUID"] = "1E328EC6",
            ["NextDialogue"] = 12062616,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120626/1E328EC6",
            },
        [12062616] = {
            ["Content"] = "不仅如此，小安的父母，还有更多受害者，都丧身于她引发的事故当中。",
            ["ContentFR"] = "Et ce n’est pas tout. Les parents d’An, et bien d’autres encore, ont perdu la vie dans l’accident qu’elle a provoqué.",
            ["DialogueId"] = 12062616,
            ["GUID"] = "1E328EF0",
            ["NextDialogue"] = 12062617,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120626/1E328EF0",
            },
        [12062617] = {
            ["Content"] = "那女人妄图操纵灭蒙巨鸟撞击执律阁，被击坠后，那足有千斤重的机关巨鸟直直冲向东郊。无数人躲闪不及，当场身陨。",
            ["ContentFR"] = "Cette femme a tenté de diriger l’Oiseau Géant Miemeng contre le Pavillon de l’Arbitrage. Lorsqu’il a été abattu, l’énorme machine, pesant des centaines de kilos, s’est écrasée droit sur les quartiers est. Beaucoup de gens n’ont même pas eu le temps de fuir... ils sont morts sur le coup.",
            ["DialogueId"] = 12062617,
            ["GUID"] = "1E328F1A",
            ["NextDialogue"] = 12062618,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120626/1E328F1A",
            },
        [12062618] = {
            ["Content"] = "……不，那不是姑姑的本意！在灭蒙残留的信息匣里，她留下了最后的遗言！",
            ["ContentFR"] = "... Non. Ce n’était pas l’intention de ma tante ! Dans la boîte de données laissée par Miemeng, elle a enregistré un dernier message !",
            ["DialogueId"] = 12062618,
            ["GUID"] = "1E328F44",
            ["NextDialogue"] = 12062619,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120626/1E328F44",
            },
        [12062619] = {
            ["Content"] = "“我想在生命最后的时刻飞去执律阁上空看一看，看看那支配着所有人的神明究竟是何模样。”",
            ["ContentFR"] = "« Dans les derniers instants de ma vie, je veux voler au-dessus du Pavillon de l’Arbitrage, ne serait-ce qu’une fois... et voir de mes propres yeux le dieu qui décide du destin de tous. »",
            ["DialogueId"] = 12062619,
            ["GUID"] = "1E328F6E",
            ["NextDialogue"] = 12062620,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120626/1E328F6E",
            },
        [12062620] = {
            ["Content"] = "姑姑……是这样说的。她飞向执律阁，并非是为了什么袭击……她，她只是想看一眼……",
            ["ContentFR"] = "... C’est ce qu’elle a dit. Elle s’est dirigée vers le Pavillon de l’Arbitrage non pas pour attaquer... mais simplement pour voir... une seule fois...",
            ["DialogueId"] = 12062620,
            ["GUID"] = "1E328F98",
            ["NextDialogue"] = 12062621,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120626/1E328F98",
            },
        [12062621] = {
            ["Content"] = "你对那些亡魂解释去吧，如果他们还能听得到。",
            ["ContentFR"] = "Explique ça aux morts, si tant est qu’ils puissent encore t’entendre.",
            ["DialogueId"] = 12062621,
            ["GUID"] = "1E328FC2",
            ["NextDialogue"] = 12062622,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120626/1E328FC2",
            },
        [12062622] = {
            ["Content"] = "从知道那场事故因她而起的那一天，我就无时无刻地想要找到她，让她血债血偿。",
            ["ContentFR"] = "Depuis le jour où j’ai appris que cette catastrophe venait d’elle, je n’ai cessé de vouloir la retrouver pour qu’elle paie de son sang.",
            ["DialogueId"] = 12062622,
            ["GUID"] = "1E328FEC",
            ["NextDialogue"] = 12062623,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120626/1E328FEC",
            },
        [12062623] = {
            ["Content"] = "即便会遭受大风九章的制裁，我也要让她的血在我的剑下流淌，让她在死亡的绝望之中向所有因她而逝去的生命忏悔。",
            ["ContentFR"] = "Même si les Neuf Chapitres de Dafeng devaient me condamner pour cela, je voulais que son sang coule sur ma lame. Je voulais qu’au moment de mourir, elle implore le pardon de toutes les vies qu’elle avait prises.",
            ["DialogueId"] = 12062623,
            ["GUID"] = "1E329016",
            ["NextDialogue"] = 12062624,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120626/1E329016",
            },
        [12062624] = {
            ["Content"] = "我要亲手杀了她。",
            ["ContentFR"] = "Je voulais la tuer de mes propres mains.",
            ["DialogueId"] = 12062624,
            ["GUID"] = "1E329040",
            ["NextDialogue"] = 12062625,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120626/1E329040",
            },
        [12062625] = {
            ["Content"] = "可是，姑姑早就死在了那场事故当中……！",
            ["ContentFR"] = "Mais ma tante est déjà morte dans cet accident... !",
            ["DialogueId"] = 12062625,
            ["GUID"] = "1E32906A",
            ["NextDialogue"] = 12062626,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120626/1E32906A",
            },
        [12062626] = {
            ["Content"] = "是啊，正如你所说。她死了，没有哀嚎，没有忏悔。她就这么简简单单地死了。",
            ["ContentFR"] = "Oui. Comme tu le dis. Elle est morte. Sans hurler. Sans se repentir. Elle est morte... simplement.",
            ["DialogueId"] = 12062626,
            ["GUID"] = "1E329094",
            ["NextDialogue"] = 12062627,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120626/1E329094",
            },
        [12062627] = {
            ["Content"] = "把周围变得天翻地覆之后，她就这么倒在了废墟里。她死了，然后呢？为什么始作俑者死得那么潇洒，幸存者却要经历漫长痛苦的折磨？",
            ["ContentFR"] = "Après avoir tout bouleversé autour d’elle, elle s’est effondrée dans les ruines. Elle est morte... et alors ? Pourquoi celui qui provoque la catastrophe peut-il mourir si facilement... tandis que les survivants doivent continuer à souffrir pendant des années ?",
            ["DialogueId"] = 12062627,
            ["GUID"] = "1E3290BE",
            ["NextDialogue"] = 12062628,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120626/1E3290BE",
            },
        [12062628] = {
            ["Content"] = "我的愤怒，我的仇恨，就只能像是受了潮的火药，就这么强行被浇灭。直到你们飘零人重新回来……回到大家的眼前。",
            ["ContentFR"] = "Ma colère, ma haine... c’était comme de la poudre mouillée. Impossible de l’embraser. Tout a été étouffé... jusqu’à ce que vous, les Vagabonds, reveniez devant les yeux de tout le monde.",
            ["DialogueId"] = 12062628,
            ["GUID"] = "1E3290E8",
            ["NextDialogue"] = 12062629,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120626/1E3290E8",
            },
        [12062629] = {
            ["Content"] = "残害人命的凶手不是你苏乙，但我不会让身为苏暮鹧传人的你，不会让飘零人就这么说走就走，说回就回。",
            ["ContentFR"] = "Ce n’est pas toi qui as tué ces gens, Su Yi. Mais toi, l’héritière de Su Muzhe — et les Vagabonds — vous ne pouvez pas apparaître et disparaître comme bon vous semble.",
            ["DialogueId"] = 12062629,
            ["GUID"] = "1E329112",
            ["NextDialogue"] = 12062630,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120626/1E329112",
            },
        [12062630] = {
            ["Content"] = "这下你明白了吧，飘零人小姑娘？",
            ["ContentFR"] = "Alors, tu comprends maintenant, petite Vagabonde ?",
            ["DialogueId"] = 12062630,
            ["GUID"] = "1E32913C",
            ["NextDialogue"] = 12062631,
            ["SpeakNpcId"] = 250015,
            ["VoiceName"] = "voice/$Locale$/story/1206/120626/1E32913C",
            },
        [12062631] = {
            ["Content"] = "…………",
            ["ContentFR"] = "...",
            ["DialogueId"] = 12062631,
            ["GUID"] = "1E329166",
            ["NextDialogue"] = 12062632,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120626/1E329166",
            },
        [12062632] = {
            ["Content"] = "飘零人就是一根刺，一根插在渴望和平厌倦纷争的华胥人身上的一根刺，华胥，不会接纳你们。",
            ["ContentFR"] = "Les Vagabonds sont comme une épine plantée dans la chair de Huaxu. Les habitants de Huaxu aspirent à la paix et en ont assez des conflits... et ils ne vous accepteront jamais.",
            ["DialogueId"] = 12062632,
            ["GUID"] = "1E329190",
            ["NextDialogue"] = 12062633,
            ["SpeakNpcId"] = 250015,
            ["VoiceName"] = "voice/$Locale$/story/1206/120626/1E329190",
            },
        [12062633] = {
            ["Content"] = "该传达的意思已经清楚了。潇湘，我们走吧。",
            ["ContentFR"] = "Le message est passé. Xiaoxiang, allons-y.",
            ["DialogueId"] = 12062633,
            ["GUID"] = "1E3291BA",
            ["NextDialogue"] = 12062634,
            ["SpeakNpcId"] = 250015,
            ["VoiceName"] = "voice/$Locale$/story/1206/120626/1E3291BA",
            },
        [12062634] = {
            ["Content"] = "…………",
            ["ContentFR"] = "...",
            ["DialogueId"] = 12062634,
            ["GUID"] = "1E3291E4",
            ["NextDialogue"] = 12062635,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120626/1E3291E4",
            },
        [12062635] = {
            ["Content"] = "{nickname}，我先失陪一下……",
            ["ContentFR"] = "{nickname}... excuse-moi un instant...",
            ["DialogueId"] = 12062635,
            ["GUID"] = "1E32920E",
            ["NextDialogue"] = 12062636,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120626/1E32920E",
            },
        [12062636] = {
            ["Content"] = "苏乙……你是在哭吗？",
            ["ContentFR"] = "Su Yi... tu es en train de pleurer ?",
            ["DialogueId"] = 12062636,
            ["GUID"] = "1E329238",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120626/1E329238",
            },
        [12062637] = {
            ["Content"] = "这种问题，你明明可以不用问的……",
            ["ContentFR"] = "Tu n’étais pas obligé de poser la question...",
            ["DialogueId"] = 12062637,
            ["GUID"] = "1E329262",
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120626/1E329262",
            },
        [12062638] = {
            ["Content"] = "呜……明明这种时候留我一个人在这里就好……",
            ["ContentFR"] = "... Tu aurais pu me laisser seule...",
            ["DialogueId"] = 12062638,
            ["GUID"] = "1E32928C",
            ["NextDialogue"] = 12062639,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120626/1E32928C",
            },
        [12062639] = {
            ["DialogueId"] = 12062639,
            ["GUID"] = "1E32928D",
            ["NextDialogue"] = 12062640,
            },
        [12062640] = {
            ["DialogueId"] = 12062640,
            ["GUID"] = "1E32928E",
            },
        [12062641] = {
            ["Content"] = "说的也是呢……{nickname}，从我与你认识的第一面开始，你就是这样，总是在做正确的事情。不像我……",
            ["ContentFR"] = "Oui... c’est vrai. {nickname}, depuis le jour où je t’ai rencontré, tu as toujours été comme ça. Tu fais toujours ce qui est juste... contrairement à moi.",
            ["DialogueId"] = 12062641,
            ["GUID"] = "1E32930A",
            ["NextDialogue"] = 12062642,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120626/1E32930A",
            },
        [12062642] = {
            ["Content"] = "我从来没有想过我是不是做错了，只是一意孤行地想要证明自己，直到刚刚……",
            ["ContentFR"] = "Je ne me suis jamais demandé si j’avais tort. Je voulais seulement prouver que j’avais raison... jusqu’à maintenant.",
            ["DialogueId"] = 12062642,
            ["GUID"] = "1E329334",
            ["NextDialogue"] = 12062643,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120626/1E329334",
            },
        [12062643] = {
            ["Content"] = "我知道他们憎恨飘零人，但我以为他们只是讨厌飘零人不敬神明。我甚至没有尝试去理解一下他们，去理解他们真正的痛苦。",
            ["ContentFR"] = "Je savais qu’ils détestaient les Vagabonds. Mais je pensais que c’était seulement parce que nous ne respectons pas leur dieu. Je n’ai jamais essayé de comprendre ce qu’ils ressentaient vraiment.",
            ["DialogueId"] = 12062643,
            ["GUID"] = "1E32935E",
            ["NextDialogue"] = 12062644,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120626/1E32935E",
            },
        [12062644] = {
            ["Content"] = "我知道姑姑做的是正确的事情，却没想过她当年的事故酿成的后果，哪怕不是出于她的本意。",
            ["ContentFR"] = "Je me répétais que ma tante avait fait ce qu’il fallait... sans jamais réfléchir aux conséquences de cet accident, même si ce n’était pas ce qu’elle voulait.",
            ["DialogueId"] = 12062644,
            ["GUID"] = "1E329388",
            ["NextDialogue"] = 12062645,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120626/1E329388",
            },
        [12062645] = {
            ["Content"] = "我真是……糟透了。",
            ["ContentFR"] = "Je suis vraiment... pitoyable.",
            ["DialogueId"] = 12062645,
            ["GUID"] = "1E3293B2",
            ["NextDialogue"] = 12062646,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120626/1E3293B2",
            },
        [12062646] = {
            ["Content"] = "苏乙……我没有你说的那么厉害，你也没有自己想的那么糟糕。",
            ["ContentFR"] = "Su Yi... je ne suis pas aussi remarquable que tu le crois. Et toi, tu n’es pas aussi terrible que tu le penses.",
            ["DialogueId"] = 12062646,
            ["GUID"] = "1E3293DC",
            ["NextDialogue"] = 12062647,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120626/1E3293DC",
            },
        [12062647] = {
            ["Content"] = "不然，你不会往这个方向走的。我没猜错的话——你想去小安的家，不是吗？",
            ["ContentFR"] = "Sinon, tu ne serais pas en train de marcher dans cette direction. Si je ne me trompe pas... tu te rends chez An, n’est-ce pas ?",
            ["DialogueId"] = 12062647,
            ["GUID"] = "1E329406",
            ["NextDialogue"] = 12062648,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120626/1E329406",
            },
        [12062648] = {
            ["Content"] = "……连这也被你看出来了。",
            ["ContentFR"] = "... Tu as encore deviné.",
            ["DialogueId"] = 12062648,
            ["GUID"] = "1E329430",
            ["NextDialogue"] = 12062649,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120626/1E329430",
            },
        [12062649] = {
            ["Content"] = "走吧，我们一起。",
            ["ContentFR"] = "Allons-y. On y va ensemble.",
            ["DialogueId"] = 12062649,
            ["GUID"] = "1E32945A",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120626/1E32945A",
            },
        [12062701] = {
            ["Content"] = "{nickname}，苏乙姑娘，别来无恙。",
            ["ContentFR"] = "{nickname}, Mademoiselle Su Yi. J’espère que vous vous portez bien.",
            ["DialogueId"] = 12062701,
            ["GUID"] = "1E329CE2",
            ["NextDialogue"] = 12062702,
            ["RelatedWikiId"] = {
                [1] = 203009,
                [2] = 201029,
                [3] = 203006,
                [4] = 103001,
                [5] = 203013,
                [6] = 203014,
                [7] = 408018,
                [8] = 403009,
                },
            ["SpeakNpcId"] = 250001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E329CE2",
            },
        [12062702] = {
            ["Content"] = "扶疏……你怎么会在这里？",
            ["ContentFR"] = "Fushu... que fais-tu ici ?",
            ["DialogueId"] = 12062702,
            ["GUID"] = "1E329D0C",
            ["NextDialogue"] = 12062703,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E329D0C",
            },
        [12062703] = {
            ["Content"] = "这家的女主人收养了一位孤儿。那名幼童在一场机傀坠毁的灾难中父母双亡，自己亦险些丧生。",
            ["ContentFR"] = "La maîtresse de maison a recueilli un orphelin. Cet enfant a perdu ses parents lors de la chute d’une méchapoupée et a lui-même failli y laisser la vie.",
            ["DialogueId"] = 12062703,
            ["GUID"] = "1E329D36",
            ["NextDialogue"] = 12062704,
            ["SpeakNpcId"] = 250001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E329D36",
            },
        [12062704] = {
            ["Content"] = "根据卷宗记载，当年泽生阁的医师们虽然拼尽全力保住了幼童的性命，但那孩子还是落下了终身残疾。",
            ["ContentFR"] = "D’après les archives, les médecins de la Pharmacie Zesheng ont tout tenté pour sauver l’enfant. Ils ont réussi à lui préserver la vie, mais il en est resté handicapé à vie.",
            ["DialogueId"] = 12062704,
            ["GUID"] = "1E329D60",
            ["NextDialogue"] = 12062705,
            ["SpeakNpcId"] = 250001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E329D60",
            },
        [12062705] = {
            ["Content"] = "那……小安的腿，还有机会治好吗？",
            ["ContentFR"] = "Alors... la jambe d’An... il y aurait encore une chance de la soigner ?",
            ["DialogueId"] = 12062705,
            ["GUID"] = "1E329D8A",
            ["NextDialogue"] = 12062706,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E329D8A",
            },
        [12062706] = {
            ["Content"] = "现在的我还办不到。枯荣之法虽可引渡浊气，但面对此等经年残疾，亦是无能为力。",
            ["ContentFR"] = "Pour l’instant, je n’en suis pas capable. L’Art de l’Éphémère permet d’extraire les miasmes du corps, mais il ne peut pas réparer un handicap installé depuis tant d’années.",
            ["DialogueId"] = 12062706,
            ["GUID"] = "1E329DB4",
            ["NextDialogue"] = 12062707,
            ["SpeakNpcId"] = 250001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E329DB4",
            },
        [12062707] = {
            ["Content"] = "但我既然选择好好继承家姐的药学衣钵，便打算从拜访那些泽生阁未能完全治愈的患者开始。折磨他们的疑难杂症，也许有朝一日，可以在我手中克服。",
            ["ContentFR"] = "Cependant, puisque j’ai décidé de reprendre l’héritage médical de ma sœur, j’ai commencé par rendre visite aux patients que la Pharmacie Zesheng n’avait pas pu guérir complètement. Les maladies qui les tourmentent encore... peut-être qu’un jour, je parviendrai à les vaincre.",
            ["DialogueId"] = 12062707,
            ["GUID"] = "1E329DDE",
            ["NextDialogue"] = 12062708,
            ["SpeakNpcId"] = 250001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E329DDE",
            },
        [12062708] = {
            ["Content"] = "不愧是你，好惊人的行动力。",
            ["ContentFR"] = "On reconnaît bien là ton sens de l’initiative, Fushu. Quand tu vois un problème, tu agis immédiatement.",
            ["DialogueId"] = 12062708,
            ["GUID"] = "1E329E08",
            ["NextDialogue"] = 12062709,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E329E08",
            },
        [12062709] = {
            ["Content"] = "那是因为你不曾见过家姐，与她的果决相比，我还差得远。",
            ["ContentFR"] = "C’est simplement que tu n’as jamais rencontré ma sœur. Comparée à sa détermination, je suis encore bien loin derrière.",
            ["DialogueId"] = 12062709,
            ["GUID"] = "1E329E32",
            ["NextDialogue"] = 12062710,
            ["SpeakNpcId"] = 250001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E329E32",
            },
        [12062710] = {
            ["Content"] = "那……如果——我不是故意乌鸦嘴，我只是说如果——",
            ["ContentFR"] = "Alors... si jamais — je ne veux pas porter malheur, je dis ça comme ça —",
            ["DialogueId"] = 12062710,
            ["GUID"] = "1E329E5C",
            ["NextDialogue"] = 12062711,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E329E5C",
            },
        [12062711] = {
            ["Content"] = "如果那些病你一辈子都治不好，该怎么办？",
            ["ContentFR"] = "Si tu n’arrivais jamais à guérir ces maladies... que ferais-tu ?",
            ["DialogueId"] = 12062711,
            ["GUID"] = "1E329E86",
            ["NextDialogue"] = 12062712,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E329E86",
            },
        [12062712] = {
            ["Content"] = "呵呵……那自然有下一个我接下这份使命。就像泽生阁的那些药师，姐姐把使命传给她的学生，她的学生又传给新的学生。",
            ["ContentFR"] = "Hm... dans ce cas, quelqu’un après moi prendra le relais. C’est ainsi que les choses ont toujours fonctionné à la Pharmacie Zesheng : ma sœur a transmis sa mission à ses élèves, et eux la transmettront aux leurs.",
            ["DialogueId"] = 12062712,
            ["GUID"] = "1E329EB0",
            ["NextDialogue"] = 12062713,
            ["SpeakNpcId"] = 250001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E329EB0",
            },
        [12062713] = {
            ["Content"] = "更何况，对扶疏而言，还有一件极为重要之事。",
            ["ContentFR"] = "Et puis, pour moi, il y a une chose encore plus importante.",
            ["DialogueId"] = 12062713,
            ["GUID"] = "1E329EDA",
            ["NextDialogue"] = 12062714,
            ["SpeakNpcId"] = 250001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E329EDA",
            },
        [12062714] = {
            ["Content"] = "我希望那些病人知道，他们并不是独自与伤痛抗争——世界上还有另一个人，永远不会放弃他们。",
            ["ContentFR"] = "Je veux que ces patients sachent qu’ils ne sont pas seuls face à leur souffrance. Qu’il existe quelque part quelqu’un qui ne les abandonnera jamais.",
            ["DialogueId"] = 12062714,
            ["GUID"] = "1E329F04",
            ["NextDialogue"] = 12062715,
            ["SpeakNpcId"] = 250001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E329F04",
            },
        [12062715] = {
            ["Content"] = "如此，他们自己才不会轻言放弃。",
            ["ContentFR"] = "Ainsi, ils ne renonceront pas eux-mêmes.",
            ["DialogueId"] = 12062715,
            ["GUID"] = "1E329F2E",
            ["NextDialogue"] = 12062716,
            ["SpeakNpcId"] = 250001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E329F2E",
            },
        [12062716] = {
            ["Content"] = "……不放弃……",
            ["ContentFR"] = "... Ne pas abandonner...",
            ["DialogueId"] = 12062716,
            ["GUID"] = "1E329F58",
            ["NextDialogue"] = 12062717,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E329F58",
            },
        [12062717] = {
            ["Content"] = "即使前路多艰，希望微茫？",
            ["ContentFR"] = "Même si le chemin est difficile... et que l’espoir est infime ?",
            ["DialogueId"] = 12062717,
            ["GUID"] = "1E329F82",
            ["NextDialogue"] = 12062718,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E329F82",
            },
        [12062718] = {
            ["Content"] = "即使前路多艰，希望微茫。",
            ["ContentFR"] = "Même si le chemin est difficile... et que l’espoir est infime.",
            ["DialogueId"] = 12062718,
            ["GUID"] = "1E329FAC",
            ["NextDialogue"] = 12062719,
            ["SpeakNpcId"] = 250001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E329FAC",
            },
        [12062719] = {
            ["Content"] = "…………",
            ["ContentFR"] = "...",
            ["DialogueId"] = 12062719,
            ["GUID"] = "1E329FD6",
            ["NextDialogue"] = 12062720,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E329FD6",
            },
        [12062720] = {
            ["Content"] = "姑姑……你要去哪？！为什么不带上我！",
            ["ContentFR"] = "Tante... où est-ce que tu vas ?! Pourquoi tu ne m’emmènes pas avec toi ?",
            ["DialogueId"] = 12062720,
            ["GUID"] = "1E32A000",
            ["NextDialogue"] = 12062721,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E32A000",
            },
        [12062721] = {
            ["Content"] = "对不起啊，小苏。姑姑如果继续留在这里，只会拖累你和你的母亲。",
            ["ContentFR"] = "Je suis désolée, Su. Si je reste ici, je ne ferai qu’attirer des ennuis sur toi et sur ta mère.",
            ["DialogueId"] = 12062721,
            ["GUID"] = "1E32A02A",
            ["NextDialogue"] = 12062722,
            ["SpeakNpcName"] = "UI_Npc_Name_Sumuo",
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E32A02A",
            },
        [12062722] = {
            ["Content"] = "为什么？是因为那些坏人要来抓姑姑吗？",
            ["ContentFR"] = "Pourquoi ? C’est parce que ces méchants vont venir t’arrêter ?",
            ["DialogueId"] = 12062722,
            ["GUID"] = "1E32A054",
            ["NextDialogue"] = 12062723,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E32A054",
            },
        [12062723] = {
            ["Content"] = "不，他们不是坏人。",
            ["ContentFR"] = "Non. Ce ne sont pas de mauvaises personnes.",
            ["DialogueId"] = 12062723,
            ["GUID"] = "1E32A07E",
            ["NextDialogue"] = 12062724,
            ["SpeakNpcName"] = "UI_Npc_Name_Sumuo",
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E32A07E",
            },
        [12062724] = {
            ["Content"] = "虽然他们给小鸟儿戴上了黄金的脚链，但他们心里是为了小鸟儿好。",
            ["ContentFR"] = "Ils ont simplement attaché une chaîne d’or à la patte d’un petit oiseau, en pensant agir pour son bien.",
            ["DialogueId"] = 12062724,
            ["GUID"] = "1E32A0A8",
            ["NextDialogue"] = 12062725,
            ["SpeakNpcName"] = "UI_Npc_Name_Sumuo",
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E32A0A8",
            },
        [12062725] = {
            ["Content"] = "那姑姑为什么要走？姑姑你在做的事难道不是能够造福大家的好事吗？",
            ["ContentFR"] = "Alors pourquoi dois-tu partir ? Ce que tu fais n’est-il pas quelque chose de bon pour tout le monde ?",
            ["DialogueId"] = 12062725,
            ["GUID"] = "1E32A0D2",
            ["NextDialogue"] = 12062726,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E32A0D2",
            },
        [12062726] = {
            ["Content"] = "当然了。因为小鸟儿自己知道，比起黄金的锁链，她更想要辽阔的天空，还有无拘无束、自在飞翔的未来。",
            ["ContentFR"] = "Bien sûr que si. Mais le petit oiseau sait lui-même que ce qu’il veut n’est pas une chaîne d’or. Il veut le ciel immense... et un avenir où il pourra voler librement.",
            ["DialogueId"] = 12062726,
            ["GUID"] = "1E32A0FC",
            ["NextDialogue"] = 12062727,
            ["SpeakNpcName"] = "UI_Npc_Name_Sumuo",
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E32A0FC",
            },
        [12062727] = {
            ["Content"] = "如果那天真的到来了，我们小苏就不用被关在宅子里，人们也可以更加尽力去开发机枢术，研究出更多造福大家的技术。",
            ["ContentFR"] = "Si ce jour arrive, toi non plus tu ne seras plus enfermée dans cette maison. Et les artisans pourront consacrer tous leurs efforts à développer l’art des méchapoupées, afin de créer encore plus d’inventions utiles à tous.",
            ["DialogueId"] = 12062727,
            ["GUID"] = "1E32A126",
            ["NextDialogue"] = 12062728,
            ["SpeakNpcName"] = "UI_Npc_Name_Sumuo",
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E32A126",
            },
        [12062728] = {
            ["Content"] = "姑姑你那么厉害，他们也不是坏人，那么是不是只要你证明给他们看，机枢是非常非常了不起的好东西，你们就能和好了？",
            ["ContentFR"] = "Tante, tu es si forte. Et eux ne sont pas mauvais... alors si tu leur montres que l’art des méchapoupées peut apporter tellement de bonnes choses, vous pourrez vous réconcilier, non ?",
            ["DialogueId"] = 12062728,
            ["GUID"] = "1E32A150",
            ["NextDialogue"] = 12062729,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E32A150",
            },
        [12062729] = {
            ["Content"] = "当然——如果姑姑能做得到的话。",
            ["ContentFR"] = "Bien sûr... si ta tante y parvient.",
            ["DialogueId"] = 12062729,
            ["GUID"] = "1E32A17A",
            ["NextDialogue"] = 12062730,
            ["SpeakNpcName"] = "UI_Npc_Name_Sumuo",
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E32A17A",
            },
        [12062730] = {
            ["Content"] = "可惜，姑姑并没有那么厉害。就连我最擅长的机枢工造，小苏也很快就能超过我。",
            ["ContentFR"] = "Malheureusement, je ne suis pas aussi exceptionnelle. Même dans le domaine où je suis la plus compétente, la fabrication de méchapoupées, tu me dépasseras bientôt.",
            ["DialogueId"] = 12062730,
            ["GUID"] = "1E32A1A4",
            ["NextDialogue"] = 12062731,
            ["SpeakNpcName"] = "UI_Npc_Name_Sumuo",
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E32A1A4",
            },
        [12062731] = {
            ["Content"] = "幸好，我已经把我毕生所学全部教给了你。遗憾的事呀，又少了一件。",
            ["ContentFR"] = "Heureusement, je t’ai déjà transmis tout ce que je savais. C’est déjà un regret de moins.",
            ["DialogueId"] = 12062731,
            ["GUID"] = "1E32A1CE",
            ["NextDialogue"] = 12062732,
            ["SpeakNpcName"] = "UI_Npc_Name_Sumuo",
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E32A1CE",
            },
        [12062732] = {
            ["Content"] = "呜呜……呜呜……",
            ["ContentFR"] = "<I>Snif... snif...</>",
            ["DialogueId"] = 12062732,
            ["GUID"] = "1E32A1F8",
            ["NextDialogue"] = 12062733,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E32A1F8",
            },
        [12062733] = {
            ["Content"] = "小苏，别哭。我们约好了，如果姑姑成功改变了大风九章，就回来带上你，还有你的父亲母亲，去东郊放飞我们一起做的机巧鸟玩，好吗？",
            ["ContentFR"] = "Su, ne pleure pas. Nous avons fait une promesse, tu te souviens ? Si je parviens à changer les Neuf Chapitres de Dafeng, je reviendrai te chercher, toi et tes parents, et nous irons faire voler les petits oiseaux mécaniques que nous avons fabriqués ensemble dans les plaines de l’est. D’accord ?",
            ["DialogueId"] = 12062733,
            ["GUID"] = "1E32A222",
            ["NextDialogue"] = 12062734,
            ["SpeakNpcName"] = "UI_Npc_Name_Sumuo",
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E32A222",
            },
        [12062734] = {
            ["Content"] = "呜……那如果失败了呢？",
            ["ContentFR"] = "Mais... et si tu échoues ?",
            ["DialogueId"] = 12062734,
            ["GUID"] = "1E32A24C",
            ["NextDialogue"] = 12062735,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E32A24C",
            },
        [12062735] = {
            ["Content"] = "如果失败了，姑姑还有你啊。就算失败，至少也能告诉你，我所行的乃是错误的道路。那样你就能及时避开啦。",
            ["ContentFR"] = "Si j’échoue... j’aurai encore toi. Au moins, je pourrai te dire que le chemin que j’ai suivi était une erreur. Ainsi, tu pourras l’éviter.",
            ["DialogueId"] = 12062735,
            ["GUID"] = "1E32A276",
            ["NextDialogue"] = 12062736,
            ["SpeakNpcName"] = "UI_Npc_Name_Sumuo",
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E32A276",
            },
        [12062736] = {
            ["Content"] = "可要是我也错了呢……",
            ["ContentFR"] = "Mais si moi aussi je me trompe... ?",
            ["DialogueId"] = 12062736,
            ["GUID"] = "1E32A2A0",
            ["NextDialogue"] = 12062737,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E32A2A0",
            },
        [12062737] = {
            ["Content"] = "没关系，像我一样，你也会拥有你的学生。你可以告诉他们，不要犯你犯的错误呀。学生又会有新的学生，总有一个人能看到一切改变的那一天，不是吗？",
            ["ContentFR"] = "Ce n’est pas grave. Comme moi, tu auras un jour tes propres élèves. Tu leur diras de ne pas commettre les mêmes erreurs que toi. Et eux auront à leur tour de nouveaux élèves... jusqu’au jour où quelqu’un verra enfin le monde changer.",
            ["DialogueId"] = 12062737,
            ["GUID"] = "1E32A2CA",
            ["NextDialogue"] = 12062738,
            ["SpeakNpcName"] = "UI_Npc_Name_Sumuo",
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E32A2CA",
            },
        [12062738] = {
            ["Content"] = "可、可要等那么久的话，姑姑还能看到那一天吗？",
            ["ContentFR"] = "Mais... si cela prend aussi longtemps... est-ce que tu pourras encore voir ce jour-là ?",
            ["DialogueId"] = 12062738,
            ["GUID"] = "1E32A2F4",
            ["NextDialogue"] = 12062739,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E32A2F4",
            },
        [12062739] = {
            ["Content"] = "这就难说了……唉，真头疼呀。",
            ["ContentFR"] = "Ça... je n’en sais rien. C’est bien le problème.",
            ["DialogueId"] = 12062739,
            ["GUID"] = "1E32A31E",
            ["NextDialogue"] = 12062740,
            ["SpeakNpcName"] = "UI_Npc_Name_Sumuo",
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E32A31E",
            },
        [12062740] = {
            ["Content"] = "为了一起看到那一天，那不就只能在我这里成功了嘛。小苏一定要好好吃饭睡觉，等着我的好消息哦。",
            ["ContentFR"] = "Alors pour que nous puissions voir ce jour ensemble... il va falloir que je réussisse, n’est-ce pas ? Su, promets-moi de bien manger, de bien dormir... et d’attendre mes bonnes nouvelles.",
            ["DialogueId"] = 12062740,
            ["GUID"] = "1E32A348",
            ["NextDialogue"] = 12062741,
            ["SpeakNpcName"] = "UI_Npc_Name_Sumuo",
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E32A348",
            },
        [12062741] = {
            ["Content"] = "……还有最后一件事……",
            ["ContentFR"] = "... Et encore une dernière chose.",
            ["DialogueId"] = 12062741,
            ["GUID"] = "1E32A372",
            ["NextDialogue"] = 12062742,
            ["SpeakNpcName"] = "UI_Npc_Name_Sumuo",
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E32A372",
            },
        [12062742] = {
            ["Content"] = "改变必定伴随着代价。如果——我不是故意乌鸦嘴，我只是说如果——姑姑有一天犯下了什么大错……",
            ["ContentFR"] = "Tout changement a un prix. Et si — je ne veux pas porter malheur, je dis ça comme ça — si un jour ta tante commettait une terrible erreur...",
            ["DialogueId"] = 12062742,
            ["GUID"] = "1E32A39C",
            ["NextDialogue"] = 12062743,
            ["SpeakNpcName"] = "UI_Npc_Name_Sumuo",
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E32A39C",
            },
        [12062743] = {
            ["Content"] = "就也交给我吧，谁让……我是姑姑的学生呢。",
            ["ContentFR"] = "Alors laisse-moi m’en charger. Après tout... je suis ton élève.",
            ["DialogueId"] = 12062743,
            ["GUID"] = "1E32A3C6",
            ["NextDialogue"] = 12062744,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E32A3C6",
            },
        [12062744] = {
            ["Content"] = "……我知道了……",
            ["ContentFR"] = "Je comprends maintenant...",
            ["DialogueId"] = 12062744,
            ["GUID"] = "1E32A3F0",
            ["NextDialogue"] = 12062745,
            ["RelatedWikiId"] = {
                [1] = 203009,
                [2] = 201029,
                [3] = 103001,
                [4] = 203013,
                [5] = 203014,
                [6] = 408018,
                [7] = 403009,
                },
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E32A3F0",
            },
        [12062745] = {
            ["Content"] = "……我知道该做什么了，姑姑。",
            ["ContentFR"] = "... Je sais ce que je dois faire, tante.",
            ["DialogueId"] = 12062745,
            ["GUID"] = "1E32A41A",
            ["NextDialogue"] = 12062746,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E32A41A",
            },
        [12062746] = {
            ["Content"] = "{nickname}，刚刚的我可能是个落荒而逃的胆小鬼。但现在不一样了！",
            ["ContentFR"] = "{nickname}... tout à l’heure, j’ai fui comme une lâche. Mais maintenant, c’est différent !",
            ["DialogueId"] = 12062746,
            ["GUID"] = "1E32A444",
            ["NextDialogue"] = 12062747,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E32A444",
            },
        [12062747] = {
            ["Content"] = "现在我有一件很重要很重要的事情要拜托你！",
            ["ContentFR"] = "Il y a quelque chose de très, très important que je dois te demander !",
            ["DialogueId"] = 12062747,
            ["GUID"] = "1E32A46E",
            ["NextDialogue"] = 12062748,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E32A46E",
            },
        [12062748] = {
            ["Content"] = "不愧是苏乙姑娘，行事风风火火。这样的人无论跌入何种低谷都能振作起来吧。",
            ["ContentFR"] = "On reconnaît bien là Mademoiselle Su Yi... toujours prompte à agir. Un tempérament pareil finit toujours par se relever, peu importe la profondeur de la chute.",
            ["DialogueId"] = 12062748,
            ["GUID"] = "1E32A498",
            ["NextDialogue"] = 12062749,
            ["SpeakNpcId"] = 250001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E32A498",
            },
        [12062749] = {
            ["Content"] = "苏乙姑娘虽并非药师，但我能隐隐察觉……她似乎也想以自己的方式，治疗世界上的另一种伤痛。",
            ["ContentFR"] = "Elle n’est pas médecin... pourtant je sens en elle quelque chose de semblable. À sa manière, elle cherche elle aussi à guérir une autre forme de souffrance.",
            ["DialogueId"] = 12062749,
            ["GUID"] = "1E32A4C2",
            ["NextDialogue"] = 12062750,
            ["SpeakNpcId"] = 250001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E32A4C2",
            },
        [12062750] = {
            ["Content"] = "并非肉体之痛，而是心间之痛。",
            ["ContentFR"] = "Non pas celle du corps... mais celle du cœur.",
            ["DialogueId"] = 12062750,
            ["GUID"] = "1E32A4EC",
            ["NextDialogue"] = 12062751,
            ["SpeakNpcId"] = 250001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E32A4EC",
            },
        [12062751] = {
            ["Content"] = "但，即便方式不同，也仍然有人与我们走在相似的道路上，接下来的路，我们不会感到孤独了吧，姐姐。",
            ["ContentFR"] = "Nos chemins sont différents, et pourtant certains avancent dans une direction proche de la nôtre. Peut-être ne serons-nous plus seuls sur cette route, désormais... grande sœur.",
            ["DialogueId"] = 12062751,
            ["GUID"] = "1E32A516",
            ["SpeakNpcId"] = 250001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E32A516",
            },
        [12062801] = {
            ["Content"] = "呼啊——我说，比赛快开场了，别的队伍三三两两都已经入场了，她真的还会来吗？",
            ["ContentFR"] = "Haa— Dis donc... la manche va bientôt commencer. Les autres équipes entrent déjà une par une... Tu es {性别:sûr|sûre} qu’elle va encore venir ?",
            ["DialogueId"] = 12062801,
            ["GUID"] = "1E32AD4A",
            ["NextDialogue"] = 12062802,
            ["RelatedWikiId"] = {
                [1] = 203009,
                [2] = 201029,
                [3] = 103001,
                [4] = 203013,
                [5] = 203014,
                [6] = 408018,
                [7] = 403009,
                },
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120628/1E32AD4A",
            },
        [12062802] = {
            ["Content"] = "再等五分钟……五分钟就好。",
            ["ContentFR"] = "Attendons encore cinq minutes... juste cinq minutes.",
            ["DialogueId"] = 12062802,
            ["GUID"] = "1E32AD74",
            ["NextDialogue"] = 12062803,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120628/1E32AD74",
            },
        [12062803] = {
            ["Content"] = "如果那时候苏乙还没能赶过来，我们就先进场。",
            ["ContentFR"] = "Si Su Yi n’est toujours pas revenue d’ici là, nous entrerons sans elle.",
            ["DialogueId"] = 12062803,
            ["GUID"] = "1E32AD9E",
            ["NextDialogue"] = 12062804,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120628/1E32AD9E",
            },
        [12062804] = {
            ["Content"] = "喂喂，{nickname}，苏乙那家伙之前都和你说了什么啊？神神秘秘的。",
            ["ContentFR"] = "Hé, {nickname}... au fait, qu’est-ce que Su Yi t’a raconté tout à l’heure ? Vous aviez l’air bien mystérieux.",
            ["DialogueId"] = 12062804,
            ["GUID"] = "1E32ADC8",
            ["NextDialogue"] = 12062805,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120628/1E32ADC8",
            },
        [12062805] = {
            ["Content"] = "现在我有一件很重要很重要的事情要拜托你！",
            ["ContentFR"] = "Il y a quelque chose de très, très important que je dois te demander !",
            ["DialogueId"] = 12062805,
            ["GUID"] = "1E32ADF2",
            ["NextDialogue"] = 12062806,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120628/1E32ADF2",
            },
        [12062806] = {
            ["Content"] = "你说，我在听。",
            ["ContentFR"] = "Je t’écoute.",
            ["DialogueId"] = 12062806,
            ["GUID"] = "1E32AE1C",
            ["NextDialogue"] = 12062807,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120628/1E32AE1C",
            },
        [12062807] = {
            ["Content"] = "我已经想清楚自己该做什么了。我必须现在立刻马上去，一分一秒都不能耽搁！",
            ["ContentFR"] = "J’ai enfin compris ce que je devais faire. Je dois y aller tout de suite — immédiatement. Je ne peux pas perdre une seule seconde !",
            ["DialogueId"] = 12062807,
            ["GUID"] = "1E32AE46",
            ["NextDialogue"] = 12062808,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120628/1E32AE46",
            },
        [12062808] = {
            ["Content"] = "我会尽量在比赛前回来，但万一没能赶上的话，只能拜托你们先入场了。",
            ["ContentFR"] = "Je ferai de mon mieux pour revenir avant la manche, mais si je n’y arrive pas... je compte sur vous pour entrer sans moi.",
            ["DialogueId"] = 12062808,
            ["GUID"] = "1E32AE70",
            ["NextDialogue"] = 12062809,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120628/1E32AE70",
            },
        [12062809] = {
            ["Content"] = "明明大家是因为我才参赛，我却擅自去忙自己的事情，真的非常对不起……",
            ["ContentFR"] = "Vous participez tous à ce tournoi à cause de moi, et pourtant je pars régler mes propres affaires... je suis vraiment désolée.",
            ["DialogueId"] = 12062809,
            ["GUID"] = "1E32AE9A",
            ["NextDialogue"] = 12062810,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120628/1E32AE9A",
            },
        [12062810] = {
            ["Content"] = "没关系。现在塔比瑟回来了，就算你真的缺席了这场比赛，她也能替补上场。",
            ["ContentFR"] = "Ce n’est rien. Maintenant que Tabethe est revenue, même si tu manques cette manche, elle pourra te remplacer.",
            ["DialogueId"] = 12062810,
            ["GUID"] = "1E32AEC4",
            ["NextDialogue"] = 12062811,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120628/1E32AEC4",
            },
        [12062811] = {
            ["Content"] = "比起这个，我更高兴你找到了自己该做的事情。",
            ["ContentFR"] = "Et puis... je suis surtout {性别:content|contente} que tu aies trouvé ce que tu devais faire.",
            ["DialogueId"] = 12062811,
            ["GUID"] = "1E32AEEE",
            ["NextDialogue"] = 12062812,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120628/1E32AEEE",
            },
        [12062812] = {
            ["Content"] = "……谢谢。",
            ["ContentFR"] = "... Merci.",
            ["DialogueId"] = 12062812,
            ["GUID"] = "1E32AF18",
            ["NextDialogue"] = 12062813,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120628/1E32AF18",
            },
        [12062813] = {
            ["Content"] = "仔细想想，之前的我又迷茫又偏执，你却愿意陪着这样的我胡闹。但我可不能再这样一直不像话下去了！",
            ["ContentFR"] = "Quand j’y repense, j’étais complètement perdue... et terriblement obstinée. Pourtant tu es resté à mes côtés malgré tout. Mais je ne peux pas continuer à agir de manière aussi déraisonnable !",
            ["DialogueId"] = 12062813,
            ["GUID"] = "1E32AF42",
            ["NextDialogue"] = 12062814,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120628/1E32AF42",
            },
        [12062814] = {
            ["Content"] = "{nickname}，也是时候让你看到我的另外一面了。认准了一件事情就不撞南墙不回头，闪闪发光的那一面！",
            ["ContentFR"] = "{nickname}... il est temps que je te montre une autre facette de moi. Quand je décide de faire quelque chose, je ne m’arrête plus — la version de moi qui avance sans jamais reculer !",
            ["DialogueId"] = 12062814,
            ["GUID"] = "1E32AF6C",
            ["NextDialogue"] = 12062815,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120628/1E32AF6C",
            },
        [12062815] = {
            ["Content"] = "正确的事，什么时候开始做都不算晚，你说对吗？",
            ["ContentFR"] = "Faire ce qui est juste n’est jamais trop tard... tu ne crois pas ?",
            ["DialogueId"] = 12062815,
            ["GUID"] = "1E32AF96",
            ["NextDialogue"] = 12062816,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120628/1E32AF96",
            },
        [12062816] = {
            ["Content"] = "如此一来，我们也不能辜负苏乙的决心了。",
            ["ContentFR"] = "Dans ce cas, nous ne devons pas laisser les efforts de Su Yi être vains.",
            ["DialogueId"] = 12062816,
            ["GUID"] = "1E32AFC0",
            ["NextDialogue"] = 12062817,
            ["SpeakNpcId"] = 250005,
            ["VoiceName"] = "voice/$Locale$/story/1206/120628/1E32AFC0",
            },
        [12062817] = {
            ["Content"] = "嘻嘻，既然这样，我可不能让她小瞧了。没有那家伙，我们也能轻轻松松地拿下胜利嘛，到时候再向她要报酬好了——我要让她请我把八珍楼的所有菜吃个遍！",
            ["ContentFR"] = "Héhé... dans ce cas, je ne peux pas me permettre de la laisser me sous-estimer. Même sans elle, on peut gagner sans problème ! Et ensuite je réclamerai ma récompense. Je vais lui demander de m’inviter au Pavillon des Huit Trésors — et je compte bien goûter tous les plats du menu !",
            ["DialogueId"] = 12062817,
            ["GUID"] = "1E32AFEA",
            ["NextDialogue"] = 12062818,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120628/1E32AFEA",
            },
        [12062818] = {
            ["Content"] = "嗯。就算身处不同的赛场，但是大家都在为自己的目标而奋斗，这样就好。",
            ["ContentFR"] = "Mm. Même si nous combattons sur des terrains différents, chacun poursuit son objectif. C’est ce qui compte.",
            ["DialogueId"] = 12062818,
            ["GUID"] = "1E32B014",
            ["NextDialogue"] = 12062819,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120628/1E32B014",
            },
        [12062819] = {
            ["Content"] = "走吧，我们很快就会再次和苏乙会合的——以胜者的姿势。",
            ["ContentFR"] = "Allons-y. Nous retrouverons bientôt Su Yi... et cette fois en tant que vainqueurs.",
            ["DialogueId"] = 12062819,
            ["GUID"] = "1E32B03E",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120628/1E32B03E",
            },
        [12062820] = {
            ["Content"] = "最后果然还是没有赶上……",
            ["ContentFR"] = "Finalement... je n’ai vraiment pas réussi à arriver à temps...",
            ["DialogueId"] = 12062820,
            ["GUID"] = "1E32B068",
            ["NextDialogue"] = 12062821,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120628/1E32B068",
            },
        [12062821] = {
            ["Content"] = "不过就算没有我，{nickname}他们也可以顺顺利利的吧。",
            ["ContentFR"] = "Mais même sans moi, {nickname} et les autres devraient s’en sortir.",
            ["DialogueId"] = 12062821,
            ["GUID"] = "1E32B092",
            ["NextDialogue"] = 12062822,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120628/1E32B092",
            },
        [12062822] = {
            ["Content"] = "该把做好的东西送过去给小安了。",
            ["ContentFR"] = "Je devrais apporter ce que j’ai fabriqué à An.",
            ["DialogueId"] = 12062822,
            ["GUID"] = "1E32B0BC",
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120628/1E32B0BC",
            },
        [12062901] = {
            ["Content"] = "你好，请问有人在家吗……？",
            ["ContentFR"] = "Bonjour... il y a quelqu’un ?",
            ["DialogueId"] = 12062901,
            ["GUID"] = "1E32BDB2",
            ["NextDialogue"] = 12062902,
            ["RelatedWikiId"] = {
                [1] = 203009,
                [2] = 201029,
                [3] = 103001,
                [4] = 203013,
                [5] = 203014,
                [6] = 408018,
                [7] = 403009,
                },
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120629/1E32BDB2",
            },
        [12062902] = {
            ["Content"] = "小安，我为你赶制了一副义肢，希望可以帮上忙……",
            ["ContentFR"] = "An... j’ai fabriqué pour toi une prothèse de jambe. J’espère que cela pourra t’aider...",
            ["DialogueId"] = 12062902,
            ["GUID"] = "1E32BDDC",
            ["NextDialogue"] = 12062903,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120629/1E32BDDC",
            },
        [12062903] = {
            ["Content"] = "我知道这弥补不了已经造成的伤害，但是……请至少让我尝试一下！",
            ["ContentFR"] = "Je sais que cela ne peut pas réparer ce qui s’est déjà passé, mais... s’il te plaît, laisse-moi au moins essayer.",
            ["DialogueId"] = 12062903,
            ["GUID"] = "1E32BE06",
            ["NextDialogue"] = 12062904,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120629/1E32BE06",
            },
        [12062904] = {
            ["Content"] = "果然还是不行吗……",
            ["ContentFR"] = "... Comme je le pensais.",
            ["DialogueId"] = 12062904,
            ["GUID"] = "1E32BE30",
            ["NextDialogue"] = 12062905,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120629/1E32BE30",
            },
        [12062905] = {
            ["Content"] = "……来人啊……有谁在吗…………",
            ["ContentFR"] = "À l’aide... quelqu’un... s’il vous plaît...",
            ["DialogueId"] = 12062905,
            ["GUID"] = "1E32BE5A",
            ["NextDialogue"] = 12062906,
            ["SpeakNpcId"] = 250017,
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["VoiceName"] = "voice/$Locale$/story/1206/120629/1E32BE5A",
            },
        [12062906] = {
            ["Content"] = "谁？",
            ["ContentFR"] = "Qui est là ?",
            ["DialogueId"] = 12062906,
            ["GUID"] = "1E32BE84",
            ["NextDialogue"] = 12062907,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120629/1E32BE84",
            },
        [12062907] = {
            ["Content"] = "等等……这个熟悉的声音，难不成是……",
            ["ContentFR"] = "Attends... cette voix me dit quelque chose... ce ne serait pas...",
            ["DialogueId"] = 12062907,
            ["GUID"] = "1E32BEAE",
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120629/1E32BEAE",
            },
        [12063001] = {
            ["Content"] = "……太好了，终于有人来了！！",
            ["ContentFR"] = "Ah ! Enfin quelqu’un !",
            ["DialogueId"] = 12063001,
            ["GUID"] = "1E32CE1A",
            ["NextDialogue"] = 12063002,
            ["RelatedWikiId"] = {
                [1] = 203004,
                [2] = 203009,
                [3] = 201029,
                [4] = 103001,
                [5] = 203013,
                [6] = 203014,
                [7] = 408018,
                [8] = 403009,
                },
            ["SpeakNpcId"] = 250017,
            ["VoiceName"] = "voice/$Locale$/story/1206/120630/1E32CE1A",
            },
        [12063002] = {
            ["Content"] = "小安？到底发生什么事了？！",
            ["ContentFR"] = "An ?! Que s’est-il passé ?",
            ["DialogueId"] = 12063002,
            ["GUID"] = "1E32CE44",
            ["NextDialogue"] = 12063003,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120630/1E32CE44",
            },
        [12063003] = {
            ["Content"] = "苏乙姐姐！拜托你，可以去阻止阿姨吗！！",
            ["ContentFR"] = "Su Yi ! S’il te plaît, tu dois arrêter ma tata !",
            ["DialogueId"] = 12063003,
            ["GUID"] = "1E32CE6E",
            ["NextDialogue"] = 12063004,
            ["SpeakNpcId"] = 250017,
            ["VoiceName"] = "voice/$Locale$/story/1206/120630/1E32CE6E",
            },
        [12063004] = {
            ["Content"] = "我听到阿姨和她的朋友们聊天，他们要去袭击赛场，这样就可以栽赃姐姐还有更多人！我想劝阿姨不要这样做，可是她不仅不听我的话，还把我关了起来！！",
            ["ContentFR"] = "Je l’ai entendue parler avec ses amis. Ils veulent attaquer l’arène pour ensuite accuser toi et les autres Vagabonds ! J’ai essayé de l’en empêcher, mais elle n’a rien voulu entendre... et elle m’a même enfermé ici !",
            ["DialogueId"] = 12063004,
            ["GUID"] = "1E32CE98",
            ["NextDialogue"] = 12063005,
            ["SpeakNpcId"] = 250017,
            ["VoiceName"] = "voice/$Locale$/story/1206/120630/1E32CE98",
            },
        [12063005] = {
            ["Content"] = "袭击赛场？糟糕！！",
            ["ContentFR"] = "Attaquer l’arène ?! Oh non...",
            ["DialogueId"] = 12063005,
            ["GUID"] = "1E32CEC2",
            ["NextDialogue"] = 12063006,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120630/1E32CEC2",
            },
        [12063006] = {
            ["Content"] = "她最终还是走到了这一步吗！{nickname}他们，还有更多人恐怕会遇到危险！！",
            ["ContentFR"] = "Elle est vraiment allée jusque-là... {nickname} et les autres — et beaucoup d’autres personnes — pourraient être en danger !",
            ["DialogueId"] = 12063006,
            ["GUID"] = "1E32CEEC",
            ["NextDialogue"] = 12063007,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120630/1E32CEEC",
            },
        [12063007] = {
            ["Content"] = "谢谢你的消息，小安，我这就赶过去。",
            ["ContentFR"] = "Merci de m’avoir prévenue, An. Je pars immédiatement.",
            ["DialogueId"] = 12063007,
            ["GUID"] = "1E32CF16",
            ["NextDialogue"] = 12063008,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120630/1E32CF16",
            },
        [12063008] = {
            ["Content"] = "等等，苏乙姐姐！可以带上我吗？现在的阿姨大概听不进去你说的话！",
            ["ContentFR"] = "Attends, Su Yi ! Tu peux m’emmener avec toi ? Ma tata ne t’écoutera probablement pas... mais elle pourrait peut-être m’écouter, moi !",
            ["DialogueId"] = 12063008,
            ["GUID"] = "1E32CF40",
            ["NextDialogue"] = 12063009,
            ["SpeakNpcId"] = 250017,
            ["VoiceName"] = "voice/$Locale$/story/1206/120630/1E32CF40",
            },
        [12063009] = {
            ["Content"] = "拜托了，请让我一起去吧！我想阻止阿姨走向最坏的结局！",
            ["ContentFR"] = "S’il te plaît ! Laisse-moi venir avec toi ! Je veux empêcher ma tata de commettre l’irréparable !",
            ["DialogueId"] = 12063009,
            ["GUID"] = "1E32CF6A",
            ["NextDialogue"] = 12063010,
            ["SpeakNpcId"] = 250017,
            ["VoiceName"] = "voice/$Locale$/story/1206/120630/1E32CF6A",
            },
        [12063010] = {
            ["Content"] = "好，那我背着你。你小心点不要掉下来。",
            ["ContentFR"] = "D’accord. Je vais te porter sur mon dos. Accroche-toi bien.",
            ["DialogueId"] = 12063010,
            ["GUID"] = "1E32CF94",
            ["NextDialogue"] = 12063011,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120630/1E32CF94",
            },
        [12063011] = {
            ["Content"] = "与此同时，另一边……",
            ["ContentFR"] = "Pendant ce temps, à l’arène…",
            ["DialogueId"] = 12063011,
            ["GUID"] = "1E32CFBE",
            ["IsBlack"] = 1,
            ["VoiceName"] = "voice/$Locale$/story/1206/120630/1E32CFBE",
            },
        [12063012] = {
            ["Content"] = "你们先保护民众，我将他引走。",
            ["ContentFR"] = "Protégez les civils. Je vais l’attirer ailleurs !",
            ["DialogueId"] = 12063012,
            ["GUID"] = "1E32CFBF",
            ["SpeakNpcId"] = 250005,
            ["VoiceName"] = "voice/$Locale$/story/1206/120630/1E32CFBF",
            },
        [12063101] = {
            ["Content"] = "煜明……！",
            ["ContentFR"] = "Yuming... !",
            ["DialogueId"] = 12063101,
            ["GUID"] = "1E32DE82",
            ["NextDialogue"] = 12063102,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120631/1E32DE82",
            },
        [12063102] = {
            ["Content"] = "喂喂，这扇门压根打不开，一条缝隙都没有，你们华胥的门都这么结实的吗？！",
            ["ContentFR"] = "Hé ! Cette porte ne bouge pas du tout ! Pas même une fissure ! Elles sont toutes aussi solides que ça, les portes de Huaxu ?!",
            ["DialogueId"] = 12063102,
            ["GUID"] = "1E32DEAC",
            ["NextDialogue"] = 12063103,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120631/1E32DEAC",
            },
        [12063103] = {
            ["Content"] = "……还是来晚了一步！！",
            ["ContentFR"] = "... Je suis encore arrivée trop tard !",
            ["DialogueId"] = 12063103,
            ["GUID"] = "1E32DED6",
            ["NextDialogue"] = 12063104,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120631/1E32DED6",
            },
        [12063104] = {
            ["Content"] = "苏乙！！巨阙突然从山体里出现，煜明为了阻止它被困在里面了！",
            ["ContentFR"] = "Su Yi ! Le Terracolosse est sorti de la montagne tout à coup ! Yuming est entré pour l’arrêter et il s’est retrouvé coincé à l’intérieur !",
            ["DialogueId"] = 12063104,
            ["GUID"] = "1E32DF00",
            ["NextDialogue"] = 12063105,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120631/1E32DF00",
            },
        [12063105] = {
            ["Content"] = "这扇门看起来像是机枢派的技术，你知道有什么方法能打开它吗？！",
            ["ContentFR"] = "Cette porte ressemble à une construction de la Secte Jishu. Tu saurais comment l’ouvrir ?!",
            ["DialogueId"] = 12063105,
            ["GUID"] = "1E32DF2A",
            ["NextDialogue"] = 12063106,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120631/1E32DF2A",
            },
        [12063106] = {
            ["Content"] = "这里的地宫是机枢派的旧址，与偃隐宫为同一前辈设计。比起外力破解，找到始作俑者会更加迅速。",
            ["ContentFR"] = "Ce complexe souterrain est un ancien site de la Secte Jishu. Il a été conçu par le même maître que le Labyrinthe de Yanyin. Plutôt que d’essayer de l’ouvrir par la force, il sera plus rapide de trouver celui qui a déclenché tout cela.",
            ["DialogueId"] = 12063106,
            ["GUID"] = "1E32DF54",
            ["NextDialogue"] = 12063107,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120631/1E32DF54",
            },
        [12063107] = {
            ["Content"] = "始作俑者？",
            ["ContentFR"] = "Celui qui a déclenché tout ça... ?",
            ["DialogueId"] = 12063107,
            ["GUID"] = "1E32DF7E",
            ["NextDialogue"] = 12063108,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120631/1E32DF7E",
            },
        [12063108] = {
            ["Content"] = "没错，潇湘，以及她的同伴——计划没有按他们预想中去实施，这伙人一定还徘徊在附近寻找机会。",
            ["ContentFR"] = "Oui. Xiaoxiang et ses complices. Leur plan ne s’est pas déroulé comme prévu. Ils doivent encore rôder dans les environs, en attendant une autre occasion.",
            ["DialogueId"] = 12063108,
            ["GUID"] = "1E32DFA8",
            ["NextDialogue"] = 12063109,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120631/1E32DFA8",
            },
        [12063109] = {
            ["Content"] = "喂喂，你怎么突然知道了这么多情报？",
            ["ContentFR"] = "Hé... comment tu sais tout ça, d’un coup ?",
            ["DialogueId"] = 12063109,
            ["GUID"] = "1E32DFD2",
            ["NextDialogue"] = 12063110,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120631/1E32DFD2",
            },
        [12063110] = {
            ["Content"] = "来不及解释了，跟我来。",
            ["ContentFR"] = "Pas le temps d’expliquer. Suivez-moi.",
            ["DialogueId"] = 12063110,
            ["GUID"] = "1E32DFFC",
            ["NextDialogue"] = 12063111,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120631/1E32DFFC",
            },
        [12063111] = {
            ["Content"] = "煜明还困在里面。现在耽误的每分每秒都会增加他受伤的风险！",
            ["ContentFR"] = "Yuming est toujours coincé là-dedans. Chaque seconde qui passe augmente le risque qu’il soit blessé !",
            ["DialogueId"] = 12063111,
            ["GUID"] = "1E32E026",
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120631/1E32E026",
            },
        [12063201] = {
            ["Content"] = "找到你了。",
            ["ContentFR"] = "Je t’ai trouvée.",
            ["DialogueId"] = 12063201,
            ["GUID"] = "1E32EEEA",
            ["NextDialogue"] = 12063202,
            ["RelatedWikiId"] = {
                [1] = 203009,
                [2] = 201029,
                [3] = 103001,
                [4] = 203013,
                [5] = 203014,
                [6] = 408018,
                [7] = 403009,
                },
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120632/1E32EEEA",
            },
        [12063202] = {
            ["Content"] = "快把地宫钥匙交出来，现在还没有人受伤，一切还来得及。",
            ["ContentFR"] = "Donne-nous la clé du complexe souterrain. Personne n’a encore été blessé. On peut encore arrêter ça.",
            ["DialogueId"] = 12063202,
            ["GUID"] = "1E32EF14",
            ["NextDialogue"] = 12063203,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120632/1E32EF14",
            },
        [12063203] = {
            ["Content"] = "呵，被你逮到是我技输一筹，我认输。",
            ["ContentFR"] = "<I>Hmpf.</> Si tu m’as trouvée, c’est que tu as été plus habile que moi. Je l’admets.",
            ["DialogueId"] = 12063203,
            ["GUID"] = "1E32EF3E",
            ["NextDialogue"] = 12063204,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120632/1E32EF3E",
            },
        [12063204] = {
            ["Content"] = "但若是想让我交出地宫钥匙，还是死了这条心吧。我与你没什么话好说的。",
            ["ContentFR"] = "Mais si tu crois que je vais te remettre la clé, tu peux oublier. Je n’ai rien à te dire.",
            ["DialogueId"] = 12063204,
            ["GUID"] = "1E32EF68",
            ["NextDialogue"] = 12063205,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120632/1E32EF68",
            },
        [12063205] = {
            ["Content"] = "够了……你们就恨飘零人恨到即使伤及无辜者的性命也在所不惜吗？！",
            ["ContentFR"] = "Ça suffit... Vous détestez les Vagabonds au point d’être prêts à mettre des innocents en danger ?!",
            ["DialogueId"] = 12063205,
            ["GUID"] = "1E32EF92",
            ["NextDialogue"] = 12063206,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120632/1E32EF92",
            },
        [12063206] = {
            ["Content"] = "如此大义凛然的话从那个苏暮鹧的侄女口中听到，真是让人想笑。",
            ["ContentFR"] = "Entendre ce genre de discours sortir de la bouche de la nièce de Su Muzhe... C’est presque comique.",
            ["DialogueId"] = 12063206,
            ["GUID"] = "1E32EFBC",
            ["NextDialogue"] = 12063207,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120632/1E32EFBC",
            },
        [12063207] = {
            ["Content"] = "如果你和姑姑曾经共事过，你就应该知道她做出那些事究竟是为了什么。",
            ["ContentFR"] = "Si tu as travaillé avec ma tante autrefois, tu sais pourtant pourquoi elle a fait tout cela.",
            ["DialogueId"] = 12063207,
            ["GUID"] = "1E32EFE6",
            ["NextDialogue"] = 12063208,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120632/1E32EFE6",
            },
        [12063208] = {
            ["Content"] = "那般荒诞的理想，就算知道了又能如何？",
            ["ContentFR"] = "Et alors ? Même en le sachant, ça ne change rien. Ses idéaux étaient absurdes.",
            ["DialogueId"] = 12063208,
            ["GUID"] = "1E32F010",
            ["NextDialogue"] = 12063209,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120632/1E32F010",
            },
        [12063209] = {
            ["Content"] = "可如今烛阴归位，大风九章迎来改制——你口中荒诞的理想，如今已经成了现实！",
            ["ContentFR"] = "Regarde autour de toi. Zhuyin est revenu, et les Neuf Chapitres de Dafeng sont en train d’être réformés. Les idéaux que tu qualifies d’absurdes sont en train de devenir réalité.",
            ["DialogueId"] = 12063209,
            ["GUID"] = "1E32F03A",
            ["NextDialogue"] = 12063210,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120632/1E32F03A",
            },
        [12063210] = {
            ["Content"] = "但她所犯下的罪行，她所造成的伤害，绝不会因此一笔勾销。",
            ["ContentFR"] = "Mais les crimes qu’elle a commis... et les souffrances qu’elle a causées... tout cela ne disparaîtra pas pour autant.",
            ["DialogueId"] = 12063210,
            ["GUID"] = "1E32F064",
            ["NextDialogue"] = 12063211,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120632/1E32F064",
            },
        [12063211] = {
            ["Content"] = "……你说得对。",
            ["ContentFR"] = "... Tu as raison.",
            ["DialogueId"] = 12063211,
            ["GUID"] = "1E32F08E",
            ["NextDialogue"] = 12063212,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120632/1E32F08E",
            },
        [12063212] = {
            ["Content"] = "……！！",
            ["ContentFR"] = "... !?",
            ["DialogueId"] = 12063212,
            ["GUID"] = "1E32F0B8",
            ["NextDialogue"] = 12063213,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120632/1E32F0B8",
            },
        [12063213] = {
            ["Content"] = "所以姑姑她，已经得到了应有的制裁。你的复仇早就结束了……",
            ["ContentFR"] = "C’est pour cela que ma tante a déjà payé le prix de ses actes. Ta vengeance s’est terminée le jour de sa mort.",
            ["DialogueId"] = 12063213,
            ["GUID"] = "1E32F0E2",
            ["NextDialogue"] = 12063214,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120632/1E32F0E2",
            },
        [12063214] = {
            ["Content"] = "够了，我对今日的所作所为问心无愧。你说再多也只是徒劳。",
            ["ContentFR"] = "Ça suffit. Je ne regrette rien de ce que j’ai fait aujourd’hui. Tout ce que tu dis est inutile.",
            ["DialogueId"] = 12063214,
            ["GUID"] = "1E32F10C",
            ["NextDialogue"] = 12063215,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120632/1E32F10C",
            },
        [12063215] = {
            ["Content"] = "问心无愧吗？那你听听这个人说什么吧。",
            ["ContentFR"] = "Tu es vraiment sûre de toi ? Alors écoute plutôt ce que cette personne a à dire.",
            ["DialogueId"] = 12063215,
            ["GUID"] = "1E32F136",
            ["NextDialogue"] = 12063216,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120632/1E32F136",
            },
        [12063216] = {
            ["Content"] = "……阿姨。",
            ["ContentFR"] = "... Tata.",
            ["DialogueId"] = 12063216,
            ["GUID"] = "1E32F160",
            ["NextDialogue"] = 12063217,
            ["SpeakNpcId"] = 250017,
            ["VoiceName"] = "voice/$Locale$/story/1206/120632/1E32F160",
            },
        [12063217] = {
            ["Content"] = "收手吧，我们一起回家，好吗？",
            ["ContentFR"] = "Arrête... s’il te plaît. Rentrons à la maison ensemble.",
            ["DialogueId"] = 12063217,
            ["GUID"] = "1E32F18A",
            ["NextDialogue"] = 12063218,
            ["SpeakNpcId"] = 250017,
            ["VoiceName"] = "voice/$Locale$/story/1206/120632/1E32F18A",
            },
        [12063218] = {
            ["Content"] = "…………",
            ["ContentFR"] = "...",
            ["DialogueId"] = 12063218,
            ["GUID"] = "1E32F1B4",
            ["NextDialogue"] = 12063219,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120632/1E32F1B4",
            },
        [12063219] = {
            ["Content"] = "……以为搬出小安就能说服我吗？",
            ["ContentFR"] = "... Tu crois que faire venir An va me faire changer d’avis ?",
            ["DialogueId"] = 12063219,
            ["GUID"] = "1E32F1DE",
            ["NextDialogue"] = 12063220,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120632/1E32F1DE",
            },
        [12063220] = {
            ["Content"] = "这次行动前，我早已想好了。无论成败，我都要与他断绝关系。小安今后也与我再无瓜葛。",
            ["ContentFR"] = "Avant même cette opération, j’avais déjà pris ma décision. Peu importe l’issue, je couperai tout lien avec lui. À partir d’aujourd’hui, An n’aura plus rien à voir avec moi.",
            ["DialogueId"] = 12063220,
            ["GUID"] = "1E32F208",
            ["NextDialogue"] = 12063221,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120632/1E32F208",
            },
        [12063221] = {
            ["Content"] = "听到了吗，养了你这个无亲无故的孩子十几年，我已经受够了。",
            ["ContentFR"] = "Tu entends ? Je t’ai élevé plus de dix ans alors que nous n’avons aucun lien de sang... J’en ai assez.",
            ["DialogueId"] = 12063221,
            ["GUID"] = "1E32F232",
            ["NextDialogue"] = 12063222,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120632/1E32F232",
            },
        [12063222] = {
            ["Content"] = "不，阿姨……好好看一看我吧，看看我的腿！",
            ["ContentFR"] = "Non... tata... Regarde-moi bien... regarde ma jambe !",
            ["DialogueId"] = 12063222,
            ["GUID"] = "1E32F25C",
            ["NextDialogue"] = 12063223,
            ["SpeakNpcId"] = 250017,
            ["VoiceName"] = "voice/$Locale$/story/1206/120632/1E32F25C",
            },
        [12063223] = {
            ["Content"] = "难道是……你真的攻克了那项禁忌的技术……",
            ["ContentFR"] = "Attends... ne me dis pas que... Tu as vraiment réussi à maîtriser cet art interdit... ?",
            ["DialogueId"] = 12063223,
            ["GUID"] = "1E32F286",
            ["NextDialogue"] = 12063224,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120632/1E32F286",
            },
        [12063224] = {
            ["Content"] = "是的！这是苏乙姐姐特地来送给我的机关义肢！！有了它的帮助，以后只要再练习一下，我就能像正常人一样走路了！！",
            ["ContentFR"] = "Oui ! Su Yi m’a fabriqué une prothèse mécanique ! Avec ça... et un peu d’entraînement... je pourrai marcher comme tout le monde !",
            ["DialogueId"] = 12063224,
            ["GUID"] = "1E32F2B0",
            ["NextDialogue"] = 12063225,
            ["SpeakNpcId"] = 250017,
            ["VoiceName"] = "voice/$Locale$/story/1206/120632/1E32F2B0",
            },
        [12063225] = {
            ["Content"] = "但其实就算没有它，我也一直在一个人偷偷练习走路！！因为总有一天，我想用自己的双腿走到阿姨面前，让阿姨不再总是皱着眉，就算付出再多努力也没关系！！",
            ["ContentFR"] = "Mais même avant ça, je m’entraînais déjà en secret ! Parce qu’un jour, je voulais pouvoir marcher jusqu’à toi par mes propres moyens... Je voulais juste que tu arrêtes d’avoir cet air triste... même si je dois travailler très dur pour ça !",
            ["DialogueId"] = 12063225,
            ["GUID"] = "1E32F2DA",
            ["NextDialogue"] = 12063226,
            ["SpeakNpcId"] = 250017,
            ["VoiceName"] = "voice/$Locale$/story/1206/120632/1E32F2DA",
            },
        [12063226] = {
            ["Content"] = "阿姨，你知道吗，这几年来我最难过的事……并不是这条腿。",
            ["ContentFR"] = "Tu sais, tata... Ce qui m’a fait le plus souffrir ces dernières années... ce n’est pas ma jambe.",
            ["DialogueId"] = 12063226,
            ["GUID"] = "1E32F304",
            ["NextDialogue"] = 12063227,
            ["SpeakNpcId"] = 250017,
            ["VoiceName"] = "voice/$Locale$/story/1206/120632/1E32F304",
            },
        [12063227] = {
            ["Content"] = "当我醒过来发现自己的腿已经不在的时候，我难过得要命，痛得要命……但伤口是会随着时间慢慢愈合的！",
            ["ContentFR"] = "Quand je me suis réveillé après l’accident et que j’ai compris que ma jambe avait disparu... j’étais anéanti... la douleur était insupportable... Mais avec le temps, la blessure a fini par cicatriser.",
            ["DialogueId"] = 12063227,
            ["GUID"] = "1E32F32E",
            ["NextDialogue"] = 12063228,
            ["SpeakNpcId"] = 250017,
            ["VoiceName"] = "voice/$Locale$/story/1206/120632/1E32F32E",
            },
        [12063228] = {
            ["Content"] = "我最难过的是……阿姨好像永远被困在那场机关坠毁的事故里，一直无法出来，但我不想看你一直痛苦！",
            ["ContentFR"] = "Ce qui me fait vraiment mal... c’est de te voir encore prisonnière de cet accident, incapable d’en sortir. Je ne veux plus te voir souffrir comme ça !",
            ["DialogueId"] = 12063228,
            ["GUID"] = "1E32F358",
            ["NextDialogue"] = 12063229,
            ["SpeakNpcId"] = 250017,
            ["VoiceName"] = "voice/$Locale$/story/1206/120632/1E32F358",
            },
        [12063229] = {
            ["Content"] = "阿姨总说“小安的一生都被毁了”，但不是这样的！如果把自己关在过去的笼子里，认为自己没有了幸福的资格，那样的人生才是真的被毁掉了啊……",
            ["ContentFR"] = "Tu répètes toujours que « la vie d’An est détruite »... Mais ce n’est pas vrai ! Une vie n’est pas détruite parce qu’on perd une jambe ! Elle l’est quand quelqu’un reste enfermé dans le passé... et pense qu’il n’a plus le droit d’être heureux...",
            ["DialogueId"] = 12063229,
            ["GUID"] = "1E32F382",
            ["NextDialogue"] = 12063230,
            ["SpeakNpcId"] = 250017,
            ["VoiceName"] = "voice/$Locale$/story/1206/120632/1E32F382",
            },
        [12063230] = {
            ["Content"] = "…………",
            ["ContentFR"] = "...",
            ["DialogueId"] = 12063230,
            ["GUID"] = "1E32F3AC",
            ["NextDialogue"] = 12063231,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120632/1E32F3AC",
            },
        [12063231] = {
            ["Content"] = "……我们走吧。",
            ["ContentFR"] = "... Allons-y.",
            ["DialogueId"] = 12063231,
            ["GUID"] = "1E32F3D6",
            ["NextDialogue"] = 12063232,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120632/1E32F3D6",
            },
        [12063232] = {
            ["Content"] = "诶？现在吗？？但是地宫钥匙明明还没有拿到……",
            ["ContentFR"] = "Hein ? Maintenant ? Mais on n’a toujours pas la clé du complexe souterrain !",
            ["DialogueId"] = 12063232,
            ["GUID"] = "1E32F400",
            ["NextDialogue"] = 12063233,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120632/1E32F400",
            },
        [12063233] = {
            ["Content"] = "她如果不愿意开口，我们在这里空耗时间也只是徒劳。不如抓紧回去找其他人打听，有没有其他能打开那扇门的法子……",
            ["ContentFR"] = "Si elle refuse de parler, rester ici ne servira à rien. Mieux vaut retourner voir les autres et chercher un autre moyen d’ouvrir cette porte.",
            ["DialogueId"] = 12063233,
            ["GUID"] = "1E32F42A",
            ["NextDialogue"] = 12063234,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120632/1E32F42A",
            },
        [12063234] = {
            ["Content"] = "……你为了复仇，将无辜的人卷入其中，成为了你最痛恨的样子，甚至罔顾小安的幸福。但我不会变成你的模样。",
            ["ContentFR"] = "... Pour te venger, tu as entraîné des innocents dans cette affaire. Tu es devenue exactement ce que tu prétends détester. Tu étais même prête à sacrifier le bonheur d’An. Mais moi, je ne deviendrai pas comme toi.",
            ["DialogueId"] = 12063234,
            ["GUID"] = "1E32F454",
            ["NextDialogue"] = 12063235,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120632/1E32F454",
            },
        [12063235] = {
            ["Content"] = "我已经发誓过，我不会再让任何人受伤，无论是出于什么样的理由。",
            ["ContentFR"] = "J’ai juré de ne plus laisser personne être blessé... quelle qu’en soit la raison.",
            ["DialogueId"] = 12063235,
            ["GUID"] = "1E32F47E",
            ["NextDialogue"] = 12063236,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120632/1E32F47E",
            },
        [12063236] = {
            ["Content"] = "……",
            ["ContentFR"] = "...",
            ["DialogueId"] = 12063236,
            ["GUID"] = "1E32F4A8",
            ["NextDialogue"] = 12063237,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120632/1E32F4A8",
            },
        [12063237] = {
            ["Content"] = "等等……拿着。",
            ["ContentFR"] = "Attends... Prends ça.",
            ["DialogueId"] = 12063237,
            ["GUID"] = "1E32F4D2",
            ["NextDialogue"] = 12063238,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120632/1E32F4D2",
            },
        [12063238] = {
            ["Content"] = "…………阿姨……太好了！",
            ["ContentFR"] = "... Tata... Merci !",
            ["DialogueId"] = 12063238,
            ["GUID"] = "1E32F4FC",
            ["SpeakNpcId"] = 250017,
            ["VoiceName"] = "voice/$Locale$/story/1206/120632/1E32F4FC",
            },
        [12063301] = {
            ["Content"] = "大当家，真的不需要赶紧请动应天尉，捉拿那些贼人吗？",
            ["ContentFR"] = "Patronne, n’est-il vraiment pas nécessaire de prévenir les Magistrats de Yingtian et de faire arrêter ces criminels ?",
            ["DialogueId"] = 12063301,
            ["GUID"] = "1E32FF52",
