  { MinKey = 12063302, MaxKey = 20000903, Loader = function()
      return {
        [12063302] = {
            ["Content"] = "之前或许还有这个必要，现在却是不必了。",
            ["ContentFR"] = "Autrefois, peut-être. Mais plus maintenant.",
            ["DialogueId"] = 12063302,
            ["GUID"] = "1E32FF7C",
            ["NextDialogue"] = 12063303,
            ["SpeakNpcId"] = 250004,
            ["VoiceName"] = "voice/$Locale$/story/1206/120633/1E32FF7C",
            },
        [12063303] = {
            ["Content"] = "你没有看出来吗？局势已经明朗。看来，这届群英试终于发挥了其应有的作用。",
            ["ContentFR"] = "Tu ne l’as pas remarqué ? La situation est déjà claire. Il semble que cette édition du Tournoi de l’Encens ait enfin rempli son véritable rôle.",
            ["DialogueId"] = 12063303,
            ["GUID"] = "1E32FFA6",
            ["NextDialogue"] = 12063304,
            ["SpeakNpcId"] = 250004,
            ["VoiceName"] = "voice/$Locale$/story/1206/120633/1E32FFA6",
            },
        [12063304] = {
            ["Content"] = "应有的作用……群英试不是用来决出胜者的吗？",
            ["ContentFR"] = "Son véritable rôle... ? Ce tournoi n’est-il pas censé désigner un vainqueur ?",
            ["DialogueId"] = 12063304,
            ["GUID"] = "1E32FFD0",
            ["NextDialogue"] = 12063305,
            ["SpeakNpcId"] = 250026,
            ["VoiceName"] = "voice/$Locale$/story/1206/120633/1E32FFD0",
            },
        [12063305] = {
            ["Content"] = "胜者？呵呵……输赢从来不是这场比赛的重点，群英试从一开始，就是为了创造<H>英雄</>的。",
            ["ContentFR"] = "Un vainqueur ? Héhé... la victoire ou la défaite n’a jamais été le véritable objectif. Depuis le début, ce tournoi existe pour faire naître des <H>héros</>.",
            ["DialogueId"] = 12063305,
            ["GUID"] = "1E32FFFA",
            ["NextDialogue"] = 12063306,
            ["SpeakNpcId"] = 250004,
            ["VoiceName"] = "voice/$Locale$/story/1206/120633/1E32FFFA",
            },
        [12063306] = {
            ["Content"] = "能够以人的力量，人的身姿，克服内心的所有动摇，无论如何弱小迷茫也不会放弃寻求正确之路，如此，才能称为英雄之姿。",
            ["ContentFR"] = "Quelqu’un capable, avec la seule force d’un être humain, de surmonter les hésitations de son cœur, et de continuer à chercher la bonne voie même dans la faiblesse et le doute... Voilà ce que l’on peut appeler la véritable allure d’un héros.",
            ["DialogueId"] = 12063306,
            ["GUID"] = "1E330024",
            ["NextDialogue"] = 12063307,
            ["SpeakNpcId"] = 250004,
            ["VoiceName"] = "voice/$Locale$/story/1206/120633/1E330024",
            },
        [12063307] = {
            ["Content"] = "竟然还有这层用意……不愧是大当家！",
            ["ContentFR"] = "Je vois... Votre clairvoyance est impressionnante, Patronne.",
            ["DialogueId"] = 12063307,
            ["GUID"] = "1E33004E",
            ["NextDialogue"] = 12063308,
            ["SpeakNpcId"] = 250026,
            ["VoiceName"] = "voice/$Locale$/story/1206/120633/1E33004E",
            },
        [12063308] = {
            ["Content"] = "大当家，我有个疑问。怀远、潇湘一伙人的行迹一直在您的掌握之中。中途您有多次机会可以出手阻止他们的计划，为何您没有那样做呢？",
            ["ContentFR"] = "Mais j’ai une question. Vous surveilliez Huaiyuan et le groupe de Xiaoxiang depuis le début. Vous auriez pu intervenir à plusieurs reprises pour arrêter leur plan. Pourquoi ne l’avoir pas fait ?",
            ["DialogueId"] = 12063308,
            ["GUID"] = "1E330078",
            ["NextDialogue"] = 12063309,
            ["SpeakNpcId"] = 250026,
            ["VoiceName"] = "voice/$Locale$/story/1206/120633/1E330078",
            },
        [12063309] = {
            ["Content"] = "那是因为我对他们仍怀有期待。",
            ["ContentFR"] = "Parce que j’avais encore de l’espoir pour eux.",
            ["DialogueId"] = 12063309,
            ["GUID"] = "1E3300A2",
            ["NextDialogue"] = 12063310,
            ["SpeakNpcId"] = 250004,
            ["VoiceName"] = "voice/$Locale$/story/1206/120633/1E3300A2",
            },
        [12063310] = {
            ["Content"] = "我期待他们能够跨越迷障，放弃执行中的计划……但他们最终还是向心中的仇恨屈服了。",
            ["ContentFR"] = "J’espérais qu’ils parviendraient à dépasser leurs illusions et à abandonner leur plan en cours de route... Mais au final, ils ont choisi de céder à la haine qui habitait leur cœur.",
            ["DialogueId"] = 12063310,
            ["GUID"] = "1E3300CC",
            ["NextDialogue"] = 12063311,
            ["SpeakNpcId"] = 250004,
            ["VoiceName"] = "voice/$Locale$/story/1206/120633/1E3300CC",
            },
        [12063311] = {
            ["Content"] = "那些人未能战胜心中的迷障，只能说是一桩憾事。",
            ["ContentFR"] = "Qu’ils n’aient pas réussi à vaincre leurs propres ténèbres... c’est bien regrettable.",
            ["DialogueId"] = 12063311,
            ["GUID"] = "1E3300F6",
            ["NextDialogue"] = 12063312,
            ["SpeakNpcId"] = 250004,
            ["VoiceName"] = "voice/$Locale$/story/1206/120633/1E3300F6",
            },
        [12063312] = {
            ["Content"] = "走吧，我们也当去见证最后的胜利时刻了。",
            ["ContentFR"] = "Allons-y. Il est temps d’assister au moment final de la victoire.",
            ["DialogueId"] = 12063312,
            ["GUID"] = "1E330120",
            ["SpeakNpcId"] = 250004,
            ["VoiceName"] = "voice/$Locale$/story/1206/120633/1E330120",
            },
        [12063313] = {
            ["Content"] = "……！太好了，钥匙到手了！",
            ["ContentFR"] = "... ! On a la clé ! Dépêchons-nous !",
            ["DialogueId"] = 12063313,
            ["GUID"] = "1E33014A",
            ["NextDialogue"] = 12063314,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120633/1E33014A",
            },
        [12063314] = {
            ["Content"] = "加快脚步，煜明还在等着我们！不要让他久等了！",
            ["ContentFR"] = "Yuming nous attend à l’intérieur — ne le faisons pas attendre !",
            ["DialogueId"] = 12063314,
            ["GUID"] = "1E330174",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120633/1E330174",
            },
        [12063315] = {
            ["Content"] = "煜明，我们来了，你还支撑得住吗！",
            ["ContentFR"] = "Yuming, nous sommes là ! Tu tiens toujours le coup ?",
            ["DialogueId"] = 12063315,
            ["GUID"] = "1E33019E",
            ["NextDialogue"] = 12063316,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120633/1E33019E",
            },
        [12063316] = {
            ["Content"] = "并无大碍。与巨阙纠缠这一阵，我已熟悉了它的攻击方式。",
            ["ContentFR"] = "Je vais bien. À force de combattre ce Terracolosse, j’ai fini par comprendre ses attaques.",
            ["DialogueId"] = 12063316,
            ["GUID"] = "1E3301C8",
            ["NextDialogue"] = 12063317,
            ["SpeakNpcId"] = 250005,
            ["VoiceName"] = "voice/$Locale$/story/1206/120633/1E3301C8",
            },
        [12063317] = {
            ["Content"] = "好，我们一起击败它！",
            ["ContentFR"] = "Bien. Alors finissons-en ensemble !",
            ["DialogueId"] = 12063317,
            ["GUID"] = "1E3301F2",
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120633/1E3301F2",
            },
        [12063318] = {
            ["Content"] = "呼……这次，总算是结束了。",
            ["ContentFR"] = "<I>Pfiou...</> cette fois, c’est enfin terminé.",
            ["DialogueId"] = 12063318,
            ["GUID"] = "1E33021C",
            ["NextDialogue"] = 12063319,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120633/1E33021C",
            },
        [12063319] = {
            ["Content"] = "（热烈的鼓掌声）",
            ["ContentFR"] = "(Applaudissements enthousiastes.)",
            ["DialogueId"] = 12063319,
            ["GUID"] = "1E330246",
            ["NextDialogue"] = 12063320,
            ["VoiceName"] = "voice/$Locale$/story/1206/120633/1E330246",
            },
        [12063320] = {
            ["Content"] = "哇啊啊啊，现在是什么情况？！怎么回事，怎么这么多人？！",
            ["ContentFR"] = "Ouaah ! C’est quoi, ce délire ?! Pourquoi il y a autant de monde ?!",
            ["DialogueId"] = 12063320,
            ["GUID"] = "1E330270",
            ["NextDialogue"] = 12063321,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120633/1E330270",
            },
        [12063321] = {
            ["Content"] = "又是那个少年英杰！{nickname}！",
            ["ContentFR"] = "C’est encore {性别:ce jeune homme|cette jeune femme} ! {nickname} !",
            ["DialogueId"] = 12063321,
            ["GUID"] = "1E33029A",
            ["NextDialogue"] = 12063322,
            ["SpeakNpcName"] = "UI_Npc_Name_Yilun",
            ["VoiceName"] = "voice/$Locale$/story/1206/120633/1E33029A",
            },
        [12063322] = {
            ["Content"] = "还有那个飘零人，我就说嘛，飘零人才不是传说中青面獠牙的样子咧！那个两条大辫子的小姑娘还怪可爱的！",
            ["ContentFR"] = "Et la Vagabonde aussi ! Je vous l’avais dit : les Vagabonds ne sont pas ces monstres aux crocs qu’on raconte ! La petite avec ses deux grandes tresses, elle est même plutôt mignonne !",
            ["DialogueId"] = 12063322,
            ["GUID"] = "1E3302C4",
            ["NextDialogue"] = 12063323,
            ["SpeakNpcName"] = "UI_Npc_Name_Yilun",
            ["VoiceName"] = "voice/$Locale$/story/1206/120633/1E3302C4",
            },
        [12063323] = {
            ["Content"] = "我从未亲眼见过飘零人，或许，他们也只是和我们一样的普通人，会迷茫，也会奋起。",
            ["ContentFR"] = "Je n’avais jamais vu de Vagabond de mes propres yeux... Peut-être qu’ils sont juste des gens comme nous. Ils doutent... et ils se relèvent.",
            ["DialogueId"] = 12063323,
            ["GUID"] = "1E3302EE",
            ["SpeakNpcName"] = "UI_Npc_Name_Yilun",
            ["VoiceName"] = "voice/$Locale$/story/1206/120633/1E3302EE",
            },
        [12063401] = {
            ["Content"] = "小仆从，你们终于出来了！你们刚刚说的话做的事情，全都被围观的大家看到了。",
            ["ContentFR"] = "Petit larbin ! Vous êtes enfin sortis ! Tout le monde a vu ce que vous avez dit et fait là-dedans !",
            ["DialogueId"] = 12063401,
            ["GUID"] = "1E330FBA",
            ["NextDialogue"] = 12063402,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120634/1E330FBA",
            },
        [12063402] = {
            ["Content"] = "大家完全知道谁是好人，谁是坏人了！现在他们都在很激烈地讨论着你们的英雄事迹呢！",
            ["ContentFR"] = "Maintenant, ils savent très bien qui sont les gentils et qui sont les méchants ! Ils sont tous en train de parler de vos exploits !",
            ["DialogueId"] = 12063402,
            ["GUID"] = "1E330FE4",
            ["NextDialogue"] = 12063403,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120634/1E330FE4",
            },
        [12063403] = {
            ["Content"] = "只是赛场被搞得一团糟，这下就算要重赛恐怕也要等好久了……",
            ["ContentFR"] = "Mais l’arène est dans un état... Même s’ils veulent refaire une manche, ça risque de prendre un temps fou...",
            ["DialogueId"] = 12063403,
            ["GUID"] = "1E33100E",
            ["NextDialogue"] = 12063404,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120634/1E33100E",
            },
        [12063404] = {
            ["Content"] = "等到那个时候，恐怕我们也已经不在华胥了吧。",
            ["ContentFR"] = "À ce moment-là, on ne sera probablement déjà plus à Huaxu.",
            ["DialogueId"] = 12063404,
            ["GUID"] = "1E331038",
            ["NextDialogue"] = 12063405,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120634/1E331038",
            },
        [12063405] = {
            ["Content"] = "塔比瑟，煜明，到时候只能交给你们咯？",
            ["ContentFR"] = "Tabethe, Yuming... j’imagine que ce sera à vous de gérer la suite.",
            ["DialogueId"] = 12063405,
            ["GUID"] = "1E331062",
            ["NextDialogue"] = 12063406,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120634/1E331062",
            },
        [12063406] = {
            ["Content"] = "诸位多虑了。",
            ["ContentFR"] = "Ne vous inquiétez pas.",
            ["DialogueId"] = 12063406,
            ["GUID"] = "1E33108C",
            ["NextDialogue"] = 12063407,
            ["SpeakNpcId"] = 250004,
            ["VoiceName"] = "voice/$Locale$/story/1206/120634/1E33108C",
            },
        [12063407] = {
            ["Content"] = "无论是在赛场上的优异表现，又或者是在赛场外面对挫折时的反应，你们毫无疑问，是我见过的最优秀的队伍之一。",
            ["ContentFR"] = "Que ce soit par vos performances remarquables dans l’arène, ou par votre attitude face aux difficultés en dehors de celle-ci, vous êtes sans aucun doute l’une des meilleures équipes qu’il m’ait été donné de voir.",
            ["DialogueId"] = 12063407,
            ["GUID"] = "1E3310B6",
            ["NextDialogue"] = 12063408,
            ["SpeakNpcId"] = 250004,
            ["VoiceName"] = "voice/$Locale$/story/1206/120634/1E3310B6",
            },
        [12063408] = {
            ["Content"] = "而更重要的是……你们小队面对突然出现的危机临危不惧，为他人所不能及之勇。",
            ["ContentFR"] = "Et plus important encore... face à une crise soudaine, votre équipe n’a pas flanché. Vous avez fait preuve d’un courage que peu de gens possèdent.",
            ["DialogueId"] = 12063408,
            ["GUID"] = "1E3310E0",
            ["NextDialogue"] = 12063409,
            ["SpeakNpcId"] = 250004,
            ["VoiceName"] = "voice/$Locale$/story/1206/120634/1E3310E0",
            },
        [12063409] = {
            ["Content"] = "这等表现，司事会找不到一定要举行重赛的理由。",
            ["ContentFR"] = "Avec une telle démonstration, le conseil administratif n’a aucune raison d’imposer une revanche.",
            ["DialogueId"] = 12063409,
            ["GUID"] = "1E33110A",
            ["NextDialogue"] = 12063410,
            ["SpeakNpcId"] = 250004,
            ["VoiceName"] = "voice/$Locale$/story/1206/120634/1E33110A",
            },
        [12063410] = {
            ["Content"] = "等一下……止流的意思，莫非是……",
            ["ContentFR"] = "Attends... tu veux dire que...",
            ["DialogueId"] = 12063410,
            ["GUID"] = "1E331134",
            ["NextDialogue"] = 12063411,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120634/1E331134",
            },
        [12063411] = {
            ["Content"] = "狩月逐香队，经过司事会的综合评判，你们已经正式赢得本届奉香群英试的优胜，登上执律阁尽情庆祝吧，你们的胜利毋庸置疑。",
            ["ContentFR"] = "Équipe des Chasseurs d’Encens, après délibération du conseil administratif, vous êtes officiellement déclarés vainqueurs de cette édition du Tournoi de l’Encens. Montez au Pavillon de l’Arbitrage et célébrez comme il se doit : votre victoire ne fait aucun doute.",
            ["DialogueId"] = 12063411,
            ["GUID"] = "1E33115E",
            ["NextDialogue"] = 12063412,
            ["SpeakNpcId"] = 250004,
            ["VoiceName"] = "voice/$Locale$/story/1206/120634/1E33115E",
            },
        [12063412] = {
            ["Content"] = "我们赢了？！",
            ["ContentFR"] = "On a gagné ?!",
            ["DialogueId"] = 12063412,
            ["GUID"] = "1E331188",
            ["NextDialogue"] = 12063413,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120634/1E331188",
            },
        [12063413] = {
            ["Content"] = "嗯，我们赢了，苏乙……苏乙？",
            ["ContentFR"] = "Oui, on a gagné, Su Yi... Su Yi ?",
            ["DialogueId"] = 12063413,
            ["GUID"] = "1E3311B2",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120634/1E3311B2",
            },
        [12063414] = {
            ["Content"] = "找到了，原来她在那里。",
            ["ContentFR"] = "Je l’ai trouvée... elle est là-bas.",
            ["DialogueId"] = 12063414,
            ["GUID"] = "1E3311DC",
            ["NextDialogue"] = 12063415,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120634/1E3311DC",
            },
        [12063415] = {
            ["Content"] = "旁边的那是……潇湘？",
            ["ContentFR"] = "Et la personne à côté d’elle... c’est Xiaoxiang ?",
            ["DialogueId"] = 12063415,
            ["GUID"] = "1E331206",
            ["NextDialogue"] = 12063416,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120634/1E331206",
            },
        [12063416] = {
            ["Content"] = "不知道她们会聊些什么，过去看看吧。",
            ["ContentFR"] = "Je me demande ce qu’elles se disent... allons voir.",
            ["DialogueId"] = 12063416,
            ["GUID"] = "1E331230",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120634/1E331230",
            },
        [12063501] = {
            ["Content"] = "请等一等，让我和她单独聊聊，可以吗？",
            ["ContentFR"] = "Attendez un instant. Pourriez-vous nous laisser parler seules un moment ?",
            ["DialogueId"] = 12063501,
            ["GUID"] = "1E332022",
            ["NextDialogue"] = 12063502,
            ["RelatedWikiId"] = {
                [1] = 203009,
                [2] = 203014,
                [3] = 103001,
                [4] = 407008,
                },
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E332022",
            },
        [12063502] = {
            ["Content"] = "苏乙姑娘是吧，龙渊上卿已有交代，不过还请您注意时间。",
            ["ContentFR"] = "Vous êtes bien Mademoiselle Su Yi ? Le Haut Chancelier de Longyuan a donné ses instructions... mais ne traînez pas.",
            ["DialogueId"] = 12063502,
            ["GUID"] = "1E33204C",
            ["NextDialogue"] = 12063503,
            ["SpeakNpcId"] = 250027,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E33204C",
            },
        [12063503] = {
            ["Content"] = "多谢。",
            ["ContentFR"] = "Merci.",
            ["DialogueId"] = 12063503,
            ["GUID"] = "1E332076",
            ["NextDialogue"] = 12063504,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E332076",
            },
        [12063504] = {
            ["Content"] = "是专程来嘲讽你的手下败将的吗，苏氏传人？",
            ["ContentFR"] = "Alors, héritière du clan Su... tu es venue te moquer de celle que tu as vaincue ?",
            ["DialogueId"] = 12063504,
            ["GUID"] = "1E3320A0",
            ["NextDialogue"] = 12063505,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E3320A0",
            },
        [12063505] = {
            ["Content"] = "不，我是来向你道谢的……",
            ["ContentFR"] = "Non. Je suis venue te remercier...",
            ["DialogueId"] = 12063505,
            ["GUID"] = "1E3320CA",
            ["NextDialogue"] = 12063506,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E3320CA",
            },
        [12063506] = {
            ["Content"] = "谢谢你那个时候愿意把钥匙交出来，为我们争取了宝贵的救援时间。",
            ["ContentFR"] = "Merci d’avoir accepté de remettre la clé à ce moment-là. Cela nous a permis de gagner un temps précieux pour le sauvetage.",
            ["DialogueId"] = 12063506,
            ["GUID"] = "1E3320F4",
            ["NextDialogue"] = 12063507,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E3320F4",
            },
        [12063507] = {
            ["Content"] = "别自作多情了，我这么做只是为了小安。仅此而已。",
            ["ContentFR"] = "Ne t’imagine pas des choses. Je l’ai fait pour An. Rien de plus.",
            ["DialogueId"] = 12063507,
            ["GUID"] = "1E33211E",
            ["NextDialogue"] = 12063508,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E33211E",
            },
        [12063508] = {
            ["Content"] = "而且，这不代表我原谅了昔日种种，给我记住。",
            ["ContentFR"] = "Et ne crois pas que cela signifie que je pardonne ce qui s’est passé. Souviens-t’en bien.",
            ["DialogueId"] = 12063508,
            ["GUID"] = "1E332148",
            ["NextDialogue"] = 12063509,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E332148",
            },
        [12063509] = {
            ["Content"] = "嗯，我知道。",
            ["ContentFR"] = "Oui. Je le sais.",
            ["DialogueId"] = 12063509,
            ["GUID"] = "1E332172",
            ["NextDialogue"] = 12063510,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E332172",
            },
        [12063510] = {
            ["Content"] = "不管你怎么说，你愿意踏出这一步……我很高兴。",
            ["ContentFR"] = "Quoi que tu en dises, tu as fait ce pas... et ça me fait plaisir.",
            ["DialogueId"] = 12063510,
            ["GUID"] = "1E33219C",
            ["NextDialogue"] = 12063511,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E33219C",
            },
        [12063511] = {
            ["Content"] = "我曾经无数次想过，为何机枢派妄受非议，为何飘零人心生叛逆，为何大风九章如此蛮横强硬，为什么人们时常无法理解彼此……",
            ["ContentFR"] = "Je me suis souvent demandé pourquoi la Secte Jishu était si mal jugée... pourquoi les Vagabonds ont fini par se rebeller... pourquoi les Neuf Chapitres de Dafeng sont si rigides... pourquoi les gens ont tant de mal à se comprendre...",
            ["DialogueId"] = 12063511,
            ["GUID"] = "1E3321C6",
            ["NextDialogue"] = 12063512,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E3321C6",
            },
        [12063512] = {
            ["Content"] = "只可惜，无论再怎么懂得机枢工造，被旁人称作天才，我也只不过是数千年的历史中，一个再普通不过的庸人罢了。",
            ["ContentFR"] = "Mais même si certains me qualifient de génie dans la fabrication de méchapoupées, au fond je ne suis qu’une personne ordinaire parmi des milliers d’années d’histoire.",
            ["DialogueId"] = 12063512,
            ["GUID"] = "1E3321F0",
            ["NextDialogue"] = 12063513,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E3321F0",
            },
        [12063513] = {
            ["Content"] = "我想不明白这个问题的答案，也不知道如何才能根绝纷争。曾经的悬衡派为了消灭纷争封印烛阴，但这片土地并没有因此变得更好。",
            ["ContentFR"] = "Je n’ai pas la réponse à ces questions, et je ne sais pas comment mettre fin aux conflits. Autrefois, la Secte Xuanheng a scellé Zhuyin pour mettre fin aux troubles... mais cette terre ne s’en est pas trouvée meilleure.",
            ["DialogueId"] = 12063513,
            ["GUID"] = "1E33221A",
            ["NextDialogue"] = 12063514,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E33221A",
            },
        [12063514] = {
            ["Content"] = "我想，人与人终究是想法不同的，即使烛阴之灾结束，大风九章重启，人们也还是会因为各种各样的原因争论，冲突……",
            ["ContentFR"] = "Je pense que les gens auront toujours des idées différentes. Même si le Fléau de Zhuyin a pris fin et que les Neuf Chapitres de Dafeng ont été réformés, les gens continueront à se disputer et à s’opposer pour toutes sortes de raisons...",
            ["DialogueId"] = 12063514,
            ["GUID"] = "1E332244",
            ["NextDialogue"] = 12063515,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E332244",
            },
        [12063515] = {
            ["Content"] = "我所能做的，也就只是倾尽我的所有，试着去治愈曾经的冲突所造成的伤痛。",
            ["ContentFR"] = "La seule chose que je puisse faire, c’est donner tout ce que je peux pour tenter de guérir les blessures laissées par ces conflits.",
            ["DialogueId"] = 12063515,
            ["GUID"] = "1E33226E",
            ["NextDialogue"] = 12063516,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E33226E",
            },
        [12063516] = {
            ["Content"] = "弥合些皮肉之伤罢了。",
            ["ContentFR"] = "Tout au plus... tu ne feras que panser quelques plaies.",
            ["DialogueId"] = 12063516,
            ["GUID"] = "1E332298",
            ["NextDialogue"] = 12063517,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E332298",
            },
        [12063517] = {
            ["Content"] = "嗯，但这就是我眼下能够做到的事。",
            ["ContentFR"] = "Oui. Mais pour l’instant, c’est tout ce que je peux faire.",
            ["DialogueId"] = 12063517,
            ["GUID"] = "1E3322C2",
            ["NextDialogue"] = 12063518,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E3322C2",
            },
        [12063518] = {
            ["Content"] = "在那之后，我也会竭尽所能，让你与我经历的事不再上演。",
            ["ContentFR"] = "Et après cela, je ferai tout ce qui est en mon pouvoir pour que ce que toi et moi avons vécu ne se reproduise plus.",
            ["DialogueId"] = 12063518,
            ["GUID"] = "1E3322EC",
            ["NextDialogue"] = 12063519,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E3322EC",
            },
        [12063519] = {
            ["Content"] = "就凭你？",
            ["ContentFR"] = "Toi ? Tu plaisantes.",
            ["DialogueId"] = 12063519,
            ["GUID"] = "1E332316",
            ["NextDialogue"] = 12063520,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E332316",
            },
        [12063520] = {
            ["Content"] = "还有你，还有所有为了这个目标一同努力的人，就像千百年来，一直尝试着改变大风九章的人们一样。",
            ["ContentFR"] = "Pas seule. Avec toi... et avec tous ceux qui voudront poursuivre cet objectif. Depuis des siècles, des gens tentent de changer les Neuf Chapitres de Dafeng.",
            ["DialogueId"] = 12063520,
            ["GUID"] = "1E332340",
            ["NextDialogue"] = 12063521,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E332340",
            },
        [12063521] = {
            ["Content"] = "现在，他们已经成功了，该轮到我们了。",
            ["ContentFR"] = "Aujourd’hui, ils y sont enfin parvenus. Maintenant, c’est à notre tour.",
            ["DialogueId"] = 12063521,
            ["GUID"] = "1E33236A",
            ["NextDialogue"] = 12063522,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E33236A",
            },
        [12063522] = {
            ["Content"] = "无论如何，你放弃了你们的计划，阻止了那台失控的机关巨阙。你还有我，我们已经共同踏出了第一步。",
            ["ContentFR"] = "Quoi que tu en dises, tu as renoncé à ton plan et tu as aidé à arrêter ce Terracolosse devenu incontrôlable. Toi et moi... on a déjà fait le premier pas.",
            ["DialogueId"] = 12063522,
            ["GUID"] = "1E332394",
            ["NextDialogue"] = 12063523,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E332394",
            },
        [12063523] = {
            ["Content"] = "也许我们也会成为不靠谱的前辈，只能把写了一半的答卷留给后人，甚至已经写好的部分也有可能是错误答案……",
            ["ContentFR"] = "Peut-être que nous deviendrons des prédécesseurs imparfaits... laissant aux générations suivantes une réponse incomplète. Peut-être même que ce que nous aurons accompli sera erroné...",
            ["DialogueId"] = 12063523,
            ["GUID"] = "1E3323BE",
            ["NextDialogue"] = 12063524,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E3323BE",
            },
        [12063524] = {
            ["Content"] = "但我相信，我们一定可以离那个未来更近一些，再近一些……一步一步。",
            ["ContentFR"] = "Mais je crois que nous pouvons nous rapprocher un peu plus de cet avenir... pas à pas.",
            ["DialogueId"] = 12063524,
            ["GUID"] = "1E3323E8",
            ["NextDialogue"] = 12063525,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E3323E8",
            },
        [12063525] = {
            ["Content"] = "……天真，甚至近乎愚昧。",
            ["ContentFR"] = "... Naïf. Presque stupide.",
            ["DialogueId"] = 12063525,
            ["GUID"] = "1E332412",
            ["NextDialogue"] = 12063526,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E332412",
            },
        [12063526] = {
            ["Content"] = "时间差不多了，该上路了。",
            ["ContentFR"] = "Le temps est écoulé. On y va.",
            ["DialogueId"] = 12063526,
            ["GUID"] = "1E33243C",
            ["NextDialogue"] = 12063527,
            ["SpeakNpcId"] = 250027,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E33243C",
            },
        [12063527] = {
            ["Content"] = "即便身为阶下之囚，我也会一直看着你……",
            ["ContentFR"] = "Même derrière les barreaux... je continuerai à t’observer.",
            ["DialogueId"] = 12063527,
            ["GUID"] = "1E332466",
            ["NextDialogue"] = 12063528,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E332466",
            },
        [12063528] = {
            ["Content"] = "别让我看笑话，苏氏传人。",
            ["ContentFR"] = "Ne me déçois pas, héritière du clan Su.",
            ["DialogueId"] = 12063528,
            ["GUID"] = "1E332490",
            ["NextDialogue"] = 12063529,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E332490",
            },
        [12063529] = {
            ["Content"] = "{nickname}，谢谢你一直指引我走到这一步。",
            ["ContentFR"] = "{nickname}... merci de m’avoir guidée jusqu’ici.",
            ["DialogueId"] = 12063529,
            ["GUID"] = "1E3324BA",
            ["NextDialogue"] = 12063530,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E3324BA",
            },
        [12063530] = {
            ["Content"] = "我并没有做什么。",
            ["ContentFR"] = "Je n’ai rien fait de spécial.",
            ["DialogueId"] = 12063530,
            ["GUID"] = "1E3324E4",
            ["NextDialogue"] = 12063531,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E3324E4",
            },
        [12063531] = {
            ["Content"] = "真要说我有帮上什么忙，大概只是见证你用自己的意志一步一步走到这里吧。",
            ["ContentFR"] = "Si j’ai aidé d’une quelconque façon, c’est simplement en étant là pour te voir avancer, pas à pas, par ta propre volonté.",
            ["DialogueId"] = 12063531,
            ["GUID"] = "1E33250E",
            ["NextDialogue"] = 12063532,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E33250E",
            },
        [12063532] = {
            ["Content"] = "既然这样，那就见证我直到今天的最后一刻吧。",
            ["ContentFR"] = "Alors... reste avec moi et sois témoin de la toute fin de cette journée.",
            ["DialogueId"] = 12063532,
            ["GUID"] = "1E332538",
            ["NextDialogue"] = 12063533,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E332538",
            },
        [12063533] = {
            ["Content"] = "走吧，一起去执律阁，享受属于我们的胜利时刻！",
            ["ContentFR"] = "Allons-y. Allons au Pavillon de l’Arbitrage et profitons de notre moment de victoire !",
            ["DialogueId"] = 12063533,
            ["GUID"] = "1E332562",
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E332562",
            },
        [12063534] = {
            ["Content"] = "准备好了吗？",
            ["ContentFR"] = "Tu es prête ?",
            ["DialogueId"] = 12063534,
            ["GUID"] = "1E33258C",
            ["NextDialogue"] = 12063535,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E33258C",
            },
        [12063535] = {
            ["Content"] = "嗯。",
            ["ContentFR"] = "Oui.",
            ["DialogueId"] = 12063535,
            ["GUID"] = "1E3325B6",
            ["NextDialogue"] = 12063536,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E3325B6",
            },
        [12063536] = {
            ["Content"] = "昊天苍苍，玄水泱泱。",
            ["ContentFR"] = "Vaste est le Ciel ; profondes sont les eaux sombres.",
            ["DialogueId"] = 12063536,
            ["GUID"] = "1E3325E0",
            ["NextDialogue"] = 12063537,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E3325E0",
            },
        [12063537] = {
            ["Content"] = "华胥承祀，爰奉馨香。",
            ["ContentFR"] = "Huaxu perpétue les rites et offre l’encens sacré.",
            ["DialogueId"] = 12063537,
            ["GUID"] = "1E33260A",
            ["NextDialogue"] = 12063538,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E33260A",
            },
        [12063538] = {
            ["Content"] = "润其五谷，泽彼田桑。",
            ["ContentFR"] = "Que la pluie nourrisse les moissons et abreuve les champs.",
            ["DialogueId"] = 12063538,
            ["GUID"] = "1E332634",
            ["NextDialogue"] = 12063539,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E332634",
            },
        [12063539] = {
            ["Content"] = "禔福兆民，惠汲四方。",
            ["ContentFR"] = "Que la bénédiction s’étende aux peuples et aux terres.",
            ["DialogueId"] = 12063539,
            ["GUID"] = "1E33265E",
            ["NextDialogue"] = 12063540,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E33265E",
            },
        [12063540] = {
            ["Content"] = "永锡丰年，以宁万邦。",
            ["ContentFR"] = "Que les années d’abondance perdurent et apportent la paix à tous les royaumes.",
            ["DialogueId"] = 12063540,
            ["GUID"] = "1E332688",
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E332688",
            },
        [12063601] = {
            ["Content"] = "每个人的力量都是如此渺小，或许往后数十载，人们仍会对飘零人心生畏惧。",
            ["ContentFR"] = "La force de chacun d’entre nous est si infime... Peut-être que dans des décennies encore, les gens continueront de craindre les Vagabonds.",
            ["DialogueId"] = 12063601,
            ["GUID"] = "1E33308A",
            ["NextDialogue"] = 12063602,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120636/1E33308A",
            },
        [12063602] = {
            ["Content"] = "或许即便付出一切，直至行将就木，我也无法见到人们彻底摒弃往日恩怨齐心协力的那一日。",
            ["ContentFR"] = "Peut-être que même en donnant tout ce que j’ai, jusqu’à la fin de ma vie, je ne verrai jamais le jour où les gens abandonneront leurs vieilles rancœurs pour avancer ensemble.",
            ["DialogueId"] = 12063602,
            ["GUID"] = "1E3330B4",
            ["NextDialogue"] = 12063603,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120636/1E3330B4",
            },
        [12063603] = {
            ["Content"] = "姐姐，那个机关鸟儿是怎么飞起来的呀？",
            ["ContentFR"] = "Mademoiselle... comment cet oiseau mécanique peut-il voler ?",
            ["DialogueId"] = 12063603,
            ["GUID"] = "1E3330DE",
            ["NextDialogue"] = 12063604,
            ["SpeakNpcId"] = 250025,
            ["VoiceName"] = "voice/$Locale$/story/1206/120636/1E3330DE",
            },
        [12063604] = {
            ["Content"] = "但，我已经走上了这条道路。还有很多人，与我一起走上了这条道路——纵使星火黯然，改变也已然到来。",
            ["ContentFR"] = "Mais j’ai déjà choisi cette voie. Et beaucoup d’autres marchent à mes côtés sur ce chemin — même une étincelle vacillante peut allumer un changement... et ce changement a déjà commencé.",
            ["DialogueId"] = 12063604,
            ["GUID"] = "1E333108",
            ["NextDialogue"] = 12063605,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120636/1E333108",
            },
        [12063605] = {
            ["Content"] = "你看到了吗，姑姑？",
            ["ContentFR"] = "Tu vois cela, ma tante ?",
            ["DialogueId"] = 12063605,
            ["GUID"] = "1E333132",
            ["NextDialogue"] = 12063606,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120636/1E333132",
            },
        [12063606] = {
            ["Content"] = "小妹妹，想学吗？",
            ["ContentFR"] = "Petite, tu veux apprendre ?",
            ["DialogueId"] = 12063606,
            ["GUID"] = "1E33315C",
            ["NextDialogue"] = 12063607,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120636/1E33315C",
            },
        [12063607] = {
            ["Content"] = "——那便来当姐姐的第一个“学生”，好不好？",
            ["ContentFR"] = "Alors... veux-tu devenir ma première élève ?",
            ["DialogueId"] = 12063607,
            ["GUID"] = "1E333186",
            ["VoiceName"] = "voice/$Locale$/story/1206/120636/1E333186",
            },
        [12063701] = {
            ["Content"] = "一日后 浮星埠",
            ["ContentFR"] = "Un jour plus tard — Quai-aux-Étoiles.",
            ["DialogueId"] = 12063701,
            ["GUID"] = "1E3340F2",
            ["NextDialogue"] = 12063702,
            ["VoiceName"] = "voice/$Locale$/story/1206/120637/1E3340F2",
            },
        [12063702] = {
            ["Content"] = "小仆从，这次我们是真的要离开华胥了吧？",
            ["ContentFR"] = "Petit larbin, cette fois on quitte vraiment Huaxu, n’est-ce pas ?",
            ["DialogueId"] = 12063702,
            ["GUID"] = "1E33411C",
            ["NextDialogue"] = 12063703,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120637/1E33411C",
            },
        [12063703] = {
            ["Content"] = "这么平平淡淡，没有波折，没有陷阱，没有奇怪的人突然冒出来阻止我们，还有点不习惯呢……",
            ["ContentFR"] = "Tout est tellement... calme. Pas de rebondissements, pas de pièges, pas d’étranges personnages surgissant pour nous barrer la route... j’ai presque du mal à m’y habituer.",
            ["DialogueId"] = 12063703,
            ["GUID"] = "1E334146",
            ["NextDialogue"] = 12063704,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120637/1E334146",
            },
        [12063704] = {
            ["Content"] = "呵呵……怎么，需要我扮演“奇怪的人”再来热情好客地阻拦一下你们的归程吗？",
            ["ContentFR"] = "Héhé... Alors, veux-tu que je joue le rôle de « l’étrange personnage » et que je vienne vous retenir chaleureusement avant votre départ ?",
            ["DialogueId"] = 12063704,
            ["GUID"] = "1E334170",
            ["NextOptions"] = {
                [1] = 12063705,
                },
            ["SpeakNpcId"] = 250004,
            ["VoiceName"] = "voice/$Locale$/story/1206/120637/1E334170",
            },
        [12063705] = {
            ["Content"] = "白，闭嘴！",
            ["ContentFR"] = "<I>Snow, tais-toi !</>",
            ["DialogueId"] = 12063705,
            ["GUID"] = "1E33419A",
            ["NextDialogue"] = 12063706,
            },
        [12063706] = {
            ["Content"] = "不不不不还是不用了！",
            ["ContentFR"] = "Non non non, finalement ça ira !",
            ["DialogueId"] = 12063706,
            ["GUID"] = "1E3341C4",
            ["NextDialogue"] = 12063707,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120637/1E3341C4",
            },
        [12063707] = {
            ["Content"] = "白，{nickname}——",
            ["ContentFR"] = "Snow, {nickname} —",
            ["DialogueId"] = 12063707,
            ["GUID"] = "1E3341EE",
            ["NextDialogue"] = 12063708,
            ["VoiceName"] = "voice/$Locale$/story/1206/120637/1E3341EE",
            },
        [12063708] = {
            ["Content"] = "你们……怎么都来了？",
            ["ContentFR"] = "Vous... pourquoi vous-êtes tous là ?",
            ["DialogueId"] = 12063708,
            ["GUID"] = "1E334218",
            ["NextDialogue"] = 12063709,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120637/1E334218",
            },
        [12063709] = {
            ["Content"] = "自然是来送别你了！要是你回到那个叫冰湖城的地方被人欺负了，给我写封信，兄弟我不远千里也要来两肋插刀，帮你打架！",
            ["ContentFR"] = "Évidemment pour te dire au revoir ! Si jamais quelqu’un t’embête quand tu retourneras à Givrelac, écris-moi une lettre. Peu importe la distance, je viendrai te donner un coup de main, {性别:frérot|sœurette} !",
            ["DialogueId"] = 12063709,
            ["GUID"] = "1E334242",
            ["NextDialogue"] = 12063710,
            ["SpeakNpcId"] = 250002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120637/1E334242",
            },
        [12063710] = {
            ["Content"] = "{nickname}，你要走了吗？保重。愿你平安无虞。但若是不慎有了伤痛，扶疏随时愿来为你治疗。",
            ["ContentFR"] = "{nickname}, tu pars donc... Prends soin de toi. Puisses-tu rester {性别:sain et sauf|saine et sauve}. Mais si jamais la blessure ou la maladie te frappe, appelle-moi — Je viendrai te soigner.",
            ["DialogueId"] = 12063710,
            ["GUID"] = "1E33426C",
            ["NextDialogue"] = 12063711,
            ["SpeakNpcId"] = 250001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120637/1E33426C",
            },
        [12063711] = {
            ["Content"] = "此去一别，山高水远。愿君万事顺遂。",
            ["ContentFR"] = "Après ce départ, montagnes et rivières nous sépareront. Puisses-tu voir tous tes projets se réaliser.",
            ["DialogueId"] = 12063711,
            ["GUID"] = "1E334296",
            ["NextDialogue"] = 12063712,
            ["SpeakNpcId"] = 250005,
            ["VoiceName"] = "voice/$Locale$/story/1206/120637/1E334296",
            },
        [12063712] = {
            ["Content"] = "……呼。昨天比赛胜利后有好多好多事情要处理，又熬了个通宵，差一点没赶过来。",
            ["ContentFR"] = "... Haa... haa... Après la victoire d’hier, il y avait tant de choses à régler... j’ai encore passé une nuit blanche. J’ai failli ne pas arriver à temps.",
            ["DialogueId"] = 12063712,
            ["GUID"] = "1E3342C0",
            ["NextDialogue"] = 12063713,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120637/1E3342C0",
            },
        [12063713] = {
            ["Content"] = "但是，{nickname}，有些话，我一定要当面和你说出口！",
            ["ContentFR"] = "Mais {nickname}... il y a quelque chose que je dois absolument te dire en face !",
            ["DialogueId"] = 12063713,
            ["GUID"] = "1E3342EA",
            ["NextDialogue"] = 12063714,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120637/1E3342EA",
            },
        [12063714] = {
            ["Content"] = "谢谢你帮助我认清了自己真正想要做的事情……谢谢你！你一定也有不顾一切都想做的事情吧，你一定能做到的！",
            ["ContentFR"] = "Merci de m’avoir aidée à comprendre ce que je veux vraiment faire... merci ! Et toi aussi, tu dois avoir quelque chose pour lequel tu serais {性别:prêt|prête} à tout risquer, n’est-ce pas ? Je suis sûre que tu y arriveras !",
            ["DialogueId"] = 12063714,
            ["GUID"] = "1E334314",
            ["NextDialogue"] = 12063715,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120637/1E334314",
            },
        [12063715] = {
            ["Content"] = "多写信回来——还有，不要忘了大家！",
            ["ContentFR"] = "Écris-nous souvent... et ne nous oublie pas !",
            ["DialogueId"] = 12063715,
            ["GUID"] = "1E33433E",
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120637/1E33433E",
            },
        [12063801] = {
            ["Content"] = "扫描完成……正在建立追踪路径……",
            ["ContentFR"] = "Analyse terminée... itinéraire de poursuite établi...",
            ["DialogueId"] = 12063801,
            ["GUID"] = "1E33515A",
            ["NextDialogue"] = 12063802,
            ["SnapShot"] = "ROBOT",
            ["SpeakNpcName"] = "UI_Npc_Name_Qingluan",
            ["VoiceName"] = "voice/$Locale$/story/1206/120638/1E33515A",
            },
        [12063802] = {
            ["Content"] = "来，跟上青鸾贰型，它会为我们指明潇湘藏身的位置！",
            ["ContentFR"] = "Vite, suivez le Qingluan Type II ! Il va nous indiquer où Xiaoxiang se cache !",
            ["DialogueId"] = 12063802,
            ["GUID"] = "1E335184",
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120638/1E335184",
            },
        [20000401] = {
            ["Content"] = "喂。",
            ["ContentFR"] = "Hé.",
            ["DialogueId"] = 20000401,
            ["Duration"] = 3,
            ["GUID"] = "3211A3CA",
            ["NextDialogue"] = 20000402,
            ["SpeakNpcId"] = 200024,
            ["VoiceName"] = "voice/$Locale$/story/2001/200004/3211A3CA",
            },
        [20000402] = {
            ["Content"] = "我说，那边的年轻人……",
            ["ContentFR"] = "Hé, toi là-bas... {性别:le gamin|la gamine}.",
            ["DialogueId"] = 20000402,
            ["Duration"] = 3,
            ["GUID"] = "3211A3CB",
            ["SpeakNpcId"] = 200024,
            ["VoiceName"] = "voice/$Locale$/story/2001/200004/3211A3CB",
