            ["SpeakNpcId"] = 200024,
            ["VoiceName"] = "voice/$Locale$/story/2001/200005/3211B5AC",
            },
        [20000511] = {
            ["Content"] = "其实呢，刚刚你们路过的时候啊，老朽嗅到了了不得的东西。",
            ["ContentFR"] = "En vérité, en vous voyant passer à l’instant, mes vieux instincts se sont éveillés...",
            ["DialogueId"] = 20000511,
            ["Duration"] = 2,
            ["FacialId"] = {
