            ["VoiceName"] = "voice/$Locale$/story/2001/200005/3211B750",
            },
        [20000520] = {
            ["Camera"] = "47.933167,48.183594,106.281372,0.000106,0.998942,164.023529,50.0,162.033707,false,Manual,14.755679",
            ["Content"] = "从我记事起，这把剑就在我身边了。也许是我父母留下的?",
            ["ContentFR"] = "Elle a toujours été à mes côtés. Peut-être un héritage de mes parents ?",
            ["DialogueId"] = 20000520,
            ["Duration"] = 2,
            ["ExStoryInfo"] = "Player",
            ["FacialId"] = {
                [1] = "100001:Shock01",
                },
            ["GUID"] = "3211B77A",
