            ["TalkOptions"] = {
                [1] = 200005261,
                [2] = 200005262,
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200005/3211B876",
            },
        [20000528] = {
            ["Camera"] = "112.837646,-162.337891,36.354004,0.000129,8.798526,128.416595,50.000008,421.26944,false,Manual,6.435696",
            ["Content"] = "嗬……年轻人的表情，这是在怀疑老朽吧。",
            ["ContentFR"] = "Hmpf... je vois bien que tu es sceptique, tu doutes de moi, pas vrai ?",
            ["DialogueId"] = 20000528,
