        [20000531] = {
            ["Camera"] = "-7.611328,-33.099121,102.976074,0.0,0.0,129.770859,35.0,211.517212,false,Manual,3.358988",
            ["Content"] = "（没错，身为皎皎之民的白就是一个热心肠的孩子。更何况，我身上也没什么值钱的东西，一名铁匠又能图谋什么呢？）",
            ["ContentFR"] = "Elle a raison. C’est dans leur nature : Snow en est la preuve vivante. Et puis... qu’aurait-elle donc à gagner d’un duo qui n’a rien à offrir ?",
            ["DialogueId"] = 20000531,
            ["DialoguePanelType"] = "Voiceover",
            ["DisableMouth"] = 1,
            ["Duration"] = 2,
            ["FacialId"] = {
                [1] = "100001:Confident01",
                },
            ["FinalCamera"] = "-15.199463,-23.983398,104.64917,0.0,0.0,129.770859,35.0,211.517212,false,Manual,3.358988",
