        [20000602] = {
            ["Camera"] = "-160.725159,-13.358643,119.220985,0.0,4.999999,-2.79654,35.0,142.092117,false,Manual,5.04021",
            ["Content"] = "说起来，我在路上也看到了和白、铁匠前辈长得很相似的人。她们也是<H>皎皎之民</>吗？",
            ["ContentFR"] = "Au fait, j’ai croisé sur la route d’autres personnes qui te ressemblent, toi et Snow. Ce sont aussi des <H>Lunariens</> ?",
            ["DialogueId"] = 20000602,
            ["Duration"] = 2,
            ["ExStoryInfo"] = "Player",
