        [20000603] = {
            ["Camera"] = "-4.034668,-120.357422,84.402077,0.00001,-0.800252,111.203094,25.0,279.088654,false,Manual,4.45866",
            ["Content"] = "年轻人，你是不是从什么偏僻地方来的？",
            ["ContentFR"] = "Dis-moi, {性别:gamin|gamine}, tu viens d’un village perdu ou quoi ?",
            ["DialogueId"] = 20000603,
            ["Duration"] = 3,
            ["GUID"] = "3211C4EE",
