            },
        [20000604] = {
            ["Camera"] = "172.062653,-1154.075806,143.87851,0.0,0.0,89.999985,25.0,200.0,false,Disable,2.8",
            ["Content"] = "是的……我的故乡确实不算繁华。",
            ["ContentFR"] = "Oui... Mon village est plutôt isolé.",
            ["DialogueId"] = 20000604,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "Player",
            ["FacialId"] = {
                [1] = "100001:Ahaha02",
                },
            ["FinalCamera"] = "172.062653,-1154.075806,164.062302,-0.0,-0.999987,89.999985,25.0,200.0,false,Disable,2.8",
            ["GUID"] = "3211C518",
            ["NextDialogue"] = 20000605,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Sigh_Start",
                },
            ["ToFinalCameraBlendTime"] = 6,
            ["VoiceName"] = "voice/$Locale$/story/2001/200006/3211C518",
            },
        [20000605] = {
            ["Camera"] = "375.018433,-82.650635,97.525391,0.000002,-1.800014,165.397888,25.0,200.0,false,Disable,2.8",
            ["Content"] = "哈哈，难怪，难怪。毕竟在老朽走过的地方啊，有人类的地方就有皎皎之民。像你这样没见过我们一族的孩子，已经不多啦。",
            ["ContentFR"] = "Haha ! Ça explique tout. Dans tous les endroits que j’ai traversés, là où vivent les humains, il y a toujours des Lunariens. Des gens comme toi, qui n’ont jamais entendu parler de nous, il n’en reste plus beaucoup.",
            ["DialogueId"] = 20000605,
            ["Duration"] = 1.5,
            ["FacialId"] = {
                [1] = "200024:Ahaha02",
                },
            ["FinalCamera"] = "356.082672,-77.70874,94.312401,0.000002,-1.800014,165.397888,25.0,200.0,false,Disable,2.8",
            ["GUID"] = "3211C542",
            ["NextOptions"] = {
                [1] = 200006051,
                },
            ["SpeakNpcId"] = 200024,
            ["SpeakNpcName"] = "UI_Npc_Name_Duanzao",
            ["TalkActionId"] = {
                [1] = "100001:Sigh_End",
                },
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/2001/200006/3211C542",
            },
        [20000606] = {
            ["Camera"] = "155.926254,-348.624268,84.660477,0.0,-0.799986,116.795898,25.0,200.0,false,Disable,2.8",
            ["Content"] = "我们皎皎呀，每个人都和白长得—样可爱，而且拥有很长的寿命。",
            ["ContentFR"] = "Nous, les Lunariens, on se ressemble tous — aussi adorables que moi, évidemment — et nous vivons très, très longtemps.",
            ["DialogueId"] = 20000606,
            ["Duration"] = 3,
            ["FacialId"] = {
                [1] = "200002:Confident01",
                },
            ["GUID"] = "3211C56C",
            ["LookAt"] = {
                [1] = "100001:n(200002)",
                [2] = "200002:n(100001)",
                [3] = "200024:n(200002)",
                },
            ["NextDialogue"] = 20000607,
            ["SpeakNpcId"] = 200002,
            ["TurnTo"] = {
                [1] = "200002:n(100001)",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200006/3211C56C",
            },
        [20000607] = {
            ["Camera"] = "-55.37558,-141.429932,74.678345,0.000005,-1.600122,102.597961,25.0,136.939529,false,Manual,2.8",
            ["Content"] = "而且就像铁匠前辈—样，大家每个人都有很擅长的事！",
            ["ContentFR"] = "Et comme cette incroyable forgeronne-là, chacun de nous possède un talent unique !",
            ["DialogueId"] = 20000607,
            ["Duration"] = 3,
            ["FacialId"] = {
                [1] = "200002:Happy01",
                },
            ["GUID"] = "3211C596",
            ["LookAt"] = {
                [1] = "200002:n(200024)",
                [2] = "100001:n(200002)",
                },
            ["NextDialogue"] = 20000608,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/2001/200006/3211C596",
            },
        [20000608] = {
            ["Camera"] = "-273.669891,-169.162842,94.503487,0.000062,-4.201106,40.194386,20.0,189.105499,false,Manual,2.8",
            ["Content"] = "哇哦。那么白也有一技之长吗？",
