        [20000618] = {
            ["Camera"] = "-100.573456,-44.273193,82.943001,0.000289,2.394917,38.210751,50.0,255.910919,false,Disable,2.8",
            ["Content"] = "唔……每天二十张魔王大人的亲笔签名夸奖信？哎呀到时候再说啦，总之，绝对不会亏待你的！",
            ["ContentFR"] = "Hmmm... disons... vingt lettres de louange signées de la main du Roi Démon chaque jour ? Oh, bah, on verra bien. Une chose est sûre : je ne te laisserai jamais tomber.",
