            },
        [20000811] = {
            ["Camera"] = "-172.939453,-35.199219,127.119141,0.000043,-6.20035,28.797371,30.0,157.579727,false,Manual,4.388952",
            ["CameraBlendCurve"] = "easeInOutQuad",
