            ["Scripts"] = "SEQ{PlayAnimation{ActorId{200027},AnimationId{\"Explain01_Start\"},Duration{4}},PlayAnimation{ActorId{200027},AnimationId{\"Explain01_End\"},Duration{1}}}",
            ["SpeakNpcId"] = 200027,
            ["VoiceName"] = "voice/$Locale$/story/2001/200009/3211F81E",
            },
        [20000916] = {
            ["Camera"] = "125.382812,-36.4729,125.59375,-0.0,0.599998,-168.793137,25.0,147.010483,false,DoNotOverride,1.8",
            ["Content"] = "嗯……看来把花送给你是对的，你一定会好好养护它们。",
            ["ContentFR"] = "Hmm... je suis contente de t’avoir offerte cette fleur, je savais que tu en prendrais soin.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 20000916,
            ["Duration"] = 3,
            ["GUID"] = "3211F848",
            ["NextDialogue"] = 20000919,
            ["SpeakNpcId"] = 200027,
            ["TalkActionId"] = {
                [1] = "200027:AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200009/3211F848",
            },
        [20000917] = {
            ["Camera"] = "125.382812,-36.4729,125.59375,-0.0,0.599998,-168.793137,25.0,147.010483,false,DoNotOverride,1.8",
            ["Content"] = "嗯……我明白，我也是这么想的。",
            ["ContentFR"] = "Oui... je comprends, moi aussi je le pense.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 20000917,
            ["Duration"] = 3,
            ["FacialId"] = {
                [1] = "200027:Smile01",
                },
            ["GUID"] = "3211F872",
            ["NextDialogue"] = 20000919,
            ["SpeakNpcId"] = 200027,
            ["TalkActionId"] = {
                [1] = "200027:AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200009/3211F872",
            },
        [20000918] = {
            ["Camera"] = "125.382812,-36.4729,125.59375,-0.0,0.599998,-168.793137,25.0,147.010483,false,DoNotOverride,1.8",
            ["Content"] = "你和我小时候想的一样呢。",
            ["ContentFR"] = "Tu penses comme moi quand j’étais petite.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 20000918,
            ["Duration"] = 3,
            ["FacialId"] = {
                [1] = "200027:Smile01",
                },
            ["GUID"] = "3211F89C",
            ["NextDialogue"] = 20000919,
            ["SpeakNpcId"] = 200027,
            ["TalkActionId"] = {
                [1] = "200027:AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200009/3211F89C",
            },
        [20000919] = {
            ["Camera"] = "624.845703,-2701.800537,279.474609,0.0,0.0,-89.999985,25.0,147.010483,false,DoNotOverride,1.8",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "现在的我啊，看到被切下来的花，还是会有点难过。但是，我也渐渐发觉，那些鲜切花很了不起，比我想象中更了不起。",
            ["ContentFR"] = "Aujourd’hui, voir une fleur coupée me rend encore triste. Mais je commence à voir combien elles sont incroyables, plus que je ne l’imaginais.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 20000919,
            ["Duration"] = 3,
            ["FinalCamera"] = "624.845703,-2600.36084,279.474609,0.0,0.0,-89.999985,25.0,147.010483,false,DoNotOverride,1.8",
            ["GUID"] = "3211F8C6",
            ["NextDialogue"] = 20000920,
            ["SpeakNpcId"] = 200027,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200009/3211F8C6",
            },
        [20000920] = {
            ["Camera"] = "260.572266,-2538.362549,380.068359,0.0,-7.500005,90.0,15.0,147.010483,false,DoNotOverride,1.8",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "明明从被切断的那一刻起，它们就注定无法结出果实，只能慢慢枯萎——",
            ["ContentFR"] = "Dès qu’elles sont coupées, elles sont destinées à ne plus donner de fruit et à faner lentement...",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 20000920,
            ["Duration"] = 3,
            ["FinalCamera"] = "260.572266,-2339.146973,232.763672,0.0,-2.499965,90.0,17.5,147.010483,false,DoNotOverride,1.8",
            ["GUID"] = "3211F8F0",
            ["NextDialogue"] = 20000921,
            ["SpeakNpcId"] = 200027,
            ["TalkActionId"] = {
                [1] = "100001:Think_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200009/3211F8F0",
            },
        [20000921] = {
            ["Camera"] = "454.208984,234.598389,25.705078,0.000022,5.099815,-140.996017,30.0,147.010483,false,DoNotOverride,1.8",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "但是它们还是会拼命吸收水分，在短暂的时间里竭尽全力盛开，仿佛它们还有根，仿佛它们从未被剪下。",
            ["ContentFR"] = "Pourtant, elles continuent à absorber l’eau de toutes leurs forces et, même pour un temps si court, s’épanouissent pleinement, comme si elles avaient encore leurs racines, comme si elles n’avaient jamais été coupées. ",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 20000921,
            ["Duration"] = 3,
            ["FinalCamera"] = "428.185547,247.284424,26.796875,0.000022,5.099815,-136.996017,30.0,147.010483,false,DoNotOverride,1.8",
            ["GUID"] = "3211F91A",
            ["NextDialogue"] = 20000922,
            ["SpeakNpcId"] = 200027,
            ["TalkActionId"] = {
                [1] = "100001:Think_End",
                [2] = "200027:Talk02_Start",
                },
            ["ToFinalCameraBlendTime"] = 7,
            ["VoiceName"] = "voice/$Locale$/story/2001/200009/3211F91A",
            },
        [20000922] = {
            ["Camera"] = "125.382812,-36.4729,125.59375,-0.0,0.599998,-168.793137,25.0,147.010483,false,DoNotOverride,1.8",
            ["Content"] = "所以现在，我不可怜它们，我敬佩它们。",
            ["ContentFR"] = "Maintenant, je ne les plains plus. Je les admire.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 20000922,
            ["Duration"] = 3,
            ["GUID"] = "3211F944",
            ["NextOptions"] = {
                [1] = 200009221,
                [2] = 200009222,
                },
            ["SpeakNpcId"] = 200027,
            ["TalkActionId"] = {
                [1] = "200027:Talk02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200009/3211F944",
            },
        [20000923] = {
            ["Camera"] = "104.851562,-52.04541,128.546875,0.0,1.599992,-165.590759,25.0,95.278557,false,Manual,1.8",
            ["Content"] = "嗯，你也这么觉得吧！",
            ["ContentFR"] = "Toi aussi, tu penses comme moi, hein ?",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 20000923,
            ["Duration"] = 3,
            ["FacialId"] = {
                [1] = "200027:Happy01",
                },
            ["GUID"] = "3211F96E",
            ["NextDialogue"] = 20000925,
            ["SpeakNpcId"] = 200027,
            ["TalkActionId"] = {
                [1] = "200027:AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200009/3211F96E",
            },
        [20000924] = {
            ["Camera"] = "104.851562,-52.04541,128.546875,0.0,1.599992,-165.590759,25.0,95.278557,false,Manual,1.8",
            ["Content"] = "你真善良……嗯，你说的没错……如果不曾被切下，就更好了。",
            ["ContentFR"] = "Tu es vraiment {性别:gentil|gentille}... oui, tu as raison, ce serait mieux si elles n’étaient jamais coupées.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 20000924,
            ["Duration"] = 3,
            ["GUID"] = "3211F998",
            ["NextDialogue"] = 20000925,
            ["SpeakNpcId"] = 200027,
            ["VoiceName"] = "voice/$Locale$/story/2001/200009/3211F998",
            },
        [20000925] = {
            ["Camera"] = "125.382812,-36.4729,125.59375,-0.0,0.599998,-168.793137,25.0,147.010483,false,DoNotOverride,1.8",
            ["Content"] = "啊，一不小心就把话题搞沉重起来了，我的错我的错——",
            ["ContentFR"] = "Ah... je ne voulais pas, mais je crois que j’ai un peu alourdi la conversation, pardon, pardon...",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 20000925,
            ["Duration"] = 3,
            ["FacialId"] = {
                [1] = "200027:Sad02",
                },
            ["GUID"] = "3211F9C2",
            ["NextDialogue"] = 20000926,
            ["SpeakNpcId"] = 200027,
            ["TalkActionId"] = {
                [1] = "200027:Sigh_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200009/3211F9C2",
            },
        [20000926] = {
            ["Camera"] = "125.382812,-36.4729,125.59375,-0.0,0.599998,-168.793137,25.0,147.010483,false,DoNotOverride,1.8",
            ["Content"] = "谢谢你带回来的土壤，湿度和松软程度正合适……说不定你也有园艺方面的天分呢！",
            ["ContentFR"] = "Merci pour la terre, son humidité et sa texture sont parfaites... Peut-être que tu as un talent pour le jardinage !",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 20000926,
            ["Duration"] = 3,
            ["FacialId"] = {
                [1] = "200027:Smile01",
                },
            ["GUID"] = "3211F9EC",
            ["NextOptions"] = {
                [1] = 200009261,
                [2] = 200009262,
                },
            ["SpeakNpcId"] = 200027,
            ["TalkActionId"] = {
                [1] = "200027:Sigh_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200009/3211F9EC",
            },
        [20000927] = {
            ["Camera"] = "106.785156,-624.62207,37.896484,0.0,2.399917,5.600382,30.0,352.267853,false,Manual,1.2",
            ["Content"] = "好呀，我会把我了解的所有窍门都教给你的！……如果有时间。",
            ["ContentFR"] = "Bien sûr ! Je te transmettrai tous mes secrets... si j’ai le temps.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 20000927,
            ["Duration"] = 3,
            ["FinalCamera"] = "106.785156,-624.62207,56.728516,0.000001,0.0,5.600479,30.0,352.267853,false,Manual,1.2",
            ["GUID"] = "3211FA16",
            ["NextDialogue"] = 20000928,
            ["SpeakNpcId"] = 200027,
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/2001/200009/3211FA16",
            },
        [20000928] = {
            ["Camera"] = "-73.154297,-38.155029,129.271484,0.000001,-2.400053,-18.186663,33.0,255.978088,false,Manual,4.671381",
            ["Content"] = "嗯，就这么定了。",
            ["ContentFR"] = "Parfait, c’est une promesse. ",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 20000928,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "3211FA40",
            ["NextDialogue"] = 20000929,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200009/3211FA40",
            },
        [20000929] = {
            ["Camera"] = "428.185547,247.284424,82.193359,0.000022,-0.999987,-136.995941,30.0,147.010483,false,DoNotOverride,1.8",
            ["Content"] = "{nickname}，你……真好啊。",
            ["ContentFR"] = "{nickname}, tu... es vraiment adorable.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 20000929,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "3211FA6A",
            ["NextDialogue"] = 20000930,
            ["SpeakNpcId"] = 200027,
            ["VoiceName"] = "voice/$Locale$/story/2001/200009/3211FA6A",
            },
        [20000930] = {
            ["Camera"] = "125.382812,-36.4729,125.59375,-0.0,0.599998,-168.793137,25.0,147.010483,false,DoNotOverride,1.8",
            ["Content"] = "除了爸爸妈妈，不会有人把我微不足道的话记挂在心。更不用说为了一盆花，费这么大工夫了。",
            ["ContentFR"] = "À part papa et maman, personne ne se soucie de mes petites paroles, et encore moins pour une simple fleur.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 20000930,
            ["Duration"] = 3,
            ["FacialId"] = {
                [1] = "200027:Happy01",
                },
            ["GUID"] = "3211FA94",
            ["NextDialogue"] = 20000931,
            ["SpeakNpcId"] = 200027,
            ["VoiceName"] = "voice/$Locale$/story/2001/200009/3211FA94",
            },
        [20000931] = {
            ["Camera"] = "104.851562,-52.04541,128.546875,0.0,1.599992,-165.590759,25.0,95.278557,false,Manual,1.8",
            ["Content"] = "这是报酬。虽然不值多少钱，还是希望你能收下！",
            ["ContentFR"] = "C’est pour te remercier... Ce n’est pas grand-chose, mais j’espère que tu l’accepteras",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 20000931,
            ["Duration"] = 3,
            ["GUID"] = "3211FABE",
            ["NextDialogue"] = 20000932,
            ["SpeakNpcId"] = 200027,
            ["TalkActionId"] = {
                [1] = "200027:Give",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200009/3211FABE",
            },
        [20000932] = {
            ["Camera"] = "-51.462891,437.980225,224.990234,0.000043,-14.999996,-75.99987,30.0,147.010483,false,DoNotOverride,1.8",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "等这些花儿重新开好了，你记得回来看看。",
            ["ContentFR"] = "Quand ces fleurs refleuriront, promets-moi de revenir les voir.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 20000932,
            ["Duration"] = 3,
            ["FacialId"] = {
                [1] = "200027:Happy02",
                },
            ["FinalCamera"] = "-51.462891,437.980225,188.777344,0.000045,-10.999991,-75.998978,30.0,147.010483,false,DoNotOverride,1.8",
            ["GUID"] = "3211FAE8",
            ["SpeakNpcId"] = 200027,
            ["TalkActionId"] = {
                [1] = "200027:Explain02_Start",
                },
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/2001/200009/3211FAE8",
            },
        [20001001] = {
            ["Content"] = "这里的土壤好像有点干燥……再去别的地方看看吧。",
            ["ContentFR"] = "Cette terre semble un peu sèche... Allons voir ailleurs.",
            ["DialogueId"] = 20001001,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "3212063A",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/2001/200010/3212063A",
            },
        [20001201] = {
            ["Content"] = "找到了……！这里的土壤比较松软，湿度看起来也合适，多挖一点回去吧。",
            ["ContentFR"] = "Je l’ai trouvée... ! Cette terre est souple et l’humidité semble parfaite. Je vais en prendre un peu plus.",
            ["DialogueId"] = 20001201,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "3212270A",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/2001/200012/3212270A",
            },
        [20001301] = {
            ["Content"] = "{nickname}，你找到那种土壤了吗？",
            ["ContentFR"] = "{nickname}, as-tu trouvé cette terre spéciale ?",
            ["DialogueId"] = 20001301,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "32123772",
            ["NextDialogue"] = 20001302,
            ["SpeakNpcId"] = 200027,
            ["VoiceName"] = "voice/$Locale$/story/2001/200013/32123772",
            },
        [20001302] = {
            ["Content"] = "还没有。",
            ["ContentFR"] = "Pas encore.",
            ["DialogueId"] = 20001302,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "3212379C",
            ["NextDialogue"] = 20001303,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/2001/200013/3212379C",
            },
        [20001303] = {
            ["Content"] = "找不到也没关系的，不要勉强……",
            ["ContentFR"] = "Ce n’est pas grave si tu ne l’as pas trouvée, ne te force pas...",
            ["DialogueId"] = 20001303,
            ["GUID"] = "321237C6",
            ["SpeakNpcId"] = 200027,
            ["VoiceName"] = "voice/$Locale$/story/2001/200013/321237C6",
            },
        [20001401] = {
            ["Content"] = "对了对了，我还有几件事要问你。",
            ["ContentFR"] = "Ah, au fait, j’ai encore quelques questions à te poser.",
            ["DialogueId"] = 20001401,
            ["GUID"] = "321247DA",
            ["NextDialogue"] = 20001402,
            ["SpeakNpcId"] = 200027,
            ["VoiceName"] = "voice/$Locale$/story/2001/200014/321247DA",
            },
        [20001402] = {
            ["Content"] = "你有没有亲自到天之树脚下去过呀，它是不是真的有传说中那——么大，大到遮天蔽日？从下往上看，会不会像……满天都是水晶？",
            ["ContentFR"] = "Dis-moi... as-tu déjà vu l’Arbre Céleste de près ? Est-il vraiment aussi immense que dans les légendes, au point de cacher tout le ciel ? Quand on lève les yeux depuis son pied... est-ce que ses branches et ses feuilles scintillent comme du cristal ?",
            ["DialogueId"] = 20001402,
            ["GUID"] = "32124804",
            ["NextDialogue"] = 20001403,
            ["SpeakNpcId"] = 200027,
            ["VoiceName"] = "voice/$Locale$/story/2001/200014/32124804",
            },
        [20001403] = {
            ["Content"] = "还有还有……海边的沙子是不是都是软绵绵的，踩上去像面粉一样，一点儿也不硌脚？",
            ["ContentFR"] = "Et puis... sur la plage, le sable est-il vraiment si doux, si fin qu’on dirait de la farine, sans jamais blesser les pieds ?",
            ["DialogueId"] = 20001403,
            ["GUID"] = "3212482E",
            ["NextDialogue"] = 20001404,
            ["SpeakNpcId"] = 200027,
            ["VoiceName"] = "voice/$Locale$/story/2001/200014/3212482E",
            },
        [20001404] = {
            ["Content"] = "问题可能会有点多！是帮大家问的……嘿嘿，不要嫌我烦哦！",
            ["ContentFR"] = "Je risque d’avoir beaucoup de questions ! Mais c’est aussi pour mes amis de l’auberge... héhé, ne m’en veux pas si je deviens trop bavarde.",
            ["DialogueId"] = 20001404,
            ["GUID"] = "32124858",
            ["SpeakNpcId"] = 200027,
            ["VoiceName"] = "voice/$Locale$/story/2001/200014/32124858",
            },
        [20001501] = {
            ["Content"] = "嗯……有这些应该够了，回去交给赛琪吧。",
            ["ContentFR"] = "Hmm... ça devrait suffire. Allons la remettre à Psyche.",
            ["DialogueId"] = 20001501,
            ["Duration"] = 4,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "32125842",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/2001/200015/32125842",
            },
        [20001601] = {
            ["Camera"] = "1700.51709,233.67041,1259.031372,0.0,0.0,-179.999985,20.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "嗯等。",
            ["DialogueId"] = 20001601,
            ["GUID"] = "321268AA",
            ["NextDialogue"] = 20001602,
            },
        [20001602] = {
            ["Camera"] = "1700.51709,233.67041,1259.031372,0.0,0.0,-179.999985,20.0,100000.0,false,DoNotOverride,2.8",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "等不耐烦了。",
            ["DialogueId"] = 20001602,
            ["FinalCamera"] = "1700.51709,233.67041,212.238281,0.0,0.0,-179.999985,20.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "321268D4",
            ["NextDialogue"] = 20001603,
            ["ToFinalCameraBlendTime"] = 4,
            },
        [20001603] = {
            ["Content"] = "赛琪怎么还没出来，我们去瞅瞅吧。",
            ["DialogueId"] = 20001603,
            ["GUID"] = "321268FE",
            },
        [20001701] = {
            ["Camera"] = "-284.28125,-104.837433,123.125,0.000002,0.199954,98.206268,35.0,310.0,false,Manual,22.0",
            ["Content"] = "想要阻止秽蚀者并非易事，先做好准备再出城找赛琪吧。",
            ["ContentFR"] = "Vouloir arrêter un Dégradé n’est pas une tâche facile. Prépare-toi bien avant de quitter la cité pour aller chercher Psyche.",
            ["DialogueId"] = 20001701,
            ["FinalCamera"] = "-286.169922,-91.687805,123.117188,0.000002,-0.200043,98.206268,35.0,310.0,false,Manual,22.0",
