            ["VoiceName"] = "voice/$Locale$/story/2001/200017/32127912",
            },
        [20001801] = {
            ["Content"] = "哇……要被吹跑了！",
            ["ContentFR"] = "Waaah... je vais m’envoler !",
            ["DialogueId"] = 20001801,
            ["GUID"] = "3212897A",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 20001802,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/2001/200018/3212897A",
            },
        [20001802] = {
            ["Content"] = "白，跟在我们后面，趁着风小一点的时候一起向前。",
            ["ContentFR"] = "Snow, reste derrière nous. Avançons seulement quand le vent se calme un peu.",
            ["DialogueId"] = 20001802,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "321289A4",
            ["NextDialogue"] = 20001803,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/2001/200018/321289A4",
            },
        [20001803] = {
            ["Content"] = "风太大的时候也可以躲在石头后面，别着急。",
            ["ContentFR"] = "Et si ça souffle trop fort, cachez-vous derrière les rochers. Pas la peine de foncer tête baissée.",
            ["DialogueId"] = 20001803,
            ["GUID"] = "321289CE",
            ["SpeakNpcId"] = 200021,
            ["VoiceName"] = "voice/$Locale$/story/2001/200018/321289CE",
            },
        [20001901] = {
            ["Camera"] = "-362.765625,-80.016602,-24.530273,0.000006,17.167358,25.771385,15.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "远处的冰湖上刮起了风暴，赛琪应该就在那个方向……",
            ["ContentFR"] = "Au loin, une tempête balaie la surface gelée du lac. C’est sûrement par là que Psyche est partie...",
            ["DialogueId"] = 20001901,
            ["GUID"] = "321299E2",
            },
        [20002001] = {
            ["Content"] = "……蝴蝶？冬天怎么会有蝴蝶？",
            ["ContentFR"] = "... Des papillons ? En plein hiver ?",
            ["DialogueId"] = 20002001,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "3212AA4A",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/2001/200020/3212AA4A",
            },
        [20002002] = {
            ["Content"] = "就像是……在为我们引路一样……",
            ["ContentFR"] = "On dirait... qu’ils nous montrent le chemin...",
            ["DialogueId"] = 20002002,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "3212AA74",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/2001/200020/3212AA74",
            },
        [20002101] = {
            ["Content"] = "这些秽兽都半死不活的，很可能是和赛琪交过手。",
            ["ContentFR"] = "Ces Souillés sont à moitié morts... sans doute vaincus par Psyche.",
            ["DialogueId"] = 20002101,
            ["GUID"] = "3212BAB2",
            ["NextDialogue"] = 20002102,
            ["SpeakNpcId"] = 200021,
            ["VoiceName"] = "voice/$Locale$/story/2001/200021/3212BAB2",
            },
        [20002102] = {
            ["Content"] = "看来只要沿着它们的反方向，就能找到赛琪了……",
            ["ContentFR"] = "Alors si on suit leur piste en sens inverse, on finira par la retrouver...",
            ["DialogueId"] = 20002102,
            ["GUID"] = "3212BADC",
            ["SpeakNpcId"] = 200021,
            ["VoiceName"] = "voice/$Locale$/story/2001/200021/3212BADC",
            },
        [20002201] = {
            ["Content"] = "兄弟，你还好吗。",
            ["DialogueId"] = 20002201,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "3212CB1A",
            ["NextDialogue"] = 20002202,
            ["SpeakNpcId"] = 100001,
            },
        [20002202] = {
            ["Content"] = "不太好。",
            ["DialogueId"] = 20002202,
            ["GUID"] = "3212CB44",
            ["NextDialogue"] = 20002203,
            },
        [20002203] = {
            ["Content"] = "外面情况怎么样？",
            ["DialogueId"] = 20002203,
            ["GUID"] = "3212CB6E",
            ["NextDialogue"] = 20002204,
            },
        [20002204] = {
            ["Content"] = "刮了好大的风，秽兽的行为也很反常。",
            ["DialogueId"] = 20002204,
            ["GUID"] = "3212CB98",
            },
        [20002301] = {
            ["Content"] = "（已经失去理智的赛琪正在与秽蚀对抗……应该为她做些什么……）",
            ["ContentFR"] = "Psyche, ayant perdu la raison, lutte toujours contre la Dégradation... Il faut faire quelque chose...",
            ["DialogueId"] = 20002301,
            ["DisableMouth"] = 1,
            ["GUID"] = "3212DB82",
            },
        [20002401] = {
            ["Content"] = "……赛琪好像往城外去了。",
            ["ContentFR"] = "... On dirait que Psyche est sortie de la cité.",
            ["DialogueId"] = 20002401,
            ["GUID"] = "3212EBEA",
            ["NextDialogue"] = 20002402,
            ["SpeakNpcId"] = 700049,
            },
        [20002402] = {
            ["Content"] = "应该是因为城外人比较少吧，在还有最后一点理智的时候，尽量去人少的地方去。",
            ["ContentFR"] = "Sans doute parce qu’il y a moins de monde dehors... Avec le peu de lucidité qui lui restait, elle a voulu s’éloigner de la foule.",
            ["DialogueId"] = 20002402,
            ["GUID"] = "3212EC14",
            ["SpeakNpcId"] = 700049,
            },
        [20002501] = {
            ["Content"] = "你们……要去找赛琪吗？",
            ["ContentFR"] = "Vous... vous allez chercher Psyche ?",
            ["DialogueId"] = 20002501,
            ["GUID"] = "3212FC52",
            ["NextDialogue"] = 20002502,
            ["SpeakNpcId"] = 200045,
            },
        [20002502] = {
            ["Content"] = "找到她的话，不要犹豫，结束她的痛苦吧，我想她也希望你们这么做……",
            ["ContentFR"] = "Si vous la trouvez... n’hésitez pas. Abrégez ses souffrances. Je crois qu’elle voudrait que vous fassiez ça...",
            ["DialogueId"] = 20002502,
            ["GUID"] = "3212FC7C",
            ["SpeakNpcId"] = 200045,
            },
        [20002601] = {
            ["Content"] = "刚刚那个大姐姐怎么跑那么快？",
            ["ContentFR"] = "La grande fille de tout à l’heure... comment elle a couru aussi vite ?",
            ["DialogueId"] = 20002601,
            ["GUID"] = "32130CBA",
            ["NextDialogue"] = 20002602,
            ["SpeakNpcName"] = "UI_Npc_Name_FindSaiqiNpc1",
            ["VoiceName"] = "voice/$Locale$/story/2001/200026/32130CBA",
            },
        [20002602] = {
            ["Content"] = "别问了，快走，快到城里去，那是秽蚀者！",
            ["ContentFR"] = "Chut, ne demande pas ! Vite, rentre en ville, c’était un Dégradé !",
            ["DialogueId"] = 20002602,
            ["GUID"] = "32130CE4",
            ["NextDialogue"] = 20002603,
            ["SpeakNpcName"] = "UI_Npc_Name_FindSaiqiNpc2",
            ["VoiceName"] = "voice/$Locale$/story/2001/200026/32130CE4",
            },
        [20002603] = {
            ["Content"] = "别……别慌……已经有人去找卫戍部队了！",
            ["ContentFR"] = "Ne... ne paniquez pas... Les Veilleurs arrivent bientôt !",
            ["DialogueId"] = 20002603,
            ["GUID"] = "32130D0E",
            ["NextDialogue"] = 20002604,
            ["SpeakNpcName"] = "UI_Npc_Name_FindSaiqiNpc3",
            ["VoiceName"] = "voice/$Locale$/story/2001/200026/32130D0E",
            },
        [20002604] = {
            ["Content"] = "你们不要想趁机溜进城里，通行证，出示通行证！",
            ["ContentFR"] = "Et vous, n’essayez pas de profiter du chaos pour entrer. Montrez vos permis de circulation !",
            ["DialogueId"] = 20002604,
            ["GUID"] = "32130D38",
            ["NextDialogue"] = 20002605,
            ["SpeakNpcName"] = "UI_Npc_Name_FindSaiqiNpc4",
            ["VoiceName"] = "voice/$Locale$/story/2001/200026/32130D38",
            },
        [20002605] = {
            ["Content"] = "求求你们让我们进去吧，通行证真的只是不小心弄丢了！",
            ["ContentFR"] = "Pitié, laissez-nous entrer ! On a vraiment juste perdu notre permis de circulation par accident !",
            ["DialogueId"] = 20002605,
            ["GUID"] = "32130D62",
            ["NextDialogue"] = 20002606,
            ["SpeakNpcName"] = "UI_Npc_Name_FindSaiqiNpc5",
            ["VoiceName"] = "voice/$Locale$/story/2001/200026/32130D62",
            },
        [20002606] = {
            ["Content"] = "都什么时候了还通行证，反正在外面也是死，不如直接冲进去！",
            ["ContentFR"] = "Vous pensez encore aux permis de circulation ?! Dehors on est condamnés de toute façon, autant forcer le passage !",
            ["DialogueId"] = 20002606,
            ["GUID"] = "32130D8C",
            ["NextDialogue"] = 20002607,
            ["SpeakNpcName"] = "UI_Npc_Name_FindSaiqiNpc6",
            ["VoiceName"] = "voice/$Locale$/story/2001/200026/32130D8C",
            },
        [20002607] = {
            ["Content"] = "停，停，你们再过来我就开枪了！",
            ["ContentFR"] = "Halte ! Arrêtez ou je tire !",
            ["DialogueId"] = 20002607,
            ["GUID"] = "32130DB6",
            ["NextDialogue"] = 20002608,
            ["SpeakNpcName"] = "UI_Npc_Name_FindSaiqiNpc7",
            ["VoiceName"] = "voice/$Locale$/story/2001/200026/32130DB6",
            },
        [20002608] = {
            ["Content"] = "开啊！开枪把秽蚀者引过来我们一起死！",
            ["ContentFR"] = "Tire donc ! Fais du bruit et attire le Dégradé, qu’on crève tous ensemble !",
            ["DialogueId"] = 20002608,
            ["GUID"] = "32130DE0",
            ["NextDialogue"] = 20002609,
            ["SpeakNpcName"] = "UI_Npc_Name_FindSaiqiNpc8",
            ["VoiceName"] = "voice/$Locale$/story/2001/200026/32130DE0",
            },
        [20002609] = {
            ["Content"] = "你……算你狠。行吧，先进来，等卫戍部队处理掉秽蚀者再说。",
            ["ContentFR"] = "Tu... Bon, tu as raison. Entrez vite, on s’occupera de vous quand les Veilleurs auront réglé ça.",
            ["DialogueId"] = 20002609,
            ["GUID"] = "32130E0A",
            ["SpeakNpcName"] = "UI_Npc_Name_FindSaiqiNpc9",
            ["VoiceName"] = "voice/$Locale$/story/2001/200026/32130E0A",
            },
        [20002701] = {
            ["Content"] = "好大的风……直接跳下去会被吹飞的。",
            ["ContentFR"] = "Quel vent ! Si on saute directement, on sera balayés.",
            ["DialogueId"] = 20002701,
            ["GUID"] = "32131D22",
            ["NextDialogue"] = 20002702,
            ["SpeakNpcId"] = 200021,
            ["VoiceName"] = "voice/$Locale$/story/2001/200027/32131D22",
            },
        [20002702] = {
            ["Content"] = "那边，我们坐升降机下去。",
            ["ContentFR"] = "Par ici, prenons l’ascenseur.",
            ["DialogueId"] = 20002702,
            ["GUID"] = "32131D4C",
            ["SpeakNpcId"] = 200021,
            ["VoiceName"] = "voice/$Locale$/story/2001/200027/32131D4C",
            },
        [20002801] = {
            ["Content"] = "没事的，我们知道了赛琪去了哪里，跟上去就是。",
            ["ContentFR"] = "Ça va. On sait maintenant où Psyche est allée, il suffit de suivre sa trace.",
            ["DialogueId"] = 20002801,
            ["Duration"] = 3,
            ["GUID"] = "32132D8A",
            ["NextDialogue"] = 20002802,
            ["SpeakNpcId"] = 200021,
            ["VoiceName"] = "voice/$Locale$/story/2001/200028/32132D8A",
            },
        [20002802] = {
            ["Content"] = "嗯，没错，只要找到赛琪，就一定会有办法的！",
            ["ContentFR"] = "Exactement ! Tant qu’on la retrouve, il y aura forcément une solution !",
            ["DialogueId"] = 20002802,
            ["Duration"] = 3,
            ["GUID"] = "32132DB4",
            ["NextDialogue"] = 20002803,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/2001/200028/32132DB4",
            },
        [20002803] = {
            ["Content"] = "谢谢你们……",
            ["ContentFR"] = "Merci... à vous deux...",
            ["DialogueId"] = 20002803,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "32132DDE",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/2001/200028/32132DDE",
            },
        [20002901] = {
            ["Content"] = "（已经和奥特赛德和白交代好了今天发生的所有事。）",
            ["ContentFR"] = "<I>J’ai déjà mis au courant l’Étranger et Snow de tout ce qui s’est passé aujourd’hui.</>",
            ["DialogueId"] = 20002901,
            ["DisableMouth"] = 1,
            ["Duration"] = 3,
            ["GUID"] = "32133DF2",
            ["NextDialogue"] = 20002902,
            },
        [20002902] = {
            ["Content"] = "（接下来能做的，就只有在说好的地方……耐心等待。）",
            ["ContentFR"] = "<I>À présent, il ne reste plus qu’à attendre au point de rendez-vous... avec patience.</>",
            ["DialogueId"] = 20002902,
            ["DisableMouth"] = 1,
            ["Duration"] = 3,
            ["GUID"] = "32133E1C",
            },
