        [20003201] = {
            ["Camera"] = "-718.347656,-180.535156,184.294922,0.000032,34.597809,36.600552,16.0,100000.0,false,Manual,2.8",
            ["DialogueId"] = 20003201,
            ["GUID"] = "32136F2A",
            },
        [20003301] = {
            ["Content"] = "……安息吧。",
            ["ContentFR"] = "... Reposez en paix.",
            ["DialogueId"] = 20003301,
            ["GUID"] = "32137F92",
            ["NextDialogue"] = 20003302,
            ["SpeakNpcId"] = 200021,
            ["VoiceName"] = "voice/$Locale$/story/2001/200033/32137F92",
            },
        [20003302] = {
            ["Content"] = "嗯？是你啊。别忘了晚上见。",
