        [20004701] = {
            ["Content"] = "呃，碎了。",
            ["DialogueId"] = 20004701,
            ["Duration"] = 2,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "32146542",
            ["NextDialogue"] = 20004702,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101137/19518F12",
            },
        [20004702] = {
            ["Content"] = "废品改装的嘛，能用已经很不错了！",
            ["ContentFR"] = "C’est fait avec de la récup’ ! Qu’il fonctionne déjà, c’est un miracle.",
            ["DialogueId"] = 20004702,
            ["Duration"] = 3,
            ["GUID"] = "3214656C",
            ["SpeakNpcId"] = 200021,
            ["VoiceName"] = "voice/$Locale$/story/1002/101137/19518F3C",
