        [20004803] = {
            ["Camera"] = "-578.413757,-1981.769775,101.114594,0.0,0.0,76.99968,25.0,198.283234,false,Manual,3.328919",
            ["Content"] = "喘口气慢慢说，怎么了？",
            ["ContentFR"] = "Calme-toi et explique. Qu’est-ce qu’il se passe ?",
            ["DialogueId"] = 20004803,
            ["FinalCamera"] = "-564.10083,-1919.769043,101.114594,0.0,0.0,76.999603,25.0,198.283234,false,Manual,3.328919",
            ["GUID"] = "321475FE",
