        [20004805] = {
            ["Camera"] = "-662.342529,29.628418,112.909363,0.000096,-2.999962,-41.401596,25.0,161.861893,false,Manual,1.2",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "这算什么好事！我看你是饿迷糊了。",
            ["ContentFR"] = "Hein ?! Mais de quoi tu parles ! Ton estomac te fait encore perdre la raison !",
            ["DialogueId"] = 20004805,
            ["FinalCamera"] = "-660.245789,32.00293,112.909363,0.000096,-2.999962,-41.401596,25.0,824.858765,false,Manual,1.2",
            ["GUID"] = "32147652",
            ["NextDialogue"] = 20004807,
            ["Scripts"] = "PARA{\
SetRotation{SetRotationDescription{\"100001:p(30)\"}},\
MoveTo{_delay{0.1},ActorId{100001},TargetPoint{\"P200048Nvzhu2\"},MoveSpeed{50},Visibility{\"Show\"}}\
}",
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Bai_Circle_End",
                },
            ["ToFinalCameraBlendTime"] = 4,
            ["VoiceName"] = "voice/$Locale$/story/2001/200048/32147652",
            },
        [20004806] = {
            ["Camera"] = "-662.342529,29.628418,112.909363,0.000096,-2.999962,-41.401596,25.0,161.861893,false,Manual,1.2",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "当然不止这点，我可是见过大风大浪的魔王大人。",
            ["ContentFR"] = "Bien sûr que non ! Tu me prends pour qui ? En tant que Roi Démon, j’ai affronté tempêtes et cataclysmes, je ne m’affole pas pour un simple cochon !",
            ["DialogueId"] = 20004806,
            ["FinalCamera"] = "-660.245789,32.00293,112.909363,0.000096,-2.999962,-41.401596,25.0,824.858765,false,Manual,1.2",
            ["GUID"] = "3214767C",
            ["NextDialogue"] = 20004807,
            ["Scripts"] = "PARA{\
SetRotation{SetRotationDescription{\"100001:p(30)\"}},\
MoveTo{_delay{0.1},ActorId{100001},TargetPoint{\"P200048Nvzhu2\"},MoveSpeed{50},Visibility{\"Show\"}}\
}",
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Bai_Circle_End",
                },
            ["ToFinalCameraBlendTime"] = 4,
            ["VoiceName"] = "voice/$Locale$/story/2001/200048/3214767C",
            },
        [20004807] = {
            ["Camera"] = "-992.792297,-208.039062,42.167068,0.000105,1.999995,-0.499939,32.5,507.776001,false,Manual,1.2",
            ["CameraBlendCurve"] = "easeInQuad",
            ["Content"] = "总之，我就是很好奇嘛！来吧来吧，反正我看你现在也不是很忙，和我走一趟。",
            ["ContentFR"] = "Bref ! Viens, viens ! De toute façon tu n’es pas si {性别:occupé|occupée}, hein ? Alors accompagne-moi dans cette quête périlleuse !",
            ["DialogueId"] = 20004807,
            ["FinalCamera"] = "-920.479614,-208.66748,44.692398,0.000105,1.999995,-0.499969,35.0,507.776001,false,Manual,1.2",
            ["GUID"] = "321476A6",
            ["Scripts"] = "PARA{\
CameraMoveTo{_delay{3.6},TargetPosition{\"-310.142487,-382.269043,103.6129,0.000111,-5.200185,99.10128,35.0,221.943451,false,Manual,3.5\"},duration{0}},\
PlayFacial{_delay{3.6},ActorId{200002},FacialId{\"Beg\"}}\
}",
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:SpecialHappy_Start",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/story/2001/200048/321476A6",
            },
        [20004901] = {
            ["Content"] = "怎么怎么，现在有空了吗？和我一起出城去看看传闻中的巨猪的真实面目！",
            ["DialogueId"] = 20004901,
            ["GUID"] = "32148612",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/2001/200049/32148612",
            },
        [20005001] = {
            ["Camera"] = "1059.539062,-1035.320312,97.993164,0.000246,4.999999,145.950104,15.0,100.0,false,DoNotOverride,1.2",
            ["Content"] = "到了到了，“泪湖南岸，大坡边上”，我听到的传闻里说那只巨大的猪就在这附近出没。",
            ["ContentFR"] = "Nous y voilà ! La rive sud du Lac du Deuil, juste au pied de la grande pente. C’est ici que, d’après la rumeur, rôde l’immense cochon destructeur !",
            ["DialogueId"] = 20005001,
            ["FinalCamera"] = "952.429688,-962.9375,109.304688,0.000246,4.999999,145.950104,15.0,100.0,false,DoNotOverride,1.2",
            ["GUID"] = "3214967A",
            ["LookAt"] = {
