            },
        [20005101] = {
            ["Content"] = "来嘛来嘛，要是不是的话我们就回去。",
            ["ContentFR"] = "Allez, viens ! Si jamais ce n’est pas ça, on rentrera.",
            ["DialogueId"] = 20005101,
            ["GUID"] = "3214A6E2",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/2001/200051/3214A6E2",
            },
        [20005201] = {
            ["Camera"] = "-39.945312,-242.193359,24.603516,0.000001,2.99999,77.499886,12.0,49.119881,false,Manual,1.2",
            ["Content"] = "你们好，请问——",
            ["ContentFR"] = "Bonjour, puis-je vous demander—",
            ["DialogueId"] = 20005201,
            ["FinalCamera"] = "-39.945312,-242.193359,83.955078,0.000001,-1.999995,77.49987,12.0,132.068192,false,Manual,1.2",
