                [1] = "700262:p(150)",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200052/3214B74A",
            },
        [20005202] = {
            ["Camera"] = "262.703125,537.847656,14.655273,0.00002,0.0,116.300385,35.0,212.772263,false,Manual,3.0",
            ["Content"] = "嘘——小声点，没看见在这儿等着呢吗？",
            ["ContentFR"] = "Chut ! Pas si fort ! Tu ne vois pas qu’on guette ?",
            ["DialogueId"] = 20005202,
            ["GUID"] = "3214B774",
            ["LookAt"] = {
                [1] = "700262:n(100001)",
                [2] = "700261:n(100001)",
                },
            ["NextDialogue"] = 20005203,
            ["SpeakNpcId"] = 700261,
            ["TalkActionId"] = {
                [1] = "700261:Angry01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200052/3214B774",
            },
        [20005203] = {
            ["Camera"] = "209.695312,903.513672,-4.157227,0.000101,4.999999,-103.000175,42.5,185.973083,false,Manual,4.798596",
            ["CameraBlendCurve"] = "easeInQuad",
            ["Content"] = "哦哦，不好意思。难道说，你们也在等那个？",
            ["ContentFR"] = "Oh pardon ! Alors... vous êtes là pour...",
            ["DialogueId"] = 20005203,
            ["FinalCamera"] = "208.707031,899.171875,-3.768555,0.000101,4.999999,-103.000175,45.0,531.784363,false,Manual,4.468951",
