        [20005204] = {
            ["Camera"] = "309.964844,919.208984,5.208984,-5.000004,5.59915,-117.792343,35.000011,633.13739,false,Manual,1.8174",
            ["CameraBlendCurve"] = "easeInQuad",
            ["Content"] = "是啊，怎么，你们也有这个打算？先来后到，排队排队，可别和我们抢。",
            ["ContentFR"] = "Évidemment ! Et vous aussi, non ? Mais premier arrivé, premier servi ! Alors ne cherchez pas à gruger !",
            ["DialogueId"] = 20005204,
            ["FinalCamera"] = "217.996094,951.210938,-3.291016,-5.000006,6.999127,-102.591911,35.000011,582.351562,false,Manual,4.0",
            ["GUID"] = "3214B7C8",
            ["NextDialogue"] = 20005205,
            ["SpeakNpcId"] = 700262,
            ["TalkActionId"] = {
                [1] = "100001:Sigh_End",
                [2] = "200002:SpecialConfident_End",
                },
            ["ToFinalCameraBlendTime"] = 4.5,
            ["VoiceName"] = "voice/$Locale$/story/2001/200052/3214B7C8",
            },
        [20005205] = {
            ["Camera"] = "212.636719,71.935547,89.862305,5.000298,4.599968,-145.002823,35.0,260.575531,false,Manual,2.726124",
            ["Content"] = "啊？还要排队？不用吧……那么大一只呢，不过既然是你们先来的，那我们就在边上看着，你们看完了，我们再凑近看。",
            ["ContentFR"] = "Quoi ?! Il faut même faire la queue pour ça ?! Une créature aussi colossale, il y en a forcément assez pour tout le monde ! ... Hmpf ! Puisque vous étiez là avant, on se contentera de regarder. Une fois que vous aurez fini, on s’approchera.",
            ["DialogueId"] = 20005205,
            ["FinalCamera"] = "209.164062,76.990234,90.396484,5.000327,4.599968,-145.002823,35.0,260.575531,false,Manual,2.726124",
            ["GUID"] = "3214B7F2",
            ["NextDialogue"] = 20005206,
            ["Scripts"] = "PARA{\
