        [20005206] = {
            ["Camera"] = "40.953125,79.552734,151.863281,0.000014,-3.600008,-122.403854,35.0,180.795609,false,Manual,4.0",
            ["Content"] = "你们是在说同一件事吗？",
            ["ContentFR"] = "Vous êtes sûrs qu’on parle bien de la même chose... ?",
