        [20005207] = {
            ["Camera"] = "166.644531,674.560547,33.423828,0.00001,-19.999928,48.994301,35.0,58.026943,false,Manual,4.0",
            ["Content"] = "还能是什么事，凡是来这边的，不都是为了——",
            ["ContentFR"] = "Et de quoi d’autre ? Tous ceux qui viennent ici, c’est forcément pour—",
            ["DialogueId"] = 20005207,
            ["FinalCamera"] = "162.179688,669.451172,35.886719,0.00001,-19.999928,48.994301,35.0,58.026943,false,Manual,4.0",
