            },
        [20005208] = {
            ["Camera"] = "290.441406,1084.865234,40.077148,0.000001,-4.999971,-107.19886,35.0,350.360718,false,Manual,1.2",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "来了！老二，拉绳子！",
            ["ContentFR"] = "Le voilà ! Vite, tire la corde !",
            ["DialogueId"] = 20005208,
            ["FinalCamera"] = "390.636719,1408.566406,69.72168,0.000001,-4.999971,-107.19886,35.0,716.16925,false,Manual,1.2",
            ["GUID"] = "3214B870",
            ["NextDialogue"] = 20005209,
            ["SpeakNpcId"] = 700262,
            ["ToFinalCameraBlendTime"] = 0.5,
            ["TurnTo"] = {
                [1] = "700262:p(180)",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200052/3214B870",
            },
        [20005209] = {
            ["Content"] = "只见这两个人正对的方向出现了几只小动物，摇头晃脑，走来走去。",
            ["ContentFR"] = "À cet instant, de petites créatures surgissent, leurs têtes oscillant tandis qu’elles reniflent le sol.",
            ["DialogueId"] = 20005209,
            ["GUID"] = "3214B89A",
            },
        [20005210] = {
            ["Content"] = "而在领头人的一声令下之后，一道埋在雪地中的陷阱出现，把这些小动物尽数困住。",
            ["ContentFR"] = "Au signal du chef, un piège dissimulé sous la neige jaillit d’un coup sec et les capture toutes en un instant.",
            ["DialogueId"] = 20005210,
            ["GUID"] = "3214B8C4",
            ["NextDialogue"] = 20005211,
            ["VoiceName"] = "voice/$Locale$/story/2001/200052/3214B8C4",
            },
        [20005211] = {
            ["DialogueId"] = 20005211,
            ["GUID"] = "3214B8EE",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 20005212,
            ["VoiceName"] = "voice/$Locale$/story/2001/200052/3214B8EE",
            },
        [20005212] = {
            ["Camera"] = "-362.589844,47.628906,98.706055,0.000069,-4.80014,34.000423,40.0,696.785583,false,Manual,2.0",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "这次还行，有一只还没见过，都带回去吧。",
            ["ContentFR"] = "Pas mal ! Et même une espèce qu’on n’avait jamais vue. On les embarque tous.",
            ["DialogueId"] = 20005212,
            ["FinalCamera"] = "-361.582031,46.011719,98.706055,0.00007,-4.80014,32.000233,40.0,305.607483,false,Manual,2.0",
