        [20005301] = {
            ["Camera"] = "975.558594,-278.386719,544.839844,-0.000154,-24.199093,159.000153,35.0,849.721619,false,Manual,4.5",
            ["CameraBlendCurve"] = "easeOutQuad",
            ["Content"] = "不可以欺负魔灵！榛子，撞飞他们！",
            ["ContentFR"] = "Ne faites pas de mal aux Géniemon ! Filbert, fonce !",
            ["DialogueId"] = 20005301,
            ["FinalCamera"] = "975.558594,-278.386719,544.839844,-0.000154,-24.199093,159.000153,35.0,106.409363,false,Manual,4.5",
