            ["SpeakNpcName"] = "UI_Npc_Name_SongluVoice",
            ["ToFinalCameraBlendTime"] = 1,
            ["VoiceName"] = "voice/$Locale$/story/2001/200053/3214C7B2",
            },
        [20005302] = {
            ["Camera"] = "-152.486328,408.109375,66.322266,3.000006,1.59976,-64.998474,35.0,157.777542,false,Manual,3.0",
            ["Content"] = "怎么又是她，最近第几次了？晦气。快走快走，刚刚抓到的这些魔灵都给揣在怀里，别落下。",
            ["ContentFR"] = "Encore elle ?! Ça fait combien de fois cette semaine ?! La poisse... On se replie ! Ramassez tout ce qu’on vient de choper et qu’on dégage, vite !",
            ["DialogueId"] = 20005302,
            ["GUID"] = "3214C7DC",
            ["LookAt"] = {
                [1] = "200075:n(200086)",
                [2] = "200087:n(200075)",
                },
            ["NextDialogue"] = 20005303,
            ["SpeakNpcId"] = 200075,
            ["TalkActionId"] = {
                [1] = "200075:Shock_Start",
                },
            ["TurnTo"] = {
                [1] = "200002:p(-50)",
                [2] = "100001:p(-30)",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200053/3214C7DC",
            },
        [20005303] = {
            ["Camera"] = "1291.046875,2.449219,566.126953,0.000018,-13.600217,-152.798065,50.0,479.745667,false,Manual,2.340814",
            ["Content"] = "他们想跑！喂，那边的{性别：大哥哥|大姐姐}和小朋友，帮一帮我。",
            ["ContentFR"] = "Ils s’enfuient ! Hé, {性别:Monsieur|Mademoiselle}, avec ta petite camarade, aidez-moi !",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 20005303,
            ["GUID"] = "3214C806",
            ["NextDialogue"] = 20005304,
            ["Scripts"] = "CameraMoveTo{_delay{2},TargetPosition{\"1290.28125,4.085938,560.338867,0.000019,-13.600217,-155.000031,50.0,1281.009277,false,Manual,1.2\"},duration{2}}",
            ["SpeakNpcName"] = "UI_Npc_Name_SongluVoice",
            ["VoiceName"] = "voice/$Locale$/story/2001/200053/3214C806",
            },
        [20005304] = {
            ["Camera"] = "-174.296875,-493.421875,69.123047,0.0,-9.999956,-157.999863,50.0,274.526611,false,Manual,2.0",
            ["Content"] = "真的有巨猪啊——还在对我们说话！我看我们就听它的吧，这奇怪的家伙确实很可疑！",
            ["ContentFR"] = "Ouah ! Le cochon géant est réel... et il parle ! Le Roi Démon décrète que nous devons l’écouter ! Et puis ces types étaient louches, de toute façon...",
            ["DialogueId"] = 20005304,
            ["GUID"] = "3214C830",
            ["Scripts"] = "PARA{\
PlayFacial{_delay{1},ActorId{200002},FacialId{\"Shock01\"}},\
PlayAnimation{_delay{4},ActorId{200002},AnimationId{\"SpecialConfident_Start\"},Duration{1}},\
CameraMoveTo{_delay{4},TargetPosition{\"-480.78125,-711.425781,30.280273,0.000005,-2.99999,64.808571,25.0,222.467651,false,Manual,2.0\"},duration{0}},\
CameraMoveTo{_delay{4.1},TargetPosition{\"-480.78125,-711.425781,58.818359,0.000003,-7.999968,64.807953,25.0,391.569885,false,Manual,2.0\"},blend{\"easeInOutQuad\"},duration{4}}\
}",
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:SpecialHappy_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200053/3214C830",
            },
        [20005305] = {
            ["Content"] = "可恶，算了，保命要紧，再纠缠下去怕是要被这头猪压扁，把魔灵都留给他们，我们走。",
            ["ContentFR"] = "Argh ! Tant pis ! Mieux vaut sauver notre peau avant que ce monstre nous écrase ! Lâchez les Géniemon et fuyez !",
            ["DialogueId"] = 20005305,
            ["GUID"] = "3214C85A",
            ["SpeakNpcId"] = 200075,
            ["VoiceName"] = "voice/$Locale$/story/2001/200053/3214C85A",
            },
        [20005401] = {
            ["Camera"] = "-119.943359,-388.015625,79.53125,0.000079,7.500012,142.399338,15.0,100000.0,false,Disable,2.8",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "哎呀，他们跑得也太快了，一溜烟儿就不见了，要追吗？",
            ["ContentFR"] = "Ouah ! Ils se sont volatilisés plus vite que des lapins ! On les poursuit ?",
            ["DialogueId"] = 20005401,
            ["FinalCamera"] = "-119.943359,-388.015625,79.53125,0.00008,7.500012,115.0,15.0,100000.0,false,Disable,2.8",
