            },
        [20005720] = {
            ["Camera"] = "496.032623,271.400391,167.851562,-0.000763,-15.436493,171.781372,35.000011,285.391632,false,Manual,12.0",
            ["Content"] = "嘿嘿，没想到那些凶巴巴的看守在卡米拉女士面前都乖乖巧巧，和魔灵差不多。",
            ["ContentFR"] = "Héhé, qui aurait cru que les gardes si sévères se transformeraient en gentils chatons devant Madame Camilla ? Comme les Géniemon quand ils ont des friandises.",
            ["DialogueId"] = 20005720,
            ["FinalCamera"] = "535.708679,265.305664,177.851562,-0.000763,-14.436451,172.180801,35.000011,285.391632,false,Manual,12.0",
