        [20005722] = {
            ["Camera"] = "345.16864,317.928711,137.46875,-0.000763,1.607089,136.417633,35.0,169,false,Manual,12.0",
            ["Content"] = "你有头绪吗？",
            ["ContentFR"] = "Tu as un plan ?",
            ["DialogueId"] = 20005722,
            ["FinalCamera"] = "311.653595,331.706055,134.34375,-0.000763,4.806766,132.015808,35.0,169.08606,false,Manual,12.0",
            ["GUID"] = "32150CC4",
            ["NextDialogue"] = 20005723,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Talk02_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200057/32150CC4",
            },
        [20005723] = {
            ["Camera"] = "427.671539,393.154297,128.347656,-0.000763,-6.992433,-162.983078,35.000008,216.630737,false,Manual,12.0",
            ["Content"] = "我有头猪——可靠的榛子。它嗅觉可灵敏啦，可以闻到附近魔灵们在哪里出没，应该能在附近逮到那些魔灵猎人！",
            ["ContentFR"] = "J’ai l’unique Filbert ! Son flair est incroyable, elle peut sentir les Géniemon aux alentours et repérer les chasseurs !",
            ["DialogueId"] = 20005723,
            ["FinalCamera"] = "427.671539,393.154297,128.347656,-0.000763,-8.192443,-154.983536,35.000008,216.630737,false,Manual,12.0",
            ["GUID"] = "32150CEE",
            ["LookAt"] = {
                [1] = "200074:n(200086)",
                },
            ["Scripts"] = "PARA{\
PlayFacial{_delay{2.1},ActorId{200074},FacialId{\"Happy01\"}},\
PlayAnimation{_delay{4.1},ActorId{200074},AnimationId{\"Confident_Start\"}}\
}",
            ["SpeakNpcId"] = 200074,
            ["ToFinalCameraBlendTime"] = 10,
            ["TurnTo"] = {
                [1] = "200074:p(45)",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200057/32150CEE",
            },
        [20005801] = {
            ["Content"] = "走吧，先往高处走，魔灵的气味更容易传到高处。",
            ["ContentFR"] = "Allons en hauteur, là où l’odeur se répand le mieux.",
            ["DialogueId"] = 20005801,
            ["GUID"] = "321519BA",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200074,
            ["VoiceName"] = "voice/$Locale$/story/2001/200058/321519BA",
            },
        [20005802] = {
            ["Content"] = "啊，榛子闻到了，在那里！",
            ["ContentFR"] = "Ah ! Filbert a flairé quelque chose, regardez par là !",
            ["DialogueId"] = 20005802,
            ["GUID"] = "321519E4",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200074,
            ["VoiceName"] = "voice/$Locale$/story/2001/200058/321519E4",
            },
        [20005803] = {
            ["Content"] = "是这里……但没有魔灵，只有……",
            ["ContentFR"] = "C’est bien ici... mais aucun Géniemon à l’horizon, seulement...",
            ["DialogueId"] = 20005803,
            ["GUID"] = "32151A0E",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200074,
            ["VoiceName"] = "voice/$Locale$/story/2001/200058/32151A0E",
            },
        [20005804] = {
            ["Content"] = "这是他们陷阱的痕迹，好可恶，他们应该已经走了。",
            ["ContentFR"] = "Oh non ! Leurs pièges... Ces vilains sont déjà partis !",
            ["DialogueId"] = 20005804,
            ["GUID"] = "32151A38",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 20005805,
            ["SpeakNpcId"] = 200074,
            ["VoiceName"] = "voice/$Locale$/story/2001/200058/32151A38",
            },
        [20005805] = {
            ["Content"] = "那接下来我们去人少一点的地方，气味会明显一些。",
            ["ContentFR"] = "Allons un peu plus loin, là où il y a moins de monde, l’odeur sera plus facile à suivre.",
            ["DialogueId"] = 20005805,
            ["GUID"] = "32151A62",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200074,
            ["VoiceName"] = "voice/$Locale$/story/2001/200058/32151A62",
            },
        [20005901] = {
            ["Content"] = "这里这里，{性别：大哥哥|大姐姐}别着急，慢点一点走，别滑倒啦。",
            ["ContentFR"] = "Ici, ici, {性别:Monsieur|Mademoiselle}, doucement, marche lentement, fais attention à ne pas glisser.",
            ["DialogueId"] = 20005901,
            ["GUID"] = "32152A22",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200074,
            ["VoiceName"] = "voice/$Locale$/story/2001/200059/32152A22",
            },
        [20005902] = {
            ["Content"] = "呃……这里也是一样，有人布设过陷阱。",
            ["ContentFR"] = "Euh... ici aussi, il y a un piège.",
            ["DialogueId"] = 20005902,
            ["GUID"] = "32152A4C",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 20005903,
            ["SpeakNpcId"] = 200074,
            ["VoiceName"] = "voice/$Locale$/story/2001/200059/32152A4C",
            },
        [20005903] = {
            ["Content"] = "哼唧……",
            ["ContentFR"] = "<I>Groin…</>",
            ["DialogueId"] = 20005903,
            ["GUID"] = "32152A76",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 20005904,
            ["SpeakNpcId"] = 200086,
            ["VoiceName"] = "voice/$Locale$/story/2001/200059/32152A76",
            },
        [20005904] = {
            ["Content"] = "榛子别丧气，我们再试试下一处地方。",
            ["ContentFR"] = "Allez, Filbert, ne te décourage pas, on essaie l’endroit suivant.",
            ["DialogueId"] = 20005904,
            ["GUID"] = "32152AA0",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200074,
            ["VoiceName"] = "voice/$Locale$/story/2001/200059/32152AA0",
            },
        [20006001] = {
            ["Camera"] = "606.297791,-918.271484,784.640625,0.000207,-7.459188,79.056267,35.000015,174.116943,false,Manual,12.0",
            ["Content"] = "这里是……下水道入口？",
            ["ContentFR"] = "C’est... l’entrée des égouts ?",
            ["DialogueId"] = 20006001,
            ["FinalCamera"] = "541.89978,-1160.757812,832.416992,0.000208,-8.459162,77.455727,35.000015,174.116943,false,Manual,12.0",
