            ["TalkActionId"] = {
                [1] = "200074:Think_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32153ADE",
            },
        [20006004] = {
            ["Camera"] = "-913.889771,-785.241211,282.312012,0.000156,-6.059081,28.454039,35.000015,174.116943,false,Manual,12.0",
            ["Content"] = "啊，是还没被收走的陷阱！里面还有一只魔灵！",
            ["ContentFR"] = "Ah ! Un piège encore intact ! Il y a un Géniemon à l’intérieur !",
            ["DialogueId"] = 20006004,
            ["FinalCamera"] = "-932.27832,-741.113281,282.15332,0.000157,-6.459043,18.853708,35.000015,174.116943,false,Manual,12.0",
            ["GUID"] = "32153B08",
