            },
        [20006013] = {
            ["Camera"] = "-383.416382,-617.654297,369.226074,0.000175,-13.632108,-162.021347,35.000019,314.116943,false,Manual,2.8",
            ["Content"] = "哎呀，别乱叫了，快走快走。下一次再被抓的话，可就不一定有这么好的运气了。",
            ["ContentFR"] = "Allez, arrête de piailler maintenant et pars vite. La prochaine fois, tu n’auras peut-être pas autant de chance.",
            ["DialogueId"] = 20006013,
            ["FacialId"] = {
                [1] = "200002:Confident01",
                },
            ["FinalCamera"] = "-444.914062,-637.505859,353.714355,0.000175,-13.432099,-162.221298,35.000019,324.116943,false,Manual,2.8",
            ["GUID"] = "32153C82",
