            },
        [20006014] = {
            ["Camera"] = "-615.953979,-649.889648,308.302246,0.000101,-13.6588,-149.769836,35.000023,174.116943,false,Manual,12.0",
            ["Content"] = "我看……这只魔灵不太聪明嘛，和它说了这么多，都还不走。",
            ["ContentFR"] = "Hmmm... je crois que ce Géniemon n’est pas très futé, on lui explique tout, et il ne veut quand même pas partir.",
            ["DialogueId"] = 20006014,
            ["FacialId"] = {
                [1] = "200002:Unhappy02",
                },
            ["FinalCamera"] = "-644.868896,-667.681641,299.754395,0.000098,-11.858697,-147.368286,35.000023,174.116943,false,Manual,12.0",
            ["GUID"] = "32153CAC",
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Confident_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32153CAC",
            },
        [20006015] = {
            ["Content"] = "啪叽——",
            ["ContentFR"] = "<I>clac—</>",
            ["DialogueId"] = 20006015,
            ["GUID"] = "32153CD6",
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32153CD6",
            },
        [20006016] = {
            ["Camera"] = "-828.218018,-695.823242,274.558105,0.0,-10.196652,12.391548,11.88,174.116943,false,Manual,12.0",
            ["Content"] = "诶？怎么又钻到陷阱里去了？这只魔灵，是不是太害怕我们，所以把陷阱当做是安全的地方了？",
            ["ContentFR"] = "Hein ? Il s’est recaché dans le piège ? Est-ce qu’il a tellement peur de nous qu’il croit être en sécurité là-dedans ?",
            ["DialogueId"] = 20006016,
            ["FinalCamera"] = "-812.047607,-692.268555,271.699219,0.0,-9.796662,12.39166,11.88,174.116943,false,Manual,12.0",
            ["GUID"] = "32153D00",
            ["NextDialogue"] = 20006017,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:SpecialConfident_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32153D00",
            },
        [20006017] = {
            ["Camera"] = "-760.560303,-565.728516,290.460938,0.000099,-1.191192,-176.627136,35.000011,174.459366,false,Manual,2.8",
            ["Content"] = "唔，不应该呀，我们明明救过它，并且也没有表现出敌意。魔灵们虽然不会说话，但是是能分清楚谁对它好，谁对它坏的。",
            ["ContentFR"] = "Non, ça ne colle pas. On l’a déjà sauvé, et on n’a montré aucune hostilité. Les Géniemons ne parlent pas, mais ils savent distinguer qui leur veut du bien et qui leur veut du mal.",
            ["DialogueId"] = 20006017,
            ["FacialId"] = {
                [1] = "200074:Sad01",
                },
            ["FinalCamera"] = "-784.401123,-567.131836,289.964355,0.000099,-1.191192,-176.427139,35.000011,138.232086,false,Manual,2.8",
            ["GUID"] = "32153D2A",
            ["NextDialogue"] = 20006018,
            ["SpeakNpcId"] = 200074,
            ["TalkActionId"] = {
                [1] = "200074:Think_Start",
                [2] = "200002:SpecialConfident_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32153D2A",
            },
        [20006018] = {
            ["Camera"] = "-538.68689,-695.786133,229.021973,0.000027,5.603125,151.387604,35.000008,345.779022,false,Manual,12.0",
            ["Content"] = "我想想……榛子有没有像这样，做的事我一开始完全无法理解的时候……",
            ["ContentFR"] = "Hmm... Filbert a-t-elle déjà fait des choses que je ne comprenais pas, au début ?",
            ["DialogueId"] = 20006018,
            ["FinalCamera"] = "-556.785034,-685.914062,231.044922,0.000028,5.603125,151.387619,35.000008,278.757599,false,Manual,12.0",
            ["GUID"] = "32153D54",
            ["NextDialogue"] = 20006019,
            ["SpeakNpcId"] = 200074,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32153D54",
            },
        [20006019] = {
            ["Camera"] = "-152.133362,-1170.719727,714.169434,0.000035,-27.996868,146.383102,35.0,674.116943,false,Manual,22.0",
            ["Content"] = "一次非得去看起来光秃秃的山谷里，后来才知道是因为它闻到了山谷深处有许多浆果……一次是停在花店门口不走，等我买了花，它就开心地一口吃掉……",
            ["ContentFR"] = "Une fois, elle a absolument voulu aller dans une vallée qui paraissait toute vide... et en fait, il y avait plein de baies cachées ! Une autre fois, elle est restée bloquée devant une boutique de fleurs, alors je lui en ai acheté une... et elle l’a engloutie d’un seul coup !",
            ["DialogueId"] = 20006019,
            ["FinalCamera"] = "-66.008728,-699.472656,615.159668,0.000042,-26.596804,175.382294,35.0,671.116943,false,Manual,22.0",
            ["GUID"] = "32153D7E",
            ["NextDialogue"] = 20006020,
            ["SpeakNpcId"] = 200074,
            ["ToFinalCameraBlendTime"] = 20,
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32153D7E",
            },
        [20006020] = {
            ["Content"] = "还有一次，是它丢下我，拼命往山坡上跑，是因为附近的草丛里有蛇……它想把蛇引开……",
            ["ContentFR"] = "Et puis il y a eu la fois où elle m’a laissée pour filer en haut d’une colline, il y avait un serpent dans les herbes, et elle voulait l’éloigner.",
            ["DialogueId"] = 20006020,
            ["GUID"] = "32153DA8",
            ["NextDialogue"] = 20006021,
            ["SpeakNpcId"] = 200074,
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32153DA8",
            },
        [20006021] = {
            ["Camera"] = "-854.367188,-711.143555,293.184082,0.000106,-12.591494,30.173449,35.000008,1674.542114,false,Manual,8.0",
            ["Content"] = "嗯……都是因为有很在意的事情……魔灵会在意什么呢？食物……还有伙伴！",
            ["ContentFR"] = "Hum... à chaque fois, c’était parce qu’elle avait senti quelque chose d’important... Qu’est-ce qui compte pour un Géniemon ? La nourriture... et les amis !",
            ["DialogueId"] = 20006021,
            ["FinalCamera"] = "-942.035889,-762.558594,315.785645,0.000113,-12.391452,31.173887,35.000008,1674.542114,false,Manual,8.0",
            ["GUID"] = "32153DD2",
            ["NextDialogue"] = 20006022,
            ["SpeakNpcId"] = 200074,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32153DD2",
            },
        [20006022] = {
            ["Camera"] = "-800.104004,-669.561523,327.374512,0.000095,-2.797638,176.175522,35.000008,104.665184,false,Manual,12.0",
            ["Content"] = "伙伴……我明白了！如果猜得没错的话，那些魔灵猎人的藏身之处就在下水道里。",
            ["ContentFR"] = "Les amis... je vois ! Si je ne me trompe pas, la cachette des chasseurs doit être dans les égouts.",
            ["DialogueId"] = 20006022,
            ["FacialId"] = {
                [1] = "100001:Satisfy01",
                },
            ["GUID"] = "32153DFC",
            ["NextDialogue"] = 20006023,
            ["Scripts"] = "SEQ{CameraMoveTo{_delay{6},TargetPosition{\"535.722229,-1070.53125,709.230469,0.000068,-6.997009,79.177307,35.0,174.116943,false,Manual,12.0\"},duration{0}},CameraMoveTo{_delay{0.5},TargetPosition{\"868.026001,153.00293,482.812988,0.000102,-2.791628,85.174393,35.000008,1674.542114,false,Manual,2.8\"},duration{5}}}",
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "200074:Think_End",
                [2] = "100001:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32153DFC",
            },
        [20006023] = {
            ["Camera"] = "-687.931763,-671.883789,322.655273,0.000069,-2.197053,176.775879,35.0,174.116943,false,Manual,12.0",
            ["Content"] = "在这里能嗅到其他被抓的魔灵的气息，所以它才不愿意离开。",
            ["ContentFR"] = "Ici, il sent l’odeur des autres Géniemon capturés, c’est pour ça qu’il refuse de s’éloigner.",
            ["DialogueId"] = 20006023,
            ["FacialId"] = {
                [1] = "100001:Confident02",
                },
            ["FinalCamera"] = "-771.952148,-667.40625,310.516113,0.000069,5.202958,177.175873,35.0,174.116943,false,Manual,12.0",
            ["GUID"] = "32153E26",
            ["NextDialogue"] = 20006024,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Think_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32153E26",
            },
        [20006024] = {
            ["Camera"] = "-821.866577,-728.666992,342.821289,0.000095,-11.597776,130.969742,35.000008,178.123947,false,Manual,2.8",
            ["Content"] = "很有可能噢，那这样一来的话，我们就可以在边上等着，要是那些魔灵猎人出现了，就跟着他们，狠狠教训他们一顿！",
            ["ContentFR"] = "Très probable ! Alors on attend ici. Si les chasseurs viennent récupérer le Géniemon, on les suit et on leur donnera une bonne leçon !",
            ["DialogueId"] = 20006024,
            ["FacialId"] = {
                [1] = "200074:Confident01",
                },
            ["FinalCamera"] = "-828.375366,-721.172852,340.748047,0.000093,-11.797785,130.969742,35.000008,178.123947,false,Manual,2.8",
            ["GUID"] = "32153E50",
            ["NextDialogue"] = 20006025,
            ["Scripts"] = "SEQ{\
LookAt{LookAtDescription{\"200074:n(100001)\"}},\
LookAt{LookAtDescription{\"100001:n(200074)\"}},\
PlayAnimation{ActorId{200074},AnimationId{\"AgreeHead\"},Duration{1}},\
PlayAnimation{_delay{5},\
ActorId{200074},AnimationId{\"Angry01_Start\"},Duration{2}}}",
            ["SpeakNpcId"] = 200074,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32153E50",
            },
        [20006025] = {
            ["Camera"] = "-788.137817,-637.754883,224.224121,0.000072,-2.597166,-0.625336,35.0,174.116943,false,Manual,12.0",
            ["Content"] = "嗯嗯嗯！",
            ["ContentFR"] = "<I>Yiip—!</>",
            ["DialogueId"] = 20006025,
            ["FacialId"] = {
                [1] = "100001:None",
                },
            ["FinalCamera"] = "-756.913574,-638.139648,223.32666,0.000072,-3.397097,-1.225342,35.0,174.116943,false,Manual,12.0",
            ["GUID"] = "32153E7A",
            ["NextDialogue"] = 20006026,
            ["SpeakNpcId"] = 700251,
            ["SpeakNpcName"] = "UI_Npc_Name_PanBeikun",
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32153E7A",
            },
        [20006026] = {
            ["Camera"] = "-412.370728,-629.598633,225.119141,0.000073,3.802544,-175.221069,28.0,265.494751,false,Manual,12.0",
            ["Content"] = "唔，该说这只魔灵是聪明还是笨呢？能想着要去找伙伴，算得上是聪明吧，但又自己进到陷阱里，有点笨笨的。",
            ["ContentFR"] = "Hmm, alors ce Géniemon est intelligent ou stupide ? Car il a l’intelligence de vouloir qu’on sauve ses amis, mais il vient aussi de retourner dans un piège...",
            ["DialogueId"] = 20006026,
            ["FinalCamera"] = "-412.370728,-629.598633,241.541992,0.000073,0.002452,-175.420853,28.0,265.494751,false,Manual,12.0",
            ["GUID"] = "32153EA4",
            ["LookAt"] = {
                [1] = "200002:n(700251)",
                },
            ["NextDialogue"] = 20006027,
            ["Scripts"] = "PARA{\
LookAt{LookAtDescription{\"200074:n(200074)\"}},\
LookAt{LookAtDescription{\"100001:n(100001)\"}},\
PlayAnimation{ActorId{200074},AnimationId{\"Angry01_End\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Think_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32153EA4",
            },
        [20006027] = {
            ["Camera"] = "-700.815918,-705.999023,263.483887,0.000069,3.402636,153.177032,35.0,174.116943,false,Manual,12.0",
            ["Content"] = "说不定它是看到我们，才故意又进到陷阱里，让我们好跟踪呢。",
            ["ContentFR"] = "Peut-être qu’il est revenu exprès dans le piège pour qu’on puisse le suivre jusqu’au repaire des chasseurs.",
            ["DialogueId"] = 20006027,
            ["FinalCamera"] = "-755.168457,-688.192383,266.806152,0.000068,3.602624,148.576843,35.0,174.116943,false,Manual,12.0",
            ["GUID"] = "32153ECE",
            ["NextDialogue"] = 20006028,
            ["SpeakNpcId"] = 200074,
            ["TalkActionId"] = {
                [1] = "200074:Talk02_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32153ECE",
            },
        [20006028] = {
            ["Camera"] = "-486.203613,-623.530273,240.246582,0.000087,2.002625,-162.023193,35.0,174.116943,false,Manual,12.0",
            ["Content"] = "真的假的？我觉得——",
            ["ContentFR"] = "Oh, vraiment ? C’est—",
            ["DialogueId"] = 20006028,
            ["FacialId"] = {
                [1] = "200002:Shock02",
                },
            ["FinalCamera"] = "-531.324463,-638.469727,243.410156,0.000087,4.602584,-160.822952,35.0,174.116943,false,Manual,12.0",
            ["GUID"] = "32153EF8",
            ["NextDialogue"] = 20006029,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200074:Talk02_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32153EF8",
            },
        [20006029] = {
            ["Content"] = "哎？不错啊，真抓到了一只。",
            ["ContentFR"] = "Hé ? Pas mal, on en a attrapé un autre.",
            ["DialogueId"] = 20006029,
            ["GUID"] = "32153F22",
            ["NextDialogue"] = 20006030,
            ["SpeakNpcId"] = 200075,
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32153F22",
            },
        [20006030] = {
            ["Camera"] = "-647.833496,-724.029297,337.969727,0.000094,-6.997679,159.175262,35.0,324.116943,false,Manual,12.0",
            ["Content"] = "是魔灵猎人，快躲起来。",
            ["ContentFR"] = "Ce sont les chasseurs de Géniemon. Cachez-vous !",
            ["DialogueId"] = 20006030,
            ["GUID"] = "32153F4C",
            ["NextDialogue"] = 20006031,
            ["SpeakNpcId"] = 100001,
            ["TurnTo"] = {
                [1] = "100001:n(200074)",
                [2] = "200074:n(100001)",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32153F4C",
            },
        [20006031] = {
            ["Content"] = "好！",
            ["ContentFR"] = "D’accord !",
            ["DialogueId"] = 20006031,
            ["GUID"] = "32153F76",
            ["SpeakNpcId"] = 200074,
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32153F76",
            },
        [20006032] = {
            ["Camera"] = "-593.543457,-336.325195,269.372559,0.000176,-9.390683,-128.619858,35.000008,268.984894,false,Manual,12.0",
            ["Content"] = "好想现在就揍他们一顿，不过算了，等会儿有他们好看的！",
            ["ContentFR"] = "J’ai bien envie de leur casser la figure tout de suite, mais bon, on gardera ça pour plus tard !",
            ["DialogueId"] = 20006032,
            ["FacialId"] = {
                [1] = "200002:Angry01",
                },
            ["FinalCamera"] = "-632.141357,-384.262695,260.398438,0.000174,-8.190715,-130.618393,35.000008,268.984894,false,Manual,12.0",
            ["GUID"] = "32153FA0",
            ["NextDialogue"] = 20006033,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Confident_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32153FA0",
            },
        [20006033] = {
            ["Camera"] = "-1663.477051,-843.626953,503.279785,0.000179,-12.99065,25.976145,35.0,1674.542114,false,Manual,2.8",
            ["Content"] = "本来以为冰湖城里的魔灵已经快被抓完了，没想到还有收获。",
            ["ContentFR"] = "Je pensais que nous avions déjà capturé tous les Géniemon de Givrelac, mais il semble que nous en ayons attrapé un autre...",
            ["DialogueId"] = 20006033,
            ["GUID"] = "32153FCA",
            ["NextDialogue"] = 20006034,
            ["SpeakNpcId"] = 200075,
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32153FCA",
            },
        [20006034] = {
            ["Camera"] = "-468.823608,196.549805,329.405273,0.000182,-6.590613,-5.024419,35.000008,1033.678345,false,Manual,22.0",
            ["Content"] = "还是得出城啊，出城才能抓到更多。也不知道那个骑猪的小女孩什么时候才走。",
            ["ContentFR"] = "Nous devons encore sortir de la cité, c’est là qu’on en attrape le plus. Mais cette gamine qui monte sur son cochon, quand est-ce qu’elle va enfin bouger ?",
            ["DialogueId"] = 20006034,
            ["FinalCamera"] = "-443.855225,194.355469,326.509277,0.000182,-6.590613,-5.024419,35.000008,1033.678345,false,Manual,22.0",
            ["GUID"] = "32153FF4",
            ["NextDialogue"] = 20006035,
            ["SpeakNpcId"] = 200087,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32153FF4",
            },
        [20006035] = {
            ["Content"] = "别急嘛，我就不信了，捱上半个月，她还能在那里守着。",
            ["ContentFR"] = "T’inquiète pas, elle partira. Elle ne va pas pouvoir rester bien longtemps devant la cité.",
            ["DialogueId"] = 20006035,
            ["GUID"] = "3215401E",
            ["NextDialogue"] = 20006036,
            ["SpeakNpcId"] = 200075,
            ["TalkActionId"] = {
                [1] = "200075:Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/3215401E",
            },
        [20006036] = {
            ["Content"] = "也是，天寒地冻的还有秽兽，说不定明天她就哭着鼻子回家啦。",
            ["ContentFR"] = "Ouais, avec le froid et les Souillés, elle risque de bien vite rentrer en pleurant.",
            ["DialogueId"] = 20006036,
            ["GUID"] = "32154048",
            ["NextDialogue"] = 20006037,
            ["SpeakNpcId"] = 200087,
            ["TalkActionId"] = {
                [1] = "200075:Talk02_End",
                [2] = "200087:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32154048",
            },
        [20006037] = {
            ["Content"] = "最好这样！",
            ["ContentFR"] = "Tant mieux !",
            ["DialogueId"] = 20006037,
            ["GUID"] = "32154072",
            ["SpeakNpcId"] = 200075,
            ["TalkActionId"] = {
                [1] = "200075:Angry01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32154072",
            },
        [20006101] = {
            ["Camera"] = "-1302.360229,-832.505859,345.045898,0.000178,-0.789761,21.978495,35.0,1674.542114,false,Manual,2.8",
            ["Content"] = "他们回下水道里了，走，快跟上。",
            ["ContentFR"] = "Ils retournent dans les égouts ! Allez, on les suit vite !",
            ["DialogueId"] = 20006101,
            ["FacialId"] = {
                [1] = "200002:Confident02",
                },
            ["GUID"] = "32154AF2",
            ["NextDialogue"] = 20006102,
            ["Scripts"] = "PARA{SEQ{TurnTo{TurnToDescription{\"200002:n(100001)\"}},PlayAnimation{_delay{0.1},ActorId{200002},AnimationId{\"Confident_Start\"},Duration{1}}},CameraMoveTo{_delay{2},TargetPosition{\"-840.86145,-688.524414,290.947754,0.000184,-10.389148,-19.824919,35.000008,95.310921,false,Manual,2.8\"},duration{0}}}",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/2001/200061/32154AF2",
            },
        [20006102] = {
            ["Camera"] = "-691.08667,-817.638672,263.54541,0.000229,8.209702,133.76033,35.000011,242.476578,false,Manual,2.8",
            ["Content"] = "小声点，别兴高采烈的，如果惊动了魔灵猎人，那只魔灵要是会说话，一定会骂你笨蛋的。",
            ["ContentFR"] = "Chut, parle moins fort. Si nous nous faisons repérer, ce Géniemon que nous venons de sauver te traitera sûrement d’idiote.",
            ["DialogueId"] = 20006102,
            ["FinalCamera"] = "-710.927734,-796.919922,267.683105,0.000229,8.209702,133.76033,35.000011,242.476578,false,Manual,2.8",
            ["GUID"] = "32154B1C",
            ["LookAt"] = {
                [1] = "100001:n(200002)",
                },
            ["NextDialogue"] = 20006103,
            ["Scripts"] = "LookAt{LookAtDescription{\"200074:n(200002)\"}}",
            ["SpeakNpcId"] = 100001,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200061/32154B1C",
            },
        [20006103] = {
            ["Camera"] = "-840.86145,-688.524414,290.947754,0.000184,-10.389148,-19.824919,35.000008,95.310921,false,Manual,2.8",
            ["Content"] = "哼，才不会，我刚刚那么关心它，一定给它留下了好印象！",
            ["ContentFR"] = "Hmpf, impossible ! J’ai été si gentille avec lui que je lui ai laissé une impression divine.",
            ["DialogueId"] = 20006103,
            ["FacialId"] = {
                [1] = "200002:Confident01",
                },
            ["GUID"] = "32154B46",
            ["LookAt"] = {
                [1] = "200074:n(100001)",
                },
            ["NextDialogue"] = 20006104,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/2001/200061/32154B46",
            },
        [20006104] = {
            ["Camera"] = "-832.142822,-728.967773,342.387207,0.000241,-11.390535,127.158501,35.000011,192.086792,false,Manual,2.8",
            ["Content"] = "噗哧……你们啊……虽然我年纪不大，但是带着榛子也见过很多人了，但像你们这样，在意魔灵想法的人可不多。",
            ["ContentFR"] = "Haha... vous deux... Même si je suis petite, j’ai beaucoup voyagé avec Filbert et j’ai rencontré plein de gens, mais peu se soucient vraiment de ce que ressentent les Géniemon.",
            ["DialogueId"] = 20006104,
            ["FinalCamera"] = "-837.814453,-721.487305,340.496582,0.000241,-11.390535,127.158501,35.000011,192.086792,false,Manual,2.8",
            ["GUID"] = "32154B70",
            ["LookAt"] = {
                [1] = "100001:n(200074)",
                },
            ["NextDialogue"] = 20006105,
            ["SpeakNpcId"] = 200074,
            ["TalkActionId"] = {
                [1] = "200074:Talk02_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200061/32154B70",
            },
        [20006105] = {
            ["Content"] = "要是每个人都像你们一样，意识到动物和魔灵也是有自己喜好的，就不会有魔灵猎人了！",
            ["ContentFR"] = "Si tout le monde pensait comme vous, que les Géniemon ont leurs propres pensées et sentiments, il n’y aurait pas de chasseurs de Géniemon.",
            ["DialogueId"] = 20006105,
            ["GUID"] = "32154B9A",
            ["NextDialogue"] = 20006106,
            ["SpeakNpcId"] = 200074,
            ["TalkActionId"] = {
                [1] = "200074:Talk02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200061/32154B9A",
            },
        [20006106] = {
            ["Camera"] = "-809.379883,-578.354492,277.954102,0.000212,5.809533,178.160782,35.000011,115.034302,false,Manual,2.8",
            ["Content"] = "走吧走吧，这一次我一定要让他们彻底知错！",
            ["ContentFR"] = "Allez, on y va ! Cette fois, je leur ferai comprendre leur erreur !",
            ["DialogueId"] = 20006106,
            ["FinalCamera"] = "-822.223877,-577.945312,279.260742,0.000213,5.809533,178.160782,35.000011,110.479393,false,Manual,2.8",
            ["GUID"] = "32154BC4",
            ["LookAt"] = {
                [1] = "200074:n(200074)",
                },
            ["SpeakNpcId"] = 200074,
            ["TalkActionId"] = {
                [1] = "200074:Confident_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200061/32154BC4",
            },
        [20006201] = {
            ["Camera"] = "-287.4375,38.861328,166.546265,0.000031,-8.400183,-1.804748,18.000004,100000.0,false,Manual,2.8",
            ["Content"] = "唔，原来这里的下水道这么复杂。榛子，能闻到魔灵的味道吗？",
            ["ContentFR"] = "Oh, les égouts sont vraiment compliqués. Filbert, tu sens quelque chose ?",
            ["DialogueId"] = 20006201,
            ["GUID"] = "32155B5A",
            ["NextDialogue"] = 20006202,
            ["SpeakNpcId"] = 200074,
            ["VoiceName"] = "voice/$Locale$/story/2001/200062/32155B5A",
            },
        [20006202] = {
            ["Content"] = "哼唧……",
            ["ContentFR"] = "<I>Groin...</>",
            ["DialogueId"] = 20006202,
            ["GUID"] = "32155B84",
            ["NextDialogue"] = 20006203,
            ["SpeakNpcId"] = 200086,
            ["VoiceName"] = "voice/$Locale$/story/2001/200062/32155B84",
            },
        [20006203] = {
            ["Content"] = "味道太多了反而无法分辨方向？唔，只能先向前走了。",
            ["ContentFR"] = "Il y a tellement d’odeurs mélangées qu’on n’arrive pas à s’orienter. Bon, avançons quand même.",
            ["DialogueId"] = 20006203,
            ["GUID"] = "32155BAE",
            ["NextDialogue"] = 20006204,
            ["SpeakNpcId"] = 200074,
            ["VoiceName"] = "voice/$Locale$/story/2001/200062/32155BAE",
            },
        [20006204] = {
            ["Content"] = "跟着我走就好，我对这里可熟悉了。",
            ["ContentFR"] = "Suivez-moi, je connais bien ce terrain.",
            ["DialogueId"] = 20006204,
            ["GUID"] = "32155BD8",
            ["NextDialogue"] = 20006205,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/2001/200062/32155BD8",
            },
        [20006205] = {
            ["Content"] = "咦，原来小白平时住在这种地方吗？",
            ["ContentFR"] = "Hein ? Tu habites dans des endroits comme ça, Snow ?",
            ["DialogueId"] = 20006205,
            ["GUID"] = "32155C02",
            ["NextDialogue"] = 20006206,
            ["SpeakNpcId"] = 200074,
            ["VoiceName"] = "voice/$Locale$/story/2001/200062/32155C02",
            },
        [20006206] = {
            ["Content"] = "不……不是的，只是身为魔王大人，之前来过这里巡视过几次，远来的魔灵猎人猎人哟，跟紧了。",
            ["ContentFR"] = "B-Bien sûr que non. Mais en tant que Roi Démon, j’ai déjà inspecté ces tunnels plusieurs fois. Suis-moi, Chasseuse de Chasseurs de Géniemon venue de loin !",
            ["DialogueId"] = 20006206,
            ["GUID"] = "32155C2C",
            ["NextDialogue"] = 20006207,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/2001/200062/32155C2C",
            },
        [20006207] = {
            ["Content"] = "好~",
            ["ContentFR"] = "D’accord !",
            ["DialogueId"] = 20006207,
            ["GUID"] = "32155C56",
            ["SpeakNpcId"] = 200074,
            ["VoiceName"] = "voice/$Locale$/story/2001/200062/32155C56",
            },
        [20006301] = {
            ["Content"] = "啊，这个痕迹，之前巡视的时候可没有见到过。",
            ["ContentFR"] = "Ah, cette marque, je ne l’avais pas vue lors de mes précédentes patrouilles.",
            ["DialogueId"] = 20006301,
            ["GUID"] = "32156BC2",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 20006302,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/2001/200063/32156BC2",
            },
        [20006302] = {
            ["Content"] = "看起来像是被抓的那个魔灵留下来的，跟着这个痕迹吧。",
            ["ContentFR"] = "On dirait la trace laissée par le Géniemon qu’on a sauvé. Suivons-la.",
            ["DialogueId"] = 20006302,
            ["GUID"] = "32156BEC",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200074,
            ["VoiceName"] = "voice/$Locale$/story/2001/200063/32156BEC",
            },
        [20006401] = {
            ["Content"] = "痕迹越来越新，应该不远了……",
            ["ContentFR"] = "Les traces sont de plus en plus fraîches, on doit être proches...",
            ["DialogueId"] = 20006401,
            ["GUID"] = "32157C2A",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 20006402,
            ["SpeakNpcId"] = 200074,
            ["VoiceName"] = "voice/$Locale$/story/2001/200064/32157C2A",
            },
        [20006402] = {
            ["Content"] = "我好像听见有人在说话——",
            ["ContentFR"] = "J’entends des voix—",
            ["DialogueId"] = 20006402,
            ["GUID"] = "32157C54",
            ["GuideFacialId"] = "Confident",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/2001/200064/32157C54",
            },
        [20006501] = {
            ["Camera"] = "802.462891,37.094727,399.100616,0.000002,-18.600189,1.600099,35.000011,403.34671,false,Manual,12.0",
            ["Content"] = "我跟你说，这只魔灵……据说是所有魔灵里最聪明、最稀有、也是所有魔灵的最初形态——潘神。",
            ["ContentFR"] = "On a touché le gros lot, tu sais, celui-ci est spécial ! C’est le Paniemon, ils disent que c’est le plus intelligent, le plus rare et la forme originale de tous les Géniemon.",
            ["DialogueId"] = 20006501,
            ["FinalCamera"] = "559.453125,30.306641,481.861816,0.000002,-18.800184,1.600099,35.000011,403.34671,false,Manual,12.0",
            ["GUID"] = "32158C92",
            ["NextDialogue"] = 20006502,
            ["SpeakNpcId"] = 200075,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200065/32158C92",
            },
        [20006502] = {
            ["Content"] = "最聪明？真的假的？真要是最聪明，怎么会被我们抓到？",
            ["ContentFR"] = "Le plus intelligent ? Sérieux ? S’il est si malin, comment a-t’il pu finir dans notre piège ?",
            ["DialogueId"] = 20006502,
            ["GUID"] = "32158CBC",
            ["NextDialogue"] = 20006503,
            ["SpeakNpcId"] = 200087,
            ["TalkActionId"] = {
                [1] = "200087:Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200065/32158CBC",
            },
        [20006503] = {
            ["Camera"] = "565.943359,-554.305664,435.741028,0.000025,-6.400112,56.795567,35.000008,100000.0,false,Manual,22.0",
            ["Content"] = "你什么意思？你是说我们很笨，所以不可能抓到最聪明的魔灵？",
            ["ContentFR"] = "Qu’est-ce que tu insinues ? Tu veux dire qu’on est trop stupides pour attraper le plus malin des Géniemon ?",
            ["DialogueId"] = 20006503,
            ["FinalCamera"] = "586.517578,-522.865234,431.526306,0.000026,-6.400112,56.795399,35.000008,100000.0,false,Manual,22.0",
            ["GUID"] = "32158CE6",
            ["LookAt"] = {
                [1] = "200075:n(200087)",
                },
            ["NextDialogue"] = 20006504,
            ["SpeakNpcId"] = 200075,
            ["TalkActionId"] = {
                [1] = "200075:Talk03_Start",
                [2] = "200087:Talk02_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200065/32158CE6",
            },
        [20006504] = {
            ["Camera"] = "485.179688,62.989258,489.663513,0.000012,-12.999386,-2.199652,35.000008,450.0,false,Manual,6.0",
            ["Content"] = "我……我没这个意思，老大你可聪明了，要不是靠着你做的陷阱，我们怎么能抓到这么多魔灵。",
            ["ContentFR"] = "N-Non, je ne voulais pas dire ça. Patron, t’es un génie ! Sans tes pièges, on n’en aurait jamais capturé autant.",
            ["DialogueId"] = 20006504,
            ["FinalCamera"] = "610.728516,58.283203,460.538757,0.000012,-13.199401,-1.999653,35.000008,450.0,false,Manual,6.0",
            ["GUID"] = "32158D10",
            ["LookAt"] = {
                [1] = "200087:n(200075)",
                },
            ["NextDialogue"] = 20006505,
            ["SpeakNpcId"] = 200087,
            ["TalkActionId"] = {
                [1] = "200087:Shock_Start",
                },
            ["ToFinalCameraBlendTime"] = 15,
            ["VoiceName"] = "voice/$Locale$/story/2001/200065/32158D10",
            },
        [20006505] = {
            ["Content"] = "那是，你看，咱们已经抓了这么多魔灵，慢慢来研究，总能找出从它们身上炼出月石的方法，写出论文来。",
            ["ContentFR"] = "Exactement. Avec tout ce qu’on a rassemblé, on finira par percer la méthode d’extraction du Phoxène. J’en ferai une thèse.",
            ["DialogueId"] = 20006505,
            ["GUID"] = "32158D3A",
            ["LookAt"] = {
                [1] = "200075:n(200075)",
                },
            ["NextDialogue"] = 20006506,
            ["SpeakNpcId"] = 200075,
            ["TalkActionId"] = {
                [1] = "200087:Shock_End",
                [2] = "200075:Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200065/32158D3A",
            },
        [20006506] = {
            ["Content"] = "到时候，我看谁还敢嘲笑我是炼金院的肄业生！",
            ["ContentFR"] = "Ensuite, qui osera encore se moquer de moi pour avoir abandonné l’Académie d’Alchimie ?",
            ["DialogueId"] = 20006506,
            ["GUID"] = "32158D64",
            ["NextDialogue"] = 20006507,
            ["SpeakNpcId"] = 200075,
            ["TalkActionId"] = {
                [1] = "200075:Angry01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200065/32158D64",
            },
        [20006507] = {
            ["Content"] = "老大，我对论文什么的不感兴趣，能分点银币给我就好了。",
            ["ContentFR"] = "Patron, je me fiche de toutes ces histoires de thèse. Je veux juste avoir ma part des pièces d’argent.",
            ["DialogueId"] = 20006507,
            ["GUID"] = "32158D8E",
            ["NextDialogue"] = 20006508,
            ["SpeakNpcId"] = 200087,
            ["TalkActionId"] = {
                [1] = "200075:Angry01_End",
                [2] = "200087:Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200065/32158D8E",
            },
        [20006508] = {
            ["Content"] = "好说，都好说。",
            ["ContentFR"] = "Bien sûr, ne t’inquiète pas.",
            ["DialogueId"] = 20006508,
            ["GUID"] = "32158DB8",
            ["LookAt"] = {
                [1] = "200087:n(200087)",
                },
            ["NextDialogue"] = 20006509,
            ["SpeakNpcId"] = 200075,
            ["TalkActionId"] = {
                [1] = "200087:Talk01_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200065/32158DB8",
            },
        [20006509] = {
            ["Camera"] = "0.919922,-0.328125,154.78241,0.000047,-0.999783,-169.994827,35.000008,147.718536,false,Manual,8.0",
            ["Content"] = "我觉得，不怎么好说。",
            ["ContentFR"] = "Cela ne sera pas aussi simple.",
            ["DialogueId"] = 20006509,
            ["FacialId"] = {
                [1] = "100001:Confident02",
                },
            ["GUID"] = "32158DE2",
            ["NextDialogue"] = 20006510,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Confident_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200065/32158DE2",
            },
        [20006510] = {
            ["Camera"] = "460.484375,70.31543,355.815216,0.000048,1.599391,-2.995058,35.000008,300.0,false,Manual,8.0",
            ["Content"] = "你们是……",
            ["ContentFR"] = "Vous êtes qui, vous... ?",
            ["DialogueId"] = 20006510,
            ["FinalCamera"] = "525.451172,67.851562,357.435608,0.000048,1.39939,-2.39505,35.000008,300.0,false,Manual,8.0",
            ["GUID"] = "32158E0C",
            ["NextDialogue"] = 20006511,
            ["Scripts"] = "PARA{TurnTo{TurnToDescription{\"200075:p(-150)\"}},TurnTo{TurnToDescription{\"200087:p(150)\"}}}",
            ["SpeakNpcId"] = 200075,
            ["TalkActionId"] = {
                [1] = "100001:Confident_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200065/32158E0C",
            },
        [20006511] = {
            ["Camera"] = "47.310547,-89.34375,82.346375,0.000071,6.199694,-170.591293,35.000011,184.872482,false,Manual,8.0",
            ["Content"] = "我乃纯白之救赎，光之魔王大人！",
            ["ContentFR"] = "Je suis le Rédempteur Immaculé ☆ Roi Démon de la Lumière !",
            ["DialogueId"] = 20006511,
            ["FacialId"] = {
                [1] = "200002:Confident01",
                },
            ["FinalCamera"] = "33.654297,-91.604492,83.850006,0.000072,8.199676,-167.790817,35.000011,131.269821,false,Manual,8.0",
            ["GUID"] = "32158E36",
            ["NextDialogue"] = 20006512,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Confident_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200065/32158E36",
            },
        [20006512] = {
            ["Camera"] = "13.498047,83.051758,121.173889,0.000102,-0.000096,-173.797699,35.000008,145.105087,false,Manual,8.0",
            ["Content"] = "我……我乃魔灵猎人猎人，粮秣专员松露！以及粮秣特别专员，榛子！",
            ["ContentFR"] = "Je... je suis la Chasseuse de Chasseurs de Géniemon, Commissaire au Ravitaillement Truffle ! Et Filbert, Commissaire d’élite au Ravitaillement !",
            ["DialogueId"] = 20006512,
            ["FinalCamera"] = "2.105469,81.813477,121.173889,0.000102,-0.000096,-173.797699,35.000008,145.105087,false,Manual,8.0",
            ["GUID"] = "32158E60",
            ["NextDialogue"] = 20006513,
            ["Scripts"] = "PARA{\
CameraMoveTo{_delay{6.01},TargetPosition{\"150.591797,30.707031,123.61908,0.000102,-6.400208,141.202621,35.0,300.0,false,Manual,8.0\"},duration{0}},\
