            },
        [20006513] = {
            ["Camera"] = "150.591797,30.707031,123.61908,0.000102,-6.400208,141.202621,35.0,300.0,false,Manual,8.0",
            ["Content"] = "哼哼！",
            ["ContentFR"] = "<I>Groin, groin !</>",
            ["DialogueId"] = 20006513,
            ["FinalCamera"] = "134.871094,118.75,17.023186,0.000235,24.799322,157.617859,35.0,628.586243,false,Manual,12.0",
            ["GUID"] = "32158E8A",
            ["NextDialogue"] = 200065130,
            ["SpeakNpcId"] = 200086,
            ["ToFinalCameraBlendTime"] = 6,
            ["VoiceName"] = "voice/$Locale$/story/2001/200065/32158E8A",
            },
        [20006514] = {
            ["Camera"] = "292.925781,74.748047,369.465027,0.000041,-0.400365,-1.603272,35.000008,300.0,false,Manual,16.0",
            ["Content"] = "懂了，你们是盖雷亚剧院的演员。",
            ["ContentFR"] = "Je vois, vous êtes des comédiens du Théâtre Galea.",
            ["DialogueId"] = 20006514,
            ["GUID"] = "32158EB4",
            ["NextDialogue"] = 20006515,
            ["SpeakNpcId"] = 200075,
            ["TalkActionId"] = {
                [1] = "200075:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200065/32158EB4",
            },
        [20006515] = {
            ["Camera"] = "-26.337891,71.758789,115.010025,0.000102,5.001563,-179.000427,35.000019,100.535843,false,Manual,8.0",
            ["Content"] = "不……不是的！请你们放了这些魔灵！否则，我会让榛子撞飞你们！",
            ["ContentFR"] = "Non... pas du tout ! Relâchez ces Géniemon ! Sinon, Filbert va vous envoyer valser !",
            ["DialogueId"] = 20006515,
            ["GUID"] = "32158EDE",
            ["Scripts"] = "SEQ{\
PlayFacial{_delay{0.1},ActorId{200074},FacialId{\"Unacceptable01\"}},\
PlayFacial{_delay{0.6},ActorId{200074},FacialId{\"Smile02\"}}\
}",
            ["SpeakNpcId"] = 200074,
            ["TalkActionId"] = {
                [1] = "200074:Confident_End",
                [2] = "200074:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200065/32158EDE",
            },
        [20006516] = {
            ["Camera"] = "292.925781,74.748047,369.465027,0.000041,-0.400365,-1.603272,35.000008,300.0,false,Manual,8.0",
            ["Content"] = "刚刚在城外不就是你和这个什么光之魔头坏了我们的好事吗？",
            ["ContentFR"] = "Ce n’était pas vous, avec ce... Roi Démon de je-ne-sais-quoi, qui avez fichu en l’air nos plans hors de la cité ?",
            ["DialogueId"] = 20006516,
            ["GUID"] = "32158F08",
            ["NextDialogue"] = 20006517,
            ["SpeakNpcId"] = 200075,
            ["TalkActionId"] = {
                [1] = "200075:Angry01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200065/32158F08",
            },
        [20006517] = {
            ["Camera"] = "-27.242188,73.443359,154.929871,0.00007,-15.000351,-177.200226,35.000015,130.614029,false,Manual,8.0",
            ["Content"] = "是光之魔王大人，不好好记住别人的名字是很没有礼貌的行为，会被榛子撞飞的！",
            ["ContentFR"] = "C’est le Grand Roi Démon de la Lumière ! C’est malpoli de ne pas retenir un nom ! Filbert va te faire retenir la leçon !",
            ["DialogueId"] = 20006517,
            ["FacialId"] = {
                [1] = "200074:Confident02",
                },
            ["GUID"] = "32158F32",
            ["LookAt"] = {
                [1] = "200074:n(200075)",
                },
            ["SpeakNpcId"] = 200074,
            ["VoiceName"] = "voice/$Locale$/story/2001/200065/32158F32",
            },
        [20006518] = {
            ["Camera"] = "292.925781,74.748047,369.465027,0.000041,-0.400365,-1.603272,35.000008,300.0,false,Manual,8.0",
            ["Content"] = "白日做——梦！",
            ["ContentFR"] = "Dans tes rêves !",
            ["DialogueId"] = 20006518,
            ["GUID"] = "32158F5C",
            ["NextDialogue"] = 20006519,
            ["SpeakNpcId"] = 200075,
            ["TalkActionId"] = {
                [1] = "200075:Angry01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200065/32158F5C",
            },
        [20006519] = {
            ["Camera"] = "9.128906,71.000977,164.786407,0.000102,-18.198389,-178.600586,35.000008,450.0,false,Manual,6.0",
            ["Content"] = "如果是这样的话，那……榛子，撞飞他们！",
            ["ContentFR"] = "Si c’est comme ça... Filbert, fonce !",
            ["DialogueId"] = 20006519,
            ["FinalCamera"] = "-9.466797,68.333008,115.745117,0.000102,3.801383,-177.600464,35.000011,131.004227,false,Manual,6.0",
            ["GUID"] = "32158F86",
            ["LookAt"] = {
                [1] = "200074:n(200075)",
                },
            ["Scripts"] = "SEQ{\
PlayFacial{_delay{0.1},ActorId{200074},FacialId{\"Confident02\"}},\
PlayFacial{_delay{1.6},ActorId{200074},FacialId{\"Doubt01\"}}\
}",
            ["SpeakNpcId"] = 200074,
            ["TalkActionId"] = {
                [1] = "200074:Confident_End",
                [2] = "200074:Think_Start",
                },
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/2001/200065/32158F86",
            },
        [20006601] = {
            ["Content"] = "打就打，还怕你们几个半大孩子和一头畜生不成？",
            ["ContentFR"] = "Pff, et puis quoi encore ? Vous croyez que j’ai peur d’une bande de gamins et de leur tas de lard ambulant ?",
            ["DialogueId"] = 20006601,
            ["GUID"] = "32159CFA",
            ["NextDialogue"] = 20006602,
            ["SpeakNpcId"] = 200087,
            ["VoiceName"] = "voice/$Locale$/story/2001/200066/32159CFA",
            },
        [20006602] = {
            ["Content"] = "不可以这么骂榛子！向榛子道歉！",
            ["ContentFR"] = "On n’insulte pas Filbert comme ça ! Excuse-toi auprès d’elle, tout de suite !",
            ["DialogueId"] = 20006602,
            ["GUID"] = "32159D24",
            ["NextDialogue"] = 20006603,
            ["SpeakNpcId"] = 200074,
            ["VoiceName"] = "voice/$Locale$/story/2001/200066/32159D24",
            },
        [20006603] = {
            ["Content"] = "能打赢再说！",
            ["ContentFR"] = "Faut déjà réussir à me battre !",
            ["DialogueId"] = 20006603,
            ["GUID"] = "32159D4E",
            ["SpeakNpcId"] = 200087,
            ["VoiceName"] = "voice/$Locale$/story/2001/200066/32159D4E",
            },
        [20006604] = {
            ["Content"] = "咿咿呀——",
            ["ContentFR"] = "<I>Yiip— !</>",
            ["DialogueId"] = 20006604,
            ["GUID"] = "32159D78",
            ["NextDialogue"] = 20006605,
            ["SpeakNpcId"] = 700251,
            ["SpeakNpcName"] = "UI_Npc_Name_Pan_Common",
            ["VoiceName"] = "voice/$Locale$/story/2001/200066/32159D78",
            },
        [20006605] = {
            ["Content"] = "不好了老大，这个魔灵把其他魔灵都放出来了！",
            ["ContentFR"] = "P-Patron ! Ce Géniemon... il a libéré tous les autres !",
            ["DialogueId"] = 20006605,
            ["GUID"] = "32159DA2",
            ["NextDialogue"] = 20006606,
            ["SpeakNpcId"] = 200075,
            ["VoiceName"] = "voice/$Locale$/story/2001/200066/32159DA2",
            },
        [20006606] = {
            ["Content"] = "啾——",
            ["ContentFR"] = "Piou— !",
            ["DialogueId"] = 20006606,
            ["GUID"] = "32159DCC",
            ["NextDialogue"] = 20006607,
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["VoiceName"] = "voice/$Locale$/story/2001/200066/32159DCC",
            },
        [20006607] = {
            ["Content"] = "咩——",
            ["ContentFR"] = "Bêê— !",
            ["DialogueId"] = 20006607,
            ["GUID"] = "32159DF6",
            ["NextDialogue"] = 20006608,
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["VoiceName"] = "voice/$Locale$/story/2001/200066/32159DF6",
            },
        [20006608] = {
            ["Content"] = "叮咚——",
            ["ContentFR"] = "Ploc— !",
            ["DialogueId"] = 20006608,
            ["GUID"] = "32159E20",
            ["NextDialogue"] = 20006609,
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["VoiceName"] = "voice/$Locale$/story/2001/200066/32159E20",
            },
        [20006609] = {
            ["Content"] = "啊呀，好烫好烫——好麻——冷冷冷——",
            ["ContentFR"] = "Aïe, c’est brûlant ! Ouille ça pique ! J’ai froid, trop froid !",
            ["DialogueId"] = 20006609,
            ["GUID"] = "32159E4A",
            ["NextDialogue"] = 20006610,
            ["SpeakNpcId"] = 200087,
            ["VoiceName"] = "voice/$Locale$/story/2001/200066/32159E4A",
            },
        [20006610] = {
            ["Content"] = "我错了！我错了！",
            ["ContentFR"] = "Je me rends ! Pitié !",
            ["DialogueId"] = 20006610,
            ["GUID"] = "32159E74",
            ["SpeakNpcId"] = 200087,
            ["VoiceName"] = "voice/$Locale$/story/2001/200066/32159E74",
            },
        [20006701] = {
            ["Camera"] = "-939.216797,26.854492,320.087097,0.0,-13.407927,0.807412,35.000008,450.0,false,Manual,6.0",
            ["Content"] = "{nickname}大人，魔灵猎人猎人大人，还有光之魔王大人，我错了，我们错了。这些魔灵我们都不要了，饶了我们。",
            ["ContentFR"] = "{性别:Seigneur|Dame} {nickname}, ô Grande Chasseuse de Chasseurs de Géniemon, et Ô Grand Roi Démon de la Lumière, pardonnez-nous ! On a eu tort ! On renonce à tous ces Géniemon, épargnez-nous !",
            ["DialogueId"] = 20006701,
            ["GUID"] = "3215AD62",
            ["NextDialogue"] = 20006702,
            ["SpeakNpcId"] = 200087,
            ["TalkActionId"] = {
                [1] = "200075:Avoid",
                [2] = "200087:Avoid",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200067/3215AD62",
            },
        [20006702] = {
            ["Content"] = "诶？不用这么害怕，只要你们保证以后不再乱捉魔灵，我和榛子就不会把你们怎么样的。",
            ["ContentFR"] = "Hé, pas besoin d’être aussi paniqués. Si vous promettez de ne plus jamais attraper de Géniemon, Filbert et moi ne vous ferons rien.",
            ["DialogueId"] = 20006702,
            ["GUID"] = "3215AD8C",
            ["NextDialogue"] = 20006703,
            ["SpeakNpcId"] = 200074,
            ["VoiceName"] = "voice/$Locale$/story/2001/200067/3215AD8C",
            },
        [20006703] = {
            ["Content"] = "一定，一定。",
            ["ContentFR"] = "Oui, oui, promis !",
            ["DialogueId"] = 20006703,
            ["GUID"] = "3215ADB6",
            ["NextDialogue"] = 20006704,
            ["SpeakNpcId"] = 200075,
            ["VoiceName"] = "voice/$Locale$/story/2001/200067/3215ADB6",
            },
        [20006704] = {
            ["Content"] = "我也一定不捉魔灵了！也监督老大，要是老大又开始抓魔灵，我第一个告诉你们！",
            ["ContentFR"] = "Moi aussi, je promets de ne plus attraper de Géniemon ! Et je surveillerai le patron, si jamais il recommence, je vous le dirai en premier !",
            ["DialogueId"] = 20006704,
            ["GUID"] = "3215ADE0",
            ["NextDialogue"] = 20006705,
            ["SpeakNpcId"] = 200087,
            ["VoiceName"] = "voice/$Locale$/story/2001/200067/3215ADE0",
            },
        [20006705] = {
            ["Content"] = "好，那么你们也需要向它们道歉。",
            ["ContentFR"] = "Bien. Alors vous devez aussi aller leur présenter des excuses.",
            ["DialogueId"] = 20006705,
            ["GUID"] = "3215AE0A",
            ["NextDialogue"] = 20006706,
            ["SpeakNpcId"] = 200074,
            ["VoiceName"] = "voice/$Locale$/story/2001/200067/3215AE0A",
            },
        [20006706] = {
            ["Content"] = "非常抱歉！是我利欲熏心，本来想要研究魔灵，却怎么都写不出论文，所以动起了歪心思……你们来捕猎我吧，让我这个魔灵猎人体验魔灵猎人……",
            ["ContentFR"] = "Je suis profondément désolé ! L’avidité m’a aveuglé... Je voulais étudier les Géniemon, mais je n’arrivais pas à rédiger de thèse, alors j’ai pris le mauvais chemin... Allez-y ! Vengez-vous ! Chassez-moi comme je vous ai chassés...",
            ["DialogueId"] = 20006706,
            ["GUID"] = "3215AE34",
            ["NextDialogue"] = 20006708,
            ["SpeakNpcId"] = 200075,
            ["VoiceName"] = "voice/$Locale$/story/2001/200067/3215AE34",
            },
        [20006707] = {
            ["Content"] = "我实在是不聪明，居然质疑潘神大人的智力，潘神大人比我还要聪明……比老大还要聪明！今天开始我称呼你为老大……",
            ["ContentFR"] = "J’ai été idiot d’avoir douté de la sagesse du Seigneur Paniemon. Le Seigneur Paniemon est plus intelligent que moi... même plus que mon patron ! Dès aujourd’hui, je jure allégeance à vous, Seigneur Paniemon !",
            ["DialogueId"] = 20006707,
            ["GUID"] = "3215AE5E",
            ["SpeakNpcId"] = 200087,
            ["VoiceName"] = "voice/$Locale$/story/2001/200067/3215AE5E",
            },
        [20006708] = {
            ["Content"] = "咿咿。",
            ["ContentFR"] = "<I>Yiip !</>",
            ["DialogueId"] = 20006708,
            ["GUID"] = "3215AE88",
            ["NextDialogue"] = 20006709,
            ["SpeakNpcId"] = 700251,
            ["SpeakNpcName"] = "UI_Npc_Name_Pan_Common",
            ["VoiceName"] = "voice/$Locale$/story/2001/200067/3215AE88",
            },
        [20006709] = {
            ["Camera"] = "35.800781,50.916992,117.894058,0.000003,-4.407924,143.206772,35.000011,450.0,false,Manual,6.0",
            ["Content"] = "唔，看你们这么诚恳，姑且相信你们吧。那么，接下来，{nickname}，小白，我们得想办法安置这些魔灵。",
            ["ContentFR"] = "Hum... vous avez l’air sincères, on va vous croire pour l’instant. Alors, {性别:Monsieur|Mademoiselle}, Snow, que fait-on de tous ces Géniemon ?",
            ["DialogueId"] = 20006709,
            ["FinalCamera"] = "140.537109,-26.151367,129.112198,0.000003,-5.407959,144.206726,35.000011,450.0,false,Manual,6.0",
            ["GUID"] = "3215AEB2",
            ["NextDialogue"] = 20006710,
            ["SpeakNpcId"] = 200074,
            ["TalkActionId"] = {
                [1] = "200074:Confident_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200067/3215AEB2",
            },
        [20006710] = {
            ["Camera"] = "-101.119141,154.260742,108.99675,0.000025,3.592208,132.807907,35.000015,110.824821,false,Manual,6.0",
            ["Content"] = "这么多魔灵，应该没法带出冰湖城，直接放生的话，它们也会因为附近没有月石这样的能量来源陷入困境……",
            ["ContentFR"] = "Ils sont bien trop nombreux pour les faire sortir discrètement de Givrelac. Et si on les relâche ici, ils ne trouveront pas assez de Phoxène pour survivre...",
            ["DialogueId"] = 20006710,
            ["FacialId"] = {
                [1] = "200074:Unhappy01",
                },
            ["GUID"] = "3215AEDC",
            ["NextDialogue"] = 20006711,
            ["SpeakNpcId"] = 200074,
            ["TalkActionId"] = {
                [1] = "200074:Confident_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200067/3215AEDC",
            },
        [20006711] = {
            ["Camera"] = "6.857422,-38.206055,107.53566,0.000019,-3.007906,-59.192425,35.000015,161.420593,false,Manual,6.0",
            ["Content"] = "怎么会这样……也就是说尽管我们救了它们，但还是不能确保它们一定都能活下来是吗？",
            ["ContentFR"] = "Comment ça... ? Tu veux dire que, même en les sauvant, on ne peut pas garantir qu’ils s’en tireront tous ?",
            ["DialogueId"] = 20006711,
            ["FacialId"] = {
                [1] = "200002:Unacceptable01",
                },
            ["FinalCamera"] = "6.857422,-38.206055,107.53566,0.000019,-3.007906,-59.192459,35.000011,450.0,false,Manual,6.0",
            ["GUID"] = "3215AF06",
            ["NextDialogue"] = 20006712,
            ["SpeakNpcId"] = 200002,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200067/3215AF06",
            },
        [20006712] = {
            ["Camera"] = "-64.103516,31.655273,119.67865,0.000029,-4.808036,119.607536,35.000011,450.0,false,Manual,6.0",
            ["Content"] = "是的，除非有足够多的月石……可是这么多的魔灵，除非冰湖城每户人家都拿出一块月石来……可是一般人都很害怕魔灵的，肯定不愿意这么做……",
            ["ContentFR"] = "Oui. Sauf si on a suffisamment de Phoxène... mais pour en avoir assez pour tous, il faudrait qu’un fragment de Phoxène provienne de chaque foyer de Givrelac... or la plupart des gens ont peur des Géniemon. Ils ne voudront jamais aider.",
            ["DialogueId"] = 20006712,
            ["FinalCamera"] = "14.46875,-50.96875,106.754761,0.000019,-3.007906,-59.192356,35.000015,134.451996,false,Manual,6.0",
            ["GUID"] = "3215AF30",
            ["NextDialogue"] = 20006713,
            ["SpeakNpcId"] = 200074,
            ["TalkActionId"] = {
                [1] = "200074:Think_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200067/3215AF30",
            },
        [20006713] = {
            ["Camera"] = "-108.800781,-45.291992,165.959991,0.000029,-12.807772,59.206985,35.000008,450.0,false,Manual,6.0",
            ["Content"] = "哼哼……",
            ["ContentFR"] = "<I>Groin groin...</>",
            ["DialogueId"] = 20006713,
            ["GUID"] = "3215AF5A",
            ["NextDialogue"] = 20006714,
            ["SpeakNpcId"] = 200086,
            ["VoiceName"] = "voice/$Locale$/story/2001/200067/3215AF5A",
            },
        [20006714] = {
            ["Camera"] = "-112.921875,-23.537109,160.274353,0.000064,1.1921,-114.590996,35.000011,159.3237,false,Manual,6.0",
            ["Content"] = "嗯……得想想办法……",
            ["ContentFR"] = "Hmm... il va falloir trouver une solution...",
            ["DialogueId"] = 20006714,
            ["FacialId"] = {
                [1] = "100001:Think01",
                },
            ["FinalCamera"] = "-122.841797,-45.224609,160.77063,0.000065,2.392089,-114.590553,35.000011,142.061966,false,Manual,6.0",
            ["GUID"] = "3215AF84",
            ["NextDialogue"] = 20006715,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Think_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200067/3215AF84",
            },
        [20006715] = {
            ["Camera"] = "-20.984375,-89.079102,120.151733,0.000088,-7.208342,-37.78812,35.000015,123.723419,false,Manual,6.0",
            ["Content"] = "虽然我还没有亲眼见到，但是一想到这件事可能是真的，就觉得非常可怕！",
            ["ContentFR"] = "Je n’ai pas encore vu tout ça de mes propres yeux, et rien que d’y penser, ça me donne des frissons...",
            ["DialogueId"] = 20006715,
            ["FacialId"] = {
                [1] = "200002:Shock02",
                },
            ["FinalCamera"] = "-40.863281,-87.678711,84.628616,0.000085,7.591741,-32.988117,35.000015,161.950012,false,Manual,6.0",
            ["GUID"] = "3215AFAE",
            ["NextDialogue"] = 20006716,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:ScratchHead_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200067/3215AFAE",
            },
        [20006716] = {
            ["Camera"] = "-92.931641,513.984375,128.895233,0.000055,-1.407743,-97.792145,35.000008,450.0,false,Manual,6.0",
            ["Content"] = "松露，在你的家乡，大家会害怕榛子吗？",
            ["ContentFR"] = "Truffle, dans ton village, les gens avaient peur de Filbert ?",
            ["DialogueId"] = 20006716,
            ["GUID"] = "3215AFD8",
            ["LookAt"] = {
                [1] = "100001:n(200074)",
                },
            ["NextDialogue"] = 20006717,
            ["Scripts"] = "SEQ{\
PlayAnimation{_delay{0.1},ActorId{100001},AnimationId{\"Think_End\"}},\
PARA{\
PlayFacial{_delay{0.5},ActorId{100001},FacialId{\"Confident01\"}},\
PlayAnimation{_delay{2.1},ActorId{100001},AnimationId{\"Talk02_Start\"}}\
}\
}",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/2001/200067/3215AFD8",
            },
        [20006717] = {
            ["Camera"] = "-130.119141,-252.262695,186.619904,0.00007,-10.007689,106.210793,35.000011,450.0,false,Manual,6.0",
            ["Content"] = "嗯？实话说，一开始大家没看过这么大的猪，都会有点害怕的。但是一旦知道榛子能够和我一起找到很多食物，非常能干，就不害怕了。",
            ["ContentFR"] = "Hein ? Au début, oui. Personne n’avait jamais vu un cochon si énorme, ça fait peur. Mais quand ils ont vu que Filbert m’aidait à trouver de la nourriture, qu’elle était intelligente et débrouillarde, ils n’ont plus eu peur.",
            ["DialogueId"] = 20006717,
            ["FacialId"] = {
                [1] = "200074:Smile01",
                },
            ["GUID"] = "3215B002",
            ["LookAt"] = {
                [1] = "200074:n(100001)",
                },
            ["NextDialogue"] = 20006718,
            ["SpeakNpcId"] = 200074,
            ["TalkActionId"] = {
                [1] = "100001:Talk02_End",
                [2] = "200074:Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200067/3215B002",
            },
        [20006718] = {
            ["Camera"] = "-143.039062,97.484375,110.879364,0.000087,0.791714,106.205078,35.000015,140.05127,false,Manual,6.0",
            ["Content"] = "是的，觉得害怕是因为不够了解，如果让大家了解魔灵的能力，获得魔灵的帮助，就一定不会害怕了。",
            ["ContentFR"] = "Exactement. La peur vient de l’ignorance. Si les gens voient ce que peuvent faire les Géniemon et qu’ils reçoivent leur aide, la peur finira par disparaître.",
            ["DialogueId"] = 20006718,
            ["FacialId"] = {
                [1] = "100001:Smile01",
                },
            ["FinalCamera"] = "-146.861328,105.399414,111.090088,0.000087,1.391712,107.405457,35.000015,140.05127,false,Manual,6.0",
            ["GUID"] = "3215B02C",
            ["NextDialogue"] = 20006719,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Explain02_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200067/3215B02C",
            },
        [20006719] = {
            ["Content"] = "松露，白，我们一起把这些魔灵带到水仙平原去。",
            ["ContentFR"] = "Truffle, Snow, on va les emmener aux Asphodèles.",
            ["DialogueId"] = 20006719,
            ["GUID"] = "3215B056",
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200067/3215B056",
            },
        [20006720] = {
            ["Camera"] = "390.472656,-23.833008,76.522202,0.000054,0.592102,149.805954,35.000011,450.0,false,Manual,6.0",
            ["Content"] = "好的，榛子坐下，我们把魔灵放到你的背上，一口气都带出去。",
            ["ContentFR"] = "D’accord ! Filbert, assieds-toi. On va charger les Géniemon sur ton dos et tous les emmener d’un seul coup !",
            ["DialogueId"] = 20006720,
            ["FinalCamera"] = "290.703125,34.223633,80.627289,0.000054,2.592091,149.805908,35.000011,450.0,false,Manual,6.0",
            ["GUID"] = "3215B080",
            ["LookAt"] = {
                [1] = "200074:n(200086)",
                },
            ["NextDialogue"] = 20006721,
            ["SpeakNpcId"] = 200074,
            ["TalkActionId"] = {
                [1] = "200074:Talk02_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200067/3215B080",
            },
        [20006721] = {
            ["Content"] = "嗯？又要找卡米拉吗？她呀，肯定又要嘴上说着不愿意，然后和你一起想办法了。",
            ["ContentFR"] = "Hein ? Encore Camilla ? Elle fera sa tête de mule et dira non... puis elle finira par trouver la solution parfaite, comme d’habitude.",
            ["DialogueId"] = 20006721,
            ["FacialId"] = {
                [1] = "200002:Confident02",
                },
            ["GUID"] = "3215B0AA",
            ["NextDialogue"] = 20006722,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Confident_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200067/3215B0AA",
            },
        [20006722] = {
            ["Content"] = "我也来帮忙！",
            ["ContentFR"] = "Je viens aussi !",
            ["DialogueId"] = 20006722,
            ["GUID"] = "3215B0D4",
            ["NextDialogue"] = 20006723,
            ["SpeakNpcId"] = 200087,
            ["VoiceName"] = "voice/$Locale$/story/2001/200067/3215B0D4",
            },
        [20006723] = {
            ["Content"] = "还有我，还有我。",
            ["ContentFR"] = "Moi aussi, moi aussi !",
            ["DialogueId"] = 20006723,
            ["GUID"] = "3215B0FE",
            ["NextDialogue"] = 20006724,
            ["SpeakNpcId"] = 200075,
            ["VoiceName"] = "voice/$Locale$/story/2001/200067/3215B0FE",
            },
        [20006724] = {
            ["Camera"] = "25.234375,43.664062,76.073486,0.000057,-10.207888,-1.19403,35.000011,450.0,false,Manual,6.0",
            ["Content"] = "咿咿。",
            ["ContentFR"] = "<I>Yiip !</>",
            ["DialogueId"] = 20006724,
            ["FinalCamera"] = "-37.855469,44.204102,84.949371,0.000057,-8.007871,-0.194,35.000011,450.0,false,Manual,6.0",
            ["GUID"] = "3215B128",
            ["NextDialogue"] = 20006725,
            ["SpeakNpcId"] = 700251,
            ["SpeakNpcName"] = "UI_Npc_Name_Pan_Common",
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200067/3215B128",
            },
        [20006725] = {
            ["Camera"] = "447.40625,104.102539,80.368851,0.000072,-1.207823,-159.593887,35.000011,450.0,false,Manual,6.0",
            ["Content"] = "嗯？你不一起跟着来吗？",
            ["ContentFR"] = "Hein ? Tu ne viens pas avec nous ?",
            ["DialogueId"] = 20006725,
            ["FinalCamera"] = "483.496094,102.482422,81.651184,0.000072,-3.00781,-160.39386,35.000011,450.0,false,Manual,6.0",
            ["GUID"] = "3215B152",
            ["LookAt"] = {
                [1] = "100001:n(700251)",
                },
            ["NextDialogue"] = 20006726,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Talk02_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200067/3215B152",
            },
        [20006726] = {
            ["Camera"] = "45.181641,44.441406,28.436035,0.000076,6.992051,-0.794525,35.000011,450.0,false,Manual,6.0",
            ["Content"] = "魔灵潘神一般都会和人尽可能保持距离，看起来刚刚它只是想靠你们把其他魔灵救出来。",
            ["ContentFR"] = "Le Seigneur Paniemon a l’habitude de garder ses distances avec les gens. Il est probablement venu juste pour que vous aidiez à libérer les autres Géniemon.",
            ["DialogueId"] = 20006726,
            ["FinalCamera"] = "-94.589844,48.933594,37.514648,0.000076,0.791967,-1.194519,35.000011,450.0,false,Manual,6.0",
            ["GUID"] = "3215B17C",
            ["NextDialogue"] = 20006727,
            ["SpeakNpcId"] = 200075,
            ["TalkActionId"] = {
                [1] = "100001:Talk02_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200067/3215B17C",
            },
        [20006727] = {
            ["Camera"] = "-76.480469,-72.768555,129.284988,0.000097,13.191738,-135.390411,35.000015,137.250519,false,Manual,6.0",
            ["Content"] = "好，那你也要小心。",
            ["ContentFR"] = "D’accord. Alors prends soin de toi, Paniemon.",
            ["DialogueId"] = 20006727,
            ["FinalCamera"] = "-99.601562,-95.574219,136.62146,0.000099,15.191671,-135.990753,35.000015,105.456551,false,Manual,6.0",
            ["GUID"] = "3215B1A6",
            ["NextDialogue"] = 20006728,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:AgreeHead",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200067/3215B1A6",
            },
        [20006728] = {
            ["Camera"] = "-854.189453,515.839844,461.855774,0.000065,-20.40831,-29.192192,35.000011,450.0,false,Manual,6.0",
            ["Content"] = "咿咿咿。",
            ["ContentFR"] = "<I>Yiiip !</>",
            ["DialogueId"] = 20006728,
            ["FinalCamera"] = "-854.189453,515.839844,461.855774,0.000065,-20.40831,-29.192192,35.000011,450.0,false,Manual,6.0",
            ["GUID"] = "3215B1D0",
            ["SpeakNpcId"] = 700251,
            ["SpeakNpcName"] = "UI_Npc_Name_Pan_Common",
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200067/3215B1D0",
            },
        [20006801] = {
            ["Content"] = "最终，这些魔灵被一起带到了水仙平原，吓跑了一屋子的客人，并成功让卡米拉眉头紧锁，开始思考当初是不是不应该带{nickname}进城。",
            ["ContentFR"] = "Finalement, les Géniemon furent conduits jusqu’aux Asphodèles, les clients de la taverne prirent la fuite, renversant chaises et verres dans la précipitation. Camilla fronça les sourcils et se demanda si laisser {nickname} entrer en ville n’avait pas été une énorme erreur.",
            ["DialogueId"] = 20006801,
            ["Duration"] = 5,
            ["GUID"] = "3215BDCA",
            ["VoiceName"] = "voice/$Locale$/story/2001/200068/3215BDCA",
            },
        [20006901] = {
            ["Content"] = "又过了一段时间，卡米拉的眉头终于缓缓舒展开来……",
            ["ContentFR"] = "Puis, au fil des jours, le froncement de sourcils de Camilla finit par s’adoucir...",
            ["DialogueId"] = 20006901,
            ["Duration"] = 3,
            ["GUID"] = "3215CE32",
            ["VoiceName"] = "voice/$Locale$/story/2001/200069/3215CE32",
            },
        [20006902] = {
            ["Camera"] = "-77.774261,-546.844727,210.810547,-0.000763,-8.992114,80.412018,35.0,369.08606,false,Manual,12.0",
            ["Content"] = "哟，卡米拉，给我来一杯“打火鸡特调”，这么冷的天来上一口，再合适不过了。",
            ["ContentFR"] = "Eh bien, Camilla, sers-moi un Spécial Piquero. Par ce froid, un petit remontant chauffé par de vraies flammes, c’est ce qu’il nous faut.",
            ["DialogueId"] = 20006902,
            ["GUID"] = "3215CE5C",
            ["LookAt"] = {
                [1] = "700253:n(700248)",
                [2] = "700254:n(700253)",
                },
            ["NextDialogue"] = 20006903,
            ["Scripts"] = "PARA{\
PlayFacial{_delay{3.5},ActorId{700248},FacialId{\"Confident01\"}},\
PlayAnimation{_delay{3.1},ActorId{700248},AnimationId{\"Talk03_Start\"}}\
}",
            ["SpeakNpcId"] = 700253,
            ["VoiceName"] = "voice/$Locale$/story/2001/200069/3215CE5C",
            },
        [20006903] = {
            ["Content"] = "一开始我觉得这小东西很邪门，没想到喷出的火焰拿来温酒，绝了！",
            ["ContentFR"] = "Au début, je pensais que cette petite chose était maléfique... mais sa flamme est parfaite pour chauffer une bonne boisson, c’est génial !",
            ["DialogueId"] = 20006903,
            ["GUID"] = "3215CE86",
            ["LookAt"] = {
                [1] = "700253:n(700253)",
                },
            ["NextDialogue"] = 20006904,
            ["SpeakNpcId"] = 700253,
            ["TalkActionId"] = {
                [1] = "700253:Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200069/3215CE86",
            },
        [20006904] = {
            ["Camera"] = "-270.673706,295.446289,221.228516,-0.000763,-10.792361,-56.385796,35.000008,369.08606,false,Manual,12.0",
            ["Content"] = "可悲啊，威尔斯先生，可叹啊，威尔斯先生。",
            ["ContentFR"] = "Triste sort, Wells, ô triste sort, Wells.",
            ["DialogueId"] = 20006904,
            ["GUID"] = "3215CEB0",
            ["NextDialogue"] = 20006905,
            ["SpeakNpcId"] = 700254,
            ["TalkActionId"] = {
                [1] = "700254:Sigh_Start",
                [2] = "700253:Talk01_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200069/3215CEB0",
            },
        [20006905] = {
            ["Camera"] = "-37.503937,-47.555664,133.710938,-0.000763,-2.992312,-78.38279,35.000008,369.08606,false,Manual,12.0",
            ["Content"] = "你只知道打火鸡的火焰可以让酒水温热，暖及肚肠，却不知道它真正的价值，在于划破黑暗，在黑夜中为我点亮书本，带来灵感！",
            ["ContentFR"] = "Toi qui vois seulement que le feu du Piquero réchauffe la boisson et réconforte le ventre, tu ignores sa vraie valeur : il fend l’obscurité, éclaire mes écrits la nuit et m’inspire !",
            ["DialogueId"] = 20006905,
            ["GUID"] = "3215CEDA",
            ["NextDialogue"] = 20006906,
            ["SpeakNpcId"] = 700254,
            ["TalkActionId"] = {
                [1] = "700254:Sigh_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200069/3215CEDA",
            },
        [20006906] = {
            ["Camera"] = "-89.716675,175.708008,152.642578,-0.000763,-3.992218,-88.380859,35.000008,369.08606,false,Manual,12.0",
            ["Content"] = "打，火，鸡。多么美妙的三个字，我的写作生命之光，我的创作欲念之火！我的罪恶，我的灵魂！",
            ["ContentFR"] = "Pi-que-ro. Trois syllabes sublimes : la lumière de ma plume, l’ardeur de ma création ! Mon péché, mon salut !",
            ["DialogueId"] = 20006906,
            ["GUID"] = "3215CF04",
            ["SpeakNpcId"] = 700254,
            ["TalkActionId"] = {
                [1] = "700254:Angry01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200069/3215CF04",
            },
        [20007001] = {
            ["Camera"] = "410.60437,303.494141,154.748047,0.000089,0.396813,37.710804,35.0,369.08606,false,Manual,12.0",
            ["Content"] = "有人用雨衣水滴浇花，有人用好梦先生助眠……就连我的生意，也离不开一只打火鸡。",
            ["ContentFR"] = "Certains arrosent leurs fleurs avec des Gouttines, d’autres s’endorment grâce à M. Bonne Nuit... et maintenant, même mon commerce dépend d’un Piquero.",
            ["DialogueId"] = 20007001,
            ["FinalCamera"] = "262.071167,223.890625,147.691406,0.000094,-1.403686,36.110554,35.000011,369.08606,false,Manual,12.0",
            ["GUID"] = "3215DE9A",
            ["NextDialogue"] = 20007002,
            ["Scripts"] = "PARA{\
SEQ{\
TurnTo{_delay{2},TurnToDescription{\"700248:p(180)\"}},\
PlayAnimation{_delay{0.5},ActorId{700248},AnimationId{\"Confident_Start\"},Duration{1}}\
},\
PlayFacial{_delay{0.5},ActorId{700248},FacialId{\"Smile01\"}}\
}",
            ["SpeakNpcId"] = 700248,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200070/3215DE9A",
            },
        [20007002] = {
            ["Content"] = "现在根本不会有人想要从魔灵身上提炼月石，反而会为了和魔灵更加亲近，专门买月石去喂养它们，挺有趣的。",
            ["ContentFR"] = "C’est drôle comme les choses changent. Hier encore, on parlait d’extraire le Phoxène des Géniemon, et maintenant, les gens en achètent exprès pour les nourrir et mieux s’en faire des amis.",
            ["DialogueId"] = 20007002,
            ["GUID"] = "3215DEC4",
            ["LookAt"] = {
                [1] = "100001:n(200074)",
                [2] = "200002:n(200074)",
                },
            ["NextDialogue"] = 20007003,
            ["Scripts"] = "SEQ{\
PlayAnimation{_delay{1},ActorId{700248},AnimationId{\"Confident_End\"},Duration{1}},\
PARA{\
PlayAnimation{_delay{1.5},ActorId{700248},AnimationId{\"Talk02_Start\"},Duration{1}},\
PlayFacial{_delay{7.5},ActorId{700248},FacialId{\"Smile02\"}}\
},\
PlayFacial{_delay{1.0},ActorId{700248},FacialId{\"None\"}}\
}",
            ["SpeakNpcId"] = 700248,
            ["VoiceName"] = "voice/$Locale$/story/2001/200070/3215DEC4",
            },
        [20007003] = {
            ["Camera"] = "855.156494,437.582031,235.363281,-0.000335,-12.202781,-167.746658,35.000008,369.08606,false,Manual,12.0",
            ["Content"] = "这也是看到松露和榛子才想到的。既然榛子能和人类友好相处，那么魔灵也能。",
            ["ContentFR"] = "C’est grâce à Truffle et Filbert. Si Filbert sait vivre avec les humains, les Géniemon aussi le peuvent.",
            ["DialogueId"] = 20007003,
            ["GUID"] = "3215DEEE",
            ["LookAt"] = {
                [1] = "200074:n(100001)",
                },
            ["NextDialogue"] = 20007004,
            ["Scripts"] = "SEQ{\
PlayAnimation{_delay{1},ActorId{700248},AnimationId{\"Talk02_End\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200070/3215DEEE",
            },
        [20007004] = {
            ["Camera"] = "385.531738,327.31543,122.824219,-0.000336,8.596824,174.251282,35.0,169.08606,false,Manual,12.0",
            ["Content"] = "而如果魔灵都能和人类友好相处，那么卡戎和索拉之民，迟早有一天也会相处融洽的。",
            ["ContentFR"] = "Et si les Géniemon peuvent coexister avec nous, peut-être qu’un jour Charons et Solariens trouveront aussi un terrain d’entente.",
            ["DialogueId"] = 20007004,
            ["GUID"] = "3215DF18",
            ["NextDialogue"] = 20007005,
            ["Scripts"] = "PlayFacial{_delay{0.5},ActorId{700248},FacialId{\"Smile01\"}}",
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200070/3215DF18",
            },
        [20007005] = {
            ["Camera"] = "271.747681,244.423828,145.421875,0.000091,0.396629,32.112232,35.0,369.08606,false,Manual,12.0",
            ["Content"] = "哈哈，我都不好说你是天真，还是看得足够远，让我好好期待那一天的到来吧。但在那之前，该送别那一位小朋友了。",
            ["ContentFR"] = "Haha, je ne sais pas si tu es {性别:naïf|naïve} ou simplement {性别:porteur|porteuse} d’une grande vision. En tout cas, j’attends ce jour avec curiosité. Mais pour l’instant... il est temps de dire au revoir à cette petite voyageuse.",
            ["DialogueId"] = 20007005,
            ["FinalCamera"] = "134.401306,153.286133,129.798828,-0.000336,-0.203833,31.850718,35.000008,369.08606,false,Manual,12.0",
            ["GUID"] = "3215DF42",
            ["NextDialogue"] = 20007006,
            ["Scripts"] = "SEQ{\
PlayAnimation{_delay{0.5},ActorId{700248},AnimationId{\"Sigh_Start\"},Duration{2}},\
PlayAnimation{_delay{0.5},ActorId{700248},AnimationId{\"Sigh_End\"},Duration{1}}}",
            ["SpeakNpcId"] = 700248,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200070/3215DF42",
            },
        [20007006] = {
            ["Camera"] = "721.993774,408.491211,205.130859,0.00002,-14.403127,-165.088608,35.0,369.08606,false,Manual,12.0",
            ["Content"] = "呜呜呜，松露，你就不能留在冰湖城吗？光之魔王大人好不容易找到一个伙伴愿意和我一起大声念出自己的称号！",
            ["ContentFR"] = "<I>Ouinnn...</> Truffle, tu ne peux pas rester à Givrelac ? Le Roi Démon de la Lumière a enfin trouvé quelqu’un pour scander ses titres ensemble !",
            ["DialogueId"] = 20007006,
            ["FacialId"] = {
                [1] = "200002:Sad01",
                },
            ["GUID"] = "3215DF6C",
            ["NextDialogue"] = 20007007,
            ["SpeakNpcId"] = 200002,
            ["TurnTo"] = {
                [1] = "200074:p(30)",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200070/3215DF6C",
            },
        [20007007] = {
            ["Content"] = "别哭呀小白，我已经出门很久啦，该回去了。再说了，那几个魔灵猎人都改行变成魔灵学者了，你可以让他们和你一起念称号呀。",
            ["ContentFR"] = "Ne pleure pas, Snow. Ça fait longtemps que je suis partie à l’aventure, il est temps de rentrer. Puis ces anciens chasseurs se sont reconvertis en chercheurs sur les Géniemon, tu peux leur demander de chanter tes titres avec toi.",
            ["DialogueId"] = 20007007,
            ["GUID"] = "3215DF96",
            ["NextDialogue"] = 20007008,
            ["SpeakNpcId"] = 200074,
            ["VoiceName"] = "voice/$Locale$/story/2001/200070/3215DF96",
            },
        [20007008] = {
            ["Camera"] = "428.352539,486.96582,156.205078,0.000078,-8.003704,-124.08696,35.0,369.08606,false,Manual,12.0",
            ["Content"] = "不，他们说话没有你说话好听，也不能和你一样让榛子背着我兜风。{nickname}你也别傻站着，留一留松露呀。",
            ["ContentFR"] = "Non, ils n’ont pas ta voix, et ils ne peuvent pas me faire faire un tour sur Filbert comme toi. {nickname}, bouge-toi et aide-moi à convaincre Truffle de rester !",
            ["DialogueId"] = 20007008,
            ["FacialId"] = {
                [1] = "200002:Unhappy01",
                },
            ["GUID"] = "3215DFC0",
            ["NextOptions"] = {
                [1] = 200070081,
                },
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "700248:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200070/3215DFC0",
            },
        [20007009] = {
            ["Camera"] = "322.5,503.43457,157.886719,0.000066,-8.003506,-99.487526,35.000008,369.08606,false,Manual,12.0",
            ["Content"] = "嘿嘿，以后我也会时不时来玩的。{性别：大哥哥|大姐姐}，悄悄告诉你哦，我要回去的那个很远很远的地方，其实是艾利西安传颂会。",
            ["ContentFR"] = "Héhé, je reviendrai de temps en temps, promis. Et laisse-moi te dire un petit secret, l’endroit lointain où je retourne, c’est en fait l’Église Élyséenne.",
            ["DialogueId"] = 20007009,
            ["FacialId"] = {
                [1] = "200002:CM_Idle",
                },
            ["FinalCamera"] = "316.476074,471.517578,153.757812,0.000067,-8.603483,-101.087669,35.000008,369.08606,false,Manual,12.0",
            ["GUID"] = "3215DFEA",
            ["LookAt"] = {
                [1] = "200074:n(100001)",
                },
            ["NextDialogue"] = 20007010,
            ["SpeakNpcId"] = 200074,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200070/3215DFEA",
            },
        [20007010] = {
            ["Camera"] = "-189.593018,180.383789,233.115234,0.000085,-10.602577,9.713165,35.0,369.08606,false,Manual,12.0",
            ["Content"] = "我收集食物时，偶尔会和榛子一起越过那些没有人看守的高山，到海伯利亚来。一开始我还有点害怕，因为传颂会和帝国一直在打仗嘛。",
            ["ContentFR"] = "Quand Filbert et moi cherchons de la nourriture, on traverse parfois, par des montagnes non gardées pour atteindre l’Hyperborea. Au début, j'avais un peu peur, après tout, l’Église et l’Empire ont toujours été en guerre...",
            ["DialogueId"] = 20007010,
            ["GUID"] = "3215E014",
            ["NextDialogue"] = 20007011,
            ["SpeakNpcId"] = 200074,
            ["VoiceName"] = "voice/$Locale$/story/2001/200070/3215E014",
            },
        [20007011] = {
            ["Content"] = "但是遇到了{性别：大哥哥|大姐姐}后，我就不害怕了。",
            ["ContentFR"] = "Mais après vous avoir rencontré, je n’ai plus peur.",
            ["DialogueId"] = 20007011,
            ["GUID"] = "3215E03E",
            ["NextDialogue"] = 20007012,
            ["SpeakNpcId"] = 200074,
            ["TalkActionId"] = {
                [1] = "200074:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200070/3215E03E",
            },
        [20007012] = {
            ["Content"] = "{性别：大哥哥|大姐姐}能够想出办法让魔灵和人类相处，那么就一定能让卡戎和索拉不再互相讨厌，帝国和传颂会也能不再打仗。",
            ["ContentFR"] = "Parce que si tu peux trouver un moyen pour que les Géniemon et les humains vivent ensemble en amis, alors je crois qu’un jour, tu sauras aussi rapprocher les Charons et les Solariens, et peut-être même faire en sorte que l’Empire et l’Église cessent enfin de se battre.",
            ["DialogueId"] = 20007012,
            ["GUID"] = "3215E068",
            ["NextDialogue"] = 20007013,
            ["SpeakNpcId"] = 200074,
            ["TalkActionId"] = {
                [1] = "200074:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200070/3215E068",
            },
        [20007013] = {
            ["Content"] = "这样一来，大家就都不会饿肚子了！",
            ["ContentFR"] = "Comme ça, plus personne n’aura faim !",
            ["DialogueId"] = 20007013,
            ["GUID"] = "3215E092",
            ["NextDialogue"] = 20007014,
            ["SpeakNpcId"] = 200074,
            ["VoiceName"] = "voice/$Locale$/story/2001/200070/3215E092",
            },
        [20007014] = {
            ["Content"] = "到那时候，也请你和小白，还有卡米拉女士，一起到南方。吃粉嘟嘟的红蕈、吹烫烫的海风、看这里看不到的星星，和我在这里一样开心！等着你哦！",
            ["ContentFR"] = "Et quand ce jour viendra, viens me voir au sud avec Snow et Madame Camilla. On mangera des Chapeaux-de-Rubis tout roses, on sentira la brise chaude de la mer et on regardera plein d’étoiles qu’on ne voit pas ici. Ce sera trop bien, comme quand je suis venue ici ! Je vous attendrai !",
            ["DialogueId"] = 20007014,
            ["GUID"] = "3215E0BC",
            ["NextDialogue"] = 20007015,
            ["SpeakNpcId"] = 200074,
            ["VoiceName"] = "voice/$Locale$/story/2001/200070/3215E0BC",
            },
        [20007015] = {
            ["Content"] = "嗯，我会尽量做到。",
            ["ContentFR"] = "D’accord, je vais faire de mon mieux.",
            ["DialogueId"] = 20007015,
            ["GUID"] = "3215E0E6",
            ["NextDialogue"] = 20007016,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/2001/200070/3215E0E6",
            },
        [20007016] = {
            ["Content"] = "拉钩为定。",
            ["ContentFR"] = "On se le jure sur le petit doigt !",
            ["DialogueId"] = 20007016,
            ["GUID"] = "3215E110",
            ["NextOptions"] = {
                [1] = 200070161,
                },
            ["SpeakNpcId"] = 200074,
            ["VoiceName"] = "voice/$Locale$/story/2001/200070/3215E110",
            },
        [20007017] = {
            ["Content"] = "也要和榛子拉钩。",
            ["ContentFR"] = "Et avec Filbert aussi !",
            ["DialogueId"] = 20007017,
            ["GUID"] = "3215E13A",
            ["NextDialogue"] = 20007018,
            ["SpeakNpcId"] = 200074,
            ["VoiceName"] = "voice/$Locale$/story/2001/200070/3215E13A",
            },
        [20007018] = {
            ["Content"] = "榛子的蹄子太粗，拉不了勾啦。",
            ["ContentFR"] = "Les sabots de Filbert sont trop gros pour un petit doigt...",
            ["DialogueId"] = 20007018,
            ["GUID"] = "3215E164",
            ["NextDialogue"] = 20007019,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/2001/200070/3215E164",
            },
        [20007019] = {
            ["Content"] = "那握住它的蹄子就行。来，我们一起：拉钩上吊，一百年不许变！",
            ["ContentFR"] = "Alors tiens juste son sabot, ça marche quand même ! Allez, ensemble : promis sur le petit doigt, pour toujours !",
            ["DialogueId"] = 20007019,
            ["GUID"] = "3215E18E",
            ["NextDialogue"] = 20007020,
            ["SpeakNpcId"] = 200074,
            ["VoiceName"] = "voice/$Locale$/story/2001/200070/3215E18E",
            },
        [20007020] = {
            ["Content"] = "哼唧！",
            ["ContentFR"] = "<I>Groin !</>",
            ["DialogueId"] = 20007020,
            ["GUID"] = "3215E1B8",
            ["SpeakNpcId"] = 200086,
            ["VoiceName"] = "voice/$Locale$/story/2001/200070/3215E1B8",
            },
        [20007101] = {
            ["Content"] = "我乃——冰湖城第一魔灵学者！有什么魔灵疑问，都可以问我——啊，是你啊……有……有什么事吗？",
            ["ContentFR"] = "Je suis... le premier chercheur en Géniemon de Givrelac ! Si vous avez des questions sur ces créatures, vous pouvez me demander — Ah, c’est toi... Euh, je peux t’aider ?",
            ["DialogueId"] = 20007101,
            ["GUID"] = "3215EF02",
            ["NextOptions"] = {
                [1] = 200071011,
                [2] = 200071012,
                [3] = 200071013,
                },
            ["SpeakNpcId"] = 200075,
            ["SpeakNpcName"] = "UI_CMNpc_Name_MolingXZ",
            ["VoiceName"] = "voice/$Locale$/story/2001/200071/3215EF02",
            },
        [20007102] = {
            ["Content"] = "你是说那个很聪明的魔灵吗？",
            ["ContentFR"] = "Tu veux parler de ce Géniemon réputé pour son intelligence ?",
            ["DialogueId"] = 20007102,
            ["GUID"] = "3215EF2C",
            ["NextDialogue"] = 20007103,
            ["SpeakNpcId"] = 200075,
            ["SpeakNpcName"] = "UI_CMNpc_Name_MolingXZ",
            ["VoiceName"] = "voice/$Locale$/story/2001/200071/3215EF2C",
            },
        [20007103] = {
            ["Content"] = "关于它的记录非常少，我也只见过那一次，听说只有受到它们的认可，才能找到他们。",
            ["ContentFR"] = "Les archives sont très maigres. Je ne l’ai vu qu’une seule fois. On raconte qu’il ne se montre qu’à ceux qu’il juge dignes.",
            ["DialogueId"] = 20007103,
            ["GUID"] = "3215EF56",
            ["NextDialogue"] = 20007104,
            ["SpeakNpcId"] = 200075,
            ["SpeakNpcName"] = "UI_CMNpc_Name_MolingXZ",
            ["VoiceName"] = "voice/$Locale$/story/2001/200071/3215EF56",
            },
        [20007104] = {
            ["Content"] = "不过，你应该可以顺着它们留下来的痕迹找到藏身的地方。",
            ["ContentFR"] = "En revanche, tu devrais pouvoir le localiser en suivant les traces qu’il laisse.",
            ["DialogueId"] = 20007104,
            ["GUID"] = "3215EF80",
            ["SpeakNpcId"] = 200075,
            ["SpeakNpcName"] = "UI_CMNpc_Name_MolingXZ",
            ["VoiceName"] = "voice/$Locale$/story/2001/200071/3215EF80",
            },
        [20007105] = {
            ["Content"] = "比做魔灵猎人要好多了，每天都有许多人来问我魔灵问题，好像我真的是什么大学者一样。",
            ["ContentFR"] = "Bien mieux que celle d’un chasseur de Géniemon. Maintenant, des gens viennent me poser des questions, j’ai l’air d’un vrai savant.",
            ["DialogueId"] = 20007105,
            ["GUID"] = "3215EFAA",
            ["NextDialogue"] = 20007106,
            ["SpeakNpcId"] = 200075,
            ["SpeakNpcName"] = "UI_CMNpc_Name_MolingXZ",
            ["VoiceName"] = "voice/$Locale$/story/2001/200071/3215EFAA",
            },
        [20007106] = {
            ["Content"] = "多谢你和松露手下留情，多谢多谢。",
            ["ContentFR"] = "Merci d’avoir été indulgent avec moi, toi et Truffle. Vraiment, merci.",
            ["DialogueId"] = 20007106,
            ["GUID"] = "3215EFD4",
            ["SpeakNpcId"] = 200075,
            ["SpeakNpcName"] = "UI_CMNpc_Name_MolingXZ",
            ["VoiceName"] = "voice/$Locale$/story/2001/200071/3215EFD4",
            },
        [20007107] = {
            ["Content"] = "若干道深深的刻痕，似是某种尖锐物体留下的痕迹。",
            ["ContentFR"] = "Plusieurs profondes entailles, laissées, semble-t-il, par un objet particulièrement tranchant.",
            ["DialogueId"] = 20007107,
            ["GUID"] = "3215EFD5",
            },
        [20007108] = {
            ["Content"] = "写着“禁区危险，严禁通行”的告示。贴了厚厚一叠，似乎是当老告示变旧了就会贴一张新告示上去。最新的一张告示落款是新历1004年，也就是二十年前——格雷姆矿场应当就是在那时彻底废弃的。",
            ["ContentFR"] = "Un panneau indiquant : « Zone dangereuse — Accès strictement interdit ». Plusieurs avis ont été superposés, comme si un nouveau venait recouvrir l’ancien dès qu’il se dégradait. Le plus récent est daté de l’an 1004 du nouveau calendrier — il y a une vingtaine d’années. C’est sans doute à cette époque que la Fosse de Glevum a été définitivement abandonnée.",
            ["DialogueId"] = 20007108,
            ["GUID"] = "3215EFD6",
            },
        [21000101] = {
            ["Content"] = "背白白进场台词（测试用）",
            ["DialogueId"] = 21000101,
            ["GUID"] = "34925112",
            ["TalkActionId"] = {
                [1] = "900005:Beibao_Start",
                },
            },
        [21000102] = {
            ["Content"] = "背白白退场台词（测试用）",
            ["DialogueId"] = 21000102,
            ["GUID"] = "3492513C",
            ["TalkActionId"] = {
                [1] = "900005:Beibao_Finish",
                },
            },
        [50000101] = {
            ["Content"] = "通行证——喂，说你呢，通行证带了吗？",
            ["ContentFR"] = "Hé, c’est à toi que je parle ! Tu as bien ton permis sur toi ?",
            ["DialogueId"] = 50000101,
            ["Duration"] = 3,
            ["GUID"] = "7D2B8592",
            ["SpeakNpcId"] = 700111,
            ["VoiceName"] = "voice/$Locale$/env/700002/7D2B8592",
            },
        [50000201] = {
            ["Content"] = "居然有狩月人能找到这里，看来你和它们一样，有着成为英雄的可能啊。",
            ["ContentFR"] = "{性别:Un Chasseur de Phoxène|Une Chasseuse de Phoxène} ? Je n’aurais jamais cru que l’un d’eux atteindrait cet endroit... Tu dois avoir, toi aussi, ce qu’il faut pour devenir {性别:un héros|une héroïne}.",
            ["DialogueId"] = 50000201,
            ["Duration"] = 4,
            ["GUID"] = "7D2B95FA",
            ["SpeakNpcId"] = 700003,
            ["VoiceName"] = "voice/$Locale$/env/700003/7D2B95FA",
            },
        [50000301] = {
            ["Content"] = "**的都怪格朗德，我现在到底该怎么办呢……嗯？看什么看，我这今天也没有委托！",
            ["ContentFR"] = "Tout ça, c’est la faute de Grandet ! Qu’est-ce que je suis censé faire maintenant... Hein ? Qu’est-ce que tu regardes ? Je n’ai aucune mission pour toi aujourd’hui !",
            ["DialogueId"] = 50000301,
            ["Duration"] = 3,
            ["GUID"] = "7D2BA662",
            ["SpeakNpcId"] = 700004,
            ["VoiceName"] = "voice/$Locale$/env/700004/7D2BA662",
            },
        [50000401] = {
            ["Content"] = "我是……安妮？",
            ["ContentFR"] = "Je suis... Annie ?",
            ["DialogueId"] = 50000401,
            ["Duration"] = 3,
            ["GUID"] = "7D2BB6CA",
            ["SpeakNpcId"] = 700032,
            ["TalkActionId"] = {
                [1] = "700032:Sigh_Start",
                },
            ["VoiceName"] = "voice/$Locale$/env/700032/7D2BB6CA",
            },
        [50000501] = {
            ["Content"] = "等身体养好了，我就打算开始下一段冒险了。",
            ["ContentFR"] = "Dès que je serai rétablie, je reprendrai la route pour une nouvelle aventure.",
            ["DialogueId"] = 50000501,
            ["Duration"] = 3,
            ["GUID"] = "7D2BC732",
            ["SpeakNpcId"] = 700005,
            ["TalkActionId"] = {
                [1] = "700032:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/env/700005/7D2BC732",
            },
        [50000601] = {
            ["Content"] = "我该带什么去见妈妈呢……她一定很想我。",
            ["ContentFR"] = "Qu’est-ce que je pourrais offrir à maman... ? Elle doit être impatiente de me revoir.",
            ["DialogueId"] = 50000601,
            ["Duration"] = 3,
            ["GUID"] = "7D2BD79A",
            ["SpeakNpcId"] = 700005,
            ["TalkActionId"] = {
                [1] = "700005:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/env/700005/7D2BD79A",
            },
        [50000701] = {
            ["Content"] = "安妮……安妮！",
            ["ContentFR"] = "Annie... Annie !",
            ["DialogueId"] = 50000701,
            ["Duration"] = 3,
            ["GUID"] = "7D2BE802",
            ["SpeakNpcId"] = 700006,
            ["VoiceName"] = "voice/$Locale$/env/700006/7D2BE802",
            },
        [50000801] = {
            ["Content"] = "今天的鲜花真好看啊，得留几朵给那孩子送去。",
            ["ContentFR"] = "Les fleurs sont magnifiques aujourd’hui... Je devrais en garder quelques-unes pour cette enfant.",
            ["DialogueId"] = 50000801,
            ["Duration"] = 3,
            ["GUID"] = "7D2BF86A",
            ["SpeakNpcId"] = 700007,
            ["TalkActionId"] = {
                [1] = "700007:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/env/700007/7D2BF86A",
            },
        [50000901] = {
            ["Content"] = "您好，这朵花与您今天的装扮很相称……如果那孩子还在的话，一定也会这么说吧。",
            ["ContentFR"] = "Bonjour. Cette fleur s’accorde parfaitement avec votre tenue... Si elle était encore là, elle aurait dit la même chose.",
            ["DialogueId"] = 50000901,
            ["Duration"] = 5,
            ["GUID"] = "7D2C08D2",
            ["SpeakNpcId"] = 700203,
            ["VoiceName"] = "voice/$Locale$/env/700007/7D2C08D2",
            },
        [50001001] = {
            ["Content"] = "您这身板样貌，不穿我家的衣服可惜了。",
            ["ContentFR"] = "Avec votre allure, ce serait un crime de ne pas porter mes créations.",
            ["DialogueId"] = 50001001,
            ["Duration"] = 3,
            ["GUID"] = "7D2C193A",
            ["SpeakNpcId"] = 700008,
            ["VoiceName"] = "voice/$Locale$/env/700008/7D2C193A",
            },
        [50001101] = {
            ["Content"] = "自家庄园的好果子，别的地方没有这培育技术！",
            ["ContentFR"] = "Les meilleurs fruits de notre domaine ! Nulle part ailleurs vous ne trouverez un savoir-faire aussi raffiné !",
            ["DialogueId"] = 50001101,
            ["Duration"] = 3,
            ["GUID"] = "7D2C29A2",
            ["SpeakNpcId"] = 700009,
            ["TalkActionId"] = {
                [1] = "700009:Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/env/700009/7D2C29A2",
            },
        [50001201] = {
            ["Content"] = "啊……哇哇我……",
            ["ContentFR"] = "Ah... O-Oh, je... euh...",
            ["DialogueId"] = 50001201,
            ["Duration"] = 2,
            ["GUID"] = "7D2C3A0A",
            ["SpeakNpcId"] = 700010,
            ["VoiceName"] = "voice/$Locale$/env/700010/7D2C3A0A",
            },
        [50001301] = {
            ["Content"] = "嗯……实验对象1号，就决定是你了！",
            ["ContentFR"] = "Hmm... j’ai décidé, toi, tu seras le sujet d’expérience n° 1 !",
            ["DialogueId"] = 50001301,
            ["Duration"] = 3,
            ["GUID"] = "7D2C4A72",
            ["SpeakNpcId"] = 700011,
            ["TalkActionId"] = {
                [1] = "700011:Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/env/700011/7D2C4A72",
            },
        [50001401] = {
            ["Content"] = "{nickname}，又见面啦！我每天都在努力学习新知识哦，一起加油吧！",
            ["ContentFR"] = "{nickname} ! Je suis content de te voir ! Moi, je continue à apprendre plein de nouvelles choses tous les jours. Alors... on continue à progresser ensemble, d’accord ?",
            ["DialogueId"] = 50001401,
            ["Duration"] = 4,
            ["GUID"] = "7D2C5ADA",
            ["SpeakNpcId"] = 700011,
            ["TalkActionId"] = {
                [1] = "700011:Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/env/700011/7D2C5ADA",
            },
        [50001501] = {
            ["Content"] = "你……卡戎……我的同类……",
            ["ContentFR"] = "Tu... Charon... un des miens...",
            ["DialogueId"] = 50001501,
            ["Duration"] = 6,
            ["GUID"] = "7D2C6B42",
            ["SpeakNpcId"] = 700012,
            ["VoiceName"] = "voice/$Locale$/env/700012/7D2C6B42",
            },
        [50001601] = {
            ["Content"] = "见不得人的事我见多了，涉事的主角们也不止有“恶魔”。\
……有时我也分不清，人类与卡戎，到底谁才是恶魔。",
            ["ContentFR"] = "J’en ai vu, des choses qu’on préfère cacher dans l’ombre... Et les \"démons\" ne sont pas toujours ceux qu’on croit.\
... Parfois, entre les Solariens et les Charons, je ne sais plus lesquels sont les véritables démons.",
            ["DialogueId"] = 50001601,
            ["Duration"] = 4,
            ["GUID"] = "7D2C7BAA",
            ["SpeakNpcId"] = 700013,
            ["VoiceName"] = "voice/$Locale$/env/700013/7D2C7BAA",
            },
        [50001701] = {
            ["Content"] = "呸！不识货的蠢婆娘！我倒要看看你还能兴风作浪到什么时候！",
            ["ContentFR"] = "Pff ! Sale idiote ! On verra bien combien de temps encore tu pourras jouer les fortes têtes !",
            ["DialogueId"] = 50001701,
            ["Duration"] = 4,
            ["GUID"] = "7D2C8C12",
            ["SpeakNpcId"] = 700014,
            ["TalkActionId"] = {
                [1] = "700014:Angry01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/env/700014/7D2C8C12",
            },
        [50001801] = {
            ["Content"] = "皇帝在上，我这样善良的人儿却碰上了偷窃灵感的幽魂！哦，这真是一桩老天爷见了都会落泪的冤案！",
            ["ContentFR"] = "Par tous les Cieux ! Comment un être aussi doux que moi a-t-il pu tomber victime d’un spectre voleur d’inspiration ?! Une telle injustice ferait pleurer même les cieux !",
            ["DialogueId"] = 50001801,
            ["Duration"] = 4,
            ["GUID"] = "7D2C9C7A",
            ["SpeakNpcId"] = 700015,
            ["VoiceName"] = "voice/$Locale$/env/700015/7D2C9C7A",
            },
        [50001901] = {
            ["Content"] = "真没劲！净组织些虚头巴脑的活动，还不如放半天假呢！",
            ["ContentFR"] = "Quelle perte de temps ! Organiser des évènements aussi creux... On ferait mieux d’avoir une demi-journée de repos !",
            ["DialogueId"] = 50001901,
            ["Duration"] = 3,
            ["GUID"] = "7D2CACE2",
            ["SpeakNpcId"] = 700016,
            ["VoiceName"] = "voice/$Locale$/env/700016/7D2CACE2",
            },
        [50002001] = {
            ["Content"] = "“下雨了，妈妈的花被浇坏了，所以天空在水坑里赔给妈妈无数朵小花。”",
            ["ContentFR"] = "« Sous la pluie, les fleurs de maman se sont fanées... Alors le ciel a semé de petites fleurs dans les flaques, pour lui présenter ses excuses. »",
            ["DialogueId"] = 50002001,
            ["Duration"] = 3,
            ["GUID"] = "7D2CBD4A",
            ["NextDialogue"] = 50002002,
            ["SpeakNpcId"] = 700017,
            ["VoiceName"] = "voice/$Locale$/env/700017/7D2CBD4A",
            },
        [50002002] = {
            ["Content"] = "——您知道吗，这首诗叫做《道歉》，是我六岁的学生写的。",
            ["ContentFR"] = "Vous savez ? Ce petit poème s’intitule <I>Excuses</>, et il a été écrit par l’un de mes élèves... il n’a que six ans.",
            ["DialogueId"] = 50002002,
            ["Duration"] = 3,
            ["GUID"] = "7D2CBD74",
            ["SpeakNpcId"] = 700017,
            ["TalkActionId"] = {
                [1] = "700017:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/env/700017/7D2CBD74",
            },
        [50002101] = {
            ["Content"] = "向自然法则扔出的石头，最终一定会砸到自己的头上。",
            ["ContentFR"] = "Les pierres jetées contre les lois de la nature finissent toujours par retomber sur celui qui les lance.",
            ["DialogueId"] = 50002101,
            ["Duration"] = 3,
            ["GUID"] = "7D2CCDB2",
            ["SpeakNpcId"] = 700018,
            ["TalkActionId"] = {
                [1] = "700018:Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/env/700018/7D2CCDB2",
            },
        [50002201] = {
            ["Content"] = "到底去了哪里啊……",
            ["ContentFR"] = "Où a-t-il bien pu disparaître...",
            ["DialogueId"] = 50002201,
            ["Duration"] = 3,
            ["GUID"] = "7D2CDE1A",
            ["SpeakNpcId"] = 700019,
            ["TalkActionId"] = {
                [1] = "700019:Sigh_Start",
                },
            ["VoiceName"] = "voice/$Locale$/env/700019/7D2CDE1A",
            },
        [50002301] = {
            ["Content"] = "希望今晚的奶油蘑菇浓汤能让夫人感到稍许舒适。",
            ["ContentFR"] = "J’espère que la crème de champignons préparée ce soir réchauffera un peu le cœur de Madame.",
            ["DialogueId"] = 50002301,
            ["Duration"] = 4,
            ["GUID"] = "7D2CEE82",
            ["SpeakNpcId"] = 700020,
            ["TalkActionId"] = {
                [1] = "700020:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/env/700020/7D2CEE82",
            },
        [50002401] = {
            ["Content"] = "真可怜，每天疯疯癫癫的。",
            ["ContentFR"] = "Pauvre femme... Elle a complètement perdu la tête.",
            ["DialogueId"] = 50002401,
            ["Duration"] = 3,
            ["GUID"] = "7D2CFEEA",
            ["NextDialogue"] = 50002402,
            ["SpeakNpcId"] = 700023,
            ["VoiceName"] = "voice/$Locale$/env/700023/7D2CFEEA",
            },
        [50002402] = {
            ["Content"] = "怪不得她女儿会受不了她的管教。",
            ["ContentFR"] = "Pas étonnant que sa fille ait fini par partir.",
            ["DialogueId"] = 50002402,
            ["Duration"] = 3,
            ["GUID"] = "7D2CFF14",
            ["SpeakNpcId"] = 700024,
            ["VoiceName"] = "voice/$Locale$/env/700024/7D2CFF14",
            },
        [50002501] = {
            ["Content"] = "全城的垃圾桶都归我管，那里有只穿过几回的鹿皮靴子，没来得及打蔫的百合花，还有不知道是谁碎掉的梦……",
            ["ContentFR"] = "Toutes les poubelles de la cité sont sous ma garde. Et crois-moi, on y trouve de tout ! Des bottes en daim portées à peine deux fois, des lys encore frais... et même les fragments de rêves brisés de quelqu’un.",
            ["DialogueId"] = 50002501,
