            ["VoiceName"] = "voice/$Locale$/env/700072/7D2D71C2",
            },
        [50003201] = {
            ["Content"] = "城外的怪物吃我们的肉~城内的怪物剪我们的毛~猎犬们吃着白面包~咱们绵羊嚼着地上的草~",
            ["ContentFR"] = "« Hors de la ville, les Souillés nous dévorent, en ville, les fermiers nous tondent sans répit. Les chiens festoient de pain blanc, les moutons Charon broutent l’herbe jaunie... »",
            ["DialogueId"] = 50003201,
            ["Duration"] = 3,
            ["GUID"] = "7D2D822A",
            ["NextDialogue"] = 50003202,
            ["SpeakNpcId"] = 700073,
            ["TalkActionId"] = {
                [1] = "700073:Confident_Start",
                },
            ["VoiceName"] = "voice/$Locale$/env/700073/7D2D822A",
            },
        [50003202] = {
            ["Content"] = "该死！你跟谁学的这首歌……早晚你要害死我们俩！",
            ["ContentFR"] = "Bon sang ! Où as-tu appris cette chanson... ? Un jour, elle va nous faire exécuter tous les deux !",
            ["DialogueId"] = 50003202,
