            ["VoiceName"] = "voice/$Locale$/env/700074/7D2D8254",
            },
        [50003203] = {
            ["Content"] = "哦！客人要买点什么？这都是我自己手工做的，质量可是一顶一的好！",
            ["ContentFR"] = "Oh ! {性别:Cher client|Chère cliente}, désirez-vous acheter quelque chose ? Tout ici est fait main par mes soins, qualité irréprochable garantie !",
