            ["VoiceName"] = "voice/$Locale$/env/700081/7D2DE49A",
            },
        [50003901] = {
            ["Content"] = "别看我手断过，搬杂货还是能搬动的，您要点什么？",
            ["ContentFR"] = "Ne vous fiez pas à mon bras cassé, je peux encore transporter des marchandises. Qu’est-ce qu’il vous faut ?",
