            ["VoiceName"] = "voice/$Locale$/env/700113/7D2E470A",
            },
        [50004501] = {
            ["Content"] = "跳舞吧！来跳舞！活着有什么意义？让我们把所有复杂的问题丢进垃圾桶，共舞直到明天！",
            ["ContentFR"] = "Danse ! Allez, danse ! La vie n’a pas de sens, alors balance toutes tes préoccupations à la poubelle et danse avec moi jusqu’au matin !",
