            },
        [50100701] = {
            ["Content"] = "香料丝绸茶叶油膏器皿……种类也太多了！",
            ["ContentFR"] = "Épices, soieries, thés, huiles, onguents, vaisselle... il y a trop de choix !",
            ["DialogueId"] = 50100701,
            ["GUID"] = "7D6BFE42",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6BFE42",
            },
        [50100801] = {
            ["Content"] = "沉月香卖完了？怎么可能，昨天才进的货！",
            ["ContentFR"] = "Plus de Lune Profonde ? Impossible ! La livraison date d’hier !",
            ["DialogueId"] = 50100801,
            ["GUID"] = "7D6C0EAA",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6C0EAA",
            },
        [50100901] = {
            ["Content"] = "点数清，码数齐，今日开市不慌矣~",
            ["ContentFR"] = "Comptes vérifiés, marchandises rangées... la journée commence sans souci~",
            ["DialogueId"] = 50100901,
            ["GUID"] = "7D6C1F12",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6C1F12",
            },
        [50101001] = {
            ["Content"] = "不愧是织星客的故乡，华胥果真名不虚传。",
            ["ContentFR"] = "Ainsi donc, la patrie des Tisse-Étoiles... Huaxu mérite vraiment sa réputation.",
            ["DialogueId"] = 50101001,
            ["GUID"] = "7D6C2F7A",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6C2F7A",
            },
        [50101101] = {
            ["Content"] = "山清水秀，在此品一盏香茗，妙趣横生呐~",
            ["ContentFR"] = "Montagnes limpides, eaux claires... savourer un thé parfumé ici serait un pur bonheur~",
            ["DialogueId"] = 50101101,
            ["GUID"] = "7D6C3FE2",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6C3FE2",
            },
        [50101201] = {
            ["Content"] = "说好打赌输了就欠我三根糖葫芦，你不许耍赖。",
            ["ContentFR"] = "On avait dit que si tu perdais, tu me devais trois brochettes de tanghulu. Pas de triche !",
            ["DialogueId"] = 50101201,
            ["GUID"] = "7D6C504A",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6C504A",
            },
        [50101202] = {
            ["Content"] = "放心，明日阿娘给了零花钱就来请你！",
            ["ContentFR"] = "D’accord ! Demain, quand maman me donnera de l’argent, je t’invite !",
            ["DialogueId"] = 50101202,
            ["GUID"] = "7D6C5074",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6C5074",
            },
        [50101203] = {
            ["Content"] = "浮星埠是一年比一年热闹了啊……",
            ["ContentFR"] = "Quai-aux-Étoiles devient de plus en plus animé chaque année...",
            ["DialogueId"] = 50101203,
            ["GUID"] = "7D6C509E",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6C509E",
            },
        [50101301] = {
            ["Content"] = "诶呀！撞得我发髻都散啦！",
            ["ContentFR"] = "<I>Aïe !</> Tu m’as bousculée, ma coiffure est toute défaite !",
            ["DialogueId"] = 50101301,
            ["GUID"] = "7D6C60B2",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6C60B2",
            },
        [50101401] = {
            ["Content"] = "嘿！小友走路别分心，撞到人可不好！",
            ["ContentFR"] = "Hé, jeune {性别:homme|femme}, regarde où tu marches. Heurter les gens, ce n’est pas bien.",
            ["DialogueId"] = 50101401,
            ["GUID"] = "7D6C711A",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6C711A",
            },
        [50101501] = {
            ["Content"] = "绸缎齐整，杂粮归铺，心才安……",
            ["ContentFR"] = "Soieries rangées, grains stockés... alors seulement le cœur est en paix...",
            ["DialogueId"] = 50101501,
            ["GUID"] = "7D6C8182",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6C8182",
            },
        [50101601] = {
            ["Content"] = "祖传山参，百年阿胶，价优物美待君选！",
            ["ContentFR"] = "Ginseng de lignée ancienne, gélatine d’âne centenaire ! Marchandise de choix, prix honnêtes !",
            ["DialogueId"] = 50101601,
            ["GUID"] = "7D6C91EA",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6C91EA",
            },
        [50101701] = {
            ["Content"] = "好东西不贱卖哈，总有眼尖识货人！",
            ["ContentFR"] = "Les bonnes choses ne se bradent pas. Les connaisseurs savent reconnaître leur valeur.",
            ["DialogueId"] = 50101701,
            ["GUID"] = "7D6CA252",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6CA252",
            },
        [50101801] = {
            ["Content"] = "瓷器娇贵，客人轻拿轻放~",
            ["ContentFR"] = "Porcelaine fragile, doucement, s’il vous plaît~",
            ["DialogueId"] = 50101801,
            ["GUID"] = "7D6CB2BA",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6CB2BA",
            },
        [50101901] = {
            ["Content"] = "再便宜点，我直接拿了。",
            ["ContentFR"] = "Faites-moi encore un petit prix, et je la prends tout de suite.",
            ["DialogueId"] = 50101901,
            ["GUID"] = "7D6CC322",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6CC322",
            },
        [50102001] = {
            ["Content"] = "瓶子看着精致……没什么瑕疵吧？",
            ["ContentFR"] = "Ce vase est élégant... aucune fissure, n’est-ce pas ?",
            ["DialogueId"] = 50102001,
            ["GUID"] = "7D6CD38A",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6CD38A",
            },
        [50102101] = {
            ["Content"] = "称点桂花糕，我带回去给娘子吃~",
            ["ContentFR"] = "Un peu de gâteau à l’osmanthe, s’il vous plaît. C’est pour ma femme~",
            ["DialogueId"] = 50102101,
            ["GUID"] = "7D6CE3F2",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6CE3F2",
            },
        [50102201] = {
            ["Content"] = "这匹布料柔软顺滑，做成里衣定是舒适。",
            ["ContentFR"] = "Ce tissu est si doux... parfait pour des sous-vêtements confortables.",
            ["DialogueId"] = 50102201,
            ["GUID"] = "7D6CF45A",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6CF45A",
            },
        [50102301] = {
            ["Content"] = "神君鉴上，我雪霁立誓一生不负初晴，如……",
            ["ContentFR"] = "Par le regard du Seigneur Dragon, moi, Xueji, je fais le serment de ne jamais trahir Chuqing, sinon...",
            ["DialogueId"] = 50102301,
            ["GUID"] = "7D6D04C2",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6D04C2",
            },
        [50102401] = {
            ["Content"] = "嘘！后面的话不许你说！我都明白……",
            ["ContentFR"] = "Chut ! Ne dis pas la suite ! Je comprends...",
            ["DialogueId"] = 50102401,
            ["GUID"] = "7D6D152A",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6D152A",
            },
        [50102501] = {
            ["Content"] = "白龙神君保佑此次出航平安无虞！",
            ["ContentFR"] = "Que le Seigneur Dragon d’Argent bénisse cette traversée et nous accorde une navigation sans heurts !",
            ["DialogueId"] = 50102501,
            ["GUID"] = "7D6D2592",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6D2592",
            },
        [50102601] = {
            ["Content"] = "小女愿家中长辈身体康健，福寿绵长。",
            ["ContentFR"] = "Je prie pour que les anciens de ma famille restent en bonne santé, et que leur vie soit longue et paisible.",
            ["DialogueId"] = 50102601,
            ["GUID"] = "7D6D35FA",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6D35FA",
            },
        [50102701] = {
            ["Content"] = "明先生最近可是在哪发了大财？",
            ["ContentFR"] = "Alors, Monsieur Ming, on dirait que les affaires ont été florissantes ces derniers temps ?",
            ["DialogueId"] = 50102701,
            ["GUID"] = "7D6D4662",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6D4662",
            },
        [50102702] = {
            ["Content"] = "侥幸而已！还是江先生的生意更稳当。",
            ["ContentFR"] = "Oh, rien que de la chance ! Vos affaires à vous sont bien plus solides, Monsieur Jiang.",
            ["DialogueId"] = 50102702,
            ["GUID"] = "7D6D468C",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6D468C",
            },
        [50102801] = {
            ["Content"] = "下次出航得往赫墨北边再走一走……",
            ["ContentFR"] = "La prochaine expédition devrait pousser un peu plus au nord de Khemet...",
            ["DialogueId"] = 50102801,
            ["GUID"] = "7D6D56CA",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6D56CA",
            },
        [50102901] = {
            ["Content"] = "明明已经让了极大的利，为何销量还是……",
            ["ContentFR"] = "J’ai pourtant consenti de très larges concessions... pourquoi les ventes ne décollent-elles toujours pas ?",
            ["DialogueId"] = 50102901,
            ["GUID"] = "7D6D6732",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6D6732",
            },
        [50103001] = {
            ["Content"] = "我才加入织星客，凡事劳请前辈多指点！",
            ["ContentFR"] = "Je viens à peine de rejoindre les Tisse-Étoiles. J’espère pouvoir compter sur les conseils de mes aînés.",
            ["DialogueId"] = 50103001,
            ["GUID"] = "7D6D779A",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6D779A",
            },
        [50103002] = {
            ["Content"] = "客气了，若有问题便尽管问吧。",
            ["ContentFR"] = "Nul besoin de tant de politesses. Si vous avez des questions, posez-les sans hésiter.",
            ["DialogueId"] = 50103002,
            ["GUID"] = "7D6D77C4",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6D77C4",
            },
        [50103003] = {
            ["Content"] = "您说我是要继续追资还是见好就收呢？",
            ["ContentFR"] = "Selon vous, vaut-il mieux continuer à investir... ou se retirer pendant qu’il en est encore temps ?",
            ["DialogueId"] = 50103003,
            ["GUID"] = "7D6D77EE",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6D77EE",
            },
        [50103101] = {
            ["Content"] = "新来的哥儿，皮子肥不肥？",
            ["ContentFR"] = "Le nouveau, là... tu crois qu’il est bien chargé ?",
            ["DialogueId"] = 50103101,
            ["GUID"] = "7D6D8802",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6D8802",
            },
        [50103201] = {
            ["Content"] = "穷地方来的，没挂多少老居米子。",
            ["ContentFR"] = "Il vient d’un coin misérable. À mon avis, il n’a pas grand-chose sur lui.",
            ["DialogueId"] = 50103201,
            ["GUID"] = "7D6D986A",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6D986A",
            },
        [50103301] = {
            ["Content"] = "客人来看看？爬山头来的正经古董。",
            ["ContentFR"] = "Venez jeter un œil, cher client. De véritables antiquités, tout juste sorties des collines.",
            ["DialogueId"] = 50103301,
            ["GUID"] = "7D6DA8D2",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6DA8D2",
            },
        [50103401] = {
            ["Content"] = "以前都只做洋庄，好不容易才运回国的！",
            ["ContentFR"] = "Avant, tout ça partait directement vers l’étranger. Ça nous a coûté cher de les rapatrier au pays !",
            ["DialogueId"] = 50103401,
            ["GUID"] = "7D6DB93A",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6DB93A",
            },
        [50103501] = {
            ["Content"] = "风里有太皓的意志，只需静下心感受……",
            ["ContentFR"] = "Le vent porte la volonté de Taihao... Il suffit de calmer son esprit pour la ressentir.",
            ["DialogueId"] = 50103501,
            ["GUID"] = "7D6DC9A2",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6DC9A2",
            },
        [50103601] = {
            ["Content"] = "冰台五十斤，春一品三十斤，诶诶诶，那边的，香料都是稀奇货，搬运的时候可小心点！",
            ["ContentFR"] = "Cinquante livres de Givrefeuille, trente de Printemps d’Excellence... Hé, hé, doucement par là-bas ! Les épices sont des denrées rares, manipulez-les avec soin !",
            ["DialogueId"] = 50103601,
            ["GUID"] = "7D6DDA0A",
            ["SpeakNpcId"] = 701039,
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6DDA0A",
            },
        [50103701] = {
            ["Content"] = "专供异国友人的纪念品摊铺，来华胥之游人必不可错过！香囊折扇古玩珍宝，您想要的，应有尽有！",
            ["ContentFR"] = "Souvenirs pour voyageurs étrangers ! À Huaxu, nul visiteur ne devrait passer à côté ! Sachets parfumés, éventails de soie, antiquités, trésors rares... tout ce que vous désirez !",
            ["DialogueId"] = 50103701,
            ["GUID"] = "7D6DEA72",
            ["SpeakNpcId"] = 701040,
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6DEA72",
            },
        [50103801] = {
            ["Content"] = "南来北往的慢走一步，且听我说道说道咱们这浮星埠的千年历史——做生意讲究明明白白，对自己的过去啊，也得清清楚楚才好。",
            ["ContentFR"] = "Voyageurs venus du sud comme du nord, accordez-moi un instant. Laissez-moi vous conter les mille ans d’histoire de notre Quai-aux-Étoiles. En affaires, on aime que tout soit clair et net... eh bien, il en va de même pour notre passé.",
            ["DialogueId"] = 50103801,
            ["GUID"] = "7D6DFADA",
            ["SpeakNpcId"] = 701041,
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6DFADA",
            },
        [50103901] = {
            ["Content"] = "您可听好了，这大风九章的第一章就是：戕身害命，不可为也。",
            ["ContentFR"] = "Écoutez bien. Le premier précepte des Neuf Chapitres de Dafeng énonce ceci : « Attenter au corps ou ôter la vie — cela est proscrit. »",
            ["DialogueId"] = 50103901,
            ["GUID"] = "7D6E0B42",
            ["SpeakNpcId"] = 701044,
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6E0B42",
            },
        [50104001] = {
            ["Content"] = "怎么样才能长出角呢，我揪……我揪……嗷！好痛……",
            ["ContentFR"] = "Comment on fait pour faire pousser des cornes... si je tire un peu... je tire... <I>aïe !</> Ça fait mal...",
            ["DialogueId"] = 50104001,
            ["GUID"] = "7D6E1BAA",
            ["SpeakNpcId"] = 701045,
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6E1BAA",
            },
        [50104101] = {
            ["Content"] = "没想到成为织星客还有如此多的便利！百年春真是家大业大啊。",
            ["ContentFR"] = "Je ne pensais pas que devenir Tisse-Étoiles offrait autant d’avantages ! Éternel Printemps a vraiment des moyens impressionnants.",
            ["DialogueId"] = 50104101,
            ["GUID"] = "7D6E2C12",
            ["SpeakNpcId"] = 701046,
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6E2C12",
            },
        [50104201] = {
            ["Content"] = "盖个会客厅怎么样？要不再加个小厨房？",
            ["ContentFR"] = "Et si on ajoutait une salle de réception ? Ou même une petite cuisine ?",
            ["DialogueId"] = 50104201,
            ["GUID"] = "7D6E3C7A",
            ["SpeakNpcId"] = 701048,
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6E3C7A",
            },
        [50104301] = {
            ["Content"] = "爬到月亮上？咱们爬得上去吗？",
            ["ContentFR"] = "Grimper jusqu’à la lune ? Mais... c’est impossible, non ?",
            ["DialogueId"] = 50104301,
            ["GUID"] = "7D6E4CE2",
            ["SpeakNpcId"] = 701050,
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6E4CE2",
            },
        [50104401] = {
            ["Content"] = "嚯，这块千星板的年岁可真够久了！",
            ["ContentFR"] = "Oh ! Ce Panneau aux Mille Étoiles a vraiment de l’âge !",
            ["DialogueId"] = 50104401,
            ["GUID"] = "7D6E5D4A",
            ["SpeakNpcId"] = 701051,
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6E5D4A",
            },
        [50104501] = {
            ["Content"] = "不以利丰为荣，以义为荣；不以豪奢为高，以德为高……",
            ["ContentFR"] = "Ne pas se glorifier de la richesse, mais de la droiture ; ne pas se prévaloir du faste, mais de la vertu...",
            ["DialogueId"] = 50104501,
            ["GUID"] = "7D6E6DB2",
            ["SpeakNpcId"] = 701052,
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6E6DB2",
            },
        [50104601] = {
            ["Content"] = "如若对百年春业务相关有所疑问，可至此处问询。",
            ["ContentFR"] = "Si vous avez la moindre question concernant les services d’Éternel Printemps, vous pouvez vous adresser à moi ici.",
            ["DialogueId"] = 50104601,
            ["GUID"] = "7D6E7E1A",
            ["SpeakNpcId"] = 701054,
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6E7E1A",
            },
        [50104701] = {
            ["Content"] = "昨天到港的北风莓酱，怎么现在还没通过检查！快把货给我！",
            ["ContentFR"] = "La confiture de Baies Boréales arrivée hier... pourquoi n’a-t-elle toujours pas passé l’inspection ? Rendez-moi ma marchandise !",
            ["DialogueId"] = 50104701,
            ["GUID"] = "7D6E8E82",
            ["SpeakNpcId"] = 701057,
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6E8E82",
            },
        [50104801] = {
            ["Content"] = "回家……可是，我的家又在哪里？这里……又是什么地方？",
            ["ContentFR"] = "Rentrer chez moi... mais où est ma maison, au juste ? Et ici... quel est donc cet endroit ?",
            ["DialogueId"] = 50104801,
            ["GUID"] = "7D6E9EEA",
            ["SpeakNpcId"] = 701059,
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6E9EEA",
            },
        [50104901] = {
            ["Content"] = "敕愿亡魂，早离迷茫，急急如律，往生乐乡……",
            ["ContentFR"] = "« Âmes errantes, par décret et par vœu, quittez la confusion sans tarder. Hâtez-vous — selon la Loi céleste — vers la Terre de Félicité. »",
            ["DialogueId"] = 50104901,
            ["GUID"] = "7D6EAF52",
            ["SpeakNpcId"] = 701060,
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6EAF52",
            },
        [50105001] = {
            ["Content"] = "如果爷爷回来看我的话，就让叶子落在我的头上吧！",
            ["ContentFR"] = "Grand-père ! Si tu es revenu me voir, fais tomber une feuille sur ma tête !",
            ["DialogueId"] = 50105001,
            ["GUID"] = "7D6EBFBA",
            ["SpeakNpcId"] = 701061,
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6EBFBA",
            },
        [50105101] = {
            ["Content"] = "这棵树，一直在说话！",
            ["ContentFR"] = "Cet arbre... il parle sans cesse !",
            ["DialogueId"] = 50105101,
            ["GUID"] = "7D6ED022",
            ["SpeakNpcId"] = 701063,
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6ED022",
            },
        [50105201] = {
            ["Content"] = "你也是从外面过来的？",
            ["ContentFR"] = "Toi aussi... tu viens de l’extérieur ?",
            ["DialogueId"] = 50105201,
            ["GUID"] = "7D6EE08A",
            ["SpeakNpcId"] = 701065,
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6EE08A",
            },
        [50105301] = {
            ["Content"] = "小鬼，微茫市可不是你随便乱逛的地方。",
            ["ContentFR"] = "Hé, {性别:gamin|gamine}. Le Marché Voilé, c’est pas un endroit où on se promène au hasard.",
            ["DialogueId"] = 50105301,
            ["GUID"] = "7D6EF0F2",
            ["SpeakNpcId"] = 701066,
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6EF0F2",
            },
        [50105401] = {
            ["Content"] = "这缝儿得趁早补，再泡些日子，木芯都得烂透咯。",
            ["ContentFR"] = "Cette fissure, faut la colmater vite. Si le bois trempe encore quelques mois, le cœur va pourrir complètement.",
            ["DialogueId"] = 50105401,
            ["GUID"] = "7D6F015A",
            ["SpeakNpcId"] = 701067,
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6F015A",
            },
        [50105501] = {
            ["Content"] = "呼……呼……",
            ["ContentFR"] = "<I>Hrr... hrr...</>",
            ["DialogueId"] = 50105501,
            ["GUID"] = "7D6F11C2",
            ["SpeakNpcId"] = 701071,
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6F11C2",
            },
        [50105601] = {
            ["Content"] = "一会冷一会热……想当年我太姥姥还跟我说，这里是个春暖花开的好地方呢！",
            ["ContentFR"] = "Un coup froid, un coup chaud... Dire que mon arrière-grand-mère racontait qu’ici, c’était un endroit doux, où les fleurs s’épanouissaient au printemps !",
            ["DialogueId"] = 50105601,
            ["GUID"] = "7D6F222A",
            ["SpeakNpcId"] = 701072,
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6F222A",
            },
        [50105701] = {
            ["Content"] = "就在这里点香，白龙神君一定会像神话里那样挺身而出，将那恶兽赶尽杀绝！",
            ["ContentFR"] = "C’est ici que je vais allumer l’encens. Le Seigneur Dragon d’Argent se dressera comme dans les mythes, et il exterminera cette bête immonde jusqu’au dernier souffle !",
            ["DialogueId"] = 50105701,
            ["GUID"] = "7D6F3292",
            ["SpeakNpcId"] = 701073,
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6F3292",
            },
        [50105801] = {
            ["Content"] = "千星板运作情况一切正常，算算时间，马上要到下一次保养的日子了……",
            ["ContentFR"] = "Le Panneau aux Mille Étoiles fonctionne normalement... À bien y réfléchir, l’échéance de la prochaine maintenance approche.",
            ["DialogueId"] = 50105801,
            ["GUID"] = "7D6F42FA",
            ["SpeakNpcId"] = 701042,
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6F42FA",
            },
        [50105901] = {
            ["Content"] = "龙老板，好久不见，新到的银针要尝尝吗，香的嘞~",
            ["ContentFR"] = "Hé, Patron Long, ça faisait longtemps ! Tu veux goûter le nouveau thé Aiguilles d’argent ? Il est délicieusement parfumé~",
            ["DialogueId"] = 50105901,
            ["GUID"] = "7D6F5362",
            ["SpeakNpcId"] = 701055,
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6F5362",
            },
        [50106001] = {
            ["Content"] = "到底是什么时候就在这里的呢？",
            ["ContentFR"] = "Depuis quand ce grand arbre se dresse-t-il ici... ?",
            ["DialogueId"] = 50106001,
            ["GUID"] = "7D6F63CA",
            ["SpeakNpcId"] = 701062,
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6F63CA",
            },
        [50106101] = {
            ["Content"] = "最近微茫市来了些新面孔，买卖时闲话许多，上不得台面。",
            ["ContentFR"] = "Ces derniers temps, pas mal de nouvelles têtes traînent au Marché Voilé. Quand ils marchandent, ils bavardent trop... ça manque sérieusement de tenue.",
            ["DialogueId"] = 50106101,
            ["GUID"] = "7D6F7432",
            ["SpeakNpcId"] = 701068,
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6F7432",
            },
        [50106201] = {
            ["Content"] = "下次和虬先生约见之时，定要选个风雅茶楼，而不是这种……",
            ["ContentFR"] = "La prochaine fois que je rencontrerai Maître Qiu, ce sera dans un salon de thé élégant. Pas dans un endroit... comme celui-ci.",
            ["DialogueId"] = 50106201,
            ["GUID"] = "7D6F849A",
            ["SpeakNpcId"] = 701070,
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6F849A",
            },
        [50106301] = {
            ["Content"] = "福运蛋上新款式啦，要不要来扭一发试试？",
            ["ContentFR"] = "Les Œufs porte-bonheur ont de nouveaux modèles ! Ça te dit d’en tenter un ?",
            ["DialogueId"] = 50106301,
            ["Duration"] = 5,
            ["GUID"] = "7D6F9502",
            ["SpeakNpcId"] = 900012,
            },
        [50107001] = {
            ["Content"] = "我的钱袋子呢？我的钱袋子怎么不见了？",
            ["DialogueId"] = 50107001,
            ["GUID"] = "7D7007DA",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7028AA",
            },
        [50107002] = {
            ["Content"] = "定是那油嘴滑舌的小贩子偷的！",
            ["DialogueId"] = 50107002,
            ["GUID"] = "7D700804",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7028D4",
            },
        [50107003] = {
            ["Content"] = "诶？怎么就是找不到呢？",
            ["DialogueId"] = 50107003,
            ["GUID"] = "7D70082E",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7028FE",
            },
        [50107004] = {
            ["Content"] = "我早跟你说了这街上有贼，之前有人看到了，一个小女孩，皮肤黑黢黢的！",
            ["DialogueId"] = 50107004,
            ["GUID"] = "7D700858",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702928",
            },
        [50107005] = {
            ["Content"] = "博山香行周年店庆，来店订购香料满十赠五~",
            ["DialogueId"] = 50107005,
            ["GUID"] = "7D700882",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702952",
            },
        [50107006] = {
            ["Content"] = "你要知道一点——我对香料品质的要求很高，晒得太干我不要，香味散得太过我也不要。",
            ["DialogueId"] = 50107006,
            ["GUID"] = "7D7008AC",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70297C",
            },
        [50107007] = {
            ["Content"] = "之前定的那批香料，品质相当不错，这次就按原先的订单再来一批，还是送到我家中。",
            ["DialogueId"] = 50107007,
            ["GUID"] = "7D7008D6",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7029A6",
            },
        [50107008] = {
            ["Content"] = "噫！好酸的果干！",
            ["DialogueId"] = 50107008,
            ["GUID"] = "7D700900",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7029D0",
            },
        [50107009] = {
            ["Content"] = "为什么没人来试试我做的糕点呢……难道是卖相不太好？可是味道很香呀……",
            ["DialogueId"] = 50107009,
            ["GUID"] = "7D70092A",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7029FA",
            },
        [50107010] = {
            ["Content"] = "华胥特色小吃，吃一口念一年！",
            ["DialogueId"] = 50107010,
            ["GUID"] = "7D700954",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702A24",
            },
        [50107011] = {
            ["Content"] = "各色果干，酸甜可口，欢迎试吃品尝~",
            ["DialogueId"] = 50107011,
            ["GUID"] = "7D70097E",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702A4E",
            },
        [50107012] = {
            ["Content"] = "那里曾是家布鞋店，现在却已经改成了木雕摊……东市啊，大变样咯！",
            ["DialogueId"] = 50107012,
            ["GUID"] = "7D7009A8",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702A78",
            },
        [50107013] = {
            ["Content"] = "这位客人，看你身材匀称，要不要来试试我们千绣阁里的成衣？",
            ["DialogueId"] = 50107013,
            ["GUID"] = "7D7009D2",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702AA2",
            },
        [50107014] = {
            ["Content"] = "同福饭馆菜品上新，外域高人指点，香料入菜，佳肴更添新风味。",
            ["DialogueId"] = 50107014,
            ["GUID"] = "7D7009FC",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702ACC",
            },
        [50107015] = {
            ["Content"] = "香料做菜？听起来奇奇怪怪的，这做出来的东西能好吃吗？",
            ["DialogueId"] = 50107015,
            ["GUID"] = "7D700A26",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702AF6",
            },
        [50107016] = {
            ["Content"] = "同福饭馆的厨子发了疯，居然把莞婆娘碾碎包进丸子里！",
            ["DialogueId"] = 50107016,
            ["GUID"] = "7D700A50",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702B20",
            },
        [50107017] = {
            ["Content"] = "一天到晚就知道折腾看似新颖实则无用的花招，可别忘了华胥美食的精髓是什么！",
            ["DialogueId"] = 50107017,
            ["GUID"] = "7D700A7A",
            ["SpeakNpcId"] = 701266,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702B4A",
            },
        [50107018] = {
            ["Content"] = "秀芳……不要离开我……秀芳……",
            ["DialogueId"] = 50107018,
            ["GUID"] = "7D700AA4",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702B74",
            },
        [50107019] = {
            ["Content"] = "把翠屏雀搬来了皓京城？！还有此等奇事！",
            ["DialogueId"] = 50107019,
            ["GUID"] = "7D700ACE",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702B9E",
            },
        [50107020] = {
            ["Content"] = "雀翎茗轩……是在这里吗？",
            ["DialogueId"] = 50107020,
            ["GUID"] = "7D700AF8",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702BC8",
            },
        [50107021] = {
            ["Content"] = "东市雀翎茗轩开张，凡携亲眷者入座，皆送花茶一壶。",
            ["DialogueId"] = 50107021,
            ["GUID"] = "7D700B22",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702BF2",
            },
        [50107022] = {
            ["Content"] = "呜呜……龙君不公啊！这茶舍还未开张，怎料运来的雀儿都不见踪影，我该如何是好……",
            ["DialogueId"] = 50107022,
            ["GUID"] = "7D700B4C",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702C1C",
            },
        [50107023] = {
            ["Content"] = "游船游船，十文一趟，排队购票，客满即发。",
            ["DialogueId"] = 50107023,
            ["GUID"] = "7D700B76",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702C46",
            },
        [50107024] = {
            ["Content"] = "这皓京城的地形，怎么看怎么觉得邪乎呢……",
            ["DialogueId"] = 50107024,
            ["GUID"] = "7D700BA0",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702C70",
            },
        [50107025] = {
            ["Content"] = "想当初咱这湖边多清净？钓竿一放，不消半个时辰就能钓上好几尾大鱼。",
            ["DialogueId"] = 50107025,
            ["GUID"] = "7D700BCA",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702C9A",
            },
        [50107026] = {
            ["Content"] = "若是能把这五禽戏练好，你平日的那些小病小灾，都可一并消弭！",
            ["DialogueId"] = 50107026,
            ["GUID"] = "7D700BF4",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702CC4",
            },
        [50107027] = {
            ["Content"] = "他们还真把那五禽戏当真了不成？",
            ["DialogueId"] = 50107027,
            ["GUID"] = "7D700C1E",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702CEE",
            },
        [50107028] = {
            ["Content"] = "自己要早起练功也便罢了，为何还要拖着我早起……呵欠……",
            ["DialogueId"] = 50107028,
            ["GUID"] = "7D700C48",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702D18",
            },
        [50107029] = {
            ["Content"] = "这皓京城还没有我说不成的媒！",
            ["DialogueId"] = 50107029,
            ["GUID"] = "7D700C72",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702D42",
            },
        [50107030] = {
            ["Content"] = "我这般主动找人说亲，会不会……被他看出来了？",
            ["DialogueId"] = 50107030,
            ["GUID"] = "7D700C9C",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702D6C",
            },
        [50107031] = {
            ["Content"] = "咱皓京人，除了吃就是喝，没别的~",
            ["DialogueId"] = 50107031,
            ["GUID"] = "7D700CC6",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702D96",
            },
        [50107032] = {
            ["Content"] = "瞧你这孩子，走起路来慌慌张张，留心点别踩到路上的石子了！",
            ["DialogueId"] = 50107032,
            ["GUID"] = "7D700CF0",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702DC0",
            },
        [50107033] = {
            ["Content"] = "什么？涨了这么多？我没看错吧？",
            ["DialogueId"] = 50107033,
            ["GUID"] = "7D700D1A",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702DEA",
            },
        [50107034] = {
            ["Content"] = "父亲向来放不下娘亲，想必在天上也是不愿看见娘亲落泪的。",
            ["DialogueId"] = 50107034,
            ["GUID"] = "7D700D44",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702E14",
            },
        [50107035] = {
            ["Content"] = "现在都什么年代了，哪有在丧礼上请乐队的人家！",
            ["DialogueId"] = 50107035,
            ["GUID"] = "7D700D6E",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702E3E",
            },
        [50107036] = {
            ["Content"] = "林兄，昔日你我诗会相逢，一见如故。高山流水，难遇知音，这杯，我敬你！",
            ["DialogueId"] = 50107036,
            ["GUID"] = "7D700D98",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702E68",
            },
        [50107037] = {
            ["Content"] = "草木深胡同……是在这里？还是……",
            ["DialogueId"] = 50107037,
            ["GUID"] = "7D700DC2",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702E92",
            },
        [50107038] = {
            ["Content"] = "你说那家私房菜？我是听说过，但那家地方小，难订座，现下去问恐怕是吃不上了。",
            ["DialogueId"] = 50107038,
            ["GUID"] = "7D700DEC",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702EBC",
            },
        [50107039] = {
            ["Content"] = "若非有仙人指路，怎知这小巷深处竟藏着这庖厨圣地！",
            ["DialogueId"] = 50107039,
            ["GUID"] = "7D700E16",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702EE6",
            },
        [50107040] = {
            ["Content"] = "老张啊，你那只八哥，今日居然念了几句诗，是不是你孙子整日在家背书被它听着学了去？",
            ["DialogueId"] = 50107040,
            ["GUID"] = "7D700E40",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702F10",
            },
        [50107041] = {
            ["Content"] = "凡夫俗子溜凡羽俗鸟，他们那些鸟，能有我这只厉害吗？",
            ["DialogueId"] = 50107041,
            ["GUID"] = "7D700E6A",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702F3A",
            },
        [50107042] = {
            ["Content"] = "车三进六，将军！老友，这局棋，你该怎么破？",
            ["DialogueId"] = 50107042,
            ["GUID"] = "7D700E94",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702F64",
            },
        [50107043] = {
            ["Content"] = "叫上陈老太太，咱们也在家里聚上一聚，打打骨牌？",
            ["DialogueId"] = 50107043,
            ["GUID"] = "7D700EBE",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702F8E",
            },
        [50107044] = {
            ["Content"] = "我看你是蹬鼻子上脸，三天不打上房揭瓦！给我回去复习功课！",
            ["DialogueId"] = 50107044,
            ["GUID"] = "7D700EE8",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702FB8",
            },
        [50107045] = {
            ["Content"] = "我来了！不好意思，今天翻墙出来被阿娘逮到了……",
            ["DialogueId"] = 50107045,
            ["GUID"] = "7D700F12",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702FE2",
            },
        [50107046] = {
            ["Content"] = "三……二……一……躲好了吗？无由生马上要出来抓你们咯？",
            ["DialogueId"] = 50107046,
            ["GUID"] = "7D700F3C",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70300C",
            },
        [50107047] = {
            ["Content"] = "今年的税账至今还在统计之中，明年的汇算眼见着也要来了……真是忙到头晕眼花。",
            ["DialogueId"] = 50107047,
            ["GUID"] = "7D700F66",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703036",
            },
        [50107048] = {
            ["Content"] = "昨夜通宵整理典籍，今日双眼昏花，恐一蹬腿就要去往虞泉了！",
            ["DialogueId"] = 50107048,
            ["GUID"] = "7D700F90",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703060",
            },
        [50107049] = {
            ["Content"] = "奉香大典意味着什么？意味着休假呀！我一直想去海伯利亚看雪……",
            ["DialogueId"] = 50107049,
            ["GUID"] = "7D700FBA",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70308A",
            },
        [50107050] = {
            ["Content"] = "这般数据出现在这栏不太应当，莫非是填错了？",
            ["DialogueId"] = 50107050,
            ["GUID"] = "7D700FE4",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7030B4",
            },
        [50107051] = {
            ["Content"] = "最近的日子，真是难得的清闲啊~",
            ["DialogueId"] = 50107051,
            ["GUID"] = "7D70100E",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7030DE",
            },
        [50107052] = {
            ["Content"] = "下次遇到这种事情记得早些来泉通司，硬拖只会让事态恶化。",
            ["DialogueId"] = 50107052,
            ["GUID"] = "7D701038",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703108",
            },
        [50107053] = {
            ["Content"] = "祀香阁今年为何额外申请了一笔经费，是作何用处的？",
            ["DialogueId"] = 50107053,
            ["GUID"] = "7D701062",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703132",
            },
        [50107054] = {
            ["Content"] = "搭台子，修香炉，后续还有各种开销，我都递交申请了，只是拨款何时能来？",
            ["DialogueId"] = 50107054,
            ["GUID"] = "7D70108C",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70315C",
            },
        [50107055] = {
            ["Content"] = "是，就是往西郊那个方向，鬼鬼祟祟的，看起来不像什么好人。",
            ["DialogueId"] = 50107055,
            ["GUID"] = "7D7010B6",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703186",
            },
        [50107056] = {
            ["Content"] = "西郊西郊西郊，为何几封投诉信，来来回回都在提西郊？",
            ["DialogueId"] = 50107056,
            ["GUID"] = "7D7010E0",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7031B0",
            },
        [50107057] = {
            ["Content"] = "快给我来碗茶水，刚从西郊回来，渴死我了！",
            ["DialogueId"] = 50107057,
            ["GUID"] = "7D70110A",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7031DA",
            },
        [50107058] = {
            ["Content"] = "嗯，是说您负责运输的一船货物在码头丢失了……不是货物？那是……翠屏雀？！",
            ["DialogueId"] = 50107058,
            ["GUID"] = "7D701134",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703204",
            },
        [50107059] = {
            ["Content"] = "它到底是怎么跑出去的呢？",
            ["DialogueId"] = 50107059,
            ["GUID"] = "7D70115E",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70322E",
            },
        [50107060] = {
            ["Content"] = "找不回来了……一切努力都付之东流了……",
            ["DialogueId"] = 50107060,
            ["GUID"] = "7D701188",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703258",
            },
        [50107061] = {
            ["Content"] = "已经找到一只了？在民居的屋顶上？到底是怎么飞上去的？！",
            ["DialogueId"] = 50107061,
            ["GUID"] = "7D7011B2",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703282",
            },
        [50107062] = {
            ["Content"] = "千绣阁今年的订货量又涨了许多，咱们的绣品在皓京城里很受欢迎呢~",
            ["DialogueId"] = 50107062,
            ["GUID"] = "7D7011DC",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7032AC",
            },
        [50107063] = {
            ["Content"] = "此趟运输甜果只有百分之三损毁？甚好甚好~",
            ["DialogueId"] = 50107063,
            ["GUID"] = "7D701206",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7032D6",
            },
        [50107064] = {
            ["Content"] = "太皓神君的纹样大家早就看腻啦~一点新意也没有。",
            ["DialogueId"] = 50107064,
            ["GUID"] = "7D701230",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703300",
            },
        [50107065] = {
            ["Content"] = "各位好姐姐好哥哥们，现在呢就已经到了咱们皓京，也是咱们华胥呢，最繁华的地方~",
            ["DialogueId"] = 50107065,
            ["GUID"] = "7D70125A",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70332A",
            },
        [50107066] = {
            ["Content"] = "三百九十九？！皓京三天两晚包吃包住包来回船票只需要三百九十九？",
            ["DialogueId"] = 50107066,
            ["GUID"] = "7D701284",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703354",
            },
        [50107067] = {
            ["Content"] = "恁大一个皓京城，比我屋头看着气派多了哟！",
            ["DialogueId"] = 50107067,
            ["GUID"] = "7D7012AE",
            ["SpecialConversation"] = "偏川普",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70337E",
            },
        [50107068] = {
            ["Content"] = "别靠过来！我……呕……我……头好晕……怎么有三个太阳……呕！",
            ["DialogueId"] = 50107068,
            ["GUID"] = "7D7012D8",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7033A8",
            },
        [50107069] = {
            ["Content"] = "水龙车我先带走了。不知道哪个龟孙以为是普通木桶，居然往里面放香油，被老鼠啃得面目全非。",
            ["DialogueId"] = 50107069,
            ["GUID"] = "7D701302",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7033D2",
            },
        [50107070] = {
            ["Content"] = "匠矩阁的师傅已经来将水龙车全部取走了吗？太麻烦他们了。",
            ["DialogueId"] = 50107070,
            ["GUID"] = "7D70132C",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7033FC",
            },
        [50107071] = {
            ["Content"] = "为何匠矩阁的人回回要来参商港跑个好几趟，来回拉扯不嫌麻烦吗？",
            ["DialogueId"] = 50107071,
            ["GUID"] = "7D701356",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703426",
            },
        [50107072] = {
            ["Content"] = "凌波微步，且看我腾空起，驾云去，身似飞雁过南关，蜻蜓点水不留痕！嘿！哈！",
            ["DialogueId"] = 50107072,
            ["GUID"] = "7D701380",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703450",
            },
        [50107073] = {
            ["Content"] = "天一热，潮一涨，这浸在水中的部分就开始疯狂长苔，转动都费劲……",
            ["DialogueId"] = 50107073,
            ["GUID"] = "7D7013AA",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70347A",
            },
        [50107074] = {
            ["Content"] = "要不是他们把水车停了下来，怎会有这多事端？",
            ["DialogueId"] = 50107074,
            ["GUID"] = "7D7013D4",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7034A4",
            },
        [50107075] = {
            ["Content"] = "你需谨记六字——明法、公心、勤谨。",
            ["DialogueId"] = 50107075,
            ["GUID"] = "7D7013FE",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7034CE",
            },
        [50107076] = {
            ["Content"] = "每至夜半三更，船舶抵港，那船工吆喝声、铁链撞击声、货箱搬运声，直吵得人不得安睡！",
            ["DialogueId"] = 50107076,
            ["GUID"] = "7D701428",
            ["SpecialConversation"] = "该npc为一期印象npc",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7034F8",
            },
        [50107077] = {
            ["Content"] = "游船游船，十文一趟，排队购票，客满即发。",
            ["DialogueId"] = 50107077,
            ["GUID"] = "7D701452",
            ["SpecialConversation"] = "该npc与刘福最好为一人",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703522",
            },
        [50107078] = {
            ["Content"] = "稍……稍等一下……我查一下刚买的《华胥问候语录大全》。",
            ["DialogueId"] = 50107078,
            ["GUID"] = "7D70147C",
            ["SpecialConversation"] = "外国人",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70354C",
            },
        [50107079] = {
            ["Content"] = "他大舅母，晚上做了什么好吃的？可是来这儿散散步，消消食？",
            ["DialogueId"] = 50107079,
            ["GUID"] = "7D7014A6",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703576",
            },
        [50107080] = {
            ["Content"] = "一，二，三，铁柱呢？铁柱为何不在？你们来的时候看到他了吗？",
            ["DialogueId"] = 50107080,
            ["GUID"] = "7D7014D0",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7035A0",
            },
        [50107081] = {
            ["Content"] = "尘香袅袅龙君现，典前争辉竞纷纭。奉香大典特别活动——灯谜会，待君赏玩！",
            ["DialogueId"] = 50107081,
            ["GUID"] = "7D7014FA",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7035CA",
            },
        [50107082] = {
            ["Content"] = "妈妈我到皓京了……",
            ["DialogueId"] = 50107082,
            ["GUID"] = "7D701524",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7035F4",
            },
        [50107083] = {
            ["Content"] = "这里面不能进去吗？我买票也不行？那有什么办法能进去看看？我想见白龙神君。",
            ["DialogueId"] = 50107083,
            ["GUID"] = "7D70154E",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70361E",
            },
        [50107084] = {
            ["Content"] = "你看！只要内心足够虔诚，望向执律阁顶之时，就会看到白龙神君在云间遨游。",
            ["DialogueId"] = 50107084,
            ["GUID"] = "7D701578",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703648",
            },
        [50107085] = {
            ["Content"] = "朝报朝报，茶不思饭不想只想看朝报，皓京独家新闻，绝对真实绝对劲爆！",
            ["DialogueId"] = 50107085,
            ["GUID"] = "7D7015A2",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703672",
            },
        [50107086] = {
            ["Content"] = "这字乍一看好似和海伯利亚那边没什么区别，可凑在一起为什么完全看不懂……",
            ["DialogueId"] = 50107086,
            ["GUID"] = "7D7015CC",
            ["SpecialConversation"] = "外国人",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70369C",
            },
        [50107087] = {
            ["Content"] = "您听我说，您去一个地方，吃什么玩什么，都是次要，主要的是要来感受当地的氛围，您说对不对？",
            ["DialogueId"] = 50107087,
            ["GUID"] = "7D7015F6",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7036C6",
            },
        [50107088] = {
            ["Content"] = "退一万步说，在人家办事处门口宣传这些也不合适吧……",
            ["DialogueId"] = 50107088,
            ["GUID"] = "7D701620",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7036F0",
            },
        [50107089] = {
            ["Content"] = "我家老婆子好好地走在街上，他路也不看，直接推着车撞了过来。",
            ["DialogueId"] = 50107089,
            ["GUID"] = "7D70164A",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70371A",
            },
        [50107090] = {
            ["Content"] = "以香论道法，坐实众生象，天地为共生，万物与我一……",
            ["DialogueId"] = 50107090,
            ["GUID"] = "7D701674",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703744",
            },
        [50107091] = {
            ["Content"] = "为人在世，奉天命当如沙洲，勤而学当如竹溪先生。",
            ["DialogueId"] = 50107091,
            ["GUID"] = "7D70169E",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70376E",
            },
        [50107092] = {
            ["Content"] = "我何时曾说我亲眼见过竹溪先生？我说的是父亲年幼之时，曾在学院听竹溪先生传授最后一课。",
            ["DialogueId"] = 50107092,
            ["GUID"] = "7D7016C8",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703798",
            },
        [50107093] = {
            ["Content"] = "吵死了……这怎么让人背书！",
            ["DialogueId"] = 50107093,
            ["GUID"] = "7D7016F2",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7037C2",
            },
        [50107094] = {
            ["Content"] = "所谓理一，即天地万物都只有一个理，所谓分殊，即千差万殊的事物都是一个理的体现。",
            ["DialogueId"] = 50107094,
            ["GUID"] = "7D70171C",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7037EC",
            },
        [50107095] = {
            ["Content"] = "五味万殊，而大同于美；曲变虽众，亦大同于和；子性各异，但大同于敏；教术众多，然大同于情。",
            ["DialogueId"] = 50107095,
            ["GUID"] = "7D701746",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703816",
            },
        [50107096] = {
            ["Content"] = "这万事万物，道理总是只有一个，但一个道理却可涵盖了世间万物，所以理一定是在前面的！",
            ["DialogueId"] = 50107096,
            ["GUID"] = "7D701770",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703840",
            },
        [50107097] = {
            ["Content"] = "今天该轮到你执勤了吧，之前你说你娘风寒，我可帮你顶了三天，夫子都起疑了！",
            ["DialogueId"] = 50107097,
            ["GUID"] = "7D70179A",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70386A",
            },
        [50107098] = {
            ["Content"] = "奉香大典期间放假，你们都去哪玩？我哥从外地回来了，说要给我带外国的新奇玩具呢。",
            ["DialogueId"] = 50107098,
            ["GUID"] = "7D7017C4",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703894",
            },
        [50107099] = {
            ["Content"] = "下午的蹴球赛，咱们队还差一人，你问过樾山哥没有？他要是肯来，咱们定能踢得对面满地找牙！",
            ["DialogueId"] = 50107099,
            ["GUID"] = "7D7017EE",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7038BE",
            },
        [50107100] = {
            ["Content"] = "按这个势头算下去，岂不是又要扩张？可这又还能往哪里扩呢？",
            ["DialogueId"] = 50107100,
            ["GUID"] = "7D701818",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7038E8",
            },
        [50107101] = {
            ["Content"] = "是了，来年开春便要递上辞函，到时候自然是会念着大家的，放心！",
            ["DialogueId"] = 50107101,
            ["GUID"] = "7D701842",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703912",
            },
        [50107102] = {
            ["Content"] = "若华胥的安宁和平需要人们以不同的努力去守护，那为何飘零人的行为不能算是一种独特的方式？",
            ["DialogueId"] = 50107102,
            ["GUID"] = "7D70186C",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70393C",
            },
        [50107103] = {
            ["Content"] = "好啊，今天的辩题有趣，我在学院许久没见过这么有意思的辩题了。",
            ["DialogueId"] = 50107103,
            ["GUID"] = "7D701896",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703966",
            },
        [50107104] = {
            ["Content"] = "空口说白话，不亚于纸上谈兵。有这闲工夫，不如多读些书！",
            ["DialogueId"] = 50107104,
            ["GUID"] = "7D7018C0",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703990",
            },
        [50107105] = {
            ["Content"] = "椒兰村的香料自然是地道，处理方式也多样，只是要论品质，外面的许多园子都不遑多让。",
            ["DialogueId"] = 50107105,
            ["GUID"] = "7D7018EA",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7039BA",
            },
        [50107106] = {
            ["Content"] = "敢问祀烟阁的管事香官现在何处？鄙人自氤园而来，与他有约。",
            ["DialogueId"] = 50107106,
            ["GUID"] = "7D701914",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7039E4",
            },
        [50107107] = {
            ["Content"] = "今日怎得是你来奉香，你哥又回烟津渡了？",
            ["DialogueId"] = 50107107,
            ["GUID"] = "7D70193E",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703A0E",
            },
        }
  end },
  { MinKey = 50107108, MaxKey = 50107350, Loader = function()
      return {
        [50107108] = {
            ["Content"] = "伏惟上苍垂佑，神君护持，愿家父身体健康，百病不侵。",
            ["DialogueId"] = 50107108,
            ["GUID"] = "7D701968",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703A38",
            },
        [50107109] = {
            ["Content"] = "唔……我的愿望是，长高一点，也不用太高，像一个正常的抟土氏就好。",
            ["DialogueId"] = 50107109,
            ["GUID"] = "7D701992",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703A62",
            },
        [50107110] = {
            ["Content"] = "奉香大典今年比往年都热闹许多呢！香官跟我说的。",
            ["DialogueId"] = 50107110,
            ["GUID"] = "7D7019BC",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703A8C",
            },
        [50107111] = {
            ["Content"] = "往年到了奉香大典期间，总是需要许多帮工入阁，今年怎得没动静了？",
            ["DialogueId"] = 50107111,
            ["GUID"] = "7D7019E6",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703AB6",
            },
        [50107112] = {
            ["Content"] = "全城的香炉都要仔细查验香料储备，尤其是中心广场水上的那个炉子，务必不能有疏漏。",
            ["DialogueId"] = 50107112,
            ["GUID"] = "7D701A10",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703AE0",
            },
        [50107113] = {
            ["Content"] = "难不成真是我思维迟缓，想不出新颖独特的香方了？",
            ["DialogueId"] = 50107113,
            ["GUID"] = "7D701A3A",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703B0A",
            },
        [50107114] = {
            ["Content"] = "不同的香方自然作用也不相同，你初来乍到，不了解也很正常。",
            ["DialogueId"] = 50107114,
            ["GUID"] = "7D701A64",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703B34",
            },
        [50107115] = {
            ["Content"] = "听说了吗？祀香阁今年招了一位特殊香官，据说是……一位皎皎之民！",
            ["DialogueId"] = 50107115,
            ["GUID"] = "7D701A8E",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703B5E",
            },
        [50107116] = {
            ["Content"] = "皎皎之民？！那矮冬瓜大头鱼一样的家伙，如何能担任香官一职？",
            ["DialogueId"] = 50107116,
            ["GUID"] = "7D701AB8",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703B88",
            },
        [50107117] = {
            ["Content"] = "去泉通司问过了吗？奉香大典前事务繁杂，那批拨款要早点讨过来才好做事。",
            ["DialogueId"] = 50107117,
            ["GUID"] = "7D701AE2",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703BB2",
            },
        [50107118] = {
            ["Content"] = "师傅，我就是想来问问，这炉灶为何总是出问题，我这几番叨扰，自己都有点过意不去了。",
            ["DialogueId"] = 50107118,
            ["GUID"] = "7D701B0C",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703BDC",
            },
        [50107119] = {
            ["Content"] = "过两天不是休息了吗？你准备回家？还是带妻子出门逛逛？",
            ["DialogueId"] = 50107119,
            ["GUID"] = "7D701B36",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703C06",
            },
        [50107120] = {
            ["Content"] = "来奉香也有这么多嘁嘁喳喳嘟嘟囔囔，要么就是嘀嘀咕咕哼哼唧唧，这要我们如何兢兢业业干活？",
            ["DialogueId"] = 50107120,
            ["GUID"] = "7D701B60",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703C30",
            },
        [50107121] = {
            ["Content"] = "你这关节做的根本不行！偶人要做抬手、转腰的动作，反复受力下来，榫头迟早开裂！",
            ["DialogueId"] = 50107121,
            ["GUID"] = "7D701B8A",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703C5A",
            },
        [50107122] = {
            ["Content"] = "你瞧瞧，这是咱们新研究的木头珍猪，上了发条后一下便能冲出十米，想学的话来机枢派报个名？",
            ["DialogueId"] = 50107122,
            ["GUID"] = "7D701BB4",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703C84",
            },
        [50107123] = {
            ["Content"] = "叔叔，这是什么？看着好可爱，可以送给我吗？",
            ["DialogueId"] = 50107123,
            ["GUID"] = "7D701BDE",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703CAE",
            },
        [50107124] = {
            ["Content"] = "年年招新，年年没人，与其把心思放在拉人进阁，还不如多花些时间造个惊天动地的大工程出来！",
            ["DialogueId"] = 50107124,
            ["GUID"] = "7D701C08",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703CD8",
            },
        [50107126] = {
            ["Content"] = "民以食为天，食以香为先，香……这香……香啊……香。",
            ["DialogueId"] = 50107126,
            ["GUID"] = "7D701C5C",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703D2C",
            },
        [50107127] = {
            ["Content"] = "这就是华胥风格的服饰吗？嘶……我怎么觉得穿起来哪里怪怪的呢？",
            ["DialogueId"] = 50107127,
            ["GUID"] = "7D701C86",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703D56",
            },
        [50107128] = {
            ["Content"] = "青青子衿，悠悠我心，在这苍茫人世间，难道我真就无法找到相伴一生之人？",
            ["DialogueId"] = 50107128,
            ["GUID"] = "7D701CB0",
            ["SpecialConversation"] = "该角色不怎么着调，可以跳脱一点",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703D80",
            },
        [50107129] = {
            ["Content"] = "要是我把这个人杀了……大家的反响一定很好，要是再把这个也顺便刀了……",
            ["DialogueId"] = 50107129,
            ["GUID"] = "7D701CDA",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703DAA",
            },
        [50107130] = {
            ["Content"] = "天气大好啊，等开春，去收两斤新茶泡来喝！",
            ["DialogueId"] = 50107130,
            ["GUID"] = "7D701D04",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703DD4",
            },
        [50107131] = {
            ["Content"] = "瞧见那远处的楼没？我啊，小时候曾听老人说，其实它根本不存在，都是假的！",
            ["DialogueId"] = 50107131,
            ["GUID"] = "7D701D2E",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703DFE",
            },
        [50107132] = {
            ["Content"] = "所有目光向我看齐，在场的各位，都是彻彻底底的聪明龙！聪明土！",
            ["DialogueId"] = 50107132,
            ["GUID"] = "7D701D58",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703E28",
            },
        [50107133] = {
            ["Content"] = "怎就没有愿意与我辩论之人？莫非是我过于咄咄逼人了？",
            ["DialogueId"] = 50107133,
            ["GUID"] = "7D701D82",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703E52",
            },
        [50107134] = {
            ["Content"] = "要说最为复杂的调解案……莫过于十年前的那场意外了。",
            ["DialogueId"] = 50107134,
            ["GUID"] = "7D701DAC",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703E7C",
            },
        [50107135] = {
            ["Content"] = "若是法理不通，又怎敢把评判的权利交由那劳什子人心私情？",
            ["DialogueId"] = 50107135,
            ["GUID"] = "7D701DD6",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703EA6",
            },
        [50107136] = {
            ["Content"] = "现在敲敲打打的这些木头块，那都没意思！要是放在以前，我能给你们看带劲的大家伙！",
            ["DialogueId"] = 50107136,
            ["GUID"] = "7D701E00",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703ED0",
            },
        [50107137] = {
            ["Content"] = "皎皎为何不能当香官？我偏要当这皎皎第一人！",
            ["DialogueId"] = 50107137,
            ["GUID"] = "7D701E2A",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703EFA",
            },
        [50107138] = {
            ["Content"] = "夫君莫急，你先将那筐香料放下再说，那种叶子娇贵，颠了撒了香味可要散一半呢。",
            ["DialogueId"] = 50107138,
            ["GUID"] = "7D701E54",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703F24",
            },
        [50107139] = {
            ["Content"] = "想起来了，我可都想起来了，由来巷的事儿，我可全都记着呢！",
            ["DialogueId"] = 50107139,
            ["GUID"] = "7D701E7E",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703F4E",
            },
        [50107140] = {
            ["Content"] = "飘零四杰啊……那可真是一段因为年代久远而模糊不清的故事啊……",
            ["DialogueId"] = 50107140,
            ["GUID"] = "7D701EA8",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703F78",
            },
        [50107141] = {
            ["Content"] = "高高的台上我远远地望，见笨笨的家伙建高高的台~",
            ["DialogueId"] = 50107141,
            ["GUID"] = "7D701ED2",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703FA2",
            },
        [50107142] = {
            ["Content"] = "又来了一个长鼻子家伙，诶呀诶呀，这家伙怎么看着我？",
            ["DialogueId"] = 50107142,
            ["GUID"] = "7D701EFC",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703FCC",
            },
        [50107143] = {
            ["Content"] = "都去哪里了？我要开始抓你们了哦！",
            ["DialogueId"] = 50107143,
            ["GUID"] = "7D701F26",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703FF6",
            },
        [50107144] = {
            ["Content"] = "谁家的孩子穿一身白，太素净，看着一点也不喜庆！",
            ["DialogueId"] = 50107144,
            ["GUID"] = "7D701F50",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D704020",
            },
        [50107145] = {
            ["Content"] = "此香烘制程度不够，你闻，香味还没散出来呢。",
            ["DialogueId"] = 50107145,
            ["GUID"] = "7D701F7A",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70404A",
            },
        [50107146] = {
            ["Content"] = "早跟你说了，收回来的新鲜吿苍要立即拿去晾晒，为何回回都能忘了呢？",
            ["DialogueId"] = 50107146,
            ["GUID"] = "7D701FA4",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D704074",
            },
        [50107147] = {
            ["Content"] = "落生香的原料研磨最讲究精细，一遍下来若是还有这种大颗粒，你得重新再来一遍。",
            ["DialogueId"] = 50107147,
            ["GUID"] = "7D701FCE",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70409E",
            },
        [50107148] = {
            ["Content"] = "亮哥亮哥！快来帮忙，炉子又炸了！",
            ["DialogueId"] = 50107148,
            ["GUID"] = "7D701FF8",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7040C8",
            },
        [50107149] = {
            ["Content"] = "合香是一门技术活，没你想得那么简单，配比和时间都要多加注意，制香也要顺应天时呀~",
            ["DialogueId"] = 50107149,
            ["GUID"] = "7D702022",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7040F2",
            },
        [50107150] = {
            ["Content"] = "那批香装好了吗？订货的那些人问过几回了。",
            ["DialogueId"] = 50107150,
            ["GUID"] = "7D70204C",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70411C",
            },
        [50107151] = {
            ["Content"] = "抓紧犁完这片田，就能早些回家歇息了……",
            ["DialogueId"] = 50107151,
            ["GUID"] = "7D702076",
            ["SpeakNpcId"] = 701246,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D704146",
            },
        [50107152] = {
            ["Content"] = "听说最近西郊有人借着飘零人的名头活动，不知道是打什么鬼主意。",
            ["DialogueId"] = 50107152,
            ["GUID"] = "7D7020A0",
            ["SpeakNpcId"] = 701247,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D704170",
            },
        [50107153] = {
            ["Content"] = "是小苏带回来的那位？模样俊俏，当真是位妙人~",
            ["DialogueId"] = 50107153,
            ["GUID"] = "7D7020CA",
            ["SpeakNpcId"] = 701249,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70419A",
            },
        [50107154] = {
            ["Content"] = "大哥，我们什么时候才能出山啊，天天待在这里太无聊了……",
            ["DialogueId"] = 50107154,
            ["GUID"] = "7D7020F4",
            ["SpeakNpcId"] = 701250,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7041C4",
            },
        [50107155] = {
            ["Content"] = "哼！我早说过不要随便带人回来，不然山外山迟早会暴露出去！",
            ["DialogueId"] = 50107155,
            ["GUID"] = "7D70211E",
            ["SpeakNpcId"] = 701252,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7041EE",
            },
        [50107156] = {
            ["Content"] = "机枢有什么好！听我的，剑拿着，咱俩练两手才是真的。",
            ["DialogueId"] = 50107156,
            ["GUID"] = "7D702148",
            ["SpeakNpcId"] = 701253,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D704218",
            },
        [50107157] = {
            ["Content"] = "是……新面孔……好想……好想和新面孔说说话……",
            ["DialogueId"] = 50107157,
            ["GUID"] = "7D702172",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D704242",
            },
        [50107158] = {
            ["Content"] = "打打打打打劫！要从此巷过，留下姓名来！",
            ["DialogueId"] = 50107158,
            ["GUID"] = "7D70219C",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70426C",
            },
        [50107159] = {
            ["Content"] = "我好像有一个哥哥……还有一个妹妹……但他们现在都在哪……",
            ["DialogueId"] = 50107159,
            ["GUID"] = "7D7021C6",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D704296",
            },
        [50107201] = {
            ["Content"] = "我的钱袋子呢？",
            ["DialogueId"] = 50107201,
            ["GUID"] = "7D7028AA",
            ["SpeakNpcId"] = 701113,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7028AA",
            },
        [50107202] = {
            ["Content"] = "定是那油嘴滑舌的小贩子偷的！",
            ["DialogueId"] = 50107202,
            ["GUID"] = "7D7028D4",
            ["SpeakNpcId"] = 701114,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7028D4",
            },
        [50107203] = {
            ["Content"] = "诶？怎么就是找不到呢？",
            ["DialogueId"] = 50107203,
            ["GUID"] = "7D7028FE",
            ["SpeakNpcId"] = 701115,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7028FE",
            },
        [50107204] = {
            ["Content"] = "我早跟你说了这街上有贼！",
            ["DialogueId"] = 50107204,
            ["GUID"] = "7D702928",
            ["SpeakNpcId"] = 701116,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702928",
            },
        [50107205] = {
            ["Content"] = "博山香行周年店庆！",
            ["DialogueId"] = 50107205,
            ["GUID"] = "7D702952",
            ["SpeakNpcId"] = 701118,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702952",
            },
        [50107206] = {
            ["Content"] = "我对香料品质的要求很高……",
            ["DialogueId"] = 50107206,
            ["GUID"] = "7D70297C",
            ["SpeakNpcId"] = 701119,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70297C",
            },
        [50107207] = {
            ["Content"] = "再来一批！",
            ["DialogueId"] = 50107207,
            ["GUID"] = "7D7029A6",
            ["SpeakNpcId"] = 701121,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7029A6",
            },
        [50107208] = {
            ["Content"] = "噫！好酸的果干！",
            ["DialogueId"] = 50107208,
            ["GUID"] = "7D7029D0",
            ["SpeakNpcId"] = 701122,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7029D0",
            },
        [50107209] = {
            ["Content"] = "为什么没人来试试我做的糕点呢……",
            ["DialogueId"] = 50107209,
            ["GUID"] = "7D7029FA",
            ["SpeakNpcId"] = 701123,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7029FA",
            },
        [50107210] = {
            ["Content"] = "华胥特色小吃！",
            ["DialogueId"] = 50107210,
            ["GUID"] = "7D702A24",
            ["SpeakNpcId"] = 701124,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702A24",
            },
        [50107211] = {
            ["Content"] = "欢迎试吃品尝~",
            ["DialogueId"] = 50107211,
            ["GUID"] = "7D702A4E",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702A4E",
            },
        [50107212] = {
            ["Content"] = "东市啊，大变样咯！",
            ["DialogueId"] = 50107212,
            ["GUID"] = "7D702A78",
            ["SpeakNpcId"] = 701125,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702A78",
            },
        [50107213] = {
            ["Content"] = "要不要来试试我们千绣阁里的成衣？",
            ["DialogueId"] = 50107213,
            ["GUID"] = "7D702AA2",
            ["SpeakNpcId"] = 701127,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702AA2",
            },
        [50107214] = {
            ["Content"] = "同福饭馆菜品上新……",
            ["DialogueId"] = 50107214,
            ["GUID"] = "7D702ACC",
            ["SpeakNpcId"] = 701128,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702ACC",
            },
        [50107215] = {
            ["Content"] = "香料做菜？",
            ["DialogueId"] = 50107215,
            ["GUID"] = "7D702AF6",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702AF6",
            },
        [50107216] = {
            ["Content"] = "同福饭馆的厨子发了疯！",
            ["DialogueId"] = 50107216,
            ["GUID"] = "7D702B20",
            ["SpeakNpcId"] = 701129,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702B20",
            },
        [50107217] = {
            ["Content"] = "可别忘了华胥美食的精髓是什么！",
            ["DialogueId"] = 50107217,
            ["GUID"] = "7D702B4A",
            ["SpeakNpcId"] = 701130,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702B4A",
            },
        [50107218] = {
            ["Content"] = "秀芳……不要离开我……",
            ["DialogueId"] = 50107218,
            ["GUID"] = "7D702B74",
            ["SpeakNpcId"] = 701131,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702B74",
            },
        [50107219] = {
            ["Content"] = "把翠屏雀搬来了皓京城？！",
            ["DialogueId"] = 50107219,
            ["GUID"] = "7D702B9E",
            ["SpeakNpcId"] = 701132,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702B9E",
            },
        [50107220] = {
            ["Content"] = "雀翎茗轩……",
            ["DialogueId"] = 50107220,
            ["GUID"] = "7D702BC8",
            ["SpeakNpcId"] = 701134,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702BC8",
            },
        [50107221] = {
            ["Content"] = "东市雀翎茗轩开张！",
            ["DialogueId"] = 50107221,
            ["GUID"] = "7D702BF2",
            ["SpeakNpcId"] = 701258,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702BF2",
            },
        [50107222] = {
            ["Content"] = "呜呜……龙君不公啊！",
            ["DialogueId"] = 50107222,
            ["GUID"] = "7D702C1C",
            ["SpeakNpcId"] = 701135,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702C1C",
            },
        [50107223] = {
            ["Content"] = "游船游船，十文一趟。",
            ["DialogueId"] = 50107223,
            ["GUID"] = "7D702C46",
            ["SpeakNpcId"] = 701136,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702C46",
            },
        [50107224] = {
            ["Content"] = "怎么看怎么觉得邪乎呢……",
            ["DialogueId"] = 50107224,
            ["GUID"] = "7D702C70",
            ["SpeakNpcId"] = 701137,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702C70",
            },
        [50107225] = {
            ["Content"] = "想当初咱这湖边多清净？",
            ["DialogueId"] = 50107225,
            ["GUID"] = "7D702C9A",
            ["SpeakNpcId"] = 701138,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702C9A",
            },
        [50107226] = {
            ["Content"] = "若是能把这五禽戏练好……",
            ["DialogueId"] = 50107226,
            ["GUID"] = "7D702CC4",
            ["SpeakNpcId"] = 701139,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702CC4",
            },
        [50107227] = {
            ["Content"] = "他们还真把那五禽戏当真了不成？",
            ["DialogueId"] = 50107227,
            ["GUID"] = "7D702CEE",
            ["SpeakNpcId"] = 701141,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702CEE",
            },
        [50107228] = {
            ["Content"] = "呵欠……",
            ["DialogueId"] = 50107228,
            ["GUID"] = "7D702D18",
            ["SpeakNpcId"] = 701142,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702D18",
            },
        [50107229] = {
            ["Content"] = "这皓京城还没有我说不成的媒！",
            ["DialogueId"] = 50107229,
            ["GUID"] = "7D702D42",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702D42",
            },
        [50107230] = {
            ["Content"] = "会不会……被他看出来了？",
            ["DialogueId"] = 50107230,
            ["GUID"] = "7D702D6C",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702D6C",
            },
        [50107231] = {
            ["Content"] = "咱皓京人，除了吃就是喝，没别的~",
            ["DialogueId"] = 50107231,
            ["GUID"] = "7D702D96",
            ["SpeakNpcId"] = 701143,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702D96",
            },
        [50107232] = {
            ["Content"] = "留心点别踩到路上的石子了！",
            ["DialogueId"] = 50107232,
            ["GUID"] = "7D702DC0",
            ["SpeakNpcId"] = 701145,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702DC0",
            },
        [50107233] = {
            ["Content"] = "什么？涨了这么多？",
            ["DialogueId"] = 50107233,
            ["GUID"] = "7D702DEA",
            ["SpeakNpcId"] = 701146,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702DEA",
            },
        [50107234] = {
            ["Content"] = "父亲想必在天上也是不愿看见娘亲落泪的。",
            ["DialogueId"] = 50107234,
            ["GUID"] = "7D702E14",
            ["SpeakNpcId"] = 701148,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702E14",
            },
        [50107235] = {
            ["Content"] = "现在都什么年代了……",
            ["DialogueId"] = 50107235,
            ["GUID"] = "7D702E3E",
            ["SpeakNpcId"] = 701149,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702E3E",
            },
        [50107236] = {
            ["Content"] = "这杯，我敬你！",
            ["DialogueId"] = 50107236,
            ["GUID"] = "7D702E68",
            ["SpeakNpcId"] = 701150,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702E68",
            },
        [50107237] = {
            ["Content"] = "草木深胡同……是在这里？",
            ["DialogueId"] = 50107237,
            ["GUID"] = "7D702E92",
            ["SpeakNpcId"] = 701151,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702E92",
            },
        [50107238] = {
            ["Content"] = "你说那家私房菜？",
            ["DialogueId"] = 50107238,
            ["GUID"] = "7D702EBC",
            ["SpeakNpcId"] = 701152,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702EBC",
            },
        [50107239] = {
            ["Content"] = "这小巷深处竟藏着这庖厨圣地！",
            ["DialogueId"] = 50107239,
            ["GUID"] = "7D702EE6",
            ["SpeakNpcId"] = 701153,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702EE6",
            },
        [50107240] = {
            ["Content"] = "老张啊，你那只八哥……",
            ["DialogueId"] = 50107240,
            ["GUID"] = "7D702F10",
            ["SpeakNpcId"] = 701154,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702F10",
            },
        [50107241] = {
            ["Content"] = "凡夫俗子溜凡羽俗鸟！",
            ["DialogueId"] = 50107241,
            ["GUID"] = "7D702F3A",
            ["SpeakNpcId"] = 701155,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702F3A",
            },
        [50107242] = {
            ["Content"] = "老友，这局棋，你该怎么破？",
            ["DialogueId"] = 50107242,
            ["GUID"] = "7D702F64",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702F64",
            },
        [50107243] = {
            ["Content"] = "在家里聚上一聚，打打骨牌？",
            ["DialogueId"] = 50107243,
            ["GUID"] = "7D702F8E",
            ["SpeakNpcId"] = 701157,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702F8E",
            },
        [50107244] = {
            ["Content"] = "给我回去复习功课！",
            ["DialogueId"] = 50107244,
            ["GUID"] = "7D702FB8",
            ["SpeakNpcId"] = 701158,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702FB8",
            },
        [50107245] = {
            ["Content"] = "今天翻墙出来被阿娘逮到了……",
            ["DialogueId"] = 50107245,
            ["GUID"] = "7D702FE2",
            ["SpeakNpcId"] = 701160,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702FE2",
            },
        [50107246] = {
            ["Content"] = "无由生马上要出来抓你们咯？",
            ["DialogueId"] = 50107246,
            ["GUID"] = "7D70300C",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70300C",
            },
        [50107247] = {
            ["Content"] = "真是忙到头晕眼花。",
            ["DialogueId"] = 50107247,
            ["GUID"] = "7D703036",
            ["SpeakNpcId"] = 701162,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703036",
            },
        [50107248] = {
            ["Content"] = "恐一蹬腿就要去往虞泉了！",
            ["DialogueId"] = 50107248,
            ["GUID"] = "7D703060",
            ["SpeakNpcId"] = 701163,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703060",
            },
        [50107249] = {
            ["Content"] = "奉香大典意味着什么？",
            ["DialogueId"] = 50107249,
            ["GUID"] = "7D70308A",
            ["SpeakNpcId"] = 701164,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70308A",
            },
        [50107250] = {
            ["Content"] = "莫非是填错了？",
            ["DialogueId"] = 50107250,
            ["GUID"] = "7D7030B4",
            ["SpeakNpcId"] = 701165,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7030B4",
            },
        [50107251] = {
            ["Content"] = "真是难得的清闲啊~",
            ["DialogueId"] = 50107251,
            ["GUID"] = "7D7030DE",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7030DE",
            },
        [50107252] = {
            ["Content"] = "下次记得早些来泉通司……",
            ["DialogueId"] = 50107252,
            ["GUID"] = "7D703108",
            ["SpeakNpcId"] = 701166,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703108",
            },
        [50107253] = {
            ["Content"] = "祀香阁今年额外申请了一笔经费。",
            ["DialogueId"] = 50107253,
            ["GUID"] = "7D703132",
            ["SpeakNpcId"] = 701167,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703132",
            },
        [50107254] = {
            ["Content"] = "搭台子，修香炉……",
            ["DialogueId"] = 50107254,
            ["GUID"] = "7D70315C",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70315C",
            },
        [50107255] = {
            ["Content"] = "鬼鬼祟祟的，看起来不像什么好人。",
            ["DialogueId"] = 50107255,
            ["GUID"] = "7D703186",
            ["SpeakNpcId"] = 701168,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703186",
            },
        [50107256] = {
            ["Content"] = "为何来来回回都在提西郊？",
            ["DialogueId"] = 50107256,
            ["GUID"] = "7D7031B0",
            ["SpeakNpcId"] = 701169,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7031B0",
            },
        [50107257] = {
            ["Content"] = "快给我来碗茶水！",
            ["DialogueId"] = 50107257,
            ["GUID"] = "7D7031DA",
            ["SpeakNpcId"] = 701170,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7031DA",
            },
        [50107258] = {
            ["Content"] = "不是货物？那是……翠屏雀？！",
            ["DialogueId"] = 50107258,
            ["GUID"] = "7D703204",
            ["SpeakNpcId"] = 701171,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703204",
            },
        [50107259] = {
            ["Content"] = "它到底是怎么跑出去的呢？",
            ["DialogueId"] = 50107259,
            ["GUID"] = "7D70322E",
            ["SpeakNpcId"] = 701172,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70322E",
            },
        [50107260] = {
            ["Content"] = "一切努力都付之东流了……",
            ["DialogueId"] = 50107260,
            ["GUID"] = "7D703258",
            ["SpeakNpcId"] = 701173,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703258",
            },
        [50107261] = {
            ["Content"] = "已经找到一只了？",
            ["DialogueId"] = 50107261,
            ["GUID"] = "7D703282",
            ["SpeakNpcId"] = 701174,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703282",
            },
        [50107262] = {
            ["Content"] = "咱们的绣品在皓京城里很受欢迎呢~",
            ["DialogueId"] = 50107262,
            ["GUID"] = "7D7032AC",
            ["SpeakNpcId"] = 701175,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7032AC",
            },
        [50107263] = {
            ["Content"] = "甜果只有百分之三损毁？",
            ["DialogueId"] = 50107263,
            ["GUID"] = "7D7032D6",
            ["SpeakNpcId"] = 701176,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7032D6",
            },
        [50107264] = {
            ["Content"] = "一点新意也没有。",
            ["DialogueId"] = 50107264,
            ["GUID"] = "7D703300",
            ["SpeakNpcId"] = 701177,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703300",
            },
        [50107265] = {
            ["Content"] = "现在呢就已经到了咱们皓京……",
            ["DialogueId"] = 50107265,
            ["GUID"] = "7D70332A",
            ["SpeakNpcId"] = 701178,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70332A",
            },
        [50107266] = {
            ["Content"] = "三百九十九？！",
            ["DialogueId"] = 50107266,
            ["GUID"] = "7D703354",
            ["SpeakNpcId"] = 701179,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703354",
            },
        [50107267] = {
            ["Content"] = "恁大一个皓京城！",
            ["DialogueId"] = 50107267,
            ["GUID"] = "7D70337E",
            ["SpeakNpcId"] = 701180,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70337E",
            },
        [50107268] = {
            ["Content"] = "别靠过来！",
            ["DialogueId"] = 50107268,
            ["GUID"] = "7D7033A8",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7033A8",
            },
        [50107269] = {
            ["Content"] = "水龙车我先带走了。",
            ["DialogueId"] = 50107269,
            ["GUID"] = "7D7033D2",
            ["SpeakNpcId"] = 701181,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7033D2",
            },
        [50107270] = {
            ["Content"] = "太麻烦他们了。",
            ["DialogueId"] = 50107270,
            ["GUID"] = "7D7033FC",
            ["SpeakNpcId"] = 701182,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7033FC",
            },
        [50107271] = {
            ["Content"] = "来回拉扯不嫌麻烦吗？",
            ["DialogueId"] = 50107271,
            ["GUID"] = "7D703426",
            ["SpeakNpcId"] = 701183,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703426",
            },
        [50107272] = {
            ["Content"] = "凌波疾步！",
            ["DialogueId"] = 50107272,
            ["GUID"] = "7D703450",
            ["SpeakNpcId"] = 701184,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703450",
            },
        [50107273] = {
            ["Content"] = "疯狂长苔，转动都费劲……",
            ["DialogueId"] = 50107273,
            ["GUID"] = "7D70347A",
            ["SpeakNpcId"] = 701185,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70347A",
            },
        [50107274] = {
            ["Content"] = "怎会有这多事端？",
            ["DialogueId"] = 50107274,
            ["GUID"] = "7D7034A4",
            ["SpeakNpcId"] = 701186,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7034A4",
            },
        [50107275] = {
            ["Content"] = "明法、公心、勤谨。",
            ["DialogueId"] = 50107275,
            ["GUID"] = "7D7034CE",
            ["SpeakNpcId"] = 701187,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7034CE",
            },
        [50107276] = {
            ["Content"] = "直吵得人不得安睡！",
            ["DialogueId"] = 50107276,
            ["GUID"] = "7D7034F8",
            ["SpeakNpcId"] = 701188,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7034F8",
            },
        [50107277] = {
            ["Content"] = "游船游船，十文一趟。",
            ["DialogueId"] = 50107277,
            ["GUID"] = "7D703522",
            ["SpeakNpcId"] = 701189,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703522",
            },
        [50107278] = {
            ["Content"] = "我查一下刚买的《华胥问候语录大全》。",
            ["DialogueId"] = 50107278,
            ["GUID"] = "7D70354C",
            ["SpeakNpcId"] = 701190,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70354C",
            },
        [50107279] = {
            ["Content"] = "晚上做了什么好吃的？",
            ["DialogueId"] = 50107279,
            ["GUID"] = "7D703576",
            ["SpeakNpcId"] = 701191,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703576",
            },
        [50107280] = {
            ["Content"] = "铁柱呢？铁柱为何不在？",
            ["DialogueId"] = 50107280,
            ["GUID"] = "7D7035A0",
            ["SpeakNpcId"] = 701192,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7035A0",
            },
        [50107281] = {
            ["Content"] = "灯谜会，待君赏玩！",
            ["DialogueId"] = 50107281,
            ["GUID"] = "7D7035CA",
            ["SpeakNpcId"] = 701193,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7035CA",
            },
        [50107282] = {
            ["Content"] = "妈妈我到皓京了……",
            ["DialogueId"] = 50107282,
            ["GUID"] = "7D7035F4",
            ["SpeakNpcId"] = 701194,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7035F4",
            },
        [50107283] = {
            ["Content"] = "这里面不能进去吗？",
            ["DialogueId"] = 50107283,
            ["GUID"] = "7D70361E",
            ["SpeakNpcId"] = 701195,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70361E",
            },
        [50107284] = {
            ["Content"] = "会看到白龙神君在云间遨游。",
            ["DialogueId"] = 50107284,
            ["GUID"] = "7D703648",
            ["SpeakNpcId"] = 701196,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703648",
            },
        [50107285] = {
            ["Content"] = "朝报朝报，茶不思饭不想只想看朝报。",
            ["DialogueId"] = 50107285,
            ["GUID"] = "7D703672",
            ["SpeakNpcId"] = 701198,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703672",
            },
        [50107286] = {
            ["Content"] = "凑在一起为什么完全看不懂……",
            ["DialogueId"] = 50107286,
            ["GUID"] = "7D70369C",
            ["SpeakNpcId"] = 701199,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70369C",
            },
        [50107287] = {
            ["Content"] = "主要的是感受当地的氛围，您说对不对？",
            ["DialogueId"] = 50107287,
            ["GUID"] = "7D7036C6",
            ["SpeakNpcId"] = 701200,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7036C6",
            },
        [50107288] = {
            ["Content"] = "退一万步说……",
            ["DialogueId"] = 50107288,
            ["GUID"] = "7D7036F0",
            ["SpeakNpcId"] = 701201,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7036F0",
            },
        [50107289] = {
            ["Content"] = "直接推着车撞了过来……",
            ["DialogueId"] = 50107289,
            ["GUID"] = "7D70371A",
            ["SpeakNpcId"] = 701202,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70371A",
            },
        [50107290] = {
            ["Content"] = "天地为共生，万物与我一……",
            ["DialogueId"] = 50107290,
            ["GUID"] = "7D703744",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703744",
            },
        [50107291] = {
            ["Content"] = "为人在世……",
            ["DialogueId"] = 50107291,
            ["GUID"] = "7D70376E",
            ["SpeakNpcId"] = 701203,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70376E",
            },
        [50107292] = {
            ["Content"] = "曾在学院听竹溪先生传授最后一课。",
            ["DialogueId"] = 50107292,
            ["GUID"] = "7D703798",
            ["SpeakNpcId"] = 701204,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703798",
            },
        [50107293] = {
            ["Content"] = "吵死了……",
            ["DialogueId"] = 50107293,
            ["GUID"] = "7D7037C2",
            ["SpeakNpcId"] = 701205,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7037C2",
            },
        [50107294] = {
            ["Content"] = "所谓理一……",
            ["DialogueId"] = 50107294,
            ["GUID"] = "7D7037EC",
            ["SpeakNpcId"] = 701206,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7037EC",
            },
        [50107295] = {
            ["Content"] = "五味万殊，而大同于美。",
            ["DialogueId"] = 50107295,
            ["GUID"] = "7D703816",
            ["SpeakNpcId"] = 701207,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703816",
            },
        [50107296] = {
            ["Content"] = "所以理一定是在前面的！",
            ["DialogueId"] = 50107296,
            ["GUID"] = "7D703840",
            ["SpeakNpcId"] = 701208,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703840",
            },
        [50107297] = {
            ["Content"] = "今天该轮到你执勤了吧？",
            ["DialogueId"] = 50107297,
            ["GUID"] = "7D70386A",
            ["SpeakNpcId"] = 701209,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70386A",
            },
        [50107298] = {
            ["Content"] = "放假你们都去哪玩？",
            ["DialogueId"] = 50107298,
            ["GUID"] = "7D703894",
            ["SpeakNpcId"] = 701210,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703894",
            },
        [50107299] = {
            ["Content"] = "蹴球赛咱们队还差一人！",
            ["DialogueId"] = 50107299,
            ["GUID"] = "7D7038BE",
            ["SpeakNpcId"] = 701211,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7038BE",
            },
        [50107300] = {
            ["Content"] = "可这又还能往哪里扩呢？",
            ["DialogueId"] = 50107300,
            ["GUID"] = "7D7038E8",
            ["SpeakNpcId"] = 701212,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7038E8",
            },
        [50107301] = {
            ["Content"] = "是了，来年开春便要递上辞函……",
            ["DialogueId"] = 50107301,
            ["GUID"] = "7D703912",
            ["SpeakNpcId"] = 701213,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703912",
            },
        [50107302] = {
            ["Content"] = "为何飘零人的行为不能算是一种独特的方式？",
            ["DialogueId"] = 50107302,
            ["GUID"] = "7D70393C",
            ["SpeakNpcId"] = 701214,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70393C",
            },
        [50107303] = {
            ["Content"] = "今天的辩题有趣！",
            ["DialogueId"] = 50107303,
            ["GUID"] = "7D703966",
            ["SpeakNpcId"] = 701215,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703966",
            },
        [50107304] = {
            ["Content"] = "有这闲工夫，不如多读些书！",
            ["DialogueId"] = 50107304,
            ["GUID"] = "7D703990",
            ["SpeakNpcId"] = 701216,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703990",
            },
        [50107305] = {
            ["Content"] = "椒兰村的香料自然是地道。",
            ["DialogueId"] = 50107305,
            ["GUID"] = "7D7039BA",
            ["SpeakNpcId"] = 701217,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7039BA",
            },
        [50107306] = {
            ["Content"] = "鄙人自氤园而来，与他有约。",
            ["DialogueId"] = 50107306,
            ["GUID"] = "7D7039E4",
            ["SpeakNpcId"] = 701219,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7039E4",
            },
        [50107307] = {
            ["Content"] = "你哥又回烟津渡了？",
            ["DialogueId"] = 50107307,
            ["GUID"] = "7D703A0E",
            ["SpeakNpcId"] = 701220,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703A0E",
            },
        [50107308] = {
            ["Content"] = "愿家父身体健康，百病不侵。",
            ["DialogueId"] = 50107308,
            ["GUID"] = "7D703A38",
            ["SpeakNpcId"] = 701221,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703A38",
            },
        [50107309] = {
            ["Content"] = "唔……我的愿望是，长高一点！",
            ["DialogueId"] = 50107309,
            ["GUID"] = "7D703A62",
            ["SpeakNpcId"] = 701222,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703A62",
            },
        [50107310] = {
            ["Content"] = "香官跟我说的。",
            ["DialogueId"] = 50107310,
            ["GUID"] = "7D703A8C",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703A8C",
            },
        [50107311] = {
            ["Content"] = "今年祀香阁怎得没动静了？",
            ["DialogueId"] = 50107311,
            ["GUID"] = "7D703AB6",
            ["SpeakNpcId"] = 701223,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703AB6",
            },
        [50107312] = {
            ["Content"] = "尤其是中心广场水上的那个炉子！",
            ["DialogueId"] = 50107312,
            ["GUID"] = "7D703AE0",
            ["SpeakNpcId"] = 701224,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703AE0",
            },
        [50107313] = {
            ["Content"] = "难不成真是我思维迟缓？",
            ["DialogueId"] = 50107313,
            ["GUID"] = "7D703B0A",
            ["SpeakNpcId"] = 701225,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703B0A",
            },
        [50107314] = {
            ["Content"] = "不同的香方自然作用也不相同。",
            ["DialogueId"] = 50107314,
            ["GUID"] = "7D703B34",
            ["SpeakNpcId"] = 701226,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703B34",
            },
        [50107315] = {
            ["Content"] = "祀香阁今年招了一位皎皎之民！",
            ["DialogueId"] = 50107315,
            ["GUID"] = "7D703B5E",
            ["SpeakNpcId"] = 701227,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703B5E",
            },
        [50107316] = {
            ["Content"] = "那矮冬瓜大头鱼一样的家伙……",
            ["DialogueId"] = 50107316,
            ["GUID"] = "7D703B88",
            ["SpeakNpcId"] = 701228,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703B88",
            },
        [50107317] = {
            ["Content"] = "去泉通司问过了吗？",
            ["DialogueId"] = 50107317,
            ["GUID"] = "7D703BB2",
            ["SpeakNpcId"] = 701229,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703BB2",
            },
        [50107318] = {
            ["Content"] = "几番叨扰，自己都有点过意不去了。",
            ["DialogueId"] = 50107318,
            ["GUID"] = "7D703BDC",
            ["SpeakNpcId"] = 701230,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703BDC",
            },
        [50107319] = {
            ["Content"] = "你准备回家？",
            ["DialogueId"] = 50107319,
            ["GUID"] = "7D703C06",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703C06",
            },
        [50107320] = {
            ["Content"] = "这要我们如何兢兢业业干活？",
            ["DialogueId"] = 50107320,
            ["GUID"] = "7D703C30",
            ["SpeakNpcId"] = 701231,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703C30",
            },
        [50107321] = {
            ["Content"] = "你这关节做的根本不行！",
            ["DialogueId"] = 50107321,
            ["GUID"] = "7D703C5A",
            ["SpeakNpcId"] = 701232,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703C5A",
            },
        [50107322] = {
            ["Content"] = "想学的话来机枢派报个名？",
            ["DialogueId"] = 50107322,
            ["GUID"] = "7D703C84",
            ["SpeakNpcId"] = 701233,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703C84",
            },
        [50107323] = {
            ["Content"] = "叔叔，这是什么？",
            ["DialogueId"] = 50107323,
            ["GUID"] = "7D703CAE",
            ["SpeakNpcId"] = 701234,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703CAE",
            },
        [50107324] = {
            ["Content"] = "与其把心思放在拉人进阁，还不如……",
            ["DialogueId"] = 50107324,
            ["GUID"] = "7D703CD8",
            ["SpeakNpcId"] = 701235,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703CD8",
            },
        [50107326] = {
            ["Content"] = "香……这香……香啊……香。",
            ["DialogueId"] = 50107326,
            ["GUID"] = "7D703D2C",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703D2C",
            },
        [50107327] = {
            ["Content"] = "这就是华胥风格的服饰吗？",
            ["DialogueId"] = 50107327,
            ["GUID"] = "7D703D56",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703D56",
            },
        [50107328] = {
            ["Content"] = "难道我真就无法找到相伴一生之人？",
            ["DialogueId"] = 50107328,
            ["GUID"] = "7D703D80",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703D80",
            },
        [50107329] = {
            ["Content"] = "要是我把这个人杀了……",
            ["DialogueId"] = 50107329,
            ["GUID"] = "7D703DAA",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703DAA",
            },
        [50107330] = {
            ["Content"] = "等开春，去收两斤新茶泡来喝！",
            ["DialogueId"] = 50107330,
            ["GUID"] = "7D703DD4",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703DD4",
            },
        [50107331] = {
            ["Content"] = "瞧见那远处的楼没？",
            ["DialogueId"] = 50107331,
            ["GUID"] = "7D703DFE",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703DFE",
            },
        [50107332] = {
            ["Content"] = "所有目光向我看齐！",
            ["DialogueId"] = 50107332,
            ["GUID"] = "7D703E28",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703E28",
            },
        [50107333] = {
            ["Content"] = "怎就没有愿意与我辩论之人？",
            ["DialogueId"] = 50107333,
            ["GUID"] = "7D703E52",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703E52",
            },
        [50107334] = {
            ["Content"] = "要说最为复杂的调解案……",
            ["DialogueId"] = 50107334,
            ["GUID"] = "7D703E7C",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703E7C",
            },
        [50107335] = {
            ["Content"] = "若是法理不通……",
            ["DialogueId"] = 50107335,
            ["GUID"] = "7D703EA6",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703EA6",
            },
        [50107336] = {
            ["Content"] = "这些木头块都没意思！",
            ["DialogueId"] = 50107336,
            ["GUID"] = "7D703ED0",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703ED0",
            },
        [50107337] = {
            ["Content"] = "皎皎为何不能当香官？",
            ["DialogueId"] = 50107337,
            ["GUID"] = "7D703EFA",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703EFA",
            },
        [50107338] = {
            ["Content"] = "将那筐香料放下再说……",
            ["DialogueId"] = 50107338,
            ["GUID"] = "7D703F24",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703F24",
            },
        [50107339] = {
            ["Content"] = "由来巷的事儿，我可全都记着呢！",
            ["DialogueId"] = 50107339,
            ["GUID"] = "7D703F4E",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703F4E",
            },
        [50107340] = {
            ["Content"] = "飘零四杰啊……",
            ["DialogueId"] = 50107340,
            ["GUID"] = "7D703F78",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703F78",
            },
        [50107341] = {
            ["Content"] = "笨笨的家伙建高高的台~",
            ["DialogueId"] = 50107341,
            ["GUID"] = "7D703FA2",
            ["SpeakNpcId"] = 701236,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703FA2",
            },
        [50107342] = {
            ["Content"] = "诶呀诶呀，这家伙怎么看着我？",
            ["DialogueId"] = 50107342,
            ["GUID"] = "7D703FCC",
            ["SpeakNpcId"] = 701237,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703FCC",
            },
        [50107343] = {
            ["Content"] = "我要开始抓你们了哦！",
            ["DialogueId"] = 50107343,
            ["GUID"] = "7D703FF6",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703FF6",
            },
        [50107344] = {
            ["Content"] = "谁家的孩子穿一身白？",
            ["DialogueId"] = 50107344,
            ["GUID"] = "7D704020",
            ["SpeakNpcId"] = 701239,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D704020",
            },
        [50107345] = {
            ["Content"] = "你闻，香味还没散出来呢。",
            ["DialogueId"] = 50107345,
            ["GUID"] = "7D70404A",
            ["SpeakNpcId"] = 701240,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70404A",
            },
        [50107346] = {
            ["Content"] = "收回来的新鲜吿苍要立即拿去晾晒。",
            ["DialogueId"] = 50107346,
            ["GUID"] = "7D704074",
            ["SpeakNpcId"] = 701241,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D704074",
            },
        [50107347] = {
            ["Content"] = "落生香的原料研磨最讲究精细。",
            ["DialogueId"] = 50107347,
            ["GUID"] = "7D70409E",
            ["SpeakNpcId"] = 701242,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70409E",
            },
        [50107348] = {
            ["Content"] = "快来帮忙，炉子又炸了！",
            ["DialogueId"] = 50107348,
            ["GUID"] = "7D7040C8",
            ["SpeakNpcId"] = 701243,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7040C8",
            },
        [50107349] = {
            ["Content"] = "合香是一门技术活。",
            ["DialogueId"] = 50107349,
            ["GUID"] = "7D7040F2",
            ["SpeakNpcId"] = 701244,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7040F2",
            },
        [50107350] = {
            ["Content"] = "那批香装好了吗？",
            ["DialogueId"] = 50107350,
            ["GUID"] = "7D70411C",
            ["SpeakNpcId"] = 701245,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70411C",
            },
        }
  end },
  { MinKey = 50107351, MaxKey = 51001207, Loader = function()
      return {
        [50107351] = {
            ["Content"] = "抓紧犁完这片田……",
            ["DialogueId"] = 50107351,
