            },
        [50107352] = {
            ["Content"] = "不知道是打什么鬼主意。",
            ["DialogueId"] = 50107352,
            ["GUID"] = "7D704170",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D704170",
            },
        [50107353] = {
            ["Content"] = "是小苏带回来的那位？",
            ["DialogueId"] = 50107353,
            ["GUID"] = "7D70419A",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70419A",
            },
        [50107354] = {
            ["Content"] = "天天待在这里太无聊了……",
            ["DialogueId"] = 50107354,
            ["GUID"] = "7D7041C4",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7041C4",
            },
        [50107355] = {
            ["Content"] = "我早说过不要随便带人回来！",
            ["DialogueId"] = 50107355,
            ["GUID"] = "7D7041EE",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7041EE",
            },
        [50107356] = {
            ["Content"] = "剑拿着，咱俩练两手才是真的。",
            ["DialogueId"] = 50107356,
            ["GUID"] = "7D704218",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D704218",
            },
        [50107357] = {
            ["Content"] = "好想……好想和新面孔说说话……",
            ["DialogueId"] = 50107357,
            ["GUID"] = "7D704242",
            ["SpeakNpcId"] = 701255,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D704242",
            },
        [50107358] = {
            ["Content"] = "打打打打打劫！",
            ["DialogueId"] = 50107358,
            ["GUID"] = "7D70426C",
            ["SpeakNpcId"] = 701256,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70426C",
            },
        [50107359] = {
            ["Content"] = "我好像有一个哥哥……",
            ["DialogueId"] = 50107359,
            ["GUID"] = "7D704296",
            ["SpeakNpcId"] = 701257,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D704296",
            },
        [50107401] = {
            ["Content"] = "父亲向来放不下娘亲，想必在天上也是不愿看见娘亲落泪的。",
            ["DialogueId"] = 50107401,
            ["GUID"] = "7D70497A",
            ["SpeakNpcId"] = 701148,
            },
        [50107501] = {
            ["Content"] = "此屋地势偏低，又在避阳潮湿处，看这情况，要是再来个几场大雨，恐怕就要出问题……",
            ["DialogueId"] = 50107501,
            ["GUID"] = "7D7059E2",
            ["SpeakNpcId"] = 701147,
            },
        [51000001] = {
            ["Content"] = "（接受）",
            ["ContentFR"] = "Accepter",
            ["DialogueId"] = 51000001,
            ["GUID"] = "7FAC53AA",
            ["NextDialogue"] = 51005311,
            },
        [51000002] = {
            ["Content"] = "（拒绝）",
            ["ContentFR"] = "(Refuser)",
            ["DialogueId"] = 51000002,
            ["GUID"] = "7FAC53D4",
            ["Scripts"] = "SetOutport{FinishType{\"Fail\"}}",
            },
        [51000101] = {
            ["Content"] = "嗯，今晚就煮奶油蘑菇浓汤吧……啊呀？可爱的孩子。",
            ["ContentFR"] = "Hmm, ce soir je vais préparer une bonne crème de champignons... Oh ? Mais quel adorable enfant que voilà.",
            ["DialogueId"] = 51000101,
            ["GUID"] = "7FAC6412",
            ["NextDialogue"] = 51000102,
            ["SpeakNpcId"] = 700020,
            },
        [51000102] = {
            ["Content"] = "（老妇人用她的大手重重地拍了拍你的脑袋，又捏了捏你的脸。她过分的热情甚至让你感到有些手足无措。）",
            ["ContentFR"] = "La vieille femme t’empoigne la tête dans sa large main avant de te pincer la joue. Son enthousiasme débordant te laisse presque {性别:déconcerté|déconcertée}.",
            ["DialogueId"] = 51000102,
            ["GUID"] = "7FAC643C",
            ["NextDialogue"] = 51000103,
            },
        [51000103] = {
            ["Content"] = "来，喝了这碗奶油蘑菇汤！婶婶这是丹流城带来的手艺，你肯定没见识过。",
            ["ContentFR"] = "Tiens, bois donc cette soupe ! C’est une recette de ma ville natale, Rougerive. Je parie que tu n’as jamais goûté à ça.",
            ["DialogueId"] = 51000103,
            ["GUID"] = "7FAC6466",
            ["NextDialogue"] = 51000104,
            ["SpeakNpcId"] = 700020,
            },
        [51000104] = {
            ["Content"] = "（老妇人不由分说，将一碗热汤端到你面前，你总觉得下一秒，她就要掰着你的脑袋强行灌下去了——）",
            ["ContentFR"] = "Sans attendre ton avis, elle pose devant toi un bol fumant. Tu as presque l’impression qu’elle va t’attraper par la nuque pour t’obliger à avaler la première cuillerée—",
            ["DialogueId"] = 51000104,
            ["GUID"] = "7FAC6490",
            ["NextOptions"] = {
                [1] = 510001041,
                [2] = 510001042,
                },
            ["bForbidSkipOptions"] = true,
            },
        [51000105] = {
            ["Content"] = "（香浓的菌类汤汁伴随着奶油的甘甜温润了你的喉咙，你感到异常舒适。）",
            ["ContentFR"] = "La richesse du bouillon crémeux et parfumé aux champignons glisse dans ta gorge, apportant une chaleur réconfortante.",
            ["DialogueId"] = 51000105,
            ["GUID"] = "7FAC64BA",
            ["NextDialogue"] = 51000106,
            },
        [51000106] = {
            ["Content"] = "怎么样。莎莉婶婶是不会骗你的，哈哈。",
            ["ContentFR"] = "Alors ? Je ne t’ai pas menti, hein ! Tante Sally ne déçoit jamais, haha !",
            ["DialogueId"] = 51000106,
            ["GUID"] = "7FAC64E4",
            ["NextDialogue"] = 51000108,
            ["SpeakNpcId"] = 700020,
            },
        [51000107] = {
            ["Content"] = "不懂事的小鬼！不知道什么是好东西。",
            ["ContentFR"] = "{性别:Petit ingrat|Petite ingrate} ! Tu ne sais pas reconnaître les bonnes choses quand elles te sont offertes.",
            ["DialogueId"] = 51000107,
            ["GUID"] = "7FAC650E",
            ["NextDialogue"] = 51000108,
            ["SpeakNpcId"] = 700020,
            },
        [51000108] = {
            ["Content"] = "夫人还是个年轻姑娘的时候就开始喝我煮的汤，已经快四十年了啦。",
            ["ContentFR"] = "Sa Seigneurie boit ma soupe depuis qu’elle est toute jeune fille. Voilà bientôt quarante ans que ça dure.",
            ["DialogueId"] = 51000108,
            ["GUID"] = "7FAC6538",
            ["NextDialogue"] = 51000109,
            ["SpeakNpcId"] = 700020,
            },
        [51000109] = {
            ["Content"] = "……唉，夫人！也不知道她那病还能不能好。",
            ["ContentFR"] = "... Hélas... Dame Hilin... Je me demande si sa santé s’améliorera un jour.",
            ["DialogueId"] = 51000109,
            ["GUID"] = "7FAC6562",
            ["NextDialogue"] = 51000110,
            ["SpeakNpcId"] = 700020,
            },
        [51000110] = {
            ["Content"] = "（老妇人眼睛里洋溢的笑容逐渐消退，取而代之的是闪烁的泪花。）",
            ["ContentFR"] = "Le sourire qui illuminait ses yeux se fane doucement, remplacé par l’éclat humide des larmes.",
            ["DialogueId"] = 51000110,
            ["GUID"] = "7FAC658C",
            ["NextOptions"] = {
                [1] = 510001101,
                },
            },
        [51000111] = {
            ["Content"] = "是啊，一天不如一天……唉，可她放着丹流城不呆，非得跑到这种冰天雪地的地方来，我怎么也拦不住。",
            ["ContentFR"] = "Oui... son état empire de jour en jour. Mais elle a refusé de rester à Rougerive, et s’est obstinée à venir vivre dans ces contrées glacées. Rien n’a pu la retenir.",
            ["DialogueId"] = 51000111,
            ["GUID"] = "7FAC65B6",
            ["NextDialogue"] = 51000112,
            ["SpeakNpcId"] = 700020,
            },
        [51000112] = {
            ["Content"] = "她还惦记着四十年前那件事，天天在大街上托人打听，还不让我掺和。",
            ["ContentFR"] = "Elle ressasse sans cesse un vieux souvenir, remontant à quarante ans... Chaque jour, elle interroge les passants, et me défend d’intervenir.",
            ["DialogueId"] = 51000112,
            ["GUID"] = "7FAC65E0",
            ["NextDialogue"] = 51000190,
            ["SpeakNpcId"] = 700020,
            },
        [51000113] = {
            ["Content"] = "好了，婶婶我要继续忙活啦！",
            ["ContentFR"] = "Bon ! Tante Sally doit retourner à ses fourneaux !",
            ["DialogueId"] = 51000113,
            ["GUID"] = "7FAC660A",
            ["NextDialogue"] = 51000114,
            ["SpeakNpcId"] = 700020,
            },
        [51000114] = {
            ["Content"] = "（一位在打听某件事的夫人……如果遇见的话，或许可以留意一下。）",
            ["ContentFR"] = "Elle a mentionné une dame à la recherche de quelque chose... Si jamais tu la croises, il serait sage de tendre l’oreille.",
            ["DialogueId"] = 51000114,
            ["GUID"] = "7FAC6634",
            },
        [51000190] = {
            ["Content"] = "我管不了她的心病，只能天天变着花样煮不同口味的汤，希望至少让她身子好受一些。",
            ["ContentFR"] = "Je ne peux rien contre ses blessures du cœur. Alors je varie mes recettes, espérant qu’au moins sa santé s’en trouve un peu soulagée.",
            ["DialogueId"] = 51000190,
            ["GUID"] = "7FAC72AC",
            ["NextDialogue"] = 51000113,
            ["SpeakNpcId"] = 700020,
            },
        [51000201] = {
            ["Content"] = "希望今晚的奶油蘑菇浓汤能让夫人舒服一点儿……啊呀？你回来了，孩子。",
            ["ContentFR"] = "J’espère que la crème de champignons préparée ce soir réchauffera un peu le cœur de Madame.",
            ["DialogueId"] = 51000201,
            ["GUID"] = "7FAC747A",
            ["NextDialogue"] = 51000202,
            ["SpeakNpcId"] = 700020,
