            ["SpeakNpcId"] = 200003,
            },
        [51001312] = {
            ["Content"] = "冰湖城的人啊，无论是谁，说的话你只信一半就好。",
            ["ContentFR"] = "Petit conseil, à Givrelac, peu importe qui parle, ne crois jamais plus de la moitié de ce qu’il dit.",
            ["DialogueId"] = 51001312,
            ["GUID"] = "7FAD2AC0",
            ["NextDialogue"] = 51001315,
            ["SpeakNpcId"] = 200003,
            },
        [51001313] = {
            ["Camera"] = "-189.380859,-54.21875,122.534668,0.000015,3.499987,-5.919168,35.000008,1.5,false,Disable,1.2",
            ["Content"] = "别算了啊，你不试试怎么知道——",
            ["ContentFR"] = "Mais enfin, comment tu peux savoir si tu n’essaies pas...",
            ["DialogueId"] = 51001313,
            ["GUID"] = "7FAD2AEA",
            ["NextDialogue"] = 51001314,
            ["Scripts"] = "PlayAnimation{_delay{0.5},ActorId{700014},AnimationId{\"Disagree\"},Duration{1}}",
            ["SpeakNpcId"] = 700014,
            ["TalkActionId"] = {
                [1] = "700014:Talk01_Start",
                [2] = "100001:Think_End",
                },
            },
        [51001314] = {
            ["Camera"] = "35.446289,521.132324,214.651123,0.000094,-12.499997,-89.999947,45.0,696.082092,false,Manual,5.0",
            ["Content"] = "不错嘛，看来你还保持着最基本的戒心。",
            ["ContentFR"] = "Pas mal. Tu as encore un minimum de bon sens, ça rassure.",
            ["DialogueId"] = 51001314,
            ["GUID"] = "7FAD2B14",
            ["LookAt"] = {
                [1] = "700014:n(200003)",
                [2] = "100001:n(200003)",
                },
            ["NextDialogue"] = 51001315,
