            ["SpeakNpcId"] = 200003,
            },
        [51001315] = {
            ["Camera"] = "32.993408,156.229492,158.578613,0.000122,-1.500244,-80.195831,35.0,250.869797,false,Manual,5.0",
            ["Content"] = "你你、你想干什么！怎么还挡着别人做生意？",
            ["ContentFR"] = "Toi ! Qu’est-ce que tu veux encore ? Tu n’as pas mieux à faire que de saboter mon commerce ?",
            ["DialogueId"] = 51001315,
            ["GUID"] = "7FAD2B3E",
            ["LookAt"] = {
                [1] = "200003:n(700014)",
                },
            ["NextDialogue"] = 51001316,
            ["SpeakNpcId"] = 700014,
            ["TalkActionId"] = {
                [1] = "700014:Angry01_Start",
                },
            },
        [51001316] = {
            ["Camera"] = "108.244629,-193.245605,185.203125,0.000066,-10.700194,101.210106,35.000008,250.869797,false,Manual,5.0",
            ["Content"] = "别误会，我对你的买卖没什么兴趣，我来找你是要和你谈谈另一件事。",
            ["ContentFR"] = "Ne t’y trompe pas, ton commerce ne m’intéresse pas. Si je viens, c’est pour une autre affaire.",
            ["DialogueId"] = 51001316,
            ["GUID"] = "7FAD2B68",
            ["NextDialogue"] = 51001317,
            ["Scripts"] = "PlayAnimation{_delay{0.5},ActorId{200003},AnimationId{\"Disagree\"},Duration{1}}",
            ["SpeakNpcId"] = 200003,
            ["TalkActionId"] = {
                [1] = "200003:Talk03_End",
                [2] = "700014:Angry01_End",
                },
            ["TurnTo"] = {
                [1] = "100001:p(-30)",
                },
            },
        [51001317] = {
            ["Content"] = "最近总有人冒用我的名字到处贩卖劣质的假货，说什么“这是水仙平原推出的新品”啦，“在水仙平原的吧台上被一抢而光，想喝都喝不到”啦……",
            ["ContentFR"] = "Depuis quelque temps, certains vendent de la camelote sous mon nom. Ils prétendent que c’est la nouvelle « spécialité des Asphodèles », ou que « ça s’arrache au comptoir, même pas le temps d’y goûter ».",
            ["DialogueId"] = 51001317,
            ["GUID"] = "7FAD2B92",
            ["NextDialogue"] = 51001318,
            ["Scripts"] = "PlayAnimation{_delay{3},ActorId{200003},AnimationId{\"Explain01_End\"},Duration{1}}",
            ["SpeakNpcId"] = 200003,
            ["TalkActionId"] = {
                [1] = "200003:Explain01_Start",
                },
            },
        [51001318] = {
            ["Content"] = "你也知道，做生意讲究的无非就是个信誉，酒水的质量关乎水仙平原的脸面，我总不能任由他人到处抹黑。",
            ["ContentFR"] = "Or, dans les affaires, tout repose sur la réputation. La qualité de nos boissons, c’est l’image des Asphodèles. Je ne peux pas laisser des escrocs la salir.",
            ["DialogueId"] = 51001318,
            ["GUID"] = "7FAD2BBC",
            ["NextDialogue"] = 51001319,
            ["SpeakNpcId"] = 200003,
            ["TalkActionId"] = {
                [1] = "200003:Talk03_Start",
                },
            },
        [51001319] = {
            ["Camera"] = "32.993408,156.229492,158.578613,0.000122,-1.500244,-80.195831,35.0,250.869797,false,Manual,5.0",
            ["Content"] = "这、这……这和我有什么关系？我可没工夫多管你的闲事！",
            ["ContentFR"] = "Et... Et qu’est-ce que ça a à voir avec moi ? J’ai pas le temps de régler tes histoires !",
            ["DialogueId"] = 51001319,
            ["GUID"] = "7FAD2BE6",
            ["NextDialogue"] = 51001320,
            ["Scripts"] = "PlayAnimation{_delay{3},ActorId{700014},AnimationId{\"Sigh_End\"},Duration{1}}",
            ["SpeakNpcId"] = 700014,
            ["TalkActionId"] = {
                [1] = "700014:Sigh_Start",
                },
            },
        [51001320] = {
            ["Content"] = "让开让开，我要走了，你不做生意我还得做呢。",
            ["ContentFR"] = "Allez, dégage, moi j’ai un commerce à faire tourner !",
            ["DialogueId"] = 51001320,
            ["GUID"] = "7FAD2C10",
            ["NextDialogue"] = 51001321,
            ["SpeakNpcId"] = 700014,
            ["TalkActionId"] = {
                [1] = "700014:Confident_Start",
                },
            },
        [51001321] = {
            ["Camera"] = "108.244629,-193.245605,185.203125,0.000066,-10.700194,101.210106,35.000008,250.869797,false,Manual,5.0",
            ["Content"] = "走？就在不久前水仙平原拒绝与你合作的时候，我让人保留了一份你售卖的酒水样本，你猜怎么样？",
            ["ContentFR"] = "Pas si vite. Quand les Asphodèles ont refusé ton offre, j’ai fait garder un échantillon de ta marchandise. Devine quoi ?",
            ["DialogueId"] = 51001321,
            ["GUID"] = "7FAD2C3A",
            ["NextDialogue"] = 51001322,
            ["SpeakNpcId"] = 200003,
            },
        [51001322] = {
            ["Content"] = "你带来的货品和市面上那些冒充水仙平原的假货成分一模一样。这恐怕不仅仅是巧合这么简单吧？",
            ["ContentFR"] = "Tes bouteilles ont exactement la même composition que ces contrefaçons. Tu crois vraiment que c’est un hasard ?",
            ["DialogueId"] = 51001322,
            ["GUID"] = "7FAD2C64",
            ["NextDialogue"] = 51001323,
            ["SpeakNpcId"] = 200003,
            },
        [51001323] = {
            ["Camera"] = "-209.837891,-298.262207,123.758301,0.000147,1.099674,42.806149,35.000008,408.143951,false,Manual,5.0",
            ["Content"] = "什么意思！你少血口喷人！我我我、我怎么可能卖假货！你就是怕我的酒抢了你的老主顾，才、才在这里胡说八道！",
            ["ContentFR"] = "Qu’est-ce que tu insinues ?! Tu mens ! Moi, vendre des faux ?! Tu racontes ça juste parce que tu crains que ma gnôle te pique tes clients !",
            ["DialogueId"] = 51001323,
            ["GUID"] = "7FAD2C8E",
            ["NextOptions"] = {
                [1] = 510013231,
                [2] = 510013232,
                },
            ["Scripts"] = "PARA{\
\
CameraMoveTo{_delay{5},TargetPosition{\"87.344482,-123.555176,125.176514,0.000141,5.699588,170.405472,35.000008,177.462952,false,Manual,5.0\"},duration{0}},\
MoveTo{_delay{6},ActorId{200003},TargetPoint{\"PDien1\"},MoveSpeed{10},Visibility{\"Hide\"}},\
TurnTo{_delay{6},TurnToDescription{\"700014:p(60)\"}},\
LookAt{_delay{6},LookAtDescription{\"100001:n(700014)\"}},\
LookAt{_delay{7},LookAtDescription{\"100001:n(100001)\"}},\
PlayAnimation{_delay{7.2},ActorId{100001},AnimationId{\"Think_Start\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 700014,
            ["TalkActionId"] = {
                [1] = "700014:Angry01_Start",
                },
            ["bForbidSkipOptions"] = true,
            },
        [51001324] = {
            ["Camera"] = "-126.292969,-236.144531,121.561768,0.000212,4.098496,38.002239,35.0,288.862579,false,Manual,5.0",
            ["Content"] = "什么假酒？骂谁卖假酒？我算看明白了，你们两个就是一丘之貉，在这里颠倒黑白……",
            ["ContentFR"] = "Faux alcool ?! Tu traites mes produits de faux ?! J’ai compris. Vous êtes de mèche {性别:tous|toutes} les deux, à me salir exprès !",
            ["DialogueId"] = 51001324,
            ["GUID"] = "7FAD2CB8",
            ["LookAt"] = {
                [1] = "700014:n(100001)",
                },
            ["NextDialogue"] = 51001325,
            ["SpeakNpcId"] = 700014,
            },
        [51001325] = {
            ["Camera"] = "186.59668,149.714844,103.179443,0.000225,1.098103,-121.993439,35.0,286.170746,false,Manual,5.0",
            ["Content"] = "好！那我就让你看看这是不是假货！",
            ["ContentFR"] = "Très bien ! Je vais vous prouver que c’est pas du faux !",
            ["DialogueId"] = 51001325,
            ["FinalCamera"] = "202.597412,139.721191,94.749023,0.000225,1.098103,-121.993439,35.0,166.090637,false,Manual,5.0",
            ["GUID"] = "7FAD2CE2",
            ["NextDialogue"] = 51001327,
            ["SpeakNpcId"] = 700014,
            ["TalkActionId"] = {
                [1] = "700014:Talk02_Start",
                },
            ["ToFinalCameraBlendTime"] = 5,
            },
        [51001326] = {
            ["Camera"] = "-126.292969,-236.144531,121.561768,0.000212,4.098496,38.002239,35.0,288.862579,false,Manual,5.0",
            ["Content"] = "喝……喝就喝，谁怕谁啊？",
            ["ContentFR"] = "Boire ? ... Très bien ! Je vais lui montrer !",
            ["DialogueId"] = 51001326,
            ["GUID"] = "7FAD2D0C",
            ["LookAt"] = {
                [1] = "700014:n(100001)",
                },
            ["NextDialogue"] = 51001327,
            ["SpeakNpcId"] = 700014,
            },
        [51001327] = {
            ["Content"] = "（迪恩双手抱住一桶酒，仰头痛饮。）",
            ["ContentFR"] = "Dean saisit un tonneau à deux mains et se met à boire à grandes gorgées.",
            ["DialogueId"] = 51001327,
            ["GUID"] = "7FAD2D36",
            ["IsBlack"] = 1,
            ["LookAt"] = {
                [1] = "200003:n(700014)",
                [2] = "100001:n(700014)",
                },
            ["NextDialogue"] = 51001328,
            ["Scripts"] = "MoveTo{ActorId{200003},TargetPoint{\"PDien1\"},MoveSpeed{100},Visibility{\"Show\"}}",
            },
        [51001328] = {
            ["Camera"] = "-58.997803,-300.757812,211.441162,0.000378,-35.900509,52.402233,35.000008,288.862579,false,Manual,5.0",
            ["Content"] = "（可不等迪恩喝完，他仿佛就像是被人打了一拳，身形一晃重重砸在地上，洒在地上的液体仍然散发着浓郁的气味。）",
            ["ContentFR"] = "Mais avant même d’avoir fini, son corps vacille comme frappé d’un coup de poing. Il s’effondre lourdement, tandis que le liquide renversé empeste la pièce.",
            ["DialogueId"] = 51001328,
            ["FinalCamera"] = "-163.664062,-436.681641,303.508057,0.000378,-35.900513,52.404461,35.000008,288.862579,false,Manual,5.0",
            ["GUID"] = "7FAD2D60",
            ["LookAt"] = {
                [1] = "700014:n(700014)",
                },
            ["NextOptions"] = {
                [1] = 510013281,
                },
            ["TalkActionId"] = {
                [1] = "700014:Onground02",
                [2] = "100001:Think_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            },
        [51001329] = {
            ["Camera"] = "-139.912598,-187.989746,131.374023,0.00013,0.499936,50.203888,35.0,272.58197,false,Manual,5.0",
            ["Content"] = "我说过，冰湖城可不是那种人人安居乐业的好地方，想要在这里站稳脚跟处处都得留个心眼儿。",
            ["ContentFR"] = "Je l’avais dit, Givrelac n’est pas une cité paisible. Ici, il faut toujours garder l’œil ouvert si tu veux survivre.",
            ["DialogueId"] = 51001329,
            ["GUID"] = "7FAD2D8A",
            ["LookAt"] = {
                [1] = "200003:n(100001)",
                [2] = "100001:n(200003)",
                },
            ["NextDialogue"] = 51001330,
            ["SpeakNpcId"] = 200003,
            ["TurnTo"] = {
                [1] = "100001:p(30)",
                },
            },
        [51001330] = {
            ["Content"] = "唉，要是就这么放着不管他的小命可就不保了，还是先差人把他送进医院，再和他清算总账吧。",
            ["ContentFR"] = "Hélas... si on le laisse là, il risque d’y passer. Autant le faire conduire à l’hôpital. Ensuite, je réglerai mes comptes avec lui.",
            ["DialogueId"] = 51001330,
            ["GUID"] = "7FAD2DB4",
            ["NextDialogue"] = 51001331,
            ["SpeakNpcId"] = 200003,
            },
        [51001331] = {
            ["Content"] = "还有，虽然不像迪恩这么“实惠”，但如果你想喝点一分钱一分货的酒，水仙平原随时欢迎你。",
            ["ContentFR"] = "Et si un jour tu veux boire autre chose que la \"bonne affaire\" de Dean, les Asphodèles t’accueilleront toujours. Chez nous, la qualité vaut son prix.",
            ["DialogueId"] = 51001331,
            ["GUID"] = "7FAD2DDE",
            ["SpeakNpcId"] = 200003,
            },
        [51001332] = {
            ["Content"] = "要说哪的酒最好，还得是水仙平原啊。",
            ["ContentFR"] = "Le meilleur alcool de la région ? C’est bien sûr aux Asphodèles.",
            ["DialogueId"] = 51001332,
            ["GUID"] = "7FAD2E08",
            ["NextDialogue"] = 51001333,
            ["SpeakNpcId"] = 790009,
            ["TalkActionId"] = {
                [1] = "790009:Talk02_Start",
                },
            },
        [51001333] = {
            ["Content"] = "这里的酒气味醇香，口味丰满，最难能可贵的是入口绵甜干净，回味悠长。",
            ["ContentFR"] = "Ici, le parfum est enivrant, le goût riche et rond. Et surtout... une douceur en bouche, un arrière-goût qui s’attarde longtemps.",
            ["DialogueId"] = 51001333,
            ["GUID"] = "7FAD2E32",
            ["NextDialogue"] = 51001334,
            ["SpeakNpcId"] = 790009,
            },
        [51001334] = {
            ["Content"] = "正所谓好酒是这世上最勾心的情人啊……不行，我得再来一杯……",
            ["ContentFR"] = "On dit que le bon vin est le plus cruel des amants... ah, il m’en faut encore un verre...",
            ["DialogueId"] = 51001334,
            ["GUID"] = "7FAD2E5C",
            ["SpeakNpcId"] = 790009,
            ["TalkActionId"] = {
                [1] = "790009:Talk02_End",
                },
            },
        [51001335] = {
            ["Content"] = "你不知道吧，水仙平原最厉害的地方可不止有这儿的饮品。",
            ["ContentFR"] = "Tu crois que les Asphodèles, c’est juste pour les boissons ? Détrompe-toi.",
            ["DialogueId"] = 51001335,
            ["GUID"] = "7FAD2E86",
            ["NextDialogue"] = 51001336,
            ["SpeakNpcId"] = 790010,
            ["TalkActionId"] = {
                [1] = "790010:Talk03_Start",
                },
            },
        [51001336] = {
            ["Content"] = "在水仙平原，你根本就不用担心被卷进醉汉一时兴起的茬架，或者被不知道哪来的疯子打得头破血流……",
            ["ContentFR"] = "Ici, tu n’as pas à craindre d’être embarqué dans une bagarre d’ivrognes, ni de te faire cogner par un fou sorti de nulle part.",
            ["DialogueId"] = 51001336,
            ["GUID"] = "7FAD2EB0",
            ["NextDialogue"] = 51001337,
            ["SpeakNpcId"] = 790010,
            },
        [51001337] = {
            ["Content"] = "要知道这可是卡米拉的地盘，只要提起她的名字，哈，看谁还敢闹事。",
            ["ContentFR"] = "C’est le territoire de Camilla. Son nom suffit à faire taire les fauteurs de trouble.",
            ["DialogueId"] = 51001337,
            ["GUID"] = "7FAD2EDA",
            ["SpeakNpcId"] = 790010,
            ["TalkActionId"] = {
                [1] = "790010:Talk03_End",
                },
            },
        [51001338] = {
            ["Content"] = "呜呜……呜呜呜……",
            ["ContentFR"] = "<I>Snif... snif snif...</>",
            ["DialogueId"] = 51001338,
            ["GUID"] = "7FAD2F04",
            ["NextDialogue"] = 51001339,
            ["SpeakNpcId"] = 790011,
            ["TalkActionId"] = {
                [1] = "790011:Sigh_Start",
                },
            },
        [51001339] = {
            ["Content"] = "爱！你告诉我什么是爱的滋味？是我加入卡米拉后援会时的欣喜若狂？还是听到她解散后援会话语时的心碎……",
            ["ContentFR"] = "L’amour... quel goût a-t-il vraiment ? Était-ce l’extase quand j’ai rejoint le Fan Club de Camilla ? Ou bien le chagrin écrasant quand j’ai appris qu’elle l’avait dissous ?",
            ["DialogueId"] = 51001339,
            ["GUID"] = "7FAD2F2E",
            ["NextDialogue"] = 51001340,
            ["SpeakNpcId"] = 790011,
            },
        [51001340] = {
            ["Content"] = "呜呜……只有卡米拉大人的微笑才能将我这破碎的心重新粘连！",
            ["ContentFR"] = "<I>Snif...</> seul le sourire de Dame Camilla pourra recoller les morceaux de mon cœur brisé !",
            ["DialogueId"] = 51001340,
            ["GUID"] = "7FAD2F58",
            ["SpeakNpcId"] = 790011,
            ["TalkActionId"] = {
                [1] = "790011:Sigh_End",
                },
            },
        [51001401] = {
            ["Content"] = "“下雨了，妈妈的花被浇坏了，所以天空在水坑里赔给妈妈无数朵小花。”",
            ["ContentFR"] = "« Sous la pluie, les fleurs de maman se sont fanées... Alors le ciel a semé de petites fleurs dans les flaques, pour lui présenter ses excuses. »",
            ["DialogueId"] = 51001401,
            ["GUID"] = "7FAD395A",
            ["NextDialogue"] = 51001402,
            ["SpeakNpcId"] = 700017,
            ["TalkActionId"] = {
                [1] = "700017:Explain02_Start",
                },
            },
        [51001402] = {
            ["Content"] = "——您知道吗，这首诗叫做《道歉》，是我六岁的学生写的。",
            ["ContentFR"] = "Vous savez ? Ce petit poème s’intitule <I>Excuses</>, et il a été écrit par l’un de mes élèves... il n’a que six ans.",
            ["DialogueId"] = 51001402,
            ["GUID"] = "7FAD3984",
            ["NextOptions"] = {
                [1] = 510014021,
                [2] = 510014022,
                [3] = 510014023,
                },
            ["SpeakNpcId"] = 700017,
            ["TalkActionId"] = {
                [1] = "700017:Explain02_End",
                },
            ["bForbidSkipOptions"] = true,
            },
        [51001403] = {
            ["Content"] = "（桑尼身边的孩子们衣着华丽，像是群贵族出身的孩子。）",
            ["ContentFR"] = "Autour de Sunny, les enfants portent des vêtements élégants : à n’en pas douter, ils sont issus de familles nobles.",
            ["DialogueId"] = 51001403,
            ["GUID"] = "7FAD39AE",
            ["NextDialogue"] = 51001404,
            },
        [51001404] = {
            ["Content"] = "哈哈，不瞒您说，像这样的诗还有很多，我也经常会被他们的奇思妙想打动。",
            ["ContentFR"] = "Haha, pour tout vous dire, ce n’est pas le seul poème de ce genre. Leur créativité me surprend toujours autant.",
            ["DialogueId"] = 51001404,
            ["GUID"] = "7FAD39D8",
            ["NextDialogue"] = 51001405,
            ["SpeakNpcId"] = 700017,
            ["TalkActionId"] = {
                [1] = "700017:Explain01_Start",
                },
            },
        [51001405] = {
            ["Content"] = "我始终觉得天马行空的创造力与想象力——这才是一个孩子最珍贵的东西。",
            ["ContentFR"] = "J’ai toujours pensé qu’une imagination débordante et une créativité sans limite... c’est ce qu’il y a de plus précieux chez un enfant.",
            ["DialogueId"] = 51001405,
            ["GUID"] = "7FAD3A02",
            ["NextDialogue"] = 51001406,
            ["SpeakNpcId"] = 700017,
            ["TalkActionId"] = {
                [1] = "700017:Explain01_End",
                },
            },
        [51001406] = {
            ["Content"] = "只不过对贵族而言，我这样的老师是最不称职的。",
            ["ContentFR"] = "Mais pour les nobles, une enseignante comme moi est sans doute la moins compétente qu’on puisse trouver.",
            ["DialogueId"] = 51001406,
            ["GUID"] = "7FAD3A2C",
            ["NextOptions"] = {
                [1] = 510014061,
                },
            ["RestartTag"] = 51001406,
            ["SpeakNpcId"] = 700017,
            ["bForbidSkipOptions"] = true,
            },
        [51001407] = {
            ["Content"] = "啊，上课时间要到了，抱歉不能再耽误了。",
            ["ContentFR"] = "Oh, l’heure du cours approche, je ne peux pas m’attarder davantage.",
            ["DialogueId"] = 51001407,
            ["GUID"] = "7FAD3A56",
            ["NextDialogue"] = 51001408,
            ["SpeakNpcId"] = 700017,
            },
        [51001408] = {
            ["Content"] = "（桑尼看了一眼时间，示意后匆忙离开了。）",
            ["ContentFR"] = "Sunny jette un coup d’œil à sa montre, s’excuse d’un signe de tête et s’éloigne en hâte.",
            ["DialogueId"] = 51001408,
            ["GUID"] = "7FAD3A80",
            ["SpeakNpcId"] = 700017,
            },
        [51001409] = {
            ["Content"] = "哈哈，多谢你的肯定，我从来都没有后悔过这个决定，哪怕我将失去这份工作。",
            ["ContentFR"] = "Haha... merci pour vos paroles. Je n’ai jamais regretté mon choix, même si cela devait me coûter mon emploi.",
            ["DialogueId"] = 51001409,
            ["GUID"] = "7FAD3AAA",
            ["NextDialogue"] = 51001410,
            ["SpeakNpcId"] = 700017,
            ["TalkActionId"] = {
                [1] = "700017:Agree",
                },
            },
        [51001410] = {
            ["Content"] = "在这之后，我的孩子们就不得不走上整日背诵《帝国律法》或者钻研如何通过军团考核的路了。",
            ["ContentFR"] = "Après mon départ, mes élèves devront se consacrer à la récitation des Lois Impériales et à la préparation des examens de la Légion.",
            ["DialogueId"] = 51001410,
            ["GUID"] = "7FAD3AD4",
            ["NextDialogue"] = 51001411,
            ["SpeakNpcId"] = 700017,
            },
        [51001411] = {
            ["Content"] = "这是最后一课，我得告诉他们：无论将要面对的现实如何残酷与无趣，我会为他们的梦而骄傲，永远。",
            ["ContentFR"] = "C’est ma dernière leçon. Je dois leur dire que, peu importe la dureté ou la monotonie de la réalité qu’ils auront à affronter... je serai toujours fière de leurs rêves.",
            ["DialogueId"] = 51001411,
            ["GUID"] = "7FAD3AFE",
            ["NextDialogue"] = 51001490,
            ["SpeakNpcId"] = 700017,
            ["TalkActionId"] = {
                [1] = "700083:Think_End",
                [2] = "700084:Think_End",
                [3] = "700085:Confident_End",
                },
            },
        [51001412] = {
            ["Content"] = "当然！我得到了世上最好的东西！",
            ["ContentFR"] = "Bien sûr ! J’ai reçu le plus beau cadeau du monde !",
            ["DialogueId"] = 51001412,
            ["GUID"] = "7FAD3B28",
            ["NextDialogue"] = 51001413,
            ["SpeakNpcId"] = 700017,
            ["TalkActionId"] = {
                [1] = "700017:Agree",
                },
            },
        [51001413] = {
            ["Content"] = "“老师说我是天上的星星，她只是海上的倒影。",
            ["ContentFR"] = "« Ma professeure dit que je suis une étoile dans le ciel, et qu’elle n’est que mon reflet dans la mer. »",
            ["DialogueId"] = 51001413,
            ["GUID"] = "7FAD3B52",
            ["NextDialogue"] = 51001414,
            ["SpeakNpcId"] = 700017,
            ["TalkActionId"] = {
                [1] = "700017:Explain01_Start",
                },
            },
        [51001414] = {
            ["Content"] = "可天和海离了一万米，这样不好。",
            ["ContentFR"] = "« Mais entre le ciel et la mer, il y a dix mille mètres... Ce n’est pas bien. »",
            ["DialogueId"] = 51001414,
            ["GUID"] = "7FAD3B7C",
            ["NextDialogue"] = 51001415,
            ["SpeakNpcId"] = 700017,
            },
        [51001415] = {
            ["Content"] = "所以我说：看！流星！”",
            ["ContentFR"] = "Alors j’ai dit : « Regarde ! Une étoile filante ! »",
            ["DialogueId"] = 51001415,
            ["GUID"] = "7FAD3BA6",
            ["NextDialogue"] = 51001416,
            ["SpeakNpcId"] = 700017,
            ["TalkActionId"] = {
                [1] = "700017:Explain01_End",
                },
            },
        [51001416] = {
            ["Content"] = "——您知道吗，这首诗叫做《见面》，是我六岁的学生写的。",
            ["ContentFR"] = "Vous savez ? Ce petit poème s’intitule <I>Rencontre</>, et il a été écrit par l’un de mes élèves de six ans.",
            ["DialogueId"] = 51001416,
            ["GUID"] = "7FAD3BD0",
            ["SpeakNpcId"] = 700017,
            },
        [51001417] = {
            ["Content"] = "那几个孩子最近在做什么呢，该长高了吧。",
            ["ContentFR"] = "Je me demande ce que font ces enfants, maintenant... Ils ont sûrement bien grandi.",
            ["DialogueId"] = 51001417,
            ["GUID"] = "7FAD3BFA",
            ["SpeakNpcId"] = 700017,
            },
        [51001490] = {
            ["Content"] = "（随着桑尼课程的结束，孩子们挥着小手和老师说了再见，桑尼微笑着注视孩子们离开的背影）",
            ["ContentFR"] = "À la fin du cours, les enfants agitent leurs petites mains pour dire au revoir. Sunny les regarde s’éloigner, un sourire attendri aux lèvres.",
            ["DialogueId"] = 51001490,
            ["GUID"] = "7FAD47F4",
            ["NextOptions"] = {
                [1] = 510014901,
                [2] = 510014902,
                },
            ["Scripts"] = "PARA{\
MoveTo{ActorId{700083},MoveSpeed{150},TargetPoint{\"Point_Sangni_nearby_YNF01\"},Visibility{\"Hide\"}},\
MoveTo{ActorId{700084},MoveSpeed{150},TargetPoint{\"Point_Sangni_nearby_YNF02\"},Visibility{\"Hide\"}},\
MoveTo{ActorId{700085},MoveSpeed{150},TargetPoint{\"Point_Sangni_nearby_YNM01\"},Visibility{\"Hide\"}}\
}",
            ["bForbidSkipOptions"] = true,
            },
        [51001501] = {
            ["Content"] = "欸……血渍怎么都擦不掉啊。",
            ["ContentFR"] = "Argh... pourquoi ces taches de sang ne veulent-elles pas partir ?",
            ["DialogueId"] = 51001501,
            ["GUID"] = "7FAD49C2",
            ["NextDialogue"] = 51001502,
            ["SpeakNpcId"] = 700067,
            ["TalkActionId"] = {
                [1] = "700067:Sigh_Start",
                },
            },
        [51001502] = {
            ["Content"] = "再弄不干净就又要挨打挨骂了。",
            ["ContentFR"] = "Si je ne nettoie pas ça, je vais encore me faire frapper et insulter...",
            ["DialogueId"] = 51001502,
            ["GUID"] = "7FAD49EC",
            ["SpeakNpcId"] = 700067,
            ["TalkActionId"] = {
                [1] = "700067:Sigh_End",
                },
            ["TalkOptions"] = {
                [1] = 510015021,
                [2] = 510015022,
                [3] = 510015023,
                },
            },
        [51001503] = {
            ["Content"] = "你说什么？",
            ["ContentFR"] = "Quoi ? Qu’est-ce que tu racontes ?",
            ["DialogueId"] = 51001503,
            ["GUID"] = "7FAD4A16",
            ["NextDialogue"] = 51001504,
            ["SpeakNpcId"] = 700067,
            },
        [51001504] = {
            ["Content"] = "哎呦，我根本没心思听你说话，你等我擦完再说。",
            ["ContentFR"] = "Pff... je n’ai pas la tête à discuter. Attends que j’aie fini de nettoyer.",
            ["DialogueId"] = 51001504,
            ["GUID"] = "7FAD4A40",
            ["NextDialogue"] = 51001505,
            ["SpeakNpcId"] = 700067,
            },
        [51001505] = {
            ["Content"] = "（男人艰难地推着粗糙的抹布，一遍又一遍地擦拭着，终于在快筋疲力竭的时候擦净了血渍。）",
            ["ContentFR"] = "L’homme frotte avec acharnement, poussant la serpillière rêche d’un geste épuisé. Ce n’est qu’au bord de l’effondrement qu’il parvient enfin à faire disparaître la tache.",
            ["DialogueId"] = 51001505,
            ["GUID"] = "7FAD4A6A",
            ["NextDialogue"] = 51001506,
            },
        [51001506] = {
            ["Content"] = "呼，刚才那两个人打得太激烈了，血溅得到处都是，太难擦了。",
            ["ContentFR"] = "Pfiou... Ces deux-là se sont battus avec une violence inouïe. Il y avait du sang partout... quelle horreur à nettoyer.",
            ["DialogueId"] = 51001506,
            ["GUID"] = "7FAD4A94",
            ["NextDialogue"] = 51001507,
            ["SpeakNpcId"] = 700067,
            ["TalkActionId"] = {
                [1] = "700067:Talk01_Start",
                },
            },
        [51001507] = {
            ["Content"] = "还是那种一击毙命的好收拾，或者那种用药的，不会流什么血。",
            ["ContentFR"] = "C’est plus facile quand c’est une exécution nette, ou avec du poison... Au moins, il n’y a presque pas de sang.",
            ["DialogueId"] = 51001507,
            ["GUID"] = "7FAD4ABE",
            ["SpeakNpcId"] = 700067,
            ["TalkActionId"] = {
                [1] = "700067:Talk01_End",
                },
            ["TalkOptions"] = {
                [1] = 510015071,
                },
            },
        [51001508] = {
            ["Content"] = "哪来的闲人偏要讲闲话，站着说话不腰疼，管好你自己吧！",
            ["ContentFR"] = "Et alors ? Facile de faire la morale quand on n’est pas à ma place. Occupe-toi de tes affaires.",
            ["DialogueId"] = 51001508,
            ["GUID"] = "7FAD4AE8",
            ["SpeakNpcId"] = 700067,
            },
        [51001509] = {
            ["Content"] = "我有什么办法，地脏了就要擦，擦不好就要挨打挨骂。",
            ["ContentFR"] = "Qu’est-ce que tu veux que j’y fasse ? Quand c’est sale, il faut nettoyer. Et si ce n’est pas bien fait, c’est coups et insultes.",
            ["DialogueId"] = 51001509,
            ["GUID"] = "7FAD4B12",
            ["NextDialogue"] = 51001510,
            ["SpeakNpcId"] = 700067,
            ["TalkActionId"] = {
                [1] = "700067:Sigh_Start",
                },
            },
        [51001510] = {
            ["Content"] = "一开始我还同情他们，可是根本同情不过来，我自己都要被打死了，哪能管那么多！",
            ["ContentFR"] = "Au début, j’avais de la peine pour eux... mais on ne peut pas tout supporter. J’essaie déjà de rester en vie, alors le reste...",
            ["DialogueId"] = 51001510,
            ["GUID"] = "7FAD4B3C",
            ["NextDialogue"] = 51001511,
            ["SpeakNpcId"] = 700067,
            ["TalkActionId"] = {
                [1] = "700067:Sigh_End",
                },
            },
        [51001511] = {
            ["Content"] = "时间久了，血在我眼里也只是红色液体了，这样心里没负担，麻木点好啊，不然日子可过不下去啊……",
            ["ContentFR"] = "Avec le temps, le sang n’est plus qu’un liquide rouge. S’endurcir, c’est plus simple... sinon, la vie devient impossible.",
            ["DialogueId"] = 51001511,
            ["GUID"] = "7FAD4B66",
            ["NextDialogue"] = 51001512,
            ["SpeakNpcId"] = 700067,
            ["TalkActionId"] = {
                [1] = "700067:Explain01_Start",
                },
            },
        [51001512] = {
            ["Content"] = "不说了不说了，还有另一片地没擦呢……",
            ["ContentFR"] = "Bon, assez parlé. J’ai encore une autre zone à nettoyer...",
            ["DialogueId"] = 51001512,
            ["GUID"] = "7FAD4B90",
            ["SpeakNpcId"] = 700067,
            ["TalkActionId"] = {
                [1] = "700067:Explain01_End",
                },
            },
        [51001513] = {
            ["Content"] = "不说了不说了，还有另一片地没擦呢……",
            ["ContentFR"] = "Bon, assez parlé. J’ai encore une autre zone à nettoyer...",
            ["DialogueId"] = 51001513,
            ["GUID"] = "7FAD4BBA",
            ["SpeakNpcId"] = 700067,
            },
        [51001601] = {
            ["Content"] = "滚开！卡戎崽种！",
            ["ContentFR"] = "Dégage, sale Charon !",
            ["DialogueId"] = 51001601,
            ["GUID"] = "7FAD5A2A",
            ["NextDialogue"] = 51001602,
            ["SpeakNpcId"] = 700068,
            },
        [51001602] = {
            ["Content"] = "（面前的卡戎男人身穿破损的军装，用一双仇恨的眼睛看着来往的行人。）",
            ["ContentFR"] = "Devant toi, un homme Charon vêtu d’un uniforme en lambeaux fixe les passants d’un regard chargé de haine.",
            ["DialogueId"] = 51001602,
            ["GUID"] = "7FAD5A54",
            ["NextOptions"] = {
                [1] = 510016021,
                [2] = 510016022,
                [3] = 510016023,
                },
            ["bForbidSkipOptions"] = true,
            },
        [51001603] = {
            ["Content"] = "嘿！你干什么？欠揍吗？！",
            ["ContentFR"] = "Hé ! Qu’est-ce que tu fais ?! Tu veux te battre ou quoi ?!",
            ["DialogueId"] = 51001603,
            ["GUID"] = "7FAD5A7E",
            ["NextDialogue"] = 51001604,
            ["SpeakNpcId"] = 700068,
            },
        [51001604] = {
            ["Content"] = "你也长了一双角呢，和我们一样。",
            ["ContentFR"] = "Toi aussi, tu as des cornes... comme nous.",
            ["DialogueId"] = 51001604,
            ["GUID"] = "7FAD5AA8",
            ["NextDialogue"] = 51001608,
            ["SpeakNpcId"] = 100001,
            },
        [51001605] = {
            ["Content"] = "嚯，大圣人！你这话不如到治安署说去，让他们教教你怎么管好自己的嘴。",
            ["ContentFR"] = "Oh, {性别:quel grand saint|quelle grande sainte} tu fais ! Va donc prêcher ça au Bureau de la Sécurité, ils sauront te faire taire.",
            ["DialogueId"] = 51001605,
            ["GUID"] = "7FAD5AD2",
            ["NextDialogue"] = 51001606,
            ["SpeakNpcId"] = 700068,
            },
        [51001606] = {
            ["Content"] = "如果换成是你，治安署就会尊敬有加？",
            ["ContentFR"] = "Et tu crois vraiment qu’ils te traiteraient avec respect si tu étais à ma place ?",
            ["DialogueId"] = 51001606,
            ["GUID"] = "7FAD5AFC",
            ["NextDialogue"] = 51001608,
            ["SpeakNpcId"] = 100001,
            },
        [51001607] = {
            ["Content"] = "“也是卡戎”？在这跟谁也是呢？想和我相提并论，就你也配？",
            ["ContentFR"] = "Un Charon, moi aussi ? Tu plaisantes ? Tu crois qu’on est pareils, toi et moi ? Quelle blague !",
            ["DialogueId"] = 51001607,
            ["GUID"] = "7FAD5B26",
            ["NextDialogue"] = 51001608,
            ["SpeakNpcId"] = 700068,
            },
        [51001608] = {
            ["Content"] = "我告诉你，卡戎和卡戎不一样！",
            ["ContentFR"] = "Tu veux que je te dise ? Tous les Charons ne se ressemblent pas !",
            ["DialogueId"] = 51001608,
            ["GUID"] = "7FAD5B50",
            ["NextDialogue"] = 51001609,
            ["SpeakNpcId"] = 700068,
            },
        [51001609] = {
            ["Content"] = "老子打小就拿索拉之民的标准要求自己，从来不跟其他卡戎扎堆。你见过哪个卡戎像我这么说话？告诉你，这是标准的迪斯玛尼亚口音！",
            ["ContentFR"] = "Depuis que je suis gamin, je m’impose les standards des Solariens. Je n’ai jamais traîné avec les autres Charons. Tu en connais beaucoup, toi, des Charons qui parlent comme moi ? Je te le dis : c’est un accent dismanien parfait.",
            ["DialogueId"] = 51001609,
            ["GUID"] = "7FAD5B7A",
            ["NextDialogue"] = 51001691,
            ["SpeakNpcId"] = 700068,
            },
        [51001610] = {
            ["Content"] = "羡慕吗？这是我应得的！",
            ["ContentFR"] = "Tu es {性别:jaloux|jalouse}, hein ? C’est bien mérité !",
            ["DialogueId"] = 51001610,
            ["GUID"] = "7FAD5BA4",
            ["NextDialogue"] = 51001692,
            ["SpeakNpcId"] = 700068,
            },
        [51001611] = {
            ["Content"] = "现在懂了吗？比起你们，我更像是索拉，这就是为什么我能够成为长官，而你只能穿得破破烂烂，活脱脱一个乞丐。",
            ["ContentFR"] = "Tu comprends maintenant ? Je suis bien plus Sola que n’importe lequel d’entre vous. C’est pour ça que je suis devenu officier, pendant que toi, tu traînes en haillons comme {性别:un mendiant|une mendiante}.",
            ["DialogueId"] = 51001611,
            ["GUID"] = "7FAD5BCE",
            ["NextDialogue"] = 51001612,
            ["SpeakNpcId"] = 700068,
            },
        [51001612] = {
            ["Content"] = "行了，跟你说这么说是因为我和索拉之民一样，心地善良，就当是免费给你们上一课。去其他地方要饭去，别让我再看见你，晦气。",
            ["ContentFR"] = "Allez, assez perdu de temps. Si je discute avec toi, c’est uniquement parce que j’ai le cœur aussi noble que celui d’un Sola. Considère ça comme une leçon gratuite. Maintenant, dégage et va mendier ailleurs, je ne veux plus te voir, tu me portes malheur.",
            ["DialogueId"] = 51001612,
            ["GUID"] = "7FAD5BF8",
            ["NextOptions"] = {
                [1] = 510016121,
                },
            ["RestartTag"] = 51001612,
            ["SpeakNpcId"] = 700068,
            ["bForbidSkipOptions"] = true,
            },
        [51001613] = {
            ["Content"] = "嗯？你说什么？",
            ["ContentFR"] = "Hein ? Qu’est-ce que tu viens de dire ?",
            ["DialogueId"] = 51001613,
            ["GUID"] = "7FAD5C22",
            ["NextDialogue"] = 51001614,
            ["SpeakNpcId"] = 700068,
            },
        [51001614] = {
            ["Content"] = "我听说海伯利亚会为那些最优秀的卡戎授予一种叫做“桂冠卡戎”的荣誉。",
            ["ContentFR"] = "J’ai entendu dire qu’Hyperborea décernait un titre prestigieux, celui de Charon Couronné, aux plus méritants.",
            ["DialogueId"] = 51001614,
            ["GUID"] = "7FAD5C4C",
            ["NextDialogue"] = 51001615,
            ["SpeakNpcId"] = 100001,
            },
        [51001615] = {
            ["Content"] = "像您这样威猛、忠诚、口音标准的长官，一定拥有那个奖章吧，真想亲自看一眼啊。",
            ["ContentFR"] = "Un officier aussi vaillant, loyal et à l’accent irréprochable que toi doit forcément en avoir une. J’aimerais tellement la voir de mes propres yeux.",
            ["DialogueId"] = 51001615,
            ["GUID"] = "7FAD5C76",
            ["NextDialogue"] = 51001616,
            ["SpeakNpcId"] = 100001,
            },
        [51001616] = {
            ["Content"] = "……老子……忘带了！改天再说！",
            ["ContentFR"] = "... Je... je l’ai oubliée chez moi ! Une autre fois !",
            ["DialogueId"] = 51001616,
            ["GUID"] = "7FAD5CA0",
            ["NextDialogue"] = 51001617,
            ["SpeakNpcId"] = 700068,
            },
        [51001617] = {
            ["Content"] = "是吗，我真的好羡慕您！",
            ["ContentFR"] = "Vraiment ? Je vous admire, mon officier !",
            ["DialogueId"] = 51001617,
            ["GUID"] = "7FAD5CCA",
            ["NextDialogue"] = 51001693,
            ["SpeakNpcId"] = 100001,
            },
        [51001618] = {
            ["Content"] = "那是自然！",
            ["ContentFR"] = "Bien sûr que oui !",
            ["DialogueId"] = 51001618,
            ["GUID"] = "7FAD5CF4",
            ["NextDialogue"] = 51001619,
            ["SpeakNpcId"] = 700068,
            },
        [51001619] = {
            ["Content"] = "听说内城有一座叫做“沃彼安德”的喷泉，很有名的！",
            ["ContentFR"] = "On dit aussi qu’il y a là-bas une célèbre fontaine appelée « Mythaine »...",
            ["DialogueId"] = 51001619,
            ["GUID"] = "7FAD5D1E",
            ["NextDialogue"] = 51001620,
            ["SpeakNpcId"] = 100001,
            },
        [51001620] = {
            ["Content"] = "我这种人这辈子估计都没机会看一眼了，可以请长官告诉我，喷泉边的雕像到底是狮子还是狼吗——求求您，我真的很想长长见识！",
            ["ContentFR"] = "Je n’aurai sans doute jamais la chance d’y mettre les pieds. Dis-moi au moins, la statue près de la fontaine, c’est un lion ou un loup ? S’il te plaît, je veux vraiment savoir !",
            ["DialogueId"] = 51001620,
            ["GUID"] = "7FAD5D48",
            ["NextDialogue"] = 51001621,
            ["SpeakNpcId"] = 100001,
            },
        [51001621] = {
            ["Content"] = "我想想……是狮子。没错，狮子！",
            ["ContentFR"] = "Laisse-moi réfléchir... Oui, c’est un lion. Un lion, évidemment !",
            ["DialogueId"] = 51001621,
            ["GUID"] = "7FAD5D72",
            ["NextDialogue"] = 51001622,
            ["SpeakNpcId"] = 700068,
            },
        [51001622] = {
            ["Content"] = "长官，您是不是记错了？另一个朋友和我说……",
            ["ContentFR"] = "Officier... tu es sûr ? Un ami m’a dit que...",
            ["DialogueId"] = 51001622,
            ["GUID"] = "7FAD5D9C",
            ["NextDialogue"] = 51001623,
            ["SpeakNpcId"] = 100001,
            },
        [51001623] = {
            ["Content"] = "……不对，我昨天没睡好，脑袋疼，记岔了！现在想起来了，是狼！老子今天早上还路过那里，满意了吗？",
            ["ContentFR"] = "Ah, non, attends... Je n’ai pas bien dormi cette nuit, j’ai mal à la tête. Maintenant que j’y pense, c’est un loup ! Oui, un loup — je suis passé devant ce matin même, {性别:satisfait|satisfaite} ?",
            ["DialogueId"] = 51001623,
            ["GUID"] = "7FAD5DC6",
            ["NextDialogue"] = 51001624,
            ["SpeakNpcId"] = 700068,
            },
        [51001624] = {
            ["Content"] = "（你脸上仍然挂着崇拜的微笑，脑中回闪过很多情绪——先是愤怒，而后是不解，现在只剩下怜悯。）",
            ["ContentFR"] = "Un sourire admiratif reste figé sur ton visage, mais dans ta tête, mille émotions s’entrechoquent : d’abord la colère, puis l’incompréhension, pour ne laisser place qu’à la pitié.",
            ["DialogueId"] = 51001624,
            ["GUID"] = "7FAD5DF0",
            ["NextDialogue"] = 51001625,
            },
        [51001625] = {
            ["Content"] = "恐怕您的记性真的不太好。因为“沃彼安德”喷泉是我瞎说的，根本没有这个喷泉。",
            ["ContentFR"] = "J’ai bien peur que ta mémoire te joue vraiment des tours... Parce que la fontaine « Mythaine », je l’ai inventée. Elle n’existe pas.",
            ["DialogueId"] = 51001625,
            ["GUID"] = "7FAD5E1A",
            ["NextDialogue"] = 51001626,
            ["SpeakNpcId"] = 100001,
            },
        [51001626] = {
            ["Content"] = "你……你……小崽子你敢戏弄我——！",
            ["ContentFR"] = "Espèce de... de {性别:petit insolent|petite insolente}... ! Tu oses te moquer de moi ?!",
            ["DialogueId"] = 51001626,
            ["GUID"] = "7FAD5E44",
            ["NextDialogue"] = 51001627,
            ["SpeakNpcId"] = 700068,
            },
        [51001627] = {
            ["Content"] = "（早有防备的你轻巧地闪过了男人愤怒的拳头。）",
            ["ContentFR"] = "Ayant anticipé sa réaction, tu esquives sans peine le coup de poing qu’il t’adresse, ivre de rage.",
            ["DialogueId"] = 51001627,
            ["GUID"] = "7FAD5E6E",
            ["NextDialogue"] = 51001628,
            },
        [51001628] = {
            ["Content"] = "再见啦，长官。下次我再来问您内城的事吧。",
            ["ContentFR"] = "Au revoir, mon officier. La prochaine fois, j’espère que tu pourras encore m’apprendre des choses sur la cité intérieure.",
            ["DialogueId"] = 51001628,
            ["GUID"] = "7FAD5E98",
            ["SpeakNpcId"] = 100001,
            },
        [51001629] = {
            ["Content"] = "滚！！老子再也不想看见你！！滚远点！！！",
            ["ContentFR"] = "DÉGAGE ! Je ne veux plus jamais te voir ! DÉGAGE !",
            ["DialogueId"] = 51001629,
            ["GUID"] = "7FAD5EC2",
            ["SpeakNpcId"] = 700068,
            },
        [51001690] = {
            ["Content"] = "怎么又来老子眼前晃悠了？不是说过别让我看见你吗？",
            ["ContentFR"] = "Quoi ? Encore toi ? Je t’ai pourtant dit de déguerpir !",
            ["DialogueId"] = 51001690,
            ["GUID"] = "7FAD68C4",
            ["SpeakNpcId"] = 700068,
            },
        [51001691] = {
            ["Content"] = "我的索拉朋友都说，只听我说话，根本听不出来是卡戎还是索拉。",
            ["ContentFR"] = "Mes amis Solariens disent qu’à m’entendre, ils ne devineraient jamais que je suis un Charon. Ils disent que je parle exactement comme eux.",
            ["DialogueId"] = 51001691,
            ["GUID"] = "7FAD68EE",
            ["NextDialogue"] = 51001610,
            ["SpeakNpcId"] = 700068,
            },
        [51001692] = {
            ["Content"] = "有那么三年，我每天早上起来先念两个小时的《海伯利亚新报》，一边纠正口音，一边看看又是哪里的卡戎犯罪作奸，丢人现眼。",
            ["ContentFR"] = "Pendant trois ans, tous les matins, je lisais <I>L’Actualité d’Hyperborea</> pendant deux heures, à corriger mon accent... et à lire les horreurs commises par ces minables Charons, ces incapables que nous sommes censés être.",
            ["DialogueId"] = 51001692,
            ["GUID"] = "7FAD6918",
            ["NextDialogue"] = 51001611,
            ["SpeakNpcId"] = 700068,
            },
        [51001693] = {
            ["Content"] = "听说桂冠卡戎拥有居住在内城的资格，您一定在那里有幢富丽堂皇的庭院吧，像故事书上描写的那样——还有成群的管家和仆人！",
            ["ContentFR"] = "On raconte que les Charons Couronnés ont le droit de résider dans la cité intérieure. Tu dois sûrement y posséder un manoir splendide, comme dans les contes — avec des majordomes et des domestiques par dizaines !",
            ["DialogueId"] = 51001693,
            ["GUID"] = "7FAD6942",
            ["NextDialogue"] = 51001618,
            ["SpeakNpcId"] = 100001,
            },
        [51001701] = {
            ["Content"] = "13号管道已经在修了，我天，里面老鼠实在是太多了。",
            ["ContentFR"] = "La canalisation n° 13 est en réparation. Bon sang... il y a bien trop de rats là-dedans.",
            ["DialogueId"] = 51001701,
            ["GUID"] = "7FAD6A92",
            ["NextDialogue"] = 51001702,
            ["SpeakNpcId"] = 700069,
            ["TalkActionId"] = {
                [1] = "700069:Sigh_Start",
                },
            },
        [51001702] = {
            ["Content"] = "（达顿抬起头来，他身上臭气熏天，强烈刺鼻的味道逼得你不得不后退一步，你忍住干呕。）",
            ["ContentFR"] = "Dutton lève les yeux vers toi. Une odeur nauséabonde s’échappe de ses vêtements, si forte que tu recules instinctivement d’un pas, luttant contre la nausée.",
            ["DialogueId"] = 51001702,
            ["GUID"] = "7FAD6ABC",
            ["NextDialogue"] = 51001703,
            ["TalkActionId"] = {
                [1] = "700069:Sigh_End",
                },
            },
        [51001703] = {
            ["Content"] = "嘶，你躲什么躲，在下水道干活儿身上哪能没点味道。",
            ["ContentFR"] = "Hé ! Pourquoi tu t’éloignes ? Quand on bosse dans les égouts, c’est normal de sentir un peu fort.",
            ["DialogueId"] = 51001703,
            ["GUID"] = "7FAD6AE6",
            ["NextOptions"] = {
                [1] = 510017031,
                [2] = 510017032,
                [3] = 510017033,
                },
            ["SpeakNpcId"] = 700069,
            ["bForbidSkipOptions"] = true,
            },
        [51001704] = {
            ["Content"] = "别看我现在这样，在几年前，大多数人还是会尊敬地叫我“达顿医生”。",
            ["ContentFR"] = "Ne te fie pas à ce que tu vois. Il y a encore quelques années, la plupart des gens m’appelaient avec respect « Docteur Dutton ».",
            ["DialogueId"] = 51001704,
            ["GUID"] = "7FAD6B10",
            ["NextDialogue"] = 51001705,
            ["SpeakNpcId"] = 700069,
            },
        [51001705] = {
            ["Content"] = "你应该明白作为一个出生在贫民区的卡戎人，这个称呼有怎样特别的意义吧。",
            ["ContentFR"] = "Tu comprends sans doute ce que ce titre représentait pour un Charon né dans les taudis.",
            ["DialogueId"] = 51001705,
            ["GUID"] = "7FAD6B3A",
            ["NextDialogue"] = 51001706,
            ["SpeakNpcId"] = 700069,
            },
        [51001706] = {
            ["Content"] = "我在中心医院给数不清的卡戎人看病，甚至有贵族慕名请我问诊。",
            ["ContentFR"] = "J’ai soigné d’innombrables Charons à l’hôpital central... même des nobles faisaient le déplacement pour une consultation.",
            ["DialogueId"] = 51001706,
            ["GUID"] = "7FAD6B64",
            ["NextDialogue"] = 51001707,
            ["SpeakNpcId"] = 700069,
            ["TalkActionId"] = {
                [1] = "700069:Explain02_Start",
                },
            },
        [51001707] = {
            ["Content"] = "不信的话你可以问问年轻一辈的卡戎小孩，他们父母以前最常说的话就是让这帮孩子向我好好学习。",
            ["ContentFR"] = "Si tu ne me crois pas, demande donc aux jeunes Charons : leurs parents leur répétaient sans cesse de prendre exemple sur moi.",
            ["DialogueId"] = 51001707,
            ["GUID"] = "7FAD6B8E",
            ["NextDialogue"] = 51001708,
            ["SpeakNpcId"] = 700069,
            ["TalkActionId"] = {
                [1] = "700069:Explain02_End",
                },
            },
        [51001708] = {
            ["Content"] = "那时候我可有着不轻的洁癖呢，地砖缝但凡有一点灰尘都受不了......",
            ["ContentFR"] = "À l’époque, j’étais un vrai maniaque de la propreté... le moindre grain de poussière entre deux carreaux me rendait fou.",
            ["DialogueId"] = 51001708,
            ["GUID"] = "7FAD6BB8",
            ["NextOptions"] = {
                [1] = 510017081,
                },
            ["RestartTag"] = 51001708,
            ["SpeakNpcId"] = 700069,
            ["bForbidSkipOptions"] = true,
            },
        [51001709] = {
            ["Content"] = "我之前修理人们，现在修理管道，也没什么不同吧。",
            ["ContentFR"] = "Je réparais des gens, aujourd’hui je répare des tuyaux... au fond, ça revient au même, non ?",
            ["DialogueId"] = 51001709,
            ["GUID"] = "7FAD6BE2",
            ["NextDialogue"] = 51001710,
            ["SpeakNpcId"] = 700069,
            ["TalkActionId"] = {
                [1] = "700069:Think_Start",
                },
            },
        [51001710] = {
            ["Content"] = "（达顿笑了笑，好像有什么不算轻松的故事就这么翻了篇。）",
            ["ContentFR"] = "Dutton esquisse un sourire tranquille, comme s’il tournait sans rancune la page d’un passé douloureux.",
            ["DialogueId"] = 51001710,
            ["GUID"] = "7FAD6C0C",
            ["TalkActionId"] = {
                [1] = "700069:Think_End",
                },
            },
        [51001711] = {
            ["Content"] = "突发高危急症的行人晕倒在一个医生面前，医生大义凛然，选了抢救。",
            ["ContentFR"] = "Imagine la scène : un passant s’effondre, frappé par une urgence vitale, juste devant un médecin... et ce médecin choisit bravement de le sauver.",
            ["DialogueId"] = 51001711,
            ["GUID"] = "7FAD6C36",
            ["NextDialogue"] = 51001712,
            ["SpeakNpcId"] = 700069,
            ["TalkActionId"] = {
                [1] = "700069:Explain01_Start",
                },
            },
        [51001712] = {
            ["Content"] = "想知道结局是什么吗？先帮我拿个扳手——",
            ["ContentFR"] = "Tu veux connaître la suite ? Passe-moi plutôt cette clé à molette.",
            ["DialogueId"] = 51001712,
            ["GUID"] = "7FAD6C60",
            ["NextDialogue"] = 51001713,
            ["SpeakNpcId"] = 700069,
            },
        [51001713] = {
            ["Content"] = "他的抢救不但没能请来奇迹，来的还是巨额赔偿金，医院为了名誉只好辞退了一个员工。",
            ["ContentFR"] = "Le miracle n’a pas eu lieu. Ce qui est arrivé, c’est un procès colossal pour faute médicale. Pour préserver sa réputation, l’hôpital a dû licencier un employé.",
            ["DialogueId"] = 51001713,
            ["GUID"] = "7FAD6C8A",
            ["NextDialogue"] = 51001714,
            ["SpeakNpcId"] = 700069,
            ["TalkActionId"] = {
                [1] = "700069:Explain01_End",
                },
            },
        [51001714] = {
            ["Content"] = "谁能想到呢，他竟然除了治病救人什么都不会，所以欢迎他的只有下水管道。",
            ["ContentFR"] = "Et cet homme-là, qui ne savait rien faire d’autre que soigner... s’est retrouvé dans les égouts.",
            ["DialogueId"] = 51001714,
            ["GUID"] = "7FAD6CB4",
            ["NextDialogue"] = 51001715,
            ["SpeakNpcId"] = 700069,
            ["TalkActionId"] = {
                [1] = "700069:Sigh_Start",
                },
            },
        [51001715] = {
            ["Content"] = "好在当年怎么都没治好的洁癖，来这儿几个月就治好了。",
            ["ContentFR"] = "Au moins, ce passage ici a guéri ma vieille obsession de la propreté en quelques mois. C’est déjà ça.",
            ["DialogueId"] = 51001715,
            ["GUID"] = "7FAD6CDE",
            ["NextDialogue"] = 51001716,
            ["SpeakNpcId"] = 700069,
            ["TalkActionId"] = {
                [1] = "700069:Sigh_End",
                },
            },
        [51001716] = {
            ["Content"] = "再者说，干这活儿也不至于被饿死在街上，不过就是得还债还到进棺材喽。",
            ["ContentFR"] = "Et puis bon... ce boulot me permet de ne pas mourir de faim dans la rue. Je devrai juste rembourser mes dettes jusqu’à ce qu’on me mette en terre.",
            ["DialogueId"] = 51001716,
            ["GUID"] = "7FAD6D08",
            ["NextOptions"] = {
                [1] = 510017161,
                },
            ["SpeakNpcId"] = 700069,
            ["bForbidSkipOptions"] = true,
            },
        [51001717] = {
            ["Content"] = "（达顿转过身用扳手拧紧新换的螺丝，他甩着胳膊干得卖力又熟练，好像没听见你的问题。）",
            ["ContentFR"] = "Dutton tourne le dos et resserre consciencieusement les nouvelles vis de la canalisation. Il balance ses bras avec habitude et énergie, comme s’il n’avait même pas entendu ta question.",
            ["DialogueId"] = 51001717,
            ["GUID"] = "7FAD6D32",
            ["NextDialogue"] = 51001718,
            },
        [51001718] = {
            ["Content"] = "（只是在如轰鸣般的沉默中，你和他都已经对答案心知肚明了。）",
            ["ContentFR"] = "Dans le silence assourdissant qui suit, la réponse est pourtant évidente pour vous deux.",
            ["DialogueId"] = 51001718,
            ["GUID"] = "7FAD6D5C",
            },
        [51001719] = {
            ["Content"] = "哎呦……！里边这儿的老鼠也太多了！",
            ["ContentFR"] = "Aïe... ! Il y a vraiment trop de rats, là-dedans !",
            ["DialogueId"] = 51001719,
            ["GUID"] = "7FAD6D86",
            ["SpeakNpcId"] = 700069,
            },
        [51001801] = {
            ["Content"] = "嘿，我都听说了，你在格雷姆矿坑可是干了票大的。这么好的身手，要不要咱们一起做个委托，你拿八我拿二，怎么样？",
            ["ContentFR"] = "Eh, j’ai entendu dire que tu t’étais bien débrouillé à la Fosse de Glevum. Avec un tel talent, ça te dirait qu’on fasse un boulot ensemble ? Tu prends 80 %, je prends 20. Qu’en dis-tu ?",
            ["DialogueId"] = 51001801,
            ["GUID"] = "7FAD7AFA",
            ["NextOptions"] = {
                [1] = 510018011,
                [2] = 510018012,
                },
            ["SpeakNpcId"] = 200015,
            ["bForbidSkipOptions"] = true,
            },
        [51001802] = {
            ["Content"] = "好嘞，那我们这就出发。",
            ["ContentFR"] = "Parfait, on y va alors.",
            ["DialogueId"] = 51001802,
            ["GUID"] = "7FAD7B24",
            ["NextDialogue"] = 51001803,
            ["SpeakNpcId"] = 200015,
            ["TalkActionId"] = {
                [1] = "200015:Agree",
                },
            },
        [51001803] = {
            ["Content"] = "卡米拉，酒钱先赊着啊，等我拿到报酬就还你。",
            ["ContentFR"] = "Camilla, mets-moi ça sur ta note, je te rembourse quand j’aurai la récompense.",
            ["DialogueId"] = 51001803,
            ["GUID"] = "7FAD7B4E",
            ["LookAt"] = {
                [1] = "200015:n(200003)",
                [2] = "200003:n(200015)",
                },
            ["NextDialogue"] = 51001804,
            ["SpeakNpcId"] = 200015,
            ["TurnTo"] = {
                [1] = "200015:n(200003)",
                [2] = "200003:n(200015)",
                },
            },
        [51001804] = {
            ["Content"] = "老规矩，先把你的怀表放我这做抵押。",
            ["ContentFR"] = "Comme d’habitude, alors ta montre reste ici en garantie.",
            ["DialogueId"] = 51001804,
            ["GUID"] = "7FAD7B78",
            ["NextDialogue"] = 51001805,
            ["SpeakNpcId"] = 200003,
            },
        [51001805] = {
            ["Content"] = "没问题没问题，{nickname}，我们快去快回吧。",
            ["ContentFR"] = "Pas de souci. {nickname}, on y va et on revient vite.",
            ["DialogueId"] = 51001805,
            ["GUID"] = "7FAD7BA2",
            ["SpeakNpcId"] = 200015,
            ["TurnTo"] = {
                [1] = "200015:n(0)",
                },
            },
        [51001901] = {
            ["Content"] = "（还没推开水仙平原的门，就已能听到其中响彻的咒骂声，仿佛想让全城都来倾听他的愤怒。）",
            ["ContentFR"] = "Avant même d’entrer aux Asphodèles, tu entends déjà des jurons résonner à travers la salle, comme si toute la cité devait entendre sa colère.",
            ["DialogueId"] = 51001901,
            ["GUID"] = "7FAD8B62",
            ["NextDialogue"] = 51001902,
            },
        [51001902] = {
            ["Content"] = "你怎么还有脸活着！我真是老糊涂了，当初就不该只是把你简单赶出去！",
            ["ContentFR"] = "Tu as encore le culot de montrer ta tête ! J’ai été si stupide... j’aurais dû faire plus que te chasser !",
            ["DialogueId"] = 51001902,
            ["GUID"] = "7FAD8B8C",
            ["LookAt"] = {
                [1] = "200015:n(700047)",
                },
            ["NextDialogue"] = 51001903,
            ["SpeakNpcId"] = 700047,
            ["TalkActionId"] = {
                [1] = "700047:Angry01_Start",
                },
            },
        [51001903] = {
            ["Content"] = "顶着我们家的姓抛头露面这么多年，我寄给你的警告信都让你拿去烧炉灰了？",
            ["ContentFR"] = "Tu parades avec notre nom depuis des années... et mes lettres de mise en garde ? Tu les as brûlées ?",
            ["DialogueId"] = 51001903,
            ["GUID"] = "7FAD8BB6",
            ["NextDialogue"] = 51001904,
            ["SpeakNpcId"] = 700047,
            ["TalkActionId"] = {
                [1] = "700047:Angry01_End",
                },
            },
        [51001904] = {
            ["Content"] = "是，是，岳父大人说得对，但这个姓毕竟是过去您……",
            ["ContentFR"] = "Oui, oui... vous avez raison, mais ce nom, après tout, c’est ce que vous...",
            ["DialogueId"] = 51001904,
            ["GUID"] = "7FAD8BE0",
            ["NextDialogue"] = 51001905,
            ["SpeakNpcId"] = 200015,
            ["TalkActionId"] = {
                [1] = "200015:Shock_Start",
                },
            },
        [51001905] = {
            ["Content"] = "（威尔斯如一个犯错的孩童般低头站在一名老者面前，任由对方的手指戳打在自己身上。）",
            ["ContentFR"] = "Wells, tête baissée comme un enfant puni, reste immobile tandis que l’homme le pointe du doigt.",
            ["DialogueId"] = 51001905,
            ["GUID"] = "7FAD8C0A",
            ["NextDialogue"] = 51001906,
            },
        [51001906] = {
            ["Content"] = "别来沾边，没什么本事还学人家做狩月人，这钱、这名声是你配赚的？天天像条狗一样给人跑前跑后，内城现在都把我们威尔斯家当笑话看！",
            ["ContentFR"] = "Ferme-la ! Tu n’as aucun talent et tu prétends être un Chasseur de Phoxène ? L’argent et la renommée ? Tu ne les mérites pas ! Tu cours partout comme un chien... maintenant toute la cité intérieure prend les Wells pour une blague !",
            ["DialogueId"] = 51001906,
            ["GUID"] = "7FAD8C34",
            ["NextDialogue"] = 51001907,
            ["SpeakNpcId"] = 700047,
            ["TalkActionId"] = {
                [1] = "200015:Shock_End",
                },
            },
        [51001907] = {
            ["Content"] = "我这不是想着，要是哪天有出息了，说不定您会再考虑一下萨拉的事——",
            ["ContentFR"] = "Je pensais juste... si je réussis un jour, peut-être que vous reverrez votre jugement sur Sara et moi...",
            ["DialogueId"] = 51001907,
            ["GUID"] = "7FAD8C5E",
            ["NextDialogue"] = 51001908,
            ["SpeakNpcId"] = 200015,
            ["TalkActionId"] = {
                [1] = "200015:Explain02_Start",
                },
            },
        [51001908] = {
            ["Content"] = "你还敢提她的名字！少他**惦记了，你和我女儿，永远都没有复合的可能，永远！",
            ["ContentFR"] = "Comment oses-tu prononcer son nom ! Oublie-la ! Toi et ma fille, il n’y aura jamais de retour possible ! Jamais !",
            ["DialogueId"] = 51001908,
            ["GUID"] = "7FAD8C88",
            ["NextDialogue"] = 51001909,
            ["SpeakNpcId"] = 700047,
            ["TalkActionId"] = {
                [1] = "700047:Angry01_Start",
                },
            },
        [51001909] = {
            ["Content"] = "别怪我没警告你，你要是敢踏进内城一步，我就打断你的腿。",
            ["ContentFR"] = "Et ne dis pas que je ne t’ai pas prévenu : si tu poses un pied dans la cité intérieure, je te brise les jambes.",
            ["DialogueId"] = 51001909,
            ["GUID"] = "7FAD8CB2",
            ["NextDialogue"] = 51001910,
            ["SpeakNpcId"] = 700047,
            ["TalkActionId"] = {
                [1] = "700047:Angry01_End",
                },
            },
        [51001910] = {
            ["Content"] = "是，是……",
            ["ContentFR"] = "Oui, oui...",
            ["DialogueId"] = 51001910,
            ["GUID"] = "7FAD8CDC",
            ["NextDialogue"] = 51001911,
            ["SpeakNpcId"] = 200015,
            ["TalkActionId"] = {
                [1] = "200015:Explain02_End",
                },
            },
        [51001911] = {
            ["Content"] = "（老者看着不断点头的威尔斯气更是不打一处来，环顾四周，最后把视线落到了刚进水仙平原的你身上。）",
            ["ContentFR"] = "L’homme, voyant Wells hocher la tête sans fin, devient encore plus furieux. Son regard se pose finalement sur toi qui vient d’entrer dans les Asphodèles.",
            ["DialogueId"] = 51001911,
            ["GUID"] = "7FAD8D06",
            ["NextDialogue"] = 51001912,
            },
        [51001912] = {
            ["Content"] = "还有你，狩月人是吧，你们这种卡戎我见多了，幻想着靠狩月人扬名立万，当上桂冠卡戎？",
            ["ContentFR"] = "Et toi, Charon ? J’en ai vu des comme toi, rêvant de gloire en tant que Chasseur de Phoxène, pour ensuite espérer devenir un Charon Couronné...",
            ["DialogueId"] = 51001912,
            ["GUID"] = "7FAD8D30",
            ["NextDialogue"] = 51001990,
            ["SpeakNpcId"] = 700047,
            ["TalkActionId"] = {
                [1] = "700047:Explain01_Start",
                },
            },
        [51001913] = {
            ["Content"] = "岳父，{nickname}很有本事的，和我这种废物不一样……",
            ["ContentFR"] = "Vous avez raison... mais {nickname} est vraiment capable, pas comme moi...",
            ["DialogueId"] = 51001913,
            ["GUID"] = "7FAD8D5A",
            ["NextDialogue"] = 51001914,
            ["SpeakNpcId"] = 200015,
            },
        [51001914] = {
            ["Content"] = "费迪南特·威尔斯先生，先前是你们二人的私事，我不便插嘴。但无缘无故打扰我们的客人，水仙平原可就要送客了。",
            ["ContentFR"] = "Ferdinand Wells, ce qui s’est passé entre vous deux ne me regarde pas. Mais si vous continuez à déranger nos invités pour rien, je devrai vous faire sortir.",
            ["DialogueId"] = 51001914,
            ["GUID"] = "7FAD8D84",
            ["NextDialogue"] = 51001915,
            ["SpeakNpcId"] = 200003,
            ["TalkActionId"] = {
                [1] = "200003:Talk03_Start",
                },
            },
        [51001915] = {
            ["Content"] = "（坐在柜台前的卡米拉吐出一抹烟圈，轻描淡写的话语在空旷的水仙平原中却显得无比洪亮。）",
            ["ContentFR"] = "Camilla, assise derrière le comptoir, souffle un anneau de fumée. Ses paroles désinvoltes résonnent pourtant avec force dans la salle vide.",
            ["DialogueId"] = 51001915,
            ["GUID"] = "7FAD8DAE",
            ["NextDialogue"] = 51001991,
            ["TalkActionId"] = {
                [1] = "200003:Talk03_End",
                },
            },
        [51001916] = {
            ["Content"] = "哼。",
            ["ContentFR"] = "<I>Hmpf.</>",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 51001916,
            ["GUID"] = "7FAD8DD8",
            ["LookAt"] = {
                [1] = "200015:n(700047)",
                },
            ["NextDialogue"] = 51001917,
            ["SpeakNpcId"] = 700047,
            ["TalkActionId"] = {
                [1] = "700047:Disagree",
                },
            },
        [51001917] = {
            ["Content"] = "（老者没听清你说什么，继续指着威尔斯的鼻子咒骂，也许应该过一会儿，等他冷静一点再说。）",
            ["ContentFR"] = "Le vieil homme continue de pointer Wells et de jurer. Peut-être vaut-il mieux attendre qu’il se calme pour parler à nouveau.",
            ["DialogueId"] = 51001917,
            ["GUID"] = "7FAD8E02",
            },
        [51001918] = {
            ["Content"] = "……哼。",
            ["ContentFR"] = "<I>... Hmpf.</>",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 51001918,
            ["GUID"] = "7FAD8E2C",
            ["LookAt"] = {
                [1] = "200015:n(700047)",
                },
            ["NextDialogue"] = 51001919,
            ["SpeakNpcId"] = 700047,
            ["TalkActionId"] = {
                [1] = "700047:Disagree",
                },
            },
        [51001919] = {
            ["Content"] = "（老者被你说得哑口无言，恶狠狠地回瞪一眼，摔门而出。）",
            ["ContentFR"] = "L’homme, réduit au silence par tes paroles, jette un dernier regard noir et sort en claquant la porte.",
            ["DialogueId"] = 51001919,
            ["GUID"] = "7FAD8E56",
            ["NextDialogue"] = 51001920,
            ["Scripts"] = "MoveTo{ActorId{700047},TargetPoint{\"TargetPoint_LeaveTavern\"},MoveSpeed{90},Visibility{\"Hide\"}}",
            },
        [51001920] = {
            ["Content"] = "抱歉抱歉，给大家添麻烦了。那、那个，我岳……费迪南特·威尔斯先生十几年没来过外城了。",
            ["ContentFR"] = "Désolé pour tout ce remue-ménage... Mon beau-père... Monsieur Ferdinand Wells n’était pas venu dans la cité extérieure depuis des années.",
            ["DialogueId"] = 51001920,
            ["GUID"] = "7FAD8E80",
            ["LookAt"] = {
                [1] = "200015:n(0)",
                },
            ["NextDialogue"] = 51001992,
            ["SpeakNpcId"] = 200015,
            ["TalkActionId"] = {
                [1] = "200015:Sigh_Start",
                },
            },
        [51001921] = {
            ["Content"] = "没事，要是一两句恶言就能刺激到，我们也不会站在这里。倒是听说威尔斯先生最近在做委托时受了伤，不要紧吗？",
            ["ContentFR"] = "Pas grave. Si quelques insultes pouvaient nous abattre, nous ne serions pas ici. On m’a dit que vous aviez été blessé pendant une mission. Ça va ?",
            ["DialogueId"] = 51001921,
            ["GUID"] = "7FAD8EAA",
            ["NextDialogue"] = 51001922,
            ["SpeakNpcId"] = 100001,
            },
        [51001922] = {
            ["Content"] = "小事，多亏了它，没受什么致命伤。",
            ["ContentFR"] = "Ce n’est rien. Heureusement, cette montre m’a protégé d’une blessure mortelle.",
            ["DialogueId"] = 51001922,
            ["GUID"] = "7FAD8ED4",
            ["NextDialogue"] = 51001923,
            ["SpeakNpcId"] = 200015,
            ["TalkActionId"] = {
                [1] = "200015:Explain01_Start",
                },
            },
        [51001923] = {
            ["Content"] = "（威尔斯说着从胸前取出一块精致的怀表，裂纹遍布表盘，指针夸张地朝上扭曲着，让关闭怀表的翻盖都成了一种奢望。）",
            ["ContentFR"] = "Wells sort une montre de poche finement travaillée, le cadran fissuré, les aiguilles tordues de façon exagérée, au point qu’il est devenu impossible de refermer le boîtier.",
            ["DialogueId"] = 51001923,
            ["GUID"] = "7FAD8EFE",
            ["NextOptions"] = {
                [1] = 510019231,
                [2] = 510019232,
                },
            ["TalkActionId"] = {
                [1] = "200015:Explain01_End",
                },
            ["bForbidSkipOptions"] = true,
            },
        [51001924] = {
            ["Content"] = "那是他自己做的，十几年前，没人不知道天才钟表匠陶德·威尔斯的名字。当年靠这手艺，甚至差点成为桂冠卡戎。",
            ["ContentFR"] = "Il l’a faite lui-même. Il y a dix ans, tout le monde connaissait Todd Wells, le prodige horloger. Il était presque devenu un Charon Couronné grâce à son talent.",
            ["DialogueId"] = 51001924,
            ["GUID"] = "7FAD8F28",
            ["NextDialogue"] = 51001925,
            ["SpeakNpcId"] = 200003,
            ["TalkActionId"] = {
                [1] = "200003:Explain01_Start",
                },
            },
        [51001925] = {
            ["Content"] = "做工确实精良，就这么裂开了真是可惜。",
            ["ContentFR"] = "Une pièce magnifique... dommage qu’elle soit cassée.",
            ["DialogueId"] = 51001925,
            ["GUID"] = "7FAD8F52",
            ["NextDialogue"] = 51001926,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "200003:Explain01_End",
                },
            },
        [51001926] = {
            ["Content"] = "哈哈，话是这么说，其实很久以前指针就坏掉不走了，只是带身上留个念想。",
            ["ContentFR"] = "Haha, oui, mais les aiguilles étaient déjà cassées depuis longtemps. Je la garde juste comme souvenir.",
            ["DialogueId"] = 51001926,
            ["GUID"] = "7FAD8F7C",
            ["NextDialogue"] = 51001927,
            ["SpeakNpcId"] = 200015,
            ["TalkActionId"] = {
                [1] = "200015:Sigh_Start",
                },
            },
        [51001927] = {
            ["Content"] = "为什么不试着修好它呢？",
            ["ContentFR"] = "Pourquoi ne pas essayer de la réparer ?",
            ["DialogueId"] = 51001927,
            ["GUID"] = "7FAD8FA6",
            ["NextDialogue"] = 51001928,
            ["SpeakNpcId"] = 100001,
            },
        [51001928] = {
            ["Content"] = "维修用的工具和原料都被我岳父掐死，想修也没得修。",
            ["ContentFR"] = "Mon beau-père a coupé l’accès aux outils et matériaux, impossible de la réparer.",
            ["DialogueId"] = 51001928,
            ["GUID"] = "7FAD8FD0",
            ["NextDialogue"] = 51001929,
            ["SpeakNpcId"] = 200015,
            ["TalkActionId"] = {
                [1] = "200015:Sigh_End",
                },
            },
        [51001929] = {
            ["Content"] = "……没办法。不是所有东西都是你想修，你用力去修，就能修得好的。",
            ["ContentFR"] = "... Tout ne se répare pas juste parce qu’on veut et qu’on y met de la force.",
            ["DialogueId"] = 51001929,
            ["GUID"] = "7FAD8FFA",
            ["NextDialogue"] = 51001930,
            ["SpeakNpcId"] = 200015,
            ["TalkActionId"] = {
                [1] = "200015:Talk01_Start",
                },
            },
        [51001930] = {
            ["Content"] = "……",
            ["ContentFR"] = "...",
            ["DialogueId"] = 51001930,
            ["GUID"] = "7FAD9024",
            ["NextDialogue"] = 51001931,
            ["SpeakNpcId"] = 100001,
            },
        [51001931] = {
            ["Content"] = "不说这些了！刚才真是谢了啊，要不是你出来说话，我这耳朵估计都要废了。",
            ["ContentFR"] = "Bref, merci d’être intervenu. Sans toi, mes oreilles n’y auraient pas résisté.",
            ["DialogueId"] = 51001931,
            ["GUID"] = "7FAD904E",
            ["NextDialogue"] = 51001932,
            ["SpeakNpcId"] = 200015,
            ["TalkActionId"] = {
                [1] = "200015:Talk01_End",
                },
            },
        [51001932] = {
            ["Content"] = "来来，今天随便吃随便喝。我开这边的酒，你把那边几桶开了，通通我买单！",
            ["ContentFR"] = "Allez, ce soir c’est moi qui régale. Tu ouvres ces fûts là-bas, je m’occupe de ceux-ci !",
            ["DialogueId"] = 51001932,
            ["GUID"] = "7FAD9078",
            ["NextDialogue"] = 51001934,
            ["SpeakNpcId"] = 200015,
            ["TalkActionId"] = {
                [1] = "200015:Explain02_Start",
                },
            },
        [51001933] = {
            ["Content"] = "来嘛，喝，喝起来！",
            ["ContentFR"] = "Allez, bois ! À la tienne !",
            ["DialogueId"] = 51001933,
            ["GUID"] = "7FAD90A2",
            ["SpeakNpcId"] = 200015,
            },
        [51001934] = {
            ["Content"] = "……",
            ["ContentFR"] = "...",
            ["DialogueId"] = 51001934,
            ["GUID"] = "7FAD9079",
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "200015:Explain02_End",
                },
            },
        [51001935] = {
            ["Camera"] = "122.0,278.0,139.0,0.000007,0.0,-95.0,35.0,200.0,false,Manual,2.8",
            ["Content"] = "（你将面前的酒桶全部打开，转身看去，威尔斯已经挂回了熟悉的笑容，举杯畅饮了起来。）",
            ["ContentFR"] = "Tu ouvres tous les fûts, te retournes et vois Wells lever son verre, le sourire large et familier.",
            ["DialogueId"] = 51001935,
            ["FinalCamera"] = "102.0,278.0,139.0,0.000007,0.0,-95.0,35.0,350.0,false,Manual,2.8",
            ["GUID"] = "7FAD907A",
            ["Scripts"] = "TurnTo{_delay{1.5},TurnToDescription{\"100001:n(700207)\"}}",
            ["TalkActionId"] = {
                [1] = "700207:Angry01_Start",
                },
            ["ToFinalCameraBlendTime"] = 7,
            },
        [51001936] = {
            ["Content"] = "只是那欢笑之下捧着怀表的一丝落寞，恐怕也如怀表本身一样，无法被轻易修复吧。",
            ["ContentFR"] = "Pourtant, sous ce rire, ses doigts serrent la montre à gousset brisée, une pointe de mélancolie qui semble, tout comme la montre elle-même, impossible à réparer facilement.",
            ["DialogueId"] = 51001936,
            ["Duration"] = 4,
            ["GUID"] = "7FAD907B",
            },
        [51001990] = {
            ["Content"] = "告诉你们，<H>冰湖城这么多年就没出过几个活着的桂冠卡戎</>，卡戎最后，都只会消失在街角暗巷里！",
            ["ContentFR"] = "Laisse-moi te dire quelque chose. <H>Givrelac n’a pas eu beaucoup de Charons Couronnés vivants depuis des années.</> Les Charons finissent seulement par pourrir dans une ruelle sombre !",
            ["DialogueId"] = 51001990,
            ["GUID"] = "7FAD99FC",
            ["NextDialogue"] = 51001913,
            ["SpeakNpcId"] = 700047,
            ["TalkActionId"] = {
                [1] = "700047:Explain01_End",
                },
            },
        [51001991] = {
            ["Content"] = "（不知是心理作用还是真实变化，烟雾间水仙平原的温度都感觉上升了不少。）",
            ["ContentFR"] = "On a l’impression que la température de la pièce monte légèrement à cause de la fumée.",
            ["DialogueId"] = 51001991,
            ["GUID"] = "7FAD9A26",
            ["NextOptions"] = {
                [1] = 510019911,
                [2] = 510019912,
                [3] = 510019913,
                },
            ["RestartTag"] = 51001915,
            ["bForbidSkipOptions"] = true,
            },
        [51001992] = {
            ["Content"] = "老人家比较……那个，尊重传统。他说的那些话你别往心里去。",
            ["ContentFR"] = "Il est un peu... attaché aux traditions. Ne prends pas ses paroles trop à cœur.",
            ["DialogueId"] = 51001992,
            ["GUID"] = "7FAD9A50",
            ["NextDialogue"] = 51001921,
            ["SpeakNpcId"] = 200015,
            ["TalkActionId"] = {
                [1] = "200015:Sigh_End",
                },
            },
        [51002001] = {
            ["Content"] = "来往的朋友，稍微停一停脚步，给上几个银币，就能获得南国海岛隐藏的惊天秘宝——的线索。",
            ["ContentFR"] = "Amis de passage, arrêtez-vous un instant ! Contre quelques pièces, vous repartirez avec un indice menant au fabuleux trésor caché d’une île du sud !",
            ["DialogueId"] = 51002001,
            ["GUID"] = "7FAD9BCA",
            ["NextDialogue"] = 51002002,
            ["SpeakNpcId"] = 700048,
            ["TalkActionId"] = {
                [1] = "700048:Explain01_Start",
                },
            },
        [51002002] = {
            ["Content"] = "难道您真的就甘心每天面对冰冷的面包和变味的红酒吗？不如开始一场冒险，拥抱机遇，改变人生！",
            ["ContentFR"] = "Quoi, vous comptez vraiment vous contenter chaque jour de pain rassis et de vin éventé ? Lancez-vous donc dans l’aventure, saisissez votre chance, changez votre destin !",
            ["DialogueId"] = 51002002,
            ["GUID"] = "7FAD9BF4",
            ["NextDialogue"] = 51002003,
            ["SpeakNpcId"] = 700048,
            ["TalkActionId"] = {
                [1] = "700048:Explain01_End",
                },
            },
        [51002003] = {
            ["Content"] = "（眼前这位满嘴投机主义言论的老人衣着破烂，言语激昂，但是这让他看起来很不值得信任。）",
            ["ContentFR"] = "L’homme qui t’interpelle, un vieillard en haillons au ton exalté, respire l’opportunisme. Mais son assurance excessive le rend plutôt suspect.",
            ["DialogueId"] = 51002003,
            ["GUID"] = "7FAD9C1E",
            ["NextOptions"] = {
                [1] = 510020031,
                [2] = 510020032,
                [3] = 510020033,
                },
            ["bForbidSkipOptions"] = true,
            },
        [51002004] = {
            ["Content"] = "哎呀，我这不是一把老骨头，要把机会让给年轻人嘛。",
            ["ContentFR"] = "Ah, mais regardez-moi... je ne suis plus qu’un tas de vieilles guibolles. Autant laisser cette chance à la jeunesse !",
            ["DialogueId"] = 51002004,
            ["GUID"] = "7FAD9C48",
            ["NextDialogue"] = 51002005,
            ["SpeakNpcId"] = 700048,
            ["TalkActionId"] = {
                [1] = "700048:Explain01_Start",
                },
            },
        [51002005] = {
            ["Content"] = "唉，我要是你这个年纪啊，肯定就已经收拾行李准备动身了。",
            ["ContentFR"] = "Hé, si j’avais encore votre âge, j’aurais déjà empaqueté mes affaires et pris la mer !",
            ["DialogueId"] = 51002005,
            ["GUID"] = "7FAD9C72",
            ["NextDialogue"] = 51002010,
            ["SpeakNpcId"] = 700048,
            },
        [51002006] = {
            ["Content"] = "怎么？有兴趣？年轻人很会把握机会嘛。",
            ["ContentFR"] = "Tiens donc, vous êtes {性别:intéressé|intéressée} ? Vous savez reconnaître une occasion quand elle se présente.",
            ["DialogueId"] = 51002006,
            ["GUID"] = "7FAD9C9C",
            ["NextDialogue"] = 51002007,
            ["SpeakNpcId"] = 700048,
            ["TalkActionId"] = {
                [1] = "700048:Explain01_End",
                },
            },
        [51002007] = {
            ["Content"] = "我就喜欢你这样的聪明孩子，所以我确实可以免费给你透露那么一两句。",
            ["ContentFR"] = "J’aime les jeunes {性别:futés|futées} comme vous. Alors, pour vous, je peux bien lâcher un petit indice... gratuitement.",
            ["DialogueId"] = 51002007,
            ["GUID"] = "7FAD9CC6",
            ["NextDialogue"] = 51002010,
            ["SpeakNpcId"] = 700048,
            ["TalkActionId"] = {
                [1] = "700048:Agree",
                },
            },
        [51002008] = {
            ["Content"] = "你这叫什么话？还没听我说呢就说在骗人，怎么一点礼貌都没有。",
            ["ContentFR"] = "Comment pouvez-vous dire ça ? Vous ne m’avez même pas écouté ! Quelle impolitesse !",
            ["DialogueId"] = 51002008,
            ["GUID"] = "7FAD9CF0",
            ["NextDialogue"] = 51002009,
            ["SpeakNpcId"] = 700048,
            ["TalkActionId"] = {
                [1] = "700048:Disagree",
                },
            },
        [51002009] = {
            ["Content"] = "既然你觉得我是骗子，那我就要跟你说上几句了，让你开开眼界。",
            ["ContentFR"] = "Puisque vous m’accusez d’être un escroc, laissez-moi au moins vous ouvrir les yeux.",
            ["DialogueId"] = 51002009,
            ["GUID"] = "7FAD9D1A",
            ["NextDialogue"] = 51002010,
            ["SpeakNpcId"] = 700048,
            },
        [51002010] = {
            ["Content"] = "实际上啊，我不是冰湖城本地人，出生在帝国南方的一个海岛上。",
            ["ContentFR"] = "Je ne suis pas natif de Givrelac. Je suis né sur une île au sud de l’Empire.",
            ["DialogueId"] = 51002010,
            ["GUID"] = "7FAD9D44",
            ["NextDialogue"] = 51002011,
            ["SpeakNpcId"] = 700048,
            ["TalkActionId"] = {
                [1] = "700048:Explain01_Start",
                },
            },
        [51002011] = {
            ["Content"] = "我们的那个海岛啊，被一棵巨大的天之树遮盖着，一般的地图上根本找不着。",
            ["ContentFR"] = "Notre île était dominée par un immense Arbre Céleste, invisible sur la plupart des cartes.",
            ["DialogueId"] = 51002011,
            ["GUID"] = "7FAD9D6E",
            ["NextDialogue"] = 51002012,
            ["SpeakNpcId"] = 700048,
            },
        [51002012] = {
            ["Content"] = "岛上有一个隐秘的山洞，里面有一尊女神的雕像，比你见过的所有女人都要美！据说啊，这个女神的雕像的后面就藏着宝藏。",
            ["ContentFR"] = "Dans une grotte secrète, il y avait la statue d’une déesse plus belle que toutes les femmes de ce monde ! On dit que le trésor repose juste derrière elle.",
            ["DialogueId"] = 51002012,
            ["GUID"] = "7FAD9D98",
            ["NextDialogue"] = 51002013,
            ["SpeakNpcId"] = 700048,
            ["TalkActionId"] = {
                [1] = "700048:Explain01_End",
                },
            },
        [51002013] = {
            ["Content"] = "至于这个宝藏具体是什么，想继续听的话，给上几个子儿就行。",
            ["ContentFR"] = "Mais... pour savoir en quoi consiste ce trésor exactement, il faudra m’offrir quelques pièces de plus.",
            ["DialogueId"] = 51002013,
            ["GUID"] = "7FAD9DC2",
            ["NextOptions"] = {
                [1] = 510020131,
                },
            ["RestartTag"] = 51002013,
            ["SpeakNpcId"] = 700048,
            ["bForbidSkipOptions"] = true,
            },
        [51002014] = {
            ["Content"] = "（听着很像是净界岛，这家伙十有八九是个骗子，先不在他身上浪费时间了。）",
            ["ContentFR"] = "<I>Ça ressemble fort à l’Île du Purgatoire. Cet homme est sûrement un escroc. Inutile de perdre plus de temps.</>",
            ["DialogueId"] = 51002014,
            ["GUID"] = "7FAD9DEC",
            ["NextDialogue"] = 51002015,
            ["SpeakNpcId"] = 100001,
            },
        [51002015] = {
            ["Content"] = "还是算了，我的铜币还没有多到为了听个响就随便乱扔的地步。",
            ["ContentFR"] = "Laissez tomber. Je n’ai pas assez de pièces pour les jeter à la première fable venue.",
            ["DialogueId"] = 51002015,
            ["GUID"] = "7FAD9E16",
            ["SpeakNpcId"] = 100001,
            },
        [51002016] = {
            ["Content"] = "你说的这个南方岛屿，是不是附近有一棵巨大的天之树，叫做净界岛？",
            ["ContentFR"] = "<I>Cet îlot du sud... il est bien dominé par un Arbre Céleste gigantesque ? On l’appelle l’Île du Purgatoire, n’est-ce pas ?</>",
            ["DialogueId"] = 51002016,
            ["GUID"] = "7FAD9E40",
            ["NextDialogue"] = 51002017,
            ["SpeakNpcId"] = 100001,
            },
        [51002017] = {
            ["Content"] = "——！",
            ["ContentFR"] = "... !",
            ["DialogueId"] = 51002017,
            ["GUID"] = "7FAD9E6A",
            ["NextDialogue"] = 51002018,
            ["SpeakNpcId"] = 700048,
            },
        [51002018] = {
            ["Content"] = "你为什么会知道这个名字？",
            ["ContentFR"] = "Comment connais-tu ce nom ?",
            ["DialogueId"] = 51002018,
            ["GUID"] = "7FAD9E94",
            ["NextDialogue"] = 51002019,
            ["SpeakNpcId"] = 700048,
            ["TalkActionId"] = {
                [1] = "700048:Explain01_Start",
                },
            },
        [51002019] = {
            ["Content"] = "那是我曾经的家。",
            ["ContentFR"] = "C’était chez moi.",
            ["DialogueId"] = 51002019,
            ["GUID"] = "7FAD9EBE",
            ["NextDialogue"] = 51002020,
            ["SpeakNpcId"] = 100001,
            },
        [51002020] = {
            ["Content"] = "……你也是那里的人？难道那里不再阻止村民离开了吗？",
            ["ContentFR"] = "... Toi aussi tu viens de là-bas ? Attends... ils laissent désormais les villageois partir ?",
            ["DialogueId"] = 51002020,
            ["GUID"] = "7FAD9EE8",
            ["NextDialogue"] = 51002021,
            ["SpeakNpcId"] = 700048,
            ["TalkActionId"] = {
                [1] = "700048:Explain01_End",
                },
            },
        [51002021] = {
            ["Content"] = "也不瞒着你了，我二十岁的时候出海打渔，看着帝国的海岸线弯弯曲曲，像极了我在书上读到过的马鞍和城堡。",
            ["ContentFR"] = "Bon, inutile de te mentir. À vingt ans, je suis parti pêcher au large. En voyant la côte de l’Empire, sinueuse comme les châteaux et les selles de mes livres, j’ai eu un déclic.",
            ["DialogueId"] = 51002021,
            ["GUID"] = "7FAD9F12",
            ["NextDialogue"] = 51002022,
            ["SpeakNpcId"] = 700048,
            },
        [51002022] = {
            ["Content"] = "于是我没有和往常一样带着渔获回家，而是一直向东，到了海岸这一侧。只不过这边的日子和我想象中还是有点不太一样……",
            ["ContentFR"] = "Au lieu de rentrer avec ma pêche, j’ai continué vers l’est, jusqu’à atteindre ce rivage. Mais la vie ici n’était pas vraiment ce que j’avais imaginé...",
            ["DialogueId"] = 51002022,
            ["GUID"] = "7FAD9F3C",
            ["NextDialogue"] = 51002023,
            ["SpeakNpcId"] = 700048,
            },
        [51002023] = {
            ["Content"] = "唉，十几年了，现在想回去连个路费都凑不出，只能耍耍嘴皮子。",
            ["ContentFR"] = "Ça fait plus de dix ans. Et maintenant, je n’ai même plus de quoi payer le voyage du retour. Alors je me débrouille avec mon éloquence...",
            ["DialogueId"] = 51002023,
            ["GUID"] = "7FAD9F66",
            ["NextDialogue"] = 51002024,
            ["SpeakNpcId"] = 700048,
            ["TalkActionId"] = {
                [1] = "700048:Sigh_Start",
                },
            },
        [51002024] = {
            ["Content"] = "那，既然你也是从净界岛出来的，那应该知道，村子最东边那一户的人家，现在还好吗？",
            ["ContentFR"] = "Puisque tu viens de l’île aussi... dis-moi, la maison tout à l’est du village, est-ce que tu sais si ses habitants vont bien ?",
            ["DialogueId"] = 51002024,
            ["GUID"] = "7FAD9F90",
            ["NextDialogue"] = 51002025,
            ["SpeakNpcId"] = 700048,
            ["TalkActionId"] = {
                [1] = "700048:Sigh_End",
                },
            },
        [51002025] = {
            ["Content"] = "（向他讲述村子被秽兽袭击，大部分村民已经坐船逃走的场景。）",
            ["ContentFR"] = "Tu lui racontes l’attaque des Souillés et la fuite des villageois par bateau.",
            ["DialogueId"] = 51002025,
            ["GUID"] = "7FAD9FBA",
            ["NextDialogue"] = 51002026,
            ["SpeakNpcId"] = 100001,
            },
        [51002026] = {
            ["Content"] = "居然……",
            ["ContentFR"] = "Quoi... ?!",
            ["DialogueId"] = 51002026,
            ["GUID"] = "7FAD9FE4",
            ["NextDialogue"] = 51002027,
            ["SpeakNpcId"] = 700048,
            },
        [51002027] = {
            ["Content"] = "不过，听你的意思是他们都逃出来了吧，逃出来就好，逃出来就好……",
            ["ContentFR"] = "Mais... d’après toi, ils ont réussi à s’échapper ? Alors tant mieux... tant mieux...",
            ["DialogueId"] = 51002027,
            ["GUID"] = "7FADA00E",
            ["NextDialogue"] = 51002028,
            ["SpeakNpcId"] = 700048,
            ["TalkActionId"] = {
                [1] = "700048:Agree",
                },
            },
        [51002028] = {
            ["Content"] = "对了，如果你们有机会回到净界岛的话，能不能去我的老房子附近看看，有没有什么东西留下来。",
            ["ContentFR"] = "Dis, si jamais tu retournes sur l’Île du Purgatoire, pourrais-tu jeter un œil près de ma vieille maison ? Voir s’il reste quelque chose...",
            ["DialogueId"] = 51002028,
            ["GUID"] = "7FADA038",
            ["NextDialogue"] = 51002029,
            ["SpeakNpcId"] = 700048,
            },
        }
  end },
  { MinKey = 51002029, MaxKey = 51003414, Loader = function()
      return {
        [51002029] = {
            ["Content"] = "如果实在什么都找不到的话，帮我带点东西回来吧，什么都行，一片草叶也行。",
            ["ContentFR"] = "Et s’il n’y a vraiment rien, rapporte-moi n’importe quoi. Même un brin d’herbe ferait l’affaire.",
            ["DialogueId"] = 51002029,
            ["GUID"] = "7FADA062",
            ["NextDialogue"] = 51002030,
            ["SpeakNpcId"] = 700048,
            ["TalkActionId"] = {
                [1] = "700048:Explain02_Start",
                },
            },
        [51002030] = {
            ["Content"] = "好。",
            ["ContentFR"] = "D’accord.",
            ["DialogueId"] = 51002030,
            ["GUID"] = "7FADA08C",
            ["SpeakNpcId"] = 100001,
            },
        [51002031] = {
            ["Content"] = "唉，小时候想出来难得很，现在想回去又回不去……",
            ["ContentFR"] = "Ah... quand j’étais jeune, partir était si difficile, et maintenant, quand j’aimerais rentrer, je n’en ai plus la possibilité...",
            ["DialogueId"] = 51002031,
            ["GUID"] = "7FADA0B6",
            ["NextDialogue"] = 51002032,
            ["SpeakNpcId"] = 700048,
            ["TalkActionId"] = {
                [1] = "700048:Explain02_End",
                },
            },
        [51002032] = {
            ["Content"] = "再见。",
            ["ContentFR"] = "Prends soin de toi.",
            ["DialogueId"] = 51002032,
            ["GUID"] = "7FADA0E0",
            ["SpeakNpcId"] = 100001,
            },
        [51002101] = {
            ["Content"] = "这里应该就是那个布鲁内托的家了。",
            ["ContentFR"] = "Ça doit être ici, la maison de Brunetto. Voyons s’il reste quelque chose que je puisse lui rapporter.",
            ["DialogueId"] = 51002101,
            ["Duration"] = 3,
            ["GUID"] = "7FADAC32",
            ["NextDialogue"] = 51002102,
            ["SpeakNpcId"] = 100001,
            },
        [51002102] = {
            ["Content"] = "这儿有个箱子，里面会有什么能捎带给他的东西吗？",
            ["ContentFR"] = "Tiens... un coffre. Peut-être qu’il contient un souvenir à lui ramener.",
            ["DialogueId"] = 51002102,
            ["Duration"] = 4,
            ["GUID"] = "7FADAC5C",
            ["NextDialogue"] = 51002103,
            ["SpeakNpcId"] = 100001,
            },
        [51002103] = {
            ["Content"] = "可惜没看到钥匙，去附近找找看吧。",
            ["ContentFR"] = "Pas de chance, il est fermé... Allons chercher la clé dans les environs.",
            ["DialogueId"] = 51002103,
            ["Duration"] = 2.5,
            ["GUID"] = "7FADAC86",
            ["SpeakNpcId"] = 100001,
            },
        [51002104] = {
            ["Content"] = "从形状来看，就是这把钥匙了。",
            ["ContentFR"] = "Vu la forme, cette clé devrait convenir. Essayons.",
            ["DialogueId"] = 51002104,
            ["Duration"] = 2,
            ["GUID"] = "7FADAC87",
            ["SpeakNpcId"] = 100001,
            },
        [51002105] = {
            ["Camera"] = "183.0,143.319336,121.0,0.0,-0.99996,-114.999725,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "（钥匙缓缓转动，生锈的锁芯吃力地咬合着，发出刺耳的摩擦声。当箱子彻底打开，周围的秽兽也被异响吸引到了附近，拦住了你的去路。）",
            ["ContentFR"] = "La clé tourne lentement. Le barillet rouillé résiste, grinçant d’un bruit strident. Quand le couvercle s’ouvre enfin, le vacarme attire aussitôt une meute de Souillés qui te barre le passage.",
            ["DialogueId"] = 51002105,
            ["FinalCamera"] = "186.0,143.319336,121.0,0.0,-0.99996,-114.999725,35.0,100000.0,false,DoNotOverride,2.8",
