        [51002106] = {
            ["Camera"] = "-160.396484,-385.0,156.553223,0.0,-14.799763,65.201347,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "（这些秽兽并不是你的对手，但这小小的插曲让你感到了一丝熟悉，久远的回忆开始苏醒，你仿佛听到了两个小孩在这间房子前打闹的声音。）",
            ["ContentFR"] = "Les Souillés ne t’ont pas posé de réelle difficulté. Pourtant, ce bref affrontement a réveillé en toi une étrange familiarité. Un souvenir ancien refait surface : tu entends presque deux enfants se chamailler devant cette maison.",
            ["DialogueId"] = 51002106,
            ["FinalCamera"] = "-160.396484,-404.0,156.553223,0.0,-14.799763,65.201347,35.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "7FADAC89",
            ["NextDialogue"] = 51002107,
            ["TalkActionId"] = {
                [1] = "100001:Talk03_Start",
                },
            ["ToFinalCameraBlendTime"] = 7,
            },
        [51002107] = {
            ["Camera"] = "119.585938,-26.257812,128.0,-0.0,-9.999997,-145.798935,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我想起来了，小时候我和这家的小孩打过一架。名字我已经记不清了，算起来，应该是布鲁内托的孙子吧。",
            ["ContentFR"] = "Ça me revient... Quand j’étais gosse, je me suis {性别:battu|battue} avec l’enfant qui vivait ici. Son nom m’échappe... mais en y repensant, ça devait être le petit-fils de Brunetto.",
            ["DialogueId"] = 51002107,
            ["FinalCamera"] = "119.585938,-26.257812,128.0,0.0,-9.999997,-138.598923,35.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "7FADAC8A",
            ["NextDialogue"] = 51002108,
            ["Scripts"] = "TurnTo{_delay{3},TurnToDescription{\"100001:n(700211)\"}}",
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Talk03_End",
                },
            ["ToFinalCameraBlendTime"] = 7,
            },
        [51002108] = {
            ["Camera"] = "-180.842773,-670.0,18.0,0.000018,4.000004,83.599602,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "起因是什么已经想不起来了，但我还记得开打前的最后一句话是……那小鬼喊我独眼龙，我骂他是眼睛鼓鼓的大青蛙。",
            ["ContentFR"] = "Je ne sais plus ce qui avait déclenché la bagarre. Mais je me souviens encore de nos dernières piques avant d’en venir aux poings... Ce garnement m’a traité de cyclope, et moi je l’ai traité de crapaud aux yeux globuleux.",
            ["DialogueId"] = 51002108,
            ["GUID"] = "7FADAC8B",
