            ["NextDialogue"] = 51002440,
            ["SpeakNpcId"] = 700020,
            ["TalkActionId"] = {
                [1] = "700020:Explain01_End",
                },
            },
        [51002440] = {
            ["Content"] = "她下定决心，只要哈默尔来，她就打算和他一起走，无论去哪里。",
            ["ContentFR"] = "Elle était prête à tout quitter, du moment qu’Hamel venait.",
            ["DialogueId"] = 51002440,
            ["GUID"] = "51002440.0",
            ["NextOptions"] = {
                [1] = 51002441,
                },
            ["SpeakNpcId"] = 700020,
            },
        [51002441] = {
            ["Content"] = "但是哈默尔爽约了？",
            ["ContentFR"] = "Mais... il n’est jamais venu ?",
            ["DialogueId"] = 51002441,
            ["GUID"] = "51002441.0",
            ["NextDialogue"] = 51002442,
            },
        [51002442] = {
            ["Content"] = "是。希琳小姐在那里等到天亮，等来的却只有气急败坏的父亲。不久之后，她就像一件货物那样，被远嫁到了弗莱格桑行省。",
