            ["SpeakNpcId"] = 700016,
            ["TalkActionId"] = {
                [1] = "700086:Confident_End",
                [2] = "700016:Shock_Start",
                },
            },
        [51003504] = {
            ["Camera"] = "-336.324951,48.679199,108.230957,0.0,0.0,-9.40437,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "你这孩子最近怎么魂不守舍的，下次可不能这样了。",
            ["ContentFR"] = "Tu es ailleurs ces temps-ci. La prochaine fois, tâche de rester concentrée.",
            ["DialogueId"] = 51003504,
            ["GUID"] = "7FAE9260",
            ["NextDialogue"] = 510035041,
            ["SpeakNpcId"] = 700086,
            ["TalkActionId"] = {
                [1] = "700086:Sigh_Start",
                },
            },
        [51003505] = {
            ["Content"] = "唉……真无聊……不知道婆婆在做什么呢？",
            ["ContentFR"] = "Pff... c’est trop ennuyeux... Je me demande ce que Mamie est en train de faire...",
            ["DialogueId"] = 51003505,
            ["GUID"] = "7FAE928A",
            ["NextOptions"] = {
                [1] = 510035051,
                [2] = 510035052,
                [3] = 510035053,
                },
            ["SpeakNpcId"] = 700016,
            ["bForbidSkipOptions"] = true,
            },
        [51003506] = {
            ["Content"] = "当然有原因啦，告诉你也不是不行，但你得保证守口如瓶。",
            ["ContentFR"] = "Enfin bon... j’ai mes raisons. Je peux te les dire, mais tu dois promettre de ne rien répéter.",
            ["DialogueId"] = 51003506,
            ["GUID"] = "7FAE92B4",
            ["LookAt"] = {
                [1] = "700016:n(0)",
                },
            ["NextOptions"] = {
                [1] = 510035061,
                },
            ["RestartTag"] = 51003506,
            ["SpeakNpcId"] = 700016,
            ["bForbidSkipOptions"] = true,
            },
        [51003507] = {
            ["Content"] = "像，很像啊！",
            ["ContentFR"] = "Franchement, un peu oui.",
            ["DialogueId"] = 51003507,
            ["GUID"] = "7FAE92DE",
            ["SpeakNpcId"] = 700016,
            },
        [51003508] = {
            ["Content"] = "那我就告诉你吧！",
            ["ContentFR"] = "Bon... d’accord, je vais te le dire.",
            ["DialogueId"] = 51003508,
            ["GUID"] = "7FAE9308",
            ["LookAt"] = {
                [1] = "700016:n(0)",
                },
            ["NextDialogue"] = 51003509,
            ["SpeakNpcId"] = 700016,
            ["TalkActionId"] = {
                [1] = "700016:Confident_Start",
                },
            },
        [51003509] = {
            ["Content"] = "上个月我偷偷溜去贫民窟玩，结果在小巷子里碰到了一个神秘的老婆婆！",
            ["ContentFR"] = "Le mois dernier, je me suis faufilée dans les taudis. Et là, dans une ruelle, j’ai rencontré une vieille dame mystérieuse ! Elle s’appelle Belinda.",
            ["DialogueId"] = 51003509,
            ["GUID"] = "7FAE9332",
            ["NextDialogue"] = 51003510,
            ["SpeakNpcId"] = 700016,
            },
        [51003510] = {
            ["Content"] = "她手可巧啦，会给我编各种花式的小辫子，会用鲜花给我染指甲，还知道许许多多我从来没听过的小故事！",
            ["ContentFR"] = "Elle a des doigts magiques, elle sait tresser des coiffures incroyables, colorer mes ongles avec des fleurs fraîches, et elle connaît des histoires que je n’avais jamais entendues de ma vie !",
            ["DialogueId"] = 51003510,
            ["GUID"] = "7FAE935C",
            ["NextDialogue"] = 51003511,
            ["SpeakNpcId"] = 700016,
            ["TalkActionId"] = {
                [1] = "700016:Confident_End",
                },
            },
        [51003511] = {
            ["Content"] = "她从不对我说教，也不把我当小孩糊弄，虽然那是我们头一回见，但她搂着我的时候就像我奶奶一样温暖……",
            ["ContentFR"] = "Elle ne me fait jamais la leçon, elle ne me prend pas de haut. La première fois déjà, quand elle m’a serrée dans ses bras, j’ai eu l’impression de retrouver ma propre grand-mère...",
            ["DialogueId"] = 51003511,
            ["GUID"] = "7FAE9386",
            ["NextDialogue"] = 51003512,
            ["SpeakNpcId"] = 700016,
            },
        [51003512] = {
            ["Content"] = "那不是很好吗？为什么不坦然告诉别人你有新朋友了呢？",
            ["ContentFR"] = "Alors où est le problème ? Pourquoi ne pas dire simplement à tout le monde que tu as une nouvelle amie ?",
            ["DialogueId"] = 51003512,
            ["GUID"] = "7FAE93B0",
            ["NextDialogue"] = 51003513,
            ["SpeakNpcId"] = 100001,
            },
        [51003513] = {
            ["Content"] = "因为婆婆长了角……如果我告诉父母、同学、老师，一定会让她受到伤害吧……",
            ["ContentFR"] = "Parce que... Mamie Belinda a des cornes. Si mes parents, mes camarades ou les professeurs l’apprenaient, elle risquerait d’avoir des ennuis...",
            ["DialogueId"] = 51003513,
            ["GUID"] = "7FAE93DA",
            ["NextDialogue"] = 51003514,
            ["SpeakNpcId"] = 700016,
            ["TalkActionId"] = {
                [1] = "700016:Explain02_Start",
                },
            },
        [51003514] = {
            ["Content"] = "我们本来约好了今天见面，可是学校临时增加了纪念活动，我只能爽约了，如果你有空，可不可以帮我把这个布娃娃带给她？",
            ["ContentFR"] = "On devait se voir aujourd’hui, mais l’école a ajouté cette commémoration au dernier moment. Du coup je ne peux pas y aller... Est-ce que tu pourrais lui apporter cette poupée à ma place ?",
            ["DialogueId"] = 51003514,
            ["GUID"] = "7FAE9404",
            ["LookAt"] = {
                [1] = "700016:n(0)",
                },
            ["NextOptions"] = {
                [1] = 510035141,
                [2] = 51000002,
                },
            ["SpeakNpcId"] = 700016,
            ["TalkActionId"] = {
                [1] = "700016:Explain02_End",
                },
            ["bForbidSkipOptions"] = true,
            },
        [51003515] = {
            ["Content"] = "集合时间到了，拜托你可千万要送到哦！谢谢你！",
            ["ContentFR"] = "Mince, je dois y aller, la maîtresse m’attend... Tu me promets de lui donner ? Merci !",
            ["DialogueId"] = 51003515,
            ["GUID"] = "7FAE942E",
            ["SpeakNpcId"] = 700016,
            },
        [51003520] = {
            ["Content"] = "下面由艾玛献上纪念的花……",
            ["ContentFR"] = "Et maintenant, qu’Emma vienne offrir les fleurs du souvenir...",
            ["DialogueId"] = 51003520,
            ["GUID"] = "7FAE9500",
            ["NextDialogue"] = 51003502,
            ["SpeakNpcId"] = 700086,
            },
        [51003601] = {
            ["Camera"] = "-59.474121,-281.53418,130.205078,0.000004,0.0,71.19751,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "谢谢你，婆婆，我觉得好多了，如果这是罗伯期望的，我会为了他好好生活。",
            ["ContentFR"] = "Merci, Madame Belinda... Je me sens déjà mieux. Si c’est ce que Robb voulait, alors je vais vivre bravement... pour lui.",
            ["DialogueId"] = 51003601,
            ["GUID"] = "7FAEA24A",
            ["NextDialogue"] = 51003602,
            ["SpeakNpcId"] = 700087,
            ["TalkActionId"] = {
                [1] = "700087:Explain02_Start",
                },
            },
        [51003602] = {
            ["Camera"] = "-83.495605,207.759766,134.179199,0.000004,-0.199981,-68.802429,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "希望你早日走出悲痛，我们与你同在，孩子，如果你需要，贝琳达的小屋永远为你开放。",
            ["ContentFR"] = "Courage, mon enfant. Nous sommes à tes côtés. Et si besoin est, la tente de Belinda te sera toujours ouverte.",
            ["DialogueId"] = 51003602,
            ["GUID"] = "7FAEA274",
            ["SpeakNpcId"] = 700081,
            ["TalkActionId"] = {
                [1] = "700087:Explain02_End",
                [2] = "700081:Explain01_Start",
                },
            },
        [51003604] = {
            ["Content"] = "你好呀！我从没见过你，我猜你是刚来冰湖城的朋友？找贝琳达有什么事呢？",
            ["ContentFR"] = "Bonjour ! Je ne t’ai jamais vu par ici. Tu viens d’arriver à Givrelac, peut-être ? Qu’est-ce qui t’amène chez la vieille Belinda ?",
            ["DialogueId"] = 51003604,
            ["GUID"] = "7FAEA2C8",
            ["NextOptions"] = {
                [1] = 510036041,
                },
            ["SpeakNpcId"] = 700081,
            ["TalkActionId"] = {
                [1] = "700081:Explain01_Start",
                },
            },
        [51003605] = {
            ["Content"] = "（虽然手艺粗糙，但你能看出娃娃和贝琳达有几分相似。卡戎婆婆满是喜悦，将娃娃抚摸了一遍又一遍。）",
            ["ContentFR"] = "La poupée est rudimentaire, mais on y devine les traits de Belinda. La vieille dame s’en empare avec une joie visible, la caressant avec tendresse.",
            ["DialogueId"] = 51003605,
            ["GUID"] = "7FAEA2F2",
            ["NextDialogue"] = 51003606,
            ["TalkActionId"] = {
                [1] = "700081:Explain01_End",
                },
            },
        [51003606] = {
            ["Content"] = "我从娃娃上感觉到了广场的气息……啊，瞧我这记性！纪念周到啦，这时候的活动总是很多……",
            ["ContentFR"] = "Je sens encore l’odeur de la place sur ce jouet... Ah ! mais oui, c’est la semaine commémorative ! Comme le temps passe vite...",
            ["DialogueId"] = 51003606,
            ["GUID"] = "7FAEA31C",
            ["NextDialogue"] = 51003607,
            ["SpeakNpcId"] = 700081,
            ["TalkActionId"] = {
                [1] = "700081:Agree",
                },
            },
        [51003607] = {
            ["Content"] = "我很感谢你，孩子。",
            ["ContentFR"] = "Merci, mon enfant.",
            ["DialogueId"] = 51003607,
            ["GUID"] = "7FAEA346",
            ["NextDialogue"] = 51003608,
            ["SpeakNpcId"] = 700081,
            },
        [51003608] = {
            ["Content"] = "（她仔细地端详着你，有好几分钟都没有说话。）",
            ["ContentFR"] = "Belinda te fixe longuement, sans un mot.",
            ["DialogueId"] = 51003608,
            ["GUID"] = "7FAEA370",
            ["NextDialogue"] = 51003609,
            },
        [51003609] = {
            ["Content"] = "你好像惹上了大麻烦，我闻到了海风的味道，感受到了潮水的包裹，还有……你手掌上残留的，他人的温度，但这份温暖正逐渐远去……",
            ["ContentFR"] = "Tu portes un grand fardeau. Je sens sur toi l’odeur de la mer, l’étreinte des vagues... et la chaleur d’une main aimée, qui peu à peu s’éteint.",
            ["DialogueId"] = 51003609,
            ["GUID"] = "7FAEA39A",
            ["NextDialogue"] = 51003610,
            ["SpeakNpcId"] = 700081,
            ["TalkActionId"] = {
                [1] = "700081:Explain02_Start",
                },
            },
        [51003610] = {
            ["Content"] = "来到这里的每时每刻，你都被困惑与悲伤缠绕，但你努力把这些压抑在心底，不去表露……",
            ["ContentFR"] = "Depuis ton arrivée ici, confusion et chagrin t’accompagnent. Tu caches tout ça au fond de ton cœur...",
            ["DialogueId"] = 51003610,
            ["GUID"] = "7FAEA3C4",
            ["NextDialogue"] = 51003611,
            ["SpeakNpcId"] = 700081,
            ["TalkActionId"] = {
                [1] = "700081:Explain02_End",
                },
            },
        [51003611] = {
            ["Content"] = "无意冒犯，你是否失去了重要之人？",
            ["ContentFR"] = "Pardonne ma franchise, mais... as-tu perdu quelqu’un de cher ?",
            ["DialogueId"] = 51003611,
            ["GUID"] = "7FAEA3EE",
            ["NextOptions"] = {
                [1] = 510036111,
                [2] = 510036112,
                [3] = 510036113,
                },
            ["SpeakNpcId"] = 700081,
            ["bForbidSkipOptions"] = true,
            },
        [51003612] = {
            ["Content"] = "能活到我这么大年纪的卡戎很稀奇吧？",
            ["ContentFR"] = "En effet. Il est rare que les Charons atteignent mon âge.",
            ["DialogueId"] = 51003612,
            ["GUID"] = "7FAEA418",
            ["NextDialogue"] = 51003615,
            ["SpeakNpcId"] = 700081,
            },
        [51003613] = {
            ["Content"] = "你在难过，孩子。",
            ["ContentFR"] = "Tu es triste, mon enfant.",
            ["DialogueId"] = 51003613,
            ["GUID"] = "7FAEA442",
            ["NextDialogue"] = 51003615,
            ["SpeakNpcId"] = 700081,
            },
        [51003614] = {
            ["Content"] = "不用强撑，我知道的，孩子。",
            ["ContentFR"] = "Tu souffres, mon enfant. Pas besoin de le nier, je le vois.",
            ["DialogueId"] = 51003614,
            ["GUID"] = "7FAEA46C",
            ["NextDialogue"] = 51003615,
            ["SpeakNpcId"] = 700081,
            },
        [51003615] = {
            ["Content"] = "很遗憾，孩子，我没有帮助你的办法，但有一句话，我想正适合此时的你……",
            ["ContentFR"] = "Hélas, je n’ai pas de remède à t’offrir. Mais voici des paroles anciennes, peut-être t’apporteront-elles un peu de réconfort...",
            ["DialogueId"] = 51003615,
            ["GUID"] = "7FAEA496",
            ["NextDialogue"] = 51003616,
            ["SpeakNpcId"] = 700081,
            },
        [51003616] = {
            ["Content"] = "“行人走上一线旅途，命运女神纺锤收束。当千头万绪重聚，失物在眼前沉浮。”",
            ["ContentFR"] = "« Le voyageur chausse ses bottes et s’avance tandis que le fuseau de la Déesse du Destin resserre ses fils. Quand mille chemins se rejoignent, ce qui a été perdu revient doucement à portée de main. »",
            ["DialogueId"] = 51003616,
            ["GUID"] = "7FAEA4C0",
            ["NextOptions"] = {
                [1] = 510036161,
                },
            ["RestartTag"] = 51003616,
            ["SpeakNpcId"] = 700081,
            ["TalkActionId"] = {
                [1] = "700081:Agree",
                },
            ["bForbidSkipOptions"] = true,
            },
        [51003617] = {
            ["Content"] = "孩子，你将在旅途中拾得你缺少的一切，去吧，去吧。",
            ["ContentFR"] = "Va, mon enfant. Tu retrouveras sur ta route tout ce qui t’a été arraché.",
            ["DialogueId"] = 51003617,
            ["GUID"] = "7FAEA4EA",
            ["SpeakNpcId"] = 700081,
            },
        [51003618] = {
            ["Content"] = "出自《命运女神的纺锤》终幕……无可剥夺者在双面之境见到了自己失去的一切……你是在告诉我终有一天我们会再次相见？",
            ["ContentFR"] = "C’est la fin de <I>Le Fuseau de la Déesse du Destin</>. Le héros y retrouve, dans le Royaume des Reflets, tout ce qu’il avait perdu... Tu veux dire que nous nous reverrons ?",
            ["DialogueId"] = 51003618,
            ["GUID"] = "7FAEA514",
            ["NextDialogue"] = 51003619,
            ["SpeakNpcId"] = 100001,
            },
        [51003619] = {
            ["Content"] = "请把这句箴言当作送来娃娃的谢礼吧。你很聪明，孩子，就像我所看到的一样……不需要我告诉你什么，你会依靠自己的力量探明疑问。",
            ["ContentFR"] = "Considère ces mots comme un remerciement pour la poupée. Tu es {性别:intelligent|intelligente}, je le vois bien. Tu trouveras toi-même la réponse.",
            ["DialogueId"] = 51003619,
            ["GUID"] = "7FAEA53E",
            ["NextDialogue"] = 51003620,
            ["SpeakNpcId"] = 700081,
            ["TalkActionId"] = {
                [1] = "700081:Agree",
                },
            },
        [51003620] = {
            ["Content"] = "另外，我会送给每个初次来拜访我的人一件小礼物，只要一件带有你自身气息的铁丝就好，不急于现在，我会一直在这里等你。",
            ["ContentFR"] = "Et puis... chaque personne qui parvient jusqu’ici pour la première fois reçoit un petit présent de ma part. Il me suffira d’un simple fil de fer portant ton empreinte... Pas besoin de se presser, je t’attendrai ici.",
            ["DialogueId"] = 51003620,
            ["GUID"] = "7FAEA568",
            ["NextDialogue"] = 51003621,
            ["SpeakNpcId"] = 700081,
            ["TalkActionId"] = {
                [1] = "700081:Explain02_Start",
                },
            },
        [51003621] = {
            ["Content"] = "气息……虽然不太明白，但只要是我接触过的，或者在我身上待过的就可以吧。",
            ["ContentFR"] = "Mon empreinte... ? Je ne suis pas {性别:sûr|sûre} de comprendre, mais ça doit vouloir dire n’importe quel objet que j’ai touché ou porté, non ?",
            ["DialogueId"] = 51003621,
            ["GUID"] = "7FAEA592",
            ["NextDialogue"] = 51003622,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "700081:Explain02_End",
                },
            },
        [51003622] = {
            ["Content"] = "格雷姆废矿那里应该有不少铁丝，我去那边看看。",
            ["ContentFR"] = "Dans la Fosse de Glevum, il doit y avoir plein de morceaux de fils de fer. J’irai voir.",
            ["DialogueId"] = 51003622,
            ["Duration"] = 3,
            ["GUID"] = "7FAEA5BC",
            ["SpeakNpcId"] = 100001,
            },
        [51003630] = {
            ["Content"] = "陌生的卡戎虽然还挂着泪痕，但你能从他的眼中看出，他已经燃起了活下去的勇气。",
            ["ContentFR"] = "Le jeune Charon, les yeux encore humides, repart avec hésitation. Mais dans son regard brille désormais une volonté nouvelle.",
            ["DialogueId"] = 51003630,
            ["Duration"] = 4,
            ["GUID"] = "7FAEA70C",
            ["NextDialogue"] = 51003631,
            },
        [51003631] = {
            ["Content"] = "他与贝琳达拥抱后，依依不舍地离去了。",
            ["ContentFR"] = "Après avoir serré Belinda dans ses bras, il s’éloigne à contrecœur.",
            ["DialogueId"] = 51003631,
            ["Duration"] = 2,
            ["GUID"] = "7FAEA736",
            },
        [51003701] = {
            ["Content"] = "（贝琳达从你手中接过铁丝，将其弯成了一枚侧脸肖像，你能看出这件小工艺品与贝蕾妮卡有些相似。）",
            ["ContentFR"] = "Belinda prend le fil entre ses doigts et le tord jusqu’à en faire un délicat profil de jeune fille. Il ressemble étrangement à Berenica.",
            ["DialogueId"] = 51003701,
            ["GUID"] = "7FAEB2B2",
            ["NextDialogue"] = 51003702,
            },
        [51003702] = {
            ["Content"] = "我并不强大，只能看到些朦胧的影子，不知道这与你思念之人是否相像，只是希望这能让你好受一些。",
            ["ContentFR"] = "Je ne vois que des ombres... Je ne sais pas si cela ressemble à celle que tu chéris. Mais j’espère que cela t’apaisera un peu.",
            ["DialogueId"] = 51003702,
            ["GUID"] = "7FAEB2DC",
            ["NextDialogue"] = 51003703,
            ["SpeakNpcId"] = 700081,
            ["TalkActionId"] = {
                [1] = "700081:Disagree",
                },
            },
        [51003703] = {
            ["Content"] = "衷心祝愿你们再次重逢。",
            ["ContentFR"] = "Je souhaite de tout cœur que vous vous retrouviez.",
            ["DialogueId"] = 51003703,
            ["GUID"] = "7FAEB306",
            ["NextDialogue"] = 51003704,
            ["SpeakNpcId"] = 700081,
            },
        [51003704] = {
            ["Content"] = "（你离开了贝琳达的小帐篷，现在你好像理解为什么艾玛对这里如此留恋了，贝琳达的力量并不强大，但她始终在治愈心灵，抚平伤痛。）",
            ["ContentFR"] = "Tu quittes sa tente, comprenant mieux pourquoi Emma tient tant à elle. Ses pouvoirs ne sont pas immenses, mais elle guérit les cœurs et console les âmes.",
            ["DialogueId"] = 51003704,
            ["GUID"] = "7FAEB330",
            },
        [51003705] = {
            ["Camera"] = "-279.652405,-157.0,151.0,0.000004,-6.0,21.800476,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "嗯……这样应该就差不多了！",
            ["ContentFR"] = "Bon... ça devrait faire l’affaire !",
            ["DialogueId"] = 51003705,
            ["FinalCamera"] = "-279.652405,-135.0,151.0,0.000004,-6.0,21.80052,35.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "7FAEA5BD",
            ["NextDialogue"] = 51003706,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Think_Start",
                },
            ["ToFinalCameraBlendTime"] = 5,
            },
        [51003706] = {
            ["Camera"] = "-279.652405,-135.0,151.0,0.000004,-6.0,21.80052,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "打打打打打劫！你怀里的宝贝是我的啦！",
            ["ContentFR"] = "H-H-H-Halte-là ! Ce trésor est à moi maintenant !",
            ["DialogueId"] = 51003706,
            ["GUID"] = "7FAEA5BE",
            ["NextDialogue"] = 51003707,
            ["Scripts"] = "SEQ{PlayAnimation{ActorId{100001},AnimationId{\"Think_End\"},Duration{1}},TurnTo{_delay{1},TurnToDescription{\"100001:p(180)\"}}}",
            ["SpeakNpcId"] = 700206,
            },
        [51003707] = {
            ["Camera"] = "128.007935,301.234375,103.0,0.000009,0.0,-108.798302,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "（皎皎之民的身影猛地从一旁窜出，一把抢过你怀中的铁丝，一边跑一边回头嘲笑着你。）",
            ["ContentFR"] = "D’un bond, la petite Luno surgit de nulle part, arrache le fil de fer de tes mains et s’enfuit en ricanant.",
            ["DialogueId"] = 51003707,
            ["GUID"] = "7FAEA5BF",
            ["NextDialogue"] = 51003708,
            ["Scripts"] = "MoveTo{ActorId{700206},TargetPoint{\"QuestPoint_DJMove\"},MoveSpeed{200},Visibility{\"Show\"}}",
            },
        [51003708] = {
            ["Camera"] = "21.397217,106.074219,131.0,0.00001,0.0,-116.797485,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "总算被我逮到机会了，这次我我我终于成功啦，哈哈哈哈哈哈哈！",
            ["ContentFR"] = "Hahaha ! J’ai enfin réussie ! Cette fois c’est moi la gagnante !",
            ["DialogueId"] = 51003708,
            ["GUID"] = "7FAEA5C0",
            ["NextDialogue"] = 51003709,
            ["SpeakNpcId"] = 700206,
            },
        [51003709] = {
            ["Camera"] = "21.397217,106.074219,131.0,0.00001,0.0,-116.797485,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "（就算不知道贝琳达要这些铁丝做什么用，你也不打算让手中的东西被白白抢走，追上去好好教训她一番吧。）",
            ["ContentFR"] = "Même si tu ignores pourquoi Belinda a besoin de ce fil, tu ne peux pas la laisser filer avec ton bien. Il faut la rattraper et lui donner une petite leçon !",
            ["DialogueId"] = 51003709,
            ["GUID"] = "7FAEA5C1",
            ["TalkActionId"] = {
                [1] = "100001:Confident_Start",
                },
            },
        [51003710] = {
            ["Content"] = "战胜打打打打打劫皎皎",
            ["ContentFR"] = "Combat : Vaincre Lulu, pilleuse de loot",
            ["DialogueId"] = 51003710,
            ["GUID"] = "7FAEA5C2",
            },
        [51003711] = {
            ["Camera"] = "-279.652405,-135.0,151.0,0.000004,-6.0,21.80052,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "为了一堆破铜烂铁，至于打成这样嘛呜呜呜呜……",
            ["ContentFR"] = "Aïe aïe aïe ! Tout ça pour un vieux bout de ferraille... Fallait vraiment me frapper si fort ? <I>Bouhouhou...</>",
            ["DialogueId"] = 51003711,
            ["GUID"] = "7FAEA5C3",
            ["SpeakNpcId"] = 700206,
            },
        [51003712] = {
            ["Content"] = "费了一些周折，你总算拿回了属于你的铁丝。检查无误再一抬头，发现那只皎皎早已不见了踪影。",
            ["ContentFR"] = "Après quelques efforts, tu récupères ton bien. Lulu, elle, a déjà disparu sans laisser de trace.",
            ["DialogueId"] = 51003712,
            ["Duration"] = 5,
            ["GUID"] = "7FAEA5C4",
            ["NextDialogue"] = 51003713,
            },
        [51003713] = {
            ["Content"] = "你无奈地摇摇头，向着贝琳达的帐篷动身。",
            ["ContentFR"] = "Tu secoues la tête et reprends ton chemin vers la tente de Belinda.",
            ["DialogueId"] = 51003713,
            ["GUID"] = "7FAEA5C5",
            },
        [51003721] = {
            ["Content"] = "打打打打打劫皎皎已逃走，任务失败，请重新开始。",
            ["ContentFR"] = "Lulu, pilleuse de loot a pris la fuite. Mission échouée. Veuillez recommencer.",
            ["DialogueId"] = 51003721,
            ["Duration"] = 3,
            ["GUID"] = "7FAEA5C6",
            },
        [51003801] = {
            ["Content"] = "你……卡戎……我的同类……",
            ["ContentFR"] = "Tu... Charon... un des miens...",
            ["DialogueId"] = 51003801,
            ["GUID"] = "7FAEC31A",
            ["NextDialogue"] = 51003802,
            ["SpeakNpcId"] = 700012,
            ["TalkActionId"] = {
                [1] = "700012:Explain02_Start",
                },
            },
        [51003802] = {
            ["Content"] = "（眼前的少女喃喃地说着，眼神似乎是在看你，又似乎是在看着未知的远方。）",
            ["ContentFR"] = "La jeune fille devant toi murmure d’une voix éteinte. Son regard semble se poser sur toi... ou peut-être se perdre dans un lointain invisible.",
            ["DialogueId"] = 51003802,
            ["GUID"] = "7FAEC344",
            ["NextOptions"] = {
                [1] = 510038021,
                [2] = 510038022,
                },
            ["TalkActionId"] = {
                [1] = "700012:Explain02_End",
                },
            ["bForbidSkipOptions"] = true,
            },
        [51003803] = {
            ["Content"] = "你愿意帮我吗……？",
            ["ContentFR"] = "Tu... tu voudrais m’aider... ?",
            ["DialogueId"] = 51003803,
            ["GUID"] = "7FAEC36E",
            ["NextDialogue"] = 51003805,
            ["SpeakNpcId"] = 700012,
            ["TalkActionId"] = {
                [1] = "700012:Agree",
                },
            },
        [51003804] = {
            ["Content"] = "不……我不是索拉之民……",
            ["ContentFR"] = "Non... Je ne suis pas une Sola...",
            ["DialogueId"] = 51003804,
            ["GUID"] = "7FAEC398",
            ["NextDialogue"] = 51003805,
            ["SpeakNpcId"] = 700012,
            ["TalkActionId"] = {
                [1] = "700012:Disagree",
                },
            },
        [51003805] = {
            ["Content"] = "你看，我的……恶魔角。",
            ["ContentFR"] = "Regarde, mes... cornes de démon.",
            ["DialogueId"] = 51003805,
            ["GUID"] = "7FAEC3C2",
            ["NextDialogue"] = 51003806,
            ["SpeakNpcId"] = 700012,
            },
        [51003806] = {
            ["Content"] = "（女孩揪起自己的凌乱的发梢给你看，依稀可以看出那只是被拆掉了一半的辫子，没有任何角的痕迹。显然，她是一个如假包换的索拉之民。)",
            ["ContentFR"] = "La fille soulève ses mèches en désordre pour te montrer. On distingue seulement une tresse défaites à moitié, sans la moindre trace de corne. Il est évident qu’elle est une Sola, sans l’ombre d’un doute.",
            ["DialogueId"] = 51003806,
            ["GUID"] = "7FAEC3EC",
            ["NextDialogue"] = 51003807,
            },
        [51003807] = {
            ["Content"] = "这只是头发而已。",
            ["ContentFR"] = "Ce n’est que des cheveux.",
            ["DialogueId"] = 51003807,
            ["GUID"] = "7FAEC416",
            ["NextDialogue"] = 51003808,
            ["SpeakNpcId"] = 100001,
            },
        [51003808] = {
            ["Content"] = "不，这是角……它们只是被魔法隐藏起来了，所以看上去才像头发！他们都看到了……两根硕大无比的角！",
            ["ContentFR"] = "Non, ce sont mes cornes... Elles sont juste dissimulées par un sort, alors tu crois voir des cheveux ! Mais eux les ont vues... deux cornes énormes, massives !",
            ["DialogueId"] = 51003808,
            ["GUID"] = "7FAEC440",
            ["NextOptions"] = {
                [1] = 510038081,
                [2] = 510038082,
                },
            ["SpeakNpcId"] = 700012,
            ["TalkActionId"] = {
                [1] = "700012:Disagree",
                },
            ["bForbidSkipOptions"] = true,
            },
        [51003809] = {
            ["Content"] = "是真的！虽然我也不知道该怎么解释，但是……",
            ["ContentFR"] = "C’est vrai ! Je ne sais pas comment l’expliquer, mais...",
            ["DialogueId"] = 51003809,
            ["GUID"] = "7FAEC46A",
            ["NextDialogue"] = 51003811,
            ["SpeakNpcId"] = 700012,
            ["TalkActionId"] = {
                [1] = "700012:Agree",
                },
            },
        [51003810] = {
            ["Content"] = "我……我也不知道该怎么向你解释，但是……",
            ["ContentFR"] = "Je... je ne saurais pas te l’expliquer, mais...",
            ["DialogueId"] = 51003810,
            ["GUID"] = "7FAEC494",
            ["NextDialogue"] = 51003811,
            ["SpeakNpcId"] = 700012,
            ["TalkActionId"] = {
                [1] = "700012:Disagree",
                },
            },
        [51003811] = {
            ["Content"] = "他们都这么说。",
            ["ContentFR"] = "C’est ce qu’ils disent, eux.",
            ["DialogueId"] = 51003811,
            ["GUID"] = "7FAEC4BE",
            ["NextDialogue"] = 51003812,
            ["SpeakNpcId"] = 700012,
            ["TalkActionId"] = {
                [1] = "700012:Explain01_Start",
                },
            },
        [51003812] = {
            ["Content"] = "“他们”是谁？",
            ["ContentFR"] = "« Eux »... qui ça ?",
            ["DialogueId"] = 51003812,
            ["GUID"] = "7FAEC4E8",
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "700012:Explain01_End",
                },
            },
        [51003813] = {
            ["Camera"] = "273.684082,-345.582031,101.247314,0.000134,0.0,134.992844,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "费伊，原来你是跑到外城来了！可让我好找。",
            ["ContentFR"] = "Faye, te voilà ! Tu t’étais réfugiée dans la cité extérieure ! On t’a cherchée partout !",
            ["DialogueId"] = 51003813,
            ["GUID"] = "7FAEC512",
            ["LookAt"] = {
                [1] = "700012:n(700089)",
                },
            ["NextDialogue"] = 51003814,
            ["SpeakNpcId"] = 700088,
            ["TurnTo"] = {
                [1] = "700012:n(700089)",
                [2] = "100001:n(700089)",
                },
            },
        [51003814] = {
            ["Camera"] = "-150.919434,85.612305,106.559326,0.000157,0.0,-35.397251,18.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "怎么了？收到我们精心准备的礼物不开心吗？我雇了两个卡戎小孩才弄到那么多虫子，花了一整天的零花钱呢！",
            ["ContentFR"] = "Quoi ? Notre petit cadeau ne t’a pas plu ? J’ai payé deux gosses Charons pour attraper tous ces rats, ça m’a coûté une journée entière d’argent de poche !",
            ["DialogueId"] = 51003814,
            ["GUID"] = "7FAEC53C",
            ["NextDialogue"] = 51003815,
            ["SpeakNpcId"] = 700088,
            ["TalkActionId"] = {
                [1] = "700088:Explain01_Start",
                },
            },
        [51003815] = {
            ["Camera"] = "-150.919434,85.612305,106.559326,0.000157,0.0,-35.397251,18.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "快回去吧，你跑来这种地方，可把大伙儿“担心”坏了。",
            ["ContentFR"] = "Allez, rentre avec nous. Tout le monde est tellement \"inquiet\" de ton absence.",
            ["DialogueId"] = 51003815,
            ["GUID"] = "7FAEC566",
            ["NextDialogue"] = 51003816,
            ["SpeakNpcId"] = 700088,
            ["TalkActionId"] = {
                [1] = "700088:Explain01_End",
                },
            },
        [51003816] = {
            ["Camera"] = "305.593262,-312.492188,101.247314,0.000134,-0.200008,138.792572,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我……我不要回去……",
            ["ContentFR"] = "Je... je ne veux pas rentrer...",
            ["DialogueId"] = 51003816,
            ["GUID"] = "7FAEC590",
            ["NextDialogue"] = 51003817,
            ["Scripts"] = "SEQ{MoveTo{ActorId{100001},TargetPoint{\"QuestPoint_20021101\"},MoveSpeed{100}},TurnTo{TurnToDescription{\"100001:n(700089)\"}},PlayAnimation{ActorId{100001},AnimationId{\"Talk03_Start\"},Duration{2}}}",
            ["SpeakNpcId"] = 700012,
            ["TalkActionId"] = {
                [1] = "700012:Shock_Start",
                [2] = "700090:Confident_End",
                },
            },
        [51003817] = {
            ["Camera"] = "305.593262,-312.492188,101.247314,0.000134,-0.200008,138.792572,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "哎，你们看，那边那个不是卡戎吗？",
            ["ContentFR"] = "Hé, regardez ! Là-bas, c’est {性别:un|une} Charon, non ?",
            ["DialogueId"] = 51003817,
            ["GUID"] = "7FAEC5BA",
            ["NextDialogue"] = 51003818,
            ["SpeakNpcId"] = 700089,
            ["TurnTo"] = {
                [1] = "700088:n(100001)",
                [2] = "700089:n(100001)",
                [3] = "700090:n(100001)",
                },
            },
        [51003818] = {
            ["Camera"] = "305.593262,-312.492188,101.247314,0.000134,-0.200008,138.792572,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "哈哈哈，我就说她是恶魔嘛！",
            ["ContentFR"] = "Ahahaha ! Je le savais, c’est bien un démon !",
            ["DialogueId"] = 51003818,
            ["GUID"] = "7FAEC5E4",
            ["NextDialogue"] = 51003819,
            ["SpeakNpcId"] = 700088,
            ["TalkActionId"] = {
                [1] = "700088:Talk03_Start",
                },
            },
        [51003819] = {
            ["Camera"] = "305.593262,-312.492188,101.247314,0.000134,-0.200008,138.792572,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "原来你是跑到外城找亲戚啊，真有意思！",
            ["ContentFR"] = "Alors comme ça, tu traînes dans les taudis pour retrouver ta famille ? Trop drôle !",
            ["DialogueId"] = 51003819,
            ["GUID"] = "7FAEC60E",
            ["NextDialogue"] = 51003820,
            ["SpeakNpcId"] = 700088,
            ["TalkActionId"] = {
                [1] = "700088:Talk03_End",
                },
            },
        [51003820] = {
            ["Camera"] = "-196.32959,376.199219,82.648193,0.000135,0.0,-68.609573,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我不是！……不，不，我是……",
            ["ContentFR"] = "Ce n’est pas vrai ! ... Non, non, je... je suis...",
            ["DialogueId"] = 51003820,
            ["FinalCamera"] = "-158.777344,280.334961,89.867432,0.000135,0.0,-68.609573,35.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "7FAEC638",
            ["NextDialogue"] = 51003821,
            ["SpeakNpcId"] = 700012,
            ["TalkActionId"] = {
                [1] = "700012:Disagree",
                },
            ["ToFinalCameraBlendTime"] = 6,
            },
        [51003821] = {
            ["Content"] = "女孩捂着耳朵逃开了。",
            ["ContentFR"] = "La fille se bouche les oreilles et s’enfuit en courant.",
            ["DialogueId"] = 51003821,
            ["GUID"] = "7FAEC662",
            ["IsBlack"] = 1,
            ["Scripts"] = "SetLocation{ActorId{700012},TargetPoint{\"QuestPoint_FayeRun\"},Visibility{\"Hide\"}}",
            },
        [51003901] = {
            ["Content"] = "（女孩低着头站在角落里，心情看上去非常低落。）",
            ["ContentFR"] = "La fille est recroquevillée dans un coin, la tête basse. Elle paraît abattue.",
            ["DialogueId"] = 51003901,
            ["GUID"] = "7FAED382",
            ["NextOptions"] = {
                [1] = 510039011,
                },
            ["bForbidSkipOptions"] = true,
            },
        [51003902] = {
            ["Content"] = "（女孩微微转过了头，似乎并不想开口。）",
            ["ContentFR"] = "La fille détourne légèrement la tête, visiblement peu disposée à parler.",
            ["DialogueId"] = 51003902,
            ["GUID"] = "7FAED3AC",
            },
        [51003903] = {
            ["Content"] = "是你啊……",
            ["ContentFR"] = "C’est toi...",
            ["DialogueId"] = 51003903,
            ["GUID"] = "7FAED3D6",
            ["NextDialogue"] = 51003904,
            ["SpeakNpcId"] = 700104,
            ["TalkActionId"] = {
                [1] = "700104:Explain02_Start",
                },
            },
        [51003904] = {
            ["Content"] = "刚才那些是你的同学吗？",
            ["ContentFR"] = "Ces enfants, c’étaient tes... camarades ?",
            ["DialogueId"] = 51003904,
            ["GUID"] = "7FAED400",
            ["NextDialogue"] = 51003905,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "700104:Explain02_End",
                },
            },
        [51003905] = {
            ["Content"] = "是的……对不起……对不起……我又搞砸了。",
            ["ContentFR"] = "Oui... Désolée... Désolée... J’ai encore tout raté.",
            ["DialogueId"] = 51003905,
            ["GUID"] = "7FAED42A",
            ["NextDialogue"] = 51003906,
            ["SpeakNpcId"] = 700104,
            ["TalkActionId"] = {
                [1] = "700104:Sigh_Start",
                },
            },
        [51003906] = {
            ["Content"] = "他们是不是欺负你了？",
            ["ContentFR"] = "Ils t’intimidaient, n’est-ce pas ?",
            ["DialogueId"] = 51003906,
            ["GUID"] = "7FAED454",
            ["NextDialogue"] = 51003907,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "700104:Sigh_End",
                },
            },
        [51003907] = {
            ["Content"] = "不……都是我的错……",
            ["ContentFR"] = "Non... c’est de ma faute...",
            ["DialogueId"] = 51003907,
            ["GUID"] = "7FAED47E",
            ["NextDialogue"] = 51003908,
            ["SpeakNpcId"] = 700104,
            ["TalkActionId"] = {
                [1] = "700104:Disagree",
                },
            },
        [51003908] = {
            ["Content"] = "我什么事都做不好，妈妈和老师都说我脑袋笨笨的。",
            ["ContentFR"] = "Je rate tout. Maman et mes professeurs disent que je suis idiote.",
            ["DialogueId"] = 51003908,
            ["GUID"] = "7FAED4A8",
            ["NextDialogue"] = 51003909,
            ["SpeakNpcId"] = 700104,
            ["TalkActionId"] = {
                [1] = "700104:Disagree",
                },
            },
        [51003909] = {
            ["Content"] = "我的同学很聪明，他们发现我之所以脑袋笨，是因为我是个卡戎，只是爸爸妈妈用魔法把角藏起来了。",
            ["ContentFR"] = "Mes camarades sont très intelligents. Ils ont découvert que si je suis stupide, c’est parce que je suis une Charon. Mes parents auraient caché mes cornes par magie.",
            ["DialogueId"] = 51003909,
            ["GUID"] = "7FAED4D2",
            ["NextDialogue"] = 51003910,
            ["SpeakNpcId"] = 700104,
            ["TalkActionId"] = {
                [1] = "700104:Explain01_Start",
                },
            },
        [51003910] = {
            ["Content"] = "都是我的错……我不该混在索拉之民里的……",
            ["ContentFR"] = "C’est de ma faute... Je n’aurais jamais dû me mêler aux Solariens...",
            ["DialogueId"] = 51003910,
            ["GUID"] = "7FAED4FC",
            ["NextDialogue"] = 51003911,
            ["SpeakNpcId"] = 700104,
            ["TalkActionId"] = {
                [1] = "700104:Explain01_End",
                },
            },
        [51003911] = {
            ["Content"] = "（毫无疑问，这是最拙劣的谎言。它勾起了一些令你不快的回忆：在净界岛上，你和贝蕾曾经遭遇的恶意。）",
            ["ContentFR"] = "Il ne fait aucun doute que c’est un mensonge grossier. Mais ses mots réveillent en toi de mauvais souvenirs : la malveillance que toi et Berenica aviez subie sur l’Île du Purgatoire.",
            ["DialogueId"] = 51003911,
            ["GUID"] = "7FAED526",
            ["NextDialogue"] = 51003912,
            },
        [51003912] = {
            ["Content"] = "（这些恶意或者因为你的弱小，或者因为你与众不同，又或者毫无来由——他们只是需要找什么倾泻，而那个倒霉蛋恰好是你。）",
            ["ContentFR"] = "La cruauté peut viser les faibles, les différents, ou n’avoir aucune raison : certains ont juste besoin d’un exutoire, et la malchance te désignait comme cible.",
            ["DialogueId"] = 51003912,
            ["GUID"] = "7FAED550",
            ["NextDialogue"] = 51003913,
            ["TalkActionId"] = {
                [1] = "700104:Disagree",
                },
            },
        [51003913] = {
            ["Content"] = "（只是这个女孩比曾经的你更加无助：甚至没有一个贝蕾妮卡愿意与她分摊这一切。）",
            ["ContentFR"] = "Mais cette enfant est plus démunie encore que toi jadis : elle n’a même pas une personne comme Berenica pour partager son fardeau.",
            ["DialogueId"] = 51003913,
            ["GUID"] = "7FAED57A",
            ["NextOptions"] = {
                [1] = 510039131,
                [2] = 510039132,
                [3] = 510039133,
                },
            ["bForbidSkipOptions"] = true,
            },
        [51003914] = {
            ["Content"] = "不是我的错吗……？",
            ["ContentFR"] = "Ce n’est pas... ma faute... ?",
            ["DialogueId"] = 51003914,
            ["GUID"] = "7FAED5A4",
            ["NextDialogue"] = 51003915,
            ["SpeakNpcId"] = 700104,
            ["TalkActionId"] = {
                [1] = "700104:Explain02_Start",
                },
            },
        [51003915] = {
            ["Content"] = "伤害别人的家伙才有错。",
            ["ContentFR"] = "Ceux qui blessent les autres sont les seuls coupables.",
            ["DialogueId"] = 51003915,
            ["GUID"] = "7FAED5CE",
            ["NextDialogue"] = 51003916,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "700104:Explain02_End",
                },
            },
        [51003916] = {
            ["Content"] = "你没有必要害怕，去反击吧。",
            ["ContentFR"] = "Tu n’as pas à avoir peur. Riposte.",
            ["DialogueId"] = 51003916,
            ["GUID"] = "7FAED5F8",
            ["NextDialogue"] = 51003922,
            ["SpeakNpcId"] = 100001,
            },
        [51003917] = {
            ["Content"] = "咦……？",
            ["ContentFR"] = "Hein... ?",
            ["DialogueId"] = 51003917,
            ["GUID"] = "7FAED622",
            ["NextDialogue"] = 51003918,
            ["SpeakNpcId"] = 700104,
            ["TalkActionId"] = {
                [1] = "700104:Shock_Start",
                },
            },
        [51003918] = {
            ["Content"] = "既然他们说你是恶魔，那不如就干点恶魔该干的事吧。",
            ["ContentFR"] = "Puisqu’ils t’appellent démon, alors agis comme tel.",
            ["DialogueId"] = 51003918,
            ["GUID"] = "7FAED64C",
            ["NextDialogue"] = 51003922,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "700104:Shock_End",
                },
            },
        [51003919] = {
            ["Content"] = "咦……？",
            ["ContentFR"] = "Hein... ?",
            ["DialogueId"] = 51003919,
            ["GUID"] = "7FAED676",
            ["NextDialogue"] = 51003920,
            ["SpeakNpcId"] = 700104,
            ["TalkActionId"] = {
                [1] = "700104:Shock_Start",
                },
            },
        [51003920] = {
            ["Content"] = "他们编了个谎话拿你取乐呢。不过……",
            ["ContentFR"] = "Ils ont inventé un mensonge pour se moquer de toi. Mais...",
            ["DialogueId"] = 51003920,
            ["GUID"] = "7FAED6A0",
            ["NextDialogue"] = 51003921,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "700104:Shock_End",
                },
            },
        [51003921] = {
            ["Content"] = "既然他们说你是恶魔，那不如就干点恶魔该干的事吧。",
            ["ContentFR"] = "Puisqu’ils t’appellent démon, alors agis comme tel.",
            ["DialogueId"] = 51003921,
            ["GUID"] = "7FAED6CA",
            ["NextDialogue"] = 51003922,
            ["SpeakNpcId"] = 100001,
            },
        [51003922] = {
            ["Content"] = "走，我们回去找他们。",
            ["ContentFR"] = "Viens. On retourne les voir.",
            ["DialogueId"] = 51003922,
            ["GUID"] = "7FAED6F4",
            ["SpeakNpcId"] = 100001,
            },
        [51004001] = {
            ["Camera"] = "-54.027344,192.986816,154.662109,0.000025,-9.800139,-47.991821,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我该怎么做呢……？",
