            },
        [51004003] = {
            ["Camera"] = "-415.09082,-71.93457,95.116699,0.000026,0.0,13.207663,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "快看，那家伙回来了！",
            ["ContentFR"] = "Regardez, la voilà !",
            ["DialogueId"] = 51004003,
            ["GUID"] = "7FAEE43E",
            ["LookAt"] = {
                [1] = "100001:n(100001)",
                [2] = "700104:n(700104)",
