                [1] = "700088:n(100001)",
                [2] = "700089:n(100001)",
                [3] = "700090:n(100001)",
                },
            },
        [51004004] = {
            ["Camera"] = "-415.09082,-71.93457,95.116699,0.000026,0.0,13.207663,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "这就和卡戎勾搭上了？不是一家人不进一家门！",
            ["ContentFR"] = "Elle traîne déjà avec {性别:un|une} Charon ? Qui se ressemble s’assemble !",
            ["DialogueId"] = 51004004,
            ["GUID"] = "7FAEE468",
            ["NextDialogue"] = 51004005,
            ["SpeakNpcId"] = 700088,
            ["TalkActionId"] = {
                [1] = "700088:Confident_Start",
                },
            },
        [51004005] = {
            ["Camera"] = "-415.09082,-71.93457,95.116699,0.000026,0.0,13.207663,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我……",
            ["ContentFR"] = "Je...",
            ["DialogueId"] = 51004005,
            ["GUID"] = "7FAEE492",
            ["NextDialogue"] = 51004006,
            ["SpeakNpcId"] = 700104,
            },
        [51004006] = {
            ["Camera"] = "-415.09082,-71.93457,95.116699,0.000026,0.0,13.207663,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "（女孩努力地张嘴想要说什么，但似乎还没组织好语言，也许是需要一些小小的帮助。要对她的同学们说什么？）",
            ["ContentFR"] = "La fille veut dire quelque chose, mais les mots ne sortent pas. Peut-être qu’elle a besoin d’un petit coup de pouce.",
            ["DialogueId"] = 51004006,
            ["GUID"] = "7FAEE4BC",
            ["NextOptions"] = {
                [1] = 510040061,
                [2] = 510040062,
                },
            },
        [51004007] = {
            ["Camera"] = "-415.09082,-71.93457,95.116699,0.000026,0.0,13.207663,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "是的……给我……给我……滚开！",
            ["ContentFR"] = "Oui... Dégagez... de mon... chemin !",
            ["DialogueId"] = 51004007,
            ["GUID"] = "7FAEE4E6",
            ["NextDialogue"] = 51004008,
            ["SpeakNpcId"] = 700104,
            ["TalkActionId"] = {
                [1] = "700104:Agree",
                },
            },
        [51004008] = {
            ["Camera"] = "-415.09082,-71.93457,95.116699,0.000026,0.0,13.207663,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "……不然我……我会和我的朋友一起把你们都送进地狱……！",
            ["ContentFR"] = "... Sinon je... je vous enverrai tous en enfer avec mon {性别:ami|amie}... !",
            ["DialogueId"] = 51004008,
            ["GUID"] = "7FAEE510",
            ["NextDialogue"] = 51004009,
            ["SpeakNpcId"] = 700104,
            },
        [51004009] = {
            ["Camera"] = "-415.09082,-71.93457,95.116699,0.000026,0.0,13.207663,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "或者，你们不是喜欢虫子、喜欢老鼠吗？就把你们丢进下水道好了……！",
            ["ContentFR"] = "Ou bien, puisque vous aimez les rats et les insectes, je vous jetterai dans les égouts... !",
            ["DialogueId"] = 51004009,
            ["GUID"] = "7FAEE53A",
            ["NextDialogue"] = 51004010,
            ["SpeakNpcId"] = 700104,
            ["TalkActionId"] = {
                [1] = "700104:Think_Start",
                },
            },
        [51004010] = {
            ["Camera"] = "-415.09082,-71.93457,95.116699,0.000026,0.0,13.207663,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "不，不行，老鼠肯定也会嫌弃你们的！",
            ["ContentFR"] = "Non, attendez... Même les rats auraient honte de vous !",
            ["DialogueId"] = 51004010,
            ["GUID"] = "7FAEE564",
            ["NextDialogue"] = 51004011,
            ["SpeakNpcId"] = 700104,
            ["TalkActionId"] = {
                [1] = "700104:Think_End",
                },
            },
        [51004011] = {
            ["Camera"] = "-415.09082,-71.93457,95.116699,0.000026,0.0,13.207663,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "（仿佛是打破了某种无形的束缚，女孩一反之前寡言少语的样子，滔滔不绝地骂了起来。）",
            ["ContentFR"] = "Comme libérée d’un carcan invisible, la fille d’ordinaire si timide se met à déverser un flot ininterrompu d’insultes.",
            ["DialogueId"] = 51004011,
            ["GUID"] = "7FAEE58E",
            ["NextDialogue"] = 51004012,
            },
        [51004012] = {
            ["Camera"] = "-415.09082,-71.93457,95.116699,0.000026,0.0,13.207663,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "她居然骂人？！她疯了吧？",
            ["ContentFR"] = "Elle nous insulte ?! Elle a perdu la tête ?!",
            ["DialogueId"] = 51004012,
            ["GUID"] = "7FAEE5B8",
            ["NextDialogue"] = 51004013,
            ["SpeakNpcId"] = 700088,
            ["TalkActionId"] = {
                [1] = "700088:Confident_Start",
                },
            ["TurnTo"] = {
                [1] = "700089:n(700104)",
                },
            },
        [51004013] = {
            ["Camera"] = "-415.09082,-71.93457,95.116699,0.000026,0.0,13.207663,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "气死我了！来人啊，给我教训教训她，让我满意了这些钱就都是你们的！",
            ["ContentFR"] = "Assez ! Que quelqu’un lui donne une bonne leçon ! Et je paie bien, alors que ce soit fait correctement !",
            ["DialogueId"] = 51004013,
            ["GUID"] = "7FAEE5E2",
            ["SpeakNpcId"] = 700089,
            ["TalkActionId"] = {
                [1] = "700089:Angry01_Start",
                },
            },
        [51004101] = {
            ["Camera"] = "-342.361328,156.479492,90.07373,0.0,0.0,-33.384811,20.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "这个白头发的，不好惹啊！",
            ["ContentFR"] = "{性别:Ce Charon aux cheveux blancs... il est trop fort !|Cette Charon aux cheveux blancs... elle est trop forte !}",
            ["DialogueId"] = 51004101,
            ["GUID"] = "7FAEF452",
            ["NextDialogue"] = 51004102,
            ["SpeakNpcId"] = 700088,
            ["TalkActionId"] = {
                [1] = "700088:Sigh_Start",
                [2] = "700089:Shock_Start",
                },
            },
        [51004102] = {
            ["Camera"] = "-342.361328,156.479492,90.07373,0.0,0.0,-33.384811,20.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "喂……情况好像不太妙啊！我们还是先回去吧！",
            ["ContentFR"] = "Ça tourne mal... On ferait mieux de rentrer !",
            ["DialogueId"] = 51004102,
            ["GUID"] = "7FAEF47C",
            ["LookAt"] = {
                [1] = "700089:n(700088)",
                },
            ["NextDialogue"] = 51004103,
            ["SpeakNpcId"] = 700089,
            },
        [51004103] = {
            ["Camera"] = "-97.533691,-5.197266,119.393066,0.000077,-0.399996,173.011871,20.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "等等。",
            ["ContentFR"] = "Attendez.",
            ["DialogueId"] = 51004103,
            ["GUID"] = "7FAEF4A6",
            ["NextDialogue"] = 51004104,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Talk03_Start",
                },
            },
        [51004104] = {
            ["Camera"] = "-97.533691,-5.197266,119.393066,0.000077,-0.399996,173.011871,20.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "费伊已经和我这个恶魔签了一份协议，如果你们再找她的麻烦，我会在一分钟之内出现在你们面前。",
            ["ContentFR"] = "Faye a conclu un pacte démoniaque avec moi. Si vous l’embêtez encore, j’apparaîtrai dans la minute pour vous régler votre compte.",
            ["DialogueId"] = 51004104,
            ["GUID"] = "7FAEF4D0",
            ["NextDialogue"] = 51004105,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "700088:Sigh_End",
                },
            },
        [51004105] = {
            ["Camera"] = "-199.681152,34.707031,99.213867,0.000074,-2.198085,-15.786639,20.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "你……你……哼！",
            ["ContentFR"] = "Tu... tu... pff !",
            ["DialogueId"] = 51004105,
            ["GUID"] = "7FAEF4FA",
            ["SpeakNpcId"] = 700088,
            ["TalkActionId"] = {
                [1] = "700088:Angry01_Start",
                },
            },
        [51004106] = {
            ["Content"] = "学生们一溜烟逃走了。",
            ["ContentFR"] = "Les élèves détalent aussitôt.",
            ["DialogueId"] = 51004106,
            ["GUID"] = "7FAEF524",
            },
        [51004107] = {
            ["Content"] = "你看，他们的胆量不过如此。",
            ["ContentFR"] = "Tu vois ? Ce n’est que du vent.",
            ["DialogueId"] = 51004107,
            ["GUID"] = "7FAEF54E",
            ["NextDialogue"] = 51004108,
            ["SpeakNpcId"] = 100001,
            },
        [51004108] = {
            ["Content"] = "……嗯！",
            ["ContentFR"] = "... Oui !",
            ["DialogueId"] = 51004108,
            ["GUID"] = "7FAEF578",
            ["NextDialogue"] = 51004109,
            ["SpeakNpcId"] = 700105,
            ["TalkActionId"] = {
                [1] = "700105:Agree",
                },
            },
        [51004109] = {
            ["Content"] = "多亏了有你在……你抡起拳头的样子真的很威风呢！",
            ["ContentFR"] = "Merci... {性别:Quand tu t’es battu, tu avais l’air tellement puissant !|Quand tu t’es battue, tu avais l’air tellement puissante !}",
            ["DialogueId"] = 51004109,
            ["GUID"] = "7FAEF5A2",
            ["NextOptions"] = {
                [1] = 510041091,
                [2] = 510041092,
                },
            ["SpeakNpcId"] = 700105,
            ["bForbidSkipOptions"] = true,
            },
        [51004110] = {
            ["Content"] = "诶，是、是吗？我只是……把以前偷偷在心里想的话说出来了。",
            ["ContentFR"] = "Hein... Vraiment ? Je... J’ai seulement dit tout haut ce que je pensais en silence.",
            ["DialogueId"] = 51004110,
            ["GUID"] = "7FAEF5CC",
            ["NextDialogue"] = 51004111,
            ["SpeakNpcId"] = 700105,
            ["TalkActionId"] = {
                [1] = "700105:Shock_Start",
                },
            },
        [51004111] = {
            ["Content"] = "谢谢你，我长这么大，还是头一次心里这么畅快呢！",
            ["ContentFR"] = "Merci ! C’est la première fois que je me sens aussi soulagée et libre !",
            ["DialogueId"] = 51004111,
            ["GUID"] = "7FAEF5F6",
            ["NextDialogue"] = 51004112,
            ["SpeakNpcId"] = 700105,
            ["TalkActionId"] = {
                [1] = "700105:Shock_End",
                },
            },
        [51004112] = {
            ["Content"] = "不用谢，他们短时间应该不会来找你麻烦了，我送你回家吧。这是我的地址——如果他们再惹你，就来找我。",
            ["ContentFR"] = "Pas de quoi. Ils ne t’approcheront pas avant longtemps. Je vais te raccompagner. Voilà mon adresse, s’ils reviennent, viens me trouver.",
            ["DialogueId"] = 51004112,
            ["GUID"] = "7FAEF620",
            ["NextDialogue"] = 51004113,
            ["SpeakNpcId"] = 100001,
            },
        [51004113] = {
            ["Content"] = "我不想回家……！",
            ["ContentFR"] = "Je ne veux pas rentrer... !",
            ["DialogueId"] = 51004113,
            ["GUID"] = "7FAEF64A",
            ["NextDialogue"] = 51004114,
            ["SpeakNpcId"] = 700105,
            ["TalkActionId"] = {
                [1] = "700105:Disagree",
                },
            },
        [51004114] = {
            ["Content"] = "我是卡戎，我要和卡戎之民待在一起……",
            ["ContentFR"] = "Je suis une Charon. Je veux rester avec les miens...",
            ["DialogueId"] = 51004114,
            ["GUID"] = "7FAEF674",
            ["NextOptions"] = {
                [1] = 510041141,
                },
            ["RestartTag"] = 51004114,
            ["SpeakNpcId"] = 700105,
            ["TalkActionId"] = {
                [1] = "700105:Agree",
                },
            ["bForbidSkipOptions"] = true,
            },
        [51004115] = {
            ["Content"] = "（女孩固执地噘着嘴，并没有被你说服。）",
            ["ContentFR"] = "La fille boude avec entêtement. Tes paroles ne l’ont pas touchée.",
            ["DialogueId"] = 51004115,
            ["GUID"] = "7FAEF69E",
            },
        [51004116] = {
            ["Content"] = "还没看清他们吗？他们平日里对着你威风凛凛，但真的有人比他们拳头更硬的时候，他们就会落荒而逃。",
            ["ContentFR"] = "Tu n’as pas remarqué ? Ils jouent les durs, mais dès qu’ils tombent sur plus fort, ils fuient.",
            ["DialogueId"] = 51004116,
            ["GUID"] = "7FAEF6C8",
            ["NextDialogue"] = 51004117,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "700105:Think_Start",
                },
            },
        [51004117] = {
            ["Content"] = "他们不像自己表现得那么强大。所以，他们嘴里说的自然也不是事实。费伊，你是如假包换的索拉之民，不要被他们蹩脚的谎言骗了。",
            ["ContentFR"] = "Ils ne sont pas aussi puissants qu’ils le prétendent. Alors, pourquoi leurs mots seraient-ils vrais ? Faye, tu es une Sola, ne te laisse pas avoir par leurs minables mensonges.",
            ["DialogueId"] = 51004117,
            ["GUID"] = "7FAEF6F2",
            ["NextDialogue"] = 51004118,
            ["SpeakNpcId"] = 100001,
            },
        [51004118] = {
            ["Content"] = "记住，永远不要因为别人的恶意质疑自己，责备自己……这是我的家人教会我的，我也把它教给你。",
            ["ContentFR"] = "Souviens-toi, ne doute jamais de toi à cause de la méchanceté des autres. Ne te reproche rien... C’est ma famille qui me l’a appris, et aujourd’hui je te transmets cette leçon.",
            ["DialogueId"] = 51004118,
            ["GUID"] = "7FAEF71C",
            ["NextDialogue"] = 51004119,
            ["SpeakNpcId"] = 100001,
            },
        [51004119] = {
            ["Content"] = "（女孩略带困惑地眨了眨眼，似乎还不能完全理解你话语的含义，但是表情却有所缓和。）",
            ["ContentFR"] = "La fille bat des cils, un peu perdue. Elle ne comprend pas tout, mais son visage s’apaise.",
            ["DialogueId"] = 51004119,
            ["GUID"] = "7FAEF746",
            ["NextDialogue"] = 51004120,
            },
        [51004120] = {
            ["Content"] = "好吧……既然你这么说的话，我会努力试试看的！但在那之前，我还有最后一个小小的请求……",
            ["ContentFR"] = "D’accord... puisque tu le dis, je vais essayer ! Mais avant... j’ai une dernière petite demande...",
            ["DialogueId"] = 51004120,
            ["GUID"] = "7FAEF770",
            ["NextDialogue"] = 51004121,
            ["SpeakNpcId"] = 700105,
            ["TalkActionId"] = {
                [1] = "700105:Think_End",
                },
            },
        [51004121] = {
            ["Content"] = "可以让我摸一下你的角吗？",
            ["ContentFR"] = "Est-ce que je peux toucher ta corne ?",
            ["DialogueId"] = 51004121,
            ["GUID"] = "7FAEF79A",
            ["NextOptions"] = {
                [1] = 510041211,
                [2] = 510041212,
                },
            ["SpeakNpcId"] = 700105,
            ["TalkActionId"] = {
                [1] = "700105:Explain02_Start",
                },
            ["bForbidSkipOptions"] = true,
            },
        [51004122] = {
            ["Content"] = "谢谢！",
            ["ContentFR"] = "Merci !",
            ["DialogueId"] = 51004122,
            ["GUID"] = "7FAEF7C4",
            ["NextDialogue"] = 51004123,
            ["SpeakNpcId"] = 700105,
            ["TalkActionId"] = {
                [1] = "700105:Explain02_End",
                },
            },
        [51004123] = {
            ["Content"] = "（女孩小心翼翼地伸出纤瘦的手，摸了摸你头上的角。）",
            ["ContentFR"] = "La fille tend une main délicate et touche prudemment la corne sur ta tête.",
            ["DialogueId"] = 51004123,
            ["GUID"] = "7FAEF7EE",
            ["NextDialogue"] = 51004126,
            },
        [51004124] = {
            ["Content"] = "好吧，那我不摸，就看一看……",
            ["ContentFR"] = "Bon... alors, laisse-moi au moins la regarder de près...",
            ["DialogueId"] = 51004124,
            ["GUID"] = "7FAEF818",
            ["NextDialogue"] = 51004125,
            ["SpeakNpcId"] = 700105,
            ["TalkActionId"] = {
                [1] = "700105:Explain02_End",
                },
            },
        [51004125] = {
            ["Content"] = "（女孩小心翼翼地凑上来，仔细地打量着你头上的角。）",
            ["ContentFR"] = "La fille s’approche et observe attentivement ta corne.",
            ["DialogueId"] = 51004125,
            ["GUID"] = "7FAEF842",
            ["NextDialogue"] = 51004126,
            },
        [51004126] = {
            ["Content"] = "原来真正的角，是这样的啊……",
            ["ContentFR"] = "Alors c’est ça, une vraie corne de Charon...",
            ["DialogueId"] = 51004126,
            ["GUID"] = "7FAEF86C",
            ["NextDialogue"] = 51004127,
            ["SpeakNpcId"] = 700105,
            },
        [51004127] = {
            ["Content"] = "红色的，很精巧……还会反射阳光呢。确实比我的辫子要可爱多了。",
            ["ContentFR"] = "Rouge, fine... Elle brille au soleil... Elle est bien plus jolie que mes tresses.",
            ["DialogueId"] = 51004127,
            ["GUID"] = "7FAEF896",
            ["NextOptions"] = {
                [1] = 510041271,
                },
            ["SpeakNpcId"] = 700105,
            ["bForbidSkipOptions"] = true,
            },
        [51004128] = {
            ["Content"] = "你是第一个这么说的人。但它们现在都被弄乱了……我要重新梳好才行。",
            ["ContentFR"] = "Tu es {性别:le premier|la première} à me le dire. Mais elles sont toutes défaites... Je vais les refaire.",
            ["DialogueId"] = 51004128,
            ["GUID"] = "7FAEF8C0",
            ["NextDialogue"] = 51004129,
            ["SpeakNpcId"] = 700105,
            ["TalkActionId"] = {
                [1] = "700105:Explain01_Start",
                },
            },
        [51004129] = {
            ["Content"] = "（女孩从书包里找出一把梳子，认真地将头上的两条辫子重新梳好，然后将它们向上提起来，比划出角的样子。）",
            ["ContentFR"] = "Elle sort un peigne, refait soigneusement ses deux tresses, puis les soulève pour les faire ressembler à des cornes.",
            ["DialogueId"] = 51004129,
            ["GUID"] = "7FAEF8EA",
            ["NextDialogue"] = 51004130,
            ["TalkActionId"] = {
                [1] = "700105:Explain01_End",
                },
            },
        [51004130] = {
            ["Content"] = "这样像不像恶魔角？",
            ["ContentFR"] = "Comme ça, ça fait cornes de démon ?",
            ["DialogueId"] = 51004130,
            ["GUID"] = "7FAEF914",
            ["NextOptions"] = {
                [1] = 510041301,
                [2] = 510041302,
                },
            ["SpeakNpcId"] = 700105,
            ["bForbidSkipOptions"] = true,
            },
        [51004131] = {
            ["Content"] = "嘿嘿。",
            ["ContentFR"] = "Héhé.",
            ["DialogueId"] = 51004131,
            ["GUID"] = "7FAEF93E",
            ["NextDialogue"] = 51004133,
            ["SpeakNpcId"] = 700105,
            },
        [51004132] = {
            ["Content"] = "哈哈，那也不错。",
            ["ContentFR"] = "Haha, c’est bien aussi.",
            ["DialogueId"] = 51004132,
            ["GUID"] = "7FAEF968",
            ["NextDialogue"] = 51004133,
            ["SpeakNpcId"] = 700105,
            ["TalkActionId"] = {
                [1] = "700105:Agree",
                },
            },
        [51004133] = {
            ["Content"] = "啊，我口袋里还有多的发圈呢，要不要给你也扎个小辫子？",
            ["ContentFR"] = "Oh ! J’ai encore des élastiques. Je peux te faire une petite tresse ?",
            ["DialogueId"] = 51004133,
            ["GUID"] = "7FAEF992",
            ["NextOptions"] = {
                [1] = 510041331,
                [2] = 510041332,
                },
            ["SpeakNpcId"] = 700105,
            ["bForbidSkipOptions"] = true,
            },
        [51004134] = {
            ["Content"] = "就扎一下让我看看嘛！",
            ["ContentFR"] = "Allez, juste un essai !",
            ["DialogueId"] = 51004134,
            ["GUID"] = "7FAEF9BC",
            ["NextDialogue"] = 51004135,
            ["SpeakNpcId"] = 700105,
            },
        [51004135] = {
            ["Content"] = "（女孩不由分说地踮起脚尖，试图把你按到一个她能够得到的位置。看来，她已经精神多了。）",
            ["ContentFR"] = "La fille se met sur la pointe des pieds pour atteindre tes cheveux. Elle paraît nettement plus joyeuse.",
            ["DialogueId"] = 51004135,
            ["GUID"] = "7FAEF9E6",
            ["NextDialogue"] = 51004136,
            },
        [51004136] = {
            ["Content"] = "来，稍微蹲下一些……",
            ["ContentFR"] = "Accroupis-toi un peu...",
            ["DialogueId"] = 51004136,
            ["GUID"] = "7FAEFA10",
            ["NextDialogue"] = 51004137,
            ["SpeakNpcId"] = 700105,
            ["TalkActionId"] = {
                [1] = "700105:Explain01_Start",
                },
            },
        [51004137] = {
            ["Content"] = "（你感到脑后的发丝被人轻轻地揪住了。女孩梳头的动作非常温柔，看来不用担心发际线受到伤害了。）",
            ["ContentFR"] = "Tu sens une légère traction sur ta nuque. Elle coiffe avec douceur, rien à craindre pour ta chevelure.",
            ["DialogueId"] = 51004137,
            ["GUID"] = "7FAEFA3A",
            ["NextDialogue"] = 51004138,
            ["TalkActionId"] = {
                [1] = "700105:Explain01_End",
                },
            },
        [51004138] = {
            ["Content"] = "好了！哇，你扎辫子的样子好可爱！",
            ["ContentFR"] = "Voilà ! Ouah, tu es tellement {性别:mignon|mignonne} avec des tresses !",
            ["DialogueId"] = 51004138,
            ["GUID"] = "7FAEFA64",
            ["NextDialogue"] = 51004139,
            ["SpeakNpcId"] = 700105,
            ["TalkActionId"] = {
                [1] = "700105:Agree",
                },
            },
        [51004139] = {
            ["Content"] = "可惜我没有带镜子……",
            ["ContentFR"] = "Dommage, je n’ai pas de miroir...",
            ["DialogueId"] = 51004139,
            ["GUID"] = "7FAEFA8E",
            ["NextDialogue"] = 51004140,
            ["SpeakNpcId"] = 700105,
            ["TalkActionId"] = {
                [1] = "700105:Think_Start",
                },
            },
        [51004140] = {
            ["Content"] = "啊……我想到了！我可以画出来。",
            ["ContentFR"] = "Oh ! Je sais ! Je vais te dessiner.",
            ["DialogueId"] = 51004140,
            ["GUID"] = "7FAEFAB8",
            ["NextDialogue"] = 51004141,
            ["SpeakNpcId"] = 700105,
            ["TalkActionId"] = {
                [1] = "700105:Think_End",
                },
            },
        [51004141] = {
            ["Content"] = "（女孩打开书包，在笔记本上认真画着你的样子。）",
            ["ContentFR"] = "Elle sort un cahier de son sac et esquisse ton portrait.",
            ["DialogueId"] = 51004141,
            ["GUID"] = "7FAEFAE2",
            ["NextDialogue"] = 51004142,
            },
        [51004142] = {
            ["Content"] = "对了，你叫什么名字呀？",
            ["ContentFR"] = "Au fait... comment tu t’appelles ?",
            ["DialogueId"] = 51004142,
            ["GUID"] = "7FAEFB0C",
            ["NextOptions"] = {
                [1] = 510041421,
                },
            ["SpeakNpcId"] = 700105,
            ["bForbidSkipOptions"] = true,
            },
        [51004143] = {
            ["Content"] = "嗯！{nickname}，我会一直一直记住你的。给，这是我给你画的画像，再见！",
            ["ContentFR"] = "Très bien ! {nickname}, je n’oublierai jamais ton nom. Tiens, garde ce dessin de toi que j’ai fait. À bientôt !",
            ["DialogueId"] = 51004143,
            ["GUID"] = "7FAEFB36",
            ["NextDialogue"] = 51004144,
            ["SpeakNpcId"] = 700105,
            ["TalkActionId"] = {
                [1] = "700105:Agree",
                },
            },
        [51004144] = {
            ["Content"] = "……太神秘了，这就是城里人的艺术吗……",
            ["ContentFR"] = "... Mmmh... C’est donc ça l’art abstrait.",
            ["DialogueId"] = 51004144,
            ["GUID"] = "7FAEFB60",
            ["NextDialogue"] = 51004145,
            ["SpeakNpcId"] = 100001,
            },
        [51004145] = {
            ["Content"] = "（女孩正准备离开，忽然又回过头，认真地看向你。）",
            ["ContentFR"] = "Alors qu’elle s’éloigne, la fille se retourne soudain, le regard grave.",
            ["DialogueId"] = 51004145,
            ["GUID"] = "7FAEFB8A",
            ["NextDialogue"] = 51004146,
            },
        [51004146] = {
            ["Content"] = "对了……刚才给你梳头的时候，我突然想到一件事。",
            ["ContentFR"] = "Au fait... Quand je t’ai coiffé, j’ai repensé à quelque chose.",
            ["DialogueId"] = 51004146,
            ["GUID"] = "7FAEFBB4",
            ["NextDialogue"] = 51004147,
            ["SpeakNpcId"] = 700105,
            },
        [51004147] = {
            ["Content"] = "他们一直都告诉我，卡戎是恶魔的孩子，是脑袋笨笨又一肚子坏水的，总是在做坏事的……",
            ["ContentFR"] = "On m’a toujours répété que les Charons étaient des enfants de démons, stupides, perfides, toujours à faire le mal...",
            ["DialogueId"] = 51004147,
            ["GUID"] = "7FAEFBDE",
            ["NextDialogue"] = 51004148,
            ["SpeakNpcId"] = 700105,
            ["TalkActionId"] = {
                [1] = "700105:Explain01_Start",
                },
            },
        [51004148] = {
            ["Content"] = "这些话……其实也不是真的吧？",
            ["ContentFR"] = "Mais ce n’est pas vrai, pas vrai ?",
            ["DialogueId"] = 51004148,
            ["GUID"] = "7FAEFC08",
            ["NextDialogue"] = 51004149,
            ["SpeakNpcId"] = 700105,
            ["TalkActionId"] = {
                [1] = "700105:Explain01_End",
                },
            },
        [51004149] = {
            ["Content"] = "那也是他们用来欺负你们的借口，对不对？",
            ["ContentFR"] = "C’est juste un prétexte pour vous harceler... n’est-ce pas ?",
            ["DialogueId"] = 51004149,
            ["GUID"] = "7FAEFC32",
            ["NextOptions"] = {
                [1] = 510041491,
                [2] = 510041492,
                },
            ["SpeakNpcId"] = 700105,
            ["TalkActionId"] = {
                [1] = "700105:Confident_Start",
                },
            ["bForbidSkipOptions"] = true,
            },
        [51004150] = {
            ["Content"] = "你们一定……承受了比我多得多的痛苦吧。",
            ["ContentFR"] = "Alors vous avez sûrement... souffert bien plus que moi.",
            ["DialogueId"] = 51004150,
            ["GUID"] = "7FAEFC5C",
            ["NextDialogue"] = 51004151,
            ["SpeakNpcId"] = 700105,
            ["TalkActionId"] = {
                [1] = "700105:Confident_End",
                },
            },
        [51004151] = {
            ["Content"] = "今后，如果有什么我能帮得上忙的事，请尽管说……不是因为我们是同类，而是因为我们是朋友。",
            ["ContentFR"] = "Désormais, si je peux faire quoi que ce soit pour aider, je le ferai. Pas parce que nous sommes pareils... mais parce que nous sommes {性别:amis|amies}.",
            ["DialogueId"] = 51004151,
            ["GUID"] = "7FAEFC86",
            ["SpeakNpcId"] = 700105,
            ["TalkActionId"] = {
                [1] = "700105:Explain02_Start",
                },
            },
        [51004152] = {
            ["Content"] = "同学们还是不喜欢我，但现在我已经不怕他们了！这都是多亏了你！",
            ["ContentFR"] = "Mes camarades ne m’aiment toujours pas... mais je n’ai plus peur d’eux ! Tout ça, c’est grâce à toi !",
            ["DialogueId"] = 51004152,
            ["GUID"] = "7FAEFCB0",
            ["SpeakNpcId"] = 700105,
            },
        [51004201] = {
            ["Content"] = "啧，生面孔啊。",
            ["ContentFR"] = "Pff. Une nouvelle tête.",
            ["DialogueId"] = 51004201,
            ["GUID"] = "7FAF04BA",
            ["NextDialogue"] = 51004202,
            ["SpeakNpcId"] = 700096,
            ["TalkActionId"] = {
                [1] = "700096:Talk03_Start",
                },
            },
        [51004202] = {
            ["Content"] = "（眼前的男人眯起眼，抿了抿嘴唇上锐利的裂口，吐出干燥的话语。）",
            ["ContentFR"] = "L’homme en face de toi plisse les yeux, ses lèvres fendues et sèches s’étirent tandis qu’il recrache des mots arides.",
            ["DialogueId"] = 51004202,
            ["GUID"] = "7FAF04E4",
            ["NextDialogue"] = 51004203,
            },
        [51004203] = {
            ["Content"] = "说说吧，谁介绍你来的？",
            ["ContentFR"] = "Alors, dis-moi. Qui t’envoie ici ?",
            ["DialogueId"] = 51004203,
            ["GUID"] = "7FAF050E",
            ["NextOptions"] = {
                [1] = 510042031,
                [2] = 510042032,
                [3] = 510042033,
                },
            ["SpeakNpcId"] = 700096,
            ["TalkActionId"] = {
                [1] = "700096:Talk03_End",
                },
            ["bForbidSkipOptions"] = true,
            },
        [51004204] = {
            ["Content"] = "（一个新的问题，才是最好的回答。）",
            ["ContentFR"] = "Une nouvelle question est parfois la meilleure des réponses.",
            ["DialogueId"] = 51004204,
            ["GUID"] = "7FAF0538",
            ["NextDialogue"] = 51004207,
            },
        [51004205] = {
            ["Content"] = "（“介绍”？很明显，他是在等什么人。）",
            ["ContentFR"] = "Il est évident qu’il attend quelqu’un.",
            ["DialogueId"] = 51004205,
            ["GUID"] = "7FAF0562",
            ["NextDialogue"] = 51004207,
            },
        [51004206] = {
            ["Content"] = "（不知道他在问什么，但没人会拒绝这个回答。）",
            ["ContentFR"] = "Tu ignores ce qu’il voulait entendre, mais personne ne refuse jamais ce genre de réponse.",
            ["DialogueId"] = 51004206,
            ["GUID"] = "7FAF058C",
            ["NextDialogue"] = 51004207,
            },
        [51004207] = {
            ["Content"] = "（男人沉默了一阵，抬眼打量起你来，几乎能听见他抬头时脊椎疲惫地的异响。）",
            ["ContentFR"] = "L’homme reste un instant silencieux, puis lève les yeux pour t’observer. Tu entends presque ses vertèbres craquer sous l’effort.",
            ["DialogueId"] = 51004207,
            ["GUID"] = "7FAF05B6",
            ["NextDialogue"] = 51004208,
            },
        [51004208] = {
            ["Content"] = "碎嘴子。",
            ["ContentFR"] = "{性别:Beau parleur|Fine parleuse}.",
            ["DialogueId"] = 51004208,
            ["GUID"] = "7FAF05E0",
            ["NextDialogue"] = 51004209,
            ["SpeakNpcId"] = 700096,
            ["TalkActionId"] = {
                [1] = "700096:Disagree",
                },
            },
        [51004209] = {
            ["Content"] = "（他轻哼了一声，又似乎很满意你的回答。）",
            ["ContentFR"] = "Il émet un bref grognement, mais son expression semble trahir une certaine satisfaction.",
            ["DialogueId"] = 51004209,
            ["GUID"] = "7FAF060A",
            ["NextDialogue"] = 51004210,
            },
        [51004210] = {
            ["Content"] = "不管是谁介绍你来的，反正也是为了我口袋里的货，对吧？",
            ["ContentFR"] = "Peu importe qui t’a recommandé. De toute façon, tu es là pour ce que j’ai dans ma poche, pas vrai ?",
            ["DialogueId"] = 51004210,
            ["GUID"] = "7FAF0634",
            ["NextDialogue"] = 51004211,
            ["SpeakNpcId"] = 700096,
            ["TalkActionId"] = {
                [1] = "700096:Confident_Start",
                },
            },
        [51004211] = {
            ["Content"] = "（男人扯开衣领，黯淡的金属管自怀中闪过。）",
            ["ContentFR"] = "Il entrouvre son col, laissant entrevoir le reflet terne d’un canon métallique.",
            ["DialogueId"] = 51004211,
            ["GUID"] = "7FAF065E",
            ["NextDialogue"] = 51004212,
            ["TalkActionId"] = {
                [1] = "700096:Confident_End",
                },
            },
        [51004212] = {
            ["Content"] = "（他立刻收紧了衣领，警惕地望了望四周。）",
            ["ContentFR"] = "Il resserre aussitôt son manteau et jette un regard méfiant autour de lui.",
            ["DialogueId"] = 51004212,
            ["GUID"] = "7FAF0688",
            ["NextDialogue"] = 51004213,
            },
        [51004213] = {
            ["Content"] = "4号口径，双管单发，不论是卡戎人还是秽兽，在它面前都走不过两下。",
            ["ContentFR"] = "Calibre 4. Double canon, un seul tir. Qu’il s’agisse d’un Charon ou d’un Souillé, personne ne résiste à ça.",
            ["DialogueId"] = 51004213,
            ["GUID"] = "7FAF06B2",
            ["NextDialogue"] = 51004214,
            ["SpeakNpcId"] = 700096,
            },
        [51004214] = {
            ["Content"] = "（男人撇了撇嘴，像在谈论农用杀虫剂的功效。）",
            ["ContentFR"] = "Ses lèvres se tordent, comme s’il parlait d’un banal pesticide.",
            ["DialogueId"] = 51004214,
            ["GUID"] = "7FAF06DC",
            ["NextDialogue"] = 51004215,
            },
        [51004215] = {
            ["Content"] = "这回的货不要钱，只要你帮我办件事。",
            ["ContentFR"] = "Cette fois, pas besoin d’argent. Mais tu vas devoir faire quelque chose pour moi.",
            ["DialogueId"] = 51004215,
            ["GUID"] = "7FAF0706",
            ["NextOptions"] = {
                [1] = 510042151,
                [2] = 510042152,
                },
            ["SpeakNpcId"] = 700096,
            ["bForbidSkipOptions"] = true,
            },
        [51004216] = {
            ["Content"] = "哆嗦什么？你不就是冲着这玩意来的吗？",
            ["ContentFR"] = "Qu’est-ce que tu bafouilles ? T’es venu pour ce joujou, non ?",
            ["DialogueId"] = 51004216,
            ["GUID"] = "7FAF0730",
            ["NextDialogue"] = 51004217,
            ["SpeakNpcId"] = 700096,
            ["TalkActionId"] = {
                [1] = "700096:Explain01_Start",
                },
            },
        [51004217] = {
            ["Content"] = "事儿办利索了，不仅东西归你，我再追补给你一笔。",
            ["ContentFR"] = "Si tu t’acquittes de la tâche, il est à toi. Et je rajoute même une prime.",
            ["DialogueId"] = 51004217,
            ["GUID"] = "7FAF075A",
            ["NextOptions"] = {
                [1] = 510042171,
                [2] = 510042172,
                },
            ["RestartTag"] = 51004216,
            ["SpeakNpcId"] = 700096,
            ["TalkActionId"] = {
                [1] = "700096:Explain01_End",
                },
            ["bForbidSkipOptions"] = true,
            },
        [51004218] = {
            ["Content"] = "想快点，我等不了你太久。",
            ["ContentFR"] = "Dépêche-toi. J’ai pas toute la journée.",
            ["DialogueId"] = 51004218,
            ["GUID"] = "7FAF0784",
            ["SpeakNpcId"] = 700096,
            },
        [51004219] = {
            ["Content"] = "好吧，你要我做什么？",
            ["ContentFR"] = "Bon, d’accord. Qu’est-ce que tu veux que je fasse ?",
            ["DialogueId"] = 51004219,
            ["GUID"] = "7FAF07AE",
            ["NextDialogue"] = 51004220,
            ["SpeakNpcId"] = 100001,
            },
        [51004220] = {
            ["Content"] = "爽快，一会儿我给你个地方，目标就是那地方除了女人之外的东西都清了。",
            ["ContentFR"] = "Parfait. Je vais te donner un lieu. Là-bas, dégomme tout le monde sauf la femme.",
            ["DialogueId"] = 51004220,
            ["GUID"] = "7FAF07D8",
            ["NextDialogue"] = 51004221,
            ["SpeakNpcId"] = 700096,
            ["TalkActionId"] = {
                [1] = "700096:Agree",
                },
            },
        [51004221] = {
            ["Content"] = "这……感情问题……？",
            ["ContentFR"] = "... Une histoire de cœur ?",
            ["DialogueId"] = 51004221,
            ["GUID"] = "7FAF0802",
            ["NextDialogue"] = 51004222,
            ["SpeakNpcId"] = 100001,
            },
        [51004222] = {
            ["Content"] = "别多嘴。",
            ["ContentFR"] = "Mêle-toi de tes affaires. Fais juste le travail.",
            ["DialogueId"] = 51004222,
            ["GUID"] = "7FAF082C",
            ["NextDialogue"] = 51004223,
            ["SpeakNpcId"] = 700096,
            ["TalkActionId"] = {
                [1] = "700096:Disagree",
                },
            },
        [51004223] = {
            ["Content"] = "(男人紧了紧衣领，抿住干瘪的嘴唇，不愿再吐出任何一个字。)",
            ["ContentFR"] = "Il resserre son col et pince ses lèvres sèches, refusant de dire un mot de plus.",
            ["DialogueId"] = 51004223,
            ["GUID"] = "7FAF0856",
            },
        [51004301] = {
            ["Content"] = "行啊，收了钱就走吧，我不希望在这附近见到你。",
            ["ContentFR"] = "Bien joué. Prends ton argent et pars. Je ne veux plus te voir dans le coin.",
            ["DialogueId"] = 51004301,
            ["GUID"] = "7FAF1522",
            ["NextDialogue"] = 51004302,
            ["SpeakNpcId"] = 700101,
            ["TalkActionId"] = {
                [1] = "700101:Agree",
                },
            },
        [51004302] = {
            ["Content"] = "你是想找人清理附近的秽兽？就算不雇佣我，也会有人处理那些秽兽的。",
            ["ContentFR"] = "Tout ça, c’était juste pour que je nettoie les Souillés du coin ? Même sans moi, quelqu’un aurait fini par s’en occuper.",
            ["DialogueId"] = 51004302,
            ["GUID"] = "7FAF154C",
            ["NextDialogue"] = 51004303,
            ["SpeakNpcId"] = 100001,
            },
        [51004303] = {
            ["Content"] = "有人处理？谁？那群把卡戎人当狗的杂碎？",
            ["ContentFR"] = "Quelqu’un ? Tu veux dire ces pourritures en uniforme, qui traitent les Charons comme des chiens ?",
            ["DialogueId"] = 51004303,
            ["GUID"] = "7FAF1576",
            ["NextDialogue"] = 51004304,
            ["SpeakNpcId"] = 700101,
            ["TalkActionId"] = {
                [1] = "700101:Angry01_Start",
                },
            },
        [51004304] = {
            ["Content"] = "你猜猜他们到时候打开门，发现这里住的是一个卡戎女人，他们会怎么办？",
            ["ContentFR"] = "Imagine-les découvrir qu’ici vit une femme Charon, seule, frêle. Tu crois qu’ils feraient quoi ?",
            ["DialogueId"] = 51004304,
            ["GUID"] = "7FAF15A0",
            ["NextDialogue"] = 51004305,
            ["SpeakNpcId"] = 700101,
            ["TalkActionId"] = {
                [1] = "700101:Angry01_End",
                },
            },
        [51004305] = {
            ["Content"] = "（男人突然捂紧胸口，浑身战栗起来，像是伤口被扯痛一般。好一阵，他才止住颤抖，偏过头，吐出一口唾沫钉在地上。）",
            ["ContentFR"] = "Soudain, il porte la main à sa poitrine. Son corps tremble, comme si une vieille blessure s’était réveillée. Après de longues secondes, il reprend son souffle, détourne la tête et crache au sol.",
            ["DialogueId"] = 51004305,
            ["GUID"] = "7FAF15CA",
            ["NextDialogue"] = 51004306,
            },
        [51004306] = {
            ["Content"] = "一个善良的卡戎女人，为了救一个重伤躺在路边的陌生人，砸伤了内城跑出来的烈犬。",
            ["ContentFR"] = "Une femme Charon, compatissante, qui a lancé des pierres sur un molosse échappé de la cité intérieure pour protéger un étranger blessé.",
            ["DialogueId"] = 51004306,
            ["GUID"] = "7FAF15F4",
            ["NextDialogue"] = 51004307,
            ["SpeakNpcId"] = 700101,
            },
        [51004307] = {
            ["Content"] = "就因为这点事，她被毒打一顿，拖出冰湖城的门，丢到这荒地里。",
            ["ContentFR"] = "Pour ça, ils l’ont battue à mort, traînée jusqu’aux portes de Givrelac et jetée ici, dans cette terre désolée.",
            ["DialogueId"] = 51004307,
            ["GUID"] = "7FAF161E",
            ["NextDialogue"] = 51004308,
            ["SpeakNpcId"] = 700101,
            },
        [51004308] = {
            ["Content"] = "这……也许你可以想办法帮她离开冰湖城，换个地方生活。",
            ["ContentFR"] = "... Tu pourrais peut-être trouver un moyen de la faire partir, lui offrir une autre vie loin d’ici.",
            ["DialogueId"] = 51004308,
            ["GUID"] = "7FAF1648",
            ["NextDialogue"] = 51004309,
            ["SpeakNpcId"] = 100001,
            },
        [51004309] = {
            ["Content"] = "……快了，快攒够了。",
            ["ContentFR"] = "... Bientôt. Je touche au but. Bientôt j’aurai assez d’argent.",
            ["DialogueId"] = 51004309,
            ["GUID"] = "7FAF1672",
            ["NextDialogue"] = 51004310,
            ["SpeakNpcId"] = 700101,
            ["TalkActionId"] = {
                [1] = "700101:Agree",
                },
            },
        [51004310] = {
            ["Content"] = "（男人转过身，面向帐篷的方向，僵硬的嘴角罕见地被撬开了一瞬，露出类似笑容的表情。）",
            ["ContentFR"] = "Il se tourne vers la tente. Ses lèvres raides se soulèvent l’espace d’un instant, esquissant un sourire rare.",
            ["DialogueId"] = 51004310,
            ["GUID"] = "7FAF169C",
            ["LookAt"] = {
                [1] = "700101:n(700100)",
                },
            ["NextDialogue"] = 51004311,
            ["TurnTo"] = {
                [1] = "700101:n(700100)",
                },
            },
        [51004311] = {
            ["Content"] = "（你似乎听见了朽木舒展时发出的干燥异响。）",
            ["ContentFR"] = "Il te semble entendre le craquement sec du bois mort qui se redresse.",
            ["DialogueId"] = 51004311,
            ["GUID"] = "7FAF16C6",
            },
        [51004401] = {
            ["Content"] = "下水道里的什么是不会消失的？",
            ["ContentFR"] = "Qu’est-ce qui ne disparaît jamais dans les égouts ?",
            ["DialogueId"] = 51004401,
            ["GUID"] = "7FAF258A",
            ["NextOptions"] = {
                [1] = 510044011,
                [2] = 510044012,
                [3] = 510044013,
                },
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["bForbidSkipOptions"] = true,
            },
        [51004402] = {
            ["Content"] = "进来吧。",
            ["ContentFR"] = "Entre.",
            ["DialogueId"] = 51004402,
            ["GUID"] = "7FAF25B4",
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            },
        [51004403] = {
            ["Content"] = "这不是什么都不知道的蠢货该来的地方。",
            ["ContentFR"] = "Ici, ce n’est pas un endroit pour les {性别:idiots|idiotes} qui ne savent rien.",
            ["DialogueId"] = 51004403,
            ["GUID"] = "7FAF25DE",
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            },
        [51004501] = {
