                [1] = "700144:Agree",
                },
            },
        [51006019] = {
            ["Camera"] = "-81.742432,-73.919922,111.949219,0.000021,-10.600009,-24.396614,33.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "就是就是！",
            ["ContentFR"] = "Exactement !",
            ["DialogueId"] = 51006019,
            ["GUID"] = "7FB02EFE",
            ["LookAt"] = {
                [1] = "700145:n(100001)",
                [2] = "100001:n(700145)",
                [3] = "700144:n(700145)",
                },
            ["NextDialogue"] = 51006023,
            ["SpeakNpcId"] = 700144,
            ["TalkActionId"] = {
                [1] = "700144:Agree",
                },
            },
        [51006020] = {
            ["Camera"] = "-81.742432,-73.919922,111.949219,0.000021,-10.600009,-24.396614,33.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "不——好——！你们这样下去，队伍一定会变成看板上倒数第一的！",
            ["ContentFR"] = "NOOOON ! Avec ça, notre équipe finirait bonne dernière du tableau !",
            ["DialogueId"] = 51006020,
            ["GUID"] = "7FB02F28",
            ["LookAt"] = {
                [1] = "700145:n(100001)",
                [2] = "100001:n(700145)",
                [3] = "700144:n(700145)",
                },
            ["NextDialogue"] = 51006021,
            ["SpeakNpcId"] = 700144,
            ["TalkActionId"] = {
                [1] = "700144:Disagree",
                },
            },
        [51006021] = {
            ["Camera"] = "-29.963501,-92.201172,138.935547,0.000018,8.199928,169.801865,33.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "倒数第一不也会让人好奇——",
            ["ContentFR"] = "Et alors ? Être dernier peut aussi susciter la curiosité—",
            ["DialogueId"] = 51006021,
            ["GUID"] = "7FB02F52",
            ["NextDialogue"] = 51006022,
            ["SpeakNpcId"] = 700145,
            },
        [51006022] = {
            ["Camera"] = "-81.742432,-73.919922,111.949219,0.000021,-10.600009,-24.396614,33.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "停停停！",
            ["ContentFR"] = "Stop ! Pas question !",
            ["DialogueId"] = 51006022,
            ["GUID"] = "7FB02F7C",
            ["NextDialogue"] = 51006023,
            ["SpeakNpcId"] = 700144,
            ["TalkActionId"] = {
                [1] = "700144:Disagree",
                },
            },
        [51006023] = {
            ["Camera"] = "-165.896606,-64.533203,164.121094,0.000035,-17.399591,-29.602789,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "现在我们组成了新的队伍，已经不是你一个人单打独斗了，所以你这个名字作废，我们来取一个新的名字！",
            ["ContentFR"] = "Maintenant qu’on forme une nouvelle équipe, fini les décisions en solo. Ton nom est annulé. On va en trouver un autre !",
            ["DialogueId"] = 51006023,
            ["GUID"] = "7FB02FA6",
            ["NextDialogue"] = 51006024,
            ["SpeakNpcId"] = 700144,
            ["TalkActionId"] = {
                [1] = "700144:Explain02_Start",
                },
            ["TurnTo"] = {
                [1] = "100001:n(700144)",
                },
            },
        [51006024] = {
            ["Camera"] = "-29.963501,-92.201172,138.935547,0.000018,8.199928,169.801865,33.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "呃，也行，不过要是我们三个意见不统一怎么办。",
            ["ContentFR"] = "Euh... d’accord. Mais si on n’arrive pas à se mettre d’accord tous les trois ?",
            ["DialogueId"] = 51006024,
            ["GUID"] = "7FB02FD0",
            ["NextDialogue"] = 51006025,
            ["SpeakNpcId"] = 700145,
            ["TalkActionId"] = {
                [1] = "700145:Agree",
                [2] = "700144:Explain02_End",
                },
            },
        [51006025] = {
            ["Camera"] = "-81.742432,-73.919922,111.949219,0.000021,-10.600009,-24.396614,33.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "哼哼，白早就想好啦，自然是靠身手决定，谁赢了就听谁的。跟我来，我们来比试比试吧。",
            ["ContentFR"] = "Héhé, le Roi Démon avait déjà tout prévu ! On va régler ça par la force : celui qui gagne choisira le nom. Allez, suivez-moi !",
            ["DialogueId"] = 51006025,
            ["GUID"] = "7FB02FFA",
            ["Scripts"] = "SEQ{PlayAnimation{ActorId{700144},AnimationId{\"Agree\"},Duration{2}},PlayAnimation{ActorId{700144},AnimationId{\"Confident_Start\"},Duration{1}}}",
            ["SpeakNpcId"] = 700144,
            },
        [51006101] = {
            ["Camera"] = "245.083435,-275.051758,86.080566,0.0,0.0,113.398338,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "喔，这不是吵闹小白吗！后面跟着的是……食用昆虫研究队的赛特奥德！",
            ["ContentFR"] = "Oh ! Mais c’est la petite pipelette Snow ! Et derrière elle... voilà Monsieur l’Étrangleur de l’Équipe des Insectes Comestibles !",
            ["DialogueId"] = 51006101,
            ["GUID"] = "7FB03C72",
            ["LookAt"] = {
                [1] = "100001:n(700146)",
                [2] = "700144:n(700146)",
                [3] = "700145:n(700146)",
                },
            ["NextDialogue"] = 51006102,
            ["Scripts"] = "SEQ{CameraMoveTo{_delay{3},TargetPosition{\"46.114136,38.984375,117.397705,0.000007,10.999807,-124.000984,35.0,100000.0,false,DoNotOverride,2.8\"},duration{0}}}",
            ["SpeakNpcId"] = 700146,
            ["TalkActionId"] = {
                [1] = "100001:Confident_Start",
                },
            ["TurnTo"] = {
                [1] = "100001:n(700146)",
                [2] = "700144:n(700146)",
                [3] = "700145:n(700146)",
                [4] = "700146:n(700144)",
                },
            },
        [51006102] = {
            ["Camera"] = "234.691406,72.036133,66.071777,0.000003,10.399475,-155.20079,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "啊，我当是谁呢，原来是探险家皎皎啊。虽然刚刚叫对了我的小队名让我有一点感动，但只是几天不见，你又把我名字叫错了。",
            ["ContentFR"] = "Tiens, Luno, l’exploratrice... J’apprécie que tu aies retenu le nom de mon équipe, mais ça fait des jours que tu écorches toujours mon propre nom.",
            ["DialogueId"] = 51006102,
            ["GUID"] = "7FB03C9C",
            ["NextDialogue"] = 51006103,
            ["Scripts"] = "SEQ{PlayAnimation{ActorId{700145},AnimationId{\"Explain01_Start\"},Duration{3}},PlayAnimation{ActorId{700145},AnimationId{\"Explain01_End\"},Duration{1}},PlayAnimation{ActorId{700145},AnimationId{\"Disagree\"},Duration{1}}}",
            ["SpeakNpcId"] = 700145,
            ["TalkActionId"] = {
                [1] = "100001:Confident_End",
                },
            ["TurnTo"] = {
                [1] = "700146:n(700145)",
                },
            },
        [51006103] = {
            ["Camera"] = "-105.877808,-273.970215,200.745117,0.000031,-17.99987,65.800964,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "那是因为我的注意力总是在你带回来的记录上，等下次，我就一定会记对你的名字的！赛特奥德小哥。",
            ["ContentFR"] = "C’est que mon attention est toujours happée par tes exploits. La prochaine fois, promis, je le retiendrai bien, Monsieur... euh... l’Étrangleur.",
            ["DialogueId"] = 51006103,
            ["GUID"] = "7FB03CC6",
            ["NextDialogue"] = 51006104,
            ["SpeakNpcId"] = 700146,
            ["TalkActionId"] = {
                [1] = "700146:Explain01_Start",
                },
            },
        [51006104] = {
            ["Camera"] = "-253.942383,145.432129,112.640137,0.000095,-3.399563,-32.804798,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "那么吵闹小白，这位是？",
            ["ContentFR"] = "Et toi, Snow-la-pipelette, qui est cette personne ?",
            ["DialogueId"] = 51006104,
            ["GUID"] = "7FB03CF0",
            ["NextDialogue"] = 51006105,
            ["SpeakNpcId"] = 700146,
            ["TalkActionId"] = {
                [1] = "700146:Explain01_End",
                },
            ["TurnTo"] = {
                [1] = "700146:n(700144)",
                },
            },
        [51006105] = {
            ["Camera"] = "-47.697998,-122.447266,163.110352,0.000107,-15.799224,-21.20565,28.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "{性别：他|她}呀，是{nickname}，我新认识的小仆从，现在我在引导{性别：他|她}成为一名合格的狩月人。",
            ["ContentFR"] = "C’est {nickname}, mon tout nouveau petit larbin. Je lui montre comment devenir {性别:un vrai Chasseur de Phoxène|une vraie Chasseuse de Phoxène} !",
            ["DialogueId"] = 51006105,
            ["GUID"] = "7FB03D1A",
            ["LookAt"] = {
                [1] = "100001:n(700144)",
                },
            ["NextDialogue"] = 51006106,
            ["Scripts"] = "SEQ{TurnTo{TurnToDescription{\"700144:n(100001)\"}},LookAt{LookAtDescription{\"700144:n(100001)\"}},PlayAnimation{_delay{2},ActorId{700144},AnimationId{\"Confident_Start\"},Duration{2}}}",
            ["SpeakNpcId"] = 700144,
            },
        [51006106] = {
            ["Camera"] = "-70.926147,-57.200684,76.004883,0.000152,0.0,32.790924,28.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "那么，我再来向你介绍一下！她是探险家皎皎，我认识的皎皎之民中就数她最富有冒险精神，最喜欢收集各种冒险者的情报啦。",
            ["ContentFR"] = "Et elle, c’est Luno, l’exploratrice ! Parmi les siens, c’est la plus audacieuse que je connaisse. Elle adore collecter des infos sur les aventuriers.",
            ["DialogueId"] = 51006106,
            ["GUID"] = "7FB03D44",
            ["LookAt"] = {
                [1] = "100001:n(700146)",
                },
            ["NextDialogue"] = 51006107,
            ["Scripts"] = "SEQ{CameraMoveTo{TargetPosition{\"-70.926147,-62.0,76.004883,0.000152,0.0,32.790958,28.0,100000.0,false,DoNotOverride,2.8\"},duration{2}},CameraMoveTo{TargetPosition{\"59.133484,-36.513672,112.323975,0.000181,0.0,78.584763,28.0,100000.0,false,DoNotOverride,2.8\"},duration{0}},CameraMoveTo{TargetPosition{\"60.901123,-27.689453,112.323975,0.000181,0.0,78.984596,28.0,100000.0,false,DoNotOverride,2.8\"},duration{2}},CameraMoveTo{TargetPosition{\"35.020691,-126.598145,87.284668,0.000142,0.0,77.791298,28.0,100000.0,false,DoNotOverride,2.8\"},duration{0}},PlayAnimation{ActorId{700146},AnimationId{\"Explain02_Start\"},Duration{2}}}",
            ["SpeakNpcId"] = 700144,
            ["TurnTo"] = {
                [1] = "700144:n(700146)",
                [2] = "700146:n(100001)",
                },
            },
        [51006107] = {
            ["Camera"] = "35.020691,-126.598145,87.284668,0.000142,0.0,77.791298,28.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "你看，就连奥特赛德的那个糟糕的小队名字，她都会记得！",
            ["ContentFR"] = "La preuve, elle se souvient même de l’horrible nom d’équipe de l’Étranger !",
            ["DialogueId"] = 51006107,
            ["GUID"] = "7FB03D6E",
            ["NextDialogue"] = 51006108,
            ["SpeakNpcId"] = 700144,
            ["TalkActionId"] = {
                [1] = "700146:Explain02_End",
                },
            },
        [51006108] = {
            ["Camera"] = "46.114136,38.984375,117.397705,0.000007,10.999807,-124.000984,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "奥德赛特的起名水准虽然一般，但身手还是很厉害的！换做一般的狩月人，顶着这样一个小队名字，应该在一年前转行或者三个月前饿毙街头了。",
            ["ContentFR"] = "Certes, son talent pour les noms laisse à désirer, mais son talent en tant que Chasseur de Phoxène n’est plus à prouver ! Avec un nom pareil, n’importe quel autre Chasseur de Phoxène aurait déjà abandonné ou crevé de faim depuis belle lurette.",
            ["DialogueId"] = 51006108,
            ["GUID"] = "7FB03D98",
            ["NextDialogue"] = 51006109,
            ["Scripts"] = "CameraMoveTo{_delay{3},TargetPosition{\"62.480164,-164.678711,86.856934,0.000015,0.0,88.998657,35.0,100000.0,false,DoNotOverride,2.8\"},duration{0}}",
            ["SpeakNpcId"] = 700146,
            ["TalkActionId"] = {
                [1] = "700145:Talk03_Start",
                [2] = "700146:Confident_Start",
                },
            },
        [51006109] = {
            ["Camera"] = "46.114136,38.984375,117.397705,0.000007,10.999807,-124.000984,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "饿毙……行吧，改，改吧。那么小个子你说的靠身手决定，是什么意思？",
            ["ContentFR"] = "Crevé de faim... ? Bon, très bien, changeons. Mais dis-moi, Petit Champi, ces épreuves, en quoi consistent-elles ?",
            ["DialogueId"] = 51006109,
            ["GUID"] = "7FB03DC2",
            ["NextDialogue"] = 51006110,
            ["SpeakNpcId"] = 700145,
            ["TalkActionId"] = {
                [1] = "700146:Confident_End",
                },
            },
        [51006110] = {
            ["Camera"] = "78.202087,-48.859863,118.763184,0.000051,-12.200288,-36.19857,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "哼，你的疙瘩脑袋总算转过弯了，那么先让我来和探险家皎皎前辈解释一下发生了什么。",
            ["ContentFR"] = "Hé ! Tu réalises enfin. Laisse-moi expliquer à Luno, l’exploratrice.",
            ["DialogueId"] = 51006110,
            ["GUID"] = "7FB03DEC",
            ["NextDialogue"] = 51006111,
            ["SpeakNpcId"] = 700144,
            ["TalkActionId"] = {
                [1] = "700144:Confident_Start",
                [2] = "700145:Talk03_End",
                },
            },
        [51006111] = {
            ["Camera"] = "46.114136,38.984375,117.397705,0.000007,10.999807,-124.000984,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "（白张牙舞爪地比划了奥特赛德对于旧小队名的喜爱，以及通过靠身手来统一意见的打算。）",
            ["ContentFR"] = "Snow se lance dans une gesticulation exagérée, mimant l’attachement de l’Étranger à son ancien nom d’équipe et leur idée de se départager par des épreuves.",
            ["DialogueId"] = 51006111,
            ["GUID"] = "7FB03E16",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 51006112,
            },
        [51006112] = {
            ["Content"] = "喔，我明白了，是用那个挑战来决定啊，那我是不会输的！",
            ["ContentFR"] = "Ah, je comprends ! Des défis, donc. Parfait, je ne perds jamais !",
            ["DialogueId"] = 51006112,
            ["GUID"] = "7FB03E40",
            ["NextDialogue"] = 51006113,
            ["SpeakNpcId"] = 700145,
            ["TalkActionId"] = {
                [1] = "700145:Angry01_Start",
                },
            ["TurnTo"] = {
                [1] = "700146:n(700145)",
                },
            },
        [51006113] = {
            ["Camera"] = "-107.990723,-296.696289,204.89624,0.000065,-19.999907,67.198593,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "嗯，你确实是挑战次数最多的几个人之一，但{nickname}应该没有见过我设下的挑战，让我来说明一下。",
            ["ContentFR"] = "Oui, tu es l’un de ceux qui ont relevé le plus de mes défis... Mais {nickname}, {性别:lui|elle}, ne connaît pas encore mes règles. Je vais lui expliquer.",
            ["DialogueId"] = 51006113,
            ["GUID"] = "7FB03E6A",
            ["NextDialogue"] = 51006114,
            ["SpeakNpcId"] = 700146,
            ["TalkActionId"] = {
                [1] = "700145:Angry01_End",
                [2] = "700146:Agree",
                },
            },
        [51006114] = {
            ["Camera"] = "18.039185,-278.991699,158.917725,0.000157,-13.200044,68.989624,28.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "简单来说呢，我之所以会对狩月人这么熟悉，是因为我会观察各位的身手，再记录下来。",
            ["ContentFR"] = "En clair, je connais si bien les Chasseurs de Phoxène parce que je les observe et que je note leurs prouesses.",
            ["DialogueId"] = 51006114,
            ["GUID"] = "7FB03E94",
            ["NextDialogue"] = 51006115,
            ["SpeakNpcId"] = 700146,
            ["TurnTo"] = {
                [1] = "700146:n(100001)",
                },
            },
        [51006115] = {
            ["Camera"] = "61.417114,-123.797852,85.32666,0.0,0.0,86.990524,28.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "但狩月人这么多，并且在他们执行委托时跟在后面也很危险，所以我就找了一个帮手——一位年长的，令人尊敬的，但是长得和你有些像的铁匠。",
            ["ContentFR"] = "Mais suivre chacun d’eux en mission est dangereux, alors j’ai demandé de l’aide à une personne de confiance : une forgeronne âgée, respectée, qui te ressemble un peu.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 51006115,
            ["GUID"] = "7FB03EBE",
            ["NextDialogue"] = 51006116,
            ["Scripts"] = "SEQ{TurnTo{_delay{4},TurnToDescription{\"700146:n(700144)\"}},CameraMoveTo{_delay{1},TargetPosition{\"54.903625,146.320801,86.79541,0.000006,0.0,-72.008141,28.0,100000.0,false,DoNotOverride,2.8\"},duration{0}},CameraMoveTo{TargetPosition{\"59.0,148.0,86.79541,0.000006,0.0,-72.008102,28.0,100000.0,false,DoNotOverride,2.8\"},duration{3}}}",
            ["SpeakNpcId"] = 700146,
            },
        [51006116] = {
            ["Camera"] = "123.392273,2.931152,85.919922,0.000078,0.0,-60.200184,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "难道你说的是铁匠皎皎前辈？我们认识她呀！",
            ["ContentFR"] = "Tu veux dire... Luno, la forgeronne ? On la connaît !",
            ["DialogueId"] = 51006116,
            ["GUID"] = "7FB03EE8",
            ["NextDialogue"] = 51006117,
            ["SpeakNpcId"] = 700144,
            ["TalkActionId"] = {
                [1] = "700144:Agree",
                },
            },
        [51006117] = {
            ["Camera"] = "245.083435,-275.051758,86.080566,0.0,0.0,113.398293,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "喔，认识的话就好说了，你们应该见过她的手艺。",
            ["ContentFR"] = "Parfait ! Vous avez sûrement vu son savoir-faire.",
            ["DialogueId"] = 51006117,
            ["GUID"] = "7FB03F12",
            ["NextDialogue"] = 51006118,
            ["SpeakNpcId"] = 700146,
            },
        [51006118] = {
            ["Camera"] = "-36.301025,308.482422,2046.960449,0.000022,-8.399964,-137.801437,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我拜托她做了一个魔法小玩意，能够在各个地方留下记号。那个记号只要被人碰一下，就会显出一段文字，也能记录下附近的人的行动。",
            ["ContentFR"] = "Je lui ai demandé de créer un petit artéfact magique : un marqueur qui peut être posé n’importe où. Quiconque le touche voit s’afficher un message, et ses actions sont enregistrées.",
            ["DialogueId"] = 51006118,
            ["FinalCamera"] = "78.561584,181.818848,2047.960449,0.000022,-8.399964,-137.801376,35.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "7FB03F3C",
            ["NextDialogue"] = 51006119,
            ["SpeakNpcId"] = 700146,
            ["ToFinalCameraBlendTime"] = 10,
            },
        [51006119] = {
            ["Camera"] = "-317.315186,330.895508,307.277344,0.000049,-21.599884,-50.999966,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "要是有人完成了文字要求的行动，就算是完成了挑战。要是结果足够好，就可以在我这里拿到一些报酬。所以说，我是最清楚怎么摸清狩月人身手的了。",
            ["ContentFR"] = "Si vous accomplissez ce qui est écrit, le défi est relevé. Et si le résultat est satisfaisant, je donne même une récompense. Voilà comment j’évalue les Chasseurs de Phoxène.",
            ["DialogueId"] = 51006119,
            ["GUID"] = "7FB03F66",
            ["NextDialogue"] = 51006120,
            ["SpeakNpcId"] = 700146,
            },
        [51006120] = {
            ["Camera"] = "68.506897,3.594238,109.754639,0.000018,13.999626,-134.600388,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我可太熟悉这些挑战了，小个子这下失算了，我都不知道怎么输。",
            ["ContentFR"] = "Ces défis ? Je les connais sur le bout des doigts. Petit Champi, tu t’es trompé de pari : la défaite, je ne sais pas ce que c’est.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 51006120,
            ["GUID"] = "7FB03F90",
            ["NextDialogue"] = 51006121,
            ["Scripts"] = "PlayAnimation{_delay{1},ActorId{700145},AnimationId{\"Disagree\"},Duration{2}}",
            ["SpeakNpcId"] = 700145,
            ["TurnTo"] = {
                [1] = "700146:n(700145)",
                },
            },
        [51006121] = {
            ["Camera"] = "-17.909668,-172.834961,149.789795,0.000038,-17.999323,66.400116,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "你先冷静一下，我只看最后的挑战结果。那么如果这位{nickname}{性别：小兄弟|小姑娘}也没问题的话，就来这里找我吧。",
            ["ContentFR"] = "Du calme. Seul le résultat final compte. Si {nickname} est {性别:partant|partante}, venez me voir.",
            ["DialogueId"] = 51006121,
            ["GUID"] = "7FB03FBA",
            ["NextDialogue"] = 51006122,
            ["Scripts"] = "SEQ{PlayAnimation{ActorId{700146},AnimationId{\"Disagree\"},Duration{2}},LookAt{LookAtDescription{\"700146:n(100001)\"}}}",
            ["SpeakNpcId"] = 700146,
            },
        [51006122] = {
            ["Camera"] = "68.506897,3.594238,109.754639,0.000018,13.999626,-134.600388,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "（探险家皎皎掏出笔，在你手中的冰湖城地图上做了一个标记。）",
            ["ContentFR"] = "Luno, l’exploratrice sort un stylet et trace un symbole sur ta carte de Givrelac.",
            ["DialogueId"] = 51006122,
            ["GUID"] = "7FB03FE4",
            ["IsBlack"] = 1,
            },
        [51006201] = {
            ["Camera"] = "100.462158,-55.870972,113.845947,0.000005,-7.000062,-90.399178,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "好，那么在开始之前我讲解一下规则：在我说开始之后，沿着我标记的发光圈圈一直向前就好！",
            ["ContentFR"] = "Bien, avant de commencer, voici les règles : une fois que je dis « Partez », suivez les cercles lumineux que j’ai placés le long du parcours.",
            ["DialogueId"] = 51006201,
            ["GUID"] = "7FB04CDA",
            ["NextDialogue"] = 51006202,
            ["Scripts"] = "SEQ{PlayAnimation{ActorId{700146},AnimationId{\"Explain02_Start\"},Duration{2}},PlayAnimation{ActorId{700146},AnimationId{\"Explain02_End\"},Duration{1}},PARA{TurnTo{TurnToDescription{\"700146:p(90)\"}},CameraMoveTo{TargetPosition{\"365.846802,-145.875488,80.777954,0.0,0.0,-161.797287,35.0,100000.0,false,DoNotOverride,2.8\"},duration{0}}},CameraMoveTo{TargetPosition{\"365.846802,-135.0,80.777954,0.0,0.0,-161.797287,35.0,100000.0,false,DoNotOverride,2.8\"},duration{3}}}",
            ["SpeakNpcId"] = 700146,
            },
        [51006202] = {
            ["Camera"] = "176.590088,288.807129,234.116333,0.000006,-17.800079,-96.798767,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "别担心，别看那个奥特赛文那么有信心，但是我更看好你，加油加油。",
            ["ContentFR"] = "Ne t’inquiète pas. L’Étriqué fait le fier, mais moi, je crois en toi. Allez, courage !",
            ["DialogueId"] = 51006202,
            ["GUID"] = "7FB04D04",
            ["Scripts"] = "SEQ{TurnTo{TurnToDescription{\"700146:n(100001)\"}},LookAt{LookAtDescription{\"700146:n(100001)\"}},PlayAnimation{ActorId{700146},AnimationId{\"Agree\"},Duration{2}}}",
            ["SpeakNpcId"] = 700146,
            ["TalkActionId"] = {
                [1] = "700145:Sigh_Start",
                [2] = "100001:Confident_Start",
                },
            },
        [51006301] = {
            ["Content"] = "驾轻就熟，我赢定了。",
            ["ContentFR"] = "Ça roule. Facile. C’est gagné d’avance.",
            ["DialogueId"] = 51006301,
            ["Duration"] = 3,
            ["GUID"] = "7FB05D42",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700145,
            },
        [51006302] = {
            ["Content"] = "哎？谁往地上泼油？",
            ["ContentFR"] = "Hein ? Qui a renversé de l’huile par terre ?",
            ["DialogueId"] = 51006302,
            ["Duration"] = 3,
            ["GUID"] = "7FB05D6C",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700145,
            },
        [51006303] = {
            ["Content"] = "不是？怎么屋顶还有狗？",
            ["ContentFR"] = "Quoi ? Y a un chien sur le toit maintenant ?",
            ["DialogueId"] = 51006303,
            ["Duration"] = 3,
            ["GUID"] = "7FB05D96",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 51006304,
            ["SpeakNpcId"] = 700145,
            },
        [51006304] = {
            ["Content"] = "汪汪——",
            ["ContentFR"] = "Ouaf ! Ouaf !",
            ["DialogueId"] = 51006304,
            ["Duration"] = 2,
            ["GUID"] = "7FB05DC0",
            ["SpeakNpcName"] = "UI_Npc_Name_Dog",
            },
        [51006305] = {
            ["Content"] = "刚刚是发挥失常了吧，别着急，再来一次，我相信你！",
            ["ContentFR"] = "Pas grave ! Recommence, je sais que tu peux le faire.",
            ["DialogueId"] = 51006305,
            ["Duration"] = 3,
            ["GUID"] = "7FB05DEA",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700146,
            },
        [51006401] = {
            ["Content"] = "哦，{nickname}身手不错嘛，那么我们现在去进行第二场测试，跟着我来。",
            ["ContentFR"] = "Pas mal, {nickname}, vraiment pas mal. Passons au deuxième test. Suis-moi.",
            ["DialogueId"] = 51006401,
            ["Duration"] = 3,
            ["GUID"] = "7FB06DAA",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 51006402,
            ["SpeakNpcId"] = 700146,
            },
        [51006402] = {
            ["Content"] = "奥德特赛也抓紧赶上，不要跟丢了。",
            ["ContentFR"] = "L’Étriper, dépêche un peu, ne perds pas le rythme.",
            ["DialogueId"] = 51006402,
            ["Duration"] = 2,
            ["GUID"] = "7FB06DD4",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700146,
            },
        [51006501] = {
            ["Camera"] = "190.745117,183.455322,84.877686,0.000011,0.0,-90.395432,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "这一个测试的规则也很简单：我说开始后，面前会出现我拜托铁匠皎皎前辈做的气球。",
            ["ContentFR"] = "Cette fois, c’est simple : à mon signal, des ballons forgés par Luno, la forgeronne vont apparaître.",
            ["DialogueId"] = 51006501,
            ["GUID"] = "7FB07E12",
            ["NextDialogue"] = 51006502,
            ["Scripts"] = "SEQ{PlayAnimation{ActorId{700146},AnimationId{\"Agree\"},Duration{2}},PARA{TurnTo{TurnToDescription{\"700146:p(-90)\"}},CameraMoveTo{TargetPosition{\"-135.275879,-75.0,84.279785,0.000003,0.0,-0.597107,35.0,100000.0,false,DoNotOverride,2.8\"},duration{0}}},CameraMoveTo{TargetPosition{\"-135.275879,-63.0,84.279785,0.000003,0.0,-0.597107,35.0,100000.0,false,DoNotOverride,2.8\"},duration{3}}}",
            ["SpeakNpcId"] = 700146,
            },
        [51006502] = {
            ["Camera"] = "485.306641,-103.10376,80.212891,0.000003,0.0,-177.99791,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "瞄准，然后打爆它就好！",
            ["ContentFR"] = "Tu n’as qu’à viser... et les faire exploser !",
            ["DialogueId"] = 51006502,
            ["GUID"] = "7FB07E3C",
            ["SpeakNpcId"] = 700146,
            ["TalkActionId"] = {
                [1] = "700146:Confident_Start",
                },
            },
        [51006601] = {
            ["Content"] = "奇怪了，我的子弹呢？",
            ["ContentFR"] = "Mais... mes balles ? Elles sont passées où ?",
            ["DialogueId"] = 51006601,
            ["Duration"] = 2,
            ["GUID"] = "7FB08E7A",
            ["GuideFacialId"] = "Sad",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700145,
            },
        [51006602] = {
            ["Content"] = "……可恶，刚刚手上沾了油，装弹好麻烦。",
            ["ContentFR"] = "Pff... mes mains sont pleines d’huile, recharger, c’est la galère...",
            ["DialogueId"] = 51006602,
            ["Duration"] = 2,
            ["GUID"] = "7FB08EA4",
            ["GuideFacialId"] = "Sad",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700145,
            },
        [51006603] = {
            ["Content"] = "别装弹了，{nickname}已经完成测试了。",
            ["ContentFR"] = "Pas la peine, {nickname} a déjà terminé.",
            ["DialogueId"] = 51006603,
            ["Duration"] = 2,
            ["GUID"] = "7FB08ECE",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700146,
            },
        [51006701] = {
            ["Camera"] = "-20.024414,-347.564941,170.543701,0.000067,-13.199791,66.207527,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "恭喜你，{nickname}，我的眼光没错，你是一位潜力十足的狩月人。",
            ["ContentFR"] = "Bravo, {nickname}. Tu confirmes ce que je pensais, tu as un vrai potentiel en tant que Chasseur de Phoxène.",
            ["DialogueId"] = 51006701,
            ["GUID"] = "7FB09EE2",
            ["LookAt"] = {
                [1] = "100001:n(700146)",
                [2] = "700144:n(700146)",
                [3] = "700145:n(700146)",
                [4] = "700146:n(100001)",
                },
            ["NextDialogue"] = 51006702,
            ["SpeakNpcId"] = 700146,
            ["TalkActionId"] = {
                [1] = "700146:Agree",
                },
            },
        [51006702] = {
            ["Camera"] = "70.664551,-61.835938,124.763184,0.000051,-13.200255,-30.598364,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "哼哼，按照之前的约定，新的小队名字，就由你来取啦！奥特赛德，你有意见吗？",
            ["ContentFR"] = "Héhé ! Comme convenu, c’est à toi de choisir le nom de notre équipe. Et toi, l’Étranger, tu as quelque chose à redire ?",
            ["DialogueId"] = 51006702,
            ["GUID"] = "7FB09F0C",
            ["NextDialogue"] = 51006703,
            ["Scripts"] = "SEQ{PlayAnimation{ActorId{700144},AnimationId{\"Confident_Start\"},Duration{2}},LookAt{_delay{2},LookAtDescription{\"700144:n(700145)\"}}}",
            ["SpeakNpcId"] = 700144,
            },
        [51006703] = {
            ["Camera"] = "73.404785,8.581055,112.754639,0.000019,13.999578,-134.799911,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我抗议！你们一定是在针对我！",
            ["ContentFR"] = "Bien sûr que j’ai à redire ! C’est un complot contre moi !",
            ["DialogueId"] = 51006703,
            ["GUID"] = "7FB09F36",
            ["NextDialogue"] = 51006704,
            ["SpeakNpcId"] = 700145,
            ["TalkActionId"] = {
                [1] = "700145:Sigh_Start",
                },
            },
        [51006704] = {
            ["Camera"] = "-120.803711,-309.877441,224.89624,0.000075,-19.999907,68.198792,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "怎么可能，我是专业的狩月人能力记录者，不会偏袒谁，也不会针对谁。",
            ["ContentFR"] = "Ridicule. Je suis une observatrice professionnelle, je ne favorise personne...",
            ["DialogueId"] = 51006704,
            ["GUID"] = "7FB09F60",
            ["LookAt"] = {
                [1] = "700146:n(700145)",
                },
            ["NextDialogue"] = 51006705,
            ["SpeakNpcId"] = 700146,
            ["TalkActionId"] = {
                [1] = "700145:Sigh_End",
                },
            ["TurnTo"] = {
                [1] = "700146:n(700145)",
                },
            },
        [51006705] = {
            ["Camera"] = "64.692383,-137.981445,87.32666,0.0,0.0,87.390518,28.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "除非……",
            ["ContentFR"] = "Sauf si...",
            ["DialogueId"] = 51006705,
            ["GUID"] = "7FB09F8A",
            ["NextDialogue"] = 51006706,
            ["SpeakNpcId"] = 700146,
            ["TalkActionId"] = {
                [1] = "700146:Explain02_Start",
                },
            },
        [51006706] = {
            ["Camera"] = "11.383789,132.50415,88.602051,0.000028,2.199956,-70.207726,28.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "除非？",
            ["ContentFR"] = "Sauf si ?",
            ["DialogueId"] = 51006706,
            ["GUID"] = "7FB09FB4",
            ["NextDialogue"] = 51006707,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "700146:Explain02_End",
                },
            },
        [51006707] = {
            ["Camera"] = "-120.803711,-309.877441,224.89624,0.000075,-19.999907,68.198792,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "除非有人和这个奥特赛德一样，简直把完成挑战当成营生的手段一样！每次我新布设了一批记号，他都第一个过去挑战，再冲到我这边要报酬，坏透了！",
            ["ContentFR"] = "... Sauf si quelqu’un profite de mes défis comme d’un gagne-pain. Et je parle bien sûr de toi, l’Étranger ! Chaque fois que je place de nouveaux marqueurs, tu es le premier à foncer... et le premier à exiger ta récompense.",
            ["DialogueId"] = 51006707,
            ["GUID"] = "7FB09FDE",
            ["NextDialogue"] = 51006708,
            ["SpeakNpcId"] = 700146,
            },
        [51006708] = {
            ["Camera"] = "73.404785,8.581055,112.754639,0.000019,13.999578,-134.799911,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "只要他去过一次的挑战，就没几个人再能超过他拿到报酬！搞得别人都不愿意参加了！所以我要让他尝一尝苦头！",
            ["ContentFR"] = "Résultat, plus personne n’avait la moindre chance de battre tes records. Les autres ont fini par ne même plus oser participer. Il fallait bien que je te donne une bonne leçon !",
            ["DialogueId"] = 51006708,
            ["GUID"] = "7FB0A008",
            ["LookAt"] = {
                [1] = "700145:n(700145)",
                },
            ["NextDialogue"] = 51006709,
            ["SpeakNpcId"] = 700146,
            },
        [51006709] = {
            ["Camera"] = "73.404785,8.581055,112.754639,0.000019,13.999578,-134.799911,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "你报复我居然是因为这个？！还有你终于叫对我的名字了，之前是不是都是故意的？",
            ["ContentFR"] = "Quoi ?! Tu me punis pour ça ? Et en plus, tu viens de prononcer mon nom correctement... tu le faisais exprès avant, pas vrai ?",
            ["DialogueId"] = 51006709,
            ["GUID"] = "7FB0A032",
