            ["DialoguePanelType"] = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Atlas/Prop/Item/T_ExploreBadge_Beibao_Chapter01.T_ExploreBadge_Beibao_Chapter01'}",
            ["GUID"] = "7FB0A3F9",
            ["NextDialogue"] = 51006740,
            ["SpeakNpcId"] = 700146,
            },
        [51006734] = {
            ["Content"] = "“夜航者”……嗯，好名字！要是人人都像你们一样，这块看板就不会不够写了……",
            ["ContentFR"] = "Les Vagabonds de la Nuit... Oui, c’est un beau nom. Si toutes les équipes en choisissaient d’aussi simples, le tableau d’affichage aurait enfin de la place !",
            ["DialogueId"] = 51006734,
            ["GUID"] = "7FB0A44C",
            ["LookAt"] = {
