            },
        [51006740] = {
            ["Camera"] = "80.842773,-51.764648,173.552246,0.000151,-10.797237,-94.405273,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "这个是？",
            ["ContentFR"] = "Qu’est-ce que c’est ?",
            ["DialogueId"] = 51006740,
            ["GUID"] = "7FB0A3FA",
            ["NextDialogue"] = 51006741,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Think_Start",
                },
            },
        [51006741] = {
            ["Camera"] = "38.65332,-125.365479,127.959717,0.000135,-12.798094,77.399048,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "觉得眼熟吗？眼熟的话就说明你还挺喜欢探险的，没见过的话也没关系！这是我特制的标记，当我外出探险的时候，会用它来标记走过的路。",
            ["ContentFR"] = "Ça te dit quelque chose ? Si oui, c’est que tu aimes vraiment l’aventure. Sinon, ce n’est pas grave ! Ce sont des marques que j’ai conçues moi-même : lorsque je partais explorer, je les utilisais pour signaler les chemins déjà parcourus.",
            ["DialogueId"] = 51006741,
            ["GUID"] = "7FB0A3FB",
            ["NextDialogue"] = 51006736,
            ["SpeakNpcId"] = 700146,
            ["TalkActionId"] = {
                [1] = "700146:Explain02_Start",
                [2] = "100001:Think_End",
                },
            },
        [51006801] = {
            ["Camera"] = "-208.101562,-322.367188,154.874023,0.000172,12.798783,96.059433,12.0,1.5,false,Disable,1.2",
            ["Content"] = "愿你的灵魂于雾海深处获得安宁……",
            ["ContentFR"] = "Que ton âme trouve la paix... au plus profond de la Mer du Silence...",
            ["DialogueId"] = 51006801,
            ["FinalCamera"] = "-208.101562,-322.367188,98.418945,0.000172,12.798783,96.059433,12.0,1.5,false,Disable,1.2",
            ["GUID"] = "7FB0AF4A",
            ["NextDialogue"] = 51006802,
            ["SpeakNpcId"] = 700133,
            ["TalkActionId"] = {
                [1] = "700133:Think_Start",
                },
            ["ToFinalCameraBlendTime"] = 8,
            },
        [51006802] = {
            ["Camera"] = "-397.094727,-621.34375,166.169922,0.000161,-7.00162,55.459202,35.0,1.5,false,Disable,1.2",
            ["Content"] = "（在这片对你来说意义沉重的回忆之地，一位身披黑纱的女人静静地垂眸低语。伴随着低沉的祷告之声，女人手中的提灯散发出荧荧的幽光。）",
            ["ContentFR"] = "Dans ce lieu chargé de tes souvenirs les plus lourds, une femme voilée de noir incline doucement la tête. Tandis que sa voix s’élève en une prière grave et apaisée, la lanterne entre ses mains diffuse une lueur spectrale et vacillante.",
            ["DialogueId"] = 51006802,
            ["GUID"] = "7FB0AF74",
            ["LookAt"] = {
                [1] = "100001:n(700133)",
                },
            ["NextOptions"] = {
                [1] = 51006803,
                [2] = 51006804,
                },
            ["Scripts"] = "MoveTo{ActorId{100001},TargetPoint{\"200218510060P1\"},MoveSpeed{80},Visibility{\"Show\"}}",
            },
        [51006803] = {
            ["Content"] = "你在做什么？",
            ["ContentFR"] = "<I>Que faites-vous ici ?</>",
            ["DialogueId"] = 51006803,
            ["GUID"] = "7FB0AF9E",
            ["NextDialogue"] = 51006805,
            },
        [51006804] = {
            ["Content"] = "你是谁？",
            ["ContentFR"] = "<I>Qui êtes-vous ?</>",
            ["DialogueId"] = 51006804,
            ["GUID"] = "7FB0AFC8",
            ["NextDialogue"] = 51006805,
            },
        [51006805] = {
            ["Camera"] = "-89.203125,275.894531,124.682617,0.000181,-2.801388,-79.533676,35.0,1.5,false,Disable,1.2",
            ["Content"] = "你来了，孩子……请稍等，待我完成最后的仪式。",
            ["ContentFR"] = "Te voilà, mon enfant... Attends un instant, le temps que j’achève ce dernier rite.",
            ["DialogueId"] = 51006805,
            ["GUID"] = "7FB0AFF2",
            ["LookAt"] = {
                [1] = "100001:n(700133)",
                [2] = "700133:p(200218510060P3)",
                },
            ["NextDialogue"] = 51006806,
            ["SpeakNpcId"] = 700133,
            },
        [51006806] = {
            ["Camera"] = "-243.27832,141.84375,135.348633,0.000225,-4.600918,-11.145157,35.0,1.5,false,Disable,1.2",
            ["Content"] = "……愿你于母神的怀抱中重获新生。",
            ["ContentFR"] = "... Puisse-tu renaître dans l’étreinte de Mère Embla.",
            ["DialogueId"] = 51006806,
            ["FinalCamera"] = "-243.27832,141.84375,129.169922,0.000225,-4.600918,-11.145157,35.0,1.5,false,Disable,1.2",
            ["GUID"] = "7FB0B01C",
            ["LookAt"] = {
                [1] = "700133:n(700133)",
                },
            ["NextDialogue"] = 51006807,
            ["SpeakNpcId"] = 700133,
            ["ToFinalCameraBlendTime"] = 6,
            },
        [51006807] = {
            ["Camera"] = "-122.856445,-382.609375,156.415039,0.000195,-5.601042,76.061539,80.0,1.5,false,Disable,1.2",
            ["Content"] = "你好，孩子。我是一名漂泊的雾海引渡人——或者，如果你更喜欢以姓名相称，也可以称呼我为妮弗尔夫人。",
            ["ContentFR"] = "Bonjour, mon enfant. Je suis une Passeuse de la Mer du Silence... Mais si tu préfères me nommer, appelle-moi Dame Nifle.",
            ["DialogueId"] = 51006807,
            ["GUID"] = "7FB0B046",
            ["LookAt"] = {
                [1] = "700133:n(100001)",
                },
            ["NextDialogue"] = 51006808,
            ["SpeakNpcId"] = 700133,
            ["SpeakNpcName"] = "UI_Npc_Name_Nifu",
            ["TalkActionId"] = {
                [1] = "700133:Think_End",
                },
            ["TurnTo"] = {
                [1] = "700133:n(100001)",
                },
            },
        [51006808] = {
            ["Content"] = "我听见此处彷徨灵魂的絮语，因此前来指引“她”回归雾海。",
            ["ContentFR"] = "J’ai entendu les murmures d’une âme égarée en ce lieu. Je suis venue la guider vers la Mer du Silence.",
            ["DialogueId"] = 51006808,
            ["GUID"] = "7FB0B070",
            ["NextDialogue"] = 51006809,
            ["SpeakNpcId"] = 700133,
            ["SpeakNpcName"] = "UI_Npc_Name_Nifu",
            ["TalkActionId"] = {
                [1] = "700133:Explain02_Start",
                },
            },
        [51006809] = {
            ["Content"] = "彷徨的灵魂？",
            ["ContentFR"] = "Une âme égarée ?",
            ["DialogueId"] = 51006809,
            ["GUID"] = "7FB0B09A",
            ["NextDialogue"] = 51006810,
            ["SpeakNpcId"] = 100001,
            },
        [51006810] = {
            ["Camera"] = "-63.210938,263.902344,129.163086,0.000284,-1.000821,-85.744926,50.0,1.5,false,Disable,1.2",
            ["Content"] = "是的。孩子，你是否也为一位亡者而来？",
            ["ContentFR"] = "Oui. Dis-moi, mon enfant... serais-tu venu, toi aussi, pour quelqu’un qui n’est plus ?",
            ["DialogueId"] = 51006810,
            ["GUID"] = "7FB0B0C4",
            ["NextDialogue"] = 51006811,
            ["SpeakNpcId"] = 700133,
            ["SpeakNpcName"] = "UI_Npc_Name_Nifu",
            ["TalkActionId"] = {
                [1] = "700133:Explain02_End",
                },
            },
        [51006811] = {
            ["Content"] = "你怎么知道？",
            ["ContentFR"] = "Comment le savez-vous ?",
            ["DialogueId"] = 51006811,
            ["FacialId"] = {
                [1] = "100001:Shock01",
                },
            ["GUID"] = "7FB0B0EE",
            ["NextDialogue"] = 51006812,
            ["SpeakNpcId"] = 100001,
            },
        [51006812] = {
            ["Content"] = "我的双眼能看到灵魂所思之物。",
            ["ContentFR"] = "Mes yeux perçoivent ce que les âmes désirent.",
            ["DialogueId"] = 51006812,
            ["GUID"] = "7FB0B118",
            ["NextDialogue"] = 51006813,
            ["SpeakNpcId"] = 700133,
            ["SpeakNpcName"] = "UI_Npc_Name_Nifu",
            ["TalkActionId"] = {
                [1] = "700133:Agree",
                },
            },
        [51006813] = {
            ["Content"] = "方才，在引导她归去之时，我看到了她牵念的一切，其中便有你的身影。",
            ["ContentFR"] = "Tandis que je la conduisais, j’ai aperçu ce qui lui tenait le plus à cœur. Et parmi ces visions... ton visage est apparu.",
            ["DialogueId"] = 51006813,
            ["GUID"] = "7FB0B142",
            ["NextDialogue"] = 51006814,
            ["Scripts"] = "LookAt{_delay{2},LookAtDescription{\"700133:n(100001)\"}}",
            ["SpeakNpcId"] = 700133,
            ["SpeakNpcName"] = "UI_Npc_Name_Nifu",
            ["TalkActionId"] = {
                [1] = "700133:Think_Start",
                },
            },
        [51006814] = {
            ["Camera"] = "-107.791016,-87.445312,208.306641,0.000234,-20.00128,-75.339943,50.0,161.900574,false,Manual,4.684293",
            ["Content"] = "……她是我的朋友。",
            ["ContentFR"] = "... C’était mon amie.",
            ["DialogueId"] = 51006814,
            ["FinalCamera"] = "-107.791016,-87.445312,205.959961,0.000234,-20.00128,-75.339943,50.0,161.900574,false,Manual,4.684293",
            ["GUID"] = "7FB0B16C",
            ["NextDialogue"] = 51006815,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Explain02_Start",
                [2] = "700133:Think_End",
                },
            ["ToFinalCameraBlendTime"] = 6,
            },
        [51006815] = {
            ["Content"] = "我……没能保护好她。她或许是……对我感到失望。",
            ["ContentFR"] = "Je... je n’ai pas su la protéger. Elle doit être... déçue de moi.",
            ["DialogueId"] = 51006815,
            ["FacialId"] = {
                [1] = "100001:Sad01",
                },
            ["GUID"] = "7FB0B196",
            ["NextDialogue"] = 51006816,
            ["Scripts"] = "PlayAnimation{_delay{2},ActorId{100001},AnimationId{\"Disagree\"},Duration{0.1}}",
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Explain02_End",
                },
            },
        [51006816] = {
            ["Camera"] = "-108.74707,-318.570312,141.492188,0.000272,-5.401217,74.453423,50.0,406.774475,false,Manual,11.670671",
            ["Content"] = "不，恰恰相反。我曾见过许多怀抱着强烈的遗憾与怨恨归去的灵魂，他们的恸哭悲号，如浓雾一般溢满河岸。",
            ["ContentFR"] = "Non. Bien au contraire. J’ai vu tant d’âmes partir avec la rancune au ventre, noyées de regrets, leurs cris emplissant la rive comme une brume étouffante.",
            ["DialogueId"] = 51006816,
            ["FinalCamera"] = "-112.657227,-317.488281,141.492188,0.000272,-5.401217,74.453423,50.0,406.774475,false,Manual,11.670671",
            ["GUID"] = "7FB0B1C0",
            ["NextDialogue"] = 51006817,
            ["SpeakNpcId"] = 700133,
            ["SpeakNpcName"] = "UI_Npc_Name_Nifu",
            ["TalkActionId"] = {
                [1] = "700133:Disagree",
                },
            ["ToFinalCameraBlendTime"] = 6,
            },
        [51006817] = {
            ["Camera"] = "-120.291992,-125.242188,65.380859,0.000261,13.99884,64.854691,50.0,245.850052,false,Manual,11.670671",
            ["Content"] = "但是，那个灵魂的声音非常温柔。没有哀叹，也没有愤怒与不甘，而是在诉说感谢以及……祝福。",
            ["ContentFR"] = "Mais la sienne... était douce. Ni plainte, ni colère, ni ressentiment. Seulement des paroles de gratitude... et de bénédiction.",
            ["DialogueId"] = 51006817,
            ["GUID"] = "7FB0B1EA",
            ["NextDialogue"] = 51006818,
            ["SpeakNpcId"] = 700133,
            ["SpeakNpcName"] = "UI_Npc_Name_Nifu",
            ["TalkActionId"] = {
                [1] = "700133:Talk02_Start",
                },
            },
        [51006818] = {
            ["Camera"] = "-53.820312,278.359375,119.661133,0.000265,1.398256,-88.943329,80.0,202.867935,false,Manual,11.670671",
            ["CameraBlendCurve"] = "easeOutQuad",
            ["Content"] = "或许，那便是她所为你留下的。",
            ["ContentFR"] = "Peut-être était-ce là son dernier cadeau pour toi.",
            ["DialogueId"] = 51006818,
            ["FinalCamera"] = "-53.820312,278.359375,119.661133,0.000265,1.398256,-88.943329,80.0,522.565857,false,Manual,11.670671",
            ["GUID"] = "7FB0B214",
            ["NextDialogue"] = 51006819,
            ["SpeakNpcId"] = 700133,
            ["SpeakNpcName"] = "UI_Npc_Name_Nifu",
            ["TalkActionId"] = {
                [1] = "700133:Talk02_End",
                },
            ["ToFinalCameraBlendTime"] = 5,
            },
        [51006819] = {
            ["Content"] = "可是……",
            ["ContentFR"] = "Mais...",
            ["DialogueId"] = 51006819,
            ["GUID"] = "7FB0B23E",
            ["NextOptions"] = {
                [1] = 51006820,
                [2] = 51006821,
                },
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Sigh_Start",
                },
            },
        [51006820] = {
            ["Content"] = "我很想念她。",
            ["ContentFR"] = "<I>Elle me manque tellement...</>",
            ["DialogueId"] = 51006820,
            ["GUID"] = "7FB0B268",
            ["NextDialogue"] = 51006822,
            },
        [51006821] = {
            ["Content"] = "我不接受这样的结局。",
            ["ContentFR"] = "<I>Je refuse d’accepter cette fin.</>",
            ["DialogueId"] = 51006821,
            ["GUID"] = "7FB0B292",
            ["NextDialogue"] = 51006822,
            },
        [51006822] = {
            ["Camera"] = "-200.257812,-533.824219,181.400391,0.000274,-6.801939,71.257195,80.0,522.565857,false,Manual,11.670671",
            ["Content"] = "（妮弗尔夫人温柔地笑了，似是早就猜到了你想说的话。）",
            ["ContentFR"] = "Dame Nifle esquisse un sourire tendre, comme si elle avait déjà deviné ta réponse.",
            ["DialogueId"] = 51006822,
            ["GUID"] = "7FB0B2BC",
            ["NextDialogue"] = 51006823,
            ["TalkActionId"] = {
                [1] = "700133:Agree",
                },
            },
        [51006823] = {
            ["Camera"] = "-147.616211,-244.476562,75.759766,0.000265,7.39762,69.851921,80.0,318.95755,false,Manual,11.670671",
            ["Content"] = "孩子，我已经在这世上活了很久、很久，送别了无数的亡魂，也曾无数次听过这样的话语。",
            ["ContentFR"] = "Mon enfant... J’ai vécu si longtemps, escorté d’innombrables âmes, et tant de fois j’ai entendu les mêmes mots que les tiens.",
            ["DialogueId"] = 51006823,
            ["FinalCamera"] = "-147.616211,-244.476562,78.396484,0.000265,7.39762,69.851921,80.0,318.95755,false,Manual,11.670671",
            ["GUID"] = "7FB0B2E6",
            ["NextDialogue"] = 51006824,
            ["SpeakNpcId"] = 700133,
            ["SpeakNpcName"] = "UI_Npc_Name_Nifu",
            ["TalkActionId"] = {
                [1] = "100001:Sigh_End",
                },
            ["ToFinalCameraBlendTime"] = 6,
            },
        [51006824] = {
            ["Camera"] = "-2590.543945,-1518.859375,933.94043,0.000426,-19.601589,29.648626,18.0,318.95755,false,Disable,11.670671",
            ["Content"] = "草木会因一场山火而化作焦土，虫豸会因一阵狂风而溺于深水……无常本就是生命的一部分。或早或晚，死亡终将来临。",
            ["ContentFR"] = "Les forêts se consument sous les flammes, les insectes se noient dans les tempêtes... L’impermanence est la loi même de l’existence. Tôt ou tard, la mort nous atteint tous.",
            ["DialogueId"] = 51006824,
            ["FinalCamera"] = "-2618.442383,-1534.75,945.375,0.000426,-19.601589,29.648626,18.0,318.95755,false,Disable,11.670671",
            ["GUID"] = "7FB0B310",
            ["LookAt"] = {
                [1] = "700133:p(200218510060P2)",
                },
            ["NextDialogue"] = 51006825,
            ["SpeakNpcId"] = 700133,
            ["SpeakNpcName"] = "UI_Npc_Name_Nifu",
            ["ToFinalCameraBlendTime"] = 10,
            },
        [51006825] = {
            ["Camera"] = "-100.15625,166.824219,62.766602,0.000582,37.387058,-69.136719,18.0,318.95755,false,Disable,11.670671",
            ["Content"] = "除了诅咒命运的冷漠与残酷，或是哀叹自我的无力与渺小，我们还可以选择……珍惜切实拥有的回忆。",
            ["ContentFR"] = "Face à cela, nous avons le choix : maudire la cruauté du destin, pleurer notre impuissance... ou bien chérir les souvenirs que nous avons réellement vécus.",
            ["DialogueId"] = 51006825,
            ["FinalCamera"] = "-100.15625,166.824219,58.511719,0.000582,37.387058,-69.136719,18.0,318.95755,false,Disable,11.670671",
            ["GUID"] = "7FB0B33A",
            ["NextDialogue"] = 51006826,
            ["Scripts"] = "CameraMoveTo{_delay{3.1},TargetPosition{\"-116.790039,-32.921875,80.651367,0.000596,20.386126,46.463051,50.0,318.95755,false,Disable,11.670671\"},duration{0}}",
            ["SpeakNpcId"] = 700133,
            ["SpeakNpcName"] = "UI_Npc_Name_Nifu",
            ["ToFinalCameraBlendTime"] = 3,
            },
        [51006826] = {
            ["Camera"] = "-112.657227,-317.488281,141.492188,0.000272,-5.401217,74.453423,50.0,406.774475,false,Manual,11.670671",
            ["Content"] = "毕竟，如果说死亡是“必然”，那么活着的每一日，不正是与它擦肩而过的“奇迹”吗？",
            ["ContentFR"] = "Après tout... si la mort est l’inévitable, n’est-ce pas un miracle que chaque jour passé en vie.",
            ["DialogueId"] = 51006826,
            ["FinalCamera"] = "-108.74707,-318.570312,141.492188,0.000272,-5.401217,74.453423,50.0,406.774475,false,Manual,11.670671",
            ["GUID"] = "7FB0B364",
            ["LookAt"] = {
                [1] = "700133:n(100001)",
                },
            ["NextDialogue"] = 51006827,
            ["SpeakNpcId"] = 700133,
            ["SpeakNpcName"] = "UI_Npc_Name_Nifu",
            ["ToFinalCameraBlendTime"] = 6,
            },
        [51006827] = {
            ["Camera"] = "-108.535156,-156.035156,123.041016,0.000277,-1.200986,70.850563,50.0,262.367676,false,Manual,11.670671",
            ["Content"] = "我想，去往了雾海的那个灵魂，也一定会希望……当你回忆起与她共同经历的时日，你是面带笑意的，而非哀怜和悲泣。",
            ["ContentFR"] = "Je crois que cette âme, partie vers la Mer du Silence, souhaite que, lorsque tu repenseras à vos instants partagés... ce soit un sourire qui vienne à tes lèvres, et non des larmes.",
            ["DialogueId"] = 51006827,
            ["GUID"] = "7FB0B38E",
            ["NextOptions"] = {
                [1] = 51006828,
                },
            ["SpeakNpcId"] = 700133,
            ["SpeakNpcName"] = "UI_Npc_Name_Nifu",
            ["TalkActionId"] = {
                [1] = "700133:Give",
                },
            },
        [51006828] = {
            ["Content"] = "“雾海”到底是什么地方？",
            ["ContentFR"] = "Qu’est-ce que la \"Mer du Silence\", au juste ?",
            ["DialogueId"] = 51006828,
            ["GUID"] = "7FB0B3B8",
            ["NextDialogue"] = 51006829,
            },
        [51006829] = {
            ["Camera"] = "-95.244141,-1.792969,77.727539,0.000237,25.99535,65.250359,18.0,262.367676,false,Disable,11.670671",
            ["Content"] = "雾海……是卡戎之民的生命之源，亦是安眠之地。亡者的灵魂回归雾海，生者的灵魂从中诞生。生命如此循环流转，生生不息。",
            ["ContentFR"] = "La Mer du Silence... est l’origine et le repos des Charons. Les âmes des défunts y retournent, celles des vivants en émergent. Ainsi la vie circule, sans fin ni rupture.",
            ["DialogueId"] = 51006829,
            ["FinalCamera"] = "-100.587891,0.652344,77.727539,0.000236,25.99535,65.250565,18.0,262.367676,false,Disable,11.670671",
            ["GUID"] = "7FB0B3E2",
            ["NextDialogue"] = 51006830,
            ["SpeakNpcId"] = 700133,
            ["SpeakNpcName"] = "UI_Npc_Name_Nifu",
            ["ToFinalCameraBlendTime"] = 6,
            },
        [51006830] = {
            ["Camera"] = "-111.96875,-162.601562,135.374023,0.000258,6.394546,-70.962959,27.0,262.367676,false,Disable,11.670671",
            ["Content"] = "如果是那样……",
            ["ContentFR"] = "Alors, si c’est ainsi...",
            ["DialogueId"] = 51006830,
            ["FacialId"] = {
                [1] = "100001:Shock01",
                },
            ["GUID"] = "7FB0B40C",
            ["NextDialogue"] = 51006831,
            ["NextOptions"] = {
                [1] = 51006831,
                [2] = 51006832,
                },
            ["SpeakNpcId"] = 100001,
            },
        [51006831] = {
            ["Content"] = "我能去雾海把她带回来吗？",
            ["ContentFR"] = "<I>Puis-je aller là-bas pour la ramener ?</>",
            ["DialogueId"] = 51006831,
            ["GUID"] = "7FB0B436",
            ["NextDialogue"] = 51006833,
            },
        [51006832] = {
            ["Content"] = "她还会回到我身边吗？",
            ["ContentFR"] = "<I>Reviendra-t-elle un jour à mes côtés ?</>",
            ["DialogueId"] = 51006832,
            ["GUID"] = "7FB0B460",
            ["NextDialogue"] = 51006833,
            },
        [51006833] = {
            ["Camera"] = "-792.569336,-40.027344,85.155273,0.000242,-0.205042,-2.348938,18.000004,262.367676,false,Disable,11.670671",
            ["Content"] = "（妮弗尔夫人没有立刻回答。她抬起那双满含温柔与悲悯的眼眸，静静地看着你，半晌之后才再度开口——）",
            ["ContentFR"] = "Dame Nifle ne répond pas aussitôt. Elle lève vers toi un regard plein de douceur et de compassion. Après un long silence, elle reprend d’une voix calme :",
            ["DialogueId"] = 51006833,
            ["FinalCamera"] = "-809.700195,-39.3125,85.211914,0.000242,-0.205042,-2.348938,18.000004,262.367676,false,Disable,11.670671",
            ["GUID"] = "7FB0B48A",
            ["NextDialogue"] = 51006834,
            ["ToFinalCameraBlendTime"] = 6,
            },
        [51006834] = {
            ["Camera"] = "-134.571289,-64.273438,162.016602,0.000233,-12.205288,51.838001,50.0,262.367676,false,Disable,11.670671",
            ["Content"] = "如果向我提问的是别人，我应当会如此回答：生与死的循环是不容违背的世界法则，凭人类的力量绝对无法与之抗衡。",
            ["ContentFR"] = "Si quelqu’un d’autre m’avait posé la question, voici ce que j’aurais répondu : le cycle de la vie et de la mort est une loi inviolable. Aucun pouvoir humain ne saurait le briser.",
            ["DialogueId"] = 51006834,
            ["FinalCamera"] = "-136.608398,-62.683594,162.016602,0.000234,-12.205288,51.838234,50.0,262.367676,false,Disable,11.670671",
            ["GUID"] = "7FB0B4B4",
            ["NextDialogue"] = 51006835,
            ["SpeakNpcId"] = 700133,
            ["SpeakNpcName"] = "UI_Npc_Name_Nifu",
            ["TalkActionId"] = {
                [1] = "700133:Disagree",
                },
            ["ToFinalCameraBlendTime"] = 6,
            },
        [51006835] = {
            ["Camera"] = "-57.59375,207.816406,103.970703,0.000219,3.798521,-89.331329,80.0,445.659943,false,Manual,22.0",
            ["Content"] = "不过，孩子，我能感受得到……你背负着不同寻常的命运。",
            ["ContentFR"] = "Mais toi... toi, mon enfant, je sens en toi un destin exceptionnel.",
            ["DialogueId"] = 51006835,
            ["GUID"] = "7FB0B4DE",
            ["NextDialogue"] = 51006836,
            ["SpeakNpcId"] = 700133,
            ["SpeakNpcName"] = "UI_Npc_Name_Nifu",
            },
        [51006836] = {
            ["Camera"] = "-128.890625,-402.097656,132.947266,0.000231,-1.40176,75.0606,80.0,445.659943,false,Manual,22.0",
            ["Content"] = "有朝一日，当你获得了足够强大的力量——当你能够直面世界的真相，甚至打破构筑它的法则本身……或许，通向雾海之河亦会为你倒流。",
            ["ContentFR"] = "Un jour, quand tu auras acquis une force suffisante, quand tu pourras affronter la vérité du monde et même défier les lois qui le régissent... Peut-être alors pourras-tu marcher dans le fleuve de la vie et, à son terme, dans la Mer du Silence... revoir les âmes passées.",
            ["DialogueId"] = 51006836,
            ["FinalCamera"] = "-125.893555,-402.882812,132.947266,0.000233,-1.40176,75.060074,80.0,445.659943,false,Manual,22.0",
            ["GUID"] = "7FB0B508",
            ["LookAt"] = {
                [1] = "700133:p(200218510060P2)",
                },
            ["NextOptions"] = {
                [1] = 51006837,
                },
            ["SpeakNpcId"] = 700133,
            ["SpeakNpcName"] = "UI_Npc_Name_Nifu",
            ["ToFinalCameraBlendTime"] = 6,
            },
        [51006837] = {
            ["Content"] = "你的意思是……？！",
            ["ContentFR"] = "<I>Vous voulez dire... ?</>",
            ["DialogueId"] = 51006837,
            ["GUID"] = "7FB0B532",
            ["NextDialogue"] = 51006838,
            },
        [51006838] = {
            ["Camera"] = "-239.978516,-66.265625,99.682617,0.000237,6.198123,33.460938,80.000008,264.973846,false,Manual,22.0",
            ["Content"] = "呵呵……我不过是驻于河畔的一介旁观者。这个问题的答案，只能由你自己寻得。",
            ["ContentFR"] = "Hé hé... je ne suis qu’une observatrice sur le rivage. La réponse à cette question, seule, tu dois la découvrir.",
            ["DialogueId"] = 51006838,
            ["GUID"] = "7FB0B55C",
            ["LookAt"] = {
                [1] = "700133:n(100001)",
                },
            ["NextDialogue"] = 51006839,
            ["SpeakNpcId"] = 700133,
            ["SpeakNpcName"] = "UI_Npc_Name_Nifu",
            },
        [51006839] = {
            ["Camera"] = "-142.427734,-464.648438,180.995117,0.000256,-7.402442,75.056717,80.000008,411.46283,false,Disable,22.0",
            ["Content"] = "如果你真的心怀渴望，那么，就请继续前进吧。",
            ["ContentFR"] = "Si ton cœur la désire vraiment, alors poursuis ton chemin.",
            ["DialogueId"] = 51006839,
            ["GUID"] = "7FB0B586",
            ["NextDialogue"] = 51006840,
            ["SpeakNpcId"] = 700133,
            ["SpeakNpcName"] = "UI_Npc_Name_Nifu",
            ["TalkActionId"] = {
                [1] = "700133:Agree",
                },
            },
        [51006840] = {
            ["Content"] = "一路顺风，亲爱的孩子。",
            ["ContentFR"] = "Que les vents te soient favorables, mon cher enfant.",
            ["DialogueId"] = 51006840,
            ["GUID"] = "7FB0B5B0",
            ["SpeakNpcId"] = 700133,
            ["SpeakNpcName"] = "UI_Npc_Name_Nifu",
            ["TalkActionId"] = {
                [1] = "700133:Give",
                },
            },
        [51006841] = {
            ["Content"] = "孩子，纵是前路无常，也请你坚定地走下去吧。",
            ["ContentFR"] = "Même si la route est incertaine, avance avec détermination.",
            ["DialogueId"] = 51006841,
            ["GUID"] = "7FB0B5DA",
            ["NextDialogue"] = 51006842,
            ["SpeakNpcId"] = 700133,
            ["SpeakNpcName"] = "UI_Npc_Name_Nifu",
            },
        [51006842] = {
            ["Content"] = "愿母神茵布拉赐福于你。",
            ["ContentFR"] = "Que la Mère Embla t’accorde sa bénédiction.",
            ["DialogueId"] = 51006842,
            ["GUID"] = "7FB0B604",
            ["SpeakNpcId"] = 700133,
            ["SpeakNpcName"] = "UI_Npc_Name_Nifu",
            },
        [51006901] = {
            ["Camera"] = "475.811523,676.893555,129.602295,0.000004,0.0,-119.200165,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "（列车售票亭吸引了你的注意：你回忆起从玛尔洁那里得到的“货物”，它们中的某一个似乎与“车票”有关。）",
            ["ContentFR"] = "Le guichet du train attire ton regard : tu te rappelles des objets confiés par Margie, l’un d’eux était lié aux billets de train.",
            ["DialogueId"] = 51006901,
            ["FinalCamera"] = "475.811523,694.0,129.602295,0.000004,0.0,-119.200157,35.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "7FB0BFB2",
            ["LookAt"] = {
                [1] = "700147:n(700148)",
                [2] = "700148:n(700147)",
                },
            ["NextDialogue"] = 51006902,
            ["TalkActionId"] = {
                [1] = "100001:Think_Start",
                },
            ["ToFinalCameraBlendTime"] = 5,
            },
        [51006902] = {
            ["Camera"] = "475.811523,694.0,129.602295,0.000004,0.0,-119.200157,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "（你来得不凑巧，一个异国打扮的卡戎之民与售票员起了冲突。）",
            ["ContentFR"] = "Pas de chance, un Charon aux habits étrangers est en pleine dispute avec la guichetière.",
            ["DialogueId"] = 51006902,
            ["GUID"] = "7FB0BFDC",
            ["NextDialogue"] = 51006903,
            ["TalkActionId"] = {
                [1] = "700147:Confident_Start",
                [2] = "100001:Think_End",
                },
            },
        [51006903] = {
            ["Camera"] = "50.741211,214.74707,179.342529,0.000012,-8.799981,-110.198242,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "没钱就滚开！",
            ["ContentFR"] = "Pas d’argent ? Dégage !",
            ["DialogueId"] = 51006903,
            ["GUID"] = "7FB0C006",
            ["NextDialogue"] = 51006904,
            ["SpeakNpcId"] = 700147,
            },
        [51006904] = {
            ["Camera"] = "70.262695,-223.553711,140.896484,0.00001,0.0,109.401634,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "天呐，我只想一问！你为何狂躁！",
            ["ContentFR"] = "Bon sang ! J’ai juste posé une question ! Pourquoi tant de colère ?",
            ["DialogueId"] = 51006904,
            ["GUID"] = "7FB0C030",
            ["NextDialogue"] = 51006905,
            ["SpeakNpcId"] = 700148,
            ["TalkActionId"] = {
                [1] = "700147:Confident_End",
                [2] = "700148:Shock_Start",
                },
            },
        [51006905] = {
            ["Camera"] = "50.741211,214.74707,179.342529,0.000012,-8.799981,-110.198242,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "哦好的，这位怪腔怪调的穷鬼先生，在我礼貌地告诉你票价后，你打算怎么做？搓搓自己漏不出一个子儿的破口袋对我颐指气使？",
            ["ContentFR"] = "Ah, d’accord... Monsieur \"accent bizarre\", après que je t’ai poliment donné le prix du billet, tu comptes faire quoi ? Fouiller tes poches vides et me donner des ordres ?",
            ["DialogueId"] = 51006905,
            ["GUID"] = "7FB0C05A",
            ["NextDialogue"] = 51006906,
            ["SpeakNpcId"] = 700147,
            ["TalkActionId"] = {
                [1] = "700147:Talk03_Start",
                [2] = "700148:Shock_End",
                },
            },
        [51006906] = {
            ["Camera"] = "33.833008,-38.410156,159.227783,0.00001,0.999987,101.202133,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "你在讲什么？你怎知我没——",
            ["ContentFR"] = "Quoi ? Comment tu sais que—",
            ["DialogueId"] = 51006906,
            ["GUID"] = "7FB0C084",
            ["NextDialogue"] = 51006907,
            ["SpeakNpcId"] = 700148,
            ["TalkActionId"] = {
                [1] = "700148:Explain01_Start",
                [2] = "700147:Talk03_End",
                },
            },
        [51006907] = {
            ["Camera"] = "8.34668,69.227539,155.484863,0.000015,-7.799837,-93.597458,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "知道什么？卡戎人兜里能有几个铜币？这里只属于富豪、贵族和高官，不欢迎穷光蛋！",
            ["ContentFR"] = "Savoir quoi ? Comme si un Charon pouvait avoir plus de cinq pièces ! Ici, c’est réservé aux riches, aux nobles et aux grands fonctionnaires. Pas aux clochards.",
            ["DialogueId"] = 51006907,
            ["GUID"] = "7FB0C0AE",
            ["NextDialogue"] = 51006908,
            ["SpeakNpcId"] = 700147,
            ["TalkActionId"] = {
                [1] = "700148:Explain01_End",
                [2] = "700147:Confident_Start",
                },
            },
        [51006908] = {
            ["Camera"] = "70.262695,-223.553711,140.896484,0.00001,0.0,109.401634,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "（异国人哆嗦着嘴唇，改换某种方言加以反击，然而什么也没听懂的售票员轻蔑地看了他一眼，不再理他，商人自讨没趣，悻悻离去。）",
            ["ContentFR"] = "Le marchand bredouille un peu dans sa langue maternelle, mais la guichetière lui lance un regard dédaigneux et l’ignore. Vexé, il s’éloigne.",
            ["DialogueId"] = 51006908,
            ["GUID"] = "7FB0C0D8",
            ["Scripts"] = "PARA{MoveTo{_delay{2},ActorId{700148},MoveSpeed{75},TargetPoint{\"QuestPoint_20021901Move\"}},CameraMoveTo{_delay{2},TargetPosition{\"479.638672,673.591797,127.602295,0.000004,-0.600005,-125.400406,35.0,100000.0,false,DoNotOverride,2.8\"},duration{0}}}",
            },
        [51006921] = {
            ["Content"] = "看你白白净净的，怎么也跟兄弟抢垃圾啊？",
            ["ContentFR"] = "Tiens, tiens... Regardez-moi ça. La peau bien propre, le manteau bien repassé. Qu’est-ce que tu viens faire à fouiller les poubelles avec nous ?",
            ["DialogueId"] = 51006921,
            ["GUID"] = "7FB0C0D9",
            ["NextOptions"] = {
                [1] = 51006922,
                [2] = 51006923,
                },
            ["SpeakNpcId"] = 700230,
            },
        [51006922] = {
            ["Content"] = "我还没动手呢！",
            ["ContentFR"] = "<I>Je n’ai encore rien touché !</>",
            ["DialogueId"] = 51006922,
            ["GUID"] = "7FB0C0DA",
            ["NextDialogue"] = 51006924,
            },
        [51006923] = {
            ["Content"] = "我才没有翻垃圾桶的癖好。",
            ["ContentFR"] = "<I>Je n’ai pas vraiment le goût des poubelles, merci bien.</>",
            ["DialogueId"] = 51006923,
            ["GUID"] = "7FB0C0DB",
            ["NextDialogue"] = 51006924,
            },
        [51006924] = {
            ["Content"] = "你这小孩少充楞，我都看到了。",
            ["ContentFR"] = "Fais pas {性别:l’innocent, gamin|l’innocente, gamine}. Je t’ai vu.",
            ["DialogueId"] = 51006924,
            ["GUID"] = "7FB0C0DC",
            ["NextDialogue"] = 51006925,
            ["SpeakNpcId"] = 700230,
            },
        [51006925] = {
            ["Content"] = "昨天有个穿制服的女的，一边哭，一边把这盒子丢了进去。有个拾荒的老太太好心问她怎么了，结果愣是被那凶女人劈头盖脸骂了一顿，让少管闲事。",
            ["ContentFR"] = "Hier, y avait une femme en uniforme qui est venue par ici, les larmes aux yeux. Elle a balancé une boîte dans la benne. Une vieille qui fouillait gentiment l’a interrogée, et la furie l’a incendiée, en lui disant de se mêler de ses affaires.",
            ["DialogueId"] = 51006925,
            ["GUID"] = "7FB0C0DD",
            ["NextDialogue"] = 51006926,
            ["SpeakNpcId"] = 700230,
            },
        [51006926] = {
            ["Content"] = "喏，就是你手上那个盒子。还说你不是从垃圾桶捡的？",
            ["ContentFR"] = "Et devine quoi ? La boîte que t’as dans les mains, c’est celle-là. Alors, toujours {性别:sûr|sûre} de pas l’avoir pêchée dans la poubelle ?",
            ["DialogueId"] = 51006926,
            ["GUID"] = "7FB0C0DE",
            ["NextDialogue"] = 51006927,
            ["SpeakNpcId"] = 700230,
            },
        [51006927] = {
            ["Content"] = "不是我……算了懒得解释了，总之谢谢你告诉我失主的信息。",
            ["ContentFR"] = "Ce n’est pas moi... enfin peu importe, pas envie d’entrer dans les détails. Merci de m’avoir donné un indice sur sa propriétaire.",
            ["DialogueId"] = 51006927,
            ["GUID"] = "7FB0C0DF",
            ["NextDialogue"] = 51006928,
            ["SpeakNpcId"] = 100001,
            },
        [51006928] = {
            ["Content"] = "（穿制服的凶女人……会和玛尔洁的“哪件货物”有关呢？）",
            ["ContentFR"] = "<I>Une femme en uniforme... Est-ce que ça aurait un lien avec les objets de Margie ?</>",
            ["DialogueId"] = 51006928,
            ["GUID"] = "7FB0C0E0",
            ["SpeakNpcId"] = 100001,
            },
        [51006931] = {
            ["Content"] = "成为售票员的第一年零八个月，我终于攒够了可以从冰湖城坐到南方丹流城的车票钱。",
            ["ContentFR"] = "Après un an et huit mois travaillant en tant que guichetière, j’ai enfin réuni assez d’argent pour acheter un billet jusqu’à Rougerive, dans le sud.",
            ["DialogueId"] = 51006931,
            ["GUID"] = "7FB0C49E",
            ["NextDialogue"] = 51006932,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Jiexi",
            },
        [51006932] = {
            ["Content"] = "这不是很好吗？你在一步步接近梦想。",
            ["ContentFR"] = "C’est une victoire, non ? Tu avances vers ton rêve.",
            ["DialogueId"] = 51006932,
            ["GUID"] = "7FB0C4C8",
            ["NextDialogue"] = 51006933,
            ["SpeakNpcId"] = 100001,
            },
        [51006933] = {
            ["Content"] = "接近？你忘了<H>卡戎监护金</>了吗？票本身的价格连买票要交的监护金零头都不到！要想买去他那边的票，我要不吃不喝五年！可我还有家要养……",
            ["ContentFR"] = "Avancer ? Tu oublies les <H>taxes de surveillance</> imposées aux Charons ? Le billet, c’était rien comparé à ça. Pour espérer rejoindre le sud, il m’aurait fallu cinq ans d’économie... sans manger ni boire. Et j’ai une famille à nourrir.",
            ["DialogueId"] = 51006933,
            ["GUID"] = "7FB0C4F2",
            ["NextDialogue"] = 51007147,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Jiexi",
            },
        [51007001] = {
            ["Content"] = "你来打听，火车信息？希望远离，有刻薄女性驻守关卡！",
            ["ContentFR"] = "Toi, venu pour infos sur train ? Attention, méchante guichetière, garde amère !",
            ["DialogueId"] = 51007001,
            ["GUID"] = "7FB0D01A",
            ["LookAt"] = {
                [1] = "700149:n(0)",
                },
            ["NextOptions"] = {
                [1] = 510070011,
                [2] = 510070012,
                },
            ["SpeakNpcId"] = 700149,
            ["TurnTo"] = {
                [1] = "700149:n(0)",
                },
            ["bForbidSkipOptions"] = true,
            },
        [51007002] = {
            ["Content"] = "已经受够！特别、非常、极其想走！",
            ["ContentFR"] = "Moi, non ! Moi, très, très envie partir !",
            ["DialogueId"] = 51007002,
            ["GUID"] = "7FB0D044",
            ["LookAt"] = {
                [1] = "700149:n(0)",
                },
            ["NextDialogue"] = 51007004,
            ["SpeakNpcId"] = 700149,
            ["TurnTo"] = {
                [1] = "700149:n(0)",
                },
            },
        [51007003] = {
            ["Content"] = "在学了！此地口音，和故乡，有差别！",
            ["ContentFR"] = "J’apprends ! Accent d’ici, pas comme chez moi.",
            ["DialogueId"] = 51007003,
            ["GUID"] = "7FB0D06E",
            ["LookAt"] = {
                [1] = "700149:n(0)",
                },
            ["NextDialogue"] = 51007004,
            ["SpeakNpcId"] = 700149,
            ["TurnTo"] = {
                [1] = "700149:n(0)",
                },
            },
        [51007004] = {
            ["Content"] = "（这个售票员看着很不好惹。但考虑到你总有一天会离开冰湖城，和她打交道是必须的……是否应该现在采取些行动呢？）",
            ["ContentFR"] = "Cette guichetière a l’air coriace. Mais tôt ou tard, tu devras quitter Givrelac, il faudra bien traiter avec elle. Est-ce le moment de tenter quelque chose ?",
            ["DialogueId"] = 51007004,
            ["GUID"] = "7FB0D098",
            ["LookAt"] = {
                [1] = "700149:n(0)",
                },
            ["NextDialogue"] = 51007005,
            ["RestartTag"] = 51007004,
            ["TurnTo"] = {
                [1] = "700149:n(0)",
                },
            },
        [51007005] = {
            ["Content"] = "（你手上这份来自玛尔洁的“情报”，或许可以用来打开话题……）",
            ["ContentFR"] = "Et peut-être que l’information confiée par Margie peut servir à amorcer la conversation...",
            ["DialogueId"] = 51007005,
            ["GUID"] = "7FB0D0C2",
            ["LookAt"] = {
                [1] = "700149:n(0)",
                },
            ["NextOptions"] = {
                [1] = 510070051,
                },
            ["TurnTo"] = {
                [1] = "700149:n(0)",
                },
            ["bForbidSkipOptions"] = true,
            },
        [51007006] = {
            ["Content"] = "（有心无力，一时没想到什么好办法。）",
            ["ContentFR"] = "Tu voudrais intervenir, mais aucune idée ne te vient.",
            ["DialogueId"] = 51007006,
            ["GUID"] = "7FB0D0EC",
            },
        [51007007] = {
            ["Content"] = "感谢！为您喝彩！我全程目击该事件！",
            ["ContentFR"] = "Bravo ! Tu as géré ! J’ai tout vu !",
            ["DialogueId"] = 51007007,
            ["GUID"] = "7FB0D116",
            ["SpeakNpcId"] = 700149,
            ["TalkActionId"] = {
                [1] = "700149:Agree",
                },
            },
        [51007101] = {
            ["Content"] = "（你和异国人走到售票亭前，售票员杰西卡上下打量你几眼，冷冷地开了口。）",
            ["ContentFR"] = "Tu t’avances au guichet avec le marchand. La guichetière, Jessica, te dévisage froidement.",
            ["DialogueId"] = 51007101,
            ["GUID"] = "7FB0E082",
            ["NextDialogue"] = 51007102,
            },
        [51007102] = {
            ["Content"] = "怎么又来了个穷酸卡戎？",
            ["ContentFR"] = "Encore {性别:un Charon fauché|une Charon fauchée} ?",
            ["DialogueId"] = 51007102,
            ["GUID"] = "7FB0E0AC",
            ["LookAt"] = {
                [1] = "700147:n(0)",
                [2] = "700148:n(700147)",
                },
            ["NextDialogue"] = 51007103,
            ["SpeakNpcId"] = 700147,
            ["TalkActionId"] = {
                [1] = "700147:Talk01_Start",
                },
            ["TurnTo"] = {
                [1] = "700147:n(0)",
                },
            },
        [51007103] = {
            ["Content"] = "注意你的态度，我可不是什么“穷酸卡戎”。修普诺斯之家的老板你知道吧，他空置的那间宅子现在是我租着。",
            ["ContentFR"] = "Surveille ton langage. Je ne suis pas {性别:un \"fauché\"|une \"fauchée\"}. Tu connais la Maison d’Hypnos ? Eh bien, c’est moi qui loue une de ses propriétés.",
            ["DialogueId"] = 51007103,
            ["GUID"] = "7FB0E0D6",
            ["NextDialogue"] = 51007104,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "700147:Talk01_End",
                },
            },
        [51007104] = {
            ["Content"] = "哈？谁都知道那个臭脸大叔最讨厌外乡人，你说谎不打草稿吗？既然得了幻想症，就把自己关在那“大宅子”里哪儿也别去！",
            ["ContentFR"] = "Quoi ? Tout le monde sait que ce vieux grincheux déteste les étrangers. Tu devrais faire quelques recherches avant d’essayer d’impressionner des gens avec ton mensonge. Allez, enferme-toi dans ton \"manoir\" et épargne-nous tes délires.",
            ["DialogueId"] = 51007104,
            ["GUID"] = "7FB0E100",
            ["NextDialogue"] = 51007105,
            ["SpeakNpcId"] = 700147,
            ["TalkActionId"] = {
                [1] = "700147:Confident_Start",
                },
            },
        [51007105] = {
            ["Content"] = "过分！请说词，让她止住刻薄语言！",
            ["ContentFR"] = "C’est trop ! Dis-lui, fais-la taire !",
            ["DialogueId"] = 51007105,
            ["GUID"] = "7FB0E12A",
            ["LookAt"] = {
                [1] = "700147:n(700148)",
                },
            ["NextOptions"] = {
                [1] = 51007106,
                },
            ["SpeakNpcId"] = 700148,
            ["TalkActionId"] = {
                [1] = "700147:Confident_End",
                [2] = "700148:Talk03_Start",
                },
            },
        [51007106] = {
            ["Content"] = "（将玛尔洁赠予的一盒纸星星放在售票员的桌子上。）",
            ["ContentFR"] = "<I>Poser la boîte d’étoiles en papier donnée par Margie sur le comptoir</>",
            ["DialogueId"] = 51007106,
            ["GUID"] = "7FB0E154",
            ["NextDialogue"] = 51007107,
            },
        [51007107] = {
            ["Content"] = "（看到纸星星的瞬间，售票员的神色有些动摇。但她很快恢复了刚才的表情，嫌弃地瞥了你一眼。）",
            ["ContentFR"] = "En voyant les étoiles, Jessica a une seconde d’hésitation, mais se reprend vite et t’adresse un regard dédaigneux.",
            ["DialogueId"] = 51007107,
            ["GUID"] = "7FB0E17E",
            ["NextDialogue"] = 51007108,
            ["TalkActionId"] = {
                [1] = "700148:Talk03_End",
                },
            },
        [51007108] = {
            ["Content"] = "这是哪个桶捡来的垃圾？你把这儿当垃圾回收站？给我扔掉！",
            ["ContentFR"] = "Et c’est quoi, ça ? De la camelote sortie d’une poubelle ? Tu crois que je suis aussi un centre de recyclage ? Dégage ça d’ici !",
            ["DialogueId"] = 51007108,
            ["GUID"] = "7FB0E1A8",
            ["LookAt"] = {
                [1] = "700147:n(0)",
                },
            ["NextDialogue"] = 51007109,
            ["SpeakNpcId"] = 700147,
            ["TalkActionId"] = {
                [1] = "700147:Angry01_Start",
                },
            },
        [51007109] = {
            ["Content"] = "为什么说是垃圾？在我看来，这是很用心完成的手工艺品，可以感觉到制作者真挚的感情。",
            ["ContentFR"] = "Pourquoi \"camelote\" ? Moi, j’y vois un travail minutieux, plein de sincérité et de sentiment.",
            ["DialogueId"] = 51007109,
            ["GUID"] = "7FB0E1D2",
            ["NextDialogue"] = 51007110,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "700147:Angry01_End",
                },
            },
        [51007110] = {
            ["Content"] = "华胥也有，折纸星星习俗。据说，折得多，会美梦成真。",
            ["ContentFR"] = "Chez nous aussi, à Huaxu, on plie étoiles de papier. On dit : plus tu en fais, plus tes rêves se réalisent.",
            ["DialogueId"] = 51007110,
            ["GUID"] = "7FB0E1FC",
            ["LookAt"] = {
                [1] = "700148:n(0)",
                },
            ["NextDialogue"] = 51007111,
            ["SpeakNpcId"] = 700148,
            ["TalkActionId"] = {
                [1] = "700148:Think_Start",
                },
            },
        [51007111] = {
            ["Content"] = "原来是这样……怪不得，我之前想研究一下它是怎么叠起来的，就拆了一个，结果发现里面写了字。",
            ["ContentFR"] = "Je comprends mieux... J’ai voulu en déplier une, pour comprendre le pliage, et j’ai trouvé des mots écrits à l’intérieur.",
            ["DialogueId"] = 51007111,
            ["GUID"] = "7FB0E226",
            ["NextDialogue"] = 51007112,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "700148:Think_End",
                },
            },
        [51007112] = {
            ["Content"] = "上面写的好像正是……某个人许下的愿望？",
            ["ContentFR"] = "C’était... comme un vœu ?",
            ["DialogueId"] = 51007112,
            ["GUID"] = "7FB0E250",
            ["NextDialogue"] = 51007113,
            ["SpeakNpcId"] = 100001,
            },
        [51007113] = {
            ["Content"] = "你……你都打开看了？！",
            ["ContentFR"] = "Tu... tu les as ouverts ?!",
            ["DialogueId"] = 51007113,
            ["GUID"] = "7FB0E27A",
            ["LookAt"] = {
                [1] = "700148:n(700147)",
                },
            ["NextDialogue"] = 51007114,
            ["SpeakNpcId"] = 700147,
            ["TalkActionId"] = {
                [1] = "700147:Sigh_Start",
                },
            },
        [51007114] = {
            ["Content"] = "我只看了一张。我发现它是用车票折的，背面写的文字也和列车有关，所以我才想来车站看看，想着也许能物归原主。",
            ["ContentFR"] = "Juste un. J’ai vu que c’était plié dans un billet de train, avec un message lié au voyage. Alors je suis venu ici, pensant retrouver le propriétaire.",
            ["DialogueId"] = 51007114,
            ["GUID"] = "7FB0E2A4",
            ["NextDialogue"] = 51007115,
            ["SpeakNpcId"] = 100001,
            },
        [51007115] = {
            ["Content"] = "但既然你说是垃圾，那就随我处置喽。",
            ["ContentFR"] = "Mais puisque tu dis que c’est des ordures... je peux les garder, non ?",
            ["DialogueId"] = 51007115,
            ["GUID"] = "7FB0E2CE",
            ["NextDialogue"] = 51007116,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "700147:Sigh_End",
                },
            },
        [51007116] = {
            ["Content"] = "（你将纸星星拿在手里，再次看向售票员。她的目光分明跟着盒子移了过来，但她似乎还是不愿意开口。）",
            ["ContentFR"] = "Tu reprends la boîte. Ses yeux suivent clairement le mouvement, mais elle reste silencieuse.",
            ["DialogueId"] = 51007116,
            ["GUID"] = "7FB0E2F8",
            ["NextOptions"] = {
                [1] = 510071161,
                [2] = 510071162,
                },
            },
        [51007117] = {
            ["Content"] = "许愿的那个人虽然买不起车票，但还是忍不住把看起来像车站的词写在星星上。应该是希望有一天可以美梦成真，真的抵达这些地方吧。",
            ["ContentFR"] = "La personne qui a fait ces étoiles n’avait probablement pas assez pour un billet. Pourtant, elle y a écrit des noms de gares, comme si, au fond, elle espérait qu’un jour son rêve se réalise et qu’elle puisse vraiment atteindre ces lieux.",
            ["DialogueId"] = 51007117,
            ["GUID"] = "7FB0E322",
            ["NextDialogue"] = 51007118,
            ["SpeakNpcId"] = 100001,
            },
        [51007118] = {
            ["Content"] = "那个人真就这么忍心把这些愿望当垃圾丢掉吗？",
            ["ContentFR"] = "Peut-on vraiment être assez cruel pour jeter ces vœux à la poubelle ?",
            ["DialogueId"] = 51007118,
            ["GUID"] = "7FB0E34C",
            ["NextDialogue"] = 51007121,
            ["SpeakNpcId"] = 100001,
            },
        [51007119] = {
            ["Content"] = "“5月21日。凯瑟琳太太把银币扔在我脚边，让我蹲着一枚枚捡起来。她说我没资格从她手中接过钱袋。唉，如果我也能像她一样有花不完的银币就好了。”",
            ["ContentFR"] = "21 mai. Madame Catherine a jeté des pièces à mes pieds et m’a forcée à les ramasser une à une. Elle disait que je n’étais pas digne de recevoir l’argent directement. Ah... si seulement j’avais, moi aussi, des pièces à volonté, comme elle...",
            ["DialogueId"] = 51007119,
            ["GUID"] = "7FB0E376",
            ["NextDialogue"] = 51007120,
            ["SpeakNpcId"] = 100001,
            },
        [51007120] = {
            ["Content"] = "“9月13日。昨晚再次梦见自己终于攒够了钱，买下车票。这次梦里的终点站是丹流城……”",
            ["ContentFR"] = "13 septembre. Encore rêvé cette nuit que j’avais enfin assez pour un billet. Cette fois, la destination était Rougerive...",
            ["DialogueId"] = 51007120,
            ["GUID"] = "7FB0E3A0",
            ["NextDialogue"] = 51007121,
            ["SpeakNpcId"] = 100001,
            },
        [51007121] = {
            ["Content"] = "……住口！别说了！",
            ["ContentFR"] = "... Assez ! Tais-toi !",
            ["DialogueId"] = 51007121,
            ["GUID"] = "7FB0E3CA",
            ["NextDialogue"] = 51007122,
            ["SpeakNpcId"] = 700147,
            ["TalkActionId"] = {
                [1] = "700147:Sigh_Start",
                },
            },
        [51007122] = {
            ["Content"] = "其实这是你的东西，对吗——",
            ["ContentFR"] = "En réalité, ces étoiles sont à toi, pas vrai ?",
            ["DialogueId"] = 51007122,
            ["GUID"] = "7FB0E3F4",
            ["NextDialogue"] = 51007123,
            ["SpeakNpcId"] = 100001,
            },
        [51007123] = {
            ["Content"] = "（你回忆了一下车票上写着的名字。）",
            ["ContentFR"] = "Tu te rappelles avoir vu un nom écrit sur un billet.",
            ["DialogueId"] = 51007123,
            ["GUID"] = "7FB0E41E",
            ["NextDialogue"] = 51007124,
            },
        [51007124] = {
            ["Content"] = "“杰西卡”？",
            ["ContentFR"] = "« Jessica » ?",
            ["DialogueId"] = 51007124,
            ["GUID"] = "7FB0E448",
            ["NextDialogue"] = 51007125,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "700147:Sigh_End",
                },
            },
        [51007125] = {
            ["Content"] = "你……",
            ["ContentFR"] = "...",
            ["DialogueId"] = 51007125,
            ["GUID"] = "7FB0E472",
            ["NextDialogue"] = 51007126,
            ["SpeakNpcId"] = 700147,
            },
        [51007126] = {
            ["Content"] = "……好吧，没错。我是杰西卡。这些垃圾确实是我扔的，行了吧？你弯弯绕绕说了一大堆，不就想看我笑话吗？",
            ["ContentFR"] = "... D’accord. Oui. C’est moi. Ces \"saletés\", c’est bien les miennes... Mais qu’est-ce que tu veux, au juste ? Te moquer de moi ?",
            ["DialogueId"] = 51007126,
            ["GUID"] = "7FB0E49C",
            ["NextDialogue"] = 51007127,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Jiexi",
            ["TalkActionId"] = {
                [1] = "700147:Agree",
                },
            },
        [51007127] = {
            ["Content"] = "没错，我和所有穷鬼一样，根本坐不起这破车，满意了吗？！",
            ["ContentFR"] = "Oui, c’est moi. Comme tous les pauvres types de ce trou, je n’ai jamais eu de quoi m’offrir un billet pour ces foutus trains. C’est ça que tu voulais entendre ? Ça te satisfait ?",
            ["DialogueId"] = 51007127,
            ["GUID"] = "7FB0E4C6",
            ["NextDialogue"] = 51007128,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Jiexi",
            ["TalkActionId"] = {
                [1] = "700147:Explain01_Start",
                },
            },
        [51007128] = {
            ["Content"] = "……什么美梦成真……都是骗人的。",
            ["ContentFR"] = "... Tous ces beaux discours sur les rêves qui se réalisent... des mensonges.",
            ["DialogueId"] = 51007128,
            ["GUID"] = "7FB0E4F0",
            ["NextDialogue"] = 51007129,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Jiexi",
            ["TalkActionId"] = {
                [1] = "700147:Explain01_End",
                },
            },
        [51007129] = {
            ["Content"] = "既然你也想乘上列车、也买不起车票，那么你本该能够理解其他和你一样的穷苦之人，为什么要对他们恶语相向？",
            ["ContentFR"] = "Si toi aussi tu veux monter à bord, mais que tu n’as pas les moyens, tu devrais comprendre les autres. Pourquoi leur cracher au visage ?",
            ["DialogueId"] = 51007129,
            ["GUID"] = "7FB0E51A",
            ["NextDialogue"] = 51007130,
            ["SpeakNpcId"] = 100001,
            },
        [51007130] = {
            ["Content"] = "呵，那我要怎么做，温柔地安慰他们吗？",
            ["ContentFR"] = "Ah oui ? Et je devrais faire quoi, au juste ? Leur chuchoter des mots doux ?",
            ["DialogueId"] = 51007130,
            ["GUID"] = "7FB0E544",
            ["NextDialogue"] = 51007131,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Jiexi",
            },
        [51007131] = {
            ["Content"] = "然后让他们产生不切实际的妄想，以为自己有一天也配坐上老爷们的列车？！",
            ["ContentFR"] = "Leur donner l’illusion qu’ils auront un jour leur place parmi les puissants ?",
            ["DialogueId"] = 51007131,
            ["GUID"] = "7FB0E56E",
            ["NextDialogue"] = 51007132,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Jiexi",
            ["TalkActionId"] = {
                [1] = "700147:Disagree",
                },
            },
        [51007132] = {
            ["Content"] = "只需好好赚钱，能坐上！我们织星客，做生意缓慢挣钱。",
            ["ContentFR"] = "Pas illusion ! Juste travailler, épargner. Nous, les Tisses-Étoiles, on vend, on met de côté. Lentement, mais possible.",
            ["DialogueId"] = 51007132,
            ["GUID"] = "7FB0E598",
            ["LookAt"] = {
                [1] = "700147:n(700148)",
                },
            ["NextDialogue"] = 51007133,
            ["SpeakNpcId"] = 700148,
            ["TalkActionId"] = {
                [1] = "700148:Explain02_Start",
                },
            },
        [51007133] = {
            ["Content"] = "你是织星客？！那你……你知道一个叫“嘉言”的华胥织星客吗？他是十三年前到过冰湖城的。",
            ["ContentFR"] = "Tu es un Tisse-Étoiles ?! Alors peut-être que tu connais un Tisse-Étoiles de Huaxu, appelé Jiayan. Il est passé par Givrelac... il y a treize ans.",
            ["DialogueId"] = 51007133,
            ["GUID"] = "7FB0E5C2",
            ["NextDialogue"] = 51007134,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Jiexi",
            ["TalkActionId"] = {
                [1] = "700148:Explain02_End",
                },
            },
        [51007134] = {
            ["Content"] = "不记得。织星客，为数众多。",
            ["ContentFR"] = "Jiayan ? Non souvenir. Beaucoup, beaucoup de Tisse-Étoiles. Impossible retenir tous.",
            ["DialogueId"] = 51007134,
            ["GUID"] = "7FB0E5EC",
            ["NextDialogue"] = 51007135,
            ["SpeakNpcId"] = 700148,
            ["TalkActionId"] = {
                [1] = "700148:Disagree",
                },
            },
        [51007135] = {
            ["Content"] = "……好吧。",
            ["ContentFR"] = "... Je vois.",
            ["DialogueId"] = 51007135,
            ["GUID"] = "7FB0E616",
            ["NextDialogue"] = 51007136,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Jiexi",
            },
        [51007136] = {
            ["Content"] = "你说的那个人，是你的朋友？",
            ["ContentFR"] = "C’était un ami à toi ?",
            ["DialogueId"] = 51007136,
            ["GUID"] = "7FB0E640",
            ["LookAt"] = {
                [1] = "700147:n(0)",
                },
            ["NextDialogue"] = 51007137,
            ["SpeakNpcId"] = 100001,
            },
        [51007137] = {
            ["Content"] = "呵呵，朋友？不，那是我最讨厌的人。",
            ["ContentFR"] = "Un ami ? Hmpf. Non. C’est l’homme que je hais le plus.",
            ["DialogueId"] = 51007137,
            ["GUID"] = "7FB0E66A",
            ["NextDialogue"] = 51007138,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Jiexi",
            ["TalkActionId"] = {
                [1] = "700147:Disagree",
                },
            },
        [51007138] = {
            ["Content"] = "（杰西卡拆开了一颗纸星星。她看一眼上面的字，又开始拆下一颗，就这样一颗一颗地拆了下去。）",
            ["ContentFR"] = "Jessica saisit une étoile, la déplie. Puis une autre, et encore une autre. Elle lit chaque mot avec un mélange de rage et de nostalgie.",
            ["DialogueId"] = 51007138,
            ["GUID"] = "7FB0E694",
            ["NextDialogue"] = 51007139,
            },
        [51007139] = {
            ["Content"] = "他说自己去过很多国家，见过许多有趣的人和事。每卖出一件货物，他就会讲一个来自远方的故事。",
            ["ContentFR"] = "Il disait avoir parcouru des dizaines de pays. Avoir rencontré des gens formidables, vécu des aventures incroyables. Chaque objet qu’il vendait venait avec une histoire, et je buvais chacune de ses paroles.",
            ["DialogueId"] = 51007139,
            ["GUID"] = "7FB0E6BE",
            ["NextDialogue"] = 51007140,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Jiexi",
            ["TalkActionId"] = {
                [1] = "700147:Explain01_Start",
                },
            },
        [51007140] = {
            ["Content"] = "我就像个傻子一样，把他故事里的每个句子都记下来，背下来，以为这样就能更接近他说的那个广阔世界。",
            ["ContentFR"] = "Comme une idiote, je les recopiais, les apprenais par cœur... croyant qu’un jour, ça me rapprocherait du monde qu’il décrivait.",
            ["DialogueId"] = 51007140,
            ["GUID"] = "7FB0E6E8",
            ["NextDialogue"] = 51007141,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Jiexi",
            ["TalkActionId"] = {
                [1] = "700147:Explain01_End",
                },
            },
        [51007141] = {
            ["Content"] = "他说“星星是愿望的种子，当它坠落，就如果实收获，你所期盼的，都会实现。”他说“无数由珍爱之物做成的星，将在地上发芽。”",
            ["ContentFR"] = "Il m’a dit un jour : « Les étoiles sont les graines des vœux. Quand elles tombent, elles deviennent des fruits, et tes désirs se réalisent. » Ou encore : « Quand on fabrique d’innombrables étoiles avec ce que l’on chérit, elles germeront un jour sur la terre. »",
            ["DialogueId"] = 51007141,
            ["GUID"] = "7FB0E712",
            ["NextDialogue"] = 51007142,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Jiexi",
            ["TalkActionId"] = {
                [1] = "700147:Explain02_Start",
                },
            },
        [51007142] = {
            ["Content"] = "我很想和他一起走，继续听他讲不完的故事。但是我买不起车票，最后只能独自目送他登上了远去的火车。",
            ["ContentFR"] = "Je voulais partir avec lui. Écouter encore ses histoires sans fin. Mais je n’ai pas pu. Pas de billet. Tout ce que j’ai pu faire, c’est le regarder disparaître dans ce train.",
            ["DialogueId"] = 51007142,
            ["GUID"] = "7FB0E73C",
            ["NextDialogue"] = 51007143,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Jiexi",
            ["TalkActionId"] = {
                [1] = "700147:Explain02_End",
                },
            },
        [51007143] = {
            ["Content"] = "（她又拆开了一颗星星，这张车票的颜色有些泛黄。车票背面写着“我想离开这里，追上你的脚步”。）",
            ["ContentFR"] = "Elle ouvre une autre étoile. Le billet jauni à l’intérieur porte une phrase : « Je veux quitter cet endroit et marcher dans tes pas. »",
            ["DialogueId"] = 51007143,
            ["GUID"] = "7FB0E766",
            ["NextDialogue"] = 51007144,
            },
        [51007144] = {
            ["Content"] = "哈哈……找到了。这一张，是他登上的那趟列车。那辆列车将穿越海伯利亚大平原，去向遥远的南方。",
            ["ContentFR"] = "Ah... Voilà. C’est celui-là. C’est le train qu’il a pris. Celui qui traversait les grandes plaines d’Hyperborea pour filer vers le sud.",
            ["DialogueId"] = 51007144,
            ["GUID"] = "7FB0E790",
            ["NextDialogue"] = 51007145,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Jiexi",
            ["TalkActionId"] = {
                [1] = "700147:Talk02_Start",
                },
            },
        [51007145] = {
            ["Content"] = "当时的售票员看我可怜，在发车后把没卖出去的废票给了我一张，安慰我说去那边的列车还有很多。",
            ["ContentFR"] = "La guichetière d’alors m’a prise en pitié. Quand le train est parti, elle m’a refilé un vieux billet invendu, juste pour me consoler. Elle m’a aussi dit qu’il y aurait d’autres trains allant dans cette direction.",
            ["DialogueId"] = 51007145,
            ["GUID"] = "7FB0E7BA",
            ["NextDialogue"] = 51007146,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Jiexi",
            ["TalkActionId"] = {
                [1] = "700147:Talk02_End",
                },
            },
        [51007146] = {
            ["Content"] = "可是我始终买不起票，只能眼巴巴地在旁边看着。久而久之我也把卖票的流程看熟了，后来就接替她当了售票员。",
            ["ContentFR"] = "Mais je n’ai jamais eu de quoi en acheter un vrai. Alors je me suis contentée de regarder les trains passer. Les allers, les retours. J’ai appris toutes les procédures par cœur, et le jour où cette guichetière a pris sa retraite... c’est moi qui ai pris sa place.",
            ["DialogueId"] = 51007146,
            ["GUID"] = "7FB0E7E4",
            ["NextDialogue"] = 51006931,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Jiexi",
            ["TalkActionId"] = {
                [1] = "700147:Disagree",
                },
            },
        [51007147] = {
            ["Content"] = "（她叹了一口气，停下了动作，把所有拆开和没拆开的纸星星拢在一起，推到了桌角。）",
            ["ContentFR"] = "Elle soupire, rassemble toutes les étoiles, dépliées et intactes, et les pousse dans un coin du comptoir.",
            ["DialogueId"] = 51007147,
            ["GUID"] = "7FB0E80E",
            ["NextDialogue"] = 51007148,
            },
        [51007148] = {
            ["Content"] = "现在你明白了吧？这些纸星星就是不折不扣的垃圾。谢谢你特地拿来还给我，下次我会把它们撕成碎片再扔。",
            ["ContentFR"] = "Tu comprends, maintenant ? Ces étoiles ne sont rien d’autre que des ordures. Merci de me les avoir rapportées. La prochaine fois, je les déchirerai avant de les jeter.",
            ["DialogueId"] = 51007148,
            ["GUID"] = "7FB0E838",
            ["NextDialogue"] = 51007149,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Jiexi",
            ["TalkActionId"] = {
                [1] = "700147:Explain02_Start",
                },
            },
        [51007149] = {
            ["Content"] = "怎么觉得，有点可惜……",
            ["ContentFR"] = "Quel dommage...",
            ["DialogueId"] = 51007149,
            ["GUID"] = "7FB0E862",
            ["NextDialogue"] = 51007150,
            ["SpeakNpcId"] = 700148,
            ["TalkActionId"] = {
                [1] = "700147:Explain02_End",
                [2] = "700148:Think_Start",
                },
            },
        [51007150] = {
            ["Content"] = "我用不着你可怜，织星客。",
            ["ContentFR"] = "Garde ta pitié, Tisse-Étoiles. Je n’en ai pas besoin.",
            ["DialogueId"] = 51007150,
            ["GUID"] = "7FB0E88C",
            ["NextOptions"] = {
                [1] = 51007151,
                },
            ["SpeakNpcName"] = "UI_CMNpc_Name_Jiexi",
            ["TalkActionId"] = {
                [1] = "700148:Think_End",
                },
            },
        [51007151] = {
            ["Content"] = "你就不能好好说话吗？",
            ["ContentFR"] = "<I>Tu pourrais pas, pour une fois, parler normalement ?</>",
            ["DialogueId"] = 51007151,
            ["GUID"] = "7FB0E8B6",
            ["NextDialogue"] = 51007152,
            },
        [51007152] = {
            ["Content"] = "“好好说话”？你的意思是要我也像那个织星客、像那个售票员一样，说些漂亮的空话，什么“远方”，什么“未来”，然后让人眼巴巴地盼望着？",
            ["ContentFR"] = "« Parler normalement » ? Tu veux dire comme ce Tisse-Étoiles ou cette guichetière, à radoter de belles paroles vides, du genre l’avenir, l’ailleurs, juste pour donner de faux espoirs aux gens ?",
            ["DialogueId"] = 51007152,
            ["GUID"] = "7FB0E8E0",
            ["NextDialogue"] = 51007153,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Jiexi",
            ["TalkActionId"] = {
                [1] = "700147:Explain01_Start",
                },
            },
        [51007153] = {
            ["Content"] = "既然你是卡戎，你应该比我、比这个华胥人更清楚冰湖城到底是个什么地方！",
            ["ContentFR"] = "Puisque tu es {性别:un|une} Charon, tu devrais savoir mieux que moi, mieux que ce gars de Huaxu, ce qu’est vraiment Givrelac !",
            ["DialogueId"] = 51007153,
            ["GUID"] = "7FB0E90A",
            ["NextDialogue"] = 51007154,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Jiexi",
            ["TalkActionId"] = {
                [1] = "700147:Explain01_End",
                },
            },
        [51007154] = {
            ["Content"] = "去城里走上一圈，人人都在悲叹、抱怨、咒骂！在这种地方，好好说话有意义吗？",
            ["ContentFR"] = "Fais donc un tour là-bas, tu n’entendras que des plaintes, des lamentations et des injures. Dans un endroit pareil, ça sert à quoi, de parler gentiment ?",
            ["DialogueId"] = 51007154,
            ["GUID"] = "7FB0E934",
            ["NextDialogue"] = 51007155,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Jiexi",
            },
        [51007155] = {
            ["Content"] = "等一下！",
            ["ContentFR"] = "Attendez !",
            ["DialogueId"] = 51007155,
            ["GUID"] = "7FB0E95E",
            ["IsBlack"] = 1,
            ["LookAt"] = {
                [1] = "700147:n(700148)",
                },
            ["NextDialogue"] = 51007156,
            ["SpeakNpcId"] = 700148,
            },
        [51007156] = {
            ["Content"] = "（异国人忽然想到了什么，转过身开始翻背包。你和杰西卡不明就里地听着一连串叮铃哐啷的声响，不知他到底在干什么。）",
            ["ContentFR"] = "Le marchand semble avoir une idée soudaine. Il se retourne et fouille frénétiquement dans son sac. Jessica et toi entendez des cliquetis et des bruits métalliques sans trop comprendre ce qu’il fabrique.",
            ["DialogueId"] = 51007156,
            ["GUID"] = "7FB0E988",
            ["NextDialogue"] = 51007157,
            },
        [51007157] = {
            ["Content"] = "（过了一会儿，声音停下来，他捧着一个外观颇有异域风情的小盒子递给杰西卡。）",
            ["ContentFR"] = "Au bout d’un moment, le vacarme s’arrête. Il tend à Jessica une petite boîte d’allure exotique.",
            ["DialogueId"] = 51007157,
            ["GUID"] = "7FB0E9B2",
            ["NextDialogue"] = 51007158,
            ["TalkActionId"] = {
                [1] = "700148:Give",
                },
            },
        [51007158] = {
            ["Content"] = "这个，华胥产出盒子！可以锁起，不怕再丢星星，被人看到。",
            ["ContentFR"] = "Ça, boîte de Huaxu ! Se ferme à clé. Plus jamais perdre étoiles, plus personne voir !",
            ["DialogueId"] = 51007158,
            ["GUID"] = "7FB0E9DC",
            ["NextDialogue"] = 51007159,
            ["SpeakNpcId"] = 700148,
            },
        [51007159] = {
            ["Content"] = "你什么意思啊……？我哪来的钱买这么精致的盒子……",
            ["ContentFR"] = "Qu’est-ce que... tu veux dire quoi, là ? Je n’ai pas les moyens d’acheter une boîte aussi jolie...",
            ["DialogueId"] = 51007159,
            ["GUID"] = "7FB0EA06",
            ["NextDialogue"] = 51007160,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Jiexi",
            },
        [51007160] = {
            ["Content"] = "不要钱，送给你！切勿放弃心愿！",
            ["ContentFR"] = "Pas besoin argent ! Cadeau. Pas abandonner vœux !",
            ["DialogueId"] = 51007160,
            ["GUID"] = "7FB0EA30",
            ["NextDialogue"] = 51007161,
            ["SpeakNpcId"] = 700148,
            ["TalkActionId"] = {
                [1] = "700148:Disagree",
                },
            },
        [51007161] = {
            ["Content"] = "（杰西卡愣了一下，低头看向那个盒子，又转过头去，沉默不语。）",
            ["ContentFR"] = "Jessica reste figée un instant, baisse les yeux vers la boîte, puis détourne la tête, silencieuse.",
            ["DialogueId"] = 51007161,
            ["GUID"] = "7FB0EA5A",
            ["NextOptions"] = {
                [1] = 51007162,
                [2] = 51007168,
                },
            },
        [51007162] = {
            ["Content"] = "（劝杰西卡收下盒子。）",
            ["ContentFR"] = "<I>Encourager Jessica à accepter la boîte</>",
            ["DialogueId"] = 51007162,
            ["GUID"] = "7FB0EA84",
            ["NextDialogue"] = 51007163,
            },
        [51007163] = {
            ["Content"] = "……你看。温柔也不是全无意义的——至少它能变成一个精致的小盒子，守护一个藏在星星的梦想。",
            ["ContentFR"] = "Tu vois ? La gentillesse n’est pas inutile. Parfois, elle se transforme en une jolie petite boîte... prête à protéger les rêves cachés dans ces étoiles.",
            ["DialogueId"] = 51007163,
            ["GUID"] = "7FB0EAAE",
            ["LookAt"] = {
                [1] = "700147:n(0)",
                },
            ["NextDialogue"] = 51007164,
            ["SpeakNpcId"] = 100001,
            },
        [51007164] = {
            ["Content"] = "（你将桌上的纸星星都捧起来，放进了那个华胥风格的盒子，然后将它重新递给杰西卡。）",
            ["ContentFR"] = "Tu ramasses toutes les étoiles de papier sur la table, les places dans la boîte, et la tends à nouveau vers Jessica.",
            ["DialogueId"] = 51007164,
            ["GUID"] = "7FB0EAD8",
            ["NextDialogue"] = 51007165,
            },
        [51007165] = {
            ["Content"] = "有空的时候，再把这些星星叠起来吧。",
            ["ContentFR"] = "Quand tu auras un peu de temps... tu pourras en plier d’autres.",
            ["DialogueId"] = 51007165,
            ["GUID"] = "7FB0EB02",
            ["NextDialogue"] = 51007166,
            ["SpeakNpcId"] = 100001,
            },
        [51007166] = {
            ["Content"] = "你……",
            ["ContentFR"] = "Tu...",
            ["DialogueId"] = 51007166,
            ["GUID"] = "7FB0EB2C",
            ["NextDialogue"] = 51007167,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Jiexi",
            },
        [51007167] = {
            ["Content"] = "好……好吧。受不了你的啰嗦了，我收下就是了。谢……谢谢。",
            ["ContentFR"] = "Bon... d-d’accord. Je la prends mais seulement parce que j’en ai assez de ton baratin. M-Merci.",
            ["DialogueId"] = 51007167,
            ["GUID"] = "7FB0EB56",
            ["NextDialogue"] = 51007172,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Jiexi",
            },
        [51007168] = {
            ["Content"] = "（就这样吧，尊重他人命运。）",
            ["ContentFR"] = "<I>Respecter son choix</>",
            ["DialogueId"] = 51007168,
            ["GUID"] = "7FB0EB80",
            ["NextDialogue"] = 51007169,
            },
        [51007169] = {
            ["Content"] = "把它拿走吧。你以为我为什么要扔掉那些星星？这么多年下来，该想的我早就想清楚了，现实也早就认清了。",
            ["ContentFR"] = "Reprends-la. Tu crois que je les ai jetées pourquoi, ces étoiles ? Après toutes ces années, j’ai déjà fait le tri dans mes pensées. J’ai compris ce qu’était la réalité.",
            ["DialogueId"] = 51007169,
            ["GUID"] = "7FB0EBAA",
            ["NextDialogue"] = 51007170,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Jiexi",
            },
        [51007170] = {
            ["Content"] = "唉，憾事，憾事！",
            ["ContentFR"] = "Hélas... quel dommage, quel dommage !",
            ["DialogueId"] = 51007170,
            ["GUID"] = "7FB0EBD4",
            ["NextDialogue"] = 51007171,
            ["SpeakNpcId"] = 700148,
            ["TalkActionId"] = {
                [1] = "700148:Disagree",
                },
            },
        [51007171] = {
            ["Content"] = "…………",
            ["ContentFR"] = "...",
            ["DialogueId"] = 51007171,
            ["GUID"] = "7FB0EBFE",
            ["NextDialogue"] = 51007172,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Jiexi",
            },
        [51007172] = {
            ["Content"] = "……对了，就算是开往同一个目的地，不同车次的价格也不一样，有几趟会便宜些。虽然也省不了多少钱，但……",
            ["ContentFR"] = "... Au fait, même pour la même destination, les prix des billets varient. Certains sont moins chers, pas de beaucoup, mais quand même...",
            ["DialogueId"] = 51007172,
            ["GUID"] = "7FB0EC28",
            ["NextDialogue"] = 51007173,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Jiexi",
            },
        [51007173] = {
            ["Content"] = "如果，有一天你们真能从自己的破口袋里掏出点钱来买票的话……我可以帮你们提前看一看，预留最便宜的那趟车的票。",
            ["ContentFR"] = "Si un jour vous réussissez à rassembler assez de pièces pour acheter un billet... je peux vous aider à réserver la place la moins chère.",
            ["DialogueId"] = 51007173,
            ["GUID"] = "7FB0EC52",
            ["NextDialogue"] = 51007174,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Jiexi",
            },
        [51007174] = {
            ["Content"] = "作为交换，星星的事，别说出去。",
            ["ContentFR"] = "En échange... ne parlez à personne de ces étoiles.",
            ["DialogueId"] = 51007174,
            ["GUID"] = "7FB0EC7C",
            ["NextDialogue"] = 51007175,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Jiexi",
            },
        [51007175] = {
            ["Content"] = "感谢感谢，你原来是善良售票员！",
            ["ContentFR"] = "Merci, merci ! Alors toi, gentille vendeuse de billets !",
            ["DialogueId"] = 51007175,
            ["GUID"] = "7FB0ECA6",
            ["NextDialogue"] = 51007176,
            ["SpeakNpcId"] = 700148,
            ["TalkActionId"] = {
                [1] = "700148:Agree",
                },
            },
        [51007176] = {
            ["Content"] = "你说的，十几年前织星客，我遇到帮你捎话。",
            ["ContentFR"] = "Ton Tisse-Étoiles. Si moi le croiser, moi lui transmettre message !",
            ["DialogueId"] = 51007176,
            ["GUID"] = "7FB0ECD0",
            ["NextDialogue"] = 51007177,
            ["SpeakNpcId"] = 700148,
            ["TalkActionId"] = {
                [1] = "700148:Talk02_Start",
                },
            },
        [51007177] = {
            ["Content"] = "谢谢你的好意，不过……不用了。如果有一天真的能离开这里，我大概也不会去找他了。我想去个不会下雪的地方，看看外边的人是不是都和冰湖城不一样。",
            ["ContentFR"] = "Merci de ta proposition, mais... ce n’est pas nécessaire. Si un jour je pars d’ici, je n’irai sûrement pas le chercher. Je voudrais plutôt un endroit sans neige... voir si les gens, là-bas, sont différents de ceux de Givrelac.",
            ["DialogueId"] = 51007177,
            ["GUID"] = "7FB0ECFA",
            ["NextDialogue"] = 51007178,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Jiexi",
            ["TalkActionId"] = {
                [1] = "700148:Talk02_End",
                [2] = "700147:Explain02_Start",
                },
            },
        [51007178] = {
            ["Content"] = "也很好，用功攒钱，一定能够离开。",
            ["ContentFR"] = "Bien aussi ! Toi travailler dur, économiser... sûrement partir un jour !",
            ["DialogueId"] = 51007178,
            ["GUID"] = "7FB0ED24",
            ["NextDialogue"] = 51007179,
            ["SpeakNpcId"] = 700148,
            ["TalkActionId"] = {
                [1] = "700147:Explain02_End",
                [2] = "700148:Agree",
                },
            },
        [51007179] = {
            ["Content"] = "……嗯。",
            ["ContentFR"] = "... Oui.",
            ["DialogueId"] = 51007179,
            ["GUID"] = "7FB0ED4E",
            ["NextDialogue"] = 51007186,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Jiexi",
            },
        [51007180] = {
            ["Content"] = "你也有自己的星星。保存好你的星星，切记，不要丢进垃圾桶。",
            ["ContentFR"] = "Toi aussi avoir tes étoiles. Garde-les précieusement. Jamais à la poubelle !",
            ["DialogueId"] = 51007180,
            ["GUID"] = "7FB0ED78",
            ["NextDialogue"] = 51007181,
            ["SpeakNpcId"] = 700148,
            ["TurnTo"] = {
                [1] = "700148:n(0)",
                },
            },
        [51007181] = {
            ["Content"] = "我名李安德，是织星客。前日子，生意有点赔，现在城门附近用心摆摊，请光顾！",
            ["ContentFR"] = "Moi, Li An’de ! Tisse-Étoiles ! Ces derniers temps... commerce pas bon. Maintenant moi vendre près de porte de la ville, travailler dur ! Viens voir !",
            ["DialogueId"] = 51007181,
            ["GUID"] = "7FB0EDA2",
            ["SpeakNpcName"] = "UI_CMNpc_Name_Liande",
            ["TalkActionId"] = {
                [1] = "700148:Explain02_Start",
                },
            },
        [51007182] = {
            ["Content"] = "是你啊……要买车票的话和我说一声就好。",
            ["ContentFR"] = "Ah, c’est toi... Si jamais tu veux un billet, viens me voir.",
            ["DialogueId"] = 51007182,
            ["GUID"] = "7FB0EDCC",
            ["SpeakNpcId"] = 700021,
            ["TalkActionId"] = {
                [1] = "700021:Agree",
                },
            },
        [51007186] = {
            ["Content"] = "对了！我也有美丽纸张。我们一起折星星。",
            ["ContentFR"] = "Oh ! Moi aussi avoir beaux papiers ! On plie étoiles ensemble ?",
            ["DialogueId"] = 51007186,
            ["GUID"] = "7FB0ED4F",
            ["NextDialogue"] = 51007187,
            ["SpeakNpcId"] = 700148,
            },
        [51007187] = {
            ["Content"] = "啊？你是想让我帮你吗？可我不会折星星。",
            ["ContentFR"] = "Hein ? Tu veux que je t’aide ? Mais je ne sais même pas comment faire...",
            ["DialogueId"] = 51007187,
            ["GUID"] = "7FB0ED50",
            ["NextDialogue"] = 51007188,
            ["SpeakNpcId"] = 100001,
            },
        [51007188] = {
            ["Content"] = "我也不会折，很丑。但是互帮互助，就会好看！",
            ["ContentFR"] = "Moi non plus ! Moi plier... très moche. Mais si on s’entraide... belles étoiles peut-être !",
            ["DialogueId"] = 51007188,
            ["GUID"] = "7FB0ED51",
            ["NextDialogue"] = 51007189,
            ["SpeakNpcId"] = 700148,
            },
        [51007189] = {
            ["Content"] = "那我试试吧。",
            ["ContentFR"] = "... D’accord, je vais essayer.",
            ["DialogueId"] = 51007189,
            ["GUID"] = "7FB0ED52",
            ["SpeakNpcId"] = 100001,
            },
        [51007190] = {
            ["Content"] = "收下吧，善良有龙氏同胞。这里还有一些谢礼。",
            ["ContentFR"] = "Tiens ! Cadeau pour toi, {性别:ami|amie} Charon au grand cœur. Pas beaucoup d’argent... mais petite récompense, accepte !",
            ["DialogueId"] = 51007190,
            ["GUID"] = "7FB0ED53",
            ["NextDialogue"] = 51007191,
            ["SpeakNpcId"] = 700148,
            },
        [51007191] = {
            ["Content"] = "送我的？",
            ["ContentFR"] = "Pour moi ?",
            ["DialogueId"] = 51007191,
            ["GUID"] = "7FB0ED54",
            ["NextDialogue"] = 51007192,
            ["SpeakNpcId"] = 100001,
            },
        [51007192] = {
            ["Content"] = "嗯！她的星星，是愿望。织星客的星星，是远方，是故乡。",
            ["ContentFR"] = "Oui ! Ses étoiles, à elle... sont des vœux. Celles du Tisse-Étoiles... des voyages, des souvenirs.",
            ["DialogueId"] = 51007192,
            ["GUID"] = "7FB0ED55",
            ["NextDialogue"] = 51007180,
            ["SpeakNpcId"] = 700148,
            },
        [51007301] = {
            ["Content"] = "忠于欲望，忠于欲望，忠于欲望，哎，到底怎么才算忠于欲望啊……",
            ["ContentFR"] = "Être fidèle à ses désirs... fidèle à ses désirs... fidèle à ses désirs... Pff... Mais qu’est-ce que ça signifie vraiment, être fidèle à ses désirs... ?",
            ["DialogueId"] = 51007301,
            ["GUID"] = "7FB10152",
            ["NextDialogue"] = 51007302,
            ["SpeakNpcId"] = 700077,
            },
        [51007302] = {
            ["Content"] = "我是考古学者！欲望这种东西不在我的研究领域啊！！！",
            ["ContentFR"] = "Je suis archéologue ! Les désirs, ce n’est pas exactement mon domaine de recherche !",
            ["DialogueId"] = 51007302,
            ["GUID"] = "7FB1017C",
            ["NextOptions"] = {
                [1] = 510073021,
                [2] = 510073022,
                [3] = 510073023,
                },
            ["SpeakNpcId"] = 700077,
            ["bForbidSkipOptions"] = true,
            },
        [51007303] = {
            ["Content"] = "你的见解很有意思，能帮帮我吗？",
            ["ContentFR"] = "Votre point de vue est intéressant. Pourriez-vous m’aider ?",
            ["DialogueId"] = 51007303,
            ["GUID"] = "7FB101A6",
            ["NextOptions"] = {
                [1] = 510073031,
                [2] = 510073032,
                },
            ["SpeakNpcId"] = 700077,
            },
        [51007304] = {
            ["Content"] = "我是阿特拉西亚大陆考古协会，帝国分会的研究员，最近交上去的学术报告总是被“感受不到欲望”为由打回来。",
            ["ContentFR"] = "Je suis chercheuse à la Société archéologique d’Atlasia, section impériale. Dernièrement, tous mes rapports sont rejetés avec la même remarque : « manque de désir ».",
            ["DialogueId"] = 51007304,
            ["GUID"] = "7FB101D0",
            ["NextDialogue"] = 51007305,
            ["SpeakNpcId"] = 700077,
            },
        [51007305] = {
            ["Content"] = "哎……真是搞不懂投资人的要求……",
            ["ContentFR"] = "Franchement... je ne comprends rien aux exigences de ces investisseurs...",
            ["DialogueId"] = 51007305,
            ["GUID"] = "7FB101FA",
            ["NextDialogue"] = 51007306,
            ["SpeakNpcId"] = 700077,
            },
        [51007306] = {
            ["Content"] = "什么投资人居然还懂学术？",
            ["ContentFR"] = "Depuis quand un investisseur comprend-il l’archéologie ?",
            ["DialogueId"] = 51007306,
            ["GUID"] = "7FB10224",
            ["NextDialogue"] = 51007307,
            ["SpeakNpcId"] = 100001,
            },
        [51007307] = {
            ["Content"] = "虬先生可不是一般的投资人，卢卡的百年沉船、艾利西安的千年遗迹、海伯利亚的战争遗址等等考古学重大发现都是他亲自找到的。",
            ["ContentFR"] = "Maître Qiu n’est pas un investisseur ordinaire. Les épaves centenaires de Luca, les ruines millénaires d’Élysium, les champs de bataille oubliés d’Hyperborea... ce sont toutes ses découvertes personnelles.",
            ["DialogueId"] = 51007307,
            ["GUID"] = "7FB1024E",
            ["NextDialogue"] = 51007308,
            ["SpeakNpcId"] = 700077,
            },
        [51007308] = {
            ["Content"] = "（雪莉眼含崇拜，滔滔不绝地向你讲述虬先生的过往。）",
            ["ContentFR"] = "Les yeux de Shirley brillent d’admiration tandis qu’elle vous raconte sans s’arrêter les exploits de Maître Qiu.",
            ["DialogueId"] = 51007308,
            ["GUID"] = "7FB10278",
            ["NextDialogue"] = 51007309,
            },
        [51007309] = {
            ["Content"] = "虬先生是大陆考古协会的总投资人，更是一名伟大的考古学家与大收藏家。甚至还有传言说他是行走在华胥“阴影”中的君主……",
            ["ContentFR"] = "Il est le principal investisseur de la Société, mais aussi un immense archéologue et collectionneur. Certains murmures prétendent même qu’il serait un souverain marchant dans l’ombre de Huaxu...",
            ["DialogueId"] = 51007309,
            ["GUID"] = "7FB102A2",
            ["NextDialogue"] = 51007310,
            ["SpeakNpcId"] = 700077,
            },
        [51007310] = {
            ["Content"] = "要是没有他的幕后资助，考古协会根本发展不成遍布大陆各个角落的庞大组织。",
            ["ContentFR"] = "Sans son soutien, la Société n’aurait jamais pu devenir une organisation couvrant tout le continent.",
            ["DialogueId"] = 51007310,
            ["GUID"] = "7FB102CC",
            ["NextDialogue"] = 51007311,
            ["SpeakNpcId"] = 700077,
            },
        [51007311] = {
            ["Content"] = "唉……他老人家之前都不怎么管的，怎么突然又抓起我们考古协会不放了，华胥那边的退休生活这么清闲吗？",
            ["ContentFR"] = "<I>Pff...</> Il ne se mêlait jamais de nos affaires avant. Pourquoi s’acharne-t-il soudain ? Sa retraite à Huaxu est-elle si ennuyeuse ?",
            ["DialogueId"] = 51007311,
            ["GUID"] = "7FB102F6",
            ["NextDialogue"] = 51007312,
            ["SpeakNpcId"] = 700077,
            },
        [51007312] = {
            ["Content"] = "能看看你的报告吗？",
            ["ContentFR"] = "Puis-je consulter vos rapports ?",
            ["DialogueId"] = 51007312,
            ["GUID"] = "7FB10320",
            ["NextDialogue"] = 51007313,
            ["SpeakNpcId"] = 100001,
            },
        [51007313] = {
            ["Content"] = "好啊，《冰湖城酒馆客流变化的简要分析》、《水仙平原饮品技术工艺演变》，《自称魔王的皎皎的观察记录》，要看哪个？",
            ["ContentFR"] = "Bien sûr ! <I>Analyse succincte de la fréquentation des tavernes de Givrelac</>, <I>Évolution des techniques de brassage aux Asphodèles</>, ou encore <I>Observations sur la Luno se proclamant Roi Démon</>. Lequel vous tente ?",
            ["DialogueId"] = 51007313,
            ["GUID"] = "7FB1034A",
            ["NextOptions"] = {
                [1] = 510073131,
                [2] = 510073132,
                },
            ["SpeakNpcId"] = 700077,
            },
        [51007314] = {
            ["Content"] = "这也没办法呀，冰湖城冰天雪地的啥都挖不出来，所以写不了什么正常的考古报告嘛！",
            ["ContentFR"] = "Que voulez-vous... À Givrelac, tout est gelé. On ne peut rien fouiller, alors impossible d’écrire un vrai rapport archéologique !",
            ["DialogueId"] = 51007314,
            ["GUID"] = "7FB10374",
            ["NextOptions"] = {
                [1] = 510073141,
                },
            ["SpeakNpcId"] = 700077,
            },
        [51007315] = {
            ["Content"] = "也许你缺一个合适的向导。",
            ["ContentFR"] = "<I>Il vous manque peut-être un guide compétent.</>",
            ["DialogueId"] = 51007315,
            ["FailDialogue"] = 510073151,
            ["GUID"] = "7FB1039E",
            ["ImprCheckId"] = 1061,
            ["NextDialogue"] = 510073152,
            },
        [51007316] = {
            ["Content"] = "拜托你不要放弃我！",
            ["ContentFR"] = "Je vous en prie, ne m’abandonnez pas !",
            ["DialogueId"] = 51007316,
            ["GUID"] = "7FB103C8",
            ["SpeakNpcId"] = 700077,
            },
        [51007317] = {
            ["Content"] = "好复杂的下水道，要不是你带我进来肯定会迷路。",
            ["ContentFR"] = "Ces égouts sont bien trop complexes... Sans vous pour me guider, je me serais perdue à coup sûr.",
            ["DialogueId"] = 51007317,
            ["GUID"] = "7FB103F2",
            ["NextDialogue"] = 51007318,
            ["SpeakNpcId"] = 700172,
            },
        [51007318] = {
            ["Content"] = "我偶尔也会迷路。",
            ["ContentFR"] = "Il m’arrive aussi de perdre mon chemin.",
            ["DialogueId"] = 51007318,
            ["GUID"] = "7FB1041C",
            ["NextDialogue"] = 51007319,
            ["SpeakNpcId"] = 100001,
            },
        [51007319] = {
            ["Content"] = "嗯……就连经常来下水道探险的狩月人也会迷路，这个下水道的规模也太过巨大了。",
            ["ContentFR"] = "Hmm... Même les Chasseurs de Phoxène qui explorent souvent les égouts s’y égarent. Leur ampleur est vraiment démesurée.",
            ["DialogueId"] = 51007319,
            ["GUID"] = "7FB10446",
            ["NextDialogue"] = 51007320,
            ["SpeakNpcId"] = 700172,
            },
        [51007320] = {
            ["Content"] = "对了，在海伯利亚的官方正史里，他们国家最早就是在冰湖城建立的。所以才会有这么一个和地面建筑差不多大的下水道吧。",
            ["ContentFR"] = "D’ailleurs, selon les chroniques officielles d’Hyperborea, la nation aurait vu le jour ici même, à Givrelac. Cela expliquerait l’existence d’un réseau souterrain presque aussi vaste que la ville en surface.",
            ["DialogueId"] = 51007320,
            ["GUID"] = "7FB10447",
            ["NextDialogue"] = 51007321,
            ["SpeakNpcId"] = 700172,
            },
        [51007321] = {
            ["Content"] = "感觉这里的墙壁要更古老一些。",
            ["ContentFR"] = "Les murs semblent plus anciens que le reste.",
            ["DialogueId"] = 51007321,
            ["GUID"] = "7FB10470",
            ["NextDialogue"] = 51007322,
            ["SpeakNpcId"] = 100001,
            },
        [51007322] = {
            ["Content"] = "应该是随着当时冰湖城的扩建不断完善的吧，好像冰湖城一开始是就是一个卡戎的定居点……",
            ["ContentFR"] = "Sans doute ont-ils été améliorés au fil de l’expansion de la ville... Il paraît qu’à l’origine, Givrelac n’était qu’un simple établissement de Charons...",
            ["DialogueId"] = 51007322,
            ["GUID"] = "7FB1049A",
            ["NextDialogue"] = 51007323,
            ["SpeakNpcId"] = 700172,
            },
        [51007323] = {
            ["Content"] = "啊，你这倒提醒我了，虽然外面的是冻土终年封冻，地面的建筑不断翻新，但是下水道说不定没有彻底翻新过。",
            ["ContentFR"] = "Ah, vous venez de me faire penser à quelque chose. À l’extérieur, le pergélisol empêche toute excavation et les bâtiments sont sans cesse rénovés... mais les égouts, eux, n’ont peut-être jamais été entièrement reconstruits.",
            ["DialogueId"] = 51007323,
            ["GUID"] = "7FB104C4",
            ["NextDialogue"] = 510073231,
            ["SpeakNpcId"] = 700172,
            },
        [51007325] = {
            ["Content"] = "呜啊啊啊，这里也太高了吧，也不知道和华胥的执律阁比起来哪个高……我恐高症要犯了！",
            ["ContentFR"] = "Aaaah ! C’est beaucoup trop haut ! Je ne sais même pas si c’est plus élevé que le Pavillon de l’Arbitrage à Huaxu... Mon vertige va revenir !",
            ["DialogueId"] = 51007325,
            ["GUID"] = "7FB10542",
            ["NextDialogue"] = 51007326,
            ["SpeakNpcId"] = 700173,
            },
        [51007326] = {
            ["Content"] = "你先别看外面，盯着脚底下看一会儿缓一下吧。",
            ["ContentFR"] = "Ne regardez pas au loin pour l’instant. Fixez le sol sous vos pieds et respirez un peu.",
            ["DialogueId"] = 51007326,
            ["GUID"] = "7FB1056C",
            ["NextDialogue"] = 51007327,
            ["SpeakNpcId"] = 100001,
            },
        [51007327] = {
            ["Content"] = "呼，呼……好多了。",
            ["ContentFR"] = "<I>Haa... haa...</> Ça va mieux, merci.",
            ["DialogueId"] = 51007327,
            ["GUID"] = "7FB10596",
            ["NextDialogue"] = 51007328,
            ["SpeakNpcId"] = 700173,
            },
        [51007328] = {
            ["Content"] = "真是的，当初帝国这帮人到底想什么，要修这么高的城墙。",
            ["ContentFR"] = "Sérieusement, à quoi pensaient les architectes de l’Empire en érigeant des murailles aussi démesurées ?",
            ["DialogueId"] = 51007328,
            ["GUID"] = "7FB105C0",
            ["NextDialogue"] = 51007329,
            ["SpeakNpcId"] = 700173,
            },
        [51007329] = {
            ["Content"] = "？",
            ["ContentFR"] = "... ?",
            ["DialogueId"] = 51007329,
            ["GUID"] = "7FB105EA",
            ["NextDialogue"] = 51007330,
            ["SpeakNpcId"] = 700173,
            },
        [51007330] = {
            ["Content"] = "对哦，为什么呢？我记得按照帝国正史记载的话，冰湖城最初是卡戎人的聚落。",
            ["ContentFR"] = "Mais oui, pourquoi au juste ? D’après les chroniques impériales, Givrelac était à l’origine un simple village de Charons.",
            ["DialogueId"] = 51007330,
            ["GUID"] = "7FB10614",
            ["NextDialogue"] = 51007331,
            ["SpeakNpcId"] = 700173,
            },
        [51007331] = {
            ["Content"] = "初代皇帝迪斯·盖雷亚，也就是迪斯一世在大迁徙后到了这附近，想要和这里的卡戎部落和平相处，但是他的弟弟却被这里的卡戎以宴会的名义诱杀了。",
            ["ContentFR"] = "Le premier empereur, Dis Galea, plus connu sous le nom de Dis Ier, est arrivé dans cette région après la Grande Migration. Il souhaitait coexister pacifiquement avec les tribus de Charon... mais son frère fut attiré ici sous prétexte d’un banquet, puis assassiné.",
            ["DialogueId"] = 51007331,
            ["GUID"] = "7FB1063E",
            ["NextDialogue"] = 51007333,
            ["SpeakNpcId"] = 700173,
            },
        [51007333] = {
            ["Content"] = "所以迪斯一世才会认定卡戎们是一群恶魔，率领着他的骑士团征服了附近的卡戎，带来了所谓的银色和平。",
            ["ContentFR"] = "C’est ainsi que Dis Ier en vint à considérer les Charons comme des démons. Il mena alors son ordre de chevaliers pour les soumettre et imposa ce que l’on appelle la soi-disant Paix d’Argent.",
            ["DialogueId"] = 51007333,
            ["GUID"] = "7FB10692",
            ["NextDialogue"] = 51007334,
            ["SpeakNpcId"] = 700173,
            },
        [51007334] = {
            ["Content"] = "但如果是这样的话，这么高大的城墙，是要防备谁呢？是秽兽吗？还是说当时那些卡戎还在继续反抗？",
            ["ContentFR"] = "Mais dans ce cas... contre qui ces murailles colossales ont-elles été érigées ? Contre les Souillés ? Ou bien les Charons continuaient-ils encore de résister à l’époque ?",
            ["DialogueId"] = 51007334,
            ["GUID"] = "7FB106BC",
            ["NextDialogue"] = 51007335,
            ["SpeakNpcId"] = 700173,
            },
        [51007335] = {
            ["Content"] = "看来你又获得了灵感？",
            ["ContentFR"] = "On dirait que vous avez encore trouvé matière à réflexion.",
            ["DialogueId"] = 51007335,
            ["GUID"] = "7FB106E6",
            ["NextDialogue"] = 51007336,
            ["SpeakNpcId"] = 100001,
            },
        [51007336] = {
            ["Content"] = "灵感说不上啦，但是就是感到有一些奇怪，但是虬先生有教导我们说，不要放过任何感到奇怪的时刻，那里潜藏着真相。",
            ["ContentFR"] = "Ce n’est pas vraiment de l’inspiration... plutôt une étrange sensation. Maître Qiu nous a toujours enseigné de ne jamais ignorer ce qui nous semble étrange : c’est souvent là que la vérité se dissimule.",
            ["DialogueId"] = 51007336,
            ["GUID"] = "7FB10710",
            ["NextDialogue"] = 51007339,
            ["SpeakNpcId"] = 700173,
            },
        [51007339] = {
            ["Content"] = "总之谢谢，谢谢！现在的我感觉能写出有意思的考察报告了！",
            ["ContentFR"] = "Quoi qu’il en soit, merci, vraiment ! J’ai l’impression de pouvoir enfin rédiger un rapport de terrain digne d’intérêt !",
            ["DialogueId"] = 51007339,
            ["GUID"] = "7FB1078E",
            ["NextDialogue"] = 51007340,
            ["SpeakNpcId"] = 700173,
            },
        [51007340] = {
            ["Content"] = "如果没有你，我肯定像个傻瓜一样，认为冰湖城这破冻土没什么考古价值，然后像之前那样糊弄下去。",
            ["ContentFR"] = "Sans vous, j’aurais continué à penser que ce sol gelé n’avait aucune valeur archéologique, et j’aurais bâclé mes travaux comme avant.",
            ["DialogueId"] = 51007340,
            ["GUID"] = "7FB107B8",
            ["NextDialogue"] = 51007341,
            ["SpeakNpcId"] = 700173,
            },
        [51007341] = {
            ["Content"] = "是我太浅薄了！难道说，您就是潜藏在冰湖城的考古大师！",
            ["ContentFR"] = "Quelle superficialité de ma part ! Ne seriez-vous pas... le grand maître archéologue caché de Givrelac ?",
            ["DialogueId"] = 51007341,
            ["GUID"] = "7FB107E2",
            ["NextOptions"] = {
                [1] = 510073411,
                [2] = 510073412,
                [3] = 510073413,
                },
            ["SpeakNpcId"] = 700173,
            ["bForbidSkipOptions"] = true,
            },
        }
  end },
  { MinKey = 51007342, MaxKey = 51007694, Loader = function()
      return {
        [51007342] = {
            ["Content"] = "我想想……什么报酬才配的上大师您呢……",
            ["ContentFR"] = "Laissez-moi réfléchir... Quelle offrande serait digne d’un maître tel que vous...",
            ["DialogueId"] = 51007342,
            ["GUID"] = "7FB1080C",
            ["NextDialogue"] = 51007343,
            ["SpeakNpcId"] = 700173,
            },
        [51007343] = {
            ["Content"] = "有了，大师您在城门口等我一会儿！",
            ["ContentFR"] = "J’ai trouvé ! Veuillez m’attendre un instant à la porte de la cité !",
            ["DialogueId"] = 51007343,
            ["GUID"] = "7FB10836",
            ["SpeakNpcId"] = 700173,
            },
        [51007344] = {
            ["Content"] = "不愧是大师，太有高人风范了！",
            ["ContentFR"] = "Comme on pouvait s’y attendre d’un maître... Vous avez vraiment l’allure d’un sage hors du commun !",
            ["DialogueId"] = 51007344,
            ["GUID"] = "7FB1080D",
            ["NextDialogue"] = 51007342,
            ["SpeakNpcId"] = 700173,
            },
        [51007345] = {
            ["Content"] = "（没过多久，雪莉就拎着两个大袋子跑到了你的面前。）",
            ["ContentFR"] = "Peu de temps après, Shirley accourt vers vous, chargée de deux énormes sacs.",
            ["DialogueId"] = 51007345,
            ["GUID"] = "7FB1088A",
            ["NextDialogue"] = 51007346,
            },
        [51007346] = {
            ["Content"] = "大师！这是考古协会最新收到的帝国皇家钦定史书《海伯利亚史》第三十二编，小小敬意，希望大师不要嫌弃！",
            ["ContentFR"] = "Maître ! Voici les derniers ouvrages approuvés par l’Empire : Les Chroniques officielles d’Hyperborea, trente-deuxième volume, tout juste reçus par la Société archéologique. Une modeste marque de reconnaissance — j’espère que vous ne les trouverez pas indignes !",
            ["DialogueId"] = 51007346,
            ["GUID"] = "7FB108B4",
            ["NextDialogue"] = 51007347,
            ["SpeakNpcId"] = 700174,
            },
        [51007347] = {
            ["Content"] = "（虽说是不要嫌弃，但雪莉丝毫没有给你拒绝的机会，硬是把两大袋子书塞到了你的手中，然后一边道谢一边蹦跳着跑远了。）",
            ["ContentFR"] = "Malgré ses paroles, elle ne vous laisse aucune occasion de refuser. Elle vous fourre de force les deux sacs de livres dans les bras, vous remercie à plusieurs reprises, puis s’éloigne en sautillant.",
            ["DialogueId"] = 51007347,
            ["GUID"] = "7FB108DE",
            },
        [51007382] = {
            ["Content"] = "13号管道已经在修了，我天，里面老鼠实在是太多了。",
            ["ContentFR"] = "La canalisation n° 13 est en réparation. Bon sang... il y a bien trop de rats là-dedans.",
            ["DialogueId"] = 51007382,
            ["GUID"] = "7FB10E9C",
            ["NextDialogue"] = 51007383,
            ["SpeakNpcId"] = 700069,
            },
        [51007383] = {
            ["Content"] = "（达顿抬起头来，他身上臭气熏天，强烈刺鼻的味道逼得你不得不后退一步，你忍住干呕。）",
            ["ContentFR"] = "Dutton lève les yeux vers toi. Une odeur nauséabonde s’échappe de ses vêtements, si forte que tu recules instinctivement d’un pas, luttant contre la nausée.",
            ["DialogueId"] = 51007383,
            ["GUID"] = "7FB10EC6",
            ["NextDialogue"] = 51007384,
            },
        [51007384] = {
            ["Content"] = "嘶，你躲什么躲，在下水道干活儿身上哪能没点味道。",
            ["ContentFR"] = "Hé ! Pourquoi tu t’éloignes ? Quand on bosse dans les égouts, c’est normal de sentir un peu fort.",
            ["DialogueId"] = 51007384,
            ["GUID"] = "7FB10EF0",
            ["SpeakNpcId"] = 700069,
            ["TalkOptions"] = {
                [1] = 510073841,
                [2] = 510073842,
                [3] = 510073843,
                },
            },
        [51007388] = {
            ["Content"] = "别看我现在这样，在几年前，大多数人还是会尊敬地叫我“达顿医生”。",
            ["ContentFR"] = "Ne te fie pas à ce que tu vois. Il y a encore quelques années, la plupart des gens m’appelaient avec respect « Docteur Dutton ».",
            ["DialogueId"] = 51007388,
            ["GUID"] = "7FB10F98",
            ["NextDialogue"] = 51007389,
            ["SpeakNpcId"] = 700069,
            },
        [51007389] = {
            ["Content"] = "你应该明白作为一个出生在贫民区的卡戎人，这个称呼有怎样特别的意义吧。",
            ["ContentFR"] = "Tu comprends sans doute ce que ce titre représentait pour un Charon né dans les taudis.",
            ["DialogueId"] = 51007389,
            ["GUID"] = "7FB10FC2",
            ["NextDialogue"] = 51007390,
            ["SpeakNpcId"] = 700069,
            },
        [51007390] = {
            ["Content"] = "我在中心医院给数不清的卡戎人看病，甚至有贵族慕名请我问诊。",
            ["ContentFR"] = "J’ai soigné d’innombrables Charons à l’hôpital central... même des nobles faisaient le déplacement pour une consultation.",
            ["DialogueId"] = 51007390,
            ["GUID"] = "7FB10FEC",
            ["NextDialogue"] = 51007391,
            ["SpeakNpcId"] = 700069,
            },
        [51007391] = {
            ["Content"] = "不信的话你可以问问年轻一辈的卡戎小孩，他们父母以前最常说的话就是让这帮孩子向我好好学习。",
            ["ContentFR"] = "Si tu ne me crois pas, demande donc aux jeunes Charons : leurs parents leur répétaient sans cesse de prendre exemple sur moi.",
            ["DialogueId"] = 51007391,
            ["GUID"] = "7FB11016",
            ["NextDialogue"] = 51007392,
            ["SpeakNpcId"] = 700069,
            },
        [51007392] = {
            ["Content"] = "那时候我可有着不轻的洁癖呢，地砖缝但凡有一点灰尘都受不了......",
            ["ContentFR"] = "À l’époque, j’étais un vrai maniaque de la propreté... le moindre grain de poussière entre deux carreaux me rendait fou.",
            ["DialogueId"] = 51007392,
            ["GUID"] = "7FB11040",
            ["RestartTag"] = 51007392,
            ["SpeakNpcId"] = 700069,
            ["TalkOptions"] = {
                [1] = 51007393,
                },
            },
        [51007393] = {
            ["Content"] = "一个救死扶伤的人怎么会来修理下水道？",
            ["ContentFR"] = "Un homme qui sauve des vies ne devrait pas se retrouver à réparer des canalisations.",
            ["DialogueId"] = 51007393,
            ["GUID"] = "7FB1106A",
            ["ImprCheckId"] = 1062,
            ["NextDialogue"] = 510073931,
            },
        [51007395] = {
            ["Content"] = "我之前修理人们，现在修理管道，也没什么不同吧。",
            ["ContentFR"] = "Je réparais des gens, aujourd’hui je répare des tuyaux... au fond, ça revient au même, non ?",
            ["DialogueId"] = 51007395,
            ["GUID"] = "7FB110BE",
            ["NextDialogue"] = 51007396,
            ["SpeakNpcId"] = 700069,
            },
        [51007396] = {
            ["Content"] = "（达顿笑了笑，好像有什么不算轻松的故事就这么翻了篇。）",
            ["ContentFR"] = "Dutton esquisse un sourire tranquille, comme s’il tournait sans rancune la page d’un passé douloureux.",
            ["DialogueId"] = 51007396,
            ["GUID"] = "7FB110E8",
            ["NextDialogue"] = 51007398,
            },
        [51007398] = {
            ["Content"] = "生活本来就是这样充满意外，突发高危急症的行人晕倒在一个医生面前，医生大义凛然，选了抢救。",
            ["ContentFR"] = "Imagine la scène : un passant s’effondre, frappé par une urgence vitale, juste devant un médecin... et ce médecin choisit bravement de le sauver.",
            ["DialogueId"] = 51007398,
            ["GUID"] = "7FB1113C",
            ["NextDialogue"] = 51007399,
            ["SpeakNpcId"] = 700069,
            },
        [51007399] = {
            ["Content"] = "想知道结局是什么？等我修完下水道那几条破管子着，还是说你要跟我一起？",
            ["ContentFR"] = "Tu veux connaître la suite ? Passe-moi plutôt cette clé à molette.",
            ["DialogueId"] = 51007399,
            ["GUID"] = "7FB11166",
            ["SpeakNpcId"] = 700069,
            },
        [51007401] = {
            ["Content"] = "行，跟我来吧，路上那些乱七八糟的东西就交给你了。",
            ["DialogueId"] = 51007401,
            ["GUID"] = "7FB111BA",
            ["SpeakNpcId"] = 700069,
            },
        [51007404] = {
            ["Content"] = "帮我拿下扳手——",
            ["DialogueId"] = 51007404,
            ["GUID"] = "7FB11238",
            ["SpeakNpcId"] = 700193,
            },
        [51007405] = {
            ["Content"] = "总之，他的抢救不但没能请来奇迹，来的还是巨额赔偿金，医院为了名誉只好辞退了一个员工。",
            ["DialogueId"] = 51007405,
            ["GUID"] = "7FB11262",
            ["NextDialogue"] = 51007406,
            ["SpeakNpcId"] = 700194,
            },
        [51007406] = {
            ["Content"] = "谁能想到呢，他竟然除了治病救人什么都不会，所以欢迎他的只有下水管道。",
            ["DialogueId"] = 51007406,
            ["GUID"] = "7FB1128C",
            ["NextDialogue"] = 51007407,
            ["SpeakNpcId"] = 700194,
            },
        [51007407] = {
            ["Content"] = "好在当年怎么都没治好的洁癖，来这儿几个月就治好了。",
            ["DialogueId"] = 51007407,
            ["GUID"] = "7FB112B6",
            ["NextDialogue"] = 51007408,
            ["SpeakNpcId"] = 700194,
            },
        [51007408] = {
            ["Content"] = "再者说，干这活儿也不至于被饿死在街上，不过就是得还债还到进棺材喽。",
            ["DialogueId"] = 51007408,
            ["GUID"] = "7FB112E0",
            ["NextDialogue"] = 51007409,
            ["SpeakNpcId"] = 700194,
            },
        [51007409] = {
            ["Content"] = "如果再给你的人生重来一次的机会，你还会救他吗？",
            ["DialogueId"] = 51007409,
            ["GUID"] = "7FB1130A",
            ["NextDialogue"] = 51007410,
            ["SpeakNpcId"] = 700194,
            },
        [51007410] = {
            ["Content"] = "（达顿转过身用扳手拧紧新换的螺丝，他甩着胳膊干得卖力又熟练，好像没听见你的问题。）",
            ["DialogueId"] = 51007410,
            ["GUID"] = "7FB11334",
            ["NextDialogue"] = 51007411,
            },
        [51007411] = {
            ["Content"] = "（只是在如轰鸣般的沉默中，你和他都已经对答案心知肚明了。）",
            ["DialogueId"] = 51007411,
            ["GUID"] = "7FB1135E",
            },
        [51007415] = {
            ["Content"] = "哎呦……！里边这儿的老鼠也太多了！",
            ["DialogueId"] = 51007415,
            ["GUID"] = "7FB11406",
            ["SpeakNpcId"] = 700192,
            },
        [51007501] = {
            ["Content"] = "嗯……实验对象1号，就决定是你了！",
            ["ContentFR"] = "Hmm... j’ai décidé, toi, tu seras le sujet d’expérience n° 1 !",
            ["DialogueId"] = 51007501,
            ["GUID"] = "7FB12222",
            ["NextDialogue"] = 51007502,
            ["SpeakNpcId"] = 700011,
            },
        [51007502] = {
            ["Content"] = "（眼前的孩子正满脸期待地看着你。）",
            ["ContentFR"] = "Le garçon te regarde avec de grands yeux brillants d’excitation.",
            ["DialogueId"] = 51007502,
            ["GUID"] = "7FB1224C",
            ["NextOptions"] = {
                [1] = 51007503,
                [2] = 51007506,
                [3] = 51007509,
                },
            },
        [51007503] = {
            ["Content"] = "（注意到他穿着考究的制服，似乎还是一名学生。）",
            ["ContentFR"] = "<I>– Il porte un uniforme soigné, on dirait un élève.</>",
            ["DialogueId"] = 51007503,
            ["GUID"] = "7FB12276",
            ["ImprPlusId"] = 1003,
            ["NextDialogue"] = 51007504,
            },
        [51007504] = {
            ["Content"] = "你在说什么实验，是你的作业吗？",
            ["ContentFR"] = "C’est quel genre d’expérience ? C’est pour tes devoirs ?",
            ["DialogueId"] = 51007504,
            ["GUID"] = "7FB122A0",
            ["NextDialogue"] = 51007505,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "0:Explain01_Start",
                },
            },
        [51007505] = {
            ["Content"] = "不是啦，这是我的个人爱好！",
            ["ContentFR"] = "Non ! C’est pour mon plaisir personnel ! Mon propre projet !",
            ["DialogueId"] = 51007505,
            ["GUID"] = "7FB122CA",
            ["NextDialogue"] = 51007512,
            ["SpeakNpcId"] = 700011,
            ["TalkActionId"] = {
                [1] = "700011:Disagree",
                },
            },
        [51007506] = {
            ["Content"] = "（担心他一个人会遭遇危险。）",
            ["ContentFR"] = "<I>– Ce n’est pas très sûr pour un enfant d’être dehors tout seul.</>",
            ["DialogueId"] = 51007506,
            ["GUID"] = "7FB122F4",
            ["ImprPlusId"] = 1004,
            ["NextDialogue"] = 51007507,
            },
        [51007507] = {
            ["Content"] = "小朋友，你一个人待在这里不安全，我送你回家吧。",
            ["ContentFR"] = "Petit, ce n’est pas très sûr de rester ici tout seul. Je te raccompagne ?",
            ["DialogueId"] = 51007507,
            ["GUID"] = "7FB1231E",
            ["NextDialogue"] = 51007508,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "0:Explain01_Start",
                },
            },
        [51007508] = {
            ["Content"] = "谢谢你，你人真好啊！不过我要先做完实验再回家。",
            ["ContentFR"] = "Oh ! Merci ! Tu es vraiment {性别:gentil|gentille} ! Mais je dois finir mon expérience avant de rentrer.",
            ["DialogueId"] = 51007508,
            ["GUID"] = "7FB12348",
            ["NextDialogue"] = 51007512,
            ["SpeakNpcId"] = 700011,
            ["TalkActionId"] = {
                [1] = "700011:Agree",
                },
            },
        [51007509] = {
            ["Content"] = "（询问他说的实验是否能获取报酬。）",
            ["ContentFR"] = "<I>Demander si il y a une récompense à la clé</>",
            ["DialogueId"] = 51007509,
            ["GUID"] = "7FB12372",
            ["ImprPlusId"] = 1001,
            ["NextDialogue"] = 51007510,
            },
        [51007510] = {
            ["Content"] = "诶？啊……有，当然有！我的零花钱都可以给你。",
            ["ContentFR"] = "Hein ? Ah... oui, bien sûr ! Tu peux prendre tout mon argent de poche !",
            ["DialogueId"] = 51007510,
            ["GUID"] = "7FB1239C",
            ["NextDialogue"] = 51007512,
            ["SpeakNpcId"] = 700011,
            ["TalkActionId"] = {
                [1] = "700011:Agree",
                },
            },
        [51007512] = {
            ["Content"] = "是这样的，我正在开展一项针对卡戎之民的实验调查，恭喜你被选中成为我的第一个实验对象！",
            ["ContentFR"] = "Voilà le plan : je mène une étude scientifique sur les Charons ! Et devine quoi ? Tu es mon tout premier sujet d’expérience !",
            ["DialogueId"] = 51007512,
            ["GUID"] = "7FB123F0",
            ["NextDialogue"] = 51007513,
            ["SpeakNpcId"] = 700011,
            ["TalkActionId"] = {
                [1] = "700011:Explain01_Start",
                },
            },
        [51007513] = {
            ["Content"] = "为什么选我？",
            ["ContentFR"] = "Pourquoi moi ?",
            ["DialogueId"] = 51007513,
            ["GUID"] = "7FB1241A",
            ["NextDialogue"] = 51007514,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "0:Think_Start",
                },
            },
        [51007514] = {
            ["Content"] = "是随机抽选的哦，这样才能排除主观因素影响！",
            ["ContentFR"] = "Euh... c’est un tirage au sort ! Ça évite tout biais subjectif !",
            ["DialogueId"] = 51007514,
            ["GUID"] = "7FB12444",
            ["NextDialogue"] = 51007515,
            ["SpeakNpcId"] = 700011,
            },
        [51007515] = {
            ["Content"] = "咳咳，请先告诉我你的名字吧。",
            ["ContentFR"] = "Hum... d’abord, commençons par ton nom.",
            ["DialogueId"] = 51007515,
            ["GUID"] = "7FB1246E",
            ["NextOptions"] = {
                [1] = 51007516,
                [2] = 51007519,
                },
            ["SpeakNpcId"] = 700011,
            ["TalkActionId"] = {
                [1] = "700011:Explain01_End",
                },
            },
        [51007516] = {
            ["Content"] = "我叫诞生于净界岛·重生之焰·冰湖城守护者·光荣的·{nickname}。",
            ["ContentFR"] = "<I>Je suis {nickname}, Flamme de la Renaissance, {性别:Glorieux Gardien de Givrelac|Glorieuse Gardienne de Givrelac}, originaire de l’Île du Purgatoire !</>",
            ["DialogueId"] = 51007516,
            ["GUID"] = "7FB12498",
            ["ImprPlusId"] = 1005,
            ["NextDialogue"] = 51007517,
            ["Scripts"] = "SetTag{Tag{\"XiAoTag\"}, Value{\"Value_1\"}}",
            },
        [51007517] = {
            ["Content"] = "啊，请你说慢点……！那么，诞生于净界岛·重生……诞……蛋……",
            ["ContentFR"] = "Ouah... parle lentement... Flamme de... euh... Givrelac... Purg... quoi ?",
            ["DialogueId"] = 51007517,
            ["GUID"] = "7FB124C2",
            ["NextDialogue"] = 51007518,
            ["SpeakNpcId"] = 700011,
            ["TalkActionId"] = {
                [1] = "700011:Talk01_Start",
                },
            },
        [51007518] = {
            ["Content"] = "呜，好难念！方便起见我就叫你{$XiAoTag(Value_1,Value_2)$|蛋蛋:西比尔}{性别：哥哥|姐姐}好了。",
            ["ContentFR"] = "Trop compliqué ! Je vais t’appeler {$XiAoTag(Value_1,Value_2)$|性别(Purginou|Purginette):Sibylle} !",
            ["DialogueId"] = 51007518,
            ["GUID"] = "7FB124EC",
            ["NextDialogue"] = 51007522,
            ["SpeakNpcId"] = 700011,
            ["TalkActionId"] = {
                [1] = "700011:Agree",
                },
            },
        [51007519] = {
            ["Content"] = "我叫西比尔。",
            ["ContentFR"] = "<I>Je m’appelle Sibylle.</>",
            ["DialogueId"] = 51007519,
            ["GUID"] = "7FB12516",
            ["ImprPlusId"] = 1003,
            ["NextDialogue"] = 51007520,
            ["Scripts"] = "SetTag{Tag{\"XiAoTag\"}, Value{\"Value_2\"}}",
            },
        [51007520] = {
            ["Content"] = "总觉得这个名字有点耳熟，从哪里听过来着……",
            ["ContentFR"] = "Ce nom me rappelle quelque chose... je crois l’avoir entendu quelque part...",
            ["DialogueId"] = 51007520,
            ["GUID"] = "7FB12540",
            ["NextDialogue"] = 51007521,
            ["SpeakNpcId"] = 700011,
            ["TalkActionId"] = {
                [1] = "700011:Think_Start",
                },
            },
        [51007521] = {
            ["Content"] = "算了，不重要。{$XiAoTag(Value_1,Value_2)$|蛋蛋:西比尔}{性别：哥哥|姐姐}，我们开始吧。",
            ["ContentFR"] = "Bon, peu importe ! {$XiAoTag(Value_1,Value_2)$|性别(Purginou|Purginette):Sibylle}, on commence !",
            ["DialogueId"] = 51007521,
            ["GUID"] = "7FB1256A",
            ["NextDialogue"] = 51007522,
            ["SpeakNpcId"] = 700011,
            ["TalkActionId"] = {
                [1] = "700011:Disagree",
                },
            },
        [51007522] = {
            ["Content"] = "放心，实验内容很简单，你只要填完这个调查问卷就行了！",
            ["ContentFR"] = "Pas de souci, le test est simple, il suffit juste de remplir ce questionnaire !",
            ["DialogueId"] = 51007522,
            ["GUID"] = "7FB12594",
            ["NextDialogue"] = 51007523,
            ["SpeakNpcId"] = 700011,
            ["TalkActionId"] = {
                [1] = "700011:Explain01_Start",
                },
            },
        [51007523] = {
            ["Content"] = "（男孩双手捧起一沓厚厚的纸递给了你。）",
            ["ContentFR"] = "Le garçon te tend une pile de papiers, tenant les feuilles à deux mains.",
            ["DialogueId"] = 51007523,
            ["GUID"] = "7FB125BE",
            ["NextDialogue"] = 51007524,
            },
        [51007524] = {
            ["Content"] = "（纸张的边缘并不整齐，似乎是从作业本上撕下来的；纸上是用稚嫩但工整的字体写下的一长串问题，序号甚至标到了三位数。）",
            ["ContentFR"] = "Les bords sont irréguliers, comme arrachés d’un cahier, les pages sont couvertes d’une écriture enfantine mais soignée, numérotées jusqu’à trois chiffres.",
            ["DialogueId"] = 51007524,
            ["GUID"] = "7FB125E8",
            ["NextOptions"] = {
                [1] = 51007525,
                [2] = 51007527,
                [3] = 51007529,
                },
            },
        [51007525] = {
            ["Content"] = "你这问卷未免也太长了吧……",
            ["ContentFR"] = "<I>Ton questionnaire est un peu long...</>",
            ["DialogueId"] = 51007525,
            ["GUID"] = "7FB12612",
            ["NextDialogue"] = 51007526,
            },
        [51007526] = {
            ["Content"] = "也还好吧，只有七百七十七个问题哦！",
            ["ContentFR"] = "Ah bon ? Il n’y a que 777 questions !",
            ["DialogueId"] = 51007526,
            ["GUID"] = "7FB1263C",
            ["NextDialogue"] = 51007531,
            ["SpeakNpcId"] = 700011,
            ["TalkActionId"] = {
                [1] = "700011:Explain01_Start",
                },
            },
        [51007527] = {
            ["Content"] = "这个长度的问卷要加钱。",
            ["ContentFR"] = "<I>Pour un questionnaire aussi long, il faudra sûrement me payer encore plus.</>",
            ["DialogueId"] = 51007527,
            ["GUID"] = "7FB12666",
            ["NextDialogue"] = 51007528,
            },
        [51007528] = {
            ["Content"] = "啊……可是我已经没有多的钱了……可以分期付款吗？",
            ["ContentFR"] = "Mais... je n’ai plus d’argent... je peux te payer en plusieurs fois ?",
            ["DialogueId"] = 51007528,
            ["GUID"] = "7FB12690",
            ["NextDialogue"] = 51007531,
            ["SpeakNpcId"] = 700011,
            ["TalkActionId"] = {
                [1] = "700011:Explain01_Start",
                },
            },
        [51007529] = {
            ["Content"] = "好的，我争取十年内填完。",
            ["ContentFR"] = "<I>D’accord, je répondrai aussi en plusieurs fois... disons sur dix ans.</>",
            ["DialogueId"] = 51007529,
            ["GUID"] = "7FB126BA",
            ["NextDialogue"] = 51007530,
            },
        [51007530] = {
            ["Content"] = "咦？！那也太久了吧！",
            ["ContentFR"] = "Hein ? Dix ans !?",
            ["DialogueId"] = 51007530,
            ["GUID"] = "7FB126E4",
            ["NextDialogue"] = 51007531,
            ["SpeakNpcId"] = 700011,
            ["TalkActionId"] = {
                [1] = "700011:Explain01_Start",
                },
            },
        [51007531] = {
            ["Content"] = "拜托你答应我吧，冰湖城有这么多的卡戎，偏偏是你成为了我随机选中的那个观察目标，这可是天大的运气呢！",
            ["ContentFR"] = "S’il te plaît, accepte ! Parmi tous les Charons de Givrelac, c’est toi qui as été {性别:choisi|choisie} ! Tu es {性别:l’élu|l’élue} !",
            ["DialogueId"] = 51007531,
            ["GUID"] = "7FB1270E",
            ["NextDialogue"] = 51007532,
            ["SpeakNpcId"] = 700011,
            },
        [51007532] = {
            ["Content"] = "（此时，一个高大的卡戎之民从你们旁边路过，男孩的身影在一瞬间消失不见了。你转过头，发现他缩进了你身后的阴影里。）",
            ["ContentFR"] = "Un grand Charon passe près de vous, et le garçon disparaît en un instant. Tu te retournes et le vois caché dans ton ombre.",
            ["DialogueId"] = 51007532,
            ["GUID"] = "7FB12738",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 51007533,
            },
        [51007533] = {
            ["Content"] = "（高大的卡戎之民离开后，男孩又在一瞬间回到了原来的站立位置，仿佛什么都没发生过那样。）",
            ["ContentFR"] = "Quand le Charon s’éloigne, le garçon revient instantanément à sa position initiale. Comme si de rien n’était.",
            ["DialogueId"] = 51007533,
            ["GUID"] = "7FB12762",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 51007534,
            },
        [51007534] = {
            ["Content"] = "好不好嘛，{$XiAoTag(Value_1,Value_2)$|蛋蛋:西比尔}{性别：哥哥|姐姐}？",
            ["ContentFR"] = "Alors... tu es {性别:partant|partante} ?",
            ["DialogueId"] = 51007534,
            ["GUID"] = "7FB1278C",
