            ["SpeakNpcId"] = 100001,
            },
        [51007538] = {
            ["Content"] = "呃……可、可能是有一点点点点害怕……总之，这些小事不重要啦！",
            ["ContentFR"] = "Bon... peut-être un tout petit peu... Mais ce n’est pas important.",
            ["DialogueId"] = 51007538,
            ["GUID"] = "7FB12834",
            ["NextDialogue"] = 51007539,
            ["SpeakNpcId"] = 700011,
            },
        [51007539] = {
            ["Content"] = "刚才说到哪儿了……噢，对了，问卷！如果你实在不愿意填的话，我就挑几个重要的问题问吧，你只要口头回答就行了！",
            ["ContentFR"] = "Où en étions-nous... ah oui, le questionnaire ! Si tu ne veux pas répondre par écrit, je poserai juste quelques questions importantes à l’oral.",
            ["DialogueId"] = 51007539,
            ["GUID"] = "7FB1285E",
            ["NextDialogue"] = 51007540,
            ["SpeakNpcId"] = 700011,
            },
        [51007540] = {
            ["Content"] = "如果你现在有空的话，我们就立刻开始问答吧？",
            ["ContentFR"] = "Si tu es libre maintenant, on peut commencer tout de suite !",
            ["DialogueId"] = 51007540,
            ["GUID"] = "7FB12888",
            ["SpeakNpcId"] = 700011,
            },
        [51007543] = {
            ["Content"] = "好耶！那就听好咯——",
