            ["DialogueId"] = 51007543,
            ["GUID"] = "7FB12906",
            ["NextDialogue"] = 51007544,
            ["SpeakNpcId"] = 700011,
            },
        [51007544] = {
            ["Content"] = "问题1：你为什么只有一只角？",
            ["ContentFR"] = "Question 1 : Pourquoi n’as-tu qu’une seule corne ?",
            ["DialogueId"] = 51007544,
            ["GUID"] = "7FB12930",
