            ["DialogueId"] = 51007545,
            ["GUID"] = "7FB1295A",
            ["NextDialogue"] = 51007546,
            },
        [51007546] = {
            ["Content"] = "噢，所以是先天的差异……",
            ["ContentFR"] = "Ah... donc c’est une différence naturelle. Intéressant...",
            ["DialogueId"] = 51007546,
            ["GUID"] = "7FB12984",
