            ["SpeakNpcId"] = 700011,
            ["TalkActionId"] = {
                [1] = "700011:Agree",
                },
            },
        [51007547] = {
            ["Content"] = "另一只被我卖掉换钱了。",
            ["ContentFR"] = "<I>J’ai vendu l’autre pour de l’argent.</>",
            ["DialogueId"] = 51007547,
            ["GUID"] = "7FB129AE",
            ["NextDialogue"] = 51007548,
            },
        [51007548] = {
            ["Content"] = "咦，还能这样？！",
            ["ContentFR"] = "Hein ? On peut vendre ses cornes ?!",
            ["DialogueId"] = 51007548,
            ["GUID"] = "7FB129D8",
            ["NextDialogue"] = 51007549,
            ["SpeakNpcId"] = 700011,
            ["TalkActionId"] = {
                [1] = "700011:Shock_Start",
                },
            },
        [51007549] = {
