            ["ContentFR"] = "J’aimerais en acheter une pour mes recherches... !",
            ["DialogueId"] = 51007549,
            ["GUID"] = "7FB12A02",
            ["NextDialogue"] = 51007553,
            ["SpeakNpcId"] = 700011,
            },
        [51007550] = {
