            ["NextDialogue"] = 51007569,
            ["SpeakNpcId"] = 700011,
            },
        [51007569] = {
            ["Content"] = "几年前我遇到过一个很友善的卡戎哥哥，他对我说自己是“精灵”。",
            ["ContentFR"] = "Il y a quelques années, j’ai rencontré un Charon très gentil. Il m’a dit qu’il était une \"fée\".",
