                [1] = "0:Explain01_Start",
                },
            },
        [51007711] = {
            ["Content"] = "真的吗？谢谢你！",
            ["ContentFR"] = "Vraiment ? Merci !",
            ["DialogueId"] = 51007711,
            ["GUID"] = "7FB14496",
            ["SpeakNpcId"] = 700204,
            ["TalkActionId"] = {
                [1] = "700204:Agree",
                },
            },
        [51007712] = {
            ["Camera"] = "-329.898193,-397.409424,278.790771,0.000011,-19.79974,48.99963,22.97237,100000.0,false,Manual,22.0",
            ["Content"] = "你看这些破旧的小摊，每天天不亮的时候便会支起来，很多卡戎之民就是这样谋生的。跟他们熟起来的话，说不定会给你打点折扣呢。",
            ["ContentFR"] = "Regarde ces petits étals usés... ils s’installent avant l’aube tous les jours. C’est ainsi que la plupart des Charons gagnent leur vie. Si tu apprends à les connaître, ils pourraient même te faire une petite réduction.",
            ["DialogueId"] = 51007712,
            ["GUID"] = "7FB144C0",
            ["NextDialogue"] = 51007713,
            ["SpeakNpcId"] = 100001,
            },
        [51007713] = {
            ["Camera"] = "-329.898193,-397.409424,278.790771,0.000011,-19.79974,48.99963,22.97237,100000.0,false,Manual,22.0",
            ["Content"] = "大家……很累很辛苦呢。",
            ["ContentFR"] = "Tout le monde... semble très fatigué et travaille dur...",
            ["DialogueId"] = 51007713,
            ["GUID"] = "7FB144EA",
            ["SpeakNpcId"] = 700204,
            },
        [51007714] = {
            ["Camera"] = "128.125977,-687.591797,132.197266,0.00004,9.199882,90.600075,21.238844,100000.0,false,Manual,22.0",
            ["Content"] = "这里就是大部分卡戎生活的地方了。",
            ["ContentFR"] = "Voici où vivent la plupart des Charons à Givrelac.",
            ["DialogueId"] = 51007714,
            ["GUID"] = "7FB14514",
            ["NextDialogue"] = 51007715,
            ["SpeakNpcId"] = 100001,
            },
        [51007715] = {
            ["Camera"] = "128.125977,-687.591797,132.197266,0.00004,9.199882,90.600075,21.238844,100000.0,false,Manual,22.0",
            ["Content"] = "唔嗯……房子破破的，啊，这是那个很凶的大叔在帮邻居修房顶呢。还有这些小朋友在玩的游戏，我在内城也和朋友们玩过。",
            ["ContentFR"] = "Hmm... les maisons sont vraiment délabrées... Ah ! C’est le vieux monsieur grincheux, il aide son voisin à réparer le toit ! Et ces enfants jouent aux mêmes jeux que nous jouons dans la cité intérieure !",
            ["DialogueId"] = 51007715,
            ["GUID"] = "7FB1453E",
            ["NextDialogue"] = 51007716,
            ["SpeakNpcId"] = 700204,
            },
        [51007716] = {
            ["Camera"] = "128.125977,-687.591797,132.197266,0.00004,9.199882,90.600075,21.238844,100000.0,false,Manual,22.0",
            ["Content"] = "我懂你的意思了，事实并不像妈妈说的那样，虽然有些卡戎人说话很凶、行为古怪……但我们索拉人里也有这种人啊。",
            ["ContentFR"] = "Je comprends maintenant... ce n’est pas comme ce que dit maman. Certes, certains Charons sont rudes ou étranges... mais chez les Solariens, il y a aussi des gens comme ça.",
            ["DialogueId"] = 51007716,
            ["GUID"] = "7FB14568",
            ["NextDialogue"] = 51007717,
            ["SpeakNpcId"] = 700204,
            },
        [51007717] = {
            ["Camera"] = "128.125977,-687.591797,132.197266,0.00004,9.199882,90.600075,21.238844,100000.0,false,Manual,22.0",
            ["Content"] = "除了头上的角以外，我觉得你们和我们没有什么不同。",
            ["ContentFR"] = "À part les cornes sur la tête... je ne vois pas de grande différence entre les Charons et Solariens.",
            ["DialogueId"] = 51007717,
            ["GUID"] = "7FB14592",
            ["NextDialogue"] = 51007718,
            ["SpeakNpcId"] = 700204,
            ["TalkActionId"] = {
                [1] = "700204:Explain01_Start",
                },
            },
        [51007718] = {
            ["Camera"] = "128.125977,-687.591797,132.197266,0.00004,9.199882,90.600075,21.238844,100000.0,false,Manual,22.0",
            ["Content"] = "这么明显的事实，只要稍微观察一下就明白了，为什么大家还是坚持那些错误的说法呢？",
            ["ContentFR"] = "Quand on regarde bien, ça se voit tout de suite... Alors pourquoi les gens s’accrochent-ils à des idées fausses, même quand la vérité est sous leurs yeux ?",
            ["DialogueId"] = 51007718,
            ["GUID"] = "7FB145BC",
            ["NextOptions"] = {
                [1] = 51007719,
                [2] = 51007720,
                },
            ["SpeakNpcId"] = 700204,
            ["TalkActionId"] = {
                [1] = "700204:Think_Start",
                },
            },
        [51007719] = {
            ["Content"] = "因为偏见的力量往往会胜过眼前的真相。",
            ["ContentFR"] = "<I>Parce que le préjugé est souvent plus fort que la vérité.</>",
            ["DialogueId"] = 51007719,
            ["GUID"] = "7FB145E6",
            ["NextDialogue"] = 51007721,
            },
        [51007720] = {
            ["Content"] = "也许他们是刻意对此视而不见的。",
            ["ContentFR"] = "<I>Peut-être qu’ils choisissent simplement de fermer les yeux.</>",
            ["DialogueId"] = 51007720,
            ["GUID"] = "7FB14610",
            ["NextDialogue"] = 51007721,
            },
        [51007721] = {
            ["Camera"] = "128.125977,-687.591797,132.197266,0.00004,9.199882,90.600075,21.238844,100000.0,false,Manual,22.0",
            ["Content"] = "是吗……？好复杂哦……看来世界上也有研究解决不了的问题啊……",
            ["ContentFR"] = "Vraiment ? C’est compliqué... Il y a des problèmes dans le monde que même la recherche ne peut résoudre...",
            ["DialogueId"] = 51007721,
            ["GUID"] = "7FB1463A",
            ["NextDialogue"] = 51007722,
            ["SpeakNpcId"] = 700204,
            },
        [51007722] = {
            ["Camera"] = "128.125977,-687.591797,132.197266,0.00004,9.199882,90.600075,21.238844,100000.0,false,Manual,22.0",
            ["Content"] = "不想这些了，正好你带着相机，我们再一起去拍一下城北边的那个叫，修，修普诺斯之家的漂亮房子吧！我在那里等你哦~",
            ["ContentFR"] = "Bon, oublions ça pour l’instant. Avec l’appareil photo, allons prendre des photos de la jolie maison au nord, la Maison d’Hypnos ! Je t’attends là-bas !",
            ["DialogueId"] = 51007722,
            ["GUID"] = "7FB14664",
            ["SpeakNpcId"] = 700204,
            ["TalkActionId"] = {
                [1] = "700204:Disagree",
                },
            },
        [51007723] = {
            ["Content"] = "你来啦~嘿嘿，我以前就偷偷观察过，那里面住着的都是年纪不大的卡戎哥哥姐姐，经过今天的了解，我……我想和他们聊聊天！",
            ["ContentFR"] = "Tu es là ! Héhé, en fait j’ai déjà observé discrètement cette maison auparavant, il y avait des jeunes Charons dedans. Après tout ce que j’ai appris aujourd’hui... je veux vraiment leur parler !",
            ["DialogueId"] = 51007723,
            ["GUID"] = "7FB1468E",
            ["NextDialogue"] = 51007724,
            ["SpeakNpcId"] = 700204,
            },
        [51007724] = {
            ["Content"] = "{nickname}，你可以和我一起去吗？",
            ["ContentFR"] = "{nickname}, tu viens avec moi ?",
            ["DialogueId"] = 51007724,
            ["GUID"] = "7FB146B8",
            ["NextDialogue"] = 51007725,
            ["SpeakNpcId"] = 700204,
            },
        [51007725] = {
            ["Content"] = "…………",
            ["ContentFR"] = "...",
            ["DialogueId"] = 51007725,
            ["GUID"] = "7FB146E2",
            ["NextOptions"] = {
                [1] = 51007726,
                [2] = 51007727,
                },
            ["SpeakNpcId"] = 100001,
            },
        [51007726] = {
            ["Content"] = "（说出真相。）",
            ["ContentFR"] = "<I>Dire la vérité</>",
            ["DialogueId"] = 51007726,
            ["GUID"] = "7FB1470C",
            ["ImprPlusId"] = 1002,
            ["NextDialogue"] = 51007728,
            },
        [51007727] = {
            ["Content"] = "（犹豫是否说出真相。）",
            ["ContentFR"] = "<I>Hésiter à dire la vérité</>",
            ["DialogueId"] = 51007727,
            ["GUID"] = "7FB14736",
            ["ImprPlusId"] = 1004,
            ["NextDialogue"] = 51007728,
            },
        [51007728] = {
            ["Content"] = "他们这会儿……不一定方便……",
            ["ContentFR"] = "Ils... ne sont peut-être pas disponibles maintenant.",
            ["DialogueId"] = 51007728,
            ["GUID"] = "7FB14760",
            ["NextDialogue"] = 51007729,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "0:Disagree",
                },
            },
        [51007729] = {
            ["Content"] = "嗯……？这样吗……",
            ["ContentFR"] = "Hein... ? D’accord...",
            ["DialogueId"] = 51007729,
            ["GUID"] = "7FB1478A",
            ["NextDialogue"] = 51007730,
            ["SpeakNpcId"] = 700204,
            },
        [51007730] = {
            ["Content"] = "那……我可以敲门问问吗？就问问，说不定他们刚好有空呢！",
            ["ContentFR"] = "Euh... Je peux au moins frapper à la porte ? Peut-être qu’ils ont un peu de temps !",
            ["DialogueId"] = 51007730,
            ["GUID"] = "7FB147B4",
            ["NextDialogue"] = 51007731,
            ["SpeakNpcId"] = 700204,
            },
        [51007731] = {
            ["Content"] = "……其实，那里已经没有人了。所以，已经不用敲门了。",
            ["ContentFR"] = "... En fait, la maison est vide maintenant.",
            ["DialogueId"] = 51007731,
            ["GUID"] = "7FB147DE",
            ["NextDialogue"] = 51007732,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "0:Explain01_Start",
                },
            },
        [51007732] = {
            ["Content"] = "诶？为什么，明明我上次偷看的时候看到好几个哥哥姐姐呢。",
            ["ContentFR"] = "Hein ? Mais la dernière fois, il y avait plein d’enfants plus vieux que moi dedans !",
            ["DialogueId"] = 51007732,
            ["GUID"] = "7FB14808",
            ["NextDialogue"] = 51007733,
            ["SpeakNpcId"] = 700204,
            },
        [51007733] = {
            ["Content"] = "他们……搬家了……",
            ["ContentFR"] = "Ils... ont déménagé.",
            ["DialogueId"] = 51007733,
            ["GUID"] = "7FB14832",
            ["NextDialogue"] = 51007734,
            ["SpeakNpcId"] = 100001,
            },
        [51007734] = {
            ["Content"] = "那他们什么时候回来呢？",
            ["ContentFR"] = "Ah ? Tu sais quand ils vont revenir ?",
            ["DialogueId"] = 51007734,
            ["GUID"] = "7FB1485C",
            ["NextDialogue"] = 51007735,
            ["SpeakNpcId"] = 700204,
            },
        [51007735] = {
            ["Content"] = "正好让我整理一下问题，我想问问那个穿绿衣服的姐姐！至于那个凶巴巴的吓人大叔……就算、算了吧。",
            ["ContentFR"] = "Je vais réfléchir à ce que je veux demander pendant que j’attends ! J’ai des tonnes de questions pour cette dame en vert ! Et le monsieur grincheux... euh... peut-être que lui je vais l’éviter.",
            ["DialogueId"] = 51007735,
            ["GUID"] = "7FB14886",
            ["NextDialogue"] = 51007736,
            ["SpeakNpcId"] = 700204,
            },
        [51007736] = {
            ["Content"] = "他们……不会回来了。",
            ["ContentFR"] = "Ils... ne reviendront pas.",
            ["DialogueId"] = 51007736,
            ["GUID"] = "7FB148B0",
            ["NextDialogue"] = 51007737,
            ["SpeakNpcId"] = 100001,
            },
        [51007737] = {
            ["Content"] = "为什么呀？那些军人叔叔把他们赶走了吗，还是说他们搬到别的城市去了？真好呀，其他地方比冰湖城暖和多了，应该还有很多值得研究的——",
            ["ContentFR"] = "Hein ? Pourquoi ? Les soldats les ont chassés ? Ou alors... ils ont déménagé dans une autre ville ? Ce serait bien, non ? Là-bas il doit faire plus chaud qu’à Givrelac, et il y a sûrement plein de choses passionnantes à étudier—",
            ["DialogueId"] = 51007737,
            ["GUID"] = "7FB148DA",
            ["NextDialogue"] = 51007738,
            ["SpeakNpcId"] = 700204,
            },
        [51007738] = {
            ["Content"] = "咦？！{性别：哥哥|姐姐}你怎么哭了？摸摸你，不哭不哭！",
            ["ContentFR"] = "Hein ?! ... Tu pleures ? Euh... n-n’aie pas peur, d’accord ? Ça va aller...",
            ["DialogueId"] = 51007738,
            ["GUID"] = "7FB14904",
            ["NextDialogue"] = 51007739,
            ["SpeakNpcId"] = 700204,
            ["TalkActionId"] = {
                [1] = "700204:Shock_Start",
                },
            },
        [51007739] = {
            ["Content"] = "没、没事。旅馆的主人恩里克呢，是一个很好很好的医生。他带着他的小助手们去了南方，去研究一种疾病的治疗方式，因为他想救很多很多人。",
            ["ContentFR"] = "Ce... ce n’est rien. L’aubergiste, Henrik, c’était un médecin formidable. Il est parti vers le sud avec ses apprentis, pour chercher un remède à une terrible maladie. Parce qu’il voulait sauver le plus de vies possible.",
            ["DialogueId"] = 51007739,
            ["GUID"] = "7FB1492E",
            ["NextDialogue"] = 51007740,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "0:Disagree",
                },
            },
        [51007740] = {
            ["Content"] = "疾病？唔，是一种怎样的疾病呢？",
            ["ContentFR"] = "Une maladie ? Quelle sorte de maladie ?",
            ["DialogueId"] = 51007740,
            ["GUID"] = "7FB14958",
            ["NextDialogue"] = 51007741,
            ["SpeakNpcId"] = 700204,
            },
        [51007741] = {
            ["Content"] = "……“秽蚀”，一种只有卡戎之民会得的病，现在还治不好，很多很多卡戎之民在受它折磨。",
            ["ContentFR"] = "... On l’appelle la \"Dégradation\". Une maladie qui n’affecte que les Charons. Il n’existe encore aucun traitement... et beaucoup des nôtres en souffrent chaque jour.",
            ["DialogueId"] = 51007741,
            ["GUID"] = "7FB14982",
            ["NextDialogue"] = 51007742,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "0:Think_Start",
                },
            },
        [51007742] = {
            ["Content"] = "咦？治不好吗？我认识的医生姐姐告诉我，炼金院里有一群聪明的炼金术师，他们会研究消除索拉人各种疑难杂症的方法……",
            ["ContentFR"] = "Quoi ?! Pas de remède ?! Mais... mais la médecin que je connais m’a dit qu’à l’Académie d’Alchimie, il y a des tas d’alchimistes super intelligents ! Ils cherchent toujours des remèdes pour soigner toutes les maladies des Solariens...",
            ["DialogueId"] = 51007742,
            ["GUID"] = "7FB149AC",
            ["NextDialogue"] = 51007743,
            ["SpeakNpcId"] = 700204,
            },
        [51007743] = {
            ["Content"] = "（男孩提到“索拉人”之后愣了一下，似乎明白了什么。）",
            ["ContentFR"] = "Theo s’interrompt en prononçant « Solariens », comme si quelque chose venait de lui tomber dessus.",
            ["DialogueId"] = 51007743,
            ["GUID"] = "7FB149D6",
            ["NextDialogue"] = 51007744,
            },
        [51007744] = {
            ["Content"] = "所以，那些大人们……不会帮卡戎研究治疗那种病的办法？",
            ["ContentFR"] = "Alors... ça veut dire qu’ils n’essaient pas de soigner les Charons ?",
            ["DialogueId"] = 51007744,
            ["GUID"] = "7FB14A00",
            ["NextDialogue"] = 51007745,
            ["SpeakNpcId"] = 700204,
            },
        [51007745] = {
            ["Content"] = "那可怎么行……明明大家都是一样的，怎么能因为是卡戎就不去救治呢！",
            ["ContentFR"] = "Mais... mais c’est pas juste ! Malade, c’est malade, peu importe qui c’est ! Pourquoi ils feraient semblant de rien juste parce que ce sont des Charons ?!",
            ["DialogueId"] = 51007745,
            ["GUID"] = "7FB14A2A",
            ["NextOptions"] = {
                [1] = 51007746,
                },
            ["SpeakNpcId"] = 700204,
            ["TalkActionId"] = {
                [1] = "700204:Disagree",
                },
            },
        [51007746] = {
            ["Content"] = "这里或许没有……但是我相信，在世界的某处，一定有人正在为此努力着。",
            ["ContentFR"] = "<I>Peut-être pas ici... mais quelque part, quelqu’un doit sûrement chercher un remède.</>",
            ["DialogueId"] = 51007746,
            ["GUID"] = "7FB14A54",
            ["ImprPlusId"] = 1004,
            ["NextDialogue"] = 51007747,
            },
        [51007747] = {
            ["Content"] = "……我决定了！大家的看法或许不是单靠研究就能改变的，但疾病的话，还是可以靠研究解决的吧？",
            ["ContentFR"] = "... D’accord, j’ai décidé ! Peut-être que je peux pas changer la façon dont les gens pensent... mais la maladie, elle, on peut la combattre avec la recherche, non ?",
            ["DialogueId"] = 51007747,
            ["GUID"] = "7FB14A7E",
            ["NextDialogue"] = 51007748,
            ["SpeakNpcId"] = 700204,
            ["TalkActionId"] = {
                [1] = "700204:Angry01_Start",
                },
            },
        [51007748] = {
            ["Content"] = "我也要研究那种病！我也想像你说的那个医生一样，好好努力，去救很多很多人。",
            ["ContentFR"] = "Alors moi aussi, je vais l’étudier ! Je veux trouver un remède, comme le docteur dont tu m’as parlé, et sauver plein de gens !",
            ["DialogueId"] = 51007748,
            ["GUID"] = "7FB14AA8",
            ["NextDialogue"] = 51007749,
            ["SpeakNpcId"] = 700204,
            },
        [51007749] = {
            ["Content"] = "我们的炼金院有很多很多帮助索拉人的炼金术师，但我西奥想要成为第一个帮助卡戎的炼金术师！",
            ["ContentFR"] = "À l’Académie d’Alchimie, tout le monde travaille pour aider les Solariens... mais moi, Theo, je serai le premier alchimiste à aider les Charons !",
            ["DialogueId"] = 51007749,
            ["GUID"] = "7FB14AD2",
            ["NextDialogue"] = 51007750,
            ["SpeakNpcId"] = 700204,
            },
        [51007750] = {
            ["Content"] = "你可以把那种病的名字写在这里吗？我要记住它。",
            ["ContentFR"] = "Dis, tu peux écrire le nom de la maladie ici ? Je veux être sûr de ne jamais l’oublier.",
            ["DialogueId"] = 51007750,
            ["GUID"] = "7FB14AFC",
            ["NextDialogue"] = 51007751,
            ["SpeakNpcId"] = 700204,
            ["TalkActionId"] = {
                [1] = "700204:Explain01_Start",
                },
            },
        [51007751] = {
            ["Content"] = "（你接过了男孩递来的笔记本，认真地写下了“秽蚀”二字。）",
            ["ContentFR"] = "Tu prends le carnet que le garçon te tend et tu écris soigneusement le mot « Dégradation » sur la page.",
            ["DialogueId"] = 51007751,
            ["GUID"] = "7FB14B26",
            ["NextDialogue"] = 51007752,
            },
        [51007752] = {
            ["Content"] = "嗯，“秽蚀”……我记住了。",
            ["ContentFR"] = "« Dégradation »... d’accord, je m’en souviendrai.",
            ["DialogueId"] = 51007752,
            ["GUID"] = "7FB14B50",
            ["NextDialogue"] = 51007753,
            ["SpeakNpcId"] = 700204,
            ["TalkActionId"] = {
                [1] = "700204:Agree",
                },
            },
        [51007753] = {
            ["Content"] = "{nickname}，谢谢你告诉我这些！今天我学到了很多。",
            ["ContentFR"] = "Merci, {nickname} ! J’ai appris tellement de choses aujourd’hui !",
            ["DialogueId"] = 51007753,
            ["GUID"] = "7FB14B7A",
            ["NextDialogue"] = 51007754,
            ["SpeakNpcId"] = 700204,
            },
        [51007754] = {
            ["Content"] = "你也要好好努力喔！你这么优秀，你也一定可以成为冰湖城最厉害的狩月人，让大家都对卡戎刮目相看。",
            ["ContentFR"] = "Toi aussi, continue de te donner à fond ! Tu es déjà {性别:super fort|super forte}... je suis sûr qu’un jour tu deviendras {性别:le plus grand Chasseur de Phoxène|la plus grande Chasseuse de Phoxène} de Givrelac, et tout le monde verra que les Charons sont formidables !",
            ["DialogueId"] = 51007754,
            ["GUID"] = "7FB14BA4",
            ["NextDialogue"] = 51007755,
            ["SpeakNpcId"] = 700204,
            },
        [51007755] = {
            ["Content"] = "好，一言为定。",
            ["ContentFR"] = "D’accord. Promis.",
            ["DialogueId"] = 51007755,
            ["GUID"] = "7FB14BCE",
            ["NextDialogue"] = 51007756,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "0:Agree",
                },
            },
        [51007756] = {
            ["Content"] = "一言为定！",
            ["ContentFR"] = "Promis !",
            ["DialogueId"] = 51007756,
            ["GUID"] = "7FB14BF8",
            ["NextDialogue"] = 51007757,
            ["SpeakNpcId"] = 700204,
            },
        [51007757] = {
            ["Content"] = "（男孩向你挥手作别，他的脸上还挂着属于孩童的天真笑容，只不过相比之前，那笑容中似乎更多了一分坚定。）",
            ["ContentFR"] = "Le garçon te fait un grand signe de la main. Son sourire reste empreint de l’innocence des enfants... mais cette fois, on y devine une nouvelle lueur de détermination.",
            ["DialogueId"] = 51007757,
            ["GUID"] = "7FB14C22",
            },
        [51007758] = {
            ["Content"] = "{nickname}，又见面啦！我每天都在努力学习新知识哦，一起加油吧！",
            ["ContentFR"] = "{nickname} ! Je suis content de te voir ! Moi, je continue à apprendre plein de nouvelles choses tous les jours. Alors... on continue à progresser ensemble, d’accord ?",
            ["DialogueId"] = 51007758,
            ["GUID"] = "7FB14C4C",
            ["SpeakNpcId"] = 700204,
            },
        [51007801] = {
            ["Content"] = "向自然法则扔出的石头，最终一定会砸到自己的头上。",
            ["DialogueId"] = 51007801,
            ["GUID"] = "7FB1535A",
            ["NextDialogue"] = 51007802,
            ["SpeakNpcId"] = 700018,
            },
        [51007802] = {
            ["Content"] = "（这是一个瘦弱潦倒的中年男性，看起来有些神经质，鼻梁上挂着一副厚厚的眼镜。）",
            ["DialogueId"] = 51007802,
            ["GUID"] = "7FB15384",
            ["NextDialogue"] = 51007803,
            },
        [51007803] = {
            ["Content"] = "（周围散落的报告署名是“阿尔加尔”，你似乎在某些生物学期刊上见过这个名字。）",
            ["DialogueId"] = 51007803,
            ["GUID"] = "7FB153AE",
            ["NextOptions"] = {
                [1] = 51007804,
                [2] = 51007806,
                [3] = 51007808,
                },
            },
        [51007804] = {
            ["Content"] = "自然是万物的起源，我们理应保护好它。",
            ["DialogueId"] = 51007804,
            ["GUID"] = "7FB153D8",
            ["ImprPlusId"] = 1002,
            ["NextDialogue"] = 51007805,
            },
        [51007805] = {
            ["Content"] = "是的是的，我正是为此而来的。",
            ["DialogueId"] = 51007805,
            ["GUID"] = "7FB15402",
            ["NextDialogue"] = 51007810,
            ["SpeakNpcId"] = 100001,
            },
        [51007806] = {
            ["Content"] = "自然是镜子，破坏它的苦果只会由自己吞食。",
            ["DialogueId"] = 51007806,
            ["GUID"] = "7FB1542C",
            ["ImprPlusId"] = 1001,
            ["NextDialogue"] = 51007807,
            },
        [51007807] = {
            ["Content"] = "深刻的见解，我是生物学者阿尔加尔，很高兴认识你。",
            ["DialogueId"] = 51007807,
            ["GUID"] = "7FB15456",
            ["NextDialogue"] = 51007810,
            ["SpeakNpcId"] = 100001,
            },
        [51007808] = {
            ["Content"] = "笑死，根本活不到砸到我的那天。",
            ["DialogueId"] = 51007808,
            ["GUID"] = "7FB15480",
            ["ImprPlusId"] = 1005,
            ["NextDialogue"] = 51007809,
            },
        [51007809] = {
            ["Content"] = "……",
            ["DialogueId"] = 51007809,
            ["GUID"] = "7FB154AA",
            ["NextDialogue"] = 51007810,
            ["SpeakNpcId"] = 100001,
            },
        [51007810] = {
            ["Content"] = "唉，年轻人，你听说过冰湖城的红角鹿吗？",
            ["DialogueId"] = 51007810,
            ["GUID"] = "7FB154D4",
            ["NextDialogue"] = 51007811,
            ["SpeakNpcId"] = 700018,
            },
        [51007811] = {
            ["Content"] = "那是非常古老的物种，已经存在了三亿多年，至今保留着其原始而古老的相貌。",
            ["DialogueId"] = 51007811,
            ["GUID"] = "7FB154FE",
            ["NextDialogue"] = 51007812,
            ["SpeakNpcId"] = 700018,
            },
        [51007812] = {
            ["Content"] = "这不只是一对红角，这是整片大陆诞生时的......脐血。",
            ["DialogueId"] = 51007812,
            ["GUID"] = "7FB15528",
            ["NextDialogue"] = 51007813,
            ["SpeakNpcId"] = 700018,
            },
        [51007813] = {
            ["Content"] = "（阿尔加尔说话时，原本苍白的脸上浮现出了激动的红晕。可随后他似乎又想起了什么，露出焦虑悲戚的神色。）",
            ["DialogueId"] = 51007813,
            ["GUID"] = "7FB15552",
            ["NextDialogue"] = 51007814,
            },
        [51007814] = {
            ["Content"] = "所以我一定要阻止那些贪得无厌的猎人，不能再任由他们无节制地狩猎红角鹿了......",
            ["DialogueId"] = 51007814,
            ["GUID"] = "7FB1557C",
            ["NextDialogue"] = 51007815,
            ["SpeakNpcId"] = 700018,
            },
        [51007815] = {
            ["Content"] = "红角鹿的鹿角具有极高的药用价值，内城的贵族们开了高价收购。",
            ["DialogueId"] = 51007815,
            ["GUID"] = "7FB155A6",
            ["NextDialogue"] = 51007816,
            ["SpeakNpcId"] = 700018,
            },
        [51007816] = {
            ["Content"] = "那群贵族们的拥趸像一群见了血肉的苍蝇一样蜂拥而上。他们握着枪杆杀红了眼，射向红角鹿的子弹越多，他们腰间的钱袋越重。",
            ["DialogueId"] = 51007816,
            ["GUID"] = "7FB155D0",
            ["NextDialogue"] = 51007817,
            ["SpeakNpcId"] = 700018,
            },
        [51007817] = {
            ["Content"] = "仅仅十年，冰湖城郊区的红角鹿就从随处可见变成如今濒临灭绝的境地。",
            ["DialogueId"] = 51007817,
            ["GUID"] = "7FB155FA",
            ["NextOptions"] = {
                [1] = 51007818,
                },
            ["RestartTag"] = 51007817,
            ["SpeakNpcId"] = 700018,
            },
        [51007818] = {
            ["Content"] = "红角鹿活了三亿年，不该被人们的贪婪一朝逼入绝境。",
            ["DialogueId"] = 51007818,
            ["GUID"] = "7FB15624",
            ["ImprCheckId"] = 1063,
            ["NextDialogue"] = 51007819,
            },
        [51007819] = {
            ["Content"] = "算了，多说无益......",
            ["DialogueId"] = 51007819,
            ["GUID"] = "7FB1564E",
            ["NextDialogue"] = 51007820,
            ["SpeakNpcId"] = 700018,
            },
        [51007820] = {
            ["Content"] = "（阿尔加尔叹了口气，瘦弱的身体在转身时踉跄了一下，离开的背影如同一位殉道者。）",
            ["DialogueId"] = 51007820,
            ["GUID"] = "7FB15678",
            ["NextDialogue"] = 51007821,
            ["SpeakNpcId"] = 700018,
            },
        [51007821] = {
            ["Content"] = "正如你所说，它们珍贵的鹿角不该成了猎人的摇钱树。",
            ["DialogueId"] = 51007821,
            ["GUID"] = "7FB156A2",
            ["NextDialogue"] = 51007822,
            ["SpeakNpcId"] = 700018,
            },
        [51007822] = {
            ["Content"] = "红角鹿的繁殖期马上就要到了，我们必须为自然真的做些什么。",
            ["DialogueId"] = 51007822,
            ["GUID"] = "7FB156CC",
            ["NextDialogue"] = 51007823,
            ["SpeakNpcId"] = 700018,
            },
        [51007823] = {
            ["Content"] = "咳，年轻人，可以拜托你帮我阻止那些滥杀红角鹿的猎人吗？",
            ["DialogueId"] = 51007823,
            ["GUID"] = "7FB156F6",
            ["NextDialogue"] = 51007824,
            ["SpeakNpcId"] = 700018,
            },
        [51007824] = {
            ["Content"] = "年轻人，那就靠你了，我在这里等你回来。",
            ["DialogueId"] = 51007824,
            ["GUID"] = "7FB15720",
            ["SpeakNpcId"] = 700018,
            },
        [51007825] = {
            ["Content"] = "赶走滥杀红角鹿的猎人，已经刻不容缓了。",
            ["DialogueId"] = 51007825,
            ["GUID"] = "7FB1574A",
            ["SpeakNpcId"] = 700018,
            },
        [51007826] = {
            ["Content"] = "（这只红角鹿的脖颈已经被猎人的子弹击穿，胸腔微弱起伏是它最后的挣扎。）",
            ["DialogueId"] = 51007826,
            ["GUID"] = "7FB15774",
            ["NextDialogue"] = 51007827,
            },
        [51007827] = {
            ["Content"] = "（那双鹿眼雾气朦胧，它委屈地看向你，仿佛希望你能说出什么解释，好让它能情愿地接受自己被剥夺生机的命运。）",
            ["DialogueId"] = 51007827,
            ["GUID"] = "7FB1579E",
            ["NextDialogue"] = 51007828,
            },
        [51007828] = {
            ["Content"] = "（你没有说话，直到那对鹿角上的殷红不再美丽。）",
            ["DialogueId"] = 51007828,
            ["GUID"] = "7FB157C8",
            },
        [51007829] = {
            ["Content"] = "太好了！让这些猎人得到教训后，他们至少就不会在红角鹿的繁殖期滥捕了。",
            ["DialogueId"] = 51007829,
            ["GUID"] = "7FB157F2",
            ["NextDialogue"] = 51007830,
            ["SpeakNpcId"] = 700018,
            },
        [51007830] = {
            ["Content"] = "你帮了我一个大忙，真不知道该怎么感谢你好......",
            ["DialogueId"] = 51007830,
            ["GUID"] = "7FB1581C",
            ["NextOptions"] = {
                [1] = 51007831,
                [2] = 51007834,
                },
            ["SpeakNpcId"] = 700018,
            },
        [51007831] = {
            ["Content"] = "您真的非常重视红角鹿与自然生态的平衡。",
            ["DialogueId"] = 51007831,
            ["GUID"] = "7FB15846",
            ["ImprPlusId"] = 1002,
            ["NextDialogue"] = 51007832,
            },
        [51007832] = {
            ["Content"] = "这还用说，我建议你精读一下这篇论文——《海伯利亚帝国生物多样性和生态系统保护的伦理之争》。",
            ["DialogueId"] = 51007832,
            ["GUID"] = "7FB15870",
            ["NextDialogue"] = 51007833,
            ["SpeakNpcId"] = 700018,
            },
        [51007833] = {
            ["Content"] = "这篇论文是以红角鹿为典型案例，对环境伦理学和人类中心主义伦理观进行综述——当然，很巧的是，这篇论文的作者正是我。",
            ["DialogueId"] = 51007833,
            ["GUID"] = "7FB1589A",
            ["NextDialogue"] = 51007837,
            ["SpeakNpcId"] = 700018,
            },
        [51007834] = {
            ["Content"] = "您为了红角鹿一直很辛苦，可以休息一阵了。",
            ["DialogueId"] = 51007834,
            ["GUID"] = "7FB158C4",
            ["ImprPlusId"] = 1004,
            ["NextDialogue"] = 51007835,
            },
        [51007835] = {
            ["Content"] = "休息？休息什么？就算那些见钱眼开的臭虫们愿意消停一会儿，红角鹿的生存环境依然受到了不小的破坏。",
            ["DialogueId"] = 51007835,
            ["GUID"] = "7FB158EE",
            ["NextDialogue"] = 51007836,
            ["SpeakNpcId"] = 700018,
            },
        [51007836] = {
            ["Content"] = "我得赶在这段时间里好好磨一磨那群婆婆妈妈的政客，让他们马上围栏保护好栖息地，否则红角鹿还是永无宁日。",
            ["DialogueId"] = 51007836,
            ["GUID"] = "7FB15918",
            ["NextDialogue"] = 51007837,
            ["SpeakNpcId"] = 700018,
            },
        [51007837] = {
            ["Content"] = "唉，我在几十年前就发过誓，要为生物学事业付出我的一切。",
            ["DialogueId"] = 51007837,
            ["GUID"] = "7FB15942",
            ["NextDialogue"] = 51007838,
            ["SpeakNpcId"] = 700018,
            },
        [51007838] = {
            ["Content"] = "我自认做到了，也付出了代价，这代价里包括我的家人、爱人与朋友，哦对，还有所有的积蓄。",
            ["DialogueId"] = 51007838,
            ["GUID"] = "7FB1596C",
            ["NextDialogue"] = 51007839,
            ["SpeakNpcId"] = 700018,
            },
        [51007839] = {
            ["Content"] = "你能想象到吗？每分每秒都聒噪不停的刻薄奚落，只能荒郊破屋里睡觉导致的一身的冻疮，还有曾经真诚支持你的人转身离开的背影。",
            ["DialogueId"] = 51007839,
            ["GUID"] = "7FB15996",
            ["NextDialogue"] = 51007840,
            ["SpeakNpcId"] = 700018,
            },
        [51007840] = {
            ["Content"] = "我得承认，这确实是一场颠沛流离又漫长的旅程。",
            ["DialogueId"] = 51007840,
            ["GUID"] = "7FB159C0",
            ["NextDialogue"] = 51007841,
            ["SpeakNpcId"] = 700018,
            },
        [51007841] = {
            ["Content"] = "（阿尔加尔看向红角鹿的标本，他的眼神变了，像慈爱的父亲，忽然又像委屈的孩子。）",
            ["DialogueId"] = 51007841,
            ["GUID"] = "7FB159EA",
            ["NextDialogue"] = 51007842,
            },
        [51007842] = {
            ["Content"] = "说实话，我不知道要做什么才能真的挽留这些即将消失的生灵。",
            ["DialogueId"] = 51007842,
            ["GUID"] = "7FB15A14",
            ["NextDialogue"] = 51007843,
            ["SpeakNpcId"] = 700018,
            },
        [51007843] = {
            ["Content"] = "但是，我想我知道要为此尽瘁到何时——",
            ["DialogueId"] = 51007843,
            ["GUID"] = "7FB15A3E",
            ["NextDialogue"] = 51007844,
            ["SpeakNpcId"] = 700018,
            },
        [51007844] = {
            ["Content"] = "直到鹿角上面落满花瓣。",
            ["DialogueId"] = 51007844,
            ["GUID"] = "7FB15A68",
            ["SpeakNpcId"] = 700018,
            },
        [51007845] = {
            ["Content"] = "我们人类，存续于自然中的意义，究竟是什么？",
            ["DialogueId"] = 51007845,
            ["GUID"] = "7FB15A92",
            ["SpeakNpcId"] = 700018,
            },
        [51007901] = {
            ["Content"] = "走过路过不要错过了嘿！免费体验最新最酷的雾区娱乐项目，不玩的话后悔一辈子了呦！",
            ["ContentFR"] = "Venez, venez, ne passez pas à côté ! Testez gratuitement la toute dernière attraction de Brumelac, la plus amusante et excitante ! Si vous ne jouez pas, vous le regretterez toute votre vie !",
            ["DialogueId"] = 51007901,
            ["GUID"] = "7FB163C2",
            ["SpeakNpcId"] = 700069,
            },
        [51007902] = {
            ["Content"] = "（达顿看到你后立马兴奋地冲了过来，一股浓厚的香水味包裹着下水道的气息向你袭来，直熏得你眼睛生疼。）",
            ["ContentFR"] = "Dès que Dutton te repère, il se précipite vers toi, un parfum entêtant mêlé à l’odeur des égouts te frappe en pleine figure, te faisant presque pleurer.",
            ["DialogueId"] = 51007902,
            ["GUID"] = "7FB163EC",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 51007903,
            },
        [51007903] = {
            ["Content"] = "亲爱的朋友，你来得太是时候了，现在体验本项目，你就刚刚好是第100位参与者了！不光不要钱啊，我还送你钱呢！怎么样，要不要来试试！",
            ["ContentFR"] = "{性别:Mon cher ami|Ma chère amie}, tu arrives pile au bon moment ! En participant maintenant, tu es exactement la centième personne ! Et ce n’est pas tout, c’est gratuit et en plus, je te donne une récompense ! Alors, ça te tente ?",
            ["DialogueId"] = 51007903,
            ["GUID"] = "7FB16416",
            ["SpeakNpcId"] = 700069,
            },
        [51007904] = {
            ["Content"] = "（你敏锐地注意到达顿眼神中的躲闪——这个项目想必并不是那么受欢迎。）",
            ["ContentFR"] = "Tu remarques une lueur d’évitement dans le regard de Dutton, cette attraction n’est sans doute pas aussi populaire qu’il le prétend.",
            ["DialogueId"] = 51007904,
            ["GUID"] = "7FB16440",
            ["NextOptions"] = {
                [1] = 51007905,
                [2] = 51007906,
                },
            },
        [51007905] = {
            ["Content"] = "（虽然有种不好的预感，但只要奖励足够丰厚，那体验一下也无妨。）",
            ["ContentFR"] = "<I>– Même si j’ai un mauvais pressentiment... si la récompense est suffisamment alléchante, autant tenter l’expérience.</>",
            ["DialogueId"] = 51007905,
            ["GUID"] = "7FB1646A",
            ["ImprPlusId"] = 1001,
            ["NextDialogue"] = 51007907,
            },
        [51007906] = {
            ["Content"] = "白捡的便宜不占白不占。",
            ["ContentFR"] = "<I>De l’argent gratuit ? Je ne vais pas dire non.</>",
            ["DialogueId"] = 51007906,
            ["GUID"] = "7FB16494",
            ["ImprPlusId"] = 1005,
            ["NextDialogue"] = 51007907,
            },
        [51007907] = {
            ["Content"] = "年轻人就是有眼光啊！来来来，我们这边走，路上可能会碰到一两只秽兽，但我相信这点小麻烦对你肯定不算什么的！",
            ["ContentFR"] = "Tu as vraiment l’œil ! Viens, suis-moi, mais attention, on risque de croiser un ou deux Souillés sur le chemin. Mais je suis sûr que ça ne te posera aucun problème !",
            ["DialogueId"] = 51007907,
            ["GUID"] = "7FB164BE",
            ["SpeakNpcId"] = 700069,
            },
        [51007908] = {
            ["Content"] = "你这项目靠谱吗……为什么我们一直在钻下水道。",
            ["ContentFR"] = "Tu es {性别:sûr|sûre} que ce trajet est fiable... Pourquoi on continue de s’enfoncer dans les égouts ?",
            ["DialogueId"] = 51007908,
            ["GUID"] = "7FB164E8",
            ["NextDialogue"] = 51007909,
            ["SpeakNpcId"] = 100001,
            },
        [51007909] = {
            ["Content"] = "那当然！卢卡的水上滑梯听过没，大伙顺着流水的管子从高处一路滑下来，别提多好玩多刺激了。",
            ["ContentFR"] = "Bien sûr que oui ! Tu connais les toboggans aquatiques de Luca ? Les gens glissent dans les tuyaux depuis le haut et finissent dans un grand bassin, en riant tout le long.",
            ["DialogueId"] = 51007909,
            ["GUID"] = "7FB16512",
            ["NextDialogue"] = 51007910,
            ["SpeakNpcId"] = 700191,
            },
        [51007910] = {
            ["Content"] = "虽然去卢卡一趟的钱，这城里大部分人一辈子都攒不出，但我这项目和“水上滑梯”一模一样，你不需要出冰湖城，就能体验到同样的快乐！",
            ["ContentFR"] = "Aller à Luca coûte plus que ce que la plupart des habitants de Givrelac gagnent en une vie, mais grâce à moi, tu peux vivre la même expérience sans quitter la cité !",
            ["DialogueId"] = 51007910,
            ["GUID"] = "7FB1653C",
            ["NextDialogue"] = 51007911,
            ["SpeakNpcId"] = 700191,
            },
        [51007911] = {
            ["Content"] = "便宜实惠安全有趣这些词，简直就是给它量身打造的。看，咱们帝国下水道这些管子，不是比卢卡那些破烂塑料货高级多了吗！",
            ["ContentFR"] = "Bon marché, sûr, amusant... ces mots ont été faits pour nous. Regarde ces tuyaux de l’Empire dans nos égouts, c’est bien mieux que le plastique pourri de Luca !",
            ["DialogueId"] = 51007911,
            ["GUID"] = "7FB16566",
            ["NextDialogue"] = 51007912,
            ["SpeakNpcId"] = 700191,
            },
        [51007912] = {
            ["Content"] = "（达顿说着拍了拍身旁的管道，一枚螺丝顿时崩飞了出去，他却仿佛没看到一般示意你赶紧钻进去。）",
            ["ContentFR"] = "Dutton tape sur un tuyau à côté de lui. Une vis se détache et vole, mais il semble ne pas la voir et te fait signe d’entrer.",
            ["DialogueId"] = 51007912,
            ["GUID"] = "7FB16590",
            ["NextOptions"] = {
                [1] = 51007913,
                },
            ["RestartTag"] = 51007912,
            },
        [51007913] = {
            ["Content"] = "我不太清楚应该怎么玩，不如你先给我示范一下吧。",
            ["ContentFR"] = "Je ne sais pas trop comment faire... Montre-moi d’abord.",
            ["DialogueId"] = 51007913,
            ["GUID"] = "7FB165BA",
            ["ImprCheckId"] = 1064,
            },
        [51007914] = {
            ["Content"] = "嗨呀没关系的，第一次玩总会有点紧张，但这不有我在嘛！我等你平复下心情，准备好了再找我就行。",
            ["ContentFR"] = "Pas de souci, la première fois ça peut être stressant. Prends ton temps et reviens quand tu es {性别:prêt|prête}.",
            ["DialogueId"] = 51007914,
            ["GUID"] = "7FB165E4",
            ["SpeakNpcId"] = 700191,
            },
        [51007915] = {
            ["Content"] = "好吧好吧，那我就来给你示范一下怎么玩，你之后也帮我去雾区跟大伙宣传宣传我这项目哈。",
            ["ContentFR"] = "Très bien, je vais te montrer comment ça se fait. Mais promets-moi de faire un peu de pub quand tu retourneras à Brumelac, d’accord ?",
            ["DialogueId"] = 51007915,
            ["GUID"] = "7FB1660E",
            ["NextDialogue"] = 51007916,
            ["SpeakNpcId"] = 700191,
            },
        [51007916] = {
            ["Content"] = "（达顿说完便钻进了管道，待金属被挤压的咯吱咯吱声完全停息，你听到达顿拍了拍管道的内壁对你说。）",
            ["ContentFR"] = "Dutton se glisse dans le tuyau. Le métal grince sous son poids. Il frappe la paroi et t’appelle.",
            ["DialogueId"] = 51007916,
            ["GUID"] = "7FB16638",
            ["NextDialogue"] = 51007917,
            },
        [51007917] = {
            ["Content"] = "哎呦你没先体验真是可惜了，我这管子里不仅擦得干净，还很香哩。行了，滑梯出口就在前面，我先滑过去了哈，回见！",
            ["ContentFR"] = "Dommage que tu ne sois pas passé en {性别:premier|première} ! Le tuyau est tout propre et ça sent bon. Allez, la sortie du toboggan est juste devant, je file ! À tout de suite !",
            ["DialogueId"] = 51007917,
            ["GUID"] = "7FB16662",
            ["SpeakNpcId"] = 700191,
            },
        [51007918] = {
            ["Content"] = "（咯吱作响的管道将附近的秽兽吸引了过来，待你清理完这些小麻烦后，达顿的声音从身旁的管道传来。）",
            ["ContentFR"] = "Le grincement du tuyau attire les Souillés à proximité. Une fois débarrassé des nuisibles, tu entends la voix de Dutton à travers le tuyau.",
            ["DialogueId"] = 51007918,
            ["GUID"] = "7FB1668C",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 51007919,
            },
        [51007919] = {
            ["Content"] = "太——好——玩——啦——我——们——终——点——见——",
            ["ContentFR"] = "C’est — trop — cool — on — se — retrouve — à — l’arrivée !",
            ["DialogueId"] = 51007919,
            ["GUID"] = "7FB166B6",
            ["SpeakNpcId"] = 700191,
            },
        [51007920] = {
            ["Content"] = "（终点除了一滩水什么也没有。趴在管道上仔细聆听，你能听到咯吱声还在不断地从终点前方传来。你知道，达顿滑过头了。）",
            ["ContentFR"] = "À la ligne d’arrivée, il n’y a qu’une flaque d’eau. En pressant ton oreille contre le tuyau, tu entends encore le grincement s’éloigner. Dutton a clairement dépassé la sortie.",
            ["DialogueId"] = 51007920,
            ["GUID"] = "7FB166E0",
            },
        [51007921] = {
            ["Content"] = "（一只又一只的秽兽被喷出了管道，拦住了你的去路。）",
            ["ContentFR"] = "Un à un, des Souillés sont projetés hors du tuyau, s’accumulant et bloquant ton passage.",
            ["DialogueId"] = 51007921,
            ["GUID"] = "7FB1670A",
            ["IsBlack"] = 1,
            },
        [51007922] = {
            ["Camera"] = "-143.335342,-546.682495,487.077148,0.000039,-45.799725,92.919357,15.353726,100000.0,false,Manual,22.0",
            ["Content"] = "唔——呃——呕——",
            ["ContentFR"] = "Argh... bleeeh !",
            ["DialogueId"] = 51007922,
            ["FinalCamera"] = "-60.066826,-542.436035,487.077148,0.000039,-45.799725,92.919357,15.353726,100000.0,false,Manual,22.0",
            ["GUID"] = "7FB16734",
            ["NextDialogue"] = 51007923,
            ["SpeakNpcId"] = 700191,
            ["TalkActionId"] = {
                [1] = "700191:Hurt01",
                },
            ["ToFinalCameraBlendTime"] = 8,
            ["TurnTo"] = {
                [1] = "100001:n(700191)",
                },
            },
        [51007923] = {
            ["Content"] = "（从错误出口喷出来的达顿面色苍白，趴在地上狂吐不止，显然“滑梯”颇为颠簸——这个“下水道滑梯”并没有他所说的那么安全有趣。）",
            ["ContentFR"] = "Pâle et affalé au sol, Dutton vomit sans cesse. Le toboggan des égouts n’était ni sûr ni amusant comme il le prétendait.",
            ["DialogueId"] = 51007923,
            ["GUID"] = "7FB1675E",
            ["NextOptions"] = {
                [1] = 51007924,
                [2] = 51007925,
                },
            },
        [51007924] = {
            ["Content"] = "你没事吧？",
            ["ContentFR"] = "<I>Ça va ?</>",
            ["DialogueId"] = 51007924,
            ["GUID"] = "7FB16788",
            ["ImprPlusId"] = 1002,
            ["NextDialogue"] = 51007926,
            },
        [51007925] = {
            ["Content"] = "我没看清，你能再滑一次吗？",
            ["ContentFR"] = "<I>Je n’ai pas bien vu, tu peux me montrer encore une fois ?</>",
            ["DialogueId"] = 51007925,
            ["GUID"] = "7FB167B2",
            ["ImprPlusId"] = 1005,
            ["NextDialogue"] = 51007926,
            },
        [51007926] = {
            ["Camera"] = "-310.433411,-170.472031,157.965942,0.000161,-12.197788,12.9158,15.353726,100000.0,false,Manual,22.0",
            ["Content"] = "呼……呼……",
            ["ContentFR"] = "Haa... haa...",
            ["DialogueId"] = 51007926,
            ["GUID"] = "7FB167DC",
            ["NextDialogue"] = 51007927,
            ["SpeakNpcId"] = 700191,
            },
        [51007927] = {
            ["Content"] = "不行了，我得，休息一下……答应你的奖励，给……我先走了……",
            ["ContentFR"] = "Je ne peux plus... je dois... me reposer... Ta récompense... je te la donne... je m’en vais...",
            ["DialogueId"] = 51007927,
            ["GUID"] = "7FB16806",
            ["NextDialogue"] = 51007928,
            ["SpeakNpcId"] = 700191,
            ["TalkActionId"] = {
                [1] = "700191:Sigh_Start",
                },
            },
        [51007928] = {
            ["Camera"] = "-125.646004,-486.612549,465.015015,-0.001072,-47.41058,90.325813,15.353726,100000.0,false,Manual,22.0",
            ["Content"] = "唉……到底怎么才能搞出便宜好玩，雾区人也能玩得起的游乐设施呢……",
            ["ContentFR"] = "<I>Soupir...</> Des attractions pas chères et amusantes pour les habitants de Brumelac... faut que je trouve un moyen...",
            ["DialogueId"] = 51007928,
            ["GUID"] = "7FB16830",
            ["NextDialogue"] = 51007929,
            ["SpeakNpcId"] = 700191,
            },
        [51007929] = {
            ["Content"] = "（达顿递给你一个小包裹，然后捂着胸口头也不回地离开了下水道——显然，他不会再回到这个令他伤心的地方了。）",
            ["ContentFR"] = "Dutton te tend un petit paquet puis quitte les égouts en se tenant la poitrine, il ne reviendra plus dans ce lieu décevant.",
            ["DialogueId"] = 51007929,
            ["GUID"] = "7FB1685A",
            ["IsBlack"] = 1,
            },
        [51007930] = {
            ["Content"] = "雾区什么娱乐项目都没有，肯定还有潜在的商机，让我再好好想想……",
            ["ContentFR"] = "Brumelac n’a aucune attraction. Il doit bien y avoir un marché inexploité quelque part. Je trouverai la solution... tôt ou tard...",
            ["DialogueId"] = 51007930,
            ["GUID"] = "7FB16884",
            ["SpeakNpcId"] = 700191,
            },
        [51008001] = {
            ["Content"] = "走，走开……不买月石的话就赶紧走……别把那群当兵的引来了……",
            ["ContentFR"] = "Va... va-t’en... si tu n’achètes pas de Phoxène, ne reste pas ici... et n’attire pas ces foutus soldats sur moi...",
            ["DialogueId"] = 51008001,
            ["GUID"] = "7FB1742A",
            ["NextDialogue"] = 51008002,
            ["SpeakNpcId"] = 700113,
            },
        [51008002] = {
            ["Content"] = "（男人瑟缩在角落，与他健硕的体格所给人的印象相去甚远。他的眼神躲闪，渴望将身旁的月石脱手，却迟疑着要不要向他人寻求帮助。）",
            ["ContentFR"] = "L’homme, pourtant bâti comme un colosse, se recroqueville dans un coin. Son regard fuyant trahit sa nervosité. À ses côtés, un sac rempli de Phoxènes qu’il semble vouloir vendre à tout prix... mais il hésite encore à demander de l’aide.",
            ["DialogueId"] = 51008002,
            ["GUID"] = "7FB17454",
            ["NextOptions"] = {
                [1] = 51008003,
                [2] = 51008004,
                [3] = 51008005,
                [4] = 51008007,
                },
            },
        [51008003] = {
            ["Content"] = "我虽然不买，但分我一半报酬的话，可以帮你找找买家。",
            ["ContentFR"] = "Je n’achète pas, mais si on partage la récompense à parts égales, je peux t’aider à trouver un acheteur.",
            ["DialogueId"] = 51008003,
            ["GUID"] = "7FB1747E",
            ["ImprPlusId"] = 1001,
            ["NextDialogue"] = 51008009,
            },
        [51008004] = {
            ["Content"] = "你需要什么帮助吗？",
            ["ContentFR"] = "Tu as besoin d’aide ?",
            ["DialogueId"] = 51008004,
            ["GUID"] = "7FB174A8",
            ["ImprPlusId"] = 1004,
            ["NextDialogue"] = 51008009,
            },
        [51008005] = {
            ["Content"] = "帝国肯定不会允许你干这种事，不想惹麻烦的话就快走吧。",
            ["ContentFR"] = "L’Empire ne tolère pas ce genre de trafic. Si tu veux éviter les ennuis, pars vite.",
            ["DialogueId"] = 51008005,
            ["GUID"] = "7FB174D2",
            ["ImprPlusId"] = 1002,
            ["NextDialogue"] = 51008006,
            },
        [51008006] = {
            ["Content"] = "您高抬贵手，把我当个屁放了吧，我只要把这批月石卖掉就立马离开冰湖城，绝不回来。",
            ["ContentFR"] = "Ayez pitié... Faites comme si je n’existais pas... Dès que j’ai vendu ce Phoxène, je quitte Givrelac pour de bon, je le jure !",
            ["DialogueId"] = 51008006,
            ["GUID"] = "7FB174FC",
            ["NextDialogue"] = 51008009,
            ["SpeakNpcId"] = 700113,
            },
        [51008007] = {
            ["Content"] = "咳！军团的士兵委托我盘查你，赶紧把通行证拿出来！",
            ["ContentFR"] = "Hum ! La Légion m’a chargé de contrôler les gens comme toi. Montre-moi ton permis de circulation, tout de suite !",
            ["DialogueId"] = 51008007,
            ["GUID"] = "7FB17526",
            ["ImprPlusId"] = 1005,
            ["NextDialogue"] = 51008008,
            },
        [51008008] = {
            ["Content"] = "（男人听罢提起袋子就要跑，好不容易向他说明玩笑并解释身份后，他才悄声说明了自己的难处。）",
            ["ContentFR"] = "À ces mots, l’homme agrippe son sac et s’enfuit. Tu parviens à l’arrêter de justesse et, après lui avoir expliqué qu’il s’agissait d’une plaisanterie, il t’avoue à voix basse ses véritables difficultés.",
            ["DialogueId"] = 51008008,
            ["GUID"] = "7FB17550",
            ["NextDialogue"] = 51008009,
            ["SpeakNpcId"] = 700113,
            },
        [51008009] = {
            ["Content"] = "只要你帮我找个买家，报酬分你七成，不，八成！拜托了，拜托！",
            ["ContentFR"] = "Trouve-moi un acheteur et je te laisse 70 %... Non, 80 % ! Je t’en supplie, aide-moi !",
            ["DialogueId"] = 51008009,
            ["GUID"] = "7FB1757A",
            ["SpeakNpcId"] = 700113,
            },
        [51008010] = {
            ["Content"] = "（虽说答应了男人的委托，但他的神色和袋子上干涸的暗红色痕迹都宣告着这批月石的来路并不单纯。）",
            ["ContentFR"] = "Tu acceptes sa requête, mais son attitude nerveuse et les traces rouge sombre séchées sur son sac ne laissent guère de doute : cette cargaison de Phoxène n’a pas une origine très nette.",
            ["DialogueId"] = 51008010,
            ["GUID"] = "7FB175A4",
            ["NextDialogue"] = 51008011,
            },
        [51008011] = {
            ["Content"] = "（贸然寻找买主也许会招来麻烦，也许，先确认一下这批月石的来历会更好？）",
            ["ContentFR"] = "Peut-être vaudrait-il mieux, avant de chercher un acheteur, s’assurer de la provenance du Phoxène ?",
            ["DialogueId"] = 51008011,
            ["GUID"] = "7FB175CE",
            },
        [51008012] = {
            ["Content"] = "（这片草丛刚刚是不是有什么东西闪了一下？）",
            ["ContentFR"] = "Un éclat lumineux vient de traverser les fourrés... Était-ce ton imagination ?",
            ["DialogueId"] = 51008012,
            ["GUID"] = "7FB175F8",
            ["NextOptions"] = {
                [1] = 51008053,
                },
            },
        [51008013] = {
            ["Content"] = "（你翻了翻草丛，什么都没找到。也许刚才只是眼花了吧。）",
            ["ContentFR"] = "Tu fouilles, mais ne trouves rien. Sans doute un simple reflet...",
            ["DialogueId"] = 51008013,
            ["GUID"] = "7FB17622",
            },
        [51008014] = {
            ["Content"] = "（你翻了翻草丛，果然找到了一颗散发着微弱光亮的石头——月石。只是，月石上同样沾着暗红色的血迹，和男人袋子上的暗红痕迹一模一样。）",
            ["ContentFR"] = "Tu écartes les herbes et découvres un éclat de Phoxène luisant faiblement. Lui aussi est maculé de sang séché, identique aux taches sur le sac de Larry.",
            ["DialogueId"] = 51008014,
            ["GUID"] = "7FB1764C",
            ["NextDialogue"] = 51008015,
            },
        [51008015] = {
            ["Content"] = "我可不觉得今天是什么运气好到足够随地捡月石的日子。更何况这种带着一抹血迹的月石可不常见……",
            ["ContentFR"] = "Ce n’est vraiment pas le genre de jour où le Phoxène tomberait du ciel... Et encore moins quand il est couvert de sang. Quelque chose ne va pas.",
            ["DialogueId"] = 51008015,
            ["GUID"] = "7FB17676",
            ["NextDialogue"] = 51008016,
            ["SpeakNpcId"] = 100001,
            },
        [51008016] = {
            ["Content"] = "吼——",
            ["ContentFR"] = "Grrrraaaah !",
            ["DialogueId"] = 51008016,
            ["GUID"] = "7FB176A0",
            ["NextDialogue"] = 51008017,
            },
        [51008017] = {
            ["Content"] = "先清理掉碍事的秽兽吧……",
            ["ContentFR"] = "Mieux vaut d’abord s’occuper de ces Souillés...",
            ["DialogueId"] = 51008017,
            ["GUID"] = "7FB176CA",
            ["SpeakNpcId"] = 100001,
            },
        [51008018] = {
            ["Content"] = "（一片凌乱的残渣碎屑，是冰湖的碎石、折断的树枝、些许瓦砾碎片。看这个凌乱程度，这里想必经历过一场打斗。）",
            ["ContentFR"] = "Des débris jonchent le sol : gravats provenant du lac, branches brisées, éclats de pierre. Tout indique qu’un affrontement a eu lieu ici.",
            ["DialogueId"] = 51008018,
            ["GUID"] = "7FB176F4",
            ["NextDialogue"] = 51008019,
            },
        [51008019] = {
            ["Content"] = "（残渣中夹杂着撕下来的劣质布料和棉絮，这些布料似乎和那个寻找买主的男人身上穿的衣物类似。）",
            ["ContentFR"] = "Éparpillés parmi les débris gisent des morceaux de tissu rêche et du rembourrage effiloché, exactement les mêmes que ceux qui composaient les vêtements de cet homme.",
            ["DialogueId"] = 51008019,
            ["GUID"] = "7FB1771E",
            },
        [51008020] = {
            ["Content"] = "（翻开那些碎屑，你又发现了一小块染血的月石。）",
            ["ContentFR"] = "En fouillant les débris, tu découvres un autre petit éclat de Phoxène, maculé de sang séché.",
            ["DialogueId"] = 51008020,
            ["GUID"] = "7FB17748",
            },
        [51008021] = {
            ["Content"] = "（周围的脚印杂乱无章，但却并没有秽兽或野兽的蹄印，只有人类的脚印。）",
            ["ContentFR"] = "Les empreintes sont nombreuses et désordonnées... mais aucune trace de bête ou de Souillé. Rien que des pas humains.",
            ["DialogueId"] = 51008021,
            ["GUID"] = "7FB17772",
            },
        [51008022] = {
            ["Content"] = "（一道重物被拖行的痕迹绵延至远处。）",
            ["ContentFR"] = "Une longue marque dans la terre laisse deviner qu’un objet lourd a été traîné sur une longue distance.",
            ["DialogueId"] = 51008022,
            ["GUID"] = "7FB1779C",
            ["NextDialogue"] = 51008023,
            },
        [51008023] = {
            ["Content"] = "嗯……我想，我大概能猜到这里发生过什么了。月石上血迹的来源是：",
            ["ContentFR"] = "Hmm... Je crois deviner ce qui s’est passé. Le sang sur le Phoxène vient :",
            ["DialogueId"] = 51008023,
            ["GUID"] = "7FB177C6",
            ["NextOptions"] = {
                [1] = 51008024,
                [2] = 51008026,
                [3] = 51008028,
                },
            ["SpeakNpcId"] = 100001,
            },
        [51008024] = {
            ["Content"] = "人类",
            ["ContentFR"] = "<I>Des humains.</>",
            ["DialogueId"] = 51008024,
            ["GUID"] = "7FB177F0",
            ["NextDialogue"] = 51008025,
            },
        [51008025] = {
            ["Content"] = "（是的，这里并没有秽兽和野兽来过。）",
            ["ContentFR"] = "<I>Exact. Aucune trace de bêtes ni de Souillés.</>",
            ["DialogueId"] = 51008025,
            ["GUID"] = "7FB1781A",
            ["NextDialogue"] = 51008030,
            },
        [51008026] = {
            ["Content"] = "野兽",
            ["ContentFR"] = "<I>Des bêtes.</>",
            ["DialogueId"] = 51008026,
            ["GUID"] = "7FB17844",
            ["NextDialogue"] = 51008027,
            },
        [51008027] = {
            ["Content"] = "（不对，如果有野兽来过，这里应该会留有野兽的蹄印。）",
            ["ContentFR"] = "<I>Non... il y aurait des empreintes de pattes ou de griffes.</>",
            ["DialogueId"] = 51008027,
            ["GUID"] = "7FB1786E",
            ["NextDialogue"] = 51008030,
            },
        [51008028] = {
            ["Content"] = "秽兽",
            ["ContentFR"] = "<I>Des Souillés.</>",
            ["DialogueId"] = 51008028,
            ["GUID"] = "7FB17898",
            ["NextDialogue"] = 51008029,
            },
        [51008029] = {
            ["Content"] = "（不对，如果有秽兽来过，这里应该会留有秽兽的蹄印。）",
            ["ContentFR"] = "<I>Non... leurs traces auraient lacéré le sol.</>",
            ["DialogueId"] = 51008029,
            ["GUID"] = "7FB178C2",
            ["NextDialogue"] = 51008030,
            },
        [51008030] = {
            ["Content"] = "（是有人在这里袭击了其他人，也许就是为了……抢走那一小袋月石。接下来怎么办呢……）",
            ["ContentFR"] = "<I>Il y a eu une attaque ici... quelqu’un a tué pour s’emparer de ce sac de Phoxène. Reste à décider quoi faire maintenant.</>",
            ["DialogueId"] = 51008030,
            ["GUID"] = "7FB178EC",
            ["SpeakNpcId"] = 100001,
            ["TalkOptions"] = {
                [1] = 51008031,
                [2] = 51008032,
                },
            },
        [51008031] = {
            ["Content"] = "那个人的月石来路不正，不如吞下这笔不义之财。",
            ["ContentFR"] = "<I>Le Phoxène est taché de sang... mais après tout, autant en tirer profit moi-même.</>",
            ["DialogueId"] = 51008031,
            ["GUID"] = "7FB17916",
            ["ImprPlusId"] = 1005,
            },
        [51008032] = {
            ["Content"] = "那个人做了恶事，去找卫戍部队举报他吧。",
            ["ContentFR"] = "<I>Ce type a fait des choses graves... je ferais mieux d’en informer les Veilleurs.</>",
            ["DialogueId"] = 51008032,
            ["GUID"] = "7FB17940",
            ["ImprPlusId"] = 1002,
            },
        [51008033] = {
            ["Content"] = "你干了什么见不得人的事吧？",
            ["ContentFR"] = "Tu as fait quelque chose dont tu n’es pas fier, pas vrai ?",
            ["DialogueId"] = 51008033,
            ["GUID"] = "7FB1796A",
            ["NextDialogue"] = 51008034,
            ["SpeakNpcId"] = 100001,
            },
        [51008034] = {
            ["Content"] = "这枚月石你可能未必会有印象，但它一定记得你。它上面沾染的血迹的主人也永远不会忘了你的。",
            ["ContentFR"] = "Ce Phoxène... peut-être que toi, tu as oublié. Mais lui, il se souvient. Et le sang qui l’a taché aussi.",
            ["DialogueId"] = 51008034,
            ["GUID"] = "7FB17994",
            ["NextDialogue"] = 51008035,
            ["SpeakNpcId"] = 100001,
            },
        [51008035] = {
            ["Content"] = "我……我听不懂你在说什么！",
            ["ContentFR"] = "Je... je ne comprends pas ce que tu racontes !",
            ["DialogueId"] = 51008035,
            ["GUID"] = "7FB179BE",
            ["NextDialogue"] = 51008036,
            ["SpeakNpcId"] = 700113,
            },
        [51008036] = {
            ["Content"] = "不用你帮忙了，什么月石，我听不懂！",
            ["ContentFR"] = "Je n’ai jamais eu besoin de ton aide ! Pars !",
            ["DialogueId"] = 51008036,
            ["GUID"] = "7FB179E8",
            ["NextDialogue"] = 51008037,
            ["SpeakNpcId"] = 700113,
            },
        [51008037] = {
            ["Content"] = "没必要这样，卫戍部队马上就要到了。不过，我倒是有个法子可以帮你——前提是，这袋月石归我。",
            ["ContentFR"] = "Inutile de nier. Les Veilleurs ne vont pas tarder à arriver... Mais j’ai un moyen de détourner leur attention, à une condition : ton sac de Phoxène.",
            ["DialogueId"] = 51008037,
            ["GUID"] = "7FB17A12",
            ["NextDialogue"] = 51008038,
            ["SpeakNpcId"] = 100001,
            },
        [51008038] = {
            ["Content"] = "我……你……",
            ["ContentFR"] = "Je... tu...",
            ["DialogueId"] = 51008038,
            ["GUID"] = "7FB17A3C",
            ["NextDialogue"] = 51008039,
            ["SpeakNpcId"] = 700113,
            },
        [51008039] = {
            ["Content"] = "当然，你也可以选择跟他们走，这完全是你的自由。",
            ["ContentFR"] = "Évidemment, tu peux aussi rester ici et les attendre. C’est ton choix.",
            ["DialogueId"] = 51008039,
            ["GUID"] = "7FB17A66",
            ["NextDialogue"] = 51008040,
            ["SpeakNpcId"] = 100001,
            },
        [51008040] = {
            ["Content"] = "我可以在这里等你做选择， 但卫戍部队大概不会等你。在你犹豫这会儿的时间里，他们大概就要到喽。",
            ["ContentFR"] = "Je peux t’attendre ici pendant que tu décides, mais les Veilleurs ne t’attendront probablement pas. Pendant que tu hésites, ils seront sans doute déjà en chemin.",
            ["DialogueId"] = 51008040,
            ["GUID"] = "7FB17A90",
            ["NextDialogue"] = 51008041,
            ["SpeakNpcId"] = 100001,
            },
        [51008041] = {
            ["Content"] = "我给你！我全都给你还不行么！",
            ["ContentFR"] = "D’accord ! Prends-les ! Tout le Phoxène est à toi !",
            ["DialogueId"] = 51008041,
            ["GUID"] = "7FB17ABA",
            ["NextDialogue"] = 51008042,
            ["SpeakNpcId"] = 700113,
            },
        [51008042] = {
            ["Content"] = "就是这袋该死的月石！如果不是偶然发现它，我的兄弟们应该都还活着的！我们现在应该已经快要休息了……",
            ["ContentFR"] = "Ce maudit sac de Phoxène... Si je ne l’avais jamais trouvé, mes camarades seraient encore en vie...",
            ["DialogueId"] = 51008042,
            ["GUID"] = "7FB17AE4",
            ["NextDialogue"] = 51008043,
            ["SpeakNpcId"] = 700113,
            },
        [51008043] = {
            ["Content"] = "不不……我们今天的收获比往常还要好一点，没准今晚还能一起去一次水仙平原，每个人都能来上一杯满满的麦芽酒！",
            ["ContentFR"] = "Non, non... aujourd’hui, notre récolte a été meilleure que d’habitude. Ce soir, on aurait peut-être même pu retourner une fois aux Asphodèles, et chacun aurait levé une grande chope de bière maltée !",
            ["DialogueId"] = 51008043,
            ["GUID"] = "7FB17B0E",
            ["NextDialogue"] = 51008044,
            ["SpeakNpcId"] = 700113,
            },
        [51008044] = {
            ["Content"] = "我们可以一醉方休，可以吹牛到半夜，明早再一起……",
            ["ContentFR"] = "On aurait bu jusqu’à plus soif... on aurait fanfaronné jusqu’au milieu de la nuit... et demain matin, ensemble, on aurait encore...",
            ["DialogueId"] = 51008044,
            ["GUID"] = "7FB17B38",
            ["NextDialogue"] = 51008045,
            ["SpeakNpcId"] = 700113,
            },
        [51008045] = {
            ["Content"] = "我……我不能给你！",
            ["ContentFR"] = "Non... je ne peux pas te les donner !",
            ["DialogueId"] = 51008045,
            ["GUID"] = "7FB17B62",
            ["SpeakNpcId"] = 700113,
            },
        [51008046] = {
            ["Camera"] = "-607.952148,-441.947266,565.15332,0.000023,-34.799801,23.996548,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "你骗我！根本就没有什么卫戍部队，你就是想吞掉我这月石罢了！",
            ["ContentFR"] = "Tu m’as trompé ! Il n’y a pas de Veilleurs, tu voulais juste voler mon Phoxène !",
            ["DialogueId"] = 51008046,
            ["GUID"] = "7FB17B8C",
            ["NextDialogue"] = 51008047,
            ["SpeakNpcId"] = 700113,
            },
        [51008047] = {
            ["Content"] = "你就是用它砸死了你的朋友——像刚才袭击我那样？",
            ["ContentFR"] = "Tu as tué tes propres camarades pour ces pierres, n’est-ce pas ? Comme tu as tenté de m’abattre.",
            ["DialogueId"] = 51008047,
            ["GUID"] = "7FB17BB6",
            ["NextDialogue"] = 51008048,
            ["SpeakNpcId"] = 100001,
            },
        [51008048] = {
            ["Content"] = "是他们先动手的……我，我这都是正当防卫！",
            ["ContentFR"] = "C’est eux qui ont attaqué les premiers... J’ai juste voulu me défendre !",
            ["DialogueId"] = 51008048,
            ["GUID"] = "7FB17BE0",
            ["NextDialogue"] = 51008049,
            ["SpeakNpcId"] = 700113,
            },
        [51008049] = {
            ["Content"] = "还有你……你想贪下这包月石，你、又是什么好东西？还教训起我来了？",
            ["ContentFR"] = "Et toi ? Tu ne vaux pas mieux que moi ! Tu veux ces pierres, toi aussi ! Et tu essaies de me faire la morale ?",
            ["DialogueId"] = 51008049,
            ["GUID"] = "7FB17C0A",
            ["NextOptions"] = {
                [1] = 51008050,
                [2] = 51008051,
                },
            ["SpeakNpcId"] = 700113,
            },
        [51008050] = {
            ["Content"] = "成年人应该为犯下的错付出代价，这包月石给你长点记性。",
            ["ContentFR"] = "<I>Les adultes doivent assumer leurs fautes. Ce sac de Phoxène sera ta leçon.</>",
            ["DialogueId"] = 51008050,
            ["GUID"] = "7FB17C34",
            ["ImprPlusId"] = 1001,
            ["NextDialogue"] = 51008052,
            },
        [51008051] = {
            ["Content"] = "我不是什么好人，你自然也不是。但我至少愿意给你留一条命，滚吧。",
            ["ContentFR"] = "<I>Je ne suis pas {性别:un saint|une sainte}, et toi non plus. Mais je t’épargne la vie. File.</>",
            ["DialogueId"] = 51008051,
            ["GUID"] = "7FB17C5E",
            ["ImprPlusId"] = 1005,
            ["NextDialogue"] = 51008052,
            },
        [51008052] = {
            ["Content"] = "（手里染血的月石沉甸甸的。它是如此沉重，仿佛要变成一个怪物，把所有的“拉里”都吃掉。）",
            ["ContentFR"] = "Le Phoxène ensanglanté pèse lourd dans ta main. Bien plus qu’une pierre. On croirait qu’il palpite, prêt à engloutir le prochain \"Larry\" qui s’en approchera.",
            ["DialogueId"] = 51008052,
            ["GUID"] = "7FB17C88",
            ["IsBlack"] = 1,
            },
        [51008053] = {
            ["Content"] = "低头翻找一下看看",
            ["ContentFR"] = "Fouiller les herbes",
            ["DialogueId"] = 51008053,
            ["GUID"] = "7FB17CB2",
            ["ImprCheckId"] = 1070,
            },
        [51008054] = {
            ["Content"] = "（清理掉这群碍眼的秽兽后，附近的地面上某些似乎被掩埋过的痕迹暴露了出来。你决定去检查一下这些新的线索。）",
            ["ContentFR"] = "Après avoir éliminé les Souillés, tu remarques des traces étranges dans le sol. Tu décides d’enquêter sur ces traces.",
            ["DialogueId"] = 51008054,
            ["GUID"] = "7FB17CDC",
            },
        [51009001] = {
            ["Camera"] = "-758.908325,369.843262,211.244629,0.000082,-6.598509,-20.974316,35.000011,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "新剧上映，新剧上映！那边的年轻人，要不要来体验一下？",
            ["ContentFR"] = "Une nouvelle pièce ! Une toute nouvelle pièce ! Hé, toi là-bas, ça te tente ?",
            ["DialogueId"] = 51009001,
            ["GUID"] = "7FB2183A",
            ["LookAt"] = {
                [1] = "700240:n(100001)",
                },
            ["NextDialogue"] = 51009002,
            ["SpeakNpcId"] = 700240,
            },
        [51009002] = {
            ["Content"] = "叫我吗？",
            ["ContentFR"] = "Moi ?",
            ["DialogueId"] = 51009002,
            ["GUID"] = "7FB21864",
            ["NextDialogue"] = 51009003,
            ["SpeakNpcId"] = 100001,
            },
        [51009003] = {
            ["Content"] = "是的是的，盖雷亚剧院正在试演一种全新的戏剧——沉浸式戏剧！",
            ["ContentFR"] = "Oui ! Le Théâtre Galea lance un tout nouveau concept : le théâtre immersif !",
            ["DialogueId"] = 51009003,
            ["GUID"] = "7FB2188E",
            ["NextDialogue"] = 51009004,
            ["SpeakNpcId"] = 700240,
            },
        [51009004] = {
            ["Camera"] = "-758.908325,369.843262,211.244629,0.000082,-6.598509,-20.974316,35.000011,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "这是来自卢卡的全新演绎形式！你不会再像过去一样被按在观众席上，而是可以自己选择去哪儿，甚至自己成为故事的一部分……",
            ["ContentFR"] = "C’est une toute nouvelle forme de spectacle venue de Luca ! Fini le temps où tu restais coincé sur ton siège... Ici, tu choisis où aller, et tu peux même devenir une partie de l’histoire !",
            ["DialogueId"] = 51009004,
            ["GUID"] = "7FB218B8",
            ["NextDialogue"] = 51009005,
            ["SpeakNpcId"] = 700240,
            ["TalkActionId"] = {
                [1] = "700240:Explain02_Start",
                },
            },
        [51009005] = {
            ["Content"] = "我们需要志愿者来完成这场伟大的艺术实验！现在正在上映的是一场英雄冒险故事，你要来参加吗？我们准备了特别的礼物相赠！",
            ["ContentFR"] = "Nous recherchons des volontaires pour donner vie à cette grande expérience artistique ! L’histoire en cours est une véritable épopée héroïque. Veux-tu y prendre part ? Un cadeau spécial attend chaque participant !",
            ["DialogueId"] = 51009005,
            ["GUID"] = "7FB218E2",
            ["SpeakNpcId"] = 700240,
            ["TalkActionId"] = {
                [1] = "700240:Explain02_End",
                },
            },
        [51009006] = {
            ["Camera"] = "-758.908325,369.843262,211.244629,0.000082,-6.598509,-20.974316,35.000011,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "好，请跟我来！",
            ["ContentFR"] = "Parfait ! Suis-moi, je vais tout t’expliquer !",
            ["DialogueId"] = 51009006,
            ["GUID"] = "7FB2190C",
            ["LookAt"] = {
                [1] = "700240:n(100001)",
                },
            ["SpeakNpcId"] = 700240,
            ["TalkActionId"] = {
                [1] = "700240:Explain01_Start",
                },
            },
        [51009007] = {
            ["Camera"] = "-758.908325,369.843262,211.244629,0.000082,-6.598509,-20.974316,35.000011,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "好吧，等你有兴趣了再来找我就好！",
            ["ContentFR"] = "Très bien. Reviens me voir quand tu auras l’envie, tu seras toujours {性别:le|la} bienvenu !",
            ["DialogueId"] = 51009007,
            ["GUID"] = "7FB21936",
            ["LookAt"] = {
                [1] = "700240:n(100001)",
                },
            ["SpeakNpcId"] = 700240,
            ["TalkActionId"] = {
                [1] = "700240:Agree",
                },
            },
        }
  end },
