                },
            ["NextDialogue"] = 51009109,
            ["SpeakNpcId"] = 230002,
            },
        [51009109] = {
            ["Content"] = "你的那把剑给了老朽不少灵感，这就给你露一手吧。",
            ["ContentFR"] = "Dein Schwert hat mich richtig inspiriert. Ich zeig dir, was diese Hände noch draufhaben.",
            ["DialogueId"] = 51009109,
            ["FacialId"] = {
                [1] = "230002:Confident02",
                },
            ["GUID"] = "7FB229F2",
            ["SpeakNpcId"] = 230002,
            ["TalkActionId"] = {
                [1] = "100001:Think_End",
                },
            },
        [51009110] = {
            ["Camera"] = "8.336334,-29.466553,77.175323,0.000124,7.39872,94.000053,35.000011,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "完成了！",
            ["ContentFR"] = "Fertig.",
            ["DialogueId"] = 51009110,
            ["FacialId"] = {
                [1] = "230002:Happy02",
                },
            ["FinalCamera"] = "2.849762,-30.109863,88.122185,0.000128,-1.001312,89.199585,35.000011,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "7FB22A1C",
            ["LookAt"] = {
                [1] = "100001:n(230002)",
                [2] = "230001:n(230002)",
                },
            ["NextDialogue"] = 51009111,
            ["Scripts"] = "PlayOrStopBGM{PlayType{\"Play\"},SoundPriority{\"StoryCustom\"},SoundType{\"SOUND_BGM\"},SoundUnitKey{\"sidestory_tiejiangjiaojiao\"},EventPath{\"event:/bgm/cbt02/0041_story_jiaojiao_tiejiang\"}}",
            ["SpeakNpcId"] = 230002,
            ["ToFinalCameraBlendTime"] = 10,
            },
        [51009111] = {
            ["Camera"] = "-109.266235,212.040771,142.030579,0.000303,-12.201387,-63.418461,35.000011,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "哇——铁匠前辈，好厉害！",
            ["ContentFR"] = "Wow! Das war unglaublich!",
            ["DialogueId"] = 51009111,
            ["FacialId"] = {
                [1] = "230001:Smile02",
                },
            ["GUID"] = "7FB22A46",
            ["NextOptions"] = {
                [1] = 510091111,
                [2] = 510091112,
                },
            ["SpeakNpcId"] = 230001,
            ["TalkActionId"] = {
                [1] = "230001:Shock03_Start",
                },
            },
        [51009112] = {
            ["Camera"] = "-98.319763,-208.091797,193.145508,0.000145,-22.401394,63.002728,35.000011,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "放心吧，这次是特别服务。",
            ["ContentFR"] = "Was für eine schöne Waffe. Darf ich sie ausprobieren?",
            ["DialogueId"] = 51009112,
            ["GUID"] = "7FB22A70",
            ["LookAt"] = {
                [1] = "230002:n(100001)",
                },
            ["NextDialogue"] = 51009114,
            ["SpeakNpcId"] = 230002,
            ["TalkActionId"] = {
                [1] = "230001:Shock03_End",
                },
            },
        [51009113] = {
            ["Camera"] = "-98.319763,-208.091797,193.145508,0.000145,-22.401394,63.002728,35.000011,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "当然，这就是专门为你打造的。",
            ["ContentFR"] = "Natürlich. Sie wurde schließlich für dich geschmiedet.",
            ["DialogueId"] = 51009113,
            ["GUID"] = "7FB22A9A",
            ["LookAt"] = {
                [1] = "230002:n(100001)",
                },
            ["NextDialogue"] = 51009114,
            ["SpeakNpcId"] = 100001,
            },
        [51009114] = {
            ["Camera"] = "-24.090881,-40.348145,106.749283,0.00021,-8.600826,75.590508,35.000011,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "虽然还比不上你原本的剑，但也算是老朽的得意之作了。",
            ["ContentFR"] = "Sie mag deinem alten Schwert nicht das Wasser reichen, aber ich würde sagen, sie gehört zu meinen besten Arbeiten.",
            ["DialogueId"] = 51009114,
            ["FacialId"] = {
                [1] = "230002:Confident02",
                },
            ["GUID"] = "7FB22AC4",
            ["NextDialogue"] = 51009115,
            ["SpeakNpcId"] = 230002,
            },
        [51009115] = {
            ["Camera"] = "-45.129822,68.886719,129.014465,0.000222,1.198575,-71.808838,35.000011,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "谢谢前辈，不过为什么突然会为我锻造这个？我已经……",
            ["ContentFR"] = "Danke. Aber warum machst du dir so viel Mühe für mich? Ich hab doch schon ...",
            ["DialogueId"] = 51009115,
            ["FacialId"] = {
                [1] = "100001:Shy",
                },
            ["GUID"] = "7FB22AEE",
            ["NextDialogue"] = 51009116,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Explain02_Start",
                },
            },
        [51009116] = {
            ["Camera"] = "-47.538391,-157.203125,145.923813,0.00021,-15.601462,76.384178,35.000011,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "武器是每个踏上旅途的年轻人最重要的伙伴，当然要做到有备无患。",
            ["ContentFR"] = "Eine Waffe ist der treueste Gefährte eines jungen Abenteurers. Du solltest niemals unvorbereitet sein.",
            ["DialogueId"] = 51009116,
            ["FacialId"] = {
                [1] = "230002:Happy02",
                },
            ["GUID"] = "7FB22B18",
            ["NextDialogue"] = 51009117,
            ["SpeakNpcId"] = 230002,
            ["TalkActionId"] = {
                [1] = "100001:Explain02_End",
                },
            },
        [51009117] = {
            ["Content"] = "老朽见过太多和你一样的年轻人，不管默默无闻，还是成为了阿特拉西亚的传奇，最开始也都只是些带着好奇心和鲁莽的毛头小子。",
            ["ContentFR"] = "Ich habe mehr junge Leute wie dich gesehen, als ich zählen kann. Manche sind in Vergessenheit geraten, andere wurden zu Legenden von Atlasia. Aber alle begannen gleich: neugierig, ungestüm, voller Feuer und mit viel zu wenig Vorsicht.",
            ["DialogueId"] = 51009117,
            ["FacialId"] = {
                [1] = "230002:Ahaha02",
                },
            ["GUID"] = "7FB22B42",
            ["NextDialogue"] = 51009118,
            ["SpeakNpcId"] = 230002,
            },
        [51009118] = {
            ["Content"] = "一把可靠的武器，正是补足毛躁和稚嫩的良药。",
            ["ContentFR"] = "Deshalb ist eine verlässliche Waffe wichtig. Sie zügelt die Hitze der Jugend und stabilisiert Hände, die noch nicht durch die Zeit geprüft sind.",
            ["DialogueId"] = 51009118,
            ["FacialId"] = {
                [1] = "230002:Satisfy01",
                },
            ["GUID"] = "7FB22B6C",
            ["NextDialogue"] = 51009119,
            ["SpeakNpcId"] = 230002,
            },
        [51009119] = {
            ["Camera"] = "-11.187744,-30.125488,113.694717,0.000209,-16.401381,81.782051,35.000011,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "虽然你可能不那么需要，就算是当备用品也好，这把武器就交给你了，就当是老朽对年轻人的一句忠告吧。",
            ["ContentFR"] = "Vielleicht brauchst du sie jetzt nicht, aber behalt sie als Ersatz. Sieh es als Rat einer alten Schmiedin.",
            ["DialogueId"] = 51009119,
            ["GUID"] = "7FB22B96",
            ["NextDialogue"] = 51009120,
            ["SpeakNpcId"] = 230002,
            },
        [51009120] = {
            ["Camera"] = "-36.630005,38.096924,125.536903,0.000215,5.798011,-71.413826,35.000011,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "前辈……",
            ["ContentFR"] = "Ich ... Ich werde. Danke.",
            ["DialogueId"] = 51009120,
            ["FacialId"] = {
                [1] = "100001:Smile01",
                },
            ["GUID"] = "7FB22BC0",
            ["NextDialogue"] = 51009121,
            ["SpeakNpcId"] = 100001,
            },
        [51009121] = {
            ["Camera"] = "-23.448242,-113.345947,147.890976,0.000217,-16.601587,81.187027,35.000011,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "以后要是有新的素材和图谱就找老朽，到时候会给你锻造新武器的。",
            ["ContentFR"] = "Wenn du auf deiner Reise auf feine Materialien oder neue Baupläne stößt, bring sie mir. Ich werde etwas Neues für dich schmieden.",
            ["DialogueId"] = 51009121,
            ["FacialId"] = {
                [1] = "230002:Confident02",
                },
            ["GUID"] = "7FB22BEA",
            ["NextDialogue"] = 51009122,
            ["SpeakNpcId"] = 230002,
            },
        [51009122] = {
            ["Content"] = "不过唯独这一把……如果有一天，它不再锋利、残缺、甚至折断，就把它带回来，无论多少次老朽都会帮你重锻。",
            ["ContentFR"] = "Was diese hier angeht ... sollte der Tag kommen, an dem sie stumpf wird, abplatzt oder sogar bricht, bring sie zurück zu mir. Ich werde sie wieder schmieden, egal wie lange es her ist.",
            ["DialogueId"] = 51009122,
            ["GUID"] = "7FB22C14",
            ["NextDialogue"] = 51009123,
            ["SpeakNpcId"] = 230002,
            },
        [51009123] = {
            ["Camera"] = "-72.498413,-159.67749,187.376312,0.000227,-25.601515,61.982807,35.000011,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "希望无论什么时候，只要握住它，你都会想起促使你踏上旅途的心情。",
            ["ContentFR"] = "Versprich mir nur eins: Wann immer du sie in der Hand hältst, denk daran, was dein Herz damals dazu bewegte, loszuziehen.",
            ["DialogueId"] = 51009123,
            ["FacialId"] = {
                [1] = "230002:Happy02",
                },
            ["GUID"] = "7FB22C3E",
            ["NextDialogue"] = 51009124,
            ["SpeakNpcId"] = 230002,
            },
        [51009124] = {
            ["Camera"] = "-77.020996,37.951172,120.615501,0.000228,5.798578,-53.617523,35.000011,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我会好好使用它的。",
            ["ContentFR"] = "Ich werde sorgsam mit ihr umgehen. Mein Wort darauf.",
            ["DialogueId"] = 51009124,
            ["FacialId"] = {
                [1] = "100001:Confident02",
                },
            ["GUID"] = "7FB22C68",
            ["NextDialogue"] = 51009125,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Talk02_Start",
                },
            },
        [51009125] = {
            ["Camera"] = "7.467804,-22.984863,112.509064,0.000025,-21.401974,93.791664,35.000011,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "喔，真是不错的眼神，像你这样的年轻人可不多见咯。",
            ["ContentFR"] = "Ah ... Dieser Blick in deinen Augen. So etwas sieht man bei jungen Leuten heutzutage kaum noch.",
            ["DialogueId"] = 51009125,
            ["FacialId"] = {
                [1] = "230002:Satisfy01",
                },
            ["FinalCamera"] = "6.965179,-18.811523,117.716042,0.000023,-25.002098,92.79113,35.000011,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "7FB22C92",
            ["NextDialogue"] = 51009126,
            ["SpeakNpcId"] = 230002,
            ["TalkActionId"] = {
                [1] = "100001:Talk02_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            },
        [51009126] = {
            ["Content"] = "…………",
            ["ContentFR"] = "...",
            ["DialogueId"] = 51009126,
            ["GUID"] = "7FB22CBC",
            ["LookAt"] = {
                [1] = "230002:n(230002)",
                },
            ["NextDialogue"] = 51009127,
            ["SpeakNpcId"] = 230002,
            },
        [51009127] = {
            ["Camera"] = "-70.951233,159.355713,107.396042,0.000206,-7.602048,-68.41877,35.000011,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "铁匠前辈，你的表情有点怪怪的，是有什么事吗？",
            ["ContentFR"] = "Äh ... Schmiedin? Du bist ganz still geworden und wirkst seltsam. Ist alles in Ordnung?",
            ["DialogueId"] = 51009127,
            ["FacialId"] = {
                [1] = "230001:Shock01",
                },
            ["GUID"] = "7FB22CE6",
            ["NextDialogue"] = 51009128,
            ["SpeakNpcId"] = 230001,
            ["TalkActionId"] = {
                [1] = "230001:Explain02_Start",
                },
            },
        [51009128] = {
            ["Camera"] = "6.965179,-18.811523,117.716042,0.000023,-25.002098,92.79113,35.000011,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "没什么，只是想起来一些往事罢了。",
            ["ContentFR"] = "Hm? Oh, nichts. Nur ... eine alte Erinnerung.",
            ["DialogueId"] = 51009128,
            ["FacialId"] = {
                [1] = "230002:Syouganai01",
                },
            ["GUID"] = "7FB22D10",
            ["LookAt"] = {
                [1] = "230002:n(230001)",
                },
            ["NextDialogue"] = 51009129,
            ["SpeakNpcId"] = 230002,
            ["TalkActionId"] = {
                [1] = "230001:Explain02_End",
                },
            },
        [51009129] = {
            ["Content"] = "年轻人，能不能帮老朽一个忙？",
            ["ContentFR"] = "Sag mal, Jungspund ... könntest du mir einen Gefallen tun?",
            ["DialogueId"] = 51009129,
            ["FacialId"] = {
                [1] = "230002:None",
                },
            ["GUID"] = "7FB22D3A",
            ["LookAt"] = {
                [1] = "230002:n(100001)",
                },
            ["NextDialogue"] = 51009130,
            ["SpeakNpcId"] = 230002,
            },
        [51009130] = {
            ["Camera"] = "-47.573486,44.222656,131.574463,0.000207,1.597875,-67.619141,35.000011,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "什么忙？",
            ["ContentFR"] = "Natürlich. Was ist es?",
            ["DialogueId"] = 51009130,
            ["FacialId"] = {
                [1] = "100001:Smile01",
                },
            ["GUID"] = "7FB22D64",
            ["NextDialogue"] = 51009131,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Explain02_Start",
                },
            },
        [51009131] = {
            ["Camera"] = "-40.003357,-158.163818,175.533508,0.000306,-22.201714,78.178841,35.000011,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "如果在你冒险的途中，见到……或者听说一把如火焰般赤红的剑，记得告诉我。",
            ["ContentFR"] = "Wenn du auf deiner Reise zufällig ein Schwert siehst – oder davon hörst –, das die Farbe der Flammen hat, lass es mich wissen.",
            ["DialogueId"] = 51009131,
            ["GUID"] = "7FB22D8E",
            ["NextDialogue"] = 51009132,
            ["SpeakNpcId"] = 230002,
            ["TalkActionId"] = {
                [1] = "100001:Explain02_End",
                },
            },
        [51009132] = {
            ["Camera"] = "-79.764465,168.026123,112.217056,0.000226,-5.602353,-64.817764,35.000011,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "那也是铁匠前辈的作品吗？",
            ["ContentFR"] = "Ist das auch eines deiner Werke?",
            ["DialogueId"] = 51009132,
            ["GUID"] = "7FB22DB8",
            ["NextDialogue"] = 51009133,
            ["SpeakNpcId"] = 230001,
            ["TalkActionId"] = {
                [1] = "230001:Think_Start",
                },
            },
        [51009133] = {
            ["Camera"] = "-54.818481,-149.708496,145.451065,0.00023,-15.002154,70.382484,35.000011,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "应该是吧，不过什么时候锻造的它，为谁锻造的它……为什么想不起来呢……",
            ["ContentFR"] = "Ich glaube schon. Aber wann ich es geschmiedet habe ... und für wen ich es gemacht habe ... kann ich mich nicht mehr erinnern.",
            ["DialogueId"] = 51009133,
            ["FinalCamera"] = "-23.610504,-51.820557,117.260406,0.000222,-15.60216,74.782066,35.000011,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "7FB22DE2",
            ["NextDialogue"] = 51009134,
            ["SpeakNpcId"] = 230002,
            ["ToFinalCameraBlendTime"] = 15,
            },
        [51009134] = {
            ["Content"] = "老朽对那把剑的印象只剩下那像在燃烧着一般的颜色，但总觉得必须要找到那把剑不可……",
            ["ContentFR"] = "Alles, woran ich mich erinnere, ist dieses feurige Rot. Wie Flammen. Und das Gefühl, dass ich es finden muss.",
            ["DialogueId"] = 51009134,
            ["GUID"] = "7FB22E0C",
            ["NextDialogue"] = 51009135,
            ["SpeakNpcId"] = 230002,
            },
        [51009135] = {
            ["Camera"] = "4.024445,-18.40332,83.317413,0.00013,3.196528,91.587433,35.000011,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "年轻人，只有一些传闻也好，拜托你稍微注意一下。",
            ["ContentFR"] = "Sogar Gerüchte wären hilfreich. Bitte, halte ein Ohr für mich offen.",
            ["DialogueId"] = 51009135,
            ["FacialId"] = {
                [1] = "230002:Satisfy01",
                },
            ["FinalCamera"] = "0.602966,-57.215332,91.756393,0.000139,-1.603605,87.387039,35.000011,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "7FB22E36",
            ["LookAt"] = {
                [1] = "230002:n(100001)",
                },
            ["NextDialogue"] = 51009136,
            ["SpeakNpcId"] = 230002,
            ["ToFinalCameraBlendTime"] = 15,
            },
        [51009136] = {
            ["Camera"] = "-74.956299,70.125977,132.865021,0.000285,-2.00201,-61.222034,35.000011,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我明白了，会替前辈留意的。",
            ["ContentFR"] = "Verstanden. Ich werde Ausschau halten.",
            ["DialogueId"] = 51009136,
            ["GUID"] = "7FB22E60",
            ["NextDialogue"] = 51009137,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Talk02_Start",
                },
            },
        [51009137] = {
            ["Camera"] = "-45.467529,-102.451904,136.414795,0.000299,-15.201719,72.779053,35.000011,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "好了，长辈的唠叨到此为止。新的奇迹即将开始，让阿特拉西亚见证你的冒险吧。",
            ["ContentFR"] = "Genug gequasselt von einer alten Schmiedin. Ein neues Wunder steht bevor. Möge ganz Atlasia Zeuge deiner Reise werden.",
            ["DialogueId"] = 51009137,
            ["FacialId"] = {
                [1] = "230002:Happy02",
                },
            ["FinalCamera"] = "-109.385742,-261.364746,203.023361,0.000271,-18.801235,65.979637,35.000011,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "7FB22E8A",
            ["SpeakNpcId"] = 230002,
            ["TalkActionId"] = {
                [1] = "100001:Talk02_End",
                },
            ["ToFinalCameraBlendTime"] = 15,
            },
        [51009201] = {
            ["Camera"] = "438.621582,138.591309,121.772217,0.000022,0.399839,-164.795059,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "抱歉打扰到你，请容许我占用你英雄诗篇上那微不足道的一行用以自我介绍。",
            ["ContentFR"] = "Pardonnez mon audace. Permettez que j’emprunte une ligne, infime mais glorieuse, de votre épopée héroïque, pour me présenter.",
            ["DialogueId"] = 51009201,
            ["GUID"] = "7FB2390A",
            ["LookAt"] = {
                [1] = "230003:n(100001)",
                },
            ["NextDialogue"] = 51009202,
            ["SpeakNpcId"] = 230003,
            ["TalkActionId"] = {
                [1] = "230003:Explain02_Start",
                },
            },
        [51009202] = {
            ["Camera"] = "184.849121,-47.185059,77.377197,0.000079,-13.401609,165.810257,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "本人名叫阿米埃特，至于职业……本人所从事的事业比较难以用语言概括，因为那样做比较有违美学。",
            ["ContentFR"] = "Je me nomme Amiette. Quant à mon métier... il serait une offense à l’art de le réduire en mots.",
            ["DialogueId"] = 51009202,
            ["FinalCamera"] = "155.654297,64.67334,157.197266,0.000115,-0.001284,-158.590393,35.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "7FB23934",
            ["NextDialogue"] = 51009203,
            ["SpeakNpcId"] = 230003,
            ["TalkActionId"] = {
                [1] = "230003:Explain02_End",
                },
            ["ToFinalCameraBlendTime"] = 15,
            },
        [51009203] = {
            ["Camera"] = "155.654297,64.67334,157.197266,0.000115,-0.001284,-158.590393,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "如果一定要用一个词去称呼本人的职业，那还请叫做——艺术家。",
            ["ContentFR"] = "Mais si je dois absolument le nommer... appelez-moi \"artiste\".",
            ["DialogueId"] = 51009203,
            ["FinalCamera"] = "133.85498,-3.754883,152.920898,0.000117,0.198506,175.208954,35.000008,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "7FB2395E",
            ["NextDialogue"] = 51009204,
            ["SpeakNpcId"] = 230003,
            ["TalkActionId"] = {
                [1] = "230003:Confident_Start",
                },
            ["ToFinalCameraBlendTime"] = 15,
            },
        [51009204] = {
            ["Camera"] = "-116.031738,-138.629395,169.49292,0.000161,-6.801338,43.0089,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "好可疑……",
            ["ContentFR"] = "Louche...",
            ["DialogueId"] = 51009204,
            ["FacialId"] = {
                [1] = "100001:Uninterested01",
                },
            ["FinalCamera"] = "-50.322266,-81.086426,160.310791,0.000161,-6.001311,41.20895,35.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "7FB23988",
            ["LookAt"] = {
                [1] = "100001:n(230003)",
                },
            ["NextDialogue"] = 51009205,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Think_Start",
                [2] = "230003:Confident_End",
                },
            ["ToFinalCameraBlendTime"] = 30,
            },
        [51009205] = {
            ["Camera"] = "182.905762,56.904785,140.219238,0.000167,0.19811,-165.575302,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "请不必无端怀疑，本人在这里徘徊只是因为一些<H>美学</>上的疑惑。",
            ["ContentFR"] = "Pas de suspicion gratuite, je vous en prie. Je ne fais que hanter ces lieux, troublé par de profondes interrogations... <H>esthétiques</>.",
            ["DialogueId"] = 51009205,
            ["FacialId"] = {
                [1] = "100001:None",
                },
            ["FinalCamera"] = "209.431152,63.451172,140.220459,0.000167,-0.001858,-166.175751,35.000008,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "7FB239B2",
            ["NextDialogue"] = 51009206,
            ["SpeakNpcId"] = 230003,
            ["TalkActionId"] = {
                [1] = "100001:Think_End",
                [2] = "230003:Explain01_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            },
        [51009206] = {
            ["Content"] = "不知道你有没有这种感觉，朋友——最近的武器似乎都只注重杀伤力和成本，却忽略了锻造物应有的美学。",
            ["ContentFR"] = "N’avez-vous pas remarqué ? Les armes d’aujourd’hui n’ont d’yeux que pour la puissance brute et le coût de production. La beauté de la forge, elle, est complètement oubliée !",
            ["DialogueId"] = 51009206,
            ["GUID"] = "7FB239DC",
            ["NextDialogue"] = 51009207,
            ["SpeakNpcId"] = 230003,
            ["TalkActionId"] = {
                [1] = "230003:Explain01_End",
                },
            },
        [51009207] = {
            ["Camera"] = "-2849.924805,472.516602,-933.664307,0.000118,-4.801397,-111.175285,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "武器原本并非我主要的研究对象，只是你有没有发现，如今这座城市的士兵变得越来越粗鄙了。",
            ["ContentFR"] = "Les armes n’étaient pas mon domaine de prédilection, mais regardez donc ! Les soldats de cette cité se sont faits vulgaires, grossiers.",
            ["DialogueId"] = 51009207,
            ["FinalCamera"] = "-2585.590332,363.479004,-933.664307,0.000116,-5.401429,-115.973396,35.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "7FB23A06",
            ["NextDialogue"] = 51009208,
            ["SpeakNpcId"] = 230003,
            ["ToFinalCameraBlendTime"] = 15,
            },
        [51009208] = {
            ["Camera"] = "323.17334,117.169922,145.404541,0.000149,-2.002072,-168.165207,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我想正是海伯利亚的炼金院放弃了他们的美学追求，使用者才会如此粗俗，不成体统。而本人把他们的装备在美学上加以矫正，却遭到了不公的对待……",
            ["ContentFR"] = "Et je blâme l’Académie d’Alchimie d’Hyperborea ! À force de renoncer à l’esthétique, leurs porteurs deviennent eux-mêmes médiocres. Quand j’ai voulu corriger leurs armes, ils m’ont injustement puni...",
            ["DialogueId"] = 51009208,
            ["GUID"] = "7FB23A30",
            ["NextDialogue"] = 51009209,
            ["SpeakNpcId"] = 230003,
            ["TalkActionId"] = {
                [1] = "230003:Explain02_Start",
                },
            },
        [51009209] = {
            ["Camera"] = "107.540039,43.087402,155.901123,0.000135,-9.202333,39.223675,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "“矫正”？你做了什么出格的事吗？",
            ["ContentFR"] = "« Corriger » ? Tu as fait quelque chose d’interdit ?",
            ["DialogueId"] = 51009209,
            ["GUID"] = "7FB23A5A",
            ["NextDialogue"] = 51009210,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Think_Start",
                },
            },
        [51009210] = {
            ["Camera"] = "323.17334,117.169922,145.404541,0.000149,-2.002072,-168.165207,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "出格？当然没有，只是趁换岗的时候把他们的武器和配饰稍加修改，和他们对我下达监禁十五日的处罚相比，谈何出格？",
            ["ContentFR"] = "Interdit ? Pas du tout ! Je n’ai fait que modifier subtilement leurs armes et accessoires pendant un changement de garde. Quinze jours d’emprisonnement pour ça... n’est-ce pas démesuré ?",
            ["DialogueId"] = 51009210,
            ["GUID"] = "7FB23A84",
            ["NextDialogue"] = 51009211,
            ["SpeakNpcId"] = 230003,
            ["TalkActionId"] = {
                [1] = "230003:Angry01_Start",
                },
            },
        [51009211] = {
            ["Content"] = "本人理解让所有人拥有基本的美学素养是一项艰巨的伟大事业，但我们不应该因为前路艰险就停下脚步——",
            ["ContentFR"] = "Certes, inculquer un sens esthétique au plus grand nombre est une tâche titanesque. Mais devons-nous abandonner pour autant ?",
            ["DialogueId"] = 51009211,
            ["GUID"] = "7FB23AAE",
            ["NextDialogue"] = 51009212,
            ["SpeakNpcId"] = 230003,
            ["TalkActionId"] = {
                [1] = "230003:Angry01_End",
                },
            },
        [51009212] = {
            ["Camera"] = "355.351074,108.127441,146.656494,0.000137,-3.402848,-172.570343,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "本人以艺术名义起誓，上到传说英雄的利剑，下到聊以防身的小刀，无关出身无关价格，其本身都应具备美的要素！",
            ["ContentFR"] = "Je le jure au nom de l’Art ! De la plus légendaire des épées à la plus humble des lames, peu importe son prix ou son origine : toute arme doit refléter la beauté !",
            ["DialogueId"] = 51009212,
            ["GUID"] = "7FB23AD8",
            ["NextDialogue"] = 51009213,
            ["SpeakNpcId"] = 230003,
            ["TalkActionId"] = {
                [1] = "230003:Agree",
                },
            },
        [51009213] = {
            ["Camera"] = "179.876953,-270.89502,193.723389,0.00005,-10.001951,105.430725,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "哦？老朽好像听到了些很有趣的话。",
            ["ContentFR"] = "Oh ? Voilà qui est intéressant. J’aime entendre parler avec passion.",
            ["DialogueId"] = 51009213,
            ["FinalCamera"] = "170.026367,-235.211914,187.194336,0.00005,-10.001951,105.430725,35.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "7FB23B02",
            ["LookAt"] = {
                [1] = "100001:n(230002)",
                [2] = "230003:n(230002)",
                },
            ["NextDialogue"] = 51009214,
            ["Scripts"] = "PlayOrStopBGM{PlayType{\"Play\"},SoundPriority{\"StoryCustom\"},SoundType{\"SOUND_BGM\"},SoundUnitKey{\"sidestory_tiejiangjiaojiao\"},EventPath{\"event:/bgm/cbt02/0041_story_jiaojiao_tiejiang\"}}",
            ["SpeakNpcId"] = 230002,
            ["ToFinalCameraBlendTime"] = 30,
            },
        [51009214] = {
            ["Camera"] = "25.713867,-203.86377,194.304688,0.000058,-11.801876,80.425873,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "这个后辈虽然从外表看起来不太靠谱，但似乎对武器的美学颇有一些见解。",
            ["ContentFR"] = "Ce garçon n’a pas l’air bien fiable... mais il touche juste sur un point : une arme doit aussi posséder une esthétique.",
            ["DialogueId"] = 51009214,
            ["FinalCamera"] = "71.773438,-210.437012,194.733398,0.000048,-11.601704,88.225449,35.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "7FB23B2C",
            ["LookAt"] = {
                [1] = "230002:n(230003)",
                },
            ["NextDialogue"] = 51009215,
            ["Scripts"] = "PARA{\
LookAt{_delay{0.5},LookAtDescription{\"230003:n(230002)\"}}\
}",
            ["SpeakNpcId"] = 230002,
            ["TalkActionId"] = {
                [1] = "100001:Think_End",
                },
            ["ToFinalCameraBlendTime"] = 30,
            },
        [51009215] = {
            ["Camera"] = "77.210938,30.784668,120.665283,0.000054,-10.001801,93.224159,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "现在的武器总是粗枝大叶，锤锻造就的线条，淬炼形成的纹路，恰到好处的平衡，每一个环节都应该饱含锻造者的心血才是。",
            ["ContentFR"] = "Aujourd’hui, tout est bâclé. Les lignes forgées au marteau, les motifs créés par la trempe, l’équilibre au creux de la main... chaque détail devrait porter la marque de l’âme du forgeron.",
            ["DialogueId"] = 51009215,
            ["FacialId"] = {
                [1] = "230002:Happy01",
                },
            ["FinalCamera"] = "109.248535,35.82959,120.665283,0.000053,-10.801848,106.024544,35.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "7FB23B56",
            ["LookAt"] = {
                [1] = "230002:n(230002)",
                },
            ["NextDialogue"] = 51009216,
            ["SpeakNpcId"] = 230002,
            ["ToFinalCameraBlendTime"] = 30,
            },
        [51009216] = {
            ["Camera"] = "192.502441,42.003906,148.640137,0.000075,-3.202395,-170.373978,35.000011,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "线条？纹路？平衡？",
            ["ContentFR"] = "Des lignes ? Des motifs ? De l’équilibre ?",
            ["DialogueId"] = 51009216,
            ["GUID"] = "7FB23B80",
            ["NextDialogue"] = 51009217,
            ["SpeakNpcId"] = 230003,
            ["TalkActionId"] = {
                [1] = "230003:Think_Start",
                },
            },
        [51009217] = {
            ["Content"] = "请等一等，这些和美学有什么关系？",
            ["ContentFR"] = "Attendez... quel rapport avec l’esthétique ?",
            ["DialogueId"] = 51009217,
            ["GUID"] = "7FB23BAA",
            ["NextDialogue"] = 51009218,
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{230003},AnimationId{\"Think_End\"},Duration{0.7}},\
PlayAnimation{ActorId{230003},AnimationId{\"Explain01_Start\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 230003,
            },
        [51009218] = {
            ["Camera"] = "2.193848,-80.82959,191.693848,0.000078,-22.189302,81.527405,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "啊？",
            ["ContentFR"] = "Hein ?",
            ["DialogueId"] = 51009218,
            ["FacialId"] = {
                [1] = "230002:Shock01",
                },
            ["GUID"] = "7FB23BD4",
            ["LookAt"] = {
                [1] = "230002:n(230003)",
                },
            ["NextDialogue"] = 51009219,
            ["SpeakNpcId"] = 230002,
            },
        [51009219] = {
            ["Camera"] = "249.694824,-158.883301,265.504639,0.000084,-27.202122,132.82428,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "美学真正的灵魂所在是色彩啊！色彩！",
            ["ContentFR"] = "L’essence véritable de l’esthétique, c’est la couleur ! La couleur, vous dis-je !",
            ["DialogueId"] = 51009219,
            ["GUID"] = "7FB23BFE",
            ["NextDialogue"] = 51009220,
            ["SpeakNpcId"] = 230003,
            ["TalkActionId"] = {
                [1] = "230003:Angry01_Start",
                },
            },
        [51009220] = {
            ["Camera"] = "66.329102,29.245117,148.397217,0.000144,-18.801685,88.624496,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "喔——原来是考虑这个方面吗？",
            ["ContentFR"] = "Ah... je comprends mieux ton point de vue.",
            ["DialogueId"] = 51009220,
            ["FinalCamera"] = "67.455566,76.165527,132.418457,0.000147,-18.801685,88.624504,25.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "7FB23C28",
            ["NextDialogue"] = 51009221,
            ["Scripts"] = "SEQ{\
LookAt{_delay{2.8},LookAtDescription{\"230002:n(230002)\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 230002,
            ["TalkActionId"] = {
                [1] = "230003:Angry01_End",
                },
            ["ToFinalCameraBlendTime"] = 3,
            },
        [51009221] = {
            ["Camera"] = "178.851562,-88.053223,170.254639,0.000148,-13.401493,102.027,25.000006,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "你不生气吗，前辈？",
            ["ContentFR"] = "Ça ne t’énerve pas ? ",
            ["DialogueId"] = 51009221,
            ["FinalCamera"] = "199.270508,-82.57959,170.254639,0.000143,-13.401459,105.427238,25.000006,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "7FB23C52",
            ["LookAt"] = {
                [1] = "100001:n(230002)",
                },
            ["NextDialogue"] = 51009222,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Explain01_Start",
                },
            ["ToFinalCameraBlendTime"] = 30,
            },
        [51009222] = {
            ["Camera"] = "302.543945,-108.304688,186.282227,0.000152,-9.201569,139.426468,25.000002,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "虽然回答有些出乎意料，但涂装色彩的确是影响美观的一个因素，倒也确实有不少人比较在意。",
            ["ContentFR"] = "Pas le moins du monde. Sa réponse est surprenante, mais il n’a pas tort. La teinte, le fini, ça compte aussi pour beaucoup.",
            ["DialogueId"] = 51009222,
            ["FacialId"] = {
                [1] = "230002:Ahaha02",
                },
            ["FinalCamera"] = "278.34668,-132.726074,186.282227,0.000151,-9.00156,131.226593,25.000002,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "7FB23C7C",
            ["LookAt"] = {
                [1] = "230002:n(100001)",
                },
            ["NextDialogue"] = 51009223,
            ["SpeakNpcId"] = 230002,
            ["TalkActionId"] = {
                [1] = "100001:Explain01_End",
                },
            ["ToFinalCameraBlendTime"] = 30,
            },
        [51009223] = {
            ["Camera"] = "414.796875,83.106445,83.046387,0.000167,1.99893,178.023361,25.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我刚才发觉这位英雄的武器色调朴素，本想尊重您的个人喜好，但对艺术和美的追求又让本人控制不住向您搭话……",
            ["ContentFR"] = "J’ai remarqué que votre arme, {性别:héros|héroïne}, était d’une sobriété... presque austère. J’aurais pu respecter ce choix. Mais mon âme d’artiste n’a pas pu se retenir de vous aborder.",
            ["DialogueId"] = 51009223,
            ["FinalCamera"] = "334.032227,127.685059,137.778564,0.000189,-2.60138,-169.170135,25.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "7FB23CA6",
            ["LookAt"] = {
                [1] = "230003:n(100001)",
                [2] = "100001:n(230003)",
                },
            ["NextDialogue"] = 51009224,
            ["SpeakNpcId"] = 230003,
            ["TalkActionId"] = {
                [1] = "230003:Explain01_Start",
                },
            ["ToFinalCameraBlendTime"] = 15,
            },
        [51009224] = {
            ["Content"] = "总之，这里有一份独家的染剂配方，还有一些染剂的试作品，还请务必试试。",
            ["ContentFR"] = "Voilà donc une recette exclusive de teinture, avec quelques échantillons. Essayez-les, je vous en prie.",
            ["DialogueId"] = 51009224,
            ["GUID"] = "7FB23CD0",
            ["LookAt"] = {
                [1] = "230002:n(230002)",
                },
            ["NextDialogue"] = 51009225,
            ["SpeakNpcId"] = 230003,
            ["TalkActionId"] = {
                [1] = "230003:Explain01_End",
                },
            },
        [51009225] = {
            ["Camera"] = "140.89209,77.023438,171.302979,0.000198,-10.586759,-153.78447,25.000006,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "无论是武器，还是穿戴的饰品。只要用了它，您与美学真谛之间的距离，便不再远不可及！",
            ["ContentFR"] = "Arme ou bijou, peu importe : grâce à cela, vous vous rapprocherez de l’essence de l’esthétique !",
            ["DialogueId"] = 51009225,
            ["FinalCamera"] = "147.106445,6.32666,173.12915,0.000199,-13.386808,178.615372,25.000006,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "7FB23CFA",
            ["NextOptions"] = {
                [1] = 510092251,
                [2] = 510092252,
                [3] = 510092253,
                },
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{230003},AnimationId{\"Give\"},Duration{2}},\
PlayAnimation{ActorId{230003},AnimationId{\"Angry01_Start\"},Duration{2}}\
}",
            ["SpeakNpcId"] = 230003,
            ["ToFinalCameraBlendTime"] = 15,
            },
        [51009226] = {
            ["Camera"] = "274.12793,98.953613,123.311523,0.000205,0.68726,-170.794342,25.000006,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "怎么能叫推销呢，这只是接近美学真谛的一点小小代价。",
            ["ContentFR"] = "Vendre ? Allons donc ! Ce n’est qu’un infime prix à payer pour effleurer la véritable essence de la beauté.",
            ["DialogueId"] = 51009226,
            ["GUID"] = "7FB23D24",
            ["NextDialogue"] = 51009227,
            ["SpeakNpcId"] = 230003,
            ["TalkActionId"] = {
                [1] = "230003:Explain02_Start",
                },
            },
        [51009227] = {
            ["Camera"] = "113.979492,13.10791,128.264404,0.000198,2.998221,54.034763,25.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "每个推销的人都这么说。",
            ["ContentFR"] = "Ce que disent tous les vendeurs...",
            ["DialogueId"] = 51009227,
            ["FacialId"] = {
                [1] = "100001:Uninterested01",
                },
            ["FinalCamera"] = "124.612793,27.871582,129.727783,0.000197,4.59822,54.234753,25.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "7FB23D4E",
            ["NextDialogue"] = 51009233,
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{100001},AnimationId{\"Sigh_Start\"},Duration{2}},\
PlayAnimation{ActorId{100001},AnimationId{\"Sigh_End\"},Duration{2}}\
}",
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "230003:Explain02_End",
                },
            ["ToFinalCameraBlendTime"] = 30,
            },
        [51009228] = {
            ["Camera"] = "274.12793,98.953613,123.311523,0.000205,0.68726,-170.794342,25.000006,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "请不要为自己在审美上的欠缺而愧疚，这是每个人都有可能犯的错误。",
            ["ContentFR"] = "Mais non, il ne faut pas te sentir coupable de manquer de sens esthétique. C’est une faiblesse humaine très courante, et pardonnable.",
            ["DialogueId"] = 51009228,
            ["GUID"] = "7FB23D78",
            ["NextDialogue"] = 51009229,
            ["SpeakNpcId"] = 230003,
            ["TalkActionId"] = {
                [1] = "230003:Explain02_Start",
                },
            },
        [51009229] = {
            ["Camera"] = "113.979492,13.10791,128.264404,0.000198,2.998221,54.034763,25.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "你这个人……",
            ["ContentFR"] = "Non mais toi...",
            ["DialogueId"] = 51009229,
