        [51009230] = {
            ["Camera"] = "274.12793,98.953613,123.311523,0.000205,0.68726,-170.794342,25.000006,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "喂喂喂……你没事吧？",
            ["ContentFR"] = "Quoi ?! Attendez ! Vous êtes complètement {性别:fou|folle} !?",
            ["DialogueId"] = 51009230,
            ["GUID"] = "7FB23DCC",
            ["LookAt"] = {
                [1] = "100001:n(100001)",
                },
            ["NextDialogue"] = 51009231,
            ["SpeakNpcId"] = 230003,
            ["TalkActionId"] = {
                [1] = "230003:Angry01_Start",
                [2] = "230003:Shock_Start",
                },
            },
        [51009231] = {
            ["Camera"] = "113.979492,13.10791,128.264404,0.000198,2.998221,54.034763,25.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "还挺好喝？",
            ["ContentFR"] = "Pas mauvais, en fait.",
            ["DialogueId"] = 51009231,
            ["FacialId"] = {
                [1] = "100001:Shock01",
                },
            ["FinalCamera"] = "124.612793,27.871582,129.727783,0.000197,4.59822,54.234753,25.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "7FB23DF6",
