            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:ScratchHead_Start",
                },
            },
        [51009465] = {
            ["Camera"] = "62.644531,-11.876099,183.486328,0.000056,-8.794127,105.195045,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "怎么就夸张了？我生平最见不得这种危害社会治安的败类，你放心，这一带的住户我都或多或少打过交道，只要有点线索我一定能把犯人抓到！",
            ["ContentFR"] = "Comment ça, pas nécessaire ? Je déteste ce genre d’individus qui troublent l’ordre public. Je connais pratiquement tous les habitants du coin. Donne-moi un indice, et je le retrouverai.",
            ["DialogueId"] = 51009465,
            ["GUID"] = "7FB2645A",
            ["NextDialogue"] = 51009466,
            ["SpeakNpcId"] = 700313,
            ["TalkActionId"] = {
                [1] = "100001:ScratchHead_End",
                [2] = "700313:Confident_Start",
                },
