                },
            },
        [51009470] = {
            ["Content"] = "怎么了，你为什么不说话？",
            ["ContentFR"] = "... Qu’y a-t-il ? Pourquoi ne dites-vous rien ?",
            ["DialogueId"] = 51009470,
            ["GUID"] = "7FB2652C",
            ["NextDialogue"] = 51009471,
            ["SpeakNpcId"] = 100001,
            },
        [51009471] = {
            ["Camera"] = "28.276367,114.675842,163.198242,0.000057,-8.794093,105.195099,12.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "这……这对吗？这不对吧？我觉得这封信言辞恳切情感真挚，和骚扰信天差地别。",
            ["ContentFR"] = "C’est... c’est vraiment ça ? Non, impossible. Cette lettre est sincère, pleine de passion et d’émotion ! Rien à voir avec du harcèlement !",
            ["DialogueId"] = 51009471,
            ["GUID"] = "7FB26556",
            ["NextDialogue"] = 51009472,
            ["SpeakNpcId"] = 700313,
            ["TalkActionId"] = {
                [1] = "700313:Talk01_Start",
                },
            },
        [51009472] = {
            ["Camera"] = "224.37207,502.975342,173.965332,0.000078,-3.594175,-121.197639,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "看来寄信的人已经找到了。刚才好像有人说要把犯人好好教训一顿？",
            ["ContentFR"] = "On dirait bien que j’ai trouvé le coupable. Vous ne parliez pas de lui « apprendre les bonnes manières », tout à l’heure ?",
            ["DialogueId"] = 51009472,
            ["FacialId"] = {
                [1] = "100001:None",
                },
            ["GUID"] = "7FB26580",
            ["NextDialogue"] = 51009473,
            ["SpeakNpcId"] = 100001,
            },
        [51009473] = {
            ["Camera"] = "28.276367,114.675842,163.198242,0.000057,-8.794093,105.195099,12.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "这是误会，一定是误会。我发誓我对薇奥莱塔女士一片真心——不是说薇奥莱塔女士最喜欢热情洋溢的表白吗？她怎么会说那是骚扰啊？",
            ["ContentFR"] = "C’est un malentendu, forcément un malentendu ! Je jure que mes sentiments pour Violetta sont réels ! Et puis, n’est-ce pas bien connu qu’elle aime les déclarations enflammées ? Pourquoi verrait-elle ça comme du harcèlement ?",
            ["DialogueId"] = 51009473,
            ["GUID"] = "7FB265AA",
            ["NextDialogue"] = 51009474,
            ["SpeakNpcId"] = 700313,
            },
        [51009474] = {
            ["Content"] = "……难道是<H>那家伙在骗我</>……",
            ["ContentFR"] = "... Attends une seconde. <H>Est-ce que ce {性别:Chasseur de Phoxène|Chasseuse de Phoxène} m’aurait menti</>... ?",
            ["DialogueId"] = 51009474,
            ["GUID"] = "7FB265D4",
            ["NextDialogue"] = 51009475,
            ["SpeakNpcId"] = 700313,
            },
        [51009475] = {
            ["Content"] = "等一下，我明白了！是你！你根本不是薇奥莱塔女士派来的，你是来拆散我们的！",
            ["ContentFR"] = "Je comprends maintenant ! C’est toi ! Tu n’as jamais été envoyé par Violetta, tu veux simplement nous séparer !",
            ["DialogueId"] = 51009475,
            ["GUID"] = "7FB265FE",
            ["NextDialogue"] = 51009476,
            ["SpeakNpcId"] = 700313,
            ["TalkActionId"] = {
                [1] = "700313:Angry01_Start",
                },
            },
        [51009476] = {
            ["Content"] = "你有什么证据证明是薇奥莱塔女士让你来的？依我看你就是在挑拨离间！",
            ["ContentFR"] = "As-tu seulement la moindre preuve qu’elle t’a demandé de venir ? À mon avis, tu veux juste semer la discorde !",
            ["DialogueId"] = 51009476,
            ["GUID"] = "7FB26628",
            ["NextDialogue"] = 51009477,
            ["SpeakNpcId"] = 700313,
            },
        [51009477] = {
            ["Camera"] = "112.706055,-213.83313,198.990479,0.000058,-8.794134,109.594849,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "居然试图用这样的手段来破坏薇奥莱塔女士和追随者之间的信任，我必须要好好教训一下你！",
            ["ContentFR"] = "Tenter de briser le lien sacré qui unit Violetta à ses admirateurs ? Jamais ! Je vais t’apprendre à regretter ce que tu as fait !",
            ["DialogueId"] = 51009477,
            ["GUID"] = "7FB26652",
            ["NextDialogue"] = 51009478,
            ["SpeakNpcId"] = 700313,
            },
        [51009478] = {
            ["Camera"] = "92.173828,227.503815,153.63623,0.000067,-3.594264,-113.599007,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "你这人怎么……",
            ["ContentFR"] = "Mais qu’est-ce que vous racontez... ?",
            ["DialogueId"] = 51009478,
            ["GUID"] = "7FB2667C",
            ["NextDialogue"] = 51009479,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Talk03_End",
                },
            },
        [51009479] = {
            ["Camera"] = "112.706055,-213.83313,198.990479,0.000058,-8.794134,109.594849,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "（还是先想办法让这个自说自话的家伙冷静一下吧。）",
            ["ContentFR"] = "<I>Mieux vaut calmer ce fan délirant avant que les choses ne dégénèrent.</>",
            ["DialogueId"] = 51009479,
            ["GUID"] = "7FB266A6",
            ["SpeakNpcId"] = 100001,
            },
        [51009480] = {
            ["Camera"] = "112.706055,-213.83313,198.990479,0.000058,-8.794134,109.594849,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "薇奥莱塔女士，是我……是我太弱小……",
            ["ContentFR"] = "Violetta... Je suis désolé... Je suis trop faible pour te protéger...",
            ["DialogueId"] = 51009480,
            ["GUID"] = "7FB266D0",
            ["NextDialogue"] = 51009481,
            ["SpeakNpcId"] = 700313,
            ["TalkActionId"] = {
                [1] = "700313:Stop01_Start",
                },
            },
        [51009481] = {
            ["Camera"] = "172.162109,534.255371,170.810547,0.000068,-3.594264,-113.598976,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "闹够了？看看这个吧。",
            ["ContentFR"] = "C’est bon, vous avez fini ? Regardez plutôt ceci.",
            ["DialogueId"] = 51009481,
            ["DialoguePanelType"] = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_ChapterFire_Ribbon01.T_Guide_ChapterFire_Ribbon01'}",
            ["FacialId"] = {
                [1] = "100001:Angry01",
                },
            ["GUID"] = "7FB266FA",
            ["NextDialogue"] = 51009482,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Give",
                [2] = "700313:Stop01_End",
                },
            },
        [51009482] = {
            ["Camera"] = "62.644531,-11.876099,183.486328,0.000056,-8.794127,105.195045,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "这是，薇奥莱塔女士的缎带？她从十多年前第一次公开演出开始就一直带着的……",
            ["ContentFR"] = "C’est... c’est le ruban de Violetta ? Celui qu’elle porte depuis sa première représentation, il y a plus de dix ans...",
            ["DialogueId"] = 51009482,
            ["GUID"] = "7FB26724",
            ["NextDialogue"] = 51009483,
            ["SpeakNpcId"] = 700313,
            ["TalkActionId"] = {
                [1] = "700313:Shock_Start",
                },
            },
        [51009483] = {
            ["Camera"] = "92.173828,227.503815,153.63623,0.000067,-3.594264,-113.599007,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "这也能认出来？",
            ["ContentFR"] = "Vous arrivez à le reconnaître aussi vite ?",
            ["DialogueId"] = 51009483,
            ["FacialId"] = {
                [1] = "100001:Shock01",
                },
            ["GUID"] = "7FB2674E",
            ["NextDialogue"] = 51009484,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Disagree",
                },
            },
        [51009484] = {
            ["Camera"] = "62.644531,-11.876099,183.486328,0.000056,-8.794127,105.195045,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "怎么可能认不出来！我跟你说这些干吗……",
            ["ContentFR"] = "Bien sûr que oui... Pourquoi est-ce que je raconte tout ça, d’ailleurs...",
            ["DialogueId"] = 51009484,
            ["GUID"] = "7FB26778",
            ["NextDialogue"] = 51009485,
            ["SpeakNpcId"] = 700313,
            ["TalkActionId"] = {
                [1] = "700313:Shock_End",
                },
            },
        [51009485] = {
            ["Content"] = "既然你拿着这个，那看来我是真的被拒绝了。我不会再去骚扰薇奥莱塔女士了，祝你们幸福。",
            ["ContentFR"] = "Si c’est toi qui le portes, alors ça veut dire que j’ai vraiment été rejeté. Je ne la dérangerai plus. Je vous souhaite tout le bonheur du monde.",
            ["DialogueId"] = 51009485,
            ["GUID"] = "7FB267A2",
            ["NextOptions"] = {
                [1] = 510093951,
                [2] = 510093952,
                },
            ["SpeakNpcId"] = 700313,
            },
        [51009486] = {
            ["Camera"] = "62.644531,-11.876099,183.486328,0.000056,-8.794127,105.195045,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "不要再说了，就让一颗炽烈的心在角落默默哭泣吧！",
            ["ContentFR"] = "Inutile d’en dire plus... Laisse donc un cœur brûlant pleurer seul dans l’ombre...",
            ["DialogueId"] = 51009486,
            ["GUID"] = "7FB267CC",
            ["NextDialogue"] = 51009487,
            ["SpeakNpcId"] = 700313,
            ["TalkActionId"] = {
                [1] = "700313:Stop01_Start",
                },
            },
        [51009487] = {
            ["Camera"] = "92.173828,227.503815,153.63623,0.000067,-3.594264,-113.599007,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "（卫兵不再回答，只是一味流泪……还是让他自己安静一会儿吧。）",
            ["ContentFR"] = "Le soldat ne dit plus rien. Il se contente de pleurer en silence... Mieux vaut le laisser tranquille un moment.",
            ["DialogueId"] = 51009487,
            ["FacialId"] = {
                [1] = "100001:None",
                },
            ["GUID"] = "7FB267F6",
            ["SpeakNpcId"] = 100001,
            },
        [51009488] = {
            ["Camera"] = "154.741699,155.880859,184.548828,0.000014,-8.400074,-153.591629,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "薇奥莱塔女士，我回来了。",
            ["ContentFR"] = "Madame Violetta, me revoilà.",
            ["DialogueId"] = 51009488,
            ["GUID"] = "7FB26820",
            ["NextDialogue"] = 51009489,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Explain01_Start",
                },
            },
        [51009489] = {
            ["Camera"] = "-225.489746,72.248535,138.279785,0.000003,0.400024,-11.196657,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "辛苦你了，看起来问题已经解决了。",
            ["ContentFR"] = "Merci pour ton aide. J’en déduis que l’affaire est réglée ?",
            ["DialogueId"] = 51009489,
            ["FacialId"] = {
                [1] = "700300:CM_Happy01",
                },
            ["GUID"] = "7FB2684A",
            ["NextDialogue"] = 51009490,
            ["SpeakNpcId"] = 700300,
            ["TalkActionId"] = {
                [1] = "100001:Explain01_End",
                [2] = "700300:Talk02_Start",
                },
            },
        [51009490] = {
            ["Camera"] = "154.741699,155.880859,184.548828,0.000014,-8.400074,-153.591629,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "嗯，他不会再来骚扰你了。这条缎带也还给你，如果没有它，恐怕还要再被纠缠一段时间。",
            ["ContentFR"] = "Oui. Il ne viendra plus t’importuner. Voici ton ruban — sans lui, j’aurais probablement été coincé dans cette histoire encore un bon moment.",
            ["DialogueId"] = 51009490,
            ["DialoguePanelType"] = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_ChapterFire_Ribbon01.T_Guide_ChapterFire_Ribbon01'}",
            ["FacialId"] = {
                [1] = "100001:Confident01",
                },
            ["GUID"] = "7FB26874",
            ["NextDialogue"] = 51009491,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "700300:Talk02_End",
                [2] = "100001:Give",
                },
            },
        [51009491] = {
            ["Content"] = "听说这条缎带，你从十几年前就一直戴着？",
            ["ContentFR"] = "J’ai entendu dire que tu le portes depuis tes débuts... il y a plus de dix ans ?",
            ["DialogueId"] = 51009491,
            ["FacialId"] = {
                [1] = "100001:Doubt01",
                },
            ["GUID"] = "7FB2689E",
            ["NextDialogue"] = 51009492,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Explain01_Start",
                },
            },
        [51009492] = {
            ["Camera"] = "-225.489746,72.248535,138.279785,0.000003,0.400024,-11.196719,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "是的，这是一位友人留给我的纪念，她才华横溢，但却不受命运垂怜……",
            ["ContentFR"] = "C’est exact. C’est un souvenir qu’une amie très chère m’a laissé. Elle était brillante, mais le destin ne l’a pas épargnée...",
            ["DialogueId"] = 51009492,
            ["FacialId"] = {
                [1] = "700300:CM_Sad01",
                },
            ["GUID"] = "7FB268C8",
            ["NextDialogue"] = 51009493,
            ["SpeakNpcId"] = 700300,
            ["TalkActionId"] = {
                [1] = "100001:Explain01_End",
                [2] = "700300:Sigh_Start",
                },
            },
        [51009493] = {
            ["Content"] = "出于某些原因，她无法实现自己的梦想了，不过我可以，所以我希望能够让她也一起在舞台上闪耀。",
            ["ContentFR"] = "Pour certaines raisons, elle n’a jamais pu accomplir son rêve. Moi, en revanche, j’en ai eu l’opportunité, alors j’ai voulu qu’elle brille à mes côtés, sur scène.",
            ["DialogueId"] = 51009493,
            ["FacialId"] = {
                [1] = "700300:CM_Sad01",
                },
            ["GUID"] = "7FB268F2",
            ["NextDialogue"] = 51009494,
            ["SpeakNpcId"] = 700300,
            ["TalkActionId"] = {
                [1] = "700300:Sigh_End",
                },
            },
        [51009494] = {
            ["Content"] = "所以在我第一次公演的时候，我亲自设计了一张海报，在黑白的画面里，只有一抹紫色格外亮眼——",
            ["ContentFR"] = "C’est pourquoi, lors de ma toute première représentation, j’ai conçu moi-même l’affiche : une image en noir et blanc, traversée d’un unique éclat de violet.",
            ["DialogueId"] = 51009494,
            ["FacialId"] = {
                [1] = "700300:CM_Sad01",
                },
            ["GUID"] = "7FB2691C",
            ["NextDialogue"] = 51009495,
            ["SpeakNpcId"] = 700300,
            ["TalkActionId"] = {
                [1] = "700300:Talk02_Start",
                },
            },
        [51009495] = {
            ["Content"] = "你应该听说过“千面的薇奥莱塔”这个称呼，我有着足以让自己变成另一个人的化妆技术，在每场演出都会根据角色用不同的容貌登台。",
            ["ContentFR"] = "Tu as sans doute déjà entendu ce surnom — « Violetta aux mille visages ». Grâce à mon talent pour le maquillage, je peux me transformer entièrement et incarner chaque rôle avec un visage différent.",
            ["DialogueId"] = 51009495,
            ["FacialId"] = {
                [1] = "700300:CM_Sad01",
                },
            ["GUID"] = "7FB26946",
            ["NextDialogue"] = 51009496,
            ["SpeakNpcId"] = 700300,
            },
        [51009496] = {
            ["Content"] = "但唯独这条缎带，我每次都会戴上。久而久之，<H>它也就成了我独有的标志</>。",
            ["ContentFR"] = "Mais il y a une chose qui ne change jamais : ce ruban. Je le porte à chacune de mes représentations. <H>Il est devenu ma signature.</>",
            ["DialogueId"] = 51009496,
            ["FacialId"] = {
                [1] = "700300:CM_Sad01",
                },
            ["GUID"] = "7FB26970",
            ["NextDialogue"] = 51009497,
            ["SpeakNpcId"] = 700300,
            ["TalkActionId"] = {
                [1] = "700300:Talk02_End",
                },
            },
        [51009497] = {
            ["Camera"] = "6.950195,47.361328,152.822266,0.000007,-4.600037,-165.990051,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "原来如此……",
            ["ContentFR"] = "Je vois...",
            ["DialogueId"] = 51009497,
            ["FacialId"] = {
                [1] = "100001:Unhappy02",
                },
            ["GUID"] = "7FB2699A",
            ["NextDialogue"] = 51009498,
            ["SpeakNpcId"] = 100001,
            },
        [51009498] = {
            ["Content"] = "老师！",
            ["ContentFR"] = "Professeur !",
            ["DialogueId"] = 51009498,
            ["GUID"] = "7FB269C4",
            ["LookAt"] = {
                [1] = "100001:n(700306)",
                [2] = "700300:n(700306)",
                },
            ["NextDialogue"] = 51009499,
            ["SpeakNpcId"] = 700306,
            },
        [51009499] = {
            ["Camera"] = "-225.489746,72.248535,138.279785,0.000003,0.400024,-11.196657,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "费恩，我应该教过你不要大呼小叫。",
            ["ContentFR"] = "Fane, je t’ai déjà dit de ne pas crier ainsi.",
            ["DialogueId"] = 51009499,
            ["FacialId"] = {
                [1] = "700300:CM_Angry01",
                },
            ["GUID"] = "7FB269EE",
            ["NextDialogue"] = 51009500,
            ["SpeakNpcId"] = 700300,
            ["TalkActionId"] = {
                [1] = "700300:Confident_Start",
                },
            },
        [51009500] = {
            ["Camera"] = "-401.135742,235.075195,139.57666,0.000003,-1.799823,-39.399132,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "对不起……但是老师你必须看看这个！",
            ["ContentFR"] = "Je suis désolé... mais tu dois absolument voir ça !",
            ["DialogueId"] = 51009500,
            ["GUID"] = "7FB26A18",
            ["NextDialogue"] = 51009501,
            ["Scripts"] = "PARA{\
