            ["GUID"] = "7FB28FFE",
            ["NextDialogue"] = 51009733,
            ["SpeakNpcId"] = 700309,
            },
        [51009732] = {
            ["Content"] = "抱歉，我只是一只普通的箱子，没有那种力量。",
            ["ContentFR"] = "Désolée de te décevoir, mais je ne réalise pas de vœux. Je ne suis qu’une simple caisse ordinaire.",
            ["DialogueId"] = 51009732,
            ["GUID"] = "7FB29028",
