            },
        [51009747] = {
            ["Content"] = "你知道的，我只是一只木箱，我没有办法去剧院看戏。",
            ["ContentFR"] = "Tu sais, je ne peux pas aller au théâtre... je ne suis qu’une caisse, après tout.",
            ["DialogueId"] = 51009747,
            ["GUID"] = "7FB2929E",
            ["NextDialogue"] = 51009748,
            ["SpeakNpcId"] = 700309,
            },
        [51009748] = {
            ["Camera"] = "258.270447,-156.542389,96.182617,0.000091,-4.999384,138.403717,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "抱歉，我没看过。",
            ["ContentFR"] = "{性别:Désolé|Désolée}, je ne l’ai pas vu.",
            ["DialogueId"] = 51009748,
            ["FacialId"] = {
                [1] = "100001:None",
                },
            ["GUID"] = "7FB292C8",
            ["NextDialogue"] = 51009749,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:DisagreeHead",
                },
            },
        [51009749] = {
            ["Camera"] = "165.608704,156.288574,79.068604,0.000101,-0.599274,-97.799728,13.284671,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "没关系，没人会因此责怪你。或许你应该找个机会去看一看，那是一出好戏。那个叫普蒂妮的主角，她美丽、善良。还有着……追逐自由的勇气。",
            ["ContentFR"] = "Ce n’est pas grave. Personne ne t’en voudra. Mais si un jour tu en as l’occasion, va le voir — c’est une œuvre magnifique. L’héroïne, Putini, est belle, généreuse... et surtout, elle a le courage de poursuivre sa liberté.",
            ["DialogueId"] = 51009749,
            ["GUID"] = "7FB292F2",
            ["NextDialogue"] = 51009750,
            ["SpeakNpcId"] = 700309,
            },
        [51009750] = {
            ["Content"] = "我也想成为她那样的人，可我却只是一只木箱。",
            ["ContentFR"] = "Moi aussi, j’aimerais être comme elle. Mais je ne suis qu’une simple caisse.",
            ["DialogueId"] = 51009750,
            ["GUID"] = "7FB2931C",
            ["NextDialogue"] = 51009751,
            ["SpeakNpcId"] = 700309,
            },
        [51009751] = {
            ["Content"] = "所以我做出了一个决定。",
            ["ContentFR"] = "Alors j’ai pris une décision.",
            ["DialogueId"] = 51009751,
            ["GUID"] = "7FB29346",
            ["NextDialogue"] = 51009752,
            ["SpeakNpcId"] = 700309,
            },
        [51009752] = {
            ["Content"] = "什么样的决定？",
            ["ContentFR"] = "Quelle décision ?",
            ["DialogueId"] = 51009752,
            ["FacialId"] = {
                [1] = "100001:Doubt01",
                },
            ["GUID"] = "7FB29370",
            ["NextDialogue"] = 51009753,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Talk02_Start",
                },
            },
        [51009753] = {
            ["Camera"] = "693.018372,159.482361,393.903809,0.000131,-25.999353,-158.378677,27.283031,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我想去远航，没人规定木箱只能堆放在街道的角落，它也可以被做成船，随着洋流漂泊——我想感受混着海水与砂砾的风。",
            ["ContentFR"] = "Je veux partir en mer. Qui a décrété qu’une caisse devait rester dans un coin de rue ? Elle peut devenir un bateau, voguer au gré des flots... Je veux sentir le vent marin, chargé de sel et de sable.",
            ["DialogueId"] = 51009753,
            ["FacialId"] = {
                [1] = "100001:None",
                },
            ["GUID"] = "7FB2939A",
            ["NextDialogue"] = 51009754,
            ["SpeakNpcId"] = 700309,
            ["TalkActionId"] = {
                [1] = "100001:Talk02_End",
                },
            },
        [51009754] = {
            ["Content"] = "可离开这里，就意味着我同样会失去现有的一切。",
            ["ContentFR"] = "Mais quitter cet endroit signifie aussi tout perdre.",
            ["DialogueId"] = 51009754,
            ["GUID"] = "7FB293C4",
            ["NextDialogue"] = 51009755,
            ["SpeakNpcId"] = 700309,
            },
        [51009755] = {
            ["Content"] = "失去了囚笼，也代表着失去了容身之所。拥有了自由，也代表拥有了未知的风险。",
            ["ContentFR"] = "Se libérer de sa cage, c’est aussi perdre son abri. Obtenir la liberté, c’est aussi affronter l’inconnu.",
            ["DialogueId"] = 51009755,
            ["GUID"] = "7FB293EE",
            ["NextDialogue"] = 51009756,
            ["SpeakNpcId"] = 700309,
            },
        [51009756] = {
            ["Camera"] = "165.608704,156.288574,79.068604,0.000101,-0.599274,-97.799728,13.284671,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我的朋友，你觉得，我应该怎么选呢？",
            ["ContentFR"] = "Alors, mon {性别:ami|amie}... dis-moi. Que devrais-je faire ?",
            ["DialogueId"] = 51009756,
            ["GUID"] = "7FB29418",
            ["NextOptions"] = {
                [1] = 510096661,
                [2] = 510096662,
                },
            ["SpeakNpcId"] = 700309,
            },
        [51009757] = {
            ["Content"] = "……说的也是。",
            ["ContentFR"] = "... Tu as raison.",
            ["DialogueId"] = 51009757,
            ["GUID"] = "7FB29442",
            ["NextDialogue"] = 51009758,
            ["SpeakNpcId"] = 700309,
            },
        [51009758] = {
            ["Content"] = "谢谢你愿意陪一只箱子聊天，善良的人啊。天快亮了，属于朽木的魔法要消失了。",
            ["ContentFR"] = "Merci d’avoir parlé avec une simple caisse, toi, l’âme bienveillante. L’aube approche... et avec elle, la magie qui anime ce vieux bois disparaît.",
            ["DialogueId"] = 51009758,
            ["GUID"] = "7FB2946C",
            ["NextDialogue"] = 51009759,
            ["SpeakNpcId"] = 700309,
            },
        [51009759] = {
            ["Content"] = "祝愿你在未来的每一个无眠的夜晚，都有……不，祝愿你每个夜晚都能安享美梦。",
            ["ContentFR"] = "Je te souhaite, non pas des nuits d’insomnie moins pénibles... mais que toutes tes nuits soient peuplées de doux rêves.",
            ["DialogueId"] = 51009759,
            ["GUID"] = "7FB29496",
            ["SpeakNpcId"] = 700309,
            },
        [51009760] = {
            ["Content"] = "（你听到了一阵微小的震颤声，如同躲藏在箱子背后的小精灵赶在天亮前离开了孩子的床头。当回过神来的时候，你意识到那位箱子小姐似乎已经离开了。）",
            ["ContentFR"] = "Tu entends un léger frémissement — comme une petite fée qui s’envole de la chambre d’un enfant avant le lever du jour. Quand tu reprends tes esprits, Mademoiselle Caisse a disparu.",
            ["DialogueId"] = 51009760,
            ["GUID"] = "7FB294C0",
            },
        [51009761] = {
            ["Camera"] = "181.495728,-78.722099,88.629395,0.000093,-3.999294,136.804047,30.022871,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "（躲在箱子里的那个声音……不知道为什么就顺着她的想法聊下去了。）",
            ["ContentFR"] = "<I>Cette voix dans la caisse... Je ne sais pas pourquoi, mais j’ai fini par me laisser entraîner dans sa conversation.</>",
            ["DialogueId"] = 51009761,
            ["FacialId"] = {
                [1] = "100001:Doubt01",
                },
            ["GUID"] = "7FB294EA",
            ["NextDialogue"] = 51009762,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Think_Start",
                },
            },
        [51009762] = {
            ["Camera"] = "-5654.617676,-3244.824707,4837.760742,0.000161,-38.599369,19.822903,27.283031,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "（可能是谁家的小孩子在乱跑，不能就这么放着不管，还是找周围的人问问吧。）",
            ["ContentFR"] = "<I>C’est sans doute un enfant du quartier qui s’amusait. Je ne peux pas laisser ça sans suite — je devrais poser quelques questions autour de moi.</>",
            ["DialogueId"] = 51009762,
            ["GUID"] = "7FB29514",
            ["SpeakNpcId"] = 100001,
            },
        [51009763] = {
            ["Content"] = "请问……你是谁？从刚才开始似乎就一直在我家附近转悠。",
            ["ContentFR"] = "Excuse-moi... qui es-tu ? Je t’ai vu tourner dans le coin depuis un moment.",
            ["DialogueId"] = 51009763,
            ["GUID"] = "7FB2953E",
            ["NextDialogue"] = 51009764,
            ["SpeakNpcId"] = 700302,
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            },
        [51009764] = {
            ["Content"] = "是有委托找我吗，找人？还是收集素材？其他的委托也不是不接，但必须合法。",
            ["ContentFR"] = "Tu cherches à passer une mission ? Suivi, collecte, livraison... j’accepte toutes sortes de missions — tant qu’elles sont légales.",
            ["DialogueId"] = 51009764,
            ["GUID"] = "7FB29568",
            ["NextDialogue"] = 51009765,
            ["SpeakNpcId"] = 700302,
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            },
        [51009765] = {
            ["Content"] = "委托？",
            ["ContentFR"] = "Une mission ?",
            ["DialogueId"] = 51009765,
            ["GUID"] = "7FB29592",
            ["NextDialogue"] = 51009766,
            ["SpeakNpcId"] = 100001,
            },
        [51009766] = {
            ["Content"] = "嗯？原来你不是来找我发委托的？",
            ["ContentFR"] = "Hein ? Tu n’es pas là pour m’en confier une ?",
            ["DialogueId"] = 51009766,
            ["GUID"] = "7FB295BC",
            ["NextDialogue"] = 51009767,
            ["SpeakNpcId"] = 700302,
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            },
        [51009767] = {
            ["Content"] = "好吧，看来“狩月人吉赛尔”的名气没有卡米拉说的那么响。",
            ["ContentFR"] = "Bon... on dirait que la renommée de « Giselle la Chasseuse de Phoxène » n’est pas aussi éclatante que Camilla le prétendait.",
            ["DialogueId"] = 51009767,
            ["GUID"] = "7FB295E6",
            ["NextDialogue"] = 51009768,
            ["SpeakNpcId"] = 700302,
            },
        [51009768] = {
            ["Content"] = "狩月人吉赛尔……这么一说我好像听到过——",
            ["ContentFR"] = "Giselle la Chasseuse de Phoxène... Oui, ce nom me dit quelque chose.",
            ["DialogueId"] = 51009768,
            ["GUID"] = "7FB29610",
            ["NextDialogue"] = 51009769,
            ["SpeakNpcId"] = 100001,
            },
        [51009769] = {
            ["Content"] = "倒也不用为了照顾我的心情这么说。",
            ["ContentFR"] = "Pas besoin de me flatter pour me faire plaisir.",
            ["DialogueId"] = 51009769,
            ["GUID"] = "7FB2963A",
            ["NextDialogue"] = 51009770,
            ["SpeakNpcId"] = 700302,
            },
        [51009770] = {
            ["Content"] = "不……其实……",
            ["ContentFR"] = "Non... je le pense vraiment.",
            ["DialogueId"] = 51009770,
            ["GUID"] = "7FB29664",
            ["NextDialogue"] = 51009771,
            ["SpeakNpcId"] = 100001,
            },
        [51009771] = {
            ["Content"] = "（向吉赛尔说明了她家屋后那个箱子的事。）",
            ["ContentFR"] = "Tu racontes à Giselle l’histoire de la caisse qui parlait derrière sa maison.",
            ["DialogueId"] = 51009771,
            ["GUID"] = "7FB2968E",
            ["NextDialogue"] = 51009772,
            },
        [51009772] = {
            ["Content"] = "你是说，我家房后的木箱说话了，还推荐你去听一场歌剧。嗯，我了解了。",
            ["ContentFR"] = "Donc... une caisse derrière chez moi t’a parlé, et t’a conseillé d’aller à l’opéra. Très bien, j’ai compris.",
            ["DialogueId"] = 51009772,
            ["GUID"] = "7FB296B8",
            ["NextDialogue"] = 51009773,
            ["SpeakNpcId"] = 700302,
            },
        [51009773] = {
            ["Content"] = "……",
            ["ContentFR"] = "...",
            ["DialogueId"] = 51009773,
            ["GUID"] = "7FB296E2",
            ["NextDialogue"] = 51009774,
            ["SpeakNpcId"] = 100001,
            },
        [51009774] = {
            ["Content"] = "你好像，反应和我想象中有点不一样？",
            ["ContentFR"] = "Ta réaction est... pas exactement celle à laquelle je m’attendais.",
            ["DialogueId"] = 51009774,
            ["GUID"] = "7FB2970C",
            ["NextDialogue"] = 51009775,
            ["SpeakNpcId"] = 100001,
            },
        [51009775] = {
            ["Content"] = "是吗？可能是我性格如此。无论是有小孩子淘气钻进去和你说话，还是箱子本身就会说话，对我来说都是可以接受的现实。",
            ["ContentFR"] = "Ah bon ? C’est sûrement ma nature. Qu’il s’agisse d’un enfant caché dans une caisse ou d’une caisse qui parle vraiment, pour moi, les deux sont plausibles.",
            ["DialogueId"] = 51009775,
            ["GUID"] = "7FB29736",
            ["NextDialogue"] = 51009776,
            ["SpeakNpcId"] = 700302,
            },
        [51009776] = {
            ["Content"] = "谢谢你把这件事告诉我，我会在这一带问一问的。",
            ["ContentFR"] = "Merci de m’avoir raconté ça. Je poserai quelques questions dans le voisinage.",
            ["DialogueId"] = 51009776,
            ["GUID"] = "7FB29760",
            ["NextDialogue"] = 51009777,
            ["SpeakNpcId"] = 700302,
            },
        [51009777] = {
            ["Content"] = "哦对了，我想起来了。你是{nickname}对吗？最近在狩月人圈子里评价很高的新星。",
            ["ContentFR"] = "Oh, au fait... je crois savoir qui tu es. Tu es bien {nickname}, non ? La nouvelle étoile montante parmi les Chasseurs de Phoxène.",
            ["DialogueId"] = 51009777,
            ["GUID"] = "7FB2978A",
            ["NextOptions"] = {
                [1] = 510096871,
                [2] = 510096872,
                [3] = 510096873,
                },
            ["SpeakNpcId"] = 700302,
            },
        [51009778] = {
            ["Content"] = "果然是你，看来我的眼光还没退步。",
            ["ContentFR"] = "Je m’en doutais. Ravie de voir que mon instinct ne me trompe pas encore.",
            ["DialogueId"] = 51009778,
            ["GUID"] = "7FB297B4",
            ["NextDialogue"] = 51009781,
            ["SpeakNpcId"] = 700302,
            },
        [51009779] = {
            ["Content"] = "不用那么警惕，像你这样的有能力的新人出名很快的。",
            ["ContentFR"] = "Détends-toi. Des nouveaux talents comme toi deviennent célèbres très vite.",
            ["DialogueId"] = 51009779,
            ["GUID"] = "7FB297DE",
            ["NextDialogue"] = 51009781,
            ["SpeakNpcId"] = 700302,
            },
        [51009780] = {
            ["Content"] = "品味稍微差了点……不过确实是个辨识度很高的称号。",
            ["ContentFR"] = "Pas très subtil... mais au moins, c’est un surnom qui marque les esprits.",
            ["DialogueId"] = 51009780,
            ["GUID"] = "7FB29808",
            ["NextDialogue"] = 51009781,
            ["SpeakNpcId"] = 700302,
            },
        [51009781] = {
            ["Content"] = "既然你看起来有空，可以帮我一个忙吗？",
            ["ContentFR"] = "Puisque tu sembles avoir un peu de temps... pourrais-tu m’aider ?",
            ["DialogueId"] = 51009781,
            ["GUID"] = "7FB29832",
            ["NextDialogue"] = 51009782,
            ["SpeakNpcId"] = 700302,
            },
        [51009782] = {
            ["Content"] = "帮我找些草药来，种类和数量我会列一个清单给你，收集好之后直接送到水仙平原就好，报酬我也会提前留给卡米拉。",
            ["ContentFR"] = "J’ai besoin de certaines herbes. Je vais te donner une liste. Quand tu les auras, apporte-les simplement aux Asphodèles. Camilla t’y remettra la récompense.",
            ["DialogueId"] = 51009782,
            ["GUID"] = "7FB2985C",
            ["NextDialogue"] = 51009783,
            ["SpeakNpcId"] = 700302,
            },
        [51009783] = {
            ["Content"] = "不用送到这里？",
            ["ContentFR"] = "Tu ne veux pas que je te les livre ici ?",
            ["DialogueId"] = 51009783,
            ["GUID"] = "7FB29886",
            ["NextDialogue"] = 51009784,
            ["SpeakNpcId"] = 100001,
            },
        [51009784] = {
            ["Content"] = "没事，放到水仙平原就可以。",
            ["ContentFR"] = "Non, pas besoin. Les Asphodèles suffiront.",
            ["DialogueId"] = 51009784,
            ["GUID"] = "7FB298B0",
            ["SpeakNpcId"] = 700302,
            },
        [51009785] = {
            ["Camera"] = "777.87793,290.900391,409.416016,0.000004,-23.199877,-161.79744,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "（差不多应该够了。）",
            ["ContentFR"] = "<I>Ça devrait suffire.</>",
            ["DialogueId"] = 51009785,
            ["FacialId"] = {
                [1] = "100001:Smile02",
                },
            ["GUID"] = "7FB298DA",
            ["NextDialogue"] = 51009786,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Confident_Start",
                },
            },
        [51009786] = {
            ["Camera"] = "104.59375,60.244141,114.90918,0.000007,-13.199702,-164.194138,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "（这些草药……都是些随处可见的品种，如果吉赛尔也是狩月人为什么要专门拜托我？）",
            ["ContentFR"] = "<I>Ces herbes... elles sont toutes très communes. Si Giselle est vraiment une Chasseuse de Phoxène, pourquoi m’avoir demandé de les ramasser à sa place ?</>",
            ["DialogueId"] = 51009786,
            ["FacialId"] = {
                [1] = "100001:Doubt01",
                },
            ["GUID"] = "7FB29904",
            ["NextDialogue"] = 51009787,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Think_Start",
                },
            },
        [51009787] = {
            ["Content"] = "（现在回想起来，她的态度也有些奇怪……）",
            ["ContentFR"] = "<I>Maintenant que j’y repense, son attitude aussi était étrange...</>",
            ["DialogueId"] = 51009787,
            ["GUID"] = "7FB2992E",
            ["NextDialogue"] = 51009788,
            ["SpeakNpcId"] = 100001,
            },
        [51009788] = {
            ["Content"] = "（先把这些草药带回水仙平原吧，顺便向卡米拉打听一下。）",
            ["ContentFR"] = "<I>Je ferais mieux d’apporter tout ça aux Asphodèles, et d’en profiter pour interroger Camilla.</>",
            ["DialogueId"] = 51009788,
            ["GUID"] = "7FB29958",
            ["SpeakNpcId"] = 100001,
            },
        [51009789] = {
            ["Camera"] = "-670.438599,-35.56543,192.935547,0.000003,-7.599917,-2.401886,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "下午好，今天是想喝上一杯，还是在看委托？",
            ["ContentFR"] = "Eh bien, quelle surprise. Tu viens pour un verre ou c’est le travail qui t’amène ?",
            ["DialogueId"] = 51009789,
            ["FacialId"] = {
                [1] = "200003:Smile01",
                },
            ["GUID"] = "7FB29982",
            ["NextDialogue"] = 51009790,
            ["SpeakNpcId"] = 200003,
            },
        [51009790] = {
            ["Content"] = "我是来送东西的，是吉赛尔的委托，说让我把东西送到水仙平原就好。",
            ["ContentFR"] = "Je suis juste venu livrer ça. C’est Giselle qui m’a demandé d’apporter ces herbes ici.",
            ["DialogueId"] = 51009790,
            ["GUID"] = "7FB299AC",
            ["NextDialogue"] = 51009791,
            ["SpeakNpcId"] = 100001,
            },
        [51009791] = {
            ["Content"] = "吉赛尔？她的确不久前来过一趟，说让我帮忙把一个包裹转交给你。不过总感觉有些不对劲……委托的内容是什么？",
            ["ContentFR"] = "Giselle ? Oui, elle est passée tout à l’heure — elle m’a même laissé un colis pour toi. Mais... quelque chose ne tourne pas rond. Qu’est-ce qu’elle t’avait demandé exactement ?",
            ["DialogueId"] = 51009791,
            ["GUID"] = "7FB299D6",
            ["NextDialogue"] = 51009792,
            ["SpeakNpcId"] = 200003,
            ["TalkActionId"] = {
                [1] = "200003:Talk03_Start",
                },
            },
        [51009792] = {
            ["Content"] = "（向卡米拉说明了吉赛尔委托自己采集草药的事。）",
            ["ContentFR"] = "Tu expliques à Camilla que Giselle t’a chargé de cueillir des herbes.",
            ["DialogueId"] = 51009792,
            ["GUID"] = "7FB29A00",
            ["NextDialogue"] = 51009793,
            },
        [51009793] = {
            ["Content"] = "…………",
            ["ContentFR"] = "...",
            ["DialogueId"] = 51009793,
            ["GUID"] = "7FB29A2A",
            ["NextDialogue"] = 51009794,
            ["SpeakNpcId"] = 200003,
            },
        [51009794] = {
            ["Camera"] = "-172.41748,71.862305,163.089844,0.000016,-8.200038,-114.998413,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "有什么不对吗？",
            ["ContentFR"] = "Il y a un problème ?",
            ["DialogueId"] = 51009794,
            ["GUID"] = "7FB29A54",
            ["NextDialogue"] = 51009795,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Talk01_Start",
                },
            },
        [51009795] = {
            ["Camera"] = "-263.901001,-18.859375,168.283203,0.000002,-5.799807,9.398898,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "委托本身倒是没什么，不过为什么她会发出这种委托？",
            ["ContentFR"] = "Pas vraiment un problème... mais j’ai du mal à comprendre pourquoi elle t’aurait confié ça.",
            ["DialogueId"] = 51009795,
            ["GUID"] = "7FB29A7E",
            ["NextDialogue"] = 51009796,
            ["SpeakNpcId"] = 200003,
            ["TalkActionId"] = {
                [1] = "100001:Talk01_End",
                },
            },
        [51009796] = {
            ["Content"] = "需求都是些很常见的风寒草药，她自己去收集的话一早上就能回来，没有必要专门请人去做。",
            ["ContentFR"] = "Ces plantes sont des remèdes de base contre le rhume. Elle aurait pu les cueillir elle-même en moins d’une matinée — ce n’est pas vraiment le genre de travail pour lequel on engage quelqu’un.",
            ["DialogueId"] = 51009796,
            ["GUID"] = "7FB29AA8",
            ["NextDialogue"] = 51009797,
            ["SpeakNpcId"] = 200003,
            },
        [51009797] = {
            ["Camera"] = "-172.41748,71.862305,163.089844,0.000016,-8.200038,-114.998413,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "说起来我的确听她提到过，她自己就是个狩月人。",
            ["ContentFR"] = "C’est vrai, elle m’a dit elle-même qu’elle était une Chasseuse de Phoxène.",
            ["DialogueId"] = 51009797,
            ["GUID"] = "7FB29AD2",
            ["NextDialogue"] = 51009798,
            ["SpeakNpcId"] = 100001,
            },
        [51009798] = {
            ["Camera"] = "-263.901001,-18.859375,168.283203,0.000002,-5.799807,9.398898,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "嗯，她以前做过卫戍官，十六年前因为某个案子的判决和上级起了矛盾离开卫戍部队做了狩月人。思维敏捷身手也不错，在圈子里名气不小。",
            ["ContentFR"] = "Oui. Elle n’est pas une simple chasseuse : elle a même été capitaine chez les Veilleurs, avant de claquer la porte il y a seize ans, après un sale désaccord avec sa hiérarchie. Depuis, elle opère en solo. Elle est rapide, efficace, et suffisamment respectée pour ne pas avoir besoin d’aide sur une corvée pareille.",
            ["DialogueId"] = 51009798,
            ["GUID"] = "7FB29AFC",
            ["NextDialogue"] = 51009799,
            ["SpeakNpcId"] = 200003,
            },
        [51009799] = {
            ["Content"] = "算了，不提那些了。既然委托没什么问题，她也提前留过了口信，我就没什么好多说的。",
            ["ContentFR"] = "Mais bref... inutile de se torturer l’esprit. La mission est en règle, et elle t’a bel et bien laissé quelque chose.",
            ["DialogueId"] = 51009799,
            ["FacialId"] = {
                [1] = "200003:None",
                },
            ["GUID"] = "7FB29B26",
            ["NextDialogue"] = 51009800,
            ["SpeakNpcId"] = 200003,
            ["TalkActionId"] = {
                [1] = "200003:Talk03_End",
                },
            },
        [51009800] = {
            ["Content"] = "这是她留给你的东西，拿好。",
            ["ContentFR"] = "Tiens, prends ça.",
            ["DialogueId"] = 51009800,
            ["GUID"] = "7FB29B50",
            ["NextDialogue"] = 51009801,
            ["SpeakNpcId"] = 200003,
            ["TalkActionId"] = {
                [1] = "200003:Give",
                },
            },
        [51009801] = {
            ["Camera"] = "-172.41748,71.862305,163.089844,0.000016,-8.200038,-114.998413,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "这是……委托的报酬，还有一封信？",
            ["ContentFR"] = "C’est... la récompense ? Et une lettre ?",
            ["DialogueId"] = 51009801,
            ["FacialId"] = {
                [1] = "100001:Doubt01",
                },
            ["GUID"] = "7FB29B7A",
            ["SpeakNpcId"] = 100001,
            },
        [51009802] = {
            ["Content"] = "你好，亲爱的朋友。\
谢谢你愿意陪一个荒唐的箱子聊到深夜，也谢谢你给我踏上旅途的勇气。\
也许这么做有些对不起我的朋友和老师，但她们一定会理解我的选择。世界那么大，我会在其他的舞台和她们再见。\
还有，请不要责怪吉赛尔，这是我自己的意愿。希望我的任性不会连累到其他人。\
啊，突然想起来我还没有对你说过我的名字。\
不过那个名字以后不会再用啦，让我想想……\
如果你以后遇到了一个叫普蒂妮的女孩，请一定要认出我，我也一定会认出你的。",
            ["ContentFR"] = "« Bonjour, {性别:mon cher ami|ma chère amie},\
Merci d’avoir tenu compagnie à une vieille caisse un peu folle jusqu’au bout de la nuit... et de m’avoir donné le courage de prendre la mer.\
Peut-être que ce que je fais n’est pas juste envers mes amies... ou mon professeur. Mais je suis sûre qu’elles comprendront. Le monde est vaste. Je les reverrai quelque part, sur une autre scène.\
\
Et s’il te plaît, ne blâme pas Giselle. C’était mon choix. J’espère seulement que mon égoïsme n’aura causé de tort à personne.\
\
Ah... je me rends compte que je ne t’ai jamais dit mon nom.\
Mais ce n’est plus important maintenant — je n’en aurai plus besoin. Voyons voir...\
Si un jour tu rencontres une fille qui s’appelle Putini... j’espère que tu me reconnaîtras. Moi, je te reconnaîtrai. »",
            ["DialogueId"] = 51009802,
            ["Duration"] = 10,
            ["GUID"] = "7FB29BA4",
            },
        [51009803] = {
            ["Camera"] = "-670.438599,-35.56543,192.935547,0.000003,-7.599917,-2.401886,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "看来你认识了一个奇怪的朋友，这应该是一段有趣的故事。",
            ["ContentFR"] = "On dirait que tu t’es fait une amie pour le moins... singulière. Je parie que l’histoire derrière tout ça vaut son pesant d’or.",
            ["DialogueId"] = 51009803,
            ["FacialId"] = {
                [1] = "200003:Smile01",
                },
            ["GUID"] = "7FB29BCE",
            ["NextDialogue"] = 51009804,
            ["SpeakNpcId"] = 200003,
            ["TalkActionId"] = {
                [1] = "200003:Talk02_Start",
                },
            },
        [51009804] = {
            ["Camera"] = "-172.41748,71.862305,163.089844,0.000016,-8.200038,-114.998413,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "不……其实我也不知道具体发生了什么。",
            ["ContentFR"] = "Pas vraiment... Honnêtement, je ne sais même pas exactement ce qui s’est passé.",
            ["DialogueId"] = 51009804,
            ["FacialId"] = {
                [1] = "100001:None",
                },
            ["GUID"] = "7FB29BF8",
            ["NextDialogue"] = 51009805,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "200003:Talk02_End",
                [2] = "100001:ScratchHead_Start",
                },
            },
        [51009805] = {
            ["Content"] = "（和卡米拉讲述了最近两天发生的事。）",
            ["ContentFR"] = "Tu racontes à Camilla tout ce qui s’est passé ces deux derniers jours.",
            ["DialogueId"] = 51009805,
            ["GUID"] = "7FB29C22",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 51009806,
            },
        [51009806] = {
            ["Camera"] = "-263.901001,-18.859375,168.283203,0.000002,-5.799807,9.398898,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "普蒂妮……",
            ["ContentFR"] = "Putini...",
            ["DialogueId"] = 51009806,
            ["GUID"] = "7FB29C4C",
            ["NextDialogue"] = 51009807,
            ["SpeakNpcId"] = 200003,
            ["TalkActionId"] = {
                [1] = "200003:Talk03_Start",
                },
            },
        [51009807] = {
            ["Camera"] = "-172.41748,71.862305,163.089844,0.000016,-8.200038,-114.998413,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "这个名字怎么了？",
            ["ContentFR"] = "Ce nom te dit quelque chose ?",
            ["DialogueId"] = 51009807,
            ["FacialId"] = {
                [1] = "100001:Doubt01",
                },
            ["GUID"] = "7FB29C76",
            ["NextDialogue"] = 51009808,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:ScratchHead_End",
                },
            },
        [51009808] = {
            ["Camera"] = "-263.901001,-18.859375,168.283203,0.000002,-5.799807,9.398898,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "单论名字好像没什么特别的，不过箱子里的那个声音确实提到了前几天歌剧院的演出对吗？",
            ["ContentFR"] = "Pris isolément, ce nom ne me dit rien... mais cette voix dans la caisse, elle a bien parlé d’un opéra, pas vrai ?",
            ["DialogueId"] = 51009808,
            ["GUID"] = "7FB29CA0",
            ["NextDialogue"] = 51009809,
            ["SpeakNpcId"] = 200003,
            },
        [51009809] = {
            ["Camera"] = "-172.41748,71.862305,163.089844,0.000016,-8.200038,-114.998413,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "嗯，还专门问过我那个女主角唱的怎么样。",
            ["ContentFR"] = "Oui. Elle m’a même demandé ce que je pensais du rôle principal.",
            ["DialogueId"] = 51009809,
            ["GUID"] = "7FB29CCA",
            ["NextDialogue"] = 51009810,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "200003:Talk03_End",
                },
            },
        [51009810] = {
            ["Camera"] = "-670.438599,-35.56543,192.935547,0.000003,-7.599917,-2.401886,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "实际上我从酒馆的客人那里听到了这样一则传闻……",
            ["ContentFR"] = "Curieux... J’ai justement entendu quelques rumeurs à ce sujet.",
            ["DialogueId"] = 51009810,
            ["FacialId"] = {
                [1] = "200003:None",
                },
            ["GUID"] = "7FB29CF4",
            ["NextDialogue"] = 51009811,
            ["SpeakNpcId"] = 200003,
            ["TalkActionId"] = {
                [1] = "200003:Talk02_Start",
                },
            },
        [51009811] = {
            ["Content"] = "他们中曾经有人观看过《普蒂妮》的彩排，当时的女主角并不是正式公演时登台的这位。",
            ["ContentFR"] = "Un client m’a confié qu’il avait assisté à la répétition générale de Putini. Et d’après lui, l’actrice principale n’était pas la même que celle qui est montée sur scène le soir de la première.",
            ["DialogueId"] = 51009811,
            ["GUID"] = "7FB29D1E",
            ["NextDialogue"] = 51009812,
            ["SpeakNpcId"] = 200003,
            },
        [51009812] = {
            ["Content"] = "据他说那是一个更年轻的，但很有天赋的演员，但正式演出登台的，却还是以前的主演。",
            ["ContentFR"] = "D’après lui, l’interprète à la répétition était plus jeune — et très talentueuse, mais le soir de la première, c’est l’ancienne vedette qui est montée sur scène.",
            ["DialogueId"] = 51009812,
            ["GUID"] = "7FB29D48",
            ["NextDialogue"] = 51009813,
            ["SpeakNpcId"] = 200003,
            },
        [51009813] = {
            ["Camera"] = "-172.41748,71.862305,163.089844,0.000016,-8.200038,-114.998413,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "你是说……",
            ["ContentFR"] = "Tu veux dire que...",
            ["DialogueId"] = 51009813,
            ["GUID"] = "7FB29D72",
            ["NextDialogue"] = 51009814,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Think_Start",
                },
            },
        [51009814] = {
            ["Camera"] = "-263.901001,-18.859375,168.283203,0.000002,-5.799807,9.398898,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "只是些传闻罢了，并没有直接的证据能把这两件事联系起来。",
            ["ContentFR"] = "Ce ne sont que des bruits de comptoir, rien qui permette d’établir un lien certain entre les deux affaires.",
            ["DialogueId"] = 51009814,
            ["FacialId"] = {
                [1] = "200003:Smile01",
                },
            ["GUID"] = "7FB29D9C",
            ["NextDialogue"] = 51009815,
            ["SpeakNpcId"] = 200003,
            },
        [51009815] = {
            ["Content"] = "不过，我对事情的真相也很好奇，如果你有空的话，可以继续调查一下。",
            ["ContentFR"] = "Mais... si tu as un peu de temps devant toi, ça vaudrait peut-être le coup d’aller gratter plus loin. Moi aussi, j’aimerais bien connaître le fin mot de l’histoire.",
            ["DialogueId"] = 51009815,
            ["GUID"] = "7FB29DC6",
            ["NextDialogue"] = 51009816,
            ["SpeakNpcId"] = 200003,
            },
        [51009816] = {
            ["Camera"] = "-172.41748,71.862305,163.089844,0.000016,-8.200038,-114.998413,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "（看来卡米拉也感到有些奇怪。不过可以确定的是，吉赛尔的确有些反常。）",
            ["ContentFR"] = "<I>Camilla n’en sait pas plus que moi... Mais une chose est sûre : Giselle a eu un comportement étrange.</>",
            ["DialogueId"] = 51009816,
            ["GUID"] = "7FB29DF0",
            ["NextDialogue"] = 51009817,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "200003:Talk02_End",
                },
            },
        [51009817] = {
            ["Content"] = "（箱子里的那个女孩会是那位没能登台的演员吗……吉赛尔是否从一开始就知情？）",
            ["ContentFR"] = "La fille de la caisse... serait-elle l’actrice qui n’a jamais pu monter sur scène ? Et si oui, Giselle était-elle au courant depuis le début ?",
            ["DialogueId"] = 51009817,
            ["GUID"] = "7FB29E1A",
            ["NextDialogue"] = 51009818,
            ["SpeakNpcId"] = 100001,
            },
        [51009818] = {
            ["Content"] = "（在这里想也不会有什么结果，再去找吉赛尔问问吧。）",
            ["ContentFR"] = "<I>Je ne trouverai aucune réponse en restant ici. Autant aller interroger Giselle directement.</>",
            ["DialogueId"] = 51009818,
            ["GUID"] = "7FB29E44",
            ["SpeakNpcId"] = 100001,
            },
        [51009819] = {
            ["Camera"] = "-459.554443,-130.776611,223.984375,0.000025,-13.400024,3.198126,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我说过，我早就说过！",
            ["ContentFR"] = "Je l’avais dit ! Je l’avais prévenu !",
            ["DialogueId"] = 51009819,
            ["FacialId"] = {
                [1] = "700307:CM_Angry01",
                },
            ["GUID"] = "7FB29E6E",
            ["NextDialogue"] = 51009820,
            ["SpeakNpcId"] = 700307,
            ["TalkActionId"] = {
                [1] = "700307:Angry01_Start",
                },
            },
        [51009820] = {
            ["Content"] = "就不该找那种来历不明的女人当家庭教师！就不该让罗莎琳去学什么声乐！",
            ["ContentFR"] = "On n’aurait jamais dû engager cette femme louche comme préceptrice ! On n’aurait jamais dû laisser Rosalind suivre ces fichus cours de chant !",
            ["DialogueId"] = 51009820,
            ["GUID"] = "7FB29E98",
            ["NextDialogue"] = 51009821,
            ["SpeakNpcId"] = 700307,
            },
        [51009821] = {
            ["Content"] = "明明是你说要给她找点事做，不让她一天到晚想着到处乱跑！",
            ["ContentFR"] = "C’est toi qui disais qu’il lui fallait une activité pour qu’elle arrête de traîner dehors toute la journée !",
            ["DialogueId"] = 51009821,
            ["FacialId"] = {
                [1] = "700308:CM_Sad01",
                },
            ["GUID"] = "7FB29EC2",
            ["NextDialogue"] = 51009822,
            ["SpeakNpcId"] = 700308,
            ["TalkActionId"] = {
                [1] = "700308:Explain01_Start",
                },
            },
        [51009822] = {
            ["Content"] = "是我说的，但我是让她有点事做才能老实待在家里，而不是变本加厉地往外跑搞得自己被绑匪盯上！",
            ["ContentFR"] = "Oui, je voulais qu’elle reste tranquille à la maison — pas qu’elle recommence à courir partout jusqu’à attirer l’attention de ravisseurs !",
            ["DialogueId"] = 51009822,
            ["GUID"] = "7FB29EEC",
            ["NextDialogue"] = 51009823,
            ["SpeakNpcId"] = 700307,
            ["TalkActionId"] = {
                [1] = "700307:Angry01_End",
                [2] = "700308:Explain01_End",
                },
            },
        [51009823] = {
            ["Content"] = "还有你们，这群废物卫戍部队！你们到底是干什么吃的？好不容易查到这里有线索，就是因为你们效率太低，才让绑匪跑了！",
            ["ContentFR"] = "Et vous, bande d’incapables ! Vous appelez ça des Veilleurs ? On avait enfin une piste, et parce que vous êtes trop lents, les kidnappeurs se sont enfuis !",
            ["DialogueId"] = 51009823,
            ["GUID"] = "7FB29F16",
            ["NextDialogue"] = 51009824,
            ["Scripts"] = "PARA{\
TurnTo{TurnToDescription{\"700307:n(700313)\"}},\
TurnTo{TurnToDescription{\"700308:n(700313)\"}}\
}",
            ["SpeakNpcId"] = 700307,
            },
        [51009824] = {
            ["Content"] = "……",
            ["ContentFR"] = "...",
            ["DialogueId"] = 51009824,
            ["GUID"] = "7FB29F40",
            ["NextDialogue"] = 51009825,
            ["SpeakNpcId"] = 700313,
            },
        [51009825] = {
            ["Content"] = "该死，我为什么要在大街上对你们这些没脑子的家伙发脾气！我要用其他的渠道去找。",
            ["ContentFR"] = "Pff... pourquoi est-ce que je perds mon temps à crier sur des imbéciles pareils ! Je vais retrouver ma fille moi-même !",
            ["DialogueId"] = 51009825,
            ["GUID"] = "7FB29F6A",
            ["NextDialogue"] = 51009826,
            ["Scripts"] = "PARA{\
LookAt{LookAtDescription{\"700307:n(700307)\"}},\
LookAt{LookAtDescription{\"700308:n(700308)\"}},\
MoveTo{ActorId{700307},MoveSpeed{150},TargetPoint{\"MagnusMPoint_20023205\"}},\
MoveTo{ActorId{700308},MoveSpeed{150},TargetPoint{\"MagnusFPoint_20023205\"}}\
}",
            ["SpeakNpcId"] = 700307,
            },
        [51009826] = {
            ["Camera"] = "-238.418213,-514.537842,220.403809,0.000037,-12.999988,72.598557,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "……呼，可算走了。",
            ["ContentFR"] = "... Ouf. Enfin parti.",
            ["DialogueId"] = 51009826,
            ["GUID"] = "7FB29F94",
            ["NextDialogue"] = 51009827,
            ["SpeakNpcId"] = 700313,
            },
        [51009827] = {
            ["Camera"] = "77.355469,-517.516235,186.296875,0.000047,-11.199768,98.997734,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "抱歉，闲杂人等请止步。",
            ["ContentFR"] = "Veuillez rester à l’écart, s’il vous plaît. Cet endroit est interdit au public.",
            ["DialogueId"] = 51009827,
            ["GUID"] = "7FB29FBE",
            ["NextDialogue"] = 51009828,
            ["Scripts"] = "SEQ{\
MoveTo{ActorId{100001},MoveSpeed{150},TargetPoint{\"NvzhuPoint_20023205\"}},\
TurnTo{TurnToDescription{\"100001:n(700313)\"}}\
}",
            ["SpeakNpcId"] = 700313,
            },
        [51009828] = {
            ["Camera"] = "-445.371338,-206.447021,167.490234,0.00006,-10.999575,13.197603,28.570547,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "不好意思，我只是听到有争吵声，这里发生了什么？",
            ["ContentFR"] = "{性别:Désolé|Désolée}, j’ai entendu des cris... Que se passe-t-il ici ?",
            ["DialogueId"] = 51009828,
            ["FacialId"] = {
                [1] = "100001:Smile01",
                },
            ["GUID"] = "7FB29FE8",
            ["NextDialogue"] = 51009829,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Talk01_Start",
                },
            },
        [51009829] = {
            ["Content"] = "我们收到举报，有人实施了绑架并把受害人囚禁于此，不过等卫戍部队赶到后这里已经没有人了。",
            ["ContentFR"] = "Nous avons reçu un signalement : une personne aurait été kidnappée et retenue ici. Mais quand nous sommes arrivés, les lieux étaient déjà vides.",
            ["DialogueId"] = 51009829,
            ["FacialId"] = {
                [1] = "100001:None",
                },
            ["GUID"] = "7FB2A012",
            ["NextDialogue"] = 51009830,
            ["SpeakNpcId"] = 700313,
            ["TalkActionId"] = {
                [1] = "100001:Talk01_End",
                },
            },
        [51009830] = {
            ["Content"] = "我们已经封锁了这间住宅，如果你只是来看热闹的，就请不要继续靠近了。",
            ["ContentFR"] = "Cette maison est désormais sous scellés. Si tu es simplement venu par curiosité, je te demanderai de ne pas t’approcher davantage.",
            ["DialogueId"] = 51009830,
            ["GUID"] = "7FB2A03C",
            ["NextDialogue"] = 51009831,
            ["SpeakNpcId"] = 700313,
            },
        [51009831] = {
            ["Content"] = "好吧，刚才那二位是？",
            ["ContentFR"] = "D’accord... Et ces deux personnes, c’était qui ?",
            ["DialogueId"] = 51009831,
            ["GUID"] = "7FB2A066",
            ["NextDialogue"] = 51009832,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Talk02_Start",
                },
            },
        [51009832] = {
            ["Content"] = "马格努斯伯爵和他的夫人，受害人的父母。虽然我能理解女儿被人绑架的焦急，不过这二位还真是和传闻一样的臭脾气……",
            ["ContentFR"] = "Le Comte Magnus et son épouse — les parents de la victime. Je comprends qu’ils soient inquiets, mais... disons qu’ils sont fidèles à leur réputation.",
            ["DialogueId"] = 51009832,
            ["GUID"] = "7FB2A090",
            ["NextDialogue"] = 51009833,
            ["SpeakNpcId"] = 700313,
            ["TalkActionId"] = {
                [1] = "100001:Talk02_End",
                },
            },
        [51009833] = {
            ["Content"] = "而且据说他们对女儿的控制欲也很强，说不定罗莎琳小姐就是受不了他们才往外跑。",
            ["ContentFR"] = "On raconte qu’ils étaient très autoritaires avec leur fille. Peut-être que Mademoiselle Rosalind a fui pour échapper à leur emprise...",
            ["DialogueId"] = 51009833,
            ["GUID"] = "7FB2A0BA",
            ["NextDialogue"] = 51009834,
            ["SpeakNpcId"] = 700313,
            },
        [51009834] = {
            ["Content"] = "咳……闲话说太多了。总之还请配合我们执行公务，如果有什么线索也请告知卫戍部队。",
            ["ContentFR"] = "<I>Hum hum.</> Assez bavardé. Si tu obtiens la moindre information, transmets-la aux Veilleurs.",
            ["DialogueId"] = 51009834,
            ["GUID"] = "7FB2A0E4",
            ["NextDialogue"] = 51009835,
            ["SpeakNpcId"] = 700313,
            },
        [51009835] = {
            ["Camera"] = "-99.088623,-74.42334,133.572266,0.000056,-4.199521,-40.602531,28.570547,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "（吉赛尔和……箱子小姐，似乎都不在这里了。）",
            ["ContentFR"] = "<I>Giselle... et Mademoiselle Caisse... ne sont plus là.</>",
            ["DialogueId"] = 51009835,
            ["FacialId"] = {
                [1] = "100001:Doubt01",
                },
            ["GUID"] = "7FB2A10E",
            ["NextDialogue"] = 51009836,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Think_Start",
                },
            },
        [51009836] = {
            ["Content"] = "（绑架……？会和吉赛尔留在水仙平原的那封信有关吗？）",
            ["ContentFR"] = "<I>Un enlèvement ? Est-ce que cela pourrait avoir un lien avec la lettre laissée à la taverne ?</>",
            ["DialogueId"] = 51009836,
            ["GUID"] = "7FB2A138",
            ["NextDialogue"] = 51009837,
            ["SpeakNpcId"] = 100001,
            },
        [51009837] = {
            ["Content"] = "（暂时没有其他头绪，平时如果有空就多留意一下吧。）",
            ["ContentFR"] = "<I>Je n’ai aucune piste pour l’instant... Autant rester vigilant et voir ce qui se passera.</>",
            ["DialogueId"] = 51009837,
            ["GUID"] = "7FB2A162",
            ["SpeakNpcId"] = 100001,
            },
        [51009838] = {
            ["Content"] = "哒……哒哒……",
            ["ContentFR"] = "Da... da da...",
            ["DialogueId"] = 51009838,
            ["GUID"] = "7FB2A163",
            ["SpeakNpcId"] = 700309,
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            },
        [51009850] = {
            ["Camera"] = "-1567.962891,-185.177612,2329.811035,0.000069,-20.199333,74.602768,20.0,100000.0,false,Manual,2.8",
            ["Content"] = "（这两天冰湖城发生了好多事，还涉及到绑架案之类的……）",
            ["ContentFR"] = "<I>Ces derniers jours à Givrelac ont été bien mouvementés... et maintenant, une affaire d’enlèvement est venue s’ajouter au chaos.</>",
            ["DialogueId"] = 51009850,
            ["FinalCamera"] = "-1614.97168,-559.773193,2467.275635,0.000069,-20.199333,74.602768,20.0,100000.0,false,Manual,2.8",
            ["GUID"] = "7FB2A384",
            ["NextDialogue"] = 51009851,
            ["Scripts"] = "SetTag{Tag{\"Huozai04Tag\"},Value{\"Value_1\"}}",
            ["SpeakNpcId"] = 100001,
            ["ToFinalCameraBlendTime"] = 5,
            },
        [51009851] = {
            ["Camera"] = "389.291016,-7961.245117,-744.026855,0.000091,3.00055,131.807861,20.0,100000.0,false,Manual,2.8",
            ["Content"] = "（仔细想想，其中<H>几件事</>似乎和案件有千丝万缕的联系。）",
            ["ContentFR"] = "<I>En y repensant bien, plusieurs événements semblent liés d’une manière ou d’une autre.</>",
            ["DialogueId"] = 51009851,
            ["FinalCamera"] = "712.783569,-8322.950195,-679.47168,0.000091,3.00055,131.807861,20.0,100000.0,false,Manual,2.8",
            ["GUID"] = "7FB2A3AE",
            ["NextDialogue"] = 51009852,
            ["SpeakNpcId"] = 100001,
            ["ToFinalCameraBlendTime"] = 5,
            },
        [51009852] = {
            ["Camera"] = "1489.815308,3777.302246,3313.351074,0.000015,-35.199669,-107.997414,20.0,100000.0,false,Manual,2.8",
            ["Content"] = "（先简单梳理一下吧……）",
            ["ContentFR"] = "<I>Mieux vaut faire le point... et essayer d’assembler les morceaux.</>",
            ["DialogueId"] = 51009852,
            ["FinalCamera"] = "1806.783691,4752.98291,4037.017334,0.000015,-35.199627,-107.997398,20.0,100000.0,false,Manual,2.8",
            ["GUID"] = "7FB2A3D8",
            ["SpeakNpcId"] = 100001,
            ["ToFinalCameraBlendTime"] = 5,
            },
        [51009853] = {
            ["Camera"] = "1806.783691,4752.98291,4037.017334,0.000015,-35.199627,-107.997398,20.0,100000.0,false,Manual,2.8",
            ["Content"] = "（十六年前的绑架案另有隐情，而薇奥莱塔女士很可能知道真相……吉赛尔绑架了她的学生，为的是与薇奥莱塔单独见面……）",
            ["ContentFR"] = "<I>Il y avait plus dans cette affaire que ce que l’on croyait. Et Violetta... elle connaît sûrement la vérité. Giselle a enlevé son élève pour la forcer à se montrer.</>",
            ["DialogueId"] = 51009853,
            ["GUID"] = "7FB2A402",
            ["NextDialogue"] = 51009854,
            ["SpeakNpcId"] = 100001,
            },
        [51009854] = {
            ["Content"] = "（如果推断没错，现在吉赛尔应该已经见到薇奥莱塔了。）",
            ["ContentFR"] = "<I>Si j’ai raison, elles doivent être ensemble en ce moment.</>",
            ["DialogueId"] = 51009854,
            ["GUID"] = "7FB2A42C",
            ["NextDialogue"] = 51009855,
            ["SpeakNpcId"] = 100001,
            },
        [51009855] = {
            ["Content"] = "（我还记得信上的那个地点，必须快点过去……希望没有什么不好的事发生。）",
            ["ContentFR"] = "<I>Je dois me rendre sur place au plus vite... en espérant qu’il ne soit pas trop tard.</>",
            ["DialogueId"] = 51009855,
            ["GUID"] = "7FB2A456",
            ["SpeakNpcId"] = 100001,
            },
        [51009856] = {
            ["Camera"] = "-1404.640625,-280.359375,849.211426,0.00002,-23.200226,22.597872,35.0,100000.0,false,Manual,2.8",
            ["Content"] = "看来你还算准时。",
            ["ContentFR"] = "Tiens, t’es à l’heure finalement.",
            ["DialogueId"] = 51009856,
            ["FacialId"] = {
                [1] = "700302:CM_Smile01",
                },
            ["GUID"] = "7FB2A480",
            ["NextDialogue"] = 51009857,
            ["SpeakNpcId"] = 700302,
            ["TalkActionId"] = {
                [1] = "700302:Confident_Start",
                },
            },
        [51009857] = {
            ["Content"] = "……",
            ["ContentFR"] = "...",
            ["DialogueId"] = 51009857,
            ["GUID"] = "7FB2A4AA",
            ["NextDialogue"] = 51009858,
            ["SpeakNpcId"] = 700300,
            },
        [51009858] = {
            ["Camera"] = "-357.697266,-104.112305,130.897461,0.99998,-2.799988,24.192202,24.205383,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "都到了这个场合，你还打算一言不发吗？我可不是迂腐的法官，如果你想听到“你有权保持沉默”这种话，那可能要失望了。",
            ["ContentFR"] = "Quoi, tu comptes garder le silence ? Ce n’est pas un tribunal ici. Si tu attends qu’on te lise tes droits, tu risques d’attendre longtemps.",
            ["DialogueId"] = 51009858,
            ["GUID"] = "7FB2A4D4",
            ["NextDialogue"] = 51009859,
            ["SpeakNpcId"] = 700302,
            },
        [51009859] = {
            ["Content"] = "你想让我说什么？先来让我听听吧，用这种卑劣的手段，你想得到的是怎样的答案？",
            ["ContentFR"] = "Et qu’est-ce que tu veux que je dise ? Vas-y, je t’écoute. Après un coup aussi bas, quelle réponse attends-tu exactement ?",
            ["DialogueId"] = 51009859,
            ["FacialId"] = {
                [1] = "700300:CM_Angry01",
                },
            ["GUID"] = "7FB2A4FE",
            ["NextDialogue"] = 51009860,
            ["SpeakNpcId"] = 700300,
            },
        [51009860] = {
            ["Camera"] = "148.300781,-316.230469,157.037598,0.999999,-5.400179,115.588638,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "你是在跟我装糊涂吗？还是说，你觉得你做过的恶行也像你的脸一样，可以被你高超的化妆技术轻易遮盖掉？",
            ["ContentFR"] = "Tu te fous de moi ? Ou tu crois vraiment que tes crimes peuvent se maquiller aussi facilement que ton visage ? Tu penses qu’un peu de poudre peut tout effacer ?",
            ["DialogueId"] = 51009860,
            ["GUID"] = "7FB2A528",
            ["NextDialogue"] = 51009861,
            ["SpeakNpcId"] = 700302,
            },
        [51009861] = {
            ["Content"] = "也罢，那我来帮你回忆一下吧。",
            ["ContentFR"] = "Très bien... Laisse-moi rafraîchir ta mémoire.",
            ["DialogueId"] = 51009861,
            ["GUID"] = "7FB2A552",
            ["NextDialogue"] = 51009862,
            ["SpeakNpcId"] = 700302,
            },
        [51009862] = {
            ["Camera"] = "-1404.640625,-280.359375,849.211426,0.00002,-23.200226,22.597872,35.0,100000.0,false,Manual,2.8",
            ["Content"] = "十六年前，冰湖城发生了一起绑架案，一个叫西格的年轻人绑架了时任格雷姆矿场负责人法布瑞斯·鲁斯福德的女儿——艾诺拉·鲁斯福德。",
            ["ContentFR"] = "Il y a seize ans, à Givrelac, un jeune homme nommé Sig a enlevé Enola Ruthford, la fille de Fabrice Ruthford, responsable de la Fosse de Glevum.",
            ["DialogueId"] = 51009862,
            ["GUID"] = "7FB2A57C",
            ["NextDialogue"] = 51009863,
            ["SpeakNpcId"] = 700302,
            },
        [51009863] = {
            ["Content"] = "在抵抗抓捕的过程中，西格不慎点燃了房屋，导致了艾诺拉丧生，而他也因此被判处死刑。",
            ["ContentFR"] = "Lorsqu’il a été acculé par les Veilleurs, Sig a résisté... et a accidentellement mis le feu à la maison. Enola est morte dans l’incendie, et Sig a été condamné à mort.",
            ["DialogueId"] = 51009863,
            ["GUID"] = "7FB2A5A6",
            ["NextDialogue"] = 51009864,
            ["SpeakNpcId"] = 700302,
            },
        [51009864] = {
            ["Camera"] = "-314.688477,142.042969,142.037598,1.000012,-0.599793,-21.008369,40.559872,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "那起陈年旧事我的确有所耳闻。真是一出令人扼腕的悲剧，愿那个可怜的女孩安息。",
            ["ContentFR"] = "Oui, j’ai entendu parler de cette tragédie. Une histoire lamentable... que cette pauvre fille repose en paix.",
            ["DialogueId"] = 51009864,
            ["GUID"] = "7FB2A5D0",
            ["NextDialogue"] = 51009865,
            ["SpeakNpcId"] = 700300,
            ["TalkActionId"] = {
                [1] = "700300:Explain02_Start",
                },
            },
        [51009865] = {
            ["Content"] = "——但我只是近年来才来到冰湖城，那起案件，又和我有什么关系呢？",
            ["ContentFR"] = "Mais je ne suis arrivée à Givrelac que bien plus tard. En quoi cela me concerne-t-il ?",
            ["DialogueId"] = 51009865,
            ["GUID"] = "7FB2A5FA",
            ["NextDialogue"] = 51009866,
            ["SpeakNpcId"] = 700300,
            },
        [51009866] = {
            ["Camera"] = "-357.697266,-104.112305,130.897461,0.99998,-2.799988,24.192202,24.205383,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "当然是因为，那场火灾有一个幸存者。",
            ["ContentFR"] = "Parce qu’il y a eu une survivante.",
            ["DialogueId"] = 51009866,
            ["GUID"] = "7FB2A624",
            ["NextDialogue"] = 51009867,
            ["SpeakNpcId"] = 700302,
            ["TalkActionId"] = {
                [1] = "700300:Explain02_End",
                },
            },
        [51009867] = {
            ["Content"] = "根据一位知情人的说法，在火灾现场除了西格和艾诺拉以外，还有一个人——西格的妹妹，维尔莉特。一个与当年的艾诺拉年岁相仿的女孩。",
            ["ContentFR"] = "Un témoin affirme qu’il y avait trois personnes dans la maison ce soir-là : Sig, Enola... et la sœur de Sig, Violette, une fille du même âge qu’Enola.",
            ["DialogueId"] = 51009867,
            ["GUID"] = "7FB2A64E",
            ["NextDialogue"] = 51009868,
            ["SpeakNpcId"] = 700302,
            },
        [51009868] = {
            ["Content"] = "在混乱的火灾现场，那位知情人救出了当时也在屋子里的维尔莉特……或者说，他<H>以为</>自己救出了维尔莉特。",
            ["ContentFR"] = "Dans le chaos, ce témoin a sorti une jeune fille des flammes — une fille qu’il croyait être Violette. Mais l’était-elle vraiment ?",
            ["DialogueId"] = 51009868,
            ["GUID"] = "7FB2A678",
            ["NextDialogue"] = 51009869,
            ["SpeakNpcId"] = 700302,
            },
        [51009869] = {
            ["Content"] = "到此为止，我说的没错吧？十六年前杀害了维尔莉特，又假扮成她，利用她的身份蒙骗多纳特逃出了冰湖城的你，艾诺拉·鲁斯福德！",
            ["ContentFR"] = "Arrête-moi si je me trompe : tu as tué Violette ce soir-là... puis tu as pris son nom pour tromper Donat et t’échapper de Givrelac, n’est-ce pas, Enola Ruthford ?",
            ["DialogueId"] = 51009869,
            ["FacialId"] = {
                [1] = "700302:CM_Angry01",
                },
            ["GUID"] = "7FB2A6A2",
            ["NextDialogue"] = 51009870,
            ["SpeakNpcId"] = 700302,
            ["TalkActionId"] = {
                [1] = "700302:Angry01_Start",
                },
            },
        [51009870] = {
            ["Camera"] = "-220.682617,16.6875,142.309082,1.000003,-2.999962,-14.610696,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "……呵，有趣的剧本，是不多见的悬疑题材呢。",
            ["ContentFR"] = "... Ah ! Intéressant scénario. Un polar de ce genre, c’est plutôt rare.",
            ["DialogueId"] = 51009870,
            ["FacialId"] = {
                [1] = "700300:CM_Idle",
                },
            ["GUID"] = "7FB2A6CC",
            ["NextDialogue"] = 51009871,
            ["SpeakNpcId"] = 700300,
            ["TalkActionId"] = {
                [1] = "700300:Talk01_Start",
                [2] = "700302:Angry01_End",
                },
            },
        [51009871] = {
            ["Content"] = "说下去，我喜欢听。",
            ["ContentFR"] = "Continue, j’aime bien les histoires.",
            ["DialogueId"] = 51009871,
            ["FacialId"] = {
                [1] = "700302:CM_Idle",
                },
            ["GUID"] = "7FB2A6F6",
            ["NextDialogue"] = 51009872,
            ["SpeakNpcId"] = 700300,
            ["TalkActionId"] = {
                [1] = "700302:Confident_End",
                },
            },
        [51009872] = {
            ["Camera"] = "-357.697266,-104.112305,130.897461,0.99998,-2.799988,24.192202,24.205383,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "这些年我一直在调查那桩案件，烧焦的尸体，幸存的维尔莉特，这一切都太过巧合。",
            ["ContentFR"] = "J’ai passé des années à enquêter sur cette affaire. Un corps méconnaissable... une seule survivante... trop de coïncidences.",
            ["DialogueId"] = 51009872,
            ["GUID"] = "7FB2A720",
            ["NextDialogue"] = 51009873,
            ["SpeakNpcId"] = 700302,
            ["TalkActionId"] = {
                [1] = "700300:Talk01_End",
                [2] = "700302:Think_Start",
                },
            },
        [51009873] = {
            ["Content"] = "这一切似乎都有着某种关联，但破碎的关键词之间缺少一条能将这一切连起来的线。",
            ["ContentFR"] = "Toutes les pièces étaient là, mais il manquait le fil conducteur.",
            ["DialogueId"] = 51009873,
            ["GUID"] = "7FB2A74A",
            ["NextDialogue"] = 51009874,
            ["SpeakNpcId"] = 700302,
            },
        [51009874] = {
            ["Content"] = "如果不是我在卫戍部队期间给法布瑞斯那个家伙当过几天护卫，并且凑巧听到了她女儿的歌声——",
            ["ContentFR"] = "Si je n’avais pas été assignée à la protection de Fabrice Ruthford à l’époque — si je n’avais pas entendu sa fille chanter —",
            ["DialogueId"] = 51009874,
            ["GUID"] = "7FB2A774",
            ["NextDialogue"] = 51009875,
            ["SpeakNpcId"] = 700302,
            },
        [51009875] = {
            ["Camera"] = "-220.682617,16.6875,142.309082,1.000003,-2.999962,-14.610696,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "恐怕我永远都不会把这些和你联系起来，“千面的薇奥莱塔”。",
            ["ContentFR"] = "je n’aurais jamais fait le lien. Cette voix... je la reconnaîtrais entre mille. Voilà comment j’ai su qui tu étais vraiment, « Violetta aux mille visages ».",
            ["DialogueId"] = 51009875,
            ["FacialId"] = {
                [1] = "700300:CM_Sad01",
                },
            ["GUID"] = "7FB2A79E",
            ["NextDialogue"] = 51009876,
            ["SpeakNpcId"] = 700302,
            },
        [51009876] = {
            ["Content"] = "我用各种方法试图调查你的生活习惯，比如……找一些人以送信的名义观察你。",
            ["ContentFR"] = "J’ai même trouvé des moyens d’étudier tes habitudes... par exemple en envoyant quelqu’un t’apporter de fausses lettres pour t’observer.",
            ["DialogueId"] = 51009876,
            ["GUID"] = "7FB2A7C8",
            ["NextDialogue"] = 51009877,
            ["SpeakNpcId"] = 700302,
            ["TalkActionId"] = {
                [1] = "700302:Explain01_Start",
                },
            },
        [51009877] = {
            ["Content"] = "原来那个卫兵是你派来的。",
            ["ContentFR"] = "Donc ce soldat, c’était toi qui l’avais envoyé.",
            ["DialogueId"] = 51009877,
            ["GUID"] = "7FB2A7F2",
            ["NextDialogue"] = 51009878,
            ["SpeakNpcId"] = 700300,
            ["TalkActionId"] = {
                [1] = "700300:Talk01_Start",
                [2] = "700302:Explain01_End",
                },
            },
        [51009878] = {
            ["Content"] = "不，他的确是你的剧迷，我也只是稍稍煽动了一下罢了。多亏了他，我才最终确定了你的身份。",
            ["ContentFR"] = "Pas exactement. C’était vraiment un de tes admirateurs. Je n’ai fait que le pousser un peu dans cette direction. Grâce à lui, j’ai eu la confirmation.",
            ["DialogueId"] = 51009878,
            ["GUID"] = "7FB2A81C",
            ["NextDialogue"] = 51009879,
            ["SpeakNpcId"] = 700302,
            },
        [51009879] = {
            ["Camera"] = "127.291016,-233.679688,146.983398,1.000008,-1.000206,118.987587,38.469608,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "即便如此，我还是有一件事没有搞清楚。",
            ["ContentFR"] = "Mais il reste une chose que je ne comprends pas.",
            ["DialogueId"] = 51009879,
            ["GUID"] = "7FB2A846",
            ["NextDialogue"] = 51009880,
            ["SpeakNpcId"] = 700302,
            },
        [51009880] = {
            ["Content"] = "在火灾中和维尔莉特调换身份，这种方法没有西格和维尔莉特的配合难以实施，你到底是怎么说服他们的？",
            ["ContentFR"] = "Changer d’identité avec Violette n’aurait pas été possible sans leur coopération. Comment les as-tu convaincus ?",
            ["DialogueId"] = 51009880,
            ["GUID"] = "7FB2A870",
            ["NextDialogue"] = 51009881,
            ["SpeakNpcId"] = 700302,
            ["TalkActionId"] = {
                [1] = "700300:Talk01_End",
                [2] = "700302:Think_Start",
                },
            },
        [51009881] = {
            ["Camera"] = "-294.663086,168.334961,176.219727,1.000005,-6.799897,-27.606359,56.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我还以为你要问什么呢……这种事不是很简单吗？",
            ["ContentFR"] = "Je croyais que tu allais poser une question difficile... La réponse est simple.",
            ["DialogueId"] = 51009881,
            ["FacialId"] = {
                [1] = "700300:CM_Smile01",
                },
            ["GUID"] = "7FB2A89A",
            ["NextDialogue"] = 51009882,
            ["SpeakNpcId"] = 700300,
            ["TalkActionId"] = {
                [1] = "700300:Sigh_Start",
                [2] = "700302:Think_End",
                },
            },
        [51009882] = {
            ["Content"] = "我可是那个法布瑞斯的女儿，既然你曾经在父亲的手下工作过，就应该知道触碰他逆鳞的后果。",
            ["ContentFR"] = "J’étais la fille de Fabrice Ruthford. Et tu sais ce que cela signifie de s’opposer à lui.",
            ["DialogueId"] = 51009882,
            ["GUID"] = "7FB2A8C4",
            ["NextDialogue"] = 51009883,
            ["SpeakNpcId"] = 700300,
            ["TalkActionId"] = {
                [1] = "700300:Sigh_End",
                },
            },
        [51009883] = {
            ["Content"] = "可怜的西格早就做好了牺牲自己的准备，但按父亲的作风，维尔莉特也无法幸免。",
            ["ContentFR"] = "Le pauvre Sig savait déjà qu’il n’en sortirait pas vivant... et connaissant mon père, Violette non plus n’avait aucune chance.",
            ["DialogueId"] = 51009883,
            ["GUID"] = "7FB2A8EE",
            ["NextDialogue"] = 51009884,
            ["SpeakNpcId"] = 700300,
            },
        [51009884] = {
            ["Content"] = "而我则告诉他们：唯一的办法，就是在拿到赎金后尽可能拖延时间，同时想办法制造混乱让维尔莉特逃跑。",
            ["ContentFR"] = "Je leur ai proposé une solution : après avoir reçu la rançon, ils n’avaient qu’à gagner du temps, créer la confusion, et donner à Violette une chance de s’échapper.",
            ["DialogueId"] = 51009884,
            ["GUID"] = "7FB2A918",
            ["NextDialogue"] = 51009885,
            ["SpeakNpcId"] = 700300,
            },
        [51009885] = {
            ["Content"] = "真是可笑，惊慌失措的他居然真的独自去拖延卫戍部队，期待一个重病的小姑娘在火灾中逃出生天……",
            ["ContentFR"] = "Pathétique, non ? Dans sa panique, il a affronté les Veilleurs seul, espérant qu’une fillette malade s’échapperait d’une maison en feu...",
            ["DialogueId"] = 51009885,
            ["GUID"] = "7FB2A942",
            ["NextDialogue"] = 51009886,
            ["SpeakNpcId"] = 700300,
            ["TalkActionId"] = {
                [1] = "700300:Talk02_Start",
                },
            },
        [51009886] = {
            ["Content"] = "我抓住了这个机会，杀死了那个碍事的小可怜，用她的身份摆脱了那栋破房子，也摆脱了我的父亲，摆脱了所有阻止我踏上舞台的一切。",
            ["ContentFR"] = "J’ai saisi ma chance. J’ai tué cette pauvre enfant qui se trouvait sur mon chemin. J’ai pris son nom. J’ai laissé derrière moi cette maison pourrie... et mon père. J’ai laissé derrière moi tout ce qui m’empêchait de monter sur scène.",
            ["DialogueId"] = 51009886,
            ["GUID"] = "7FB2A96C",
            ["NextDialogue"] = 51009887,
            ["SpeakNpcId"] = 700300,
            },
        [51009887] = {
            ["Camera"] = "96.022461,-329.655273,121.388672,0.999973,0.800034,107.991287,33.074104,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "……",
            ["ContentFR"] = "...",
            ["DialogueId"] = 51009887,
            ["FacialId"] = {
                [1] = "700302:CM_Angry01",
                },
            ["GUID"] = "7FB2A996",
            ["NextDialogue"] = 51009888,
            ["SpeakNpcId"] = 700302,
            },
        [51009888] = {
            ["Content"] = "啊呀，得到了自己十几年来日思夜想的真相，你看起来并不开心，吉赛尔女士。",
            ["ContentFR"] = "Qu’y a-t-il, Giselle ? Tu poursuis cette vérité depuis des années... et maintenant que tu l’as, tu ne sembles pas ravie.",
            ["DialogueId"] = 51009888,
            ["FacialId"] = {
                [1] = "700300:CM_Smile01",
                },
            ["GUID"] = "7FB2A9C0",
            ["NextDialogue"] = 51009889,
            ["SpeakNpcId"] = 700300,
            },
        [51009889] = {
            ["Content"] = "不可理喻……就为了这种理由？就为了这种理由害死了两个人？！你把人命当成什么了！",
            ["ContentFR"] = "T’es complètement folle... Tout ça, juste pour les projecteurs ?! Tu as tué deux personnes innocentes !",
            ["DialogueId"] = 51009889,
            ["GUID"] = "7FB2A9EA",
            ["NextDialogue"] = 51009890,
            ["SpeakNpcId"] = 700302,
            ["TalkActionId"] = {
                [1] = "700302:Angry01_Start",
                [2] = "700300:Talk02_End",
                },
            },
        [51009890] = {
            ["Content"] = "那么你打算怎么做？去满世界宣扬薇奥莱塔的恶毒手段让我身败名裂？又或者……现在就为他们两人报仇？",
            ["ContentFR"] = "Alors, que vas-tu faire ? Révéler mes crimes au grand jour pour ruiner ma réputation ? Ou bien... venger leur mort ici et maintenant ?",
            ["DialogueId"] = 51009890,
            ["GUID"] = "7FB2AA14",
            ["NextDialogue"] = 51009891,
            ["SpeakNpcId"] = 700300,
            ["TalkActionId"] = {
                [1] = "700300:Confident_Start",
                },
            },
        [51009891] = {
            ["Content"] = "……我原本只是想揭露这一切，然后把你交给卫戍部队。",
            ["ContentFR"] = "... Je voulais seulement révéler la vérité... et te livrer aux Veilleurs.",
            ["DialogueId"] = 51009891,
            ["GUID"] = "7FB2AA3E",
            ["NextDialogue"] = 51009892,
            ["SpeakNpcId"] = 700302,
            },
        [51009892] = {
            ["Content"] = "（吉赛尔从腰间拔出匕首，她愤怒的神情，让你似乎感觉自己听到了攥紧刀柄，又或者是几乎要把牙齿咬碎的碾磨声。）",
            ["ContentFR"] = "Giselle dégaine un poignard. La tension est palpable. Tu entends presque le cuir craquer sous la force de sa poigne, et le grincement de ses dents serrées.",
            ["DialogueId"] = 51009892,
            ["GUID"] = "7FB2AA68",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 51009893,
            ["TalkActionId"] = {
                [1] = "700302:Angry01_End",
                },
            },
        [51009893] = {
            ["Content"] = "（如果再不阻止她，那柄利刃毫无疑问会在下一刻划开这冰湖城最美妙的歌喉。无论如何，一场命案是你不愿看到的。）",
            ["ContentFR"] = "Si personne ne l’arrête, cette lame mettra bientôt fin à la plus belle voix de Givrelac... Quoi qu’il en soit, tu ne peux pas rester là à regarder quelqu’un commettre un meurtre.",
            ["DialogueId"] = 51009893,
            ["GUID"] = "7FB2AA69",
            ["IsBlack"] = 1,
            },
        [51009894] = {
            ["Content"] = "{nickname}？你为什么会在这里？",
            ["ContentFR"] = "{nickname}... ? Qu’est-ce que tu fais ici ?",
            ["DialogueId"] = 51009894,
            ["GUID"] = "7FB2AABC",
            ["NextDialogue"] = 51009895,
            ["SpeakNpcId"] = 700300,
            },
        [51009895] = {
            ["Content"] = "闪开，我无法容忍这样的败类继续活在世上！",
            ["ContentFR"] = "Écarte-toi. Je ne laisserai pas une ordure comme elle vivre une minute de plus !",
            ["DialogueId"] = 51009895,
            ["GUID"] = "7FB2AAE6",
            ["NextDialogue"] = 51009896,
            ["SpeakNpcId"] = 700302,
            ["TalkActionId"] = {
                [1] = "700302:Angry01_Start",
                },
            },
        [51009896] = {
            ["Content"] = "（吉赛尔似乎因愤怒失去了理智，得想办法让她冷静下来。）",
            ["ContentFR"] = "<I>Elle a complètement perdu les pédales... Je dois trouver un moyen de la calmer.</>",
            ["DialogueId"] = 51009896,
            ["FacialId"] = {
                [1] = "100001:Doubt01",
                },
            ["GUID"] = "7FB2AB10",
            ["SpeakNpcId"] = 100001,
            },
        [51009897] = {
            ["Camera"] = "-19.636719,461.339844,156.540039,0.000053,-6.400208,-95.20314,35.333332,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "冷静下来，吉赛尔，或许事情并不是你想的那样。",
            ["ContentFR"] = "Calme-toi, Giselle. Il y a peut-être plus dans cette histoire que ce que tu crois.",
            ["DialogueId"] = 51009897,
            ["GUID"] = "7FB2AB3A",
            ["NextDialogue"] = 51009898,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Talk02R_Start",
                },
            },
        [51009898] = {
            ["Content"] = "你听到她刚才说的那些话了吗？这让我怎么冷静？！",
            ["ContentFR"] = "Tu as entendu ce qu’elle vient d’avouer ?! Tu crois vraiment que je peux rester calme après ça ?!",
            ["DialogueId"] = 51009898,
            ["FacialId"] = {
                [1] = "700302:CM_Angry01",
                },
            ["GUID"] = "7FB2AB64",
            ["NextDialogue"] = 51009899,
            ["SpeakNpcId"] = 700302,
            ["TalkActionId"] = {
                [1] = "700302:Angry01_Start",
                },
            },
        [51009899] = {
            ["Content"] = "有我们两个在这里，她跑不掉的。所以，至少先冷静下来让我问她几个问题！",
            ["ContentFR"] = "Elle ne s’échappera pas, pas avec nous deux ici. Alors souffle un bon coup... et laisse-moi lui poser quelques questions.",
            ["DialogueId"] = 51009899,
            ["GUID"] = "7FB2AB8E",
            ["NextDialogue"] = 51009900,
            ["SpeakNpcId"] = 100001,
            },
        [51009900] = {
            ["Camera"] = "157.706055,-54.485352,141.052246,0.0001,-1.599849,150.594193,53.202648,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "…………",
            ["ContentFR"] = "...",
            ["DialogueId"] = 51009900,
            ["FacialId"] = {
                [1] = "700302:CM_Idle",
                },
            ["GUID"] = "7FB2ABB8",
            ["NextDialogue"] = 51009901,
            ["SpeakNpcId"] = 700302,
            ["TalkActionId"] = {
                [1] = "700302:Angry01_End",
                },
            },
        [51009901] = {
            ["Content"] = "你问吧。",
            ["ContentFR"] = "Très bien. Vas-y, pose-les.",
            ["DialogueId"] = 51009901,
            ["GUID"] = "7FB2ABE2",
            ["NextDialogue"] = 51009902,
            ["SpeakNpcId"] = 700302,
            ["TalkActionId"] = {
                [1] = "700302:Talk03_Start",
                [2] = "100001:Talk02R_End",
                },
            ["TurnTo"] = {
                [1] = "100001:n(700300)",
                [2] = "700300:n(100001)",
                },
            },
        [51009902] = {
            ["Camera"] = "-62.486328,-300.395508,128.418945,0.000093,0.0,73.193901,35.333332,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "在那之前，薇奥莱塔女士，这个东西你有印象吗？",
            ["ContentFR"] = "Avant toute chose... Madame Violetta, est-ce que cet objet te dit quelque chose ?",
            ["DialogueId"] = 51009902,
            ["DialoguePanelType"] = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_ChapterFire_Ribbon02.T_Guide_ChapterFire_Ribbon02'}",
            ["GUID"] = "7FB2AC0C",
            ["NextDialogue"] = 51009903,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Give",
                },
            },
        [51009903] = {
            ["Content"] = "那是……",
            ["ContentFR"] = "C’est...",
            ["DialogueId"] = 51009903,
            ["FacialId"] = {
                [1] = "700300:CM_Shock01",
                },
            ["GUID"] = "7FB2AC36",
            ["NextDialogue"] = 51009904,
            ["SpeakNpcId"] = 700300,
            ["TalkActionId"] = {
                [1] = "700300:Sigh_Start",
                },
            },
        [51009904] = {
            ["Content"] = "（薇奥莱塔下意识地将手伸向自己脑后，在确认到熟悉的触感后愣在了原地。）",
            ["ContentFR"] = "Violetta lève instinctivement la main vers l’arrière de sa tête. Ses doigts frôlent une texture familière... puis elle se fige, comme frappée par la réalité.",
            ["DialogueId"] = 51009904,
            ["GUID"] = "7FB2AC60",
            ["NextDialogue"] = 51009905,
            ["Scripts"] = "PlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt01/0036_story_renweidaozu\"}}",
            },
        [51009905] = {
            ["Content"] = "看你的反应，我想的果然没错……这条缎带，是你放在西格墓前的吧？",
            ["ContentFR"] = "Vu ta réaction, je ne me trompais pas... C’est toi qui as déposé ce ruban sur la tombe de Sig, n’est-ce pas ?",
            ["DialogueId"] = 51009905,
            ["GUID"] = "7FB2AC8A",
            ["NextDialogue"] = 51009906,
            ["SpeakNpcId"] = 100001,
            },
        [51009906] = {
            ["Content"] = "你曾经告诉过我，这条缎带来自你的一位挚友，你是为了她的梦想才站上舞台的。",
            ["ContentFR"] = "Tu m’avais dit qu’il appartenait à une amie très chère, et que si tu avais choisi de monter sur scène, c’était pour accomplir son rêve.",
            ["DialogueId"] = 51009906,
            ["GUID"] = "7FB2ACB4",
            ["NextDialogue"] = 51009907,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "700300:Sigh_End",
                },
            },
        [51009907] = {
            ["Content"] = "你还真是个天真的傻瓜，居然连那么肉麻的谎言也会相信。",
            ["ContentFR"] = "Tu es vraiment {性别:un idiot naïf|une idiote naïve}. Je n’aurais jamais cru que tu pourrais gober une histoire aussi mielleuse.",
            ["DialogueId"] = 51009907,
            ["FacialId"] = {
                [1] = "700300:CM_Sad01",
                },
            ["GUID"] = "7FB2ACDE",
            ["NextDialogue"] = 51009908,
            ["SpeakNpcId"] = 700300,
            },
        [51009908] = {
            ["Camera"] = "233.676758,-71.671875,155.098145,0.000096,-6.00058,179.598373,35.333332,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "或许吧，所以我去找多纳特借来了这条缎带，并且确认了它的来历。",
            ["ContentFR"] = "Peut-être bien. C’est pour ça que je suis allé demander la vérité à Donat — en lui empruntant ce ruban.",
            ["DialogueId"] = 51009908,
            ["FacialId"] = {
                [1] = "100001:Smile01",
                },
            ["GUID"] = "7FB2AD08",
            ["NextDialogue"] = 51009909,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Talk02R_Start",
                },
            },
        [51009909] = {
            ["Content"] = "多纳特告诉了我维尔莉特的事。他说那是个才华横溢的姑娘，如果不是贫穷和罹患重病，她也许会成为一名优秀的剧作家。",
            ["ContentFR"] = "Il m’a parlé de Violette. Il a dit que c’était une fille incroyablement talentueuse. Sans la pauvreté ni la maladie, elle serait sans doute devenue une grande dramaturge.",
            ["DialogueId"] = 51009909,
            ["GUID"] = "7FB2AD32",
            ["NextDialogue"] = 51009910,
            ["SpeakNpcId"] = 100001,
            },
        [51009910] = {
            ["Content"] = "虽然命运没能眷顾那个女孩，但她从未放弃。即便几乎不能下床行动，她也还是用另外的方式追寻着自己的梦想。",
            ["ContentFR"] = "Le destin ne lui a pas souri, mais elle n’a jamais abandonné. Même clouée au lit, elle a continué à poursuivre son rêve, à sa façon.",
            ["DialogueId"] = 51009910,
            ["GUID"] = "7FB2AD5C",
            ["NextDialogue"] = 51009911,
            ["SpeakNpcId"] = 100001,
            },
        [51009911] = {
            ["Content"] = "她希望能让世界上最好的演员表演她创作的作品，把她在生命的最后写下的她最满意的故事传遍整个阿特拉西亚。",
            ["ContentFR"] = "Elle voulait que la plus grande comédienne du monde joue son œuvre, et que l’histoire qu’elle avait écrite, la dernière et la plus belle, fasse le tour de tout Atlasia.",
            ["DialogueId"] = 51009911,
            ["GUID"] = "7FB2AD86",
            ["NextDialogue"] = 51009912,
            ["SpeakNpcId"] = 100001,
            },
        [51009912] = {
            ["Content"] = "那部作品的名字是——",
            ["ContentFR"] = "Cette œuvre, c’était—",
            ["DialogueId"] = 51009912,
            ["GUID"] = "7FB2ADB0",
            ["NextDialogue"] = 51009913,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Talk02R_End",
                },
            },
        [51009913] = {
            ["Camera"] = "-62.486328,-300.395508,128.418945,0.000093,0.0,73.193901,35.333332,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "……三幕剧《普蒂妮》。后来被改编为同名歌剧。",
            ["ContentFR"] = "... <I>Putini</>. Une pièce en trois actes. Elle a ensuite été adaptée en opéra.",
            ["DialogueId"] = 51009913,
            ["GUID"] = "7FB2ADDA",
            ["NextDialogue"] = 51009914,
            ["SpeakNpcId"] = 700300,
            ["TalkActionId"] = {
                [1] = "700300:Agree",
                },
            },
        [51009914] = {
            ["Camera"] = "233.676758,-71.671875,155.098145,0.000096,-6.00058,179.598373,35.333332,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "嗯，你已经意识到了，继续说谎只会让你的处境更危险。所以……",
            ["ContentFR"] = "Exactement. Tu comprends maintenant que mentir davantage ne ferait qu’aggraver ta situation. Alors...",
            ["DialogueId"] = 51009914,
            ["GUID"] = "7FB2AE04",
            ["NextOptions"] = {
                [1] = 510098241,
                [2] = 510098242,
                },
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:ConfidentLR_Start",
                },
            },
        [51009915] = {
            ["Camera"] = "-62.486328,-300.395508,128.418945,0.000093,0.0,73.193901,35.333332,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "说的也是，剧本总该有结局的。",
            ["ContentFR"] = "Tu as raison... toute pièce mérite une fin.",
            ["DialogueId"] = 51009915,
            ["GUID"] = "7FB2AE2E",
            ["NextDialogue"] = 51009917,
            ["SpeakNpcId"] = 700300,
            ["TalkActionId"] = {
                [1] = "700300:Agree",
                },
            },
        [51009916] = {
            ["Camera"] = "-62.486328,-300.395508,128.418945,0.000093,0.0,73.193901,35.333332,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "在这种时候说悬疑剧的经典台词吗……",
            ["ContentFR"] = "... Vraiment ? C’est le moment que tu choisis pour citer un polar ?",
            ["DialogueId"] = 51009916,
            ["GUID"] = "7FB2AE58",
            ["NextDialogue"] = 51009917,
            ["SpeakNpcId"] = 700300,
            ["TalkActionId"] = {
                [1] = "700300:Disagree",
                },
            },
        [51009917] = {
            ["Content"] = "如果每一部悬疑剧的观众都如你一样敏锐，那些剧作家也无需绞尽脑汁思考如何把剧本再改简单些了。",
            ["ContentFR"] = "Si tous les spectateurs étaient aussi perspicaces que toi, les dramaturges n’auraient plus besoin de se casser la tête à rendre leurs intrigues plus simples.",
            ["DialogueId"] = 51009917,
            ["GUID"] = "7FB2AE82",
            ["NextDialogue"] = 51009918,
            ["SpeakNpcId"] = 700300,
            },
        [51009918] = {
            ["Camera"] = "167.182617,-305.451172,119.724609,0.000095,2.599987,124.794083,44.87347,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "你们在说什么？这是什么意思？",
            ["ContentFR"] = "Qu’est-ce que vous racontez tous les deux ? Que signifie tout ça ?",
            ["DialogueId"] = 51009918,
            ["GUID"] = "7FB2AEAC",
            ["LookAt"] = {
                [1] = "100001:n(700302)",
                },
            ["NextDialogue"] = 51009919,
            ["SpeakNpcId"] = 700302,
            ["TalkActionId"] = {
                [1] = "100001:ConfidentLR_End",
                },
            ["TurnTo"] = {
                [1] = "700300:n(700302)",
                },
            },
        [51009919] = {
            ["Camera"] = "-19.636719,461.339844,156.540039,0.000053,-6.400208,-95.20314,35.333332,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "很简单，吉赛尔。如果薇奥莱塔真的只把维尔莉特当做随意丢弃的工具，她怎么会给自己取一个和维尔莉特如此相似的名字呢？",
            ["ContentFR"] = "C’est très simple, Giselle. Si Violetta avait vraiment considéré Violette comme un simple outil à jeter, pourquoi aurait-elle choisi un nom si proche du sien ?",
            ["DialogueId"] = 51009919,
            ["GUID"] = "7FB2AED6",
            ["NextDialogue"] = 51009920,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Talk01_Start",
                },
            },
        [51009920] = {
            ["Camera"] = "-1216.617188,-202.104492,761.92041,0.000021,-23.200226,22.597822,35.0,100000.0,false,Manual,2.8",
            ["Content"] = "我继续说我的猜测吧：十六年前，西格为了筹到钱给维尔莉特治病，绑架了艾诺拉·鲁斯福德……也就是如今的薇奥莱塔。",
            ["ContentFR"] = "Laisse-moi te raconter ce que je crois : il y a seize ans, Sig a enlevé Enola Ruthford — celle qui se fait appeler aujourd’hui Violetta — pour réunir de quoi soigner sa sœur.",
            ["DialogueId"] = 51009920,
            ["FinalCamera"] = "-1418.189453,-286.000977,855.499756,0.000021,-23.200226,22.597822,35.0,100000.0,false,Manual,2.8",
            ["GUID"] = "7FB2AF00",
            ["NextDialogue"] = 51009921,
            ["SpeakNpcId"] = 100001,
            ["ToFinalCameraBlendTime"] = 10,
            },
        [51009921] = {
            ["Content"] = "在被绑架的期间，艾诺拉结识了生病卧床的维尔莉特。你们就是在那时成为了挚友。",
            ["ContentFR"] = "Pendant sa captivité, Enola a rencontré Violette, malade et alitée. Et pendant ce court laps de temps, elles sont devenues amies.",
            ["DialogueId"] = 51009921,
            ["GUID"] = "7FB2AF2A",
            ["NextDialogue"] = 51009922,
            ["SpeakNpcId"] = 100001,
            },
        [51009922] = {
            ["Content"] = "但好景不长……",
            ["ContentFR"] = "Mais leur bonheur n’a pas duré...",
            ["DialogueId"] = 51009922,
            ["GUID"] = "7FB2AF54",
            ["NextDialogue"] = 51009923,
            ["SpeakNpcId"] = 100001,
            },
        [51009923] = {
            ["Content"] = "维尔莉特察觉到了自己已经时日无多，她不希望哥哥为了虚无缥缈的可能性一错再错，于是写信给哥哥的好友多纳特，希望他阻止西格。",
            ["ContentFR"] = "Violette savait que ses jours étaient comptés. Elle ne voulait pas que son frère s’enfonce plus profondément dans l’erreur. Alors elle a écrit à Donat, l’ami de Sig, pour lui demander d’intervenir.",
            ["DialogueId"] = 51009923,
            ["GUID"] = "7FB2AF7E",
            ["NextDialogue"] = 51009924,
            ["SpeakNpcId"] = 100001,
            },
        [51009924] = {
            ["Content"] = "如她所想，多纳特最终还是找到了吉赛尔，向你举报了西格绑架了艾诺拉的事。不过我猜，那个时候恐怕维尔莉特已经……",
            ["ContentFR"] = "Comme elle l’espérait, Donat a fini par venir te trouver, Giselle, et t’a dénoncé l’enlèvement d’Enola. Mais à ce moment-là, je suppose que Violette était déjà...",
            ["DialogueId"] = 51009924,
            ["GUID"] = "7FB2AFA8",
            ["NextDialogue"] = 51009925,
            ["SpeakNpcId"] = 100001,
            },
        [51009925] = {
            ["Camera"] = "-158.601562,204.59082,150.237305,0.000071,-3.199944,-50.20327,35.333332,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "啊……说来好笑，明明是被人绑架，但那段时光却是我出生以来最快乐的回忆。",
            ["ContentFR"] = "Ah... ironique, n’est-ce pas ? J’étais censée être une otage, et pourtant... ce furent les jours les plus heureux de ma vie.",
            ["DialogueId"] = 51009925,
            ["FacialId"] = {
                [1] = "700300:CM_Smile01",
                },
            ["FinalCamera"] = "-91.950195,124.576172,144.41748,0.000071,-3.199944,-50.20327,35.333332,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "7FB2AFD2",
            ["LookAt"] = {
                [1] = "100001:n(700300)",
                },
            ["NextDialogue"] = 51009926,
            ["SpeakNpcId"] = 700300,
            ["TalkActionId"] = {
                [1] = "700300:Explain02_Start",
                },
            ["ToFinalCameraBlendTime"] = 15,
            },
        [51009926] = {
            ["Content"] = "虽然把我绑在了房间里，但西格并没有打算伤害我，甚至并未对我有过多的关注，只是在屋子里匆忙地走来走去。",
            ["ContentFR"] = "Sig m’avait attachée dans une pièce, mais il n’avait aucune intention de me faire du mal. Il ne faisait que marcher nerveusement de long en large.",
            ["DialogueId"] = 51009926,
            ["GUID"] = "7FB2AFFC",
            ["NextDialogue"] = 51009927,
            ["SpeakNpcId"] = 700300,
            },
        [51009927] = {
            ["Content"] = "当时的我清楚地知道屋子里还有第三个人，那是个女孩子，总会在心情好的时候哼着歌……",
            ["ContentFR"] = "Je savais qu’il y avait une autre personne dans la maison — une jeune fille. Je l’entendais fredonner doucement, les jours où elle se sentait bien...",
            ["DialogueId"] = 51009927,
            ["GUID"] = "7FB2B026",
            ["NextDialogue"] = 51009928,
            ["SpeakNpcId"] = 700300,
            },
        [51009928] = {
            ["Content"] = "或许是因为西格实在无法同时照顾两个无法自理的人，所以几天后，他给我解了绑，允许我在一楼自由行动。",
            ["ContentFR"] = "Peut-être a-t-il compris qu’il ne pouvait pas s’occuper de deux personnes à la fois. Quelques jours plus tard, il m’a détachée et m’a laissée me déplacer librement au rez-de-chaussée.",
            ["DialogueId"] = 51009928,
            ["GUID"] = "7FB2B050",
            ["NextDialogue"] = 51009929,
            ["SpeakNpcId"] = 700300,
            },
        [51009929] = {
            ["Camera"] = "-91.950195,124.576172,144.41748,0.000071,-3.199944,-50.20327,35.333332,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我总是在他外出的时候去二楼和维尔莉特偷偷见面，我们会一起聊她写的故事。她会把她的想法告诉我，而我则把存在于她想象中的画面表演出来。",
            ["ContentFR"] = "Chaque fois qu’il sortait, je montais discrètement voir Violette à l’étage. Elle me lisait ses histoires, et moi, je les jouais — je leur donnais vie.",
            ["DialogueId"] = 51009929,
            ["GUID"] = "7FB2B07A",
            ["NextDialogue"] = 51009930,
            ["SpeakNpcId"] = 700300,
            },
        [51009930] = {
            ["Content"] = "“亲爱的人儿，请不要为我悲伤！在这个无眠之夜，我将远航——”",
            ["ContentFR"] = "« Mon bien-aimé, ne pleure pas pour moi ! En cette nuit sans sommeil, je mets les voiles sous la lumière argentée — »",
            ["DialogueId"] = 51009930,
            ["GUID"] = "7FB2B0A4",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
            ["NextDialogue"] = 51009931,
            ["SpeakNpcId"] = 700300,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Anora",
            },
        [51009931] = {
            ["Content"] = "“风儿鼓起船帆，我撑起木桨——灯塔映在海里啊，月光多明亮！”",
            ["ContentFR"] = "« Le vent gonfle ma voile, la marée embrasse mon aviron... le phare s’illumine dans la mer, et la lune brille si fort ! »",
            ["DialogueId"] = 51009931,
            ["GUID"] = "7FB2B0CE",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
            ["NextDialogue"] = 51009932,
            ["SpeakNpcId"] = 700300,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Anora",
            },
        [51009932] = {
            ["Content"] = "谢谢你，艾诺拉……你演得很好，很好。呵呵……我想象中的普蒂妮啊，她就是你的样子……热烈，勇敢，心儿永远向着自由……",
            ["ContentFR"] = "Merci, Enola... C’était magnifique. Dans mon esprit, Putini t’a toujours ressemblé : passionnée, courageuse, toujours en quête de liberté...",
            ["DialogueId"] = 51009932,
            ["GUID"] = "7FB2B0F8",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
            ["NextDialogue"] = 51009933,
            ["SpeakNpcId"] = 700300,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Violet",
            },
        [51009933] = {
            ["Content"] = "谢谢！这个是我自己瞎唱的……不过我认识一位很优秀的作曲家！他叫卡瓦拉多西。我们可以拜托他把《普蒂妮》改编成歌剧——",
            ["ContentFR"] = "Merci ! J’ai un peu improvisé... Mais je connais un compositeur talentueux, Cavaradossi. Peut-être pourrait-il adapter <I>Putini</> en opéra...",
            ["DialogueId"] = 51009933,
            ["GUID"] = "7FB2B122",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
            ["NextDialogue"] = 51009934,
            ["SpeakNpcId"] = 700300,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Anora",
            },
        [51009934] = {
            ["Content"] = "……不过我应该没有机会演唱了。",
            ["ContentFR"] = "... Mais je n’aurai sans doute jamais l’occasion de la chanter.",
            ["DialogueId"] = 51009934,
            ["GUID"] = "7FB2B14C",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
            ["NextDialogue"] = 51009935,
            ["SpeakNpcId"] = 700300,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Anora",
            },
        [51009935] = {
            ["Content"] = "我已经十八岁了。父亲已经给我安排好了婚事，就在两个月后。对方也是炼金院的年轻长官。",
            ["ContentFR"] = "J’ai dix-huit ans. Mon père m’a déjà trouvé un mari, un jeune officier de l’Académie d’Alchimie. Le mariage est dans deux mois.",
            ["DialogueId"] = 51009935,
            ["GUID"] = "7FB2B176",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
            ["NextDialogue"] = 51009936,
            ["SpeakNpcId"] = 700300,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Anora",
            },
        [51009936] = {
            ["Content"] = "我想我接下来的一生，不是要待在小房间里做个瓷娃娃一样的漂亮摆件，就是要和那些该死的月髓液罐子打一辈子交道了。",
            ["ContentFR"] = "Je suppose que je finirai ma vie en poupée de porcelaine dans un salon... ou les mains plongées à jamais dans ces maudits flacons de Phoxichor.",
            ["DialogueId"] = 51009936,
            ["GUID"] = "7FB2B1A0",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
            ["NextDialogue"] = 51009937,
            ["SpeakNpcId"] = 700300,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Anora",
            },
        [51009937] = {
            ["Content"] = "不，不……艾诺拉，不应该是这样的——你有着云雀一样的歌喉……你不属于小房间……而是更大的，更大的舞台……",
            ["ContentFR"] = "Non... non, Enola, ce n’est pas ce qui doit t’arriver. Ta voix est celle d’une alouette... Tu n’es pas faite pour un petit salon. Tu es faite pour la scène — la plus grande de toutes.",
            ["DialogueId"] = 51009937,
            ["GUID"] = "7FB2B1CA",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
            ["NextDialogue"] = 51009938,
            ["SpeakNpcId"] = 700300,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Violet",
            },
        }
  end },
  { MinKey = 51009938, MaxKey = 51010137, Loader = function()
      return {
        [51009938] = {
            ["Content"] = "每一个热爱歌唱的人……都有资格在舞台上熠熠发光……无论是索拉还是卡戎，是富有还是贫穷……",
            ["ContentFR"] = "Chaque personne qui aime chanter mérite de briller sous les projecteurs — qu’elle soit Sola ou Charon, riche ou pauvre...",
            ["DialogueId"] = 51009938,
            ["GUID"] = "7FB2B1F4",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
            ["NextDialogue"] = 51009939,
            ["SpeakNpcId"] = 700300,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Violet",
            },
        [51009939] = {
            ["Content"] = "我会想办法让哥哥放你离开。我的身体已经没有办法了，我不知道还有没有机会把《普蒂妮》的最后一幕写完……",
            ["ContentFR"] = "Je trouverai un moyen pour que mon frère te laisse partir. Mon corps me lâche déjà... Je ne sais pas si j’aurai le temps d’écrire la dernière scène de <I>Putini</>...",
            ["DialogueId"] = 51009939,
            ["GUID"] = "7FB2B21E",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
            ["NextDialogue"] = 51009940,
            ["SpeakNpcId"] = 700300,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Violet",
            },
        [51009940] = {
            ["Content"] = "但艾诺拉，请你答应我，一定要走上舞台，把我们的《普蒂妮》唱给所有人……",
            ["ContentFR"] = "Mais Enola... promets-moi que tu monteras sur scène. Que tu feras entendre notre <I>Putini</> au monde entier...",
            ["DialogueId"] = 51009940,
            ["GUID"] = "7FB2B248",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
            ["NextDialogue"] = 51009941,
            ["SpeakNpcId"] = 700300,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Violet",
            },
        [51009941] = {
            ["Content"] = "“每一个热爱歌唱的人，都有资格在舞台上熠熠发光。无论他们是索拉还是卡戎，是富有还是贫穷。”这是维尔莉特的遗愿，也是我一生的箴言。",
            ["ContentFR"] = "« Chaque personne qui aime chanter mérite de briller sous les projecteurs. » C’était la dernière volonté de Violette... et c’est devenu ma raison de vivre.",
            ["DialogueId"] = 51009941,
            ["GUID"] = "7FB2B272",
            ["NextDialogue"] = 51009942,
            ["SpeakNpcId"] = 700300,
            },
        [51009942] = {
            ["Content"] = "……后来，当我在维尔莉特病逝后，在颓废的西格面前唱出终于完稿的《普蒂妮》最后一幕时，他的眼里充满惊讶，却又像是在一片死灰中稍稍燃起了火星。",
            ["ContentFR"] = "... Quand elle est morte, j’ai chanté le dernier acte de <I>Putini</> devant Sig. Il était vidé par la douleur... mais dans ses yeux, j’ai vu une étincelle renaître des cendres.",
            ["DialogueId"] = 51009942,
            ["GUID"] = "7FB2B29C",
            ["NextDialogue"] = 51009943,
            ["SpeakNpcId"] = 700300,
            },
        [51009943] = {
            ["Content"] = "我们仍有弥补维尔莉特的机会，她的快乐、她的忧伤、她的希望、她的思念全都寄存在这部作品里。我想让这部作品闻名世界——我可以做到，我也必须做到。",
            ["ContentFR"] = "Nous avions encore une chance de faire vivre Violette à travers son œuvre. Sa joie, sa tristesse, son espoir, sa nostalgie — tout est dans cette pièce. Je voulais la faire connaître au monde. Je devais le faire.",
            ["DialogueId"] = 51009943,
            ["GUID"] = "7FB2B2C6",
            ["NextDialogue"] = 51009944,
            ["SpeakNpcId"] = 700300,
            },
        [51009944] = {
            ["Content"] = "她和我都是为舞台而生的，即便病魔就这样让一位天才陨落，我也要带着她的灵魂踏上舞台。",
            ["ContentFR"] = "Nous étions toutes deux nées pour la scène. La maladie l’a emportée trop tôt, mais je porterai son âme sur chaque scène, dans chaque lumière.",
            ["DialogueId"] = 51009944,
            ["GUID"] = "7FB2B2F0",
            ["NextDialogue"] = 51009945,
            ["SpeakNpcId"] = 700300,
            },
        [51009945] = {
            ["Content"] = "所以为了让你能够摆脱你父亲的控制，以及实现维尔莉特的遗愿，西格决定配合你演一出戏。",
            ["ContentFR"] = "Alors, pour t’aider à échapper au contrôle de ton père... et pour accomplir la dernière volonté de Violette... Sig a accepté de jouer son rôle dans cette mise en scène.",
            ["DialogueId"] = 51009945,
            ["GUID"] = "7FB2B31A",
            ["NextDialogue"] = 51009946,
            ["SpeakNpcId"] = 100001,
            },
        [51009946] = {
            ["Camera"] = "173.006836,-16.306641,127.36377,0.000095,0.999769,158.194092,44.87347,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "不……不可能，如果真的是这样，那她刚刚又为什么……",
            ["ContentFR"] = "Non... impossible. Si tout cela est vrai, alors pourquoi a-t-elle dit tout ce qu’elle vient d’avouer... ?",
            ["DialogueId"] = 51009946,
            ["FacialId"] = {
                [1] = "700302:CM_Shock01",
                },
            ["GUID"] = "7FB2B344",
            ["NextDialogue"] = 51009947,
            ["SpeakNpcId"] = 700302,
            ["TalkActionId"] = {
                [1] = "700302:Shock_Start",
                },
            },
        [51009947] = {
            ["Content"] = "你带着预设好的答案而来，吉赛尔。如果薇奥莱塔女士没有顺着你的意思说下去，她害怕她的学生罗莎琳会遭遇不测。",
            ["ContentFR"] = "Parce que tu es venue ici avec ta version des faits déjà décidée, Giselle. Et Madame Violetta avait peur qu’en te contredisant, elle mette la vie de son élève Rosalind en danger.",
            ["DialogueId"] = 51009947,
            ["GUID"] = "7FB2B36E",
            ["NextDialogue"] = 51009948,
            ["SpeakNpcId"] = 100001,
            },
        [51009948] = {
            ["Content"] = "什……",
            ["ContentFR"] = "Qu... Quoi... ?",
            ["DialogueId"] = 51009948,
            ["FacialId"] = {
                [1] = "700302:CM_Angry01",
                },
            ["GUID"] = "7FB2B398",
            ["NextDialogue"] = 51009949,
            ["SpeakNpcId"] = 700302,
            ["TalkActionId"] = {
                [1] = "700302:Shock_End",
                },
            },
        [51009949] = {
            ["Camera"] = "-158.601562,204.59082,150.237305,0.000071,-3.199944,-50.20327,35.333332,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我有个请求……我不会逃跑的，所以陪我去一个地方走走，可以吗？",
            ["ContentFR"] = "J’ai une requête... Je ne m’enfuirai pas, je te le promets. Mais accompagne-moi. J’aimerais te montrer un endroit.",
            ["DialogueId"] = 51009949,
            ["GUID"] = "7FB2B3C2",
            ["NextOptions"] = {
                [1] = 510098591,
                },
            ["Scripts"] = "PlayOrStopBGM{PlayType{\"Stop\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt01/0036_story_renweidaozu\"}}",
            ["SpeakNpcId"] = 700300,
            },
        [51009950] = {
            ["Camera"] = "173.006836,-16.306641,127.36377,0.000095,0.999769,158.194092,44.87347,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "可以，但最好不要想耍什么花样。",
            ["ContentFR"] = "D’accord. Mais mieux vaut pour toi ne pas essayer de jouer à un petit jeu.",
            ["DialogueId"] = 51009950,
            ["GUID"] = "7FB2B3EC",
            ["LookAt"] = {
                [1] = "100001:n(700302)",
                },
            ["SpeakNpcId"] = 700302,
            ["TalkActionId"] = {
                [1] = "700302:Agree",
                },
            },
        [51009951] = {
            ["Camera"] = "-257.950684,511.992188,553.037598,0.000167,-36.995567,-61.979073,17.27956,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "这里已经重建了，但在我眼里，它的每一寸砖石都还是当年的样子。",
            ["ContentFR"] = "Tout a été reconstruit... Et pourtant, à mes yeux, chaque brique, chaque pierre est restée figée dans son état d’il y a seize ans.",
            ["DialogueId"] = 51009951,
            ["FinalCamera"] = "-156.373047,321.121094,390.135742,0.000167,-36.995567,-61.979073,17.27956,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "7FB2B416",
            ["LookAt"] = {
                [1] = "100001:n(700300)",
                [2] = "700302:n(700300)",
                },
            ["NextDialogue"] = 51009952,
            ["SpeakNpcId"] = 700300,
            ["ToFinalCameraBlendTime"] = 5,
            },
        [51009952] = {
            ["Content"] = "维尔莉特，我又来看你了……和我们的作品一起。",
            ["ContentFR"] = "Violette... je suis revenue te voir. Et j’ai apporté avec moi notre œuvre.",
            ["DialogueId"] = 51009952,
            ["FacialId"] = {
                [1] = "700300:CM_Sad01",
                },
            ["GUID"] = "7FB2B440",
            ["LookAt"] = {
                [1] = "100001:n(700300)",
                },
            ["NextDialogue"] = 51009953,
            ["SpeakNpcId"] = 700300,
            ["TalkActionId"] = {
                [1] = "700300:Explain01_Start",
                },
            },
        [51009953] = {
            ["Content"] = "已经有聪明的家伙知道了我们的故事，但不知道为什么，我并不害怕，反而有些轻松。也许是因为我终于可以堂堂正正对你说……西格的事，对不起。",
            ["ContentFR"] = "Quelqu’un a fini par comprendre notre histoire... Et étrangement, ça ne m’effraie pas. Je me sens presque soulagée. Peut-être parce que je peux enfin te le dire comme il faut... Pour Sig... je suis désolée.",
            ["DialogueId"] = 51009953,
            ["GUID"] = "7FB2B46A",
            ["NextDialogue"] = 51009954,
            ["SpeakNpcId"] = 700300,
            },
        [51009954] = {
            ["Content"] = "（薇奥莱塔的指尖在墙壁上轻轻拂过，像是在和多年不见老友诉说着过往的经历。或许是发觉已经到了应当离别的时候，她才会选择在此刻回到这里。）",
            ["ContentFR"] = "Violetta fit glisser ses doigts sur le mur, comme si elle confiait ses souvenirs à une amie disparue depuis longtemps. Peut-être avait-elle simplement senti que le moment des adieux était venu.",
            ["DialogueId"] = 51009954,
            ["GUID"] = "7FB2B494",
            ["NextDialogue"] = 51009955,
            ["TalkActionId"] = {
                [1] = "700300:Explain01_End",
                },
            },
        [51009955] = {
            ["Camera"] = "-412.794434,216.719727,171.631836,0.000165,-6.39514,-27.7768,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "谢谢你们纵容我的任性……",
            ["ContentFR"] = "Merci... de m’avoir laissée suivre mes caprices jusqu’au bout.",
            ["DialogueId"] = 51009955,
            ["GUID"] = "7FB2B4BE",
            ["NextDialogue"] = 51009956,
            ["SpeakNpcId"] = 700300,
            ["TurnTo"] = {
                [1] = "700300:n(700302)",
                },
            },
        [51009956] = {
            ["Content"] = "所以，薇奥莱塔，你主动担下罪行还有另一个原因——西格的死并不在你的预料之中，对吗？",
            ["ContentFR"] = "Alors, Violetta... si tu as accepté de porter seule la faute, c’est aussi parce que la mort de Sig n’était pas prévue, n’est-ce pas ?",
            ["DialogueId"] = 51009956,
            ["GUID"] = "7FB2B4E8",
            ["NextDialogue"] = 51009957,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Explain01_Start",
                },
            },
        [51009957] = {
            ["Content"] = "……法布瑞斯·鲁斯福德，那是个冷酷无情的男人。那些矿工因为他几乎食不果腹，手下的卫戍部队也因为他的残暴管理苦不堪言。",
            ["ContentFR"] = "... Fabrice Ruthford. C’était un homme froid et impitoyable. Les mineurs sous ses ordres mouraient presque de faim. Même les Veilleurs souffraient sous sa poigne de fer.",
            ["DialogueId"] = 51009957,
            ["GUID"] = "7FB2B512",
            ["NextDialogue"] = 51009958,
            ["SpeakNpcId"] = 700300,
            ["TalkActionId"] = {
                [1] = "700300:Disagree",
                [2] = "100001:Explain01_End",
                },
            },
        [51009958] = {
            ["Camera"] = "-412.794434,216.719727,171.631836,0.000165,-6.39514,-27.7768,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "就连自己的亲生女儿，那个男人也不留情面地否定她的一切，践踏她的梦想，禁锢她的自由，强迫那个可怜的孩子按照他规划好的无趣的人生去成长。",
            ["ContentFR"] = "Même envers sa propre fille, il ne faisait preuve d’aucune tendresse. Il rejetait tout ce qu’elle était, piétinait ses rêves, emprisonnait sa liberté... Il voulait la façonner selon la vie sans éclat qu’il avait planifiée pour elle.",
            ["DialogueId"] = 51009958,
            ["FinalCamera"] = "-134.225342,69.999023,159.965332,0.000165,-6.39514,-27.776773,35.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "7FB2B53C",
            ["NextDialogue"] = 51009959,
            ["SpeakNpcId"] = 700300,
            ["TalkActionId"] = {
                [1] = "700300:Sigh_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            },
        [51009959] = {
            ["Content"] = "可就是这样一个冷酷无情的人，却因为亲生女儿的死，越过了所有的审判流程亲自将绑架犯处决——即使那会让他被名利场上的敌人抓住把柄，最终被解职。",
            ["ContentFR"] = "Et pourtant... quand sa fille est \"morte\", cet homme cruel a ignoré toute procédure judiciaire pour exécuter lui-même l’auteur de l’enlèvement — quitte à offrir à ses ennemis l’arme pour le destituer.",
            ["DialogueId"] = 51009959,
            ["GUID"] = "7FB2B566",
            ["NextDialogue"] = 51009960,
            ["SpeakNpcId"] = 700300,
            },
        [51009960] = {
            ["Content"] = "我设想过无数种方案，要怎么在逃出他的掌控之后，再想办法悄悄把书信送到法庭上去，这样就能把西格救出来。但我唯独没想到……",
            ["ContentFR"] = "J’avais imaginé mille plans pour envoyer une lettre au tribunal après m’être enfuie... Assez pour innocenter Sig. Mais ce à quoi je n’avais jamais pensé —",
            ["DialogueId"] = 51009960,
            ["GUID"] = "7FB2B590",
            ["NextDialogue"] = 51009961,
            ["SpeakNpcId"] = 700300,
            },
        [51009961] = {
            ["Content"] = "你的父亲比你想象中爱你……",
            ["ContentFR"] = "... C’est que ton père t’aimait bien plus que tu ne le croyais.",
            ["DialogueId"] = 51009961,
            ["GUID"] = "7FB2B5BA",
            ["NextDialogue"] = 51009962,
            ["SpeakNpcId"] = 700302,
            ["TalkActionId"] = {
                [1] = "700302:Talk02_Start",
                },
            },
        [51009962] = {
            ["Content"] = "……后来，我无数次想要说出实情，但海伯利亚只是起点，她的作品还需要我传遍整个世界——我必须遵守我的承诺，至少我必须要这么想。",
            ["ContentFR"] = "... Il y a eu tant de fois où j’ai voulu tout avouer. Mais Hyperborea n’était que le point de départ : son œuvre devait voyager à travers le monde. Je devais tenir ma promesse... ou du moins essayer.",
            ["DialogueId"] = 51009962,
            ["GUID"] = "7FB2B5E4",
            ["NextDialogue"] = 51009963,
            ["SpeakNpcId"] = 700300,
            ["TalkActionId"] = {
                [1] = "700300:Sigh_End",
                [2] = "700302:Talk02_End",
                },
            },
        [51009963] = {
            ["Content"] = "所以当你找上我的时候，我反而感到有些轻松……我已经有了很多学生，他们都是拥有天赋的孩子，他们可以代替我把《普蒂妮》带上更多更广阔的舞台。",
            ["ContentFR"] = "Alors quand tu es venue me trouver, Giselle... j’ai ressenti un étrange soulagement. J’ai formé de nombreux enfants talentueux, et eux pourront porter <I>Putini</> encore plus loin que moi.",
            ["DialogueId"] = 51009963,
            ["GUID"] = "7FB2B60E",
            ["LookAt"] = {
                [1] = "700300:n(700302)",
                },
            ["NextDialogue"] = 51009964,
            ["SpeakNpcId"] = 700300,
            ["TalkActionId"] = {
                [1] = "700300:Talk02_Start",
                },
            },
        [51009964] = {
            ["Content"] = "而你，只需要在这里承认吉赛尔的指控，就可以洗去西格身上本不属于他的罪名。",
            ["ContentFR"] = "Et il te suffisait... d’endosser la culpabilité aux yeux de Giselle, pour laver Sig d’un crime qui n’était pas le sien.",
            ["DialogueId"] = 51009964,
            ["GUID"] = "7FB2B638",
            ["NextDialogue"] = 51009965,
            ["SpeakNpcId"] = 100001,
            },
        [51009965] = {
            ["Content"] = "……我会跟你走的，吉赛尔。但必须在你放了罗莎琳·马格努斯之后。",
            ["ContentFR"] = "... Je te suivrai, Giselle. Mais seulement si tu libères Rosalind Magnus.",
            ["DialogueId"] = 51009965,
            ["FacialId"] = {
                [1] = "700300:CM_Idle",
                },
            ["GUID"] = "7FB2B662",
            ["NextDialogue"] = 51009966,
            ["SpeakNpcId"] = 700300,
            },
        [51009966] = {
            ["Content"] = "不管是为了我自己，还是为了西格和维尔莉特，她都绝对不能有事。",
            ["ContentFR"] = "Pour moi... pour Sig et pour Violette... il ne doit rien lui arriver.",
            ["DialogueId"] = 51009966,
            ["GUID"] = "7FB2B68C",
            ["NextDialogue"] = 51009967,
            ["SpeakNpcId"] = 700300,
            },
        [51009967] = {
            ["Camera"] = "214.642578,12.081055,146.839844,0.000166,-1.794707,-168.969223,41.877083,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "……她已经离开冰湖城了。",
            ["ContentFR"] = "... Elle a déjà quitté Givrelac.",
            ["DialogueId"] = 51009967,
            ["GUID"] = "7FB2B6B6",
            ["LookAt"] = {
                [1] = "100001:n(700302)",
                },
            ["NextDialogue"] = 51009968,
            ["SpeakNpcId"] = 700302,
            ["TalkActionId"] = {
                [1] = "700302:Talk01_Start",
                [2] = "700300:Talk02_End",
                },
            },
        [51009968] = {
            ["Camera"] = "-134.225342,69.999023,159.965332,0.000165,-6.39514,-27.776773,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "什么？",
            ["ContentFR"] = "Quoi ?!",
            ["DialogueId"] = 51009968,
            ["FacialId"] = {
                [1] = "700300:CM_Shock01",
                },
            ["GUID"] = "7FB2B6E0",
            ["NextDialogue"] = 51009969,
            ["SpeakNpcId"] = 700300,
            ["TalkActionId"] = {
                [1] = "700300:Shock_Start",
                },
            },
        [51009969] = {
            ["Camera"] = "-156.373047,321.121094,390.135742,0.000167,-36.995567,-61.979073,17.27956,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "既然你作为声乐老师和她的父母打过交道，就应该知道她所面临的处境。",
            ["ContentFR"] = "Tu étais son professeur de chant, tu sais donc ce qu’elle affrontait.",
            ["DialogueId"] = 51009969,
            ["FacialId"] = {
                [1] = "700302:CM_Smile01",
                },
            ["GUID"] = "7FB2B70A",
            ["NextDialogue"] = 51009970,
            ["SpeakNpcId"] = 700302,
            },
        [51009970] = {
            ["Content"] = "雏鸟为了摆脱囚笼不惜折断翅膀，作为师徒，你们两个倒是如出一辙。",
            ["ContentFR"] = "Une oiselle prête à se briser les ailes pour s’échapper de sa cage... Vous deux, vous vous ressemblez énormément.",
            ["DialogueId"] = 51009970,
            ["GUID"] = "7FB2B734",
            ["NextDialogue"] = 51009971,
            ["SpeakNpcId"] = 700302,
            },
        [51009971] = {
            ["Content"] = "原来你从一开始就在骗我……",
            ["ContentFR"] = "Alors tout ce temps... tu me mentais.",
            ["DialogueId"] = 51009971,
            ["FacialId"] = {
                [1] = "700300:CM_Smile01",
                },
            ["GUID"] = "7FB2B75E",
            ["NextDialogue"] = 51009972,
            ["SpeakNpcId"] = 700300,
            ["TalkActionId"] = {
                [1] = "700300:Shock_End",
                },
            },
        [51009972] = {
            ["Camera"] = "214.642578,12.081055,146.839844,0.000166,-1.794707,-168.969223,41.877083,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我也不会想到会和你关系如此密切的人会突然跑过来雇我“绑架”她，我只是利用下这小小的巧合罢了。",
            ["ContentFR"] = "Ce n’était pas prévu. Je ne pensais pas que quelqu’un d’aussi proche de toi viendrait m’engager pour la \"kidnapper\". J’ai simplement... profité de l’occasion.",
            ["DialogueId"] = 51009972,
            ["GUID"] = "7FB2B788",
            ["NextDialogue"] = 51009973,
            ["SpeakNpcId"] = 700302,
            ["TalkActionId"] = {
                [1] = "700302:Confident_Start",
                },
            },
        [51009973] = {
            ["Content"] = "怎么样，我的演技是不是也还不错？是时候考虑接下来要不要转行了。",
            ["ContentFR"] = "Alors ? Mon jeu d’actrice était convaincant, non ? Peut-être que je devrais songer à changer de métier.",
            ["DialogueId"] = 51009973,
            ["GUID"] = "7FB2B7B2",
            ["NextDialogue"] = 51009974,
            ["SpeakNpcId"] = 700302,
            },
        [51009974] = {
            ["Camera"] = "-204.130859,4.202148,148.053223,0.000166,-3.794798,6.829297,41.877083,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "吉赛尔不打算做狩月人了？",
            ["ContentFR"] = "Tu ne veux plus être une Chasseuse de Phoxène ?",
            ["DialogueId"] = 51009974,
            ["FacialId"] = {
                [1] = "100001:Happy01",
                },
            ["GUID"] = "7FB2B7DC",
            ["NextDialogue"] = 51009975,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Talk02R_Start",
                },
            },
        [51009975] = {
            ["Camera"] = "214.642578,12.081055,146.839844,0.000166,-1.794707,-168.969223,41.877083,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "呵，也多亏了马格努斯家大小姐的绑架案闹得满城风雨，接下来很长一段时间我也得避避风头了。",
            ["ContentFR"] = "Eh bien. Avec tout ce vacarme autour de \"l’enlèvement\" de la demoiselle Magnus, je vais devoir disparaître quelque temps de toute façon.",
            ["DialogueId"] = 51009975,
            ["GUID"] = "7FB2B806",
            ["NextDialogue"] = 51009976,
            ["SpeakNpcId"] = 700302,
            },
        [51009976] = {
            ["Content"] = "至于薇奥莱塔……",
            ["ContentFR"] = "Quant à Violetta...",
            ["DialogueId"] = 51009976,
            ["GUID"] = "7FB2B830",
            ["NextDialogue"] = 51009977,
            ["SpeakNpcId"] = 700302,
            ["TalkActionId"] = {
                [1] = "100001:Talk02R_End",
                },
            },
        [51009977] = {
            ["Camera"] = "-204.130859,4.202148,148.053223,0.000166,-3.794798,6.829297,41.877083,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "{nickname}，你来做决定吧。既然你比我先一步查清真相，就由你来选择怎么处置她吧。",
            ["ContentFR"] = "{nickname}, c’est toi qui vas décider. Puisque tu as découvert la vérité avant moi, c’est à toi de choisir ce qu’il adviendra d’elle.",
            ["DialogueId"] = 51009977,
            ["FacialId"] = {
                [1] = "100001:Doubt01",
                },
            ["GUID"] = "7FB2B85A",
            ["LookAt"] = {
                [1] = "700300:n(100001)",
                },
            ["NextDialogue"] = 51009978,
            ["SpeakNpcId"] = 700302,
            ["TalkActionId"] = {
                [1] = "700302:Confident_End",
                },
            },
        [51009978] = {
            ["Content"] = "这样就好吗，吉赛尔？",
            ["ContentFR"] = "Tu es sûre, Giselle ?",
            ["DialogueId"] = 51009978,
            ["GUID"] = "7FB2B884",
            ["NextDialogue"] = 51009979,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Talk02R_Start",
                },
            },
        [51009979] = {
            ["Camera"] = "-62.87207,113.884766,154.009766,0.000172,-4.994904,-44.169758,41.877083,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我不知道。<H>揭露真相，她也许会因当年的欺骗行径名誉扫地，无法再登台演出。隐瞒真相，那西格的冤屈……</>",
            ["ContentFR"] = "Je n’en sais rien. <H>Si nous révélons la vérité, elle pourrait tout perdre — son nom, son rêve. Mais si nous gardons le silence... le nom de Sig ne sera jamais lavé.</>",
            ["DialogueId"] = 51009979,
            ["FacialId"] = {
                [1] = "700300:CM_Smile01",
                },
            ["GUID"] = "7FB2B8AE",
            ["NextDialogue"] = 51009980,
            ["SpeakNpcId"] = 700302,
            },
        [51009980] = {
            ["Content"] = "我现在脑子很乱，或许现在让你做决定才是正确的选择。",
            ["ContentFR"] = "Je ne sais plus quoi penser. Peut-être qu’il vaut mieux que ce soit toi qui décides.",
            ["DialogueId"] = 51009980,
            ["GUID"] = "7FB2B8D8",
            ["NextDialogue"] = 51009981,
            ["SpeakNpcId"] = 700302,
            },
        [51009981] = {
            ["Content"] = "如果是你做出的决定……我会接受的。",
            ["ContentFR"] = "Si c’est toi qui fais ce choix... je l’accepterai.",
            ["DialogueId"] = 51009981,
            ["GUID"] = "7FB2B902",
            ["NextOptions"] = {
                [1] = 510098911,
                [2] = 510098912,
                },
            ["SpeakNpcId"] = 700300,
            ["TalkActionId"] = {
                [1] = "700300:Agree",
                },
            ["bForbidSkipOptions"] = true,
            },
        [51009982] = {
            ["Camera"] = "214.642578,12.081055,146.839844,0.000166,-1.794707,-168.969223,41.877083,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "吉赛尔。",
            ["ContentFR"] = "Giselle.",
            ["DialogueId"] = 51009982,
            ["GUID"] = "7FB2B92C",
            ["LookAt"] = {
                [1] = "100001:n(700302)",
                },
            ["NextDialogue"] = 51009983,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "700302:Talk03_Start",
                },
            },
        [51009983] = {
            ["Content"] = "说吧，我在听。",
            ["ContentFR"] = "Je t’écoute.",
            ["DialogueId"] = 51009983,
            ["GUID"] = "7FB2B956",
            ["NextDialogue"] = 51009984,
            ["SpeakNpcId"] = 700302,
            },
        [51009984] = {
            ["Camera"] = "-204.130859,4.202148,148.053223,0.000166,-3.794798,6.829297,41.877083,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "可不可以就这样维持现状，不去揭发薇奥莱塔女士？",
            ["ContentFR"] = "Est-ce qu’on ne pourrait pas simplement... ne rien dire ? Ne pas révéler toute cette histoire ?",
            ["DialogueId"] = 51009984,
            ["FacialId"] = {
                [1] = "100001:Sad01",
                },
            ["GUID"] = "7FB2B980",
            ["NextDialogue"] = 51009985,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Explain02_Start",
                },
            },
        [51009985] = {
            ["Camera"] = "-134.225342,69.999023,159.965332,0.000165,-6.39514,-27.776773,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "西格愿意牺牲自己的生命和名誉让薇奥莱塔女士将《普蒂妮》传唱，这应该不是他希望看到的局面。",
            ["ContentFR"] = "Sig a donné sa vie et son honneur pour que Violetta fasse vivre <I>Putini</>. Je ne crois pas que ce soit ainsi qu’il voudrait que ça se termine.",
            ["DialogueId"] = 51009985,
            ["GUID"] = "7FB2B9AA",
            ["NextDialogue"] = 51009986,
            ["SpeakNpcId"] = 100001,
            },
        [51009986] = {
            ["Camera"] = "214.642578,12.081055,146.839844,0.000166,-1.794707,-168.969223,41.877083,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "……我明白了。",
            ["ContentFR"] = "... D’accord. Je comprends.",
            ["DialogueId"] = 51009986,
            ["FacialId"] = {
                [1] = "700302:CM_Idle",
                },
            ["GUID"] = "7FB2B9D4",
            ["NextDialogue"] = 51009987,
            ["SpeakNpcId"] = 700302,
            ["TalkActionId"] = {
                [1] = "700302:Agree",
                [2] = "100001:Explain02_End",
                },
            },
        [51009987] = {
            ["Content"] = "吉赛尔？",
            ["ContentFR"] = "Giselle ?",
            ["DialogueId"] = 51009987,
            ["GUID"] = "7FB2B9FE",
            ["NextDialogue"] = 51009988,
            ["SpeakNpcId"] = 700300,
            },
        [51009988] = {
            ["Content"] = "是我把选择的权利交给了你，自然会尊重你的选择。",
            ["ContentFR"] = "C’est toi qui choisis. Alors je respecterai ta décision.",
            ["DialogueId"] = 51009988,
            ["GUID"] = "7FB2BA28",
            ["NextDialogue"] = 51009989,
            ["SpeakNpcId"] = 700302,
            },
        [51009989] = {
            ["Camera"] = "-412.794434,216.719727,171.631836,0.000165,-6.39514,-27.7768,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "感激不尽。",
            ["ContentFR"] = "Je t’en suis profondément reconnaissante.",
            ["DialogueId"] = 51009989,
            ["FacialId"] = {
                [1] = "700300:CM_Smile01",
                },
            ["GUID"] = "7FB2BA52",
            ["LookAt"] = {
                [1] = "100001:n(700300)",
                },
            ["NextDialogue"] = 51009990,
            ["SpeakNpcId"] = 700300,
            ["TalkActionId"] = {
                [1] = "700300:Explain02_Start",
                },
            },
        [51009990] = {
            ["Content"] = "那看来已经达成共识了。",
            ["ContentFR"] = "Dans ce cas, nous sommes d’accord.",
            ["DialogueId"] = 51009990,
            ["GUID"] = "7FB2BA7C",
            ["NextDialogue"] = 51009991,
            ["SpeakNpcId"] = 700302,
            ["TalkActionId"] = {
                [1] = "700302:Confident_Start",
                },
            },
        [51009991] = {
            ["Camera"] = "-156.373047,321.121094,390.135742,0.000167,-36.995567,-61.979073,17.27956,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "对了，不知道二位可否赏光来看两天后的演出，我会为二位准备特等席。",
            ["ContentFR"] = "Oh, et... accepteriez-vous de venir à la représentation dans deux jours ? Je vous réserverai les meilleures places.",
            ["DialogueId"] = 51009991,
            ["GUID"] = "7FB2BAA6",
            ["NextDialogue"] = 51009992,
            ["SpeakNpcId"] = 700300,
            },
        [51009992] = {
            ["Content"] = "演出吗……",
            ["ContentFR"] = "Une représentation... ?",
            ["DialogueId"] = 51009992,
            ["GUID"] = "7FB2BAD0",
            ["NextDialogue"] = 51009993,
            ["SpeakNpcId"] = 700302,
            },
        [51009993] = {
            ["Content"] = "嗯，是《普蒂妮》。就当是我给那个孩子的送行演出吧，这是她最喜欢的剧目。",
            ["ContentFR"] = "Oui, <I>Putini</>. Considère-la comme une représentation d’adieu pour Rosalind. C’est sa pièce préférée.",
            ["DialogueId"] = 51009993,
            ["GUID"] = "7FB2BAFA",
            ["NextDialogue"] = 51010006,
            ["SpeakNpcId"] = 700300,
            },
        [51009994] = {
            ["Camera"] = "-62.87207,113.884766,154.009766,0.000172,-4.994904,-44.169758,41.877083,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我理解你的做法，薇奥莱塔女士。可我们不该让一个已经逝去的生命从此只能以杀人犯的身份被他人想起。",
            ["ContentFR"] = "Je comprends ce que tu as fait, Violetta. Mais on ne peut pas laisser un homme être considéré comme un meurtrier, même après sa mort.",
            ["DialogueId"] = 51009994,
            ["GUID"] = "7FB2BB24",
            ["LookAt"] = {
                [1] = "700300:n(100001)",
                },
            ["NextDialogue"] = 51009995,
            ["Scripts"] = "SEQ{\
TurnTo{TurnToDescription{\"100001:n(700300)\"}},\
PlayAnimation{ActorId{100001},AnimationId{\"Talk01_Start\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 100001,
            },
        [51009995] = {
            ["Content"] = "虽然西格已经不在了，但至少我们还有能力还他清白。",
            ["ContentFR"] = "Sig n’est plus là. Mais nous avons encore la possibilité de laver son nom.",
            ["DialogueId"] = 51009995,
            ["GUID"] = "7FB2BB4E",
            ["NextDialogue"] = 51009996,
            ["SpeakNpcId"] = 100001,
            },
        [51009996] = {
            ["Camera"] = "214.642578,12.081055,146.839844,0.000166,-1.794707,-168.969223,41.877083,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "{nickname}……谢谢。",
            ["ContentFR"] = "{nickname}... Merci.",
            ["DialogueId"] = 51009996,
            ["GUID"] = "7FB2BB78",
            ["NextDialogue"] = 51009997,
            ["SpeakNpcId"] = 700302,
            ["TalkActionId"] = {
                [1] = "100001:Talk01_End",
                },
            },
        [51009997] = {
            ["Content"] = "西格的确出于金钱目的绑架了你，但和他的罪行相比一条人命还是太过沉重了，我们应该真相公之于众。",
            ["ContentFR"] = "Sig t’a enlevée pour l’argent, oui. Mais ce n’est pas un meurtrier. La vérité doit être révélée.",
            ["DialogueId"] = 51009997,
            ["GUID"] = "7FB2BBA2",
            ["NextDialogue"] = 51009998,
            ["SpeakNpcId"] = 100001,
            },
        [51009998] = {
            ["Camera"] = "-62.87207,113.884766,154.009766,0.000172,-4.994904,-44.169758,41.877083,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "薇奥莱塔女士，这件事一经公开，恐怕你的事业会受到影响。",
            ["ContentFR"] = "Violetta... une fois que ce sera public, tu risques de tout perdre : ta réputation, ta carrière...",
            ["DialogueId"] = 51009998,
            ["FacialId"] = {
                [1] = "700300:CM_Sad01",
                },
            ["GUID"] = "7FB2BBCC",
            ["NextDialogue"] = 51009999,
            ["SpeakNpcId"] = 100001,
            },
        [51009999] = {
            ["Content"] = "我明白，不过这样就好……抱歉，维尔莉特，我们的梦想只能拜托给那些孩子们了。",
            ["ContentFR"] = "Je comprends. Mais c’est très bien ainsi... Pardon, Violette. Notre rêve devra continuer à vivre à travers ces enfants.",
            ["DialogueId"] = 51009999,
            ["GUID"] = "7FB2BBF6",
            ["NextDialogue"] = 51010000,
            ["SpeakNpcId"] = 700300,
            },
        [51010000] = {
            ["Camera"] = "-412.794434,216.719727,171.631836,0.000165,-6.39514,-27.7768,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "那看来已经达成共识了。",
            ["ContentFR"] = "Dans ce cas, nous sommes d’accord.",
            ["DialogueId"] = 51010000,
            ["GUID"] = "7FB2BC20",
            ["LookAt"] = {
                [1] = "700300:n(700302)",
                },
            ["NextDialogue"] = 51010001,
            ["SpeakNpcId"] = 700302,
            },
        [51010001] = {
            ["Content"] = "还有一件事……",
            ["ContentFR"] = "Une dernière chose...",
            ["DialogueId"] = 51010001,
            ["GUID"] = "7FB2BC4A",
            ["NextDialogue"] = 51010002,
            ["SpeakNpcId"] = 700300,
            },
        [51010002] = {
            ["Content"] = "嗯哼？现在反悔可来不及了。",
            ["ContentFR"] = "Hmm ? Il est un peu tard pour changer d’avis.",
            ["DialogueId"] = 51010002,
            ["GUID"] = "7FB2BC74",
            ["NextDialogue"] = 51010003,
            ["SpeakNpcId"] = 700302,
            ["TalkActionId"] = {
                [1] = "700302:Confident_Start",
                },
            },
        [51010003] = {
            ["Camera"] = "-156.373047,321.121094,390.135742,0.000167,-36.995567,-61.979073,17.27956,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "怎么会呢，我只是想邀请二位来看两天后的演出，就当是我的告别演出吧。我会为二位准备特等席。",
            ["ContentFR"] = "Oh non. Je voulais simplement vous inviter à une représentation, dans deux jours. Considérez-la comme mon chant du cygne. Je préparerai les meilleures places pour vous deux.",
            ["DialogueId"] = 51010003,
            ["GUID"] = "7FB2BC9E",
            ["NextDialogue"] = 51010004,
            ["SpeakNpcId"] = 700300,
            ["TalkActionId"] = {
                [1] = "700300:Explain02_Start",
                },
            },
        [51010004] = {
            ["Content"] = "告别演出啊……",
            ["ContentFR"] = "Ton chant du cygne, hein... ?",
            ["DialogueId"] = 51010004,
            ["GUID"] = "7FB2BCC8",
            ["NextDialogue"] = 51010005,
            ["SpeakNpcId"] = 700302,
            },
        [51010005] = {
            ["Content"] = "嗯，是《普蒂妮》。从这部戏开始也从这部戏结束，也算是有始有终。",
            ["ContentFR"] = "Oui. <I>Putini</>. Tout a commencé avec cette pièce — et c’est ainsi que cela doit se terminer.",
            ["DialogueId"] = 51010005,
            ["GUID"] = "7FB2BCF2",
            ["NextDialogue"] = 51010006,
            ["SpeakNpcId"] = 700300,
            },
        [51010006] = {
            ["Content"] = "我会去的。",
            ["ContentFR"] = "J’y serai.",
            ["DialogueId"] = 51010006,
            ["GUID"] = "7FB2BD1C",
            ["NextDialogue"] = 51010007,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Agree",
                },
            },
        [51010007] = {
            ["Content"] = "特等席准备一个就行了。",
            ["ContentFR"] = "Une seule place suffira.",
            ["DialogueId"] = 51010007,
            ["GUID"] = "7FB2BD46",
            ["NextDialogue"] = 51010008,
            ["SpeakNpcId"] = 700302,
            },
        [51010008] = {
            ["Content"] = "…………",
            ["ContentFR"] = "...",
            ["DialogueId"] = 51010008,
            ["GUID"] = "7FB2BD70",
            ["NextDialogue"] = 51010009,
            ["SpeakNpcId"] = 700300,
            },
        [51010009] = {
            ["Content"] = "别误会，我会去捧场的。不过我好歹也是半个通缉犯，看个戏还是不要那么招摇了。",
            ["ContentFR"] = "Ne te méprends pas, je viendrai. Mais disons que pour une \"demi-fugitive\", mieux vaut ne pas trop se faire remarquer.",
            ["DialogueId"] = 51010009,
            ["GUID"] = "7FB2BD9A",
            ["NextDialogue"] = 51010010,
            ["SpeakNpcId"] = 700302,
            },
        [51010010] = {
            ["Content"] = "明白了，我这就让剧团去安排。",
            ["ContentFR"] = "Très bien. Je vais prévenir la troupe.",
            ["DialogueId"] = 51010010,
            ["GUID"] = "7FB2BDC4",
            ["NextDialogue"] = 51010011,
            ["SpeakNpcId"] = 700300,
            },
        [51010011] = {
            ["Content"] = "那么，我们两天后见。",
            ["ContentFR"] = "Dans ce cas... rendez-vous dans deux jours.",
            ["DialogueId"] = 51010011,
            ["GUID"] = "7FB2BDEE",
            ["SpeakNpcId"] = 700300,
            },
        [51010012] = {
            ["Camera"] = "-257.685547,-253.308594,133.213379,0.000042,-0.199585,40.001606,38.587292,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "早上好，薇奥莱塔女士。",
            ["ContentFR"] = "Bonjour, Violetta.",
            ["DialogueId"] = 51010012,
            ["FacialId"] = {
                [1] = "100001:Smile01",
                },
            ["GUID"] = "7FB2BE18",
            ["NextDialogue"] = 51010013,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Talk02_Start",
                },
            },
        [51010013] = {
            ["Content"] = "你们来了，给，这是你们二位的门票。",
            ["ContentFR"] = "Vous voilà. Tenez, voici vos billets.",
            ["DialogueId"] = 51010013,
            ["GUID"] = "7FB2BE42",
            ["NextDialogue"] = 51010014,
            ["SpeakNpcId"] = 700300,
            ["TalkActionId"] = {
                [1] = "700300:Give",
                [2] = "100001:Talk02_End",
                },
            },
        [51010014] = {
            ["Content"] = "那我就不客气了。",
            ["ContentFR"] = "Eh bien, je ne vais pas me faire prier.",
            ["DialogueId"] = 51010014,
            ["FacialId"] = {
                [1] = "700302:CM_Smile01",
                },
            ["GUID"] = "7FB2BE6C",
            ["NextDialogue"] = 51010015,
            ["SpeakNpcId"] = 700302,
            ["TalkActionId"] = {
                [1] = "700302:Confident_Start",
                },
            },
        [51010015] = {
            ["Camera"] = "-182.809326,149.35498,133.001709,0.000049,-0.999878,-49.996906,35.520077,340.13559,false,Manual,2.8",
            ["Content"] = "请便，让《普蒂妮》传遍世界是维尔莉特的遗愿，只是少收两张票而已，她不会有意见的。",
            ["ContentFR"] = "Allez-y. Faire voyager <I>Putini</> à travers le monde était le dernier vœu de Violette. Elle ne m’en voudra pas d’offrir deux places.",
            ["DialogueId"] = 51010015,
            ["GUID"] = "7FB2BE96",
            ["NextDialogue"] = 51010016,
            ["SpeakNpcId"] = 700300,
            ["TalkActionId"] = {
                [1] = "700300:Agree",
                },
            },
        [51010016] = {
            ["Content"] = "只是……",
            ["ContentFR"] = "C’est juste que...",
            ["DialogueId"] = 51010016,
            ["GUID"] = "7FB2BEC0",
            ["NextDialogue"] = 51010017,
            ["SpeakNpcId"] = 700300,
            ["TalkActionId"] = {
                [1] = "700300:Explain02_Start",
                },
            },
        [51010017] = {
            ["Content"] = "你在想罗莎琳小姐吗？",
            ["ContentFR"] = "... Tu penses à Mademoiselle Rosalind, n’est-ce pas ?",
            ["DialogueId"] = 51010017,
            ["GUID"] = "7FB2BEEA",
            ["NextDialogue"] = 51010018,
            ["SpeakNpcId"] = 100001,
            },
        [51010018] = {
            ["Content"] = "嗯，虽说是给她的送行演出，但我也不知道她是否还在冰湖城中，能否看到这场她最喜欢的戏。",
            ["ContentFR"] = "Mmh. C’était censé être sa représentation d’adieu. Mais j’ignore même si elle est toujours à Givrelac... ou si elle pourra assister à sa pièce préférée.",
            ["DialogueId"] = 51010018,
            ["GUID"] = "7FB2BF14",
            ["LookAt"] = {
                [1] = "100001:n(700302)",
                [2] = "700300:n(700302)",
                },
            ["NextDialogue"] = 51010019,
            ["SpeakNpcId"] = 700300,
            },
        [51010019] = {
            ["Camera"] = "-257.685547,-253.308594,133.213379,0.000042,-0.199585,40.001564,38.587292,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "别看我啊，为了不让她再被父母抓回去，连我也不知道她现在的行踪。",
            ["ContentFR"] = "Ne me regarde pas. Pour éviter que ses parents ne la retrouvent, j’ai moi-même préféré ne pas connaître sa cachette.",
            ["DialogueId"] = 51010019,
            ["FacialId"] = {
                [1] = "700302:CM_Shock01",
                },
            ["GUID"] = "7FB2BF3E",
            ["NextOptions"] = {
                [1] = 510099291,
                [2] = 510099292,
                },
            ["SpeakNpcId"] = 700302,
            },
        [51010020] = {
            ["Camera"] = "-182.809326,149.35498,133.001709,0.000049,-0.999878,-49.996906,35.520077,340.13559,false,Manual,2.8",
            ["Content"] = "但愿如此。",
            ["ContentFR"] = "Espérons-le... Oh, {nickname}.",
            ["DialogueId"] = 51010020,
            ["FacialId"] = {
                [1] = "700302:CM_Idle",
                [2] = "700300:CM_Smile01",
                },
            ["GUID"] = "7FB2BF68",
            ["SpeakNpcId"] = 700300,
            },
        [51010021] = {
            ["Content"] = "你能将三件看似毫无关联的事件联系在一起，并书写这场皆大欢喜的结局，你的聪慧和行动力令我惊叹。",
            ["ContentFR"] = "Tu as relié entre eux trois événements qui semblaient sans lien... pour en faire une histoire à la fin heureuse. Ton esprit et ta détermination m’impressionnent.",
            ["DialogueId"] = 51010021,
            ["GUID"] = "7FB2BF92",
            ["NextDialogue"] = 51010022,
            ["SpeakNpcId"] = 700300,
            },
        [51010022] = {
            ["Content"] = "所以，我有另一个重要的委托，希望你可以接下。事关我的另一位学生，报酬不是问题，等你得空了，来剧院找我就好。",
            ["ContentFR"] = "J’ai donc une autre mission à te proposer — elle concerne l’un de mes élèves. La récompense n’est pas un souci. Passe me voir au théâtre quand tu auras le temps.",
            ["DialogueId"] = 51010022,
            ["GUID"] = "7FB2BFBC",
            ["NextDialogue"] = 51010023,
            ["SpeakNpcId"] = 700300,
            },
        [51010023] = {
            ["Content"] = "不过无需在今夜——今夜属于歌曲和远航。愿二位抛却烦恼，度过一个美妙的假日。",
            ["ContentFR"] = "Mais pas ce soir — ce soir appartient à la musique, et au grand départ. Laisse tes soucis derrière toi... et profite de cette nuit inoubliable.",
            ["DialogueId"] = 51010023,
            ["GUID"] = "7FB2BFE6",
            ["SpeakNpcId"] = 700300,
            },
        [51010024] = {
            ["Content"] = "你找到了薇奥莱塔为你安排的座位，在观众席等待着演出开场。",
            ["ContentFR"] = "Tu trouves les places réservées par Violetta et t’installes, attendant que le rideau se lève.",
            ["DialogueId"] = 51010024,
            ["GUID"] = "7FB2C010",
            ["NextDialogue"] = 51010025,
            },
        [51010025] = {
            ["Content"] = "随着看台的灯光逐渐熄灭，洪亮的女声唱白带着你的期待与好奇从幕布后侵染到整个演出厅。",
            ["ContentFR"] = "Alors que les lumières s’éteignent peu à peu, une puissante voix de soprano s’élève derrière le rideau, emplissant la salle d’une magie indicible.",
            ["DialogueId"] = 51010025,
            ["GUID"] = "7FB2C03A",
            ["NextDialogue"] = 51010026,
            },
        [51010026] = {
            ["Content"] = "看台下异常安静，尚未习惯这种环境的你稍稍有些不安。",
            ["ContentFR"] = "Le public retient son souffle. Ce silence profond te met presque mal à l’aise.",
            ["DialogueId"] = 51010026,
            ["GUID"] = "7FB2C064",
            ["NextDialogue"] = 51010027,
            },
        [51010027] = {
            ["Content"] = "控制住对精彩桥段的赞美并非易事，你害怕自己无意识的感叹扰了他人雅兴。",
            ["ContentFR"] = "Il est difficile de retenir tes exclamations face aux scènes les plus spectaculaires — tu crains qu’un soupir d’admiration n’interrompe l’enchantement.",
            ["DialogueId"] = 51010027,
            ["GUID"] = "7FB2C08E",
            ["NextDialogue"] = 51010028,
            },
        [51010028] = {
            ["Content"] = "不过这种担忧是多余的——为剧中人所牵动的你甚至忘记了鼓掌，直至演出结束……",
            ["ContentFR"] = "Mais cette crainte s’évanouit vite — tant et si bien qu’au moment où le dernier son s’éteint, tu en oublies même d’applaudir.",
            ["DialogueId"] = 51010028,
            ["GUID"] = "7FB2C0B8",
            },
        [51010029] = {
            ["Camera"] = "-423.906006,-31.62793,121.737549,0.0,1.799973,0.000049,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "呼，的确是一出好戏，差点让我忘了我最讨厌这种人多的封闭空间。",
            ["ContentFR"] = "Ouf... C’était vraiment une pièce magnifique. J’en ai presque oublié à quel point je déteste les endroits clos et bondés.",
            ["DialogueId"] = 51010029,
            ["GUID"] = "7FB2C0E2",
            ["LookAt"] = {
                [1] = "100001:n(700302)",
                [2] = "700302:n(100001)",
                },
            ["NextDialogue"] = 51010030,
            ["SpeakNpcId"] = 700302,
            },
        [51010030] = {
            ["Content"] = "感觉稍微能够理解他们很多人为什么这么喜欢舞台了。",
            ["ContentFR"] = "Je crois que je comprends enfin pourquoi la scène fascine autant les gens.",
            ["DialogueId"] = 51010030,
            ["FacialId"] = {
                [1] = "100001:Smile01",
                },
            ["GUID"] = "7FB2C10C",
            ["NextDialogue"] = 51010031,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Talk02R_Start",
                },
            },
        [51010031] = {
            ["Content"] = "只希望一个两个的以后都让人省点心……我可不想再接到让我绑架委托人的单了。",
            ["ContentFR"] = "Espérons simplement que les gens arrêteront de me donner du fil à retordre... Je ne veux plus jamais avoir à \"kidnapper\" mes propres clients.",
            ["DialogueId"] = 51010031,
            ["FacialId"] = {
                [1] = "700302:CM_Smile01",
                },
            ["GUID"] = "7FB2C136",
            ["NextDialogue"] = 51010032,
            ["SpeakNpcId"] = 700302,
            ["TalkActionId"] = {
                [1] = "700302:Confident_Start",
                [2] = "100001:Talk02R_End",
                },
            },
        [51010032] = {
            ["Content"] = "虽然我自己也没什么资格说她们，明明我也是个钻了十几年牛角尖的怪人。",
            ["ContentFR"] = "Même si, pour être honnête, je ne suis pas mieux. Moi aussi, je me suis enfermée dans mes obsessions pendant des années.",
            ["DialogueId"] = 51010032,
            ["GUID"] = "7FB2C160",
            ["NextDialogue"] = 51010033,
            ["SpeakNpcId"] = 700302,
            },
        [51010033] = {
            ["Content"] = "我稍微有点好奇你为什么对这件案子这么执着。",
            ["ContentFR"] = "Je suis {性别:curieux|curieuse}... pourquoi cette affaire te tenait-elle autant à cœur ?",
            ["DialogueId"] = 51010033,
            ["GUID"] = "7FB2C18A",
            ["NextDialogue"] = 51010034,
            ["SpeakNpcId"] = 100001,
            },
        [51010034] = {
            ["Content"] = "……我可以不说吗？",
            ["ContentFR"] = "... Je peux ne pas répondre à ça ?",
            ["DialogueId"] = 51010034,
            ["GUID"] = "7FB2C1B4",
            ["NextDialogue"] = 51010035,
            ["SpeakNpcId"] = 700302,
            },
        [51010035] = {
            ["Content"] = "如果你不愿意那就算了，没关系。",
            ["ContentFR"] = "Tu n’es pas obligée d’en parler.",
            ["DialogueId"] = 51010035,
            ["GUID"] = "7FB2C1DE",
            ["NextDialogue"] = 51010036,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:AgreeHead",
                [2] = "700302:Confident_End",
                },
            },
        [51010036] = {
            ["Content"] = "算了，对你这么好说话的人还讲谜语就没意思了。",
            ["ContentFR"] = "D’accord... inutile de faire des mystères avec quelqu’un d’aussi sincère que toi.",
            ["DialogueId"] = 51010036,
            ["GUID"] = "7FB2C208",
            ["NextDialogue"] = 51010037,
            ["SpeakNpcId"] = 700302,
            ["TalkActionId"] = {
                [1] = "700302:Talk02_Start",
                },
            },
        [51010037] = {
            ["Content"] = "多纳特应该告诉过你，是他举报了西格的绑架行为。而当时收到举报的人，就是我。",
            ["ContentFR"] = "Donat t’a sûrement raconté qu’il avait dénoncé Sig. Eh bien, la personne à qui il s’est adressé... c’était moi.",
            ["DialogueId"] = 51010037,
            ["FacialId"] = {
                [1] = "700302:CM_Sad01",
                },
            ["GUID"] = "7FB2C232",
            ["NextDialogue"] = 51010038,
            ["SpeakNpcId"] = 700302,
            },
        [51010038] = {
            ["Content"] = "最初为了避免打草惊蛇，我的计划是，我一个人秘密前去和西格谈判，争取解救人质……但是考虑到事关长官的女儿，我犹豫再三，还是汇报给了他。",
            ["ContentFR"] = "Au départ, pour ne pas l’effrayer, je voulais aller négocier seule, libérer l’otage sans faire de vagues. Mais quand j’ai réalisé qu’il s’agissait de la fille de mon supérieur, j’ai hésité... et j’ai fini par faire un rapport.",
            ["DialogueId"] = 51010038,
            ["FacialId"] = {
                [1] = "100001:None",
                },
            ["GUID"] = "7FB2C25C",
            ["NextDialogue"] = 51010039,
            ["SpeakNpcId"] = 700302,
            },
        [51010039] = {
            ["Content"] = "但后续你也知道了，艾诺拉……薇奥莱塔的父亲，盛怒之下驳回了我的方案，直接带着大队人马包围了那栋房子。",
            ["ContentFR"] = "La suite, tu la connais. Son père a refusé mon plan, a perdu son sang-froid, et a lancé l’assaut.",
            ["DialogueId"] = 51010039,
            ["GUID"] = "7FB2C286",
            ["NextDialogue"] = 51010040,
            ["SpeakNpcId"] = 700302,
            },
        [51010040] = {
            ["Content"] = "如果当初我能够坚持自己的想法，说不定这一切都不会发生。",
            ["ContentFR"] = "Si j’avais suivi mon instinct... peut-être que rien de tout cela ne serait arrivé.",
            ["DialogueId"] = 51010040,
            ["GUID"] = "7FB2C2B0",
            ["NextDialogue"] = 51010041,
            ["SpeakNpcId"] = 700302,
            },
        [51010041] = {
            ["Content"] = "虽然有些对不起薇奥莱塔，可至少西格不会因为虚假的罪名被处死。",
            ["ContentFR"] = "Même si cela aurait rendu les choses plus difficiles pour Violetta, au moins Sig n’aurait pas été exécuté pour un crime qu’il n’avait pas commis.",
            ["DialogueId"] = 51010041,
            ["GUID"] = "7FB2C2DA",
            ["NextDialogue"] = 51010042,
            ["SpeakNpcId"] = 700302,
            },
        [51010042] = {
            ["Content"] = "吉赛尔……",
            ["ContentFR"] = "Giselle...",
            ["DialogueId"] = 51010042,
            ["GUID"] = "7FB2C304",
            ["NextDialogue"] = 51010043,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "700302:Talk02_End",
                },
            },
        [51010043] = {
            ["Content"] = "我……能理解长官的心情，不管是谁都无法接受女儿死于非命。但我无法赞同在调查清楚一切之前就做出决断。",
            ["ContentFR"] = "Je comprends sa réaction. Aucun parent ne supporterait la mort de son enfant. Mais je ne peux pas approuver qu’on rende justice avant d’avoir découvert toute la vérité.",
            ["DialogueId"] = 51010043,
            ["GUID"] = "7FB2C32E",
            ["NextDialogue"] = 51010044,
            ["SpeakNpcId"] = 700302,
            ["TalkActionId"] = {
                [1] = "700302:Sigh_Start",
                },
            },
        [51010044] = {
            ["Content"] = "我不是为了这样才进入卫戍部队的。",
            ["ContentFR"] = "Ce n’est pas pour ça que j’ai rejoint les Veilleurs.",
            ["DialogueId"] = 51010044,
            ["GUID"] = "7FB2C358",
            ["NextDialogue"] = 51010045,
            ["SpeakNpcId"] = 700302,
            },
        [51010045] = {
            ["Content"] = "卫戍部队少了这么一个正义感强烈的人是他们的损失。",
            ["ContentFR"] = "Les Veilleurs ont perdu quelqu’un qui représentait vraiment la justice.",
            ["DialogueId"] = 51010045,
            ["FacialId"] = {
                [1] = "100001:Smile01",
                },
            ["GUID"] = "7FB2C382",
            ["NextDialogue"] = 51010046,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Talk01_Start",
                },
            },
        [51010046] = {
            ["Content"] = "这是在夸我吗？",
            ["ContentFR"] = "... Est-ce que c’était un compliment ?",
            ["DialogueId"] = 51010046,
            ["FacialId"] = {
                [1] = "700302:CM_Smile01",
                },
            ["GUID"] = "7FB2C3AC",
            ["NextDialogue"] = 51010047,
            ["SpeakNpcId"] = 700302,
            ["TalkActionId"] = {
                [1] = "700302:Sigh_End",
                },
            },
        [51010047] = {
            ["Content"] = "反正都是过去的事了，现在事情解决了，接下来我想想办法，看看能不能把绑架纵火案的部分真相公开……当然，前提是隐瞒薇奥莱塔的真实身份。",
            ["ContentFR"] = "Quoi qu’il en soit, c’est du passé. Maintenant que tout est terminé, je vais voir si je peux rendre publique une partie de la vérité sur l’affaire — tout en gardant secrète l’identité de Violetta.",
            ["DialogueId"] = 51010047,
            ["GUID"] = "7FB2C3D6",
            ["NextDialogue"] = 51010048,
            ["SpeakNpcId"] = 700302,
            ["TalkActionId"] = {
                [1] = "100001:Talk01_End",
                },
            },
        [51010048] = {
            ["Content"] = "找不到艾诺拉本人的话，没有足够证据能说服卫戍部队的人翻案吧？",
            ["ContentFR"] = "Sans Enola, tu n’auras aucune preuve pour convaincre les Veilleurs de rouvrir l’enquête.",
            ["DialogueId"] = 51010048,
            ["FacialId"] = {
                [1] = "100001:Doubt01",
                },
            ["GUID"] = "7FB2C400",
            ["NextDialogue"] = 51010049,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Think_Start",
                },
            },
        [51010049] = {
            ["Content"] = "卫戍部队？没那个必要，我打算把消息告诉报社或者其他什么机构，在坊间传播的效果可比那些死板的公文要好多了。",
            ["ContentFR"] = "Les Veilleurs ? Inutile. Je vais tout raconter à la presse. La rumeur est un juge bien plus puissant que des archives poussiéreuses.",
            ["DialogueId"] = 51010049,
            ["GUID"] = "7FB2C42A",
            ["NextDialogue"] = 51010050,
            ["SpeakNpcId"] = 700302,
            ["TalkActionId"] = {
                [1] = "700302:Confident_Start",
                },
            },
        [51010050] = {
            ["Content"] = "这样真的能行吗……",
            ["ContentFR"] = "Tu crois que ça marchera vraiment... ?",
            ["DialogueId"] = 51010050,
            ["GUID"] = "7FB2C454",
            ["NextDialogue"] = 51010051,
            ["SpeakNpcId"] = 100001,
            },
        [51010051] = {
            ["Content"] = "人们总是愿意相信某件事的背后另有隐情，只有这样才会显得自己拥有独立思考的智慧。这次就让我小小的利用一下这种心理吧。",
            ["ContentFR"] = "Les gens adorent les secrets cachés. Croire qu’ils ont découvert ce qui se cache derrière les apparences les fait se sentir intelligents. Je vais juste... exploiter ça un peu.",
            ["DialogueId"] = 51010051,
            ["GUID"] = "7FB2C47E",
            ["NextDialogue"] = 51010052,
            ["SpeakNpcId"] = 700302,
            },
        [51010052] = {
            ["Content"] = "……啊！",
            ["ContentFR"] = "... Ah !",
            ["DialogueId"] = 51010052,
            ["GUID"] = "7FB2C4A8",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 51010053,
            ["Scripts"] = "SEQ{\
MoveTo{ActorId{700305},TargetPoint{\"RosalindPoint1_20023305\"},MoveSpeed{250},Visibility{\"Show\"}},\
PARA{\
LookAt{LookAtDescription{\"100001:n(700305)\"}},\
LookAt{LookAtDescription{\"700302:n(700305)\"}},\
TurnTo{TurnToDescription{\"700305:n(100001)\"}}\
},\
PARA{\
PlayAnimation{ActorId{100001},AnimationId{\"Shock_Start\"},Duration{1}},\
PlayAnimation{ActorId{700302},AnimationId{\"Angry01_Start\"},Duration{1}},\
PlayAnimation{ActorId{700305},AnimationId{\"Explain02_Start\"},Duration{1}}\
}}",
            ["SpeakNpcId"] = 700305,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Rosalind02",
            },
        [51010053] = {
            ["Camera"] = "-442.745117,136.447266,137.21167,0.000002,-3.200169,-35.40036,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "抱……抱歉，我刚才没看路！没受伤吧？有没有哪里不舒服？",
            ["ContentFR"] = "P-Pardon, je ne regardais pas devant moi ! Tu vas bien ? Je ne t’ai pas fait mal ?",
            ["DialogueId"] = 51010053,
            ["FacialId"] = {
                [1] = "700302:CM_Angry01",
                },
            ["GUID"] = "7FB2C4D2",
            ["NextDialogue"] = 51010054,
            ["SpeakNpcId"] = 700305,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Rosalind02",
            },
        [51010054] = {
            ["Content"] = "我没事，下次注意就好。",
            ["ContentFR"] = "Je vais bien. Faites juste attention, d’accord ?",
            ["DialogueId"] = 51010054,
            ["GUID"] = "7FB2C4FC",
            ["NextDialogue"] = 51010055,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Shock_End",
                [2] = "700302:Angry01_End",
                },
            },
        [51010055] = {
            ["Camera"] = "-77.586914,100.682129,157.737793,0.000019,-6.000089,-109.999786,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "嗯——",
            ["ContentFR"] = "Mmm...",
            ["DialogueId"] = 51010055,
            ["GUID"] = "7FB2C526",
            ["NextDialogue"] = 51010056,
            ["SpeakNpcId"] = 700305,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Rosalind02",
            ["TalkActionId"] = {
                [1] = "700305:Think_Start",
                },
            },
        [51010056] = {
            ["Camera"] = "-304.188965,-104.091309,139.379639,0.000002,-0.600189,4.199689,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我的脸上怎么了吗？",
            ["ContentFR"] = "J’ai quelque chose sur le visage ?",
            ["DialogueId"] = 51010056,
            ["FacialId"] = {
                [1] = "100001:Unhappy01",
                },
            ["GUID"] = "7FB2C550",
            ["NextDialogue"] = 51010057,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Talk03_Start",
                },
            },
        [51010057] = {
            ["Camera"] = "-77.586914,100.682129,157.737793,0.000019,-6.000089,-109.999786,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "没什么，嘻嘻……谢谢你的草药。啊，约定好的时间要过了！",
            ["ContentFR"] = "Non, rien du tout... Hihi... Merci pour les herbes ! Oh non, je vais être en retard !",
            ["DialogueId"] = 51010057,
            ["FacialId"] = {
                [1] = "700305:CM_Happy01",
                },
            ["GUID"] = "7FB2C57A",
            ["NextDialogue"] = 51010058,
            ["SpeakNpcId"] = 700305,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Rosalind02",
            ["TalkActionId"] = {
                [1] = "700305:Think_End",
                },
            },
        [51010058] = {
            ["Content"] = "草药……？等一下你东西掉了！",
            ["ContentFR"] = "Des herbes... ? Attendez, vous avez fait tomber quelque chose !",
            ["DialogueId"] = 51010058,
            ["GUID"] = "7FB2C5A4",
            ["NextDialogue"] = 51010059,
            ["Scripts"] = "SEQ{\
MoveTo{ActorId{700305},TargetPoint{\"RosalindPoint2_20023305\"},MoveSpeed{250},Visibility{\"Hide\"}},\
PlayAnimation{ActorId{100001},AnimationId{\"Nvzhu_Story_StretchHand_Start\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 100001,
            },
        [51010059] = {
            ["Content"] = "——送给你了！！",
            ["ContentFR"] = "Garde-le ! C’est pour toi !",
            ["DialogueId"] = 51010059,
            ["GUID"] = "7FB2C5CE",
            ["NextDialogue"] = 51010060,
            ["SpeakNpcId"] = 700305,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Rosalind02",
            },
        [51010060] = {
            ["Camera"] = "-423.906006,-31.62793,121.737549,0.0,1.799973,0.000049,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "现在的年轻人还真是风风火火。",
            ["ContentFR"] = "Sérieusement... les jeunes, aujourd’hui, sont toujours aussi pressés.",
            ["DialogueId"] = 51010060,
            ["GUID"] = "7FB2C5F8",
            ["LookAt"] = {
                [1] = "700302:n(100001)",
                [2] = "100001:n(700302)",
                },
            ["NextDialogue"] = 51010061,
            ["SpeakNpcId"] = 700302,
            ["TalkActionId"] = {
                [1] = "100001:Nvzhu_Story_StretchHand_End",
                },
            },
        [51010061] = {
            ["Content"] = "说什么送给我了……这上面好像绣了字，是那个女孩的名字吗？",
            ["ContentFR"] = "Pourquoi m’a-t-elle laissé ça... ? Il y a une broderie dessus... C’est son nom ?",
            ["DialogueId"] = 51010061,
            ["FacialId"] = {
                [1] = "100001:Doubt01",
                },
            ["GUID"] = "7FB2C622",
            ["NextDialogue"] = 51010062,
            ["SpeakNpcId"] = 100001,
            },
        [51010062] = {
            ["Content"] = "……普蒂妮？",
            ["ContentFR"] = "... Putini ?",
            ["DialogueId"] = 51010062,
            ["GUID"] = "7FB2C64C",
            ["NextDialogue"] = 51010063,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Think_Start",
                },
            },
        [51010063] = {
            ["Content"] = "如果你以后遇到了一个叫普蒂妮的女孩，请一定要认出我，我也一定会认出你的。",
            ["ContentFR"] = "« Si un jour tu rencontres une fille qui s’appelle Putini... j’espère que tu me reconnaîtras. Moi, je te reconnaîtrai. »",
            ["DialogueId"] = 51010063,
            ["GUID"] = "7FB2C676",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 51010064,
            },
        [51010064] = {
            ["Content"] = "怎么了，你笑什么？",
            ["ContentFR"] = "Qu’est-ce qui te fait sourire comme ça ?",
            ["DialogueId"] = 51010064,
            ["FacialId"] = {
                [1] = "100001:Happy02",
                },
            ["GUID"] = "7FB2C6A0",
            ["NextDialogue"] = 51010065,
            ["SpeakNpcId"] = 700302,
            ["TalkActionId"] = {
                [1] = "100001:Think_End",
                },
            },
        [51010065] = {
            ["Content"] = "如果连吉赛尔都没有认出来的话，看来有千面的不止是薇奥莱塔。",
            ["ContentFR"] = "Si même toi tu ne l’as pas reconnue... peut-être que Violetta n’est pas la seule à avoir mille visages.",
            ["DialogueId"] = 51010065,
            ["GUID"] = "7FB2C6CA",
            ["NextDialogue"] = 51010066,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Talk02R_Start",
                },
            },
        [51010066] = {
            ["Content"] = "人生的剧目不止有一场，我们总会在新的舞台再见。在那之前，祝你旅途愉快，箱子小姐。",
            ["ContentFR"] = "La vie ne se joue jamais en un seul acte. Nous nous reverrons sur une nouvelle scène. D’ici là... bon voyage à toi, Mademoiselle Caisse.",
            ["DialogueId"] = 51010066,
            ["GUID"] = "7FB2C6F4",
            ["IsBlack"] = 1,
            ["SpeakNpcId"] = 100001,
            },
        [51010067] = {
            ["Camera"] = "-257.685547,-253.308594,133.213379,0.000042,-0.199585,40.001606,38.587292,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "……",
            ["ContentFR"] = "...",
            ["DialogueId"] = 51010067,
            ["FacialId"] = {
                [1] = "100001:Sad01",
                },
            ["GUID"] = "7FB2C71E",
            ["NextDialogue"] = 51010068,
            ["SpeakNpcId"] = 100001,
            },
        [51010068] = {
            ["Content"] = "早上好，{nickname}，怎么看起来不太开心？",
            ["ContentFR"] = "Bonjour, {nickname}. Pourquoi cette mine triste ?",
            ["DialogueId"] = 51010068,
            ["GUID"] = "7FB2C748",
            ["NextDialogue"] = 51010069,
            ["SpeakNpcId"] = 700300,
            },
        [51010069] = {
            ["Content"] = "薇奥莱塔女士……",
            ["ContentFR"] = "Violetta...",
            ["DialogueId"] = 51010069,
            ["GUID"] = "7FB2C772",
            ["NextDialogue"] = 51010070,
            ["SpeakNpcId"] = 100001,
            },
        [51010070] = {
            ["Camera"] = "-182.809326,149.35498,133.001709,0.000049,-0.999878,-49.996906,35.520077,340.13559,false,Manual,2.8",
            ["Content"] = "好啦，不用再说了。明明要退休的是我，怎么反倒是你在难过。",
            ["ContentFR"] = "Allons, pas besoin d’en dire plus. C’est moi qui prends ma retraite, pas toi. Inutile d’avoir de la peine pour moi.",
            ["DialogueId"] = 51010070,
            ["FacialId"] = {
                [1] = "700300:CM_Smile01",
                },
            ["GUID"] = "7FB2C79C",
            ["NextDialogue"] = 51010071,
            ["SpeakNpcId"] = 700300,
            ["TalkActionId"] = {
                [1] = "700300:Disagree",
                },
            },
        [51010071] = {
            ["Content"] = "你只是做出了每一个坚守底线的人会做出的选择，不要为此有负担。就当是帮忙抓到了一个离家出走的孩子，好吗？",
            ["ContentFR"] = "Tu n’as fait que ce que ferait toute personne fidèle à ses principes. Ne porte pas ce poids sur tes épaules. Dis-toi simplement que tu as aidé une fugueuse à rentrer chez elle.",
            ["DialogueId"] = 51010071,
            ["GUID"] = "7FB2C7C6",
            ["NextDialogue"] = 51010072,
            ["SpeakNpcId"] = 700300,
            },
        [51010072] = {
            ["Camera"] = "-257.685547,-253.308594,133.213379,0.000042,-0.199585,40.001606,38.587292,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "看来人都到齐了？",
            ["ContentFR"] = "On dirait que tout le monde est là.",
            ["DialogueId"] = 51010072,
            ["GUID"] = "7FB2C7F0",
            ["NextDialogue"] = 51010073,
            ["Scripts"] = "MoveTo{ActorId{700302},TargetPoint{\"GisellePoint_20023305\"},MoveSpeed{150},Visibility{\"Show\"}}",
            ["SpeakNpcId"] = 700302,
            },
        [51010073] = {
            ["Content"] = "吉赛尔女士也来了，给，这是二位的门票。",
            ["ContentFR"] = "Parfait, Giselle, tiens — voici vos billets.",
            ["DialogueId"] = 51010073,
            ["GUID"] = "7FB2C81A",
            ["NextDialogue"] = 51010074,
            ["SpeakNpcId"] = 700300,
            ["TalkActionId"] = {
                [1] = "700300:Give",
                },
            },
        [51010074] = {
            ["Content"] = "那我就不客气了。已经和卫戍部队的朋友们打过招呼了，直到演出结束前他们都不会有动作。",
            ["ContentFR"] = "Merci. J’ai déjà contacté mes anciens collègues des Veilleurs : ils n’interviendront pas avant la fin du spectacle.",
            ["DialogueId"] = 51010074,
            ["GUID"] = "7FB2C844",
            ["NextDialogue"] = 51010075,
            ["SpeakNpcId"] = 700302,
            ["TalkActionId"] = {
                [1] = "700302:Confident_Start",
                },
            },
        [51010075] = {
            ["Content"] = "非常感谢。演出快要开始了，我先失陪去后台了。",
            ["ContentFR"] = "Je t’en suis très reconnaissante. La représentation va commencer, je dois aller en coulisses.",
            ["DialogueId"] = 51010075,
            ["GUID"] = "7FB2C86E",
            ["NextDialogue"] = 51010076,
            ["SpeakNpcId"] = 700300,
            ["TalkActionId"] = {
                [1] = "700300:Explain02_Start",
                },
            },
        [51010076] = {
            ["Content"] = "那我们也进去吧，虽然好像是我导致的，不过薇奥莱塔的告别演出的确让人期待。",
            ["ContentFR"] = "Allons-y aussi. Même si c’est en partie de ma faute, j’avoue que j’attends avec impatience cette représentation d’adieu.",
            ["DialogueId"] = 51010076,
            ["GUID"] = "7FB2C898",
            ["LookAt"] = {
                [1] = "100001:n(700302)",
                [2] = "700302:n(100001)",
                },
            ["NextDialogue"] = 51010077,
            ["SpeakNpcId"] = 700302,
            },
        [51010077] = {
            ["Content"] = "好。",
            ["ContentFR"] = "Allons-y.",
            ["DialogueId"] = 51010077,
            ["GUID"] = "7FB2C8C2",
            ["SpeakNpcId"] = 100001,
            },
        [51010078] = {
            ["Content"] = "你找到了薇奥莱塔为你安排的座位，在观众席等待着演出开场。",
            ["ContentFR"] = "Tu trouves les places réservées par Violetta et t’installes, attendant que le rideau se lève.",
            ["DialogueId"] = 51010078,
            ["GUID"] = "7FB2C8EC",
            ["NextDialogue"] = 51010079,
            },
        [51010079] = {
            ["Content"] = "随着看台的灯光逐渐熄灭，洪亮的女声唱白带着你的期待与好奇从幕布后侵染到整个演出厅。",
            ["ContentFR"] = "Alors que les lumières s’éteignent peu à peu, une puissante voix de soprano s’élève derrière le rideau, emplissant la salle d’une magie indicible.",
            ["DialogueId"] = 51010079,
            ["GUID"] = "7FB2C916",
            ["NextDialogue"] = 51010080,
            },
        [51010080] = {
            ["Content"] = "看台下异常安静，尚未习惯这种环境的你稍稍有些不安。",
            ["ContentFR"] = "Le public retient son souffle. Ce silence profond te met presque mal à l’aise.",
            ["DialogueId"] = 51010080,
            ["GUID"] = "7FB2C940",
            ["NextDialogue"] = 51010081,
            },
        [51010081] = {
            ["Content"] = "控制住对精彩桥段的赞美并非易事，你害怕自己无意识的感叹扰了他人雅兴。",
            ["ContentFR"] = "Il est difficile de retenir tes exclamations face aux scènes les plus spectaculaires — tu crains qu’un soupir d’admiration n’interrompe l’enchantement.",
            ["DialogueId"] = 51010081,
            ["GUID"] = "7FB2C96A",
            ["NextDialogue"] = 51010082,
            },
        [51010082] = {
            ["Content"] = "不过这种担忧是多余的——",
            ["ContentFR"] = "Mais cette crainte s’évanouit vite —",
            ["DialogueId"] = 51010082,
            ["GUID"] = "7FB2C994",
            ["NextDialogue"] = 51010083,
            },
        [51010083] = {
            ["Content"] = "为剧中人所牵动的你甚至忘记了鼓掌，直至演出结束……",
            ["ContentFR"] = "Tant et si bien qu’au moment où le dernier son s’éteint, tu en oublies même d’applaudir.",
            ["DialogueId"] = 51010083,
            ["GUID"] = "7FB2C9BE",
            },
        [51010084] = {
            ["Camera"] = "-34.440796,-11.397461,144.465332,0.000003,0.80015,-179.606598,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "吉赛尔，我需要你给我一个解释！",
            ["ContentFR"] = "Giselle ! Tu me dois des explications !",
            ["DialogueId"] = 51010084,
            ["FacialId"] = {
                [1] = "700304:CM_Angry01",
                },
            ["GUID"] = "7FB2C9E8",
            ["NextDialogue"] = 51010085,
            ["SpeakNpcId"] = 700304,
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["TalkActionId"] = {
                [1] = "700304:Angry01_Start",
                },
            },
        [51010085] = {
            ["Camera"] = "-446.109863,-216.286133,176.425781,0.000133,-6.999605,41.589813,60.202423,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "哦？无所不知的法布瑞斯大人，有什么事是需要我来给你解释的？",
            ["ContentFR"] = "Oh ? Et que pourrait bien vouloir savoir le grand Fabrice Ruthford ?",
            ["DialogueId"] = 51010085,
            ["GUID"] = "7FB2CA12",
            ["NextDialogue"] = 51010086,
            ["SpeakNpcId"] = 700302,
            ["TalkActionId"] = {
                [1] = "700302:Confident_Start",
                },
            },
        [51010086] = {
            ["Content"] = "是你举报了薇奥莱塔就是艾诺拉，可我带人来到了后台，那里一个人也没有！",
            ["ContentFR"] = "Tu as signalé que Violetta était Enola, mais quand je suis arrivé en coulisses avec mes hommes... il n’y avait plus personne !",
            ["DialogueId"] = 51010086,
            ["GUID"] = "7FB2CA3C",
            ["NextDialogue"] = 51010087,
            ["SpeakNpcId"] = 700304,
            },
        [51010087] = {
            ["Content"] = "是这件事啊……没想到您居然亲自来了，真是负责任的长官。",
            ["ContentFR"] = "Ah, ça. Je ne m’attendais pas à ce que tu viennes en personne. Quelle implication, vraiment.",
            ["DialogueId"] = 51010087,
            ["FacialId"] = {
                [1] = "700302:CM_Happy01",
                },
            ["GUID"] = "7FB2CA66",
            ["NextDialogue"] = 51010088,
            ["SpeakNpcId"] = 700302,
            },
        [51010088] = {
            ["Content"] = "别跟我阴阳怪气！我命令你，马上带我找到艾诺拉！",
            ["ContentFR"] = "Ne joue pas au plus malin ! Je t’ordonne de me conduire à Enola, tout de suite !",
            ["DialogueId"] = 51010088,
            ["GUID"] = "7FB2CA90",
            ["NextDialogue"] = 51010089,
            ["SpeakNpcId"] = 700304,
            },
        [51010089] = {
            ["Content"] = "您似乎忘了一件事，我现在已经不是卫戍部队的人了，您也不是。我只是作为一介平民向卫戍部队提供了一些线索而已。",
            ["ContentFR"] = "Il semble que tu oublies un détail : je ne fais plus partie des Veilleurs. Et toi non plus. J’ai simplement transmis une information... en tant que simple citoyenne.",
            ["DialogueId"] = 51010089,
            ["FacialId"] = {
                [1] = "700302:CM_Idle",
                },
            ["GUID"] = "7FB2CABA",
            ["NextDialogue"] = 51010090,
            ["SpeakNpcId"] = 700302,
            },
        [51010090] = {
            ["Content"] = "所以我没有义务听从你的命令，噢，也许你可以给“狩月人吉赛尔”发一份委托？",
            ["ContentFR"] = "Je ne suis donc pas tenue d’obéir à tes ordres. Par contre... tu peux toujours engager « Giselle la Chasseuse de Phoxène ».",
            ["DialogueId"] = 51010090,
            ["GUID"] = "7FB2CAE4",
            ["NextDialogue"] = 51010091,
            ["SpeakNpcId"] = 700302,
            },
        [51010091] = {
            ["Camera"] = "-34.440796,-11.397461,144.465332,0.000003,0.80015,-179.606598,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "你……！发委托就发委托！",
            ["ContentFR"] = "Très bien ! Alors je vais t’engager !",
            ["DialogueId"] = 51010091,
            ["GUID"] = "7FB2CB0E",
            ["NextDialogue"] = 51010092,
            ["SpeakNpcId"] = 700304,
            ["TalkActionId"] = {
                [1] = "700302:Confident_End",
                },
            },
        [51010092] = {
            ["Camera"] = "-446.109863,-216.286133,176.425781,0.000133,-6.999605,41.589813,60.202423,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "好的，我不接。",
            ["ContentFR"] = "Parfait. Je refuse la mission.",
            ["DialogueId"] = 51010092,
            ["FacialId"] = {
                [1] = "700302:CM_Happy01",
                },
            ["GUID"] = "7FB2CB38",
            ["NextDialogue"] = 51010093,
            ["SpeakNpcId"] = 700302,
            ["TalkActionId"] = {
                [1] = "700302:Talk01_Start",
                },
            },
        [51010093] = {
            ["Content"] = "你耍我？！",
            ["ContentFR"] = "Tu te moques de moi !?",
            ["DialogueId"] = 51010093,
            ["GUID"] = "7FB2CB62",
            ["NextDialogue"] = 51010094,
            ["SpeakNpcId"] = 700304,
            },
        [51010094] = {
            ["Content"] = "毕竟我现在有绑架伯爵千金的嫌疑，狩月人业务也只能暂停咯。",
            ["ContentFR"] = "Disons que, puisque je suis actuellement suspectée d’avoir \"kidnappé\"la fille d’un comte, mon activité est suspendue.",
            ["DialogueId"] = 51010094,
            ["FacialId"] = {
                [1] = "700302:CM_Idle",
                },
            ["GUID"] = "7FB2CB8C",
            ["NextDialogue"] = 51010095,
            ["SpeakNpcId"] = 700302,
            },
        [51010095] = {
            ["Content"] = "说到底，如果当年您老老实实听从我的建议推进谈判，如今也不会有这么多麻烦事。",
            ["ContentFR"] = "Au fond, si tu avais accepté la solution pacifique que je proposais à l’époque, tout ceci n’aurait jamais eu lieu.",
            ["DialogueId"] = 51010095,
            ["GUID"] = "7FB2CBB6",
            ["NextDialogue"] = 51010096,
            ["SpeakNpcId"] = 700302,
            },
        [51010096] = {
            ["Camera"] = "-34.440796,-11.397461,144.465332,0.000003,0.80015,-179.606598,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "你这女人……算我瞎了眼，居然信了你能找到艾诺拉。",
            ["ContentFR"] = "... Je n’aurais jamais dû croire que tu pouvais retrouver Enola.",
            ["DialogueId"] = 51010096,
            ["GUID"] = "7FB2CBE0",
            ["NextDialogue"] = 51010097,
            ["SpeakNpcId"] = 700304,
            ["TalkActionId"] = {
                [1] = "700302:Talk01_End",
                },
            },
        [51010097] = {
            ["Content"] = "艾诺拉……我的女儿，我会找到你的……至于你，以后别再让我看到你！",
            ["ContentFR"] = "Enola... ma fille... Je te retrouverai moi-même. Et toi, je ne veux plus jamais te revoir !",
            ["DialogueId"] = 51010097,
            ["GUID"] = "7FB2CC0A",
            ["NextDialogue"] = 51010098,
            ["SpeakNpcId"] = 700304,
            },
        [51010098] = {
            ["Camera"] = "-446.109863,-216.286133,176.425781,0.000133,-6.999605,41.589813,60.202423,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "求之不得。",
            ["ContentFR"] = "Avec plaisir.",
            ["DialogueId"] = 51010098,
            ["GUID"] = "7FB2CC34",
            ["NextDialogue"] = 51010099,
            ["Scripts"] = "MoveTo{ActorId{700304},TargetPoint{\"FabricePoint_20023305\"},MoveSpeed{150},Visibility{\"Hide\"}}",
            ["SpeakNpcId"] = 700302,
            ["TalkActionId"] = {
                [1] = "700302:Confident_Start",
                },
            },
        [51010099] = {
            ["Camera"] = "-446.109863,-216.286133,176.425781,0.000133,-6.999605,41.589813,60.202423,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "吉赛尔，你还好吧？",
            ["ContentFR"] = "Giselle, ça va ?",
            ["DialogueId"] = 51010099,
            ["FinalCamera"] = "-423.906006,-31.62793,121.737549,0.0,1.799973,0.000049,35.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "7FB2CC5E",
            ["NextDialogue"] = 51010100,
            ["Scripts"] = "SEQ{\
MoveTo{ActorId{100001},TargetPoint{\"NvzhuPoint_20023305\"},MoveSpeed{150},Visibility{\"Show\"}},\
PARA{\
LookAt{LookAtDescription{\"100001:n(700302)\"}},\
LookAt{LookAtDescription{\"700302:n(100001)\"}}\
}\
}",
            ["SpeakNpcId"] = 100001,
            ["ToFinalCameraBlendTime"] = 5,
            },
        [51010100] = {
            ["Camera"] = "-423.906006,-31.62793,121.737549,0.0,1.799973,0.000049,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我很好，在卫戍部队的时候可没机会这么和他说话，心情好多了。",
            ["ContentFR"] = "Très bien. Je n’aurais jamais pu lui parler ainsi quand j’étais chez les Veilleurs. Ça fait un bien fou.",
            ["DialogueId"] = 51010100,
            ["GUID"] = "7FB2CC88",
            ["LookAt"] = {
                [1] = "100001:n(700302)",
                [2] = "700302:n(100001)",
                },
            ["NextDialogue"] = 51010101,
            ["SpeakNpcId"] = 700302,
            },
        [51010101] = {
            ["Content"] = "刚刚那个人是……",
            ["ContentFR"] = "C’était qui, exactement ?",
            ["DialogueId"] = 51010101,
            ["FacialId"] = {
                [1] = "100001:Doubt01",
                },
            ["GUID"] = "7FB2CCB2",
            ["NextDialogue"] = 51010102,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Talk02R_Start",
                },
            },
        [51010102] = {
            ["Content"] = "法布瑞斯·鲁斯福德，薇奥莱塔的亲生父亲，还是和十六年前一样沉不住气。",
            ["ContentFR"] = "Fabrice Ruthford. Le père de Violetta. Toujours aussi impulsif qu’il y a seize ans.",
            ["DialogueId"] = 51010102,
            ["GUID"] = "7FB2CCDC",
            ["NextDialogue"] = 51010103,
            ["SpeakNpcId"] = 700302,
            ["TalkActionId"] = {
                [1] = "100001:Talk02R_End",
                },
            },
        [51010103] = {
            ["Content"] = "薇奥莱塔女士呢？",
            ["ContentFR"] = "Et Violetta ?",
            ["DialogueId"] = 51010103,
            ["GUID"] = "7FB2CD06",
            ["NextDialogue"] = 51010104,
            ["SpeakNpcId"] = 100001,
            },
        [51010104] = {
            ["Content"] = "跑了，法布瑞斯带人闯进后台的时候那里一个人都没有。",
            ["ContentFR"] = "Disparue. Quand Fabrice a débarqué, les coulisses étaient déjà vides.",
            ["DialogueId"] = 51010104,
            ["GUID"] = "7FB2CD30",
            ["NextDialogue"] = 51010105,
            ["SpeakNpcId"] = 700302,
            },
        [51010105] = {
            ["Content"] = "……啊！",
            ["ContentFR"] = "... Ah !",
            ["DialogueId"] = 51010105,
            ["GUID"] = "7FB2CD5A",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 51010106,
            ["Scripts"] = "SEQ{\
MoveTo{ActorId{700305},TargetPoint{\"RosalindPoint1_20023305\"},MoveSpeed{250},Visibility{\"Show\"}},\
PARA{\
LookAt{LookAtDescription{\"100001:n(700305)\"}},\
LookAt{LookAtDescription{\"700302:n(700305)\"}},\
TurnTo{TurnToDescription{\"700305:n(100001)\"}}\
},\
PARA{\
PlayAnimation{ActorId{100001},AnimationId{\"Shock_Start\"},Duration{1}},\
PlayAnimation{ActorId{700302},AnimationId{\"Angry01_Start\"},Duration{1}},\
PlayAnimation{ActorId{700305},AnimationId{\"Explain02_Start\"},Duration{1}}\
}}",
            ["SpeakNpcId"] = 700305,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Rosalind02",
            },
        [51010106] = {
            ["Camera"] = "-442.745117,136.447266,137.21167,0.000002,-3.200169,-35.40036,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "抱……抱歉，我刚才没看路！没受伤吧？有没有哪里不舒服？",
            ["ContentFR"] = "P-Pardon, je ne regardais pas devant moi ! Tu vas bien ? Je ne t’ai pas fait mal ?",
            ["DialogueId"] = 51010106,
            ["FacialId"] = {
                [1] = "700302:CM_Angry01",
                },
            ["GUID"] = "7FB2CD84",
            ["NextDialogue"] = 51010107,
            ["SpeakNpcId"] = 700305,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Rosalind02",
            },
        [51010107] = {
            ["Content"] = "我没事，下次注意就好。",
            ["ContentFR"] = "Je vais bien. Faites juste attention, d’accord ?",
            ["DialogueId"] = 51010107,
            ["GUID"] = "7FB2CDAE",
            ["NextDialogue"] = 51010108,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Shock_End",
                [2] = "700302:Angry01_End",
                },
            },
        [51010108] = {
            ["Camera"] = "-77.586914,100.682129,157.737793,0.000019,-6.000089,-109.999786,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "嗯——",
            ["ContentFR"] = "Mmm...",
            ["DialogueId"] = 51010108,
            ["GUID"] = "7FB2CDD8",
            ["NextDialogue"] = 51010109,
            ["SpeakNpcId"] = 700305,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Rosalind02",
            ["TalkActionId"] = {
                [1] = "700305:Think_Start",
                },
            },
        [51010109] = {
            ["Camera"] = "-304.188965,-104.091309,139.379639,0.000002,-0.600189,4.199689,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我的脸上怎么了吗？",
            ["ContentFR"] = "J’ai quelque chose sur le visage ?",
            ["DialogueId"] = 51010109,
            ["FacialId"] = {
                [1] = "100001:Unhappy01",
                },
            ["GUID"] = "7FB2CE02",
            ["NextDialogue"] = 51010110,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Talk03_Start",
                },
            },
        [51010110] = {
            ["Camera"] = "-77.586914,100.682129,157.737793,0.000019,-6.000089,-109.999786,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "没什么，嘻嘻……谢谢你的草药。",
            ["ContentFR"] = "Non, rien du tout... Hihi... Merci pour les herbes ! ",
            ["DialogueId"] = 51010110,
            ["FacialId"] = {
                [1] = "700305:CM_Happy01",
                },
            ["GUID"] = "7FB2CE2C",
            ["NextDialogue"] = 51010111,
            ["SpeakNpcId"] = 700305,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Rosalind02",
            ["TalkActionId"] = {
                [1] = "700305:Think_End",
                },
            },
        [51010111] = {
            ["Content"] = "约定的时间要来不及了哦。",
            ["ContentFR"] = "L’heure tourne ! Tu vas être en retard !",
            ["DialogueId"] = 51010111,
            ["GUID"] = "7FB2CE56",
            ["NextDialogue"] = 51010112,
            ["SpeakNpcId"] = 700311,
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            },
        [51010112] = {
            ["Content"] = "啊抱歉了我得走了！来了来了，等等我！",
            ["ContentFR"] = "Oh non ! Je dois filer ! J’arrive, attendez-moi !",
            ["DialogueId"] = 51010112,
            ["GUID"] = "7FB2CE80",
            ["NextDialogue"] = 51010113,
            ["Scripts"] = "MoveTo{ActorId{700305},TargetPoint{\"RosalindPoint2_20023305\"},MoveSpeed{250},Visibility{\"Hide\"}}",
            ["SpeakNpcId"] = 700305,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Rosalind02",
            },
        [51010113] = {
            ["Content"] = "什么草药……？等一下，你东西掉了！",
            ["ContentFR"] = "Des herbes... ? Attendez, vous avez fait tomber quelque chose !",
            ["DialogueId"] = 51010113,
            ["GUID"] = "7FB2CEAA",
            ["NextDialogue"] = 51010114,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Nvzhu_Story_StretchHand_Start",
                },
            },
        [51010114] = {
            ["Content"] = "——送给你了！！",
            ["ContentFR"] = "Garde-le ! C’est pour toi !",
            ["DialogueId"] = 51010114,
            ["GUID"] = "7FB2CED4",
            ["NextDialogue"] = 51010115,
            ["SpeakNpcId"] = 700305,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Rosalind02",
            ["TalkActionId"] = {
                [1] = "100001:Nvzhu_Story_StretchHand_End",
                },
            },
        [51010115] = {
            ["Camera"] = "-423.906006,-31.62793,121.737549,0.0,1.799973,0.000049,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "现在的年轻人还真是风风火火。",
            ["ContentFR"] = "Sérieusement... les jeunes, aujourd’hui, sont toujours aussi pressés.",
            ["DialogueId"] = 51010115,
            ["GUID"] = "7FB2CEFE",
            ["LookAt"] = {
                [1] = "700302:n(100001)",
                [2] = "100001:n(700302)",
                },
            ["NextDialogue"] = 51010116,
            ["SpeakNpcId"] = 700302,
            },
        [51010116] = {
            ["Content"] = "说什么送给我了……这上面好像绣了字，是那个女孩的名字吗？",
            ["ContentFR"] = "Pourquoi m’a-t-elle laissé ça... ?",
            ["DialogueId"] = 51010116,
            ["FacialId"] = {
                [1] = "100001:Doubt01",
                [2] = "700302:CM_Idle",
                },
            ["GUID"] = "7FB2CF28",
            ["NextDialogue"] = 51010117,
            ["SpeakNpcId"] = 100001,
            },
        [51010117] = {
            ["Content"] = "勇敢的蝴蝶挣脱了茧，向着天空振翅，她随风隐去，就像一枝紫罗兰消失在花海。",
            ["ContentFR"] = "Une courageuse chenille s’est changée en papillon et s’est envolée vers le ciel. Elle a disparu dans le vent... comme une violette perdue dans une mer de fleurs.",
            ["DialogueId"] = 51010117,
            ["FacialId"] = {
                [1] = "100001:None",
                },
            ["GUID"] = "7FB2CF52",
            ["NextDialogue"] = 51010118,
            ["Scripts"] = "MoveTo{ActorId{700311},TargetPoint{\"ViolettePoint_20023305\"},MoveSpeed{150},Visibility{\"Show\"}}",
            ["SpeakNpcId"] = 700311,
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            },
        [51010118] = {
            ["Camera"] = "-77.586914,100.682129,157.737793,0.000019,-6.000089,-109.999786,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "她可能很长一段时间都不会再同你我见面了……所以收下这份临别的礼物吧，她珍视的朋友。",
            ["ContentFR"] = "Elle ne reviendra peut-être pas avant longtemps... alors prends ceci, un cadeau d’adieu de la part d’une amie précieuse.",
            ["DialogueId"] = 51010118,
            ["GUID"] = "7FB2CF7C",
            ["LookAt"] = {
                [1] = "100001:n(700311)",
                [2] = "700302:n(700311)",
                },
            ["NextDialogue"] = 51010119,
            ["SpeakNpcId"] = 700311,
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            },
        [51010119] = {
            ["Camera"] = "-304.188965,-104.091309,139.379639,0.000002,-0.600189,4.199689,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "临别的礼物……这上面好像绣了字，是那个女孩的名字吗？",
            ["ContentFR"] = "Un cadeau d’adieu... ? Il y a une broderie dessus... C’est son nom ?",
            ["DialogueId"] = 51010119,
            ["GUID"] = "7FB2CFA6",
            ["NextDialogue"] = 51010120,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Think_Start",
                },
            },
        [51010120] = {
            ["Content"] = "……普蒂妮？",
            ["ContentFR"] = "... Putini ?",
            ["DialogueId"] = 51010120,
            ["GUID"] = "7FB2CFD0",
            ["NextDialogue"] = 51010121,
            ["SpeakNpcId"] = 100001,
            },
        [51010121] = {
            ["Content"] = "如果你以后遇到了一个叫普蒂妮的女孩，请一定要认出我，我也一定会认出你的。",
            ["ContentFR"] = "Si un jour tu rencontres une fille qui s’appelle Putini... j’espère que tu me reconnaîtras. Moi, je te reconnaîtrai.",
            ["DialogueId"] = 51010121,
            ["GUID"] = "7FB2CFFA",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 51010122,
            },
        [51010122] = {
            ["Content"] = "原来是这样啊，看来箱子小姐她平安踏上自己的旅途了。这么说来你是——",
            ["ContentFR"] = "Je vois... Alors, Mademoiselle Caisse a pris son envol en toute sécurité. Ce qui veut dire que tu es—",
            ["DialogueId"] = 51010122,
            ["GUID"] = "7FB2D024",
            ["NextDialogue"] = 51010123,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Think_End",
                },
            },
        [51010123] = {
            ["Camera"] = "-77.586914,100.682129,157.737793,0.000019,-6.000089,-109.999786,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "嘘——虽然我认可你们的揭发，但还是会保守秘密的孩子更可爱哦。",
            ["ContentFR"] = "Chut... Même si je respecte ta décision de révéler la vérité, ceux qui savent garder un secret sont toujours les plus charmants.",
            ["DialogueId"] = 51010123,
            ["GUID"] = "7FB2D04E",
            ["NextDialogue"] = 51010124,
            ["SpeakNpcId"] = 700311,
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["TalkActionId"] = {
                [1] = "700311:Disagree",
                },
            },
        [51010124] = {
            ["Content"] = "就这么暴露身份，你不怕我再找麻烦？",
            ["ContentFR"] = "Tu n’as pas peur que je revienne te chercher ?",
            ["DialogueId"] = 51010124,
            ["GUID"] = "7FB2D078",
            ["NextDialogue"] = 51010125,
            ["SpeakNpcId"] = 700302,
            },
        [51010125] = {
            ["Content"] = "“薇奥莱塔”不会再登台，可我短期内并不打算离开这里。当然，就算你再次揭发，我也不会有怨言。只是事关我的另一位学生，我无法弃之不顾。",
            ["ContentFR"] = "« Violetta » ne remontera plus jamais sur scène. Mais je ne suis pas prête à partir. Même si tu me dénonces à nouveau, je n’en voudrais à personne. J’ai encore un élève que je ne peux pas abandonner.",
            ["DialogueId"] = 51010125,
            ["GUID"] = "7FB2D0A2",
            ["NextDialogue"] = 51010126,
            ["SpeakNpcId"] = 700311,
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            },
        [51010126] = {
            ["Content"] = "……",
            ["ContentFR"] = "...",
            ["DialogueId"] = 51010126,
            ["GUID"] = "7FB2D0CC",
            ["NextDialogue"] = 51010127,
            ["SpeakNpcId"] = 700302,
            },
        [51010127] = {
            ["Content"] = "……感谢你的沉默。",
            ["ContentFR"] = "Merci... pour ton silence.",
            ["DialogueId"] = 51010127,
            ["FacialId"] = {
                [1] = "700311:CM_Happy01",
                },
            ["GUID"] = "7FB2D0F6",
            ["NextDialogue"] = 51010128,
            ["SpeakNpcId"] = 700311,
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["TalkActionId"] = {
                [1] = "700311:Agree",
                },
            },
        [51010128] = {
            ["Content"] = "那么失陪了，愿二位度过一个美妙的假日。",
            ["ContentFR"] = "Sur ce, je vous laisse. Je vous souhaite à tous deux une très belle soirée.",
            ["DialogueId"] = 51010128,
            ["GUID"] = "7FB2D120",
            ["NextDialogue"] = 51010129,
            ["Scripts"] = "MoveTo{ActorId{700311},TargetPoint{\"RosalindPoint2_20023305\"},MoveSpeed{150},Visibility{\"Hide\"}}",
            ["SpeakNpcId"] = 700311,
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            },
        [51010129] = {
            ["Camera"] = "-423.906006,-31.62793,121.737549,0.0,1.799973,0.000049,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "哈，我就知道，那样的女人怎么可能乖乖束手就擒。",
            ["ContentFR"] = "Ah. Je le savais. Une femme comme elle n’allait jamais se laisser attraper si facilement.",
            ["DialogueId"] = 51010129,
            ["FacialId"] = {
                [1] = "700302:CM_Smile01",
                },
            ["GUID"] = "7FB2D14A",
            ["LookAt"] = {
                [1] = "700302:n(100001)",
                [2] = "100001:n(700302)",
                },
            ["NextDialogue"] = 51010130,
            ["SpeakNpcId"] = 700302,
            ["TalkActionId"] = {
                [1] = "700302:Confident_Start",
                },
            },
        [51010130] = {
            ["Content"] = "你看起来好像有点高兴？",
            ["ContentFR"] = "On dirait que ça te réjouit presque ?",
            ["DialogueId"] = 51010130,
            ["GUID"] = "7FB2D174",
            ["NextDialogue"] = 51010131,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Talk02R_Start",
                },
            },
        [51010131] = {
            ["Content"] = "这样吗？说实话，我也纠结过到底要不要牺牲活人的生活去换死者的清白……",
            ["ContentFR"] = "Vraiment ? Pour être honnête, j’ai longtemps hésité : fallait-il détruire la vie d’une femme talentueuse pour laver l’honneur d’un mort... ?",
            ["DialogueId"] = 51010131,
            ["GUID"] = "7FB2D19E",
            ["NextDialogue"] = 51010132,
            ["SpeakNpcId"] = 700302,
            ["TalkActionId"] = {
                [1] = "100001:Talk02R_End",
                },
            },
        [51010132] = {
            ["Content"] = "如你所见，我做出了选择，这是吉赛尔的执着。",
            ["ContentFR"] = "Mais j’ai fait mon choix. Têtue comme toujours.",
            ["DialogueId"] = 51010132,
            ["GUID"] = "7FB2D1C8",
            ["NextDialogue"] = 51010133,
            ["SpeakNpcId"] = 700302,
            },
        [51010133] = {
            ["Content"] = "不过既然能在二选一的局面被打破后而感到开心，说明我这十六年来也有了成长不是吗？",
            ["ContentFR"] = "Et si je peux aujourd’hui accepter une fin ouverte, c’est bien la preuve que j’ai changé en seize ans, non ?",
            ["DialogueId"] = 51010133,
            ["FacialId"] = {
                [1] = "700302:CM_Sad01",
                },
            ["GUID"] = "7FB2D1F2",
            ["NextDialogue"] = 51010134,
            ["SpeakNpcId"] = 700302,
            },
        [51010134] = {
            ["Content"] = "要是十六年前的我也能像现在一样，或许就不会有人因此逝去了。",
            ["ContentFR"] = "Si j’avais compris cela il y a seize ans... peut-être que personne n’aurait eu à mourir.",
            ["DialogueId"] = 51010134,
            ["GUID"] = "7FB2D21C",
            ["NextDialogue"] = 51010135,
            ["SpeakNpcId"] = 700302,
            },
        [51010135] = {
            ["Content"] = "这不是你的错，吉赛尔。",
            ["ContentFR"] = "Ce n’était pas ta faute, Giselle.",
            ["DialogueId"] = 51010135,
            ["FacialId"] = {
                [1] = "100001:Smile01",
                },
            ["GUID"] = "7FB2D246",
            ["NextDialogue"] = 51010136,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Disagree",
                },
            },
        [51010136] = {
            ["Content"] = "放心，我没有难过，我只是在想“狩月人吉赛尔”歇业后要去做点什么。",
            ["ContentFR"] = "Je sais. Je ne suis pas triste. Je me demande juste ce que je vais faire maintenant que « Giselle la Chasseuse de Phoxène » a pris sa retraite.",
            ["DialogueId"] = 51010136,
            ["FacialId"] = {
                [1] = "700302:CM_Smile01",
                },
            ["GUID"] = "7FB2D270",
            ["NextDialogue"] = 51010137,
            ["SpeakNpcId"] = 700302,
            },
        [51010137] = {
            ["Content"] = "我放弃当演员了，看过薇奥莱塔的演出之后很难再夸下这种海口啊……",
            ["ContentFR"] = "J’abandonne l’idée de devenir comédienne. Après avoir vu Violetta sur scène, difficile de me comparer...",
            ["DialogueId"] = 51010137,
            ["GUID"] = "7FB2D29A",
            ["NextOptions"] = {
                [1] = 510100471,
                [2] = 510100472,
                },
            ["SpeakNpcId"] = 700302,
            },
        }
  end },
  { MinKey = 51010138, MaxKey = 51011018, Loader = function()
      return {
        [51010138] = {
            ["Content"] = "因为感觉很赚钱。",
            ["ContentFR"] = "Oui... parce que ça paye bien.",
            ["DialogueId"] = 51010138,
            ["FacialId"] = {
                [1] = "700302:CM_Happy01",
                },
            ["GUID"] = "7FB2D2C4",
            ["NextDialogue"] = 51010140,
            ["SpeakNpcId"] = 700302,
            },
        [51010139] = {
            ["Content"] = "就别挖苦我了，真正的神探。",
            ["ContentFR"] = "D’accord, d’accord... pas la peine d’en rajouter, Détective {nickname}.",
            ["DialogueId"] = 51010139,
            ["GUID"] = "7FB2D2EE",
            ["NextDialogue"] = 51010140,
            ["SpeakNpcId"] = 700302,
            },
        [51010140] = {
            ["Content"] = "那现在呢，你打算做什么？",
            ["ContentFR"] = "Et maintenant ? Tu as un nouveau plan ?",
            ["DialogueId"] = 51010140,
