            ["SpeakNpcId"] = 700302,
            },
        [51010143] = {
            ["Camera"] = "-19.636719,461.339844,156.540039,0.000053,-6.400208,-95.20314,35.333332,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "请等一下！",
            ["ContentFR"] = "Attends !",
            ["DialogueId"] = 51010143,
            ["FacialId"] = {
                [1] = "700300:CM_Smile01",
                [2] = "700302:CM_Angry01",
