                [1] = "100001:Nvzhu_Story_StretchHand_Start",
                },
            },
        [51010201] = {
            ["Content"] = "♪熔炉焚烧黎明 倾倒出白雪与铁的城塞……",
            ["ContentFR"] = "♪ Le feu de la forge embrase l’aube, érigeant une forteresse de neige et de fer... ♪",
            ["DialogueId"] = 51010201,
            ["GUID"] = "7FB2DD1A",
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/env/700342/7FB2DD1A",
            },
        [51010202] = {
            ["Content"] = "♪熔炉焚烧黎明 倾倒出白雪与铁的城塞\
齿轮高歌 吞没晨星 赞颂北地的伟大时代——",
            ["ContentFR"] = "♪ Le feu de la forge embrase l’aube, érigeant une forteresse de neige et de fer...\
Les rouages entonnent leur chant, engloutissant l’étoile du matin, célébrant l’âge glorieux du Nord... ♪",
            ["DialogueId"] = 51010202,
            ["GUID"] = "7FB2DD44",
            ["NextDialogue"] = 51010203,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510102/7FB2DD44",
            },
        [51010203] = {
            ["Content"] = "嗯？你叫我……",
            ["ContentFR"] = "Hmm ? Tu m’as appelé... ?",
            ["DialogueId"] = 51010203,
            ["GUID"] = "7FB2DD6E",
            ["LookAt"] = {
                [1] = "700342:n(0)",
                },
            ["NextOptions"] = {
                [1] = 510102031,
                [2] = 510102032,
                },
            ["SpeakNpcId"] = 700342,
            ["TalkActionId"] = {
                [1] = "700342:Lilikou_Story_Playlyre_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/510102/7FB2DD6E",
            },
        [51010204] = {
            ["Content"] = "谢谢你，陌生的旅人！不过这首歌还没有完成，或许你可以和我一起来创作它。",
            ["ContentFR"] = "Merci, {性别:voyageur inconnu|voyageuse inconnue} ! Mais cette chanson n’est pas encore achevée... Peut-être pourrais-tu m’aider à en trouver la fin ?",
            ["DialogueId"] = 51010204,
            ["GUID"] = "7FB2DD98",
            ["NextDialogue"] = 51010206,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510102/7FB2DD98",
            },
        [51010205] = {
            ["Content"] = "很抱歉打扰到你！不过我问过那边的士兵，这座城市的广场并没有张贴律令，禁止一位吟游诗人在这里唱歌。",
            ["ContentFR"] = "Oh... pardon de t’avoir dérangé ! Mais j’ai demandé au soldat là-bas : aucune loi n’interdit à un ménestrel de chanter sur cette place.",
            ["DialogueId"] = 51010205,
            ["GUID"] = "7FB2DDC2",
            ["NextDialogue"] = 51010206,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510102/7FB2DDC2",
            },
        [51010206] = {
            ["Content"] = "后一句应该是什么呢……",
            ["ContentFR"] = "Hmm... quelle devrait être la dernière ligne... ?",
            ["DialogueId"] = 51010206,
            ["GUID"] = "7FB2DDEC",
            ["NextDialogue"] = 51010207,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510102/7FB2DDEC",
            },
        [51010207] = {
            ["Content"] = "我想我应该写“风”……每个地方的风都是不同的……",
            ["ContentFR"] = "Je pense qu’elle devrait parler du vent... Chaque endroit a son propre souffle...",
            ["DialogueId"] = 51010207,
            ["GUID"] = "7FB2DE16",
            ["NextDialogue"] = 51010208,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510102/7FB2DE16",
            },
        [51010208] = {
            ["Content"] = "艾利西安的风是融化在晚祷里的乳香，卢卡的风是画室的松节油和咖啡店的焦糖，伊瑟尔的风是混着野薄荷的油墨……",
            ["ContentFR"] = "À Élysium, le vent sent l’encens fondu dans les prières du soir. À Luca, il porte l’odeur de l’essence de pin des ateliers de peinture et du caramel des cafés. À Aethyrie, il se mêle à l’encre et à la menthe sauvage...",
            ["DialogueId"] = 51010208,
            ["GUID"] = "7FB2DE40",
            ["NextDialogue"] = 51010209,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510102/7FB2DE40",
            },
        [51010209] = {
            ["Content"] = "那么海伯利亚的“风”是什么呢？",
            ["ContentFR"] = "Et ici, en Hyperborea... à quoi ressemble le vent ?",
            ["DialogueId"] = 51010209,
            ["GUID"] = "7FB2DE6A",
            ["NextOptions"] = {
                [1] = 510102091,
                [2] = 510102092,
                [3] = 510102093,
                },
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510102/7FB2DE6A",
            },
        [51010210] = {
            ["Content"] = "嗯……你说的有道理。这里有很多钢铁的森林，就像这座城市一样。",
            ["ContentFR"] = "Hmm... tu n’as pas tort. Cette cité est née de l’acier — une forêt forgée plutôt que semée.",
            ["DialogueId"] = 51010210,
            ["GUID"] = "7FB2DE94",
            ["NextDialogue"] = 51010211,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510102/7FB2DE94",
            },
        [51010211] = {
            ["Content"] = "虽然吹起来有些冷，但风会捎来那些齿轮和引擎的声音，它们摸起来总是滚烫的。",
            ["ContentFR"] = "Le vent est glacial, oui... mais il transporte le grondement des engrenages et le souffle brûlant des forges. Et lorsque tu tends la main... il te brûle la peau.",
            ["DialogueId"] = 51010211,
            ["GUID"] = "7FB2DEBE",
            ["NextDialogue"] = 51010212,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510102/7FB2DEBE",
            },
        [51010212] = {
            ["Content"] = "士兵的枪管或许也是滚烫的，虽然他们的表情是冷的……",
            ["ContentFR"] = "Comme le canon d’un fusil de soldat : brûlant, même quand le visage qui le tient reste de pierre.",
            ["DialogueId"] = 51010212,
            ["GUID"] = "7FB2DEE8",
            ["NextDialogue"] = 51010220,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510102/7FB2DEE8",
            },
        [51010213] = {
            ["Content"] = "嗯！这座城市的四分之三是由雪组成的。因为这里的人说，冰湖城总是在下雪，融雪季只有短短的三个月~",
            ["ContentFR"] = "Oui ! On dit que les trois quarts de cette cité sont faits de neige. Les habitants racontent qu’à Givrelac, il neige presque toute l’année — la fonte ne dure que trois mois.",
            ["DialogueId"] = 51010213,
            ["GUID"] = "7FB2DF12",
            ["NextDialogue"] = 51010214,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510102/7FB2DF12",
            },
        [51010214] = {
            ["Content"] = "而且风和雪总是在一起的，这是大自然给我们的经典搭配！",
            ["ContentFR"] = "Et le vent et la neige sont inséparables. C’est le duo éternel que la nature nous offre.",
            ["DialogueId"] = 51010214,
            ["GUID"] = "7FB2DF3C",
            ["NextDialogue"] = 51010220,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510102/7FB2DF3C",
            },
        [51010215] = {
            ["Content"] = "“眼泪”吗……是这首歌前面没有用过的意象呢……",
            ["ContentFR"] = "Des larmes... Voilà une image que je n’ai pas encore employée...",
            ["DialogueId"] = 51010215,
            ["GUID"] = "7FB2DF66",
            ["NextDialogue"] = 51010216,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510102/7FB2DF66",
            },
        [51010216] = {
            ["Content"] = "…………",
            ["ContentFR"] = "...",
            ["DialogueId"] = 51010216,
            ["GUID"] = "7FB2DF90",
            ["NextDialogue"] = 51010217,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510102/7FB2DF90",
            },
        [51010217] = {
            ["Content"] = "第一天来到这座广场时，我看到一位目盲的小丑在广场表演，他说他的眼是多年前被锅炉熏坏的。一个孩子被表演逗得狂笑不止，他的仆人便抛下银币。",
            ["ContentFR"] = "Le premier jour où je suis venu sur cette place, j’ai vu un bouffon aveugle donner un spectacle. Il disait que ses yeux avaient été brûlés par la vapeur d’une chaudière, des années plus tôt. Un enfant riait à s’en rouler par terre, et son serviteur a jeté une pièce d’argent.",
            ["DialogueId"] = 51010217,
            ["GUID"] = "7FB2DFBA",
            ["NextDialogue"] = 51010218,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510102/7FB2DFBA",
            },
        [51010218] = {
            ["Content"] = "我现在坐的这条长椅上，一个退伍老兵叫喊着，兜售自己最后一枚勋章。旁边的长椅上，一个消瘦的母亲从干瘪的乳房挤出奶水喂给她重病的孩子。",
            ["ContentFR"] = "Sur ce même banc où je suis assis, un ancien soldat hurlait en essayant de vendre sa dernière médaille. Sur le banc voisin, une mère amaigrie tirait quelques maigres gouttes de lait de son corps épuisé pour nourrir son enfant gravement malade.",
            ["DialogueId"] = 51010218,
            ["GUID"] = "7FB2DFE4",
            ["NextDialogue"] = 51010219,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510102/7FB2DFE4",
            },
        [51010219] = {
            ["Content"] = "……我想那时，吹过这座广场的风，捎来的就是“眼泪”吧。",
            ["ContentFR"] = "... Ce jour-là, le vent qui traversait la place portait avec lui le goût des larmes.",
            ["DialogueId"] = 51010219,
            ["GUID"] = "7FB2E00E",
            ["NextDialogue"] = 51010220,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510102/7FB2E00E",
            },
        [51010220] = {
            ["Content"] = "谢谢你的建议，如冰原上玫瑰一般的{性别：先生|小姐}……我想，我很快就可以完成这首歌了。",
            ["ContentFR"] = "Merci pour ton inspiration, {性别:monsieur|mademoiselle}... une rose éclose au cœur de la toundra. Grâce à toi, je crois que ma chanson touche enfin à sa fin.",
            ["DialogueId"] = 51010220,
            ["GUID"] = "7FB2E038",
            ["SpeakNpcId"] = 700342,
            ["TalkActionId"] = {
                [1] = "700342:Lilikou_Story_Playlyre_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/510102/7FB2E038",
            },
        [51010221] = {
            ["Content"] = "谢谢你的建议，如冰原上玫瑰一般的{性别：先生|小姐}。",
            ["ContentFR"] = "Merci, {性别:monsieur|mademoiselle}. Grâce à toi, j’ai trouvé la dernière strophe. Tu es comme une rose qui fleurit sur la toundra glacée.",
            ["DialogueId"] = 51010221,
            ["GUID"] = "7FB2E062",
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510102/7FB2E062",
            },
        [51010301] = {
            ["Content"] = "卡戎之民的雾海神话……",
            ["ContentFR"] = "Les anciens mythes des Charons...",
            ["DialogueId"] = 51010301,
            ["GUID"] = "7FB2ED82",
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/env/700342/7FB2ED82",
            },
        [51010302] = {
            ["Content"] = "……最有趣的就是这一篇，它说雾海中的万物都在生和死的循环中，你觉得呢？伊——",
            ["ContentFR"] = "... celui-ci est particulièrement fascinant : il raconte que, dans la Mer du Silence, toutes choses sont prises dans un cycle infini de vie et de mort. Qu’en penses-tu, Idy—",
            ["DialogueId"] = 51010302,
            ["GUID"] = "7FB2EDAC",
            ["NextDialogue"] = 51010303,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510103/7FB2EDAC",
            },
        [51010303] = {
            ["Content"] = "啊，是你！我记得你的，我们上次就在这儿说过话。",
            ["ContentFR"] = "Ah, c’est toi ! Je me souviens de toi — nous avons parlé ici même, la dernière fois.",
            ["DialogueId"] = 51010303,
            ["GUID"] = "7FB2EDD6",
            ["NextDialogue"] = 51010304,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510103/7FB2EDD6",
            },
        [51010304] = {
            ["Content"] = "你有看到我的朋友吗？一个红发的女孩子，刚才应该就在这儿……",
            ["ContentFR"] = "As-tu vu mon amie ? Une jeune fille aux cheveux rouges, insaisissable comme le vent... Elle était là il y a un instant.",
            ["DialogueId"] = 51010304,
            ["GUID"] = "7FB2EE00",
            ["NextOptions"] = {
                [1] = 51010305,
                },
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510103/7FB2EE00",
            },
        [51010305] = {
            ["Content"] = "没有见过。",
            ["ContentFR"] = "<I>Non, je n’ai vu personne comme ça.</>",
            ["DialogueId"] = 51010305,
            ["GUID"] = "7FB2EE2A",
            ["NextDialogue"] = 51010306,
            },
        [51010306] = {
            ["Content"] = "谢谢！那我继续等一会儿。她常常突然离开，又突然回来。",
            ["ContentFR"] = "Merci ! Je vais l’attendre encore un peu. Elle a l’habitude de disparaître sans prévenir... pour réapparaître tout aussi soudainement.",
            ["DialogueId"] = 51010306,
            ["GUID"] = "7FB2EE54",
            ["NextDialogue"] = 51010307,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510103/7FB2EE54",
            },
        [51010307] = {
            ["Content"] = "这几天，我们在这儿收集了许多卡戎之民的古老神话。我很惊讶，这里的人竟然不避讳讲这些。",
            ["ContentFR"] = "Ces derniers jours, nous avons collecté de nombreux mythes Charons. Je suis surpris de voir à quel point les gens ici en parlent librement.",
            ["DialogueId"] = 51010307,
            ["GUID"] = "7FB2EE7E",
            ["NextDialogue"] = 51010308,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510103/7FB2EE7E",
            },
        [51010308] = {
            ["Content"] = "在我们的故乡艾利西安，那里的卡戎之民地位比这里崇高得多。他们坐在高台上，与神问答，执掌权柄。但在那儿，讨论古老的神话是一件危险的事。",
            ["ContentFR"] = "Dans mon pays, à Élysium, les Charons sont bien plus vénérés : ils siègent dans des temples élevés, dialoguent avec les dieux et détiennent l’autorité. Mais là-bas, évoquer les anciens mythes est dangereux.",
            ["DialogueId"] = 51010308,
            ["GUID"] = "7FB2EEA8",
            ["NextDialogue"] = 51010309,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510103/7FB2EEA8",
            },
        [51010309] = {
            ["Content"] = "对了，你知道卡戎之民的神话吗？",
            ["ContentFR"] = "Dis-moi, connais-tu ces mythes Charons ?",
            ["DialogueId"] = 51010309,
            ["GUID"] = "7FB2EED2",
            ["NextOptions"] = {
                [1] = 51010310,
                [2] = 51010311,
                },
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510103/7FB2EED2",
            },
        [51010310] = {
            ["Content"] = "知道一点。",
            ["ContentFR"] = "<I>Un peu.</>",
            ["DialogueId"] = 51010310,
            ["GUID"] = "7FB2EEFC",
            ["NextDialogue"] = 51010312,
            },
        [51010311] = {
            ["Content"] = "不知道。",
            ["ContentFR"] = "<I>Pas vraiment.</>",
            ["DialogueId"] = 51010311,
            ["GUID"] = "7FB2EF26",
            ["NextDialogue"] = 51010312,
            },
        [51010312] = {
            ["Content"] = "“卡戎”，这个词的意思是“来自雾海之人”……",
            ["ContentFR"] = "Charon signifie « ceux qui viennent de la Mer du Silence »...",
            ["DialogueId"] = 51010312,
            ["GUID"] = "7FB2EF50",
            ["NextDialogue"] = 51010313,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510103/7FB2EF50",
            },
        [51010313] = {
            ["Content"] = "雾海是一切的原点。圣树自雾海生长，天之树是它庞大的枝叶，世界则立于圣树之上。",
            ["ContentFR"] = "La mer est l’origine de tout. De ses profondeurs a surgi l’Arbre Sacré. Son feuillage s’est étendu jusqu’aux cieux, et chacune de ses branches devint un Arbre Céleste. Ses racines, elles, ont donné naissance au monde.",
            ["DialogueId"] = 51010313,
            ["GUID"] = "7FB2EF7A",
            ["NextDialogue"] = 51010314,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510103/7FB2EF7A",
            },
        [51010314] = {
            ["Content"] = "圣树绽放纯白的花，从中走出母神茵布拉。她创造万物，其中就有父神埃斯刻。母神与父神诞育出卡戎之民共同的先祖。",
            ["ContentFR"] = "L’Arbre Sacré fleurit de fleurs blanches, et de ces fleurs naquit la Mère — Embla. Elle créa toutes choses, et de son essence naquit le Père — Ask. Ensemble, ils engendrèrent les ancêtres des Charons.",
            ["DialogueId"] = 51010314,
            ["GUID"] = "7FB2EFA4",
            ["NextDialogue"] = 51010315,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510103/7FB2EFA4",
            },
        [51010315] = {
            ["Content"] = "但执掌<W>死之权能</>的埃斯刻却成为灾厄的化身，并最终带来叫做“日蚀”的末日。",
            ["ContentFR"] = "Mais Ask, porteur du <W>Pouvoir de la Mort</>, devint l’incarnation du désastre, et finit par précipiter la fin du monde — l’apocalypse que l’on nomme Ragnarök.",
            ["DialogueId"] = 51010315,
            ["GUID"] = "7FB2EFCE",
            ["NextDialogue"] = 51010316,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510103/7FB2EFCE",
            },
        [51010316] = {
            ["Content"] = "在末日中，执掌<H>生之权能</>的母神庇护了她的子民，她散碎的灵魂飘向海洋，最终归于雾海——",
            ["ContentFR"] = "Dans cette heure sombre, Embla, gardienne du <H>Pouvoir de la Vie</>, protégea ses enfants. Son âme se fragmenta et se dispersa dans la mer... jusqu’à revenir à la Mer du Silence.",
            ["DialogueId"] = 51010316,
            ["GUID"] = "7FB2EFF8",
            ["NextDialogue"] = 51010317,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510103/7FB2EFF8",
            },
        [51010317] = {
            ["Content"] = "父神的身躯则化为大地，他高高举起的手臂化为山岳，永远伸向不知何时归来的神明。",
            ["ContentFR"] = "Le corps d’Ask devint la terre, et ses bras levés, les montagnes, tendues vers des dieux qui ne reviendraient jamais.",
            ["DialogueId"] = 51010317,
            ["GUID"] = "7FB2F022",
            ["NextOptions"] = {
                [1] = 51010318,
                },
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510103/7FB2F022",
            },
        [51010318] = {
            ["Content"] = "是个有些伤感的故事。",
            ["ContentFR"] = "<I>C’est... une histoire plutôt triste.</>",
            ["DialogueId"] = 51010318,
            ["GUID"] = "7FB2F04C",
            ["NextDialogue"] = 51010319,
            },
        [51010319] = {
            ["Content"] = "嗯，不过在这些古老的神话里，还有另一个有趣的故事。",
            ["ContentFR"] = "Oui, mais il existe une autre version fascinante.",
            ["DialogueId"] = 51010319,
            ["GUID"] = "7FB2F076",
            ["NextDialogue"] = 51010320,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510103/7FB2F076",
            },
        [51010320] = {
            ["Content"] = "有个故事说，埃斯刻和茵布拉已经在末日后的新世界，以新生的样貌出现。",
            ["ContentFR"] = "Elle raconte qu’Ask et Embla ont été réincarnés dans le nouveau monde, sous de nouvelles formes.",
            ["DialogueId"] = 51010320,
            ["GUID"] = "7FB2F0A0",
            ["NextDialogue"] = 51010321,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510103/7FB2F0A0",
            },
        [51010321] = {
            ["Content"] = "而新生的他们则会带来新的一轮末日，以及再一度毁灭，再一度新生。",
            ["ContentFR"] = "Et que leurs nouveaux avatars provoqueront un autre crépuscule — suivi d’une autre aube.",
            ["DialogueId"] = 51010321,
            ["GUID"] = "7FB2F0CA",
            ["NextDialogue"] = 51010322,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510103/7FB2F0CA",
            },
        [51010322] = {
            ["Content"] = "世界在无尽的循环之中，万物都在新生与死亡间轮回往复。",
            ["ContentFR"] = "Ainsi tourne le monde, dans un cycle sans fin. Vie et mort, encore et encore.",
            ["DialogueId"] = 51010322,
            ["GUID"] = "7FB2F0F4",
            ["NextOptions"] = {
                [1] = 51010323,
                },
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510103/7FB2F0F4",
            },
        [51010323] = {
            ["Content"] = "看来古人也不喜欢悲剧的结局。",
            ["ContentFR"] = "<I>On dirait que même les anciens n’aimaient pas les fins tragiques.</>",
            ["DialogueId"] = 51010323,
            ["GUID"] = "7FB2F11E",
            ["NextDialogue"] = 51010324,
            },
        [51010324] = {
            ["Content"] = "不过……我有些在意的是，为什么这个故事的作者坚信父神和母神得到了新生？或者说，是什么“定义”了茵布拉和埃斯刻的本质呢？",
            ["ContentFR"] = "Et pourtant… je me demande : pourquoi l’auteur croyait-il si fermement à leur renaissance ? Ou plutôt... qu’est-ce qui définit l’essence d’Ask et d’Embla ?",
            ["DialogueId"] = 51010324,
            ["GUID"] = "7FB2F148",
            ["NextDialogue"] = 51010325,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510103/7FB2F148",
            },
        [51010325] = {
            ["Content"] = "是他们的肉体，他们的灵魂？……还是其他？",
            ["ContentFR"] = "Leur corps ? Leur âme ? ... Ou tout autre chose ?",
            ["DialogueId"] = 51010325,
            ["GUID"] = "7FB2F172",
            ["NextDialogue"] = 51010326,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510103/7FB2F172",
            },
        [51010326] = {
            ["Content"] = "假设——我是说假设，一位伟大的魔法师把我们脚下的大地重新变成了埃斯刻的模样——那么这个埃斯刻，和新生的埃斯刻，哪个才是我们的父神大人呢？",
            ["ContentFR"] = "Imaginons... juste pour un instant... qu’un grand mage transforme la terre sous nos pieds pour lui redonner la forme d’Ask. Lequel serait alors le vrai Père ? Celui fait de l’ancien sol, ou celui qui porte son âme ?",
            ["DialogueId"] = 51010326,
            ["GUID"] = "7FB2F19C",
            ["NextOptions"] = {
                [1] = 510103261,
                [2] = 510103262,
                [3] = 510103263,
                [4] = 510103264,
                },
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510103/7FB2F19C",
            },
        [51010327] = {
            ["Content"] = "原来你是这样认为的……谢谢！你的观点启发了我很多。",
            ["ContentFR"] = "Ah... je vois. Merci, ta réponse m’apporte une nouvelle perspective.",
            ["DialogueId"] = 51010327,
            ["GUID"] = "7FB2F1C6",
            ["NextDialogue"] = 51010329,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510103/7FB2F1C6",
            },
        [51010328] = {
            ["Content"] = "很多创作都是从一个无聊的问题开始的，不是吗？",
            ["ContentFR"] = "La plupart des créations commencent par une question absurde, tu ne crois pas ?",
            ["DialogueId"] = 51010328,
            ["GUID"] = "7FB2F1F0",
            ["NextDialogue"] = 51010329,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510103/7FB2F1F0",
            },
        [51010329] = {
            ["Content"] = "谢谢你，如蜡烛上火焰一般的{性别：先生|小姐}。我很喜欢这些神话，现在我已经有了关于它们的歌。",
            ["ContentFR"] = "Merci, {性别:monsieur|mademoiselle}, flamme vive sur une chandelle glacée. J’aime ces mythes... et je crois que j’y ai enfin trouvé ma chanson.",
            ["DialogueId"] = 51010329,
            ["GUID"] = "7FB2F21A",
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510103/7FB2F21A",
            },
        [51010330] = {
            ["Content"] = "是什么让我们得以成为“我们”？",
            ["ContentFR"] = "Qu’est-ce qui fait de nous ce que nous sommes ?",
            ["DialogueId"] = 51010330,
            ["GUID"] = "7FB2F244",
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510103/7FB2F244",
            },
        [51010401] = {
            ["Content"] = "盖雷亚剧院……",
            ["ContentFR"] = "Le Théâtre Galea...",
            ["DialogueId"] = 51010401,
            ["GUID"] = "7FB2FDEA",
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/env/700342/7FB2FDEA",
            },
        [51010402] = {
            ["Content"] = "又见面了，如白沙上石榴石一般的{性别：先生|小姐}。你很喜欢到这儿来呢，我也是。",
            ["ContentFR"] = "Nous revoilà réunis, {性别:monsieur|mademoiselle}, tel un grenat posé sur le sable blanc. Tu sembles apprécier cet endroit... moi aussi.",
            ["DialogueId"] = 51010402,
            ["GUID"] = "7FB2FE14",
            ["NextDialogue"] = 51010403,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510104/7FB2FE14",
            },
        [51010403] = {
            ["Content"] = "你去过盖雷亚剧院吗？",
            ["ContentFR"] = "As-tu déjà mis les pieds à l’intérieur du Théâtre Galea ?",
            ["DialogueId"] = 51010403,
            ["GUID"] = "7FB2FE3E",
            ["NextOptions"] = {
                [1] = 510104031,
                [2] = 510104032,
                [3] = 510104033,
                },
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510104/7FB2FE3E",
            },
        [51010404] = {
            ["Content"] = "噢！真让人羡慕，你一定很富有。",
            ["ContentFR"] = "Oh ! Quelle chance... Tu dois être quelqu’un d’aisé.",
            ["DialogueId"] = 51010404,
            ["GUID"] = "7FB2FE68",
            ["NextDialogue"] = 51010407,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510104/7FB2FE68",
            },
        [51010405] = {
            ["Content"] = "嗯……你也是吗。",
            ["ContentFR"] = "Ah... alors je ne suis pas le seul à être tenu à l’écart de ses portes.",
            ["DialogueId"] = 51010405,
            ["GUID"] = "7FB2FE92",
            ["NextDialogue"] = 51010407,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510104/7FB2FE92",
            },
        [51010406] = {
            ["Content"] = "和军团？不可思议。看来你身上也有很多很多故事。",
            ["ContentFR"] = "Combattu la Légion ? Incroyable... Tu dois avoir des histoires plein les poches, comme autant de partitions oubliées.",
            ["DialogueId"] = 51010406,
            ["GUID"] = "7FB2FEBC",
            ["NextDialogue"] = 51010407,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510104/7FB2FEBC",
            },
        [51010407] = {
            ["Content"] = "我在卢卡去过大大小小的歌剧院，但总被海伯利亚的剧院关在门外。",
            ["ContentFR"] = "J’ai visité toutes sortes d’opéras à Luca, mais ici, à Hyperborea, les théâtres m’en ont toujours refusé l’entrée.",
            ["DialogueId"] = 51010407,
            ["GUID"] = "7FB2FEE6",
            ["NextDialogue"] = 51010408,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510104/7FB2FEE6",
            },
        [51010408] = {
            ["Content"] = "虽然知道卡戎之民在这儿过得不算好，但公共设施收的监护金比我想象中还要昂贵。",
            ["ContentFR"] = "Je savais que les Charons n’avaient pas la vie facile dans cette cité, mais je n’imaginais pas que les taxes de surveillance des lieux publics puissent être aussi exorbitants...",
            ["DialogueId"] = 51010408,
            ["GUID"] = "7FB2FF10",
            ["NextDialogue"] = 51010409,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510104/7FB2FF10",
            },
        [51010409] = {
            ["Content"] = "虽然幸运地赶上这座城市一年一度不需要门票的狂欢日，但又不幸地听说那儿发生了械战……简直糟透了。",
            ["ContentFR"] = "J’ai eu la chance d’arriver à temps pour la Fête de la Chandelle d’Argent, ce jour unique où même les plus pauvres peuvent franchir les portes du théâtre sans payer. Malheureusement... il y a eu une fusillade à l’intérieur. Quelle tragédie.",
            ["DialogueId"] = 51010409,
            ["GUID"] = "7FB2FF3A",
            ["NextDialogue"] = 51010410,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510104/7FB2FF3A",
            },
        [51010410] = {
            ["Content"] = "不过还好——我收集了很多乐谱！书店的价格还算公道，很多人也同意让我用歌声交换乐谱，还有一位神秘的好心朋友教过我一首有名的歌！",
            ["ContentFR"] = "Au moins, j’ai réussi à rassembler beaucoup de partitions ! Les prix des librairies étaient raisonnables, certains ont même accepté d’échanger des pages contre une chanson, et... une personne mystérieuse m’a appris un air très célèbre.",
            ["DialogueId"] = 51010410,
            ["GUID"] = "7FB2FF64",
            ["NextOptions"] = {
                [1] = 510104101,
                },
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510104/7FB2FF64",
            },
        [51010411] = {
            ["Content"] = "前阵子的一个晚上，我靠着一堵墙，就着月光，随意弹唱一首从淘来的乐谱里学的歌。那首歌的旋律并不复杂，很容易便能记住。",
            ["ContentFR"] = "Une nuit, adossé à un mur sous la lumière de la lune, je fredonnais un air appris dans une vieille partition. La mélodie n’était pas compliquée, facile à mémoriser.",
            ["DialogueId"] = 51010411,
            ["GUID"] = "7FB2FF8E",
            ["NextDialogue"] = 51010412,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510104/7FB2FF8E",
            },
        [51010412] = {
            ["Content"] = "但我唱完后，墙的那边突然传来奇怪的敲击声……我能听出来，那些敲击声遵循着某种规律。你知道的，吟游诗人总是对节奏格外敏感。",
            ["ContentFR"] = "Mais lorsque j’ai terminé, j’ai entendu frapper de l’autre côté du mur... Des coups réguliers, délibérés. Tu sais, les ménestrels ont l’oreille fine : ce n’était pas du hasard.",
            ["DialogueId"] = 51010412,
            ["GUID"] = "7FB2FFB8",
            ["NextDialogue"] = 51010413,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510104/7FB2FFB8",
            },
        [51010413] = {
            ["Content"] = "我试着拆解了那些节奏。那是一种很常见的古老密码，用两种不同的敲击声就可以传递讯号。",
            ["ContentFR"] = "J’ai analysé ce rythme. C’était un ancien code, transmis depuis longtemps — deux types de frappes suffisaient à faire passer un message.",
            ["DialogueId"] = 51010413,
            ["GUID"] = "7FB2FFE2",
            ["NextDialogue"] = 51010414,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510104/7FB2FFE2",
            },
        [51010414] = {
            ["Content"] = "墙那边的人告诉我，我唱错了。那是一首歌剧的唱段，在这儿很有名——因为没读过剧本的缘故，我未能准确理解那首歌所传递给观众的情感。",
            ["ContentFR"] = "La personne derrière le mur m’a dit que je m’étais trompé. C’était un air d’opéra très célèbre ici... mais, n’ayant pas lu le livret, j’étais passé à côté de l’émotion que la chanson voulait transmettre.",
            ["DialogueId"] = 51010414,
            ["GUID"] = "7FB3000C",
            ["NextDialogue"] = 51010415,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510104/7FB3000C",
            },
        [51010415] = {
            ["Content"] = "他则是因为某种原因没有办法开口说话和演唱。但他可以用这种讯号教给我如何演唱。",
            ["ContentFR"] = "Cette personne, pour une raison que j’ignore, ne pouvait ni parler ni chanter. Mais elle a utilisé ce langage pour m’apprendre à chanter correctement.",
            ["DialogueId"] = 51010415,
            ["GUID"] = "7FB30036",
            ["NextDialogue"] = 51010416,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510104/7FB30036",
            },
        [51010416] = {
            ["Content"] = "但当我终于在他的教导下学会了那首歌，跑到对面那条街打算当面道谢时，那位好心人已经不在那里了。",
            ["ContentFR"] = "Et quand enfin j’ai maîtrisé l’air, je me suis précipité de l’autre côté pour la remercier... Elle avait déjà disparu.",
            ["DialogueId"] = 51010416,
            ["GUID"] = "7FB30060",
            ["NextOptions"] = {
                [1] = 510104161,
                [2] = 510104162,
                },
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510104/7FB30060",
            },
        [51010417] = {
            ["Content"] = "噢，真是太巧了！",
            ["ContentFR"] = "Oh, quelle coïncidence !",
            ["DialogueId"] = 51010417,
            ["GUID"] = "7FB3008A",
            ["NextDialogue"] = 51010418,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510104/7FB3008A",
            },
        [51010418] = {
            ["Content"] = "如果方便，还请你代我向那位先生或女士致谢——还有祝福！虽然不知道他为什么无法开口，但还是祝愿他早日好起来。我能感受到，他喜欢唱歌，非常喜欢。",
            ["ContentFR"] = "Si tu peux, remercie-la de ma part — et transmets-lui tous mes vœux. J’ignore pourquoi elle ne peut pas chanter, mais je suis certain qu’elle aime la musique... profondément.",
            ["DialogueId"] = 51010418,
            ["GUID"] = "7FB300B4",
            ["NextDialogue"] = 51010419,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510104/7FB300B4",
            },
        [51010419] = {
            ["Content"] = "……好，我会的。",
            ["ContentFR"] = "... D’accord, je le ferai.",
            ["DialogueId"] = 51010419,
            ["GUID"] = "7FB300DE",
            ["NextDialogue"] = 51010421,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "0:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/510104/7FB300DE",
            },
        [51010420] = {
            ["Content"] = "是呢……也藏着很多故事。",
            ["ContentFR"] = "C’est vrai... et d’histoires étranges, aussi.",
            ["DialogueId"] = 51010420,
            ["GUID"] = "7FB30108",
            ["NextDialogue"] = 51010421,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510104/7FB30108",
            },
        [51010421] = {
            ["Content"] = "说来，这里的歌剧和卢卡的很不一样……",
            ["ContentFR"] = "D’ailleurs, l’opéra d’ici est très différent de celui de Luca...",
            ["DialogueId"] = 51010421,
            ["GUID"] = "7FB30132",
            ["NextDialogue"] = 51010422,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510104/7FB30132",
            },
        [51010422] = {
            ["Content"] = "卢卡的歌剧是焰火，伊瑟尔的歌剧是风。",
            ["ContentFR"] = "L’opéra de Luca est un feu d’artifice. Celui d’Aethyrie est le vent.",
            ["DialogueId"] = 51010422,
            ["GUID"] = "7FB3015C",
            ["NextDialogue"] = 51010423,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510104/7FB3015C",
            },
        [51010423] = {
            ["Content"] = "而这里的歌剧是大地。广阔的，苦痛的大地……",
            ["ContentFR"] = "Mais ici... l’opéra est la terre. Large, lourde, empreinte de douleur...",
            ["DialogueId"] = 51010423,
            ["GUID"] = "7FB30186",
            ["NextDialogue"] = 51010424,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510104/7FB30186",
            },
        [51010424] = {
            ["Content"] = "我和朋友就快要离开这儿了，在那之前，我还想为这里写一首歌。",
            ["ContentFR"] = "Mon amie et moi quitterons bientôt cet endroit. Mais avant cela... je veux écrire une dernière chanson pour cette cité.",
            ["DialogueId"] = 51010424,
            ["GUID"] = "7FB301B0",
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510104/7FB301B0",
            },
        [51010425] = {
            ["Content"] = "♪白雪是她的羊水 晨昏线是她的脐带……",
            ["ContentFR"] = "♪ La neige blanche est son eau matricielle, la ligne de l’aube et du crépuscule son cordon ombilical... ♪",
            ["DialogueId"] = 51010425,
            ["GUID"] = "7FB301DA",
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/env/700342/7FB301DA",
            },
        [51010426] = {
            ["Content"] = "♪白雪是她的羊水 晨昏线是她的脐带\
她娩出伟大与苦难 汇入白山下的黑铁摇篮……",
            ["ContentFR"] = "♪ La neige blanche est son eau matricielle, la ligne de l’aube et du crépuscule son cordon ombilical...\
Elle enfante grandeur et souffrance, versant sa progéniture dans un berceau de fer noir, sous la montagne enneigée... ♪",
            ["DialogueId"] = 51010426,
            ["GUID"] = "7FB30204",
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510104/7FB30204",
            },
        [51010501] = {
            ["Content"] = "通行证——喂，说你呢，通行证带了吗？",
            ["ContentFR"] = "Hé, c’est à toi que je parle ! Tu as bien ton permis sur toi ?",
            ["DialogueId"] = 51010501,
            ["GUID"] = "7FB30E52",
            ["NextOptions"] = {
                [1] = 51010502,
                [2] = 51010504,
                [3] = 51010506,
                },
            ["SpeakNpcId"] = 700111,
            },
        [51010502] = {
            ["Content"] = "（声泪俱下地哭诉你是一个遵纪守法的人，只是碰巧又忘带通行证了。）",
            ["ContentFR"] = "<I>Fondre en larmes et expliquer, la voix tremblante, que vous êtes {性别:un citoyen respectueux|une citoyenne respectueuse} des règles... qui a simplement encore oublié son permis.</>",
            ["DialogueId"] = 51010502,
            ["GUID"] = "7FB30E7C",
            ["ImprPlusId"] = 1004,
            ["NextDialogue"] = 51010503,
            },
        [51010503] = {
            ["Content"] = "算了吧，你这话听得我耳朵都快起茧子了。去去，快过去，别搞得那么显眼。",
            ["ContentFR"] = "Oh, épargne-moi ça... J’ai tellement entendu ce discours que j’en ai les oreilles usées. Allez, passe. Et évite de te faire remarquer.",
            ["DialogueId"] = 51010503,
            ["GUID"] = "7FB30EA6",
            ["NextDialogue"] = 51010508,
            ["SpeakNpcId"] = 700111,
            },
        [51010504] = {
            ["Content"] = "（掏出卡米拉帮忙伪造的通行证。）",
            ["ContentFR"] = "<I>Sortir le permis de circulation falsifié par Camilla</>",
            ["DialogueId"] = 51010504,
            ["GUID"] = "7FB30ED0",
            ["ImprPlusId"] = 1003,
            ["NextDialogue"] = 51010505,
            },
        [51010505] = {
            ["Content"] = "通行证核验无误，准许放行。",
            ["ContentFR"] = "Permis de circulation conforme. Tu peux passer.",
            ["DialogueId"] = 51010505,
            ["GUID"] = "7FB30EFA",
            ["NextDialogue"] = 51010508,
            ["SpeakNpcId"] = 700111,
            },
        [51010506] = {
            ["Content"] = "凯文先生，你也不想你在泪湖边上那件事被上级知……",
            ["ContentFR"] = "<I>Kevin, vous ne voudriez tout de même pas que ce qui s’est passé au bord du Lac du Deuil remonte jusqu’à vos supérieurs...</>",
            ["DialogueId"] = 51010506,
            ["GUID"] = "7FB30F24",
            ["ImprPlusId"] = 1005,
            ["NextDialogue"] = 51010507,
            },
        [51010507] = {
            ["Content"] = "别念了！！！让你过还不行吗！！",
            ["ContentFR"] = "Arrête ! Ça va, ça va, je te laisse passer ! Maintenant, file !",
            ["DialogueId"] = 51010507,
            ["GUID"] = "7FB30F4E",
            ["NextDialogue"] = 51010508,
            ["SpeakNpcId"] = 700111,
            },
        [51010508] = {
            ["Content"] = "难得今天没出什么事……",
            ["ContentFR"] = "C’est rare qu’il ne se passe rien aujourd’hui...",
            ["DialogueId"] = 51010508,
            ["GUID"] = "7FB30F78",
            ["NextOptions"] = {
                [1] = 51010509,
                },
            ["RestartTag"] = 51010508,
            ["SpeakNpcId"] = 700111,
            },
        [51010509] = {
            ["Content"] = "（按理说只要有人说出这种话，就会有意外发生。）",
            ["ContentFR"] = "En principe, dès que quelqu’un prononce ce genre de phrase, un imprévu survient.",
            ["DialogueId"] = 51010509,
            ["FailDialogue"] = 51010510,
            ["GUID"] = "7FB30FA2",
            ["ImprCheckId"] = 1074,
            ["NextDialogue"] = 51010511,
            },
        [51010510] = {
            ["Content"] = "（预期的突发情况并未发生，与凯文简单寒暄几句后，大家就各自回到了工作岗位。）",
            ["ContentFR"] = "Contre toute attente, rien ne se produit. Après quelques mots échangés avec Kevin, chacun retourne à son poste.",
            ["DialogueId"] = 51010510,
            ["GUID"] = "7FB30FCC",
            },
        [51010511] = {
            ["Content"] = "（大门旁突然响起急促的电话铃声，凯文如同受惊的兔子一般跳起，急匆匆地接起电话。）",
            ["ContentFR"] = "Soudain, une sonnerie stridente retentit près de la porte. Kevin sursaute comme un lapin effarouché et se précipite pour décrocher.",
            ["DialogueId"] = 51010511,
            ["GUID"] = "7FB30FF6",
            ["NextDialogue"] = 51010512,
            },
        [51010512] = {
            ["Content"] = "好，好……是！我明白了！",
            ["ContentFR"] = "Ouais, ouais... compris ! Bien reçu !",
            ["DialogueId"] = 51010512,
            ["GUID"] = "7FB31020",
            ["NextDialogue"] = 51010513,
            ["SpeakNpcId"] = 700111,
            },
        [51010513] = {
            ["Content"] = "（简短的交谈过后，凯文放下电话，对大门方向比了个通过的手势。）",
            ["ContentFR"] = "Après ce bref appel, Kevin raccroche et te fait signe de passer.",
            ["DialogueId"] = 51010513,
            ["GUID"] = "7FB3104A",
            ["NextDialogue"] = 51010514,
            },
        [51010514] = {
            ["Content"] = "没事的话就赶紧回去吧，我今天又没法安稳下班了。",
            ["ContentFR"] = "Si t’as fini ici, rentre vite. Pour moi, la fin de service tranquille, c’est encore mort.",
            ["DialogueId"] = 51010514,
            ["GUID"] = "7FB31074",
            ["NextDialogue"] = 51010515,
            ["SpeakNpcId"] = 700111,
            },
        [51010515] = {
            ["Content"] = "唉……怎么一遇到你就出意外……",
            ["ContentFR"] = "Sérieux... comment ça se fait qu’il arrive toujours des embrouilles quand tu passes par là... ?",
            ["DialogueId"] = 51010515,
            ["GUID"] = "7FB3109E",
            ["SpeakNpcId"] = 700111,
            },
        [51010516] = {
            ["Content"] = "喂！通行证……啊，是你啊，过去吧过去吧。",
            ["ContentFR"] = "Hé ! Le permis de... ah, c’est toi. Allez, circule.",
            ["DialogueId"] = 51010516,
            ["GUID"] = "7FB310C8",
            ["SpeakNpcId"] = 700111,
            },
        [51010601] = {
            ["Content"] = "好心人，求你帮帮我……给多少都可以……救救身无分文的老人家吧……",
            ["ContentFR"] = "Brave âme... je vous en prie... Donnez ce que vous pouvez... Ayez pitié d’un vieil homme sans le sou...",
            ["DialogueId"] = 51010601,
            ["GUID"] = "7FB31EBA",
            ["NextDialogue"] = 51010602,
            ["SpeakNpcId"] = 700338,
            },
        [51010602] = {
            ["Content"] = "（面前的老人白发苍苍，满面风霜。他呆滞的目光扫过冰湖城来来往往的行人，用嘶哑的声音请求怜悯。）",
            ["ContentFR"] = "Un vieillard aux cheveux blanchis par le temps et au visage marqué par les épreuves se tient devant vous. Son regard vide parcourt la foule de Givrelac, tandis qu’il implore d’une voix rauque.",
            ["DialogueId"] = 51010602,
            ["GUID"] = "7FB31EE4",
            ["NextOptions"] = {
                [1] = 51010603,
                [2] = 51010606,
                [3] = 51010610,
                },
            },
        [51010603] = {
            ["Content"] = "（这个老人真可怜，给他一些钱。）",
            ["ContentFR"] = "<I>Ce vieil homme fait peine à voir. Lui donner un peu d’argent.</>",
            ["DialogueId"] = 51010603,
            ["GUID"] = "7FB31F0E",
            ["ImprPlusId"] = 1004,
            ["NextDialogue"] = 51010604,
            },
        [51010604] = {
            ["Content"] = "唉，谢谢你，年轻人。",
            ["ContentFR"] = "Ah... merci à vous, jeune âme.",
            ["DialogueId"] = 51010604,
            ["GUID"] = "7FB31F38",
            ["NextDialogue"] = 51010605,
            ["SpeakNpcId"] = 700338,
            },
        [51010605] = {
            ["Content"] = "也不知道我这老头子今天睡着明天还能不能醒过来，但至少，今天能吃顿饱饭了。",
            ["ContentFR"] = "À mon âge, je ne sais jamais si je me réveillerai demain... mais au moins, aujourd’hui, je mangerai à ma faim.",
            ["DialogueId"] = 51010605,
            ["GUID"] = "7FB31F62",
            ["SpeakNpcId"] = 700338,
            },
        [51010606] = {
            ["Content"] = "（从老人的破碗里拿走几枚硬币。）",
            ["ContentFR"] = "<I>Prendre quelques pièces dans le bol ébréché du vieil homme</>",
            ["DialogueId"] = 51010606,
            ["GUID"] = "7FB31F8C",
            ["ImprPlusId"] = 1005,
            ["NextDialogue"] = 51010607,
            },
        [51010607] = {
            ["Content"] = "你……唉。",
            ["ContentFR"] = "Vous... hm.",
            ["DialogueId"] = 51010607,
            ["GUID"] = "7FB31FB6",
            ["NextDialogue"] = 51010608,
            ["SpeakNpcId"] = 700338,
            },
        [51010608] = {
            ["Content"] = "{性别：小伙子|小姑娘}你这眼睛，莫非也是让他们打的？",
            ["ContentFR"] = "{性别:Jeune homme|Jeune femme}, ce regard... ils vous ont fait ça aussi ?",
            ["DialogueId"] = 51010608,
            ["GUID"] = "7FB31FE0",
            ["NextDialogue"] = 51010609,
            ["SpeakNpcId"] = 700338,
            },
        [51010609] = {
            ["Content"] = "算了，拿去吧，拿去吧，你可能比我更需要这些钱。",
            ["ContentFR"] = "Bah... prenez-les. Prenez-les donc. Vous en avez sans doute plus besoin que moi.",
            ["DialogueId"] = 51010609,
            ["GUID"] = "7FB3200A",
            ["SpeakNpcId"] = 700338,
            },
        [51010610] = {
            ["Content"] = "身体健全的你应该去工作。",
            ["ContentFR"] = "<I>Vous êtes valide. Vous devriez travailler.</>",
            ["DialogueId"] = 51010610,
            ["GUID"] = "7FB32034",
            ["ImprPlusId"] = 1001,
            ["NextDialogue"] = 51010611,
            },
        [51010611] = {
            ["Content"] = "工作……哈。谁还没有过一份体面的工作……",
            ["ContentFR"] = "Travailler... ha. Qui n’a jamais eu un emploi honorable, autrefois...",
            ["DialogueId"] = 51010611,
            ["GUID"] = "7FB3205E",
            ["NextDialogue"] = 51010612,
            ["SpeakNpcId"] = 700338,
            },
        [51010612] = {
            ["Content"] = "可那又有什么用？有时候啊，他们夺走你的工作，就和夺走这破碗中的硬币一样简单。",
            ["ContentFR"] = "Mais à quoi bon ? Parfois, ils vous arrachent votre travail aussi facilement que les pièces dans ce bol.",
            ["DialogueId"] = 51010612,
            ["GUID"] = "7FB32088",
            ["NextDialogue"] = 51010613,
            ["SpeakNpcId"] = 700338,
            },
        [51010613] = {
            ["Content"] = "在漂亮屋子里乞讨，在大街上乞讨，都一样的。",
            ["ContentFR"] = "Mendier dans une belle maison ou dans la rue... quelle différence, au fond ?",
            ["DialogueId"] = 51010613,
            ["GUID"] = "7FB320B2",
            ["SpeakNpcId"] = 700338,
            },
        [51010614] = {
            ["Content"] = "好好活着吧……唉，这世道，越是好人越难立足啊。",
            ["ContentFR"] = "Tâchez de survivre... En ces temps troublés, ce sont toujours les braves gens qui ont le plus de mal à tenir debout.",
            ["DialogueId"] = 51010614,
            ["GUID"] = "7FB320DC",
            ["SpeakNpcId"] = 700338,
            },
        [51010701] = {
            ["Content"] = "末日将至啊……末日将至……",
            ["ContentFR"] = "La fin approche... la fin approche...",
            ["DialogueId"] = 51010701,
            ["GUID"] = "7FB32F22",
            ["NextDialogue"] = 51010702,
            ["SpeakNpcId"] = 700337,
            },
        [51010702] = {
            ["Content"] = "（眼前的皎皎摇头晃脑地趴在桌子上，昏昏欲睡。）",
            ["ContentFR"] = "La Luno devant vous est affalée sur la table, la tête ballante, au bord du sommeil.",
            ["DialogueId"] = 51010702,
            ["GUID"] = "7FB32F4C",
            ["NextOptions"] = {
                [1] = 51010703,
                [2] = 51010704,
                },
            },
        [51010703] = {
            ["Content"] = "把她叫醒。",
            ["ContentFR"] = "<I>Réveiller</>",
            ["DialogueId"] = 51010703,
            ["GUID"] = "7FB32F76",
            ["NextDialogue"] = 51010705,
            },
        [51010704] = {
            ["Content"] = "让她继续睡。",
            ["ContentFR"] = "<I>Laisser dormir</>",
            ["DialogueId"] = 51010704,
            ["GUID"] = "7FB32FA0",
            ["Scripts"] = "SetOutport{FinishType{\"Fail\"}}",
            },
        [51010705] = {
            ["Content"] = "（悲观皎皎猛地抬起头，眼神闪闪发光，声音如洪水一般宣泄出来。）",
            ["ContentFR"] = "Elle redresse brusquement la tête. Ses yeux brillent d’un éclat inquiétant, et les mots jaillissent comme une crue incontrôlable.",
            ["DialogueId"] = 51010705,
            ["GUID"] = "7FB32FCA",
            ["NextDialogue"] = 51010706,
            },
        [51010706] = {
            ["Content"] = "末日……末日要来了，没人能够逃掉。",
            ["ContentFR"] = "La fin... la fin arrive ! Personne n’y échappera !",
            ["DialogueId"] = 51010706,
            ["GUID"] = "7FB32FF4",
            ["NextDialogue"] = 51010707,
            ["SpeakNpcId"] = 700337,
            },
        [51010707] = {
            ["Content"] = "花店里的花朵不再鲜艳，褪色成纯白的石楠……",
            ["ContentFR"] = "Les fleurs du fleuriste perdent leurs couleurs, devenant de la bruyère blanche comme la pierre...",
            ["DialogueId"] = 51010707,
            ["GUID"] = "7FB3301E",
            ["NextDialogue"] = 51010708,
            ["SpeakNpcId"] = 700337,
            },
        [51010708] = {
            ["Content"] = "广场上的猫猫不再毛绒绒，而是像石膏雕像一样又硬又滑……",
            ["ContentFR"] = "Les chats de la place ne sont plus doux ni moelleux... Ils sont durs et lisses, comme des statues de plâtre...",
            ["DialogueId"] = 51010708,
            ["GUID"] = "7FB33048",
            ["NextDialogue"] = 51010709,
            ["SpeakNpcId"] = 700337,
            },
        [51010709] = {
            ["Content"] = "面包房再也做不出蓬松的面包，无论怎么烘焙都会变成黑漆漆的烂泥……",
            ["ContentFR"] = "La boulangerie ne sait plus faire de pain gonflé. Peu importe la cuisson, tout devient une boue noire et informe...",
            ["DialogueId"] = 51010709,
            ["GUID"] = "7FB33072",
            ["NextDialogue"] = 51010710,
            ["SpeakNpcId"] = 700337,
            },
        [51010710] = {
            ["Content"] = "我最爱吃的冰棍也不再冰冰凉凉，放到嘴里只会黏糊糊粘住嗓子……",
            ["ContentFR"] = "Même mes glaces préférées ne sont plus froides... Elles collent à la gorge, gluantes...",
            ["DialogueId"] = 51010710,
            ["GUID"] = "7FB3309C",
            ["NextDialogue"] = 51010711,
            ["SpeakNpcId"] = 700337,
            },
        [51010711] = {
            ["Content"] = "大家也开始慢慢变得和皎皎一样高，和皎皎一样白……",
            ["ContentFR"] = "Et puis... tout le monde devient peu à peu aussi grand que moi... aussi pâle que moi...",
            ["DialogueId"] = 51010711,
            ["GUID"] = "7FB330C6",
            ["NextDialogue"] = 51010712,
            ["SpeakNpcId"] = 700337,
            },
        [51010712] = {
            ["Content"] = "到最后……",
            ["ContentFR"] = "À la fin...",
            ["DialogueId"] = 51010712,
            ["GUID"] = "7FB330F0",
            ["NextDialogue"] = 51010713,
            ["SpeakNpcId"] = 700337,
            },
        [51010713] = {
            ["Content"] = "花店的阿姨，面包房的大婶，卖冰棍的爷爷……大家都会变成皎皎！",
            ["ContentFR"] = "La fleuriste, la boulangère, le grand-père aux glaces... Tout le monde deviendra une Luno !",
            ["DialogueId"] = 51010713,
            ["GUID"] = "7FB3311A",
            ["NextOptions"] = {
                [1] = 51010714,
                [2] = 51010715,
                },
            ["SpeakNpcId"] = 700337,
            },
        [51010714] = {
            ["Content"] = "皎皎好，我也想变成皎皎。",
            ["ContentFR"] = "<I>Les Lunariens, c’est formidable. Moi aussi, je veux devenir une Luno.</>",
            ["DialogueId"] = 51010714,
            ["GUID"] = "7FB33144",
            ["ImprPlusId"] = 1005,
            ["NextDialogue"] = 51010716,
            },
        [51010715] = {
            ["Content"] = "好可怕的末日……",
            ["ContentFR"] = "<I>Quelle fin terrifiante...</>",
            ["DialogueId"] = 51010715,
            ["GUID"] = "7FB3316E",
            ["ImprPlusId"] = 1004,
            ["NextDialogue"] = 51010716,
            },
        [51010716] = {
            ["Content"] = "你……你的头发、你的衣服、你的身高……你已经开始变成皎皎了吗！",
            ["ContentFR"] = "Vos cheveux... vos vêtements... votre taille... Vous commencez déjà à devenir une Luno ?!",
            ["DialogueId"] = 51010716,
            ["GUID"] = "7FB33198",
            ["NextDialogue"] = 51010717,
            ["SpeakNpcId"] = 700337,
            },
        [51010717] = {
            ["Content"] = "末日……末日果然来了，一切都完了。",
            ["ContentFR"] = "La fin... La fin est vraiment là. Tout est terminé.",
            ["DialogueId"] = 51010717,
            ["GUID"] = "7FB331C2",
            ["NextDialogue"] = 51010718,
            ["SpeakNpcId"] = 700337,
            },
        [51010718] = {
            ["Content"] = "（悲观皎皎无力地垂下双手，看向你的视线透过你的身躯，透过层叠的建筑，失神地望向昏暗的天空。仿佛她口中的末日马上就要变为现实。）",
            ["ContentFR"] = "Les bras de Luno, la pessimiste, retombent mollement. Son regard vous traverse, dépasse les bâtiments entassés, et se perd dans le ciel sombre — comme si l’apocalypse qu’elle annonçait allait s’abattre d’un instant à l’autre.",
            ["DialogueId"] = 51010718,
            ["GUID"] = "7FB331EC",
            ["NextDialogue"] = 51010719,
            },
        [51010719] = {
            ["Content"] = "（几分钟过去，理所当然的什么都未发生，悲观皎皎的视线再也没有落到你的身上，不断呢喃着末日将至。）",
            ["ContentFR"] = "Les minutes passent. Comme on pouvait s’y attendre, rien ne se produit. Luno, la pessimiste, ne vous regarde plus, murmurant sans fin que la fin est proche.",
            ["DialogueId"] = 51010719,
            ["GUID"] = "7FB33216",
            ["NextDialogue"] = 51010720,
            },
        [51010720] = {
            ["Content"] = "（你有些好奇变成皎皎会是怎么样的感觉，但现在你能做的，也只有转身离开了。）",
            ["ContentFR"] = "Vous vous surprenez à imaginer ce que cela ferait de devenir une Luno. Mais pour l’instant, vous n’avez d’autre choix que de tourner les talons.",
            ["DialogueId"] = 51010720,
            ["GUID"] = "7FB33240",
            },
        [51010721] = {
            ["Content"] = "末日，末日已经开始了……",
            ["ContentFR"] = "La fin... elle a déjà commencé...",
            ["DialogueId"] = 51010721,
            ["GUID"] = "7FB3326A",
            ["SpeakNpcId"] = 700337,
            },
        [51010801] = {
            ["Content"] = "您好，这朵花与您今天的装扮很相称……如果那孩子还在的话，一定也会这么说吧。",
            ["ContentFR"] = "Bonjour. Cette fleur s’accorde parfaitement avec votre tenue... Si elle était encore là, elle aurait dit la même chose.",
            ["DialogueId"] = 51010801,
            ["GUID"] = "7FB33F8A",
            ["NextOptions"] = {
                [1] = 51010802,
                [2] = 51010803,
                },
            ["SpeakNpcId"] = 700203,
            },
        [51010802] = {
            ["Content"] = "你认识我？",
            ["ContentFR"] = "Vous me connaissez ?",
            ["DialogueId"] = 51010802,
            ["GUID"] = "7FB33FB4",
            ["NextDialogue"] = 51010804,
            },
        [51010803] = {
            ["Content"] = "“那孩子”难道指的是……",
            ["ContentFR"] = "« Elle »... vous parlez de... ?",
            ["DialogueId"] = 51010803,
            ["GUID"] = "7FB33FDE",
            ["NextDialogue"] = 51010804,
            },
        [51010804] = {
            ["Content"] = "我的女儿。她的名字是赛琪。",
            ["ContentFR"] = "Ma fille. Elle s’appelait Psyche.",
            ["DialogueId"] = 51010804,
            ["GUID"] = "7FB34008",
            ["NextDialogue"] = 51010805,
            ["SpeakNpcId"] = 700203,
            },
        [51010805] = {
            ["Content"] = "她曾在给我的信里提到过“一个新交的朋友”。您的模样与那封书信中的描述很相似……如果我认错了人，还请您谅解。",
            ["ContentFR"] = "Dans ses lettres, elle évoquait souvent « {性别:un nouvel ami|une nouvelle amie} ». Votre apparence correspond beaucoup à ce qu’elle décrivait... Si je me trompe, je vous prie de bien vouloir m’en excuser.",
            ["DialogueId"] = 51010805,
            ["GUID"] = "7FB34032",
            ["NextOptions"] = {
                [1] = 51010806,
                [2] = 51010807,
                },
            ["SpeakNpcId"] = 700203,
            ["bForbidSkipOptions"] = true,
            },
        [51010806] = {
            ["Content"] = "……她是怎么说我的？",
            ["ContentFR"] = "<I>... Que disait-elle de moi ?</>",
            ["DialogueId"] = 51010806,
            ["GUID"] = "7FB3405C",
            ["NextDialogue"] = 51010809,
            },
        [51010807] = {
            ["Content"] = "……是的，你认错人了。（离开）",
            ["ContentFR"] = "<I>... Vous vous trompez de personne.</>",
            ["DialogueId"] = 51010807,
            ["GUID"] = "7FB34086",
            ["NextDialogue"] = 51010808,
            },
        [51010808] = {
            ["Content"] = "（你像逃跑一样转身离开。那是你们心中共同的隐痛，你不愿再触及它。）",
            ["ContentFR"] = "Vous vous détournez presque en fuyant. C’est une douleur que vous partagez en silence, et que vous ne souhaitez pas raviver.",
            ["DialogueId"] = 51010808,
            ["GUID"] = "7FB340B0",
            ["Scripts"] = "SetOutport{FinishType{\"Fail\"}}",
            },
        [51010809] = {
            ["Content"] = "你很聪明，又很勇敢。听说你到冰湖城的第一天就深入格雷姆废矿，在她见过的所有同龄人里，你是最强大的一个。更重要的是……",
            ["ContentFR"] = "Elle disait que vous étiez {性别:intelligent et courageux|intelligente et courageuse}. Que dès votre premier jour à Givrelac, vous aviez osé vous enfoncer dans la Fosse de Glevum. Parmi tous ceux de son âge qu’elle avait rencontrés, vous étiez {性别:le plus fort|la plus forte}. Et plus encore...",
            ["DialogueId"] = 51010809,
            ["GUID"] = "7FB340DA",
            ["NextDialogue"] = 51010810,
            ["SpeakNpcId"] = 700203,
            },
        [51010810] = {
            ["Content"] = "“{性别：他|她}和冰湖城的大多数人不一样，{性别：他|她}还有着我们早就丢失了的东西——对正义和自由的渴望。”",
            ["ContentFR"] = "« {性别:Il|Elle} n’est pas comme la plupart des habitants de Givrelac. {性别:Il|Elle} possède encore ce que nous avons perdu depuis longtemps — le désir de justice et de liberté. »",
            ["DialogueId"] = 51010810,
            ["GUID"] = "7FB34104",
            ["NextDialogue"] = 51010811,
            ["SpeakNpcId"] = 700203,
            },
        [51010811] = {
            ["Content"] = "“从{性别：他|她}身上，我看到了另一种不一样的生活。”",
            ["ContentFR"] = "« À ses côtés, j’ai entrevu une autre manière de vivre. »",
            ["DialogueId"] = 51010811,
            ["GUID"] = "7FB3412E",
            ["NextDialogue"] = 51010812,
            ["SpeakNpcId"] = 700203,
            },
        [51010812] = {
            ["Content"] = "这是她信里写的。",
            ["ContentFR"] = "C’est ce qu’elle a écrit.",
            ["DialogueId"] = 51010812,
            ["GUID"] = "7FB34158",
            ["NextDialogue"] = 51010813,
            ["SpeakNpcId"] = 700203,
            },
        [51010813] = {
            ["Content"] = "（女人熟练地复述着——显然，那封信她不知看了多少遍。）",
            ["ContentFR"] = "La femme récite ces mots avec une aisance troublante — il est évident qu’elle a relu cette lettre d’innombrables fois.",
            ["DialogueId"] = 51010813,
            ["GUID"] = "7FB34182",
            ["NextDialogue"] = 51010814,
            },
        [51010814] = {
            ["Content"] = "对不起，我没能……",
            ["ContentFR"] = "Je suis {性别:désolé|désolée}... je n’ai pas pu...",
            ["DialogueId"] = 51010814,
            ["GUID"] = "7FB341AC",
            ["NextDialogue"] = 51010815,
            ["SpeakNpcId"] = 100001,
            },
        [51010815] = {
            ["Content"] = "不要说抱歉，孩子。我看得到，有你最后的陪伴，她是快乐的。这就够了。是我们应该感谢你。",
            ["ContentFR"] = "Ne vous excusez pas, mon enfant. Je le vois bien : avec vous à ses côtés jusqu’au bout, elle était heureuse. Cela suffit amplement. C’est nous qui devrions vous remercier.",
            ["DialogueId"] = 51010815,
            ["GUID"] = "7FB341D6",
            ["NextDialogue"] = 51010816,
            ["SpeakNpcId"] = 700203,
            },
        [51010816] = {
            ["Content"] = "请带上这束花吧，我们的祝福与你同在。",
            ["ContentFR"] = "Veuillez accepter ce bouquet. Que notre bénédiction vous accompagne.",
            ["DialogueId"] = 51010816,
            ["GUID"] = "7FB34200",
            ["SpeakNpcId"] = 700203,
            },
        [51010817] = {
            ["Content"] = "一路顺利，我们的祝福与你同在。",
            ["ContentFR"] = "Que votre route soit sûre. Notre bénédiction vous accompagne.",
            ["DialogueId"] = 51010817,
            ["GUID"] = "7FB3422A",
            ["SpeakNpcId"] = 700203,
            },
        [51010901] = {
            ["Content"] = "自家庄园的好果子，别的地方没有这培育技术！",
            ["ContentFR"] = "Les meilleurs fruits de notre domaine ! Nulle part ailleurs vous ne trouverez un savoir-faire aussi raffiné !",
            ["DialogueId"] = 51010901,
            ["GUID"] = "7FB34FF2",
            ["NextDialogue"] = 51010902,
            ["SpeakNpcId"] = 700009,
            },
        [51010902] = {
            ["Content"] = "您来点果子吗？一等一的肥料加上好种子，自家温室培养出来的，个个营养丰富口感好！",
            ["ContentFR"] = "Cela vous dirait quelques fruits ? Des graines de premier choix, un engrais de qualité, cultivés sous serre chez nous. Ils sont tous riches et savoureux !",
            ["DialogueId"] = 51010902,
            ["GUID"] = "7FB3501C",
            ["NextOptions"] = {
                [1] = 51010903,
                [2] = 51010905,
                },
            ["SpeakNpcId"] = 700009,
            },
        [51010903] = {
            ["Content"] = "温室培育的果子应该很贵吧。",
            ["ContentFR"] = "<I>Les fruits cultivés sous serre doivent coûter cher.</>",
            ["DialogueId"] = 51010903,
            ["GUID"] = "7FB35046",
            ["ImprPlusId"] = 1001,
            ["NextDialogue"] = 51010904,
            },
        [51010904] = {
            ["Content"] = "果子不同价格也不同，能吃到好果子本身就很难了，我之前在战场上根本吃不到。",
            ["ContentFR"] = "Les prix varient selon les fruits. Mais pouvoir manger quelque chose de vraiment bon, c’est déjà rare. Sur le champ de bataille, je n’avais jamais accès à ce genre de choses.",
            ["DialogueId"] = 51010904,
            ["GUID"] = "7FB35070",
            ["NextOptions"] = {
                [1] = 51010907,
                },
            ["SpeakNpcId"] = 700009,
            },
        [51010905] = {
            ["Content"] = "掌握温室培育的技术应该很难。",
            ["ContentFR"] = "<I>Maîtriser la culture sous serre doit être compliqué.</>",
            ["DialogueId"] = 51010905,
            ["GUID"] = "7FB3509A",
            ["ImprPlusId"] = 1003,
            ["NextDialogue"] = 51010906,
            },
        [51010906] = {
            ["Content"] = "技术是我爷爷传下来的，我一开始还不想继承，后来退伍了才接受。",
            ["ContentFR"] = "Cette technique vient de mon grand-père. Au début, je ne voulais pas en hériter... Puis, après avoir quitté l’armée, j’ai fini par accepter.",
            ["DialogueId"] = 51010906,
            ["GUID"] = "7FB350C4",
            ["NextOptions"] = {
                [1] = 51010907,
                },
            ["SpeakNpcId"] = 700009,
            },
        [51010907] = {
            ["Content"] = "您当过兵？",
            ["ContentFR"] = "<I>Vous étiez soldat ?</>",
            ["DialogueId"] = 51010907,
            ["GUID"] = "7FB350EE",
            ["NextDialogue"] = 51010908,
            },
        [51010908] = {
            ["Content"] = "是啊，我当初可是优秀士兵，一个顶三个！",
            ["ContentFR"] = "Oui ! À l’époque, j’étais un excellent soldat. Un seul homme en valait trois !",
            ["DialogueId"] = 51010908,
            ["GUID"] = "7FB35118",
            ["NextDialogue"] = 51010909,
            ["SpeakNpcId"] = 700009,
            },
        [51010909] = {
            ["Content"] = "后来受伤了，越来越力不从心，就提前退伍了。",
            ["ContentFR"] = "Mais après une blessure, j’ai commencé à manquer de forces... Alors j’ai été réformé plus tôt que prévu.",
            ["DialogueId"] = 51010909,
            ["GUID"] = "7FB35142",
            ["NextDialogue"] = 51010910,
            ["SpeakNpcId"] = 700009,
            },
        [51010910] = {
            ["Content"] = "现在才明白平平淡淡才是真，踏踏实实培育果子，再遇到个好姑娘，一辈子挺好的了。",
            ["ContentFR"] = "Aujourd’hui, je comprends que la simplicité a du bon. Cultiver de bons fruits, mener une vie honnête... Et rencontrer une brave fille. Une vie entière comme ça, ce serait déjà très bien.",
            ["DialogueId"] = 51010910,
            ["GUID"] = "7FB3516C",
            ["NextOptions"] = {
                [1] = 51010911,
                },
            ["RestartTag"] = 51010910,
            ["SpeakNpcId"] = 700009,
            },
        [51010911] = {
            ["Content"] = "有心仪的人选吗？",
            ["ContentFR"] = "<I>Vous avez quelqu’un en tête ?</>",
            ["DialogueId"] = 51010911,
            ["FailDialogue"] = 51010912,
            ["GUID"] = "7FB35196",
            ["ImprCheckId"] = 1075,
            ["NextDialogue"] = 51010914,
            },
        [51010912] = {
            ["Content"] = "（男人一时语塞，尴尬地张了张嘴，艰难地挤出一句话。）",
            ["ContentFR"] = "L’homme reste un instant sans voix. Il entrouvre maladroitement la bouche, puis finit par articuler difficilement.",
            ["DialogueId"] = 51010912,
            ["GUID"] = "7FB351C0",
            ["NextDialogue"] = 51010913,
            },
        [51010913] = {
            ["Content"] = "您，您别问了，您还是多看看果子，我帮您挑挑。",
            ["ContentFR"] = "Euh... n’insistez pas. Regardez donc les fruits, plutôt. Je vais vous aider à choisir.",
            ["DialogueId"] = 51010913,
            ["GUID"] = "7FB351EA",
            ["SpeakNpcId"] = 700009,
            },
        [51010914] = {
            ["Content"] = "（男人的眼睛闪过一丝亮光，不自觉地微笑了起来，但瞬间又陷入了困惑。）",
            ["ContentFR"] = "Une lueur traverse son regard. Un sourire inconscient se dessine, avant de laisser place à la confusion.",
            ["DialogueId"] = 51010914,
            ["GUID"] = "7FB35214",
            ["NextDialogue"] = 51010915,
            },
        [51010915] = {
            ["Content"] = "……虽然有，但我只见过她的背影。",
            ["ContentFR"] = "... Il y a bien quelqu’un. Mais je n’ai vu que son dos.",
            ["DialogueId"] = 51010915,
            ["GUID"] = "7FB3523E",
            ["NextDialogue"] = 51010916,
            ["SpeakNpcId"] = 700009,
            },
        [51010916] = {
            ["Content"] = "这么久了，我还没和她说过话呢，唉。",
            ["ContentFR"] = "Ça fait longtemps maintenant, et je ne lui ai jamais adressé la parole... hélas.",
            ["DialogueId"] = 51010916,
            ["GUID"] = "7FB35268",
            ["NextDialogue"] = 51010917,
            ["SpeakNpcId"] = 700009,
            },
        [51010917] = {
            ["Content"] = "贸然搭话又怕吓到心爱的姑娘，我只好先让空空皎皎帮我传下话。唉，可我真是太倒霉了，每次空空皎皎去传话的时候，都赶上她不在家。",
            ["ContentFR"] = "Si je l’aborde trop brusquement, j’ai peur de l’effrayer. Alors j’ai demandé à Luno, l’étourdie, de lui transmettre un message. Mais j’ai une chance terrible : à chaque fois qu’elle y va, la jeune femme est absente.",
            ["DialogueId"] = 51010917,
            ["GUID"] = "7FB35292",
            ["NextOptions"] = {
                [1] = 51010918,
                },
            ["SpeakNpcId"] = 700009,
            },
        [51010918] = {
            ["Content"] = "你看上去不拘小节，却很懂得尊重对方。",
            ["ContentFR"] = "<I>Vous avez l’air simple, mais très respectueux.</>",
            ["DialogueId"] = 51010918,
            ["GUID"] = "7FB352BC",
            ["ImprPlusId"] = 1002,
            ["NextDialogue"] = 51010919,
            },
        [51010919] = {
            ["Content"] = "您夸得我都不好意思了，哈哈。",
            ["ContentFR"] = "Vous allez me faire rougir, haha.",
            ["DialogueId"] = 51010919,
            ["GUID"] = "7FB352E6",
            ["NextDialogue"] = 51010920,
            ["SpeakNpcId"] = 700009,
            },
        [51010920] = {
            ["Content"] = "对了，我看您像是个文化人，可不可以帮我这个粗人润色一下句子，我怎么写怎么别扭。",
            ["ContentFR"] = "Dites... vous avez l’air cultivé. Pourriez-vous aider un rustre comme moi à améliorer quelques phrases ? Quoi que j’écrive, ça sonne toujours de travers.",
            ["DialogueId"] = 51010920,
            ["GUID"] = "7FB35310",
            ["NextOptions"] = {
                [1] = 51010921,
                },
            ["SpeakNpcId"] = 700009,
            },
        [51010921] = {
            ["Content"] = "我现在正好有时间，你读来听听？",
            ["ContentFR"] = "<I>J’ai un peu de temps. Lisez-moi ça.</>",
            ["DialogueId"] = 51010921,
            ["GUID"] = "7FB3533A",
            ["NextDialogue"] = 51010922,
            },
        [51010922] = {
            ["Content"] = "咳咳。",
            ["ContentFR"] = "<I>Hum, hum.</>",
            ["DialogueId"] = 51010922,
            ["GUID"] = "7FB35364",
            ["NextDialogue"] = 51010923,
            ["SpeakNpcId"] = 700009,
            },
        [51010923] = {
            ["Content"] = "“我对你的感情，一直升温，比冬天的温室，还要温暖。”",
            ["ContentFR"] = "« Les sentiments que j’éprouve pour toi ne cessent de s’intensifier, plus chaleureux encore qu’une serre en plein hiver. »",
            ["DialogueId"] = 51010923,
            ["GUID"] = "7FB3538E",
            ["NextOptions"] = {
                [1] = 51010924,
                },
            ["SpeakNpcId"] = 700009,
            },
        [51010924] = {
            ["Content"] = "……",
            ["ContentFR"] = "...",
            ["DialogueId"] = 51010924,
            ["GUID"] = "7FB353B8",
            ["NextDialogue"] = 51010925,
            },
        [51010925] = {
            ["Content"] = "“你什么时候能发现，我的心像果子，就等着你来采摘。”",
            ["ContentFR"] = "« Quand remarqueras-tu que mon cœur est comme un fruit mûr, attendant simplement que tu le cueilles ? »",
            ["DialogueId"] = 51010925,
            ["GUID"] = "7FB353E2",
            ["NextDialogue"] = 51010926,
            ["SpeakNpcId"] = 700009,
            },
        [51010926] = {
            ["Content"] = "“接受我吧，我的姑娘！不要让我的爱像烂果子一样，烂在地里。”",
            ["ContentFR"] = "« Accepte-moi, ma chère ! Ne laisse pas mon amour pourrir sur le sol comme un fruit gâté. »",
            ["DialogueId"] = 51010926,
            ["GUID"] = "7FB3540C",
            ["NextDialogue"] = 51010927,
            ["SpeakNpcId"] = 700009,
            },
        [51010927] = {
            ["Content"] = "……怎么样，有可以润色的地方吗？",
            ["ContentFR"] = "... Alors ? Y a-t-il quelque chose à retoucher ?",
            ["DialogueId"] = 51010927,
            ["GUID"] = "7FB35436",
            ["NextOptions"] = {
                [1] = 51010928,
                },
            ["SpeakNpcId"] = 700009,
            },
        [51010928] = {
            ["Content"] = "……很有个人特色，也很真挚，我觉得保持现状就好。",
            ["ContentFR"] = "<I>C’est très personnel, et très sincère. Je pense qu’il vaut mieux ne rien changer.</>",
            ["DialogueId"] = 51010928,
            ["GUID"] = "7FB35460",
            ["NextDialogue"] = 51010929,
            },
        [51010929] = {
            ["Content"] = "真的吗？那太好了，借您吉言。",
            ["ContentFR"] = "Vraiment ? Alors c’est parfait ! Je prends ça comme un bon présage.",
            ["DialogueId"] = 51010929,
            ["GUID"] = "7FB3548A",
            ["NextDialogue"] = 51010930,
            ["SpeakNpcId"] = 700009,
            },
        [51010930] = {
            ["Content"] = "如果这份感情有结果了，您来买果子我给您最大优惠，哈哈。",
            ["ContentFR"] = "Si cette histoire aboutit, quand vous viendrez acheter des fruits, je vous ferai la plus grosse remise possible, haha !",
            ["DialogueId"] = 51010930,
            ["GUID"] = "7FB354B4",
            ["SpeakNpcId"] = 700009,
            },
        [51010931] = {
            ["Content"] = "我的爱对方还没回应，唉，最大优惠您要等等了。",
            ["ContentFR"] = "Elle n’a toujours pas répondu... Pour la grosse remise, il faudra encore patienter un peu.",
            ["DialogueId"] = 51010931,
            ["GUID"] = "7FB354DE",
            ["SpeakNpcId"] = 700009,
            },
        [51011001] = {
            ["Content"] = "请留步，很抱歉突然叫住您。",
            ["ContentFR"] = "Veuillez m’excuser. Pardonnez-moi de vous interrompre ainsi.",
            ["DialogueId"] = 51011001,
            ["GUID"] = "7FB3605A",
            ["NextDialogue"] = 51011002,
            ["SpeakNpcId"] = 700008,
            },
        [51011002] = {
            ["Content"] = "但若是我家衣服能拥有自己的思想，一定很盼望能够被像您一样俊美的人穿在身上。",
            ["ContentFR"] = "Mais si mes vêtements pouvaient penser, ils rêveraient tous d’être portés par quelqu’un d’aussi {性别:élégant|élégante} que vous.",
            ["DialogueId"] = 51011002,
            ["GUID"] = "7FB36084",
            ["NextDialogue"] = 51011003,
            ["SpeakNpcId"] = 700008,
            },
        [51011003] = {
            ["Content"] = "如果就这么错过了您，它们一定会伤心的。",
            ["ContentFR"] = "Les laisser passer à côté de vous les attristerait profondément.",
            ["DialogueId"] = 51011003,
            ["GUID"] = "7FB360AE",
            ["NextDialogue"] = 51011004,
            ["SpeakNpcId"] = 700008,
            },
        [51011004] = {
            ["Content"] = "（眼前的男人有着贵族的气质，举手投足之间尽显优雅，身躯瘦弱却又挺拔，富有亲和力的笑眼让人如沐春风。）",
            ["ContentFR"] = "L’homme devant vous dégage une noblesse naturelle. Sa silhouette est fine mais droite, ses gestes gracieux, et son regard souriant inspire immédiatement la confiance.",
            ["DialogueId"] = 51011004,
            ["GUID"] = "7FB360D8",
            ["NextOptions"] = {
                [1] = 51011005,
                [2] = 51011006,
                },
            },
        [51011005] = {
            ["Content"] = "你这里的衣服是我能买得起的吗？",
            ["ContentFR"] = "<I>Les vêtements ici sont-ils à ma portée ?</>",
            ["DialogueId"] = 51011005,
            ["GUID"] = "7FB36102",
            ["ImprPlusId"] = 1001,
            ["NextDialogue"] = 51011007,
            },
        [51011006] = {
            ["Content"] = "我穿麻袋都好看。",
            ["ContentFR"] = "<I>Même vêtu d’un sac de jute, je serais superbe.</>",
            ["DialogueId"] = 51011006,
            ["GUID"] = "7FB3612C",
            ["ImprPlusId"] = 1005,
            ["NextDialogue"] = 51011007,
            },
        [51011007] = {
            ["Content"] = "那是当然，您可以先看看我们的款式图册，如果看中了哪件可以试穿。",
            ["ContentFR"] = "Bien entendu. Je vous invite à consulter notre catalogue de modèles. Si quelque chose vous plaît, vous pourrez l’essayer.",
            ["DialogueId"] = 51011007,
            ["GUID"] = "7FB36156",
            ["NextDialogue"] = 51011008,
            ["SpeakNpcId"] = 700008,
            },
        [51011008] = {
            ["Content"] = "（你接过了那本册子，上面的款式令人目不暇接。）",
            ["ContentFR"] = "Vous prenez le catalogue. Les créations qu’il contient donnent le tournis.",
            ["DialogueId"] = 51011008,
            ["GUID"] = "7FB36180",
            ["NextDialogue"] = 51011009,
            },
        [51011009] = {
            ["Content"] = "（是时候享受生活了，就从买一件新衣服开始如何？这么想着的你指了指了一件色彩艳丽的{性别：衣服|裙子}。）",
            ["ContentFR"] = "Et si vous profitiez un peu de la vie ? Acheter un nouveau vêtement serait un bon début. Vous désignez une {robe|tenue} aux couleurs éclatantes.",
            ["DialogueId"] = 51011009,
            ["GUID"] = "7FB361AA",
            ["NextDialogue"] = 51011010,
            },
        [51011010] = {
            ["Content"] = "{性别：不好意思，这件是女装。而且是按照我的身材缝制的，暂时没有适合您的尺码……|真不巧，这件是按照我的身材缝制的，暂时没有适合您的尺码……}",
            ["ContentFR"] = "{性别:Quel dommage... Cette pièce a été cousue à mes mesures. Je n’ai pas votre taille pour l’instant.|Je suis désolé, c’est un vêtement féminin. Et il a été cousu à mes mesures — je n’ai pas votre taille...}",
            ["DialogueId"] = 51011010,
            ["GUID"] = "7FB361D4",
            ["NextOptions"] = {
                [1] = 51011011,
                },
            ["RestartTag"] = 51011010,
            ["SpeakNpcId"] = 700008,
            },
        [51011011] = {
            ["Content"] = "我就想要这件，要不你先穿上让我参考一下。",
            ["ContentFR"] = "C’est précisément celle-là que je veux. Vous pourriez l’enfiler pour que je me fasse une idée ?",
            ["DialogueId"] = 51011011,
            ["FailDialogue"] = 51011012,
            ["GUID"] = "7FB361FE",
            ["ImprCheckId"] = 1076,
            ["NextDialogue"] = 51011013,
            },
        [51011012] = {
            ["Content"] = "呵呵，还是请您不要取笑我了。",
            ["ContentFR"] = "Héhé... ne vous moquez pas de moi.",
            ["DialogueId"] = 51011012,
            ["GUID"] = "7FB36228",
            ["SpeakNpcId"] = 700008,
            },
        [51011013] = {
            ["Content"] = "如果您一定要看的话倒也没什么，只是现在换上的话可能会带来一些不必要的困扰。",
            ["ContentFR"] = "Si vous insistez vraiment, ce n’est pas impossible... Mais me changer ici risquerait de provoquer quelques désagréments.",
            ["DialogueId"] = 51011013,
            ["GUID"] = "7FB36252",
            ["NextDialogue"] = 51011014,
            ["SpeakNpcId"] = 700008,
            },
        [51011014] = {
            ["Content"] = "会被认成女性吗？",
            ["ContentFR"] = "On pourrait vous prendre pour une femme ?",
            ["DialogueId"] = 51011014,
            ["GUID"] = "7FB3627C",
            ["NextDialogue"] = 51011015,
            ["SpeakNpcId"] = 100001,
            },
        [51011015] = {
            ["Content"] = "确实如此，但又不完全是这样……重点不在于有谁“把我认成女士”，而是“把我认成女士后会发生什么”。",
            ["ContentFR"] = "Exactement... mais ce n’est qu’une partie du problème. La question n’est pas « qui me prendra pour une dame », mais bien « ce qui arrivera ensuite ».",
            ["DialogueId"] = 51011015,
            ["GUID"] = "7FB362A6",
            ["NextDialogue"] = 51011016,
            ["SpeakNpcId"] = 700008,
            },
        [51011016] = {
            ["Content"] = "或许这样和您表述很难理解……",
            ["ContentFR"] = "C’est peut-être difficile à comprendre ainsi...",
            ["DialogueId"] = 51011016,
            ["GUID"] = "7FB362D0",
            ["NextDialogue"] = 51011017,
            ["SpeakNpcId"] = 700008,
            },
        [51011017] = {
            ["Content"] = "难道……有人把你当成了女人，然后对你心生爱意？！",
            ["ContentFR"] = "Attendez... quelqu’un vous a pris pour une femme et est tombé amoureux de vous ?!",
            ["DialogueId"] = 51011017,
            ["GUID"] = "7FB362FA",
            ["NextDialogue"] = 51011018,
            ["SpeakNpcId"] = 100001,
            },
        [51011018] = {
            ["Content"] = "哦，幸好您是这般聪慧，省去了不少解释的时间。",
            ["ContentFR"] = "Ah... quelle sagacité. Vous m’épargnez bien des explications.",
            ["DialogueId"] = 51011018,
            ["GUID"] = "7FB36324",
            ["NextDialogue"] = 51011019,
            ["SpeakNpcId"] = 700008,
            },
        }
  end },
  { MinKey = 51011019, MaxKey = 51100004, Loader = function()
      return {
        [51011019] = {
            ["Content"] = "不过那位专情的先生似乎是认定了另一种现实，在他的想象中我有一个美丽的妹妹。",
            ["ContentFR"] = "Cet homme passionné semble avoir choisi une autre réalité, dans laquelle j’aurais une charmante sœur cadette.",
            ["DialogueId"] = 51011019,
            ["GUID"] = "7FB3634E",
            ["NextDialogue"] = 51011020,
            ["SpeakNpcId"] = 700008,
            },
        [51011020] = {
            ["Content"] = "直到一位可爱的皎皎小姐突然找到我的店里，对我声情并茂地朗诵对方的情书，我才知道自己的行为引起了误会。",
            ["ContentFR"] = "Je n’ai compris le malentendu que le jour où une adorable Luno s’est présentée dans ma boutique pour me réciter, avec émotion, ses lettres d’amour.",
            ["DialogueId"] = 51011020,
            ["GUID"] = "7FB36378",
            ["NextDialogue"] = 51011021,
            ["SpeakNpcId"] = 700008,
            },
        [51011021] = {
            ["Content"] = "我不得不在那位皎皎小姐代其传达爱意的时候谎称我的妹妹有事出门，才一次次地搪塞过去。",
            ["ContentFR"] = "Depuis, chaque fois qu’elle vient transmettre ses sentiments, je prétends que ma « sœur » est sortie. C’est devenu une habitude.",
            ["DialogueId"] = 51011021,
            ["GUID"] = "7FB363A2",
            ["NextDialogue"] = 51011022,
            ["SpeakNpcId"] = 700008,
            },
        [51011022] = {
            ["Content"] = "那你为什么不直接和他说清楚呢？",
            ["ContentFR"] = "Pourquoi ne pas lui dire simplement la vérité ?",
            ["DialogueId"] = 51011022,
            ["GUID"] = "7FB363CC",
            ["NextDialogue"] = 51011023,
            ["SpeakNpcId"] = 100001,
            },
        [51011023] = {
            ["Content"] = "为什么……因为很有趣？",
            ["ContentFR"] = "Pourquoi... ? Parce que c’est divertissant, peut-être ?",
            ["DialogueId"] = 51011023,
            ["GUID"] = "7FB363F6",
            ["NextDialogue"] = 51011024,
            ["SpeakNpcId"] = 700008,
            },
        [51011024] = {
            ["Content"] = "“你漂亮的头巾，和我家的北风莓一样鲜甜诱人。”",
            ["ContentFR"] = "« Ton joli foulard est aussi doux et sucré que les Baies boréales de mon jardin. »",
            ["DialogueId"] = 51011024,
            ["GUID"] = "7FB36420",
            ["NextDialogue"] = 51011025,
            ["SpeakNpcId"] = 700008,
            },
        [51011025] = {
            ["Content"] = "“你火红的裙子，像火焰根那样炽烈，让我紧张的冒汗。”",
            ["ContentFR"] = "« Ta robe écarlate brûle comme une racine de feu, et me fait transpirer de nervosité. »",
            ["DialogueId"] = 51011025,
            ["GUID"] = "7FB3644A",
            ["NextDialogue"] = 51011026,
            ["SpeakNpcId"] = 700008,
            },
        [51011026] = {
            ["Content"] = "不管我换成什么样的装扮，他都会在两天后对每一套衣装给出类似风格的评价。",
            ["ContentFR"] = "Quelle que soit la tenue que je porte, deux jours plus tard, il me fait parvenir une appréciation du même style.",
            ["DialogueId"] = 51011026,
            ["GUID"] = "7FB36474",
            ["NextDialogue"] = 51011027,
            ["SpeakNpcId"] = 700008,
            },
        [51011027] = {
            ["Content"] = "尽管措辞稍微有些……质朴，但对于我而言也是相当直观的参考。",
            ["ContentFR"] = "Ses mots sont peut-être un peu... rustiques, mais pour moi, ce sont des retours étonnamment utiles.",
            ["DialogueId"] = 51011027,
            ["GUID"] = "7FB3649E",
            ["NextDialogue"] = 51011028,
            ["SpeakNpcId"] = 700008,
            },
        [51011028] = {
            ["Content"] = "这个风格总觉得有些熟悉……",
            ["ContentFR"] = "Ce style me semble étrangement familier...",
            ["DialogueId"] = 51011028,
            ["GUID"] = "7FB364C8",
            ["NextDialogue"] = 51011029,
            ["SpeakNpcId"] = 100001,
            },
        [51011029] = {
            ["Content"] = "您认识那位为情所困的先生？既然如此，还请您代为保守这个秘密。",
            ["ContentFR"] = "Vous connaissez cet homme éperdu d’amour ? Dans ce cas, je vous prie de garder le secret.",
            ["DialogueId"] = 51011029,
            ["GUID"] = "7FB364F2",
            ["NextDialogue"] = 51011030,
            ["SpeakNpcId"] = 700008,
            },
        [51011030] = {
            ["Content"] = "你只是想找一个工具人帮你评论你新设计的衣服吧……",
            ["ContentFR"] = "Vous l’utilisez simplement comme critique gratuit pour vos nouvelles créations, non... ?",
            ["DialogueId"] = 51011030,
            ["GUID"] = "7FB3651C",
            ["NextDialogue"] = 51011031,
            ["SpeakNpcId"] = 100001,
            },
        [51011031] = {
            ["Content"] = "“这位情感真挚的先生明天会用什么样新奇的比喻来描述我的衣服”，如果是您遇到这样的事，也会有这样的好奇心吧？",
            ["ContentFR"] = "« Quelle métaphore inédite utilisera-t-il demain pour décrire mes vêtements ? » Si vous étiez à ma place, n’éprouveriez-vous pas la même curiosité ?",
            ["DialogueId"] = 51011031,
            ["GUID"] = "7FB36546",
            ["NextDialogue"] = 51011032,
            ["SpeakNpcId"] = 700008,
            },
        [51011032] = {
            ["Content"] = "不过最近这位先生的言辞不像往常那样直白，就像对一个捉摸不透的梦产生了犹豫……",
            ["ContentFR"] = "Dernièrement pourtant, ses mots sont moins directs... Comme s’il hésitait face à un rêve qu’il ne parvient plus à saisir.",
            ["DialogueId"] = 51011032,
            ["GUID"] = "7FB36570",
            ["NextDialogue"] = 51011033,
            ["SpeakNpcId"] = 700008,
            },
        [51011033] = {
            ["Content"] = "也许我可以在适当的时机做出一些适当的回应，才能在保持距离的同时让他不要放弃？",
            ["ContentFR"] = "Peut-être devrais-je lui répondre subtilement, au bon moment... Juste assez pour entretenir l’espoir, sans l’encourager à s’approcher davantage.",
            ["DialogueId"] = 51011033,
            ["GUID"] = "7FB3659A",
            ["NextDialogue"] = 51011034,
            ["SpeakNpcId"] = 700008,
            },
        [51011034] = {
            ["Content"] = "你这完全是乐在其中了啊……",
            ["ContentFR"] = "Vous y prenez clairement plaisir...",
            ["DialogueId"] = 51011034,
            ["GUID"] = "7FB365C4",
            ["SpeakNpcId"] = 100001,
            },
        [51011035] = {
            ["Content"] = "是您啊，还请您帮忙保守秘密。作为回报，本店对您永久打折。",
            ["ContentFR"] = "Ah, c’est vous. Je compte sur votre discrétion. En échange, cette boutique vous accordera une remise permanente.",
            ["DialogueId"] = 51011035,
            ["GUID"] = "7FB365EE",
            ["SpeakNpcId"] = 700008,
            },
        [51011101] = {
            ["Content"] = "哇，商户们工作得好认真！",
            ["ContentFR"] = "Ouaah, les commerçants travaillent vraiment dur !",
            ["DialogueId"] = 51011101,
            ["GUID"] = "7FB370C2",
            ["NextDialogue"] = 51011102,
            ["SpeakNpcId"] = 700336,
            },
        [51011102] = {
            ["Content"] = "不像我，只会睡觉和晒太阳……",
            ["ContentFR"] = "Pas comme moi... je fais que dormir et prendre le soleil...",
            ["DialogueId"] = 51011102,
            ["GUID"] = "7FB370EC",
            ["NextOptions"] = {
                [1] = 51011103,
                [2] = 51011104,
                [3] = 51011105,
                },
            ["SpeakNpcId"] = 700336,
            },
        [51011103] = {
            ["Content"] = "每个人都有适合自己的生活方式。",
            ["ContentFR"] = "<I>Chacun a sa propre manière de vivre.</>",
            ["DialogueId"] = 51011103,
            ["GUID"] = "7FB37116",
            ["ImprPlusId"] = 1002,
            ["NextDialogue"] = 51011106,
            },
        [51011104] = {
            ["Content"] = "晒太阳和睡觉才是人生啊！",
            ["ContentFR"] = "<I>Dormir au soleil, c’est ça la vraie vie !</>",
            ["DialogueId"] = 51011104,
            ["GUID"] = "7FB37140",
            ["ImprPlusId"] = 1004,
            ["NextDialogue"] = 51011106,
            },
        [51011105] = {
            ["Content"] = "晒太阳和睡觉对身体有好处，是对健康的长期投资。",
            ["ContentFR"] = "<I>Dormir et prendre le soleil, c’est bon pour la santé. Un investissement à long terme.</>",
            ["DialogueId"] = 51011105,
            ["GUID"] = "7FB3716A",
            ["ImprPlusId"] = 1003,
            ["NextDialogue"] = 51011106,
            },
        [51011106] = {
            ["Content"] = "哇，你很懂嘛。",
            ["ContentFR"] = "Ouaah, tu t’y connais !",
            ["DialogueId"] = 51011106,
            ["GUID"] = "7FB37194",
            ["NextDialogue"] = 51011107,
            ["SpeakNpcId"] = 700336,
            },
        [51011107] = {
            ["Content"] = "但不劳动就总是有愧疚感，看到他们这么辛苦地赚钱，而我无所事事的却还这么富有，总觉得过意不去……",
            ["ContentFR"] = "Mais si je ne travaille pas, je me sens toujours un peu coupable... Les voir se donner tant de mal pour gagner leur vie, alors que je ne fais rien et que je suis pourtant si riche... Ça me met mal à l’aise...",
            ["DialogueId"] = 51011107,
            ["GUID"] = "7FB371BE",
            ["NextDialogue"] = 51011108,
            ["SpeakNpcId"] = 700336,
            },
        [51011108] = {
            ["Content"] = "但是对皎皎来说，如果不帮人干点啥就会浑身难受，不踏实，唉……",
            ["ContentFR"] = "Et puis, pour une Luno... si je n’aide personne, je me sens toute bizarre, pas tranquille... hmmm...",
            ["DialogueId"] = 51011108,
            ["GUID"] = "7FB371E8",
            ["NextOptions"] = {
                [1] = 51011109,
                },
            ["RestartTag"] = 51011108,
            ["SpeakNpcId"] = 700336,
            },
        [51011109] = {
            ["Content"] = "（询问空空皎皎致富秘诀。）",
            ["ContentFR"] = "<I>Demander à Luno, l’étourdie, son secret pour devenir riche</>",
            ["DialogueId"] = 51011109,
            ["FailDialogue"] = 51011110,
            ["GUID"] = "7FB37212",
            ["ImprCheckId"] = 1077,
            ["NextDialogue"] = 51011111,
            },
        [51011110] = {
            ["Content"] = "……什么？哈（呵欠），你刚才说了什么吗……",
            ["ContentFR"] = "... Hein ? Ha... Tu as dit quelque chose, à l’instant... ?",
            ["DialogueId"] = 51011110,
            ["GUID"] = "7FB3723C",
            ["SpeakNpcId"] = 700336,
            },
        [51011111] = {
            ["Content"] = "致富秘诀？就是我有次不小心从山崖掉了下去，碰巧捡了块价值连城的石头，一下子就变有钱了。这么多钱根本花不完……",
            ["ContentFR"] = "Mon secret pour devenir riche ? Une fois, je suis tombée d’une falaise par accident, et j’ai ramassé une pierre qui valait une fortune. D’un coup, je suis devenue incroyablement riche... Impossible de tout dépenser...",
            ["DialogueId"] = 51011111,
            ["GUID"] = "7FB37266",
            ["NextDialogue"] = 51011112,
            ["SpeakNpcId"] = 700336,
            },
        [51011112] = {
            ["Content"] = "要不你也从山崖上跳下去试试？",
            ["ContentFR"] = "Tu pourrais essayer de tomber d’une falaise toi aussi ?",
            ["DialogueId"] = 51011112,
            ["GUID"] = "7FB37290",
            ["NextOptions"] = {
                [1] = 51011113,
                [2] = 51011114,
                },
            ["SpeakNpcId"] = 700336,
            },
        [51011113] = {
            ["Content"] = "谢谢，已经试过了……",
            ["ContentFR"] = "<I>Merci, j’ai déjà essayé...</>",
            ["DialogueId"] = 51011113,
            ["GUID"] = "7FB372BA",
            ["NextDialogue"] = 51011115,
            },
        [51011114] = {
            ["Content"] = "可恶，为什么同样是从山崖上掉下去，我就没摊上这种好事！",
            ["ContentFR"] = "<I>Quelle injustice ! Pourquoi quand je tombe d’une falaise, il ne m’arrive jamais ce genre de chose ?!</>",
            ["DialogueId"] = 51011114,
            ["GUID"] = "7FB372E4",
            ["NextDialogue"] = 51011115,
            },
        [51011115] = {
            ["Content"] = "唔……那我只能帮你到这里了。",
            ["ContentFR"] = "Hmm... alors je ne peux pas t’aider davantage.",
            ["DialogueId"] = 51011115,
            ["GUID"] = "7FB3730E",
            ["NextDialogue"] = 51011116,
            ["SpeakNpcId"] = 700336,
            },
        [51011116] = {
            ["Content"] = "哦！我想起来了，那个卖果子的瓦伦大叔又要我帮他传话呢！太好了，有事做了……",
            ["ContentFR"] = "Oh ! Je viens de me souvenir — Valen, le marchand de fruits, m’a encore demandé de transmettre un message ! Génial, j’ai quelque chose à faire...",
            ["DialogueId"] = 51011116,
            ["GUID"] = "7FB37338",
            ["SpeakNpcId"] = 700336,
            },
        [51011201] = {
            ["Content"] = "……",
            ["ContentFR"] = "...",
            ["DialogueId"] = 51011201,
            ["GUID"] = "7FB3812A",
            ["NextDialogue"] = 51011202,
            ["SpeakNpcId"] = 700339,
            },
        [51011202] = {
            ["Content"] = "（少女盯着窗外一言不发，聚焦在远处的目光似乎在浩瀚的苍穹中寻找着什么。）",
            ["ContentFR"] = "La jeune fille fixe l’extérieur par la fenêtre, en silence. Son regard semble chercher quelque chose au loin, perdu dans l’immensité du ciel.",
            ["DialogueId"] = 51011202,
            ["GUID"] = "7FB38154",
            ["NextDialogue"] = 51011203,
            },
        [51011203] = {
            ["Content"] = "（从她的身上，你感受到了一种不该属于她这个年纪的气息——凝滞、衰朽的气息。）",
            ["ContentFR"] = "Il émane d’elle une atmosphère qui ne devrait pas appartenir à quelqu’un de son âge — une sensation de stagnation, de lente décrépitude.",
            ["DialogueId"] = 51011203,
            ["GUID"] = "7FB3817E",
            ["NextOptions"] = {
                [1] = 51011204,
                [2] = 51011220,
                },
            },
        [51011204] = {
            ["Content"] = "向她搭话",
            ["ContentFR"] = "<I>S’approcher et lui parler</>",
            ["DialogueId"] = 51011204,
            ["GUID"] = "7FB381A8",
            ["NextDialogue"] = 51011205,
            },
        [51011205] = {
            ["Content"] = "（或许是担心下一刻她就会做出什么不可挽回的事情，又或者是对她在寻找的事物产生了好奇，你决定向她搭话。）",
            ["ContentFR"] = "Craignant qu’elle ne fasse quelque chose d’irréversible, ou simplement intrigué par ce qu’elle semble chercher, vous décidez de lui parler.",
            ["DialogueId"] = 51011205,
            ["GUID"] = "7FB381D2",
            ["NextDialogue"] = 51011206,
            },
        [51011206] = {
            ["Content"] = "你好？",
            ["ContentFR"] = "Bonjour ?",
            ["DialogueId"] = 51011206,
            ["GUID"] = "7FB381FC",
            ["NextDialogue"] = 51011207,
            ["SpeakNpcId"] = 100001,
            },
        [51011207] = {
            ["Content"] = "……",
            ["ContentFR"] = "...",
            ["DialogueId"] = 51011207,
            ["GUID"] = "7FB38226",
            ["NextDialogue"] = 51011208,
            ["SpeakNpcId"] = 700339,
            },
        [51011208] = {
            ["Content"] = "……",
            ["ContentFR"] = "...",
            ["DialogueId"] = 51011208,
            ["GUID"] = "7FB38250",
            ["NextDialogue"] = 51011209,
            ["SpeakNpcId"] = 100001,
            },
        [51011209] = {
            ["Content"] = "有什么事直接说就好。",
            ["ContentFR"] = "Si vous avez quelque chose à dire, dites-le directement.",
            ["DialogueId"] = 51011209,
            ["GUID"] = "7FB3827A",
            ["NextDialogue"] = 51011210,
            ["SpeakNpcId"] = 700339,
            },
        [51011210] = {
            ["Content"] = "没什么，只是你好像一直在看很远的地方，是在找什么吗？",
            ["ContentFR"] = "Oh, ce n’est rien... C’est juste que vous regardez au loin depuis un moment. Vous cherchez quelque chose ?",
            ["DialogueId"] = 51011210,
            ["GUID"] = "7FB382A4",
            ["NextDialogue"] = 51011211,
            ["SpeakNpcId"] = 100001,
            },
        [51011211] = {
            ["Content"] = "是吗……说不定，我没有在看向任何地方呢？",
            ["ContentFR"] = "Vraiment... ? Peut-être que je ne regarde nulle part, en réalité.",
            ["DialogueId"] = 51011211,
            ["GUID"] = "7FB382CE",
            ["NextDialogue"] = 51011212,
            ["SpeakNpcId"] = 700339,
            },
        [51011212] = {
            ["Content"] = "就只是……无意义地消磨时间而已。",
            ["ContentFR"] = "Je fais juste... passer le temps. Sans but.",
            ["DialogueId"] = 51011212,
            ["GUID"] = "7FB382F8",
            ["NextOptions"] = {
                [1] = 51011213,
                [2] = 51011215,
                },
            ["SpeakNpcId"] = 700339,
            },
        [51011213] = {
            ["Content"] = "我有时也会像这样发呆，感觉心情会变得平静。",
            ["ContentFR"] = "<I>Il m’arrive aussi de rester comme ça, à ne penser à rien. Ça apaise l’esprit.</>",
            ["DialogueId"] = 51011213,
            ["GUID"] = "7FB38322",
            ["ImprPlusId"] = 1004,
            ["NextDialogue"] = 51011214,
            },
        [51011214] = {
            ["Content"] = "“有时”吗……看来你和我是不一样的人……",
            ["ContentFR"] = "« Il t’arrive »... On dirait bien que nous ne sommes pas pareils.",
            ["DialogueId"] = 51011214,
            ["GUID"] = "7FB3834C",
            ["NextDialogue"] = 51011217,
            ["SpeakNpcId"] = 700339,
            },
        [51011215] = {
            ["Content"] = "要不要聊聊别的话题，比如——晚饭吃什么？",
            ["ContentFR"] = "<I>On peut parler d’autre chose, si vous voulez... Par exemple, qu’est-ce que vous mangerez ce soir ?</>",
            ["DialogueId"] = 51011215,
            ["GUID"] = "7FB38376",
            ["ImprPlusId"] = 1001,
            ["NextDialogue"] = 51011216,
            },
        [51011216] = {
            ["Content"] = "随便——我知道这算不上回答，但我的确没什么想吃的东西。",
            ["ContentFR"] = "N’importe quoi — je sais que ce n’est pas vraiment une réponse, mais honnêtement, je n’ai envie de rien.",
            ["DialogueId"] = 51011216,
            ["GUID"] = "7FB383A0",
            ["NextDialogue"] = 51011217,
            ["SpeakNpcId"] = 700339,
            },
        [51011217] = {
            ["Content"] = "（少女垂下头去，不再多言。）",
            ["ContentFR"] = "La jeune fille baisse la tête et ne dit plus un mot.",
            ["DialogueId"] = 51011217,
            ["GUID"] = "7FB383CA",
            ["NextDialogue"] = 51011218,
            },
        [51011218] = {
            ["Content"] = "（每个人都会有旁人无法得知的困境，并且终有一日将要独自面对。）",
            ["ContentFR"] = "Chacun porte des épreuves que nul autre ne peut voir, et qu’il devra un jour affronter seul.",
            ["DialogueId"] = 51011218,
            ["GUID"] = "7FB383F4",
            ["NextDialogue"] = 51011219,
            },
        [51011219] = {
            ["Content"] = "（也许此刻的她还没有鼓起勇气，那就让她自己先静一静吧——你这样想着。）",
            ["ContentFR"] = "Peut-être n’a-t-elle pas encore trouvé le courage nécessaire. Autant la laisser tranquille pour le moment, pensez-vous.",
            ["DialogueId"] = 51011219,
            ["GUID"] = "7FB3841E",
            },
        [51011220] = {
            ["Content"] = "无视她",
            ["ContentFR"] = "<I>Ignorer</>",
            ["DialogueId"] = 51011220,
            ["GUID"] = "7FB38448",
            ["NextDialogue"] = 51011221,
            },
        [51011221] = {
            ["Content"] = "（或许是她过于阴郁的表情在周围凝结出了一片生人勿近的气场，你决定还是不要多管闲事了。）",
            ["ContentFR"] = "Son expression sombre semble dresser autour d’elle une barrière invisible. Vous décidez de ne pas vous mêler de ses affaires.",
            ["DialogueId"] = 51011221,
            ["GUID"] = "7FB38472",
            ["Scripts"] = "SetOutport{FinishType{\"Fail\"}}",
            },
        [51011301] = {
            ["Content"] = "离我远一点……我什么都不知道！！",
            ["ContentFR"] = "Restez loin de moi... Je ne sais rien !",
            ["DialogueId"] = 51011301,
            ["GUID"] = "7FB39192",
            ["NextDialogue"] = 51011302,
            ["SpeakNpcId"] = 700341,
            },
        [51011302] = {
            ["Content"] = "我只是想看看那只怀表，或许能修好也说不定。",
            ["ContentFR"] = "Je voulais juste regarder cette montre à gousset. Peut-être que je pourrais la réparer.",
            ["DialogueId"] = 51011302,
            ["GUID"] = "7FB391BC",
            ["NextDialogue"] = 51011303,
            ["SpeakNpcId"] = 100001,
            },
        [51011303] = {
            ["Content"] = "……",
            ["ContentFR"] = "...",
            ["DialogueId"] = 51011303,
            ["GUID"] = "7FB391E6",
            ["NextDialogue"] = 51011304,
            ["SpeakNpcId"] = 700341,
            },
        [51011304] = {
            ["Content"] = "那是很重要的东西吧？",
            ["ContentFR"] = "C’est quelque chose de très important pour vous, n’est-ce pas ?",
            ["DialogueId"] = 51011304,
            ["GUID"] = "7FB39210",
            ["NextDialogue"] = 51011305,
            ["SpeakNpcId"] = 100001,
            },
        [51011305] = {
            ["Content"] = "真的……能修好吗？",
            ["ContentFR"] = "Vous... vous pouvez vraiment la réparer ?",
            ["DialogueId"] = 51011305,
            ["GUID"] = "7FB3923A",
            ["NextOptions"] = {
                [1] = 51011306,
                [2] = 51011312,
                },
            ["SpeakNpcId"] = 700341,
            },
        [51011306] = {
            ["Content"] = "你愿意让我试试吗？",
            ["ContentFR"] = "<I>Accepteriez-vous que j’essaie ?</>",
            ["DialogueId"] = 51011306,
            ["GUID"] = "7FB39264",
            ["ImprPlusId"] = 1004,
            ["NextDialogue"] = 51011307,
            },
        [51011307] = {
            ["Content"] = "我……我不知道……",
            ["ContentFR"] = "Je... je ne sais pas...",
            ["DialogueId"] = 51011307,
            ["GUID"] = "7FB3928E",
            ["NextDialogue"] = 51011308,
            ["SpeakNpcId"] = 700341,
            },
        [51011308] = {
            ["Content"] = "亨特……我该怎么做？",
            ["ContentFR"] = "Hunt... Qu’est-ce que je suis censée faire... ?",
            ["DialogueId"] = 51011308,
            ["GUID"] = "7FB392B8",
            ["NextDialogue"] = 51011309,
            ["SpeakNpcId"] = 700341,
            },
        [51011309] = {
            ["Content"] = "所以，亨特他到底发生了什么？",
            ["ContentFR"] = "Alors, qu’est-il arrivé à Hunt ?",
            ["DialogueId"] = 51011309,
            ["GUID"] = "7FB392E2",
            ["NextDialogue"] = 51011310,
            ["SpeakNpcId"] = 100001,
            },
        [51011310] = {
            ["Content"] = "他……",
            ["ContentFR"] = "Il...",
            ["DialogueId"] = 51011310,
            ["GUID"] = "7FB3930C",
            ["NextDialogue"] = 51011311,
            ["SpeakNpcId"] = 700341,
            },
        [51011311] = {
            ["Content"] = "不，我不能说。请你离开这里吧，不要再来了。",
            ["ContentFR"] = "Non. Je ne peux pas en parler. S’il vous plaît, partez. Et ne revenez plus.",
            ["DialogueId"] = 51011311,
            ["GUID"] = "7FB39336",
            ["NextDialogue"] = 51011317,
            ["SpeakNpcId"] = 700341,
            },
        [51011312] = {
            ["Content"] = "城里应该有钟表匠吧，我们可以找他们帮忙。",
            ["ContentFR"] = "<I>Il doit bien y avoir des horlogers en ville. Nous pourrions leur demander de l’aide.</>",
            ["DialogueId"] = 51011312,
            ["GUID"] = "7FB39360",
            ["ImprPlusId"] = 1003,
            ["NextDialogue"] = 51011313,
            },
        [51011313] = {
            ["Content"] = "那请你……",
            ["ContentFR"] = "Alors vous pourriez...",
            ["DialogueId"] = 51011313,
            ["GUID"] = "7FB3938A",
            ["NextDialogue"] = 51011314,
            ["SpeakNpcId"] = 700341,
            },
        [51011314] = {
            ["Content"] = "不……不可以相信外面的人。",
            ["ContentFR"] = "Non... Je ne peux pas faire confiance aux gens de l’extérieur.",
            ["DialogueId"] = 51011314,
            ["GUID"] = "7FB393B4",
            ["NextDialogue"] = 51011315,
            ["SpeakNpcId"] = 700341,
            },
        [51011315] = {
            ["Content"] = "当我什么都没说过吧。",
            ["ContentFR"] = "Oubliez ce que j’ai dit.",
            ["DialogueId"] = 51011315,
            ["GUID"] = "7FB393DE",
            ["NextDialogue"] = 51011316,
            ["SpeakNpcId"] = 700341,
            },
        [51011316] = {
            ["Content"] = "请你离开这里，不要再来了。",
            ["ContentFR"] = "S’il vous plaît, partez. Et ne revenez plus.",
            ["DialogueId"] = 51011316,
            ["GUID"] = "7FB39408",
            ["NextDialogue"] = 51011317,
            ["SpeakNpcId"] = 700341,
            },
        [51011317] = {
            ["Content"] = "（少女的情绪转变让你一时间不知道该如何应对，只能试图从她的眼神中得到更多信息。）",
            ["ContentFR"] = "Le brusque changement d’attitude de la jeune fille vous laisse désemparé. Vous tentez de lire quelque chose de plus dans son regard.",
            ["DialogueId"] = 51011317,
            ["GUID"] = "7FB39432",
            ["NextDialogue"] = 51011318,
            },
        [51011318] = {
            ["Content"] = "（那是双充满迷茫与悲伤的眼睛，却又夹杂着一丝不易察觉的信念。你并不知道那信念从何而来，又意味着什么。但你明白这就是她守口如瓶的原因。）",
            ["ContentFR"] = "Ses yeux sont emplis de confusion et de tristesse, mais au fond brille une lueur de conviction difficile à saisir. Vous ignorez d’où elle vient et ce qu’elle signifie, mais vous comprenez que c’est elle qui la pousse à garder le silence.",
            ["DialogueId"] = 51011318,
            ["GUID"] = "7FB3945C",
            },
        [51011401] = {
            ["Content"] = "桌子……擦过了。地板……也擦过了。还剩……扶手，对，还有扶手。",
            ["ContentFR"] = "La table... c’est fait. Le sol... aussi. Il reste... la rampe. Oui, la rampe.",
            ["DialogueId"] = 51011401,
            ["GUID"] = "7FB3A1FA",
            ["NextDialogue"] = 51011402,
            ["SpeakNpcId"] = 700340,
            },
        [51011402] = {
            ["Content"] = "（少年絮絮自言自语着什么，面露急色，双手无所适从地比划着。）",
            ["ContentFR"] = "Le garçon marmonne sans cesse, l’air anxieux. Ses mains s’agitent, maladroites, comme s’il ne savait où les poser.",
            ["DialogueId"] = 51011402,
            ["GUID"] = "7FB3A224",
            ["NextDialogue"] = 51011403,
            },
        [51011403] = {
            ["Content"] = "……你让一让。",
            ["ContentFR"] = "... Écartez-vous.",
            ["DialogueId"] = 51011403,
            ["GUID"] = "7FB3A24E",
            ["NextDialogue"] = 51011404,
            ["SpeakNpcId"] = 700340,
            },
        [51011404] = {
            ["Content"] = "嗯？",
            ["ContentFR"] = "Hm ?",
            ["DialogueId"] = 51011404,
            ["GUID"] = "7FB3A278",
            ["NextDialogue"] = 51011405,
            ["SpeakNpcId"] = 100001,
            },
        [51011405] = {
            ["Content"] = "扶手，还没有擦。不要挡路。",
            ["ContentFR"] = "La rampe. Je ne l’ai pas encore nettoyée. Vous gênez.",
            ["DialogueId"] = 51011405,
            ["GUID"] = "7FB3A2A2",
            ["NextDialogue"] = 51011406,
            ["SpeakNpcId"] = 700340,
            },
        [51011406] = {
            ["Content"] = "（顺着少年急切不安的视线，你看到了他凝视着的东西——楼梯扶手。但在你看来，那个扶手不算新，却光洁锃亮，一尘不染。）",
            ["ContentFR"] = "En suivant son regard fébrile, vous comprenez ce qu’il fixe — la rampe de l’escalier. À vos yeux, elle n’est peut-être pas neuve, mais elle est lisse, brillante, et parfaitement propre.",
            ["DialogueId"] = 51011406,
            ["GUID"] = "7FB3A2CC",
            ["NextOptions"] = {
                [1] = 51011407,
                [2] = 51011411,
                },
            },
        [51011407] = {
            ["Content"] = "不用擦了。我瞧着那个扶手还挺干净的。",
            ["ContentFR"] = "<I>Inutile de nettoyer. Elle a l’air déjà très propre.</>",
            ["DialogueId"] = 51011407,
            ["GUID"] = "7FB3A2F6",
            ["ImprPlusId"] = 1001,
            ["NextDialogue"] = 51011408,
            },
        [51011408] = {
            ["Content"] = "不干净！那里我今天还没擦过，不能算干净……",
            ["ContentFR"] = "Pas propre ! Je ne l’ai pas nettoyée aujourd’hui, donc elle ne l’est pas...",
            ["DialogueId"] = 51011408,
            ["GUID"] = "7FB3A320",
            ["NextDialogue"] = 51011409,
            ["SpeakNpcId"] = 700340,
            },
        [51011409] = {
            ["Content"] = "还有二楼的画框、书橱、落地灯……还有……",
            ["ContentFR"] = "Et il y a encore les cadres du deuxième étage, la bibliothèque, le lampadaire... et puis... et puis...",
            ["DialogueId"] = 51011409,
            ["GUID"] = "7FB3A34A",
            ["NextDialogue"] = 51011410,
            ["SpeakNpcId"] = 700340,
            },
        [51011410] = {
            ["Content"] = "不要管我，拜托你……你就没有自己的事要忙吗？",
            ["ContentFR"] = "Ne vous occupez pas de moi, je vous en prie... Vous n’avez pas autre chose à faire ?",
            ["DialogueId"] = 51011410,
            ["GUID"] = "7FB3A374",
            ["NextDialogue"] = 51011412,
            ["SpeakNpcId"] = 700340,
            },
        [51011411] = {
            ["Content"] = "（让出道路。）",
            ["ContentFR"] = "<I>Laisser le passage</>",
            ["DialogueId"] = 51011411,
            ["GUID"] = "7FB3A39E",
            ["ImprPlusId"] = 1004,
            ["NextDialogue"] = 51011412,
            },
        [51011412] = {
            ["Content"] = "（你识趣地耸耸肩，侧身让出一条道路，任由他徒劳奔忙。）",
            ["ContentFR"] = "Vous haussez discrètement les épaules et vous écartez, le laissant reprendre son agitation vaine et obstinée.",
            ["DialogueId"] = 51011412,
            ["GUID"] = "7FB3A3C8",
            },
        [51011501] = {
            ["Content"] = "好心人，求你帮帮我……给多少都可以……救救身无分文的老人家吧……",
            ["ContentFR"] = "Brave âme... je vous en prie... Donnez ce que vous pouvez... Ayez pitié d’un vieil homme sans le sou...",
            ["DialogueId"] = 51011501,
            ["GUID"] = "7FB3B262",
            ["SpeakNpcId"] = 700338,
            },
        [51011601] = {
            ["Content"] = "末日将至啊……末日将至……",
            ["ContentFR"] = "La fin approche... la fin approche...",
            ["DialogueId"] = 51011601,
            ["GUID"] = "7FB3C2CA",
            ["SpeakNpcId"] = 700337,
            },
        [51011701] = {
            ["Content"] = "哇，商户们工作得好认真！",
            ["ContentFR"] = "Ouaah, les commerçants travaillent vraiment dur !",
            ["DialogueId"] = 51011701,
            ["GUID"] = "7FB3D332",
            ["SpeakNpcId"] = 700336,
            },
        [51011801] = {
            ["Content"] = "……",
            ["ContentFR"] = "...",
            ["DialogueId"] = 51011801,
            ["GUID"] = "7FB3E39A",
            ["SpeakNpcId"] = 700339,
            },
        [51011901] = {
            ["Content"] = "离我远一点……我什么都不知道！！",
            ["ContentFR"] = "Restez loin de moi... Je ne sais rien !",
            ["DialogueId"] = 51011901,
            ["GUID"] = "7FB3F402",
            ["SpeakNpcId"] = 700341,
            },
        [51012001] = {
            ["Content"] = "……先别说话。这些台阶，还没擦干净。",
            ["ContentFR"] = "... Ne parlez pas. Ces marches ne sont pas encore propres.",
            ["DialogueId"] = 51012001,
            ["GUID"] = "7FB4046A",
            ["SpeakNpcId"] = 700340,
            },
        [51012101] = {
            ["Content"] = "喵，喵喵！",
            ["ContentFR"] = "<I>Miaou, miaou !</>",
            ["DialogueId"] = 51012101,
            ["GUID"] = "7FB414D2",
            ["NextDialogue"] = 51012102,
            ["SpeakNpcId"] = 700334,
            },
        [51012102] = {
            ["Content"] = "（离得老远，野猫就兴奋地叫着，一蹦一跳地朝你跑来。）",
            ["ContentFR"] = "De très loin, le chat errant vous aperçoit et se met à miauler avec enthousiasme. Il bondit joyeusement dans votre direction.",
            ["DialogueId"] = 51012102,
            ["GUID"] = "7FB414FC",
            ["NextDialogue"] = 51012103,
            },
        [51012103] = {
            ["Content"] = "喵。",
            ["ContentFR"] = "<I>Miaou.</>",
            ["DialogueId"] = 51012103,
            ["GUID"] = "7FB41526",
            ["NextDialogue"] = 51012104,
            ["SpeakNpcId"] = 700334,
            },
        [51012104] = {
            ["Content"] = "（它看起来很有精神，并不需要你陪它玩或者给它找吃的。而是围着你的脚转了两圈后跑向了休憩之所的方向，转头看着你，似乎想要你跟上去。） ",
            ["ContentFR"] = "Il a l’air plein d’énergie et ne semble ni réclamer votre attention ni attendre de la nourriture. Après avoir tourné deux fois autour de vos pieds, il s’élance vers le Sanctuaire, puis se retourne pour vous regarder, comme pour vous inviter à le suivre.",
            ["DialogueId"] = 51012104,
            ["GUID"] = "7FB41550",
            ["NextOptions"] = {
                [1] = 51012105,
                [2] = 51012106,
                },
            },
        [51012105] = {
            ["Content"] = "（跟过去看看。）",
            ["ContentFR"] = "<I>Suivre le chat</>",
            ["DialogueId"] = 51012105,
            ["GUID"] = "7FB4157A",
            },
        [51012106] = {
            ["Content"] = "（以后再说。）",
            ["ContentFR"] = "<I>Remettre à plus tard</>",
            ["DialogueId"] = 51012106,
            ["GUID"] = "7FB415A4",
            ["Scripts"] = "SetOutport{FinishType{\"Fail\"}}",
            },
        [51012107] = {
            ["Content"] = "（野猫从休憩之所附近的草丛里叼出一条硬邦邦的冻鱼，歪头看着你，似乎那便是它的谢礼。）",
            ["ContentFR"] = "Dans les hautes herbes près du Sanctuaire, le chat errant tire avec peine un poisson gelé, dur comme la pierre. Il penche la tête vers vous, comme s’il vous offrait son présent.",
            ["DialogueId"] = 51012107,
            ["GUID"] = "7FB415CE",
            ["NextDialogue"] = 51012108,
            },
        [51012108] = {
            ["Content"] = "（你捡起冻鱼，有什么叮叮当当地从冻鱼口中掉了出来——哦，那是几枚闪着暗淡光泽的铜币……）",
            ["ContentFR"] = "Vous ramassez le poisson gelé. Soudain, quelque chose tombe de sa gueule avec un léger tintement... Oh, ce sont quelques pièces de cuivre à l’éclat terni.",
            ["DialogueId"] = 51012108,
            ["GUID"] = "7FB415F8",
            ["NextDialogue"] = 51012109,
            },
        [51012109] = {
            ["Content"] = "你是记住了我的味道，所以给我准备了礼物吗？",
            ["ContentFR"] = "Tu as mémorisé mon odeur... et tu m’as préparé un cadeau en retour ?",
            ["DialogueId"] = 51012109,
            ["GUID"] = "7FB41622",
            ["NextDialogue"] = 51012110,
            ["SpeakNpcId"] = 100001,
            },
        [51012110] = {
            ["Content"] = "喵——",
            ["ContentFR"] = "<I>Miaou—</>",
            ["DialogueId"] = 51012110,
            ["GUID"] = "7FB4164C",
            ["NextDialogue"] = 51012111,
            ["SpeakNpcId"] = 700335,
            },
        [51012111] = {
            ["Content"] = "（野猫好似听懂了你的话一般长叫了一声，亲昵地用头蹭着你的脚。）",
            ["ContentFR"] = "Comme s’il avait compris vos paroles, le chat pousse un long miaulement, puis frotte affectueusement sa tête contre vos jambes.",
            ["DialogueId"] = 51012111,
            ["GUID"] = "7FB41676",
            ["NextOptions"] = {
                [1] = 51012112,
                [2] = 51012113,
                },
            },
        [51012112] = {
            ["Content"] = "谢谢你的好意。",
            ["ContentFR"] = "<I>Merci pour ton attention.</>",
            ["DialogueId"] = 51012112,
            ["GUID"] = "7FB416A0",
            ["ImprPlusId"] = 1004,
            ["NextDialogue"] = 51012114,
            },
        [51012113] = {
            ["Content"] = "给我找点更好的谢礼。",
            ["ContentFR"] = "<I>Tu n’aurais pas un meilleur cadeau ?</>",
            ["DialogueId"] = 51012113,
            ["GUID"] = "7FB416CA",
            ["ImprPlusId"] = 1005,
            ["NextDialogue"] = 51012114,
            },
        [51012114] = {
            ["Content"] = "（野猫听罢点了点头，蹦跳着跑远了。虽然不知道它下次会给你带来什么，但你知道，接下来很长一段时间，你都会经常在休憩之所看到它了。）",
            ["ContentFR"] = "Le chat hoche la tête, puis s’éloigne en bondissant. Vous ignorez ce qu’il vous rapportera la prochaine fois, mais vous savez déjà qu’à partir de maintenant, vous le croiserez souvent autour du Sanctuaire.",
            ["DialogueId"] = 51012114,
            ["GUID"] = "7FB416F4",
            },
        [51012201] = {
            ["Content"] = "（既然它已经打算留在休憩之所，那就给它取个名字吧。）",
            ["ContentFR"] = "Puisqu’il a décidé de rester au Sanctuaire, autant lui donner un nom.",
            ["DialogueId"] = 51012201,
            ["GUID"] = "7FB4253A",
            },
        [51012202] = {
            ["Content"] = "喵~喵——",
            ["ContentFR"] = "<I>Miaou~ Miaou—</>",
            ["DialogueId"] = 51012202,
            ["GUID"] = "7FB42564",
            ["NextDialogue"] = 51012203,
            ["SpeakNpcId"] = 888888,
            },
        [51012203] = {
            ["Content"] = "（收到新名字后，它喵喵叫着围着你转圈，显然十分喜欢{catname}这个名字。）",
            ["ContentFR"] = "En entendant son nouveau nom, le chat se met à miauler joyeusement en tournant autour de vous. De toute évidence, {catname} lui plaît beaucoup.",
            ["DialogueId"] = 51012203,
            ["GUID"] = "7FB4258E",
            ["NextDialogue"] = 51012204,
            },
        [51012204] = {
            ["Content"] = "好，那{catname}就是你以后的名字了。",
            ["ContentFR"] = "Très bien. Désormais, tu t’appelleras {catname}.",
            ["DialogueId"] = 51012204,
            ["GUID"] = "7FB425B8",
            ["SpeakNpcId"] = 100001,
            },
        [51012300] = {
            ["Content"] = "“咔嚓——”",
            ["DialogueId"] = 51012300,
            ["GUID"] = "7FB43578",
            ["NextDialogue"] = 51012301,
            },
        [51012301] = {
            ["Content"] = "咦？",
            ["DialogueId"] = 51012301,
            ["GUID"] = "7FB435A2",
            ["NextDialogue"] = 51012302,
            ["SpeakNpcId"] = 100001,
            },
        [51012302] = {
            ["Content"] = "啊，真抱歉，不小心把你拍进去了……",
            ["DialogueId"] = 51012302,
            ["GUID"] = "7FB435CC",
            ["NextDialogue"] = 51012304,
            ["SpeakNpcId"] = 700383,
            },
        [51012303] = {
            ["Content"] = "我不是故意的，之后我会把这张照片销毁。",
            ["DialogueId"] = 51012303,
            ["GUID"] = "7FB435F6",
            ["SpeakNpcId"] = 700383,
            },
        [51012304] = {
            ["Content"] = "你为什么要拍这座房子？",
            ["DialogueId"] = 51012304,
            ["GUID"] = "7FB43620",
            ["NextDialogue"] = 51012305,
            ["SpeakNpcId"] = 100001,
            },
        [51012305] = {
            ["Content"] = "噢，在解释之前，请允许我做个自我介绍——我叫帕蒂，是一个旅行摄影师！",
            ["DialogueId"] = 51012305,
            ["GUID"] = "7FB4364A",
            ["NextDialogue"] = 51012306,
            ["SpeakNpcId"] = 700383,
            },
        [51012306] = {
            ["Content"] = "我今天刚到冰湖城，正在寻找此地值得记录的风景。",
            ["DialogueId"] = 51012306,
            ["GUID"] = "7FB43674",
            ["NextDialogue"] = 51012307,
            ["SpeakNpcId"] = 700383,
            },
        [51012307] = {
            ["Content"] = "这座房子实在是漂亮极了，我看得入迷，情不自禁地举起了相机……所以才没注意到你路过，抱歉啦。",
            ["DialogueId"] = 51012307,
            ["GUID"] = "7FB4369E",
            ["NextDialogue"] = 51012308,
            ["SpeakNpcId"] = 700383,
            },
        [51012308] = {
            ["Content"] = "“摄影师”……就是专门拍照的人？原来世界上还有这种职业啊。你拍过很多照片吗？",
            ["DialogueId"] = 51012308,
            ["GUID"] = "7FB436C8",
            ["NextDialogue"] = 51012309,
            ["SpeakNpcId"] = 100001,
            },
        [51012309] = {
            ["Content"] = "当然啦，你看——",
            ["DialogueId"] = 51012309,
            ["GUID"] = "7FB436F2",
            ["NextDialogue"] = 51012310,
            ["SpeakNpcId"] = 700383,
            },
        [51012310] = {
            ["Content"] = "（少女从包里掏出一本厚厚的笔记，打开向你展示。里面贴着很多照片，文字反而很少。）",
            ["DialogueId"] = 51012310,
            ["GUID"] = "7FB4371C",
            ["NextDialogue"] = 51012311,
            },
        [51012311] = {
            ["Content"] = "原来照片还能做成这样特别的笔记，真有意思……我拍的照片都被我随手放在柜子里了。",
            ["DialogueId"] = 51012311,
            ["GUID"] = "7FB43746",
            ["NextDialogue"] = 51012312,
            ["SpeakNpcId"] = 100001,
            },
        [51012312] = {
            ["Content"] = "嘿嘿，我把它叫做“影像笔记”哦。你感兴趣的话，也做一本试试怎么样？",
            ["DialogueId"] = 51012312,
            ["GUID"] = "7FB43770",
            ["NextDialogue"] = 51012313,
            ["SpeakNpcId"] = 700383,
            },
        [51012313] = {
            ["Content"] = "好像有点难。",
            ["DialogueId"] = 51012313,
            ["GUID"] = "7FB4379A",
            ["NextDialogue"] = 51012314,
            ["SpeakNpcId"] = 100001,
            },
        [51012314] = {
            ["Content"] = "一点也不难的，你试试就知道啦！",
            ["DialogueId"] = 51012314,
            ["GUID"] = "7FB437C4",
            ["NextDialogue"] = 51012315,
            ["SpeakNpcId"] = 700383,
            },
        [51012315] = {
            ["Content"] = "可是……就算说要做，我不知道该放些什么照片，写些什么文字。你是怎么做的？",
            ["DialogueId"] = 51012315,
            ["GUID"] = "7FB437EE",
            ["NextDialogue"] = 51012316,
            ["SpeakNpcId"] = 100001,
            },
        [51012316] = {
            ["Content"] = "其实我一开始也是随便做做的。不过，做了这么多年，我也算积累了一些经验。既然你是从头做起，那先定一下属于你的影像笔记的“主题”，怎么样？",
            ["DialogueId"] = 51012316,
            ["GUID"] = "7FB43818",
            ["NextDialogue"] = 51012317,
            ["SpeakNpcId"] = 700383,
            },
        [51012317] = {
            ["Content"] = "主题？",
            ["DialogueId"] = 51012317,
            ["GUID"] = "7FB43842",
            ["NextDialogue"] = 51012318,
            ["SpeakNpcId"] = 100001,
            },
        [51012318] = {
            ["Content"] = "嗯，简单来说就是你制作笔记的目的——就比如说我吧，我制作这些笔记，是为了回到故乡时拿给我的姐姐看。",
            ["DialogueId"] = 51012318,
            ["GUID"] = "7FB4386C",
            ["NextDialogue"] = 51012319,
            ["SpeakNpcId"] = 700383,
            },
        [51012319] = {
            ["Content"] = "我姐姐曾经很喜欢旅行，可后来她生了重病，身体变得很弱，没法再出远门，一直郁郁寡欢。",
            ["DialogueId"] = 51012319,
            ["GUID"] = "7FB43896",
            ["NextDialogue"] = 51012320,
            ["SpeakNpcId"] = 700383,
            },
        [51012320] = {
            ["Content"] = "可有一天，当我无意中把我外出时拍到的照片展示给姐姐看的时候，她的脸上竟然破天荒地出现了笑容……",
            ["DialogueId"] = 51012320,
            ["GUID"] = "7FB438C0",
            ["NextDialogue"] = 51012321,
            ["SpeakNpcId"] = 700383,
            },
        [51012321] = {
            ["Content"] = "这就是我开始旅行并制作影像笔记的契机。我想要走到更远的地方，拍下更多的风景，让姐姐在家也能看到广阔的世界。",
            ["DialogueId"] = 51012321,
            ["GUID"] = "7FB438EA",
            ["NextDialogue"] = 51012322,
            ["SpeakNpcId"] = 700383,
            },
        [51012322] = {
            ["Content"] = "所以，我的影像笔记的主题就是“记录广阔的世界”。从这个主题出发，我要做的就是找到新的风景并记录下来。你呢，你有什么特别想记录的东西吗？",
            ["DialogueId"] = 51012322,
            ["GUID"] = "7FB43914",
            ["NextDialogue"] = 51012325,
            ["SpeakNpcId"] = 700383,
            },
        [51012323] = {
            ["Content"] = "……",
            ["DialogueId"] = 51012323,
            ["GUID"] = "7FB4393E",
            ["SpeakNpcId"] = 100001,
            },
        [51012324] = {
            ["Content"] = "用你的眼睛，替我继续看看这个世界吧。",
            ["DialogueId"] = 51012324,
            ["GUID"] = "7FB43968",
            ["SpeakNpcName"] = "UI_Npc_Name_Saiqi",
            },
        [51012325] = {
            ["Content"] = "送给我照相机的那个人曾经说过，希望我能代替她继续看看这个世界。",
            ["DialogueId"] = 51012325,
            ["GUID"] = "7FB43992",
            ["NextDialogue"] = 51012326,
            ["SpeakNpcId"] = 100001,
            },
        [51012326] = {
            ["Content"] = "我想把旅程中拍摄过的照片制作成影像笔记，作为好好看过这个世界的证明。这可以作为“主题”吗？",
            ["DialogueId"] = 51012326,
            ["GUID"] = "7FB439BC",
            ["NextDialogue"] = 51012327,
            ["SpeakNpcId"] = 100001,
            },
        [51012327] = {
            ["Content"] = "当然了，我觉得这个主题很棒！",
            ["DialogueId"] = 51012327,
            ["GUID"] = "7FB439E6",
            ["NextDialogue"] = 51012328,
            ["SpeakNpcId"] = 700383,
            },
        [51012328] = {
            ["Content"] = "既然你已经有方向了，不如现在就开始行动起来！我刚好带了一本空白的笔记，就送给你吧。",
            ["DialogueId"] = 51012328,
            ["GUID"] = "7FB43A10",
            ["NextDialogue"] = 51012329,
            ["SpeakNpcId"] = 700383,
            },
        [51012329] = {
            ["Content"] = "没关系，我可以自己去买。",
            ["DialogueId"] = 51012329,
            ["GUID"] = "7FB43A3A",
            ["NextDialogue"] = 51012330,
            ["SpeakNpcId"] = 100001,
            },
        [51012330] = {
            ["Content"] = "不不，我这本可不是商店那种普通笔记本。你看，它的内页里已经做好了放置照片和书写文字的区域，对新手来说很方便哦。",
            ["DialogueId"] = 51012330,
            ["GUID"] = "7FB43A64",
            ["NextDialogue"] = 51012331,
            ["SpeakNpcId"] = 700383,
            },
        [51012331] = {
            ["Content"] = "它的封面还是空白的，你可以自己给它加上装饰，让它变得独一无二。这样，记录的过程也会变得更有成就感！",
            ["DialogueId"] = 51012331,
            ["GUID"] = "7FB43A8E",
            ["NextDialogue"] = 51012332,
            ["SpeakNpcId"] = 700383,
            },
        [51012332] = {
            ["Content"] = "原来如此……那我就收下了，谢谢你。",
            ["DialogueId"] = 51012332,
            ["GUID"] = "7FB43AB8",
            ["NextDialogue"] = 51012333,
            ["SpeakNpcId"] = 100001,
            },
        [51012333] = {
            ["Content"] = "嗯，加油呀，新人摄影师！等你做出了属于自己的影像笔记，欢迎来找我分享~",
            ["DialogueId"] = 51012333,
            ["GUID"] = "7FB43AE2",
            ["SpeakNpcId"] = 700383,
            },
        [51012400] = {
            ["Content"] = "（该怎么装饰呢……？对了，也许铁匠前辈那里会有材料。）",
            ["DialogueId"] = 51012400,
            ["GUID"] = "7FB445E0",
            ["SpeakNpcId"] = 100001,
            },
        [51012500] = {
            ["Content"] = "嗯？年轻人，找我有事吗？",
            ["DialogueId"] = 51012500,
            ["GUID"] = "7FB45648",
            ["NextDialogue"] = 51012501,
            ["SpeakNpcId"] = 230002,
            },
        [51012501] = {
            ["Content"] = "你好，前辈。我想给这本“影像笔记”做一些装饰。如果你有多余的材料，可不可以分一些给我？",
            ["DialogueId"] = 51012501,
            ["GUID"] = "7FB45672",
            ["NextDialogue"] = 51012502,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "0:Talk02_Start",
                },
            },
        [51012502] = {
            ["Content"] = "有，当然有！平时你这么照顾老朽的生意，这点小忙不在话下。来，你自己挑，想要的尽管拿走。",
            ["DialogueId"] = 51012502,
            ["GUID"] = "7FB4569C",
            ["NextDialogue"] = 51012503,
            ["SpeakNpcId"] = 230002,
            ["TalkActionId"] = {
                [1] = "0:Talk02_End",
                },
            },
        [51012503] = {
            ["Content"] = "哈哈，真教人怀念啊，老朽小的时候，也很喜欢做手工……",
            ["DialogueId"] = 51012503,
            ["GUID"] = "7FB456C6",
            ["NextDialogue"] = 51012504,
            ["SpeakNpcId"] = 230002,
            },
        [51012504] = {
            ["Content"] = "在铁匠前辈的帮助下对影像笔记进行了装饰……",
            ["DialogueId"] = 51012504,
            ["GUID"] = "7FB456F0",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 51012505,
            },
        [51012505] = {
            ["Content"] = "嗯，这样就差不多了。接下来，想一想要放怎样的照片进去吧。",
            ["DialogueId"] = 51012505,
            ["DialoguePanelType"] = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_Chapter_Passport.T_Guide_Chapter_Passport'}",
            ["GUID"] = "7FB4571A",
            ["SpeakNpcId"] = 100001,
            },
        [51012600] = {
            ["Content"] = "第一张照片，应该是旅途的起点。那么，就只能是那个地方了——",
            ["DialogueId"] = 51012600,
            ["GUID"] = "7FB466B0",
            ["NextDialogue"] = 51012601,
            ["SpeakNpcId"] = 100001,
            },
        [51012601] = {
            ["Content"] = "净界岛，我和贝蕾妮卡一起生活的故乡。",
            ["DialogueId"] = 51012601,
            ["GUID"] = "7FB466DA",
            ["NextDialogue"] = 51012602,
            ["SpeakNpcId"] = 100001,
            },
        [51012602] = {
            ["Content"] = "如果以后能回到净界岛，我想给<H>家</>拍一张照片，作为笔记的第一页。",
            ["DialogueId"] = 51012602,
            ["GUID"] = "7FB46704",
            ["NextDialogue"] = 51012603,
            ["SpeakNpcId"] = 100001,
            },
        [51012603] = {
            ["Content"] = "等找到了贝蕾妮卡，再和她一起拍一张照片吧。",
            ["DialogueId"] = 51012603,
            ["GUID"] = "7FB47718",
            ["SpeakNpcId"] = 100001,
            },
        [51012800] = {
            ["Content"] = "离开净界岛之后，我来到了冰湖城。",
            ["DialogueId"] = 51012800,
            ["GUID"] = "7FB48780",
            ["NextDialogue"] = 51012801,
            ["SpeakNpcId"] = 100001,
            },
        [51012801] = {
            ["Content"] = "在这座冷冰冰的城市，有一个女孩温柔地接纳了我、帮助了我……",
            ["DialogueId"] = 51012801,
            ["GUID"] = "7FB487AA",
            ["NextDialogue"] = 51012802,
            ["SpeakNpcId"] = 100001,
            },
        [51012802] = {
            ["Content"] = "第二页的照片，就选<H>和她第一次见面的地方</>吧。",
            ["DialogueId"] = 51012802,
            ["GUID"] = "7FB487D4",
            ["NextDialogue"] = 51012803,
            ["SpeakNpcId"] = 100001,
            },
        [51012803] = {
            ["Content"] = "我不会忘记，在净界岛之外的世界，是谁给了我第一份温暖的回忆。",
            ["DialogueId"] = 51012803,
            ["GUID"] = "7FB497E8",
            ["NextDialogue"] = 51012804,
            ["SpeakNpcId"] = 100001,
            },
        [51012804] = {
            ["Content"] = "我会记住你的，赛琪。",
            ["DialogueId"] = 51012804,
            ["GUID"] = "7FB49812",
            ["SpeakNpcId"] = 100001,
            },
        [51013000] = {
            ["Content"] = "这一页……我想留下<H>和赛琪分别的地方</>。",
            ["DialogueId"] = 51013000,
            ["GUID"] = "7FB4A850",
            ["NextDialogue"] = 51013001,
            ["SpeakNpcId"] = 100001,
            },
        [51013001] = {
            ["Content"] = "虽然非常不想回忆那个悲伤的时刻……但，赛琪一定会希望我全部记住。",
            ["DialogueId"] = 51013001,
            ["GUID"] = "7FB4A87A",
            ["NextDialogue"] = 51013002,
            ["SpeakNpcId"] = 100001,
            },
        [51013002] = {
            ["Content"] = "赛琪，我没有忘记约定。",
            ["DialogueId"] = 51013002,
            ["GUID"] = "7FB4B8B8",
            ["NextDialogue"] = 51013003,
            ["SpeakNpcId"] = 100001,
            },
        [51013003] = {
            ["Content"] = "将来有一天，等我回到了南方，我一定会在房子周围种满花。",
            ["DialogueId"] = 51013003,
            ["GUID"] = "7FB4B8E2",
            ["SpeakNpcId"] = 100001,
            },
        [51013200] = {
            ["Content"] = "在那之后的下一个大事件……就是“卡戎狩猎”的案子，是幻景和布鲁斯的故事。",
            ["DialogueId"] = 51013200,
            ["GUID"] = "7FB4C920",
            ["NextDialogue"] = 51013201,
            ["SpeakNpcId"] = 100001,
            },
        [51013201] = {
            ["Content"] = "我还记得他们<H>在下水道里为自己搭建的那座舞台</>，那也是我们第一次见到扮演布鲁斯的幻景。",
            ["DialogueId"] = 51013201,
            ["GUID"] = "7FB4C94A",
            ["NextDialogue"] = 51013202,
            ["SpeakNpcId"] = 100001,
            },
        [51013202] = {
            ["Content"] = "这一页的相片，我会选择那沉没在淤泥之中，却依然闪闪发光的“梦想”。",
            ["DialogueId"] = 51013202,
            ["GUID"] = "7FB4C974",
            ["NextDialogue"] = 51013203,
            ["SpeakNpcId"] = 100001,
            },
        [51013203] = {
            ["Content"] = "回想起来，这就是他最后那场演出的“开幕”……",
            ["DialogueId"] = 51013203,
            ["GUID"] = "7FB4D988",
            ["NextDialogue"] = 51013204,
            ["SpeakNpcId"] = 100001,
            },
        [51013204] = {
            ["Content"] = "可惜那时候，我们还什么都不知道。",
            ["DialogueId"] = 51013204,
            ["GUID"] = "7FB4D9B2",
            ["SpeakNpcId"] = 100001,
            },
        [51013400] = {
            ["Content"] = "这一页，该记下“卡戎狩猎”的结局了。",
            ["DialogueId"] = 51013400,
            ["GUID"] = "7FB4E9F0",
            ["NextDialogue"] = 51013401,
            ["SpeakNpcId"] = 100001,
            },
        [51013401] = {
            ["Content"] = "盖雷亚剧院的舞台，幻景以自己的身份和我们第一次、也是最后一次对话的地方。我在<H>那座舞台</>见证了他故事的终幕。",
            ["DialogueId"] = 51013401,
            ["GUID"] = "7FB4EA1A",
            ["NextDialogue"] = 51013402,
            ["SpeakNpcId"] = 100001,
            },
        [51013402] = {
            ["Content"] = "虽然观众只有我们寥寥几人，但我们，以及他自己，都不会忘记……",
            ["DialogueId"] = 51013402,
            ["GUID"] = "7FB4EA44",
            ["NextDialogue"] = 51013403,
            ["SpeakNpcId"] = 100001,
            },
        [51013403] = {
            ["Content"] = "他在这里完成了一场最好的演出。",
            ["DialogueId"] = 51013403,
            ["GUID"] = "7FB4FA58",
            ["SpeakNpcId"] = 100001,
            },
        [51013600] = {
            ["Content"] = "后来，我们因为一场意外，跟着止流去往了华胥。",
            ["DialogueId"] = 51013600,
            ["GUID"] = "7FB50AC0",
            ["NextDialogue"] = 51013601,
            ["SpeakNpcId"] = 100001,
            },
        [51013601] = {
            ["Content"] = "如果要说最初对华胥的印象，脑海里首先浮现的，是烟津渡那座气派的商会“<H>百年春</>”。",
            ["DialogueId"] = 51013601,
            ["GUID"] = "7FB50AEA",
            ["NextDialogue"] = 51013602,
            ["SpeakNpcId"] = 100001,
            },
        [51013602] = {
            ["Content"] = "这一页就它吧，还记得百年春门口的那条白龙雕像很威风凛凛呢。",
            ["DialogueId"] = 51013602,
            ["GUID"] = "7FB50B14",
            ["NextDialogue"] = 51013603,
            ["SpeakNpcId"] = 100001,
            },
        [51013603] = {
            ["Content"] = "第一次踏上华胥的土地时，真是完全没想到竟会被卷入这样重大的事件……",
            ["DialogueId"] = 51013603,
            ["GUID"] = "7FB51B28",
            ["NextDialogue"] = 51013604,
            ["SpeakNpcId"] = 100001,
            },
        [51013604] = {
            ["Content"] = "命运还真是奇妙。不过，这大概本来就在止流的计划之中吧。",
            ["DialogueId"] = 51013604,
            ["GUID"] = "7FB51B52",
            ["SpeakNpcId"] = 100001,
            },
        [51013800] = {
            ["Content"] = "华胥的这段旅程中，最惊心动魄的一幕，还是听闻止流踏入太虚陵的时候吧。",
            ["DialogueId"] = 51013800,
            ["GUID"] = "7FB52B90",
            ["NextDialogue"] = 51013801,
            ["SpeakNpcId"] = 100001,
            },
        [51013801] = {
            ["Content"] = "那片土地上所有人的命运，都被悬在她抛出的钱币之上……好在，最终人们还是共同选择了正确的未来。",
            ["DialogueId"] = 51013801,
            ["GUID"] = "7FB52BBA",
            ["NextDialogue"] = 51013802,
            ["SpeakNpcId"] = 100001,
            },
        [51013802] = {
            ["Content"] = "这一页的相片，就放<H>执律阁上方的天空</>吧。",
            ["DialogueId"] = 51013802,
            ["GUID"] = "7FB52BE4",
            ["NextDialogue"] = 51013803,
            ["SpeakNpcId"] = 100001,
            },
        [51013803] = {
            ["Content"] = "现在回想那时的事还是有点后怕，好在最后一切都顺利收场了。",
            ["DialogueId"] = 51013803,
            ["GUID"] = "7FB53BF8",
            ["NextDialogue"] = 51013804,
            ["SpeakNpcId"] = 100001,
            },
        [51013804] = {
            ["Content"] = "不过，经历了华胥的故事，我也对未来多了一分信心——所谓的命运，一定是可以改变的。",
            ["DialogueId"] = 51013804,
            ["GUID"] = "7FB53C22",
            ["SpeakNpcId"] = 100001,
            },
        [51014000] = {
            ["Content"] = "目前我想到的足以代表这一路经历的照片就是这些了……不知道这样算是完成了我的“主题”吗？",
            ["DialogueId"] = 51014000,
            ["GUID"] = "7FB54C60",
            ["SpeakNpcId"] = 100001,
            },
        [51014100] = {
            ["Content"] = "“咔嚓——”",
            ["DialogueId"] = 51014100,
            ["GUID"] = "7FB55CC8",
            ["NextDialogue"] = 51014101,
            },
        [51014101] = {
            ["Content"] = "啊，真抱歉——咦？！",
            ["DialogueId"] = 51014101,
            ["GUID"] = "7FB55CF2",
            ["NextDialogue"] = 51014102,
            ["SpeakNpcId"] = 700383,
            },
        [51014102] = {
            ["Content"] = "你怎么从这栋房子里走出来了，该不会这里其实是你家吧？",
            ["DialogueId"] = 51014102,
            ["GUID"] = "7FB55D1C",
            ["NextDialogue"] = 51014103,
            ["SpeakNpcId"] = 700383,
            },
        [51014103] = {
            ["Content"] = "确实。",
            ["DialogueId"] = 51014103,
            ["GUID"] = "7FB55D46",
            ["NextDialogue"] = 51014104,
            ["SpeakNpcId"] = 100001,
            },
        [51014104] = {
            ["Content"] = "什么！我只是随口一问，没想到这真是{性别：他|她}家……早知道就不急着订旅馆了，{性别：他|她}这么好说话，说不定会同意我在这里借宿的……呜……",
            ["DialogueId"] = 51014104,
            ["GUID"] = "7FB55D70",
            ["NextDialogue"] = 51014105,
            ["SpeakNpcId"] = 700383,
            },
        [51014105] = {
            ["Content"] = "咳咳……言归正传。看来你已经开始制作自己的影像笔记了，感觉怎么样？",
            ["DialogueId"] = 51014105,
            ["GUID"] = "7FB55D9A",
            ["NextDialogue"] = 51014106,
            ["SpeakNpcId"] = 700383,
            },
        [51014106] = {
            ["Content"] = "我试着做了几页，感觉……很奇妙。",
            ["DialogueId"] = 51014106,
            ["GUID"] = "7FB55DC4",
            ["NextDialogue"] = 51014107,
            ["SpeakNpcId"] = 100001,
            },
        [51014107] = {
            ["Content"] = "尽管照片只是定格的画面，但当我把它贴在纸上，写下文字记录的时候，曾经经历过的一幕幕故事和当时的感受又清晰地浮现出来。",
            ["DialogueId"] = 51014107,
            ["GUID"] = "7FB55DEE",
            ["NextDialogue"] = 51014108,
            ["SpeakNpcId"] = 100001,
            },
        [51014108] = {
            ["Content"] = "所以说，影像笔记唤醒了你重要的回忆与情感——而这些正是你“好好看过世界的证明”！看来你完成了自己的主题呀。",
            ["DialogueId"] = 51014108,
            ["GUID"] = "7FB55E18",
            ["NextDialogue"] = 51014109,
            ["SpeakNpcId"] = 700383,
            },
        [51014109] = {
            ["Content"] = "嗯，你说得对。谢谢你向我介绍了这种特别的笔记，我会好好珍藏它。",
            ["DialogueId"] = 51014109,
            ["GUID"] = "7FB55E42",
            ["NextDialogue"] = 51014110,
            ["SpeakNpcId"] = 100001,
            },
        [51014110] = {
            ["Content"] = "不客气！能遇到像我一样认真记录影像的人，我也很开心。",
            ["DialogueId"] = 51014110,
            ["GUID"] = "7FB55E6C",
            ["NextDialogue"] = 51014111,
            ["SpeakNpcId"] = 700383,
            },
        [51014111] = {
            ["Content"] = "过几天我就要离开冰湖城了，或许在旅途的前方，我们还会再次相遇。到时候，再给我分享你的新笔记吧！",
            ["DialogueId"] = 51014111,
            ["GUID"] = "7FB55E96",
            ["NextDialogue"] = 51014112,
            ["SpeakNpcId"] = 700383,
            },
        [51014112] = {
            ["Content"] = "好啊，那就后会有期。",
            ["DialogueId"] = 51014112,
            ["GUID"] = "7FB55EC0",
            ["NextDialogue"] = 51014113,
            ["SpeakNpcId"] = 100001,
            },
        [51014113] = {
            ["Content"] = "嗯，后会有期！",
            ["DialogueId"] = 51014113,
            ["GUID"] = "7FB55F02",
            ["SpeakNpcId"] = 700383,
            },
        [51100001] = {
            ["Content"] = "心诚不怕道路难，自有龙神保周全。前方崎岖污浊地，为还宏愿也向前、前、前面路过的那位有龙氏！留步、留步啊！",
            ["ContentFR"] = "Un cœur sincère ne craint pas les chemins difficiles : le Seigneur Dragon d’Argent veille, et tout ira bien. Devant, la route est rude et souillée... mais pour accomplir mon grand vœu, j’avance... j’avance... j’a— Hé, toi, {性别:Descendant|Descendante} draconique qui passes par là ! Attends ! Attends donc !",
            ["DialogueId"] = 51100001,
            ["GUID"] = "7FEC69EA",
            },
        [51100002] = {
            ["Content"] = "哎呀别左顾右盼了，老夫喊的就是你哇。",
            ["ContentFR"] = "Ne regarde pas à droite et à gauche. C’est bien toi que j’interpelle !",
            ["DialogueId"] = 51100002,
            ["GUID"] = "7FEC6A14",
            ["NextOptions"] = {
                [1] = 51100003,
                [2] = 51100006,
                [3] = 51100009,
                },
            ["SpeakNpcId"] = 700319,
            },
        [51100003] = {
            ["Content"] = "都有龙神护你周全了，为什么喊住我呢？",
            ["ContentFR"] = "<I>Puisque le Seigneur Dragon d’Argent te protège, pourquoi m’arrêter ?</>",
            ["DialogueId"] = 51100003,
            ["GUID"] = "7FEC6A3E",
            ["ImprPlusId"] = 1208,
            ["NextDialogue"] = 51100004,
            },
        [51100004] = {
