        [51104006] = {
            ["Camera"] = "359.076172,-369.277344,120.089844,0.000002,-2.199519,103.398605,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "哥，我想吃这个。",
            ["ContentFR"] = "Frangin, je veux celui-là.",
            ["DialogueId"] = 51104006,
            ["GUID"] = "7FEEFAFC",
            ["LookAt"] = {
                [1] = "700326:n(700327)",
                [2] = "700328:n(700327)",
                },
            ["NextDialogue"] = 51104007,
            ["SpeakNpcId"] = 700327,
            ["TurnTo"] = {
                [1] = "700326:n(700327)",
                [2] = "700327:n(700326)",
                },
            },
        [51104007] = {
            ["Content"] = "啊？桂花糕啊……明明说好不买这买那才带你出门的。",
            ["ContentFR"] = "Hein ? Des gâteaux à l’osmanthe... On avait pourtant dit qu’on n’achèterait rien aujourd’hui, sinon je ne t’aurais pas emmené.",
            ["DialogueId"] = 51104007,
            ["FacialId"] = {
                [1] = "700326:Syouganai01",
                },
            ["GUID"] = "7FEEFB26",
            ["LookAt"] = {
                [1] = "700327:n(700326)",
                [2] = "700328:n(700326)",
                },
            ["NextDialogue"] = 51104008,
            ["SpeakNpcId"] = 700326,
            ["TalkActionId"] = {
                [1] = "700326:Disagree",
                },
            },
        [51104008] = {
            ["Content"] = "我没有买这买那，今天从出门到现在我明明只让你买了一次蜂蜜糍耙。",
            ["ContentFR"] = "Mais si ! Depuis ce matin, je t’ai demandé qu’une seule chose : des galettes de riz au miel !",
            ["DialogueId"] = 51104008,
            ["GUID"] = "7FEEFB50",
            ["LookAt"] = {
                [1] = "700326:n(700327)",
                [2] = "700328:n(700327)",
                },
            ["NextDialogue"] = 51104009,
            ["SpeakNpcId"] = 700327,
            ["TalkActionId"] = {
                [1] = "700327:Talk03_Start",
                },
            },
        [51104009] = {
            ["Content"] = "糍粑不好消化，刚吃完现在又要吃这桂花糕……",
            ["ContentFR"] = "Les galettes de riz, c’est déjà difficile à digérer... Si tu manges encore ça, tu n’auras plus faim ce soir.",
            ["DialogueId"] = 51104009,
            ["FacialId"] = {
                [1] = "700326:Unhappy01",
                },
            ["GUID"] = "7FEEFB7A",
            ["LookAt"] = {
                [1] = "700327:n(700326)",
                [2] = "700328:n(700326)",
                },
            ["NextDialogue"] = 51104010,
            ["SpeakNpcId"] = 700326,
            ["TalkActionId"] = {
                [1] = "700327:Talk03_End",
                [2] = "700326:Talk01_Start",
                },
            },
        [51104010] = {
            ["Content"] = "一会回家吃不下饭被阿娘骂事小，要是再晚上肚子胀到睡不着觉我可帮不了你。",
            ["ContentFR"] = "Se faire gronder par Maman, passe encore... Mais si tu as mal au ventre cette nuit, je ne pourrai rien pour toi.",
            ["DialogueId"] = 51104010,
            ["GUID"] = "7FEEFBA4",
            ["LookAt"] = {
                [1] = "700327:n(700326)",
                [2] = "700328:n(700326)",
                },
            ["NextDialogue"] = 51104011,
            ["SpeakNpcId"] = 700326,
            ["TalkActionId"] = {
                [1] = "700326:Talk01_End",
                },
            },
        [51104011] = {
            ["Content"] = "我不管！今天吃不到桂花糕我就不回去了，到时候阿娘一着急你就惨咯。",
            ["ContentFR"] = "Je m’en fiche ! Si je n’ai pas de gâteau à l’osmanthe aujourd’hui, je ne rentre pas ! Et quand Maman s’inquiétera, c’est toi qui seras dans de beaux draps !",
            ["DialogueId"] = 51104011,
            ["GUID"] = "7FEEFBCE",
            ["LookAt"] = {
                [1] = "700326:n(700327)",
                [2] = "700328:n(700327)",
                },
            ["NextDialogue"] = 51104012,
            ["SpeakNpcId"] = 700327,
            ["TalkActionId"] = {
                [1] = "700327:Angry01_Start",
                },
            },
        [51104012] = {
            ["Content"] = "行吧行吧，拗不过你。老板，要一份桂花糕。",
            ["ContentFR"] = "Bon... bon... impossible de te raisonner. Patron, une portion de gâteau à l’osmanthe, s’il vous plaît.",
            ["DialogueId"] = 51104012,
            ["FacialId"] = {
                [1] = "700326:Syouganai01",
                },
            ["GUID"] = "7FEEFBF8",
            ["LookAt"] = {
                [1] = "700327:n(700326)",
                [2] = "700328:n(700326)",
                },
            ["NextDialogue"] = 51104013,
            ["SpeakNpcId"] = 700326,
            ["TalkActionId"] = {
                [1] = "700327:Angry01_End",
                },
            ["TurnTo"] = {
                [1] = "700326:n(700328)",
                [2] = "700327:n(700328)",
                },
            },
        [51104013] = {
            ["Content"] = "好嘞。",
            ["ContentFR"] = "Bien reçu.",
            ["DialogueId"] = 51104013,
            ["FacialId"] = {
                [1] = "700328:Smile01",
                },
            ["GUID"] = "7FEEFC22",
            ["LookAt"] = {
                [1] = "700327:n(700328)",
                [2] = "700326:n(700328)",
                },
            ["NextDialogue"] = 51104014,
            ["SpeakNpcId"] = 700328,
            ["TalkActionId"] = {
                [1] = "700328:Give",
                },
            },
        [51104014] = {
            ["Content"] = "呃……老板，桂花糕能卖半份……啊不，三分之一份吗？出门带的铜币好像不够了……",
            ["ContentFR"] = "Euh... patron... On pourrait en prendre une demi-portion ? Ou... un tiers ? J’ai l’impression de ne pas avoir assez de pièces...",
            ["DialogueId"] = 51104014,
            ["GUID"] = "7FEEFC4C",
            ["LookAt"] = {
                [1] = "700327:n(700326)",
                [2] = "700328:n(700326)",
                },
            ["NextDialogue"] = 51104015,
            ["SpeakNpcId"] = 700326,
            ["TalkActionId"] = {
                [1] = "700326:Sigh_Start",
                },
            },
        [51104015] = {
            ["Content"] = "你这小家伙……罢了罢了。",
            ["ContentFR"] = "Ah, petit filou... bon, bon.",
            ["DialogueId"] = 51104015,
            ["FacialId"] = {
                [1] = "700328:Syouganai01",
                },
            ["GUID"] = "7FEEFC76",
            ["LookAt"] = {
                [1] = "700327:n(700328)",
                [2] = "700326:n(700328)",
                },
            ["NextDialogue"] = 51104016,
            ["SpeakNpcId"] = 700328,
            ["TalkActionId"] = {
                [1] = "700326:Sigh_End",
                },
            },
        [51104016] = {
            ["Content"] = "我们家老爷子倒是交代过，要是有小孩子嘴馋也不用太计较，按老爷子说法，给你们两个小家伙出个谜语。",
            ["ContentFR"] = "Mon vieux maître disait toujours que pour des enfants gourmands, inutile d’être trop strict. Alors voilà ce qu’on va faire : une énigme.",
            ["DialogueId"] = 51104016,
            ["GUID"] = "7FEEFCA0",
            ["LookAt"] = {
                [1] = "700327:n(700328)",
                [2] = "700326:n(700328)",
                },
            ["NextDialogue"] = 51104017,
            ["SpeakNpcId"] = 700328,
            ["TalkActionId"] = {
                [1] = "700328:Think_Start",
                },
            },
        [51104017] = {
            ["Content"] = "要是你俩能猜上来啊，这桂花糕送你们一份也行。",
            ["ContentFR"] = "Si vous trouvez la bonne réponse, le gâteau est pour vous.",
            ["DialogueId"] = 51104017,
            ["GUID"] = "7FEEFCCA",
            ["LookAt"] = {
                [1] = "700327:n(700328)",
                [2] = "700326:n(700328)",
                },
            ["NextDialogue"] = 51104018,
            ["SpeakNpcId"] = 700328,
            },
        [51104018] = {
            ["Content"] = "真的吗？",
            ["ContentFR"] = "Vraiment ?!",
            ["DialogueId"] = 51104018,
            ["GUID"] = "7FEEFCF4",
            ["LookAt"] = {
                [1] = "700326:n(700327)",
                [2] = "700328:n(700327)",
                },
            ["NextDialogue"] = 51104019,
            ["SpeakNpcId"] = 700327,
            ["TalkActionId"] = {
                [1] = "700327:Huanhu_Nan_Start",
                [2] = "700328:Think_End",
                },
            },
        [51104019] = {
            ["Content"] = "我骗你们两个小毛孩做什么。",
            ["ContentFR"] = "Pourquoi est-ce que je mentirais à deux garnements ?",
            ["DialogueId"] = 51104019,
            ["GUID"] = "7FEEFD1E",
            ["LookAt"] = {
                [1] = "700327:n(700328)",
                [2] = "700326:n(700328)",
                },
            ["NextDialogue"] = 51104020,
            ["SpeakNpcId"] = 700328,
            ["TalkActionId"] = {
                [1] = "700328:Talk01_Start",
                },
            },
        [51104020] = {
            ["Content"] = "小武，快说谢谢叔叔！",
            ["ContentFR"] = "Wu, dis merci au monsieur !",
            ["DialogueId"] = 51104020,
            ["GUID"] = "7FEEFD48",
            ["LookAt"] = {
                [1] = "700327:n(700326)",
                [2] = "700328:n(700326)",
                [3] = "700326:n(700327)",
                },
            ["NextDialogue"] = 51104021,
            ["SpeakNpcId"] = 700326,
            ["TalkActionId"] = {
                [1] = "700326:Talk01_Start",
                },
            },
        [51104021] = {
            ["Content"] = "哎，莫着急谢，先听谜面。山腰悬玉钩，树杪挂银舟。圆缺妆台镜，阴晴刈麦秋。",
            ["ContentFR"] = "Doucement, écoutez d’abord l’énigme : À flanc de montagne pend un croissant de jade, au sommet des arbres flotte une barque d’argent. Pleine ou absente, miroir de coiffeuse elle se fait, claire ou voilée, elle veille sur les moissons d’automne.",
            ["DialogueId"] = 51104021,
            ["GUID"] = "7FEEFD72",
            ["LookAt"] = {
                [1] = "700327:n(700328)",
                [2] = "700326:n(700328)",
                },
            ["NextOptions"] = {
                [1] = 51104022,
                [2] = 51104024,
                [3] = 51104026,
                },
            ["SpeakNpcId"] = 700328,
            ["TalkActionId"] = {
                [1] = "700326:Talk01_End",
                },
            },
        [51104022] = {
