        [51105207] = {
            ["Camera"] = "-408.350037,74.383789,220.105469,0.00001,-11.599511,-24.20009,35.0,717.932434,false,Manual,2.8",
            ["Content"] = "怎么回事，大家都一副无精打采的样子。按照以往来说，卡米拉应该开始让大家别瘫在座位上影响生意了。",
            ["ContentFR"] = "Qu’est-ce qui se passe ? Pourquoi tout le monde a l’air si abattu ? Normalement, Camilla aurait déjà commencé à vous dire d’arrêter de traîner et de reprendre le travail.",
            ["DialogueId"] = 51105207,
            ["FacialId"] = {
                [1] = "700352:Doubt01",
                },
            ["GUID"] = "7FEFC006",
            ["LookAt"] = {
                [1] = "700352:n(700350)",
                [2] = "700349:n(700352)",
                [3] = "700350:n(700352)",
                },
            ["NextDialogue"] = 51105208,
            ["SpeakNpcId"] = 700352,
            ["TalkActionId"] = {
                [1] = "700352:Think_Start",
                },
            },
        [51105208] = {
            ["Camera"] = "-408.350037,74.383789,220.105469,0.00001,-11.599511,-24.20009,35.0,717.932434,false,Manual,2.8",
            ["Content"] = "结果就连卡米拉也懒得说话。",
            ["ContentFR"] = "Et pourtant... même Camilla ne dit rien.",
            ["DialogueId"] = 51105208,
            ["GUID"] = "7FEFC030",
            ["NextDialogue"] = 51105209,
            ["SpeakNpcId"] = 700352,
            },
        [51105209] = {
            ["Camera"] = "65.352905,-133.640625,128.195312,0.000014,-13.199456,-33.401524,35.0,191.233246,false,Manual,2.8",
            ["Content"] = "啊！我知道了，一定是银烛狂欢大家玩得太累了，所以需要休息一段时间。",
            ["ContentFR"] = "Ah ! Je sais ! Vous avez tous trop donné pendant la fête, voilà tout. Vous êtes épuisés, c’est normal ! Il vous faut un peu de repos !",
            ["DialogueId"] = 51105209,
            ["FacialId"] = {
                [1] = "700352:Confident01",
                },
            ["GUID"] = "7FEFC05A",
            ["LookAt"] = {
                [1] = "700352:n(700349)",
                },
            ["NextDialogue"] = 51105210,
            ["SpeakNpcId"] = 700352,
            ["TalkActionId"] = {
                [1] = "700352:Think_End",
                },
            },
        [51105210] = {
            ["Camera"] = "122.45166,-377.09082,180.578125,0.000048,-8.599699,81.995476,35.0,219.013687,false,Manual,2.8",
            ["Content"] = "不是的，并且恰恰相反，是因为今年的银烛狂欢由于剧院发生的意外，没有最后的收尾就匆忙结束了。",
            ["ContentFR"] = "Pas vraiment... c’est même l’inverse. Cette année, la fête s’est arrêtée brutalement à cause de l’incident au théâtre. Il n’y a même pas eu de final.",
            ["DialogueId"] = 51105210,
            ["GUID"] = "7FEFC084",
            ["LookAt"] = {
                [1] = "700349:n(700352)",
                },
            ["NextDialogue"] = 51105211,
            ["SpeakNpcId"] = 700349,
            ["TalkActionId"] = {
                [1] = "700349:Disagree",
                },
            },
        [51105211] = {
            ["Camera"] = "122.45166,-377.09082,180.578125,0.000048,-8.599699,81.995476,35.0,219.013687,false,Manual,2.8",
            ["Content"] = "就总觉得……提不起劲啊，狂欢的氛围开始没多久，就戛然而止了。这比一开始没有开始狂欢还要难受。",
            ["ContentFR"] = "Tout s’est interrompu avant que l’ambiance ne prenne vraiment. Franchement... c’est pire que si la fête n’avait jamais commencé.",
            ["DialogueId"] = 51105211,
            ["GUID"] = "7FEFC0AE",
            ["NextDialogue"] = 51105212,
            ["SpeakNpcId"] = 700349,
            },
        [51105212] = {
            ["Camera"] = "65.352905,-133.640625,128.195312,0.000014,-13.199456,-33.401524,35.0,191.233246,false,Manual,2.8",
            ["Content"] = "原来如此，也不是不能理解，就像很多时候我想要帮助别人，帮到一半才发现事情已经解决了一样，就是会很泄气！",
            ["ContentFR"] = "Je comprends... C’est comme quand je veux aider quelqu’un, et qu’à mi-chemin je découvre que tout est déjà réglé. Ça coupe toute motivation !",
            ["DialogueId"] = 51105212,
            ["FacialId"] = {
                [1] = "700352:Think02",
                },
            ["GUID"] = "7FEFC0D8",
            ["NextDialogue"] = 51105213,
            ["SpeakNpcId"] = 700352,
            },
        [51105213] = {
            ["Camera"] = "353.20105,-320.401367,139.5,0.000096,-2.398947,159.395554,35.0,253.984177,false,Manual,2.8",
            ["Content"] = "没错！就好像是最终消失了的梦中灵感、打到一半但是没有打出来的喷嚏……甚至我都想不出第三个合适的比喻来形容。",
            ["ContentFR"] = "Exactement ! Comme une idée géniale dans un rêve qui disparaît au réveil... ou un éternuement qui n’arrive jamais ! J’arrive même pas à trouver un troisième exemple.",
            ["DialogueId"] = 51105213,
            ["GUID"] = "7FEFC102",
            ["LookAt"] = {
                [1] = "700350:n(700352)",
                },
            ["NextDialogue"] = 51105214,
            ["SpeakNpcId"] = 700350,
            },
        [51105214] = {
            ["Camera"] = "353.20105,-320.401367,139.5,0.000096,-2.398947,159.395554,35.0,253.984177,false,Manual,2.8",
            ["Content"] = "总之就是，没有生机！",
            ["ContentFR"] = "Bref... tout paraît sans vie.",
            ["DialogueId"] = 51105214,
            ["GUID"] = "7FEFC12C",
            ["NextDialogue"] = 51105215,
            ["SpeakNpcId"] = 700350,
            ["TalkActionId"] = {
                [1] = "700350:Explain01_End",
                },
            },
        [51105215] = {
            ["Camera"] = "65.352905,-133.640625,128.195312,0.000014,-13.199456,-33.401524,35.0,191.233246,false,Manual,2.8",
            ["Content"] = "听起来有些严重……",
            ["ContentFR"] = "Ça a l’air plus grave que je ne le pensais...",
            ["DialogueId"] = 51105215,
            ["FacialId"] = {
                [1] = "700352:Sad01",
                },
            ["GUID"] = "7FEFC156",
            ["LookAt"] = {
                [1] = "700352:n(700350)",
                },
            ["NextDialogue"] = 51105216,
            ["SpeakNpcId"] = 700352,
            ["TalkActionId"] = {
                [1] = "700352:Think_Start",
                },
            },
        [51105216] = {
            ["Camera"] = "65.352905,-133.640625,128.195312,0.000014,-13.199456,-33.401524,35.0,191.233246,false,Manual,2.8",
            ["Content"] = "不行，我得想想办法，找人一起来帮帮忙，否则大家变不回之前正常的样子啦。",
            ["ContentFR"] = "Non, ça ne va pas du tout. Il faut absolument que je trouve une solution, sinon tout Givrelac va rester comme ça !",
            ["DialogueId"] = 51105216,
            ["GUID"] = "7FEFC180",
            ["LookAt"] = {
                [1] = "700352:n(700352)",
                },
            ["NextDialogue"] = 51105217,
            ["SpeakNpcId"] = 700352,
            ["TalkActionId"] = {
                [1] = "700352:Think_End",
                },
            },
        [51105217] = {
            ["Camera"] = "65.352905,-133.640625,128.195312,0.000014,-13.199456,-33.401524,35.0,191.233246,false,Manual,2.8",
            ["Content"] = "该找谁呢……哦！她们，找她们准没错。毕竟她们一直以来都情绪稳定，不会受任何外界影响。",
            ["ContentFR"] = "Qui pourrait m’aider... Oh ! Elles ! Bien sûr ! Elles restent toujours calmes, quoi qu’il arrive.",
            ["DialogueId"] = 51105217,
            ["FacialId"] = {
                [1] = "700352:None",
                },
            ["GUID"] = "7FEFC1AA",
            ["NextDialogue"] = 51105218,
            ["SpeakNpcId"] = 700352,
            ["TalkActionId"] = {
                [1] = "700352:Bai_Think2Confident",
                },
            },
        [51105218] = {
            ["Camera"] = "-310.544434,-605.483398,200.802734,0.000083,-9.19898,40.997597,35.0,588.773376,false,Manual,2.8",
            ["Content"] = "我只要问问她们是怎样不受外界影响，保持工作热情的，就一定能借助她们的心得，让整个冰湖城重新打起精神来。",
            ["ContentFR"] = "Si je découvre comment elles gardent leur motivation sans se laisser influencer, je pourrai redonner de l’élan à toute la cité !",
            ["DialogueId"] = 51105218,
            ["GUID"] = "7FEFC1D4",
            ["SpeakNpcId"] = 700352,
            },
        [51105301] = {
            ["Camera"] = "457.37326,-586.730225,248.960373,0.000032,-15.000139,121.598587,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "三位前辈，如何让冰湖城焕发生机，就拜托你们了！",
            ["ContentFR"] = "Vénérables aînées ! Pour redonner vie à Givrelac, je compte sur vous !",
            ["DialogueId"] = 51105301,
            ["GUID"] = "7FEFCF72",
            ["NextDialogue"] = 51105302,
            ["Scripts"] = "PlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt02/0041_story_jiaojiao_tiejiang\"},RelatedRegionId{\"210101\"}}",
            ["SpeakNpcId"] = 700352,
            },
        [51105302] = {
            ["Camera"] = "272.063049,-136.137207,110.183517,0.000049,-7.200071,139.397171,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "喔，虽然老朽只懂如何锻造，但是看到白这么热情，确实不好推辞啊。",
            ["ContentFR"] = "Oh... Même si la vieille que je suis ne connaît que l’art de la forge, face à tant d’enthousiasme, il m’est difficile de refuser.",
            ["DialogueId"] = 51105302,
            ["FacialId"] = {
                [1] = "700353:Happy02",
                },
            ["GUID"] = "7FEFCF9C",
            ["NextDialogue"] = 51105303,
            ["SpeakNpcId"] = 700353,
            },
        [51105303] = {
            ["Camera"] = "272.063049,-136.137207,110.183517,0.000049,-7.200071,139.397171,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "虽然我一直为大家在休息时提供饮品和补给，但如果所有人一直都在休息的话，那也是不对的。",
            ["ContentFR"] = "Je veille d’ordinaire à servir boissons et ravitaillement pendant les pauses... mais si tout le monde se repose sans fin, ce n’est pas mieux.",
            ["DialogueId"] = 51105303,
            ["GUID"] = "7FEFCFC6",
            ["NextDialogue"] = 51105304,
            ["SpeakNpcId"] = 700354,
            },
        [51105304] = {
            ["Camera"] = "272.063049,-136.137207,110.183517,0.000049,-7.200071,139.397171,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "嗯嗯，白这份心意很好，冰湖城在我的记录里一直是北方的都市，要是大家都一直提不起劲，我就要把记录变成北方的睡城啦。",
            ["ContentFR"] = "Mm-hmm, l’intention de Snow est louable. Dans mes chroniques, Givrelac est la grande cité du Nord... Si tout le monde manque d’énergie, je vais devoir la rebaptiser « la Dormiville du Nord ».",
            ["DialogueId"] = 51105304,
            ["GUID"] = "7FEFCFF0",
            ["NextDialogue"] = 51105305,
            ["SpeakNpcId"] = 700355,
            },
        [51105305] = {
            ["Camera"] = "31.725586,31.275146,96.110329,0.000056,-5.000033,-13.205209,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "对吧，我也觉得，所以呀，让我们一起来想想办法，让大家都振作起来吧。",
            ["ContentFR"] = "Voilà ! C’est exactement ce que je pense ! Alors trouvons ensemble un moyen de réveiller tout le monde !",
            ["DialogueId"] = 51105305,
            ["GUID"] = "7FEFD01A",
            ["NextDialogue"] = 51105306,
            ["SpeakNpcId"] = 700352,
            ["TalkActionId"] = {
                [1] = "700352:Talk02_Start",
                },
            },
        [51105306] = {
            ["Camera"] = "135.03241,-10.31543,93.88092,0.000073,-4.399932,146.59407,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "依老朽之见啊，方法很简单——",
            ["ContentFR"] = "Selon moi, la solution est simple —",
            ["DialogueId"] = 51105306,
            ["FacialId"] = {
                [1] = "700353:Happy01",
                },
            ["GUID"] = "7FEFD044",
            ["NextDialogue"] = 51105307,
            ["SpeakNpcId"] = 700353,
            },
        [51105307] = {
            ["Camera"] = "130.178741,-15.803711,93.827461,0.000077,-0.999905,121.994286,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "没有其他的方法了，那就是——",
            ["ContentFR"] = "Il n’existe qu’un seul véritable remède, à savoir —",
            ["DialogueId"] = 51105307,
            ["GUID"] = "7FEFD06E",
            ["NextDialogue"] = 51105308,
            ["SpeakNpcId"] = 700354,
            ["TalkActionId"] = {
                [1] = "700352:Talk02_End",
                },
            },
        [51105308] = {
            ["Camera"] = "132.125397,17.031494,91.702133,0.000075,-2.599946,-177.40564,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "是啊，我一下子就想到了——",
            ["ContentFR"] = "Oui, j’y ai pensé immédiatement —",
            ["DialogueId"] = 51105308,
            ["GUID"] = "7FEFD098",
            ["NextDialogue"] = 51105309,
            ["SpeakNpcId"] = 700355,
            ["TalkActionId"] = {
                [1] = "700355:Confident_Start",
                },
            },
        [51105309] = {
            ["Camera"] = "31.725586,31.275146,96.110329,0.000056,-5.000033,-13.205209,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "是什么呢！",
            ["ContentFR"] = "Lequel ?!",
            ["DialogueId"] = 51105309,
            ["GUID"] = "7FEFD0C2",
            ["NextDialogue"] = 51105310,
            ["SpeakNpcId"] = 700352,
            ["TalkActionId"] = {
                [1] = "700352:Excited01_Start",
                },
            },
        [51105310] = {
            ["Camera"] = "618.50708,-678.68042,180.93396,0.000092,-5.799923,127.191681,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "锻造！\
经商！\
冒险！",
            ["ContentFR"] = "Forger !\
Commercer !\
Explorer !",
            ["DialogueId"] = 51105310,
            ["FacialId"] = {
                [1] = "700353:Smile02",
                },
            ["GUID"] = "7FEFD0EC",
            ["NextDialogue"] = 51105311,
            ["SpeakNpcName"] = "UI_CMName_Name_SanRenTongShi",
            },
        [51105311] = {
            ["Camera"] = "31.725586,31.275146,96.110329,0.000056,-5.000033,-13.205209,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "这不是完全不一样嘛！！！",
            ["ContentFR"] = "Ce sont trois choses complètement différentes !",
            ["DialogueId"] = 51105311,
            ["FacialId"] = {
                [1] = "700352:Unhappy01",
                },
            ["GUID"] = "7FEFD116",
            ["NextDialogue"] = 51105312,
            ["SpeakNpcId"] = 700352,
            ["TalkActionId"] = {
                [1] = "700352:Excited01_End",
                },
            },
        [51105312] = {
            ["Camera"] = "429.908936,-169.867676,216.608871,0.000088,-20.19973,151.389633,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "并且与其说是方法，不如说是三位前辈各自擅长的事情！",
            ["ContentFR"] = "Et ce ne sont pas des solutions, mais simplement ce que chacune de vous sait faire !",
            ["DialogueId"] = 51105312,
            ["GUID"] = "7FEFD140",
            ["NextDialogue"] = 51105313,
            ["SpeakNpcId"] = 700352,
            ["TalkActionId"] = {
                [1] = "700352:Sigh_Start",
                },
            },
        [51105313] = {
            ["Camera"] = "214.145203,-52.911133,124.187378,0.000093,-10.999684,148.988251,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "哦？这确实是出乎我的意料之外。",
            ["ContentFR"] = "Oh ? Voilà qui est inattendu.",
            ["DialogueId"] = 51105313,
            ["FacialId"] = {
                [1] = "700353:Shock01",
                },
            ["GUID"] = "7FEFD16A",
            ["NextDialogue"] = 51105314,
            ["SpeakNpcId"] = 700353,
            },
        [51105314] = {
            ["Camera"] = "214.145203,-52.911133,124.187378,0.000093,-10.999684,148.988251,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我还以为你们俩和我想的完全一样。",
            ["ContentFR"] = "Je pensais pourtant que nous avions exactement la même idée.",
            ["DialogueId"] = 51105314,
            ["GUID"] = "7FEFD194",
            ["LookAt"] = {
                [1] = "700354:n(700353)",
                },
            ["NextDialogue"] = 51105315,
            ["SpeakNpcId"] = 700355,
            },
        [51105315] = {
            ["Camera"] = "214.145203,-52.911133,124.187378,0.000093,-10.999684,148.988251,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "……嗯，原来你们不来卖东西是因为真的觉得经商不是最重要的，有点失望。",
            ["ContentFR"] = "... Donc si vous ne vendez rien, c’est parce que vous pensez vraiment que le commerce n’est pas essentiel. Je suis un peu déçue.",
            ["DialogueId"] = 51105315,
            ["GUID"] = "7FEFD1BE",
            ["LookAt"] = {
                [1] = "700355:n(700353)",
                },
            ["NextDialogue"] = 51105316,
            ["SpeakNpcId"] = 700354,
            },
        [51105316] = {
            ["Camera"] = "31.725586,31.275146,96.110329,0.000056,-5.000033,-13.205209,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "停，停一下三位前辈。这样吧，既然你们各自都觉得自己在干的事情能够让人振奋精神，那，那我来挨个试一遍好了。",
            ["ContentFR"] = "Attendez, attendez ! Bon... Puisque chacune de vous est convaincue que son activité redonne de l’énergie, alors je vais tout essayer, une par une !",
            ["DialogueId"] = 51105316,
            ["GUID"] = "7FEFD1E8",
            ["LookAt"] = {
                [1] = "700354:n(700352)",
                [2] = "700355:n(700352)",
                },
            ["NextDialogue"] = 51105317,
            ["SpeakNpcId"] = 700352,
            ["TalkActionId"] = {
                [1] = "700352:Sigh_End",
                },
            },
        [51105317] = {
            ["Camera"] = "-202.37793,93.230225,130.826981,0.000078,-8.999676,-11.213411,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "好，那么就从我这里开始吧，和老朽一起挥动铁锤，一定会打起精神的。",
            ["ContentFR"] = "Allons-y, commençons par moi. Prends un marteau, et tu verras : l’ardeur reviendra d’elle-même.",
            ["DialogueId"] = 51105317,
            ["FacialId"] = {
                [1] = "700353:Confident02",
                },
            ["GUID"] = "7FEFD212",
            ["NextDialogue"] = 51105318,
            ["SpeakNpcId"] = 700353,
            },
        [51105318] = {
            ["Camera"] = "-202.37793,93.230225,130.826981,0.000078,-8.999676,-11.213411,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "好，铁匠前辈，我之前没有干过这种活，你教一教我。",
            ["ContentFR"] = "D’accord. Je n’ai jamais fait ça... Vous pouvez m’apprendre ?",
            ["DialogueId"] = 51105318,
            ["FacialId"] = {
                [1] = "700353:CM_Idle",
                },
            ["GUID"] = "7FEFD23C",
            ["NextDialogue"] = 51105319,
            ["SpeakNpcId"] = 700352,
            ["TalkActionId"] = {
                [1] = "700352:AgreeHead",
                },
            },
        [51105319] = {
            ["Camera"] = "-202.37793,93.230225,130.826981,0.000078,-8.999676,-11.213411,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "简单的简单的，拿起铁锤，深吸一口气，砸——",
            ["ContentFR"] = "C’est très simple. Prends le marteau, inspire profondément... et frappe —",
            ["DialogueId"] = 51105319,
            ["FacialId"] = {
                [1] = "700353:Smile02",
                },
            ["GUID"] = "7FEFD266",
            ["NextDialogue"] = 51105320,
            ["SpeakNpcId"] = 700353,
            },
        [51105320] = {
            ["Camera"] = "-202.37793,93.230225,130.826981,0.000078,-8.999676,-11.213411,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "一边砸，一遍想着别人看到你锻造出的东西满意地露出笑容，就会产生动力。",
            ["ContentFR"] = "En imaginant le sourire de ceux qui verront ton œuvre achevée. C’est ainsi que naît la motivation.",
            ["DialogueId"] = 51105320,
            ["GUID"] = "7FEFD290",
            ["NextDialogue"] = 51105321,
            ["SpeakNpcId"] = 700353,
            },
        [51105321] = {
            ["Camera"] = "-202.37793,93.230225,130.826981,0.000078,-8.999676,-11.213411,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "并且呀，有节奏地敲击铁锤，看着火花迸出，每锤一次都会涌现出成就感。",
            ["ContentFR"] = "Et puis, frapper avec rythme, voir jaillir les étincelles... Chaque coup apporte son lot de satisfaction.",
            ["DialogueId"] = 51105321,
            ["GUID"] = "7FEFD2BA",
            ["NextDialogue"] = 51105322,
            ["SpeakNpcId"] = 700353,
            },
        [51105322] = {
            ["Camera"] = "-5.819641,123.071289,115.489243,0.000093,-10.599607,-37.011742,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "嗯……好的，我明白了，总的来说就是，挥舞铁锤会让人感到振奋。",
            ["ContentFR"] = "Hmm... je crois comprendre. En résumé, manier un marteau rend enthousiaste.",
            ["DialogueId"] = 51105322,
            ["FacialId"] = {
                [1] = "700352:Happy02",
                },
            ["GUID"] = "7FEFD2E4",
            ["NextDialogue"] = 51105323,
            ["SpeakNpcId"] = 700352,
            ["TalkActionId"] = {
                [1] = "700352:SpecialConfident_Start",
                },
            },
        [51105323] = {
            ["Camera"] = "-5.819641,123.071289,115.489243,0.000093,-10.599607,-37.011742,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "那么让白来试一试……呜哇，好重……",
            ["ContentFR"] = "Allez, c’est mon tour... Ouaaah ! C’est lourd !",
            ["DialogueId"] = 51105323,
            ["FacialId"] = {
                [1] = "700352:Shock02",
                },
            ["GUID"] = "7FEFD30E",
            ["NextDialogue"] = 51105324,
            ["Scripts"] = "PlayNormalSound{EventPath{\"event:/sfx/common/story/jiaojiao/hammer\"},PlayAs2D{true}}",
            ["SpeakNpcId"] = 700352,
            ["TalkActionId"] = {
                [1] = "700352:SpecialConfident_End",
                },
            },
        [51105324] = {
            ["Content"] = "白举起铁锤，用力挥舞了起来。",
            ["ContentFR"] = "Snow lève le marteau et l’abat de toutes ses forces.",
            ["DialogueId"] = 51105324,
            ["GUID"] = "7FEFD338",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 51105325,
            },
        [51105325] = {
            ["Camera"] = "31.725586,31.275146,96.110329,0.000056,-5.000033,-13.205209,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "嗯，确实抡起大锤来会让人感觉力量从身体里涌出……",
            ["ContentFR"] = "Oh... C’est vrai... On sent la puissance jaillir du corps en maniant un tel marteau...",
            ["DialogueId"] = 51105325,
            ["FacialId"] = {
                [1] = "700352:Confident02",
                },
            ["GUID"] = "7FEFD362",
            ["NextDialogue"] = 51105326,
            ["SpeakNpcId"] = 700352,
            ["TalkActionId"] = {
                [1] = "700352:SpecialHappy_Start",
                },
            },
        [51105326] = {
            ["Camera"] = "31.725586,31.275146,96.110329,0.000056,-5.000033,-13.205209,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "要不就号召大家一起来打铁锻造吧，一定能感到快乐的！",
            ["ContentFR"] = "Peut-être que si tout le monde forgeait ensemble, ils retrouveraient le sourire !",
            ["DialogueId"] = 51105326,
            ["GUID"] = "7FEFD38C",
            ["NextDialogue"] = 51105327,
            ["SpeakNpcId"] = 700352,
            },
        [51105327] = {
            ["Content"] = "随着白挥舞锤子的时间越来越长，她的速度也逐渐变慢……",
            ["ContentFR"] = "Mais à mesure que Snow continue, ses gestes se font de plus en plus lents...",
            ["DialogueId"] = 51105327,
            ["GUID"] = "7FEFD3B6",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 51105328,
            ["TalkActionId"] = {
                [1] = "700352:SpecialHappy_End",
                },
            },
        [51105328] = {
            ["Camera"] = "31.725586,31.275146,96.110329,0.000056,-5.000033,-13.205209,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "好累……我挥不动了……",
            ["ContentFR"] = "Je... suis épuisée... Je n’y arrive plus...",
            ["DialogueId"] = 51105328,
            ["FacialId"] = {
                [1] = "700352:Sad03",
                },
            ["GUID"] = "7FEFD3E0",
            ["NextDialogue"] = 51105329,
            ["SpeakNpcId"] = 700352,
            ["TalkActionId"] = {
                [1] = "700352:BaiTX_Story_Cry_Start",
                },
            },
        [51105329] = {
            ["Camera"] = "-1.381409,25.406982,97.682739,0.000088,-5.599846,-10.014951,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "不行，我累坏了，我必须立刻睡觉……晚安……",
            ["ContentFR"] = "Non... c’est trop... Je dois dormir tout de suite... Bonne nuit...",
            ["DialogueId"] = 51105329,
            ["GUID"] = "7FEFD40A",
            ["NextDialogue"] = 51105330,
            ["SpeakNpcId"] = 700352,
            },
        [51105330] = {
            ["Camera"] = "-1.381409,25.406982,97.682739,0.000088,-5.599846,-10.014951,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "并且我得出一个结论，这种方法不太适合……让大家振奋精神。",
            ["ContentFR"] = "Et je peux déjà tirer une conclusion... Cette méthode n’est pas vraiment adaptée pour redonner de l’énergie à tout le monde...",
            ["DialogueId"] = 51105330,
            ["FacialId"] = {
                [1] = "700352:Syouganai01",
                },
            ["GUID"] = "7FEFD434",
            ["NextDialogue"] = 51105331,
            ["SpeakNpcId"] = 700352,
            },
        [51105331] = {
            ["Camera"] = "203.842834,-65.611328,97.294655,0.000084,-5.799711,133.783813,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "所以啊，这样是不行的，过度地劳动只会让大家变得更加疲惫。",
            ["ContentFR"] = "Voilà pourquoi cela ne fonctionne pas. Travailler à l’excès ne fait qu’aggraver la fatigue.",
            ["DialogueId"] = 51105331,
            ["GUID"] = "7FEFD45E",
            ["NextDialogue"] = 51105332,
            ["SpeakNpcId"] = 700354,
            },
        [51105332] = {
            ["Camera"] = "203.842834,-65.611328,97.294655,0.000084,-5.799711,133.783813,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "本来狂欢节就是为了让大家休息才设立的，敲敲打打的声音只适合作为狂欢节的背景音乐。",
            ["ContentFR"] = "La fête existait pour permettre aux gens de se reposer. Le bruit des marteaux devrait rester une musique de fond, pas l’activité principale.",
            ["DialogueId"] = 51105332,
            ["GUID"] = "7FEFD488",
            ["NextDialogue"] = 51105333,
            ["SpeakNpcId"] = 700354,
            },
        [51105333] = {
            ["Camera"] = "390.128845,-909.648804,240.500732,0.000087,-4.799129,103.981491,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "是这样吗？哎呀，能做背景音乐也很好啦，那么接下来该你啦。让我们见识见识什么叫做经商能够带来活力。",
            ["ContentFR"] = "Vraiment ? Eh bien, servir de musique d’ambiance me va très bien. À ton tour, alors. Voyons comment le commerce peut insuffler de la vitalité.",
            ["DialogueId"] = 51105333,
            ["FacialId"] = {
                [1] = "700353:Happy01",
                },
            ["GUID"] = "7FEFD4B2",
            ["NextDialogue"] = 51105334,
            ["SpeakNpcId"] = 700353,
            },
        [51105334] = {
            ["Camera"] = "390.128845,-909.648804,240.500732,0.000087,-4.799129,103.981491,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "哼哼，我看你是一直待在屋内打铁，根本不知道外面发生过什么。",
            ["ContentFR"] = "<I>Hmpf. </>Tu passes trop de temps enfermée à forger. Tu n’as aucune idée de ce qui se passe dehors.",
            ["DialogueId"] = 51105334,
            ["GUID"] = "7FEFD4DC",
            ["NextDialogue"] = 51105335,
            ["SpeakNpcId"] = 700354,
            },
        [51105335] = {
            ["Camera"] = "390.128845,-909.648804,240.500732,0.000087,-4.799129,103.981491,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "跟我来吧，顺便把睡着的白给一起抬出去。",
            ["ContentFR"] = "Suivez-moi. Et tant qu’à faire, emportez aussi Snow... elle dort déjà.",
            ["DialogueId"] = 51105335,
            ["GUID"] = "7FEFD506",
            ["SpeakNpcId"] = 700354,
            },
        [51105401] = {
            ["Camera"] = "-1078.888672,-652.357727,332.403564,0.000018,-12.600039,32.600487,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "咦？我怎么在广场上啦？难道是因为我挥舞锤子的力气太大，把自己甩飞出去啦？",
            ["ContentFR"] = "Hein ? Pourquoi est-ce que je me retrouve sur la place ? Ne me dis pas que j’ai frappé trop fort et que je me suis moi-même projetée jusqu’ici...",
            ["DialogueId"] = 51105401,
            ["FacialId"] = {
                [1] = "700352:Shock02",
                },
            ["GUID"] = "7FEFDFDA",
            ["NextDialogue"] = 51105402,
            ["SpeakNpcId"] = 700352,
            ["TalkActionId"] = {
                [1] = "700352:SpecialLook01_Start",
                },
            ["TurnTo"] = {
                [1] = "700360:n(700352)",
                },
            },
        [51105402] = {
            ["Camera"] = "-1078.888672,-652.357727,332.403564,0.000018,-12.600039,32.600487,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "那你们没事吧？有没有受伤？",
            ["ContentFR"] = "Et vous, ça va ? Personne n’est blessé, au moins ?",
            ["DialogueId"] = 51105402,
            ["GUID"] = "7FEFE004",
            ["LookAt"] = {
                [1] = "700352:n(700355)",
                },
            ["NextDialogue"] = 51105403,
            ["SpeakNpcId"] = 700352,
            },
        [51105403] = {
            ["Camera"] = "-158.35083,-438.890656,112.984375,0.000041,-9.199888,76.798775,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "不是啦，只是刚刚你太用力，累坏了而已。",
            ["ContentFR"] = "Non, rassure-toi. Tu as simplement trop forcé... et tu t’es épuisée.",
            ["DialogueId"] = 51105403,
            ["GUID"] = "7FEFE02E",
            ["LookAt"] = {
                [1] = "700354:n(700352)",
                },
            ["NextDialogue"] = 51105404,
            ["SpeakNpcId"] = 700354,
            ["TurnTo"] = {
                [1] = "700352:n(700354)",
                },
            },
        [51105404] = {
            ["Camera"] = "-255.641846,4.335266,87.516602,0.000049,-5.799889,-10.203091,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "原来是这样……不过我刚刚要干什么来着。",
            ["ContentFR"] = "Je vois... Mais alors... qu’est-ce que je devais faire, déjà ?",
            ["DialogueId"] = 51105404,
            ["FacialId"] = {
                [1] = "700352:CM_Idle",
                },
            ["GUID"] = "7FEFE058",
            ["NextDialogue"] = 51105405,
            ["SpeakNpcId"] = 700352,
            ["TalkActionId"] = {
                [1] = "700352:Think_Start",
                },
            },
        [51105405] = {
            ["Camera"] = "19.978271,-270.103577,92.347168,0.000058,-6.999878,105.596878,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "是打算用经商来让冰湖城重新焕发生机哦。",
            ["ContentFR"] = "Tu comptais redonner de l’élan à Givrelac par le commerce.",
            ["DialogueId"] = 51105405,
            ["GUID"] = "7FEFE082",
            ["NextDialogue"] = 51105406,
            ["SpeakNpcId"] = 700354,
            },
        [51105406] = {
            ["Camera"] = "-255.641846,4.335266,87.516602,0.000049,-5.799889,-10.203091,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "哦对，想起来了，那么到底要怎么做，侍者前辈，请教教我！",
            ["ContentFR"] = "Ah oui ! Ça me revient ! Alors... comment on s’y prend, exactement ? S’il vous plaît, expliquez-moi !",
            ["DialogueId"] = 51105406,
            ["GUID"] = "7FEFE0AC",
            ["NextDialogue"] = 51105407,
            ["SpeakNpcId"] = 700352,
            ["TalkActionId"] = {
                [1] = "700352:Excited01_Start",
                },
            },
        [51105407] = {
            ["Camera"] = "19.978271,-270.103577,92.347168,0.000058,-6.999878,105.596878,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "唔，说起来其实也简单，就是制造商机，制造悬念，制造潮流，只要吊足大家的胃口，就能够唤出大家的热情。",
            ["ContentFR"] = "Eh bien, en réalité, c’est assez simple. Il faut créer des opportunités, entretenir le mystère, lancer une tendance... Quand on sait éveiller le désir, l’enthousiasme suit naturellement.",
            ["DialogueId"] = 51105407,
            ["GUID"] = "7FEFE0D6",
            ["NextDialogue"] = 51105408,
            ["SpeakNpcId"] = 700354,
            },
        [51105408] = {
            ["Camera"] = "19.978271,-270.103577,92.347168,0.000058,-6.999878,105.596878,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "而一旦想要拥有，想购买的情绪充斥着心胸，那么人们就会为此好好工作。这样就能让人们焕发活力。",
            ["ContentFR"] = "Et lorsque l’envie de posséder, d’acheter, emplit le cœur, les gens se remettent à travailler avec entrain. C’est ainsi que l’énergie renaît.",
            ["DialogueId"] = 51105408,
            ["GUID"] = "7FEFE100",
            ["NextDialogue"] = 51105409,
            ["SpeakNpcId"] = 700354,
            ["TalkActionId"] = {
                [1] = "700352:Excited01_End",
                },
            },
        [51105409] = {
            ["Camera"] = "-698.29834,-1511.247803,548.52002,0.000096,-3.199643,-79.40123,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "话不多说，比如我这里就有准备好的银烛狂欢终场限定饮品，每购买一杯就能获得一个印章，",
            ["ContentFR"] = "Regarde, par exemple : j’ai préparé ici une boisson exclusive de clôture de la Fête de la Chandelle d’Argent. Chaque achat donne droit à un tampon.",
            ["DialogueId"] = 51105409,
            ["GUID"] = "7FEFE12A",
            ["NextDialogue"] = 51105410,
            ["SpeakNpcId"] = 700354,
            },
        [51105410] = {
            ["Camera"] = "-60.891846,1.497742,78.666992,0.0,-1.200105,-41.399494,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "集齐五枚印章后可以获得限定款银色烛台一个，烛台总共有五种颜色款式还有斑斓之黑隐藏款。",
            ["ContentFR"] = "En réunissant cinq tampons, on obtient un chandelier d’argent en édition limitée. Il existe cinq couleurs... et une version noire irisée secrète.",
            ["DialogueId"] = 51105410,
            ["FacialId"] = {
                [1] = "700352:Shock02",
                },
            ["GUID"] = "7FEFE154",
            ["NextDialogue"] = 51105411,
            ["SpeakNpcId"] = 700354,
            },
        [51105411] = {
            ["Camera"] = "-211.238281,484.548462,133.915771,0.000002,-6.80019,-72.198151,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "来吧，白，吆喝起来！只要来买的人足够多，那么冰湖城就一定会重新焕发活力的！",
            ["ContentFR"] = "Allez, Snow, à toi de jouer ! Si suffisamment de gens répondent à l’appel, Givrelac retrouvera sa vitalité !",
            ["DialogueId"] = 51105411,
            ["GUID"] = "7FEFE17E",
            ["NextDialogue"] = 51105412,
            ["SpeakNpcId"] = 700354,
            },
        [51105412] = {
            ["Camera"] = "-165.009277,12.943481,86.168457,0.000005,-5.000094,-19.198158,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "噢！好耶！只要能够让冰湖城重新焕发生机我什么都会做的！",
            ["ContentFR"] = "Oh ! D’accord ! S’il faut crier pour redonner vie à la cité, alors je crierai !",
            ["DialogueId"] = 51105412,
            ["FacialId"] = {
                [1] = "700352:Happy02",
                },
            ["GUID"] = "7FEFE1A8",
            ["NextDialogue"] = 51105413,
            ["SpeakNpcId"] = 700352,
            },
        [51105413] = {
            ["Camera"] = "-377.683594,-687.164856,156.533447,0.000002,-4.600002,62.002022,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "银烛狂欢终场限定饮品！购入获得限定款银色烛台！还有隐藏款！",
            ["ContentFR"] = "Boisson exclusive de clôture de la Fête de la Chandelle d’Argent ! Achetez-en une et recevez un chandelier d’argent en édition limitée ! Et il existe même une version secrète !",
            ["DialogueId"] = 51105413,
            ["GUID"] = "7FEFE1D2",
            ["LookAt"] = {
                [1] = "700352:n(700360)",
                },
            ["NextDialogue"] = 51105414,
            ["SpeakNpcId"] = 700352,
            ["TalkActionId"] = {
                [1] = "700352:BaiTX_Story_Shout_Start",
                },
            },
        [51105414] = {
            ["Camera"] = "-377.683594,-687.164856,156.533447,0.000002,-4.600002,62.002022,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "只卖一天，今天卖完等到明年，快来看呀！",
            ["ContentFR"] = "Disponible un seul jour ! Aujourd’hui seulement ! Sinon, il faudra attendre l’année prochaine ! Venez voir !",
            ["DialogueId"] = 51105414,
            ["GUID"] = "7FEFE1FC",
            ["LookAt"] = {
                [1] = "700352:n(700355)",
                },
            ["NextDialogue"] = 51105415,
            ["SpeakNpcId"] = 700352,
            },
        [51105415] = {
            ["Camera"] = "-32.104248,371.151123,518.605469,0.000011,-3.999909,-83.395515,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "侍者皎皎与白的吆喝在广场上交织，不少人驻足观看，但随即摇摇头离去。",
            ["ContentFR"] = "Les appels de Luno, la servante, et de Snow se mêlent sur la place. De nombreux passants s’arrêtent, observent... puis secouent la tête avant de repartir.",
            ["DialogueId"] = 51105415,
            ["GUID"] = "7FEFE226",
            ["NextDialogue"] = 51105416,
            },
        [51105416] = {
            ["Camera"] = "-107.829102,-165.86377,117.956055,0.000013,-16.999786,49.203773,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "唔……会不会是吆喝的声音不够大……",
            ["ContentFR"] = "Hmm... Peut-être que je ne crie pas assez fort... ?",
            ["DialogueId"] = 51105416,
            ["FacialId"] = {
                [1] = "700352:Sad03",
                },
            ["GUID"] = "7FEFE250",
            ["NextDialogue"] = 51105417,
            ["SpeakNpcId"] = 700352,
            ["TalkActionId"] = {
                [1] = "700352:BaiTX_Story_Shout_End",
                },
            },
        [51105417] = {
            ["Camera"] = "-107.829102,-165.86377,117.956055,0.000013,-16.999786,49.203773,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "不是的……只是听了感觉有一些内心疲惫。",
            ["ContentFR"] = "Non... ce n’est pas ça. C’est juste que... à l’entendre, ça ne me donne plus vraiment envie.",
            ["DialogueId"] = 51105417,
            ["FacialId"] = {
                [1] = "700352:CM_Idle",
                },
            ["GUID"] = "7FEFE27A",
            ["NextDialogue"] = 51105418,
            ["SpeakNpcId"] = 700360,
            ["TurnTo"] = {
                [1] = "700352:n(700360);700355:n(700360)",
                },
            },
        [51105418] = {
            ["Camera"] = "-154.719238,-781.528137,203.725098,0.000044,-10.999541,77.402351,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "咦？为什么？我们准备的饮料也很可口，烛台也很精致，为什么会疲惫呢？",
            ["ContentFR"] = "Comment ça ? Les boissons sont délicieuses, les chandeliers raffinés... Pourquoi dire que l’envie n’y est plus ?",
            ["DialogueId"] = 51105418,
            ["FacialId"] = {
                [1] = "700352:Shock01",
                },
            ["GUID"] = "7FEFE2A4",
            ["LookAt"] = {
                [1] = "700354:n(700360)",
                },
            ["NextDialogue"] = 51105419,
            ["SpeakNpcId"] = 700354,
            ["TalkActionId"] = {
                [1] = "700352:Shock_Start",
                },
            },
        [51105419] = {
            ["Camera"] = "-59.487549,298.752197,127.998779,0.000024,-5.399681,-87.594635,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "因为我家里已经有七八个烛台啦、还有十几个银烛狂欢纪念牌、二十多个银烛狂欢纪念徽章。",
            ["ContentFR"] = "Parce que chez moi, j’ai déjà sept ou huit chandeliers... Sans compter une dizaine de plaques commémoratives et plus de vingt insignes de la fête.",
            ["DialogueId"] = 51105419,
            ["GUID"] = "7FEFE2CE",
            ["NextDialogue"] = 51105420,
            ["SpeakNpcId"] = 700360,
            ["TalkActionId"] = {
                [1] = "700360:Sigh_Start",
                },
            },
        [51105420] = {
            ["Camera"] = "-59.487549,298.752197,127.998779,0.000024,-5.399681,-87.594635,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "银烛狂欢期间，城里的商家就和约好了一样，每一家都在推出什么银烛狂欢特制纪念品，偏偏每一家都做得很好。",
            ["ContentFR"] = "Pendant la Fête de la Chandelle d’Argent, tous les commerçants semblaient s’être donné le mot. Chaque boutique proposait ses objets commémoratifs... et ils étaient tous réussis.",
            ["DialogueId"] = 51105420,
            ["FacialId"] = {
                [1] = "700352:CM_Idle",
                },
            ["GUID"] = "7FEFE2F8",
            ["NextDialogue"] = 51105421,
            ["SpeakNpcId"] = 700360,
            ["TalkActionId"] = {
                [1] = "700352:Shock_End",
                },
            },
        [51105421] = {
            ["Camera"] = "-59.487549,298.752197,127.998779,0.000024,-5.399681,-87.594635,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "大家一不留神，就买了好多……所以现在都是钱包空空，后悔花了很多钱的状态。",
            ["ContentFR"] = "Sans s’en rendre compte, on a trop acheté... Et maintenant, les portefeuilles sont vides, et les regrets bien présents.",
            ["DialogueId"] = 51105421,
            ["GUID"] = "7FEFE322",
            ["NextDialogue"] = 51105422,
            ["SpeakNpcId"] = 700360,
            },
        [51105422] = {
            ["Camera"] = "-98.028564,-609.098694,176.426514,0.000047,-11.999569,80.00383,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "所以在银烛狂欢结束的时候看到你们还在这样叫卖，反而让我感到后悔和痛苦……",
            ["ContentFR"] = "Alors vous entendre vendre encore, une fois la fête terminée... Ça ravive surtout la culpabilité et l’amertume.",
            ["DialogueId"] = 51105422,
            ["GUID"] = "7FEFE34C",
            ["NextDialogue"] = 51105423,
            ["SpeakNpcId"] = 700360,
            ["TalkActionId"] = {
                [1] = "700360:Sigh_End",
                },
            },
        [51105423] = {
            ["Camera"] = "-98.028564,-609.098694,176.426514,0.000047,-11.999569,80.00383,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "对不起，我……我不是故意的。",
            ["ContentFR"] = "Oh... Je suis désolée... Je ne voulais pas...",
            ["DialogueId"] = 51105423,
            ["GUID"] = "7FEFE376",
            ["NextDialogue"] = 51105424,
            ["SpeakNpcId"] = 700352,
            },
        [51105424] = {
            ["Camera"] = "-32.595215,-176.400818,129.296143,0.000064,-0.199523,-85.395256,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "没有责怪你的意思啦，相反，我很感激你们能为了大家重新打起精神来能尝试各种方法。",
            ["ContentFR"] = "Ne vous en faites pas. Ce n’est pas un reproche. Au contraire, on apprécie vraiment que vous essayiez tant de choses pour nous redonner le sourire.",
            ["DialogueId"] = 51105424,
            ["FacialId"] = {
                [1] = "700360:Smile01",
                },
            ["GUID"] = "7FEFE3A0",
            ["NextDialogue"] = 51105425,
            ["SpeakNpcId"] = 700360,
            ["TalkActionId"] = {
                [1] = "700360:Explain01_Start",
                },
            },
        [51105425] = {
            ["Camera"] = "-32.595215,-176.400818,129.296143,0.000064,-0.199523,-85.395256,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "请继续加油，我相信你们一定可以的！",
            ["ContentFR"] = "Courage. Je suis sûr que vous trouverez la solution.",
            ["DialogueId"] = 51105425,
            ["GUID"] = "7FEFE3CA",
            ["NextDialogue"] = 51105426,
            ["SpeakNpcId"] = 700360,
            ["TalkActionId"] = {
                [1] = "700360:Explain01_End",
                [2] = "700352:BaiTX_Story_RubForehead_End",
                },
            },
        [51105426] = {
            ["Camera"] = "-234.385498,-112.179077,73.116211,0.000055,-1.799529,18.207968,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "好的！那么探险家前辈，最后的希望，靠你了！",
            ["ContentFR"] = "Oui ! Alors c’est décidé ! Luno, l’exploratrice, tout repose sur vous !",
            ["DialogueId"] = 51105426,
            ["GUID"] = "7FEFE3F4",
            ["NextDialogue"] = 51105427,
            ["SpeakNpcId"] = 700352,
            ["TurnTo"] = {
                [1] = "700352:n(700355);700355:n(700352)",
                },
            },
        [51105427] = {
            ["Camera"] = "18.141846,-75.220642,83.042236,0.000054,-7.999667,171.60376,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "嗯，确实也该是我出场的时候了。",
            ["ContentFR"] = "Hmm. Il est vrai que le moment est venu pour moi d’intervenir.",
            ["DialogueId"] = 51105427,
            ["GUID"] = "7FEFE41E",
            ["LookAt"] = {
                [1] = "700354:n(700355)",
                },
            ["NextDialogue"] = 51105428,
            ["SpeakNpcId"] = 700355,
            ["TalkActionId"] = {
                [1] = "700355:Agree",
                },
            },
        [51105428] = {
            ["Camera"] = "18.141846,-75.220642,83.042236,0.000054,-7.999667,171.60376,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "那么我的答案是冒险——",
            ["ContentFR"] = "Ma réponse est simple : l’aventure.",
            ["DialogueId"] = 51105428,
            ["GUID"] = "7FEFE448",
            ["NextDialogue"] = 51105429,
            ["SpeakNpcId"] = 700355,
            },
        [51105429] = {
            ["Camera"] = "122.499512,-108.44696,348.161377,0.000066,2.39976,-124.394104,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "银烛狂欢，大家都在冰湖城内狂欢，那么我有充分的理由认为大家是在城里憋坏了，是城墙让大家的心情压抑。",
            ["ContentFR"] = "Pendant la Fête de la Chandelle d’Argent, tout le monde est resté à festoyer dans Givrelac. Il est donc logique de penser que les gens ont fini par étouffer entre ces murs.",
            ["DialogueId"] = 51105429,
            ["GUID"] = "7FEFE472",
            ["NextDialogue"] = 51105430,
            ["SpeakNpcId"] = 700355,
            ["TalkActionId"] = {
                [1] = "700355:Explain02_Start",
                },
            },
        [51105430] = {
            ["Camera"] = "-5.647949,-37.965942,63.306885,0.000058,-1.398379,-172.39415,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "所以，如果大家都能去冰湖城外，与自然亲近，呼吸新鲜空气，心情就一定会变好的！",
            ["ContentFR"] = "Si chacun sort de la ville, se rapproche de la nature, respire l’air libre... Alors l’esprit s’allégera à coup sûr.",
            ["DialogueId"] = 51105430,
            ["GUID"] = "7FEFE49C",
            ["NextDialogue"] = 51105431,
            ["SpeakNpcId"] = 700355,
            },
        [51105431] = {
            ["Camera"] = "-234.385498,-112.179077,73.116211,0.000055,-1.799529,18.207968,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "哦！听起来很有道理。那么，是不是找到泪湖边上风景最好的地方，让大家去那里欣赏风景就可以了！",
            ["ContentFR"] = "Oh ! Ça paraît très sensé ! Dans ce cas, il suffit de trouver un endroit magnifique près du Lac du Deuil, et d’y emmener tout le monde, non ?",
            ["DialogueId"] = 51105431,
            ["GUID"] = "7FEFE4C6",
            ["NextDialogue"] = 51105432,
            ["SpeakNpcId"] = 700352,
            ["TalkActionId"] = {
                [1] = "700352:RaiseHand_Start",
                },
            },
        [51105432] = {
            ["Camera"] = "-87.131836,-425.705322,92.41748,0.000067,-8.799558,88.407211,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "不错，白很聪明嘛，已经完全知道我想要做什么了。",
            ["ContentFR"] = "Exactement. Tu comprends vite, Snow. Tu sais déjà ce que j’ai en tête.",
            ["DialogueId"] = 51105432,
            ["GUID"] = "7FEFE4F0",
            ["NextDialogue"] = 51105433,
            ["SpeakNpcId"] = 700355,
            ["TalkActionId"] = {
                [1] = "700355:Explain02_End",
                [2] = "700352:RaiseHand_End",
                },
            },
        [51105433] = {
            ["Camera"] = "-123.174316,-60.997009,67.639648,0.000072,4.20047,5.206679,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "好，那我们出发！",
            ["ContentFR"] = "Parfait ! Alors, en route !",
            ["DialogueId"] = 51105433,
            ["FacialId"] = {
                [1] = "700352:Happy02",
                },
            ["GUID"] = "7FEFE51A",
            ["SpeakNpcId"] = 700352,
            ["TalkActionId"] = {
                [1] = "700352:SpecialHappy_Start",
                },
            },
        [51105501] = {
            ["Camera"] = "913.757812,-865.021484,276.827148,0.00001,-4.399905,137.398376,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "嗯，就是这里了，视野开阔没有拘束，适合让大家来放松身心。",
            ["ContentFR"] = "Oui, c’est ici. L’espace est vaste, sans entraves... parfait pour se détendre et respirer.",
            ["DialogueId"] = 51105501,
            ["GUID"] = "7FEFF042",
            ["NextDialogue"] = 51105502,
            ["SpeakNpcId"] = 700352,
            ["TalkActionId"] = {
                [1] = "700356:Avoid",
                [2] = "700357:Avoid",
                },
            },
        [51105502] = {
            ["Camera"] = "913.757812,-865.021484,276.827148,0.00001,-4.399905,137.398376,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "没错，每当我来到这里，都觉得内心被治愈了一样，所以我相信其他人也一定能重新打起精神来的。",
            ["ContentFR"] = "Je suis d’accord. À chaque fois que je viens ici, j’ai l’impression que mon cœur se régénère. Je suis certaine que les autres ressentiraient la même chose.",
            ["DialogueId"] = 51105502,
            ["GUID"] = "7FEFF06C",
            ["NextDialogue"] = 51105503,
            ["SpeakNpcId"] = 700355,
            },
        [51105503] = {
            ["Camera"] = "-157.613281,-2017.939453,386.613281,0.000007,-21.999744,146.197006,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "救命啊，救命——",
            ["ContentFR"] = "À l’aide ! À l’aide—",
            ["DialogueId"] = 51105503,
            ["GUID"] = "7FEFF096",
            ["NextDialogue"] = 51105504,
            ["SpeakNpcName"] = "UI_CMName_Name_FuJinChuanLai",
            },
        [51105504] = {
            ["Camera"] = "-292.320312,132.621094,98.302734,0.000022,-9.399808,-35.402294,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "好像是有人在呼救，我们过去看看。",
            ["ContentFR"] = "Quelqu’un appelle au secours. Allons voir.",
            ["DialogueId"] = 51105504,
            ["GUID"] = "7FEFF0C0",
            ["SpeakNpcId"] = 700355,
            ["TalkActionId"] = {
                [1] = "700355:Explain01_Start",
                },
            },
        [51105505] = {
            ["Camera"] = "468.472656,-386.455078,184.522461,0.000007,-11.999959,151.198257,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "谢谢，谢谢救了我们。",
            ["ContentFR"] = "Merci... merci de nous avoir sauvés...",
            ["DialogueId"] = 51105505,
            ["FacialId"] = {
                [1] = "700356:Sad01",
                [2] = "700357:Sad01",
                },
            ["GUID"] = "7FEFF0EA",
            ["LookAt"] = {
                [1] = "700356:n(700352);700357:n(700352);700352:n(700356);700355:n(700356)",
                },
            ["NextDialogue"] = 51105506,
            ["SpeakNpcId"] = 700356,
            ["TalkActionId"] = {
                [1] = "700356:Explain01_Start",
                },
            },
        [51105506] = {
            ["Camera"] = "145.941406,-168.082031,122.435547,0.000021,-0.999502,157.595932,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "如果不是你们的话，我们恐怕就回不去冰湖城了……呜呜呜。",
            ["ContentFR"] = "Sans vous, nous n’aurions jamais pu rentrer à Givrelac... <I>ouin...</>",
            ["DialogueId"] = 51105506,
            ["GUID"] = "7FEFF114",
            ["NextDialogue"] = 51105507,
            ["SpeakNpcId"] = 700357,
            ["TalkActionId"] = {
                [1] = "700357:Sigh_Start",
                },
            },
        [51105507] = {
            ["Camera"] = "-72.996094,-151.029297,122.46875,0.000014,-5.599703,-1.403595,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "没事了，你们已经安全啦！不过，为什么你们会在这里？",
            ["ContentFR"] = "Tout va bien maintenant, vous êtes en sécurité. Mais... pourquoi étiez-vous ici ?",
            ["DialogueId"] = 51105507,
            ["GUID"] = "7FEFF13E",
            ["NextDialogue"] = 51105508,
            ["SpeakNpcId"] = 700352,
            ["TalkActionId"] = {
                [1] = "700352:Confident_Start",
                },
            },
        [51105508] = {
            ["Camera"] = "328.121094,-260.578125,135.602539,0.00002,-5.399599,159.79628,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "唉，都怪我。我和妹妹本来一直在雾区生活，爸爸妈妈管得很严，没有让我们出过城。",
            ["ContentFR"] = "C’est ma faute... Ma sœur et moi vivons dans Brumelac. Nos parents nous interdisent de quitter la cité.",
            ["DialogueId"] = 51105508,
            ["GUID"] = "7FEFF168",
            ["NextDialogue"] = 51105509,
            ["SpeakNpcId"] = 700356,
            },
        [51105509] = {
            ["Camera"] = "328.121094,-260.578125,135.602539,0.00002,-5.399599,159.79628,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "所以我们就想着趁着银烛狂欢期间，卫兵们也都放松去参加狂欢了，到城外看一看。",
            ["ContentFR"] = "Alors, pendant la fête, quand les gardes se sont relâchés pour participer aux célébrations... Nous avons profité de l’occasion pour sortir voir l’extérieur.",
            ["DialogueId"] = 51105509,
            ["GUID"] = "7FEFF192",
            ["NextDialogue"] = 51105510,
            ["SpeakNpcId"] = 700356,
            },
        [51105510] = {
            ["Camera"] = "328.121094,-260.578125,135.602539,0.00002,-5.399599,159.79628,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "结果一过了桥就遇见了秽兽，我们为了避免被发现，只能躲着它们，越躲越远……",
            ["ContentFR"] = "Mais à peine le pont traversé, nous sommes tombés sur des Souillés. On a essayé de se cacher... et plus on fuyait, plus on s’enfonçait loin...",
            ["DialogueId"] = 51105510,
            ["GUID"] = "7FEFF1BC",
            ["NextDialogue"] = 51105511,
            ["SpeakNpcId"] = 700356,
            ["TalkActionId"] = {
                [1] = "700357:Sigh_End",
                },
            },
        [51105511] = {
            ["Camera"] = "328.121094,-260.578125,135.602539,0.00002,-5.399599,159.79628,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "最后还是被它们围住了，如果不是你们的话……",
            ["ContentFR"] = "Ils ont fini par nous encercler. Sans vous...",
            ["DialogueId"] = 51105511,
            ["GUID"] = "7FEFF1E6",
            ["NextDialogue"] = 51105512,
            ["SpeakNpcId"] = 700356,
            ["TalkActionId"] = {
                [1] = "700356:Explain01_End",
                },
            },
        [51105512] = {
            ["Camera"] = "328.121094,-260.578125,135.602539,0.00002,-5.399599,159.79628,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "哥哥，是我不好，我不应该闹着要出城，我们回去吧。我再也不要离开冰湖城了……",
            ["ContentFR"] = "Grand frère... c’est ma faute. Je n’aurais pas dû insister pour sortir. Rentrons... Je ne veux plus jamais quitter Givrelac...",
            ["DialogueId"] = 51105512,
            ["GUID"] = "7FEFF210",
            ["LookAt"] = {
                [1] = "700357:n(700356)",
                },
            ["NextDialogue"] = 51105513,
            ["SpeakNpcId"] = 700357,
            ["TalkActionId"] = {
                [1] = "700357:Explain02_Start",
                },
            },
        [51105513] = {
            ["Camera"] = "-72.996094,-151.029297,122.46875,0.000014,-5.599703,-1.403595,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "是哦，对于大部分人来说，城墙之外的世界还是太危险了……",
            ["ContentFR"] = "Oui... Pour beaucoup de gens, le monde au-delà des murs reste bien trop dangereux...",
            ["DialogueId"] = 51105513,
            ["GUID"] = "7FEFF23A",
            ["LookAt"] = {
                [1] = "700357:n(700352)",
                },
            ["NextDialogue"] = 51105514,
            ["SpeakNpcId"] = 700352,
            ["TalkActionId"] = {
                [1] = "700357:Explain02_End",
                [2] = "700352:Think_Start",
                },
            },
        [51105514] = {
            ["Camera"] = "-51.9375,-57.070312,124.332031,0.000017,-6.39975,-57.802399,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "是我欠考虑了，对远方的渴望虽然能够唤起热情，但并不适合每一个人。走吧，我们回去。",
            ["ContentFR"] = "C’est moi qui ai manqué de discernement. Le désir d’horizons lointains peut éveiller l’enthousiasme... mais il ne convient pas à tous. Rentrons.",
            ["DialogueId"] = 51105514,
            ["GUID"] = "7FEFF264",
            ["SpeakNpcId"] = 700355,
            ["TalkActionId"] = {
                [1] = "700352:Think_End",
                [2] = "700355:Agree",
                },
            },
        [51105515] = {
            ["Content"] = "（一阵有一些激烈但不那么激烈的打斗声）",
            ["ContentFR"] = "Des bruits de combat, vifs mais sans réelle gravité.",
            ["DialogueId"] = 51105515,
            ["GUID"] = "7FEFF28E",
            ["Scripts"] = "PlayNormalSound{EventPath{\"event:/sfx/common/story/jiaojiao/fight\"},PlayAs2D{true}}",
            },
        [51105601] = {
            ["Camera"] = "164.716797,101.845215,126.411133,0.000016,-13.399744,-142.802551,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "所以，连探险家前辈的方法也没有成功……",
            ["ContentFR"] = "Alors... même la méthode de Luno, l’exploratrice n’a pas fonctionné...",
            ["DialogueId"] = 51105601,
            ["GUID"] = "7FF000AA",
            ["LookAt"] = {
                [1] = "700352:n(700355);700355:n(700352)",
                },
            ["NextDialogue"] = 51105602,
            ["SpeakNpcId"] = 700352,
            ["TalkActionId"] = {
                [1] = "700352:Sigh_Start",
                },
            ["TurnTo"] = {
                [1] = "700355:n(700352)",
                },
            },
        [51105602] = {
            ["Camera"] = "164.716797,101.845215,126.411133,0.000016,-13.399744,-142.802551,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "到底应该怎么做呢？",
            ["ContentFR"] = "Que devons-nous faire, maintenant ?",
            ["DialogueId"] = 51105602,
            ["GUID"] = "7FF000D4",
            ["NextDialogue"] = 51105603,
            ["SpeakNpcId"] = 700352,
            },
        [51105603] = {
            ["Camera"] = "93.466797,-74.861328,96.041504,0.000017,-5.799609,141.39859,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "别丧气，至少我们的尝试确实帮助了别人。",
            ["ContentFR"] = "Ne te décourage pas. Au moins, nos efforts ont réellement aidé quelqu’un.",
            ["DialogueId"] = 51105603,
            ["GUID"] = "7FF000FE",
            ["NextDialogue"] = 51105604,
            ["SpeakNpcId"] = 700355,
            ["TalkActionId"] = {
                [1] = "700355:Explain02_Start",
                },
            },
        [51105604] = {
            ["Camera"] = "93.466797,-74.861328,96.041504,0.000017,-5.799609,141.39859,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "嗯，你说得对，无论如何都不算是白忙一场。",
            ["ContentFR"] = "Oui... Tu as raison. Ce n’était pas inutile.",
            ["DialogueId"] = 51105604,
            ["GUID"] = "7FF00128",
            ["NextDialogue"] = 51105605,
            ["SpeakNpcId"] = 700352,
            ["TalkActionId"] = {
                [1] = "700352:Sigh_End",
                },
            },
        [51105605] = {
            ["Camera"] = "-192.395508,-2.036133,165.440918,0.000029,-7.999804,5.19757,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "唉，你们两个都去哪里了？我和你们的父亲都快急疯了。",
            ["ContentFR"] = "Où étiez-vous passés ? Votre père et moi étions morts d’inquiétude !",
            ["DialogueId"] = 51105605,
            ["FacialId"] = {
                [1] = "700358:Sad02",
                },
            ["GUID"] = "7FF00152",
            ["LookAt"] = {
                [1] = "700358:n(700356);700352:n(700358);700355:n(700358)",
                },
            ["NextDialogue"] = 51105606,
            ["SpeakNpcId"] = 700358,
            ["TalkActionId"] = {
                [1] = "700358:Confident_Start",
                [2] = "700355:Explain02_End",
                },
            ["TurnTo"] = {
                [1] = "700352:n(700358)",
                [2] = "700355:(700358)",
                },
            },
        [51105606] = {
            ["Camera"] = "181.737305,9.148438,135.123047,0.000029,-7.799679,159.398849,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我们去了城外，遇到了秽兽，多亏了他们，救了我们。",
            ["ContentFR"] = "Nous sommes sortis de la cité et nous avons rencontré des Souillés... Heureusement, elles nous ont sauvés !",
            ["DialogueId"] = 51105606,
            ["GUID"] = "7FF0017C",
            ["LookAt"] = {
                [1] = "700356:n(700358)",
                },
            ["NextDialogue"] = 51105607,
            ["SpeakNpcId"] = 700356,
            ["SpeakNpcName"] = "UI_CMName_Name_NanHai",
            ["TalkActionId"] = {
                [1] = "700358:Confident_End",
                },
            },
        [51105607] = {
            ["Camera"] = "-279.733398,363.849609,151.888672,0.000033,-5.399538,-40.201584,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "城外？！门口的那群卫兵到底在干什么……算了，没事就好，没事就好。",
            ["ContentFR"] = "À l’extérieur ?! Mais que faisaient les gardes à l’entrée... enfin... peu importe. L’essentiel, c’est que vous alliez bien.",
            ["DialogueId"] = 51105607,
            ["FacialId"] = {
                [1] = "700358:Shock02",
                },
            ["GUID"] = "7FF001A6",
            ["NextDialogue"] = 51105608,
            ["SpeakNpcId"] = 700358,
            ["TalkActionId"] = {
                [1] = "700358:Shock_Start",
                },
            },
        [51105608] = {
            ["Camera"] = "-228.207031,-9.803711,149.039062,0.000034,-4.999445,4.798473,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "也谢谢你们二位。",
            ["ContentFR"] = "Merci à vous deux.",
            ["DialogueId"] = 51105608,
            ["FacialId"] = {
                [1] = "700358:None",
                },
            ["GUID"] = "7FF001D0",
            ["LookAt"] = {
                [1] = "700358:n(700352)",
                },
            ["NextDialogue"] = 51105609,
            ["SpeakNpcId"] = 700358,
            ["TalkActionId"] = {
                [1] = "700358:Shock_End",
                },
            },
        [51105609] = {
            ["Camera"] = "-228.207031,-9.803711,149.039062,0.000034,-4.999445,4.798473,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "咦，等等，这不是白嘛？",
            ["ContentFR"] = "Tiens... Attendez... Vous ne seriez pas Snow ?",
            ["DialogueId"] = 51105609,
            ["GUID"] = "7FF001FA",
            ["NextDialogue"] = 51105610,
            ["SpeakNpcId"] = 700358,
            ["TalkActionId"] = {
                [1] = "700358:Talk01_Start",
                },
            },
        [51105610] = {
            ["Camera"] = "221.630859,16.369629,149.368164,0.000039,-18.199278,-167.801788,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "嗯？你认识我吗？",
            ["ContentFR"] = "Hmm ? Vous me connaissez ?",
            ["DialogueId"] = 51105610,
            ["GUID"] = "7FF00224",
            ["NextDialogue"] = 51105611,
            ["SpeakNpcId"] = 700352,
            ["TalkActionId"] = {
                [1] = "700352:Think_Start",
                [2] = "700358:Talk01_End",
                },
            },
        [51105611] = {
            ["Camera"] = "50.040039,30.647461,131.996094,0.000035,3.20023,0.399084,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "之前不认识，但是这几天听说有一位皎皎之民在努力让冰湖城的居民振奋精神，听他们来看描述就应该是你了。",
            ["ContentFR"] = "Pas personnellement, mais ces derniers jours, on parle beaucoup d’une Luno qui s’efforce de redonner courage aux habitants de Givrelac. D’après les descriptions... c’est forcément vous.",
            ["DialogueId"] = 51105611,
            ["GUID"] = "7FF0024E",
            ["NextDialogue"] = 51105612,
            ["SpeakNpcId"] = 700358,
            ["TalkActionId"] = {
                [1] = "700358:Agree",
                },
            },
        [51105612] = {
            ["Camera"] = "221.630859,16.369629,149.368164,0.000039,-18.199278,-167.801788,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "哼哼，没错，就是我！",
            ["ContentFR"] = "Héhé... Exactement ! C’est bien moi !",
            ["DialogueId"] = 51105612,
            ["GUID"] = "7FF00278",
            ["NextDialogue"] = 51105613,
            ["SpeakNpcId"] = 700352,
            ["TalkActionId"] = {
                [1] = "700352:Think_End",
                },
            },
        [51105613] = {
            ["Camera"] = "56.023438,-549.053711,122.467773,0.00005,-3.199588,88.599136,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "不过……我也没有找到什么很好的让大家振作起来的办法。唉，这样一来连我都要没什么精神啦。",
            ["ContentFR"] = "Mais... pour être honnête, je n’ai pas trouvé de solution miracle. À force, même moi, je commence à manquer d’énergie...",
            ["DialogueId"] = 51105613,
            ["GUID"] = "7FF002A2",
            ["NextDialogue"] = 51105614,
            ["SpeakNpcId"] = 700352,
            ["TalkActionId"] = {
                [1] = "700352:Sigh_Start",
                },
            },
        [51105614] = {
            ["Camera"] = "-228.207031,-9.803711,149.039062,0.000034,-4.999445,4.798473,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "那你可就白担心啦，快去盖雷亚剧院吧，我刚刚就听说你的几个朋友在到处找你，但是却不知道你跑到哪里去了。",
            ["ContentFR"] = "Dans ce cas, vous vous faites du souci pour rien. Allez vite au Théâtre Galea. J’ai entendu dire que vos amis vous cherchaient partout.",
            ["DialogueId"] = 51105614,
            ["GUID"] = "7FF002CC",
            ["NextDialogue"] = 51105615,
            ["SpeakNpcId"] = 700358,
            ["TalkActionId"] = {
                [1] = "700358:Explain01_Start",
                },
            },
        [51105615] = {
            ["Camera"] = "221.630859,16.369629,149.368164,0.000039,-18.199278,-167.801788,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "嗯？盖雷亚剧院，好的，我这就去！",
            ["ContentFR"] = "Hein ? Le Théâtre Galea ? Très bien, j’y vais tout de suite !",
            ["DialogueId"] = 51105615,
            ["GUID"] = "7FF002F6",
            ["SpeakNpcId"] = 700352,
            ["TalkActionId"] = {
                [1] = "700352:Bai_Think2Confident",
                },
            },
        [51105701] = {
            ["Camera"] = "23.855469,1780.534668,845.710938,0.000039,-0.800191,-90.801872,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "只见盖雷亚剧院的舞台上，一个纸质的画板竖立了起来，按轮廓来看，是皎皎的身形。",
            ["ContentFR"] = "Sur la scène du Théâtre Galea, un grand panneau de papier a été dressé. À en juger par la silhouette... il représente une Luno.",
            ["DialogueId"] = 51105701,
            ["FinalCamera"] = "17.328125,1336.186768,839.191406,0.000039,-1.000206,-90.801872,35.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "7FF01112",
            ["NextDialogue"] = 51105702,
            ["ToFinalCameraBlendTime"] = 5,
            },
        [51105702] = {
            ["Camera"] = "410.433594,758.865479,107.394531,0.000057,-1.200132,-118.800987,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "哟，白，你回来啦。",
            ["ContentFR"] = "Hé ! Snow, te voilà enfin !",
            ["DialogueId"] = 51105702,
            ["GUID"] = "7FF0113C",
            ["LookAt"] = {
                [1] = "700349:n(700352)",
                },
            ["NextDialogue"] = 51105703,
            ["SpeakNpcId"] = 700349,
            ["TalkActionId"] = {
                [1] = "700349:Explain01_Start",
                },
            },
        [51105703] = {
            ["Camera"] = "22.292969,279.418884,100.0625,0.000061,4.399789,-95.400414,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "那凯旋的身影在灯光的照射下，如同巨人一般伟岸！",
            ["ContentFR"] = "Cette silhouette triomphante, baignée par les projecteurs... On dirait un géant dressé sur scène !",
            ["DialogueId"] = 51105703,
            ["GUID"] = "7FF01166",
            ["NextDialogue"] = 51105704,
            ["SpeakNpcId"] = 700350,
            ["TalkActionId"] = {
                [1] = "700350:Talk02_Start",
                },
            },
        [51105704] = {
            ["Camera"] = "71.03125,17.270752,111.34375,0.000066,-7.600156,112.99839,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "威尔斯大叔，巴克？还有这么多人，你们为什么在这里？",
            ["ContentFR"] = "Wells ? Buck ? Et... tout le monde est là ? Que se passe-t-il ?",
            ["DialogueId"] = 51105704,
            ["GUID"] = "7FF01190",
            ["LookAt"] = {
                [1] = "700352:n(700349)",
                },
            ["NextDialogue"] = 51105705,
            ["SpeakNpcId"] = 700352,
            ["TalkActionId"] = {
                [1] = "700350:Talk02_End",
                [2] = "700352:Shock03_Start",
                },
            },
        [51105705] = {
            ["Camera"] = "-8.945312,81.085327,158.34375,0.000068,-1.800137,-122.402336,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "说来怪不好意思的，一开始听说你想办法让我们振作起来，就只是觉得你是又无聊啦，没事找事。",
            ["ContentFR"] = "Pour être honnête, au début, quand on a appris que tu essayais de nous remotiver... On s’est dit que tu t’ennuyais, comme d’habitude, et que tu cherchais quelque chose à faire.",
            ["DialogueId"] = 51105705,
            ["GUID"] = "7FF011BA",
            ["NextDialogue"] = 51105706,
            ["SpeakNpcId"] = 700349,
            ["TalkActionId"] = {
                [1] = "700352:Shock03_End",
                },
            },
        [51105706] = {
            ["Camera"] = "-8.945312,81.085327,158.34375,0.000068,-1.800137,-122.402336,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "结果没想到你真的去尝试了各种方式，虽然听说也没什么好的结果，但我们水仙平原的常客听说了，都有点被打动吧。",
            ["ContentFR"] = "Mais quand on a compris que tu essayais vraiment toutes sortes de méthodes... Même si aucune n’a vraiment abouti, les habitués des Asphodèles ont été touchés.",
            ["DialogueId"] = 51105706,
            ["GUID"] = "7FF011E4",
            ["NextDialogue"] = 51105707,
            ["SpeakNpcId"] = 700349,
            ["TalkActionId"] = {
                [1] = "700349:Explain01_End",
                },
            },
        [51105707] = {
            ["Camera"] = "-117.642578,-246.383423,180.195312,0.00005,-13.000267,74.194115,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "呃，“没什么好的结果”可以不用说的！",
            ["ContentFR"] = "Hé ! Vous pouviez éviter la partie « aucune n’a abouti » !",
            ["DialogueId"] = 51105707,
            ["FacialId"] = {
                [1] = "700352:Sad03",
                },
            ["GUID"] = "7FF0120E",
            ["NextDialogue"] = 51105708,
            ["SpeakNpcId"] = 700352,
            ["TalkActionId"] = {
                [1] = "700352:Sad02_Start",
                },
            },
        [51105708] = {
            ["Camera"] = "378.371094,743.933472,140.042969,0.000055,-4.200552,-119.40416,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "唔，确实不是重点，重点是，我们觉得不能光看你一个人这样东奔西走！",
            ["ContentFR"] = "Oui, bon... ce n’est pas l’important. L’important, c’est qu’on s’est rendu compte qu’on ne pouvait pas te laisser courir partout toute seule.",
            ["DialogueId"] = 51105708,
            ["GUID"] = "7FF01238",
            ["NextDialogue"] = 51105709,
            ["SpeakNpcId"] = 700349,
            ["TalkActionId"] = {
                [1] = "700349:Talk02_Start",
                },
            },
        [51105709] = {
            ["Camera"] = "378.371094,743.933472,140.042969,0.000055,-4.200552,-119.40416,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "于是我们觉得得要做点什么，不能让你白忙活。",
            ["ContentFR"] = "Alors on a décidé de faire quelque chose, nous aussi. On ne voulait pas que tes efforts soient vains.",
            ["DialogueId"] = 51105709,
            ["GUID"] = "7FF01262",
            ["NextDialogue"] = 51105710,
            ["SpeakNpcId"] = 700349,
            ["TalkActionId"] = {
                [1] = "700349:Talk02_End",
                },
            },
        [51105710] = {
            ["Camera"] = "45.978516,411.828857,121.648438,0.000068,-1.000397,-97.205254,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "然后，思想之间迸发出火花，火花引爆了更多的思绪。",
            ["ContentFR"] = "Les pensées ont jailli, les idées se sont entrechoquées... et les étincelles ont fusé.",
            ["DialogueId"] = 51105710,
            ["FacialId"] = {
                [1] = "700352:None",
                },
            ["GUID"] = "7FF0128C",
            ["NextDialogue"] = 51105711,
            ["SpeakNpcId"] = 700350,
            ["TalkActionId"] = {
                [1] = "700352:Sad02_End",
                },
            },
        [51105711] = {
            ["Camera"] = "-8.945312,81.085327,158.34375,0.000068,-1.800137,-122.402336,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "巴克说的话呢，可能不是那么好懂，意思是我们俩商量了一会儿，没什么好法子，又找到了其他人，最后找到了普奇团长。",
            ["ContentFR"] = "Pour faire simple, après avoir réfléchi, on n’a pas trouvé de solution parfaite. Alors on a demandé de l’aide à d’autres... jusqu’à rencontrer la Directrice Putsch.",
            ["DialogueId"] = 51105711,
            ["GUID"] = "7FF012B6",
            ["NextDialogue"] = 51105712,
            ["SpeakNpcId"] = 700349,
            ["TalkActionId"] = {
                [1] = "700349:Explain02_Start",
                },
            },
        [51105712] = {
            ["Camera"] = "-8.945312,81.085327,158.34375,0.000068,-1.800137,-122.402336,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "大家对于怎么向你表示感谢都各自有想法，但又都觉得不是最好的。",
            ["ContentFR"] = "Chacun avait sa propre idée pour te remercier, mais aucune ne faisait l’unanimité.",
            ["DialogueId"] = 51105712,
            ["GUID"] = "7FF012E0",
            ["NextDialogue"] = 51105713,
            ["SpeakNpcId"] = 700349,
            },
        [51105713] = {
            ["Camera"] = "85.224609,834.157471,143.992188,0.000093,-3.799914,-95.203133,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "于是大家聚在一起想啊想，想地抓耳挠腮，争地面红耳赤。就在这个过程中，突然就感觉热情又重新回来了。",
            ["ContentFR"] = "On a débattu, argumenté, failli s’écharper... Et sans s’en rendre compte, l’enthousiasme est revenu.",
            ["DialogueId"] = 51105713,
            ["GUID"] = "7FF0130A",
            ["NextDialogue"] = 51105714,
            ["SpeakNpcId"] = 700349,
            },
        [51105714] = {
            ["Camera"] = "85.224609,834.157471,143.992188,0.000093,-3.799914,-95.203133,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "于是我们意识到了，为了一个明确的目标去行动，可以让所有人重新燃起热情。",
            ["ContentFR"] = "C’est là qu’on a compris une chose : agir ensemble pour un objectif clair ravive la flamme de chacun.",
            ["DialogueId"] = 51105714,
            ["GUID"] = "7FF01334",
            ["NextDialogue"] = 51105715,
            ["SpeakNpcId"] = 700349,
            ["TalkActionId"] = {
                [1] = "700349:Explain02_End",
                },
            },
        [51105715] = {
            ["Camera"] = "242.505859,2691.037598,777.695312,0.000124,0.999209,-92.40229,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "最终呢，我们决定在这里搭建一个皎皎们的舞台，在这里举办一个小的舞会，以宣告银烛狂欢的正式结束。",
            ["ContentFR"] = "Finalement, nous avons décidé d’installer ici une scène dédiée aux Luno, et d’organiser un petit bal pour marquer officiellement la fin de la Fête de la Chandelle d’Argent.",
            ["DialogueId"] = 51105715,
            ["GUID"] = "7FF0135E",
            ["LookAt"] = {
                [1] = "700352:n(700359)",
                },
            ["NextDialogue"] = 51105716,
            ["SpeakNpcId"] = 700359,
            ["TalkActionId"] = {
                [1] = "700359:Talk03_Start",
                },
            },
        [51105716] = {
            ["Camera"] = "48.492188,150.261108,106.398438,0.000098,6.400003,-77.597488,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "更重要的是，向你，以及为了人类奔走的每一位皎皎表示感谢。",
            ["ContentFR"] = "Mais surtout... pour te remercier, toi, et toutes les Luno qui se sont tant démenées pour les autres.",
            ["DialogueId"] = 51105716,
            ["FacialId"] = {
                [1] = "700359:Smile01",
                },
            ["GUID"] = "7FF01388",
            ["NextDialogue"] = 51105717,
            ["SpeakNpcId"] = 700359,
            },
        [51105717] = {
            ["Camera"] = "47.298828,36.943848,122.441406,0.000113,-10.600057,107.802986,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "只不过因为准备仓促，这个布景还没有做好，但是我相信会有热心的冰湖城市民伸出援手的！",
            ["ContentFR"] = "Seulement, comme tout a été préparé dans l’urgence, le décor n’est pas encore prêt... mais je suis certaine que les habitants de Givrelac nous prêteront main-forte !",
            ["DialogueId"] = 51105717,
            ["GUID"] = "7FF013B2",
            ["NextDialogue"] = 51105718,
            ["SpeakNpcId"] = 700359,
            ["TalkActionId"] = {
                [1] = "700359:Talk03_End",
                },
            },
        [51105718] = {
            ["Camera"] = "47.298828,36.943848,122.441406,0.000113,-10.600057,107.802986,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "咦？为什么是皎皎们……我们其实，也没做什么啦，只是都做了一些平时在做的事情。",
            ["ContentFR"] = "Hein ? Pourquoi les Luno ? Nous n’avons pourtant rien fait d’exceptionnel... juste ce que nous faisons d’habitude.",
            ["DialogueId"] = 51105718,
            ["GUID"] = "7FF013DC",
            ["NextDialogue"] = 51105719,
            ["SpeakNpcId"] = 700352,
            ["TalkActionId"] = {
                [1] = "700352:Shy03_Start",
                },
            },
        [51105719] = {
            ["Camera"] = "-8.619141,416.381531,105.339844,0.000135,-0.200131,-79.794884,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "正是因为你们平时一直都在帮助其他人，所以在大家都无精打采的时候，看到皎皎们还是和往常一样。",
            ["ContentFR"] = "Justement. Quand tout le monde était à bout de souffle, vous avez continué comme toujours.",
            ["DialogueId"] = 51105719,
            ["GUID"] = "7FF01406",
            ["NextDialogue"] = 51105720,
            ["SpeakNpcId"] = 700359,
            ["TalkActionId"] = {
                [1] = "700359:Think_Start",
                },
            },
        [51105720] = {
            ["Camera"] = "-8.619141,416.381531,105.339844,0.000135,-0.200131,-79.794884,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "和往常一样锻造，冒险，经商，并且又帮助感染了其他人，所以才会让大家想着为你们做点什么吧。",
            ["ContentFR"] = "Forger, commercer, explorer... et aider les autres sans relâche. C’est cela qui a redonné espoir à chacun.",
            ["DialogueId"] = 51105720,
            ["GUID"] = "7FF01430",
            ["NextDialogue"] = 51105721,
            ["SpeakNpcId"] = 700359,
            ["TalkActionId"] = {
                [1] = "700359:Think_End",
                },
            },
        [51105721] = {
            ["Camera"] = "210.134766,-175.124634,161.980469,0.000142,-12.600367,121.406113,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "……即便和平常一样，也能让大家打起精神吗。",
            ["ContentFR"] = "... Même rester fidèle à ses habitudes peut redonner du courage aux autres ?",
            ["DialogueId"] = 51105721,
            ["GUID"] = "7FF0145A",
            ["NextDialogue"] = 51105722,
            ["SpeakNpcId"] = 700352,
            ["TalkActionId"] = {
                [1] = "700352:Shy03_End",
                },
            },
        [51105722] = {
            ["Camera"] = "13.275391,55.729736,111.578125,0.000138,-6.800259,96.806892,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我明白了，哼哼。看来平时本魔王大人和小仆从在冰湖城里跑来跑去，已经积攒了很多人望。",
            ["ContentFR"] = "Je comprends... héhé. On dirait que, mine de rien, le Roi Démon et son petit larbin ont gagné l’estime de Givrelac.",
            ["DialogueId"] = 51105722,
            ["GUID"] = "7FF01484",
            ["LookAt"] = {
                [1] = "700352:n(700352)",
                },
            ["NextDialogue"] = 51105723,
            ["SpeakNpcId"] = 700352,
            ["TalkActionId"] = {
                [1] = "700352:SpecialConfident_Start",
                },
            },
        [51105723] = {
            ["Camera"] = "-8.945312,81.085327,158.34375,0.000068,-1.800137,-122.402336,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "是，是，你是最受大家畏惧，最受大家尊敬，也最热爱自己子民的魔王大人，只要你一声令下，大家都会充满力量。",
            ["ContentFR"] = "Bien sûr ! Tu es le plus redouté, le plus respecté et le plus aimant des Rois Démons. Un seul de tes ordres, et tout le monde retrouve sa vigueur !",
            ["DialogueId"] = 51105723,
            ["FacialId"] = {
                [1] = "700349:Smile01",
                },
            ["GUID"] = "7FF014AE",
            ["NextDialogue"] = 51105724,
            ["SpeakNpcId"] = 700349,
            ["TalkActionId"] = {
                [1] = "700349:Agree",
                [2] = "700352:SpecialConfident_End",
                },
            },
        [51105724] = {
            ["Camera"] = "0.195312,-69.396484,112.128906,0.000143,-7.20016,90.206581,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "没错，那么我命令你们所有人！听从魔王大人的命令，恢复精神，开始银烛狂欢最后的舞会！",
            ["ContentFR"] = "Exactement ! Alors écoutez bien : le Roi Démon vous en donne l’ordre ! Reprenez des forces, et que commence le dernier bal de la Fête de la Chandelle d’Argent !",
            ["DialogueId"] = 51105724,
            ["FacialId"] = {
                [1] = "700352:Smile02",
                },
            ["GUID"] = "7FF014D8",
            ["NextDialogue"] = 51105725,
            ["SpeakNpcId"] = 700352,
            ["TalkActionId"] = {
                [1] = "700352:SpecialHappy_Start",
                },
            },
        [51105725] = {
            ["Camera"] = "320.064453,1972.346924,419.992188,0.000141,-7.200317,-99.594925,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "好！",
            ["ContentFR"] = "Oui !",
            ["DialogueId"] = 51105725,
            ["GUID"] = "7FF01502",
            ["NextDialogue"] = 51105726,
            ["SpeakNpcName"] = "UI_CMName_Name_ZhongRen",
            },
        [51105726] = {
            ["Camera"] = "-22.078125,-800.788818,638.539062,0.000137,3.599831,-91.394226,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "于是，今年本蒙上一层阴翳的银烛狂欢，在一位自称魔王的皎皎的努力下，成功地重新燃起欢乐氛围。",
            ["ContentFR"] = "Ainsi, la Fête de la Chandelle d’Argent, autrefois assombrie par les incidents, retrouva finalement son éclat... grâce aux efforts d’une Luno qui se proclamait Roi Démon, et à la chaleur retrouvée de Givrelac.",
            ["DialogueId"] = 51105726,
            ["FinalCamera"] = "61.220703,-802.816284,638.539062,0.000137,3.599831,-91.394226,35.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "7FF0152C",
            ["ToFinalCameraBlendTime"] = 7,
            },
