            ["SpeakNpcId"] = 701005,
            },
        [51105901] = {
            ["Content"] = "什么奇遇？我也能分点好处吗？",
            ["ContentFR"] = "<I>Quelle rencontre providentielle ? Et... j’y gagne quelque chose, moi aussi ?</>",
            ["DialogueId"] = 51105901,
            ["GUID"] = "7FF031E2",
            ["ImprPlusId"] = 1206,
            ["NextDialogue"] = 51105902,
            },
        [51105902] = {
            ["Content"] = "嗯？不行不行，没人说过奇遇还能跟别人分的啊？",
            ["ContentFR"] = "Hein ? Non, non ! Personne n’a jamais dit qu’on pouvait partager les bénéfices d’une rencontre du destin !",
            ["DialogueId"] = 51105902,
            ["GUID"] = "7FF0320C",
            ["NextDialogue"] = 51105903,
            ["SpeakNpcId"] = 701005,
            ["TalkActionId"] = {
                [1] = "701005:Talk01_Start",
                },
            },
        [51105903] = {
            ["Content"] = "嘶……等等，我懂了，前辈这是在考验我的心性！",
            ["ContentFR"] = "<I>Hss...</> attendez… je comprends ! Vous mettez mon cœur à l’épreuve !",
            ["DialogueId"] = 51105903,
            ["GUID"] = "7FF03236",
            ["NextDialogue"] = 51105904,
            ["SpeakNpcId"] = 701005,
            },
        [51105904] = {
            ["Content"] = "怪我愚钝，差点就被蝇头小利冲昏头脑，神功乃济世之器，晚辈岂会独占？",
            ["ContentFR"] = "Quelle stupidité de ma part... J’ai failli me laisser aveugler par un maigre profit. Un art divin est fait pour sauver le monde, comment pourrais-je le garder pour moi seul ?",
            ["DialogueId"] = 51105904,
            ["GUID"] = "7FF03260",
            ["NextDialogue"] = 51105913,
            ["SpeakNpcId"] = 701005,
            ["TalkActionId"] = {
                [1] = "701005:Talk01_End",
                },
            },
        [51105905] = {
            ["Content"] = "这是什么角色扮演活动吗？",
            ["ContentFR"] = "<I>C’est... une sorte de jeu de rôle ?</>",
            ["DialogueId"] = 51105905,
            ["GUID"] = "7FF0328A",
            ["ImprPlusId"] = 1208,
            ["NextDialogue"] = 51105906,
            },
        [51105906] = {
            ["Content"] = "啊？那是什么？",
            ["ContentFR"] = "Un jeu de quoi ?",
            ["DialogueId"] = 51105906,
            ["GUID"] = "7FF032B4",
            ["NextDialogue"] = 51105907,
            ["SpeakNpcId"] = 701005,
            ["TalkActionId"] = {
                [1] = "701005:Talk02_Start",
                },
            },
        [51105907] = {
            ["Content"] = "呃，一种游戏形式？扮演故事里的角色一起互动……你小时候没这么玩过吗？",
            ["ContentFR"] = "Disons... une forme de jeu où l’on incarne des personnages d’une histoire, et où l’on joue des scènes ensemble. Tu n’as jamais fait ça, enfant ?",
            ["DialogueId"] = 51105907,
            ["GUID"] = "7FF032DE",
            ["NextDialogue"] = 51105908,
            ["SpeakNpcId"] = 100001,
            },
        [51105908] = {
            ["Content"] = "扮演？不不不，要来当然就来真的，扮演多没意思。",
            ["ContentFR"] = "Incarner ? Non, non, non. Quitte à faire quelque chose, autant que ce soit réel. Faire semblant, quel intérêt ?",
