        [51116024] = {
            ["Content"] = "天哪，你弹得太好了，小动物们听完都热血沸腾了！",
            ["ContentFR"] = "<I>Incroyable ! Vous jouez si bien qu’ils en ont perdu la tête !</>",
            ["DialogueId"] = 51116024,
            ["GUID"] = "7FF6AEB0",
            ["ImprPlusId"] = 1210,
            ["NextDialogue"] = 51116025,
            },
        [51116025] = {
            ["Content"] = "怎、怎会如此……这究竟是何缘故……？",
            ["ContentFR"] = "C... comment cela a-t-il pu arriver... ? Quelle en est la raison... ?",
            ["DialogueId"] = 51116025,
            ["GUID"] = "7FF6AEDA",
            ["NextDialogue"] = 51116026,
            ["SpeakNpcId"] = 701020,
            },
        [51116026] = {
            ["Content"] = "你弹的东西真的是音乐吗？",
            ["ContentFR"] = "Êtes-vous certain que ce que vous jouez puisse être qualifié de musique ?",
            ["DialogueId"] = 51116026,
            ["GUID"] = "7FF6AF04",
            ["NextDialogue"] = 51116027,
            ["SpeakNpcId"] = 100001,
            },
        [51116027] = {
            ["Content"] = "这“出神入化之曲”，总应与一般的音乐有异啊。",
            ["ContentFR"] = "Une œuvre dite « transcendante » ne saurait ressembler à de la musique ordinaire.",
            ["DialogueId"] = 51116027,
            ["GUID"] = "7FF6AF2E",
            ["NextDialogue"] = 51116028,
            ["SpeakNpcId"] = 701020,
            ["TalkActionId"] = {
                [1] = "701020:Talk02_Start",
                },
            },
        [51116028] = {
            ["Content"] = "我想既是要让动物也能欣赏，想必最好取材于自然……好比我刚才弹的这一曲，便是融合了树枝撕裂之声、蚊虫振翅之声、野狗刨地之声……",
            ["ContentFR"] = "Puisqu’elle devait être appréciée même par les animaux, j’ai pensé qu’il fallait puiser directement dans la nature... Ainsi, ce morceau mêlait le craquement des branches, le bourdonnement des insectes, le grattement des chiens errants...",
            ["DialogueId"] = 51116028,
            ["GUID"] = "7FF6AF58",
            ["NextDialogue"] = 51116029,
            ["SpeakNpcId"] = 701020,
            },
        [51116029] = {
            ["Content"] = "我自以为此曲完美无缺，没想到，终究是错付了……",
            ["ContentFR"] = "Je croyais cette composition parfaite... et pourtant, tout cela n’a servi à rien...",
            ["DialogueId"] = 51116029,
            ["GUID"] = "7FF6AF82",
            ["NextOptions"] = {
                [1] = 51116030,
                },
            ["SpeakNpcId"] = 701020,
            ["TalkActionId"] = {
                [1] = "701020:Talk02_End",
                },
            },
        [51116030] = {
            ["Content"] = "有没有可能你选的这些声音本来也不好听……",
            ["ContentFR"] = "<I>Et si ces sons n’étaient tout simplement... pas agréables à l’oreille ?</>",
            ["DialogueId"] = 51116030,
            ["GUID"] = "7FF6AFAC",
            ["NextDialogue"] = 51116031,
            },
        [51116031] = {
            ["Content"] = "……！",
            ["ContentFR"] = "... !",
            ["DialogueId"] = 51116031,
            ["GUID"] = "7FF6AFD6",
            ["NextDialogue"] = 51116032,
            ["SpeakNpcId"] = 701020,
            },
        [51116032] = {
            ["Content"] = "{性别：兄台|姑娘}可真是一语惊醒梦中人！",
            ["ContentFR"] = "{性别:Monsieur|Mademoiselle}, votre remarque m’éclaire comme un éclair dans la nuit !",
            ["DialogueId"] = 51116032,
            ["GUID"] = "7FF6B000",
            ["NextDialogue"] = 51116033,
            ["SpeakNpcId"] = 701020,
            ["TalkActionId"] = {
                [1] = "701020:Sigh_Start",
                },
            },
        [51116033] = {
            ["Content"] = "原来如此，是我取材有误……我这就回去重新谱曲！让我想想……乌鸦高鸣之声、野鼠啃噬之声、金石摩擦之声……嗯，应当不错！",
            ["ContentFR"] = "Voilà donc l’erreur... le choix des sons ! Je vais rentrer et recomposer aussitôt ! Voyons... le croassement des corbeaux, le grignotement des souris, le frottement du métal contre la pierre... oui, cela devrait être parfait !",
            ["DialogueId"] = 51116033,
            ["GUID"] = "7FF6B02A",
            ["NextDialogue"] = 51116034,
            ["SpeakNpcId"] = 701020,
            ["TalkActionId"] = {
                [1] = "701020:Sigh_End",
                },
            },
        [51116034] = {
            ["Content"] = "（具睦似乎已经完全沉浸在了自己的艺术之中。无论如何，你已经拿到了报酬，还是赶紧离开，保护好自己的耳朵吧。）",
            ["ContentFR"] = "Ju Mu semble désormais entièrement absorbé par son « art ». Quoi qu’il en soit, vous avez reçu votre récompense ; mieux vaut vous éclips­er rapidement et préserver vos oreilles.",
            ["DialogueId"] = 51116034,
            ["GUID"] = "7FF6B054",
            },
        [51116035] = {
            ["Content"] = "小鸟儿、小狐狸、小野猫你们别跑呀，再听一曲吧！",
            ["ContentFR"] = "Petits oiseaux, renards, chatons sauvages ! Ne fuyez pas ! Écoutez encore un morceau !",
            ["DialogueId"] = 51116035,
            ["GUID"] = "7FF6B07E",
            ["SpeakNpcId"] = 701020,
            },
        [51117000] = {
            ["Camera"] = "-56.007812,179.976562,127.53125,0.000043,-7.60004,-107.399704,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "一定是无由生啦！",
            ["ContentFR"] = "C’est forcément un Wishen !",
            ["DialogueId"] = 51117000,
            ["GUID"] = "7FF74ED0",
            ["LookAt"] = {
                [1] = "701021:n(701022)",
                [2] = "701022:n(701021)",
                [3] = "100001:n(701021)",
                },
            ["NextDialogue"] = 51117001,
            ["SpeakNpcId"] = 701021,
            ["TalkActionId"] = {
                [1] = "701021:Angry01_Start",
                },
            },
        [51117001] = {
            ["Camera"] = "-175.459961,-170.417969,118.708984,0.000063,-4.799348,68.995163,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "一定是狴犴啦！",
            ["ContentFR"] = "Pas du tout ! C’est forcément un Bi’an !",
            ["DialogueId"] = 51117001,
            ["GUID"] = "7FF74EFA",
            ["NextDialogue"] = 51117002,
            ["SpeakNpcId"] = 701022,
            ["TalkActionId"] = {
                [1] = "701022:Angry01_Start",
                },
            },
        [51117002] = {
            ["Camera"] = "-102.625977,389.867188,178.47168,0.000117,-10.004881,-94.054535,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "（枯荣阁外，两个小孩吵吵嚷嚷的，不知在争论些什么。你无意中放慢了脚步，引起了他们的注意——）",
            ["ContentFR"] = "À l’extérieur du Pavillon de l’Éphémère, deux enfants se disputent bruyamment à propos de quelque chose. Vous ralentissez machinalement le pas, attirant leur attention —",
            ["DialogueId"] = 51117002,
            ["GUID"] = "7FF74F24",
            ["NextDialogue"] = 51117003,
            ["TalkActionId"] = {
                [1] = "701021:Angry01_End",
                [2] = "701022:Angry01_End",
                },
            },
        [51117003] = {
            ["Content"] = "{性别：大哥哥|大姐姐}，{性别：大哥哥|大姐姐}！你说呢？",
            ["ContentFR"] = "Hé ! {性别:Monsieur|Mademoiselle} ! Vous en pensez quoi ?",
            ["DialogueId"] = 51117003,
            ["GUID"] = "7FF74F4E",
            ["LookAt"] = {
                [1] = "701021:n(100001)",
                [2] = "701022:n(100001)",
                },
            ["NextOptions"] = {
                [1] = 51117004,
                },
            ["SpeakNpcId"] = 701021,
            },
        [51117004] = {
            ["Content"] = "我说什么？",
            ["ContentFR"] = "<I>De quoi exactement ?</>",
            ["DialogueId"] = 51117004,
            ["GUID"] = "7FF74F78",
            ["NextDialogue"] = 51117005,
            },
        [51117005] = {
            ["Content"] = "你说那个白色的影子到底是什么？",
            ["ContentFR"] = "De cette ombre blanche !",
            ["DialogueId"] = 51117005,
            ["GUID"] = "7FF74FA2",
            ["NextDialogue"] = 51117006,
            ["SpeakNpcId"] = 701021,
            ["TalkActionId"] = {
                [1] = "701021:Think_Start",
                },
            },
        [51117006] = {
            ["Content"] = "什么白色的影子？",
            ["ContentFR"] = "Quelle ombre blanche ?",
            ["DialogueId"] = 51117006,
            ["GUID"] = "7FF74FCC",
            ["NextDialogue"] = 51117007,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "701021:Think_End",
                },
            },
        [51117007] = {
            ["Camera"] = "807.511719,-81.339844,690.010742,0.000093,5.194338,77.734879,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "就是旁边的这间宅子里出现的那个呀！我们几个都看见过。",
            ["ContentFR"] = "Celle qui apparaît dans la maison juste à côté ! On l’a tous vue !",
            ["DialogueId"] = 51117007,
            ["GUID"] = "7FF74FF6",
            ["NextDialogue"] = 51117008,
            ["SpeakNpcId"] = 701021,
            },
        [51117008] = {
            ["Content"] = "那白色的影子会飞，会浮在空中，还会突然出现、突然消失，你觉得那到底是什么？",
            ["ContentFR"] = "Elle vole, elle flotte dans les airs, elle apparaît et disparaît d’un coup... À votre avis, c’est quoi ?",
            ["DialogueId"] = 51117008,
            ["GUID"] = "7FF75020",
            ["NextDialogue"] = 51117009,
            ["SpeakNpcId"] = 701021,
            },
        [51117009] = {
            ["Camera"] = "-102.625977,389.867188,178.47168,0.000117,-10.004881,-94.054535,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我觉得是狴犴！身为执法者，狴犴在有人的地方要时刻保持威严，但一直这样多累呀，所以它们会偷偷跑进这间没人的宅子里嬉戏玩耍。",
            ["ContentFR"] = "Moi je dis que c’est un Bi’an ! En tant qu’exécuteurs de la loi, ils doivent toujours rester dignes quand il y a du monde. Mais à force, ça doit être épuisant ! Alors ils se faufilent sûrement dans cette maison vide pour jouer un peu.",
            ["DialogueId"] = 51117009,
            ["GUID"] = "7FF7504A",
            ["LookAt"] = {
                [1] = "701021:n(701022)",
                [2] = "701022:n(701021)",
                [3] = "100001:n(701022)",
                },
            ["NextDialogue"] = 51117010,
            ["SpeakNpcId"] = 701022,
            ["TalkActionId"] = {
                [1] = "701022:Talk01_Start",
                },
            },
        [51117010] = {
            ["Content"] = "说什么傻话呢，狴犴可是大风九章的使者，又不是你家的狗狗，才不需要玩呢！而且这座宅子最近有人住了。",
            ["ContentFR"] = "N’importe quoi ! Les Bi’an sont les émissaires des Neuf Chapitres de Dafeng, pas des chiens de compagnie ! Et puis cette maison n’est plus vide, quelqu’un y vit maintenant.",
            ["DialogueId"] = 51117010,
            ["GUID"] = "7FF75074",
            ["LookAt"] = {
                [1] = "100001:n(701021)",
                },
            ["NextDialogue"] = 51117011,
            ["SpeakNpcId"] = 701021,
            ["TalkActionId"] = {
                [1] = "701022:Talk01_End",
                },
            },
        [51117011] = {
            ["Content"] = "我觉得那个白色影子一定是无由生。它可能是这个宅子的上一任主人变的，因为太喜欢这座宅子，所以不愿意离开……",
            ["ContentFR"] = "Moi, je pense que c’est forcément un Wishen. Peut-être l’ancien propriétaire de la maison... Trop attaché à cet endroit pour accepter de partir.",
            ["DialogueId"] = 51117011,
            ["GUID"] = "7FF7509E",
            ["NextDialogue"] = 51117012,
            ["SpeakNpcId"] = 701021,
            ["TalkActionId"] = {
                [1] = "701021:Talk02_Start",
                },
            },
        [51117012] = {
            ["Content"] = "如果真的是宅子主人变的，怎么会现在才出现呢？",
            ["ContentFR"] = "Si c’était vraiment l’ancien propriétaire, pourquoi il n’apparaîtrait que maintenant ?",
            ["DialogueId"] = 51117012,
            ["GUID"] = "7FF750C8",
            ["LookAt"] = {
                [1] = "100001:n(701022)",
                },
            ["NextDialogue"] = 51117013,
            ["SpeakNpcId"] = 701022,
            ["TalkActionId"] = {
                [1] = "701021:Talk02_End",
                },
            },
        [51117013] = {
            ["Content"] = "无由生可以活很久很久，说不定它之前是出门玩了呀。",
            ["ContentFR"] = "Les Wishen peuvent vivre très, très longtemps ! Peut-être qu’il était simplement parti se promener avant !",
            ["DialogueId"] = 51117013,
            ["GUID"] = "7FF750F2",
            ["LookAt"] = {
                [1] = "100001:n(701021)",
                },
            ["NextDialogue"] = 51117014,
            ["SpeakNpcId"] = 701021,
            },
        [51117014] = {
            ["Content"] = "可是无由生的颜色也不是白的呀！",
            ["ContentFR"] = "Mais les Wishen ne sont pas blancs !",
            ["DialogueId"] = 51117014,
            ["GUID"] = "7FF7511C",
            ["LookAt"] = {
                [1] = "100001:n(701022)",
                },
            ["NextDialogue"] = 51117015,
            ["SpeakNpcId"] = 701022,
            ["TalkActionId"] = {
                [1] = "701022:Explain01_Start",
                },
            },
        [51117015] = {
            ["Content"] = "你怎么知道没有白的无由生？无由生才会飞，狴犴又不会飞。",
            ["ContentFR"] = "Et comment tu sais qu’il n’existe pas de Wishen blancs ? Les Wishen peuvent voler, les Bi’an non !",
            ["DialogueId"] = 51117015,
            ["GUID"] = "7FF75146",
            ["LookAt"] = {
                [1] = "100001:n(701021)",
                },
            ["NextDialogue"] = 51117016,
            ["SpeakNpcId"] = 701021,
            ["TalkActionId"] = {
                [1] = "701022:Explain01_End",
                },
            },
        [51117016] = {
            ["Content"] = "你怎么知道没有会飞的狴犴？",
            ["ContentFR"] = "Et comment tu sais qu’il n’existe pas de Bi’an qui volent ?",
            ["DialogueId"] = 51117016,
            ["GUID"] = "7FF75170",
            ["LookAt"] = {
                [1] = "100001:n(701022)",
                },
            ["NextDialogue"] = 51117017,
            ["SpeakNpcId"] = 701022,
            },
        [51117017] = {
            ["Content"] = "……哼！{性别：大哥哥|大姐姐}，你说呢，你觉得那是无由生还是狴犴？",
            ["ContentFR"] = "... <I>Hmpf !</> {性别:Monsieur|Mademoiselle}, dites-nous : Wishen ou Bi’an ?",
            ["DialogueId"] = 51117017,
            ["GUID"] = "7FF7519A",
            ["LookAt"] = {
                [1] = "701021:n(100001)",
                [2] = "701022:n(100001)",
                },
            ["NextOptions"] = {
                [1] = 51117018,
                },
            ["RestartTag"] = 51117017,
            ["SpeakNpcId"] = 701021,
            },
        [51117018] = {
            ["Content"] = "（白色影子吗……会是什么呢？）",
            ["ContentFR"] = "<I>Une ombre blanche... qu’est-ce que ça pourrait bien être ?</>",
            ["DialogueId"] = 51117018,
            ["FailDialogue"] = 51117019,
            ["GUID"] = "7FF751C4",
            ["ImprCheckId"] = 1125,
            ["NextDialogue"] = 51117020,
            },
        [51117019] = {
            ["Content"] = "（一时没想到答案。）",
            ["ContentFR"] = "Aucune idée ne vous vient.",
            ["DialogueId"] = 51117019,
            ["GUID"] = "7FF751EE",
            },
        [51117020] = {
            ["Content"] = "我觉得你们说的都不对。我猜那个白色影子是住在这里的人养的小宠物。",
            ["ContentFR"] = "Je pense que vous avez tous les deux tort. À mon avis, c’est simplement le petit animal de compagnie de la personne qui habite ici.",
            ["DialogueId"] = 51117020,
            ["GUID"] = "7FF75218",
            ["NextDialogue"] = 51117021,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Talk01_Start",
                },
            },
        [51117021] = {
            ["Content"] = "啊……？",
            ["ContentFR"] = "Hein... ?",
            ["DialogueId"] = 51117021,
            ["GUID"] = "7FF75242",
            ["NextDialogue"] = 51117022,
            ["SpeakNpcId"] = 701021,
            },
        [51117022] = {
            ["Content"] = "小宠物……是说小猫小狗吗？可是我们看到的那个影子会瞬间消失诶！",
            ["ContentFR"] = "Un animal de compagnie ? Comme un chat ou un chien ? Mais cette ombre disparaît instantanément !",
            ["DialogueId"] = 51117022,
            ["GUID"] = "7FF7526C",
            ["NextDialogue"] = 51117023,
            ["SpeakNpcId"] = 701021,
            ["TalkActionId"] = {
                [1] = "701021:Talk02_Start",
                },
            },
        [51117023] = {
            ["Content"] = "对呀，而且它有时候飞得特别快，比我们家的小猫被擀面杖吓得跳起来的速度还快。",
            ["ContentFR"] = "Oui ! Et parfois elle va super vite, encore plus vite que notre chat quand il sursaute à cause du rouleau à pâtisserie !",
            ["DialogueId"] = 51117023,
            ["GUID"] = "7FF75296",
            ["NextDialogue"] = 51117024,
            ["SpeakNpcId"] = 701022,
            ["TalkActionId"] = {
                [1] = "701022:Think_Start",
                [2] = "701021:Talk02_End",
                },
            },
        [51117024] = {
            ["Content"] = "不信的话，你们就敲门问问看。",
            ["ContentFR"] = "Si vous ne me croyez pas, vous n’avez qu’à aller frapper à la porte et demander.",
            ["DialogueId"] = 51117024,
            ["GUID"] = "7FF752C0",
            ["NextDialogue"] = 51117025,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "701022:Think_End",
                },
            },
        [51117025] = {
            ["Content"] = "可、可是里面住的是个陌生人……",
            ["ContentFR"] = "M-Mais... la personne qui habite là est une inconnue...",
            ["DialogueId"] = 51117025,
            ["GUID"] = "7FF752EA",
            ["NextDialogue"] = 51117026,
            ["SpeakNpcId"] = 701021,
            ["TalkActionId"] = {
                [1] = "100001:Talk01_End",
                },
            },
        [51117026] = {
            ["Content"] = "听我外婆讲，这个宅子里住的好像是很厉害的大人物，万一那个大人物听了生气了怎么办？",
            ["ContentFR"] = "Ma grand-mère dit que c’est quelqu’un de très important. Et si on la mettait en colère ?",
            ["DialogueId"] = 51117026,
            ["GUID"] = "7FF75314",
            ["NextDialogue"] = 51117028,
            ["SpeakNpcId"] = 701022,
            },
        [51117027] = {
            ["Content"] = "第三个小孩入场",
            ["ContentFR"] = "Un troisième enfant s’approche.",
            ["DialogueId"] = 51117027,
            ["GUID"] = "7FF7533E",
            },
        [51117028] = {
            ["Camera"] = "-183.449219,717.648438,135.62793,0.000058,-3.004539,-77.045387,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "咦？兰叶，望南，你们两个怎么在这里呀？",
            ["ContentFR"] = "Oh ? Lan Ye, Wang Nan, qu’est-ce que vous faites ici ?",
            ["DialogueId"] = 51117028,
            ["GUID"] = "7FF75368",
            ["LookAt"] = {
                [1] = "701021:n(701023)",
                [2] = "701022:n(701023)",
                [3] = "100001:n(701023)",
                [4] = "701023:n(100001)",
                },
            ["NextDialogue"] = 51117029,
            ["Scripts"] = "MoveTo{ActorId{701023},TargetPoint{\"YuXian_Target\"},MoveSpeed{100},Visibility{\"Show\"}}",
            ["SpeakNpcId"] = 701023,
            },
        [51117029] = {
            ["Camera"] = "-157.855469,429.066406,150.193359,0.000067,-5.60486,-83.644531,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我们正在辩论那个白色影子的真身呢！",
            ["ContentFR"] = "On débat sur la véritable nature de l’ombre blanche !",
            ["DialogueId"] = 51117029,
            ["GUID"] = "7FF75392",
            ["LookAt"] = {
                [1] = "701021:n(701021)",
                [2] = "701022:n(701021)",
                [3] = "100001:n(701021)",
                [4] = "701023:n(701021)",
                },
            ["NextDialogue"] = 51117030,
            ["SpeakNpcId"] = 701021,
            },
        [51117030] = {
            ["Content"] = "噢，这个呀，我已经知道啦。我昨天经过这里的时候恰好遇见了住在里面的姐姐，她说那个白色的影子是“鱼龙”。",
            ["ContentFR"] = "Ah, ça ! Je sais déjà ce que c’est. Hier, je suis tombée sur la mademoiselle qui habite ici. Elle m’a dit que cette ombre blanche s’appelait un « Poisson-Dragon ».",
            ["DialogueId"] = 51117030,
            ["GUID"] = "7FF753BC",
            ["LookAt"] = {
                [1] = "701021:n(701023)",
                [2] = "701022:n(701023)",
                [3] = "100001:n(701023)",
                [4] = "701023:n(701023)",
                },
            ["NextDialogue"] = 51117031,
            ["SpeakNpcId"] = 701023,
            ["TalkActionId"] = {
                [1] = "701023:Explain01_Start",
                },
            },
        [51117031] = {
            ["Content"] = "她解释了一大堆什么“寄托”呀，“思念”呀什么的，我不太听得懂……反正就是类似于小宠物的东西啦！",
            ["ContentFR"] = "Elle m’a expliqué plein de choses sur les « liens », les « souvenirs » et tout ça... j’ai pas tout compris. Mais en gros, c’est comme un petit animal de compagnie !",
            ["DialogueId"] = 51117031,
            ["GUID"] = "7FF753E6",
            ["NextDialogue"] = 51117032,
            ["SpeakNpcId"] = 701023,
            },
        [51117032] = {
            ["Content"] = "她还变了一只出来给我看呢，“鱼龙”摸上去就像水做的一样，凉凉的，可神奇了！",
            ["ContentFR"] = "Elle en a même invoqué un pour me montrer ! On aurait dit de l’eau vivante, tout frais et tout doux... c’était incroyable !",
            ["DialogueId"] = 51117032,
            ["GUID"] = "7FF75410",
            ["NextDialogue"] = 51117033,
            ["SpeakNpcId"] = 701023,
            ["TalkActionId"] = {
                [1] = "701023:Explain01_End",
                },
            },
        [51117033] = {
            ["Content"] = "什么？！",
            ["ContentFR"] = "Quoi ?!",
            ["DialogueId"] = 51117033,
            ["GUID"] = "7FF7543A",
            ["LookAt"] = {
                [1] = "701021:n(701021)",
                [2] = "701022:n(701021)",
                [3] = "100001:n(701021)",
                [4] = "701023:n(701021)",
                },
            ["NextDialogue"] = 51117034,
            ["SpeakNpcId"] = 701021,
            },
        [51117034] = {
            ["Content"] = "居、居然真的是小宠物……",
            ["ContentFR"] = "A-Alors c’était vraiment un animal...",
            ["DialogueId"] = 51117034,
            ["GUID"] = "7FF75464",
            ["LookAt"] = {
                [1] = "701021:n(701022)",
                [2] = "701022:n(701022)",
                [3] = "100001:n(701022)",
                [4] = "701023:n(701022)",
                },
            ["NextDialogue"] = 51117035,
            ["SpeakNpcId"] = 701023,
            },
        [51117035] = {
            ["Content"] = "没想到最后是这个{性别：大哥哥|大姐姐}猜对了……",
            ["ContentFR"] = "Je pensais que {性别:ce Monsieur|cette Mademoiselle} plaisantait...",
            ["DialogueId"] = 51117035,
            ["GUID"] = "7FF7548E",
            ["LookAt"] = {
                [1] = "701021:n(100001)",
                [2] = "701022:n(100001)",
                [3] = "100001:n(100001)",
                [4] = "701023:n(100001)",
                },
            ["NextOptions"] = {
                [1] = 51117036,
                [2] = 51117040,
                [3] = 51117044,
                },
            ["SpeakNpcId"] = 701021,
            },
        [51117036] = {
            ["Content"] = "其实是因为我也见过那位姐姐，所以才能猜对的。",
            ["ContentFR"] = "<I>En fait, c’est parce que j’ai déjà rencontré cette personne que j’ai pu deviner.</>",
            ["DialogueId"] = 51117036,
            ["GUID"] = "7FF754B8",
            ["ImprPlusId"] = 1207,
            ["NextDialogue"] = 51117037,
            },
        [51117037] = {
            ["Content"] = "怎么你也见过？那我也要见。",
            ["ContentFR"] = "Quoi, toi aussi tu l’as vue ? Alors moi aussi je veux la rencontrer !",
            ["DialogueId"] = 51117037,
            ["GUID"] = "7FF754E2",
            ["LookAt"] = {
                [1] = "701021:n(701023)",
                [2] = "701022:n(701021)",
                [3] = "100001:n(701021)",
                [4] = "701023:n(701021)",
                },
            ["NextDialogue"] = 51117038,
            ["SpeakNpcId"] = 701021,
            ["TalkActionId"] = {
                [1] = "701021:Talk01_Start",
                },
            },
        [51117038] = {
            ["Content"] = "我也要，我也要！",
            ["ContentFR"] = "Moi aussi ! Moi aussi !",
            ["DialogueId"] = 51117038,
            ["GUID"] = "7FF7550C",
            ["LookAt"] = {
                [1] = "701021:n(701023)",
                [2] = "701022:n(701023)",
                [3] = "100001:n(701022)",
                [4] = "701023:n(701022)",
                },
            ["NextDialogue"] = 51117039,
            ["SpeakNpcId"] = 701022,
            },
        [51117039] = {
            ["Content"] = "嗯……那下次我们带点好吃的去找那个姐姐玩，让她也给我们看看“鱼龙”吧~",
            ["ContentFR"] = "Alors la prochaine fois, on apportera quelque chose de bon à manger et on ira lui rendre visite ! Peut-être qu’elle nous montrera encore le Poisson-Dragon~",
            ["DialogueId"] = 51117039,
            ["GUID"] = "7FF75536",
            ["NextDialogue"] = 51117048,
            ["SpeakNpcId"] = 701021,
            ["TalkActionId"] = {
                [1] = "701021:Talk01_End",
                },
            },
        [51117040] = {
            ["Content"] = "也可能你们看到的是其他的白色影子。",
            ["ContentFR"] = "<I>Ou alors, vous avez peut-être vu une autre ombre blanche.</>",
            ["DialogueId"] = 51117040,
            ["GUID"] = "7FF75560",
            ["ImprPlusId"] = 1209,
            ["NextDialogue"] = 51117041,
            },
        [51117041] = {
            ["Content"] = "有道理诶！",
            ["ContentFR"] = "Oh... c’est vrai !",
            ["DialogueId"] = 51117041,
            ["GUID"] = "7FF7558A",
            ["LookAt"] = {
                [1] = "701021:n(701021)",
                [2] = "701022:n(701021)",
                [3] = "100001:n(701021)",
                [4] = "701023:n(701021)",
                },
            ["NextDialogue"] = 51117042,
            ["SpeakNpcId"] = 701021,
            ["TalkActionId"] = {
                [1] = "701021:Talk01_Start",
                },
            },
        [51117042] = {
            ["Content"] = "也许这宅子里既有鱼龙，也有狴犴，还有无由生！",
            ["ContentFR"] = "Peut-être qu’il y a un Poisson-Dragon, un Bi’an et un Wishen tous ensemble dans cette maison !",
            ["DialogueId"] = 51117042,
            ["GUID"] = "7FF755B4",
            ["NextDialogue"] = 51117043,
            ["SpeakNpcId"] = 701021,
            },
        [51117043] = {
            ["Content"] = "那我们都说对了，好耶~",
            ["ContentFR"] = "Alors on avait tous raison ! Trop bien~",
            ["DialogueId"] = 51117043,
            ["GUID"] = "7FF755DE",
            ["LookAt"] = {
                [1] = "701021:n(701022)",
                [2] = "701022:n(701022)",
                [3] = "100001:n(701022)",
                [4] = "701023:n(701022)",
                },
            ["NextDialogue"] = 51117048,
            ["SpeakNpcId"] = 701022,
            ["TalkActionId"] = {
                [1] = "701021:Talk01_End",
                },
            },
        [51117044] = {
            ["Content"] = "哼哼，这就是大人的实力。",
            ["ContentFR"] = "<I>Héhé, c’est ça la puissance des adultes.</>",
            ["DialogueId"] = 51117044,
            ["GUID"] = "7FF75608",
            ["ImprPlusId"] = 1210,
            ["NextDialogue"] = 51117045,
            },
        [51117045] = {
            ["Content"] = "那我长大以后也要变得这么聪明。",
            ["ContentFR"] = "Quand je serai grand, je serai aussi intelligent !",
            ["DialogueId"] = 51117045,
            ["GUID"] = "7FF75632",
            ["LookAt"] = {
                [1] = "701021:n(701022)",
                [2] = "701022:n(701022)",
                [3] = "100001:n(701022)",
                [4] = "701023:n(701022)",
                },
            ["NextDialogue"] = 51117046,
            ["SpeakNpcId"] = 701022,
            ["TalkActionId"] = {
                [1] = "701022:Talk01_Start",
                },
            },
        [51117046] = {
            ["Content"] = "我要变得比这个{性别：大哥哥|大姐姐}还聪明！",
            ["ContentFR"] = "Moi, je serai encore plus intelligent que {性别:ce Monsieur|cette Mademoiselle} !",
            ["DialogueId"] = 51117046,
            ["GUID"] = "7FF7565C",
            ["LookAt"] = {
                [1] = "701021:n(701022)",
                [2] = "701022:n(701022)",
                [3] = "100001:n(701022)",
                [4] = "701023:n(701022)",
                },
            ["NextDialogue"] = 51117047,
            ["SpeakNpcId"] = 701021,
            ["TalkActionId"] = {
                [1] = "701022:Talk01_End",
                },
            },
        [51117047] = {
            ["Content"] = "那你们还在这儿玩什么呀，赶快回去做功课啦。",
            ["ContentFR"] = "Dans ce cas, pourquoi vous traînez encore ici ? Allez faire vos devoirs ! Rester à bavarder ne vous rendra pas plus malins.",
            ["DialogueId"] = 51117047,
            ["GUID"] = "7FF75686",
            ["LookAt"] = {
                [1] = "701021:n(701023)",
                [2] = "701022:n(701023)",
                [3] = "100001:n(701023)",
                [4] = "701023:n(701023)",
                },
            ["NextDialogue"] = 51117048,
            ["SpeakNpcId"] = 701023,
            },
        [51117048] = {
            ["Content"] = "（孩子们有说有笑地离开了。也许，下次见到扶疏的时候，可以把这件趣闻说给她听听。）",
            ["ContentFR"] = "Les enfants s’en vont en riant. Peut-être que la prochaine fois que vous verrez Fushu, vous pourrez lui raconter cette amusante anecdote.",
            ["DialogueId"] = 51117048,
            ["GUID"] = "7FF756B0",
            ["Scripts"] = "PARA{\
MoveTo{ActorId{701021},TargetPoint{\"LanYe_Leave_Target\"},MoveSpeed{100},Visibility{\"Hide\"}},\
MoveTo{ActorId{701022},TargetPoint{\"WangNan_Leave_Target\"},MoveSpeed{100},Visibility{\"Hide\"}},\
MoveTo{ActorId{701023},TargetPoint{\"YuXian_Leave_Target\"},MoveSpeed{100},Visibility{\"Hide\"}}\
}",
            },
        [51118000] = {
            ["Content"] = "呜……怎么还没来……",
            ["ContentFR"] = "Hnn... pourquoi il n’est toujours pas là...",
            ["DialogueId"] = 51118000,
            ["GUID"] = "7FF7F2E0",
            ["NextDialogue"] = 51118001,
            ["SpeakNpcId"] = 701024,
            ["TalkActionId"] = {
                [1] = "701024:Sigh_Start",
                },
            },
        [51118001] = {
            ["Content"] = "（小女孩半睁着眼睛，坐在屋檐下嘟囔着什么。当你经过的时候，她忽然一头栽倒在地。）",
            ["ContentFR"] = "À demi assoupie, la petite fille marmonne sous l’auvent d’une maison. Lorsque vous passez près d’elle, elle bascule soudainement en avant et s’effondre.",
            ["DialogueId"] = 51118001,
            ["GUID"] = "7FF7F30A",
            ["NextDialogue"] = 51118002,
            },
        [51118002] = {
            ["Content"] = "哎？！",
            ["ContentFR"] = "Eh ?!",
            ["DialogueId"] = 51118002,
            ["GUID"] = "7FF7F334",
            ["NextDialogue"] = 51118003,
            ["SpeakNpcId"] = 100001,
            },
        [51118003] = {
            ["Content"] = "（你连忙上前查看。被你拍了拍肩膀之后，小女孩睁开眼睛，从地上爬了起来。）",
            ["ContentFR"] = "Vous vous précipitez pour l’aider. Après une légère tape sur l’épaule, la fillette entrouvre les yeux et se redresse tant bien que mal.",
            ["DialogueId"] = 51118003,
            ["GUID"] = "7FF7F35E",
            ["NextDialogue"] = 51118004,
            },
        [51118004] = {
            ["Content"] = "唔……",
            ["ContentFR"] = "Mmmh...",
            ["DialogueId"] = 51118004,
            ["GUID"] = "7FF7F388",
            ["NextOptions"] = {
                [1] = 51118005,
                },
            ["SpeakNpcId"] = 701024,
            },
        [51118005] = {
            ["Content"] = "小妹妹，你还好吗？",
            ["ContentFR"] = "<I>Petite, ça va ?</>",
            ["DialogueId"] = 51118005,
            ["GUID"] = "7FF7F3B2",
            ["NextDialogue"] = 51118006,
            },
        [51118006] = {
            ["Content"] = "啊，我没事，我只是太困了……谢谢你，{性别：大哥哥|大姐姐}。",
            ["ContentFR"] = "Ah... ça va. Je suis juste vraiment très fatiguée... merci, {性别:Monsieur|Mademoiselle}.",
            ["DialogueId"] = 51118006,
            ["GUID"] = "7FF7F3DC",
            ["LookAt"] = {
                [1] = "701024:n(0)",
                },
            ["NextDialogue"] = 51118007,
            ["SpeakNpcId"] = 701024,
            ["TalkActionId"] = {
                [1] = "701024:Sigh_End",
                },
            },
        [51118007] = {
            ["Content"] = "既然困了，怎么不回去休息？",
            ["ContentFR"] = "Si tu es si fatiguée, pourquoi ne rentres-tu pas te reposer ?",
            ["DialogueId"] = 51118007,
            ["GUID"] = "7FF7F406",
            ["NextDialogue"] = 51118008,
            ["SpeakNpcId"] = 100001,
            },
        [51118008] = {
            ["Content"] = "我在等我哥哥！他是个织星客，平常总是在外面游历，但每年这个时候，他都会带礼物和信给我。",
            ["ContentFR"] = "J’attends mon grand frère ! C’est un Tisse-Étoiles. Il voyage tout le temps, mais chaque année à cette période, il m’apporte toujours des cadeaux et une lettre.",
            ["DialogueId"] = 51118008,
            ["GUID"] = "7FF7F430",
            ["NextDialogue"] = 51118009,
            ["SpeakNpcId"] = 701024,
            ["TalkActionId"] = {
                [1] = "701024:Talk02_Start",
                },
            },
        [51118009] = {
            ["Content"] = "不能在家里等吗？",
            ["ContentFR"] = "Tu ne pourrais pas l’attendre à l’intérieur ?",
            ["DialogueId"] = 51118009,
            ["GUID"] = "7FF7F45A",
            ["NextDialogue"] = 51118010,
            ["SpeakNpcId"] = 100001,
            },
        [51118010] = {
            ["Content"] = "那就会和他错过了。他每次来都不进家门，只会早早地把东西放在门口。等我起床看到的时候，他早就不见了。",
            ["ContentFR"] = "Si je fais ça, on se ratera encore. Il n’entre jamais dans la maison... Il dépose les affaires devant la porte très tôt, puis il repart. Quand je me lève, il est déjà loin.",
            ["DialogueId"] = 51118010,
            ["GUID"] = "7FF7F484",
            ["NextDialogue"] = 51118011,
            ["SpeakNpcId"] = 701024,
            },
        [51118011] = {
            ["Content"] = "所以我今年打算在门口等着，一定要当面见到他！",
            ["ContentFR"] = "Alors cette année, j’ai décidé d’attendre ici. Cette fois, je veux absolument le voir en vrai !",
            ["DialogueId"] = 51118011,
            ["GUID"] = "7FF7F4AE",
            ["NextDialogue"] = 51118012,
            ["SpeakNpcId"] = 701024,
            },
        [51118012] = {
            ["Content"] = "但我也不知道他会几点来，所以只好从三更天就开始等……哈欠……结果等到现在他也没来……哈欠……",
            ["ContentFR"] = "Mais je ne sais pas à quelle heure il vient... alors j’attends depuis le milieu de la nuit... haaah... et il n’est toujours pas venu... haaah...",
            ["DialogueId"] = 51118012,
            ["GUID"] = "7FF7F4D8",
            ["NextOptions"] = {
                [1] = 51118013,
                },
            ["RestartTag"] = 51118012,
            ["SpeakNpcId"] = 701024,
            ["TalkActionId"] = {
                [1] = "701024:Talk02_End",
                },
            },
        [51118013] = {
            ["Content"] = "（想想该怎么帮助她。）",
            ["ContentFR"] = "<I>Réfléchir à un moyen de l’aider</>",
            ["DialogueId"] = 51118013,
            ["FailDialogue"] = 51118014,
            ["GUID"] = "7FF7F502",
            ["ImprCheckId"] = 1126,
            ["NextDialogue"] = 51118015,
            },
        [51118014] = {
            ["Content"] = "（哈欠……你也有点困了。）",
            ["ContentFR"] = "Haaah... vous commencez vous aussi à piquer du nez.",
            ["DialogueId"] = 51118014,
            ["GUID"] = "7FF7F52C",
            },
        [51118015] = {
            ["Content"] = "会不会就是因为你在这里等着，所以他才不出现的？",
            ["ContentFR"] = "Et si justement, il ne venait pas parce qu’il t’a vue attendre ici ?",
            ["DialogueId"] = 51118015,
            ["GUID"] = "7FF7F556",
            ["NextDialogue"] = 51118016,
            ["SpeakNpcId"] = 100001,
            },
        [51118016] = {
            ["Content"] = "咦？什么意思？",
            ["ContentFR"] = "Hein ? Qu’est-ce que tu veux dire ?",
            ["DialogueId"] = 51118016,
            ["GUID"] = "7FF7F580",
            ["NextDialogue"] = 51118017,
            ["SpeakNpcId"] = 701024,
            ["TalkActionId"] = {
                [1] = "701024:Think_Start",
                },
            },
        [51118017] = {
            ["Content"] = "也许他是想要给你一个惊喜啊。",
            ["ContentFR"] = "Peut-être qu’il voulait te faire une surprise.",
            ["DialogueId"] = 51118017,
            ["GUID"] = "7FF7F5AA",
            ["NextDialogue"] = 51118018,
            ["SpeakNpcId"] = 100001,
            },
        [51118018] = {
            ["Content"] = "可是比起惊喜，我更想见到他……",
            ["ContentFR"] = "Mais... moi, je préfère le voir plutôt qu’avoir une surprise...",
            ["DialogueId"] = 51118018,
            ["GUID"] = "7FF7F5D4",
            ["NextDialogue"] = 51118019,
            ["SpeakNpcId"] = 701024,
            ["TalkActionId"] = {
                [1] = "701024:Think_End",
                },
            },
        [51118019] = {
            ["Content"] = "那我有个办法。",
            ["ContentFR"] = "Alors j’ai une idée.",
            ["DialogueId"] = 51118019,
            ["GUID"] = "7FF7F5FE",
            ["NextDialogue"] = 51118020,
            ["SpeakNpcId"] = 100001,
            },
        [51118020] = {
            ["Content"] = "你现在进屋去，假装休息。我到对面的角落帮你盯着这扇门，如果看到你哥哥出现，我就把他拦下来。怎么样？",
            ["ContentFR"] = "Rentre à l’intérieur et fais semblant de te reposer. Moi, je vais attendre de l’autre côté et surveiller la porte. Si ton frère arrive, je l’arrêterai. D’accord ?",
            ["DialogueId"] = 51118020,
            ["GUID"] = "7FF7F628",
            ["NextDialogue"] = 51118021,
            ["SpeakNpcId"] = 100001,
            },
        [51118021] = {
            ["Content"] = "哈欠……咦？！所以，{性别：大哥哥|大姐姐}你要帮我等吗？好呀好呀，你真是个好人！",
            ["ContentFR"] = "<I>Haaawn...</> hein ?! Tu veux bien attendre à ma place ? Vraiment ? Tu es trop {性别:gentil|gentille} !",
            ["DialogueId"] = 51118021,
            ["GUID"] = "7FF7F652",
            ["NextDialogue"] = 51118022,
            ["SpeakNpcId"] = 701024,
            },
        [51118022] = {
            ["Content"] = "你哥哥叫什么名字？",
            ["ContentFR"] = "Comment s’appelle ton frère ?",
            ["DialogueId"] = 51118022,
            ["GUID"] = "7FF7F67C",
            ["NextDialogue"] = 51118023,
            ["SpeakNpcId"] = 100001,
            },
        [51118023] = {
            ["Content"] = "他叫朝雨。",
            ["ContentFR"] = "Il s’appelle Zhaoyu.",
            ["DialogueId"] = 51118023,
            ["GUID"] = "7FF7F6A6",
            ["NextDialogue"] = 51118024,
            ["SpeakNpcId"] = 701024,
            },
        [51118024] = {
            ["Content"] = "好的，我记住了。",
            ["ContentFR"] = "D’accord, je m’en souviendrai.",
            ["DialogueId"] = 51118024,
            ["GUID"] = "7FF7F6D0",
            ["NextDialogue"] = 51118025,
            ["SpeakNpcId"] = 100001,
            },
        [51118025] = {
            ["Content"] = "（女孩揉着眼睛，晃晃悠悠地进屋休息去了。你来到角落，悄悄观察周围的动静。）",
            ["ContentFR"] = "La fillette se frotte les yeux et rentre en titubant à l’intérieur. Vous vous placez dans un coin et observez discrètement.",
            ["DialogueId"] = 51118025,
            ["GUID"] = "7FF7F6FA",
            },
        [51118026] = {
            ["Content"] = "（果不其然，就在女孩离开后没多久，一位青年男子便现身了。他四下打量了一番，飞快地将一个包裹放在了门口，然后转身离去。）",
            ["ContentFR"] = "Comme prévu, peu de temps après son départ, un jeune homme apparaît. Il regarde autour de lui, dépose rapidement un paquet devant la porte, puis s’apprête à partir.",
            ["DialogueId"] = 51118026,
            ["GUID"] = "7FF7F724",
            },
        [51118027] = {
            ["Content"] = "等等！",
            ["ContentFR"] = "Attendez !",
            ["DialogueId"] = 51118027,
            ["GUID"] = "7FF7F74E",
            ["LookAt"] = {
                [1] = "701025:n(0)",
                },
            ["NextDialogue"] = 51118028,
            ["SpeakNpcId"] = 100001,
            },
        [51118028] = {
            ["Content"] = "哎？！",
            ["ContentFR"] = "Hein ?!",
            ["DialogueId"] = 51118028,
            ["GUID"] = "7FF7F778",
            ["NextDialogue"] = 51118029,
            ["SpeakNpcId"] = 701025,
            ["TalkActionId"] = {
                [1] = "701025:Shock_Start",
                },
            },
        [51118029] = {
            ["Content"] = "你就是朝雨吧！",
            ["ContentFR"] = "Vous êtes Zhaoyu, n’est-ce pas ?",
            ["DialogueId"] = 51118029,
            ["GUID"] = "7FF7F7A2",
            ["NextDialogue"] = 51118030,
            ["SpeakNpcId"] = 100001,
            },
        [51118030] = {
            ["Content"] = "（听到这个名字，男子显得很惊讶。他愣了一会儿，然后才开口。）",
            ["ContentFR"] = "À l’évocation de ce nom, l’homme se fige. Après un long silence, il prend la parole.",
            ["DialogueId"] = 51118030,
            ["GUID"] = "7FF7F7CC",
            ["NextDialogue"] = 51118031,
            ["TalkActionId"] = {
                [1] = "701025:Shock_End",
                },
            },
        [51118031] = {
            ["Content"] = "不……我不是朝雨。",
            ["ContentFR"] = "Non... je ne suis pas Zhaoyu.",
            ["DialogueId"] = 51118031,
            ["GUID"] = "7FF7F7F6",
            ["NextDialogue"] = 51118032,
            ["SpeakNpcId"] = 701025,
            ["TalkActionId"] = {
                [1] = "701025:Talk01_Start",
                },
            },
        [51118032] = {
            ["Content"] = "你为何会知道这个名字？你认识他吗？",
            ["ContentFR"] = "Pourquoi connaissez-vous ce nom ? Le connaissez-vous ?",
            ["DialogueId"] = 51118032,
            ["GUID"] = "7FF7F820",
            ["NextDialogue"] = 51118033,
            ["SpeakNpcId"] = 701025,
            },
        [51118033] = {
            ["Content"] = "我认识他的妹妹，他妹妹一直在等他出现。",
            ["ContentFR"] = "Je connais sa petite sœur. Elle l’attend ici depuis des heures.",
            ["DialogueId"] = 51118033,
            ["GUID"] = "7FF7F84A",
            ["NextDialogue"] = 51118034,
            ["SpeakNpcId"] = 100001,
            },
        [51118034] = {
            ["Content"] = "是吗……原来青青一直坐在门口，是想见哥哥啊。",
            ["ContentFR"] = "... Je vois. Alors Qingqing attendait son frère.",
            ["DialogueId"] = 51118034,
            ["GUID"] = "7FF7F874",
            ["NextDialogue"] = 51118035,
            ["SpeakNpcId"] = 701025,
            ["TalkActionId"] = {
                [1] = "701025:Talk01_End",
                },
            },
        [51118035] = {
            ["Content"] = "但她怕是等不到了。",
            ["ContentFR"] = "Mais... elle ne pourra plus l’attendre.",
            ["DialogueId"] = 51118035,
            ["GUID"] = "7FF7F89E",
            ["NextDialogue"] = 51118036,
            ["SpeakNpcId"] = 701025,
            },
        [51118036] = {
            ["Content"] = "为什么？你是谁？",
            ["ContentFR"] = "Pourquoi ? Qui êtes-vous ?",
            ["DialogueId"] = 51118036,
            ["GUID"] = "7FF7F8C8",
            ["NextDialogue"] = 51118037,
            ["SpeakNpcId"] = 100001,
            },
        [51118037] = {
            ["Content"] = "我是朝雨的旧友。几年前，我们在同一个商队出海远航时，不慎遭遇了海难。朝雨他……为了救不通水性的我，不幸去世了。",
            ["ContentFR"] = "Je suis un vieil ami de Zhaoyu. Il y a quelques années, nous faisions partie du même convoi marchand en mer... Nous avons fait naufrage. Zhaoyu est mort en essayant de me sauver. Je ne savais pas nager.",
            ["DialogueId"] = 51118037,
            ["GUID"] = "7FF7F8F2",
            ["NextDialogue"] = 51118038,
            ["SpeakNpcId"] = 701025,
            ["TalkActionId"] = {
                [1] = "701025:Talk02_Start",
                },
            },
        [51118038] = {
            ["Content"] = "这份救命之恩，我无以为报……但至少不忍看他疼爱的幼妹伤心，所以就想了这个办法。",
            ["ContentFR"] = "Je ne pourrai jamais lui rendre cette dette... Mais je ne supportais pas l’idée que la petite sœur qu’il chérissait vive dans le chagrin.",
            ["DialogueId"] = 51118038,
            ["GUID"] = "7FF7F91C",
            ["NextDialogue"] = 51118039,
            ["SpeakNpcId"] = 701025,
            },
        [51118039] = {
            ["Content"] = "在青青成年之前，我会假装成朝雨，每年给她送来礼物和信件。",
            ["ContentFR"] = "Alors j’ai décidé de prendre sa place. Jusqu’à ce que Qingqing devienne adulte, je lui apporterai chaque année des cadeaux et des lettres, comme s’il était encore en vie.",
            ["DialogueId"] = 51118039,
            ["GUID"] = "7FF7F946",
            ["NextDialogue"] = 51118040,
            ["SpeakNpcId"] = 701025,
            },
        [51118040] = {
            ["Content"] = "竟然是这样……",
            ["ContentFR"] = "... Je comprends.",
            ["DialogueId"] = 51118040,
            ["GUID"] = "7FF7F970",
            ["NextDialogue"] = 51118041,
            ["SpeakNpcId"] = 100001,
            },
        [51118041] = {
            ["Content"] = "是的……所以，还请你对青青保密。",
            ["ContentFR"] = "Alors, je vous en prie... gardez le secret pour elle.",
            ["DialogueId"] = 51118041,
            ["GUID"] = "7FF7F99A",
            ["NextDialogue"] = 51118042,
            ["SpeakNpcId"] = 701025,
            ["TalkActionId"] = {
                [1] = "701025:Talk02_End",
                },
            },
        [51118042] = {
            ["Content"] = "我明白了。",
            ["ContentFR"] = "Je le ferai.",
            ["DialogueId"] = 51118042,
            ["GUID"] = "7FF7F9C4",
            ["SpeakNpcId"] = 100001,
            },
        [51118043] = {
            ["Camera"] = "-82.615234,229.359375,122.754883,0.0,-0.800191,-69.000504,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "（你思考了一会儿，然后敲了敲门。）",
            ["ContentFR"] = "Après un instant de réflexion, vous frappez doucement à la porte.",
            ["DialogueId"] = 51118043,
            ["GUID"] = "7FF7F9EE",
            ["IsBlack"] = 1,
            ["LookAt"] = {
                [1] = "701024:n(100001)",
                [2] = "100001:n(701024)",
                },
            ["NextDialogue"] = 51118062,
            },
        [51118044] = {
            ["Content"] = "青青？",
            ["ContentFR"] = "<I>Qingqing ?</>",
            ["DialogueId"] = 51118044,
            ["GUID"] = "7FF7FA18",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 51118045,
            },
        [51118045] = {
            ["Content"] = "{性别：大哥哥|大姐姐}，怎么啦？咦，你手上那是——是哥哥来了吗？他在哪里？",
            ["ContentFR"] = "Oui ? {性别:Monsieur|Mademoiselle} ? Eh ? C’est quoi, ce paquet... ? Mon frère est venu ? Où est-il ?",
            ["DialogueId"] = 51118045,
            ["GUID"] = "7FF7FA42",
            ["NextDialogue"] = 51118046,
            ["SpeakNpcId"] = 701024,
            ["TalkActionId"] = {
                [1] = "701024:Talk01_Start",
                },
            },
        [51118046] = {
            ["Content"] = "他已经走了。",
            ["ContentFR"] = "Il est déjà reparti.",
            ["DialogueId"] = 51118046,
            ["GUID"] = "7FF7FA6C",
            ["NextDialogue"] = 51118047,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "701024:Talk01_End",
                [2] = "100001:Talk02_Start",
                },
            },
        [51118047] = {
            ["Content"] = "什么？你不是答应我要拦下他的吗？呜呜……",
            ["ContentFR"] = "Quoi ?! Mais tu avais promis de l’arrêter... <I>snif...</>",
            ["DialogueId"] = 51118047,
            ["GUID"] = "7FF7FA96",
            ["NextOptions"] = {
                [1] = 51118048,
                [2] = 51118052,
                },
            ["SpeakNpcId"] = 701024,
            ["TalkActionId"] = {
                [1] = "100001:Talk02_End",
                },
            },
        [51118048] = {
            ["Content"] = "你哥哥工作很辛苦，不想让你担心。",
            ["ContentFR"] = "<I>Ton frère travaille très dur. Il ne voulait pas t’inquiéter.</>",
            ["DialogueId"] = 51118048,
            ["GUID"] = "7FF7FAC0",
            ["ImprPlusId"] = 1209,
            ["NextDialogue"] = 51118049,
            },
        [51118049] = {
            ["Content"] = "他说自己常年风餐露宿，消瘦了不少，怕你看见会担心，所以才不露面。我看他好像很累，就没有强行拦下他。",
            ["ContentFR"] = "Il m’a dit qu’il vivait dehors depuis longtemps, qu’il avait beaucoup maigri... Il avait peur que tu t’inquiètes en le voyant. Il avait l’air très fatigué, alors je ne l’ai pas retenu.",
            ["DialogueId"] = 51118049,
            ["GUID"] = "7FF7FAEA",
            ["NextDialogue"] = 51118050,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Explain01_Start",
                },
            },
        [51118050] = {
            ["Content"] = "居然是这样……可是见不到他我会更担心呀，笨哥哥……",
            ["ContentFR"] = "Vraiment... ? Mais ne pas le voir m’inquiète encore plus... quel idiot...",
            ["DialogueId"] = 51118050,
            ["GUID"] = "7FF7FB14",
            ["NextDialogue"] = 51118051,
            ["SpeakNpcId"] = 701024,
            ["TalkActionId"] = {
                [1] = "100001:Explain01_End",
                [2] = "701024:Think_Start",
                },
            },
        [51118051] = {
            ["Content"] = "他说等他身体好一点，就一定会回来看你的。在那之前，你要照顾好自己。",
            ["ContentFR"] = "Il a dit que lorsqu’il irait un peu mieux, il reviendrait te voir. En attendant, tu dois bien prendre soin de toi.",
            ["DialogueId"] = 51118051,
            ["GUID"] = "7FF7FB3E",
            ["NextDialogue"] = 51118058,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "701024:Think_End",
                },
            },
        [51118052] = {
            ["Content"] = "你哥哥在参加一场超级商战，分秒必争！",
            ["ContentFR"] = "<I>Ton frère participe à une grande « guerre commerciale ». Chaque seconde compte !</>",
            ["DialogueId"] = 51118052,
            ["GUID"] = "7FF7FB68",
            ["ImprPlusId"] = 1208,
            ["NextDialogue"] = 51118053,
            },
        [51118053] = {
            ["Content"] = "“商战”……？那是什么？",
            ["ContentFR"] = "Une... guerre commerciale ? C’est quoi ?",
            ["DialogueId"] = 51118053,
            ["GUID"] = "7FF7FB92",
            ["NextDialogue"] = 51118054,
            ["SpeakNpcId"] = 701024,
            ["TalkActionId"] = {
                [1] = "701024:Think_Start",
                },
            },
        [51118054] = {
            ["Content"] = "商战就是一种比谁挣钱更多、更快的游戏。你哥哥想要赢下第一名，所以一秒钟都不能耽误呢！",
            ["ContentFR"] = "C’est un jeu pour savoir qui gagne le plus d’argent, le plus vite. Ton frère veut arriver premier, alors il ne peut pas perdre une seule seconde.",
            ["DialogueId"] = 51118054,
            ["GUID"] = "7FF7FBBC",
            ["NextDialogue"] = 51118055,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Explain01_Start",
                },
            },
        [51118055] = {
            ["Content"] = "刚才他一放下礼物就跑了，这些还是他的同事告诉我的。",
            ["ContentFR"] = "Il a déposé le cadeau et est reparti aussitôt. Ce sont ses collègues qui me l’ont expliqué.",
            ["DialogueId"] = 51118055,
            ["GUID"] = "7FF7FBE6",
            ["NextDialogue"] = 51118056,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Explain01_End",
                },
            },
        [51118056] = {
            ["Content"] = "原来是这样啊！那我要给哥哥加油！",
            ["ContentFR"] = "Ah d’accord ! Alors je vais l’encourager !",
            ["DialogueId"] = 51118056,
            ["GUID"] = "7FF7FC10",
            ["NextDialogue"] = 51118057,
            ["SpeakNpcId"] = 701024,
            ["TalkActionId"] = {
                [1] = "701024:Think_End",
                },
            },
        [51118057] = {
            ["Content"] = "他说你只要照顾好自己就行了，等他赢了游戏，一定会回来看你的。",
            ["ContentFR"] = "Il a dit que tu devais simplement bien prendre soin de toi. Quand il gagnera, il reviendra te voir.",
            ["DialogueId"] = 51118057,
            ["GUID"] = "7FF7FC3A",
            ["NextDialogue"] = 51118058,
            ["SpeakNpcId"] = 100001,
            },
        [51118058] = {
            ["Content"] = "嗯嗯，那我要回去好好睡一觉，不然哥哥会担心的……",
            ["ContentFR"] = "Alors je vais rentrer dormir un peu... sinon, il va s’inquiéter...",
            ["DialogueId"] = 51118058,
            ["GUID"] = "7FF7FC64",
            ["NextDialogue"] = 51118059,
            ["SpeakNpcId"] = 701024,
            ["TalkActionId"] = {
                [1] = "701024:Talk02_Start",
                },
            },
        [51118059] = {
            ["Content"] = "谢谢你帮我，{性别：大哥哥|大姐姐}，再见……哈欠……",
            ["ContentFR"] = "Merci pour ton aide, {性别:Monsieur|Mademoiselle}... à bientôt... <I>haaawn...</>",
            ["DialogueId"] = 51118059,
            ["GUID"] = "7FF7FC8E",
            ["NextDialogue"] = 51118060,
            ["SpeakNpcId"] = 701024,
            ["TalkActionId"] = {
                [1] = "701024:Talk02_End",
                },
            },
        [51118060] = {
            ["Content"] = "（女孩给了你报酬，然后带着一脸满足的笑容接过礼物，进屋去了。）",
            ["ContentFR"] = "La fillette vous remet votre récompense, prend son cadeau avec un sourire apaisé, puis rentre à l’intérieur.",
            ["DialogueId"] = 51118060,
            ["GUID"] = "7FF7FCB8",
            ["NextDialogue"] = 51118061,
            },
        [51118061] = {
            ["Content"] = "（等到真相被揭穿的那一天，她还能再露出这样的笑容吗……？）",
            ["ContentFR"] = "Lorsque la vérité éclatera un jour... pourra-t-elle encore sourire ainsi ?",
            ["DialogueId"] = 51118061,
            ["GUID"] = "7FF7FCE2",
            },
        [51118062] = {
            ["Content"] = "（青青打着哈欠走了出来。）",
            ["ContentFR"] = "Qingqing sort en bâillant.",
            ["DialogueId"] = 51118062,
            ["GUID"] = "7FF7FD0C",
            ["IsBlack"] = 1,
            ["NextOptions"] = {
                [1] = 51118044,
                },
            },
        [51119000] = {
            ["Content"] = "金口一张白龙降，折扇轻摇故事来。诸位乡亲，诸位父老，诸位不远万里来到华胥的外乡客，大家且听我一言！",
            ["ContentFR"] = "D’un mot, le Dragon d’Argent descend, d’un éventail, l’histoire prend son élan. Chers voisins, honorables anciens, voyageurs venus de loin jusqu’à Huaxu, accordez-moi un instant !",
            ["DialogueId"] = 51119000,
            ["GUID"] = "7FF896F0",
            ["NextDialogue"] = 51119001,
            ["SpeakNpcId"] = 701026,
            ["TalkActionId"] = {
                [1] = "701026:Talk01_Start",
                },
            },
        [51119001] = {
            ["Content"] = "鄙人名唤权都通，曾被白龙神君赐号——全通先生。平时最爱与诸位挚爱亲朋分享这世间百态趣事，今日便有一桩趣闻想与各位说道说道。",
            ["ContentFR"] = "Je me nomme Quan Doutong. Il fut un temps où le Seigneur Dragon d’Argent me gratifia d’un titre — Maître-Qui-Sait-Tout. J’ai pour plaisir de partager avec mes proches et amis les mille curiosités du monde, et justement, aujourd’hui, j’ai une anecdote savoureuse à vous conter.",
            ["DialogueId"] = 51119001,
            ["GUID"] = "7FF8971A",
            ["NextDialogue"] = 51119002,
            ["SpeakNpcId"] = 701026,
            },
        [51119002] = {
            ["Content"] = "不过呢……今日天气燥热，我这喉咙啊也焦渴难耐，若是诸位能先赏点银钱让我买壶茶水润润喉咙，或许这故事就能说得更好。",
            ["ContentFR"] = "Mais hélas... la chaleur est étouffante, et ma gorge est aussi sèche qu’un parchemin ancien. Si quelques âmes généreuses consentaient à me donner un peu d’argent\
pour acheter une théière et m’humecter le gosier, alors ce récit n’en serait que meilleur.",
            ["DialogueId"] = 51119002,
            ["GUID"] = "7FF89744",
            ["LookAt"] = {
                [1] = "701026:n(0)",
                },
            ["NextOptions"] = {
                [1] = 51119003,
                [2] = 51119005,
                [3] = 51119007,
                },
            ["SpeakNpcId"] = 701026,
            ["TalkActionId"] = {
                [1] = "701026:Talk01_End",
                },
            },
        [51119003] = {
            ["Content"] = "白龙神君赐号？骗人的吧？",
            ["ContentFR"] = "<I>Le Seigneur Dragon d’Argent t’aurait accordé un titre ? Tu inventes, non ?</>",
            ["DialogueId"] = 51119003,
            ["GUID"] = "7FF8976E",
            ["ImprPlusId"] = 1208,
            ["NextDialogue"] = 51119004,
            },
        [51119004] = {
            ["Content"] = "名号的确是假的，白龙神君并未与我赐号，但要不是如此吆喝，如何才能让诸位听众驻足呢？白龙神君即使知晓，想必也不会怪罪于我。",
            ["ContentFR"] = "Certes, ce titre est une invention — le Seigneur Dragon d’Argent ne m’a jamais honoré ainsi. Mais sans un peu d’emphase, comment espérer retenir votre attention ? Et même s’il l’apprenait, j’ose croire qu’il ne m’en tiendrait pas rigueur.",
            ["DialogueId"] = 51119004,
            ["GUID"] = "7FF89798",
            ["NextDialogue"] = 51119009,
            ["SpeakNpcId"] = 701026,
            },
        [51119005] = {
            ["Content"] = "你得说的好才能讨钱吧。",
            ["ContentFR"] = "<I>Encore faut-il que l’histoire en vaille la peine.</>",
            ["DialogueId"] = 51119005,
            ["GUID"] = "7FF897C2",
            ["ImprPlusId"] = 1206,
            ["NextDialogue"] = 51119006,
            },
        [51119006] = {
            ["Content"] = "这位外乡客说的是，此举只凭自愿，绝无要挟之意，只是看各位父老是否愿意先让我们龙君青睐的信众喝上口水，解我燃喉之急啊。",
            ["ContentFR"] = "L’{性别:étranger|étrangère} a raison. Tout ceci repose sur le volontariat, jamais sur la contrainte. Je me demande seulement si quelques respectables habitants souhaitent offrir une gorgée d’eau à un conteur dévoué au Dragon d’Argent, afin d’apaiser sa gorge en feu.",
            ["DialogueId"] = 51119006,
            ["GUID"] = "7FF897EC",
            ["NextDialogue"] = 51119009,
            ["SpeakNpcId"] = 701026,
            },
        [51119007] = {
            ["Content"] = "（给他点银钱买茶水。）",
            ["ContentFR"] = "<I>Donner quelques pièces pour acheter du thé</>",
            ["DialogueId"] = 51119007,
            ["GUID"] = "7FF89816",
            ["ImprPlusId"] = 1209,
            ["NextDialogue"] = 51119008,
            },
        [51119008] = {
            ["Content"] = "感谢感谢，外乡客，鄙人记住你的恩情了。",
            ["ContentFR"] = "Mille mercis, {性别:étranger|étrangère}. Je n’oublierai pas cette générosité.",
            ["DialogueId"] = 51119008,
            ["GUID"] = "7FF89840",
            ["NextDialogue"] = 51119009,
            ["SpeakNpcId"] = 701026,
            },
        [51119009] = {
            ["Content"] = "（一些不差钱的围观者递上了银钱，远处很快跑来一名端茶之人，这权都通接过紫砂壶，猛地灌了一口，这才继续说起来。）",
            ["ContentFR"] = "Quelques spectateurs aisés tendent des pièces. Un porteur de thé accourt depuis le fond de la rue. Quan Doutong saisit la théière de terre cuite, en boit une longue gorgée, puis reprend son récit.",
            ["DialogueId"] = 51119009,
            ["GUID"] = "7FF8986A",
            ["NextDialogue"] = 51119010,
            },
        [51119010] = {
            ["Content"] = "感谢诸位信任，今日，我权都通就为大家说上一个我才听说的趣闻。",
            ["ContentFR"] = "Merci de votre confiance. Aujourd’hui, moi, Quan Doutong, vais vous conter une histoire que j’ai entendue tout récemment.",
            ["DialogueId"] = 51119010,
            ["GUID"] = "7FF89894",
            ["NextDialogue"] = 51119011,
            ["SpeakNpcId"] = 701026,
            ["TalkActionId"] = {
                [1] = "701026:Talk02_Start",
                },
            },
        [51119011] = {
            ["Content"] = "这华胥境内，哪里最繁华？自然是那皓京城中，这事儿，就发生在皓京。皓京城内呢，有一条狭窄的小巷，巷子两边都住着一户人家，一家姓吕，一家姓马。",
            ["ContentFR"] = "À Huaxu, quel lieu est le plus florissant ? Haojing, bien sûr. Et c’est précisément là-bas que notre histoire commence. Dans Haojing, il existait une ruelle étroite. De chaque côté vivaient deux familles : l’une se nommait Lü, l’autre Ma.",
            ["DialogueId"] = 51119011,
            ["GUID"] = "7FF898BE",
            ["NextDialogue"] = 51119012,
            ["SpeakNpcId"] = 701026,
            },
        [51119012] = {
            ["Content"] = "这两家，平日相处很是和睦，端的是相敬如宾啊，但天有变迁，这皓京城内的天禄司，因着皓京城许多住宅年久失修问题，要各家上报宅邸面积。",
            ["ContentFR"] = "Ces deux foyers vivaient d’ordinaire en parfaite harmonie, se respectant comme de véritables invités l’un envers l’autre. Mais le temps changea, et le Bureau de la Fortune Céleste de Haojing, souhaitant restaurer de nombreuses habitations délabrées, exigea que chaque famille déclare la superficie de son logement.",
            ["DialogueId"] = 51119012,
            ["GUID"] = "7FF898E8",
            ["NextDialogue"] = 51119013,
            ["SpeakNpcId"] = 701026,
            },
        [51119013] = {
            ["Content"] = "这事闹得，上报上去的面积到时候可就是天禄司需要出钱的部分了，为着让上面多关照自家，这吕马两家啊，不约而同都开始琢磨起了扩建一事。",
            ["ContentFR"] = "Or, la surface déclarée déterminait la somme que le Bureau de la Fortune Céleste devait verser. Désireuses d’attirer davantage de faveur, les familles Lü et Ma se mirent, sans se concerter, à envisager un agrandissement.",
            ["DialogueId"] = 51119013,
            ["GUID"] = "7FF89912",
            ["NextDialogue"] = 51119014,
            ["SpeakNpcId"] = 701026,
            },
        [51119014] = {
            ["Content"] = "但这小巷之间的地块此前并非两家所属，但也并无文书说明巷中空地归属，这一下可就陷入了僵局。",
            ["ContentFR"] = "Mais le terrain situé entre les deux maisons n’appartenait officiellement à aucune d’elles, et aucun document n’en précisait la propriété. Ainsi, la situation se retrouva dans une impasse.",
            ["DialogueId"] = 51119014,
            ["GUID"] = "7FF8993C",
            ["NextDialogue"] = 51119015,
            ["SpeakNpcId"] = 701026,
            },
        [51119015] = {
            ["Content"] = "吕家说自己院中种了棵梨树，树荫早已罩住巷子，所以那地该是自家的。",
            ["ContentFR"] = "La famille Lü déclara qu’un poirier poussait dans sa cour et que son ombre couvrait déjà la ruelle : le terrain devait donc lui revenir.",
            ["DialogueId"] = 51119015,
            ["GUID"] = "7FF89966",
            ["NextDialogue"] = 51119016,
            ["SpeakNpcId"] = 701026,
            },
        [51119016] = {
            ["Content"] = "马家却说自己原先一直将家中香料放在巷内晾晒，吕家也从未提出异议，说明这地该是他家的呀。",
            ["ContentFR"] = "La famille Ma répliqua qu’elle y faisait sécher ses épices depuis des années, sans jamais rencontrer d’opposition — preuve que cette terre était la sienne.",
            ["DialogueId"] = 51119016,
            ["GUID"] = "7FF89990",
            ["NextDialogue"] = 51119017,
            ["SpeakNpcId"] = 701026,
            },
        [51119017] = {
            ["Content"] = "这双方，各执一词，那是吵个昏天黑地，要不是咱们大风九章在上，肯定是要撕打起来的。",
            ["ContentFR"] = "Chacun campait sur ses positions, et la dispute devint si violente que, sans la présence des Neuf Chapitres de Dafeng, ils en seraient venus aux mains.",
            ["DialogueId"] = 51119017,
            ["GUID"] = "7FF899BA",
            ["NextDialogue"] = 51119018,
            ["SpeakNpcId"] = 701026,
            ["TalkActionId"] = {
                [1] = "701026:Talk02_End",
                },
            },
        [51119018] = {
            ["Content"] = "但话又说到这了，两家都有理，难道此事就没办法了吗？",
            ["ContentFR"] = "Mais puisque chacun avait ses raisons, fallait-il vraiment admettre qu’il n’existait aucune solution ?",
            ["DialogueId"] = 51119018,
            ["GUID"] = "7FF899E4",
            ["NextDialogue"] = 51119019,
            ["SpeakNpcId"] = 701026,
            },
        [51119019] = {
            ["Content"] = "（权都通特意顿了一下，似乎在吊人胃口。）",
            ["ContentFR"] = "Quan Doutong marque volontairement une pause, entretenant le suspense.",
            ["DialogueId"] = 51119019,
            ["GUID"] = "7FF89A0E",
            ["NextDialogue"] = 51119020,
            },
        [51119020] = {
            ["Content"] = "对了，大家可别忘了，那可是皓京城，自然是有着许多管理邻里纷争的调解人。",
            ["ContentFR"] = "N’oubliez pas : nous sommes à Haojing, où ne manquent pas les médiateurs chargés\
de régler les conflits de voisinage.",
            ["DialogueId"] = 51119020,
            ["GUID"] = "7FF89A38",
            ["NextDialogue"] = 51119021,
            ["SpeakNpcId"] = 701026,
            ["TalkActionId"] = {
                [1] = "701026:Explain01_Start",
                },
            },
        [51119021] = {
            ["Content"] = "那调解人，一听说此事，便马不停蹄地赶去了，调解者一听两家说出了自己的理由，却是幽幽一笑，当场作诗一首：",
            ["ContentFR"] = "L’un d’eux, averti de l’affaire, accourut sans tarder. Après avoir écouté les deux parties, il esquissa un sourire discret et improvisa un poème :",
            ["DialogueId"] = 51119021,
            ["GUID"] = "7FF89A62",
            ["NextDialogue"] = 51119022,
            ["SpeakNpcId"] = 701026,
            },
        [51119022] = {
            ["Content"] = "黑蛟鼓惑恶念起，龙君一怒断嗔痴。几番无果闹荒唐，让他三尺又何妨？",
            ["ContentFR"] = "« Le dragon noir attise les pensées mauvaises, la colère du Dragon d’Argent tranche l’avidité. Les querelles vaines sèment le chaos — céder trois pas, n’est-ce pas sagesse ? »",
            ["DialogueId"] = 51119022,
            ["GUID"] = "7FF89A8C",
            ["NextDialogue"] = 51119023,
            ["SpeakNpcId"] = 701026,
            },
        [51119023] = {
            ["Content"] = "诶呀！这话的意思说明什么？诸位听众可能听出来？这是要将这争吵不停的二人比作神话里那为非作歹的黑蛟一般，要与白龙神君劝人向善之心对着来！",
            ["ContentFR"] = "Voyez-vous le sens de ces vers ? Il comparait les deux familles au dragon noir malfaisant des légendes, s’opposant aux enseignements bienveillants du Dragon d’Argent.",
            ["DialogueId"] = 51119023,
            ["GUID"] = "7FF89AB6",
            ["NextDialogue"] = 51119024,
            ["SpeakNpcId"] = 701026,
            },
        [51119024] = {
            ["Content"] = "那烛阴恶兽因心生恶念，被白龙神君封印于荒野，而今日，为何在这泱泱华胥又生出贪嗔之人啊？此话一出，两家讪讪，不再争执，各自回去了。",
            ["ContentFR"] = "Le monstre Zhuyin, rongé par la malveillance, fut jadis scellé dans les terres sauvages par le Dragon d’Argent. Alors pourquoi, en cette noble Huaxu, laisser naître l’avidité et la colère ? À ces mots, les deux familles, honteuses, cessèrent leur querelle et rentrèrent chez elles.",
            ["DialogueId"] = 51119024,
            ["GUID"] = "7FF89AE0",
            ["NextDialogue"] = 51119025,
            ["SpeakNpcId"] = 701026,
            },
        [51119025] = {
            ["Content"] = "于是吕家回去后，为表自己诚心，拆了自家院墙向后三尺，在门口立上了一座白龙神君的雕像。那马家见状，也将自己院墙拆除，向后三尺，摆了同样的雕像。",
            ["ContentFR"] = "Pour prouver leur sincérité, la famille Lü démolit son mur d’enceinte et le recula de trois pas, érigeant à l’entrée une statue du Dragon d’Argent. La famille Ma, voyant cela, fit de même.",
            ["DialogueId"] = 51119025,
            ["GUID"] = "7FF89B0A",
            ["NextDialogue"] = 51119026,
            ["SpeakNpcId"] = 701026,
            },
        [51119026] = {
            ["Content"] = "喜哉乐哉！息事宁哉！这巷子后来也成了附近邻居们每每发生争执之时前往理论之地，为的就是让白龙神君见证自己的虔诚之心，从未动摇啊！",
            ["ContentFR"] = "Quelle joie ! Quelle paix retrouvée ! Par la suite, cette ruelle devint le lieu où les voisins se rendaient lors de tout différend, afin de laisser le Dragon d’Argent témoigner de leur bonne foi.",
            ["DialogueId"] = 51119026,
            ["GUID"] = "7FF89B34",
            ["NextDialogue"] = 51119027,
            ["SpeakNpcId"] = 701026,
            },
        [51119027] = {
            ["Content"] = "今日鄙人便斗胆改一下诗句，不若改为“向善之心何以见，三尺之争见真心。”诸位看客以为如何？",
            ["ContentFR"] = "Aujourd’hui, permettez-moi d’adapter ces vers : « Comment prouver un cœur tourné vers le bien ? Dans trois pas cédés, se révèle la sincérité. » Qu’en pensez-vous, chers spectateurs ?",
            ["DialogueId"] = 51119027,
            ["GUID"] = "7FF89B5E",
            ["NextDialogue"] = 51119028,
            ["SpeakNpcId"] = 701026,
            ["TalkActionId"] = {
                [1] = "701026:Explain01_End",
                },
            },
        [51119028] = {
            ["Content"] = "（路人纷纷向其喝彩，夸赞起白龙神君，权都通又收到了许多打赏，人群逐渐散去……）",
            ["ContentFR"] = "La foule applaudit chaleureusement et loue le Dragon d’Argent. Quan Doutong reçoit encore plusieurs offrandes, puis les passants se dispersent peu à peu.",
            ["DialogueId"] = 51119028,
            ["GUID"] = "7FF89B88",
            ["Scripts"] = "PARA{\
MoveTo{ActorId{701081},TargetPoint{\"quandoutong_show1\"},MoveSpeed{100},Visibility{\"Hide\"}},\
MoveTo{ActorId{701082},TargetPoint{\"quandoutong_show2\"},MoveSpeed{100},Visibility{\"Hide\"}},\
MoveTo{ActorId{701083},TargetPoint{\"quandoutong_show3\"},MoveSpeed{100},Visibility{\"Hide\"}},\
MoveTo{ActorId{701084},TargetPoint{\"quandoutong_show4\"},MoveSpeed{100},Visibility{\"Hide\"}},\
MoveTo{ActorId{701085},TargetPoint{\"quandoutong_show5\"},MoveSpeed{100},Visibility{\"Hide\"}},\
MoveTo{ActorId{701086},TargetPoint{\"quandoutong_show6\"},MoveSpeed{100},Visibility{\"Hide\"}}\
}",
            },
        [51119029] = {
            ["Content"] = "有钱的捧个钱场，没钱的捧个人场！",
            ["ContentFR"] = "Les riches peuvent donner de l’argent, les autres n’ont qu’à faire acte de présence !",
            ["DialogueId"] = 51119029,
            ["GUID"] = "7FF89BB2",
            ["SpeakNpcId"] = 701026,
            },
        [51120000] = {
            ["Content"] = "黄药师，此药服用后有何注意事项？可有忌口？",
            ["ContentFR"] = "Apothicaire Huang, après avoir pris ce remède... y a-t-il des précautions à prendre ? Des aliments à éviter ?",
            ["DialogueId"] = 51120000,
            ["GUID"] = "7FF93B00",
            ["LookAt"] = {
                [1] = "701028:n(701027)",
                [2] = "701027:n(701028)",
                },
            ["NextDialogue"] = 51120001,
            ["SpeakNpcId"] = 701028,
            ["TalkActionId"] = {
                [1] = "701028:Talk01_Start",
                },
            },
        [51120001] = {
            ["Content"] = "自然是有的，你要记得，药效如何全依据你是否遵守我以下所说：",
            ["ContentFR"] = "Bien sûr que oui. Et retiens bien ceci : l’efficacité du traitement dépend entièrement de ta capacité à suivre ce que je vais te dire.",
            ["DialogueId"] = 51120001,
            ["GUID"] = "7FF93B2A",
            ["NextDialogue"] = 51120002,
            ["SpeakNpcId"] = 701027,
            ["TalkActionId"] = {
                [1] = "701028:Talk01_End",
                },
            },
        [51120002] = {
            ["Content"] = "其一，这药不可空腹服下，否则体重不减反增。你需一日三餐都吃半饱以上，方可服用。",
            ["ContentFR"] = "Premièrement : ce remède ne doit jamais être pris à jeun. Sinon, non seulement tu ne maigriras pas, mais tu risques même de prendre du poids. Tu devras donc manger trois repas par jour, au moins jusqu’à être à moitié rassasiée, avant chaque prise.",
            ["DialogueId"] = 51120002,
            ["GUID"] = "7FF93B54",
            ["NextDialogue"] = 51120003,
            ["SpeakNpcId"] = 701027,
            ["TalkActionId"] = {
                [1] = "701027:Talk02_Start",
                },
            },
        [51120003] = {
            ["Content"] = "其二，这药副作用猛烈，你需努力运动，我给你一本册子，你按这上面，每日运动一个时辰，直至大汗淋漓，我这药带来的副作用才可被排出。",
            ["ContentFR"] = "Deuxièmement : les effets secondaires sont puissants. Il te faudra donc faire de l’exercice. Tiens, je vais te donner un livret : suis les exercices indiqués et entraîne-toi chaque jour pendant une heure entière, jusqu’à transpirer abondamment. Ce n’est qu’ainsi que les effets indésirables pourront être évacués.",
            ["DialogueId"] = 51120003,
            ["GUID"] = "7FF93B7E",
            ["NextDialogue"] = 51120004,
            ["SpeakNpcId"] = 701027,
            },
        [51120004] = {
            ["Content"] = "其三，我这药最忌断药，你此次只从我这里买了一月的用量，一月后你需要尽快来我这购入下一月的，若是断药，则你前一个月的效果全都前功尽弃！",
            ["ContentFR"] = "Troisièmement : il est absolument interdit d’interrompre le traitement. Tu n’as acheté qu’un mois de remèdes ; une fois ce mois écoulé, tu devras revenir immédiatement pour le suivant. Si tu arrêtes en cours de route, tous les efforts du premier mois seront réduits à néant.",
            ["DialogueId"] = 51120004,
            ["GUID"] = "7FF93BA8",
            ["NextDialogue"] = 51120005,
            ["SpeakNpcId"] = 701027,
            },
        [51120005] = {
            ["Content"] = "就是这三点，你可记住了？",
            ["ContentFR"] = "Voilà les trois règles. Tu les as bien retenues ?",
            ["DialogueId"] = 51120005,
            ["GUID"] = "7FF93BD2",
            ["NextDialogue"] = 51120006,
            ["SpeakNpcId"] = 701027,
            ["TalkActionId"] = {
                [1] = "701027:Talk02_End",
                },
            },
        [51120006] = {
            ["Content"] = "药师，我这记住是记住了，但这么复杂的要求，你真能保证我在三个月内瘦成一道闪电吗？",
            ["ContentFR"] = "Je... oui, je crois. Mais avec des conditions aussi strictes... pouvez-vous vraiment garantir que je serai mince comme l’éclair en trois mois ?",
            ["DialogueId"] = 51120006,
            ["GUID"] = "7FF93BFC",
            ["NextDialogue"] = 51120007,
            ["SpeakNpcId"] = 701028,
            ["TalkActionId"] = {
                [1] = "701028:Think_Start",
                },
            },
        [51120007] = {
            ["Content"] = "小雁啊小雁，我黄药师何曾骗过人？若不是我的药灵验，你又如何才能找到我这来？",
            ["ContentFR"] = "Ah, Yan, Yan... est-ce que je t’ai déjà menti, ne serait-ce qu’une fois ? Si mes remèdes n’étaient pas efficaces, comment aurais-tu seulement entendu parler de moi ?",
            ["DialogueId"] = 51120007,
            ["GUID"] = "7FF93C26",
            ["NextDialogue"] = 51120008,
            ["SpeakNpcId"] = 701027,
            },
        [51120008] = {
            ["Content"] = "好……好像是这个道理……我明白了，这次一定要瘦下去！",
            ["ContentFR"] = "E-Eh bien... c’est vrai... Je comprends. Cette fois, je vais vraiment maigrir !",
            ["DialogueId"] = 51120008,
            ["GUID"] = "7FF93C50",
            ["NextDialogue"] = 51120009,
            ["SpeakNpcId"] = 701028,
            ["TalkActionId"] = {
                [1] = "701028:Think_End",
                },
            },
        }
  end },
  { MinKey = 51120009, MaxKey = 51125051, Loader = function()
      return {
        [51120009] = {
            ["Content"] = "（名唤小雁的女孩手持一瓶药，兴致勃勃地跑走了。）",
            ["ContentFR"] = "La jeune fille nommée Yan serre son flacon contre elle et s’en va en courant, pleine d’enthousiasme.",
            ["DialogueId"] = 51120009,
            ["GUID"] = "7FF93C7A",
            ["NextDialogue"] = 51120010,
            ["Scripts"] = "MoveTo{ActorId{701028},TargetPoint{\"LuoYan_Target\"},MoveSpeed{200},Visibility{\"Hide\"}}",
            },
        [51120010] = {
            ["Content"] = "客人好性子，在此处等待如此之久，定是有药相求，说吧，是保身体康健，还是如刚才的小姑娘一般，求个身材窈窕？",
            ["ContentFR"] = "{性别:Vous êtes patient, cher client, d’avoir attendu si longtemps. J’imagine que vous êtes venu|Vous êtes patiente, chère cliente, d’avoir attendue si longtemps. J’imagine que vous êtes venue} chercher un remède ? Pour la santé du corps... ou pour une silhouette plus élancée, comme cette jeune fille ?",
            ["DialogueId"] = 51120010,
            ["GUID"] = "7FF93CA4",
            ["LookAt"] = {
                [1] = "701027:n(0)",
                },
            ["NextOptions"] = {
                [1] = 51120011,
                [2] = 51120013,
                [3] = 51120015,
                },
            ["SpeakNpcId"] = 701027,
            },
        [51120011] = {
            ["Content"] = "你刚才说的要求，不用吃药也可以瘦下来吧……",
            ["ContentFR"] = "<I>Avec vos conditions, elle pourrait maigrir sans même prendre de médicament...</>",
            ["DialogueId"] = 51120011,
            ["GUID"] = "7FF93CCE",
            ["ImprPlusId"] = 1208,
            ["NextDialogue"] = 51120012,
            },
        [51120012] = {
            ["Content"] = "哦？客人聪明呀，这种事情都被你看出来了，的确如此，若是她严格按照我的要求行事，不出三月，恐怕两月便心想事成。",
            ["ContentFR"] = "Oh ? Vous avez l’œil. En effet, si elle suivait strictement mes recommandations, deux mois suffiraient sans doute — trois au grand maximum.",
            ["DialogueId"] = 51120012,
            ["GUID"] = "7FF93CF8",
            ["NextDialogue"] = 51120017,
            ["SpeakNpcId"] = 701027,
            },
        [51120013] = {
            ["Content"] = "你不会是在卖假药吧？",
            ["ContentFR"] = "<I>Vous ne seriez pas en train de vendre de faux remèdes, par hasard ?</>",
            ["DialogueId"] = 51120013,
            ["GUID"] = "7FF93D22",
            ["ImprPlusId"] = 1207,
            ["NextDialogue"] = 51120014,
            },
        [51120014] = {
            ["Content"] = "假药？如何见得？那姑娘现在还没服下一口，客人您也未见成效，如何能断定我卖的是假药呢？",
            ["ContentFR"] = "Des faux remèdes ? Sur quoi vous basez-vous ? Elle n’a pas encore avalé une seule dose, et vous n’avez vu aucun résultat. N’est-ce pas un peu hâtif de m’accuser ?",
            ["DialogueId"] = 51120014,
            ["GUID"] = "7FF93D4C",
            ["NextDialogue"] = 51120017,
            ["SpeakNpcId"] = 701027,
            },
        [51120015] = {
            ["Content"] = "你得给我开点封口费了吧。",
            ["ContentFR"] = "<I>Il va falloir me payer pour que je garde le silence.</>",
            ["DialogueId"] = 51120015,
            ["GUID"] = "7FF93D76",
            ["ImprPlusId"] = 1206,
            ["NextDialogue"] = 51120016,
            },
        [51120016] = {
            ["Content"] = "封口费？为何？我在这交易之地，做着你情我愿的买卖，也不违反大风九章，如何会需要到给客人您封口费的地步呢？",
            ["ContentFR"] = "Du silence ? Pourquoi donc ? Ici, je fais commerce librement, sans enfreindre les Neuf Chapitres de Dafeng. Pourquoi aurais-je besoin de soudoyer qui que ce soit ?",
            ["DialogueId"] = 51120016,
            ["GUID"] = "7FF93DA0",
            ["NextDialogue"] = 51120017,
            ["SpeakNpcId"] = 701027,
            },
        [51120017] = {
            ["Content"] = "你卖给她的究竟是什么？",
            ["ContentFR"] = "Alors... qu’est-ce que vous lui avez vraiment vendu ?",
            ["DialogueId"] = 51120017,
            ["GUID"] = "7FF93DCA",
            ["NextDialogue"] = 51120018,
            ["SpeakNpcId"] = 100001,
            },
        [51120018] = {
            ["Content"] = "客人既然已经知晓，何必再假意询问，卖的自然是让她心想事成之药，必能达成她心之所愿。",
            ["ContentFR"] = "Puisque vous avez déjà compris, inutile de feindre l’ignorance. Je lui ai vendu un remède qui exauce les souhaits — celui qui lui permettra d’atteindre ce qu’elle désire au fond d’elle-même.",
            ["DialogueId"] = 51120018,
            ["GUID"] = "7FF93DF4",
            ["NextDialogue"] = 51120019,
            ["SpeakNpcId"] = 701027,
            ["TalkActionId"] = {
                [1] = "701027:Explain01_Start",
                },
            },
        [51120019] = {
            ["Content"] = "……所以还是假药喽？万一她吃出什么毛病怎么办？",
            ["ContentFR"] = "... Donc c’est bien un faux remède ? Et si elle tombait malade ?",
            ["DialogueId"] = 51120019,
            ["GUID"] = "7FF93E1E",
            ["NextDialogue"] = 51120020,
            ["SpeakNpcId"] = 100001,
            },
        [51120020] = {
            ["Content"] = "呵呵，客人心地善良，但我黄药师也不是什么奸恶之人，不做谋财害命之事。那小姑娘体态康健，却执意想通过节食和药物减肥，实非明智之举。",
            ["ContentFR"] = "Heh. Vous avez bon cœur. Mais je ne suis pas un escroc qui joue avec la vie des gens. Cette jeune fille est en parfaite santé, pourtant elle s’obstinait à vouloir maigrir par la faim et les potions — ce qui est profondément déraisonnable.",
            ["DialogueId"] = 51120020,
            ["GUID"] = "7FF93E48",
            ["NextDialogue"] = 51120021,
            ["SpeakNpcId"] = 701027,
            ["TalkActionId"] = {
                [1] = "701027:Explain01_End",
                },
            },
        [51120021] = {
            ["Content"] = "所以我建议她好好吃饭的同时，给她开了些补剂，里面掺的是一人日常所需的营养，免得她运动后气血亏空，瘫倒在地啊。",
            ["ContentFR"] = "Je lui ai donc conseillé de manger correctement, et je lui ai donné des compléments contenant les nutriments nécessaires à son corps, afin qu’elle ne s’effondre pas après l’exercice.",
            ["DialogueId"] = 51120021,
            ["GUID"] = "7FF93E72",
            ["NextDialogue"] = 51120022,
            ["SpeakNpcId"] = 701027,
            ["TalkActionId"] = {
                [1] = "701027:Talk01_Start",
                },
            },
        [51120022] = {
            ["Content"] = "你很懂啊？",
            ["ContentFR"] = "Vous vous y connaissez, finalement.",
            ["DialogueId"] = 51120022,
            ["GUID"] = "7FF93E9C",
            ["NextDialogue"] = 51120023,
            ["SpeakNpcId"] = 100001,
            },
        [51120023] = {
            ["Content"] = "诶？不敢很懂，只敢略懂，客人，小药师我只是做着一些小本生意，勉强在这黑市混口饭吃而已。",
            ["ContentFR"] = "Oh, je n’oserais pas dire cela. Disons simplement que je m’y connais un peu. Je ne suis qu’un humble apothicaire, survivant tant bien que mal dans ce marché noir.",
            ["DialogueId"] = 51120023,
            ["GUID"] = "7FF93EC6",
            ["NextDialogue"] = 51120024,
            ["SpeakNpcId"] = 701027,
            ["TalkActionId"] = {
                [1] = "701027:Talk01_End",
                },
            },
        [51120024] = {
            ["Content"] = "所以别的药你也是一样的卖法？用补剂代替药品。",
            ["ContentFR"] = "Vous procédez de la même manière pour vos autres remèdes ? Des compléments à la place de médicaments ?",
            ["DialogueId"] = 51120024,
            ["GUID"] = "7FF93EF0",
            ["NextDialogue"] = 51120025,
            ["SpeakNpcId"] = 100001,
            },
        [51120025] = {
            ["Content"] = "你们这些家伙总是喜欢刨根问底，有些事睁一只眼闭一只眼便算了罢。我也并未害人，只是让他们以正确的方式去达成他们的目的。",
            ["ContentFR"] = "Vous aimez vraiment fouiller jusqu’au bout, vous autres. Certaines choses méritent qu’on ferme un œil. Je n’ai jamais fait de mal à personne — je les aide simplement à atteindre leurs objectifs par les bons moyens.",
            ["DialogueId"] = 51120025,
            ["GUID"] = "7FF93F1A",
            ["NextDialogue"] = 51120026,
            ["SpeakNpcId"] = 701027,
            ["TalkActionId"] = {
                [1] = "701027:Talk02_Start",
                },
            },
        [51120026] = {
            ["Content"] = "想要长寿，那便早睡早起，健康饮食，想要美丽，那便香薰敷面，减少操劳。客人对药的定义还是过于狭隘了不是吗？",
            ["ContentFR"] = "Qui cherche la longévité doit bien dormir et bien manger. Qui cherche la beauté doit prendre soin de soi et ménager ses efforts. Votre définition du mot « remède » n’est-elle pas un peu trop étroite ?",
            ["DialogueId"] = 51120026,
            ["GUID"] = "7FF93F44",
            ["NextDialogue"] = 51120027,
            ["SpeakNpcId"] = 701027,
            },
        [51120027] = {
            ["Content"] = "药，即可以是一方服入腹中便可见效的物品，也可以是一种生活方针，我表面是给了他们药，实际却是指导了他们要如何生活。",
            ["ContentFR"] = "Un remède peut être une potion à avaler... mais aussi une manière de vivre. En apparence, je vends des médicaments ; en réalité, j’enseigne comment vivre correctement.",
            ["DialogueId"] = 51120027,
            ["GUID"] = "7FF93F6E",
            ["NextDialogue"] = 51120028,
            ["SpeakNpcId"] = 701027,
            },
        [51120028] = {
            ["Content"] = "这样看起来，我拿这钱是否理所应当？",
            ["ContentFR"] = "À ce titre, l’argent que je reçois n’est-il pas parfaitement légitime ?",
            ["DialogueId"] = 51120028,
            ["GUID"] = "7FF93F98",
            ["NextDialogue"] = 51120029,
            ["SpeakNpcId"] = 701027,
            ["TalkActionId"] = {
                [1] = "701027:Talk02_End",
                },
            },
        [51120029] = {
            ["Content"] = "（好像很有道理……）",
            ["ContentFR"] = "<I>... Il n’a peut-être pas tort.</>",
            ["DialogueId"] = 51120029,
            ["GUID"] = "7FF93FC2",
            ["NextDialogue"] = 51120030,
            ["SpeakNpcId"] = 100001,
            },
        [51120030] = {
            ["Content"] = "所以啊，客人莫要纠结了，若是我害人自有应天尉大人来找我麻烦，如何还能让我“作恶多端”呢？",
            ["ContentFR"] = "Ainsi, ne vous tourmentez pas davantage. Si je faisais réellement du tort, le Magistrat de Yingtian serait déjà venu me chercher. Comment pourrais-je encore être ici autrement ?",
            ["DialogueId"] = 51120030,
            ["GUID"] = "7FF93FEC",
            ["NextDialogue"] = 51120031,
            ["SpeakNpcId"] = 701027,
            ["TalkActionId"] = {
                [1] = "701027:Explain01_Start",
                },
            },
        [51120031] = {
            ["Content"] = "若是客人不买药，不如往边上让让？把机会让给需要的人？",
            ["ContentFR"] = "Et si vous ne comptez rien acheter, pourriez-vous vous pousser un peu ? Laissez la place à ceux qui ont vraiment besoin de mes remèdes.",
            ["DialogueId"] = 51120031,
            ["GUID"] = "7FF94016",
            ["SpeakNpcId"] = 701027,
            ["TalkActionId"] = {
                [1] = "701027:Explain01_End",
                },
            },
        [51120032] = {
            ["Content"] = "看山看水不如看病，吃素吃肉不如吃我药师的灵丹妙药啊~",
            ["ContentFR"] = "Contempler monts et rivières vaut moins que guérir les misères ! Manger maigre ou gras n’y changera rien — venez goûter aux élixirs de votre apothicaire~",
            ["DialogueId"] = 51120032,
            ["GUID"] = "7FF94040",
            ["SpeakNpcId"] = 701027,
            },
        [51121000] = {
            ["Content"] = "不管怎样，你今日必须给我一个说法！",
            ["ContentFR"] = "Quoi qu’il arrive, aujourd’hui tu vas me donner une explication !",
            ["DialogueId"] = 51121000,
            ["GUID"] = "7FF9DF10",
            ["LookAt"] = {
                [1] = "701029:n(701030)",
                [2] = "701030:n(701029)",
                },
            ["NextDialogue"] = 51121001,
            ["SpeakNpcId"] = 701029,
            ["TalkActionId"] = {
                [1] = "701029:Talk01_Start",
                [2] = "701030:Talk02_Start",
                },
            },
        [51121001] = {
            ["Content"] = "说法，什么说法？你别太无理取闹……",
            ["ContentFR"] = "Une explication ? Pour quoi faire ? Ne sois pas ridicule...",
            ["DialogueId"] = 51121001,
            ["GUID"] = "7FF9DF3A",
            ["NextOptions"] = {
                [1] = 51121002,
                [2] = 51121003,
                [3] = 51121004,
                },
            ["SpeakNpcId"] = 701030,
            ["TalkActionId"] = {
                [1] = "701029:Talk01_End",
                [2] = "701030:Talk02_End",
                },
            },
        [51121002] = {
            ["Content"] = "看起来吵得有点凶，过去劝劝架吧。",
            ["ContentFR"] = "<I>Ils ont l’air de vraiment s’emporter... Autant essayer de calmer le jeu.</>",
            ["DialogueId"] = 51121002,
            ["GUID"] = "7FF9DF64",
            ["ImprPlusId"] = 1207,
            ["NextDialogue"] = 51121005,
            },
        [51121003] = {
            ["Content"] = "打起来！打起来！",
            ["ContentFR"] = "<I>Bagarre ! Bagarre !</>",
            ["DialogueId"] = 51121003,
            ["GUID"] = "7FF9DF8E",
            ["ImprPlusId"] = 1210,
            ["NextDialogue"] = 51121005,
            },
        [51121004] = {
            ["Content"] = "什么事吵成这样……",
            ["ContentFR"] = "<I>Qu’est-ce qui peut bien provoquer une dispute pareille... ?</>",
            ["DialogueId"] = 51121004,
            ["GUID"] = "7FF9DFB8",
            ["ImprPlusId"] = 1209,
            ["NextDialogue"] = 51121005,
            },
        [51121005] = {
            ["Content"] = "你，对，就是你这个有着满头雪发的{性别：老头|老太}，你过来，帮人家评评理！",
            ["ContentFR"] = "Hé, toi ! Oui, toi, avec ta tignasse blanche — {性别:le vieux|la vieille} ! Approche donc, et dis-nous qui a raison !",
            ["DialogueId"] = 51121005,
            ["GUID"] = "7FF9DFE2",
            ["LookAt"] = {
                [1] = "701029:n(0)",
                [2] = "701030:n(0)",
                },
            ["NextDialogue"] = 51121006,
            ["SpeakNpcId"] = 701029,
            },
        [51121006] = {
            ["Content"] = "瞧你这眼神，大好一个{性别：小伙子|小姑娘}都被你看成老人家了。与其在这里丢人现脸，你还是早点回家睡觉吧。",
            ["ContentFR"] = "Ouvre un peu les yeux. {性别:Un jeune homme|Une jeune femme} en pleine forme, et tu {性别:le prends pour un vieux|la prends pour une vieille} ? Tu te couvres de ridicule. Rentre donc chez toi dormir.",
            ["DialogueId"] = 51121006,
            ["GUID"] = "7FF9E00C",
            ["LookAt"] = {
                [1] = "701029:n(701030)",
                [2] = "701030:n(701029)",
                },
            ["NextDialogue"] = 51121007,
            ["SpeakNpcId"] = 701030,
            ["TalkActionId"] = {
                [1] = "701030:Talk01_Start",
                },
            },
        [51121007] = {
            ["Content"] = "你还说！分明就是你害的，要不是你整日昼伏夜出，扰得我日日夜夜睡不上一个好觉，我写书的创意是如何枯竭的，定是被你搅浑了！",
            ["ContentFR"] = "Tu oses encore parler ! C’est bien de ta faute ! Si tu ne passais pas tes nuits à rôder dehors pour dormir le jour, je pourrais fermer l’œil ! Mes idées s’épuisent, mon inspiration est à sec — c’est toi qui as tout brouillé !",
            ["DialogueId"] = 51121007,
            ["GUID"] = "7FF9E036",
            ["NextDialogue"] = 51121008,
            ["SpeakNpcId"] = 701029,
            ["TalkActionId"] = {
                [1] = "701030:Talk01_End",
                },
            },
        [51121008] = {
            ["Content"] = "你有完没完，不管我什么时间出门，什么时间回家，都是我的自由，我既没有在回家之时去敲你的门，也没在出门的时候摔你的门，如何惹到你了？",
            ["ContentFR"] = "Tu n’as pas encore fini ? À quelle heure je sors ou je rentre, ça me regarde. Je ne frappe pas à ta porte, je ne claque pas la mienne. En quoi est-ce que je te dérange ?",
            ["DialogueId"] = 51121008,
            ["GUID"] = "7FF9E060",
            ["NextDialogue"] = 51121009,
            ["SpeakNpcId"] = 701030,
            },
        [51121009] = {
            ["Content"] = "你那动静，与敲门摔门有何区别？你那又笨又重的靴子在家中踩来踩去，呱唧作响，每回上床之前，要将两只靴子一一甩开，发出咚咚两声。",
            ["ContentFR"] = "Le vacarme que tu fais, c’est tout comme ! Tes bottes lourdes et maladroites martèlent le sol, <I>clac clac clac,</> et chaque soir avant de dormir tu les balances par terre — <I>boum, boum !</>",
            ["DialogueId"] = 51121009,
            ["GUID"] = "7FF9E08A",
            ["NextDialogue"] = 51121010,
            ["SpeakNpcId"] = 701029,
            ["TalkActionId"] = {
                [1] = "701029:Explain01_Start",
                },
            },
        [51121010] = {
            ["Content"] = "少胡扯了，之前你来说过一次，我不是后面都尽量想起来放轻声音了吗？",
            ["ContentFR"] = "Arrête un peu. Tu t’es déjà plaint une fois, et depuis je fais attention, non ?",
            ["DialogueId"] = 51121010,
            ["GUID"] = "7FF9E0B4",
            ["NextDialogue"] = 51121011,
            ["SpeakNpcId"] = 701030,
            ["TalkActionId"] = {
                [1] = "701030:Talk02_Start",
                },
            },
        [51121011] = {
            ["Content"] = "对！你只记得放轻第二只靴子，却忘了第一只，我被你那第一只靴子吵醒，一直在等你甩第二只，你却迟迟不甩，我便干等到天亮！",
            ["ContentFR"] = "Justement ! Tu penses à poser doucement la deuxième botte... mais tu oublies la première ! Elle me réveille, et ensuite j’attends la seconde... qui ne vient jamais. Résultat : je reste éveillé jusqu’à l’aube !",
            ["DialogueId"] = 51121011,
            ["GUID"] = "7FF9E0DE",
            ["NextDialogue"] = 51121012,
            ["SpeakNpcId"] = 701029,
            ["TalkActionId"] = {
                [1] = "701029:Explain01_End",
                },
            },
        [51121012] = {
            ["Content"] = "不是……这也怪我吗？况且在那之后我不都已经格外注意了吗，如今每晚不过是在自家正常走动、洗漱，也没见其他邻居来找我。",
            ["ContentFR"] = "Mais... c’est encore ma faute, ça ? Et depuis, je fais pourtant attention ! Je marche, je me lave, rien de plus. Aucun autre voisin ne se plaint.",
            ["DialogueId"] = 51121012,
            ["GUID"] = "7FF9E108",
            ["NextDialogue"] = 51121013,
            ["SpeakNpcId"] = 701030,
            ["TalkActionId"] = {
                [1] = "701030:Talk02_End",
                },
            },
        [51121013] = {
            ["Content"] = "半点声音都听不得，莫不是你自己耳朵有问题。有病就去治，别来烦别人好吗？",
            ["ContentFR"] = "Si tu ne supportes pas le moindre bruit, c’est peut-être ton oreille le problème. Si tu es malade, va te faire soigner — mais arrête d’embêter les autres.",
            ["DialogueId"] = 51121013,
            ["GUID"] = "7FF9E132",
            ["NextDialogue"] = 51121014,
            ["SpeakNpcId"] = 701030,
            },
        [51121014] = {
            ["Content"] = "你！你欺人太甚！",
            ["ContentFR"] = "Toi... tu dépasses les bornes !",
            ["DialogueId"] = 51121014,
            ["GUID"] = "7FF9E15C",
            ["NextOptions"] = {
                [1] = 51121015,
                },
            ["RestartTag"] = 51121014,
            ["SpeakNpcId"] = 701029,
            },
        [51121015] = {
            ["Content"] = "试试劝架吧。",
            ["ContentFR"] = "<I>Tenter de calmer la dispute</>",
            ["DialogueId"] = 51121015,
            ["FailDialogue"] = 51121016,
            ["GUID"] = "7FF9E186",
            ["ImprCheckId"] = 1127,
            ["NextDialogue"] = 51121017,
            },
        [51121016] = {
            ["Content"] = "（眼前的二人怒上心头，越吵越激烈，压根听不到你微弱的劝架声……）",
            ["ContentFR"] = "<I>Ils sont bien trop en colère. Ma voix se perd complètement dans leurs cris...</>",
            ["DialogueId"] = 51121016,
            ["GUID"] = "7FF9E1B0",
            },
        [51121017] = {
            ["Content"] = "不要吵了。",
            ["ContentFR"] = "Ça suffit. Arrêtez tous les deux.",
            ["DialogueId"] = 51121017,
            ["GUID"] = "7FF9E1DA",
            ["LookAt"] = {
                [1] = "701029:n(0)",
                [2] = "701030:n(0)",
                },
            ["NextDialogue"] = 51121018,
            ["SpeakNpcId"] = 100001,
            },
        [51121018] = {
            ["Content"] = "这位好心人，你刚才也听到了，这家伙作息吊诡，搅我安眠。我本在家中创作写书，创意枯竭，本就神经衰弱，却被这动静搅得连觉也没法睡！",
            ["ContentFR"] = "Vous avez entendu ! Il vit à contretemps, m’empêche de dormir. J’écris chez moi, l’esprit épuisé, déjà au bord de la rupture — et son bruit m’empêche même de me reposer !",
            ["DialogueId"] = 51121018,
            ["GUID"] = "7FF9E204",
            ["NextDialogue"] = 51121019,
            ["SpeakNpcId"] = 701029,
            ["TalkActionId"] = {
                [1] = "701029:Talk01_Start",
                },
            },
        [51121019] = {
            ["Content"] = "我到底闹出什么天大的动静了？连在自家走动都要管，难道非得要我像个贼一样蹑手蹑脚你才能满意？",
            ["ContentFR"] = "Quel vacarme monumental, hein ? Je ne pourrais même plus marcher chez moi ? Tu veux que je me déplace comme un voleur ?",
            ["DialogueId"] = 51121019,
            ["GUID"] = "7FF9E22E",
            ["NextDialogue"] = 51121020,
            ["SpeakNpcId"] = 701030,
            ["TalkActionId"] = {
                [1] = "701029:Talk01_End",
                [2] = "701030:Talk02_Start",
                },
            },
        [51121020] = {
            ["Content"] = "好了好了……我先问问你，你为什么要昼伏夜出？",
            ["ContentFR"] = "D’accord... Commençons par toi. Pourquoi ce rythme nocturne ?",
            ["DialogueId"] = 51121020,
            ["GUID"] = "7FF9E258",
            ["NextDialogue"] = 51121021,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "701030:Talk02_End",
                },
            },
        [51121021] = {
            ["Content"] = "我吗？我没办法，码头力工本来就是老板让几点过去搬货就几点去，只是最近接到的单子便让我深夜卸货，忙完回来也就天亮了。",
            ["ContentFR"] = "Moi ? Je n’ai pas le choix. Je travaille sur les quais. Le patron fixe l’heure, je bosse. Ces temps-ci, tout se fait de nuit. Quand je rentre, le jour se lève.",
            ["DialogueId"] = 51121021,
            ["GUID"] = "7FF9E282",
            ["NextDialogue"] = 51121022,
            ["SpeakNpcId"] = 701030,
            ["TalkActionId"] = {
                [1] = "701030:Explain01_Start",
                },
            },
        [51121022] = {
            ["Content"] = "你为何要接这种阴间时辰的单子？",
            ["ContentFR"] = "Pourquoi accepter des contrats à des heures pareilles ?",
            ["DialogueId"] = 51121022,
            ["GUID"] = "7FF9E2AC",
            ["LookAt"] = {
                [1] = "701029:n(701030)",
                [2] = "701030:n(701029)",
                },
            ["NextDialogue"] = 51121023,
            ["SpeakNpcId"] = 701029,
            ["TalkActionId"] = {
                [1] = "701029:Talk02_Start",
                },
            },
        [51121023] = {
            ["Content"] = "呵……你以为大家都跟你一样在家躺着就有钱吃饭吗？我不干活哪来的钱吃饭，再说晚上的单子油水足，赚的多啊！",
            ["ContentFR"] = "Ha... Tu crois que tout le monde peut rester chez soi et manger à sa faim ? Si je ne travaille pas, je ne mange pas. Et les nuits, ça rapporte plus.",
            ["DialogueId"] = 51121023,
            ["GUID"] = "7FF9E2D6",
            ["NextDialogue"] = 51121024,
            ["SpeakNpcId"] = 701030,
            ["TalkActionId"] = {
                [1] = "701030:Explain01_End",
                },
            },
        [51121024] = {
            ["Content"] = "什么叫我在家躺着就有饭吃？我每日呕心沥血在家钻研字句用词之时，你考虑过我创意的疲乏与苦衷吗？",
            ["ContentFR"] = "« Rester chez soi » ? Tu crois qu’écrire, c’est du repos ? Je me saigne l’esprit chaque jour ! Tu crois que l’inspiration ne fatigue pas ?",
            ["DialogueId"] = 51121024,
            ["GUID"] = "7FF9E300",
            ["NextDialogue"] = 51121025,
            ["SpeakNpcId"] = 701029,
            ["TalkActionId"] = {
                [1] = "701029:Talk02_End",
                },
            },
        [51121025] = {
            ["Content"] = "听起来你们两个都很有道理。",
            ["ContentFR"] = "À vous entendre... vous avez tous les deux vos raisons.",
            ["DialogueId"] = 51121025,
            ["GUID"] = "7FF9E32A",
            ["NextDialogue"] = 51121026,
            ["SpeakNpcId"] = 100001,
            },
        [51121026] = {
            ["Content"] = "我不管，他就是吵到我睡觉，你给评评理吧！",
            ["ContentFR"] = "Je m’en moque ! Il m’empêche de dormir. Tranche donc !",
            ["DialogueId"] = 51121026,
            ["GUID"] = "7FF9E354",
            ["NextDialogue"] = 51121027,
            ["SpeakNpcId"] = 701029,
            },
        [51121027] = {
            ["Content"] = "快结束这出闹剧吧，哈欠……我还得回家睡觉，晚上上工呢。",
            ["ContentFR"] = "Dépêchons-nous... <I>haaah...</> j’ai besoin de dormir avant de repartir bosser.",
            ["DialogueId"] = 51121027,
            ["GUID"] = "7FF9E37E",
            ["NextOptions"] = {
                [1] = 51121028,
                [2] = 51121034,
                },
            ["SpeakNpcId"] = 701030,
            },
        [51121028] = {
            ["Content"] = "帮余下说话。",
            ["ContentFR"] = "<I>Soutenir Yu Xia</>",
            ["DialogueId"] = 51121028,
            ["GUID"] = "7FF9E3A8",
            ["NextDialogue"] = 51121029,
            },
        [51121029] = {
            ["Content"] = "你的作息时间毕竟和大家都不一样，打扰了他也是事实。所以还是再注意把脚步声放轻点吧。",
            ["ContentFR"] = "Ton rythme est effectivement atypique, et cela le dérange. Essaie encore de marcher plus doucement.",
            ["DialogueId"] = 51121029,
            ["GUID"] = "7FF9E3D2",
            ["LookAt"] = {
                [1] = "701029:n(0)",
                [2] = "701030:n(0)",
                },
            ["NextDialogue"] = 51121030,
            ["SpeakNpcId"] = 100001,
            },
        [51121030] = {
            ["Content"] = "你听你听，还是义士大人说话中肯！",
            ["ContentFR"] = "Tu vois ! Cette personne sait juger avec justesse !",
            ["DialogueId"] = 51121030,
            ["GUID"] = "7FF9E3FC",
            ["NextDialogue"] = 51121031,
            ["SpeakNpcId"] = 701029,
            ["TalkActionId"] = {
                [1] = "701029:Explain01_Start",
                },
            },
        [51121031] = {
            ["Content"] = "怎么你也向着他……哼！",
            ["ContentFR"] = "Même toi... <I>tss.</>",
            ["DialogueId"] = 51121031,
            ["GUID"] = "7FF9E426",
            ["NextDialogue"] = 51121032,
            ["SpeakNpcId"] = 701030,
            },
        [51121032] = {
            ["Content"] = "鄙人先行谢过，义士大人您可真是人中龙凤，气度不凡，多谢您为我伸冤！",
            ["ContentFR"] = "Merci infiniment ! Quelle droiture, quelle noblesse ! Vous m’avez rendu justice !",
            ["DialogueId"] = 51121032,
            ["GUID"] = "7FF9E450",
            ["NextDialogue"] = 51121033,
            ["SpeakNpcId"] = 701029,
            ["TalkActionId"] = {
                [1] = "701029:Explain01_End",
                },
            },
        [51121033] = {
            ["Content"] = "他吵到你也是生计所迫，并不是故意的。你们邻居一场，多体谅一些对方的难处吧。",
            ["ContentFR"] = "Il ne le fait pas par malveillance. Essayez tous deux de faire preuve de compréhension entre voisins.",
            ["DialogueId"] = 51121033,
            ["GUID"] = "7FF9E47A",
            ["NextDialogue"] = 51121040,
            ["SpeakNpcId"] = 100001,
            },
        [51121034] = {
            ["Content"] = "帮董筑说话。",
            ["ContentFR"] = "<I>Soutenir Dong Zhu</>",
            ["DialogueId"] = 51121034,
            ["GUID"] = "7FF9E4A4",
            ["NextDialogue"] = 51121035,
            },
        [51121035] = {
            ["Content"] = "如果其他邻居没有和你一样的困扰，也许是你过于敏感了。考虑用棉花把耳朵塞起来如何？",
            ["ContentFR"] = "Si les autres voisins ne sont pas dérangés, peut-être es-tu simplement trop sensible. As-tu essayé de boucher tes oreilles avec du coton ?",
            ["DialogueId"] = 51121035,
            ["GUID"] = "7FF9E4CE",
            ["LookAt"] = {
                [1] = "701029:n(0)",
                [2] = "701030:n(0)",
                },
            ["NextDialogue"] = 51121036,
            ["SpeakNpcId"] = 100001,
            },
        [51121036] = {
            ["Content"] = "听到没？路人都帮我说话，都说了你自己塞上耳朵得了，非要吵来吵去的。",
            ["ContentFR"] = "Tu entends ? Même {性别:un passant|une passante} est d’accord. Mets du coton au lieu de hurler.",
            ["DialogueId"] = 51121036,
            ["GUID"] = "7FF9E4F8",
            ["NextDialogue"] = 51121037,
            ["SpeakNpcId"] = 701030,
            ["TalkActionId"] = {
                [1] = "701030:Talk01_Start",
                },
            },
        [51121037] = {
            ["Content"] = "你！你有眼无珠！分明就是他的过错，却让我一再忍耐，你们未免太过分了！",
            ["ContentFR"] = "Toi... tu n’as donc ni yeux ni jugeote ? C’est clairement sa faute, et c’est encore moi qui devrais encaisser ? Vous dépassez les bornes !",
            ["DialogueId"] = 51121037,
            ["GUID"] = "7FF9E522",
            ["NextDialogue"] = 51121038,
            ["SpeakNpcId"] = 701029,
            },
        [51121038] = {
            ["Content"] = "若是我的书出版之后有了钱，定要去皓京买幢独栋别墅，第一时间搬出这里，再不与你这种人同为里邻！",
            ["ContentFR"] = "Quand mon livre sera publié, j’irai m’acheter une grande maison à Haojing et je quitterai ce quartier à jamais !",
            ["DialogueId"] = 51121038,
            ["GUID"] = "7FF9E54C",
            ["NextDialogue"] = 51121039,
            ["SpeakNpcId"] = 701029,
            ["TalkActionId"] = {
                [1] = "701030:Talk01_End",
                },
            },
        [51121039] = {
            ["Content"] = "狴犴没来抓我，说明我没问题，但要是你再闹下去，会不会来抓你我就不知道了。",
            ["ContentFR"] = "Si les Bi’an ne sont pas venus pour moi, c’est que je suis en règle. Mais toi... continue comme ça, et qui sait.",
            ["DialogueId"] = 51121039,
            ["GUID"] = "7FF9E576",
            ["NextDialogue"] = 51121040,
            ["SpeakNpcId"] = 701030,
            },
        [51121040] = {
            ["Content"] = "事情就到这里吧，我先走了，你们和睦相处，日后不要起争执了。",
            ["ContentFR"] = "Bon. Cela s’arrête ici. Essayez de vivre en bonne entente à l’avenir.",
            ["DialogueId"] = 51121040,
            ["GUID"] = "7FF9E5A0",
            ["NextDialogue"] = 51121041,
            ["SpeakNpcId"] = 100001,
            },
        [51121041] = {
            ["Content"] = "（余下急匆匆地离开了，董筑挠挠头，切了一声，什么也没说。）",
            ["ContentFR"] = "Yu Xia s’éloigne en trombe. Dong Zhu se gratte la tête, claque la langue et ne dit rien.",
            ["DialogueId"] = 51121041,
            ["GUID"] = "7FF9E5CA",
            ["NextDialogue"] = 51121042,
            },
        [51121042] = {
            ["Content"] = "（想必他们的关系并不会因为一次小调解就冰释前嫌，但至少暂时不会吵架了。）",
            ["ContentFR"] = "Ils ne deviendront sans doute pas amis grâce à une simple médiation... mais au moins, pour l’instant, le calme est revenu.",
            ["DialogueId"] = 51121042,
            ["GUID"] = "7FF9E5F4",
            },
        [51122000] = {
            ["Content"] = "娃娃娃娃，快过来！",
            ["ContentFR"] = "Hé, {性别:p’tit ! P’tit|p’tite ! P’tite} ! Viens par ici !",
            ["DialogueId"] = 51122000,
            ["GUID"] = "7FFA8320",
            ["LookAt"] = {
                [1] = "701031:n(0)",
                },
            ["NextDialogue"] = 51122001,
            ["SpeakNpcId"] = 701031,
            },
        [51122001] = {
            ["Content"] = "（你环顾四周，并没有发现别人的身影，于是你试探性指了指自己。）",
            ["ContentFR"] = "Vous regardez autour de vous. Personne d’autre en vue. Vous pointez prudemment votre doigt vers votre poitrine.",
            ["DialogueId"] = 51122001,
            ["GUID"] = "7FFA834A",
            ["NextDialogue"] = 51122002,
            },
        [51122002] = {
            ["Content"] = "对咯，叫你呢娃娃，快过来呀！",
            ["ContentFR"] = "Oui, toi ! C’est bien à toi que je parle, {性别:p’tit|p’tite} ! Approche donc !",
            ["DialogueId"] = 51122002,
            ["GUID"] = "7FFA8374",
            ["NextDialogue"] = 51122003,
            ["NextOptions"] = {
                [1] = 51122003,
                [2] = 51122004,
                [3] = 51122005,
                },
            ["SpeakNpcId"] = 701031,
            },
        [51122003] = {
            ["Content"] = "（老实走过去。）",
            ["ContentFR"] = "<I>S’approcher sans méfiance</>",
            ["DialogueId"] = 51122003,
            ["GUID"] = "7FFA839E",
            ["ImprPlusId"] = 1207,
            ["NextDialogue"] = 51122006,
            },
        [51122004] = {
            ["Content"] = "（难道是要给我推销？）",
            ["ContentFR"] = "<I>– Il veut sûrement me vendre quelque chose...</>",
            ["DialogueId"] = 51122004,
            ["GUID"] = "7FFA83C8",
            ["ImprPlusId"] = 1206,
            ["NextDialogue"] = 51122006,
            },
        [51122005] = {
            ["Content"] = "（装作什么也没看见走开。）",
            ["ContentFR"] = "<I>Faire comme si de rien n’était et s’éloigner</>",
            ["DialogueId"] = 51122005,
            ["GUID"] = "7FFA83F2",
            ["ImprPlusId"] = 1210,
            ["NextDialogue"] = 51122006,
            },
        [51122006] = {
            ["Content"] = "诶呀你这小娃儿，好生难叫，老夫我啊老远就注意到你了，叫你半天也不应，我就在那想啊，难道这娃娃小小年纪就失聪了？",
            ["ContentFR"] = "Ah là là... {性别:quel gamin|quelle gamine} difficile à appeler. Je t’ai repéré de loin, tu sais. J’ai beau t’appeler encore et encore, pas la moindre réaction. J’ai fini par me dire : « Ça alors, serait-il déjà dur d’oreille à cet âge-là ? »",
            ["DialogueId"] = 51122006,
            ["GUID"] = "7FFA841C",
            ["NextDialogue"] = 51122007,
            ["SpeakNpcId"] = 701031,
            ["TalkActionId"] = {
                [1] = "701031:Talk01_Start",
                },
            },
        [51122007] = {
            ["Content"] = "现在看起来，精精神神，倒是没有毛病的样子。",
            ["ContentFR"] = "Mais à te voir de près... l’œil vif, l’air alerte. Non, rien de travers, finalement.",
            ["DialogueId"] = 51122007,
            ["GUID"] = "7FFA8446",
            ["NextDialogue"] = 51122008,
            ["SpeakNpcId"] = 701031,
            ["TalkActionId"] = {
                [1] = "701031:Talk01_End",
                },
            },
        [51122008] = {
            ["Content"] = "所以你叫我是做什么？",
            ["ContentFR"] = "Alors... qu’est-ce que vous me voulez ?",
            ["DialogueId"] = 51122008,
            ["GUID"] = "7FFA8470",
            ["NextDialogue"] = 51122009,
            ["SpeakNpcId"] = 100001,
            },
        [51122009] = {
            ["Content"] = "娃娃，你别紧张，华胥可没什么坏人，只是我这有一瓶新酿好的酒，想让你品鉴一番。",
            ["ContentFR"] = "Du calme, {性别:p’tit|p’tite}. À Huaxu, y a pas vraiment de mauvaises personnes. C’est juste que j’ai brassé une nouvelle cuvée, et j’aimerais que tu m’en donnes ton avis.",
            ["DialogueId"] = 51122009,
            ["GUID"] = "7FFA849A",
            ["NextDialogue"] = 51122010,
            ["SpeakNpcId"] = 701031,
            ["TalkActionId"] = {
                [1] = "701031:Talk02_Start",
                },
            },
        [51122010] = {
            ["Content"] = "哦哦，老夫知晓你要怀疑，听我给你解释，我呢是个专门卖酒的，你可去城里打听打听我酒瓢子的名号，凡是平日爱喝上那么一口的，自然是都晓得。",
            ["ContentFR"] = "Oh, je vois bien ton regard méfiant. Écoute donc. Moi, je suis marchand d’alcool. Va te renseigner en ville : le nom de Vieux Pichet, tous les amateurs d’un bon coup le connaissent.",
            ["DialogueId"] = 51122010,
            ["GUID"] = "7FFA84C4",
            ["NextDialogue"] = 51122011,
            ["SpeakNpcId"] = 701031,
            },
        [51122011] = {
            ["Content"] = "但这最近呢，老夫却接到个织星客的订单，说是要出口一批甜酒到大陆另一头的海伯利亚去。",
            ["ContentFR"] = "Mais récemment, j’ai reçu une commande d’un Tisse-Étoiles. Il veut exporter une cargaison d’alcool doux jusqu’à l’autre bout du continent, en Hyperborea.",
            ["DialogueId"] = 51122011,
            ["GUID"] = "7FFA84EE",
            ["NextDialogue"] = 51122012,
            ["SpeakNpcId"] = 701031,
            },
        [51122012] = {
            ["Content"] = "但看了这订单我可就犯难了呀，订单特意要求了酒味要淡，甘甜可口，这这这……和咱平日酿的酒口味差了十万八千里呀，但奈何这订单出手确实阔绰……",
            ["ContentFR"] = "Et là, vois-tu, j’ai été bien embêté. Il exige un alcool léger, doux, sucré sans excès... Rien à voir avec les alcools puissants que je fais d’ordinaire. Mais la bourse, elle, est sacrément généreuse...",
            ["DialogueId"] = 51122012,
            ["GUID"] = "7FFA8518",
            ["NextDialogue"] = 51122013,
            ["SpeakNpcId"] = 701031,
            ["TalkActionId"] = {
                [1] = "701031:Talk02_End",
                },
            },
        [51122013] = {
            ["Content"] = "所以你研发新酒，想找人帮你试试口味。",
            ["ContentFR"] = "Donc vous avez créé un nouvel alcool et vous cherchez quelqu’un pour en tester le goût.",
            ["DialogueId"] = 51122013,
            ["GUID"] = "7FFA8542",
            ["NextDialogue"] = 51122014,
            ["SpeakNpcId"] = 100001,
            },
        [51122014] = {
            ["Content"] = "娃娃聪慧！所以老夫绝无别心，这瓶香料酒，是我专程收的圆糯米，蒸制时加入玉桂，带出一丝温润的甜香，再加青砖红提香增味。",
            ["ContentFR"] = "{性别:Futé, le p’tit|Futée, la p’tite} ! Voilà exactement. Aucune arrière-pensée, je te l’assure. Pour cet alcool épicé, j’ai choisi du riz gluant bien rond, ajouté de la cannelle à la cuisson pour une douceur chaleureuse, puis rehaussé l’arôme avec des feuilles de thé.",
            ["DialogueId"] = 51122014,
            ["GUID"] = "7FFA856C",
            ["NextDialogue"] = 51122015,
            ["SpeakNpcId"] = 701031,
            ["TalkActionId"] = {
                [1] = "701031:Explain01_Start",
                },
            },
        [51122015] = {
            ["Content"] = "最后，老夫特地订购了一批南山甜果，果肉碾碎成汁后混入现采山泉之水，历时整整三日，最终制成。",
            ["ContentFR"] = "Ensuite, j’ai fait venir des fruits sucrés des monts du Sud. La pulpe a été broyée, mélangée à de l’eau de source fraîchement puisée, et travaillée durant trois jours entiers.",
            ["DialogueId"] = 51122015,
            ["GUID"] = "7FFA8596",
            ["NextDialogue"] = 51122016,
            ["SpeakNpcId"] = 701031,
            },
        [51122016] = {
            ["Content"] = "那帮老头们整日喝的都是辛辣烈酒，舌头早已品不出好坏，问来问去只说过于甜腻，老夫也是求助无门，才想起来在这街上等个有缘之人。",
            ["ContentFR"] = "Les vieux bougres que je connais ne boivent que des alcools brûlants. Leur langue est émoussée. À chaque fois, ils disent juste : « Trop sucré ». Ne sachant plus vers qui me tourner, j’ai attendu ici... qu’un esprit affiné passe par là.",
            ["DialogueId"] = 51122016,
            ["GUID"] = "7FFA85C0",
            ["NextDialogue"] = 51122017,
            ["SpeakNpcId"] = 701031,
            },
        [51122017] = {
            ["Content"] = "怎么样，娃娃，你可愿意尝尝我这新酒？你放心，这酒几乎没什么度数，你若后面有其他事，一两口也不会耽误的。",
            ["ContentFR"] = "Alors ? {性别:P’tit|P’tite}, ça te dirait de goûter ? Rassure-toi, le degré est très bas. Une ou deux gorgées, et tu pourras repartir l’esprit clair.",
            ["DialogueId"] = 51122017,
            ["GUID"] = "7FFA85EA",
            ["NextDialogue"] = 51122018,
            ["SpeakNpcId"] = 701031,
            ["TalkActionId"] = {
                [1] = "701031:Explain01_End",
                },
            },
        [51122018] = {
            ["Content"] = "让我试试。",
            ["ContentFR"] = "D’accord, je goûte.",
            ["DialogueId"] = 51122018,
            ["GUID"] = "7FFA8614",
            ["NextOptions"] = {
                [1] = 51122019,
                },
            ["RestartTag"] = 51122018,
            ["SpeakNpcId"] = 100001,
            },
        [51122019] = {
            ["Content"] = "（你从他手中接过酒水，试探性抿了一口。）",
            ["ContentFR"] = "Vous prenez la coupe et en buvez une petite gorgée.",
            ["DialogueId"] = 51122019,
            ["FailDialogue"] = 51122020,
            ["GUID"] = "7FFA863E",
            ["ImprCheckId"] = 1128,
            ["NextDialogue"] = 51122021,
            },
        [51122020] = {
            ["Content"] = "（没品出来……）",
            ["ContentFR"] = "<I>Difficile à cerner...</>",
            ["DialogueId"] = 51122020,
            ["GUID"] = "7FFA8668",
            ["SpeakNpcId"] = 100001,
            },
        [51122021] = {
            ["Content"] = "入口甘甜似饮蜜，酒水从喉咙之间穿过之时，又隐约有股幽香，是瓶好酒。",
            ["ContentFR"] = "Doux à l’entrée, presque comme du miel... Et lorsqu’il glisse dans la gorge, un parfum discret se révèle. C’est un très bon breuvage.",
            ["DialogueId"] = 51122021,
            ["GUID"] = "7FFA8692",
            ["NextDialogue"] = 51122022,
            ["SpeakNpcId"] = 100001,
            },
        [51122022] = {
            ["Content"] = "酒甜不过娃娃嘴甜呀，你这一说，给老夫说的心里也甜滋滋的，不枉我这几日绞尽脑汁想着如何完成这场订单了。",
            ["ContentFR"] = "Ha ! Voilà une langue plus douce encore que mon breuvage. À t’entendre, le cœur m’en devient léger. Tous ces jours à me creuser la tête n’auront pas été vains.",
            ["DialogueId"] = 51122022,
            ["GUID"] = "7FFA86BC",
            ["NextDialogue"] = 51122023,
            ["SpeakNpcId"] = 701031,
            ["TalkActionId"] = {
                [1] = "701031:Confident_Start",
                },
            },
        [51122023] = {
            ["Content"] = "你为什么不从你现有的酒品里找一些做交易？",
            ["ContentFR"] = "Pourquoi ne pas simplement utiliser l’un de vos alcools habituels pour la vente ?",
            ["DialogueId"] = 51122023,
            ["GUID"] = "7FFA86E6",
            ["NextDialogue"] = 51122024,
            ["SpeakNpcId"] = 100001,
            },
        [51122024] = {
            ["Content"] = "你想，这海伯利亚离咱们这么远，那个远在另一头的娃娃不远万里下这个订单，定是信任老夫的酿酒技艺。",
            ["ContentFR"] = "Réfléchis. Hyperborea est si loin... Et pourtant, cette jeune étrangère a passé commande sans hésiter. C’est qu’elle a foi en mon savoir-faire.",
            ["DialogueId"] = 51122024,
            ["GUID"] = "7FFA8710",
            ["NextDialogue"] = 51122025,
            ["SpeakNpcId"] = 701031,
            },
        [51122025] = {
            ["Content"] = "若我随意交差，岂不是辜负了她的信任，砸了咱酒坊多年的好名声？",
            ["ContentFR"] = "Si je bâclais le travail, je trahirais cette confiance... et ruinerais la réputation de mon échoppe.",
            ["DialogueId"] = 51122025,
            ["GUID"] = "7FFA873A",
            ["NextDialogue"] = 51122026,
            ["SpeakNpcId"] = 701031,
            },
        [51122026] = {
            ["Content"] = "不过还好你这娃娃给了好评价，这让老夫交差的心都踏实了些，想必那个叫卡什么的外国女娃娃也会喜欢这特制甜酒吧。",
            ["ContentFR"] = "Mais grâce à ton avis, me voilà rassuré. Je suis certain que cette demoiselle étrangère — Camil, ou quelque chose comme ça — aimera cet alcool doux spécialement conçu.",
            ["DialogueId"] = 51122026,
            ["GUID"] = "7FFA8764",
            ["NextDialogue"] = 51122027,
            ["SpeakNpcId"] = 701031,
            },
        [51122027] = {
            ["Content"] = "多谢你了，小娃，若下次还想饮酒，可再来找我酒瓢子，我可专程为你酿制一瓶好酒！",
            ["ContentFR"] = "Merci, {性别:p’tit|p’tite}. Si un jour l’envie te prend de boire un bon cru, reviens me voir. Je te brasserai une bouteille rien que pour toi.",
            ["DialogueId"] = 51122027,
            ["GUID"] = "7FFA878E",
            ["SpeakNpcId"] = 701031,
            ["TalkActionId"] = {
                [1] = "701031:Confident_End",
                },
            },
        [51122028] = {
            ["Content"] = "好酒不怕巷子深！",
            ["ContentFR"] = "Un bon breuvage n’a pas besoin d’enseigne pour être trouvé.",
            ["DialogueId"] = 51122028,
            ["GUID"] = "7FFA87B8",
            ["SpeakNpcId"] = 701031,
            },
        [51123000] = {
            ["Content"] = "早起去割麦，割出万里田，整日忙不歇，归家喝小酒。",
            ["ContentFR"] = "À l’aube je coupe le blé, les champs s’étendent à perte de vue. Je m’affaire du matin au soir sans jamais souffler, puis je rentre boire un petit verre.",
            ["DialogueId"] = 51123000,
            ["GUID"] = "7FFB2730",
            ["LookAt"] = {
                [1] = "701032:n(0)",
                },
            ["NextDialogue"] = 51123001,
            ["SpeakNpcId"] = 701032,
            ["TalkActionId"] = {
                [1] = "701032:Confident_Start",
                },
            },
        [51123001] = {
            ["Content"] = "歇，酒，好像不怎么押韵啊……改成什么好呢？",
            ["ContentFR"] = "Souffler, boire... ça ne rime pas vraiment, hein... Par quoi je pourrais remplacer ça ?",
            ["DialogueId"] = 51123001,
            ["GUID"] = "7FFB275A",
            ["NextOptions"] = {
                [1] = 51123002,
                },
            ["RestartTag"] = 51123001,
            ["SpeakNpcId"] = 701032,
            ["TalkActionId"] = {
                [1] = "701032:Confident_End",
                },
            },
        [51123002] = {
            ["Content"] = "帮他想想。",
            ["ContentFR"] = "<I>Donner un coup de main</>",
            ["DialogueId"] = 51123002,
            ["FailDialogue"] = 51123003,
            ["GUID"] = "7FFB2784",
            ["ImprCheckId"] = 1129,
            ["NextDialogue"] = 51123004,
            },
        [51123003] = {
            ["Content"] = "（没想出来，再想想吧。）",
            ["ContentFR"] = "<I>Rien ne me vient... réfléchissons encore.</>",
            ["DialogueId"] = 51123003,
            ["GUID"] = "7FFB27AE",
            ["SpeakNpcId"] = 100001,
            },
        [51123004] = {
            ["Content"] = "整日忙不歇，归家端菜碟。是不是押上了？",
            ["ContentFR"] = "Je m’affaire du matin au soir sans jamais souffler, puis je rentre poser les plats sur le vaisselier. Là, ça rime, non ?",
            ["DialogueId"] = 51123004,
            ["GUID"] = "7FFB27D8",
            ["NextDialogue"] = 51123005,
            ["SpeakNpcId"] = 100001,
            },
        [51123005] = {
            ["Content"] = "歇，碟……押上了，的确押上了，只是诗句还是不怎么好听，也是我这题出的不好啊，要是那文人墨客，定是比我这老农会作诗。",
            ["ContentFR"] = "Souffler... vaisselier... oui, ça rime bien, en effet. Mais ce n’est toujours pas très joli à l’oreille. C’est sûrement moi qui ai mal posé la question. Un vrai lettré ferait bien mieux que ce vieux paysan.",
            ["DialogueId"] = 51123005,
            ["GUID"] = "7FFB2802",
            ["NextDialogue"] = 51123006,
            ["SpeakNpcId"] = 701032,
            ["TalkActionId"] = {
                [1] = "701032:Think_Start",
                },
            },
        [51123006] = {
            ["Content"] = "不过，{性别：小伙子|小姑娘}，你看起来不像是华胥人，竟也对诗句有些研究吗？",
            ["ContentFR"] = "Cela dit... {性别:jeune homme|jeune femme}, tu ne sembles pas être de Huaxu, et pourtant tu t’y connais un peu en vers ?",
            ["DialogueId"] = 51123006,
            ["GUID"] = "7FFB282C",
            ["NextDialogue"] = 51123007,
            ["SpeakNpcId"] = 701032,
            ["TalkActionId"] = {
                [1] = "701032:Think_End",
                },
            },
        [51123007] = {
            ["Content"] = "随口瞎说的，这不是也没对出好的。",
            ["ContentFR"] = "J’ai juste dit ça au hasard. Ce n’est pas fameux non plus.",
            ["DialogueId"] = 51123007,
            ["GUID"] = "7FFB2856",
            ["NextDialogue"] = 51123008,
            ["SpeakNpcId"] = 100001,
            },
        [51123008] = {
            ["Content"] = "哈哈哈哈！你倒是自谦，这不比我作的好多啦，{性别：小伙子|小姑娘}，你为何会往这田埂里跑？",
            ["ContentFR"] = "Hahahaha ! Tu es bien modeste. C’est déjà bien meilleur que ce que j’ai pondu. Dis-moi, {性别:jeune homme|jeune femme}, qu’est-ce qui t’amène à traîner par ici, sur ces talus ?",
            ["DialogueId"] = 51123008,
            ["GUID"] = "7FFB2880",
            ["NextOptions"] = {
                [1] = 51123009,
                [2] = 51123011,
                },
            ["SpeakNpcId"] = 701032,
            },
        [51123009] = {
            ["Content"] = "看你一人在这里，有些担心。",
            ["ContentFR"] = "<I>Te voir seul ici m’a un peu inquiété.</>",
            ["DialogueId"] = 51123009,
            ["GUID"] = "7FFB28AA",
            ["ImprPlusId"] = 1209,
            ["NextDialogue"] = 51123010,
            },
        [51123010] = {
            ["Content"] = "嗨！这有什么好担心的，这可是华胥，白龙神君庇佑的好地方。{性别：小伙子|小姑娘}，你这份好意老农我心领了呀。",
            ["ContentFR"] = "Bah ! Inutile de s’en faire. Nous sommes à Huaxu, sous la protection du Seigneur Dragon d’Argent. Mais ton attention me touche, {性别:jeune homme|jeune femme}.",
            ["DialogueId"] = 51123010,
            ["GUID"] = "7FFB28D4",
            ["NextDialogue"] = 51123014,
            ["SpeakNpcId"] = 701032,
            },
        [51123011] = {
            ["Content"] = "我没事，我就溜达。",
            ["ContentFR"] = "<I>Rien de spécial, je me promenais.</>",
            ["DialogueId"] = 51123011,
            ["GUID"] = "7FFB28FE",
            ["ImprPlusId"] = 1210,
            ["NextDialogue"] = 51123012,
            },
        [51123012] = {
            ["Content"] = "溜达？你不会是迷路了还嘴硬吧？记得带好香囊啊，可别碰上玄色狴犴喽。",
            ["ContentFR"] = "Te promener ? Tu ne serais pas {性别:perdu et trop fier|perdue et trop fière} pour l’admettre ? Pense à garder ton sachet sur toi... On ne sait jamais, avec les Bi’an obscurs.",
            ["DialogueId"] = 51123012,
            ["GUID"] = "7FFB2928",
            ["NextDialogue"] = 51123013,
            ["SpeakNpcId"] = 701032,
            },
        [51123013] = {
            ["Content"] = "所以，你是一位吟游诗人？",
            ["ContentFR"] = "Alors... tu serais une sorte de ménestrel itinérant ?",
            ["DialogueId"] = 51123013,
            ["GUID"] = "7FFB2952",
            ["NextDialogue"] = 51123014,
            ["SpeakNpcId"] = 100001,
            },
        [51123014] = {
            ["Content"] = "吟游诗人？这名儿倒是新鲜。不过我可不是什么诗人，我是个种地的。喏，这一大片都是我家的田地。",
            ["ContentFR"] = "Ménestrel itinérant ? Voilà un titre bien élégant. Mais non, pas du tout. Je suis cultivateur. Regarde : tous ces champs, là, ce sont les miens.",
            ["DialogueId"] = 51123014,
            ["GUID"] = "7FFB297C",
            ["NextDialogue"] = 51123015,
            ["SpeakNpcId"] = 701032,
            ["TalkActionId"] = {
                [1] = "701032:Talk01_Start",
                },
            },
        [51123015] = {
            ["Content"] = "对老农我来说啊，吟诗作对就是消遣罢了，和赏花看戏没什么区别。",
            ["ContentFR"] = "Pour un vieux fermier comme moi, rimer deux phrases n’est qu’un passe-temps. Un loisir, comme admirer les fleurs ou regarder un spectacle.",
            ["DialogueId"] = 51123015,
            ["GUID"] = "7FFB29A6",
            ["NextDialogue"] = 51123016,
            ["SpeakNpcId"] = 701032,
            },
        [51123016] = {
            ["Content"] = "不过啊，想我年轻那会倒是真用心读过几年书，想着有朝一日能入三司为神君效力，诶呀，想想就美啊。",
            ["ContentFR"] = "Cela dit... quand j’étais jeune, j’ai vraiment étudié quelques années. Je rêvais d’entrer un jour dans les Trois Bureaux pour servir le Seigneur Dragon d’Argent. Ah... quel beau rêve c’était.",
            ["DialogueId"] = 51123016,
            ["GUID"] = "7FFB29D0",
            ["NextDialogue"] = 51123017,
            ["SpeakNpcId"] = 701032,
            },
        [51123017] = {
            ["Content"] = "那怎么没去？",
            ["ContentFR"] = "Et pourquoi cela ne s’est-il pas fait ?",
            ["DialogueId"] = 51123017,
            ["GUID"] = "7FFB29FA",
            ["NextDialogue"] = 51123018,
            ["SpeakNpcId"] = 701032,
            },
        [51123018] = {
            ["Content"] = "早起去割麦，割出万里田，整日忙不歇，归家喝小酒。老农我种田一等一地好，但摊上那些乱七八糟的事就开始犯难啦。",
            ["ContentFR"] = "À l’aube je coupe le blé, les champs s’étendent à perte de vue. Je m’affaire du matin au soir sans jamais souffler, puis je rentre boire un petit verre. Cultiver la terre, je sais faire. Mais dès qu’il s’agit de paperasse et d’affaires compliquées... je sèche.",
            ["DialogueId"] = 51123018,
            ["GUID"] = "7FFB2A24",
            ["NextDialogue"] = 51123019,
            ["SpeakNpcId"] = 701032,
            },
        [51123019] = {
            ["Content"] = "天理司的辩经，天禄司的账，天梁司的机关，咱是一个都搞不明白哟。要是咱也能入仕，那明日大风九章就该改成大风乱吹啦。",
            ["ContentFR"] = "Les débats du Bureau des Rites, les comptes du Bureau de la Fortune Céleste,\
les mécanismes du Bureau des Travaux... Je n’y comprends strictement rien. Si quelqu’un comme moi entrait en fonction, les Neuf Chapitres de Dafeng deviendraient vite les Neuf Bourrasques du Désordre !",
            ["DialogueId"] = 51123019,
            ["GUID"] = "7FFB2A4E",
            ["NextDialogue"] = 51123020,
            ["SpeakNpcId"] = 701032,
            ["TalkActionId"] = {
                [1] = "701032:Talk01_End",
                },
            },
        [51123020] = {
            ["Content"] = "原来是这样。",
            ["ContentFR"] = "Je comprends mieux.",
            ["DialogueId"] = 51123020,
            ["GUID"] = "7FFB2A78",
            ["NextDialogue"] = 51123021,
            ["SpeakNpcId"] = 100001,
            },
        [51123021] = {
            ["Content"] = "不过像现在这样，没事念念打油诗，和年轻人聊聊天，晚上回去和我那好大儿就着集市上买来的卤肉，喝点小酒，也挺好的不是？",
            ["ContentFR"] = "Mais au fond, ma vie actuelle me convient bien. Quelques vers improvisés, une discussion avec les jeunes, puis le soir, un peu de viande braisée du marché, deux gorgées de breuvages avec mon grand gaillard de fils... C’est une bonne vie, non ?",
            ["DialogueId"] = 51123021,
            ["GUID"] = "7FFB2AA2",
            ["NextDialogue"] = 51123022,
            ["SpeakNpcId"] = 701032,
            ["TalkActionId"] = {
                [1] = "701032:Talk02_Start",
                },
            },
        [51123022] = {
            ["Content"] = "诶呀，今儿天不早了，{性别：小伙子|小姑娘}，咱们先不说啦！我要拾掇拾掇，回家喝上两口咯！",
            ["ContentFR"] = "Oh là là, il se fait tard ! {性别:jeune homme|jeune femme}, parlons-en une autre fois ! Je vais ranger mes outils et rentrer savourer quelques verres !",
            ["DialogueId"] = 51123022,
            ["GUID"] = "7FFB2ACC",
            ["SpeakNpcId"] = 701032,
            ["TalkActionId"] = {
                [1] = "701032:Talk02_End",
                },
            },
        [51123023] = {
            ["Content"] = "锄禾日当午，汗滴禾下土，好诗，好诗啊！",
            ["ContentFR"] = "Sarcler sous le soleil de midi, la sueur tombe sur la terre... Quelle poésie, quelle poésie !",
            ["DialogueId"] = 51123023,
            ["GUID"] = "7FFB2AF6",
            ["SpeakNpcId"] = 701032,
            },
        [51124000] = {
            ["Content"] = "呜啊！",
            ["ContentFR"] = "<I>Bouh !</>",
            ["DialogueId"] = 51124000,
            ["FacialId"] = {
                [1] = "701033:Smile01",
                },
            ["GUID"] = "7FFBCB40",
            ["LookAt"] = {
                [1] = "701033:n(0)",
                },
            ["NextDialogue"] = 51124001,
            ["SpeakNpcId"] = 701033,
            },
        [51124001] = {
            ["Content"] = "（不知道从哪里突然窜出了一只皎皎……看起来张牙舞爪的样子。）",
            ["ContentFR"] = "Sans que vous sachiez d’où elle sort, une Luno surgit soudain devant vous... l’air féroce, gesticulant de toutes ses forces.",
            ["DialogueId"] = 51124001,
            ["GUID"] = "7FFBCB6A",
            ["NextDialogue"] = 51124002,
            },
        [51124002] = {
            ["Content"] = "怎么不说话！怎么不尖叫！难道你已经被我吓傻了，额哈哈哈哈！看来本皎皎的吓人技术已经炉火纯青啦！",
            ["ContentFR"] = "Pourquoi tu ne dis rien ? Pourquoi tu ne cries pas ?! Ne me dis pas que je t’ai tellement effrayé que tu en es resté figé, ahahahaha ! On dirait bien que mes talents pour faire peur sont arrivés à maturité !",
            ["DialogueId"] = 51124002,
            ["GUID"] = "7FFBCB94",
            ["NextOptions"] = {
                [1] = 51124003,
                [2] = 51124004,
                },
            ["SpeakNpcId"] = 701033,
            ["TalkActionId"] = {
                [1] = "701033:Confident_Start",
                },
            },
        [51124003] = {
            ["Content"] = "为什么要在这里吓人？",
            ["ContentFR"] = "<I>Pourquoi faire peur aux gens ici ?</>",
            ["DialogueId"] = 51124003,
            ["GUID"] = "7FFBCBBE",
            ["ImprPlusId"] = 1209,
            ["NextDialogue"] = 51124005,
            },
        [51124004] = {
            ["Content"] = "这样好玩吗？",
            ["ContentFR"] = "<I>Tu trouves ça amusant ?</>",
            ["DialogueId"] = 51124004,
            ["GUID"] = "7FFBCBE8",
            ["ImprPlusId"] = 1207,
            ["NextDialogue"] = 51124005,
            },
        [51124005] = {
            ["Content"] = "唔？！说话了！没被吓傻呀。",
            ["ContentFR"] = "Hein ?! Tu parles ?! Alors tu n’es pas terrorisé à ce point-là !",
            ["DialogueId"] = 51124005,
            ["FacialId"] = {
                [1] = "701033:Shock01",
                },
            ["GUID"] = "7FFBCC12",
            ["NextDialogue"] = 51124006,
            ["SpeakNpcId"] = 701033,
            ["TalkActionId"] = {
                [1] = "701033:Confident_End",
                },
            },
        [51124006] = {
            ["Content"] = "本皎皎只是在钻研，钻研一种华胥的特色生物是如何进行日常活动的，并进行一些简单的模仿！",
            ["ContentFR"] = "Je suis en pleine recherche ! En train d’étudier comment une créature typique de Huaxu mène ses activités quotidiennes... et d’en reproduire quelques comportements simples !",
            ["DialogueId"] = 51124006,
            ["GUID"] = "7FFBCC3C",
            ["NextOptions"] = {
                [1] = 51124007,
                [2] = 51124009,
                },
            ["SpeakNpcId"] = 701033,
            ["TalkActionId"] = {
                [1] = "701033:Excited01_Start",
                },
            },
        [51124007] = {
            ["Content"] = "你是说无由生？",
            ["ContentFR"] = "<I>Tu parles des Wishen ?</>",
            ["DialogueId"] = 51124007,
            ["GUID"] = "7FFBCC66",
            ["NextDialogue"] = 51124008,
            },
        [51124008] = {
            ["Content"] = "嗐？！你知道？你居然知道无由生？难道……",
            ["ContentFR"] = "Quoi ?! Tu sais ce que sont les Wishen ?! Attends... ne me dis pas que—",
            ["DialogueId"] = 51124008,
            ["GUID"] = "7FFBCC90",
            ["NextDialogue"] = 51124011,
            ["SpeakNpcId"] = 701033,
            ["TalkActionId"] = {
                [1] = "701033:Excited01_End",
                },
            },
        [51124009] = {
            ["Content"] = "无由生好像不会这么行动……",
            ["ContentFR"] = "<I>Les Wishen n’agissent pas vraiment comme ça...</>",
            ["DialogueId"] = 51124009,
            ["GUID"] = "7FFBCCBA",
            ["NextDialogue"] = 51124010,
            },
        [51124010] = {
            ["Content"] = "嗐？！听你的意思，你好像亲眼看过无由生一样？！难道……",
            ["ContentFR"] = "Hein ?! À t’entendre, on dirait presque que tu en as déjà vu de tes propres yeux ! Ne me dis pas que—",
            ["DialogueId"] = 51124010,
            ["GUID"] = "7FFBCCE4",
            ["NextDialogue"] = 51124011,
            ["SpeakNpcId"] = 701033,
            },
        [51124011] = {
            ["Content"] = "难道本皎皎对于无由生的研究成果已经被泄密，现在所有华胥人都已经知道了无由生，我再也不是唯一一位研究无由生的皎皎了……",
            ["ContentFR"] = "Ne me dis pas que mes recherches sur les Wishen ont fuité... que tous les habitants de Huaxu savent déjà ce que sont les Wishen... et que je ne suis plus la seule Luno à les étudier... ?!",
            ["DialogueId"] = 51124011,
            ["GUID"] = "7FFBCD0E",
            ["NextDialogue"] = 51124012,
            ["SpeakNpcId"] = 701033,
            ["TalkActionId"] = {
                [1] = "701033:Shock03_Start",
                },
            },
        [51124012] = {
            ["Content"] = "如果我不是唯一一个研究无由生的皎皎，我将失去自己的独特之处，我就会变成和别的皎皎一样的存在了！",
            ["ContentFR"] = "Si je ne suis plus la seule à étudier les Wishen, alors je perds ce qui me rend unique ! Je deviendrai une Luno comme les autres !",
            ["DialogueId"] = 51124012,
            ["GUID"] = "7FFBCD38",
            ["NextDialogue"] = 51124013,
            ["RestartTag"] = 51124012,
            ["SpeakNpcId"] = 701033,
            ["TalkActionId"] = {
                [1] = "701033:Shock03_End",
                },
            },
        [51124013] = {
            ["Content"] = "不！我绝对不能接受！",
            ["ContentFR"] = "Non ! Je refuse absolument ça !",
            ["DialogueId"] = 51124013,
            ["GUID"] = "7FFBCD62",
            ["NextOptions"] = {
                [1] = 51124014,
                [2] = 51124016,
                },
            ["SpeakNpcId"] = 701033,
            },
        [51124014] = {
            ["Content"] = "别这么想，你是最独特的皎皎，至少在吓人这一点上……",
            ["ContentFR"] = "<I>Ne pense pas comme ça. Tu es une Luno vraiment unique — au moins quand il s’agit de faire peur...</>",
            ["DialogueId"] = 51124014,
            ["GUID"] = "7FFBCD8C",
            ["ImprPlusId"] = 1209,
            ["NextDialogue"] = 51124015,
            },
        [51124015] = {
            ["Content"] = "唔……好像是这个道理，那本皎皎今日要放弃灵异皎皎这个称号，从今日开始，我要改名为恐怖皎皎！",
            ["ContentFR"] = "Hmm... Vu comme ça, ce n’est pas faux. Très bien ! Alors à partir d’aujourd’hui, j’abandonne le nom de « Luno, la spectrale » ! Désormais, je m’appellerai... Luno, la terrifiante !",
            ["DialogueId"] = 51124015,
            ["GUID"] = "7FFBCDB6",
            ["NextOptions"] = {
                [1] = 51124018,
                },
            ["SpeakNpcId"] = 701033,
            },
        [51124016] = {
            ["Content"] = "我就是无由生。",
            ["ContentFR"] = "<I>Je suis un Wishen.</>",
            ["DialogueId"] = 51124016,
            ["GUID"] = "7FFBCDE0",
            ["ImprPlusId"] = 1210,
            ["NextDialogue"] = 51124017,
            },
        [51124017] = {
            ["Content"] = "才不是嘞，虽然本皎皎对无由生的研究已经不再是唯一，但是据我所知，无由生都是没有实体的，你看起来分明就是直挺挺地站在这里……",
            ["ContentFR"] = "N’importe quoi ! Même si mes recherches ne sont plus uniques, je sais au moins une chose : les Wishen n’ont pas de corps matériel ! Et toi, tu es bien droit là, devant moi...",
            ["DialogueId"] = 51124017,
            ["GUID"] = "7FFBCE0A",
            ["NextOptions"] = {
                [1] = 51124018,
                },
            ["SpeakNpcId"] = 701033,
            },
        [51124018] = {
            ["Content"] = "（所以这只皎皎吓人的目的是……）",
            ["ContentFR"] = "<I>Alors... si elle fait peur aux gens, c’est parce que...</>",
            ["DialogueId"] = 51124018,
            ["FailDialogue"] = 51124019,
            ["GUID"] = "7FFBCE34",
            ["ImprCheckId"] = 1130,
            ["NextDialogue"] = 51124020,
            },
        [51124019] = {
            ["Content"] = "（她为什么要在这里吓人呢？）",
            ["ContentFR"] = "<I>Pourquoi tient-elle tant à effrayer les passants, au juste... ?</>",
            ["DialogueId"] = 51124019,
            ["GUID"] = "7FFBCE5E",
            ["SpeakNpcId"] = 100001,
            },
        [51124020] = {
            ["Content"] = "所以你不在乎自己是什么皎皎，你只是想要成为独一无二的皎皎。",
            ["ContentFR"] = "Donc, au fond, peu importe ton titre... ce que tu veux vraiment, c’est être une Luno unique.",
            ["DialogueId"] = 51124020,
            ["GUID"] = "7FFBCE88",
            ["NextDialogue"] = 51124021,
            ["SpeakNpcId"] = 100001,
            },
        [51124021] = {
            ["Content"] = "噫呀呀呀！被戳穿了！被你发现了！哈哈！对，就是这样，无论如何我都是独一无二的皎皎哦！",
            ["ContentFR"] = "Eeeeh ! Démasquée ! Tu m’as percée à jour ! Ahahaha ! Exactement ! Peu importe comment on m’appelle, je suis unique, moi !",
            ["DialogueId"] = 51124021,
            ["FacialId"] = {
                [1] = "701033:Happy02",
                },
            ["GUID"] = "7FFBCEB2",
            ["NextDialogue"] = 51124022,
            ["SpeakNpcId"] = 701033,
            ["TalkActionId"] = {
                [1] = "701033:Explain01_Start",
                },
            },
        [51124022] = {
            ["Content"] = "现在在我这里，你已经是个非常独特的皎皎了。",
            ["ContentFR"] = "En tout cas, pour moi, tu es déjà une Luno très spéciale.",
            ["DialogueId"] = 51124022,
            ["GUID"] = "7FFBCEDC",
            ["NextDialogue"] = 51124023,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "701033:Explain01_End",
                },
            },
        [51124023] = {
            ["Content"] = "真的？那你不会把我和别的皎皎弄混淆吧？",
            ["ContentFR"] = "Vraiment ? Alors tu ne me confondras pas avec une autre Luno, hein ?",
            ["DialogueId"] = 51124023,
            ["GUID"] = "7FFBCF06",
            ["NextDialogue"] = 51124024,
            ["SpeakNpcId"] = 701033,
            ["TalkActionId"] = {
                [1] = "701033:Shy03_Start",
                },
            },
        [51124024] = {
            ["Content"] = "我想不会。",
            ["ContentFR"] = "Je ne pense pas.",
            ["DialogueId"] = 51124024,
            ["GUID"] = "7FFBCF30",
            ["NextDialogue"] = 51124025,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "701033:Shy03_End",
                },
            },
        [51124025] = {
            ["Content"] = "嘿嘿~这还差不多，如果下次你遇到我却把我和别的皎皎弄混，我可是会生气的。",
            ["ContentFR"] = "Héhé~ C’est mieux comme ça. Mais attention : si un jour tu me confonds avec une autre, je me fâcherai !",
            ["DialogueId"] = 51124025,
            ["FacialId"] = {
                [1] = "701033:Smile01",
                },
            ["GUID"] = "7FFBCF5A",
            ["NextDialogue"] = 51124026,
            ["SpeakNpcId"] = 701033,
            ["TalkActionId"] = {
                [1] = "701033:Explain01_Start",
                },
            },
        [51124026] = {
            ["Content"] = "今天就聊到这里吧，你是个好有龙氏，但我要去研究更多的无由生，证明我是个在无由生研究上独一无二的皎皎啦。",
            ["ContentFR"] = "Bon, on va s’arrêter là pour aujourd’hui. Tu es {性别:un très gentil Descendant draconique|une très gentille Descendante draconique}. Mais moi, je dois continuer mes recherches sur les Wishen ! Et prouver que je suis la Luno la plus unique dans ce domaine !",
            ["DialogueId"] = 51124026,
            ["GUID"] = "7FFBCF84",
            ["SpeakNpcId"] = 701033,
            ["TalkActionId"] = {
                [1] = "701033:Explain01_End",
                },
            },
        [51124027] = {
            ["Content"] = "我是最独特的皎皎，是吧？",
            ["ContentFR"] = "Je suis la plus unique des Luno... pas vrai ?",
            ["DialogueId"] = 51124027,
            ["GUID"] = "7FFBCFAE",
            ["SpeakNpcId"] = 701033,
            },
        [51125000] = {
            ["Content"] = "什么！妙趣那家伙今天也来不了！水土不服这都几天了啊！唉……那烟津渡的几场戏可怎么拍啊……",
            ["ContentFR"] = "Quoi ?! Miaoqu est encore indisponible ?! Ça fait combien de jours que ça dure, cette histoire de mauvaise acclimatation ?! Pff... mais comment voulez-vous qu’on tourne les scènes de Port-des-Brumes dans ces conditions...",
            ["DialogueId"] = 51125000,
            ["GUID"] = "7FFC6F50",
            ["NextOptions"] = {
                [1] = 51125001,
                [2] = 51125002,
                },
            ["SpeakNpcId"] = 700365,
            ["TalkActionId"] = {
                [1] = "700365:Angry01_Start",
                },
            },
        [51125001] = {
            ["Content"] = "（面前这位男子似乎有什么难处，过去看看有什么需要帮忙的地方吧。）",
            ["ContentFR"] = "<I>Cet homme semble en difficulté. Allons voir s’il a besoin d’aide.</>",
            ["DialogueId"] = 51125001,
            ["GUID"] = "7FFC6F7A",
            ["ImprPlusId"] = 1207,
            ["NextDialogue"] = 51125003,
            },
        [51125002] = {
            ["Content"] = "（你闻到了一丝麻烦事的气息，还是离远点好。）",
            ["ContentFR"] = "<I>Ça sent les ennuis. Mieux vaut rester à distance.</>",
            ["DialogueId"] = 51125002,
            ["GUID"] = "7FFC6FA4",
            ["ImprPlusId"] = 1210,
            ["NextDialogue"] = 51125003,
            },
        [51125003] = {
            ["Content"] = "诶，我看你这{性别：兄弟|姑娘}浓眉大眼的，是个演戏好苗子，有没有兴趣来我们剧组看看啊？",
            ["ContentFR"] = "Hé... toi, dis-moi, avec tes sourcils bien dessinés et ce regard assuré, tu as une vraie tête {性别:d’acteur|d’actrice}. Ça ne te dirait pas de jeter un œil à notre troupe ?",
            ["DialogueId"] = 51125003,
            ["GUID"] = "7FFC6FCE",
            ["NextDialogue"] = 51125004,
            ["SpeakNpcId"] = 700365,
            ["TalkActionId"] = {
                [1] = "700365:Angry01_End",
                },
            },
        [51125004] = {
            ["Content"] = "我们在拍戏——嗯，就是那种很新的戏，叫“照影”的。你有兴趣吗？",
            ["ContentFR"] = "On est en plein tournage — enfin, d’un genre très nouveau. Ça s’appelle le « Zhaoying ». Ça t’intéresse ?",
            ["DialogueId"] = 51125004,
            ["GUID"] = "7FFC6FF8",
            ["SpeakNpcId"] = 700365,
            },
        [51125005] = {
            ["DialogueId"] = 51125005,
            ["GUID"] = "7FFC7022",
            },
        [51125006] = {
            ["Content"] = "甚好甚好。自我介绍一下，我们正在拍摄的照影叫《应天尉大战飘零人3：最后一战》，今天就得把烟津渡的戏全部拍完。",
            ["ContentFR"] = "Parfait, parfait. Je me présente : nous tournons actuellement « <I>Le Magistrat de Yingtian contre les Vagabonds III : L’Ultime Confrontation</> ». Aujourd’hui, on doit impérativement boucler toutes les scènes de Port-des-Brumes.",
            ["DialogueId"] = 51125006,
            ["GUID"] = "7FFC704C",
            ["NextDialogue"] = 51125007,
            ["SpeakNpcId"] = 700365,
            ["TalkActionId"] = {
                [1] = "700365:Agree",
                },
            },
        [51125007] = {
            ["Content"] = "但我们的主演这几天连床都下不来，更别提拍摄了。所以你来我们这客串一下应天尉吧。这个应天尉之前也没登过场，换个新人再合适不过。",
            ["ContentFR"] = "Mais notre acteur principal est cloué au lit depuis plusieurs jours... inutile d’espérer le voir sur le plateau. Alors voilà : tu pourrais le remplacer et incarner le Magistrat de Yingtian.",
            ["DialogueId"] = 51125007,
            ["GUID"] = "7FFC7076",
            ["NextDialogue"] = 51125008,
            ["SpeakNpcId"] = 700365,
            ["TalkActionId"] = {
                [1] = "700365:Talk02_Start",
                },
            },
        [51125008] = {
            ["Content"] = "可是我不会拍戏。",
            ["ContentFR"] = "Mais... je n’ai jamais joué la comédie.",
            ["DialogueId"] = 51125008,
            ["GUID"] = "7FFC70A0",
            ["NextDialogue"] = 51125009,
            ["SpeakNpcId"] = 100001,
            },
        [51125009] = {
            ["Content"] = "没事没事，这场戏简单得很，就是咱们华胥最常见的正义应天尉打败邪恶飘零人的故事。",
            ["ContentFR"] = "Oh, ce n’est rien du tout. L’histoire est on ne peut plus classique : le juste Magistrat de Yingtian terrasse un Vagabond maléfique. À Huaxu, tout le monde connaît ce genre de récit.",
            ["DialogueId"] = 51125009,
            ["GUID"] = "7FFC70CA",
            ["NextDialogue"] = 51125010,
            ["SpeakNpcId"] = 700365,
            },
        [51125010] = {
            ["Content"] = "文戏不长，你也不用背太多台词。主要体现的是那种正派的气质，基本往那一站感觉对了，就没问题。",
            ["ContentFR"] = "Il n’y a pas beaucoup de dialogues, tu n’as rien à apprendre par cœur. L’important, c’est l’aura : tu te tiens {性别:droit|droite}, tu dégages la droiture... et ça suffit.",
            ["DialogueId"] = 51125010,
            ["GUID"] = "7FFC70F4",
            ["NextDialogue"] = 51125011,
            ["SpeakNpcId"] = 700365,
            ["TalkActionId"] = {
                [1] = "700365:Talk02_End",
                },
            },
        [51125011] = {
            ["Content"] = "横生！我们的临时主角找到了，赶紧过来对一下剧本，半个时辰以后开拍。",
            ["ContentFR"] = "Hengsheng ! Notre protagoniste temporaire est là ! Viens vite revoir le script avec {性别:lui|elle}. On tourne dans une demi-heure !",
            ["DialogueId"] = 51125011,
            ["GUID"] = "7FFC711E",
            ["SpeakNpcId"] = 700365,
            },
        [51125012] = {
            ["Content"] = "（远处一位衣着简朴的男人听罢，拿起手边厚厚的本子，嘴里一边咕哝着什么一边跑了过来。）",
            ["ContentFR"] = "Au loin, un homme vêtu simplement saisit un épais livret. Tout en marmonnant, il accourt vers vous.",
            ["DialogueId"] = 51125012,
            ["GUID"] = "7FFC7148",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 51125013,
            },
        [51125013] = {
            ["Camera"] = "325.265625,-73.105469,141.634766,0.017556,-1.600095,166.905365,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "啧，你好，我叫横生，没有妙趣，也不是无由生。给，这是你的台本。",
            ["ContentFR"] = "<I>Tch...</> salut. Moi, c’est Hengsheng. Je ne suis ni Miaoqu, ni Wishen. Tiens, voilà ton script.",
            ["DialogueId"] = 51125013,
            ["GUID"] = "7FFC7172",
            ["NextDialogue"] = 51125014,
            ["SpeakNpcId"] = 700366,
            ["TalkActionId"] = {
                [1] = "700366:Give",
                },
            },
        [51125014] = {
            ["Content"] = "（你接过横生递来的台本。乍看下来确实没什么演出难度。只要<H>不出什么意外</>的话……）",
            ["ContentFR"] = "Vous prenez le script que Hengsheng vous tend. À première vue, rien de bien compliqué à jouer... tant que <H>rien d’imprévu</> ne survient.",
            ["DialogueId"] = 51125014,
            ["GUID"] = "7FFC719C",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 51125015,
            },
        [51125015] = {
            ["Content"] = "一小时后……",
            ["ContentFR"] = "Une heure plus tard...",
            ["DialogueId"] = 51125015,
            ["GUID"] = "7FFC71C6",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 51125016,
            },
        [51125016] = {
            ["Camera"] = "-63.742188,-75.883789,146.362305,0.017534,-2.399595,19.908815,45.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我乃应天尉，上承天命，下斩邪祟。尔等飘零人，还不速速伏法！",
            ["ContentFR"] = "Je suis le Magistrat de Yingtian. Mandaté par le Ciel, je tranche le mal et châtie les impies de ce monde. Vagabonds, rendez-vous sur-le-champ !",
            ["DialogueId"] = 51125016,
            ["GUID"] = "7FFC71F0",
            ["NextDialogue"] = 51125017,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Angry01_Start",
                },
            },
        [51125017] = {
            ["Camera"] = "55.546875,-172.925781,148.643555,0.017533,-2.399322,141.50882,45.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "哈哈哈哈……应天尉大人，你英明一世，糊涂一时，连中计了都浑然不知。你可识得此物？",
            ["ContentFR"] = "Ha ha ha ha... Grand Magistrat, vous avez été sage toute votre vie... mais aujourd’hui, vous êtes tombé droit dans notre piège. Reconnaissez-vous ceci ?",
            ["DialogueId"] = 51125017,
            ["GUID"] = "7FFC721A",
            ["NextDialogue"] = 51125018,
            ["SpeakNpcId"] = 700366,
            ["TalkActionId"] = {
                [1] = "100001:Angry01_End",
                },
            },
        [51125018] = {
            ["Camera"] = "12.683594,-11.320312,144.433594,0.017532,-2.598996,1.708115,45.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "这是……缚仙索……尔等竟用此阴毒计俩！",
            ["ContentFR"] = "C’est... une Corde de Liaison Immortelle... Vous osez employer des stratagèmes aussi ignobles ?!",
            ["DialogueId"] = 51125018,
            ["FacialId"] = {
                [1] = "100001:Shock02",
                },
            ["GUID"] = "7FFC7244",
            ["NextDialogue"] = 51125019,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Shock02_Start",
                },
            },
        [51125019] = {
            ["Camera"] = "7.867188,-1148.030273,172.847656,0.017538,-3.199889,90.504539,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "哼，有了此物，管你是狴犴还是应天尉，便是那高高在上的白龙神君，我也杀给你看！",
            ["ContentFR"] = "Hmpf. Avec ça, que tu sois un Bi’an, un Magistrat... ou même le très vénéré Seigneur Dragon d’Argent, je te tuerai sans hésiter !",
            ["DialogueId"] = 51125019,
            ["GUID"] = "7FFC726E",
            ["NextDialogue"] = 51125020,
            ["SpeakNpcId"] = 700366,
            },
        [51125020] = {
            ["Content"] = "今日我即使战死在此，也不容尔等宵小对神君放肆！",
            ["ContentFR"] = "Même si je dois périr ici aujourd’hui, je ne laisserai jamais des misérables comme vous insulter le Seigneur Dragon !",
            ["DialogueId"] = 51125020,
            ["GUID"] = "7FFC7298",
            ["NextDialogue"] = 51125021,
            ["SpeakNpcId"] = 100001,
            },
        [51125021] = {
            ["Camera"] = "55.546875,-172.925781,148.643555,0.017533,-2.399322,141.50882,45.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "嘻嘻，看是你应天尉的命硬，还是我飘零人的刀子硬！弟兄们——",
            ["ContentFR"] = "Hé hé... On va voir si la vie du Magistrat est plus solide que la lame d’un Vagabond ! À moi, mes frères—",
            ["DialogueId"] = 51125021,
            ["GUID"] = "7FFC72C2",
            ["SpeakNpcId"] = 700366,
            },
        [51125022] = {
            ["Camera"] = "94.78125,-111.488281,172.178711,0.017554,-4.800099,138.306519,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "来嘞！",
            ["ContentFR"] = "À l’attaque !",
            ["DialogueId"] = 51125022,
            ["GUID"] = "7FFC72EC",
            ["NextDialogue"] = 51125023,
            ["SpeakNpcName"] = "UI_CMNpc_Name_QunYan",
            },
        [51125023] = {
            ["Camera"] = "269.707031,21.212891,176.939453,0.017553,-5.400084,157.106674,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "好，按照我们之前说的，接下来是今天的第一场打戏。三、二、一，开始——",
            ["ContentFR"] = "Parfait ! Comme prévu ! Première scène d’action de la journée. Trois... deux... un... Action !",
            ["DialogueId"] = 51125023,
            ["GUID"] = "7FFC7316",
            ["SpeakNpcId"] = 700365,
            ["TalkActionId"] = {
                [1] = "100001:Shock02_End",
                },
            },
        [51125024] = {
            ["DialogueId"] = 51125024,
            ["GUID"] = "7FFC7340",
            },
        [51125025] = {
            ["Content"] = "可恶……没有力气！",
            ["ContentFR"] = "Maudit soit... je n’ai plus de forces !",
            ["DialogueId"] = 51125025,
            ["GUID"] = "7FFC736A",
            ["NextDialogue"] = 51125026,
            ["SpeakNpcId"] = 100001,
            },
        [51125026] = {
            ["Content"] = "兄弟们，上啊！",
            ["ContentFR"] = "Tous ensemble !",
            ["DialogueId"] = 51125026,
            ["GUID"] = "7FFC7394",
            ["SpeakNpcName"] = "UI_CMNpc_Name_QunYan",
            },
        [51125027] = {
            ["DialogueId"] = 51125027,
            ["GUID"] = "7FFC73BE",
            },
        [51125028] = {
            ["Content"] = "宵小退散！",
            ["ContentFR"] = "Disparaissez, vermine !",
            ["DialogueId"] = 51125028,
            ["GUID"] = "7FFC73E8",
            ["NextDialogue"] = 51125029,
            ["SpeakNpcId"] = 100001,
            },
        [51125029] = {
            ["Content"] = "这厮好生厉害，中了缚仙索还不落下风！兄弟们快撤！",
            ["ContentFR"] = "Incroyable... même entravé par la Corde, il tient encore ! Retraite, vite !",
            ["DialogueId"] = 51125029,
            ["GUID"] = "7FFC7412",
            ["NextDialogue"] = 51125030,
            ["SpeakNpcName"] = "UI_CMNpc_Name_QunYan",
            },
        [51125030] = {
            ["Content"] = "哪里逃？！",
            ["ContentFR"] = "Vous ne fuirez pas !",
            ["DialogueId"] = 51125030,
            ["GUID"] = "7FFC743C",
            ["NextDialogue"] = 51125031,
            ["SpeakNpcId"] = 100001,
            },
        [51125031] = {
            ["Content"] = "还没结束呢……吃我正义的毒针！",
            ["ContentFR"] = "Ce n’est pas fini... Prends donc mon Aiguille Empoisonnée de la Justice !",
            ["DialogueId"] = 51125031,
            ["GUID"] = "7FFC7466",
            ["NextDialogue"] = 51125032,
            ["SpeakNpcId"] = 700366,
            },
        [51125032] = {
            ["Content"] = "（等下，台词里有“正义的毒针”吗？）",
            ["ContentFR"] = "<I>Attends... le script parlait vraiment d’une « Aiguille Empoisonnée de la Justice » ?</>",
            ["DialogueId"] = 51125032,
            ["GUID"] = "7FFC7490",
            ["SpeakNpcId"] = 100001,
            },
        [51125033] = {
            ["DialogueId"] = 51125033,
            ["GUID"] = "7FFC74BA",
            },
        [51125034] = {
            ["Camera"] = "-352.015625,-106.05957,152.610352,0.017523,-3.999574,17.508425,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "哼哼，应天尉大人，你再英明神武，也敌不过这背后的毒针吧！",
            ["ContentFR"] = "<I>Hmpf hmpf... </>Grand Magistrat, aussi héroïque soyez-vous, vous n’avez pas su voir l’aiguille dans votre dos.",
            ["DialogueId"] = 51125034,
            ["GUID"] = "7FFC74E4",
            ["NextDialogue"] = 51125035,
            ["SpeakNpcId"] = 700366,
            ["TalkActionId"] = {
                [1] = "700366:Talk03_Start",
                },
            },
        [51125035] = {
            ["Camera"] = "12.683594,-11.320312,144.433594,0.017532,-2.598996,1.708115,45.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "你……你家族世代——",
            ["ContentFR"] = "Toi... ta famille a servi, génération après génération—",
            ["DialogueId"] = 51125035,
            ["FacialId"] = {
                [1] = "100001:None",
                },
            ["GUID"] = "7FFC750E",
            ["NextDialogue"] = 51125036,
            ["SpeakNpcId"] = 100001,
            },
        [51125036] = {
            ["Camera"] = "43.136719,-3.177734,147.396484,0.017532,-2.399165,-177.490891,45.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "那又如何！",
            ["ContentFR"] = "Et alors ?!",
            ["DialogueId"] = 51125036,
            ["GUID"] = "7FFC7538",
            ["NextDialogue"] = 51125037,
            ["SpeakNpcId"] = 700366,
            },
        [51125037] = {
            ["Camera"] = "7.867188,-1148.030273,172.847656,0.017538,-3.199889,90.504539,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "等等，我台词还没说完呢……",
            ["ContentFR"] = "Attends, je n’ai pas fini ma réplique...",
            ["DialogueId"] = 51125037,
            ["GUID"] = "7FFC7562",
            ["NextDialogue"] = 51125038,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:RaiseHand_Start",
                },
            },
        [51125038] = {
            ["Content"] = "哦！嘿嘿，不好意思，不小心抢词了，重来，重来。",
            ["ContentFR"] = "Oh ! Ah ah, désolé, désolé. Je me suis laissé emporter. On recommence.",
            ["DialogueId"] = 51125038,
            ["GUID"] = "7FFC758C",
            ["NextDialogue"] = 51125039,
            ["SpeakNpcId"] = 700366,
            ["TalkActionId"] = {
                [1] = "100001:RaiseHand_End",
                },
            },
        [51125039] = {
