            ["ContentFR"] = "Ça peut vraiment fonctionner, ça... ? Enfin... qui sait, une fois lancé, il sera peut-être plus sérieux. Allez, allez, tout le monde en place ! On tourne !",
            ["DialogueId"] = 51125080,
            ["GUID"] = "7FFC7C70",
            ["SpeakNpcId"] = 700365,
            },
        [51125081] = {
            ["DialogueId"] = 51125081,
            ["GUID"] = "7FFC7C9A",
            ["IsBlack"] = 1,
            },
        [51125082] = {
            ["Content"] = "可恶……没有力气！",
            ["ContentFR"] = "Maudit soit… je n’ai plus de forces !",
            ["DialogueId"] = 51125082,
            ["GUID"] = "7FFC7CC4",
            ["NextDialogue"] = 51125083,
            ["SpeakNpcId"] = 700379,
            },
        [51125083] = {
            ["Content"] = "兄弟们，上啊！",
            ["ContentFR"] = "Tous ensemble !",
            ["DialogueId"] = 51125083,
            ["GUID"] = "7FFC7CEE",
            ["SpeakNpcName"] = "UI_CMNpc_Name_QunYan",
            },
        [51125084] = {
            ["DialogueId"] = 51125084,
            ["GUID"] = "7FFC7D18",
            ["IsBlack"] = 1,
            },
        [51125085] = {
            ["Content"] = "哼——宵小！嗬——退散！",
            ["ContentFR"] = "<I>Hmpf—</> Vermine ! Hah— Disparaissez !",
            ["DialogueId"] = 51125085,
            ["GUID"] = "7FFC7D42",
            ["NextDialogue"] = 51125086,
            ["SpeakNpcId"] = 700379,
            },
        [51125086] = {
            ["Content"] = "这厮好生厉害，中了缚仙索还不落下风！兄弟们快撤！",
            ["ContentFR"] = "Incroyable... même entravé par la Corde, il tient encore ! Retraite, vite !",
            ["DialogueId"] = 51125086,
            ["GUID"] = "7FFC7D6C",
            ["NextDialogue"] = 51125087,
            ["SpeakNpcName"] = "UI_CMNpc_Name_QunYan",
            },
        [51125087] = {
            ["Content"] = "呔！哪里逃！",
            ["ContentFR"] = "Hah ! Où croyez-vous fuir ?!",
            ["DialogueId"] = 51125087,
            ["GUID"] = "7FFC7D96",
            ["NextDialogue"] = 51125088,
            ["SpeakNpcId"] = 700379,
            },
        [51125088] = {
            ["Content"] = "看针！",
            ["ContentFR"] = "Prends ça !",
            ["DialogueId"] = 51125088,
            ["GUID"] = "7FFC7DC0",
            ["NextDialogue"] = 51125089,
            ["SpeakNpcId"] = 100001,
            },
        [51125089] = {
            ["Content"] = "哼！区区毒针，我避它锋芒！",
            ["ContentFR"] = "<I>Hmpf !</> Une simple aiguille empoisonnée ? J’en évite le tranchant sans difficulté !",
            ["DialogueId"] = 51125089,
            ["GUID"] = "7FFC7DEA",
            ["SpeakNpcId"] = 700379,
            },
        [51125090] = {
            ["DialogueId"] = 51125090,
            ["GUID"] = "7FFC7E14",
            ["IsBlack"] = 1,
            },
        [51125091] = {
            ["Content"] = "等等，这不在剧本里吧。",
            ["ContentFR"] = "Attends... Ça, ce n’était pas dans le script.",
            ["DialogueId"] = 51125091,
            ["GUID"] = "7FFC7E3E",
            ["NextDialogue"] = 51125092,
            ["SpeakNpcId"] = 100001,
            },
        [51125092] = {
            ["Content"] = "咿嘻嘻嘻嘻，你这小毒针算什么啊。我手上这把，可是沾满了剧毒的大斧哦~",
            ["ContentFR"] = "Hi hi hi hi hi... Ton petit poison, ce n’est rien du tout. Regarde plutôt cette lame que je tiens : une épée imprégnée d’un poison mortel~",
            ["DialogueId"] = 51125092,
            ["GUID"] = "7FFC7E68",
            ["NextDialogue"] = 51125093,
            ["SpeakNpcId"] = 700379,
            },
        [51125093] = {
            ["Content"] = "（怎么又在加戏！）",
            ["ContentFR"] = "<I>Il recommence à improviser...</>",
            ["DialogueId"] = 51125093,
            ["GUID"] = "7FFC7E92",
            ["SpeakNpcId"] = 100001,
            },
        [51125094] = {
            ["DialogueId"] = 51125094,
            ["GUID"] = "7FFC7EBC",
            ["IsBlack"] = 1,
            },
        [51125095] = {
            ["Camera"] = "493.785156,-135.24707,12.011719,0.017552,14.799428,162.905365,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "应天尉大人，你再英明神武，也敌不过这背后的毒针吧！",
            ["ContentFR"] = "Grand Magistrat, aussi héroïque soyez-vous, vous n’avez pas su voir l’aiguille dans votre dos.",
            ["DialogueId"] = 51125095,
            ["GUID"] = "7FFC7EE6",
            ["NextDialogue"] = 51125096,
            ["SpeakNpcId"] = 100001,
            },
        [51125096] = {
            ["Camera"] = "43.136719,-3.177734,147.396484,0.017532,-2.399165,-177.490891,45.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "……………………",
            ["ContentFR"] = "...",
            ["DialogueId"] = 51125096,
            ["GUID"] = "7FFC7F10",
            ["NextDialogue"] = 51125097,
            ["SpeakNpcId"] = 700379,
            },
        [51125097] = {
            ["Camera"] = "-63.742188,-75.883789,146.362305,0.017534,-2.399595,19.908815,45.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "说台词啊！",
            ["ContentFR"] = "Dis ta réplique !",
            ["DialogueId"] = 51125097,
            ["GUID"] = "7FFC7F3A",
            ["NextDialogue"] = 51125098,
            ["SpeakNpcId"] = 100001,
            },
        [51125098] = {
            ["Camera"] = "55.546875,-172.925781,148.643555,0.017533,-2.399322,141.50882,45.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "什么词来着？",
            ["ContentFR"] = "C’était quoi, déjà ?",
            ["DialogueId"] = 51125098,
            ["GUID"] = "7FFC7F64",
            ["NextDialogue"] = 51125099,
            ["SpeakNpcId"] = 700379,
            },
        [51125099] = {
            ["Camera"] = "-40.277344,-15.838867,165.15625,0.017561,-8.200645,2.511383,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "“你家族世代为悬衡派香官，满门忠良，怎就出了你这败类！”",
            ["ContentFR"] = "« Toi... ta famille a servi, génération après génération, comme Officiants de l’Encens de la Secte Xuanheng, fidèles et irréprochables... comment a-t-elle pu engendrer une ordure comme toi ?! »",
            ["DialogueId"] = 51125099,
            ["GUID"] = "7FFC7F8E",
            ["NextDialogue"] = 51125100,
            ["SpeakNpcId"] = 100001,
            },
        [51125100] = {
            ["Camera"] = "7.867188,-1148.030273,172.847656,0.017538,-3.199889,90.504539,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "嘿，骂谁败类呢？怎么就败类了呢？你想想，我们在悬衡派干的那都是什么活啊，报酬没给多少，一天到晚烧个破香熏得要死，假期也没几天。",
            ["ContentFR"] = "Hé, qui traites-tu d’ordure, exactement ? Pourquoi ce serait une ordure, hein ? Réfléchis un peu : tu sais ce que c’était, travailler pour la Secte Xuanheng ? Une paie misérable, de l’encens à respirer toute la journée, et presque aucun jour de repos !",
            ["DialogueId"] = 51125100,
            ["GUID"] = "7FFC7FB8",
            ["NextDialogue"] = 51125101,
            ["SpeakNpcId"] = 700379,
            },
        [51125101] = {
            ["Content"] = "还整天受大风九章的条条框框拘束，连踹条路边的狗都不行，万一一不小心踹到了主人，还得担心被当成行凶。",
            ["ContentFR"] = "Toujours enchaînés aux règles des Neuf Chapitres de Dafeng. Même donner un coup de pied à un chien dans la rue était interdit ! Et si le chien avait un maître ? On risquait d’être accusés de violence !",
            ["DialogueId"] = 51125101,
            ["GUID"] = "7FFC7FE2",
            ["NextDialogue"] = 51125102,
            ["SpeakNpcId"] = 700379,
            },
        [51125102] = {
            ["Camera"] = "-40.277344,-15.838867,165.15625,0.017561,-8.200645,2.511383,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "等一下……",
            ["ContentFR"] = "Attends une seconde...",
            ["DialogueId"] = 51125102,
            ["GUID"] = "7FFC800C",
            ["NextDialogue"] = 51125103,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:RaiseHand_Start",
                },
            },
        [51125103] = {
            ["Camera"] = "55.546875,-172.925781,148.643555,0.017533,-2.399322,141.50882,45.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "事儿办好了都是白龙神君英明神武，办砸了都是我们办事不力！还不如当个飘零人，逍遥自在！",
            ["ContentFR"] = "Quand tout allait bien, c’était « Toute gloire au Seigneur Dragon d’Argent » ! Mais dès que ça tournait mal, c’était notre faute ! Plutôt que ça, autant devenir un Vagabond, libre et sans chaînes !",
            ["DialogueId"] = 51125103,
            ["GUID"] = "7FFC8036",
            ["NextDialogue"] = 51125104,
            ["SpeakNpcId"] = 700379,
            },
        [51125104] = {
            ["Content"] = "嘻嘻，看是你应天尉的命硬，还是我飘零人的刀子硬！吃我正义的毒针！",
            ["ContentFR"] = "Hé hé... On va voir si la vie du Magistrat est plus solide que la lame d’un Vagabond ! Goûte à mon Aiguille Empoisonnée de la Justice !",
            ["DialogueId"] = 51125104,
            ["GUID"] = "7FFC8060",
            ["SpeakNpcId"] = 700379,
            },
        [51125105] = {
            ["DialogueId"] = 51125105,
            ["GUID"] = "7FFC808A",
            },
        [51125106] = {
            ["Camera"] = "2.65625,-886.189453,212.766602,0.017553,-6.600674,89.711586,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "精彩，一气呵成行云流水！果然横生你就是万里挑一的天选反派！",
            ["ContentFR"] = "Magnifique ! Fluide, percutant, sans la moindre hésitation ! Hengsheng, tu es vraiment un antagoniste né, unique en son genre !",
            ["DialogueId"] = 51125106,
            ["FacialId"] = {
                [1] = "700365:CM_Happy01",
                },
            ["GUID"] = "7FFC80B4",
            ["NextDialogue"] = 51125107,
            ["SpeakNpcId"] = 700365,
            },
        [51125107] = {
            ["Content"] = "不拍了不拍了，收工！烟津渡这几场最后就靠我的导演剪辑版来救一救吧。",
            ["ContentFR"] = "On arrête là ! C’est fini pour aujourd’hui, on plie ! Pour les scènes du Port-des-Brumes, je vais devoir compter sur mon montage de réalisateur pour sauver ce qui peut l’être...",
            ["DialogueId"] = 51125107,
            ["GUID"] = "7FFC80DE",
            ["LookAt"] = {
                [1] = "700365:n(700379)",
                },
            ["NextDialogue"] = 51125108,
            ["SpeakNpcId"] = 700365,
            },
        [51125108] = {
            ["Content"] = "{性别：兄弟|姑娘}，这是你今天拍戏的报酬，拿好了。",
            ["ContentFR"] = "{性别:Jeune homme|Jeune femme}, voilà ta rémunération pour aujourd’hui. C’est amplement mérité.",
            ["DialogueId"] = 51125108,
            ["GUID"] = "7FFC8108",
            ["LookAt"] = {
                [1] = "700365:n(100001)",
                },
            ["NextDialogue"] = 51125109,
            ["SpeakNpcId"] = 700365,
            },
        [51125109] = {
            ["Content"] = "（这一场荒唐的闹剧总算是落下了帷幕。横生如愿以偿地留下了他的高光时刻……或许。）",
            ["ContentFR"] = "Cette farce aussi absurde qu’improbable touche enfin à sa fin. Hengsheng a obtenu ce qu’il désirait tant : son moment de gloire... du moins, en apparence.",
            ["DialogueId"] = 51125109,
            ["GUID"] = "7FFC8132",
            ["IsBlack"] = 1,
            },
        [51125201] = {
            ["Content"] = "呼……可算搬完了，这下没有遗漏了吧？",
            ["ContentFR"] = "<I>Hrr...</> enfin terminé. Rien d’oublié, cette fois ?",
            ["DialogueId"] = 51125201,
            ["GUID"] = "7FFC904A",
            ["NextDialogue"] = 51125202,
            ["SpeakNpcId"] = 701034,
            },
        [51125202] = {
            ["Content"] = "还没完呢，今天阿庄哥休工，咱俩得把他那一份也搬完。",
            ["ContentFR"] = "Pas encore. Zhuang est en congé aujourd’hui, il faut aussi transporter sa part.",
            ["DialogueId"] = 51125202,
            ["GUID"] = "7FFC9074",
            ["NextDialogue"] = 51125203,
            ["SpeakNpcId"] = 701035,
            },
        [51125203] = {
            ["Content"] = "为何不让他明天自己来？",
            ["ContentFR"] = "Pourquoi ne vient-il pas demain s’en charger lui-même ?",
            ["DialogueId"] = 51125203,
            ["GUID"] = "7FFC909E",
            ["NextDialogue"] = 51125204,
            ["SpeakNpcId"] = 701034,
            },
        [51125204] = {
            ["Content"] = "阿庄哥说家里有喜事，回来请咱们吃茶呢！",
            ["ContentFR"] = "Il a une bonne nouvelle à la maison. Il a promis de nous inviter à boire le thé à son retour !",
            ["DialogueId"] = 51125204,
            ["GUID"] = "7FFC90C8",
            ["NextDialogue"] = 51125205,
            ["SpeakNpcId"] = 701035,
            },
        [51125205] = {
            ["Content"] = "嘿！有好事也不叫我们，可得敲他一壶上好的碧茅！",
            ["ContentFR"] = "Hé ! Fêter sans nous ? Il nous devra au moins une bonne théière de son meilleur Bimao !",
            ["DialogueId"] = 51125205,
            ["GUID"] = "7FFC90F2",
            ["SpeakNpcId"] = 701034,
            },
        [51125301] = {
            ["Content"] = "您别说，咱们华胥就是数一数二的安全，看到那四处巡逻的狴犴了没？但凡有奸人作恶，都会被迅速逮捕！",
            ["ContentFR"] = "Franchement, Huaxu est l’un des endroits les plus sûrs. Tu vois ces Bi’an en patrouille ? Au moindre méfait, ils interviennent aussitôt.",
            ["DialogueId"] = 51125301,
            ["GUID"] = "7FFCA0B2",
            ["NextDialogue"] = 51125302,
            ["SpeakNpcId"] = 701036,
            },
        [51125302] = {
            ["Content"] = "哼，我们海伯利亚也很安全的，知道帝国军团的威名吗？帝国的铁骑会踏破每一句反抗的声音。",
            ["ContentFR"] = "<I>Hmpf.</> Hyperborea est tout aussi sûr. Tu connais la réputation de la Légion ? La cavalerie de l’Empire écrase toute rébellion.",
            ["DialogueId"] = 51125302,
            ["GUID"] = "7FFCA0DC",
            ["NextDialogue"] = 51125303,
            ["SpeakNpcId"] = 701037,
            },
        [51125303] = {
            ["Content"] = "拉倒吧！从外头回来的织星客谁不说你们海伯利亚隔三差五就和南边打仗，这也能叫安全？",
            ["ContentFR"] = "Tu plaisantes ? Tous les Tisse-Étoiles revenus de l’étranger disent qu’Hyperborea est sans cesse en guerre au sud. C’est ça, la sécurité ?",
            ["DialogueId"] = 51125303,
            ["GUID"] = "7FFCA106",
            ["NextDialogue"] = 51125304,
            ["SpeakNpcId"] = 701036,
            },
        [51125304] = {
            ["Content"] = "打仗那是……那是帝国的本事……打仗的目的就是为了和平！",
            ["ContentFR"] = "La guerre... c’est la force de l’Empire... on combat pour la paix !",
            ["DialogueId"] = 51125304,
            ["GUID"] = "7FFCA130",
            ["NextDialogue"] = 51125305,
            ["SpeakNpcId"] = 701037,
            },
        [51125305] = {
            ["Content"] = "啧啧，那你为何苦苦要来华胥生活？姐们，来了华胥，只要你一心向善，白龙神君就会护佑你日日平安。",
            ["ContentFR"] = "Alors pourquoi vouloir vivre à Huaxu ? Ici, tant que tu agis avec droiture, le Seigneur Dragon d’Argent veille sur toi jour après jour.",
            ["DialogueId"] = 51125305,
            ["GUID"] = "7FFCA15A",
            ["SpeakNpcId"] = 701036,
            },
        [51125401] = {
            ["Content"] = "这荒塔倒是上了年头了，想来曾经也是咱们机枢派的杰作，竟任由它被风吹雨打，无人维护……",
            ["ContentFR"] = "Cette tour en ruine a de l’âge... elle devait être jadis une œuvre de la Secte Jishu. La laisser ainsi aux intempéries, sans entretien...",
            ["DialogueId"] = 51125401,
            ["GUID"] = "7FFCB11A",
            ["NextOptions"] = {
                [1] = 51125402,
                },
            ["SpeakNpcId"] = 701038,
            },
        [51125402] = {
            ["Content"] = "这是做什么用的？",
            ["ContentFR"] = "<I>À quoi servait-elle ?</>",
            ["DialogueId"] = 51125402,
            ["GUID"] = "7FFCB144",
            ["NextDialogue"] = 51125403,
            },
        [51125403] = {
            ["Content"] = "放在以前，是机枢派帮助织星客们建造的卜天楼，但要说现在……无人在意的废铜烂铁罢了。",
            ["ContentFR"] = "Autrefois, c’était une Tour de Divination, construite par notre secte pour les Tisse-Étoiles. Aujourd’hui... plus que du métal rouillé abandonné.",
            ["DialogueId"] = 51125403,
            ["GUID"] = "7FFCB16E",
            ["NextOptions"] = {
                [1] = 51125404,
                },
            ["SpeakNpcId"] = 701038,
            },
        [51125404] = {
            ["Content"] = "卜天楼是？",
            ["ContentFR"] = "<I>Tour de Divination ?</>",
            ["DialogueId"] = 51125404,
            ["GUID"] = "7FFCB198",
            ["NextDialogue"] = 51125405,
            },
        [51125405] = {
            ["Content"] = "卜算天象，测绘吉凶。说是这么说，但没这么玄乎，只是用于更好观测星空，推断后几日的天气情况的装置罢了。",
            ["ContentFR"] = "Elle servait à observer les cieux, à estimer auspices et calamités. Rien de mystique : elle permettait surtout d’étudier les étoiles et de prévoir la météo.",
            ["DialogueId"] = 51125405,
            ["GUID"] = "7FFCB1C2",
            ["NextOptions"] = {
                [1] = 51125406,
                },
            ["SpeakNpcId"] = 701038,
            },
        [51125406] = {
            ["Content"] = "那为什么荒废了？",
            ["ContentFR"] = "<I>Pourquoi a-t-elle été abandonnée ?</>",
            ["DialogueId"] = 51125406,
            ["GUID"] = "7FFCB1EC",
            ["NextDialogue"] = 51125407,
            },
        [51125407] = {
            ["Content"] = "……那可就说来话长了。最开始只是机枢派落魄，塔楼少人维护，计量结果也不怎么灵准了。",
            ["ContentFR"] = "... C’est une longue histoire. La Secte Jishu déclina, plus personne pour l’entretenir, et les mesures perdirent en précision.",
            ["DialogueId"] = 51125407,
            ["GUID"] = "7FFCB216",
            ["NextDialogue"] = 51125408,
            ["SpeakNpcId"] = 701038,
            },
        [51125408] = {
            ["Content"] = "后面织星客们改良了千星板，也能起到一定预测天气的作用，这塔便失去了作用。",
            ["ContentFR"] = "Plus tard, les Tisse-Étoiles perfectionnèrent les Panneaux aux Mille Étoiles, rendant ces tours inutiles.",
            ["DialogueId"] = 51125408,
            ["GUID"] = "7FFCB240",
            ["NextDialogue"] = 51125409,
            ["SpeakNpcId"] = 701038,
            },
        [51125409] = {
            ["Content"] = "不过要我说，若是机枢派还和百年以前一样风光，这塔应早该被后人迭新出其他作用才对。",
            ["ContentFR"] = "À mon avis, si la secte avait conservé son éclat d’il y a cent ans, cette tour aurait trouvé un nouvel usage.",
            ["DialogueId"] = 51125409,
            ["GUID"] = "7FFCB26A",
            ["NextDialogue"] = 51125410,
            ["SpeakNpcId"] = 701038,
            },
        [51125410] = {
            ["Content"] = "唉……都成过往，何必追溯。罢了，罢了……",
            ["ContentFR"] = "Hélas... tout cela appartient au passé. À quoi bon remuer la poussière...",
            ["DialogueId"] = 51125410,
            ["GUID"] = "7FFCB294",
            ["SpeakNpcId"] = 701038,
            },
        [51125501] = {
            ["Content"] = "这位远来的小友，可否靠边站站？",
            ["ContentFR"] = "{性别:Ami venu|Amie venue} de loin, pourriez-vous vous décaler un instant ?",
            ["DialogueId"] = 51125501,
            ["GUID"] = "7FFCC182",
            ["NextOptions"] = {
                [1] = 51125502,
                [2] = 51125505,
                },
            ["SpeakNpcId"] = 701039,
            },
        [51125502] = {
            ["Content"] = "不好意思。",
            ["ContentFR"] = "{性别:Désolé|Désolée}.",
            ["DialogueId"] = 51125502,
            ["GUID"] = "7FFCC1AC",
            ["ImprPlusId"] = 1207,
            ["NextDialogue"] = 51125503,
            },
        [51125503] = {
            ["Content"] = "都是小事，异国小友来咱们华胥，恐怕也是人生地不熟，若是有什么地方疑惑不解，可以随时来问我。",
            ["ContentFR"] = "Ce n’est rien. Vous venez d’arriver à Huaxu, j’imagine ? Il est normal de ne pas connaître les lieux. Si quelque chose vous intrigue, n’hésitez pas à venir me voir.",
            ["DialogueId"] = 51125503,
            ["GUID"] = "7FFCC1D6",
            ["NextDialogue"] = 51125504,
            ["SpeakNpcId"] = 701039,
            },
        [51125504] = {
            ["Content"] = "虽说我看起来平平无奇，但怎么也算是这浮星埠数一数二的点货人，上到天文地理下到民生风情，我啊，信手拈来。",
            ["ContentFR"] = "Même si j’ai l’air tout à fait ordinaire, je compte tout de même parmi les meilleurs commis au comptage du Quai-aux-Étoiles. Astronomie, géographie, coutumes locales... je pourrais vous en parler pendant des heures.",
            ["DialogueId"] = 51125504,
            ["GUID"] = "7FFCC200",
            ["SpeakNpcId"] = 701039,
            },
        [51125505] = {
            ["Content"] = "这路好像也不是你的吧？",
            ["ContentFR"] = "<I>Cette route ne vous appartient pas, si ?</>",
            ["DialogueId"] = 51125505,
            ["GUID"] = "7FFCC22A",
            ["ImprPlusId"] = 1210,
            ["NextDialogue"] = 51125506,
            },
        [51125506] = {
            ["Content"] = "诶呀这异国小友脾气就是有些大，我这是好心提醒你，这码头货工人来人往，搬运的全是重物，要是一个不小心磕碰到了你可如何是好？",
            ["ContentFR"] = "Oh là, {性别:ami venu|amie venue} de loin, inutile de vous emporter ! Je vous prévenais par gentillesse. Le port est constamment traversé par des manutentionnaires chargés de lourds fardeaux. Un faux pas, et vous pourriez vous blesser.",
            ["DialogueId"] = 51125506,
            ["GUID"] = "7FFCC254",
            ["NextDialogue"] = 51125507,
            ["SpeakNpcId"] = 701039,
            },
        [51125507] = {
            ["Content"] = "小友初来乍到，对咱们华胥不熟悉也是正常，若是有什么不解，可随时来问我，虽说我只是个点货人，但毕竟也是土生土长的华胥之民。",
            ["ContentFR"] = "Quand on arrive à Huaxu, tout cela peut sembler déroutant. Si quelque chose vous échappe, venez me demander. Je ne suis qu’un commis au comptage, certes, mais je suis né et j’ai grandi ici.",
            ["DialogueId"] = 51125507,
            ["GUID"] = "7FFCC27E",
            ["SpeakNpcId"] = 701039,
            },
        [51125508] = {
            ["Content"] = "冰台五十斤，春一品三十斤，诶诶诶，那边的，香料都是稀奇货，搬运的时候可小心点！",
            ["ContentFR"] = "Cinquante livres de Givrefeuille, trente de Printemps d’Excellence... Hé, hé, doucement par là-bas ! Les épices sont des denrées rares, manipulez-les avec soin !",
            ["DialogueId"] = 51125508,
            ["GUID"] = "7FFCC2A8",
            ["NextDialogue"] = 51125509,
            },
        [51125509] = {
            ["Content"] = "哟，你是那位刚来华胥的异国小友吧，还在浮星埠？莫非其实是来经商的小掌柜？专门来看看我这点货人的日常活计。",
            ["ContentFR"] = "Tiens donc, vous êtes encore là ? L’{性别:ami étranger|amie étrangère} fraîchement arrivé à Huaxu... Seriez-vous en réalité {性别:un petit marchand venu|une petite marchande venue} observer le quotidien d’un humble commis au comptage ?",
            ["DialogueId"] = 51125509,
            ["GUID"] = "7FFCC2D2",
            ["NextOptions"] = {
                [1] = 51125510,
                [2] = 51125527,
                },
            ["SpeakNpcId"] = 701039,
            },
        [51125510] = {
            ["Content"] = "我有事要问你。",
            ["ContentFR"] = "<I>J’ai quelque chose à vous demander.</>",
            ["DialogueId"] = 51125510,
            ["GUID"] = "7FFCC2FC",
            ["NextDialogue"] = 51125511,
            },
        [51125511] = {
            ["Content"] = "你便问吧，我知晓的，必定一一答复于你。",
            ["ContentFR"] = "Je vous écoute. Tout ce que je sais, je vous le dirai.",
            ["DialogueId"] = 51125511,
            ["GUID"] = "7FFCC326",
            ["NextOptions"] = {
                [1] = 51125512,
                [2] = 51125516,
                },
            ["SpeakNpcId"] = 701039,
            },
        [51125512] = {
            ["Content"] = "点货人是干什么的？",
            ["ContentFR"] = "<I>En quoi consiste le travail de commis au comptage ?</>",
            ["DialogueId"] = 51125512,
            ["GUID"] = "7FFCC350",
            ["NextDialogue"] = 51125513,
            },
        [51125513] = {
            ["Content"] = "点货人，字如其名，自然是帮着织星客们清点货品的人物啦。",
            ["ContentFR"] = "Commis au comptage... comme le nom l’indique, nous aidons les Tisse-Étoiles à recenser leurs marchandises.",
            ["DialogueId"] = 51125513,
            ["GUID"] = "7FFCC37A",
            ["NextDialogue"] = 51125514,
            ["SpeakNpcId"] = 701039,
            },
        [51125514] = {
            ["Content"] = "这浮星埠，每日吞吐船只容量大得很，要是只让织星客们自己清点这些货物，岂不是要忙坏他们了。",
            ["ContentFR"] = "Le Quai-aux-Étoiles voit passer un nombre incalculable de navires chaque jour. Si les Tisse-Étoiles devaient tout vérifier eux-mêmes, ils n’auraient plus une minute de répit.",
            ["DialogueId"] = 51125514,
            ["GUID"] = "7FFCC3A4",
            ["NextDialogue"] = 51125515,
            ["SpeakNpcId"] = 701039,
            },
        [51125515] = {
            ["Content"] = "所以我们点货人便应运而生，我们的主要任务就是帮着织星客们清点出入境的货物数量，防止有缺漏，届时也不好向国外的订购商们交代。",
            ["ContentFR"] = "Nous sommes donc là pour comptabiliser les cargaisons entrant et sortant du port, afin d’éviter tout manque. Sans quoi il serait difficile de rendre des comptes aux acheteurs étrangers.",
            ["DialogueId"] = 51125515,
            ["GUID"] = "7FFCC3CE",
            ["NextOptions"] = {
                [1] = 51125516,
                [2] = 51125527,
                },
            ["SpeakNpcId"] = 701039,
            },
        [51125516] = {
            ["Content"] = "华胥的织星客们进出运输货物都需要登记吗？",
            ["ContentFR"] = "<I>Les Tisse-Étoiles doivent donc tout déclarer ?</>",
            ["DialogueId"] = 51125516,
            ["GUID"] = "7FFCC3F8",
            ["NextDialogue"] = 51125517,
            },
        [51125517] = {
            ["Content"] = "那是自然，一方面华胥贸易发达，天禄司上下管理繁琐，这出去和进来的货多少是要收些税金。",
            ["ContentFR"] = "Bien entendu. Le commerce de Huaxu est florissant, et le Bureau de la Fortune Céleste applique une gestion rigoureuse. Toute marchandise importée ou exportée est soumise à taxation.",
            ["DialogueId"] = 51125517,
            ["GUID"] = "7FFCC422",
            ["NextDialogue"] = 51125518,
            ["SpeakNpcId"] = 701039,
            },
        [51125518] = {
            ["Content"] = "另一方面，华胥本身对一些重要香料配额管理便十分严苛，尤其是像吿苍这种本地人大量需求香料，若是任由织星客们贩至海外，咱们自己不够用如何是好？",
            ["ContentFR"] = "Par ailleurs, certaines épices font l’objet de quotas très stricts. Prenez le Lys céleste : la demande locale est énorme. Si les Tisse-Étoiles l’exportaient sans limite, que nous resterait-il ?",
            ["DialogueId"] = 51125518,
            ["GUID"] = "7FFCC44C",
            ["NextDialogue"] = 51125519,
            ["SpeakNpcId"] = 701039,
            },
        [51125519] = {
            ["Content"] = "这进来的东西自然更是需要登记，就说那什么海伯利亚，刀啊枪啊的，要是都进了华胥岂不是乱了套！",
            ["ContentFR"] = "Quant aux marchandises entrant à Huaxu, la vigilance est encore plus grande. D’Hyperborea arrivent parfois armes et mécanismes... laisser passer cela sans contrôle sèmerait le chaos.",
            ["DialogueId"] = 51125519,
            ["GUID"] = "7FFCC476",
            ["NextOptions"] = {
                [1] = 51125520,
                [2] = 51125524,
                [3] = 51125527,
                },
            ["SpeakNpcId"] = 701039,
            },
        [51125520] = {
            ["Content"] = "如果混进了违禁品呢？",
            ["ContentFR"] = "<I>Et si des marchandises interdites se glissaient dans les cargaisons ?</>",
            ["DialogueId"] = 51125520,
            ["GUID"] = "7FFCC4A0",
            ["NextDialogue"] = 51125521,
            },
        [51125521] = {
            ["Content"] = "小友啊小友，不是那么简单的事呀！且不说我们这样的点货人做得久了，光是看一眼货物大小，闻一闻香气，就能知道是运的何种货物。",
            ["ContentFR"] = "Ah, ce n’est pas si simple, mon {性别:ami|amie}. Les commis au comptage expérimentés reconnaissent une cargaison d’un coup d’œil... ou à son parfum.",
            ["DialogueId"] = 51125521,
            ["GUID"] = "7FFCC4CA",
            ["NextDialogue"] = 51125522,
            ["SpeakNpcId"] = 701039,
            },
        [51125522] = {
            ["Content"] = "你再看看在这码头四周游走的狴犴大人们，我们点得出来的错额他们能知晓，我们点不出来的，更是瞒不过它们。",
            ["ContentFR"] = "Et voyez ces Bi’an qui patrouillent le port. Ce que nous détectons, ils le confirment. Et ce que nous manquons... ne leur échappe jamais.",
            ["DialogueId"] = 51125522,
            ["GUID"] = "7FFCC4F4",
            ["NextDialogue"] = 51125523,
            ["SpeakNpcId"] = 701039,
            },
        [51125523] = {
            ["Content"] = "为了防止有不好的东西进入咱们华胥，狴犴大人整日都在码头游走巡逻，大人们的鼻子可灵啦，一闻便知道有谁偷偷藏了东西。",
            ["ContentFR"] = "Ils arpentent le quai jour et nuit. Leur flair est infaillible : une seule inspiration, et ils savent qui cache quoi.",
            ["DialogueId"] = 51125523,
            ["GUID"] = "7FFCC51E",
            ["SpeakNpcId"] = 701039,
            },
        [51125524] = {
            ["Content"] = "所以你不是织星客？",
            ["ContentFR"] = "<I>Vous n’êtes donc pas un Tisse-Étoiles ?</>",
            ["DialogueId"] = 51125524,
            ["GUID"] = "7FFCC548",
            ["NextDialogue"] = 51125525,
            },
        [51125525] = {
            ["Content"] = "是，也不是，在华胥想成为织星客简单，但却没有必要一定要当个织星客。",
            ["ContentFR"] = "Oui... et non. À Huaxu, devenir Tisse-Étoiles est simple, mais ce n’est pas une obligation.",
            ["DialogueId"] = 51125525,
            ["GUID"] = "7FFCC572",
            ["NextDialogue"] = 51125526,
            ["SpeakNpcId"] = 701039,
            },
        [51125526] = {
            ["Content"] = "商人做生意有赚有亏，我只想过好自己的日子，干着悠闲不忙碌的工作，拿着稳定的工资岂不美哉？何必与他们一样出海远航，家也不见得顾上。",
            ["ContentFR"] = "Le commerce a ses hauts et ses bas. Moi, je préfère une vie tranquille : un travail stable, une paie régulière. Pourquoi partir en mer pendant des mois et délaisser son foyer ?",
            ["DialogueId"] = 51125526,
            ["GUID"] = "7FFCC59C",
            ["SpeakNpcId"] = 701039,
            },
        [51125527] = {
            ["Content"] = "我先走了。",
            ["ContentFR"] = "<I>Je vais poursuivre ma route.</>",
            ["DialogueId"] = 51125527,
            ["GUID"] = "7FFCC5C6",
            ["NextDialogue"] = 51125528,
            },
        [51125528] = {
            ["Content"] = "小友慢逛~有事再来问我哈！",
            ["ContentFR"] = "Bonne promenade ! Revenez me voir si une question vous traverse l’esprit.",
            ["DialogueId"] = 51125528,
            ["GUID"] = "7FFCC5F0",
            ["SpeakNpcId"] = 701039,
            },
        [51125601] = {
            ["Content"] = "这位客人您上上眼，小店卖的啊，都是在华胥游历必不可缺的尖货，样样好！尤其是这沉月香的香囊啊，想要得到咱们华胥的白龙神君的庇佑啊，必不可缺！",
            ["ContentFR"] = "Approchez, {性别:cher client|chère cliente}. Ici, nous vendons l’indispensable du voyage à Huaxu. Et surtout ces sachets de Lune Profonde : pour recevoir la bénédiction du Dragon d’Argent, nul ne saurait s’en passer !",
            ["DialogueId"] = 51125601,
            ["GUID"] = "7FFCD1EA",
            ["NextOptions"] = {
                [1] = 51125602,
                [2] = 51125604,
                },
            ["SpeakNpcId"] = 701040,
            },
        [51125602] = {
            ["Content"] = "有人送过我了。",
            ["ContentFR"] = "<I>Quelqu’un m’en a déjà offert un.</>",
            ["DialogueId"] = 51125602,
            ["GUID"] = "7FFCD214",
            ["ImprPlusId"] = 1209,
            ["NextDialogue"] = 51125603,
            },
        [51125603] = {
            ["Content"] = "哦？客人是来华胥见朋友？难不成是哪位织星客将客人带来的？没事！除了香囊我这还有别的呢，要不您看看这把绢面的折扇？或者这柄金漆的雕花镜？",
            ["ContentFR"] = "Oh ? Vous venez rendre visite à un ami à Huaxu ? Un Tisse-Étoiles, peut-être ? Aucun souci ! J’ai bien d’autres merveilles. Que diriez-vous d’un éventail de soie ? Ou d’un miroir laqué aux motifs dorés ?",
            ["DialogueId"] = 51125603,
            ["GUID"] = "7FFCD23E",
            ["SpeakNpcId"] = 701040,
            },
        [51125604] = {
            ["Content"] = "我没钱，你可以送我吗？",
            ["ContentFR"] = "<I>Je n’ai pas d’argent. Vous pourriez m’en offrir un ?</>",
            ["DialogueId"] = 51125604,
            ["GUID"] = "7FFCD268",
            ["ImprPlusId"] = 1210,
            ["NextDialogue"] = 51125605,
            },
        [51125605] = {
            ["Content"] = "哈哈哈，客人真会说笑，但其实并无不可，沉月香香囊在咱们华胥本就不是什么稀奇之物，客人不嫌弃的话，便从我这随便挑一个拿走吧！",
            ["ContentFR"] = "Ha ha ! Vous avez le sens de l’humour. Mais après tout... pourquoi pas ? Les sachets de Lune Profonde sont courants ici. Choisissez-en un, je vous l’offre.",
            ["DialogueId"] = 51125605,
            ["GUID"] = "7FFCD292",
            ["NextDialogue"] = 51125606,
            ["SpeakNpcId"] = 701040,
            },
        [51125606] = {
            ["Content"] = "等客人在华胥发了财，可别忘了来我这再挑挑，选些纪念品带给亲朋好友啊！",
            ["ContentFR"] = "Et quand la fortune vous sourira à Huaxu, revenez donc m’acheter quelques souvenirs pour vos proches.",
            ["DialogueId"] = 51125606,
            ["GUID"] = "7FFCD2BC",
            ["SpeakNpcId"] = 701040,
            },
        [51125607] = {
            ["Content"] = "专供异国友人的纪念品摊铺，来华胥之游人必不可错过！香囊折扇古玩珍宝，您想要的，应有尽有！",
            ["ContentFR"] = "Souvenirs pour voyageurs étrangers ! À Huaxu, nul visiteur ne devrait passer à côté ! Sachets parfumés, éventails de soie, antiquités, trésors rares... tout ce que vous désirez !",
            ["DialogueId"] = 51125607,
            ["GUID"] = "7FFCD2E6",
            ["NextDialogue"] = 51125608,
            ["SpeakNpcId"] = 701040,
            },
        [51125608] = {
            ["Content"] = "客人来啦，随便瞧随便看，有什么喜欢的您尽管说，价格好商量。",
            ["ContentFR"] = "Bienvenue ! Regardez à votre guise. Si quelque chose vous plaît, parlons-en : les prix se négocient.",
            ["DialogueId"] = 51125608,
            ["GUID"] = "7FFCD310",
            ["NextOptions"] = {
                [1] = 51125609,
                [2] = 51125620,
                [3] = 51125622,
                },
            ["SpeakNpcId"] = 701040,
            },
        [51125609] = {
            ["Content"] = "有什么推荐的必备物品吗？除了香囊。",
            ["ContentFR"] = "<I>Avez-vous des objets vraiment indispensables ? En dehors des sachets.</>",
            ["DialogueId"] = 51125609,
            ["GUID"] = "7FFCD33A",
            ["NextDialogue"] = 51125610,
            },
        [51125610] = {
            ["Content"] = "有，自然是有的！首先便是这大风九章挂轴，上面把条目写得一清二楚。这样啊，您离开华胥回到故国，和朋友们讲起大风九章，就能有实物说明啦，不至于用手比划！",
            ["ContentFR"] = "Bien sûr ! Voyez ce rouleau des Neuf Chapitres de Dafeng. Tout y est consigné avec clarté. Ainsi, de retour dans votre patrie, vous pourrez en parler preuves à l’appui.",
            ["DialogueId"] = 51125610,
            ["GUID"] = "7FFCD364",
            ["NextDialogue"] = 51125611,
            ["SpeakNpcId"] = 701040,
            },
        [51125611] = {
            ["Content"] = "客人再看看这华胥特有的首饰，咱们华胥上至老人下至小孩，都喜欢这种古色古香的款式，经典！",
            ["ContentFR"] = "Et ces bijoux typiques de Huaxu : des modèles appréciés aussi bien des anciens que des enfants. Des classiques intemporels.",
            ["DialogueId"] = 51125611,
            ["GUID"] = "7FFCD38E",
            ["NextDialogue"] = 51125612,
            ["SpeakNpcId"] = 701040,
            },
        [51125612] = {
            ["Content"] = "您要是喜欢与众不同呢，也有这种以昆虫为主题的，更能凸显客人气质独特，品位不凡。",
            ["ContentFR"] = "Pour quelque chose de plus singulier, nous avons aussi des pièces inspirées des insectes, idéales pour affirmer un goût hors du commun.",
            ["DialogueId"] = 51125612,
            ["GUID"] = "7FFCD3B8",
            ["NextDialogue"] = 51125613,
            ["SpeakNpcId"] = 701040,
            },
        [51125613] = {
            ["Content"] = "对了对了，客人一定不能错过我们店里新到的香薰蜡烛，比普通蜡烛多了一份来自华胥的芳香，许多异国客人买过之后还想要呢！",
            ["ContentFR"] = "Ah ! Et ne manquez pas nos nouvelles bougies parfumées. Une senteur propre à Huaxu — les voyageurs en redemandent toujours.",
            ["DialogueId"] = 51125613,
            ["GUID"] = "7FFCD3E2",
            ["NextOptions"] = {
                [1] = 51125614,
                [2] = 51125618,
                },
            ["SpeakNpcId"] = 701040,
            },
        [51125614] = {
            ["Content"] = "这些我都不喜欢，有没有更实用的东西？",
            ["ContentFR"] = "<I>Ce n’est pas mon style. Auriez-vous quelque chose de plus pratique ?</>",
            ["DialogueId"] = 51125614,
            ["GUID"] = "7FFCD40C",
            ["NextDialogue"] = 51125615,
            },
        [51125615] = {
            ["Content"] = "客人呀~我就是个卖纪念品的小贩，纪念品这种东西，主打的就是一个没什么实际意义，买着好玩的存在呀。",
            ["ContentFR"] = "Ah, {性别:cher client|chère cliente}... je ne vends que des souvenirs. Leur vocation n’est pas l’utilité, mais le plaisir et la mémoire.",
            ["DialogueId"] = 51125615,
            ["GUID"] = "7FFCD436",
            ["NextDialogue"] = 51125616,
            ["SpeakNpcId"] = 701040,
            },
        [51125616] = {
            ["Content"] = "来咱们华胥的外国客人，要么是旅游要么是做生意，多少都想带点东西给家乡里没法亲自过来的人作为纪念，要是有用的华胥之物，他们也用不惯的。",
            ["ContentFR"] = "Les étrangers viennent ici pour voyager ou commercer, et souhaitent emporter un souvenir pour ceux restés au pays. Les objets réellement utiles... ils auraient du mal à s’y habituer.",
            ["DialogueId"] = 51125616,
            ["GUID"] = "7FFCD460",
            ["NextDialogue"] = 51125617,
            ["SpeakNpcId"] = 701040,
            },
        [51125617] = {
            ["Content"] = "再说了，要是真有大用的货物，早就会有商人把它当做紧俏货，卖得各国都是啦，又怎么会只有华胥才能买到呢。",
            ["ContentFR"] = "Et puis, si un bien était véritablement indispensable, les Tisse-Étoiles l’auraient déjà diffusé dans tous les royaumes. Il ne serait pas exclusif à Huaxu.",
            ["DialogueId"] = 51125617,
            ["GUID"] = "7FFCD48A",
            ["NextOptions"] = {
                [1] = 51125622,
                },
            ["SpeakNpcId"] = 701040,
            },
        [51125618] = {
            ["Content"] = "都想要，但我没钱，能不能赊账。",
            ["ContentFR"] = "<I>Je voudrais tout, mais je n’ai pas d’argent. Puis-je acheter à crédit ?</>",
            ["DialogueId"] = 51125618,
            ["GUID"] = "7FFCD4B4",
            ["NextDialogue"] = 51125619,
            },
        [51125619] = {
            ["Content"] = "客人这……我这是小本生意，客人别难为我啦，要是客人想找点活，我可以帮您引荐引荐，织星客们经常在码头招募搬货的工人，客人要不去问问？",
            ["ContentFR"] = "Ah... pardonnez-moi. Mon échoppe est modeste, je ne peux me le permettre. Mais si vous cherchez du travail, je peux vous orienter : les Tisse-Étoiles recrutent souvent des manutentionnaires au port.",
            ["DialogueId"] = 51125619,
            ["GUID"] = "7FFCD4DE",
            ["NextOptions"] = {
                [1] = 51125622,
                },
            ["SpeakNpcId"] = 701040,
            },
        [51125620] = {
            ["Content"] = "卖给外国人的货，不会在价格上坑我吧？",
            ["ContentFR"] = "<I>Vous n’arnaquez pas les étrangers sur les prix, au moins ?</>",
            ["DialogueId"] = 51125620,
            ["GUID"] = "7FFCD508",
            ["NextDialogue"] = 51125621,
            },
        [51125621] = {
            ["Content"] = "客人这话说的！我在这档口待了快有十年，远近闻名的好信用，货品都是尽量给客人最大的优惠。",
            ["ContentFR"] = "Quelle idée ! Cela fait presque dix ans que je tiens ce stand. Ma réputation est irréprochable, et je fais toujours de mon mieux pour offrir les meilleurs prix.",
            ["DialogueId"] = 51125621,
            ["GUID"] = "7FFCD532",
            ["NextOptions"] = {
                [1] = 51125609,
                [2] = 51125622,
                },
            ["SpeakNpcId"] = 701040,
            },
        [51125622] = {
            ["Content"] = "没什么要说的，走了。",
            ["ContentFR"] = "<I>Je n’ai plus de questions. Je m’en vais.</>",
            ["DialogueId"] = 51125622,
            ["GUID"] = "7FFCD55C",
            ["NextDialogue"] = 51125623,
            },
        [51125623] = {
            ["Content"] = "客人慢走，以后有空再来看看，定能找到您喜欢的东西！",
            ["ContentFR"] = "Bonne route ! Revenez quand vous voulez — vous trouverez forcément quelque chose à votre goût.",
            ["DialogueId"] = 51125623,
            ["GUID"] = "7FFCD586",
            ["SpeakNpcId"] = 701040,
            },
        [51125701] = {
            ["Content"] = "诸位有所不知啊，咱们浮星埠现在呢，只是织星客们货物往来的小小码头，平平无奇，但是在千年之前呢，这里可出过一位大人物。",
            ["ContentFR"] = "Vous l’ignorez peut-être, mais aujourd’hui, le Quai-aux-Étoiles n’est plus qu’un modeste port où transitent les marchandises des Tisse-Étoiles. Rien d’extraordinaire en apparence. Pourtant, il y a mille ans, un personnage illustre est parti d’ici.",
            ["DialogueId"] = 51125701,
            ["GUID"] = "7FFCE252",
            ["NextDialogue"] = 51125702,
            ["SpeakNpcId"] = 701041,
            },
        [51125702] = {
            ["Content"] = "哪位呢？说来大家也都听过名字，就是那大风九章的创立者之一，也是匠矩派的老祖宗——矩！",
            ["ContentFR"] = "Qui donc ? Vous avez tous déjà entendu son nom : l’un des fondateurs des Neuf Chapitres de Dafeng, l’ancêtre de la Secte Jishu... Ju !",
            ["DialogueId"] = 51125702,
            ["GUID"] = "7FFCE27C",
            ["NextOptions"] = {
                [1] = 51125703,
                [2] = 51125720,
                },
            ["SpeakNpcId"] = 701041,
            },
        [51125703] = {
            ["Content"] = "继续听下去。",
            ["ContentFR"] = "<I>Continuer à écouter</>",
            ["DialogueId"] = 51125703,
            ["GUID"] = "7FFCE2A6",
            ["NextDialogue"] = 51125704,
            },
        [51125704] = {
            ["Content"] = "南来北往的慢走一步，且听我说道说道咱们这浮星埠的千年历史——做生意讲究明明白白，对自己的过去啊，也得清清楚楚才好。",
            ["ContentFR"] = "Voyageurs venus du sud comme du nord, accordez-moi un instant. Laissez-moi vous conter les mille ans d’histoire de notre Quai-aux-Étoiles. En affaires, on aime que tout soit clair et net... eh bien, il en va de même pour notre passé.",
            ["DialogueId"] = 51125704,
            ["GUID"] = "7FFCE2D0",
            ["NextDialogue"] = 51125705,
            ["SpeakNpcId"] = 701041,
            },
        [51125705] = {
            ["Content"] = "当年的华胥，没有大风九章的庇佑，秽兽四起，袭击无辜之人，为了活命，是不分老幼，都得想着法和那些凶恶的野兽去斗来斗去。",
            ["ContentFR"] = "À cette époque, Huaxu ne bénéficiait pas encore de la protection des Neuf Chapitres de Dafeng. Les Souillés erraient partout, attaquant les innocents. Pour survivre, qu’on soit vieux ou enfant, il fallait lutter sans cesse contre ces bêtes féroces.",
            ["DialogueId"] = 51125705,
            ["GUID"] = "7FFCE2FA",
            ["NextDialogue"] = 51125706,
            ["SpeakNpcId"] = 701041,
            },
        [51125706] = {
            ["Content"] = "有争斗就会有伤亡，那时，华胥人口数量极少，因为大多数出生的孩子都难在这乱世之中活下来，为了寻找到让华胥境内安宁的办法，有龙一族上下求索。",
            ["ContentFR"] = "Là où il y a lutte, il y a morts. La population de Huaxu était alors extrêmement réduite : bien peu d’enfants parvenaient à survivre dans ce chaos. Afin de trouver un moyen d’apporter la paix au territoire, les Descendants draconiques cherchèrent sans relâche une solution.",
            ["DialogueId"] = 51125706,
            ["GUID"] = "7FFCE324",
            ["NextDialogue"] = 51125707,
            ["SpeakNpcId"] = 701041,
            },
        [51125707] = {
            ["Content"] = "而我们的前辈矩呢，走遍了华胥，发现哪儿都是不得安生，于是他想着，不如出去看看，去看看人家是怎么做的，取其长处再充盈自身。",
            ["ContentFR"] = "Ju, lui, parcourut toute Huaxu... sans jamais trouver de lieu véritablement paisible. Alors il se dit : puisque la paix n’est nulle part ici, pourquoi ne pas aller voir ailleurs ? Observer comment font les autres, apprendre de leurs forces, et revenir enrichi de ce savoir.",
            ["DialogueId"] = 51125707,
            ["GUID"] = "7FFCE34E",
            ["NextOptions"] = {
                [1] = 51125708,
                },
            ["SpeakNpcId"] = 701041,
            },
        [51125708] = {
            ["Content"] = "继续听下去。",
            ["ContentFR"] = "<I>Continuer à écouter</>",
            ["DialogueId"] = 51125708,
            ["GUID"] = "7FFCE378",
            ["NextDialogue"] = 51125709,
            },
        [51125709] = {
            ["Content"] = "当年啊，还没现在这么厉害的船，也没有织星客的存在，想要出海，全凭运气，运气好便漂流到荒岛看鸟，运气不好，就只能葬身海底喂鱼喽。",
            ["ContentFR"] = "À l’époque, il n’existait ni navires aussi robustes qu’aujourd’hui, ni Tisse-Étoiles pour guider les traversées. Prendre la mer relevait du pur hasard. Avec de la chance, on échouait sur une île déserte à observer les oiseaux. Sans elle... on finissait au fond de l’océan, nourriture pour les poissons.",
            ["DialogueId"] = 51125709,
            ["GUID"] = "7FFCE3A2",
            ["NextDialogue"] = 51125710,
            ["SpeakNpcId"] = 701041,
            },
        [51125710] = {
            ["Content"] = "但矩呢，抱定要为万民谋安宁的一颗赤心，自制了艘船，说是不连累别人，愣是一个人就从咱们这浮星埠下了海！",
            ["ContentFR"] = "Mais Ju, animé d’un ardent désir d’apporter la paix à tous, construisit lui-même un bateau. Refusant d’impliquer qui que ce soit, il prit la mer seul... depuis ce même Quai-aux-Étoiles.",
            ["DialogueId"] = 51125710,
            ["GUID"] = "7FFCE3CC",
            ["NextDialogue"] = 51125711,
            ["SpeakNpcId"] = 701041,
            },
        [51125711] = {
            ["Content"] = "好在，白龙神君眷顾，矩在风浪里去了那神秘的塔之国，但可惜的是，那边也不得安生，矩认为外民也无法给华胥带来希望，于是便带着同样想要安定的人回来了。",
            ["ContentFR"] = "Par la grâce du Seigneur Dragon d’Argent, Ju survécut aux tempêtes et atteignit le mystérieux pays de la Tour. Hélas, là-bas non plus, la paix n’existait pas. Convaincu que les peuples étrangers ne pouvaient offrir l’espoir à Huaxu, Ju reprit la route du retour... accompagné d’autres âmes en quête de stabilité.",
            ["DialogueId"] = 51125711,
            ["GUID"] = "7FFCE3F6",
            ["NextDialogue"] = 51125712,
            ["SpeakNpcId"] = 701041,
            },
        [51125712] = {
            ["Content"] = "这都多少年过去了，大家都以为矩早就是个死人，结果啊非但没死，还又带了许许多多的活人回来了浮星埠。",
            ["ContentFR"] = "Les années passèrent. Tous pensaient Ju mort depuis longtemps. Et pourtant... il revint, bien vivant, ramenant avec lui de nombreux survivants jusqu’au Quai-aux-Étoiles.",
            ["DialogueId"] = 51125712,
            ["GUID"] = "7FFCE420",
            ["NextOptions"] = {
                [1] = 51125713,
                },
            ["SpeakNpcId"] = 701041,
            },
        [51125713] = {
            ["Content"] = "继续听下去。",
            ["ContentFR"] = "<I>Continuer à écouter</>",
            ["DialogueId"] = 51125713,
            ["GUID"] = "7FFCE44A",
            ["NextDialogue"] = 51125714,
            },
        [51125714] = {
            ["Content"] = "你们可能好奇，矩是如何做到如此准确的寻路，是有神灵庇佑还是靠的信念和直觉？",
            ["ContentFR"] = "Vous vous demandez sans doute comment Ju parvint à naviguer avec une telle précision. Était-ce la bénédiction des dieux ? Ou bien la foi et l’instinct ?",
            ["DialogueId"] = 51125714,
            ["GUID"] = "7FFCE474",
            ["NextDialogue"] = 51125715,
            ["SpeakNpcId"] = 701041,
            },
        [51125715] = {
            ["Content"] = "都不是，老柳头啊也不卖关子了，现在织星者们出海时用的引路的工具不是叫千星板吗？矩也是一样，只是啊，他手里用的那个，就是第一个。",
            ["ContentFR"] = "Non, ni l’un ni l’autre ! Et je ne vais pas faire durer : l’outil qui guide aujourd’hui les Tisse-Étoiles en mer, on l’appelle bien le Panneau aux Mille Étoiles, n’est-ce pas ? Ju utilisait le même... sauf que le sien, c’était le tout premier.",
            ["DialogueId"] = 51125715,
            ["GUID"] = "7FFCE49E",
            ["NextDialogue"] = 51125716,
            ["SpeakNpcId"] = 701041,
            },
        [51125716] = {
            ["Content"] = "他用几块木板测绘星辰，记录航向，这才能在茫茫大海上自由来去，不受羁绊。",
            ["ContentFR"] = "À l’aide de simples planches de bois, il observa les étoiles, consigna les routes, et put ainsi parcourir l’océan librement, sans entraves.",
            ["DialogueId"] = 51125716,
            ["GUID"] = "7FFCE4C8",
            ["NextDialogue"] = 51125717,
            ["SpeakNpcId"] = 701041,
            },
        [51125717] = {
            ["Content"] = "矩的成功出海与归来，让华胥的有龙们不再畏惧海洋，现在浮星埠的繁华和织星客们的昌盛，也是多亏了当年矩的先行。",
            ["ContentFR"] = "Le voyage de Ju, son départ et son retour, libérèrent les Descendants draconiques de Huaxu de leur peur de la mer. La prospérité actuelle du Quai-aux-Étoiles et l’essor des Tisse-Étoiles, nous les devons à ce pas qu’il osa faire le premier.",
            ["DialogueId"] = 51125717,
            ["GUID"] = "7FFCE4F2",
            ["NextDialogue"] = 51125718,
            ["SpeakNpcId"] = 701041,
            },
        [51125718] = {
            ["Content"] = "所以，矩和飏，都是咱们要时时牢记于心的开国贤君，没有他们，就没有今天的华胥，我们要时时刻刻记住他们的名字和事迹！懂了吗？",
            ["ContentFR"] = "Voilà pourquoi Ju et Yang sont à jamais nos sages fondateurs. Sans eux, Huaxu n’existerait pas telle que nous la connaissons aujourd’hui. N’oubliez jamais leurs noms, ni leurs actes. Compris ?",
            ["DialogueId"] = 51125718,
            ["GUID"] = "7FFCE51C",
            ["NextDialogue"] = 51125719,
            ["SpeakNpcId"] = 701041,
            },
        [51125719] = {
            ["Content"] = "（响起一阵叫好声。）",
            ["ContentFR"] = "Une vague d’acclamations s’élève parmi la foule.",
            ["DialogueId"] = 51125719,
            ["GUID"] = "7FFCE546",
            },
        [51125720] = {
            ["Content"] = "不听了。",
            ["ContentFR"] = "<I>Ne plus écouter</>",
            ["DialogueId"] = 51125720,
            ["GUID"] = "7FFCE570",
            ["NextDialogue"] = 51125721,
            },
        [51125721] = {
            ["Content"] = "（身后传来老柳头宣扬两位华胥开国贤君事迹的声音和喝茶群众的叫好声……）",
            ["ContentFR"] = "Dans votre dos, la voix du Vieux Liu continue de vanter les exploits des deux fondateurs de Huaxu, tandis que la foule applaudit en buvant son thé...",
            ["DialogueId"] = 51125721,
            ["GUID"] = "7FFCE59A",
            },
        [51125801] = {
            ["Content"] = "千星板运作情况一切正常，算算时间，马上要到下一次保养的日子了……",
            ["ContentFR"] = "Le Panneau aux Mille Étoiles fonctionne normalement... À bien y réfléchir, l’échéance de la prochaine maintenance approche.",
            ["DialogueId"] = 51125801,
            ["GUID"] = "7FFCF2BA",
            ["NextDialogue"] = 51125802,
            ["SpeakNpcId"] = 701042,
            },
        [51125802] = {
            ["Content"] = "这千星板上了船还没个三年，怎么就这么快就要去保养了呢，这次不知道他们还记不记得提前预约机枢派的师傅……先看看刻度有没有被磨坏吧！",
            ["ContentFR"] = "Cela fait à peine trois ans qu’il a été installé à bord... Comment se fait-il qu’il faille déjà l’envoyer en maintenance ? J’espère qu’ils n’ont pas oublié de prendre rendez-vous avec la Secte Jishu... Voyons si les graduations ne sont pas trop usées.",
            ["DialogueId"] = 51125802,
            ["GUID"] = "7FFCF2E4",
            ["NextDialogue"] = 51125803,
            ["SpeakNpcId"] = 701042,
            },
        [51125803] = {
            ["Content"] = "呀！吓了我一跳，你是异国人吗？在咱们船上做什么？",
            ["ContentFR"] = "Ah ! Vous m’avez fait peur. Vous n’êtes pas d’ici, hein ? Que faites-vous sur notre navire ?",
            ["DialogueId"] = 51125803,
            ["GUID"] = "7FFCF30E",
            ["NextOptions"] = {
                [1] = 51125804,
                [2] = 51125807,
                },
            ["SpeakNpcId"] = 701042,
            },
        [51125804] = {
            ["Content"] = "好奇你在做什么。",
            ["ContentFR"] = "<I>Je suis </>{性别:<I>curieux</>|<I>curieuse</>} <I>de savoir ce que vous faites.</>",
            ["DialogueId"] = 51125804,
            ["GUID"] = "7FFCF338",
            ["ImprPlusId"] = 1208,
            ["NextDialogue"] = 51125805,
            },
        [51125805] = {
            ["Content"] = "我？我在查看这船上千星板的情况呀，我是这艘船上配的工匠，专门负责日常维护这千星板的运作，要是没有这千星板，这船只可就没法出航啦。",
            ["ContentFR"] = "Moi ? Je vérifie l’état du Panneau aux Mille Étoiles. Je suis l’artisan affecté à ce navire, chargé de son entretien quotidien. Sans lui, le bateau serait incapable de prendre la mer.",
            ["DialogueId"] = 51125805,
            ["GUID"] = "7FFCF362",
            ["NextDialogue"] = 51125806,
            ["SpeakNpcId"] = 701042,
            },
        [51125806] = {
            ["Content"] = "你有事的话，以后再来找我吧，现在我还要仔细检查一下过热情况……",
            ["ContentFR"] = "Si vous avez besoin de quelque chose, revenez plus tard. Je dois encore contrôler les risques de surchauffe...",
            ["DialogueId"] = 51125806,
            ["GUID"] = "7FFCF38C",
            ["SpeakNpcId"] = 701042,
            },
        [51125807] = {
            ["Content"] = "闲逛到这里了。",
            ["ContentFR"] = "<I>Je me promenais simplement.</>",
            ["DialogueId"] = 51125807,
            ["GUID"] = "7FFCF3B6",
            ["ImprPlusId"] = 1207,
            ["NextDialogue"] = 51125808,
            },
        [51125808] = {
            ["Content"] = "哦哦是吗？可我在检查千星板的情况呢，要是出了问题，这船就没法出航啦，你有什么事情的话以后再来找我聊吧。",
            ["ContentFR"] = "Je vois... mais je suis en pleine vérification du Panneau. Au moindre problème, le navire ne pourra pas appareiller. Si vous avez besoin de moi, revenez plus tard.",
            ["DialogueId"] = 51125808,
            ["GUID"] = "7FFCF3E0",
            ["SpeakNpcId"] = 701042,
            },
        [51125809] = {
            ["Content"] = "千星板运作情况一切正常，算算时间，马上要到下一次保养的日子了……",
            ["ContentFR"] = "Le Panneau aux Mille Étoiles fonctionne normalement... À bien y réfléchir, l’échéance de la prochaine maintenance approche.",
            ["DialogueId"] = 51125809,
            ["GUID"] = "7FFCF40A",
            ["NextDialogue"] = 51125810,
            ["SpeakNpcId"] = 701042,
            },
        [51125810] = {
            ["Content"] = "这个刻度误差……我手动增加五次校准运算后结果也大差不差……那是不是可以申请延期保养时间了。",
            ["ContentFR"] = "Cette légère erreur de graduation... après cinq recalibrages manuels, les résultats restent acceptables. Peut-être pourrions-nous demander un report de maintenance.",
            ["DialogueId"] = 51125810,
            ["GUID"] = "7FFCF434",
            ["NextDialogue"] = 51125811,
            ["SpeakNpcId"] = 701042,
            },
        [51125811] = {
            ["Content"] = "呀，又是你，异国人，你又逛到我这啦。",
            ["ContentFR"] = "Ah, c’est encore vous, l’{性别:étranger|étrangère}. Vous voilà revenu jeter un coup d’œil ?",
            ["DialogueId"] = 51125811,
            ["GUID"] = "7FFCF45E",
            ["NextOptions"] = {
                [1] = 51125812,
                [2] = 51125815,
                [3] = 51125825,
                },
            ["SpeakNpcId"] = 701042,
            },
        [51125812] = {
            ["Content"] = "师傅你是做什么的？",
            ["ContentFR"] = "<I>Quel est votre métier ?</>",
            ["DialogueId"] = 51125812,
            ["GUID"] = "7FFCF488",
            ["NextDialogue"] = 51125813,
            },
        [51125813] = {
            ["Content"] = "我吗？自然是这船上配的工匠啦，我的工作就是负责维护千星板的运作情况，保证它一切正常，不会临时出意外，不然会影响到下一次出航。",
            ["ContentFR"] = "Moi ? Je suis l’artisan affecté à ce navire. Mon rôle est d’assurer le bon fonctionnement du Panneau aux Mille Étoiles, afin qu’aucune panne imprévue ne compromette le prochain départ.",
            ["DialogueId"] = 51125813,
            ["GUID"] = "7FFCF4B2",
            ["NextDialogue"] = 51125814,
            ["SpeakNpcId"] = 701042,
            },
        [51125814] = {
            ["Content"] = "这些信息都要记录下来，找天禄司申请通文时用得到呢。",
            ["ContentFR"] = "Toutes ces données doivent être consignées. Elles seront nécessaires lors de la demande de documents auprès du Bureau de la Fortune Céleste.",
            ["DialogueId"] = 51125814,
            ["GUID"] = "7FFCF4DC",
            ["NextOptions"] = {
                [1] = 51125815,
                [2] = 51125825,
                },
            ["SpeakNpcId"] = 701042,
            },
        [51125815] = {
            ["Content"] = "千星板是什么？",
            ["ContentFR"] = "<I>Qu’est-ce que le Panneau aux Mille Étoiles ?</>",
            ["DialogueId"] = 51125815,
            ["GUID"] = "7FFCF506",
            ["NextDialogue"] = 51125816,
            },
        [51125816] = {
            ["Content"] = "千星板可是咱们织星客们赖以生存的传家宝呢！在一望无际的大海上，只有它能观测天上的星星的方位，给船只导航指路，怎么都不会跑偏。",
            ["ContentFR"] = "C’est le pilier de l’existence des Tisse-Étoiles, un héritage transmis depuis des générations. Sur l’océan infini, lui seul permet d’observer la position des étoiles et de guider les navires sans jamais dévier de leur route.",
            ["DialogueId"] = 51125816,
            ["GUID"] = "7FFCF530",
            ["NextDialogue"] = 51125817,
            ["SpeakNpcId"] = 701042,
            },
        [51125817] = {
            ["Content"] = "华胥四周的海域紊乱，没有千星板的正确指引，织星客们很容易在乱流之间迷路，所以啊，我们每回远航之前，都需要仔细检查千星板的情况。",
            ["ContentFR"] = "Les mers autour de Huaxu sont instables. Sans le guidage précis du Panneau, les Tisse-Étoiles se perdraient aisément dans les courants chaotiques. Voilà pourquoi nous l’inspectons toujours avant chaque grande traversée.",
            ["DialogueId"] = 51125817,
            ["GUID"] = "7FFCF55A",
            ["NextOptions"] = {
                [1] = 51125818,
                [2] = 51125822,
                },
            ["SpeakNpcId"] = 701042,
            },
        [51125818] = {
            ["Content"] = "你说的保养是什么意思？",
            ["ContentFR"] = "<I>Que signifie la maintenance dont vous parlez ?</>",
            ["DialogueId"] = 51125818,
            ["GUID"] = "7FFCF584",
            ["NextDialogue"] = 51125819,
            },
        [51125819] = {
            ["Content"] = "保养吗？其实就是让机枢派的老师傅们帮咱们看看千星板是否出现一些零件松动之类的情况，虽然大多数情况都没什么问题，但是在海上航行，难免会有浪涛大时磕碰。",
            ["ContentFR"] = "La maintenance consiste à confier le Panneau aux maîtres artisans de la Secte Jishu, afin qu’ils vérifient si certaines pièces se sont desserrées. En général, tout va bien, mais en mer, les chocs sont inévitables.",
            ["DialogueId"] = 51125819,
            ["GUID"] = "7FFCF5AE",
            ["NextDialogue"] = 51125820,
            ["SpeakNpcId"] = 701042,
            },
        [51125820] = {
            ["Content"] = "我们这种普通工匠能看出问题但不会修，只有去机枢派找有专门检测器材的老师傅们帮着看看，但是频率不需要太高，大概四五年一次就好。",
            ["ContentFR"] = "Nous, simples artisans, pouvons détecter les anomalies, mais pas les réparer. Seuls les maîtres de la Secte disposent des instruments nécessaires. Une vérification tous les quatre ou cinq ans suffit amplement.",
            ["DialogueId"] = 51125820,
            ["GUID"] = "7FFCF5D8",
            ["NextDialogue"] = 51125821,
            ["SpeakNpcId"] = 701042,
            },
        [51125821] = {
            ["Content"] = "不过即使是过去找他们，也需要给到日常测量的一些数据，方便给出更好的判断。",
            ["ContentFR"] = "Et bien sûr, nous devons leur fournir nos relevés quotidiens pour qu’ils puissent établir un diagnostic précis.",
            ["DialogueId"] = 51125821,
            ["GUID"] = "7FFCF602",
            ["SpeakNpcId"] = 701042,
            },
        [51125822] = {
            ["Content"] = "千星板在哪，我怎么没看到？",
            ["ContentFR"] = "<I>Où se trouve le Panneau aux Mille Étoiles ? Je ne le vois pas.</>",
            ["DialogueId"] = 51125822,
            ["GUID"] = "7FFCF62C",
            ["NextDialogue"] = 51125823,
            },
        [51125823] = {
            ["Content"] = "哈哈，笨家伙，就在咱们脚下呀，咱们这种用来出海的大船，千星板都是装在船舱里的，只有最大的那块板会倒置朝向天空，方便观测星空。",
            ["ContentFR"] = "Ha ha ! Juste sous vos pieds, voyons. Sur les grands navires de haute mer, le Panneau est installé dans la cale. Seule la plaque principale est inversée vers le ciel pour observer les étoiles.",
            ["DialogueId"] = 51125823,
            ["GUID"] = "7FFCF656",
            ["NextDialogue"] = 51125824,
            ["SpeakNpcId"] = 701042,
            },
        [51125824] = {
            ["Content"] = "用你们外国人能听懂的话来形容，大概有些像那种大型的吊灯，我们在海上的时候，每时每刻都需要有人在船舱里值班记录千星板转动的幅度，不然就容易偏航呢。",
            ["ContentFR"] = "Pour que vous compreniez avec vos références étrangères... disons que cela ressemble à un immense lustre. En mer, quelqu’un doit surveiller en permanence ses mouvements, sous peine de dévier de la trajectoire.",
            ["DialogueId"] = 51125824,
            ["GUID"] = "7FFCF680",
            ["SpeakNpcId"] = 701042,
            },
        [51125825] = {
            ["Content"] = "没什么要问的。",
            ["ContentFR"] = "<I>Je n’ai plus de questions.</>",
            ["DialogueId"] = 51125825,
            ["GUID"] = "7FFCF6AA",
            ["NextDialogue"] = 51125826,
            },
        [51125826] = {
            ["Content"] = "有事再来找我吧，我要测量新的数据啦。",
            ["ContentFR"] = "Dans ce cas, revenez me voir plus tard. Je dois encore relever de nouvelles données.",
            ["DialogueId"] = 51125826,
            ["GUID"] = "7FFCF6D4",
            ["SpeakNpcId"] = 701042,
            },
        [51125901] = {
            ["Content"] = "白女士，这个什么什么身，是什么意思，我听不懂。",
            ["ContentFR"] = "« Attenter au corps... » ? Euh... ça veut dire quoi, exactement ?",
            ["DialogueId"] = 51125901,
            ["GUID"] = "7FFD0322",
            ["NextDialogue"] = 51125902,
            ["SpeakNpcId"] = 701043,
            },
        [51125902] = {
            ["Content"] = "戕，这个字念戕，就是和你们异国人经常用的枪字一个读音。",
            ["ContentFR"] = "Cela signifie blesser quelqu’un. L’attaquer. Lui faire du mal, quelle qu’en soit la manière.",
            ["DialogueId"] = 51125902,
            ["GUID"] = "7FFD034C",
            ["NextDialogue"] = 51125903,
            ["SpeakNpcId"] = 701044,
            },
        [51125903] = {
            ["Content"] = "哦哦！枪！枪身就是，用枪打对方的身子，对不对？",
            ["ContentFR"] = "Oh ! Donc... pas tirer sur les gens, c’est ça ?",
            ["DialogueId"] = 51125903,
            ["GUID"] = "7FFD0376",
            ["NextDialogue"] = 51125904,
            ["SpeakNpcId"] = 701043,
            },
        [51125904] = {
            ["Content"] = "这……诶，你就这么理解吧，也没什么问题，总之就是，在我们华胥，不能出现伤人之事，所以你带来的枪我们就先没收了，等你离开华胥之时再还给你。",
            ["ContentFR"] = "... Disons que vous pouvez le comprendre ainsi. En résumé, à Huaxu, toute forme de violence est proscrite. C’est pourquoi les armes que vous avez apportées seront mises sous scellés et vous seront rendues à votre départ.",
            ["DialogueId"] = 51125904,
            ["GUID"] = "7FFD03A0",
            ["NextDialogue"] = 51125905,
            ["SpeakNpcId"] = 701044,
            },
        [51125905] = {
            ["Content"] = "可以可以，我来做生意，听本地的规矩，大风什么的，还有别的吗？",
            ["ContentFR"] = "D’accord, d’accord. Je suis ici pour faire du commerce, je respecte les règles locales. Le Dafeng et tout ça... il y a d’autres interdictions ?",
            ["DialogueId"] = 51125905,
            ["GUID"] = "7FFD03CA",
            ["NextDialogue"] = 51125906,
            ["SpeakNpcId"] = 701043,
            },
        [51125906] = {
            ["Content"] = "你既然是来做生意的，那这第二条：毁约背盟，不可为也。你可得谨记于心。",
            ["ContentFR"] = "Puisque vous venez pour commercer, retenez bien le second chapitre : « Rompre un serment ou trahir une alliance — cela est proscrit. »",
            ["DialogueId"] = 51125906,
            ["GUID"] = "7FFD03F4",
            ["NextDialogue"] = 51125907,
            ["SpeakNpcId"] = 701044,
            },
        [51125907] = {
            ["Content"] = "毁约，听得懂，背萌是什么意思？背上萌萌的吗？",
            ["ContentFR"] = "Rompre un serment, je vois... mais trahir une alliance ? Genre... abandonner ses partenaires en cours de route ?",
            ["DialogueId"] = 51125907,
            ["GUID"] = "7FFD041E",
            ["NextDialogue"] = 51125908,
            ["SpeakNpcId"] = 701043,
            },
        [51125908] = {
            ["Content"] = "不是那个萌……是盟约的盟，意思就是，你如果和咱们华胥人做生意，在谈妥价格之后，一定要在白龙神君的见证下立契，不然我们是不敢信你的。",
            ["ContentFR"] = "Exactement. Si vous faites affaire avec un habitant de Huaxu, une fois le prix fixé, vous devez conclure un pacte sous le regard du Seigneur Dragon d’Argent. Sans cela, nous ne pouvons vous accorder notre confiance.",
            ["DialogueId"] = 51125908,
            ["GUID"] = "7FFD0448",
            ["NextDialogue"] = 51125909,
            ["SpeakNpcId"] = 701044,
            },
        [51125909] = {
            ["Content"] = "哦哦，我明白了，你们要写合同，我们那边也写的，没问题没问题！",
            ["ContentFR"] = "Oh, je comprends ! Vous signez des contrats ! On fait pareil chez nous, aucun souci !",
            ["DialogueId"] = 51125909,
            ["GUID"] = "7FFD0472",
            ["NextDialogue"] = 51125910,
            ["SpeakNpcId"] = 701043,
            },
        [51125910] = {
            ["Content"] = "不不不，不一样，我们这是契约，是在白龙神君的见证下完成的，我们写的合同都是用沉月香香灰掺进墨里写，立契的时候便有了神君亲鉴。",
            ["ContentFR"] = "Non, ce n’est pas la même chose. Nos contrats sont sacrés, conclus sous le témoignage du Seigneur Dragon d’Argent. L’encre est mêlée aux cendres de Lune Profonde : dès la signature, le serment est reconnu.",
            ["DialogueId"] = 51125910,
            ["GUID"] = "7FFD049C",
            ["NextDialogue"] = 51125911,
            ["SpeakNpcId"] = 701044,
            },
        [51125911] = {
            ["Content"] = "如若一方背誓，可是会被狴犴大人追缉的！",
            ["ContentFR"] = "Et si l’une des parties venait à trahir ce serment... les Bi’an se chargeraient de la traquer.",
            ["DialogueId"] = 51125911,
            ["GUID"] = "7FFD04C6",
            ["NextDialogue"] = 51125912,
            ["SpeakNpcId"] = 701044,
            },
        [51125912] = {
            ["Content"] = "狴犴！华胥大狗，这个我知道的！",
            ["ContentFR"] = "Les Bi’an ? Les gros chiens de Huaxu ? Je connais !",
            ["DialogueId"] = 51125912,
            ["GUID"] = "7FFD04F0",
            ["NextDialogue"] = 51125913,
            ["SpeakNpcId"] = 701043,
            },
        [51125913] = {
            ["Content"] = "你这家伙，好生无礼！不可以这么称呼狴犴大人！",
            ["ContentFR"] = "Quelle impolitesse ! Ne vous permettez pas d’appeler les Bi’an ainsi !",
            ["DialogueId"] = 51125913,
            ["GUID"] = "7FFD051A",
            ["SpeakNpcId"] = 701044,
            },
        [51126001] = {
            ["Content"] = "妈妈说的都是骗我的，什么叫我大了就可以长出角，前年说去年长，去年说今年长。结果还是什么都没有……",
            ["ContentFR"] = "Maman me ment, c’est sûr. Elle disait que quand je serais grand, j’en aurais. L’an dernier elle disait « l’an prochain », et avant encore « l’an prochain »... et toujours rien...",
            ["DialogueId"] = 51126001,
            ["GUID"] = "7FFD138A",
            ["NextDialogue"] = 51126002,
            ["SpeakNpcId"] = 701045,
            },
        [51126002] = {
            ["Content"] = "难道我根本长不出角吗？不要啊，我不想当抟土氏，我想当光荣的有龙氏。",
            ["ContentFR"] = "Et si elles ne poussent pas ? Non... je ne veux pas être un Enfant de la Terre. Je veux devenir un glorieux Descendant draconique !",
