            ["GUID"] = "7FFD13B4",
            ["NextOptions"] = {
                [1] = 51126003,
                [2] = 51126005,
                },
            ["SpeakNpcId"] = 701045,
            },
        [51126003] = {
            ["Content"] = "当抟土氏不好吗？",
            ["ContentFR"] = "<I>Être un Enfant de la Terre, c’est si mal que ça ?</>",
            ["DialogueId"] = 51126003,
            ["GUID"] = "7FFD13DE",
            ["ImprPlusId"] = 1207,
            ["NextDialogue"] = 51126004,
            },
        [51126004] = {
            ["Content"] = "不好不好，当然不好，只有成为有龙才有强大的魔法，只有成为有龙才能在华胥为神君效力。",
            ["ContentFR"] = "Pas bien du tout ! Les Enfants de la Terres n’ont pas de magie ! Seuls les Descendants draconiques sont puissants, et seuls eux peuvent servir le Dragon d’Argent à Huaxu !",
            ["DialogueId"] = 51126004,
            ["GUID"] = "7FFD1408",
            ["SpeakNpcId"] = 701045,
            },
        [51126005] = {
            ["Content"] = "有龙可能会变成秽兽的。",
            ["ContentFR"] = "<I>Les Descendants draconiques peuvent devenir des Souillés.</>",
            ["DialogueId"] = 51126005,
            ["GUID"] = "7FFD1432",
            ["ImprPlusId"] = 1209,
            ["NextDialogue"] = 51126006,
            },
        [51126006] = {
            ["Content"] = "秽兽？我才不怕呢，即使变成了秽兽，我也会成为光荣的狴犴大人，我妈妈一定也会为我骄傲的！",
            ["ContentFR"] = "Des Souillés ? Même pas peur ! Même si je devenais un Souillé, je serais un glorieux Bi’an ! Maman serait fière de moi !",
            ["DialogueId"] = 51126006,
            ["GUID"] = "7FFD145C",
            ["SpeakNpcId"] = 701045,
            },
        [51126007] = {
            ["Content"] = "怎么样才能长出角呢，我揪……我揪……嗷！好痛……",
            ["ContentFR"] = "Comment on fait pour faire pousser des cornes... si je tire un peu... je tire... <I>aïe !</> Ça fait mal...",
            ["DialogueId"] = 51126007,
            ["GUID"] = "7FFD1486",
            ["NextDialogue"] = 51126008,
            ["SpeakNpcId"] = 701045,
            },
        [51126008] = {
            ["Content"] = "是你啊，{性别：大哥哥|大姐姐}，我妈妈最近告诉我一个新办法，就是在这浮星埠去摸过往路过有龙氏的角，摸多了就可以长出自己的角来。",
            ["ContentFR"] = "Oh ! C’est toi ! Maman m’a appris une nouvelle méthode : ici, au Quai-aux-Étoiles, il suffit de toucher les cornes des Descendants draconiques qui passent. Si on les touche souvent, les miennes pousseront aussi !",
            ["DialogueId"] = 51126008,
            ["GUID"] = "7FFD14B0",
            ["NextDialogue"] = 51126009,
            ["SpeakNpcId"] = 701045,
            },
        [51126009] = {
            ["Content"] = "她还说，如果摸的多，就可以长出一模一样的，所以一定要找角好看的有龙氏！{性别：大哥哥|大姐姐}，我喜欢你的角，你可以给我摸摸吗？",
            ["ContentFR"] = "Et elle a dit que si on touche beaucoup, elles pousseront pareilles ! Alors il faut trouver quelqu’un avec de belles cornes ! Dis, j’aime bien la tienne... je peux toucher ?",
            ["DialogueId"] = 51126009,
            ["GUID"] = "7FFD14DA",
            ["NextOptions"] = {
