        [51126911] = {
            ["Content"] = "没闻到。",
            ["ContentFR"] = "<I>Je ne sens rien.</>",
            ["DialogueId"] = 51126911,
            ["GUID"] = "7FFDA8D6",
            ["NextDialogue"] = 51126912,
            },
        [51126912] = {
            ["Content"] = "怎么会呢？这里真的有种味道……像家里点的蜡烛燃烧完之后，那股温暖到灼人的味道，让人安心……让人沉醉。",
            ["ContentFR"] = "Comment ça ? Elle est là pourtant... Comme l’odeur d’une bougie une fois consumée, chez soi... Une chaleur douce, presque brûlante... Rassurante... enivrante...",
            ["DialogueId"] = 51126912,
            ["GUID"] = "7FFDA900",
            ["NextOptions"] = {
                [1] = 51126913,
                [2] = 51126916,
                },
            ["SpeakNpcId"] = 701059,
            },
        [51126913] = {
            ["Content"] = "也许只是来祭拜的华胥民点的香。",
            ["ContentFR"] = "<I>Peut-être simplement l’encens brûlé par les habitants de Huaxu venus se recueillir.</>",
            ["DialogueId"] = 51126913,
            ["GUID"] = "7FFDA92A",
            ["NextDialogue"] = 51126914,
            },
        [51126914] = {
            ["Content"] = "不，绝对不是，祭拜的香里有哀伤的味道，想念的味道，却没有家的味道，我曾经离开过这里很多次，但最终都会被这股香味吸引回来。",
            ["ContentFR"] = "Non... ce n’est pas ça. L’encens du recueillement porte la tristesse, le manque... mais pas l’odeur de la maison. J’ai quitté cet endroit tant de fois... et pourtant, cette fragrance me ramène toujours ici.",
            ["DialogueId"] = 51126914,
            ["GUID"] = "7FFDA954",
            ["NextDialogue"] = 51126915,
            ["SpeakNpcId"] = 701059,
            },
        [51126915] = {
            ["Content"] = "你说，这里是不是就是我的家？生前的我，难道是住在树上的吗？难道我是一片树叶？",
            ["ContentFR"] = "Dis-moi... et si cet endroit était ma maison ? Avant de mourir... vivais-je dans cet arbre ? Ou bien... étais-je une feuille ?",
            ["DialogueId"] = 51126915,
            ["GUID"] = "7FFDA97E",
            ["SpeakNpcId"] = 701059,
            },
        [51126916] = {
            ["Content"] = "据我所知，没有树叶变成无由生的说法。",
            ["ContentFR"] = "<I>À ma connaissance, les feuilles ne deviennent pas des Wishen.</>",
            ["DialogueId"] = 51126916,
            ["GUID"] = "7FFDA9A8",
            ["NextDialogue"] = 51126917,
            },
        [51126917] = {
            ["Content"] = "说的也是……那么我是什么呢？我是一抔泥土，我是这里的空气，是路边的石子。唔……我只想一直待在这里……好舒服，再也不想离开了。",
            ["ContentFR"] = "C’est vrai... Alors que suis-je ? De la terre ? L’air qui flotte ici ? Un caillou au bord du chemin... Mmm... J’aimerais rester ici pour toujours... C’est si confortable... Je n’ai plus envie de partir...",
            ["DialogueId"] = 51126917,
            ["GUID"] = "7FFDA9D2",
            ["SpeakNpcId"] = 701059,
            },
        [51126918] = {
            ["Content"] = "好像……闻到了？",
            ["ContentFR"] = "<I>Attends... je crois que je sens quelque chose.</>",
            ["DialogueId"] = 51126918,
            ["GUID"] = "7FFDA9FC",
            ["NextDialogue"] = 51126919,
            },
        [51126919] = {
            ["Content"] = "对吧对吧，你也闻到了，就是那种家里点的蜡烛燃烧完之后，那股温暖到灼人的味道，让人安心……让人沉醉。",
            ["ContentFR"] = "Tu vois ! Cette odeur... Comme une bougie consumée à la maison... Chaleureuse, presque brûlante... Rassurante... enivrante...",
            ["DialogueId"] = 51126919,
            ["GUID"] = "7FFDAA26",
            ["NextDialogue"] = 51126920,
            ["SpeakNpcId"] = 701059,
            },
        [51126920] = {
            ["Content"] = "所以我每次都会回来，无论走了多远，我都会回来，你说，这里会不会就是我的家，不然我为什么会有如此安心的感觉？",
            ["ContentFR"] = "C’est pour ça que je reviens toujours. Peu importe la distance, je finis par revenir ici. Dis... si ce n’est pas ma maison, pourquoi me sentirais-je aussi apaisé ?",
            ["DialogueId"] = 51126920,
            ["GUID"] = "7FFDAA50",
            ["NextOptions"] = {
                [1] = 51126921,
                [2] = 51126923,
                },
            ["SpeakNpcId"] = 701059,
            },
        [51126921] = {
            ["Content"] = "这里怎么看都不像是你的家吧。",
            ["ContentFR"] = "<I>Honnêtement... cet endroit ne ressemble pas à une maison.</>",
            ["DialogueId"] = 51126921,
            ["GUID"] = "7FFDAA7A",
            ["NextDialogue"] = 51126922,
            },
        [51126922] = {
            ["Content"] = "可我有一种感觉，我和这里的一切互相绑定，我们共享一种呼吸，你闻，温暖的气息包裹着我们，我要回归了……",
            ["ContentFR"] = "Mais je le sens... Je suis lié à tout ici. Nous partageons un même souffle. Respire... Cette chaleur nous enveloppe...  Je... je retourne à la maison...",
            ["DialogueId"] = 51126922,
            ["GUID"] = "7FFDAAA4",
            ["SpeakNpcId"] = 701059,
            },
        [51126923] = {
            ["Content"] = "这里只有一棵树。",
            ["ContentFR"] = "<I>Il n’y a ici qu’un arbre.</>",
            ["DialogueId"] = 51126923,
            ["GUID"] = "7FFDAACE",
            ["NextDialogue"] = 51126924,
            },
        [51126924] = {
            ["Content"] = "也许……也许我生前就是一片树叶也说不准？是了，所以我才对这里如此熟悉，这里就是我的家，我是一只树叶化作的无由生！",
            ["ContentFR"] = "Peut-être... peut-être étais-je vraiment une feuille autrefois ? Oui... c’est ça. Voilà pourquoi cet endroit m’est si familier. C’est ici, ma maison. Je suis un Wishen né d’une feuille...",
            ["DialogueId"] = 51126924,
            ["GUID"] = "7FFDAAF8",
            ["SpeakNpcId"] = 701059,
            },
        [51126925] = {
            ["Content"] = "离开吧。",
            ["ContentFR"] = "Je m’en vais.",
            ["DialogueId"] = 51126925,
            ["GUID"] = "7FFDAB22",
            ["NextDialogue"] = 51126926,
            },
        [51126926] = {
            ["Content"] = "你不会理解的，回家，回到家的感觉……",
            ["ContentFR"] = "Tu ne peux pas comprendre... ce sentiment de rentrer chez soi...",
            ["DialogueId"] = 51126926,
            ["GUID"] = "7FFDAB4C",
            ["SpeakNpcId"] = 701059,
            },
        [51127001] = {
            ["Content"] = "神君慈光，照彻幽乡，孤魂滞魄，莫再彷徨。往昔苦厄，皆可暂忘，今朝受度，得沐恩光。",
            ["ContentFR"] = "« Que la lumière miséricordieuse du Seigneur Dragon d’Argent éclaire jusqu’aux royaumes d’ombre. Âmes solitaires, esprits entravés, ne vous égarez plus, ne demeurez plus en errance. Que les souffrances d’autrefois soient mises de côté, qu’aujourd’hui vous receviez la délivrance, et soyez baignées dans l’éclat de sa grâce... »",
            ["DialogueId"] = 51127001,
            ["GUID"] = "7FFDB79A",
            ["NextOptions"] = {
                [1] = 51127002,
                },
            ["SpeakNpcId"] = 701060,
            },
        [51127002] = {
            ["Content"] = "你在念什么？",
            ["ContentFR"] = "<I>Que récitez-vous ?</>",
            ["DialogueId"] = 51127002,
            ["GUID"] = "7FFDB7C4",
            ["NextDialogue"] = 51127003,
            },
        [51127003] = {
            ["Content"] = "你好，陌生人，我在为这里的无由生们诵念往生的经文，是无穷藏派流传下来的。",
            ["ContentFR"] = "Bonjour, {性别:voyageur|voyageuse}. Je récite des sutras pour guider les Wishen de ce lieu vers le repos. Ils proviennent de la tradition de la Secte de l’Insondable Trésor.",
            ["DialogueId"] = 51127003,
            ["GUID"] = "7FFDB7EE",
            ["SpeakNpcId"] = 701060,
            },
        [51127004] = {
            ["Content"] = "敕愿亡魂，早离迷茫，急急如律，往生乐乡……",
            ["ContentFR"] = "« Âmes errantes, par décret et par vœu, quittez la confusion sans tarder. Hâtez-vous — selon la Loi céleste — vers la Terre de Félicité. »",
            ["DialogueId"] = 51127004,
            ["GUID"] = "7FFDB818",
            ["NextDialogue"] = 51127005,
            ["SpeakNpcId"] = 701060,
            },
        [51127005] = {
            ["Content"] = "是你啊，你要和我一起念吗？",
            ["ContentFR"] = "Ah... c’est vous. Souhaitez-vous réciter avec moi ?",
            ["DialogueId"] = 51127005,
            ["GUID"] = "7FFDB842",
            ["NextOptions"] = {
                [1] = 51127006,
                [2] = 51127014,
                [3] = 51127026,
                },
            ["SpeakNpcId"] = 701060,
            },
        [51127006] = {
            ["Content"] = "可以完整念一遍吗？",
            ["ContentFR"] = "<I>Pouvez-vous réciter la prière en entier ?</>",
            ["DialogueId"] = 51127006,
            ["GUID"] = "7FFDB86C",
            ["NextDialogue"] = 51127007,
            },
        [51127007] = {
            ["Content"] = "当然，如果你想和我一起念就再好不过了。",
            ["ContentFR"] = "Bien sûr. Et ce serait encore mieux si vous m’accompagniez.",
            ["DialogueId"] = 51127007,
            ["GUID"] = "7FFDB896",
            ["NextDialogue"] = 51127008,
            ["SpeakNpcId"] = 701060,
            },
        [51127008] = {
            ["Content"] = "神君慈光，照彻幽乡，孤魂滞魄，莫再彷徨。",
            ["ContentFR"] = "Que la lumière miséricordieuse du Seigneur Dragon d’Argent éclaire jusqu’aux royaumes d’ombre. Âmes solitaires, esprits entravés, ne vous égarez plus, ne demeurez plus en errance.",
            ["DialogueId"] = 51127008,
            ["GUID"] = "7FFDB8C0",
            ["NextDialogue"] = 51127009,
            ["SpeakNpcId"] = 701060,
            },
        [51127009] = {
            ["Content"] = "往昔苦厄，皆可暂忘，今朝受度，得沐恩光。",
            ["ContentFR"] = "Que les souffrances d’autrefois soient mises de côté, qu’aujourd’hui vous receviez la délivrance, et soyez baignées dans l’éclat de sa grâce.",
            ["DialogueId"] = 51127009,
            ["GUID"] = "7FFDB8EA",
            ["NextDialogue"] = 51127010,
            ["SpeakNpcId"] = 701060,
            },
        [51127010] = {
            ["Content"] = "横亡屈死，冤结尽解，牵绊执念，随光散场。",
            ["ContentFR"] = "Morts injustes, trépas prématurés, que les nœuds du ressentiment se dénouent. Que les liens et les obsessions se dispersent avec la lumière.",
            ["DialogueId"] = 51127010,
            ["GUID"] = "7FFDB914",
            ["NextDialogue"] = 51127011,
            ["SpeakNpcId"] = 701060,
            },
        [51127011] = {
            ["Content"] = "八卦引途，坎位通祥，往生善处，安稳安康。",
            ["ContentFR"] = "Que le Bagua vous ouvre la voie, que la position de Kan conduise au bon augure. Allez vers un lieu paisible, en sûreté, en sérénité.",
            ["DialogueId"] = 51127011,
            ["GUID"] = "7FFDB93E",
            ["NextDialogue"] = 51127012,
            ["SpeakNpcId"] = 701060,
            },
        [51127012] = {
            ["Content"] = "来世荣枯，随心所向，福缘自植，善果绵长。",
            ["ContentFR"] = "Dans les vies à venir, gloire ou déclin, suivez l’élan de votre cœur. Que les bénédictions prennent racine, et que les fruits du bien perdurent.",
            ["DialogueId"] = 51127012,
            ["GUID"] = "7FFDB968",
            ["NextDialogue"] = 51127013,
            ["SpeakNpcId"] = 701060,
            },
        [51127013] = {
            ["Content"] = "敕愿亡魂，早离迷茫，急急如律，往生乐乡。",
            ["ContentFR"] = "Âmes errantes, par décret et par vœu, quittez la confusion sans tarder. Hâtez-vous — selon la Loi céleste — vers la Terre de Félicité.",
            ["DialogueId"] = 51127013,
            ["GUID"] = "7FFDB992",
            ["SpeakNpcId"] = 701060,
            },
        [51127014] = {
            ["Content"] = "为什么要念这个？",
            ["ContentFR"] = "<I>Pourquoi récitez-vous cela ?</>",
            ["DialogueId"] = 51127014,
            ["GUID"] = "7FFDB9BC",
            ["NextDialogue"] = 51127015,
            },
        [51127015] = {
            ["Content"] = "我想为我的家人祈福，父亲……去年走了。家里只剩我和母亲，每当我想他的时候，都会来这里念上几遍经文。",
            ["ContentFR"] = "Je prie pour ma famille. Mon père... est décédé l’an dernier. Il ne reste plus que ma mère et moi. Quand il me manque, je viens ici réciter quelques prières.",
            ["DialogueId"] = 51127015,
            ["GUID"] = "7FFDB9E6",
            ["NextOptions"] = {
                [1] = 51127016,
                [2] = 51127019,
                [3] = 51127026,
                },
            ["SpeakNpcId"] = 701060,
            },
        [51127016] = {
            ["Content"] = "有用吗？",
            ["ContentFR"] = "<I>Est-ce que ça sert à quelque chose ?</>",
            ["DialogueId"] = 51127016,
            ["GUID"] = "7FFDBA10",
            ["NextDialogue"] = 51127017,
            },
        [51127017] = {
            ["Content"] = "有……或者没有……其实对我来说，都只是一种心理安慰罢了……小的时候我总想，父亲太累了，若是我长大了，一定要让他过上享福的好日子。",
            ["ContentFR"] = "Peut-être... ou peut-être pas. Pour moi, c’est surtout un réconfort. Quand j’étais enfant, je me disais toujours que mon père travaillait trop. Je pensais qu’une fois adulte, je pourrais enfin lui offrir une vie paisible.",
            ["DialogueId"] = 51127017,
            ["GUID"] = "7FFDBA3A",
            ["NextDialogue"] = 51127018,
            ["SpeakNpcId"] = 701060,
            },
        [51127018] = {
            ["Content"] = "可还没等我支撑起这个家，他就已经走了……我只能来此处念这些，希冀他能在我看不见的地方过上好日子……",
            ["ContentFR"] = "Mais avant que je puisse soutenir cette famille... il est parti. Alors je viens ici... en espérant qu’il vive bien, quelque part que je ne peux voir...",
            ["DialogueId"] = 51127018,
            ["GUID"] = "7FFDBA64",
            ["SpeakNpcId"] = 701060,
            },
        [51127019] = {
            ["Content"] = "为什么在这念？",
            ["ContentFR"] = "<I>Pourquoi venir ici ?</>",
            ["DialogueId"] = 51127019,
            ["GUID"] = "7FFDBA8E",
            ["NextDialogue"] = 51127020,
            },
        [51127020] = {
            ["Content"] = "您听说过华胥无由生的传说吧？无由生就是华胥执念未散的孤魂，我想，父亲如果对我们还有眷恋，或许也会成为无由生。",
            ["ContentFR"] = "Vous connaissez la légende des Wishen de Huaxu, n’est-ce pas ? Ce sont les âmes dont les attaches ne se sont pas dissipées. Si mon père avait encore des regrets... peut-être serait-il devenu un Wishen.",
            ["DialogueId"] = 51127020,
            ["GUID"] = "7FFDBAB8",
            ["NextDialogue"] = 51127021,
            ["SpeakNpcId"] = 701060,
            },
        [51127021] = {
            ["Content"] = "或许……或许也会出现在这里。",
            ["ContentFR"] = "Peut-être... peut-être apparaîtra-t-il ici un jour...",
            ["DialogueId"] = 51127021,
            ["GUID"] = "7FFDBAE2",
            ["NextOptions"] = {
                [1] = 51127022,
                [2] = 51127024,
                [3] = 51127026,
                },
            ["SpeakNpcId"] = 701060,
            },
        [51127022] = {
            ["Content"] = "为什么会觉得你父亲会出现在这里呢？",
            ["ContentFR"] = "<I>Pourquoi pensez-vous qu’il viendrait ici ?</>",
            ["DialogueId"] = 51127022,
            ["GUID"] = "7FFDBB0C",
            ["NextDialogue"] = 51127023,
            },
        [51127023] = {
            ["Content"] = "我也不知道……只是一种感觉吧，即便他不在，也当做为这里的其他执念未散的无由生祈福吧……如果他们也会去那个虚无缥缈的地方……请为我给父亲带个信。",
            ["ContentFR"] = "Je n’en sais rien... C’est juste un sentiment. Et même s’il n’est pas là, je prie pour les autres Wishen liés à ce monde. S’ils atteignent cet endroit vague et lointain... je leur demande de lui transmettre un message.",
            ["DialogueId"] = 51127023,
            ["GUID"] = "7FFDBB36",
            ["SpeakNpcId"] = 701060,
            },
        [51127024] = {
            ["Content"] = "如果他真能看到你现在的样子，应该会放下心来，没有执念了。",
            ["ContentFR"] = "<I>S’il pouvait vous voir aujourd’hui, il serait rassuré.</>",
            ["DialogueId"] = 51127024,
            ["GUID"] = "7FFDBB60",
            ["NextDialogue"] = 51127025,
            },
        [51127025] = {
            ["Content"] = "那就当我……为这里的其他执念未散的无由生祈福吧……如果他们也会去那个虚无缥缈的地方……请为我给父亲带个信。",
            ["ContentFR"] = "Alors... que cette prière soit pour eux. Et s’ils le croisent là-bas... qu’ils lui disent que je pense à lui.",
            ["DialogueId"] = 51127025,
            ["GUID"] = "7FFDBB8A",
            ["SpeakNpcId"] = 701060,
            },
        [51127026] = {
            ["Content"] = "默默离开。",
            ["ContentFR"] = "<I>S’éloigner en silence</>",
            ["DialogueId"] = 51127026,
            ["GUID"] = "7FFDBBB4",
            ["NextDialogue"] = 51127027,
            },
        [51127027] = {
            ["Content"] = "敕愿亡魂，早离迷茫，急急如律，往生乐乡……",
            ["ContentFR"] = "« Âmes errantes, par décret et par vœu, quittez la confusion sans tarder. Hâtez-vous — selon la Loi céleste — vers la Terre de Félicité. »",
            ["DialogueId"] = 51127027,
            ["GUID"] = "7FFDBBDE",
            ["SpeakNpcId"] = 701060,
            },
        [51127101] = {
            ["Content"] = "诶呀，爷爷老糊涂了，好笨，不是落在地上也不是水上，是我的头上，如果实在不行的话，落到肩上也可以。",
            ["ContentFR"] = "Oh là là... Grand-père, tu deviens vraiment étourdi... Pas par terre, pas dans l’eau — sur ma tête ! Bon... si c’est trop difficile, sur mon épaule, ça ira aussi !",
            ["DialogueId"] = 51127101,
            ["GUID"] = "7FFDC802",
            ["NextOptions"] = {
                [1] = 51127102,
                [2] = 51127104,
                },
            ["SpeakNpcId"] = 701061,
            },
        [51127102] = {
            ["Content"] = "你在自言自语吗？",
            ["ContentFR"] = "<I>Tu parles toute seule ?</>",
            ["DialogueId"] = 51127102,
            ["GUID"] = "7FFDC82C",
            ["ImprPlusId"] = 1208,
            ["NextDialogue"] = 51127103,
            },
        [51127103] = {
            ["Content"] = "自言自语？刚才可能是，但是你这不是主动和我搭话了吗，那现在我不是自言自语，而是在和你对话。",
            ["ContentFR"] = "Toute seule ? Peut-être avant... mais maintenant que tu me parles, je te réponds, non ?",
            ["DialogueId"] = 51127103,
            ["GUID"] = "7FFDC856",
            ["NextDialogue"] = 51127106,
            ["SpeakNpcId"] = 701061,
            },
        [51127104] = {
            ["Content"] = "你在和无由生说话？",
            ["ContentFR"] = "<I>Tu parlais à un Wishen ?</>",
            ["DialogueId"] = 51127104,
            ["GUID"] = "7FFDC880",
            ["ImprPlusId"] = 1209,
            ["NextDialogue"] = 51127105,
            },
        [51127105] = {
            ["Content"] = "不是啦，其实我只是在自言自语，但你现在主动和我搭话了，所以我现在在和你说话哦。",
            ["ContentFR"] = "Non, non ! Je parlais toute seule. Mais maintenant, je parle avec toi !",
            ["DialogueId"] = 51127105,
            ["GUID"] = "7FFDC8AA",
            ["NextDialogue"] = 51127106,
            ["SpeakNpcId"] = 701061,
            },
        [51127106] = {
            ["Content"] = "那么，你究竟在和谁说话？",
            ["ContentFR"] = "Alors... à qui parlais-tu vraiment ?",
            ["DialogueId"] = 51127106,
            ["GUID"] = "7FFDC8D4",
            ["NextDialogue"] = 51127107,
            ["SpeakNpcId"] = 100001,
            },
        [51127107] = {
            ["Content"] = "异国{性别：哥哥|姐姐}，你对你现在所处的地方有所不知哦，这里可是很恐怖的，那些在华胥死掉的有龙和抟土，都会变成无由生聚集在这里！",
            ["ContentFR"] = "{性别:Étranger venu|Étrangère venue} d’ailleurs, tu ne sais pas où tu te trouves. C’est un endroit très effrayant ! Tous ceux qui meurent à Huaxu — Descendants draconiques ou Enfants de la Terre — deviennent des Wishen et se rassemblent ici !",
            ["DialogueId"] = 51127107,
            ["GUID"] = "7FFDC8FE",
            ["NextDialogue"] = 51127108,
            ["SpeakNpcId"] = 701061,
            },
        [51127108] = {
            ["Content"] = "怎么样？害怕了吗？害怕的话就赶紧离开吧！",
            ["ContentFR"] = "Alors ? Tu as peur ? Si oui, pars vite !",
            ["DialogueId"] = 51127108,
            ["GUID"] = "7FFDC928",
            ["SpeakNpcId"] = 701061,
            },
        [51127109] = {
            ["Content"] = "如果爷爷回来看我的话，就让叶子落在我的头上吧！",
            ["ContentFR"] = "Grand-père ! Si tu es revenu me voir, fais tomber une feuille sur ma tête !",
            ["DialogueId"] = 51127109,
            ["GUID"] = "7FFDC952",
            ["NextDialogue"] = 51127110,
            ["SpeakNpcId"] = 701061,
            },
        [51127110] = {
            ["Content"] = "诶呀，你怎么还敢回来！",
            ["ContentFR"] = "Eh ? Pourquoi es-tu {性别:revenu|revenue} ? Tu n’as même pas un peu peur ?",
            ["DialogueId"] = 51127110,
            ["GUID"] = "7FFDC97C",
            ["NextOptions"] = {
                [1] = 51127111,
                [2] = 51127123,
                },
            ["SpeakNpcId"] = 701061,
            },
        [51127111] = {
            ["Content"] = "无由生又不会伤害我，为什么不敢呀？",
            ["ContentFR"] = "<I>Les Wishen ne me feront pas de mal. Pourquoi aurais-je peur ?</>",
            ["DialogueId"] = 51127111,
            ["GUID"] = "7FFDC9A6",
            ["NextDialogue"] = 51127112,
            },
        [51127112] = {
            ["Content"] = "其实我也是这么觉得的，只是之前我也遇到过一些过路的异国人，他们一听说这里是死去的人变成的无由生聚集的地方，就吓得哇呀哇呀跑掉啦。",
            ["ContentFR"] = "Moi aussi, je pense comme ça. Mais j’ai déjà croisé des étrangers de passage : dès qu’ils entendent que c’est ici que se rassemblent les Wishen, ils prennent peur, crient « <I>waaah ! waaah !</> » et s’enfuient en courant !",
            ["DialogueId"] = 51127112,
            ["GUID"] = "7FFDC9D0",
            ["NextDialogue"] = 51127113,
            ["SpeakNpcId"] = 701061,
            },
        [51127113] = {
            ["Content"] = "他们都不知道，无由生并不害人性命，他们只是在这，安安静静地，待在这……",
            ["ContentFR"] = "Ils ne savent pas que les Wishen ne font de mal à personne. Ils restent simplement là... tranquillement...",
            ["DialogueId"] = 51127113,
            ["GUID"] = "7FFDC9FA",
            ["NextOptions"] = {
                [1] = 51127114,
                },
            ["SpeakNpcId"] = 701061,
            },
        [51127114] = {
            ["Content"] = "所以你来这做什么？",
            ["ContentFR"] = "<I>Alors pourquoi viens-tu ici ?</>",
            ["DialogueId"] = 51127114,
            ["GUID"] = "7FFDCA24",
            ["NextDialogue"] = 51127115,
            },
        [51127115] = {
            ["Content"] = "我爷爷生了很重很重的病，叫衰老，前段时间白龙神君就把他接走了，他阖眼之前和我说，他以前曾经在幽明涧看到过死掉的人化身为无由生。",
            ["ContentFR"] = "Mon grand-père est tombé très malade. Une maladie appelée « vieillesse ». Il y a quelque temps, le Seigneur Dragon d’Argent l’a emmené. Avant de fermer les yeux, il m’a raconté qu’il avait vu ici, au Ravin du Clair-Obscur, des gens morts devenus des Wishen.",
            ["DialogueId"] = 51127115,
            ["GUID"] = "7FFDCA4E",
            ["NextDialogue"] = 51127116,
            ["SpeakNpcId"] = 701061,
            },
        [51127116] = {
            ["Content"] = "他就说，说不定他以后也会变成无由生，到时候，就可以随时随地陪在我身边了。",
            ["ContentFR"] = "Il disait que peut-être, un jour, il deviendrait lui aussi un Wishen, et qu’il pourrait rester près de moi.",
            ["DialogueId"] = 51127116,
            ["GUID"] = "7FFDCA78",
            ["NextDialogue"] = 51127117,
            ["SpeakNpcId"] = 701061,
            },
        [51127117] = {
            ["Content"] = "可我在家里等了好久，爷爷也没回来陪我，问了妈妈才知道，只有这里才有无由生，所以就过来了……",
            ["ContentFR"] = "Mais je l’ai attendu longtemps à la maison... Il n’est jamais revenu. Maman m’a dit que les Wishen n’étaient qu’ici... alors je suis venue.",
            ["DialogueId"] = 51127117,
            ["GUID"] = "7FFDCAA2",
            ["NextOptions"] = {
                [1] = 51127118,
                [2] = 51127120,
                },
            ["SpeakNpcId"] = 701061,
            },
        [51127118] = {
            ["Content"] = "那你见到了吗？",
            ["ContentFR"] = "<I>L’as-tu vu ?</>",
            ["DialogueId"] = 51127118,
            ["GUID"] = "7FFDCACC",
            ["NextDialogue"] = 51127119,
            },
        [51127119] = {
            ["Content"] = "没有，我听妈妈说，我们是看不到无由生的，所以我就让爷爷如果听的到我说话，就把树叶落在我的头上，可爷爷真是笨糊涂了，这都不清楚……",
            ["ContentFR"] = "Non... Maman dit que nous ne pouvons pas voir les Wishen. Alors j’ai demandé à grand-père, s’il m’entend, de faire tomber une feuille sur ma tête. Mais il est vraiment étourdi... il n’y arrive toujours pas...",
            ["DialogueId"] = 51127119,
            ["GUID"] = "7FFDCAF6",
            ["SpeakNpcId"] = 701061,
            },
        [51127120] = {
            ["Content"] = "可是这里阴森森的，你不害怕吗？",
            ["ContentFR"] = "<I>Mais cet endroit est sombre et inquiétant. Tu n’as pas peur ?</>",
            ["DialogueId"] = 51127120,
            ["GUID"] = "7FFDCB20",
            ["NextDialogue"] = 51127121,
            },
        [51127121] = {
            ["Content"] = "一开始也害怕啊，所以我就开始和爷爷说话，但是我后来就想着，即使这里有别的无由生，那也是某个死掉的人吧。",
            ["ContentFR"] = "Au début, oui. Alors je me suis mise à parler à grand-père. Puis j’ai pensé... même les autres Wishen étaient des personnes autrefois.",
            ["DialogueId"] = 51127121,
            ["GUID"] = "7FFDCB4A",
            ["NextDialogue"] = 51127122,
            ["SpeakNpcId"] = 701061,
            },
        [51127122] = {
            ["Content"] = "死掉的人会有家人，有家人就会有人想他们，就像我的爷爷一样，即使死掉也会一直被纪念……这么一想，我就不害怕了。",
            ["ContentFR"] = "Et les personnes ont des familles. Et quand on a une famille, quelqu’un pense toujours à vous. Comme moi et grand-père. Même s’il est parti, on se souvient de lui. Quand j’y pense comme ça... je n’ai plus peur.",
            ["DialogueId"] = 51127122,
            ["GUID"] = "7FFDCB74",
            ["SpeakNpcId"] = 701061,
            },
        [51127123] = {
            ["Content"] = "祝你能等到你的爷爷。",
            ["ContentFR"] = "<I>J’espère que tu retrouveras ton grand-père.</>",
            ["DialogueId"] = 51127123,
            ["GUID"] = "7FFDCB9E",
            ["NextDialogue"] = 51127124,
            },
        [51127124] = {
            ["Content"] = "我会的，爷爷，一定会回来陪我的。",
            ["ContentFR"] = "Oui ! Grand-père reviendra, c’est sûr. Il reviendra rester avec moi.",
            ["DialogueId"] = 51127124,
            ["GUID"] = "7FFDCBC8",
            ["SpeakNpcId"] = 701061,
            },
        [51127201] = {
            ["Content"] = "到底是什么时候就在这里的呢？",
            ["ContentFR"] = "Depuis quand ce grand arbre se dresse-t-il ici... ?",
            ["DialogueId"] = 51127201,
            ["GUID"] = "7FFDD86A",
            ["NextDialogue"] = 51127202,
            ["SpeakNpcId"] = 701062,
            },
        [51127202] = {
            ["Content"] = "问阿方，他说他来的时候树就在了，问阿洁，她说她在的时候树就在了。可是大家都死了数不清的年月了，树到底是什么时候长出来的呢？",
            ["ContentFR"] = "J’ai demandé à Fang : il m’a dit que l’arbre était déjà là quand il est arrivé. J’ai demandé à Jie : elle a dit pareil. Mais ils sont tous morts depuis des temps impossibles à mesurer... Alors quand est-ce que cet arbre a poussé ?",
            ["DialogueId"] = 51127202,
            ["GUID"] = "7FFDD894",
            ["NextDialogue"] = 51127203,
            ["SpeakNpcId"] = 701062,
            },
        [51127203] = {
            ["Content"] = "你好呀，你是来看大树的吗？",
            ["ContentFR"] = "Bonjour ! Tu es venu voir le grand arbre, toi aussi ?",
            ["DialogueId"] = 51127203,
            ["GUID"] = "7FFDD8BE",
            ["NextOptions"] = {
                [1] = 51127204,
                [2] = 51127215,
                [3] = 51127218,
                },
            ["SpeakNpcId"] = 701062,
            },
        [51127204] = {
            ["Content"] = "嗯……是？",
            ["ContentFR"] = "<I>Euh... oui, je crois ?</>",
            ["DialogueId"] = 51127204,
            ["GUID"] = "7FFDD8E8",
            ["NextDialogue"] = 51127205,
            },
        [51127205] = {
            ["Content"] = "果然，我都说了，大家都会对树感兴趣的，阿方阿洁还笑我呢，这不是，就来了个找上门的。",
            ["ContentFR"] = "Je le savais ! Je l’avais dit : tout le monde finit par s’intéresser à l’arbre. Fang et Jie se moquaient de moi... et voilà, quelqu’un est vraiment venu !",
            ["DialogueId"] = 51127205,
            ["GUID"] = "7FFDD912",
            ["NextDialogue"] = 51127220,
            ["SpeakNpcId"] = 701062,
            },
        [51127206] = {
            ["Content"] = "这棵树有什么特别的？",
            ["ContentFR"] = "<I>Qu’a-t-il de si spécial, cet arbre ?</>",
            ["DialogueId"] = 51127206,
            ["GUID"] = "7FFDD93C",
            ["NextDialogue"] = 51127207,
            },
        [51127207] = {
            ["Content"] = "你看不出来吗？这棵树从外形就和别的树不一样，它的颜色有点像……天之树？大家是这么叫的吗？虽然华胥的天之树是长在地底啦……",
            ["ContentFR"] = "Tu ne le vois pas ? Rien que sa forme est différente. Et sa couleur... on dirait presque l’Arbre Céleste ? C’est comme ça qu’on l’appelle, non ? Même si, à Huaxu, les Arbres Célestes poussent sous terre...",
            ["DialogueId"] = 51127207,
            ["GUID"] = "7FFDD966",
            ["NextDialogue"] = 51127208,
            ["SpeakNpcId"] = 701062,
            },
        [51127208] = {
            ["Content"] = "华胥有好多树，果树，香料树，普通的树，每颗树都有自己的作用，但这颗树什么也没有，不能开花，不能结果，唯一的作用是站在这里。",
            ["ContentFR"] = "À Huaxu, il y a toutes sortes d’arbres : des fruitiers, des arbres à encens, des arbres ordinaires. Chaque arbre a son utilité. Mais celui-ci... rien. Il ne fleurit pas, ne donne aucun fruit. Son seul rôle, c’est d’être là.",
            ["DialogueId"] = 51127208,
            ["GUID"] = "7FFDD990",
            ["NextDialogue"] = 51127220,
            ["SpeakNpcId"] = 701062,
            },
        [51127209] = {
            ["Content"] = "这颗树存在了多久？",
            ["ContentFR"] = "<I>Depuis combien de temps existe-t-il ?</>",
            ["DialogueId"] = 51127209,
            ["GUID"] = "7FFDD9BA",
            ["NextDialogue"] = 51127210,
            },
        [51127210] = {
            ["Content"] = "正是我想搞清楚的问题呢，我问了好多无由生，他们都说自己刚来的时候这树就已经这么大了，可最早的那位无由生已经是华胥开国之时的老家伙了呢。",
            ["ContentFR"] = "C’est justement ce que j’essaie de comprendre. J’ai interrogé beaucoup de Wishen : tous disent que, lorsqu’ils sont arrivés, l’arbre était déjà aussi grand. Or le plus ancien d’entre eux datait de la fondation même de Huaxu.",
            ["DialogueId"] = 51127210,
            ["GUID"] = "7FFDD9E4",
            ["NextDialogue"] = 51127211,
            ["SpeakNpcId"] = 701062,
            },
        [51127211] = {
            ["Content"] = "所以你说，这棵树会不会比华胥还要老呀？那这么老的树为什么没有死掉呢？我们无由生都会消散呢！",
            ["ContentFR"] = "Alors dis-moi... et si cet arbre était plus ancien que Huaxu ? Pourquoi une chose aussi vieille ne disparaît-elle pas, alors que nous, les Wishen, finissons par nous dissiper ?",
            ["DialogueId"] = 51127211,
            ["GUID"] = "7FFDDA0E",
            ["NextDialogue"] = 51127220,
            ["SpeakNpcId"] = 701062,
            },
        [51127212] = {
            ["Content"] = "这棵树长得挺好看。",
            ["ContentFR"] = "<I>Il est plutôt beau, cet arbre.</>",
            ["DialogueId"] = 51127212,
            ["GUID"] = "7FFDDA38",
            ["NextDialogue"] = 51127213,
            },
        [51127213] = {
            ["Content"] = "是啊是啊，我也这么觉得。我经常和阿洁说，如果我们还有躯体的话，一定要摘下树上的叶子给自己做顶树叶帽。",
            ["ContentFR"] = "Oui ! Moi aussi, je trouve. Je disais souvent à Jie que, si nous avions encore un corps, on cueillerait ses feuilles pour se faire des chapeaux.",
            ["DialogueId"] = 51127213,
            ["GUID"] = "7FFDDA62",
            ["NextDialogue"] = 51127214,
            ["SpeakNpcId"] = 701062,
            },
        [51127214] = {
            ["Content"] = "唔……不过据说啊，树上的叶子摘下来就会很快枯萎，不知道枯萎后的叶子还好不好看……你可别摘哟，路过的生者们说，摘树叶可是会倒霉的。",
            ["ContentFR"] = "Hmm... mais on raconte que, dès qu’on arrache une feuille, elle se fane très vite. Je me demande si elle serait encore jolie après... En tout cas, n’en cueille pas, d’accord ? Les vivants disent que ça porte malheur.",
            ["DialogueId"] = 51127214,
            ["GUID"] = "7FFDDA8C",
            ["NextDialogue"] = 51127220,
            ["SpeakNpcId"] = 701062,
            },
        [51127215] = {
            ["Content"] = "嗯……不是。",
            ["ContentFR"] = "<I>Euh... non.</>",
            ["DialogueId"] = 51127215,
            ["GUID"] = "7FFDDAB6",
            ["NextDialogue"] = 51127216,
            },
        [51127216] = {
            ["Content"] = "啊？你怎么也对树不感兴趣，你不觉得这棵树非常有趣吗？它和这里的其他树都不一样。",
            ["ContentFR"] = "Hein ? Toi non plus tu ne t’intéresses pas à l’arbre ? Tu ne le trouves pas fascinant ? Il n’est comme aucun autre ici !",
            ["DialogueId"] = 51127216,
            ["GUID"] = "7FFDDAE0",
            ["NextDialogue"] = 51127217,
            ["SpeakNpcId"] = 701062,
            },
        [51127217] = {
            ["Content"] = "不过既然你不感兴趣，那就算啦，我要继续思考关于这棵树的事情了，你找别的无由生聊天吧。",
            ["ContentFR"] = "Mais bon, si ça ne t’intéresse pas, tant pis. Moi, je vais continuer à réfléchir à cet arbre. Va discuter avec d’autres Wishen !",
            ["DialogueId"] = 51127217,
            ["GUID"] = "7FFDDB0A",
            ["SpeakNpcId"] = 701062,
            },
        [51127218] = {
            ["Content"] = "再见。",
            ["ContentFR"] = "Au revoir.",
            ["DialogueId"] = 51127218,
            ["GUID"] = "7FFDDB34",
            ["NextDialogue"] = 51127219,
            },
        [51127219] = {
            ["Content"] = "走啦，下次回来，我们再聊聊树的事情哦！",
            ["ContentFR"] = "À bientôt ! La prochaine fois, on reparlera de l’arbre, d’accord ?",
            ["DialogueId"] = 51127219,
            ["GUID"] = "7FFDDB5E",
            ["SpeakNpcId"] = 701062,
            },
        [51127220] = {
            ["DialogueId"] = 51127220,
            ["DialoguePanelType"] = "None",
            ["Duration"] = 0.1,
            ["FinalDialogueId"] = 51127219,
            ["GUID"] = "7FFDDB88",
            ["NextOptions"] = {
                [1] = 51127206,
                [2] = 51127209,
                [3] = 51127212,
                },
            },
        [51127301] = {
            ["Content"] = "我能听到，世间万物的呼吸，树叶，草木，泥土，水滴，一切的一切我都可以听到。",
            ["ContentFR"] = "Je peux entendre la respiration de toute chose : les feuilles, l’herbe, la terre, les gouttes d’eau... tout, absolument tout.",
            ["DialogueId"] = 51127301,
            ["GUID"] = "7FFDE8D2",
            ["NextDialogue"] = 51127302,
            ["SpeakNpcId"] = 701063,
            },
        [51127302] = {
            ["Content"] = "你听到了吗？这颗树一直在说话，它们全都听不到，只有我……只有我听到了……",
            ["ContentFR"] = "Tu l’entends ? Cet arbre parle tout le temps. Personne d’autre ne l’entend... Moi seul... moi seul l’entends...",
            ["DialogueId"] = 51127302,
            ["GUID"] = "7FFDE8FC",
            ["NextOptions"] = {
                [1] = 51127303,
                [2] = 51127305,
                },
            ["SpeakNpcId"] = 701063,
            },
        [51127303] = {
            ["Content"] = "树怎么会说话？",
            ["ContentFR"] = "<I>Comment un arbre pourrait-il parler ?</>",
            ["DialogueId"] = 51127303,
            ["GUID"] = "7FFDE926",
            ["ImprPlusId"] = 1208,
            ["NextDialogue"] = 51127304,
            },
        [51127304] = {
            ["Content"] = "树当然会说话！但你们这些捂住耳朵的家伙听不见，只有静下心来，仔细感知，你听！它又在说话，它在说……",
            ["ContentFR"] = "Bien sûr que les arbres parlent ! Mais vous, vous vous bouchez les oreilles. Calme-toi... ressens... écoute. Tu vois ? Il recommence... il dit...",
            ["DialogueId"] = 51127304,
            ["GUID"] = "7FFDE950",
            ["SpeakNpcId"] = 701063,
            },
        [51127305] = {
            ["Content"] = "树说了什么？",
            ["ContentFR"] = "<I>Que dit-il ?</>",
            ["DialogueId"] = 51127305,
            ["GUID"] = "7FFDE97A",
            ["ImprPlusId"] = 1209,
            ["NextDialogue"] = 51127306,
            },
        [51127306] = {
            ["Content"] = "嘘！它的声音模糊不清……我一直没办法听清楚，只要再给我一点时间，再给我……",
            ["ContentFR"] = "Chut... Sa voix est floue... Je n’arrive pas encore à la saisir. Il me faut juste un peu plus de temps... juste un peu...",
            ["DialogueId"] = 51127306,
            ["GUID"] = "7FFDE9A4",
            ["SpeakNpcId"] = 701063,
            },
        [51127307] = {
            ["Content"] = "这棵树，一直在说话！",
            ["ContentFR"] = "Cet arbre... il parle sans cesse !",
            ["DialogueId"] = 51127307,
            ["GUID"] = "7FFDE9CE",
            ["NextDialogue"] = 51127308,
            ["SpeakNpcId"] = 701063,
            },
        [51127308] = {
            ["Content"] = "我又听到了！这次比之前的每一次都清楚，你也是被树的树叶吸引而来的吗？快告诉我，你听到了吗？！",
            ["ContentFR"] = "Il parle encore ! Cette fois, plus clairement que jamais ! Toi aussi, ce sont ses feuilles qui t’ont attiré ici ? Dis-moi ! Tu l’as entendu, toi aussi ?!",
            ["DialogueId"] = 51127308,
            ["GUID"] = "7FFDE9F8",
            ["NextOptions"] = {
                [1] = 51127309,
                [2] = 51127311,
                [3] = 51127326,
                },
            ["SpeakNpcId"] = 701063,
            },
        [51127309] = {
            ["Content"] = "只有树叶的沙沙声。",
            ["ContentFR"] = "<I>Je n’entends que le bruissement des feuilles.</>",
            ["DialogueId"] = 51127309,
            ["GUID"] = "7FFDEA22",
            ["NextDialogue"] = 51127310,
            },
        [51127310] = {
            ["Content"] = "不！你仔细听，潜藏在树叶的声音之下，还有一种独特的，属于树的低语，它又开始说话了，它在呼唤我！",
            ["ContentFR"] = "Non ! Écoute mieux ! Sous le froissement, il y a une autre voix... Un murmure propre à l’arbre. Il m’appelle !",
            ["DialogueId"] = 51127310,
            ["GUID"] = "7FFDEA4C",
            ["SpeakNpcId"] = 701063,
            },
        [51127311] = {
            ["Content"] = "我听到了，是……",
            ["ContentFR"] = "<I>Je l’ai entendu. Il disait...</>",
            ["DialogueId"] = 51127311,
            ["GUID"] = "7FFDEA76",
            ["NextDialogue"] = 51127312,
            },
        [51127312] = {
            ["Content"] = "我果然没有看错你，你是和它们不一样的！树在说什么，快告诉我吧！",
            ["ContentFR"] = "Je le savais ! Tu n’es pas comme les autres ! Qu’a-t-il dit ? Dis-le-moi, vite !",
            ["DialogueId"] = 51127312,
            ["GUID"] = "7FFDEAA0",
            ["NextOptions"] = {
                [1] = 51127313,
                [2] = 51127315,
                [3] = 51127317,
                },
            ["SpeakNpcId"] = 701063,
            },
        [51127313] = {
            ["Content"] = "树在说：生长。",
            ["ContentFR"] = "<I>Il dit : « grandir ».</>",
            ["DialogueId"] = 51127313,
            ["GUID"] = "7FFDEACA",
            ["NextDialogue"] = 51127314,
            },
        [51127314] = {
            ["Content"] = "生长，是了，树木都是从微小的种子成长成现在模样。如同你从千里百里之外行走到这里，让一串脚印生长成一段旅程。",
            ["ContentFR"] = "Grandir... oui. Les arbres partent d’une graine minuscule pour devenir ce qu’ils sont. Comme toi : chaque pas, depuis des terres lointaines, fait naître un voyage.",
            ["DialogueId"] = 51127314,
            ["GUID"] = "7FFDEAF4",
            ["NextOptions"] = {
                [1] = 51127321,
                [2] = 51127324,
                },
            ["SpeakNpcId"] = 701063,
            },
        [51127315] = {
            ["Content"] = "树在说：开花。",
            ["ContentFR"] = "<I>Il dit : « fleurir ».</>",
            ["DialogueId"] = 51127315,
            ["GUID"] = "7FFDEB1E",
            ["NextDialogue"] = 51127316,
            },
        [51127316] = {
            ["Content"] = "开花，嗯……树木的生命很长但是花期却好短，可是唯独开花的时日最吸引人。人也是差不多哦，被看不见的时日牵引，突然地就开出了花来，连白龙神君都要赞叹。",
            ["ContentFR"] = "Fleurir... La vie d’un arbre est longue, mais sa floraison est brève — et c’est justement pour ça qu’elle attire tous les regards. Les humains sont pareils : guidés par des saisons invisibles, ils fleurissent soudain... même le Seigneur Dragon d’Argent s’en émerveillerait.",
            ["DialogueId"] = 51127316,
            ["GUID"] = "7FFDEB48",
            ["NextOptions"] = {
                [1] = 51127321,
                [2] = 51127324,
                },
            ["SpeakNpcId"] = 701063,
            },
        [51127317] = {
            ["Content"] = "树在说：腐朽。",
            ["ContentFR"] = "<I>Il dit : « se décomposer ».</>",
            ["DialogueId"] = 51127317,
            ["GUID"] = "7FFDEB72",
            ["NextDialogue"] = 51127318,
            },
        [51127318] = {
            ["Content"] = "腐朽，哈哈，原来树木也会伤感腐朽吗？明明和我们无由生一样，倒下后会引来新的生灵。不……不对，也许在它看来，腐朽并不伤感，反倒是我先入为主了……",
            ["ContentFR"] = "Se décomposer... Ah... les arbres aussi seraient-ils tristes de pourrir ? Ils tombent, et une nouvelle vie naît. Non... ce sont mes pensées, pas les siennes. Pour lui, la décomposition n’est pas une peine...",
            ["DialogueId"] = 51127318,
            ["GUID"] = "7FFDEB9C",
            ["NextDialogue"] = 51127319,
            ["SpeakNpcId"] = 701063,
            },
        [51127319] = {
            ["Content"] = "总之，我知道了，每个人听到的声音都是不一样的，这颗树能听到我们的心底真实的声音，它不断地叫我的名字……",
            ["ContentFR"] = "J’ai compris, maintenant. Chacun entend une voix différente. Cet arbre entend la vérité enfouie dans nos cœurs... Et il prononce mon nom...",
            ["DialogueId"] = 51127319,
            ["GUID"] = "7FFDEBC6",
            ["NextDialogue"] = 51127320,
            ["SpeakNpcId"] = 701063,
            },
        [51127320] = {
            ["Content"] = "但在名字之外，我又听到了它自己的声音，它在和我们说……",
            ["ContentFR"] = "Mais au-delà de nos voix, j’ai entendu la sienne. Il nous dit...",
            ["DialogueId"] = 51127320,
            ["GUID"] = "7FFDEBF0",
            ["NextOptions"] = {
                [1] = 51127321,
                [2] = 51127324,
                },
            ["SpeakNpcId"] = 701063,
            },
        [51127321] = {
            ["Content"] = "你听到的树说了什么？",
            ["ContentFR"] = "<I>Qu’est-ce qu’il dit ?</>",
            ["DialogueId"] = 51127321,
            ["GUID"] = "7FFDEC1A",
            ["NextDialogue"] = 51127322,
            },
        [51127322] = {
            ["Content"] = "树……树一直在重复一句话……",
            ["ContentFR"] = "Il répète toujours la même phrase...",
            ["DialogueId"] = 51127322,
            ["GUID"] = "7FFDEC44",
            ["NextDialogue"] = 51127323,
            ["SpeakNpcId"] = 701063,
            },
        [51127323] = {
            ["Content"] = "它说……枯朽的再度开放，死去的正在归来。",
            ["ContentFR"] = "« Ce qui s’est flétri refleurira. Ce qui est mort est en train de revenir. »",
            ["DialogueId"] = 51127323,
            ["GUID"] = "7FFDEC6E",
            ["SpeakNpcId"] = 701063,
            },
        [51127324] = {
            ["Content"] = "如果你活着，我会推荐你去看看医生。",
            ["ContentFR"] = "<I>Si tu étais vivant, je te conseillerais d’aller voir un médecin.</>",
            ["DialogueId"] = 51127324,
            ["GUID"] = "7FFDEC98",
            ["NextDialogue"] = 51127325,
            },
        [51127325] = {
            ["Content"] = "哼，你不会理解我，就像你们不理解树一样。但这并不算什么，树已经告诉我了，树把一切都告诉我了。",
            ["ContentFR"] = "<I>Hmpf. </>Tu ne comprendrais pas. Pas plus que vous ne comprenez les arbres. Mais peu importe... L’arbre m’a déjà tout dit.",
            ["DialogueId"] = 51127325,
            ["GUID"] = "7FFDECC2",
            ["SpeakNpcId"] = 701063,
            },
        [51127326] = {
            ["Content"] = "（离这疯子远点吧……）",
            ["ContentFR"] = "<I>Mieux vaut s’éloigner de ce fou...</>",
            ["DialogueId"] = 51127326,
            ["GUID"] = "7FFDECEC",
            ["NextDialogue"] = 51127327,
            },
        [51127327] = {
            ["Content"] = "你会回来的，在树说过的那一天。",
            ["ContentFR"] = "Tu reviendras. Le jour que l’arbre a annoncé.",
            ["DialogueId"] = 51127327,
            ["GUID"] = "7FFDED16",
            ["SpeakNpcId"] = 701063,
            },
        [51127401] = {
            ["Content"] = "你知道这是哪儿吗？我清醒的时候就在这儿了，供桌上那泥像，脸裂得跟我老家墙似的。",
            ["ContentFR"] = "Tu sais où on est ? À chaque fois que je reprends conscience, je me retrouve ici. La statue d’argile sur l’autel... son visage est fissuré comme le mur de ma maison.",
            ["DialogueId"] = 51127401,
            ["GUID"] = "7FFDF93A",
            ["NextDialogue"] = 51127402,
            ["SpeakNpcId"] = 701064,
            },
        [51127402] = {
            ["Content"] = "老家？我也想不起来了。只记得好像总闻得到香火气，不是这种霉味的香，是甜丝丝的，裹着糖霜的那种。你老家有糖吃吗？",
            ["ContentFR"] = "Ta maison ? Je n’arrive pas à m’en souvenir non plus. Je me rappelle seulement l’odeur de l’encens... Pas cette odeur de moisi. Quelque chose de sucré... comme du sucre glacé. Chez toi, il y avait des douceurs ?",
            ["DialogueId"] = 51127402,
            ["GUID"] = "7FFDF964",
            ["NextDialogue"] = 51127403,
            ["SpeakNpcId"] = 701065,
            },
        [51127403] = {
            ["Content"] = "糖没印象，倒有河！宽得很，船划半天都到不了头，夏天总有人在河边撒网，网起来的鱼带着光，一蹦能溅我满身水。你见过会发光的鱼不？",
            ["ContentFR"] = "Je ne me souviens pas du sucre. Mais il y avait une rivière. Si large qu’on ne voyait jamais l’autre rive. L’été, les gens lançaient leurs filets, et les poissons remontaient en brillant. Tu as déjà vu des poissons lumineux ?",
            ["DialogueId"] = 51127403,
            ["GUID"] = "7FFDF98E",
            ["NextDialogue"] = 51127404,
            ["SpeakNpcId"] = 701064,
            },
        [51127404] = {
            ["Content"] = "没见过，但我见过会转的轮子！木头做的，比这大树还高，转起来呜呜响，能把水送到田里头。",
            ["ContentFR"] = "Non. Mais j’ai vu une roue qui tournait. En bois, plus haute que ce grand arbre. Elle faisait un bruit sourd en tournant, et amenait l’eau jusqu’aux champs.",
            ["DialogueId"] = 51127404,
            ["GUID"] = "7FFDF9B8",
            ["NextDialogue"] = 51127405,
            ["SpeakNpcId"] = 701065,
            },
        [51127405] = {
            ["Content"] = "有回轮子卡住了，好多人围着敲敲打打，我也跟着凑了热闹，结果被溅了一脸泥 —— 哎，你脸上有泥不？",
            ["ContentFR"] = "Un jour, elle s’est bloquée. Tout le monde s’est rassemblé pour taper dessus. Je me suis approché aussi... et j’ai fini couvert de boue. Hé... tu as de la boue sur le visage, toi ?",
            ["DialogueId"] = 51127405,
            ["GUID"] = "7FFDF9E2",
            ["NextDialogue"] = 51127406,
            ["SpeakNpcId"] = 701065,
            },
        [51127406] = {
            ["Content"] = "无由生的脸上怎么会有泥，倒有点风。你说咱们为什么会来这里？我之前出去走过好几回，最后总是又回来了。",
            ["ContentFR"] = "Comment un Wishen aurait-il de la boue sur le visage ? Il n’y a que le vent. Dis-moi... pourquoi sommes-nous ici ? Je suis parti plusieurs fois, et à chaque fois je reviens.",
            ["DialogueId"] = 51127406,
            ["GUID"] = "7FFDFA0C",
            ["NextDialogue"] = 51127407,
            ["SpeakNpcId"] = 701064,
            },
        [51127407] = {
            ["Content"] = "昨天我往东边走，看见一片麦子地，黄灿灿的，想蹲下来摸一把，刚伸手就又回来了。",
            ["ContentFR"] = "Hier, je suis allé vers l’est. J’ai vu un champ de blé, tout doré. Je me suis accroupi pour en toucher une poignée... et aussitôt, j’étais de retour ici.",
            ["DialogueId"] = 51127407,
            ["GUID"] = "7FFDFA36",
            ["NextDialogue"] = 51127408,
            ["SpeakNpcId"] = 701065,
            },
        [51127408] = {
            ["Content"] = "我想回老家……你说，我们的老家到底在哪儿啊？",
            ["ContentFR"] = "Je veux rentrer chez moi... Dis-moi... où est notre maison, au juste ?",
            ["DialogueId"] = 51127408,
            ["GUID"] = "7FFDFA60",
            ["NextDialogue"] = 51127409,
            ["SpeakNpcId"] = 701064,
            },
        [51127409] = {
            ["Content"] = "不知道。但不管在哪，肯定不是这。",
            ["ContentFR"] = "Je ne sais pas. Mais quoi qu’il en soit... ce n’est certainement pas ici.",
            ["DialogueId"] = 51127409,
            ["GUID"] = "7FFDFA8A",
            ["NextDialogue"] = 51127410,
            ["SpeakNpcId"] = 701065,
            },
        [51127410] = {
            ["Content"] = "对，肯定不是这儿！",
            ["ContentFR"] = "Oui. Ce n’est sûrement pas ici.",
            ["DialogueId"] = 51127410,
            ["GUID"] = "7FFDFAB4",
            ["SpeakNpcId"] = 701064,
            },
        [51127501] = {
            ["Content"] = "哟，小鬼，东张西望什么呢？叫的就是你，看起来不像是老练的买家，明显也和咱们也不是一条船的，说说，你……是来做什么的？",
            ["ContentFR"] = "Oh ! {性别:Petit|Petite}, qu’est-ce que tu regardes comme ça ? Oui, toi. T’as pas l’air d’{性别:un acheteur aguerri|une acheteuse aguerrie}... et t’es clairement pas du même bord que nous. Alors dis-moi... qu’est-ce que tu viens faire ici ?",
            ["DialogueId"] = 51127501,
            ["GUID"] = "7FFE09A2",
            ["NextOptions"] = {
                [1] = 51127502,
                [2] = 51127505,
                },
            ["SpeakNpcId"] = 701066,
            },
        [51127502] = {
            ["Content"] = "我有必要告诉你吗？",
            ["ContentFR"] = "<I>Ai-je vraiment besoin de te le dire ?</>",
            ["DialogueId"] = 51127502,
            ["GUID"] = "7FFE09CC",
            ["ImprPlusId"] = 1203,
            ["NextDialogue"] = 51127503,
            },
        [51127503] = {
            ["Content"] = "哟，脾气还挺硬，这里，可不是你这种乳臭未干的小娃娃可以来的地方，只有我这种……嗝……叱吒风云，名震八方的，大名人！才能来，懂吗？",
            ["ContentFR"] = "Oh ho, du répondant ! Mais écoute bien : ici, c’est pas un terrain de jeu pour {性别:un morveux|une morveuse} qui sent encore le lait. Seuls des types comme moi... hic... des figures légendaires, qui font trembler les rues et les rumeurs... comme moi, Chizhatian, ont leur place ici. Compris ?",
            ["DialogueId"] = 51127503,
            ["GUID"] = "7FFE09F6",
            ["NextDialogue"] = 51127504,
            ["SpeakNpcId"] = 701066,
            },
        [51127504] = {
            ["Content"] = "不如快快来求你叱咤天爷爷相护，保佑你这种嫩娃娃，不被蛟人……嗝……吃掉。",
            ["ContentFR"] = "Alors fais donc vite appel à ton grand-père Chizhatian pour te protéger, histoire que toi, petit tendre... <I>hic... </>tu ne finisses pas dévoré par les Jiao.",
            ["DialogueId"] = 51127504,
            ["GUID"] = "7FFE0A20",
            ["NextDialogue"] = 51127508,
            ["SpeakNpcId"] = 701066,
            },
        [51127505] = {
            ["Content"] = "关你什么事？",
            ["ContentFR"] = "<I>En quoi ça te regarde ?</>",
            ["DialogueId"] = 51127505,
            ["GUID"] = "7FFE0A4A",
            ["ImprPlusId"] = 1205,
            ["NextDialogue"] = 51127506,
            },
        [51127506] = {
            ["Content"] = "嘿！我可是好心提醒你，你对咱们这有所不知，百年之前，这里可是有一种名为蛟人的怪物出没，它们以人为食，最爱吃的就是——你这种嫩娃娃！",
            ["ContentFR"] = "Hé ! J’essaie d’être sympa, moi. Tu n’y connais rien : il y a cent ans, des monstres appelés Jiao rôdaient ici. Des créatures mangeuses d’hommes. Et tu sais ce qu’elles préféraient ? Les gamins frais comme toi !",
            ["DialogueId"] = 51127506,
            ["GUID"] = "7FFE0A74",
            ["NextDialogue"] = 51127507,
            ["SpeakNpcId"] = 701066,
            },
        [51127507] = {
            ["Content"] = "不过，好歹你遇上了我叱咤天，这样……你给我……嗝，买瓶好酒，我就在微茫市，护你平安，如何？",
            ["ContentFR"] = "Mais bon, t’as de la chance d’être tombé sur moi. Alors voilà le marché : tu m’achètes... <I>hic...</> une bonne bouteille, et moi, je te garantis la vie sauve dans le Marché Voilé. Qu’est-ce que t’en dis ?",
            ["DialogueId"] = 51127507,
            ["GUID"] = "7FFE0A9E",
            ["NextDialogue"] = 51127508,
            ["SpeakNpcId"] = 701066,
            },
        [51127508] = {
            ["Content"] = "你这酒鬼，喝多了吧？",
            ["ContentFR"] = "<I>T’es ivre, vieux poivrot.</>",
            ["DialogueId"] = 51127508,
            ["GUID"] = "7FFE0AC8",
            ["NextDialogue"] = 51127509,
            ["SpeakNpcId"] = 100001,
            },
        [51127509] = {
            ["Content"] = "我喝多？我才没喝多，你才喝多了呢，你快回来，我和你讲……嗝！嗝！嗝！我和你讲蛟人……嗝！",
            ["ContentFR"] = "Ivre ? Moi ? Pas du tout ! C’est toi qui l’es ! Reviens là, je vais t’expli— <I>hic ! hic !</> — je vais t’expliquer les Jiao... <I>hic !</>",
            ["DialogueId"] = 51127509,
            ["GUID"] = "7FFE0AF2",
            ["SpeakNpcId"] = 701066,
            },
        [51127510] = {
            ["Content"] = "小鬼，微茫市可不是你随便乱逛的地方。",
            ["ContentFR"] = "Hé, {性别:gamin|gamine}. Le Marché Voilé, c’est pas un endroit où on se promène au hasard.",
            ["DialogueId"] = 51127510,
            ["GUID"] = "7FFE0B1C",
            ["NextDialogue"] = 51127511,
            ["SpeakNpcId"] = 701066,
            },
        [51127511] = {
            ["Content"] = "又是你啊，啧……微茫市能三番两头看到你这种白嫩嫩的面孔可有些不常见，又来啦？不怕被蛟人吃掉？",
            ["ContentFR"] = "Encore toi... <I>Tss.</> Voir deux fois de suite une petite tête toute blanche comme la tienne ici, c’est rare. T’es {性别:revenu|revenue} ? T’as pas peur de te faire croquer par les Jiao ?",
            ["DialogueId"] = 51127511,
            ["GUID"] = "7FFE0B46",
            ["NextDialogue"] = 51127512,
            ["SpeakNpcId"] = 701066,
            },
        [51127512] = {
            ["Content"] = "（这次看起来倒是比上次清醒一些……）",
            ["ContentFR"] = "<I>Cette fois, il a l’air un peu plus sobre...</>",
            ["DialogueId"] = 51127512,
            ["GUID"] = "7FFE0B70",
            ["NextOptions"] = {
                [1] = 51127513,
                [2] = 51127530,
                },
            ["SpeakNpcId"] = 101001,
            },
        [51127513] = {
            ["Content"] = "蛟人到底是什么东西……",
            ["ContentFR"] = "<I>Alors... c’est quoi exactement, ces Jiao ?</>",
            ["DialogueId"] = 51127513,
            ["GUID"] = "7FFE0B9A",
            ["NextDialogue"] = 51127514,
            },
        [51127514] = {
            ["Content"] = "你想知道啊，止流大当家请来的贵客，怎么也没跟你聊点咱们微茫市的小话本呢？",
            ["ContentFR"] = "Tu veux vraiment savoir ? Et dire que t’es l’{性别:invité|invitée} de marque de la Patronne Zhiliu... personne t’a raconté les petites histoires du Marché Voilé ?",
            ["DialogueId"] = 51127514,
            ["GUID"] = "7FFE0BC4",
            ["NextDialogue"] = 51127515,
            ["SpeakNpcId"] = 701066,
            },
        [51127515] = {
            ["Content"] = "你知道我的身份？那你还故意激我。",
            ["ContentFR"] = "<I>Tu connaissais mon identité ? Et tu m’as provoqué exprès ?</>",
            ["DialogueId"] = 51127515,
            ["GUID"] = "7FFE0BEE",
            ["NextDialogue"] = 51127516,
            ["SpeakNpcId"] = 100001,
            },
        [51127516] = {
            ["Content"] = "有趣啊！就像我说的，微茫市来来去去的人里，能看到你这样面孔的机会可不多，小鬼，想不想知道我说的蛟人故事是什么，给我买壶酒我就告诉你。",
            ["ContentFR"] = "Évidemment ! C’est ça qui est drôle. Comme je te l’ai dit, des visages comme le tien, on n’en voit pas souvent par ici. Alors... ça te dit d’entendre mon histoire sur les Jiao ? Offre-moi une jarre d’alcool, et je te raconte tout.",
            ["DialogueId"] = 51127516,
            ["GUID"] = "7FFE0C18",
            ["NextOptions"] = {
                [1] = 51127517,
                [2] = 51127528,
                },
            ["SpeakNpcId"] = 701066,
            },
        [51127517] = {
            ["Content"] = "你说吧，好听再给你买。",
            ["ContentFR"] = "<I>Parle d’abord. Si c’est bon, j’achèterai.</>",
            ["DialogueId"] = 51127517,
            ["GUID"] = "7FFE0C42",
            ["NextDialogue"] = 51127518,
            },
        [51127518] = {
            ["Content"] = "嘿嘿，我就知道你感兴趣，你可知，传闻中在华胥，有龙氏如果被神话中的黑蛟蛊惑，就会变成可怖的怪物，我们将其称之为——蛟人。",
            ["ContentFR"] = "Héhé, je savais que ça t’intriguerait. On raconte qu’à Huaxu, lorsqu’un Descendant draconique est corrompu par le mythique Dragon Noir, il devient une abomination. On les appelle... les Jiao.",
            ["DialogueId"] = 51127518,
            ["GUID"] = "7FFE0C6C",
            ["NextDialogue"] = 51127519,
            ["SpeakNpcId"] = 701066,
            },
        [51127519] = {
            ["Content"] = "蛟人们没有声音，害怕光线，常年生活在阴暗潮湿的洞穴之中，以人为食，为引诱无知的猎物上钩，他们常使用伪装的声调在洞穴深处歌唱。",
            ["ContentFR"] = "Ils n’ont pas de voix, craignent la lumière, et vivent dans des cavernes humides et sombres. Ils se nourrissent d’êtres humains. Pour attirer leurs proies, ils imitent des voix et chantent depuis les profondeurs.",
            ["DialogueId"] = 51127519,
            ["GUID"] = "7FFE0C96",
            ["NextDialogue"] = 51127520,
            ["SpeakNpcId"] = 701066,
            },
        [51127520] = {
            ["Content"] = "那路过之人，因为好奇美妙的歌声而深入查看，最终却葬身蛟人腹中。你猜，大家都说蛟人最经常聚集的地方，是哪？",
            ["ContentFR"] = "Les voyageurs, séduits par ce chant envoûtant, s’approchent... et finissent dans leur ventre. À ton avis, où dit-on qu’ils se rassemblent le plus souvent ?",
            ["DialogueId"] = 51127520,
            ["GUID"] = "7FFE0CC0",
            ["NextDialogue"] = 51127521,
            ["SpeakNpcId"] = 701066,
            },
        [51127521] = {
            ["Content"] = "难道是……微茫市外面的？",
            ["ContentFR"] = "À l’extérieur du Marché Voilé... ?",
            ["DialogueId"] = 51127521,
            ["GUID"] = "7FFE0CEA",
            ["NextDialogue"] = 51127522,
            ["SpeakNpcId"] = 100001,
            },
        [51127522] = {
            ["Content"] = "哈哈，小鬼，你有几分聪明，答对了！就是潮声岩穴！",
            ["ContentFR"] = "Ha ha ! {性别:Malin, le gamin|Maline, la gamine} ! Exact ! Chant-des-Marées !",
            ["DialogueId"] = 51127522,
            ["GUID"] = "7FFE0D14",
            ["NextDialogue"] = 51127523,
            ["SpeakNpcId"] = 701066,
            },
        [51127523] = {
            ["Content"] = "现在还有蛟人吗？",
            ["ContentFR"] = "Il en existe encore aujourd’hui ?",
            ["DialogueId"] = 51127523,
            ["GUID"] = "7FFE0D3E",
            ["NextDialogue"] = 51127524,
            ["SpeakNpcId"] = 100001,
            },
        [51127524] = {
            ["Content"] = "现在不需要有了。",
            ["ContentFR"] = "Plus besoin.",
            ["DialogueId"] = 51127524,
            ["GUID"] = "7FFE0D68",
            ["NextDialogue"] = 51127525,
            ["SpeakNpcId"] = 701066,
            },
        [51127525] = {
            ["Content"] = "不需要有是什么意思？",
            ["ContentFR"] = "Plus besoin... comment ça ?",
            ["DialogueId"] = 51127525,
            ["GUID"] = "7FFE0D92",
            ["NextDialogue"] = 51127526,
            ["SpeakNpcId"] = 100001,
            },
        [51127526] = {
            ["Content"] = "不需要有，就是不需要有的意思咯，直接告诉你多没意思，小鬼，你不是挺聪明的吗，你来猜猜好了。",
            ["ContentFR"] = "Plus besoin, c’est plus besoin. Te le dire franchement serait trop facile. T’es {性别:malin|maline}, non ? Devine.",
            ["DialogueId"] = 51127526,
            ["GUID"] = "7FFE0DBC",
            ["NextDialogue"] = 51127527,
            ["SpeakNpcId"] = 701066,
            },
        [51127527] = {
            ["Content"] = "为什么这么多年来，蛟人只闻传说不见实物，又为什么在虬先生来了之后，潮声岩穴就没有蛟人了。",
            ["ContentFR"] = "Pourquoi, à ton avis, on ne parle des Jiao qu’en légendes depuis des années ? Et pourquoi, depuis l’arrivée de Maître Qiu, Chant-des-Marées est devenue silencieuse ?",
            ["DialogueId"] = 51127527,
            ["GUID"] = "7FFE0DE6",
            ["SpeakNpcId"] = 701066,
            },
        [51127528] = {
            ["Content"] = "没兴趣听。",
            ["ContentFR"] = "<I>Pas intéressé.</>",
            ["DialogueId"] = 51127528,
            ["GUID"] = "7FFE0E10",
            ["NextDialogue"] = 51127529,
            },
        [51127529] = {
            ["Content"] = "啧……小鬼好没意思，我还以为你会比那些满脑子铜板金银的人更有趣些。算了，今日的好酒只能去找个水客给我送咯。",
            ["ContentFR"] = "<I>Tss...</> quel ennui. Je te croyais plus amusant que ces marchands obsédés par l’or. Tant pis. Je trouverai bien un batelier pour m’apporter du breuvage.",
            ["DialogueId"] = 51127529,
            ["GUID"] = "7FFE0E3A",
            ["SpeakNpcId"] = 701066,
            },
        [51127530] = {
            ["Content"] = "你烦不烦？",
            ["ContentFR"] = "<I>Tu parles trop.</>",
            ["DialogueId"] = 51127530,
            ["GUID"] = "7FFE0E64",
            ["NextDialogue"] = 51127531,
            },
        [51127531] = {
            ["Content"] = "哟呵，你这脾气真够炸的，敢这么跟我说话！上一个这么说话的，早就被我……被我丢去喂给蛟人了。",
            ["ContentFR"] = "Oh ? Sacré caractère ! Le dernier qui m’a parlé comme ça, je l’ai... je l’ai jeté aux Jiao.",
            ["DialogueId"] = 51127531,
            ["GUID"] = "7FFE0E8E",
            ["NextDialogue"] = 51127532,
            ["SpeakNpcId"] = 701066,
            },
        [51127532] = {
            ["Content"] = "不过我倒是知道你的身份，虬先生的贵人，止流大当家请来的客，所以啊，我饶你一命。",
            ["ContentFR"] = "Mais bon. Je sais qui tu es. L’{性别:invité|invitée} de Maître Qiu. {性别:Le|La} convive de la Patronne Zhiliu. Alors je t’épargne.",
            ["DialogueId"] = 51127532,
            ["GUID"] = "7FFE0EB8",
            ["NextOptions"] = {
                [1] = 51127513,
                },
            ["SpeakNpcId"] = 701066,
            },
        [51127533] = {
            ["Content"] = "你大可以动手试试。",
            ["ContentFR"] = "Essaie donc.",
            ["DialogueId"] = 51127533,
            ["GUID"] = "7FFE0EE2",
            ["NextDialogue"] = 51127534,
            },
        [51127534] = {
            ["Content"] = "哦哟，那可不敢哦，怕是你身上掉了一根头发，有些人皮都要给我掀掉两层。早些走吧，在这待太久，不说是我，总会有些眼睛没长齐的家伙盯上你。",
            ["ContentFR"] = "Oh non, surtout pas. Si un seul de tes cheveux tombait, certains me dépèceraient vivant. File, {性别:gamin|gamine}. Traîner ici trop longtemps, c’est attirer les regards de ceux qui ne savent pas à qui ils ont affaire.",
            ["DialogueId"] = 51127534,
            ["GUID"] = "7FFE0F0C",
            ["SpeakNpcId"] = 701066,
            },
        [51127601] = {
            ["Content"] = "得找点旧棉絮，混着桐油塞进去，再去定两块颜色相近的薄木板，结结实实地钉在两边，才能保证后续能不漏水呢。",
            ["ContentFR"] = "Faut trouver du vieux coton, le mélanger à de l’huile de tung, bien bourrer la fente... puis commander deux planches fines de la même teinte, les clouer solidement des deux côtés. Comme ça, plus aucune fuite.",
            ["DialogueId"] = 51127601,
            ["GUID"] = "7FFE1A0A",
            ["NextDialogue"] = 51127602,
            ["SpeakNpcId"] = 701067,
            },
        [51127602] = {
            ["Content"] = "孩儿呀，帮我个忙呗，把那头箱子里我带的铆钉递给我，你看看这原先的钉子，松松垮垮，这时日一长，如何不摇摆呢？",
            ["ContentFR"] = "Hé, {性别:petit|petite}, rends-moi service. Passe-moi les rivets dans cette caisse là-bas. Regarde ces vieux clous : tout branlants. Avec le temps, comment veux-tu que ça tienne ?",
            ["DialogueId"] = 51127602,
            ["GUID"] = "7FFE1A34",
            ["NextDialogue"] = 51127603,
            ["SpeakNpcId"] = 701067,
            },
        [51127603] = {
            ["Content"] = "（你顺着他指的方向，将盒子里的铆钉找出来递给他。）",
            ["ContentFR"] = "Vous suivez son geste, fouillez dans la boîte et lui tendez les rivets.",
            ["DialogueId"] = 51127603,
            ["GUID"] = "7FFE1A5E",
            ["NextDialogue"] = 51127604,
            },
        [51127604] = {
            ["Content"] = "谢谢了娃儿，我给……嘿！敲上去！齐活叻！",
            ["ContentFR"] = "Merci, {性别:gamin|gamine}. Et voilà... <I>toc !...</> terminé !",
            ["DialogueId"] = 51127604,
            ["GUID"] = "7FFE1A88",
            ["NextOptions"] = {
                [1] = 51127605,
                },
            ["SpeakNpcId"] = 701067,
            },
        [51127605] = {
            ["Content"] = "这是在修船？",
            ["ContentFR"] = "<I>Tu répares un bateau ?</>",
            ["DialogueId"] = 51127605,
            ["GUID"] = "7FFE1AB2",
            ["NextDialogue"] = 51127606,
            },
        [51127606] = {
            ["Content"] = "是啊，虬先生专门请我来，休整休整这艘老破船，这家伙，兜里的钱恐怕再造三百来个这样的船都合理，却堪堪死守着这条。",
            ["ContentFR"] = "Ouais. Maître Qiu m’a engagé pour remettre en état cette vieille carcasse. L’argent qu’il a sur lui suffirait à en construire trois cents comme ça... et pourtant, il s’obstine à garder celle-ci.",
            ["DialogueId"] = 51127606,
            ["GUID"] = "7FFE1ADC",
            ["NextDialogue"] = 51127607,
            ["SpeakNpcId"] = 701067,
            },
        [51127607] = {
            ["Content"] = "娃儿，我得把这块烂木头先锯下来，你且先让让，不然噪声大，吵着耳朵聋。",
            ["ContentFR"] = "Bon, je vais devoir scier cette partie pourrie. Recule un peu, ça fait du bruit. Je voudrais pas t’abîmer les oreilles.",
            ["DialogueId"] = 51127607,
            ["GUID"] = "7FFE1B06",
            ["SpeakNpcId"] = 701067,
            },
        [51127608] = {
            ["Content"] = "这缝儿得趁早补，再泡些日子，木芯都得烂透咯。",
            ["ContentFR"] = "Cette fissure, faut la colmater vite. Si le bois trempe encore quelques mois, le cœur va pourrir complètement.",
            ["DialogueId"] = 51127608,
            ["GUID"] = "7FFE1B30",
            ["NextDialogue"] = 51127609,
            ["SpeakNpcId"] = 701067,
            },
        [51127609] = {
            ["Content"] = "这船，老归老了，但这木料用的可都是好木料，平日里如果好好保养，再用个好些年应该也没问题。",
            ["ContentFR"] = "Ce bateau est vieux, oui. Mais le bois est excellent. Avec un bon entretien, il peut encore tenir des décennies.",
            ["DialogueId"] = 51127609,
            ["GUID"] = "7FFE1B5A",
            ["NextDialogue"] = 51127610,
            ["SpeakNpcId"] = 701067,
            },
        [51127610] = {
            ["Content"] = "娃儿，你又来啦，来找我聊天还是侃大山？",
            ["ContentFR"] = "Te revoilà, {性别:gamin|gamine}. Tu viens bavarder ou poser des questions ?",
            ["DialogueId"] = 51127610,
            ["GUID"] = "7FFE1B84",
            ["NextDialogue"] = 51127633,
            ["SpeakNpcId"] = 701067,
            },
        [51127611] = {
            ["Content"] = "这艘船有什么特别之处？",
            ["ContentFR"] = "<I>Qu’a-t-il de spécial, ce bateau ?</>",
            ["DialogueId"] = 51127611,
            ["GUID"] = "7FFE1BAE",
            ["NextDialogue"] = 51127612,
            },
        [51127612] = {
            ["Content"] = "老！就是它的特别之处。虬先生收藏的古董里，它可能不是最老的那个，但是总该是最大的那一个。",
            ["ContentFR"] = "Son âge. C’est ça, sa valeur. Parmi les antiquités de Maître Qiu, ce n’est peut-être pas la plus ancienne... mais c’est sûrement la plus grande.",
            ["DialogueId"] = 51127612,
            ["GUID"] = "7FFE1BD8",
            ["NextDialogue"] = 51127613,
            ["SpeakNpcId"] = 701067,
            },
        [51127613] = {
            ["Content"] = "据说微茫市还没建立的时候，这船就不知道从哪飘来了，一直在岸边搁浅，后面这里逐渐有了人气，才给这船又捡起来利用利用。",
            ["ContentFR"] = "On raconte qu’il était déjà là avant même la fondation du Marché Voilé. Il aurait dérivé jusqu’ici, échoué sur la rive. Puis, avec le temps, les gens se sont installés, et on l’a réutilisé.",
            ["DialogueId"] = 51127613,
            ["GUID"] = "7FFE1C02",
            ["NextDialogue"] = 51127614,
            ["SpeakNpcId"] = 701067,
            },
        [51127614] = {
            ["Content"] = "不过这船之前似乎是织星客们的，因为那些家伙喜欢在船身顶部装上个巨大的千星板，但这条船上的板不知道被什么人拆了。",
            ["ContentFR"] = "Il semble avoir appartenu aux Tisse-Étoiles. Ils avaient l’habitude d’installer un immense Panneau aux Mille Étoiles sur le pont. Celui-ci a été retiré, par quelqu’un.",
            ["DialogueId"] = 51127614,
            ["GUID"] = "7FFE1C2C",
            ["NextDialogue"] = 51127615,
            ["SpeakNpcId"] = 701067,
            },
        [51127615] = {
            ["Content"] = "也许是织星客们回收了去？我也跟虬先生问过，但他却没告诉我太多。",
            ["ContentFR"] = "Peut-être récupéré par les Tisse-Étoiles. J’ai posé la question à Maître Qiu... il n’a pas voulu en dire plus.",
            ["DialogueId"] = 51127615,
            ["GUID"] = "7FFE1C56",
            ["NextDialogue"] = 51127633,
            ["SpeakNpcId"] = 701067,
            },
        [51127616] = {
            ["Content"] = "你是机枢派的木匠吗？",
            ["ContentFR"] = "<I>Tu es un artisan de la Secte Jishu ?</>",
            ["DialogueId"] = 51127616,
            ["GUID"] = "7FFE1C80",
            ["NextDialogue"] = 51127617,
            },
        [51127617] = {
            ["Content"] = "娃儿这都看得出来啊，我以前是在机枢派学过些时日，但我对那会动的木头娃娃确实不感兴趣，我就喜欢琢磨钻研那不会动的东西。",
            ["ContentFR"] = "Bien vu. J’y ai appris un temps. Mais les poupées mécaniques qui bougent toutes seules, très peu pour moi. J’aime travailler ce qui reste immobile.",
            ["DialogueId"] = 51127617,
            ["GUID"] = "7FFE1CAA",
            ["NextDialogue"] = 51127618,
            ["SpeakNpcId"] = 701067,
            },
        [51127618] = {
            ["Content"] = "咱们华胥建筑的那些讲究可多呢，什么飞檐斗拱，什么雕栏玉砌，要是能把它们全琢磨明白，我这把老骨头，也是死而无憾了。",
            ["ContentFR"] = "L’architecture de Huaxu est pleine de subtilités : avant-toits en vol, consoles imbriquées, balustrades sculptées... Si je pouvais tout maîtriser avant de mourir, je partirais l’esprit en paix.",
            ["DialogueId"] = 51127618,
            ["GUID"] = "7FFE1CD4",
            ["NextDialogue"] = 51127619,
            ["SpeakNpcId"] = 701067,
            },
        [51127619] = {
            ["Content"] = "不过琢磨归琢磨，人还是得吃饭的嘛，虬先生每次请我过来都开价不菲，我啊，一年到头就等着他这大单吃呢。",
            ["ContentFR"] = "Mais bon, faut manger. Et Maître Qiu paie bien. Une commande de lui, et je tiens l’année.",
            ["DialogueId"] = 51127619,
            ["GUID"] = "7FFE1CFE",
            ["NextDialogue"] = 51127633,
            ["SpeakNpcId"] = 701067,
            },
        [51127620] = {
            ["Content"] = "这船大概多大岁数了？",
            ["ContentFR"] = "<I>Quel âge a ce bateau ?</>",
            ["DialogueId"] = 51127620,
            ["GUID"] = "7FFE1D28",
            ["NextDialogue"] = 51127621,
            },
        [51127621] = {
            ["Content"] = "我倒也没仔细琢磨过，按船上木料的情况来看，约莫怎么也有个百来年的历史了，但这种事也说不好。",
            ["ContentFR"] = "Je ne me suis jamais penché dessus de très près, mais à en juger par l’état du bois, elle doit bien avoir une centaine d’années... au bas mot. Après, ce genre de chose, ça reste difficile à affirmer.",
            ["DialogueId"] = 51127621,
            ["GUID"] = "7FFE1D52",
            ["NextDialogue"] = 51127622,
            ["SpeakNpcId"] = 701067,
            },
        [51127622] = {
            ["Content"] = "也许在虬先生之前，哪些对这老古董情有独钟的怪咖，也曾里里面面给它翻修过呢？",
            ["ContentFR"] = "Avant Maître Qiu, il y a sûrement eu d’autres amateurs d’antiquités qui l’ont restauré de fond en comble.",
            ["DialogueId"] = 51127622,
            ["GUID"] = "7FFE1D7C",
            ["NextDialogue"] = 51127623,
            ["SpeakNpcId"] = 701067,
            },
        [51127623] = {
            ["Content"] = "不过说到底可以确定的是，这船应该是出自早年那班织星客们的，不然谁还会在船身顶部留个如此大的坑位用来装千星板呢？",
            ["ContentFR"] = "Mais une chose est sûre : seuls les premiers Tisse-Étoiles auraient laissé un espace aussi large sur le pont pour un Panneau aux Mille Étoiles.",
            ["DialogueId"] = 51127623,
            ["GUID"] = "7FFE1DA6",
            ["NextDialogue"] = 51127633,
            ["SpeakNpcId"] = 701067,
            },
        [51127624] = {
            ["Content"] = "这船从哪来的？",
            ["ContentFR"] = "D’où vient-il ?",
            ["DialogueId"] = 51127624,
            ["GUID"] = "7FFE1DD0",
            ["NextDialogue"] = 51127625,
            },
        [51127625] = {
            ["Content"] = "这个嘛……我也不是特别清楚，不过排除掉那些怪力乱神的说法，或者天禄司高层与微茫市内部有所勾结这种怎么想都不可能的……倒是有两种较为可信。",
            ["ContentFR"] = "Difficile à dire. Si on écarte les histoires de fantômes... ou celles, tout aussi invraisemblables, d’arrangements secrets entre le Bureau de la Fortune Céleste et le Marché Voilé... deux versions tiennent la route.",
            ["DialogueId"] = 51127625,
            ["GUID"] = "7FFE1DFA",
            ["NextDialogue"] = 51127626,
            ["SpeakNpcId"] = 701067,
            },
        [51127626] = {
            ["Content"] = "一是说百年之前，黑蛟作乱之时，白龙神君将其镇压，恰逢海域附近有一艘归来的织星客船只，无力承受神君怒火。",
            ["ContentFR"] = "La première dit que, lors du chaos causé par le Dragon Noir, le Seigneur Dragon d’Argent l’a écrasé. À ce moment-là, un navire de Tisse-Étoiles, de retour au port, se trouvait dans les parages — et n’a pas résisté à la colère divine.",
            ["DialogueId"] = 51127626,
            ["GUID"] = "7FFE1E24",
            ["NextDialogue"] = 51127627,
            ["SpeakNpcId"] = 701067,
            },
        [51127627] = {
            ["Content"] = "巨大的浪潮把船掀翻，船上人员全都死于海难，这艘船顺着洋流肆意漂流，直到在此触礁。",
            ["ContentFR"] = "Une vague colossale l’a retournée. Tout l’équipage est mort. Le navire a dérivé jusqu’à s’échouer ici.",
            ["DialogueId"] = 51127627,
            ["GUID"] = "7FFE1E4E",
            ["NextDialogue"] = 51127628,
            ["SpeakNpcId"] = 701067,
            },
        [51127628] = {
            ["Content"] = "另一说是……（小声）你知道这里的人不好惹吧？",
            ["ContentFR"] = "L’autre version... tu sais que les gens d’ici ne sont pas tendres, hein ?",
            ["DialogueId"] = 51127628,
            ["GUID"] = "7FFE1E78",
            ["NextDialogue"] = 51127629,
            ["SpeakNpcId"] = 701067,
            },
        [51127629] = {
            ["Content"] = "（小声）说是有那种……心肠极为歹毒，心思极为缜密之人，混进了织星客里，把船上的人都……伪装成海难呢。",
            ["ContentFR"] = "On dit qu’un homme d’une cruauté extrême se serait infiltré parmi les Tisse-Étoiles... et aurait massacré tout l’équipage, maquillant le tout en naufrage.",
            ["DialogueId"] = 51127629,
            ["GUID"] = "7FFE1EA2",
            ["NextDialogue"] = 51127630,
            ["SpeakNpcId"] = 701067,
            },
        [51127630] = {
            ["Content"] = "（正常）诶呀，不过那都是说着图一乐的，真正的原因想必只是哪位前辈的收藏罢。",
            ["ContentFR"] = "Bah... des histoires pour passer le temps. En réalité, ce n’est sans doute que la collection d’un ancien.",
            ["DialogueId"] = 51127630,
            ["GUID"] = "7FFE1ECC",
            ["NextDialogue"] = 51127633,
            ["SpeakNpcId"] = 701067,
            },
        [51127631] = {
            ["Content"] = "没什么要说的了。",
            ["ContentFR"] = "Je n’ai plus rien à demander.",
            ["DialogueId"] = 51127631,
            ["GUID"] = "7FFE1EF6",
            ["NextDialogue"] = 51127632,
            },
        [51127632] = {
            ["Content"] = "要走了吗娃儿，下次再过来找我说说话呗，年纪大啦，就爱和你们这些娃儿没事聊上几句。",
            ["ContentFR"] = "Tu t’en vas, {性别:gamin|gamine} ? Reviens me voir à l’occasion. À mon âge, on aime bien discuter avec les jeunes.",
            ["DialogueId"] = 51127632,
            ["GUID"] = "7FFE1F20",
            ["SpeakNpcId"] = 701067,
            },
        [51127633] = {
            ["DialogueId"] = 51127633,
            ["DialoguePanelType"] = "None",
            ["Duration"] = 0.1,
            ["FinalDialogueId"] = 51127632,
            ["GUID"] = "7FFE1F4A",
            ["NextOptions"] = {
                [1] = 51127611,
                [2] = 51127616,
                [3] = 51127620,
                [4] = 51127624,
                [5] = 51127631,
                },
            },
        [51127701] = {
            ["Content"] = "最近微茫市来了些新面孔，买卖时闲话许多，上不得台面。",
            ["ContentFR"] = "Ces derniers temps, pas mal de nouvelles têtes traînent au Marché Voilé. Quand ils marchandent, ils bavardent trop... ça manque sérieusement de tenue.",
            ["DialogueId"] = 51127701,
            ["GUID"] = "7FFE2A72",
            ["NextDialogue"] = 51127702,
            ["SpeakNpcId"] = 701068,
            },
        [51127702] = {
            ["Content"] = "可不是，那次我路过偶然看到个摆件小巧可爱，想收一个回去送婆娘，结果一问，你猜他怎么说的？",
            ["ContentFR"] = "Tu m’étonnes. L’autre jour, je passais devant un étal et j’ai vu un petit bibelot, fin et mignon. Je me suis dit que ça ferait un cadeau pour ma femme. Alors je demande le prix... et devine ce que le type m’a répondu.",
            ["DialogueId"] = 51127702,
            ["GUID"] = "7FFE2A9C",
            ["NextDialogue"] = 51127703,
            ["SpeakNpcId"] = 701069,
            },
        [51127703] = {
            ["Content"] = "我猜猜……什么家传之宝，或者盗墓所得，亦或者是……总归是些上不得台面的说法。",
            ["ContentFR"] = "Laisse-moi deviner... un héritage familial, un objet déterré d’une tombe, ou quelque autre histoire du même genre. Bref, des excuses indignes du Marché Voilé.",
            ["DialogueId"] = 51127703,
            ["GUID"] = "7FFE2AC6",
            ["NextDialogue"] = 51127704,
            ["SpeakNpcId"] = 701068,
            },
        [51127704] = {
            ["Content"] = "何止上不得台面，这是失了咱们微茫市的规矩！谁不知道，微茫市做生意最重要的一点就是只谈物件，不问来去。",
            ["ContentFR"] = "Indignes ? Pire que ça. C’est une violation pure et simple de nos règles. Tout le monde sait qu’ici, on ne parle que de l’objet — jamais de son origine.",
            ["DialogueId"] = 51127704,
            ["GUID"] = "7FFE2AF0",
            ["NextDialogue"] = 51127705,
            ["SpeakNpcId"] = 701069,
            },
        }
  end },
  { MinKey = 51127705, MaxKey = 51140062, Loader = function()
      return {
        [51127705] = {
            ["Content"] = "哟，你说这我又想起来了，之前那些来问我那摊子价格的，张口就是几几钱，连暗语也不说，真是不懂规矩！",
            ["ContentFR"] = "Ah, ça me rappelle ceux qui sont venus à mon étal récemment. Ils annonçaient les prix à voix haute, en chiffres bien clairs, sans même utiliser les mots codés. Une totale ignorance des usages.",
