            },
        [51127825] = {
            ["Content"] = "还有呢？",
            ["ContentFR"] = "<I>Et puis ?</>",
            ["DialogueId"] = 51127825,
            ["GUID"] = "7FFE3ECA",
            ["NextDialogue"] = 51127826,
            },
        [51127826] = {
            ["Content"] = "讲义气啊！我们这些经常来往的熟人，逢年过节，虬先生总是会给咱们都寄上些礼品，有时候是精致名点，有时是珍奇古玩，总是少不了的。",
            ["ContentFR"] = "Il a le sens de l’honneur. Nous, les habitués, à chaque fête, il nous fait toujours parvenir quelque chose : pâtisseries raffinées, antiquités rares... jamais il n’oublie.",
            ["DialogueId"] = 51127826,
            ["GUID"] = "7FFE3EF4",
            ["NextDialogue"] = 51127827,
            ["SpeakNpcId"] = 701070,
            },
        [51127827] = {
            ["Content"] = "如果不是虬先生对大家如此之好，我何必还苦兮兮跑来这黑市等着他与他交易……",
            ["ContentFR"] = "Sans cette attention constante, crois-tu vraiment que je me donnerais la peine de venir jusqu’ici, dans ce marché noir, pour l’attendre et traiter avec lui ?",
            ["DialogueId"] = 51127827,
            ["GUID"] = "7FFE3F1E",
            ["SpeakNpcId"] = 701070,
            },
        [51127828] = {
            ["Content"] = "好了不要再说了，知道你是虬吹了。",
            ["ContentFR"] = "<I>Ça va, j’ai compris. Tu es un fan absolu de Maître Qiu.</>",
            ["DialogueId"] = 51127828,
            ["GUID"] = "7FFE3F48",
            ["NextDialogue"] = 51127829,
            },
        [51127829] = {
            ["Content"] = "什么意思，你们这些小孩嘴里说出的词语总是让我听不明白，就像我那八岁的女儿，一天到晚都在那说什么……又能怎……语气怪怪的。",
            ["ContentFR"] = "Un quoi ? Vous autres jeunes utilisez des mots bien étranges... Comme ma fille de huit ans, toujours à dire des choses incompréhensibles...",
            ["DialogueId"] = 51127829,
            ["GUID"] = "7FFE3F72",
            ["NextDialogue"] = 51127830,
            ["SpeakNpcId"] = 701070,
            },
        [51127830] = {
            ["Content"] = "说起来我那女儿，也很喜欢老虬，老虬来我家时，总会给她额外捎上些甜品果子，她每回都盼着他来……",
            ["ContentFR"] = "D’ailleurs, elle adore Maître Qiu. Quand il vient chez nous, il lui apporte toujours des douceurs. Elle l’attend avec impatience.",
            ["DialogueId"] = 51127830,
            ["GUID"] = "7FFE3F9C",
            ["SpeakNpcId"] = 701070,
            },
        [51127831] = {
            ["Content"] = "我先溜了！",
            ["ContentFR"] = "Je m’éclipse !",
            ["DialogueId"] = 51127831,
            ["GUID"] = "7FFE3FC6",
            ["NextDialogue"] = 51127832,
            },
        [51127832] = {
            ["Content"] = "怎么就走了，你还没说你来这里是做什么的呢！",
            ["ContentFR"] = "Déjà {性别:parti|partie} ? Mais tu ne m’as même pas dit ce que tu venais faire ici !",
            ["DialogueId"] = 51127832,
            ["GUID"] = "7FFE3FF0",
            ["SpeakNpcId"] = 701070,
            },
        [51127901] = {
            ["Content"] = "（这只狴犴的状态看起来很不对劲，似乎在变黑与保持白色之间摇摆不定……）",
            ["ContentFR"] = "L’état de ce Bi’an est très instable. Sa forme vacille, oscillant entre une blancheur fragile et une noirceur envahissante...",
            ["DialogueId"] = 51127901,
            ["GUID"] = "7FFE4B42",
            ["NextOptions"] = {
                [1] = 51127902,
                [2] = 51127907,
                },
            },
        [51127902] = {
            ["Content"] = "我能帮你什么吗？",
            ["ContentFR"] = "<I>Puis-je t’aider ?</>",
            ["DialogueId"] = 51127902,
            ["GUID"] = "7FFE4B6C",
            ["NextDialogue"] = 51127903,
            },
        [51127903] = {
            ["Content"] = "呼……",
            ["ContentFR"] = "<I>Hrr...</>",
            ["DialogueId"] = 51127903,
            ["GUID"] = "7FFE4B96",
            ["NextDialogue"] = 51127904,
            ["SpeakNpcId"] = 701071,
            },
        [51127904] = {
            ["Content"] = "（它看了你一眼，眼底猩红，不知是受了伤还是在竭力保持清醒。）",
            ["ContentFR"] = "Il lève les yeux vers vous. Leur rougeoiement est intense — impossible de dire s’il souffre ou s’il lutte simplement pour rester conscient.",
            ["DialogueId"] = 51127904,
            ["GUID"] = "7FFE4BC0",
            ["NextDialogue"] = 51127905,
            },
        [51127905] = {
            ["Content"] = "……呜……噫呜……呜……",
            ["ContentFR"] = "<I>... grr... hhrr... grr...</>",
            ["DialogueId"] = 51127905,
            ["GUID"] = "7FFE4BEA",
            ["NextDialogue"] = 51127906,
            ["SpeakNpcId"] = 701071,
            },
        [51127906] = {
            ["Content"] = "（狴犴在你面前自绝了。）",
            ["ContentFR"] = "Le Bi’an chancelle, puis s’effondre devant vous.",
            ["DialogueId"] = 51127906,
            ["GUID"] = "7FFE4C14",
            ["NextOptions"] = {
                [1] = 51127912,
                [2] = 51127914,
                },
            },
        [51127907] = {
            ["Content"] = "（拿起武器，做好防备。）",
            ["ContentFR"] = "<I>Saisir votre arme et rester sur vos gardes</>",
            ["DialogueId"] = 51127907,
            ["GUID"] = "7FFE4C3E",
            ["NextDialogue"] = 51127908,
            },
        [51127908] = {
            ["Content"] = "嗷！",
            ["ContentFR"] = "<I>Rraaaagh !</>",
            ["DialogueId"] = 51127908,
            ["GUID"] = "7FFE4C68",
            ["NextDialogue"] = 51127909,
            ["SpeakNpcId"] = 701071,
            },
        [51127909] = {
            ["Content"] = "（在你露出刀光的那一刹，狴犴仰天长啸，向你冲来，却因力竭跌倒在地。）",
            ["ContentFR"] = "À l’instant où l’éclat de votre lame se révèle, le Bi’an semble perdre tout contrôle. Sa forme se noie dans l’ombre et il se rue sur vous.",
            ["DialogueId"] = 51127909,
            ["GUID"] = "7FFE4C92",
            ["NextDialogue"] = 51127910,
            },
        [51127910] = {
            ["Content"] = "嗷呜呜……呜……",
            ["ContentFR"] = "<I>Aouh... grr... hhrr...</>",
            ["DialogueId"] = 51127910,
            ["GUID"] = "7FFE4CBC",
            ["NextDialogue"] = 51127911,
            ["SpeakNpcId"] = 701071,
            },
        [51127911] = {
            ["Content"] = "（狴犴在你面前咽了气。）",
            ["ContentFR"] = "Le souffle du Bi’an s’éteint à vos pieds.",
            ["DialogueId"] = 51127911,
            ["GUID"] = "7FFE4CE6",
            ["NextOptions"] = {
                [1] = 51127912,
                [2] = 51127914,
                },
            },
        [51127912] = {
            ["Content"] = "安葬狴犴。",
            ["ContentFR"] = "<I>Offrir une sépulture au Bi’an</>",
            ["DialogueId"] = 51127912,
            ["GUID"] = "7FFE4D10",
            ["ImprPlusId"] = 1207,
            ["NextDialogue"] = 51127913,
            },
        [51127913] = {
            ["Content"] = "（你将这只死去的狴犴好好安葬了……）",
            ["ContentFR"] = "Vous prenez soin d’ensevelir dignement la créature défunte...",
            ["DialogueId"] = 51127913,
            ["GUID"] = "7FFE4D3A",
            },
        [51127914] = {
            ["Content"] = "离开吧。",
            ["ContentFR"] = "<I>Partir</>",
            ["DialogueId"] = 51127914,
            ["GUID"] = "7FFE4D64",
            ["ImprPlusId"] = 1211,
            ["NextDialogue"] = 51127915,
            },
        [51127915] = {
            ["Content"] = "（自尘土中来，归尘土中去……）",
            ["ContentFR"] = "De la poussière il est venu... à la poussière il retourne.",
            ["DialogueId"] = 51127915,
            ["GUID"] = "7FFE4D8E",
            },
        [51128001] = {
            ["Content"] = "嘶……又冷起来了，这鬼天气！我带来的考古器材全都结了一层晶，零件迟钝，反应不灵，诶！又要让虬先生破费维修了！",
            ["ContentFR"] = "<I>Brr... </>encore ce froid infernal ! Tout mon matériel archéologique est couvert de cristaux — mécanismes grippés, capteurs engourdis... Ah ! Maître Qiu va encore devoir payer les réparations !",
            ["DialogueId"] = 51128001,
            ["GUID"] = "7FFE5BAA",
            ["NextDialogue"] = 51128002,
            ["SpeakNpcId"] = 701072,
            },
        [51128002] = {
            ["Content"] = "咦？你是谁？你怎么会跑到这种地方来？快回去快回去，这里可不是等闲之辈可以随意来往的地方！",
            ["ContentFR"] = "Hm ? Qui êtes-vous ? Que faites-vous dans un endroit pareil ? Rentrez chez vous, vite ! Ce lieu n’est pas fait pour qu’on s’y promène à la légère !",
            ["DialogueId"] = 51128002,
            ["GUID"] = "7FFE5BD4",
            ["NextOptions"] = {
                [1] = 51128003,
                [2] = 51128005,
                },
            ["SpeakNpcId"] = 701072,
            },
        [51128003] = {
            ["Content"] = "（听到她提起虬先生……）我是虬先生叫过来的。",
            ["ContentFR"] = "<I>Maître Qiu m’a {性别:envoyé|envoyée}.</>",
            ["DialogueId"] = 51128003,
            ["GUID"] = "7FFE5BFE",
            ["ImprPlusId"] = 1208,
            ["NextDialogue"] = 51128004,
            },
        [51128004] = {
            ["Content"] = "虬先生叫你来的？怎么可能？不是说了尘漠石海区域只由我一人来负责就好吗？来之前还说的……什么什么，无甚旧史，不必细考的……",
            ["ContentFR"] = "Maître Qiu ? Impossible. Il a bien dit que la Mer de Poussière relevait uniquement de ma responsabilité... Et avant mon départ, il insistait encore : « pas de vestiges notables, inutile d’approfondir »...",
            ["DialogueId"] = 51128004,
            ["GUID"] = "7FFE5C28",
            ["SpeakNpcId"] = 701072,
            },
        [51128005] = {
            ["Content"] = "看你一个人在这很危险，就过来看看。",
            ["ContentFR"] = "<I>Vous étiez seule, et c’est dangereux ici.</>",
            ["DialogueId"] = 51128005,
            ["GUID"] = "7FFE5C52",
            ["ImprPlusId"] = 1207,
            ["NextDialogue"] = 51128006,
            },
        [51128006] = {
            ["Content"] = "呜呜呜，谢谢你好心人，我在这太久了，风餐露宿的，都快忘了还有除了玄色狴犴之外的正常人存在了。",
            ["ContentFR"] = "<I>Bouh...</> merci, vraiment. Je suis ici depuis si longtemps, à dormir dehors et manger au vent, que j’en avais presque oublié qu’il existait encore des gens normaux... en dehors des Bi’an obscurs.",
            ["DialogueId"] = 51128006,
            ["GUID"] = "7FFE5C7C",
            ["NextDialogue"] = 51128007,
            ["SpeakNpcId"] = 701072,
            },
        [51128007] = {
            ["Content"] = "不管怎么说，你也得先回去多带些衣服，这里的温差特殊，没一会就要冷得结冰了。",
            ["ContentFR"] = "Quoi qu’il en soit, vous devriez repartir vous couvrir davantage. Les écarts de température ici sont violents — on gèle en un clin d’œil.",
            ["DialogueId"] = 51128007,
            ["GUID"] = "7FFE5CA6",
            ["NextDialogue"] = 51128008,
            ["SpeakNpcId"] = 701072,
            },
        [51128008] = {
            ["Content"] = "呼……我也得去加上两件衣服了。",
            ["ContentFR"] = "<I>Pff... </>moi aussi, je vais rajouter une couche.",
            ["DialogueId"] = 51128008,
            ["GUID"] = "7FFE5CD0",
            ["SpeakNpcId"] = 701072,
            },
        [51128101] = {
            ["Content"] = "一会冷一会热……想当年我姥姥还跟我说，这里是个春暖花开的好地方呢！",
            ["ContentFR"] = "Un coup froid, un coup chaud... Dire que mon arrière-grand-mère racontait qu’ici, c’était un endroit doux, où les fleurs s’épanouissaient au printemps !",
            ["DialogueId"] = 51128101,
            ["GUID"] = "7FFE6C12",
            ["NextDialogue"] = 51128102,
            ["SpeakNpcId"] = 701072,
            },
        [51128102] = {
            ["Content"] = "啊啊啊！又热起来了！一热起来我就心烦气躁！臭外套，滚一边去吧！",
            ["ContentFR"] = "Ahhh ! Ça recommence, il fait une chaleur à crever ! Dès qu’il fait chaud, je deviens insupportable ! Fichu manteau... hors de ma vue !",
            ["DialogueId"] = 51128102,
            ["GUID"] = "7FFE6C3C",
            ["NextDialogue"] = 51128103,
            ["SpeakNpcId"] = 701072,
            },
        [51128103] = {
            ["Content"] = "你！你是谁！哦！我想起来了，你之前来过这里！衣服带好了吗？这就回来啦？",
            ["ContentFR"] = "Hé ! Vous ! Qui êtes-vous— Ah ! Je me souviens. Vous êtes déjà {性别:venu|venue} ici, n’est-ce pas ? Alors, avez-vous pris des vêtements cette fois ? Et vous voilà déjà de retour ?",
            ["DialogueId"] = 51128103,
            ["GUID"] = "7FFE6C66",
            ["NextOptions"] = {
                [1] = 51128104,
                [2] = 51128106,
                [3] = 51128120,
                },
            ["SpeakNpcId"] = 701072,
            },
        [51128104] = {
            ["Content"] = "我包里有很多件。",
            ["ContentFR"] = "<I>J’en ai beaucoup dans mon sac.</>",
            ["DialogueId"] = 51128104,
            ["GUID"] = "7FFE6C90",
            ["NextDialogue"] = 51128105,
            },
        [51128105] = {
            ["Content"] = "那就好，你可不知道这里的天气有多怪，一会冷得牙齿打颤，一会又热得满头大汗，真是要了命了。",
            ["ContentFR"] = "Tant mieux. Vous n’imaginez pas à quel point le temps est étrange ici : un coup on claque des dents de froid, l’instant d’après on transpire à grosses gouttes... c’est à rendre fou.",
            ["DialogueId"] = 51128105,
            ["GUID"] = "7FFE6CBA",
            ["NextOptions"] = {
                [1] = 51128108,
                },
            ["SpeakNpcId"] = 701072,
            },
        [51128106] = {
            ["Content"] = "我不怕冷，也不怕热。",
            ["ContentFR"] = "<I>Le froid comme la chaleur ne me font rien.</>",
            ["DialogueId"] = 51128106,
            ["GUID"] = "7FFE6CE4",
            ["NextDialogue"] = 51128107,
            },
        [51128107] = {
            ["Content"] = "什么？！那是你没见识过这里的天气有多怪！一会冷得牙齿打颤，一会又热得满头大汗，真是要了命了。",
            ["ContentFR"] = "Quoi ?! Alors ça, c’est que vous n’avez encore rien vu ! Ici, ça change sans prévenir : un moment on grelotte jusqu’aux os, l’instant suivant on sue de partout... c’est infernal.",
            ["DialogueId"] = 51128107,
            ["GUID"] = "7FFE6D0E",
            ["NextOptions"] = {
                [1] = 51128108,
                },
            ["SpeakNpcId"] = 701072,
            },
        [51128108] = {
            ["Content"] = "这里的天气为什么奇怪？",
            ["ContentFR"] = "<I>Pourquoi le climat est-il si instable ici ?</>",
            ["DialogueId"] = 51128108,
            ["GUID"] = "7FFE6D38",
            ["NextDialogue"] = 51128109,
            },
        [51128109] = {
            ["Content"] = "嘿！你要问这个，我可太有发言权了，我在这待了这么久，可算把这地方的历史和劳什子浊化现象整明白了七七八八。",
            ["ContentFR"] = "Ah ! Là-dessus, je suis bien placée pour vous répondre. Ça fait si longtemps que je travaille dans le coin que j’ai fini par comprendre une bonne partie de l’histoire du lieu... et de ce fichu phénomène d’Altération.",
            ["DialogueId"] = 51128109,
            ["GUID"] = "7FFE6D62",
            ["NextDialogue"] = 51128122,
            ["SpeakNpcId"] = 701072,
            },
        [51128110] = {
            ["Content"] = "聊聊这里的曾经。",
            ["ContentFR"] = "<I>À quoi ressemblait cet endroit avant ?</>",
            ["DialogueId"] = 51128110,
            ["GUID"] = "7FFE6D8C",
            ["NextDialogue"] = 51128111,
            },
        [51128111] = {
            ["Content"] = "以前啊，我太姥姥说的，说这里是个好地方，好山好水，山川纵横，美景如画，四季如春。那时这还没那么荒，有人会在山上种半步仙。",
            ["ContentFR"] = "Autrefois... enfin, d’après mon arrière-grand-mère. Elle disait que c’était un endroit splendide : montagnes et rivières à perte de vue, des paysages dignes d’un tableau, et un printemps qui durait toute l’année. À l’époque, ce n’était pas encore aussi aride. Des gens cultivaient même la Demi-Pas-d’Immortel sur les pentes.",
            ["DialogueId"] = 51128111,
            ["GUID"] = "7FFE6DB6",
            ["NextDialogue"] = 51128112,
            ["SpeakNpcId"] = 701072,
            },
        [51128112] = {
            ["Content"] = "那花一开，满山都是红艳艳的，香气熏得人昏昏沉沉，扰得路过的织星客们纷纷投诉，说是从这路上走就会香昏迷过去。",
            ["ContentFR"] = "Quand ces fleurs s’ouvraient, toute la montagne devenait rouge éclatant. Le parfum était si entêtant qu’il donnait le tournis — au point que les Tisse-Étoiles de passage s’en plaignaient, disant qu’en empruntant cette route, on risquait de s’évanouir à force d’en respirer l’odeur.",
            ["DialogueId"] = 51128112,
            ["GUID"] = "7FFE6DE0",
            ["SpeakNpcId"] = 701072,
            },
        [51128113] = {
            ["Content"] = "聊聊这里为什么会变成这样。",
            ["ContentFR"] = "<I>Alors pourquoi cet endroit est-il devenu ainsi ?</>",
            ["DialogueId"] = 51128113,
            ["GUID"] = "7FFE6E0A",
            ["NextDialogue"] = 51128114,
            },
        [51128114] = {
            ["Content"] = "还能因为什么，烛阴之灾呗。那恶兽，贼心不死，吞吐之间全是黑雾，雾气从海上向内地不断扩散，直至覆盖整个区域。",
            ["ContentFR"] = "À cause de quoi, à votre avis ? Du Fléau de Zhuyin, évidemment. Cette bête immonde n’a jamais cessé de nuire : à chaque souffle, elle rejetait une brume noire qui s’est propagée depuis la mer vers l’intérieur des terres, jusqu’à recouvrir toute la région.",
            ["DialogueId"] = 51128114,
            ["GUID"] = "7FFE6E34",
            ["NextDialogue"] = 51128115,
            ["SpeakNpcId"] = 701072,
            },
        [51128115] = {
            ["Content"] = "黑雾还邪气着呢！被影响的地方一会冷一会热，山上的石头受不住这温差，全碎成了块块。那花啊草啊的也不长了，盖上了一层不知道什么东西。",
            ["ContentFR"] = "Et cette brume était profondément malsaine. Là où elle passait, le froid et la chaleur s’alternaient sans cesse. Les roches n’y ont pas résisté — elles se sont fissurées, pulvérisées. Les plantes ont cessé de pousser, recouvertes d’une croûte inconnue.",
            ["DialogueId"] = 51128115,
            ["GUID"] = "7FFE6E5E",
            ["NextDialogue"] = 51128116,
            ["SpeakNpcId"] = 701072,
            },
        [51128116] = {
            ["Content"] = "这种现象就是浊化，也是我一直在这里研究的方向。",
            ["ContentFR"] = "Ce phénomène, on l’appelle l’Altération. Et c’est précisément ce que j’étudie ici.",
            ["DialogueId"] = 51128116,
            ["GUID"] = "7FFE6E88",
            ["SpeakNpcId"] = 701072,
            },
        [51128117] = {
            ["Content"] = "聊聊浊化。",
            ["ContentFR"] = "<I>L’Altération, c’est quoi exactement ?</>",
            ["DialogueId"] = 51128117,
            ["GUID"] = "7FFE6EB2",
            ["NextDialogue"] = 51128118,
            },
        [51128118] = {
            ["Content"] = "唔……这其实很难说，但我的初步推测是，黑雾里有种晶尘，肉眼看不到，但是会在呼吸之间被吸入体内。",
            ["ContentFR"] = "Hmm... ce n’est pas facile à expliquer. Mais selon mes premières hypothèses, la brume noire contient une sorte de poussière cristalline. Invisible à l’œil nu, mais que l’on inhale sans s’en rendre compte en respirant.",
            ["DialogueId"] = 51128118,
            ["GUID"] = "7FFE6EDC",
            ["NextDialogue"] = 51128119,
            ["SpeakNpcId"] = 701072,
            },
        [51128119] = {
            ["Content"] = "被这种晶尘影响的生物，原本的形态就会被破坏。原理嘛……搞不懂！但是邪门的很，不是我说，狴犴大人都抵挡不了呢！",
            ["ContentFR"] = "Les êtres vivants affectés par cette poussière voient leur forme originelle se détériorer. Le mécanisme exact ? ... Aucune idée. Mais c’est terriblement étrange — même les Bi’an n’y résistent pas.",
            ["DialogueId"] = 51128119,
            ["GUID"] = "7FFE6F06",
            ["SpeakNpcId"] = 701072,
            },
        [51128120] = {
            ["Content"] = "不和你聊了",
            ["ContentFR"] = "Je vais m’arrêter là.",
            ["DialogueId"] = 51128120,
            ["GUID"] = "7FFE6F30",
            ["NextDialogue"] = 51128121,
            },
        [51128121] = {
            ["Content"] = "好不容易等来个聊聊天的，诶……再不和正常人说说话，我的嘴巴可就要生锈啦。",
            ["ContentFR"] = "Oh... J’avais enfin quelqu’un avec qui discuter. Si je ne parle plus à une personne normale bientôt, j’ai bien peur que ma langue ne finisse par rouiller...",
            ["DialogueId"] = 51128121,
            ["GUID"] = "7FFE6F5A",
            ["SpeakNpcId"] = 701072,
            },
        [51128122] = {
            ["DialogueId"] = 51128122,
            ["DialoguePanelType"] = "None",
            ["Duration"] = 0.1,
            ["FinalDialogueId"] = 51128121,
            ["GUID"] = "7FFE6F84",
            ["NextOptions"] = {
                [1] = 51128110,
                [2] = 51128113,
                [3] = 51128117,
                [4] = 51128120,
                },
            },
        [51128201] = {
            ["Content"] = "这怎么连个插香的地方都没有……还好我带了香炉！不然今天好不容易铤而走险过来一趟，要是啥也没干就回去可太丢面子了！",
            ["ContentFR"] = "Quoi ? Il n’y a même pas un endroit pour planter l’encens... Heureusement que j’ai apporté un encensoir ! J’ai pris assez de risques pour venir jusqu’ici — repartir sans rien faire, ce serait trop humiliant !",
            ["DialogueId"] = 51128201,
            ["GUID"] = "7FFE7C7A",
            ["NextOptions"] = {
                [1] = 51128202,
                [2] = 51128204,
                },
            ["SpeakNpcId"] = 701073,
            },
        [51128202] = {
            ["Content"] = "你怎么一个人在这，这里很危险。",
            ["ContentFR"] = "<I>Que faites-vous seul ici ? C’est dangereux.</>",
            ["DialogueId"] = 51128202,
            ["GUID"] = "7FFE7CA4",
            ["ImprPlusId"] = 1207,
            ["NextDialogue"] = 51128203,
            },
        [51128203] = {
            ["Content"] = "我当然知道危险啦，多谢你的提醒，但我就是图着危险才特意来此处的！我偏要来这旁人不敢涉足之地，点上一根沉月香给白龙神君，求他将烛阴之灾彻底扫除！",
            ["ContentFR"] = "Oh, je le sais bien ! Merci de vous en soucier. Mais justement, c’est parce que c’est dangereux que je suis venu. Je voulais allumer un bâton d’encens de Lune Profonde pour le Seigneur Dragon d’Argent, ici même, là où personne n’ose poser le pied, et lui demander d’éradiquer définitivement le Fléau de Zhuyin !",
            ["DialogueId"] = 51128203,
            ["GUID"] = "7FFE7CCE",
            ["SpeakNpcId"] = 701073,
            },
        [51128204] = {
            ["Content"] = "再等一会就有玄色狴犴来吃你咯。",
            ["ContentFR"] = "<I>Si vous restez ici, un Bi’an obscur finira par venir vous dévorer.</>",
            ["DialogueId"] = 51128204,
            ["GUID"] = "7FFE7CF8",
            ["ImprPlusId"] = 1205,
            ["NextDialogue"] = 51128205,
            },
        [51128205] = {
            ["Content"] = "莫慌莫慌，我自是知道此地危险，但是我偏要来这旁人不敢涉足之地，点上一根沉月香给白龙神君，求他将烛阴之灾彻底扫除！",
            ["ContentFR"] = "Pas d’inquiétude, pas d’inquiétude. Je sais que l’endroit est dangereux — c’est précisément pour cela que je suis venu ici, là où nul n’ose s’aventurer, afin d’offrir de l’encens de Lune Profonde au Seigneur Dragon d’Argent et de le supplier d’anéantir le Fléau de Zhuyin une bonne fois pour toutes !",
            ["DialogueId"] = 51128205,
            ["GUID"] = "7FFE7D22",
            ["NextDialogue"] = 51128206,
            ["SpeakNpcId"] = 701073,
            },
        [51128206] = {
            ["Content"] = "不必担心我，我虽手无寸铁，但胜在机灵跑得快，且不是第一天来这了。反倒是你要担心自己，是那玄色狴犴找过来，我拔腿就跑时带不上你。",
            ["ContentFR"] = "Ne vous faites pas de souci pour moi. Je n’ai pas d’arme, certes, mais je suis vif et je cours vite — et ce n’est pas la première fois que je viens ici. En revanche, vous devriez penser à vous : si un Bi’an obscur surgit et que je dois détaler, je ne pourrai pas vous emporter avec moi.",
            ["DialogueId"] = 51128206,
            ["GUID"] = "7FFE7D4C",
            ["NextDialogue"] = 51128207,
            ["SpeakNpcId"] = 701073,
            },
        [51128207] = {
            ["Content"] = "所以你先走吧，不用管我！",
            ["ContentFR"] = "Alors partez, d’accord ? Ne vous occupez pas de moi !",
            ["DialogueId"] = 51128207,
            ["GUID"] = "7FFE7D76",
            ["SpeakNpcId"] = 701073,
            },
        [51128208] = {
            ["Content"] = "就在这里点香，白龙神君一定会像神话里那样挺身而出，将那恶兽赶尽杀绝！",
            ["ContentFR"] = "C’est ici que je vais allumer l’encens. Le Seigneur Dragon d’Argent se dressera comme dans les mythes, et il exterminera cette bête immonde jusqu’au dernier souffle !",
            ["DialogueId"] = 51128208,
            ["GUID"] = "7FFE7DA0",
            ["NextDialogue"] = 51128209,
            ["SpeakNpcId"] = 701073,
            },
        [51128209] = {
            ["Content"] = "诶哟，怎么又是你，你也真不害怕呢，这种地方你还一遍又一遍地来。",
            ["ContentFR"] = "Oh ? Encore vous ? Vous êtes vraiment sans peur... revenir encore et encore dans un endroit pareil.",
            ["DialogueId"] = 51128209,
            ["GUID"] = "7FFE7DCA",
            ["NextOptions"] = {
                [1] = 51128210,
                [2] = 51128233,
                },
            ["SpeakNpcId"] = 701073,
            },
        [51128210] = {
            ["Content"] = "这话该是我说你吧……",
            ["ContentFR"] = "<I>On pourrait dire la même chose de vous...</>",
            ["DialogueId"] = 51128210,
            ["GUID"] = "7FFE7DF4",
            ["NextDialogue"] = 51128211,
            },
        [51128211] = {
            ["Content"] = "哦！说的也是呢，我才是一遍又一遍来这的，不过不是说了嘛，我机灵跑得快，哪怕遇到危险也可以逃走的，为了你的安全，你还是先走吧。",
            ["ContentFR"] = "Ah ! Ce n’est pas faux. C’est vrai que c’est moi qui reviens sans cesse ici. Mais je vous l’ai dit : je suis rapide. Même en cas de danger, je peux toujours m’enfuir. Pour votre sécurité, vous feriez mieux de partir.",
            ["DialogueId"] = 51128211,
            ["GUID"] = "7FFE7E1E",
            ["NextOptions"] = {
                [1] = 51128212,
                },
            ["SpeakNpcId"] = 701073,
            },
        [51128212] = {
            ["Content"] = "我压根不用逃，直接击退玄色狴犴都可以。",
            ["ContentFR"] = "<I>Je n’ai pas besoin de fuir. Je peux repousser un Bi’an obscur sans problème.</>",
            ["DialogueId"] = 51128212,
            ["GUID"] = "7FFE7E48",
            ["NextDialogue"] = 51128213,
            },
        [51128213] = {
            ["Content"] = "看不出来啊，没想到你这么厉害，那你应该不是华胥人吧，唔……穿着打扮的确不是很像……",
            ["ContentFR"] = "Ah bon ? Je ne vous aurais pas cru aussi redoutable. Alors vous n’êtes sans doute pas originaire de Huaxu... Hmm... votre tenue ne ressemble pas vraiment à la nôtre.",
            ["DialogueId"] = 51128213,
            ["GUID"] = "7FFE7E72",
            ["NextDialogue"] = 51128214,
            ["SpeakNpcId"] = 701073,
            },
        [51128214] = {
            ["Content"] = "那你要跟我一起奉香吗？要是有两个人一起，想必白龙神君更能听到我们的求助！",
            ["ContentFR"] = "Dans ce cas, accepteriez-vous de brûler de l’encens avec moi ? À deux, nos prières auront plus de chances d’atteindre le Seigneur Dragon d’Argent !",
            ["DialogueId"] = 51128214,
            ["GUID"] = "7FFE7E9C",
            ["NextOptions"] = {
                [1] = 51128215,
                [2] = 51128221,
                },
            ["SpeakNpcId"] = 701073,
            },
        [51128215] = {
            ["Content"] = "你在这荒郊野岭奉香不是很奇怪吗？",
            ["ContentFR"] = "<I>Allumer de l’encens dans un endroit aussi désert, ce n’est pas étrange ?</>",
            ["DialogueId"] = 51128215,
            ["GUID"] = "7FFE7EC6",
            ["NextDialogue"] = 51128216,
            },
        [51128216] = {
            ["Content"] = "诶，这你就有所不知了，你应该知道此地天象异诡是何原因吧，就是那百年之前危害华胥的烛阴之灾，可你知不知道，烛阴这只恶兽为何会造成灾害呢？",
            ["ContentFR"] = "Ah, là-dessus, vous manquez d’un détail essentiel. Vous savez sans doute pourquoi les phénomènes célestes sont si anormaux ici : c’est à cause du Fléau de Zhuyin, qui a ravagé Huaxu il y a cent ans. Mais savez-vous pourquoi cette bête a provoqué un tel désastre ?",
            ["DialogueId"] = 51128216,
            ["GUID"] = "7FFE7EF0",
            ["NextDialogue"] = 51128217,
            ["SpeakNpcId"] = 701073,
            },
        [51128217] = {
            ["Content"] = "算啦，我也就不卖关子了，直接告诉你吧。在咱们华胥上古时期，有一只为非作歹的妖兽，名为烛阴。",
            ["ContentFR"] = "Bon, inutile de faire durer le suspense. Je vais vous le dire. Dans les temps anciens de Huaxu, il existait une bête démoniaque qui semait le chaos : Zhuyin.",
            ["DialogueId"] = 51128217,
            ["GUID"] = "7FFE7F1A",
            ["NextDialogue"] = 51128218,
            ["SpeakNpcId"] = 701073,
            },
        [51128218] = {
            ["Content"] = "其以不安之心篡夺华胥人行凶作恶，伤人见血，百姓因其作乱民不聊生，叫苦不迭。百姓们便轮番点香，求助于神君。",
            ["ContentFR"] = "Par son cœur inquiet et malveillant, elle poussait les hommes à la violence, faisant couler le sang. Le peuple vivait dans la misère, sans répit, et les lamentations ne cessaient jamais. Alors les gens allumèrent l’encens, les uns après les autres, et implorèrent l’aide du Seigneur Dragon.",
            ["DialogueId"] = 51128218,
            ["GUID"] = "7FFE7F44",
            ["NextDialogue"] = 51128219,
            ["SpeakNpcId"] = 701073,
            },
        [51128219] = {
            ["Content"] = "白龙神君在九天之上，闻到了百姓们点的沉月香，遂勃然大怒。动用神力将之驱逐至华胥海外。",
            ["ContentFR"] = "Depuis les Neuf Cieux, le Seigneur Dragon d’Argent perçut le parfum de l’encens de Lune Profonde. Pris de colère, il usa de sa puissance divine pour chasser Zhuyin au-delà des mers de Huaxu.",
            ["DialogueId"] = 51128219,
            ["GUID"] = "7FFE7F6E",
            ["NextDialogue"] = 51128220,
            ["SpeakNpcId"] = 701073,
            },
        [51128220] = {
            ["Content"] = "悬衡派仙人们齐心协力，以锁龙环将烛阴层层束缚在仙山之上，才让华胥重回安宁与祥和之中。",
            ["ContentFR"] = "Les immortels de la Secte Xuanheng unirent ensuite leurs forces, scellant Zhuyin à l’aide du Sceau Draconique et l’enchaînèrent sur la montagne sacrée. Ce n’est qu’alors que Huaxu retrouva la paix et l’harmonie.",
            ["DialogueId"] = 51128220,
            ["GUID"] = "7FFE7F98",
            ["NextOptions"] = {
                [1] = 51128223,
                },
            ["SpeakNpcId"] = 701073,
            },
        [51128221] = {
            ["Content"] = "好，给我一支。",
            ["ContentFR"] = "<I>Très bien. Donnez-m’en un.</>",
            ["DialogueId"] = 51128221,
            ["GUID"] = "7FFE7FC2",
            ["NextDialogue"] = 51128222,
            },
        [51128222] = {
            ["Content"] = "（你陪着他一起奉了根香。）",
            ["ContentFR"] = "Vous allumez un bâton d’encens et l’offrez à ses côtés.",
            ["DialogueId"] = 51128222,
            ["GUID"] = "7FFE7FEC",
            ["NextOptions"] = {
                [1] = 51128223,
                },
            },
        [51128223] = {
            ["Content"] = "所以你是想来复刻神话里的奉香行为，呼唤白龙神君？",
            ["ContentFR"] = "<I>Vous cherchez donc à reproduire le rituel des mythes, pour appeler le Seigneur Dragon d’Argent ?</>",
            ["DialogueId"] = 51128223,
            ["GUID"] = "7FFE8016",
            ["NextDialogue"] = 51128224,
            },
        [51128224] = {
            ["Content"] = "正是如此！我想着，定是现在大家整日都在奉香，白龙神君闻到哪哪都是香味，不知该帮哪里了。不如我来这无人之境奉香，神君一定会很好奇。",
            ["ContentFR"] = "Exactement ! Je me dis que, de nos jours, tout le monde brûle de l’encens sans cesse. Le Seigneur Dragon d’Argent doit sentir l’encens partout et ne plus savoir où intervenir. Alors si j’offre de l’encens ici, dans un lieu désert, il ne pourra qu’être intrigué.",
            ["DialogueId"] = 51128224,
            ["GUID"] = "7FFE8040",
            ["NextDialogue"] = 51128225,
            ["SpeakNpcId"] = 701073,
            },
        [51128225] = {
            ["Content"] = "好奇什么？",
            ["ContentFR"] = "Intrigué par quoi ?",
            ["DialogueId"] = 51128225,
            ["GUID"] = "7FFE806A",
            ["NextDialogue"] = 51128226,
            ["SpeakNpcId"] = 100001,
            },
        [51128226] = {
            ["Content"] = "好奇为何这人烟稀少之地会有香气啊！足见我心诚之滔滔！",
            ["ContentFR"] = "Par le fait que de l’encens brûle dans un endroit aussi isolé ! Cela prouve à quel point ma sincérité est profonde !",
            ["DialogueId"] = 51128226,
            ["GUID"] = "7FFE8094",
            ["NextDialogue"] = 51128227,
            ["SpeakNpcId"] = 701073,
            },
        [51128227] = {
            ["Content"] = "……",
            ["ContentFR"] = "...",
            ["DialogueId"] = 51128227,
            ["GUID"] = "7FFE80BE",
            ["NextDialogue"] = 51128228,
            ["SpeakNpcId"] = 100001,
            },
        [51128228] = {
            ["Content"] = "好啦，不多说了，你要跟我一起来奉吗？",
            ["ContentFR"] = "Bien, cessons de bavarder. Voulez-vous brûler de l’encens avec moi une seconde fois ?",
            ["DialogueId"] = 51128228,
            ["GUID"] = "7FFE80E8",
            ["NextOptions"] = {
                [1] = 51128229,
                [2] = 51128231,
                },
            ["SpeakNpcId"] = 701073,
            },
        [51128229] = {
            ["Content"] = "可以。",
            ["ContentFR"] = "<I>D’accord.</>",
            ["DialogueId"] = 51128229,
            ["GUID"] = "7FFE8112",
            ["NextDialogue"] = 51128230,
            },
        [51128230] = {
            ["Content"] = "来！今日我等一起奉香，明日你我皆是挚友！",
            ["ContentFR"] = "Allons-y ! Aujourd’hui nous offrons l’encens ensemble — demain, une amitié naîtra !",
            ["DialogueId"] = 51128230,
            ["GUID"] = "7FFE813C",
            ["SpeakNpcId"] = 701073,
            },
        [51128231] = {
            ["Content"] = "算了吧。",
            ["ContentFR"] = "<I>Laissez tomber.</>",
            ["DialogueId"] = 51128231,
            ["GUID"] = "7FFE8166",
            ["NextDialogue"] = 51128232,
            },
        [51128232] = {
            ["Content"] = "那好吧，你们外国人是不懂我们这些讲究的。",
            ["ContentFR"] = "Très bien... Les étrangers ne comprennent pas toujours nos usages.",
            ["DialogueId"] = 51128232,
            ["GUID"] = "7FFE8190",
            ["SpeakNpcId"] = 701073,
            },
        [51128233] = {
            ["Content"] = "有别的事，我先走了。",
            ["ContentFR"] = "J’ai autre chose à faire. Je vais y aller.",
            ["DialogueId"] = 51128233,
            ["GUID"] = "7FFE81BA",
            ["NextDialogue"] = 51128234,
            },
        [51128234] = {
            ["Content"] = "哦哦，那好吧！有缘再会！",
            ["ContentFR"] = "Ah, d’accord ! Que le destin nous réunisse à nouveau !",
            ["DialogueId"] = 51128234,
            ["GUID"] = "7FFE81E4",
            ["SpeakNpcId"] = 701073,
            },
        [51128301] = {
            ["Content"] = "（不知何人立的碑，碑上的字是……）",
            ["ContentFR"] = "Nul ne sait qui a dressé cette stèle. Les caractères gravés dessus disent :",
            ["DialogueId"] = 51128301,
            ["GUID"] = "7FFE8CE2",
            ["NextDialogue"] = 51128302,
            },
        [51128302] = {
            ["DialogueId"] = 51128302,
            ["DialoguePanelType"] = "{type:showtext;topic:SCEREAD_NAME_1000001;content:SCEREAD_TEXT_1000001}",
            ["GUID"] = "7FFE8D0C",
            },
        [51128401] = {
            ["Content"] = "（石碑上刻着密密麻麻的铭文，似是对一些人的纪念。）",
            ["ContentFR"] = "La stèle est couverte d’inscriptions serrées, semblant rendre hommage à des disparus.",
            ["DialogueId"] = 51128401,
            ["GUID"] = "7FFE9D4A",
            ["NextDialogue"] = 51128402,
            },
        [51128402] = {
            ["DialogueId"] = 51128402,
            ["DialoguePanelType"] = "{type:showtext;topic:SCEREAD_NAME_1000002;content:SCEREAD_TEXT_1000002}",
            ["GUID"] = "7FFE9D74",
            },
        [51140001] = {
            ["Camera"] = "-113.539062,61.592773,195.840332,0.000114,-25.089722,-48.41589,35.000008,218.514374,false,Manual,1.894586",
            ["Content"] = "不知道为什么……每次走在幽明涧，总觉得身后有阵阵凉风，冷飕飕地往我的领口里钻……",
            ["ContentFR"] = "Je ne sais pas pourquoi... Chaque fois que je traverse le Ravin du Clair-Obscur, j’ai l’impression qu’un courant d’air glacé me frôle le dos et s’infiltre dans mon col...",
            ["DialogueId"] = 51140001,
            ["GUID"] = "80060C6A",
            ["LookAt"] = {
                [1] = "100001:n(200002)",
                [2] = "200002:n(100001)",
                },
            ["Scripts"] = "SetVisibility{ActorId{701074},Visibility{\"Hide\"}}",
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Talk03_Start",
                },
            },
        [51140002] = {
            ["Camera"] = "-113.539062,61.592773,195.840332,0.000114,-25.089722,-48.41589,35.000008,218.514374,false,Manual,1.894586",
            ["Content"] = "那种感觉就像是我在水仙平原偷懒，卡米拉从背后阴恻恻地靠过来，然后……",
            ["ContentFR"] = "C’est exactement comme aux Asphodèles, quand j’essaie de faire une pause en douce et que Camilla s’approche derrière moi avec son regard tout froid, puis—",
            ["DialogueId"] = 51140002,
            ["GUID"] = "80060C94",
            ["Scripts"] = "SetVisibility{ActorId{701074},Visibility{\"Hide\"}}",
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Talk03_End",
                },
            },
        [51140003] = {
            ["Camera"] = "121.967773,-57.251953,229.506348,0.000098,-10.894431,176.76123,35.0,100000.0,false,DoNotOverride,7.0",
            ["Content"] = "敢问二位……",
            ["ContentFR"] = "Pardonnez-moi, vous deux...",
            ["DialogueId"] = 51140003,
            ["FinalCamera"] = "-25.474121,-45.555664,158.86438,0.000091,5.70566,175.16095,35.000008,100000.0,false,DoNotOverride,7.0",
            ["GUID"] = "80060CBE",
            ["Scripts"] = "SetVisibility{ActorId{701074},Visibility{\"Show\"}}",
            ["SpeakNpcId"] = 701074,
            ["SpeakNpcName"] = "UI_NPC_Name_mosheng_Sce",
            ["TalkActionId"] = {
                [1] = "701074:Wuyou_Born",
                },
            ["ToFinalCameraBlendTime"] = 0.2,
            },
        [51140004] = {
            ["Camera"] = "-339.228027,-47.569336,251.475708,0.000101,-29.99987,-4.83933,61.07761,402.688873,false,Manual,7.0",
            ["Content"] = "呜啊！有鬼啊！！！",
            ["ContentFR"] = "Aaaah ! U-Un fantôme !",
            ["DialogueId"] = 51140004,
            ["GUID"] = "80060CE8",
            ["LookAt"] = {
                [1] = "200002:n(200002)",
                [2] = "100001:n(200002)",
                },
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Afraid_Start",
                [2] = "100001:Talk03_Start",
                },
            },
        [51140005] = {
            ["Camera"] = "-339.228027,-47.569336,251.475708,0.000101,-29.99987,-4.83933,61.07761,402.688873,false,Manual,7.0",
            ["Content"] = "哪哪——哪里来的妖魔鬼怪！胆胆胆敢恐——恐吓本魔王大人！信不信我——玄黄什么什么……糟糕，后面想不起来了！",
            ["ContentFR"] = "Q-Qui va là ?! Quelle abomination ose effrayer le grand Roi Démon ?! Je vais te réduire en poussière avec mon... mon... sort de... de truc sacré ! Mince, j’ai oublié la suite !",
            ["DialogueId"] = 51140005,
            ["GUID"] = "80060D12",
            ["LookAt"] = {
                [1] = "100001:n(701074)",
                },
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "100001:Talk03_End",
                },
            },
        [51140006] = {
            ["Camera"] = "763.383301,600.294922,831.858032,0.000046,-32.495926,-142.840744,35.000008,100000.0,false,DoNotOverride,7.0",
            ["Content"] = "竟然听得到我说话？太好了！惊扰二位非尾生有意之举，在此向二位致歉，还望海涵。",
            ["ContentFR"] = "Vous... vous pouvez m’entendre ? Quelle chance ! Je me nomme Weisheng. Je n’avais nullement l’intention de vous effrayer. Veuillez accepter mes plus sincères excuses.",
            ["DialogueId"] = 51140006,
            ["GUID"] = "80060D3C",
            ["SpeakNpcId"] = 701074,
            ["TalkActionId"] = {
                [1] = "200002:Afraid_End",
                },
            },
        [51140007] = {
            ["Camera"] = "-205.567871,-119.201172,110.475708,0.000172,0.0,5.771363,35.000015,187.02475,false,Manual,7.0",
            ["Content"] = "什么嘛，原来是无由生，你怎么突然冒出来，吓了我好一大跳……看在你道歉态度诚恳的份上，魔王大人就原谅你了。",
            ["ContentFR"] = "Oh... c’est juste un Wishen. Tu pourrais prévenir avant d’apparaître, non ? Tu m’as fait une de ces peurs... Bon, comme tu t’excuses correctement, le Roi Démon consent à te pardonner.",
            ["DialogueId"] = 51140007,
            ["GUID"] = "80060D66",
            ["Scripts"] = "SEQ\
{\
PARA{\
PlayAnimation{ActorId{200002},AnimationId{\"Alright_Start\"},Duration{1}},\
PlayFacial{ActorId{200002},FacialId{\"Unhappy02\"}}\
},\
PARA{\
PlayAnimation{ActorId{200002},AnimationId{\"Alright_End\"}},\
PlayFacial{ActorId{200002},FacialId{\"None\"}}\
}\
}",
            ["SpeakNpcId"] = 200002,
            },
        [51140008] = {
            ["Camera"] = "333.445312,-77.007812,119.176392,0.000049,3.105147,176.364456,35.0,100000.0,false,DoNotOverride,7.0",
            ["Content"] = "多谢二位大人不计小人过。在下拦路却是另有隐情，实不相瞒，在下有一要事……",
            ["ContentFR"] = "Je vous remercie infiniment de votre indulgence. Si je vous ai arrêtés, c’est parce que... j’ai une requête importante...",
            ["DialogueId"] = 51140008,
            ["GUID"] = "80060D90",
            ["LookAt"] = {
                [1] = "100001:n(100001)",
                },
            ["SpeakNpcId"] = 701074,
            },
        [51140009] = {
            ["Content"] = "（敏锐察觉到一丝不对劲，脚步偷偷向后挪了挪。）",
            ["ContentFR"] = "<I>Vous percevez quelque chose d’étrange et reculez discrètement d’un pas.</>",
            ["DialogueId"] = 51140009,
            ["GUID"] = "80060DBA",
            ["ImprPlusId"] = 1208,
            },
        [51140010] = {
            ["Content"] = "要我跑腿是吧？打扰了这就走！",
            ["ContentFR"] = "<I>Encore une course à faire ? Désolé, je passe mon tour !</>",
            ["DialogueId"] = 51140010,
            ["GUID"] = "80060DE4",
            ["ImprPlusId"] = 1206,
            },
        [51140011] = {
            ["Camera"] = "-455.513672,-227.362305,283.345703,0.000077,-20.494774,26.363897,35.0,100000.0,false,DoNotOverride,7.0",
            ["Content"] = "是委托的气息！小仆从！准备——诶？你怎么一副要逃跑的样子？！",
            ["ContentFR"] = "Je reconnaîtrais cette aura entre mille ! Une mission ! Petit larbin, prépare-toi— Hein ? Pourquoi tu recules comme si tu voulais t’enfuir ?!",
            ["DialogueId"] = 51140011,
            ["GUID"] = "80060E0E",
            ["LookAt"] = {
                [1] = "200002:n(100001)",
                [2] = "100001:n(200002)",
                },
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{100001},AnimationId{\"Shock02_Start\"},Duration{1}},\
PlayAnimation{ActorId{200002},AnimationId{\"Angry01_Start\"}}\
}",
            ["SpeakNpcId"] = 200002,
            },
        [51140012] = {
            ["Content"] = "（你正想离开，却觉得好像有什么轻飘飘的东西靠近了你，然后……）",
            ["ContentFR"] = "Alors que vous vous apprêtez à partir, quelque chose de léger s’approche silencieusement de vous...",
            ["DialogueId"] = 51140012,
            ["FacialId"] = {
                [1] = "100001:None",
                },
            ["GUID"] = "80060E38",
            ["IsBlack"] = 1,
            ["LookAt"] = {
                [1] = "200002:n(701074);100001:n(100001)",
                },
            ["SpeakNpcId"] = 0,
            },
        [51140013] = {
            ["Content"] = "（尾生蹦到了你的脚边。）",
            ["ContentFR"] = "Weisheng se matérialise doucement à vos pieds.",
            ["DialogueId"] = 51140013,
            ["GUID"] = "80060E62",
            ["IsBlack"] = 1,
            ["SpeakNpcId"] = 0,
            },
        [51140014] = {
            ["Camera"] = "29.751953,-50.233398,225.475708,0.000091,-14.99999,175.16095,35.000011,100000.0,false,DoNotOverride,7.0",
            ["Content"] = "在下只希望二位能<H>帮我寻找爱妻闲书下落</>，若是你不帮我，我就……我就一直跟着你，直到你答应为止！",
            ["ContentFR"] = "Je... je souhaite simplement que vous m’aidiez à <H>retrouver la trace de mon épouse, Xianshu</>. Si vous refusez... alors... alors je resterai à vos côtés. Je ne partirai pas tant que vous n’aurez pas accepté.",
            ["DialogueId"] = 51140014,
            ["GUID"] = "80060E8C",
            ["SpeakNpcId"] = 701074,
            ["TalkActionId"] = {
                [1] = "100001:Shock02_End",
                },
            },
        [51140015] = {
            ["Camera"] = "-194.939453,-70.49707,155.490723,0.000079,-19.495415,-7.838241,35.000011,100000.0,false,DoNotOverride,7.0",
            ["Content"] = "你——你这家伙耍赖！",
            ["ContentFR"] = "Hé ! C’est de la triche !",
            ["DialogueId"] = 51140015,
            ["FacialId"] = {
                [1] = "200002:Angry01",
                },
            ["GUID"] = "80060EB6",
            ["LookAt"] = {
                [1] = "200002:n(200002)",
                [2] = "100001:n(100001)",
                },
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Angry01_Start",
                },
            },
        [51140016] = {
            ["Camera"] = "11.114258,106.112305,84.475708,0.000119,19.999981,-140.838303,64.81044,100000.0,false,DoNotOverride,7.0",
            ["Content"] = "他们都看不到听不到我，你们是第一个回应我说话的。我晓得你们比旁人特殊，只有你们才能帮我！",
            ["ContentFR"] = "Personne d’autre ne peut me voir ni m’entendre. Vous êtes les premiers à m’avoir répondu. Je sais que vous êtes différents... Vous seuls pouvez m’aider !",
            ["DialogueId"] = 51140016,
            ["GUID"] = "80060EE0",
            ["SpeakNpcId"] = 701074,
            ["TalkActionId"] = {
                [1] = "200002:Angry01_End",
                },
            },
        [51140017] = {
            ["Camera"] = "-243.208984,-3.944336,191.368408,-0.0,-15.293783,-3.434053,35.000015,266.740662,false,Manual,7.0",
            ["Content"] = "……你说说看吧。",
            ["ContentFR"] = "... Parle. Dis-nous ce qu’il s’est passé.",
            ["DialogueId"] = 51140017,
            ["FacialId"] = {
                [1] = "100001:Uninterested01",
                },
            ["GUID"] = "80060F0A",
            ["LookAt"] = {
                [1] = "100001:n(701074)",
                },
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:ConfidentLR_Start",
                },
            },
        [51140018] = {
            ["Camera"] = "333.445312,-77.007812,119.176392,0.000049,3.105147,176.364456,35.0,100000.0,false,DoNotOverride,7.0",
            ["Content"] = "真……真的吗？你，你愿意帮我找我妻子了？",
            ["ContentFR"] = "V-Vraiment ? Vous accepteriez de m’aider à retrouver mon épouse ?",
            ["DialogueId"] = 51140018,
            ["GUID"] = "80060F34",
            ["SpeakNpcId"] = 701074,
            },
        [51140019] = {
            ["Camera"] = "29.751953,-50.233398,225.475708,0.000091,-14.99999,175.16095,35.000011,100000.0,false,DoNotOverride,7.0",
            ["Content"] = "好，好的！事情是这样的。我生前住蒹葭浦附近，靠做些小买卖维持生计，虽没赚到什么大钱，但日子过得倒也舒坦。",
            ["ContentFR"] = "A-Alors... voici mon histoire. De mon vivant, je vivais près de la Baie des Roseaux-Pâles. Je subsistais grâce à un modeste commerce. Ce n’était pas une grande fortune, mais notre vie était paisible.",
            ["DialogueId"] = 51140019,
            ["GUID"] = "80060F5E",
            ["SpeakNpcId"] = 701074,
            },
        [51140020] = {
            ["Camera"] = "29.751953,-50.233398,225.475708,0.000091,-14.99999,175.16095,35.000011,100000.0,false,DoNotOverride,7.0",
            ["Content"] = "本以为一生就这样平平淡淡过去了，直到我认识了爱妻闲书，我与她情投意合，很快便成了婚，婚后更是如胶似漆，伉俪情深……",
            ["ContentFR"] = "Je pensais finir mes jours ainsi... jusqu’à ce que je rencontre Xianshu. Nous étions faits l’un pour l’autre. Nous nous sommes mariés très vite, et notre union était emplie de tendresse...",
            ["DialogueId"] = 51140020,
            ["GUID"] = "80060F88",
            ["SpeakNpcId"] = 701074,
            },
        [51140021] = {
            ["Camera"] = "-125.262207,40.953125,171.12085,0.000126,-15.293818,-18.234081,35.000015,117.407356,false,Manual,3.0",
            ["Content"] = "说重点。",
            ["ContentFR"] = "Va à l’essentiel.",
            ["DialogueId"] = 51140021,
            ["FacialId"] = {
                [1] = "100001:Uninterested01",
                },
            ["GUID"] = "80060FB2",
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:ConfidentLRToExplainL_Start",
                },
            },
        [51140022] = {
            ["Camera"] = "121.967773,-57.251953,229.506348,0.000098,-10.894431,176.76123,35.0,100000.0,false,DoNotOverride,7.0",
            ["Content"] = "是是！只可惜天有不测风云，闲书不知为何得了一种怪病，痛苦异常。我便去求助枯荣阁里的药师为其治疗，药师为我开了些药剂。",
            ["ContentFR"] = "O-Oui ! Un jour, Xianshu fut frappée par une maladie étrange. Elle souffrait atrocement. Je suis allé demander de l’aide aux médecins du <H>Pavillon de l’Éphémère</>, qui lui préparèrent des remèdes.",
            ["DialogueId"] = 51140022,
            ["FinalCamera"] = "25.034668,-51.429688,210.820923,0.000096,-10.894411,176.561234,35.000008,100000.0,false,DoNotOverride,7.0",
            ["GUID"] = "80060FDC",
            ["SpeakNpcId"] = 701074,
            ["ToFinalCameraBlendTime"] = 5,
            },
        [51140023] = {
            ["Content"] = "那日后，我日日为她煎药试药，悉心照料，依旧不见好转，我便想着将她带去皓京问问有没有更好的药师治疗，谁知道……她一直不同意。",
            ["ContentFR"] = "Chaque jour, je faisais bouillir ses décoctions, je les goûtais moi-même, je veillais sur elle sans relâche... Mais son état ne s’améliorait pas. J’ai voulu l’emmener à Haojing pour consulter de meilleurs praticiens... Elle a refusé.",
            ["DialogueId"] = 51140023,
            ["GUID"] = "80061006",
            ["SpeakNpcId"] = 701074,
            ["TalkActionId"] = {
                [1] = "100001:ConfidentLRToExplainL_End",
                },
            },
        [51140024] = {
            ["Content"] = "她失踪那日，我终于耐不住性子，第一次凶了她……我直至今日都在后悔。",
            ["ContentFR"] = "Le jour de sa disparition... j’ai perdu patience. Pour la première fois, je lui ai parlé durement. Je le regrette encore aujourd’hui.",
            ["DialogueId"] = 51140024,
            ["GUID"] = "80061030",
            ["SpeakNpcId"] = 701074,
            },
        [51140025] = {
            ["Camera"] = "11.114258,106.112305,84.475708,0.000119,19.999981,-140.838303,64.81044,100000.0,false,DoNotOverride,7.0",
            ["Content"] = "我那天好说歹说，她终于点头愿意随我去看病。我便去铺子上拜托伙计看摊，和闲书约好晚上直接在码头见面，不耽误出发时间。",
            ["ContentFR"] = "Finalement, elle accepta de partir avec moi. Je confiai ma boutique à un employé, et nous avions convenu de nous retrouver le soir même au quai, afin de partir sans tarder.",
            ["DialogueId"] = 51140025,
            ["GUID"] = "8006105A",
            ["SpeakNpcId"] = 701074,
            },
        [51140026] = {
            ["Camera"] = "11.114258,106.112305,84.475708,0.000119,19.999981,-140.838303,64.81044,100000.0,false,DoNotOverride,7.0",
            ["Content"] = "可谁知道……我在码头等到天亮，却根本没等到她！",
            ["ContentFR"] = "Mais... je l’ai attendue jusqu’à l’aube. Elle n’est jamais venue.",
            ["DialogueId"] = 51140026,
            ["GUID"] = "80061084",
            ["SpeakNpcId"] = 701074,
            },
        [51140027] = {
            ["Camera"] = "-175.286621,11.260742,161.297852,0.000068,-19.495415,-35.038132,35.000008,100000.0,false,DoNotOverride,7.0",
            ["Content"] = "等一下等一下？她会不会是因为生病倒在家里了？",
            ["ContentFR"] = "Attends... Elle n’était pas simplement trop malade pour sortir ?",
            ["DialogueId"] = 51140027,
            ["GUID"] = "800610AE",
            ["LookAt"] = {
                [1] = "100001:n(200002)",
                },
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "100001:ConfidentLR_End",
                [2] = "200002:Think_Start",
                },
            },
        [51140028] = {
            ["Camera"] = "-25.474121,-45.555664,158.86438,0.000091,5.70566,175.16095,35.000008,100000.0,false,DoNotOverride,7.0",
            ["Content"] = "家中自然是看过了，但却没有找到一丝闲书的痕迹，她好像就这样，突然轻轻地挥一挥袖，从我的世界里消失了……",
            ["ContentFR"] = "J’ai fouillé la maison. Pas la moindre trace. Comme si elle avait disparu de ce monde d’un simple geste...",
            ["DialogueId"] = 51140028,
            ["GUID"] = "800610D8",
            ["SpeakNpcId"] = 701074,
            },
        [51140029] = {
            ["Camera"] = "-25.474121,-45.555664,158.86438,0.000091,5.70566,175.16095,35.000008,100000.0,false,DoNotOverride,7.0",
            ["Content"] = "我怕她是否会有一日归来，便一直在码头等她。那日下了很大的雨，浮星埠水位上涨，我却担心她要是此时回来找不到我，于是我便执意不走。",
            ["ContentFR"] = "Craignant qu’elle ne revienne, je suis resté au quai. Ce jour-là, la pluie était torrentielle, et les eaux du Quai-aux-Étoiles montaient sans cesse. Pourtant, je refusais de partir... Si elle revenait et que je n’étais pas là...",
            ["DialogueId"] = 51140029,
            ["GUID"] = "80061102",
            ["SpeakNpcId"] = 701074,
            },
        [51140030] = {
            ["Camera"] = "-205.567871,-119.201172,110.475708,0.000172,0.0,5.771363,35.000015,187.02475,false,Manual,7.0",
            ["Content"] = "为什么不去找地方避雨呢？你就傻傻等着吗？",
            ["ContentFR"] = "Pourquoi ne pas t’être mis à l’abri ?!",
            ["DialogueId"] = 51140030,
            ["FacialId"] = {
                [1] = "200002:Shock01",
                },
            ["GUID"] = "8006112C",
            ["LookAt"] = {
                [1] = "200002:n(701074)",
                },
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Think_End",
                },
            },
        [51140031] = {
            ["Camera"] = "333.445312,-77.007812,119.176392,0.000049,3.105147,176.364456,35.0,100000.0,false,DoNotOverride,7.0",
            ["Content"] = "那日洪水暴涨，我只能抓住一切随手能见着的东西……人力终不能胜天，我被水卷走，死不见全尸，幸而化作无由之身，游荡于此。",
            ["ContentFR"] = "La crue était trop violente. Je m’accrochais à tout ce que je pouvais... Mais l’homme ne peut lutter contre le Ciel. J’ai été emporté par les flots. Mon corps n’a jamais été retrouvé. Ainsi, je suis devenu un Wishen... errant ici depuis lors.",
            ["DialogueId"] = 51140031,
            ["GUID"] = "80061156",
            ["SpeakNpcId"] = 701074,
            },
        [51140032] = {
            ["Camera"] = "-272.66748,181.339844,236.877319,0.000052,-19.999928,-51.83622,27.780128,100000.0,false,DoNotOverride,7.0",
            ["Content"] = "你……你……诶……真是个笨蛋啊！",
            ["ContentFR"] = "T-Tu es vraiment... complètement idiot !",
            ["DialogueId"] = 51140032,
            ["FacialId"] = {
                [1] = "200002:Sad03",
                },
            ["GUID"] = "80061180",
            ["LookAt"] = {
                [1] = "200002:n(701074)",
                [2] = "100001:n(200002)",
                },
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Sigh_Start",
                },
            },
        [51140033] = {
            ["Camera"] = "333.445312,-77.007812,119.176392,0.000049,3.105147,176.364456,35.0,100000.0,false,DoNotOverride,7.0",
            ["Content"] = "鸿毛之命，此时不必再提及，我只求二位帮忙，去扶氏<H>枯荣阁</>那里帮我问问闲书的踪迹。",
            ["ContentFR"] = "Ma vie était aussi légère qu’un fétu de paille. N’en parlons plus. Je vous en prie... allez au <H>Pavillon de l’Éphémère</> et demandez s’ils ont des nouvelles de Xianshu.",
            ["DialogueId"] = 51140033,
            ["GUID"] = "800611AA",
            ["SpeakNpcId"] = 701074,
            },
        [51140034] = {
            ["Camera"] = "333.445312,-77.007812,119.176392,0.000049,3.105147,176.364456,35.0,100000.0,false,DoNotOverride,7.0",
            ["Content"] = "我妻子那病需要以药吊命，要是她回来了，想必第一时间一定会去找那里的药师开药的。",
            ["ContentFR"] = "Elle avait besoin de ses médicaments pour survivre. Si elle était revenue, c’est là qu’elle se serait rendue en premier.",
            ["DialogueId"] = 51140034,
            ["GUID"] = "800611D4",
            ["SpeakNpcId"] = 701074,
            },
        [51140035] = {
            ["Camera"] = "-174.360352,-43.571289,181.889648,0.000123,-15.293852,16.366138,35.000011,100000.0,false,DoNotOverride,7.0",
            ["Content"] = "知道了，我会帮你去问问，但结果如何我不能保证。",
            ["ContentFR"] = "Très bien. J’irai me renseigner. Mais je ne te promets rien.",
            ["DialogueId"] = 51140035,
            ["FacialId"] = {
                [1] = "100001:Smile01",
                },
            ["GUID"] = "800611FE",
            ["LookAt"] = {
                [1] = "100001:n(701074)",
                },
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Talk02R_Start",
                },
            },
        [51140036] = {
            ["Camera"] = "-25.474121,-45.555664,158.86438,0.000091,5.70566,175.16095,35.000008,100000.0,false,DoNotOverride,7.0",
            ["Content"] = "大恩大德，尾生来世必报！",
            ["ContentFR"] = "Votre bonté dépasse tout ce que je mérite... Si une autre vie m’est accordée, je vous rendrai cette dette.",
            ["DialogueId"] = 51140036,
            ["GUID"] = "80061228",
            ["SpeakNpcId"] = 701074,
            ["TalkActionId"] = {
                [1] = "701074:Wuyou_Disappear",
                },
            },
        [51140037] = {
            ["Camera"] = "-287.652344,948.660156,170.522461,0.000065,-3.551971,-72.129524,35.0,100000.0,false,DoNotOverride,7.0",
            ["Content"] = "（扶疏正痴痴望着一个方向发呆，连鱼龙也显得垂头丧气。）",
            ["ContentFR"] = "Fushu fixe le vide, plongée dans ses pensées. Même son Poisson-Dragon semble abattu.",
            ["DialogueId"] = 51140037,
            ["FinalCamera"] = "-170.042969,583.894531,146.733398,0.000065,-3.551971,-72.129524,35.0,100000.0,false,DoNotOverride,7.0",
            ["GUID"] = "80061252",
            ["Scripts"] = "PARA{\
MoveTo{ActorId{100001},MoveSpeed{100},TargetPoint{\"Targetpoint_20030901\"},Visibility{\"Show\"}},\
MoveTo{ActorId{200002},MoveSpeed{100},TargetPoint{\"Targetpoint_20030902\"},Visibility{\"Show\"}}\
}",
            ["SpeakNpcId"] = 0,
            ["TalkActionId"] = {
                [1] = "701075:Think_Start",
                },
            ["ToFinalCameraBlendTime"] = 4,
            },
        [51140038] = {
            ["Content"] = "是有什么心事吗？",
            ["ContentFR"] = "<I>Quelque chose te préoccupe ?</>",
            ["DialogueId"] = 51140038,
            ["GUID"] = "8006127C",
            ["ImprPlusId"] = 1209,
            },
        [51140039] = {
            ["Content"] = "（等她发现自己。）",
            ["ContentFR"] = "<I>Attendre qu’elle te remarque</>",
            ["DialogueId"] = 51140039,
