        [51140054] = {
            ["Content"] = "（你将诊籍递给扶疏，她仔细看了一会儿。）",
            ["ContentFR"] = "Vous tendez le registre à Fushu. Elle le parcourt longuement en silence.",
            ["DialogueId"] = 51140054,
            ["GUID"] = "8006151C",
            ["IsBlack"] = 1,
            ["SpeakNpcId"] = 0,
            },
        [51140055] = {
            ["Camera"] = "-81.537109,-85.851562,132.566406,0.000039,0.0,11.891485,18.482418,157.042984,false,Manual,1.41721",
            ["Content"] = "咦……这里面有个人……我曾在姐姐的日记里见过……",
            ["ContentFR"] = "Hmm... Cette personne... Je me souviens l’avoir vue mentionnée dans le journal de ma sœur...",
            ["DialogueId"] = 51140055,
            ["GUID"] = "80061546",
