            ["GUID"] = "800D2274",
            ["NextDialogue"] = 51151059,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:AgreeHead",
                },
            },
        [51151059] = {
            ["Camera"] = "90.658203,-126.199219,65.186523,0.000053,10.554213,85.36705,35.0,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "是你缠着锦鲤皎皎教你的吧。",
            ["ContentFR"] = "Tu as harcelé Luno, la carpe, pour qu’elle te l’apprenne, pas vrai ?",
            ["DialogueId"] = 51151059,
            ["FacialId"] = {
                [1] = "100001:Ahaha02",
                },
            ["GUID"] = "800D229E",
            ["NextDialogue"] = 51151060,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "200002:Confident_End",
                },
            },
        [51151060] = {
            ["Camera"] = "-38.962891,173.353027,130.660156,0.000067,-14.045956,-26.231251,35.0,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "你怎么知道的！",
            ["ContentFR"] = "Comment tu le sais ?!",
            ["DialogueId"] = 51151060,
            ["FacialId"] = {
                [1] = "200002:Shock01",
                },
            ["GUID"] = "800D22C8",
            ["NextDialogue"] = 51151061,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Shock03_Start",
                [2] = "100001:TilteHead_End",
                },
            },
        [51151061] = {
            ["Camera"] = "501.320312,-108.880371,210.521484,0.000008,-12.845597,152.96994,35.0,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "哈哈。你们来之前，我早就绕着这房子转了两圈，除了檐角又长了些青苔之外，并无其他异样。等你们准备好了，咱们就进去。",
            ["ContentFR"] = "Haha. Avant votre arrivée, j’ai déjà fait deux fois le tour du bâtiment. À part un peu plus de mousse sur les avant-toits, rien d’anormal. Quand vous serez prêts, on entre.",
            ["DialogueId"] = 51151061,
            ["FacialId"] = {
                [1] = "700373:CM_Smile01",
                [2] = "100001:None",
                [3] = "200002:None",
                },
            ["GUID"] = "800D22F2",
            ["LookAt"] = {
                [1] = "700373:n(100001)",
                [2] = "100001:n(700373)",
                [3] = "200002:n(700373)",
                },
            ["NextDialogue"] = 51151062,
            ["SpeakNpcId"] = 700373,
            ["TalkActionId"] = {
                [1] = "200002:Shock03_End",
                },
            },
        [51151062] = {
            ["Content"] = "好，我们走吧。",
            ["ContentFR"] = "Très bien. Allons-y.",
            ["DialogueId"] = 51151062,
            ["FacialId"] = {
                [1] = "100001:Smile01",
                },
            ["GUID"] = "800D231C",
            ["NextDialogue"] = 51151063,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:AgreeHead",
                [2] = "200002:Confident_Start",
                },
            },
        [51151063] = {
            ["Content"] = "勇气可嘉，不愧是我看中的人，我这就……咦？",
            ["ContentFR"] = "Voilà une belle assurance. Je savais que je ne m’étais pas trompé sur votre compte. Je vais donc... hein ?",
            ["DialogueId"] = 51151063,
            ["GUID"] = "800D2346",
            ["NextDialogue"] = 51151064,
            ["SpeakNpcId"] = 700373,
            ["TalkActionId"] = {
                [1] = "700373:Talk03_End",
                },
            },
        [51151064] = {
            ["Content"] = "等等，我好像……没带开门的钥匙……",
            ["ContentFR"] = "Attendez... ne me dites pas que... j’ai oublié la clé...",
            ["DialogueId"] = 51151064,
            ["FacialId"] = {
                [1] = "700373:CM_Idle",
                },
            ["GUID"] = "800D2370",
            ["LookAt"] = {
                [1] = "700373:n(700373)",
                },
            ["NextDialogue"] = 51151065,
            ["SpeakNpcId"] = 700373,
            ["TalkActionId"] = {
                [1] = "700373:Disagree",
                },
            },
        [51151065] = {
            ["Camera"] = "-75.279297,-3.990723,118.624023,0.000049,-9.845662,26.368061,35.0,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "你也太粗心大意啦，这下我们该怎么进去？",
            ["ContentFR"] = "Tu plaisantes ?! Et maintenant, on entre comment ?",
            ["DialogueId"] = 51151065,
            ["FacialId"] = {
                [1] = "200002:Angry01",
                },
            ["GUID"] = "800D239A",
            ["NextDialogue"] = 51151066,
            ["SpeakNpcId"] = 200002,
            },
        [51151066] = {
            ["Content"] = "（一阵阴风吹来。“吱呀”一声，那本该紧锁的门，不知为何竟大敞开来。乍一望去，宛如一张黑漆漆的饕餮大口，似乎随时会将你们吞入……）",
            ["ContentFR"] = "Une bourrasque glaciale surgit. Dans un long grincement — « <I>crrrreeeek</> » — la porte censée être verrouillée s’ouvre toute seule. Dans l’obscurité, elle ressemble à une immense gueule béante prête à vous engloutir...",
            ["DialogueId"] = 51151066,
            ["GUID"] = "800D23C4",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 51151067,
            },
        [51151067] = {
            ["Camera"] = "212.025391,71.061035,156.366211,0.000012,-5.445498,168.168427,35.0,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "鬼啊！！！闹鬼啦！！！",
            ["ContentFR"] = "Aaaah ! Un fantôme ! C’est vraiment hanté !",
            ["DialogueId"] = 51151067,
            ["FacialId"] = {
                [1] = "700373:CM_Shock01",
                },
            ["GUID"] = "800D23EE",
            ["NextDialogue"] = 51151068,
            ["Scripts"] = "CameraShake{FileName {\"FixSimple_CameraShake_Normal\"}}",
            ["SpeakNpcId"] = 700373,
            ["TalkActionId"] = {
                [1] = "700373:Shock_Start",
                [2] = "200002:Confident_End",
                },
            },
        [51151068] = {
            ["Content"] = "（在你们面前，肖阿壮扭头就跑，眨眼间便已经没了踪影……）",
            ["ContentFR"] = "Sous vos yeux, Xiao Azhuang se retourne et détale. En un clin d’œil, il a disparu.",
            ["DialogueId"] = 51151068,
            ["GUID"] = "800D2418",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 51151069,
            ["Scripts"] = "SetVisibility{ActorId{700373},Visibility{\"Hide\"}}",
            },
        [51151069] = {
            ["Camera"] = "-201.375,-40.395996,174.717773,0.000056,-11.445586,26.764484,35.0,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "不是……他……明明是他撺掇我们过来探险，这还没进去就被吓跑了？他今天在码头那样说话，我还以为他胆子很大呢！",
            ["ContentFR"] = "Attends... quoi ?! C’est lui qui nous a traînés ici, et il s’enfuit avant même d’entrer ?! Vu comment il parlait au quai, je le croyais courageux !",
            ["DialogueId"] = 51151069,
            ["GUID"] = "800D2442",
            ["LookAt"] = {
                [1] = "100001:n(200002)",
                [2] = "200002:n(100001)",
                },
            ["NextDialogue"] = 51151070,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Angry01_Start",
                },
            },
        [51151070] = {
            ["Camera"] = "90.658203,-126.199219,65.186523,0.000053,10.554213,85.36705,35.0,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "白，你好好想想。他如果真的胆子很大，又为什么一定要拉上别人和他一起探险呢？",
            ["ContentFR"] = "Réfléchis bien, Snow. S’il avait réellement autant de courage, aurait-il eu besoin d’entraîner d’autres personnes avec lui ?",
            ["DialogueId"] = 51151070,
            ["FacialId"] = {
                [1] = "100001:Ahaha02",
                },
            ["GUID"] = "800D246C",
            ["NextDialogue"] = 51151071,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Talk02_Start",
                [2] = "200002:Angry01_End",
                },
            },
        [51151071] = {
            ["Camera"] = "-38.962891,173.353027,130.660156,0.000067,-14.045956,-26.231251,35.0,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "是哦，这么说好像有些道理。小仆从，还是你观察仔细。那现在要怎么办，我们还进去吗？",
            ["ContentFR"] = "Ah... vu comme ça, c’est vrai que ça se tient. Petit larbin, tu observes bien. Alors... on fait quoi maintenant ? On entre quand même ?",
            ["DialogueId"] = 51151071,
            ["FacialId"] = {
                [1] = "200002:Think02",
                },
            ["GUID"] = "800D2496",
            ["NextDialogue"] = 51151072,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Think_Start",
                [2] = "100001:Talk02_End",
                },
            },
        [51151072] = {
            ["Camera"] = "90.658203,-126.199219,65.186523,0.000053,10.554213,85.36705,35.0,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "是不是需要展现一下我对华胥的了解了？华胥有句俗语，叫……来都来了。",
            ["ContentFR"] = "Peut-être est-ce le moment de montrer que je connais aussi Huaxu. Il y a un dicton ici : « Puisqu’on est déjà là... »",
            ["DialogueId"] = 51151072,
            ["FacialId"] = {
                [1] = "100001:Smile01",
                },
            ["GUID"] = "800D24C0",
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Talk01_Start",
                },
            },
        [51151073] = {
            ["Camera"] = "-54.057632,-5.761841,316.41864,0.00005,-11.218168,90.395935,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "仓库里怎么都是游荡的无由生……他们好像在守护着最里面的什么东西？",
            ["ContentFR"] = "Pourquoi y a-t-il autant de Wishen qui errent dans l’entrepôt... ? On dirait qu’ils protègent quelque chose, tout au fond.",
            ["DialogueId"] = 51151073,
            ["FacialId"] = {
                [1] = "200002:Doubt01",
                },
            ["GUID"] = "800D24EA",
            ["NextDialogue"] = 51151074,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:PointF_Start",
                [2] = "100001:Think_Start",
                },
            },
        [51151074] = {
            ["Camera"] = "-65.365799,-156.657349,145.755508,0.000201,-8.416945,79.202469,15.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "地上的痕迹，嗅嗅……香香的，好像是香料耶？怎么洒出来了，也是无由生捣的鬼吗？",
            ["ContentFR"] = "Et ces traces au sol... <I>snif snif...</> ça sent bon ! C’est de l’encens ? Pourquoi est-il répandu partout ? C’est encore un tour des Wishen ?",
            ["DialogueId"] = 51151074,
            ["FacialId"] = {
                [1] = "200002:Curious",
                },
            ["GUID"] = "800D2514",
            ["NextDialogue"] = 51151075,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:PointF_End",
                },
            },
        [51151075] = {
            ["Content"] = "看它们如此谨慎，想必被发现了会遭遇什么不好的事情吧，白，我们要谨慎前进了。",
            ["ContentFR"] = "À en juger par leur prudence, se faire repérer ne présagerait rien de bon. Snow, avançons avec prudence.",
            ["DialogueId"] = 51151075,
            ["FacialId"] = {
                [1] = "100001:Think01",
                },
            ["GUID"] = "800D253E",
            ["LookAt"] = {
                [1] = "100001:n(200002)",
                },
            ["SpeakNpcId"] = 100001,
            },
        [51151076] = {
            ["Content"] = "白，快蹲下来。",
            ["ContentFR"] = "Snow, baisse-toi. Vite.",
            ["DialogueId"] = 51151076,
            ["GUID"] = "800D2568",
            ["SpeakNpcId"] = 100001,
            },
        [51151077] = {
            ["Content"] = "又是香料，看起来通向更深的地方，哦！前面也有好多无由生！",
            ["ContentFR"] = "Encore de l’encens... Ça mène plus loin... Oh ! Il y a encore plein de Wishen devant !",
            ["DialogueId"] = 51151077,
            ["GUID"] = "800D2592",
            ["SpeakNpcId"] = 200002,
            },
        [51151078] = {
            ["Content"] = "这只无由生怎么绕来绕去的……要不趁它不注意，咱们一鼓作气冲过去？",
            ["ContentFR"] = "Pourquoi celui-là tourne en rond comme ça... ? On tente de passer en force pendant qu’il regarde ailleurs ?",
            ["DialogueId"] = 51151078,
            ["GUID"] = "800D25BC",
            ["SpeakNpcId"] = 200002,
            },
        [51151079] = {
            ["Camera"] = "-595.896667,244.201172,274.973206,0.000002,-17.388731,-24.245804,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "（仓库的尽头，香料箱上，一只魔灵正把头埋在盒子里，忘情地吸着香料……）",
            ["ContentFR"] = "Tout au bout, sur des caisses d’encens, un Géniemon a la tête plongée dans un coffret, absorbant le parfum avec délectation...",
            ["DialogueId"] = 51151079,
            ["GUID"] = "800D25E6",
            ["NextDialogue"] = 51151080,
            },
        [51151080] = {
            ["Camera"] = "172.276642,-106.706421,224.133514,0.000011,-22.388477,154.355042,30.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "哼哼……可算被我们抓到了，快束手就擒吧，你这小贼！",
            ["ContentFR"] = "Héhé... On t’a enfin attrapé ! Allez, rends-toi gentiment, petit voleur !",
            ["DialogueId"] = 51151080,
            ["FacialId"] = {
                [1] = "200002:Confident02",
                },
            ["GUID"] = "800D2610",
            ["LookAt"] = {
                [1] = "200002:n(700377)",
                [2] = "100001:n(700377)",
                },
            ["NextDialogue"] = 51151081,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Confident_Start",
                [2] = "100001:Talk03_Start",
                },
            },
        [51151081] = {
            ["Camera"] = "-595.896667,244.201172,274.973206,0.000002,-17.388731,-24.245804,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "啾？",
            ["ContentFR"] = "<I>Piou ?</>",
            ["DialogueId"] = 51151081,
            ["GUID"] = "800D263A",
            ["NextDialogue"] = 51151125,
            ["Scripts"] = "PlayNormalSound{EventPath{\"event:/sfx/common/story/east/vo_hello\"},PlayAs2D{true}}",
            ["SpeakNpcId"] = 700377,
            },
        [51151082] = {
            ["Content"] = "灵神大人，哼生这便来为你护驾！何方鼠贼，瞒天过海只为靠近我们灵神大人！",
            ["ContentFR"] = "Seigneur spirituel ! Hengsheng se tient prêt à assurer votre protection ! Qui ose se faufiler jusqu’à notre seigneur sous couvert d’illusions ?",
            ["DialogueId"] = 51151082,
            ["GUID"] = "800D2664",
            ["NextDialogue"] = 51151083,
            ["Scripts"] = "PARA{\
SetVisibility{ActorId{700375},Visibility{\"Show\"}},\
SetVisibility{ActorId{700376},Visibility{\"Show\"}}\
}",
            ["SpeakNpcId"] = 700375,
            ["TalkActionId"] = {
                [1] = "700376:Wuyou_Born",
                [2] = "700375:Wuyou_Born",
                },
            },
        [51151083] = {
            ["Content"] = "哈生也来助你！",
            ["ContentFR"] = "Hasheng vient en renfort !",
            ["DialogueId"] = 51151083,
            ["GUID"] = "800D268E",
            ["NextDialogue"] = 51151084,
            ["SpeakNpcId"] = 700376,
            },
        [51151084] = {
            ["Content"] = "啾啾啾~~~",
            ["ContentFR"] = "<I>Piou piou piou~~~</>",
            ["DialogueId"] = 51151084,
            ["GUID"] = "800D26B8",
            ["NextDialogue"] = 51151126,
            ["Scripts"] = "PlayNormalSound{EventPath{\"event:/sfx/common/story/east/vo_happy\"},PlayAs2D{true}}",
            ["SpeakNpcId"] = 700377,
            ["TalkActionId"] = {
                [1] = "200002:Confident_End",
                },
            },
        [51151085] = {
            ["Camera"] = "172.276642,-106.706421,224.133514,0.000011,-22.388477,154.355042,30.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "不对不对，这分明是魔灵呀？怎么变成灵神大人了？",
            ["ContentFR"] = "Attends... ce n’est qu’un Géniemon, non ? Depuis quand est-il devenu un « Seigneur spirituel » ?",
            ["DialogueId"] = 51151085,
            ["FacialId"] = {
                [1] = "200002:Shock01",
                },
            ["GUID"] = "800D26E2",
            ["NextDialogue"] = 51151086,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Angry02_Start",
                },
            },
        [51151086] = {
            ["Camera"] = "-595.896667,244.201172,274.973206,0.000002,-17.388731,-24.245804,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "恶徒休要胡言，感受到这空气之中飘散的狂风了吗？这就是灵神大人的威力！",
            ["ContentFR"] = "Misérables, cessez vos balivernes ! Ne sentez-vous donc pas le vent qui parcourt l’air ? Voilà la puissance de notre seigneur !",
            ["DialogueId"] = 51151086,
            ["GUID"] = "800D270C",
            ["NextDialogue"] = 51151087,
            ["SpeakNpcId"] = 700375,
            ["TalkActionId"] = {
                [1] = "200002:Angry02_End",
                [2] = "700375:Wuyou_Agree",
                },
            },
        [51151087] = {
            ["Content"] = "（的确有些凉风在你的脖颈间转圈，你只觉得有点痒，忍不住咳嗽了一声。）",
            ["ContentFR"] = "Un léger courant d’air frais effleure votre nuque. Cela vous chatouille légèrement, et vous toussez malgré vous.",
            ["DialogueId"] = 51151087,
            ["GUID"] = "800D2736",
            ["NextDialogue"] = 51151088,
            },
        [51151088] = {
            ["Camera"] = "172.276642,-106.706421,224.133514,0.000011,-22.388477,154.355042,30.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "什么嘛，分明只是一只会些风魔法的魔灵罢了。快老实交代，你们为什么要占据别人的仓库，还让这里传出闹鬼的传言？",
            ["ContentFR"] = "Franchement… c’est juste un Géniemon qui maîtrise un peu la magie du vent. Allez, avouez : pourquoi occuper l’entrepôt de quelqu’un d’autre et faire croire que l’endroit est hanté ?",
            ["DialogueId"] = 51151088,
            ["FacialId"] = {
                [1] = "200002:Guilty",
                },
            ["GUID"] = "800D2760",
            ["NextDialogue"] = 51151089,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Helpless01_Start",
                },
            },
        [51151089] = {
            ["Camera"] = "-595.896667,244.201172,274.973206,0.000002,-17.388731,-24.245804,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "啾啾！吖~吖吖！",
            ["ContentFR"] = "<I>Piou piou ! Pia~ pia pia !</>",
            ["DialogueId"] = 51151089,
            ["FacialId"] = {
                [1] = "200002:None",
                },
            ["GUID"] = "800D278A",
            ["NextDialogue"] = 51151127,
            ["Scripts"] = "SEQ{\
PlayNormalSound{EventPath{\"event:/sfx/common/story/east/vo_hello\"},PlayAs2D{true}},\
PlayNormalSound{EventPath{\"event:/sfx/common/story/east/vo_hello\"},PlayAs2D{true}},\
PlayNormalSound{EventPath{\"event:/sfx/common/story/east/vo_hello\"},PlayAs2D{true}}\
}",
            ["SpeakNpcId"] = 700377,
            ["TalkActionId"] = {
                [1] = "200002:Helpless01_End",
                },
            },
        [51151090] = {
            ["Content"] = "灵神大人说，这里已经被它占领了，请你们速速离去，不然就别怪我们不客气了！",
            ["ContentFR"] = "Notre seigneur déclare que ce lieu est désormais sous son autorité. Partez immédiatement, ou nous passerons aux choses sérieuses !",
            ["DialogueId"] = 51151090,
            ["GUID"] = "800D27B4",
            ["NextDialogue"] = 51151091,
            ["SpeakNpcId"] = 700376,
            ["TalkActionId"] = {
                [1] = "700376:Wuyou_Disagree",
                },
            },
        [51151091] = {
            ["Camera"] = "23.355988,-69.482788,172.744568,0.000006,-14.788239,163.1539,30.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "不客气……你确定吗？",
            ["ContentFR"] = "Passer aux choses sérieuses... vous en êtes sûrs ?",
            ["DialogueId"] = 51151091,
            ["FacialId"] = {
                [1] = "100001:Ahaha02",
                },
            ["GUID"] = "800D27DE",
            ["NextDialogue"] = 51151092,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Talk03ToTalkL_Start",
                },
            },
        [51151092] = {
            ["Content"] = "（你看了一眼自己腰间的武器……）",
            ["ContentFR"] = "(Vous jetez un regard à l’arme à votre ceinture.)",
            ["DialogueId"] = 51151092,
            ["GUID"] = "800D2808",
            ["NextDialogue"] = 51151093,
            },
        [51151093] = {
            ["Camera"] = "-595.896667,244.201172,274.973206,0.000002,-17.388731,-24.245804,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "吖吖……",
            ["ContentFR"] = "<I>Pia pia...</>",
            ["DialogueId"] = 51151093,
            ["GUID"] = "800D2832",
            ["NextDialogue"] = 51151128,
            ["Scripts"] = "PlayNormalSound{EventPath{\"event:/sfx/common/story/east/vo_upset\"},PlayAs2D{true}}",
            ["SpeakNpcId"] = 700377,
            ["TalkActionId"] = {
                [1] = "100001:Talk03ToTalkL_End",
                },
            },
        [51151094] = {
            ["Content"] = "灵神大人？此话怎讲？你为何让我们退下，不要招惹他们？",
            ["ContentFR"] = "Seigneur ? Pourquoi nous ordonner de battre en retraite ?",
            ["DialogueId"] = 51151094,
            ["GUID"] = "800D285C",
            ["NextDialogue"] = 51151095,
            ["SpeakNpcId"] = 700375,
            },
        [51151095] = {
            ["Content"] = "莫非……这两位是比灵神大人还要强大的存在？是我哈生有眼不识泰山了？",
            ["ContentFR"] = "Serait-ce… des êtres encore plus puissants que notre divinité ? Hasheng aurait-il manqué de discernement ?",
            ["DialogueId"] = 51151095,
            ["GUID"] = "800D2886",
            ["NextDialogue"] = 51151096,
            ["SpeakNpcId"] = 700376,
            },
        [51151096] = {
            ["Camera"] = "-595.896667,244.201172,274.973206,0.000002,-17.388731,-24.245804,35.0,100000.0,false,DoNotOverride,2.8",
            ["DialogueId"] = 51151096,
            ["DialoguePanelType"] = "None",
            ["Duration"] = 0.5,
            ["FacialId"] = {
                [1] = "100001:None",
                [2] = "200002:None",
                },
            ["FinalDialogueId"] = 51151107,
            ["GUID"] = "800D28B0",
            ["NextOptions"] = {
                [1] = 51151097,
                [2] = 51151101,
                [3] = 51151105,
                },
            },
        [51151097] = {
            ["Content"] = "你为什么会出现在华胥？",
            ["ContentFR"] = "<I>Pourquoi es-tu apparu à Huaxu ?</>",
            ["DialogueId"] = 51151097,
            ["GUID"] = "800D28DA",
            ["NextDialogue"] = 51151098,
            },
        [51151098] = {
            ["Content"] = "啾啾~啾~~~",
            ["ContentFR"] = "<I>Piou piou piou~~~</>",
            ["DialogueId"] = 51151098,
            ["GUID"] = "800D2904",
            ["NextDialogue"] = 51151099,
            ["Scripts"] = "SEQ{\
PlayNormalSound{EventPath{\"event:/sfx/common/story/east/vo_hello\"},PlayAs2D{true}},\
PlayNormalSound{EventPath{\"event:/sfx/common/story/east/vo_happy\"},PlayAs2D{true}}\
}",
            ["SpeakNpcId"] = 700377,
            },
        [51151099] = {
            ["Content"] = "灵神大人说，它在原来的地方闻到了很香的味道，十分喜欢，就跟着味道一路来到了船上……",
            ["ContentFR"] = "Notre seigneur dit qu’il a perçu, dans son pays natal, une odeur délicieuse. Il a suivi ce parfum jusqu’à un navire...",
            ["DialogueId"] = 51151099,
            ["GUID"] = "800D292E",
            ["NextDialogue"] = 51151100,
            ["SpeakNpcId"] = 700375,
            },
        [51151100] = {
            ["Content"] = "所以这家伙是跟着织星客的船偷渡来的华胥！",
            ["ContentFR"] = "Donc il s’est introduit clandestinement à Huaxu à bord d’un vaisseau des Tisse-Étoiles !",
            ["DialogueId"] = 51151100,
            ["FacialId"] = {
                [1] = "200002:Doubt01",
                },
            ["GUID"] = "800D2958",
            ["NextDialogue"] = 51151096,
            ["SpeakNpcId"] = 200002,
            },
        [51151101] = {
            ["Content"] = "那为什么要霸占这里？",
            ["ContentFR"] = "<I>Et pourquoi occuper cet endroit précisément ?</>",
            ["DialogueId"] = 51151101,
            ["GUID"] = "800D2982",
            ["NextDialogue"] = 51151102,
            },
        [51151102] = {
            ["Content"] = "吖吖……啾！啾啾~",
            ["ContentFR"] = "<I>Pia pia... piou ! piou piou~</>",
            ["DialogueId"] = 51151102,
            ["GUID"] = "800D29AC",
            ["NextDialogue"] = 51151103,
            ["Scripts"] = "SEQ{\
PlayNormalSound{EventPath{\"event:/sfx/common/story/east/vo_hello\"},PlayAs2D{true}},\
PlayNormalSound{EventPath{\"event:/sfx/common/story/east/vo_hello\"},PlayAs2D{true}},\
PlayNormalSound{EventPath{\"event:/sfx/common/story/east/vo_hello\"},PlayAs2D{true}}\
}",
            ["SpeakNpcId"] = 700377,
            },
        [51151103] = {
            ["Content"] = "灵神大人说，这里有好闻的香料，没有不认识的面孔，没有凶巴巴的魔灵猎人，还有好兄弟无由生相随保护。",
            ["ContentFR"] = "Notre seigneur explique qu’ici, l’encens est agréable, il y a peu d’étrangers, aucun chasseur de Géniemon agressif, et des Wishen amicaux pour le protéger.",
            ["DialogueId"] = 51151103,
            ["GUID"] = "800D29D6",
            ["NextDialogue"] = 51151104,
            ["SpeakNpcId"] = 700376,
            },
        [51151104] = {
            ["Camera"] = "172.276642,-106.706421,224.133514,0.000011,-22.388477,154.355042,30.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "啊~所以这里所谓的闹鬼，只是你想占据这里不让普通人打扰，故意和无由生一起闹出来的。",
            ["ContentFR"] = "Ah~ donc cette histoire d’entrepôt hanté, c’était juste pour éloigner les gens et garder l’endroit pour toi, avec l’aide des Wishen.",
            ["DialogueId"] = 51151104,
            ["FacialId"] = {
                [1] = "200002:Confident01",
                },
            ["GUID"] = "800D2A00",
            ["NextDialogue"] = 51151096,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Confident_Start",
                },
            },
        [51151105] = {
            ["Content"] = "（闻闻香料。）",
            ["ContentFR"] = "<I>Vous humez l’encens.</>",
            ["DialogueId"] = 51151105,
            ["GUID"] = "800D2A2A",
            ["NextDialogue"] = 51151106,
            },
        [51151106] = {
            ["Camera"] = "172.276642,-106.706421,224.133514,0.000011,-22.388477,154.355042,30.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "嗅嗅……这香料和咱们投喂魔灵用的罐罐味道好像呀！难道这就是魔灵赖在这里的原因？",
            ["ContentFR"] = "<I>Snif snif... </>Ça sent exactement comme les petites friandises qu’on donne aux Géniemon ! Voilà pourquoi il refuse de partir !",
            ["DialogueId"] = 51151106,
            ["FacialId"] = {
                [1] = "200002:Think02",
                },
            ["GUID"] = "800D2A54",
            ["NextDialogue"] = 51151096,
            ["SpeakNpcId"] = 200002,
            },
        [51151107] = {
            ["Camera"] = "23.355988,-69.482788,172.744568,0.000006,-14.788239,163.1539,30.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "你们闹鬼的事情已经被百年春的人知道了，怕是再过几天就有人来抓你们了。",
            ["ContentFR"] = "Les gens d’Éternel Printemps sont déjà au courant de vos histoires de fantômes. Il est à craindre que, d’ici quelques jours, quelqu’un ne vienne vous arrêter.",
            ["DialogueId"] = 51151107,
            ["FacialId"] = {
                [1] = "100001:Angry01",
                [2] = "200002:None",
                },
            ["GUID"] = "800D2A7E",
            ["NextDialogue"] = 51151108,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Talk03ToTalkL_Start",
                },
            },
        [51151108] = {
            ["Camera"] = "-595.896667,244.201172,274.973206,0.000002,-17.388731,-24.245804,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "啾……吖……",
            ["ContentFR"] = "<I>Piou... pia...</>",
            ["DialogueId"] = 51151108,
            ["FacialId"] = {
                [1] = "100001:None",
                },
            ["GUID"] = "800D2AA8",
            ["NextDialogue"] = 51151109,
            ["Scripts"] = "PlayNormalSound{EventPath{\"event:/sfx/common/story/east/vo_upset\"},PlayAs2D{true}}",
            ["SpeakNpcId"] = 700377,
            ["TalkActionId"] = {
                [1] = "100001:Talk03ToTalkL_End",
                },
            },
        [51151109] = {
            ["Content"] = "什么？灵神大人，你让我们离开，你一个神来承担？",
            ["ContentFR"] = "Quoi ? Seigneur, vous voulez que nous partions et que vous restiez seul ?",
            ["DialogueId"] = 51151109,
            ["GUID"] = "800D2AD2",
            ["NextDialogue"] = 51151110,
            ["SpeakNpcId"] = 700375,
            ["TalkActionId"] = {
                [1] = "700375:Wuyou_Disagree",
                },
            },
        [51151110] = {
            ["Content"] = "不要啊，我们和灵神大人同生共死！哦不对……好像我们已经死掉了……",
            ["ContentFR"] = "Non ! Nous vivrons et mourrons ensemble ! ... Ah. Attends. On est déjà morts, non ?",
            ["DialogueId"] = 51151110,
            ["GUID"] = "800D2AFC",
            ["NextDialogue"] = 51151111,
            ["SpeakNpcId"] = 700376,
            ["TalkActionId"] = {
                [1] = "700376:Wuyou_Disagree",
                },
            },
        [51151111] = {
            ["Camera"] = "172.276642,-106.706421,224.133514,0.000011,-22.388477,154.355042,30.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我看你们就别在这里演什么无由生魔灵情深的戏码了，都收拾收拾快点离开这里吧。",
            ["ContentFR"] = "Bon, inutile de continuer cette pièce mélodramatique. Faites vos bagages et quittez les lieux.",
            ["DialogueId"] = 51151111,
            ["FacialId"] = {
                [1] = "200002:Syouganai01",
                },
            ["GUID"] = "800D2B26",
            ["NextDialogue"] = 51151112,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Helpless01_Start",
                },
            },
        [51151112] = {
            ["Camera"] = "-595.896667,244.201172,274.973206,0.000002,-17.388731,-24.245804,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "啾~",
            ["ContentFR"] = "<I>Piou~</>",
            ["DialogueId"] = 51151112,
            ["GUID"] = "800D2B50",
            ["NextDialogue"] = 51151113,
            ["Scripts"] = "PlayNormalSound{EventPath{\"event:/sfx/common/story/east/vo_hello\"},PlayAs2D{true}}",
            ["SpeakNpcId"] = 700377,
            ["TalkActionId"] = {
                [1] = "200002:Helpless01_End",
                },
            },
        [51151113] = {
            ["Content"] = "至于你……",
            ["ContentFR"] = "Quant à toi...",
            ["DialogueId"] = 51151113,
            ["FacialId"] = {
                [1] = "200002:Angry01",
                },
            ["GUID"] = "800D2B7A",
            ["NextDialogue"] = 51151114,
            ["SpeakNpcId"] = 200002,
            },
        [51151114] = {
            ["Camera"] = "23.355988,-69.482788,172.744568,0.000006,-14.788239,163.1539,30.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "给你两个选择，一是继续在华胥游荡，直到你混到一艘船上回到你的故乡，另一个选择是……",
            ["ContentFR"] = "Deux choix s’offrent à toi. Soit tu continues d’errer à Huaxu jusqu’à réussir à rentrer clandestinement dans ton pays, soit...",
            ["DialogueId"] = 51151114,
            ["FacialId"] = {
                [1] = "100001:Think01",
                },
            ["GUID"] = "800D2BA4",
            ["NextDialogue"] = 51151115,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Talk03ToTalkL_Start",
                },
            },
        [51151115] = {
            ["Content"] = "我这也有妙妙罐罐，和我走，怎么样？",
            ["ContentFR"] = "J’ai aussi des petites friandises. Tu viens avec moi ?",
            ["DialogueId"] = 51151115,
            ["FacialId"] = {
                [1] = "100001:Smile01",
                },
            ["GUID"] = "800D2BCE",
            ["NextDialogue"] = 51151116,
            ["SpeakNpcId"] = 100001,
            },
        [51151116] = {
            ["Camera"] = "-257.016357,106.369873,179.233536,0.000001,-9.588553,-21.443916,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "吖……",
            ["ContentFR"] = "<I>Pia...</>",
            ["DialogueId"] = 51151116,
            ["GUID"] = "800D2BF8",
            ["NextDialogue"] = 51151117,
            ["Scripts"] = "PlayNormalSound{EventPath{\"event:/sfx/common/story/east/vo_upset\"},PlayAs2D{true}}",
            ["SpeakNpcId"] = 700377,
            },
        [51151117] = {
            ["Content"] = "吖！",
            ["ContentFR"] = "<I>Pia !</>",
            ["DialogueId"] = 51151117,
            ["GUID"] = "800D2C22",
            ["NextDialogue"] = 51151118,
            ["Scripts"] = "PlayNormalSound{EventPath{\"event:/sfx/common/story/east/vo_happy\"},PlayAs2D{true}}",
            ["SpeakNpcId"] = 700377,
            },
        [51151118] = {
            ["Content"] = "看起来它同意跟我们走啦~",
            ["ContentFR"] = "On dirait qu’il accepte de nous suivre~ !",
            ["DialogueId"] = 51151118,
            ["FacialId"] = {
                [1] = "200002:Smile01",
                },
            ["GUID"] = "800D2C4C",
            ["NextDialogue"] = 51151119,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Excited01_Start",
                },
            ["TurnTo"] = {
                [1] = "200002:n(100001)",
                },
            },
        [51151119] = {
            ["Content"] = "灵神大人，相逢本是一场缘，若是今日你选择离开，我们自然也不宜久留，只求大人记得我们，有空再来找我们说说话！",
            ["ContentFR"] = "Seigneur, notre rencontre était sans doute le fruit du destin. Si vous partez aujourd’hui, nous n’avons plus lieu de rester. Souvenez-vous simplement de nous... et revenez nous parler quand vous le pourrez.",
            ["DialogueId"] = 51151119,
            ["GUID"] = "800D2C76",
            ["NextDialogue"] = 51151120,
            ["SpeakNpcId"] = 700375,
            ["TalkActionId"] = {
                [1] = "700375:Wuyou_Agree",
                },
            },
        [51151120] = {
            ["Content"] = "大人……呜呜……可千万不要忘了我们啊，如果没有你，我们都不知道该和谁聊天了……",
            ["ContentFR"] = "Seigneur... <I>snif...</> Ne nous oubliez pas... sans vous, nous ne saurions même plus à qui parler...",
            ["DialogueId"] = 51151120,
            ["GUID"] = "800D2CA0",
            ["NextDialogue"] = 51151121,
            ["SpeakNpcId"] = 700376,
            ["TalkActionId"] = {
                [1] = "700376:Wuyou_Disagree",
                },
            },
        [51151121] = {
            ["Content"] = "吖吖……",
            ["ContentFR"] = "<I>Pia pia...</>",
            ["DialogueId"] = 51151121,
            ["GUID"] = "800D2CCA",
            ["Scripts"] = "PlayNormalSound{EventPath{\"event:/sfx/common/story/east/vo_upset\"},PlayAs2D{true}}",
            ["SpeakNpcId"] = 700377,
            },
        [51151122] = {
            ["Content"] = "（你就这么看着一个魔灵和两个无由生相拥而泣，互相把不存在的眼泪抹在对方身上，等了好久，直到将哼哈二将送至门外……）",
            ["ContentFR"] = "Vous assistez à une scène pour le moins improbable : un Géniemon et deux Wishen s’enlacent en pleurant, essuyant des larmes inexistantes sur les joues les uns des autres. Longtemps après, vous accompagnez enfin Hengsheng et Hasheng jusqu’à la porte.",
            ["DialogueId"] = 51151122,
            ["GUID"] = "800D2CF4",
            },
        [51151123] = {
            ["Content"] = "呼~可算把两位无由生送走了，想不到这些无由生还挺有情有义的嘛……接下来就轮到……",
            ["ContentFR"] = "<I>Pfiou~</> Voilà qui est fait. Je ne pensais pas que des Wishen pouvaient être aussi loyaux... Et maintenant...",
            ["DialogueId"] = 51151123,
            ["GUID"] = "800D2D1E",
            ["NextDialogue"] = 51151124,
            ["SpeakNpcId"] = 200002,
            },
        [51151124] = {
            ["Content"] = "小仆从，你带妙妙罐罐了吗？试试投喂这只魔灵吧！",
            ["ContentFR"] = "Petit larbin, tu as apporté les Délices Yum ? Essaie de nourrir le Géniemon !",
            ["DialogueId"] = 51151124,
            ["GUID"] = "800D2D48",
            ["SpeakNpcId"] = 200002,
            },
        [51151125] = {
            ["Content"] = "（这只魔灵似乎对你们的到来看起来有些疑惑。）",
            ["ContentFR"] = "Ce Géniemon semble quelque peu déconcerté par votre arrivée.",
            ["DialogueId"] = 51151125,
            ["GUID"] = "800D263B",
            ["NextDialogue"] = 51151082,
            },
        [51151126] = {
            ["Content"] = "（这只魔灵明显意识到了你们的来意，但因有无由生相助而显得十分得意。）",
            ["ContentFR"] = "Ce Géniemon a manifestement compris vos intentions, mais l’aide des Wishen le rend particulièrement satisfait de lui.",
            ["DialogueId"] = 51151126,
            ["GUID"] = "800D26B9",
            ["NextDialogue"] = 51151085,
            },
        [51151127] = {
            ["Content"] = "（咿咿呀呀说了一大堆，完全听不懂……）",
            ["ContentFR"] = "Le Géniemon babille longuement... impossible d’en comprendre le moindre mot.",
            ["DialogueId"] = 51151127,
            ["GUID"] = "800D278B",
            ["NextDialogue"] = 51151090,
            },
        [51151128] = {
            ["Content"] = "(它似乎有些害怕？）",
            ["ContentFR"] = "Il semble… un peu effrayé ?",
            ["DialogueId"] = 51151128,
            ["GUID"] = "800D2833",
            ["NextDialogue"] = 51151094,
            },
        [51151129] = {
            ["Content"] = "是说百年春角落那间仓库吗？那里不是早就租给天岚先生做供货仓库了吗？为何现在过来提起？",
            ["ContentFR"] = "Tu parles de l’entrepôt au fond d’Éternel Printemps ? Il n’a pas été loué à Monsieur Tianlan comme dépôt de marchandises ? Pourquoi cette question maintenant ?",
            ["DialogueId"] = 51151129,
            ["GUID"] = "800D2D49",
            ["SpeakNpcId"] = 700370,
            },
        [51151201] = {
            ["Camera"] = "368.707031,55.0,181.27832,0.0001,-12.598782,-171.164566,25.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "是白魔王大人和她忠诚的有龙氏随从！你们来找我玩啦！",
            ["ContentFR"] = "Hé, mais c’est le Roi Démon et {性别:son fidèle Descendant draconique|sa fidèle Descendante draconique} ! Vous êtes venus jouer avec moi ?",
            ["DialogueId"] = 51151201,
            ["GUID"] = "800D39EA",
            ["NextDialogue"] = 51151202,
            ["Scripts"] = "SEQ{\
PARA{\
LookAt{LookAtDescription{\"200002:n(900012)\"}}, \
LookAt{LookAtDescription{\"100001:n(900012)\"}},\
PlayAnimation{ActorId{900012},AnimationId{\"Talk02_Start\"}},\
LookAt{LookAtDescription{\"900012:n(200002)\"}}\
},\
LookAt{_delay{1},LookAtDescription{\"900012:n(100001)\"}}\
}",
            ["SpeakNpcId"] = 900012,
            },
        [51151202] = {
            ["Content"] = "“她忠诚的有龙氏随从”不配拥有自己的姓名吗？",
            ["ContentFR"] = "« {性别:Son fidèle Descendant draconique|Sa fidèle Descendante draconique} » n’a donc pas droit à son propre nom ?",
            ["DialogueId"] = 51151202,
            ["GUID"] = "800D3A14",
            ["NextDialogue"] = 51151203,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Talk01_Start",
                },
            },
        [51151203] = {
            ["Content"] = "当然是开玩笑的啦，{nickname}也是锦鲤皎皎的好朋友！你的角红红的一只，像枫叶，很特别。我很羡慕这样的角呢。",
            ["ContentFR"] = "Haha, je sais, je plaisantais ! {nickname} est bien sûr {性别:un grand ami|une grande amie} de Luno, la carpe ! Et regarde cette corne rouge, là... on dirait une feuille d’érable, c’est si joli. Je t’envie tellement !",
            ["DialogueId"] = 51151203,
            ["FacialId"] = {
                [1] = "900012:Smile02",
                },
            ["GUID"] = "800D3A3E",
            ["NextDialogue"] = 51151204,
            ["SpeakNpcId"] = 900012,
            ["TalkActionId"] = {
                [1] = "100001:Talk01_End",
                [2] = "900012:Talk02_End",
                },
            },
        [51151204] = {
            ["Camera"] = "368.707031,55.0,181.27832,0.0001,-12.598782,-171.164566,25.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "说起来，锦鲤皎皎，这个高高的、装满小球的机器是什么？",
            ["ContentFR"] = "Luno, la carpe... cette grande machine pleine de petites sphères, c’est quoi exactement ?",
            ["DialogueId"] = 51151204,
            ["FacialId"] = {
                [1] = "900012:None",
                },
            ["FinalCamera"] = "368.707031,55.0,181.27832,0.000102,5.401252,-149.163544,25.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "800D3A68",
            ["NextDialogue"] = 51151205,
            ["SpeakNpcId"] = 200002,
            ["ToFinalCameraBlendTime"] = 1,
            },
        [51151205] = {
            ["Camera"] = "277.509766,14.723633,155.932617,0.000082,-10.198612,-178.573135,25.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "不愧是火眼金睛的白魔王大人，一眼就能看出好东西！这可是本皎皎做生意的独家秘诀。",
            ["ContentFR"] = "Ah, quel œil, Roi Démon ! Tu repères les bonnes choses en un clin d’œil ! Et ça, c’est mon petit secret pour faire des affaires !",
            ["DialogueId"] = 51151205,
            ["FacialId"] = {
                [1] = "900012:Confident01",
                },
            ["GUID"] = "800D3A92",
            ["LookAt"] = {
                [1] = "900012:n(200002)",
                },
            ["NextDialogue"] = 51151206,
            ["SpeakNpcId"] = 900012,
            ["TalkActionId"] = {
                [1] = "900012:Excited01_Start",
                },
            },
        [51151206] = {
            ["Content"] = "我特意找一个机枢派的叫公、公什么的师傅定制了这套福运蛋机。只要往里面投入代币，它就会给你随机吐小奖品出来！",
            ["ContentFR"] = "J’ai fait appel à un artisan de la Secte Jishu — un certain Maître Gong... enfin, Gong-quelque-chose — pour me fabriquer cette machine à Œufs porte-bonheur. Tu insères un jeton, et hop, elle recrache un petit prix au hasard !",
            ["DialogueId"] = 51151206,
            ["GUID"] = "800D3ABC",
            ["NextDialogue"] = 51151207,
            ["SpeakNpcId"] = 900012,
            ["TalkActionId"] = {
                [1] = "900012:Excited01_End",
                },
            },
        [51151207] = {
            ["Camera"] = "83.419922,-2.439453,100.824219,0.000082,-6.798552,-173.972046,25.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "随机性才是挣钱的诀窍——这是本皎皎某天向白龙神君大人祈祷时，一下子福至心灵想出来的。怎么样，是不是天才般的想法？",
            ["ContentFR"] = "Le hasard, voilà la clé du profit ! Cette idée m’est venue comme une illumination, un jour où je priais le Seigneur Dragon d’Argent. Alors ? Avoue que c’est une idée de génie !",
            ["DialogueId"] = 51151207,
            ["GUID"] = "800D3AE6",
            ["LookAt"] = {
                [1] = "900012:n(900012)",
                },
            ["NextDialogue"] = 51151208,
            ["SpeakNpcId"] = 900012,
            ["TalkActionId"] = {
                [1] = "900012:Excited02_Start",
                },
            },
        [51151208] = {
            ["Camera"] = "-57.599609,-59.527832,146.118164,0.000087,-5.198607,48.427074,25.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "那你的生意好吗？",
            ["ContentFR"] = "Et... les affaires marchent bien ?",
            ["DialogueId"] = 51151208,
            ["GUID"] = "800D3B10",
            ["NextDialogue"] = 51151209,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "900012:Excited02_End",
                [2] = "100001:Talk02_Start",
                },
            },
        [51151209] = {
            ["Camera"] = "83.419922,-2.439453,100.824219,0.000082,-6.798552,-173.972046,25.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "……呜，一般。",
            ["ContentFR"] = "... Mmh. Pas vraiment.",
            ["DialogueId"] = 51151209,
            ["FacialId"] = {
                [1] = "900012:Syouganai01",
                },
            ["GUID"] = "800D3B3A",
            ["NextDialogue"] = 51151210,
            ["SpeakNpcId"] = 900012,
            ["TalkActionId"] = {
                [1] = "900012:DisagreeHead",
                [2] = "100001:Talk02_End",
                },
            },
        [51151210] = {
            ["Content"] = "因为这个想法太新潮了，所以到现在连机器的本钱还没挣回来。大概这就是高手常常落寞吧。",
            ["ContentFR"] = "L’idée est sans doute trop avant-gardiste. Je n’ai même pas encore récupéré le coût de la machine. Les génies sont souvent incompris, après tout.",
            ["DialogueId"] = 51151210,
            ["FacialId"] = {
                [1] = "900012:Sad03",
                },
            ["GUID"] = "800D3B64",
            ["NextDialogue"] = 51151211,
            ["SpeakNpcId"] = 900012,
            ["TalkActionId"] = {
                [1] = "900012:Shy03_Start",
                },
            },
        [51151211] = {
            ["Content"] = "如果你们在烟津渡捡到什么太虚符文呀、齿轮呀一类的玩意儿，可以用它来抽福运蛋机。",
            ["ContentFR"] = "Si vous trouvez dans le Port-des-Brumes des Runes de Taixu, des engrenages ou ce genre de bricoles, vous pourrez les utiliser pour tenter votre chance à la machine.",
            ["DialogueId"] = 51151211,
            ["FacialId"] = {
                [1] = "900012:None",
                },
            ["GUID"] = "800D3B8E",
            ["NextDialogue"] = 51151212,
            ["SpeakNpcId"] = 900012,
            },
        [51151212] = {
            ["Content"] = "这些福运蛋里的小垃圾……咳咳，不对，是小奖品！你们就不客气地拿走，当做是本皎皎的一片心意吧！",
            ["ContentFR"] = "Et ces petits déchets... euh, pardon, ces petits lots ! Prenez-les sans hésiter. Considérez-ça comme un cadeau de ma part !",
            ["DialogueId"] = 51151212,
            ["GUID"] = "800D3BB8",
            ["SpeakNpcId"] = 900012,
            ["TalkActionId"] = {
                [1] = "900012:Shy03_End",
                },
            },
        [51151301] = {
            ["Content"] = "是{nickname}和白魔王大人，你们来找我玩啦！今天的福运蛋又上新了新款式，要不要来扭一发试试？",
            ["ContentFR"] = "Oh ! C’est {nickname} et le Roi Démon ! Vous venez encore jouer avec moi ? J’ai de nouveaux Œufs porte-bonheur aujourd’hui... ça vous tente d’en essayer ?",
            ["DialogueId"] = 51151301,
            ["GUID"] = "800D4A52",
            ["NextOptions"] = {
                [1] = 51151302,
                [2] = 51151307,
                },
            ["SpeakNpcId"] = 900012,
            ["TalkActionId"] = {
                [1] = "900012:Explain01_Start",
                },
            },
        [51151302] = {
            ["Content"] = "聊聊锦鲤皎皎的梦想。",
            ["ContentFR"] = "<I>Demander quels sont ses rêves</>",
            ["DialogueId"] = 51151302,
            ["GUID"] = "800D4A7C",
            ["NextDialogue"] = 51151303,
            },
        [51151303] = {
            ["Content"] = "我呀，以前只是个普普通通的皎皎，每天最大的梦想不过是怎么从那些抠门织星客手中多抢下来几个单子，直到白魔王大人的出现改变了这一切——",
            ["ContentFR"] = "Moi, tu sais... avant, je n’étais qu’une Luno tout ce qu’il y a de plus ordinaire.\
Chaque jour, mon plus grand rêve, c’était simplement de réussir à grappiller quelques commandes de plus à ces radins de Tisse-Étoiles. Et puis le Roi Démon est arrivé... Et là, tout a changé !",
            ["DialogueId"] = 51151303,
            ["GUID"] = "800D4AA6",
            ["NextDialogue"] = 51151304,
            ["SpeakNpcId"] = 900012,
            ["TalkActionId"] = {
                [1] = "900012:Explain01_End",
                },
            },
        [51151304] = {
            ["Content"] = "现在的我已经不再是昨日的我了！我要成为青史留名的织星客，带领皎皎一族走向辉煌！",
            ["ContentFR"] = "Aujourd’hui, je ne suis plus celle d’hier ! Je vais devenir une Tisse-Étoiles dont le nom restera gravé dans l’histoire, et conduire tout le peuple des Luno vers une grande renaissance !",
            ["DialogueId"] = 51151304,
            ["GUID"] = "800D4AD0",
            ["NextDialogue"] = 51151305,
            ["SpeakNpcId"] = 900012,
            ["TalkActionId"] = {
                [1] = "900012:Excited02_Start",
                },
            },
        [51151305] = {
            ["Content"] = "以后白魔王大人的宫殿旁边，一定也有本皎皎豪华商铺的一席之地！",
            ["ContentFR"] = "Un jour, juste à côté du palais du Roi Démon, il y aura forcément une place réservée à la somptueuse boutique de Luno, la carpe !",
            ["DialogueId"] = 51151305,
            ["GUID"] = "800D4AFA",
            ["NextDialogue"] = 51151306,
            ["SpeakNpcId"] = 900012,
            },
        [51151306] = {
            ["Content"] = "这是约定和梦想！你们就等着瞧吧，我一定会做到的！",
            ["ContentFR"] = "C’est à la fois une promesse et un rêve ! Vous verrez bien... je le réaliserai, quoi qu’il arrive !",
            ["DialogueId"] = 51151306,
            ["GUID"] = "800D4B24",
            ["NextDialogue"] = 51151313,
            ["SpeakNpcId"] = 900012,
            ["TalkActionId"] = {
                [1] = "900012:Excited02_End",
                },
            },
        [51151307] = {
            ["Content"] = "聊聊锦鲤皎皎的生意经。",
            ["ContentFR"] = "<I>Demander quels sont ses secrets de commerce</>",
            ["DialogueId"] = 51151307,
            ["GUID"] = "800D4B4E",
            ["NextDialogue"] = 51151308,
            },
        [51151308] = {
            ["Content"] = "听我说听我说，我最近有一个体悟……福运蛋之所以没什么人来玩，除了它太新潮之外，奖品不够吸引人也是一大痛点！",
            ["ContentFR"] = "Écoute, écoute ! J’ai eu une révélation récemment... Si les Œufs porte-bonheur n’attirent pas grand monde, ce n’est pas seulement parce qu’ils sont trop avant-gardistes. Le vrai problème, c’est que les récompenses ne font pas assez rêver !",
            ["DialogueId"] = 51151308,
            ["GUID"] = "800D4B78",
            ["NextDialogue"] = 51151309,
            ["SpeakNpcId"] = 900012,
            ["TalkActionId"] = {
                [1] = "900012:Explain01_End",
                },
            },
        [51151309] = {
            ["Content"] = "华胥有些织星客和悬衡派谈下了授权，专门售卖限定版香囊，生意可红火啦。这给了本皎皎灵感！",
            ["ContentFR"] = "À Huaxu, certains Tisse-Étoiles ont obtenu des autorisations de la Secte Xuanheng pour vendre des sachets d’encens en édition limitée. Et leur commerce marche du tonnerre ! Ça m’a donné une idée géniale !",
            ["DialogueId"] = 51151309,
            ["GUID"] = "800D4BA2",
            ["NextDialogue"] = 51151310,
            ["SpeakNpcId"] = 900012,
            ["TalkActionId"] = {
                [1] = "900012:Talk02_Start",
                },
            },
        [51151310] = {
            ["Content"] = "说到足够吸引人的奖品，那自然得是我们人见人爱的皎皎一族！",
            ["ContentFR"] = "Et quand on parle de récompenses vraiment irrésistibles... quoi de mieux que notre adorable peuple Luno ?",
            ["DialogueId"] = 51151310,
            ["GUID"] = "800D4BCC",
            ["NextDialogue"] = 51151311,
            ["SpeakNpcId"] = 900012,
            ["TalkActionId"] = {
                [1] = "900012:Talk02_End",
                },
            },
        }
  end },
  { MinKey = 51151311, MaxKey = 51155215, Loader = function()
      return {
        [51151311] = {
            ["Content"] = "{nickname}，你说你说，我去订制一款皎皎联名奖品，将来自海伯利亚的魔王大人作为压轴隐藏款，是不是一定能大卖特卖？",
            ["ContentFR"] = "Dis-moi, {nickname}, dis-moi ! Si je lance une récompense en collaboration avec les Luno, et que je garde le Roi Démon venu d’Hyperborea comme lot secret ultime... Ça ferait un carton, non ?",
            ["DialogueId"] = 51151311,
            ["GUID"] = "800D4BF6",
            ["NextDialogue"] = 51151312,
            ["SpeakNpcId"] = 900012,
            ["TalkActionId"] = {
                [1] = "900012:Excited01_Start",
                },
            },
        [51151312] = {
            ["Content"] = "嘿嘿，到时候一定会数钱数到手软！",
            ["ContentFR"] = "Héhé... j’en aurais les mains engourdies à force de compter les pièces !",
            ["DialogueId"] = 51151312,
            ["GUID"] = "800D4C20",
            ["NextDialogue"] = 51151313,
            ["SpeakNpcId"] = 900012,
            ["TalkActionId"] = {
                [1] = "900012:Excited01_End",
                },
            },
        [51151313] = {
            ["Content"] = "你们忙你们的去吧！在努力实现梦想这方面，本皎皎也不能输！",
            ["ContentFR"] = "Allez, allez, vous avez des choses à faire ! Moi aussi, j’ai des rêves à poursuivre... et hors de question que je me laisse distancer !",
            ["DialogueId"] = 51151313,
            ["GUID"] = "800D4C4A",
            ["SpeakNpcId"] = 900012,
            },
        [51151401] = {
            ["Content"] = "…………（蛋皎在板子上写下了“喜欢您来”。）",
            ["ContentFR"] = "... Lunoeggy trace lentement des mots sur la planche. On peut y lire : « Ravie de vous voir. »",
            ["DialogueId"] = 51151401,
            ["GUID"] = "800D5ABA",
            ["NextOptions"] = {
                [1] = 51151402,
                [2] = 51151403,
                },
            ["SpeakNpcId"] = 900011,
            },
        [51151402] = {
            ["Content"] = "总觉得你有点眼熟……",
            ["ContentFR"] = "<I>J’ai l’impression de t’avoir déjà vu quelque part...</>",
            ["DialogueId"] = 51151402,
            ["GUID"] = "800D5AE4",
            ["NextDialogue"] = 51151404,
            },
        [51151403] = {
            ["Content"] = "我们是不是在一个叫冰湖城的地方见过。",
            ["ContentFR"] = "<I>On ne se serait pas rencontrés à Givrelac ?</>",
            ["DialogueId"] = 51151403,
            ["GUID"] = "800D5B0E",
            ["NextDialogue"] = 51151404,
            },
        [51151404] = {
            ["Content"] = "…………（没错！就是我！我有好多好多分身。不信的话，等你去了下一个城市，我会再变出来一个分身。）",
            ["ContentFR"] = "... « Exactement ! C’est bien moi ! J’ai énormément, énormément de copies. Si vous ne me croyez pas, attendez d’arriver dans la prochaine ville : j’y apparaîtrai encore sous une autre forme. »",
            ["DialogueId"] = 51151404,
            ["GUID"] = "800D5B38",
            ["NextOptions"] = {
                [1] = 51151405,
                [2] = 51151407,
                },
            ["SpeakNpcId"] = 900011,
            },
        [51151405] = {
            ["Content"] = "相信。",
            ["ContentFR"] = "<I>Croire</>",
            ["DialogueId"] = 51151405,
            ["GUID"] = "800D5B62",
            ["ImprPlusId"] = 1207,
            ["NextDialogue"] = 51151406,
            },
        [51151406] = {
            ["Content"] = "会分身的蛋皎吗……真是不可思议的神奇生物啊。",
            ["ContentFR"] = "Une Lunoeggy capable de se multiplier... Quelle créature incroyablement fascinante.",
            ["DialogueId"] = 51151406,
            ["GUID"] = "800D5B8C",
            ["NextOptions"] = {
                [1] = 51151412,
                },
            ["SpeakNpcId"] = 100001,
            },
        [51151407] = {
            ["Content"] = "不相信。",
            ["ContentFR"] = "<I>Ne pas croire</>",
            ["DialogueId"] = 51151407,
            ["GUID"] = "800D5BB6",
            ["ImprPlusId"] = 1208,
            ["NextDialogue"] = 51151408,
            },
        [51151408] = {
            ["Content"] = "你们就是钻进了蛋壳的不同皎皎吧，只是不知为何选了同样的蛋壳。",
            ["ContentFR"] = "Vous êtes simplement différentes Luno cachées à l’intérieur de coquilles similaires, non ? Je me demande juste pourquoi vous avez toutes choisi exactement la même.",
            ["DialogueId"] = 51151408,
            ["GUID"] = "800D5BE0",
            ["NextDialogue"] = 51151409,
            ["SpeakNpcId"] = 100001,
            },
        [51151409] = {
            ["Content"] = "…………（哼哼，当然是因为，最高明的躲藏方式，就是藏在一群蛋皎之中！）",
            ["ContentFR"] = "... « Héhé... parce que la meilleure cachette, c’est de se fondre parmi une foule de Lunoeggy ! »",
            ["DialogueId"] = 51151409,
            ["GUID"] = "800D5C0A",
            ["NextDialogue"] = 51151410,
            ["SpeakNpcId"] = 900011,
            },
        [51151410] = {
            ["Content"] = "…………（这样当一只蛋皎在玩骰子时赢了你，你想赢回来的时候，就找不到当时赢你的到底是哪只蛋皎了。）",
            ["ContentFR"] = "... « Ainsi, quand l’une d’entre nous vous bat aux dés et que vous cherchez à prendre votre revanche, vous ne savez jamais laquelle vous a battu. »",
            ["DialogueId"] = 51151410,
            ["GUID"] = "800D5C34",
            ["NextDialogue"] = 51151411,
            ["SpeakNpcId"] = 900011,
            },
        [51151411] = {
            ["Content"] = "好像挺有道理的。",
            ["ContentFR"] = "Vu comme ça... ça se tient.",
            ["DialogueId"] = 51151411,
            ["GUID"] = "800D5C5E",
            ["NextOptions"] = {
                [1] = 51151412,
                },
            ["SpeakNpcId"] = 100001,
            },
        [51151412] = {
            ["Content"] = "那么，能打开蛋壳给我看看吗？",
            ["ContentFR"] = "<I>Dans ce cas, tu pourrais ouvrir la coquille et me montrer ce qu’il y a à l’intérieur ?</>",
            ["DialogueId"] = 51151412,
            ["GUID"] = "800D5C88",
            ["NextDialogue"] = 51151413,
            },
        [51151413] = {
            ["Content"] = "…………！（不可以！蛋壳之下就是蛋壳，蛋壳之下还是蛋壳，绝对不是皎皎，绝对！）",
            ["ContentFR"] = "... ! « Impossible ! Sous la coquille, il y a encore une coquille. Et sous celle-là, une autre coquille ! Certainement pas une Luno. Absolument pas ! »",
            ["DialogueId"] = 51151413,
            ["GUID"] = "800D5CB2",
            ["SpeakNpcId"] = 900011,
            },
        [51152002] = {
            ["Content"] = "诶？小仆从小仆从，这附近的风声好大哦，你听你听，呜呜呜呜呜的。",
            ["ContentFR"] = "Hein ? Petit larbin... écoute un peu ! Le vent fait un bruit énorme par ici... tu entends ? <I>Ouuuh—ouuuuh—</>",
            ["DialogueId"] = 51152002,
            ["GUID"] = "800DBD54",
            ["SpeakNpcId"] = 701087,
            },
        [51152003] = {
            ["Content"] = "呜……呜……",
            ["ContentFR"] = "<I>Ouuuh... ouuuuh...</>",
            ["DialogueId"] = 51152003,
            ["GUID"] = "800DBD7E",
            ["SpeakNpcName"] = "UI_CMNpc_Name_Zhongniannan",
            },
        [51152004] = {
            ["Content"] = "呜……别过来，不要逼我……不要逼我！",
            ["ContentFR"] = "<I>Ouuuh... </>n’approchez pas... ne me forcez pas... ne me forcez pas !",
            ["DialogueId"] = 51152004,
            ["GUID"] = "800DBDA8",
            ["SpeakNpcName"] = "UI_CMNpc_Name_Zhongniannan",
            },
        [51152005] = {
            ["Content"] = "咦，不，不是风声，好像是有人在前面！我们快过去看看发生了什么吧。",
            ["ContentFR"] = "Oh— ! Attends, ce n’est pas le vent... On dirait qu’il y a quelqu’un plus loin devant ! Vite, allons voir ce qui se passe !",
            ["DialogueId"] = 51152005,
            ["GUID"] = "800DBDD2",
            ["SpeakNpcId"] = 701087,
            },
        [51152007] = {
            ["Content"] = "好，我们出发！",
            ["ContentFR"] = "Très bien ! En route !",
            ["DialogueId"] = 51152007,
            ["GUID"] = "800DBE26",
            ["SpeakNpcId"] = 200002,
            },
        [51152008] = {
            ["Content"] = "呜哇，好多秽兽，看招看招！",
            ["ContentFR"] = "Ouaaah, il y en a plein ! Allez, mangez-moi ça !",
            ["DialogueId"] = 51152008,
            ["GUID"] = "800DBE50",
            ["SpeakNpcId"] = 200002,
            },
        [51152009] = {
            ["Content"] = "好耶，马上就能把这群坏家伙打跑了。不过话说回来，你有没有觉得那个被困的家伙有点眼熟哇？",
            ["ContentFR"] = "Bien ! On va bientôt faire fuir tous ces vilains monstres ! ... Dis donc, petit larbin, tu ne trouves pas que le type coincé là-bas te dit quelque chose ?",
            ["DialogueId"] = 51152009,
            ["GUID"] = "800DBE7A",
            ["SpeakNpcId"] = 200002,
            },
        [51152010] = {
            ["Content"] = "先专注眼前的敌人吧。",
            ["ContentFR"] = "Concentre-toi sur l’ennemi. Finissons le combat.",
            ["DialogueId"] = 51152010,
            ["GUID"] = "800DBEA4",
            ["SpeakNpcId"] = 100001,
            },
        [51152011] = {
            ["Camera"] = "643.927734,72.326172,238.735352,0.000106,-19.939514,-168.080322,35.0,472.956573,false,Manual,2.557317",
            ["Content"] = "呼……呼……",
            ["ContentFR"] = "Hah... hah...",
            ["DialogueId"] = 51152011,
            ["FinalCamera"] = "467.330078,35.046875,173.258789,0.000107,-19.939507,-168.080215,35.0,283.195221,false,Manual,1.482159",
            ["GUID"] = "800DBECE",
            ["LookAt"] = {
                [1] = "200002:n(701088)",
                },
            ["SpeakNpcId"] = 701088,
            ["TalkActionId"] = {
                [1] = "701088:Hurt01",
                },
            ["ToFinalCameraBlendTime"] = 5,
            },
        [51152012] = {
            ["Camera"] = "421.720703,-66.143555,106.893555,0.00008,-8.94039,-173.895111,35.000008,197.80249,false,Manual,2.8",
            ["Content"] = "那些秽兽都被我们打跑啦，你的伤……",
            ["ContentFR"] = "Les Souillés sont partis ! Mais vous êtes blessé... ça va aller ?",
            ["DialogueId"] = 51152012,
            ["FacialId"] = {
                [1] = "200002:Shock01",
                },
            ["GUID"] = "800DBEF8",
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Shock03_Start",
                },
            ["TurnTo"] = {
                [1] = "701088:n(100001)",
                },
            },
        [51152013] = {
            ["Content"] = "发乎于心，现乎于行。若是动了兵戈，人心就会变质。无论这兵戈朝向的是友邻还是恶敌，性质都是相同的！终是逆了天意呀！",
            ["ContentFR"] = "Tout commence dans le cœur et se manifeste dans les actes. Une fois les armes levées, l’âme se corrompt. Qu’elles soient tournées vers un allié ou un ennemi, leur nature demeure identique ! C’est aller à l’encontre de la volonté céleste !",
            ["DialogueId"] = 51152013,
            ["GUID"] = "800DBF22",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20031004.T_Story_Recall_20031004'\
",
            ["SpeakNpcId"] = 701088,
            ["TalkActionId"] = {
                [1] = "200002:Shock03_End",
                },
            },
        [51152014] = {
            ["Content"] = "按照你的意思。我们应该在原地待着，什么都不做，束手就擒……是吗？",
            ["ContentFR"] = "Selon vous, nous devrions donc rester immobiles, ne rien faire, et attendre d’être dévorés... est-ce bien cela ?",
            ["DialogueId"] = 51152014,
            ["GUID"] = "800DBF4C",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20031004.T_Story_Recall_20031004'",
            ["SpeakNpcName"] = "UI_Npc_Name_Zhiliu",
            },
        [51152015] = {
            ["Content"] = "白龙神君会为我们驱除恶邪的！要是招来白龙神君的厌弃，失去了祂的庇护，那才是因小失大。您请三思啊！",
            ["ContentFR"] = "Le Seigneur Dragon d’Argent chassera le mal pour nous ! Si nous provoquons Son courroux et perdons Sa protection, ce serait là la véritable ruine. Je vous en prie, réfléchissez !",
            ["DialogueId"] = 51152015,
            ["GUID"] = "800DBF76",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20031004.T_Story_Recall_20031004'",
            ["SpeakNpcId"] = 701088,
            },
        [51152016] = {
            ["Camera"] = "467.330078,35.046875,173.258789,0.000107,-19.939507,-168.080215,35.0,283.195221,false,Manual,1.482159",
            ["Content"] = "啊，是你！你是那时候被止流姐姐赶出百年春的家伙。",
            ["ContentFR"] = "Ah ! C’est vous ! Vous êtes celui que Zhiliu a chassé d’Éternel Printemps, l’autre jour !",
            ["DialogueId"] = 51152016,
            ["FacialId"] = {
                [1] = "200002:Shock01",
                },
            ["GUID"] = "800DBFA0",
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Talk01_Start",
                },
            },
        [51152017] = {
            ["Camera"] = "414.412109,-49.105469,121.125977,0.000048,1.599821,152.399612,35.0,290.856323,false,Manual,2.056568",
            ["Content"] = "（鲜血顺着男子的额角滑至地面，那摊鲜血旁，倒着一只死去不久的秽兽。结合周围香雾缭绕却未见狴犴的样子，看来他直到遇袭都没等到白龙神君的庇护。）",
            ["ContentFR"] = "Le sang s’écoule de la tempe de l’homme et s’étale sur le sol. À côté de la flaque repose un Souillé fraîchement abattu. L’air est saturé d’encens, mais aucune trace de Bi’an à l’horizon. Il semble que, même face à la mort, la protection du Seigneur Dragon d’Argent ne soit jamais venue.",
            ["DialogueId"] = 51152017,
            ["GUID"] = "800DBFCA",
            ["SpeakNpcId"] = 0,
            ["TalkActionId"] = {
                [1] = "200002:Talk01_End",
                [2] = "100001:Give",
                },
            },
        [51152018] = {
            ["Content"] = "这只秽兽是你杀死的。",
            ["ContentFR"] = "<I>Ce Souillé... c’est vous qui l’avez tué.</>",
            ["DialogueId"] = 51152018,
            ["GUID"] = "800DBFF4",
            ["ImprPlusId"] = 1208,
            },
        [51152019] = {
            ["Content"] = "看来白龙神君并没有对你出手相助。",
            ["ContentFR"] = "<I>On dirait que le Seigneur Dragon d’Argent ne vous a pas porté secours.</>",
            ["DialogueId"] = 51152019,
            ["GUID"] = "800DC01E",
            ["ImprPlusId"] = 1206,
            },
        [51152020] = {
            ["Content"] = "之前不是说，就算是死外面也绝不动武吗？",
            ["ContentFR"] = "<I>Vous disiez pourtant préférer mourir plutôt que de vous battre.</>",
            ["DialogueId"] = 51152020,
            ["GUID"] = "800DC048",
            ["ImprPlusId"] = 1210,
            },
        [51152024] = {
            ["Camera"] = "360.478516,-106.482422,91.936523,0.000124,0.0,159.903,16.91279,275.194305,false,Manual,2.8",
            ["Content"] = "哈哈……是你们。我在百年春见过你们。",
            ["ContentFR"] = "Ha ha... c’est vous. Je vous ai vus à Éternel Printemps.",
            ["DialogueId"] = 51152024,
            ["FacialId"] = {
                [1] = "100001:Smile01",
                },
            ["GUID"] = "800DC0F0",
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{100001},AnimationId{\"Wave02_Start\"},Duration{3}},\
PlayAnimation{ActorId{100001},AnimationId{\"Wave02_End\"}}\
}",
            ["SpeakNpcId"] = 701088,
            ["TalkActionId"] = {
                [1] = "701088:Idle",
                [2] = "200002:Confident_Start",
                },
            },
        [51152025] = {
            ["Camera"] = "61.623047,-87.913086,149.791992,0.000068,3.860225,27.111759,35.000008,629.109375,false,DoNotOverride,2.8",
            ["Content"] = "你们是来耻笑我的吗……无所谓，笑就笑吧。我触犯了诫律，我动了兵刃……",
            ["ContentFR"] = "Êtes-vous venus vous moquer de moi... ? Peu importe. Riez, si cela vous chante. J’ai transgressé les préceptes. J’ai pris une arme...",
            ["DialogueId"] = 51152025,
            ["GUID"] = "800DC11A",
            ["SpeakNpcId"] = 701088,
            },
        [51152026] = {
            ["Camera"] = "61.623047,-87.913086,149.791992,0.000068,3.860225,27.111759,35.000008,629.109375,false,DoNotOverride,2.8",
            ["Content"] = "我犯了错……白龙神君就要降下惩罚了。哈、哈……",
            ["ContentFR"] = "J’ai fauté... et le Seigneur Dragon Blanc va me punir. Ha... ha...",
            ["DialogueId"] = 51152026,
            ["FacialId"] = {
                [1] = "701088:Sad01",
                },
            ["GUID"] = "800DC144",
            ["SpeakNpcId"] = 701088,
            ["TalkActionId"] = {
                [1] = "701088:Disagree",
                },
            },
        [51152027] = {
            ["Camera"] = "467.330078,35.046875,173.258789,0.000107,-19.939507,-168.080215,35.0,283.195221,false,Manual,1.482159",
            ["Content"] = "你是笨蛋吗！死脑筋！",
            ["ContentFR"] = "Vous êtes bête ou quoi ? Complètement borné !",
            ["DialogueId"] = 51152027,
            ["FacialId"] = {
                [1] = "200002:Angry02",
                },
            ["GUID"] = "800DC16E",
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Angry01_Start",
                },
            },
        [51152028] = {
            ["Camera"] = "467.330078,35.046875,173.258789,0.000107,-19.939507,-168.080215,35.0,283.195221,false,Manual,1.482159",
            ["Content"] = "我听小仆从说，白龙神君只是说，不能对人类动手吧？但祂没有说过，对秽兽动手也不可以吧？",
            ["ContentFR"] = "Petit larbin m’a raconté que le Seigneur Dragon Blanc a seulement interdit de lever la main contre les humains, non ? Il n’a jamais dit qu’on n’avait pas le droit de se défendre contre les Souillés !",
            ["DialogueId"] = 51152028,
            ["GUID"] = "800DC198",
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Angry01_End",
                },
            },
        [51152029] = {
            ["Camera"] = "-44.644531,-128.060547,109.717773,0.000053,4.460147,35.51128,35.000008,395.555206,false,Manual,2.8",
            ["Content"] = "我、我不知道……诫律没提到秽兽，我不知道……我只知道，不可动武，不可动武……这是我从小到大的信仰。",
            ["ContentFR"] = "Je... je ne sais pas... Les préceptes ne parlaient pas des Souillés... je ne sais pas... Je n’ai retenu qu’une chose, depuis l’enfance : ne jamais combattre... jamais...",
            ["DialogueId"] = 51152029,
            ["FacialId"] = {
                [1] = "701088:Grief",
                },
            ["GUID"] = "800DC1C2",
            ["SpeakNpcId"] = 701088,
            ["TalkActionId"] = {
                [1] = "701088:Sigh_Start",
                },
            },
        [51152030] = {
            ["Camera"] = "-44.644531,-128.060547,109.717773,0.000053,4.460147,35.51128,35.000008,395.555206,false,Manual,2.8",
            ["Content"] = "可是刚刚，那秽兽扑上来，血盆大口对着我，我无论如何都不想死、不想死啊！于是我就拿着、拿着砍树的柴刀，拼命地——",
            ["ContentFR"] = "Mais tout à l’heure... ce Souillé s’est jeté sur moi, la gueule grande ouverte... Je ne voulais pas mourir... je ne voulais pas mourir ! Alors j’ai pris... pris ma hache... et j’ai frappé de toutes mes forces—",
            ["DialogueId"] = 51152030,
            ["GUID"] = "800DC1EC",
            ["SpeakNpcId"] = 701088,
            ["TalkActionId"] = {
                [1] = "701088:Sigh_End",
                },
            },
        [51152031] = {
            ["Camera"] = "431.021484,-25.061523,196.442383,0.000075,-11.940488,159.505447,35.000008,308.194794,false,Manual,2.8",
            ["Content"] = "这就对了。",
            ["ContentFR"] = "Voilà. C’est exactement ça.",
            ["DialogueId"] = 51152031,
            ["FacialId"] = {
                [1] = "100001:Happy01",
                },
            ["GUID"] = "800DC216",
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:ConfidentLR_Start",
                },
            },
        [51152032] = {
            ["Camera"] = "431.021484,-25.061523,196.442383,0.000075,-11.940488,159.505447,35.000008,308.194794,false,Manual,2.8",
            ["Content"] = "什么神明，什么信仰，都没有活下去重要，这才是你的本心。所以，你才会在生死关头做出这样的选择。",
            ["ContentFR"] = "Les dieux, la foi... rien n’est plus important que de rester en vie. Au moment décisif, vous avez écouté votre véritable instinct. C’est pour cela que vous avez fait ce choix.",
            ["DialogueId"] = 51152032,
            ["GUID"] = "800DC240",
            ["SpeakNpcId"] = 100001,
            },
        [51152033] = {
            ["Camera"] = "338.265625,19.038086,179.210938,0.000076,-10.340483,176.105225,35.0,210.359772,false,Manual,2.8",
            ["Content"] = "看你伤成这样，就不笑话你了。人想活着有什么错？我送你回百年春吧。",
            ["ContentFR"] = "Vu votre état, je vais éviter de me moquer. Vouloir vivre... en quoi est-ce une faute ? Je vais vous raccompagner à Éternel Printemps.",
            ["DialogueId"] = 51152033,
            ["FacialId"] = {
                [1] = "100001:Smile02",
                },
            ["GUID"] = "800DC26A",
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:ConfidentLR_End",
                },
            },
        [51152034] = {
            ["Camera"] = "60.732422,-88.369141,149.791992,0.000076,3.860225,27.111778,35.000008,290.0,false,Manual,2.8",
            ["Content"] = "百年春？这……",
            ["ContentFR"] = "Éternel Printemps... ? Mais—",
            ["DialogueId"] = 51152034,
            ["FacialId"] = {
                [1] = "701088:Nervous",
                },
            ["GUID"] = "800DC294",
            ["SpeakNpcId"] = 701088,
            ["TalkActionId"] = {
                [1] = "701088:Shock_Start",
                },
            },
        [51152035] = {
            ["Camera"] = "244.042969,25.453125,161.979492,0.000076,-9.34042,173.305008,35.000008,111.625343,false,Manual,2.8",
            ["Content"] = "想活命的话就少说几句吧。",
            ["ContentFR"] = "Si vous tenez à rester en vie, économisez votre souffle.",
            ["DialogueId"] = 51152035,
            ["GUID"] = "800DC2BE",
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Talk02_Start",
                },
            },
        [51152036] = {
            ["Camera"] = "-22.400391,-85.114258,115.713867,0.000092,8.260102,28.910444,38.0,357.30426,false,Manual,2.0",
            ["Content"] = "是、是……",
            ["ContentFR"] = "O... oui...",
            ["DialogueId"] = 51152036,
            ["GUID"] = "800DC2E8",
            ["SpeakNpcId"] = 701088,
            ["TalkActionId"] = {
                [1] = "701088:Shock_End",
                },
            },
        [51152037] = {
            ["Camera"] = "204.353516,19.880981,141.953125,0.000018,0.800095,-168.670593,33.0,272.927826,false,Manual,2.8",
            ["Content"] = "我、我……",
            ["ContentFR"] = "Je... je...",
            ["DialogueId"] = 51152037,
            ["FacialId"] = {
                [1] = "701088:Grief",
                },
            ["GUID"] = "800DC312",
            ["LookAt"] = {
                [1] = "100001:n(701088)",
                },
            ["SpeakNpcId"] = 701088,
            ["TalkActionId"] = {
                [1] = "701088:Sigh_Start",
                },
            },
        [51152038] = {
            ["Camera"] = "-151.316406,-261.926147,162.417969,0.000048,-3.799989,55.524673,50.0,371.934418,false,Manual,2.5",
            ["Content"] = "怎么了？",
            ["ContentFR"] = "Qu’y a-t-il ?",
            ["DialogueId"] = 51152038,
            ["GUID"] = "800DC33C",
            ["LookAt"] = {
                [1] = "701088:n(100001)",
                },
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Talk03_Start",
                },
            },
        [51152039] = {
            ["Camera"] = "204.353516,19.880981,141.953125,0.000018,0.800095,-168.670593,33.0,272.927826,false,Manual,2.8",
            ["Content"] = "方前我对止流大人如此出言不逊，她、她还愿意收留我吗……",
            ["ContentFR"] = "Plus tôt... j’ai parlé avec insolence à Dame Zhiliu... Acceptera-t-elle vraiment de me recueillir... ?",
            ["DialogueId"] = 51152039,
            ["GUID"] = "800DC366",
            ["SpeakNpcId"] = 701088,
            ["TalkActionId"] = {
                [1] = "701088:Sigh_End",
                },
            },
        [51152040] = {
            ["Camera"] = "93.96875,-175.016968,177.651367,0.000065,-8.600068,90.798744,50.0,198.719955,false,Manual,2.5",
            ["Content"] = "她先前不过是对你以信仰为由，阻止大家自卫而愤怒。但如今……你已经用双手诚实地做出了选择。",
            ["ContentFR"] = "Elle était en colère parce que vous utilisiez la foi pour empêcher les autres de se défendre. Mais maintenant... vous avez fait un choix honnête, de vos propres mains.",
            ["DialogueId"] = 51152040,
            ["GUID"] = "800DC390",
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Talk03_End",
                },
            },
        [51152041] = {
            ["Camera"] = "93.96875,-175.016968,177.651367,0.000065,-8.600068,90.798744,50.0,198.719955,false,Manual,2.5",
            ["Content"] = "只要你真诚道歉，我想她会谅解的。",
            ["ContentFR"] = "Si vous présentez vos excuses avec sincérité, je pense qu’elle saura vous pardonner.",
            ["DialogueId"] = 51152041,
            ["FacialId"] = {
                [1] = "100001:Smile01",
                },
            ["GUID"] = "800DC3BA",
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Talk02_Start",
                },
            },
        [51152042] = {
            ["Camera"] = "350.330078,-275.796265,132.675781,0.000026,0.600155,140.929413,15.794469,336.572845,false,Manual,2.8",
            ["Content"] = "……我明白了。",
            ["ContentFR"] = "... Je comprends.",
            ["DialogueId"] = 51152042,
            ["FacialId"] = {
                [1] = "701088:Nervous",
                },
            ["GUID"] = "800DC3E4",
            ["SpeakNpcId"] = 701088,
            ["TalkActionId"] = {
                [1] = "701088:Agree",
                },
            },
        [51152043] = {
            ["Camera"] = "350.330078,-275.796265,132.675781,0.000026,0.600155,140.929413,15.794469,336.572845,false,Manual,2.8",
            ["Content"] = "想不到我半生的信仰救不了我，最终救了我的竟是这把柴刀……",
            ["ContentFR"] = "Ironique, n’est-ce pas... La foi qui m’a accompagné toute ma vie n’a pas pu me sauver... Et c’est cette simple hache qui l’a fait.",
            ["DialogueId"] = 51152043,
            ["GUID"] = "800DC40E",
            ["SpeakNpcId"] = 701088,
            ["TalkActionId"] = {
                [1] = "701088:Talk02_Start",
                },
            },
        [51152044] = {
            ["Camera"] = "69.585938,11.308655,153.422852,0.000016,0.999987,-144.27388,33.0,143.369492,false,Manual,2.8",
            ["Content"] = "我会向止流大人致歉……还有，致谢。",
            ["ContentFR"] = "Je présenterai mes excuses à Dame Zhiliu... Et je la remercierai.",
            ["DialogueId"] = 51152044,
            ["FacialId"] = {
                [1] = "701088:Sad01",
                },
            ["GUID"] = "800DC438",
            ["SpeakNpcId"] = 701088,
            ["TalkActionId"] = {
                [1] = "701088:Talk02_End",
                },
            },
        [51152045] = {
            ["Camera"] = "69.585938,11.308655,153.422852,0.000016,0.999987,-144.27388,33.0,143.369492,false,Manual,2.8",
            ["Content"] = "多谢义士一路护送，请收下我的谢礼吧。",
            ["ContentFR"] = "Merci, {性别:valeureux voyageur|valeureuse voyageuse}, pour votre protection. Je vous en prie... acceptez ceci en gage de ma gratitude.",
            ["DialogueId"] = 51152045,
            ["GUID"] = "800DC462",
            ["SpeakNpcId"] = 701088,
            ["TalkActionId"] = {
                [1] = "701088:Give",
                },
            },
        [51153001] = {
            ["Content"] = "不对味，不对味，这味怎么不对啊？老板，你是不是做了什么手脚。这茶汤与我<H>记忆中的滋味</>分明相差甚远！",
            ["ContentFR"] = "Ce n’est pas ça... non, ce n’est pas ça... Cette saveur est différente. Dites-moi, patron, vous n’auriez pas changé quelque chose ? Ce thé n’a rien à voir avec <H>le goût dont je me souviens</> !",
            ["DialogueId"] = 51153001,
            ["GUID"] = "800E613A",
            ["SpeakNpcId"] = 701091,
            },
        [51153002] = {
            ["Camera"] = "-408.917969,289.988281,124.88916,-0.0,-4.999999,-26.999968,22.0,556.40625,false,Manual,1.7",
            ["Content"] = "这位客人，究竟是哪里不对，哪里味道不一样，你倒是说出个一二来啊？",
            ["ContentFR"] = "Et qu’est-ce qui ne va pas, au juste ? Dites-le clairement. En quoi ce thé serait-il différent ?",
            ["DialogueId"] = 51153002,
            ["FacialId"] = {
                [1] = "701090:CM_Angry01",
                },
            ["GUID"] = "800E6164",
            ["LookAt"] = {
                [1] = "100001:n(701090)",
                },
            ["NextDialogue"] = 51153003,
            ["SpeakNpcId"] = 701090,
            ["TalkActionId"] = {
                [1] = "701090:Angry01_Start",
                },
            },
        [51153003] = {
            ["Camera"] = "-22.859375,122.511719,145.754395,0.000026,0.199988,-79.15564,33.0,197.256683,false,Manual,1.78578",
            ["Content"] = "你在这里红口白牙瞎说，这不是在砸我的买卖吗！这位白衣服{性别：小兄弟|姑娘}，我看你在这儿站了一阵子了，不然你来评评理？",
            ["ContentFR"] = "Vous parlez sans preuve, la bouche pleine de mensonges. C’est mon commerce que vous cherchez à ruiner ! Vous là-bas, en blanc — {性别:jeune homme|jeune femme} — vous êtes là depuis un moment, non ? Venez donc trancher.",
            ["DialogueId"] = 51153003,
            ["GUID"] = "800E618E",
            ["LookAt"] = {
                [1] = "701090:n(100001)",
                },
            ["NextOptions"] = {
                [1] = 51153004,
                [2] = 51153007,
                },
            ["SpeakNpcId"] = 701090,
            ["TalkActionId"] = {
                [1] = "701090:Angry01_End",
                },
            },
        [51153004] = {
            ["Content"] = "是不是老板换了原料或工艺，以次充好？",
            ["ContentFR"] = "<I>Auriez-vous changé les ingrédients ou la méthode, pour réduire les coûts ?</>",
            ["DialogueId"] = 51153004,
            ["GUID"] = "800E61B8",
            ["NextDialogue"] = 51153005,
            },
        [51153005] = {
            ["Camera"] = "-285.1875,166.675781,127.64502,0.000036,1.399991,-33.151527,50.0,375.0,false,Manual,2.8",
            ["Content"] = "你可别瞎说，我这大碗茶，三停茶叶一停花，半银币一大碗，从未变过。",
            ["ContentFR"] = "Ne racontez pas n’importe quoi. Mon thé, c’est trois parts de feuilles, une part de fleurs. Une demi-pièce d’argent le grand bol. Ça n’a jamais changé.",
            ["DialogueId"] = 51153005,
            ["GUID"] = "800E61E2",
            ["NextDialogue"] = 51153006,
            ["SpeakNpcId"] = 701090,
            ["TalkActionId"] = {
                [1] = "701090:Talk03_Start",
                },
            },
        [51153006] = {
            ["Camera"] = "-285.1875,166.675781,127.64502,0.000036,1.399991,-33.151527,50.0,375.0,false,Manual,2.8",
            ["Content"] = "我随老父亲在此处卖了二十年茶水了，从挑着担子卖水起，到今日有两间小铺，从不做偷工减料，以次充好的事！",
            ["ContentFR"] = "Voilà vingt ans que je vends du thé ici avec mon vieux père. On a commencé avec une simple palanche, et aujourd’hui on a deux petites échoppes. Jamais je n’ai triché sur la marchandise !",
            ["DialogueId"] = 51153006,
            ["GUID"] = "800E620C",
            ["NextDialogue"] = 51153009,
            ["SpeakNpcId"] = 701090,
            ["TalkActionId"] = {
                [1] = "701090:Talk03_End",
                },
            },
        [51153007] = {
            ["Content"] = "是不是这位顾客故意找茬，白吃白喝？",
            ["ContentFR"] = "<I>Ce client cherche peut-être seulement à provoquer, pour boire gratuitement ?</>",
            ["DialogueId"] = 51153007,
            ["GUID"] = "800E6236",
            ["NextDialogue"] = 51153008,
            },
        [51153008] = {
            ["Camera"] = "-273.785156,39.746094,126.045898,0.000046,1.999934,16.852501,50.0,348.791229,false,Manual,2.8",
            ["Content"] = "这位小友，我绝非信口开河，你且听我道来。",
            ["ContentFR"] = "Je vous assure que je ne parle pas à la légère. Écoutez-moi, je vous prie.",
            ["DialogueId"] = 51153008,
            ["GUID"] = "800E6260",
            ["LookAt"] = {
                [1] = "100001:n(701091)",
                },
            ["NextDialogue"] = 51153009,
            ["SpeakNpcId"] = 701091,
            ["TurnTo"] = {
                [1] = "701091:n(100001)",
                [2] = "100001:n(701091)",
                },
            },
        [51153009] = {
            ["Camera"] = "-273.785156,39.746094,126.045898,0.000046,1.999934,16.852501,50.0,348.791229,false,Manual,2.8",
            ["Content"] = "小友你有所不知，我是一名织星客，常年游历异乡，久不归家。这次在横越沙漠，口干舌燥时，口中突然涌起年幼时曾经尝过的花茶的甘香。",
            ["ContentFR"] = "Je suis un Tisse-Étoiles. Cela fait des années que je parcours des terres lointaines, sans rentrer chez moi. Dernièrement, en traversant le désert, la gorge desséchée, le goût sucré d’un thé aux fleurs de mon enfance m’est soudain revenu.",
            ["DialogueId"] = 51153009,
            ["GUID"] = "800E628A",
            ["LookAt"] = {
                [1] = "701091:n(100001)",
                [2] = "100001:n(701091)",
                },
            ["NextDialogue"] = 51153010,
            ["SpeakNpcId"] = 701091,
            ["TalkActionId"] = {
                [1] = "701091:Talk02_Start",
                },
            },
        [51153010] = {
            ["Camera"] = "-273.785156,39.746094,126.045898,0.000046,1.999934,16.852501,50.0,348.791229,false,Manual,2.8",
            ["Content"] = "这不，我一回到浮星埠，就奔着这家茶摊来了。可是他家的茶汤却变了味道，令人好不扫兴。",
            ["ContentFR"] = "Alors, dès mon retour au Quai-aux-Étoiles, je suis venu droit à cette échoppe. Mais ce thé... son goût a changé. Quelle déception.",
            ["DialogueId"] = 51153010,
            ["GUID"] = "800E62B4",
            ["NextDialogue"] = 51153011,
            ["SpeakNpcId"] = 701091,
            },
        [51153011] = {
            ["Camera"] = "-273.785156,39.746094,126.045898,0.000046,1.999934,16.852501,50.0,348.791229,false,Manual,2.8",
            ["Content"] = "我记得之前的茶汤，甘冽解渴，花香隐约，只是汤中有碎末这一点不好。如今你这茶，透亮清澈，确不是曾经的茶汤。",
            ["ContentFR"] = "Le thé dont je me souviens était vif et désaltérant, le parfum floral discret. Seuls les résidus au fond du bol étaient désagréables. Celui-ci est limpide, clair... Ce n’est plus le même.",
            ["DialogueId"] = 51153011,
            ["GUID"] = "800E62DE",
            ["NextDialogue"] = 51153012,
            ["SpeakNpcId"] = 701091,
            ["TalkActionId"] = {
                [1] = "701091:Talk02_End",
                },
            },
        [51153012] = {
            ["Camera"] = "8.28125,542.140625,129.218262,0.000026,0.999981,-90.554573,50.0,605.407349,false,Manual,2.8",
            ["Content"] = "老弟，你这么一说我就明白了。我老父亲年前回家颐养天年，我接手了这家铺子，把之前的碎末子换成了整叶。",
            ["ContentFR"] = "Ah... je comprends, maintenant. Mon vieux père est rentré chez lui l’an passé pour se reposer. J’ai repris l’échoppe, et remplacé les feuilles brisées par des feuilles entières.",
            ["DialogueId"] = 51153012,
            ["FacialId"] = {
                [1] = "701090:CM_Smile01",
                },
            ["GUID"] = "800E6308",
            ["LookAt"] = {
                [1] = "100001:n(701090)",
                [2] = "701091:n(701090)",
                [3] = "701090:n(701091)",
                },
            ["NextDialogue"] = 51153013,
            ["SpeakNpcId"] = 701090,
            ["TalkActionId"] = {
                [1] = "701090:Think_Start",
                },
            },
        [51153013] = {
            ["Camera"] = "8.28125,542.140625,129.218262,0.000026,0.999981,-90.554573,50.0,605.407349,false,Manual,2.8",
            ["Content"] = "我这茶摊卖的不过是解渴的大碗茶，没想到这点差别让你给品出来了。",
            ["ContentFR"] = "Ce n’est pourtant qu’un thé pour étancher la soif. Je ne pensais pas que quelqu’un remarquerait la différence.",
            ["DialogueId"] = 51153013,
            ["GUID"] = "800E6332",
            ["NextDialogue"] = 51153014,
            ["SpeakNpcId"] = 701090,
            ["TalkActionId"] = {
                [1] = "701090:Think_End",
                },
            },
        [51153014] = {
            ["Camera"] = "141.191406,-101.46875,191.177734,0.000115,-13.600491,142.446793,50.0,284.737152,false,Manual,1.78578",
            ["Content"] = "既然误会解开，那我就告……",
            ["ContentFR"] = "Puisque le malentendu est levé, je vais prendre cong—",
            ["DialogueId"] = 51153014,
            ["FacialId"] = {
                [1] = "100001:Smile02",
                },
            ["GUID"] = "800E635C",
            ["LookAt"] = {
                [1] = "701091:n(100001)",
                },
            ["NextDialogue"] = 51153015,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Talk01_Start",
                },
            },
        [51153015] = {
            ["Camera"] = "-273.785156,39.746094,126.045898,0.000046,1.999934,16.852501,50.0,348.791229,false,Manual,2.8",
            ["Content"] = "小友且留步！",
            ["ContentFR"] = "Attendez, jeune {性别:ami|amie} !",
            ["DialogueId"] = 51153015,
            ["GUID"] = "800E6386",
            ["LookAt"] = {
                [1] = "100001:n(701091)",
                [2] = "701091:n(100001)",
                },
            ["NextDialogue"] = 51153016,
            ["SpeakNpcId"] = 701091,
            ["TalkActionId"] = {
                [1] = "701091:Explain02_Start",
                },
            },
        [51153016] = {
            ["Camera"] = "-273.785156,39.746094,126.045898,0.000046,1.999934,16.852501,50.0,348.791229,false,Manual,2.8",
            ["Content"] = "我今日定要找到旧时茶汤的滋味。百年春客商云集，天下商品无所不有，在那儿一定能找到老板曾经用过的那款茶叶。",
            ["ContentFR"] = "Aujourd’hui, je retrouverai à tout prix le goût de ce thé d’autrefois. À Éternel Printemps, les marchands affluent du monde entier. S’il existe encore ces feuilles, elles s’y trouvent forcément.",
            ["DialogueId"] = 51153016,
            ["GUID"] = "800E63B0",
            ["NextDialogue"] = 51153017,
            ["SpeakNpcId"] = 701091,
            },
        [51153017] = {
            ["Camera"] = "-273.785156,39.746094,126.045898,0.000046,1.999934,16.852501,50.0,348.791229,false,Manual,2.8",
            ["Content"] = "不知小友是否愿意随我一同前往。",
            ["ContentFR"] = "Accepteriez-vous de m’y accompagner ?",
            ["DialogueId"] = 51153017,
            ["GUID"] = "800E63DA",
            ["NextOptions"] = {
                [1] = 51153018,
                [2] = 51153020,
                },
            ["SpeakNpcId"] = 701091,
            ["TalkActionId"] = {
                [1] = "701091:Explain02_End",
                },
            },
        [51153018] = {
            ["Content"] = "走这一趟也不是不行，有什么好处吗？",
            ["ContentFR"] = "<I>Faire le détour ne me dérange pas... mais qu’est-ce que j’y gagne ?</>",
            ["DialogueId"] = 51153018,
            ["GUID"] = "800E6404",
            ["ImprPlusId"] = 1201,
            ["NextDialogue"] = 51153019,
            },
        [51153019] = {
            ["Camera"] = "-273.785156,39.746094,126.045898,0.000046,1.999934,16.852501,50.0,348.791229,false,Manual,2.8",
            ["Content"] = "如今一路上玄色狴犴猖獗为灾，如能护送我平安抵达百年春，定当重金酬谢！",
            ["ContentFR"] = "Les Bi’an obscurs sévissent sur les routes ces temps-ci. Si vous me conduisez sain et sauf jusqu’à Éternel Printemps, je vous récompenserai généreusement.",
            ["DialogueId"] = 51153019,
            ["GUID"] = "800E642E",
            ["SpeakNpcId"] = 701091,
            ["TalkActionId"] = {
                [1] = "701091:Talk01_Start",
                },
            },
        [51153020] = {
            ["Content"] = "一路上玄色狴犴泛滥，你是在担心安危吗？",
            ["ContentFR"] = "<I>Avec tous ces Bi’an obscurs, vous craignez pour votre sécurité ?</>",
            ["DialogueId"] = 51153020,
            ["GUID"] = "800E6458",
            ["ImprPlusId"] = 1204,
            ["NextDialogue"] = 51153021,
            },
        [51153021] = {
            ["Camera"] = "-273.785156,39.746094,126.045898,0.000046,1.999934,16.852501,50.0,348.791229,false,Manual,2.8",
            ["Content"] = "正是。近来烛阴为灾，我多年未归，先前的道路也不知畅行与否。如能护送我平安抵达百年春，定当重金酬谢！",
            ["ContentFR"] = "Exactement. Le Fléau de Zhuyin fait rage, et cela fait trop longtemps que je n’ai pas emprunté ces routes. Escortez-moi jusqu’à Éternel Printemps, et vous serez largement payé.",
            ["DialogueId"] = 51153021,
            ["GUID"] = "800E6482",
            ["SpeakNpcId"] = 701091,
            ["TalkActionId"] = {
                [1] = "701091:Talk01_Start",
                },
            },
        [51153022] = {
            ["Content"] = "经蒹葭浦至浮星埠，我幼时常走这条路去看船，没想到如今它竟变得如此危险。",
            ["ContentFR"] = "Entre la Baie des Roseaux-Pâles et le Quai-aux-Étoiles, enfant, je prenais souvent ce chemin pour venir voir les navires. Jamais je n’aurais imaginé qu’il devienne si dangereux.",
            ["DialogueId"] = 51153022,
            ["GUID"] = "800E64AC",
            ["NextDialogue"] = 51153023,
            ["SpeakNpcId"] = 701091,
            ["TalkActionId"] = {
                [1] = "701091:Think_Start",
                },
            },
        [51153023] = {
            ["Content"] = "果然时移世易，不可同日而语。",
            ["ContentFR"] = "Le monde change... et le temps n’attend personne.",
            ["DialogueId"] = 51153023,
            ["GUID"] = "800E64D6",
            ["NextDialogue"] = 51153024,
            ["SpeakNpcId"] = 701091,
            },
        [51153024] = {
            ["Content"] = "我们继续前进吧，百年春就在前面了。",
            ["ContentFR"] = "Continuons. Éternel Printemps est tout près.",
            ["DialogueId"] = 51153024,
            ["GUID"] = "800E6500",
            ["SpeakNpcId"] = 701091,
            ["TalkActionId"] = {
                [1] = "701091:Think_End",
                },
            },
        [51153025] = {
            ["Camera"] = "-218.316406,82.341675,107.538086,0.000017,5.878347,-22.685118,60.0,535.899536,false,Manual,2.8",
            ["Content"] = "陈老兄，哪阵风把你吹来了。久不见面，这一趟出海还顺利吗？",
            ["ContentFR"] = "Eh bien, Chen ! Quel vent t’amène ici ? Cela fait une éternité ! Ton dernier voyage en mer s’est-il bien passé ?",
            ["DialogueId"] = 51153025,
            ["GUID"] = "800E652A",
            ["LookAt"] = {
                [1] = "701092:n(701091)",
                [2] = "701091:n(701092)",
                [3] = "100001:n(701092)",
                },
            ["NextDialogue"] = 51153026,
            ["SpeakNpcId"] = 701092,
            ["TalkActionId"] = {
                [1] = "701092:Talk01_Start",
                },
            },
        [51153026] = {
            ["Content"] = "你不在的日子里，兄弟可挂心你了。为了我们一同长大的交情，我好茶好酒都给你留着，就等你回来一同品尝。",
            ["ContentFR"] = "Pendant ton absence, je pensais souvent à toi. Pour notre vieille amitié, j’ai gardé le meilleur thé et les meilleures liqueurs, en attendant ton retour.",
            ["DialogueId"] = 51153026,
            ["GUID"] = "800E6554",
            ["NextDialogue"] = 51153027,
            ["SpeakNpcId"] = 701092,
            ["TalkActionId"] = {
                [1] = "701092:Talk01_End",
                },
            },
        [51153027] = {
            ["Camera"] = "-499.664062,-243.194458,187.458984,0.000042,-8.200284,15.325444,30.0,410.0,false,Manual,2.8",
            ["Content"] = "来来来二位请坐，请上座！我好好给你讲讲这些日子里发生的事！",
            ["ContentFR"] = "Allez, asseyez-vous, tous les deux ! J’ai tant de choses à raconter !",
            ["DialogueId"] = 51153027,
            ["GUID"] = "800E657E",
            ["NextDialogue"] = 51153028,
            ["SpeakNpcId"] = 701092,
            ["TalkActionId"] = {
                [1] = "701092:Explain01_Start",
                },
            },
        [51153028] = {
            ["Content"] = "（胡老板滔滔不绝地讲述起了近日的见闻，你和陈白沙只能等待着他回过神来……）",
            ["ContentFR"] = "Patron Hu se lance dans un flot ininterrompu d’histoires récentes. Vous et Chen Baisha n’avez d’autre choix que d’attendre qu’il reprenne enfin son souffle...",
            ["DialogueId"] = 51153028,
            ["GUID"] = "800E65A8",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 51153029,
            ["SpeakNpcId"] = 0,
            },
        [51153029] = {
            ["Camera"] = "-133.140625,43.044434,148.704102,0.000039,0.0,-19.0756,50.0,410.0,false,Manual,2.8",
            ["Content"] = "对了老兄，我见到你激动得都忘了，你这趟来是为了什么事？",
            ["ContentFR"] = "Ah, pardon ! J’étais si heureux de te revoir que j’en ai oublié de demander : qu’est-ce qui t’amène aujourd’hui ?",
            ["DialogueId"] = 51153029,
            ["GUID"] = "800E65D2",
            ["NextDialogue"] = 51153030,
            ["SpeakNpcId"] = 701092,
            ["TalkActionId"] = {
                [1] = "701092:Explain01_End",
                },
            },
        [51153030] = {
            ["Camera"] = "305.871094,-370.953125,181.147461,0.000052,-6.399839,115.319542,50.0,440.022095,false,Manual,2.334505",
            ["Content"] = "我来找一款花茶……",
            ["ContentFR"] = "Je cherche un thé aux fleurs—",
            ["DialogueId"] = 51153030,
            ["GUID"] = "800E65FC",
            ["NextDialogue"] = 51153031,
            ["SpeakNpcId"] = 701091,
            ["TalkActionId"] = {
                [1] = "701091:Explain02_Start",
                },
            },
        [51153031] = {
            ["Camera"] = "-133.140625,43.044434,148.704102,0.000039,0.0,-19.0756,50.0,410.0,false,Manual,2.8",
            ["Content"] = "花茶，那还不容易！伙计们，把最好的端上来！",
            ["ContentFR"] = "Un thé aux fleurs ? Facile ! Apportez les meilleurs !",
            ["DialogueId"] = 51153031,
            ["FacialId"] = {
                [1] = "701092:CM_Ahaha01",
                },
            ["GUID"] = "800E6626",
            ["NextDialogue"] = 51153032,
            ["SpeakNpcId"] = 701092,
            ["TalkActionId"] = {
                [1] = "701092:Explain02_Start",
                },
            },
        [51153032] = {
            ["Content"] = "（伙计们一溜烟地端上了十多款花茶。）",
            ["ContentFR"] = "Les employés déposent en un instant plus d’une dizaine de thés différents.",
            ["DialogueId"] = 51153032,
            ["GUID"] = "800E6650",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 51153033,
            ["SpeakNpcId"] = 0,
            ["TalkActionId"] = {
                [1] = "701092:Explain02_End",
                },
            },
        [51153033] = {
            ["Camera"] = "-133.140625,43.044434,148.704102,0.000039,0.0,-19.0756,50.0,410.0,false,Manual,2.8",
            ["Content"] = "陈老兄，你先尝尝这款莲花茶。清晨日未出之时将茶叶置入菡萏中经日，如此反复数次，焙干后，香美异常。",
            ["ContentFR"] = "Chen, mon vieil ami, commence donc par goûter ce thé au lotus. Avant l’aube, nous plaçons les feuilles de thé dans des boutons de lotus frais, nous les y laissons toute la journée, et recommençons ainsi plusieurs fois. Ensuite, nous faisons sécher et torréfier les feuilles. Le parfum qui en résulte est tout simplement exceptionnel.",
            ["DialogueId"] = 51153033,
            ["FacialId"] = {
                [1] = "701092:CM_Smile01",
                },
            ["GUID"] = "800E667A",
            ["NextDialogue"] = 51153034,
            ["SpeakNpcId"] = 701092,
            ["TalkActionId"] = {
                [1] = "701092:Give",
                },
            },
        [51153034] = {
            ["Content"] = "（陈白沙尝了尝这杯莲花茶。）",
            ["ContentFR"] = "Chen Baisha goûte le thé au lotus.",
            ["DialogueId"] = 51153034,
            ["GUID"] = "800E66A4",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 51153035,
            ["SpeakNpcId"] = 0,
            },
        [51153035] = {
            ["Camera"] = "305.871094,-370.953125,181.147461,0.000052,-6.399839,115.319542,50.0,440.022095,false,Manual,2.334505",
            ["Content"] = "确实不错，但是……",
            ["ContentFR"] = "Il est effectivement excellent, mais...",
            ["DialogueId"] = 51153035,
            ["GUID"] = "800E66CE",
            ["NextDialogue"] = 51153036,
            ["SpeakNpcId"] = 701091,
            ["TalkActionId"] = {
                [1] = "701091:Explain02_End",
                },
            },
        [51153036] = {
            ["Camera"] = "-133.140625,43.044434,148.704102,0.000039,0.0,-19.0756,50.0,410.0,false,Manual,2.8",
            ["Content"] = "陈老兄，你再尝尝这款茉莉花茶。九窨一提，汤色黄绿明净，花香清雅，滋味清甜，花叶交错，犹如碧潭飘雪。",
            ["ContentFR"] = "Alors essaie donc ce thé au jasmin. Neuf passages d’imprégnation. La liqueur est d’un jaune-vert limpide, le parfum floral délicat, la saveur douce et fraîche. Fleurs et feuilles s’entrelacent, comme de la neige tombant sur une eau d’émeraude.",
            ["DialogueId"] = 51153036,
            ["GUID"] = "800E66F8",
            ["NextDialogue"] = 51153037,
            ["SpeakNpcId"] = 701092,
            ["TalkActionId"] = {
                [1] = "701092:Give",
                },
            },
        [51153037] = {
            ["Content"] = "（陈白沙又尝了尝这杯茉莉花茶。）",
            ["ContentFR"] = "Chen Baisha goûte le thé au jasmin.",
            ["DialogueId"] = 51153037,
            ["GUID"] = "800E6722",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 51153038,
            ["SpeakNpcId"] = 0,
            },
        [51153038] = {
            ["Camera"] = "305.871094,-370.953125,181.147461,0.000052,-6.399839,115.319542,50.0,440.022095,false,Manual,2.334505",
            ["Content"] = "多谢招待，只是……",
            ["ContentFR"] = "Merci pour ton accueil, mais...",
            ["DialogueId"] = 51153038,
            ["GUID"] = "800E674C",
            ["NextDialogue"] = 51153039,
            ["SpeakNpcId"] = 701091,
            ["TalkActionId"] = {
                [1] = "701091:Think_Start",
                },
            },
        [51153039] = {
            ["Camera"] = "-133.140625,43.044434,148.704102,0.000039,0.0,-19.0756,50.0,410.0,false,Manual,2.8",
            ["Content"] = "陈老兄，你再试试这款桂花茶。汤色通透，滋味醇厚，花茶一体，清雅有蜜香。",
            ["ContentFR"] = "Très bien, très bien, alors goûte celui-ci : le thé à l’osmanthe. Une liqueur claire et lumineuse, une saveur riche et ronde. Ici, le thé et la fleur ne font qu’un, avec un parfum élégant aux notes miellées.",
            ["DialogueId"] = 51153039,
            ["GUID"] = "800E6776",
            ["NextDialogue"] = 51153040,
            ["SpeakNpcId"] = 701092,
            ["TalkActionId"] = {
                [1] = "701092:Give",
                },
            },
        [51153040] = {
            ["Content"] = "（陈白沙只得喝下了这杯桂花茶。）",
            ["ContentFR"] = "Chen Baisha n’a d’autre choix que de boire ce thé à l’osmanthe.",
            ["DialogueId"] = 51153040,
            ["GUID"] = "800E67A0",
            ["IsBlack"] = 1,
            ["LookAt"] = {
                [1] = "701091:n(701091)",
                },
            ["NextDialogue"] = 51153041,
            ["SpeakNpcId"] = 0,
            ["TalkActionId"] = {
                [1] = "701091:Think_End",
                },
            },
        [51153041] = {
            ["Camera"] = "305.871094,-370.953125,181.147461,0.000052,-6.399839,115.319542,50.0,440.022095,false,Manual,2.334505",
            ["Content"] = "好茶是好茶，就是……",
            ["ContentFR"] = "C’est un bon thé, vraiment... mais...",
            ["DialogueId"] = 51153041,
            ["GUID"] = "800E67CA",
            ["NextDialogue"] = 51153042,
            ["SpeakNpcId"] = 701091,
            ["TalkActionId"] = {
                [1] = "701091:Sigh_Start",
                },
            },
        [51153042] = {
            ["Camera"] = "48.894531,-6.67627,173.09668,0.000049,-4.600002,-33.478237,50.0,230.0,false,Manual,2.8",
            ["Content"] = "不合适，对不对？别急，再尝尝这个！",
            ["ContentFR"] = "Pas tout à fait ça, n’est-ce pas ? Ne t’inquiète pas, goûte encore celui-ci !",
            ["DialogueId"] = 51153042,
            ["GUID"] = "800E67F4",
            ["SpeakNpcId"] = 701092,
            ["TalkActionId"] = {
                [1] = "701092:Give",
                },
            },
        [51153043] = {
            ["Content"] = "在胡老板热情的招待下，陈白沙一次性喝下了十多杯不同的花茶。",
            ["ContentFR"] = "Sous l’accueil bien trop enthousiaste de Patron Hu, Chen Baisha finit par boire d’une traite plus d’une dizaine de thés aux fleurs différents.",
            ["DialogueId"] = 51153043,
            ["GUID"] = "800E681E",
            ["SpeakNpcId"] = 0,
            },
        [51153044] = {
            ["Camera"] = "205.382812,225.099731,26.811523,0.000026,3.692967,-111.917961,33.0,237.662262,false,Manual,2.8",
            ["Content"] = "不……嗝……不行了……我再也喝不下了……",
            ["ContentFR"] = "N... non... <I>hic...</> Je n’y arrive plus... Je ne peux vraiment plus rien avaler...",
            ["DialogueId"] = 51153044,
            ["GUID"] = "800E6848",
            ["NextDialogue"] = 51153045,
            ["SpeakNpcId"] = 701091,
            ["TalkActionId"] = {
                [1] = "701091:Onground01_Loop",
                },
            },
        [51153045] = {
            ["Camera"] = "57.484375,110.06665,34.862305,0.0,19.999989,-59.999985,50.000008,327.854492,false,Manual,5.0",
            ["Content"] = "怎么样，找到还可入口的没有？",
            ["ContentFR"] = "Alors ? Y en a-t-il au moins un qui t’ait semblé familier ?",
            ["DialogueId"] = 51153045,
            ["FacialId"] = {
                [1] = "701092:CM_Smile01",
                },
            ["GUID"] = "800E6872",
            ["LookAt"] = {
                [1] = "701092:n(701091)",
                },
            ["NextDialogue"] = 51153046,
            ["SpeakNpcId"] = 701092,
            },
        [51153046] = {
            ["Camera"] = "205.382812,225.099731,26.811523,0.000026,3.692967,-111.917961,33.0,237.662262,false,Manual,2.8",
            ["Content"] = "我……我……嗝……",
            ["ContentFR"] = "Je... je... <I>hic...</>",
            ["DialogueId"] = 51153046,
            ["FacialId"] = {
                [1] = "701091:CM_Sad01",
                },
            ["GUID"] = "800E689C",
            ["LookAt"] = {
                [1] = "701091:n(701092)",
                },
            ["NextDialogue"] = 51153047,
            ["SpeakNpcId"] = 701091,
            },
        [51153047] = {
            ["Camera"] = "419.035156,-105.711426,187.561523,0.000082,-9.999806,-178.116913,50.0,398.468353,false,Manual,5.0",
            ["Content"] = "我来替他说吧，我们在找二十年前浮星埠茶摊子卖的碎末子。",
            ["ContentFR"] = "Je vais parler à sa place. Nous cherchons le thé aux feuilles brisées que l’on vendait au Quai-aux-Étoiles il y a vingt ans.",
            ["DialogueId"] = 51153047,
            ["FacialId"] = {
                [1] = "100001:Happy02",
                },
            ["GUID"] = "800E68C6",
            ["LookAt"] = {
                [1] = "701092:n(100001)",
                [2] = "100001:n(701092)",
                },
            ["NextDialogue"] = 51153048,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Sigh_Start",
                },
            },
        [51153048] = {
            ["Camera"] = "-133.570312,74.551025,127.095703,0.000084,2.000234,-34.916454,50.0,428.920837,false,Manual,2.8",
            ["Content"] = "碎末子？你们找它做什么，又不是什么好东西。",
            ["ContentFR"] = "Des feuilles brisées ? Pourquoi chercher cela ? Ce n’est même pas un bon produit.",
            ["DialogueId"] = 51153048,
            ["FacialId"] = {
                [1] = "701092:Curious",
                },
            ["GUID"] = "800E68F0",
            ["NextDialogue"] = 51153049,
            ["SpeakNpcId"] = 701092,
            ["TalkActionId"] = {
                [1] = "701092:Think_Start",
                },
            },
        [51153049] = {
            ["Camera"] = "419.035156,-105.711426,187.561523,0.000082,-9.999806,-178.116913,50.0,398.468353,false,Manual,5.0",
            ["Content"] = "确实不过是街上摊子卖的大碗茶。只是这位织星客对此念念不忘，一定要找到他所说的“旧时的滋味”不可。",
            ["ContentFR"] = "C’était du thé de rue, vendu en grands bols. Mais pour ce Tisse-Étoiles, ce goût d’antan est irremplaçable.",
            ["DialogueId"] = 51153049,
            ["GUID"] = "800E691A",
            ["NextDialogue"] = 51153050,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Sigh_End",
                },
            },
        [51153050] = {
            ["Camera"] = "57.484375,110.06665,34.862305,0.0,19.999989,-59.999985,50.000008,327.854492,false,Manual,5.0",
            ["Content"] = "陈老兄，这些茶里有哪款让你想起以前的滋味的吗？",
            ["ContentFR"] = "Chen, parmi tous ces thés... y en a-t-il un seul qui t’ait rappelé le goût d’autrefois ?",
            ["DialogueId"] = 51153050,
            ["GUID"] = "800E6944",
            ["LookAt"] = {
                [1] = "701092:n(701091)",
                },
            ["NextDialogue"] = 51153051,
            ["SpeakNpcId"] = 701092,
            ["TalkActionId"] = {
                [1] = "701092:Think_End",
                },
            },
        [51153051] = {
            ["Camera"] = "610.267578,-184.272705,139.628906,0.000035,-9.30713,162.883575,60.0,605.249268,false,Manual,2.8",
            ["Content"] = "一次性……嗝……喝太多，分……嗝……不出来了。",
            ["ContentFR"] = "J’ai trop bu d’un coup... Je n’arrive plus à distinguer les saveurs...",
            ["DialogueId"] = 51153051,
            ["FacialId"] = {
                [1] = "701091:CM_Sad01",
                },
            ["GUID"] = "800E696E",
            ["NextDialogue"] = 51153052,
            ["SpeakNpcId"] = 701091,
            },
        [51153052] = {
            ["Camera"] = "239.548828,50.161377,163.197266,0.000064,-6.400146,-93.912025,30.0,181.281296,false,Manual,5.0",
            ["Content"] = "唉……老兄，让我来替你想想吧。",
            ["ContentFR"] = "Hm... Laisse-moi réfléchir.",
            ["DialogueId"] = 51153052,
            ["FacialId"] = {
                [1] = "701092:CM_Idle",
                },
            ["GUID"] = "800E6998",
            ["NextDialogue"] = 51153053,
            ["SpeakNpcId"] = 701092,
            ["TalkActionId"] = {
                [1] = "701092:Talk01_Start",
                },
            },
        [51153053] = {
            ["Camera"] = "664.539062,942.744019,270.186523,0.000074,-7.000185,72.683929,11.0,327.854492,false,DoNotOverride,5.0",
            ["Content"] = "二十年前，我们俩都还是在蒹葭浦的河滩上赤着脚玩泥巴的野孩子。",
            ["ContentFR"] = "Il y a vingt ans, nous étions encore des gamins pieds nus à jouer dans la boue, sur la rive de la Baie des Roseaux-Pâles.",
            ["DialogueId"] = 51153053,
            ["FinalCamera"] = "664.539062,942.744019,270.186523,-0.0,-7.000185,109.999985,11.000002,327.854492,false,DoNotOverride,5.0",
            ["GUID"] = "800E69C2",
            ["NextDialogue"] = 51153054,
            ["SpeakNpcId"] = 701092,
            ["ToFinalCameraBlendTime"] = 10,
            },
        [51153054] = {
            ["Content"] = "没想到二十年过去，一个往西，一个往东，好几年也见不上一面。",
            ["ContentFR"] = "Qui aurait cru qu’un jour, l’un partirait vers l’ouest, l’autre vers l’est, sans presque jamais se revoir ?",
            ["DialogueId"] = 51153054,
            ["GUID"] = "800E69EC",
            ["NextDialogue"] = 51153055,
            ["SpeakNpcId"] = 701092,
            },
        [51153055] = {
            ["Content"] = "时光飞逝，有什么味道是永久不变的呢……",
            ["ContentFR"] = "Le temps file... Quel goût pourrait rester éternel ?",
            ["DialogueId"] = 51153055,
            ["GUID"] = "800E6A16",
            ["NextDialogue"] = 51153056,
            ["SpeakNpcId"] = 701092,
            },
        [51153056] = {
            ["Camera"] = "388.880859,100.010376,1.513672,0.00003,10.692913,-163.316513,38.0,306.638,false,Manual,2.8",
            ["Content"] = "我……我知道了！",
            ["ContentFR"] = "Je... je sais !",
            ["DialogueId"] = 51153056,
            ["FacialId"] = {
                [1] = "701091:CM_Shock01",
                },
            ["FinalCamera"] = "208.158203,45.84729,37.138672,0.00003,10.692913,-163.316513,38.0,117.599663,false,Manual,2.8",
            ["GUID"] = "800E6A40",
            ["NextDialogue"] = 51153057,
            ["SpeakNpcId"] = 701091,
            ["ToFinalCameraBlendTime"] = 0.2,
            },
        [51153057] = {
            ["Content"] = "（陈白沙迅速地从地上爬了起来，目光炯炯地看着你。）",
            ["ContentFR"] = "Chen Baisha se redresse brusquement, se relevant d’un bond. Son regard, soudain animé, se pose sur vous.",
            ["DialogueId"] = 51153057,
            ["GUID"] = "800E6A6A",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 51153058,
            ["SpeakNpcId"] = 0,
            ["TalkActionId"] = {
                [1] = "701091:Idle",
                },
            },
        [51153058] = {
            ["Camera"] = "172.066406,36.535034,156.958008,0.000033,-6.107124,-151.715576,30.0,185.0,false,Manual,2.8",
            ["Content"] = "{nickname}小友……",
            ["ContentFR"] = "{nickname}, {性别:mon jeune ami|ma jeune amie}...",
            ["DialogueId"] = 51153058,
            ["FacialId"] = {
                [1] = "701091:CM_Smile01",
                },
            ["GUID"] = "800E6A94",
            ["LookAt"] = {
                [1] = "701091:n(100001)",
                [2] = "100001:n(701091)",
                },
            ["NextOptions"] = {
                [1] = 51153059,
                [2] = 51153061,
                },
            ["SpeakNpcId"] = 701091,
            ["TalkActionId"] = {
                [1] = "100001:Confident_Start",
                },
            },
        [51153059] = {
            ["Content"] = "来都来了，就帮忙帮到底吧。",
            ["ContentFR"] = "<I>Puisqu’on est déjà là, autant aller jusqu’au bout.</>",
            ["DialogueId"] = 51153059,
            ["GUID"] = "800E6ABE",
            ["ImprPlusId"] = 1204,
            ["NextDialogue"] = 51153060,
            },
        [51153060] = {
            ["Camera"] = "37.376953,-174.963745,129.658203,0.000059,3.999984,87.884972,30.000002,191.158386,false,Manual,2.8",
            ["Content"] = "多谢小友，等我尝到那旧日花茶，必有重谢！",
            ["ContentFR"] = "Merci, mon {性别:ami|amie}. Lorsque j’aurai retrouvé ce thé d’autrefois et goûté à nouveau sa saveur, je saurai vous récompenser comme il se doit !",
            ["DialogueId"] = 51153060,
            ["GUID"] = "800E6AE8",
            ["SpeakNpcId"] = 701091,
            ["TalkActionId"] = {
                [1] = "701091:Talk01_Start",
                },
            },
        [51153061] = {
            ["Content"] = "再让我跑腿就要收费了！",
            ["ContentFR"] = "<I>Encore une course ? Cette fois, ce sera payant.</>",
            ["DialogueId"] = 51153061,
            ["GUID"] = "800E6B12",
            ["ImprPlusId"] = 1201,
            ["NextDialogue"] = 51153062,
            },
        [51153062] = {
            ["Camera"] = "37.376953,-174.963745,129.658203,0.000059,3.999984,87.884972,30.000002,191.158386,false,Manual,2.8",
            ["Content"] = "一定一定，绝不亏待！",
            ["ContentFR"] = "Bien sûr, bien sûr ! Je ne vous ferai pas perdre votre temps pour rien !",
            ["DialogueId"] = 51153062,
            ["GUID"] = "800E6B3C",
            ["SpeakNpcId"] = 701091,
            ["TalkActionId"] = {
                [1] = "701091:Talk01_Start",
                },
            },
        [51153063] = {
            ["Content"] = "你端着一壶茶来这儿，就是你说的……好主意？",
            ["ContentFR"] = "Venir jusqu’ici avec une théière... c’était donc ça, votre « brillante idée » ?",
            ["DialogueId"] = 51153063,
            ["GUID"] = "800E6B66",
            ["NextDialogue"] = 51153064,
            ["SpeakNpcId"] = 100001,
            },
        [51153064] = {
            ["Content"] = "哈哈，我想明白了。既然想要找那时的味道，自然也要重现当时的情境不是。",
            ["ContentFR"] = "Ha ha ! J’ai compris, enfin. Si je veux retrouver le goût d’alors, il me faut aussi revivre le moment qui l’accompagnait.",
            ["DialogueId"] = 51153064,
            ["GUID"] = "800E6B90",
            ["NextDialogue"] = 51153065,
            ["SpeakNpcId"] = 701091,
            ["TalkActionId"] = {
                [1] = "701091:Talk01_Start",
                },
            },
        [51153065] = {
            ["Content"] = "那时我整日在这片河滩上狂奔，兴许等我跑得渴了累了，就能找到当时的味道了。",
            ["ContentFR"] = "À l’époque, je passais mes journées à courir sur cette rive. Peut-être qu’en courant jusqu’à l’épuisement, la soif me rendra ce goût perdu.",
            ["DialogueId"] = 51153065,
            ["GUID"] = "800E6BBA",
            ["NextDialogue"] = 51153066,
            ["SpeakNpcId"] = 701091,
            },
        [51153066] = {
            ["Content"] = "小友不妨和我来比试一番。",
            ["ContentFR"] = "Si cela vous dit, faisons donc la course ensemble.",
            ["DialogueId"] = 51153066,
            ["GUID"] = "800E6BE4",
            ["SpeakNpcId"] = 701091,
            ["TalkActionId"] = {
                [1] = "701091:Talk01_End",
                },
            },
        [51153067] = {
            ["Content"] = "二十年没在这片河滩上跑过了，今天真是过瘾！",
            ["ContentFR"] = "Voilà vingt ans que je n’avais pas couru sur cette berge... Quel plaisir !",
            ["DialogueId"] = 51153067,
            ["GUID"] = "800E6C0E",
            ["SpeakNpcId"] = 701091,
            },
        [51153068] = {
            ["Content"] = "嘿咻……有点跟不上了……",
            ["ContentFR"] = "Hé... hé... Je commence à peiner...",
            ["DialogueId"] = 51153068,
            ["GUID"] = "800E6C38",
            ["SpeakNpcId"] = 701091,
            },
        [51153069] = {
            ["Content"] = "呼……呼……自愧不如！自愧不如！",
            ["ContentFR"] = "Hah... hah... Je m’avoue vaincu ! Vous êtes bien plus rapide !",
            ["DialogueId"] = 51153069,
            ["GUID"] = "800E6C62",
            ["SpeakNpcId"] = 701091,
            },
        [51153070] = {
            ["Content"] = "（陈白沙大口将茶水灌进了口里，随即累得倒下了。）",
            ["ContentFR"] = "Chen Baisha porte la théière à ses lèvres et boit à grandes gorgées, avant de s’effondrer, épuisé.",
            ["DialogueId"] = 51153070,
            ["GUID"] = "800E6C8C",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 51153071,
            ["SpeakNpcId"] = 0,
            ["TalkActionId"] = {
                [1] = "701091:Onground01_Loop",
                },
            },
        [51153071] = {
            ["Camera"] = "82.539062,236.600586,94.693359,0.000013,-1.542742,-109.15033,38.0,410.739655,false,Manual,2.8",
            ["Content"] = "是你想找的滋味吗？",
            ["ContentFR"] = "Alors ? Est-ce le goût que vous cherchiez ?",
            ["DialogueId"] = 51153071,
            ["FacialId"] = {
                [1] = "100001:Curious",
                },
            ["GUID"] = "800E6CB6",
            ["LookAt"] = {
                [1] = "100001:n(701091)",
                },
            ["NextDialogue"] = 51153072,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:ConfidentLR_Start",
                },
            },
        [51153072] = {
            ["Camera"] = "225.349609,-183.40332,129.71582,0.000022,-14.342556,161.450195,38.0,362.946472,false,Manual,2.8",
            ["Content"] = "有八分像了，还有两分差在哪里呢……",
            ["ContentFR"] = "À huit parts près... Il en manque encore deux...",
            ["DialogueId"] = 51153072,
            ["GUID"] = "800E6CE0",
            ["LookAt"] = {
                [1] = "701091:n(100001)",
                },
            ["NextDialogue"] = 51153073,
            ["SpeakNpcId"] = 701091,
            },
        [51153073] = {
            ["Camera"] = "225.349609,-183.40332,129.71582,0.000022,-14.342556,161.450195,38.0,362.946472,false,Manual,2.8",
            ["Content"] = "我记得……记得……",
            ["ContentFR"] = "Je me souviens... Oui... je me souviens...",
            ["DialogueId"] = 51153073,
            ["GUID"] = "800E6D0A",
            ["LookAt"] = {
                [1] = "701091:n(701091)",
                },
            ["NextDialogue"] = 51153074,
            ["SpeakNpcId"] = 701091,
            },
        [51153074] = {
            ["Camera"] = "82.539062,236.600586,94.693359,0.000013,-1.542742,-109.15033,38.0,410.739655,false,Manual,2.8",
            ["Content"] = "你回想起了什么？",
            ["ContentFR"] = "De quoi vous rappelez-vous ?",
            ["DialogueId"] = 51153074,
            ["FacialId"] = {
                [1] = "100001:Doubt01",
                },
            ["GUID"] = "800E6D34",
            ["NextDialogue"] = 51153075,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:TilteHead_Start",
                [2] = "100001:ConfidentLRToExplainL_Start",
                },
            },
        [51153075] = {
            ["Camera"] = "-105.767578,-54.1875,3088.036133,0.0,12.999988,42.650269,11.0,362.946472,false,DoNotOverride,2.8",
            ["Content"] = "我想起十数年前，蒹葭浦还没犯烛阴之灾的日子。我和伙伴一同在河滩上玩泥沙、磨螺壳的时候。",
            ["ContentFR"] = "D’il y a plus de dix ans. À l’époque où la Baie des Roseaux-Pâles n’avait pas encore subi le Fléau de Zhuyin. Quand mes compagnons et moi jouions dans la boue, polissions des coquilles sur cette rive.",
            ["DialogueId"] = 51153075,
            ["FinalCamera"] = "-2100.933594,-1892.0625,2461.760742,0.0,12.999988,42.650452,11.000002,362.946472,false,DoNotOverride,2.8",
            ["GUID"] = "800E6D5E",
            ["NextDialogue"] = 51153076,
            ["SpeakNpcId"] = 701091,
            ["ToFinalCameraBlendTime"] = 10,
            },
        [51153076] = {
            ["Content"] = "我想起那时也是这样的天，白云悠悠从头顶飘过。似乎永无烦恼，永无忧虑。",
            ["ContentFR"] = "Le ciel était exactement comme aujourd’hui. Des nuages blancs glissaient lentement au-dessus de nos têtes. On aurait dit que les soucis n’existaient pas encore.",
            ["DialogueId"] = 51153076,
            ["GUID"] = "800E6D88",
            ["NextDialogue"] = 51153077,
            ["SpeakNpcId"] = 701091,
            ["TalkActionId"] = {
                [1] = "100001:TilteHead_End",
                },
            },
        [51153077] = {
            ["Content"] = "是从什么时候开始，我决定当一名织星客的呢……又是从什么时候开始，我们各奔东西，各自万里未归，异乡为客的呢……",
            ["ContentFR"] = "À quel moment ai-je décidé de devenir un Tisse-Étoiles... Et à partir de quand avons-nous suivi chacun notre route, partant aux quatre coins du monde, sans jamais rentrer vraiment chez nous ?",
            ["DialogueId"] = 51153077,
            ["GUID"] = "800E6DB2",
            ["NextDialogue"] = 51153078,
            ["SpeakNpcId"] = 701091,
            },
        [51153078] = {
            ["Camera"] = "0.871094,-16.166992,127.25293,0.000021,-6.342841,-89.151169,38.000008,179.802216,false,Manual,2.8",
            ["Content"] = "你最早喝到这碗茶，是在什么时候？",
            ["ContentFR"] = "Quand avez-vous bu ce thé pour la toute première fois ?",
            ["DialogueId"] = 51153078,
            ["GUID"] = "800E6DDC",
            ["NextDialogue"] = 51153079,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:ConfidentLRToExplainL_End",
                },
            },
        [51153079] = {
            ["Camera"] = "7466.974609,-3541.548828,3565.794922,0.0,-6.200104,-34.800346,11.0,362.946472,false,DoNotOverride,2.8",
            ["Content"] = "我年幼时，有一次父亲带着我，沿着蒹葭浦走去浮星埠看船。路途遥远，我累极了，也兴奋极了。",
            ["ContentFR"] = "Quand j’étais enfant. Un jour, mon père m’a emmené à pied, le long de la Baie des Roseaux-Pâles, jusqu’au Quai-aux-Étoiles, pour voir les navires. Le trajet était long. J’étais épuisé... mais aussi terriblement excité.",
            ["DialogueId"] = 51153079,
            ["FinalCamera"] = "10758.478516,-5829.231445,3130.332031,0.0,-6.200104,-34.800346,11.0,362.946472,false,DoNotOverride,2.8",
            ["GUID"] = "800E6E06",
            ["NextDialogue"] = 51153080,
            ["SpeakNpcId"] = 701091,
            ["ToFinalCameraBlendTime"] = 10,
            },
        [51153080] = {
            ["Content"] = "我们在茶摊喝茶，不远处的大海波光粼粼，商船穿梭往来，码头上人声喧哗，还是孩子的我，一下被这场景所深深吸引。",
            ["ContentFR"] = "Nous avons bu du thé à une échoppe. Non loin de là, la mer scintillait, les navires marchands allaient et venaient, le port bruissait de voix. Moi qui n’étais encore qu’un enfant, je suis resté fasciné par ce spectacle.",
            ["DialogueId"] = 51153080,
            ["GUID"] = "800E6E30",
            ["NextDialogue"] = 51153081,
            ["SpeakNpcId"] = 701091,
            ["TalkActionId"] = {
                [1] = "100001:ConfidentLR_End",
                },
            },
        [51153081] = {
            ["Content"] = "也许从第一次见到大海起，就注定了我未来会远远地离开这片土地，走到天涯海角去。",
            ["ContentFR"] = "Peut-être qu’à l’instant même où j’ai vu la mer pour la première fois, mon destin était déjà scellé. Quitter cette terre, aller jusqu’aux confins du monde.",
            ["DialogueId"] = 51153081,
            ["GUID"] = "800E6E5A",
            ["NextDialogue"] = 51153082,
            ["SpeakNpcId"] = 701091,
            },
        [51153082] = {
            ["Content"] = "但是再一次见到这片天空，还是会感慨万千啊……",
            ["ContentFR"] = "Et pourtant... revoir aujourd’hui ce même ciel me remplit encore d’émotion...",
            ["DialogueId"] = 51153082,
            ["GUID"] = "800E6E84",
            ["NextDialogue"] = 51153083,
            ["SpeakNpcId"] = 701091,
            },
        [51153083] = {
            ["Content"] = "（陈白沙默然不语，在地上躺了好一会儿，似乎在深思些什么。）",
            ["ContentFR"] = "Chen Baisha se tait. Il reste allongé longtemps, le regard perdu dans le ciel, comme plongé dans ses pensées.",
            ["DialogueId"] = 51153083,
            ["GUID"] = "800E6EAE",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 51153084,
            ["SpeakNpcId"] = 0,
            ["TalkActionId"] = {
                [1] = "701091:Idle",
                },
            },
        [51153084] = {
            ["Camera"] = "308.283203,-261.548828,90.578125,0.000047,4.057549,157.051544,30.0,450.096558,false,Manual,2.8",
            ["Content"] = "小友，我明白了。",
            ["ContentFR"] = "Mon {性别:ami|amie}... j’ai compris.",
            ["DialogueId"] = 51153084,
            ["GUID"] = "800E6ED8",
            ["LookAt"] = {
                [1] = "701091:n(100001)",
                },
            ["NextDialogue"] = 51153085,
            ["SpeakNpcId"] = 701091,
            ["TalkActionId"] = {
                [1] = "701091:Explain02_Start",
                },
            },
        [51153085] = {
            ["Camera"] = "308.283203,-261.548828,90.578125,0.000047,4.057549,157.051544,30.0,450.096558,false,Manual,2.8",
            ["Content"] = "再也不会有和从前一模一样的茶叶的味道了，就像不会有和从前一样的日子。",
            ["ContentFR"] = "Il n’existera plus jamais de thé ayant exactement le même goût qu’autrefois. Pas plus qu’il n’existera de jours semblables à ceux du passé.",
            ["DialogueId"] = 51153085,
            ["GUID"] = "800E6F02",
            ["NextDialogue"] = 51153086,
            ["SpeakNpcId"] = 701091,
            },
        [51153086] = {
            ["Camera"] = "308.283203,-261.548828,90.578125,0.000047,4.057549,157.051544,30.0,450.096558,false,Manual,2.8",
            ["Content"] = "我所怀念的不过是逝去的岁月，和再也回不去的小时候。",
            ["ContentFR"] = "Ce que je regrette, ce ne sont pas les feuilles de thé... mais le temps révolu, et l’enfance à laquelle je ne pourrai jamais revenir.",
            ["DialogueId"] = 51153086,
            ["GUID"] = "800E6F2C",
            ["NextDialogue"] = 51153087,
            ["SpeakNpcId"] = 701091,
            ["TalkActionId"] = {
                [1] = "701091:Explain02_End",
                },
            },
        [51153087] = {
            ["Camera"] = "-58.130859,194.003906,181.458984,0.000058,-9.342407,-86.547867,30.0,228.692245,false,Manual,2.8",
            ["Content"] = "再见了，小友，这些报酬你请收好。",
            ["ContentFR"] = "Adieu, mon {性别:ami|amie}. Veuillez accepter ces récompenses.",
            ["DialogueId"] = 51153087,
            ["GUID"] = "800E6F56",
            ["LookAt"] = {
                [1] = "701091:n(701091)",
                },
            ["NextDialogue"] = 51153088,
            ["Scripts"] = "SEQ{\
TurnTo{TurnToDescription{\"701091:p(-180)\"}},   PlayAnimation{ActorId{100001},AnimationId{\"RaiseHand_Start\"}}\
}",
            ["SpeakNpcId"] = 701091,
            },
        [51153088] = {
            ["Camera"] = "18.898438,5.989258,151.822266,0.000043,-13.742524,-94.34774,30.0,192.427872,false,Manual,2.8",
            ["Content"] = "你要去哪里？",
            ["ContentFR"] = "Où allez-vous, maintenant ?",
            ["DialogueId"] = 51153088,
            ["FacialId"] = {
                [1] = "100001:Curious",
                },
            ["GUID"] = "800E6F80",
            ["NextDialogue"] = 51153089,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:RaiseHand_End",
                },
            },
        [51153089] = {
            ["Camera"] = "-104.441406,157.805664,256.822266,0.000024,-24.942291,-76.543663,50.0,400.0,false,Manual,2.8",
            ["Content"] = "已经过去的不可再追回，现在的一切尚在手中。",
            ["ContentFR"] = "Ce qui est passé ne peut être rattrapé. Mais ce qui est présent, je peux encore le saisir.",
            ["DialogueId"] = 51153089,
            ["FinalCamera"] = "-104.441406,157.805664,256.822266,0.000024,-24.942291,-76.543663,50.0,210.0,false,Manual,2.8",
            ["GUID"] = "800E6FAA",
            ["NextDialogue"] = 51153090,
            ["SpeakNpcId"] = 701091,
            ["TalkActionId"] = {
                [1] = "701091:Disagree",
                },
            ["ToFinalCameraBlendTime"] = 5,
            },
        [51153090] = {
            ["Content"] = "我已经喝不到二十年前的茶了，但是我现在仍然能和我的父亲一起散步、谈天说地、走去港口看船。",
            ["ContentFR"] = "Je ne boirai sans doute plus jamais le thé d’il y a vingt ans. Mais je peux encore marcher avec mon père, discuter en chemin, et aller ensemble regarder les navires quitter le port.",
            ["DialogueId"] = 51153090,
            ["GUID"] = "800E6FD4",
            ["NextDialogue"] = 51153091,
            ["SpeakNpcId"] = 701091,
            },
        [51153091] = {
            ["Camera"] = "609.125,169.490234,2.267578,0.0,7.999989,-155.538208,34.0,720.492676,false,Manual,2.8",
            ["Content"] = "我要回家了。",
            ["ContentFR"] = "Je rentre chez moi.",
            ["DialogueId"] = 51153091,
            ["GUID"] = "800E6FFE",
            ["SpeakNpcId"] = 701091,
            ["TalkActionId"] = {
                [1] = "701091:Explain02_Start",
                },
            },
        [51153092] = {
            ["Content"] = "如今的浮星埠，比二十年前父亲带我来看船时更加热闹了。",
            ["ContentFR"] = "Le Quai-aux-Étoiles est encore plus animé qu’autrefois... Bien plus que lorsque tu m’y avais conduit pour voir les navires, il y a vingt ans, père.",
            ["DialogueId"] = 51153092,
            ["GUID"] = "800E6FFF",
            ["SpeakNpcId"] = 701098,
            },
        [51153093] = {
            ["Content"] = "二十年过去，这里也成了你出发的地方了……",
            ["ContentFR"] = "Vingt ans ont passé... et c’est d’ici que commence ton nouveau voyage.",
            ["DialogueId"] = 51153093,
            ["GUID"] = "800E7000",
            ["SpeakNpcId"] = 701099,
            },
        [51153094] = {
            ["Content"] = "小友，还是我略胜一筹！",
            ["ContentFR"] = "{性别:Mon jeune ami|Ma jeune amie}, il faut croire que j’avais une longueur d’avance.",
            ["DialogueId"] = 51153094,
            ["GUID"] = "800E7001",
            ["SpeakNpcId"] = 701091,
            },
        [51154001] = {
            ["Content"] = "我就知道你会再来找我。",
            ["ContentFR"] = "Je savais que tu reviendrais me voir.",
            ["DialogueId"] = 51154001,
            ["GUID"] = "800F054A",
            ["NextOptions"] = {
                [1] = 51154002,
                [2] = 51154003,
                },
            ["SpeakNpcId"] = 701096,
            },
        [51154002] = {
            ["Content"] = "说吧，还有什么事。",
            ["ContentFR"] = "<I>Très bien. Dites-moi, qu’avez-vous encore à me proposer ?</>",
            ["DialogueId"] = 51154002,
            ["GUID"] = "800F0574",
            ["ImprPlusId"] = 1208,
            ["NextDialogue"] = 51154004,
            },
        [51154003] = {
            ["Content"] = "你笑得太恶心了，到底还想说什么。",
            ["ContentFR"] = "<I>Ce sourire est franchement malsain. Dites-moi plutôt ce que vous voulez.</>",
            ["DialogueId"] = 51154003,
            ["GUID"] = "800F059E",
            ["ImprPlusId"] = 1210,
            ["NextDialogue"] = 51154004,
            },
        [51154004] = {
            ["Content"] = "不用如此戒备，既然提到投资，自然是要再为你提供一些切实的便利。",
            ["ContentFR"] = "Inutile d’être si sur tes gardes. Puisqu’il est question d’investissement, il est naturel que je t’offre quelques avantages... un peu plus concrets.",
            ["DialogueId"] = 51154004,
            ["GUID"] = "800F05C8",
            ["NextDialogue"] = 51154005,
            ["SpeakNpcId"] = 701096,
            },
        [51154005] = {
            ["Content"] = "小友且看我这件藏品。",
            ["ContentFR"] = "Approche, et regarde donc l’une des pièces de ma collection.",
            ["DialogueId"] = 51154005,
            ["GUID"] = "800F05F2",
            ["NextDialogue"] = 51154006,
            ["SpeakNpcId"] = 701096,
            },
        [51154006] = {
            ["Content"] = "玄色狴犴！",
            ["ContentFR"] = "Un Bi’an ?!",
            ["DialogueId"] = 51154006,
            ["GUID"] = "800F061C",
            ["NextDialogue"] = 51154007,
            ["SpeakNpcId"] = 100001,
            },
        [51154007] = {
            ["Content"] = "哈哈哈哈，放心。我虽手眼通天，但也有一些力所不及的憾事，就比如我的珍藏里始终少了一只<H>真正的玄色狴犴</>。",
            ["ContentFR"] = "Ha ha ha... Du calme. Même avec les réseaux dont je dispose, certaines choses restent hors de portée. Par exemple... un <H>véritable Bi’an</>. Ma collection a toujours souffert de cette absence.",
            ["DialogueId"] = 51154007,
            ["GUID"] = "800F0646",
            ["NextDialogue"] = 51154008,
            ["SpeakNpcId"] = 701096,
            },
        [51154008] = {
            ["Content"] = "你眼前的玄色狴犴，不过是一个徒有其表的样子货罢了。",
            ["ContentFR"] = "Celui que tu vois là n’est, en réalité, qu’un simple objet d’apparat.",
            ["DialogueId"] = 51154008,
            ["GUID"] = "800F0670",
            ["NextDialogue"] = 51154009,
            ["SpeakNpcId"] = 701096,
            },
        [51154009] = {
            ["Content"] = "样子货？",
            ["ContentFR"] = "Une contrefaçon ?",
            ["DialogueId"] = 51154009,
            ["GUID"] = "800F069A",
            ["NextDialogue"] = 51154010,
            ["SpeakNpcId"] = 100001,
            },
        [51154010] = {
            ["Content"] = "哦，这么说可能会让公尚师傅急得跳脚了。要说“样子货”也有点折辱了它，这多少还算得上是机枢派智慧的结晶。",
            ["ContentFR"] = "Oh... formulé ainsi, tu ferais bondir le pauvre Maître Gongshang. Employer ce terme serait même lui faire offense. Disons plutôt qu’il s’agit d’un condensé du génie de la Secte Jishu.",
            ["DialogueId"] = 51154010,
            ["GUID"] = "800F06C4",
            ["NextDialogue"] = 51154011,
            ["SpeakNpcId"] = 701096,
            },
        [51154011] = {
            ["Content"] = "它的运作原理繁琐冗长，想必你也不感兴趣。你只需要知道，公尚师傅打磨了很多年才让它像狴犴一样动起来。",
            ["ContentFR"] = "Son fonctionnement est d’une complexité fastidieuse. Je doute que ces détails t’intéressent. Contente-toi de savoir que Maître Gongshang a passé des années à le perfectionner, jusqu’à lui donner les mouvements d’un véritable Bi’an.",
            ["DialogueId"] = 51154011,
            ["GUID"] = "800F06EE",
            ["NextDialogue"] = 51154012,
            ["SpeakNpcId"] = 701096,
            },
        [51154012] = {
            ["Content"] = "只可惜，公尚师傅一开始造的那几只拟真狴犴，引来了悬衡派一群无聊的老顽固，念叨着什么“渎神”、“不敬”之类的，给他没收了，无趣。",
            ["ContentFR"] = "Quel dommage... Les premiers Bi’an obscurs mécanisés façonnés par Maître Gongshang ont attiré une bande de vieux grincheux de la Secte Xuanheng. Ils n’ont cessé de marmonner des absurdités sur le « blasphème » et le « manque de respect », avant de tout confisquer. Quelle platitude.",
            ["DialogueId"] = 51154012,
            ["GUID"] = "800F06EF",
            ["NextDialogue"] = 51154024,
            ["SpeakNpcId"] = 701096,
            },
        [51154013] = {
            ["Content"] = "要不要骑上它试上一试？华胥幅员辽阔，小友全凭一双脚又能走到何处。就算日后去了其他地方，它也能充当你上天入地、纵情奔走的不错助力。",
            ["ContentFR"] = "Que dirais-tu de l’essayer ? Huaxu est vaste. Avec tes seules jambes, tu n’iras pas bien loin. Et même si un jour tu quittes ces terres, il pourra devenir pour toi un allié fidèle, capable de te porter aussi bien sur terre que dans les airs.",
            ["DialogueId"] = 51154013,
            ["GUID"] = "800F0742",
            ["NextOptions"] = {
                [1] = 51154014,
                [2] = 51154015,
                [3] = 51154016,
                },
            ["SpeakNpcId"] = 701096,
            },
        [51154014] = {
            ["Content"] = "你想要多少钱？",
            ["ContentFR"] = "<I>Combien cela va-t-il me coûter ?</>",
            ["DialogueId"] = 51154014,
            ["GUID"] = "800F076C",
            ["ImprPlusId"] = 1206,
            ["NextDialogue"] = 51154017,
            },
        [51154015] = {
            ["Content"] = "我是狩月人，白送我。",
            ["ContentFR"] = "<I>Je suis Chasseur de Phoxène. Vous pourriez me l’offrir.</>",
            ["DialogueId"] = 51154015,
            ["GUID"] = "800F0796",
            ["ImprPlusId"] = 1210,
            ["NextDialogue"] = 51154017,
            },
        [51154016] = {
            ["Content"] = "这么好的东西，应该不会随随便便送给我吧。",
            ["ContentFR"] = "<I>Un tel objet ne se donne sûrement pas sans contrepartie.</>",
            ["DialogueId"] = 51154016,
            ["GUID"] = "800F07C0",
            ["ImprPlusId"] = 1207,
            ["NextDialogue"] = 51154017,
            },
        [51154017] = {
            ["Content"] = "呵呵，白送的东西就是天底下最贵的东西，我若是直接给，你也不敢直接收吧。",
            ["ContentFR"] = "Héhé... Ce qui est donné gratuitement est toujours ce qu’il y a de plus coûteux au monde. Si je te l’offrais sans condition, tu hésiterais à l’accepter. Et tu aurais raison de te méfier.",
            ["DialogueId"] = 51154017,
            ["GUID"] = "800F07EA",
            ["NextDialogue"] = 51154018,
            ["SpeakNpcId"] = 701096,
            },
        [51154018] = {
            ["Content"] = "诶诶？原来本魔王大人送出去的东西这么珍贵吗！",
            ["ContentFR"] = "Héhé ? Alors ça veut dire que tout ce que le grand Roi Démon offre est inestimable ?!",
            ["DialogueId"] = 51154018,
            ["GUID"] = "800F0814",
            ["NextDialogue"] = 51154019,
            ["SpeakNpcId"] = 200002,
            },
        [51154019] = {
            ["Content"] = "哈哈哈哈哈，这是皎皎之民的幽默吗，有意思，真是有意思。",
            ["ContentFR"] = "Ha ha ha ha... Est-ce donc là l’humour des Lunariens ? Intéressant. Vraiment intéressant.",
            ["DialogueId"] = 51154019,
            ["GUID"] = "800F083E",
            ["NextDialogue"] = 51154020,
            ["SpeakNpcId"] = 701096,
            },
        [51154020] = {
            ["Content"] = "呜哇啊啊啊，小仆从救命，他看起来要吃了我一样！",
            ["ContentFR"] = "<I>Uwaaah !</> Petit larbin, à l’aide ! Il me regarde comme s’il allait me croquer !",
            ["DialogueId"] = 51154020,
            ["GUID"] = "800F0868",
            ["NextDialogue"] = 51154021,
            ["SpeakNpcId"] = 200002,
            },
        [51154021] = {
            ["Content"] = "好，好，好。作为博我一笑的报酬，这“假狴犴”我就不收你钱了。",
            ["ContentFR"] = "Très bien... très bien. Puisque tu as su m’arracher un rire... je consens à ne pas te faire payer ce \"faux Bi’an\".",
            ["DialogueId"] = 51154021,
            ["GUID"] = "800F0892",
            ["NextDialogue"] = 51154022,
            ["SpeakNpcId"] = 701096,
            },
        [51154022] = {
            ["Content"] = "言尽于此，慢走不送。日后若是有什么其他想要的珍藏，或是关于珍藏有什么疑问的话，再来这里找我吧。",
            ["ContentFR"] = "Sur ce, je ne te retiens pas davantage. Si un jour tu convoites une autre pièce de ma collection, ou si une curiosité te prend à leur sujet... reviens me voir.",
            ["DialogueId"] = 51154022,
            ["GUID"] = "800F08BC",
            ["NextDialogue"] = 51154023,
            ["SpeakNpcId"] = 701096,
            },
        [51154023] = {
            ["Content"] = "微茫市的大门，随时为你敞开。",
            ["ContentFR"] = "Les portes du Marché Voilé te seront toujours ouvertes.",
            ["DialogueId"] = 51154023,
            ["GUID"] = "800F08E6",
            ["SpeakNpcId"] = 701096,
            },
        [51154024] = {
            ["Content"] = "但公尚对他的拟真狴犴宝贝得很，怎么舍得就此放弃。所以后来的拟真狴犴啊，他都做成了玄色狴犴的样子，那些香官才不得不作罢。",
            ["ContentFR"] = "Mais Maître Gongshang tenait énormément à ses Bi’an obscurs mécanisés ; comment aurait-il pu s’en défaire aussi facilement ? C’est pourquoi, par la suite, il façonna tous ses Bi’an obscurs mécanisés à l’image du Bi’an noir, contraignant ainsi les officiants de l’encens à renoncer.",
            ["DialogueId"] = 51154024,
            ["GUID"] = "800F0718",
            ["NextDialogue"] = 51154013,
            ["SpeakNpcId"] = 701096,
            },
        [51155001] = {
            ["Content"] = "小仆从小仆从，你刚刚听到没有！",
            ["ContentFR"] = "Petit larbin, tu as entendu ça à l’instant ?!",
            ["DialogueId"] = 51155001,
            ["GUID"] = "800FA95A",
            ["NextDialogue"] = 51155002,
            ["SpeakNpcId"] = 200002,
            },
        [51155002] = {
            ["Content"] = "听到什么？",
            ["ContentFR"] = "Entendu quoi ?",
            ["DialogueId"] = 51155002,
            ["GUID"] = "800FA984",
            ["NextDialogue"] = 51155003,
            ["SpeakNpcId"] = 100001,
            },
        [51155003] = {
            ["Content"] = "“大烟花”！！",
            ["ContentFR"] = "Le « Coup de Grâce » !",
            ["DialogueId"] = 51155003,
            ["GUID"] = "800FA9AE",
            ["NextDialogue"] = 51155004,
            ["SpeakNpcId"] = 200002,
            },
        [51155004] = {
            ["Content"] = "刚刚黑市那个家伙在用通讯器和同伙聊天，说他们从帝国进了一批“大烟花”的货！那可是“大烟花”啊——",
            ["ContentFR"] = "Le type du marché noir parlait sur son communicateur. Il disait qu’ils avaient fait entrer depuis l’Empire Hyperboréen tout un lot de « Coup de Grâce » ! Tout un lot, tu te rends compte ?!",
            ["DialogueId"] = 51155004,
            ["GUID"] = "800FA9D8",
            ["NextDialogue"] = 51155005,
            ["SpeakNpcId"] = 200002,
            },
        [51155005] = {
            ["Content"] = "你记得吧？狩月人委托排行榜上，最危险、最艰辛、最有挑战性的委托之一，就是拆掉神弃者同盟安装的超级危险炸弹“大烟花”！",
            ["ContentFR"] = "Tu te souviens, hein ? Sur le tableau des missions des Chasseurs de Phoxène, l’une des missions les plus dangereuses, les plus pénibles, les plus infernales... c’est bien de désamorcer les bombes ultra-dangereuses installées par les Déchus, ces machins appelés « Coup de Grâce » !",
            ["DialogueId"] = 51155005,
            ["GUID"] = "800FAA02",
            ["NextDialogue"] = 51155006,
            ["SpeakNpcId"] = 200002,
            },
        [51155006] = {
            ["Content"] = "要是在这里爆炸了，不知道会炸死多少人！这里的摊子通通都要被炸上天！天啊，这简直就是——烟津渡史上最大危机！",
            ["ContentFR"] = "Si ça explose ici, tu imagines le nombre de morts ?! Tous les étals vont être pulvérisés ! Tout va voler en éclats ! C’est... c’est... la plus grande crise de l’histoire de Port-des-Brumes !",
            ["DialogueId"] = 51155006,
            ["GUID"] = "800FAA2C",
            ["NextOptions"] = {
                [1] = 51155007,
                [2] = 51155008,
                },
            ["SpeakNpcId"] = 200002,
            },
        [51155007] = {
            ["Content"] = "没想到黑市的人居然如此猖狂，必须去阻止他。",
            ["ContentFR"] = "<I>Le marché noir agit vraiment sans limites. Il faut l’arrêter.</>",
            ["DialogueId"] = 51155007,
            ["GUID"] = "800FAA56",
            ["ImprPlusId"] = 1207,
            ["NextDialogue"] = 51155009,
            },
        [51155008] = {
            ["Content"] = "那完了，我们跑路吧。",
            ["ContentFR"] = "<I>C’est fichu. On ferait mieux de déguerpir.</>",
            ["DialogueId"] = 51155008,
            ["GUID"] = "800FAA80",
            ["ImprPlusId"] = 1210,
            ["NextDialogue"] = 51155009,
            },
        [51155009] = {
            ["Content"] = "其他人好像还没意识到问题的严重性，这种时候只能靠小仆从和本魔王大人来拯救世界了！",
            ["ContentFR"] = "Personne n’a l’air de réaliser la gravité de la situation... Dans des moments pareils, il n’y a que le grand Roi Démon et son fidèle petit larbin pour sauver le monde !",
            ["DialogueId"] = 51155009,
            ["GUID"] = "800FAAAA",
            ["SpeakNpcId"] = 200002,
            },
        [51155010] = {
            ["Content"] = "这次的大烟花……",
            ["ContentFR"] = "Parlez au PNJ affichant la bulle « Cette fois, le Coup de Grâce... ».",
            ["DialogueId"] = 51155010,
            ["GUID"] = "800FAAD4",
            ["SpeakNpcId"] = 701095,
            },
        [51155101] = {
            ["Content"] = "我们先去跟他接触一下，稳住他，探探口风。要是把他逼急了直接在这种地方引爆“大烟花”，那就危险了。",
            ["ContentFR"] = "Allons d’abord lui parler. Restons calmes, sondons le terrain. S’il panique et en déclenche une ici, ce sera un désastre.",
            ["DialogueId"] = 51155101,
            ["GUID"] = "800FB9C2",
            ["SpeakNpcId"] = 100001,
            },
        [51155201] = {
            ["Content"] = "听说你这里能买到“大烟花”？",
            ["ContentFR"] = "J’ai entendu dire que tu pouvais te procurer des « Coups de Grâce ».",
            ["DialogueId"] = 51155201,
            ["GUID"] = "800FCA2A",
            ["NextDialogue"] = 51155202,
            ["SpeakNpcId"] = 100001,
            },
        [51155202] = {
            ["Content"] = "……什么人？谁介绍你来的？",
            ["ContentFR"] = "... Qui es-tu ? Et qui t’a envoyé ici ?",
            ["DialogueId"] = 51155202,
            ["GUID"] = "800FCA54",
            ["NextOptions"] = {
                [1] = 51155203,
                [2] = 51155204,
                },
            ["SpeakNpcId"] = 701093,
            },
        [51155203] = {
            ["Content"] = "别紧张，我也想买枚“大烟花”。",
            ["ContentFR"] = "<I>Pas de panique. Je veux juste en acheter.</>",
            ["DialogueId"] = 51155203,
            ["GUID"] = "800FCA7E",
            ["ImprPlusId"] = 1207,
            ["NextDialogue"] = 51155205,
            },
        [51155204] = {
            ["Content"] = "我可是虬先生的贵客。",
            ["ContentFR"] = "<I>Je suis </>{性别:<I>un invité</>|<I>une invitée</>} <I>de marque de Maître Qiu.</>",
            ["DialogueId"] = 51155204,
            ["GUID"] = "800FCAA8",
            ["ImprPlusId"] = 1208,
            ["NextDialogue"] = 51155205,
            },
        [51155205] = {
            ["Content"] = "……你？看着很是面生。对不住了，咱家的货只卖熟人。",
            ["ContentFR"] = "... Vraiment ? Ton visage ne me dit rien. Désolé, je ne traite qu’avec des habitués.",
            ["DialogueId"] = 51155205,
            ["GUID"] = "800FCAD2",
            ["NextDialogue"] = 51155206,
            ["SpeakNpcId"] = 701093,
            },
        [51155206] = {
            ["Content"] = "小仆从小仆从，不行啊，这样他要怀疑我们了……",
            ["ContentFR"] = "Petit larbin... Ça ne va pas du tout, là... Il commence à se méfier !",
            ["DialogueId"] = 51155206,
            ["GUID"] = "800FCAFC",
            ["NextOptions"] = {
                [1] = 51155207,
                [2] = 51155208,
                },
            ["SpeakNpcId"] = 200002,
            },
        [51155207] = {
            ["Content"] = "谨慎是没错，但也没必要跟钱过不去吧。",
            ["ContentFR"] = "<I>La prudence, c’est bien. Mais l’argent reste l’argent, non ?</>",
            ["DialogueId"] = 51155207,
            ["GUID"] = "800FCB26",
            ["ImprPlusId"] = 1206,
            ["NextDialogue"] = 51155209,
            },
        [51155208] = {
            ["Content"] = "好你在这等着，我去叫秦虬那老东西来一趟。",
            ["ContentFR"] = "<I>Très bien. Attends ici. Je vais aller ramener Maître Qiu, ce vieux schnock, et tu lui demanderas toi-même.</>",
            ["DialogueId"] = 51155208,
            ["GUID"] = "800FCB50",
            ["ImprPlusId"] = 1210,
            ["NextDialogue"] = 51155209,
            },
        [51155209] = {
            ["Content"] = "嘶……行吧行吧，今天我就破个例，勉为其难地卖你好了。但你记得，出去以后，别说这“大烟花”是在微茫市买的。",
            ["ContentFR"] = "<I>Tss...</> d’accord, d’accord. Pour une fois, je fais une exception. Mais écoute bien. Une fois dehors, tu ne dis à personne que ces « Coups de Grâce » viennent du Marché Voilé.",
            ["DialogueId"] = 51155209,
            ["GUID"] = "800FCB7A",
            ["NextDialogue"] = 51155210,
            ["SpeakNpcId"] = 701093,
            },
        [51155210] = {
            ["Content"] = "不然坏了我和老主顾们定下的规矩，我到时候也不好给其他人交代。",
            ["ContentFR"] = "Sinon, je romps les règles avec mes anciens clients, et là, je ne pourrai plus rendre de comptes à personne.",
            ["DialogueId"] = 51155210,
            ["GUID"] = "800FCBA4",
            ["NextDialogue"] = 51155211,
            ["SpeakNpcId"] = 701093,
            },
        [51155211] = {
            ["Content"] = "啊？？很，很多人买吗？",
            ["ContentFR"] = "Hein ? Beaucoup de gens en achètent ?",
            ["DialogueId"] = 51155211,
            ["GUID"] = "800FCBCE",
            ["NextDialogue"] = 51155212,
            ["SpeakNpcId"] = 100001,
            },
        [51155212] = {
            ["Content"] = "不然呢，这烛阴之灾害得商路阻断，好多原材料运不过来。我这批“大烟花”……嘿嘿，可是花了点门路从海伯利亚搞来的呢。",
            ["ContentFR"] = "Évidemment. Le Fléau de Zhuyin a coupé les routes commerciales. Les matières premières n’arrivent plus. Cette cargaison de « Coup de Grâce » hé hé... j’ai dû activer quelques réseaux pour la faire venir d’Hyperborea.",
            ["DialogueId"] = 51155212,
            ["GUID"] = "800FCBF8",
            ["NextDialogue"] = 51155213,
            ["SpeakNpcId"] = 701093,
            },
        [51155213] = {
            ["Content"] = "今年的“大烟花”卖的可好了，有个大客户直接要了一半，说这不奉香大典快到了吗，他打算去百年春搞点大动静。",
            ["ContentFR"] = "Cette année, ça part comme des petits pains. Un gros client en a pris la moitié d’un coup. Avec la Cérémonie de l’Encens qui approche, il compte faire grand bruit à Éternel Printemps.",
            ["DialogueId"] = 51155213,
            ["GUID"] = "800FCC22",
            ["NextDialogue"] = 51155214,
            ["SpeakNpcId"] = 701093,
            },
        [51155214] = {
            ["Content"] = "完了完了完了，这要是一引爆，整个百年春岂不是都要——",
            ["ContentFR"] = "C’est fini, c’est fini... Si elles explosent toutes en même temps, Éternel Printemps va disparaître—",
            ["DialogueId"] = 51155214,
            ["GUID"] = "800FCC4C",
            ["NextDialogue"] = 51155215,
            ["SpeakNpcId"] = 200002,
            },
        [51155215] = {
            ["Content"] = "冷静，白你先冷静……",
            ["ContentFR"] = "Calme-toi, Snow. Respire.",
            ["DialogueId"] = 51155215,
            ["GUID"] = "800FCC76",
            ["NextDialogue"] = 51155216,
            ["SpeakNpcId"] = 100001,
            },
        }
  end },
  { MinKey = 51155216, MaxKey = 51156916, Loader = function()
      return {
        [51155216] = {
            ["Content"] = "这有什么好大惊小怪的。海伯利亚的大烟花可响亮了，我给你放个看看？",
            ["ContentFR"] = "Pourquoi tant d’agitation ? Les Coups de Grâce hyperboréens sont réputés pour leur vacarme. Tu veux que je t’en déclenche un, pour te montrer ?",
            ["DialogueId"] = 51155216,
            ["GUID"] = "800FCCA0",
            ["NextDialogue"] = 51155217,
            ["SpeakNpcId"] = 701093,
            },
        [51155217] = {
            ["Content"] = "大哥你也冷静！！",
            ["ContentFR"] = "Hé ! Calme-toi aussi !",
            ["DialogueId"] = 51155217,
            ["GUID"] = "800FCCCA",
            ["NextDialogue"] = 51155218,
            ["SpeakNpcId"] = 100001,
            },
        [51155218] = {
            ["Content"] = "不放啊？也是，还没到时候呢，等人多的时候再放更好，嘻嘻……",
            ["ContentFR"] = "Pas maintenant ? C’est vrai... Ce sera plus joli quand il y aura du monde... hé hé...",
            ["DialogueId"] = 51155218,
