            ["GUID"] = "8010F276",
            ["NextDialogue"] = 51157008,
            ["SpeakNpcId"] = 701124,
            },
        [51157008] = {
            ["Content"] = "怎么说，要尝尝吗？免费试吃！",
            ["DialogueId"] = 51157008,
            ["GUID"] = "8010F2A0",
            ["SpeakNpcId"] = 701124,
            },
        [51157009] = {
            ["Content"] = "（试探性伸手。）",
            ["DialogueId"] = 51157009,
            ["GUID"] = "8010F2CA",
            ["NextDialogue"] = 51157010,
            },
        [51157010] = {
            ["Content"] = "来来来，别客气！多吃两个！",
            ["DialogueId"] = 51157010,
            ["GUID"] = "8010F2F4",
            ["NextDialogue"] = 51157011,
            ["SpeakNpcId"] = 701124,
            },
        [51157011] = {
            ["Content"] = "（好辣好辣好辣好辣！！！这种食物对于你这种没有吃过重口味的舌头来说有些勉强了……）",
            ["DialogueId"] = 51157011,
            ["GUID"] = "8010F31E",
            ["NextDialogue"] = 51157012,
            ["SpeakNpcId"] = 701124,
            },
        [51157012] = {
            ["Content"] = "怎么脸都吃红了？你还好吧？要不要来点水？",
            ["DialogueId"] = 51157012,
            ["GUID"] = "8010F348",
            ["NextDialogue"] = 51157013,
            ["SpeakNpcId"] = 701124,
            },
        [51157013] = {
            ["Content"] = "水……救命……",
            ["DialogueId"] = 51157013,
            ["GUID"] = "8010F372",
            ["SpeakNpcId"] = 100001,
            },
        [51157014] = {
            ["Content"] = "华胥特色小吃，吃一口念一年！",
            ["DialogueId"] = 51157014,
            ["GUID"] = "8010F17B",
            ["NextDialogue"] = 51157001,
            ["SpeakNpcId"] = 701124,
            },
        [51157101] = {
            ["Content"] = "噫……看着红彤彤的，有些骇人……",
            ["DialogueId"] = 51157101,
            ["Duration"] = 5,
            ["GUID"] = "801101E2",
            },
        [51157201] = {
            ["Content"] = "那东西的味道，怎么闻起来怪怪的？",
            ["DialogueId"] = 51157201,
            ["Duration"] = 5,
            ["GUID"] = "8011124A",
            },
        [51157301] = {
            ["Content"] = "好吃好吃！来三袋！我给娃娃带些！",
            ["DialogueId"] = 51157301,
            ["Duration"] = 5,
            ["GUID"] = "801122B2",
            },
        [51157401] = {
            ["Content"] = "唔……不是很合胃口，算了，谢谢你。",
            ["DialogueId"] = 51157401,
            ["Duration"] = 5,
            ["GUID"] = "8011331A",
            },
        [51157501] = {
            ["Content"] = "今天的目标是，吃空一整条街！",
            ["DialogueId"] = 51157501,
            ["Duration"] = 5,
            ["GUID"] = "80114382",
            },
        [51157601] = {
            ["Content"] = "好些日子不曾来东市逛过，身子骨老了，不怎么爱在城中走动了。",
            ["DialogueId"] = 51157601,
            ["GUID"] = "801153EA",
            ["NextDialogue"] = 51157602,
            ["SpeakNpcId"] = 701125,
            },
        [51157602] = {
            ["Content"] = "娃儿看着面生，不像是咱们皓京本地的，是来这东市买些啥？纪念之物，还是别的？",
            ["DialogueId"] = 51157602,
            ["GUID"] = "80115414",
            ["NextOptions"] = {
                [1] = 51157603,
                [2] = 51157606,
                },
            ["SpeakNpcId"] = 701125,
            },
        [51157603] = {
            ["Content"] = "只是随便逛逛。",
            ["DialogueId"] = 51157603,
            ["GUID"] = "8011543E",
            ["NextDialogue"] = 51157604,
            },
        [51157604] = {
            ["Content"] = "是啊……外地人来皓京，总是免不了来东市逛逛，但要我们这些老皓京人来说，这边卖的也没什么新鲜稀奇的东西。",
            ["DialogueId"] = 51157604,
            ["GUID"] = "80115468",
            ["NextDialogue"] = 51157605,
            ["SpeakNpcId"] = 701125,
            },
        [51157605] = {
            ["Content"] = "真要是有空闲，去华胥各地多走走，多看些山水才是要紧事。",
            ["DialogueId"] = 51157605,
            ["GUID"] = "80115492",
            ["SpeakNpcId"] = 701125,
            },
        [51157606] = {
            ["Content"] = "有什么推荐吗？",
            ["DialogueId"] = 51157606,
            ["GUID"] = "801154BC",
            ["NextDialogue"] = 51157607,
            },
        [51157607] = {
            ["Content"] = "推荐嘛……真要是说，其实还真没有，这东市近些年改换得面目一新，以往熟悉的老店要不关了门要不搬了地址。",
            ["DialogueId"] = 51157607,
            ["GUID"] = "801154E6",
            ["NextDialogue"] = 51157608,
            ["SpeakNpcId"] = 701125,
            },
        [51157608] = {
            ["Content"] = "索性不推荐了，比起买这些特色玩意，还不如多出去走走，看看山山水水才是美事。",
            ["DialogueId"] = 51157608,
            ["GUID"] = "80115510",
            ["SpeakNpcId"] = 701125,
            },
        [51157609] = {
            ["Content"] = "前几年那里还是家布鞋店，现在却已经改成了木雕铺……东市啊，大变样咯！",
            ["DialogueId"] = 51157609,
            ["GUID"] = "8011553A",
            ["NextDialogue"] = 51157610,
            ["SpeakNpcId"] = 701125,
            },
        [51157610] = {
            ["Content"] = "你这娃儿又来东市了？真是好巧，我本来腿脚不好便不怎么来这边逛，今日却又巧合见着你了。",
            ["DialogueId"] = 51157610,
            ["GUID"] = "80115564",
            ["NextOptions"] = {
                [1] = 51157611,
                [2] = 51157617,
                },
            ["SpeakNpcId"] = 701125,
            },
        [51157611] = {
            ["Content"] = "的确好巧。",
            ["DialogueId"] = 51157611,
            ["GUID"] = "8011558E",
            ["NextDialogue"] = 51157612,
            },
        [51157612] = {
            ["Content"] = "是啊……想起了我当年和老头子定情之时……他也是如此这般，频频装作与我偶遇，最终俘获我的芳心，只可惜……",
            ["DialogueId"] = 51157612,
            ["GUID"] = "801155B8",
            ["NextOptions"] = {
                [1] = 51157613,
                [2] = 51157615,
                },
            ["SpeakNpcId"] = 701125,
            },
        [51157613] = {
            ["Content"] = "可惜什么？",
            ["DialogueId"] = 51157613,
            ["GUID"] = "801155E2",
            ["NextDialogue"] = 51157614,
            },
        [51157614] = {
            ["Content"] = "可惜他去年就走啦……这条路，倒是没他陪我再走一遍……",
            ["DialogueId"] = 51157614,
            ["GUID"] = "8011560C",
            ["SpeakNpcId"] = 701125,
            },
        [51157615] = {
            ["Content"] = "我……我没这个意思……",
            ["DialogueId"] = 51157615,
            ["GUID"] = "80115636",
            ["NextDialogue"] = 51157616,
            },
        [51157616] = {
            ["Content"] = "哈哈哈！娃儿说话有趣，老太婆我不是那个意思，只是见到你便想起了我那命短的丈夫……诶，还是不提那些伤心事好啦……",
            ["DialogueId"] = 51157616,
            ["GUID"] = "80115660",
            ["NextOptions"] = {
                [1] = 51157623,
                },
            ["SpeakNpcId"] = 701125,
            },
        [51157617] = {
            ["Content"] = "你不是每天都在这里吗？",
            ["DialogueId"] = 51157617,
            ["GUID"] = "8011568A",
            ["NextDialogue"] = 51157618,
            },
        [51157618] = {
            ["Content"] = "娃儿在说什么胡话呢？我不常来这里了，我家那老头子才是经常来，他喜欢热闹，回回肉菜都不从西市买，非要绕一圈过来。",
            ["DialogueId"] = 51157618,
            ["GUID"] = "801156B4",
            ["NextOptions"] = {
                [1] = 51157619,
                },
            ["SpeakNpcId"] = 701125,
            },
        [51157619] = {
            ["Content"] = "他现在不在这里买了吗？",
            ["DialogueId"] = 51157619,
            ["GUID"] = "801156DE",
            ["NextDialogue"] = 51157620,
            },
        [51157620] = {
            ["Content"] = "东市现在已经改成了供外来游客闲逛的街区，以往那些适合咱们购入生活用品的店铺基本都关了。",
            ["DialogueId"] = 51157620,
            ["GUID"] = "80115708",
            ["NextDialogue"] = 51157621,
            ["SpeakNpcId"] = 701125,
            },
        [51157621] = {
            ["Content"] = "你且从这看过去，哪里有卖瓜果蔬菜之类的店？只有年轻一辈们爱来凑热闹了。",
            ["DialogueId"] = 51157621,
            ["GUID"] = "80115732",
            ["NextDialogue"] = 51157622,
            ["SpeakNpcId"] = 701125,
            },
        [51157622] = {
            ["Content"] = "改了也好，现在老头子也走了。若是他还能再来逛逛，想必现在……多少会有些失望了。",
            ["DialogueId"] = 51157622,
            ["GUID"] = "8011575C",
            ["NextOptions"] = {
                [1] = 51157623,
                },
            ["SpeakNpcId"] = 701125,
            },
        [51157623] = {
            ["Content"] = "再见！",
            ["DialogueId"] = 51157623,
            ["GUID"] = "80115786",
            ["NextDialogue"] = 51157624,
            },
        [51157624] = {
            ["Content"] = "下次见，娃儿，买东西时记得和他们谈谈价，别直接就掏钱了。",
            ["DialogueId"] = 51157624,
            ["GUID"] = "801157B0",
            ["SpeakNpcId"] = 701125,
            },
        [51157625] = {
            ["Content"] = "那里曾是家布鞋店，现在却已经改成了木雕摊……东市啊，大变样咯！",
            ["DialogueId"] = 51157625,
            ["GUID"] = "801153EB",
            ["NextDialogue"] = 51157601,
            ["SpeakNpcId"] = 701125,
            },
        [51157701] = {
            ["Content"] = "这店里怎么摆了这么多木头块？用来做什么的？",
            ["DialogueId"] = 51157701,
            ["Duration"] = 7,
            ["GUID"] = "80116452",
            },
        [51157801] = {
            ["Content"] = "不知道，但那店主看起来眉间带煞，不像是好招惹的。",
            ["DialogueId"] = 51157801,
            ["Duration"] = 7,
            ["GUID"] = "801174BA",
            },
        [51157901] = {
            ["Content"] = "（男人双眸似鹰隼，冷冷地盯着路过的人群，见你在他面前驻留，冰冷的目光便转到你身上。）",
            ["DialogueId"] = 51157901,
            ["GUID"] = "80118522",
            ["NextDialogue"] = 51157902,
            },
        [51157902] = {
            ["Content"] = "做什么？",
            ["DialogueId"] = 51157902,
            ["GUID"] = "8011854C",
            ["NextOptions"] = {
                [1] = 51157903,
                [2] = 51157905,
                },
            ["SpeakNpcId"] = 701126,
            },
        [51157903] = {
            ["Content"] = "这话好像该我问你？",
            ["DialogueId"] = 51157903,
            ["GUID"] = "80118576",
            ["NextDialogue"] = 51157904,
            },
        [51157904] = {
            ["Content"] = "唔……我开店，卖木头，买不买？",
            ["DialogueId"] = 51157904,
            ["GUID"] = "801185A0",
            ["NextOptions"] = {
                [1] = 51157907,
                },
            ["SpeakNpcId"] = 701126,
            },
        [51157905] = {
            ["Content"] = "不是你开的店吗？！",
            ["DialogueId"] = 51157905,
            ["GUID"] = "801185CA",
            ["NextDialogue"] = 51157906,
            },
        [51157906] = {
            ["Content"] = "唔……是……刚开门，我卖木头的，你买不买？",
            ["DialogueId"] = 51157906,
            ["GUID"] = "801185F4",
            ["NextOptions"] = {
                [1] = 51157907,
                },
            ["SpeakNpcId"] = 701126,
            },
        [51157907] = {
            ["Content"] = "算了。",
            ["DialogueId"] = 51157907,
            ["GUID"] = "8011861E",
            ["NextDialogue"] = 51157908,
            },
        [51157908] = {
            ["Content"] = "行……",
            ["DialogueId"] = 51157908,
            ["GUID"] = "80118648",
            ["SpeakNpcId"] = 701126,
            },
        [51157909] = {
            ["Content"] = "（男人在发呆，看到你走过来，他有些怔愣，但片刻好像是想起来了什么，面色也自然了许多。）",
            ["DialogueId"] = 51157909,
            ["GUID"] = "80118672",
            ["NextDialogue"] = 51157910,
            },
        [51157910] = {
            ["Content"] = "又是……你。",
            ["DialogueId"] = 51157910,
            ["GUID"] = "8011869C",
            ["NextOptions"] = {
                [1] = 51157911,
                },
            ["SpeakNpcId"] = 701126,
            },
        [51157911] = {
            ["Content"] = "看到我很惊讶？",
            ["DialogueId"] = 51157911,
            ["GUID"] = "801186C6",
            ["NextDialogue"] = 51157912,
            },
        [51157912] = {
            ["Content"] = "你之前……不是说不买吗？为什么今天……又回来？",
            ["DialogueId"] = 51157912,
            ["GUID"] = "801186F0",
            ["NextDialogue"] = 51157913,
            ["SpeakNpcId"] = 701126,
            },
        [51157913] = {
            ["Content"] = "只是路过这里，顺便来看看你做生意。",
            ["DialogueId"] = 51157913,
            ["GUID"] = "8011871A",
            ["NextDialogue"] = 51157914,
            ["SpeakNpcId"] = 10001,
            },
        [51157914] = {
            ["Content"] = "他们……跟我说，皓京，喜欢木头的多……让我来开店。",
            ["DialogueId"] = 51157914,
            ["GUID"] = "80118744",
            ["NextDialogue"] = 51157915,
            ["SpeakNpcId"] = 701126,
            },
        [51157915] = {
            ["Content"] = "结果，没有人买木头，生意……不好。",
            ["DialogueId"] = 51157915,
            ["GUID"] = "8011876E",
            ["NextOptions"] = {
                [1] = 51157916,
                [2] = 51157919,
                },
            ["SpeakNpcId"] = 701126,
            },
        [51157916] = {
            ["Content"] = "为什么每次说话都不说完整？",
            ["DialogueId"] = 51157916,
            ["GUID"] = "80118798",
            ["NextDialogue"] = 51157917,
            },
        [51157917] = {
            ["Content"] = "嘴巴，笨……",
            ["DialogueId"] = 51157917,
            ["GUID"] = "801187C2",
            ["NextDialogue"] = 51157918,
            ["SpeakNpcId"] = 701126,
            },
        [51157918] = {
            ["Content"] = "说的慢，才能清楚。",
            ["DialogueId"] = 51157918,
            ["GUID"] = "801187EC",
            ["NextOptions"] = {
                [1] = 51157919,
                },
            ["SpeakNpcId"] = 701126,
            },
        [51157919] = {
            ["Content"] = "木头买来做什么？",
            ["DialogueId"] = 51157919,
            ["GUID"] = "80118816",
            ["NextDialogue"] = 51157920,
            },
        [51157920] = {
            ["Content"] = "很……很多。屏风，桌子，板凳，都可以。",
            ["DialogueId"] = 51157920,
            ["GUID"] = "80118840",
            ["NextDialogue"] = 51157921,
            ["SpeakNpcId"] = 701126,
            },
        [51157921] = {
            ["Content"] = "主要是……要雕，我……我会雕，但要时间。",
            ["DialogueId"] = 51157921,
            ["GUID"] = "8011886A",
            ["NextDialogue"] = 51157922,
            ["SpeakNpcId"] = 701126,
            },
        [51157922] = {
            ["Content"] = "所以是家具？",
            ["DialogueId"] = 51157922,
            ["GUID"] = "80118894",
            ["NextDialogue"] = 51157923,
            ["SpeakNpcId"] = 100001,
            },
        [51157923] = {
            ["Content"] = "嗯……没人买，大家，不喜欢木头。租了半年，到时间，就走了。",
            ["DialogueId"] = 51157923,
            ["GUID"] = "801188BE",
            ["NextDialogue"] = 51157924,
            ["SpeakNpcId"] = 701126,
            },
        [51157924] = {
            ["Content"] = "我听路过的人说，你看起来不是什么好惹的家伙，所以不敢进来，要不你……多笑笑？",
            ["DialogueId"] = 51157924,
            ["GUID"] = "801188E8",
            ["NextDialogue"] = 51157925,
            ["SpeakNpcId"] = 100001,
            },
        [51157925] = {
            ["Content"] = "不好惹？笑……笑吗……",
            ["DialogueId"] = 51157925,
            ["GUID"] = "80118912",
            ["NextDialogue"] = 51157926,
            ["SpeakNpcId"] = 701126,
            },
        [51157926] = {
            ["Content"] = "（他踌躇了片刻，似乎在思考该如何摆出笑的表情，直到逐渐驯服五官，做出一副古怪的表情。）",
            ["DialogueId"] = 51157926,
            ["GUID"] = "8011893C",
            ["NextDialogue"] = 51157927,
            },
        [51157927] = {
            ["Content"] = "这样……可以吗？",
            ["DialogueId"] = 51157927,
            ["GUID"] = "80118966",
            ["NextOptions"] = {
                [1] = 51157928,
                [2] = 51157930,
                },
            ["SpeakNpcId"] = 701126,
            },
        [51157928] = {
            ["Content"] = "（拍拍他的肩膀。）还是不要勉强自己了。",
            ["DialogueId"] = 51157928,
            ["GUID"] = "80118990",
            ["NextDialogue"] = 51157929,
            },
        [51157929] = {
            ["Content"] = "唔……好吧，或许，在木头上……画个笑脸，比我自己笑，更简单。",
            ["DialogueId"] = 51157929,
            ["GUID"] = "801189BA",
            ["SpeakNpcId"] = 701126,
            },
        [51157930] = {
            ["Content"] = "（朝他笑一个。）做得很好，以后就按这么来。",
            ["DialogueId"] = 51157930,
            ["GUID"] = "801189E4",
            ["NextDialogue"] = 51157931,
            },
        [51157931] = {
            ["Content"] = "谢谢，你，我以后，就这么，对着大家笑。",
            ["DialogueId"] = 51157931,
            ["GUID"] = "80118A0E",
            ["SpeakNpcId"] = 701126,
            },
        [51158001] = {
            ["Content"] = "客人，来看看阁里的衣服吗？千绣阁是皓京最有名的成衣店，我们店的成衣都是绣娘们一针一线缝出来的，客人喜欢的话，我给您拿一件试试？",
            ["DialogueId"] = 51158001,
            ["GUID"] = "8011958A",
            ["NextOptions"] = {
                [1] = 51158002,
                [2] = 51158003,
                },
            ["SpeakNpcId"] = 701127,
            },
        [51158002] = {
            ["Content"] = "试衣服好麻烦，耽误时间。",
            ["DialogueId"] = 51158002,
            ["GUID"] = "801195B4",
            ["ImprPlusId"] = 1206,
            ["NextDialogue"] = 51158004,
            },
        [51158003] = {
            ["Content"] = "我这身不够好看吗？",
            ["DialogueId"] = 51158003,
            ["GUID"] = "801195DE",
            ["ImprPlusId"] = 1210,
            ["NextDialogue"] = 51158004,
            },
        [51158004] = {
            ["Content"] = "客人身在华胥，可曾听说过一句：人靠衣装马靠鞍？",
            ["DialogueId"] = 51158004,
            ["GUID"] = "80119608",
            ["NextDialogue"] = 51158005,
            ["SpeakNpcId"] = 701127,
            },
        [51158005] = {
            ["Content"] = "客人一看就是德才兼备之士，若是再搭配上我们店里精挑细选的好衣服，定是能进一步彰显出客人的卓尔不凡呢。",
            ["DialogueId"] = 51158005,
            ["GUID"] = "80119632",
            ["NextDialogue"] = 51158006,
            ["SpeakNpcId"] = 701127,
            },
        [51158006] = {
            ["Content"] = "怎么样，要不要来看看呢？",
            ["DialogueId"] = 51158006,
            ["GUID"] = "8011965C",
            ["NextOptions"] = {
                [1] = 51158007,
                [2] = 51158008,
                },
            ["SpeakNpcId"] = 701127,
            },
        [51158007] = {
            ["Content"] = "那行吧。",
            ["DialogueId"] = 51158007,
            ["GUID"] = "80119686",
            ["Scripts"] = "SetOutport{FinishType{2},OptionIdx{1}}",
            },
        [51158008] = {
            ["Content"] = "不看！",
            ["DialogueId"] = 51158008,
            ["GUID"] = "801196B0",
            ["NextDialogue"] = 51158009,
            ["Scripts"] = "SetOutport{FinishType{2},OptionIdx{2}}",
            },
        [51158009] = {
            ["Content"] = "好嘞，客人慢走，若是什么时候想来，我们随时欢迎。",
            ["DialogueId"] = 51158009,
            ["GUID"] = "801196DA",
            ["SpeakNpcId"] = 701127,
            },
        [51158010] = {
            ["Content"] = "这位客人，看你身材匀称，要不要来试试我们千绣阁里的成衣？",
            ["DialogueId"] = 51158010,
            ["GUID"] = "8011958B",
            ["NextDialogue"] = 51158001,
            ["SpeakNpcId"] = 701127,
            },
        [51158101] = {
            ["Content"] = "你是不知道，我一向就厌恶莞婆娘那刺破天的香味，每次闻到，那气味浓郁到像是要把我的鼻腔冲洗一遍！",
            ["DialogueId"] = 51158101,
            ["GUID"] = "8011A5F2",
            ["NextDialogue"] = 51158102,
            ["SpeakNpcId"] = 701129,
            },
        [51158102] = {
            ["Content"] = "结果呢，这家厨子，起了个什么……翡翠丸子的称号，我过去一看还以为是什么新奇玩意，结果居然是把莞婆娘捏进肉丸子里，再用糯米皮包上。",
            ["DialogueId"] = 51158102,
            ["GUID"] = "8011A61C",
            ["NextDialogue"] = 51158103,
            ["SpeakNpcId"] = 701129,
            },
        [51158103] = {
            ["Content"] = "端上来闻不出味，吃到嘴里却是太迟了！有没有人考虑过我们讨厌莞婆娘的人的心理感受呢？",
            ["DialogueId"] = 51158103,
            ["GUID"] = "8011A646",
            ["NextOptions"] = {
                [1] = 51158104,
                [2] = 51158107,
                },
            ["SpeakNpcId"] = 701129,
            },
        [51158104] = {
            ["Content"] = "听起来挺好吃。",
            ["DialogueId"] = 51158104,
            ["GUID"] = "8011A670",
            ["NextDialogue"] = 51158105,
            },
        [51158105] = {
            ["Content"] = "什么？！你喜欢莞婆娘这种香料？！我和你已经无法正常交流了，我单方面认为喜欢莞婆娘这种香料的人嗅觉有问题！",
            ["DialogueId"] = 51158105,
            ["GUID"] = "8011A69A",
            ["NextDialogue"] = 51158106,
            ["SpeakNpcId"] = 701129,
            },
        [51158106] = {
            ["Content"] = "同福饭馆就该给我赔点钱，好不容易下顿馆子，却吃了一肚子不开心！",
            ["DialogueId"] = 51158106,
            ["GUID"] = "8011A6C4",
            ["NextDialogue"] = 51158110,
            ["SpeakNpcId"] = 701129,
            },
        [51158107] = {
            ["Content"] = "听起来好难吃。",
            ["DialogueId"] = 51158107,
            ["GUID"] = "8011A6EE",
            ["NextDialogue"] = 51158108,
            },
        [51158108] = {
            ["Content"] = "对嘛对嘛！这就对了嘛！这种独特的香料，用进菜里就应该在菜单上，客人开点之前，就明确告知会放进去，看看客人能不能接受。",
            ["DialogueId"] = 51158108,
            ["GUID"] = "8011A718",
            ["NextDialogue"] = 51158109,
            ["SpeakNpcId"] = 701129,
            },
        [51158109] = {
            ["Content"] = "现在倒好了，我出来下个馆子，却吃了一肚子不开心。",
            ["DialogueId"] = 51158109,
            ["GUID"] = "8011A742",
            ["NextDialogue"] = 51158110,
            ["SpeakNpcId"] = 701129,
            },
        [51158110] = {
            ["Content"] = "消消气，不然下次不来吃了。",
            ["DialogueId"] = 51158110,
            ["GUID"] = "8011A76C",
            ["NextDialogue"] = 51158111,
            ["SpeakNpcId"] = 100001,
            },
        [51158111] = {
            ["Content"] = "说得对，再也不来了！我以后只会去隔壁的八珍楼。",
            ["DialogueId"] = 51158111,
            ["GUID"] = "8011A796",
            ["SpeakNpcId"] = 701129,
            },
        [51158112] = {
            ["Content"] = "同福饭馆的厨子发了疯，居然把莞婆娘碾碎包进丸子里！",
            ["DialogueId"] = 51158112,
            ["GUID"] = "8011A5F1",
            ["NextDialogue"] = 51158101,
            ["SpeakNpcId"] = 701129,
            },
        [51158201] = {
            ["Content"] = "你居然没去凑那同福饭馆的热闹？哼，我就知道顾客的眼睛终究是雪亮的！那些凑热闹的人，说白了都是不会吃，不懂吃的。",
            ["DialogueId"] = 51158201,
            ["GUID"] = "8011B65A",
            ["NextDialogue"] = 51158202,
            ["SpeakNpcId"] = 701130,
            },
        [51158202] = {
            ["Content"] = "你看那同福饭馆，噱头满天飞！什么香料入菜，简直是欺师灭祖，一派胡言！",
            ["DialogueId"] = 51158202,
            ["GUID"] = "8011B684",
            ["NextOptions"] = {
                [1] = 51158203,
                [2] = 51158206,
                },
            ["SpeakNpcId"] = 701130,
            },
        [51158203] = {
            ["Content"] = "没你说的这么夸张吧？",
            ["DialogueId"] = 51158203,
            ["GUID"] = "8011B6AE",
            ["ImprPlusId"] = 1207,
            ["NextDialogue"] = 51158204,
            },
        [51158204] = {
            ["Content"] = "怎么夸张了？咱们华胥老祖宗传下来的规矩，做菜就要老老实实本本分分，菜里的香，是用油用盐，一把猛火炒出来的，那是菜品本来的香气！",
            ["DialogueId"] = 51158204,
            ["GUID"] = "8011B6D8",
            ["NextDialogue"] = 51158205,
            ["SpeakNpcId"] = 701130,
            },
        [51158205] = {
            ["Content"] = "才不是这些歪门邪道的方法……让老饕们知晓了，都是要笑话他们的！",
            ["DialogueId"] = 51158205,
            ["GUID"] = "8011B702",
            ["SpeakNpcId"] = 701130,
            },
        [51158206] = {
            ["Content"] = "说的很有道理！",
            ["DialogueId"] = 51158206,
            ["GUID"] = "8011B72C",
            ["ImprPlusId"] = 1209,
            ["NextDialogue"] = 51158207,
            },
        [51158207] = {
            ["Content"] = "你看，你也觉得我说的对吧？你可知道我们八珍楼的那些老顾客，各个都是老吃家。",
            ["DialogueId"] = 51158207,
            ["GUID"] = "8011B756",
            ["NextDialogue"] = 51158208,
            ["SpeakNpcId"] = 701130,
            },
        [51158208] = {
            ["Content"] = "他们品一道菜，更注重的是菜肴原本的味道，是调料和食物碰撞后在舌尖迸发的风味。而不是这些……花里胡哨却没有实际意义的东西……哼！",
            ["DialogueId"] = 51158208,
            ["GUID"] = "8011B780",
            ["SpeakNpcId"] = 701130,
            },
        [51158209] = {
            ["Content"] = "一天到晚就知道折腾些看似新颖实则无用的花架子，可别忘了华胥美食的精髓是什么！",
            ["DialogueId"] = 51158209,
            ["GUID"] = "8011B7AA",
            ["NextDialogue"] = 51158210,
            ["SpeakNpcId"] = 701266,
            },
        [51158210] = {
            ["Content"] = "好啦，这下好啦，把我们家的客人全都骗走了，殊不知大家只是图一时新鲜，难道还能真觉得那些东西好吃吗？",
            ["DialogueId"] = 51158210,
            ["GUID"] = "8011B7D4",
            ["NextDialogue"] = 51158211,
            ["SpeakNpcId"] = 701266,
            },
        [51158211] = {
            ["Content"] = "我不信……还能真的好吃吗？那个……你，对！就是你！你过来一下！",
            ["DialogueId"] = 51158211,
            ["GUID"] = "8011B7FE",
            ["NextOptions"] = {
                [1] = 51158212,
                [2] = 51158221,
                },
            ["SpeakNpcId"] = 701266,
            },
        [51158212] = {
            ["Content"] = "叫我吗？",
            ["DialogueId"] = 51158212,
            ["GUID"] = "8011B828",
            ["NextDialogue"] = 51158213,
            },
        [51158213] = {
            ["Content"] = "对对对，就是你，你快来，我托你办个事。",
            ["DialogueId"] = 51158213,
            ["GUID"] = "8011B852",
            ["NextOptions"] = {
                [1] = 51158214,
                [2] = 51158221,
                },
            ["SpeakNpcId"] = 701266,
            },
        [51158214] = {
            ["Content"] = "什么事？",
            ["DialogueId"] = 51158214,
            ["GUID"] = "8011B87C",
            ["NextDialogue"] = 51158215,
            },
        [51158215] = {
            ["Content"] = "你有没有吃过同福饭馆的新品菜肴？",
            ["DialogueId"] = 51158215,
            ["GUID"] = "8011B8A6",
            ["NextOptions"] = {
                [1] = 51158216,
                [2] = 51158221,
                },
            ["SpeakNpcId"] = 701266,
            },
        [51158216] = {
            ["Content"] = "没吃过。",
            ["DialogueId"] = 51158216,
            ["GUID"] = "8011B8D0",
            ["NextDialogue"] = 51158217,
            },
        [51158217] = {
            ["Content"] = "你这样，我给你些钱，你就像寻常顾客那样，去找同福饭馆的店小二买些他们新上的菜品回来，如何？",
            ["DialogueId"] = 51158217,
            ["GUID"] = "8011B8FA",
            ["NextOptions"] = {
                [1] = 51158218,
                [2] = 51158221,
                },
            ["SpeakNpcId"] = 701266,
            },
        [51158218] = {
            ["Content"] = "可以。",
            ["DialogueId"] = 51158218,
            ["GUID"] = "8011B924",
            ["NextDialogue"] = 51158219,
            ["Scripts"] = "SetOutport{FinishType{2},OptionIdx{1}}",
            },
        [51158219] = {
            ["Content"] = "诶，这就对了嘛，给，这是给你的钱。",
            ["DialogueId"] = 51158219,
            ["GUID"] = "8011B94E",
            ["SpeakNpcId"] = 701266,
            },
        [51158221] = {
            ["Content"] = "（不理他。）",
            ["DialogueId"] = 51158221,
            ["GUID"] = "8011B9A2",
            ["NextDialogue"] = 51158222,
            ["Scripts"] = "SetOutport{FinishType{2},OptionIdx{2}}",
            },
        [51158222] = {
            ["Content"] = "不帮就不帮，摆什么脸色呢！我还差你一个吗？",
            ["DialogueId"] = 51158222,
            ["GUID"] = "8011B9CC",
            ["SpeakNpcId"] = 701266,
            },
        [51158224] = {
            ["Content"] = "一天到晚就知道折腾些看似新颖实则无用的花架子，可别忘了华胥美食的精髓是什么！",
            ["DialogueId"] = 51158224,
            ["GUID"] = "8011BA20",
            ["NextDialogue"] = 51158225,
            ["SpeakNpcId"] = 701266,
            },
        [51158225] = {
            ["Content"] = "怎……怎么样？东西带回来了？",
            ["DialogueId"] = 51158225,
            ["GUID"] = "8011BA4A",
            ["NextDialogue"] = 51158226,
            ["SpeakNpcId"] = 701266,
            },
        [51158226] = {
            ["Content"] = "给你。",
            ["DialogueId"] = 51158226,
            ["GUID"] = "8011BA74",
            ["NextDialogue"] = 51158227,
            ["SpeakNpcId"] = 100001,
            },
        [51158227] = {
            ["Content"] = "（他迫不及待地打开食盒，先是俯身仔细闻了一圈，不知从哪掏出一双筷子，夹起菜肴送入嘴中。）",
            ["DialogueId"] = 51158227,
            ["GUID"] = "8011BA9E",
            ["NextDialogue"] = 51158228,
            },
        [51158228] = {
            ["Content"] = "的确是……香！在同时保留菜品原先的风味之上，使用香料平增了更刺激的味道，口腔和鼻腔任由香气钩织出协奏的共鸣……美妙！太美妙了！",
            ["DialogueId"] = 51158228,
            ["GUID"] = "8011BAC8",
            ["NextDialogue"] = 51158229,
            ["SpeakNpcId"] = 701266,
            },
        [51158229] = {
            ["Content"] = "此食只由天上有，人间哪得几回吃！妙哉！妙哉！",
            ["DialogueId"] = 51158229,
            ["GUID"] = "8011BAF2",
            ["NextOptions"] = {
                [1] = 51158230,
                },
            ["SpeakNpcId"] = 701266,
            },
        [51158230] = {
            ["Content"] = "有这么夸张吗？",
            ["DialogueId"] = 51158230,
            ["GUID"] = "8011BB1C",
            ["NextDialogue"] = 51158231,
            },
        [51158231] = {
            ["Content"] = "（他并没有理你，显然已经沉浸在食物里不知天地为何物了……）",
            ["DialogueId"] = 51158231,
            ["GUID"] = "8011BB46",
            },
        [51158301] = {
            ["Content"] = "客人您如意，今日来店，是打尖还是吃饭，咱们店里新上了几道菜品，道道都获得各方好评，您要不要点上一份试试？",
            ["DialogueId"] = 51158301,
            ["GUID"] = "8011C6C2",
            ["NextOptions"] = {
                [1] = 51158302,
                },
            ["SpeakNpcId"] = 701128,
            },
        [51158302] = {
            ["Content"] = "有什么推荐吗？",
            ["DialogueId"] = 51158302,
            ["GUID"] = "8011C6EC",
            ["NextDialogue"] = 51158303,
            },
        [51158303] = {
            ["Content"] = "有！统共有甜咸酸三种，您是爱吃什么口的？",
            ["DialogueId"] = 51158303,
            ["GUID"] = "8011C716",
            ["NextDialogue"] = 51158323,
            ["SpeakNpcId"] = 701128,
            },
        [51158304] = {
            ["Content"] = "甜的吧。",
            ["DialogueId"] = 51158304,
            ["GUID"] = "8011C740",
            ["NextDialogue"] = 51158305,
            },
        [51158305] = {
            ["Content"] = "这就不得不为客人推荐我们的玉桂甜瓜卷了！",
            ["DialogueId"] = 51158305,
            ["GUID"] = "8011C76A",
            ["NextDialogue"] = 51158306,
            ["SpeakNpcId"] = 701128,
            },
        [51158306] = {
            ["Content"] = "华胥西部特产甜瓜，榨汁后混入面团，揉成小团小团再放至蒸锅，最后撒上一层浓浓的玉桂粉。",
            ["DialogueId"] = 51158306,
            ["GUID"] = "8011C794",
            ["NextDialogue"] = 51158307,
            ["SpeakNpcId"] = 701128,
            },
        [51158307] = {
            ["Content"] = "怎么样，客人要点这个吗？",
            ["DialogueId"] = 51158307,
            ["GUID"] = "8011C7BE",
            ["NextOptions"] = {
                [1] = 51158316,
                [2] = 51158318,
                [3] = 51158320,
                },
            ["SpeakNpcId"] = 701128,
            },
        [51158308] = {
            ["Content"] = "咸的吧。",
            ["DialogueId"] = 51158308,
            ["GUID"] = "8011C7E8",
            ["NextDialogue"] = 51158309,
            },
        [51158309] = {
            ["Content"] = "这就不得不为客人推荐我们的翡翠丸子了！",
            ["DialogueId"] = 51158309,
            ["GUID"] = "8011C812",
            ["NextDialogue"] = 51158310,
            ["SpeakNpcId"] = 701128,
            },
        [51158310] = {
            ["Content"] = "莞婆娘切得碎碎的，和猪肉搅的馅，混上其他调味品拌在一起，让味道充分融合在每个角落，蒸熟后再用带着咸味的糯米皮包上一层。",
            ["DialogueId"] = 51158310,
            ["GUID"] = "8011C83C",
            ["NextDialogue"] = 51158311,
            ["SpeakNpcId"] = 701128,
            },
        [51158311] = {
            ["Content"] = "怎么样，客人要点这个吗？",
            ["DialogueId"] = 51158311,
            ["GUID"] = "8011C866",
            ["NextOptions"] = {
                [1] = 51158316,
                [2] = 51158318,
                [3] = 51158320,
                },
            ["SpeakNpcId"] = 701128,
            },
        [51158312] = {
            ["Content"] = "酸的吧。",
            ["DialogueId"] = 51158312,
            ["GUID"] = "8011C890",
            ["NextDialogue"] = 51158313,
            },
        [51158313] = {
            ["Content"] = "这就不得不为客人推荐我们的开胃凤爪了！",
            ["DialogueId"] = 51158313,
            ["GUID"] = "8011C8BA",
            ["NextDialogue"] = 51158314,
            ["SpeakNpcId"] = 701128,
            },
        [51158314] = {
            ["Content"] = "咱把那凤爪煮熟，放冰水里一过，用刀挑出骨头，再加入各色调料，最后将那冰台洗净放进去，再用严寒天里存的冰，冻上个一下午，最终端上来。",
            ["DialogueId"] = 51158314,
            ["GUID"] = "8011C8E4",
            ["NextDialogue"] = 51158315,
            ["SpeakNpcId"] = 701128,
            },
        [51158315] = {
            ["Content"] = "怎么样，客人要点这个吗？",
            ["DialogueId"] = 51158315,
            ["GUID"] = "8011C90E",
            ["NextOptions"] = {
                [1] = 51158316,
                [2] = 51158318,
                [3] = 51158320,
                },
            ["SpeakNpcId"] = 701128,
            },
        [51158316] = {
            ["Content"] = "就要这个吧。",
            ["DialogueId"] = 51158316,
            ["GUID"] = "8011C938",
            ["NextDialogue"] = 51158317,
            },
        [51158317] = {
            ["Content"] = "好嘞客人，一千铜，店内现在没有堂食的座椅了，不如我给您用食盒打包了？",
            ["DialogueId"] = 51158317,
            ["GUID"] = "8011C962",
            ["SpeakNpcId"] = 701128,
            },
        [51158318] = {
            ["Content"] = "等等……我想换成别的。",
            ["DialogueId"] = 51158318,
            ["GUID"] = "8011C98C",
            ["NextDialogue"] = 51158319,
            },
        [51158319] = {
            ["Content"] = "当然可以，客人还想了解什么口味的菜品？",
            ["DialogueId"] = 51158319,
            ["GUID"] = "8011C9B6",
            ["NextOptions"] = {
                [1] = 51158322,
                [2] = 51158320,
                },
            ["SpeakNpcId"] = 701128,
            },
        [51158320] = {
            ["Content"] = "我有别的事，先走了。",
            ["DialogueId"] = 51158320,
            ["GUID"] = "8011C9E0",
            ["NextDialogue"] = 51158321,
            },
        [51158321] = {
            ["Content"] = "客人慢走，下次来有事您招呼！",
            ["DialogueId"] = 51158321,
            ["GUID"] = "8011CA0A",
            ["SpeakNpcId"] = 701128,
            },
        [51158322] = {
            ["Content"] = "同福饭馆菜品上新，外域高人指点，香料入菜，佳肴更添新风味。",
            ["DialogueId"] = 51158322,
            ["GUID"] = "8011C6C1",
            ["NextDialogue"] = 51158301,
            ["SpeakNpcId"] = 701128,
            },
        [51158323] = {
            ["DialogueId"] = 51158323,
            ["DialoguePanelType"] = "None",
            ["Duration"] = 0,
            ["FinalDialogueId"] = 51158321,
            ["GUID"] = "8011C717",
            ["NextOptions"] = {
                [1] = 51158304,
                [2] = 51158308,
                [3] = 51158312,
                },
            },
        [51158401] = {
            ["Content"] = "（眼前的男人醉气熏天，你犹豫着是否要绕开他时，他却一把拉住了你。）",
            ["DialogueId"] = 51158401,
            ["GUID"] = "8011D72A",
            ["NextDialogue"] = 51158402,
            },
        [51158402] = {
            ["Content"] = "秀芳！你终于来见我了！不要改嫁好不好，我才是唯一对你好的人啊！",
            ["DialogueId"] = 51158402,
            ["GUID"] = "8011D754",
            ["NextOptions"] = {
                [1] = 51158403,
                [2] = 51158406,
                },
            ["SpeakNpcId"] = 701131,
            },
        [51158403] = {
            ["Content"] = "大哥，你看清楚，我不是秀芳！",
            ["DialogueId"] = 51158403,
            ["GUID"] = "8011D77E",
            ["NextDialogue"] = 51158404,
            },
        [51158404] = {
            ["Content"] = "不是……我……呜呜呜……她果然还是不肯来见我……",
            ["DialogueId"] = 51158404,
            ["GUID"] = "8011D7A8",
            ["NextDialogue"] = 51158405,
            ["SpeakNpcId"] = 701131,
            },
        [51158405] = {
            ["Content"] = "小二！再来三坛酒，今日我就要一醉方休！",
            ["DialogueId"] = 51158405,
            ["GUID"] = "8011D7D2",
            ["SpeakNpcId"] = 701131,
            },
        [51158406] = {
            ["Content"] = "（不解释自己的身份，任他认错。）",
            ["DialogueId"] = 51158406,
            ["GUID"] = "8011D7FC",
            ["NextDialogue"] = 51158407,
            },
        [51158407] = {
            ["Content"] = "秀芳……你不知道我这段时日有多想你，你为何……为何不愿见我！",
            ["DialogueId"] = 51158407,
            ["GUID"] = "8011D826",
            ["NextDialogue"] = 51158408,
            ["SpeakNpcId"] = 701131,
            },
        [51158408] = {
            ["Content"] = "难道那人真就有那么好，值得你为此托付终身吗？还是说……还是说你……你之前与我许诺的那些海誓山盟，都是骗我的？",
            ["DialogueId"] = 51158408,
            ["GUID"] = "8011D850",
            ["NextDialogue"] = 51158409,
            ["SpeakNpcId"] = 701131,
            },
        [51158409] = {
            ["Content"] = "秀芳……我答应你，再不喝了，我们……",
            ["DialogueId"] = 51158409,
            ["GUID"] = "8011D87A",
            ["NextDialogue"] = 51158410,
            ["SpeakNpcId"] = 701131,
            },
        [51158410] = {
            ["Content"] = "（男人呜咽一声，醉倒在地，显然是晕过去了。）",
            ["DialogueId"] = 51158410,
            ["GUID"] = "8011D8A4",
            },
        [51158411] = {
            ["Content"] = "秀芳……不要离开我……秀芳……",
            ["DialogueId"] = 51158411,
            ["GUID"] = "8011D72B",
            ["NextDialogue"] = 51158401,
            ["SpeakNpcId"] = 701131,
            },
        [51158501] = {
            ["Content"] = "要不说还是东市的这些商户精明呢，为了一时的噱头，无所不用极。",
            ["DialogueId"] = 51158501,
            ["GUID"] = "8011E792",
            ["NextDialogue"] = 51158502,
            ["SpeakNpcId"] = 701133,
            },
        [51158502] = {
            ["Content"] = "那店铺是卖什么呢？总不能把雀儿的羽翎摘下来做饰品吧？",
            ["DialogueId"] = 51158502,
            ["GUID"] = "8011E7BC",
            ["NextDialogue"] = 51158503,
            ["SpeakNpcId"] = 701132,
            },
        [51158503] = {
            ["Content"] = "哦哟！说得也太残忍了……雀儿可是用来观赏的，赏雀品茗，是不是别有一番风味？",
            ["DialogueId"] = 51158503,
            ["GUID"] = "8011E7E6",
            ["NextDialogue"] = 51158504,
            ["SpeakNpcId"] = 701133,
            },
        [51158504] = {
            ["Content"] = "有趣是有趣，但……他如何保证客人能看到开了屏的翠屏雀呢？",
            ["DialogueId"] = 51158504,
            ["GUID"] = "8011E810",
            ["NextDialogue"] = 51158505,
            ["SpeakNpcId"] = 701132,
            },
        [51158505] = {
            ["Content"] = "嘿！他们请了全华胥画技最为精妙的画师，在店内绘制了一副又一副栩栩如生的雌雀在那屏风之上。",
            ["DialogueId"] = 51158505,
            ["GUID"] = "8011E83A",
            ["NextDialogue"] = 51158506,
            ["SpeakNpcId"] = 701133,
            },
        [51158506] = {
            ["Content"] = "再将那屏风放置在每位客人的雅间之内，最后将雄雀放出去。那雄雀是左看右看，晕头转向，争相开屏，怕晚一步就吸引不到假雌雀的注意力咯！",
            ["DialogueId"] = 51158506,
            ["GUID"] = "8011E864",
            ["SpeakNpcId"] = 701133,
            },
        [51158507] = {
            ["Content"] = "把翠屏雀搬来了皓京城？！还有此等奇事！",
            ["DialogueId"] = 51158507,
            ["GUID"] = "8011E791",
            ["NextDialogue"] = 51158501,
            ["SpeakNpcId"] = 701132,
            },
        [51158601] = {
            ["Content"] = "收到的传单上分明写的是东市，怎么找过来走了几条街也没见着地方在哪呢？",
            ["DialogueId"] = 51158601,
            ["GUID"] = "8011F7FA",
            ["NextDialogue"] = 51158602,
            ["SpeakNpcId"] = 701134,
            },
        [51158602] = {
            ["Content"] = "诶！这位朋友，你可曾见到一家茶舍，名为雀翎茗轩，店内据说有多只漂亮张扬的翠屏雀，实不相瞒，我从小到大就对那些鸟儿特别感兴趣。",
            ["DialogueId"] = 51158602,
            ["GUID"] = "8011F824",
            ["NextDialogue"] = 51158603,
            ["SpeakNpcId"] = 701134,
            },
        [51158603] = {
            ["Content"] = "这次一听说皓京有这样新鲜的店铺，我就高兴得一蹦三尺高，第一时间就赶了过来，可不知为何……我遍寻许久，就是没有瞧见招牌呢……",
            ["DialogueId"] = 51158603,
            ["GUID"] = "8011F84E",
            ["NextOptions"] = {
                [1] = 51158604,
                },
            ["SpeakNpcId"] = 701134,
            },
        [51158604] = {
            ["Content"] = "我也不知道在哪。",
            ["DialogueId"] = 51158604,
            ["GUID"] = "8011F878",
            ["NextDialogue"] = 51158605,
            },
        [51158605] = {
            ["Content"] = "是吗……那确实是可惜了……",
            ["DialogueId"] = 51158605,
            ["GUID"] = "8011F8A2",
            ["SpeakNpcId"] = 701134,
            },
        [51158606] = {
            ["Content"] = "雀翎茗轩……是在这里吗？",
            ["DialogueId"] = 51158606,
            ["GUID"] = "8011F8CC",
            ["NextDialogue"] = 51158607,
            ["SpeakNpcId"] = 701134,
            },
        [51158607] = {
            ["Content"] = "好不容易能有机会看着翠屏雀，怎么就是整日不见开门呢？",
            ["DialogueId"] = 51158607,
            ["GUID"] = "8011F8F6",
            ["NextDialogue"] = 51158608,
            ["SpeakNpcId"] = 701134,
            },
        [51158608] = {
            ["Content"] = "诶？是你！你也是来找雀翎茗轩的吗？",
            ["DialogueId"] = 51158608,
            ["GUID"] = "8011F920",
            ["NextOptions"] = {
                [1] = 51158609,
                },
            ["SpeakNpcId"] = 701134,
            },
        [51158609] = {
            ["Content"] = "你还没找到吗？",
            ["DialogueId"] = 51158609,
            ["GUID"] = "8011F94A",
            ["NextDialogue"] = 51158610,
            },
        [51158610] = {
            ["Content"] = "什么？不不不，其实我倒是找到了，但我过去一看，那店铺空空如也，问了店老板，说是……雀儿在参商港全丢了……",
            ["DialogueId"] = 51158610,
            ["GUID"] = "8011F974",
            ["NextDialogue"] = 51158611,
            ["SpeakNpcId"] = 701134,
            },
        [51158611] = {
            ["Content"] = "你说这事荒谬不荒谬？哪有这种道理呢？好好的雀儿竟是丢了……那我该如何是好呢？",
            ["DialogueId"] = 51158611,
            ["GUID"] = "8011F99E",
            ["NextOptions"] = {
                [1] = 51158612,
                [2] = 51158614,
                },
            ["SpeakNpcId"] = 701134,
            },
        [51158612] = {
            ["Content"] = "别担心，总会找回来的。",
            ["DialogueId"] = 51158612,
            ["GUID"] = "8011F9C8",
            ["NextDialogue"] = 51158613,
            },
        [51158613] = {
            ["Content"] = "话虽如此……诶！算啦！再想也无济于事，多谢你的宽慰，我这心里好受多了。",
            ["DialogueId"] = 51158613,
            ["GUID"] = "8011F9F2",
            ["SpeakNpcId"] = 701134,
            },
        [51158614] = {
            ["Content"] = "那就不看了呗！",
            ["DialogueId"] = 51158614,
            ["GUID"] = "8011FA1C",
            ["NextDialogue"] = 51158615,
            },
        [51158615] = {
            ["Content"] = "只是感到有些可惜……诶！算啦！那便等段时间，再来看看是何情况吧。",
            ["DialogueId"] = 51158615,
            ["GUID"] = "8011FA46",
            ["SpeakNpcId"] = 701134,
            },
        [51158616] = {
            ["Content"] = "雀翎茗轩……是在这里吗？",
            ["DialogueId"] = 51158616,
            ["GUID"] = "8011F7FB",
            ["NextDialogue"] = 51158601,
            ["SpeakNpcId"] = 701134,
            },
        [51158701] = {
            ["Content"] = "（她心不在焉地吆喝了两嗓子便不再继续了，满脸写着不耐烦。）",
            ["DialogueId"] = 51158701,
            ["GUID"] = "80120862",
            ["NextDialogue"] = 51158702,
            },
        [51158702] = {
            ["Content"] = "反正雀儿也没找回来，还要吆喝这些做什么……",
            ["DialogueId"] = 51158702,
            ["GUID"] = "8012088C",
            ["NextOptions"] = {
                [1] = 51158703,
                },
            ["SpeakNpcId"] = 701258,
            },
        [51158703] = {
            ["Content"] = "你在说什么？",
            ["DialogueId"] = 51158703,
            ["GUID"] = "801208B6",
            ["NextDialogue"] = 51158704,
            },
        }
  end },
  { MinKey = 51158704, MaxKey = 51159809, Loader = function()
      return {
        [51158704] = {
            ["Content"] = "噫！偷懒被抓到了？你难道是老板请来的监工？",
