            ["GUID"] = "8017FFCE",
            ["NextDialogue"] = 51168012,
            ["Scripts"] = "SetOutport{FinishType{2},OptionIdx{1}}",
            },
        [51168012] = {
            ["Content"] = "您是熟客，就不让您多等了，直接发船！去东市记得给哥哥带声好！",
            ["DialogueId"] = 51168012,
