        }
  end },
  { MinKey = 51168123, MaxKey = 51169731, Loader = function()
      return {
        [51168123] = {
            ["Content"] = "虽然我也对华胥语不是特别了解，但是你刚刚念的只交，应该是知交吧？初来炸弹听起来也很奇怪，应该是初来乍到？",
            ["DialogueId"] = 51168123,
            ["GUID"] = "8018122E",
            ["NextDialogue"] = 51168124,
            ["SpeakNpcId"] = 100001,
            },
        [51168124] = {
            ["Content"] = "啊！原来是这样啊！哎呀，你看我这……所以其实这翻译也没必要请，现在大家说话也都差不多？",
            ["DialogueId"] = 51168124,
            ["GUID"] = "80181258.0",
