            ["DialogueId"] = 51171011,
            ["GUID"] = "8019EBFE",
            ["NextDialogue"] = 51171013,
            },
        [51171012] = {
            ["Content"] = "你刚刚没和他说实话吧？",
            ["DialogueId"] = 51171012,
            ["GUID"] = "8019EC28",
            ["NextDialogue"] = 51171013,
            },
        [51171013] = {
            ["Content"] = "嚯！哪里来的孩子，吓我一跳呢。",
            ["DialogueId"] = 51171013,
            ["GUID"] = "8019EC52",
            ["NextDialogue"] = 51171014,
            ["SpeakNpcId"] = 701213,
            },
        [51171014] = {
            ["Content"] = "听你这话，应是刚才我与老先生的话都被你听了个七七八八。实不相瞒，的确没说实话，只是有些话如实说了并非好事，何况……",
            ["DialogueId"] = 51171014,
