        [51171016] = {
            ["Content"] = "什么事情这么严重？",
            ["DialogueId"] = 51171016,
            ["GUID"] = "8019ECD0",
            ["NextDialogue"] = 51171017,
            },
        [51171017] = {
            ["Content"] = "这事说来也是话长……其实我早年来学院之时，便是想着能与诸多学术大能交流沟通，碰撞思想。",
            ["DialogueId"] = 51171017,
            ["GUID"] = "8019ECFA",
            ["NextDialogue"] = 51171018,
            ["SpeakNpcId"] = 701213,
            },
        [51171018] = {
            ["Content"] = "而后来到这里，虽说是在一些明辨理论上有了更深的造诣，也接触到了许多未曾思考过的想法，深感新奇有趣。",
            ["DialogueId"] = 51171018,
            ["GUID"] = "8019ED24",
            ["NextDialogue"] = 51171019,
            ["SpeakNpcId"] = 701213,
            },
        [51171019] = {
            ["Content"] = "但久而久之……却总觉得哪里有些不对味。",
            ["DialogueId"] = 51171019,
            ["GUID"] = "8019ED4E",
            ["NextDialogue"] = 51171020,
            ["SpeakNpcId"] = 701213,
            },
        [51171020] = {
            ["Content"] = "似乎所有人都在对着书本，对着一些先哲之言引经据典，用复杂的词汇和一些之乎者也之类的话术，恨不得把对方绕到胡同里。",
            ["DialogueId"] = 51171020,
            ["GUID"] = "8019ED78",
            ["NextDialogue"] = 51171021,
            ["SpeakNpcId"] = 701213,
            },
        [51171021] = {
            ["Content"] = "辩论最终的结果，往往不是一方的成功，而是一方不愿再进行下去的失败。",
            ["DialogueId"] = 51171021,
            ["GUID"] = "8019EDA2",
            ["NextDialogue"] = 51171022,
            ["SpeakNpcId"] = 701213,
            },
        [51171022] = {
            ["Content"] = "我只觉得这样的碰撞，无法再产生思想的火花，无法让我再度找到那种脑中的想法被对方捋顺所找寻到的快乐。",
            ["DialogueId"] = 51171022,
            ["GUID"] = "8019EDCC",
            ["NextDialogue"] = 51171023,
            ["SpeakNpcId"] = 701213,
            },
        [51171023] = {
            ["Content"] = "我也不知道该如何解决这样的问题，回家或许不是解法，但我所能想到的改变方式只有这个了。",
            ["DialogueId"] = 51171023,
            ["GUID"] = "8019EDF6",
            ["NextDialogue"] = 51171024,
            ["SpeakNpcId"] = 701213,
            },
        [51171024] = {
            ["Content"] = "或许放下书本，走进生活之中，才是我应该做的，而不是高悬在楼台之上，当那莫须有的明月。",
            ["DialogueId"] = 51171024,
            ["GUID"] = "8019EE20",
            ["NextDialogue"] = 51171025,
            ["SpeakNpcId"] = 701213,
            },
        [51171025] = {
            ["Content"] = "你瞧我，又开始说些奇怪的话了！",
            ["DialogueId"] = 51171025,
            ["GUID"] = "8019EE4A",
            ["NextOptions"] = {
                [1] = 51171026,
