            },
        [51171026] = {
            ["Content"] = "说的有道理，你应该更务实一些。",
            ["DialogueId"] = 51171026,
            ["GUID"] = "8019EE74",
            ["NextDialogue"] = 51171027,
            },
        [51171027] = {
            ["Content"] = "其实我还不确定这样的方式对还是不对，但总之，改变才是我的第一步。",
            ["DialogueId"] = 51171027,
            ["GUID"] = "8019EE9E",
            ["NextDialogue"] = 51171030,
            ["SpeakNpcId"] = 701213,
            },
        [51171028] = {
            ["Content"] = "也不是吧，或许你只是累了。",
