            ["GUID"] = "801A804E",
            ["NextOptions"] = {
                [1] = 51171916,
                [2] = 51171918,
                },
            ["SpeakNpcId"] = 701222,
            },
        [51171916] = {
            ["Content"] = "可是这种事情靠祈祷有用吗？",
            ["DialogueId"] = 51171916,
            ["GUID"] = "801A8078",
            ["NextDialogue"] = 51171917,
            },
        [51171917] = {
            ["Content"] = "哼。你这家伙好没意思，有没有用总也得试过了再说吧……",
            ["DialogueId"] = 51171917,
            ["GUID"] = "801A80A2",
            ["NextDialogue"] = 51171921,
            ["SpeakNpcId"] = 701222,
            },
        [51171918] = {
            ["Content"] = "你为什么想长高呢？",
            ["DialogueId"] = 51171918,
            ["GUID"] = "801A80CC",
            ["NextDialogue"] = 51171919,
            },
        [51171919] = {
            ["Content"] = "唔……我只是觉得我们皎皎一族都太没有意思了，就是说，大家好像全都长得一模一样，一样的头，一样的身子。",
            ["DialogueId"] = 51171919,
            ["GUID"] = "801A80F6",
            ["NextDialogue"] = 51171920,
            ["SpeakNpcId"] = 701222,
            },
        [51171920] = {
            ["Content"] = "我想让自己更独特一些，至少可以和其他皎皎拉开一些差距，但也不要是穿着打扮的那种，而是更更更独特一些的。",
            ["DialogueId"] = 51171920,
            ["GUID"] = "801A8120",
            ["NextDialogue"] = 51171921,
            ["SpeakNpcId"] = 701222,
            },
        [51171921] = {
            ["Content"] = "不过现在看起来，还是很有用的嘛~你看你这不就是在人群之中一眼发现了我，然后和我搭话了嘛？",
            ["DialogueId"] = 51171921,
            ["GUID"] = "801A814A",
            ["NextDialogue"] = 51171922,
            ["SpeakNpcId"] = 701222,
            },
        [51171922] = {
            ["Content"] = "是被我的魅力折服了吧！",
            ["DialogueId"] = 51171922,
            ["GUID"] = "801A8174",
            ["NextDialogue"] = 51171923,
            ["SpeakNpcId"] = 701222,
            },
        [51171923] = {
            ["Content"] = "（怎么和白那家伙一样自恋……）",
            ["DialogueId"] = 51171923,
            ["GUID"] = "801A819E",
            ["NextOptions"] = {
                [1] = 51171924,
                },
            },
        [51171924] = {
            ["Content"] = "你说得对。",
            ["DialogueId"] = 51171924,
            ["GUID"] = "801A81C8",
            ["NextDialogue"] = 51171925,
            },
        [51171925] = {
            ["Content"] = "嘿嘿~增高计划卓有成效嘛，我这就回家多找些垫子垫上~",
            ["DialogueId"] = 51171925,
            ["GUID"] = "801A81F2",
            ["SpeakNpcId"] = 701222,
            },
        [51172001] = {
            ["Content"] = "往年到了奉香大典期间，总是需要许多帮工入阁，今年怎得没动静了？",
            ["DialogueId"] = 51172001,
            ["GUID"] = "801A8E6A",
            ["NextDialogue"] = 51172002,
            ["SpeakNpcId"] = 701223,
            },
        [51172002] = {
            ["Content"] = "您不知道？前些日子听说阁内出了事故，引来了几只玄色狴犴。",
            ["DialogueId"] = 51172002,
            ["GUID"] = "801A8E94",
            ["NextDialogue"] = 51172003,
            ["SpeakNpcName"] = "UI_NPC_Name_yuwei_Sce",
            },
        [51172003] = {
