            ["GUID"] = "801B541C",
            ["NextDialogue"] = 51173207,
            ["SpeakNpcName"] = "UI_NPC_Name_muyu_Sce",
            },
        [51173207] = {
            ["Content"] = "啧……撒谎！",
            ["DialogueId"] = 51173207,
            ["GUID"] = "801B5446",
            ["NextDialogue"] = 51173208,
            ["SpeakNpcId"] = 701240,
            },
        [51173208] = {
            ["Content"] = "嘶！好痛！不要敲我的头！",
