        [51173209] = {
            ["Content"] = "不敲你两下你能记得住？现在连撒谎都学会了，谁教你的？闻得出来就闻得出来，闻不出来就说实话，你啊……",
            ["DialogueId"] = 51173209,
            ["GUID"] = "801B549A",
            ["SpeakNpcId"] = 701240,
            },
        [51173301] = {
