            ["DialogueId"] = 51175925,
            ["GUID"] = "801D1232",
            },
        [51175926] = {
            ["Content"] = "像这样的活动可太多了，一年四季转不过来的，若是你久居华胥，就知道个中滋味了。",
            ["DialogueId"] = 51175926,
            ["GUID"] = "801D125C",
