        [51176027] = {
            ["Content"] = "哈哈，不管怎么说，可惜的是，长生不老根本是不可能存在的，反而有大多数抟土氏，因为过于渴望这一点，前赴后继地踏上登楼的道路。",
            ["DialogueId"] = 51176027,
            ["GUID"] = "801D22EE",
            },
        [51176028] = {
            ["Content"] = "不能借助外力，即坐不了船，用不了桨，凭借自己的力量过去谈何容易？大多都在水上夭折，尸骨无存。",
            ["DialogueId"] = 51176028,
            ["GUID"] = "801D2318",
            },
        [51176029] = {
            ["Content"] = "再后来，为了让那些愚昧的家伙们不再去追求一些不可能实现的梦想，天禄司便真的在水上建了一座小岛，并在小岛上盖了个楼。",
            ["DialogueId"] = 51176029,
            ["GUID"] = "801D2342",
            },
        [51176030] = {
            ["Content"] = "啊！所以，现在的楼是真的，以前的楼是假的，是吗？",
            ["DialogueId"] = 51176030,
            ["GUID"] = "801D236C",
            },
        [51176031] = {
            ["Content"] = "可以这么说，但也有一种说法其实是，现在的楼是假蜃楼，真蜃楼则被藏了起来，任何人都无法再度找到它。",
            ["DialogueId"] = 51176031,
            ["GUID"] = "801D2396",
            },
        [51176032] = {
            ["Content"] = "再？你的意思是……",
            ["DialogueId"] = 51176032,
            ["GUID"] = "801D23C0",
            },
        [51176033] = {
            ["Content"] = "是的，曾有一名沈姓书生，扬言自己登上了真蜃楼，并在上面见到了八仙，但却没有通过他们的考验。",
            ["DialogueId"] = 51176033,
            ["GUID"] = "801D23EA",
            },
        [51176034] = {
            ["Content"] = "他声称即使自己没有通过考验，但八仙依旧端出玉液琼浆，蟠桃珍馐，热情款待了他，并在他离开之际赠给他一个样貌别致的法宝。",
            ["DialogueId"] = 51176034,
            ["GUID"] = "801D2414",
            },
        [51176035] = {
            ["Content"] = "说是可以消灾抵难，福寿延长。",
            ["DialogueId"] = 51176035,
            ["GUID"] = "801D243E",
            },
        [51176036] = {
            ["Content"] = "哇！听起来好厉害啊，那姑母，沈书生现在在哪里？",
            ["DialogueId"] = 51176036,
            ["GUID"] = "801D2468",
            },
        [51176037] = {
            ["Content"] = "那名沈书生啊，早就是一百多年前的事情了，听说他后来搬到了天禄司新建的假蜃楼上，并幻想着有一天可以再次登上真蜃楼。",
            ["DialogueId"] = 51176037,
            ["GUID"] = "801D2492",
            },
        [51176038] = {
            ["Content"] = "不过呢……多半是没有后话了，应该是早已离世了吧，他似乎有留下一些书籍，写了自己登上真蜃楼后的经历，那书叫什么……《蜃景笔谈》？",
            ["DialogueId"] = 51176038,
            ["GUID"] = "801D24BC",
            },
        [51176039] = {
            ["Content"] = "估计现在早就找不到了，可能只有资历老的书商那边才有留档吧，也可能早就被丢到哪个瘸了腿的桌子下面当踮脚砖了。",
            ["DialogueId"] = 51176039,
            ["GUID"] = "801D24E6",
            },
        [51176040] = {
            ["Content"] = "好有趣的故事，姑母，哪天你带我去假蜃楼玩吧！",
            ["DialogueId"] = 51176040,
            ["GUID"] = "801D2510",
            },
        [51176041] = {
            ["Content"] = "好啊，条件是你现在乖乖回家，把昨天你阿娘给你买的糖罐交出来，听到没？",
            ["DialogueId"] = 51176041,
            ["GUID"] = "801D253A",
            },
        [51176042] = {
            ["Content"] = "可是那个，就是，嗯……吃，吃完了……",
            ["DialogueId"] = 51176042,
            ["GUID"] = "801D2564",
            },
        [51176043] = {
            ["Content"] = "什么？！这才过了三天！你这贪吃的娃娃！小心牙齿全都掉光光！",
            ["DialogueId"] = 51176043,
            ["GUID"] = "801D258E",
            },
        [51176044] = {
            ["Content"] = "（姑侄两人笑着闹着跑远了，独留你在原地看着她们离开的背影……）",
            ["DialogueId"] = 51176044,
            ["GUID"] = "801D25B8",
            },
        [51176045] = {
            ["Content"] = "（《蜃景笔谈》吗？有机会找来看看吧。）",
            ["DialogueId"] = 51176045,
            ["GUID"] = "801D25E2",
            },
        [51177001] = {
            ["Content"] = "所有目光向我看齐！",
            ["DialogueId"] = 51177001,
            ["GUID"] = "801DC2BA",
            },
        [51177002] = {
            ["Content"] = "所有目光向我看齐，在场的各位，都是彻彻底底的聪明龙！聪明土！",
            ["DialogueId"] = 51177002,
            ["GUID"] = "801DC2E4",
            },
        [51177003] = {
            ["Content"] = "（眼前的皎皎趾高气昂地站在桌子上，意气风发。）",
            ["DialogueId"] = 51177003,
            ["GUID"] = "801DC30E",
            },
        [51177004] = {
            ["Content"] = "这里不能站着。",
            ["DialogueId"] = 51177004,
            ["GUID"] = "801DC338",
            },
        [51177005] = {
            ["Content"] = "乐观皎皎的词典里没有不可以！只要用积极的眼光看出去，就会发现皓京里到处都是条条大道~",
            ["DialogueId"] = 51177005,
            ["GUID"] = "801DC362",
            },
        [51177006] = {
            ["Content"] = "让我们说一些更加灿烂的词语吧，比如爱，比如希望，比如明天！",
            ["DialogueId"] = 51177006,
            ["GUID"] = "801DC38C",
            },
        [51177007] = {
            ["Content"] = "站这么高不累吗？",
            ["DialogueId"] = 51177007,
            ["GUID"] = "801DC3B6",
            },
        [51177008] = {
            ["Content"] = "累，困，沮丧，疲惫……这些词在我乐观皎皎的词典里统统不存在！我想请你以其他的词语来形容我。",
            ["DialogueId"] = 51177008,
            ["GUID"] = "801DC3E0",
            },
        [51177009] = {
            ["Content"] = "比如爱，比如希望，比如明天！",
            ["DialogueId"] = 51177009,
            ["GUID"] = "801DC40A",
            },
        [51177010] = {
            ["Content"] = "所以你在这里做什么？",
            ["DialogueId"] = 51177010,
            ["GUID"] = "801DC434",
            },
        [51177011] = {
            ["Content"] = "如你所见，我在宣讲，宣讲一段独属于乐观的发言，我是被乐观感染的皎皎，我的存在即是为了将乐观传递给他人！",
            ["DialogueId"] = 51177011,
            ["GUID"] = "801DC45E",
            },
        [51177012] = {
            ["Content"] = "你看见了吗？看见了乐观洒满皓京城内的样子了吗？",
            ["DialogueId"] = 51177012,
            ["GUID"] = "801DC488",
            },
        [51177013] = {
            ["Content"] = "隔夜的鲜花曾经奄奄一息，现在却焕发新姿，摇曳间散发芳香。",
            ["DialogueId"] = 51177013,
            ["GUID"] = "801DC4B2",
            },
        [51177014] = {
            ["Content"] = "包子摊本来冷冷清清，今早一开摊却排起了长龙，大家抢着要买刚出笼的热乎乎的包子。",
            ["DialogueId"] = 51177014,
            ["GUID"] = "801DC4DC",
            },
        [51177015] = {
            ["Content"] = "我最爱喝的绿豆沙店主也记住了我的口味，一碗里多放了六颗莲子！",
            ["DialogueId"] = 51177015,
            ["GUID"] = "801DC506",
            },
        [51177016] = {
            ["Content"] = "大家开始像我一样乐观，像我一样爱笑……",
            ["DialogueId"] = 51177016,
            ["GUID"] = "801DC530",
            },
        [51177017] = {
            ["Content"] = "这就是……",
            ["DialogueId"] = 51177017,
            ["GUID"] = "801DC55A",
            },
        [51177018] = {
            ["Content"] = "这就是乐观的感染啊！你呢？你有被感染到吗？！",
            ["DialogueId"] = 51177018,
            ["GUID"] = "801DC584",
            },
        [51177019] = {
            ["Content"] = "有被感染。",
            ["DialogueId"] = 51177019,
            ["GUID"] = "801DC5AE",
            },
        [51177020] = {
            ["Content"] = "有被“感染”。",
            ["DialogueId"] = 51177020,
            ["GUID"] = "801DC5D8",
            },
        [51177021] = {
            ["Content"] = "对啦，这就对啦！只要所有人都心存乐观，世界就会变得更美好！",
            ["DialogueId"] = 51177021,
            ["GUID"] = "801DC602",
            },
        [51177022] = {
            ["Content"] = "去吧，带着这份乐观，保持脸上的笑容，去把乐观传递给更多人吧！",
            ["DialogueId"] = 51177022,
            ["GUID"] = "801DC62C",
            },
        [51177023] = {
            ["Content"] = "（乐观皎皎伸出手，煞有介事地拍了拍你的肩膀，目光却灼灼地直视前方，似乎要透过你，看向更多的地方……）",
            ["DialogueId"] = 51177023,
            ["GUID"] = "801DC656",
            },
        [51177024] = {
            ["Content"] = "（过了一会，她的目光转向了你，在短暂对视后，她重重的点了点头，然后挪开手，继续开始了宣讲。）",
            ["DialogueId"] = 51177024,
            ["GUID"] = "801DC680",
            },
        [51177025] = {
            ["Content"] = "（你总觉得这种感觉似乎有些熟悉，像是这段对话曾经在何时发生过，只是不是以这样的形式……）",
            ["DialogueId"] = 51177025,
            ["GUID"] = "801DC6AA",
            },
        [51177026] = {
            ["Content"] = "怎么样，今天有比昨天更乐观一些吗？如果没有的话，那就留下来再听听我的宣讲吧！",
            ["DialogueId"] = 51177026,
            ["GUID"] = "801DC6EC",
            },
        [51178001] = {
            ["Content"] = "怎就没有愿意与我辩论之人？",
            ["DialogueId"] = 51178001,
            ["GUID"] = "801E66CA",
            },
        [51178002] = {
            ["Content"] = "怎就没有愿意与我辩论之人？莫非是我过于咄咄逼人了？",
            ["DialogueId"] = 51178002,
            ["GUID"] = "801E66F4",
            },
        [51178003] = {
            ["Content"] = "明明我想了个如此精妙绝伦的辩题，辩完后必定醍醐灌顶，效用堪比仙人抚顶啊！",
            ["DialogueId"] = 51178003,
            ["GUID"] = "801E671E",
            },
        [51178004] = {
            ["Content"] = "偏生那帮混蛋双目昏昏，愚钝不堪，不看好我的辩题，等到夫子回来，我定要狠狠告他们一桩。",
            ["DialogueId"] = 51178004,
            ["GUID"] = "801E6748",
            },
        [51178005] = {
            ["Content"] = "唉……究竟何处能有慧眼识珠之人，透过我的脆弱，看穿我的坚强，与我展开一场精彩的辩论……",
            ["DialogueId"] = 51178005,
            ["GUID"] = "801E6772",
            },
        [51178006] = {
            ["Content"] = "我来！",
            ["DialogueId"] = 51178006,
            ["GUID"] = "801E679C",
            },
        [51178007] = {
            ["Content"] = "（他的目光移向你，炽热的视线似乎要把你灼伤。）",
            ["DialogueId"] = 51178007,
            ["GUID"] = "801E67C6",
            },
        [51178008] = {
            ["Content"] = "好！好啊！就决定是你了！",
            ["DialogueId"] = 51178008,
            ["GUID"] = "801E67F0",
            },
        [51178009] = {
            ["Content"] = "（没意思，走吧。）",
            ["DialogueId"] = 51178009,
            ["GUID"] = "801E681A",
            },
        [51178010] = {
            ["Content"] = "这位朋友请留步！我见你相貌堂堂，一表人才，眉间似有龙气萦绕，想必定是卧虎藏龙之辈。",
            ["DialogueId"] = 51178010,
            ["GUID"] = "801E6844",
            },
        [51178011] = {
            ["Content"] = "不如就由你来与我辩论一番，如何？",
            ["DialogueId"] = 51178011,
            ["GUID"] = "801E686E",
            },
        [51178012] = {
            ["Content"] = "你说的这个辩论我不懂，之前也没学过。",
            ["DialogueId"] = 51178012,
            ["GUID"] = "801E6898",
            },
        [51178013] = {
            ["Content"] = "这话说得就生疏了，什么叫不懂和没学过呢，凡事不都得有第一次尝试？",
            ["DialogueId"] = 51178013,
            ["GUID"] = "801E68C2",
            },
        [51178014] = {
            ["Content"] = "再说了，辩论辩论，说白了就是嘴皮子一掀就能做的，我见你口齿伶俐，说不定在辩论一事上颇有天赋呢？",
            ["DialogueId"] = 51178014,
            ["GUID"] = "801E68EC",
            },
        [51178015] = {
            ["Content"] = "这样，本来分殊学院内部的辩论流程应该是要提前申请，再开论台请人鉴辩，最终由鉴辩者分出高低。",
            ["DialogueId"] = 51178015,
            ["GUID"] = "801E6916",
            },
        [51178016] = {
            ["Content"] = "不过看在你第一次尝试，我们便进行一场私下较量，只碰撞思想，不考虑胜负，如何？",
            ["DialogueId"] = 51178016,
            ["GUID"] = "801E6940",
            },
        [51178017] = {
            ["Content"] = "（你不由开始思索起自己的才智究竟能不能承托起这场莫名其妙的辩论。）",
            ["DialogueId"] = 51178017,
            ["GUID"] = "801E696A",
            },
        [51178018] = {
            ["Content"] = "算了，我还是不感兴趣。",
            ["DialogueId"] = 51178018,
            ["GUID"] = "801E6994",
            },
        [51178019] = {
            ["Content"] = "……罢了，罢了，只能说是缘分未至……",
            ["DialogueId"] = 51178019,
            ["GUID"] = "801E69BE",
            },
        [51178020] = {
            ["Content"] = "好，你说说辩题，我陪你玩玩。",
            ["DialogueId"] = 51178020,
            ["GUID"] = "801E69E8",
            },
        [51178021] = {
            ["Content"] = "哎呀！阁下也是爽快人！我的辩题十分简单，即：旁观者清亦或旁观者不清，你想选哪边？",
            ["DialogueId"] = 51178021,
            ["GUID"] = "801E6A12",
            },
        [51178022] = {
            ["Content"] = "旁观者清。",
            ["DialogueId"] = 51178022,
            ["GUID"] = "801E6A3C",
            },
        [51178023] = {
            ["Content"] = "好啊，那便是正方了。",
            ["DialogueId"] = 51178023,
            ["GUID"] = "801E6A66",
            },
        [51178024] = {
            ["Content"] = "（砚台清故意咳嗽了两声，挺胸抬头，摆出一副正经的样子，脸也板正了起来。）",
            ["DialogueId"] = 51178024,
            ["GUID"] = "801E6A90",
            },
        [51178025] = {
            ["Content"] = "既然你选了这个，那你便先提出你的观点吧，随便说就行，想怎么说就怎么说！",
            ["DialogueId"] = 51178025,
            ["GUID"] = "801E6ABA",
            },
        [51178026] = {
            ["Content"] = "（你开始思索你对于旁观者清的理解，或许举例描述会更直白？）",
            ["DialogueId"] = 51178026,
            ["GUID"] = "801E6AE4",
            },
        [51178027] = {
            ["Content"] = "以下棋为例。",
            ["DialogueId"] = 51178027,
            ["GUID"] = "801E6B0E",
            },
        [51178028] = {
            ["Content"] = "我在酒馆见过别人下棋，他们往往会将所有心力都沉浸在当前的棋局之中，每一枚棋子要放在哪个格子上，都需要经过多种思考。",
            ["DialogueId"] = 51178028,
            ["GUID"] = "801E6B38",
            },
        [51178029] = {
            ["Content"] = "但这也直接导致了他们无法顾及全盘的局势，过于将心思放在这一枚棋子之上。",
            ["DialogueId"] = 51178029,
            ["GUID"] = "801E6B62",
            },
        [51178030] = {
            ["Content"] = "与此同时，在一边观看他们下棋的人则很容易就能分辨出来谁可能会赢，因为他们可以将全部的精力用于分析局势，而不是研究这一枚棋子。",
            ["DialogueId"] = 51178030,
            ["GUID"] = "801E6B8C",
            },
        [51178031] = {
            ["Content"] = "胡说八道！你说的这是下棋下得不好的笨蛋，而不是真正的国手，要是足够厉害，怎会有你说的这种情况？",
            ["DialogueId"] = 51178031,
            ["GUID"] = "801E6BB6",
            },
        [51178032] = {
            ["Content"] = "以生意为例。",
            ["DialogueId"] = 51178032,
            ["GUID"] = "801E6BE0",
            },
        [51178033] = {
            ["Content"] = "我曾听一位熟悉做生意的酒馆老板说起，谈判极为重要，但参与谈判的人有时并不能明确繁杂的利润算法。",
            ["DialogueId"] = 51178033,
            ["GUID"] = "801E6C0A",
            },
        [51178034] = {
            ["Content"] = "他们经常会被对方开出的短期利益迷惑，从而忘记自己的长久目的，造成谈判失误。",
            ["DialogueId"] = 51178034,
            ["GUID"] = "801E6C34",
            },
        [51178035] = {
            ["Content"] = "所以他们会多带一两个人，那带过去的人就相当于他们的警钟，在他们快要迷失之时拉他们一把。",
            ["DialogueId"] = 51178035,
            ["GUID"] = "801E6C5E",
            },
        [51178036] = {
            ["Content"] = "胡说八道！你说的这是做生意做不明白的笨蛋，而不是真正的大商贾，要是足够厉害，怎会有你说的这种情况？",
            ["DialogueId"] = 51178036,
            ["GUID"] = "801E6C88",
            },
        [51178037] = {
            ["Content"] = "旁观者不清。",
            ["DialogueId"] = 51178037,
            ["GUID"] = "801E6CB2",
            },
        [51178038] = {
            ["Content"] = "好啊，那便是反方了。",
            ["DialogueId"] = 51178038,
            ["GUID"] = "801E6CDC",
            },
        [51178039] = {
            ["Content"] = "既然你选了这个，那你便先提出你的观点吧，随便说就行，想怎么说就怎么说！",
            ["DialogueId"] = 51178039,
            ["GUID"] = "801E6D06",
            },
        [51178040] = {
            ["Content"] = "（你开始思索你对于旁观者不清的理解，或许举例描述会更直白？）",
            ["DialogueId"] = 51178040,
            ["GUID"] = "801E6D30",
            },
        [51178041] = {
            ["Content"] = "以大风九章为例。",
            ["DialogueId"] = 51178041,
            ["GUID"] = "801E6D5A",
            },
        [51178042] = {
            ["Content"] = "我听一位飘零人说过，大风九章有时在尚未摸清事情的始末之时，便会派出狴犴前往执法。",
            ["DialogueId"] = 51178042,
            ["GUID"] = "801E6D84",
            },
        [51178043] = {
            ["Content"] = "导致许多人明明是因为一些不得已的原因犯下错误，却根本得不到辩解的机会。",
            ["DialogueId"] = 51178043,
            ["GUID"] = "801E6DAE",
            },
        [51178044] = {
            ["Content"] = "我想，在这些案件里，大风九章的判决就像是一种另类的旁观者一样，不知全情便进行判断，实在是算不上“清”。",
            ["DialogueId"] = 51178044,
            ["GUID"] = "801E6DD8",
            },
        [51178045] = {
            ["Content"] = "胡说八道！你好大的胆子！怎么敢置喙大风九章的判决？大风九章就是天理，说什么都是对的，怎会不清？",
            ["DialogueId"] = 51178045,
            ["GUID"] = "801E6E02",
            },
        [51178046] = {
            ["Content"] = "以小孩打架为例。",
            ["DialogueId"] = 51178046,
            ["GUID"] = "801E6E2C",
            },
        [51178047] = {
            ["Content"] = "我小时候生活的村子，孩子们常常在玩耍的时候争执，有时候甚至会闹到要打起来的地步。",
            ["DialogueId"] = 51178047,
            ["GUID"] = "801E6E56",
            },
        [51178048] = {
            ["Content"] = "孩子们鼻青脸肿地回家后，关心他们的父母看到伤痕就红了眼。",
            ["DialogueId"] = 51178048,
            ["GUID"] = "801E6E80",
            },
        [51178049] = {
            ["Content"] = "他们直接粗暴地找到其他孩子家里去，甚至不预先询问究竟是因为什么原因打架——比如，是不是他们的孩子先欺负了其他孩子。",
            ["DialogueId"] = 51178049,
            ["GUID"] = "801E6EAA",
            },
        [51178050] = {
            ["Content"] = "在这场斗殴中，孩子是参与者，而父母却是旁观者，但父母却不愿追究这场争斗的原因，只是因为自己的孩子受伤了，就要惩罚其他孩子。",
            ["DialogueId"] = 51178050,
            ["GUID"] = "801E6ED4",
            },
        [51178051] = {
            ["Content"] = "虽说是出于对孩子的关爱，但……我觉得这应该也是一种旁观者不清吧？",
            ["DialogueId"] = 51178051,
            ["GUID"] = "801E6EFE",
            },
        [51178052] = {
            ["Content"] = "胡说八道！我不管你什么村子，打架了、出手伤人那就是不对的，这在我们华胥是要被狴犴大人惩罚的！",
            ["DialogueId"] = 51178052,
            ["GUID"] = "801E6F28",
            },
        [51178053] = {
            ["Content"] = "（听到砚台清莫名其妙的话，你不由得眉头一皱。）",
            ["DialogueId"] = 51178053,
            ["GUID"] = "801E6F52",
            },
        [51178054] = {
            ["Content"] = "我们不是在辩论吗？你为什么不说你的观点，而是突然气急败坏？",
            ["DialogueId"] = 51178054,
            ["GUID"] = "801E6F7C",
            },
        [51178055] = {
            ["Content"] = "这就是我的辩论道理！不然难道要任由你这样胡言乱语？",
            ["DialogueId"] = 51178055,
            ["GUID"] = "801E6FA6",
            },
        [51178056] = {
            ["Content"] = "（你回想起了他最开始说的话……）",
            ["DialogueId"] = 51178056,
            ["GUID"] = "801E6FD0",
            },
        [51178057] = {
            ["Content"] = "（你逐渐理解了为什么没有人愿意与他辩论……）",
            ["DialogueId"] = 51178057,
            ["GUID"] = "801E6FFA",
            },
        [51178058] = {
            ["Content"] = "不可理喻。",
            ["DialogueId"] = 51178058,
            ["GUID"] = "801E7024",
            },
        [51178059] = {
            ["Content"] = "你说什么呢？你骂我？",
            ["DialogueId"] = 51178059,
            ["GUID"] = "801E704E",
            },
        [51178060] = {
            ["Content"] = "不理他。",
            ["DialogueId"] = 51178060,
            ["GUID"] = "801E7078",
            },
        [51178061] = {
            ["Content"] = "（你径自走开，不理会在你身后跳脚大骂的砚台清。）",
            ["DialogueId"] = 51178061,
            ["GUID"] = "801E70A2",
            },
        [51178062] = {
            ["Content"] = "吓唬他。",
            ["DialogueId"] = 51178062,
            ["GUID"] = "801E70CC",
            },
        [51178063] = {
            ["Content"] = "最近走夜路小心点。",
            ["DialogueId"] = 51178063,
            ["GUID"] = "801E70F6",
            },
        [51178064] = {
            ["Content"] = "（你握紧了腰间的刀柄，向他威慑性地亮了亮，然后转身离开。）",
            ["DialogueId"] = 51178064,
            ["GUID"] = "801E7120",
            },
        [51178101] = {
            ["Content"] = "要说最为复杂的调解案……",
            ["DialogueId"] = 51178101,
            ["GUID"] = "801E7732",
            },
        [51178102] = {
            ["Content"] = "要说最为复杂的案件……莫过于十年前的那场意外了。",
            ["DialogueId"] = 51178102,
            ["GUID"] = "801E775C",
            },
        [51178103] = {
            ["Content"] = "你毕竟也是刚来做调解人，这样的事件说给你实在有些……",
            ["DialogueId"] = 51178103,
            ["GUID"] = "801E7786",
            },
        [51178104] = {
            ["Content"] = "姐，能一样吗？我可是新晋的调解人里接受度最高，能力也最为出众，口才也最好的那一位了。你就说给我听听吧~",
            ["DialogueId"] = 51178104,
            ["GUID"] = "801E77B0",
            },
        [51178105] = {
            ["Content"] = "我看你是嘴最贫，心眼子最多的那个还差不多！",
            ["DialogueId"] = 51178105,
            ["GUID"] = "801E77DA",
            },
        [51178106] = {
            ["Content"] = "（默不作声假装靠近……）",
            ["DialogueId"] = 51178106,
            ["GUID"] = "801E7804",
            },
        [51178107] = {
            ["Content"] = "（没意思，走吧。）",
            ["DialogueId"] = 51178107,
            ["GUID"] = "801E782E",
            },
        [51178108] = {
            ["Content"] = "那件事说起来是十年前，但对我来说，就像在昨天一样。",
            ["DialogueId"] = 51178108,
            ["GUID"] = "801E7858",
            },
        [51178109] = {
            ["Content"] = "那日，我的舅父浑身浴血，急匆匆从外面赶了回来。",
            ["DialogueId"] = 51178109,
            ["GUID"] = "801E7882",
            },
        [51178110] = {
            ["Content"] = "我看到时，吓了一跳，以为是他在外遇到了危险……",
            ["DialogueId"] = 51178110,
            ["GUID"] = "801E78AC",
            },
        [51178111] = {
            ["Content"] = "他慌里慌张的，喘着粗气，话也说不利索。他说：死人了。",
            ["DialogueId"] = 51178111,
            ["GUID"] = "801E78D6",
            },
        [51178112] = {
            ["Content"] = "死人？死的是谁？咱们不是有狴犴大人执法吗？如果真闹出了什么恶性事件，狴犴大人岂不是直接就将犯人逮捕了？",
            ["DialogueId"] = 51178112,
            ["GUID"] = "801E7900",
            },
        [51178113] = {
            ["Content"] = "嗯哼~常理来说如此，但那件事并非常理之中。",
            ["DialogueId"] = 51178113,
            ["GUID"] = "801E792A",
            },
        [51178114] = {
            ["Content"] = "遇害的那位是一名学堂的孩子，因为家境好，父母疏于管教又溺爱，导致性格十分恶劣，在学堂里一直有小霸王之称。",
            ["DialogueId"] = 51178114,
            ["GUID"] = "801E7954",
            },
        [51178115] = {
            ["Content"] = "据说当时的孩子都很怕他，因为他经常威胁别的孩子把零花钱给自己，还会做出一些顽劣的恶作剧整蛊自己的同窗——直到成年，都是顽劣如此。",
            ["DialogueId"] = 51178115,
            ["GUID"] = "801E797E",
            },
        [51178116] = {
            ["Content"] = "诶呀，这孩子真是……可是这样不会被狴犴惩罚吗？",
            ["DialogueId"] = 51178116,
            ["GUID"] = "801E79A8",
            },
        [51178117] = {
            ["Content"] = "（有什么不会被惩罚的恶作剧吗……）",
            ["DialogueId"] = 51178117,
            ["GUID"] = "801E79D2",
            },
        [51178118] = {
            ["Content"] = "（想不出来，你果然是一个善良的孩子。）",
            ["DialogueId"] = 51178118,
            ["GUID"] = "801E79FC",
            },
        [51178119] = {
            ["Content"] = "我小时候，隔壁一个顽劣的孩子喜欢捉弄自己的玩伴。他趁玩伴小睡的时候，把几只螃蟹塞在她装贝壳的陶罐里。",
            ["DialogueId"] = 51178119,
            ["GUID"] = "801E7A26",
            },
        [51178120] = {
            ["Content"] = "玩伴醒来，想把贝壳拿出来玩，就被受惊的螃蟹狠狠地夹了手指。",
            ["DialogueId"] = 51178120,
            ["GUID"] = "801E7A50",
            },
        [51178121] = {
            ["Content"] = "真是个坏孩子。那他后来怎么样了？",
            ["DialogueId"] = 51178121,
            ["GUID"] = "801E7A7A",
            },
        [51178122] = {
            ["Content"] = "他站在一边捧腹大笑，但很快他就笑不出来了，因为我看不过去，和家人一起把他“修理”了一顿，从此之后他就老实了。",
            ["DialogueId"] = 51178122,
            ["GUID"] = "801E7AA4",
            },
        [51178123] = {
            ["Content"] = "若有人管教，能走上正途，也算是一件好事了。只是我说的那小霸王，就没有那么好运了。",
            ["DialogueId"] = 51178123,
            ["GUID"] = "801E7ACE",
            },
        [51178124] = {
            ["Content"] = "——他死了。但杀他的……",
            ["DialogueId"] = 51178124,
            ["GUID"] = "801E7AF8",
            },
        [51178125] = {
            ["Content"] = "什么呀，姐你就别卖关子了！",
            ["DialogueId"] = 51178125,
            ["GUID"] = "801E7B22",
            },
        [51178126] = {
            ["Content"] = "是个傻子。",
            ["DialogueId"] = 51178126,
            ["GUID"] = "801E7B4C",
            },
        [51178127] = {
            ["Content"] = "？！",
            ["DialogueId"] = 51178127,
            ["GUID"] = "801E7B76",
            },
        [51178128] = {
            ["Content"] = "他从娘胎里生出来就和旁人就不大一样，街坊邻居也都可怜他，自小也宽厚待他，只是长大了，送到学堂里，孩子们不懂事，有时便不给他好脸色。",
            ["DialogueId"] = 51178128,
            ["GUID"] = "801E7BA0",
            },
        [51178129] = {
            ["Content"] = "只是不给好脸色久了，那孩子比起旁的孩子就显得有几分怯懦。怯懦久了，孩子们便不再把他当回事，不给他好脸色，或是总差遣他去做些杂活。",
            ["DialogueId"] = 51178129,
            ["GUID"] = "801E7BCA",
            },
        [51178130] = {
            ["Content"] = "如此说来，这不就是在霸凌他吗？我明白了，所以那个欺负得最过分的那位，就是姐你刚才说的……“小霸王”？",
            ["DialogueId"] = 51178130,
            ["GUID"] = "801E7BF4",
            },
        [51178131] = {
            ["Content"] = "没错，“小霸王”总是用玩闹的借口欺负傻的那位，可也是在一次玩闹里，那痴傻少年不小心把人从二楼推了下去，当场便没了气。",
            ["DialogueId"] = 51178131,
            ["GUID"] = "801E7C1E",
            },
        [51178132] = {
            ["Content"] = "傻孩子还不知道发生了什么，见那血流了三尺，围观者无不尖叫呼救，他只意味站在原地拍手傻乐。",
            ["DialogueId"] = 51178132,
            ["GUID"] = "801E7C48",
            },
        [51178133] = {
            ["Content"] = "然后呢？狴犴大人是如何裁决的？",
            ["DialogueId"] = 51178133,
            ["GUID"] = "801E7C72",
            },
        [51178134] = {
            ["Content"] = "自然是飞速赶来，同样将傻孩子的命带走了，可怜那孩子的母亲，十月怀胎生下他，当的是心头肉一样拉扯他，好不容易长大成人，却得到这般结局。",
            ["DialogueId"] = 51178134,
            ["GUID"] = "801E7C9C",
            },
        [51178135] = {
            ["Content"] = "冤情难解，尤其是她四处走访得知自己的孩子生前遭遇，更是哭瞎了眼。只能到处拜托近亲远邻，求他们换自己一个公道。",
            ["DialogueId"] = 51178135,
            ["GUID"] = "801E7CC6",
            },
        [51178136] = {
            ["Content"] = "大伙儿纷纷避之不及，只有我的舅父心热，因着当时亲历现场，所以一路陪她诉冤陪到底。",
            ["DialogueId"] = 51178136,
            ["GUID"] = "801E7CF0",
            },
        [51178137] = {
            ["Content"] = "所以最终的结局是什么？",
            ["DialogueId"] = 51178137,
            ["GUID"] = "801E7D1A",
            },
        [51178138] = {
            ["Content"] = "虽然很想告诉你，但是我当时也只是个十几岁的孩子，所以这件事的结果，我不知道。",
            ["DialogueId"] = 51178138,
            ["GUID"] = "801E7D44",
            },
        [51178139] = {
            ["Content"] = "不知道？！姐，你就别拿我开玩笑了，就告诉我吧！",
            ["DialogueId"] = 51178139,
            ["GUID"] = "801E7D6E",
            },
        [51178140] = {
            ["Content"] = "我是真的不晓得结果是什么，几次和舅父探听，也没有得到答案。不过，我今日来问问你们，你们觉得这场案件的结果会是什么呢？",
            ["DialogueId"] = 51178140,
            ["GUID"] = "801E7D98",
            },
        }
  end },
  { MinKey = 51178141, MaxKey = 51178633, Loader = function()
      return {
        [51178141] = {
            ["Content"] = "我认为杀人者的母亲取得了自己的公道。",
            ["DialogueId"] = 51178141,
            ["GUID"] = "801E7DC2",
            },
        [51178142] = {
            ["Content"] = "我想……她应该得到了公道。就算死者不能复活，也不能让他背负罪犯的恶名。无论怎么说，这件事都不能算是蓄意伤人，顶多算是一场意外。",
            ["DialogueId"] = 51178142,
            ["GUID"] = "801E7DEC",
            },
        [51178143] = {
            ["Content"] = "你说得对，如果这事放在今日改制后的华胥，我也会竭尽全力为他的母亲辩护，直至她沉冤得雪。",
            ["DialogueId"] = 51178143,
            ["GUID"] = "801E7E16",
            },
        [51178144] = {
            ["Content"] = "毕竟，我们调解人就是为了这个目的诞生的——裁定罪行的不再是大风九章，而应当是人类自己，不是吗？",
            ["DialogueId"] = 51178144,
            ["GUID"] = "801E7E40",
            },
        [51178145] = {
            ["Content"] = "我认为这件事多半不了了之了。",
            ["DialogueId"] = 51178145,
            ["GUID"] = "801E7E6A",
            },
        [51178146] = {
            ["Content"] = "如果这件事真的让那位孩子的母亲讨回了公道，你的舅父不会因此避而不谈的，只不过是没有做到，所以也不愿告知你，让你伤心。",
            ["DialogueId"] = 51178146,
            ["GUID"] = "801E7E94",
            },
        [51178147] = {
            ["Content"] = "是啊，我们心里其实都晓得，只是不愿去接受这样的结果……",
            ["DialogueId"] = 51178147,
            ["GUID"] = "801E7EBE",
            },
        [51178148] = {
            ["Content"] = "还好，改制后有了我们调解员——裁定罪行的不再是大风九章，而应当是人类自己，不是吗？",
            ["DialogueId"] = 51178148,
            ["GUID"] = "801E7EE8",
            },
        [51178149] = {
            ["Content"] = "但是吧……无论结果如何，其实都谈不上是个好结果。",
            ["DialogueId"] = 51178149,
            ["GUID"] = "801E7F12",
            },
        [51178150] = {
            ["Content"] = "那孩子已经死了，那些是非对错又有什么意义呢？死了的人哪里还会在意自己的名声……",
            ["DialogueId"] = 51178150,
            ["GUID"] = "801E7F3C",
            },
        [51178151] = {
            ["Content"] = "说到底，都是因为狴犴大人它……",
            ["DialogueId"] = 51178151,
            ["GUID"] = "801E7F66",
            },
        [51178152] = {
            ["Content"] = "这话你也敢说？",
            ["DialogueId"] = 51178152,
            ["GUID"] = "801E7F90",
            },
        [51178153] = {
            ["Content"] = "为何不敢说？未知结果之前，盲目断案，错的就是错的，我成为调解人，不就是为了减少这样的事情发生，还更多人一个公道吗？",
            ["DialogueId"] = 51178153,
            ["GUID"] = "801E7FBA",
            },
        [51178154] = {
            ["Content"] = "……噗嗤~",
            ["DialogueId"] = 51178154,
            ["GUID"] = "801E7FE4",
            },
        [51178155] = {
            ["Content"] = "萍姐，你笑什么？",
            ["DialogueId"] = 51178155,
            ["GUID"] = "801E800E",
            },
        [51178156] = {
            ["Content"] = "你能这样想，那就不算浪费我今日唠叨的口舌啦……",
            ["DialogueId"] = 51178156,
            ["GUID"] = "801E8038",
            },
        [51178157] = {
            ["Content"] = "我没理解，姐你到底什么意思嘛？",
            ["DialogueId"] = 51178157,
            ["GUID"] = "801E8062",
            },
        [51178158] = {
            ["Content"] = "没事没事，今天的故事时间结束了，我还要回去整理卷宗，你也得一起。",
            ["DialogueId"] = 51178158,
            ["GUID"] = "801E808C",
            },
        [51178159] = {
            ["Content"] = "对啦，这位{性别:公子|姑娘}，不好意思，耽误你许久听我讲这陈芝麻烂谷子的旧事。",
            ["DialogueId"] = 51178159,
            ["GUID"] = "801E80B6",
            },
        [51178160] = {
            ["Content"] = "没关系。",
            ["DialogueId"] = 51178160,
            ["GUID"] = "801E80E0",
            },
        [51178161] = {
            ["Content"] = "既然如此，那我们也不再叨扰了，再见。",
            ["DialogueId"] = 51178161,
            ["GUID"] = "801E810A",
            },
        [51178162] = {
            ["Content"] = "还不回去是要等到什么时候？",
            ["DialogueId"] = 51178162,
            ["GUID"] = "801E814C",
            },
        [51178163] = {
            ["Content"] = "再等等嘛，卷宗是整不完的，还是先珍惜一下我们难得的休息时间吧！",
            ["DialogueId"] = 51178163,
            ["GUID"] = "801E818E",
            },
        [51178201] = {
            ["Content"] = "若是法理不通……",
            ["DialogueId"] = 51178201,
            ["GUID"] = "801E879A",
            },
        [51178202] = {
            ["Content"] = "若是法理不通，又怎敢把评判的权利交由那劳什子人心私情？",
            ["DialogueId"] = 51178202,
            ["GUID"] = "801E87C4",
            },
        [51178203] = {
            ["Content"] = "（眼前的男人趾高气昂地向人们大肆宣扬着，你不由地走近了些，想听听他说的是什么。）",
            ["DialogueId"] = 51178203,
            ["GUID"] = "801E87EE",
            },
        [51178204] = {
            ["Content"] = "本来咱们华胥的大风九章是多么完善的制度？",
            ["DialogueId"] = 51178204,
            ["GUID"] = "801E8818",
            },
        [51178205] = {
            ["Content"] = "对就是对，错就是错，杀人就要偿命，伤人就要惩处，一切都简单明了，勿需他人来断。",
            ["DialogueId"] = 51178205,
            ["GUID"] = "801E8842",
            },
        [51178206] = {
            ["Content"] = "现在倒好，弄出个劳什子改制。狴犴大人过去了，把人带回收押，期间不知道多少纠葛不足为外人道也，几番周折，罪行也被人忘了，不了了之了！",
            ["DialogueId"] = 51178206,
            ["GUID"] = "801E886C",
            },
        [51178207] = {
            ["Content"] = "我华胥千年天人律法竟就此断送，以后，该怎么办呐！",
            ["DialogueId"] = 51178207,
            ["GUID"] = "801E8896",
            },
        [51178208] = {
            ["Content"] = "（这家伙肆意倾泻着对于大风九章改制的不满，想想用什么话来反驳他吧。）",
            ["DialogueId"] = 51178208,
            ["GUID"] = "801E88C0",
            },
        [51178209] = {
            ["Content"] = "（说点什么来反驳他。）",
            ["DialogueId"] = 51178209,
            ["GUID"] = "801E88EA",
            },
        [51178210] = {
            ["Content"] = "（你似乎想不到该说什么，对于这种人似乎也没什么好说的。）",
            ["DialogueId"] = 51178210,
            ["GUID"] = "801E8914",
            },
        [51178211] = {
            ["Content"] = "你对华胥人好像缺乏应有的尊重。",
            ["DialogueId"] = 51178211,
            ["GUID"] = "801E893E",
            },
        [51178212] = {
            ["Content"] = "什么？你什么意思？",
            ["DialogueId"] = 51178212,
            ["GUID"] = "801E8968",
            },
        [51178213] = {
            ["Content"] = "按你的说法，你把华胥人说得很愚蠢，失去了神君的判断就没有办法独立行走。",
            ["DialogueId"] = 51178213,
            ["GUID"] = "801E8992",
            },
        [51178214] = {
            ["Content"] = "绝无此意！且听我道来。",
            ["DialogueId"] = 51178214,
            ["GUID"] = "801E89BC",
            },
        [51178215] = {
            ["Content"] = "如果现在的人知晓了谋财害命的下场不是被狴犴惩处，而是被抓起来，经历审讯，那他们的心中便不会畏惧。",
            ["DialogueId"] = 51178215,
            ["GUID"] = "801E89E6",
            },
        [51178216] = {
            ["Content"] = "而畏惧就是栓马的木桩，是囚禁兀鹫的牢笼，是限制河水肆意横流的河堤。",
            ["DialogueId"] = 51178216,
            ["GUID"] = "801E8A10",
            },
        [51178217] = {
            ["Content"] = "失去了畏惧，那些阴暗的念头就会不断滋生，蔓延，直至大家又因为兵戈相见而惴惴不安，这还是华胥吗？还是和平的，安宁的华胥吗？",
            ["DialogueId"] = 51178217,
            ["GUID"] = "801E8A3A",
            },
        [51178218] = {
            ["Content"] = "就算大风九章有错，也好过减轻惩罚，让人们忘却畏惧之心！",
            ["DialogueId"] = 51178218,
            ["GUID"] = "801E8A64",
            },
        [51178219] = {
            ["Content"] = "你又不是其他人，怎么知道其他华胥人都像你所说的那样心怀不轨呢？还是说你本身是这样的人，于是就拿这样的念头去揣度别人？",
            ["DialogueId"] = 51178219,
            ["GUID"] = "801E8A8E",
            },
        [51178220] = {
            ["Content"] = "我只是假设，我是说假设！你敢保证没有这样的情况发生吗？",
            ["DialogueId"] = 51178220,
            ["GUID"] = "801E8AB8",
            },
        [51178221] = {
            ["Content"] = "（搬出止流。）",
            ["DialogueId"] = 51178221,
            ["GUID"] = "801E8AE2",
            },
        [51178222] = {
            ["Content"] = "我听说，龙渊上卿就是神君的选择。",
            ["DialogueId"] = 51178222,
            ["GUID"] = "801E8B0C",
            },
        [51178223] = {
            ["Content"] = "既然你相信神君，那你应该选择相信止流——白龙神君选择的龙渊上卿，相信她的判断。",
            ["DialogueId"] = 51178223,
            ["GUID"] = "801E8B36",
            },
        [51178224] = {
            ["Content"] = "止流推动的改制，或许正是神君自己的旨意。",
            ["DialogueId"] = 51178224,
            ["GUID"] = "801E8B60",
            },
        [51178225] = {
            ["Content"] = "神君自己的旨意？不，难道说……",
            ["DialogueId"] = 51178225,
            ["GUID"] = "801E8B8A",
            },
        [51178226] = {
            ["Content"] = "（讲道理。）",
            ["DialogueId"] = 51178226,
            ["GUID"] = "801E8BB4",
            },
        [51178227] = {
            ["Content"] = "可即使是过去的大风九章，也无法阻止那些存心想做恶事的人。相反，我见过微茫市一群圆滑老道的家伙是如何钻大风九章的空子，逃避惩罚。",
            ["DialogueId"] = 51178227,
            ["GUID"] = "801E8BDE",
            },
        [51178228] = {
            ["Content"] = "但那些过去因为大风九章错判而被狴犴夺去性命的人，却再也回不来了。",
            ["DialogueId"] = 51178228,
            ["GUID"] = "801E8C08",
            },
        [51178229] = {
            ["Content"] = "我想……相比严酷，可能“确定”和“公正”更重要吧？——确保每一个做错事的人受到惩罚，给每一个被错判的人以纠正的机会。",
            ["DialogueId"] = 51178229,
            ["GUID"] = "801E8C32",
            },
        [51178230] = {
            ["Content"] = "这才是律法的意义，不是吗？",
            ["DialogueId"] = 51178230,
            ["GUID"] = "801E8C5C",
            },
        [51178231] = {
            ["Content"] = "确定和公正……难道说……",
            ["DialogueId"] = 51178231,
            ["GUID"] = "801E8C86",
            },
        [51178232] = {
            ["Content"] = "你，你说的好像也有点道理，我想想……",
            ["DialogueId"] = 51178232,
            ["GUID"] = "801E8CB0",
            },
        [51178233] = {
            ["Content"] = "（你眼前的男人在你面前失落地喃喃自语，你察觉到他只是有些恐惧——对于华胥即将迎来的改制，对于充满不确定性的未来。）",
            ["DialogueId"] = 51178233,
            ["GUID"] = "801E8CDA",
            },
        [51178234] = {
            ["Content"] = "（但无论如何，变革已然发生——它也必然会发生。）",
            ["DialogueId"] = 51178234,
            ["GUID"] = "801E8D04",
            },
        [51178235] = {
            ["Content"] = "我想想……我再想想……",
            ["DialogueId"] = 51178235,
            ["GUID"] = "801E8D46",
            },
        [51178301] = {
            ["Content"] = "这些木头块都没意思！",
            ["DialogueId"] = 51178301,
            ["GUID"] = "801E9802",
            },
        [51178302] = {
            ["Content"] = "现在敲敲打打的这些木头块，那都没意思！要是放在以前，我能给你们看带劲的大家伙！",
            ["DialogueId"] = 51178302,
            ["GUID"] = "801E982C",
            },
        [51178303] = {
            ["Content"] = "想当初，我造的那可都是惊天地泣鬼神的东西，知道应龙壹型吗，那可是我仿造龙君的外型制造出的大型机傀。",
            ["DialogueId"] = 51178303,
            ["GUID"] = "801E9856",
            },
        [51178304] = {
            ["Content"] = "可惜啊……那帮不长眼胆子小的，说什么，不敬龙君……什么恐伤路人……什么能止孩儿夜啼……",
            ["DialogueId"] = 51178304,
            ["GUID"] = "801E9880",
            },
        [51178305] = {
            ["Content"] = "连启动都没有，连夜拆了个干净，可怜我花了多少心血，却见一眼他动起来的样子都不行……",
            ["DialogueId"] = 51178305,
            ["GUID"] = "801E98AA",
            },
        [51178306] = {
            ["Content"] = "至少你还见过他被拆成碎片的样子。",
            ["DialogueId"] = 51178306,
            ["GUID"] = "801E98D4",
            },
        [51178307] = {
            ["Content"] = "你！你这家伙！怎么这么说话的！呜呜呜……我的应龙壹型，呜啊！",
            ["DialogueId"] = 51178307,
            ["GUID"] = "801E98FE",
            },
        [51178308] = {
            ["Content"] = "拆了之后的碎片做什么了？",
            ["DialogueId"] = 51178308,
            ["GUID"] = "801E9928",
            },
        [51178309] = {
            ["Content"] = "还能做什么……当然是再利用成了那些小玩具的零件……呜……可怜了我的应龙壹型，呜啊！",
            ["DialogueId"] = 51178309,
            ["GUID"] = "801E9952",
            },
        [51178310] = {
            ["Content"] = "（老大不小的男人在你面前哭得像个稚嫩的孩子，看起来十分可怜。）",
            ["DialogueId"] = 51178310,
            ["GUID"] = "801E997C",
            },
        [51178311] = {
            ["Content"] = "（你挑起来的，还是安慰安慰他吧。）",
            ["DialogueId"] = 51178311,
            ["GUID"] = "801E99A6",
            },
        [51178312] = {
            ["Content"] = "（想不到该说什么，你实在不会安慰人。）",
            ["DialogueId"] = 51178312,
            ["GUID"] = "801E99D0",
            },
        [51178313] = {
            ["Content"] = "别哭了，是我不好，让你想起了难过的事情。",
            ["DialogueId"] = 51178313,
            ["GUID"] = "801E99FA",
            },
        [51178314] = {
            ["Content"] = "嘶……不，不怪你，我只是感叹机枢派近些年来落魄至此。",
            ["DialogueId"] = 51178314,
            ["GUID"] = "801E9A24",
            },
        [51178315] = {
            ["Content"] = "曾经的机枢派，是多么百花齐放，书本上说，机傀术几乎每天都会进行迭代。更优越的性能，更炫酷的外型……",
            ["DialogueId"] = 51178315,
            ["GUID"] = "801E9A4E",
            },
        [51178316] = {
            ["Content"] = "而现在呢，没法做出什么创新了。有也只是小打小闹，多么无趣，我只恨自己生的晚，没能亲历那个辉煌的年代。",
            ["DialogueId"] = 51178316,
            ["GUID"] = "801E9A78",
            },
        [51178317] = {
            ["Content"] = "只要你潜心钻研，以后说不定会好起来的，可以再造一个……应龙贰型？",
            ["DialogueId"] = 51178317,
            ["GUID"] = "801E9AA2",
            },
        [51178318] = {
            ["Content"] = "实不相瞒，我最近已有了一些念头，就是关于重建应龙壹型的，不对，现在应该叫应龙贰型。",
            ["DialogueId"] = 51178318,
            ["GUID"] = "801E9ACC",
            },
        [51178319] = {
            ["Content"] = "早年的设计稍许还是有些稚嫩，比如耗能过高，机体容易过热，还有外型过于庞大，移动不是很方便……",
            ["DialogueId"] = 51178319,
            ["GUID"] = "801E9AF6",
            },
        [51178320] = {
            ["Content"] = "虽然我的确有了一些想法，但我也想听听别人的意见……对了，你觉得你理想中的机傀应该是什么样子，没关系，随便说就行，只当是聊天就好。",
            ["DialogueId"] = 51178320,
            ["GUID"] = "801E9B20",
            },
        [51178321] = {
            ["Content"] = "机傀就应该强大！战无不胜！",
            ["DialogueId"] = 51178321,
            ["GUID"] = "801E9B4A",
            },
        [51178322] = {
            ["Content"] = "强大……没错，我也这么觉得，这也是我设计应龙形态机傀的初衷，毕竟在华胥，没有什么比龙神更为强大的东西了。",
            ["DialogueId"] = 51178322,
            ["GUID"] = "801E9B74",
            },
        [51178323] = {
            ["Content"] = "既然你也觉得强大是对的，那我在下次设计应龙贰型时，将重点放在供能和耗能相关上吧……",
            ["DialogueId"] = 51178323,
            ["GUID"] = "801E9B9E",
            },
        [51178324] = {
            ["Content"] = "强是暂时的，但帅气是一辈子的。",
            ["DialogueId"] = 51178324,
            ["GUID"] = "801E9BC8",
            },
        [51178325] = {
            ["Content"] = "帅气……没错！你说的很有道理，日后华胥的机傀术一定会再现曾经的荣光。",
            ["DialogueId"] = 51178325,
            ["GUID"] = "801E9BF2",
            },
        [51178326] = {
            ["Content"] = "当更新迭代的速度过快时，我即使做出了当前最为强大的机傀，没两天也会被淘汰。",
            ["DialogueId"] = 51178326,
            ["GUID"] = "801E9C1C",
            },
        [51178327] = {
            ["Content"] = "所以，我就应该在外型上多下些功夫，比如我把外甲替换为汉白玉如何？一定艳惊四座！",
            ["DialogueId"] = 51178327,
            ["GUID"] = "801E9C46",
            },
        [51178328] = {
            ["Content"] = "机傀一定要有娱乐性。",
            ["DialogueId"] = 51178328,
            ["GUID"] = "801E9C70",
            },
        [51178329] = {
            ["Content"] = "娱乐……性？我没有特别理解你的意思，你是说，机傀要有趣？好玩？这听起来好像和现在的机傀方向没什么相关性。",
            ["DialogueId"] = 51178329,
            ["GUID"] = "801E9C9A",
            },
        [51178330] = {
            ["Content"] = "哦哦！我明白了，你的意思是，机傀应该剑走偏锋，比如我设计出一个龙君外型的机傀，它如果会唱歌跳舞，那一定十分受人欢迎。",
            ["DialogueId"] = 51178330,
            ["GUID"] = "801E9CC4",
            },
        [51178331] = {
            ["Content"] = "是啊，我怎么没想到呢，如果当时我的应龙壹型可以给那些家伙唱首歌，说不定他们就乐颠颠地拍手叫好，也不会拆了它……",
            ["DialogueId"] = 51178331,
            ["GUID"] = "801E9CEE",
            },
        [51178332] = {
            ["Content"] = "你的建议我完全明白了，我相信我会设计出一个最完美的应龙贰型！",
            ["DialogueId"] = 51178332,
            ["GUID"] = "801E9D18",
            },
        [51178333] = {
            ["Content"] = "等到应龙贰型落地后，我一定第一个找你来看看！",
            ["DialogueId"] = 51178333,
            ["GUID"] = "801E9D42",
            },
        [51178334] = {
            ["Content"] = "怎么这么快就回来了，应龙贰型还没头绪呢！",
            ["DialogueId"] = 51178334,
            ["GUID"] = "801E9D84",
            },
        [51178401] = {
            ["Content"] = "皎皎为何不能当香官？",
            ["DialogueId"] = 51178401,
            ["GUID"] = "801EA86A",
            },
        [51178402] = {
            ["Content"] = "皎皎为何不能当香官？我偏要当这皎皎第一人！",
            ["DialogueId"] = 51178402,
            ["GUID"] = "801EA894",
            },
        [51178403] = {
            ["Content"] = "（在你面前的这位皎皎双手叉腰，似乎在和谁较劲一般，气得面红耳赤。）",
            ["DialogueId"] = 51178403,
            ["GUID"] = "801EA8BE",
            },
        [51178404] = {
            ["Content"] = "你你你！你看什么看！你也觉得我不能当香官？",
            ["DialogueId"] = 51178404,
            ["GUID"] = "801EA8E8",
            },
        [51178405] = {
            ["Content"] = "我没这么说，是你自己说的。",
            ["DialogueId"] = 51178405,
            ["GUID"] = "801EA912",
            },
        [51178406] = {
            ["Content"] = "分明就是有！你的眼神，你的行为，你嘴巴弯起的弧度，都在挑衅我！",
            ["DialogueId"] = 51178406,
            ["GUID"] = "801EA93C",
            },
        [51178407] = {
            ["Content"] = "我只是在呼吸。",
            ["DialogueId"] = 51178407,
            ["GUID"] = "801EA966",
            },
        [51178408] = {
            ["Content"] = "挺好的啊，我没这么觉得。",
            ["DialogueId"] = 51178408,
            ["GUID"] = "801EA990",
            },
        [51178409] = {
            ["Content"] = "真的吗？！看你飘忽不定的眼神，该不会是随便说些好听的话来哄我的吧？",
            ["DialogueId"] = 51178409,
            ["GUID"] = "801EA9BA",
            },
        [51178410] = {
            ["Content"] = "真的啊，我像在哄你吗？",
            ["DialogueId"] = 51178410,
            ["GUID"] = "801EA9E4",
            },
        [51178411] = {
            ["Content"] = "嗯……嗯……好吧，那我就相信你了！",
            ["DialogueId"] = 51178411,
            ["GUID"] = "801EAA0E",
            },
        [51178412] = {
            ["Content"] = "大头鱼还能当香官？",
            ["DialogueId"] = 51178412,
            ["GUID"] = "801EAA38",
            },
        [51178413] = {
            ["Content"] = "骂谁大头鱼呢！",
            ["DialogueId"] = 51178413,
            ["GUID"] = "801EAA62",
            },
        [51178414] = {
            ["Content"] = "谁应了谁就是大头鱼。",
            ["DialogueId"] = 51178414,
            ["GUID"] = "801EAA8C",
            },
        [51178415] = {
            ["Content"] = "哼！本香官和其他一触即炸的皎皎们可不一样，我可是经受过专业教育，这种小小的挑衅才不会放在眼里呢！",
            ["DialogueId"] = 51178415,
            ["GUID"] = "801EAAB6",
            },
        [51178416] = {
            ["Content"] = "反正无论怎么样努力都要被质疑……我早就习惯了……",
            ["DialogueId"] = 51178416,
            ["GUID"] = "801EAAE0",
            },
        [51178417] = {
            ["Content"] = "他们只看到我当上香官时的风风光光，怎么就不看我从最开始压根不认识华胥字，到现在可以对《香籍》倒背如流？",
            ["DialogueId"] = 51178417,
            ["GUID"] = "801EAB0A",
            },
        [51178418] = {
            ["Content"] = "他们都说皎皎一族只要负责可爱就好了，可以被大个子们抱起来捏捏脸揉揉头发就好，但我不想成为这样的皎皎。",
            ["DialogueId"] = 51178418,
            ["GUID"] = "801EAB34",
            },
        [51178419] = {
            ["Content"] = "我觉得我应该要更特殊一些，大家看到我的时候想到的不是：啊，这是一个皎皎。",
            ["DialogueId"] = 51178419,
            ["GUID"] = "801EAB5E",
            },
        [51178420] = {
            ["Content"] = "而是：快看呐，是那个很厉害的香官皎皎！",
            ["DialogueId"] = 51178420,
            ["GUID"] = "801EAB88",
            },
        [51178421] = {
            ["Content"] = "我觉得你已经做到了。",
            ["DialogueId"] = 51178421,
            ["GUID"] = "801EABB2",
            },
        [51178422] = {
            ["Content"] = "人们对你的香官身份产生质疑，不正是说明他们想起你的时候冒出的第一个身份是香官皎皎，而不是一位普通的皎皎吗？",
            ["DialogueId"] = 51178422,
            ["GUID"] = "801EABDC",
            },
        [51178423] = {
            ["Content"] = "剩下的，有关你能不能胜任这个职位的事情，不如就交给时间来证明吧。",
            ["DialogueId"] = 51178423,
            ["GUID"] = "801EAC06",
            },
        [51178424] = {
            ["Content"] = "你说得对。只要我做好自己的本职工作，那些闲言碎语的人迟早会意识到我有多厉害，我只要一直努力，一直向上走……",
            ["DialogueId"] = 51178424,
            ["GUID"] = "801EAC30",
            },
        [51178425] = {
            ["Content"] = "一定！我一定可以做到的！",
            ["DialogueId"] = 51178425,
            ["GUID"] = "801EAC5A",
            },
        [51178426] = {
            ["Content"] = "（她的脸上扬起明媚而自信的笑容，比今天的阳光还要耀眼。）",
            ["DialogueId"] = 51178426,
            ["GUID"] = "801EAC84",
            },
        [51178427] = {
            ["Content"] = "愿你善根常驻……咦？是你~你回来看我啦~",
            ["DialogueId"] = 51178427,
            ["GUID"] = "801EACC6",
            },
        [51178501] = {
            ["Content"] = "这些往事，我可全都记着呢！",
            ["DialogueId"] = 51178501,
            ["GUID"] = "801EB8D2",
            },
        [51178502] = {
            ["Content"] = "想起来了，我可都想起来了，这些往事，我可全都记着呢！",
            ["DialogueId"] = 51178502,
            ["GUID"] = "801EB8FC",
            },
        [51178503] = {
            ["Content"] = "你……就是你，你快过来，趁着我还清醒，这事我要说给你听，不然在月光拐过墙头时，我可能就什么也想不起来了……",
            ["DialogueId"] = 51178503,
            ["GUID"] = "801EB926",
            },
        [51178504] = {
            ["Content"] = "小娃儿，你愿意耽搁片刻，听老头子我说说这个故事吗？",
            ["DialogueId"] = 51178504,
            ["GUID"] = "801EB950",
            },
        [51178505] = {
            ["Content"] = "我愿意。",
            ["DialogueId"] = 51178505,
            ["GUID"] = "801EB97A",
            },
        [51178506] = {
            ["Content"] = "好，太好了，我要抓紧……",
            ["DialogueId"] = 51178506,
            ["GUID"] = "801EB9A4",
            },
        [51178507] = {
            ["Content"] = "我的时间很宝贵。",
            ["DialogueId"] = 51178507,
            ["GUID"] = "801EB9CE",
            },
        [51178508] = {
            ["Content"] = "不会耽误你太久的，毕竟时间久了，可能我也要忘了……",
            ["DialogueId"] = 51178508,
            ["GUID"] = "801EB9F8",
            },
        [51178509] = {
            ["Content"] = "没空。",
            ["DialogueId"] = 51178509,
            ["GUID"] = "801EBA22",
            },
        [51178510] = {
            ["Content"] = "是吗……那算了，只好等到下一位有缘人，下一位让我想起这些事的有缘人了……",
            ["DialogueId"] = 51178510,
            ["GUID"] = "801EBA4C",
            },
        [51178511] = {
            ["Content"] = "让我想想，这事要从哪里说起来呢……",
            ["DialogueId"] = 51178511,
            ["GUID"] = "801EBA76",
            },
        [51178512] = {
            ["Content"] = "这一片儿，以前都是一家的，那家正是皓京城里赫赫有名的首富——萧府。",
            ["DialogueId"] = 51178512,
            ["GUID"] = "801EBAA0",
            },
        [51178513] = {
            ["Content"] = "我是府上的管事，自小就跟着老爷做事，老爷年轻时经商，攒下了万贯家财，平日里便喜欢收集些古玩书画，我便常年帮他跑东跑西，收集藏品。",
            ["DialogueId"] = 51178513,
            ["GUID"] = "801EBACA",
            },
        [51178514] = {
            ["Content"] = "本想这辈子便也就这样了，谁想到老爷竟老来得子，府里上下欢天喜地。",
            ["DialogueId"] = 51178514,
            ["GUID"] = "801EBAF4",
            },
        [51178515] = {
            ["Content"] = "小公子年幼，但聪慧的很，老爷十分看重他，更是宠得无法无天，不爱读书那便不读，喜欢拿那些老爷的藏品当玩具那也随他。",
            ["DialogueId"] = 51178515,
            ["GUID"] = "801EBB1E",
            },
        [51178516] = {
            ["Content"] = "谁曾想呢，小公子竟成了个纨绔性格，不把所有人看在眼里，还十分挥霍，花起府上的钱来眼也不眨。",
            ["DialogueId"] = 51178516,
            ["GUID"] = "801EBB48",
            },
        [51178517] = {
            ["Content"] = "我当时管着账房，几次向老爷劝阻，他却只摆摆手由着。",
            ["DialogueId"] = 51178517,
            ["GUID"] = "801EBB72",
            },
        [51178518] = {
            ["Content"] = "后来啊，老爷生意出现了问题，府上收入渐少，形势日益严峻。少爷还充耳不闻，整日花天酒地。",
            ["DialogueId"] = 51178518,
            ["GUID"] = "801EBB9C",
            },
        [51178519] = {
            ["Content"] = "老爷心痛，却不好说什么，可能是为了寄托，也可能只是他心善，他从外接回来许多孩子，都是父母因意外离世后没人管的孤儿，养在府中当义子。",
            ["DialogueId"] = 51178519,
            ["GUID"] = "801EBBC6",
            },
        [51178520] = {
            ["Content"] = "那时他已经很老了，坐在那腰也直不起来，眼神也浑浊起来，只在看到孩子们围在他身边叫爷爷时才冒出些光彩来。",
            ["DialogueId"] = 51178520,
            ["GUID"] = "801EBBF0",
            },
        [51178521] = {
            ["Content"] = "没多久，老爷离世了，他嘱咐我葬礼一切从简，省下钱将这些苦命的孩子们拉扯长大，至于少爷……他没吩咐。",
            ["DialogueId"] = 51178521,
            ["GUID"] = "801EBC1A",
            },
        [51178522] = {
            ["Content"] = "萧府的顶梁柱断了，少爷没那个本事管着家里的铺子，但各方的开销还在继续，我只能变卖府上房子，将偌大一个府邸拆成各个房子出售给他人。",
            ["DialogueId"] = 51178522,
            ["GUID"] = "801EBC44",
            },
        [51178523] = {
            ["Content"] = "那些孩子，可怜的孩子们，他们不知道发生了什么，只知道疼他们的爷爷不见了，吃的东西从顿顿好的变成了粗茶淡饭。",
            ["DialogueId"] = 51178523,
            ["GUID"] = "801EBC6E",
            },
        [51178524] = {
            ["Content"] = "少爷没多久就离开了萧府，我不晓得他去哪里了，因我根本没那个闲心去管，那些孩子逐渐长大，我拉扯他们也不容易……",
            ["DialogueId"] = 51178524,
            ["GUID"] = "801EBC98",
            },
        [51178525] = {
            ["Content"] = "一直到那一日……那些孩子里最大的那位，十岁生日的时候……再过几年就可以出去做工的年纪。",
            ["DialogueId"] = 51178525,
            ["GUID"] = "801EBCC2",
            },
        [51178526] = {
            ["Content"] = "我们都围在最后卖剩下的那间主屋里，我去买了米面和蛋，做了长寿面，少爷也赶了回来，他看起来十分憔悴，虽说我们也好不到哪去。",
            ["DialogueId"] = 51178526,
            ["GUID"] = "801EBCEC",
            },
        [51178527] = {
            ["Content"] = "那些孩子，小时候都是健健康康的，可能是我没能好好喂养他们，各个长大后瘦骨嶙峋，动不动就晕倒。",
            ["DialogueId"] = 51178527,
            ["GUID"] = "801EBD16",
            },
        [51178528] = {
            ["Content"] = "我端了面出来，一个二个眼睛冒着光，小狼一样，哧溜哧溜吸口水。",
            ["DialogueId"] = 51178528,
            ["GUID"] = "801EBD40",
            },
        [51178529] = {
            ["Content"] = "那天晚上啊少爷回来了，带着一大篓鱼，鱼又多又大，也有好多种，我都记不太清。",
            ["DialogueId"] = 51178529,
            ["GUID"] = "801EBD6A",
            },
        [51178530] = {
            ["Content"] = "老爷还在世的时候少爷就最喜欢钓鱼，但等他过世的后少爷就一直劳碌，就没怎么挥过杆，没曾想他这本事一直没丢。",
            ["DialogueId"] = 51178530,
            ["GUID"] = "801EBD94",
            },
        [51178531] = {
            ["Content"] = "全家欢天喜地把这些鱼给煮了，府上也没有盐巴，就白水煮了，但毕竟是少爷新钓的，竟是一点也没有腥气……",
            ["DialogueId"] = 51178531,
            ["GUID"] = "801EBDBE",
            },
        [51178532] = {
            ["Content"] = "后来……后来发生了什么……啊……我想不起来了……发生了什么呢……",
            ["DialogueId"] = 51178532,
            ["GUID"] = "801EBDE8",
            },
        [51178533] = {
            ["Content"] = "（他说的话听起来有些耳熟，你隐约想起了……）",
            ["DialogueId"] = 51178533,
            ["GUID"] = "801EBE12",
            },
        [51178534] = {
            ["Content"] = "（你没有想起什么。）",
            ["DialogueId"] = 51178534,
            ["GUID"] = "801EBE3C",
            },
        [51178535] = {
            ["Content"] = "我听说，华胥有一种鱼有剧毒……需要细心处理……否则……",
            ["DialogueId"] = 51178535,
            ["GUID"] = "801EBE66",
            },
        [51178536] = {
            ["Content"] = "…………！",
            ["DialogueId"] = 51178536,
            ["GUID"] = "801EBE90",
            },
        [51178537] = {
            ["Content"] = "是了，那时候我不知怎的胸闷，迷迷瞪瞪地晕过去了。昏迷前，我看见少爷和孩子们都歪七扭八地躺在周围的地上……",
            ["DialogueId"] = 51178537,
            ["GUID"] = "801EBEBA",
            },
        [51178538] = {
            ["Content"] = "老爷……我没做到，我没做到啊……您让我照顾好的孩子们，我都没做到……",
            ["DialogueId"] = 51178538,
            ["GUID"] = "801EBEE4",
            },
        [51178539] = {
            ["Content"] = "（你面前的无由生突然剧烈地抖动，看起来悲怆万分……无由生也会流泪吗？）",
            ["DialogueId"] = 51178539,
            ["GUID"] = "801EBF0E",
            },
        [51178540] = {
            ["Content"] = "（片刻之后，它似乎平复了情绪。又如同初见时一般在原地徘徊着……）",
            ["DialogueId"] = 51178540,
            ["GUID"] = "801EBF38",
            },
        [51178541] = {
            ["Content"] = "啊……我想起来了，这些往事，我都想起来了！",
            ["DialogueId"] = 51178541,
            ["GUID"] = "801EBF62",
            },
        [51178542] = {
            ["Content"] = "你……就是你，你快过来，趁着我还清醒，这事我要说给你听，不然在月光拐过墙头时，我可能就什么也想不起来了……",
            ["DialogueId"] = 51178542,
            ["GUID"] = "801EBF8C",
            },
        [51178543] = {
            ["Content"] = "这故事你已经说过一遍了。",
            ["DialogueId"] = 51178543,
            ["GUID"] = "801EBFB6",
            },
        [51178544] = {
            ["Content"] = "说过了？我怎么想不起来了？已经说过了吗？我记得……我没……",
            ["DialogueId"] = 51178544,
            ["GUID"] = "801EBFE0",
            },
        [51178545] = {
            ["Content"] = "………………再见。",
            ["DialogueId"] = 51178545,
            ["GUID"] = "801EC00A",
            },
        [51178546] = {
            ["Content"] = "说过了吗？老爷……为何突然想起这个名字？老爷是谁？",
            ["DialogueId"] = 51178546,
            ["GUID"] = "801EC034",
            },
        [51178547] = {
            ["Content"] = "谁？我又是谁……我有愧于你啊……有愧于……谁？",
            ["DialogueId"] = 51178547,
            ["GUID"] = "801EC05E",
            },
        [51178548] = {
            ["Content"] = "我是谁？以前的那些事，我还记得吗？呜呜呜……",
            ["DialogueId"] = 51178548,
            ["GUID"] = "801EC0A0",
            },
        [51178601] = {
            ["Content"] = "飘零四杰啊……",
            ["DialogueId"] = 51178601,
            ["GUID"] = "801EC93A",
            },
        [51178602] = {
            ["Content"] = "飘零四杰啊……那时候的意气风发，如今尽往矣……",
            ["DialogueId"] = 51178602,
            ["GUID"] = "801EC964",
            },
        [51178603] = {
            ["Content"] = "在我们山外山老一辈人的眼里，他们好似还是来时那桀骜不驯的半大青年。未曾想到，十数年过去，如今的皓京城里，他们也成为了街头巷尾的传奇故事。",
            ["DialogueId"] = 51178603,
            ["GUID"] = "801EC98E",
            },
        [51178604] = {
            ["Content"] = "有空的话，再说与你们听。今天先回去做功课吧。",
            ["DialogueId"] = 51178604,
            ["GUID"] = "801EC9B8",
            },
        [51178605] = {
            ["Content"] = "老爷爷好坏，回回都吊着我们，上次说的烛阴闹海的故事也是说到一半就赶我们走，分明是故意的。",
            ["DialogueId"] = 51178605,
            ["GUID"] = "801EC9E2",
            },
        [51178606] = {
            ["Content"] = "噢哟，倒赖上我了，你可记得你们的好老师菡姐因着你们在功课里胡乱写我讲的传奇故事，课上到一半就要来我这儿要说法，我可惹不起！",
            ["DialogueId"] = 51178606,
            ["GUID"] = "801ECA0C",
            },
        [51178607] = {
            ["Content"] = "略略略！我不管，你就是骗我们，除非明天我来的时候你给我吃饴糖，我就原谅你。",
            ["DialogueId"] = 51178607,
            ["GUID"] = "801ECA36",
            },
        [51178608] = {
            ["Content"] = "你这小鬼，是想从我这里骗饴糖吧！",
            ["DialogueId"] = 51178608,
            ["GUID"] = "801ECA60",
            },
        [51178609] = {
            ["Content"] = "不听不听，咱们说好了，明天我就来取饴糖！我先走了！",
            ["DialogueId"] = 51178609,
            ["GUID"] = "801ECA8A",
            },
        [51178610] = {
            ["Content"] = "（顽劣的孩子嬉笑打闹着，张牙舞爪地跑开了。）",
            ["DialogueId"] = 51178610,
            ["GUID"] = "801ECAB4",
            },
        [51178611] = {
            ["Content"] = "这孩子……",
            ["DialogueId"] = 51178611,
            ["GUID"] = "801ECADE",
            },
        [51178612] = {
            ["Content"] = "（老人这才注意到你，面上显出几分诧异。）",
            ["DialogueId"] = 51178612,
            ["GUID"] = "801ECB08",
            },
        [51178613] = {
            ["Content"] = "你是刚来的后生吗？看着有些面生……",
            ["DialogueId"] = 51178613,
            ["GUID"] = "801ECB32",
            },
        [51178614] = {
            ["Content"] = "我是苏乙带来的客人。",
            ["DialogueId"] = 51178614,
            ["GUID"] = "801ECB5C",
            },
        [51178615] = {
            ["Content"] = "你不知道吗，山外山请我来帮忙的。",
            ["DialogueId"] = 51178615,
            ["GUID"] = "801ECB86",
            },
        [51178616] = {
            ["Content"] = "哦？还有这事？我确是不晓得，不过既然他们这么决定，想必你定是有几分过人之处。",
            ["DialogueId"] = 51178616,
            ["GUID"] = "801ECBB0",
            },
        [51178617] = {
            ["Content"] = "我是飘零四杰第五杰——人称狩月人之王的净界岛主{nickname}。",
            ["DialogueId"] = 51178617,
            ["GUID"] = "801ECBDA",
            },
        [51178618] = {
            ["Content"] = "哈哈，小友真会开玩笑，飘零四杰的时代已经过去啦，即使再有新人谱写故事，应该也不会选择如此古早的称号。",
            ["DialogueId"] = 51178618,
            ["GUID"] = "801ECC04",
            },
        [51178619] = {
            ["Content"] = "幸会幸会，不管怎么说，欢迎你来到山外山。",
            ["DialogueId"] = 51178619,
            ["GUID"] = "801ECC2E",
            },
        [51178620] = {
            ["Content"] = "我刚才听到你和那些孩子们说起飘零四杰……",
            ["DialogueId"] = 51178620,
            ["GUID"] = "801ECC58",
            },
        [51178621] = {
            ["Content"] = "是啊，被你听到了。你也是因为好奇他们的事情才在老头子我这里留步的吗？",
            ["DialogueId"] = 51178621,
            ["GUID"] = "801ECC82",
            },
        [51178622] = {
            ["Content"] = "确实有兴趣。",
            ["DialogueId"] = 51178622,
            ["GUID"] = "801ECCAC",
            },
        [51178623] = {
            ["Content"] = "嗯……只是我今天已经讲过一遍啦，想要再听一遍的话，总得拿些什么东西换才是，老头子我啊可不乐意白讲。",
            ["DialogueId"] = 51178623,
            ["GUID"] = "801ECCD6",
            },
        [51178624] = {
            ["Content"] = "我是你们山外山的贵客，了解一些基础情报也不行吗？",
            ["DialogueId"] = 51178624,
            ["GUID"] = "801ECD00",
            },
        [51178625] = {
            ["Content"] = "一物换一物，你告诉我一个故事，我告诉你一个故事。",
            ["DialogueId"] = 51178625,
            ["GUID"] = "801ECD2A",
            },
        [51178626] = {
            ["Content"] = "这听起来只是一些往事，不是什么有价值的情报吧。",
            ["DialogueId"] = 51178626,
            ["GUID"] = "801ECD54",
            },
        [51178627] = {
            ["Content"] = "哈哈哈！开玩笑的！不要惊慌，只是我想看看小友会如何反应，方才出此下策。",
            ["DialogueId"] = 51178627,
            ["GUID"] = "801ECD7E",
            },
        [51178628] = {
            ["Content"] = "既然这样，小友想了解谁的故事呢？先说好，那些大家都耳熟能详的我就不说了，我只说一些我觉得有趣的事。",
            ["DialogueId"] = 51178628,
            ["GUID"] = "801ECDA8",
            },
        [51178629] = {
            ["Content"] = "问问宴山亭。",
            ["DialogueId"] = 51178629,
            ["GUID"] = "801ECDD2",
            },
        [51178630] = {
            ["Content"] = "荡涤千山——宴山亭，名字很潇洒吧？那家伙艺高人胆大，喜欢耍点剑法，还爱显摆，总喜欢收一个又一个徒弟。",
            ["DialogueId"] = 51178630,
            ["GUID"] = "801ECDFC",
            },
        [51178631] = {
            ["Content"] = "你知道他以前是个香官吧？是不是下意识里会觉得，华胥的香官便是成熟稳重的家伙？他嘛，简直是成熟稳重的反义词！",
            ["DialogueId"] = 51178631,
            ["GUID"] = "801ECE26",
            },
        [51178632] = {
            ["Content"] = "他有次聊发少年狂，不知为何用剑挑下了树上的蜂窝，引得那马蜂追着他跑了三里地，鼻青脸肿地回来找我取药。",
            ["DialogueId"] = 51178632,
            ["GUID"] = "801ECE50",
            },
        [51178633] = {
            ["Content"] = "怎么样，是不是和你印象里的宴山亭大相径庭？",
            ["DialogueId"] = 51178633,
            ["GUID"] = "801ECE7A",
            },
        }
  end },
  { MinKey = 51178634, MaxKey = 60120101, Loader = function()
      return {
        [51178634] = {
            ["Content"] = "问问苏暮鹧。",
            ["DialogueId"] = 51178634,
            ["GUID"] = "801ECEA4",
            },
        [51178635] = {
            ["Content"] = "一燕平川——苏暮鹧，苏乙那丫头的姑姑。其实她没什么好说的，或者说，苏乙现在什么样子，当年的苏暮鹧就是什么样子，简直一个模子印出来的。",
            ["DialogueId"] = 51178635,
            ["GUID"] = "801ECECE",
            },
        [51178636] = {
            ["Content"] = "其实我不太了解她，她大多数时间都在研究机傀术，后面也因为一些原因早早离世……但山外山的人们都知晓她与宴山亭的关系，并且以为他们会早早……",
            ["DialogueId"] = 51178636,
            ["GUID"] = "801ECEF8",
            },
        [51178637] = {
            ["Content"] = "算啦……不说这个。苏暮鹧嘛……我记得她特别爱吃酸食，就是皓京城里那些卖蜜饯的小摊，她回回都要去把最酸的那些果干买空。",
            ["DialogueId"] = 51178637,
            ["GUID"] = "801ECF22",
            },
        [51178638] = {
            ["Content"] = "然后就一边对着她那堆叠如山的设计图纸，一边像是没有味觉一样把酸到掉牙的果干往嘴里塞。",
            ["DialogueId"] = 51178638,
            ["GUID"] = "801ECF4C",
            },
        [51178639] = {
            ["Content"] = "据说是这样可以有一些提神醒脑的效果？我非她，焉知她之乐呢？",
            ["DialogueId"] = 51178639,
            ["GUID"] = "801ECF76",
            },
        [51178640] = {
            ["Content"] = "问问行香子。",
            ["DialogueId"] = 51178640,
            ["GUID"] = "801ECFA0",
            },
        [51178641] = {
            ["Content"] = "哎呀那个老混蛋！我可好久没见到他了！那家伙，打铁玩火一把好手！",
            ["DialogueId"] = 51178641,
            ["GUID"] = "801ECFCA",
            },
        [51178642] = {
            ["Content"] = "他是我见过最无聊的人了，之前的山外山，家家户户都用灶火烧饭，有时柴火受潮，火头就不旺。火头不旺，烧出的饭便不香。",
            ["DialogueId"] = 51178642,
            ["GUID"] = "801ECFF4",
            },
        [51178643] = {
            ["Content"] = "他就专门盯着人家火头不旺的锅沿，假装从门口路过，等人家恭恭敬敬请他去帮忙点火，再客客气气请他吃上一顿晚饭。",
            ["DialogueId"] = 51178643,
            ["GUID"] = "801ED01E",
            },
        [51178644] = {
            ["Content"] = "至于为什么他点火就旺其他人不行，这自然是他自己的功夫，但他非要说是自己到处行善积德，一颗赤子之心的缘故。",
            ["DialogueId"] = 51178644,
            ["GUID"] = "801ED048",
            },
        [51178645] = {
            ["Content"] = "喜欢贫嘴，带点自吹自擂，这就是白焰丹曦——行香子。",
            ["DialogueId"] = 51178645,
            ["GUID"] = "801ED072",
            },
        [51178646] = {
            ["Content"] = "问问文氏姐妹。",
            ["DialogueId"] = 51178646,
            ["GUID"] = "801ED09C",
            },
        [51178647] = {
            ["Content"] = "那两个娃娃啊……是可怜丫头，长得一模一样，伫在你面前，不仔细看是完全分不出来的。",
            ["DialogueId"] = 51178647,
            ["GUID"] = "801ED0C6",
            },
        [51178648] = {
            ["Content"] = "其实她俩乖的很，年纪轻但心里藏着事，所以大多数时间都沉默寡言。",
            ["DialogueId"] = 51178648,
            ["GUID"] = "801ED0F0",
            },
        [51178649] = {
            ["Content"] = "她们难得展露出女儿家情态，是在绣东西的时候。",
            ["DialogueId"] = 51178649,
            ["GUID"] = "801ED11A",
            },
        [51178650] = {
            ["Content"] = "我们这的大多数人，手可以搓机傀可以拿利器，但捧起绣花针那就傻了眼，只能干看着发愣。但她俩一来，却是将大多数针线活都包揽了过去。",
            ["DialogueId"] = 51178650,
            ["GUID"] = "801ED144",
            },
        [51178651] = {
            ["Content"] = "有段时间，山外山人人都用上了绣着小花的手绢，纳着鸳鸯的鞋垫，我们就这样接受着她们俩默默的善意，用力所能及的东西回馈她们。",
            ["DialogueId"] = 51178651,
            ["GUID"] = "801ED16E",
            },
        [51178652] = {
            ["Content"] = "只是可惜……只是可惜啊……",
            ["DialogueId"] = 51178652,
            ["GUID"] = "801ED198",
            },
        [51178653] = {
            ["Content"] = "你看我，年龄大了，说起过去的事情就有些收不住，耽误你的时间了吧？",
            ["DialogueId"] = 51178653,
            ["GUID"] = "801ED1C2",
            },
        [51178654] = {
            ["Content"] = "倒也没有。",
            ["DialogueId"] = 51178654,
            ["GUID"] = "801ED1EC",
            },
        [51178655] = {
            ["Content"] = "没有？没有我也说不下去啦，我一想到曾经的光景，那几个孩子在我面前嬉闹，练剑的练剑，造机傀的造机傀，我心里就……",
            ["DialogueId"] = 51178655,
            ["GUID"] = "801ED216",
            },
        [51178656] = {
            ["Content"] = "罢啦！今日就到这里吧，老头子身体弱，要回去休息了，我们有缘再聊吧！",
            ["DialogueId"] = 51178656,
            ["GUID"] = "801ED240",
            },
        [51179001] = {
            ["Content"] = "好想让我的绵绵草开心起来……",
            ["DialogueId"] = 51179001,
            ["GUID"] = "801F0ADA",
            },
        [51179002] = {
            ["Content"] = "它看起来总是很孤单，所以整日垂着脑袋，怎么才能让它开心起来呢？",
            ["DialogueId"] = 51179002,
            ["GUID"] = "801F0B04",
            },
        [51179003] = {
            ["Content"] = "我是说我的魔灵啦，你看，它垂头丧气的，之前带它去野外寻找同类，它们却总会在我们走近的时候躲起来。",
            ["DialogueId"] = 51179003,
            ["GUID"] = "801F0B2E",
            },
        [51179004] = {
            ["Content"] = "所以，为了满足它的小小愿望，你可以展示一下你的<W>绵绵草</>魔灵吗？如果可以的话，能在它面前<W>释放绵绵草的能力</>吗？",
            ["DialogueId"] = 51179004,
            ["GUID"] = "801F0B58",
            },
        [51179005] = {
            ["Content"] = "你居然真的有绵绵草魔灵，多亏有你，我的绵绵草现在看起来开心多了！你看，都显得蓬松了一些呢！",
            ["DialogueId"] = 51179005,
            ["GUID"] = "801F0B82",
            },
        [51179006] = {
            ["Content"] = "谢谢你让它开心起来，为了表达我的谢意，喏，这是我的一点心意，你就收下吧~",
            ["DialogueId"] = 51179006,
            ["GUID"] = "801F0BAC",
            },
        [51179101] = {
            ["Content"] = "烧起来！烧起来啊！",
            ["DialogueId"] = 51179101,
            ["GUID"] = "801F1B42",
            },
        [51179102] = {
            ["Content"] = "呼！呼！快点燃呀，今天怎么像是被浇了一盆水一样，一点火星子都看不着？",
            ["DialogueId"] = 51179102,
            ["GUID"] = "801F1B6C",
            },
        [51179103] = {
            ["Content"] = "那位路过的白衣少侠，你有没有会点火的东西，比如<W>打火鸡</>之类的，我这支香怎么都点不着！",
            ["DialogueId"] = 51179103,
            ["GUID"] = "801F1B96",
            },
        [51179104] = {
            ["Content"] = "诶呀！厉害！我之前只听说拽着魔灵的屁股给东西点火的道理，居然没想到还有这种更厉害的用法！",
            ["DialogueId"] = 51179104,
            ["GUID"] = "801F1BC0",
            },
        [51179105] = {
            ["Content"] = "果然，天下英雄出少年啊，谢谢你啦！",
            ["DialogueId"] = 51179105,
            ["GUID"] = "801F1BEA",
            },
        [51179201] = {
            ["Content"] = "要是能亲眼见到那只小兔子……",
            ["DialogueId"] = 51179201,
            ["GUID"] = "801F2BAA",
            },
        [51179202] = {
            ["Content"] = "听闻魔灵里有一种长相可爱，酷似珍珠一样的小小兔子，浑身毛茸茸的，深受各种魔灵爱好者的喜爱。",
            ["DialogueId"] = 51179202,
            ["GUID"] = "801F2BD4",
            },
        [51179203] = {
            ["Content"] = "我本来也想抓一只，可寻觅许久，终不见其踪。唉，我老啦，不知道这辈子还有没有机会一睹<W>珍珠兔</>的真容了……",
            ["DialogueId"] = 51179203,
            ["GUID"] = "801F2BFE",
            },
        [51179204] = {
            ["Content"] = "这……这就是……传说中的珍珠兔？！我……我能摸一下吗？",
            ["DialogueId"] = 51179204,
            ["GUID"] = "801F2C28",
            },
        [51179205] = {
            ["Content"] = "这柔软的触感，这可爱的身姿，啊！我圆梦了！谢谢你为我的生命带来了一束光！",
            ["DialogueId"] = 51179205,
            ["GUID"] = "801F2C52",
            },
        [51179301] = {
            ["Content"] = "寻宝神器，莫过于你好箱~",
            ["DialogueId"] = 51179301,
            ["GUID"] = "801F3C12",
            },
        [51179302] = {
            ["Content"] = "小友可曾听闻有一种稀有的魔灵？有它陪伴在身侧时，你好箱会为你指引出各种埋藏在山川角落里的宝藏。",
            ["DialogueId"] = 51179302,
            ["GUID"] = "801F3C3C",
            },
        [51179303] = {
            ["Content"] = "据说它的名字十分奇怪，叫……<W>你好箱</>？若是有幸拥有一只这样的魔灵，岂不是这辈子都要吃喝不愁了？",
            ["DialogueId"] = 51179303,
            ["GUID"] = "801F3C66",
            },
        [51179304] = {
            ["Content"] = "哦？你不是一般人吧，居然拥有如此稀有的魔灵，想必定是人中龙凤！",
            ["DialogueId"] = 51179304,
            ["GUID"] = "801F3C90",
            },
        [51179305] = {
            ["Content"] = "我正好在附近藏了一些东西，你不嫌弃的话，就用这只魔灵的能力去找找看吧！",
            ["DialogueId"] = 51179305,
            ["GUID"] = "801F3CBA",
            },
        [51179401] = {
            ["Content"] = "那是我见过最狡猾的魔灵……",
            ["DialogueId"] = 51179401,
            ["GUID"] = "801F4C7A",
            },
        [51179402] = {
            ["Content"] = "那就是全世界最可怕的魔灵，狡猾，险恶，居心叵测……",
            ["DialogueId"] = 51179402,
            ["GUID"] = "801F4CA4",
            },
        [51179403] = {
            ["Content"] = "是的，它有着两对<W>像羊一样的大角</>，脖子上<W>挂着会叮当作响的铃铛</>，背上还<W>有扑闪扑闪的小翅膀</>！",
            ["DialogueId"] = 51179403,
            ["GUID"] = "801F4CCE",
            },
        [51179404] = {
            ["Content"] = "呜啊！你怎么会拥有如此邪恶的魔灵，快把它拿开，离我远些！",
            ["DialogueId"] = 51179404,
            ["GUID"] = "801F4CF8",
            },
        [51179405] = {
            ["Content"] = "求求你了，这些……这些都给你好了吧！你快带它走开吧！",
            ["DialogueId"] = 51179405,
            ["GUID"] = "801F4D22",
            },
        [51179501] = {
            ["Content"] = "魔灵并非永生不灭，但有一只除外……",
            ["DialogueId"] = 51179501,
            ["GUID"] = "801F5CE2",
            },
        [51179502] = {
            ["Content"] = "你好啊，你看起来是一位经验丰富的年少侠客，不知道你有没有接触过魔灵这种神奇的小家伙。",
            ["DialogueId"] = 51179502,
            ["GUID"] = "801F5D0C",
            },
        [51179503] = {
            ["Content"] = "每一只魔灵都有自己的寿命，就像我们抟土氏一样，到了一定的年龄就会死亡，不过有一只魔灵却十分特殊。",
            ["DialogueId"] = 51179503,
            ["GUID"] = "801F5D36",
            },
        [51179504] = {
            ["Content"] = "它一生中<W>有99%的时间都在睡觉</>，这也使得它<W>十分长寿</>，你知道这只魔灵是什么吗？",
            ["DialogueId"] = 51179504,
            ["GUID"] = "801F5D60",
            },
        [51179505] = {
            ["Content"] = "你好箱。",
            ["DialogueId"] = 51179505,
            ["GUID"] = "801F5D8A",
            },
        [51179506] = {
            ["Content"] = "珍珠兔。",
            ["DialogueId"] = 51179506,
            ["GUID"] = "801F5DB4",
            },
        [51179507] = {
            ["Content"] = "不对哦，好好想想再回答吧~",
            ["DialogueId"] = 51179507,
            ["GUID"] = "801F5DDE",
            },
        [51179508] = {
            ["Content"] = "好梦先生。",
            ["DialogueId"] = 51179508,
            ["GUID"] = "801F5E08",
            },
        [51179509] = {
            ["Content"] = "您可真是一位知识渊博的侠客，既然这样，我就把这些东西送给你吧！",
            ["DialogueId"] = 51179509,
            ["GUID"] = "801F5E32",
            },
        [51179601] = {
            ["Content"] = "其实能完整说出四杰姓名的人已经很少了……",
            ["DialogueId"] = 51179601,
            ["GUID"] = "801F6D4A",
            },
        [51179602] = {
            ["Content"] = "毕竟他们的故事太过久远，很多人只能记住那些外界给他们的称号，记不住他们的本名。",
            ["DialogueId"] = 51179602,
            ["GUID"] = "801F6D74",
            },
        [51179603] = {
            ["Content"] = "或许再过些日子，等我们老死了，孩子们也不再知晓飘零四杰的故事，这些名字就会被淹没在历史的长河里了吧……",
            ["DialogueId"] = 51179603,
            ["GUID"] = "801F6D9E",
            },
        [51179604] = {
            ["Content"] = "你一直盯着我看，是想说你知道？那你说说看，<W>飘零四杰的真名</>都叫什么？",
            ["DialogueId"] = 51179604,
            ["GUID"] = "801F6DC8",
            },
        [51179605] = {
            ["Content"] = "雪琴，关中，耐安，城恩。",
            ["DialogueId"] = 51179605,
            ["GUID"] = "801F6DF2",
            },
        [51179606] = {
            ["Content"] = "沉鱼，落雁，闭月，羞花。",
            ["DialogueId"] = 51179606,
            ["GUID"] = "801F6E1C",
            },
        [51179607] = {
            ["Content"] = "磐安，宋语，长弓，魏杰。",
            ["DialogueId"] = 51179607,
            ["GUID"] = "801F6E46",
            },
        [51179608] = {
            ["Content"] = "诶呀，这都是谁和谁呀，小娃儿，你就别拿我这老头子取乐啦！",
            ["DialogueId"] = 51179608,
            ["GUID"] = "801F6E70",
            },
        [51179609] = {
            ["Content"] = "宴山亭，行香子，苏幕鹧，文氏姐妹。",
            ["DialogueId"] = 51179609,
            ["GUID"] = "801F6E9A",
            },
        [51179610] = {
            ["Content"] = "不错不错，看来年轻人里还是有人记得啊！",
            ["DialogueId"] = 51179610,
            ["GUID"] = "801F6EC4",
            },
        [51179701] = {
            ["Content"] = "织星客里的头头儿？",
            ["DialogueId"] = 51179701,
            ["GUID"] = "801F7DB2",
            },
        [51179702] = {
            ["Content"] = "你要问的是织星客里最权威的人，我不知道，但我知道织星客们最听谁的话。",
            ["DialogueId"] = 51179702,
            ["GUID"] = "801F7DDC",
            },
        [51179703] = {
            ["Content"] = "那位啊，可是在百年春呼风唤雨的大人物，还是鼎鼎有名的<W>龙渊上卿</>呢~想不想知道是谁？给我一个铜币我就告诉你。",
            ["DialogueId"] = 51179703,
            ["GUID"] = "801F7E06",
            },
        [51179704] = {
            ["Content"] = "我本人。",
            ["DialogueId"] = 51179704,
            ["GUID"] = "801F7E30",
            },
        [51179705] = {
            ["Content"] = "诶呀！你这家伙竟会胡说八道，你甚至都不是华胥之人，怎么会是龙渊上卿呢？",
            ["DialogueId"] = 51179705,
            ["GUID"] = "801F7E5A",
            },
        [51179706] = {
            ["Content"] = "扶疏。",
            ["DialogueId"] = 51179706,
            ["GUID"] = "801F7E84",
            },
        [51179707] = {
            ["Content"] = "这个名字听起来有点耳生，我只听说过扶风似乎是城内泽生阁的创始人，至于扶疏……她们有什么关系吗？",
            ["DialogueId"] = 51179707,
            ["GUID"] = "801F7EAE",
            },
        [51179708] = {
            ["Content"] = "止流。",
            ["DialogueId"] = 51179708,
            ["GUID"] = "801F7ED8",
            },
        [51179709] = {
            ["Content"] = "答对啦！止流大掌柜可是咱们华胥的风云人物，在这华胥谁人不知谁人不晓呢？",
            ["DialogueId"] = 51179709,
            ["GUID"] = "801F7F02",
            },
        [51179801] = {
            ["Content"] = "这批香料有些受潮……",
            ["DialogueId"] = 51179801,
            ["GUID"] = "801F8E1A",
            },
        [51179802] = {
            ["Content"] = "受潮的香料怕是没法用了，偏偏这批香方对于香料的要求极为苛刻……哎呀，这该死的阴雨天，香料真是遭了罪了。",
            ["DialogueId"] = 51179802,
            ["GUID"] = "801F8E44",
            },
        [51179803] = {
            ["Content"] = "咦？外乡客，看你一脸迷糊的样子，我来考考你，香方的意思是制香的配方，香料的意思是制香的材料，那么<W>制香的成品</>叫做什么呢？",
            ["DialogueId"] = 51179803,
            ["GUID"] = "801F8E6E",
            },
        [51179804] = {
            ["Content"] = "沉月香。",
            ["DialogueId"] = 51179804,
            ["GUID"] = "801F8E98",
            },
        [51179805] = {
            ["Content"] = "不对不对，每种制好的香有自己的名字，但它们的统称可不一样。",
            ["DialogueId"] = 51179805,
            ["GUID"] = "801F8EC2",
            },
        [51179806] = {
            ["Content"] = "香。",
            ["DialogueId"] = 51179806,
            ["GUID"] = "801F8EEC",
            },
        [51179807] = {
            ["Content"] = "不对不对，香料与制好的香都被统称为香哦。",
            ["DialogueId"] = 51179807,
            ["GUID"] = "801F8F16",
            },
        [51179808] = {
            ["Content"] = "香品。",
            ["DialogueId"] = 51179808,
            ["GUID"] = "801F8F40",
            },
        [51179809] = {
            ["Content"] = "对啦！你可真聪明，来这里的外乡客里，你算是最快答出来的，其他人都被这些拗口的名称绕得迷迷糊糊呢。",
            ["DialogueId"] = 51179809,
            ["GUID"] = "801F8F6A",
            },
        [51179901] = {
            ["Content"] = "我会去哪里呢？",
            ["DialogueId"] = 51179901,
            ["GUID"] = "801F9E82",
            },
        [51179902] = {
            ["Content"] = "它们跟我说，我不会一直待在这里的，我以后会去一个神秘的地方，那里有好多死去的无由生。",
            ["DialogueId"] = 51179902,
            ["GUID"] = "801F9EAC",
            },
        [51179903] = {
            ["Content"] = "但我好害怕啊，你知道<W>我会去哪里</>吗？如果我不知道地点就被带过去的话，会很难过的……",
            ["DialogueId"] = 51179903,
            ["GUID"] = "801F9ED6",
            },
        [51179904] = {
            ["Content"] = "我家。",
            ["DialogueId"] = 51179904,
            ["GUID"] = "801F9F00",
            },
        [51179905] = {
            ["Content"] = "真的吗？虽然我很愿意去你家，但是它们好像不是这么说的……",
            ["DialogueId"] = 51179905,
            ["GUID"] = "801F9F2A",
            },
        [51179906] = {
            ["Content"] = "执律阁。",
            ["DialogueId"] = 51179906,
            ["GUID"] = "801F9F54",
            },
        [51179907] = {
            ["Content"] = "真好啊，我要去陪伴龙君吗？虽然我很愿意，但是它们好像不是这么说的……",
            ["DialogueId"] = 51179907,
            ["GUID"] = "801F9F7E",
            },
        [51179908] = {
            ["Content"] = "虞泉。",
            ["DialogueId"] = 51179908,
            ["GUID"] = "801F9FA8",
            },
        [51179909] = {
            ["Content"] = "啊……是啊，我要去虞泉，真美的名字，那里一定也是个很美好的地方吧，谢谢你，现在我不害怕了。",
            ["DialogueId"] = 51179909,
            ["GUID"] = "801F9FD2",
            },
        [51180001] = {
            ["Content"] = "肚子好饿……",
            ["DialogueId"] = 51180001,
            ["GUID"] = "801FAEEA",
            },
        [51180002] = {
            ["Content"] = "我说啊，你有没有听说过华胥有一个故事，说是一群织星客行商在外之时，前不着村后不着店，随身的口粮也吃完了。直饿得他们眼冒金星，没有力气赶路。",
            ["DialogueId"] = 51180002,
            ["GUID"] = "801FAF14",
            },
        [51180003] = {
            ["Content"] = "有一名织星客就跟所有人说：前面有甜果林！旁人一听这话，立刻就精神起来，互相叫着哪呢哪呢往前继续行进。",
            ["DialogueId"] = 51180003,
            ["GUID"] = "801FAF3E",
            },
        [51180004] = {
            ["Content"] = "后来他们即使到达了目的地，也没有找到那名织星客所说的甜果林，我们华胥把这个故事叫做望林止渴。",
            ["DialogueId"] = 51180004,
            ["GUID"] = "801FAF68",
            },
        [51180005] = {
            ["Content"] = "现在我的肚子好饿啊，你能不能也给我<W>编造一个“甜果林”</>，让我陷入一些美好的幻想里呢？",
            ["DialogueId"] = 51180005,
            ["GUID"] = "801FAF92",
            },
        [51180006] = {
            ["Content"] = "哇……好像真的烤肉啊，我好像已经闻到了肉的香气了。谢谢你！",
            ["DialogueId"] = 51180006,
            ["GUID"] = "801FAFBC",
            },
        [51180101] = {
            ["Content"] = "不够隐蔽……怎么想都不够隐蔽！",
            ["DialogueId"] = 51180101,
            ["GUID"] = "801FBF52",
            },
        [51180102] = {
            ["Content"] = "要论藏身之法，本来最该去请教微茫市的那些老油条，可现在我身在皓京，无暇回烟津渡……",
            ["DialogueId"] = 51180102,
            ["GUID"] = "801FBF7C",
            },
        [51180103] = {
            ["Content"] = "到底有什么办法，才能让那些频繁过来巡逻的应天尉<W>看不着我</>呢？",
            ["DialogueId"] = 51180103,
            ["GUID"] = "801FBFA6",
            },
        [51180104] = {
            ["Content"] = "哦哦！好厉害的隐蔽之术！如此这般定能让巡逻的人觉察不到！",
            ["DialogueId"] = 51180104,
            ["GUID"] = "801FBFD0",
            },
        [51180105] = {
            ["Content"] = "受教了！我这就开始仔细研究你的动作，力求模仿到惟妙惟肖！",
            ["DialogueId"] = 51180105,
            ["GUID"] = "801FBFFA",
            },
        [51180201] = {
            ["Content"] = "好想去华胥之外的地方看看巫师啊。",
            ["DialogueId"] = 51180201,
            ["GUID"] = "801FCFBA",
            },
        [51180202] = {
            ["Content"] = "听说在海伯利亚帝国，会魔法的有龙氏可以身披黑色的斗篷，坐着大大的扫帚在夜空中穿行。",
            ["DialogueId"] = 51180202,
            ["GUID"] = "801FCFE4",
            },
        [51180203] = {
            ["Content"] = "我好羡慕啊，可惜华胥只有拿着武器的应天尉，没有<W>骑着扫帚</>的巫师。",
            ["DialogueId"] = 51180203,
            ["GUID"] = "801FD00E",
            },
        [51180204] = {
            ["Content"] = "哇！对！就是像这样！坐在扫帚上飞行！你好厉害啊，你也是外国来的有龙氏吗？",
            ["DialogueId"] = 51180204,
            ["GUID"] = "801FD038",
            },
        [51180205] = {
            ["Content"] = "你可不可以教教我怎么让扫帚飞起来？我有了会飞的扫帚，就不用爬墙出去找同学玩了！",
            ["DialogueId"] = 51180205,
            ["GUID"] = "801FD062",
            },
        [51180301] = {
            ["Content"] = "呵欠……好困啊……",
            ["DialogueId"] = 51180301,
            ["GUID"] = "801FE022",
            },
        [51180302] = {
            ["Content"] = "要不是要帮人排队代购桂花糕，我才不会起这么早就来排队，好困啊……",
            ["DialogueId"] = 51180302,
            ["GUID"] = "801FE04C",
            },
        [51180303] = {
            ["Content"] = "要是能有<W>一张床</>摆在街上让我躺躺就好了……反正现在桂花糕摊也没有开门……",
            ["DialogueId"] = 51180303,
            ["GUID"] = "801FE076",
            },
        [51180304] = {
            ["Content"] = "喝呀！你你你你！你从哪里摸出来这么大一张床？！看着还不是华胥的样式……",
            ["DialogueId"] = 51180304,
            ["GUID"] = "801FE0A0",
            },
        [51180305] = {
            ["Content"] = "诶呀不管了，能不能借我躺躺，看着好柔软啊，一定能让我睡个好觉吧！",
            ["DialogueId"] = 51180305,
            ["GUID"] = "801FE0CA",
            },
        [51180401] = {
            ["Content"] = "吾乃五子棋高手，谁人能战？",
            ["DialogueId"] = 51180401,
            ["GUID"] = "801FF08A",
            },
        [51180402] = {
            ["Content"] = "呔！来者何人？可敢与我一战？吾等乃华胥第一五子棋高手，最擅一手技能五子棋，其中飞沙走石一招，更是打遍天下无敌手！",
            ["DialogueId"] = 51180402,
            ["GUID"] = "801FF0B4",
            },
        [51180403] = {
            ["Content"] = "如何，听闻吾的威名，你可敢与我于<W>技能五子棋</>上一战？",
            ["DialogueId"] = 51180403,
            ["GUID"] = "801FF0DE",
            },
        [51180404] = {
            ["Content"] = "咦？！竟有人能将技能五子棋一脉发展到如此炉火纯青……真是青出于蓝而胜于蓝，一代更比一代强啊！",
            ["DialogueId"] = 51180404,
            ["GUID"] = "801FF108",
            },
        [51180405] = {
            ["Content"] = "好啊！我承认你有几分本事！今日便将技能五子棋的衣钵传授于你，你我他日顶峰再见！",
            ["DialogueId"] = 51180405,
            ["GUID"] = "801FF132",
            },
        [60010101] = {
            ["Content"] = "诶？周围这么多毒雾，血清根本不够用呀！去附近回收一些再安安全全地离开这里吧~",
            ["ContentFR"] = "Quoi ?! Ils utilisent du brouillard toxique... Quelle lâcheté ! Vite, utilise le Sérum !",
            ["DialogueId"] = 60010101,
            ["Duration"] = 4.5,
            ["GUID"] = "963A9F32",
            ["NextDialogue"] = 60010102,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/600101/963A9F32",
            ["bTurnOffVoice"] = true,
            },
        [60010102] = {
            ["Content"] = "唔嗯……敌人也不受影响，看来他们也有血清的样子呢。",
            ["ContentFR"] = "Hmm... Ils ne semblent pas affectés non plus. Ils doivent eux aussi avoir du Sérum.",
            ["DialogueId"] = 60010102,
            ["Duration"] = 3,
            ["GUID"] = "963A9F5C",
            ["NextDialogue"] = 60010103,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/600101/963A9F5C",
            ["bTurnOffVoice"] = true,
            },
        [60010103] = {
            ["Content"] = "我发现这附近有存放血清的地方，我们快赶过去吧！",
            ["ContentFR"] = "J’ai repéré un Réservoir de Sérum tout près. Allons-y sans tarder !",
            ["DialogueId"] = 60010103,
            ["Duration"] = 4.5,
            ["GUID"] = "963A9F86",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/600101/963A9F86",
            ["bTurnOffVoice"] = true,
            },
        [60010201] = {
            ["Content"] = "新的血清做好喽，有了它我们就可以逃出去了。",
            ["ContentFR"] = "Parfait, on peut s’échapper par ici ! Vite, en route !",
            ["DialogueId"] = 60010201,
            ["Duration"] = 3.5,
            ["GUID"] = "963AAF9A",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/600102/963AAF9A",
            ["bTurnOffVoice"] = true,
            },
        [60010301] = {
            ["Content"] = "找到他们放血清的地方了！我很厉害吧~",
            ["ContentFR"] = "J’ai trouvé un Réservoir de Sérum ! Pas mal, hein ?",
            ["DialogueId"] = 60010301,
            ["Duration"] = 2,
            ["GUID"] = "963AC002",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/600103/963AC002",
            ["bTurnOffVoice"] = true,
            },
        [60010401] = {
            ["Content"] = "又找到了一个他们放血清的地方，我已经标记出来啦！",
            ["ContentFR"] = "Un autre Réservoir de Sérum repéré, je l’ai déjà marqué pour toi !",
            ["DialogueId"] = 60010401,
            ["Duration"] = 3,
            ["GUID"] = "963AD06A",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/600104/963AD06A",
            ["bTurnOffVoice"] = true,
            },
        [60010501] = {
            ["Content"] = "探险开始喽！让我们四处看看，揭开这里的秘密吧~",
            ["ContentFR"] = "L’aventure commence ! Explorons les lieux et découvrons les secrets qu’ils renferment.",
            ["DialogueId"] = 60010501,
            ["Duration"] = 4.5,
            ["GUID"] = "963AE0D2",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/600105/963AE0D2",
            ["bTurnOffVoice"] = true,
            },
        [60010601] = {
            ["Content"] = "危险危险，我们剩的血清不多了，快去找找血清吧。",
            ["ContentFR"] = "Danger ! Nos réserves de Sérum s’épuisent... Il faut en trouver d’autres au plus vite !",
            ["DialogueId"] = 60010601,
            ["Duration"] = 4.5,
            ["GUID"] = "963AF13A",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/600106/963AF13A",
            ["bTurnOffVoice"] = true,
            },
        [60010701] = {
            ["Content"] = "回收完成，马上就能做好新的血清了！我看看附近哪里还有血清……",
            ["ContentFR"] = "Ouf... On a enfin récupéré un peu de Sérum. Ça devrait nous faire gagner un peu de temps. Voyons voir... où pourrait-il y avoir un autre Réservoir de Sérum...",
            ["DialogueId"] = 60010701,
            ["Duration"] = 4.5,
            ["GUID"] = "963B01A2",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/600107/963B01A2",
            ["bTurnOffVoice"] = true,
            },
        [60020101] = {
            ["Content"] = "咱要研究的东西听说就在这，具体是在哪呢……",
            ["ContentFR"] = "L’objet de nos recherches est censé être ici... mais où exactement, hmm ?",
            ["DialogueId"] = 60020101,
            ["Duration"] = 4,
            ["GUID"] = "964107D2",
            ["SpeakNpcId"] = 900005,
            ["VoiceName"] = "voice/$Locale$/story/0/600201/964107D2",
            ["bTurnOffVoice"] = true,
            },
        [60020201] = {
            ["Content"] = "呜哇，突然冲出来好多敌人！我的研究不能被打断，他们就交给你啦！",
            ["ContentFR"] = "Ouaaah ! Une nuée d’ennemis fonce sur nous ! Je ne peux pas interrompre mes recherches, je te laisse t’en occuper !",
            ["DialogueId"] = 60020201,
            ["Duration"] = 4,
            ["GUID"] = "9641183A",
            ["SpeakNpcId"] = 900005,
            ["VoiceName"] = "voice/$Locale$/story/0/600202/9641183A",
            ["bTurnOffVoice"] = true,
            },
        [60020301] = {
            ["Content"] = "敌人的进攻暂时停止了……",
            ["ContentFR"] = "Ouf... Les ennemis ont battu en retraite... pour l’instant.",
            ["DialogueId"] = 60020301,
            ["Duration"] = 4,
            ["GUID"] = "964128A2",
            ["SpeakNpcId"] = 900005,
            ["VoiceName"] = "voice/$Locale$/story/0/600203/964128A2",
            ["bTurnOffVoice"] = true,
            },
        [60020401] = {
            ["Content"] = "研究好累哦，这是给你的谢礼！现在是陪我继续研究还是回去休息呢？",
            ["ContentFR"] = "Cette recherche m’épuise... Tiens, voilà ta récompense ! Alors, on continue ou on rentre nous reposer ?",
            ["DialogueId"] = 60020401,
            ["Duration"] = 4,
            ["GUID"] = "9641390A",
            ["SpeakNpcId"] = 900005,
            ["VoiceName"] = "voice/$Locale$/story/0/600204/9641390A",
            ["bTurnOffVoice"] = true,
            },
        [60020501] = {
            ["Content"] = "真是的，不就是研究一下嘛，干嘛打得这么狠，为了咱的研究大计，快点解决掉敌人吧。",
            ["ContentFR"] = "Sérieusement... ce n’est qu’une étude ! Pourquoi une telle violence ? Pour le bien de notre découverte, élimine-les vite !",
            ["DialogueId"] = 60020501,
            ["Duration"] = 4,
            ["GUID"] = "96414972",
            ["SpeakNpcId"] = 900005,
            ["VoiceName"] = "voice/$Locale$/story/0/600205/96414972",
            ["bTurnOffVoice"] = true,
            },
        [60020601] = {
            ["Content"] = "不行不行，再这样下去绮晶和我都要被敌人打成筛子啦，这还怎么研究，最最最厉害的狩月人，快想想办法。",
            ["ContentFR"] = "Non, non, non ! Si ça continue, l’Éclat stellaire et moi allons finir en miettes ! {性别:Chasseur de Phoxène|Chasseuse de Phoxène} légendaire, fais quelque chose !",
            ["DialogueId"] = 60020601,
            ["Duration"] = 4,
            ["GUID"] = "964159DA",
            ["SpeakNpcId"] = 900005,
            ["VoiceName"] = "voice/$Locale$/story/0/600206/964159DA",
            ["bTurnOffVoice"] = true,
            },
        [60020701] = {
            ["Content"] = "嗯……没什么思路呢，是我研究方向不对吗？你再坚持一会哈，我先想想，就快了就快了。",
            ["ContentFR"] = "Hmm... Aucune piste. Est-ce que je fais fausse route ? Tiens bon encore un peu, j’ai presque trouvé la solution !",
            ["DialogueId"] = 60020701,
            ["Duration"] = 4,
            ["GUID"] = "96416A42",
            ["SpeakNpcId"] = 900005,
            ["VoiceName"] = "voice/$Locale$/story/0/600207/96416A42",
            ["bTurnOffVoice"] = true,
            },
        [60020801] = {
            ["Content"] = "研究好累哦，这是给你的谢礼！",
            ["ContentFR"] = "Ouf... C’est enfin terminé ! Tiens, un petit cadeau pour te remercier de ton aide.",
            ["DialogueId"] = 60020801,
            ["Duration"] = 4,
            ["GUID"] = "96417AAA",
            ["SpeakNpcId"] = 900005,
            ["VoiceName"] = "voice/$Locale$/story/0/600208/96417AAA",
            ["bTurnOffVoice"] = true,
            },
        [60020901] = {
            ["Content"] = "不行不行，再这样下去设备和我都要被敌人打成筛子啦，这还怎么研究，最最最厉害的狩月人，快想想办法。",
            ["ContentFR"] = "Non, non, non ! Si ça continue, l’Éclat stellaire et moi allons finir en miettes ! {性别:Chasseur de Phoxène|Chasseuse de Phoxène} légendaire, fais quelque chose !",
            ["DialogueId"] = 60020901,
            ["Duration"] = 4,
            ["GUID"] = "96417AAB",
            ["SpeakNpcId"] = 900005,
            ["VoiceName"] = "voice/$Locale$/story/0/600208/96417AAB",
            ["bTurnOffVoice"] = true,
            },
        [60030101] = {
            ["Content"] = "这里居然也有毒雾！光靠我们带的血清撑不了太久诶。",
            ["ContentFR"] = "Brrr ! Beurk, il y a du brouillard toxique partout... Même la puissante Snow ne tiendra pas éternellement avec si peu de Sérum !",
            ["DialogueId"] = 60030101,
            ["Duration"] = 4,
            ["GUID"] = "96477072",
            ["NextDialogue"] = 60030102,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/600301/96477072",
            ["bTurnOffVoice"] = true,
            },
        [60030102] = {
            ["Content"] = "附近应该有制作血清的药剂台，去找找看吧。",
            ["ContentFR"] = "Hmpf ! Il doit bien y avoir un Poste d’Alchimie dans le coin ! Allons voir ça de plus près !",
            ["DialogueId"] = 60030102,
            ["Duration"] = 4,
            ["GUID"] = "96477073",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/600301/96477073",
            ["bTurnOffVoice"] = true,
            },
        [60030201] = {
            ["Content"] = "趁血清还有剩，快快去找药剂台吧。",
            ["ContentFR"] = "Pas une seconde à perdre ! Tant qu’il nous reste du Sérum, fonçons vers ce Poste d’Alchimie !",
            ["DialogueId"] = 60030201,
            ["Duration"] = 4,
            ["GUID"] = "964780DA",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/600302/964780DA",
            ["bTurnOffVoice"] = true,
            },
        [60030301] = {
            ["Content"] = "敌人来啦！我看药剂台的使用手册上说，我们要在药剂台周围打倒敌人，才能让它回收敌人携带的血清。",
            ["ContentFR"] = "Les ennemis arrivent ! D’après le manuel du Poste d’Alchimie, il faut les vaincre autour du poste pour qu’il puisse récupérer leur Sérum !",
            ["DialogueId"] = 60030301,
            ["Duration"] = 4,
            ["GUID"] = "96478104",
            ["NextDialogue"] = 60030302,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/600303/96478104",
            ["bTurnOffVoice"] = true,
            },
        [60030302] = {
            ["Content"] = "啊，血清回收完记得去取哦！要是血清耗尽的话，我们就只能终止委托了！",
            ["ContentFR"] = "Ah ! N’oublie pas d’aller récupérer le Sérum une fois qu’il est prêt ! Si on n’a plus rien, notre mission sera fichue !",
            ["DialogueId"] = 60030302,
            ["Duration"] = 3,
            ["GUID"] = "96479142",
            ["NextDialogue"] = 60030303,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/600303/96479142",
            ["bTurnOffVoice"] = true,
            },
        [60030303] = {
            ["Content"] = "上面还说了一堆难懂的话，但大概意思应该是说，在药剂台周围战斗，还能让我们变得很厉害很厉害，白真聪明！",
            ["ContentFR"] = "Le manuel raconte encore plein de trucs compliqués... Mais en gros, si on se bat près du Poste d’Alchimie, on devient super puissants ! Hé hé, Snow est trop maligne !",
            ["DialogueId"] = 60030303,
            ["Duration"] = 4,
            ["GUID"] = "96479143",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/600303/96479143",
            ["bTurnOffVoice"] = true,
            },
        [60030401] = {
            ["Content"] = "嘘……我听到一些奇怪的动静，好像有大家伙要来了！",
            ["ContentFR"] = "Chut... J’entends des bruits bizarres... On dirait qu’un gros monstre arrive par ici !",
            ["DialogueId"] = 60030401,
            ["Duration"] = 4,
            ["GUID"] = "9647A1AA",
            ["NextDialogue"] = 60030402,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/600304/9647A1AA",
            ["bTurnOffVoice"] = true,
            },
        [60030402] = {
            ["Content"] = "快看看血清还够不够用吧。",
            ["ContentFR"] = "Vite, vérifie si on a encore assez de Sérum pour tenir !",
            ["DialogueId"] = 60030402,
            ["Duration"] = 3,
            ["GUID"] = "9647A2AB",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/600304/9647A1AB",
            ["bTurnOffVoice"] = true,
            },
        [60030501] = {
            ["Content"] = "我们可以走啦，但再探一会险的话，应该能获得更多报酬吧！要继续吗？",
            ["ContentFR"] = "On peut partir maintenant... Mais si on explore un peu plus, on aura sûrement plus de récompenses ! Alors, on continue ?",
            ["DialogueId"] = 60030501,
            ["Duration"] = 4,
            ["GUID"] = "9647B212",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/600305/9647B212",
            ["bTurnOffVoice"] = true,
            },
        [60030601] = {
            ["Content"] = "不行不行，敌人被打倒的位置离药剂台太远的话，它就回收不到了！",
            ["ContentFR"] = "Non, non, non ! Si tu les bats trop loin du Poste d’Alchimie, il ne pourra pas récupérer leur Sérum !",
            ["DialogueId"] = 60030601,
            ["Duration"] = 4,
            ["GUID"] = "9647C27A",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/600306/9647C27A",
            ["bTurnOffVoice"] = true,
            },
        [60030701] = {
            ["Content"] = "你看起来好虚弱，是不是血清已经不多了……",
            ["ContentFR"] = "Tu as l’air {性别:tout|toute} pâle... On n’aurait pas déjà épuisé notre Sérum, par hasard ?",
            ["DialogueId"] = 60030701,
            ["Duration"] = 4,
            ["GUID"] = "9647D2E2",
            ["NextDialogue"] = 60030702,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/600307/9647D2E2",
            ["bTurnOffVoice"] = true,
            },
        [60030702] = {
            ["Content"] = "不要硬撑，快去把药剂台里做好的血清用掉吧！",
            ["ContentFR"] = "Ne force pas trop ! Utilise vite le Sérum qu’on a préparé au Poste d’Alchimie !",
            ["DialogueId"] = 60030702,
            ["Duration"] = 4,
            ["GUID"] = "9647D2E3",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/600307/9647D2E3",
            ["bTurnOffVoice"] = true,
            },
        [60030801] = {
            ["Content"] = "我启动了一个新的药剂台！",
            ["ContentFR"] = "Et voilà ! J’ai activé un nouveau Poste d’Alchimie !",
            ["DialogueId"] = 60030801,
            ["Duration"] = 4,
            ["GUID"] = "9647E34A",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/600308/9647E34A",
            ["bTurnOffVoice"] = true,
            },
        [60030901] = {
            ["Content"] = "呜哇，药剂台里一点血清都没了，我们也快走吧！",
            ["ContentFR"] = "Aïe ! Il n’y a plus une goutte de Sérum dans le Poste d’Alchimie ! On ferait mieux de filer !",
            ["DialogueId"] = 60030901,
            ["Duration"] = 4,
            ["GUID"] = "9647F3B2",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/600309/9647F3B2",
            ["bTurnOffVoice"] = true,
            },
        [60031001] = {
            ["Content"] = "快把做好的血清用掉吧。",
            ["ContentFR"] = "Allez, dépêche-toi d’utiliser le Sérum qu’on vient de fabriquer !",
            ["DialogueId"] = 60031001,
            ["Duration"] = 4,
            ["GUID"] = "9648041A",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/600310/9648041A",
            ["bTurnOffVoice"] = true,
            },
        [60031101] = {
            ["Content"] = "小白：哇啊啊，那个大家伙带着一大片毒雾冲过来了，我们的血清撑不了多久，快解决掉它吧！",
            ["ContentFR"] = "Grrr... toxines... croître... mort... s’accélère... Grrr...",
            ["DialogueId"] = 60031101,
            ["Duration"] = 4,
            ["GUID"] = "96481482",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/600311/96481482",
            ["bTurnOffVoice"] = true,
            },
        [60031201] = {
            ["Content"] = "敌人来啦！还好这个药剂台开始工作了,在它附近作战吧！",
            ["ContentFR"] = "Les ennemis arrivent ! Heureusement, ce Poste d’Alchimie fonctionne ! Combats près de lui !",
            ["DialogueId"] = 60031201,
            ["Duration"] = 4,
            ["GUID"] = "964824EA",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/600312/964824EA",
            ["bTurnOffVoice"] = true,
            },
        [60040101] = {
            ["Content"] = "哎，我们真是什么奇怪的委托都能接到呢，快点去找到委托人说的车子吧。",
            ["ContentFR"] = "Eh, on accepte vraiment les missions les plus étranges, pas vrai ? Allez, trouvons ce véhicule dont parlait le commanditaire.",
            ["DialogueId"] = 60040101,
            ["Duration"] = 4,
            ["GUID"] = "964DD912",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/600401/964DD912",
            ["bTurnOffVoice"] = true,
            },
        [60040201] = {
            ["Content"] = "哇哦，靠近发个信号以后车子真的动了，我们靠近车子时要注意自己的状态哦。可别在车子到目标点前就倒下了。",
            ["ContentFR"] = "Ouah ! On dirait que le signal a fonctionné — le véhicule bouge ! Reste sur tes gardes pendant l’escorte ! Pas question de s’effondrer avant d’arriver !",
            ["DialogueId"] = 60040201,
            ["Duration"] = 4,
            ["GUID"] = "964DE97A",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/600402/964DE97A",
            ["bTurnOffVoice"] = true,
            },
        [60040301] = {
            ["Content"] = "可恶，检查站的门又被关上了！把他们打倒然后冲过去吧！",
            ["ContentFR"] = "Argh ! La porte du point de contrôle est encore verrouillée ! Élimine-les et fonce !",
            ["DialogueId"] = 60040301,
            ["Duration"] = 4,
            ["GUID"] = "964DF9E2",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/600403/964DF9E2",
            ["bTurnOffVoice"] = true,
            },
        [60040401] = {
            ["Content"] = "检查站的门可以开啦，继续出发！滴滴滴~",
            ["ContentFR"] = "La porte est ouverte, on peut continuer ! <I>Bip bip biiip !</>",
            ["DialogueId"] = 60040401,
            ["Duration"] = 4,
            ["GUID"] = "964E0A4A",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/600404/964E0A4A",
            ["bTurnOffVoice"] = true,
            },
        [60040501] = {
            ["Content"] = "车子被前面的障碍物拦住了，破坏掉它吧！",
            ["ContentFR"] = "Le véhicule est bloqué par un obstacle, détruis-le !",
            ["DialogueId"] = 60040501,
            ["Duration"] = 4,
            ["GUID"] = "964E1AB2",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/600405/964E1AB2",
            ["bTurnOffVoice"] = true,
            },
        [60040601] = {
            ["Content"] = "不行呀，障碍物还是没碎，全力破坏它然后冲过去吧！",
            ["ContentFR"] = "Non, pas encore... L’obstacle tient toujours ! Allez, concentre-toi et fracasse-moi ça !",
            ["DialogueId"] = 60040601,
            ["Duration"] = 4,
            ["GUID"] = "964E2B1A",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/600406/964E2B1A",
            ["bTurnOffVoice"] = true,
            },
        [60040701] = {
            ["Content"] = "哼哼，小小障碍物怎么可能拦得住我们嘛，去车子边继续发信号让委托人把车子开起来吧！",
            ["ContentFR"] = "Héhé ! Ce petit tas de débris croyait pouvoir nous arrêter ? Retourne près du véhicule et envoie le signal pour qu’il redémarre !",
            ["DialogueId"] = 60040701,
            ["Duration"] = 4,
            ["GUID"] = "964E3B82",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/600407/964E3B82",
            ["bTurnOffVoice"] = true,
            },
        [60040801] = {
            ["Content"] = "可恶，检查站的门被关上了！打倒那个军官然后冲过去吧！",
            ["ContentFR"] = "Argh ! La porte du point de contrôle est verrouillée ! Occupe-toi de cet officier pour qu’on puisse avancer !",
            ["DialogueId"] = 60040801,
            ["Duration"] = 4,
            ["GUID"] = "964E3B86",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/600408/964E3B86",
            ["bTurnOffVoice"] = true,
            },
        [60050101] = {
            ["Content"] = "这次委托是让我们把这片区域的敌人都驱逐出去吗？真是简单易懂呀，让我们放开手脚大干一场吧！",
            ["ContentFR"] = "Cette mission consiste à repousser tous les ennemis de la zone ? Ça me va ! On va leur montrer de quel bois on se chauffe.",
            ["DialogueId"] = 60050101,
            ["Duration"] = 4,
            ["GUID"] = "965441B2",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/600501/965441B2",
            ["bTurnOffVoice"] = true,
            },
        [60050201] = {
            ["Content"] = "驱逐了这么多敌人，他们总该吸取教训了吧！收工收工，回去领报酬喽。",
            ["ContentFR"] = "On en a éliminé un sacré paquet... Ils devraient avoir compris la leçon, maintenant. Mission terminée, allons chercher notre récompense !",
            ["DialogueId"] = 60050201,
            ["Duration"] = 4,
            ["GUID"] = "9654521A",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/600502/9654521A",
            ["bTurnOffVoice"] = true,
            },
        [60060101] = {
            ["Content"] = "目标已倒下，委托失败。",
            ["ContentFR"] = "La cible est à terre... Mission échouée.",
            ["DialogueId"] = 60060101,
            ["Duration"] = 1,
            ["GUID"] = "965AAA52",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/0/600601/965AAA52",
            ["bTurnOffVoice"] = true,
            },
        [60060201] = {
            ["Content"] = "这次的委托有点复杂，我们得先解救被困的目标，再护送目标安全撤离。",
            ["ContentFR"] = "Cette mission est un peu plus délicate : il faut d’abord libérer la cible, puis la raccompagner en lieu sûr.",
            ["DialogueId"] = 60060201,
            ["Duration"] = 4,
            ["GUID"] = "965ABABA",
            ["NextDialogue"] = 60060202,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/600602/965ABABA",
            ["bTurnOffVoice"] = true,
            },
        [60060202] = {
            ["Content"] = "先按照委托人给的标记，找到敌人据点里的<H>密室区域</>吧。",
            ["ContentFR"] = "Suivons les repères indiqués par le commanditaire — la zone des <H>Cellules secrètes</> doit se trouver dans le repaire ennemi.",
            ["DialogueId"] = 60060202,
            ["Duration"] = 4,
            ["GUID"] = "965ABAE4",
            ["NextDialogue"] = 60060203,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/600602/965ABAE4",
            ["bTurnOffVoice"] = true,
            },
        [60060203] = {
            ["Content"] = "说起来，这个目标到底是什么人啊……值这么多钱又神神秘秘的，该不会是什么大人物吧？",
            ["ContentFR"] = "Mais au fait, qui est cette personne qu’on doit sauver ? Autant d’argent pour un inconnu aussi mystérieux... Ce serait pas un gros poisson, par hasard ?",
            ["DialogueId"] = 60060203,
            ["Duration"] = 4,
            ["GUID"] = "965ABB0E",
            ["NextDialogue"] = 60060204,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/600602/965ABB0E",
            ["bTurnOffVoice"] = true,
            },
        [60060204] = {
            ["Content"] = "又或者，是和委托人有什么不可告人的关系……哼哼……",
            ["ContentFR"] = "Ou alors... il y a une petite histoire entre lui et le commanditaire, hmm ? Hé hé hé...",
            ["DialogueId"] = 60060204,
            ["Duration"] = 4,
            ["GUID"] = "965ABB38",
            ["NextDialogue"] = 60060205,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/600602/965ABB38",
            ["bTurnOffVoice"] = true,
            },
        [60060205] = {
            ["Content"] = "你别忘了，委托人说过不要多问，否则我们就拿不到钱了。",
            ["ContentFR"] = "N’oublie pas ce que le commanditaire a dit — pas de questions, sinon pas de paiement.",
            ["DialogueId"] = 60060205,
            ["Duration"] = 4,
            ["GUID"] = "965ABB62",
            ["NextDialogue"] = 60060206,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/0/600602/965ABB62",
            ["bTurnOffVoice"] = true,
            },
        [60060206] = {
            ["Content"] = "呃——好吧，那我就忍一忍，不好奇了。",
            ["ContentFR"] = "Euh... bon, d’accord. J’vais retenir ma curiosité, pour cette fois.",
            ["DialogueId"] = 60060206,
            ["Duration"] = 3,
            ["GUID"] = "965ABB8C",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/600602/965ABB8C",
            ["bTurnOffVoice"] = true,
            },
        [60060301] = {
            ["Content"] = "根据事先调查到的情报，密室区域是由很多独立的小房间组成的，其中一间关着我们要找的目标。",
            ["ContentFR"] = "D’après les infos qu’on a récoltées, les Cellules secrètes sont composées de plusieurs pièces isolées. L’une d’elles abrite la cible.",
            ["DialogueId"] = 60060301,
            ["Duration"] = 4,
            ["GUID"] = "965ACB22",
            ["NextDialogue"] = 60060302,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/600603/965ACB22",
            ["bTurnOffVoice"] = true,
            },
        [60060302] = {
            ["Content"] = "看来敌人很谨慎啊！万一发现有人来营救，他们搞不好会破罐破摔，把目标灭口……",
            ["ContentFR"] = "Ces types sont vraiment prudents ! S’ils remarquent une tentative de sauvetage, ils pourraient supprimer la cible avant qu’on arrive...",
            ["DialogueId"] = 60060302,
            ["Duration"] = 4,
            ["GUID"] = "965ACB4C",
            ["NextDialogue"] = 60060303,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/600603/965ACB4C",
            ["bTurnOffVoice"] = true,
            },
        [60060303] = {
            ["Content"] = "尽量小心一些吧！",
            ["ContentFR"] = "Fais attention, surtout !",
            ["DialogueId"] = 60060303,
            ["Duration"] = 2.5,
            ["GUID"] = "965ACB76",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/600603/965ACB76",
            ["bTurnOffVoice"] = true,
            },
        [60060401] = {
            ["Content"] = "快看，前面就是密室区域了！要注意避开敌人中的<H>巡逻单位</>哦！",
            ["ContentFR"] = "Regarde là-bas, c’est la zone des Cellules secrètes ! Fais gaffe à éviter les <H>patrouilles</> ennemies !",
            ["DialogueId"] = 60060401,
            ["Duration"] = 4,
            ["GUID"] = "965ADB8A",
            ["NextDialogue"] = 60060402,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/600604/965ADB8A",
            ["bTurnOffVoice"] = true,
            },
        [60060402] = {
            ["Content"] = "如果他们发出了警报，目标可就危险啦。",
            ["ContentFR"] = "S’ils déclenchent l’alarme, la cible est fichue !",
            ["DialogueId"] = 60060402,
            ["Duration"] = 3,
            ["GUID"] = "965ADBB4",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/600604/965ADBB4",
            ["bTurnOffVoice"] = true,
            },
        [60060501] = {
            ["Content"] = "呜哇，这些密室还真是长得一模一样啊……不过，以小仆从的聪明才智，解开这些机关绰绰有余。",
            ["ContentFR"] = "Pfiou... toutes ces cellules se ressemblent ! Mais grâce à l’intelligence du petit larbin, on va s’en sortir sans problème.",
            ["DialogueId"] = 60060501,
            ["Duration"] = 4,
            ["GUID"] = "965AEBF2",
            ["NextDialogue"] = 60060502,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/600605/965AEBF2",
            ["bTurnOffVoice"] = true,
            },
        [60060502] = {
            ["Content"] = "抓紧时间找到目标所在的密室吧！本魔王会在旁边帮你注意动静的。",
            ["ContentFR"] = "Dépêche-toi de trouver la cellule où est enfermée la cible ! Sa Majesté le Roi Démon veille au grain.",
            ["DialogueId"] = 60060502,
            ["Duration"] = 4,
            ["GUID"] = "965AEC1C",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/600605/965AEC1C",
            ["bTurnOffVoice"] = true,
            },
        [60060601] = {
            ["Content"] = "不、不要靠近我……！",
            ["ContentFR"] = "N-N’approchez pas... !",
            ["DialogueId"] = 60060601,
            ["Duration"] = 2.5,
            ["GUID"] = "965AFC5A",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 60060602,
            ["SpeakNpcId"] = 930001,
            ["VoiceName"] = "voice/$Locale$/story/0/600606/965AFC5A",
            ["bTurnOffVoice"] = true,
            },
        [60060602] = {
            ["Content"] = "别怕，我们是狩月人，来救你的！",
            ["ContentFR"] = "N’aie pas peur, nous sommes des Chasseurs de Phoxène. On est là pour te sauver !",
            ["DialogueId"] = 60060602,
            ["Duration"] = 3,
            ["GUID"] = "965AFC84",
            ["NextDialogue"] = 60060603,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/600606/965AFC84",
            ["bTurnOffVoice"] = true,
            },
        [60060603] = {
            ["Content"] = "咦……？啊，我知道了，是那个人让你们来的，一定是的……",
            ["ContentFR"] = "Hein... ? Oh, je comprends... C’est cette personne qui vous envoie... n’est-ce pas ?",
            ["DialogueId"] = 60060603,
            ["Duration"] = 4,
            ["GUID"] = "965AFCAE",
            ["GuideFacialId"] = "Confident",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 60060604,
            ["SpeakNpcId"] = 930001,
            ["VoiceName"] = "voice/$Locale$/story/0/600606/965AFCAE",
            ["bTurnOffVoice"] = true,
            },
        [60060604] = {
            ["Content"] = "谢谢！我们快走吧，我等不及要见到……",
            ["ContentFR"] = "Merci ! Partons vite, j’ai hâte de le revoir...",
            ["DialogueId"] = 60060604,
            ["Duration"] = 4,
            ["GUID"] = "965AFCD8",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 930001,
            ["VoiceName"] = "voice/$Locale$/story/0/600606/965AFCD8",
            ["bTurnOffVoice"] = true,
            },
        [60060701] = {
            ["Content"] = "不好啦，那个巡逻的家伙发出了警报！",
            ["ContentFR"] = "Oh non ! L’un des patrouilleurs a déclenché l’alarme !",
            ["DialogueId"] = 60060701,
            ["Duration"] = 3,
            ["GUID"] = "965B0CC2",
            ["NextDialogue"] = 60060702,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/600607/965B0CC2",
            ["bTurnOffVoice"] = true,
            },
        [60060702] = {
            ["Content"] = "和我想的一样，他们果然狗急跳墙，打算把目标处理掉了！",
            ["ContentFR"] = "Je le savais ! Ces lâches sont prêts à tout, ils veulent exécuter la cible avant qu’on arrive !",
            ["DialogueId"] = 60060702,
            ["Duration"] = 4,
            ["GUID"] = "965B0CEC",
            ["NextDialogue"] = 60060703,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/600607/965B0CEC",
            ["bTurnOffVoice"] = true,
            },
        [60060703] = {
            ["Content"] = "得赶在他们之前救出目标才行。",
            ["ContentFR"] = "On doit la sauver avant qu’il ne soit trop tard !",
            ["DialogueId"] = 60060703,
            ["Duration"] = 2,
            ["GUID"] = "965B0D16",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/600607/965B0D16",
            ["bTurnOffVoice"] = true,
            },
        [60060801] = {
            ["Content"] = "哎，我好像听见目标的呼救声了！",
            ["ContentFR"] = "J’entends des appels à l’aide ! C’est sûrement la cible !",
            ["DialogueId"] = 60060801,
            ["Duration"] = 2,
            ["GUID"] = "965B1D2A",
            ["NextDialogue"] = 60060802,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/600608/965B1D2A",
            ["bTurnOffVoice"] = true,
            },
        [60060802] = {
            ["Content"] = "就是那间密室，快去救人吧！",
            ["ContentFR"] = "Cette cellule-là — c’est la bonne ! Vite, va la sauver !",
            ["DialogueId"] = 60060802,
            ["Duration"] = 2,
            ["GUID"] = "965B1D54",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/600608/965B1D54",
            ["bTurnOffVoice"] = true,
            },
        [60060901] = {
            ["Content"] = "我……好像动不了了……拜托，请救救我……！",
            ["ContentFR"] = "Je... je ne peux plus bouger... s’il vous plaît... aidez-moi... !",
            ["DialogueId"] = 60060901,
            ["Duration"] = 3,
            ["GUID"] = "965B2D92",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 60060902,
            ["SpeakNpcId"] = 930001,
            ["VoiceName"] = "voice/$Locale$/story/0/600609/965B2D92",
            ["bTurnOffVoice"] = true,
            },
        [60060902] = {
            ["Content"] = "我不能……在这里……倒下……我还没有……",
            ["ContentFR"] = "Je ne peux pas... m’effondrer maintenant... pas ici...",
            ["DialogueId"] = 60060902,
            ["Duration"] = 3,
            ["GUID"] = "965B3DFA",
            ["GuideFacialId"] = "Sad",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 930001,
            ["VoiceName"] = "voice/$Locale$/story/0/600609/965B3DFA",
            ["bTurnOffVoice"] = true,
            },
