            ["DialogueId"] = 60140503,
            ["Duration"] = 5,
            ["GUID"] = "968E3146",
            ["VoiceName"] = "sfx/boss/Lianhuo/vo_$Locale$_battleEnd",
            },
        [60140504] = {
            ["Content"] = "开始你最后的狡辩。",
            ["ContentFR"] = "Alors... qu’as-tu à dire pour ta défense ?",
            ["DialogueId"] = 60140504,
            ["Duration"] = 5,
            ["GUID"] = "968E3170",
            ["VoiceName"] = "sfx/boss/Lianhuo/vo_$Locale$_skill06_01",
            },
        [60140505] = {
            ["Content"] = "在宣判前，丑陋地挣扎吧。",
            ["ContentFR"] = "Tord-toi donc avant la sentence.",
            ["DialogueId"] = 60140505,
            ["Duration"] = 5,
            ["GUID"] = "968E319A",
            ["VoiceName"] = "sfx/boss/Lianhuo/vo_$Locale$_skill06_02",
            },
        [60140506] = {
            ["Content"] = "在枷锁中迎接死亡。",
            ["ContentFR"] = "Mourir enchaîné... voilà ton sort.",
            ["DialogueId"] = 60140506,
            ["Duration"] = 5,
            ["GUID"] = "968E31C4",
            ["VoiceName"] = "sfx/boss/Lianhuo/vo_$Locale$_skill08_01",
            },
        [60140507] = {
            ["Content"] = "律法会历数你的罪状。",
            ["ContentFR"] = "La Loi énumérera tous tes crimes.",
            ["DialogueId"] = 60140507,
            ["Duration"] = 5,
            ["GUID"] = "968E31EE",
            ["VoiceName"] = "sfx/boss/Lianhuo/vo_$Locale$_skill08_02",
            },
        [60140508] = {
            ["Content"] = "休想逃脱火焰的囚笼。",
            ["ContentFR"] = "Nul n’échappe à la prison de flammes.",
            ["DialogueId"] = 60140508,
            ["Duration"] = 5,
            ["GUID"] = "968E3218",
            ["VoiceName"] = "sfx/boss/Lianhuo/vo_$Locale$_skill03",
            },
        [60149001] = {
            ["Content"] = "打打打打打劫，唔……这家伙看起来好猛，溜了溜了。",
            ["ContentFR"] = "H-H-H-H-Haut les mains ! Oh, {性别:celui-là|celle-là} a l’air costaud... je m’en vais !",
            ["DialogueId"] = 60149001,
            ["Duration"] = 5,
            ["GUID"] = "9693A37A",
            ["SpeakNpcId"] = 920001,
            ["VoiceName"] = "voice/$Locale$/char/Dajiebai/vo_birth_r01",
            },
        [60149002] = {
            ["Content"] = "可恶！怎么是你，再再再见。",
            ["DialogueId"] = 60149002,
            ["Duration"] = 3.8,
            ["GUID"] = "9693A3A4",
            ["SpeakNpcId"] = 920001,
            ["VoiceName"] = "voice/$Locale$/char/Dajiebai/vo_birth_r02",
            },
        [60149003] = {
            ["Content"] = "留留留下买路财！啧，怎么今天一上来就碰到硬茬子，告辞。",
            ["DialogueId"] = 60149003,
            ["Duration"] = 6.7,
            ["GUID"] = "9693A3CE",
            ["SpeakNpcId"] = 920001,
            ["VoiceName"] = "voice/$Locale$/char/Dajiebai/vo_birth_r03",
            },
        [60149004] = {
            ["Content"] = "除了打劫，逃跑我也是专业的！",
            ["DialogueId"] = 60149004,
            ["Duration"] = 3.5,
            ["GUID"] = "9693A3F8",
            ["SpeakNpcId"] = 920001,
            ["VoiceName"] = "voice/$Locale$/char/Dajiebai/vo_Skill01",
            },
        [60149005] = {
            ["Content"] = "舍不得孩子套不着狼，这些都给你，别再追啦！",
            ["DialogueId"] = 60149005,
            ["Duration"] = 5.1,
            ["GUID"] = "9693A422",
            ["SpeakNpcId"] = 920001,
            ["VoiceName"] = "voice/$Locale$/char/Dajiebai/vo_Skill02",
            },
        [60149006] = {
            ["Content"] = "咋还在追我啊，这个给你行了吧。",
            ["DialogueId"] = 60149006,
            ["Duration"] = 3.5,
            ["GUID"] = "9693A44C",
            ["SpeakNpcId"] = 920001,
            ["VoiceName"] = "voice/$Locale$/char/Dajiebai/vo_Skill03",
            },
        [60149007] = {
            ["Content"] = "你使那么大劲干啥呢！",
            ["DialogueId"] = 60149007,
            ["Duration"] = 2.5,
            ["GUID"] = "9693A476",
            ["SpeakNpcId"] = 920001,
            ["VoiceName"] = "voice/$Locale$/char/Dajiebai/vo_be_hit_heavy_r01",
            },
        [60149008] = {
            ["Content"] = "可恶，以后走夜路小心点！",
            ["DialogueId"] = 60149008,
            ["Duration"] = 3.2,
            ["GUID"] = "9693A4A0",
            ["SpeakNpcId"] = 920001,
            ["VoiceName"] = "voice/$Locale$/char/Dajiebai/vo_be_hit_heavy_r02",
            },
        [60149009] = {
            ["Content"] = "啊啊啊啊啊，我要生气了！",
            ["DialogueId"] = 60149009,
            ["Duration"] = 3.4,
            ["GUID"] = "9693A4CA",
            ["SpeakNpcId"] = 920001,
            ["VoiceName"] = "voice/$Locale$/char/Dajiebai/vo_be_hit_heavy_r03",
            },
        [60149010] = {
            ["Content"] = "笨笨笨蛋，追不上我吧，桀桀桀桀桀桀~",
            ["DialogueId"] = 60149010,
            ["Duration"] = 6,
            ["GUID"] = "9693A4F4",
            ["SpeakNpcId"] = 920001,
            ["VoiceName"] = "voice/$Locale$/char/Dajiebai/vo_Skill04",
            },
        [60149011] = {
            ["Content"] = "这次是我大意了，下次我一定要把你打得抱头大哭，呜……",
            ["DialogueId"] = 60149011,
            ["Duration"] = 10.4,
            ["GUID"] = "9693A51E",
            ["SpeakNpcId"] = 920001,
            ["VoiceName"] = "voice/$Locale$/char/Dajiebai/vo_death",
            },
        [60149012] = {
            ["Content"] = "东西南北四条街，打听打听谁是爹，道上谁不知道我打劫皎皎的名号！",
            ["DialogueId"] = 60149012,
            ["Duration"] = 6.9,
            ["GUID"] = "9693A548",
            ["SpeakNpcId"] = 920001,
            ["VoiceName"] = "voice/$Locale$/char/Dajiebai/vo_Run_r01",
            },
        [60149013] = {
            ["Content"] = "跟我斗，你还是太年轻了呀~",
            ["DialogueId"] = 60149013,
            ["Duration"] = 5.7,
            ["GUID"] = "9693A572",
            ["SpeakNpcId"] = 920001,
            ["VoiceName"] = "voice/$Locale$/char/Dajiebai/vo_Run_r02",
            },
        [60149014] = {
            ["Content"] = "哼，我打打打劫皎皎可不是好惹的。",
            ["DialogueId"] = 60149014,
            ["Duration"] = 4.8,
            ["GUID"] = "9693A59C",
            ["SpeakNpcId"] = 920001,
            ["VoiceName"] = "voice/$Locale$/char/Dajiebai/vo_Run_r03",
            },
        [60149015] = {
            ["Content"] = "呼，呼……你咋还不累呢，吃啥玩意长大的啊。",
            ["DialogueId"] = 60149015,
            ["Duration"] = 8.8,
            ["GUID"] = "9693A5C6",
            ["SpeakNpcId"] = 920001,
            ["VoiceName"] = "voice/$Locale$/char/Dajiebai/vo_Run_r04",
            },
        [60150001] = {
            ["Content"] = "离我远点！",
            ["ContentFR"] = "Reste loin de moi !",
            ["DialogueId"] = 60150001,
            ["Duration"] = 3,
            ["GUID"] = "9694478A",
            ["SpeakNpcId"] = 200053,
            ["VoiceName"] = "sfx/enemy/Mn/Haer/vo_$Locale$_Attack01",
            },
        [60150002] = {
            ["Content"] = "非要吃点苦头？",
            ["ContentFR"] = "Tu l’auras voulu !",
            ["DialogueId"] = 60150002,
            ["Duration"] = 3,
            ["GUID"] = "969447B4",
            ["SpeakNpcId"] = 200053,
            ["VoiceName"] = "sfx/enemy/Mn/Haer/vo_$Locale$_Attack02",
            },
        [60150003] = {
            ["Content"] = "我跑不动了……我投降……",
            ["ContentFR"] = "Je n’en peux plus... je me rends...",
            ["DialogueId"] = 60150003,
            ["Duration"] = 5,
            ["GUID"] = "969447DE",
            ["SpeakNpcId"] = 200053,
            ["VoiceName"] = "sfx/enemy/Mn/Haer/vo_$Locale$_Die",
            },
        [60150004] = {
            ["Content"] = "别逞能了！",
            ["ContentFR"] = "Arrête ton cirque !",
            ["DialogueId"] = 60150004,
            ["Duration"] = 3,
            ["GUID"] = "96944808",
            ["SpeakNpcId"] = 200053,
            ["VoiceName"] = "sfx/enemy/Mn/Haer/vo_$Locale$_Skill01",
            },
        [60150005] = {
            ["Content"] = "别追了!",
            ["ContentFR"] = "Arrête de me suivre !",
            ["DialogueId"] = 60150005,
            ["Duration"] = 3,
            ["GUID"] = "96944832",
            ["SpeakNpcId"] = 200053,
            ["VoiceName"] = "sfx/enemy/Mn/Haer/vo_$Locale$_Skill02",
            },
        [60150006] = {
            ["Content"] = "追不上的你们！",
            ["ContentFR"] = "Vous ne m’aurez pas !",
            ["DialogueId"] = 60150006,
            ["Duration"] = 4,
            ["GUID"] = "9694485C",
            ["SpeakNpcId"] = 200053,
            ["VoiceName"] = "sfx/enemy/Mn/Haer/vo_$Locale$_Skill03",
            },
        [60160001] = {
            ["Content"] = "欢迎乘坐帝国铁道的最新专列——极光号！",
            ["DialogueId"] = 60160001,
            ["Duration"] = 4,
            ["GUID"] = "969AB02A",
            ["SpeakNpcId"] = 920001,
            },
        [60160002] = {
            ["Content"] = "最终防卫状态已经启动，进入最终防御状态。",
            ["DialogueId"] = 60160002,
            ["Duration"] = 4,
            ["GUID"] = "969AB054",
            ["SpeakNpcId"] = 920001,
            },
        [60160003] = {
            ["Content"] = "列车主炮已无反应，已记录战斗数据，后续继续优化。",
            ["DialogueId"] = 60160003,
            ["Duration"] = 4,
            ["GUID"] = "969AB07E",
            ["SpeakNpcId"] = 920001,
            },
        [60160004] = {
            ["Content"] = "月髓引擎运转已经过载，失去控制，失去控制……",
            ["DialogueId"] = 60160004,
            ["Duration"] = 4,
            ["GUID"] = "969AB0A8",
            ["SpeakNpcId"] = 920001,
            },
        [60160005] = {
            ["Content"] = "和钢铁掰掰手腕吧。",
            ["DialogueId"] = 60160005,
            ["Duration"] = 4,
            ["GUID"] = "969AB0D2",
            ["SpeakNpcId"] = 920001,
            },
        [60160006] = {
            ["Content"] = "来点惊喜，笑一笑。",
            ["DialogueId"] = 60160006,
            ["Duration"] = 4,
            ["SpeakNpcId"] = 920001,
            },
        [60160007] = {
            ["Content"] = "极光号将会以最快的速度抵达远方——",
            ["DialogueId"] = 60160007,
            ["Duration"] = 4,
            ["SpeakNpcId"] = 920001,
            },
        [60160008] = {
            ["Content"] = "听说你们一直在找炸弹？",
            ["DialogueId"] = 60160008,
            ["Duration"] = 4,
            ["SpeakNpcId"] = 920001,
            },
        [60160009] = {
            ["Content"] = "别躲嘛，别害羞。",
            ["DialogueId"] = 60160009,
            ["Duration"] = 4,
            ["SpeakNpcId"] = 920001,
            },
        [60170001] = {
            ["Content"] = "死……死！",
            ["ContentFR"] = "Meurs... MEEEUUURS !",
            ["DialogueId"] = 60170001,
            ["Duration"] = 1.5,
            ["GUID"] = "96A118CA",
            ["VoiceName"] = "sfx/boss/Tuosi/vo_$Locale$_BattleStart01",
            },
        [60170002] = {
            ["Content"] = "吼……呃……啊啊啊啊……",
            ["ContentFR"] = "Raaagh... Urrhh... AAAARGH !",
            ["DialogueId"] = 60170002,
            ["Duration"] = 1.5,
            ["GUID"] = "96A118F4",
            ["VoiceName"] = "sfx/boss/Tuosi/vo_$Locale$_Skill06",
            },
        [60170003] = {
            ["Content"] = "嘎嗷嗷嗷……吼……吼！！",
            ["ContentFR"] = "GRRRR... RAAH... ROOOAR !",
            ["DialogueId"] = 60170003,
            ["Duration"] = 4,
            ["GUID"] = "96A1191E",
            ["VoiceName"] = "sfx/boss/Tuosi/vo_$Locale$_Skill08",
            },
        [60180001] = {
            ["Content"] = "近吾者，必罹天劫！",
            ["ContentFR"] = "Que quiconque ose s’approcher soit foudroyé par le jugement des cieux !",
            ["DialogueId"] = 60180001,
            ["Duration"] = 3,
            ["GUID"] = "9834E965",
            ["VoiceName"] = "sfx/boss/Heilong/vo_$Locale$_BattleStart",
            },
        [60180002] = {
            ["Content"] = "吼————",
            ["ContentFR"] = "ROAAAH !",
            ["DialogueId"] = 60180002,
            ["Duration"] = 3,
            ["GUID"] = "9834E966",
            ["VoiceName"] = "sfx/boss/Heilong/vo_$Locale$_Condemn",
            },
        [60180003] = {
            ["Content"] = "俱往矣……",
            ["ContentFR"] = "Tout s’efface dans le néant...",
            ["DialogueId"] = 60180003,
            ["Duration"] = 3,
            ["GUID"] = "9834E967",
            ["VoiceName"] = "sfx/boss/Heilong/vo_$Locale$_BattleEnd",
            },
        [60180004] = {
            ["Content"] = "晦暝临世。",
            ["ContentFR"] = "Les ténèbres s’abattent sur ce monde.",
            ["DialogueId"] = 60180004,
            ["Duration"] = 4,
            ["GUID"] = "9834E968",
            ["VoiceName"] = "sfx/boss/Heilong/vo_$Locale$_Skill05",
            },
        [60180005] = {
            ["Content"] = "吼————",
            ["ContentFR"] = "Les ombres grondent, le tonnerre s’éveille...",
            ["DialogueId"] = 60180005,
            ["Duration"] = 5,
            ["GUID"] = "9834E969",
            ["VoiceName"] = "sfx/boss/Heilong/vo_$Locale$_Skill06",
            },
        [60180006] = {
            ["Content"] = "曀曀其阴，虺虺其雷——",
            ["ContentFR"] = "ROAAAR !",
            ["DialogueId"] = 60180006,
            ["Duration"] = 3,
            ["GUID"] = "9834E970",
            ["VoiceName"] = "sfx/boss/Heilong/vo_$Locale$_Skill07",
            },
        [60200101] = {
            ["Content"] = "不好，我们被敌人发现了！",
            ["ContentFR"] = "Zut, on a été repérés par l’ennemi !",
            ["DialogueId"] = 60200101,
            ["Duration"] = 4,
            ["GUID"] = "96B46312",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/602001/96B46312",
            ["bTurnOffVoice"] = true,
            },
        [60200201] = {
            ["Content"] = "发现敌人，在他们呼叫同伴前阻止他们吧。",
            ["ContentFR"] = "Ennemi repéré ! Empêche-le d’appeler des renforts !",
            ["DialogueId"] = 60200201,
            ["Duration"] = 4,
            ["GUID"] = "96B4737A",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/602002/96B4737A",
            ["bTurnOffVoice"] = true,
            },
        [60200301] = {
            ["Content"] = "当心，敌人要去呼叫同伴了！再这样下去就麻烦啦。",
            ["ContentFR"] = "Attention, ils vont prévenir leurs alliés ! Si on ne fait rien, ça va très mal tourner.",
            ["DialogueId"] = 60200301,
            ["Duration"] = 4,
            ["GUID"] = "96B483E2",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/602003/96B483E2",
            ["bTurnOffVoice"] = true,
            },
        [60200401] = {
            ["Content"] = "他们要去呼叫同伴，快想想办法阻止一下呀！",
            ["ContentFR"] = "Ils vont appeler du renfort ! Vite, trouve un moyen de les en empêcher !",
            ["DialogueId"] = 60200401,
            ["Duration"] = 4,
            ["GUID"] = "96B4944A",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/602004/96B4944A",
            ["bTurnOffVoice"] = true,
            },
        [60200501] = {
            ["Content"] = "真是的，我们躲藏得这么好居然都被发现了，没办法，快点解决掉他们吧。",
            ["ContentFR"] = "Argh, on s’était si bien cachés ! Tant pis, il va falloir les éliminer rapidement.",
            ["DialogueId"] = 60200501,
            ["Duration"] = 4,
            ["GUID"] = "96B4A4B2",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/602005/96B4A4B2",
            ["bTurnOffVoice"] = true,
            },
        [60210101] = {
            ["Content"] = "委托人只能帮我们争取到一点点时间，我们趁现在快把那三台奇奇怪怪的装置拆掉吧！",
            ["ContentFR"] = "Le commanditaire n’a pu nous gagner qu’un peu de temps. Allons vite démonter ces trois drôles de machines avant qu’il ne soit trop tard !",
            ["DialogueId"] = 60210101,
            ["Duration"] = 4,
            ["GUID"] = "9687C88C",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/602101/9687C88C",
            ["bTurnOffVoice"] = true,
            },
        [60210201] = {
            ["Content"] = "好耶，全都拆掉了，委托圆满完成！",
            ["ContentFR"] = "Youpi ! Tout démonté ! Mission accomplie haut la main !",
            ["DialogueId"] = 60210201,
            ["Duration"] = 3,
            ["GUID"] = "9687C892",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/602102/9687C892",
            ["bTurnOffVoice"] = true,
            },
        [60210301] = {
            ["Content"] = "委托人说没时间了，我们也快撤吧！",
            ["ContentFR"] = "Le commanditaire dit que le temps est écoulé — on se replie, vite !",
            ["DialogueId"] = 60210301,
            ["Duration"] = 3,
            ["GUID"] = "9687C896",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/602103/9687C896",
            ["bTurnOffVoice"] = true,
            },
        [60220101] = {
            ["Content"] = "什么什么，第一场比赛这就开始了吗？",
            ["ContentFR"] = "Hein, quoi ?! La première manche commence déjà !?",
            ["DialogueId"] = 60220101,
            ["Duration"] = 4,
            ["GUID"] = "9687C89A",
            ["NextDialogue"] = 60220102,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/602201/9687C89A",
            ["bTurnOffVoice"] = true,
            },
        [60220102] = {
            ["Content"] = "我看看哇……第一场我们要做的是淘汰“神奇的同盟”这支队伍的种子选手！",
            ["ContentFR"] = "Voyons voir... Oh ! On doit éliminer le champion de l’équipe « Les Déçus » !",
            ["DialogueId"] = 60220102,
            ["Duration"] = 3,
            ["GUID"] = "9687C89E",
            ["NextDialogue"] = 60220103,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/602201/9687C89E",
            ["bTurnOffVoice"] = true,
            },
        [60220103] = {
            ["Content"] = "但我们根本不知道其他人藏在哪嘛！去周围找找线索吧。",
            ["ContentFR"] = "Mais on ne sait même pas où ils se cachent ! Vite, cherchons des indices !",
            ["DialogueId"] = 60220103,
            ["Duration"] = 3,
            ["GUID"] = "9687C8A2",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/602201/9687C8A2",
            ["bTurnOffVoice"] = true,
            },
        [60220201] = {
            ["Content"] = "知道他们的种子选手藏在哪了！去打败啊不是，淘汰他们吧~",
            ["ContentFR"] = "Haha ! On a trouvé où il se planque ! Allez, on va le... euh, l’éliminer !",
            ["DialogueId"] = 60220201,
            ["Duration"] = 3,
            ["GUID"] = "9687C8A6",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/602202/9687C8A6",
            ["bTurnOffVoice"] = true,
            },
        [60220301] = {
            ["Content"] = "下场好像是个抢地盘的比赛耶，我们快过去吧。",
            ["ContentFR"] = "La prochaine manche, c’est un combat de territoire ! En avant !",
            ["DialogueId"] = 60220301,
            ["Duration"] = 3,
            ["GUID"] = "9687C8AA",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/602203/9687C8AA",
            ["bTurnOffVoice"] = true,
            },
        [60220401] = {
            ["Content"] = "把他们从指定区域赶走！这场比赛的胜利必将属于我们“军团长天下第一”。",
            ["ContentFR"] = "Chassez-les de la zone désignée ! La victoire sera pour « Le Commandant est le meilleur » !",
            ["DialogueId"] = 60220401,
            ["Duration"] = 4,
            ["GUID"] = "9687C8AE",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 930002,
            ["VoiceName"] = "voice/$Locale$/story/0/602204/9687C8AE",
            ["bTurnOffVoice"] = true,
            },
        [60220501] = {
            ["Content"] = "军团的骄傲，靠你们了。",
            ["ContentFR"] = "L’honneur de la Légion repose sur vos épaules.",
            ["DialogueId"] = 60220501,
            ["Duration"] = 4,
            ["GUID"] = "9687C8B2",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 930002,
            ["VoiceName"] = "voice/$Locale$/story/0/602205/9687C8B2",
            ["bTurnOffVoice"] = true,
            },
        [60220601] = {
            ["Content"] = "可恶，居然如此难缠，看来不是保留实力的时候了。",
            ["ContentFR"] = "Pff... Quelle résistance ! Il est temps de se battre sérieusement.",
            ["DialogueId"] = 60220601,
            ["Duration"] = 4,
            ["GUID"] = "9687C8B6",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 930002,
            ["VoiceName"] = "voice/$Locale$/story/0/602206/9687C8B6",
            ["bTurnOffVoice"] = true,
            },
        [60220701] = {
            ["Content"] = "虽然输了……但下场比赛，我们还有机会！",
            ["ContentFR"] = "Même si nous avons perdu... la prochaine manche sera la nôtre !",
            ["DialogueId"] = 60220701,
            ["Duration"] = 3,
            ["GUID"] = "9687C8BA",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 930002,
            ["VoiceName"] = "voice/$Locale$/story/0/602207/9687C8BA",
            ["bTurnOffVoice"] = true,
            },
        [60220801] = {
            ["Content"] = "终于到第三场比赛了呀，快去奖箱那里吧，绝不能让其他人抢走！",
            ["ContentFR"] = "Enfin ! Troisième manche ! Vite, au coffre ! On ne va pas laisser quelqu’un d’autre le prendre !",
            ["DialogueId"] = 60220801,
            ["Duration"] = 4,
            ["GUID"] = "9687C8BE",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/602208/9687C8BE",
            ["bTurnOffVoice"] = true,
            },
        [60220901] = {
            ["Content"] = "开始了开始了！从这群家伙手里夺回钥匙，打开最后的宝箱吧。",
            ["ContentFR"] = "Ça y est, ça commence ! Récupère les clés sur ces types et ouvre le coffre final !",
            ["DialogueId"] = 60220901,
            ["Duration"] = 3,
            ["GUID"] = "9687C8C2",
            ["NextDialogue"] = 60220902,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/602209/9687C8C2",
            ["bTurnOffVoice"] = true,
            },
        [60220902] = {
            ["Content"] = "一群异教徒，妄想染指神赐的宝物。准备好承受祂的怒火了吗？",
            ["ContentFR"] = "Impies ! Comment osez-vous convoiter un trésor béni par les dieux ? Préparez-vous à subir Sa colère !",
            ["DialogueId"] = 60220902,
            ["Duration"] = 4,
            ["GUID"] = "9687C8C4",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 930003,
            ["VoiceName"] = "voice/$Locale$/story/0/602209/9687C8C4",
            ["bTurnOffVoice"] = true,
            },
        [60221001] = {
            ["Content"] = "去吧，神最虔诚的信徒们，为祂摘下名为胜利的果实。",
            ["ContentFR"] = "En avant, fidèles serviteurs ! Récoltez le fruit de la victoire en Son nom !",
            ["DialogueId"] = 60221001,
            ["Duration"] = 4,
            ["GUID"] = "9687C8C6",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 930003,
            ["VoiceName"] = "voice/$Locale$/story/0/602210/9687C8C6",
            ["bTurnOffVoice"] = true,
            },
        [60221101] = {
            ["Content"] = "为了军团的荣耀，前进！",
            ["ContentFR"] = "Pour la gloire de la Légion ! En avant !",
            ["DialogueId"] = 60221101,
            ["Duration"] = 4,
            ["GUID"] = "9687C8CA",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 930002,
            ["VoiceName"] = "voice/$Locale$/story/0/602211/9687C8CA",
            ["bTurnOffVoice"] = true,
            },
        [60221201] = {
            ["Content"] = "如我所料，大赛最重要的还是第三场。现在，该我们大显身手了。",
            ["ContentFR"] = "Comme prévu... la troisième manche est la plus décisive. À nous de briller !",
            ["DialogueId"] = 60221201,
            ["Duration"] = 4,
            ["GUID"] = "9687C8CE",
            ["SpeakNpcId"] = 930004,
            ["VoiceName"] = "voice/$Locale$/story/0/602212/9687C8CE",
            ["bTurnOffVoice"] = true,
            },
        [60221301] = {
            ["Content"] = "这样就打开第一把锁了，剩下的也继续加油吧！",
            ["ContentFR"] = "Une serrure ouverte ! Continuons, on peut ouvrir les autres !",
            ["DialogueId"] = 60221301,
            ["Duration"] = 3,
            ["GUID"] = "9687C8D2",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/602213/9687C8D2",
            ["bTurnOffVoice"] = true,
            },
        [60221401] = {
            ["Content"] = "宝箱开啦，好耶！是我们赢喽~",
            ["ContentFR"] = "Le coffre est ouvert, youpi ! C’est nous les vainqueurs !",
            ["DialogueId"] = 60221401,
            ["Duration"] = 3,
            ["GUID"] = "9687C8D6",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/602214/9687C8D6",
            ["bTurnOffVoice"] = true,
            },
        [60221501] = {
            ["Content"] = "看那边看那边，主办方往赛场里丢进来一把新钥匙！",
            ["ContentFR"] = "Regarde, regarde ! L’organisation vient de lancer une nouvelle clé dans l’arène !",
            ["DialogueId"] = 60221501,
            ["Duration"] = 4,
            ["GUID"] = "9687C8DA",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/602215/9687C8DA",
            ["bTurnOffVoice"] = true,
            },
        [60221601] = {
            ["Content"] = "为了军团的荣耀，前进！",
            ["ContentFR"] = "Pour la gloire de la Légion ! En avant !",
            ["DialogueId"] = 60221601,
            ["Duration"] = 4,
            ["GUID"] = "9687C8DE",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 930005,
            ["VoiceName"] = "voice/$Locale$/story/0/602216/9687C8DE",
            ["bTurnOffVoice"] = true,
            },
        [60230101] = {
            ["Content"] = "赶快去找药剂台吧。",
            ["ContentFR"] = "Allez vite, trouve le Poste d’Alchimie !",
            ["DialogueId"] = 60230101,
            ["Duration"] = 4,
            ["GUID"] = "96910001",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/602301/96910001",
            ["bTurnOffVoice"] = true,
            },
        [60230201] = {
            ["Content"] = "对了对了，要让药剂台回收血清的话，就得在它附近打倒敌人才行！",
            ["ContentFR"] = "Ah oui, j’y pense ! Pour que le Poste d’Alchimie récupère le Sérum, il faut battre les ennemis juste à côté !",
            ["DialogueId"] = 60230201,
            ["Duration"] = 4,
            ["GUID"] = "96910029",
            ["NextDialogue"] = 60230202,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/602302/96910029",
            ["bTurnOffVoice"] = true,
            },
        [60230202] = {
            ["Content"] = "把药剂台装满就能完成委托了，加油加油。",
            ["ContentFR"] = "Remplis le Poste d’Alchimie et la mission sera accomplie ! En avant, petit larbin, montre-leur notre grandeur !",
            ["DialogueId"] = 60230202,
            ["Duration"] = 4,
            ["GUID"] = "96910191",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/602302/96910191",
            ["bTurnOffVoice"] = true,
            },
        [60230301] = {
            ["Content"] = "嘘……我听到一些奇怪的动静，好像有大家伙要来了！",
            ["ContentFR"] = "Chut... J’entends des bruits bizarres... On dirait qu’un gros monstre arrive par ici !",
            ["DialogueId"] = 60230301,
            ["Duration"] = 4,
            ["GUID"] = "96910321",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/602303/96910321",
            ["bTurnOffVoice"] = true,
            },
        [60230401] = {
            ["Content"] = "哇啊啊，有个大家伙带着一大片毒雾冲过来了，药剂台里的血清一下子就会被它侵蚀干净的，快解决掉它吧！",
            ["ContentFR"] = "Ouaaah ! Un monstre géant fonce sur nous en crachant un brouillard toxique !\
Si on le laisse faire, il va corrompre tout le Sérum dans le Poste d’Alchimie ! Vite, élimine-le !",
            ["DialogueId"] = 60230401,
            ["Duration"] = 4,
            ["GUID"] = "969104B1",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/602304/969104B1",
            ["bTurnOffVoice"] = true,
            },
        [60240101] = {
            ["Content"] = "比赛开始了，启动计数装置，在它们周围淘汰别的参赛队伍吧！",
            ["DialogueId"] = 60240101,
            ["Duration"] = 4,
            ["GUID"] = "96A20000",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/602401/96A20000",
            },
        [60240201] = {
            ["Content"] = "打开计数装置喽，在装置周围狠狠地淘汰他们吧！",
            ["DialogueId"] = 60240201,
            ["Duration"] = 4,
            ["GUID"] = "96A20004",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/602402/96A20004",
            },
        [60240301] = {
            ["Content"] = "计数装置怎么又关掉啦，快去重新启动一下吧。",
            ["DialogueId"] = 60240301,
            ["Duration"] = 4,
            ["GUID"] = "96A20008",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/602403/96A20008",
            },
        [60240401] = {
            ["Content"] = "好耶！淘汰了这么多人总算凑够这台计数装置的要求了，去下一台装置吧。",
            ["DialogueId"] = 60240401,
            ["Duration"] = 4,
            ["GUID"] = "96A2000C",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/602404/96A2000C",
            },
        [60240501] = {
            ["Content"] = "第一场比赛轻轻松松嘛，去下个赛场，拿下固定载具的控制权吧~",
            ["DialogueId"] = 60240501,
            ["Duration"] = 3,
            ["GUID"] = "96A20010",
            ["NextDialogue"] = 60240502,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/602405/96A20010",
            },
        [60240502] = {
            ["Content"] = "找到第一台固定载具啦，赶紧激活它吧。",
            ["DialogueId"] = 60240502,
            ["Duration"] = 4,
            ["GUID"] = "96A20014",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/602405/96A20014",
            },
        [60240601] = {
            ["Content"] = "其他参赛选手靠过来啦，快点淘汰他们，保护好固定载具吧。",
            ["DialogueId"] = 60240601,
            ["Duration"] = 4,
            ["GUID"] = "96A20018",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/602406/96A20018",
            },
        [60240701] = {
            ["Content"] = "保护成功！赶在其他人之前激活下一个固定载具吧。",
            ["DialogueId"] = 60240701,
            ["Duration"] = 4,
            ["GUID"] = "96A2001C",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/602407/96A2001C",
            },
        [60240801] = {
            ["Content"] = "第二场比赛也赢啦！去最后一场比赛的起点吧。",
            ["DialogueId"] = 60240801,
            ["Duration"] = 3,
            ["GUID"] = "96A20020",
            ["NextDialogue"] = 60240802,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/602408/96A20020",
            },
        [60240802] = {
            ["Content"] = "移动载具好像塞在很里面的位置呢，把它找出来再送到终点就算我们赢喽！",
            ["DialogueId"] = 60240802,
            ["Duration"] = 4,
            ["GUID"] = "96A20024",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/602408/96A20024",
            },
        [60240901] = {
            ["Content"] = "开始向终点移动。",
            ["DialogueId"] = 60240901,
            ["Duration"] = 4,
            ["GUID"] = "96A20028",
            ["SpeakNpcId"] = 930008,
            ["VoiceName"] = "voice/$Locale$/story/0/602409/96A20028",
            },
        [60241001] = {
            ["Content"] = "维修中，停止移动。",
            ["DialogueId"] = 60241001,
            ["Duration"] = 4,
            ["GUID"] = "96A2002C",
            ["SpeakNpcId"] = 930008,
            ["VoiceName"] = "voice/$Locale$/story/0/602410/96A2002C",
            },
        [60241101] = {
            ["Content"] = "检测不到己方参赛选手，停止移动。",
            ["DialogueId"] = 60241101,
            ["Duration"] = 4,
            ["GUID"] = "96A20030",
            ["SpeakNpcId"] = 930008,
            ["VoiceName"] = "voice/$Locale$/story/0/602411/96A20030",
            },
        [60241201] = {
            ["Content"] = "比赛结——束！！！！！本届大赛的冠军已经诞生，让我们一起恭喜他们！！！",
            ["DialogueId"] = 60241201,
            ["Duration"] = 3,
            ["GUID"] = "96A20034",
            ["NextDialogue"] = 60241202,
            ["SpeakNpcId"] = 930009,
            ["VoiceName"] = "voice/$Locale$/story/0/602412/96A20034",
            },
        [60241202] = {
            ["Content"] = "宝箱开啦，好耶！是我们赢喽~",
            ["DialogueId"] = 60241202,
            ["Duration"] = 4,
            ["GUID"] = "96A20038",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/602412/96A20038",
            },
        [60241301] = {
            ["Content"] = "吼哦哦哦！！！",
            ["DialogueId"] = 60241301,
            ["Duration"] = 4,
            ["GUID"] = "96A2003C",
            ["SpeakNpcId"] = 930006,
            ["VoiceName"] = "voice/$Locale$/story/0/602413/96A2003C",
            },
        [60241401] = {
            ["Content"] = "何等混沌亵渎的赛场，以神之名，予他们以制裁。",
            ["DialogueId"] = 60241401,
            ["Duration"] = 4,
            ["GUID"] = "96A20040",
            ["SpeakNpcId"] = 930015,
            ["VoiceName"] = "voice/$Locale$/story/0/602414/96A20040",
            },
        [60241501] = {
            ["Content"] = "吼嗷嗷嗷！！！",
            ["DialogueId"] = 60241501,
            ["Duration"] = 4,
            ["GUID"] = "96A20044",
            ["SpeakNpcId"] = 930007,
            ["VoiceName"] = "voice/$Locale$/story/0/602415/96A20044",
            },
        [60300101] = {
            ["Content"] = "嘘……我好像听到了魔灵的声音！我们快去找一找，赶紧救它出来吧！",
            ["ContentFR"] = "Chut... J’ai cru entendre la voix d’un Géniemon ! Allons vite le chercher, il faut le sauver !",
            ["DialogueId"] = 60300101,
            ["Duration"] = 4,
            ["GUID"] = "96F47952",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/0/603001/96F47952",
            ["bTurnOffVoice"] = true,
            },
        [60800101] = {
