            ["GUID"] = "B1C10B9C",
            ["NextDialogue"] = 71005210,
            ["SpeakNpcId"] = 800006,
            },
        [71005210] = {
            ["Content"] = "你看我左手的幸福硬币和右手的铜币有什么不一样吗？",
            ["ContentFR"] = "Tu vois une différence entre la pièce porte-bonheur dans ma main gauche et la pièce dans ma main droite ?",
