            ["bForbidSkipOptions"] = true,
            },
        [71007204] = {
            ["Content"] = "万分感谢，我就在这儿等你。",
            ["ContentFR"] = "Un grand merci. Je vous attends ici.",
            ["DialogueId"] = 71007204,
            ["GUID"] = "B1C25368",
