            },
        [72000202] = {
            ["Content"] = "咿呀，被你找到了。",
            ["ContentFR"] = "<I>Yiiiip !</> Tu m’as trouvé.",
            ["DialogueId"] = 72000202,
            ["FacialId"] = {
                [1] = "820000:PetPan_Common",
                },
            ["GUID"] = "B43EB524",
            ["NextDialogue"] = 72000203,
            ["SpeakNpcId"] = 820000,
            },
        [72000203] = {
            ["Content"] = "树木的臂弯很温暖，但是不能一直待在这里呢。",
            ["ContentFR"] = "Les arbres m’enlacent avec chaleur... mais je ne peux pas rester blotti là éternellement.",
            ["DialogueId"] = 72000203,
