            ["bAllowClickSkipScript"] = false,
            },
        [72000302] = {
            ["Content"] = "有人把灯点亮了。",
            ["ContentFR"] = "Oh, quelqu’un a rallumé la lampe.",
            ["DialogueId"] = 72000302,
            ["FacialId"] = {
                [1] = "820000:PetPan_Common",
                },
            ["GUID"] = "B43EC58C",
            ["NextDialogue"] = 72000303,
            ["SpeakNpcId"] = 820000,
            },
        [72000303] = {
            ["Content"] = "你说，太阳是不是也是谁点亮的灯芯呢？",
            ["ContentFR"] = "Dis... et si le soleil n’était lui aussi qu’une mèche qu’on a enflammée ?",
            ["DialogueId"] = 72000303,
            ["FacialId"] = {
                [1] = "820000:PetPan_Common",
                },
            ["GUID"] = "B43EC5B6",
