            ["GUID"] = "B43ED5CA",
            ["NextDialogue"] = 72000402,
            ["Scripts"] = "PlayAnimation{Sync{true},Duration{1},ActorId{820000},AnimationId{\"Wuyou_Born\"}}",
            ["bAllowClickSkipScript"] = false,
            },
        [72000402] = {
            ["Content"] = "只要我像风那样飘来飘去，就可以和风做朋友了吧。",
            ["ContentFR"] = "Si je flotte comme le vent... alors peut-être qu’il deviendra mon ami.",
            ["DialogueId"] = 72000402,
            ["FacialId"] = {
                [1] = "820000:PetPan_Common",
                },
            ["GUID"] = "B43ED5F4",
            ["NextDialogue"] = 72000403,
            ["Scripts"] = "PlayAnimation{ActorId{820000},AnimationId{\"Wuyou_Disagree\"}}",
            ["SpeakNpcId"] = 820000,
            ["bAllowClickSkipScript"] = false,
            },
        [72000403] = {
            ["Content"] = "你也想要做风的朋友吗？",
            ["ContentFR"] = "Et toi, veux-tu aussi être {性别:l’ami|l’amie} du vent ?",
            ["DialogueId"] = 72000403,
