            ["Scripts"] = "PlayAnimation{Sync{true},Duration{1},ActorId{820000},AnimationId{\"Wuyou_Born\"}}",
            ["bAllowClickSkipScript"] = false,
            },
        [72000502] = {
            ["Content"] = "谢谢你，草丛一样的人类……我被卡在这个圆圆的冰冰的桶里好久了……",
            ["ContentFR"] = "Merci, humain des buissons... J’étais coincé dans ce seau rond et glacé depuis si longtemps...",
            ["DialogueId"] = 72000502,
            ["FacialId"] = {
                [1] = "820000:PetPan_Dizzy",
                },
            ["GUID"] = "B43EE65C",
            ["NextDialogue"] = 72000503,
            ["SpeakNpcId"] = 820000,
            },
        [72000503] = {
            ["Content"] = "唔，草丛不见了，但还是谢谢你，雪一样的人类。",
            ["ContentFR"] = "Oh ? Plus de buissons... Mais merci quand même, humain de neige.",
            ["DialogueId"] = 72000503,
            ["FacialId"] = {
                [1] = "820000:PetPan_Common",
                },
            ["GUID"] = "B43EE686",
