            ["Scripts"] = "PlayAnimation{Sync{true},Duration{1},ActorId{820000},AnimationId{\"Wuyou_Born\"}}",
            ["bAllowClickSkipScript"] = false,
            },
        [72000602] = {
            ["Content"] = "旋转……旋转……头有点晕。",
            ["ContentFR"] = "Tourne... tourne... ouh, j’ai le tournis...",
            ["DialogueId"] = 72000602,
            ["FacialId"] = {
                [1] = "820000:PetPan_Dizzy",
                },
            ["GUID"] = "B43EF6C4",
            ["NextDialogue"] = 72000603,
            ["Scripts"] = "PlayAnimation{ActorId{820000},AnimationId{\"Wuyou_Agree\"}}",
            ["SpeakNpcId"] = 820000,
            ["bAllowClickSkipScript"] = false,
            },
        [72000603] = {
            ["Content"] = "这个东西好危险，都是月髓，但是又转个不停，是陷阱吗？",
            ["ContentFR"] = "Ce machin est dangereux ! Rempli de Phoxichor, et pourtant il ne cesse de tourner. Serait-ce... un piège ?",
            ["DialogueId"] = 72000603,
            ["FacialId"] = {
                [1] = "820000:PetPan_Cry",
