            ["Scripts"] = "PlayAnimation{Sync{true},Duration{1},ActorId{820000},AnimationId{\"Wuyou_Born\"}}",
            ["bAllowClickSkipScript"] = false,
            },
        [72000702] = {
            ["Content"] = "一群人跑，一群人追……",
            ["ContentFR"] = "Un groupe fuit, un autre poursuit...",
            ["DialogueId"] = 72000702,
            ["FacialId"] = {
                [1] = "820000:PetPan_Speechless",
                },
            ["GUID"] = "B43F072C",
            ["NextDialogue"] = 72000703,
            ["SpeakNpcId"] = 820000,
            },
        [72000703] = {
            ["Content"] = "人类也喜欢玩捉迷藏吗？但是好像你们玩得并不是很开心……",
            ["ContentFR"] = "Les humains aiment aussi jouer à cache-cache ? Mais vous... vous n’avez pas l’air de vous amuser.",
            ["DialogueId"] = 72000703,
