            },
        [72001002] = {
            ["Content"] = "墙说，它能挡住它想挡住的东西。",
            ["ContentFR"] = "Le mur dit qu’il repousse ce qu’il veut repousser.",
            ["DialogueId"] = 72001002,
            ["FacialId"] = {
                [1] = "820000:PetPan_Common",
                },
            ["GUID"] = "B43F3864",
            ["NextDialogue"] = 72001003,
            ["SpeakNpcId"] = 820000,
            },
        [72001003] = {
            ["Content"] = "但是如果它不想挡住的东西，都会放进城里！",
            ["ContentFR"] = "Mais s’il t’apprécie... il te laisse entrer.",
            ["DialogueId"] = 72001003,
            ["FacialId"] = {
                [1] = "820000:PetPan_Common",
                },
            ["GUID"] = "B43F388E",
            ["NextDialogue"] = 72001004,
            ["SpeakNpcId"] = 820000,
            },
