            ["GUID"] = "B43F48A2",
            ["NextDialogue"] = 72001102,
            ["Scripts"] = "PlayAnimation{Sync{true},Duration{1},ActorId{820000},AnimationId{\"Wuyou_Born\"}}",
            ["bAllowClickSkipScript"] = false,
            },
        [72001102] = {
            ["Content"] = "我以为这个箱子是你好箱，劝他动起来劝了好久。",
            ["ContentFR"] = "Je croyais que ce coffre était un Poto Carta. Je lui ai demandé si longtemps de bouger...",
            ["DialogueId"] = 72001102,
            ["FacialId"] = {
                [1] = "820000:PetPan_Wink",
                },
            ["GUID"] = "B43F48CC",
            ["NextDialogue"] = 72001103,
            ["SpeakNpcId"] = 820000,
            },
        [72001103] = {
            ["Content"] = "原来不是，看来，我应该早一点踢这个箱子一脚。",
            ["ContentFR"] = "Mais non... J’aurais dû lui donner un petit coup de pied plus tôt.",
            ["DialogueId"] = 72001103,
            ["FacialId"] = {
                [1] = "820000:PetPan_Common",
                },
            ["GUID"] = "B43F48F6",
            ["NextDialogue"] = 72001104,
            ["SpeakNpcId"] = 820000,
            },
        [72001104] = {
            ["DialogueId"] = 72001104,
            ["DialoguePanelType"] = "AllHide",
