            ["bAllowClickSkipScript"] = false,
            },
        [72001201] = {
            ["Camera"] = "196.204834,-2.952148,87.243896,0.0,-7.999989,179.200043,35.0,100000.0,false,DoNotOverride,2.8",
            ["DialogueId"] = 72001201,
            ["DialoguePanelType"] = "AllHide",
            ["FacialId"] = {
                [1] = "820000:PetPan_Common",
                },
            ["GUID"] = "B43F590A",
            ["NextDialogue"] = 72001202,
            ["Scripts"] = "PlayAnimation{Sync{true},Duration{1},ActorId{820000},AnimationId{\"Wuyou_Born\"}}",
            ["bAllowClickSkipScript"] = false,
            },
        [72001202] = {
            ["Content"] = "这棵树好像累了，躺在地上休息。",
            ["ContentFR"] = "Cet arbre a l’air fatigué... Il s’est couché pour se reposer.",
            ["DialogueId"] = 72001202,
            ["FacialId"] = {
                [1] = "820000:PetPan_Common",
                },
            ["GUID"] = "B43F5934",
            ["NextDialogue"] = 72001203,
            ["SpeakNpcId"] = 820000,
            },
        [72001203] = {
            ["Content"] = "所以那些落到地上的雪，是不是也飞累了，想要躺下来呢？",
            ["ContentFR"] = "Alors... la neige tombée au sol... peut-être qu’elle aussi a fini par se lasser de voler, et s’est posée pour se reposer ?",
            ["DialogueId"] = 72001203,
            ["FacialId"] = {
                [1] = "820000:PetPan_Common",
                },
            ["GUID"] = "B43F595E",
            ["NextDialogue"] = 72001204,
            ["SpeakNpcId"] = 820000,
            },
        [72001204] = {
            ["DialogueId"] = 72001204,
            ["DialoguePanelType"] = "AllHide",
            ["Duration"] = 0.63,
            ["FacialId"] = {
                [1] = "820000:PetPan_Common",
                },
            ["GUID"] = "B43F5988",
            ["Scripts"] = "PlayAnimation{ActorId{820000},AnimationId{\"Wuyou_Disappear\"}}",
            ["bAllowClickSkipScript"] = false,
            },
        [72001301] = {
            ["Camera"] = "196.204834,-2.952148,87.243896,0.0,-7.999989,179.200043,35.0,100000.0,false,DoNotOverride,2.8",
            ["DialogueId"] = 72001301,
            ["DialoguePanelType"] = "AllHide",
            ["FacialId"] = {
                [1] = "820000:PetPan_Common",
                },
            ["GUID"] = "B43F6972",
            ["NextDialogue"] = 72001302,
            ["Scripts"] = "PlayAnimation{Sync{true},Duration{1},ActorId{820000},AnimationId{\"Wuyou_Born\"}}",
            ["bAllowClickSkipScript"] = false,
            },
        [72001302] = {
            ["Content"] = "这里很暖和哦，你也可以坐在这里。",
            ["ContentFR"] = "Ici, il fait si bon... Tu peux t’asseoir avec moi.",
            ["DialogueId"] = 72001302,
            ["FacialId"] = {
                [1] = "820000:PetPan_Common",
                },
            ["GUID"] = "B43F699C",
            ["NextDialogue"] = 72001303,
            ["SpeakNpcId"] = 820000,
            },
        [72001303] = {
            ["Content"] = "但是不可以坐太久，我也有其他朋友会冷。",
            ["ContentFR"] = "Mais pas trop longtemps, mes autres amis risqueraient d’avoir froid.",
            ["DialogueId"] = 72001303,
            ["FacialId"] = {
                [1] = "820000:PetPan_Common",
                },
            ["GUID"] = "B43F69C6",
            ["NextDialogue"] = 72001304,
            ["SpeakNpcId"] = 820000,
            },
        [72001304] = {
            ["DialogueId"] = 72001304,
            ["DialoguePanelType"] = "AllHide",
            ["Duration"] = 0.63,
            ["FacialId"] = {
                [1] = "820000:PetPan_Common",
                },
            ["GUID"] = "B43F69F0",
            ["Scripts"] = "PlayAnimation{ActorId{820000},AnimationId{\"Wuyou_Disappear\"}}",
            ["bAllowClickSkipScript"] = false,
            },
        [72001401] = {
            ["Camera"] = "196.204834,-2.952148,87.243896,0.0,-7.999989,179.200043,35.0,100000.0,false,DoNotOverride,2.8",
            ["DialogueId"] = 72001401,
            ["DialoguePanelType"] = "AllHide",
            ["FacialId"] = {
                [1] = "820000:PetPan_Common",
                },
            ["GUID"] = "B43F79DA",
            ["NextDialogue"] = 72001402,
            ["Scripts"] = "PlayAnimation{Sync{true},Duration{1},ActorId{820000},AnimationId{\"Wuyou_Born\"}}",
            ["bAllowClickSkipScript"] = false,
            },
        [72001402] = {
            ["Content"] = "此路不通，嗯……",
            ["ContentFR"] = "Un chemin sans issue... hmm...",
            ["DialogueId"] = 72001402,
            ["FacialId"] = {
                [1] = "820000:PetPan_Common",
                },
            ["GUID"] = "B43F7A04",
            ["NextDialogue"] = 72001403,
            ["SpeakNpcId"] = 820000,
            },
        [72001403] = {
            ["Content"] = "或者说，我想说的是，我想独处一段时间。你要和我一起独处吗？",
            ["ContentFR"] = "Ou peut-être voulais-je dire... que j’aimerais rester seul un moment. Veux-tu... rester seul avec moi ?",
            ["DialogueId"] = 72001403,
            ["FacialId"] = {
                [1] = "820000:PetPan_Common",
                },
            ["GUID"] = "B43F7A2E",
            ["NextDialogue"] = 72001404,
            ["SpeakNpcId"] = 820000,
            },
        [72001404] = {
            ["Content"] = "但这样是不是不能叫作独处了。",
            ["ContentFR"] = "Mais alors... pourrait-on encore appeler cela être seul ?",
            ["DialogueId"] = 72001404,
            ["FacialId"] = {
                [1] = "820000:PetPan_Common",
                },
            ["GUID"] = "B43F7A58",
            ["NextDialogue"] = 72001405,
            ["Scripts"] = "PlayAnimation{ActorId{820000},AnimationId{\"Wuyou_Disagree\"}}",
            ["SpeakNpcId"] = 820000,
            ["bAllowClickSkipScript"] = false,
            },
        [72001405] = {
            ["DialogueId"] = 72001405,
            ["DialoguePanelType"] = "AllHide",
            ["Duration"] = 0.63,
            ["FacialId"] = {
                [1] = "820000:PetPan_Common",
                },
            ["GUID"] = "B43F7A82",
            ["Scripts"] = "PlayAnimation{ActorId{820000},AnimationId{\"Wuyou_Disappear\"}}",
            ["bAllowClickSkipScript"] = false,
            },
        [72001501] = {
            ["Camera"] = "196.204834,-2.952148,87.243896,0.0,-7.999989,179.200043,35.0,100000.0,false,DoNotOverride,2.8",
            ["DialogueId"] = 72001501,
            ["DialoguePanelType"] = "AllHide",
            ["FacialId"] = {
                [1] = "820000:PetPan_Common",
