            ["GUID"] = "B43F8A42",
            ["NextDialogue"] = 72001502,
            ["Scripts"] = "PlayAnimation{Sync{true},Duration{1},ActorId{820000},AnimationId{\"Wuyou_Born\"}}",
            ["bAllowClickSkipScript"] = false,
            },
        [72001502] = {
            ["Content"] = "这里的房子看起来都很疲惫呢，皮肤上都斑斑驳驳。",
            ["ContentFR"] = "Ces maisons ont l’air si fatiguées... Leur peau est toute abîmée, tachetée...",
            ["DialogueId"] = 72001502,
            ["FacialId"] = {
                [1] = "820000:PetPan_Speechless",
                },
            ["GUID"] = "B43F8A6C",
            ["NextDialogue"] = 72001503,
            ["SpeakNpcId"] = 820000,
            },
        [72001503] = {
            ["Content"] = "真希望他们能够好起来。",
            ["ContentFR"] = "Comme j’aimerais qu’elles guérissent...",
            ["DialogueId"] = 72001503,
            ["FacialId"] = {
                [1] = "820000:PetPan_Common",
                },
            ["GUID"] = "B43F8A96",
            ["NextDialogue"] = 72001504,
            ["SpeakNpcId"] = 820000,
