            ["GUID"] = "B43F8AC0",
            ["Scripts"] = "PlayAnimation{ActorId{820000},AnimationId{\"Wuyou_Disappear\"}}",
            ["bAllowClickSkipScript"] = false,
            },
        [72001601] = {
            ["Camera"] = "196.204834,-2.952148,87.243896,0.0,-7.999989,179.200043,35.0,100000.0,false,DoNotOverride,2.8",
            ["DialogueId"] = 72001601,
            ["DialoguePanelType"] = "AllHide",
            ["FacialId"] = {
                [1] = "820000:PetPan_Common",
                },
            ["GUID"] = "B43F9AAA",
            ["NextDialogue"] = 72001602,
            ["Scripts"] = "PlayAnimation{Sync{true},Duration{1},ActorId{820000},AnimationId{\"Wuyou_Born\"}}",
            ["bAllowClickSkipScript"] = false,
            },
        [72001602] = {
            ["Content"] = "这座山好高，好亮！站在山顶的我，厉害！",
            ["ContentFR"] = "Cette montagne est si haute ! Si brillante ! Et moi, tout en haut ! Je suis incroyable !",
            ["DialogueId"] = 72001602,
            ["FacialId"] = {
                [1] = "820000:PetPan_Common",
                },
            ["GUID"] = "B43F9AD4",
            ["NextDialogue"] = 72001603,
            ["SpeakNpcId"] = 820000,
            },
        [72001603] = {
            ["Content"] = "咿呀？这里不是山？怎么会？",
            ["ContentFR"] = "<I>Yiiiip ! </>Ce n’est pas une montagne ? Mais alors... ?",
            ["DialogueId"] = 72001603,
            ["FacialId"] = {
                [1] = "820000:PetPan_Speechless",
                },
            ["GUID"] = "B43F9AFE",
            ["NextDialogue"] = 72001604,
            ["SpeakNpcId"] = 820000,
            },
        [72001604] = {
            ["Content"] = "山不就是高高的，尖尖的地方，这里就是山！",
            ["ContentFR"] = "C’est grand, c’est pointu... donc c’est une montagne !",
            ["DialogueId"] = 72001604,
            ["FacialId"] = {
                [1] = "820000:PetPan_Common",
                },
            ["GUID"] = "B43F9B28",
            ["NextDialogue"] = 72001605,
            ["SpeakNpcId"] = 820000,
            },
        [72001605] = {
            ["DialogueId"] = 72001605,
            ["DialoguePanelType"] = "AllHide",
            ["Duration"] = 0.63,
            ["FacialId"] = {
                [1] = "820000:PetPan_Common",
                },
            ["GUID"] = "B43F9B52",
            ["Scripts"] = "PlayAnimation{ActorId{820000},AnimationId{\"Wuyou_Disappear\"}}",
            ["bAllowClickSkipScript"] = false,
            },
        [72001701] = {
            ["Camera"] = "196.204834,-2.952148,87.243896,0.0,-7.999989,179.200043,35.0,100000.0,false,DoNotOverride,2.8",
            ["DialogueId"] = 72001701,
            ["DialoguePanelType"] = "AllHide",
            ["FacialId"] = {
                [1] = "820000:PetPan_Common",
                },
            ["GUID"] = "B43FAB12",
            ["NextDialogue"] = 72001702,
            ["Scripts"] = "PlayAnimation{Sync{true},Duration{1},ActorId{820000},AnimationId{\"Wuyou_Born\"}}",
            ["bAllowClickSkipScript"] = false,
            },
        [72001702] = {
            ["Content"] = "如果能看清脚下的路，你是不是就不怕秽兽了？",
            ["ContentFR"] = "Si tu vois bien le chemin sous tes pieds... tu n’auras plus peur des Souillés, pas vrai ?",
            ["DialogueId"] = 72001702,
            ["FacialId"] = {
                [1] = "820000:PetPan_Common",
                },
            ["GUID"] = "B43FAB3C",
            ["NextDialogue"] = 72001703,
            ["SpeakNpcId"] = 820000,
            },
        [72001703] = {
            ["Content"] = "那么，这里亮起来了哦。",
            ["ContentFR"] = "Tadaa ! Voilà, tout est illuminé.",
            ["DialogueId"] = 72001703,
            ["FacialId"] = {
                [1] = "820000:PetPan_Common",
                },
            ["GUID"] = "B43FAB66",
            ["NextDialogue"] = 72001704,
            ["Scripts"] = "PlayAnimation{ActorId{820000},AnimationId{\"Wuyou_Agree\"}}",
            ["SpeakNpcId"] = 820000,
            ["bAllowClickSkipScript"] = false,
            },
        [72001704] = {
            ["DialogueId"] = 72001704,
            ["DialoguePanelType"] = "AllHide",
            ["Duration"] = 0.63,
            ["FacialId"] = {
                [1] = "820000:PetPan_Common",
