            ["GUID"] = "B43FAB90",
            ["Scripts"] = "PlayAnimation{ActorId{820000},AnimationId{\"Wuyou_Disappear\"}}",
            ["bAllowClickSkipScript"] = false,
            },
        [72001801] = {
            ["Camera"] = "196.204834,-2.952148,87.243896,0.0,-7.999989,179.200043,35.0,100000.0,false,DoNotOverride,2.8",
            ["DialogueId"] = 72001801,
            ["DialoguePanelType"] = "AllHide",
            ["FacialId"] = {
                [1] = "820000:PetPan_Common",
                },
            ["GUID"] = "B43FBB7A",
            ["NextDialogue"] = 72001802,
            ["Scripts"] = "PlayAnimation{Sync{true},Duration{1},ActorId{820000},AnimationId{\"Wuyou_Born\"}}",
            ["bAllowClickSkipScript"] = false,
            },
        [72001802] = {
            ["Content"] = "这里有许多人的气息，但是他们都不见了。",
            ["ContentFR"] = "Il y a ici tant d’odeurs humaines ici... et pourtant, pas une seule présence.",
            ["DialogueId"] = 72001802,
            ["FacialId"] = {
                [1] = "820000:PetPan_Common",
                },
            ["GUID"] = "B43FBBA4",
            ["NextDialogue"] = 72001803,
            ["SpeakNpcId"] = 820000,
            },
        [72001803] = {
            ["Content"] = "到底去了哪里呢？",
            ["ContentFR"] = "Où sont-ils donc passés ?",
            ["DialogueId"] = 72001803,
            ["FacialId"] = {
                [1] = "820000:PetPan_Common",
                },
            ["GUID"] = "B43FBBCE",
            ["NextDialogue"] = 72001804,
            ["SpeakNpcId"] = 820000,
            },
        [72001804] = {
            ["DialogueId"] = 72001804,
            ["DialoguePanelType"] = "AllHide",
            ["Duration"] = 0.63,
            ["FacialId"] = {
                [1] = "820000:PetPan_Common",
                },
            ["GUID"] = "B43FBBF8",
            ["Scripts"] = "PlayAnimation{ActorId{820000},AnimationId{\"Wuyou_Disappear\"}}",
            ["bAllowClickSkipScript"] = false,
            },
        [72001901] = {
            ["Camera"] = "196.204834,-2.952148,87.243896,0.0,-7.999989,179.200043,35.0,100000.0,false,DoNotOverride,2.8",
            ["DialogueId"] = 72001901,
            ["DialoguePanelType"] = "AllHide",
            ["FacialId"] = {
                [1] = "820000:PetPan_Common",
                },
            ["GUID"] = "B43FCBE2",
            ["NextDialogue"] = 72001902,
            ["Scripts"] = "PlayAnimation{Sync{true},Duration{1},ActorId{820000},AnimationId{\"Wuyou_Born\"}}",
            ["bAllowClickSkipScript"] = false,
            },
        [72001902] = {
            ["Content"] = "哼哼，大家都坐在一起，只有它跑开了。",
            ["ContentFR"] = "Hmpf ! Tout le monde est assis côte à côte... sauf celui qui s’est enfui !",
            ["DialogueId"] = 72001902,
            ["FacialId"] = {
                [1] = "820000:PetPan_Common",
                },
            ["GUID"] = "B43FCC0C",
            ["NextDialogue"] = 72001903,
            ["SpeakNpcId"] = 820000,
            },
        [72001903] = {
            ["Content"] = "那么，现在，我宣布，箱箱大会开始！",
            ["ContentFR"] = "Alors... que la grande fête des Cartas commence !",
            ["DialogueId"] = 72001903,
            ["FacialId"] = {
                [1] = "820000:PetPan_Common",
                },
            ["GUID"] = "B43FCC36",
            ["NextDialogue"] = 72001904,
            ["Scripts"] = "PlayAnimation{ActorId{820000},AnimationId{\"Wuyou_Agree\"}}",
            ["SpeakNpcId"] = 820000,
            ["bAllowClickSkipScript"] = false,
            },
        [72001904] = {
            ["DialogueId"] = 72001904,
            ["DialoguePanelType"] = "AllHide",
            ["Duration"] = 0.63,
            ["FacialId"] = {
                [1] = "820000:PetPan_Common",
                },
            ["GUID"] = "B43FCC60",
            ["Scripts"] = "PlayAnimation{ActorId{820000},AnimationId{\"Wuyou_Disappear\"}}",
            ["bAllowClickSkipScript"] = false,
            },
        [72002201] = {
            ["Camera"] = "196.204834,-2.952148,87.243896,0.0,-7.999989,179.200043,35.0,100000.0,false,DoNotOverride,2.8",
            ["DialogueId"] = 72002201,
            ["DialoguePanelType"] = "AllHide",
            ["FacialId"] = {
                [1] = "820000:PetPan_Common",
                },
            ["GUID"] = "B43FFD1A",
            ["NextDialogue"] = 72002202,
            ["Scripts"] = "PlayAnimation{Sync{true},Duration{1},ActorId{820000},AnimationId{\"Wuyou_Born\"}}",
            ["bAllowClickSkipScript"] = false,
            },
        [72002202] = {
            ["Content"] = "我想要和路上的车比一比谁跑得快。",
            ["ContentFR"] = "J’aimerais faire la course avec les voitures de la route.",
            ["DialogueId"] = 72002202,
            ["FacialId"] = {
                [1] = "820000:PetPan_Common",
                },
            ["GUID"] = "B43FFD44",
            ["NextDialogue"] = 72002203,
            ["SpeakNpcId"] = 820000,
            },
        [72002203] = {
            ["Content"] = "但是他们跑得太快的话，会滑倒，真担心他们。",
            ["ContentFR"] = "Mais si elles courent trop vite... elles pourraient glisser. Et j’en serais si triste pour elles...",
            ["DialogueId"] = 72002203,
            ["FacialId"] = {
                [1] = "820000:PetPan_Wink",
                },
            ["GUID"] = "B43FFD6E",
