            ["NextDialogue"] = 72003503,
            ["SpeakNpcId"] = 820000,
            },
        [72003503] = {
            ["Content"] = "他好凶，讨厌他，你也不要和他做朋友。",
            ["ContentFR"] = "Elle est méchante... je la déteste. Toi non plus, ne deviens pas son ami.",
