            },
        [72003602] = {
            ["Content"] = "这里，有一点点外面的味道，又快乐，又伟大。",
            ["ContentFR"] = "Ici... ça sent un peu comme dehors. Ça sent la joie, la grandeur.",
            ["DialogueId"] = 72003602,
            ["FacialId"] = {
                [1] = "820000:PetPan_Common",
                },
            ["GUID"] = "B440E2F4",
            ["NextDialogue"] = 72003603,
            ["SpeakNpcId"] = 820000,
            },
        [72003603] = {
            ["Content"] = "不像其他地方，都是争吵和打架的味道。",
            ["ContentFR"] = "Rien à voir avec ces lieux saturés de cris et de bagarres.",
            ["DialogueId"] = 72003603,
