            },
        [72100102] = {
            ["Content"] = "浮名洗尽始见心，风月不染本来明。",
            ["ContentFR"] = "Quand les faux-semblants s’effacent, le cœur véritable apparaît.\
Préservé de la poussière du monde, il demeure clair, tel qu’à l’origine.",
            ["DialogueId"] = 72100102,
            ["FacialId"] = {
                [1] = "830001:PetPan_Common",
                },
            ["GUID"] = "B47EBAFC",
            ["NextDialogue"] = 72100103,
            ["SpeakNpcId"] = 830001,
            },
        [72100103] = {
            ["Content"] = "远道而来的朋友，你拂开繁花，可曾窥见自己明朗的本心呢？",
            ["ContentFR"] = "{性别:Ami venu|Amie venue} de loin, en écartant les fleurs écloses, as-tu entrevu la limpidité de ton propre cœur ?",
            ["DialogueId"] = 72100103,
            ["FacialId"] = {
                [1] = "830001:PetPan_Common",
                },
            ["GUID"] = "B47EBB26",
