        [72100202] = {
            ["Content"] = "好似做了个久远的美梦……",
            ["ContentFR"] = "On dirait que j’ai fait un rêve ancien... Un très beau rêve.",
            ["DialogueId"] = 72100202,
            ["FacialId"] = {
                [1] = "830001:PetPan_Common",
                },
            ["GUID"] = "B47ECB64",
            ["NextDialogue"] = 72100203,
            ["SpeakNpcId"] = 830001,
            },
        [72100203] = {
            ["Content"] = "梦见孩提时，娘亲牵着我的手去渡口买糖人。",
            ["ContentFR"] = "Je rêvais de mon enfance... Ma mère me tenait la main, nous allions au débarcadère acheter des figurines en sucre.",
            ["DialogueId"] = 72100203,
            ["FacialId"] = {
                [1] = "830001:PetPan_Common",
                },
            ["GUID"] = "B47ECB8E",
