            ["Scripts"] = "PlayAnimation{Sync{true},Duration{1},ActorId{830001},AnimationId{\"Wuyou_Born\"}}",
            },
        [72100402] = {
            ["Content"] = "空中飘来的味道是什么香料，吿苍，还是春一品？",
            ["ContentFR"] = "Quel est ce parfum qui flotte dans l’air ? Du Lys céleste... ou peut-être du Printemps d’Excellence ?",
            ["DialogueId"] = 72100402,
            ["FacialId"] = {
                [1] = "830001:PetPan_Common",
                },
            ["GUID"] = "B47EEC34",
            ["NextDialogue"] = 72100403,
            ["SpeakNpcId"] = 830001,
            },
        [72100403] = {
            ["Content"] = "不如我自制的香方，可惜，我再也做不出了。",
            ["ContentFR"] = "Ce n’est pas aussi bon que ma propre composition... Quel dommage... Je ne pourrai plus jamais la recréer.",
            ["DialogueId"] = 72100403,
