            ["Scripts"] = "PlayAnimation{Sync{true},Duration{1},ActorId{830001},AnimationId{\"Wuyou_Born\"}}",
            },
        [72100502] = {
            ["Content"] = "我儿梁卿！你可安好？",
            ["ContentFR"] = "Liang Qing, mon enfant ! Te portes-tu bien ?",
            ["DialogueId"] = 72100502,
            ["FacialId"] = {
                [1] = "830001:PetPan_Common",
                },
            ["GUID"] = "B47EFC9C",
            ["NextDialogue"] = 72100503,
            ["SpeakNpcId"] = 830001,
            },
        [72100503] = {
            ["Content"] = "咦？不是我儿？你是谁……？",
            ["ContentFR"] = "Hein... ? Ce n’est pas mon enfant ? Alors... qui es-tu ?",
            ["DialogueId"] = 72100503,
