            ["Scripts"] = "PlayAnimation{Sync{true},Duration{1},ActorId{830001},AnimationId{\"Wuyou_Born\"}}",
            },
        [72100902] = {
            ["Content"] = "你喜欢什么颜色？豆绿还是鹤灰？",
            ["ContentFR"] = "Quelle couleur préfères-tu ? Vert fève... ou gris grue ?",
            ["DialogueId"] = 72100902,
            ["FacialId"] = {
                [1] = "830001:PetPan_Common",
                },
            ["GUID"] = "B47F3E3C",
            ["NextDialogue"] = 72100903,
            ["SpeakNpcId"] = 830001,
            },
        [72100903] = {
            ["Content"] = "我啊，我喜欢云水蓝，就像我的身体一样蓝。",
            ["ContentFR"] = "Moi ? J’aime le bleu des nuages et de l’eau. Bleu... comme mon corps.",
