            ["Scripts"] = "PlayAnimation{Sync{true},Duration{1},ActorId{830001},AnimationId{\"Wuyou_Born\"}}",
            },
        [72101002] = {
            ["Content"] = "尘漠铺天盖地，分不清方向，也辨别不了来路……",
            ["ContentFR"] = "La Poussière-corrompue recouvre tout, elle engloutit le ciel. Impossible de distinguer la direction, ni même le chemin parcouru...",
            ["DialogueId"] = 72101002,
            ["FacialId"] = {
                [1] = "830001:PetPan_Common",
                },
            ["GUID"] = "B47F4EA4",
            ["NextDialogue"] = 72101003,
            ["SpeakNpcId"] = 830001,
            },
        [72101003] = {
            ["Content"] = "还好有你为我指明方向。谢谢你，远道而来的朋友。",
            ["ContentFR"] = "Heureusement que tu es là pour me guider. Merci à toi, {性别:ami venu|amie venue} de loin.",
