            },
        [72101302] = {
            ["Content"] = "水流拍击石块，浸润泥土，滋养生命。",
            ["ContentFR"] = "L’eau frappe la pierre, s’infiltre dans la terre, et nourrit toute vie.",
            ["DialogueId"] = 72101302,
            ["FacialId"] = {
                [1] = "830001:PetPan_Common",
                },
            ["GUID"] = "B47F7FDC",
            ["NextDialogue"] = 72101303,
            ["SpeakNpcId"] = 830001,
            },
        [72101303] = {
            ["Content"] = "我听说大家最后都会去一个叫忘川的地方，忘川……也是这样的一条小溪吗？",
            ["ContentFR"] = "On dit qu’à la fin, tout le monde se rend en un lieu appelé le Fleuve de l’Oubli... Dis-moi, est-ce aussi un ruisseau comme celui-ci ?",
            ["DialogueId"] = 72101303,
            ["FacialId"] = {
                [1] = "830001:PetPan_Common",
                },
            ["GUID"] = "B47F8006",
            ["NextDialogue"] = 72101304,
            ["Scripts"] = "PlayAnimation{ActorId{830001},AnimationId{\"Wuyou_Agree\"}}",
            ["SpeakNpcId"] = 830001,
            ["bAllowClickSkipScript"] = false,
            },
