            ["Scripts"] = "PlayAnimation{Sync{true},Duration{1},ActorId{830001},AnimationId{\"Wuyou_Born\"}}",
            },
        [72101602] = {
            ["Content"] = "斜坡！斜坡！我乘着风，踏着花，从坡上呼啸而下。",
            ["ContentFR"] = "La pente ! La pente ! Porté par le vent, foulant les fleurs, je dévale la pente à toute allure !",
            ["DialogueId"] = 72101602,
            ["FacialId"] = {
                [1] = "830001:PetPan_Common",
                },
            ["GUID"] = "B47FB114",
            ["NextDialogue"] = 72101603,
            ["SpeakNpcId"] = 830001,
            },
        [72101603] = {
            ["Content"] = "呜呼！莫要拦我！",
            ["ContentFR"] = "Youhou ! Ne m’arrête pas !",
            ["DialogueId"] = 72101603,
