            },
        [72202302] = {
            ["Content"] = "世间千万事流转，我且遍游自逍遥～",
            ["DialogueId"] = 72202302,
            ["FacialId"] = {
                [1] = "830001:PetPan_Common",
                },
            ["GUID"] = "B4C03A2C",
            ["NextDialogue"] = 72202303,
            ["SpeakNpcId"] = 830001,
            },
        [72202303] = {
            ["Content"] = "瞧瞧！这不是我们的老朋友吗？又见面了，那必不能辜负这场邂逅啊。",
            ["DialogueId"] = 72202303,
            ["FacialId"] = {
                [1] = "830001:PetPan_Common",
                },
            ["GUID"] = "B4C03A56",
            ["NextDialogue"] = 72202304,
            ["Scripts"] = "PlayAnimation{ActorId{830001},AnimationId{\"Wuyou_Agree\"}}",
            ["SpeakNpcId"] = 830001,
            ["bAllowClickSkipScript"] = false,
            },
        [72202304] = {
            ["DialogueId"] = 72202304,
            ["DialoguePanelType"] = "AllHide",
            ["Duration"] = 0.63,
            ["FacialId"] = {
                [1] = "830001:PetPan_Common",
                },
            ["GUID"] = "B4C03A80",
            ["Scripts"] = "PlayAnimation{ActorId{830001},AnimationId{\"Wuyou_Disappear\"}}",
            ["bAllowClickSkipScript"] = false,
            },
        [72999999] = {
            ["DialogueId"] = 72999999,
            ["DialoguePanelType"] = "AllHide",
            ["Duration"] = 1.4,
            ["GUID"] = "B6BF7256",
            },
        [73000201] = {
            ["Content"] = "我改进了这个装置，你继续来试试，帮我测试一下改进效果。花大价钱从艾利西安搞来的东西，我就不信了，这次你还能躲得开。",
            ["ContentFR"] = "J’ai amélioré ce dispositif. Allez, essaie encore, aide-moi à tester ces réglages. Ça m’a coûté une fortune de le faire venir d’Élysium... Cette fois, tu n’y échapperas pas !",
            ["DialogueId"] = 73000201,
            ["GUID"] = "B6BF937A",
            ["SpeakNpcId"] = 818022,
            },
        [73000202] = {
            ["Content"] = "还想试试？行啊。哎，你们这些身手好的家伙就喜欢这么上蹿下跳的。",
            ["ContentFR"] = "Tu veux retenter ? D’accord. Tsss... vous, les acrobates, vous adorez bondir partout.",
            ["DialogueId"] = 73000202,
            ["GUID"] = "B6BF93A4",
            ["SpeakNpcId"] = 818022,
            },
        [73000203] = {
            ["Content"] = "啊？怎么你又成功了？至少失败一次啊……不行，我得再优化一下。",
            ["ContentFR"] = "Hein ? Tu as encore réussi ?! Échoue au moins une fois... Non, il faut que je l’optimise davantage.",
            ["DialogueId"] = 73000203,
            ["GUID"] = "B6BF93CE",
            ["SpeakNpcId"] = 818022,
            },
        [73000204] = {
            ["Content"] = "嗯，对，这就是我想要的效果！虽然不知道它到底能做什么……但一定能派上用场的。",
            ["ContentFR"] = "Oui, voilà, c’est l’effet que je voulais ! Même si, honnêtement... je ne sais pas encore vraiment à quoi ça sert. Mais ça trouvera bien une utilité !",
            ["DialogueId"] = 73000204,
            ["GUID"] = "B6BF93F8",
            ["SpeakNpcId"] = 818022,
            },
        [73000301] = {
            ["Content"] = "你又来了，而我也又一次改进了这个装置，上次的难度还是太简单了，这次一定可以绊倒你。",
            ["ContentFR"] = "Te revoilà... pile quand je venais d’apporter une nouvelle amélioration. La dernière version était trop facile, mais cette fois... je parie que tu vas trébucher.",
            ["DialogueId"] = 73000301,
            ["GUID"] = "B6BFA3E2",
            ["SpeakNpcId"] = 818022,
            },
        [73000302] = {
            ["Content"] = "还想试试？行啊。哎，你们这些身手好的家伙就喜欢这么上蹿下跳的。",
            ["ContentFR"] = "Tu veux retenter ? D’accord. Tsss... vous, les acrobates, vous adorez bondir partout.",
            ["DialogueId"] = 73000302,
            ["GUID"] = "B6BFA40C",
            ["SpeakNpcId"] = 818022,
            },
        [73000303] = {
            ["Content"] = "怎么回事！你又通过了！不行，我已经花了好多铜币改进它，不能就这么放弃，你等着，你等着。",
            ["ContentFR"] = "Quoi ?! Tu as encore réussi ? Impossible... J’ai dépensé des tas de pièces pour l’améliorer, je n’abandonnerai pas. Attends un peu, la prochaine fois je t’aurai !",
            ["DialogueId"] = 73000303,
            ["GUID"] = "B6BFA436",
            ["SpeakNpcId"] = 818022,
            },
        [73000304] = {
            ["Content"] = "好好好，看到你手忙脚乱的样子，我想到了，我可以和长官说把它装到冰湖城门口，用来防止有人强行闯进去……",
            ["ContentFR"] = "Héhé... en te voyant gesticuler comme ça, j’ai eu une idée. Je vais en parler à mon supérieur : installer ce dispositif aux portes de Givrelac, pour empêcher toute intrusion...",
            ["DialogueId"] = 73000304,
            ["GUID"] = "B6BFA460",
            ["SpeakNpcId"] = 818022,
            },
        [73000401] = {
            ["Content"] = "你终于来了，就等着你呢，这次我花费了全部家当把这个机关改造地毁天灭地，它已经完美，你是不可能通过的。",
            ["ContentFR"] = "Enfin te voilà ! Je t’attendais. Cette fois, j’ai investi toutes mes économies pour rendre ce mécanisme dévastateur. Il est parfait désormais... tu n’as aucune chance de passer !",
            ["DialogueId"] = 73000401,
            ["GUID"] = "B6BFB44A",
            ["SpeakNpcId"] = 818022,
            },
        [73000402] = {
            ["Content"] = "还想试试？行啊。哎，你们这些身手好的家伙就喜欢这么上蹿下跳的。",
            ["ContentFR"] = "Tu veux retenter ? D’accord. Tsss... vous, les acrobates, vous adorez bondir partout.",
            ["DialogueId"] = 73000402,
            ["GUID"] = "B6BFB474",
            ["SpeakNpcId"] = 818022,
            },
        [73000403] = {
            ["Content"] = "又……又失败了。算了……我就不应该对传颂会的东西有任何期待，这一定是我对皇帝陛下不忠的下场。",
            ["ContentFR"] = "Encore... encore raté ?! Assez ! J’aurais dû savoir qu’on ne peut rien attendre de la camelote d’Élysium. Voilà le prix de ma désobéissance à Sa Majesté...",
            ["DialogueId"] = 73000403,
            ["GUID"] = "B6BFB49E",
            ["SpeakNpcId"] = 818022,
            },
        [73000404] = {
            ["Content"] = "这堆东西我就放这儿了，你爱怎么玩儿怎么玩儿吧……我看你好像还挺乐在其中的。",
            ["ContentFR"] = "Bah ! Je laisse ce truc ici. Amuse-toi avec si ça te chante... On dirait que ça t’amuse de toute façon.",
            ["DialogueId"] = 73000404,
            ["GUID"] = "B6BFB4C8",
            ["SpeakNpcId"] = 818022,
            },
        [73000405] = {
            ["Content"] = "怎么样，尝到厉害了吧。而我也想到了，我可以把它献给皇帝陛下，和他说用它来训练和筛选士兵，一定能够获得许多赏钱。这样我就能还上为了改进它欠下的钱了。",
            ["ContentFR"] = "Eh bah alors ? Tu as goûté à sa puissance ? Héhé... Je pourrais même l’offrir à Sa Majesté, proposer de l’utiliser pour former et sélectionner les recrues. Avec la prime, je pourrai enfin rembourser toutes les dettes que j’ai contractées pour l’améliorer.",
            ["DialogueId"] = 73000405,
            ["GUID"] = "B6BFB4F2",
            ["SpeakNpcId"] = 818022,
            },
        [73000502] = {
            ["Content"] = "（这台装置沉默不语，上面有一个简陋的旋钮，以及简单，不简单和燃尽了三个档位，显然是出自那位喋喋不休的士兵的手笔。）",
            ["ContentFR"] = "La machine vibre doucement. Un cadran grossier y est fixé, gravé de trois options : Facile, Difficile et Extrême. Tout indique que c’est l’œuvre de ce soldat bavard.",
            ["DialogueId"] = 73000502,
            ["GUID"] = "B6BFC4DC",
            ["SpeakNpcId"] = 818022,
            },
        [73000601] = {
            ["Content"] = "（是运输用升降机，兴许可以得到补给。不过，也要小心留意是否有埋伏的敌人。）",
            ["ContentFR"] = "<I>C’est un monte-charge... je pourrais peut-être récupérer des provisions. Mais je dois rester sur mes gardes, une embuscade est possible.</>",
            ["DialogueId"] = 73000601,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "B6BFD51A",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110192/1B95DDD7",
            },
        [73000701] = {
            ["Content"] = "这个房间暂时安全，可以操作控制台了。",
            ["ContentFR"] = "Pour l’instant la zone est sûre. Je peux accéder au terminal.",
            ["DialogueId"] = 73000701,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "B6BFE582",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110192/1B95DDD8",
            },
        [73000801] = {
            ["Content"] = "获取控制权限中，请稍等。",
            ["ContentFR"] = "Autorisation en cours. Veuillez patienter...",
            ["DialogueId"] = 73000801,
            ["GUID"] = "B6BFF5EA",
            ["SpeakNpcName"] = "UI_Npc_MechVoice",
            ["VoiceName"] = "voice/$Locale$/story/1002/110192/1B95DDD9",
            },
        [73000901] = {
            ["Content"] = "（中央控制室是独立供能……这里的髓动轮并未受到动力室爆炸的影响。）",
            ["ContentFR"] = "<I>La salle de commande centrale est alimentée séparément... Les Roues Phoxynamo n’ont donc pas été affectées par l’explosion de la salle des machines.</>",
            ["DialogueId"] = 73000901,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "B6C00652",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110192/1B95DDDA",
            },
        [73001001] = {
            ["Content"] = "线路错误，控制台处于保护状态。请关闭髓动轮以解除保护状态。",
            ["ContentFR"] = "Erreur de flux énergétique. Le terminal est passé en mode de protection. Veuillez désactiver les Roues Phoxynamo pour lever le verrouillage.",
            ["DialogueId"] = 73001001,
            ["GUID"] = "B6C016BA",
            ["SpeakNpcName"] = "UI_Npc_MechVoice",
            ["VoiceName"] = "voice/$Locale$/story/1002/110192/1B95DDDB",
            },
        [80001001] = {
            ["Content"] = "哇，我来到大魔法师的家门口了！咚咚咚——大魔法师，你在家吗？",
            ["ContentFR"] = "Oh ! Je suis devant la maison du Grand Magicien ! Toc, toc, toc... Grand Magicien, tu es là ?",
            ["DialogueId"] = 80001001,
            ["GUID"] = "C8462C3A",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/C8462C3A",
            },
        [80001002] = {
            ["Content"] = "唔……没有回应，看来大魔法师出门了。去外面找找看吧！",
            ["ContentFR"] = "Hmm... Pas de réponse. On dirait qu’il est sorti. Allons voir dehors si on peut le retrouver !",
            ["DialogueId"] = 80001002,
            ["GUID"] = "C8462C64",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/C8462C64",
            },
        [80001003] = {
            ["Content"] = "哎呀，前面的故事还没有颜色……不过没关系，菲娜有魔法的画笔，可以一边前进，一边给故事填上色彩。",
            ["ContentFR"] = "Oh... l’histoire devant moi n’a même pas de couleurs... Mais ce n’est pas grave, j’ai mon pinceau magique ! Je vais colorier l’histoire au fur et à mesure que j’avance.",
            ["DialogueId"] = 80001003,
            ["GUID"] = "C8462C8E",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/C8462C8E",
            },
        [80001004] = {
            ["Content"] = "沿着这条路出发，寻找大魔法师的踪迹吧。",
            ["ContentFR"] = "Allez, empruntons ce chemin et partons sur les traces du Grand Magicien.",
            ["DialogueId"] = 80001004,
            ["GUID"] = "C8462CB8",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/C8462CB8",
            },
        [80001005] = {
            ["Content"] = "咦，花园里怎么一朵花也没有……",
            ["ContentFR"] = "Hein ? Mais... il n’y a pas une seule fleur dans le jardin...",
            ["DialogueId"] = 80001005,
            ["GUID"] = "C8462CE2",
            ["GuideFacialId"] = "Sad",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 80001006,
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/C8462CE2",
            },
        [80001006] = {
            ["Content"] = "让菲娜来给这里添上漂亮的花朵吧！",
            ["ContentFR"] = "Je vais faire apparaître de jolies fleurs ici !",
            ["DialogueId"] = 80001006,
            ["GUID"] = "C8462D0C",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/C8462D0C",
            },
        [80001007] = {
            ["Content"] = "这样一来，花园就变得漂亮多啦。继续前进吧！",
            ["ContentFR"] = "Voilà ! C’est bien plus joli comme ça. Continuons notre aventure !",
            ["DialogueId"] = 80001007,
            ["GUID"] = "C8462D36",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/C8462D36",
            },
        [80001008] = {
            ["Content"] = "这是……小夜莺留下的羽毛！",
            ["ContentFR"] = "Oh... C’est une plume laissée par le petit Rossignol !",
            ["DialogueId"] = 80001008,
            ["GUID"] = "C8462D60",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 80001009,
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/C8462D60",
            },
        [80001009] = {
            ["Content"] = "把它收集起来吧，一定会带来好运的。",
            ["ContentFR"] = "Vite, ramassons-la. Ça nous portera sûrement bonheur.",
            ["DialogueId"] = 80001009,
            ["GUID"] = "C8462D8A",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/C8462D8A",
            },
        [80001010] = {
            ["Content"] = "前面的路被挡住了……该怎么做才能请藤蔓让路呢？",
            ["ContentFR"] = "Le chemin est bloqué... Comment faire pour que ces lianes me laissent passer ?",
            ["DialogueId"] = 80001010,
            ["GUID"] = "C8462DB4",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/C8462DB4",
            },
        [80001011] = {
            ["Content"] = "太好啦，可以前进了！",
            ["ContentFR"] = "Super ! Je peux avancer !",
            ["DialogueId"] = 80001011,
            ["GUID"] = "C8462DDE",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/C8462DDE",
            },
        [80001012] = {
            ["Content"] = "大魔法师会在那里吗？",
            ["ContentFR"] = "Peut-être que le Grand Magicien est là-bas...",
            ["DialogueId"] = 80001012,
            ["GUID"] = "C8462E08",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/C8462E08",
            },
        [80001013] = {
            ["Content"] = "咦，篝火还在燃烧，看来大魔法师才刚离开不久。",
            ["ContentFR"] = "Oh ? Le feu brûle encore... On dirait qu’il vient juste de partir.",
            ["DialogueId"] = 80001013,
            ["GUID"] = "C8462E32",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/C8462E32",
            },
        [80001014] = {
            ["Content"] = "哇，萤火虫飞散开来，好像星星长出了翅膀！",
            ["ContentFR"] = "Ouaaah... les lucioles brillent comme des petites étoiles qui volent !",
            ["DialogueId"] = 80001014,
            ["GUID"] = "C8462E5C",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/C8462E5C",
            },
        [80001015] = {
            ["Content"] = "这里也开出漂亮的花了。",
            ["ContentFR"] = "Ici aussi, de jolies fleurs ont éclos.",
            ["DialogueId"] = 80001015,
            ["GUID"] = "C8462E86",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 80001016,
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/C8462E86",
            },
        [80001016] = {
            ["Content"] = "看，还有圆圆的蘑菇！如果踩在上面，一定能跳得很高吧？",
            ["ContentFR"] = "Et regarde, des champignons tout ronds ! Si je saute dessus, je vais sûrement bondir très haut !",
            ["DialogueId"] = 80001016,
            ["GUID"] = "C8462EB0",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/C8462EB0",
            },
        [80001017] = {
            ["Content"] = "这里竟然会有宝物，难道是大魔法师的珍藏？",
            ["ContentFR"] = "Un trésor ?! Ce serait... la cachette secrète du Grand Magicien ?",
            ["DialogueId"] = 80001017,
            ["GUID"] = "C8462EDA",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/C8462EDA",
            },
        [80001018] = {
            ["Content"] = "前面没有路了，该怎么过去呢？",
            ["ContentFR"] = "Il n’y a plus de chemin devant... Comment je vais faire pour traverser ?",
            ["DialogueId"] = 80001018,
            ["GUID"] = "C8462F04",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/C8462F04",
            },
        [80001019] = {
            ["Content"] = "哇……！可爱的蘑菇们，你们是来帮我的吗？",
            ["ContentFR"] = "Ouaah... Vous êtes adorables, les petits champignons ! Vous êtes venus pour m’aider ?",
            ["DialogueId"] = 80001019,
            ["GUID"] = "C8462F2E",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 80001020,
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/C8462F2E",
            },
        [80001020] = {
            ["Content"] = "谢谢你们，这样我就可以跳到对岸去啦。",
            ["ContentFR"] = "Merci à vous ! Comme ça, je peux sauter de l’autre côté !",
            ["DialogueId"] = 80001020,
            ["GUID"] = "C8462F58",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/C8462F58",
            },
        [80001021] = {
            ["Content"] = "咦，这里也有宝物。是大魔法师特地留给我的吗？",
            ["ContentFR"] = "Oh ! Ici aussi il y a un coffre... C’est le Grand Magicien qui l’a laissé exprès pour moi ?",
            ["DialogueId"] = 80001021,
            ["GUID"] = "C8462F82",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/C8462F82",
            },
        [80001022] = {
            ["Camera"] = "55.417297,85.066406,122.219238,0.000047,0.044225,-103.953941,35.0,272.596405,false,Manual,7.0",
            ["Content"] = "大魔法师，终于找到你啦！",
            ["ContentFR"] = "Grand Magicien ! Je t’ai enfin retrouvé !",
            ["DialogueId"] = 80001022,
