            },
        [80001023] = {
            ["Camera"] = "85.921997,188.681641,126.737305,0.000048,-0.755863,-106.954742,35.0,272.596405,false,Manual,7.0",
            ["Content"] = "菲娜需要你的帮助，请和我一起去往现实世界吧~",
            ["ContentFR"] = "J’ai besoin de ton aide... Viens avec moi dans le monde réel, s’il te plaît !",
            ["DialogueId"] = 80001023,
