            },
        [80002001] = {
            ["Content"] = "哇，这是一座迷宫花园！",
            ["ContentFR"] = "Ouaaah... Un jardin-labyrinthe !",
            ["DialogueId"] = 80002001,
            ["GUID"] = "C846D04A",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 80002002,
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/C846D04A",
            },
        [80002002] = {
            ["Content"] = "独角兽{性别：先生|小姐}会藏在哪里呢？",
            ["ContentFR"] = "Où est-ce que {性别:Monsieur|Mademoiselle} Licorne pourrait bien se cacher ?",
            ["DialogueId"] = 80002002,
            ["GUID"] = "C846D074",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/C846D074",
            },
        [80002003] = {
            ["Content"] = "嗯？没有反应……也许是需要用和它相同的颜色来画？",
            ["ContentFR"] = "Hein ? Rien ne se passe... Peut-être qu’il faut utiliser la même couleur ?",
            ["DialogueId"] = 80002003,
            ["GUID"] = "C846D09E",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/C846D09E",
            },
        [80002004] = {
            ["Content"] = "我还没有其他的颜料，去迷宫里找找看吧。",
            ["ContentFR"] = "Je n’ai pas d’autre pigment pour l’instant. Allons chercher dans le labyrinthe !",
            ["DialogueId"] = 80002004,
            ["GUID"] = "C846D0C8",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/C846D0C8",
            },
        [80002005] = {
            ["Content"] = "唔，这一侧的迷宫被锁住了，看来要按从另一侧开始解谜呀。",
            ["ContentFR"] = "Hmm... Ce côté du labyrinthe est bloqué. On dirait qu’il faut essayer par l’autre côté.",
            ["DialogueId"] = 80002005,
            ["GUID"] = "C846D0F2",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/C846D0F2",
            },
        [80002006] = {
            ["Content"] = "独角兽{性别：先生|小姐}曾经为了躲避怪兽，和家人一起躲在狭窄的山洞里……",
            ["ContentFR"] = "{性别:Monsieur|Mademoiselle} Licorne s’était déjà réfugié dans une grotte étroite avec sa famille... pour échapper aux monstres.",
            ["DialogueId"] = 80002006,
            ["GUID"] = "C846D11C",
            ["GuideFacialId"] = "Confident",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/C846D11C",
            },
        [80002007] = {
            ["Content"] = "后来，{性别：他们|她们}勇敢地拿起武器，与怪兽对抗。",
            ["ContentFR"] = "Puis {性别:ils|elles} ont eu le courage de saisir leurs armes... et d’affronter les monstres.",
            ["DialogueId"] = 80002007,
            ["GUID"] = "C846D146",
            ["GuideFacialId"] = "Confident",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/C846D146",
            },
        [80002008] = {
            ["Content"] = "终于，独角兽{性别：先生|小姐}和家人一起打跑了拦路的秽兽，冲出重围……",
            ["ContentFR"] = "Enfin, {性别:Monsieur|Mademoiselle} Licorne et sa famille ont repoussé les Souillés et se sont frayé un chemin...",
            ["DialogueId"] = 80002008,
            ["GUID"] = "C846D170",
            ["GuideFacialId"] = "Confident",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/C846D170",
            },
        [80002009] = {
            ["Content"] = "却又遇到了更强大的敌人！",
            ["ContentFR"] = "Mais à ce moment-là... un ennemi encore plus puissant est apparu !",
            ["DialogueId"] = 80002009,
            ["GUID"] = "C846D19A",
            ["GuideFacialId"] = "Confident",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/C846D19A",
            },
        [80002010] = {
            ["Content"] = "他们拼命地战斗，使出了全部的力量，却还是被迫失散了……",
            ["ContentFR"] = "Ils ont combattu de toutes leurs forces, mais ont fini par être séparés...",
            ["DialogueId"] = 80002010,
            ["GUID"] = "C846D1C4",
            ["GuideFacialId"] = "Confident",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 80002011,
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/C846D1C4",
            },
        [80002011] = {
            ["Content"] = "希望独角兽{性别：先生|小姐}能早一点找回重要的家人。",
            ["ContentFR"] = "J’espère que {性别:Monsieur|Mademoiselle} Licorne retrouvera vite sa famille bien-aimée.",
            ["DialogueId"] = 80002011,
            ["GUID"] = "C846D1EE",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/C846D1EE",
            },
        [80002012] = {
            ["Content"] = "来到寒冰的国度之后，独角兽{性别：先生|小姐}遇到了新的伙伴，展开了一次次精彩的冒险。",
            ["ContentFR"] = "Puis, après être arrivé dans le royaume de glace... {性别:Monsieur|Mademoiselle} Licorne rencontra de nouveaux compagnons, et vécut encore et encore de merveilleuses aventures.",
            ["DialogueId"] = 80002012,
            ["GUID"] = "C846D218",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/C846D218",
            },
        [80002013] = {
            ["Content"] = "嗯？水池里的圆环亮起了半边……看来我已经完成一半的谜题啦！",
            ["ContentFR"] = "Hein ? Le cercle dans le bassin s’est illuminé... à moitié ! Ça veut dire que j’ai déjà résolu la moitié de l’énigme !",
            ["DialogueId"] = 80002013,
            ["GUID"] = "C846D242",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/C846D242",
            },
