        [80002016] = {
            ["Content"] = "现在我有新的颜料了，试着改变它的颜色吧！",
            ["ContentFR"] = "Maintenant que j’ai un nouveau pigment, essayons de changer sa couleur !",
            ["DialogueId"] = 80002016,
            ["GUID"] = "C846D2C0",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/C846D2C0",
            },
        [80002017] = {
            ["Content"] = "这个颜色好像不对……试试看刚获得的新颜料吧。",
            ["ContentFR"] = "Oh... ce n’est pas la bonne couleur. Essayons celle que je viens de recevoir !",
            ["DialogueId"] = 80002017,
            ["GUID"] = "C846D2EA",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/C846D2EA",
            },
        [80002018] = {
            ["Content"] = "换一种颜料试试看吧。",
            ["ContentFR"] = "Changeons de pigment, ça marchera peut-être !",
            ["DialogueId"] = 80002018,
            ["GUID"] = "C846D314",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/C846D314",
            },
        [80002019] = {
            ["Content"] = "成功了！现在可以去另一侧的迷宫探险啦。",
            ["ContentFR"] = "Ça a marché ! Maintenant je peux explorer l’autre côté du labyrinthe !",
            ["DialogueId"] = 80002019,
            ["GUID"] = "C846D33E",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/C846D33E",
            },
        [80002020] = {
            ["Content"] = "看，这里有积木！独角兽{性别：先生|小姐}曾经陪菲娜一起玩过叫做“弹壳”的积木呢。",
            ["ContentFR"] = "Oh, des blocs de construction ! {性别:Monsieur|Mademoiselle} Licorne avait déjà joué avec moi à construire une tour avec ces blocs qu’on appelle des « douilles ».",
            ["DialogueId"] = 80002020,
            ["GUID"] = "C846D368",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/C846D368",
            },
        [80002021] = {
            ["Content"] = "哇，是星星！好想再和独角兽{性别：先生|小姐}一起看一次真正的星空呀。",
            ["ContentFR"] = "Ooooh... des étoiles ! J’aimerais tellement revoir un vrai ciel étoilé avec {性别:Monsieur|Mademoiselle} Licorne.",
            ["DialogueId"] = 80002021,
            ["GUID"] = "C846D392",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/C846D392",
            },
        [80002022] = {
            ["Content"] = "这里也有宝物，是独角兽{性别：先生|小姐}通过委托得到的报酬吗？",
            ["ContentFR"] = "Un trésor, ici aussi ? Ce serait... la récompense d’une mission réussie par {性别:Monsieur|Mademoiselle} Licorne ?",
            ["DialogueId"] = 80002022,
            ["GUID"] = "C846D3BC",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/C846D3BC",
            },
        [80002023] = {
            ["Content"] = "又发现了宝物！独角兽{性别：先生|小姐}，这是你给菲娜的惊喜吗？",
            ["ContentFR"] = "Encore un coffre ?! {性别:Monsieur|Mademoiselle} Licorne, c’est toi qui m’as préparé une surprise ?",
            ["DialogueId"] = 80002023,
            ["GUID"] = "C846D3E6",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/C846D3E6",
            },
        [80002024] = {
            ["Content"] = "菲娜和独角兽{性别：先生|小姐}一起书写的故事，一定会很长很长……嗯，我希望它永远也不要结束。",
            ["ContentFR"] = "L’histoire que j’écris avec {性别:Monsieur|Mademoiselle} Licorne sera sûrement très, très longue... Et j’espère qu’elle ne se terminera jamais.",
            ["DialogueId"] = 80002024,
            ["GUID"] = "C846D410",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/C846D410",
            },
        [80002025] = {
            ["Content"] = "另一半的圆环也被点亮了。",
            ["ContentFR"] = "Oh ! L’autre moitié du cercle s’est illuminée !",
            ["DialogueId"] = 80002025,
            ["GUID"] = "C846D43A",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 80002026,
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/C846D43A",
            },
        [80002026] = {
            ["Content"] = "回到水池旁边，看看有没有发生什么神奇的变化吧~",
            ["ContentFR"] = "Vite, retournons près du bassin pour voir si quelque chose de magique s’est produit !",
            ["DialogueId"] = 80002026,
            ["GUID"] = "C846D464",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/C846D464",
            },
        [80002027] = {
            ["Content"] = "哇……地板飞起来了？看来我们找到迷宫的出口啦！",
            ["ContentFR"] = "Ouaaah... Le sol s’élève ?! On a trouvé la sortie du labyrinthe !",
            ["DialogueId"] = 80002027,
            ["GUID"] = "C846D48E",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 80002028,
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/C846D48E",
            },
        [80002028] = {
            ["Content"] = "谢谢你的帮忙，独角兽{性别：先生|小姐}。你这么聪明，一定也可以帮助菲娜解开现实世界中的谜题吧？",
            ["ContentFR"] = "Merci de ton aide, {性别:Monsieur|Mademoiselle} Licorne. Tu es vraiment super {性别:intelligent|intelligente}... Je suis sûre que tu pourras aussi m’aider à résoudre les énigmes du monde réel, pas vrai ?",
            ["DialogueId"] = 80002028,
            ["GUID"] = "C846D4B8",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/C846D4B8",
            },
