        [80003201] = {
            ["Content"] = "唔，前面的航路被藤蔓挡住了……",
            ["ContentFR"] = "Oh non... Les lianes bloquent le passage juste devant...",
            ["DialogueId"] = 80003201,
            ["Duration"] = 3,
            ["GUID"] = "C847952A",
            ["GuideFacialId"] = "Sad",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 80003202,
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120113/C847952A",
            },
        [80003202] = {
            ["Content"] = "下船找找有没有其他的路吧。",
            ["ContentFR"] = "Descendons du bateau pour voir s’il n’y aurait pas un autre chemin.",
            ["DialogueId"] = 80003202,
            ["Duration"] = 3,
            ["GUID"] = "C8479554",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120113/C8479554",
            },
        [80003203] = {
            ["Content"] = "咦，是蝴蝶小姐！你特地飞过来帮助菲娜吗，谢谢！",
            ["ContentFR"] = "Hein ? C’est Mademoiselle Papillon ! Tu es venue exprès pour m’aider ? Merci !",
            ["DialogueId"] = 80003203,
            ["Duration"] = 3,
            ["GUID"] = "C847957E",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120113/C847957E",
            },
        [80003204] = {
            ["Content"] = "圆圆的荷叶浮起来，连成了一条路呢~这样菲娜就可以走在水面上啦。",
            ["ContentFR"] = "Les feuilles de lotus rondes flottent et forment un chemin ! Comme ça, je peux marcher sur l’eau !",
            ["DialogueId"] = 80003204,
            ["Duration"] = 3,
            ["GUID"] = "C84795A8",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120113/C84795A8",
            },
        [80003205] = {
            ["Content"] = "藤蔓都消失啦，可以回去再次开动“白色夜莺号”了！",
            ["ContentFR"] = "Les lianes ont disparu ! On va pouvoir repartir avec le Rossignol Blanc !",
            ["DialogueId"] = 80003205,
            ["Duration"] = 3,
            ["GUID"] = "C84795D2",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120113/C84795D2",
            },
        [80003206] = {
            ["Content"] = "又出现了水盆，这次它们会藏着什么机关呢？",
            ["ContentFR"] = "Encore des bassins... Qu’est-ce qu’ils cachent cette fois ?",
            ["DialogueId"] = 80003206,
            ["Duration"] = 3,
            ["GUID"] = "C84795FC",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 80003207,
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120113/C84795FC",
            },
        [80003207] = {
            ["Content"] = "也许……是和这些石柱有关？",
            ["ContentFR"] = "Peut-être... que c’est lié à ces piliers ?",
            ["DialogueId"] = 80003207,
            ["Duration"] = 3,
            ["GUID"] = "C8479626",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120113/C8479626",
            },
        [80003208] = {
            ["Content"] = "蝴蝶小姐，我们成功抵达目的地啦！",
            ["ContentFR"] = "Mademoiselle Papillon, on est arrivées à destination !",
            ["DialogueId"] = 80003208,
            ["Duration"] = 3,
            ["GUID"] = "C8479650",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 80003209,
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120113/C8479650",
            },
        [80003209] = {
            ["Content"] = "菲娜需要你帮一个小小的忙，请和我一起回到现实世界去吧~",
            ["ContentFR"] = "J’ai besoin d’un petit coup de main... Viens avec moi dans le monde réel, s’il te plaît !",
            ["DialogueId"] = 80003209,
            ["Duration"] = 3,
            ["GUID"] = "C847967A",
            ["GuideFacialId"] = "Happy",
