        [80004101] = {
            ["Content"] = "森林里雾好大呀！",
            ["ContentFR"] = "Ah... La forêt est remplie de brouillard !",
            ["DialogueId"] = 80004101,
            ["Duration"] = 3,
            ["GUID"] = "C84828D2",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 80004102,
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/C84828D2",
            },
        [80004102] = {
            ["Content"] = "为了避免迷路，就沿着这条小溪前进吧。",
            ["ContentFR"] = "Pour ne pas me perdre, je vais suivre ce petit ruisseau.",
            ["DialogueId"] = 80004102,
            ["Duration"] = 3,
            ["GUID"] = "C84828FC",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/C84828FC",
            },
        [80004103] = {
            ["Content"] = "咦……这些荆棘缺了一部分颜色呢。",
            ["ContentFR"] = "Hein... Ces ronces ont perdu leur couleur.",
            ["DialogueId"] = 80004103,
            ["Duration"] = 3,
            ["GUID"] = "C8482926",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 80004104,
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/C8482926",
            },
        [80004104] = {
            ["Content"] = "等我给空白的部分涂上颜色，也许它就会动起来啦。",
            ["ContentFR"] = "Si je leur rends leurs couleurs, peut-être qu’elles s’écarteront ?",
            ["DialogueId"] = 80004104,
            ["Duration"] = 3,
            ["GUID"] = "C8482950",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/C8482950",
            },
        [80004105] = {
            ["Content"] = "小夜莺，你怎么待在里面不出来呀？是这些荆棘把你困住了吗？",
            ["ContentFR"] = "Petit Rossignol, pourquoi restes-tu enfermé là-dedans ? Ce sont les ronces qui t’ont piégé ?",
            ["DialogueId"] = 80004105,
            ["Duration"] = 3,
            ["GUID"] = "C848297A",
            ["GuideFacialId"] = "Sad",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 80004106,
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/C848297A",
            },
        [80004106] = {
            ["Content"] = "别害怕，菲娜会帮助你的！",
            ["ContentFR"] = "N’aie pas peur, je vais t’aider à sortir !",
            ["DialogueId"] = 80004106,
            ["Duration"] = 3,
            ["GUID"] = "C84829A4",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/C84829A4",
            },
        [80004107] = {
            ["Content"] = "这里的荆棘长得太高，把小夜莺的巢穴都挡住了。",
            ["ContentFR"] = "Oh non... Les ronces sont si hautes qu’elles ont caché tout le nid du petit Rossignol.",
            ["DialogueId"] = 80004107,
            ["Duration"] = 3,
            ["GUID"] = "C84829CE",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 80004108,
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/C84829CE",
            },
        [80004108] = {
            ["Content"] = "用刚才的方法给它们涂上颜色，他们就会给小夜莺让路了吧？",
            ["ContentFR"] = "Si je les peins comme tout à l’heure, elles lui laisseront sûrement le passage !",
            ["DialogueId"] = 80004108,
            ["Duration"] = 3,
            ["GUID"] = "C84829F8",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/C84829F8",
            },
        [80004109] = {
            ["Content"] = "拦路的荆棘消失了，我们继续前进吧，小夜莺~",
            ["ContentFR"] = "Les ronces ont disparu ! Allons plus loin, petit Rossignol !",
            ["DialogueId"] = 80004109,
            ["Duration"] = 3,
            ["GUID"] = "C8482A22",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/C8482A22",
            },
        [80004110] = {
