        [80004201] = {
            ["Content"] = "前面的雾气好像更浓了……",
            ["ContentFR"] = "On dirait que le brouillard est encore plus épais...",
            ["DialogueId"] = 80004201,
            ["Duration"] = 3,
            ["GUID"] = "C848393A",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 80004202,
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/C848393A",
            },
        [80004202] = {
            ["Content"] = "小夜莺，你来给菲娜带路吧！",
            ["ContentFR"] = "Petit Rossignol, tu veux bien guider mes pas ?",
            ["DialogueId"] = 80004202,
            ["Duration"] = 3,
            ["GUID"] = "C8483964",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/C8483964",
            },
        [80004203] = {
            ["Content"] = "哇……原来这块石头是一盏灯呀！灯光亮起来，雾气就散开了。",
            ["ContentFR"] = "Ouaaah... Cette pierre est en fait une lampe ! Et quand elle s’allume, le brouillard s’en va !",
            ["DialogueId"] = 80004203,
            ["Duration"] = 3,
            ["GUID"] = "C848398E",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 80004204,
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/C848398E",
            },
        [80004204] = {
            ["Content"] = "我们再去找找别的石头吧。",
            ["ContentFR"] = "Cherchons d’autres pierres comme celle-ci.",
            ["DialogueId"] = 80004204,
            ["Duration"] = 3,
            ["GUID"] = "C84839B8",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/C84839B8",
            },
        [80004205] = {
            ["Content"] = "雾气会让人迷失方向，要紧跟在小夜莺身边才安全哦。",
            ["ContentFR"] = "Avec ce brouillard, on peut vite se perdre... Il faut rester tout près du petit Rossignol pour ne pas se tromper de chemin.",
            ["DialogueId"] = 80004205,
            ["Duration"] = 3,
            ["GUID"] = "C84839E2",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/C84839E2",
            },
        [80004206] = {
            ["Content"] = "终于走出迷雾了！快看，森林的出口就在前面。",
            ["ContentFR"] = "Ouf, on est enfin sortis du brouillard ! Regarde, la sortie de la forêt est juste devant nous !",
            ["DialogueId"] = 80004206,
            ["Duration"] = 3,
            ["GUID"] = "C8483A0C",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/C8483A0C",
            },
        [80004207] = {
            ["Content"] = "走出森林之后，会见到怎样的风景呢？好期待呀！",
            ["ContentFR"] = "Une fois dehors... quel paysage merveilleux nous attendra ? J’ai trop hâte de voir !",
            ["DialogueId"] = 80004207,
            ["Duration"] = 3,
            ["GUID"] = "C8483A36",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/C8483A36",
            },
        [80004208] = {
            ["Content"] = "咦，那是……大魔法师、独角兽{性别：先生|小姐}和蝴蝶小姐！大家都在等我们呢。",
            ["ContentFR"] = "Hein ? Mais... c’est le Grand Magicien, {性别:Monsieur|Mademoiselle} Licorne et Mademoiselle Papillon ! Tout le monde nous attendait !",
            ["DialogueId"] = 80004208,
            ["Duration"] = 3,
            ["GUID"] = "C8483A60",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 80004209,
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/C8483A60",
            },
        [80004209] = {
            ["Content"] = "小夜莺，我们赶快过去和它们会合吧！",
            ["ContentFR"] = "Vite, petit Rossignol, allons les rejoindre !",
            ["DialogueId"] = 80004209,
            ["Duration"] = 3,
            ["GUID"] = "C8483A8A",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/C8483A8A",
            },
        [80004210] = {
