        [80010100] = {
            ["Content"] = "嗯，荣幸之至。",
            ["DialogueId"] = 80010100,
            ["GUID"] = "C84C0108",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/001/C84C0108",
            },
        [80010101] = {
            ["Content"] = "这是为了维系您与我之间的友谊，而有意为之的邀约，对吗？",
            ["DialogueId"] = 80010101,
            ["GUID"] = "C84C0132",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/001/C84C0132",
            },
        [80010102] = {
            ["Content"] = "好，那么我愿与您共饮。",
            ["DialogueId"] = 80010102,
            ["GUID"] = "C84C015C",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/001/C84C015C",
            },
        [80010103] = {
            ["Content"] = "唔，咳……",
            ["DialogueId"] = 80010103,
            ["GUID"] = "C84C0186",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/001/C84C0186",
            },
        [80010104] = {
            ["Content"] = "没什么，请继续讲吧。",
            ["DialogueId"] = 80010104,
            ["GUID"] = "C84C01B0",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/001/C84C01B0",
            },
        [80010105] = {
            ["Content"] = "不，只是……",
            ["DialogueId"] = 80010105,
            ["GUID"] = "C84C01DA",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/001/C84C01DA",
            },
        [80010106] = {
            ["Content"] = "嗯。被您看穿了呢。",
            ["DialogueId"] = 80010106,
            ["GUID"] = "C84C0204",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/001/C84C0204",
            },
        [80010107] = {
            ["Content"] = "酒的味道，颇有些……浓烈。长久以来，受到家族较多管束的缘故，我极少品尝这种饮品。",
            ["DialogueId"] = 80010107,
            ["GUID"] = "C84C022E",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/001/C84C022E",
            },
        [80010108] = {
            ["Content"] = "但既然您饱含诚意的邀请了，那回绝就过于失礼。",
            ["DialogueId"] = 80010108,
            ["GUID"] = "C84C0258",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/001/C84C0258",
            },
        [80010109] = {
            ["Content"] = "您不必为此介怀。对宾客投其所好或许是尽地主之谊的必要礼节，但适逢其时的好意本身已经足以慰藉风尘。",
            ["DialogueId"] = 80010109,
            ["GUID"] = "C84C0282",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/001/C84C0282",
            },
        [80010110] = {
            ["Content"] = "而且，我也在逐步学会适应“外面的一切”。",
            ["DialogueId"] = 80010110,
            ["GUID"] = "C84C02AC",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/001/C84C02AC",
            },
        [80010111] = {
            ["Content"] = "第一次抵达北境的时候，在冰天雪地的荒原上，也曾有一位年迈的猎人给了我同样的东西。",
            ["DialogueId"] = 80010111,
            ["GUID"] = "C84C02D6",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/001/C84C02D6",
            },
        [80010112] = {
            ["Content"] = "“烈酒”。",
            ["DialogueId"] = 80010112,
            ["GUID"] = "C84C0300",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/001/C84C0300",
            },
        [80010113] = {
            ["Content"] = "远比您调制的这杯更辛辣，更苦涩，甚至让人难以保持清醒的意志。",
            ["DialogueId"] = 80010113,
            ["GUID"] = "C84C032A",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/001/C84C032A",
            },
        [80010114] = {
            ["Content"] = "但却非常温暖。像一小簇火苗，让几乎冻僵的我们再次有了活着的知觉。",
            ["DialogueId"] = 80010114,
            ["GUID"] = "C84C0354",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/001/C84C0354",
            },
        [80010115] = {
            ["Content"] = "是的，这没什么值得隐瞒的。",
            ["DialogueId"] = 80010115,
            ["GUID"] = "C84C037E",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/001/C84C037E",
            },
        [80010116] = {
            ["Content"] = "您这个玩笑……我并不觉得非常有趣。",
            ["DialogueId"] = 80010116,
            ["GUID"] = "C84C03A8",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/001/C84C03A8",
            },
        [80010117] = {
            ["Content"] = "我是一名漂泊之人，如您所见。",
            ["DialogueId"] = 80010117,
            ["GUID"] = "C84C03D2",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/001/C84C03D2",
            },
        [80010118] = {
            ["Content"] = "也许您已经从希尔妲那里听说过，我们的故土，是迪斯玛尼亚——也许您会更加熟悉它的另一个称呼，“皇都”。",
            ["DialogueId"] = 80010118,
            ["GUID"] = "C84C03FC",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/001/C84C03FC",
            },
        [80010119] = {
            ["Content"] = "在那里，我和家族发生了一些冲突，致使流落至此。",
            ["DialogueId"] = 80010119,
            ["GUID"] = "C84C0426",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/001/C84C0426",
            },
        [80010120] = {
            ["Content"] = "请谅解。您是与我订立过重要契约的人，按照礼节，我本应坦诚以待。",
            ["DialogueId"] = 80010120,
            ["GUID"] = "C84C0450",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/001/C84C0450",
            },
        [80010121] = {
            ["Content"] = "但关于这件事，请容许我保守秘密——",
            ["DialogueId"] = 80010121,
            ["GUID"] = "C84C047A",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/001/C84C047A",
            },
        [80010122] = {
            ["Content"] = "我对您虽无戒备之心，但出于对您安全的顾虑，还是建议您不要牵涉过深为好。",
            ["DialogueId"] = 80010122,
            ["GUID"] = "C84C04A4",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/001/C84C04A4",
            },
        [80010123] = {
            ["Content"] = "时间有些迟了，谢谢您今日的邀请。回见。",
            ["DialogueId"] = 80010123,
            ["GUID"] = "C84C04CE",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/001/C84C04CE",
            },
        [80010201] = {
            ["Content"] = "与您共度的时光称得上令人欢悦，虽然我还不能很好地适应它的味道。",
            ["DialogueId"] = 80010201,
            ["GUID"] = "C84C119A",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/002/C84C119A",
            },
        [80010202] = {
            ["Content"] = "嗯……的确没有呢。",
            ["DialogueId"] = 80010202,
            ["GUID"] = "C84C11C4",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/002/C84C11C4",
            },
        [80010203] = {
            ["Content"] = "请不要误会，我并非在对您的邀约敷衍了事。",
            ["DialogueId"] = 80010203,
            ["GUID"] = "C84C11EE",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/002/C84C11EE",
            },
        [80010204] = {
            ["Content"] = "只是希尔妲不允许我对食物拥有偏好。她每日都会要求厨师奉上和此前完全不同的菜肴，而这些餐点里，喜爱的也好，厌弃的也好，她都会要求我一视同仁地品尝。",
            ["DialogueId"] = 80010204,
            ["GUID"] = "C84C1218",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/002/C84C1218",
            },
        [80010205] = {
            ["Content"] = "久而久之，我也就没有什么“喜爱的味道”了。",
            ["DialogueId"] = 80010205,
            ["GUID"] = "C84C1242",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/002/C84C1242",
            },
        [80010206] = {
            ["Content"] = "呵呵……您或许误解她了。她不是无礼之徒，此举也绝非傲慢地越俎代庖。",
            ["DialogueId"] = 80010206,
            ["GUID"] = "C84C126C",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/002/C84C126C",
            },
        [80010207] = {
            ["Content"] = "呵呵……如果您是我，想必就不会说出这样的话了。",
            ["DialogueId"] = 80010207,
            ["GUID"] = "C84C1296",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/002/C84C1296",
            },
        [80010208] = {
            ["Content"] = "希尔妲是个敏锐的姑娘。她非常清楚，对我而言，拥有喜好，便意味着危险。",
            ["DialogueId"] = 80010208,
            ["GUID"] = "C84C12C0",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/002/C84C12C0",
            },
        [80010209] = {
            ["Content"] = "比如……我来问您一个问题。您看这杯酒——",
            ["DialogueId"] = 80010209,
            ["GUID"] = "C84C12EA",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/002/C84C12EA",
            },
        [80010210] = {
            ["Content"] = "假设我喜爱浸泡了罗勒叶和迷迭香的酒，每次都会一饮而尽，",
            ["DialogueId"] = 80010210,
            ["GUID"] = "C84C1314",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/002/C84C1314",
            },
        [80010211] = {
            ["Content"] = "而您又是一名受雇于主，混迹于一众家仆之中，想要夺取我性命的“窥伺者”，",
            ["DialogueId"] = 80010211,
            ["GUID"] = "C84C133E",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/002/C84C133E",
            },
        [80010212] = {
            ["Content"] = "您要如何忍住，不把那漂亮而致命的毒液涂抹在罗勒叶之上呢？",
            ["DialogueId"] = 80010212,
            ["GUID"] = "C84C1368",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/002/C84C1368",
            },
        [80010213] = {
            ["Content"] = "哦？我只是做个简单的比喻。难道您真的……",
            ["DialogueId"] = 80010213,
            ["GUID"] = "C84C1392",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/002/C84C1392",
            },
        [80010214] = {
            ["Content"] = "呵呵，别太紧张。我不会怀疑您。",
            ["DialogueId"] = 80010214,
            ["GUID"] = "C84C13BC",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/002/C84C13BC",
            },
        [80010215] = {
            ["Content"] = "的确……",
            ["DialogueId"] = 80010215,
            ["GUID"] = "C84C13E6",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/002/C84C13E6",
            },
        [80010216] = {
            ["Content"] = "在我身边环绕着的人……或许更应该称呼他们是兽群。",
            ["DialogueId"] = 80010216,
            ["GUID"] = "C84C1410",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/002/C84C1410",
            },
        [80010217] = {
            ["Content"] = "他们像是一群秃鹫，随时在等待着我停止挣扎的一刻，然后分食。",
            ["DialogueId"] = 80010217,
            ["GUID"] = "C84C143A",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/002/C84C143A",
            },
        }
  end },
  { MinKey = 80010218, MaxKey = 80030124, Loader = function()
      return {
        [80010218] = {
            ["Content"] = "迪斯玛尼亚的每一粒灵魂，包括我自己，都是污浊的。",
            ["DialogueId"] = 80010218,
            ["GUID"] = "C84C1464",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/002/C84C1464",
            },
        [80010219] = {
            ["Content"] = "呵呵……也许对您而言，漂泊在外意味着异邦的风土，喧哗而有趣的人们，焕然一新的人生。但至于我……",
            ["DialogueId"] = 80010219,
            ["GUID"] = "C84C148E",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/002/C84C148E",
            },
        [80010220] = {
            ["Content"] = "陌生的土地给了我片刻喘息，但我终究要到故乡。不过，并非因为我有多怀念它。",
            ["DialogueId"] = 80010220,
            ["GUID"] = "C84C14B8",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/002/C84C14B8",
            },
        [80010221] = {
            ["Content"] = "而是我全部的爱与憎恨，思念与愤怒，都在那个地方。",
            ["DialogueId"] = 80010221,
            ["GUID"] = "C84C14E2",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/002/C84C14E2",
            },
        [80010222] = {
            ["Content"] = "我该走了。还有……",
            ["DialogueId"] = 80010222,
            ["GUID"] = "C84C150C",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/002/C84C150C",
            },
        [80010223] = {
            ["Content"] = "尝得出，相比上次，您在调和时有意减淡了口味。",
            ["DialogueId"] = 80010223,
            ["GUID"] = "C84C1536",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/002/C84C1536",
            },
        [80010224] = {
            ["Content"] = "多谢您，将我的无意之言记挂在心。",
            ["DialogueId"] = 80010224,
            ["GUID"] = "C84C1560",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/002/C84C1560",
            },
        [80010301] = {
            ["Content"] = "尝得出，您调制饮品的手艺愈发娴熟，甚至达到了希尔妲五成的水准。",
            ["DialogueId"] = 80010301,
            ["GUID"] = "C84C2202",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/003/C84C2202",
            },
        [80010302] = {
            ["Content"] = "我不像希尔妲那样，擅长社交上的体面辞令。我的意思是，以她为基准的话，五成也已经很了不起了。",
            ["DialogueId"] = 80010302,
            ["GUID"] = "C84C222C",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/003/C84C222C",
            },
        [80010303] = {
            ["Content"] = "如果说有什么值得特别留意的……",
            ["DialogueId"] = 80010303,
            ["GUID"] = "C84C2256",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/003/C84C2256",
            },
        [80010304] = {
            ["Content"] = "那就是您过于平等地糅合了所有原料，反而让人无法品尝出它的基底——也就是，调制者最想要呈现的味道。",
            ["DialogueId"] = 80010304,
            ["GUID"] = "C84C2280",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/003/C84C2280",
            },
        [80010305] = {
            ["Content"] = "您近日心绪也有些乱。也许，忧虑太多纷杂的事，不如选择一件最重要的，细细研磨。",
            ["DialogueId"] = 80010305,
            ["GUID"] = "C84C22AA",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/003/C84C22AA",
            },
        [80010306] = {
            ["Content"] = "啊……",
            ["DialogueId"] = 80010306,
            ["GUID"] = "C84C22D4",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/003/C84C22D4",
            },
        [80010307] = {
            ["Content"] = "杯子……粘上了……抱歉，我并非有意弄脏它。",
            ["DialogueId"] = 80010307,
            ["GUID"] = "C84C22FE",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/003/C84C22FE",
            },
        [80010308] = {
            ["Content"] = "只是赴约之前，我刚刚完成那幅画。没有希尔妲提醒，我忘记手指沾了些颜料。",
            ["DialogueId"] = 80010308,
            ["GUID"] = "C84C2328",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/003/C84C2328",
            },
        [80010309] = {
            ["Content"] = "…………",
            ["DialogueId"] = 80010309,
            ["GUID"] = "C84C2352",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/003/C84C2352",
            },
        [80010310] = {
            ["Content"] = "是您的话，倒无妨。",
            ["DialogueId"] = 80010310,
            ["GUID"] = "C84C237C",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/003/C84C237C",
            },
        [80010311] = {
            ["Content"] = "过去吗？呵呵……如果这是真正的过去，就好了。",
            ["DialogueId"] = 80010311,
            ["GUID"] = "C84C23A6",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/003/C84C23A6",
            },
        [80010312] = {
            ["Content"] = "父亲、母亲……",
            ["DialogueId"] = 80010312,
            ["GUID"] = "C84C23D0",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/003/C84C23D0",
            },
        [80010313] = {
            ["Content"] = "其实我从未见过他们。",
            ["DialogueId"] = 80010313,
            ["GUID"] = "C84C23FA",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/003/C84C23FA",
            },
        [80010314] = {
            ["Content"] = "在我的居所，他们存在过的痕迹——连同他们的画像——都已经被残忍粗暴地抹去了。我只能通过老仆人的只言片语，去想象他们的样子。",
            ["DialogueId"] = 80010314,
            ["GUID"] = "C84C2424",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/003/C84C2424",
            },
        [80010315] = {
            ["Content"] = "年岁尚小的时候啊，我每天都在想，我总会与他们相见的。就在未来的某一天……",
            ["DialogueId"] = 80010315,
            ["GUID"] = "C84C244E",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/003/C84C244E",
            },
        [80010316] = {
            ["Content"] = "到那天，我们就可以像这样，邀来最优秀的画师，来为我们画一幅家族肖像。像那些可爱的三口之家一样。",
            ["DialogueId"] = 80010316,
            ["GUID"] = "C84C2478",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/003/C84C2478",
            },
        [80010317] = {
            ["Content"] = "但真正到了我能够把心中所思绘制在画布上的年纪，我才知道，我画的不是过去，亦非未来。",
            ["DialogueId"] = 80010317,
            ["GUID"] = "C84C24A2",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/003/C84C24A2",
            },
        [80010318] = {
            ["Content"] = "而是从未存在过，将来也不会存在的……",
            ["DialogueId"] = 80010318,
            ["GUID"] = "C84C24CC",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/003/C84C24CC",
            },
        [80010319] = {
            ["Content"] = "“泡影”。",
            ["DialogueId"] = 80010319,
            ["GUID"] = "C84C24F6",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/003/C84C24F6",
            },
        [80010320] = {
            ["Content"] = "嗯。也许您早已猜到，在我记事之前，他们已经是墓园的白骨。",
            ["DialogueId"] = 80010320,
            ["GUID"] = "C84C2520",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/003/C84C2520",
            },
        [80010321] = {
            ["Content"] = "抱歉，我不小心自顾自地说起来了，连带您的心情也变糟糕了吧。",
            ["DialogueId"] = 80010321,
            ["GUID"] = "C84C254A",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/003/C84C254A",
            },
        [80010322] = {
            ["Content"] = "您认真地准备了饮品和茶点，想必并非打算听我喋喋不休地叨念些不快的旧事。",
            ["DialogueId"] = 80010322,
            ["GUID"] = "C84C2574",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/003/C84C2574",
            },
        [80010323] = {
            ["Content"] = "我们来聊些其他的吧，比如珀西·巴莱德的诗集。",
            ["DialogueId"] = 80010323,
            ["GUID"] = "C84C259E",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/003/C84C259E",
            },
        [80010401] = {
            ["Content"] = "……您又邀请了我呢。真是奇怪。",
            ["DialogueId"] = 80010401,
            ["GUID"] = "C84C326A",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/004/C84C326A",
            },
        [80010402] = {
            ["Content"] = "我认为，我并不是一个可以给您带来欢愉的攀谈对象。",
            ["DialogueId"] = 80010402,
            ["GUID"] = "C84C3294",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/004/C84C3294",
            },
        [80010403] = {
            ["Content"] = "我今天读了一句诗：“好奇心会杀死一只知更鸟”……",
            ["DialogueId"] = 80010403,
            ["GUID"] = "C84C32BE",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/004/C84C32BE",
            },
        [80010404] = {
            ["Content"] = "罢了，既然您再度问起，那么我讲一个故事吧。",
            ["DialogueId"] = 80010404,
            ["GUID"] = "C84C32E8",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/004/C84C32E8",
            },
        [80010405] = {
            ["Content"] = "很久很久之前，有一个年轻的姑娘，她从出生起就住在一座黄金的牢笼里……",
            ["DialogueId"] = 80010405,
            ["GUID"] = "C84C3312",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/004/C84C3312",
            },
        [80010406] = {
            ["Content"] = "她似乎拥有世上的一切：她有一百顶镶着璀璨钻石的冠冕，有一百件皎洁珍珠编织的衣衫，有一百名仆人每天献上沾着晨露的鲜花……",
            ["DialogueId"] = 80010406,
            ["GUID"] = "C84C333C",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/004/C84C333C",
            },
        [80010407] = {
            ["Content"] = "但有一件东西是她始终得不到的：那就是黄金牢笼外的任何事物，哪怕是一滴雨，一缕风。",
            ["DialogueId"] = 80010407,
            ["GUID"] = "C84C3366",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/004/C84C3366",
            },
        [80010408] = {
            ["Content"] = "一个夜晚，一条陌生的龙闯进了黄金的牢笼。",
            ["DialogueId"] = 80010408,
            ["GUID"] = "C84C3390",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/004/C84C3390",
            },
        [80010409] = {
            ["Content"] = "她不知道那条龙硕大的身躯是如何钻进狭窄的栅栏，只知道它带来了她梦寐以求的一切——诗集，油彩，琴弦，剑术……以及她日思夜想的，牢笼之外的故事。",
            ["DialogueId"] = 80010409,
            ["GUID"] = "C84C33BA",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/004/C84C33BA",
            },
        [80010410] = {
            ["Content"] = "虽然身在牢笼之中，但她却从龙带来的故事里，看到了广阔的天空，触摸到旷野的清风，奔跑在金色的麦田，听到了广场上吟游诗人的歌谣。",
            ["DialogueId"] = 80010410,
            ["GUID"] = "C84C33E4",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/004/C84C33E4",
            },
        [80010411] = {
            ["Content"] = "她是如此感谢龙带给她的一切……",
            ["DialogueId"] = 80010411,
            ["GUID"] = "C84C340E",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/004/C84C340E",
            },
        [80010412] = {
            ["Content"] = "直到有一天，她无意间从传言中得知，正是那条龙，在她还在襁褓中时，灭亡了她的城市，杀死了她的亲生父亲……是的，它是一条恶龙。",
            ["DialogueId"] = 80010412,
            ["GUID"] = "C84C3438",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/004/C84C3438",
            },
        [80010413] = {
            ["Content"] = "然后，恶龙将她锁进了这座黄金的监牢。",
            ["DialogueId"] = 80010413,
            ["GUID"] = "C84C3462",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/004/C84C3462",
            },
        [80010414] = {
            ["Content"] = "少女将愤怒熔铸成刺剑，等待着恶龙再次踏着月色来访，她发誓将以利刃贯穿恶龙的心脏。但最后，她却犹疑了。她颤抖着询问传言的虚实，她渴望得到错误的答案。",
            ["DialogueId"] = 80010414,
            ["GUID"] = "C84C348C",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/004/C84C348C",
            },
        [80010415] = {
            ["Content"] = "但恶龙却亲口承认了一切。最后，她的剑只触及恶龙坚硬的鳞片。",
            ["DialogueId"] = 80010415,
            ["GUID"] = "C84C34B6",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/004/C84C34B6",
            },
        [80010416] = {
            ["Content"] = "不久之后，黄金囚笼里的吃穿用度，全部变了模样。每日奉上的鲜花，花蕾中再也不是晨露，而是毒刺。",
            ["DialogueId"] = 80010416,
            ["GUID"] = "C84C34E0",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/004/C84C34E0",
            },
        [80010417] = {
            ["Content"] = "终于有一天，一位聪明的女仆想方设法找到黄金的钥匙，打开了囚笼的门……女仆对少女说，她自由了。",
            ["DialogueId"] = 80010417,
            ["GUID"] = "C84C350A",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/004/C84C350A",
            },
        [80010418] = {
            ["Content"] = "但是少女知道，恶龙焚城的火焰在她的心底燃烧着，记忆的余烬环绕着她，将她投入深渊。她永远不会得到自由了。",
            ["DialogueId"] = 80010418,
            ["GUID"] = "C84C3534",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/004/C84C3534",
            },
        [80010419] = {
            ["Content"] = "嗯，很久之后我才得知，那两场<C=#FF0000>盛大的谋杀</C>。",
            ["DialogueId"] = 80010419,
            ["GUID"] = "C84C355E",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/004/C84C355E",
            },
        [80010420] = {
            ["Content"] = "从那之后，我的梦中永远是鲜血淋漓的身体，痛苦扭曲的面庞……每一晚，每一晚。",
            ["DialogueId"] = 80010420,
            ["GUID"] = "C84C3588",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/004/C84C3588",
            },
        [80010421] = {
            ["Content"] = "在用小刀划破自己皮肤的时候，我已经是那么痛了。那么被利剑贯穿的父亲，被埋在废墟中的母亲，该有多痛啊……",
            ["DialogueId"] = 80010421,
            ["GUID"] = "C84C35B2",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/004/C84C35B2",
            },
        [80010422] = {
            ["Content"] = "呵呵，您知道吗？您眼前的芙罗拉，并不是什么优雅高贵的贵族小姐……",
            ["DialogueId"] = 80010422,
            ["GUID"] = "C84C35DC",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/004/C84C35DC",
            },
        [80010423] = {
            ["Content"] = "她只是一个献祭生命也在所不惜的，复仇的恶鬼啊。",
            ["DialogueId"] = 80010423,
            ["GUID"] = "C84C3606",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/004/C84C3606",
            },
        [80010424] = {
            ["Content"] = "呵呵……呵呵呵。",
            ["DialogueId"] = 80010424,
            ["GUID"] = "C84C3630",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/004/C84C3630",
            },
        [80010425] = {
            ["Content"] = "{NickName}，我想，您拥有一位过于优秀的骑士。",
            ["DialogueId"] = 80010425,
            ["GUID"] = "C84C365A",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/004/C84C365A",
            },
        [80010426] = {
            ["Content"] = "贝蕾妮卡小姐，她把您护佑得多周全啊，无论是身体，还是灵魂。",
            ["DialogueId"] = 80010426,
            ["GUID"] = "C84C3684",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/004/C84C3684",
            },
        [80010427] = {
            ["Content"] = "“新的人生”……好漂亮的愿望，就像孩子们吹出的肥皂泡……",
            ["DialogueId"] = 80010427,
            ["GUID"] = "C84C36AE",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/004/C84C36AE",
            },
        [80010428] = {
            ["Content"] = "呵呵……呵呵呵。",
            ["DialogueId"] = 80010428,
            ["GUID"] = "C84C36D8",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/004/C84C36D8",
            },
        [80010429] = {
            ["Content"] = "{NickName}，您真的是一个过于天真的家伙。",
            ["DialogueId"] = 80010429,
            ["GUID"] = "C84C3702",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/004/C84C3702",
            },
        [80010430] = {
            ["Content"] = "以至于，您可以笃定地认为，您有资格对抗我所对抗的东西。",
            ["DialogueId"] = 80010430,
            ["GUID"] = "C84C372C",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/004/C84C372C",
            },
        [80010431] = {
            ["Content"] = "您不知道，那是一个怎样的<C=#FF0000>“怪物”</C>……",
            ["DialogueId"] = 80010431,
            ["GUID"] = "C84C3756",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/004/C84C3756",
            },
        [80010432] = {
            ["Content"] = "…………",
            ["DialogueId"] = 80010432,
            ["GUID"] = "C84C3780",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/004/C84C3780",
            },
        [80010433] = {
            ["Content"] = "失礼了，我今天说了太多错误的言辞。",
            ["DialogueId"] = 80010433,
            ["GUID"] = "C84C37AA",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/004/C84C37AA",
            },
        [80010434] = {
            ["Content"] = "把这一切都忘了吧。或者，请您只当它是从某本小说里读来的传奇故事。",
            ["DialogueId"] = 80010434,
            ["GUID"] = "C84C37D4",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/004/C84C37D4",
            },
        [80010435] = {
            ["Content"] = "以及，不要再邀请我赴约了。这样，我还可以视您为一名值得尊敬的受托人。",
            ["DialogueId"] = 80010435,
            ["GUID"] = "C84C37FE",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/004/C84C37FE",
            },
        [80010436] = {
            ["Content"] = "只是这样……就好。",
            ["DialogueId"] = 80010436,
            ["GUID"] = "C84C3828",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/004/C84C3828",
            },
        [80010501] = {
            ["Content"] = "我应该说过，请您不要再邀请我。",
            ["DialogueId"] = 80010501,
            ["GUID"] = "C84C42D2",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/005/C84C42D2",
            },
        [80010502] = {
            ["Content"] = "如果事关我们的契约，谈判桌远比这里更加合适。",
            ["DialogueId"] = 80010502,
            ["GUID"] = "C84C42FC",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/005/C84C42FC",
            },
        [80010503] = {
            ["Content"] = "呵……",
            ["DialogueId"] = 80010503,
            ["GUID"] = "C84C4326",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/005/C84C4326",
            },
        [80010504] = {
            ["Content"] = "我想，上次我已经给了您清楚的回答。",
            ["DialogueId"] = 80010504,
            ["GUID"] = "C84C4350",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/005/C84C4350",
            },
        [80010505] = {
            ["Content"] = "回去吧。我的前路没有过去，也没有未来。只有紧紧闭锁的漆黑深渊。",
            ["DialogueId"] = 80010505,
            ["GUID"] = "C84C437A",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/005/C84C437A",
            },
        [80010506] = {
            ["Content"] = "即使是您放声呼喊，也无法将我从那里带回。",
            ["DialogueId"] = 80010506,
            ["GUID"] = "C84C43A4",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/005/C84C43A4",
            },
        [80010507] = {
            ["Content"] = "…………",
            ["DialogueId"] = 80010507,
            ["GUID"] = "C84C43CE",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/005/C84C43CE",
            },
        [80010508] = {
            ["Content"] = "…………",
            ["DialogueId"] = 80010508,
            ["GUID"] = "C84C43F8",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/005/C84C43F8",
            },
        [80010509] = {
            ["Content"] = "你……",
            ["DialogueId"] = 80010509,
            ["GUID"] = "C84C4422",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/005/C84C4422",
            },
        [80010510] = {
            ["Content"] = "哪来的笨蛋{性别：先生|小姐}，幼稚鬼，秽兽一样的脑袋！你以为你是什么人？传奇小说里的屠龙勇士，神眷之子？少做白日梦了！我们的契约只是要你帮我找东西，可没约定过这种事！",
            ["DialogueId"] = 80010510,
            ["GUID"] = "C84C444C",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/005/C84C444C",
            },
        [80010511] = {
            ["Content"] = "你知道我的仇人是什么家伙吗？别犯蠢了，他一秒钟，一句话，就足以要你的命。",
            ["DialogueId"] = 80010511,
            ["GUID"] = "C84C4476",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/005/C84C4476",
            },
        [80010512] = {
            ["Content"] = "……失礼了。",
            ["DialogueId"] = 80010512,
            ["GUID"] = "C84C44A0",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/005/C84C44A0",
            },
        [80010513] = {
            ["Content"] = "您……在说些什么。",
            ["DialogueId"] = 80010513,
            ["GUID"] = "C84C44CA",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/005/C84C44CA",
            },
        [80010514] = {
            ["Content"] = "我希望可以成为芙罗拉的朋友，而非仅仅是受托人。不……甚至不只是朋友，而是可以共享哀乐，共享命运的人。",
            ["DialogueId"] = 80010514,
            ["GUID"] = "C84C44CB",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/005/C84C44CB",
            },
        [80010515] = {
            ["Content"] = "所以，如果我没有可以将芙罗拉带回的绳索，那就让我也一起跳下去吧。",
            ["DialogueId"] = 80010515,
            ["GUID"] = "C84C44CC",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/005/C84C44CC",
            },
        [80010516] = {
            ["Content"] = "我不是什么诸神眷顾的屠龙勇者，但我可以和你一起战斗至最后一刻。",
            ["DialogueId"] = 80010516,
            ["GUID"] = "C84C44CD",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/005/C84C44CD",
            },
        [80010517] = {
            ["Content"] = "哪怕最终你的剑折断了，至少还有人可以陪你一起躺在血泊里，而不是让你孤独一人面对死亡。",
            ["DialogueId"] = 80010517,
            ["GUID"] = "C84C44CE",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/005/C84C44CE",
            },
        [80010518] = {
            ["Content"] = "…………",
            ["DialogueId"] = 80010518,
            ["GUID"] = "C84C44F4",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/005/C84C44F4",
            },
        [80010519] = {
            ["Content"] = "真是……愚蠢啊。",
            ["DialogueId"] = 80010519,
            ["GUID"] = "C84C451E",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/005/C84C451E",
            },
        [80010520] = {
            ["Content"] = "说到这份上，我要用什么办法才能甩掉你呢……",
            ["DialogueId"] = 80010520,
            ["GUID"] = "C84C4548",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/005/C84C4548",
            },
        [80010521] = {
            ["Content"] = "我没有过去，也没有未来。",
            ["DialogueId"] = 80010521,
            ["GUID"] = "C84C4572",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/005/C84C4572",
            },
        [80010522] = {
            ["Content"] = "除了千疮百孔的灵魂，一无所有。",
            ["DialogueId"] = 80010522,
            ["GUID"] = "C84C459C",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/005/C84C459C",
            },
        [80010523] = {
            ["Content"] = "既然你来了……那就和我一起，行走在鲜血淋漓的“现在”吧。",
            ["DialogueId"] = 80010523,
            ["GUID"] = "C84C45C6",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/005/C84C45C6",
            },
        [80010524] = {
            ["Content"] = "直到那漆黑之物杀死我们，或者我们杀死它。",
            ["DialogueId"] = 80010524,
            ["GUID"] = "C84C45F0",
            ["VoiceName"] = "voice/$Locale$/inv/Fuluo/005/C84C45F0",
            },
        [80020100] = {
            ["Content"] = "没有委托的话，我们似乎不需要那么多的闲聊。当然，如果委托的内容就是谈话，那么也没问题，支付一点佣金，我们就可以友好相处。",
            ["ContentFR"] = "À moins que vous n’ayez une mission pour moi, inutile de bavarder. Mais si votre requête consiste à simplement discuter, un petit tarif pour mes services et je vous tiendrai compagnie.",
            ["DialogueId"] = 80020100,
            ["GUID"] = "C85269A8",
            ["SpeakNpcId"] = 93102,
            ["VoiceName"] = "voice/$Locale$/inv/Xier/001/C85269A8",
            },
        [80020201] = {
            ["Camera"] = "106.860352,-6.606262,134.715088,0.0,-0.99996,-137.196014,30.0,125.0,false,Manual,2.8",
            ["Content"] = "呼，真羡慕您，居然有闲心邀请人来喝点什么。",
            ["ContentFR"] = "Hmpf, je vous envie. Avoir le loisir d’inviter quelqu’un pour prendre un verre...",
            ["DialogueId"] = 80020201,
            ["FacialId"] = {
                [1] = "93102:Smile02",
                },
            ["GUID"] = "C8527A3A",
            ["LookAt"] = {
                [1] = "93102:p(18000P1)",
                },
            ["NextDialogue"] = 80020202,
            ["SpeakNpcId"] = 93102,
            ["TalkActionId"] = {
                [1] = "93102:Sit_Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xier/002/C8527A3A",
            },
        [80020202] = {
            ["Content"] = "而我呢，刚刚完成一份委托，从更北边的地方回来。感觉浑身的骨头都快散架啦，需要睡上一整个晚上连带白天才复活。",
            ["ContentFR"] = "Je reviens à peine d’une mission dans le grand nord. J’ai l’impression que mes os vont se désarticuler. Il me faudra une nuit entière, et toute la journée suivante, pour m’en remettre.",
            ["DialogueId"] = 80020202,
            ["GUID"] = "C8527A64",
            ["NextOptions"] = {
                [1] = 800202021,
                [2] = 800202022,
                },
            ["SpeakNpcId"] = 93102,
            ["TalkActionId"] = {
                [1] = "93102:Sit_Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xier/002/C8527A64",
            },
        [80020203] = {
            ["Content"] = "不用，都坐下了。来上一杯再去睡觉吧。",
            ["ContentFR"] = "Ce n’est pas la peine, je suis déjà installée. Autant boire un verre avant d’aller dormir.",
            ["DialogueId"] = 80020203,
            ["FacialId"] = {
                [1] = "93102:None",
                },
            ["GUID"] = "C8527A8E",
            ["NextDialogue"] = 80020205,
            ["SpeakNpcId"] = 93102,
            ["VoiceName"] = "voice/$Locale$/inv/Xier/002/C8527A8E",
            },
        [80020204] = {
            ["Content"] = "唔，要不您帮我完成一次委托试试？",
            ["ContentFR"] = "Peut-être. Ou alors vous pourriez prendre en charge une de mes prochaines missions ?",
            ["DialogueId"] = 80020204,
            ["FacialId"] = {
                [1] = "93102:None",
                },
            ["GUID"] = "C8527AB8",
            ["NextDialogue"] = 80020205,
            ["SpeakNpcId"] = 93102,
            ["VoiceName"] = "voice/$Locale$/inv/Xier/002/C8527AB8",
            },
        [80020205] = {
            ["Content"] = "唉，下次再遇到这个雇主的委托还是直接拒绝好了。虽然给的报酬足够多，但还是有点危险。",
            ["ContentFR"] = "Eh bien, la prochaine fois que ce client me propose une mission, je la refuserai carrément. Même si la paye est bonne, c’est quand même un peu trop risqué.",
            ["DialogueId"] = 80020205,
            ["GUID"] = "C8527AE2",
            ["NextDialogue"] = 80020206,
            ["SpeakNpcId"] = 93102,
            ["VoiceName"] = "voice/$Locale$/inv/Xier/002/C8527AE2",
            },
        [80020206] = {
            ["Content"] = "她让我带着她的亲笔信回到故乡，向她的一些热衷于暴力的亲属们递交一封满是脏话与挑衅的信件，好让愤怒冲昏他们的头脑。",
            ["ContentFR"] = "Elle m’a fait livrer une lettre, plutôt insultante, à ses proches amateurs de violence, juste pour les mettre en colère.",
            ["DialogueId"] = 80020206,
            ["GUID"] = "C8527B0C",
            ["NextDialogue"] = 80020207,
            ["SpeakNpcId"] = 93102,
            ["TalkActionId"] = {
                [1] = "93102:Sit_Talk02R_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xier/002/C8527B0C",
            },
        [80020207] = {
            ["Content"] = "但是身为信差的我得在递信结束的那一刻立刻逃走，避免被那些从来都是鼻孔朝天，没被人骂过的暴力分子们当场射杀。",
            ["ContentFR"] = "En tant que messagère, il fallait que je me sauve aussitôt après la livraison, sinon ces brutes, qui n’ont sûrement jamais été insultées, m’auraient tiré dessus.",
            ["DialogueId"] = 80020207,
            ["FacialId"] = {
                [1] = "93102:Uninterested01",
                },
            ["GUID"] = "C8527B36",
            ["NextDialogue"] = 80020208,
            ["SpeakNpcId"] = 93102,
            ["TalkActionId"] = {
                [1] = "93102:Sit_Talk02R_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xier/002/C8527B36",
            },
        [80020208] = {
            ["Content"] = "然后在雪地里走上一整夜，免得那些家伙想在几处必经之路上拦下我。虽然让他们流血很简单，但是干掉他们也没人给我加佣金……",
            ["ContentFR"] = "Puis, j’ai dû passer une nuit entière à marcher dans la neige pour éviter leurs embuscades. Évidemment, les éliminer serait facile, mais personne ne paie pour ça...",
            ["DialogueId"] = 80020208,
            ["GUID"] = "C8527B60",
            ["NextDialogue"] = 80020209,
            ["SpeakNpcId"] = 93102,
            ["TalkActionId"] = {
                [1] = "93102:Sit_Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xier/002/C8527B60",
            },
        [80020209] = {
            ["Content"] = "嗯？您干嘛瞪圆了眼睛？",
            ["ContentFR"] = "Hein ? Pourquoi cet air si surpris ?",
            ["DialogueId"] = 80020209,
            ["FacialId"] = {
                [1] = "93102:Shock02",
                },
            ["GUID"] = "C8527B8A",
            ["NextOptions"] = {
                [1] = 800202091,
                [2] = 800202092,
                },
            ["SpeakNpcId"] = 93102,
            ["TalkActionId"] = {
                [1] = "93102:Sit_Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xier/002/C8527B8A",
            },
        [80020210] = {
            ["Content"] = "那当然是的，至少现在是的。",
            ["ContentFR"] = "Bien sûr, du moins pour le moment.",
            ["DialogueId"] = 80020210,
            ["FacialId"] = {
                [1] = "93102:None",
                },
            ["GUID"] = "C8527BB4",
            ["NextDialogue"] = 80020212,
            ["SpeakNpcId"] = 93102,
            ["VoiceName"] = "voice/$Locale$/inv/Xier/002/C8527BB4",
            },
        [80020211] = {
            ["Content"] = "没事，过去有过更危险的经历。",
            ["ContentFR"] = "J’ai connu pire.",
            ["DialogueId"] = 80020211,
            ["FacialId"] = {
                [1] = "93102:None",
                },
            ["GUID"] = "C8527BDE",
            ["NextDialogue"] = 80020212,
            ["SpeakNpcId"] = 93102,
            ["VoiceName"] = "voice/$Locale$/inv/Xier/002/C8527BDE",
            },
        [80020212] = {
            ["Content"] = "在我成为芙罗拉小姐的女仆之前呢，确实还短暂地干过另外一份工作，现在的很多用得上用不上的技巧都是在那时候习得的。",
            ["ContentFR"] = "Avant de devenir la servante de Mlle Flora, j’ai eu un autre métier, bref mais intense. Beaucoup de mes compétences viennent de cette époque.",
            ["DialogueId"] = 80020212,
            ["GUID"] = "C8527C08",
            ["NextDialogue"] = 80020213,
            ["SpeakNpcId"] = 93102,
            ["VoiceName"] = "voice/$Locale$/inv/Xier/002/C8527C08",
            },
        [80020213] = {
            ["Content"] = "比如快速拆解枪械的方法啊、如何从花草中萃取出毒药啊、能够在三秒内将人击晕又不至于有生命危险的格斗术啊……",
            ["ContentFR"] = "Par exemple, démonter rapidement une arme à feu, extraire des poisons des plantes, ou neutraliser quelqu’un en trois secondes sans le tuer...",
            ["DialogueId"] = 80020213,
            ["GUID"] = "C8527C32",
            ["NextDialogue"] = 80020214,
            ["SpeakNpcId"] = 93102,
            ["TalkActionId"] = {
                [1] = "93102:Sit_Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xier/002/C8527C32",
            },
        [80020214] = {
            ["Content"] = "算了，既然您身为我的长期合作对象，那么也没有必要向您隐瞒，实际上，我过去是一名密探。",
            ["ContentFR"] = "Puisque vous êtes un client fidèle, je peux vous l’avouer : j’étais agent.",
            ["DialogueId"] = 80020214,
            ["FacialId"] = {
                [1] = "93102:Confident02",
                },
            ["GUID"] = "C8527C5C",
            ["NextDialogue"] = 80020215,
            ["SpeakNpcId"] = 93102,
            ["TalkActionId"] = {
                [1] = "93102:Sit_Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xier/002/C8527C5C",
            },
        [80020215] = {
            ["Content"] = "也有人管我们叫做特工，间谍，不过称呼并不重要，总的来说，就是一群在阴影之中，不能以真面目示人的家伙们。",
            ["ContentFR"] = "Certains nous appellent espions ou agents secrets, mais peu importe le titre. Nous sommes ces ombres furtives que personne ne remarque vraiment.",
            ["DialogueId"] = 80020215,
            ["GUID"] = "C8527C86",
            ["NextDialogue"] = 80020216,
            ["SpeakNpcId"] = 93102,
            ["TalkActionId"] = {
                [1] = "93102:Sit_Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xier/002/C8527C86",
            },
        [80020216] = {
            ["Content"] = "即便您和他们擦肩而过，您也只会觉得他们是匆忙的行路人，而实际上，他们也许正准备去制造一场混乱，或是去传递秘密消息。",
            ["ContentFR"] = "Vous pourriez croiser l’un d’entre nous dans la rue sans le remarquer, alors qu’il est en route pour semer le chaos ou transmettre un secret.",
            ["DialogueId"] = 80020216,
            ["FacialId"] = {
                [1] = "93102:None",
                },
            ["GUID"] = "C8527CB0",
            ["NextOptions"] = {
                [1] = 800202161,
                [2] = 800202162,
                },
            ["SpeakNpcId"] = 93102,
            ["TalkActionId"] = {
                [1] = "93102:Sit_Talk02_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xier/002/C8527CB0",
            },
        [80020217] = {
            ["Content"] = "我曾经也有过这样的憧憬，不过事实并非如此。",
            ["ContentFR"] = "J’ai eu cette illusion aussi, mais la réalité est bien différente.",
            ["DialogueId"] = 80020217,
            ["FacialId"] = {
                [1] = "93102:Sad01",
                },
            ["GUID"] = "C8527CDA",
            ["NextDialogue"] = 80020219,
            ["SpeakNpcId"] = 93102,
            ["VoiceName"] = "voice/$Locale$/inv/Xier/002/C8527CDA",
            },
        [80020218] = {
            ["Content"] = "嗯，听上去很刺激，实际上困难如影随形。",
            ["ContentFR"] = "En effet, cela peut sembler passionnant, mais en réalité, cela comporte de nombreux défis et risques.",
            ["DialogueId"] = 80020218,
            ["FacialId"] = {
                [1] = "93102:Sad01",
                },
            ["GUID"] = "C8527D04",
            ["NextDialogue"] = 80020219,
            ["SpeakNpcId"] = 93102,
            ["VoiceName"] = "voice/$Locale$/inv/Xier/002/C8527D04",
            },
        [80020219] = {
            ["Content"] = "大部分密探都是隶属于军团，没法挣脱，只能听从军团的命令，甚至可能要对自己的亲人痛下杀手。",
            ["ContentFR"] = "La plupart des espions dépendent de leur légion, prisonniers de leurs ordres, parfois contraints de tuer même leurs proches.",
            ["DialogueId"] = 80020219,
            ["FacialId"] = {
                [1] = "93102:None",
                },
            ["GUID"] = "C8527D2E",
            ["NextDialogue"] = 80020220,
            ["SpeakNpcId"] = 93102,
            ["VoiceName"] = "voice/$Locale$/inv/Xier/002/C8527D2E",
            },
        [80020220] = {
            ["Content"] = "至于我嘛，受不了这么多条条框框，所以想了个法子逃走了。",
            ["ContentFR"] = "Je ne supportais plus toutes ces règles et restrictions, alors j’ai trouvé un moyen de m’en libérer.",
            ["DialogueId"] = 80020220,
            ["GUID"] = "C8527D58",
            ["NextDialogue"] = 80020221,
            ["SpeakNpcId"] = 93102,
            ["TalkActionId"] = {
                [1] = "93102:Sit_Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xier/002/C8527D58",
            },
        [80020221] = {
            ["Content"] = "逃走的过程当然不是轻描淡写，不过嘛，您的这杯饮料没法换到我的那段经历。",
            ["ContentFR"] = "Mon évasion fut épique, mais je doute qu’un verre suffise à vous raconter ça.",
            ["DialogueId"] = 80020221,
            ["FacialId"] = {
                [1] = "93102:Syouganai01",
                },
            ["GUID"] = "C8527D82",
            ["NextDialogue"] = 80020222,
            ["SpeakNpcId"] = 93102,
            ["VoiceName"] = "voice/$Locale$/inv/Xier/002/C8527D82",
            },
        [80020222] = {
            ["Content"] = "我该睡觉啦，睡醒了还要帮芙罗拉小姐准备明天的早餐，她得有三四天没吃到我做的甜点了。",
            ["ContentFR"] = "Il est temps pour moi d’aller dormir. Demain, je dois préparer le petit-déjeuner de Mlle Flora. Elle n’a pas goûté à mes desserts depuis plusieurs jours.",
            ["DialogueId"] = 80020222,
            ["FacialId"] = {
                [1] = "93102:None",
                },
            ["GUID"] = "C8527DAC",
            ["NextDialogue"] = 80020223,
            ["SpeakNpcId"] = 93102,
            ["TalkActionId"] = {
                [1] = "93102:Sit_Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xier/002/C8527DAC",
            },
        [80020223] = {
            ["Content"] = "作为这杯饮料的答谢，到时候我也会给您分上一块蛋糕。",
            ["ContentFR"] = "En échange de ce verre, je vous garderai une part de gâteau.",
            ["DialogueId"] = 80020223,
            ["FacialId"] = {
                [1] = "93102:Satisfy01",
                },
            ["GUID"] = "C8527DD6",
            ["NextDialogue"] = 80020224,
            ["SpeakNpcId"] = 93102,
            ["VoiceName"] = "voice/$Locale$/inv/Xier/002/C8527DD6",
            },
        [80020224] = {
            ["Content"] = "那么，晚安。",
            ["ContentFR"] = "Sur ce, bonne nuit.",
            ["DialogueId"] = 80020224,
            ["FacialId"] = {
                [1] = "93102:None",
                },
            ["GUID"] = "C8527E00",
            ["SpeakNpcId"] = 93102,
            ["VoiceName"] = "voice/$Locale$/inv/Xier/002/C8527E00",
            },
        [80020301] = {
            ["Camera"] = "106.860352,-6.606262,134.715088,0.0,-0.99996,-137.196014,30.0,125.0,false,Manual,2.8",
            ["Content"] = "今天难得有一些空闲时间，可以陪您多喝几杯。",
            ["ContentFR"] = "Aujourd’hui, j’ai enfin un peu de temps libre. Je peux vous tenir compagnie pour quelques verres de plus.",
            ["DialogueId"] = 80020301,
            ["FacialId"] = {
                [1] = "93102:Satisfy01",
                },
            ["GUID"] = "C8528AA2",
            ["LookAt"] = {
                [1] = "93102:p(18000P1)",
                },
            ["NextDialogue"] = 80020302,
            ["SpeakNpcId"] = 93102,
            ["TalkActionId"] = {
                [1] = "93102:Sit_Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xier/003/C8528AA2",
            },
        [80020302] = {
            ["Content"] = "等喝完后，我就打算出门逛上一逛。之前接了那么多委托，富余的银币总是有那么几枚的。",
            ["ContentFR"] = "Après ça, je comptais faire un tour en ville. Avec toutes les missions que j’ai remplies dernièrement, il me reste quelques pièces d’argent à dépenser.",
            ["DialogueId"] = 80020302,
            ["GUID"] = "C8528ACC",
            ["NextOptions"] = {
                [1] = 800203021,
                [2] = 800203022,
                },
            ["SpeakNpcId"] = 93102,
            ["TalkActionId"] = {
                [1] = "93102:Sit_Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xier/003/C8528ACC",
            },
        [80020303] = {
            ["Content"] = "好啊，我可以为您挑选几件合身的衣服。",
            ["ContentFR"] = "Bien sûr. Je pourrai même vous aider à choisir quelques tenues qui vous iraient bien.",
            ["DialogueId"] = 80020303,
            ["FacialId"] = {
                [1] = "93102:Smile02",
                },
            ["GUID"] = "C8528AF6",
            ["NextDialogue"] = 80020305,
            ["SpeakNpcId"] = 93102,
            ["TalkActionId"] = {
                [1] = "93102:Sit_AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xier/003/C8528AF6",
            },
        [80020304] = {
            ["Content"] = "会啊，我还会吃饭、睡觉——很正常。",
            ["ContentFR"] = "Évidemment. Je mange, je dors, je respire aussi, rien de plus normal.",
            ["DialogueId"] = 80020304,
            ["FacialId"] = {
                [1] = "93102:Smile02",
                },
            ["GUID"] = "C8528B20",
            ["NextDialogue"] = 80020305,
            ["SpeakNpcId"] = 93102,
            ["TalkActionId"] = {
                [1] = "93102:Sit_AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xier/003/C8528B20",
            },
        [80020305] = {
            ["Content"] = "逛街对我来说是最简单直接的放松方式了：既不需要太多思考，还能呼吸新鲜空气，并且还能穿着自己喜欢的衣服——我可没多少这样的机会。",
            ["ContentFR"] = "Faire les boutiques, pour moi, c’est la manière la plus simple et directe de me détendre : pas besoin de réfléchir, je prends l’air, et je peux enfin porter ce qui me plaît, ce qui n’arrive pas souvent.",
            ["DialogueId"] = 80020305,
            ["GUID"] = "C8528B4A",
            ["NextDialogue"] = 80020306,
            ["SpeakNpcId"] = 93102,
            ["TalkActionId"] = {
                [1] = "93102:Sit_Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xier/003/C8528B4A",
            },
        [80020306] = {
            ["Content"] = "工作的时候，我要么穿着女仆装，要么是那种又厚实，口袋又多的大风衣，来装下可能会用到的各种小工具。",
            ["ContentFR"] = "En mission, je porte soit ma tenue de servante, soit un long manteau épais rempli de poches, pour y glisser tous les petits outils dont je pourrais avoir besoin.",
            ["DialogueId"] = 80020306,
            ["FacialId"] = {
                [1] = "93102:Smile02",
                },
            ["GUID"] = "C8528B74",
            ["NextDialogue"] = 80020307,
            ["SpeakNpcId"] = 93102,
            ["TalkActionId"] = {
                [1] = "93102:Sit_Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xier/003/C8528B74",
            },
        [80020307] = {
            ["Content"] = "以及为了不引人注目，执行委托的时候我会把头发束起来，您也知道，红色头发很显眼的。",
            ["ContentFR"] = "Et pour ne pas attirer l’attention, j’attache toujours mes cheveux. Vous le savez, une chevelure rouge, ça se remarque très vite.",
            ["DialogueId"] = 80020307,
            ["GUID"] = "C8528B9E",
            ["NextDialogue"] = 80020308,
            ["SpeakNpcId"] = 93102,
            ["VoiceName"] = "voice/$Locale$/inv/Xier/003/C8528B9E",
            },
        [80020308] = {
            ["Content"] = "但出门逛街的时候就不用在意这些，可以穿更加浅色的罩衫。",
            ["ContentFR"] = "Mais pour flâner en ville, je peux me permettre un peu plus de liberté. J’opte alors pour des tuniques claires.",
            ["DialogueId"] = 80020308,
            ["FacialId"] = {
                [1] = "93102:Happy01",
                },
            ["GUID"] = "C8528BC8",
            ["NextDialogue"] = 80020309,
            ["SpeakNpcId"] = 93102,
            ["TalkActionId"] = {
                [1] = "93102:Sit_Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xier/003/C8528BC8",
            },
        [80020309] = {
            ["Content"] = "浅色的衣服会和头发的颜色很相衬，不过和芙罗拉小姐一起出门的时候，我会再戴一顶帽子。",
            ["ContentFR"] = "Les tons clairs mettent bien en valeur mes cheveux. Même si, lorsque je sors avec Mlle Flora, je préfère quand même porter un chapeau.",
            ["DialogueId"] = 80020309,
            ["GUID"] = "C8528BF2",
            ["NextDialogue"] = 80020310,
            ["SpeakNpcId"] = 93102,
            ["VoiceName"] = "voice/$Locale$/inv/Xier/003/C8528BF2",
            },
        [80020310] = {
            ["Content"] = "但是鞋子我会无论如何都选暗红色的，唔，打个比方的话，就像是红色基底的蛋糕总是要缀上些红色莓果一样。",
            ["ContentFR"] = "Quant aux chaussures, je choisis toujours du rouge sombre. Un peu comme un gâteau au velours rouge : il faut bien quelques fruits rouges pour le parfaire.",
            ["DialogueId"] = 80020310,
            ["FacialId"] = {
                [1] = "93102:Smile02",
                },
            ["GUID"] = "C8528C1C",
            ["NextDialogue"] = 80020311,
            ["SpeakNpcId"] = 93102,
            ["TalkActionId"] = {
                [1] = "93102:Sit_Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xier/003/C8528C1C",
            },
        [80020311] = {
            ["Content"] = "再配上从织星客那里买到的香薰呀，带着东方纹路的首饰呀，感觉整个人的心情都会好上许多。",
            ["ContentFR"] = "J’ajoute à ça un peu de parfum des Tisse-Étoiles, et quelques bijoux aux motifs venus d’ailleurs, de quoi me mettre de bonne humeur pour la journée.",
            ["DialogueId"] = 80020311,
            ["GUID"] = "C8528C46",
            ["NextDialogue"] = 80020312,
            ["SpeakNpcId"] = 93102,
            ["VoiceName"] = "voice/$Locale$/inv/Xier/003/C8528C46",
            },
        [80020312] = {
            ["Content"] = "而像您这样，有着浅色的银发，就最好搭上明亮的衣服，想必也会显得更有活力一点。",
            ["ContentFR"] = "Avec vos cheveux argentés, porter des tons lumineux vous donnerait sans doute un air plus vif et énergique.",
            ["DialogueId"] = 80020312,
            ["GUID"] = "C8528C70",
            ["NextOptions"] = {
                [1] = 800203121,
                [2] = 800203122,
                },
            ["SpeakNpcId"] = 93102,
            ["TalkActionId"] = {
                [1] = "93102:Sit_Talk02R_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xier/003/C8528C70",
            },
        [80020313] = {
            ["Content"] = "诶？我还以为很容易理解呢。",
            ["ContentFR"] = "Hein ? Je pensais que c’était évident.",
            ["DialogueId"] = 80020313,
            ["FacialId"] = {
                [1] = "93102:Shock02",
                },
            ["GUID"] = "C8528C9A",
            ["NextDialogue"] = 80020315,
            ["SpeakNpcId"] = 93102,
            ["TalkActionId"] = {
                [1] = "93102:Sit_Talk02R_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xier/003/C8528C9A",
            },
        [80020314] = {
            ["Content"] = "对吧，您也可以试试这样。",
            ["ContentFR"] = "N’est-ce pas ? Vous devriez essayer aussi.",
            ["DialogueId"] = 80020314,
            ["FacialId"] = {
                [1] = "93102:Smile02",
                },
            ["GUID"] = "C8528CC4",
            ["NextDialogue"] = 80020315,
            ["SpeakNpcId"] = 93102,
            ["TalkActionId"] = {
                [1] = "93102:Sit_Talk02R_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xier/003/C8528CC4",
            },
        [80020315] = {
            ["Content"] = "不过，我最初注意到这些也是因为密探的工作。密探们多少都要学习一些易容术，要让自己看起来是另外一个人。",
            ["ContentFR"] = "En fait, à l’origine, si je fais attention à tout ça, c’est à cause de mon ancien travail. Un bon agent doit savoir se transformer en quelqu’un d’autre.",
            ["DialogueId"] = 80020315,
            ["FacialId"] = {
                [1] = "93102:None",
                },
            ["GUID"] = "C8528CEE",
            ["NextDialogue"] = 80020316,
            ["SpeakNpcId"] = 93102,
            ["VoiceName"] = "voice/$Locale$/inv/Xier/003/C8528CEE",
            },
        [80020316] = {
            ["Content"] = "于是我就从最基础的开始学起，街边卖花的小姑娘啊、身上首饰比衣服还重的贵族妻子呀、看起来会被风吹倒的老妇人呀，必要时还会扮演一些“公主”或者“王子”。",
            ["ContentFR"] = "Alors j’ai commencé par les bases : une petite marchande de fleurs, une noble couverte de bijoux, une vieille femme chancelante... ou même, parfois, un \"prince\" ou une \"princesse\".",
            ["DialogueId"] = 80020316,
            ["FacialId"] = {
                [1] = "93102:Confident01",
                },
            ["GUID"] = "C8528D18",
            ["NextOptions"] = {
                [1] = 800203161,
                },
            ["SpeakNpcId"] = 93102,
            ["TalkActionId"] = {
                [1] = "93102:Sit_Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xier/003/C8528D18",
            },
        [80020317] = {
            ["Content"] = "是啊，只要不开口说话就不会被认出来，甚至有几位贵族小姐送了我手帕，挺有趣的。",
            ["ContentFR"] = "Oui. Tant que je ne parlais pas, personne ne remarquait rien. Il y a même eu quelques demoiselles de bonne famille qui m’ont offert leurs mouchoirs... C’était plutôt amusant.",
            ["DialogueId"] = 80020317,
            ["FacialId"] = {
                [1] = "93102:Smile02",
                },
            ["GUID"] = "C8528D42",
            ["NextDialogue"] = 80020318,
            ["SpeakNpcId"] = 93102,
            ["TalkActionId"] = {
                [1] = "93102:Sit_Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xier/003/C8528D42",
            },
        [80020318] = {
            ["Content"] = "而这样的次数多了以后，我发现，当易容成其他人的时候，心情也会受到影响。甚至，一条裙子，一件耳饰，都可以是心情变好的契机。",
            ["ContentFR"] = "Et à force de changer d’apparence, j’ai remarqué que mon humeur changeait aussi. Une robe, une paire de boucles d’oreilles... parfois, il ne faut pas plus pour vous redonner le sourire.",
            ["DialogueId"] = 80020318,
            ["GUID"] = "C8528D6C",
            ["NextDialogue"] = 80020319,
            ["SpeakNpcId"] = 93102,
            ["TalkActionId"] = {
                [1] = "93102:Sit_Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xier/003/C8528D6C",
            },
        [80020319] = {
            ["Content"] = "所以在那之后，就开始自然而然地喜欢去逛街，并且买上几件新衣服了。",
            ["ContentFR"] = "Depuis, je prends plaisir à faire du shopping et à m’acheter quelques tenues.",
            ["DialogueId"] = 80020319,
            ["GUID"] = "C8528D96",
            ["NextDialogue"] = 80020320,
            ["SpeakNpcId"] = 93102,
            ["TalkActionId"] = {
                [1] = "93102:Sit_Talk02_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xier/003/C8528D96",
            },
        [80020320] = {
            ["Content"] = "唔，我喝完了，走吧。让我来为您搭配一套衣服，就当是这杯饮料的谢礼了。",
            ["ContentFR"] = "Bon, j’ai terminé mon verre. Allons-y. Je vais vous aider à choisir une tenue, pour vous remercier de ce verre.",
            ["DialogueId"] = 80020320,
            ["FacialId"] = {
                [1] = "93102:None",
                },
            ["GUID"] = "C8528DC0",
            ["SpeakNpcId"] = 93102,
            ["VoiceName"] = "voice/$Locale$/inv/Xier/003/C8528DC0",
            },
        [80020401] = {
            ["Camera"] = "106.860352,-6.606262,134.715088,0.0,-0.99996,-137.196014,30.0,125.0,false,Manual,2.8",
            ["Content"] = "谢谢邀请，嗯，谢谢。",
            ["ContentFR"] = "Merci pour l’invitation... Mmh, vraiment, merci.",
            ["DialogueId"] = 80020401,
            ["FacialId"] = {
                [1] = "93102:Smile02",
                },
            ["GUID"] = "C8529B0A",
            ["LookAt"] = {
                [1] = "93102:p(18000P1)",
                },
            ["NextDialogue"] = 80020402,
            ["SpeakNpcId"] = 93102,
            ["TalkActionId"] = {
                [1] = "93102:Sit_AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xier/004/C8529B0A",
            },
        [80020402] = {
            ["Content"] = "喝完这杯，我打算去修剪一些花朵。",
            ["ContentFR"] = "Une fois ce verre terminé, je comptais aller tailler quelques fleurs.",
            ["DialogueId"] = 80020402,
            ["GUID"] = "C8529B34",
            ["NextOptions"] = {
                [1] = 800204021,
                [2] = 800204022,
                },
            ["SpeakNpcId"] = 93102,
            ["VoiceName"] = "voice/$Locale$/inv/Xier/004/C8529B34",
            },
        [80020403] = {
            ["Content"] = "其实相反，正是因为心情糟糕，所以才想要拿起剪刀。",
            ["ContentFR"] = "Pas vraiment. C’est justement parce que je suis de mauvaise humeur que j’ai envie de prendre les ciseaux.",
            ["DialogueId"] = 80020403,
            ["FacialId"] = {
                [1] = "93102:Disappoint01",
                },
            ["GUID"] = "C8529B5E",
            ["NextDialogue"] = 80020405,
            ["SpeakNpcId"] = 93102,
            ["TalkActionId"] = {
                [1] = "93102:Sit_DisagreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xier/004/C8529B5E",
            },
        [80020404] = {
            ["Content"] = "其实并不是为了工作，而是排解压力。",
            ["ContentFR"] = "Oh, ce n’est pas pour le travail, c’est ma façon de me détendre.",
            ["DialogueId"] = 80020404,
            ["FacialId"] = {
                [1] = "93102:None",
                },
            ["GUID"] = "C8529B88",
            ["NextDialogue"] = 80020405,
            ["SpeakNpcId"] = 93102,
            ["TalkActionId"] = {
                [1] = "93102:Sit_DisagreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xier/004/C8529B88",
            },
        [80020405] = {
            ["Content"] = "每当我压力太大的时候，就会想要拿起剪刀，对着快要枯萎的花朵随意来上几下，仿佛能够把自己不那么振作的情绪也剪掉。",
            ["ContentFR"] = "Quand je suis trop stressée, j’ai ce réflexe étrange : je coupe les fleurs qui commencent à faner. Comme si, en taillant ce qui dépérit, je pouvais aussi trancher mes émotions négatives.",
            ["DialogueId"] = 80020405,
            ["GUID"] = "C8529BB2",
            ["NextDialogue"] = 80020406,
            ["SpeakNpcId"] = 93102,
            ["VoiceName"] = "voice/$Locale$/inv/Xier/004/C8529BB2",
            },
        [80020406] = {
            ["Content"] = "怎么？感觉奇怪吗？这不过是一种发泄情绪的方法罢了。毕竟我也不是靠动动嘴皮子就能够完成委托。",
            ["ContentFR"] = "Quoi ? Cela vous paraît étrange ? C’est juste une manière de relâcher la pression. Après tout, je ne remplis pas mes missions juste en papotant.",
            ["DialogueId"] = 80020406,
            ["GUID"] = "C8529BDC",
            ["NextDialogue"] = 80020407,
            ["SpeakNpcId"] = 93102,
            ["TalkActionId"] = {
                [1] = "93102:Sit_Talk02R_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xier/004/C8529BDC",
            },
        [80020407] = {
            ["Content"] = "当我还在做密探的时候，听说过一些同僚有更加病态的压力抒发方式。",
            ["ContentFR"] = "Quand j’étais encore agent, j’ai vu des collègues gérer leur stress de manière... disons, beaucoup plus malsaine.",
            ["DialogueId"] = 80020407,
            ["FacialId"] = {
                [1] = "93102:Unhappy02",
                },
            ["GUID"] = "C8529C06",
            ["NextDialogue"] = 80020408,
            ["SpeakNpcId"] = 93102,
            ["TalkActionId"] = {
                [1] = "93102:Sit_Talk02R_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xier/004/C8529C06",
            },
        [80020408] = {
            ["Content"] = "完成一次耗时一秒的刺杀，可能要花上一个月制定计划，一周提前准备，一天的漫长等待。而失败了，可能就要面对一辈子的漫长刑期。",
            ["ContentFR"] = "Un assassinat qui ne prend qu’une seconde peut exiger un mois de préparation, une semaine de repérage, et une journée entière d’attente... Et si tu rates, tu peux dire adieu à ta liberté pour le reste de ta vie.",
            ["DialogueId"] = 80020408,
            ["GUID"] = "C8529C30",
            ["NextDialogue"] = 80020409,
            ["SpeakNpcId"] = 93102,
            ["VoiceName"] = "voice/$Locale$/inv/Xier/004/C8529C30",
            },
        [80020409] = {
            ["Content"] = "而我面临这种压力时，胡乱剪上那么一两朵花，已经是很克制的举动了，不是吗？",
            ["ContentFR"] = "Dans ces conditions, couper deux ou trois fleurs au hasard, c’est plutôt inoffensif, non ?",
            ["DialogueId"] = 80020409,
            ["FacialId"] = {
                [1] = "93102:Iyada01",
                },
            ["GUID"] = "C8529C5A",
            ["NextOptions"] = {
                [1] = 800204091,
                [2] = 800204092,
                },
            ["SpeakNpcId"] = 93102,
            ["TalkActionId"] = {
                [1] = "93102:Sit_Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xier/004/C8529C5A",
            },
        [80020410] = {
            ["Content"] = "嗯，也不是烦心事。",
            ["ContentFR"] = "Ce n’est pas vraiment un tracas, en fait.",
            ["DialogueId"] = 80020410,
            ["FacialId"] = {
                [1] = "93102:None",
                },
            ["GUID"] = "C8529C84",
            ["NextDialogue"] = 80020412,
            ["SpeakNpcId"] = 93102,
            ["TalkActionId"] = {
                [1] = "93102:Sit_Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xier/004/C8529C84",
            },
        [80020411] = {
            ["Content"] = "您好像有点抓不住对话的重点？",
            ["ContentFR"] = "Il me semble que vous passez à côté du vrai sujet, non ?",
            ["DialogueId"] = 80020411,
            ["FacialId"] = {
                [1] = "93102:None",
                },
            ["GUID"] = "C8529CAE",
            ["NextDialogue"] = 80020412,
            ["SpeakNpcId"] = 93102,
            ["TalkActionId"] = {
                [1] = "93102:Sit_Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xier/004/C8529CAE",
            },
        [80020412] = {
            ["Content"] = "我只是有点怀念一位，嗯……很重要的人。",
            ["ContentFR"] = "Je pensais juste à quelqu’un... quelqu’un d’important.",
            ["DialogueId"] = 80020412,
            ["GUID"] = "C8529CD8",
            ["NextDialogue"] = 80020413,
            ["SpeakNpcId"] = 93102,
            ["VoiceName"] = "voice/$Locale$/inv/Xier/004/C8529CD8",
            },
        [80020413] = {
            ["Content"] = "她与我同样，也是密探，但她始终觉得我不适合这个职业。于是那时候，我就满心想向她证明，我不仅能够胜任，并且一定能做到最好。",
            ["ContentFR"] = "Elle était agent, comme moi. Mais elle a toujours pensé que je n’étais pas faite pour ça. Alors, à l’époque, je voulais lui prouver que je pouvais non seulement faire le job, mais être la meilleure.",
            ["DialogueId"] = 80020413,
            ["GUID"] = "C8529D02",
            ["NextDialogue"] = 80020414,
            ["SpeakNpcId"] = 93102,
            ["VoiceName"] = "voice/$Locale$/inv/Xier/004/C8529D02",
            },
        [80020414] = {
            ["Content"] = "事实证明，她才是对的。",
            ["ContentFR"] = "Finalement... elle avait raison.",
            ["DialogueId"] = 80020414,
            ["FacialId"] = {
                [1] = "93102:Smile02",
                },
            ["GUID"] = "C8529D2C",
            ["NextDialogue"] = 80020415,
            ["SpeakNpcId"] = 93102,
            ["TalkActionId"] = {
                [1] = "93102:Sit_AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xier/004/C8529D2C",
            },
        [80020415] = {
            ["Content"] = "我做不到像她那样把任务置于最优先，不去考虑其他的一切。",
            ["ContentFR"] = "Je n’ai jamais su, comme elle, faire passer les missions avant tout le reste.",
            ["DialogueId"] = 80020415,
            ["GUID"] = "C8529D56",
            ["NextDialogue"] = 80020416,
            ["SpeakNpcId"] = 93102,
            ["VoiceName"] = "voice/$Locale$/inv/Xier/004/C8529D56",
            },
        [80020416] = {
            ["Content"] = "不过我又多少有点庆幸，自己没有真的和她那样，走上另外一条道路吧。",
            ["ContentFR"] = "Mais au fond, je suis presque soulagée de ne pas avoir suivi exactement le même chemin.",
            ["DialogueId"] = 80020416,
            ["FacialId"] = {
                [1] = "93102:Happy01",
                },
            ["GUID"] = "C8529D80",
            ["NextDialogue"] = 80020417,
            ["SpeakNpcId"] = 93102,
            ["TalkActionId"] = {
                [1] = "93102:Sit_Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xier/004/C8529D80",
            },
        [80020417] = {
            ["Content"] = "之前我离开军团的时候，和她失去了联系，现在在这里的生活逐渐安稳，我有点……好奇她现在过得好不好。",
            ["ContentFR"] = "Quand j’ai quitté la Légion, on a perdu contact. Maintenant que ma vie est plus calme ici, je me demande parfois... si elle va bien.",
            ["DialogueId"] = 80020417,
            ["GUID"] = "C8529DAA",
            ["NextOptions"] = {
                [1] = 800204171,
                },
            ["SpeakNpcId"] = 93102,
            ["TalkActionId"] = {
                [1] = "93102:Sit_Talk02_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xier/004/C8529DAA",
            },
        [80020418] = {
            ["Content"] = "欸？嗯……",
            ["ContentFR"] = "Hein ? Hmm...",
            ["DialogueId"] = 80020418,
            ["FacialId"] = {
                [1] = "93102:Shock02",
                },
            ["GUID"] = "C8529DD4",
            ["NextDialogue"] = 80020419,
            ["SpeakNpcId"] = 93102,
            ["VoiceName"] = "voice/$Locale$/inv/Xier/004/C8529DD4",
            },
        [80020419] = {
            ["Content"] = "您说得对，与其在这里打算剪上几朵花，不如现在就去见她。",
            ["ContentFR"] = "Vous avez raison. Plutôt que de rester là à couper des fleurs, autant aller la voir.",
            ["DialogueId"] = 80020419,
            ["FacialId"] = {
                [1] = "93102:None",
                },
            ["GUID"] = "C8529DFE",
            ["SpeakNpcId"] = 93102,
            ["VoiceName"] = "voice/$Locale$/inv/Xier/004/C8529DFE",
            },
        [80020501] = {
            ["Camera"] = "106.860352,-6.606262,134.715088,0.0,-0.99996,-137.196014,30.0,125.0,false,Manual,2.8",
            ["Content"] = "刚刚回到这里，您就凑上来邀我来上一杯。说，是不是偷偷学了我的密探手法，暗地里观察我？",
            ["ContentFR"] = "Dès mon retour ici, vous êtes {性别:venu|venue} m’inviter à boire un verre. Dites-moi franchement, avez-vous appris quelques-uns de mes vieux tours d’agent et m’espionnez-vous en secret ?",
            ["DialogueId"] = 80020501,
            ["FacialId"] = {
                [1] = "93102:Confident02",
                },
            ["GUID"] = "C852AB72",
            ["LookAt"] = {
                [1] = "93102:p(18000P1)",
                },
            ["NextOptions"] = {
                [1] = 800205011,
                [2] = 800205012,
                },
            ["SpeakNpcId"] = 93102,
            ["TalkActionId"] = {
                [1] = "93102:Sit_Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xier/005/C852AB72",
            },
        [80020503] = {
            ["Content"] = "算了，不拿您开玩笑了。您其实是好奇我有没有见到那位重要的人吧？",
            ["ContentFR"] = "Je ne faisais que plaisanter. En fait, vous êtes {性别:venu|venue} parce que vous vouliez savoir si j’avais retrouvé cette personne importante pour moi, n’est-ce pas ?",
            ["DialogueId"] = 80020503,
            ["FacialId"] = {
                [1] = "93102:None",
                },
            ["GUID"] = "C852ABC6",
            ["NextDialogue"] = 80020504,
            ["SpeakNpcId"] = 93102,
            ["TalkActionId"] = {
                [1] = "93102:Sit_Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xier/005/C852ABC6",
            },
        [80020504] = {
            ["Content"] = "实话说，没有。她因为一些缘由被调离了皇都，所以我只是从其他人口中打听到了她的去向。",
            ["ContentFR"] = "Pour être honnête, non. Elle a été mutée loin de la capitale pour certaines raisons, donc je n’ai entendu parler d’elle que par des bribes venant d’autres personnes.",
            ["DialogueId"] = 80020504,
            ["GUID"] = "C852ABF0",
            ["NextDialogue"] = 80020505,
            ["SpeakNpcId"] = 93102,
            ["VoiceName"] = "voice/$Locale$/inv/Xier/005/C852ABF0",
            },
        [80020505] = {
            ["Content"] = "她去了南方的一个小城，不像这里都是冰雪，而是一个能经常晒晒太阳，听听乐曲的地方。",
            ["ContentFR"] = "Elle est dans une petite ville du sud, très différente d’ici où la glace et la neige règnent. Là-bas, elle peut profiter du soleil et écouter de la musique régulièrement.",
            ["DialogueId"] = 80020505,
            ["FacialId"] = {
                [1] = "93102:Smile02",
                },
            ["GUID"] = "C852AC1A",
            ["NextDialogue"] = 80020506,
            ["SpeakNpcId"] = 93102,
            ["VoiceName"] = "voice/$Locale$/inv/Xier/005/C852AC1A",
            },
        [80020506] = {
            ["Content"] = "其实我是松了一口气的，因为我确实不太知道该如何面对她……但是听起来她过得并不坏，那么我也能够放心了。",
            ["ContentFR"] = "Je dois avouer que ça m’a un peu soulagée, car je ne savais pas trop comment la revoir... Mais savoir qu’elle va bien me rassure.",
            ["DialogueId"] = 80020506,
            ["GUID"] = "C852AC44",
            ["NextDialogue"] = 80020507,
            ["SpeakNpcId"] = 93102,
            ["TalkActionId"] = {
                [1] = "93102:Sit_Talk02R_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xier/005/C852AC44",
            },
        [80020507] = {
            ["Content"] = "这样一来，我和军团、和密探这个身份的最后一丝关联，到了今天，终于消失了。",
            ["ContentFR"] = "Cela signifie que le dernier lien entre moi, la Légion et mon passé d’agent est enfin coupé.",
            ["DialogueId"] = 80020507,
            ["GUID"] = "C852AC6E",
            ["NextOptions"] = {
                [1] = 800205071,
                [2] = 800205072,
                },
            ["SpeakNpcId"] = 93102,
            ["TalkActionId"] = {
                [1] = "93102:Sit_Talk02R_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xier/005/C852AC6E",
            },
        [80020508] = {
            ["Content"] = "嗯，是的，终于解开了。",
            ["ContentFR"] = "Oui, enfin.",
            ["DialogueId"] = 80020508,
            ["GUID"] = "C852AC98",
            ["NextDialogue"] = 80020510,
            ["SpeakNpcId"] = 93102,
            ["TalkActionId"] = {
                [1] = "93102:Sit_AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xier/005/C852AC98",
            },
        [80020509] = {
            ["Content"] = "之前会吧，现在已经完全不会了。",
            ["ContentFR"] = "Avant oui, mais plus maintenant.",
            ["DialogueId"] = 80020509,
            ["GUID"] = "C852ACC2",
            ["NextDialogue"] = 80020510,
            ["SpeakNpcId"] = 93102,
            ["VoiceName"] = "voice/$Locale$/inv/Xier/005/C852ACC2",
            },
        [80020510] = {
            ["Content"] = "这个重要的人其实是我的一位至亲，正是因为她的缘故，我才会想要加入军团，也正是因为她，我才想要离开。",
            ["ContentFR"] = "C’est en fait un membre proche de ma famille. C’est elle qui m’a poussée à rejoindre la Légion... et c’est aussi à cause d’elle que j’en suis partie.",
            ["DialogueId"] = 80020510,
            ["FacialId"] = {
                [1] = "93102:Iyada01",
                },
            ["GUID"] = "C852ACEC",
            ["NextDialogue"] = 80020511,
            ["SpeakNpcId"] = 93102,
            ["TalkActionId"] = {
                [1] = "93102:Sit_Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xier/005/C852ACEC",
            },
        [80020511] = {
            ["Content"] = "她并不希望看到我从事这份过于危险的职业，但我拼命想证明给她看，我可以做好，并且能够为她分担一些烦恼。",
            ["ContentFR"] = "Elle ne voulait pas que je fasse ce métier dangereux, mais j’ai tout fait pour lui prouver que j’étais capable, et que je pouvais partager certains de ses fardeaux.",
            ["DialogueId"] = 80020511,
            ["GUID"] = "C852AD16",
            ["NextDialogue"] = 80020512,
            ["SpeakNpcId"] = 93102,
            ["TalkActionId"] = {
                [1] = "93102:Sit_Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xier/005/C852AD16",
            },
        [80020512] = {
            ["Content"] = "讽刺的是，我和她分别收到了保护芙罗拉小姐和除去芙罗拉小姐的任务。",
            ["ContentFR"] = "Le comble, c’est qu’elle et moi avons eu des missions opposées, elle devait éliminer Mlle Flora, moi, la protéger.",
            ["DialogueId"] = 80020512,
            ["FacialId"] = {
                [1] = "93102:None",
                },
            ["GUID"] = "C852AD40",
            ["NextDialogue"] = 800205121,
            ["SpeakNpcId"] = 93102,
            ["VoiceName"] = "voice/$Locale$/inv/Xier/005/C852AD40",
            },
        [80020513] = {
            ["Content"] = "于是我带着芙罗拉小姐，在她的暗杀计划开始之前就想办法逃了出来，奔波逃亡。那时我没精力回忆在军团的日子，也尽力不去想和她相关的一切。",
            ["ContentFR"] = "Alors j’ai fui avec Mlle Flora avant que son plan d’assassinat ne démarre. Je n’avais ni le temps ni l’envie de repenser à mes jours dans la Légion ni à elle.",
            ["DialogueId"] = 80020513,
            ["FacialId"] = {
                [1] = "93102:Smile02",
                },
            ["GUID"] = "C852AD6A",
            ["NextDialogue"] = 80020514,
            ["SpeakNpcId"] = 93102,
            ["TalkActionId"] = {
                [1] = "93102:Sit_Talk02_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xier/005/C852AD6A",
            },
        [80020514] = {
            ["Content"] = "正是因为近期安定了一些，又有您愿意听我讲这些琐事，这件事在我心中才会越扎越深，难以忍受，最终才有了前一段时间的失态。",
            ["ContentFR"] = "C’est seulement maintenant, que tout est un peu plus calme, et que vous êtes là pour écouter mes histoires, que tout ça m’a pesé au point de me faire perdre pied il y a peu.",
            ["DialogueId"] = 80020514,
            ["GUID"] = "C852AD6B",
            ["NextOptions"] = {
                [1] = 800205141,
                [2] = 800205142,
                },
            ["SpeakNpcId"] = 93102,
            ["VoiceName"] = "voice/$Locale$/inv/Xier/005/C852AD6B",
            },
        [80020515] = {
            ["Content"] = "我唯一确定的是，迟早要面临这场与她的彻底告别。之前的我多少在试图逃避面对这个现实。",
            ["ContentFR"] = "La seule chose dont je suis sûre, c’est qu’un jour je devrai lui dire un adieu définitif. Avant, j’essayais de fuir cette réalité.",
            ["DialogueId"] = 80020515,
            ["GUID"] = "C852ADBE",
            ["NextDialogue"] = 80020516,
            ["SpeakNpcId"] = 93102,
            ["VoiceName"] = "voice/$Locale$/inv/Xier/005/C852ADBE",
            },
        [80020516] = {
            ["Content"] = "而现在，当它来临的时候，这种感觉并不坏，我甚至开始庆幸，终于不用再被它们纠缠了。",
            ["ContentFR"] = "Maintenant que c’est arrivé, ça ne fait pas si mal. Je suis même soulagée de ne plus être hantée par ça.",
            ["DialogueId"] = 80020516,
            ["FacialId"] = {
                [1] = "93102:None",
                },
            ["GUID"] = "C852ADE8",
            ["NextDialogue"] = 80020517,
            ["SpeakNpcId"] = 93102,
            ["TalkActionId"] = {
                [1] = "93102:Sit_Talk02R_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xier/005/C852ADE8",
            },
        [80020517] = {
            ["Content"] = "我现在想做许多事情，修剪花朵，烘焙甜点，逛街买上七八件新装，再跳上一支舞。",
            ["ContentFR"] = "J’ai plein de choses que je veux faire : tailler des fleurs, préparer des pâtisseries, m’acheter quelques nouvelles tenues, et peut-être même danser un peu.",
            ["DialogueId"] = 80020517,
            ["FacialId"] = {
                [1] = "93102:Smile02",
                },
            ["GUID"] = "C852AE12",
            ["NextDialogue"] = 80020518,
            ["SpeakNpcId"] = 93102,
            ["TalkActionId"] = {
                [1] = "93102:Sit_Talk02R_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xier/005/C852AE12",
            },
        [80020518] = {
            ["Content"] = "不过，我现在最想做的事情还是谢谢您，让我真正的摆脱了过去最挂心的一件事。",
            ["ContentFR"] = "Mais ce que je veux surtout, c’est vous remercier. Vous m’avez vraiment aidée à tourner la page sur ce qui me pesait le plus.",
            ["DialogueId"] = 80020518,
            ["GUID"] = "C852AE3C",
            ["NextOptions"] = {
                [1] = 800205181,
                [2] = 800205182,
                },
            ["SpeakNpcId"] = 93102,
            ["VoiceName"] = "voice/$Locale$/inv/Xier/005/C852AE3C",
            },
        [80020519] = {
            ["Content"] = "同时我也得告诉您，既然知晓了我的这些过去，那么就意味着未来的某一天，军团试图抓捕我和芙罗拉小姐的时候，您也无法置身事外。",
            ["ContentFR"] = "Mais je dois aussi vous prévenir : maintenant que vous connaissez mon passé, cela veut dire qu’un jour, quand la Légion viendra pour moi et Mlle Flora, vous ne pourrez plus rester en dehors de tout ça.",
            ["DialogueId"] = 80020519,
            ["FacialId"] = {
                [1] = "93102:None",
                },
            ["GUID"] = "C852AE66",
            ["NextDialogue"] = 80020520,
            ["SpeakNpcId"] = 93102,
            ["TalkActionId"] = {
                [1] = "93102:Sit_Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xier/005/C852AE66",
            },
        [80020520] = {
            ["Content"] = "怎么样？怕了吗？会不会觉得我给了您一颗包裹毒药的蜜糖？",
            ["ContentFR"] = "J’espère que vous n’êtes pas trop effrayé. On dirait que je vous ai tendu un bonbon empoisonné, non ?",
            ["DialogueId"] = 80020520,
            ["FacialId"] = {
                [1] = "93102:Confident01",
                },
            ["GUID"] = "C852AE90",
            ["NextDialogue"] = 80020521,
            ["SpeakNpcId"] = 93102,
            ["TalkActionId"] = {
                [1] = "93102:Sit_Talk02_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xier/005/C852AE90",
            },
        [80020521] = {
            ["Content"] = "请放心，我，希尔妲，万能的女仆，会负起责任，一直一直在您身边保护您的。",
            ["ContentFR"] = "Rassurez-vous, moi, Hilda, la servante capable de tout, je prendrai mes responsabilités et resterai toujours à vos côtés pour vous protéger.",
            ["DialogueId"] = 80020521,
            ["FacialId"] = {
                [1] = "93102:None",
                },
            ["GUID"] = "C852AEBA",
            ["SpeakNpcId"] = 93102,
            ["VoiceName"] = "voice/$Locale$/inv/Xier/005/C852AEBA",
            },
        [80020522] = {
            ["Content"] = "收到来自我的感谢，很奇怪吗？这话可是真诚的。",
            ["ContentFR"] = "Merci, ça vous semble bizarre que je vous remercie ? C’est sincère.",
            ["DialogueId"] = 80020522,
            ["FacialId"] = {
                [1] = "93102:Happy02",
                },
            ["GUID"] = "C852AE65",
            ["NextDialogue"] = 80020519,
            ["SpeakNpcId"] = 93102,
            ["TalkActionId"] = {
                [1] = "93102:Sit_AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xier/005/C852AE65",
            },
        [80030100] = {
            ["Content"] = "宝贵的假期除了用来睡觉，与你一起度过也不错。",
            ["ContentFR"] = "Les vacances, c’est précieux. Et les passer avec toi, c’est presque aussi bien que de dormir.",
            ["DialogueId"] = 80030100,
            ["GUID"] = "C878DD68",
            ["VoiceName"] = "voice/$Locale$/inv/Landi/001/C878DD68",
            },
        [80030101] = {
            ["Camera"] = "184.82782,72.338623,127.99707,0.000026,1.199654,-136.185898,35.0,125.0,false,Disable,2.8",
            ["Content"] = "休息充足后再喝杯饮料……呼，不工作就是舒爽啊。",
            ["ContentFR"] = "Après une bonne sieste, un petit verre... Ah, rien de mieux que de ne pas bosser, c’est la vraie vie !",
            ["DialogueId"] = 80030101,
            ["GUID"] = "C858D272",
            ["LookAt"] = {
                [1] = "94202:p(18000P1)",
                },
            ["NextDialogue"] = 80030102,
            ["SpeakNpcId"] = 94202,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/001/C858D272",
            },
        [80030102] = {
            ["Content"] = "哦对了，来这儿之前勤务员塞给我一个包裹，还没拆开，让我来看看……",
            ["ContentFR"] = "Ah, au fait, on m’a refilé un colis juste avant que je vienne. Je l’ai même pas encore ouvert, voyons un peu...",
            ["DialogueId"] = 80030102,
            ["GUID"] = "C858D29C",
            ["NextDialogue"] = 80030103,
            ["SpeakNpcId"] = 94202,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/001/C858D29C",
            },
        [80030103] = {
            ["Content"] = "应该是我托属下买的睡衣和助眠熏香送到了吧……嗯，待会儿就再去好好补一觉……",
            ["ContentFR"] = "Ça doit être le pyjama et l’encens pour dormir que j’ai demandé à mes gars... Parfait, je vais pouvoir faire une sieste tranquille après.",
            ["DialogueId"] = 80030103,
            ["GUID"] = "C858D2C6",
            ["NextDialogue"] = 80030104,
            ["SpeakNpcId"] = 94202,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/001/C858D2C6",
            },
        [80030104] = {
            ["Content"] = "嗯？这是……《十三军团驻地外围观赏植物优化建议书》？《为了增强士兵士气购入娱乐设施申请函》？",
            ["ContentFR"] = "Hein ? C’est quoi ça... « Proposition pour optimiser les plantes décoratives de la XIIIᵉ Légion » ? « Demande d’achat d’installations de loisirs pour booster le moral des soldats » ?",
            ["DialogueId"] = 80030104,
            ["GUID"] = "C858D2F0",
            ["NextDialogue"] = 80030105,
            ["SpeakNpcId"] = 94202,
            ["TalkActionId"] = {
                [1] = "94202:Sit_Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Landi/001/C858D2F0",
            },
        [80030105] = {
            ["Content"] = "原来是工作上的事啊。虽然内容看起来没什么问题，但还是之后再说吧，没人能打扰我的假期。军团长也许可以，不过她现在不会出现在这里。",
            ["ContentFR"] = "Ah, boulot, boulot... Ça a l’air ok, mais on en reparlera plus tard. Personne ne va me gâcher mes vacances. Peut-être la commandante, mais elle viendra pas ici.",
            ["DialogueId"] = 80030105,
            ["GUID"] = "C858D31A",
            ["NextOptions"] = {
                [1] = 800301051,
                [2] = 800301052,
                },
            ["SpeakNpcId"] = 94202,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/001/C858D31A",
            },
        [80030106] = {
            ["Content"] = "思考出这样实用的准则可是很不容易的。",
            ["ContentFR"] = "Trouver des règles aussi pratiques, ça s’invente pas tout seul, hein.",
            ["DialogueId"] = 80030106,
            ["GUID"] = "C858D344",
            ["NextDialogue"] = 80030108,
            ["SpeakNpcId"] = 94202,
            ["TalkActionId"] = {
                [1] = "94202:Sit_Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Landi/001/C858D344",
            },
        [80030107] = {
            ["Content"] = "可不要乱说，这怎么能叫偷懒呢。",
            ["ContentFR"] = "Hé, t’appelles ça glander ? Pas du tout.",
            ["DialogueId"] = 80030107,
            ["FacialId"] = {
                [1] = "94202:Blink",
                },
            ["GUID"] = "C858D36E",
            ["NextDialogue"] = 80030108,
            ["SpeakNpcId"] = 94202,
            ["TalkActionId"] = {
                [1] = "94202:Sit_Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Landi/001/C858D36E",
            },
        [80030108] = {
            ["Content"] = "这是我——兰迪·霍华德自创的“霍氏高效节能模式”，是呕心沥血的成果。",
            ["ContentFR"] = "C’est mon fameux \"Mode Howard énergie optimale\" que j’ai inventé, un vrai boulot de titan.",
            ["DialogueId"] = 80030108,
            ["GUID"] = "C858D398",
            ["NextDialogue"] = 80030109,
            ["SpeakNpcId"] = 94202,
            ["TalkActionId"] = {
                [1] = "94202:Sit_Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Landi/001/C858D398",
            },
        [80030109] = {
            ["Content"] = "休息的时候，把脑子里和工作相关的东西摘除地一干二净，这样才不会在休息结束时恐惧工作。",
            ["ContentFR"] = "Quand je me repose, je débranche complètement la tête du boulot, comme ça je redémarre sans stresser.",
            ["DialogueId"] = 80030109,
            ["GUID"] = "C858D3C2",
            ["NextDialogue"] = 80030110,
            ["SpeakNpcId"] = 94202,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/001/C858D3C2",
            },
        [80030110] = {
            ["Content"] = "经过了多年的实践和不断地完善，非常实用。",
            ["ContentFR"] = "Après des années à peaufiner ça, c’est devenu redoutablement efficace.",
            ["DialogueId"] = 80030110,
            ["GUID"] = "C858D3EC",
            ["NextDialogue"] = 80030111,
            ["SpeakNpcId"] = 94202,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/001/C858D3EC",
            },
        [80030111] = {
            ["Content"] = "让我短时间内就能想出最“节能”的办法，来应对各种事件。",
            ["ContentFR"] = "Ça me permet de trouver la solution la plus \"économe\" en énergie pour n’importe quel problème, en un clin d’œil.",
            ["DialogueId"] = 80030111,
            ["GUID"] = "C858D416",
            ["NextDialogue"] = 80030112,
            ["SpeakNpcId"] = 94202,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/001/C858D416",
            },
        [80030112] = {
            ["Content"] = "就比如现在，这场另有目的的会谈。",
            ["ContentFR"] = "Comme cette conversation qui cache un double jeu.",
            ["DialogueId"] = 80030112,
            ["GUID"] = "C858D417",
            ["NextDialogue"] = 80030113,
            ["SpeakNpcId"] = 94202,
            ["TalkActionId"] = {
                [1] = "94202:Sit_Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Landi/001/C858D417",
            },
        [80030113] = {
            ["Content"] = "啊，你在说什么，听不懂呢。",
            ["ContentFR"] = "Hein ? Je ne comprends pas.",
            ["DialogueId"] = 80030113,
            ["GUID"] = "80030113.0",
            ["NextDialogue"] = 80030114,
            ["SpeakNpcId"] = 790008,
            },
        [80030114] = {
            ["Content"] = "这时候才装傻也太迟了吧。",
            ["ContentFR"] = "C’est un peu tard pour faire l’{性别:innocent|innocente}, non ?",
            ["DialogueId"] = 80030114,
            ["GUID"] = "C858D418",
            ["NextDialogue"] = 80030115,
            ["SpeakNpcId"] = 94202,
            ["TalkActionId"] = {
                [1] = "94202:Sit_DisagreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Landi/001/C858D418",
            },
        [80030115] = {
            ["Content"] = "……贝蕾妮卡怎么样了！",
            ["ContentFR"] = "... Dis-moi, Berenica va bien, oui ou non ?",
            ["DialogueId"] = 80030115,
            ["GUID"] = "80030115.0",
            ["NextDialogue"] = 80030116,
            ["SpeakNpcId"] = 790008,
            },
        [80030116] = {
            ["Content"] = "哦？原来零号的名字叫贝蕾妮卡啊。",
            ["ContentFR"] = "Alors c’est comme ça que s’appelle n° 0... Berenica, hein.",
            ["DialogueId"] = 80030116,
            ["GUID"] = "C858D419",
            ["NextDialogue"] = 80030117,
            ["SpeakNpcId"] = 94202,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/001/C858D419",
            },
        [80030117] = {
            ["Content"] = "你这时候装傻也有点晚。",
            ["ContentFR"] = "Un peu tard pour faire le naïf.",
            ["DialogueId"] = 80030117,
            ["GUID"] = "80030117.0",
            ["NextDialogue"] = 80030118,
            ["SpeakNpcId"] = 790008,
            },
        [80030118] = {
            ["Content"] = "聪明人之间说话，总是要先装几句傻的。",
            ["ContentFR"] = "Les gens malins savent qu’il faut toujours commencer par faire un peu le naïf.",
            ["DialogueId"] = 80030118,
            ["GUID"] = "C858D41A",
            ["NextDialogue"] = 80030119,
            ["SpeakNpcId"] = 94202,
            ["TalkActionId"] = {
                [1] = "94202:Sit_Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Landi/001/C858D41A",
            },
        [80030119] = {
            ["Content"] = "不过嘛，你这个问题，问我也是白问。第一，就算我说了也不一定是真的，你无法确认。",
            ["ContentFR"] = "Mais franchement, tu peux me poser la question, ça changera rien. Même si je te disais, tu pourrais pas vérifier.",
            ["DialogueId"] = 80030119,
            ["GUID"] = "C858D41B",
            ["NextDialogue"] = 80030120,
            ["SpeakNpcId"] = 94202,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/001/C858D41B",
            },
        [80030120] = {
            ["Content"] = "第二，根据“霍氏高效节能模式”，工作是工作，生活是生活。",
            ["ContentFR"] = "Deuxièmement, avec mon \"Mode Howard énergie optimale\", le boulot c’est le boulot, la vie c’est la vie.",
            ["DialogueId"] = 80030120,
            ["GUID"] = "C858D41C",
            ["NextDialogue"] = 80030121,
            ["SpeakNpcId"] = 94202,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/001/C858D41C",
            },
        [80030121] = {
            ["Content"] = "生活可以融入我的工作，但工作决不能闯入我的生活，现在的我，是在休假中赴约的，这是我得到的最“节能”的办法。",
            ["ContentFR"] = "La vie peut s’immiscer dans le boulot, mais pas l’inverse. Là, je suis en congé, donc je fais comme si on se voyait en pause. C’est la manière la plus \"éco-énergétique\" de gérer ça.",
            ["DialogueId"] = 80030121,
            ["GUID"] = "C858D41D",
            ["NextDialogue"] = 80030122,
            ["SpeakNpcId"] = 94202,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/001/C858D41D",
            },
        [80030122] = {
            ["Content"] = "所以不管是现在还是未来的会谈，我们怕是都不能在零号的话题上有所进展了，但如果是生活相关的，那倒是有很多可以聊。",
            ["ContentFR"] = "Du coup, aujourd’hui ou plus tard, les discussions sur n° 0 n’avanceront pas, mais si c’est pour parler de la vie, là, je suis tout ouïe.",
            ["DialogueId"] = 80030122,
            ["GUID"] = "C858D41E",
            ["NextDialogue"] = 80030123,
            ["SpeakNpcId"] = 94202,
            ["TalkActionId"] = {
                [1] = "94202:Sit_Talk01_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Landi/001/C858D41E",
            },
        [80030123] = {
            ["Content"] = "那我们没什么好谈的了，你走吧。",
            ["ContentFR"] = "Bon, on n’a plus rien à se dire, tu peux y aller.",
            ["DialogueId"] = 80030123,
            ["GUID"] = "C858D41F",
            ["NextDialogue"] = 80030124,
            ["SpeakNpcId"] = 790008,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/001/C858D41F",
            },
        [80030124] = {
            ["Content"] = "虽然没法告诉你她的下落，但我可以向你保证的是，她很安全。",
            ["ContentFR"] = "Je peux pas te dire où elle est, mais je garantis qu’elle est en sécurité.",
            ["DialogueId"] = 80030124,
            ["GUID"] = "C858D421",
            ["NextDialogue"] = 80030125,
            ["SpeakNpcId"] = 94202,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/001/C858D421",
            },
        }
  end },
  { MinKey = 80030125, MaxKey = 80040322, Loader = function()
      return {
        [80030125] = {
            ["Content"] = "从你嘴里听到的保证，我无法确认。",
            ["ContentFR"] = "Je peux pas vraiment croire à ta garantie.",
            ["DialogueId"] = 80030125,
            ["GUID"] = "C858D422",
            ["NextDialogue"] = 80030126,
            ["SpeakNpcId"] = 790008,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/001/C858D422",
            },
        [80030126] = {
            ["Content"] = "哈哈哈哈，聪明人学得就是快呀。",
            ["ContentFR"] = "Haha, les malins apprennent vite !",
            ["DialogueId"] = 80030126,
            ["GUID"] = "C858D423",
            ["NextDialogue"] = 80030127,
            ["SpeakNpcId"] = 94202,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/001/C858D423",
            },
        [80030127] = {
            ["Content"] = "哎，难得我一片好心了，真是令人悲痛欲绝，甚至明天无法正常休息……",
            ["ContentFR"] = "Bon, j’ai été sympa, c’est triste que ça ne soit pas apprécié... Je vais sûrement pas bien dormir demain...",
            ["DialogueId"] = 80030127,
            ["GUID"] = "C858D4BE",
            ["NextDialogue"] = 80030128,
            ["SpeakNpcId"] = 94202,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/001/C858D4BE",
            },
        [80030128] = {
            ["Content"] = "对哦，我应该试试能不能休假中插入病假：因为生病，没有得到休息，所以延长休假，想想也是很正常的逻辑！",
            ["ContentFR"] = "Ah, je devrais essayer un congé maladie pendant mes vacances : je suis trop malade pour me reposer, donc j’allonge mes congés, ça tient la route, non ?!",
            ["DialogueId"] = 80030128,
            ["GUID"] = "C858D4E8",
            ["NextDialogue"] = 80030129,
            ["SpeakNpcId"] = 94202,
            ["TalkActionId"] = {
                [1] = "94202:Sit_Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Landi/001/C858D4E8",
            },
        [80030129] = {
            ["Content"] = "也不是不可以……病假理由就写周身上下不明原因疼痛，尤其是心脏疼痛剧烈。",
            ["ContentFR"] = "Et comme raison... je dirais que j’ai des douleurs un peu partout, surtout au niveau du cœur.",
            ["DialogueId"] = 80030129,
            ["GUID"] = "C858D512",
            ["NextDialogue"] = 80030130,
            ["SpeakNpcId"] = 94202,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/001/C858D512",
            },
        [80030130] = {
            ["Content"] = "原因就写成在做民意调查时发生了冲突，经私下调节已解决。也许还能领到工伤抚恤……嗯，今天算来对了。",
            ["ContentFR"] = "Je dirai que c’est à cause d’un conflit lors d’une enquête d’opinion, mais que ça s’est arrangé en privé. Peut-être que je toucherai une indemnité... Aujourd’hui a été une bonne journée.",
            ["DialogueId"] = 80030130,
            ["GUID"] = "C858D53C",
            ["NextDialogue"] = 80030131,
            ["SpeakNpcId"] = 94202,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/001/C858D53C",
            },
        [80030131] = {
            ["Content"] = "你一杯茶的功夫，就多了这么多假期，你可真是我的好朋友！",
            ["ContentFR"] = "En deux secondes, t’as réussi à me prolonger les vacances. T’es vraiment {性别:un|une} super pote !",
            ["DialogueId"] = 80030131,
            ["GUID"] = "C858D566",
            ["NextDialogue"] = 80030132,
            ["SpeakNpcId"] = 94202,
            ["TalkActionId"] = {
                [1] = "94202:Sit_Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Landi/001/C858D566",
            },
        [80030132] = {
            ["Content"] = "期待下一次的请假理由……咳，我是说下一次的见面。",
            ["ContentFR"] = "J’attends avec impatience ma prochaine excuse pour... enfin, notre prochaine rencontre.",
            ["DialogueId"] = 80030132,
            ["GUID"] = "C858D590",
            ["SpeakNpcId"] = 94202,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/001/C858D590",
            },
        [80030201] = {
            ["Camera"] = "184.82782,72.338623,127.99707,0.000026,1.199654,-136.185898,35.0,125.0,false,Disable,2.8",
            ["Content"] = "看来你终于愿意跟我聊聊生活相关的话题了呀。",
            ["ContentFR"] = "On dirait que tu es enfin {性别:prêt|prête} à papoter un peu de la vie, hein ?",
            ["DialogueId"] = 80030201,
            ["GUID"] = "C858E2DA",
            ["LookAt"] = {
                [1] = "94202:p(18000P1)",
                },
            ["NextDialogue"] = 80030202,
            ["SpeakNpcId"] = 94202,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/002/C858E2DA",
            },
        [80030202] = {
            ["Content"] = "哎呀，虽然前来冰湖城是公务，但是赴约可不是，不要觉得我只是顺便来这一趟。为了和你喝上一杯，我可是又申请了假期。",
            ["ContentFR"] = "Bon, même si je suis en mission à Givrelac, cette rencontre, c’est pas du boulot. Faut pas croire que je suis juste de passage. J’ai pris un congé exprès pour venir boire un verre avec toi.",
            ["DialogueId"] = 80030202,
            ["GUID"] = "C858E304",
            ["NextDialogue"] = 80030203,
            ["SpeakNpcId"] = 94202,
            ["TalkActionId"] = {
                [1] = "94202:Sit_DisagreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Landi/002/C858E304",
            },
        [80030203] = {
            ["Content"] = "理由嘛，就说被内城的贵族小姐邀请去跳了几支舞好了。",
            ["ContentFR"] = "Comme excuse, j’ai dit que j’avais été invité à danser par une jeune noble de la cité intérieure.",
            ["DialogueId"] = 80030203,
            ["GUID"] = "C858E32E",
            ["NextDialogue"] = 80030204,
            ["SpeakNpcId"] = 94202,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/002/C858E32E",
            },
        [80030204] = {
            ["Content"] = "别奇怪，年轻军官和贵族小姐传出些浪漫故事也不是一次两次，内部也都是睁一只眼闭一只眼。毕竟要是成了，军团的势力也会有所增长，不是坏事。",
            ["ContentFR"] = "Faut pas être surpris, c’est pas la première fois qu’un jeune officier et une dame de la noblesse s’amusent un peu ensemble. Le commandement ferme les yeux là-dessus. Et puis si ça marche, ça renforce le poids de la Légion, alors ce n’est pas si mal.",
            ["DialogueId"] = 80030204,
            ["GUID"] = "C858E358",
            ["NextDialogue"] = 80030205,
            ["SpeakNpcId"] = 94202,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/0/C858E358",
            },
        [80030205] = {
            ["Content"] = "而我这样风度翩翩的绅士，因为这样的缘由而延长假期，可太正常不过了。",
            ["ContentFR"] = "En tant que vrai gentleman, c’est tout à fait normal que je prolonge mes congés pour ce genre de motifs.",
            ["DialogueId"] = 80030205,
            ["GUID"] = "C858E382",
            ["NextOptions"] = {
                [1] = 800302051,
                [2] = 800302052,
                },
            ["SpeakNpcId"] = 94202,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/002/C858E382",
            },
        [80030206] = {
            ["Content"] = "啊，你这话说得我心好痛，我得继续延长假期检查检查。",
            ["ContentFR"] = "Tu me brises le cœur... Je vais devoir prolonger mon congé pour m’en remettre.",
            ["DialogueId"] = 80030206,
            ["GUID"] = "C858E3AC",
            ["NextDialogue"] = 80030208,
            ["SpeakNpcId"] = 94202,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/002/C858E3AC",
            },
        [80030207] = {
            ["Content"] = "嗯嗯，我就当做你是真心实意在夸赞我了。",
            ["ContentFR"] = "Ah, je vais faire comme si c’était sincère. Merci !",
            ["DialogueId"] = 80030207,
            ["GUID"] = "C858E3D6",
            ["NextDialogue"] = 80030208,
            ["SpeakNpcId"] = 94202,
            ["TalkActionId"] = {
                [1] = "94202:Sit_AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Landi/002/C858E3D6",
            },
        [80030208] = {
            ["Content"] = "不过，我也是很晚才知道，绅士这个词真正用起来，更多是用来挖苦，极少是用来赞美的。",
            ["ContentFR"] = "Avec le temps, j’ai compris qu’on utilise surtout \"gentleman\" pour taquiner, rarement pour vraiment complimenter.",
            ["DialogueId"] = 80030208,
            ["GUID"] = "C858E400",
            ["NextDialogue"] = 80030209,
            ["SpeakNpcId"] = 94202,
            ["TalkActionId"] = {
                [1] = "94202:Sit_Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Landi/002/C858E400",
            },
        [80030209] = {
            ["Content"] = "而小时候，我的姐姐们总和我说，成为绅士是一个小男孩的终极目标，人生意义。",
            ["ContentFR"] = "Quand j’étais petit, mes sœurs me disaient que devenir un gentleman, c’était le but ultime pour un garçon, le sens de la vie.",
            ["DialogueId"] = 80030209,
            ["GUID"] = "C858E42A",
            ["NextOptions"] = {
                [1] = 800302091,
                [2] = 800302092,
                },
            ["SpeakNpcId"] = 94202,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/002/C858E42A",
            },
        [80030210] = {
            ["Content"] = "也许你这个推论是基于对我的良好印象，但是很遗憾，并非如此。",
            ["ContentFR"] = "Peut-être que tu dis ça parce que t’as une bonne image de moi... mais non, c’étaient tout sauf des dames.",
            ["DialogueId"] = 80030210,
            ["GUID"] = "C858E454",
            ["NextDialogue"] = 80030212,
            ["SpeakNpcId"] = 94202,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/002/C858E454",
            },
        [80030211] = {
            ["Content"] = "谁都有年轻的时候嘛，天真，可爱。",
            ["ContentFR"] = "On est tous passés par là, naïf et mignon.",
            ["DialogueId"] = 80030211,
            ["GUID"] = "C858E47E",
            ["NextDialogue"] = 80030212,
            ["SpeakNpcId"] = 94202,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/002/C858E47E",
            },
        [80030212] = {
            ["Content"] = "虽然这些算是童年的伤疤，揭开就会带来疼痛，但是既然我已经是请假之交，那么给你讲讲她们也无妨啦。",
            ["ContentFR"] = "C’est un vieux souvenir d’enfance qui fait encore un peu mal... mais puisqu’on est potes de vacances, je peux bien t’en parler.",
            ["DialogueId"] = 80030212,
            ["GUID"] = "C858E4A8",
            ["NextDialogue"] = 80030213,
            ["SpeakNpcId"] = 94202,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/002/C858E4A8",
            },
        [80030213] = {
            ["Content"] = "我可是在她们的“关爱”下长大的！想要在她们的魔爪……咳，关爱下生存，练就了一身本领……",
            ["ContentFR"] = "J’ai grandi sous la \"bienveillance\" de mes sœurs ! Pour survivre à leurs griffes... euh, à leur attention, j’ai dû développer des talents...",
            ["DialogueId"] = 80030213,
            ["GUID"] = "C858E4D2",
            ["NextOptions"] = {
                [1] = 800302131,
                [2] = 800302132,
                },
            ["SpeakNpcId"] = 94202,
            ["TalkActionId"] = {
                [1] = "94202:Sit_Talk01_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Landi/002/C858E4D2",
            },
        [80030214] = {
            ["Content"] = "有爱，但不多。",
            ["ContentFR"] = "Oui, bienveillance... mais pas beaucoup.",
            ["DialogueId"] = 80030214,
            ["GUID"] = "C858E4FC",
            ["NextDialogue"] = 80030216,
            ["SpeakNpcId"] = 94202,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/002/C858E4FC",
            },
        [80030215] = {
            ["Content"] = "不辛苦，命苦。",
            ["ContentFR"] = "C’est pas que j’ai souffert, c’est la vie qui m’a malmené.",
            ["DialogueId"] = 80030215,
            ["GUID"] = "C858E526",
            ["NextDialogue"] = 80030216,
            ["SpeakNpcId"] = 94202,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/002/C858E526",
            },
        [80030216] = {
            ["Content"] = "那时候她们成天和我说，绅士要在见面时亲吻女士的手背，还应当遵循原则与礼仪，隐藏内心的真实想法。",
            ["ContentFR"] = "Elles me répétaient sans arrêt qu’un gentleman devait embrasser l’ourlet de la robe d’une dame quand ils se rencontraient, respecter les règles et cacher ses vrais sentiments.",
            ["DialogueId"] = 80030216,
            ["GUID"] = "C858E550",
            ["NextDialogue"] = 80030217,
            ["SpeakNpcId"] = 94202,
            ["TalkActionId"] = {
                [1] = "94202:Sit_Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Landi/002/C858E550",
            },
        [80030217] = {
            ["Content"] = "那时候我才六岁甚至五岁，虽然心里有些不情愿，但还是为了成为一个合格绅士，向见到的每一位女士搭话。",
            ["ContentFR"] = "J’avais à peine cinq ou six ans, j’étais pas hyper motivé, mais pour devenir un vrai gentleman, je parlais à toutes les dames que je croisais.",
            ["DialogueId"] = 80030217,
            ["GUID"] = "C858E57A",
            ["NextDialogue"] = 80030218,
            ["SpeakNpcId"] = 94202,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/002/C858E57A",
            },
        [80030218] = {
            ["Content"] = "你可以想象一下，在边上看着的姐姐们笑成了什么样子。好在她们在第二天，就和我说，绅士并不用做到这一步。",
            ["ContentFR"] = "Tu peux imaginer leurs rires derrière moi. Heureusement, le lendemain, elles m’ont dit qu’un gentleman n’avait pas besoin d’aller aussi loin.",
            ["DialogueId"] = 80030218,
            ["GUID"] = "C858E5A4",
            ["NextDialogue"] = 80030219,
            ["SpeakNpcId"] = 94202,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/002/C858E5A4",
            },
        [80030219] = {
            ["Content"] = "但不好的是，她们又告诉我，绅士应该亲吻女士的裙摆……",
            ["ContentFR"] = "Enfin, elles m’ont ensuite dit que c’était plutôt la main qu’il fallait embrasser, pas la robe.",
            ["DialogueId"] = 80030219,
            ["GUID"] = "C858E5CE",
            ["NextDialogue"] = 80030220,
            ["SpeakNpcId"] = 94202,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/002/C858E5CE",
            },
        [80030220] = {
            ["Content"] = "算了，越是回忆我的心就越痛，先干上一杯吧，为了我那不堪回首的童年时代。",
            ["ContentFR"] = "Bon, plus j’y pense, plus ça me fait mal au cœur. Allez, on boit un coup à mon enfance traumatisante.",
            ["DialogueId"] = 80030220,
            ["GUID"] = "C858E5F8",
            ["SpeakNpcId"] = 94202,
            ["TalkActionId"] = {
                [1] = "94202:Sit_Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Landi/002/C858E5F8",
            },
        [80030401] = {
            ["Camera"] = "184.82782,72.338623,127.99707,0.000026,1.199654,-136.185898,35.0,125.0,false,Disable,2.8",
            ["Content"] = "来了来了，我不会失约的。",
            ["ContentFR"] = "Je suis là, je ne pouvais pas te poser un lapin, quand même ?",
            ["DialogueId"] = 80030401,
            ["GUID"] = "C85903AA",
            ["LookAt"] = {
                [1] = "94202:p(18000P1)",
                },
            ["NextDialogue"] = 80030402,
            ["SpeakNpcId"] = 94202,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/004/C85903AA",
            },
        [80030402] = {
            ["Content"] = "喏，这是改进好的“军用合金控温容器”，我提前试过，不会有问题的……哈欠……",
            ["ContentFR"] = "Tiens, voilà le \"Conteneur militaire à régulation thermique\" amélioré. Je l’ai déjà testé, aucun souci... bâille...",
            ["DialogueId"] = 80030402,
            ["GUID"] = "C85903D4",
            ["NextDialogue"] = 80030403,
            ["SpeakNpcId"] = 94202,
            ["TalkActionId"] = {
                [1] = "94202:Sit_Talk02R_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Landi/004/C85903D4",
            },
        [80030403] = {
            ["Content"] = "不过我现在困得不行，得要先找一个地方睡上一觉。假期额度快用完了，明天可不能黑着眼圈去给西比尔长官汇报工作。",
            ["ContentFR"] = "Mais là, je suis crevé, il faut que je trouve un endroit pour pioncer un peu. Mes congés sont presque finis, demain je peux pas aller voir la commandante Sibylle avec des cernes.",
            ["DialogueId"] = 80030403,
            ["GUID"] = "C85903FE",
            ["NextOptions"] = {
                [1] = 800304031,
                [2] = 800304032,
                },
            ["SpeakNpcId"] = 94202,
            ["TalkActionId"] = {
                [1] = "94202:Sit_Talk02R_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Landi/004/C85903FE",
            },
        [80030404] = {
            ["Content"] = "你感觉还挺敏锐的嘛，确实有一些烦恼。",
            ["ContentFR"] = "T’as l’œil, oui, il y a un truc qui me chiffonne.",
            ["DialogueId"] = 80030404,
            ["GUID"] = "C8590428",
            ["NextDialogue"] = 80030405,
            ["SpeakNpcId"] = 94202,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/004/C8590428",
            },
        [80030405] = {
            ["Content"] = "既然被你察觉了，那我也不瞒着了，其实是做了噩梦。",
            ["ContentFR"] = "Puisque tu l’as remarqué, je vais pas te le cacher : j’ai fait un cauchemar.",
            ["DialogueId"] = 80030405,
            ["GUID"] = "C8590452",
            ["NextOptions"] = {
                [1] = 800304071,
                },
            ["SpeakNpcId"] = 94202,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/004/C8590452",
            },
        [80030406] = {
            ["Content"] = "怎么会，像我这么怕麻烦的人，是会回绝掉大部分邀请的。",
            ["ContentFR"] = "Bien sûr que non. Tu sais combien je suis paresseux. Je refuse la plupart des invitations.",
            ["DialogueId"] = 80030406,
            ["GUID"] = "C859047C",
            ["NextDialogue"] = 80030407,
            ["SpeakNpcId"] = 94202,
            ["TalkActionId"] = {
                [1] = "94202:Sit_DisagreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Landi/004/C859047C",
            },
        [80030407] = {
            ["Content"] = "实话说，是因为昨天做了噩梦，心情有些糟糕。",
            ["ContentFR"] = "Pour être honnête, j’ai fait un cauchemar cette nuit, alors je ne me sens pas très bien aujourd'hui.",
            ["DialogueId"] = 80030407,
            ["GUID"] = "C85904A6",
            ["NextOptions"] = {
                [1] = 800304071,
                },
            ["SpeakNpcId"] = 94202,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/004/C85904A6",
            },
        [80030408] = {
            ["Content"] = "唉，和之前许多次噩梦一样，是关于我那个麻烦老爹的……",
            ["ContentFR"] = "Comme beaucoup d’autres, c’était encore au sujet de mon père, ce casse-pieds...",
            ["DialogueId"] = 80030408,
            ["GUID"] = "C85904D0",
            ["NextOptions"] = {
                [1] = 800304081,
                },
            ["SpeakNpcId"] = 94202,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/004/C85904D0",
            },
        [80030409] = {
            ["Content"] = "嗯，他曾经也是帝国的军人。不过现在嘛……已经在床上躺了有些年头了。",
            ["ContentFR"] = "Oui, c’était aussi un soldat de l’Empire. Mais maintenant... il est alité depuis plusieurs années.",
            ["DialogueId"] = 80030409,
            ["GUID"] = "C85904FA",
            ["NextDialogue"] = 80030410,
            ["SpeakNpcId"] = 94202,
            ["TalkActionId"] = {
                [1] = "94202:Sit_AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Landi/004/C85904FA",
            },
        [80030410] = {
            ["Content"] = "在我被姐姐们欺骗着，想要成为绅士的年纪，老爹就已经是军团里的士官了。那时他在前线的时间多，在家的时间少，和我现在差不多吧。",
            ["ContentFR"] = "À l’époque où mes sœurs me dupaient pour que je devienne un gentleman, lui, il était déjà sergent dans la Légion. Il passait plus de temps au front qu’à la maison, un peu comme moi aujourd’hui.",
            ["DialogueId"] = 80030410,
            ["GUID"] = "C8590524",
            ["NextDialogue"] = 80030411,
            ["SpeakNpcId"] = 94202,
            ["TalkActionId"] = {
                [1] = "94202:Sit_Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Landi/004/C8590524",
            },
        [80030411] = {
            ["Content"] = "不过和我现在不一样的是，他非常看重自己身上的军装。似乎对于他来说，军队才是自己的家，而我和姐姐们在的地方，不过是可以任意挑剔的旅店罢了。",
            ["ContentFR"] = "Mais à la différence de moi, il était fier de son uniforme. Pour lui, la Légion était sa vraie maison, et notre foyer n’était qu’un hôtel où il pouvait se plaindre à sa guise.",
            ["DialogueId"] = 80030411,
            ["GUID"] = "C859054E",
            ["NextDialogue"] = 80030412,
            ["SpeakNpcId"] = 94202,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/004/C859054E",
            },
        [80030412] = {
            ["Content"] = "每次他回到家，总是要发上一些牢骚，有时候是皇帝的画像没有挂正，有时候是姐姐们回家太晚。",
            ["ContentFR"] = "À chaque retour, il râlait. La photo de l’Empereur était mal accrochée. Mes sœurs rentraient trop tard...",
            ["DialogueId"] = 80030412,
            ["GUID"] = "C8590578",
            ["NextDialogue"] = 80030413,
            ["SpeakNpcId"] = 94202,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/004/C8590578",
            },
        [80030413] = {
            ["Content"] = "但是每一次都会有一个保留节目，就是发起一场对我的检阅。",
            ["ContentFR"] = "Mais il y avait toujours un rituel. Il m’inspectait.",
            ["DialogueId"] = 80030413,
            ["GUID"] = "C85905A2",
            ["NextDialogue"] = 80030414,
            ["SpeakNpcId"] = 94202,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/004/C85905A2",
            },
        [80030414] = {
            ["Content"] = "又长高了几厘米，又看了几本书，又记住了几座要塞的名字，又学会了几种求生技能，他会一一问一遍。",
            ["ContentFR"] = "Il mesurait ma taille, comptait mes lectures, vérifiait si je connaissais les noms des forteresses, et demandait mes nouvelles compétences de survie.",
            ["DialogueId"] = 80030414,
            ["GUID"] = "C85905CC",
            ["NextDialogue"] = 80030415,
            ["SpeakNpcId"] = 94202,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/004/C85905CC",
            },
        [80030415] = {
            ["Content"] = "我也试过和他讨论其他话题，但是他对于“成为军人”以外的所有事情都毫无兴趣。",
            ["ContentFR"] = "J’ai essayé de parler d’autre chose, mais rien ne l’intéressait en dehors d’être \"soldat\".",
            ["DialogueId"] = 80030415,
            ["GUID"] = "C85905F6",
            ["NextDialogue"] = 80030416,
            ["SpeakNpcId"] = 94202,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/004/C85905F6",
            },
        [80030416] = {
            ["Content"] = "有一次，我为了迎合他，像现在制造小工具那样，小心用木头刻了一把手枪，满心欢喜等着他的夸奖。",
            ["ContentFR"] = "Un jour, pour lui faire plaisir, j’ai sculpté une petite arme en bois, comme mes gadgets actuels, tout fier d’attendre ses compliments.",
            ["DialogueId"] = 80030416,
            ["GUID"] = "C8590620",
            ["NextDialogue"] = 80030417,
            ["SpeakNpcId"] = 94202,
            ["TalkActionId"] = {
                [1] = "94202:Sit_Talk03ToTalkL_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Landi/004/C8590620",
            },
        [80030417] = {
            ["Content"] = "但他只是把手枪“梆”地一下砸在桌子上，板起脸来：“少做这些浪费时间的闲事，多把心思放在如何成为一个优秀的军人上。”",
            ["ContentFR"] = "Mais il l’a juste jetée sur la table en disant d’un ton sévère : « Arrête ces bêtises et concentre-toi sur comment devenir un bon soldat. »",
            ["DialogueId"] = 80030417,
            ["GUID"] = "C859064A",
            ["NextDialogue"] = 80030418,
            ["SpeakNpcId"] = 94202,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/004/C859064A",
            },
        [80030418] = {
            ["Content"] = "那时候我的心里突然多了一种东西，像是屋子外面的风一样，冷，刀割一样，又摸不到，还无法停止。",
            ["ContentFR"] = "À ce moment-là, j’ai ressenti un froid, une douleur tranchante comme le vent dehors, invisible et insupportable.",
            ["DialogueId"] = 80030418,
            ["GUID"] = "C8590674",
            ["NextDialogue"] = 80030419,
            ["SpeakNpcId"] = 94202,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/004/C8590674",
            },
        [80030419] = {
            ["Content"] = "后来我才逐渐意识到，那也许是恨意，虽然没有十分强烈，但是已经足够让我觉得面前的这个人讨厌，陌生。",
            ["ContentFR"] = "Avec le temps, j’ai compris que c’était de la haine, pas très forte, mais suffisante pour voir cet homme comme un inconnu détestable.",
            ["DialogueId"] = 80030419,
            ["GUID"] = "C859069E",
            ["NextDialogue"] = 80030420,
            ["SpeakNpcId"] = 94202,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/004/C859069E",
            },
        [80030420] = {
            ["Content"] = "在那过后，我就不再试图迎合他了，也不管他的检阅，也不管他骂我是“废物”或者什么更难听的话。",
            ["ContentFR"] = "Après ça, j’ai arrêté de chercher à lui plaire, ignoré ses inspections, et ses insultes.",
            ["DialogueId"] = 80030420,
            ["GUID"] = "C85906C8",
            ["NextDialogue"] = 80030421,
            ["SpeakNpcId"] = 94202,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/004/C85906C8",
            },
        [80030421] = {
            ["Content"] = "直到有一天，他突然被送了回来——在战斗中为了保护下属，被弹片击中了脑袋，虽然活着，但是没了意识。",
            ["ContentFR"] = "Puis un jour, il est revenu, blessé à la tête en protégeant ses hommes. Il était vivant, mais inconscient.",
            ["DialogueId"] = 80030421,
            ["GUID"] = "C85906F2",
            ["NextDialogue"] = 80030422,
            ["SpeakNpcId"] = 94202,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/004/C85906F2",
            },
        [80030422] = {
            ["Content"] = "他没什么额外的积蓄，所有的薪水都寄回了家里，和他一起被送回来的，除了锃亮的勋章以外，就只有一把断成两截的木枪。",
            ["ContentFR"] = "Il n’avait pas d’économies, avait envoyé tout son salaire à la maison, et la seule chose qui l’accompagnait, c’était une médaille brillante... et une arme en bois cassée en deux.",
            ["DialogueId"] = 80030422,
            ["GUID"] = "C859071C",
            ["NextDialogue"] = 80030423,
            ["SpeakNpcId"] = 94202,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/004/C859071C",
            },
        [80030423] = {
            ["Content"] = "我原来以为这是因为他对我失望透顶，但是他的那些下属告诉我，这把木枪他随身带着，是他在战场上倒下时折断的。",
            ["ContentFR"] = "Je pensais que c’était parce qu’il était déçu de moi, mais ses hommes m’ont dit qu’il gardait toujours cette arme sur lui, et qu’elle s’est cassée quand il est tombé.",
            ["DialogueId"] = 80030423,
            ["GUID"] = "C8590746",
            ["NextDialogue"] = 80030424,
            ["SpeakNpcId"] = 94202,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/004/C8590746",
            },
        [80030424] = {
            ["Content"] = "他似乎在心底里认可我。但是我无法接受这样的认可。",
            ["ContentFR"] = "Au fond, il m’aimait, mais sa façon de le montrer m’était insupportable.",
            ["DialogueId"] = 80030424,
            ["GUID"] = "C8590770",
            ["NextDialogue"] = 80030425,
            ["SpeakNpcId"] = 94202,
            ["TalkActionId"] = {
                [1] = "94202:Sit_Talk03ToTalkL_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Landi/004/C8590770",
            },
        [80030425] = {
            ["Content"] = "如果真的为我感到骄傲，我更希望他能够亲口说出来，哪怕最简单的一句鼓励也好，而不是一直在逼迫着我干着不想干的事情。",
            ["ContentFR"] = "S’il avait été fier, j’aurais préféré qu’il le dise clairement, un simple encouragement aurait suffi, plutôt que de me forcer à faire ce que je n’aimais pas.",
            ["DialogueId"] = 80030425,
            ["GUID"] = "C859079A",
            ["NextDialogue"] = 80030426,
            ["SpeakNpcId"] = 94202,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/004/C859079A",
            },
        [80030426] = {
            ["Content"] = "虽然老爹已经不会再爬起来敲我的脑壳，我还是按照他一直以来的要求，加入了军团。",
            ["ContentFR"] = "Même s’il ne me pousse plus, j’ai quand même rejoint la Légion comme il le voulait.",
            ["DialogueId"] = 80030426,
            ["GUID"] = "C85907C4",
            ["NextDialogue"] = 80030427,
            ["SpeakNpcId"] = 94202,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/004/C85907C4",
            },
        [80030427] = {
            ["Content"] = "我好奇那到底是一个怎样的地方，能让老爹变成一个沉默寡言的家伙，也想证明，哪怕没有按照他的呵斥，我也能混出一个不错的日子。",
            ["ContentFR"] = "Je voulais comprendre cet endroit qui a fait de lui un homme taciturne, et prouver que je pouvais m’en sortir, même sans ses reproches.",
            ["DialogueId"] = 80030427,
            ["GUID"] = "C85907EE",
            ["NextDialogue"] = 80030428,
            ["SpeakNpcId"] = 94202,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/004/C85907EE",
            },
        [80030428] = {
            ["Content"] = "不过对他和对我来说都很不幸的是，当我加入军团后，才发现他说得其实没错。",
            ["ContentFR"] = "Mais malheureusement, quand j’ai rejoint la Légion, j’ai compris qu’il avait raison, il voulait me protéger.",
            ["DialogueId"] = 80030428,
            ["GUID"] = "C8590818",
            ["NextDialogue"] = 80030429,
            ["SpeakNpcId"] = 94202,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/004/C8590818",
            },
        [80030429] = {
            ["Content"] = "我们和军团的大多数人不一样。我们从战场的尸骸堆中爬出来，跪着接过他们施舍的勋章。",
            ["ContentFR"] = "Nous ne sommes pas comme les autres dans la Légion. On s’est traînés hors des charniers, à genoux pour recevoir des médailles balancées comme une aumône.",
            ["DialogueId"] = 80030429,
            ["GUID"] = "C8590842",
            ["NextDialogue"] = 80030430,
            ["SpeakNpcId"] = 94202,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/004/C8590842",
            },
        [80030430] = {
            ["Content"] = "体面的工作，优渥的生活，甚至生存本身——我们的一切都维系在那些小小的勋章上。父亲为了我们的家，奉上了自己的一切。",
            ["ContentFR"] = "Un boulot digne, une vie confortable, notre survie même, tout dépend de ces petites médailles. Mon père a tout donné pour notre famille.",
            ["DialogueId"] = 80030430,
            ["GUID"] = "C859086C",
            ["NextDialogue"] = 80030431,
            ["SpeakNpcId"] = 94202,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/004/C859086C",
            },
        [80030431] = {
            ["Content"] = "他去服从，去忍耐，去压抑感情，让自己习惯哀嚎和哭泣，让自己成为这匹巨兽口中的一枚獠牙。",
            ["ContentFR"] = "Il a obéi, supporté, caché ses émotions, s’est habitué à la douleur et aux pleurs, et s’est fait une carapace.",
            ["DialogueId"] = 80030431,
            ["GUID"] = "C8590896",
            ["NextDialogue"] = 80030432,
            ["SpeakNpcId"] = 94202,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/004/C8590896",
            },
        [80030432] = {
            ["Content"] = "我做不到这些，但又要一笔钱养活自己，维持家庭现有的体面，所以就只能这样悬在半空，做一个废物。",
            ["ContentFR"] = "Moi, je ne peux pas faire ça. Mais j’ai besoin d’argent pour vivre et maintenir la dignité de ma famille. Du coup, je reste là, suspendu entre deux mondes, un raté heureux.",
            ["DialogueId"] = 80030432,
            ["GUID"] = "C85908C0",
            ["NextOptions"] = {
                [1] = 800304321,
                },
            ["SpeakNpcId"] = 94202,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/004/C85908C0",
            },
        [80030433] = {
            ["Content"] = "……",
            ["ContentFR"] = "...",
            ["DialogueId"] = 80030433,
            ["GUID"] = "C85908EA",
            ["NextDialogue"] = 80030434,
            ["SpeakNpcId"] = 94202,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/004/C85908EA",
            },
        [80030434] = {
            ["Content"] = "你确实很敏锐。说实话，我到底在干什么，也是在消沉了很久之后才想明白。",
            ["ContentFR"] = "Tu es vraiment perspicace. Pour être honnête, j’ai longtemps été perdu.",
            ["DialogueId"] = 80030434,
            ["GUID"] = "C8590914",
            ["NextDialogue"] = 80030435,
            ["SpeakNpcId"] = 94202,
            ["TalkActionId"] = {
                [1] = "94202:Sit_Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Landi/004/C8590914",
            },
        [80030435] = {
            ["Content"] = "虽然我的选择和老爹的期望有一些差距，但是我并不觉得这是一件坏事。",
            ["ContentFR"] = "Même si mon choix diffère de ce qu’il voulait, je ne regrette pas ma vie.",
            ["DialogueId"] = 80030435,
            ["GUID"] = "C859093E",
            ["NextOptions"] = {
                [1] = 800304351,
                [2] = 800304352,
                },
            ["SpeakNpcId"] = 94202,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/004/C859093E",
            },
        [80030436] = {
            ["Content"] = "希望如此吧，这样一来，这场噩梦应该就能结束了。",
            ["ContentFR"] = "J’espère bien. Si ça arrive, mes cauchemars pourront enfin s’arrêter.",
            ["DialogueId"] = 80030436,
            ["GUID"] = "C8590968",
            ["NextDialogue"] = 80030438,
            ["SpeakNpcId"] = 94202,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/004/C8590968",
            },
        [80030437] = {
            ["Content"] = "真是好饮料啊，喝完了后，一定不会再做噩梦的。",
            ["ContentFR"] = "Excellent, avec ça je devrais enfin dormir sans cauchemars.",
            ["DialogueId"] = 80030437,
            ["GUID"] = "C8590992",
            ["NextDialogue"] = 80030438,
            ["SpeakNpcId"] = 94202,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/004/C8590992",
            },
        [80030438] = {
            ["Content"] = "谢了，我的请假之交，只不过现在为了明天不请假，必须得回去补上一觉了。",
            ["ContentFR"] = "Merci, {性别:mon|ma} pote de vacances, mais maintenant je dois dormir un peu, sinon je vais devoir demander un autre jour de congé demain.",
            ["DialogueId"] = 80030438,
            ["GUID"] = "C85909BC",
            ["NextDialogue"] = 80030439,
            ["SpeakNpcId"] = 94202,
            ["TalkActionId"] = {
                [1] = "94202:Sit_Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Landi/004/C85909BC",
            },
        [80030439] = {
            ["Content"] = "别担心，下次见面的时候，我还是你熟悉的那个兰迪。万一我又做噩梦了，就劳烦你再给我调制一杯饮料吧。",
            ["ContentFR"] = "T’inquiète, la prochaine fois qu’on se voit, je serai le Randy que tu connais. Et si je fais encore un cauchemar, je compte sur toi pour me préparer un autre verre.",
            ["DialogueId"] = 80030439,
            ["GUID"] = "C85909E6",
            ["SpeakNpcId"] = 94202,
            ["TalkActionId"] = {
                [1] = "94202:Sit_Talk01_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Landi/004/C85909E6",
            },
        [80030501] = {
            ["Camera"] = "184.82782,72.338623,127.99707,0.000026,1.199654,-136.185898,35.0,125.0,false,Disable,2.8",
            ["Content"] = "一杯热饮，多加点糖。另外，我还从皇都带了一些甜点来，我趁着休假排队买的，你可以尝尝。",
            ["ContentFR"] = "Un petit remontant, bien sucré s’il te plaît. Et tiens, j’ai ramené quelques douceurs de l’Empire. J’ai fait la queue pendant mon jour de repos... Goûte-moi ça.",
            ["DialogueId"] = 80030501,
            ["GUID"] = "C8591412",
            ["LookAt"] = {
                [1] = "94202:p(18000P1)",
                },
            ["NextOptions"] = {
                [1] = 800305011,
                [2] = 800305012,
                },
            ["SpeakNpcId"] = 94202,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/005/C8591412",
            },
        [80030502] = {
            ["Content"] = "是啊，所以想喝点甜的，作为接下来邀请的铺垫。",
            ["ContentFR"] = "Exactement. Une boisson sucrée, pour adoucir... une petite requête.",
            ["DialogueId"] = 80030502,
            ["GUID"] = "C859143C",
            ["NextDialogue"] = 80030504,
            ["SpeakNpcId"] = 94202,
            ["TalkActionId"] = {
                [1] = "94202:Sit_AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Landi/005/C859143C",
            },
        [80030503] = {
            ["Content"] = "绝无此事！虽然我确实想要向你发出一则邀请，但是这并不能被称作企图！",
            ["ContentFR"] = "Quoi ?! Pas du tout ! Bon... ok, j’ai bel et bien une petite faveur à te demander. Mais c’est pas un piège, promis.",
            ["DialogueId"] = 80030503,
            ["GUID"] = "C8591466",
            ["NextDialogue"] = 80030504,
            ["SpeakNpcId"] = 94202,
            ["TalkActionId"] = {
                [1] = "94202:Sit_DisagreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Landi/005/C8591466",
            },
        [80030504] = {
            ["Content"] = "咳咳……嗯，虽然有点突然，但是要不要和我跳一支舞？",
            ["ContentFR"] = "Ahem... Je sais que ça sort de nulle part, mais... ça te dirait de m’accompagner au bal ?",
            ["DialogueId"] = 80030504,
            ["GUID"] = "C8591490",
            ["NextDialogue"] = 80030505,
            ["SpeakNpcId"] = 94202,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/005/C8591490",
            },
        [80030505] = {
            ["Content"] = "就是，军团总要和一些地方势力打好关系，比如之前和你说过的，去内城参加一些必要但是很烦人的社交仪式。",
            ["ContentFR"] = "Tu sais, ces soirées diplomatiques dans la cité intérieure, avec la noblesse et tout le cirque, des événements indispensables pour que la Légion conserve de bonnes relations avec les pouvoirs locaux.",
            ["DialogueId"] = 80030505,
            ["GUID"] = "C85914BA",
            ["NextDialogue"] = 80030506,
            ["SpeakNpcId"] = 94202,
            ["TalkActionId"] = {
                [1] = "94202:Sit_Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Landi/005/C85914BA",
            },
        [80030506] = {
            ["Content"] = "我好不想去啊，就算是给我算因公出差，应付那些老爷夫人也是怪麻烦的。",
            ["ContentFR"] = "Franchement, j’ai zéro envie d’y aller. Même en mission officielle, devoir sourire à la noblesse, c’est juste insupportable.",
            ["DialogueId"] = 80030506,
            ["GUID"] = "C85914E4",
            ["NextDialogue"] = 80030507,
            ["SpeakNpcId"] = 94202,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/005/C85914E4",
            },
        [80030507] = {
            ["Content"] = "所以呢，我想了一个一劳永逸的方法，那就是带着一位足够美丽的女士一同入场，和我共舞一曲。",
            ["ContentFR"] = "Du coup, j’ai eu une idée de génie : Y aller au bras d’une partenaire splendide.",
            ["DialogueId"] = 80030507,
            ["GUID"] = "C859150E",
            ["NextDialogue"] = 80030508,
            ["SpeakNpcId"] = 94202,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/005/C859150E",
            },
        [80030508] = {
            ["Content"] = "这样一来，就不会有人凑上来，向我介绍那些他们自己可能也没见过几面的远方女性亲眷了吧。",
            ["ContentFR"] = "Comme ça, personne n’osera m’interrompre pour me présenter leurs cousines célibataires qu’ils ont vues trois fois dans leur vie.",
            ["DialogueId"] = 80030508,
            ["GUID"] = "C8591538",
            ["NextOptions"] = {
                [1] = 800305081,
                [2] = 800305082,
                },
            ["SpeakNpcId"] = 94202,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/005/C8591538",
            },
        [80030509] = {
            ["Content"] = "就……我觉得……你也许可以尝试一下男扮……",
            ["ContentFR"] = "Eh bien... je me disais... peut-être... tu pourrais envisager un petit déguisement ?",
            ["DialogueId"] = 80030509,
            ["GUID"] = "C8591562",
            ["NextOptions"] = {
                [1] = 800305091,
                [2] = 800305092,
                },
            ["SpeakNpcId"] = 94202,
            ["TalkActionId"] = {
                [1] = "94202:Sit_Talk02_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Landi/005/C8591562",
            },
        [80030510] = {
            ["Content"] = "哎呀，这不是因为邀请的是我嘛。",
            ["ContentFR"] = " Je ne peux pas. C’est moi l’invité, après tout.",
            ["DialogueId"] = 80030510,
            ["GUID"] = "C859158C",
            ["NextDialogue"] = 80030512,
            ["SpeakNpcId"] = 94202,
            ["TalkActionId"] = {
                [1] = "94202:Sit_Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Landi/005/C859158C",
            },
        [80030511] = {
            ["Content"] = "哎呀，我也是实在没有办法，才想出了这个主意。",
            ["ContentFR"] = "Je t’en prie, j’ai épuisé toutes mes options. T’es ma dernière chance.",
            ["DialogueId"] = 80030511,
            ["GUID"] = "C85915B6",
            ["NextDialogue"] = 80030512,
            ["SpeakNpcId"] = 94202,
            ["TalkActionId"] = {
                [1] = "94202:Sit_Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Landi/005/C85915B6",
            },
        [80030512] = {
            ["Content"] = "我们都喝了这么多顿酒了，你在我心里早就是比姐姐们还要亲近的兄弟了，否则我也不会想到你。",
            ["ContentFR"] = "On a bu combien de fois ensemble, hein ? Pour moi, t’es déjà plus proche que mes propres sœurs ! C’est justement parce que t’es mon meilleur pote que je te le demande.",
            ["DialogueId"] = 80030512,
            ["GUID"] = "C85915E0",
            ["NextDialogue"] = 80030513,
            ["SpeakNpcId"] = 94202,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/005/C85915E0",
            },
        [80030513] = {
            ["Content"] = "所以在这种关头，帮我一把，我接下来半年月俸都分你一半！",
            ["ContentFR"] = "Allez, arrête de faire cette tête. Si tu m’aides, je te file la moitié de mon salaire pendant six mois ! Et si la commandante Sibylle essaie encore de t’arrêter, je me sacrifierai pour te couvrir !",
            ["DialogueId"] = 80030513,
            ["GUID"] = "C859160A",
            ["NextDialogue"] = 80030514,
            ["SpeakNpcId"] = 94202,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/005/C859160A",
            },
        [80030514] = {
            ["Content"] = "你要是实在不乐意，等舞会回来，换我穿舞裙给你看好不好。",
            ["ContentFR"] = "Et si ça ne te suffit pas, je me mettrai moi-même en robe après le bal, rien que pour toi. Ça te va ?",
            ["DialogueId"] = 80030514,
            ["GUID"] = "C8591634",
            ["NextOptions"] = {
                [1] = 800305141,
                [2] = 800305142,
                },
            ["SpeakNpcId"] = 94202,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/005/C8591634",
            },
        [80030515] = {
            ["Content"] = "别……别误会，不不不不是这样的，我没有那样的兴趣，你怎么会往那个方向去想？",
            ["ContentFR"] = "Non, non, non ! Tu te méprends complètement, c’est pas du tout ce que tu crois !",
            ["DialogueId"] = 80030515,
            ["GUID"] = "C859165E",
            ["NextDialogue"] = 80030516,
            ["SpeakNpcId"] = 94202,
            ["TalkActionId"] = {
                [1] = "94202:Sit_DisagreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Landi/005/C859165E",
            },
        [80030516] = {
            ["Content"] = "好兄弟一起吃饭，一起玩耍，一起上厕所，一起穿裙子之类的，很正常吧。",
            ["ContentFR"] = "Je veux dire, c’est normal, non ? Entre vrais potes, on fait tout ensemble : sortir, manger, aller aux toilettes et essayer des robes. C’est ça, l’amitié !",
            ["DialogueId"] = 80030516,
            ["GUID"] = "C8591688",
            ["NextOptions"] = {
                [1] = 800305161,
                },
            ["SpeakNpcId"] = 94202,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/005/C8591688",
            },
        [80030517] = {
            ["Content"] = "唉，你别笑啊，我可是很认真地在发愁呢，给个答复吧。要是不答应的话，我得想想其他办法了……",
            ["ContentFR"] = "Allez, rigole pas... je suis vraiment en détresse là. Dis-moi juste si t’acceptes, sinon je vais devoir me creuser la tête pour un autre plan...",
            ["DialogueId"] = 80030517,
            ["GUID"] = "C85916B2",
            ["NextOptions"] = {
                [1] = 800305171,
                [2] = 800305172,
                },
            ["SpeakNpcId"] = 94202,
            ["TalkActionId"] = {
                [1] = "94202:Sit_Talk01_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Landi/005/C85916B2",
            },
        [80030518] = {
            ["Content"] = "你可以再考虑考虑，实在不行……",
            ["ContentFR"] = "Réfléchis encore un peu, hein...",
            ["DialogueId"] = 80030518,
            ["GUID"] = "C85916DC",
            ["NextDialogue"] = 80030519,
            ["SpeakNpcId"] = 94202,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/005/C85916DC",
            },
        [80030519] = {
            ["Content"] = "等等？你答应了？太好了！你简直就是我异父异母的亲兄弟！",
            ["ContentFR"] = "Attends... tu dis que tu acceptes ? Sérieux ? T’es un vrai frère, même si on est pas de la même famille !",
            ["DialogueId"] = 80030519,
            ["FacialId"] = {
                [1] = "94202:Shock01",
                },
            ["GUID"] = "C8591706",
            ["NextDialogue"] = 80030520,
            ["SpeakNpcId"] = 94202,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/005/C8591706",
            },
        [80030520] = {
            ["Content"] = "这次是我欠了你一个天大的人情，我得要想请假理由那样，想各种方法还掉才是。",
            ["ContentFR"] = "Je te dois une fière chandelle. Je vais devoir me creuser la tête pour te la rendre.",
            ["DialogueId"] = 80030520,
            ["FacialId"] = {
                [1] = "94202:None",
                },
            ["GUID"] = "C8591730",
            ["NextDialogue"] = 80030521,
            ["SpeakNpcId"] = 94202,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/005/C8591730",
            },
        [80030521] = {
            ["Content"] = "不过，那也得等舞会结束再说了。现在呀，我得趁着你还没反悔，先回去准备衣服啦。",
            ["ContentFR"] = "Mais bon, on verra ça après le bal. Pour l’instant, faut que je file préparer ma tenue avant que tu reviennes sur ta décision. ",
            ["DialogueId"] = 80030521,
            ["GUID"] = "C859175A",
            ["NextDialogue"] = 80030522,
            ["SpeakNpcId"] = 94202,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/005/C859175A",
            },
        [80030522] = {
            ["Content"] = "回头见，我的请假之交，休息之友，到今天为止的追捕目标。",
            ["ContentFR"] = "Allez, à plus, mon complice de pause, mon partenaire de galère, et la raison de toutes mes aventures jusqu’à maintenant.",
            ["DialogueId"] = 80030522,
            ["GUID"] = "C8591784",
            ["SpeakNpcId"] = 94202,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/005/C8591784",
            },
        [80030523] = {
            ["Content"] = "呜，你要不要再考虑考虑，舞会结束后，我会像编造请假理由那样，想出各种方法来报答你的！",
            ["ContentFR"] = "Je comprends. Mais n’oublie pas. Après le bal, je trouverai toutes sortes de façons créatives pour te rendre la pareille, comme quand je cherche des excuses pour poser des congés.",
            ["DialogueId"] = 80030523,
            ["GUID"] = "C85917AE",
            ["NextDialogue"] = 80030524,
            ["SpeakNpcId"] = 94202,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/005/C85917AE",
            },
        [80030524] = {
            ["Content"] = "不过，我觉得现在得安静下来，留出一些空间让你思考才是。不过，我还是希望你能答应，也相信你一定会答应的！",
            ["ContentFR"] = "Pour l’instant, je vais me calmer un peu et te laisser de l’espace pour y penser. Cela dit, j’espère vraiment que tu accepteras, et je suis sûr que tu le feras !",
            ["DialogueId"] = 80030524,
            ["GUID"] = "C85917D8",
            ["NextDialogue"] = 80030525,
            ["SpeakNpcId"] = 94202,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/005/C85917D8",
            },
        [80030525] = {
            ["Content"] = "那么，我先回去了，等你的好消息，我的请假之交，休息之友。",
            ["ContentFR"] = "Bon, je file alors. J’attends de tes nouvelles, mon complice de pause, mon partenaire de galère, et la raison de toutes mes aventures jusqu’à maintenant.",
            ["DialogueId"] = 80030525,
            ["GUID"] = "C8591802",
            ["SpeakNpcId"] = 94202,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/005/C8591802",
            },
        [80030526] = {
            ["Content"] = "没错，你显然也意识到了，没有比你更适合的舞伴了……所以，你能不能帮帮我，解开这个困境。",
            ["ContentFR"] = "Exact. Tu es clairement la meilleure partenaire pour ce bal... Alors, tu veux bien me filer un coup de main et me sortir de ce pétrin ?",
            ["DialogueId"] = 80030526,
            ["GUID"] = "C8591856",
            ["NextOptions"] = {
                [1] = 800305261,
                },
            ["SpeakNpcId"] = 94202,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/005/C8591856",
            },
        [80030527] = {
            ["Content"] = "嗯……？",
            ["ContentFR"] = "Hein ?",
            ["DialogueId"] = 80030527,
            ["GUID"] = "C8591880",
            ["NextDialogue"] = 80030528,
            ["SpeakNpcId"] = 94202,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/005/C8591880",
            },
        [80030528] = {
            ["Content"] = "啊？！怎么可能，你怎么能这么想？我真想要帮你绑了立功的话，第一次坐在这里的时候就可以动手了！",
            ["ContentFR"] = "Quoi ?! Comment tu peux penser ça ? Si je voulais vraiment t’arrêter, je l’aurais déjà fait la première fois qu’on s’est vus !",
            ["DialogueId"] = 80030528,
            ["FacialId"] = {
                [1] = "94202:Shock01",
                },
            ["GUID"] = "C85918AA",
            ["NextDialogue"] = 80030529,
            ["SpeakNpcId"] = 94202,
            ["TalkActionId"] = {
                [1] = "94202:Sit_Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Landi/005/C85918AA",
            },
        [80030529] = {
            ["Content"] = "根本不用专门请假到这里这么多次后，再编造出一个舞会来诱捕你。",
            ["ContentFR"] = "Pas besoin de poser mes précieux jours de congé juste pour organiser une \"soirée piège\".",
            ["DialogueId"] = 80030529,
            ["GUID"] = "C85918D4",
            ["NextDialogue"] = 80030530,
            ["SpeakNpcId"] = 94202,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/005/C85918D4",
            },
        [80030530] = {
            ["Content"] = "更何况，即便想要引诱你也不会选择用邀请你跳舞这种方式吧，万一被拒绝了怎么办？",
            ["ContentFR"] = "Et puis, même si je voulais te piéger, t’inviter à danser, ce serait bizarre, non ? Et si tu disais non ?",
            ["DialogueId"] = 80030530,
            ["GUID"] = "C85918FE",
            ["NextDialogue"] = 80030531,
            ["SpeakNpcId"] = 94202,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/005/C85918FE",
            },
        [80030531] = {
            ["Content"] = "啊啊，你是在开玩笑吧，不然我只能理解为，在你眼里，我是一个又坏又蠢的烦人家伙。",
            ["ContentFR"] = "Rassure-moi, c’était une blague ? Sinon, tu me prends vraiment pour un idiot sans scrupules, prêt à trahir mes amis pour avancer...",
            ["DialogueId"] = 80030531,
            ["GUID"] = "C8591928",
            ["NextOptions"] = {
                [1] = 800305311,
                [2] = 800305312,
                },
            ["SpeakNpcId"] = 94202,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/005/C8591928",
            },
        [80030532] = {
            ["Content"] = "还好还好，如果真的被误会成打算背叛重要的朋友，换取前途的无耻之徒的话，我会因为太过心痛而请一个月的病假的。",
            ["ContentFR"] = "Ouf... Parce que si tu pensais vraiment ça de moi, je crois que je prendrais un mois d’arrêt maladie juste pour m’en remettre.",
            ["DialogueId"] = 80030532,
            ["FacialId"] = {
                [1] = "94202:None",
                },
            ["GUID"] = "C8591952",
            ["NextDialogue"] = 80030534,
            ["SpeakNpcId"] = 94202,
            ["TalkActionId"] = {
                [1] = "94202:Sit_Talk01_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Landi/005/C8591952",
            },
        [80030533] = {
            ["Content"] = "喂喂喂，至少否定一下后半句吧！要是我当真了怎么办！",
            ["ContentFR"] = "Hé, au moins nie la partie où je trahis mes amis pour une promotion, ça ferait moins mal à mon petit cœur !",
            ["DialogueId"] = 80030533,
            ["FacialId"] = {
                [1] = "94202:None",
                },
            ["GUID"] = "C859197C",
            ["NextDialogue"] = 80030534,
            ["SpeakNpcId"] = 94202,
            ["TalkActionId"] = {
                [1] = "94202:Sit_Talk01_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Landi/005/C859197C",
            },
        [80030534] = {
            ["Content"] = "不过我现在有一点可以肯定，那么就是，你其实从一开始，就根本没有担心有什么危险。",
            ["ContentFR"] = "Mais maintenant, une chose est sûre : tu n’as jamais vraiment eu peur du danger.",
            ["DialogueId"] = 80030534,
            ["GUID"] = "C85919A6",
            ["NextDialogue"] = 80030535,
            ["SpeakNpcId"] = 94202,
            ["TalkActionId"] = {
                [1] = "94202:Sit_Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Landi/005/C85919A6",
            },
        [80030535] = {
            ["Content"] = "而是单纯地恶作剧，设想了一个最坏的可能，想看我的反应。",
            ["ContentFR"] = "Tu faisais juste une blague, en imaginant le pire scénario, pour voir ma réaction.",
            ["DialogueId"] = 80030535,
            ["GUID"] = "C85919D0",
            ["NextOptions"] = {
                [1] = 800305351,
                [2] = 800305352,
                },
            ["SpeakNpcId"] = 94202,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/005/C85919D0",
            },
        [80030536] = {
            ["Content"] = "我原来以为只有我会有这种捉弄人不正经的习惯，怎么你也这么恶趣味。也不知道和谁学来的。",
            ["ContentFR"] = "Je croyais que j’étais le seul à être aussi joueur et taquin, mais toi aussi, hein ? D’où tu sors ça ?",
            ["DialogueId"] = 80030536,
            ["GUID"] = "C85919FA",
            ["NextDialogue"] = 80030537,
            ["SpeakNpcId"] = 94202,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/005/C85919FA",
            },
        [80030537] = {
            ["Content"] = "我确实有那么一瞬间慌了几秒，虽然理智上知道不可能，但是感性上还是在担心，万一你是真的这么觉得呢？",
            ["ContentFR"] = "J’avoue, j’ai eu un moment de doute. Même si je savais que c’était impossible, au fond, j’ai flippé, et si c’était vrai ?",
            ["DialogueId"] = 80030537,
            ["GUID"] = "C8591A24",
            ["NextDialogue"] = 80030538,
            ["SpeakNpcId"] = 94202,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/005/C8591A24",
            },
        [80030538] = {
            ["Content"] = "所以，作为恶作剧的补偿，你必须答应我的邀请。",
            ["ContentFR"] = "Alors, pour compenser ta blague, tu dois accepter mon invitation.",
            ["DialogueId"] = 80030538,
            ["GUID"] = "C8591A4E",
            ["NextOptions"] = {
                [1] = 800305431,
                [2] = 800305172,
                },
            ["SpeakNpcId"] = 94202,
            ["TalkActionId"] = {
                [1] = "94202:Sit_Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Landi/005/C8591A4E",
            },
        [80030539] = {
            ["Content"] = "哈？",
            ["ContentFR"] = "Quoi ?!",
            ["DialogueId"] = 80030539,
            ["FacialId"] = {
                [1] = "94202:Shock01",
                },
            ["GUID"] = "C8591A78",
            ["NextDialogue"] = 80030540,
            ["SpeakNpcId"] = 94202,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/005/C8591A78",
            },
        [80030540] = {
            ["Content"] = "好吧，你说得没错！我一直想要逮捕你，白天，夜里，只要是大脑没有在休假，就在谋划逮捕你的计划。只是因为我一直都是偷懒耍滑，迟迟都没有实践。",
            ["ContentFR"] = "Bon, tu as raison ! J’ai toujours voulu t’arrêter, matin et soir, dès que mon cerveau était réveillé, j’y pensais ! Mais je procrastine tellement que je n’ai jamais passé à l’acte.",
            ["DialogueId"] = 80030540,
            ["FacialId"] = {
                [1] = "94202:None",
                },
            ["GUID"] = "C8591AA2",
            ["NextDialogue"] = 80030541,
            ["SpeakNpcId"] = 94202,
            ["TalkActionId"] = {
                [1] = "94202:Sit_AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Landi/005/C8591AA2",
            },
        [80030541] = {
            ["Content"] = "难得这次想认真干活，却被识破了，怎么办呀——",
            ["ContentFR"] = "Cette fois, je voulais vraiment faire le boulot, mais tu m’as démasqué... Que faire ?",
            ["DialogueId"] = 80030541,
            ["GUID"] = "C8591ACC",
            ["NextDialogue"] = 80030542,
            ["SpeakNpcId"] = 94202,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/005/C8591ACC",
            },
        [80030542] = {
            ["Content"] = "看来我迟早会被军团扫地出门，流落在冰湖城的严寒街道上，又冷，又饿，无家可归……",
            ["ContentFR"] = "Je finirai par me faire virer de la Légion, à errer dans les rues glaciales de Givrelac, seul, affamé, sans abri...",
            ["DialogueId"] = 80030542,
            ["GUID"] = "C8591AF6",
            ["NextDialogue"] = 80030543,
            ["SpeakNpcId"] = 94202,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/005/C8591AF6",
            },
        [80030543] = {
            ["Content"] = "你真的能够眼睁睁看着我成为街头的雪雕吗？",
            ["ContentFR"] = "Tu veux vraiment me voir finir en statue de glace sur le trottoir ?",
            ["DialogueId"] = 80030543,
            ["GUID"] = "C8591B20",
            ["NextOptions"] = {
                [1] = 800305431,
                [2] = 800305172,
                },
            ["SpeakNpcId"] = 94202,
            ["TalkActionId"] = {
                [1] = "94202:Sit_Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Landi/005/C8591B20",
            },
        [80030544] = {
            ["Content"] = "你可以再考虑考虑，实在不行……",
            ["ContentFR"] = "Réfléchis encore un peu, hein...",
            ["DialogueId"] = 80030544,
            ["GUID"] = "C8591B4A",
            ["NextDialogue"] = 80030545,
            ["SpeakNpcId"] = 94202,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/005/C8591B4A",
            },
        [80030545] = {
            ["Content"] = "等等？你答应了？太好了！你简直……简直……简直是我异父异母的亲姐妹！",
            ["ContentFR"] = "Attends... tu dis que tu acceptes ? Sérieux ? T’es une vraie sœur, même si on n’est pas de la même famille !",
            ["DialogueId"] = 80030545,
            ["GUID"] = "C8591B74",
            ["NextDialogue"] = 80030546,
            ["SpeakNpcId"] = 94202,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/005/C8591B74",
            },
        [80030546] = {
            ["Content"] = "这次是我欠了你一个天大的人情，我得要想请假理由那样，想各种方法还掉才是。",
            ["ContentFR"] = "Je te dois une fière chandelle. Je vais devoir me creuser la tête pour te la rendre.",
            ["DialogueId"] = 80030546,
            ["GUID"] = "C8591B9E",
            ["NextDialogue"] = 80030547,
            ["SpeakNpcId"] = 94202,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/005/C8591B9E",
            },
        [80030547] = {
            ["Content"] = "不过，那也得等舞会结束再说了。现在呀，我得趁着你还没反悔，先回去准备衣服啦。",
            ["ContentFR"] = "Mais bon, on verra ça après le bal. Pour l’instant, faut que je file préparer ma tenue avant que tu ne reviennes sur ta décision.",
            ["DialogueId"] = 80030547,
            ["GUID"] = "C8591BC8",
            ["NextDialogue"] = 80030548,
            ["SpeakNpcId"] = 94202,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/005/C8591BC8",
            },
        [80030548] = {
            ["Content"] = "回头见，我的请假之交，休息之友。",
            ["ContentFR"] = "Allez, à plus, ma complice de pause, ma partenaire de galère, et la raison de toutes mes aventures jusqu’à maintenant.",
            ["DialogueId"] = 80030548,
            ["GUID"] = "C8591BF2",
            ["SpeakNpcId"] = 94202,
            ["VoiceName"] = "voice/$Locale$/inv/Landi/005/C8591BF2",
            },
        [80040101] = {
            ["Camera"] = "-52.422852,-88.373047,123.091431,0.000216,-4.998045,54.58065,40.000011,196.024292,false,Manual,4.967944",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "这样就做好了，贝蕾尝尝看吧！",
            ["ContentFR"] = "Voilà, c’est prêt. Vas-y, dis-moi ce que tu en penses, Berry.",
            ["DefaultLookAt"] = "TalkNpc",
