            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Heitao/001/C85F3B90",
            },
        [80040105] = {
            ["Content"] = "不可以吗？我记得小时候你也很喜欢石榴的。",
            ["ContentFR"] = "Et alors ? Je me souviens que tu adorais les grenades, avant.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 80040105,
            ["FacialId"] = {
                [1] = "790007:Shock02",
                },
            ["GUID"] = "C85F3BBA",
