            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Heitao/001/C85F3BE4",
            },
        [80040107] = {
            ["Content"] = "所以这次石榴结果的时候，我专门摘了来……你已经不喜欢了吗？",
            ["ContentFR"] = "Alors cette fois, j’en ai pris exprès rien que pour toi... Tu n’aimes plus ça, maintenant ?",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 80040107,
            ["FacialId"] = {
                [1] = "790008:Smile01",
                },
            ["GUID"] = "C85F3C0E",
