            },
        [80040124] = {
            ["Content"] = "…………",
            ["ContentFR"] = "...",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 80040124,
            ["GUID"] = "C85F3ED8",
            ["NextDialogue"] = 80040125,
            ["SpeakNpcId"] = 790008,
            ["TalkActionId"] = {
                [1] = "790007:Sigh_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Heitao/001/C85F3ED8",
            },
        [80040125] = {
            ["Camera"] = "113.315186,151.120361,105.79834,0.000122,6.203184,-112.57106,40.0,164.391006,false,Manual,5.845709",
            ["Content"] = "没有没有，你做饭大多数时候都很棒，只是刚好这两次有点不巧。",
            ["ContentFR"] = "Pas du tout ! La plupart du temps, tes plats sont super bons. Ces deux fois, c’était juste... pas de chance.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 80040125,
            ["FacialId"] = {
