            },
        [80040132] = {
            ["Camera"] = "95.760498,168.30957,108.807495,0.000322,1.199449,-118.340714,25.0,282.428741,false,Manual,2.79054",
            ["Content"] = "为什么？",
            ["ContentFR"] = "Pourquoi ?",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 80040132,
            ["GUID"] = "C85F4028",
            ["NextDialogue"] = 80040133,
            ["SpeakNpcId"] = 790007,
            ["TalkActionId"] = {
                [1] = "790008:Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Heitao/001/C85F4028",
            },
        [80040133] = {
            ["Camera"] = "95.760498,168.30957,108.807495,0.000322,1.199449,-118.340714,25.0,282.428741,false,Manual,2.79054",
            ["Content"] = "味道这种东西听别人说太无聊了，你得自己尝。",
            ["ContentFR"] = "Le goût, ça ne se raconte pas, ça se découvre par soi-même.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 80040133,
            ["GUID"] = "C85F4052",
            ["NextDialogue"] = 80040134,
            ["SpeakNpcId"] = 790008,
            ["TalkActionId"] = {
                [1] = "790008:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Heitao/001/C85F4052",
            },
        [80040134] = {
            ["Camera"] = "-173.155518,-29.748779,137.313843,0.000326,-3.800016,-5.949226,35.000008,211.470428,false,Manual,2.79054",
            ["Content"] = "如果贝蕾是喝下药剂导致分不出味道，那外面肯定也有一种药剂可以让你再次尝出味道吧？",
            ["ContentFR"] = "Si c’est bien cette potion qui t’a fait perdre le goût, alors il doit forcément exister un remède, quelque part, pour te le rendre.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 80040134,
            ["FacialId"] = {
                [1] = "790008:Smile01",
                },
            ["FinalCamera"] = "-172.891357,-26.610596,137.313843,0.000326,-3.800016,-6.94926,35.000008,211.470428,false,Manual,2.79054",
            ["GUID"] = "C85F407C",
            ["NextDialogue"] = 80040135,
            ["SpeakNpcId"] = 790008,
            ["TalkActionId"] = {
                [1] = "790008:Explain01_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Heitao/001/C85F407C",
            },
        [80040135] = {
            ["Camera"] = "-425.241211,98.722656,62.558838,0.000359,6.599335,-20.947884,35.0,476.22876,false,Manual,12.234338",
            ["Content"] = "好，从今天起我要好好赚钱了。早点去到岛外面去，早点买到那种药！",
            ["ContentFR"] = "À partir d’aujourd’hui, je vais me battre pour gagner de l’argent, sortir de cette île au plus vite, et dénicher ce remède !",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 80040135,
            ["FinalCamera"] = "-427.385742,93.11792,62.558838,0.000359,6.599335,-19.947929,35.000008,482.809113,false,Manual,14.941204",
            ["GUID"] = "C85F40A6",
            ["NextDialogue"] = 80040136,
            ["SpeakNpcId"] = 790008,
            ["TalkActionId"] = {
                [1] = "790008:Angry01_Start",
                },
            ["ToFinalCameraBlendTime"] = 20,
            ["VoiceName"] = "voice/$Locale$/inv/Heitao/001/C85F40A6",
            },
        [80040136] = {
            ["Camera"] = "-33.544434,-5.307129,160.189575,0.000367,-19.800526,-12.556828,35.0,211.470428,false,DoNotOverride,2.79054",
            ["Content"] = "等你能尝出味道了，咱们就把全世界所有的美食都吃一遍……当然，还有你最喜欢的石榴，我们买一大堆石榴，把这个房间塞满。",
            ["ContentFR"] = "Et le jour où tu retrouveras le goût... on mangera tous les plats du monde. Et on remplira cette pièce de grenades !",
            ["DialogueId"] = 80040136,
            ["FacialId"] = {
                [1] = "790008:Happy02",
                },
            ["FinalCamera"] = "-32.419434,-0.398926,160.189575,0.000366,-19.800526,-15.957611,35.0,211.470428,false,DoNotOverride,2.79054",
            ["GUID"] = "C85F40D0",
