        [80040201] = {
            ["Camera"] = "32.020996,-408.154297,83.524414,0.000112,2.699038,107.178726,35.000008,497.258331,false,Manual,1.2",
            ["Content"] = "到家了。贝蕾，快坐下！",
            ["ContentFR"] = "Enfin chez nous. Vite, Berry, assieds-toi !",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 80040201,
            ["FinalCamera"] = "42.265381,-405.020264,83.524414,0.000113,2.699038,108.578911,35.000008,497.258331,false,Manual,1.2",
