        [80040204] = {
            ["Camera"] = "-63.011719,2.983643,162.785645,-0.000092,-22.699921,59.573631,35.000008,497.258331,false,DoNotOverride,1.2",
            ["Content"] = "你刚才受伤了吧？把手给我，我给你包一下。",
            ["ContentFR"] = "Tu t’es blessée tout à l’heure, non ? Donne-moi ta main, je vais te soigner.",
