                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Heitao/003/C85F5F54",
            },
        }
  end },
  { MinKey = 80040323, MaxKey = 80050438, Loader = function()
      return {
        [80040323] = {
