        [80050307] = {
            ["Content"] = "小声点，你不想奥特赛德听到你偷跑出来吧。",
            ["ContentFR"] = "Chut, parle doucement, tu ne voudrais pas que l’Étranger entende qu’on s’est {性别:faufilés|faufilées}, hein ?",
            ["DialogueId"] = 80050307,
            ["GUID"] = "C865C57E",
            ["NextDialogue"] = 80050308,
            },
        [80050308] = {
            ["Camera"] = "-78.46582,31.777893,128.363281,0.000091,-6.59982,-104.609161,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "啊——对不起对不起……",
            ["ContentFR"] = "Ah... désolée, désolée...",
            ["DialogueId"] = 80050308,
            ["FacialId"] = {
                [1] = "790017:Sad01",
