            ["TalkActionId"] = {
                [1] = "790017:Explain01_End",
                },
            ["ToFinalCameraBlendTime"] = 1,
            ["VoiceName"] = "voice/$Locale$/inv/Feina/003/C865C6A4",
            },
        [80050315] = {
            ["Content"] = "…………",
            ["ContentFR"] = "...",
            ["DialogueId"] = 80050315,
            ["FacialId"] = {
                [1] = "790017:Disappoint01",
                },
            ["GUID"] = "C865C6CE",
            ["NextOptions"] = {
                [1] = 80050316,
                },
            ["SpeakNpcId"] = 790017,
            ["VoiceName"] = "voice/$Locale$/inv/Feina/003/C865C6CE",
            },
        [80050316] = {
            ["Content"] = "怎么了？你不认识的话，我来告诉你吧。",
            ["ContentFR"] = "Qu’est-ce qui se passe ? Si tu ne reconnais pas, je peux t’aider.",
            ["DialogueId"] = 80050316,
            ["GUID"] = "C865C6F8",
            ["NextDialogue"] = 80050317,
            },
        [80050317] = {
            ["Camera"] = "-65.606445,-263.350464,109.867432,0.000101,0.000478,109.002274,35.000011,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "……我是知道的。",
            ["ContentFR"] = "... Je sais.",
            ["DialogueId"] = 80050317,
            ["GUID"] = "C865C722",
            ["NextDialogue"] = 80050318,
            ["SpeakNpcId"] = 790017,
            ["TalkActionId"] = {
                [1] = "790017:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Feina/003/C865C722",
            },
        [80050318] = {
            ["Camera"] = "-65.606445,-263.350464,109.867432,0.000101,0.000478,109.002274,35.000011,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "那是内城……菲娜长大的地方。看……那个方向，就是我以前住过的房子。",
            ["ContentFR"] = "C’est la cité intérieure... là où j’ai grandi. Regarde... cette maison, c’est là où je vivais avant.",
            ["DialogueId"] = 80050318,
            ["GUID"] = "C865C74C",
            ["NextOptions"] = {
                [1] = 80050319,
                [2] = 80050321,
                },
            ["SpeakNpcId"] = 790017,
            ["VoiceName"] = "voice/$Locale$/inv/Feina/003/C865C74C",
            },
        [80050319] = {
            ["Content"] = "原来菲娜是有钱人家的大小姐啊，真好。",
            ["ContentFR"] = "Alors tu viens d’une famille riche, c’est chouette.",
            ["DialogueId"] = 80050319,
            ["GUID"] = "C865C776",
            ["NextDialogue"] = 80050320,
            },
        [80050320] = {
            ["Content"] = "不，一点儿也不好。",
            ["ContentFR"] = "Non, c’était loin d’être chouette.",
            ["DialogueId"] = 80050320,
            ["GUID"] = "C865C7A0",
            ["NextDialogue"] = 80050323,
            ["SpeakNpcId"] = 790017,
            ["TalkActionId"] = {
                [1] = "790017:DisagreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Feina/003/C865C7A0",
            },
        [80050321] = {
            ["Content"] = "你很想念那儿吗？",
            ["ContentFR"] = "Elle te manque, cette maison ?",
            ["DialogueId"] = 80050321,
            ["GUID"] = "C865C7CA",
            ["NextDialogue"] = 80050322,
            },
        [80050322] = {
            ["Camera"] = "-61.318359,8.6604,109.648682,0.000008,0.0,-104.999664,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "不，不想。一点儿也不想。",
            ["ContentFR"] = "Non, pas du tout.",
            ["DialogueId"] = 80050322,
            ["GUID"] = "C865C7F4",
            ["NextDialogue"] = 80050323,
            ["SpeakNpcId"] = 790017,
            ["TalkActionId"] = {
                [1] = "790017:DisagreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Feina/003/C865C7F4",
            },
        [80050323] = {
            ["Camera"] = "-101.632812,-105.954285,114.34375,0.000072,0.999728,-97.801895,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "因为那里是房子，不是家。",
            ["ContentFR"] = "Parce que c’était une maison, pas un vrai foyer.",
            ["DialogueId"] = 80050323,
            ["GUID"] = "C865C81E",
            ["NextDialogue"] = 80050324,
            ["SpeakNpcId"] = 790017,
            ["TalkActionId"] = {
                [1] = "790017:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Feina/003/C865C81E",
            },
        [80050324] = {
            ["Camera"] = "-52.174805,-292.937622,109.959473,0.00007,-1.40012,109.791321,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "菲娜的爸爸和妈妈都去了很远很远的国度。都是在八月，都是在暴雨的夜晚。",
            ["ContentFR"] = "Mon père et ma mère sont partis dans un pays lointain. C’était en août, une nuit de forte pluie.",
            ["DialogueId"] = 80050324,
            ["GUID"] = "C865C848",
            ["NextDialogue"] = 80050325,
            ["SpeakNpcId"] = 790017,
            ["TalkActionId"] = {
                [1] = "790017:Explain01_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Feina/003/C865C848",
            },
        [80050325] = {
            ["Camera"] = "2649.62207,-5001.596191,-1486.966064,7.200227,0.799276,-178.809067,35.000011,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "爸爸被“坏猎人”带走了，他的脖子上套着绞索，身体挂在天空中。",
            ["ContentFR"] = "Mon père a été emmené par un \"chasseur cruel\", il avait une corde au cou, son corps pendait dans le ciel.",
            ["DialogueId"] = 80050325,
            ["FinalCamera"] = "2247.921875,-5009.945801,-1481.363281,7.200307,0.799276,-178.809067,35.000011,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "C865C872",
            ["NextDialogue"] = 80050326,
            ["SpeakNpcId"] = 790017,
            ["TalkActionId"] = {
                [1] = "790017:Disagree",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Feina/003/C865C872",
            },
        [80050326] = {
            ["Camera"] = "-7238.111328,-5586.991699,-2040.967285,7.243233,-14.796771,-166.212799,35.000011,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "妈妈被凶猛的“野兽”杀死了，大雨冲刷掉了她像玫瑰一样鲜红的血，什么也不剩。",
            ["ContentFR"] = "Ma mère a été tuée par une \"bête sauvage\", la pluie a emporté son sang rouge comme une rose, il ne reste plus rien.",
            ["DialogueId"] = 80050326,
            ["FinalCamera"] = "-7238.111328,-5586.991699,-2040.967285,7.245794,-5.59622,164.383118,35.000015,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "C865C89C",
            ["NextDialogue"] = 80050327,
            ["SpeakNpcId"] = 790017,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Feina/003/C865C89C",
            },
        [80050327] = {
            ["Camera"] = "-61.800781,64.192169,129.852539,0.000068,-7.399963,-108.799545,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "他们去了很远很远的国度……那里已经没有菲娜的家了。",
            ["ContentFR"] = "Ils sont partis dans un pays très loin... et il n’y a plus de maison pour moi là-bas.",
            ["DialogueId"] = 80050327,
            ["GUID"] = "C865C8C6",
            ["IsBlack"] = 1,
            ["NextOptions"] = {
                [1] = 80050328,
                [2] = 80050329,
                },
            ["SpeakNpcId"] = 790017,
            ["VoiceName"] = "voice/$Locale$/inv/Feina/003/C865C8C6",
            },
        [80050328] = {
            ["Content"] = "（摸摸菲娜的头。）",
            ["ContentFR"] = "Lui caresser la tête",
            ["DialogueId"] = 80050328,
            ["GUID"] = "C865C8F0",
            ["NextDialogue"] = 80050330,
            },
        [80050329] = {
            ["Content"] = "（抱一抱她。）",
            ["ContentFR"] = "La prendre dans les bras",
            ["DialogueId"] = 80050329,
            ["GUID"] = "C865C91A",
            ["NextDialogue"] = 80050330,
            },
        [80050330] = {
            ["Camera"] = "-61.800781,64.192169,129.852539,0.000068,-7.399963,-108.799545,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "独角兽{性别：先生|小姐}的手，也暖暖的呢……",
            ["ContentFR"] = "Les mains de {性别:Monsieur|Mademoiselle} Licorne sont si chaudes...",
            ["DialogueId"] = 80050330,
            ["GUID"] = "C865C944",
            ["IsBlack"] = 1,
            ["NextOptions"] = {
                [1] = 80050331,
                },
            ["SpeakNpcId"] = 790017,
            ["TalkActionId"] = {
                [1] = "790017:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Feina/003/C865C944",
            },
        [80050331] = {
            ["Content"] = "还记得你讲过的“鸟儿和星星”的故事吗？",
            ["ContentFR"] = "Tu te souviens de l’histoire que tu m’as racontée ? Celle du petit oiseau et des étoiles ?",
            ["DialogueId"] = 80050331,
            ["GUID"] = "C865C96E",
            ["NextDialogue"] = 80050332,
            },
        [80050332] = {
            ["Camera"] = "408.845703,-129.991882,-10.434082,0.000055,3.199656,177.195557,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "菲娜的爸爸和妈妈……也许也变成了天上的星。虽然它们不会说话了，却依旧沉默但温柔地注视着你。",
            ["ContentFR"] = "Peut-être que tes parents sont devenus des étoiles dans le ciel. Même s’ils ne parlent plus, ils te regardent en silence, avec douceur.",
            ["DialogueId"] = 80050332,
            ["FinalCamera"] = "408.845703,-129.991882,-10.434082,0.000055,8.599618,177.395554,35.000008,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "C865C998",
            ["NextDialogue"] = 80050333,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "790017:Explain02_End",
                [2] = "100001:Explain01_Start",
                },
            ["ToFinalCameraBlendTime"] = 4,
            ["VoiceName"] = "voice/$Locale$/inv/Feina/003/C865C998",
            },
        [80050333] = {
            ["Content"] = "想他们的时候，就对夜空笑一笑吧。",
            ["ContentFR"] = "Quand tu penses à eux, souris-leur dans la nuit étoilée.",
            ["DialogueId"] = 80050333,
            ["GUID"] = "C865C9C2",
            ["NextDialogue"] = 80050334,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Explain01_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Feina/003/C865C9C2",
            },
        [80050334] = {
            ["Camera"] = "-101.089844,-114.304626,115.5979,0.000041,2.199259,-98.406013,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "嗯……好……我会试试的。",
            ["ContentFR"] = "Oui... d’accord... je vais essayer.",
            ["DialogueId"] = 80050334,
            ["FacialId"] = {
                [1] = "790017:Satisfy01",
                [2] = "100001:Sad01",
                },
            ["GUID"] = "C865C9EC",
            ["NextDialogue"] = 80050335,
            ["SpeakNpcId"] = 790017,
            ["TalkActionId"] = {
                [1] = "790017:AgreeHead",
                [2] = "100001:Sad02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Feina/003/C865C9EC",
            },
        [80050335] = {
            ["Camera"] = "-64.15625,-266.238037,110.220703,0.000082,-0.001892,107.984558,35.000015,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "没关系，没关系的，你不要为我难过。因为菲娜现在已经有了新的家。",
            ["ContentFR"] = "Ne t’inquiète pas, ne sois pas triste pour moi. Parce que maintenant, j’ai un nouveau foyer.",
            ["DialogueId"] = 80050335,
            ["GUID"] = "C865CA16",
            ["NextDialogue"] = 80050336,
            ["SpeakNpcId"] = 790017,
            ["TalkActionId"] = {
                [1] = "790017:DisagreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Feina/003/C865CA16",
            },
        [80050336] = {
            ["Camera"] = "-109.111328,-35.609192,129.727539,0.000115,-9.201903,-90.815498,35.000015,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我有大魔法师，还有你。现在的我啊，已经很满足了。",
            ["ContentFR"] = "J’ai le Grand Magicien, et puis toi. Je suis déjà comblée.",
            ["DialogueId"] = 80050336,
            ["FacialId"] = {
                [1] = "790017:Happy02",
                },
            ["FinalCamera"] = "-109.111328,-35.609192,129.727539,0.000117,-6.401854,-90.81559,35.000015,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "C865CA40",
            ["SpeakNpcId"] = 790017,
            ["TalkActionId"] = {
                [1] = "100001:Sad02_End",
                },
            ["ToFinalCameraBlendTime"] = 3,
            ["VoiceName"] = "voice/$Locale$/inv/Feina/003/C865CA40",
            },
        [80050401] = {
            ["Camera"] = "111.911438,2.710388,118.670654,0.000003,0.0,-152.600952,35.0,160.0,false,Manual,2.8",
            ["Content"] = "独角兽{性别：先生|小姐}，你来啦。",
            ["ContentFR"] = "Te voilà, {性别:Monsieur|Mademoiselle} Licorne !",
            ["DialogueId"] = 80050401,
            ["FacialId"] = {
                [1] = "790017:Happy02",
                },
            ["GUID"] = "C865D4EA",
            ["NextOptions"] = {
                [1] = 80050402,
                },
            ["SpeakNpcId"] = 790017,
            ["TalkActionId"] = {
                [1] = "790017:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Feina/004/C865D4EA",
            },
        [80050402] = {
            ["Content"] = "这是最后一个愿望了吧。这次菲娜是想去哪儿？",
            ["ContentFR"] = "C’est ton dernier vœu, non ? Où veux-tu aller cette fois, Fina ?",
            ["DialogueId"] = 80050402,
            ["GUID"] = "C865D514",
            ["NextDialogue"] = 80050403,
            },
        [80050403] = {
            ["Content"] = "嗯……这次哪儿也不去。因为菲娜的最后一个愿望，已经在这里了。",
            ["ContentFR"] = "Hmm... cette fois, on n’ira nulle part. Parce que mon dernier vœu... est déjà ici, avec toi.",
            ["DialogueId"] = 80050403,
            ["FacialId"] = {
                [1] = "790017:None",
                },
            ["GUID"] = "C865D53E",
            ["NextDialogue"] = 80050404,
            ["SpeakNpcId"] = 790017,
            ["TalkActionId"] = {
                [1] = "790017:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Feina/004/C865D53E",
            },
        [80050404] = {
            ["Content"] = "你看，我把新的故事书带来了！",
            ["ContentFR"] = "Regarde, j’ai apporté mon nouveau livre d’histoires !",
            ["DialogueId"] = 80050404,
            ["FacialId"] = {
                [1] = "790017:Happy01",
                },
            ["GUID"] = "C865D568",
            ["NextDialogue"] = 80050405,
            ["SpeakNpcId"] = 790017,
            ["TalkActionId"] = {
                [1] = "790017:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Feina/004/C865D568",
            },
        [80050405] = {
            ["Content"] = "原来是菲娜自己编的故事集啊……咦，怎么是空白的？",
