        [80070107] = {
            ["Camera"] = "-118.393959,-109.984428,23.003906,0.000025,18.800102,61.800278,35.000008,369.962646,false,Manual,9.880018",
            ["Content"] = "好了，既然专程汇报，说明有些事你一个少校都拿不准，说说看吧。",
            ["ContentFR"] = "Bien. Puisque tu es venue spécialement pour faire ton rapport, c’est que tu as des doutes, même à ton rang. Parle donc.",
            ["DialogueId"] = 80070107,
            ["GUID"] = "C87275EE",
