            },
        [80070108] = {
            ["Camera"] = "-16.022058,-23.41791,119.476562,0.000012,4.399871,-83.797165,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "是的，我收拾出几件军团长的东西，感觉还是得给您看一下。",
            ["ContentFR"] = "Oui, en rangeant le bureau, j’ai retrouvé quelques affaires personnelles à vous, et je me suis dit que vous voudriez jeter un œil.",
            ["DialogueId"] = 80070108,
            ["GUID"] = "C8727618",
            ["NextDialogue"] = 80070109,
            ["SpeakNpcId"] = 790014,
            ["TalkActionId"] = {
                [1] = "790014:Give",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/001/C8727618",
            },
        [80070109] = {
            ["Content"] = "先是这批印着佩剑炼金院纹章的文件，看起来有些年头了。",
            ["ContentFR"] = "D’abord, ces documents portant le sceau des Spathatoi... Ils ont l’air anciens.",
            ["DialogueId"] = 80070109,
            ["GUID"] = "C8727642",
            ["NextDialogue"] = 80070110,
            ["SpeakNpcId"] = 790014,
            ["TalkActionId"] = {
                [1] = "790014:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/001/C8727642",
            },
        [80070110] = {
            ["Content"] = "佩剑炼金院的事宜一向由您亲自过问，我不便查阅。您看下这些文件怎么处理。",
            ["ContentFR"] = "Les affaires des Spathatoi ont toujours été de votre ressort, je n’ai pas osé fouiller. Que voulez-vous faire de ces papiers, commandante ?",
            ["DialogueId"] = 80070110,
            ["GUID"] = "C872766C",
            ["NextDialogue"] = 80070111,
            ["SpeakNpcId"] = 790014,
            ["TalkActionId"] = {
                [1] = "790014:Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/001/C872766C",
            },
        [80070111] = {
            ["Camera"] = "-29.486694,-231.213272,139.712891,0.000004,-3.599571,79.597282,45.0,369.962646,false,Manual,9.880018",
            ["Content"] = "这些是……几年前的炼金院走私案里，兰迪事后整理出的走私清单，可以丢掉了。",
            ["ContentFR"] = "Ce sont... des listes de contrebande datant de plusieurs années, réunies par Randy à l’époque. Elles peuvent être jetées.",
            ["DialogueId"] = 80070111,
            ["GUID"] = "C8727696",
            ["NextDialogue"] = 80070112,
            ["SpeakNpcId"] = 790013,
            ["TalkActionId"] = {
                [1] = "790013:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/001/C8727696",
            },
        [80070112] = {
            ["Camera"] = "-18.71162,-52.899345,121.708984,0.000012,4.399871,-83.797165,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "走私清单……那不是很重要的证据吗？",
            ["ContentFR"] = "Des listes de contrebande... Ce ne sont pas des preuves importantes ?",
            ["DialogueId"] = 80070112,
            ["GUID"] = "C87276C0",
            ["NextDialogue"] = 80070113,
            ["SpeakNpcId"] = 790014,
            ["TalkActionId"] = {
                [1] = "790013:Explain01_End",
                [2] = "790014:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/001/C87276C0",
            },
        [80070113] = {
            ["Camera"] = "-87.774124,-53.601727,54.482422,0.000029,17.19998,61.800571,35.000008,369.962646,false,Manual,9.880018",
            ["Content"] = "十三军团作为皇帝陛下的直属军团，行动时往往只需要“目的”，不需要“证据”。",
            ["ContentFR"] = "La XIIIᵉ Légion, en tant qu’armée directe de Sa Majesté, agit selon des objectifs, pas selon des preuves.",
            ["DialogueId"] = 80070113,
            ["FinalCamera"] = "-84.453262,-36.544121,59.619141,0.000028,17.19998,61.800621,35.000008,369.962646,false,Manual,9.880018",
            ["GUID"] = "C87276EA",
            ["NextDialogue"] = 80070114,
            ["SpeakNpcId"] = 790013,
            ["TalkActionId"] = {
                [1] = "790014:Explain02_End",
                [2] = "790013:Talk03_Start",
                },
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/001/C87276EA",
            },
        [80070114] = {
            ["Content"] = "会疑惑也很正常，毕竟你先前工作针对的都是外部敌人，还没碰过内部的虫豸。借此机会给你讲一下也好。",
            ["ContentFR"] = "Je comprends ta confusion. Jusqu’ici, tu as combattu des ennemis externes, mais tu n’as pas encore affronté les machinations internes. Profite de cette occasion pour comprendre.",
            ["DialogueId"] = 80070114,
            ["GUID"] = "C8727714",
            ["NextDialogue"] = 80070115,
            ["SpeakNpcId"] = 790013,
            ["TalkActionId"] = {
                [1] = "790013:Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/001/C8727714",
            },
        [80070115] = {
            ["Content"] = "当我们的行动涉及帝国其他组织时，一切“过程”都不再重要，十三军团，只看重陛下所要的“结果”。",
            ["ContentFR"] = "Quand nos opérations croisent d’autres institutions impériales, le \"comment\" importe peu. La XIIIᵉ ne regarde que les \"résultats\" souhaités par Sa Majesté.",
            ["DialogueId"] = 80070115,
            ["GUID"] = "C872773E",
            ["IsBlack"] = 1,
            ["SpeakNpcId"] = 790013,
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/001/C872773E",
            },
        [80070116] = {
            ["Camera"] = "524.42627,-192.475586,223.517578,0.000009,-12.600278,160.80278,35.000008,369.962646,false,Manual,9.880018",
            ["Content"] = "维勒斯先生，你涉嫌参与黑市上的炼金器械走私案，自己走还是我来帮你走？",
            ["ContentFR"] = "Monsieur Willers, vous êtes accusé de trafic d’équipements alchimiques sur le marché noir. Vous vous rendez volontairement, ou dois-je vous escorter ?",
            ["DialogueId"] = 80070116,
            ["FinalCamera"] = "532.717896,-168.658752,223.517578,0.000009,-12.600278,160.80278,35.000008,369.962646,false,Manual,9.880018",
            ["GUID"] = "C8727768",
            ["NextDialogue"] = 80070117,
            ["SpeakNpcId"] = 790015,
            ["TalkActionId"] = {
                [1] = "790015:Explain01_Start",
                },
            ["ToFinalCameraBlendTime"] = 7,
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/001/C8727768",
            },
        [80070117] = {
            ["Camera"] = "-216.380081,-25.239105,134.419922,0.000003,0.599745,13.60984,35.0,100000.0,false,Manual,10.0",
            ["Content"] = "我可是高级炼金术师，就算你们十三军团背后是皇帝，也不能为所欲为吧！",
            ["ContentFR"] = "Je suis un alchimiste de haut rang ! Même si la XIIIᵉ agit au nom de l’Empereur, vous ne pouvez pas faire ce que bon vous semble !",
            ["DialogueId"] = 80070117,
            ["GUID"] = "C8727792",
            ["NextDialogue"] = 80070118,
            ["SpeakNpcId"] = 790016,
            ["TalkActionId"] = {
                [1] = "790015:Explain01_End",
                [2] = "790016:Shock_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/001/C8727792",
            },
        [80070118] = {
            ["Camera"] = "-28.744118,-95.146759,106.203125,0.000002,9.199704,137.200348,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "嘘，劝你想好了再说。只是走私的话，运气好的人还能留一条命，若是诋毁和质疑陛下的旨意，可就要按叛国罪处理了。",
            ["ContentFR"] = "Chut. Réfléchis bien avant de parler. Le trafic, c’est pardonnable, et certains ont la chance de survivre. Mais insulter Sa Majesté, c’est trahison, passible de la peine capitale.",
            ["DialogueId"] = 80070118,
            ["GUID"] = "C87277BC",
            ["NextDialogue"] = 80070119,
            ["SpeakNpcId"] = 790015,
            ["TalkActionId"] = {
                [1] = "790015:Talk03_Start",
                [2] = "790016:Shock_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/001/C87277BC",
            },
        [80070119] = {
            ["Camera"] = "-216.380081,-25.239105,134.419922,0.000003,0.599745,13.60984,35.0,100000.0,false,Manual,10.0",
            ["Content"] = "嗯……要不你还是说下去吧，这样我都不用费劲把你押回去，现在给你一枪就完事了。来，你继续说。",
            ["ContentFR"] = "Hmm... En fait, tu ferais mieux de continuer. Ça m’évitera de t’escorter, je peux te descendre ici et maintenant. Vas-y, parle.",
            ["DialogueId"] = 80070119,
            ["GUID"] = "C87277E6",
            ["NextDialogue"] = 80070120,
            ["Scripts"] = "SEQ{PlayAnimation{ActorId{790015},AnimationId{\"Talk03_End\"},Duration{1}},PlayAnimation{ActorId{790015},AnimationId{\"Think_Start\"},Duration{3}}}",
            ["SpeakNpcId"] = 790015,
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/001/C87277E6",
            },
        [80070120] = {
            ["Content"] = "不，不敢……我对陛下和帝国忠心耿耿，绝无二心……那些炼金器械都是失败品，与其销毁，我想着还不如换点钱买些新器械……",
            ["ContentFR"] = "N-non... Je suis loyal à Sa Majesté et à l’Empire, sans la moindre arrière-pensée... Ces appareils étaient défectueux, je voulais juste les échanger contre de l’argent pour en acheter de nouveaux...",
            ["DialogueId"] = 80070120,
            ["GUID"] = "C8727810",
            ["NextDialogue"] = 80070121,
            ["SpeakNpcId"] = 790016,
            ["TalkActionId"] = {
                [1] = "790015:Think_End",
                [2] = "790016:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/001/C8727810",
            },
        [80070121] = {
            ["Camera"] = "1.974182,790.534241,-2.171875,0.0,7.599726,-89.396553,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "这批器械对炼金院来说是没用，但是如果经由黑市流通到神弃者同盟、甚至艾利西安人手上呢？",
            ["ContentFR"] = "Ces appareils ne servent plus à l’Académie, mais s’ils tombent entre les mains des Déchus ou pire, des Élyséens via le marché noir, tu imagines les conséquences ?",
            ["DialogueId"] = 80070121,
            ["FinalCamera"] = "1.650574,821.253418,-6.269531,0.0,7.599726,-89.396553,35.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "C872783A",
            ["NextDialogue"] = 80070122,
            ["SpeakNpcId"] = 790013,
            ["TalkActionId"] = {
                [1] = "790013:Explain01_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["TurnTo"] = {
                [1] = "790015:n(790013)",
                [2] = "790016:n(790013)",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/001/C872783A",
            },
        [80070122] = {
            ["Camera"] = "133.41275,-15.108414,77.826172,0.000001,3.799675,-114.404198,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "虽然是残次品，但它们会被一一拆解、研究，炼金院的技术机密就会由此泄露，那便意味着更多的伤亡。",
            ["ContentFR"] = "Même s’ils sont défectueux, ils seront démontés, étudiés. Les secrets techniques de l’Académie seraient alors compromis, ce qui causerait davantage de morts.",
            ["DialogueId"] = 80070122,
            ["GUID"] = "C8727864",
            ["NextDialogue"] = 80070123,
            ["SpeakNpcId"] = 790013,
            ["TalkActionId"] = {
                [1] = "790013:Explain01_End",
                },
            ["TurnTo"] = {
                [1] = "790013:n(790016)",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/001/C8727864",
            },
        [80070123] = {
            ["Content"] = "你在后方赚的这些走私钱，沾着多少前线士兵的鲜血，数过吗？",
            ["ContentFR"] = "L’argent que tu as gagné en contrebande est taché du sang de nos soldats au front. Tu as réfléchi à ça ?",
            ["DialogueId"] = 80070123,
            ["GUID"] = "C872788E",
            ["NextDialogue"] = 80070124,
            ["SpeakNpcId"] = 790013,
            ["TalkActionId"] = {
                [1] = "790013:Confident_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/001/C872788E",
            },
        [80070124] = {
            ["Camera"] = "802.744385,-2917.147705,950.736328,0.000016,-14.799558,100.006508,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "他们不会控诉你，因为他们已是死去的英雄，而你，则是盘旋在英雄尸体上营营嗡响的恶臭蝇虫。",
            ["ContentFR"] = "Eux ne te dénonceront pas, ce sont déjà des héros tombés au combat. Toi, tu n’es qu’un charognard puant, en train de rôder autour de leurs cadavres.",
            ["DialogueId"] = 80070124,
            ["GUID"] = "C87278B8",
            ["NextDialogue"] = 80070125,
            ["SpeakNpcId"] = 790013,
            ["TalkActionId"] = {
                [1] = "790013:Confident_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/001/C87278B8",
            },
        [80070125] = {
            ["Content"] = "帝国，不需要只会喊忠诚口号的苍蝇。",
            ["ContentFR"] = "L’Empire n’a que faire des mouches qui bourdonnent des serments de loyauté.",
            ["DialogueId"] = 80070125,
            ["GUID"] = "C87278E2",
            ["NextDialogue"] = 80070126,
            ["SpeakNpcId"] = 790013,
            ["TalkActionId"] = {
                [1] = "790013:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/001/C87278E2",
            },
        [80070126] = {
            ["Content"] = "不、不……这些走私金额在海伯利亚不至于死罪，你也说过还能留我一条命，我要求更公正的审判！",
            ["ContentFR"] = "N-non... Ces montants ne méritent pas la peine de mort à Hyperborea. Vous avez dit que j’aurais une chance de m’en sortir ! Je réclame un procès équitable !",
            ["DialogueId"] = 80070126,
            ["GUID"] = "C872790C",
            ["NextDialogue"] = 80070127,
            ["SpeakNpcId"] = 790016,
            ["TalkActionId"] = {
                [1] = "790016:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/001/C872790C",
            },
        [80070127] = {
            ["Camera"] = "-5.173111,14.265663,123.404297,0.000001,4.199979,-175.594803,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我说的是，“运气好的人”哦。",
            ["ContentFR"] = "J’ai dit « certains ». Pas toi.",
            ["DialogueId"] = 80070127,
            ["GUID"] = "C8727936",
            ["NextDialogue"] = 800701271,
            ["Scripts"] = "SEQ{TurnTo{TurnToDescription{\"790015:n(790016)\"}},PlayAnimation{ActorId{790015},AnimationId{\"Talk03_Start\"},Duration{2}}}",
            ["SpeakNpcId"] = 790015,
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/001/C8727936",
            },
        [80070128] = {
            ["Camera"] = "-18.071548,-70.088799,137.375,0.000012,-1.200228,-84.797432,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "很好，简单直接。",
            ["ContentFR"] = "Simple et direct. J’aime ça.",
            ["DialogueId"] = 80070128,
            ["FinalCamera"] = "-18.661856,-63.606865,137.505859,0.000012,-1.200228,-84.797432,35.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "C8727960",
            ["NextDialogue"] = 80070129,
            ["SpeakNpcId"] = 790014,
            ["TalkActionId"] = {
                [1] = "790014:Agree",
                },
            ["ToFinalCameraBlendTime"] = 6,
            ["TurnTo"] = {
                [1] = "790013:n(790014)",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/001/C8727960",
            },
        [80070129] = {
            ["Camera"] = "-64.542519,-9.4065,79.558594,0.000028,16.399981,62.800785,35.000008,369.962646,false,Manual,9.880018",
            ["Content"] = "并非如此简单。十三军团只受命于皇帝，我们在暗处，是陛下的袖中剑，掌中刀；但在明处，我们还是传颂他仁德的枭鸟。",
            ["ContentFR"] = "Pas si simple. La XIIIᵉ ne répond qu’à l’Empereur. Dans l’ombre, nous sommes sa lame secrète, son poignard. En plein jour, nous sommes le messager de sa clémence.",
            ["DialogueId"] = 80070129,
            ["GUID"] = "C872798A",
            ["NextDialogue"] = 80070130,
            ["Scripts"] = "SEQ{PlayAnimation{ActorId{790013},AnimationId{\"Disagree\"},Duration{2}},PlayAnimation{ActorId{790013},AnimationId{\"Explain01_Start\"},Duration{3}}}",
            ["SpeakNpcId"] = 790013,
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/001/C872798A",
            },
        [80070130] = {
            ["Content"] = "枪决走私犯并不意味着案件的结束，我们随后还要将炼金术师们叫到一起。",
            ["ContentFR"] = "Exécuter un trafiquant ne clôt pas une affaire. Nous avons dû rassembler les alchimistes pour leur faire passer un message.",
            ["DialogueId"] = 80070130,
            ["GUID"] = "C87279B4",
            ["NextDialogue"] = 80070131,
            ["SpeakNpcId"] = 790013,
            ["TalkActionId"] = {
                [1] = "790013:Explain01_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/001/C87279B4",
            },
        [80070131] = {
            ["Camera"] = "-1357.414917,-1285.646851,0.798828,0.000054,2.999491,42.001163,35.000008,369.962646,false,Manual,9.880018",
            ["Content"] = "想必他们这时已经吓得没法好好说话了吧。",
            ["ContentFR"] = "Ils ont dû être trop terrifiés pour parler, non ?",
            ["DialogueId"] = 80070131,
            ["FinalCamera"] = "-1393.55542,-1245.51001,0.798828,0.000054,2.999491,42.001163,35.000008,369.962646,false,Manual,9.880018",
            ["GUID"] = "C87279DE",
            ["NextDialogue"] = 80070132,
            ["SpeakNpcId"] = 790014,
            ["TalkActionId"] = {
                [1] = "790014:Agree",
                },
            ["ToFinalCameraBlendTime"] = 20,
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/001/C87279DE",
            },
        [80070132] = {
            ["Content"] = "是的，不过他们迎来的不是杀戮，只是一场演讲——还有被钉在演讲台上的维勒斯的尸体。而演讲宣布的是，皇室计划向佩剑炼金院提供更多经费。",
            ["ContentFR"] = "Oui, mais ce n’était pas un massacre, juste un discours. Le corps de Willers cloué à la tribune, et l’annonce d’un financement accru pour les Spathatoi.",
            ["DialogueId"] = 80070132,
            ["GUID"] = "C8727A08",
            ["NextDialogue"] = 80070133,
            ["SpeakNpcId"] = 790013,
            ["TalkActionId"] = {
                [1] = "790013:Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/001/C8727A08",
            },
        [80070133] = {
            ["Content"] = "帝国现在就像轰鸣的战车一般前进，离不开炼金院这座引擎，如果因为走私这颗小小的沙砾拖慢了炼金院的研究进程，反倒违背了陛下的意愿。",
            ["ContentFR"] = "L’Empire avance comme un char de guerre grondant, et l’Académie d’Alchimie est son moteur. Si on ralentit ses recherches à cause d’un grain de sable, c’est aller contre la volonté de Sa Majesté.",
            ["DialogueId"] = 80070133,
            ["GUID"] = "C8727A32",
            ["NextDialogue"] = 80070134,
            ["SpeakNpcId"] = 790013,
            ["TalkActionId"] = {
                [1] = "790013:Talk02_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/001/C8727A32",
            },
        [80070134] = {
            ["Camera"] = "-108.692429,383.760162,74.947266,0.000001,8.799756,-69.593491,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "那就这样放过其他人了？",
            ["ContentFR"] = "Alors les autres s'en sont tirés comme ça, sans autre forme de procès ?",
            ["DialogueId"] = 80070134,
            ["GUID"] = "C8727A5C",
            ["NextDialogue"] = 80070135,
            ["SpeakNpcId"] = 790014,
            ["TalkActionId"] = {
                [1] = "790014:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/001/C8727A5C",
            },
        [80070135] = {
            ["Content"] = "这样就足够了，所有人都看到了背叛帝国的下场。",
            ["ContentFR"] = "C’est suffisant. Tous ont vu ce qu’il arrive à ceux qui trahissent l’Empire.",
            ["DialogueId"] = 80070135,
            ["GUID"] = "C8727A86",
            ["NextDialogue"] = 80070136,
            ["SpeakNpcId"] = 790013,
            ["TalkActionId"] = {
                [1] = "790014:Explain01_End",
                [2] = "790013:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/001/C8727A86",
            },
        [80070136] = {
            ["Content"] = "和维勒斯一样的蝇营狗苟之徒将活在噩梦中，每夜胆战心惊，怕自己的房门被敲响；暗地里观望的墙头草则又庆幸又后怕：还好自己尚未做出不法之行。",
            ["ContentFR"] = "Les parasites comme Willers vivront hantés par la peur, craignant qu’on frappe à leur porte la nuit. Ceux qui hésitent respireront un peu, heureux de ne pas avoir commis d’erreur.",
            ["DialogueId"] = 80070136,
            ["GUID"] = "C8727AB0",
            ["NextDialogue"] = 80070137,
            ["SpeakNpcId"] = 790013,
            ["TalkActionId"] = {
                [1] = "790013:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/001/C8727AB0",
            },
        [80070137] = {
            ["Content"] = "而那些忠诚的士兵则会因罪恶被诛灭，美德得到嘉奖，而愈加坚信陛下的公正。",
            ["ContentFR"] = "Les loyaux, par la purge des pécheurs et la louange des vertueux, verront leur foi en la justice de Sa Majesté plus profondément ancrée.",
            ["DialogueId"] = 80070137,
            ["GUID"] = "C8727ADA",
            ["NextDialogue"] = 80070138,
            ["SpeakNpcId"] = 790013,
            ["TalkActionId"] = {
                [1] = "790013:Explain01_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/001/C8727ADA",
            },
        [80070138] = {
            ["Camera"] = "-87.774124,-53.601727,54.482422,0.000029,17.19998,61.800571,35.000008,369.962646,false,Manual,9.880018",
            ["Content"] = "鞭子和糖果，永远是掌握人心最有效的手段。我们需要接受部分污渍的存在，适时松紧手中的缰绳。",
            ["ContentFR"] = "La carotte et le bâton, la règle d’or pour inspirer la loyauté. Il faut savoir tolérer quelques impuretés, et ajuster son emprise selon les circonstances.",
            ["DialogueId"] = 80070138,
            ["GUID"] = "C8727B04",
            ["NextDialogue"] = 80070139,
            ["SpeakNpcId"] = 790013,
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/001/C8727B04",
            },
        [80070139] = {
            ["Camera"] = "-108.692429,383.760162,74.947266,0.000001,8.799756,-69.593491,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "听不懂，但我感觉当上少校不是啥好事了。我还是去做点我能搞懂的事吧，比如把这份垃圾清单扔掉。",
            ["ContentFR"] = "Trop compliqué pour moi... Finalement, être major, c’est peut-être pas si génial. Autant me contenter de ce que je maîtrise, comme jeter cette liste à la poubelle.",
            ["DialogueId"] = 80070139,
            ["GUID"] = "C8727B2E",
            ["NextDialogue"] = 80070140,
            ["SpeakNpcId"] = 790014,
            ["TalkActionId"] = {
                [1] = "790014:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/001/C8727B2E",
            },
        [80070140] = {
            ["Camera"] = "-29.486694,-231.213272,139.712891,0.000004,-3.599571,79.597282,45.0,369.962646,false,Manual,9.880018",
            ["Content"] = "不用有太大压力，十三军团对敌人来说是宣告死亡的乌鸦，对内部的同伴来说，则是坚强的后盾，像兰迪那样的家伙，就能帮你思考和处理不少琐事。",
            ["ContentFR"] = "Ne te laisse pas submerger par la pression. La XIIIᵉ incarne la mort pour nos ennemis, mais elle est un pilier pour nos alliés. Prends Randy avec toi, il t’aidera à gérer les détails.",
            ["DialogueId"] = 80070140,
            ["GUID"] = "C8727B58",
            ["LookAt"] = {
                [1] = "790013:n(790014)",
                },
            ["NextDialogue"] = 80070141,
            ["SpeakNpcId"] = 790013,
            ["TalkActionId"] = {
                [1] = "790013:Disagree",
                },
            ["TurnTo"] = {
                [1] = "790013:n(790014)",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/001/C8727B58",
            },
        [80070141] = {
            ["Camera"] = "-27.108675,189.212509,103.496094,0.000003,3.399535,-80.992088,45.0,357.136719,false,Manual,9.443032",
            ["Content"] = "他？坑了我不止一次两次了。",
            ["ContentFR"] = "Lui ? Il m’a déjà roulée plusieurs fois.",
            ["DialogueId"] = 80070141,
            ["GUID"] = "C8727B82",
            ["NextDialogue"] = 80070142,
            ["SpeakNpcId"] = 790014,
            ["TalkActionId"] = {
                [1] = "790014:Sigh_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/001/C8727B82",
            },
        [80070142] = {
            ["Camera"] = "-29.486694,-231.213272,139.712891,0.000004,-3.599571,79.597282,45.0,369.962646,false,Manual,9.880018",
            ["Content"] = "让你掉进陷阱未尝不是一种教育，他是不会真害你的。十三军团虽然在所有军团中人数最少，但也最为锋利，你要学会融入其中，和每一个人相处。",
            ["ContentFR"] = "Tomber dans ses pièges est aussi une leçon. Il ne te fera jamais vraiment de mal. La XIIIᵉ est la plus petite, mais la plus affûtée des légions. Apprends à t’intégrer et à collaborer avec chacun.",
            ["DialogueId"] = 80070142,
            ["GUID"] = "C8727BAC",
            ["NextDialogue"] = 80070143,
            ["SpeakNpcId"] = 790013,
            ["TalkActionId"] = {
                [1] = "790014:Sigh_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/001/C8727BAC",
            },
        [80070143] = {
            ["Camera"] = "-27.108675,189.212509,103.496094,0.000003,3.399535,-80.992088,45.0,357.136719,false,Manual,9.443032",
            ["Content"] = "啧，我尽量。",
            ["ContentFR"] = "Hmm, je vais faire de mon mieux.",
            ["DialogueId"] = 80070143,
            ["GUID"] = "C8727BD6",
            ["SpeakNpcId"] = 790014,
            ["TalkActionId"] = {
                [1] = "790014:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/001/C8727BD6",
            },
        [80070201] = {
            ["Camera"] = "-178.038208,706.88324,245.560547,0.000045,-15.599693,-71.79892,25.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "军团长，走私清单处理掉了。现在还剩下一台坏掉的录音机和一张照片需要您确认一下。",
            ["ContentFR"] = "Commandante, les listes de marchandises de contrebande ont été traitées. Il ne reste qu’un magnétophone hors service et une vieille photo à valider.",
            ["DialogueId"] = 80070201,
            ["FinalCamera"] = "-192.709595,702.058655,245.560547,0.000045,-15.599693,-71.798897,25.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "C872855A",
            ["LookAt"] = {
                [1] = "790014:n(790013)",
                },
            ["NextDialogue"] = 80070202,
            ["Scripts"] = "MoveTo{ActorId{790014},MoveSpeed{75},TargetPoint{\"TargetPoint_430102\"}}",
            ["SpeakNpcId"] = 790014,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/002/C872855A",
            },
        [80070202] = {
            ["Content"] = "这台录音机开了以后就一直在那轰轰响，我都怀疑是不是折磨人的刑具了。",
            ["ContentFR"] = "Ce truc fait un boucan d’enfer dès qu’on l’allume... J’ai cru que c’était un instrument de torture.",
            ["DialogueId"] = 80070202,
            ["GUID"] = "C8728584",
            ["LookAt"] = {
                [1] = "790013:n(790014)",
                },
            ["NextDialogue"] = 80070203,
            ["SpeakNpcId"] = 790014,
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/002/C8728584",
            },
        [80070203] = {
            ["Camera"] = "-88.759552,-172.692947,120.162109,0.000021,-5.59915,67.009216,28.0,453.595306,false,Manual,8.167668",
            ["Content"] = "它啊，放这吧。虽然我还有很多类似的录音，但多它一个也无妨。",
            ["ContentFR"] = "Celui-là ? Pose-le là. J’ai toute une collection d’enregistrements similaires. Un de plus ne changera pas grand-chose.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 80070203,
            ["GUID"] = "C87285AE",
            ["NextDialogue"] = 80070204,
            ["SpeakNpcId"] = 790013,
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/002/C87285AE",
            },
        [80070204] = {
            ["Content"] = "至于那录音的内容，你不知道也很正常，毕竟都是十几年前那个型号的飞艇引擎声了。",
            ["ContentFR"] = "Et pour le contenu... rien d’étonnant que tu ne reconnaisses pas ce bruit. C’est un vieux moteur de dirigeable, un modèle d’il y a une dizaine d’années.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 80070204,
            ["GUID"] = "C87285D8",
            ["NextDialogue"] = 80070205,
            ["SpeakNpcId"] = 790013,
            ["TalkActionId"] = {
                [1] = "790013:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/002/C87285D8",
            },
        [80070205] = {
            ["Content"] = "现在的帝国飞艇更注重稳定和续航，不像是那场战争的时候，只看重速度和载弹量。",
            ["ContentFR"] = "Aujourd’hui, l’Empire privilégie la stabilité et l’endurance. À l’époque de cette guerre, seule comptait la vitesse, et la capacité d’emport.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 80070205,
            ["GUID"] = "C8728602",
            ["NextDialogue"] = 80070206,
            ["SpeakNpcId"] = 790013,
            ["TurnTo"] = {
                [1] = "790013:n(790014)",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/002/C8728602",
            },
        [80070206] = {
            ["Camera"] = "-63.979523,366.17868,112.912109,0.000001,-2.799961,-78.5989,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "是说二十来年前对传颂会的“‘神之挽歌’攻势”吧。那场战役中十三军团乘着试作型飞艇直捣传颂会的高塔，这些事迹连路边的小孩都会唱两句。",
            ["ContentFR"] = "Vous parlez de l’offensive de l’Élégie Divine contre l’Église Élyséenne, il y a vingt ans ? La XIIIᵉ a foncé sur leur tour dans des dirigeables prototypes. Même les gamins dans la rue en fredonnent les exploits.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 80070206,
            ["GUID"] = "C872862C",
            ["NextDialogue"] = 80070207,
            ["Scripts"] = "SEQ{PlayAnimation{ActorId{790014},AnimationId{\"Explain02_Start\"},Duration{3}},PlayAnimation{ActorId{790014},AnimationId{\"Explain02_End\"},Duration{1}}}",
            ["SpeakNpcId"] = 790014,
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/002/C872862C",
            },
        [80070207] = {
            ["Content"] = "您也是因为那场战役中的功勋，成为帝国最年轻的军团长。",
            ["ContentFR"] = "Et c’est grâce à cette bataille que vous êtes devenue la plus jeune commandante de la Légion de l’histoire de l’Empire.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 80070207,
            ["GUID"] = "C8728656",
            ["NextDialogue"] = 80070208,
            ["SpeakNpcId"] = 790014,
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/002/C8728656",
            },
        [80070208] = {
            ["Camera"] = "-88.759552,-172.692947,120.162109,0.000021,-5.59915,67.009216,28.0,453.595306,false,Manual,8.167668",
            ["Content"] = "……从结果来看，十三军团绕过猛烈交火的边境线，奇袭无人踏足的高塔，首次打到“神”的面前，确实值得传唱。",
            ["ContentFR"] = "... Sur le papier, c’est vrai. La XIIIᵉ a contourné les lignes de front, attaqué une tour jamais approchée, et pour la première fois, affronté les \"dieux\" de près. Digne d’être chanté, oui.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 80070208,
            ["GUID"] = "C8728680",
            ["NextDialogue"] = 80070209,
            ["Scripts"] = "SEQ{PlayAnimation{ActorId{790013},AnimationId{\"Think_Start\"},Duration{2}},PlayAnimation{ActorId{790013},AnimationId{\"Think_End\"},Duration{1}},PlayAnimation{ActorId{790013},AnimationId{\"Agree\"},Duration{1}}}",
            ["SpeakNpcId"] = 790013,
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/002/C8728680",
            },
        [80070209] = {
            ["Content"] = "但对十三军团——或者说，对我而言，比起荣耀，那场战役更多意味着……愤怒与耻辱。",
            ["ContentFR"] = "Mais pour la XIIIᵉ Légion, pour moi, cette bataille n’a laissé que colère et honte.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 80070209,
            ["GUID"] = "C87286AA",
            ["NextDialogue"] = 80070210,
            ["SpeakNpcId"] = 790013,
            ["TalkActionId"] = {
                [1] = "790013:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/002/C87286AA",
            },
        [80070210] = {
            ["Content"] = "进入高塔的十二人最终无人生还。我若不是在塔外的飞艇里留守，恐怕如今也只是阵亡名单上的一个数字。",
            ["ContentFR"] = "Les douze officiers envoyés dans la tour sont tous morts. Si je n’étais pas restée en retrait sur le dirigeable, mon nom ne serait plus qu’un chiffre sur la liste des morts.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 80070210,
            ["GUID"] = "C87286D4",
            ["NextDialogue"] = 80070211,
            ["SpeakNpcId"] = 790013,
            ["TalkActionId"] = {
                [1] = "790013:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/002/C87286D4",
            },
        [80070211] = {
            ["Camera"] = "-63.415112,74.612396,161.78125,0.000025,-23.199345,52.011242,35.000008,453.595306,false,DoNotOverride,8.167668",
            ["Content"] = "辉煌之下，是惨败。",
            ["ContentFR"] = "Derrière la gloire, une défaite cuisante.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 80070211,
            ["GUID"] = "C87286FE",
            ["NextDialogue"] = 80070212,
            ["SpeakNpcId"] = 790013,
            ["TalkActionId"] = {
                [1] = "790013:Explain01_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/002/C87286FE",
            },
        [80070212] = {
            ["Content"] = "我最后的能想起来的便是，我驾驶那架失控的飞艇，在满天的炮火和魔弹中飞越边境线。",
            ["ContentFR"] = "Mon dernier souvenir de cette bataille est de piloter un dirigeable hors de contrôle, fendant un ciel en flammes sous un feu croisé de canons et de projectiles magiques.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 80070212,
            ["GUID"] = "C8728728",
            ["NextDialogue"] = 80070213,
            ["SpeakNpcId"] = 790013,
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/002/C8728728",
            },
        [80070213] = {
            ["Content"] = "这份录音，能带我回到那架失控的飞艇之中，回到那一刻。回想起鼻子里的血腥味儿，和耳边引擎疲惫的轰鸣。",
            ["ContentFR"] = "Cet enregistrement me ramène là-bas, au cœur du vacarme du moteur, à l’odeur du sang dans mes narines.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 80070213,
            ["GUID"] = "C8728752",
            ["NextDialogue"] = 80070214,
            ["SpeakNpcId"] = 790013,
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/002/C8728752",
            },
        [80070214] = {
            ["Camera"] = "-63.979523,366.17868,112.912109,0.000001,-2.799961,-78.5989,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "军团长这么一说我想起来，您每次坐飞艇确实都会坐在靠引擎的位置上。",
            ["ContentFR"] = "Maintenant que vous le dites, vous vous asseyez toujours près du moteur quand on vole...",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 80070214,
            ["GUID"] = "C872877C",
            ["NextDialogue"] = 80070215,
            ["SpeakNpcId"] = 790014,
            ["TalkActionId"] = {
                [1] = "790014:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/002/C872877C",
            },
        [80070215] = {
            ["Camera"] = "-1015.568604,-969.672852,166.992188,0.0,-4.99948,47.392773,35.000008,100000.0,false,Manual,2.8",
            ["Content"] = "战争就是这样，它会改变所有人。",
            ["ContentFR"] = "La guerre change tout. Et tout le monde.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 80070215,
            ["FinalCamera"] = "-985.23938,-936.698364,163.091797,0.0,-4.99948,47.392773,35.000008,100000.0,false,Manual,2.8",
            ["GUID"] = "C87287A6",
            ["NextDialogue"] = 80070216,
            ["SpeakNpcId"] = 790013,
            ["TalkActionId"] = {
                [1] = "790013:Talk03_Start",
                },
            ["ToFinalCameraBlendTime"] = 20,
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/002/C87287A6",
            },
        [80070216] = {
            ["Content"] = "我在医院见过很多士兵，即使在远离战争的后方，他们仍然被战争所折磨。甚至只是一门庆典的礼炮，或者一把孩童的玩具手枪都会令他们突然崩溃。",
            ["ContentFR"] = "J’ai vu tant de soldats brisés, même loin du front, dans les hôpitaux, toujours hantés par la guerre. Parfois, un simple coup de canon lors d’une fête, ou le claquement d’un jouet, suffit à les faire s’effondrer.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 80070216,
            ["GUID"] = "C87287D0",
            ["NextDialogue"] = 80070217,
            ["Scripts"] = "SEQ{PlayAnimation{ActorId{790013},AnimationId{\"Talk03_End\"},Duration{1}},PlayAnimation{ActorId{790013},AnimationId{\"Explain02_Start\"},Duration{1}}}",
            ["SpeakNpcId"] = 790013,
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/002/C87287D0",
            },
        [80070217] = {
            ["Content"] = "即使是那些心智坚强的人，战争依旧给了他们无法抹去的习惯。比如驻扎在边境线的第十一军团长，睡觉时也会睁着一只眼。",
            ["ContentFR"] = "Même les plus solides gardent des séquelles. Par exemple, le commandant de la XIᵉ Légion, stationnée à la frontière, dort toujours un œil ouvert.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 80070217,
            ["GUID"] = "C87287FA",
            ["NextDialogue"] = 80070218,
            ["Scripts"] = "SEQ{PlayAnimation{ActorId{790013},AnimationId{\"Explain02_End\"},Duration{1}},PlayAnimation{ActorId{790013},AnimationId{\"Explain01_Start\"},Duration{1}}}",
            ["SpeakNpcId"] = 790013,
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/002/C87287FA",
            },
        [80070218] = {
            ["Camera"] = "-63.415112,74.612396,161.78125,0.000025,-23.199345,52.011242,35.000008,453.595306,false,DoNotOverride,8.167668",
            ["Content"] = "那时候他们十一军团得在边境线上牵制艾利西安八成的主力部队，压力和伤亡，都不比我们十三军团小。",
            ["ContentFR"] = "Ils ont dû retenir la plus grande partie des troupes élyséennes à la frontière. Leur pression et leurs pertes étaient comparables aux nôtres.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 80070218,
            ["GUID"] = "C8728824",
            ["NextDialogue"] = 80070219,
            ["SpeakNpcId"] = 790013,
            ["TalkActionId"] = {
                [1] = "790013:Explain01_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/002/C8728824",
            },
        [80070219] = {
            ["Camera"] = "-9.893036,212.023102,120.853516,0.000003,-4.000004,-89.204086,45.0,100000.0,false,Manual,16.970627",
            ["Content"] = "您翻来覆去听这个，是为同僚的死内疚吗？",
            ["ContentFR"] = "Vous réécoutez cet enregistrement encore et encore... par culpabilité envers ceux qui sont tombés ?",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 80070219,
            ["GUID"] = "C872884E",
            ["NextDialogue"] = 80070220,
            ["SpeakNpcId"] = 790014,
            ["TalkActionId"] = {
                [1] = "790014:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/002/C872884E",
            },
        [80070220] = {
            ["Camera"] = "-88.759552,-172.692947,120.162109,0.000021,-5.59915,67.009216,28.0,453.595306,false,Manual,8.167668",
            ["Content"] = "不，只是提神罢了。困倦的时候，靠这个让自己集中注意力。",
            ["ContentFR"] = "Non. Pour rester éveillée. Quand je fatigue, ça m’aide à me concentrer.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 80070220,
            ["GUID"] = "C8728878",
            ["NextDialogue"] = 80070221,
            ["SpeakNpcId"] = 790013,
            ["TalkActionId"] = {
                [1] = "790014:Explain02_End",
                [2] = "790013:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/002/C8728878",
            },
        [80070221] = {
            ["Content"] = "很多人会悔恨于过去的失败，感叹自己的无力，一味地陷于内疚的淤泥中，将失败视之为一种折磨——这是弱者天生的权利。",
            ["ContentFR"] = "Beaucoup se complaisent dans la culpabilité. Ils ressassent leurs échecs, s’apitoient sur leur impuissance. C’est un réflexe... et un luxe de faible.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 80070221,
            ["GUID"] = "C87288A2",
            ["NextDialogue"] = 80070222,
            ["SpeakNpcId"] = 790013,
            ["TalkActionId"] = {
                [1] = "790013:Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/002/C87288A2",
            },
        [80070222] = {
            ["Camera"] = "-52.902649,28.740311,59.359375,0.000018,21.000099,65.212578,35.000008,158.228317,false,Manual,8.167668",
            ["Content"] = "但在我眼中，失败是旧日的鞭痕，它予我痛苦的清醒，提醒我活下去，在痛楚与耻辱中攀向胜利的高点。",
            ["ContentFR"] = "Pour moi, l’échec est une cicatrice. Elle me fait mal, mais elle me garde lucide. Elle me pousse à avancer, à grimper, à transformer honte et douleur en victoire.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 80070222,
            ["GUID"] = "C87288CC",
            ["NextDialogue"] = 80070223,
            ["SpeakNpcId"] = 790013,
            ["TalkActionId"] = {
                [1] = "790013:Talk03_End",
                [2] = "790014:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/002/C87288CC",
            },
        [80070223] = {
            ["Content"] = "我珍惜战友的牺牲，因此才不会允许自己像他们一样跌落悬崖。在最终的胜利前驻足喘息、缅怀死者，更是在浪费他们牺牲时的觉悟。",
            ["ContentFR"] = "J’honore mes camarades tombés. Et justement pour cela, je ne m’autorise pas à chuter. S’arrêter pour pleurer les morts avant la victoire, c’est trahir leur sacrifice.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 80070223,
            ["GUID"] = "C87288F6",
            ["NextDialogue"] = 80070224,
            ["SpeakNpcId"] = 790013,
            ["TalkActionId"] = {
                [1] = "790014:Think_End",
                [2] = "790013:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/002/C87288F6",
            },
        [80070224] = {
            ["Camera"] = "-63.979523,366.17868,112.912109,0.000001,-2.799961,-78.5989,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "很多人斥责我冷血，更有人搬出我卑微的出身，说残忍是卡戎之民的天性。",
            ["ContentFR"] = "Beaucoup me disent insensible, inhumaine. D’autres invoquent mes origines modestes, prétendant que la cruauté coule dans le sang des Charon.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 80070224,
            ["GUID"] = "C8728920",
            ["NextDialogue"] = 80070225,
            ["SpeakNpcId"] = 790013,
            ["TalkActionId"] = {
                [1] = "790013:Explain01_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/002/C8728920",
            },
        [80070225] = {
            ["Content"] = "但最后他们连失败的过程、战死者的姓名都已忘记，只是如同虫子般不停地叫着，然后逐一消失在我向上攀登的过程中。",
            ["ContentFR"] = "Mais eux, ils oublient jusqu’aux noms des morts. Ils bavardent comme des insectes avant de s’effacer, un à un, pendant que je poursuis mon ascension.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 80070225,
            ["GUID"] = "C872894A",
            ["NextDialogue"] = 80070226,
            ["SpeakNpcId"] = 790013,
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/002/C872894A",
            },
        [80070226] = {
            ["Camera"] = "-56.278519,-30.622166,132.205078,0.000009,-9.000037,-85.60675,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "最终留下的，只有铭记着耻辱与失败，不断向上的我。",
            ["ContentFR"] = "Et à la fin, il ne restera que moi, marquée par l’échec, mais toujours plus haut.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 80070226,
            ["GUID"] = "C8728974",
            ["NextDialogue"] = 80070227,
            ["SpeakNpcId"] = 790013,
            ["TalkActionId"] = {
                [1] = "790013:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/002/C8728974",
            },
        [80070227] = {
            ["Content"] = "在我看来，军团长已经站得足够高了，许多人努力一辈子也无法获得您现在的地位……",
            ["ContentFR"] = "À mes yeux, vous êtes déjà bien au-dessus de ce que la plupart atteindront un jour...",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 80070227,
            ["GUID"] = "C872899E",
            ["NextDialogue"] = 80070228,
            ["SpeakNpcId"] = 790014,
            ["TalkActionId"] = {
                [1] = "790014:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/002/C872899E",
            },
        [80070228] = {
            ["Camera"] = "-52.902649,28.740311,59.359375,0.000018,21.000099,65.212578,35.000008,158.228317,false,Manual,8.167668",
            ["Content"] = "不，还不够。十三军团还肩负着世人尚不知晓的，“真正的理想”。",
            ["ContentFR"] = "Pas assez. La XIIIᵉ Légion porte un idéal que le monde ignore encore.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 80070228,
            ["GUID"] = "C87289C8",
            ["NextDialogue"] = 80070229,
            ["SpeakNpcId"] = 790013,
            ["TalkActionId"] = {
                [1] = "790014:Explain02_End",
                [2] = "790013:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/002/C87289C8",
            },
        [80070229] = {
            ["Camera"] = "-1154.983398,-1628.61377,1072.589844,0.000071,-26.199942,47.398281,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "而很多躺在家族纹章上的蠹虫们生来便在高处，手握权力，却醉死在名声与荣誉之中，只看脚下，甚至谋算着如何把那些肩负着真正理想的人击落悬崖。",
            ["ContentFR"] = "Pendant que des larves nées avec des armoiries s’enivrent de leur pouvoir, nous, nous portons le vrai combat. Et eux, tout là-haut, ne rêvent que d’abattre ceux qui s’élèvent pour de bon.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 80070229,
            ["FinalCamera"] = "-1186.510742,-1599.621582,1072.589844,0.000071,-26.199942,47.398281,35.000008,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "C87289F2",
            ["NextDialogue"] = 80070230,
            ["SpeakNpcId"] = 790013,
            ["TalkActionId"] = {
                [1] = "790013:Talk03_Start",
                },
            ["ToFinalCameraBlendTime"] = 15,
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/002/C87289F2",
            },
        [80070230] = {
            ["Content"] = "骑不上马，不知步兵操典为何物却忝居高位的公爵伯爵们，都不应该存在于这个国家。",
            ["ContentFR"] = "Ces nobles incapables de monter à cheval ou de lire un manuel tactique... Ils n’ont rien à faire dans ce pays.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 80070230,
            ["GUID"] = "C8728A1C",
            ["NextDialogue"] = 80070231,
            ["Scripts"] = "SEQ{PlayAnimation{ActorId{790013},AnimationId{\"Talk03_End\"},Duration{1}},PlayAnimation{ActorId{790013},AnimationId{\"Explain01_Start\"},Duration{1}}}",
            ["SpeakNpcId"] = 790013,
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/002/C8728A1C",
            },
        [80070231] = {
            ["Camera"] = "-52.902649,28.740311,59.359375,0.000018,21.000099,65.212578,35.000008,158.228317,false,Manual,8.167668",
            ["Content"] = "而我决不能如他们一般止步于此，我必须站到更高的地方，得到万人之上的权力。",
            ["ContentFR"] = "Je ne peux pas m’arrêter ici. Je dois aller plus haut. Gagner un pouvoir qui domine tout.",
            ["DialogueId"] = 80070231,
            ["GUID"] = "C8728A46",
            ["LookAt"] = {
                [1] = "790013:n(790013)",
                },
            ["NextDialogue"] = 80070232,
            ["SpeakNpcId"] = 790013,
            ["TalkActionId"] = {
                [1] = "790013:Explain01_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/002/C8728A46",
            },
        [80070232] = {
            ["Camera"] = "-83.885132,575.331421,43.728516,0.0,8.799899,-79.398201,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "届时我们将带领海伯利亚帝国……不，整个人类，走向新的未来。你明白吗，琳恩？",
            ["ContentFR"] = "Ce jour-là, nous mènerons l’Empire Hyperboréen... non, toute l’humanité, vers un nouvel avenir. Tu comprends, Lynn ?",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 80070232,
            ["FinalCamera"] = "-90.078613,608.423706,38.511719,0.0,8.799899,-79.398201,35.000008,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "C8728A70",
            ["NextDialogue"] = 80070233,
            ["Scripts"] = "SEQ{MoveTo{ActorId{790013},MoveSpeed{75},TargetPoint{\"TargetPoint_43010201\"}},LookAt{_delay{2},LookAtDescription{\"790013:n(790014)\"}}}",
            ["SpeakNpcId"] = 790013,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/002/C8728A70",
            },
        [80070233] = {
            ["Content"] = "……老实说，我没完全听懂。您知道的，我来这里就是为了混口饭吃，没得选。",
            ["ContentFR"] = "... Pour être honnête, pas tout. Vous savez, je suis ici pour survivre, j’ai pas vraiment eu le choix.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 80070233,
            ["GUID"] = "C8728A9A",
            ["NextDialogue"] = 80070234,
            ["SpeakNpcId"] = 790014,
            ["TalkActionId"] = {
                [1] = "790014:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/002/C8728A9A",
            },
        [80070234] = {
            ["Camera"] = "-85.702591,-181.152481,118.537109,0.000021,-1.599391,69.810509,45.0,453.595306,false,Manual,8.167668",
            ["Content"] = "但听您的意思是，大的快来了呗。到时候，我肯定会为了保护好家人好好战斗的，也没得选。",
            ["ContentFR"] = "Mais si ce que vous dites, c’est que le monde va basculer... alors je me battrai, de toutes mes forces. Pour protéger les miens. Pas vraiment le choix non plus.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 80070234,
            ["GUID"] = "C8728AC4",
            ["NextDialogue"] = 80070235,
            ["SpeakNpcId"] = 790014,
            ["TalkActionId"] = {
                [1] = "790014:Confident_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/002/C8728AC4",
            },
        [80070235] = {
            ["Camera"] = "-17.806854,326.852264,116.085938,0.000009,2.799769,-82.405029,45.0,80.247894,false,DoNotOverride,16.970627",
            ["Content"] = "我欣赏你的坦诚，琳恩。虽然很微小，但你也有愿意不断为之攀登的目标，这便足够了。",
            ["ContentFR"] = "J’apprécie ta franchise, Lynn. Tu es peut-être modeste, mais tu grimpes aussi vers quelque chose qui compte. C’est tout ce qui importe.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 80070235,
            ["GUID"] = "C8728AEE",
            ["Scripts"] = "LookAt{_delay{2},LookAtDescription{\"790013:n(790013)\"}}",
            ["SpeakNpcId"] = 790013,
            ["TalkActionId"] = {
                [1] = "790013:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/002/C8728AEE",
            },
        [80070301] = {
            ["Camera"] = "1179.431641,-1065.483887,93.511719,0.000004,-0.200466,138.797653,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "录音机我收好了，照片的话……是我老师以及我那天真的同门那张吧。",
            ["ContentFR"] = "J’ai rangé le magnétophone. Pour la photo... c’est celle de mon professeur et de cette élève naïve, ma camarade à l’époque.",
            ["DialogueId"] = 80070301,
            ["FinalCamera"] = "1156.185791,-1092.036255,93.511719,0.000004,-0.200466,138.797653,35.000008,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "C87295C2",
            ["NextDialogue"] = 80070302,
            ["Scripts"] = "PlayOrStopBGM{PlayType{\"Play\"},SoundPriority{\"Invite\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/mute\"}}",
            ["SpeakNpcId"] = 790013,
            ["TalkActionId"] = {
                [1] = "790013:Explain01_Start",
                },
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/003/C87295C2",
            },
        [80070302] = {
            ["Camera"] = "32.871628,241.033554,128.292969,0.000024,-4.399693,-100.193977,45.000011,419.787506,false,Manual,10.901892",
            ["Content"] = "军团长怎么逮着谁都说天真。",
            ["ContentFR"] = "Pourquoi vous appelez tout le monde \"naïf\", commandante ?",
            ["DialogueId"] = 80070302,
            ["GUID"] = "C87295EC",
            ["NextDialogue"] = 80070303,
            ["SpeakNpcId"] = 790014,
            ["TalkActionId"] = {
                [1] = "790013:Explain01_End",
                [2] = "790014:Sigh_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/003/C87295EC",
            },
        [80070303] = {
            ["Content"] = "哈……是的，我也对你说过类似的话，但她和你不是同一种天真。她是老师的另一个学生，一个心思澄澈的人。",
            ["ContentFR"] = "Ah... oui, je t’ai déjà dit ça. Mais sa naïveté n’était pas la même que la tienne. Elle était une autre élève de mon professeur, une personne au cœur pur.",
            ["DialogueId"] = 80070303,
            ["GUID"] = "C8729616",
            ["NextDialogue"] = 80070304,
            ["SpeakNpcId"] = 790013,
            ["TalkActionId"] = {
                [1] = "790014:Sigh_End",
                [2] = "790013:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/003/C8729616",
            },
        [80070304] = {
            ["Camera"] = "26.439392,-248.712524,118.015625,0.000024,-2.799531,101.20755,45.000011,384.833771,false,Manual,10.901892",
            ["Content"] = "明明在炼金院那种地方，却对炼金技术抱着不切实际的幻想，甚至第一次见我的时候向我和老师确认：“炼金术会让大家过得更好吧？”",
            ["ContentFR"] = "Alors qu’elle était dans les Spathatoi, elle nourrissait des rêves irréalistes sur l’alchimie. La première fois que je l’ai vue, elle nous a demandé, à moi et à notre professeur : « L’alchimie, ça rendra la vie meilleure pour tous, n’est-ce pas ? »",
            ["DialogueId"] = 80070304,
            ["GUID"] = "C8729640",
            ["NextDialogue"] = 80070305,
            ["Scripts"] = "PlayOrStopBGM{PlayType{\"Play\"},SoundPriority{\"Invite\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt02/0067_story_daphnis_theme_piano\"}}",
            ["SpeakNpcId"] = 790013,
            ["TalkActionId"] = {
                [1] = "790013:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/003/C8729640",
            },
        [80070305] = {
            ["Content"] = "你觉得呢？",
            ["ContentFR"] = "Et toi, qu’en penses-tu, Lynn ?",
            ["DialogueId"] = 80070305,
            ["GUID"] = "C872966A",
            ["NextDialogue"] = 80070306,
            ["SpeakNpcId"] = 790013,
            ["TalkActionId"] = {
                [1] = "790013:Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/003/C872966A",
            },
        [80070306] = {
            ["Camera"] = "32.871628,241.033554,128.292969,0.000024,-4.399693,-100.193977,45.000011,419.787506,false,Manual,10.901892",
            ["Content"] = "很高级的玩意，没用过。",
            ["ContentFR"] = "C’est une technologie avancée, mais je ne l’ai jamais vraiment utilisée.",
            ["DialogueId"] = 80070306,
            ["GUID"] = "C8729694",
            ["NextDialogue"] = 80070307,
            ["SpeakNpcId"] = 790014,
            ["TalkActionId"] = {
                [1] = "790014:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/003/C8729694",
            },
        [80070307] = {
            ["Camera"] = "26.439392,-248.712524,118.015625,0.000024,-2.799531,101.20755,45.000011,384.833771,false,Manual,10.901892",
            ["Content"] = "呵呵，前人早已把炼金技术打磨成帝国生活的基石。你一直在用，只是没注意到而已。",
            ["ContentFR"] = "Haha, nos ancêtres ont fait de l’alchimie la pierre angulaire de la vie dans l’Empire. Tu l’utilises depuis toujours, sans même t’en rendre compte.",
            ["DialogueId"] = 80070307,
            ["GUID"] = "C87296BE",
            ["NextDialogue"] = 80070308,
            ["SpeakNpcId"] = 790013,
            ["TalkActionId"] = {
                [1] = "790013:Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/003/C87296BE",
            },
        [80070308] = {
            ["Camera"] = "24.780663,-23.754013,119.826172,0.000024,-1.399649,-100.595001,45.0,100000.0,false,DoNotOverride,10.901892",
            ["Content"] = "比如你用的子弹与枪械，都是炼金技术的产物之一。",
            ["ContentFR"] = "Par exemple, tes balles et tes armes à feu sont des créations issues de l’alchimie.",
            ["DialogueId"] = 80070308,
            ["GUID"] = "C87296E8",
            ["NextDialogue"] = 80070309,
            ["SpeakNpcId"] = 790013,
            ["TalkActionId"] = {
                [1] = "790013:Talk02_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/003/C87296E8",
            },
        [80070309] = {
            ["Content"] = "这样啊，枪械是我吃饭的家伙，离了它们还挺麻烦的，那研究炼金术的人，一定都是了不起的学者吧。",
            ["ContentFR"] = "Ah oui ? Bah, mes armes, c’est ce qui me nourrit. Sans elles, je serais bien embêtée. Ceux qui étudient l’alchimie doivent être des chercheurs incroyables.",
            ["DialogueId"] = 80070309,
            ["GUID"] = "C8729712",
            ["NextDialogue"] = 80070310,
            ["Scripts"] = "SEQ{PlayAnimation{ActorId{790014},AnimationId{\"Think_Start\"},Duration{2}},PlayAnimation{ActorId{790014},AnimationId{\"Think_End\"},Duration{1}}}",
            ["SpeakNpcId"] = 790014,
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/003/C8729712",
            },
        [80070310] = {
            ["Camera"] = "26.439392,-248.712524,118.015625,0.000024,-2.799531,101.20755,45.000011,384.833771,false,Manual,10.901892",
            ["Content"] = "嗯，大部分帝国人和你是一样的看法，炼金术师们也许很古怪，但他们发明的事物都在渐渐改变这个国家。",
            ["ContentFR"] = "C’est vrai. La plupart ici partagent ton avis : les alchimistes sont un peu étranges, mais leurs inventions changent peu à peu notre pays.",
            ["DialogueId"] = 80070310,
            ["GUID"] = "C872973C",
            ["NextDialogue"] = 80070311,
            ["SpeakNpcId"] = 790013,
            ["TalkActionId"] = {
                [1] = "790013:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/003/C872973C",
            },
        [80070311] = {
            ["Content"] = "老师也教导我，炼金技术是改变帝国未来的伟大学识，同门仍告诉我，炼金技术是带来和平的希望之钥。",
            ["ContentFR"] = "Mon professeur me répétait que l’alchimie est une science profonde, capable de changer l’avenir de l’Empire. Ma camarade, elle, voyait en elle la clé de la paix et de l’espoir.",
            ["DialogueId"] = 80070311,
            ["GUID"] = "C8729766",
            ["NextDialogue"] = 80070312,
            ["SpeakNpcId"] = 790013,
            ["TalkActionId"] = {
                [1] = "790013:Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/003/C8729766",
            },
        [80070312] = {
            ["Camera"] = "-0.956041,3.409428,92.585938,0.000023,10.400335,91.608727,45.0,100000.0,false,DoNotOverride,10.901892",
            ["Content"] = "但对我来说，炼金技术是更实际的东西——攀登权力的阶梯。",
            ["ContentFR"] = "Pour moi, c’est plus pragmatique, un outil pour gravir les échelons du pouvoir.",
            ["DialogueId"] = 80070312,
            ["GUID"] = "C8729790",
            ["NextDialogue"] = 80070313,
            ["SpeakNpcId"] = 790013,
            ["TalkActionId"] = {
                [1] = "790013:Talk01_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/003/C8729790",
            },
        [80070313] = {
            ["Content"] = "正是这份技术让我被皇帝看中，加以忠诚与能力，让我成为了参与“‘神之挽歌’攻势”的军官之一。",
            ["ContentFR"] = "C’est grâce à cette maîtrise que l’Empereur m’a remarquée, reconnaissant ma loyauté et mes compétences, et que j’ai pu devenir officier dans l’offensive de l’Élégie Divine.",
            ["DialogueId"] = 80070313,
            ["GUID"] = "C87297BA",
            ["NextDialogue"] = 80070314,
            ["SpeakNpcId"] = 790013,
            ["TalkActionId"] = {
                [1] = "790013:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/003/C87297BA",
            },
        [80070314] = {
            ["Content"] = "我在炼金院时，全学科都是满分，但是不会把精力投入到任何研究中，高深而纯粹的理论知识也与我无关。",
            ["ContentFR"] = "À l’Académie, j’avais les meilleures notes dans toutes les matières, mais je ne m’investissais jamais vraiment dans la recherche. La théorie pure et complexe ne m’intéressait pas.",
            ["DialogueId"] = 80070314,
            ["GUID"] = "C87297E4",
            ["NextDialogue"] = 80070315,
            ["SpeakNpcId"] = 790013,
            ["TalkActionId"] = {
                [1] = "790013:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/003/C87297E4",
            },
        [80070315] = {
            ["Content"] = "这样的作为令老师愤怒，甚至气到在毕业典礼上说我永远无法掌握真正的知识。但从古至今，参透真正的知识与真理之人又有多少呢。",
            ["ContentFR"] = "Ça mettait mon professeur en colère. Lors de la cérémonie de fin d’études, elle a dit que je ne comprendrais jamais la vraie connaissance. Mais dis-moi, combien ont vraiment percé le secret du savoir à travers l’Histoire ?",
            ["DialogueId"] = 80070315,
            ["GUID"] = "C872980E",
            ["NextDialogue"] = 80070316,
            ["Scripts"] = "SEQ{PlayAnimation{ActorId{790013},AnimationId{\"Explain01_End\"},Duration{1}},PlayAnimation{ActorId{790013},AnimationId{\"Disagree\"},Duration{1}}}",
            ["SpeakNpcId"] = 790013,
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/003/C872980E",
            },
        [80070316] = {
            ["Camera"] = "68.550446,-309.161438,92.363281,0.000028,-0.200043,106.210724,45.000011,450.975708,false,Manual,5.23506",
            ["Content"] = "他们如今，又都在哪儿呢？",
            ["ContentFR"] = "Et aujourd’hui, où sont-ils ?",
            ["DialogueId"] = 80070316,
            ["GUID"] = "C8729838",
            ["NextDialogue"] = 80070317,
            ["Scripts"] = "TurnTo{TurnToDescription{\"790013:p(180)\"}}",
            ["SpeakNpcId"] = 790013,
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/003/C8729838",
            },
        [80070317] = {
            ["Content"] = "过去这么久，如果她再问我一次这个问题，我的答案也不会有所改变，只可惜，再也没有这样的机会了。",
            ["ContentFR"] = "Après tout ce temps, si elle me reposait la question, ma réponse serait la même. Dommage que je n’en aurai plus jamais l’occasion.",
            ["DialogueId"] = 80070317,
            ["GUID"] = "C8729862",
            ["NextDialogue"] = 80070318,
            ["Scripts"] = "PlayAnimation{_delay{2},ActorId{790013},AnimationId{\"Disagree\"},Duration{1}}",
            ["SpeakNpcId"] = 790013,
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/003/C8729862",
            },
        [80070318] = {
            ["Camera"] = "42.315338,214.12384,94.9375,-0.0,-0.600128,-103.201942,35.000015,384.64978,false,Manual,7.401211",
            ["Content"] = "哦，我好像听兰迪说过，首席炼金术师死掉有些年头了，和那个同门的关系也有点……复杂。",
            ["ContentFR"] = "Oh, j’ai entendu Randy dire que la Première Alchimiste est décédée, et que sa relation avec cette camarade était... compliquée.",
            ["DialogueId"] = 80070318,
            ["GUID"] = "C872988C",
            ["NextDialogue"] = 80070319,
            ["SpeakNpcId"] = 790014,
            ["TalkActionId"] = {
                [1] = "790014:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/003/C872988C",
            },
        [80070319] = {
            ["Content"] = "是啊，可悲的是老师到死都没等到那最喜爱的学生，也就是我那同门。来的只有我和病房外几只不祥的乌鸦而已。",
            ["ContentFR"] = "Oui. Tristement, même à sa mort, la préférée du professeur, cette camarade, n’est jamais venue. J’étais la seule, avec quelques corbeaux sinistres autour de la chambre d’hôpital.",
            ["DialogueId"] = 80070319,
            ["GUID"] = "C87298B6",
            ["NextDialogue"] = 80070320,
            ["SpeakNpcId"] = 790013,
            ["TalkActionId"] = {
                [1] = "790013:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/003/C87298B6",
            },
        [80070320] = {
            ["Content"] = "更可悲的是，老师最后也没解开象征真理的公式，伟大的研究化为无法解读与理解的废纸。",
            ["ContentFR"] = "Encore plus triste, c’est que le professeur n’a jamais percé la formule symbolisant la vérité. Son travail monumental est devenu un gribouillis indéchiffrable.",
            ["DialogueId"] = 80070320,
            ["GUID"] = "C87298E0",
            ["NextDialogue"] = 80070321,
            ["SpeakNpcId"] = 790013,
            ["TalkActionId"] = {
                [1] = "790013:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/003/C87298E0",
            },
        [80070321] = {
            ["Camera"] = "149.89209,-233.861969,6.462891,0.000063,12.797854,113.801712,35.000008,100000.0,false,DoNotOverride,7.401211",
            ["Content"] = "老师将理想与抱负托付给了我那同门，自己先倒在了追逐真理的路上，而我那同门呢？",
            ["ContentFR"] = "Elle a confié ses idéaux et ses rêves à cette camarade, mais elle est tombée en chemin, à la poursuite de la vérité. Et cette camarade, que fait-elle ?",
            ["DialogueId"] = 80070321,
            ["FinalCamera"] = "132.743332,-194.975647,16.105469,0.000063,12.797854,113.801628,35.000011,100000.0,false,DoNotOverride,7.401211",
            ["GUID"] = "C872990A",
            ["NextDialogue"] = 80070322,
            ["SpeakNpcId"] = 790013,
            ["TalkActionId"] = {
                [1] = "790013:Explain02_Start",
                },
            ["ToFinalCameraBlendTime"] = 15,
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/003/C872990A",
            },
        [80070322] = {
            ["Content"] = "放弃了地位与资源，为了一个人，将才华浪费在了我与老师截然不同的领域。",
            ["ContentFR"] = "Elle a tout abandonné : son statut, ses ressources, gaspillant son talent dans un domaine totalement différent.",
            ["DialogueId"] = 80070322,
            ["GUID"] = "C8729934",
            ["NextDialogue"] = 80070323,
            ["SpeakNpcId"] = 790013,
            ["TalkActionId"] = {
                [1] = "790013:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/003/C8729934",
            },
        [80070323] = {
            ["Camera"] = "19.332775,-55.147057,119.476562,0.000024,0.000417,-99.596123,45.0,100000.0,false,DoNotOverride,10.901892",
            ["Content"] = "您不是说过不缅怀过去吗。",
            ["ContentFR"] = "Mais vous avez dit que vous ne viviez pas dans le passé.",
            ["DialogueId"] = 80070323,
            ["FacialId"] = {
                [1] = "790013:None",
                },
            ["GUID"] = "C872995E",
            ["NextDialogue"] = 80070324,
            ["SpeakNpcId"] = 790014,
            ["TalkActionId"] = {
                [1] = "790014:Explain01L_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/003/C872995E",
            },
        [80070324] = {
            ["Camera"] = "68.539764,281.670898,93.375,0.0,5.399783,-108.200027,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "是，但这并不代表我毫无感情。每每回想，对老师，对同门的愤怒、不解、遗憾甚至是嫉妒仍会涌上心头。",
            ["ContentFR"] = "C’est vrai, mais ça ne veut pas dire que je suis insensible. À chaque souvenir, montent en moi colère, incompréhension, regrets, et même jalousie.",
            ["DialogueId"] = 80070324,
            ["GUID"] = "C8729988",
            ["NextDialogue"] = 80070325,
            ["SpeakNpcId"] = 790013,
            ["TalkActionId"] = {
                [1] = "790014:Explain01L_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/003/C8729988",
            },
        [80070325] = {
            ["Content"] = "我一直都知道，自己不是老师最优秀的学生，他们有理想，有抱负，有无限的可能与希望。",
            ["ContentFR"] = "Je savais que je n’étais pas la meilleure élève, que les autres avaient des rêves, des ambitions, et un avenir plein de promesses.",
            ["DialogueId"] = 80070325,
            ["GUID"] = "C87299B2",
            ["NextDialogue"] = 80070326,
            ["SpeakNpcId"] = 790013,
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/003/C87299B2",
            },
        [80070326] = {
            ["Camera"] = "93.881493,148.724472,103.033203,-0.000001,9.39976,-174.598511,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "但我知道，我会是老师活到最后的学生。",
            ["ContentFR"] = "Mais je sais que je serai celle qui ira jusqu’au bout.",
            ["DialogueId"] = 80070326,
            ["FacialId"] = {
                [1] = "790013:None",
                },
            ["GUID"] = "C87299DC",
            ["NextDialogue"] = 80070327,
            ["SpeakNpcId"] = 790013,
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/003/C87299DC",
            },
        [80070327] = {
            ["Camera"] = "68.550446,-309.161438,92.363281,0.000028,-0.200043,106.210785,45.000011,451.021332,false,Manual,5.197097",
            ["Content"] = "……对了，虽然我知道你不会说，但我还是要提醒一下，今天跟你说的事，不要对任何人讲起。",
            ["ContentFR"] = "... Au fait, même si je sais que tu ne parleras pas de ça à qui que ce soit, je te le rappelle, garde ça pour toi.",
            ["DialogueId"] = 80070327,
            ["GUID"] = "C8729A06",
            ["LookAt"] = {
                [1] = "790013:n(790014)",
                },
            ["NextDialogue"] = 80070328,
            ["SpeakNpcId"] = 790013,
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/003/C8729A06",
            },
        [80070328] = {
            ["Camera"] = "28.509796,241.818237,128.292969,0.000024,-3.59966,-101.194298,45.0,100000.0,false,Manual,16.626261",
            ["Content"] = "我知道我知道，我也没啥人好讲的。不过，既然长官不希望别人知道，为什么要对我说这么多呢？",
            ["ContentFR"] = "Je sais, je sais, je n’ai personne à qui en parler. Mais si vous ne voulez pas que les autres sachent, pourquoi me dire tout ça ?",
            ["DialogueId"] = 80070328,
            ["GUID"] = "C8729A30",
            ["NextDialogue"] = 80070329,
            ["SpeakNpcId"] = 790014,
            ["TalkActionId"] = {
                [1] = "790014:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/003/C8729A30",
            },
        [80070329] = {
            ["Content"] = "因为合适。我知道你不关心，也不懂那些复杂的往事与情感，更不会说一些共情的漂亮话，无论是真心还是假意。",
            ["ContentFR"] = "Parce que tu es la seule qui convienne pour ça. Je sais que tu ne t’intéresses pas aux histoires compliquées ni aux émotions, et que tu ne vas pas faire de jolies phrases pleines d’empathie, qu’elles soient sincères ou non.",
            ["DialogueId"] = 80070329,
            ["GUID"] = "C8729A5A",
            ["NextDialogue"] = 80070330,
            ["SpeakNpcId"] = 790013,
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/003/C8729A5A",
            },
        [80070330] = {
            ["Camera"] = "20.92244,-217.006439,116.833984,0.000028,-1.999476,97.407928,45.000011,359.358795,false,Manual,10.901892",
            ["Content"] = "我自始至终，都不需要任何人的同情与怜悯。",
            ["ContentFR"] = "Je n’ai jamais eu besoin de la pitié de qui que ce soit.",
            ["DialogueId"] = 80070330,
            ["GUID"] = "C8729A84",
            ["NextDialogue"] = 80070331,
            ["SpeakNpcId"] = 790013,
            ["TurnTo"] = {
                [1] = "790013:n(790014)",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/003/C8729A84",
            },
        [80070331] = {
            ["Content"] = "人们能依靠的，最后只有自己手中能掌握的，我想你也明白这一点。",
            ["ContentFR"] = "Au final, on ne peut compter que sur ce qu’on tient entre nos mains. Je crois que tu comprends ça.",
            ["DialogueId"] = 80070331,
            ["GUID"] = "C8729AAE",
            ["NextDialogue"] = 80070332,
            ["SpeakNpcId"] = 790013,
            ["TalkActionId"] = {
                [1] = "790013:Angry01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/003/C8729AAE",
            },
        [80070332] = {
            ["Camera"] = "1185.878418,-1058.124756,135.4375,0.000004,-0.200466,138.797653,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "那就这样，日后若是有困惑，也可以向我诉说。",
            ["ContentFR"] = "Voilà pour aujourd’hui. Si jamais tu doutes, tu peux toujours venir m’en parler.",
            ["DialogueId"] = 80070332,
            ["FinalCamera"] = "1255.99585,-1119.513062,135.765625,0.0,-0.200466,138.797638,35.000008,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "C8729AD8",
            ["NextDialogue"] = 80070333,
            ["SpeakNpcId"] = 790013,
            ["TalkActionId"] = {
                [1] = "790013:Angry01_End",
                },
            ["ToFinalCameraBlendTime"] = 15,
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/003/C8729AD8",
            },
        [80070333] = {
            ["Content"] = "我虽不会安慰你的情绪，但会给你解决困惑的手段。",
            ["ContentFR"] = "Je ne te réconforterai pas, mais je peux t’aider à trouver des solutions.",
            ["DialogueId"] = 80070333,
            ["GUID"] = "C8729B02",
            ["Scripts"] = "PlayOrStopBGM{PlayType{\"Stop\"},SoundPriority{\"Invite\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt02/0067_story_daphnis_theme_piano\"}}",
            ["SpeakNpcId"] = 790013,
            ["VoiceName"] = "voice/$Locale$/inv/Xibi/003/C8729B02",
            },
        [80080101] = {
            ["Camera"] = "-182.740234,418.929565,109.427734,0.000006,0.00002,-72.598679,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "……我从没见过那么巨大的秽兽……那时我觉得脑袋嗡嗡作响，手脚也不听使唤。虽然我很快就要回雾海见母神大人了，但没想到这一天会提前到来。",
            ["ContentFR"] = "... Je n’avais jamais vu un Souillé aussi énorme... J’avais la tête qui bourdonnait, les bras et les jambes paralysés. Je sais que je vais bientôt retourner à la Mer du Silence, auprès de Mère Embla... mais je ne pensais pas que ce jour arriverait si vite.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 80080101,
            ["GUID"] = "C878DD92",
            ["NextDialogue"] = 80080102,
            ["SpeakNpcId"] = 790004,
            ["TalkActionId"] = {
                [1] = "790004:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Saiqi/001/C878DD92",
            },
        [80080102] = {
            ["Camera"] = "-182.740234,418.929565,109.427734,0.000006,0.00002,-72.598679,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "然后——{性别：他|她}“唰”地一下冲了上来。我睁开眼的时候，{性别：他|她}已经挡在了我的面前！",
            ["ContentFR"] = "Et puis, {性别:il|elle} a surgi d’un coup ! Quand j’ai rouvert les yeux, {性别:il|elle} se tenait déjà devant moi pour me protéger !",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 80080102,
            ["GUID"] = "C878DDBC",
            ["NextDialogue"] = 80080103,
            ["SpeakNpcId"] = 790004,
            ["TalkActionId"] = {
                [1] = "790004:Explain01_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Saiqi/001/C878DDBC",
            },
        [80080103] = {
            ["Camera"] = "-115.056641,157.29718,104.279297,0.000006,2.600007,-78.7966,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "虽然{性别：他|她}的个子也不算壮实，但{性别：他|她}勇敢地直视着秽兽，一步也不肯退让……",
            ["ContentFR"] = "{性别:Il|Elle} n’est pas bien costaud, pourtant... mais {性别:il|elle} a tenu tête au Souillé sans reculer d’un pas...",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 80080103,
            ["GUID"] = "C878DDE6",
            ["NextDialogue"] = 80080104,
            ["Scripts"] = "SEQ{PlayAnimation{ActorId{790004},AnimationId{\"Disagree\"},Duration{2}},PlayAnimation{ActorId{790004},AnimationId{\"Explain02_Start\"},Duration{3}},PlayAnimation{ActorId{790004},AnimationId{\"Explain02_End\"},Duration{1}}}",
            ["SpeakNpcId"] = 790004,
            ["VoiceName"] = "voice/$Locale$/inv/Saiqi/001/C878DDE6",
            },
        [80080104] = {
            ["Camera"] = "-330.722656,-239.585709,105.560547,0.000012,0.0,51.204865,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "然后那只大秽兽猛地跳起来砸地，你们一起掉下去了。然后你们一起并肩作战，干掉了那个大块头。然后有个叫奥特赛德的男人突然冲了出来。然后——",
            ["ContentFR"] = "Et ensuite, ce gros machin a sauté et frappé le sol, vous êtes tombés ensemble, puis vous vous êtes battus côte à côte et vous l’avez vaincu. Et après, un type appelé l’Étranger a débarqué. Et ensuite...",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 80080104,
            ["GUID"] = "C878DE10",
            ["NextDialogue"] = 80080105,
            ["SpeakNpcId"] = 790002,
            ["TalkActionId"] = {
                [1] = "790002:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Saiqi/001/C878DE10",
            },
        [80080105] = {
            ["Camera"] = "-115.056641,157.29718,104.279297,0.000006,2.600007,-78.7966,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "艾丽莎你真是的，不要提前剧透！",
            ["ContentFR"] = "Elisa ! Ne me coupe pas, tu vas gâcher la surprise !",
            ["DialogueId"] = 80080105,
            ["GUID"] = "C878DE3A",
            ["NextDialogue"] = 80080106,
            ["SpeakNpcId"] = 790004,
            ["TalkActionId"] = {
                [1] = "790004:Sigh_Start",
                [2] = "790002:Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Saiqi/001/C878DE3A",
            },
        [80080106] = {
            ["Camera"] = "-330.722656,-239.585709,105.560547,0.000012,0.0,51.204865,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "这已经是你第三遍讲你的格雷姆大冒险了，我的耳朵都已经要起茧子了。",
            ["ContentFR"] = "C’est la troisième fois que tu racontes ton expédition dans la Fosse de Glevum... mes oreilles vont finir par faner.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 80080106,
            ["FacialId"] = {
                [1] = "790004:None",
                },
            ["GUID"] = "C878DE64",
            ["NextDialogue"] = 80080107,
            ["SpeakNpcId"] = 790002,
            ["TalkActionId"] = {
                [1] = "790002:Talk02_Start",
                [2] = "790004:Sigh_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Saiqi/001/C878DE64",
            },
        [80080107] = {
            ["Camera"] = "-182.740234,418.929565,109.427734,0.000006,0.00002,-72.598679,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "因、因为我还没有跟弗雷德讲过……嗯，是这样的。",
            ["ContentFR"] = "Pa-parce que je l’ai pas encore racontée à Fred... Voilà pourquoi, oui.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 80080107,
            ["GUID"] = "C878DE8E",
            ["NextDialogue"] = 80080108,
            ["SpeakNpcId"] = 790004,
            ["TalkActionId"] = {
                [1] = "790002:Talk02_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Saiqi/001/C878DE8E",
            },
        [80080108] = {
            ["Camera"] = "-330.722656,-239.585709,105.560547,0.000012,0.0,51.204865,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "赛琪很喜欢那个新朋友吧。",
            ["ContentFR"] = "Psyche, tu l’aimes bien, {性别:ce nouvel ami|cette nouvelle amie}, pas vrai ?",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 80080108,
            ["GUID"] = "C878DEB8",
            ["NextDialogue"] = 80080109,
            ["SpeakNpcId"] = 790001,
            ["TalkActionId"] = {
                [1] = "790001:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Saiqi/001/C878DEB8",
            },
        [80080109] = {
            ["Camera"] = "-330.722656,-239.585709,105.560547,0.000012,0.0,51.204865,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "今天你的话格外多……虽然你的话一直很多……",
            ["ContentFR"] = "Tu parles encore plus que d’habitude aujourd’hui... et pourtant, tu parles déjà beaucoup.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 80080109,
            ["GUID"] = "C878DEE2",
            ["NextDialogue"] = 80080110,
            ["SpeakNpcId"] = 790001,
            ["TalkActionId"] = {
                [1] = "790001:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Saiqi/001/C878DEE2",
            },
        [80080110] = {
            ["Camera"] = "-115.056641,157.29718,104.279297,0.000006,2.600007,-78.7966,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "……很、很多吗……",
            ["ContentFR"] = "Euh... je-je parle tant que ça... ?",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 80080110,
            ["GUID"] = "C878DF0C",
            ["NextDialogue"] = 80080111,
            ["SpeakNpcId"] = 790004,
            ["TalkActionId"] = {
                [1] = "790001:Explain01_End",
                [2] = "790004:Shock_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Saiqi/001/C878DF0C",
            },
        [80080111] = {
            ["Camera"] = "-293.373047,-99.673187,105.125,0.0,0.200002,27.605503,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我确实没听过，让赛琪继续讲吧。",
            ["ContentFR"] = "Je n’ai effectivement jamais entendu cette histoire. Laissons Psyche terminer.",
            ["DialogueId"] = 80080111,
            ["GUID"] = "C878DF36",
            ["LookAt"] = {
                [1] = "790003:n(790004)",
                [2] = "790004:n(790003)",
                },
            ["NextDialogue"] = 80080112,
            ["SpeakNpcId"] = 790003,
            ["TalkActionId"] = {
                [1] = "790004:Shock_End",
                [2] = "790003:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Saiqi/001/C878DF36",
            },
        [80080112] = {
            ["Camera"] = "-115.056641,157.29718,104.279297,0.000006,2.600007,-78.7966,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "嗯！我刚才说到哪儿了……啊，艾丽莎，你已经替我把后半段讲完了。",
            ["ContentFR"] = "Oui ! Alors, où j’en étais... Ah, Elisa a déjà raconté toute la fin.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 80080112,
            ["GUID"] = "C878DF60",
            ["LookAt"] = {
                [1] = "790004:n(790002)",
                },
            ["NextDialogue"] = 80080113,
            ["SpeakNpcId"] = 790004,
            ["TalkActionId"] = {
                [1] = "790004:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Saiqi/001/C878DF60",
            },
        [80080113] = {
            ["Camera"] = "-115.056641,157.29718,104.279297,0.000006,2.600007,-78.7966,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "哦……我想起来了，这个我还没有讲过！那个人不是本地人，是从海伯利亚之外的地方来的——一座南方的小岛！",
            ["ContentFR"] = "Mais attends... je me souviens d’un truc que j’ai pas encore dit ! Cette personne ne venait pas d’ici, mais d’un endroit bien plus loin qu’Hyperborea, une petite île au sud !",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 80080113,
            ["FacialId"] = {
                [1] = "790004:Happy01",
                },
            ["GUID"] = "C878DF8A",
            ["NextDialogue"] = 80080114,
            ["SpeakNpcId"] = 790004,
            ["TalkActionId"] = {
                [1] = "790004:Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Saiqi/001/C878DF8A",
            },
        [80080114] = {
            ["Camera"] = "-115.056641,157.29718,104.279297,0.000006,2.600007,-78.7966,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "{性别：他|她}说，那座岛上有金色的砂砾、白色的迷迭香……当然，大海就更不必说了，有一百片泪湖连起来那么大呢！",
            ["ContentFR"] = "{性别:Il|Elle} m’a dit que là-bas, le sable est doré, et il y a du romarin blanc qui pousse partout... Et puis la mer ! Immense, comme si cent Lacs du Deuil s’étaient unis !",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 80080114,
            ["FacialId"] = {
                [1] = "790004:None",
                },
            ["GUID"] = "C878DFB4",
            ["NextDialogue"] = 80080115,
            ["Scripts"] = "PARA{PlayAnimation{ActorId{790004},AnimationId{\"Explain02_Start\"},Duration{4}},SEQ{LookAt{LookAtDescription{\"790004:n(790002)\"}},LookAt{_delay{2},LookAtDescription{\"790004:n(790003)\"}}}}",
            ["SpeakNpcId"] = 790004,
            ["VoiceName"] = "voice/$Locale$/inv/Saiqi/001/C878DFB4",
            },
        [80080115] = {
            ["Camera"] = "-182.740234,418.929565,109.427734,0.000006,0.00002,-72.598679,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "那里也有巨大的天之树，但和这里不一样，那里树梢间吹来的风都是暖和的。人们在出海的时候，就把天之树当做远航的信标。",
            ["ContentFR"] = "Là-bas aussi, il y a un Arbre Céleste... mais pas froid comme ici. Le vent dans ses branches est doux et tiède. Et quand les gens partent en mer, ils s’en servent comme d’un phare.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 80080115,
            ["GUID"] = "C878DFDE",
            ["NextDialogue"] = 80080116,
            ["SpeakNpcId"] = 790004,
            ["TalkActionId"] = {
                [1] = "790004:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Saiqi/001/C878DFDE",
            },
        [80080116] = {
            ["Camera"] = "-330.722656,-239.585709,105.560547,0.000012,0.0,51.204865,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "……海，暖和的风。天之树不是工厂里冰冷冷的月髓液，而是……远航的信标……",
            ["ContentFR"] = "... La mer, une brise tiède... Un Arbre Céleste qui n’est pas une machine remplie de Phoxichor, mais… un phare pour les voyageurs...",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 80080116,
            ["GUID"] = "C878E008",
            ["NextDialogue"] = 80080117,
            ["SpeakNpcId"] = 790001,
            ["TalkActionId"] = {
                [1] = "790001:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Saiqi/001/C878E008",
            },
        [80080117] = {
            ["Camera"] = "-330.722656,-239.585709,105.560547,0.000012,0.0,51.204865,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "那……那个人有没有去过天之树脚下呢？从那里看天之树，是不是晶莹剔透，遮天蔽日——像吟游诗人唱的那样？",
            ["ContentFR"] = "Et... est-ce que cette personne est déjà allée au pied de cet Arbre Céleste ? Est-ce qu’il est vraiment scintillant, immense, qu’il touche presque le ciel, comme dans les chansons des ménestrels ?",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 80080117,
            ["GUID"] = "C878E032",
            ["NextDialogue"] = 80080118,
            ["Scripts"] = "SEQ{PlayAnimation{ActorId{790001},AnimationId{\"Think_End\"},Duration{1}},PlayAnimation{ActorId{790001},AnimationId{\"Explain01_Start\"},Duration{1}}}",
            ["SpeakNpcId"] = 790001,
            ["VoiceName"] = "voice/$Locale$/inv/Saiqi/001/C878E032",
            },
        [80080118] = {
            ["Camera"] = "-330.722656,-239.585709,105.560547,0.000012,0.0,51.204865,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "刚才你说到了沙子。",
            ["ContentFR"] = "Tu as parlé du sable, tout à l’heure...",
            ["DialogueId"] = 80080118,
            ["GUID"] = "C878E05C",
            ["LookAt"] = {
                [1] = "790003:n(790004)",
                [2] = "790004:n(790003)",
                [3] = "790002:n(790003)",
                [4] = "790001:n(790003)",
                },
            ["NextDialogue"] = 80080119,
            ["SpeakNpcId"] = 790003,
            ["TalkActionId"] = {
                [1] = "790001:Explain01_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Saiqi/001/C878E05C",
            },
        [80080119] = {
            ["Camera"] = "-330.722656,-239.585709,105.560547,0.000012,0.0,51.204865,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "听说海边的沙子都是绵绵软软的，踩在上面就像踩在面粉上一样，一点也不硌脚。那些被水洗过的沙子也很干净，不会把脚弄脏。是么？",
            ["ContentFR"] = "Il paraît que sur la plage, le sable est doux, comme de la farine sous les pieds. Pas rêche du tout. Et puis, il est propre, les vagues le lavent tout le temps, alors on ne se salit même pas.",
            ["DialogueId"] = 80080119,
            ["GUID"] = "C878E086",
            ["NextDialogue"] = 80080120,
            ["SpeakNpcId"] = 790003,
            ["TalkActionId"] = {
                [1] = "790003:Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Saiqi/001/C878E086",
            },
        [80080120] = {
            ["Camera"] = "-115.056641,157.29718,104.279297,0.000006,2.600007,-78.7966,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "这些{性别：他|她}倒是没说过……下次我帮你们问问！",
            ["ContentFR"] = "{性别:Il|Elle} n’a rien dit de tout ça... Je lui demanderai pour vous, la prochaine fois !",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 80080120,
            ["FacialId"] = {
                [1] = "790004:Unhappy01",
                },
            ["GUID"] = "C878E0B0",
            ["LookAt"] = {
                [1] = "790002:n(790004)",
                [2] = "790001:n(790004)",
                [3] = "790003:n(790004)",
                },
            ["NextDialogue"] = 80080121,
            ["SpeakNpcId"] = 790004,
            ["TalkActionId"] = {
                [1] = "790003:Talk01_End",
                [2] = "790004:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Saiqi/001/C878E0B0",
            },
        [80080121] = {
            ["Camera"] = "-330.722656,-239.585709,105.560547,0.000012,0.0,51.204865,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "问这些又有什么用呢，反正我们连这座冰湖城都出不去。",
            ["ContentFR"] = "Mais à quoi bon demander tout ça, de toute façon ? On n’arrive même pas à sortir de Givrelac...",
            ["DialogueId"] = 80080121,
            ["FacialId"] = {
                [1] = "790004:None",
                },
            ["GUID"] = "C878E0DA",
            ["LookAt"] = {
                [1] = "790004:n(790002)",
                [2] = "790002:n(790004)",
                [3] = "790001:n(790002)",
                [4] = "790003:n(790002)",
                },
            ["NextDialogue"] = 80080122,
            ["SpeakNpcId"] = 790002,
            ["TalkActionId"] = {
                [1] = "790002:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Saiqi/001/C878E0DA",
            },
        [80080122] = {
            ["Camera"] = "-330.722656,-239.585709,105.560547,0.000012,0.0,51.204865,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "……也是。",
            ["ContentFR"] = "... C’est vrai.",
            ["DialogueId"] = 80080122,
