        [80080124] = {
            ["Camera"] = "-182.740234,418.929565,109.427734,0.000006,0.00002,-72.598679,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "不、不是的……艾丽莎，你想。",
            ["ContentFR"] = "Non, attends... Elisa, réfléchis.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 80080124,
            ["GUID"] = "C878E158",
            ["LookAt"] = {
                [1] = "790004:n(790002)",
                [2] = "790003:n(790004)",
                [3] = "790002:n(790004)",
                [4] = "790001:n(790004)",
                },
            ["NextDialogue"] = 80080125,
            ["SpeakNpcId"] = 790004,
            ["TalkActionId"] = {
                [1] = "790004:DisagreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Saiqi/001/C878E158",
            },
        [80080125] = {
            ["Camera"] = "-182.740234,418.929565,109.427734,0.000006,0.00002,-72.598679,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "就像亨特告诉我们狩月人每天都能遇到怎样的委托，米娅让我们知道泪湖的冰下面其实藏着各种各样的鱼……",
            ["ContentFR"] = "C’est comme quand Hunt nous raconte ce que vivent les Chasseurs de Phoxène chaque jour. Ou quand Mia nous explique tous les poissons qui vivent sous la glace du Lac du Deuil...",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 80080125,
            ["GUID"] = "C878E182",
            ["NextDialogue"] = 80080126,
            ["SpeakNpcId"] = 790004,
            ["TalkActionId"] = {
                [1] = "790004:Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Saiqi/001/C878E182",
            },
        [80080126] = {
            ["Camera"] = "-115.056641,157.29718,104.279297,0.000006,2.600007,-78.7966,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "卡罗琳娜告诉我们内城的夫人们每天都过着怎样新奇的生活，艾丽莎总是能用特别的视角解读童话故事，弗雷德教给我们很多打扫卫生的小窍门……",
            ["ContentFR"] = "Quand Carolina décrit la vie si étrange des dames de la cité intérieure, quand Elisa trouve toujours une interprétation originale des contes... Et Fred, toi, tu nous donnes plein d’astuces pour bien nettoyer...",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 80080126,
            ["GUID"] = "C878E1AC",
            ["NextDialogue"] = 80080127,
            ["SpeakNpcId"] = 790004,
            ["TalkActionId"] = {
                [1] = "790004:Talk02_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Saiqi/001/C878E1AC",
            },
        [80080127] = {
            ["Camera"] = "-115.056641,157.29718,104.279297,0.000006,2.600007,-78.7966,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "这些……就算没有亲身经历过，也一样是很棒很棒的见闻呀。",
            ["ContentFR"] = "Tout ça... même si on ne le vit pas soi-même, ce sont de belles choses à entendre, non ?",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 80080127,
            ["GUID"] = "C878E1D6",
            ["NextDialogue"] = 80080128,
            ["SpeakNpcId"] = 790004,
            ["TalkActionId"] = {
                [1] = "790004:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Saiqi/001/C878E1D6",
            },
        [80080128] = {
            ["Camera"] = "-330.722656,-239.585709,105.560547,0.000012,0.0,51.204903,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "哦，在生命快要结束的时候知道这么多知识，简直太酷了——竟然一条也用不上耶。",
            ["ContentFR"] = "Oh oui, c’est trop bien... Apprendre des tas de choses juste avant de mourir, pour les emporter dans sa tombe.",
            ["DialogueId"] = 80080128,
            ["GUID"] = "C878E200",
            ["LookAt"] = {
                [1] = "790002:n(790002)",
                [2] = "790001:n(790002)",
                [3] = "790003:n(790002)",
                },
            ["NextDialogue"] = 80080129,
            ["SpeakNpcId"] = 790002,
            ["TalkActionId"] = {
                [1] = "790002:Sigh_Start",
                [2] = "790004:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Saiqi/001/C878E200",
            },
        [80080129] = {
            ["Camera"] = "-330.722656,-239.585709,105.560547,0.000012,0.0,51.204903,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "……你不觉得这很好笑，很残忍吗？",
            ["ContentFR"] = "Tu trouves pas ça un peu ironique... et cruel ?",
            ["DialogueId"] = 80080129,
            ["GUID"] = "C878E22A",
            ["LookAt"] = {
                [1] = "790002:n(790004)",
                [2] = "790001:n(790002)",
