            ["VoiceName"] = "voice/$Locale$/inv/Saiqi/001/C878E3CE",
            },
        [80080140] = {
            ["Camera"] = "-330.722656,-239.585709,105.560547,0.000012,0.0,51.204865,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "不用了。我就随口一说……要是缺了你每天在这里聒噪，想想还挺不习惯的。",
            ["ContentFR"] = "Laisse tomber. J’ai dit ça comme ça... Mais c’est vrai que si t’arrêtais de bavarder ici tous les jours, ce serait drôlement bizarre.",
            ["DialogueId"] = 80080140,
            ["GUID"] = "C878E3F8",
            ["LookAt"] = {
                [1] = "790002:n(790004)",
                [2] = "790004:n(790002)",
                },
            ["NextDialogue"] = 80080141,
            ["SpeakNpcId"] = 790002,
            ["TalkActionId"] = {
                [1] = "790002:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Saiqi/001/C878E3F8",
            },
        [80080141] = {
            ["Camera"] = "-115.056641,157.29718,104.279297,0.000006,2.600007,-78.7966,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "好……艾丽莎你没有生气就好。",
            ["ContentFR"] = "Vraiment... ? Bon, tant mieux si tu n’es pas fâchée.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 80080141,
            ["GUID"] = "C878E422",
            ["NextDialogue"] = 80080142,
            ["SpeakNpcId"] = 790004,
            ["TalkActionId"] = {
                [1] = "790004:AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Saiqi/001/C878E422",
            },
        [80080142] = {
            ["Camera"] = "-330.722656,-239.585709,105.560547,0.000012,0.0,51.204865,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "……那下次，遇到那个人的时候，帮我问问金色沙子的事吧。",
            ["ContentFR"] = "... Alors, la prochaine fois que tu croises cette personne, tu pourras lui demander pour le sable doré ?",
            ["DialogueId"] = 80080142,
            ["GUID"] = "C878E44C",
            ["LookAt"] = {
                [1] = "790003:n(790004)",
                [2] = "790004:n(790003)",
                [3] = "790002:n(790003)",
                [4] = "790001:n(790003)",
