            },
        [80080143] = {
            ["Camera"] = "-330.722656,-239.585709,105.560547,0.000012,0.0,51.204865,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "还有天之树的事。",
            ["ContentFR"] = "Et aussi pour l’Arbre Céleste !",
            ["DialogueId"] = 80080143,
            ["GUID"] = "C878E476",
            ["LookAt"] = {
                [1] = "790004:n(790001)",
                [2] = "790003:n(790004)",
                [3] = "790002:n(790001)",
                [4] = "790001:n(790004)",
