        [80080144] = {
            ["Camera"] = "-115.056641,157.29718,104.279297,0.000006,2.600007,-78.7966,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "嗯，我记下了……下次有机会，我会帮大家问的。",
            ["ContentFR"] = "Oui, oui, c’est noté... La prochaine fois, je lui demanderai tout ça pour vous.",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 80080144,
