        [80080223] = {
            ["Camera"] = "-130.748047,-103.410034,139.367188,0.00001,3.199786,-140.194809,35.000011,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "但是，比起死亡，我更怕的是……“消失”。一旦被忘记，那就连曾经活过的证明也被抹去了。",
            ["ContentFR"] = "Mais ce qui me fait encore plus peur que la mort, c’est... disparaître. Si plus personne ne se souvient de toi, c’est comme si t’avais jamais existé.",
            ["DialogueId"] = 80080223,
            ["GUID"] = "C878F196",
            ["NextDialogue"] = 80080224,
            ["SpeakNpcId"] = 790004,
            ["TalkActionId"] = {
                [1] = "790004:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Saiqi/002/C878F196",
            },
        [80080224] = {
            ["Camera"] = "-142.1875,-33.322571,140.789062,0.0,0.0,12.604458,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "好吧，所以你就费尽心思帮这个帮那个，希望他们能记住你，多一个人也好，多一天也好。是吗？",
            ["ContentFR"] = "Alors tu fais tout ça dans l’espoir qu’on se souvienne de toi ? Même si c’est qu’une personne, même si c’est pour un jour de plus ?",
            ["DialogueId"] = 80080224,
            ["GUID"] = "C878F1C0",
            ["NextDialogue"] = 80080225,
            ["SpeakNpcId"] = 790006,
            ["TalkActionId"] = {
