            ["ToFinalCameraBlendTime"] = 15,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/001/C89F5836",
            },
        [80140144] = {
            ["Camera"] = "109.757812,-116.020081,131.90625,0.000012,-3.599912,-163.593491,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "请告诉我！报纸上说的那些东西不是真的，对不对？您怎么可能委身于男爵那种花花公子，玷污自己高洁的品格——！薇奥莱塔小姐！！！",
            ["ContentFR"] = "Dites-moi ! Ce qu’ont écrit les journaux, c’est faux, non ? Comment pourriez-vous vous abaisser à sortir avec un baron frivole, salissant votre pureté, Mademoiselle Violetta !",
            ["DialogueId"] = 80140144,
            ["FacialId"] = {
                [1] = "790039:CM_Angry01",
                },
            ["GUID"] = "C89F5860",
            ["LookAt"] = {
                [1] = "790038:n(790031)",
                [2] = "790037:n(790031)",
                },
            ["NextDialogue"] = 80140145,
            ["Scripts"] = "SEQ{\
MoveTo{_delay{6},ActorId{790039},MoveSpeed{80},TargetPoint{\"P80140145\"}},\
PlayAnimation{ActorId{790039},AnimationId{\"Angry01_Start\"},Duration{1},_click{false}}\
}",
            ["SpeakNpcId"] = 790039,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/001/C89F5860",
            },
        [80140145] = {
            ["Camera"] = "218.556641,-87.356079,99.0,0.000011,0.0,-170.399063,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "老师，小心！",
            ["ContentFR"] = "Madame Violetta, faites attention !",
            ["DialogueId"] = 80140145,
            ["FacialId"] = {
                [1] = "790036:Shock01",
                },
            ["GUID"] = "C89F588A",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 80140146,
            ["SpeakNpcId"] = 790036,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/001/C89F588A",
            },
        [80140146] = {
            ["Camera"] = "218.556641,-87.356079,99.0,0.000011,0.0,-170.399063,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "臭小子，给我让开——你、你……卡戎？！",
            ["ContentFR"] = "Sale gosse, dégage... toi... toi... un Charon ?!",
            ["DialogueId"] = 80140146,
            ["GUID"] = "C89F58B4",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 80140147,
            ["Scripts"] = "PARA{\
SetLocation{ActorId{790036},TargetPoint{\"P80140146\"},Visibility{\"Show\"}},\
SetLocation{ActorId{790039},TargetPoint{\"P80140143\"},Visibility{\"Show\"}}\
}",
            ["SpeakNpcId"] = 790039,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/001/C89F58B4",
            },
        [80140147] = {
            ["Camera"] = "-364.367188,-292.053711,181.855469,0.000102,-15.199888,38.182243,35.000008,130.60051,false,Manual,2.8",
            ["Content"] = "…………！",
            ["ContentFR"] = "... !",
            ["DialogueId"] = 80140147,
            ["FacialId"] = {
                [1] = "790036:Pain01",
                },
            ["GUID"] = "C89F58DE",
            ["LookAt"] = {
                [1] = "790031:n(790036)",
                },
            ["NextDialogue"] = 80140148,
            ["SpeakNpcId"] = 790036,
            ["TalkActionId"] = {
                [1] = "790036:Sigh_Start",
                [2] = "790039:Shock_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/001/C89F58DE",
            },
        [80140148] = {
            ["Camera"] = "-1148.580078,356.133179,777.359375,0.000013,-38.998032,-40.990875,23.313377,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "那个演员——那个新人演员是卡戎啊！",
            ["ContentFR"] = "Ce nouveau comédien est un Charon !",
            ["DialogueId"] = 80140148,
            ["FinalCamera"] = "-616.564453,649.488525,777.359375,0.000014,-40.798069,-79.789642,23.313377,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "C89F5908",
            ["NextDialogue"] = 80140149,
            ["SpeakNpcId"] = 790039,
            ["TalkActionId"] = {
                [1] = "790039:Shock_Start",
                [2] = "790031:Shock_End",
                },
            ["ToFinalCameraBlendTime"] = 25,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/001/C89F5908",
            },
        [80140149] = {
            ["Content"] = "卡戎之民也能上台？剧团疯了吧？",
            ["ContentFR"] = "Un Charon sur scène ? La troupe est folle ?",
            ["DialogueId"] = 80140149,
            ["FacialId"] = {
                [1] = "790036:Shock01",
                },
            ["GUID"] = "C89F5932",
            ["NextDialogue"] = 80140150,
            ["Scripts"] = "PlayAnimation{ActorId{790036},AnimationId{\"Sigh_End\"},Duration{1},_click{false}}",
            ["SpeakNpcId"] = 790034,
            ["SpeakNpcName"] = "UI_CMNpc_Name_UproarAudience",
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/001/C89F5932",
            },
        [80140150] = {
            ["Content"] = "你们好大的胆子，居然敢欺骗观众，敢让这种恶魔上台玷污我们的眼睛！剧团的负责人在哪里，给我出来！",
            ["ContentFR"] = "Comment osez-vous tromper le public, laisser ce démon salir nos yeux ? Où est le responsable ? Qu’il se montre !",
            ["DialogueId"] = 80140150,
            ["GUID"] = "C89F595C",
            ["NextDialogue"] = 80140151,
            ["SpeakNpcId"] = 790039,
            ["TalkActionId"] = {
                [1] = "790031:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/001/C89F595C",
            },
        [80140151] = {
            ["Camera"] = "-911.287109,-294.924744,160.019531,0.000016,-3.999909,5.600585,53.01371,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "是我欺骗了团长和薇奥莱塔女士，和其他人无关！请不要——",
            ["ContentFR"] = "C’est moi qui ai trompé la Directrice et Madame Violetta, pas eux ! S’il vous plaît...",
            ["DialogueId"] = 80140151,
            ["GUID"] = "C89F5986",
            ["LookAt"] = {
                [1] = "790036:n(790039)",
                },
            ["NextDialogue"] = 80140152,
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{790036},AnimationId{\"Explain02_Start\"},Duration{3},_click{false}},\
PlayAnimation{ActorId{790036},AnimationId{\"Explain02_End\"},Duration{1},_click{false}}\
}",
            ["SpeakNpcId"] = 790036,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/001/C89F5986",
            },
        [80140152] = {
            ["Camera"] = "-180.923828,-320.03418,145.136719,0.00002,-1.599453,141.594254,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "闭嘴！真晦气，居然让一个卡戎玷污《雪国的孩子》！啧，还碰脏了老子的衣服！还不滚下台！",
            ["ContentFR"] = "Tais-toi ! Quelle honte, laisser un Charon souiller Né du blizzard ! En plus, tu as sali mes vêtements ! Descends de scène !",
            ["DialogueId"] = 80140152,
            ["GUID"] = "C89F59B0",
            ["NextDialogue"] = 80140153,
            ["SpeakNpcId"] = 790039,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/001/C89F59B0",
            },
        [80140153] = {
            ["Camera"] = "-1296.828125,-1353.771851,875.0625,0.000009,-29.600126,51.601456,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "滚下去！滚下去！滚下去！",
            ["ContentFR"] = "Descends ! Descends ! Descends !",
            ["DialogueId"] = 80140153,
            ["GUID"] = "C89F59DA",
            ["NextDialogue"] = 80140154,
            ["Scripts"] = "PlayNormalSound{EventPath{\"event:/sfx/common/story/invite/crowdbattle\"},PlayAs2D{true}}",
            ["SpeakNpcId"] = 790034,
            ["SpeakNpcName"] = "UI_CMNpc_Name_UproarAudience",
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/001/C89F59DA",
            },
        [80140154] = {
            ["Camera"] = "219.056641,-90.314087,134.210938,0.000011,-3.599967,-170.399216,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "呃啊！",
            ["ContentFR"] = "Aaargh !",
            ["DialogueId"] = 80140154,
            ["GUID"] = "C89F5A04",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 80140155,
            ["SpeakNpcId"] = 790036,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/001/C89F5A04",
            },
        [80140155] = {
            ["Camera"] = "219.056641,-90.314087,134.210938,0.000011,-3.599967,-170.399216,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "请各位冷静些！老师，帕西法尔……唔！",
            ["ContentFR"] = "Calmez-vous ! Madame Violetta, Parsifal... arrêtez !",
            ["DialogueId"] = 80140155,
            ["GUID"] = "C89F5A2E",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 80140156,
            ["SpeakNpcId"] = 790026,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/001/C89F5A2E",
            },
        [80140156] = {
            ["Camera"] = "219.056641,-90.314087,134.210938,0.000011,-3.599967,-170.399216,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "停手……不要打人！！你们住手！治安署——谁去一趟治安署！",
            ["ContentFR"] = "Arrêtez ! Ne le frappez pas ! Quelqu’un, allez vite prévenir le Bureau de la Sécurité !",
            ["DialogueId"] = 80140156,
            ["GUID"] = "C89F5A58",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 80140157,
            ["SpeakNpcId"] = 790026,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/001/C89F5A58",
            },
        [80140157] = {
            ["Camera"] = "219.056641,-90.314087,134.210938,0.000011,-3.599967,-170.399216,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "滚下去！滚下去！滚下去！",
            ["ContentFR"] = "Descends ! Descends ! Descends !",
            ["DialogueId"] = 80140157,
            ["GUID"] = "C89F5A82",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 80140158,
            ["SpeakNpcId"] = 790034,
            ["SpeakNpcName"] = "UI_CMNpc_Name_UproarAudience",
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/001/C89F5A82",
            },
        [80140158] = {
            ["Camera"] = "219.056641,-90.314087,134.210938,0.000011,-3.599967,-170.399216,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "骗子、骗子……<W>恶魔的孩子！</>",
            ["ContentFR"] = "Menteur, menteur... <W>Enfant du démon</> !",
            ["DialogueId"] = 80140158,
            ["GUID"] = "C89F5AAC",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 80140159,
            ["SpeakNpcId"] = 790034,
            ["SpeakNpcName"] = "UI_CMNpc_Name_UproarAudience",
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/001/C89F5AAC",
            },
        [80140159] = {
            ["Camera"] = "-1232.833984,-169.477966,838.933594,0.000135,49.99144,76.002792,15.0,100.0,false,Manual,2.8",
            ["Content"] = "不……我不是……",
            ["ContentFR"] = "Non... je ne suis pas...",
            ["DialogueId"] = 80140159,
            ["FinalCamera"] = "-1012.566406,714.236694,1923.988281,0.000135,49.991432,76.002762,15.0,5.0,false,Manual,2.8",
            ["GUID"] = "C89F5AD6",
            ["NextDialogue"] = 80140160,
            ["SpeakNpcId"] = 790036,
            ["ToFinalCameraBlendTime"] = 25,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/001/C89F5AD6",
            },
        [80140160] = {
            ["Content"] = "我只是想站上舞台，仅此而已。",
            ["ContentFR"] = "Je voulais juste monter sur scène, rien de plus.",
            ["DialogueId"] = 80140160,
            ["GUID"] = "C89F5B00",
            ["NextDialogue"] = 80140161,
            ["SpeakNpcId"] = 790036,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/001/C89F5B00",
            },
        [80140161] = {
            ["Content"] = "但从舞台落下的，却不是鲜花，而是血。",
            ["ContentFR"] = "Mais ce qui est tombé de la scène, ce n’étaient pas des fleurs, c’était du sang.",
            ["DialogueId"] = 80140161,
            ["GUID"] = "C89F5B2A",
            ["SpeakNpcId"] = 790036,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/001/C89F5B2A",
            },
        [80140162] = {
            ["Content"] = "我是悲哀的囚犯，亲手献上肮脏的罪证。",
            ["ContentFR"] = "Je suis un prisonnier misérable, offrant de mes propres mains la preuve de ma culpabilité.",
            ["DialogueId"] = 80140162,
            ["Duration"] = 4,
            ["GUID"] = "C89F5B54",
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/001/C89F5B54",
            },
        [80140163] = {
            ["Content"] = "然后，接受审判。",
            ["ContentFR"] = "Et maintenant... j’attends mon jugement.",
            ["DialogueId"] = 80140163,
            ["Duration"] = 3,
            ["GUID"] = "C89F5B7E",
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/001/C89F5B7E",
            },
        [80140164] = {
            ["DialogueId"] = 80140164,
            ["GUID"] = "C89F578F",
            ["IsBlack"] = 1,
            ["Scripts"] = "PlayNormalSound{EventPath{\"event:/sfx/common/story/invite/applaud\"},PlayAs2D{true}}",
            },
        [80140201] = {
            ["Content"] = "你是谁？",
            ["ContentFR"] = "Qui êtes-vous ?",
            ["DialogueId"] = 80140201,
            ["Duration"] = 3,
            ["GUID"] = "C89F61BA",
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/002/C89F61BA",
            },
        [80140202] = {
            ["Content"] = "你在找什么？",
            ["ContentFR"] = "Que cherchez-vous ?",
            ["DialogueId"] = 80140202,
            ["Duration"] = 3,
            ["GUID"] = "C89F61E4",
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/002/C89F61E4",
            },
        [80140203] = {
            ["Camera"] = "-894.0,93.0,384.207031,0.0,-18.199085,2.584682,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "听闻您找我，年轻的演员先生。",
            ["ContentFR"] = "On m’a dit que vous souhaitiez me voir, jeune comédien.",
            ["DialogueId"] = 80140203,
            ["FinalCamera"] = "-894.0,84.0,384.207031,0.0,-18.199085,2.584682,35.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "C89F620E",
            ["LookAt"] = {
                [1] = "790043:n(790040)",
                [2] = "\
790040:n(790043)",
                },
            ["NextDialogue"] = 80140204,
            ["Scripts"] = "MoveTo{ActorId{790043},MoveSpeed{100},TargetPoint{\"P80140204\"}}",
            ["SpeakNpcId"] = 790040,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/002/C89F620E",
            },
        [80140204] = {
            ["Camera"] = "-26.839844,69.702148,131.152344,0.000001,4.999924,119.395248,35.000011,224.273438,false,Manual,2.8",
            ["Content"] = "……您好，格伦维尔先生。",
            ["ContentFR"] = "... Bonsoir, Monsieur Glenville.",
            ["DialogueId"] = 80140204,
            ["GUID"] = "C89F6238",
            ["NextDialogue"] = 80140205,
            ["SpeakNpcId"] = 790043,
            ["TalkActionId"] = {
                [1] = "790043:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/002/C89F6238",
            },
        [80140205] = {
            ["Content"] = "我是帕西法尔·斯诺菲尔德，“魔笛”剧团的演员。听闻莫里斯·格伦维尔先生莅临，团长特地吩咐我前来献上问候和一份薄礼。",
            ["ContentFR"] = "Je suis Parsifal Snowfield, comédien de la troupe de la Flûte Enchantée. Apprenant votre venue, notre directrice m’a chargé de vous adresser ses salutations, ainsi qu’un modeste cadeau.",
            ["DialogueId"] = 80140205,
            ["GUID"] = "C89F6262",
            ["NextDialogue"] = 80140206,
            ["Scripts"] = "PlayAnimation{_delay{3},ActorId{790043},AnimationId{\"Explain02_End\"},Duration{1},_click{false}}",
            ["SpeakNpcId"] = 790043,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/002/C89F6262",
            },
        [80140206] = {
            ["Content"] = "这是剧院二百周年庆典的纪念徽章，请您收下。",
            ["ContentFR"] = "Voici une broche commémorative célébrant les 200 ans du théâtre. Nous serions honorés que vous l'acceptiez.",
            ["DialogueId"] = 80140206,
            ["GUID"] = "C89F628C",
            ["NextDialogue"] = 80140207,
            ["SpeakNpcId"] = 790043,
            ["TalkActionId"] = {
                [1] = "790043:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/002/C89F628C",
            },
        [80140207] = {
            ["Camera"] = "-362.974609,231.725586,229.28125,0.000003,-18.599478,-6.208903,35.000011,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "哦？我不常来剧院，倒是头一回受到这样的礼遇，实在荣幸。请代我向普奇夫人转达谢意。",
            ["ContentFR"] = "Oh ? Je ne viens pas souvent au théâtre, c’est donc un honneur inattendu. Veuillez transmettre mes remerciements à Madame Putsch.",
            ["DialogueId"] = 80140207,
            ["GUID"] = "C89F62B6",
            ["NextDialogue"] = 80140208,
            ["SpeakNpcId"] = 790040,
            ["TalkActionId"] = {
                [1] = "790043:Explain01_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/002/C89F62B6",
            },
        [80140208] = {
            ["Camera"] = "-26.839844,69.702148,131.152344,0.000001,4.999924,119.395248,35.000011,224.273438,false,Manual,2.8",
            ["Content"] = "您是剧院的贵客，理应如此。希望我的冒昧来访没有打扰到您。",
            ["ContentFR"] = "Vous êtes un invité de marque, c’est naturel. J’espère que ma visite impromptue ne vous dérange pas.",
            ["DialogueId"] = 80140208,
            ["GUID"] = "C89F62E0",
            ["NextDialogue"] = 80140209,
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{790043},AnimationId{\"Explain02_Start\"},Duration{4}},\
PlayAnimation{ActorId{790043},AnimationId{\"Explain02_End\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 790043,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/002/C89F62E0",
            },
        [80140209] = {
            ["Camera"] = "-408.677734,262.879395,203.933594,0.000049,-12.399716,-12.21366,37.0,490.941406,false,Manual,2.8",
            ["Content"] = "无妨，我的妻子和孩子们尚未抵达，我现在正巧有空。您刚才说，您是一位演员？等会儿您会登台吗？",
            ["ContentFR"] = "Pas du tout, ma femme et mes enfants ne sont pas encore arrivés, j’ai donc un peu de temps. Vous disiez être comédien ? Vous allez monter sur scène ce soir ?",
            ["DialogueId"] = 80140209,
            ["GUID"] = "C89F630A",
            ["NextDialogue"] = 80140210,
            ["SpeakNpcId"] = 790040,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/002/C89F630A",
            },
        [80140210] = {
            ["Camera"] = "-110.558594,139.20166,173.46875,0.00002,-8.599856,100.192047,35.000008,108.885063,false,Manual,2.8",
            ["Content"] = "……不，我不在今天的演员表上。其实，我来这里除了问候之外，还有些……私人的问题，想和您谈谈。",
            ["ContentFR"] = "... Non, je ne joue pas ce soir. En réalité, au-delà de mes salutations, je viens aussi pour une... affaire personnelle.",
            ["DialogueId"] = 80140210,
            ["GUID"] = "C89F6334",
            ["NextDialogue"] = 80140211,
            ["SpeakNpcId"] = 790043,
            ["TalkActionId"] = {
                [1] = "790043:DisagreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/002/C89F6334",
            },
        [80140211] = {
            ["Camera"] = "-478.255859,-5.12793,182.710938,0.00001,-7.599002,24.784918,35.000011,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "是吗？请说，我很乐意倾听年轻朋友的烦恼。",
            ["ContentFR"] = "Ah bon ? Parlez, je suis toujours prêt à écouter les soucis d’un jeune.",
            ["DialogueId"] = 80140211,
            ["GUID"] = "C89F635E",
            ["NextDialogue"] = 80140212,
            ["SpeakNpcId"] = 790040,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/002/C89F635E",
            },
        [80140212] = {
            ["Camera"] = "-16.511719,59.08252,140.367188,0.000026,1.999565,118.993134,35.000015,220.325043,false,Manual,2.8",
            ["Content"] = "在此之前，请您先看一看这封旧信和这块怀表，也许它们能帮助您想起一些往事。",
            ["ContentFR"] = "Avant cela, pourriez-vous regarder cette vieille lettre et cette montre à gousset ? Peut-être vous rappelleront-elles certains souvenirs...",
            ["DialogueId"] = 80140212,
            ["GUID"] = "C89F6388",
            ["NextDialogue"] = 80140213,
            ["SpeakNpcId"] = 790043,
            ["TalkActionId"] = {
                [1] = "790043:Give",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/002/C89F6388",
            },
        [80140213] = {
            ["Camera"] = "-395.544922,246.702637,229.242188,0.000005,-17.199884,-7.005292,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "这怀表价值不菲，上面还刻着格伦维尔家的家徽，应该是我订制的。这封信……嗯，也是我的笔迹。“致赫泽蕾德”……",
            ["ContentFR"] = "Cette montre est précieuse, ornée du blason Glenville, je l’ai sûrement commandée. Quant à cette lettre... oui, c’est mon écriture. « À Herzeleide »...",
            ["DialogueId"] = 80140213,
            ["DialoguePanelType"] = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Atlas/Prop/Item/T_Read_03.T_Read_03'}",
            ["GUID"] = "C89F63B2",
            ["NextDialogue"] = 80140214,
            ["SpeakNpcId"] = 790040,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/002/C89F63B2",
            },
        [80140214] = {
            ["Camera"] = "259.349609,-125.29248,118.851562,0.000007,1.999504,130.99202,46.855404,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "是的，这是二十二年前，您写给一位女士的亲笔信。她叫赫泽蕾德·斯诺菲尔德，是我的母亲……她已经在前些年因病去世。",
            ["ContentFR"] = "Exact. Cette lettre date d’il y a vingt-deux ans, écrite par vous à une dame, Herzeleide Snowfield, ma mère... Elle est décédée il y a quelques années, des suites d’une maladie.",
            ["DialogueId"] = 80140214,
            ["GUID"] = "C89F63DC",
            ["NextDialogue"] = 80140215,
            ["SpeakNpcId"] = 790043,
            ["TalkActionId"] = {
                [1] = "790043:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/002/C89F63DC",
            },
        [80140215] = {
            ["Content"] = "母亲生前从未向我提起过我父亲的身份，但我整理她的遗物时发现了她早年与您往来的书信，这便是其中一封。",
            ["ContentFR"] = "Ma mère ne m’a jamais parlé de mon père. Mais en triant ses affaires après sa mort, j’ai découvert des lettres qu’elle avait échangées avec vous. Celle-ci en fait partie.",
            ["DialogueId"] = 80140215,
            ["FacialId"] = {
                [1] = "790043:Disappoint01",
                },
            ["GUID"] = "C89F6406",
            ["NextDialogue"] = 80140216,
            ["Scripts"] = "PlayAnimation{ActorId{790043},AnimationId{\"Disagree\"},Duration{1},_delay{1}}",
            ["SpeakNpcId"] = 790043,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/002/C89F6406",
            },
        [80140216] = {
            ["Camera"] = "-43.1875,107.541016,135.941406,0.00001,5.599901,121.996529,35.000011,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "根据信中的内容，二十多年前，二位在子爵大人的宴会上相识，只见了一面便坠入爱河……而那场宴会，刚好在我出生的十个月前。",
            ["ContentFR"] = "Selon la lettre, vous vous êtes rencontrés il y a plus de vingt ans lors d’un banquet chez un vicomte, et vous êtes tombés amoureux dès la première rencontre... ce banquet a eu lieu dix mois avant ma naissance.",
            ["DialogueId"] = 80140216,
            ["GUID"] = "C89F6430",
            ["NextDialogue"] = 80140217,
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{790043},AnimationId{\"Explain02_Start\"},Duration{4}},\
PlayAnimation{ActorId{790043},AnimationId{\"Explain02_End\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 790043,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/002/C89F6430",
            },
        [80140217] = {
            ["Camera"] = "-22.451172,56.513184,131.0,0.0,4.999951,121.795105,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "……您的意思是，您是我的孩子？",
            ["ContentFR"] = "... Voulez-vous dire que je suis votre père ?",
            ["DialogueId"] = 80140217,
            ["GUID"] = "C89F645A",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 80140218,
            ["SpeakNpcId"] = 790040,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/002/C89F645A",
            },
        [80140218] = {
            ["Camera"] = "-22.451172,56.513184,131.0,0.0,4.999951,121.795105,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我想……是的。",
            ["ContentFR"] = "Je crois... oui.",
            ["DialogueId"] = 80140218,
            ["GUID"] = "C89F6484",
            ["IsBlack"] = 1,
            ["SpeakNpcId"] = 790043,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/002/C89F6484",
            },
        [80140219] = {
            ["Camera"] = "-154.623047,322.536621,183.574219,-0.0,-7.599855,-47.792412,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "哈哈……哈哈哈，这可真是太令人惊喜了！没想到我竟然还有这样一位风度翩翩、才华横溢的儿子。",
            ["ContentFR"] = "Ahah... ahahahah ! Quelle surprise ! Je ne m’attendais pas à avoir un fils si distingué et talentueux.",
            ["DialogueId"] = 80140219,
            ["FacialId"] = {
                [1] = "790041:CM_Happy01",
                },
            ["GUID"] = "C89F64AE",
            ["NextDialogue"] = 80140220,
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{790041},AnimationId{\"Talk01_Start\"},Duration{4}},\
PlayAnimation{ActorId{790041},AnimationId{\"Talk01_End\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 790041,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/002/C89F64AE",
            },
        [80140220] = {
            ["Content"] = "如果我家那两个小淘气能有你这般得体的举止和周全的礼数，我额头上的皱纹也能少几条。",
            ["ContentFR"] = "Si seulement mes deux garnements avaient votre tenue et votre politesse, mes rides seraient bien moins nombreuses.",
            ["DialogueId"] = 80140220,
            ["FacialId"] = {
                [1] = "790041:CM_Smile01",
                },
            ["GUID"] = "C89F64D8",
            ["NextDialogue"] = 80140221,
            ["SpeakNpcId"] = 790041,
            ["TalkActionId"] = {
                [1] = "790041:Confident_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/002/C89F64D8",
            },
        [80140221] = {
            ["Camera"] = "74.876953,-124.654785,174.847656,0.000015,-4.99993,100.007851,42.987816,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "您过奖了。这要感谢我的母亲，虽然我们生活清贫，但她对我的言谈举止总是要求严格。",
            ["ContentFR"] = "Vous êtes trop aimable. Je le dois à ma mère, qui, malgré nos moyens modestes, était exigeante sur ma tenue et mon comportement.",
            ["DialogueId"] = 80140221,
            ["GUID"] = "C89F6502",
            ["NextDialogue"] = 80140222,
            ["SpeakNpcId"] = 790043,
            ["TalkActionId"] = {
                [1] = "790041:Confident_End",
                [2] = "790043:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/002/C89F6502",
            },
        [80140222] = {
            ["Camera"] = "-136.898438,322.355469,164.496094,0.000016,-2.5997,-48.595303,51.072975,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我想也是，毕竟你的母亲本就如此高贵优雅。",
            ["ContentFR"] = "Cela ne m’étonne pas, votre mère était d’une noblesse et d’une élégance rares.",
            ["DialogueId"] = 80140222,
            ["FacialId"] = {
                [1] = "790041:CM_Smile01",
                },
            ["GUID"] = "C89F652C",
            ["NextDialogue"] = 80140223,
            ["SpeakNpcId"] = 790041,
            ["TalkActionId"] = {
                [1] = "790041:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/002/C89F652C",
            },
        [80140223] = {
            ["Camera"] = "-112.75,119.240234,124.5,0.000061,13.59948,50.208691,50.069786,152.512924,false,Manual,2.8",
            ["Content"] = "您还记得她？",
            ["ContentFR"] = "Vous vous souvenez d’elle ?",
            ["DialogueId"] = 80140223,
            ["FacialId"] = {
                [1] = "790043:Shock01",
                },
            ["GUID"] = "C89F6556",
            ["NextDialogue"] = 80140224,
            ["SpeakNpcId"] = 790043,
            ["TalkActionId"] = {
                [1] = "790041:Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/002/C89F6556",
            },
        [80140224] = {
            ["Camera"] = "-34.798828,193.138184,154.609375,0.0,0.799924,-54.994884,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "当然，我记得清清楚楚！她当年可是个大美人，走到哪里都有追求者众星捧月般簇拥着。",
            ["ContentFR"] = "Bien sûr, je me souviens parfaitement ! À l’époque, elle était une beauté sans pareille, entourée d’admirateurs où qu’elle aille.",
            ["DialogueId"] = 80140224,
            ["FacialId"] = {
                [1] = "790041:CM_Ahaha01",
                },
            ["FinalCamera"] = "-18.773438,170.275879,154.949219,0.0,0.799924,-54.994884,35.000008,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "C89F6580",
            ["NextDialogue"] = 80140225,
            ["SpeakNpcId"] = 790041,
            ["TalkActionId"] = {
                [1] = "790041:Agree",
                },
            ["ToFinalCameraBlendTime"] = 20,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/002/C89F6580",
            },
        [80140225] = {
            ["Content"] = "那晚有幸与她共舞一曲，我兴奋得彻夜难眠，更不用说得到她的青睐，那简直就像做梦一样！",
            ["ContentFR"] = "Cette nuit-là, j’ai eu la chance de danser avec elle. Je n’ai pas fermé l’œil de la nuit, et qu’elle ait choisi de rester avec moi, c’était comme un rêve.",
            ["DialogueId"] = 80140225,
            ["FacialId"] = {
                [1] = "790041:CM_Happy01",
                },
            ["GUID"] = "C89F65AA",
            ["NextDialogue"] = 80140226,
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{790041},AnimationId{\"Talk02_Start\"},Duration{3}},\
PlayAnimation{_delay{3},ActorId{790041},AnimationId{\"Talk02_End\"},Duration{1},_click{false}}\
}",
            ["SpeakNpcId"] = 790041,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/002/C89F65AA",
            },
        [80140226] = {
            ["Camera"] = "-411.96875,787.237305,417.886719,0.0,10.799888,-2.394898,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "她裹在深红色礼裙里，皮肤比月光下的积雪还要洁白。不知是不是因为喝了酒，她的脸颊红得厉害，就像新鲜的玫瑰那般娇艳欲滴。",
            ["ContentFR"] = "Elle portait une robe rouge sombre, sa peau était plus blanche que la neige sous la lune. Ses joues rougies par le vin brillaient comme des roses fraîches.",
            ["DialogueId"] = 80140226,
            ["FinalCamera"] = "-417.09375,664.340332,417.886719,0.000003,10.799894,-2.394897,35.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "C89F65D4",
            ["NextDialogue"] = 80140227,
            ["SpeakNpcId"] = 790041,
            ["ToFinalCameraBlendTime"] = 15,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/002/C89F65D4",
            },
        [80140227] = {
            ["Camera"] = "-45.705078,202.01123,152.460938,0.0,0.200002,-51.597355,35.000011,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "你会成为歌剧演员，想必也是因为在她身边耳濡目染吧？那时我们经常一起去看歌剧，她对剧中的唱词如数家珍，在家里也常会唱起。",
            ["ContentFR"] = "Tu es devenu chanteur d’opéra, c’est sûrement grâce à elle. Nous allions souvent au théâtre ensemble, elle connaissait chaque air par cœur et les chantait chez elle.",
            ["DialogueId"] = 80140227,
            ["GUID"] = "C89F65FE",
            ["NextDialogue"] = 80140228,
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{790041},AnimationId{\"Think_Start\"},Duration{3}},\
PlayAnimation{ActorId{790041},AnimationId{\"Think_End\"},Duration{1},_click{false}}\
}",
            ["SpeakNpcId"] = 790041,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/002/C89F65FE",
            },
        [80140228] = {
            ["Camera"] = "0.203125,58.743164,162.792969,0.000001,-1.199982,94.401482,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "是的，是的……！小时候，母亲常常在闲暇时教我唱歌。她就是我的第一位老师。",
            ["ContentFR"] = "Oui, oui... ! Quand j’étais enfant, elle me chantait souvent des chansons. Elle fut ma première professeure.",
            ["DialogueId"] = 80140228,
            ["FacialId"] = {
                [1] = "790043:Happy01",
                },
            ["GUID"] = "C89F6628",
            ["NextDialogue"] = 80140229,
            ["SpeakNpcId"] = 790043,
            ["TalkActionId"] = {
                [1] = "790043:AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/002/C89F6628",
            },
        [80140229] = {
            ["Camera"] = "-33.238281,218.664062,168.585938,0.000047,-3.400478,-59.395172,44.726002,198.823807,false,Manual,2.8",
            ["Content"] = "可不知为什么，有一天她忽然离开了我，从此再无音讯。我找了很久，也没得到她的消息。",
            ["ContentFR"] = "Pourtant, un jour, elle est partie sans un mot. Je l’ai cherchée longtemps, sans jamais la retrouver.",
            ["DialogueId"] = 80140229,
            ["FacialId"] = {
                [1] = "790041:CM_Sad01",
                },
            ["GUID"] = "C89F6652",
            ["NextDialogue"] = 80140230,
            ["SpeakNpcId"] = 790041,
            ["TalkActionId"] = {
                [1] = "790041:Sigh_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/002/C89F6652",
            },
        [80140230] = {
            ["Content"] = "抱歉，孩子……刚才我骗了你。其实正是因为失去了她，我才不愿再去看歌剧……都怪我……如果我再多找一段时间，也许她就不会……",
            ["ContentFR"] = "Pardon, mon garçon... Je t’ai menti tout à l’heure. C’est parce que je l’ai perdue que j’ai cessé d’aller au théâtre. C’est ma faute... Si j’avais cherché un peu plus longtemps, peut-être que...",
            ["DialogueId"] = 80140230,
            ["FacialId"] = {
                [1] = "790041:CM_Smile01",
                },
            ["GUID"] = "C89F667C",
            ["NextDialogue"] = 80140231,
            ["SpeakNpcId"] = 790041,
            ["TalkActionId"] = {
                [1] = "790041:Sigh_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/002/C89F667C",
            },
        [80140231] = {
            ["Camera"] = "77.599609,-172.286133,173.375,0.000016,-3.599824,98.804359,53.30518,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "从我记事起，母亲的身体就一直欠佳。您也知道，她是个心气很高的人，我猜她也许是不想让您见到她病弱的样子，才……",
            ["ContentFR"] = "Depuis mes premiers souvenirs, sa santé était fragile. Vous savez qu’elle était fière. Peut-être ne voulait-elle pas que vous la voyiez malade, alors...",
            ["DialogueId"] = 80140231,
            ["GUID"] = "C89F66A6",
            ["NextDialogue"] = 80140232,
            ["Scripts"] = "PlayAnimation{_delay{3},ActorId{790043},AnimationId{\"Explain01_Start\"},Duration{3}}",
            ["SpeakNpcId"] = 790043,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/002/C89F66A6",
            },
        [80140232] = {
            ["Camera"] = "-184.095703,349.422363,165.8125,0.000016,-3.599824,-45.596992,45.495754,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "傻姑娘，我怎么会介意这种事呢……！连一个道别的机会都不愿给我，真是太狠心了。",
            ["ContentFR"] = "Ma pauvre chérie, comment aurais-je pu m’en soucier ? Ne pas me laisser lui dire au revoir, quelle cruauté !",
            ["DialogueId"] = 80140232,
            ["FacialId"] = {
                [1] = "790041:CM_Sad01",
                },
            ["GUID"] = "C89F66D0",
            ["NextDialogue"] = 80140233,
            ["SpeakNpcId"] = 790041,
            ["TalkActionId"] = {
                [1] = "790043:Explain01_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/002/C89F66D0",
            },
        [80140233] = {
            ["Camera"] = "-200.789062,-353.42627,352.734375,0.000034,-22.800413,63.99617,31.488432,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "都是些过去的事了，请不必介怀。我很高兴您还记着她。说实话，直到刚才，我都还在担心您是否会觉得我的造访太过唐突和失礼。",
            ["ContentFR"] = "Ce sont des souvenirs lointains, ne vous en faites pas. Je suis heureux que vous gardiez son souvenir. Pour être honnête, jusqu’à tout à l’heure, je craignais que ma visite vous paraisse déplacée.",
            ["DialogueId"] = 80140233,
            ["FinalCamera"] = "-359.621094,-233.489746,352.734375,0.000046,-23.200396,43.196053,31.488432,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "C89F66FA",
            ["NextDialogue"] = 80140234,
            ["SpeakNpcId"] = 790043,
            ["TalkActionId"] = {
                [1] = "790043:Explain02_Start",
                },
            ["ToFinalCameraBlendTime"] = 30,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/002/C89F66FA",
            },
        [80140234] = {
            ["Content"] = "怎么会？有你这么优秀的孩子，我高兴还来不及！",
            ["ContentFR"] = "Comment le pourrais-je ? Avec un fils aussi exceptionnel que toi, je ne peux être que fier !",
            ["DialogueId"] = 80140234,
            ["FacialId"] = {
                [1] = "790041:CM_Smile01",
                },
            ["GUID"] = "C89F6724",
            ["NextDialogue"] = 80140235,
            ["SpeakNpcId"] = 790041,
            ["TalkActionId"] = {
                [1] = "790041:Disagree",
                [2] = "790043:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/002/C89F6724",
            },
        [80140235] = {
            ["Camera"] = "-641.517578,1081.805664,364.761719,0.0,4.999999,121.995232,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "其实格伦维尔家族一直希望能向盖雷亚剧院投资，互惠互利，这次我来就是为了和普奇夫人谈这件事。如果能有一位剧团成员穿针引线……",
            ["ContentFR"] = "En réalité, la famille Glenville a toujours voulu investir dans le Théâtre Galea, pour un bénéfice mutuel. Je suis venu parler de cela à Madame Putsch. Ce serait formidable que quelqu’un de la troupe facilite la rencontre...",
            ["DialogueId"] = 80140235,
            ["FinalCamera"] = "-768.751953,1002.334961,361.761719,0.0,4.999999,121.995232,35.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "C89F674E",
            ["NextDialogue"] = 80140236,
            ["SpeakNpcId"] = 790041,
            ["ToFinalCameraBlendTime"] = 15,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/002/C89F674E",
            },
        [80140236] = {
            ["Camera"] = "-108.212891,125.750488,144.558594,0.000007,3.800044,-23.395102,40.72089,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "说到这个，孩子，你都演过些什么呢？你这么优秀，一定都是当主演的吧？",
            ["ContentFR"] = "À propos, mon garçon, quels rôles as-tu déjà joués ? Avec ton talent, tu dois être toujours en tête d’affiche, non ?",
            ["DialogueId"] = 80140236,
            ["GUID"] = "C89F6778",
            ["NextDialogue"] = 80140237,
            ["SpeakNpcId"] = 790041,
            ["TalkActionId"] = {
                [1] = "790041:Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/002/C89F6778",
            },
        [80140237] = {
            ["Camera"] = "-54.142578,120.238281,142.078125,0.000007,9.999929,72.400467,35.000011,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我——我唱过很多角色。上一次，我作为主演出演了《雪国的孩子》。",
            ["ContentFR"] = "J-J’ai joué de nombreux rôles. La dernière fois, j’étais le rôle principal dans Né du blizzard.",
            ["DialogueId"] = 80140237,
            ["GUID"] = "C89F67A2",
            ["NextDialogue"] = 80140238,
            ["SpeakNpcId"] = 790043,
            ["TalkActionId"] = {
                [1] = "790041:Talk02_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/002/C89F67A2",
            },
        [80140238] = {
            ["Camera"] = "-230.673828,393.289062,190.988281,0.000021,-6.600032,-46.195755,43.502876,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "天哪，莫非是月初的那一场？！那时有生意场上的朋友邀请我一同观看，说那部剧很是热门，一票难求。可惜我在外省有些事要处理，没能赴约。",
            ["ContentFR"] = "Bon sang, c’était au début du mois ? Un ami du monde des affaires m’avait invité, disant que la pièce était un succès et les places introuvables. Malheureusement, j’étais en déplacement.",
            ["DialogueId"] = 80140238,
            ["FacialId"] = {
                [1] = "790041:CM_Shock01",
                },
            ["FinalCamera"] = "-177.8125,338.127441,182.257812,0.000021,-6.600032,-46.195755,43.502876,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "C89F67CC",
            ["NextDialogue"] = 80140239,
            ["SpeakNpcId"] = 790041,
            ["ToFinalCameraBlendTime"] = 25,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/002/C89F67CC",
            },
        [80140239] = {
            ["Content"] = "哎呀，真是遗憾！早知道主演就是我的孩子，我一定会推掉一切工作赴约，向那位朋友好好夸耀一番。",
            ["ContentFR"] = "Quel dommage ! Si j’avais su que le rôle principal était tenu par mon fils, j’aurais annulé tout pour venir, et je me serais vanté auprès de mon ami.",
            ["DialogueId"] = 80140239,
            ["FacialId"] = {
                [1] = "790041:CM_Smile01",
                },
            ["GUID"] = "C89F67F6",
            ["NextDialogue"] = 80140240,
            ["SpeakNpcId"] = 790041,
            ["TalkActionId"] = {
                [1] = "790041:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/002/C89F67F6",
            },
        [80140240] = {
            ["Content"] = "近期这出戏还会再演吗？",
            ["ContentFR"] = "La pièce sera-t-elle rejouée bientôt ?",
            ["DialogueId"] = 80140240,
            ["GUID"] = "C89F6820",
            ["NextDialogue"] = 80140241,
            ["SpeakNpcId"] = 790041,
            ["TalkActionId"] = {
                [1] = "790041:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/002/C89F6820",
            },
        [80140241] = {
            ["Camera"] = "-45.677734,68.809082,207.492188,0.00004,-15.200093,79.400414,42.689743,178.367188,false,Manual,3.75102",
            ["Content"] = "……近期这出戏恐怕不会再演。不过，我还会很多别的剧目，也还想多尝试新的角色。",
            ["ContentFR"] = "Je ne pense pas. Mais j’ai beaucoup d’autres rôles et j’aimerais en essayer de nouveaux.",
            ["DialogueId"] = 80140241,
            ["FacialId"] = {
                [1] = "790043:Disappoint01",
                },
            ["GUID"] = "C89F684A",
            ["NextDialogue"] = 80140242,
            ["SpeakNpcId"] = 790043,
            ["TalkActionId"] = {
                [1] = "790043:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/002/C89F684A",
            },
        [80140242] = {
            ["Camera"] = "-166.054688,340.296387,174.617188,0.000012,-4.99993,-47.595356,44.120461,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "嗯，也好，年轻人就该勇于尝试！没想到，你虽然模样像极了你的母亲，但性格倒是有几分像我啊。那么，你下一次演出是什么时候？",
            ["ContentFR"] = "Bien dit ! Un jeune doit oser. Tu ressembles à ta mère, mais tu as un peu de mon tempérament. Quand est ta prochaine représentation ?",
            ["DialogueId"] = 80140242,
            ["GUID"] = "C89F6874",
            ["NextDialogue"] = 80140243,
            ["SpeakNpcId"] = 790041,
            ["TalkActionId"] = {
                [1] = "790041:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/002/C89F6874",
            },
        [80140243] = {
            ["Camera"] = "-66.726562,115.17627,204.988281,0.000037,-18.800034,69.001747,35.000011,134.03508,false,Manual,2.8",
            ["Content"] = "其实，这就是我来找您的原因——我最近遇到了一些麻烦。",
            ["ContentFR"] = "En fait, c’est pour cela que je suis venu. J’ai des ennuis.",
            ["DialogueId"] = 80140243,
            ["GUID"] = "C89F689E",
            ["NextDialogue"] = 80140244,
            ["SpeakNpcId"] = 790043,
            ["TalkActionId"] = {
                [1] = "790043:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/002/C89F689E",
            },
        [80140244] = {
            ["Content"] = "上次演出结束的时候，我和几个闯进舞台的观众起了冲突，惊动了治安署。剧团收到了不少抗议，所以我暂时失去了上台的机会。我想，您或许有办法——",
            ["ContentFR"] = "Lors de la dernière représentation, j’ai eu un conflit avec des spectateurs qui ont envahi la scène, attirant l’attention du Bureau de la Sécurité. La troupe a reçu des plaintes, et je suis temporairement interdit de scène. Peut-être pourriez-vous m’aider...",
            ["DialogueId"] = 80140244,
            ["FacialId"] = {
                [1] = "790043:Sad01",
                },
            ["GUID"] = "C89F68C8",
            ["NextDialogue"] = 80140245,
            ["SpeakNpcId"] = 790043,
            ["TalkActionId"] = {
                [1] = "790043:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/002/C89F68C8",
            },
        [80140245] = {
            ["Camera"] = "425.240234,70.813965,156.609375,0.0,0.0,170.202316,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "哈，这世道就是这样！一旦你获得了成功，就会有眼红的老鼠闻着味窜上来，巴不得把你拽进阴沟。",
            ["ContentFR"] = "Ah, c’est ainsi dans ce monde ! Quand tu réussis, des jaloux te traquent, prêts à te faire tomber.",
            ["DialogueId"] = 80140245,
            ["FacialId"] = {
                [1] = "790041:CM_Happy01",
                },
            ["GUID"] = "C89F68F2",
            ["LookAt"] = {
                [1] = "790043:n(790041)",
                },
            ["NextDialogue"] = 80140246,
            ["Scripts"] = "MoveTo{ActorId{790041},MoveSpeed{100},TargetPoint{\"P80140245\"}}",
            ["SpeakNpcId"] = 790041,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/002/C89F68F2",
            },
        [80140246] = {
            ["Camera"] = "-359.679688,-24.628906,136.578125,0.000006,0.0,28.202164,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我做生意的这些年，明里暗里遇到的谣言和诋毁数都数不清。你放心，今后这些麻烦事我来帮你打点，你只要安心演戏就好。",
            ["ContentFR"] = "Dans mes affaires, les rumeurs et calomnies m’ont toujours suivi. Ne t’inquiète pas, je vais gérer ça. Toi, concentre-toi sur ton art.",
            ["DialogueId"] = 80140246,
            ["GUID"] = "C89F691C",
            ["LookAt"] = {
                [1] = "790043:n(790041)",
                },
            ["NextDialogue"] = 80140247,
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{790041},AnimationId{\"Confident_Start\"},Duration{3},_click{false}},\
PlayAnimation{_delay{5},ActorId{790041},AnimationId{\"Confident_End\"},Duration{1},_click{false}}\
}",
            ["SpeakNpcId"] = 790041,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/002/C89F691C",
            },
        [80140247] = {
            ["Camera"] = "-135.009766,468.290527,153.695312,0.000011,-3.200073,-74.595345,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "这样，你现在就把闹事的那几个人的名字告诉我。我要让这冰湖城的人都知道，敢动我莫里斯的孩子，就等着吃苦头吧！",
            ["ContentFR"] = "Donne-moi les noms de ceux qui ont causé des troubles. Je vais faire savoir à tout Givrelac que s’en prendre au fils de Morris Glenville, c’est chercher des ennuis !",
            ["DialogueId"] = 80140247,
            ["FacialId"] = {
                [1] = "790041:CM_Smile01",
                },
            ["GUID"] = "C89F6946",
            ["NextDialogue"] = 80140248,
            ["Scripts"] = "SEQ{\
TurnTo{_click{false},TurnToDescription{\"790041:n(790043)\"}},\
PlayAnimation{_delay{3},ActorId{790041},AnimationId{\"Angry01_Start\"},Duration{3},_click{false}}\
}",
            ["SpeakNpcId"] = 790041,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/002/C89F6946",
            },
        [80140248] = {
            ["Camera"] = "-309.541016,-12.723145,143.96875,0.000011,0.0,31.003548,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "谢谢您，格伦维尔先生！不过，您不必如此费心，我只要能继续表演就够了。",
            ["ContentFR"] = "Merci, Monsieur Glenville ! Mais je n’ai pas besoin de tout ça, je veux juste continuer à jouer.",
            ["DialogueId"] = 80140248,
            ["FacialId"] = {
                [1] = "790043:Happy01",
                },
            ["GUID"] = "C89F6970",
            ["LookAt"] = {
                [1] = "790043:n(790041)",
                },
            ["NextDialogue"] = 80140249,
            ["SpeakNpcId"] = 790043,
            ["TalkActionId"] = {
                [1] = "790041:Angry01_End",
                [2] = "790043:AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/002/C89F6970",
            },
        [80140249] = {
            ["Camera"] = "-112.6875,492.869141,176.664062,0.000012,-4.199924,-79.79612,54.218994,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "哈哈，你应该叫我“父亲”才是。以后我们就是一家人了。",
            ["ContentFR"] = "Haha, tu devrais m’appeler « Père » maintenant. Nous sommes une famille.",
            ["DialogueId"] = 80140249,
            ["FacialId"] = {
                [1] = "790041:CM_Smile01",
                },
            ["GUID"] = "C89F699A",
            ["NextDialogue"] = 80140250,
            ["SpeakNpcId"] = 790041,
            ["TalkActionId"] = {
                [1] = "790041:Confident_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/002/C89F699A",
            },
        [80140250] = {
            ["Content"] = "来，别站着了，坐下慢慢说……你看，你这孩子，怎么在屋里还戴着帽子？脱下来交给管家吧。",
            ["ContentFR"] = "Viens, assieds-toi, raconte-moi tout... Pourquoi portes-tu encore ton chapeau à l’intérieur ? Enlève-le, donne-le au majordome.",
            ["DialogueId"] = 80140250,
            ["GUID"] = "C89F69C4",
            ["NextDialogue"] = 80140251,
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{790041},AnimationId{\"Confident_End\"},Duration{1},_click{false}},\
PlayAnimation{_delay{2},ActorId{790041},AnimationId{\"Talk02_Start\"},Duration{3},_click{false}}\
}",
            ["SpeakNpcId"] = 790041,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/002/C89F69C4",
            },
        [80140251] = {
            ["Camera"] = "-250.220703,64.174316,162.351562,0.000014,-0.199858,36.001259,65.759476,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "没关系，我自己拿着就好。",
            ["ContentFR"] = "Ce n’est rien, je vais le garder avec moi.",
            ["DialogueId"] = 80140251,
            ["GUID"] = "C89F69EE",
            ["SpeakNpcId"] = 790043,
            ["TalkActionId"] = {
                [1] = "790043:DisagreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/002/C89F69EE",
            },
        [80140252] = {
            ["Camera"] = "-150.300781,485.039551,180.503906,0.000002,-5.000094,-75.590591,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "等等——你、你头上……这是……你是卡戎？！",
            ["ContentFR"] = "Attends... sur ta tête... ces cornes... Tu es un Charon ?!",
            ["DialogueId"] = 80140252,
            ["FacialId"] = {
                [1] = "790041:CM_Shock01",
                },
            ["GUID"] = "C89F6A18",
            ["NextDialogue"] = 80140253,
            ["Scripts"] = "CameraMoveTo{_delay{2},TargetPosition{\"-100.347656,99.807129,165.207031,0.000004,-3.39987,60.403275,35.000011,157.778702,false,Manual,2.8\"},duration{0}}",
            ["SpeakNpcId"] = 790041,
            ["TalkActionId"] = {
                [1] = "790041:Shock_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/002/C89F6A18",
            },
        [80140253] = {
            ["Content"] = "嗯……？是的，您不记得了吗，我的母亲赫泽蕾德就是一位卡戎之民——",
            ["ContentFR"] = "Oui... Vous ne vous souvenez pas ? Ma mère, Herzeleide, était une Charon...",
            ["DialogueId"] = 80140253,
            ["FacialId"] = {
                [1] = "790036:Smile01",
                },
            ["GUID"] = "C89F6A42",
            ["NextDialogue"] = 80140254,
            ["SpeakNpcId"] = 790043,
            ["TalkActionId"] = {
                [1] = "790041:Shock_End",
                [2] = "790036:Explain02_Start",
                },
            ["TurnTo"] = {
                [1] = "790042:n(790041)",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/002/C89F6A42",
            },
        [80140254] = {
            ["Camera"] = "-99.941406,228.310547,146.640625,0.000004,0.0,-78.789078,35.000011,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "好哇，好哇！你这家伙，真是个好“演员”！看你打扮得衣冠楚楚，我才好心请你进来，听你说了这许多废话，没想到你竟是个骗子！",
            ["ContentFR"] = "Bien sûr, bien sûr ! Quel \"comédien\" tu fais ! Avec ta tenue impeccable, ton ton doucereux... Je t’ai accueilli, j’ai écouté toutes tes balivernes, et au final, tu n’es qu’un imposteur !",
            ["DialogueId"] = 80140254,
            ["FacialId"] = {
                [1] = "790041:CM_Angry01",
                },
            ["GUID"] = "C89F6A6C",
            ["NextDialogue"] = 80140255,
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{790041},AnimationId{\"Confident_Start\"},Duration{3},_click{false}},\
PlayAnimation{ActorId{790041},AnimationId{\"Agree\"},Duration{1},_click{false}}\
}",
            ["SpeakNpcId"] = 790041,
            ["TalkActionId"] = {
                [1] = "790036:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/002/C89F6A6C",
            },
        [80140255] = {
            ["Camera"] = "-110.15625,89.980957,151.796875,0.000004,0.0,59.005974,35.000011,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "不，我没有骗您！",
            ["ContentFR"] = "Non, je ne vous ai pas menti !",
            ["DialogueId"] = 80140255,
            ["FacialId"] = {
                [1] = "790036:Shock01",
                },
            ["GUID"] = "C89F6A96",
            ["NextDialogue"] = 80140256,
            ["SpeakNpcId"] = 790043,
            ["TalkActionId"] = {
                [1] = "790036:Disagree",
                [2] = "790041:Confident_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/002/C89F6A96",
            },
        [80140256] = {
            ["Camera"] = "-171.984375,506.293945,146.203125,0.000005,-1.800076,-72.188232,38.476471,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "胡扯！卡戎女人怎配为我生儿育女！你——你到底是什么人，打的什么算盘？",
            ["ContentFR"] = "Imbécillités ! Une femme Charon porter mon enfant ? Quelle absurdité ! Qui es-tu vraiment ? Quel est ton but ?",
            ["DialogueId"] = 80140256,
            ["GUID"] = "C89F6AC0",
            ["NextDialogue"] = 80140257,
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{790041},AnimationId{\"Angry01_Start\"},Duration{2},_click{false}},\
PlayAnimation{ActorId{790041},AnimationId{\"Angry01_End\"},Duration{1},_click{false}}\
}",
            ["SpeakNpcId"] = 790041,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/002/C89F6AC0",
            },
        [80140257] = {
            ["Content"] = "我知道了……你准是《冰湖城早报》那个老秃头派来的！我的对头给他塞了钱，他就总是杜撰那些捕风捉影的见鬼丑闻。",
            ["ContentFR"] = "Je vois clair dans ton jeu... Tu viens sûrement de l’Écho de Givrelac, envoyé par ce vieux chauve ! Mes rivaux le paient pour inventer des rumeurs et me salir avec des ragots grotesques.",
            ["DialogueId"] = 80140257,
            ["GUID"] = "C89F6AEA",
            ["NextDialogue"] = 80140258,
            ["Scripts"] = "SEQ{\
TurnTo{_click{false},TurnToDescription{\"790041:p(100)\"}},\
PlayAnimation{_delay{1},ActorId{790041},AnimationId{\"Confident_Start\"},Duration{3},_click{false}}\
}",
            ["SpeakNpcId"] = 790041,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/002/C89F6AEA",
            },
        [80140258] = {
            ["Camera"] = "-125.214844,146.510742,141.648438,0.00002,6.999755,41.210266,35.000011,133.743912,false,Manual,2.8",
            ["Content"] = "我——我不是……我说的都是真话！您刚才不是还说——说您记得我母亲的事，记得你们有多么相爱吗？",
            ["ContentFR"] = " J-Je ne suis pas de là-bas... Tout ce que j’ai dit est vrai ! Vous avez dit tout à l’heure... que vous vous souveniez de ma mère, de l’amour que vous aviez pour elle...",
            ["DialogueId"] = 80140258,
            ["FacialId"] = {
                [1] = "790036:Sad01",
                },
            ["GUID"] = "C89F6B14",
            ["NextDialogue"] = 80140259,
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{790036},AnimationId{\"Disagree\"},Duration{1},_click{false}},\
PlayAnimation{_delay{1},ActorId{790036},AnimationId{\"Talk02_Start\"},Duration{2},_click{false}}\
}",
            ["SpeakNpcId"] = 790043,
            ["TalkActionId"] = {
                [1] = "790041:Confident_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/002/C89F6B14",
            },
        [80140259] = {
            ["Camera"] = "-121.521484,456.680664,136.171875,0.0,0.0,-75.5924,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "混账东西，二十年前我莫里斯交往的女人那么多，谁知道你说的哪个？！",
            ["ContentFR"] = "Idioties ! Vingt ans plus tôt, des femmes, j’en ai connu un paquet ! Comment veux-tu que je sache de laquelle tu parles ?",
            ["DialogueId"] = 80140259,
            ["GUID"] = "C89F6B3E",
            ["NextDialogue"] = 80140260,
            ["SpeakNpcId"] = 790041,
            ["TalkActionId"] = {
                [1] = "790036:Talk02_End",
                },
            ["TurnTo"] = {
                [1] = "790041:p(-100)",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/002/C89F6B3E",
            },
        [80140260] = {
            ["Camera"] = "-516.966797,271.29248,136.0,0.0,0.0,-17.59621,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "咳。老爷，演出快要开始了。",
            ["ContentFR"] = "Hum. Monsieur, le spectacle va commencer.",
            ["DialogueId"] = 80140260,
            ["GUID"] = "C89F6B68",
            ["NextDialogue"] = 80140261,
            ["SpeakNpcId"] = 790042,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/002/C89F6B68",
            },
        [80140261] = {
            ["Camera"] = "-121.521484,456.680664,136.171875,0.0,0.0,-75.5924,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "……哼。这位不知从哪儿冒出来的先生，我可没说过那些胡话，有管家为证，想必是您听错了。",
            ["ContentFR"] = "... Pff. Monsieur-le-venu-de-nulle-part, je n’ai jamais tenu de tels propos, mon majordome peut en témoigner. Vous avez dû mal entendre.",
            ["DialogueId"] = 80140261,
            ["FacialId"] = {
                [1] = "790036:None",
                },
            ["GUID"] = "C89F6B92",
            ["NextDialogue"] = 80140262,
            ["Scripts"] = "PlayAnimation{_delay{2},ActorId{790041},AnimationId{\"Disagree\"},Duration{1},_click{false}}",
            ["SpeakNpcId"] = 790041,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/002/C89F6B92",
            },
        [80140262] = {
            ["Camera"] = "-130.255859,176.895508,152.324219,0.000013,0.00002,-64.789436,35.000011,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我听闻卡戎之民出现听觉失灵是个不祥的征兆，您要多多关心自己的身体才是。现在，请您离开我的包厢，否则我就要叫安保人员了。",
            ["ContentFR"] = "D’ailleurs, il paraît que les Charons qui perdent l’ouïe, c’est un mauvais présage. Vous devriez faire attention à votre santé. Maintenant, veuillez quitter ma loge, ou j’appelle la sécurité.",
            ["DialogueId"] = 80140262,
            ["GUID"] = "C89F6BBC",
            ["NextDialogue"] = 80140263,
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{790041},AnimationId{\"Think_Start\"},Duration{3},_click{false}},\
PlayAnimation{_delay{2},ActorId{790041},AnimationId{\"Think_End\"},Duration{1},_click{false}}\
}",
            ["SpeakNpcId"] = 790041,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/002/C89F6BBC",
            },
        [80140263] = {
            ["Camera"] = "-338.359375,215.333984,136.617188,0.000013,-0.80002,-26.987488,35.000011,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "请恕我不送，眼下我得抓紧时间教育一下我家的仆人，让他们以后别再和来路不明的东西搭话。",
            ["ContentFR"] = "Je ne vous raccompagne pas, j’ai mieux à faire, expliquer à mes domestiques qu’ils doivent éviter de discuter avec n’importe quoi venu d’on ne sait où.",
            ["DialogueId"] = 80140263,
            ["FacialId"] = {
                [1] = "790042:CM_Sad01",
                },
            ["GUID"] = "C89F6BE6",
            ["NextDialogue"] = 80140264,
            ["SpeakNpcId"] = 790041,
            ["TurnTo"] = {
                [1] = "790041:n(790042)",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/002/C89F6BE6",
            },
        [80140264] = {
            ["Camera"] = "-201.84375,-98.977539,157.707031,0.000015,-3.000024,56.802822,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "“东西”？",
            ["ContentFR"] = "« N’importe quoi »... ?",
            ["DialogueId"] = 80140264,
            ["FacialId"] = {
                [1] = "790036:Shock01",
                },
            ["FinalCamera"] = "-235.755859,-150.816406,160.089844,0.000015,-3.000024,56.802822,35.000008,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "C89F6C10",
            ["NextDialogue"] = 80140265,
            ["SpeakNpcId"] = 790043,
            ["ToFinalCameraBlendTime"] = 15,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/002/C89F6C10",
            },
        [80140265] = {
            ["Content"] = "……我明白了。很抱歉占用了您的时间，我这就离开。",
            ["ContentFR"] = "... Je comprends. Je suis désolé d’avoir pris de votre temps. Je m’en vais.",
            ["DialogueId"] = 80140265,
            ["FacialId"] = {
                [1] = "790036:Disappoint01",
                },
            ["GUID"] = "C89F6C3A",
            ["SpeakNpcId"] = 790043,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/002/C89F6C3A",
            },
        [80140266] = {
            ["Camera"] = "232.730469,-289.320068,155.523438,0.000156,-1.001039,118.20211,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "哈哈……",
            ["ContentFR"] = "Ah... ahah...",
            ["DialogueId"] = 80140266,
            ["FinalCamera"] = "176.0,-289.320068,155.523438,0.000156,-1.001039,118.202103,35.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "C89F6C64",
            ["NextDialogue"] = 80140267,
            ["SpeakNpcId"] = 790043,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/002/C89F6C64",
            },
        [80140267] = {
            ["Content"] = "真是一出滑稽戏。",
            ["ContentFR"] = "Quelle farce pathétique.",
            ["DialogueId"] = 80140267,
            ["GUID"] = "C89F6C8E",
            ["SpeakNpcId"] = 790043,
            ["TalkActionId"] = {
                [1] = "790043:DisagreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/002/C89F6C8E",
            },
        [80140268] = {
            ["Content"] = "我是绝望的赌徒，用力掷出最后的筹码。",
            ["ContentFR"] = "Je suis un joueur désespéré, lançant ma dernière mise de toutes mes forces.",
            ["DialogueId"] = 80140268,
            ["Duration"] = 4,
            ["GUID"] = "C89F6CB8",
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/002/C89F6CB8",
            },
        [80140269] = {
            ["Content"] = "然后，一无所有。",
            ["ContentFR"] = "Et à la fin... il ne me reste rien.",
            ["DialogueId"] = 80140269,
            ["Duration"] = 3,
            ["GUID"] = "C89F6CE2",
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/002/C89F6CE2",
            },
        [80140301] = {
            ["Content"] = "你是谁？",
            ["ContentFR"] = "Qui es-tu ?",
            ["DialogueId"] = 80140301,
            ["Duration"] = 3,
            ["GUID"] = "C89F7222",
            ["NextDialogue"] = 80140302,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/003/C89F7222",
            },
        [80140302] = {
            ["Content"] = "你想说什么？",
            ["ContentFR"] = "Que veux-tu dire ?",
            ["DialogueId"] = 80140302,
            ["Duration"] = 3,
            ["GUID"] = "C89F724C",
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/003/C89F724C",
            },
        [80140303] = {
            ["Camera"] = "-94.440186,-1.343018,87.057495,0.000437,68.604141,-1.179963,17.953867,34.943119,false,Manual,2.8",
            ["Content"] = "嗯？你在说话吗……？你说什么？",
            ["ContentFR"] = "Hmm ? Tu essaies de parler ? Qu’est-ce que tu dis... ?",
            ["DialogueId"] = 80140303,
            ["FinalCamera"] = "-94.440186,-1.343018,87.057495,0.000437,68.604141,-1.179932,17.953867,56.566151,false,Manual,2.8",
            ["GUID"] = "C89F7276",
            ["NextDialogue"] = 80140304,
            ["SpeakNpcId"] = 100336,
            ["SpeakNpcName"] = "UI_Npc_Name_XiaoLianjin",
            ["ToFinalCameraBlendTime"] = 3,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/003/C89F7276",
            },
        [80140304] = {
            ["Camera"] = "-94.440186,-1.343018,87.057495,0.000437,68.604141,-1.179932,17.953867,56.566151,false,Manual,2.8",
            ["Content"] = "这……哪……",
            ["ContentFR"] = "Qu... Où...",
            ["DialogueId"] = 80140304,
            ["FinalCamera"] = "-94.440186,-1.264404,77.296875,0.000422,54.202248,20.019747,17.953863,23.544985,false,Manual,2.8",
            ["GUID"] = "C89F72A0",
            ["NextDialogue"] = 80140305,
            ["SpeakNpcId"] = 790036,
            ["ToFinalCameraBlendTime"] = 4,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/003/C89F72A0",
            },
        [80140305] = {
            ["Camera"] = "-94.440186,-1.264404,77.296875,0.000422,54.202248,20.019747,17.953863,23.544985,false,Manual,2.8",
            ["Content"] = "我……是……怎……",
            ["ContentFR"] = "Qu’est-ce... qui m’est... arrivé... ?",
            ["DialogueId"] = 80140305,
            ["FinalCamera"] = "-94.440186,-1.264404,77.296875,0.000428,54.601673,1.42055,17.953863,46.621048,false,Manual,2.8",
            ["GUID"] = "C89F72CA",
            ["NextDialogue"] = 80140306,
            ["SpeakNpcId"] = 790036,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/003/C89F72CA",
            },
        [80140306] = {
            ["Content"] = "什么？我听不清。",
            ["ContentFR"] = "Hein ? J’ai rien compris.",
            ["DialogueId"] = 80140306,
            ["GUID"] = "C89F72F4",
            ["NextDialogue"] = 80140307,
            ["SpeakNpcId"] = 100336,
            ["SpeakNpcName"] = "UI_Npc_Name_XiaoLianjin",
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/003/C89F72F4",
            },
        [80140307] = {
            ["Camera"] = "-94.440186,-1.264404,77.296875,0.000428,54.601673,1.42055,17.953863,46.621048,false,Manual,2.8",
            ["Content"] = "这是……哪里？我这是怎么了……？",
            ["ContentFR"] = "Où est-ce que je suis... ? Qu’est-ce que vous m’avez fait... ?",
            ["DialogueId"] = 80140307,
            ["FinalCamera"] = "-94.440186,-1.264404,77.296875,0.000423,39.199577,-24.999739,17.953863,46.621048,false,Manual,2.8",
            ["GUID"] = "C89F731E",
            ["NextDialogue"] = 80140308,
            ["SpeakNpcId"] = 790036,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/003/C89F731E",
            },
        [80140308] = {
            ["Camera"] = "-94.440186,-1.264404,77.296875,0.000423,39.199577,-24.999739,17.953863,46.621048,false,Manual,2.8",
            ["Content"] = "唔，这里是第六军团的实验室……",
            ["ContentFR"] = "Euh… Ici, c’est le laboratoire de la VIᵉ Légion...",
            ["DialogueId"] = 80140308,
            ["FinalCamera"] = "-94.440186,-1.264404,77.296875,0.000424,39.199574,-24.99971,17.953863,141.187195,false,Manual,2.8",
            ["GUID"] = "C89F7348",
            ["NextDialogue"] = 80140309,
            ["SpeakNpcId"] = 100336,
            ["SpeakNpcName"] = "UI_Npc_Name_XiaoLianjin",
            ["ToFinalCameraBlendTime"] = 3,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/003/C89F7348",
            },
        [80140309] = {
            ["Camera"] = "-94.440186,-1.264404,77.296875,0.000424,39.199574,-24.99971,17.953863,141.187195,false,Manual,2.8",
            ["Content"] = "第六军团……是的，没错，我通过了考核——可为什么我会在实验室？",
            ["ContentFR"] = "La VIᵉ... Légion... Oui, c’est vrai... J’avais réussi les tests... Alors pourquoi... pourquoi suis-je ici... dans un laboratoire... ?",
            ["DialogueId"] = 80140309,
            ["FinalCamera"] = "-94.440186,-1.264404,77.296875,0.000432,50.799896,-6.183147,17.953863,125.0,false,DoNotOverride,2.8",
            ["GUID"] = "C89F7372",
            ["NextDialogue"] = 80140310,
            ["SpeakNpcId"] = 790036,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/003/C89F7372",
            },
        [80140310] = {
            ["Camera"] = "-94.440186,-1.264404,77.296875,0.000432,50.799896,-6.183147,17.953863,125.0,false,DoNotOverride,2.8",
            ["Content"] = "……好难受……你们做了什么？",
            ["ContentFR"] = "... Je me sens si mal... Qu’est-ce que vous m’avez fait... ?",
            ["DialogueId"] = 80140310,
            ["FinalCamera"] = "-94.440186,-1.264404,77.296875,0.000404,36.399063,-23.382465,17.953863,125.0,false,DoNotOverride,2.8",
            ["GUID"] = "C89F739C",
            ["NextDialogue"] = 80140311,
            ["SpeakNpcId"] = 790036,
            ["ToFinalCameraBlendTime"] = 3,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/003/C89F739C",
            },
        [80140311] = {
            ["Content"] = "你……你忘了吗，这是你第三次问这个问题了。你接受了炼金术的改造。",
            ["ContentFR"] = "Tu... tu t’en souviens pas ? C’est la troisième fois que tu me poses la question. Tu as subi une transformation alchimique.",
            ["DialogueId"] = 80140311,
            ["GUID"] = "C89F73C6",
            ["NextDialogue"] = 80140312,
            ["SpeakNpcId"] = 100336,
            ["SpeakNpcName"] = "UI_Npc_Name_XiaoLianjin",
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/003/C89F73C6",
            },
        [80140312] = {
            ["Content"] = "改造？",
            ["ContentFR"] = "Une... transformation... ?",
            ["DialogueId"] = 80140312,
            ["GUID"] = "C89F73F0",
            ["NextDialogue"] = 80140313,
            ["SpeakNpcId"] = 790036,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/003/C89F73F0",
            },
        [80140313] = {
            ["Camera"] = "-94.440186,-1.264404,77.296875,0.000404,36.399063,-23.382465,17.953863,125.0,false,DoNotOverride,2.8",
            ["Content"] = "这是……什么东西……",
            ["ContentFR"] = "Qu’est-ce que c’est que ça... ?",
            ["DialogueId"] = 80140313,
            ["FinalCamera"] = "-94.440186,-1.264404,77.296875,0.000294,59.993927,40.819923,17.953863,125.0,false,DoNotOverride,2.8",
            ["GUID"] = "C89F741A",
            ["NextDialogue"] = 80140314,
            ["SpeakNpcId"] = 790036,
            ["TalkActionId"] = {
                [1] = "790058:Tuosi02_Threat_Start",
                },
            ["ToFinalCameraBlendTime"] = 0.8,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/003/C89F741A",
            },
        [80140314] = {
            ["Content"] = "……我的手？",
            ["ContentFR"] = "... Ma main ?",
            ["DialogueId"] = 80140314,
            ["GUID"] = "C89F7444",
            ["NextDialogue"] = 80140315,
            ["SpeakNpcId"] = 790036,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/003/C89F7444",
            },
        [80140315] = {
            ["Content"] = "这怪物一样的爪子……是……我的手？",
            ["ContentFR"] = "Cette... griffe de monstre... C’est... ma main... ?",
            ["DialogueId"] = 80140315,
            ["GUID"] = "C89F746E",
            ["NextDialogue"] = 80140316,
            ["SpeakNpcId"] = 790036,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/003/C89F746E",
            },
        [80140316] = {
            ["Content"] = "其、其实这样也挺好的，毕竟你的身体变得更强了啊。对你们卡戎之民来说，有机会以这种方式报效帝国，是无上的……恩赐……嗯。",
            ["ContentFR"] = "M-Mais en vrai, c’est pas si mal ! Ton corps est devenu plus fort, non ? Pour vous autres, les Charons... avoir l’honneur de servir l’Empire de cette manière... C’est une vraie bénédiction... enfin... je crois...",
            ["DialogueId"] = 80140316,
            ["GUID"] = "C89F7498",
            ["NextDialogue"] = 80140317,
            ["SpeakNpcId"] = 100336,
            ["SpeakNpcName"] = "UI_Npc_Name_XiaoLianjin",
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/003/C89F7498",
            },
        [80140317] = {
            ["Content"] = "而且——而且你很幸运，要知道，之前的很多改造体都没有熬过移植的程序……",
            ["ContentFR"] = "Et... et tu sais, t’as eu de la chance ! Beaucoup de sujets avant toi n’ont même pas survécu au processus...",
            ["DialogueId"] = 80140317,
            ["GUID"] = "C89F74C2",
            ["NextDialogue"] = 80140318,
            ["SpeakNpcId"] = 100336,
            ["SpeakNpcName"] = "UI_Npc_Name_XiaoLianjin",
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/003/C89F74C2",
            },
        [80140318] = {
            ["Content"] = "“幸运”？你用了这个词吗？",
            ["ContentFR"] = "« De la chance » ? Tu viens de dire ça ?",
            ["DialogueId"] = 80140318,
            ["GUID"] = "C89F74EC",
            ["NextDialogue"] = 80140319,
            ["SpeakNpcId"] = 790036,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/003/C89F74EC",
            },
        [80140319] = {
            ["Camera"] = "-94.440186,-1.264404,77.296875,0.000294,59.993927,40.819923,17.953863,125.0,false,DoNotOverride,2.8",
            ["Content"] = "你觉得——这是幸运？",
            ["ContentFR"] = "Tu crois... que c’est ça, la chance ?",
            ["DialogueId"] = 80140319,
            ["FinalCamera"] = "-94.440186,-1.264404,77.296875,0.000404,36.399063,-23.382465,17.953863,125.0,false,DoNotOverride,2.8",
            ["GUID"] = "C89F7516",
            ["NextDialogue"] = 80140320,
            ["SpeakNpcId"] = 790036,
            ["TalkActionId"] = {
                [1] = "790058:Tuosi02_Threat_End",
                },
            ["ToFinalCameraBlendTime"] = 0.5,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/003/C89F7516",
            },
        [80140320] = {
            ["Content"] = "……抱歉。",
            ["ContentFR"] = "... Désolé.",
            ["DialogueId"] = 80140320,
            ["GUID"] = "C89F7540",
            ["SpeakNpcId"] = 100336,
            ["SpeakNpcName"] = "UI_Npc_Name_XiaoLianjin",
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/003/C89F7540",
            },
        [80140321] = {
            ["Content"] = "（在那之后……不知又过了多少天。）",
            ["ContentFR"] = "Et après ça... je ne sais pas combien de jours ont passé.",
            ["DialogueId"] = 80140321,
            ["GUID"] = "C89F756A",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 80140322,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/003/C89F756A",
            },
        [80140322] = {
            ["Content"] = "（太过漫长的黑暗中，时间已经成了无意义的数字。）",
            ["ContentFR"] = "Dans une obscurité si longue, le temps n’est plus qu’un nombre vide.",
            ["DialogueId"] = 80140322,
            ["GUID"] = "C89F7594",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 80140323,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/003/C89F7594",
            },
        [80140323] = {
            ["Camera"] = "-94.440186,-1.264404,77.296875,0.000406,36.399044,-23.382372,14.951323,16.665867,false,Manual,2.8",
            ["Content"] = "嗯……血液中的镇定剂浓度下降了……要不要再加点呢？",
            ["ContentFR"] = "Hmm... La concentration du sédatif baisse... Je devrais peut-être en rajouter ?",
            ["DialogueId"] = 80140323,
            ["FinalCamera"] = "-94.440186,-1.264404,77.296875,0.000406,36.399044,-23.382372,14.951323,137.079605,false,Manual,2.8",
            ["GUID"] = "C89F75BE",
            ["NextDialogue"] = 80140324,
            ["SpeakNpcId"] = 100336,
            ["SpeakNpcName"] = "UI_Npc_Name_XiaoLianjin",
            ["ToFinalCameraBlendTime"] = 1,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/003/C89F75BE",
            },
        [80140324] = {
            ["Content"] = "又是……你。",
            ["ContentFR"] = "C’est encore... toi.",
            ["DialogueId"] = 80140324,
            ["GUID"] = "C89F75E8",
            ["NextDialogue"] = 80140325,
            ["SpeakNpcId"] = 790036,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/003/C89F75E8",
            },
        [80140325] = {
            ["Content"] = "啊……！你又醒了？",
            ["ContentFR"] = "Ah... ! Tu es réveillé... encore ?",
            ["DialogueId"] = 80140325,
            ["GUID"] = "C89F7612",
            ["NextDialogue"] = 80140326,
            ["SpeakNpcId"] = 100336,
            ["SpeakNpcName"] = "UI_Npc_Name_XiaoLianjin",
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/003/C89F7612",
            },
        [80140326] = {
            ["Camera"] = "-94.440186,-1.264404,77.296875,0.000404,36.399063,-23.382465,14.951323,125.0,false,DoNotOverride,2.8",
            ["Content"] = "你在做什么？镇定剂浓度怎么会这么低？",
            ["ContentFR"] = "Qu’est-ce que tu fabriques ? Pourquoi le sédatif est si bas ?",
            ["DialogueId"] = 80140326,
            ["FinalCamera"] = "-94.440186,-1.264404,77.296875,0.000414,41.996418,18.421019,14.951323,125.0,false,DoNotOverride,2.8",
            ["GUID"] = "C89F763C",
            ["LookAt"] = {
                [1] = "100336:n(100337)",
                },
            ["NextDialogue"] = 80140327,
            ["Scripts"] = "MoveTo{ActorId{100337},MoveSpeed{60},TargetPoint{\"Move\"}}",
            ["SpeakNpcId"] = 100337,
            ["SpeakNpcName"] = "UI_Npc_Name_LaoLianjin",
            ["ToFinalCameraBlendTime"] = 2,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/003/C89F763C",
            },
        [80140327] = {
            ["Content"] = "抱、抱歉，老师，我这就追加！",
            ["ContentFR"] = "D-Désolé, professeur ! Je vais corriger ça !",
            ["DialogueId"] = 80140327,
            ["GUID"] = "C89F7666",
            ["NextDialogue"] = 80140328,
            ["SpeakNpcId"] = 100336,
            ["SpeakNpcName"] = "UI_Npc_Name_XiaoLianjin",
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/003/C89F7666",
            },
        [80140328] = {
            ["Camera"] = "-94.440186,-1.264404,77.296875,0.000414,41.996418,18.421019,14.951323,125.0,false,DoNotOverride,2.8",
            ["Content"] = "我还能……",
            ["ContentFR"] = "Est-ce que je pourrais... encore...",
            ["DialogueId"] = 80140328,
            ["FinalCamera"] = "-94.440186,-1.264404,77.296875,0.000426,42.395412,-2.778932,14.951323,125.0,false,DoNotOverride,2.8",
            ["GUID"] = "C89F7690",
            ["NextDialogue"] = 80140329,
            ["SpeakNpcId"] = 790036,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/003/C89F7690",
            },
        [80140329] = {
            ["Content"] = "嗯？这东西在嘀咕什么？",
            ["ContentFR"] = "Hmm ? Ce truc marmonne quoi, là ?",
            ["DialogueId"] = 80140329,
            ["GUID"] = "C89F76BA",
            ["LookAt"] = {
                [1] = "100337:n(790058)",
                [2] = "100336:n(790058)",
                },
            ["NextDialogue"] = 80140330,
            ["SpeakNpcId"] = 100337,
            ["SpeakNpcName"] = "UI_Npc_Name_LaoLianjin",
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/003/C89F76BA",
            },
        [80140330] = {
            ["Content"] = "我还能变回原本的模样吗？",
            ["ContentFR"] = "Est-ce que je pourrais... redevenir... comme avant ?",
            ["DialogueId"] = 80140330,
            ["GUID"] = "C89F76E4",
            ["NextDialogue"] = 80140331,
            ["SpeakNpcId"] = 790036,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/003/C89F76E4",
            },
        [80140331] = {
            ["Content"] = "哈哈……哈哈哈哈！做什么白日梦呢？我们也没动你的脑子啊？是它被火焰烧坏了，还是你本来就这么蠢？",
            ["ContentFR"] = "Ahah... AHAHAH ! Redevenir comme avant ? On n’a même pas touché à ton cerveau, c’est le feu qui t’a cramé la cervelle, ou t’étais déjà débile à la base ?",
            ["DialogueId"] = 80140331,
            ["GUID"] = "C89F770E",
            ["NextDialogue"] = 80140332,
            ["SpeakNpcId"] = 100337,
            ["SpeakNpcName"] = "UI_Npc_Name_LaoLianjin",
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/003/C89F770E",
            },
        [80140332] = {
            ["Content"] = "我们要的是一只怪物，一具容器，一把趁手的刀，唯独不是你自己。我们怎么会把你变回去？",
            ["ContentFR"] = "Ce qu’on voulait, c’était un monstre, un récipient, une arme fiable, mais sûrement pas toi. Comment pourrais-tu croire qu’on allait te rendre ta forme d’avant ?",
            ["DialogueId"] = 80140332,
            ["GUID"] = "C89F7738",
            ["NextDialogue"] = 80140333,
            ["SpeakNpcId"] = 100337,
            ["SpeakNpcName"] = "UI_Npc_Name_LaoLianjin",
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/003/C89F7738",
            },
        [80140333] = {
            ["Content"] = "为什么——为什么？！",
            ["ContentFR"] = "Pourquoi... POURQUOI ?!",
            ["DialogueId"] = 80140333,
            ["GUID"] = "C89F7762",
            ["NextDialogue"] = 80140334,
            ["SpeakNpcId"] = 790036,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/003/C89F7762",
            },
        [80140334] = {
            ["Content"] = "“为什么”？",
            ["ContentFR"] = "« Pourquoi » ?",
            ["DialogueId"] = 80140334,
            ["GUID"] = "C89F778C",
            ["NextDialogue"] = 80140335,
            ["SpeakNpcId"] = 100337,
            ["SpeakNpcName"] = "UI_Npc_Name_LaoLianjin",
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/003/C89F778C",
            },
        [80140335] = {
            ["Content"] = "你会对脚下的蚂蚁解释你为什么要踩扁它吗？你会对嘴里的樱桃解释你为什么要嚼碎它吗？",
            ["ContentFR"] = "Est-ce que tu t’excuses quand tu écrases une fourmi ? Tu expliques à une cerise pourquoi tu la broies entre tes dents ?",
            ["DialogueId"] = 80140335,
            ["GUID"] = "C89F77B6",
            ["NextDialogue"] = 80140336,
            ["SpeakNpcId"] = 100337,
            ["SpeakNpcName"] = "UI_Npc_Name_LaoLianjin",
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/003/C89F77B6",
            },
        [80140336] = {
            ["Content"] = "哦，抱歉，我忘了——像你这样卑贱的东西应该一辈子都没尝过樱桃的味道吧。",
            ["ContentFR"] = "Ah, pardon... J’avais oublié. Un rebut comme toi a sans doute jamais goûté une cerise de sa vie.",
            ["DialogueId"] = 80140336,
            ["GUID"] = "C89F77E0",
            ["NextDialogue"] = 80140337,
            ["SpeakNpcId"] = 100337,
            ["SpeakNpcName"] = "UI_Npc_Name_LaoLianjin",
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/003/C89F77E0",
            },
        [80140337] = {
            ["Content"] = "还没注射好吗？手脚利索点，别浪费时间。",
            ["ContentFR"] = "Tu n’as toujours pas fait l’injection ? Dépêche-toi. On n’a pas de temps à perdre.",
            ["DialogueId"] = 80140337,
            ["GUID"] = "C89F780A",
            ["LookAt"] = {
                [1] = "100337:n(100336)",
                [2] = "100336:n(100337)",
                },
            ["NextDialogue"] = 80140338,
            ["SpeakNpcId"] = 100337,
            ["SpeakNpcName"] = "UI_Npc_Name_LaoLianjin",
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/003/C89F780A",
            },
        [80140338] = {
            ["Content"] = "好了，老师。",
            ["ContentFR"] = "C’est fait, professeur.",
            ["DialogueId"] = 80140338,
            ["GUID"] = "C89F7834",
            ["SpeakNpcId"] = 100336,
            ["SpeakNpcName"] = "UI_Npc_Name_XiaoLianjin",
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/003/C89F7834",
            },
        [80140339] = {
            ["Camera"] = "-94.440186,-1.264404,77.296875,0.000404,36.399063,-23.382465,14.951323,125.0,false,DoNotOverride,2.8",
            ["Content"] = "……我知道。",
            ["ContentFR"] = "... Je sais.",
            ["DialogueId"] = 80140339,
            ["GUID"] = "C89F785E",
            ["NextDialogue"] = 80140340,
            ["SpeakNpcId"] = 790036,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/003/C89F785E",
            },
        [80140340] = {
            ["Content"] = "嗯？知道什么？",
            ["ContentFR"] = "Hein ? Tu sais quoi ?",
            ["DialogueId"] = 80140340,
            ["GUID"] = "C89F7888",
            ["LookAt"] = {
                [1] = "100337:n(790058)",
                [2] = "100336:n(790058)",
                },
            ["NextDialogue"] = 80140341,
            ["SpeakNpcId"] = 100336,
            ["SpeakNpcName"] = "UI_Npc_Name_XiaoLianjin",
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/003/C89F7888",
            },
        [80140341] = {
            ["Content"] = "我知道樱桃是什么味道。我和母亲第一次被剧院收留的时候，团长请我们吃了一顿丰盛的晚餐，餐后甜点就是樱桃派。",
            ["ContentFR"] = "Je sais quel goût ont les cerises. La première fois que ma mère et moi avons été recueillis par le théâtre... la directrice nous a offert un vrai festin. En dessert, il y avait une tarte aux cerises.",
            ["DialogueId"] = 80140341,
            ["GUID"] = "C89F78B2",
            ["NextDialogue"] = 80140342,
            ["SpeakNpcId"] = 790036,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/003/C89F78B2",
            },
        [80140342] = {
            ["Content"] = "我还记得它被切开的时候，深红色的果酱从金黄色的酥皮里溢出来，一股劣质糖果远远无法比拟的香甜气息在一瞬间填满了整个餐厅。",
            ["ContentFR"] = "Je me souviens... Quand elle a été coupée, un sirop rouge sombre a coulé hors de sa croûte dorée. Un parfum sucré... intense... bien plus noble que n’importe quelle friandise bon marché. Ce parfum-là... il a rempli toute la salle en une seconde.",
            ["DialogueId"] = 80140342,
            ["GUID"] = "C89F78DC",
            ["NextDialogue"] = 80140343,
            ["SpeakNpcId"] = 790036,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/003/C89F78DC",
            },
        [80140343] = {
            ["Content"] = "团长说自己年纪大不能吃甜食，让出了她那份，其实她只是看我嘴馋。",
            ["ContentFR"] = "La directrice a dit qu’à son âge, elle ne pouvait plus manger sucré. Mais je savais qu’elle me mentait... Elle voulait juste me laisser sa part. Parce qu’elle avait vu dans mes yeux à quel point je la voulais.",
            ["DialogueId"] = 80140343,
            ["GUID"] = "C89F7906",
            ["NextDialogue"] = 80140344,
            ["SpeakNpcId"] = 790036,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/003/C89F7906",
            },
        [80140344] = {
            ["Content"] = "老师那时还是个年轻又有活力的姑娘，一边小口咬着派，一边偷偷照镜子确认有没有碎屑沾在脸上。",
            ["ContentFR"] = "À l’époque, Madame Violetta, ma professeure, était encore jeune, vive... Elle mangeait sa part à toutes petites bouchées, et jetait des regards furtifs à son miroir de poche, pour voir si elle avait des miettes sur le visage.",
            ["DialogueId"] = 80140344,
            ["GUID"] = "C89F7930",
            ["NextDialogue"] = 80140345,
            ["SpeakNpcId"] = 790036,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/003/C89F7930",
            },
        [80140345] = {
            ["Content"] = "为了抢夺剩下的最后一块，小小的苏珊娜和丹尼斯提出用比赛背台词的方式决出胜负，结果两个人都背错了好多，把老师气得差点噎着。",
            ["ContentFR"] = "Et puis il y avait Susanna et Dennis, encore enfants... Ils se battaient pour la dernière part. Ils ont décidé de faire un concours de récitation pour la gagner... mais ils ont tellement cafouillé que Madame Violetta a failli s’étouffer de rire.",
            ["DialogueId"] = 80140345,
            ["GUID"] = "C89F795A",
            ["NextDialogue"] = 80140346,
            ["SpeakNpcId"] = 790036,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/003/C89F795A",
            },
        [80140346] = {
            ["Content"] = "哈哈……也不知道大家现在过得怎么样。没了我这个“骗子”，他们应该能正常举办演出了吧。",
            ["ContentFR"] = "Ahah... Je me demande ce qu’ils deviennent maintenant. Sans moi, le \"menteur\", la troupe peut sûrement jouer en paix, non ?",
            ["DialogueId"] = 80140346,
            ["GUID"] = "C89F7984",
            ["NextDialogue"] = 80140347,
            ["SpeakNpcId"] = 790036,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/003/C89F7984",
            },
        [80140347] = {
            ["Content"] = "……",
            ["ContentFR"] = "...",
            ["DialogueId"] = 80140347,
            ["GUID"] = "C89F79AE",
            ["NextDialogue"] = 80140348,
            ["SpeakNpcId"] = 100336,
            ["SpeakNpcName"] = "UI_Npc_Name_XiaoLianjin",
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/003/C89F79AE",
            },
        [80140348] = {
            ["Camera"] = "-94.440186,-1.264404,77.296875,0.000404,36.399063,-23.382465,14.951323,125.0,false,DoNotOverride,2.8",
            ["Content"] = "怎么，有什么异常吗？",
            ["ContentFR"] = "Quoi ? Un souci ?",
            ["DialogueId"] = 80140348,
            ["FinalCamera"] = "-94.440186,-1.264404,77.296875,0.000426,42.395412,-2.778932,14.951323,125.0,false,DoNotOverride,2.8",
            ["GUID"] = "C89F79D8",
            ["NextDialogue"] = 80140349,
            ["Scripts"] = "MoveTo{ActorId{100337},MoveSpeed{60},TargetPoint{\"Move\"}}",
            ["SpeakNpcId"] = 100337,
            ["SpeakNpcName"] = "UI_Npc_Name_LaoLianjin",
            ["ToFinalCameraBlendTime"] = 3,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/003/C89F79D8",
            },
        [80140349] = {
            ["Camera"] = "-94.440186,-1.264404,77.296875,0.000426,42.395412,-2.778932,14.951323,125.0,false,DoNotOverride,2.8",
            ["Content"] = "没什么，老师。实验体精神状态不太稳定，又在说胡话了。我正准备提高镇定剂的剂量。",
            ["ContentFR"] = "Non, professeur. L’état mental du sujet est instable. Il recommence à délirer. Je vais augmenter la dose de sédatif.",
            ["DialogueId"] = 80140349,
            ["GUID"] = "C89F7A02",
            ["LookAt"] = {
                [1] = "100336:n(100337)",
                },
            ["NextDialogue"] = 80140350,
            ["SpeakNpcId"] = 100336,
            ["SpeakNpcName"] = "UI_Npc_Name_XiaoLianjin",
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/003/C89F7A02",
            },
        [80140350] = {
            ["Content"] = "嗯，正确的判断。你这些天进步不少。",
            ["ContentFR"] = "Bonne décision. Tu progresses. C’est bien.",
            ["DialogueId"] = 80140350,
            ["GUID"] = "C89F7A2C",
            ["LookAt"] = {
                [1] = "100337:n(100336)",
                },
            ["NextDialogue"] = 80140351,
            ["SpeakNpcId"] = 100337,
            ["SpeakNpcName"] = "UI_Npc_Name_LaoLianjin",
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/003/C89F7A2C",
            },
        [80140351] = {
            ["Content"] = "谢谢老师！",
            ["ContentFR"] = "Merci, professeur.",
            ["DialogueId"] = 80140351,
            ["GUID"] = "C89F7A56",
            ["NextDialogue"] = 80140352,
            ["SpeakNpcId"] = 100336,
            ["SpeakNpcName"] = "UI_Npc_Name_XiaoLianjin",
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/003/C89F7A56",
            },
        [80140352] = {
            ["Content"] = "（呃……！意识……又开始模糊了……喉咙……发不出声音……）",
            ["ContentFR"] = "Argh... Ma conscience... s’efface encore... Ma gorge... ne sort plus un son...",
            ["DialogueId"] = 80140352,
            ["GUID"] = "C89F7A80",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 80140353,
            ["SpeakNpcId"] = 790036,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/003/C89F7A80",
            },
        [80140353] = {
            ["Camera"] = "-98.189453,-21.996094,87.716553,0.000448,36.592773,-24.981009,37.340542,125.0,false,DoNotOverride,2.8",
            ["Content"] = "这就对了，闭嘴吧。",
            ["ContentFR"] = "Voilà. Tais-toi maintenant.",
            ["DialogueId"] = 80140353,
            ["GUID"] = "C89F7AAA",
            ["LookAt"] = {
                [1] = "100336:n(790058)",
                },
            ["NextDialogue"] = 80140354,
            ["SpeakNpcId"] = 100336,
            ["SpeakNpcName"] = "UI_Npc_Name_XiaoLianjin",
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/003/C89F7AAA",
            },
        [80140354] = {
            ["Content"] = "（为什么……？）",
            ["ContentFR"] = "Pourquoi... ?",
            ["DialogueId"] = 80140354,
            ["GUID"] = "C89F7AD4",
            ["NextDialogue"] = 80140355,
            ["SpeakNpcId"] = 790036,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/003/C89F7AD4",
            },
        [80140355] = {
            ["Content"] = "（啊……我明白了。）",
            ["ContentFR"] = "Ah... Je comprends.",
            ["DialogueId"] = 80140355,
            ["GUID"] = "C89F7AFE",
            ["NextDialogue"] = 80140356,
            ["SpeakNpcId"] = 790036,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/003/C89F7AFE",
            },
        [80140356] = {
            ["Content"] = "（你——也变成怪物了。）",
            ["ContentFR"] = "Toi aussi... tu es devenu un monstre.",
            ["DialogueId"] = 80140356,
            ["GUID"] = "C89F7B28",
            ["IsBlack"] = 1,
            ["SpeakNpcId"] = 790036,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/003/C89F7B28",
            },
        [80140357] = {
            ["Content"] = "我是凶残的野兽，奉命撕碎所有的猎物。",
            ["ContentFR"] = "Je suis une bête féroce, envoyée pour déchiqueter mes proies.",
            ["DialogueId"] = 80140357,
            ["Duration"] = 4,
            ["GUID"] = "C89F7B52",
            ["NextDialogue"] = 80140358,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/003/C89F7B52",
            },
        [80140358] = {
            ["Content"] = "然后，埋葬自己。",
            ["ContentFR"] = "Et puis... enterrer ma propre chair dans l’ombre.",
            ["DialogueId"] = 80140358,
            ["Duration"] = 3,
            ["GUID"] = "C89F7B7C",
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/003/C89F7B7C",
            },
        [80140401] = {
            ["Content"] = "你是谁？",
            ["ContentFR"] = "Qui es-tu ?",
            ["DialogueId"] = 80140401,
            ["Duration"] = 3,
            ["GUID"] = "C89F828A",
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/004/C89F828A",
            },
        [80140402] = {
            ["Content"] = "你要去往何处？",
            ["ContentFR"] = "Où comptes-tu aller ?",
            ["DialogueId"] = 80140402,
            ["Duration"] = 4,
            ["GUID"] = "C89F82B4",
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/004/C89F82B4",
            },
        [80140403] = {
            ["Content"] = "哎，你要去哪里呀？",
            ["ContentFR"] = "Hé, tu vas où comme ça ?",
            ["DialogueId"] = 80140403,
            ["GUID"] = "C89F82DE",
            ["LookAt"] = {
                [1] = "790026:n(790027)",
                [2] = "790027:n(790026)",
                },
            ["NextDialogue"] = 80140404,
            ["Scripts"] = "PlayOrStopBGM{PlayType{\"Play\"},SoundPriority{\"Invite\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/mute\"}}",
            ["SpeakNpcId"] = 790026,
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/004/C89F82DE",
            },
        [80140404] = {
            ["Content"] = "——？！",
            ["ContentFR"] = "... ?!",
            ["DialogueId"] = 80140404,
            ["GUID"] = "C89F8308",
            ["NextDialogue"] = 80140405,
            ["SpeakNpcId"] = 790025,
            ["SpeakNpcName"] = "UI_Npc_Name_Tuosi",
            ["TurnTo"] = {
                [1] = "790025:p(180)",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/004/C89F8308",
            },
        [80140405] = {
            ["Camera"] = "149.733398,593.0,86.0,0.0,0.0,-72.599388,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "丹尼斯！等等我呀！",
            ["ContentFR"] = "Dennis ! Attends-moi !",
            ["DialogueId"] = 80140405,
            ["FacialId"] = {
                [1] = "790026:CM_Smile01",
                },
            ["GUID"] = "C89F8332",
            ["LookAt"] = {
                [1] = "790025:n(790026)",
                },
            ["NextDialogue"] = 80140406,
            ["SpeakNpcId"] = 790026,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/004/C89F8332",
            },
        [80140406] = {
            ["Camera"] = "-57.349121,46.69873,86.0,0.0,0.0,30.20026,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "呃……天太冷了，我想赶快回家睡觉。",
            ["ContentFR"] = "Brr... Il fait un froid de chien. Je veux juste rentrer me coucher.",
            ["DialogueId"] = 80140406,
            ["FacialId"] = {
                [1] = "790027:CM_Sad01",
                },
            ["GUID"] = "C89F835C",
            ["NextDialogue"] = 80140407,
            ["SpeakNpcId"] = 790027,
            ["TalkActionId"] = {
                [1] = "790027:Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/004/C89F835C",
            },
        [80140407] = {
            ["Camera"] = "226.189453,553.110352,113.588379,0.000044,-4.199979,-87.397324,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "不是吧，这才几点？别那么急嘛，陪我对一会儿戏！今天老师教的那段我还背得不怎么熟练。",
            ["ContentFR"] = "Quoi, déjà ? Il est même pas si tard ! Allez, reste un peu, fais une dernière réplique avec moi ! Celle que Madame Violetta nous a faite bosser aujourd’hui, je la maîtrise pas encore.",
            ["DialogueId"] = 80140407,
            ["FacialId"] = {
                [1] = "790027:CM_Smile01",
                },
            ["GUID"] = "C89F8386",
            ["NextDialogue"] = 80140408,
            ["SpeakNpcId"] = 790026,
            ["TalkActionId"] = {
                [1] = "790027:Talk03_End",
                [2] = "790026:Confident_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/004/C89F8386",
            },
        [80140408] = {
            ["Camera"] = "602.087891,-88.831787,85.242676,0.000014,-0.400024,133.199921,35.000008,525.224243,false,Manual,2.8",
            ["Content"] = "又来……？啊——好好好，陪你练就是了，别动手啊！",
            ["ContentFR"] = "Encore ?! Aïe... bon, bon, d’accord, je te suis... mais arrête de frapper d’abord !",
            ["DialogueId"] = 80140408,
            ["FinalCamera"] = "510.33252,8.879395,84.308105,0.000014,-0.400024,133.199921,35.000008,2024.230103,false,Manual,2.8",
            ["GUID"] = "C89F83B0",
            ["NextDialogue"] = 80140409,
            ["Scripts"] = "MoveTo{ActorId{790026},MoveSpeed{60},TargetPoint{\"P80140426\"}}",
            ["SpeakNpcId"] = 790027,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/004/C89F83B0",
            },
        [80140409] = {
            ["Content"] = "（他们两个真是一点也没变。）",
            ["ContentFR"] = "Ils n’ont pas changé... Pas du tout.",
            ["DialogueId"] = 80140409,
            ["GUID"] = "C89F83DA",
            ["NextDialogue"] = 80140410,
            ["SpeakNpcId"] = 790025,
            ["SpeakNpcName"] = "UI_Npc_Name_Tuosi",
            ["TalkActionId"] = {
                [1] = "790025:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/004/C89F83DA",
            },
        [80140410] = {
            ["Camera"] = "136.138672,760.375244,255.158691,0.000026,-19.999907,-75.596756,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "说起来，下个月的演出剧目定了吗？",
            ["ContentFR"] = "Au fait, la pièce du mois prochain, elle est choisie ?",
            ["DialogueId"] = 80140410,
            ["FinalCamera"] = "-128.058105,642.81958,243.39624,0.000037,-18.99983,-43.396786,35.000008,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "C89F8404",
            ["NextDialogue"] = 80140411,
            ["SpeakNpcId"] = 790026,
            ["TalkActionId"] = {
                [1] = "790026:Think_Start",
                },
            ["ToFinalCameraBlendTime"] = 35,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/004/C89F8404",
            },
        [80140411] = {
            ["Content"] = "团长说是《雨日》。",
            ["ContentFR"] = "La directrice a dit qu’on jouerait Pluie d’automne.",
            ["DialogueId"] = 80140411,
            ["GUID"] = "C89F842E",
            ["NextDialogue"] = 80140412,
            ["SpeakNpcId"] = 790027,
            ["TalkActionId"] = {
                [1] = "790027:Explain01_Start",
                [2] = "790026:Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/004/C89F842E",
            },
        [80140412] = {
            ["Content"] = "《雨日》的人气也就一般般吧？靠它出人头地可不容易。唉，要是能再演《雪国的孩子》就好了。那部剧在冰湖城可受欢迎了……",
            ["ContentFR"] = "Pluie d’automne ? C’est pas super populaire, non ? Pour se faire remarquer, c’est pas l’idéal... Soupir... Si seulement on pouvait refaire Né du blizzard. À Givrelac, tout le monde adore cette pièce...",
            ["DialogueId"] = 80140412,
            ["GUID"] = "C89F8458",
            ["NextDialogue"] = 80140413,
            ["SpeakNpcId"] = 790026,
            ["TalkActionId"] = {
                [1] = "790026:Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/004/C89F8458",
            },
        [80140413] = {
            ["Content"] = "就是啊！我也好想再演一次无名的妖精，那可是我最得意的角色，虽然唱段又多又难，但完整演下来的感觉真是太棒了。",
            ["ContentFR"] = "Carrément ! Je voudrais rejouer la fée sans nom. C’était mon rôle préféré, même si les chants étaient horribles à apprendre... Quand je l’ai fait en entier, c’était magique.",
            ["DialogueId"] = 80140413,
            ["GUID"] = "C89F8482",
            ["NextDialogue"] = 80140414,
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{790027},AnimationId{\"Agree\"},Duration{1}},\
PlayAnimation{ActorId{790027},AnimationId{\"Explain02_Start\"},Duration{3},_delay{1}},\
PlayAnimation{ActorId{790027},AnimationId{\"Explain02_End\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 790027,
            ["TalkActionId"] = {
                [1] = "790026:Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/004/C89F8482",
            },
        [80140414] = {
            ["Camera"] = "245.842773,452.263184,118.095703,0.000008,-6.0,-87.99778,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "诶——真的吗？我觉得我们这一届里还是费恩演得最好啊。",
            ["ContentFR"] = "Oh ? Vraiment ? Je pensais que Fane l’avait mieux interprété que toi.",
            ["DialogueId"] = 80140414,
            ["FacialId"] = {
                [1] = "790026:CM_Shock01",
                },
            ["GUID"] = "C89F84AC",
            ["NextDialogue"] = 80140415,
            ["SpeakNpcId"] = 790026,
            ["TalkActionId"] = {
                [1] = "790026:Shock_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/004/C89F84AC",
            },
        [80140415] = {
            ["Camera"] = "132.975586,162.901611,104.536133,0.000011,-0.800081,44.600689,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "你瞎说，终幕的那几段明明是我唱得更好！",
            ["ContentFR"] = "Tu plaisantes ? C’est moi qui ai assuré dans le final, tu le sais très bien !",
            ["DialogueId"] = 80140415,
            ["FacialId"] = {
                [1] = "790027:CM_Angry01",
                },
            ["GUID"] = "C89F84D6",
            ["LookAt"] = {
                [1] = "790025:n(790025)",
                },
            ["NextDialogue"] = 80140416,
            ["SpeakNpcId"] = 790027,
            ["TalkActionId"] = {
                [1] = "790027:Angry01_Start",
                [2] = "790026:Shock_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/004/C89F84D6",
            },
        [80140416] = {
            ["Camera"] = "-499.695312,1424.604492,320.095459,0.000023,-18.799973,-178.997177,35.000008,446.117035,false,Manual,1.236337",
            ["Content"] = "……",
            ["ContentFR"] = "...",
            ["DialogueId"] = 80140416,
            ["GUID"] = "C89F8500",
            ["NextDialogue"] = 80140417,
            ["SpeakNpcId"] = 790025,
            ["SpeakNpcName"] = "UI_Npc_Name_Tuosi",
            ["TalkActionId"] = {
                [1] = "790027:Angry01_End",
                },
            ["TurnTo"] = {
                [1] = "790025:p(150)",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/004/C89F8500",
            },
        [80140417] = {
            ["Content"] = "……其实我和费恩都不是演得最好的。",
            ["ContentFR"] = "... En vrai, ni Fane ni moi n’étions les meilleurs.",
            ["DialogueId"] = 80140417,
            ["GUID"] = "C89F852A",
            ["NextDialogue"] = 80140418,
            ["SpeakNpcId"] = 790027,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/004/C89F852A",
            },
        [80140418] = {
            ["Content"] = "……",
            ["ContentFR"] = "...",
            ["DialogueId"] = 80140418,
            ["GUID"] = "C89F8554",
            ["LookAt"] = {
                [1] = "790025:n(790026)",
                },
            ["NextDialogue"] = 80140419,
            ["SpeakNpcId"] = 790026,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/004/C89F8554",
            },
        [80140419] = {
            ["Content"] = "嗯，是啊。要说《雪国的孩子》，没有人能唱得比帕西法尔更好。也不知道他现在到底去哪里了……",
            ["ContentFR"] = "Non, c’est vrai. Pour Né du blizzard, personne n’arrivait à la cheville de Parsifal. Je me demande bien ce qu’il est devenu...",
            ["DialogueId"] = 80140419,
            ["GUID"] = "C89F857E",
            ["NextDialogue"] = 80140420,
            ["SpeakNpcId"] = 790026,
            ["TurnTo"] = {
                [1] = "790025:p(-50)",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/004/C89F857E",
            },
        [80140420] = {
            ["Camera"] = "220.45752,2492.598633,1532.584961,0.000103,-41.999317,-110.678604,24.770275,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "（我在这里。）",
            ["ContentFR"] = "Je suis là.",
            ["DialogueId"] = 80140420,
            ["FinalCamera"] = "309.450684,2728.375977,1759.494141,0.000103,-41.999317,-110.678604,24.770275,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "C89F85A8",
            ["LookAt"] = {
                [1] = "790025:n(790026)",
                },
            ["NextDialogue"] = 80140421,
            ["Scripts"] = "PlayOrStopBGM{PlayType{\"Play\"},SoundPriority{\"Invite\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt03/0081_scene_alchemyacademy\"}}",
            ["SpeakNpcId"] = 790025,
            ["SpeakNpcName"] = "UI_Npc_Name_Tuosi",
            ["ToFinalCameraBlendTime"] = 15,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/004/C89F85A8",
            },
        [80140421] = {
            ["Content"] = "（我在这里啊……）",
            ["ContentFR"] = "Je suis juste là, devant vous...",
            ["DialogueId"] = 80140421,
            ["GUID"] = "C89F85D2",
            ["NextDialogue"] = 80140422,
            ["SpeakNpcId"] = 790025,
            ["SpeakNpcName"] = "UI_Npc_Name_Tuosi",
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/004/C89F85D2",
            },
        [80140422] = {
            ["Content"] = "（我……）",
            ["ContentFR"] = "Je...",
            ["DialogueId"] = 80140422,
            ["GUID"] = "C89F85FC",
            ["NextDialogue"] = 80140423,
            ["SpeakNpcId"] = 790025,
            ["SpeakNpcName"] = "UI_Npc_Name_Tuosi",
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/004/C89F85FC",
            },
        [80140423] = {
            ["Camera"] = "121.94873,146.241211,123.842773,0.00001,-6.600128,46.39674,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "帕西法尔……",
            ["ContentFR"] = "Parsifal...",
            ["DialogueId"] = 80140423,
            ["GUID"] = "C89F8626",
            ["NextDialogue"] = 80140424,
            ["SpeakNpcId"] = 790027,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/004/C89F8626",
            },
        [80140424] = {
            ["Camera"] = "149.733398,593.0,86.0,0.0,0.0,-72.599388,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "哦，忘了不该在你面前提他。上次团长说起他的时候，你还在破口大骂，差点把道具都砸了。",
            ["ContentFR"] = "Ah zut, j’aurais pas dû le mentionner. La dernière fois que la directrice a dit son nom, t’as crié si fort que t’as failli casser tous les décors...",
            ["DialogueId"] = 80140424,
            ["FacialId"] = {
                [1] = "790026:CM_Sad01",
                },
            ["GUID"] = "C89F8650",
            ["LookAt"] = {
                [1] = "790027:n(790027)",
                },
            ["NextDialogue"] = 80140425,
            ["SpeakNpcId"] = 790026,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/004/C89F8650",
            },
        [80140425] = {
            ["Camera"] = "43.179199,176.508789,110.248047,0.000011,-3.59994,23.599939,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "……那时我确实很生气。如果不是他和老师欺骗观众，《雪国的孩子》就不会停演，我们那么久的排练也不会付诸东流。可是……",
            ["ContentFR"] = "... Ouais. J’étais furieux. À cause de lui et de Madame Violetta, on a annulé la pièce. Tout ce travail... gâché.",
            ["DialogueId"] = 80140425,
            ["FacialId"] = {
                [1] = "790026:CM_Shock01",
                },
            ["GUID"] = "C89F867A",
            ["LookAt"] = {
                [1] = "790026:n(790027)",
                },
            ["NextDialogue"] = 80140426,
            ["SpeakNpcId"] = 790027,
            ["TurnTo"] = {
                [1] = "790027:p(90)",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/004/C89F867A",
            },
        [80140426] = {
            ["Content"] = "可是后来很多次我问自己——他真的不该上台吗？错的到底是违反了“卡戎之民不能上台演出”这一规则的帕西法尔，还是这条规则本身？",
            ["ContentFR"] = "Mais... je me suis souvent demandé depuis, est-ce qu’il avait vraiment tort de monter sur scène ? Est-ce que c’était sa faute à lui, ou celle de cette foutue règle qui interdit aux Charons de jouer ?",
            ["DialogueId"] = 80140426,
            ["GUID"] = "C89F86A4",
            ["LookAt"] = {
                [1] = "790027:n(790026)",
                },
            ["NextDialogue"] = 80140427,
            ["SpeakNpcId"] = 790027,
            ["TurnTo"] = {
                [1] = "790027:n(790026)",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/004/C89F86A4",
            },
        [80140427] = {
            ["Content"] = "我们之所以站在舞台上是为了什么——是<H>至高无上的艺术</>……",
            ["ContentFR"] = "Pourquoi on monte sur scène ? Pour <H>célébrer l’art, ce qu’il a de plus pur</>...",
            ["DialogueId"] = 80140427,
            ["GUID"] = "C89F86CE",
            ["NextDialogue"] = 80140428,
            ["SpeakNpcId"] = 790027,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/004/C89F86CE",
            },
        [80140428] = {
            ["Content"] = "可是为什么人们不去看演出本身，而是死死盯着那个表演的人有没有长角？如果我们大家一起站在帷幕后面，那帕西法尔与我们又有什么区别？",
            ["ContentFR"] = "Alors pourquoi les gens regardent les cornes avant la performance ? Si on jouait tous derrière un rideau, Parsifal serait-il différent de nous ?",
            ["DialogueId"] = 80140428,
            ["GUID"] = "C89F86F8",
            ["NextDialogue"] = 80140429,
            ["SpeakNpcId"] = 790027,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/004/C89F86F8",
            },
        [80140429] = {
            ["Camera"] = "184.165039,231.606201,98.688477,0.00003,4.399932,43.401665,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "哦，还是有区别的。他比我唱得更好。",
            ["ContentFR"] = "Oh si, y’a une différence. Il chantait mieux que moi.",
            ["DialogueId"] = 80140429,
            ["FacialId"] = {
                [1] = "790027:CM_Idle",
                },
            ["GUID"] = "C89F8722",
            ["NextDialogue"] = 80140430,
            ["SpeakNpcId"] = 790027,
            ["TalkActionId"] = {
                [1] = "790027:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/004/C89F8722",
            },
        [80140430] = {
            ["Camera"] = "201.510254,546.49585,122.383301,0.000004,-6.400051,-77.79879,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "真是难得，竟然能从你嘴里听到这种话。看来我们莽撞的丹尼斯终于长大啦。",
            ["ContentFR"] = "Ouah. Entendre ça de toi, c’est rare. Dennis, le grand impulsif, aurait-il mûri ?",
            ["DialogueId"] = 80140430,
            ["FacialId"] = {
                [1] = "790026:CM_Happy01",
                },
            ["GUID"] = "C89F874C",
            ["NextDialogue"] = 80140431,
            ["SpeakNpcId"] = 790026,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/004/C89F874C",
            },
        [80140431] = {
            ["Camera"] = "96.443359,130.570557,116.894043,0.000003,-3.99997,42.200706,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "喂，不要突然摆出团长的样子教训我啊。",
            ["ContentFR"] = "Hé ! Commence pas à jouer la directrice, toi !",
            ["DialogueId"] = 80140431,
            ["FacialId"] = {
                [1] = "790027:CM_Angry01",
                },
            ["GUID"] = "C89F8776",
            ["NextDialogue"] = 80140432,
            ["SpeakNpcId"] = 790027,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/004/C89F8776",
            },
        [80140432] = {
            ["Camera"] = "201.510254,546.49585,122.383301,0.000004,-6.400051,-77.79879,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "这是夸奖，才不是教训！如果帕西法尔那家伙突然跑回来，我才要狠狠教训他，谁叫他连封信都没留就不知道跑哪儿去了，我是真的很想他呀。",
            ["ContentFR"] = "Mais non, c’était un compliment ! Mais si Parsifal réapparaît un jour, je lui passerai un sacré savon. Disparaître comme ça, sans une lettre... Je lui en veux, mais il me manque.",
            ["DialogueId"] = 80140432,
            ["FacialId"] = {
                [1] = "790026:CM_Smile01",
                },
            ["GUID"] = "C89F87A0",
            ["NextDialogue"] = 80140433,
            ["SpeakNpcId"] = 790026,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/004/C89F87A0",
            },
        [80140433] = {
            ["Camera"] = "-1153.268066,1960.390137,235.713867,0.000035,-6.800218,-58.593773,35.000011,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "（苏珊娜，丹尼斯……）",
            ["ContentFR"] = "Susanna... Dennis...",
            ["DialogueId"] = 80140433,
            ["GUID"] = "C89F87CA",
            ["NextDialogue"] = 80140434,
            ["SpeakNpcId"] = 790025,
            ["SpeakNpcName"] = "UI_Npc_Name_Paxi",
            ["TalkActionId"] = {
                [1] = "790025:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/004/C89F87CA",
            },
        [80140434] = {
            ["Camera"] = "185.86377,442.624756,59.498047,0.000046,11.799335,-73.192505,47.811131,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "话说回来，你还记得老师说过的吗？“虽然不是现在，但未来的某一天，我们的艺术一定会迎来一个更加纯粹的时代，那时将不再有索拉和卡戎之别。”",
            ["ContentFR"] = "Tu te souviens de ce que disait Violetta ? « Peut-être pas aujourd’hui, mais un jour, notre art connaîtra une époque plus pure. Une époque sans Solariens ni Charons, où seule comptera la beauté du jeu. »",
            ["DialogueId"] = 80140434,
            ["FacialId"] = {
                [1] = "790026:CM_Smile01",
                },
            ["FinalCamera"] = "199.419434,397.746582,69.291504,0.000046,11.799335,-73.192505,47.811131,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "C89F87F4",
            ["NextDialogue"] = 80140435,
            ["SpeakNpcId"] = 790026,
            ["TalkActionId"] = {
                [1] = "790025:Explain02_End",
                },
            ["ToFinalCameraBlendTime"] = 15,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/004/C89F87F4",
            },
        [80140435] = {
            ["Content"] = "我想，虽然老师和帕西法尔一时间被人们唾骂，让剧团蒙受耻辱……但是正因为有他们这样的人存在，那个新时代才会到来。",
            ["ContentFR"] = "Je pense que, même si Violetta et Parsifal ont été rejetés, s’ils ont couvert notre troupe de honte... c’est justement grâce à des gens comme eux qu’un avenir meilleur pourra voir le jour.",
            ["DialogueId"] = 80140435,
            ["GUID"] = "C89F881E",
            ["NextDialogue"] = 80140436,
            ["SpeakNpcId"] = 790026,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/004/C89F881E",
            },
        [80140436] = {
            ["Content"] = "到那时他们就不再是“耻辱”，而是比大家更早醒来的“英雄”。",
            ["ContentFR"] = "Ce jour-là, ils ne seront plus une \"honte\", mais des \"héros\" qui ont simplement ouvert les yeux avant les autres.",
            ["DialogueId"] = 80140436,
            ["FacialId"] = {
                [1] = "790026:CM_Happy01",
                },
            ["GUID"] = "C89F8848",
            ["NextDialogue"] = 80140437,
            ["SpeakNpcId"] = 790026,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/004/C89F8848",
            },
        [80140437] = {
            ["Camera"] = "-475.065918,1530.032227,242.341553,0.000032,-7.199647,-170.999466,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "…………",
            ["ContentFR"] = "...",
            ["DialogueId"] = 80140437,
            ["GUID"] = "C89F8872",
            ["NextDialogue"] = 80140438,
            ["SpeakNpcId"] = 790025,
            ["SpeakNpcName"] = "UI_Npc_Name_Paxi",
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/004/C89F8872",
            },
        [80140438] = {
            ["Camera"] = "52.178223,609.198242,243.78833,0.000039,-21.399986,-59.798325,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "让我们祝福他吧！也许他已经去了卡戎之民也能上台表演的地方，比如卢卡或者伊瑟尔。",
            ["ContentFR"] = "Souhaitons-lui bonne chance ! Peut-être qu’il est déjà dans un endroit où les Charons ont le droit de monter sur scène, comme à Luca ou à Aethyrie.",
            ["DialogueId"] = 80140438,
            ["FinalCamera"] = "-116.030762,898.193115,370.702637,0.000039,-21.399986,-59.798325,35.000008,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "C89F889C",
            ["NextDialogue"] = 80140439,
            ["SpeakNpcId"] = 790026,
            ["TalkActionId"] = {
                [1] = "790026:Explain02_Start",
                },
            ["ToFinalCameraBlendTime"] = 15,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/004/C89F889C",
            },
        [80140439] = {
            ["Content"] = "说不定下次我们去这些国家巡演的时候，就会发现他已经摇身一变，成了老师那样的大明星呢！",
            ["ContentFR"] = "Et qui sait, quand on partira en tournée là-bas, peut-être qu’on tombera sur lui... devenu une grande star comme Madame Violetta !",
            ["DialogueId"] = 80140439,
            ["GUID"] = "C89F88C6",
            ["LookAt"] = {
                [1] = "790025:n(790025)",
                },
            ["NextDialogue"] = 80140440,
            ["SpeakNpcId"] = 790026,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/004/C89F88C6",
            },
        [80140440] = {
            ["Content"] = "嗯。希望我们还有机会和他站上同一个舞台。",
            ["ContentFR"] = "Ouais. J’espère qu’un jour, on remontera tous ensemble sur scène.",
            ["DialogueId"] = 80140440,
            ["GUID"] = "C89F88F0",
            ["LookAt"] = {
                [1] = "790027:n(790027)",
                [2] = "790026:n(790026)",
                },
            ["NextDialogue"] = 80140454,
            ["SpeakNpcId"] = 790027,
            ["TalkActionId"] = {
                [1] = "790026:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/004/C89F88F0",
            },
        [80140441] = {
            ["Camera"] = "644.496094,-490.569336,714.540771,0.000021,-32.197926,139.796692,23.178257,407.658783,false,DoNotOverride,1.2",
            ["Content"] = "如果——如果你我以人类的模样相识，此时此刻有说有笑地离开剧院的，会是我们四个人吗？",
            ["ContentFR"] = "Si... si toi et moi nous étions rencontrés en tant qu’humains... est-ce qu’on serait tous les quatre sortis ensemble du théâtre, en riant comme ce soir ?",
            ["DialogueId"] = 80140441,
            ["FinalCamera"] = "644.496094,-490.569336,603.562866,0.000021,-32.197926,139.796692,23.178257,407.658783,false,DoNotOverride,1.2",
            ["GUID"] = "C89F891A",
            ["LookAt"] = {
                [1] = "790029:n(790028)",
                },
            ["NextDialogue"] = 80140442,
            ["SpeakNpcId"] = 790029,
            ["TalkActionId"] = {
                [1] = "790029:Explain02_Start",
                [2] = "790028:Tuosi02_Emo_Idle_Pose",
                },
            ["ToFinalCameraBlendTime"] = 7,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/004/C89F891A",
            },
        [80140442] = {
            ["Content"] = "苏珊娜绝对不会放过你这个免费的伴奏，而以你的脾气，一定会一口答应。最后八成就会变成大家陪着她一起在天寒地冻的街道上排练吧。",
            ["ContentFR"] = "Susanna t’aurait sauté dessus pour que tu l’accompagnes gratuitement, et toi, évidemment, t’aurais accepté sans discuter. On aurait tous fini dehors à répéter dans le froid, juste pour lui faire plaisir.",
            ["DialogueId"] = 80140442,
            ["GUID"] = "C89F8944",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_110304_02.T_Story_Recall_110304_02'",
            ["NextDialogue"] = 80140443,
            ["SpeakNpcId"] = 790029,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/004/C89F8944",
            },
        [80140443] = {
            ["Content"] = "不过，你是有家人的。你那个一本正经的姐姐一定会来催你回家。也说不定，你反而会拉着她一起加入我们——嗯，这个可能性更大一些。",
            ["ContentFR"] = "Mais toi... tu avais une famille. Ta sœur, toujours sérieuse, toujours droite, serait sûrement venue te chercher. Ou alors... c’est toi qui l’aurais embarquée avec nous. Oui, c’est plus ton genre, ça.",
            ["DialogueId"] = 80140443,
            ["GUID"] = "C89F896E",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_110304_01.T_Story_Recall_110304_01'",
            ["NextDialogue"] = 80140444,
            ["SpeakNpcId"] = 790029,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/004/C89F896E",
            },
        [80140444] = {
            ["Content"] = "不。不可能。事到如今，我还在幻想什么？",
            ["ContentFR"] = "Non. Impossible. Qu’est-ce que je suis encore en train de m’inventer ?",
            ["DialogueId"] = 80140444,
            ["GUID"] = "C89F8998",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 80140445,
            ["SpeakNpcId"] = 790029,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/004/C89F8998",
            },
        [80140445] = {
            ["Content"] = "那个舞台、那些剧本、那些朋友，都是属于帕西法尔的，早已不属于我。",
            ["ContentFR"] = "Cette scène, ces rôles, ces amis... c’était Parsifal. Ce n’est plus moi.",
            ["DialogueId"] = 80140445,
            ["GUID"] = "C89F89C2",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 80140446,
            ["SpeakNpcId"] = 790029,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/004/C89F89C2",
            },
        [80140446] = {
            ["Content"] = "但是——",
            ["ContentFR"] = "Mais...",
            ["DialogueId"] = 80140446,
            ["GUID"] = "C89F89EC",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 80140447,
            ["SpeakNpcId"] = 790029,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/004/C89F89EC",
            },
        }
  end },
