        [80180333] = {
            ["Camera"] = "-277.273438,-616.734375,167.08728,0.00006,-8.597869,70.799004,30.000002,598.523071,false,Manual,1.2",
            ["Content"] = "你是傻子吗？就那样直接扑在伤员身上！他一看就活不成了，你自己也想没命？要是连你都死了，其他伤员怎么办？",
            ["ContentFR"] = "Tu es folle ? Te jeter sur un blessé comme ça ! Il était condamné, tu voulais mourir avec lui ? Si tu mourais, que feraient les autres blessés sans toi ?",
            ["DialogueId"] = 80180333,
            ["FinalCamera"] = "-264.697266,-621.226562,167.08728,0.00006,-8.597869,71.198959,30.000002,598.523071,false,Manual,1.2",
