        [80180337] = {
            ["Camera"] = "-236.851562,-653.707031,37.399048,0.000145,5.401894,72.381973,40.0,784.897949,false,Manual,1.422013",
            ["Content"] = "你让我想起了我的妈妈，还有我的师姐。如果她们在这儿，也会说同样的话。",
            ["ContentFR"] = "Tu me rappelles ma mère... et mon aînée, quand j’étais étudiante. Si elles étaient ici, elles diraient la même chose.",
            ["DialogueId"] = 80180337,
            ["FinalCamera"] = "-221.035156,-658.710938,37.399048,0.000145,5.401894,73.181877,40.0,784.897949,false,Manual,1.422013",
            ["GUID"] = "C8B91A8A",
            ["NextDialogue"] = 80180338,
            ["SpeakNpcId"] = 790045,
            ["TalkActionId"] = {
                [1] = "790045:Sigh_Start",
                },
            ["ToFinalCameraBlendTime"] = 6,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/003/C8B91A8A",
            },
        [80180338] = {
            ["Camera"] = "-221.035156,-658.710938,37.399048,0.000145,5.401894,73.181877,40.0,784.897949,false,Manual,1.422013",
            ["Content"] = "她们都曾这样期许过我，但我却未能如她们所愿。",
            ["ContentFR"] = "Elles espéraient que j’apprenne, mais je n’y suis jamais parvenue.",
            ["DialogueId"] = 80180338,
            ["GUID"] = "C8B91AB4",
            ["NextDialogue"] = 80180339,
            ["SpeakNpcId"] = 790045,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/003/C8B91AB4",
            },
        [80180339] = {
            ["Camera"] = "-4.738281,-90.714844,105.755493,0.000144,6.801099,61.380829,40.0,784.897949,false,DoNotOverride,1.422013",
            ["Content"] = "世界上有许许多多理性的人，他们善于权衡利弊，做出“最不坏”的那个选择。他们是天生的优秀领导者，决定着每一个时代的前路。",
            ["ContentFR"] = "Il y a tant de gens rationnels dans ce monde. Ils pèsent le pour et le contre... choisissent toujours \"la moins mauvaise\" option. Ce sont des leaders nés, qui tracent la voie de chaque époque.",
            ["DialogueId"] = 80180339,
            ["FinalCamera"] = "-4.738281,-90.714844,105.755493,0.00014,8.801094,61.180855,40.0,784.897949,false,DoNotOverride,1.422013",
            ["GUID"] = "C8B91ADE",
            ["NextDialogue"] = 80180340,
            ["SpeakNpcId"] = 790045,
            ["TalkActionId"] = {
                [1] = "790045:Sigh_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/003/C8B91ADE",
            },
        [80180340] = {
            ["Camera"] = "997.089844,-499.308594,-19.915771,0.000057,6.20341,151.968689,40.0,1144.406128,false,Manual,1.422013",
            ["Content"] = "但我不是。我始终没有办法让自己冷静下来，去计算更长远的得失。我能听到的，就只有眼前的哭泣而已。",
            ["ContentFR"] = "Mais moi, je ne suis pas comme eux. Je n’ai jamais su me calmer au point de penser si loin. Tout ce que j’entends... ce sont les pleurs juste devant moi.",
            ["DialogueId"] = 80180340,
            ["FinalCamera"] = "993.359375,-506.820312,-19.915771,0.000057,6.20341,150.768692,40.0,1144.406128,false,Manual,1.422013",
            ["GUID"] = "C8B91B08",
            ["NextDialogue"] = 80180341,
            ["SpeakNpcId"] = 790045,
            ["TalkActionId"] = {
                [1] = "790045:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/003/C8B91B08",
            },
        [80180341] = {
