            ["Content"] = "直接吃？",
            ["ContentFR"] = "Comme ça... directement ?",
            ["DialogueId"] = 80200120,
            ["FacialId"] = {
                [1] = "790008:Shock01",
                },
            ["GUID"] = "C8C5C830",
