            ["SpeakNpcId"] = 790053,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/002/C8C5CA52",
            },
        [80200134] = {
            ["Content"] = "身膺大风九章给予的神力，就应当救死扶伤，尽职尽责，哪怕耗尽最后一滴精血也在所不惜，我们扶氏代代如此……",
            ["ContentFR"] = "Dotée du pouvoir divin conféré par les Neuf Chapitres de Dafeng, je dois sauver les vies et soulager les souffrances, accomplir mon devoir sans faillir, fût-ce au prix de mon sang. Ainsi ont agi tous les membres de la famille Fu...",
            ["DialogueId"] = 80200134,
            ["GUID"] = "C8C5CA7C",
            ["NextDialogue"] = 80200135,
            ["SpeakNpcId"] = 790053,
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/002/C8C5CA7C",
            },
        [80200135] = {
            ["Camera"] = "1.20282,-148.704437,-23.814941,-8.000016,20.99094,79.829399,25.000006,137.399506,false,Manual,3.949137",
            ["Content"] = "怎么只有你扶风如此特殊，上不应天命，下不惜生灵，不尽祝由义务，离经叛道……",
            ["ContentFR"] = "Alors pourquoi toi, Fufeng, serais-tu différente ? Pourquoi défier la volonté du Ciel, mépriser les vies d’en bas, abandonner le devoir du Zhuyou et t’écarter de la voie ?",
            ["DialogueId"] = 80200135,
            ["FacialId"] = {
                [1] = "790053:Angry01",
                },
            ["FinalCamera"] = "-1.691193,-164.853149,-30.109375,-8.000016,20.99094,79.829399,25.000006,137.399506,false,Manual,3.949137",
            ["GUID"] = "C8C5CAA6",
            ["LookAt"] = {
                [1] = "790053:n(790008)",
                },
            ["NextDialogue"] = 80200136,
            ["SpeakNpcId"] = 790053,
            ["TalkActionId"] = {
                [1] = "790008:Explain02_Start",
                [2] = "790053:Sigh_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/002/C8C5CAA6",
            },
        [80200136] = {
            ["Content"] = "等等！我不是你姐姐——",
            ["ContentFR"] = "Attends ! Je ne suis pas ta sœur—",
            ["DialogueId"] = 80200136,
            ["GUID"] = "C8C5CAD0",
            ["NextDialogue"] = 80200137,
            ["SpeakNpcId"] = 790008,
            ["TalkActionId"] = {
                [1] = "790008:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/002/C8C5CAD0",
            },
        [80200137] = {
            ["Camera"] = "236.822632,-103.189087,84.118164,0.000283,-14.803396,162.835953,35.0,231.354126,false,Manual,6.101897",
            ["Content"] = "做出这等事来，你自然不再是我姐姐——",
            ["ContentFR"] = "Après ce que tu as fait... tu ne peux plus l’être.",
            ["DialogueId"] = 80200137,
            ["FinalCamera"] = "311.739746,-126.329514,104.841797,0.000284,-14.803334,162.835846,35.0,319.934235,false,Manual,6.101897",
            ["GUID"] = "C8C5CAFA",
            ["LookAt"] = {
                [1] = "790053:n(790053)",
                },
            ["NextOptions"] = {
                [1] = 802001371,
