            ["ToFinalCameraBlendTime"] = 15,
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/002/C8C5CAFA",
            },
        [80200139] = {
            ["Content"] = "我怎会信你那天马行空的理论……但{nickname}，好熟悉的名字，这是……",
            ["ContentFR"] = "Quelle histoire absurde... Et pourtant... {nickname}... ce nom m’est étrangement familier...",
            ["DialogueId"] = 80200139,
            ["GUID"] = "C8C5CB4E",
            ["NextDialogue"] = 80200144,
            ["SpeakNpcId"] = 790053,
