            },
        [80210301] = {
            ["Camera"] = "-1168.496094,1264.441406,313.365234,0.000131,-4.398683,-49.787758,30.000002,1615.87854,false,Manual,2.8",
            ["Content"] = "侠客大多是吃主，玩主。想来也是正常的，好马，好剑，好衣裳，总是大侠的标配。",
            ["ContentFR"] = "Les Vagabonds sont souvent fins gourmets, amateurs de plaisirs. Rien d’étonnant, au fond : un bon cheval, une bonne lame, de beaux habits — voilà l’attirail classique d’un héros errant.",
            ["DialogueId"] = 80210301,
            ["FacialId"] = {
                [1] = "790071:Smile01",
                },
            ["FinalCamera"] = "-1040.925781,1113.558594,298.16748,0.000131,-4.398683,-49.787758,30.000002,1361.954834,false,Manual,2.8",
            ["GUID"] = "C8CC4E82",
            ["LookAt"] = {
                [1] = "790071:n(790069)",
                [2] = "790069:n(790071)",
                },
            ["NextDialogue"] = 80210302,
            ["Scripts"] = "PlayAnimation{ActorId{790071},AnimationId{\"Sit_Idle_Loop\"},Sync{true}}",
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC4E82",
            },
        [80210302] = {
            ["Content"] = "至于酒食，更是极为精细。以至于提起侠客，总是感觉他们好酒，大块吃肉。而如果一个侠客明言不喝酒，就多少觉得他的剑意少了三分老辣。",
            ["ContentFR"] = "Quant à la nourriture et aux breuvages, l’exigence est d’autant plus grande. À tel point que l’image du Vagabond se confond souvent avec celle d’un homme buvant à grandes rasades et mangeant à pleines bouchées. Et lorsqu’un héros proclame ne pas toucher à l’alcool, on a presque l’impression que son sabre manque d’un peu de maturité.",
            ["DialogueId"] = 80210302,
            ["GUID"] = "C8CC4EAC",
            ["NextDialogue"] = 80210303,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC4EAC",
            },
        [80210303] = {
            ["Camera"] = "-235.25,3.191406,148.305176,0.000013,-19.999994,47.002541,20.0,187.784851,false,Manual,2.8",
            ["Content"] = "小二，一斤黄酒，七个油豆腐，辣酱要多！",
            ["ContentFR"] = "Garçon, une livre de breuvage jaune, sept tofu frits, et mets-moi une bonne dose de pâte pimentée !",
            ["DialogueId"] = 80210303,
            ["FinalCamera"] = "-220.636719,18.855469,140.509766,0.000013,-19.999994,47.002541,20.0,169.81192,false,Manual,2.8",
            ["GUID"] = "C8CC4ED6",
            ["NextDialogue"] = 80210304,
            ["SpeakNpcId"] = 790071,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC4ED6",
            },
        [80210304] = {
            ["Camera"] = "-159.164062,204.953125,88.058105,0.000052,9.999997,-80.395218,20.0,169.81192,false,Manual,2.8",
            ["Content"] = "好嘞，我这就吩咐给您做。",
            ["ContentFR"] = "Bien reçu ! Je transmets en cuisine.",
            ["DialogueId"] = 80210304,
            ["FinalCamera"] = "-156.535156,189.371094,90.843262,0.000052,9.999997,-80.395218,20.0,169.81192,false,Manual,2.8",
            ["GUID"] = "C8CC4F00",
            ["NextDialogue"] = 80210305,
            ["SpeakNpcId"] = 790069,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC4F00",
            },
        [80210305] = {
            ["Content"] = "一斤黄酒，七个油豆腐，辣酱要多！",
            ["ContentFR"] = "Une livre de breuvage jaune, sept tofu frits, piment en extra !",
            ["DialogueId"] = 80210305,
            ["GUID"] = "C8CC4F2A",
            ["NextDialogue"] = 80210306,
            ["SpeakNpcId"] = 790069,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC4F2A",
            },
        [80210306] = {
            ["Camera"] = "-545.542969,-132.332031,36.390137,0.000018,6.600196,30.606834,20.0,466.554138,false,Manual,2.8",
            ["Content"] = "谢了。顺便问下，你可听说过一位飘零人，名唤铁掌移山刘纬甫，年纪应该有六七十了。",
            ["ContentFR"] = "Merci. Dis-moi, tu aurais entendu parler d’un Vagabond nommé Liu Weifu, surnommé Paume de Fer qui déplace les montagnes ? Il devrait avoir soixante-dix ans passés.",
            ["DialogueId"] = 80210306,
            ["FinalCamera"] = "-444.984375,-72.832031,49.90918,0.00003,6.600196,30.607128,20.0,400.820953,false,Manual,2.8",
            ["GUID"] = "C8CC4F54",
            ["NextDialogue"] = 80210307,
            ["SpeakNpcId"] = 790071,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC4F54",
            },
        [80210307] = {
            ["Content"] = "没听说过。我这辈子都没见过飘零人呢。",
            ["ContentFR"] = "Jamais entendu ce nom. À vrai dire, je n’ai jamais vu de Vagabond de ma vie.",
            ["DialogueId"] = 80210307,
            ["GUID"] = "C8CC4F7E",
            ["NextDialogue"] = 80210308,
            ["SpeakNpcId"] = 790069,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC4F7E",
            },
        [80210308] = {
            ["Camera"] = "-194.460938,93.691406,125.272461,0.000011,-19.99996,37.409882,20.0,81.55352,false,Manual,2.8",
            ["Content"] = "那你现在见过了。",
            ["ContentFR"] = "Alors voilà, c’est chose faite.",
            ["DialogueId"] = 80210308,
            ["FinalCamera"] = "-185.449219,100.574219,121.142578,0.000011,-19.99996,37.409882,20.0,81.55352,false,Manual,2.8",
            ["GUID"] = "C8CC4FA8",
            ["NextDialogue"] = 80210309,
            ["SpeakNpcId"] = 790071,
            ["ToFinalCameraBlendTime"] = 15,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC4FA8",
            },
        [80210309] = {
            ["Content"] = "您是飘零人？",
            ["ContentFR"] = "Vous êtes... un Vagabond ?",
            ["DialogueId"] = 80210309,
            ["GUID"] = "C8CC4FD2",
            ["NextDialogue"] = 80210310,
            ["SpeakNpcId"] = 790069,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC4FD2",
            },
        [80210310] = {
            ["Content"] = "我是啊，怎么，看着不像？",
            ["ContentFR"] = "Oui. Ça ne se voit pas ?",
            ["DialogueId"] = 80210310,
            ["GUID"] = "C8CC4FFC",
            ["NextDialogue"] = 80210311,
            ["SpeakNpcId"] = 790071,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC4FFC",
            },
        [80210311] = {
            ["Camera"] = "-159.164062,204.953125,88.058105,0.000052,9.999997,-80.395218,20.0,169.81192,false,Manual,2.8",
            ["Content"] = "是不像，我听说飘零人啊都是喜欢大口喝酒大口吃肉的，没见过点油豆腐的。",
            ["ContentFR"] = "Pas vraiment. On dit que les Vagabonds boivent à grandes lampées et mangent de la viande à pleines dents. Jamais vu quelqu’un commander des tofu frits.",
            ["DialogueId"] = 80210311,
            ["FinalCamera"] = "-156.535156,189.371094,90.843262,0.000052,9.999997,-80.395218,20.0,169.81192,false,Manual,2.8",
            ["GUID"] = "C8CC5026",
            ["NextDialogue"] = 80210312,
            ["SpeakNpcId"] = 790069,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC5026",
            },
        [80210312] = {
            ["Camera"] = "-235.25,3.191406,148.305176,0.000013,-19.999994,47.002541,20.0,187.784851,false,Manual,2.8",
            ["Content"] = "这叫什么话，飘零人又不是野狼野狗就爱吃肉，那吃得精细起来也是自有一套讲究的。",
            ["ContentFR"] = "Quelle idée ! Les Vagabonds ne sont pas des bêtes sauvages qui ne savent que mordre dans la chair. Quand on mange finement, on a aussi nos règles.",
            ["DialogueId"] = 80210312,
            ["FinalCamera"] = "-220.636719,18.855469,140.509766,0.000013,-19.999994,47.002541,20.0,169.81192,false,Manual,2.8",
            ["GUID"] = "C8CC5050",
            ["NextDialogue"] = 80210313,
            ["SpeakNpcId"] = 790071,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC5050",
            },
        [80210313] = {
            ["Camera"] = "-545.542969,-132.332031,36.390137,0.000018,6.600196,30.606834,20.0,466.554138,false,Manual,2.8",
            ["Content"] = "那野狼野狗也不止吃肉，还吃其他东西呢……",
            ["ContentFR"] = "Enfin... même les chiens mangent autre chose que de la viande...",
            ["DialogueId"] = 80210313,
            ["FinalCamera"] = "-462.796875,-83.355469,47.517578,0.0,6.600196,30.608337,20.0,466.554138,false,Manual,2.8",
            ["GUID"] = "C8CC507A",
            ["NextDialogue"] = 80210314,
            ["SpeakNpcId"] = 790069,
            ["ToFinalCameraBlendTime"] = 20,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC507A",
            },
        [80210314] = {
            ["Content"] = "打住，打住，我油豆腐好没？帮我催一催。",
            ["ContentFR"] = "Stop. Ça suffit. Mes tofu, c’est pour quand ? Va presser un peu.",
            ["DialogueId"] = 80210314,
            ["GUID"] = "C8CC50A4",
            ["NextDialogue"] = 80210315,
            ["SpeakNpcId"] = 790071,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC50A4",
            },
        [80210315] = {
            ["Content"] = "得嘞，卯金叔，油豆腐快点。",
            ["ContentFR"] = "Entendu ! Oncle Maojin, accélère pour les tofu !",
            ["DialogueId"] = 80210315,
            ["GUID"] = "C8CC50CE",
            ["NextDialogue"] = 80210316,
            ["SpeakNpcId"] = 790069,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC50CE",
            },
        [80210316] = {
            ["Content"] = "莫催莫催，就好了。",
            ["ContentFR"] = "Arrête de presser, ça arrive.",
            ["DialogueId"] = 80210316,
            ["GUID"] = "C8CC50F8",
            ["NextDialogue"] = 80210317,
            ["SpeakNpcId"] = 790070,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC50F8",
            },
        [80210317] = {
            ["Camera"] = "-159.164062,204.953125,88.058105,0.000052,9.999997,-80.395218,20.0,169.81192,false,Manual,2.8",
            ["Content"] = "行。客官您再等等。不过，刚刚您说飘零人吃起来自有一套，要不多讲讲呗，反正现在店里也没人，想听。",
            ["ContentFR"] = "Très bien. Patientez encore un instant, cher client. Mais au fait... vous disiez que les Vagabonds mangent selon leurs propres règles. Racontez donc. La salle est vide, j’aimerais bien écouter.",
            ["DialogueId"] = 80210317,
            ["FinalCamera"] = "-156.535156,189.371094,90.843262,0.000052,9.999997,-80.395218,20.0,169.81192,false,Manual,2.8",
            ["GUID"] = "C8CC5122",
            ["NextDialogue"] = 80210318,
            ["SpeakNpcId"] = 790069,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC5122",
            },
        [80210318] = {
            ["Camera"] = "-235.25,3.191406,148.305176,0.000013,-19.999994,47.002541,20.0,187.784851,false,Manual,2.8",
            ["Content"] = "也罢，我今天来找的这位飘零人前辈，当年也以做得一手好菜闻名，被称作庖侠。",
            ["ContentFR"] = "Soit. Le Vagabond que je cherche aujourd’hui était autrefois célèbre pour sa cuisine. On le surnommait le Vagabond des Fourneaux.",
            ["DialogueId"] = 80210318,
            ["FinalCamera"] = "-208.675781,31.691406,134.121582,0.000012,-19.999954,47.00246,20.0,150.472961,false,Manual,2.8",
            ["GUID"] = "C8CC514C",
            ["NextDialogue"] = 80210319,
            ["SpeakNpcId"] = 790071,
            ["ToFinalCameraBlendTime"] = 20,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC514C",
            },
        [80210319] = {
            ["Content"] = "他老人家最知名的一手是“若木无觅衔烛龙”，号称是能把维系大风九章的那白龙斩了做宴席。",
            ["ContentFR"] = "Son plat le plus fameux s’appelait « Le Dragon-Flamme inaccessible ». On racontait qu’il avait abattu le Dragon d’Argent qui soutenait les Neuf Chapitres de Dafeng pour en faire un banquet.",
            ["DialogueId"] = 80210319,
            ["GUID"] = "C8CC5176",
            ["NextDialogue"] = 80210320,
            ["SpeakNpcId"] = 790071,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC5176",
            },
        [80210320] = {
            ["Content"] = "实际上呢，是用各种飞禽走兽的肉分别以掌力击碎，再绞制成型。这样一来，一口下去可以尝出百般滋味，所以敢自称是龙肉。",
            ["ContentFR"] = "En réalité, il écrasait des viandes de bêtes et d’oiseaux variés à coups de paume, puis les façonnait ensemble. Une bouchée, cent saveurs — d’où le nom de « chair de dragon ».",
            ["DialogueId"] = 80210320,
            ["GUID"] = "C8CC51A0",
            ["NextDialogue"] = 80210321,
            ["SpeakNpcId"] = 790071,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC51A0",
            },
        [80210321] = {
            ["Content"] = "然后再又以极其滑嫩的豆腐作为基底，与诸多畜类的脊髓骨髓一同炒制，让它们的香味渗入豆腐中，号称龙髓。",
            ["ContentFR"] = "Ensuite, il utilisait du tofu d’une douceur extrême comme base, sauté avec des moelles animales, afin que les parfums pénètrent la chair blanche. Il appelait cela la « moelle de dragon ».",
            ["DialogueId"] = 80210321,
            ["GUID"] = "C8CC51CA",
            ["NextDialogue"] = 80210322,
            ["SpeakNpcId"] = 790071,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC51CA",
            },
        [80210322] = {
            ["Camera"] = "-159.164062,204.953125,88.058105,0.000052,9.999997,-80.395218,20.0,169.81192,false,Manual,2.8",
            ["Content"] = "客官您说笑了，豆腐就是豆腐，怎么能号称是龙髓呢。要这么说，我们店卖的油豆腐，也能叫炸龙髓了。",
            ["ContentFR"] = "Allons donc ! Du tofu reste du tofu. Comment appeler ça de la moelle de dragon ? À ce compte-là, nos tofu frits seraient de la « moelle de dragon frit ».",
            ["DialogueId"] = 80210322,
            ["FinalCamera"] = "-156.535156,189.371094,90.843262,0.000052,9.999997,-80.395218,20.0,169.81192,false,Manual,2.8",
            ["GUID"] = "C8CC51F4",
            ["NextDialogue"] = 80210323,
            ["SpeakNpcId"] = 790069,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC51F4",
            },
        [80210323] = {
            ["Camera"] = "-194.460938,93.691406,125.272461,0.000011,-19.99996,37.409882,20.0,81.55352,false,Manual,2.8",
            ["Content"] = "哎，我也是听师父说过而已。那位铁掌移山刘纬甫早早金盆洗手，如今没人知道他身在何方。",
            ["ContentFR"] = "Je ne fais que répéter ce que mon maître racontait. Liu Weifu a quitté le monde martial depuis longtemps. Nul ne sait où il vit aujourd’hui.",
            ["DialogueId"] = 80210323,
            ["FinalCamera"] = "-185.449219,100.574219,121.142578,0.000011,-19.99996,37.409882,20.0,81.55352,false,Manual,2.8",
            ["GUID"] = "C8CC521E",
            ["NextDialogue"] = 80210324,
            ["SpeakNpcId"] = 790071,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC521E",
            },
        [80210324] = {
            ["Camera"] = "-1040.925781,1113.558594,298.16748,0.000131,-4.398683,-49.787758,30.000002,1361.954834,false,Manual,2.8",
            ["Content"] = "说半天说得我都流口水了，原来您没吃过啊。行了那别说这些虚无缥缈的了，来尝尝这个吧，我们店招牌的油豆腐。",
            ["ContentFR"] = "Tout ce discours me donne faim... et tu n’as même jamais goûté ? Assez rêvé. Goûte plutôt ça — la spécialité de la maison.",
            ["DialogueId"] = 80210324,
            ["FinalCamera"] = "-847.84375,934.597656,274.614746,0.000131,-6.0,-49.78775,30.000002,1361.954834,false,Manual,2.8",
            ["GUID"] = "C8CC5248",
            ["NextDialogue"] = 80210325,
            ["SpeakNpcId"] = 790069,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC5248",
            },
        [80210325] = {
            ["Content"] = "……我来尝尝。",
            ["ContentFR"] = "... Très bien, je goûte.",
            ["DialogueId"] = 80210325,
            ["GUID"] = "C8CC5272",
            ["SpeakNpcId"] = 790071,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC5272",
            },
        [80210326] = {
            ["Content"] = "啊……烫，但……好好吃。",
            ["ContentFR"] = "Ah— ! C’est brûlant... mais... délicieux.",
            ["DialogueId"] = 80210326,
            ["GUID"] = "C8CC529C",
            ["IsBlack"] = 1,
            ["LookAt"] = {
                [1] = "790071:n(790069)",
                [2] = "790069:n(790071)",
                },
            ["NextDialogue"] = 80210327,
            ["Scripts"] = "PlayAnimation{ActorId{790071},AnimationId{\"Sit_Idle_Loop\"},Sync{true}}",
            ["SpeakNpcId"] = 790071,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC529C",
            },
        [80210327] = {
            ["Content"] = "嘶哈——",
            ["ContentFR"] = "Tss—ha...",
            ["DialogueId"] = 80210327,
            ["GUID"] = "C8CC52C6",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 80210328,
            ["SpeakNpcId"] = 790071,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC52C6",
            },
        [80210328] = {
            ["Camera"] = "-194.460938,93.691406,125.272461,0.000011,-19.99996,37.409882,20.0,81.55352,false,Manual,2.8",
            ["Content"] = "表皮被炸得酥脆，咬下去嘎吱作响，而里面的豆腐却软嫩绵滑，却又不至于立刻散掉，得要相当的力道和巧劲才能做到这个地步。",
            ["ContentFR"] = "La croûte est croustillante, elle craque sous la dent. À l’intérieur, le tofu est souple, soyeux, sans se déliter. Il faut une force précise et un contrôle parfait pour obtenir ça.",
            ["DialogueId"] = 80210328,
            ["FinalCamera"] = "-189.175781,97.710938,122.863281,0.00001,-19.999954,37.409824,20.0,81.55352,false,Manual,2.8",
            ["GUID"] = "C8CC52F0",
            ["NextDialogue"] = 80210329,
            ["SpeakNpcId"] = 790071,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC52F0",
            },
        [80210329] = {
            ["Camera"] = "-159.164062,204.953125,88.058105,0.000052,9.999997,-80.395218,20.0,169.81192,false,Manual,2.8",
            ["Content"] = "算你识货，我们卯金叔做得油豆腐可是远近闻名，想来啊，不比那什么“若木无觅衔烛龙”差。",
            ["ContentFR"] = "Tu t’y connais. Les tofu d’Oncle Maojin sont réputés dans toute la région. Pas moins bons que ton fameux « Dragon-Flamme inaccessible ».",
            ["DialogueId"] = 80210329,
            ["FinalCamera"] = "-156.535156,189.371094,90.843262,0.000052,9.999997,-80.395218,20.0,169.81192,false,Manual,2.8",
            ["GUID"] = "C8CC531A",
            ["NextDialogue"] = 80210330,
            ["SpeakNpcId"] = 790069,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC531A",
            },
        [80210330] = {
            ["Content"] = "等等……莫非……",
            ["ContentFR"] = "Attends... ne me dis pas que...",
            ["DialogueId"] = 80210330,
            ["FacialId"] = {
                [1] = "790071:Shock01",
                },
            ["GUID"] = "C8CC5344",
            ["NextDialogue"] = 80210331,
            ["SpeakNpcId"] = 790071,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC5344",
            },
        [80210331] = {
            ["Camera"] = "-291.878906,37.308594,153.111328,0.000122,-8.597596,-25.187979,30.000013,264.169495,false,Manual,2.8",
            ["Content"] = "就你个瓜娃儿话多，莫要和客人摆龙门阵了，又有油豆腐弄好了，上菜。",
            ["ContentFR"] = "Espèce de bavard ! Arrête de raconter des histoires au client. Les tofu sont prêts, sers.",
            ["DialogueId"] = 80210331,
            ["FinalCamera"] = "-241.59375,9.6875,154.276855,0.000128,-8.597521,-24.999588,30.000013,185.753601,false,Manual,2.8",
            ["GUID"] = "C8CC536E",
            ["NextDialogue"] = 80210332,
            ["Scripts"] = "MoveTo{ActorId{790070},TargetPoint{\"BP_NewTargetPoint_150303_1\"},MoveSpeed{150}}",
            ["SpeakNpcId"] = 790070,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC536E",
            },
        [80210332] = {
            ["Content"] = "得嘞。",
            ["ContentFR"] = "Oui !",
            ["DialogueId"] = 80210332,
            ["Duration"] = 5,
            ["GUID"] = "C8CC5398",
            ["LookAt"] = {
                [1] = "790069:n(790069)",
                },
            ["NextDialogue"] = 80210333,
            ["Scripts"] = "MoveTo{ActorId{790069},TargetPoint{\"BP_NewTargetPoint_150303_2\"},MoveSpeed{150},Visibility{\"Hide\"}}",
            ["SpeakNpcId"] = 790069,
            ["TurnTo"] = {
                [1] = "790070:n(790071)",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC5398",
            },
        [80210333] = {
            ["Camera"] = "-201.753906,194.632812,93.111328,0.000129,1.999995,-50.996628,20.0,305.107788,false,Manual,2.8",
            ["Content"] = "尝出来了？",
            ["ContentFR"] = "Alors ? Tu as reconnu ?",
            ["DialogueId"] = 80210333,
            ["FinalCamera"] = "-191.488281,181.953125,93.680664,0.000129,1.999995,-50.996746,20.0,305.107788,false,Manual,2.8",
            ["GUID"] = "C8CC53C2",
            ["LookAt"] = {
                [1] = "790071:n(790070)",
                },
            ["NextDialogue"] = 80210334,
            ["SpeakNpcId"] = 790070,
            ["ToFinalCameraBlendTime"] = 5,
            ["TurnTo"] = {
                [1] = "790070:n(790071)",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC53C2",
            },
        [80210334] = {
            ["Camera"] = "-194.460938,93.691406,125.272461,0.000011,-19.99996,37.409882,20.0,81.55352,false,Manual,2.8",
            ["Content"] = "尝出来了，前辈的手艺果然名不虚传，难怪我师父这么多年一直念念不忘。",
            ["ContentFR"] = "Oui. Votre savoir-faire est intact. Je comprends pourquoi mon maître ne vous a jamais oublié.",
            ["DialogueId"] = 80210334,
            ["FacialId"] = {
                [1] = "790071:Smile01",
                },
            ["FinalCamera"] = "-189.175781,97.710938,122.863281,0.00001,-19.999954,37.409824,20.0,81.55352,false,Manual,2.8",
            ["GUID"] = "C8CC53EC",
            ["NextDialogue"] = 80210335,
            ["SpeakNpcId"] = 790071,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC53EC",
            },
        [80210335] = {
            ["Camera"] = "-187.410156,43.980469,119.370605,0.00013,1.999995,-44.796921,20.0,171.840973,false,Manual,2.8",
            ["Content"] = "净讲这些虚的干啥子嘞，你吃东西是为自己吃的还是为你师父吃的？讲你自己的想法。",
            ["ContentFR"] = "Arrête les belles paroles. Tu manges pour toi ou pour ton maître ? Dis ce que tu en penses, toi.",
            ["DialogueId"] = 80210335,
            ["FinalCamera"] = "-198.394531,31.234375,119.370605,0.00013,1.999995,-39.196651,20.0,171.840973,false,Manual,2.8",
            ["GUID"] = "C8CC5416",
            ["NextDialogue"] = 80210336,
            ["SpeakNpcId"] = 790070,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC5416",
            },
        [80210336] = {
            ["Camera"] = "-400.648438,-387.972656,82.464844,0.000133,1.999995,51.002842,20.0,592.152588,false,Manual,2.8",
            ["Content"] = "好吃！",
            ["ContentFR"] = "C’est excellent !",
            ["DialogueId"] = 80210336,
            ["FinalCamera"] = "-314.59375,-444.601562,82.464844,0.000134,1.999995,62.002323,20.0,592.152588,false,Manual,2.8",
            ["GUID"] = "C8CC5440",
            ["NextDialogue"] = 80210337,
            ["SpeakNpcId"] = 790071,
            ["ToFinalCameraBlendTime"] = 20,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC5440",
            },
        [80210337] = {
            ["Content"] = "对头，那好吃的话应该怎么做啊？",
            ["ContentFR"] = "Voilà. Et quand c’est bon, on fait quoi ?",
            ["DialogueId"] = 80210337,
            ["GUID"] = "C8CC546A",
            ["NextDialogue"] = 80210338,
            ["SpeakNpcId"] = 790070,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC546A",
            },
        [80210338] = {
            ["Content"] = "再来七块！",
            ["ContentFR"] = "On en reprend sept !",
            ["DialogueId"] = 80210338,
            ["GUID"] = "C8CC5494",
            ["NextDialogue"] = 80210339,
            ["SpeakNpcId"] = 790071,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC5494",
            },
        [80210339] = {
            ["Content"] = "嘞就对嘛。",
            ["ContentFR"] = "Voilà qui est parlé.",
            ["DialogueId"] = 80210339,
            ["GUID"] = "C8CC54BE",
            ["NextDialogue"] = 80210340,
            ["SpeakNpcId"] = 790070,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC54BE",
            },
        [80210340] = {
            ["Camera"] = "-187.410156,43.980469,119.370605,0.00013,1.999995,-44.796921,20.0,171.840973,false,Manual,2.8",
            ["Content"] = "好，吃的问题解决了，现在你告诉我，你师父是哪一个？",
            ["ContentFR"] = "Bien. Maintenant que tu as mangé, dis-moi : qui est ton maître ?",
            ["DialogueId"] = 80210340,
            ["FinalCamera"] = "-198.394531,31.234375,119.370605,0.00013,1.999995,-39.196651,20.0,171.840973,false,Manual,2.8",
            ["GUID"] = "C8CC54E8",
            ["NextDialogue"] = 80210341,
            ["SpeakNpcId"] = 790070,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC54E8",
            },
        [80210341] = {
            ["Camera"] = "-194.460938,93.691406,125.272461,0.000011,-19.99996,37.409882,20.0,81.55352,false,Manual,2.8",
            ["Content"] = "宴山亭。",
            ["ContentFR"] = "Yan Shanting.",
            ["DialogueId"] = 80210341,
            ["FinalCamera"] = "-189.175781,97.710938,122.863281,0.00001,-19.999954,37.409824,20.0,81.55352,false,Manual,2.8",
            ["GUID"] = "C8CC5512",
            ["NextDialogue"] = 80210342,
            ["SpeakNpcId"] = 790067,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC5512",
            },
        [80210342] = {
            ["Camera"] = "-187.410156,43.980469,119.370605,0.00013,1.999995,-44.796921,20.0,171.840973,false,Manual,2.8",
            ["Content"] = "喔，原来是他，是为了论剑而来的吧？没想到他还记得这个事。",
            ["ContentFR"] = "Ah... lui. Tu viens pour l’épreuve de l’épée, alors ? Je ne pensais pas qu’il s’en souviendrait encore.",
            ["DialogueId"] = 80210342,
            ["FinalCamera"] = "-198.394531,31.234375,119.370605,0.00013,1.999995,-39.196651,20.0,171.840973,false,Manual,2.8",
            ["GUID"] = "C8CC553C",
            ["NextDialogue"] = 80210343,
            ["SpeakNpcId"] = 790070,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC553C",
            },
        [80210343] = {
            ["Camera"] = "-104.40625,-155.425781,163.111328,0.000038,-19.999928,85.208679,20.0,314.309692,false,Manual,2.8",
            ["Content"] = "师父念念不忘，敢问刘前辈会参加吗？",
            ["ContentFR"] = "Il ne l’a jamais oubliée. Puis-je vous demander si vous y participerez, Maître Liu ?",
            ["DialogueId"] = 80210343,
            ["FacialId"] = {
                [1] = "790071:Smile01",
                },
            ["FinalCamera"] = "-102.179688,-128.832031,153.394531,0.000038,-19.999928,85.208679,20.0,314.309692,false,Manual,2.8",
            ["GUID"] = "C8CC5566",
            ["NextDialogue"] = 80210344,
            ["SpeakNpcId"] = 790071,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC5566",
            },
        [80210344] = {
            ["Camera"] = "-201.753906,194.632812,93.111328,0.000129,1.999995,-50.996628,20.0,305.107788,false,Manual,2.8",
            ["Content"] = "这里没有刘前辈，我早已放下刀，这里只有卯金叔。",
            ["ContentFR"] = "Il n’y a plus de Maître Liu ici. J’ai posé la lame depuis longtemps. Il n’y a que Oncle Maojin.",
            ["DialogueId"] = 80210344,
            ["FinalCamera"] = "-191.488281,181.953125,93.680664,0.000129,1.999995,-50.996746,20.0,305.107788,false,Manual,2.8",
            ["GUID"] = "C8CC5590",
            ["NextDialogue"] = 80210345,
            ["SpeakNpcId"] = 790070,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC5590",
            },
        [80210345] = {
            ["Content"] = "好了，莫要再问了，再要七个油豆腐是吧，我这就继续。",
            ["ContentFR"] = "Assez parlé. Encore sept tofu, c’est ça ? Je m’y remets.",
            ["DialogueId"] = 80210345,
            ["GUID"] = "C8CC55BA",
            ["NextDialogue"] = 80210346,
            ["SpeakNpcId"] = 790070,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC55BA",
            },
        [80210346] = {
            ["Camera"] = "-194.460938,93.691406,125.272461,0.000011,-19.99996,37.409882,20.0,81.55352,false,Manual,2.8",
            ["Content"] = "……再来七个，打包带走，我也让我朋友尝一尝。",
            ["ContentFR"] = "... Sept de plus. À emporter. Je veux que mes amis y goûtent.",
            ["DialogueId"] = 80210346,
            ["FacialId"] = {
                [1] = "790071:Smile01",
                },
            ["FinalCamera"] = "-189.175781,97.710938,122.863281,0.00001,-19.999954,37.409824,20.0,81.55352,false,Manual,2.8",
            ["GUID"] = "C8CC55E4",
            ["NextDialogue"] = 80210347,
            ["SpeakNpcId"] = 790071,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC55E4",
            },
        [80210347] = {
            ["Camera"] = "-400.648438,-387.972656,82.464844,0.000133,1.999995,51.002842,20.0,592.152588,false,Manual,2.8",
            ["Content"] = "要得，但切记，只许和朋友说这是卯金叔做的，要是多说一句，我把你舌头割下来做成卤菜。",
            ["ContentFR"] = "Très bien. Mais souviens-toi : dis seulement que c’est Oncle Maojin qui les a faits. Un mot de trop, et je te coupe la langue pour la faire braiser.",
            ["DialogueId"] = 80210347,
            ["FinalCamera"] = "-544.378906,-565.476562,74.48877,0.000132,1.999995,51.004082,20.0,592.152588,false,Manual,2.8",
            ["GUID"] = "C8CC560E",
            ["NextDialogue"] = 80210348,
            ["SpeakNpcId"] = 790070,
            ["ToFinalCameraBlendTime"] = 20,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC560E",
            },
        [80210348] = {
            ["Content"] = "那是自然，那么后生拜别前辈。",
            ["ContentFR"] = "Naturellement. Alors, le cadet prend congé.",
            ["DialogueId"] = 80210348,
            ["GUID"] = "C8CC5638",
            ["SpeakNpcId"] = 790071,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC5638",
            },
        [80210401] = {
            ["Camera"] = "-15.96875,236.780762,198.734375,0.00004,-1.999995,63.206463,40.310993,407.767792,false,Manual,2.8",
            ["Content"] = "一大早的，还没睡醒呢就把人吵起来，是要去哪儿？",
            ["ContentFR"] = "De si bon matin... Tu réveilles les gens sans prévenir. On va où, au juste ?",
            ["DialogueId"] = 80210401,
            ["FacialId"] = {
                [1] = "790008:Doubt01",
                },
            ["FinalCamera"] = "0.390625,269.174805,197.469727,0.00004,-1.999995,63.206463,40.310993,407.767792,false,Manual,2.8",
            ["GUID"] = "C8CC5EEA",
            ["LookAt"] = {
                [1] = "790008:n(790067)",
                [2] = "790067:n(790008)",
                },
            ["NextDialogue"] = 80210402,
            ["SpeakNpcId"] = 790008,
            ["TalkActionId"] = {
                [1] = "790008:Confident_Start",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC5EEA",
            },
        [80210402] = {
            ["Camera"] = "15.414062,815.271973,212.397461,0.000014,-4.60016,-71.792816,40.310993,430.446808,false,Manual,2.8",
            ["Content"] = "比武论剑，二十年一次。",
            ["ContentFR"] = "À l’épreuve de l’épée. Elle n’a lieu qu’une fois tous les vingt ans.",
            ["DialogueId"] = 80210402,
            ["FacialId"] = {
                [1] = "790067:Confident01",
                },
            ["FinalCamera"] = "28.40625,774.96582,208.994141,0.000013,-4.60016,-72.792603,40.310993,430.446808,false,Manual,2.8",
            ["GUID"] = "C8CC5F14",
            ["NextDialogue"] = 80210403,
            ["SpeakNpcId"] = 790067,
            ["TalkActionId"] = {
                [1] = "790067:Talk03_Start",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC5F14",
            },
        [80210403] = {
            ["Camera"] = "-748.292969,-30.820801,161.345703,0.000053,0.0,31.808994,40.310993,975.20166,false,Manual,2.8",
            ["Content"] = "说这个我就不困了，谁和谁啊？",
            ["ContentFR"] = "Ah, là je suis {性别:réveillé|réveillée}. Qui contre qui ?",
            ["DialogueId"] = 80210403,
            ["FinalCamera"] = "-626.019531,45.025391,161.345703,0.000053,0.0,31.809633,40.310993,872.170044,false,Manual,2.8",
            ["GUID"] = "C8CC5F3E",
            ["NextDialogue"] = 80210404,
            ["SpeakNpcId"] = 790008,
            ["TalkActionId"] = {
                [1] = "790008:Confident_End",
                },
            ["ToFinalCameraBlendTime"] = 20,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC5F3E",
            },
        [80210404] = {
            ["Content"] = "华胥有头有脸的飘零人理应都会来，之前已经举行过七八次了，大家会在山巅互相比试，直到分出胜负。",
            ["ContentFR"] = "Tous les Vagabonds de Huaxu un tant soit peu renommés sont censés venir. Ça a déjà eu lieu sept ou huit fois. On se retrouve au sommet, on se mesure... jusqu’à ce qu’il n’en reste qu’un.",
            ["DialogueId"] = 80210404,
            ["GUID"] = "C8CC5F68",
            ["NextDialogue"] = 80210405,
            ["SpeakNpcId"] = 790067,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC5F68",
            },
        [80210405] = {
            ["Camera"] = "-15.96875,236.780762,198.734375,0.00004,-1.999995,63.206463,40.310993,407.767792,false,Manual,2.8",
            ["Content"] = "那么这次，会有多少人参加？",
            ["ContentFR"] = "Et cette fois, combien seront-ils ?",
            ["DialogueId"] = 80210405,
            ["FinalCamera"] = "0.390625,269.174805,197.469727,0.00004,-1.999995,63.206463,40.310993,407.767792,false,Manual,2.8",
            ["GUID"] = "C8CC5F92",
            ["NextDialogue"] = 80210406,
            ["SpeakNpcId"] = 790008,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC5F92",
            },
        [80210406] = {
            ["Camera"] = "-26.566406,613.213379,186.345703,0.000053,0.0,-59.788727,40.310993,251.490341,false,Manual,2.8",
            ["Content"] = "等到了你就知道了。",
            ["ContentFR"] = "Tu verras bien en arrivant.",
            ["DialogueId"] = 80210406,
            ["FinalCamera"] = "-14.558594,592.585449,193.345703,0.000053,0.0,-59.788727,40.310993,213.980072,false,Manual,2.8",
            ["GUID"] = "C8CC5FBC",
            ["SpeakNpcId"] = 790067,
            ["TalkActionId"] = {
                [1] = "790067:Talk03_End",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC5FBC",
            },
        [80210407] = {
            ["Camera"] = "976.125,1795.242676,518.382812,0.000097,-9.999997,-118.000748,26.65424,2016.868164,false,Manual,2.8",
            ["Content"] = "跟着刻舟到了一处相当荒僻的山间，想来这就是他们此前比武论剑之地了。",
            ["ContentFR"] = "Vous suivez Kezhou jusqu’au cœur d’une région montagneuse reculée. C’est sans doute ici que se tenait autrefois l’épreuve de l’épée.",
            ["DialogueId"] = 80210407,
            ["FinalCamera"] = "882.355469,1518.284668,467.509766,0.000097,-9.999964,-118.000748,26.65424,1751.967041,false,Manual,2.8",
            ["GUID"] = "C8CC5FE6",
            ["NextDialogue"] = 80210408,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC5FE6",
            },
        [80210408] = {
            ["Content"] = "但见满目新绿，飞泉直下。是适合比试的场地，只是，似乎有些过于冷清……",
            ["ContentFR"] = "Partout, une verdure nouvelle s’étend à perte de vue ; des cascades dévalent la roche en nappes argentées. Le lieu se prêterait idéalement à un affrontement... Et pourtant, un silence étrange y règne.",
            ["DialogueId"] = 80210408,
            ["GUID"] = "C8CC6010",
            ["NextDialogue"] = 80210409,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC6010",
            },
        [80210409] = {
            ["Camera"] = "511.71875,-314.994141,144.21875,0.000125,-4.000004,125.200066,42.362053,376.295776,false,Manual,2.8",
            ["Content"] = "怎么只有我们俩，不是说有头有脸的飘零人都会来吗？",
            ["ContentFR"] = "Pourquoi on est que tous les deux ? Tu disais que tous les Vagabonds importants viendraient.",
            ["DialogueId"] = 80210409,
            ["FacialId"] = {
                [1] = "790008:Doubt01",
                },
            ["FinalCamera"] = "491.65625,-286.541504,141.78418,0.000125,-4.000004,125.200066,42.362053,376.295776,false,Manual,2.8",
            ["GUID"] = "C8CC603A",
            ["LookAt"] = {
                [1] = "790067:n(790008)",
                },
            ["NextDialogue"] = 80210410,
            ["SpeakNpcId"] = 790008,
            ["TalkActionId"] = {
                [1] = "790008:Sigh_Start",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC603A",
            },
        [80210410] = {
            ["Camera"] = "434.003906,248.654785,121.818359,0.000152,1.999995,-107.80146,42.362053,398.766113,false,Manual,2.8",
            ["Content"] = "说来惭愧，现在有头有脸的飘零人也不剩几位了，正所谓江湖儿女日渐少。",
            ["ContentFR"] = "À vrai dire... il ne reste plus beaucoup de Vagabonds dignes de ce nom. Les gens du Jianghu se font de plus en plus rares.",
            ["DialogueId"] = 80210410,
            ["FacialId"] = {
                [1] = "790067:Sad01",
                },
            ["FinalCamera"] = "408.511719,168.209961,124.753906,0.000153,2.99999,-105.801682,42.362053,306.325958,false,Manual,2.8",
            ["GUID"] = "C8CC6064",
            ["NextDialogue"] = 80210411,
            ["SpeakNpcId"] = 790067,
            ["TalkActionId"] = {
                [1] = "790008:Sigh_End",
                [2] = "790067:Talk01_Start",
                },
            ["ToFinalCameraBlendTime"] = 40,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC6064",
            },
        [80210411] = {
            ["Content"] = "且不说这次，就是上一次参加比武论剑的飘零人，仅有四位而已。",
            ["ContentFR"] = "Et ce n’est pas seulement cette fois-ci. La dernière fois déjà, il n’y avait que quatre Vagabonds.",
            ["DialogueId"] = 80210411,
            ["FacialId"] = {
                [1] = "790008:None",
                },
            ["GUID"] = "C8CC608E",
            ["LookAt"] = {
                [1] = "790008:n(790067)",
                },
            ["NextDialogue"] = 80210412,
            ["SpeakNpcId"] = 790067,
            ["TalkActionId"] = {
                [1] = "790067:Talk01_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC608E",
            },
        [80210412] = {
            ["Content"] = "第一位呢，便是我的师父宴山亭。虽然他已经离世，但是在离世前对这比武论剑念念不忘，让我代他出战。",
            ["ContentFR"] = "Le premier, c’était mon maître, Yan Shanting. Il est mort depuis, mais jusqu’à la fin il n’a jamais cessé de penser à cette épreuve. Il m’a demandé de combattre à sa place.",
            ["DialogueId"] = 80210412,
            ["FacialId"] = {
                [1] = "790067:None",
                },
            ["GUID"] = "C8CC60B8",
            ["NextDialogue"] = 80210413,
            ["SpeakNpcId"] = 790067,
            ["TalkActionId"] = {
                [1] = "790067:Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC60B8",
            },
        [80210413] = {
            ["Content"] = "于是我就走访了各处，找到了另外三位当年参加了比武论剑的高手。",
            ["ContentFR"] = "Alors je suis allé retrouver les trois autres qui avaient participé autrefois.",
            ["DialogueId"] = 80210413,
            ["GUID"] = "C8CC60E2",
            ["NextDialogue"] = 80210414,
            ["SpeakNpcId"] = 790067,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC60E2",
            },
        [80210414] = {
            ["Content"] = "我先找了其中一位善于用剑的女侠，也是上次论剑时夺得魁首的天下第一。但却连面也没见到。",
            ["ContentFR"] = "La première était une grande épéiste — celle qui avait remporté la victoire la dernière fois, la véritable « Première sous le Ciel ». Mais je ne l’ai même pas vue.",
            ["DialogueId"] = 80210414,
            ["GUID"] = "C8CC610C",
            ["NextDialogue"] = 80210415,
            ["SpeakNpcId"] = 790067,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC610C",
            },
        [80210415] = {
            ["Content"] = "我师父一直说她爱剑成痴，大部分时候甚至不愿意拔剑，只以剑鞘伤人，又早早归隐，远离江湖，所以并没有被大风九章盯上。",
            ["ContentFR"] = "Mon maître disait qu’elle aimait l’épée à l’excès. Souvent, elle refusait même de la dégainer, se contentant de frapper avec le fourreau. Elle s’est retirée très tôt du monde, loin des conflits — et ainsi, elle n’a jamais attiré l’attention des Neuf Chapitres de Dafeng.",
            ["DialogueId"] = 80210415,
            ["GUID"] = "C8CC6136",
            ["NextDialogue"] = 80210416,
            ["SpeakNpcId"] = 790067,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC6136",
            },
        [80210416] = {
            ["Content"] = "现如今，却把自己的佩剑拿去当孩子的玩物，想必是不愿踏足江湖，只想躲进小楼，远离纷扰，那么我也没有多打扰她。",
            ["ContentFR"] = "Aujourd’hui, elle laisse même ses enfants jouer avec son arme. Elle ne veut plus remettre les pieds dans le Jianghu. Alors je ne l’ai pas dérangée.",
            ["DialogueId"] = 80210416,
            ["GUID"] = "C8CC6160",
            ["NextDialogue"] = 80210417,
            ["SpeakNpcId"] = 790067,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC6160",
            },
        [80210417] = {
            ["Content"] = "师父一直说她有大智慧，我此前都不明白，这次见了……不，这次没见到她，但是也已经明白师父为什么会这么说了。",
            ["ContentFR"] = "Mon maître disait toujours qu’elle possédait une grande sagesse. Je ne comprenais pas... Mais cette fois, même sans la voir, j’ai compris pourquoi.",
            ["DialogueId"] = 80210417,
            ["GUID"] = "C8CC618A",
            ["NextDialogue"] = 80210418,
            ["SpeakNpcId"] = 790067,
            ["TalkActionId"] = {
                [1] = "790067:Talk02_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC618A",
            },
        [80210418] = {
            ["Camera"] = "478.570312,-143.509766,121.444336,0.000169,2.99999,132.400314,42.362053,217.393646,false,Manual,2.8",
            ["Content"] = "嗯，换做是我的话，我应该也会这么做。",
            ["ContentFR"] = "À sa place... j’aurais sans doute fait pareil.",
            ["DialogueId"] = 80210418,
            ["FinalCamera"] = "472.527344,-136.883301,121.911133,0.00017,2.99999,132.400513,42.362053,217.393646,false,Manual,2.8",
            ["GUID"] = "C8CC61B4",
            ["NextDialogue"] = 80210419,
            ["SpeakNpcId"] = 790008,
            ["TalkActionId"] = {
                [1] = "790008:AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC61B4",
            },
        [80210419] = {
            ["Camera"] = "925.164062,204.170898,224.050781,0.000123,-9.999943,-150.992493,26.65424,679.187683,false,Manual,2.8",
            ["Content"] = "再一位呢，唤作鸣鸾，比我年长一点，自幼就被认定是习武的天才，年少成名，以弱冠之龄便能参加比武论剑。",
            ["ContentFR"] = "Le deuxième s’appelle Mingluan. Un peu plus âgé que moi. Un prodige reconnu dès l’enfance, célèbre très jeune, capable de participer à l’épreuve avant même l’âge adulte.",
            ["DialogueId"] = 80210419,
            ["FinalCamera"] = "742.019531,445.837402,225.842773,0.000124,-9.999943,-129.189941,26.65424,679.187683,false,Manual,2.8",
            ["GUID"] = "C8CC61DE",
            ["NextDialogue"] = 80210420,
            ["SpeakNpcId"] = 790067,
            ["TalkActionId"] = {
                [1] = "790067:Talk02R_Start",
                },
            ["ToFinalCameraBlendTime"] = 40,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC61DE",
            },
        [80210420] = {
            ["Content"] = "他本有一位红颜知己，剑法同样精微，一直与他快意恩仇，人人都觉得他们是一对璧人，天作之合。",
            ["ContentFR"] = "Il avait une compagne, une femme qu’il aimait. Son épée était aussi fine que la sienne. Ils parcouraient le monde ensemble, vivant leurs rancunes et leurs justices. Tout le monde pensait qu’ils étaient faits l’un pour l’autre.",
            ["DialogueId"] = 80210420,
            ["GUID"] = "C8CC6208",
            ["NextDialogue"] = 80210421,
            ["SpeakNpcId"] = 790067,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC6208",
            },
        [80210421] = {
            ["Content"] = "但是再多的快意恩仇也会让人厌倦，那位红颜知己厌倦了终日飘零，不得不躲避应天尉追杀的生活。",
            ["ContentFR"] = "Mais à force d’errance, même la liberté lasse. Elle s’est fatiguée de fuir sans cesse,\
de vivre sous la menace des Magistrats de Yingtian.",
            ["DialogueId"] = 80210421,
            ["GUID"] = "C8CC6232",
            ["NextDialogue"] = 80210422,
            ["SpeakNpcId"] = 790067,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC6232",
            },
        [80210422] = {
            ["Content"] = "于是他们相约，在某日一起离开华胥，去大陆的其他地方，过安稳日子。",
            ["ContentFR"] = "Ils s’étaient promis de quitter Huaxu ensemble, pour mener ailleurs une vie paisible.",
            ["DialogueId"] = 80210422,
            ["GUID"] = "C8CC625C",
            ["NextDialogue"] = 80210423,
            ["SpeakNpcId"] = 790067,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC625C",
            },
        [80210423] = {
            ["Content"] = "只是他们许约的那一日，偏偏又是论剑的日子。而鸣鸾被年少盛名所累，想要等到比武结束后，夺了第一的名号后与那位知己再一同离开华胥。",
            ["ContentFR"] = "Mais le jour convenu tombait... le jour même de l’épreuve. Mingluan, prisonnier de sa réputation, a voulu combattre une dernière fois, remporter le titre... puis partir avec elle.",
            ["DialogueId"] = 80210423,
            ["GUID"] = "C8CC6286",
            ["NextDialogue"] = 80210424,
            ["SpeakNpcId"] = 790067,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC6286",
            },
        [80210424] = {
            ["Content"] = "但高手对决，又怎么会几招内分出胜负，他们斗了三个日夜。等鸣鸾比试结束，前去赴约时，眼前所见只有江上数峰青山，不见人影。",
            ["ContentFR"] = "Les combats entre maîtres ne se décident pas en quelques échanges. Ils se sont battus trois jours et trois nuits. Quand il est allé au rendez-vous, il n’a vu que des montagnes bleutées au bord du fleuve. Personne ne l’attendait.",
            ["DialogueId"] = 80210424,
            ["GUID"] = "C8CC62B0",
            ["NextDialogue"] = 80210425,
            ["SpeakNpcId"] = 790067,
            ["TalkActionId"] = {
                [1] = "790067:DisagreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC62B0",
            },
        [80210425] = {
            ["Content"] = "应当是那位红颜知己见他仍然是放不下名声，感到失望而独自离开。",
            ["ContentFR"] = "Elle a dû comprendre qu’il n’abandonnerait jamais vraiment sa renommée... et elle est partie seule.",
            ["DialogueId"] = 80210425,
            ["GUID"] = "C8CC62DA",
            ["NextDialogue"] = 80210426,
            ["SpeakNpcId"] = 790067,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC62DA",
            },
        [80210426] = {
            ["Content"] = "鸣鸾最初不以为意，但是很快便思念成疾，察觉到这世界上有比所谓的“天下第一”更重要的事物。",
            ["ContentFR"] = "Au début, il n’y a pas prêté attention. Puis le manque est devenu une maladie. Il a compris qu’il existait quelque chose de plus important que le titre de « Premier sous le Ciel ».",
            ["DialogueId"] = 80210426,
            ["GUID"] = "C8CC6304",
            ["NextDialogue"] = 80210427,
            ["SpeakNpcId"] = 790067,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC6304",
            },
        [80210427] = {
            ["Content"] = "于是他也离开了华胥，寻觅至今，却还是没有寻到。",
            ["ContentFR"] = "Il a quitté Huaxu à son tour. Il la cherche encore. Sans jamais la retrouver.",
            ["DialogueId"] = 80210427,
            ["GUID"] = "C8CC632E",
            ["NextDialogue"] = 80210428,
            ["SpeakNpcId"] = 790067,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC632E",
            },
        [80210428] = {
            ["Content"] = "所以这一次比武论剑，他不参加。",
            ["ContentFR"] = "Alors cette épreuve... il n’y participera pas.",
            ["DialogueId"] = 80210428,
            ["GUID"] = "C8CC6358",
            ["NextDialogue"] = 80210429,
            ["SpeakNpcId"] = 790067,
            ["TalkActionId"] = {
                [1] = "790067:Talk02R_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC6358",
            },
        [80210429] = {
            ["Camera"] = "523.363281,229.195312,121.128906,0.000162,1.999995,-122.399033,42.362053,406.334045,false,Manual,2.8",
            ["Content"] = "至于最后一位，被称作庖侠，妙手调羹的本领是一绝，所制作的“若木无觅衔烛龙”更是举世无双。",
            ["ContentFR"] = "Quant au dernier, on l’appelait le Vagabond des Fourneaux. Un maître cuisinier hors pair. Son plat « Le Dragon-Flamme inaccessible » était sans égal.",
            ["DialogueId"] = 80210429,
            ["FinalCamera"] = "434.003906,248.654785,121.818359,0.000152,1.999995,-107.80146,42.362053,398.766113,false,Manual,2.8",
            ["GUID"] = "C8CC6382",
            ["NextDialogue"] = 80210430,
            ["SpeakNpcId"] = 790067,
            ["TalkActionId"] = {
                [1] = "790067:Talk03_Start",
                },
            ["ToFinalCameraBlendTime"] = 40,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC6382",
            },
        [80210430] = {
            ["Content"] = "但在他某次设宴招待客人时，却被歹人在饭菜中下了毒，青花的瓷盘本来盛的是珍果佳肴，却沾染了血。",
            ["ContentFR"] = "Un jour, lors d’un banquet, quelqu’un a empoisonné les mets. Les porcelaines bleues et blanches, censées porter des délices, ont été souillées de sang.",
            ["DialogueId"] = 80210430,
            ["GUID"] = "C8CC63AC",
            ["NextDialogue"] = 80210431,
            ["SpeakNpcId"] = 790067,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC63AC",
            },
        [80210431] = {
            ["Content"] = "这毒虽然不是他下的，但毕竟饭菜都经过他手，于是也被大风九章认定为有罪。",
            ["ContentFR"] = "Même s’il n’était pas responsable, les plats étaient passés par ses mains. Les Neuf Chapitres l’ont déclaré coupable.",
            ["DialogueId"] = 80210431,
            ["GUID"] = "C8CC63D6",
            ["NextDialogue"] = 80210432,
            ["SpeakNpcId"] = 790067,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC63D6",
            },
        [80210432] = {
            ["Content"] = "他的武艺，要应对应天尉倒也不难。但一旦反抗，那简直如同是自认有罪，所以他就束手就擒，受到惩罚，跛了一足。",
            ["ContentFR"] = "Il aurait pu repousser les Magistrats de Yingtian. Mais résister, c’était reconnaître sa faute. Alors il s’est laissé arrêter. On l’a puni. Il en est sorti boiteux.",
            ["DialogueId"] = 80210432,
            ["GUID"] = "C8CC6400",
            ["NextDialogue"] = 80210433,
            ["SpeakNpcId"] = 790067,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC6400",
            },
        [80210433] = {
            ["Content"] = "等他重回自由身时，也是心灰意冷，不再以飘零人自居，专心磨练厨艺去了，炸油豆腐是一绝。",
            ["ContentFR"] = "Une fois libre, il n’avait plus goût à rien. Il a renoncé au titre de Vagabond, et s’est consacré à la cuisine. Ses tofu frits... sont inégalables.",
            ["DialogueId"] = 80210433,
            ["GUID"] = "C8CC642A",
            ["NextDialogue"] = 80210434,
            ["SpeakNpcId"] = 790067,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC642A",
            },
        [80210434] = {
            ["Camera"] = "511.71875,-314.994141,144.21875,0.000125,-4.000004,125.200066,42.362053,376.295776,false,Manual,2.8",
            ["Content"] = "难道说前几天你带给我的油豆腐就是……",
            ["ContentFR"] = "Attends... Les tofu que tu m’as apportés l’autre jour...",
            ["DialogueId"] = 80210434,
            ["FinalCamera"] = "491.65625,-286.541504,141.78418,0.000125,-4.000004,125.200066,42.362053,376.295776,false,Manual,2.8",
            ["GUID"] = "C8CC6454",
            ["NextDialogue"] = 80210435,
            ["SpeakNpcId"] = 790008,
            ["TalkActionId"] = {
                [1] = "790008:Think_Start",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC6454",
            },
        [80210435] = {
            ["Camera"] = "408.371094,68.496582,165.21582,0.000151,-3.99997,-106.198517,42.362053,214.163193,false,Manual,2.8",
            ["Content"] = "不，不是，我什么都没说，你什么都没听见。",
            ["ContentFR"] = "Non. Je n’ai rien dit. Tu n’as rien entendu.",
            ["DialogueId"] = 80210435,
            ["FacialId"] = {
                [1] = "790067:Nervous",
                },
            ["FinalCamera"] = "399.097656,36.579102,162.895508,0.000151,-2.99999,-106.198524,42.362053,175.129822,false,Manual,2.8",
            ["GUID"] = "C8CC647E",
            ["NextDialogue"] = 80210436,
            ["SpeakNpcId"] = 790067,
            ["TalkActionId"] = {
                [1] = "790067:DisagreeHead",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC647E",
            },
        [80210436] = {
            ["Camera"] = "511.71875,-314.994141,144.21875,0.000125,-4.000004,125.200066,42.362053,376.295776,false,Manual,2.8",
            ["Content"] = "噢……我懂了。",
            ["ContentFR"] = "... D’accord.",
            ["DialogueId"] = 80210436,
            ["FinalCamera"] = "491.65625,-286.541504,141.78418,0.000125,-4.000004,125.200066,42.362053,376.295776,false,Manual,2.8",
            ["GUID"] = "C8CC64A8",
            ["NextDialogue"] = 80210437,
            ["SpeakNpcId"] = 790008,
            ["TalkActionId"] = {
                [1] = "790008:AgreeHead",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC64A8",
            },
        [80210437] = {
            ["Content"] = "不过这么一来……岂不是来参加比武的，只有代表宴山亭师父的你？",
            ["ContentFR"] = "Donc, en résumé... Il n’y a que toi pour représenter ton maître ?",
            ["DialogueId"] = 80210437,
            ["GUID"] = "C8CC64D2",
            ["NextDialogue"] = 80210438,
            ["SpeakNpcId"] = 790008,
            ["TalkActionId"] = {
                [1] = "790008:Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC64D2",
            },
        [80210438] = {
            ["Camera"] = "434.003906,248.654785,121.818359,0.000152,1.999995,-107.80146,42.362053,398.766113,false,Manual,2.8",
            ["Content"] = "没错，这次比武论剑，只有我代表师父参加。",
            ["ContentFR"] = "Oui. Cette fois-ci, je suis le seul à représenter mon maître.",
            ["DialogueId"] = 80210438,
            ["FacialId"] = {
                [1] = "790067:None",
                },
            ["FinalCamera"] = "408.511719,168.209961,124.753906,0.000153,2.99999,-105.801682,42.362053,306.325958,false,Manual,2.8",
            ["GUID"] = "C8CC64FC",
            ["NextDialogue"] = 80210439,
            ["SpeakNpcId"] = 790067,
            ["TalkActionId"] = {
                [1] = "790067:Talk03_End",
                [2] = "790067:AgreeHead",
                },
            ["ToFinalCameraBlendTime"] = 40,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC64FC",
            },
        [80210439] = {
            ["Content"] = "这就是现在飘零人的现状啊，曾几何时他们聚啸山林，没有什么特意需要遵从的法条，只需要遵从内心与手中剑。",
            ["ContentFR"] = "Voilà où en sont les Vagabonds, aujourd’hui. Autrefois, ils hurlaient dans les montagnes, ne suivant que leur cœur et leur épée.",
            ["DialogueId"] = 80210439,
            ["GUID"] = "C8CC6526",
            ["NextDialogue"] = 80210440,
            ["SpeakNpcId"] = 790067,
            ["TalkActionId"] = {
                [1] = "790067:Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC6526",
            },
        [80210440] = {
            ["Content"] = "刀光剑影里有着一个又一个快意恩仇的故事。",
            ["ContentFR"] = "Chaque éclair de lame portait une histoire.",
            ["DialogueId"] = 80210440,
            ["GUID"] = "C8CC6550",
            ["NextDialogue"] = 80210441,
            ["SpeakNpcId"] = 790067,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC6550",
            },
        [80210441] = {
            ["Content"] = "在大风九章之下，没有所谓的路见不平拔刀相助，大家都畏惧触发法条，被应天尉盯上。",
            ["ContentFR"] = "Mais sous les Neuf Chapitres, plus personne n’ose dégainer pour autrui. Tout le monde craint d’attirer l’attention des Magistrats de Yingtian.",
            ["DialogueId"] = 80210441,
            ["GUID"] = "C8CC657A",
            ["NextDialogue"] = 80210442,
            ["SpeakNpcId"] = 790067,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC657A",
            },
        [80210442] = {
            ["Content"] = "即便是号称自由自在的飘零人，也无法免于受到大风九章的羁绊。",
            ["ContentFR"] = "Même ceux qui se prétendent libres, les Vagabonds, ne peuvent échapper aux entraves des Neuf Chapitres de Dafeng.",
            ["DialogueId"] = 80210442,
            ["GUID"] = "C8CC65A4",
            ["NextDialogue"] = 80210443,
            ["SpeakNpcId"] = 790067,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC65A4",
            },
        [80210443] = {
            ["Camera"] = "511.71875,-314.994141,144.21875,0.000125,-4.000004,125.200066,42.362053,376.295776,false,Manual,2.8",
            ["Content"] = "所以，你才会想要推翻大风九章？",
            ["ContentFR"] = "C’est pour ça que tu veux renverser les Neuf Chapitres ?",
            ["DialogueId"] = 80210443,
            ["FinalCamera"] = "491.65625,-286.541504,141.78418,0.000125,-4.000004,125.200066,42.362053,376.295776,false,Manual,2.8",
            ["GUID"] = "C8CC65CE",
            ["NextDialogue"] = 80210444,
            ["SpeakNpcId"] = 790008,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC65CE",
            },
        [80210444] = {
            ["Camera"] = "502.972656,27.527832,181.694336,0.000158,-7.999989,-134.198502,42.362053,234.67363,false,Manual,2.8",
            ["Content"] = "只能说是原因之一吧，还有其他的新仇旧恨。",
            ["ContentFR"] = "Disons que c’est l’une des raisons. Il y a aussi d’anciennes rancunes... et de nouvelles.",
            ["DialogueId"] = 80210444,
            ["FinalCamera"] = "481.535156,5.483887,177.371094,0.000159,-7.999968,-134.198471,42.362053,201.77124,false,Manual,2.8",
            ["GUID"] = "C8CC65F8",
            ["NextDialogue"] = 80210445,
            ["SpeakNpcId"] = 790067,
            ["TalkActionId"] = {
                [1] = "790067:Talk01_End",
                },
            ["ToFinalCameraBlendTime"] = 20,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC65F8",
            },
        [80210445] = {
            ["Content"] = "有时候我也在想，有大风九章在，至少大部分人能够安居，去反对它是不是真的有意义。",
            ["ContentFR"] = "Parfois je me demande si m’y opposer a un sens, puisque tant de gens vivent en paix grâce à eux.",
            ["DialogueId"] = 80210445,
            ["GUID"] = "C8CC6622",
            ["NextDialogue"] = 80210446,
            ["SpeakNpcId"] = 790067,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC6622",
            },
        [80210446] = {
            ["Content"] = "但这次为了准备论剑拜访了诸位前辈，看他们也都过得不尽如人意，那么在一片祥和之下，到底有多少不平之事，又有谁知道。",
            ["ContentFR"] = "Mais après avoir vu le sort de ces anciens... je me demande combien d’injustices se cachent sous cette harmonie.",
            ["DialogueId"] = 80210446,
            ["GUID"] = "C8CC664C",
            ["NextDialogue"] = 80210447,
            ["SpeakNpcId"] = 790067,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC664C",
            },
        [80210447] = {
            ["Content"] = "我作为飘零人，就不应该袖手旁观。虽说江湖儿女日渐少，但也有句话说得好嘛，天下风云出我辈。",
            ["ContentFR"] = "En tant que Vagabond, je ne peux pas détourner le regard. Même si nous sommes peu nombreux, on dit bien que les tempêtes naissent toujours d’une génération nouvelle.",
            ["DialogueId"] = 80210447,
            ["GUID"] = "C8CC6676",
            ["NextDialogue"] = 80210448,
            ["SpeakNpcId"] = 790067,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC6676",
            },
        [80210448] = {
            ["Content"] = "长剑在手，人在江湖，即便如孤鹜飘零，也能为天下之先，一览他人未见之景，是好事。",
            ["ContentFR"] = "Une épée à la main, le cœur dans le monde — même seul, on peut ouvrir la voie et voir ce que les autres n’ont jamais vu.",
            ["DialogueId"] = 80210448,
            ["GUID"] = "C8CC66A0",
            ["NextDialogue"] = 80210449,
            ["SpeakNpcId"] = 790067,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC66A0",
            },
        [80210449] = {
            ["Camera"] = "511.71875,-314.994141,144.21875,0.000125,-4.000004,125.200066,42.362053,376.295776,false,Manual,2.8",
            ["Content"] = "行应行之路，竟未竟之志。我想，我大概明白所谓的飘零人为什么能延续至今了。",
            ["ContentFR"] = "Marcher sur la route qu’on doit suivre. Achever les volontés laissées en suspens. Je crois comprendre, maintenant, pourquoi les Vagabonds n’ont jamais disparu.",
            ["DialogueId"] = 80210449,
            ["FinalCamera"] = "491.65625,-286.541504,141.78418,0.000125,-4.000004,125.200066,42.362053,376.295776,false,Manual,2.8",
            ["GUID"] = "C8CC66CA",
            ["NextDialogue"] = 80210450,
            ["SpeakNpcId"] = 790008,
            ["TalkActionId"] = {
                [1] = "790008:Explain02_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC66CA",
            },
        [80210450] = {
            ["Content"] = "并且我也相信，此后比武论剑之人，肯定不会像今天这样，只有你孤身一人的。",
            ["ContentFR"] = "Et je suis sûr que la prochaine épreuve ne se déroulera pas avec toi seul.",
            ["DialogueId"] = 80210450,
            ["GUID"] = "C8CC66F4",
            ["NextDialogue"] = 80210451,
            ["SpeakNpcId"] = 790008,
            ["TalkActionId"] = {
                [1] = "790008:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC66F4",
            },
        [80210451] = {
            ["Camera"] = "795.160156,-371.187988,113.348633,0.000152,1.999995,146.999313,42.362053,398.766113,false,Manual,2.8",
            ["Content"] = "哈哈哈哈，好，好，好，说得好。",
            ["ContentFR"] = "Hahaha ! Bien dit. Très bien dit.",
            ["DialogueId"] = 80210451,
            ["FacialId"] = {
                [1] = "790067:Smile01",
                },
            ["FinalCamera"] = "862.960938,-289.070312,112.585938,0.000152,1.999995,156.599838,42.362053,398.766113,false,Manual,2.8",
            ["GUID"] = "C8CC671E",
            ["NextDialogue"] = 80210452,
            ["SpeakNpcId"] = 790067,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC671E",
            },
        [80210452] = {
            ["Content"] = "不过嘛，我可没有为没有人论剑感到难过，不如说，这可是大好事——",
            ["ContentFR"] = "Mais ne crois pas que l’absence des autres m’attriste. Au contraire — c’est parfait.",
            ["DialogueId"] = 80210452,
            ["GUID"] = "C8CC6748",
            ["NextDialogue"] = 80210453,
            ["SpeakNpcId"] = 790067,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC6748",
            },
        [80210453] = {
            ["Camera"] = "408.371094,68.496582,165.21582,0.000151,-3.99997,-106.198517,42.362053,214.163193,false,Manual,2.8",
            ["Content"] = "我宣布，因为其他三位比武者的缺席，宴山亭的弟子刻舟，正式成为华胥第一飘零人。",
            ["ContentFR"] = "Je déclare donc qu’en raison de l’absence des autres combattants, moi, Kezhou, disciple de Yan Shanting, deviens officiellement le Premier Vagabond de Huaxu.",
            ["DialogueId"] = 80210453,
            ["FinalCamera"] = "399.097656,36.579102,162.895508,0.000151,-2.99999,-106.198524,42.362053,175.129822,false,Manual,2.8",
            ["GUID"] = "C8CC6772",
            ["NextDialogue"] = 80210454,
            ["SpeakNpcId"] = 790067,
            ["TalkActionId"] = {
                [1] = "790067:Confident_Start",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC6772",
            },
        [80210454] = {
            ["Camera"] = "511.71875,-314.994141,144.21875,0.000125,-4.000004,125.200066,42.362053,376.295776,false,Manual,2.8",
            ["Content"] = "就这么宣布了？",
            ["ContentFR"] = "Tu annonces ça comme ça ?",
            ["DialogueId"] = 80210454,
            ["FinalCamera"] = "491.65625,-286.541504,141.78418,0.000125,-4.000004,125.200066,42.362053,376.295776,false,Manual,2.8",
            ["GUID"] = "C8CC679C",
            ["NextDialogue"] = 80210455,
            ["SpeakNpcId"] = 790008,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC679C",
            },
        [80210455] = {
            ["Camera"] = "434.003906,248.654785,121.818359,0.000152,1.999995,-107.80146,42.362053,398.766113,false,Manual,2.8",
            ["Content"] = "那不然呢？我师父就让我这么做的。我记得清清楚楚，当时他和我说，如果上一届的参加者们不想参加比武，那么也不用强行劝说。",
            ["ContentFR"] = "Et pourquoi pas ? C’est mon maître qui me l’a demandé. Je me souviens très bien de ses mots : si les participants de la précédente épreuve ne souhaitent pas revenir, inutile de les forcer.",
            ["DialogueId"] = 80210455,
            ["FinalCamera"] = "408.511719,168.209961,124.753906,0.000153,2.99999,-105.801682,42.362053,306.325958,false,Manual,2.8",
            ["GUID"] = "C8CC67C6",
            ["NextDialogue"] = 80210456,
            ["SpeakNpcId"] = 790067,
            ["ToFinalCameraBlendTime"] = 20,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC67C6",
            },
        [80210456] = {
            ["Content"] = "毕竟，如果参加人数少了，那么赢到最后的可能性也会跟着变大，说不定只要比试一场就能夺冠了。",
            ["ContentFR"] = "Moins il y a de participants, plus les chances de gagner sont grandes. Peut-être même qu’un seul combat suffit !",
            ["DialogueId"] = 80210456,
            ["GUID"] = "C8CC67F0",
            ["NextDialogue"] = 80210457,
            ["SpeakNpcId"] = 790067,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC67F0",
            },
        [80210457] = {
            ["Content"] = "师父还是太保守了，实际上一场都没比试，这才叫真正的天下无敌！",
            ["ContentFR"] = "Mais il était trop prudent. Moi, je n’ai même pas eu besoin de combattre. Ça, c’est la vraie invincibilité.",
            ["DialogueId"] = 80210457,
            ["GUID"] = "C8CC681A",
            ["NextDialogue"] = 80210458,
            ["SpeakNpcId"] = 790067,
            ["TalkActionId"] = {
                [1] = "790067:Confident_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC681A",
            },
        [80210458] = {
            ["Camera"] = "511.71875,-314.994141,144.21875,0.000125,-4.000004,125.200066,42.362053,376.295776,false,Manual,2.8",
            ["Content"] = "我还以为你会再低落一会儿。",
            ["ContentFR"] = "Je pensais que tu serais plus abattu.",
            ["DialogueId"] = 80210458,
            ["FinalCamera"] = "491.65625,-286.541504,141.78418,0.000125,-4.000004,125.200066,42.362053,376.295776,false,Manual,2.8",
            ["GUID"] = "C8CC6844",
            ["NextDialogue"] = 80210459,
            ["SpeakNpcId"] = 790008,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC6844",
            },
        [80210459] = {
            ["Camera"] = "502.972656,27.527832,181.694336,0.000158,-7.999989,-134.198502,42.362053,234.67363,false,Manual,2.8",
            ["Content"] = "黯然神伤刻舟求剑这种事情，不适合我，有其他人做就行了。",
            ["ContentFR"] = "La mélancolie et les soupirs, ça convient mieux à d’autres que moi.",
            ["DialogueId"] = 80210459,
            ["FinalCamera"] = "481.535156,5.483887,177.371094,0.000159,-7.999968,-134.198471,42.362053,201.77124,false,Manual,2.8",
            ["GUID"] = "C8CC686E",
            ["NextDialogue"] = 80210460,
            ["SpeakNpcId"] = 790067,
            ["TalkActionId"] = {
                [1] = "790067:DisagreeHead",
                },
            ["ToFinalCameraBlendTime"] = 20,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC686E",
            },
        [80210460] = {
            ["Content"] = "我要做的，是斩落师父，师兄，以及诸位前辈们为之郁结的大风九章。",
            ["ContentFR"] = "Ce que je dois faire, c’est trancher ce qui a enchaîné mon maître, mes aînés, et tant de Vagabonds : les Neuf Chapitres de Dafeng.",
            ["DialogueId"] = 80210460,
            ["GUID"] = "C8CC6898",
            ["NextDialogue"] = 80210461,
            ["SpeakNpcId"] = 790067,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC6898",
            },
        [80210461] = {
            ["Content"] = "等到这件事告一段落后，我大概才能和那些飘零人小说中描写的一样，退隐山林了。",
            ["ContentFR"] = "Après ça... peut-être que je me retirerai dans les montagnes, comme dans les romans.",
            ["DialogueId"] = 80210461,
            ["GUID"] = "C8CC68C2",
            ["NextDialogue"] = 80210462,
            ["SpeakNpcId"] = 790067,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC68C2",
            },
        [80210462] = {
            ["Camera"] = "511.71875,-314.994141,144.21875,0.000125,-4.000004,125.200066,42.362053,376.295776,false,Manual,2.8",
            ["Content"] = "依你的性格，我感觉你闲不下来。",
            ["ContentFR"] = "Te connaissant, tu ne tiendras pas en place.",
            ["DialogueId"] = 80210462,
            ["FinalCamera"] = "491.65625,-286.541504,141.78418,0.000125,-4.000004,125.200066,42.362053,376.295776,false,Manual,2.8",
            ["GUID"] = "C8CC68EC",
            ["NextDialogue"] = 80210463,
            ["SpeakNpcId"] = 790008,
            ["TalkActionId"] = {
                [1] = "790008:DisagreeHead",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC68EC",
            },
        [80210463] = {
            ["Camera"] = "377.449219,42.706543,179.00293,0.000195,-7.99994,-98.99649,42.362053,171.145584,false,Manual,2.8",
            ["Content"] = "确实，那就等那时再说吧。",
            ["ContentFR"] = "C’est vrai. On verra bien le moment venu.",
            ["DialogueId"] = 80210463,
            ["FinalCamera"] = "377.128906,35.079102,177.938477,0.000195,-7.99994,-98.99649,42.362053,171.145584,false,Manual,2.8",
            ["GUID"] = "C8CC6916",
            ["NextDialogue"] = 80210464,
            ["SpeakNpcId"] = 790067,
            ["TalkActionId"] = {
                [1] = "790067:AgreeHead",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC6916",
            },
        [80210464] = {
            ["Camera"] = "855.464844,-598.185059,132.694336,0.0,0.0,136.606979,26.65424,695.636841,false,Manual,2.8",
            ["Content"] = "今日拔得头筹成为第一飘零人，应该开心过活，不去管那以后的事。来吧，朋友，且歌且醉，且醉且歌！",
            ["ContentFR"] = "Aujourd’hui, je suis devenu le Premier Vagabond. Il faut vivre dans la joie. Allons, mon {性别:ami|amie} — chantons et buvons ! Buvons en chantant, chantons en buvant !",
            ["DialogueId"] = 80210464,
            ["FinalCamera"] = "1130.59375,-914.811523,132.694336,0.0,0.0,133.406891,26.65424,275.423279,false,Manual,2.8",
            ["GUID"] = "C8CC6940",
            ["NextDialogue"] = 80210465,
            ["SpeakNpcId"] = 790067,
            ["ToFinalCameraBlendTime"] = 20,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC6940",
            },
        [80210465] = {
            ["Content"] = "那些曾经锋芒毕露的，生死相许的，快意恩仇的，都早已成为风中一缕轻尘。",
            ["ContentFR"] = "Les lames éclatantes, les serments de vie et de mort, les passions ardentes... tout cela s’est dissipé dans le vent.",
            ["DialogueId"] = 80210465,
            ["GUID"] = "C8CC696A",
            ["NextDialogue"] = 80210466,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC696A",
            },
        [80210466] = {
            ["Content"] = "最终都只剩下满头霜雪与轻叹一声，少年子弟江湖老。",
            ["ContentFR"] = "Il ne reste plus que des cheveux blanchis par le givre du temps, et un soupir léger : les enfants du Jianghu ont vieilli.",
            ["DialogueId"] = 80210466,
            ["GUID"] = "C8CC6994",
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC6994",
            },
        [80210467] = {
            ["DialogueId"] = 80210467,
            ["Duration"] = 1,
            ["GUID"] = "C8CC6995",
            ["IsBlack"] = 1,
            },
        [80220101] = {
            ["Content"] = "……",
            ["DialogueId"] = 80220101,
            ["GUID"] = "C8D29652",
            ["NextDialogue"] = 80220102,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29652",
            },
        [80220102] = {
            ["Content"] = "师兄？",
            ["ContentFR"] = "Yuming... ?",
            ["DialogueId"] = 80220102,
            ["GUID"] = "C8D2967C",
            ["NextDialogue"] = 80220103,
            ["SpeakNpcId"] = 790073,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D2967C",
            },
        [80220103] = {
            ["Content"] = "是不夏啊。",
            ["ContentFR"] = "Buxia.",
            ["DialogueId"] = 80220103,
            ["GUID"] = "C8D296A6",
            ["NextDialogue"] = 80220104,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D296A6",
            },
        [80220104] = {
            ["Content"] = "老远就听到笛声了，果然是你。",
            ["ContentFR"] = "J’ai entendu la flûte de très loin. Je me suis dit que ce ne pouvait être que toi.",
            ["DialogueId"] = 80220104,
            ["GUID"] = "C8D296D0",
            ["NextDialogue"] = 80220105,
            ["SpeakNpcId"] = 790073,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D296D0",
            },
        [80220105] = {
            ["Content"] = "你找我有事？",
            ["ContentFR"] = "Tu avais quelque chose à me demander ?",
            ["DialogueId"] = 80220105,
            ["GUID"] = "C8D296FA",
            ["NextDialogue"] = 80220106,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D296FA",
            },
        [80220106] = {
            ["Content"] = "其实是……师兄，帮忙看看它吧。",
            ["ContentFR"] = "Eh bien... Yuming, pourrais-tu regarder ceci ?",
            ["DialogueId"] = 80220106,
            ["GUID"] = "C8D29724",
            ["NextDialogue"] = 80220107,
            ["SpeakNpcId"] = 790073,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29724",
            },
        [80220107] = {
            ["Content"] = "我和刻舟师兄在山外山外面发现了这只小狐狸，它被野兽咬伤了。",
            ["ContentFR"] = "Avec Kezhou, nous l’avons trouvé juste à l’extérieur des Pics Extérieurs. Il a été mordu par une bête sauvage.",
            ["DialogueId"] = 80220107,
            ["GUID"] = "C8D2974E",
            ["NextDialogue"] = 80220108,
            ["SpeakNpcId"] = 790073,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D2974E",
            },
        [80220108] = {
            ["Content"] = "刻舟师兄粗枝大叶，完全不知道怎么处理它身上的伤，就只能来找师兄你了。放着不管的话，它很快便会死掉的。",
            ["ContentFR"] = "Kezhou est beaucoup trop brusque pour s’occuper de ce genre de chose... alors je suis venue te voir. Si on le laisse ainsi, il ne survivra pas longtemps.",
            ["DialogueId"] = 80220108,
            ["GUID"] = "C8D29778",
            ["NextDialogue"] = 80220109,
            ["SpeakNpcId"] = 790073,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29778",
            },
        [80220109] = {
            ["Content"] = "……",
            ["ContentFR"] = "...",
            ["DialogueId"] = 80220109,
            ["GUID"] = "C8D297A2",
            ["NextDialogue"] = 80220110,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D297A2",
            },
        [80220110] = {
            ["Content"] = "师兄？",
            ["ContentFR"] = "Yuming ?",
            ["DialogueId"] = 80220110,
            ["GUID"] = "C8D297CC",
            ["NextDialogue"] = 80220111,
            ["SpeakNpcId"] = 790073,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D297CC",
            },
        [80220111] = {
            ["Content"] = "没什么。让我来看看吧。",
            ["ContentFR"] = "Ce n’est rien. Laisse-moi voir.",
            ["DialogueId"] = 80220111,
            ["GUID"] = "C8D297F6",
            ["NextDialogue"] = 80220112,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D297F6",
            },
        [80220112] = {
            ["Content"] = "我们发现它的时候，它就那么蜷在岩石的缝隙之间，死死地盯着外面。我们在附近找到了几只断了气的大狐狸，顺着它们的血迹才找到了这个小家伙。",
            ["ContentFR"] = "Quand nous l’avons trouvé, il était recroquevillé dans une fissure entre les rochers, fixant l’extérieur sans bouger. Nous avons découvert plusieurs renards adultes morts non loin de là... c’est en suivant leurs traces de sang que nous sommes arrivés jusqu’à lui.",
            ["DialogueId"] = 80220112,
            ["GUID"] = "C8D29820",
            ["NextDialogue"] = 80220113,
            ["SpeakNpcId"] = 790073,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29820",
            },
        [80220113] = {
            ["Content"] = "刻舟师兄把它抱起来的时候，它没有叫，也没有害怕。或者说……它太小了，小到甚至不明白发生了什么，只能这么颤抖着被带来这里。",
            ["ContentFR"] = "Quand Kezhou l’a pris dans ses bras, il n’a ni crié ni résisté. Ou plutôt... il est si jeune qu’il ne comprend même pas ce qui lui arrive. Il a simplement tremblé tout le long du chemin.",
            ["DialogueId"] = 80220113,
            ["GUID"] = "C8D2984A",
            ["NextDialogue"] = 80220114,
            ["SpeakNpcId"] = 790073,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D2984A",
            },
        [80220114] = {
            ["Content"] = "……伤口处理好了。",
            ["ContentFR"] = "... Les blessures sont traitées.",
            ["DialogueId"] = 80220114,
            ["GUID"] = "C8D29874",
            ["NextDialogue"] = 80220115,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29874",
            },
        [80220115] = {
            ["Content"] = "让刻舟去砍些木材回来，我给它搭个窝避雨。",
            ["ContentFR"] = "Dis à Kezhou d’aller couper du bois. Je vais lui construire un abri pour le protéger de la pluie.",
            ["DialogueId"] = 80220115,
            ["GUID"] = "C8D2989E",
            ["NextDialogue"] = 80220116,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D2989E",
            },
        [80220116] = {
            ["Content"] = "师兄你的意思是……我们可以养它吗？",
            ["ContentFR"] = "Tu veux dire... que nous pouvons le garder ?",
            ["DialogueId"] = 80220116,
            ["GUID"] = "C8D298C8",
            ["NextDialogue"] = 80220117,
            ["SpeakNpcId"] = 790073,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D298C8",
            },
        [80220117] = {
            ["Content"] = "太好了，我这就去！嗯嗯，还得给它取个名字……就叫你“小橙子”吧！小狐狸！",
            ["ContentFR"] = "C’est formidable ! J’y vais tout de suite ! Oh, et il lui faut un nom... Ce sera Juju, d’accord ? Petit renard !",
            ["DialogueId"] = 80220117,
            ["GUID"] = "C8D298F2",
            ["NextDialogue"] = 80220118,
            ["SpeakNpcId"] = 790073,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D298F2",
            },
        [80220118] = {
            ["Content"] = "一年后",
            ["ContentFR"] = "Un an plus tard...",
            ["DialogueId"] = 80220118,
            ["GUID"] = "C8D2991C",
            ["NextDialogue"] = 80220119,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D2991C",
            },
        [80220119] = {
            ["Content"] = "不夏？",
            ["ContentFR"] = "Buxia ?",
            ["DialogueId"] = 80220119,
            ["GUID"] = "C8D29946",
            ["NextDialogue"] = 80220120,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29946",
            },
        [80220120] = {
            ["Content"] = "……",
            ["ContentFR"] = "...",
            ["DialogueId"] = 80220120,
            ["GUID"] = "C8D29970",
            ["NextDialogue"] = 80220121,
            ["SpeakNpcId"] = 790073,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29970",
            },
        [80220121] = {
            ["Content"] = "不夏。",
            ["ContentFR"] = "Buxia.",
            ["DialogueId"] = 80220121,
            ["GUID"] = "C8D2999A",
            ["NextDialogue"] = 80220122,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D2999A",
            },
        [80220122] = {
            ["Content"] = "师兄！你回来啦？",
            ["ContentFR"] = "Yuming ! Tu es déjà de retour ?",
            ["DialogueId"] = 80220122,
            ["GUID"] = "C8D299C4",
            ["NextDialogue"] = 80220123,
            ["SpeakNpcId"] = 790073,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D299C4",
            },
        [80220123] = {
            ["Content"] = "你的耳朵？",
            ["ContentFR"] = "Ton oreille... ?",
            ["DialogueId"] = 80220123,
            ["GUID"] = "C8D299EE",
            ["NextDialogue"] = 80220124,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D299EE",
            },
        [80220124] = {
            ["Content"] = "没事没事，只是有一只耳朵偶尔听不清而已，另一只好着呢！……嗯，一定是耳朵告诉我，我又该睡大觉了！",
            ["ContentFR"] = "Oh, ça ? Rien de grave. Il y en a juste une qui fait parfois des siennes. L’autre fonctionne très bien ! ... Hm, à tous les coups, c’est mon corps qui me dit que je devrais faire une sieste !",
            ["DialogueId"] = 80220124,
            ["GUID"] = "C8D29A18",
            ["NextDialogue"] = 80220125,
            ["SpeakNpcId"] = 790073,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29A18",
            },
        [80220125] = {
            ["Content"] = "……不要怠惰。若不是你与刻舟偷懒被发现，师父也不会罚你们在这里抄书三天，磨砺心性。你与刻舟天赋有别，若继续和他一般，迟早会被拖累。",
            ["ContentFR"] = "... Ne sois pas négligente. Si toi et Kezhou n’aviez pas été surpris à paresser, le maître ne vous aurait pas punis à recopier des textes pendant trois jours pour endurcir votre esprit. Ton talent n’est pas le sien. Si tu continues à suivre son rythme, tu finiras par être entraînée dans sa chute.",
            ["DialogueId"] = 80220125,
            ["GUID"] = "C8D29A42",
            ["NextDialogue"] = 80220126,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29A42",
            },
        [80220126] = {
            ["Content"] = "至于你的耳朵，我想还是得早日去皓京寻得药师来瞧瞧。",
            ["ContentFR"] = "Quant à ton oreille... nous devrions aller à Haojing dès que possible, pour consulter un médecin.",
            ["DialogueId"] = 80220126,
            ["GUID"] = "C8D29A6C",
            ["NextDialogue"] = 80220127,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29A6C",
            },
        [80220127] = {
            ["Content"] = "知道啦知道啦——师兄还那么年轻，就像师父那个老头子一样唠唠叨叨的。",
            ["ContentFR"] = "D’accord, d’accord... Yuming, tu es encore jeune, et pourtant tu parles déjà comme le maître, toujours à sermonner.",
            ["DialogueId"] = 80220127,
            ["GUID"] = "C8D29A96",
            ["NextDialogue"] = 80220128,
            ["SpeakNpcId"] = 790073,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29A96",
            },
        [80220128] = {
            ["Content"] = "对了对了，小橙子怎么样了？昨天下了那么大的雨，我有点担心……",
            ["ContentFR"] = "Au fait... comment va Juju ? La pluie était si forte hier... j’étais un peu inquiète.",
            ["DialogueId"] = 80220128,
            ["GUID"] = "C8D29AC0",
            ["NextDialogue"] = 80220129,
            ["SpeakNpcId"] = 790073,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29AC0",
            },
        [80220129] = {
            ["Content"] = "今天我去后山看它，此前给它造的小窝被山石砸坏了。它蜷缩在那些折断的木板下面，任凭雨水渗过缝隙流淌在它身上。",
            ["ContentFR"] = "Je suis allé le voir aujourd’hui, derrière la montagne. L’abri que je lui avais construit a été détruit par un éboulement. Il s’était recroquevillé sous les planches brisées, laissant l’eau de pluie s’infiltrer dans son pelage.",
            ["DialogueId"] = 80220129,
            ["GUID"] = "C8D29AEA",
            ["NextDialogue"] = 80220130,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29AEA",
            },
        [80220130] = {
            ["Content"] = "我把窝修补好了，又放了些干草。但它还是老样子，蜷在那儿发抖。",
            ["ContentFR"] = "J’ai réparé l’abri et ajouté de la paille sèche. Mais il tremblait toujours, comme avant.",
            ["DialogueId"] = 80220130,
            ["GUID"] = "C8D29B14",
            ["NextDialogue"] = 80220131,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29B14",
            },
        [80220131] = {
            ["Content"] = "唉……这叫我怎么放心得下呀。",
            ["ContentFR"] = "Ah... comment veux-tu que je sois rassurée après ça...",
            ["DialogueId"] = 80220131,
            ["GUID"] = "C8D29B3E",
            ["NextDialogue"] = 80220132,
            ["SpeakNpcId"] = 790073,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29B3E",
            },
        [80220132] = {
            ["Content"] = "你们在干什么？不夏，你的书抄完了？",
            ["ContentFR"] = "Que faites-vous ici ? Buxia, as-tu terminé de recopier tes textes ?",
            ["DialogueId"] = 80220132,
            ["GUID"] = "C8D29B68",
            ["NextDialogue"] = 80220133,
            ["SpeakNpcId"] = 790074,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29B68",
            },
        [80220133] = {
            ["Content"] = "啊，师父，我……我们只是在商量武学！今天早上煜明师兄使出了一招枪，特别好看前所未见，我看了就也想学一学，所以正在和他讨教……没干什么，嘿嘿。",
            ["ContentFR"] = "Ah— Maître ! N–Nous discutions d’arts martiaux ! Ce matin, Yuming a exécuté une technique à la lance absolument incroyable, je n’avais jamais vu ça... alors je lui ai demandé conseil, voilà tout ! Hé hé...",
            ["DialogueId"] = 80220133,
            ["GUID"] = "C8D29B92",
            ["NextDialogue"] = 80220134,
            ["SpeakNpcId"] = 790073,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29B92",
            },
        [80220134] = {
            ["Content"] = "是的。",
            ["ContentFR"] = "... Oui.",
            ["DialogueId"] = 80220134,
            ["GUID"] = "C8D29BBC",
            ["NextDialogue"] = 80220135,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29BBC",
            },
        [80220135] = {
            ["Content"] = "唉，你们俩，一个说谎的时候话会变多，一个说谎的时候话会变少。当为师是你们俩养的那小狐狸一样不通人言吗？",
            ["ContentFR"] = "Hmpf. L’un de vous parle davantage quand il ment. L’autre se tait presque entièrement. Me prenez-vous pour un vieil homme incapable de comprendre, comme ce petit renard que vous élevez ?",
            ["DialogueId"] = 80220135,
            ["GUID"] = "C8D29BE6",
            ["NextDialogue"] = 80220136,
            ["SpeakNpcId"] = 790074,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29BE6",
            },
        [80220136] = {
            ["Content"] = "原来……师父都知道了呀。",
            ["ContentFR"] = "Alors... vous saviez depuis le début, Maître...",
            ["DialogueId"] = 80220136,
            ["GUID"] = "C8D29C10",
            ["NextDialogue"] = 80220137,
            ["SpeakNpcId"] = 790073,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29C10",
            },
        [80220137] = {
            ["Content"] = "为师只是老了不是傻了！一年前你们把这小东西捡来的时候我就知道了，毕竟它也时不时到处撒欢。",
            ["ContentFR"] = "Je suis vieux, pas aveugle. Je le savais déjà il y a un an, quand vous avez ramené cette petite chose. Elle gambade partout depuis lors.",
            ["DialogueId"] = 80220137,
            ["GUID"] = "C8D29C3A",
            ["NextDialogue"] = 80220138,
            ["SpeakNpcId"] = 790074,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29C3A",
            },
        [80220138] = {
            ["Content"] = "这几天没有见它，特意寻过来看一看，发现你们俩在这边愁眉苦脸，想问问怎么回事，没想到还和我不老实。",
            ["ContentFR"] = "Ces derniers jours, je ne l’avais plus vue. Je suis donc venu vérifier. Je vous ai trouvés ici, l’air soucieux... et en plus, vous avez essayé de me tromper.",
            ["DialogueId"] = 80220138,
            ["GUID"] = "C8D29C64",
            ["NextDialogue"] = 80220139,
            ["SpeakNpcId"] = 790074,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29C64",
            },
        [80220139] = {
            ["Content"] = "哎呀，这不是因为师父一直仙风道骨，是武林耆宿，想着你可能更喜欢什么鹤呀鹿呀之类的动物，不喜欢狐狸，所以不敢告诉你嘛。",
            ["ContentFR"] = "Eh bien... c’est parce que vous avez toujours cet air détaché, presque immortel... Je me suis dit qu’un maître aussi vénérable préférerait sans doute les grues ou les cerfs, pas un renard...",
            ["DialogueId"] = 80220139,
            ["GUID"] = "C8D29C8E",
            ["NextDialogue"] = 80220140,
            ["SpeakNpcId"] = 790073,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29C8E",
            },
        [80220140] = {
            ["Content"] = "还在饶舌，又是跟刻舟学的吧。为师什么时候讲究那些了。说吧，遇到什么问题了？",
            ["ContentFR"] = "Tu parles trop. Encore une habitude prise avec Kezhou ? Depuis quand est-ce que je fais des histoires pour si peu ? Parle. Qu’est-ce qui se passe ?",
            ["DialogueId"] = 80220140,
            ["GUID"] = "C8D29CB8",
            ["NextDialogue"] = 80220141,
            ["SpeakNpcId"] = 790074,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29CB8",
            },
        [80220141] = {
            ["Content"] = "（不夏和煜明把“小橙子”的事告诉了宴山亭。）",
            ["ContentFR"] = "Buxia et Yuming expliquent ce qui est arrivé à Juju.",
            ["DialogueId"] = 80220141,
            ["GUID"] = "C8D29CE2",
            ["NextDialogue"] = 80220142,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29CE2",
            },
        [80220142] = {
            ["Content"] = "哈哈，我当是什么事。要是我，我就把它拎起来，拎到它来的地方去。山外山不是它的家，外面的山林才是。",
            ["ContentFR"] = "Ha ha. Je m’attendais à bien pire. À votre place, je l’aurais simplement porté et ramené là d’où il vient. Les Pics Extérieurs ne sont pas son foyer. Il appartient à la forêt sauvage.",
            ["DialogueId"] = 80220142,
            ["GUID"] = "C8D29D0C",
            ["NextDialogue"] = 80220143,
            ["SpeakNpcId"] = 790074,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29D0C",
            },
        [80220143] = {
            ["Content"] = "那……那怎么行！它饿的时候谁来喂食，冷的时候谁来给它往窝里多塞点棉絮？",
            ["ContentFR"] = "M–Mais... comment fera-t-il quand il aura faim ? Qui lui donnera à manger ? Et quand il fera froid, qui ajoutera de la litière dans son abri ?",
            ["DialogueId"] = 80220143,
            ["GUID"] = "C8D29D36",
            ["NextDialogue"] = 80220144,
            ["SpeakNpcId"] = 790073,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29D36",
            },
        [80220144] = {
            ["Content"] = "你看，就是因为你总做这些，它才一直长不大的。",
            ["ContentFR"] = "Voilà précisément pourquoi il ne grandit pas.",
            ["DialogueId"] = 80220144,
            ["GUID"] = "C8D29D60",
            ["NextDialogue"] = 80220145,
            ["SpeakNpcId"] = 790074,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29D60",
            },
        [80220145] = {
            ["Content"] = "你们给它搭了避雨的窝，却没有教会它如何度过寒冬。给了它果腹之物，却没有教会它如何捕猎。",
            ["ContentFR"] = "Vous lui avez construit un abri contre la pluie, mais vous ne lui avez jamais appris à survivre à l’hiver. Vous l’avez nourri, mais vous ne lui avez jamais appris à chasser.",
            ["DialogueId"] = 80220145,
            ["GUID"] = "C8D29D8A",
            ["NextDialogue"] = 80220146,
            ["SpeakNpcId"] = 790074,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29D8A",
            },
        [80220146] = {
            ["Content"] = "它饿了冷了都等着你们照顾，要如何自己谋生？要是哪天没我的傻徒儿盯着，一场大雨就能要了它的小命啦。",
            ["ContentFR"] = "Lorsqu’il a froid ou faim, il n’attend que vous. Comment pourrait-il vivre seul ? Le jour où mes disciples étourdis détourneront le regard... une seule nuit de pluie suffira à lui coûter la vie.",
            ["DialogueId"] = 80220146,
            ["GUID"] = "C8D29DB4",
            ["NextDialogue"] = 80220147,
            ["SpeakNpcId"] = 790074,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29DB4",
            },
        [80220147] = {
            ["Content"] = "那、那师父的意思是……",
            ["ContentFR"] = "A–Alors... vous voulez dire que...",
            ["DialogueId"] = 80220147,
            ["GUID"] = "C8D29DDE",
            ["NextDialogue"] = 80220148,
            ["SpeakNpcId"] = 790073,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29DDE",
            },
        [80220148] = {
            ["Content"] = "纵是你再不舍，它终究还是要回归山林的。它是头小野兽，一味地庇护只会让它失去生存的能力。",
            ["ContentFR"] = "Même si ton cœur se refuse à l’admettre, il doit retourner à la forêt. C’est une bête sauvage. La protéger sans cesse, c’est lui retirer toute chance de survivre.",
            ["DialogueId"] = 80220148,
            ["GUID"] = "C8D29E08",
            ["NextDialogue"] = 80220149,
            ["SpeakNpcId"] = 790074,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29E08",
            },
        [80220149] = {
            ["Content"] = "……我明白了。让我和两位师兄商量商量……",
            ["ContentFR"] = "... Je comprends. Laissez-moi en discuter avec mes deux frères d’armes...",
            ["DialogueId"] = 80220149,
            ["GUID"] = "C8D29E32",
            ["NextDialogue"] = 80220150,
            ["SpeakNpcId"] = 790073,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29E32",
            },
        [80220150] = {
            ["Content"] = "…………",
            ["ContentFR"] = "...",
            ["DialogueId"] = 80220150,
            ["GUID"] = "C8D29E5C",
            ["NextDialogue"] = 80220151,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29E5C",
            },
        [80220151] = {
            ["Content"] = "煜明，你有心事。",
            ["ContentFR"] = "Yuming. Tu es tourmenté.",
            ["DialogueId"] = 80220151,
            ["GUID"] = "C8D29E86",
            ["NextDialogue"] = 80220152,
            ["SpeakNpcId"] = 790074,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29E86",
            },
        [80220152] = {
            ["Content"] = "没有。",
            ["ContentFR"] = "Non.",
            ["DialogueId"] = 80220152,
            ["GUID"] = "C8D29EB0",
            ["NextDialogue"] = 80220153,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29EB0",
            },
        [80220153] = {
            ["Content"] = "就两个字？又在扯谎。",
            ["ContentFR"] = "Un seul mot ? Voilà encore un mensonge.",
            ["DialogueId"] = 80220153,
            ["GUID"] = "C8D29EDA",
            ["NextDialogue"] = 80220154,
            ["SpeakNpcId"] = 790074,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29EDA",
            },
        [80220154] = {
            ["Content"] = "……徒儿愚钝。",
            ["ContentFR"] = "... Votre disciple a manqué de discernement.",
            ["DialogueId"] = 80220154,
            ["GUID"] = "C8D29F04",
            ["NextDialogue"] = 80220155,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29F04",
            },
        [80220155] = {
            ["Content"] = "也许那日我们收养小橙子并非明智之举，但如今错已铸成。",
            ["ContentFR"] = "Peut-être n’aurions-nous jamais dû recueillir Juju ce jour-là. Mais l’erreur est déjà commise.",
            ["DialogueId"] = 80220155,
            ["GUID"] = "C8D29F2E",
            ["NextDialogue"] = 80220156,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29F2E",
            },
        [80220156] = {
            ["Content"] = "如您所言，它和我们一起生活许久，已经失去了独自生存的能力。此时若选择放归野外，只怕它……",
            ["ContentFR"] = "Comme vous l’avez dit, il a vécu longtemps à nos côtés. Il a perdu la capacité de survivre seul. Si nous le relâchons maintenant... j’ai peur qu’il ne—",
            ["DialogueId"] = 80220156,
            ["GUID"] = "C8D29F58",
            ["NextDialogue"] = 80220157,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29F58",
            },
        [80220157] = {
            ["Content"] = "可能会冻死饿死。你说的这些，我又如何不知。但为师只有一句话，做就别怕，怕就别做。",
            ["ContentFR"] = "Qu’il ne meure de froid ou de faim. Je le sais aussi bien que toi. Mais retiens ceci : si tu choisis d’agir, ne crains pas les conséquences. Et si tu crains les conséquences, alors n’agis pas.",
            ["DialogueId"] = 80220157,
            ["GUID"] = "C8D29F82",
            ["NextDialogue"] = 80220158,
            ["SpeakNpcId"] = 790074,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29F82",
            },
        [80220158] = {
            ["Content"] = "任何选择都伴随着所失和所得。就像咱们飘零人，丢下了大风九章，便是选择自己庇护自己。这无关对错，只关抉择。",
            ["ContentFR"] = "Chaque décision s’accompagne d’un gain et d’une perte. Tout comme nous, vagabonds, avons abandonné les Neuf Chapitres de Dafeng pour nous protéger par nous-mêmes. Il n’est pas question de bien ou de mal. Seulement de choix.",
            ["DialogueId"] = 80220158,
            ["GUID"] = "C8D29FAC",
            ["NextDialogue"] = 80220159,
            ["SpeakNpcId"] = 790074,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29FAC",
            },
        [80220159] = {
            ["Content"] = "为师唯一要的，便是你在做出抉择之前细细思量，莫要让自己后悔才是。",
            ["ContentFR"] = "Tout ce que je te demande, c’est de réfléchir avant de faire ton choix. Ne vis pas dans le regret.",
            ["DialogueId"] = 80220159,
            ["GUID"] = "C8D29FD6",
            ["NextDialogue"] = 80220160,
            ["SpeakNpcId"] = 790074,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29FD6",
            },
        [80220160] = {
            ["Content"] = "谨遵教诲。",
            ["ContentFR"] = "Je suivrai votre enseignement.",
            ["DialogueId"] = 80220160,
            ["GUID"] = "C8D2A000",
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D2A000",
            },
        [80220201] = {
            ["Content"] = "……",
            ["ContentFR"] = "...",
            ["DialogueId"] = 80220201,
            ["GUID"] = "C8D2A6BA",
            ["NextDialogue"] = 80220202,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/002/C8D2A6BA",
            },
        [80220202] = {
            ["Content"] = "这是什么？不夏她……变成了妖物？！",
            ["ContentFR"] = "Qu’est-ce que... c’est quoi, ça ?! Buxia, elle... elle est devenue une créature ?!",
            ["DialogueId"] = 80220202,
            ["GUID"] = "C8D2A6E4",
            ["NextDialogue"] = 80220203,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/002/C8D2A6E4",
            },
        [80220203] = {
            ["Content"] = "……不要……别过来，我不想死！",
            ["ContentFR"] = "Non... non... reste loin de moi ! Je ne veux pas mourir !",
            ["DialogueId"] = 80220203,
            ["GUID"] = "C8D2A70E",
            ["NextDialogue"] = 80220204,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/002/C8D2A70E",
            },
        [80220204] = {
            ["Content"] = "莫非这便是……神君的惩罚……因为我们背弃了祂的恩泽？！",
            ["ContentFR"] = "Serait-ce... le châtiment du Seigneur divin... pour avoir renié Sa grâce ?!",
            ["DialogueId"] = 80220204,
            ["GUID"] = "C8D2A738",
            ["NextDialogue"] = 80220205,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/002/C8D2A738",
            },
        [80220205] = {
            ["Content"] = "爹爹、爹爹！呜呜……求你醒醒，求你说句话啊……",
            ["ContentFR"] = "Papa... papa... S’il te plaît... réveille-toi... dis quelque chose...",
            ["DialogueId"] = 80220205,
            ["GUID"] = "C8D2A762",
            ["NextDialogue"] = 80220206,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/002/C8D2A762",
            },
        }
  end },
  { MinKey = 80220206, MaxKey = 80230219, Loader = function()
      return {
        [80220206] = {
            ["Content"] = "师兄……救我……我，不想……",
            ["ContentFR"] = "Yuming... aide-moi... Je ne veux pas...",
            ["DialogueId"] = 80220206,
            ["GUID"] = "C8D2A78C",
            ["NextDialogue"] = 80220207,
            ["SpeakNpcId"] = 790073,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/002/C8D2A78C",
            },
        [80220207] = {
            ["Content"] = "…………",
            ["ContentFR"] = "...",
            ["DialogueId"] = 80220207,
            ["GUID"] = "C8D2A7B6",
            ["NextDialogue"] = 80220208,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/002/C8D2A7B6",
            },
        [80220208] = {
            ["Content"] = "是你让我看到这些的吗……太皓？",
            ["ContentFR"] = "Est-ce toi qui m’as montré tout cela... Taihao ?",
            ["DialogueId"] = 80220208,
            ["GUID"] = "C8D2A7E0",
            ["NextDialogue"] = 80220209,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/002/C8D2A7E0",
            },
        [80220209] = {
            ["Content"] = "非吾所为。吾无意窥伺凡人心神。",
            ["ContentFR"] = "Ce n’est pas mon œuvre. Je n’ai nul dessein de fouiller l’esprit des mortels.",
            ["DialogueId"] = 80220209,
            ["GUID"] = "C8D2A80A",
            ["NextDialogue"] = 80220210,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/002/C8D2A80A",
            },
        [80220210] = {
            ["Content"] = "你为什么会出现在我心中？我非但是一介凡人，还是一介飘零人。",
            ["ContentFR"] = "Alors pourquoi apparaître dans mon esprit ? Je ne suis qu’un simple mortel... et un Vagabond de surcroît.",
            ["DialogueId"] = 80220210,
            ["GUID"] = "C8D2A834",
            ["NextDialogue"] = 80220211,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/002/C8D2A834",
            },
        [80220211] = {
            ["Content"] = "汝心怀渴盼，欲吾解其惑。吾观汝非池中物，故应此愿。",
            ["ContentFR"] = "Ton cœur appelait, désireux de réponses. J’ai perçu en toi une volonté qui ne saurait se contenter d’une cage. C’est pour cela que j’ai répondu.",
            ["DialogueId"] = 80220211,
            ["GUID"] = "C8D2A85E",
            ["NextDialogue"] = 80220212,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/002/C8D2A85E",
            },
        [80220212] = {
            ["Content"] = "……原来我内心深处，竟真的期盼着你的回应。",
            ["ContentFR"] = "... Je ne pensais pas, au plus profond de moi-même, espérer réellement une réponse de ta part.",
            ["DialogueId"] = 80220212,
            ["GUID"] = "C8D2A888",
            ["NextDialogue"] = 80220213,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/002/C8D2A888",
            },
        [80220213] = {
            ["Content"] = "汝眼前种种，乃旧魇缚身，不得解脱。",
            ["ContentFR"] = "Ce que tu as vu n’était qu’un ancien cauchemar, un lien du passé dont tu ne t’es pas encore libéré.",
            ["DialogueId"] = 80220213,
            ["GUID"] = "C8D2A8B2",
            ["NextDialogue"] = 80220214,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/002/C8D2A8B2",
            },
        [80220214] = {
            ["Content"] = "……我知道。",
            ["ContentFR"] = "... Je le sais.",
            ["DialogueId"] = 80220214,
            ["GUID"] = "C8D2A8DC",
            ["NextDialogue"] = 80220215,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/002/C8D2A8DC",
            },
        [80220215] = {
            ["Content"] = "此其墓乎？",
            ["ContentFR"] = "Est-ce ici qu’elle repose ?",
            ["DialogueId"] = 80220215,
            ["GUID"] = "C8D2A906",
            ["NextDialogue"] = 80220216,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/002/C8D2A906",
            },
        [80220216] = {
            ["Content"] = "她……变成了那样，我甚至无法捡回她的遗骨。我只能寻得她的一些旧衣物，葬在这里。",
            ["ContentFR"] = "Elle... est devenue autre chose. Je n’ai même pas pu récupérer ses restes. Je n’ai retrouvé que quelques-uns de ses vêtements. C’est tout ce que j’ai pu enterrer ici.",
            ["DialogueId"] = 80220216,
            ["GUID"] = "C8D2A930",
            ["NextDialogue"] = 80220217,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/002/C8D2A930",
            },
        [80220217] = {
            ["Content"] = "之所以选择这里，而非山外山……",
            ["ContentFR"] = "Si je l’ai enterrée ici, et non aux Pics Extérieurs...",
            ["DialogueId"] = 80220217,
            ["GUID"] = "C8D2A95A",
            ["NextDialogue"] = 80220218,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/002/C8D2A95A",
            },
        [80220218] = {
            ["Content"] = "是因为她的最后一句话是，“如果当时我选择了大风九章，那么结果会不会不一样。”",
            ["ContentFR"] = "C’est parce que ses derniers mots furent : « Si, à l’époque, j’avais choisi les Neuf Chapitres de Dafeng... le résultat aurait-il été différent ? »",
            ["DialogueId"] = 80220218,
            ["GUID"] = "C8D2A984",
            ["NextDialogue"] = 80220219,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/002/C8D2A984",
            },
        [80220219] = {
            ["Content"] = "祖师扶风教诲过，医者对一切病患都应一视同仁，纵是飘零人也一样。但凡有一线生机，我又怎会不救她！",
            ["ContentFR"] = "La Patriarche Fufeng nous l’a enseigné : un médecin ne fait aucune distinction entre ses patients, pas même lorsqu’il s’agit de Vagabonds. Tant qu’il reste la moindre chance, comment pourrais-je refuser de la soigner ?",
            ["DialogueId"] = 80220219,
            ["GUID"] = "C8D2A9AE",
            ["NextDialogue"] = 80220220,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/002/C8D2A9AE",
            },
        [80220220] = {
            ["Content"] = "但那是秽蚀，是绝症，一旦开始发作，便再无半分转圜余地！她快要变成妖物了，你们还是趁这个机会赶紧逃命吧！",
            ["ContentFR"] = "Mais il s’agissait de la Dégradation... une maladie incurable. Une fois déclarée, il n’existe plus aucun retour possible. Elle est sur le point de devenir une créature monstrueuse. Partez. Profitez-en tant que vous le pouvez. Fuyez !",
            ["DialogueId"] = 80220220,
            ["GUID"] = "C8D2A9D8",
            ["NextDialogue"] = 80220221,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/002/C8D2A9D8",
            },
        [80220221] = {
            ["Content"] = "唉，若非你们飘零人执意脱离大风九章庇佑，又何至于此！",
            ["ContentFR"] = "Hélas... si vous, Vagabonds, n’aviez pas obstinément quitté la protection des Neuf Chapitres de Dafeng... rien de tout cela ne serait arrivé.",
            ["DialogueId"] = 80220221,
            ["GUID"] = "C8D2AA02",
            ["NextDialogue"] = 80220222,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/002/C8D2AA02",
            },
        [80220222] = {
            ["Content"] = "为师唯一要的，便是你在做出抉择之前细细思量，莫要让自己后悔才是。",
            ["ContentFR"] = "Tout ce que je te demande, c’est de réfléchir avant de faire ton choix. Ne vis pas dans le regret.",
            ["DialogueId"] = 80220222,
            ["GUID"] = "C8D2AA2C",
            ["NextDialogue"] = 80220223,
            ["SpeakNpcId"] = 790074,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/002/C8D2AA2C",
            },
        [80220223] = {
            ["Content"] = "……选择。",
            ["ContentFR"] = "... Un choix.",
            ["DialogueId"] = 80220223,
            ["GUID"] = "C8D2AA56",
            ["NextDialogue"] = 80220224,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/002/C8D2AA56",
            },
        [80220224] = {
            ["Content"] = "太皓，如果我们选择了大风九章，那么结果会不会不一样？",
            ["ContentFR"] = "Taihao... si nous avions choisi les Neuf Chapitres de Dafeng, le dénouement aurait-il été différent ?",
            ["DialogueId"] = 80220224,
            ["GUID"] = "C8D2AA80",
            ["NextDialogue"] = 80220225,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/002/C8D2AA80",
            },
        [80220225] = {
            ["Content"] = "汝等飘零人渴求无拘，却不知鸢无线而坠，川无堤不海。",
            ["ContentFR"] = "Vous, Vagabonds, aspirez à une liberté sans entraves, mais ignorez qu’un cerf-volant sans fil s’écrase, et qu’un fleuve sans digue devient un déluge.",
            ["DialogueId"] = 80220225,
            ["GUID"] = "C8D2AAAA",
            ["NextDialogue"] = 80220226,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/002/C8D2AAAA",
            },
        [80220226] = {
            ["Content"] = "往事已矣，来日可期。迷途知返，犹未晚也。",
            ["ContentFR"] = "Le passé est scellé. L’avenir, lui, demeure ouvert. Reconnaître son égarement et rebrousser chemin n’est jamais trop tard.",
            ["DialogueId"] = 80220226,
            ["GUID"] = "C8D2AAD4",
            ["NextDialogue"] = 80220227,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/002/C8D2AAD4",
            },
        [80220227] = {
            ["Content"] = "言尽于此，汝其慎思。",
            ["ContentFR"] = "J’ai dit ce qui devait l’être. Réfléchis avec soin.",
            ["DialogueId"] = 80220227,
            ["GUID"] = "C8D2AAFE",
            ["NextDialogue"] = 80220228,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/002/C8D2AAFE",
            },
        [80220228] = {
            ["Content"] = "太皓的幻影消失在了天际。",
            ["ContentFR"] = "L’illusion de Taihao se dissipe à l’horizon.",
            ["DialogueId"] = 80220228,
            ["GUID"] = "C8D2AB28",
            ["NextDialogue"] = 80220229,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/002/C8D2AB28",
            },
        [80220229] = {
            ["Content"] = "呜……",
            ["ContentFR"] = "Oouh...",
            ["DialogueId"] = 80220229,
            ["GUID"] = "C8D2AB52",
            ["NextDialogue"] = 80220230,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/002/C8D2AB52",
            },
        [80220230] = {
            ["Content"] = "……你还活着。原来那日，你是逃出了山外山吗……",
            ["ContentFR"] = "... Tu es en vie. Alors ce jour-là, tu as réussi à quitter les Pics Extérieurs...",
            ["DialogueId"] = 80220230,
            ["GUID"] = "C8D2AB7C",
            ["NextDialogue"] = 80220231,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/002/C8D2AB7C",
            },
        [80220231] = {
            ["Content"] = "呜……呜呜……",
            ["ContentFR"] = "Oouh... oouh...",
            ["DialogueId"] = 80220231,
            ["GUID"] = "C8D2ABA6",
            ["NextDialogue"] = 80220232,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/002/C8D2ABA6",
            },
        [80220232] = {
            ["Content"] = "你在哭吗？",
            ["ContentFR"] = "Tu pleures ?",
            ["DialogueId"] = 80220232,
            ["GUID"] = "C8D2ABD0",
            ["NextDialogue"] = 80220233,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/002/C8D2ABD0",
            },
        [80220233] = {
            ["Content"] = "是在哭她，哭师父，哭那些无辜的死难者——还是哭竟然心生叛意的我？",
            ["ContentFR"] = "Est-ce pour elle... pour le maître... pour ces innocents qui ont péri ? Ou est-ce pour moi... parce que mon cœur a vacillé ?",
            ["DialogueId"] = 80220233,
            ["GUID"] = "C8D2ABFA",
            ["NextDialogue"] = 80220234,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/002/C8D2ABFA",
            },
        [80220234] = {
            ["Content"] = "呜呜……",
            ["ContentFR"] = "Oouh...",
            ["DialogueId"] = 80220234,
            ["GUID"] = "C8D2AC24",
            ["NextDialogue"] = 80220235,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/002/C8D2AC24",
            },
        [80220235] = {
            ["Content"] = "你是打算让我带你回山外山吗？",
            ["ContentFR"] = "Tu veux que je te ramène aux Pics Extérieurs ?",
            ["DialogueId"] = 80220235,
            ["GUID"] = "C8D2AC4E",
            ["NextDialogue"] = 80220236,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/002/C8D2AC4E",
            },
        [80220236] = {
            ["Content"] = "呜呜！",
            ["ContentFR"] = "Ouh !",
            ["DialogueId"] = 80220236,
            ["GUID"] = "C8D2AC78",
            ["NextDialogue"] = 80220237,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/002/C8D2AC78",
            },
        [80220237] = {
            ["Content"] = "抱歉，我已经回不去了。",
            ["ContentFR"] = "Désolé. Je ne peux plus y retourner.",
            ["DialogueId"] = 80220237,
            ["GUID"] = "C8D2ACA2",
            ["NextDialogue"] = 80220238,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/002/C8D2ACA2",
            },
        [80220238] = {
            ["Content"] = "（不过……这只已经被驯服了的小野兽，如果不回山外山的话，恐怕是活不下去的。）",
            ["ContentFR"] = "Cette petite bête, déjà habituée à être protégée par les hommes... loin des Pics Extérieurs, elle ne survivrait pas.",
            ["DialogueId"] = 80220238,
            ["GUID"] = "C8D2ACCC",
            ["NextDialogue"] = 80220239,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/002/C8D2ACCC",
            },
        [80220239] = {
            ["Content"] = "山外山的方向在那边。接下来的路，便由你自己选择吧。",
            ["ContentFR"] = "Les Pics Extérieurs sont par là. La route qui t’attend désormais... c’est à toi d’en décider.",
            ["DialogueId"] = 80220239,
            ["GUID"] = "C8D2ACF6",
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/002/C8D2ACF6",
            },
        [80220301] = {
            ["Content"] = "……哈、哈……",
            ["ContentFR"] = "... Ha... ha...",
            ["DialogueId"] = 80220301,
            ["GUID"] = "C8D2B722",
            ["NextDialogue"] = 80220302,
            ["SpeakNpcId"] = 790075,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2B722",
            },
        [80220302] = {
            ["Content"] = "在山外山的时候不声不响，当狗倒是挺有本事。",
            ["ContentFR"] = "Muet comme une tombe aux Pics Extérieurs, mais pour faire le chien, là tu as du talent.",
            ["DialogueId"] = 80220302,
            ["GUID"] = "C8D2B74C",
            ["NextDialogue"] = 80220303,
            ["SpeakNpcId"] = 790075,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2B74C",
            },
        [80220303] = {
            ["Content"] = "……束手就擒吧。",
            ["ContentFR"] = "... Rends-toi.",
            ["DialogueId"] = 80220303,
            ["GUID"] = "C8D2B776",
            ["NextDialogue"] = 80220304,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2B776",
            },
        [80220304] = {
            ["Content"] = "束手就擒……好一个束手就擒！若旁人不知，怕不是真当我是罪人。",
            ["ContentFR"] = "Me rendre ? Quelle plaisanterie. À t’entendre, on croirait presque que c’est moi le criminel.",
            ["DialogueId"] = 80220304,
            ["GUID"] = "C8D2B7A0",
            ["NextDialogue"] = 80220305,
            ["SpeakNpcId"] = 790075,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2B7A0",
            },
        [80220305] = {
            ["Content"] = "你已犯戕身害命之罪，自为罪人，就此悔过才是正途。",
            ["ContentFR"] = "Tu t’es rendu coupable de blessures et d’homicides. Tu es un criminel. Le repentir est la seule voie qui te reste.",
            ["DialogueId"] = 80220305,
            ["GUID"] = "C8D2B7CA",
            ["NextDialogue"] = 80220306,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2B7CA",
            },
        [80220306] = {
            ["Content"] = "悔过？可笑！那老贼曲解契约，坑害劳苦欺压邻里，我不过是替天行道。",
            ["ContentFR"] = "Me repentir ? Risible. Ce vieux scélérat a dévoyé les contrats, pressuré les travailleurs et écrasé ses voisins. Je n’ai fait que rendre justice au nom du Ciel.",
            ["DialogueId"] = 80220306,
            ["GUID"] = "C8D2B7F4",
            ["NextDialogue"] = 80220307,
            ["SpeakNpcId"] = 790075,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2B7F4",
            },
        [80220307] = {
            ["Content"] = "僭权徇私，无可谓替天行道。天道既存，无需凡人替之。",
            ["ContentFR"] = "Usurper l’autorité pour servir ses intérêts n’est pas rendre justice. Si la Voie Céleste existe, elle n’a nul besoin que des mortels parlent en son nom.",
            ["DialogueId"] = 80220307,
            ["GUID"] = "C8D2B81E",
            ["NextDialogue"] = 80220308,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2B81E",
            },
        [80220308] = {
            ["Content"] = "天道既存？呸！我倒要问问，那老贼靠一纸阴阳契诈取钱财，害得无数人倾家荡产时，你的天道又在哪里？大风九章又在哪里？",
            ["ContentFR"] = "La Voie céleste, vraiment ? Alors dis-moi : quand ce vieil escroc utilisait un contrat truqué pour dépouiller des familles entières, quand d’innombrables foyers étaient ruinés, où était donc ta Voie Céleste ? Où étaient les Neuf Chapitres de Dafeng ?",
            ["DialogueId"] = 80220308,
            ["GUID"] = "C8D2B848",
            ["NextDialogue"] = 80220309,
            ["SpeakNpcId"] = 790075,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2B848",
            },
        [80220309] = {
            ["Content"] = "大风九章非一蹴而就，也非不可更改。这等恶性当如何裁断，太皓神君自有定夺，不容你我僭越。",
            ["ContentFR"] = "Les Neuf Chapitres n’ont pas été établis en un jour, et ils ne sont pas immuables. Comment juger de tels crimes relève de la décision de Taihao, et non de la nôtre. Nous n’avons pas le droit de nous arroger ce pouvoir.",
            ["DialogueId"] = 80220309,
            ["GUID"] = "C8D2B872",
            ["NextDialogue"] = 80220310,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2B872",
            },
        [80220310] = {
            ["Content"] = "……哈，冠冕堂皇。来吧，那就让我领教一番你这应天尉的本事！",
            ["ContentFR"] = "... Ha. De bien beaux discours. Très bien. Alors voyons ce que vaut réellement un Magistrat de Yingtian.",
            ["DialogueId"] = 80220310,
            ["GUID"] = "C8D2B89C",
            ["NextDialogue"] = 80220311,
            ["SpeakNpcId"] = 790075,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2B89C",
            },
        [80220311] = {
            ["Content"] = "煜明与飘零人兵刃相向。飘零人没几招就败下阵来。\
长枪刺向飘零人，却未刺破他的胸膛——\
而一枚断成两截的玉带钩，从他的胸前掉落。",
            ["ContentFR"] = "Yuming et le Vagabond croisent le fer. Le combat est bref. Le Vagabond est rapidement vaincu. La lance de Yuming frappe sa poitrine — mais ne la transperce pas. Une agrafe de ceinture en jade, brisée en deux, tombe de sa poitrine.",
            ["DialogueId"] = 80220311,
            ["GUID"] = "C8D2B8C6",
            ["NextDialogue"] = 80220312,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2B8C6",
            },
        [80220312] = {
            ["Content"] = "那是……师父的……",
            ["ContentFR"] = "C’est... l’agrafe du maître...",
            ["DialogueId"] = 80220312,
            ["GUID"] = "C8D2B8F0",
            ["NextDialogue"] = 80220313,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2B8F0",
            },
        [80220313] = {
            ["Content"] = "那日不夏秽蚀，他为掩护大家逃离而辞世。而我在血泊里捡起了他留下的这枚玉带钩。",
            ["ContentFR"] = "Le jour où la Dégradation a emporté Buxia, il est resté en arrière pour permettre aux autres de fuir. Je l’ai ramassée dans la mare de sang qu’il a laissée derrière lui.",
            ["DialogueId"] = 80220313,
            ["GUID"] = "C8D2B91A",
            ["NextDialogue"] = 80220314,
            ["SpeakNpcId"] = 790075,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2B91A",
            },
        [80220314] = {
            ["Content"] = "我将它小心翼翼地粘在一起，想留个念想……结果……该碎的东西还是要碎的。",
            ["ContentFR"] = "J’ai tenté de la recoller, de la conserver comme un souvenir... Mais ce qui est brisé\
est destiné à se briser à nouveau.",
            ["DialogueId"] = 80220314,
            ["GUID"] = "C8D2B944",
            ["NextDialogue"] = 80220315,
            ["SpeakNpcId"] = 790075,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2B944",
            },
        [80220315] = {
            ["Content"] = "飘零人无人不敬宴山亭，他告诉大家什么是恣意，什么是无拘，什么是虽千万人吾往矣，什么是一诺千金。",
            ["ContentFR"] = "Parmi les Vagabonds, tous respectaient Yan Shanting. Il nous a appris ce qu’était la liberté, l’absence de chaînes, le courage d’avancer même contre des milliers, et la valeur d’une parole donnée.",
            ["DialogueId"] = 80220315,
            ["GUID"] = "C8D2B96E",
            ["NextDialogue"] = 80220316,
            ["SpeakNpcId"] = 790075,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2B96E",
            },
        [80220316] = {
            ["Content"] = "但你呢？应天尉大人，他昔日的爱徒——竟选择背弃飘零人，向那条破龙摇尾乞怜！",
            ["ContentFR"] = "Et toi alors ? Magistrat de Yingtian... Son disciple favori, qui a tourné le dos aux Vagabonds pour aller remuer la queue devant cette misérable autorité !",
            ["DialogueId"] = 80220316,
            ["GUID"] = "C8D2B998",
            ["NextDialogue"] = 80220317,
            ["SpeakNpcId"] = 790075,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2B998",
            },
        [80220317] = {
            ["Content"] = "…………",
            ["ContentFR"] = "...",
            ["DialogueId"] = 80220317,
            ["GUID"] = "C8D2B9C2",
            ["NextDialogue"] = 80220318,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2B9C2",
            },
        [80220318] = {
            ["Content"] = "……你走吧。你既接下这一枪，便是上天要你命不该绝。",
            ["ContentFR"] = "... Pars. Si tu as survécu à ce coup, alors le Ciel n’a pas décrété que ton heure était venue.",
            ["DialogueId"] = 80220318,
            ["GUID"] = "C8D2B9EC",
            ["NextDialogue"] = 80220319,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2B9EC",
            },
        [80220319] = {
            ["Content"] = "……哼。",
            ["ContentFR"] = "... Hmpf.",
            ["DialogueId"] = 80220319,
            ["GUID"] = "C8D2BA16",
            ["NextDialogue"] = 80220320,
            ["SpeakNpcId"] = 790075,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2BA16",
            },
        [80220320] = {
            ["Content"] = "飘零人瞪了煜明一眼，转头奔去，直到消失在煜明的视线之外……",
            ["ContentFR"] = "Le Vagabond lance un dernier regard à Yuming, puis s’enfuit sous la pluie, jusqu’à disparaître de son champ de vision...",
            ["DialogueId"] = 80220320,
            ["GUID"] = "C8D2BA40",
            ["NextDialogue"] = 80220321,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2BA40",
            },
        [80220321] = {
            ["Content"] = "——本应如此。",
            ["ContentFR"] = "Cela aurait dû s’arrêter là.",
            ["DialogueId"] = 80220321,
            ["GUID"] = "C8D2BA6A",
            ["NextDialogue"] = 80220322,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2BA6A",
            },
        [80220322] = {
            ["Content"] = "但身后忽地有鼓鼓烈风吹来。未及煜明反应，飘零人已无气息。",
            ["ContentFR"] = "Mais soudain, une rafale violente surgit par l’arrière. Avant que Yuming n’ait le temps de réagir, le Vagabond s’effondre, sans vie.",
            ["DialogueId"] = 80220322,
            ["GUID"] = "C8D2BA94",
            ["NextDialogue"] = 80220323,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2BA94",
            },
        [80220323] = {
            ["Content"] = "不知何时从身后赶来的狴犴以利爪贯穿了飘零人的胸口。",
            ["ContentFR"] = "Un Bi’an est déjà sur lui. Ses griffes ont transpercé sa poitrine.",
            ["DialogueId"] = 80220323,
            ["GUID"] = "C8D2BABE",
            ["NextDialogue"] = 80220324,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2BABE",
            },
        [80220324] = {
            ["Content"] = "吼——",
            ["ContentFR"] = "Rooooaaar— !",
            ["DialogueId"] = 80220324,
            ["GUID"] = "C8D2BAE8",
            ["NextDialogue"] = 80220325,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2BAE8",
            },
        [80220325] = {
            ["Content"] = "…………",
            ["ContentFR"] = "...",
            ["DialogueId"] = 80220325,
            ["GUID"] = "C8D2BB12",
            ["NextDialogue"] = 80220326,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2BB12",
            },
        [80220326] = {
            ["Content"] = "煜明。",
            ["ContentFR"] = "Yuming.",
            ["DialogueId"] = 80220326,
            ["GUID"] = "C8D2BB3C",
            ["NextDialogue"] = 80220327,
            ["SpeakNpcId"] = 790074,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2BB3C",
            },
        [80220327] = {
            ["Content"] = "…………",
            ["ContentFR"] = "...",
            ["DialogueId"] = 80220327,
            ["GUID"] = "C8D2BB66",
            ["NextDialogue"] = 80220328,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2BB66",
            },
        [80220328] = {
            ["Content"] = "师父……",
            ["ContentFR"] = "Maître...",
            ["DialogueId"] = 80220328,
            ["GUID"] = "C8D2BB90",
            ["NextDialogue"] = 80220329,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2BB90",
            },
        [80220329] = {
            ["Content"] = "煜明，你又长高了，也长壮了。",
            ["ContentFR"] = "Tu as grandi, Yuming. Et tu t’es endurci.",
            ["DialogueId"] = 80220329,
            ["GUID"] = "C8D2BBBA",
            ["NextDialogue"] = 80220330,
            ["SpeakNpcId"] = 790074,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2BBBA",
            },
        [80220330] = {
            ["Content"] = "师父，我很多年前就不长个子了。",
            ["ContentFR"] = "Maître... je n’ai plus grandi depuis bien des années.",
            ["DialogueId"] = 80220330,
            ["GUID"] = "C8D2BBE4",
            ["NextDialogue"] = 80220331,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2BBE4",
            },
        [80220331] = {
            ["Content"] = "你这个孽徒！师父我好不容易想说句肉麻一点的开场白，你就在这里拆台。",
            ["ContentFR"] = "Petit insolent ! J’avais enfin préparé une entrée un peu sentimentale, et tu la réduis en miettes.",
            ["DialogueId"] = 80220331,
            ["GUID"] = "C8D2BC0E",
            ["NextDialogue"] = 80220332,
            ["SpeakNpcId"] = 790074,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2BC0E",
            },
        [80220332] = {
            ["Content"] = "你怎么了？一脸苦相，又在发愁？",
            ["ContentFR"] = "Qu’y a-t-il ? Encore ce visage tourmenté ?",
            ["DialogueId"] = 80220332,
            ["GUID"] = "C8D2BC38",
            ["NextDialogue"] = 80220333,
            ["SpeakNpcId"] = 790074,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2BC38",
            },
        [80220333] = {
            ["Content"] = "……没有……",
            ["ContentFR"] = "... Rien...",
            ["DialogueId"] = 80220333,
            ["GUID"] = "C8D2BC62",
            ["NextDialogue"] = 80220334,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2BC62",
            },
        [80220334] = {
            ["Content"] = "扯谎。说过多少次了，你这孩子，一说谎就两个字两个字往外蹦。",
            ["ContentFR"] = "Mensonge. Je te l’ai dit cent fois : quand tu mens, tu ne prononces jamais plus de deux mots.",
            ["DialogueId"] = 80220334,
            ["GUID"] = "C8D2BC8C",
            ["NextDialogue"] = 80220335,
            ["SpeakNpcId"] = 790074,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2BC8C",
            },
        [80220335] = {
            ["Content"] = "师父，您是来训斥徒儿的吗？",
            ["ContentFR"] = "Maître... êtes-vous venu me réprimander ?",
            ["DialogueId"] = 80220335,
            ["GUID"] = "C8D2BCB6",
            ["NextDialogue"] = 80220336,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2BCB6",
            },
        [80220336] = {
            ["Content"] = "徒儿辜负了您的期待，与昔日旧友兵刃相向。",
            ["ContentFR"] = "J’ai trahi vos attentes. J’ai croisé le fer avec d’anciens compagnons.",
            ["DialogueId"] = 80220336,
            ["GUID"] = "C8D2BCE0",
            ["NextDialogue"] = 80220337,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2BCE0",
            },
        [80220337] = {
            ["Content"] = "我背叛了您，背弃了飘零人，皈依了大风九章。如今，我已无面目见您。",
            ["ContentFR"] = "Je vous ai trahi. J’ai renié les Vagabonds. J’ai choisi les Neuf Chapitres de Dafeng. Aujourd’hui, je n’ai plus le courage de vous faire face.",
            ["DialogueId"] = 80220337,
            ["GUID"] = "C8D2BD0A",
            ["NextDialogue"] = 80220338,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2BD0A",
            },
        [80220338] = {
            ["Content"] = "死脑筋。我宴山亭聪明一世，怎就教出来你这块榆木疙瘩。",
            ["ContentFR"] = "Tête de mule. Moi qui me suis toujours cru brillant, comment ai-je pu former un disciple aussi obtus ?",
            ["DialogueId"] = 80220338,
            ["GUID"] = "C8D2BD34",
            ["NextDialogue"] = 80220339,
            ["SpeakNpcId"] = 790074,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2BD34",
            },
        [80220339] = {
            ["Content"] = "徒儿愚钝。",
            ["ContentFR"] = "Votre disciple manque de discernement.",
            ["DialogueId"] = 80220339,
            ["GUID"] = "C8D2BD5E",
            ["NextDialogue"] = 80220340,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2BD5E",
            },
        [80220340] = {
            ["Content"] = "我只问你一句，你可曾后悔过？",
            ["ContentFR"] = "Je vais te poser une seule question. As-tu déjà regretté ce choix ?",
            ["DialogueId"] = 80220340,
            ["GUID"] = "C8D2BD88",
            ["NextDialogue"] = 80220341,
            ["SpeakNpcId"] = 790074,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2BD88",
            },
        [80220341] = {
            ["Content"] = "煜明……不知。",
            ["ContentFR"] = "Yuming... ne le sait pas.",
            ["DialogueId"] = 80220341,
            ["GUID"] = "C8D2BDB2",
            ["NextDialogue"] = 80220342,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2BDB2",
            },
        [80220342] = {
            ["Content"] = "那为师换个问法，若往日再起，你是否还会像当初那样成为应天尉？",
            ["ContentFR"] = "Alors posons la question autrement. Si le temps revenait en arrière, choisirais-tu encore de devenir Magistrat de Yingtian ?",
            ["DialogueId"] = 80220342,
            ["GUID"] = "C8D2BDDC",
            ["NextDialogue"] = 80220343,
            ["SpeakNpcId"] = 790074,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2BDDC",
            },
        [80220343] = {
            ["Content"] = "……会。",
            ["ContentFR"] = "... Oui.",
            ["DialogueId"] = 80220343,
            ["GUID"] = "C8D2BE06",
            ["NextDialogue"] = 80220344,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2BE06",
            },
        [80220344] = {
            ["Content"] = "为何？",
            ["ContentFR"] = "Pourquoi ?",
            ["DialogueId"] = 80220344,
            ["GUID"] = "C8D2BE30",
            ["NextDialogue"] = 80220345,
            ["SpeakNpcId"] = 790074,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2BE30",
            },
        [80220345] = {
            ["Content"] = "大风九章之下，我们失去了洒脱，失去了快意恩仇，失去了一部分正义。可……<H>坏的规则也好过没有规则</>。",
            ["ContentFR"] = "Sous les Neuf Chapitres, nous avons perdu une part de liberté, une part de justice immédiate. Mais... <H>mieux vaut des règles imparfaites que l’absence totale de règles</>.",
            ["DialogueId"] = 80220345,
            ["GUID"] = "C8D2BE5A",
            ["NextDialogue"] = 80220346,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2BE5A",
            },
        [80220346] = {
            ["Content"] = "若无大风九章，世道失序，人间只会变得更糟。纵有飘零人惩恶扬善，也不过杯水车薪。",
            ["ContentFR"] = "Sans les Neuf Chapitres, le monde sombrerait dans le chaos. Même les Vagabonds, aussi déterminés soient-ils à punir le mal, ne peuvent qu’en atténuer les symptômes.",
            ["DialogueId"] = 80220346,
            ["GUID"] = "C8D2BE84",
            ["NextDialogue"] = 80220347,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2BE84",
            },
        [80220347] = {
            ["Content"] = "更何况，我已不想再看到不夏的事情重演一次。",
            ["ContentFR"] = "Et surtout... je ne veux plus jamais voir ce qui est arrivé à Buxia se reproduire.",
            ["DialogueId"] = 80220347,
            ["GUID"] = "C8D2BEAE",
            ["NextDialogue"] = 80220348,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2BEAE",
            },
        [80220348] = {
            ["Content"] = "……我不想再有下一位大英雄宴山亭死去了。",
            ["ContentFR"] = "... Je ne veux plus voir un autre Yan Shanting mourir en héros.",
            ["DialogueId"] = 80220348,
            ["GUID"] = "C8D2BED8",
            ["NextDialogue"] = 80220349,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2BED8",
            },
        [80220349] = {
            ["Content"] = "哈哈……哈哈！你既已遵循本心，又何须多言。纵然身不由己，但若让你重来一世仍会坚持曾经的抉择，旁人又说得什么？",
            ["ContentFR"] = "Ha... ha ha ! Puisque tu as suivi ton cœur, que reste-t-il à dire ? Même si le choix t’a été imposé, si tu devais revivre cette vie, tu choisirais encore de la même façon. Qui aurait alors le droit de te juger ?",
            ["DialogueId"] = 80220349,
            ["GUID"] = "C8D2BF02",
            ["NextDialogue"] = 80220350,
            ["SpeakNpcId"] = 790074,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2BF02",
            },
        [80220350] = {
            ["Content"] = "哪怕如今的我已与曾经的师父势不两立？",
            ["ContentFR"] = "Même si aujourd’hui, je me dresse contre vous... contre le maître que j’admirais autrefois ?",
            ["DialogueId"] = 80220350,
            ["GUID"] = "C8D2BF2C",
            ["NextDialogue"] = 80220351,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2BF2C",
            },
        [80220351] = {
            ["Content"] = "垂髫尊父母，弱冠循师长，不惑事权贵，耳顺系子女。可若人的一生如此遵从他人所制定好的路途，不曾自己做出选择，又怎么说是活过。",
            ["ContentFR"] = "Enfant, on suit ses parents. À l’âge adulte, ses maîtres. Puis les puissants. Puis ses propres enfants. Mais si un homme passe sa vie entière sur une route tracée par d’autres, sans jamais faire un seul choix par lui-même... Alors peut-on vraiment dire qu’il a vécu ?",
            ["DialogueId"] = 80220351,
            ["GUID"] = "C8D2BF56",
            ["NextDialogue"] = 80220352,
            ["SpeakNpcId"] = 790074,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2BF56",
            },
        [80220352] = {
            ["Content"] = "为师从来只教你<H>行无悔之事</>，可从未教过你跟在师父后面亦步亦趋，做那跟屁虫。",
            ["ContentFR"] = "Je ne t’ai jamais enseigné de me suivre aveuglément. Je ne t’ai appris qu’une chose : <H>vivre sans regret</>.",
            ["DialogueId"] = 80220352,
            ["GUID"] = "C8D2BF80",
            ["NextDialogue"] = 80220353,
            ["SpeakNpcId"] = 790074,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2BF80",
            },
        [80220353] = {
            ["Content"] = "煜明，你可记得我为何要反抗大风九章？",
            ["ContentFR"] = "Yuming, te souviens-tu de la raison pour laquelle j’ai défié les Neuf Chapitres ?",
            ["DialogueId"] = 80220353,
            ["GUID"] = "C8D2BFAA",
            ["NextDialogue"] = 80220354,
            ["SpeakNpcId"] = 790074,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2BFAA",
            },
        [80220354] = {
            ["Content"] = "为了不让世人困于囚笼，永无自立之本？",
            ["ContentFR"] = "Pour que les hommes ne soient pas enfermés dans une cage sans jamais apprendre à se tenir debout ?",
            ["DialogueId"] = 80220354,
            ["GUID"] = "C8D2BFD4",
            ["NextDialogue"] = 80220355,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2BFD4",
            },
        [80220355] = {
            ["Content"] = "不，是为了在天道之外，夺取<H>另一种选择的权利</>。",
            ["ContentFR"] = "Non. C’était pour arracher, au-delà même de la Voie Céleste, le <H>droit de choisir une autre voie</>.",
            ["DialogueId"] = 80220355,
            ["GUID"] = "C8D2BFFE",
            ["NextDialogue"] = 80220356,
            ["SpeakNpcId"] = 790074,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2BFFE",
            },
        [80220356] = {
            ["Content"] = "山外山虽与大风九章为敌，却向来任意来去。这是因为飘零人应当是人生的另一种可能，而不应成为另一个樊笼。",
            ["ContentFR"] = "Les Pics Extérieurs s’opposent aux Neuf Chapitres, mais ont toujours laissé chacun venir et partir librement. Être Vagabond doit rester un choix. Pas une autre prison.",
            ["DialogueId"] = 80220356,
            ["GUID"] = "C8D2C028",
            ["NextDialogue"] = 80220357,
            ["SpeakNpcId"] = 790074,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2C028",
            },
        [80220357] = {
            ["Content"] = "不要再惩罚自己了，煜明。因为……",
            ["ContentFR"] = "Ne te punis plus, Yuming. Parce que...",
            ["DialogueId"] = 80220357,
            ["GUID"] = "C8D2C052",
            ["NextDialogue"] = 80220358,
            ["SpeakNpcId"] = 790074,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2C052",
            },
        [80220358] = {
            ["Content"] = "你是我的骄傲。",
            ["ContentFR"] = "Tu es ma fierté.",
            ["DialogueId"] = 80220358,
            ["GUID"] = "C8D2C07C",
            ["NextDialogue"] = 80220359,
            ["SpeakNpcId"] = 790074,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2C07C",
            },
        [80220359] = {
            ["Content"] = "师父……",
            ["ContentFR"] = "Maître...",
            ["DialogueId"] = 80220359,
            ["GUID"] = "C8D2C0A6",
            ["NextDialogue"] = 80220360,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2C0A6",
            },
        [80220360] = {
            ["Content"] = "徒儿……谨遵教诲！",
            ["ContentFR"] = "Votre disciple... suivra fidèlement votre enseignement.",
            ["DialogueId"] = 80220360,
            ["GUID"] = "C8D2C0D0",
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2C0D0",
            },
        [80220401] = {
            ["Content"] = "煜明？是你在吹奏吗？",
            ["ContentFR"] = "Yuming ? C’était toi qui jouais ?",
            ["DialogueId"] = 80220401,
            ["GUID"] = "C8D2C78A",
            ["NextDialogue"] = 80220402,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2C78A",
            },
        [80220402] = {
            ["Content"] = "{nickname}……别来无恙。",
            ["ContentFR"] = "{nickname}... Tu vas bien ?",
            ["DialogueId"] = 80220402,
            ["GUID"] = "C8D2C7B4",
            ["NextDialogue"] = 80220403,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2C7B4",
            },
        [80220403] = {
            ["Content"] = "没想到你还会这一手，以前从来没见过。",
            ["ContentFR"] = "Je ne savais pas que tu savais jouer. Je ne t’ai jamais vu faire ça avant.",
            ["DialogueId"] = 80220403,
            ["GUID"] = "C8D2C7DE",
            ["NextDialogue"] = 80220404,
            ["SpeakNpcId"] = 790008,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2C7DE",
            },
        [80220404] = {
            ["Content"] = "虽未能为所有百姓排忧解难，倒也确实事务繁忙，无暇抽身。",
            ["ContentFR"] = "Je n’ai pas su soulager toutes les peines du peuple... mais les affaires ne manquaient jamais. Je n’ai guère eu le loisir de m’arrêter.",
            ["DialogueId"] = 80220404,
            ["GUID"] = "C8D2C808",
            ["NextDialogue"] = 80220405,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2C808",
            },
        [80220405] = {
            ["Content"] = "如今烛阴归位，辩法回归，人神共治，我等太皓代行之人反倒落得清闲。",
            ["ContentFR"] = "À présent, Zhuyin a retrouvé sa place, le Rite de Délibération a repris, et dieux comme mortels gouvernent de concert. Ceux d’entre nous qui agissaient au nom de Taihao se retrouvent, ironiquement, avec du temps libre.",
            ["DialogueId"] = 80220405,
            ["GUID"] = "C8D2C832",
            ["NextDialogue"] = 80220406,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2C832",
            },
        [80220406] = {
            ["Content"] = "怎么听起来好像有些落寞……",
            ["ContentFR"] = "À t’entendre... on dirait presque que tu te sens seul.",
            ["DialogueId"] = 80220406,
            ["GUID"] = "C8D2C85C",
            ["NextDialogue"] = 80220407,
            ["SpeakNpcId"] = 790008,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2C85C",
            },
        [80220407] = {
            ["Content"] = "见笑了。",
            ["ContentFR"] = "Pardonne-moi. Je me laisse aller à la mélancolie.",
            ["DialogueId"] = 80220407,
            ["GUID"] = "C8D2C886",
            ["NextDialogue"] = 80220408,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2C886",
            },
        [80220408] = {
            ["Content"] = "山外山……算是你的故乡吧。",
            ["ContentFR"] = "Les Pics Extérieurs... c’est un peu ton pays natal, non ?",
            ["DialogueId"] = 80220408,
            ["GUID"] = "C8D2C8B0",
            ["NextDialogue"] = 80220409,
            ["SpeakNpcId"] = 790008,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2C8B0",
            },
        [80220409] = {
            ["Content"] = "你是打算回去看看他们？",
            ["ContentFR"] = "Tu pensais retourner les voir ?",
            ["DialogueId"] = 80220409,
            ["GUID"] = "C8D2C8DA",
            ["NextDialogue"] = 80220410,
            ["SpeakNpcId"] = 790008,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2C8DA",
            },
        [80220410] = {
            ["Content"] = "……并未。",
            ["ContentFR"] = "... Non.",
            ["DialogueId"] = 80220410,
            ["GUID"] = "C8D2C904",
            ["NextDialogue"] = 80220411,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2C904",
            },
        [80220411] = {
            ["Content"] = "我……只是路过。我为应天尉太久，与他们早已殊途。",
            ["ContentFR"] = "Je... ne faisais que passer. J’ai été Magistrat de Yingtian trop longtemps. Nos chemins se sont depuis longtemps séparés.",
            ["DialogueId"] = 80220411,
            ["GUID"] = "C8D2C92E",
            ["NextDialogue"] = 80220412,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2C92E",
            },
        [80220412] = {
            ["Content"] = "比赛一事，我已完成止流嘱托，往后便不再见了吧。",
            ["ContentFR"] = "Quant au tournoi, j’ai accompli ce que Zhiliu m’avait confié. Après cela... nous n’aurons sans doute plus de raison de nous revoir.",
            ["DialogueId"] = 80220412,
            ["GUID"] = "C8D2C958",
            ["NextDialogue"] = 80220413,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2C958",
            },
        [80220413] = {
            ["Content"] = "那真是太可惜了。我来找你，原本是刻舟让我给你带个话——",
            ["ContentFR"] = "C’est bien dommage. Si je suis venu te chercher, c’est parce que Kezhou m’a demandé de te transmettre un message—",
            ["DialogueId"] = 80220413,
            ["GUID"] = "C8D2C982",
            ["NextDialogue"] = 80220414,
            ["SpeakNpcId"] = 790008,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2C982",
            },
        [80220414] = {
            ["Content"] = "他说什么？",
            ["ContentFR"] = "Qu’a-t-il dit ?",
            ["DialogueId"] = 80220414,
            ["GUID"] = "C8D2C9AC",
            ["NextDialogue"] = 80220415,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2C9AC",
            },
        [80220415] = {
            ["Content"] = "你看，这不是还是很关心山外山的人们嘛。",
            ["ContentFR"] = "Tu vois... tu te soucies encore beaucoup des gens des Pics Extérieurs.",
            ["DialogueId"] = 80220415,
            ["GUID"] = "C8D2C9D6",
            ["NextDialogue"] = 80220416,
            ["SpeakNpcId"] = 790008,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2C9D6",
            },
        [80220416] = {
            ["Content"] = "…………！",
            ["ContentFR"] = "... !",
            ["DialogueId"] = 80220416,
            ["GUID"] = "C8D2CA00",
            ["NextDialogue"] = 80220417,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2CA00",
            },
        [80220417] = {
            ["Content"] = "呵呵。",
            ["ContentFR"] = "Hm.",
            ["DialogueId"] = 80220417,
            ["GUID"] = "C8D2CA2A",
            ["NextDialogue"] = 80220418,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2CA2A",
            },
        [80220418] = {
            ["Content"] = "你笑了？这在你们华胥好像是叫什么——铁做的木头也会开花？",
            ["ContentFR"] = "Tu souris ? Chez vous, à Huaxu, on appelle ça comment déjà... « Même le plus dur des bois finit par fleurir » ?",
            ["DialogueId"] = 80220418,
            ["GUID"] = "C8D2CA54",
            ["NextDialogue"] = 80220419,
            ["SpeakNpcId"] = 790008,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2CA54",
            },
        [80220419] = {
            ["Content"] = "我只是觉得，你开起玩笑来像我和刻舟的师父。",
            ["ContentFR"] = "Je pensais simplement que ta manière de plaisanter me rappelle mon maître... et Kezhou.",
            ["DialogueId"] = 80220419,
            ["GUID"] = "C8D2CA7E",
            ["NextDialogue"] = 80220420,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2CA7E",
            },
        [80220420] = {
            ["Content"] = "听刻舟说那是个糟老头子。唉，你这究竟算是夸我还是算在阴阳怪气。",
            ["ContentFR"] = "D’après Kezhou, c’était un vieux grincheux. Alors dis-moi... c’est un compliment, ou une pique déguisée ?",
            ["DialogueId"] = 80220420,
            ["GUID"] = "C8D2CAA8",
            ["NextDialogue"] = 80220421,
            ["SpeakNpcId"] = 790008,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2CAA8",
            },
        [80220421] = {
            ["Content"] = "……{nickname}。",
            ["ContentFR"] = "... {nickname}.",
            ["DialogueId"] = 80220421,
            ["GUID"] = "C8D2CAD2",
            ["NextDialogue"] = 80220422,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2CAD2",
            },
        [80220422] = {
            ["Content"] = "怎么了？",
            ["ContentFR"] = "Qu’y a-t-il ?",
            ["DialogueId"] = 80220422,
            ["GUID"] = "C8D2CAFC",
            ["NextDialogue"] = 80220423,
            ["SpeakNpcId"] = 790008,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2CAFC",
            },
        [80220423] = {
            ["Content"] = "依你所见，我此前所践行之路，能称之为正确吗？",
            ["ContentFR"] = "Dis-moi... à tes yeux, la voie que j’ai suivie jusqu’ici... peut-elle être qualifiée de juste ?",
            ["DialogueId"] = 80220423,
            ["GUID"] = "C8D2CB26",
            ["NextDialogue"] = 80220424,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2CB26",
            },
        [80220424] = {
            ["Content"] = "这个问题……问我？",
            ["ContentFR"] = "Tu poses vraiment cette question... à moi ?",
            ["DialogueId"] = 80220424,
            ["GUID"] = "C8D2CB50",
            ["NextDialogue"] = 80220425,
            ["SpeakNpcId"] = 790008,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2CB50",
            },
        [80220425] = {
            ["Content"] = "的确。",
            ["ContentFR"] = "Oui.",
            ["DialogueId"] = 80220425,
            ["GUID"] = "C8D2CB7A",
            ["NextDialogue"] = 80220426,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2CB7A",
            },
        [80220426] = {
            ["Content"] = "这个问题，你不是早就应该自己得到答案了吗？",
            ["ContentFR"] = "Ce n’est pas une réponse que tu aurais déjà dû trouver par toi-même ?",
            ["DialogueId"] = 80220426,
            ["GUID"] = "C8D2CBA4",
            ["NextDialogue"] = 80220427,
            ["SpeakNpcId"] = 790008,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2CBA4",
            },
        [80220427] = {
            ["Content"] = "师父曾说：前路荒芜，砥砺前行，皆是前人未至之处。",
            ["ContentFR"] = "Mon maître disait : « La route à venir est aride, mais avancer, c’est marcher là où nul n’est encore allé. »",
            ["DialogueId"] = 80220427,
            ["GUID"] = "C8D2CBCE",
            ["NextDialogue"] = 80220428,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2CBCE",
            },
        [80220428] = {
            ["Content"] = "吾等须一日三省，问天、问人、问心。三省无愧，即是前程。",
            ["ContentFR"] = "Il disait aussi : « Nous devons nous interroger trois fois par jour — devant le Ciel, devant les hommes, et devant notre propre cœur. Si, après ces trois questions, on ne ressent aucune honte... alors la route vaut d’être empruntée. »",
            ["DialogueId"] = 80220428,
            ["GUID"] = "C8D2CBF8",
            ["NextDialogue"] = 80220429,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2CBF8",
            },
        [80220429] = {
            ["Content"] = "本以为尘埃落定后，又要重新经历这三问，会无比漫长痛苦。就像过去的日子里，不夏、刻舟、师父、太皓……他们的身影总出现在我眼前，令我整夜无眠。",
            ["ContentFR"] = "Je pensais qu’une fois la poussière retombée, il me faudrait à nouveau affronter ces trois interrogations, longuement, douloureusement. Comme autrefois,\
quand Buxia, Kezhou, le maître... et même Taihao venaient hanter mes nuits.",
            ["DialogueId"] = 80220429,
            ["GUID"] = "C8D2CC22",
            ["NextDialogue"] = 80220430,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2CC22",
            },
        [80220430] = {
            ["Content"] = "但当真迈开脚步，反倒也没有如旧日般迷惘了。",
            ["ContentFR"] = "Mais lorsque j’ai réellement fait le premier pas... je me suis aperçu que je n’étais plus aussi perdu.",
            ["DialogueId"] = 80220430,
            ["GUID"] = "C8D2CC4C",
            ["NextDialogue"] = 80220431,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2CC4C",
            },
        [80220431] = {
            ["Content"] = "只是向他人寻求答案的习惯一时半会还没改过来？",
            ["ContentFR"] = "Tu n’as simplement pas encore perdu l’habitude de chercher des réponses chez les autres ?",
            ["DialogueId"] = 80220431,
            ["GUID"] = "C8D2CC76",
            ["NextDialogue"] = 80220432,
            ["SpeakNpcId"] = 790008,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2CC76",
            },
        [80220432] = {
            ["Content"] = "经年如此，莫要见怪。",
            ["ContentFR"] = "Des années de réflexes... pardonne-moi.",
            ["DialogueId"] = 80220432,
            ["GUID"] = "C8D2CCA0",
            ["NextDialogue"] = 80220433,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2CCA0",
            },
        [80220433] = {
            ["Content"] = "看开一点，连龙神都说要改变了，属于一个人的改变又有什么好奇怪的？",
            ["ContentFR"] = "Relativise. Même le Seigneur Dragon parle de changer. Alors qu’y a-t-il d’étrange à ce qu’une seule personne fasse de même ?",
            ["DialogueId"] = 80220433,
            ["GUID"] = "C8D2CCCA",
            ["NextDialogue"] = 80220434,
            ["SpeakNpcId"] = 790008,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2CCCA",
            },
        [80220434] = {
            ["Content"] = "……说的也是。你说话很像我的师父，让我豁然开朗。",
            ["ContentFR"] = "... Tu as raison. Tu parles comme mon maître. Et tes mots m’éclairent.",
            ["DialogueId"] = 80220434,
            ["GUID"] = "C8D2CCF4",
            ["NextDialogue"] = 80220435,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2CCF4",
            },
        [80220435] = {
            ["Content"] = "说了不要把我比作老头子了。",
            ["ContentFR"] = "Je t’ai dit d’arrêter de me comparer à un vieil homme.",
            ["DialogueId"] = 80220435,
            ["GUID"] = "C8D2CD1E",
            ["NextDialogue"] = 80220436,
            ["SpeakNpcId"] = 790008,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2CD1E",
            },
        [80220436] = {
            ["Content"] = "呜嗷——",
            ["ContentFR"] = "Aouh—",
            ["DialogueId"] = 80220436,
            ["GUID"] = "C8D2CD48",
            ["NextDialogue"] = 80220437,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2CD48",
            },
        [80220437] = {
            ["Content"] = "什么声音……狐狸叫？",
            ["ContentFR"] = "C’était quoi, ça... un renard ?",
            ["DialogueId"] = 80220437,
            ["GUID"] = "C8D2CD72",
            ["NextDialogue"] = 80220438,
            ["SpeakNpcId"] = 790008,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2CD72",
            },
        [80220438] = {
            ["Content"] = "……是你？小橙子？！",
            ["ContentFR"] = "... Toi ? Juju ?!",
            ["DialogueId"] = 80220438,
            ["GUID"] = "C8D2CD9C",
            ["NextDialogue"] = 80220439,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2CD9C",
            },
        [80220439] = {
            ["Content"] = "嗷嗷——嗷呜！",
            ["ContentFR"] = "Aouh ! Aouuuh !",
            ["DialogueId"] = 80220439,
            ["GUID"] = "C8D2CDC6",
            ["NextDialogue"] = 80220440,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2CDC6",
            },
        [80220440] = {
            ["Content"] = "你没有回山外山。还有，你还活着。",
            ["ContentFR"] = "Tu n’es pas retourné aux Pics Extérieurs... et tu es toujours en vie.",
            ["DialogueId"] = 80220440,
            ["GUID"] = "C8D2CDF0",
            ["NextDialogue"] = 80220441,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2CDF0",
            },
        [80220441] = {
            ["Content"] = "嗷呜！",
            ["ContentFR"] = "Aouh !",
            ["DialogueId"] = 80220441,
            ["GUID"] = "C8D2CE1A",
            ["NextDialogue"] = 80220442,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2CE1A",
            },
        [80220442] = {
            ["Content"] = "你已经长得这么大了，也比过去精神得多。当年我以为，如果你不回山外山，一定会冻死饿死在野外……看来竟是我想错了。",
            ["ContentFR"] = "Tu as grandi. Tu as meilleure allure qu’avant. À l’époque, je pensais que si tu ne retournais pas aux Pics Extérieurs, tu mourrais de froid ou de faim. Il semblerait que je me sois trompé.",
            ["DialogueId"] = 80220442,
            ["GUID"] = "C8D2CE44",
            ["NextDialogue"] = 80220443,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2CE44",
            },
        [80220443] = {
            ["Content"] = "生命每个选择得到的结果，原是无定数的。一切，都要自己走上那条路后方才知晓。",
            ["ContentFR"] = "Le résultat de chaque choix n’est jamais écrit à l’avance. Ce n’est qu’en empruntant réellement un chemin que l’on découvre où il mène.",
            ["DialogueId"] = 80220443,
            ["GUID"] = "C8D2CE6E",
            ["NextDialogue"] = 80220444,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2CE6E",
            },
        [80220444] = {
            ["Content"] = "嗷呜！嗷呜！",
            ["ContentFR"] = "Aouh ! Aouh !",
            ["DialogueId"] = 80220444,
            ["GUID"] = "C8D2CE98",
            ["NextDialogue"] = 80220445,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2CE98",
            },
        [80220445] = {
            ["Content"] = "那是山外山的方向。你是想喊我一起回去看看？",
            ["ContentFR"] = "Les Pics Extérieurs sont par là. Tu veux que je rentre avec toi... juste pour aller les revoir ?",
            ["DialogueId"] = 80220445,
            ["GUID"] = "C8D2CEC2",
            ["NextDialogue"] = 80220446,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2CEC2",
            },
        [80220446] = {
            ["Content"] = "嗷呜！",
            ["ContentFR"] = "Aouh !",
            ["DialogueId"] = 80220446,
            ["GUID"] = "C8D2CEEC",
            ["NextDialogue"] = 80220447,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2CEEC",
            },
        [80220447] = {
            ["Content"] = "……我明白了。那么，{nickname}，后会有期。",
            ["ContentFR"] = "... Je comprends. Alors, {nickname}... à la prochaine.",
            ["DialogueId"] = 80220447,
            ["GUID"] = "C8D2CF16",
            ["NextDialogue"] = 80220448,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2CF16",
            },
        [80220448] = {
            ["Content"] = "去吧，他们在等你。",
            ["ContentFR"] = "Vas-y. Ils t’attendent.",
            ["DialogueId"] = 80220448,
            ["GUID"] = "C8D2CF40",
            ["SpeakNpcId"] = 790008,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2CF40",
            },
        [80230101] = {
            ["Content"] = "龙渊上卿拔擢仪式即刻开始——诸位受太皓青睐者，请依序入觐——",
            ["ContentFR"] = "La cérémonie de sélection du Haut Chancelier de Longyuan va commencer — Que ceux qui ont reçu la faveur de Taihao avancent, dans l’ordre imparti —",
            ["DialogueId"] = 80230101,
            ["GUID"] = "C8D8FEF2",
            ["NextDialogue"] = 80230102,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/001/C8D8FEF2",
            },
        [80230102] = {
            ["DialogueId"] = 80230102,
            ["GUID"] = "C8D8FF1C",
            ["NextDialogue"] = 80230103,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/001/C8D8FF1C",
            },
        [80230103] = {
            ["Content"] = "我乃现任龙渊上卿，目前协理天礼司。今日代行太皓旨意，特来考教诸君气量、心智与觉悟。",
            ["ContentFR"] = "Je suis l’actuelle Haut Chancelier de Longyuan, et j’exerce également au sein du Bureau des Rites. Par décret de Taihao, je suis chargée d’éprouver votre envergure, votre jugement et votre éveil.",
            ["DialogueId"] = 80230103,
            ["GUID"] = "C8D8FF46",
            ["NextDialogue"] = 80230104,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/001/C8D8FF46",
            },
        [80230104] = {
            ["Content"] = "今日于执律阁内，我等一举一动，一言一行，都将由祂见证。纤毫必现，心念亦无可隐遁。",
            ["ContentFR"] = "En ce jour, dans le Pavillon de l’Arbitrage, chacun de vos gestes, chacune de vos paroles sera observée par Son regard. Rien ne pourra être dissimulé — pas même la plus infime pensée.",
            ["DialogueId"] = 80230104,
            ["GUID"] = "C8D8FF70",
            ["NextDialogue"] = 80230105,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/001/C8D8FF70",
            },
        [80230105] = {
            ["Content"] = "最终裁决非我所能定夺。唯有太皓之神意，方能决断谁人有资格承此重任。",
            ["ContentFR"] = "La décision finale ne m’appartient pas. Seule la volonté divine de Taihao tranchera quant à celui ou celle qui est digne de porter ce fardeau.",
            ["DialogueId"] = 80230105,
            ["GUID"] = "C8D8FF9A",
            ["NextDialogue"] = 80230106,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/001/C8D8FF9A",
            },
        [80230106] = {
            ["Content"] = "望诸君谨记此间神圣，摒除杂念，以尔等本心与真知应对考问。现在，仪式开始——",
            ["ContentFR"] = "Souvenez-vous de la sainteté de ce lieu. Écartez toute pensée parasite, et répondez avec sincérité et lucidité. À présent — que la cérémonie commence.",
            ["DialogueId"] = 80230106,
            ["GUID"] = "C8D8FFC4",
            ["NextDialogue"] = 80230107,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/001/C8D8FFC4",
            },
        [80230107] = {
            ["Content"] = "上前来。先介绍一下自己吧，家住何处，姓甚名谁？",
            ["ContentFR"] = "Approchez. Présentez-vous. D’où venez-vous, et quel est votre nom ?",
            ["DialogueId"] = 80230107,
            ["GUID"] = "C8D8FFEE",
            ["NextDialogue"] = 80230108,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/001/C8D8FFEE",
            },
        [80230108] = {
            ["Content"] = "回大人，我名顾砚，乃本地人士，祖上数代都长居皓京脚下的椒兰村中。",
            ["ContentFR"] = "Votre Excellence, je me nomme Gu Yan. Je suis natif de ces terres ; ma famille réside depuis des générations au Village de Jiaolan, au pied de Haojing.",
            ["DialogueId"] = 80230108,
            ["GUID"] = "C8D90018",
            ["NextDialogue"] = 80230109,
            ["SpeakNpcId"] = 790078,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/001/C8D90018",
            },
        [80230109] = {
            ["Content"] = "不必这么拘谨。龙渊上卿的吉兆降于你身时，你的家人想必高兴得紧吧？",
            ["ContentFR"] = "Inutile d’être si nerveux. Lorsque le présage du Haut Chancelier de Longyuan s’est posé sur vous, votre famille a dû s’en réjouir grandement, n’est-ce pas ?",
            ["DialogueId"] = 80230109,
            ["GUID"] = "C8D90042",
            ["NextDialogue"] = 80230110,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/001/C8D90042",
            },
        [80230110] = {
            ["Content"] = "那是当然！狴犴刚衔着吉讯到来时，家母她老人家还没想到会发生什么。等她后知后觉反应过来顾家竟然要出一位龙渊上卿了，高兴得差点昏厥过去。",
            ["ContentFR"] = "Évidemment ! Lorsque le Bi’an est venu porter l’heureuse nouvelle, ma mère n’en comprenait pas encore la portée. Mais lorsqu’elle a réalisé que notre lignée allait donner naissance à un Haut Chancelier, elle a failli s’évanouir de joie.",
            ["DialogueId"] = 80230110,
            ["GUID"] = "C8D9006C",
            ["NextDialogue"] = 80230111,
            ["SpeakNpcId"] = 790078,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/001/C8D9006C",
            },
        [80230111] = {
            ["Content"] = "事后，家母把那日飘落的香花都一瓣瓣拾了起来，精心装裱，说要作为之后子子孙孙的传家宝供起来呢。",
            ["ContentFR"] = "Par la suite, elle a ramassé un à un les pétales parfumés tombés ce jour-là, les a fait encadrer avec le plus grand soin, affirmant qu’ils deviendraient un trésor transmis à nos descendants.",
            ["DialogueId"] = 80230111,
            ["GUID"] = "C8D90096",
            ["NextDialogue"] = 80230112,
            ["SpeakNpcId"] = 790078,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/001/C8D90096",
            },
        [80230112] = {
            ["Content"] = "呵呵，获得太皓的青睐只是第一步。接下来，你们还要通过三道试炼，才能加身龙渊上卿之殊荣。",
            ["ContentFR"] = "Hm... Recevoir la faveur de Taihao n’est que la première étape. Il vous faudra encore franchir trois épreuves avant de pouvoir prétendre à cet honneur.",
            ["DialogueId"] = 80230112,
            ["GUID"] = "C8D900C0",
            ["NextDialogue"] = 80230113,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/001/C8D900C0",
            },
        [80230113] = {
            ["Content"] = "那么，闲谈就到此为止。请对答——",
            ["ContentFR"] = "Assez de bavardages. Répondez maintenant —",
            ["DialogueId"] = 80230113,
            ["GUID"] = "C8D900EA",
            ["NextDialogue"] = 80230114,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/001/C8D900EA",
            },
        [80230114] = {
            ["Content"] = "华胥人生而知大风九章。但你可曾想过，大风九章究其根本为何物？",
            ["ContentFR"] = "Le peuple de Huaxu grandit en récitant les Neuf Chapitres de Dafeng. Mais vous êtes-vous déjà interrogé sur leur véritable nature ?",
            ["DialogueId"] = 80230114,
            ["GUID"] = "C8D90114",
            ["NextDialogue"] = 80230115,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/001/C8D90114",
            },
        [80230115] = {
            ["Content"] = "……自然是太皓神力的流溢。",
            ["ContentFR"] = "... Ils sont, sans l’ombre d’un doute, l’émanation de la puissance divine de Taihao.",
            ["DialogueId"] = 80230115,
            ["GUID"] = "C8D9013E",
            ["NextDialogue"] = 80230116,
            ["SpeakNpcId"] = 790078,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/001/C8D9013E",
            },
        [80230116] = {
            ["Content"] = "大风九章有如日月轮转，江河奔流，是天地自然之理。它存在于此，亘古如斯。纵地裂山崩，江水为竭，冬雷夏雪，沧海桑田，它仍如日月般恒久不变。",
            ["ContentFR"] = "Les Neuf Chapitres sont semblables au cycle du soleil et de la lune, au cours des fleuves se jetant vers la mer — ils incarnent l’ordre naturel du Ciel et de la Terre. Depuis des temps immémoriaux, ils demeurent inchangés. Quand bien même le monde serait bouleversé, les montagnes réduites en poussière et les océans asséchés, ils subsisteraient, éternels comme les astres.",
            ["DialogueId"] = 80230116,
            ["GUID"] = "C8D90168",
            ["NextDialogue"] = 80230117,
            ["SpeakNpcId"] = 790078,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/001/C8D90168",
            },
        [80230117] = {
            ["Content"] = "我等尊奉大风九章，就和鱼得水逝而相忘乎水，鸟乘风飞而不知有风是一样的道理。",
            ["ContentFR"] = "Nous honorons les Neuf Chapitres comme le poisson honore l’eau, ou l’oiseau le vent — vivant en leur sein, sans même en avoir pleinement conscience.",
            ["DialogueId"] = 80230117,
            ["GUID"] = "C8D90192",
            ["NextDialogue"] = 80230118,
            ["SpeakNpcId"] = 790078,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/001/C8D90192",
            },
        [80230118] = {
            ["Content"] = "你对神君的虔诚，祂与我等皆已知悉。先下去歇息，回家静候吧。",
            ["ContentFR"] = "Votre ferveur est manifeste. Taihao en est témoin, tout comme moi. Retirez-vous pour l’instant. Rentrez chez vous et attendez la décision.",
            ["DialogueId"] = 80230118,
            ["GUID"] = "C8D901BC",
            ["NextDialogue"] = 80230119,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/001/C8D901BC",
            },
        [80230119] = {
            ["Content"] = "下一位。",
            ["ContentFR"] = "Suivant.",
            ["DialogueId"] = 80230119,
            ["GUID"] = "C8D901E6",
            ["NextDialogue"] = 80230120,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/001/C8D901E6",
            },
        [80230120] = {
            ["DialogueId"] = 80230120,
            ["GUID"] = "C8D90210",
            ["NextDialogue"] = 80230121,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/001/C8D90210",
            },
        [80230121] = {
            ["Content"] = "晚辈止流，见过大人。",
            ["ContentFR"] = "Votre Excellence. Je me nomme Zhiliu.",
            ["DialogueId"] = 80230121,
            ["GUID"] = "C8D9023A",
            ["NextDialogue"] = 80230122,
            ["SpeakNpcId"] = 790076,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/001/C8D9023A",
            },
        [80230122] = {
            ["Content"] = "止流，你要回答的问题，与上个人相同——“大风九章究其根本为何物？”",
            ["ContentFR"] = "Zhiliu. La question qui vous est posée est la même que pour votre prédécesseur — quelle est, selon vous, la nature profonde des Neuf Chapitres de Dafeng ?",
            ["DialogueId"] = 80230122,
            ["GUID"] = "C8D90264",
            ["NextDialogue"] = 80230123,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/001/C8D90264",
            },
        [80230123] = {
            ["Content"] = "……您问的是大风九章的“本质”……",
            ["ContentFR"] = "... Vous interrogez leur essence.",
            ["DialogueId"] = 80230123,
            ["GUID"] = "C8D9028E",
            ["NextDialogue"] = 80230124,
            ["SpeakNpcId"] = 790076,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/001/C8D9028E",
            },
        [80230124] = {
            ["Content"] = "止流心中确有拙见。但若有冒犯，还请大人和神君宽恕晚辈无知。",
            ["ContentFR"] = "J’ai, à ce sujet, une humble opinion. Si mes paroles venaient à dépasser ma condition, j’implore d’avance votre indulgence, ainsi que celle de Taihao.",
            ["DialogueId"] = 80230124,
            ["GUID"] = "C8D902B8",
            ["NextDialogue"] = 80230125,
            ["SpeakNpcId"] = 790076,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/001/C8D902B8",
            },
        [80230125] = {
            ["Content"] = "哦？那依你之见，这“本质”该如何解读？",
            ["ContentFR"] = "Oh ? Exposez donc votre compréhension de cette « essence ».",
            ["DialogueId"] = 80230125,
            ["GUID"] = "C8D902E2",
            ["NextDialogue"] = 80230126,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/001/C8D902E2",
            },
        [80230126] = {
            ["Content"] = "太皓非自然之天道，而是顺应民心而生。",
            ["ContentFR"] = "Taihao n’est pas une loi céleste née de la nature elle-même. Il est issu de la volonté des peuples.",
            ["DialogueId"] = 80230126,
            ["GUID"] = "C8D9030C",
            ["NextDialogue"] = 80230127,
            ["SpeakNpcId"] = 790076,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/001/C8D9030C",
            },
        [80230127] = {
            ["Content"] = "昔日华胥子民久罹战祸，厌倦纷争，故而先祖矩、飏回应众人对和平的盼望，以无上伟力铸就大风九章之基石。",
            ["ContentFR"] = "Autrefois, les habitants de Huaxu étaient las des guerres incessantes. Épuisés par les conflits, ils aspiraient à la paix. Répondant à ce vœu, les ancêtres Ju et Yang posèrent les fondations des Neuf Chapitres de Dafeng, leur conférant une puissance sans égale.",
            ["DialogueId"] = 80230127,
            ["GUID"] = "C8D90336",
            ["NextDialogue"] = 80230128,
            ["SpeakNpcId"] = 790076,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/001/C8D90336",
            },
        [80230128] = {
            ["Content"] = "神与万民实为相互成就，缺一不可。万民自愿收兵止戈，将裁定善恶之权柄托付于太皓，以己身信守诫律，如此才造就了今日的华胥。",
            ["ContentFR"] = "Les dieux et les peuples se sont ainsi accomplis mutuellement. L’un ne saurait exister sans l’autre. Les hommes déposèrent volontairement les armes, confièrent à Taihao le droit de juger le bien et le mal, et s’engagèrent à respecter ses préceptes. C’est ainsi que Huaxu prit la forme que nous lui connaissons aujourd’hui.",
            ["DialogueId"] = 80230128,
            ["GUID"] = "C8D90360",
            ["NextDialogue"] = 80230129,
            ["SpeakNpcId"] = 790076,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/001/C8D90360",
            },
        [80230129] = {
            ["Content"] = "与此同时，太皓回应万民心愿，使允诺的和平化为现实，泽被苍生。于是生生不息，往复循环。故而大风九章的本质，实为双方达成的<H>誓约</>。",
            ["ContentFR"] = "En retour, Taihao transforma la promesse de paix en réalité, étendant sa bénédiction à tous les êtres. Un cycle sans fin, perpétuellement renouvelé. De ce fait, l’essence des Neuf Chapitres de Dafeng réside dans un <H>pacte</> — un engagement librement consenti par les deux parties.",
            ["DialogueId"] = 80230129,
            ["GUID"] = "C8D9038A",
            ["NextDialogue"] = 80230130,
            ["SpeakNpcId"] = 790076,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/001/C8D9038A",
            },
        [80230130] = {
            ["Content"] = "……好一个誓约之说，你这解读却是大胆。",
            ["ContentFR"] = "... Un pacte, dites-vous. Votre interprétation est audacieuse.",
            ["DialogueId"] = 80230130,
            ["GUID"] = "C8D903B4",
            ["NextDialogue"] = 80230131,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/001/C8D903B4",
            },
        [80230131] = {
            ["Content"] = "我且问你，你说太皓回应万民心愿，但那些太皓照耀不到的民心，又该如何看待呢？",
            ["ContentFR"] = "Permettez-moi alors une autre question. Vous affirmez que Taihao répond aux vœux du peuple — mais qu’en est-il de ceux que Sa lumière n’atteint pas ?",
            ["DialogueId"] = 80230131,
            ["GUID"] = "C8D903DE",
            ["NextDialogue"] = 80230132,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/001/C8D903DE",
            },
        [80230132] = {
            ["Content"] = "近来有些对大风九章的坊间杂言，其中不乏飘零人的推波助澜，相信你也有所耳闻——不必忌讳这个话题。",
            ["ContentFR"] = "Des rumeurs circulent récemment à propos des Neuf Chapitres, attisées notamment par certains Vagabonds. Vous n’ignorez pas ces propos — inutile d’éluder le sujet.",
            ["DialogueId"] = 80230132,
            ["GUID"] = "C8D90408",
            ["NextDialogue"] = 80230133,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/001/C8D90408",
            },
        [80230133] = {
            ["Content"] = "回大人，不同人的内心有千万种声音，神明统合了众人的心愿后，却只能保有一种声音。人人遂心所愿的世界，大约是不存在的。",
            ["ContentFR"] = "Les cœurs humains abritent d’innombrables voix. Même lorsqu’un dieu recueille les aspirations de la multitude, il ne peut en préserver qu’une seule. Un monde où chacun verrait ses désirs pleinement exaucés n’existe probablement pas.",
            ["DialogueId"] = 80230133,
            ["GUID"] = "C8D90432",
            ["NextDialogue"] = 80230134,
            ["SpeakNpcId"] = 790076,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/001/C8D90432",
            },
        [80230134] = {
            ["Content"] = "凝聚多数之共识，规训少数之异见，这是构建秩序的代价，亦为社稷存续的根基。",
            ["ContentFR"] = "Unir la majorité autour d’un consensus, discipliner la dissidence de la minorité — tel est le prix de l’ordre, et le fondement de la pérennité de l’État.",
            ["DialogueId"] = 80230134,
            ["GUID"] = "C8D9045C",
            ["NextDialogue"] = 80230135,
            ["SpeakNpcId"] = 790076,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/001/C8D9045C",
            },
        [80230135] = {
            ["Content"] = "有点意思……再说一遍你的名字，叫什么来着？",
            ["ContentFR"] = "Intéressant... Répétez-moi votre nom.",
            ["DialogueId"] = 80230135,
            ["GUID"] = "C8D90486",
            ["NextDialogue"] = 80230136,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/001/C8D90486",
            },
        [80230136] = {
            ["Content"] = "止流，不吝赐教。",
            ["ContentFR"] = "Zhiliu. Je suis à votre écoute, Votre Excellence.",
            ["DialogueId"] = 80230136,
            ["GUID"] = "C8D904B0",
            ["NextDialogue"] = 80230137,
            ["SpeakNpcId"] = 790076,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/001/C8D904B0",
            },
        [80230137] = {
            ["Content"] = "止狂澜，断万流……是个寓意不错的名字。回去等消息吧。",
            ["ContentFR"] = "« Apaiser les flots déchaînés, interrompre les courants indociles... » Un nom de bon augure. Retournez attendre la décision.",
            ["DialogueId"] = 80230137,
            ["GUID"] = "C8D904DA",
            ["NextDialogue"] = 80230138,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/001/C8D904DA",
            },
        [80230138] = {
            ["Content"] = "止流，我见你有眼缘，便多叮嘱你一句。",
            ["ContentFR"] = "Zhiliu. Vous avez su retenir mon attention. Permettez-moi donc un dernier avertissement.",
            ["DialogueId"] = 80230138,
            ["GUID"] = "C8D90504",
            ["NextDialogue"] = 80230139,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/001/C8D90504",
            },
        [80230139] = {
            ["Content"] = "——治国乃修罗之道，你须承担百般恶名，漠视万民冤屈。你下定决心了吗？",
            ["ContentFR"] = "— Gouverner un État, c’est emprunter la voie du carnage. Vous devrez endosser l’infamie, et détourner le regard des plaintes du peuple. Avez-vous réellement pris cette résolution ?",
            ["DialogueId"] = 80230139,
            ["GUID"] = "C8D9052E",
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/001/C8D9052E",
            },
        [80230201] = {
            ["Content"] = "大风九章出错了——有冤情！我要伸冤！",
            ["ContentFR"] = "Les Neuf Chapitres de Dafeng se sont trompés — il y a eu une injustice ! Je réclame réparation !",
            ["DialogueId"] = 80230201,
            ["GUID"] = "C8D90F5A",
            ["NextDialogue"] = 80230202,
            ["SpeakNpcId"] = 790077,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D90F5A",
            },
        [80230202] = {
            ["Content"] = "这位大人，求您了，听听我要说的话吧，只需要耽误您一点时间——",
            ["ContentFR"] = "Je vous en prie, honorable personne, écoutez-moi... cela ne vous prendra qu’un instant—",
            ["DialogueId"] = 80230202,
            ["GUID"] = "C8D90F84",
            ["NextDialogue"] = 80230203,
            ["SpeakNpcId"] = 790077,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D90F84",
            },
        [80230203] = {
            ["Content"] = "请您稍留片刻——",
            ["ContentFR"] = "Je vous en supplie... accordez-moi un moment—",
            ["DialogueId"] = 80230203,
            ["GUID"] = "C8D90FAE",
            ["NextDialogue"] = 80230204,
            ["SpeakNpcId"] = 790077,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D90FAE",
            },
        [80230204] = {
            ["DialogueId"] = 80230204,
            ["GUID"] = "C8D90FD8",
            ["NextDialogue"] = 80230205,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D90FD8",
            },
        [80230205] = {
            ["Content"] = "出什么事了？",
            ["ContentFR"] = "Que se passe-t-il ?",
            ["DialogueId"] = 80230205,
            ["GUID"] = "C8D91002",
            ["NextDialogue"] = 80230206,
            ["SpeakNpcId"] = 790076,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D91002",
            },
        [80230206] = {
            ["Content"] = "——！",
            ["ContentFR"] = "— !",
            ["DialogueId"] = 80230206,
            ["GUID"] = "C8D9102C",
            ["NextDialogue"] = 80230207,
            ["SpeakNpcId"] = 790077,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D9102C",
            },
        [80230207] = {
            ["Content"] = "我先前身患重病，被一位泽生阁的医师所救。治好我的那位医师，她甚至未收分文，却被狴犴惩处身亡了！",
            ["ContentFR"] = "J’étais atteinte d’une maladie grave. Une médecin de la Pharmacie Zesheng m’a sauvée. Elle n’a jamais accepté le moindre paiement... et pourtant, elle a été exécutée par un Bi’an !",
            ["DialogueId"] = 80230207,
            ["GUID"] = "C8D91056",
            ["NextDialogue"] = 80230208,
            ["SpeakNpcId"] = 790077,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D91056",
            },
        [80230208] = {
            ["Content"] = "求求你们，至少——至少把清誉还给她吧！她是个一心救人的医师啊，大风九章判她的药害了我，但那只是暂时的药效变化而已。",
            ["ContentFR"] = "Je vous en prie... au moins — au moins rendez-lui son honneur ! C’était une médecin dévouée, uniquement animée par le désir de sauver des vies ! Les Neuf Chapitres de Dafeng ont jugé que son remède m’avait nui, mais ce n’était qu’un effet temporaire !",
            ["DialogueId"] = 80230208,
            ["GUID"] = "C8D91080",
            ["NextDialogue"] = 80230209,
            ["SpeakNpcId"] = 790077,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D91080",
            },
        [80230209] = {
            ["Content"] = "我病情复杂，当时看了很多医师都只是摆摆手表示无能为力，只有她提出用以毒攻毒的险方一试。",
            ["ContentFR"] = "Ma maladie était complexe. Tous les autres médecins refusaient de me prendre en charge. Elle seule a osé proposer une méthode risquée — combattre le mal par le mal.",
            ["DialogueId"] = 80230209,
            ["GUID"] = "C8D910AA",
            ["NextDialogue"] = 80230210,
            ["SpeakNpcId"] = 790077,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D910AA",
            },
        [80230210] = {
            ["Content"] = "服药后可能出现惊厥，甚至短暂的呼吸停止，这些后果她都与我详细说过。我甘愿承担这风险，却没想到最终反倒牵连了她。",
            ["ContentFR"] = "Elle m’a expliqué chaque danger : convulsions, voire un arrêt temporaire de la respiration. J’ai accepté ces risques de mon plein gré... je n’aurais jamais imaginé que cela lui coûterait la vie.",
            ["DialogueId"] = 80230210,
            ["GUID"] = "C8D910D4",
            ["NextDialogue"] = 80230211,
            ["SpeakNpcId"] = 790077,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D910D4",
            },
        [80230211] = {
            ["Content"] = "你的意思是，大风九章错判了治疗过程，使治你的人含冤而死，是吗？",
            ["ContentFR"] = "Si je comprends bien, vous affirmez que les Neuf Chapitres de Dafeng ont mal jugé le traitement, et que celle qui vous a soignée est morte sous une accusation infondée. Est-ce bien cela ?",
            ["DialogueId"] = 80230211,
            ["GUID"] = "C8D910FE",
            ["NextDialogue"] = 80230212,
            ["SpeakNpcId"] = 790076,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D910FE",
            },
        [80230212] = {
            ["Content"] = "就是这样！我还好端端地站在这里呢，不然还有死人诈尸的道理吗？",
            ["ContentFR"] = "Exactement ! Je me tiens encore devant vous, bien vivante. Les morts ne se relèvent pas pour protester, n’est-ce pas ?",
            ["DialogueId"] = 80230212,
            ["GUID"] = "C8D91128",
            ["NextDialogue"] = 80230213,
            ["SpeakNpcId"] = 790077,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D91128",
            },
        [80230213] = {
            ["Content"] = "我还活着，救我的人却因此去世了。我……我没有办法接受这种事。",
            ["ContentFR"] = "Je suis en vie... et celle qui m’a sauvée est morte pour cela. Je... je ne peux accepter une telle injustice.",
            ["DialogueId"] = 80230213,
            ["GUID"] = "C8D91152",
            ["NextDialogue"] = 80230214,
            ["SpeakNpcId"] = 790077,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D91152",
            },
        [80230214] = {
            ["Content"] = "我明白了。这件事情我不敢保证什么，但我会尽力而为。",
            ["ContentFR"] = "Je comprends. Je ne peux rien vous promettre, mais je ferai ce qui est en mon pouvoir.",
            ["DialogueId"] = 80230214,
            ["GUID"] = "C8D9117C",
            ["NextDialogue"] = 80230215,
            ["SpeakNpcId"] = 790076,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D9117C",
            },
        [80230215] = {
            ["Content"] = "——谢谢您！谢谢！",
            ["ContentFR"] = "Merci... Merci infiniment.",
            ["DialogueId"] = 80230215,
            ["GUID"] = "C8D911A6",
            ["NextDialogue"] = 80230216,
            ["SpeakNpcId"] = 790077,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D911A6",
            },
        [80230216] = {
            ["Content"] = "……其实我知道这件事情非常难，您可能也没办法做到什么。我在这里站了好几天了，只有您一个人愿意停下来听我说话……",
            ["ContentFR"] = "... En réalité, je sais combien cette affaire est difficile. Vous ne pourrez peut-être rien y changer. Je suis restée ici plusieurs jours — vous êtes la seule personne à vous être arrêtée pour m’écouter...",
            ["DialogueId"] = 80230216,
            ["GUID"] = "C8D911D0",
            ["NextDialogue"] = 80230217,
            ["SpeakNpcId"] = 790077,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D911D0",
            },
        [80230217] = {
            ["Content"] = "哪怕是为了这点善意，我也要感谢您……",
            ["ContentFR"] = "Ne serait-ce que pour cette bonté, je vous en suis reconnaissante.",
            ["DialogueId"] = 80230217,
            ["GUID"] = "C8D911FA",
            ["NextDialogue"] = 80230218,
            ["SpeakNpcId"] = 790077,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D911FA",
            },
        [80230218] = {
            ["Content"] = "呵呵，只是无足挂齿的小事而已。",
            ["ContentFR"] = "Ce n’est qu’une chose sans importance.",
            ["DialogueId"] = 80230218,
            ["GUID"] = "C8D91224",
            ["NextDialogue"] = 80230219,
            ["SpeakNpcId"] = 790076,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D91224",
            },
        [80230219] = {
            ["DialogueId"] = 80230219,
            ["GUID"] = "C8D9124E",
            ["NextDialogue"] = 80230220,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D9124E",
            },
        }
  end },
  { MinKey = 80230220, MaxKey = 80240235, Loader = function()
      return {
        [80230220] = {
            ["Content"] = "各位既已到齐，接下来便开始第二道试炼——",
            ["ContentFR"] = "Puisque vous êtes tous présents, nous allons à présent entamer la seconde épreuve.",
            ["DialogueId"] = 80230220,
            ["GUID"] = "C8D91278",
            ["NextDialogue"] = 80230221,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D91278",
            },
        [80230221] = {
            ["Content"] = "……有冤……我要申冤！",
            ["ContentFR"] = "... Il y a eu injustice... Je réclame réparation...",
            ["DialogueId"] = 80230221,
            ["GUID"] = "C8D912A2",
            ["NextDialogue"] = 80230222,
            ["SpeakNpcId"] = 790077,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D912A2",
            },
        [80230222] = {
            ["Content"] = "那女孩怎么还在执律阁下闹个不停？既让路人烦扰不堪，也扰了太皓清净。大人，不如请应天尉将她清退吧！",
            ["ContentFR"] = "Pourquoi cette fille fait-elle encore scandale sous le Pavillon ? Elle importune les passants et trouble la quiétude de Taihao. Votre Excellence, ne vaudrait-il pas mieux demander au Magistrat de Yingtian de la faire évacuer ?",
            ["DialogueId"] = 80230222,
            ["GUID"] = "C8D912CC",
            ["NextDialogue"] = 80230223,
            ["SpeakNpcId"] = 790080,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D912CC",
            },
        [80230223] = {
            ["Content"] = "稍安勿躁，她便是你们今日的试题。",
            ["ContentFR"] = "Calmez-vous. Elle est précisément l’épreuve d’aujourd’hui.",
            ["DialogueId"] = 80230223,
            ["GUID"] = "C8D912F6",
            ["NextDialogue"] = 80230224,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D912F6",
            },
        [80230224] = {
            ["Content"] = "（嘈杂的议论声）\
配音：什么？真的吗？（复数人声）",
            ["ContentFR"] = "Quoi ? Vraiment ?",
            ["DialogueId"] = 80230224,
            ["GUID"] = "C8D91320",
            ["NextDialogue"] = 80230225,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D91320",
            },
        [80230225] = {
            ["Content"] = "大风九章作为经年累月运转的庞大体系，哪怕是万分之一的几率，也会产生纰漏。",
            ["ContentFR"] = "Les Neuf Chapitres de Dafeng forment un système colossal, fonctionnant sans relâche depuis des générations. Même une infime probabilité d’erreur finit, avec le temps, par engendrer des failles.",
            ["DialogueId"] = 80230225,
            ["GUID"] = "C8D9134A",
            ["NextDialogue"] = 80230226,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D9134A",
            },
        [80230226] = {
            ["Content"] = "如何辅助太皓妥善处理这些纰漏，是治理国家的重要一环，也是今日为诸位所设置的考察。诸位有想法，都可以畅所欲言。",
            ["ContentFR"] = "Savoir assister Taihao dans le traitement de ces failles constitue un pilier de la gouvernance. C’est l’objet de votre épreuve. Exprimez vos idées sans réserve.",
            ["DialogueId"] = 80230226,
            ["GUID"] = "C8D91374",
            ["NextDialogue"] = 80230227,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D91374",
            },
        [80230227] = {
            ["Content"] = "大人，大风九章的正义早已深入人心。这种杂音，不予理会就是。",
            ["ContentFR"] = "Votre Excellence, la légitimité des Neuf Chapitres est profondément ancrée dans le cœur du peuple. Ces voix dissonantes ne méritent aucune attention.",
            ["DialogueId"] = 80230227,
            ["GUID"] = "C8D9139E",
            ["NextDialogue"] = 80230228,
            ["SpeakNpcId"] = 790080,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D9139E",
            },
        [80230228] = {
            ["Content"] = "千里之堤，溃于蚁穴。如果长期放任不管，只会助长了山外山那等势力的气焰，造成隐患。",
            ["ContentFR"] = "Un barrage de mille lieues peut céder à cause d’une simple fourmi. Fermer les yeux trop longtemps ne ferait qu’encourager des forces telles que les Pics Extérieurs, et nourrir des menaces latentes.",
            ["DialogueId"] = 80230228,
            ["GUID"] = "C8D913C8",
            ["NextDialogue"] = 80230229,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D913C8",
            },
        [80230229] = {
            ["Content"] = "依我看，不外乎威逼利诱二种做法！给出足够强力的威胁，或者足够动人的利益交换，再顽固的人也会败下阵来。",
            ["ContentFR"] = "À mes yeux, il n’existe que deux moyens : la contrainte ou l’appât du gain. Une menace suffisamment dissuasive, ou une récompense assez séduisante, et même les plus obstinés finiront par céder.",
            ["DialogueId"] = 80230229,
            ["GUID"] = "C8D913F2",
            ["NextDialogue"] = 80230230,
            ["SpeakNpcId"] = 790081,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D913F2",
            },
        [80230230] = {
            ["Content"] = "人非草木。你若是轻视了人心，引起对方反弹，非但平息不了风波，只会让事情更加棘手。",
            ["ContentFR"] = "Les hommes ne sont pas de simples plantes. Mépriser le cœur humain ne peut qu’engendrer un retour de flamme. Vous n’apaiserez rien — vous ne ferez qu’aggraver les choses.",
            ["DialogueId"] = 80230230,
            ["GUID"] = "C8D9141C",
            ["NextDialogue"] = 80230231,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D9141C",
            },
        [80230231] = {
            ["Content"] = "（嘈杂的议论声）\
配音：这也不行，那也不行？那该如何是好（复数人声）",
            ["ContentFR"] = "Ça ne va pas non plus ? Alors... que faut-il faire ?",
            ["DialogueId"] = 80230231,
            ["GUID"] = "C8D91446",
            ["NextDialogue"] = 80230232,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D91446",
            },
        [80230232] = {
            ["Content"] = "我有一法，且让我试试吧。",
            ["ContentFR"] = "J’ai une solution. Permettez-moi d’essayer.",
            ["DialogueId"] = 80230232,
            ["GUID"] = "C8D91470",
            ["NextDialogue"] = 80230233,
            ["SpeakNpcId"] = 790076,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D91470",
            },
        [80230233] = {
            ["DialogueId"] = 80230233,
            ["GUID"] = "C8D9149A",
            ["NextDialogue"] = 80230234,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D9149A",
            },
        [80230234] = {
            ["Content"] = "好心的姐姐，是您……您来见我了！",
            ["ContentFR"] = "Vous... c’est vous... vous êtes revenue...",
            ["DialogueId"] = 80230234,
            ["GUID"] = "C8D914C4",
            ["NextDialogue"] = 80230235,
            ["SpeakNpcId"] = 790077,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D914C4",
            },
        [80230235] = {
            ["Content"] = "这么快就回来，难不成……您有什么办法了？",
            ["ContentFR"] = "Si vite... auriez-vous trouvé un moyen ?",
            ["DialogueId"] = 80230235,
            ["GUID"] = "C8D914EE",
            ["NextDialogue"] = 80230236,
            ["SpeakNpcId"] = 790077,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D914EE",
            },
        [80230236] = {
            ["Content"] = "抱歉，你的诉求，我恐怕没法满足。",
            ["ContentFR"] = "Je suis désolée. Je crains de ne pouvoir satisfaire votre requête.",
            ["DialogueId"] = 80230236,
            ["GUID"] = "C8D91518",
            ["NextDialogue"] = 80230237,
            ["SpeakNpcId"] = 790076,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D91518",
            },
        [80230237] = {
            ["Content"] = "……",
            ["ContentFR"] = "...",
            ["DialogueId"] = 80230237,
            ["GUID"] = "C8D91542",
            ["NextDialogue"] = 80230238,
            ["SpeakNpcId"] = 790077,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D91542",
            },
        [80230238] = {
            ["Content"] = "大风九章关乎华胥万民生息，万民信赖是其运转的根基。不可因为零星错案动摇根基，因小失大。这是利弊取舍的一环。",
            ["ContentFR"] = "Les Neuf Chapitres de Dafeng soutiennent l’existence de tout Huaxu. La confiance du peuple est le socle de leur fonctionnement. On ne peut ébranler ce fondement pour quelques erreurs isolées. C’est une question de choix et de conséquences.",
            ["DialogueId"] = 80230238,
            ["GUID"] = "C8D9156C",
            ["NextDialogue"] = 80230239,
            ["SpeakNpcId"] = 790076,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D9156C",
            },
        [80230239] = {
            ["Content"] = "但我可以承诺的是，此事风波平息后，泽生阁会获得扶持。此外，我还能为你个人申请一笔补偿金，聊以慰藉。",
            ["ContentFR"] = "Ce que je peux toutefois vous promettre, c’est qu’une fois la tempête apaisée, la Pharmacie Zesheng recevra un soutien discret.",
            ["DialogueId"] = 80230239,
            ["GUID"] = "C8D91596",
            ["NextDialogue"] = 80230240,
            ["SpeakNpcId"] = 790076,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D91596",
            },
        [80230240] = {
            ["Content"] = "这些听起来似乎很好，可是姐姐……我不想要这样。",
            ["ContentFR"] = "Quant à vous, je peux faire en sorte qu’une compensation vous soit accordée, afin d’alléger votre peine.",
            ["DialogueId"] = 80230240,
            ["GUID"] = "C8D915C0",
            ["NextDialogue"] = 80230241,
            ["SpeakNpcId"] = 790077,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D915C0",
            },
        [80230241] = {
            ["Content"] = "要是没有救我的那位医师，我现在已经是黄土之下的一缕亡魂了。对死人来说，钱还能花到哪里去呢？",
            ["ContentFR"] = "Tout cela paraît raisonnable... mais ce n’est pas ce que je souhaite. Sans cette médecin, je serais déjà morte. À quoi l’argent peut-il bien servir aux défunts ?",
            ["DialogueId"] = 80230241,
            ["GUID"] = "C8D915EA",
            ["NextDialogue"] = 80230242,
            ["SpeakNpcId"] = 790077,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D915EA",
            },
        [80230242] = {
            ["Content"] = "同样的道理，对于救下我却失去了性命的那位医师，这些身外之物也没有意义了。我唯一能为她争的，只有生后的清白而已。",
            ["ContentFR"] = "Et pour celle qui m’a sauvée au prix de sa vie, ces biens matériels n’ont plus aucun sens. La seule chose que je puisse encore défendre, c’est sa pureté après la mort.",
            ["DialogueId"] = 80230242,
            ["GUID"] = "C8D91614",
            ["NextDialogue"] = 80230243,
            ["SpeakNpcId"] = 790077,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D91614",
            },
        [80230243] = {
            ["Content"] = "拿了这些钱，我或许能过上更好的生活，但是我的良心呢？它以后要是痛了起来，我再也找不到药方去治疗它了。",
            ["ContentFR"] = "Si j’accepte cet argent, ma vie sera peut-être plus aisée... mais qu’adviendra-t-il de ma conscience ? Si elle se met à me ronger, aucun remède ne pourra jamais la guérir.",
            ["DialogueId"] = 80230243,
            ["GUID"] = "C8D9163E",
            ["NextDialogue"] = 80230244,
            ["SpeakNpcId"] = 790077,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D9163E",
            },
        [80230244] = {
            ["Content"] = "姐姐，大风九章的运转，真的要以一个个人的冤屈被掩埋为代价吗？",
            ["ContentFR"] = "Dites-moi... le fonctionnement des Neuf Chapitres de Dafeng exige-t-il réellement que chaque injustice soit ensevelie l’une après l’autre ?",
            ["DialogueId"] = 80230244,
            ["GUID"] = "C8D91668",
            ["NextDialogue"] = 80230245,
            ["SpeakNpcId"] = 790077,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D91668",
            },
        [80230245] = {
            ["Content"] = "……你这性子和我年轻时倒有几分相似。那有些话，我也只说与你我二人听。",
            ["ContentFR"] = "... Votre tempérament me rappelle celui que j’avais autrefois. Il y a des choses que je ne dirai qu’à vous seule.",
            ["DialogueId"] = 80230245,
            ["GUID"] = "C8D91692",
            ["NextDialogue"] = 80230246,
            ["SpeakNpcId"] = 790076,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D91692",
            },
        [80230246] = {
            ["DialogueId"] = 80230246,
            ["GUID"] = "C8D916BC",
            ["NextDialogue"] = 80230247,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D916BC",
            },
        [80230247] = {
            ["Content"] = "止流少卿，未想到你三言两语就摆平了那少女，使她签下了放弃伸冤的契书。有什么诀窍呀？也教教我们吧！",
            ["ContentFR"] = "Chancelier Zhiliu ! Je ne m’attendais pas à ce que vous régliez cette affaire si aisément. En quelques mots, vous lui avez même fait signer l’acte de renonciation à sa plainte ! Quel est votre secret ? Apprenez-nous donc !",
            ["DialogueId"] = 80230247,
            ["GUID"] = "C8D916E6",
            ["NextDialogue"] = 80230248,
            ["SpeakNpcId"] = 790081,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D916E6",
            },
        [80230248] = {
            ["Content"] = "过誉了。我还未通过全部试炼，当不起这一声称呼。只是耐心为她分析了其中利弊而已。",
            ["ContentFR"] = "Vous me flattez. Je n’ai pas encore achevé toutes les épreuves et ne mérite pas un tel titre. Je me suis contentée de lui exposer les réalités.",
            ["DialogueId"] = 80230248,
            ["GUID"] = "C8D91710",
            ["NextDialogue"] = 80230249,
            ["SpeakNpcId"] = 790076,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D91710",
            },
        [80230249] = {
            ["Content"] = "若无其他要事，我先告退了。",
            ["ContentFR"] = "Si vous n’avez rien d’autre à me demander, je vais prendre congé.",
            ["DialogueId"] = 80230249,
            ["GUID"] = "C8D9173A",
            ["NextDialogue"] = 80230250,
            ["SpeakNpcId"] = 790076,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D9173A",
            },
        [80230250] = {
            ["DialogueId"] = 80230250,
            ["GUID"] = "C8D91764",
            ["NextDialogue"] = 80230251,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D91764",
            },
        [80230251] = {
            ["Content"] = "你们知道吗？听说那个止流啊，从前也受过大风九章的冤屈。",
            ["ContentFR"] = "Vous savez... j’ai entendu dire que Zhiliu avait elle aussi, jadis, subi une injustice de la part des Neuf Chapitres.",
            ["DialogueId"] = 80230251,
            ["GUID"] = "C8D9178E",
            ["NextDialogue"] = 80230252,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D9178E",
            },
        [80230252] = {
            ["Content"] = "曾经她也在执律阁下那个位置四处奔走，甚至是这附近居民茶余饭后的谈资呢。",
            ["ContentFR"] = "Elle se tenait là, exactement à la même place, implorant réparation... un sujet de commérages pour les habitants du quartier.",
            ["DialogueId"] = 80230252,
            ["GUID"] = "C8D917B8",
            ["NextDialogue"] = 80230253,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D917B8",
            },
        [80230253] = {
            ["Content"] = "没想到今天她能眼都不眨地摆平和曾经的自己一样的人。这就是成大事者吗？",
            ["ContentFR"] = "Et aujourd’hui, elle règle ce genre d’affaire sans même ciller. Est-ce cela, accomplir de grandes choses ?",
            ["DialogueId"] = 80230253,
            ["GUID"] = "C8D917E2",
            ["NextDialogue"] = 80230254,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D917E2",
            },
        [80230254] = {
            ["Content"] = "唉……恐怕她就是下一位龙渊上卿了，我们也羡慕不来，毕竟学不了她的心狠手辣。恐怕只有修罗心肠的人，才能站在那个位置吧。",
            ["ContentFR"] = "Hélas... elle sera sans doute le prochain Haut Chancelier de Longyuan. Il n’y a rien à envier — nous n’aurions jamais la dureté nécessaire. Seul quelqu’un capable de se dépouiller de toute compassion peut supporter un tel poids.",
            ["DialogueId"] = 80230254,
            ["GUID"] = "C8D9180C",
            ["NextDialogue"] = 80230255,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D9180C",
            },
        [80230255] = {
            ["Content"] = "呵呵……只有修罗心肠，才能治大国吗？",
            ["ContentFR"] = "Hm... Faut-il vraiment se dépouiller de toute compassion pour gouverner un grand État... ?",
            ["DialogueId"] = 80230255,
            ["GUID"] = "C8D91836",
            ["SpeakNpcId"] = 790076,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D91836",
            },
        [80230301] = {
            ["Content"] = "接下来便是最后一道试炼了，先提前恭贺你一声。迈过此关，你便能以龙渊上卿的头衔荣登执律阁巅。",
            ["ContentFR"] = "Voici venue la dernière épreuve. Permettez-moi de vous adresser mes félicitations par avance. Si vous franchissez ce seuil, vous gravirez le sommet du Pavillon de l’Arbitrage et porterez officiellement le titre de Haut Chancelier de Longyuan.",
            ["DialogueId"] = 80230301,
            ["GUID"] = "C8D91FC2",
            ["NextDialogue"] = 80230302,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/003/C8D91FC2",
            },
        [80230302] = {
            ["Content"] = "这最后一道试炼，其名为“问心”。",
            ["ContentFR"] = "Cette ultime épreuve se nomme : « Questionner le cœur ».",
            ["DialogueId"] = 80230302,
            ["GUID"] = "C8D91FEC",
            ["NextDialogue"] = 80230303,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/003/C8D91FEC",
            },
        [80230303] = {
            ["Content"] = "在太皓的神力照耀之下，你的过往心魔将如影照形，历历可见。",
            ["ContentFR"] = "Sous la lumière divine de Taihao, les démons de votre passé se manifesteront sans détour, aussi nettement qu’une ombre projetée par la lumière.",
            ["DialogueId"] = 80230303,
            ["GUID"] = "C8D92016",
            ["NextDialogue"] = 80230304,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/003/C8D92016",
            },
        [80230304] = {
            ["Content"] = "对于尔等大毅力者，必能斩断过往，踏过心中软弱，从而执起“承九鼎，济苍黎”之重任。",
            ["ContentFR"] = "Seuls ceux dotés d’une volonté véritable sauront trancher avec leur passé, piétiner la faiblesse de leur cœur et assumer la charge de « porter le poids du monde et sauver le peuple ».",
            ["DialogueId"] = 80230304,
            ["GUID"] = "C8D92040",
            ["NextDialogue"] = 80230305,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/003/C8D92040",
            },
        [80230305] = {
            ["Content"] = "止流，你可准备好了？",
            ["ContentFR"] = "Zhiliu. Êtes-vous prête ?",
            ["DialogueId"] = 80230305,
            ["GUID"] = "C8D9206A",
            ["NextDialogue"] = 80230306,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/003/C8D9206A",
            },
        [80230306] = {
            ["Content"] = "从很久之前，我就已明确此心志向，不会再随外物而动。",
            ["ContentFR"] = "Il y a bien longtemps que ma décision est prise. Rien d’extérieur ne fera plus vaciller mon cœur.",
            ["DialogueId"] = 80230306,
            ["GUID"] = "C8D92094",
            ["NextDialogue"] = 80230307,
            ["SpeakNpcId"] = 790076,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/003/C8D92094",
            },
        [80230307] = {
            ["Content"] = "很好。我没有看走眼。",
            ["ContentFR"] = "Bien. Je ne me suis pas trompée à votre sujet.",
            ["DialogueId"] = 80230307,
            ["GUID"] = "C8D920BE",
            ["NextDialogue"] = 80230308,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/003/C8D920BE",
            },
        [80230308] = {
            ["Content"] = "止流，甫一见面，我便看出你是那些人里最出类拔萃的一个苗子。",
            ["ContentFR"] = "Dès notre première rencontre, j’ai compris que vous étiez la plus prometteuse parmi eux.",
            ["DialogueId"] = 80230308,
            ["GUID"] = "C8D920E8",
            ["NextDialogue"] = 80230309,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/003/C8D920E8",
            },
        [80230309] = {
            ["Content"] = "那么试炼正式开始。无关人士便先清退了，我在执律阁外静候你的佳音。",
            ["ContentFR"] = "Que l’épreuve commence. Les personnes non concernées vont se retirer. Je vous attendrai à l’extérieur, dans l’attente de votre issue.",
            ["DialogueId"] = 80230309,
            ["GUID"] = "C8D92112",
            ["NextDialogue"] = 80230310,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/003/C8D92112",
            },
        [80230310] = {
            ["DialogueId"] = 80230310,
            ["GUID"] = "C8D9213C",
            ["NextDialogue"] = 80230311,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/003/C8D9213C",
            },
        [80230311] = {
            ["Content"] = "——！",
            ["ContentFR"] = "— !",
            ["DialogueId"] = 80230311,
            ["GUID"] = "C8D92166",
            ["NextDialogue"] = 80230312,
            ["SpeakNpcId"] = 790076,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/003/C8D92166",
            },
        [80230312] = {
            ["Content"] = "……",
            ["ContentFR"] = "...",
            ["DialogueId"] = 80230312,
            ["GUID"] = "C8D92190",
            ["NextDialogue"] = 80230313,
            ["SpeakNpcId"] = 790076,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/003/C8D92190",
            },
        [80230313] = {
            ["DialogueId"] = 80230313,
            ["GUID"] = "C8D921BA",
            ["NextDialogue"] = 80230314,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/003/C8D921BA",
            },
        [80230314] = {
            ["Content"] = "呜……呜呜……为什么……",
            ["ContentFR"] = "... Pourquoi... ?",
            ["DialogueId"] = 80230314,
            ["GUID"] = "C8D921E4",
            ["NextDialogue"] = 80230315,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/003/C8D921E4",
            },
        [80230315] = {
            ["Content"] = "（果然……不出所料。）",
            ["ContentFR"] = "Comme prévu...",
            ["DialogueId"] = 80230315,
            ["GUID"] = "C8D9220E",
            ["NextDialogue"] = 80230316,
            ["SpeakNpcId"] = 790076,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/003/C8D9220E",
            },
        [80230316] = {
            ["Content"] = "你已经忘记了吗……<H>我们</>那些夜不能寐的晚上？",
            ["ContentFR"] = "As-tu déjà oublié... les nuits où <H>nous</> ne parvenions pas à trouver le sommeil ?",
            ["DialogueId"] = 80230316,
            ["GUID"] = "C8D92238",
            ["NextDialogue"] = 80230317,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/003/C8D92238",
            },
        [80230317] = {
            ["Content"] = "你忘记了吗……在山洞里饥饿如蛆附骨的感觉，身体上下的每一处，每一根发丝都在叫嚣着好饿、好饿……",
            ["ContentFR"] = "As-tu oublié... la faim dans cette grotte, si vorace qu’elle rongeait jusqu’à nos os, chaque parcelle de notre corps, chaque mèche de cheveux hurlant : « j’ai faim... j’ai faim... »",
            ["DialogueId"] = 80230317,
            ["GUID"] = "C8D92262",
            ["NextDialogue"] = 80230318,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/003/C8D92262",
            },
        [80230318] = {
            ["Content"] = "你忘记了吗……那个歹徒，他满是茧子的手紧紧钳住<H>我们</>脖子的那一刻，无论我们怎么挣扎，怎么奋力踢腿，都阻止不了分毫……",
            ["ContentFR"] = "As-tu oublié... cet instant où la main calleuse de ce bandit s’est refermée autour de <H>notre</> cou ? Peu importaient nos gestes désespérés, nos coups de pieds, rien ne pouvait l’arrêter...",
            ["DialogueId"] = 80230318,
            ["GUID"] = "C8D9228C",
            ["NextDialogue"] = 80230319,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/003/C8D9228C",
            },
        [80230319] = {
            ["Content"] = "空气逐渐消失，一切闪着光的画面都变得稀薄，冰冷的死亡即将把我们拽入雾中……",
            ["ContentFR"] = "L’air disparaissait peu à peu... le monde se faisait flou... et la mort glaciale nous entraînait vers la brume...",
            ["DialogueId"] = 80230319,
            ["GUID"] = "C8D922B6",
            ["NextDialogue"] = 80230320,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/003/C8D922B6",
            },
        [80230320] = {
            ["Content"] = "以及……你忘了吗，<H>他</>冲上来，撞开歹徒，让空气一下子全部涌回来的那个时刻。",
            ["ContentFR"] = "Et puis... as-tu oublié ce moment où <H>il</> a surgi, a percuté le bandit, et où l’air est revenu d’un seul coup dans nos poumons ?",
            ["DialogueId"] = 80230320,
            ["GUID"] = "C8D922E0",
            ["NextDialogue"] = 80230321,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/003/C8D922E0",
            },
        [80230321] = {
            ["Content"] = "他曾经那样对你，不计回报地去救你，却只落得了身死名灭的下场。",
            ["ContentFR"] = "Il t’a sauvée sans rien attendre en retour... et n’a récolté que la mort et l’oubli.",
            ["DialogueId"] = 80230321,
            ["GUID"] = "C8D9230A",
            ["NextDialogue"] = 80230322,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/003/C8D9230A",
            },
        [80230322] = {
            ["Content"] = "现在，你要背叛他，背叛我们曾经发下的誓言，投向<H>他们</>那边吗？",
            ["ContentFR"] = "Et maintenant... tu serais prête à le trahir, à trahir le serment que nous avions fait, pour rejoindre <H>leur</> camp ?",
            ["DialogueId"] = 80230322,
            ["GUID"] = "C8D92334",
            ["NextDialogue"] = 80230323,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/003/C8D92334",
            },
        [80230323] = {
            ["Content"] = "…………",
            ["ContentFR"] = "...",
            ["DialogueId"] = 80230323,
            ["GUID"] = "C8D9235E",
            ["NextDialogue"] = 80230324,
            ["SpeakNpcId"] = 790076,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/003/C8D9235E",
            },
        [80230324] = {
            ["Content"] = "（是的……是的……你不需要去铭记。因为遗忘明显更加甜美。）",
            ["ContentFR"] = "Oui... oui... tu n’as pas besoin de te souvenir. L’oubli est bien plus doux.",
            ["DialogueId"] = 80230324,
            ["GUID"] = "C8D92388",
            ["NextDialogue"] = 80230325,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/003/C8D92388",
            },
        [80230325] = {
            ["Content"] = "（你即将成为万人之上的止流大人！这些过去的纷扰无法撼动你，和你即将获得的地位相比，他们显得那么不起眼，那么无足轻重，甚至不如一根轻飘飘的鸿毛。）",
            ["ContentFR"] = "Tu es sur le point de t’élever au-dessus de tous. Les tourments du passé ne peuvent plus t’atteindre. Comparés à la position qui t’attend, ils ne sont rien — pas même le poids d’une plume.",
            ["DialogueId"] = 80230325,
            ["GUID"] = "C8D923B2",
            ["NextDialogue"] = 80230326,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/003/C8D923B2",
            },
        [80230326] = {
            ["Content"] = "（倒不如说，铭记只是软弱的证明。软弱者用无谓的良心将自己束缚住，于是他们屈服了。他们的膝盖承受不住大地的重力，永远匍匐在尘埃之中。）",
            ["ContentFR"] = "Se souvenir n’est qu’une preuve de faiblesse. Les faibles se laissent enchaîner par une conscience inutile, et finissent par plier. Leurs genoux ne supportent pas le poids de la terre et restent à jamais prosternés dans la poussière.",
            ["DialogueId"] = 80230326,
            ["GUID"] = "C8D923DC",
            ["NextDialogue"] = 80230327,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/003/C8D923DC",
            },
        [80230327] = {
            ["Content"] = "（那些软弱者沉浸在自己的梦中，同时世界毫无变化。而你，你显然更加坚毅，更加勇敢——你懂得取舍，于是你能成大器。有几人能有成为修罗的大毅力呢？）",
            ["ContentFR"] = "Ils se noient dans leurs illusions pendant que le monde demeure immobile. Mais toi... tu es plus ferme, plus courageuse. Tu comprends le prix des choix. C’est pour cela que tu es destinée à de grandes choses. Combien sont capables de se dépouiller de toute compassion ?",
            ["DialogueId"] = 80230327,
            ["GUID"] = "C8D92406",
            ["NextDialogue"] = 80230328,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/003/C8D92406",
            },
        [80230328] = {
            ["Content"] = "（不要听他的！！止流，你与那些冷眼旁观的人有何区别？）",
            ["ContentFR"] = "Ne l’écoute pas ! Zhiliu — en quoi serais-tu différente de ceux qui détournent le regard ?",
            ["DialogueId"] = 80230328,
            ["GUID"] = "C8D92430",
            ["NextDialogue"] = 80230329,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/003/C8D92430",
            },
        [80230329] = {
            ["Content"] = "（止流，你想好了，你也要成为他们的帮凶吗？！）",
            ["ContentFR"] = "Zhiliu, y as-tu réfléchi ? Veux-tu vraiment devenir leur complice ?!",
            ["DialogueId"] = 80230329,
            ["GUID"] = "C8D9245A",
            ["NextDialogue"] = 80230330,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/003/C8D9245A",
            },
        [80230330] = {
            ["Content"] = "（若是踏出这一步，你还是昨日之你吗？）",
            ["ContentFR"] = "Si tu fais ce pas... seras-tu encore celle que tu étais hier ?",
            ["DialogueId"] = 80230330,
            ["GUID"] = "C8D92484",
            ["NextDialogue"] = 80230331,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/003/C8D92484",
            },
        [80230331] = {
            ["DialogueId"] = 80230331,
            ["GUID"] = "C8D924AE",
            ["NextDialogue"] = 80230332,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/003/C8D924AE",
            },
        [80230332] = {
            ["Content"] = "救命，谁来救救我……这里好黑……我好害怕……我，我不能待在这个地方！",
            ["ContentFR"] = "Au secours... Quelqu’un... sauvez-moi... Il fait si noir... j’ai peur... je... je ne peux pas rester ici... !",
            ["DialogueId"] = 80230332,
            ["GUID"] = "C8D924D8",
            ["NextDialogue"] = 80230333,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/003/C8D924D8",
            },
        [80230333] = {
            ["DialogueId"] = 80230333,
            ["GUID"] = "C8D92502",
            ["NextDialogue"] = 80230334,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/003/C8D92502",
            },
        [80230334] = {
            ["Content"] = "你知道吗……自从几年前有意识地去控制后，怕黑便不再能影响我的一举一动了。",
            ["ContentFR"] = "Sais-tu... qu’il y a des années, j’ai appris à maîtriser ma peur de l’obscurité ? Depuis, elle n’entrave plus mes gestes.",
            ["DialogueId"] = 80230334,
            ["GUID"] = "C8D9252C",
            ["NextDialogue"] = 80230335,
            ["SpeakNpcId"] = 790076,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/003/C8D9252C",
            },
        [80230335] = {
            ["Content"] = "当我意识到无论恐惧抑或痛苦都于事无补之时，我便舍弃了这些情绪。",
            ["ContentFR"] = "Quand j’ai compris que ni la peur ni la douleur ne pouvaient changer quoi que ce soit, je les ai abandonnées.",
            ["DialogueId"] = 80230335,
            ["GUID"] = "C8D92556",
            ["NextDialogue"] = 80230336,
            ["SpeakNpcId"] = 790076,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/003/C8D92556",
            },
        [80230336] = {
            ["Content"] = "因为我突然发现，人拥有的时间过于短暂——短暂到无法偿换自己欲求之物，这一生便匆匆结束了。",
            ["ContentFR"] = "Car j’ai soudain réalisé que le temps accordé à l’existence humaine est bien trop court — trop court pour obtenir ce que l’on désire réellement avant que tout ne s’achève.",
            ["DialogueId"] = 80230336,
            ["GUID"] = "C8D92580",
            ["NextDialogue"] = 80230337,
            ["SpeakNpcId"] = 790076,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/003/C8D92580",
            },
        [80230337] = {
            ["Content"] = "从那一天起，我便下定决心。这世上的任何事情，无论是良心还是过往，都不再能绊住我的脚步。因为我还有要去完成的事情。",
            ["ContentFR"] = "À partir de ce jour, j’ai pris ma décision. Ni ma conscience, ni mon passé ne freineront plus mes pas. Il me reste quelque chose à accomplir.",
            ["DialogueId"] = 80230337,
            ["GUID"] = "C8D925AA",
            ["NextDialogue"] = 80230338,
            ["SpeakNpcId"] = 790076,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/003/C8D925AA",
            },
        [80230338] = {
            ["Content"] = "我很抱歉只能让你待在黑暗之中……但是不会有谁来救你了，你只能凭自己的力量走出这里。",
            ["ContentFR"] = "Je suis désolée de te laisser ici, dans l’obscurité... Mais personne ne viendra te sauver. Tu devras trouver seule le chemin pour en sortir.",
            ["DialogueId"] = 80230338,
            ["GUID"] = "C8D925D4",
            ["NextDialogue"] = 80230339,
            ["SpeakNpcId"] = 790076,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/003/C8D925D4",
            },
        [80230339] = {
            ["Content"] = "我言尽于此。",
            ["ContentFR"] = "Je n’ai plus rien à ajouter.",
            ["DialogueId"] = 80230339,
            ["GUID"] = "C8D925FE",
            ["NextDialogue"] = 80230340,
            ["SpeakNpcId"] = 790076,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/003/C8D925FE",
            },
        [80230340] = {
            ["DialogueId"] = 80230340,
            ["GUID"] = "C8D92628",
            ["NextDialogue"] = 80230341,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/003/C8D92628",
            },
        [80230341] = {
            ["Content"] = "传吉讯——",
            ["ContentFR"] = "Proclamation solennelle —",
            ["DialogueId"] = 80230341,
            ["GUID"] = "C8D92652",
            ["NextDialogue"] = 80230342,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/003/C8D92652",
            },
        [80230342] = {
            ["Content"] = "皓京人士止流，现荣升为龙渊上卿——愿其承九鼎，济苍黎，不负太皓之望，传大风于万代——",
            ["ContentFR"] = "Zhiliu, citoyenne de Haojing, est élevée au rang de Haut Chancelier de Longyuan — qu’elle porte le poids du monde, soutienne le peuple, ne trahisse pas l’espérance de Taihao, et fasse perdurer le souffle de Dafeng à travers les âges —",
            ["DialogueId"] = 80230342,
            ["GUID"] = "C8D9267C",
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/003/C8D9267C",
            },
        [80230401] = {
            ["Content"] = "龙渊上卿每四载选拔一任，同时在任者寥寥无几，关于其选拔过程的记载往往残缺不全。如今竟从亲历者口中听到这么多细节，妙哉，妙哉！",
            ["ContentFR"] = "Le Haut Chancelier de Longyuan n’est désigné qu’une fois tous les quatre ans. Ils sont peu nombreux à avoir occupé ce poste, et les récits de leur sélection sont souvent lacunaires. Pouvoir aujourd’hui entendre autant de détails de la bouche même de celle qui l’a traversée... quelle rare et délicieuse occasion !",
            ["DialogueId"] = 80230401,
            ["GUID"] = "C8D9302A",
            ["NextDialogue"] = 80230402,
            ["SpeakNpcId"] = 790079,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/004/C8D9302A",
            },
        [80230402] = {
            ["Content"] = "能旁观这段活生生的历史，我的心事又了了一桩。",
            ["ContentFR"] = "Assister à cette page d’histoire encore vivante apaise l’une de mes plus anciennes curiosités.",
            ["DialogueId"] = 80230402,
            ["GUID"] = "C8D93054",
            ["NextDialogue"] = 80230403,
            ["SpeakNpcId"] = 790079,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/004/C8D93054",
            },
        [80230403] = {
            ["Content"] = "……要是这些往事能让你消停片刻，少做些节外生枝的事情，那也不枉我费这么多口舌。",
            ["ContentFR"] = "... Si ressasser ces souvenirs suffit à vous calmer un moment et à vous éviter de semer de nouveaux troubles, alors je n’aurai pas parlé en vain.",
            ["DialogueId"] = 80230403,
            ["GUID"] = "C8D9307E",
            ["NextDialogue"] = 80230404,
            ["SpeakNpcId"] = 790076,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/004/C8D9307E",
            },
        [80230404] = {
            ["Content"] = "秦虬，我提醒你一句。{nickname}是我的座上宾，我不希望{性别：他|她}出什么意外。你行事最好有些分寸。",
            ["ContentFR"] = "Qin Qiu, je vous préviens d’une chose. {nickname} est mon {性别:invité|invitée} d’honneur. Je ne tolérerai aucun incident {性别:le|la} concernant. Agissez avec retenue.",
            ["DialogueId"] = 80230404,
            ["GUID"] = "C8D930A8",
            ["NextDialogue"] = 80230405,
            ["SpeakNpcId"] = 790076,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/004/C8D930A8",
            },
        [80230405] = {
            ["Content"] = "哈哈！你从冰湖城不远千里请回来的那位小友确实有趣，使我忍不住捉弄一番。",
            ["ContentFR"] = "Ha ha ! {性别:Le jeune ami|La jeune amie} que vous avez ramené de Givrelac, après un si long voyage, est effectivement fort {性别:divertissant|divertissante}. Je n’ai fait que {性别:le|la} taquiner un peu.",
            ["DialogueId"] = 80230405,
            ["GUID"] = "C8D930D2",
            ["NextDialogue"] = 80230406,
            ["SpeakNpcId"] = 790079,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/004/C8D930D2",
            },
        [80230406] = {
            ["Content"] = "不过，止流掌柜对某人如此上心，倒是难得一见的光景。",
            ["ContentFR"] = "Cela dit... vous voir accorder tant d’attention à quelqu’un est un spectacle peu commun.",
            ["DialogueId"] = 80230406,
            ["GUID"] = "C8D930FC",
            ["NextDialogue"] = 80230407,
            ["SpeakNpcId"] = 790079,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/004/C8D930FC",
            },
        [80230407] = {
            ["Content"] = "这次计划的实情，你真不打算对{性别：他|她}托出一二吗？",
            ["ContentFR"] = "À propos de votre « grand dessein »... vous n’avez vraiment pas l’intention de lui en dire ne serait-ce qu’un mot ?",
            ["DialogueId"] = 80230407,
            ["GUID"] = "C8D93126",
            ["NextDialogue"] = 80230408,
            ["SpeakNpcId"] = 790079,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/004/C8D93126",
            },
        [80230408] = {
            ["Content"] = "……我自有我的打算，劝你不要有什么额外心思。",
            ["ContentFR"] = "... J’ai mes propres arrangements. Je vous conseille de ne pas nourrir d’idées superflues.",
            ["DialogueId"] = 80230408,
            ["GUID"] = "C8D93150",
            ["NextDialogue"] = 80230409,
            ["SpeakNpcId"] = 790076,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/004/C8D93150",
            },
        [80230409] = {
            ["Content"] = "世人皆知我虬某阴险狡诈，无孔不钻，而你止流掌柜行事光明磊落，手段高明。",
            ["ContentFR"] = "Tout le monde sait que je suis réputé pour ma duplicité, pour mon goût des manœuvres et des chemins détournés. Vous, en revanche, agissez ouvertement, avec une maîtrise admirable.",
            ["DialogueId"] = 80230409,
            ["GUID"] = "C8D9317A",
            ["NextDialogue"] = 80230410,
            ["SpeakNpcId"] = 790079,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/004/C8D9317A",
            },
        [80230410] = {
            ["Content"] = "殊不知论心狠手辣，我可连你的皮毛都够不上。",
            ["ContentFR"] = "Mais lorsqu’il s’agit de véritable dureté... je suis loin d’égaler ne serait-ce que votre ombre.",
            ["DialogueId"] = 80230410,
            ["GUID"] = "C8D931A4",
            ["NextDialogue"] = 80230411,
            ["SpeakNpcId"] = 790079,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/004/C8D931A4",
            },
        [80230411] = {
            ["Content"] = "可我看你不是很喜欢那位小友吗？为了所谓的大计，把自己逼到众叛亲离的那一天，这对你而言真的值得吗？",
            ["ContentFR"] = "Et pourtant, ne tenez-vous pas {性别:ce jeune ami|cette jeune amie} en estime ? Si votre plan venait à être découvert, le jour où tous vous tourneront le dos — y compris {性别:lui|elle} — pensez-vous vraiment que le prix en vaudra la peine ?",
            ["DialogueId"] = 80230411,
            ["GUID"] = "C8D931CE",
            ["NextDialogue"] = 80230412,
            ["SpeakNpcId"] = 790079,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/004/C8D931CE",
            },
        [80230412] = {
            ["Content"] = "秦虬，勿对自己不了解的事情妄加评论，我以为这是为人的基本。",
            ["ContentFR"] = "Qin Qiu, évitez de juger ce que vous ne comprenez pas. J’ose croire que c’est le minimum de décence.",
            ["DialogueId"] = 80230412,
            ["GUID"] = "C8D931F8",
            ["NextDialogue"] = 80230413,
            ["SpeakNpcId"] = 790076,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/004/C8D931F8",
            },
        [80230413] = {
            ["Content"] = "你我不过暂且利益一致，各取所需。无论是你所言的“大计”，抑或是我的目的，你都不了解分毫。",
            ["ContentFR"] = "Nos intérêts ne font que coïncider provisoirement. Chacun obtient ce qu’il cherche, rien de plus. Quant à ce « grand dessein » que vous évoquez, vous n’en connaissez pas la moindre parcelle.",
            ["DialogueId"] = 80230413,
            ["GUID"] = "C8D93222",
            ["NextDialogue"] = 80230414,
            ["SpeakNpcId"] = 790076,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/004/C8D93222",
            },
        [80230414] = {
            ["Content"] = "怎么生气了？这么开不起玩笑，消消气消消气。",
            ["ContentFR"] = "Oh ? Vous aurais-je mise en colère ? Allons, allons... inutile de vous emporter.",
            ["DialogueId"] = 80230414,
            ["GUID"] = "C8D9324C",
            ["NextDialogue"] = 80230415,
            ["SpeakNpcId"] = 790079,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/004/C8D9324C",
            },
        [80230415] = {
            ["Content"] = "止流大当家——您在这里吗？",
            ["ContentFR"] = "Patronne Zhiliu — vous êtes là ?",
            ["DialogueId"] = 80230415,
            ["GUID"] = "C8D93276",
            ["NextDialogue"] = 80230416,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/004/C8D93276",
            },
        [80230416] = {
            ["Content"] = "呵呵，你的助手来找你了。看来比起在这里讨人嫌，我也该告辞了。",
            ["ContentFR"] = "Héhé... votre assistante vous cherche. Il est sans doute temps pour moi de prendre congé, avant de devenir vraiment importun.",
            ["DialogueId"] = 80230416,
            ["GUID"] = "C8D932A0",
            ["NextDialogue"] = 80230417,
            ["SpeakNpcId"] = 790079,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/004/C8D932A0",
            },
        [80230417] = {
            ["Content"] = "您这龙渊上卿大忙人，就不用在我这个见不得光的闲人身上浪费时间了。",
            ["ContentFR"] = "Une personne aussi occupée que le Haut Chancelier de Longyuan n’a guère de temps à perdre avec un homme de l’ombre comme moi.",
            ["DialogueId"] = 80230417,
            ["GUID"] = "C8D932CA",
            ["NextDialogue"] = 80230418,
            ["SpeakNpcId"] = 790079,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/004/C8D932CA",
            },
        [80230418] = {
            ["Content"] = "那便不送了。",
            ["ContentFR"] = "Alors, je ne vous raccompagnerai pas.",
            ["DialogueId"] = 80230418,
            ["GUID"] = "C8D932F4",
            ["NextDialogue"] = 80230419,
            ["SpeakNpcId"] = 790076,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/004/C8D932F4",
            },
        [80230419] = {
            ["DialogueId"] = 80230419,
            ["GUID"] = "C8D9331E",
            ["NextDialogue"] = 80230420,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/004/C8D9331E",
            },
        [80230420] = {
            ["Content"] = "止流大当家，百年春那里有些举棋不定的事，需要您去拿一下主意。",
            ["ContentFR"] = "Patronne Zhiliu, il y a du nouveau à Éternel Printemps. Ils hésitent sur une décision et souhaitent votre avis.",
            ["DialogueId"] = 80230420,
            ["GUID"] = "C8D93348",
            ["NextDialogue"] = 80230421,
            ["SpeakNpcId"] = 790077,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/004/C8D93348",
            },
        [80230421] = {
            ["Content"] = "好。",
            ["ContentFR"] = "Très bien.",
            ["DialogueId"] = 80230421,
            ["GUID"] = "C8D93372",
            ["NextDialogue"] = 80230422,
            ["SpeakNpcId"] = 790076,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/004/C8D93372",
            },
        [80230422] = {
            ["Content"] = "大当家，您看起来好像有点累了……？",
            ["ContentFR"] = "Vous semblez un peu fatiguée... Tout va bien ?",
            ["DialogueId"] = 80230422,
            ["GUID"] = "C8D9339C",
            ["NextDialogue"] = 80230423,
            ["SpeakNpcId"] = 790077,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/004/C8D9339C",
            },
        [80230423] = {
            ["Content"] = "……呵呵，没什么大碍。秦虬还是如以往一般问东问西，为了应付他，我不得已说了太多话。",
            ["ContentFR"] = "... Hé hé, rien de sérieux. Qin Qiu est resté fidèle à lui-même, à poser mille questions inutiles. Lui répondre m’a simplement demandé plus de paroles que prévu.",
            ["DialogueId"] = 80230423,
            ["GUID"] = "C8D933C6",
            ["NextDialogue"] = 80230424,
            ["SpeakNpcId"] = 790076,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/004/C8D933C6",
            },
        [80230424] = {
            ["Content"] = "不过，倒是聊到了你我在执律阁下相识的过往。没想到一转眼也是数年过去了。",
            ["ContentFR"] = "Nous avons évoqué aussi la façon dont toi et moi nous sommes rencontrées, autrefois, sous le Pavillon de l’Arbitrage. Dire que tant d’années se sont écoulées...",
            ["DialogueId"] = 80230424,
            ["GUID"] = "C8D933F0",
            ["NextDialogue"] = 80230425,
            ["SpeakNpcId"] = 790076,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/004/C8D933F0",
            },
        [80230425] = {
            ["Content"] = "哇，你们竟然聊到了那么久远的往事！",
            ["ContentFR"] = "Vraiment ? Vous êtes remontés si loin dans le passé ?",
            ["DialogueId"] = 80230425,
            ["GUID"] = "C8D9341A",
            ["NextDialogue"] = 80230426,
            ["SpeakNpcId"] = 790077,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/004/C8D9341A",
            },
        [80230426] = {
            ["Content"] = "那时候为了给救我的医师伸冤，我在执律阁底下站了那么多天，看够了别人的冷眼，其实已经不抱什么希望了。",
            ["ContentFR"] = "À l’époque, lorsque je tentais de laver le nom de la médecin qui m’avait sauvée, je suis restée tant de jours sous le Pavillon, à essuyer l’indifférence et les regards froids... qu’au fond, je n’espérais déjà plus grand-chose.",
            ["DialogueId"] = 80230426,
            ["GUID"] = "C8D93444",
            ["NextDialogue"] = 80230427,
            ["SpeakNpcId"] = 790077,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/004/C8D93444",
            },
        [80230427] = {
            ["Content"] = "您来劝说我时，我虽然勉强反驳了几句，但心中已经生出恐怕只能到这里为止了的念头。",
            ["ContentFR"] = "Quand vous êtes venue me parler, j’ai bien essayé de protester encore un peu, mais au fond de moi, je savais que tout s’arrêterait là.",
            ["DialogueId"] = 80230427,
            ["GUID"] = "C8D9346E",
            ["NextDialogue"] = 80230428,
            ["SpeakNpcId"] = 790077,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/004/C8D9346E",
            },
        [80230428] = {
            ["Content"] = "却没想到您当时会对我说……",
            ["ContentFR"] = "Je n’aurais jamais imaginé que vous me diriez alors...",
            ["DialogueId"] = 80230428,
            ["GUID"] = "C8D93498",
            ["NextDialogue"] = 80230429,
            ["SpeakNpcId"] = 790077,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/004/C8D93498",
            },
        [80230429] = {
            ["Content"] = "我以无穷藏派秘法遮蔽了我们的声音。接下来的这些话，包括现在的这份无力感，你都必须牢牢铭记，然后再也不和旁人提起。",
            ["ContentFR"] = "J’ai utilisé une technique secrète de la Secte de l’Insondable Trésor pour dissimuler nos voix. Ce que je vais te dire — ainsi que ce sentiment d’impuissance que tu ressens aujourd’hui — tu devras t’en souvenir, et n’en parler à personne.",
            ["DialogueId"] = 80230429,
            ["GUID"] = "C8D934C2",
            ["NextDialogue"] = 80230430,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/004/C8D934C2",
            },
        [80230430] = {
            ["Content"] = "我曾经与你一样，为了清白之人的冤屈，在这执律阁下四处奔走。很快，我意识到这一行为无异于以卵击石。",
            ["ContentFR"] = "Moi aussi, autrefois, je me suis tenue sous le Pavillon de l’Arbitrage, à courir partout pour défendre l’innocence d’autrui. Très vite, j’ai compris que c’était comme briser un rocher à coups d’œuf.",
            ["DialogueId"] = 80230430,
            ["GUID"] = "C8D934EC",
            ["NextDialogue"] = 80230431,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/004/C8D934EC",
            },
        [80230431] = {
            ["Content"] = "蚍蜉之力，如何撼树？大风九章是一整个庞大的不以个人意志为转移的体系。",
            ["ContentFR"] = "Comment la force d’un insecte pourrait-elle ébranler un arbre ? Les Neuf Chapitres de Dafeng forment un système immense, insensible à la volonté d’un individu.",
            ["DialogueId"] = 80230431,
            ["GUID"] = "C8D93516",
            ["NextDialogue"] = 80230432,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/004/C8D93516",
            },
        [80230432] = {
            ["Content"] = "现在这样做，除了让你的良心好受一点，此外毫无作用。到了最后，世界照常运转，不会产生丝毫变化。而你会在日复一日中背离当初的执着。",
            ["ContentFR"] = "À ce stade, tes efforts ne font qu’apaiser ta conscience. Le monde continuera de tourner, inchangé, et jour après jour, tu t’éloigneras de la résolution qui t’animait.",
            ["DialogueId"] = 80230432,
            ["GUID"] = "C8D93540",
            ["NextDialogue"] = 80230433,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/004/C8D93540",
            },
        [80230433] = {
            ["Content"] = "所以——你现在需要暂时妥协，但我可以承诺你一件事。",
            ["ContentFR"] = "C’est pourquoi — tu dois, pour l’instant, accepter de céder. Mais je peux te faire une promesse.",
            ["DialogueId"] = 80230433,
            ["GUID"] = "C8D9356A",
            ["NextDialogue"] = 80230434,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/004/C8D9356A",
            },
        [80230434] = {
            ["Content"] = "大风九章宣告终结的一天将会来临。我会不惜代价使这错置颠倒的一切重新归位……你愿意相信我吗？",
            ["ContentFR"] = "Le jour viendra où les Neuf Chapitres de Dafeng prendront fin. Quel qu’en soit le prix, je remettrai ce monde inversé sur ses rails... Peux-tu me faire confiance ?",
            ["DialogueId"] = 80230434,
            ["GUID"] = "C8D93594",
            ["NextDialogue"] = 80230435,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/004/C8D93594",
            },
        [80230435] = {
            ["DialogueId"] = 80230435,
            ["GUID"] = "C8D935BE",
            ["NextDialogue"] = 80230436,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/004/C8D935BE",
            },
        [80230436] = {
            ["Content"] = "时间过得真快，没想到您当年对我许下的承诺，眼看着就要实现了……不过大当家，您最近疲于奔波，面容都憔悴了许多，还是要以自己的身体为重啊！",
            ["ContentFR"] = "Le temps passe si vite... Dire que la promesse que vous m’avez faite autrefois est sur le point de se réaliser... Mais Patronne, vous avez tant couru ces derniers temps. Votre visage est bien plus marqué qu’avant... Prenez soin de vous.",
            ["DialogueId"] = 80230436,
            ["GUID"] = "C8D935E8",
            ["NextDialogue"] = 80230437,
            ["SpeakNpcId"] = 790077,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/004/C8D935E8",
            },
        [80230437] = {
            ["Content"] = "放心，我心中有数。",
            ["ContentFR"] = "Rassure-toi. Je sais ce que je fais.",
            ["DialogueId"] = 80230437,
            ["GUID"] = "C8D93612",
            ["NextDialogue"] = 80230438,
            ["SpeakNpcId"] = 790076,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/004/C8D93612",
            },
        [80230438] = {
            ["Content"] = "大当家，你知道吗？有很多人怕你，惧你，在背后腹诽于你。",
            ["ContentFR"] = "Vous savez, beaucoup de gens vous craignent. Ils murmurent sur votre passage.",
            ["DialogueId"] = 80230438,
            ["GUID"] = "C8D9363C",
            ["NextDialogue"] = 80230439,
            ["SpeakNpcId"] = 790077,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/004/C8D9363C",
            },
        [80230439] = {
            ["Content"] = "那些人说你铁石心肠，行事如同修罗，只会做做表面的慈善工夫，但只有我知道……您是什么样的人。",
            ["ContentFR"] = "Ils disent que vous avez un cœur de pierre, que vous agissez comme un démon, que votre bienveillance n’est qu’une façade... Mais moi, je sais qui vous êtes réellement.",
            ["DialogueId"] = 80230439,
            ["GUID"] = "C8D93666",
            ["NextDialogue"] = 80230440,
            ["SpeakNpcId"] = 790077,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/004/C8D93666",
            },
        [80230440] = {
            ["Content"] = "我非常佩服您的那份决心！跟在您身边越久，我越感谢，那一天遇到的是您。",
            ["ContentFR"] = "J’admire profondément votre détermination. Plus je reste à vos côtés, plus je remercie le destin que ce soit vous que j’aie rencontrée ce jour-là.",
            ["DialogueId"] = 80230440,
            ["GUID"] = "C8D93690",
            ["NextDialogue"] = 80230441,
            ["SpeakNpcId"] = 790077,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/004/C8D93690",
            },
        [80230441] = {
            ["Content"] = "呵呵……怎么突然说这么多，与其有逞这些口舌之快的功夫，不如再多做点实事。",
            ["ContentFR"] = "Hé hé... Pourquoi tant de paroles soudainement ? Si tu veux me remercier, attends que l’affaire d’Éternel Printemps soit réglée.",
            ["DialogueId"] = 80230441,
            ["GUID"] = "C8D936BA",
            ["NextDialogue"] = 80230442,
            ["SpeakNpcId"] = 790076,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/004/C8D936BA",
            },
        [80230442] = {
            ["Content"] = "我知道啦，大当家——",
            ["ContentFR"] = "Bien compris, Patronne Zhiliu —",
            ["DialogueId"] = 80230442,
            ["GUID"] = "C8D936E4",
            ["SpeakNpcId"] = 790077,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/004/C8D936E4",
            },
        [80240101] = {
            ["Content"] = "小苏？在这做什么呢。",
            ["ContentFR"] = "Petite Su ? Qu’est-ce que tu fabriques ici ?",
            ["DialogueId"] = 80240101,
            ["GUID"] = "C8DF6792",
            ["NextDialogue"] = 80240102,
            ["SpeakNpcId"] = 790083,
            ["VoiceName"] = "790082.0",
            },
        [80240102] = {
            ["Content"] = "好不容易天气放晴了，我晒点东西。",
            ["ContentFR"] = "Le ciel s’est enfin dégagé, alors j’en profite pour faire sécher quelques affaires.",
            ["DialogueId"] = 80240102,
            ["GUID"] = "C8DF67BC",
            ["NextDialogue"] = 80240103,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/001/C8DF67BC",
            },
        [80240103] = {
            ["Content"] = "好哇，唐叔！你又不带拐杖，跟你说了好几次，你的腿才好些呢，不能受太多的力。你不是刚换完拐杖吗，这个款式也不喜欢？",
            ["ContentFR"] = "Hé, Oncle Tang ! Tu es encore sorti sans ta canne ? Je te l’ai pourtant dit plusieurs fois : ta jambe commence à peine à guérir, tu ne dois pas trop la solliciter. Et tu n’en as pas changé récemment ? Ce modèle ne te plaît pas non plus ?",
            ["DialogueId"] = 80240103,
            ["GUID"] = "C8DF67E6",
            ["NextDialogue"] = 80240104,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/001/C8DF67E6",
            },
        [80240104] = {
            ["Content"] = "这拐杖可是小苏亲自给我做的，唐叔不舍得用啊。",
            ["ContentFR"] = "Cette canne, c’est toi qui me l’as fabriquée. Je n’ai pas le cœur à l’abîmer.",
            ["DialogueId"] = 80240104,
            ["GUID"] = "C8DF6810",
            ["NextDialogue"] = 80240105,
            ["SpeakNpcId"] = 790083,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/001/C8DF6810",
            },
        [80240105] = {
            ["Content"] = "做出来不用，放在那儿吃灰就舍得了？算了，现在也来不及拿了，唐叔你就勉勉强强，把我当拐杖吧。来，唐叔，我扶着你。",
            ["ContentFR"] = "Donc tu préfères la laisser prendre la poussière ? Bon... tant pis, c’est trop tard pour aller la chercher maintenant. Fais avec moi à la place. Allez, appuie-toi sur mon bras.",
            ["DialogueId"] = 80240105,
            ["GUID"] = "C8DF683A",
            ["NextDialogue"] = 80240106,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/001/C8DF683A",
            },
        [80240106] = {
            ["Content"] = "哎哟……小苏啊，真没到那个地步，唐叔这个年纪，撑着拐杖出门，人还以为唐叔七老八十了呢，多丢人啊。",
            ["ContentFR"] = "Oh là... ce n’est pas nécessaire. À mon âge, si je me promène avec une canne, les gens vont croire que j’ai quatre-vingts ans passés. Ce serait la honte.",
            ["DialogueId"] = 80240106,
            ["GUID"] = "C8DF6864",
            ["NextDialogue"] = 80240107,
            ["SpeakNpcId"] = 790083,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/001/C8DF6864",
            },
        [80240107] = {
            ["Content"] = "哼哼，这才是唐叔的真心话，被我套出来了吧~但是不行！",
            ["ContentFR"] = "Ah ! Voilà enfin la vérité. Je savais bien que je finirais par te la faire avouer. Mais ça ne change rien !",
            ["DialogueId"] = 80240107,
            ["GUID"] = "C8DF688E",
            ["NextDialogue"] = 80240108,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/001/C8DF688E",
            },
        [80240108] = {
            ["Content"] = "药师说，不能听病人的意见，你这腿不是第一次摔了，得多看顾着，免得落下病根。",
            ["ContentFR"] = "La guérisseuse l’a dit : on ne doit jamais écouter l’avis des patients. Ce n’est pas la première fois que tu tombes, alors il faut être prudent. Sinon tu risques de garder des séquelles.",
            ["DialogueId"] = 80240108,
            ["GUID"] = "C8DF68B8",
            ["NextDialogue"] = 80240109,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/001/C8DF68B8",
            },
        [80240109] = {
            ["Content"] = "好小苏，饶了唐叔吧，别去跟药师告状了。你都知道要让放久了的物什见见光，唐叔在床上躺了半个月了，也得出来晒晒太阳。",
            ["ContentFR"] = "Allez, petite Su... épargne-moi. Ne va pas te plaindre à la guérisseuse. Tu sais bien que les objets qui restent longtemps enfermés doivent prendre l’air. Eh bien moi, ça fait quinze jours que je suis cloué au lit. J’ai aussi besoin de soleil.",
            ["DialogueId"] = 80240109,
            ["GUID"] = "C8DF68E2",
            ["NextDialogue"] = 80240110,
            ["SpeakNpcId"] = 790083,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/001/C8DF68E2",
            },
        [80240110] = {
            ["Content"] = "快不说这个了，让唐叔看看，你这忙前忙后的，这晒的是什么东西啊？",
            ["ContentFR"] = "Bon, assez parlé de moi. Dis-moi plutôt ce que tu es en train de faire sécher.",
            ["DialogueId"] = 80240110,
            ["GUID"] = "C8DF690C",
            ["NextDialogue"] = 80240111,
            ["SpeakNpcId"] = 790083,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/001/C8DF690C",
            },
        [80240111] = {
            ["Content"] = "这是——",
            ["ContentFR"] = "C’est...",
            ["DialogueId"] = 80240111,
            ["GUID"] = "C8DF6936",
            ["NextDialogue"] = 80240112,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/001/C8DF6936",
            },
        [80240112] = {
            ["Content"] = "这是……抱抱鸟，一种能发热的机傀玩具。小时候我不爱睡觉，爸妈就做了这个，拿它哄我。我一抱住它，就能睡得着了。",
            ["ContentFR"] = "... un oiseau à câlins. Une méchapoupée capable de produire de la chaleur. Quand j’étais petite, je refusais toujours d’aller dormir. Alors mes parents ont fabriqué ça pour m’endormir. Dès que je le serrais dans mes bras... je m’endormais aussitôt.",
            ["DialogueId"] = 80240112,
            ["GUID"] = "C8DF6960",
            ["NextDialogue"] = 80240113,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/001/C8DF6960",
            },
        [80240113] = {
            ["Content"] = "哟，这么一看有印象了。这不是小苏每年都要买上一只的那个吗？",
            ["ContentFR"] = "Ah... maintenant que tu le dis, ça me revient. Ce n’est pas ce jouet que tu achètes tous les ans ?",
            ["DialogueId"] = 80240113,
            ["GUID"] = "C8DF698A",
            ["NextDialogue"] = 80240114,
            ["SpeakNpcId"] = 790083,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/001/C8DF698A",
            },
        [80240114] = {
            ["Content"] = "唐叔？！我不是都藏起来了吗，唐叔你——你在哪里见到的呀？",
            ["ContentFR"] = "Oncle Tang ?! Mais... je les avais pourtant cachés ! Où est-ce que tu les as vus ?",
            ["DialogueId"] = 80240114,
            ["GUID"] = "C8DF69B4",
            ["NextDialogue"] = 80240115,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/001/C8DF69B4",
            },
        [80240115] = {
            ["Content"] = "小苏年年都要买，买了之后又不开心，唐叔都看在眼里，担心着呢。",
            ["ContentFR"] = "Tu en achètes un chaque année. Puis tu passes les jours suivants à faire la tête. Je vois bien tout ça, moi. Ça m’inquiète.",
            ["DialogueId"] = 80240115,
            ["GUID"] = "C8DF69DE",
            ["NextDialogue"] = 80240116,
            ["SpeakNpcId"] = 790083,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/001/C8DF69DE",
            },
        [80240116] = {
            ["Content"] = "那会儿小苏刚来山外山，嘴巴像蚌壳一样，时常一个人闷着不说话。唐叔当时没找到机会问一问你，现在终于好跟小苏说点知心话了。",
            ["ContentFR"] = "Quand tu es arrivée aux Pics Extérieurs, tu étais muette comme une huître. Tu restais souvent seule dans ton coin, sans dire un mot. Je n’avais pas trouvé l’occasion de te poser la question à l’époque... mais aujourd’hui, on peut peut-être enfin parler à cœur ouvert.",
            ["DialogueId"] = 80240116,
            ["GUID"] = "C8DF6A08",
            ["NextDialogue"] = 80240117,
            ["SpeakNpcId"] = 790083,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/001/C8DF6A08",
            },
        [80240117] = {
            ["Content"] = "现在想想，小苏……莫不是想家了？",
            ["ContentFR"] = "Dis-moi, Su Yi... tu avais peut-être le mal du pays ?",
            ["DialogueId"] = 80240117,
            ["GUID"] = "C8DF6A32",
            ["NextDialogue"] = 80240118,
            ["SpeakNpcId"] = 790083,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/001/C8DF6A32",
            },
        [80240118] = {
            ["Content"] = "才没有！我家里人就在皓京，离得又不远，我想回去就回去了，有什么好想的。",
            ["ContentFR"] = "Pas du tout ! Ma famille est à Haojing, ce n’est pas si loin. Si je veux rentrer, je n’ai qu’à y aller. Qu’est-ce qu’il y aurait à regretter ?",
            ["DialogueId"] = 80240118,
            ["GUID"] = "C8DF6A5C",
            ["NextDialogue"] = 80240119,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/001/C8DF6A5C",
            },
        [80240119] = {
            ["Content"] = "呵呵……若是家是想回去就能回去的地方，也不至于有这么多飘零的游子了。",
            ["ContentFR"] = "Héhé... si rentrer chez soi était aussi simple, il n’y aurait pas autant d’âmes errantes dans ce monde.",
            ["DialogueId"] = 80240119,
            ["GUID"] = "C8DF6A86",
            ["NextDialogue"] = 80240120,
            ["SpeakNpcId"] = 790083,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/001/C8DF6A86",
            },
        [80240120] = {
            ["Content"] = "和唐叔说说，小苏是因为什么不愿意回家？是不是最近太累了，身体撑不住，怕让家里人担心？",
            ["ContentFR"] = "Dis-moi plutôt pourquoi tu refuses de rentrer. Tu travailles trop ces derniers temps ? Tu as peur d’inquiéter ta famille ?",
            ["DialogueId"] = 80240120,
            ["GUID"] = "C8DF6AB0",
            ["NextDialogue"] = 80240121,
            ["SpeakNpcId"] = 790083,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/001/C8DF6AB0",
            },
        [80240121] = {
            ["Content"] = "没什么啦，就是没时间回去而已！我自己的身体我心里有数，你看，我能跑能跳的，特别健康。",
            ["ContentFR"] = "Ce n’est rien de tout ça ! C’est juste que je n’ai pas le temps d’y aller. Et puis je connais mon corps. Regarde, je peux courir et sauter comme je veux. Je suis en pleine forme.",
            ["DialogueId"] = 80240121,
            ["GUID"] = "C8DF6ADA",
            ["NextDialogue"] = 80240122,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/001/C8DF6ADA",
            },
        [80240122] = {
            ["Content"] = "不是身体上的问题，就是心里的问题喽？",
            ["ContentFR"] = "Alors si ce n’est pas ton corps... c’est ton cœur qui te tracasse ?",
            ["DialogueId"] = 80240122,
            ["GUID"] = "C8DF6B04",
            ["NextDialogue"] = 80240123,
            ["SpeakNpcId"] = 790083,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/001/C8DF6B04",
            },
        [80240123] = {
            ["Content"] = "都说了我没……",
            ["ContentFR"] = "Je t’ai dit que je n’avais...",
            ["DialogueId"] = 80240123,
            ["GUID"] = "C8DF6B2E",
            ["NextDialogue"] = 80240124,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/001/C8DF6B2E",
            },
        [80240124] = {
            ["Content"] = "……好吧！真是什么都瞒不过唐叔，我是有点想家。",
            ["ContentFR"] = "... bon, d’accord ! On ne peut vraiment rien te cacher, Oncle Tang. C’est vrai que... j’ai un peu le mal du pays.",
            ["DialogueId"] = 80240124,
            ["GUID"] = "C8DF6B58",
            ["NextDialogue"] = 80240125,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/001/C8DF6B58",
            },
        [80240125] = {
            ["Content"] = "难不成是纠结带什么礼物？你这些年的发明，随意拿回去一个，就够让人刮目相看了。",
            ["ContentFR"] = "Tu hésites peut-être sur le cadeau à apporter ? Avec toutes les inventions que tu as réalisées ces dernières années, il suffirait d’en rapporter une pour impressionner tout le monde.",
            ["DialogueId"] = 80240125,
            ["GUID"] = "C8DF6B82",
            ["NextDialogue"] = 80240126,
            ["SpeakNpcId"] = 790083,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/001/C8DF6B82",
            },
        [80240126] = {
            ["Content"] = "不是啦，我爸妈不喜欢机枢，看见我研究机枢就来气，更不会因为这个夸我。礼物带这个，那是火上浇油了。",
            ["ContentFR"] = "Ce n’est pas ça. Mes parents détestent les méchapoupées. Rien que de me voir étudier l’art des méchapoupées les met en colère. Ils ne me féliciteraient jamais pour ça. Si j’apportais ce genre de cadeau, ce serait pire encore.",
            ["DialogueId"] = 80240126,
            ["GUID"] = "C8DF6BAC",
            ["NextDialogue"] = 80240127,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/001/C8DF6BAC",
            },
        [80240127] = {
            ["Content"] = "我……从小就很喜欢机枢术，学的也很快。天工苏氏古籍所载技法，我看一遍就会，哪怕是缺页少字的篇章，我也能看得懂，还能自行补全。",
            ["ContentFR"] = "Depuis toute petite... j’ai toujours adoré l’art des méchapoupées. Et j’apprenais vite. Les techniques décrites dans les anciens ouvrages du clan Su, je pouvais les comprendre d’un seul coup d’œil. Même quand il manquait des pages, j’arrivais à reconstituer le reste.",
            ["DialogueId"] = 80240127,
            ["GUID"] = "C8DF6BD6",
            ["NextDialogue"] = 80240128,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/001/C8DF6BD6",
            },
        [80240128] = {
            ["Content"] = "我喜欢机枢，也喜欢研究机枢，但是爸妈不喜欢，他们不希望我学这个。",
            ["ContentFR"] = "J’aimais vraiment ça... mais mes parents, eux, détestaient. Ils ne voulaient pas que j’étudie ces choses.",
            ["DialogueId"] = 80240128,
            ["GUID"] = "C8DF6C00",
            ["NextDialogue"] = 80240129,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/001/C8DF6C00",
            },
        [80240129] = {
            ["Content"] = "家里……就是父母的一言堂，他们不喜欢，我就也不能喜欢。幸好还有姑姑在，会偷偷地教我机枢知识，陪我一起拆卸研究。",
            ["ContentFR"] = "À la maison... leur parole faisait loi. S’ils n’aimaient pas quelque chose, je n’avais pas le droit de l’aimer non plus. Heureusement que ma tante était là. Elle me transmettait en secret ce qu’elle savait, et on démontait les machines ensemble pour les étudier.",
            ["DialogueId"] = 80240129,
            ["GUID"] = "C8DF6C2A",
            ["NextDialogue"] = 80240130,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/001/C8DF6C2A",
            },
        [80240130] = {
            ["Content"] = "呵呵，现在大风九章可是大变样咯，机枢派的往事也翻了盘。你父母心里头的想法，指不定有所改变呢。人呐，都是在向前走的。",
            ["ContentFR"] = "Héhé... aujourd’hui, les Neuf Chapitres de Dafeng ont bien changé. Même l’histoire de la Secte Jishu a été réhabilitée. Qui sait ? Peut-être que tes parents ont changé d’avis eux aussi. Les gens avancent toujours, tu sais.",
            ["DialogueId"] = 80240130,
            ["GUID"] = "C8DF6C54",
            ["NextDialogue"] = 80240131,
            ["SpeakNpcId"] = 790083,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/001/C8DF6C54",
            },
        [80240131] = {
            ["Content"] = "但是……这毕竟不算他们眼里的正道，再说，这么些年对我不闻不问，肯定是还没原谅我。",
            ["ContentFR"] = "Mais... pour eux, ce ne sera jamais une voie respectable. Et puis... toutes ces années sans la moindre nouvelle... ça veut bien dire qu’ils ne m’ont toujours pas pardonnée.",
            ["DialogueId"] = 80240131,
            ["GUID"] = "C8DF6C7E",
            ["NextDialogue"] = 80240132,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/001/C8DF6C7E",
            },
        [80240132] = {
            ["Content"] = "来山外山的时候跟家里人吵架了？",
            ["ContentFR"] = "Tu t’es disputée avec eux avant de venir aux Pics Extérieurs ?",
            ["DialogueId"] = 80240132,
            ["GUID"] = "C8DF6CA8",
            ["NextDialogue"] = 80240133,
            ["SpeakNpcId"] = 790083,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/001/C8DF6CA8",
            },
        [80240133] = {
            ["Content"] = "嗯……我走的时候，跟爸妈说了一些不太好的话。爸妈也说，以后就当没我这个女儿。",
            ["ContentFR"] = "Oui... quand je suis partie, j’ai dit des choses horribles. Et eux... ils m’ont répondu qu’à partir de ce jour-là, ils n’avaient plus de fille.",
            ["DialogueId"] = 80240133,
            ["GUID"] = "C8DF6CD2",
            ["NextDialogue"] = 80240134,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/001/C8DF6CD2",
            },
        [80240134] = {
            ["Content"] = "在家的时候，每逢年关新至，爸妈就会送我一只新的抱抱鸟，我失眠的时候，抱着它就能睡得着。",
            ["ContentFR"] = "Quand j’étais à la maison, chaque nouvelle année, mes parents m’en offraient un nouveau. Quand je faisais de l’insomnie, il me suffisait de le serrer dans mes bras pour m’endormir.",
            ["DialogueId"] = 80240134,
            ["GUID"] = "C8DF6CFC",
            ["NextDialogue"] = 80240135,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/001/C8DF6CFC",
            },
        [80240135] = {
            ["Content"] = "我最后悔的一件事，就是离家出走的时候没有揣上两只抱抱鸟，害得我刚来山外山时彻夜难眠。幸好后来在往返于山外山的商人那买到了差不多的。",
            ["ContentFR"] = "Ce que je regrette le plus, c’est de ne pas en avoir emporté deux avec moi quand je suis partie. Mes premières nuits aux Pics Extérieurs, je n’ai pas fermé l’œil. Heureusement, j’ai fini par en trouver des semblables auprès de marchands de passage.",
            ["DialogueId"] = 80240135,
            ["GUID"] = "C8DF6D26",
            ["NextDialogue"] = 80240136,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/001/C8DF6D26",
            },
        [80240136] = {
            ["Content"] = "这个……真的很像我爸妈做的，但是针脚密密的，手艺比我爸妈好多了。",
            ["ContentFR"] = "Celui-ci... ressemble vraiment à ceux que faisaient mes parents. Mais les coutures sont bien plus fines. L’artisan est meilleur qu’eux.",
            ["DialogueId"] = 80240136,
            ["GUID"] = "C8DF6D50",
            ["NextDialogue"] = 80240137,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/001/C8DF6D50",
            },
        [80240137] = {
            ["Content"] = "我每次看到都会忍不住买下来，又不敢仔细看太久，怕自己难过。买回来就匆匆塞进箱子里，扣上盖子推回床底下，好像什么都没发生过。",
            ["ContentFR"] = "Chaque fois que j’en vois un, je ne peux pas m’empêcher de l’acheter. Mais je n’ose jamais le regarder trop longtemps, de peur d’être triste. Alors je le jette dans un coffre, je referme le couvercle et je le pousse sous le lit... comme si de rien n’était.",
            ["DialogueId"] = 80240137,
            ["GUID"] = "C8DF6D7A",
            ["NextDialogue"] = 80240138,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/001/C8DF6D7A",
            },
        [80240138] = {
            ["Content"] = "……很自欺欺人，对吧？我也意识到，不能再继续逃避了。",
            ["ContentFR"] = "... C’est assez ridicule, hein ? Je sais bien que je ne peux pas continuer à fuir comme ça.",
            ["DialogueId"] = 80240138,
            ["GUID"] = "C8DF6DA4",
            ["NextDialogue"] = 80240139,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/001/C8DF6DA4",
            },
        [80240139] = {
            ["Content"] = "这几天取出来，发现它们落了好多灰。我把灰尘拍掉，又怕它们发霉，所以晾晒一下……看着这些抱抱鸟，我就又想起家里的事情了。",
            ["ContentFR"] = "Ces derniers jours, je les ai ressortis. Ils étaient couverts de poussière. Je les ai dépoussiérés, puis je les ai mis à sécher de peur qu’ils ne moisissent... Et en les regardant, tous ces souvenirs de la maison me sont revenus.",
            ["DialogueId"] = 80240139,
            ["GUID"] = "C8DF6DCE",
            ["NextDialogue"] = 80240140,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/001/C8DF6DCE",
            },
        [80240140] = {
            ["Content"] = "之前是我的身份不方便走动，也怕连累他们，不敢回家。",
            ["ContentFR"] = "Avant, je ne pouvais pas rentrer. Ma situation ne me permettait pas de voyager librement, et j’avais peur de leur attirer des ennuis.",
            ["DialogueId"] = 80240140,
            ["GUID"] = "C8DF6DF8",
            ["NextDialogue"] = 80240141,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/001/C8DF6DF8",
            },
        [80240141] = {
            ["Content"] = "最近华胥的天变了，我就想……",
            ["ContentFR"] = "Mais récemment... les choses ont changé à Huaxu, alors je me suis dit...",
            ["DialogueId"] = 80240141,
            ["GUID"] = "C8DF6E22",
            ["NextDialogue"] = 80240142,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/001/C8DF6E22",
            },
        [80240142] = {
            ["Content"] = "……唐叔，我不敢想。我想回去，可是我不敢回去……我该怎么办？",
            ["ContentFR"] = "... Oncle Tang, je n’ose pas y penser. J’ai envie de rentrer... mais je n’en ai pas le courage. Qu’est-ce que je dois faire ?",
            ["DialogueId"] = 80240142,
            ["GUID"] = "C8DF6E4C",
            ["NextDialogue"] = 80240143,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/001/C8DF6E4C",
            },
        [80240143] = {
            ["Content"] = "要是他们没原谅我，赶我走，不承认我是他们的女儿，那我、那我……",
            ["ContentFR"] = "Et s’ils ne m’avaient toujours pas pardonnée ? S’ils me chassaient... s’ils refusaient de me reconnaître comme leur fille... alors je... je...",
            ["DialogueId"] = 80240143,
            ["GUID"] = "C8DF6E76",
            ["NextDialogue"] = 80240144,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/001/C8DF6E76",
            },
        [80240144] = {
            ["Content"] = "我们小苏啊，心思细，想得也多，这是好事。只是有时候，不必考虑那么多，负担都在心里坠着，多沉、多难受啊。",
            ["ContentFR"] = "Ma petite Su Yi... tu réfléchis trop, c’est tout. Tu as l’esprit fin et le cœur sensible, et ce sont de belles qualités. Mais parfois, il n’est pas nécessaire de porter autant de poids dans son cœur. C’est lourd... et douloureux.",
            ["DialogueId"] = 80240144,
            ["GUID"] = "C8DF6EA0",
            ["NextDialogue"] = 80240145,
            ["SpeakNpcId"] = 790083,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/001/C8DF6EA0",
            },
        [80240145] = {
            ["Content"] = "想家了，就回去看看吧。",
            ["ContentFR"] = "Si ton cœur te ramène vers ta maison... alors va simplement la revoir.",
            ["DialogueId"] = 80240145,
            ["GUID"] = "C8DF6ECA",
            ["SpeakNpcId"] = 790083,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/001/C8DF6ECA",
            },
        [80240201] = {
            ["Content"] = "四年前",
            ["ContentFR"] = "— Quatre ans plus tôt —",
            ["DialogueId"] = 80240201,
            ["GUID"] = "C8DF77FA",
            ["NextDialogue"] = 80240202,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/002/C8DF77FA",
            },
        [80240202] = {
            ["Content"] = "小黑，我要走了。我走之后，爸妈只能托你来照顾了。",
            ["ContentFR"] = "Charbon... je pars. Une fois que je serai partie, il faudra que tu t’occupes de papa et maman à ma place.",
            ["DialogueId"] = 80240202,
            ["GUID"] = "C8DF7824",
            ["NextDialogue"] = 80240203,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/002/C8DF7824",
            },
        [80240203] = {
            ["Content"] = "你可得时不时来巡逻一番，把那坏耗子统统逮住，别让家里的米粮遭了殃。要是我走后爸妈寂寞了，你也替我去他们脚旁蹭上两圈……",
            ["ContentFR"] = "Passe de temps en temps faire ta ronde, et attrape tous ces sales rats. Il ne faudrait pas qu’ils abîment le riz et les réserves. Et si papa et maman se sentent seuls... va te frotter contre leurs jambes pour moi.",
            ["DialogueId"] = 80240203,
            ["GUID"] = "C8DF784E",
            ["NextDialogue"] = 80240204,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/002/C8DF784E",
            },
        [80240204] = {
            ["Content"] = "喵~",
            ["ContentFR"] = "<I>Miaou~</>",
            ["DialogueId"] = 80240204,
            ["GUID"] = "C8DF7878",
            ["NextDialogue"] = 80240205,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/002/C8DF7878",
            },
        [80240205] = {
            ["Content"] = "最后检查一遍行李。两套衣裳，榫卯青铜工具各一套，姑姑留给我的图纸……",
            ["ContentFR"] = "Dernière vérification des bagages... Deux tenues de rechange, un jeu complet d’outils en bronze pour l’assemblage, les plans que m’a laissés ma tante...",
            ["DialogueId"] = 80240205,
            ["GUID"] = "C8DF78A2",
            ["NextDialogue"] = 80240206,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/002/C8DF78A2",
            },
        [80240206] = {
            ["Content"] = "糟糕，抱抱鸟忘带了，得再回去拿一趟——",
            ["ContentFR"] = "Zut... j’ai oublié les oiseaux à câlins. Il faut que je retourne les chercher—",
            ["DialogueId"] = 80240206,
            ["GUID"] = "C8DF78CC",
            ["NextDialogue"] = 80240207,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/002/C8DF78CC",
            },
        [80240207] = {
            ["Content"] = "既已下定决心要走，这家此后与你就再无瓜葛。又何必再进进出出，反反复复，牵扯不休。",
            ["ContentFR"] = "Puisque tu as décidé de partir, cette maison n’a plus rien à voir avec toi. Alors pourquoi hésiter encore ? Entrer et sortir sans cesse... coupe le lien une bonne fois pour toutes.",
            ["DialogueId"] = 80240207,
            ["GUID"] = "C8DF78F6",
            ["NextDialogue"] = 80240208,
            ["SpeakNpcId"] = 790084,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/002/C8DF78F6",
            },
        [80240208] = {
            ["Content"] = "……妈，你怎么还醒着？",
            ["ContentFR"] = "... Maman ? Tu es encore réveillée ?",
            ["DialogueId"] = 80240208,
            ["GUID"] = "C8DF7920",
            ["NextDialogue"] = 80240209,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/002/C8DF7920",
            },
        [80240209] = {
            ["Content"] = "我还以为你早就睡了。难不成是看到我留在桌上的信了？",
            ["ContentFR"] = "Je pensais que tu dormais déjà. Tu as vu la lettre que j’ai laissée sur la table ?",
            ["DialogueId"] = 80240209,
            ["GUID"] = "C8DF794A",
            ["NextDialogue"] = 80240210,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/002/C8DF794A",
            },
        [80240210] = {
            ["Content"] = "那个，就像我信里写的一样啦，你们的女儿要去追求理想了，但以后有机会还会常回来看看的，不用为我担心……",
            ["ContentFR"] = "Enfin... c’est comme je l’ai écrit. Ta fille part poursuivre ses rêves. Mais je reviendrai vous voir quand j’en aurai l’occasion, alors ne vous inquiétez pas pour moi—",
            ["DialogueId"] = 80240210,
            ["GUID"] = "C8DF7974",
            ["NextDialogue"] = 80240211,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/002/C8DF7974",
            },
        [80240211] = {
            ["Content"] = "够了，休要再说这些儿戏之言。",
            ["ContentFR"] = "Ça suffit. Je ne veux plus entendre ces paroles enfantines.",
            ["DialogueId"] = 80240211,
            ["GUID"] = "C8DF799E",
            ["NextDialogue"] = 80240212,
            ["SpeakNpcId"] = 790084,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/002/C8DF799E",
            },
        [80240212] = {
            ["Content"] = "你是我怀胎十月生下的骨肉，你那心思自以为藏得很好，我实际一看即知。是我平时太娇纵于你，才把你养得这般离经叛道，不知天高地厚。",
            ["ContentFR"] = "Je t’ai portée dix mois dans mon ventre. Tu es mon propre sang. Tu pensais cacher tes intentions ? Je les ai devinées immédiatement. Si tu es devenue aussi rebelle et inconsidérée, c’est parce que je t’ai trop gâtée.",
            ["DialogueId"] = 80240212,
            ["GUID"] = "C8DF79C8",
            ["NextDialogue"] = 80240213,
            ["SpeakNpcId"] = 790084,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/002/C8DF79C8",
            },
        [80240213] = {
            ["Content"] = "听话，回家去。今日之事，权做未曾发生。妈妈不想你重蹈你姑姑的覆辙。",
            ["ContentFR"] = "Écoute-moi. Rentre à la maison. Considérons simplement que rien de tout cela ne s’est produit. Je refuse que tu suives le même chemin que ta tante.",
            ["DialogueId"] = 80240213,
            ["GUID"] = "C8DF79F2",
            ["NextDialogue"] = 80240214,
            ["SpeakNpcId"] = 790084,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/002/C8DF79F2",
            },
        [80240214] = {
            ["Content"] = "……娇纵？你还好意思说娇纵？",
            ["ContentFR"] = "... Me gâter ? Tu oses vraiment parler de me gâter ?",
            ["DialogueId"] = 80240214,
            ["GUID"] = "C8DF7A1C",
            ["NextDialogue"] = 80240215,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/002/C8DF7A1C",
            },
        [80240215] = {
            ["Content"] = "从小到大，你们什么都不让我做。不许学机枢术，不许捣鼓工具，吃饭不许出声，不许对白龙神不敬。我就像木偶一样被你们摆弄。你管这叫娇纵？！",
            ["ContentFR"] = "Depuis que je suis petite, vous m’avez interdit de tout faire. Interdit d’apprendre l’art des méchapoupées, interdit de toucher aux outils, interdit de faire du bruit à table, interdit d’être irrespectueuse envers Taihao. J’ai vécu comme une marionnette que vous manipuliez. Et tu appelles ça me gâter ?!",
            ["DialogueId"] = 80240215,
            ["GUID"] = "C8DF7A46",
            ["NextDialogue"] = 80240216,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/002/C8DF7A46",
            },
        [80240216] = {
            ["Content"] = "最后还是姑姑央求，你们才勉强睁一只眼闭一只眼，允许我做自己喜欢的事情！而姑姑走后，这个家里连她的名字都不允许提！",
            ["ContentFR"] = "Il a fallu que tante supplie pour que vous fermiez enfin les yeux et me laissiez faire ce que j’aimais ! Et dès qu’elle est partie... son nom même est devenu interdit dans cette maison !",
            ["DialogueId"] = 80240216,
            ["GUID"] = "C8DF7A70",
            ["NextDialogue"] = 80240217,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/002/C8DF7A70",
            },
        [80240217] = {
            ["Content"] = "大风九章种种不公，你们视而不见。姑姑含冤而死，你们甚至没有为她流一滴泪，只顾着保全自己，天天想着如何不受牵连。你们的心肠是铁石做的吗？！",
            ["ContentFR"] = "Toutes les injustices des Neuf Chapitres de Dafeng, vous les avez ignorées. Tante est morte innocente, et vous n’avez même pas versé une larme pour elle. Tout ce qui vous importait, c’était de vous protéger et d’éviter d’être impliqués. Vos cœurs sont-ils faits de pierre ?!",
            ["DialogueId"] = 80240217,
            ["GUID"] = "C8DF7A9A",
            ["NextDialogue"] = 80240218,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/002/C8DF7A9A",
            },
        [80240218] = {
            ["Content"] = "你……怎敢这般口出狂言！",
            ["ContentFR"] = "Toi... comment oses-tu proférer de telles paroles !",
            ["DialogueId"] = 80240218,
            ["GUID"] = "C8DF7AC4",
            ["NextDialogue"] = 80240219,
            ["SpeakNpcId"] = 790084,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/002/C8DF7AC4",
            },
        [80240219] = {
            ["Content"] = "太皓神君原谅小女无心之言，小苏，快为刚刚的话道歉。",
            ["ContentFR"] = "Seigneur Dragon d’Argent, pardonne les paroles irréfléchies de ma fille. Su Yi, excuse-toi immédiatement.",
            ["DialogueId"] = 80240219,
            ["GUID"] = "C8DF7AEE",
            ["NextDialogue"] = 80240220,
            ["SpeakNpcId"] = 790084,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/002/C8DF7AEE",
            },
        [80240220] = {
            ["Content"] = "不，我今天一定要把话说个明白！",
            ["ContentFR"] = "Non ! Aujourd’hui, je vais dire tout ce que j’ai à dire !",
            ["DialogueId"] = 80240220,
            ["GUID"] = "C8DF7B18",
            ["NextDialogue"] = 80240221,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/002/C8DF7B18",
            },
        [80240221] = {
            ["Content"] = "姑姑和我说，曾经的你爱笑，爱妆扮，还有一手机枢独学。可是现在的你呢？成天战战兢兢，如履薄冰，总是板着个脸，担心哪一步踏错了。",
            ["ContentFR"] = "Tante m’a raconté qu’autrefois tu aimais rire, te parer de beaux vêtements, et que tu étais une grande experte en méchapoupées. Mais regarde ce que tu es devenue ! Toujours tremblante, toujours prudente, comme si tu marchais sur de la glace fine, effrayée à l’idée de faire le moindre faux pas.",
            ["DialogueId"] = 80240221,
            ["GUID"] = "C8DF7B42",
            ["NextDialogue"] = 80240222,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/002/C8DF7B42",
            },
        [80240222] = {
            ["Content"] = "你的一身技艺只能用来做抱抱鸟这种没用的玩具，可是机枢术明明能够用来尝试更突破性，更了不起，能够造福所有人的技术！",
            ["ContentFR"] = "Tout ton talent sert maintenant à fabriquer des jouets inutiles comme ces oiseaux à câlins. Alors que l’art des méchapoupées pourrait permettre d’inventer des choses bien plus extraordinaires... des créations capables d’aider tout le monde !",
            ["DialogueId"] = 80240222,
            ["GUID"] = "C8DF7B6C",
            ["NextDialogue"] = 80240223,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/002/C8DF7B6C",
            },
        [80240223] = {
            ["Content"] = "你愿意放弃理想，向太皓俯首。可是你不能替我决定，把我的一辈子也关在牢笼里啊！",
            ["ContentFR"] = "Tu as peut-être choisi d’abandonner tes rêves et de t’incliner devant Taihao. Mais tu n’as pas le droit de décider à ma place et d’enfermer toute ma vie dans cette cage !",
            ["DialogueId"] = 80240223,
            ["GUID"] = "C8DF7B96",
            ["NextDialogue"] = 80240224,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/002/C8DF7B96",
            },
        [80240224] = {
            ["Content"] = "好啊，既然你一定要把话说开，今天为娘就和你统统说个明白。",
            ["ContentFR"] = "Très bien. Puisque tu veux absolument vider ton sac, alors écoute-moi bien.",
            ["DialogueId"] = 80240224,
            ["GUID"] = "C8DF7BC0",
            ["NextDialogue"] = 80240225,
            ["SpeakNpcId"] = 790084,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/002/C8DF7BC0",
            },
        [80240225] = {
            ["Content"] = "苏乙，你以为我这么多年的牺牲，这么多年的小心谨慎是为了谁？不都是为了你，为了这个家吗。",
            ["ContentFR"] = "Su Yi, pour qui crois-tu que j’ai fait tous ces sacrifices pendant toutes ces années ? Pour qui ai-je vécu dans la peur ? Pour toi. Pour cette famille.",
            ["DialogueId"] = 80240225,
            ["GUID"] = "C8DF7BEA",
            ["NextDialogue"] = 80240226,
            ["SpeakNpcId"] = 790084,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/002/C8DF7BEA",
            },
        [80240226] = {
            ["Content"] = "天工苏氏是什么处境，你难道不知道？平时不让你摆弄这些，是怕你触犯“禁忌”，自毁前程。",
            ["ContentFR"] = "Ignore-tu vraiment la situation dans laquelle se trouve le clan Su ? Si je t’ai empêchée de toucher à ces choses, c’était pour éviter que tu ne brises un tabou et ne ruines ton avenir.",
            ["DialogueId"] = 80240226,
            ["GUID"] = "C8DF7C14",
            ["NextDialogue"] = 80240227,
            ["SpeakNpcId"] = 790084,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/002/C8DF7C14",
            },
        [80240227] = {
            ["Content"] = "天工苏氏断臂求生，好不容易才有今日，已经担不起半点风险了。你年轻气盛，想要的无非是学以致用、出人头地。天梁司用人有缺，恰有你的用武之地。",
            ["ContentFR"] = "Les Artisans Célestes du clan Su ont dû sacrifier une part d’eux-mêmes pour survivre. Nous avons eu toutes les peines du monde à arriver jusqu’ici. Nous ne pouvons plus prendre le moindre risque. Tu es jeune, fougueuse. Tu veux simplement mettre ton talent à l’épreuve et te faire un nom. Justement, le Bureau des Travaux manque de personnel. C’est là que tu devrais aller.",
            ["DialogueId"] = 80240227,
            ["GUID"] = "C8DF7C3E",
            ["NextDialogue"] = 80240228,
            ["SpeakNpcId"] = 790084,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/002/C8DF7C3E",
            },
        [80240228] = {
            ["Content"] = "为了安稳度日，那些机枢理想统统可以让步。你年轻，还不懂这样的道理。等你受伤的时候再后悔，就来不及了！",
            ["ContentFR"] = "Pour vivre en paix, il faut parfois renoncer à certains rêves. Tu es trop jeune pour comprendre cela. Mais quand tu souffriras un jour, il sera trop tard pour regretter !",
            ["DialogueId"] = 80240228,
            ["GUID"] = "C8DF7C68",
            ["NextDialogue"] = 80240229,
            ["SpeakNpcId"] = 790084,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/002/C8DF7C68",
            },
        [80240229] = {
            ["Content"] = "……妈，为什么你不明白呢？你给的再多也没用，那些都不是我想要的啊。",
            ["ContentFR"] = "... Maman. Pourquoi refuses-tu de comprendre ? Tout ce que tu me proposes... ce n’est pas ce que je veux vraiment.",
            ["DialogueId"] = 80240229,
            ["GUID"] = "C8DF7C92",
            ["NextDialogue"] = 80240230,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/002/C8DF7C92",
            },
        [80240230] = {
            ["Content"] = "我要走了，既然你不让我回去拿，那抱抱鸟我也不要了。反正我也不稀罕。",
            ["ContentFR"] = "Je pars. Puisque tu refuses que je retourne les chercher, je laisse les oiseaux à câlins ici. De toute façon, je n’en ai pas besoin.",
            ["DialogueId"] = 80240230,
            ["GUID"] = "C8DF7CBC",
            ["NextDialogue"] = 80240231,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/002/C8DF7CBC",
            },
        [80240231] = {
            ["Content"] = "回来，我没让你走。",
            ["ContentFR"] = "Reviens ici. Je ne t’ai pas dit de partir.",
            ["DialogueId"] = 80240231,
            ["GUID"] = "C8DF7CE6",
            ["NextDialogue"] = 80240232,
            ["SpeakNpcId"] = 790084,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/002/C8DF7CE6",
            },
        [80240232] = {
            ["Content"] = "我凭什么不能走？",
            ["ContentFR"] = "Pourquoi je ne pourrais pas partir ?",
            ["DialogueId"] = 80240232,
            ["GUID"] = "C8DF7D10",
            ["NextDialogue"] = 80240233,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/002/C8DF7D10",
            },
        [80240233] = {
            ["Content"] = "凭你是我的女儿，我是你妈妈！",
            ["ContentFR"] = "Parce que tu es ma fille. Et que je suis ta mère !",
            ["DialogueId"] = 80240233,
            ["GUID"] = "C8DF7D3A",
            ["NextDialogue"] = 80240234,
            ["SpeakNpcId"] = 790084,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/002/C8DF7D3A",
            },
        [80240234] = {
            ["Content"] = "今天你敢走出这巷口，天工苏氏就再无苏乙这号人！",
            ["ContentFR"] = "Si tu franchis cette ruelle aujourd’hui, alors les Artisans Célestes du clan Su n’auront jamais eu de fille nommée Su Yi !",
            ["DialogueId"] = 80240234,
            ["GUID"] = "C8DF7D64",
            ["NextDialogue"] = 80240235,
            ["SpeakNpcId"] = 790084,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/002/C8DF7D64",
            },
        [80240235] = {
            ["Content"] = "你什么都不懂，就别再拦我了！！我才不要和你一起被困在这囚笼里！",
            ["ContentFR"] = "Tu ne comprends rien ! Alors arrête de me barrer la route ! Je refuse de rester enfermée dans cette cage avec toi !",
            ["DialogueId"] = 80240235,
            ["GUID"] = "C8DF7D8E",
            ["NextDialogue"] = 80240236,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/002/C8DF7D8E",
            },
        }
  end },
  { MinKey = 80240236, MaxKey = 90070202, Loader = function()
      return {
        [80240236] = {
            ["Content"] = "十几年殷殷爱护……养出这么个无法无天之徒……",
            ["ContentFR"] = "Plus de dix ans d’amour et de soins... et voilà le monstre ingrat que j’ai élevé...",
            ["DialogueId"] = 80240236,
            ["GUID"] = "C8DF7DB8",
            ["NextDialogue"] = 80240237,
            ["SpeakNpcId"] = 790084,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/002/C8DF7DB8",
            },
        [80240237] = {
            ["Content"] = "不，妈妈，你还好吗？我不是故意的——",
            ["ContentFR"] = "Non— maman ! Tu vas bien ? Je ne l’ai pas fait exprès—",
            ["DialogueId"] = 80240237,
            ["GUID"] = "C8DF7DE2",
            ["NextDialogue"] = 80240238,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/002/C8DF7DE2",
            },
        [80240238] = {
            ["Content"] = "别喊我了。你不愿认我这个妈，我也从未生过你这个女儿。从此我们一刀两断，再无瓜葛。",
            ["ContentFR"] = "Ne m’appelle plus ainsi. Puisque tu refuses de me reconnaître comme ta mère, je ferai comme si je ne t’avais jamais mise au monde. À partir d’aujourd’hui, nous n’avons plus aucun lien.",
            ["DialogueId"] = 80240238,
            ["GUID"] = "C8DF7E0C",
            ["NextDialogue"] = 80240239,
            ["SpeakNpcId"] = 790084,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/002/C8DF7E0C",
            },
        [80240239] = {
            ["Content"] = "拿好你的东西，滚！再也别回来！滚——",
            ["ContentFR"] = "Prends tes affaires et disparais ! Ne reviens jamais ! Pars !",
            ["DialogueId"] = 80240239,
            ["GUID"] = "C8DF7E36",
            ["SpeakNpcId"] = 790084,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/002/C8DF7E36",
            },
        [80240301] = {
            ["Content"] = "…………",
            ["ContentFR"] = "...",
            ["DialogueId"] = 80240301,
            ["GUID"] = "C8DF8862",
            ["NextDialogue"] = 80240302,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF8862",
            },
        [80240302] = {
            ["Content"] = "奇怪，怎么没有人应门？",
            ["ContentFR"] = "Étrange... pourquoi personne ne répond ?",
            ["DialogueId"] = 80240302,
            ["GUID"] = "C8DF888C",
            ["NextDialogue"] = 80240303,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF888C",
            },
        [80240303] = {
            ["Content"] = "爸妈是搬走了吗，还是不愿见我……",
            ["ContentFR"] = "Papa et maman ont déménagé ? Ou bien... ils ne veulent tout simplement pas me voir...",
            ["DialogueId"] = 80240303,
            ["GUID"] = "C8DF88B6",
            ["NextDialogue"] = 80240304,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF88B6",
            },
        [80240304] = {
            ["Content"] = "喵~",
            ["ContentFR"] = "<I>Miaou~</>",
            ["DialogueId"] = 80240304,
            ["GUID"] = "C8DF88E0",
            ["NextDialogue"] = 80240305,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF88E0",
            },
        [80240305] = {
            ["Content"] = "小黑！这么些年过去了，你还在这里！",
            ["ContentFR"] = "Charbon ! Toutes ces années ont passé, et tu es encore ici !",
            ["DialogueId"] = 80240305,
            ["GUID"] = "C8DF890A",
            ["NextDialogue"] = 80240306,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF890A",
            },
        [80240306] = {
            ["Content"] = "……要是你能说话就好了，至少你能告诉我这些年爸妈过得怎么样，还好不好……",
            ["ContentFR"] = "... Si seulement tu pouvais parler. Tu pourrais au moins me dire comment papa et maman ont vécu toutes ces années... s’ils vont bien...",
            ["DialogueId"] = 80240306,
            ["GUID"] = "C8DF8934",
            ["NextDialogue"] = 80240307,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF8934",
            },
        [80240307] = {
            ["Content"] = "要不我还是回去……不行，都到这里了，我苏乙的字典里没有半途而废！",
            ["ContentFR"] = "Peut-être que je devrais repartir... Non ! J’ai déjà fait tout ce chemin. Et dans le dictionnaire de Su Yi, il n’existe pas d’abandon en cours de route !",
            ["DialogueId"] = 80240307,
            ["GUID"] = "C8DF895E",
            ["NextDialogue"] = 80240308,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF895E",
            },
        [80240308] = {
            ["Content"] = "大家都好忙啊，总感觉不太方便打扰。",
            ["ContentFR"] = "Tout le monde a l’air terriblement occupé... j’ai l’impression que ce serait malvenu de déranger.",
            ["DialogueId"] = 80240308,
            ["GUID"] = "C8DF8988",
            ["NextDialogue"] = 80240309,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF8988",
            },
        [80240309] = {
            ["Content"] = "……等一下，这里有个闲人？",
            ["ContentFR"] = "... Attends une seconde. Il y a quelqu’un qui ne fait rien, là-bas ?",
            ["DialogueId"] = 80240309,
            ["GUID"] = "C8DF89B2",
            ["NextDialogue"] = 80240310,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF89B2",
            },
        [80240310] = {
            ["Content"] = "工匠大叔，你在这儿晒太阳呢？",
            ["ContentFR"] = "Excusez-moi, maître artisan... vous profitez du soleil ?",
            ["DialogueId"] = 80240310,
            ["GUID"] = "C8DF89DC",
            ["NextDialogue"] = 80240311,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF89DC",
            },
        [80240311] = {
            ["Content"] = "天气这么好，不晒晒太阳，多不给太阳面子。你也来享受享受？不过我这儿可没有垫子。",
            ["ContentFR"] = "Avec un temps pareil, ce serait presque une offense de ne pas en profiter. Tu veux t’asseoir un moment ? Par contre, je n’ai pas de coussin à te proposer.",
            ["DialogueId"] = 80240311,
            ["GUID"] = "C8DF8A06",
            ["NextDialogue"] = 80240312,
            ["SpeakNpcId"] = 790085,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF8A06",
            },
        [80240312] = {
            ["Content"] = "我就不坐了，有点急事。",
            ["ContentFR"] = "Non merci, je ne vais pas rester. J’ai quelque chose d’urgent.",
            ["DialogueId"] = 80240312,
            ["GUID"] = "C8DF8A30",
            ["NextDialogue"] = 80240313,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF8A30",
            },
        [80240313] = {
            ["Content"] = "叔，跟你打听个事儿。你……你认不认识在工造局当值的苏止？",
            ["ContentFR"] = "Dites, j’aurais une question. Vous... vous connaîtriez quelqu’un nommé Su Zhi ? Il travaille au Bureau des Arts Mécaniques.",
            ["DialogueId"] = 80240313,
            ["GUID"] = "C8DF8A5A",
            ["NextDialogue"] = 80240314,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF8A5A",
            },
        [80240314] = {
            ["Content"] = "你知道苏止他们家最近是怎么了？我刚刚去敲门，好像没人在家。他们是搬家了吗？",
            ["ContentFR"] = "Vous savez ce qui se passe chez sa famille en ce moment ? Je viens de frapper chez eux, mais personne n’a répondu. Ils ont déménagé ?",
            ["DialogueId"] = 80240314,
            ["GUID"] = "C8DF8A84",
            ["NextDialogue"] = 80240315,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF8A84",
            },
        [80240315] = {
            ["Content"] = "搬家？哈哈，也难怪你会这么想。在回答你的问题之前，先听我讲个故事吧。",
            ["ContentFR"] = "Déménagé ? Haha... je comprends pourquoi tu pourrais le croire. Mais avant de répondre à ta question, laisse-moi te raconter une histoire.",
            ["DialogueId"] = 80240315,
            ["GUID"] = "C8DF8AAE",
            ["NextDialogue"] = 80240316,
            ["SpeakNpcId"] = 790085,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF8AAE",
            },
        [80240316] = {
            ["Content"] = "我没时间听故事……抱歉啦大叔。",
            ["ContentFR"] = "Je n’ai pas vraiment le temps d’écouter des histoires... désolée, maître artisan.",
            ["DialogueId"] = 80240316,
            ["GUID"] = "C8DF8AD8",
            ["NextDialogue"] = 80240317,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF8AD8",
            },
        [80240317] = {
            ["Content"] = "别急着走。说不定你要找的答案就在这故事里呢。",
            ["ContentFR"] = "Ne pars pas si vite. Peut-être que la réponse que tu cherches se trouve justement dans cette histoire.",
            ["DialogueId"] = 80240317,
            ["GUID"] = "C8DF8B02",
            ["NextDialogue"] = 80240318,
            ["SpeakNpcId"] = 790085,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF8B02",
            },
        [80240318] = {
            ["Content"] = "……好吧！那你快点说，好不容易回来一趟，我真的赶时间。",
            ["ContentFR"] = "... Bon, d’accord ! Mais faites vite. Ce n’était pas simple de revenir jusqu’ici, et je suis vraiment pressée.",
            ["DialogueId"] = 80240318,
            ["GUID"] = "C8DF8B2C",
            ["NextDialogue"] = 80240319,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF8B2C",
            },
        [80240319] = {
            ["Content"] = "好好，小丫头性子真急。心急吃不到热豆腐哟。",
            ["ContentFR"] = "Très bien, très bien. Quelle impatience chez cette petite. Tu connais le dicton : la précipitation ne fait pas cuire les haricots plus vite.",
            ["DialogueId"] = 80240319,
            ["GUID"] = "C8DF8B56",
            ["NextDialogue"] = 80240320,
            ["SpeakNpcId"] = 790085,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF8B56",
            },
        [80240320] = {
            ["Content"] = "曾经有一对夫妇，他们对女儿严加管教，结果起了反效果。某一天女儿与他们大吵一架后，离开了家。",
            ["ContentFR"] = "Il était une fois un couple qui élevait leur fille avec une discipline très stricte. Mais cela produisit l’effet inverse. Un jour, après une violente dispute, la fille quitta la maison.",
            ["DialogueId"] = 80240320,
            ["GUID"] = "C8DF8B80",
            ["NextDialogue"] = 80240321,
            ["SpeakNpcId"] = 790085,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF8B80",
            },
        [80240321] = {
            ["Content"] = "起初，这对夫妇还气她固执，觉得女儿迟早会后悔的。",
            ["ContentFR"] = "Au début, les parents étaient furieux de son entêtement. Ils pensaient qu’elle finirait tôt ou tard par regretter.",
            ["DialogueId"] = 80240321,
            ["GUID"] = "C8DF8BAA",
            ["NextDialogue"] = 80240322,
            ["SpeakNpcId"] = 790085,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF8BAA",
            },
        [80240322] = {
            ["Content"] = "有一天，他们在收拾女儿旧房间时，找到了一只陈旧的机傀。女儿小时候不爱睡觉，父母想尽办法，做出了这只机傀。",
            ["ContentFR"] = "Un jour, en rangeant l’ancienne chambre de leur fille, ils trouvèrent une vieille méchapoupée. Quand elle était petite, elle refusait toujours d’aller dormir, alors ses parents avaient tout essayé pour fabriquer cette petite machine.",
            ["DialogueId"] = 80240322,
            ["GUID"] = "C8DF8BD4",
            ["NextDialogue"] = 80240323,
            ["SpeakNpcId"] = 790085,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF8BD4",
            },
        [80240323] = {
            ["Content"] = "它生来为拥抱存在，柔软的胸腹只有一颗恒温核心。说是机傀，却没有任何攻击性。",
            ["ContentFR"] = "Elle était faite pour être serrée contre soi. Son ventre moelleux ne contenait qu’un cœur thermique à température constante. On l’appelait méchapoupée, mais elle n’avait rien de dangereux.",
            ["DialogueId"] = 80240323,
            ["GUID"] = "C8DF8BFE",
            ["NextDialogue"] = 80240324,
            ["SpeakNpcId"] = 790085,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF8BFE",
            },
        [80240324] = {
            ["Content"] = "时间在它的身上留下灰尘，也留下伤痕，它脏了、旧了，被夫妇和女儿遗忘了。",
            ["ContentFR"] = "Le temps avait laissé sur elle poussière et cicatrices. Elle était sale, usée... oubliée par les parents comme par leur fille.",
            ["DialogueId"] = 80240324,
            ["GUID"] = "C8DF8C28",
            ["NextDialogue"] = 80240325,
            ["SpeakNpcId"] = 790085,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF8C28",
            },
        [80240325] = {
            ["Content"] = "面对这无害的机傀，这对夫妇想了很多，也想了很久。",
            ["ContentFR"] = "En regardant cette petite machine inoffensive, les parents réfléchirent longuement.",
            ["DialogueId"] = 80240325,
            ["GUID"] = "C8DF8C52",
            ["NextDialogue"] = 80240326,
            ["SpeakNpcId"] = 790085,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF8C52",
            },
        [80240326] = {
            ["Content"] = "他们后悔了。",
            ["ContentFR"] = "Ils commencèrent à regretter.",
            ["DialogueId"] = 80240326,
            ["GUID"] = "C8DF8C7C",
            ["NextDialogue"] = 80240327,
            ["SpeakNpcId"] = 790085,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF8C7C",
            },
        [80240327] = {
            ["Content"] = "可已经太迟了，他们对女儿说了太多冷酷的话，不知道如何挽回这段关系。",
            ["ContentFR"] = "Mais il était déjà trop tard. Ils avaient prononcé trop de paroles cruelles, et ne savaient plus comment réparer leur relation avec leur fille.",
            ["DialogueId"] = 80240327,
            ["GUID"] = "C8DF8CA6",
            ["NextDialogue"] = 80240328,
            ["SpeakNpcId"] = 790085,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF8CA6",
            },
        [80240328] = {
            ["Content"] = "……我猜这故事结局应该挺圆满吧，离家出走的女儿最后肯定回来了。",
            ["ContentFR"] = "... Je suppose que l’histoire se termine bien ? La fille qui était partie finit sûrement par rentrer chez elle, non ?",
            ["DialogueId"] = 80240328,
            ["GUID"] = "C8DF8CD0",
            ["NextDialogue"] = 80240329,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF8CD0",
            },
        [80240329] = {
            ["Content"] = "我不是满口大道理的夫子，但故事到这里还没结束。",
            ["ContentFR"] = "Je ne suis pas un maître moraliste, mais l’histoire ne s’arrête pas là.",
            ["DialogueId"] = 80240329,
            ["GUID"] = "C8DF8CFA",
            ["NextDialogue"] = 80240330,
            ["SpeakNpcId"] = 790085,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF8CFA",
            },
        [80240330] = {
            ["Content"] = "这对夫妇又制作了许多机傀，在夹层里放上他们一字一字斟酌写下的信，把它们托给了一位来往于山外山的商人。",
            ["ContentFR"] = "Le couple fabriqua encore de nombreuses méchapoupées. Dans la doublure de chacune d’elles, ils glissèrent une lettre écrite mot à mot avec le plus grand soin. Puis ils les confièrent à un marchand qui faisait souvent la route vers les Pics Extérieurs.",
            ["DialogueId"] = 80240330,
            ["GUID"] = "C8DF8D24",
            ["NextDialogue"] = 80240331,
            ["SpeakNpcId"] = 790085,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF8D24",
            },
        [80240331] = {
            ["Content"] = "……难道说……",
            ["ContentFR"] = "... Attendez... vous voulez dire...",
            ["DialogueId"] = 80240331,
            ["GUID"] = "C8DF8D4E",
            ["NextDialogue"] = 80240332,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF8D4E",
            },
        [80240332] = {
            ["Content"] = "我也问过他们，为什么不直接让商人带话，这不是方便多了？",
            ["ContentFR"] = "Je leur ai demandé pourquoi ils ne demandaient pas simplement au marchand de transmettre leur message. Ce serait bien plus simple.",
            ["DialogueId"] = 80240332,
            ["GUID"] = "C8DF8D78",
            ["NextDialogue"] = 80240333,
            ["SpeakNpcId"] = 790085,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF8D78",
            },
        [80240333] = {
            ["Content"] = "他们犹豫了很久，告诉我，他们害怕你没有原谅他们，不愿意回来，也害怕再次被你的话语刺伤，不敢直接托人告诉你。",
            ["ContentFR"] = "Ils ont hésité longtemps avant de répondre. Ils avaient peur que tu ne leur aies pas pardonné. Peur que tu refuses de rentrer. Peur aussi que tes paroles ne les blessent une nouvelle fois... alors ils n’osaient pas envoyer un message directement.",
            ["DialogueId"] = 80240333,
            ["GUID"] = "C8DF8DA2",
            ["NextDialogue"] = 80240334,
            ["SpeakNpcId"] = 790085,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF8DA2",
            },
        [80240334] = {
            ["Content"] = "他们做好了准备，哪怕你一辈子都不会回家、更不会发现夹层里的信，他们也会一直写下去的。",
            ["ContentFR"] = "Ils s’étaient préparés à continuer ainsi toute leur vie. Même si tu ne revenais jamais... même si tu ne découvrais jamais les lettres cachées dans les jouets.",
            ["DialogueId"] = 80240334,
            ["GUID"] = "C8DF8DCC",
            ["NextDialogue"] = 80240335,
            ["SpeakNpcId"] = 790085,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF8DCC",
            },
        [80240335] = {
            ["Content"] = "幸好啊……第四年，你终于发现了。",
            ["ContentFR"] = "Heureusement... la quatrième année, tu as fini par en trouver une.",
            ["DialogueId"] = 80240335,
            ["GUID"] = "C8DF8DF6",
            ["NextDialogue"] = 80240336,
            ["SpeakNpcId"] = 790085,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF8DF6",
            },
        [80240336] = {
            ["Content"] = "怎么哭了？唉，果然还是个小丫头。先收收眼泪，免得看不清字。",
            ["ContentFR"] = "Pourquoi tu pleures ? Ah... tu restes une enfant après tout. Essuie un peu tes larmes, sinon tu ne verras plus les mots.",
            ["DialogueId"] = 80240336,
            ["GUID"] = "C8DF8E20",
            ["NextDialogue"] = 80240337,
            ["SpeakNpcId"] = 790085,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF8E20",
            },
        [80240337] = {
            ["Content"] = "我从来、从来没有想过，要拆开看看。",
            ["ContentFR"] = "Je n’ai jamais... jamais pensé à regarder à l’intérieur.",
            ["DialogueId"] = 80240337,
            ["GUID"] = "C8DF8E4A",
            ["NextDialogue"] = 80240338,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF8E4A",
            },
        [80240338] = {
            ["Content"] = "我一直以为……爸妈肯定不想见到我。我也很害怕回家，害怕被爸妈再次赶走，害怕他们冷冰冰地看着我，说我不是他们的女儿……",
            ["ContentFR"] = "J’ai toujours cru... que papa et maman ne voulaient plus me voir. J’avais tellement peur de rentrer. Peur qu’ils me chassent encore... peur qu’ils me regardent froidement et disent que je ne suis plus leur fille...",
            ["DialogueId"] = 80240338,
            ["GUID"] = "C8DF8E74",
            ["NextDialogue"] = 80240339,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF8E74",
            },
        [80240339] = {
            ["Content"] = "……原来爸妈也是这么想的。",
            ["ContentFR"] = "... En fait, eux aussi pensaient la même chose.",
            ["DialogueId"] = 80240339,
            ["GUID"] = "C8DF8E9E",
            ["NextDialogue"] = 80240340,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF8E9E",
            },
        [80240340] = {
            ["Content"] = "如果我能早点发现，如果我能早点回来……",
            ["ContentFR"] = "Si seulement je l’avais découvert plus tôt... si seulement j’étais revenue plus tôt...",
            ["DialogueId"] = 80240340,
            ["GUID"] = "C8DF8EC8",
            ["NextDialogue"] = 80240341,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF8EC8",
            },
        [80240341] = {
            ["Content"] = "前些年时局不好，就算你有心也无力，这也怪不得你。现在就看看吧。",
            ["ContentFR"] = "Ces dernières années, la situation était instable. Même si tu l’avais voulu, tu n’aurais peut-être pas pu revenir. Ne t’en veux pas. Vas-y, lis la lettre.",
            ["DialogueId"] = 80240341,
            ["GUID"] = "C8DF8EF2",
            ["NextDialogue"] = 80240342,
            ["SpeakNpcId"] = 790085,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF8EF2",
            },
        [80240342] = {
            ["Content"] = "……好，我看看。",
            ["ContentFR"] = "... D’accord. Je vais regarder.",
            ["DialogueId"] = 80240342,
            ["GUID"] = "C8DF8F1C",
            ["NextDialogue"] = 80240343,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF8F1C",
            },
        [80240343] = {
            ["Content"] = "“岁末将至。因你不在，家中未办年事，一切从简。不晓得外面有多好，能叫你有家不回，一走就是一年，年夜饭也不回来吃。”",
            ["ContentFR"] = "« La fin de l’année approche. Comme tu n’es pas là, nous n’avons pas préparé les festivités. Tout est resté très simple. Je ne sais pas ce qu’il peut bien y avoir dehors pour t’empêcher de rentrer chez toi. Voilà déjà un an que tu es partie... et tu n’es même pas revenue pour le dîner du Nouvel An. »",
            ["DialogueId"] = 80240343,
            ["GUID"] = "C8DF8F46",
            ["NextDialogue"] = 80240344,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF8F46",
            },
        [80240344] = {
            ["Content"] = "“……也不知道报个平安，叫父母担心。”",
            ["ContentFR"] = "« ... Tu n’as même pas envoyé un mot pour dire que tu allais bien. Tu laisses tes parents s’inquiéter. »",
            ["DialogueId"] = 80240344,
            ["GUID"] = "C8DF8F70",
            ["NextDialogue"] = 80240345,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF8F70",
            },
        [80240345] = {
            ["Content"] = "接着看吧，每个玩偶里面都有。",
            ["ContentFR"] = "Continue à lire. Chaque jouet en contient une.",
            ["DialogueId"] = 80240345,
            ["GUID"] = "C8DF8F9A",
            ["NextDialogue"] = 80240346,
            ["SpeakNpcId"] = 790085,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF8F9A",
            },
        [80240346] = {
            ["Content"] = "“我的女儿，这是你离家的第三个年头。”",
            ["ContentFR"] = "« Ma fille. Cela fait maintenant trois ans que tu es partie. »",
            ["DialogueId"] = 80240346,
            ["GUID"] = "C8DF8FC4",
            ["NextDialogue"] = 80240347,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF8FC4",
            },
        [80240347] = {
            ["Content"] = "“……你妈妈制作机枢，划伤了手。我问她在想什么，她忽地落下泪来，说女儿钻研机枢以来，一定受了很多伤，她身为母亲，此前却一直不懂女儿的辛苦。”",
            ["ContentFR"] = "« ... Ta mère s’est coupée la main en fabriquant un mécanisme. Quand je lui ai demandé à quoi elle pensait, elle s’est mise à pleurer. Elle disait que depuis que tu étudies l’art des méchapoupées, tu as sûrement dû te blesser souvent. En tant que mère, elle n’avait jamais compris les difficultés que tu traversais. »",
            ["DialogueId"] = 80240347,
            ["GUID"] = "C8DF8FEE",
            ["NextDialogue"] = 80240348,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF8FEE",
            },
        [80240348] = {
            ["Content"] = "“我们没有在你最需要帮助的时候，撑起你的天地，如今有心作为，你却已经不在了……盼望吾女得见此信，早日归家。”",
            ["ContentFR"] = "« Nous n’avons pas su te soutenir quand tu en avais le plus besoin. Aujourd’hui nous voudrions réparer cela, mais tu n’es plus là... Puisses-tu lire cette lettre et rentrer bientôt à la maison. »",
            ["DialogueId"] = 80240348,
            ["GUID"] = "C8DF9018",
            ["NextDialogue"] = 80240349,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF9018",
            },
        [80240349] = {
            ["Content"] = "“一晃四年过去，我女儿年已十八，定是出落得亭亭玉立……母亲真想见见你，又怕你已经变了模样，叫母亲认不出了。”",
            ["ContentFR"] = "« Quatre années ont passé en un clin d’œil. Ma fille a maintenant dix-huit ans... elle doit être devenue une belle jeune femme. Ta mère aimerait tant te revoir... mais elle craint que tu aies tellement changé qu’elle ne te reconnaisse plus. »",
            ["DialogueId"] = 80240349,
            ["GUID"] = "C8DF9042",
            ["NextDialogue"] = 80240350,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF9042",
            },
        [80240350] = {
            ["Content"] = "“听闻应天尉捕下几名飘零人……最近时局动荡，母亲寝食难安，唯恐你也沦落囚狱……别又忘记吃饭，你小时候就这样，总要母亲……”",
            ["ContentFR"] = "« Nous avons entendu dire que des Magistrats de Yingtian ont capturé plusieurs Vagabonds... Les temps sont troublés, ta mère ne dort plus. Elle a peur que toi aussi tu finisses emprisonnée... Et n’oublie pas de manger. Quand tu étais petite, c’était toujours ta mère qui devait... »",
            ["DialogueId"] = 80240350,
            ["GUID"] = "C8DF906C",
            ["NextDialogue"] = 80240351,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF906C",
            },
        [80240351] = {
            ["Content"] = "“小苏，爸妈想你了……如果你还愿意回来，爸妈……一直在等你。”",
            ["ContentFR"] = "« Su... papa et maman pensent à toi. Si tu es encore prête à rentrer... nous t’attendrons toujours. »",
            ["DialogueId"] = 80240351,
            ["GUID"] = "C8DF9096",
            ["NextDialogue"] = 80240352,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF9096",
            },
        [80240352] = {
            ["Content"] = "爸爸，妈妈……我也……想你们……",
            ["ContentFR"] = "Papa... maman... moi aussi... vous me manquez...",
            ["DialogueId"] = 80240352,
            ["GUID"] = "C8DF90C0",
            ["NextDialogue"] = 80240353,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF90C0",
            },
        [80240353] = {
            ["Content"] = "大叔，我爸妈、不是，那对夫妇……现在、现在怎么样了？",
            ["ContentFR"] = "Maître artisan... mes parents— enfin... ce couple... comment vont-ils... maintenant ?",
            ["DialogueId"] = 80240353,
            ["GUID"] = "C8DF90EA",
            ["NextDialogue"] = 80240354,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF90EA",
            },
        [80240354] = {
            ["Content"] = "那对夫妇年初生了一场大病，现在已经……",
            ["ContentFR"] = "Ce couple est tombé gravement malade au début de l’année... et maintenant...",
            ["DialogueId"] = 80240354,
            ["GUID"] = "C8DF9114",
            ["NextDialogue"] = 80240355,
            ["SpeakNpcId"] = 790085,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF9114",
            },
        [80240355] = {
            ["Content"] = "……",
            ["ContentFR"] = "...",
            ["DialogueId"] = 80240355,
            ["GUID"] = "C8DF913E",
            ["NextDialogue"] = 80240356,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF913E",
            },
        [80240356] = {
            ["Content"] = "泽生阁药师妙手回春，现在已经痊愈了。",
            ["ContentFR"] = "Les guérisseurs de la Pharmacie Zesheng ont fait des miracles. Ils sont complètement rétablis.",
            ["DialogueId"] = 80240356,
            ["GUID"] = "C8DF9168",
            ["NextDialogue"] = 80240357,
            ["SpeakNpcId"] = 790085,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF9168",
            },
        [80240357] = {
            ["Content"] = "……啊？",
            ["ContentFR"] = "... Hein ?",
            ["DialogueId"] = 80240357,
            ["GUID"] = "C8DF9192",
            ["NextDialogue"] = 80240358,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF9192",
            },
        [80240358] = {
            ["Content"] = "哈哈，看你这样子，吓坏了吧？这么担心他们，想来心里也没少记挂。",
            ["ContentFR"] = "Haha ! Regarde ton visage. Tu as eu une sacrée frayeur, hein ? On voit bien que tu tiens encore beaucoup à eux.",
            ["DialogueId"] = 80240358,
            ["GUID"] = "C8DF91BC",
            ["NextDialogue"] = 80240359,
            ["SpeakNpcId"] = 790085,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF91BC",
            },
        [80240359] = {
            ["Content"] = "眉眼长相，身高体量，这些东西证明了我们的来处。我看见你第一眼，就知道你是他们的女儿。",
            ["ContentFR"] = "Les traits du visage, la silhouette... tout cela révèle d’où l’on vient. Dès que je t’ai vue, j’ai su que tu étais leur fille.",
            ["DialogueId"] = 80240359,
            ["GUID"] = "C8DF91E6",
            ["NextDialogue"] = 80240360,
            ["SpeakNpcId"] = 790085,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF91E6",
            },
        [80240360] = {
            ["Content"] = "你爹娘刚刚下工，恰好和你错开了时辰。现在，他们就在家里，准备着今年的信。",
            ["ContentFR"] = "Tes parents viennent justement de finir leur journée de travail. Vous vous êtes simplement manqués. À cette heure-ci, ils doivent déjà être à la maison... en train d’écrire la lettre de cette année.",
            ["DialogueId"] = 80240360,
            ["GUID"] = "C8DF9210",
            ["NextDialogue"] = 80240361,
            ["SpeakNpcId"] = 790085,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF9210",
            },
        [80240361] = {
            ["Content"] = "回去吧，苏乙。",
            ["ContentFR"] = "Rentre chez toi, Su Yi.",
            ["DialogueId"] = 80240361,
            ["GUID"] = "C8DF923A",
            ["NextDialogue"] = 80240362,
            ["SpeakNpcId"] = 790085,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF923A",
            },
        [80240362] = {
            ["Content"] = "你看，亲情嘛，就是这样斩也斩不断的东西啊。",
            ["ContentFR"] = "Tu vois... les liens du sang sont ainsi. Impossible de les trancher.",
            ["DialogueId"] = 80240362,
            ["GUID"] = "C8DF9264",
            ["NextDialogue"] = 80240363,
            ["SpeakNpcId"] = 790085,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF9264",
            },
        [80240363] = {
            ["Content"] = "我那犟脾气的哥哥在山外山一待就是十几年，不知道现今过得如何，也是时候走动走动了……",
            ["ContentFR"] = "Mon frère têtu vit aux Pics Extérieurs depuis plus de dix ans... je me demande comment il va. Il est peut-être temps que j’aille lui rendre visite...",
            ["DialogueId"] = 80240363,
            ["GUID"] = "C8DF928E",
            ["NextDialogue"] = 80240364,
            ["SpeakNpcId"] = 790085,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF928E",
            },
        [80240364] = {
            ["Content"] = "……小苏？是你吗？",
            ["ContentFR"] = "... Su ? Est-ce... toi ?",
            ["DialogueId"] = 80240364,
            ["GUID"] = "C8DF92B8",
            ["NextDialogue"] = 80240365,
            ["SpeakNpcId"] = 790084,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF92B8",
            },
        [80240365] = {
            ["Content"] = "……是我！",
            ["ContentFR"] = "... Oui !",
            ["DialogueId"] = 80240365,
            ["GUID"] = "C8DF92E2",
            ["NextDialogue"] = 80240366,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF92E2",
            },
        [80240366] = {
            ["Content"] = "爸，妈，我回来了！",
            ["ContentFR"] = "Papa... maman... je suis rentrée !",
            ["DialogueId"] = 80240366,
            ["GUID"] = "C8DF930C",
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF930C",
            },
        [88888801] = {
            ["DialogueId"] = 88888801,
            ["DialoguePanelType"] = "None",
            ["Duration"] = 5,
            ["GUID"] = "DE8616EA",
            ["Scripts"] = "SEQ{SetRotation{SetRotationDescription{\"888888:n(0)\"}},PlayAnimation{ActorId{0},AnimationId{\"Cat_Interactive01\"}}}",
            ["SpeakNpcId"] = 888888,
            ["bAllowClickSkipScript"] = false,
            },
        [90000001] = {
            ["Content"] = "年轻人，你之前记挂着的那个好东西，老朽瞧着材料已经齐全了。",
            ["ContentFR"] = "Jeune {性别:ami|amie}, je vois que tu as enfin réuni tous les matériaux pour l’ouvrage dont tu rêvais tant.",
            ["DialogueId"] = 90000001,
            ["Duration"] = 3,
            ["GUID"] = "E14E392A",
            ["SpeakNpcId"] = 200024,
            ["SpeakNpcName"] = "UI_Npc_Name_Tiejiang",
            },
        [90000011] = {
            ["Content"] = "强大的刻印！",
            ["ContentFR"] = "Un sceau puissant !",
            ["DialogueId"] = 90000011,
            ["GUID"] = "E14E3ACE",
            },
        [90000012] = {
            ["Content"] = "强大的宝物！",
            ["ContentFR"] = "Une relique puissante !",
            ["DialogueId"] = 90000012,
            ["GUID"] = "E14E3AF8",
            },
        [90000013] = {
            ["Content"] = "我全都要！",
            ["ContentFR"] = "Je les veux tous !",
            ["DialogueId"] = 90000013,
            ["GUID"] = "E14E3B22",
            },
        [90000021] = {
            ["Content"] = "选择一个中稀有度的刻印",
            ["ContentFR"] = "Obtenir un sceau de rareté moyenne de votre choix",
            ["DialogueId"] = 90000021,
            ["GUID"] = "E14E3C72",
            },
        [90000022] = {
            ["Content"] = "随机获得一个高稀有度的刻印",
            ["ContentFR"] = "Obtenir un sceau de haute rareté aléatoire",
            ["DialogueId"] = 90000022,
            ["GUID"] = "E14E3C9C",
            },
        [90000031] = {
            ["Content"] = "随机获得两个低稀有度的宝物",
            ["ContentFR"] = "Obtenir deux reliques de faible rareté aléatoires",
            ["DialogueId"] = 90000031,
            ["GUID"] = "E14E3E16",
            },
        [90000032] = {
            ["Content"] = "随机获得一个任意稀有度的宝物",
            ["ContentFR"] = "Obtenir une relique d’une rareté aléatoire",
            ["DialogueId"] = 90000032,
            ["GUID"] = "E14E3E40",
            },
        [90000041] = {
            ["Content"] = "你什么也没有得到",
            ["ContentFR"] = "Tu n’as rien obtenu",
            ["DialogueId"] = 90000041,
            ["GUID"] = "E14E3FBA",
            },
        [90000051] = {
            ["Content"] = "伟大的刻印赠礼人啊，我需要至高无上的您的帮助！",
            ["ContentFR"] = "Ô Grand Donateur des Sceaux, j’implore votre puissance suprême !",
            ["DialogueId"] = 90000051,
            ["GUID"] = "E14E415E",
            },
        [90000052] = {
            ["Content"] = "选择一个低稀有度的刻印",
            ["ContentFR"] = "Obtenir un sceau de faible rareté de votre choix",
            ["DialogueId"] = 90000052,
            ["GUID"] = "E14E4188",
            },
        [90000053] = {
            ["Content"] = "随机获得一个中稀有度的刻印",
            ["ContentFR"] = "Obtenir un sceau de rareté moyenne aléatoire",
            ["DialogueId"] = 90000053,
            ["GUID"] = "E14E41B2",
            },
        [90000061] = {
            ["Content"] = "伟大的宝物赠礼人啊，我需要至高无上的您的帮助！",
            ["ContentFR"] = "Ô Grand Donateur des Reliques, j’implore votre puissance suprême !",
            ["DialogueId"] = 90000061,
            ["GUID"] = "E14E4302",
            },
        [90000062] = {
            ["Content"] = "随机获得一个低稀有度的宝物",
            ["ContentFR"] = "Obtenir une relique de faible rareté aléatoire",
            ["DialogueId"] = 90000062,
            ["GUID"] = "E14E432C",
            },
        [90010101] = {
            ["Content"] = "嘿咻、嘿咻……",
            ["ContentFR"] = "Allez... encore un coup... Pas question... de s’arrêter... pas encore !",
            ["DialogueId"] = 90010101,
            ["Duration"] = 3,
            ["GUID"] = "E154B232",
            ["SpeakNpcId"] = 900001,
            ["VoiceName"] = "voice/$Locale$/char/Bai/vo_forge_05",
            },
        [90010201] = {
            ["Camera"] = "192.657425,-208.698975,78.959908,0.000142,-5.798523,129.981186,35.0,250.0,false,DoNotOverride,2.8",
            ["Content"] = "最近有没有找到什么好东西？给老朽看看，说不定能锻造出一把很特别的武器！",
            ["ContentFR"] = "As-tu déniché quelque chose de précieux, dernièrement ? Montre-moi ça ! Qui sait... je pourrais peut-être en tirer une arme exceptionnelle !",
            ["DialogueId"] = 90010201,
            ["GUID"] = "E154C29A",
            ["SpeakNpcId"] = 900001,
            ["VoiceName"] = "voice/$Locale$/char/Bai/vo_forge_r02",
            },
        [90010301] = {
            ["Camera"] = "192.657425,-208.698975,78.959908,0.000142,-5.798523,129.981186,35.0,250.0,false,DoNotOverride,2.8",
            ["Content"] = "是老朽的好友，虽然看起来个子小，但是力气可不小，老朽便让它帮忙给炉火鼓风。",
            ["ContentFR"] = "C’est mon ami. Il a beau être petit, il est sacrément costaud — il attise le feu de la forge pour moi.",
            ["DialogueId"] = 90010301,
            ["GUID"] = "E154D302",
            ["SpeakNpcId"] = 900001,
            },
        [90020101] = {
            ["Content"] = "早上好……",
            ["ContentFR"] = "<I>Bâille...</> Bonjour... Hein ? Ah, il est trop tard pour dire bonjour ? Euh... bonsoir, alors ?",
            ["DialogueId"] = 90020101,
            ["Duration"] = 3,
            ["GUID"] = "E15B1AD2",
            ["SpeakNpcId"] = 900002,
            ["VoiceName"] = "voice/$Locale$/char/Bai/vo_shop_r03",
            },
        [90020201] = {
            ["Content"] = "啊！我、我才没有偷懒……咳！有什么想买的吗？",
            ["ContentFR"] = "Hein ?! J-Je ne faisais pas la sieste... Hum hum ! Tu veux acheter quelque chose ?",
            ["DialogueId"] = 90020201,
            ["GUID"] = "E15B2B3A",
            ["SpeakNpcId"] = 900002,
            ["TalkActionId"] = {
                [1] = "900002:Shangdian_Write_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Bai/vo_shop_r01",
            },
        [90020301] = {
            ["Content"] = "聊点别的",
            ["ContentFR"] = "<I>Parlons d’autre chose.</>",
            ["DialogueId"] = 90020301,
            ["GUID"] = "E15B3BA2",
            },
        [90020302] = {
            ["Content"] = "再见",
            ["ContentFR"] = "<I>À bientôt.</>",
            ["DialogueId"] = 90020302,
            ["GUID"] = "E15B3BCC",
            },
        [90030000] = {
            ["Content"] = "{性别：他|她}从来都不是一只甘愿困在笼中的鸟。我知道的，总有一天{性别：他|她}会离开那座岛，飞向更远的天空。但我不知道的是，这对我们来说究竟是幸运还是不幸。",
            ["ContentFR"] = "{性别:Il n’a jamais été fait pour vivre en cage. J’ai toujours su qu’un jour, il quitterait l’île pour s’envoler vers le ciel. Ce que je n’ai jamais su, c’est si ce serait une bénédiction… ou une malédiction, pour nous.|Elle n’a jamais été faite pour vivre en cage. J’ai toujours su qu’un jour, elle quitterait l’île pour s’envoler vers le ciel. Ce que je n’ai jamais su, c’est si ce serait une bénédiction… ou une malédiction, pour nous.}",
            ["DialogueId"] = 90030000,
            ["GUID"] = "E15B3BCB",
            ["SpeakNpcId"] = 81101,
            ["VoiceName"] = "voice/$Locale$/char/Heitao/vo_idle",
            },
        [90030001] = {
            ["Content"] = "你回来了。今天打算做什么？还是在家休息？",
            ["ContentFR"] = "Tu es de retour. Qu’est-ce que tu comptes faire aujourd’hui ? Te reposer à la maison, peut-être ?",
            ["DialogueId"] = 90030001,
            ["GUID"] = "E161730A",
            ["LookAt"] = {
                [1] = "81101:n(0)",
                [2] = "0:n(81101)",
                },
            ["NextOptions"] = {
                [1] = 900300011,
                [2] = 900300013,
                [3] = 900300014,
                [4] = 900300015,
                [5] = 900300016,
                [6] = 900300018,
                },
            ["RandomOptionNum"] = 3,
            ["SpeakNpcId"] = 81101,
            ["TalkActionId"] = {
                [1] = "81101:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Heitao/vo_welcome",
            ["bForbidSkipOptions"] = true,
            },
        [90030002] = {
            ["Content"] = "聊点别的",
            ["ContentFR"] = "<I>Parlons d’autre chose.</>",
            ["DialogueId"] = 90030002,
            ["GUID"] = "90030002.0",
            ["NextDialogue"] = 90030001,
            },
        [90030003] = {
            ["Content"] = "再见",
            ["ContentFR"] = "<I>À bientôt.</>",
            ["DialogueId"] = 90030003,
            ["GUID"] = "90030003.0",
            },
        [90030101] = {
            ["Content"] = "愿望？我……没有什么特别的愿望。每个早上都看见你笑着，就足够了。",
            ["ContentFR"] = "Un souhait ? Honnêtement... non, rien de particulier. Tant que je peux voir ton sourire chaque matin, ça me suffit.",
            ["DialogueId"] = 90030101,
            ["GUID"] = "E1618372",
            ["LookAt"] = {
                [1] = "81101:n(0)",
                [2] = "0:n(81101)",
                },
            ["NextDialogue"] = 90030103,
            ["SpeakNpcId"] = 81101,
            ["TalkActionId"] = {
                [1] = "81101:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Heitao/vo_topic_02_1",
            },
        [90030103] = {
            ["Content"] = "好，我会做到。",
            ["ContentFR"] = "Alors je te le promets, je vais tout faire pour que ça continue.",
            ["DialogueId"] = 90030103,
            ["GUID"] = "E16183C6",
            ["NextDialogue"] = 90030104,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "81101:Explain02_End",
                },
            },
        [90030104] = {
            ["Content"] = "也不用勉强自己。如果你觉得不开心，就来靠着我说会儿话吧。或者，如果你不想说的话，我们就一起安静地待一会儿。",
            ["ContentFR"] = "Mais ne te force pas. Si tu te sens mal, viens simplement me parler un moment. Ou si tu préfères garder le silence, on pourra rester là, ensemble, tranquillement.",
            ["DialogueId"] = 90030104,
            ["GUID"] = "E16183F0",
            ["NextOptions"] = {
                [1] = 90030002,
                [2] = 90030003,
                },
            ["SpeakNpcId"] = 81101,
            ["TalkActionId"] = {
                [1] = "81101:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Heitao/vo_topic_02_2",
            ["bForbidSkipOptions"] = true,
            },
        [90030301] = {
            ["Content"] = "和净界岛不一样，这座城的每一天都在下雪。不过，还好你有这么一个温暖的住处。和我们在净界岛上的破房子相比，这个地方算得上奢侈了。",
            ["ContentFR"] = "C’est pas comme sur l’Île du Purgatoire, ici il neige tous les jours. Mais heureusement, tu as un toit bien chaud. Comparé à notre vieille cabane sur l’île, ce logement, c’est presque du luxe.",
            ["DialogueId"] = 90030301,
            ["GUID"] = "E161A442",
            ["LookAt"] = {
                [1] = "81101:n(0)",
                [2] = "0:n(81101)",
                },
            ["NextDialogue"] = 90030303,
            ["SpeakNpcId"] = 81101,
            ["TalkActionId"] = {
                [1] = "81101:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Heitao/vo_topic_03_1",
            },
        [90030303] = {
            ["Content"] = "可我还是觉得有点冷。",
            ["ContentFR"] = "Pourtant, j’ai toujours un peu froid.",
            ["DialogueId"] = 90030303,
            ["GUID"] = "E161A443",
            ["NextDialogue"] = 90030304,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "81101:Think_End",
                },
            },
        [90030304] = {
            ["Content"] = "以前每到冬天，你的手都会变得很凉……来，手给我，我帮你暖一暖。",
            ["ContentFR"] = "Je me souviens, en hiver, tes mains étaient toujours gelées… Viens, donne-moi tes mains, je vais te les réchauffer.",
            ["DialogueId"] = 90030304,
            ["GUID"] = "E161A46C",
            ["NextOptions"] = {
                [1] = 90030002,
                [2] = 90030003,
                },
            ["SpeakNpcId"] = 81101,
            ["VoiceName"] = "voice/$Locale$/char/Heitao/vo_topic_03_2",
            ["bForbidSkipOptions"] = true,
            },
        [90030401] = {
            ["Content"] = "为什么呢……我也不知道。不妨就认为这是一个美好的梦吧——就当作我还在你身边，像从前一样。",
            ["ContentFR"] = "Ce que je fais ici... ? Je ne sais pas. Disons simplement que c’est un beau rêve, fais comme si j’étais encore à tes côtés, comme autrefois.",
            ["DialogueId"] = 90030401,
            ["GUID"] = "E161B4AA",
            ["LookAt"] = {
                [1] = "81101:n(0)",
                [2] = "0:n(81101)",
                },
            ["NextDialogue"] = 90030403,
            ["SpeakNpcId"] = 81101,
            ["TalkActionId"] = {
                [1] = "81101:Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Heitao/vo_topic_01_1",
            },
        [90030403] = {
            ["Content"] = "我想再次见到你。",
            ["ContentFR"] = "Je donnerais tout pour te revoir.",
            ["DialogueId"] = 90030403,
            ["GUID"] = "E161B4FE",
            ["NextDialogue"] = 90030404,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "81101:Talk02_End",
                },
            },
        [90030404] = {
            ["Content"] = "嗯，我也想，非常想……但愿有一天，我们能够真正重逢。",
            ["ContentFR"] = "Oui, moi aussi… plus que tout. Puissions-nous un jour nous retrouver… pour de vrai.",
            ["DialogueId"] = 90030404,
            ["GUID"] = "E161B528",
            ["NextOptions"] = {
                [1] = 90030002,
                [2] = 90030003,
                },
            ["SpeakNpcId"] = 81101,
            ["VoiceName"] = "voice/$Locale$/char/Heitao/vo_topic_01_2",
            ["bForbidSkipOptions"] = true,
            },
        [90030501] = {
            ["Content"] = "应该怎么说呢，那个地方像一座钢铁做的城市……不对，应该说更像牢狱吧。很小的时候，我是在那儿度过的。",
            ["ContentFR"] = "Comment dire... C’est une ville de métal, froide et impitoyable... Non, en fait, c’est plutôt une prison. C’est là que j’ai passé mon enfance.",
            ["DialogueId"] = 90030501,
            ["GUID"] = "E161C512",
            ["LookAt"] = {
                [1] = "81101:n(0)",
                [2] = "0:n(81101)",
                },
            ["NextDialogue"] = 90030503,
            ["SpeakNpcId"] = 81101,
            ["TalkActionId"] = {
                [1] = "81101:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Heitao/vo_topic_04_1",
            },
        [90030503] = {
            ["Content"] = "后来一个人带着我逃走了。被她一同带到净界岛的，还有你。只是关于她的事，我不能说更多了……抱歉。我答应过她不说。",
            ["ContentFR"] = "Plus tard, quelqu’un m’a aidée à m’échapper. Elle nous a emmenés, toi et moi, sur l’Île du Purgatoire. Mais à propos d’elle... je ne peux rien dire de plus. Désolée, je lui ai promis de garder le secret.",
            ["DialogueId"] = 90030503,
            ["GUID"] = "E161C566",
            ["NextDialogue"] = 90030504,
            ["SpeakNpcId"] = 81101,
            ["TalkActionId"] = {
                [1] = "81101:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Heitao/vo_topic_04_2",
            },
        [90030504] = {
            ["Content"] = "……在净界岛的日子是那么平静，我差点以为我们会一辈子这样生活下去。但那天，他们再次出现的时候，我才发觉我从未真正逃离那个牢狱。",
            ["ContentFR"] = "... Les jours passés sur l’Île du Purgatoire étaient si paisibles que j’ai cru qu’on pourrait y vivre toute notre vie. Jusqu’au jour où ils sont revenus. C’est là que j’ai compris que je n’avais jamais vraiment fui cette prison.",
            ["DialogueId"] = 90030504,
            ["GUID"] = "E161C590",
            ["NextOptions"] = {
                [1] = 90030002,
                [2] = 90030003,
                },
            ["SpeakNpcId"] = 81101,
            ["VoiceName"] = "voice/$Locale$/char/Heitao/vo_topic_04_3",
            ["bForbidSkipOptions"] = true,
            },
        [90030601] = {
            ["Content"] = "是有些吵闹，不过，我并不讨厌。你结识了许多新的朋友，这是好事，我为你高兴。",
            ["ContentFR"] = "C’est un peu animé, oui... mais ça ne me dérange pas. Tu t’es fait plein de nouveaux amis, et c’est une bonne chose. Je suis vraiment contente pour toi.",
            ["DialogueId"] = 90030601,
            ["GUID"] = "E161D57A",
            ["LookAt"] = {
                [1] = "81101:n(0)",
                [2] = "0:n(81101)",
                },
            ["NextDialogue"] = 90030603,
            ["SpeakNpcId"] = 81101,
            ["TalkActionId"] = {
                [1] = "81101:Sigh_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Heitao/vo_topic_05_1",
            },
        [90030603] = {
            ["Content"] = "这样一来，就算我不在你身边，你也不会觉得孤单了。",
            ["ContentFR"] = "{性别:Comme ça, même si je ne suis pas là… tu ne te sentiras plus seul.|Comme ça, même si je ne suis pas là… tu ne te sentiras plus seule. }",
            ["DialogueId"] = 90030603,
            ["GUID"] = "E161D5A4",
            ["NextOptions"] = {
                [1] = 90030002,
                [2] = 90030003,
                },
            ["SpeakNpcId"] = 81101,
            ["TalkActionId"] = {
                [1] = "81101:Sigh_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Heitao/vo_topic_05_2",
            ["bForbidSkipOptions"] = true,
            },
        [90030801] = {
            ["Content"] = "那就枕在我身上歇息一会儿吧，像从前那样。",
            ["ContentFR"] = "Alors repose-toi un peu, pose ta tête sur mes genoux... comme avant.",
            ["DialogueId"] = 90030801,
            ["GUID"] = "E161F64A",
            ["LookAt"] = {
                [1] = "81101:n(0)",
                [2] = "0:n(81101)",
                },
            ["NextOptions"] = {
                [1] = 90030002,
                [2] = 90030003,
                },
            ["SpeakNpcId"] = 81101,
            ["TalkActionId"] = {
                [1] = "81101:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Heitao/vo_topic_06_1",
            ["bForbidSkipOptions"] = true,
            },
        [90031001] = {
            ["Content"] = "松露小姐，你的……猪，我可以摸一摸吗？摸一下就好。请你帮我按住它，我怕它跑远了，小动物看到我总会跑得远远的。",
            ["ContentFR"] = "Mademoiselle Truffle, est-ce que je peux… toucher votre cochon ? Juste une fois, promis. Vous pourriez le tenir un peu, s’il vous plaît ? J’ai peur qu’il s’enfuie... Les petits animaux me fuient toujours.",
            ["DialogueId"] = 90031001,
            ["GUID"] = "E162171A",
            ["NextDialogue"] = 90031002,
            ["SpeakNpcId"] = 81101,
            ["VoiceName"] = "voice/$Locale$/char/Heitao/vo_companio_02_1",
            },
        [90031002] = {
            ["Content"] = "谢谢你……啊，暖暖的，毛茸茸的，真好啊……",
            ["ContentFR"] = "Merci... Ah... c’est tout chaud... et tout doux... C’est vraiment agréable...",
            ["DialogueId"] = 90031002,
            ["GUID"] = "E1621744",
            ["SpeakNpcId"] = 81101,
            ["VoiceName"] = "voice/$Locale$/char/Heitao/vo_companio_02_2",
            },
        [90031101] = {
            ["Content"] = "我不是军团的“零号”，更不是你手中随意拨弄的玩具。你可以离开，或者带着我的尸骸回去。",
            ["ContentFR"] = "Je ne suis pas le \"n° 0\" de la Légion. Et encore moins un jouet entre tes mains. Pars. Ou emmène mon cadavre, mais jamais je ne te suivrai vivante.",
            ["DialogueId"] = 90031101,
            ["GUID"] = "E1622782",
            ["SpeakNpcId"] = 81101,
            ["VoiceName"] = "voice/$Locale$/char/Heitao/vo_companio_03",
            },
        [90031201] = {
            ["Content"] = "听说你是位优秀的美食家，可以给我看看你的食谱吗？{nickname}总说你做的饭很好吃，听起来不像客套话，而是发自内心的夸奖。",
            ["ContentFR"] = "On dit que vous êtes un fin gourmet... Vous accepteriez de me montrer quelques-unes de vos recettes ? {nickname} ne tarit pas d’éloges sur votre cuisine et ça sonnait vrai, pas juste un compliment de courtoisie.",
            ["DialogueId"] = 90031201,
            ["GUID"] = "E16237EA",
            ["NextDialogue"] = 90031202,
            ["SpeakNpcId"] = 81101,
            ["VoiceName"] = "voice/$Locale$/char/Heitao/vo_companio_04_1",
            },
        [90031202] = {
            ["Content"] = "……你用的食材，也只是最普通不过的食物而已？那为什么……",
            ["ContentFR"] = "...Vous n’utilisez pourtant que des ingrédients très simples ? Alors pourquoi... ? Quel est votre secret ?",
            ["DialogueId"] = 90031202,
            ["GUID"] = "E1623814",
            ["SpeakNpcId"] = 81101,
            ["VoiceName"] = "voice/$Locale$/char/Heitao/vo_companio_04_2",
            },
        [90040000] = {
            ["Content"] = "你留在这里，是为了和我一起度过一段缱绻的二人时光吗……呵呵，我已经开始期待了。",
            ["ContentFR"] = "Tu es là pour partager un doux instant à deux avec moi... J’ai hâte que ça commence.",
            ["DialogueId"] = 90040000,
            ["GUID"] = "E167DBA9",
            ["SpeakNpcId"] = 82101,
            ["VoiceName"] = "voice/$Locale$/char/Shuimu/vo_idle",
            },
        [90040001] = {
            ["Content"] = "我从睡醒就一直在这里等着，体内的毒液都快干涸了……不过还好你来了，现在它们又开始因为兴奋而跳动。你……可以再靠近一些吗？",
            ["ContentFR"] = "Je t’ai attendue ici depuis que je me suis réveillée. Mon venin est presque épuisé... C’est donc une bonne chose que tu sois venu. Je le sens à nouveau bouillonner dans mes veines. Peux-tu t’approcher un peu plus ?",
            ["DialogueId"] = 90040001,
            ["GUID"] = "E167DBAA",
            ["LookAt"] = {
                [1] = "82101:n(0)",
                [2] = "0:n(82101)",
                },
            ["NextOptions"] = {
                [1] = 900400011,
                [2] = 900400012,
                [3] = 900400013,
                [4] = 900400014,
                [5] = 900400015,
                },
            ["RandomOptionNum"] = 3,
            ["SpeakNpcId"] = 82101,
            ["TalkActionId"] = {
                [1] = "82101:Give",
                },
            ["VoiceName"] = "voice/$Locale$/char/Shuimu/vo_welcome",
            ["bForbidSkipOptions"] = true,
            },
        [90040002] = {
            ["Content"] = "聊点别的",
            ["ContentFR"] = "<I>Parlons d’autre chose.</>",
            ["DialogueId"] = 90040002,
            ["GUID"] = "90040002.0",
            ["NextDialogue"] = 90040001,
            },
        [90040003] = {
            ["Content"] = "再见",
            ["ContentFR"] = "<I>À bientôt.</>",
            ["DialogueId"] = 90040003,
            ["GUID"] = "90040003.0",
            },
        [90040101] = {
            ["Content"] = "是的，我喜欢雨天，我读了许多遍的小说里，爱的邂逅总是在下雨天自然发生。",
            ["ContentFR"] = "Oui, j’adore la pluie. Dans les romans que j’ai lus, les rencontres amoureuses ont toujours lieu sous la pluie.",
            ["DialogueId"] = 90040101,
            ["GUID"] = "E167EC12",
            ["LookAt"] = {
                [1] = "82101:n(0)",
                [2] = "0:n(82101)",
                },
            ["NextDialogue"] = 90040103,
            ["SpeakNpcId"] = 82101,
            ["TalkActionId"] = {
                [1] = "82101:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Shuimu/vo_topic_01_1",
            },
        [90040103] = {
            ["Content"] = "下雨天应该更适合家里睡觉吧，为什么会有邂逅？",
            ["ContentFR"] = "La pluie, c’est plutôt fait pour rester au lit, non ? Pourquoi y aurait-il des rencontres romantiques ?",
            ["DialogueId"] = 90040103,
            ["GUID"] = "E167EC13",
            ["NextDialogue"] = 90040104,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "82101:Explain02_End",
                },
            },
        [90040104] = {
            ["Content"] = "你留心观察过那些躲雨的人吗？他们在屋檐下不期而遇，潮湿的气息让草木的芳香更加馥郁，小心的试探使爱意缓缓流动……",
            ["ContentFR"] = "As-tu déjà observé ceux qui se protègent de la pluie ? Sous l’auvent, ils se croisent, l’humidité exhale un parfum de verdure, et l’amour naît doucement...",
            ["DialogueId"] = 90040104,
            ["GUID"] = "E167EC3C",
            ["NextDialogue"] = 90040105,
            ["SpeakNpcId"] = 82101,
            ["TalkActionId"] = {
                [1] = "82101:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Shuimu/vo_topic_01_2",
            },
        [90040105] = {
            ["Content"] = "呵呵……等到下个雨天，您同我一起出去瞧瞧，就会明白的。",
            ["ContentFR"] = "Hihi... La prochaine fois qu’il pleuvra, viens donc te promener avec moi. Tu comprendras.",
            ["DialogueId"] = 90040105,
            ["GUID"] = "E167EC3B",
            ["NextOptions"] = {
                [1] = 90040002,
                [2] = 90040003,
                },
            ["SpeakNpcId"] = 82101,
            ["TalkActionId"] = {
                [1] = "82101:Explain01_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Shuimu/vo_topic_01_3",
            ["bForbidSkipOptions"] = true,
            },
        [90040201] = {
            ["Content"] = "啊呀，难得你居然会和我主动谈论“爱”。",
            ["ContentFR"] = "Ah, tu t'engages dans une conversation sur l'amour avec moi, comme c'est inattendu.",
            ["DialogueId"] = 90040201,
            ["GUID"] = "E167FC7A",
            ["LookAt"] = {
                [1] = "82101:n(0)",
                [2] = "0:n(82101)",
                },
            ["NextDialogue"] = 90040203,
            ["SpeakNpcId"] = 82101,
            ["TalkActionId"] = {
                [1] = "82101:Shock_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Shuimu/vo_topic_02_1",
            },
        [90040203] = {
            ["Content"] = "应该如何描述呢……嗯，就像这香薰中的水：亲吻拥抱每一剂原料，吞噬汲取它们的气味，并最终在长久的馥郁中合为一体。",
            ["ContentFR"] = "Comment décrire ça ? C’est comme l’eau dans un parfum : elle embrasse chaque ingrédient, en absorbe l’essence, et crée un sillage qui dure longtemps...",
            ["DialogueId"] = 90040203,
            ["GUID"] = "E167FCA4",
            ["NextDialogue"] = 90040204,
            ["SpeakNpcId"] = 82101,
            ["TalkActionId"] = {
                [1] = "82101:Shock_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Shuimu/vo_topic_02_2",
            },
        [90040204] = {
            ["Content"] = "听起来是两个人每天腻在一起？",
            ["ContentFR"] = "Ça veut dire rester collés toute la journée ?",
            ["DialogueId"] = 90040204,
            ["GUID"] = "E167FCA5",
            ["NextDialogue"] = 90040205,
            ["SpeakNpcId"] = 100001,
            },
        [90040205] = {
            ["Content"] = "不止哦。我想要的爱情，是彻底的交融，没有彼此之分……即使一方生命终结了，也会成为香料园中的花泥；从中绽放的花朵将变成香薰，永远萦绕着另一个。",
            ["ContentFR"] = "Il y a bien plus que cela. Ce que je veux, c’est un amour si profond que nous devenions véritablement inséparables... Et si l’un de nous devait disparaître, son corps nourrirait le jardin d’aromates, les fleurs qui y pousseraient deviendraient un parfum, pour flotter à jamais autour de l’autre...",
            ["DialogueId"] = 90040205,
            ["GUID"] = "E167FCA6",
            ["NextOptions"] = {
                [1] = 90040002,
                [2] = 90040003,
                },
            ["SpeakNpcId"] = 82101,
            ["TalkActionId"] = {
                [1] = "82101:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Shuimu/vo_topic_02_3",
            ["bForbidSkipOptions"] = true,
            },
        [90040301] = {
            ["Content"] = "特别？啊，是的……从小到大，身边可有不少人视我为“怪物”呢。",
            ["ContentFR"] = "Spéciale ? Oui... depuis que je suis petite, beaucoup m’ont traitée de \"monstre\".",
            ["DialogueId"] = 90040301,
            ["GUID"] = "E1680CE2",
            ["LookAt"] = {
                [1] = "82101:n(0)",
                [2] = "0:n(82101)",
                },
            ["NextDialogue"] = 90040303,
            ["SpeakNpcId"] = 82101,
            ["TalkActionId"] = {
                [1] = "82101:Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Shuimu/vo_topic_03_1",
            },
        [90040303] = {
            ["Content"] = "他们每次看到我都会露出厌恶的表情，不过那样的表情可不好看，得想办法纠正一下呢……",
            ["ContentFR"] = "Chaque fois, les expressions de dégoût sur leurs visages sont désagréables, il faudrait y remédier...",
            ["DialogueId"] = 90040303,
            ["GUID"] = "E1680D36",
            ["NextDialogue"] = 90040304,
            ["SpeakNpcId"] = 82101,
            ["TalkActionId"] = {
                [1] = "82101:Talk01_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Shuimu/vo_topic_03_2",
            },
        [90040304] = {
            ["Content"] = "若是刺痛他们的脸，让毒素渗透进他们的肌肤，那张嫌恶的脸，也一定会变得温柔起来吧……呵呵。",
            ["ContentFR"] = "Peut-être qu’un peu de mon venin rendra leur expression moins dur... Hihi.",
            ["DialogueId"] = 90040304,
            ["GUID"] = "E1680D60",
            ["NextDialogue"] = 90040305,
            ["SpeakNpcId"] = 82101,
            ["TalkActionId"] = {
                [1] = "82101:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Shuimu/vo_topic_03_3",
            },
        [90040305] = {
            ["Content"] = "那么话说回来，你说的“特别”指的又是哪种“特别”？“特别”像个怪物……还是，“特别”令人倾心？",
            ["ContentFR"] = "Dis-moi, quand tu dis \"spéciale\", tu veux dire spécial comme un monstre... ou plutôt spécialement envoûtante ?",
            ["DialogueId"] = 90040305,
            ["GUID"] = "E1680D8A",
            ["NextOptions"] = {
                [1] = 90040002,
                [2] = 90040003,
                },
            ["SpeakNpcId"] = 82101,
            ["TalkActionId"] = {
                [1] = "82101:Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Shuimu/vo_topic_03_4",
            ["bForbidSkipOptions"] = true,
            },
        [90040401] = {
            ["Content"] = "不，不会的，这份毒与生俱来，像是爱之神赐给我的礼物，不会伤害我，只会帮助我找到命定的恋人。",
            ["ContentFR"] = "Je vais très bien. Mon venin fait partie de moi, comme un cadeau du Dieu de l'Amour, il est inoffensif pour moi et m’aidera à trouver l’amour de ma vie.",
            ["DialogueId"] = 90040401,
            ["GUID"] = "E1681D4A",
            ["LookAt"] = {
                [1] = "82101:n(0)",
                [2] = "0:n(82101)",
                },
            ["NextDialogue"] = 90040403,
            ["SpeakNpcId"] = 82101,
            ["TalkActionId"] = {
                [1] = "82101:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Shuimu/vo_topic_04_1",
            },
        [90040403] = {
            ["Content"] = "听起来你还挺喜欢这份礼物的？",
            ["ContentFR"] = "On dirait que tu apprécies vraiment ce cadeau.",
            ["DialogueId"] = 90040403,
            ["GUID"] = "E1681D4B",
            ["NextDialogue"] = 90040404,
            ["SpeakNpcId"] = 100001,
            },
        [90040404] = {
            ["Content"] = "是啊，虽然容易失控的毒液总让我被当做怪物，但也让我和其他人不同。所以我坚信，一个怪物的命定之人，也一定很特别，你说对吗？",
            ["ContentFR"] = "Bien sûr. Même si cela me fait souvent passer pour un monstre, cela me distingue également des autres. Je pense que le partenaire destiné à un monstre doit être quelqu'un de très spécial, tu ne crois pas ?",
            ["DialogueId"] = 90040404,
            ["GUID"] = "E1681D74",
            ["NextOptions"] = {
                [1] = 90040002,
                [2] = 90040003,
                },
            ["SpeakNpcId"] = 82101,
            ["TalkActionId"] = {
                [1] = "82101:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Shuimu/vo_topic_04_2",
            ["bForbidSkipOptions"] = true,
            },
        [90040501] = {
            ["Content"] = "是我自制的香薰哦，前调如同初遇一般浓烈，中调则是用来定香的甜言蜜语，最后的尾调，是散不去的回味再加一点苦涩。",
            ["ContentFR"] = "C’est mon parfum personnel : en notes de tête, une rencontre intense, en notes de cœur, des mots doux qui fixent le parfum, et en notes de fond, une amertume persistante.",
            ["DialogueId"] = 90040501,
            ["GUID"] = "E1682DB2",
            ["LookAt"] = {
                [1] = "82101:n(0)",
                [2] = "0:n(82101)",
                },
            ["NextDialogue"] = 90040503,
            ["SpeakNpcId"] = 82101,
            ["VoiceName"] = "voice/$Locale$/char/Shuimu/vo_topic_05_1",
            },
        [90040503] = {
            ["Content"] = "那，具体成分是什么呢？",
            ["ContentFR"] = "Qu’est-ce qu’il y a dedans, exactement ?",
            ["DialogueId"] = 90040503,
            ["GUID"] = "E1682E06",
            ["NextDialogue"] = 90040504,
            ["SpeakNpcId"] = 100001,
            },
        [90040504] = {
            ["Content"] = "秘密哟，当然，我也可以亲手教你如何调制，从始至终，一步一步。",
            ["ContentFR"] = "C’est mon petit secret. Mais je serais ravie de te guider moi-même, pas à pas, tout au long du processus de fabrication.",
            ["DialogueId"] = 90040504,
            ["GUID"] = "E1682E30",
            ["NextOptions"] = {
                [1] = 90040002,
                [2] = 90040003,
                },
            ["SpeakNpcId"] = 82101,
            ["TalkActionId"] = {
                [1] = "82101:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Shuimu/vo_topic_05_2",
            ["bForbidSkipOptions"] = true,
            },
        [90040601] = {
            ["Content"] = "……这个干燥的气息，原来是你啊。好久不见，你还是想把我拷走吗？\
嗯！可以哦。毕竟，即使重来一遍，重来多少遍，我依旧能够从你掌心逃脱的……你、相、信、吗？海尔法大人。",
            ["ContentFR"] = "Ce parfum sec... c’est toi, hein ? Ça fait longtemps. Tu veux toujours m’embarquer ? Ça a l’air plutôt amusant... Après tout, même si je te donnais mille chances, je m’échapperais quand même de ton emprise... Tu ne crois pas, Mme la Geôlière ?",
            ["DialogueId"] = 90040601,
            ["GUID"] = "E1683E1A",
            ["SpeakNpcId"] = 82101,
            ["VoiceName"] = "voice/$Locale$/char/Shuimu/vo_companio_01",
            },
        [90040701] = {
            ["Content"] = "你害怕我吗？那我会让你喜欢上我的，来闻一闻我调配的香薰吧，很甜的，保证你能体会到前所未有的幸福。",
            ["ContentFR"] = "Tu as peur de moi ? Ne t’inquiète pas, je finirai par te faire m’aimer. Viens, sens ce parfum que j’ai créé. Il est très doux, et je suis sûre que tu ressentiras un bonheur que tu n’as jamais connu.",
            ["DialogueId"] = 90040701,
            ["GUID"] = "E1684E82",
            ["SpeakNpcId"] = 82101,
            ["VoiceName"] = "voice/$Locale$/char/Shuimu/vo_companio_02",
            },
        [90050000] = {
            ["Content"] = "……喂……喂，放我出去玩啦！闲得我触手都要僵了！",
            ["ContentFR"] = "Hé ho, laisse-moi me battre avec toi. Je m’ennuie à mourir et mes tentacules ont besoin de s’étirer !",
            ["DialogueId"] = 90050000,
            ["GUID"] = "E16E4449",
            ["SpeakNpcId"] = 82301,
            ["VoiceName"] = "voice/$Locale$/char/Zhangyu/vo_idle",
            },
        [90050001] = {
            ["Content"] = "嗯，这个时间最适合动手了，要赶紧出门，不然就……哇！你什么时候来的！",
            ["ContentFR"] = "Hmm, c’est le moment parfait pour agir... Faut vite filer avant que... Waaah ! Depuis quand t’es là toi ?",
            ["DialogueId"] = 90050001,
            ["GUID"] = "E16E444A",
            ["LookAt"] = {
                [1] = "82301:n(0)",
                [2] = "0:n(82301)",
                },
            ["NextOptions"] = {
                [1] = 900500011,
                [2] = 900500012,
                [3] = 900500013,
                [4] = 900500014,
                },
            ["RandomOptionNum"] = 3,
            ["SpeakNpcId"] = 82301,
            ["TalkActionId"] = {
                [1] = "82301:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Zhangyu/vo_welcome",
            ["bForbidSkipOptions"] = true,
            },
        [90050002] = {
            ["Content"] = "聊点别的",
            ["ContentFR"] = "<I>Parlons d’autre chose.</>",
            ["DialogueId"] = 90050002,
            ["GUID"] = "90050002.0",
            ["NextDialogue"] = 90050001,
            },
        [90050003] = {
            ["Content"] = "再见",
            ["ContentFR"] = "<I>À bientôt.</>",
            ["DialogueId"] = 90050003,
            ["GUID"] = "90050003.0",
            },
        [90050101] = {
            ["Content"] = "贝蕾，我……",
            ["ContentFR"] = "« Berry, je... »",
            ["DialogueId"] = 90050101,
            ["GUID"] = "E16E54B2",
            ["LookAt"] = {
                [1] = "82301:n(0)",
                [2] = "0:n(82301)",
                },
            ["NextDialogue"] = 90050103,
            ["SpeakNpcId"] = 82301,
            ["TalkActionId"] = {
                [1] = "82301:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Zhangyu/vo_topic_01_1",
            },
        [90050103] = {
            ["Content"] = "？",
            ["ContentFR"] = "?",
            ["DialogueId"] = 90050103,
            ["GUID"] = "E16E5506",
            ["NextDialogue"] = 90050104,
            ["SpeakNpcId"] = 100001,
            },
        [90050104] = {
            ["Content"] = "每个早上都看见你笑着，就足够了。从今以后的每一天，我都会一直保护你的。嘻嘻，我学得像不像？",
            ["ContentFR"] = "« Ton sourire du matin me suffit pour bien commencer la journée. À partir d’aujourd’hui, je serai toujours là pour te protéger. » Hihi, j’imite bien ou pas ?",
            ["DialogueId"] = 90050104,
            ["GUID"] = "E16E5530",
            ["NextDialogue"] = 90050105,
            ["SpeakNpcId"] = 82301,
            ["VoiceName"] = "voice/$Locale$/char/Zhangyu/vo_topic_01_2",
            },
        [90050105] = {
            ["Content"] = "不像！一点也不像！不许学！",
            ["ContentFR"] = "Non ! Pas du tout ! Arrête de m’imiter !",
            ["DialogueId"] = 90050105,
            ["GUID"] = "E16E555A",
            ["NextDialogue"] = 90050106,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "82301:Explain02_End",
                },
            },
        [90050106] = {
            ["Content"] = "生气啦？嘻嘻嘻，你生气的样子让人更想学了！",
            ["ContentFR"] = "Tu es en colère ? Hihihi, cette grimace sur ton visage me donne encore plus envie de t'imiter !",
            ["DialogueId"] = 90050106,
            ["GUID"] = "E16E5584",
            ["NextOptions"] = {
                [1] = 90050002,
                [2] = 90050003,
                },
            ["SpeakNpcId"] = 82301,
            ["VoiceName"] = "voice/$Locale$/char/Zhangyu/vo_topic_01_3",
            ["bForbidSkipOptions"] = true,
            },
        [90050201] = {
            ["Content"] = "因为我会变呀，嘻嘻，我能变成任何形状，任何颜色，完美地伪装自己，一般人绝对发现不了我！",
            ["ContentFR"] = "Facile ! Je peux changer d’apparence comme je veux ! Hihi, je peux prendre n’importe quelle forme, n’importe quelle couleur, et me fondre parfaitement dans n’importe quel environnement. Personne ne peut me repérer !",
            ["DialogueId"] = 90050201,
            ["GUID"] = "E16E651A",
            ["LookAt"] = {
                [1] = "82301:n(0)",
                [2] = "0:n(82301)",
                },
            ["NextDialogue"] = 90050203,
            ["SpeakNpcId"] = 82301,
            ["TalkActionId"] = {
                [1] = "82301:Confident_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Zhangyu/vo_topic_02_1",
            },
        [90050203] = {
            ["Content"] = "有一天我还偷偷假扮成了木桶，等着吓唬你呢，没想到你根本不靠近……",
            ["ContentFR"] = "Une fois, je m’étais même changée en tonneau pour te faire peur... mais t’es même pas venu...",
            ["DialogueId"] = 90050203,
            ["GUID"] = "E16E6544",
            ["NextDialogue"] = 90050204,
            ["SpeakNpcId"] = 82301,
            ["TalkActionId"] = {
                [1] = "82301:Confident_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Zhangyu/vo_topic_02_2",
            },
        [90050204] = {
            ["Content"] = "屋子正中央突然出现一个木桶，怎么想都只有一种可能吧……",
            ["ContentFR"] = "Eh bien, un tonneau qui apparaît en plein milieu de la pièce ? Fallait pas être devin...",
            ["DialogueId"] = 90050204,
            ["GUID"] = "E16E6546",
            ["NextDialogue"] = 90050205,
            ["SpeakNpcId"] = 100001,
            },
        [90050205] = {
            ["Content"] = "什么？！所以原来你是故意无视我的！你这家伙！",
            ["ContentFR"] = "Hein ? Donc tu savais et t’as fait exprès de m’ignorer ! T’es trop {性别:méchant|méchante} !",
            ["DialogueId"] = 90050205,
            ["GUID"] = "E16E6545",
            ["NextOptions"] = {
                [1] = 90050002,
                [2] = 90050003,
                },
            ["SpeakNpcId"] = 82301,
            ["VoiceName"] = "voice/$Locale$/char/Zhangyu/vo_topic_02_3",
            ["bForbidSkipOptions"] = true,
            },
        [90050301] = {
            ["Content"] = "喂喂喂——我可和那些什么都偷还一肚子坏水的家伙不一样！",
            ["ContentFR"] = "Hé ho ! Je ne suis pas comme ces voleurs pleins de mauvaises intentions, ok ?",
            ["DialogueId"] = 90050301,
            ["GUID"] = "E16E7582",
            ["LookAt"] = {
                [1] = "82301:n(0)",
                [2] = "0:n(82301)",
                },
            ["NextDialogue"] = 90050303,
            ["SpeakNpcId"] = 82301,
            ["TalkActionId"] = {
                [1] = "82301:Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Zhangyu/vo_topic_03_1",
            },
        [90050303] = {
            ["Content"] = "不一样？哪里不一样？",
            ["ContentFR"] = "En quoi es-tu différente ?",
            ["DialogueId"] = 90050303,
            ["GUID"] = "E16E7584",
            ["NextDialogue"] = 90050304,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "82301:Talk01_End",
                },
            },
        [90050304] = {
            ["Content"] = "我专门偷小偷的东西——伪装成他们认不出来的样子，慢慢靠近，从他们的口袋里挑出最顺眼的赃物，统统带走！",
            ["ContentFR"] = "Moi, je ne vole que les voleurs. Je me fonds dans la masse, je m’approche discrètement et je leur vole leurs trésors préférés directement dans leurs poches !",
            ["DialogueId"] = 90050304,
            ["GUID"] = "E16E7585",
            ["NextDialogue"] = 90050305,
            ["SpeakNpcId"] = 82301,
            ["TalkActionId"] = {
                [1] = "82301:Confident_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Zhangyu/vo_topic_03_2",
            },
        [90050305] = {
            ["Content"] = "等他们发现的时候，总是震惊得眼珠都快掉出来！嘻嘻嘻……我这是伸张正义，怎么能算坏人！",
            ["ContentFR"] = "Quand ils pigent, c’est déjà trop tard ! Hihihi... C’est pour ça que je suis une justicière, pas une méchante !",
            ["DialogueId"] = 90050305,
            ["GUID"] = "E16E7583",
            ["NextOptions"] = {
                [1] = 90050002,
                [2] = 90050003,
                },
            ["SpeakNpcId"] = 82301,
            ["TalkActionId"] = {
                [1] = "82301:Confident_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Zhangyu/vo_topic_03_3",
            ["bForbidSkipOptions"] = true,
            },
        [90050401] = {
            ["Content"] = "那当然了，你要是被人皱着眉头一脸嫌弃地叫着“恶魔”，你也不会喜欢的。",
            ["ContentFR"] = "Bien sûr que non. Tu n’aimerais pas non plus que les gens te traitent de démon en fronçant les sourcils et en te regardant avec dégoût.",
            ["DialogueId"] = 90050401,
            ["GUID"] = "E16E85EA",
            ["LookAt"] = {
                [1] = "82301:n(0)",
                [2] = "0:n(82301)",
                },
            ["NextDialogue"] = 90050403,
            ["SpeakNpcId"] = 82301,
            ["TalkActionId"] = {
                [1] = "82301:Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Zhangyu/vo_topic_04_1",
            },
        [90050403] = {
            ["Content"] = "可你怎么会管自己叫做“恶魔大盗”啊？",
            ["ContentFR"] = "Alors pourquoi tu t’appelles \"Démon Tabethe, la Main Rouge\" ?",
            ["DialogueId"] = 90050403,
            ["GUID"] = "E16E85EC",
            ["NextDialogue"] = 90050404,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "82301:Talk03_End",
                },
            },
        [90050404] = {
            ["Content"] = "那当然是想要让“恶魔”这个词变得帅气起来，现在的小偷啊，听到“恶魔大盗”的名头就会魂不附体。",
            ["ContentFR"] = "C’est parce que je veux rendre le mot \"démon\" cool. Maintenant, la simple mention de mon titre \"Démon Tabethe la Main Rouge\" fait frissonner ces voleurs.",
            ["DialogueId"] = 90050404,
            ["GUID"] = "E16E85EB",
            ["NextDialogue"] = 90050405,
            ["SpeakNpcId"] = 82301,
            ["TalkActionId"] = {
                [1] = "82301:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Zhangyu/vo_topic_04_2",
            },
        [90050405] = {
            ["Content"] = "迟早有一天，人们提到“恶魔”，就只会想到厉害的我，怎么样，是很伟大的梦想吧！",
            ["ContentFR"] = "Un jour, quand on entendra \"démon\", on pensera juste à moi, la plus cool de toutes ! C’est pas un rêve génial, ça ?",
            ["DialogueId"] = 90050405,
            ["GUID"] = "E16E85ED",
            ["NextOptions"] = {
                [1] = 90050002,
                [2] = 90050003,
                },
            ["SpeakNpcId"] = 82301,
            ["VoiceName"] = "voice/$Locale$/char/Zhangyu/vo_topic_04_3",
            ["bForbidSkipOptions"] = true,
            },
        [90050501] = {
            ["Content"] = "要抓我？我又不是坏人！不就是顺了点东西吗，还是小偷的东西……哇，你不要过来啊！好热！",
            ["ContentFR"] = "Hein ? Tu veux m’attraper ? Mais je suis gentille, moi ! J’ai juste piqué un truc à un autre voleur... Hé, t’approche pas ! Aïe ! Ça brûle !",
            ["DialogueId"] = 90050501,
            ["GUID"] = "E16E9652",
            ["SpeakNpcId"] = 82301,
            ["VoiceName"] = "voice/$Locale$/char/Zhangyu/vo_companio_01",
            },
        [90050601] = {
            ["Content"] = "送我香薰？唔，你看起来就好危险，我不要我不要！等等……这个香薰闻起来，怎么让人感觉飘飘的……我的触手怎么麻麻的……你果然很危险！",
            ["ContentFR"] = "C’est pour moi ? Hmm... t’as une tête louche, toi... Oh non, ce parfum... j’ai la tête qui tourne, et mes tentacules picotent ! T’es vraiment trop suspecte !",
            ["DialogueId"] = 90050601,
            ["GUID"] = "E16EA6BA",
            ["SpeakNpcId"] = 82301,
            ["VoiceName"] = "voice/$Locale$/char/Zhangyu/vo_companio_02",
            },
        [90050701] = {
            ["Content"] = "你对着剑说话的样子好好玩！萨麦尔，你喜欢这个地方吗，我们还要一起去更多的地方哦！\
嗯……？你怎么在那里干憋气不出声，这样子更好玩了嘻嘻嘻！",
            ["ContentFR"] = "T’es trop marrante quand tu parles à ton épée ! « Samaël, tu aimes cet endroit ? Allons explorer encore plein d’autres lieux ! » ... Pourquoi tu fais cette tête ? Hihi, encore plus drôle comme ça !",
            ["DialogueId"] = 90050701,
            ["GUID"] = "E16EB722",
            ["SpeakNpcId"] = 82301,
            ["VoiceName"] = "voice/$Locale$/char/Zhangyu/vo_companio_03",
            },
        [90060000] = {
            ["Content"] = "真是惬意自得……不害怕我的炼火吗？哈，无知的蝼蚁，或许把你踩在脚下时你才会感到悔意。",
            ["ContentFR"] = "Quelle sérénité... Tu ne crains donc pas mes flammes ? Hmpf, pauvre insecte. Tu regretteras ton ignorance quand je t’écraserai.",
            ["DialogueId"] = 90060000,
            ["GUID"] = "E174ACE9",
            ["SpeakNpcId"] = 83201,
            ["VoiceName"] = "voice/$Locale$/char/Haier/vo_idle",
            },
        [90060001] = {
            ["Content"] = "今天准备好接受拷问了吗？！",
            ["ContentFR"] = "{性别:Prêt|Prête} pour l’interrogatoire du jour ?",
            ["DialogueId"] = 90060001,
            ["GUID"] = "E174ACEA",
            ["LookAt"] = {
                [1] = "83201:n(0)",
                [2] = "0:n(83201)",
                },
            ["NextOptions"] = {
                [1] = 900600011,
                [2] = 900600012,
                [3] = 900600013,
                [4] = 900600014,
                [5] = 900600015,
                },
            ["RandomOptionNum"] = 3,
            ["SpeakNpcId"] = 83201,
            ["TalkActionId"] = {
                [1] = "83201:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Haier/vo_welcome",
            ["bForbidSkipOptions"] = true,
            },
        [90060002] = {
            ["Content"] = "聊点别的",
            ["ContentFR"] = "<I>Parlons d’autre chose.</>",
            ["DialogueId"] = 90060002,
            ["GUID"] = "90060002.0",
            ["NextDialogue"] = 90060001,
            },
        [90060003] = {
            ["Content"] = "再见",
            ["ContentFR"] = "<I>À bientôt.</>",
            ["DialogueId"] = 90060003,
            ["GUID"] = "90060003.0",
            },
        [90060101] = {
            ["Content"] = "如果你熟读历史的话，就会知道，皇家军事监狱的初代典狱长也有着熔岩一般的皮肤，再凶恶的罪徒也会畏惧她的拷问。",
            ["ContentFR"] = "Si tu avais étudié l’histoire, tu saurais que la toute première geôlière de la Prison Militaire Royale avait la peau rouge, comme de la lave en fusion. Même les criminels les plus endurcis redoutaient ses interrogatoires.",
            ["DialogueId"] = 90060101,
            ["GUID"] = "E174BD52",
            ["LookAt"] = {
                [1] = "83201:n(0)",
                [2] = "0:n(83201)",
                },
            ["NextDialogue"] = 90060102,
            ["SpeakNpcId"] = 83201,
            ["TalkActionId"] = {
                [1] = "83201:Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Haier/vo_topic_01_1",
            },
        [90060102] = {
            ["Content"] = "而我，作为她的后代，继承了她的名号，同样会用炼火将一切罪行烧成炉灰。",
            ["ContentFR"] = "En tant que sa descendante, je porte fièrement son nom, prête à incinérer tous les péchés avec mon feu.",
            ["DialogueId"] = 90060102,
            ["GUID"] = "E174BD53",
            ["NextDialogue"] = 90060103,
            ["SpeakNpcId"] = 83201,
            ["TalkActionId"] = {
                [1] = "83201:Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Haier/vo_topic_01_2",
            },
        [90060103] = {
            ["Content"] = "那……你滚烫的皮肤会不会让你生活不太方便？",
            ["ContentFR"] = "Votre peau... aussi brûlante, ça ne rend pas la vie difficile ?",
            ["DialogueId"] = 90060103,
            ["GUID"] = "E174BD54",
            ["NextDialogue"] = 90060104,
            ["SpeakNpcId"] = 100001,
            },
        [90060104] = {
            ["Content"] = "有一些影响，我只能睡在铁制的床上，也不能在木头屋子里待上太久。但与之相对的，我能在火场里把罪犯带出来让他们直面法律，也从不怕冷。",
            ["ContentFR"] = "Cela pose certes quelques difficultés : je ne peux dormir que sur des lits en fer et je ne peux pas rester longtemps dans des structures en bois. Cependant, cela me permet de sauver des criminels de bâtiments en feu et de rendre justice. Et le froid ne me dérange jamais.",
            ["DialogueId"] = 90060104,
            ["GUID"] = "E174BD55",
            ["NextDialogue"] = 90060105,
            ["SpeakNpcId"] = 83201,
            ["TalkActionId"] = {
                [1] = "83201:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Haier/vo_topic_01_3",
            },
        [90060105] = {
            ["Content"] = "异于常人的外表于我而言，更像是一份馈赠，非要说有什么不方便的……我一直想尝一尝那种叫做冰激凌的甜品，但它总是在我手上就化掉了……",
            ["ContentFR"] = "Mon apparence inhabituelle, je la vois plutôt comme un don. S’il faut vraiment lui trouver un inconvénient... j’ai toujours voulu goûter une glace, mais elle fond avant même que je puisse en prendre une bouchée.",
            ["DialogueId"] = 90060105,
            ["GUID"] = "E174BD56",
            ["NextOptions"] = {
                [1] = 90060002,
                [2] = 90060003,
                },
            ["SpeakNpcId"] = 83201,
            ["TalkActionId"] = {
                [1] = "83201:Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Haier/vo_topic_01_4",
            ["bForbidSkipOptions"] = true,
            },
        [90060201] = {
            ["Content"] = "从帝国诞生起，我的家族就世代执掌着关押罪大恶极的犯人们的牢狱，理清冤罪，或是斩除祸患。",
            ["ContentFR"] = "Depuis la création de l'Empire, ma famille veille sur les pires détenus, rendant justice et supprimant les dangers.",
            ["DialogueId"] = 90060201,
            ["GUID"] = "E174CDBA",
            ["LookAt"] = {
                [1] = "83201:n(0)",
                [2] = "0:n(83201)",
                },
            ["NextDialogue"] = 90060202,
            ["SpeakNpcId"] = 83201,
            ["TalkActionId"] = {
                [1] = "83201:Angry01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Haier/vo_topic_02_1",
            },
        [90060202] = {
            ["Content"] = "而我与生俱来和先祖同样的火红肤色，就注定了我要拿起她留下的铁铸法典。所以并非是我选择成为典狱长，而是典狱长的头衔选择了我。",
            ["ContentFR"] = "Ma peau rouge comme le feu, héritée de mes ancêtres, m’a destinée à porter ce titre. Ce n’est pas moi qui ai choisi, c’est le rôle qui m’a choisie.",
            ["DialogueId"] = 90060202,
            ["GUID"] = "E174CDBB",
            ["NextDialogue"] = 90060203,
            ["SpeakNpcId"] = 83201,
            ["TalkActionId"] = {
                [1] = "83201:Angry01_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Haier/vo_topic_02_2",
            },
        [90060203] = {
            ["Content"] = "这么说你已经实现了自己的愿望？",
            ["ContentFR"] = "Cela signifie-t-il que vous avez déjà réalisé vos ambitions ?",
            ["DialogueId"] = 90060203,
            ["GUID"] = "E174CDBC",
            ["NextDialogue"] = 90060204,
            ["SpeakNpcId"] = 100001,
            },
        [90060204] = {
            ["Content"] = "成为典狱长并非愿望的终点，相反，这只是一个开始，它意味着我需要时刻保持戒备和警醒一一斩除帝国土地上孳生的任何不义，直到死亡将我熄灭。",
            ["ContentFR"] = "Être geôlière n’est pas un accomplissement, mais le commencement. Je resterai sur le qui-vive, traquant chaque injustice jusqu’à ce que la mort m’emporte.",
            ["DialogueId"] = 90060204,
            ["GUID"] = "E174CDBD",
            ["NextOptions"] = {
                [1] = 90060002,
                [2] = 90060003,
                },
            ["SpeakNpcId"] = 83201,
            ["TalkActionId"] = {
                [1] = "83201:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Haier/vo_topic_02_3",
            ["bForbidSkipOptions"] = true,
            },
        [90060301] = {
            ["Content"] = "那当然，帝国监狱里多的是难缠的犯人，审讯案件、查阅卷宗、防止那些狡猾的老鼠设法逃走都是典狱长的职责所在。",
            ["ContentFR"] = "Certainement. La prison impériale regorge de criminels perfides. Mes fonctions consistent à mener des interrogatoires, examiner des dossiers et déjouer les tentatives d’évasion.",
            ["DialogueId"] = 90060301,
            ["GUID"] = "E174DE22",
            ["LookAt"] = {
                [1] = "83201:n(0)",
                [2] = "0:n(83201)",
                },
            ["NextDialogue"] = 90060302,
            ["SpeakNpcId"] = 83201,
            ["TalkActionId"] = {
                [1] = "83201:Confident_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Haier/vo_topic_03_1",
            },
        [90060302] = {
            ["Content"] = "每休息一分，都会让正义迟到一分——而当正义迟迟不来时，混乱与弱肉强食就会代替法条成为新的规则。",
            ["ContentFR"] = "Le moindre moment de pause retarde la justice. Et quand la justice tarde, c’est le chaos et la loi du plus fort qui règnent.",
            ["DialogueId"] = 90060302,
            ["GUID"] = "E174DE23",
            ["NextDialogue"] = 90060303,
            ["SpeakNpcId"] = 83201,
            ["TalkActionId"] = {
                [1] = "83201:Confident_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Haier/vo_topic_03_2",
            },
        [90060303] = {
            ["Content"] = "如果监狱里的犯人越来越少，你会不会轻松一点。",
            ["ContentFR"] = "Votre travail serait-il plus facile s’il y avait moins de prisonniers ?",
            ["DialogueId"] = 90060303,
            ["GUID"] = "E174DE24",
            ["NextDialogue"] = 90060304,
            ["SpeakNpcId"] = 100001,
            },
        [90060304] = {
            ["Content"] = "确实有学者设想过没有罪犯的世界。如果真的有那天，我也将不复存在，因为正是罪恶造就了典狱长。但是在那之前，我会尽力维护好现存的秩序。",
            ["ContentFR"] = "Certains chercheurs ont imaginé un monde sans crime. Si un tel jour venait à arriver, ma raison d'être disparaîtrait, car le mal nécessite l’existence d’une geôlière. D’ici là, je m’engage à maintenir l’ordre.",
            ["DialogueId"] = 90060304,
            ["GUID"] = "E174DE25",
            ["NextOptions"] = {
                [1] = 90060002,
                [2] = 90060003,
                },
            ["SpeakNpcId"] = 83201,
            ["TalkActionId"] = {
                [1] = "83201:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Haier/vo_topic_03_3",
            ["bForbidSkipOptions"] = true,
            },
        [90060401] = {
            ["Content"] = "正义？正义就是权力约束欲望，力量桎梏罪孽，强者鞭挞恶徒。",
            ["ContentFR"] = "La justice ? C’est dompter le désir par le pouvoir, enchaîner le mal par la force, et châtier les coupables par les puissants.",
            ["DialogueId"] = 90060401,
            ["GUID"] = "E174EE8A",
            ["LookAt"] = {
                [1] = "83201:n(0)",
                [2] = "0:n(83201)",
                },
            ["NextDialogue"] = 90060402,
            ["SpeakNpcId"] = 83201,
            ["TalkActionId"] = {
                [1] = "83201:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Haier/vo_topic_04_1",
            },
        [90060402] = {
            ["Content"] = "这样的规则也太绝对了吧。",
            ["ContentFR"] = "Ce n’est pas un peu trop tranché comme vision ?",
            ["DialogueId"] = 90060402,
            ["GUID"] = "E174EE8B",
            ["NextDialogue"] = 90060403,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "83201:Explain01_End",
                },
            },
        [90060403] = {
            ["Content"] = "哼，绝对？不然呢，天真的小朋友，难道指望人人都手拉手过家家？绝对的力量、绝对的秩序，这就是我的正义！",
            ["ContentFR"] = "Hmpf, tranché ? Je ne m’attendrais pas à ce {性别:qu’un enfant naïf|qu’une enfant naïve} comprenne. Nous ne vivons pas dans une utopie où les gens se tiennent simplement la main et s’aiment les uns les autres. Ce n'est que par le pouvoir absolu et l’ordre que la véritable justice peut être garantie !",
            ["DialogueId"] = 90060403,
            ["GUID"] = "E174EE8C",
            ["NextOptions"] = {
                [1] = 90060002,
                [2] = 90060003,
                },
            ["SpeakNpcId"] = 83201,
            ["VoiceName"] = "voice/$Locale$/char/Haier/vo_topic_04_2",
            ["bForbidSkipOptions"] = true,
            },
        [90060501] = {
            ["Content"] = "帝国的罪犯还在满大街地跑，身为典狱长哪有什么闲暇时间。只能在忙里偷闲的时候，喝几杯烈酒。",
            ["ContentFR"] = "Avec des criminels partout dans les rues de l’Empire, une geôlière n’a pas de loisirs. Je profite juste de quelques verres quand je peux.",
            ["DialogueId"] = 90060501,
            ["GUID"] = "E174FEF2",
            ["LookAt"] = {
                [1] = "83201:n(0)",
                [2] = "0:n(83201)",
                },
            ["NextDialogue"] = 90060502,
            ["SpeakNpcId"] = 83201,
            ["TalkActionId"] = {
                [1] = "83201:Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Haier/vo_topic_05_1",
            },
        [90060502] = {
            ["Content"] = "什么！你会喝酒？",
            ["ContentFR"] = "Quoi ?! Vous buvez ?",
            ["DialogueId"] = 90060502,
            ["GUID"] = "E174FF1C",
            ["LookAt"] = {
                [1] = "83201:n(0)",
                [2] = "0:n(83201)",
                },
            ["NextDialogue"] = 90060503,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "83201:Talk01_End",
                },
            },
        [90060503] = {
            ["Content"] = "怎么，很惊讶？消遣而已：审讯时总会听到各种酒的名字，就开始好奇，这到底是什么邪恶药水，总是和犯罪沾边，于是偶尔会来上一些。",
            ["ContentFR"] = "Ça te surprend ? Ce n’est qu’un passe-temps. Pendant les interrogatoires, j’entends constamment parler de toutes sortes d’alcools, ce qui m’a rendue curieuse au sujet de cette soi-disant potion maléfique souvent liée au crime. Alors j’en bois à l’occasion.",
            ["DialogueId"] = 90060503,
            ["GUID"] = "E174FF1D",
            ["NextDialogue"] = 90060504,
            ["SpeakNpcId"] = 83201,
            ["TalkActionId"] = {
                [1] = "83201:Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Haier/vo_topic_05_2",
            },
        [90060504] = {
            ["Content"] = "喝得越多，我越是确信，邪恶的并不是酒。",
            ["ContentFR"] = "Et plus j’en bois, plus je suis convaincue que le mal ne vient pas de l’alcool lui-même.",
            ["DialogueId"] = 90060504,
            ["GUID"] = "E174FF1E",
            ["NextOptions"] = {
                [1] = 90060002,
                [2] = 90060003,
                },
            ["SpeakNpcId"] = 83201,
            ["TalkActionId"] = {
                [1] = "83201:Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Haier/vo_topic_05_3",
            ["bForbidSkipOptions"] = true,
            },
        [90060601] = {
            ["Content"] = "典狱长和军团长，都是帝国“黑暗”秩序的维护者。我们心狠手辣、声名狼藉——但是为了海伯利亚，这点恶名又算得上什么？！",
            ["ContentFR"] = "Moi, geôlière. Vous, commandante de la Légion. Deux visages d’un même ordre implacable. Que l’on nous craigne ou nous haïsse, tant que l’Empire vit, cela n’a aucune importance.",
            ["DialogueId"] = 90060601,
            ["GUID"] = "E1750F5A",
            ["SpeakNpcId"] = 83201,
            ["VoiceName"] = "voice/$Locale$/char/Haier/vo_companio_01",
            },
        [90060701] = {
            ["Content"] = "又是你。",
            ["ContentFR"] = "Tiens, encore toi.",
            ["DialogueId"] = 90060701,
            ["GUID"] = "E1751FC2",
            ["SpeakNpcId"] = 83201,
            ["VoiceName"] = "voice/$Locale$/char/Haier/vo_companio_02",
            },
        [90060801] = {
            ["Content"] = "啧，西比尔的副官……那个总被指责不尽职的家伙，对吧？可惜，你那些隐藏实力的拙劣技巧瞒不过我的眼睛！藏匿锋芒混迹在军团长身边，你到底有什么居心？！",
            ["ContentFR"] = "Tss, l’adjoint de Sibylle... Celui qu’on accuse sans cesse d’incompétence, pas vrai ? Je vois clair dans ton petit jeu : tu caches tes talents et ton ambition pour rester dans son ombre. Dis-moi, qu’est-ce que tu mijotes ?",
            ["DialogueId"] = 90060801,
            ["GUID"] = "E175302A",
            ["SpeakNpcId"] = 83201,
            ["VoiceName"] = "voice/$Locale$/char/Haier/vo_companio_03",
            },
        [90070000] = {
            ["Content"] = "无事，便是好事。",
            ["ContentFR"] = "Une journée sans incident est une bonne journée.",
            ["DialogueId"] = 90070000,
            ["GUID"] = "E17B1589",
            ["SpeakNpcId"] = 84201,
            ["VoiceName"] = "voice/$Locale$/char/Yuming/vo_idle",
            },
        [90070001] = {
            ["Content"] = "趁着你还没有被各种律法束缚，想做什么事情，就去做吧。",
            ["ContentFR"] = "Profite de ta liberté, tant que la loi ne t’a pas encore enchaîné.",
            ["DialogueId"] = 90070001,
            ["GUID"] = "E17B158A",
            ["LookAt"] = {
                [1] = "84201:n(0)",
                [2] = "0:n(84201)",
                },
            ["NextOptions"] = {
                [1] = 900700011,
                [2] = 900700012,
                [3] = 900700013,
                [4] = 900700014,
                },
            ["RandomOptionNum"] = 3,
            ["SpeakNpcId"] = 84201,
            ["TalkActionId"] = {
                [1] = "84201:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Yuming/vo_welcome",
            ["bForbidSkipOptions"] = true,
            },
        [90070002] = {
            ["Content"] = "聊点别的",
            ["ContentFR"] = "<I>Parlons d’autre chose.</>",
            ["DialogueId"] = 90070002,
            ["GUID"] = "90070002.0",
            ["NextDialogue"] = 90070001,
            },
        [90070003] = {
            ["Content"] = "再见",
            ["ContentFR"] = "<I>À bientôt.</>",
            ["DialogueId"] = 90070003,
            ["GUID"] = "90070003.0",
            },
        [90070101] = {
            ["Content"] = "……这等闲聊，有更适合的人选吧。找那些贩卖货物的织星客吧，或者看看书也好。",
            ["ContentFR"] = "... Pour ce genre de bavardages, il y a sûrement de meilleures personnes. Va discuter avec les marchands itinérants, ou ouvre un livre.",
            ["DialogueId"] = 90070101,
            ["GUID"] = "E17B25F2",
            ["LookAt"] = {
                [1] = "84201:n(0)",
                [2] = "0:n(84201)",
                },
            ["NextDialogue"] = 90070102,
            ["SpeakNpcId"] = 84201,
            ["TalkActionId"] = {
                [1] = "84201:Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Yuming/vo_topic_01_1",
            },
        [90070102] = {
            ["Content"] = "每个人眼中的世界各不相同，我是在问你的看法。",
            ["ContentFR"] = "Chacun a son regard sur le monde. Je veux connaître le tien.",
            ["DialogueId"] = 90070102,
            ["GUID"] = "E17B25F3",
            ["NextDialogue"] = 90070103,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "84201:Talk03_End",
                },
            },
        [90070103] = {
            ["Content"] = "我平素繁忙，所以眼见多有偏狭。你若是真的好奇，与其假他人言语，不如亲自踏足那里，如何？",
            ["ContentFR"] = "Ma vision est obscurcie par mes devoirs. Si tu veux comprendre Huaxu, il te faudra t’y rendre toi-même.",
            ["DialogueId"] = 90070103,
            ["GUID"] = "E17B25F4",
            ["NextOptions"] = {
                [1] = 90070002,
                [2] = 90070003,
                },
            ["SpeakNpcId"] = 84201,
            ["TalkActionId"] = {
                [1] = "84201:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Yuming/vo_topic_01_2",
            ["bForbidSkipOptions"] = true,
            },
        [90070201] = {
            ["Content"] = "《大风九章》是华胥的律法，谁都不能违抗。但倘若真要有人倒反天命，那自然要有人去收拾乱局。",
            ["ContentFR"] = "Les Neuf Chapitres de Dafeng sont les lois absolues de Huaxu, que nul ne peut enfreindre. Pourtant, si un jour quelqu’un devait défier le destin, il reviendrait à certains de contenir ce chaos.",
            ["DialogueId"] = 90070201,
            ["GUID"] = "E17B365A",
            ["LookAt"] = {
                [1] = "84201:n(0)",
                [2] = "0:n(84201)",
                },
            ["NextDialogue"] = 90070202,
            ["SpeakNpcId"] = 84201,
            ["TalkActionId"] = {
                [1] = "84201:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Yuming/vo_topic_02_1",
            },
        [90070202] = {
            ["Content"] = "那么你一定很受崇敬吧。",
            ["ContentFR"] = "Tu dois être très respecté, alors.",
            ["DialogueId"] = 90070202,
            ["GUID"] = "E17B365B",
            ["NextDialogue"] = 90070203,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "84201:Explain01_End",
                },
            },
        }
  end },
  { MinKey = 90070203, MaxKey = 90160404, Loader = function()
      return {
        [90070203] = {
            ["Content"] = "……也许吧，我不常与人们闲谈，毕竟但凡需要我出手的地方，总有伤逝。大部华胥之民，是并不乐见我的。",
            ["ContentFR"] = "... Peut-être bien. Je ne m’attarde guère en discussions futiles. Chaque fois que j’interviens, il y a des blessés, parfois des morts. Ainsi, la majorité des habitants de Huaxu ne se réjouissent pas de ma présence.",
            ["DialogueId"] = 90070203,
            ["GUID"] = "E17B365C",
            ["NextOptions"] = {
                [1] = 90070002,
                [2] = 90070003,
                },
            ["SpeakNpcId"] = 84201,
            ["VoiceName"] = "voice/$Locale$/char/Yuming/vo_topic_02_2",
            ["bForbidSkipOptions"] = true,
            },
        [90070301] = {
            ["Content"] = "无事可乐，自然如此。",
            ["ContentFR"] = "Rien ne mérite d’être célébré. C’est ainsi.",
            ["DialogueId"] = 90070301,
            ["GUID"] = "E17B46C2",
            ["LookAt"] = {
                [1] = "84201:n(0)",
                [2] = "0:n(84201)",
                },
            ["NextDialogue"] = 90070302,
            ["SpeakNpcId"] = 84201,
            ["TalkActionId"] = {
                [1] = "84201:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Yuming/vo_topic_03_1",
            },
        [90070302] = {
            ["Content"] = "也许我可以分享你的烦恼。",
            ["ContentFR"] = "Tu pourrais essayer d’en parler, tu sais.",
            ["DialogueId"] = 90070302,
            ["GUID"] = "E17B46C3",
            ["NextDialogue"] = 90070303,
            ["SpeakNpcId"] = 100001,
            },
        [90070303] = {
            ["Content"] = "谢了，但是说与你听，也不过是徒然让这世上又多了一个烦恼之人，何必。",
            ["ContentFR"] = "Je te remercie de ta sollicitude, mais je ne voudrais pas accabler quelqu'un d’autre avec mes malheurs. Ce n’est pas nécessaire.",
            ["DialogueId"] = 90070303,
            ["GUID"] = "E17B46C4",
            ["NextOptions"] = {
                [1] = 90070002,
                [2] = 90070003,
                },
            ["SpeakNpcId"] = 84201,
            ["TalkActionId"] = {
                [1] = "84201:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Yuming/vo_topic_03_2",
            ["bForbidSkipOptions"] = true,
            },
        [90070401] = {
            ["Content"] = "是啊，月亮很好，很好。无论前一天发生过什么，杯盘狼籍还是血溅五步，月光都能洗净一切。不管过去多久，天边的一角总是会为你留下一弯月亮。",
            ["ContentFR"] = "Oui. La lune est pure. Elle efface les souillures du jour, même les plus sanglantes. À travers les âges, son croissant veille silencieusement depuis son promontoire céleste.",
            ["DialogueId"] = 90070401,
            ["GUID"] = "E17B572A",
            ["LookAt"] = {
                [1] = "84201:n(0)",
                [2] = "0:n(84201)",
                },
            ["NextDialogue"] = 90070402,
            ["SpeakNpcId"] = 84201,
            ["TalkActionId"] = {
                [1] = "84201:Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Yuming/vo_topic_04_1",
            },
        [90070402] = {
            ["Content"] = "你在想过去的事？",
            ["ContentFR"] = "Tu penses au passé ?",
            ["DialogueId"] = 90070402,
            ["GUID"] = "E17B572B",
            ["NextDialogue"] = 90070403,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "84201:Talk02_End",
                },
            },
        [90070403] = {
            ["Content"] = "不，我是与过去诀别之人，没有过去，只是今天多喝了半杯酒而已。",
            ["ContentFR"] = "Non, j’ai fait mes adieux au passé. Ce soir, je me suis simplement permis un demi-verre de vin en plus.",
            ["DialogueId"] = 90070403,
            ["GUID"] = "E17B572C",
            ["NextOptions"] = {
                [1] = 90070002,
                [2] = 90070003,
                },
            ["SpeakNpcId"] = 84201,
            ["VoiceName"] = "voice/$Locale$/char/Yuming/vo_topic_04_2",
            ["bForbidSkipOptions"] = true,
            },
        [90070501] = {
            ["Content"] = "虽然不知道你告别了怎样的过去，但我们气息相似，保持距离吧：我并不喜欢同类。",
            ["ContentFR"] = "Je ne connais pas le passé que tu as laissé derrière toi, mais nos esprits se ressemblent. Garde tes distances, je n’apprécie guère les semblables.",
            ["DialogueId"] = 90070501,
            ["GUID"] = "E17B6792",
            ["SpeakNpcId"] = 84201,
            ["VoiceName"] = "voice/$Locale$/char/Yuming/vo_companio_01",
            },
        [90070601] = {
            ["Content"] = "我早已不是你的故知。世人萍水相逢本就如风过耳，放下吧。",
            ["ContentFR"] = "Nous ne sommes plus les camarades d’autrefois. Comme le vent qui passe, les gens vont et viennent. Mieux vaut laisser le passé derrière soi.",
            ["DialogueId"] = 90070601,
            ["GUID"] = "E17B77FA",
            ["SpeakNpcId"] = 84201,
            ["VoiceName"] = "voice/$Locale$/char/Yuming/vo_companio_02",
            },
        [90070701] = {
            ["Content"] = "我羡慕你的意志与同样坚固的法条，不知道你可有过什么时刻，曾自我怀疑过。",
            ["ContentFR"] = "Ta détermination et ton respect des règles m’impressionnent. As-tu déjà été assailli par le doute ?",
            ["DialogueId"] = 90070701,
            ["GUID"] = "E17B8862",
            ["SpeakNpcId"] = 84201,
            ["VoiceName"] = "voice/$Locale$/char/Yuming/vo_companio_03",
            },
        [90080000] = {
            ["Content"] = "嗯……这个自动绕后的折叠枪可以升级成连发的……火力也可以再猛一些……嗯，不错不错，下次出任务就可以更快地解决敌人，然后回家休息了。",
            ["ContentFR"] = "Hum... Ce fusil pliant semi-automatique pourrait être amélioré... Plus de puissance de feu, et on pourrait finir les missions encore plus vite, pour rentrer plus tôt.",
            ["DialogueId"] = 90080000,
            ["GUID"] = "E1817E29",
            ["SpeakNpcId"] = 84202,
            ["VoiceName"] = "voice/$Locale$/char/Landi/vo_idle",
            },
        [90080001] = {
            ["Content"] = "呼~刚睡醒的感觉好舒爽啊，你呀，也不要每天太紧绷了，任务是永远也做不完的，要懂得休息。",
            ["ContentFR"] = "Ahh... Cette sensation après un bon réveil, c’est le pied. Écoute, {性别:mec|l’amie}, faut pas être tendu tout le temps. Ta liste de trucs à faire sera jamais finie. Faut savoir se détendre, c’est pas un luxe, c’est vital.",
            ["DialogueId"] = 90080001,
            ["GUID"] = "E1817E2A",
            ["LookAt"] = {
                [1] = "84202:n(0)",
                [2] = "0:n(84202)",
                },
            ["NextOptions"] = {
                [1] = 900800011,
                [2] = 900800012,
                [3] = 900800013,
                [4] = 900800014,
                },
            ["RandomOptionNum"] = 3,
            ["SpeakNpcId"] = 84202,
            ["VoiceName"] = "voice/$Locale$/char/Landi/vo_welcome",
            ["bForbidSkipOptions"] = true,
            },
        [90080002] = {
            ["Content"] = "聊点别的",
            ["ContentFR"] = "<I>Parlons d’autre chose.</>",
            ["DialogueId"] = 90080002,
            ["GUID"] = "90080002.0",
            ["NextDialogue"] = 90080001,
            },
        [90080003] = {
            ["Content"] = "再见",
            ["ContentFR"] = "<I>À bientôt.</>",
            ["DialogueId"] = 90080003,
            ["GUID"] = "90080003.0",
            },
        [90080101] = {
            ["Content"] = "家里人？我爸妈都好多年没管过我了，也就两位姐姐偶尔会对我指手画脚，不过啊我现在进了军团，她们进不来。",
            ["ContentFR"] = "Ma famille ? Mes parents m’ont laissé tranquille depuis des années. Juste mes deux sœurs qui me donnent des ordres parfois, mais maintenant que je suis dans la Légion, elles peuvent rien faire.",
            ["DialogueId"] = 90080101,
            ["GUID"] = "E1818E92",
            ["LookAt"] = {
                [1] = "84202:n(0)",
                [2] = "0:n(84202)",
                },
            ["NextDialogue"] = 90080103,
            ["SpeakNpcId"] = 84202,
            ["TalkActionId"] = {
                [1] = "84202:Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Landi/vo_topic_01_1",
            },
        [90080103] = {
            ["Content"] = "听起来你的姐姐们很凶。",
            ["ContentFR"] = "On dirait que tes sœurs sont sévères.",
            ["DialogueId"] = 90080103,
            ["GUID"] = "E1818EE6",
            ["NextDialogue"] = 90080104,
            ["SpeakNpcId"] = 100001,
            },
        [90080104] = {
            ["Content"] = "不，不是的，她们都是泼可爱动人聪明贤惠温柔乐观善良积极天真烂漫落落大方的美人！不过，如果能端庄一点就更好了……",
            ["ContentFR"] = "Non, pas du tout ! Elles sont adorables, intelligentes, gentilles, élégantes, optimistes... Bref, elles ont tout pour elles ! Bon... un peu plus de retenue ne leur ferait pas de mal.",
            ["DialogueId"] = 90080104,
            ["GUID"] = "E1818F10",
            ["NextOptions"] = {
                [1] = 90080002,
                [2] = 90080003,
                },
            ["SpeakNpcId"] = 84202,
            ["TalkActionId"] = {
                [1] = "84202:Talk02_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Landi/vo_topic_01_2",
            ["bForbidSkipOptions"] = true,
            },
        [90080201] = {
            ["Content"] = "呵，你们这些不懂休息好的人有难了！听我说：床是抚慰心灵的港湾，屋顶是洗涤灵魂的圣地，午后的花园是光明降临的方向，小憩的时刻是甜蜜的交响诗……",
            ["ContentFR"] = "Toi, tu dois être du genre à pas savoir te détendre. Écoute : le lit, c’est un refuge pour l’âme, le toit, un sanctuaire pour l’esprit, l’après-midi, le jardin devient un écrin de lumière... Et la sieste ? Une douce symphonie.",
            ["DialogueId"] = 90080201,
            ["GUID"] = "E1819EFA",
            ["LookAt"] = {
                [1] = "84202:n(0)",
                [2] = "0:n(84202)",
                },
            ["NextDialogue"] = 90080203,
            ["SpeakNpcId"] = 84202,
            ["TalkActionId"] = {
                [1] = "84202:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Landi/vo_topic_02_1",
            },
        [90080203] = {
            ["Content"] = "（转身离开。）",
            ["ContentFR"] = "(L’ignorer et partir en silence.)",
            ["DialogueId"] = 90080203,
            ["GUID"] = "E1819F4E",
            ["NextDialogue"] = 90080204,
            ["SpeakNpcId"] = 100001,
            },
        [90080204] = {
            ["Content"] = "……诶！你等我念完啊！",
            ["ContentFR"] = "Hé ! Attends, j’ai pas fini !",
            ["DialogueId"] = 90080204,
            ["GUID"] = "E1819F78",
            ["NextOptions"] = {
                [1] = 90080002,
                [2] = 90080003,
                },
            ["SpeakNpcId"] = 84202,
            ["TalkActionId"] = {
                [1] = "84202:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Landi/vo_topic_02_2",
            ["bForbidSkipOptions"] = true,
            },
        [90080301] = {
            ["Content"] = "她可太能使唤人了，一个人劈三份都不够用……咳，我是说，西比尔大人作为长官，对下属一向严格。",
            ["ContentFR"] = "Elle sait vraiment comment te faire courir partout... Il me faudrait trois moi pour suivre le rythme... Euh, je veux dire, la commandante Sibylle est très stricte avec ses subordonnés.",
            ["DialogueId"] = 90080301,
            ["GUID"] = "E181AF62",
            ["LookAt"] = {
                [1] = "84202:n(0)",
                [2] = "0:n(84202)",
                },
            ["NextDialogue"] = 90080303,
            ["SpeakNpcId"] = 84202,
            ["TalkActionId"] = {
                [1] = "84202:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Landi/vo_topic_03_1",
            },
        [90080303] = {
            ["Content"] = "改口也没用，我已经听到了。",
            ["ContentFR"] = "C’est trop tard, j’ai entendu.",
            ["DialogueId"] = 90080303,
            ["GUID"] = "E181AFB6",
            ["NextDialogue"] = 90080304,
            ["SpeakNpcId"] = 100001,
            },
        [90080304] = {
            ["Content"] = "哎呀，这可怎么办才好呢……要不，我请你一份下午茶，你就当什么都没有听见，怎么样？别担心，里面没有下药。",
            ["ContentFR"] = "Voilà ce que je te propose : un goûter, et on fait comme si tu n’avais rien entendu, ça te va ? T’inquiète, y a pas de truc bizarre dedans.",
            ["DialogueId"] = 90080304,
            ["GUID"] = "E181AFE0",
            ["NextOptions"] = {
                [1] = 90080002,
                [2] = 90080003,
                },
            ["SpeakNpcId"] = 84202,
            ["TalkActionId"] = {
                [1] = "84202:Explain01_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Landi/vo_topic_03_2",
            ["bForbidSkipOptions"] = true,
            },
        [90080401] = {
            ["Content"] = "我给你设计了一个好东西，一个小型机器人偶！战斗的时候它可以跟在你后面一边摇小旗，一边大喊“加油！”“你揍人的样子真的很酷！”",
            ["ContentFR"] = "J’ai créé un truc génial pour toi : un petit robot compagnon ! En combat, il te suit, agite un drapeau et crie \"Allez ! T’assures grave !\"",
            ["DialogueId"] = 90080401,
            ["GUID"] = "E181BFCA",
            ["LookAt"] = {
                [1] = "84202:n(0)",
                [2] = "0:n(84202)",
                },
            ["NextDialogue"] = 90080403,
            ["SpeakNpcId"] = 84202,
            ["TalkActionId"] = {
                [1] = "84202:Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Landi/vo_topic_04_1",
            },
        [90080403] = {
            ["Content"] = "怎么样，是不是感觉浑身充满力量？等我把它做出来……",
            ["ContentFR"] = "Plutôt cool, non ? Attends que je le fasse vraiment fonctionner...",
            ["DialogueId"] = 90080403,
            ["GUID"] = "E181BFF4",
            ["NextDialogue"] = 90080404,
            ["SpeakNpcId"] = 84202,
            ["TalkActionId"] = {
                [1] = "84202:Talk01_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Landi/vo_topic_04_2",
            },
        [90080404] = {
            ["Content"] = "（转身离开。）",
            ["ContentFR"] = "(L’ignorer et partir en silence.)",
            ["DialogueId"] = 90080404,
            ["GUID"] = "E181BFF5",
            ["NextDialogue"] = 90080405,
            ["SpeakNpcId"] = 100001,
            },
        [90080405] = {
            ["Content"] = "喂喂，别走啊，图纸可是我瞒着西比尔长官，用宝贵的休息时间画的——",
            ["ContentFR"] = "Hé, attends, j’ai pas fini ! J’ai dessiné ces plans sans que la commandante Sibylle ne le sache, pendant mes rares pauses...",
            ["DialogueId"] = 90080405,
            ["GUID"] = "E181BFF6",
            ["NextOptions"] = {
                [1] = 90080002,
                [2] = 90080003,
                },
            ["SpeakNpcId"] = 84202,
            ["VoiceName"] = "voice/$Locale$/char/Landi/vo_topic_04_3",
            ["bForbidSkipOptions"] = true,
            },
        [90080501] = {
            ["Content"] = "报告军团长，今日的工作已经安排完毕，您如果有其他的需要，可以随时下达指示。不过今日的工作已经很饱和了，您还是要注意歇息，不要再给自己增添额外的负担了。",
            ["ContentFR"] = "Au rapport rapport, commandante Sibylle. Les tâches du jour sont toutes assignées. Si vous avez d’autres consignes, je suis prêt à les exécuter. Mais la journée a été chargée, pensez à vous reposer pour ne pas vous épuiser.",
            ["DialogueId"] = 90080501,
            ["GUID"] = "E181D032",
            ["SpeakNpcId"] = 84202,
            ["VoiceName"] = "voice/$Locale$/char/Landi/vo_companio_01",
            },
        [90080601] = {
            ["Content"] = "上次的任务真是辛苦你了，不过我接到了一些投诉，说是你在执行任务中损坏公物，唉，你是知道我的，我这么羞涩内向，还要替你去赔不是，这也太难为我了。所以……这几个紧急任务就麻烦你代劳了，相信美丽善良和蔼可亲的琳恩小姐一定不会拒绝的吧！",
            ["ContentFR"] = "Beau boulot pour la dernière mission, mais j’ai reçu quelques plaintes à propos de dégâts matériels... Et devine qui doit aller présenter ses excuses à ta place ? Moi ! Et tu me connais, je suis bien trop timide pour ça... Alors, ma très chère, adorable et gentille Lynn, tu pourrais pas t’occuper de ces petites urgences à ma place ? Allez, sois un amour, juste cette fois.",
            ["DialogueId"] = 90080601,
            ["GUID"] = "E181E09A",
            ["SpeakNpcId"] = 84202,
            ["VoiceName"] = "voice/$Locale$/char/Landi/vo_companio_02",
            },
        [90080701] = {
            ["Content"] = "嗯，你怎么会……？哎呀，看来我还是休息太少，竟然都出现幻觉，能看见不存在的人了！之后向长官打个工伤报告，再休两天病假好了。",
            ["ContentFR"] = "Hein, comment as-tu pu... ? Je dois être épuisé, j’ai des hallucinations... Je vais déclarer ça comme accident de travail et prendre un congé maladie.",
            ["DialogueId"] = 90080701,
            ["GUID"] = "E181F102",
            ["SpeakNpcId"] = 84202,
            ["VoiceName"] = "voice/$Locale$/char/Landi/vo_companio_03",
            },
        [90090000] = {
            ["Content"] = "居然把后背轻易暴露给自己的敌人……，该说你天真还是愚蠢？",
            ["ContentFR"] = "Exposer ainsi ton dos... Est-ce de l’ignorance ou de la pure idiotie ?",
            ["DialogueId"] = 90090000,
            ["GUID"] = "E187E6C9",
            ["SpeakNpcId"] = 84301,
            ["VoiceName"] = "voice/$Locale$/char/Xibi/vo_idle",
            },
        [90090001] = {
            ["Content"] = "看到你日复一日这样奔波努力，我就忍不住开始想象，想象你再次挑战我的那一天，让人期待。",
            ["ContentFR"] = "Toute cette ardeur... Je commence à espérer que tu sois bientôt {性别:prêt|prête} à me défier de nouveau.",
            ["DialogueId"] = 90090001,
            ["GUID"] = "E187E6CA",
            ["LookAt"] = {
                [1] = "84301:n(0)",
                [2] = "0:n(84301)",
                },
            ["NextOptions"] = {
                [1] = 900900011,
                [2] = 900900012,
                [3] = 900900013,
                [4] = 900900014,
                },
            ["RandomOptionNum"] = 3,
            ["SpeakNpcId"] = 84301,
            ["TalkActionId"] = {
                [1] = "84301:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Xibi/vo_welcome",
            ["bForbidSkipOptions"] = true,
            },
        [90090002] = {
            ["Content"] = "聊点别的",
            ["ContentFR"] = "<I>Parlons d’autre chose.</>",
            ["DialogueId"] = 90090002,
            ["GUID"] = "90090002.0",
            ["NextDialogue"] = 90090001,
            },
        [90090003] = {
            ["Content"] = "再见",
            ["ContentFR"] = "<I>À bientôt.</>",
            ["DialogueId"] = 90090003,
            ["GUID"] = "90090003.0",
            },
        [90090101] = {
            ["Content"] = "直属于皇帝的特殊军团，执行机密的任务，以及作为战场上随时击出的铁锤。",
            ["ContentFR"] = "Une unité d’élite sous les ordres directs de l’Empereur. Chargée de missions secrètes et d’interventions ciblées.",
            ["DialogueId"] = 90090101,
            ["GUID"] = "E187F732",
            ["LookAt"] = {
                [1] = "84301:n(0)",
                [2] = "0:n(84301)",
                },
            ["NextDialogue"] = 90090103,
            ["SpeakNpcId"] = 84301,
            ["TalkActionId"] = {
                [1] = "84301:Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Xibi/vo_topic_01_1",
            },
        [90090103] = {
            ["Content"] = "有皇帝在背后支持，难怪这么蛮横。",
            ["ContentFR"] = "Pas étonnant que vous soyez aussi arrogantes, avec l’Empereur dans votre dos.",
            ["DialogueId"] = 90090103,
            ["GUID"] = "E187F786",
            ["NextDialogue"] = 90090104,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "84301:Talk03_End",
                },
            },
        [90090104] = {
            ["Content"] = "你误会了。没有皇帝，军团依旧是军团，但没有军团，皇冠可就要落地了。",
            ["ContentFR"] = "Tu te trompes. Sans l’Empereur, la Légion existe toujours. Sans la Légion, la couronne tombe.",
            ["DialogueId"] = 90090104,
            ["GUID"] = "E187F7B0",
            ["NextDialogue"] = 90090105,
            ["SpeakNpcId"] = 84301,
            ["TalkActionId"] = {
                [1] = "84301:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Xibi/vo_topic_01_2",
            },
        [90090105] = {
            ["Content"] = "凭这句话，我是不是可以检举你打算谋反？",
            ["ContentFR"] = "Avec ce que vous venez de dire, puis-je vous accuser de tentative de rébellion ?",
            ["DialogueId"] = 90090105,
            ["GUID"] = "E187F7DA",
            ["NextDialogue"] = 90090106,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "84301:Confident_Start",
                },
            },
        [90090106] = {
            ["Content"] = "你大可以这么做，毕竟谋逆可是重罪，然后你的状告书会立刻被逐级上报，最后呈到我的书桌上。",
            ["ContentFR"] = "Tu peux me dénoncer, oui. Et ta plainte finira... sur mon bureau.",
            ["DialogueId"] = 90090106,
            ["GUID"] = "E187F804",
            ["NextOptions"] = {
                [1] = 90090002,
                [2] = 90090003,
                },
            ["SpeakNpcId"] = 84301,
            ["TalkActionId"] = {
                [1] = "84301:Confident_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Xibi/vo_topic_01_3",
            ["bForbidSkipOptions"] = true,
            },
        [90090201] = {
            ["Content"] = "呵，我并非忠于帝国，只是忠于理想罢了。曾有一个人为了这个理想付出了他的一切，而我要铭记与践行他的意志。",
            ["ContentFR"] = "Je ne sers pas l’Empire. Je sers un idéal. Quelqu’un a tout sacrifié pour lui. Je ne laisserai pas son combat se perdre.",
            ["DialogueId"] = 90090201,
            ["GUID"] = "E188079A",
            ["LookAt"] = {
                [1] = "84301:n(0)",
                [2] = "0:n(84301)",
                },
            ["NextDialogue"] = 90090203,
            ["SpeakNpcId"] = 84301,
            ["TalkActionId"] = {
                [1] = "84301:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Xibi/vo_topic_02_1",
            },
        [90090203] = {
            ["Content"] = "你在诡辩。不管原因为何，你的所作所为就是为虎作伥。",
            ["ContentFR"] = "Ce ne sont que des excuses. Peu importe vos raisons, vos actes ne font que renforcer la tyrannie.",
            ["DialogueId"] = 90090203,
            ["GUID"] = "E18807EE",
            ["NextDialogue"] = 90090204,
            ["SpeakNpcId"] = 100001,
            },
        [90090204] = {
            ["Content"] = "我不否认，不过为了我想要的，我会抓紧能利用的一切，不择手段地往上爬。但我每爬一步，都离我的理想更近一步。而你，又走到了哪一步呢？",
            ["ContentFR"] = "Tu n’as pas tort. Pour obtenir ce que je veux, j’utilise tout ce que j’ai sous la main et je grimpe les échelons par tous les moyens. Mais à chaque pas, je me rapproche de ce en quoi je crois. Et toi, où tes pas t’ont-ils mené ?",
            ["DialogueId"] = 90090204,
            ["GUID"] = "E1880818",
            ["NextOptions"] = {
                [1] = 90090002,
                [2] = 90090003,
                },
            ["SpeakNpcId"] = 84301,
            ["VoiceName"] = "voice/$Locale$/char/Xibi/vo_topic_02_2",
            ["bForbidSkipOptions"] = true,
            },
        [90090301] = {
            ["Content"] = "没关系，我的家人很早就不在了。",
            ["ContentFR"] = "Ma famille est partie depuis longtemps. Ce genre de douleur ne m’atteint plus.",
            ["DialogueId"] = 90090301,
            ["GUID"] = "E1881802",
            ["LookAt"] = {
                [1] = "84301:n(0)",
                [2] = "0:n(84301)",
                },
            ["NextDialogue"] = 90090303,
            ["SpeakNpcId"] = 84301,
            ["TalkActionId"] = {
                [1] = "84301:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Xibi/vo_topic_03_1",
            },
        [90090303] = {
            ["Content"] = "…………",
            ["ContentFR"] = "...",
            ["DialogueId"] = 90090303,
            ["GUID"] = "E1881856",
            ["NextDialogue"] = 90090304,
            ["SpeakNpcId"] = 100001,
            },
        [90090304] = {
            ["Content"] = "我甚至为此庆幸，这样一来我就没有了后顾之忧，只需要专心和正面与背面的敌人们厮杀。",
            ["ContentFR"] = "Je trouve ça libérateur. Plus aucune distraction, juste un chemin dégagé pour affronter mes ennemis, qu’ils soient visibles ou tapis dans l’ombre.",
            ["DialogueId"] = 90090304,
            ["GUID"] = "E1881880",
            ["NextDialogue"] = 90090305,
            ["SpeakNpcId"] = 84301,
            ["TalkActionId"] = {
                [1] = "84301:Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Xibi/vo_topic_03_2",
            },
        [90090305] = {
            ["Content"] = "情感，对于每一个踏入军团的人来说，都是破绽罢了。",
            ["ContentFR"] = "Pour ceux qui rejoignent la Légion, les émotions ne sont rien d’autre qu’une faille.",
            ["DialogueId"] = 90090305,
            ["GUID"] = "E18818AA",
            ["NextOptions"] = {
                [1] = 90090002,
                [2] = 90090003,
                },
            ["SpeakNpcId"] = 84301,
            ["TalkActionId"] = {
                [1] = "84301:Talk02_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Xibi/vo_topic_03_3",
            ["bForbidSkipOptions"] = true,
            },
        [90090401] = {
            ["Content"] = "当然，当面的咒骂和揶揄我已经听过不少，阴沟里的硕鼠们的抱怨只会更多。",
            ["ContentFR"] = "Bien sûr. J’ai entendu bien des insultes et moqueries... Et les murmures dans l’ombre sont encore plus nombreux.",
            ["DialogueId"] = 90090401,
            ["GUID"] = "E188286A",
            ["LookAt"] = {
                [1] = "84301:n(0)",
                [2] = "0:n(84301)",
                },
            ["NextDialogue"] = 90090403,
            ["SpeakNpcId"] = 84301,
            ["TalkActionId"] = {
                [1] = "84301:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Xibi/vo_topic_04_1",
            },
        [90090403] = {
            ["Content"] = "所幸，尽管这个世界有万般不公，但只要坐拥众人之上的力量，就能获得最起码的善意。",
            ["ContentFR"] = "Heureusement, malgré l’injustice du monde, posséder une force au-dessus de tous suffit à obtenir un minimum de respect.",
            ["DialogueId"] = 90090403,
            ["GUID"] = "E18828BE",
            ["NextDialogue"] = 90090404,
            ["SpeakNpcId"] = 84301,
            ["TalkActionId"] = {
                [1] = "84301:Explain01_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Xibi/vo_topic_04_2",
            },
        [90090404] = {
            ["Content"] = "那么如果你失去了力量，他们一定会落井下石。",
            ["ContentFR"] = "Dans ce cas, si vous veniez à perdre votre force, ils s’acharneraient aussitôt sur vous.",
            ["DialogueId"] = 90090404,
            ["GUID"] = "E18828E8",
            ["NextDialogue"] = 90090405,
            ["SpeakNpcId"] = 100001,
            },
        [90090405] = {
            ["Content"] = "那是自然，所以我永远不会对他们卑躬屈膝，否则，他们会立刻变成闻到血腥味的狼群。",
            ["ContentFR"] = "Évidemment. C’est précisément pour cela que je ne leur montrerai jamais la moindre faiblesse. Sinon, ils se jetteraient sur moi comme des loups à l’odeur du sang.",
            ["DialogueId"] = 90090405,
            ["GUID"] = "E1882912",
            ["NextOptions"] = {
                [1] = 90090002,
                [2] = 90090003,
                },
            ["SpeakNpcId"] = 84301,
            ["TalkActionId"] = {
                [1] = "84301:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Xibi/vo_topic_04_3",
            ["bForbidSkipOptions"] = true,
            },
        [90090501] = {
            ["Content"] = "……你与我，是时候做个了断了。",
            ["ContentFR"] = "... Il est temps que nous réglions nos différends.",
            ["DialogueId"] = 90090501,
            ["GUID"] = "E18838D2",
            ["SpeakNpcId"] = 84301,
            ["VoiceName"] = "voice/$Locale$/char/Xibi/vo_companio_01",
            },
        [90090801] = {
            ["Content"] = "你的伪装越是完美，就说明你的獠牙在暗地里打磨地越发锋锐，我等着你脱缰的那一天，亲手敲断你的大牙。",
            ["ContentFR"] = "Une si belle façade... ça ne fait que révéler à quel point tu as poli tes crocs dans l’ombre. J’attends patiemment le jour où tu montreras les crocs... pour mieux te les briser.",
            ["DialogueId"] = 90090801,
            ["GUID"] = "E1886A0A",
            ["SpeakNpcId"] = 84301,
            ["VoiceName"] = "voice/$Locale$/char/Xibi/vo_companio_04",
            },
        [90091001] = {
            ["Content"] = "近期的任务说明、作战计划、后勤运输、损失条目都整理好了吗。\
好，那今天再和我把对外宣传标语、对内案例分析、对皇帝的定期报告以及佩剑炼金院新武器的测试数据做完。工作，可不能叫额外的负担。",
            ["ContentFR"] = "Les derniers rapports d’opérations, les plans tactiques, documents logistiques et rapports de pertes sont bien organisés ?\
Bien. Alors passons aux slogans de campagne, aux analyses internes, aux rapports réguliers à l’Empereur, et les résultats des tests des nouvelles armes des Spathatoi. Ce n’est pas une charge supplémentaire, c’est notre boulot.",
            ["DialogueId"] = 90091001,
            ["GUID"] = "E1888ADA",
            ["SpeakNpcId"] = 84301,
            ["VoiceName"] = "voice/$Locale$/char/Xibi/vo_companio_05",
            },
        [90100000] = {
            ["Content"] = "什么都不做，只是就这样看着大家，就感觉过得好快好快……真希望时间能走慢一点儿呀。",
            ["ContentFR"] = "Parfois, il suffit de vous regarder pour que le temps file... J’aimerais qu’il ralentisse un peu.",
            ["DialogueId"] = 90100000,
            ["GUID"] = "E18E4F69",
            ["SpeakNpcId"] = 85301,
            ["VoiceName"] = "voice/$Locale$/char/Saiqi/vo_idle",
            },
        [90100001] = {
            ["Content"] = "太好了，今天我还在这儿。而且，你也在这儿……",
            ["ContentFR"] = "Je suis encore ici aujourd’hui... et toi aussi. Quel soulagement.",
            ["DialogueId"] = 90100001,
            ["GUID"] = "E18E4F6A",
            ["LookAt"] = {
                [1] = "85301:n(0)",
                [2] = "0:n(85301)",
                },
            ["NextOptions"] = {
                [1] = 901000011,
                [2] = 901000012,
                [3] = 901000013,
                [4] = 901000014,
                [5] = 901000015,
                },
            ["RandomOptionNum"] = 3,
            ["SpeakNpcId"] = 85301,
            ["TalkActionId"] = {
                [1] = "85301:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Saiqi/vo_welcome",
            ["bForbidSkipOptions"] = true,
            },
        [90100002] = {
            ["Content"] = "聊点别的",
            ["ContentFR"] = "<I>Parlons d’autre chose.</>",
            ["DialogueId"] = 90100002,
            ["GUID"] = "90100002.0",
            ["NextDialogue"] = 90100001,
            },
        [90100003] = {
            ["Content"] = "再见",
            ["ContentFR"] = "<I>À bientôt.</>",
            ["DialogueId"] = 90100003,
            ["GUID"] = "90100003.0",
            },
        [90100101] = {
            ["Content"] = "谢谢，着凉的话不用担心啦，卡戎之民是不怎么怕冷的，正好也不用再去买又厚又贵的大衣。",
            ["ContentFR"] = "Merci ! En fait, nous, les Charons, sommes assez résistants au froid, donc pas besoin d’acheter de gros manteaux chers.",
            ["DialogueId"] = 90100101,
            ["GUID"] = "E18E5FD2",
            ["LookAt"] = {
                [1] = "85301:n(0)",
                [2] = "0:n(85301)",
                },
            ["NextDialogue"] = 90100103,
            ["SpeakNpcId"] = 85301,
            ["TalkActionId"] = {
                [1] = "85301:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Saiqi/vo_topic_01_1",
            },
        [90100103] = {
            ["Content"] = "现在的衣服是妈妈帮我裁的，不过颜色是我自己选的，嫩绿色，这些蝴蝶形状的装饰也是我自己挑的，如果在暖和的南方的话，这一身应该就不奇怪了。",
            ["ContentFR"] = "Ma mère a confectionné cette robe, mais c’est moi qui ai choisi la couleur, ce vert vif, et les détails papillon. Ils seraient parfaitement à leur place dans un endroit chaud, comme le sud.",
            ["DialogueId"] = 90100103,
            ["GUID"] = "E18E6026",
            ["NextDialogue"] = 90100104,
            ["SpeakNpcId"] = 85301,
            ["TalkActionId"] = {
                [1] = "85301:Explain01_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Saiqi/vo_topic_01_2",
            },
        [90100104] = {
            ["Content"] = "原来是这样，蝴蝶装饰确实很适合你。",
            ["ContentFR"] = "Je vois. Les papillons sont une bonne idée, ils te vont à merveille.",
            ["DialogueId"] = 90100104,
            ["GUID"] = "E18E6050",
            ["NextDialogue"] = 90100105,
            ["SpeakNpcId"] = 100001,
            },
        [90100105] = {
            ["Content"] = "真的吗？太好了。其实我只见过冰湖城附近的蝴蝶，都是蓝色的。要是能去其他地方，看一看不同颜色的蝴蝶就好了。",
            ["ContentFR"] = "Vraiment ? Merci ! Je n’ai vu que des papillons bleus près de Givrelac. J’aimerais beaucoup voir un jour quelles autres couleurs ils peuvent avoir.",
            ["DialogueId"] = 90100105,
            ["GUID"] = "E18E607A",
            ["NextOptions"] = {
                [1] = 90100002,
                [2] = 90100003,
                },
            ["SpeakNpcId"] = 85301,
            ["VoiceName"] = "voice/$Locale$/char/Saiqi/vo_topic_01_3",
            ["bForbidSkipOptions"] = true,
            },
        [90100201] = {
            ["Content"] = "是的，据说几百年来一直都是这个样子。人们看到我们总像看到老鼠一样，我自己也被人追着骂过很难听的话。",
            ["ContentFR"] = "Oui, c’est comme ça depuis toujours. On nous traite comme des parasites et j’ai été victime de harcèlement et d’insultes sans raison.",
            ["DialogueId"] = 90100201,
            ["GUID"] = "E18E703A",
            ["LookAt"] = {
                [1] = "85301:n(0)",
                [2] = "0:n(85301)",
                },
            ["NextDialogue"] = 90100203,
            ["SpeakNpcId"] = 85301,
            ["TalkActionId"] = {
                [1] = "85301:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Saiqi/vo_topic_02_1",
            },
        [90100203] = {
            ["Content"] = "因为索拉畏惧卡戎的力量？",
            ["ContentFR"] = "C’est parce que les Solariens craignent les pouvoirs des Charons ?",
            ["DialogueId"] = 90100203,
            ["GUID"] = "E18E708E",
            ["NextDialogue"] = 90100204,
            ["SpeakNpcId"] = 100001,
            },
        [90100204] = {
            ["Content"] = "或许吧。“魔法是最邪恶的东西”，大家总是这么说。历史书上也写着，卡戎之民的先祖在一千多年前，曾经凭借魔法支配索拉之民，做出了很多恶事。",
            ["ContentFR"] = "Probablement. On dit que « la magie est la source de tous les maux ». Les livres d'histoire affirment que nos ancêtres l’ont utilisée pour régner sur les Solariens il y a plus de mille ans, commettant des actes terribles.",
            ["DialogueId"] = 90100204,
            ["GUID"] = "E18E70B8",
            ["NextDialogue"] = 90100205,
            ["SpeakNpcId"] = 85301,
            ["TalkActionId"] = {
                [1] = "85301:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Saiqi/vo_topic_02_2",
            },
        [90100205] = {
            ["Content"] = "说实话我有点难想象……因为我看到的卡戎们都很害怕索拉之民，不太敢和他们说话，在他们面前总是小心翼翼的，更不敢使用魔法。",
            ["ContentFR"] = "Honnêtement, j’ai du mal à y croire... Les Charons que je connais ont trop peur des Solariens pour oser parler en leur présence, alors utiliser la magie, n’en parlons pas.",
            ["DialogueId"] = 90100205,
            ["GUID"] = "E18E70E2",
            ["NextDialogue"] = 90100206,
            ["SpeakNpcId"] = 85301,
            ["TalkActionId"] = {
                [1] = "85301:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Saiqi/vo_topic_02_3",
            },
        [90100206] = {
            ["Content"] = "而且其实大多数卡戎魔法都很寻常，也就是能用来点点壁炉，冰冻一下食物之类的。",
            ["ContentFR"] = "Et la plupart des sorts des Charons sont assez ordinaires, ils ne servent qu’à des choses simples comme allumer des cheminées ou congeler des aliments.",
            ["DialogueId"] = 90100206,
            ["GUID"] = "E18E710C",
            ["NextDialogue"] = 90100207,
            ["SpeakNpcId"] = 85301,
            ["TalkActionId"] = {
                [1] = "85301:Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Saiqi/vo_topic_02_4",
            },
        [90100207] = {
            ["Content"] = "你会想回到那个时代吗——卡戎之民支配索拉之民的时代？",
            ["ContentFR"] = "Tu aimerais revenir à cette époque ? Quand les Charons régnaient sur les Solariens ?",
            ["DialogueId"] = 90100207,
            ["GUID"] = "E18E7136",
            ["NextDialogue"] = 90100208,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "85301:Talk01_End",
                },
            },
        [90100208] = {
            ["Content"] = "不，一点也不。为什么卡戎之民和索拉之民之间，一定要一个支配另一个，一个畏惧另一个呢？",
            ["ContentFR"] = "Pas du tout. Pourquoi l’un doit-il régner sur l’autre ? Pourquoi Charons et Solariens ne peuvent-ils pas simplement vivre en paix ?",
            ["DialogueId"] = 90100208,
            ["GUID"] = "E18E7160",
            ["NextDialogue"] = 90100209,
            ["SpeakNpcId"] = 85301,
            ["TalkActionId"] = {
                [1] = "85301:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Saiqi/vo_topic_02_5",
            },
        [90100209] = {
            ["Content"] = "我希望的只是……到了春天，所有人都能一起肩并着肩，一起去原野上看各种各样的花。只要这样就够了。",
            ["ContentFR"] = "Tout ce que je souhaite... c’est que, au retour du printemps, on puisse aller voir les fleurs ensemble. C’est tout.",
            ["DialogueId"] = 90100209,
            ["GUID"] = "E18E718A",
            ["NextOptions"] = {
                [1] = 90100002,
                [2] = 90100003,
                },
            ["SpeakNpcId"] = 85301,
            ["VoiceName"] = "voice/$Locale$/char/Saiqi/vo_topic_02_6",
            ["bForbidSkipOptions"] = true,
            },
        [90100301] = {
            ["Content"] = "啊，大概是因为我在试着培育新的花朵。修普诺斯之家前面的庭院只有几棵树，总觉得有点儿光秃秃的。所以，我想在那里种满白色的花……",
            ["ContentFR"] = "Ah, cela vient peut-être de mon nouveau projet de jardinage. La cour de la Maison d’Hypnos semblait un peu vide avec seulement quelques arbres, alors j’y ai planté des fleurs blanches.",
            ["DialogueId"] = 90100301,
            ["GUID"] = "E18E80A2",
            ["LookAt"] = {
                [1] = "85301:n(0)",
                [2] = "0:n(85301)",
                },
            ["NextDialogue"] = 90100303,
            ["SpeakNpcId"] = 85301,
            ["TalkActionId"] = {
                [1] = "85301:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Saiqi/vo_topic_03_1",
            },
        [90100303] = {
            ["Content"] = "在这里也种一点吧，铃兰，银莲，仙女木……哪种更合适呢？",
            ["ContentFR"] = "Peut-être devrions-nous en planter ici aussi, des muguets, des anémones des bois, des dryades blanches... Lesquelles conviendraient le mieux à cet endroit ?",
            ["DialogueId"] = 90100303,
            ["GUID"] = "E18E80F6",
            ["NextDialogue"] = 90100304,
            ["SpeakNpcId"] = 85301,
            ["TalkActionId"] = {
                [1] = "85301:Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Saiqi/vo_topic_03_2",
            },
        [90100304] = {
            ["Content"] = "也许可以问问大家的意见。",
            ["ContentFR"] = "Peut-être pourrions-nous demander l’avis de tout le monde.",
            ["DialogueId"] = 90100304,
            ["GUID"] = "E18E8120",
            ["NextDialogue"] = 90100305,
            ["SpeakNpcId"] = 100001,
            },
        [90100305] = {
            ["Content"] = "你说得对，应该让大家一起决定……我会去问问看的！啊，对了，这些花里有你喜欢的品种吗？等花开了，我摘一些送给你吧。",
            ["ContentFR"] = "Tu as raison, ce serait mieux si tout le monde décidait ensemble... Je vais leur demander ! Ah, au fait, il y en a une que tu préfères ? Quand elles auront fleuri, je t’en cueillerai.",
            ["DialogueId"] = 90100305,
            ["GUID"] = "E18E814A",
            ["NextOptions"] = {
                [1] = 90100002,
                [2] = 90100003,
                },
            ["SpeakNpcId"] = 85301,
            ["TalkActionId"] = {
                [1] = "85301:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Saiqi/vo_topic_03_3",
            ["bForbidSkipOptions"] = true,
            },
        [90100401] = {
            ["Content"] = "嗯，我从出生起就一直住在这里，虽然每天都能听到列车的声音，但从来没去过其他地方。如果有机会的话，真想去外面看一看。",
            ["ContentFR"] = "Non, je suis ici depuis toujours. J’entends les trains tous les jours, mais je n’ai jamais vu ce qu’il y a au bout des rails. Si j’en avais l’occasion, j’aimerais vraiment découvrir le monde extérieur.",
            ["DialogueId"] = 90100401,
            ["GUID"] = "E18E80CC",
            ["LookAt"] = {
                [1] = "85301:n(0)",
                [2] = "0:n(85301)",
                },
            ["NextDialogue"] = 90100403,
            ["SpeakNpcId"] = 85301,
            ["TalkActionId"] = {
                [1] = "85301:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Saiqi/vo_topic_04_1",
            },
        [90100403] = {
            ["Content"] = "想去哪些地方呢？",
            ["ContentFR"] = "Quels endroits tu aimerais voir un jour ?",
            ["DialogueId"] = 90100403,
            ["GUID"] = "E18E80CB",
            ["NextDialogue"] = 90100404,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "85301:Explain02_End",
                },
            },
        [90100404] = {
            ["Content"] = "唔，我想想，皇都总是要去的，恩里克叔叔说过丹流城的落日也很好看。对了，还想去你说的净界岛，在南方的海岛上，闻一闻海风是不是真的是咸的！",
            ["ContentFR"] = "Hmm... Je dirais la capitale, forcément. Et mon oncle Henrik m’a parlé des couchers de soleil magnifiques à Rougerive. Ah, et aussi cette île dans le sud dont tu m’as parlé, l’Île du Purgatoire ! Je veux sentir si l’air marin est vraiment salé !",
            ["DialogueId"] = 90100404,
            ["GUID"] = "E18E910A",
            ["NextOptions"] = {
                [1] = 90100002,
                [2] = 90100003,
                },
            ["SpeakNpcId"] = 85301,
            ["TalkActionId"] = {
                [1] = "85301:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Saiqi/vo_topic_04_2",
            ["bForbidSkipOptions"] = true,
            },
        [90100501] = {
            ["Content"] = "没什么，我只是想……再多看几眼，这样我就可以把你们的样子记得更清楚了。",
            ["ContentFR"] = "Non, c’est juste que... j’aimerais vous observer un peu plus longtemps. Pour garder une image bien nette de vous tous dans ma tête.",
            ["DialogueId"] = 90100501,
            ["GUID"] = "E18EA172",
            ["NextDialogue"] = 90100502,
            ["SpeakNpcId"] = 85301,
            ["TalkActionId"] = {
                [1] = "85301:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Saiqi/vo_topic_05_1",
            },
        [90100502] = {
            ["Content"] = "如果可以，你可以也多看我几眼吗？我也想让你记住我的样子……我现在的样子。",
            ["ContentFR"] = "Tu veux bien me regarder aussi ? Juste un peu... J’aimerais que tu te souviennes de moi... de moi telle que je suis maintenant.",
            ["DialogueId"] = 90100502,
            ["GUID"] = "E18EA19C",
            ["NextOptions"] = {
                [1] = 90100002,
                [2] = 90100003,
                },
            ["SpeakNpcId"] = 85301,
            ["TalkActionId"] = {
                [1] = "85301:Explain01_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Saiqi/vo_topic_05_2",
            ["bForbidSkipOptions"] = true,
            },
        [90100601] = {
            ["Content"] = "我听说奥特赛德先生为菲娜的生日精心准备了很久。虽然嘴上不饶人，但你其实是个很体贴的人吧？下一次菲娜生日，我可以和你们一起为她准备惊喜吗？",
            ["DialogueId"] = 90100601,
            ["GUID"] = "E18EB1DA",
            ["SpeakNpcId"] = 85301,
            ["VoiceName"] = "voice/$Locale$/char/Saiqi/vo_companio_01",
            },
        [90100701] = {
            ["Content"] = "看见卡米拉女士总会让我想起那间吵闹却温馨的酒馆……这些年能够认识大家，真是太好了。",
            ["ContentFR"] = "En voyant Camilla, je pense à cette taverne animée et accueillante... Quelle chance de vous connaître.",
            ["DialogueId"] = 90100701,
            ["GUID"] = "E18EC242",
            ["SpeakNpcId"] = 85301,
            ["VoiceName"] = "voice/$Locale$/char/Saiqi/vo_companio_02",
            },
        [90100801] = {
            ["Content"] = "你要讲艾利西安的故事给我听吗？太感谢了！唔……作为回礼，我应该送你什么花好呢……\
咦，你最喜欢好吃的花？",
            ["ContentFR"] = "Tu vas vraiment me raconter l’histoire d’Élysium ? Merci beaucoup ! Hmm... et si je t’offrais une fleur en échange ? Quoi ? Une fleur... à manger ?",
            ["DialogueId"] = 90100801,
            ["GUID"] = "E18ED2AA",
            ["SpeakNpcId"] = 85301,
            ["VoiceName"] = "voice/$Locale$/char/Saiqi/vo_companio_03",
            },
        [90110000] = {
            ["Content"] = "晨间打扫后通风，午后四处喷洒烈酒，薄暮时再点几支香驱散蚊虫，只有这样才能保持室内洁净。",
            ["ContentFR"] = "Aérer le matin après avoir nettoyé, vaporiser de l’alcool fort à midi, brûler de l’encens au crépuscule, il n’y a pas mieux pour assainir une pièce.",
            ["DialogueId"] = 90110000,
            ["GUID"] = "E194B809",
            ["SpeakNpcId"] = 82401,
            ["VoiceName"] = "voice/$Locale$/char/Baiheng/vo_idle",
            },
        [90110001] = {
            ["Content"] = "居移气，养移体，不妨趁天气晴朗出去走走，想必对身体会有所裨益。",
            ["ContentFR"] = "L'environnement façonne l'esprit, et prendre soin de soi renforce le corps. Peut-être qu'une promenade sous ce ciel clément pourrait te faire du bien.",
            ["DialogueId"] = 90110001,
            ["GUID"] = "E194B80A",
            ["LookAt"] = {
                [1] = "82401:n(0)",
                [2] = "0:n(82401)",
                },
            ["NextOptions"] = {
                [1] = 901100011,
                [2] = 901100012,
                [3] = 901100013,
                [4] = 901100014,
                },
            ["RandomOptionNum"] = 3,
            ["SpeakNpcId"] = 82401,
            ["VoiceName"] = "voice/$Locale$/char/Baiheng/vo_welcome",
            ["bForbidSkipOptions"] = true,
            },
        [90110002] = {
            ["Content"] = "聊点别的",
            ["ContentFR"] = "<I>Parlons d’autre chose.</>",
            ["DialogueId"] = 90110002,
            ["GUID"] = "90110002.0",
            ["NextDialogue"] = 90110001,
            },
        [90110003] = {
            ["Content"] = "再见",
            ["ContentFR"] = "<I>À bientôt.</>",
            ["DialogueId"] = 90110003,
            ["GUID"] = "90110003.0",
            },
        [90110101] = {
            ["Content"] = "确然。只是书中的内容晦涩难懂，药石之间的差异，在我看来也难以辨别。或许，我在此道上确实没什么天赋。",
            ["ContentFR"] = "En effet. Cependant, le contenu est dense et cryptique, et même les distinctions entre certains remèdes me semblent difficiles à saisir. Peut-être ne suis-je pas faite pour cette discipline.",
            ["DialogueId"] = 90110101,
            ["GUID"] = "E194C872",
            ["LookAt"] = {
                [1] = "82401:n(0)",
                [2] = "0:n(82401)",
                },
            ["NextDialogue"] = 90110103,
            ["SpeakNpcId"] = 82401,
            ["TalkActionId"] = {
                [1] = "82401:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Baiheng/vo_topic_01_1",
            },
        [90110103] = {
            ["Content"] = "咦？我还以为对医师来说，这些都信手拈来呢。",
            ["ContentFR"] = "Vraiment ? Je pensais que pour une guérisseuse, comprendre ce genre de choses serait un jeu d'enfant.",
            ["DialogueId"] = 90110103,
            ["GUID"] = "E194C8C6",
            ["NextDialogue"] = 90110104,
            ["SpeakNpcId"] = 100001,
            },
        [90110104] = {
            ["Content"] = "在我的时代……药物并不是医治疾病的主流方式，人们通常依靠一种名为“祝由术”的奇迹驱退病魔。",
            ["ContentFR"] = "À mon époque, la médecine n’était pas centrée sur les remèdes, on pratiquait un art miraculeux appelé \"Zhuyou\" pour chasser la maladie.",
            ["DialogueId"] = 90110104,
            ["GUID"] = "E194C8F0",
            ["NextDialogue"] = 90110105,
            ["SpeakNpcId"] = 82401,
            ["TalkActionId"] = {
                [1] = "82401:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Baiheng/vo_topic_01_2",
            },
        [90110105] = {
            ["Content"] = "然而，这种治疗方式虽然会带来“治愈”与“平安”，但也代表着“交换”与“牺牲”。从没有寿终正寝的医者，透支生命直至亡故才是我们唯一的选择。",
            ["ContentFR"] = "Mais cet art, bien qu’apportant guérison et paix, exigeait un prix, le sacrifice même de la force vitale du guérisseur. Aucun d’entre nous ne vivait jusqu’à un âge avancé, puiser dans notre essence jusqu’à la mort était la seule voie que nous connaissions.",
            ["DialogueId"] = 90110105,
            ["GUID"] = "E194C8F1",
            ["NextDialogue"] = 90110106,
            ["SpeakNpcId"] = 82401,
            ["TalkActionId"] = {
                [1] = "82401:Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Baiheng/vo_topic_01_3",
            },
        [90110106] = {
            ["Content"] = "……真是沉重的使命啊。",
            ["ContentFR"] = "... Un fardeau bien lourd à porter.",
            ["DialogueId"] = 90110106,
            ["GUID"] = "E194C8F2",
            ["NextDialogue"] = 90110107,
            ["SpeakNpcId"] = 100001,
            },
        [90110107] = {
            ["Content"] = "枯荣阁虽然已是岁月的一件遗物，但在治病救人的道路上，永远不缺后继者。即便使命沉重，总有人会肩负起这份责任，矢志不渝地走下去。",
            ["ContentFR"] = "Le Pavillon de l’Éphémère n’est aujourd’hui plus qu’un souvenir, mais la vocation de guérir ne s’éteint jamais. Il y aura toujours ceux qui porteront cette mission jusqu’au bout, avec une détermination inébranlable.",
            ["DialogueId"] = 90110107,
            ["GUID"] = "E194C8F3",
            ["NextOptions"] = {
                [1] = 90110002,
                [2] = 90110003,
                },
            ["SpeakNpcId"] = 82401,
            ["VoiceName"] = "voice/$Locale$/char/Baiheng/vo_topic_01_4",
            ["bForbidSkipOptions"] = true,
            },
        [90110201] = {
            ["Content"] = "愿世间再无“无药可医”的顽疾。",
            ["ContentFR"] = "Je rêve d’un monde sans maladies incurables.",
            ["DialogueId"] = 90110201,
            ["GUID"] = "E194D8DA",
            ["LookAt"] = {
                [1] = "82401:n(0)",
                [2] = "0:n(82401)",
                },
            ["NextDialogue"] = 90110203,
            ["SpeakNpcId"] = 82401,
            ["TalkActionId"] = {
                [1] = "82401:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Baiheng/vo_topic_04_1",
            },
        [90110203] = {
            ["Content"] = "好宏大的梦想……",
            ["ContentFR"] = "C'est un rêve assez ambitieux...",
            ["DialogueId"] = 90110203,
            ["GUID"] = "E194D92E",
            ["NextDialogue"] = 90110204,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "82401:Explain02_End",
                },
            },
        [90110204] = {
            ["Content"] = "听起来与空想无异吧？但即使没有术法带来的奇迹，医师所要做的事也从未改变。这样的话由我这个医书都未读通的人说出口，实在贻笑大方。",
            ["ContentFR"] = "C’est peut-être utopique, mais même sans miracles, la vocation du guérisseur ne change pas. Dire ça alors que je peine à comprendre les ouvrages médicaux...",
            ["DialogueId"] = 90110204,
            ["GUID"] = "E194D958",
            ["NextDialogue"] = 90110205,
            ["SpeakNpcId"] = 82401,
            ["TalkActionId"] = {
                [1] = "82401:Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Baiheng/vo_topic_04_2",
            },
        [90110205] = {
            ["Content"] = "但……我会继续在这条路上走下去，不止是为了黎民百姓，为了枯荣阁，也是为了我自己。",
            ["ContentFR"] = "Pourtant, je suivrai ce chemin, pour les gens, pour le Pavillon de l’Éphémère, et pour moi-même aussi.",
            ["DialogueId"] = 90110205,
            ["GUID"] = "E194D982",
            ["NextOptions"] = {
                [1] = 90110002,
                [2] = 90110003,
                },
            ["SpeakNpcId"] = 82401,
            ["TalkActionId"] = {
                [1] = "82401:Talk02_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Baiheng/vo_topic_04_3",
            ["bForbidSkipOptions"] = true,
            },
        [90110301] = {
            ["Content"] = "一个治病救人的地方。",
            ["ContentFR"] = "Un endroit pour soigner et sauver des vies.",
            ["DialogueId"] = 90110301,
            ["GUID"] = "E194E942",
            ["LookAt"] = {
                [1] = "82401:n(0)",
                [2] = "0:n(82401)",
                },
            ["NextDialogue"] = 90110303,
            ["SpeakNpcId"] = 82401,
            ["TalkActionId"] = {
                [1] = "82401:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Baiheng/vo_topic_03_1",
            },
        [90110303] = {
            ["Content"] = "还有别的吗？",
            ["ContentFR"] = "Peux-tu m'en dire plus à ce sujet ?",
            ["DialogueId"] = 90110303,
            ["GUID"] = "E194E944",
            ["NextDialogue"] = 90110304,
            ["SpeakNpcId"] = 100001,
            },
        [90110304] = {
            ["Content"] = "枯荣阁的使命，仅此而已。若说其他……每位入枯荣阁修行的医师，都要手植杏树一株，只是岁月流逝，风雨摧折，留存至今的已不足半数。",
            ["ContentFR"] = "Sa mission est unique : guérir. Chaque médecin plante un abricotier en commençant sa formation. Cependant, au fil du temps, les intempéries ont emporté beaucoup d'entre eux. Aujourd’hui, il en reste moins de la moitié.",
            ["DialogueId"] = 90110304,
            ["GUID"] = "E194E943",
            ["NextDialogue"] = 90110305,
            ["SpeakNpcId"] = 82401,
            ["TalkActionId"] = {
                [1] = "82401:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Baiheng/vo_topic_03_2",
            },
        [90110305] = {
            ["Content"] = "从长眠中苏醒后，我也曾去寻找回忆里那株属于我的杏树，但天不垂怜，花树已成枯木，今春虽暖，也未曾发出新芽来。",
            ["ContentFR"] = "Après un long sommeil, je me suis éveillée et suis partie à la recherche de l’abricotier que j’avais planté dans ma jeunesse. Hélas, il n’était plus qu’un bois desséché. Même ce printemps si doux n’a su lui faire renaître le moindre bourgeon.",
            ["DialogueId"] = 90110305,
            ["GUID"] = "E194E945",
            ["NextDialogue"] = 90110306,
            ["SpeakNpcId"] = 82401,
            ["TalkActionId"] = {
                [1] = "82401:Explain01_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Baiheng/vo_topic_03_3",
            },
        [90110306] = {
            ["Content"] = "叹隙中驹，石中火，梦中身，几时归去，空作闲人。过去的已无法挽留，就算想要弥补，也再无可能了。",
            ["ContentFR"] = "La vie s’écoule en un éclair, un cheval lancé au galop dans un défilé étroit, une étincelle jaillie d’un silex, une ombre qui erre dans un rêve. Comment retrouver sa route au cœur d’une existence si fugace ? Le passé s’éloigne un peu plus chaque jour, et les espoirs de réparer ce qui fut s’effacent comme la brume aux premières lueurs du matin.",
            ["DialogueId"] = 90110306,
            ["GUID"] = "E194E946",
            ["NextOptions"] = {
                [1] = 90110002,
                [2] = 90110003,
                },
            ["SpeakNpcId"] = 82401,
            ["VoiceName"] = "voice/$Locale$/char/Baiheng/vo_topic_03_4",
            ["bForbidSkipOptions"] = true,
            },
        [90110401] = {
            ["Content"] = "人死如灯灭，一切痕迹湮没，一切声息断绝。那种与世隔绝的寂静会吞没一切希望与可能，如果可以，我不希望任何一个病人落入那种境地。",
            ["ContentFR"] = "La mort est semblable à une lampe qui s’éteint : toutes les traces s’effacent, toutes les voix se taisent. Cet isolement, ce silence profond, engloutit toute lueur d’espoir et toute possibilité. Si cela était en mon pouvoir, je ne laisserais aucun patient sombrer dans un tel néant.",
            ["DialogueId"] = 90110401,
            ["GUID"] = "E194F9AA",
            ["LookAt"] = {
                [1] = "82401:n(0)",
                [2] = "0:n(82401)",
                },
            ["NextDialogue"] = 90110403,
            ["SpeakNpcId"] = 82401,
            ["TalkActionId"] = {
                [1] = "82401:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Baiheng/vo_topic_02_1",
            },
        [90110403] = {
            ["Content"] = "听起来，就像扶疏亲身体验过一样。",
            ["ContentFR"] = "On dirait presque que tu l’as vécu toi-même.",
            ["DialogueId"] = 90110403,
            ["GUID"] = "E194F9FE",
            ["NextDialogue"] = 90110404,
            ["SpeakNpcId"] = 100001,
            },
        [90110404] = {
            ["Content"] = "的确如你所说，我……曾经从一场重病中逃出生天。假使让我再次面对这样的考验，我也不知道自己是否还会坚持当初的选择。",
            ["ContentFR"] = "En effet, j’ai autrefois frôlé la mort, terrassée par une grave maladie. Si une telle épreuve devait se représenter, je ne saurais dire avec certitude si je referais le même choix.",
            ["DialogueId"] = 90110404,
            ["GUID"] = "E194FA28",
            ["NextOptions"] = {
                [1] = 90110002,
                [2] = 90110003,
                },
            ["SpeakNpcId"] = 82401,
            ["TalkActionId"] = {
                [1] = "82401:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Baiheng/vo_topic_02_2",
            ["bForbidSkipOptions"] = true,
            },
        [90110501] = {
            ["Content"] = "兰迪先生，依我看来，懒惰散漫也是身患疾病的一种表现，如今虽一时无恙，但毕竟也是个隐患。不如我来陪你过上两招，活动活动筋骨，可好？",
            ["ContentFR"] = "Monsieur Randy, à mon humble avis, la léthargie et le laxisme ne sont pas moins des symptômes de maladie. Ils ne vous dérangent peut-être pas pour l'instant, mais ils sèment les graines de futurs maux. Peut-être pourrions-nous faire un peu d’entraînement physique ? Un peu d'exercice pourrait vous faire du bien.",
            ["DialogueId"] = 90110501,
            ["GUID"] = "E1950A12",
            ["SpeakNpcId"] = 82401,
            ["VoiceName"] = "voice/$Locale$/char/Baiheng/vo_companio_01",
            },
        [90110601] = {
            ["Content"] = "医者疗疾，却终究无法逆天改命。我可以为您开一贴缓解心热的药方，但病因却无法根除，但愿您能顺天应时，自渡为好……",
            ["ContentFR"] = "Si un guérisseur peut soulager la souffrance, défier le destin est au-delà de nos capacités. Je peux vous offrir un remède pour apaiser la chaleur de votre cœur, mais la cause profonde de vos problèmes échappe à mon contrôle. Il vaut mieux accepter et s’adapter au cours du temps pour trouver votre propre chemin vers le réconfort...",
            ["DialogueId"] = 90110601,
            ["GUID"] = "E1951A7A",
            ["SpeakNpcId"] = 82401,
            ["VoiceName"] = "voice/$Locale$/char/Baiheng/vo_companio_02",
            },
        [90110701] = {
            ["Content"] = "有时会听到另一个人在说话？只有你能听见吗？近日睡眠如何？是否心有郁结？最怕心病难医，即使用上祝由术也无能为力，但身为医者，我必定竭尽全力。",
            ["ContentFR"] = "Vous entendez souvent une autre voix qui vous parle ? Les autres l’entendent-ils aussi ? Comment se passe votre sommeil ? Quelque chose vous pèse-t-il sur le cœur ? Les afflictions de l’esprit sont les plus difficiles à guérir, même avec l’aide des techniques Zhuyou. Mais en tant que guérisseuse, je ne ménagerai aucun effort.",
            ["DialogueId"] = 90110701,
            ["GUID"] = "E1952AE2",
            ["SpeakNpcId"] = 82401,
            ["VoiceName"] = "voice/$Locale$/char/Baiheng/vo_companio_03",
            },
        [90120000] = {
            ["Content"] = "休息一会儿吧，榛子，吃点小麦，吃点坚果。再来上几朵花当零食，要是吃不完的话，我就先插在帽子上。",
            ["ContentFR"] = "Pause goûter, Filbert ! Un peu de blé, quelques noix... et hop, des fleurs pour grignoter. Et si t’as plus faim, je les mettrai sur mon chapeau !",
            ["DialogueId"] = 90120000,
            ["GUID"] = "E19B20A9",
            ["SpeakNpcId"] = 85101,
            ["VoiceName"] = "voice/$Locale$/char/Songlu/vo_idle",
            },
        [90120001] = {
            ["Content"] = "太阳热气腾腾，云朵松软蓬蓬，早起的鸟儿吃个饱饱。你的肚子有没有像鸟儿一样咕咕叫呢？",
            ["ContentFR"] = "Le soleil brille fort, les nuages sont tout doux, et les petits oiseaux ont bien mangé. Est-ce que ton ventre fait aussi des petits bruits ? On va manger quelque chose ?",
            ["DialogueId"] = 90120001,
            ["GUID"] = "E19B20AA",
            ["LookAt"] = {
                [1] = "85101:n(0)",
                [2] = "0:n(85101)",
                },
            ["NextOptions"] = {
                [1] = 901200011,
                [2] = 901200012,
                [3] = 901200013,
                [4] = 901200014,
                [5] = 901200015,
                },
            ["RandomOptionNum"] = 3,
            ["SpeakNpcId"] = 85101,
            ["TalkActionId"] = {
                [1] = "85101:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Songlu/vo_welcome",
            ["bForbidSkipOptions"] = true,
            },
        [90120002] = {
            ["Content"] = "聊点别的",
            ["ContentFR"] = "<I>Parlons d’autre chose.</>",
            ["DialogueId"] = 90120002,
            ["GUID"] = "90120002.0",
            ["NextDialogue"] = 90120001,
            },
        [90120003] = {
            ["Content"] = "再见",
            ["ContentFR"] = "<I>À bientôt.</>",
            ["DialogueId"] = 90120003,
            ["GUID"] = "90120003.0",
            },
        [90120101] = {
            ["Content"] = "咦？你不知道吗？粮秣专员就是负责填饱大家肚子的人哦，每天都要和各种食物打交道。",
            ["ContentFR"] = "Hein ? Tu sais pas ? Moi, je fais en sorte que tout le monde ait à manger tous les jours, avec plein de bonnes choses !",
            ["DialogueId"] = 90120101,
            ["GUID"] = "E19B3112",
            ["LookAt"] = {
                [1] = "85101:n(0)",
                [2] = "0:n(85101)",
                },
            ["NextDialogue"] = 90120103,
            ["SpeakNpcId"] = 85101,
            ["TalkActionId"] = {
                [1] = "85101:Confident_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Songlu/vo_topic_01_1",
            },
        [90120103] = {
            ["Content"] = "比如我的话，就会去野外收集各种各样的食物，让榛子驮回城里，然后再去委托面包店的胡子叔叔做成吃的，分给大家。",
            ["ContentFR"] = "Par exemple, je vais chercher plein de choses dans la nature, et Filbert les ramène en ville. Après, on demande à Monsieur Barbe, le boulanger, de préparer des bons petits plats pour tout le monde.",
            ["DialogueId"] = 90120103,
            ["GUID"] = "E19B3166",
            ["NextDialogue"] = 90120104,
            ["SpeakNpcId"] = 85101,
            ["VoiceName"] = "voice/$Locale$/char/Songlu/vo_topic_01_2",
            },
        [90120104] = {
            ["Content"] = "顺带一说，和那位胡子叔叔讨价还价，也是我的工作！哼哼。",
            ["ContentFR"] = "Et devine quoi ? Marchander avec Monsieur Barbe, c’est aussi mon boulot ! Hé hé.",
            ["DialogueId"] = 90120104,
            ["GUID"] = "E19B3190",
            ["NextDialogue"] = 90120105,
            ["SpeakNpcId"] = 85101,
            ["TalkActionId"] = {
                [1] = "85101:Confident_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Songlu/vo_topic_01_3",
            },
        [90120105] = {
            ["Content"] = "哇！听起来很厉害，不过所有的粮秣专员的工作都是这样的吗？",
            ["ContentFR"] = "Ouah, ça a l’air super ! C’est comme ça pour tous les commissaires au ravitaillement ?",
            ["DialogueId"] = 90120105,
            ["GUID"] = "E19B31BA",
            ["NextDialogue"] = 90120106,
            ["SpeakNpcId"] = 100001,
            },
        [90120106] = {
            ["Content"] = "那当然不是啦，其他的粮秣官好像都是一些脑子很好的家伙，写什么手续呀文书呀申请呀，然后就会有火车头拖着小山一样的吃的过来。",
            ["ContentFR"] = "Ah non, pas du tout ! Les autres, ils sont plus à faire des papiers, des demandes, et puis après, plein de nourriture arrive par train.",
            ["DialogueId"] = 90120106,
            ["GUID"] = "E19B31E4",
            ["NextDialogue"] = 90120107,
            ["SpeakNpcId"] = 85101,
            ["TalkActionId"] = {
                [1] = "85101:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Songlu/vo_topic_01_4",
            },
        [90120107] = {
            ["Content"] = "不过，我住的镇子上人不是很多，有我和榛子就够啦！否则可能我就也得去学怎么写那些什么申请书之类的，唉，谁懂那些啊。",
            ["ContentFR"] = "Mais dans notre petite ville, moi et Filbert, ça suffit ! Sinon, il faudrait que j’apprenne à faire les papiers… et c’est trop compliqué pour moi !",
            ["DialogueId"] = 90120107,
            ["GUID"] = "E19B320E",
            ["NextOptions"] = {
                [1] = 90120002,
                [2] = 90120003,
                },
            ["SpeakNpcId"] = 85101,
            ["VoiceName"] = "voice/$Locale$/char/Songlu/vo_topic_01_5",
            ["bForbidSkipOptions"] = true,
            },
        [90120201] = {
            ["Content"] = "诶？会吧……没太想过，不过反正榛子撞飞的一定都是那些喜欢哇哇乱叫，打来打去的坏家伙！是他们活该！",
            ["ContentFR"] = "Bah, peut-être ? Je ne sais pas trop. Mais Filbert ne fonce que sur les vilains qui crient et se bagarrent ! Ils l'ont bien cherché !",
            ["DialogueId"] = 90120201,
            ["GUID"] = "E19B417A",
            ["LookAt"] = {
                [1] = "85101:n(0)",
                [2] = "0:n(85101)",
                },
            ["NextDialogue"] = 90120203,
            ["SpeakNpcId"] = 85101,
            ["TalkActionId"] = {
                [1] = "85101:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Songlu/vo_topic_02_1",
            },
        [90120203] = {
            ["Content"] = "这些家伙，打打杀杀后又会叫饿连天。有挥武器的劲头不如多垦一会儿地啦，这样才会有更多人吃饱。",
            ["ContentFR"] = "Ces vilains se battent et ont toujours faim après. Ils feraient mieux de cultiver la terre, comme ça y’aurait plus de nourriture pour tout le monde.",
            ["DialogueId"] = 90120203,
            ["GUID"] = "E19B41CE",
            ["NextDialogue"] = 90120204,
            ["SpeakNpcId"] = 85101,
            ["TalkActionId"] = {
                [1] = "85101:Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Songlu/vo_topic_02_2",
            },
        [90120204] = {
            ["Content"] = "所以你也很讨厌战争喽？",
            ["ContentFR"] = "Du coup, tu détestes la guerre, hein ?",
            ["DialogueId"] = 90120204,
            ["GUID"] = "E19B41F8",
            ["NextDialogue"] = 90120205,
            ["SpeakNpcId"] = 100001,
            },
        [90120205] = {
            ["Content"] = "那是当然！战斗是饥饿之母，是坏家伙！听说一旦遇到战争，那么大家都会饿肚子，非常讨厌！希望我不要遇上就是了。",
            ["ContentFR"] = "Évidemment que je déteste ça ! Se battre, ça finit toujours par creuser l’estomac... et c’est pas drôle du tout. On m’a dit qu’en temps de guerre, personne ne mange à sa faim. J’espère que ça m’arrivera jamais.",
            ["DialogueId"] = 90120205,
            ["GUID"] = "E19B4222",
            ["NextDialogue"] = 90120206,
            ["SpeakNpcId"] = 85101,
            ["TalkActionId"] = {
                [1] = "85101:Confident_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Songlu/vo_topic_02_3",
            },
        [90120206] = {
            ["Content"] = "真要遇到战争，就骑上榛子，撞飞开战的坏人。",
            ["ContentFR"] = "Si la guerre éclate, tu pourrais grimper sur Filbert et foncer sur les vilains.",
            ["DialogueId"] = 90120206,
            ["GUID"] = "E19B424C",
            ["NextDialogue"] = 90120207,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "85101:Confident_End",
                },
            },
        [90120207] = {
            ["Content"] = "没错，谁让人饿肚子，谁就迟早会被榛子撞飞！",
            ["ContentFR"] = "Oui ! Tous ceux qui affament les autres finiront tous par se faire renverser par Filbert !",
            ["DialogueId"] = 90120207,
            ["GUID"] = "E19B4276",
            ["NextOptions"] = {
                [1] = 90120002,
                [2] = 90120003,
                },
            ["SpeakNpcId"] = 85101,
            ["TalkActionId"] = {
                [1] = "85101:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Songlu/vo_topic_02_4",
            ["bForbidSkipOptions"] = true,
            },
        [90120301] = {
            ["Content"] = "是不少啦，不过其实不用特别为她准备吃的，她会自己找的。哪怕隔着几条小溪，榛子也能闻到熟透浆果的味道，然后驮着我飞奔过去，可能干啦。",
            ["ContentFR"] = "Oui, elle mange pas mal, mais elle trouve sa propre nourriture. Même à travers plusieurs ruisseaux, elle sent les baies mûres et me porte pour qu’on aille les chercher. Incroyable, non ?",
            ["DialogueId"] = 90120301,
            ["GUID"] = "E19B51E2",
            ["LookAt"] = {
                [1] = "85101:n(0)",
                [2] = "0:n(85101)",
                },
            ["NextDialogue"] = 90120303,
            ["SpeakNpcId"] = 85101,
            ["TalkActionId"] = {
                [1] = "85101:Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Songlu/vo_topic_03_1",
            },
        [90120303] = {
            ["Content"] = "那还好，不用担心破产了。",
            ["ContentFR"] = "Génial. Il n'y a donc pas besoin de s’inquiéter pour les provisions.",
            ["DialogueId"] = 90120303,
            ["GUID"] = "E19B5236",
            ["NextDialogue"] = 90120304,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "85101:Talk02_End",
                },
            },
        [90120304] = {
            ["Content"] = "别担心别担心，榛子只会带来食物，不会吃垮这里的！所以，一定一定不要拿榛子开玩笑哦，她听到的话会伤心的，我也会。",
            ["ContentFR"] = "T’en fais pas ! Filbert apporte toujours plus de nourriture. Alors ne te moque jamais d'elle, ça la blesserait, et moi aussi.",
            ["DialogueId"] = 90120304,
            ["GUID"] = "E19B5260",
            ["NextOptions"] = {
                [1] = 90120002,
                [2] = 90120003,
                },
            ["SpeakNpcId"] = 85101,
            ["TalkActionId"] = {
                [1] = "85101:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Songlu/vo_topic_03_2",
            ["bForbidSkipOptions"] = true,
            },
        [90120401] = {
            ["Content"] = "谢谢夸奖，不过我要纠正一下，这其实是裤子。一开始倒的确是裙子，白色的，长长的，可好看啦。是裁缝店的婆婆帮我改成了裤子。",
            ["ContentFR"] = "Merci ! Mais ce sont des shorts, pas une robe. Avant, c’était une belle robe blanche longue, mais la couturière me l’a changé en short.",
            ["DialogueId"] = 90120401,
            ["GUID"] = "E19B624A",
            ["LookAt"] = {
                [1] = "85101:n(0)",
                [2] = "0:n(85101)",
                },
            ["NextDialogue"] = 90120403,
            ["SpeakNpcId"] = 85101,
            ["TalkActionId"] = {
                [1] = "85101:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Songlu/vo_topic_04_1",
            },
        [90120403] = {
            ["Content"] = "为什么呀？",
            ["ContentFR"] = "Pourquoi ?",
            ["DialogueId"] = 90120403,
            ["GUID"] = "E19B629E",
            ["NextDialogue"] = 90120404,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "85101:Explain01_End",
                },
            },
        [90120404] = {
            ["Content"] = "因为穿着裙子到处跑太不方便啦，有一次我跑得快了，都被裙摆绊倒，手里的面包都撒了。",
            ["ContentFR"] = "Parce que courir en robe, c’est pas pratique. Une fois, j'ai trébuché sur l'ourlet et tout le pain que je portais est tombé.",
            ["DialogueId"] = 90120404,
            ["GUID"] = "E19B62C8",
            ["NextDialogue"] = 90120405,
            ["SpeakNpcId"] = 85101,
            ["TalkActionId"] = {
                [1] = "85101:Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Songlu/vo_topic_04_2",
            },
        [90120405] = {
            ["Content"] = "所以，哎……要是哪天，没有人挨饿了，我就拜托婆婆再把这条裤子改回去！",
            ["ContentFR"] = "Donc, si un jour personne n’a plus faim, je les ferai changer à nouveau en robe !",
            ["DialogueId"] = 90120405,
            ["GUID"] = "E19B62F2",
            ["NextOptions"] = {
                [1] = 90120002,
                [2] = 90120003,
                },
            ["SpeakNpcId"] = 85101,
            ["TalkActionId"] = {
                [1] = "85101:Talk01_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Songlu/vo_topic_04_3",
            ["bForbidSkipOptions"] = true,
            },
        [90120501] = {
            ["Content"] = "才不是发呆，是在冥想。不管怎么说我都是传颂会的一员，所以偶尔也会像这样用力想事情的。",
            ["ContentFR"] = "Pas du tout ! Je médite. Je fais partie de l’Église Élyséenne, après tout, alors j'essaie de réfléchir profondément de temps en temps.",
            ["DialogueId"] = 90120501,
            ["GUID"] = "E19B72B2",
            ["LookAt"] = {
                [1] = "85101:n(0)",
                [2] = "0:n(85101)",
                },
            ["NextDialogue"] = 90120503,
            ["SpeakNpcId"] = 85101,
            ["TalkActionId"] = {
                [1] = "85101:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Songlu/vo_topic_05_1",
            },
        [90120503] = {
            ["Content"] = "那在想什么呢？为什么没有吃饱饭之神？",
            ["ContentFR"] = "Tu pensais à quoi ? Pourquoi il n’y a pas de dieu des ventres pleins ?",
            ["DialogueId"] = 90120503,
            ["GUID"] = "E19B7306",
            ["NextDialogue"] = 90120504,
            ["SpeakNpcId"] = 100001,
            },
        [90120504] = {
            ["Content"] = "之前想过，不过修士们说，想这种事情是什么读……神？所以我就不想这些了。",
            ["ContentFR"] = "Je me posais souvent la question, mais les prêtres disait que c'était... blasphématoire ou quelque chose comme ça. Alors j'ai arrêté d'y penser.",
            ["DialogueId"] = 90120504,
            ["GUID"] = "E19B7330",
            ["NextDialogue"] = 90120505,
            ["SpeakNpcId"] = 85101,
            ["TalkActionId"] = {
                [1] = "85101:Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Songlu/vo_topic_05_2",
            },
        [90120505] = {
            ["Content"] = "唉，修士们的话我总是听得半懂不懂的，比如他们总是说贪吃是非常非常严重的罪过……可是好像越是大吃大喝的人，地位就越高哦。",
            ["ContentFR"] = "J’ai jamais trop compris ce qu’ils racontent... Ils disent que la gourmandise, c’est un péché grave, mais plus t’es important, plus tu manges.",
            ["DialogueId"] = 90120505,
            ["GUID"] = "E19B735A",
            ["NextOptions"] = {
                [1] = 90120002,
                [2] = 90120003,
                },
            ["SpeakNpcId"] = 85101,
            ["TalkActionId"] = {
                [1] = "85101:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Songlu/vo_topic_05_3",
            ["bForbidSkipOptions"] = true,
            },
        [90120601] = {
            ["Content"] = "你在垃圾桶里翻到了发了芽的土豆？不要扔不要扔，我们把它种起来，松松土、浇浇水，就会有好多好多土豆可以吃啦！",
            ["ContentFR"] = "Tu as trouvé des patates qui germent dans le bac ? Ne les jette pas ! On les plante, on les arrose, et on aura plein de patates pour tout le monde !",
            ["DialogueId"] = 90120601,
            ["GUID"] = "E19B831A",
            ["SpeakNpcId"] = 85101,
            ["VoiceName"] = "voice/$Locale$/char/Songlu/vo_companio_01",
            },
        [90120701] = {
            ["Content"] = "一直忙着干活，不饿吗？要不要加入传颂会，我会喂饱你的！",
            ["ContentFR"] = "Tu travailles tout le temps... T’as pas un petit creux ? Tu devrais rejoindre l’Église ! Moi, je prends soin des ventres vides.",
            ["DialogueId"] = 90120701,
            ["GUID"] = "E19B9382",
            ["SpeakNpcId"] = 85101,
            ["VoiceName"] = "voice/$Locale$/char/Songlu/vo_companio_02",
            },
        [90120801] = {
            ["Content"] = "你好你好，我想请教一下……据说祈祷可以让人的灵魂感到满足，我觉得吃饭也可以，那么吃饭和祈祷哪个更管用呀？",
            ["ContentFR"] = "Coucou ! Dis, c’est vrai que prier, ça remplit l’âme ? Moi je trouve qu’un bon repas, ça marche pareil ! Tu préfères quoi, toi ?",
            ["DialogueId"] = 90120801,
            ["GUID"] = "E19BA3EA",
            ["SpeakNpcId"] = 85101,
            ["VoiceName"] = "voice/$Locale$/char/Songlu/vo_companio_03",
            },
        [90130000] = {
            ["Content"] = "……还好，这个月的钱一分不少，还以为真的被兰迪那扣光了……嗯，这些寄回家里，剩下的生活费应该还够用。",
            ["ContentFR"] = "Pas mal. Je devrais avoir assez pour ce mois. Je pensais que ce foutu Randy allait tout me piquer. Je renvoie le reste à la maison, ça devrait suffire pour vivre.",
            ["DialogueId"] = 90130000,
            ["GUID"] = "E1A18949",
            ["SpeakNpcId"] = 83101,
            ["VoiceName"] = "voice/$Locale$/char/Linen/vo_idle",
            },
        [90130001] = {
            ["Content"] = "有事快说，没有我就出任务去。",
            ["ContentFR"] = "Tu as besoin de quelque chose ? Parle vite, j’ai une mission à finir.",
            ["DialogueId"] = 90130001,
            ["GUID"] = "E1A1894A",
            ["LookAt"] = {
                [1] = "83101:n(0)",
                [2] = "0:n(83101)",
                },
            ["NextOptions"] = {
                [1] = 901300011,
                [2] = 901300012,
                [3] = 901300013,
                [4] = 901300014,
                },
            ["RandomOptionNum"] = 3,
            ["SpeakNpcId"] = 83101,
            ["VoiceName"] = "voice/$Locale$/char/Linen/vo_welcome",
            ["bForbidSkipOptions"] = true,
            },
        [90130002] = {
            ["Content"] = "聊点别的",
            ["ContentFR"] = "<I>Parlons d’autre chose.</>",
            ["DialogueId"] = 90130002,
            ["GUID"] = "90130002.0",
            ["NextDialogue"] = 90130001,
            },
        [90130003] = {
            ["Content"] = "再见",
            ["ContentFR"] = "<I>À bientôt.</>",
            ["DialogueId"] = 90130003,
            ["GUID"] = "90130003.0",
            },
        [90130101] = {
            ["Content"] = "西比尔长官？她是十三军团的军团长。",
            ["ContentFR"] = "Sibylle ? C’est la commandante de la XIIIᵉ Légion.",
            ["DialogueId"] = 90130101,
            ["GUID"] = "E1A199B2",
            ["LookAt"] = {
                [1] = "83101:n(0)",
                [2] = "0:n(83101)",
                },
            ["NextDialogue"] = 90130103,
            ["SpeakNpcId"] = 83101,
            ["TalkActionId"] = {
                [1] = "83101:Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Linen/vo_topic_01_1",
            },
        [90130103] = {
            ["Content"] = "还有什么？",
            ["ContentFR"] = "Et ?",
            ["DialogueId"] = 90130103,
            ["GUID"] = "E1A199B3",
            ["NextDialogue"] = 90130104,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "83101:Talk03_End",
                },
            },
        [90130104] = {
            ["Content"] = "啧，我上哪知道那么多，她是上司，她下命令，我办事，就行了。",
            ["ContentFR"] = "Pff, qu’est-ce que tu veux que je sache ? C’est elle qui décide, moi je fais le boulot. C’est tout.",
            ["DialogueId"] = 90130104,
            ["GUID"] = "E1A199B4",
            ["NextOptions"] = {
                [1] = 90130002,
                [2] = 90130003,
                },
            ["SpeakNpcId"] = 83101,
            ["VoiceName"] = "voice/$Locale$/char/Linen/vo_topic_01_2",
            ["bForbidSkipOptions"] = true,
            },
        [90130201] = {
            ["Content"] = "经验？什么经验，我的经验就是没有拳头解决不了的问题，如果有，那就再来一拳。",
            ["ContentFR"] = "Des conseils ? Le seul que je connais, c’est qu’il n’y a aucun problème qu’un bon coup de poing ne puisse résoudre. Et si ça ne suffit pas, frappe encore.",
            ["DialogueId"] = 90130201,
            ["GUID"] = "E1A1AA1A",
            ["LookAt"] = {
                [1] = "83101:n(0)",
                [2] = "0:n(83101)",
                },
            ["NextDialogue"] = 90130203,
            ["SpeakNpcId"] = 83101,
            ["TalkActionId"] = {
                [1] = "83101:Confident_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Linen/vo_topic_02_1",
            },
        [90130203] = {
            ["Content"] = "两拳也不行呢？",
            ["ContentFR"] = "Et si deux coups de poing ne suffisent pas non plus ?",
            ["DialogueId"] = 90130203,
            ["GUID"] = "E1A1AA6E",
            ["NextDialogue"] = 90130204,
            ["SpeakNpcId"] = 100001,
            },
        [90130204] = {
            ["Content"] = "那就再补上一枪。",
            ["ContentFR"] = "Dans ce cas, une balle suffit généralement.",
            ["DialogueId"] = 90130204,
            ["GUID"] = "E1A1AA98",
            ["NextDialogue"] = 90130205,
            ["SpeakNpcId"] = 83101,
            ["TalkActionId"] = {
                [1] = "83101:Confident_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Linen/vo_topic_02_2",
            },
        [90130205] = {
            ["Content"] = "不是听说有人能中一枪也不死吗？",
            ["ContentFR"] = "Mais j'ai entendu dire que certaines personnes peuvent encaisser une balle sans mourir.",
            ["DialogueId"] = 90130205,
            ["GUID"] = "E1A1AAC2",
            ["NextDialogue"] = 90130206,
            ["SpeakNpcId"] = 100001,
            },
        [90130206] = {
            ["Content"] = "哎，我这就是打比方，只要拳头够硬枪够准，比什么都好使，你要是再抬杠，我先给你两拳。",
            ["ContentFR"] = "Eh, c’est juste une façon de parler. Tant que tes poings sont solides et tes tirs précis, c’est tout ce qui compte. Si tu continues à chipoter, je t’en colle deux !",
            ["DialogueId"] = 90130206,
            ["GUID"] = "E1A1AAEC",
            ["NextOptions"] = {
                [1] = 90130002,
                [2] = 90130003,
                },
            ["SpeakNpcId"] = 83101,
            ["VoiceName"] = "voice/$Locale$/char/Linen/vo_topic_02_3",
            ["bForbidSkipOptions"] = true,
            },
        [90130301] = {
            ["Content"] = "前几天看到的那把枪真不错……算了，不能因为买它饿肚子，反正旧的用着更顺手些。",
            ["ContentFR"] = "J’ai vu un flingue sympa l’autre jour... Mais bon, pas question de crever la dalle pour ça. L’ancien fait encore l’affaire.",
            ["DialogueId"] = 90130301,
            ["GUID"] = "E1A1BA82",
            ["LookAt"] = {
                [1] = "83101:n(0)",
                [2] = "0:n(83101)",
                },
            ["NextDialogue"] = 90130303,
            ["SpeakNpcId"] = 83101,
            ["TalkActionId"] = {
                [1] = "83101:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Linen/vo_topic_03_1",
            },
        [90130303] = {
            ["Content"] = "要我想办法送你一把吗？",
            ["ContentFR"] = "Si tu l’aimes vraiment, je pourrais peut-être t'en obtenir un.",
            ["DialogueId"] = 90130303,
            ["GUID"] = "E1A1BAD6",
            ["NextDialogue"] = 90130304,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "83101:Think_End",
                },
            },
        [90130304] = {
            ["Content"] = "真的假……不对，你看着也不比我有钱……算了，我不怀疑你的好意，但你用不着破费，我不想欠无谓的人情。",
            ["ContentFR"] = "Vraiment ? T’as l’air aussi fauché que moi... J’apprécie, mais te ruine pas pour moi. Je veux rien devoir à personne.",
            ["DialogueId"] = 90130304,
            ["GUID"] = "E1A1BB00",
            ["NextOptions"] = {
                [1] = 90130002,
                [2] = 90130003,
                },
            ["SpeakNpcId"] = 83101,
            ["VoiceName"] = "voice/$Locale$/char/Linen/vo_topic_03_2",
            ["bForbidSkipOptions"] = true,
            },
        [90130401] = {
            ["Content"] = "不工作就没饭吃，这个道理不懂吗？",
            ["ContentFR"] = "Si je bosse pas, je mange pas. C’est clair, non ?",
            ["DialogueId"] = 90130401,
            ["GUID"] = "E1A1CAEA",
            ["LookAt"] = {
                [1] = "83101:n(0)",
                [2] = "0:n(83101)",
                },
            ["NextDialogue"] = 90130403,
            ["SpeakNpcId"] = 83101,
            ["TalkActionId"] = {
                [1] = "83101:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Linen/vo_topic_04_1",
            },
        [90130403] = {
            ["Content"] = "但劳逸结合也是很重要的呀。",
            ["ContentFR"] = "Tu sais, c’est important de te ménager un peu aussi.",
            ["DialogueId"] = 90130403,
            ["GUID"] = "E1A1CB3E",
            ["NextDialogue"] = 90130404,
            ["SpeakNpcId"] = 100001,
            },
        [90130404] = {
            ["Content"] = "我倒是想，但是那些雇主们可不这么想，隔三差五就问我委托做完没有，快点做之类，催催催，要不是我还有一家子人要养活，真想给他们来上几发。",
            ["ContentFR"] = "J’aimerais bien, mais les clients, eux, s’en fichent. Tous les deux jours, c’est \"Alors, c’est fini ?\", \"Dépêche-toi un peu !\"… Toujours à me harceler. Si j’avais pas une famille à nourrir, je leur aurais déjà collé quelques bastos.",
            ["DialogueId"] = 90130404,
            ["GUID"] = "E1A1CB68",
            ["NextOptions"] = {
                [1] = 90130002,
                [2] = 90130003,
                },
            ["SpeakNpcId"] = 83101,
            ["TalkActionId"] = {
                [1] = "83101:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Linen/vo_topic_04_2",
            ["bForbidSkipOptions"] = true,
            },
        [90130501] = {
            ["Content"] = "下次派任务能不能直说？唠唠叨叨的，烦死了。",
            ["ContentFR"] = "La prochaine fois, va droit au but, ok ? Tes bavardages, ça me gonfle.",
            ["DialogueId"] = 90130501,
            ["GUID"] = "E1A1DB52",
            ["SpeakNpcId"] = 83101,
            ["VoiceName"] = "voice/$Locale$/char/Linen/vo_companio_01",
            },
        [90130601] = {
            ["Content"] = "……长官好。",
            ["ContentFR"] = "Bonjour, madame...",
            ["DialogueId"] = 90130601,
            ["GUID"] = "E1A1EBBA",
            ["SpeakNpcId"] = 83101,
            ["VoiceName"] = "voice/$Locale$/char/Linen/vo_companio_02",
            },
        [90130701] = {
            ["Content"] = "你是优秀的士兵，仅此一句。哦，还有……好好工作之余，也得好好生活……啧，听完了还不快走？",
            ["ContentFR"] = "T’es un bon soldat, ça c’est dit. Et… profite un peu de la vie aussi, hein ? Allez, assez causé, va-t’en.",
            ["DialogueId"] = 90130701,
            ["GUID"] = "E1A1FC22",
            ["SpeakNpcId"] = 83101,
            ["VoiceName"] = "voice/$Locale$/char/Linen/vo_companio_03",
            },
        [90150000] = {
            ["Content"] = "我的小小的、小小的家……藏在树梢的新绿里，藏在金色的河流间……温暖的壁炉呀，小火苗噼啪噼啪……握着爸爸刚修好的锡兵，听妈妈唱起摇篮曲……睡吧……",
            ["ContentFR"] = "♪ Mon tout petit foyer... niché parmi les feuilles nouvelles, au creux d’un fleuve d’or... Le feu danse dans la cheminée, crépitant doucement... Je serre fort le soldat de plomb réparé par Papa, tandis que Maman me berce d’un chant... Dors maintenant...",
            ["DialogueId"] = 90150000,
            ["GUID"] = "E1AE5A8B",
            ["SpeakNpcId"] = 81801,
            ["VoiceName"] = "voice/$Locale$/char/Feina/vo_idle",
            },
        [90150001] = {
            ["Content"] = "……唔……是你。你好，你好呀。",
            ["ContentFR"] = "Ah, c’est toi. Bonjour, comment vas-tu ?",
            ["DialogueId"] = 90150001,
            ["GUID"] = "E1AE5A8A",
            ["NextOptions"] = {
                [1] = 901500011,
                [2] = 901500012,
                [3] = 901500013,
                [4] = 901500014,
                [5] = 901500015,
                },
            ["RandomOptionNum"] = 3,
            ["SpeakNpcId"] = 81801,
            ["VoiceName"] = "voice/$Locale$/char/Feina/vo_welcome",
            ["bForbidSkipOptions"] = true,
            },
        [90150002] = {
            ["Content"] = "聊点别的",
            ["ContentFR"] = "<I>Parlons d’autre chose.</>",
            ["DialogueId"] = 90150002,
            ["GUID"] = "90150002.0",
            ["NextDialogue"] = 90150001,
            },
        [90150003] = {
            ["Content"] = "再见",
            ["ContentFR"] = "<I>À bientôt.</>",
            ["DialogueId"] = 90150003,
            ["GUID"] = "90150003.0",
            },
        [90150101] = {
            ["Content"] = "唔，我想吃掉可以让人变得很大很大的糖果……",
            ["ContentFR"] = "Hmm, je me demandais... s’il existait un bonbon qui pourrait me faire énormément grandir...",
            ["DialogueId"] = 90150101,
            ["GUID"] = "E1AE6AF2",
            ["NextDialogue"] = 90150103,
            ["SpeakNpcId"] = 81801,
            ["VoiceName"] = "voice/$Locale$/char/Feina/vo_topic_01_1",
            },
        [90150103] = {
            ["Content"] = "吃下那样的糖果，我就会长得比云还高，可以摸一摸天上的星星了吧？",
            ["ContentFR"] = "Si grande que je pouvais voir au-dessus des nuages et même toucher les étoiles !",
            ["DialogueId"] = 90150103,
            ["GUID"] = "E1AE6B46",
            ["NextDialogue"] = 90150104,
            ["SpeakNpcId"] = 81801,
            ["VoiceName"] = "voice/$Locale$/char/Feina/vo_topic_01_2",
            },
        [90150104] = {
            ["Content"] = "会不会一不留神一脚把我踩扁了……",
            ["ContentFR"] = "Mais que se passerait-il si tu me marchais dessus accidentellement et m’aplatissais comme une crêpe...",
            ["DialogueId"] = 90150104,
            ["GUID"] = "E1AE6B70",
            ["NextDialogue"] = 90150105,
            ["SpeakNpcId"] = 100001,
            },
        [90150105] = {
            ["Content"] = "不会的，我会很小心的！嗯……如果你实在害怕的话，就坐在我的手心里，我带你出去兜风，怎么样？",
            ["ContentFR"] = "Ne t’inquiète pas, je ferai attention ! Et si tu as peur, tu peux te poser dans ma paume, et on ira faire un tour. Qu’en penses-tu ?",
            ["DialogueId"] = 90150105,
            ["GUID"] = "E1AE6B9A",
            ["NextOptions"] = {
                [1] = 90150002,
                [2] = 90150003,
                },
            ["SpeakNpcId"] = 81801,
            ["VoiceName"] = "voice/$Locale$/char/Feina/vo_topic_01_3",
            ["bForbidSkipOptions"] = true,
            },
        [90150201] = {
            ["Content"] = "我有一个很大很大的玻璃盒子，盒子里面装着窗户外软绵绵的雪，装着雪一样白白的棉花糖。我还想装进去棉花糖一样轻飘飘的云朵，云朵一样暖乎乎的风……",
            ["ContentFR"] = "J’ai une grande boîte en verre remplie de neige fine provenant de l’extérieur de ma fenêtre et de guimauves aussi blanches que la neige. J’aimerais également y mettre des nuages aussi moelleux que ces guimauves, et des brises aussi chaudes que ces nuages...",
            ["DialogueId"] = 90150201,
            ["GUID"] = "E1AE7B5A",
            ["NextDialogue"] = 90150203,
            ["SpeakNpcId"] = 81801,
            ["VoiceName"] = "voice/$Locale$/char/Feina/vo_topic_02_1",
            },
        [90150203] = {
            ["Content"] = "连同你们的笑声一起，全～都装进盒子。",
            ["ContentFR"] = "Et vos rires aussi, tous sans exception, enfermés dans la boîte.",
            ["DialogueId"] = 90150203,
            ["GUID"] = "E1AE7BAE",
            ["NextDialogue"] = 90150204,
            ["SpeakNpcId"] = 81801,
            ["VoiceName"] = "voice/$Locale$/char/Feina/vo_topic_02_2",
            },
        [90150204] = {
            ["Content"] = "真好啊，想钻进去。",
            ["ContentFR"] = "Ouah... ça doit être divin de se blottir à l'intérieur.",
            ["DialogueId"] = 90150204,
            ["GUID"] = "E1AE7BD8",
            ["NextDialogue"] = 90150205,
            ["SpeakNpcId"] = 100001,
            },
        [90150205] = {
            ["Content"] = "嗯……如果你能吃下让人变得很小很小的糖果，就可以进去玩啦。不过，这个盒子里到处都是白色的，你要小心，别在里面迷路哦。",
            ["ContentFR"] = "Eh bien... si tu croques un de ces bonbons qui te font tout petit, tu pourrais y entrer. Mais tout est blanc là-dedans, alors fais bien attention à ne pas te perdre.",
            ["DialogueId"] = 90150205,
            ["GUID"] = "E1AE7C02",
            ["NextDialogue"] = 90150206,
            ["SpeakNpcId"] = 81801,
            ["VoiceName"] = "voice/$Locale$/char/Feina/vo_topic_02_3",
            },
        [90150206] = {
            ["Content"] = "如果我迷路了，菲娜会来救我吗？",
            ["ContentFR"] = "Si je me perds là-bas, Fina viendra-t-elle me chercher ?",
            ["DialogueId"] = 90150206,
            ["GUID"] = "E1AE7C2C",
            ["NextDialogue"] = 90150207,
            ["SpeakNpcId"] = 100001,
            },
        [90150207] = {
            ["Content"] = "让我想想……如果你迷路了，菲娜就把面包掰成一小块一小块，连成一条路……这样，你只要沿着面包屑向前走，就能找到出口啦！",
            ["ContentFR"] = "Laisse-moi réfléchir... Si tu te perds, je casserai du pain en miettes, je ferai un chemin... Tu n’auras qu’à suivre les miettes pour retrouver la sortie !",
            ["DialogueId"] = 90150207,
            ["GUID"] = "E1AE7C56",
            ["NextOptions"] = {
                [1] = 90150002,
                [2] = 90150003,
                },
            ["SpeakNpcId"] = 81801,
            ["VoiceName"] = "voice/$Locale$/char/Feina/vo_topic_02_4",
            ["bForbidSkipOptions"] = true,
            },
        [90150301] = {
            ["Content"] = "嗯……！在梦里，我看到了一只纯白羽毛的夜莺，它一会儿落在我的手上，一会儿绕着屋子和我捉迷藏……唔……到底是我梦见了它，还是它梦见了我呢……",
            ["ContentFR"] = "Oui... ! J'ai rêvé d’un rossignol, pur comme la neige immaculée, qui se posait sur ma main un instant, puis jouait à cache-cache avec moi l’instant d’après... Hmm, est-ce moi qui ai rêvé, ou est-ce lui qui a rêvé de moi, je me le demande ?",
            ["DialogueId"] = 90150301,
            ["GUID"] = "E1AE8BC2",
            ["NextDialogue"] = 90150303,
            ["SpeakNpcId"] = 81801,
            ["VoiceName"] = "voice/$Locale$/char/Feina/vo_topic_03_1",
            },
        [90150303] = {
            ["Content"] = "也许是你们做了同一个梦呢？",
            ["ContentFR"] = "Peut-être que vous avez partagé un même rêve ?",
            ["DialogueId"] = 90150303,
            ["GUID"] = "E1AE8C16",
            ["NextDialogue"] = 90150304,
            ["SpeakNpcId"] = 100001,
            },
        [90150304] = {
            ["Content"] = "你说得对！也许那是一个仙境，所有睡着的孩子和小动物都可以在那里一起玩。嗯……下次的梦里会遇到谁呢？猫头鹰爷爷、金丝雀小姐，还是白兔先生？",
            ["ContentFR"] = "Tu as raison ! C’est peut-être un pays magique où tous les enfants et les petites bêtes endormis peuvent jouer ensemble. Hmm... Qui vais-je rencontrer dans mon prochain rêve ? Grand-père Hibou, Mademoiselle Canari, ou Monsieur Lapin ?",
            ["DialogueId"] = 90150304,
            ["GUID"] = "E1AE8C40",
            ["NextOptions"] = {
                [1] = 90150002,
                [2] = 90150003,
                },
            ["SpeakNpcId"] = 81801,
            ["VoiceName"] = "voice/$Locale$/char/Feina/vo_topic_03_2",
            ["bForbidSkipOptions"] = true,
            },
        [90150401] = {
            ["Content"] = "菲娜曾经有一个妈妈，两个爸爸。不过，他们都不在了……",
            ["ContentFR"] = "J’avais une maman et deux papas. Mais ils ne sont plus là...",
            ["DialogueId"] = 90150401,
            ["GUID"] = "E1AE9C2A",
            ["NextDialogue"] = 90150402,
            ["SpeakNpcId"] = 81801,
            ["VoiceName"] = "voice/$Locale$/char/Feina/vo_topic_04_1",
            },
        [90150402] = {
            ["Content"] = "第一个爸爸，和妈妈一起，去了很远很远的国度。第二个爸爸，也去了很远很远的国度……是我带他去的哦。",
            ["ContentFR"] = "Le premier papa est parti dans un pays lointain avec maman. Et le deuxième... il est aussi dans ce pays lointain... C’est moi qui l’ai envoyé là-bas.",
            ["DialogueId"] = 90150402,
            ["GUID"] = "E1AE9C54",
            ["NextOptions"] = {
                [1] = 90150002,
                [2] = 90150003,
                },
            ["SpeakNpcId"] = 81801,
            ["VoiceName"] = "voice/$Locale$/char/Feina/vo_topic_04_2",
            ["bForbidSkipOptions"] = true,
            },
        [90150501] = {
            ["Content"] = "他是最伟大的魔法师，是说话最好听的人，是全世界最温柔最温柔的人……",
            ["ContentFR"] = "Il est le plus grand magicien, avec la voix la plus apaisante et l’âme la plus douce au monde...",
            ["DialogueId"] = 90150501,
            ["GUID"] = "E1AEAC92",
            ["NextDialogue"] = 90150503,
            ["SpeakNpcId"] = 81801,
            ["VoiceName"] = "voice/$Locale$/char/Feina/vo_topic_05_1",
            },
        [90150503] = {
            ["Content"] = "？",
            ["ContentFR"] = "?",
            ["DialogueId"] = 90150503,
            ["GUID"] = "E1AEACE6",
            ["NextDialogue"] = 90150504,
            ["SpeakNpcId"] = 100001,
            },
        [90150504] = {
            ["Content"] = "唔，你看起来有很多很多问题，我哪里说的不对吗？",
            ["ContentFR"] = "Euh, qu’est-ce qui ne va pas ? Tu as l’air perplexe.",
            ["DialogueId"] = 90150504,
            ["GUID"] = "E1AEAD10",
            ["NextDialogue"] = 90150505,
            ["SpeakNpcId"] = 81801,
            ["VoiceName"] = "voice/$Locale$/char/Feina/vo_topic_05_2",
            },
        [90150505] = {
            ["Content"] = "和我认识的奥特赛德完全是两个人吧！",
            ["ContentFR"] = "Ce n’est pas du tout l’Étranger que je connais !",
            ["DialogueId"] = 90150505,
            ["GUID"] = "E1AEAD3A",
            ["NextDialogue"] = 90150506,
            ["SpeakNpcId"] = 100001,
            },
        [90150506] = {
            ["Content"] = "咦……？他对你说话不好听、不温柔吗？真对不起……我会敲敲他的脑袋，要他改正的！",
            ["ContentFR"] = "Hein... ? Il n’est pas gentil avec toi ? Je suis désolée... Je vais lui donner un petit coup sur la tête pour qu’il s’améliore !",
            ["DialogueId"] = 90150506,
            ["GUID"] = "E1AEAD64",
            ["NextOptions"] = {
                [1] = 90150002,
                [2] = 90150003,
                },
            ["SpeakNpcId"] = 81801,
            ["VoiceName"] = "voice/$Locale$/char/Feina/vo_topic_05_3",
            ["bForbidSkipOptions"] = true,
            },
        [90150601] = {
            ["Content"] = "答应菲娜，再也再也再也……不要去那些有很多很多坏巫师的危险地方了，好吗？",
            ["ContentFR"] = "Promets-moi que tu n’iras jamais, jamais, jamais... dans cet endroit effrayant où il y a plein de mauvais sorciers, d’accord ?",
            ["DialogueId"] = 90150601,
            ["GUID"] = "E1AEBCFA",
            ["SpeakNpcId"] = 81801,
            ["VoiceName"] = "voice/$Locale$/char/Feina/vo_companio_01",
            },
        [90150701] = {
            ["Content"] = "那是什么？仓鼠小姐饲养的精灵吗？不可思议……它一定可以载着你飞过所有城堡的围墙！",
            ["ContentFR"] = "Qu’est-ce que c’est ? Ton petit esprit, Mlle Hamster ? Incroyable... Il doit pouvoir te porter et t’emporter au-dessus des murailles de tous les châteaux !",
            ["DialogueId"] = 90150701,
            ["GUID"] = "E1AECD62",
            ["SpeakNpcId"] = 81801,
            ["VoiceName"] = "voice/$Locale$/char/Feina/vo_companio_02",
            },
        [90150801] = {
            ["Content"] = "狮子小姐，你想要唤醒沉睡在巨剑中的仙女吗？也许你需要吟诵很多很多咒语，比如——“唤醒圣剑萨麦尔之人啊，必将成为艾利西安之王！”",
            ["ContentFR"] = "Dis, Mlle Lionne, tu veux réveiller la fée qui dort dans cette épée géante ? Alors il te faudra sûrement chanter des tas de sortilèges, comme : « Ô toi qui as éveillé l’épée sacrée Samaël... un jour, tu deviendras le roi d’Élysium ! »",
            ["DialogueId"] = 90150801,
            ["GUID"] = "E1AEDDCA",
            ["SpeakNpcId"] = 81801,
            ["VoiceName"] = "voice/$Locale$/char/Feina/vo_companio_03",
            },
        [90160000] = {
            ["Content"] = "现在这种安心的感觉也不错，甚至让我在过了那么多年后，还能对一个地方产生一丝归属感。",
            ["ContentFR"] = "Cette tranquillité, ça fait drôle... j’aurais jamais cru pouvoir me sentir à ma place, même après tout ce temps.",
            ["DialogueId"] = 90160000,
            ["GUID"] = "E1B4C329",
            ["SpeakNpcId"] = 85102,
            ["VoiceName"] = "voice/$Locale$/char/Aote/vo_idle",
            },
        [90160001] = {
            ["Content"] = "你可来了，我把之前剩的杂活清了一下，钱没赚多少还差点把自己累死，唉，为了这个家我真是付出了太多啊。",
            ["ContentFR"] = "Ah, te voilà enfin. J’ai fini tous les trucs en retard... Pas gagné un rond, et j’ai bien failli y laisser ma peau. Franchement... t’as de la chance que je vous aime bien.",
            ["DialogueId"] = 90160001,
            ["GUID"] = "E1B4C32A",
            ["LookAt"] = {
                [1] = "85102:n(0)",
                [2] = "0:n(85102)",
                },
            ["NextOptions"] = {
                [1] = 901600011,
                [2] = 901600012,
                [3] = 901600013,
                [4] = 901600014,
                [5] = 901600015,
                },
            ["RandomOptionNum"] = 3,
            ["SpeakNpcId"] = 85102,
            ["TalkActionId"] = {
                [1] = "85102:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Aote/vo_welcome",
            ["bForbidSkipOptions"] = true,
            },
        [90160002] = {
            ["Content"] = "聊点别的",
            ["ContentFR"] = "<I>Parlons d’autre chose.</>",
            ["DialogueId"] = 90160002,
            ["GUID"] = "90160002.0",
            ["NextDialogue"] = 90160001,
            },
        [90160003] = {
            ["Content"] = "再见",
            ["ContentFR"] = "<I>À bientôt.</>",
            ["DialogueId"] = 90160003,
            ["GUID"] = "90160003.0",
            },
        [90160101] = {
            ["Content"] = "手册？没有，干这行的可大部分没看书的耐性，但是口诀倒是不少，比如我自创的打人口诀：“两下腰子一下头，皇帝看了说没救”。",
            ["ContentFR"] = "Un guide ? N’y compte pas. Ici, on se fait pas aux bouquins, mais aux bonnes combines. Comme ma devise : « Deux coups dans les côtes, un à la tête, même l’empereur peut pas y faire grand-chose. »",
            ["DialogueId"] = 90160101,
            ["GUID"] = "E1B4D392",
            ["LookAt"] = {
                [1] = "85102:n(0)",
                [2] = "0:n(85102)",
                },
            ["NextDialogue"] = 90160103,
            ["SpeakNpcId"] = 85102,
            ["TalkActionId"] = {
                [1] = "85102:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Aote/vo_topic_01_1",
            },
        [90160103] = {
            ["Content"] = "有意思，再来上几句？",
            ["ContentFR"] = "J’aime bien. T’en as d’autres dans le genre ?",
            ["DialogueId"] = 90160103,
            ["GUID"] = "E1B4D3E6",
            ["NextDialogue"] = 90160104,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "85102:Confident_Start",
                },
            },
        [90160104] = {
            ["Content"] = "别贪多，饭一口一口吃，干这行的，最大的敌人永远是贪婪，有时候来自别人，但更多时候来自自己。",
            ["ContentFR"] = "Ne sois pas trop gourmand. Le plus grand danger dans ce boulot, c’est la cupidité. Parfois elle vient des autres, mais surtout de toi-même.",
            ["DialogueId"] = 90160104,
            ["GUID"] = "E1B4D410",
            ["NextOptions"] = {
                [1] = 90160002,
                [2] = 90160003,
                },
            ["SpeakNpcId"] = 85102,
            ["TalkActionId"] = {
                [1] = "85102:Confident_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Aote/vo_topic_01_2",
            ["bForbidSkipOptions"] = true,
            },
        [90160201] = {
            ["Content"] = "他们是一团未熄灭的野火，稍不留神就会烧成满山烈焰。为你个人考虑，还是少与他们接触为好……",
            ["ContentFR"] = "Ce sont des braises qui refusent de s’éteindre. Suffit d’un souffle pour que tout reprenne feu. Crois-moi, mieux vaut les éviter.",
            ["DialogueId"] = 90160201,
            ["GUID"] = "E1B4E3FA",
            ["LookAt"] = {
                [1] = "85102:n(0)",
                [2] = "0:n(85102)",
                },
            ["NextDialogue"] = 90160203,
            ["SpeakNpcId"] = 85102,
            ["TalkActionId"] = {
                [1] = "85102:Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Aote/vo_topic_02_1",
            },
        [90160203] = {
            ["Content"] = "这么严肃，为什么？",
            ["ContentFR"] = "T’as l’air bien tendu. C’est si grave que ça ?",
            ["DialogueId"] = 90160203,
            ["GUID"] = "E1B4E44E",
            ["NextDialogue"] = 90160204,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "85102:Talk03_End",
                },
            },
        [90160204] = {
            ["Content"] = "那当然是因为……有过一些小过节，要是哪天你和他们打上交道，可千万记得别报我名字。",
            ["ContentFR"] = "Disons... qu’on a eu quelques accrochages. Si jamais tu les croises, surtout, dis pas que tu me connais.",
            ["DialogueId"] = 90160204,
            ["GUID"] = "E1B4E478",
            ["NextOptions"] = {
                [1] = 90160002,
                [2] = 90160003,
                },
            ["SpeakNpcId"] = 85102,
            ["VoiceName"] = "voice/$Locale$/char/Aote/vo_topic_02_2",
            ["bForbidSkipOptions"] = true,
            },
        [90160301] = {
            ["Content"] = "嗯，能帮我拿一下那边的纱布吗？可不能被菲娜发现，不然她又要唠叨了。",
            ["ContentFR"] = "Ouais. Tu peux me passer ce bandage là-bas ? Si Fina le voit, elle va encore faire toute une histoire.",
            ["DialogueId"] = 90160301,
            ["GUID"] = "E1B4F462",
            ["LookAt"] = {
                [1] = "85102:n(0)",
                [2] = "0:n(85102)",
                },
            ["NextDialogue"] = 90160303,
            ["SpeakNpcId"] = 85102,
            ["TalkActionId"] = {
                [1] = "85102:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Aote/vo_topic_03_1",
            },
        [90160303] = {
            ["Content"] = "她那是在关心你。",
            ["ContentFR"] = "Elle s’inquiète pour toi, c’est normal.",
            ["DialogueId"] = 90160303,
            ["GUID"] = "E1B4F4B6",
            ["NextDialogue"] = 90160304,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "85102:Explain02_End",
                },
            },
        [90160304] = {
            ["Content"] = "我知道，但干咱们这一行总免不了受点伤，我也不想让她一直担心嘛。她要是真的问起来，你记得帮我打个圆场啊，回头请你吃饭。",
            ["ContentFR"] = "Je sais, mais les blessures font partie du métier. Je préfère qu’elle ne s’inquiète pas trop. Tu peux me couvrir si elle me pose des questions ? Je te revaudrai ça.",
            ["DialogueId"] = 90160304,
            ["GUID"] = "E1B4F4E0",
            ["NextOptions"] = {
                [1] = 90160002,
                [2] = 90160003,
                },
            ["SpeakNpcId"] = 85102,
            ["TalkActionId"] = {
                [1] = "85102:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Aote/vo_topic_03_2",
            ["bForbidSkipOptions"] = true,
            },
        [90160401] = {
            ["Content"] = "噢，你要不要也试试这些小家伙？别看它们长得丑，去掉头就跟小饼干一样脆脆的，甚至能在嘴巴里留下一丝肉类的回甘……",
            ["ContentFR"] = "Oh, tu veux tester ? Ils sont moches mais une fois la tête enlevée, ça croustille comme un biscuit... avec un petit arrière-goût de viande.",
            ["DialogueId"] = 90160401,
            ["GUID"] = "E1B504CA",
            ["LookAt"] = {
                [1] = "85102:n(0)",
                [2] = "0:n(85102)",
                },
            ["NextDialogue"] = 90160403,
            ["SpeakNpcId"] = 85102,
            ["TalkActionId"] = {
                [1] = "85102:Give",
                },
            ["VoiceName"] = "voice/$Locale$/char/Aote/vo_topic_04_1",
            },
        [90160403] = {
            ["Content"] = "（转身逃跑。）",
            ["ContentFR"] = "(Fait demi-tour et prend la fuite.)",
            ["DialogueId"] = 90160403,
            ["GUID"] = "E1B5051E",
            ["NextDialogue"] = 90160404,
            ["SpeakNpcId"] = 100001,
            },
        [90160404] = {
            ["Content"] = "你别跑啊，这可是很有用的生存智慧……等你迷失在野外，干粮吃完的时候，它们就是最宝贵的能量来源。",
            ["ContentFR"] = "Hé ! Reviens ! C’est des conseils de survie... Si tu te perds dans la nature sans nourriture, ces petites bêtes pourraient te sauver la vie.",
            ["DialogueId"] = 90160404,
            ["GUID"] = "E1B50548",
            ["NextOptions"] = {
                [1] = 90160002,
                [2] = 90160003,
                },
            ["SpeakNpcId"] = 85102,
            ["VoiceName"] = "voice/$Locale$/char/Aote/vo_topic_04_2",
            ["bForbidSkipOptions"] = true,
            },
        }
  end },
  { MinKey = 90160501, MaxKey = 90220301, Loader = function()
      return {
        [90160501] = {
            ["Content"] = "嗯……等等，你手上怎么才这么几个钱，是不是又把你那份报酬随便分给其他人了？",
            ["ContentFR"] = "Attends... Pourquoi t’as presque rien ? Me dis pas que t’as encore filé ta paie aux autres ?",
            ["DialogueId"] = 90160501,
            ["GUID"] = "E1B51532",
            ["LookAt"] = {
                [1] = "85102:n(0)",
                [2] = "0:n(85102)",
                },
            ["NextDialogue"] = 90160503,
            ["SpeakNpcId"] = 85102,
            ["TalkActionId"] = {
                [1] = "85102:Confident_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Aote/vo_topic_05_1",
            },
        [90160503] = {
            ["Content"] = "他们比我更需要那些钱。",
            ["ContentFR"] = "Ils en avaient plus besoin que moi.",
            ["DialogueId"] = 90160503,
            ["GUID"] = "E1B51586",
            ["NextDialogue"] = 90160504,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "85102:Confident_End",
                },
            },
        [90160504] = {
            ["Content"] = "你……哎，算了，这大概就是你的优点吧。手头紧的时候记得跟我说。",
            ["ContentFR"] = "Mais... Peu importe, c’est tout toi, toujours {性别:prêt|prête} à aider les autres. Fais-moi signe si jamais tu as besoin d'argent.",
            ["DialogueId"] = 90160504,
            ["GUID"] = "E1B515B0",
            ["NextDialogue"] = 90160505,
            ["SpeakNpcId"] = 85102,
            ["TalkActionId"] = {
                [1] = "85102:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Aote/vo_topic_05_2",
            },
        [90160505] = {
            ["Content"] = "好，那我现在手头紧了！",
            ["ContentFR"] = "Ah, bah voilà, je suis fauché !",
            ["DialogueId"] = 90160505,
            ["GUID"] = "E1B515DA",
            ["NextDialogue"] = 90160506,
            ["SpeakNpcId"] = 100001,
            },
        [90160506] = {
            ["Content"] = "……我这是身为朋友在关心你，你别得寸进尺耍无赖啊！",
            ["ContentFR"] = "... Je t’aide en tant qu’ami, pas pour que tu m’arnaques !",
            ["DialogueId"] = 90160506,
            ["GUID"] = "E1B51604",
            ["NextOptions"] = {
                [1] = 90160002,
                [2] = 90160003,
                },
            ["SpeakNpcId"] = 85102,
            ["VoiceName"] = "voice/$Locale$/char/Aote/vo_topic_05_3",
            ["bForbidSkipOptions"] = true,
            },
        [90160601] = {
            ["Content"] = "你怎么也在这儿？身体不要紧吗，病没问题吗，饭吃过了吗？哎……有什么想要的给我说就好，没事还是不要瞎跑了。",
            ["DialogueId"] = 90160601,
            ["GUID"] = "E1B5259A",
            ["SpeakNpcId"] = 85102,
            ["VoiceName"] = "voice/$Locale$/char/Aote/vo_companio_01",
            },
        [90160701] = {
            ["Content"] = "你是跟{nickname}关系很好的那个女孩子吧……听说你身体不太好，就坐下好好休息一会儿吧。",
            ["ContentFR"] = "C’est toi, la fille proche de {nickname}, c’est ça ? J’ai entendu que t’étais pas en forme. Tu devrais t’asseoir un moment.",
            ["DialogueId"] = 90160701,
            ["GUID"] = "E1B53602",
            ["NextDialogue"] = 90160702,
            ["SpeakNpcId"] = 85102,
            ["VoiceName"] = "voice/$Locale$/char/Aote/vo_companio_02_1",
            },
        [90160702] = {
            ["Content"] = "不用跟我客气，我家里也有个体弱多病的妹妹，早就习惯照顾人了……要是饿了、渴了，尽管跟我说，{nickname}的朋友就是我的朋友。",
            ["ContentFR"] = "Si t’as faim, soif, ou besoin de quoi que ce soit, dis-le-moi. J’ai l’habitude de veiller sur les autres... Ma petite sœur est malade, alors tu sais, je gère. Et puis, une amie de {nickname}, c’est aussi une amie à moi.",
            ["DialogueId"] = 90160702,
            ["GUID"] = "E1B5362C",
            ["SpeakNpcId"] = 85102,
            ["VoiceName"] = "voice/$Locale$/char/Aote/vo_companio_02_2",
            },
        [90160801] = {
            ["Content"] = "哟，老板娘，你怎么也在这儿……难不成是有什么紧急的委托？{nickname}这段时间已经累坏了，暂时就让我们歇歇吧……",
            ["ContentFR"] = "Eh, Madame Camilla ? Vous ici ? Me dites pas que c’est encore une urgence... {nickname} est déjà sur les rotules. Donnez-nous au moins une pause.",
            ["DialogueId"] = 90160801,
            ["GUID"] = "E1B5466A",
            ["NextDialogue"] = 90160802,
            ["SpeakNpcId"] = 85102,
            ["VoiceName"] = "voice/$Locale$/char/Aote/vo_companio_03_1",
            },
        [90160802] = {
            ["Content"] = "噢，不过，如果报酬够高的话，还是说来听听吧。",
            ["ContentFR"] = "Cela dit... si c’est bien payé, je veux bien écouter.",
            ["DialogueId"] = 90160802,
            ["GUID"] = "E1B54694",
            ["SpeakNpcId"] = 85102,
            ["VoiceName"] = "voice/$Locale$/char/Aote/vo_companio_03_2",
            },
        [90170000] = {
            ["Content"] = "嗯~天气不错，正适合去采一些花，熏得身上香香的！{nickname}，想一起出门逛逛吗？",
            ["ContentFR"] = "Hmm, quel temps magnifique, parfait pour cueillir des fleurs et sentir bon après ! {nickname}, tu veux venir te balader avec moi ?",
            ["DialogueId"] = 90170000,
            ["GUID"] = "E1BB2BC9",
            ["SpeakNpcId"] = 83301,
            ["VoiceName"] = "voice/$Locale$/char/Maer/vo_idle",
            },
        [90170001] = {
            ["Content"] = "我来的时候顺手把你家门口的雪给铲了！是不是特别感动，特别想请我喝一杯热可可呀~",
            ["ContentFR"] = "En arrivant, j’ai dégagé la neige devant ta porte ! Touchée ? Ça mérite bien un chocolat chaud, non ?",
            ["DialogueId"] = 90170001,
            ["GUID"] = "E1BB2BCA",
            ["LookAt"] = {
                [1] = "83301:n(0)",
                [2] = "0:n(83301)",
                },
            ["NextOptions"] = {
                [1] = 901700011,
                [2] = 901700012,
                [3] = 901700013,
                [4] = 901700014,
                [5] = 901700015,
                },
            ["RandomOptionNum"] = 3,
            ["SpeakNpcId"] = 83301,
            ["VoiceName"] = "voice/$Locale$/char/Maer/vo_welcome",
            ["bForbidSkipOptions"] = true,
            },
        [90170002] = {
            ["Content"] = "聊点别的",
            ["ContentFR"] = "<I>Parlons d’autre chose.</>",
            ["DialogueId"] = 90170002,
