            ["NextDialogue"] = 10113118,
            },
        [101131172] = {
            ["Content"] = "没事。我会好起来的……很快就会好起来的。 ",
            ["ContentFR"] = "<I>Ça va. Je m’en remettrai... très vite.</>",
            ["DialogueId"] = 101131172,
            ["GUID"] = "101131172",
