            ["NextDialogue"] = 10113118,
            },
        [101131173] = {
            ["Content"] = "无能的人才会哭泣，我总有一天会让他们付出代价。",
            ["ContentFR"] = "<I>Pleurer, c’est pour les faibles. Un jour, je leur ferai payer.</>",
            ["DialogueId"] = 101131173,
