            ["ImprPlusId"] = 1010,
            ["NextDialogue"] = 10113118,
            },
        [101259011] = {
            ["Content"] = "你在做什么？",
            ["ContentFR"] = "<I>Que faites-vous ici ?</>",
            ["DialogueId"] = 101259011,
            ["GUID"] = "101259011.0",
            ["NextDialogue"] = 10125902,
            },
        [101259012] = {
            ["Content"] = "你是谁？",
            ["ContentFR"] = "<I>Qui êtes-vous ?</>",
            ["DialogueId"] = 101259012,
            ["GUID"] = "101259012.0",
            ["NextDialogue"] = 10125902,
            },
        [101259161] = {
            ["Content"] = "我很想念她。",
            ["ContentFR"] = "<I>Elle me manque tellement...</>",
            ["DialogueId"] = 101259161,
            ["GUID"] = "101259161.0",
            ["NextDialogue"] = 10125917,
            },
        [101259162] = {
            ["Content"] = "我不接受这样的结局。",
            ["ContentFR"] = "<I>Je refuse d’accepter cette fin.</>",
            ["DialogueId"] = 101259162,
            ["GUID"] = "101259162.0",
            ["NextDialogue"] = 10125917,
            },
        [101259211] = {
            ["Content"] = "“雾海”到底是什么地方？",
            ["ContentFR"] = "<I>Qu’est-ce que la \"Mer du Silence\", au juste ?</>",
            ["DialogueId"] = 101259211,
            ["GUID"] = "101259211",
            ["NextDialogue"] = 10125922,
            },
        [101259231] = {
            ["Content"] = "我能去雾海把她带回来吗？",
            ["ContentFR"] = "<I>Puis-je aller là-bas pour la ramener ?</>",
            ["DialogueId"] = 101259231,
            ["GUID"] = "101259231.0",
            ["NextDialogue"] = 10125924,
            },
        [101259232] = {
            ["Content"] = "她还会回到我身边吗？",
            ["ContentFR"] = "<I>Reviendra-t-elle un jour à mes côtés ?</>",
            ["DialogueId"] = 101259232,
            ["GUID"] = "101259232.0",
            ["NextDialogue"] = 10125924,
            },
        [101259271] = {
            ["Content"] = "你的意思是……？！",
            ["ContentFR"] = "<I>Vous voulez dire... ?</>",
            ["DialogueId"] = 101259271,
            ["GUID"] = "101259271",
            ["NextDialogue"] = 10125928,
            },
        [101282021] = {
            ["Content"] = "通行证……有这么重要吗？",
            ["ContentFR"] = "Un permis de circulation… c’est à ce point indispensable ?",
            ["DialogueId"] = 101282021,
            ["GUID"] = "101282021",
            ["NextDialogue"] = 10128204,
            },
        [101282022] = {
            ["Content"] = "他们不会受惩罚吗？",
            ["ContentFR"] = "Et ces soldats, ils ne sont jamais punis ?",
            ["DialogueId"] = 101282022,
            ["GUID"] = "101282022",
            ["NextDialogue"] = 10128212,
            },
        [101282023] = {
            ["Content"] = "再见。",
            ["ContentFR"] = "Au revoir.",
            ["DialogueId"] = 101282023,
            ["GUID"] = "101282023",
            },
        [101282061] = {
            ["Content"] = "就没有对卡戎好一点的士兵吗？",
            ["ContentFR"] = "Il n’y a vraiment aucun soldat un peu plus juste avec les Charons ?",
            ["DialogueId"] = 101282061,
            ["GUID"] = "101282061",
            ["NextDialogue"] = 10128208,
            },
        [101282141] = {
            ["Content"] = "那为什么不去那里呢？",
            ["ContentFR"] = "Alors pourquoi ne pas partir là-bas ?",
            ["DialogueId"] = 101282141,
            ["GUID"] = "101282141",
            ["NextDialogue"] = 10128216,
            },
        [101283021] = {
            ["Content"] = "第三个？",
