            ["GUID"] = "101283022",
            ["NextDialogue"] = 10128312,
            },
        [101283023] = {
            ["Content"] = "再见。",
            ["ContentFR"] = "Au revoir.",
            ["DialogueId"] = 101283023,
            ["GUID"] = "101283023",
            },
        [101283061] = {
