            ["ContentFR"] = "La grande révolte ?",
            ["DialogueId"] = 101283061,
            ["GUID"] = "101283061",
            ["NextDialogue"] = 10128308,
            },
        [101284021] = {
            ["Content"] = "鬼气森森……？",
            ["ContentFR"] = "Lugubre... tu veux dire maudite ?",
            ["DialogueId"] = 101284021,
            ["GUID"] = "101284021",
            ["NextDialogue"] = 10128404,
            },
        [101284022] = {
            ["Content"] = "窥探别人私宅是不好的！",
