            ["DialogueId"] = 120101231,
            ["GUID"] = "120101231.0",
            ["NextDialogue"] = 12010124,
            },
        [120101232] = {
            ["Content"] = "难道……和我想的不一样？",
            ["ContentFR"] = "<I>Serait-ce... différent de ce que je pensais ?</>",
            ["DialogueId"] = 120101232,
            ["GUID"] = "120101232.0",
            ["NextDialogue"] = 12010124,
            },
        [120101281] = {
            ["Content"] = "那怎么好意思……",
            ["ContentFR"] = "<I>Je ne peux pas accepter...</>",
            ["DialogueId"] = 120101281,
            ["GUID"] = "120101281.0",
            ["NextDialogue"] = 12010129,
            },
        [120101282] = {
            ["Content"] = "我就不客气了！",
            ["ContentFR"] = "<I>Merci, j’accepte !</>",
            ["DialogueId"] = 120101282,
            ["GUID"] = "120101282.0",
            ["NextDialogue"] = 12010129,
            },
        [120102101] = {
            ["Content"] = "世界第一的大魔王早上总是赖床？",
            ["ContentFR"] = "<I>Le plus grand Roi Démon du monde... qui fait la grasse matinée jusqu’à quinze heures ?</>",
            ["DialogueId"] = 120102101,
            ["GUID"] = "120102101.0",
            ["NextDialogue"] = 12010211,
            },
        [120102102] = {
            ["Content"] = "世界第一的大魔王打架时总是躲在我身后？",
            ["ContentFR"] = "<I>Le plus grand Roi Démon du monde... qui se cache toujours derrière moi quand ça se bat ?</>",
            ["DialogueId"] = 120102102,
            ["GUID"] = "120102102.0",
            ["NextDialogue"] = 12010211,
            },
        [120102111] = {
            ["Content"] = "我一开始就在了。",
            ["ContentFR"] = "<I>J’étais là depuis le début.</>",
            ["DialogueId"] = 120102111,
            ["GUID"] = "120102111.0",
            ["NextDialogue"] = 12010212,
            },
        [120102112] = {
            ["Content"] = "也就是刚刚到。",
            ["ContentFR"] = "<I>Je viens juste d’arriver.</>",
            ["DialogueId"] = 120102112,
            ["GUID"] = "120102112.0",
            ["NextDialogue"] = 12010212,
            },
        [120103091] = {
            ["Content"] = "还是正事要紧。",
            ["ContentFR"] = "<I>Les affaires passent avant tout.</>",
            ["DialogueId"] = 120103091,
            ["GUID"] = "120103091.0",
            ["NextDialogue"] = 12010310,
            },
        [120103092] = {
            ["Content"] = "真是遗憾，您要走了吗……",
            ["ContentFR"] = "<I>Quel dommage... vous partez déjà ?</>",
            ["DialogueId"] = 120103092,
            ["GUID"] = "120103092.0",
            ["NextDialogue"] = 12010310,
            },
        [120104121] = {
            ["Content"] = "惩罚恶人？狴犴似乎并不是普通猛兽。",
            ["ContentFR"] = "<I>Ils punissent les criminels... Les Bi’an ne sont donc pas de simples bêtes.</>",
            ["DialogueId"] = 120104121,
            ["GUID"] = "120104121.0",
            ["ImprPlusId"] = 1203,
            ["NextDialogue"] = 12010413,
            },
        [120104122] = {
            ["Content"] = "这么厉害，可以抱一只回冰湖城养吗？",
            ["ContentFR"] = "<I>Ils sont si puissants... on peut en ramener un à Givrelac ?</>",
            ["DialogueId"] = 120104122,
            ["GUID"] = "120104122.0",
            ["ImprPlusId"] = 1201,
            ["NextDialogue"] = 12010414,
            },
        [120104291] = {
            ["Content"] = "夫人根基，定文为信。",
            ["ContentFR"] = "<I>« La parole fonde l’homme et établit la confiance. »</>",
            ["DialogueId"] = 120104291,
            ["GUID"] = "120104291.0",
            ["NextDialogue"] = 12010432,
            },
        [120104292] = {
            ["Content"] = "毁约背盟，不可为也。",
            ["ContentFR"] = "<I>« Rompre un serment ou trahir une alliance — cela est proscrit. »</>",
            ["DialogueId"] = 120104292,
            ["GUID"] = "120104292.0",
            ["NextDialogue"] = 12010432,
            },
        [120104401] = {
            ["Content"] = "应该不会吧？",
            ["ContentFR"] = "<I>Ça m’étonnerait quand même...</>",
            ["DialogueId"] = 120104401,
            ["GUID"] = "120104401.0",
            ["ImprPlusId"] = 1202,
            ["NextDialogue"] = 12010441,
            },
        [120104402] = {
            ["Content"] = "瞒了你很久。其实我就是飏，我没死，只是被困在海伯利亚帝国。",
            ["ContentFR"] = "<I>Je t’ai menti tout ce temps. En réalité, je suis Yang. Je ne suis pas morte — j’étais juste coincée dans l’Empire Hyperboréen.</>",
            ["DialogueId"] = 120104402,
            ["GUID"] = "120104402.0",
            ["ImprPlusId"] = 1205,
            ["NextDialogue"] = 12010441,
            },
        [120105101] = {
            ["Content"] = "感谢对方。",
            ["ContentFR"] = "<I>Remercier</>",
            ["DialogueId"] = 120105101,
            ["GUID"] = "120105101.0",
            ["ImprPlusId"] = 1204,
            ["NextDialogue"] = 12010511,
            },
        [120105102] = {
            ["Content"] = "表示自己一个人也能解决。",
            ["ContentFR"] = "<I>Dire que vous auriez pu gérer {性别:seul|seule}</>",
            ["DialogueId"] = 120105102,
            ["GUID"] = "120105102.0",
            ["ImprPlusId"] = 1201,
            ["NextDialogue"] = 12010511,
            },
        [120109041] = {
            ["Content"] = "道上的朋友？",
            ["ContentFR"] = "<I>Des contacts ?</>",
            ["DialogueId"] = 120109041,
            ["GUID"] = "120109031.0",
            ["NextDialogue"] = 12010905,
            },
        [120109042] = {
            ["Content"] = "是“有点危险的朋友”吗？",
            ["ContentFR"] = "<I>Des contacts... un peu dangereux ?</>",
            ["DialogueId"] = 120109042,
            ["GUID"] = "120109032.0",
            ["NextDialogue"] = 12010905,
            },
        [120120031] = {
            ["Content"] = "皎皎之民，白。",
            ["ContentFR"] = "<I>Snow, une Luno.</>",
            ["DialogueId"] = 120120031,
            ["GUID"] = "120120031.0",
            ["ImprPlusId"] = 1202,
            ["NextDialogue"] = 12012005,
            },
        [120120032] = {
            ["Content"] = "纯白的救赎☆光之魔王大人！",
            ["ContentFR"] = "<I>Le Rédempteur Immaculé ☆ Roi Démon de la Lumière.</>",
            ["DialogueId"] = 120120032,
            ["GUID"] = "120120032.0",
            ["ImprPlusId"] = 1205,
            ["NextDialogue"] = 12012007,
            },
        [120126041] = {
            ["Content"] = "我是海伯利亚来的狩月人。",
            ["ContentFR"] = "<I>Je suis {性别:un Chasseur|une Chasseuse} de Phoxène d’Hyperborea.</>",
            ["DialogueId"] = 120126041,
            ["GUID"] = "120126041.0",
            ["ImprPlusId"] = 1202,
            ["NextDialogue"] = 12012607,
            },
        [120126042] = {
            ["Content"] = "我是你{性别：爷爷|奶奶}！",
            ["ContentFR"] = "<I>C’est moi qui décide ici, pigé ?!</>",
            ["DialogueId"] = 120126042,
            ["GUID"] = "120126042.0",
            ["ImprPlusId"] = 1205,
            ["NextDialogue"] = 12012607,
            },
        [120127101] = {
            ["Content"] = "猛虎。",
            ["ContentFR"] = "<I>Le tigre.</>",
            ["DialogueId"] = 120127101,
            ["GUID"] = "120127101.0",
            ["NextDialogue"] = 12012711,
            },
        [120127102] = {
            ["Content"] = "羊群。",
            ["ContentFR"] = "<I>Le troupeau.</>",
            ["DialogueId"] = 120127102,
            ["GUID"] = "120127102.0",
            ["NextDialogue"] = 12012712,
            },
        [120127103] = {
            ["Content"] = "侠义之士。",
            ["ContentFR"] = "<I>Le héros.</>",
            ["DialogueId"] = 120127103,
            ["GUID"] = "120127103.0",
            ["NextDialogue"] = 12012713,
            },
        [120127104] = {
            ["Content"] = "够了，我不想和你玩智力游戏。",
            ["ContentFR"] = "<I>Assez. Je ne suis pas ici pour jouer à vos jeux d’esprit.</>",
            ["DialogueId"] = 120127104,
            ["GUID"] = "120127104.0",
            ["NextDialogue"] = 12012714,
            },
        [120131061] = {
            ["Content"] = "她是我的朋友。",
            ["ContentFR"] = "<I>Elle est mon amie.</>",
            ["DialogueId"] = 120131061,
            ["GUID"] = "120131061.0",
            ["NextDialogue"] = 12013107,
            },
        [120131062] = {
            ["Content"] = "她是路见不平救下来的人。",
            ["ContentFR"] = "<I>Nous l’avons secourue en chemin.</>",
            ["DialogueId"] = 120131062,
            ["GUID"] = "120131062.0",
            ["NextDialogue"] = 12013107,
            },
        [120131141] = {
            ["Content"] = "你调理了我的身体，送给你是应当的。",
            ["ContentFR"] = "<I>Tu as remis mon corps d’aplomb. Te l’offrir est la moindre des choses.</>",
            ["DialogueId"] = 120131141,
            ["GUID"] = "120131141.0",
            ["ImprPlusId"] = 1202,
            ["NextDialogue"] = 12013115,
            },
        [120131142] = {
            ["Content"] = "如果是对你来说很重要的人。",
            ["ContentFR"] = "<I>Si cette flûte appartenait à quelqu’un qui comptait pour toi... alors prends-la.</>",
            ["DialogueId"] = 120131142,
            ["GUID"] = "120131142.0",
            ["ImprPlusId"] = 1204,
            ["NextDialogue"] = 12013116,
            },
        [120131143] = {
            ["Content"] = "世上没有免费的午餐！",
            ["ContentFR"] = "<I>Rien n’est gratuit en ce monde.</>",
            ["DialogueId"] = 120131143,
            ["GUID"] = "120131143.0",
            ["ImprPlusId"] = 1201,
            ["NextDialogue"] = 12013117,
            },
        [120131211] = {
            ["Content"] = "我是{nickname}，这位皎皎叫做白。",
            ["ContentFR"] = "<I>Je suis {nickname}. Et voici Snow.</>",
            ["DialogueId"] = 120131211,
            ["GUID"] = "120131211.0",
            ["NextDialogue"] = 12013125,
            },
        [120131212] = {
            ["Content"] = "我是骁勇的独目勇者，冷酷的冰湖之主，第一代下水道公爵。",
            ["ContentFR"] = "<I>Je suis {性别:le Vaillant Guerrier Cyclope, Seigneur de Givrelac, et tout premier Duc des Égouts|la Vaillante Guerrière Cyclope, Souveraine de Givrelac, et toute première Duchesse des Égouts !} !</>",
            ["DialogueId"] = 120131212,
            ["GUID"] = "120131212.0",
            ["NextDialogue"] = 12013122,
            },
        [120134311] = {
            ["Content"] = "呜呼哀哉……",
            ["ContentFR"] = "Hélas... quelle lamentation...",
            ["DialogueId"] = 120134311,
            ["GUID"] = "1E130CF8",
            ["NextDialogue"] = 12013432,
            ["SnapShot"] = "ECHO",
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["VoiceName"] = "voice/$Locale$/story/1201/120134/1E130CF8",
            },
        [120134351] = {
            ["Content"] = "（声音好像是从那个方向传来的……）",
            ["ContentFR"] = "<I>Cette voix... elle semble venir de par là...</>",
            ["DialogueId"] = 120134351,
            ["GUID"] = "1E130A2F",
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120134/1E130A2F",
            },
        [120134391] = {
            ["Content"] = "告诉白刚刚听到的声音。",
            ["ContentFR"] = "<I>Dire à Snow les voix que tu as entendues</>",
            ["DialogueId"] = 120134391,
            ["GUID"] = "120134391.0",
            ["NextDialogue"] = 12013440,
            },
        [120135011] = {
            ["Content"] = "（听听他准备说什么）",
            ["ContentFR"] = "<I>Écouter ce qu’il a à dire</>",
            ["DialogueId"] = 120135011,
            ["GUID"] = "120135011.0",
            ["NextDialogue"] = 12013505,
            },
        [120135012] = {
            ["Content"] = "（装作没看到，直接走开）",
            ["ContentFR"] = "<I>Faire semblant de ne pas l’avoir vu et continuer son chemin</>",
            ["DialogueId"] = 120135012,
            ["GUID"] = "120135012.0",
            ["NextDialogue"] = 12013504,
            },
        [120135070] = {
            ["Camera"] = "-70.775307,-50.397655,304.739258,0.000104,-11.399626,52.60202,35.0,383.266479,false,DoNotOverride,2.8",
            ["DialogueId"] = 120135070,
