            },
        [120135071] = {
            ["Content"] = "我为什么要帮你们？",
            ["ContentFR"] = "<I>Pourquoi devrais-je vous aider ?</>",
            ["DialogueId"] = 120135071,
            ["GUID"] = "120135071.0",
            ["NextDialogue"] = 12013509,
            },
        [120135072] = {
            ["Content"] = "围猎行动？听起来不像什么好事。",
            ["ContentFR"] = "<I>Une battue ? Ça ne ressemble pas vraiment à une œuvre de charité.</>",
            ["DialogueId"] = 120135072,
            ["GUID"] = "120135072.0",
            ["NextDialogue"] = 12013526,
            },
        [120136021] = {
            ["Content"] = "还是先拜访扶疏吧。",
            ["ContentFR"] = "<I>Allons d’abord voir Fushu.</>",
            ["DialogueId"] = 120136021,
            ["GUID"] = "120136021.0",
