        [120155051] = {
            ["Content"] = "不知道你在说什么……",
            ["ContentFR"] = "<I>Je ne vois pas de quoi tu parles...</>",
            ["DialogueId"] = 120155051,
            ["GUID"] = "120155051.0",
            ["NextDialogue"] = 12015507,
            },
        [120155052] = {
            ["Content"] = "扶疏也是百年之前的人？！",
            ["ContentFR"] = "<I>Fushu... tu as plus de cent ans ?!</>",
            ["DialogueId"] = 120155052,
            ["GUID"] = "120155052.0",
            ["NextDialogue"] = 12015509,
            },
        [120186141] = {
            ["Content"] = "他们也不是故意的。",
            ["ContentFR"] = "<I>Ils n’avaient pas de mauvaises intentions.</>",
            ["DialogueId"] = 120186141,
            ["GUID"] = "120186141.0",
            ["ImprPlusId"] = 1202,
            ["NextDialogue"] = 12018616,
            },
        [120186142] = {
            ["Content"] = "罚他们三天工资！",
            ["ContentFR"] = "<I>Retirez-leur trois jours de salaire.</>",
            ["DialogueId"] = 120186142,
            ["GUID"] = "120186142.0",
            ["ImprPlusId"] = 1205,
            ["NextDialogue"] = 12018619,
            },
        [120193051] = {
            ["Content"] = "幸会幸会……原来华胥之外的地方，还有如此拉风的职业！相逢即是有缘，何不结伴一程？",
            ["ContentFR"] = "Enchanté, enchanté... Dire qu’en dehors de Huaxu, on peut exercer des métiers aussi flamboyants ! Puisque le destin nous a réunis, pourquoi ne pas faire un bout de chemin ensemble ?",
            ["DialogueId"] = 120193051,
            ["GUID"] = "120193050",
            ["NextDialogue"] = 12019307,
            ["SpeakNpcId"] = 210021,
            ["VoiceName"] = "voice/$Locale$/story/1201/120193/120193050",
            },
        [120193141] = {
            ["Content"] = "哦哦……！原来如此！难怪我以随身的枪戟剑林将此地翻来覆去轰了几遍，都没能撼动分毫……竟是要敲击这里。话说回来，这机枢派的造物可真结实。",
            ["ContentFR"] = "<I>Bonjour.</>",
            ["DialogueId"] = 120193141,
            ["GUID"] = "1E16CD3A",
            ["NextDialogue"] = 12019316,
            ["VoiceName"] = "voice/$Locale$/story/1201/120193/1E16CD3A",
            },
        [120223281] = {
            ["Content"] = "我不想看着华胥陷入祸乱，我想看看有什么我能做的。",
            ["ContentFR"] = "<I>Je ne veux pas regarder Huaxu sombrer dans le chaos. Je vais voir ce que je peux faire.</>",
            ["DialogueId"] = 120223281,
            ["GUID"] = "120223281.0",
            ["ImprPlusId"] = 1204,
            ["NextDialogue"] = 12022329,
            },
        [120223282] = {
            ["Content"] = "今天实在是发生了太多事情，我只想回冰湖城……",
            ["ContentFR"] = "<I>Il s’est passé trop de choses... Je veux juste rentrer à Givrelac.</>",
            ["DialogueId"] = 120223282,
            ["GUID"] = "120223282.0",
            ["ImprPlusId"] = 1201,
            ["NextDialogue"] = 12022329,
            },
        [120230021] = {
            ["Content"] = "感觉那个人有点可怜……",
            ["ContentFR"] = "<I>Il faisait un peu peine à voir...</>",
            ["DialogueId"] = 120230021,
            ["GUID"] = "120230021.0",
            ["ImprPlusId"] = 1204,
            ["NextDialogue"] = 12023003,
            },
        [120230022] = {
            ["Content"] = "虽然他的想法可能有错，但也不应该这样对待他。",
            ["ContentFR"] = "<I>Même s’il avait tort, ce n’était peut-être pas juste de le chasser ainsi.</>",
            ["DialogueId"] = 120230022,
            ["GUID"] = "120230022.0",
            ["ImprPlusId"] = 1202,
            ["NextDialogue"] = 12023003,
            },
        [120230023] = {
            ["Content"] = "为了防止人心动摇，适当的手段也是应该的。",
            ["ContentFR"] = "<I>Pour éviter que les esprits vacillent, certaines mesures sont nécessaires.</>",
            ["DialogueId"] = 120230023,
            ["GUID"] = "120230023.0",
            ["ImprPlusId"] = 1201,
            ["NextDialogue"] = 12023003,
            },
        [120230024] = {
            ["Content"] = "做得好，就该这样！",
            ["ContentFR"] = "<I>Bien fait. Il l’avait mérité.</>",
            ["DialogueId"] = 120230024,
            ["GUID"] = "120230024.0",
            ["ImprPlusId"] = 1205,
            ["NextDialogue"] = 12023003,
            },
        [120233101] = {
            ["Content"] = "讲述经过",
            ["ContentFR"] = "<I>Raconter ce qui s’est passé</>",
            ["DialogueId"] = 120233101,
            ["GUID"] = "120233101.0",
            ["NextDialogue"] = 12023311,
            },
        [120233131] = {
            ["Content"] = "试图辩解",
            ["ContentFR"] = "<I>Insister</>",
            ["DialogueId"] = 120233131,
            ["GUID"] = "120233131.0",
            ["NextDialogue"] = 12023314,
            },
