            },
        [510003021] = {
            ["Content"] = "（留意到她的衣服布料颇为华贵。）",
            ["ContentFR"] = "<I>Tu remarques que ses vêtements, bien que usés, sont de facture luxueuse.</>",
            ["DialogueId"] = 510003021,
            ["GUID"] = "510003021.0",
            ["ImprPlusId"] = 1001,
            ["NextDialogue"] = 51000303,
            },
        [510003022] = {
            ["Content"] = "（留意到她似乎在找什么人。）",
            ["ContentFR"] = "<I>Elle semble chercher quelqu’un.</>",
            ["DialogueId"] = 510003022,
            ["GUID"] = "510003022.0",
            ["ImprPlusId"] = 1003,
            ["NextDialogue"] = 51000304,
            },
        [510003023] = {
            ["Content"] = "（留意到她很悲伤。）",
            ["ContentFR"] = "<I>Elle est noyée dans le chagrin.</>",
            ["DialogueId"] = 510003023,
            ["GUID"] = "510003023.0",
            ["ImprPlusId"] = 1004,
            ["NextDialogue"] = 51000305,
            },
        [510003051] = {
            ["Content"] = "（也许可以帮上什么忙。）",
            ["ContentFR"] = "<I>Peut-être pourrais-je lui venir en aide...</>",
            ["DialogueId"] = 510003051,
            ["GUID"] = "510003051.0",
            ["NextDialogue"] = 510003052,
            },
        [510003052] = {
            ["Content"] = "（也许可以帮上什么忙。）",
            ["ContentFR"] = "<I>Peut-être pourrais-je lui venir en aide...</>",
            ["DialogueId"] = 510003052,
            ["GUID"] = "510003052.0",
            ["NextOptions"] = {
                [1] = 510003054,
                [2] = 510003055,
                [3] = 510003056,
                },
            ["SpeakNpcId"] = 100001,
            ["bForbidSkipOptions"] = true,
            },
        [510003053] = {
            ["Content"] = "（离开。）",
            ["ContentFR"] = "<I>Partir</>",
            ["DialogueId"] = 510003053,
            ["GUID"] = "510003053.0",
            ["Scripts"] = "SetOutport{FinishType{\"Fail\"}}",
            },
        [510003054] = {
            ["Content"] = "（询问她是不是遇到了什么烦心事。付一些报酬的话，可以考虑帮忙解决。）",
            ["ContentFR"] = "<I>Demander si quelque chose la tourmente, en échange d’une rétribution, tu pourrais t’en charger</>",
            ["DialogueId"] = 510003054,
            ["FailDialogue"] = 51000306,
            ["GUID"] = "510003054.0",
            ["ImprCheckId"] = 1001,
            ["NextDialogue"] = 51000307,
            },
        [510003055] = {
            ["Content"] = "（询问她是否在找什么人，也许日后出城的时候可以帮她留意一下。）",
            ["ContentFR"] = "<I>Proposer de garder l’œil ouvert si elle recherche quelqu’un</>",
            ["DialogueId"] = 510003055,
            ["FailDialogue"] = 51000306,
            ["GUID"] = "510003055.0",
            ["ImprCheckId"] = 1002,
            ["NextDialogue"] = 51000307,
            },
        [510003056] = {
            ["Content"] = "（询问她是不是有什么困难，或许能提供一些帮助。）",
            ["ContentFR"] = "<I>Offrir ton aide</>",
            ["DialogueId"] = 510003056,
            ["FailDialogue"] = 51000306,
            ["GUID"] = "510003056.0",
            ["ImprCheckId"] = 1003,
            ["NextDialogue"] = 51000307,
            },
        [510003111] = {
            ["Content"] = "对此没有印象。",
            ["ContentFR"] = "<I>Non, cela ne me dit rien...</>",
            ["DialogueId"] = 510003111,
            ["GUID"] = "510003111.0",
            ["NextDialogue"] = 51000312,
            },
        [510004031] = {
            ["Content"] = "那个……{性别：我是男的。|我不是你的女儿。}",
            ["ContentFR"] = "<I>Euh... {性别:Je suis un homme|Je ne suis pas votre fille}.</>",
            ["DialogueId"] = 510004031,
            ["GUID"] = "510004031.0",
            ["ImprPlusId"] = 1001,
            ["NextDialogue"] = 51000490,
            },
        [510004032] = {
            ["Content"] = "冷静一下。你在找人？我会帮你留意。",
            ["ContentFR"] = "<I>Calmez-vous. Vous cherchez quelqu’un ? Je peux vous aider à la trouver.</>",
            ["DialogueId"] = 510004032,
            ["GUID"] = "510004032.0",
            ["ImprPlusId"] = 1004,
            ["NextDialogue"] = 51000490,
            },
        [510004033] = {
            ["Content"] = "妈！！！",
            ["ContentFR"] = "<I>Maman !</>",
            ["DialogueId"] = 510004033,
            ["GUID"] = "510004033.0",
            ["ImprPlusId"] = 1005,
            ["NextDialogue"] = 51000404,
            },
        [510004071] = {
            ["Content"] = "（接受）",
            ["ContentFR"] = "<I>Accepter</>",
            ["DialogueId"] = 510004071,
            ["GUID"] = "510004071.0",
            ["NextDialogue"] = 51000408,
            },
        [510004921] = {
            ["Content"] = "请好好回想一下你女儿的特征与失踪的经过，这样我才能确定能否帮到你。",
            ["ContentFR"] = "<I>Rappelez-vous bien des caractéristiques de votre fille et des circonstances de sa disparition, afin que je puisse voir comment vous aider.</>",
            ["DialogueId"] = 510004921,
            ["FailDialogue"] = 51000405,
            ["GUID"] = "510004921.0",
            ["ImprCheckId"] = 1007,
            ["NextDialogue"] = 51000406,
            },
        [510005011] = {
            ["Content"] = "爱尔莎，我有了安妮的消息……",
            ["ContentFR"] = "<I>Elsa, j’ai des nouvelles d’Annie...</>",
            ["DialogueId"] = 510005011,
            ["GUID"] = "510005011.0",
            ["NextDialogue"] = 51000502,
            },
        [510005021] = {
            ["Content"] = "请您节哀，安妮已经去世了……在她生命的最后，她帮助另一个女孩活了下来，她的善良值得被铭记。",
            ["ContentFR"] = "Je suis {性别:navré|navrée}... Annie n’est plus de ce monde. Dans ses derniers instants, elle a sauvé une autre jeune fille. Sa bonté mérite d’être honorée et jamais oubliée.",
            ["DialogueId"] = 510005021,
            ["GUID"] = "510005021.0",
            ["NextDialogue"] = 51000503,
            },
        [510006011] = {
            ["Content"] = "爱尔莎，我有了安妮的消息……",
            ["ContentFR"] = "<I>Elsa, j’ai retrouvé votre fille.</>",
            ["DialogueId"] = 510006011,
            ["GUID"] = "510006011.0",
            ["NextDialogue"] = 51000602,
            },
        [510007011] = {
            ["Content"] = "你一直在这里徘徊，有什么能帮你的吗？",
            ["ContentFR"] = "<I>Tu traînes ici depuis longtemps ? Je peux t’aider en quoi que ce soit ?</>",
            ["DialogueId"] = 510007011,
            ["GUID"] = "510007011.0",
            ["NextDialogue"] = 51000702,
            },
        [510007031] = {
            ["Content"] = "我理解你的迷茫，失去归属感的确很糟。",
            ["ContentFR"] = "<I>Je comprends ta confusion, perdre son identité est terrible.</>",
            ["DialogueId"] = 510007031,
            ["GUID"] = "510007031.0",
            ["ImprPlusId"] = 1004,
            ["NextDialogue"] = 51000705,
            },
        [510007032] = {
            ["Content"] = "滞留在外并不安全，还是尽早弄清你的真实身份为妙。",
            ["ContentFR"] = "<I>Rester dehors n’est pas sûr. Il vaut mieux découvrir ta véritable identité rapidement.</>",
            ["DialogueId"] = 510007032,
            ["GUID"] = "510007032.0",
            ["ImprPlusId"] = 1002,
            ["NextDialogue"] = 51000705,
            },
        [510007033] = {
            ["Content"] = "眼见不一定为实。一切都需要调查后才能得出结论。",
            ["ContentFR"] = "<I>Ce que l’on voit n’est pas toujours la vérité. Il faut enquêter avant de tirer des conclusions.</>",
            ["DialogueId"] = 510007033,
            ["GUID"] = "510007033.0",
            ["ImprPlusId"] = 1003,
            ["NextDialogue"] = 51000705,
            },
        [510007051] = {
            ["Content"] = "（接受）",
            ["ContentFR"] = "<I>Accepter</>",
            ["DialogueId"] = 510007051,
            ["GUID"] = "510007051.0",
            ["NextDialogue"] = 51000706,
            },
        [510008121] = {
            ["Content"] = "（不展示爱丽丝的日记）",
            ["ContentFR"] = "<I>Ne pas montrer le journal</>",
            ["DialogueId"] = 510008121,
            ["GUID"] = "510008121.0",
            ["NextDialogue"] = 51000813,
            ["Scripts"] = "SetOutport{FinishType{2},OptionIdx{2}}",
            },
        [510008141] = {
            ["Content"] = "正是你母亲托我来寻找你，我会带你去见她。",
            ["ContentFR"] = "<I>C’est elle qui m’a demandé de te chercher. Je vais te conduire à elle.</>",
            ["DialogueId"] = 510008141,
            ["GUID"] = "510008141.0",
            ["NextDialogue"] = 51000814,
            },
        [510008921] = {
            ["Content"] = "（展示爱丽丝的日记）",
            ["ContentFR"] = "<I>Montrer le journal d’Alice</>",
            ["DialogueId"] = 510008921,
            ["GUID"] = "510008921.0",
            ["NextDialogue"] = 51000803,
            ["Scripts"] = "SetOutport{FinishType{2},OptionIdx{1}}",
            },
        [510009031] = {
            ["Content"] = "我只看到了一些破烂，据我估价，他们不会比几块石头更有价值。",
            ["ContentFR"] = "<I>Je ne vois ici que des vieilleries. À vue de nez, ça ne vaut pas plus que quelques cailloux.</>",
            ["DialogueId"] = 510009031,
            ["GUID"] = "510009031.0",
            ["ImprPlusId"] = 1001,
            ["NextDialogue"] = 51000904,
            },
        [510009032] = {
            ["Content"] = "不问自取的行为还是少做为妙。",
            ["ContentFR"] = "<I>Piller sans demander n’est pas exactement une vertu.</>",
            ["DialogueId"] = 510009032,
            ["GUID"] = "510009032.0",
            ["ImprPlusId"] = 1002,
            ["NextDialogue"] = 51000905,
            },
        [510009033] = {
            ["Content"] = "从哪儿摸的！带我一个！",
            ["ContentFR"] = "<I>Tu as trouvé ça où ? Emmène-moi avec toi !</>",
            ["DialogueId"] = 510009033,
            ["GUID"] = "510009033.0",
            ["ImprPlusId"] = 1005,
            ["NextDialogue"] = 51000906,
            },
        [510009071] = {
            ["Content"] = "很可惜，这里没有我需要的商品。",
            ["ContentFR"] = "<I>Dommage... rien de ce dont j’ai besoin.</>",
            ["DialogueId"] = 510009071,
            ["GUID"] = "510009071.0",
            ["NextDialogue"] = 51000907,
            },
        [510009072] = {
            ["Content"] = "（他仔仔细细地打量着你，露出了一个深思的表情）",
            ["ContentFR"] = "Martin te dévisage longuement, l’air songeur.",
            ["DialogueId"] = 510009072,
            ["GUID"] = "510009072.0",
            ["ImprCheckId"] = 1004,
            ["NextDialogue"] = 51000909,
            },
        [510009101] = {
            ["Content"] = "我听说有人可以提供一部分价格低廉的燃料与布匹，这让不少穷人能安然渡过隆冬。",
            ["ContentFR"] = "<I>On dit que quelqu’un fournit du combustible et du tissu bon marché. Grâce à ça, beaucoup de pauvres survivent à l’hiver.</>",
            ["DialogueId"] = 510009101,
            ["GUID"] = "510009101.0",
            ["ImprPlusId"] = 1002,
            },
        [510009102] = {
            ["Content"] = "你售卖情报，但你看起来不像个私家侦探，难道你有特别的情报来源？",
            ["ContentFR"] = "<I>Tu vends des informations. Pourtant, tu n’as pas l’air d’un détective... Quelle est donc ta source ?</>",
            ["DialogueId"] = 510009102,
            ["GUID"] = "510009102.0",
            ["ImprPlusId"] = 1003,
            },
        [510009103] = {
            ["Content"] = "我已经听你说过三遍马丁了，你到底谁啊？",
            ["ContentFR"] = "<I>Voilà trois fois que tu répètes « Martin ». Mais qui es-tu, au juste ?</>",
            ["DialogueId"] = 510009103,
            ["GUID"] = "510009103.0",
            ["ImprPlusId"] = 1005,
            },
        [510009121] = {
            ["Content"] = "真有那么神奇吗？",
            ["ContentFR"] = "<I>C’est vraiment aussi incroyable que ça ?</>",
            ["DialogueId"] = 510009121,
            ["GUID"] = "510009121",
            },
        [510009161] = {
            ["Content"] = "（接受）",
            ["ContentFR"] = "<I>Accepter</>",
            ["DialogueId"] = 510009161,
            ["GUID"] = "510009161.0",
            },
        [510010071] = {
            ["Content"] = "你丢了一样东西。这件东西证明了你不过也是个和他一样的窝棚板富豪。",
            ["ContentFR"] = "<I>Tu as perdu quelque chose. Cet objet prouve que tu n’es qu’une riche des taudis, comme lui.</>",
            ["DialogueId"] = 510010071,
            ["GUID"] = "510010071.0",
            ["ImprCheckId"] = 1005,
            ["NextDialogue"] = 51001008,
            },
        [510010072] = {
            ["Content"] = "你丢了一样东西。通常来说，过期车票应该销毁以防模仿造假，而私藏显然是个违规行为。",
            ["ContentFR"] = "<I>Tu as perdu quelque chose. Normalement, les billets périmés doivent être détruits pour éviter les contrefaçons, et les garder est clairement interdit.</>",
            ["DialogueId"] = 510010072,
            ["GUID"] = "510010072.0",
            ["ImprCheckId"] = 1006,
            ["NextDialogue"] = 51001008,
            },
        [510010101] = {
            ["Content"] = "传说星星有实现愿望的能力，你用车票叠了上百颗星星，又想实现什么样的愿望呢？",
            ["ContentFR"] = "<I>On raconte que les étoiles peuvent réaliser les vœux. Tu as plié des centaines d’étoiles avec ces billets... quel vœu voulais-tu exaucer ?</>",
            ["DialogueId"] = 510010101,
            ["GUID"] = "510010101.0",
            },
        [510010181] = {
            ["Content"] = "我理解你的不甘与悲痛，人生总有不如意的时候，但现在无法跨越的天堑也许终有一天会成为坦途。",
            ["ContentFR"] = "<I>Je comprends ton amertume et ta peine. La vie réserve des déceptions, mais ce qui semble infranchissable aujourd’hui pourrait devenir un chemin plus tard.</>",
            ["DialogueId"] = 510010181,
            ["GUID"] = "510010181.0",
            ["ImprPlusId"] = 1004,
            ["NextDialogue"] = 51001019,
            },
        [510010182] = {
            ["Content"] = "不论如何，刚才的先生都不应该被你这么羞辱，恕我难以苟同你把怒火发泄到别人身上的行为。",
            ["ContentFR"] = "<I>De toute façon, le monsieur tout à l’heure n’aurait pas dû subir ton humiliation. Je ne peux approuver que tu décharges ta colère sur quelqu’un d’autre.</>",
            ["DialogueId"] = 510010182,
            ["GUID"] = "510010182.0",
            ["ImprPlusId"] = 1002,
            ["NextDialogue"] = 51001020,
            },
        [510010183] = {
            ["Content"] = "不管你怎么想，要是不想摊上事，你就该把这东西收回去，妥善保存也罢，销毁也好，那是你的问题。",
            ["ContentFR"] = "<I>Peu importe ce que tu penses, si tu ne veux pas de problèmes, récupère cet objet et garde-le correctement, ou détruis-le. C’est ton affaire.</>",
            ["DialogueId"] = 510010183,
            ["GUID"] = "510010183.0",
            ["ImprPlusId"] = 1001,
            ["NextDialogue"] = 51001021,
            },
        [510010184] = {
            ["Content"] = "你干嘛不扒在车顶坐个来回过过瘾？",
            ["ContentFR"] = "<I>Pourquoi ne pas t’asseoir sur le toit du train pour un petit tour, histoire de te défouler ?</>",
            ["DialogueId"] = 510010184,
            ["GUID"] = "510010184.0",
            ["ImprPlusId"] = 1005,
            ["NextDialogue"] = 51001022,
            },
        [510012011] = {
            ["Content"] = "那些鸟都是你养的吗？",
            ["ContentFR"] = "<I>Ces oiseaux-là, ce sont les tiens ?</>",
            ["DialogueId"] = 510012011,
            ["GUID"] = "510012011.0",
            ["ImprPlusId"] = 1003,
            ["NextDialogue"] = 51001202,
            },
        [510012012] = {
            ["Content"] = "那些鸟飞得太高了，不然今天还能加顿餐。",
            ["ContentFR"] = "<I>Dommage qu’ils volent si haut... Sinon, on aurait pu s’en faire un festin.</>",
            ["DialogueId"] = 510012012,
            ["GUID"] = "510012012.0",
            ["ImprPlusId"] = 1005,
            ["NextDialogue"] = 51001203,
            },
        [510012041] = {
            ["Content"] = "（回忆你从书本上看到的金翎鸟的知识——它们的习性，以及为什么它们可以成为探测工具。）",
            ["ContentFR"] = "<I>Se rappeler avoir lu à propos des oiseaux à plumes d’or — leur comportement, et pourquoi ils sont utilisés comme outils de détection.</>",
            ["DialogueId"] = 510012041,
            ["GUID"] = "510012041.0",
            ["ImprPlusId"] = 1003,
            ["NextDialogue"] = 51001205,
            },
        [510012042] = {
            ["Content"] = "（附和面前这位矿工，批判人们对传统的遗弃。）",
            ["ContentFR"] = "<I>Approuver et déplorer comme lui que l’on ait tourné le dos aux traditions.</>",
            ["DialogueId"] = 510012042,
            ["GUID"] = "510012042.0",
            ["ImprPlusId"] = 1004,
            ["NextDialogue"] = 51001206,
            },
        [510012043] = {
            ["Content"] = "（向面前这位矿工赞扬技术发展能让人类社会更高效地运转。）",
            ["ContentFR"] = "<I>Saluer les progrès technologiques qui ont permis à la société de gagner en efficacité.</>",
            ["DialogueId"] = 510012043,
            ["GUID"] = "510012043.0",
            ["ImprPlusId"] = 1001,
            ["NextDialogue"] = 51001207,
            },
        [510013011] = {
            ["Content"] = "你不能这样侮辱一位受尊敬的女士。",
            ["ContentFR"] = "<I>Tu peux pas insulter une dame respectée comme ça.</>",
            ["DialogueId"] = 510013011,
            ["GUID"] = "510013011.0",
            ["ImprPlusId"] = 1002,
            ["NextDialogue"] = 51001302,
            },
        [510013012] = {
            ["Content"] = "（上去就是一拳）",
            ["ContentFR"] = "<I>Donner un coup de poing</>",
            ["DialogueId"] = 510013012,
            ["GUID"] = "510013012.0",
            ["ImprPlusId"] = 1005,
            ["NextDialogue"] = 51001303,
            },
        [510013013] = {
            ["Content"] = "给她点面子就敢蹬鼻子上脸，还说什么看不上老子的酒，老子早晚让她吃不了兜着走！",
            ["ContentFR"] = "Tu lui fais un compliment et elle te marche dessus. Elle ose dire que ma gnôle ne vaut rien ?! Je finirai par lui faire ravaler ses paroles, tôt ou tard !",
            ["DialogueId"] = 510013013,
            ["GUID"] = "510013013",
            ["NextOptions"] = {
                [1] = 510013011,
                [2] = 510013012,
                },
            ["SpeakNpcId"] = 700014,
            ["bForbidSkipOptions"] = true,
            },
        [510013041] = {
            ["Content"] = "不，卡米拉是一位值得信赖的朋友，她帮过我忙。",
            ["ContentFR"] = "<I>Je préfère considérer Camilla comme une alliée forte et fiable. Elle nous a aidés à de nombreuses reprises. Pas seulement nous, d’ailleurs : au moins la moitié de Givrelac lui doit quelque chose.</>",
            ["DialogueId"] = 510013041,
            ["FailDialogue"] = 51001305,
            ["GUID"] = "510013041.0",
            ["ImprCheckId"] = 1008,
            ["NextDialogue"] = 51001306,
            },
        [510013042] = {
            ["Content"] = "你不用多费唇舌，卡米拉为人怎么样，我相信自己的判断。",
            ["ContentFR"] = "<I>Ce n’est pas une raison pour déblatérer ici. Je crois en l’intégrité de Camilla, et ce n’est pas avec tes accusations ridicules que tu la saliras.</>",
            ["DialogueId"] = 510013042,
            ["FailDialogue"] = 51001305,
            ["GUID"] = "510013042.0",
            ["ImprCheckId"] = 1009,
            ["NextDialogue"] = 51001306,
            },
        [510013043] = {
            ["Content"] = "所以你是向卡米拉推销酒水不成，着急了。",
            ["ContentFR"] = "<I>J’ai vu de mes yeux le discernement de Camilla : qu’il s’agisse des gens ou des boissons, rien ne lui échappe. Celui qui ne reconnaît rien, ici, c’est toi.</>",
            ["DialogueId"] = 510013043,
            ["FailDialogue"] = 51001305,
            ["GUID"] = "510013043.0",
            ["ImprCheckId"] = 1010,
            ["NextDialogue"] = 51001306,
            },
        [510013061] = {
            ["Content"] = "嗯，咳，听口音你不是本地人吧。我猜，自从来到冰湖城，你就没去水仙平原之外的地方喝过吧？",
            ["ContentFR"] = "<I>Hum... kof...</> J’entends à ton accent que tu n’es pas du coin. Laisse-moi deviner, depuis que tu es arrivé à Givrelac, tu n’as jamais mis les pieds ailleurs qu’au bar de Camilla ?",
            ["DialogueId"] = 510013061,
            ["GUID"] = "510013061.0",
            ["SpeakNpcId"] = 700014,
            },
        [510013062] = {
            ["Content"] = "那又如何？",
            ["ContentFR"] = "<I>Et alors ?</>",
            ["DialogueId"] = 510013062,
            ["GUID"] = "510013062",
            },
        [510013091] = {
            ["Content"] = "好吧，来一桶。",
            ["ContentFR"] = "<I>D’accord, je prends une pinte.</>",
            ["DialogueId"] = 510013091,
            ["GUID"] = "510013091.0",
            ["NextDialogue"] = 51001310,
            },
        [510013092] = {
            ["Content"] = "便宜没好货。",
            ["ContentFR"] = "<I>On en a pour son argent.</>",
            ["DialogueId"] = 510013092,
            ["GUID"] = "510013092.0",
            ["NextDialogue"] = 51001313,
            },
        [510013231] = {
            ["Content"] = "抢生意也就算了，万一假酒把人喝出毛病怎么办？",
            ["ContentFR"] = "<I>La concurrence, passe encore. Mais si ton faux alcool rend les gens malades ?</>",
            ["DialogueId"] = 510013231,
            ["GUID"] = "510013231.0",
            ["ImprPlusId"] = 1002,
            ["NextDialogue"] = 51001324,
            },
        [510013232] = {
            ["Content"] = "就是！还怕她一张嘴！兄弟你喝一桶看看实力！",
            ["ContentFR"] = "<I>Ouais ! Faut pas avoir peur d’elle. Mon pote, bois un tonneau et montre-nous !</>",
            ["DialogueId"] = 510013232,
            ["GUID"] = "510013232.0",
            ["ImprPlusId"] = 1005,
            ["NextDialogue"] = 51001326,
            },
        [510013281] = {
            ["Content"] = "假货害人啊……",
            ["ContentFR"] = "<I>Sa camelote fait vraiment des ravages...</>",
            ["DialogueId"] = 510013281,
            ["GUID"] = "510013281.0",
            ["NextDialogue"] = 51001329,
            },
        [510014021] = {
            ["Content"] = "孩子本就是天生通透的诗人。",
            ["ContentFR"] = "<I>Les enfants sont des poètes nés, capables de voir l’essence même de la vie.</>",
            ["DialogueId"] = 510014021,
            ["GUID"] = "510014021.0",
            ["ImprPlusId"] = 1004,
            ["NextDialogue"] = 51001403,
            },
        [510014022] = {
            ["Content"] = "你看起来非常为他们自豪。",
            ["ContentFR"] = "<I>Vous semblez très fière d’eux.</>",
            ["DialogueId"] = 510014022,
            ["GUID"] = "510014022.0",
            ["ImprPlusId"] = 1003,
            ["NextDialogue"] = 51001403,
            },
        [510014023] = {
            ["Content"] = "可恶，原来我输在了起跑线上。",
            ["ContentFR"] = "<I>Eh bien, on dirait que j’étais déjà à la traîne dès la ligne de départ.</>",
            ["DialogueId"] = 510014023,
            ["GUID"] = "510014023.0",
            ["ImprPlusId"] = 1005,
            ["NextDialogue"] = 51001403,
            },
        [510014061] = {
            ["Content"] = "才不是呢，你教会了孩子可贵的纯真与浪漫。",
            ["ContentFR"] = "<I>Pas du tout. Vous leur enseignez la plus grande des choses : la pureté et le rêve.</>",
            ["DialogueId"] = 510014061,
            ["FailDialogue"] = 51001407,
            ["GUID"] = "510014061.0",
            ["ImprCheckId"] = 1011,
            ["NextDialogue"] = 51001409,
            },
        [510014901] = {
            ["Content"] = "你看起来在和孩子们的相处中收获了很多。",
            ["ContentFR"] = "<I>On dirait que ces enfants vous ont beaucoup appris, vous aussi.</>",
            ["DialogueId"] = 510014901,
            ["GUID"] = "510014901.0",
            ["ImprPlusId"] = 1003,
            ["NextDialogue"] = 51001412,
            },
        [510014902] = {
            ["Content"] = "为这些孩子们做出牺牲，真的是值得的吗？",
            ["ContentFR"] = "<I>Faire autant de sacrifices pour eux... en valait-il vraiment la peine ?</>",
            ["DialogueId"] = 510014902,
            ["GUID"] = "510014902.0",
            ["ImprPlusId"] = 1001,
            ["NextDialogue"] = 51001412,
            },
        [510015021] = {
            ["Content"] = "用清洁剂泡一泡再擦？",
            ["ContentFR"] = "<I>Faire tremper dans un peu de détergent, puis frotter ?</>",
            ["DialogueId"] = 510015021,
            ["GUID"] = "510015021.0",
            ["ImprPlusId"] = 1003,
            ["NextDialogue"] = 51001503,
            },
        [510015022] = {
            ["Content"] = "你付钱给我，我给你擦。",
            ["ContentFR"] = "<I>Tu me payes, et je le fais pour toi.</>",
            ["DialogueId"] = 510015022,
            ["GUID"] = "510015022.0",
            ["ImprPlusId"] = 1001,
            ["NextDialogue"] = 51001503,
            },
        [510015023] = {
            ["Content"] = "挨打挨骂是好事，有助于锻炼精神。",
            ["ContentFR"] = "<I>Se faire frapper forge le caractère, non ?</>",
            ["DialogueId"] = 510015023,
            ["GUID"] = "510015023.0",
            ["ImprPlusId"] = 1005,
            ["NextDialogue"] = 51001503,
            },
        [510015071] = {
            ["Content"] = "你不觉得说这种话太冷漠了吗？",
            ["ContentFR"] = "<I>Tu ne trouves pas ça un peu froid, comme propos ?</>",
            ["DialogueId"] = 510015071,
            ["GUID"] = "510015071.0",
            ["ImprCheckId"] = 1012,
            ["NextDialogue"] = 51001509,
            },
        [510016021] = {
            ["Content"] = "（此人脾气有点暴躁，摸一摸他的恶魔角安抚下吧。）",
            ["ContentFR"] = "<I>– Il a l’air colérique... Peut-être que lui toucher les cornes le calmerait.</>",
            ["DialogueId"] = 510016021,
            ["GUID"] = "510016021.0",
            ["ImprPlusId"] = 1005,
            ["NextDialogue"] = 51001603,
            },
        [510016022] = {
            ["Content"] = "卡戎和索拉是平等的。你不该心存偏见。",
            ["ContentFR"] = "<I>Charons et Solariens sont égaux. Tu ne devrais pas avoir de préjugés.</>",
            ["DialogueId"] = 510016022,
            ["GUID"] = "510016022.0",
            ["ImprPlusId"] = 1002,
            ["NextDialogue"] = 51001605,
            },
        [510016023] = {
            ["Content"] = "可是你也是个卡戎啊……？",
            ["ContentFR"] = "<I>Mais... tu es un Charon, toi aussi... non ?</>",
            ["DialogueId"] = 510016023,
            ["GUID"] = "510016023.0",
            ["ImprPlusId"] = 1003,
            ["NextDialogue"] = 51001607,
            },
        [510016121] = {
            ["Content"] = "我可以看看您的“桂冠卡戎”奖章吗？",
            ["ContentFR"] = "<I>Puis-je admirer votre médaille de Charon Couronné ?</>",
            ["DialogueId"] = 510016121,
            ["FailDialogue"] = 51001690,
            ["GUID"] = "510016121.0",
            ["ImprCheckId"] = 1013,
            ["NextDialogue"] = 51001613,
            },
        [510017031] = {
            ["Content"] = "（真诚建议他注意个人卫生问题）",
            ["ContentFR"] = "<I>Conseiller sincèrement de faire plus attention à son hygiène</>",
            ["DialogueId"] = 510017031,
            ["GUID"] = "510017031.0",
            ["ImprPlusId"] = 1003,
            ["NextDialogue"] = 51001704,
            },
        [510017032] = {
            ["Content"] = "（为自己刚才失礼的动作道歉）",
            ["ContentFR"] = "<I>Présenter ses excuses pour la réaction déplacée</>",
            ["DialogueId"] = 510017032,
            ["GUID"] = "510017032.0",
            ["ImprPlusId"] = 1004,
            ["NextDialogue"] = 51001704,
            },
        [510017033] = {
            ["Content"] = "（指责他的味道过于腥臭有恶劣影响）",
            ["ContentFR"] = "<I>Reprocher de sentir si mauvais que ça en devient insupportable</>",
            ["DialogueId"] = 510017033,
            ["GUID"] = "510017033.0",
            ["ImprPlusId"] = 1002,
            ["NextDialogue"] = 51001704,
            },
        [510017081] = {
            ["Content"] = "一个本该救死扶伤的人不应该来修理下水道。",
            ["ContentFR"] = "<I>Un homme qui sauve des vies ne devrait pas se retrouver à réparer des canalisations.</>",
            ["DialogueId"] = 510017081,
            ["FailDialogue"] = 51001709,
            ["GUID"] = "510017081.0",
            ["ImprCheckId"] = 1014,
            ["NextDialogue"] = 51001711,
            },
        [510017161] = {
            ["Content"] = "如果再给你的人生重来一次的机会，你还会救他吗？",
            ["ContentFR"] = "<I>Si tu pouvais revivre ta vie, referais-tu le même choix ?</>",
            ["DialogueId"] = 510017161,
            ["GUID"] = "510017161.0",
            ["NextDialogue"] = 51001717,
            },
        [510018011] = {
            ["Content"] = "（接受）",
            ["ContentFR"] = "<I>Accepter</>",
            ["DialogueId"] = 510018011,
            ["GUID"] = "510018011.0",
            ["NextDialogue"] = 51001802,
            },
        [510018012] = {
            ["Content"] = "（拒绝）",
            ["ContentFR"] = "<I>Refuser</>",
            ["DialogueId"] = 510018012,
            ["GUID"] = "510018012.0",
            ["Scripts"] = "SetOutport{FinishType{\"Fail\"}}",
            },
        [510019231] = {
            ["Content"] = "这裂纹的形状……原来如此，它替威尔斯先生挡下了胸口的致命伤啊。",
            ["ContentFR"] = "<I>La forme de ces fissures... je comprends. Elle vous a protégé d’un coup fatal.</>",
            ["DialogueId"] = 510019231,
            ["GUID"] = "510019231.0",
            ["ImprPlusId"] = 1003,
            ["NextDialogue"] = 51001924,
            },
        [510019232] = {
            ["Content"] = "……威尔斯先生就算过得再怎么惨，也不该去偷别人的怀表吧。",
            ["ContentFR"] = "... Monsieur Wells, peu importe les épreuves, vous ne devriez pas voler la montre de quelqu’un d’autre.",
            ["DialogueId"] = 510019232,
            ["GUID"] = "510019232.0",
            ["ImprPlusId"] = 1005,
            ["NextDialogue"] = 51001924,
            },
        [510019911] = {
            ["Content"] = "威尔斯先生没你说的不堪，别太过分了。",
            ["ContentFR"] = "<I>Wells n’est pas aussi mauvais que vous le dites. Vous allez trop loin.</>",
            ["DialogueId"] = 510019911,
            ["FailDialogue"] = 51001916,
            ["GUID"] = "510019911.0",
            ["ImprCheckId"] = 1015,
            ["NextDialogue"] = 51001918,
            },
        [510019912] = {
            ["Content"] = "桂冠卡戎对我们没有任何吸引力，别拿你浅薄的认知定义所有人。",
            ["ContentFR"] = "<I>Nous n’avons aucun intérêt à devenir des Charons Couronnés. Ne jugez pas tout le monde selon vos idées superficielles.</>",
            ["DialogueId"] = 510019912,
            ["FailDialogue"] = 51001916,
            ["GUID"] = "510019912.0",
            ["ImprCheckId"] = 1016,
            ["NextDialogue"] = 51001918,
            },
        [510019913] = {
            ["Content"] = "嘴巴放干净点。不然今天像狗一样被打一顿的，就是另一个“威尔斯先生”了。",
            ["ContentFR"] = "<I>Surveille ton langage. Sinon, un autre \"Monsieur Wells\" risque de prendre une sacrée raclée aujourd’hui.</>",
            ["DialogueId"] = 510019913,
            ["FailDialogue"] = 51001916,
            ["GUID"] = "510019913.0",
            ["ImprCheckId"] = 1017,
            ["NextDialogue"] = 51001918,
            },
        [510020031] = {
            ["Content"] = "为什么你不自己去寻宝呢？",
            ["ContentFR"] = "<I>Pourquoi vous n’allez pas chercher ce trésor vous-même ?</>",
            ["DialogueId"] = 510020031,
            ["GUID"] = "510020031.0",
            ["ImprPlusId"] = 1003,
            ["NextDialogue"] = 51002004,
            },
        [510020032] = {
            ["Content"] = "稍微介绍一下这个宝藏？",
            ["ContentFR"] = "<I>Parlez-moi un peu de ce trésor.</>",
            ["DialogueId"] = 510020032,
            ["GUID"] = "510020032.0",
            ["ImprPlusId"] = 1001,
            ["NextDialogue"] = 51002006,
            },
        [510020033] = {
            ["Content"] = "你是不是在骗人啊……",
            ["ContentFR"] = "<I>Vous ne seriez pas en train de me rouler ?</>",
            ["DialogueId"] = 510020033,
            ["GUID"] = "510020033.0",
            ["ImprPlusId"] = 1002,
            ["NextDialogue"] = 51002008,
            },
        [510020131] = {
            ["Content"] = "我总觉得你说的这个南方海岛很耳熟。",
            ["ContentFR"] = "<I>J’ai comme l’impression d’avoir déjà entendu parler de cette île au sud...</>",
            ["DialogueId"] = 510020131,
            ["FailDialogue"] = 51002014,
            ["GUID"] = "510020131.0",
            ["ImprCheckId"] = 1018,
            ["NextDialogue"] = 51002016,
            },
        [510023011] = {
            ["Content"] = "哈默尔·狄金森……我好像看到过这个名字……",
            ["ContentFR"] = "<I>Hamel Dickinson... ce nom me dit quelque chose...</>",
            ["DialogueId"] = 510023011,
            ["GUID"] = "510023011.0",
            ["NextDialogue"] = 51002302,
            },
        [510023041] = {
            ["Content"] = "（交出在矿坑中得到的日记）",
            ["ContentFR"] = "<I>Remettre le journal trouvé dans la mine</>",
            ["DialogueId"] = 510023041,
            ["GUID"] = "510023041.0",
            ["ImprPlusId"] = 1002,
            ["NextDialogue"] = 51002305,
            ["Scripts"] = "SetOutport{FinishType{2},OptionIdx{1}}",
            },
        [510023042] = {
            ["Content"] = "（隐瞒在矿坑中得到的日记）",
            ["ContentFR"] = "<I>Dissimuler le journal trouvé dans la mine</>",
            ["DialogueId"] = 510023042,
            ["GUID"] = "510023042.0",
            ["ImprPlusId"] = 1016,
            ["NextDialogue"] = 51002312,
            ["Scripts"] = "SetOutport{FinishType{2},OptionIdx{2}}",
            },
        [510024031] = {
            ["Content"] = "可以告诉我哈默尔的事情吗？",
            ["ContentFR"] = "<I>Pouvez-vous me raconter ce qui s’est passé avec Hamel Dickinson ?</>",
            ["DialogueId"] = 510024031,
            ["GUID"] = "510024031.0",
            ["NextDialogue"] = 51002432,
            },
        [510024141] = {
            ["Content"] = "但是哈默尔爽约了？",
            ["ContentFR"] = "<I>Mais... il n’est jamais venu ?</>",
            ["DialogueId"] = 510024141,
            ["GUID"] = "510024141.0",
            ["NextDialogue"] = 51002415,
            },
        [510025021] = {
            ["Content"] = "我虽然不买，但分我一半报酬的话，可以帮你找找买家。",
            ["ContentFR"] = "<I>Je n’achète pas, mais si on partage la récompense à parts égales, je peux t’aider à trouver un acheteur.</>",
            ["DialogueId"] = 510025021,
            ["GUID"] = "510025021.0",
            ["ImprPlusId"] = 1001,
            ["NextDialogue"] = 51002505,
            },
        [510025022] = {
            ["Content"] = "你需要什么帮助吗？",
            ["ContentFR"] = "<I>Tu as besoin d’aide ?</>",
            ["DialogueId"] = 510025022,
            ["GUID"] = "510025022.0",
            ["ImprPlusId"] = 1004,
            ["NextDialogue"] = 51002505,
            },
        [510025023] = {
            ["Content"] = "帝国肯定不会允许你干这种事，不想惹麻烦的话就快走吧。",
            ["ContentFR"] = "<I>L’Empire ne tolère pas ce genre de trafic. Si tu veux éviter les ennuis, pars vite.</>",
            ["DialogueId"] = 510025023,
            ["GUID"] = "510025023.0",
            ["ImprPlusId"] = 1002,
            ["NextDialogue"] = 51002503,
            },
        [510025024] = {
            ["Content"] = "咳！军团的士兵委托我盘查你，赶紧把通行证拿出来！",
            ["ContentFR"] = "<I>Hum ! La Légion m’a chargé de contrôler les gens comme toi. Montre-moi ton permis de circulation, tout de suite !</>",
            ["DialogueId"] = 510025024,
            ["GUID"] = "510025024.0",
            ["ImprPlusId"] = 1005,
            ["NextDialogue"] = 51002504,
            },
        [510026031] = {
            ["Content"] = "凯文，冰湖城有人在违规售卖月石。",
            ["ContentFR"] = "<I>Kevin, dans les taudis de Givrelac, quelqu’un vend illégalement du Phoxène.</>",
            ["DialogueId"] = 510026031,
            ["FailDialogue"] = 51002604,
            ["GUID"] = "510026031.0",
            ["ImprCheckId"] = 1026,
            ["NextDialogue"] = 51002605,
            },
        [510029041] = {
            ["Content"] = "按时报到。",
            ["ContentFR"] = "<I>Comme convenu, me revoilà.</>",
            ["DialogueId"] = 510029041,
            ["GUID"] = "510029041.0",
            ["NextDialogue"] = 51002905,
            },
        [510029081] = {
            ["Content"] = "他是谁？",
            ["ContentFR"] = "<I>Qui est-ce ?</>",
            ["DialogueId"] = 510029081,
            ["GUID"] = "510029081.0",
            ["NextDialogue"] = 51002909,
            },
        [510029101] = {
            ["Content"] = "省略巴克先生层层叠叠的修辞手法，再将关键词重新组合，或许能听懂他在说些什么。",
            ["ContentFR"] = "<I>En simplifiant son discours et en isolant les mots-clés, on comprendra peut-être ce qu’il essaie de dire.</>",
            ["DialogueId"] = 510029101,
            ["FailDialogue"] = 51002911,
            ["GUID"] = "510029101.0",
            ["ImprCheckId"] = 1019,
            ["NextDialogue"] = 51002912,
            },
        [510030031] = {
            ["Content"] = "巴克先生总是熬夜创作。",
            ["ContentFR"] = "<I>Monsieur Buck passe ses nuits à écrire.</>",
            ["DialogueId"] = 510030031,
            ["GUID"] = "510030031.0",
            ["ImprPlusId"] = 1004,
            ["NextDialogue"] = 51003004,
            },
        [510030032] = {
            ["Content"] = "嗐，夜猫子罢了。",
            ["ContentFR"] = "<I>Eh bien, encore un noctambule.</>",
            ["DialogueId"] = 510030032,
            ["GUID"] = "510030032.0",
            ["ImprPlusId"] = 1005,
            ["NextDialogue"] = 51003004,
            },
        [510030051] = {
            ["Content"] = "巴克先生的工作不太顺利。",
            ["ContentFR"] = "<I>Le travail de Monsieur Buck ne progresse pas vraiment.</>",
            ["DialogueId"] = 510030051,
            ["GUID"] = "510030051.0",
            ["ImprPlusId"] = 1004,
            ["NextDialogue"] = 51003006,
            },
        [510030052] = {
            ["Content"] = "哦~把自己写睡着了，说不定他更适合去写睡前故事。",
            ["ContentFR"] = "<I>Oh... il s’est endormi sur ses écrits. Peut-être devrait-il se reconvertir dans les histoires pour s’endormir.</>",
            ["DialogueId"] = 510030052,
            ["GUID"] = "510030052.0",
            ["ImprPlusId"] = 1005,
            ["NextDialogue"] = 51003006,
            },
        [510030071] = {
            ["Content"] = "巴克先生在睡着的时候注意到了一些反常的动静。",
            ["ContentFR"] = "<I>Monsieur Buck a remarqué des choses étranges pendant son sommeil.</>",
            ["DialogueId"] = 510030071,
            ["GUID"] = "510030071.0",
            ["ImprPlusId"] = 1004,
            ["NextDialogue"] = 51003008,
            },
        [510030072] = {
            ["Content"] = "不排除睡傻了的可能性，也不排除有人跟他过不去的可能性。",
            ["ContentFR"] = "<I>Peut-être que tout cela n’est que le fruit de ses rêves... mais on ne peut pas écarter l’hypothèse qu’on lui en veuille.</>",
            ["DialogueId"] = 510030072,
            ["GUID"] = "510030072.0",
            ["ImprPlusId"] = 1005,
            ["NextDialogue"] = 51003008,
            },
        [510030091] = {
            ["Content"] = "巴克先生没有财物上的损失。",
            ["ContentFR"] = "<I>Monsieur Buck n’a subi aucune perte matérielle.</>",
            ["DialogueId"] = 510030091,
            ["GUID"] = "510030091.0",
            ["ImprPlusId"] = 1004,
            ["NextDialogue"] = 51003010,
            },
        [510030092] = {
            ["Content"] = "什么都没偷？这贼难道有偷窥别人睡觉的嗜好？",
            ["ContentFR"] = "<I>Rien n’a été volé ? Le voleur aime juste regarder les gens dormir ? Quelle horreur...</>",
            ["DialogueId"] = 510030092,
            ["GUID"] = "510030092.0",
            ["ImprPlusId"] = 1005,
            ["NextDialogue"] = 51003010,
            },
        [510030111] = {
            ["Content"] = "如果有人帮他找出真相，巴克先生会把他当做下部戏剧的主角。",
            ["ContentFR"] = "<I>Si quelqu’un l’aide à résoudre ce mystère, Monsieur Buck en fera le protagoniste de sa prochaine œuvre.</>",
            ["DialogueId"] = 510030111,
            ["GUID"] = "510030111.0",
            ["ImprPlusId"] = 1004,
            ["NextDialogue"] = 51003012,
            },
        [510030112] = {
            ["Content"] = "穷光蛋啊！",
            ["ContentFR"] = "<I>Ce type est fauché...</>",
            ["DialogueId"] = 510030112,
            ["GUID"] = "510030112.0",
            ["ImprPlusId"] = 1005,
            ["NextDialogue"] = 51003012,
            },
        [510030121] = {
            ["Content"] = "让我来为你解决问题吧，巴克先生。",
            ["ContentFR"] = "<I>Je vais m’en occuper, Monsieur Buck.</>",
            ["DialogueId"] = 510030121,
            ["GUID"] = "510030121.0",
            ["NextDialogue"] = 51003013,
            },
        [510030122] = {
            ["Content"] = "算了吧。",
            ["ContentFR"] = "<I>Non, merci.</>",
            ["DialogueId"] = 510030122,
            ["GUID"] = "510030122.0",
            ["Scripts"] = "SetOutport{FinishType{\"Fail\"}}",
            },
        [510033051] = {
            ["Content"] = "今天生意怎么样，足够购买过夜的燃料吗？",
            ["ContentFR"] = "<I>Et ton commerce suffit-il à couvrir ton chauffage ?</>",
            ["DialogueId"] = 510033051,
            ["GUID"] = "510033051.0",
            ["ImprPlusId"] = 1002,
            ["NextDialogue"] = 510033053,
            },
        [510033052] = {
            ["Content"] = "你这点哪够我吃的。",
            ["ContentFR"] = "<I>Ce n’est pas assez pour moi. Je mange beaucoup.</>",
            ["DialogueId"] = 510033052,
            ["GUID"] = "510033052.0",
            ["ImprPlusId"] = 1005,
            ["NextDialogue"] = 510033054,
            },
        [510033053] = {
            ["Content"] = "托您的福，食物和燃料，我总能得到其中一个，人生就是一场取舍。",
            ["ContentFR"] = "Votre préoccupation est appréciée. J’arrive à peine à choisir, soit manger, soit me chauffer. Jamais les deux.",
            ["DialogueId"] = 510033053,
            ["GUID"] = "510033053.0",
            ["NextDialogue"] = 51003306,
            ["SpeakNpcId"] = 700080,
            },
        [510033054] = {
            ["Content"] = "给您塞塞牙缝！虽然数量不足 ，但口味可以保证！",
            ["ContentFR"] = "Alors, considérez-les comme des amuse-gueules ! Il n’y en a pas beaucoup, mais je garantis le goût !",
            ["DialogueId"] = 510033054,
            ["GUID"] = "510033054.0",
            ["NextDialogue"] = 51003306,
            ["SpeakNpcId"] = 700080,
            },
        [510033141] = {
            ["Content"] = "你并不怨恨他，也没有偷窃他家的财物，让我来猜猜看你为什么要半夜闯空门吧。",
            ["ContentFR"] = "<I>Tu n’as rien volé, tu ne le détestes pas... Alors, pourquoi entrer chez lui la nuit ? Laisse moi deviner.</>",
            ["DialogueId"] = 510033141,
            ["FailDialogue"] = 51003315,
            ["GUID"] = "510033141.0",
            ["ImprCheckId"] = 1022,
            ["NextDialogue"] = 51003316,
            },
        [510034141] = {
            ["Content"] = "有什么将要发生了！我们站在冻结的湖面，能看到的只是冷漠，深邃，凝结。",
            ["ContentFR"] = "Quelque chose se prépare ! Nous marchons sur le lac gelé, sous nos pas, tout n’est que froideur, profondeur et rigidité.",
            ["DialogueId"] = 510034141,
            ["GUID"] = "510034141.0",
            ["NextDialogue"] = 510034142,
            ["SpeakNpcId"] = 700015,
            ["TalkActionId"] = {
                [1] = "700093:Talk01_Start",
                },
            },
        [510034142] = {
            ["Content"] = "但我们谁都知道暗流正在酝酿，正在壮大，终有一天，它会吞噬我们现有的一切。在这之前，我会乘上火车前往预兆的源头。",
            ["ContentFR"] = "Mais nous savons aussi qu’un courant sombre est en train de croître, de prendre de la force, un jour viendra où il engloutira tout ce que nous tenons. Avant ce jour, je prendrai le train pour aller voir d’où vient ce présage.",
            ["DialogueId"] = 510034142,
            ["GUID"] = "510034142.0",
            ["SpeakNpcId"] = 700015,
            ["TalkActionId"] = {
                [1] = "700093:Talk01_End",
                },
            },
        [510034143] = {
            ["Content"] = "冬天的寒冷已经不再困扰我了，谢谢你，狩月人。",
            ["ContentFR"] = "L’hiver ne m’effraie plus désormais, merci à vous, {性别:Chasseur de Phoxène|Chasseuse de Phoxène}.",
            ["DialogueId"] = 510034143,
            ["GUID"] = "510034143.0",
            ["SpeakNpcId"] = 700080,
            ["TalkActionId"] = {
                [1] = "700094:Explain02_Start",
                },
            },
        [510035031] = {
            ["Content"] = "艾玛匆忙将花放在指定地点，并按流程献上了感谢致辞，但她的走神还是引起了老师的嘀咕。",
            ["ContentFR"] = "Emma dépose en hâte le bouquet au pied de la stèle et récite le discours prévu, mais son moment d’absence ne passe pas inaperçu.",
            ["DialogueId"] = 510035031,
            ["Duration"] = 3,
            ["GUID"] = "510035031.0",
            },
        [510035041] = {
            ["Camera"] = "-336.324951,48.679199,108.230957,0.0,0.0,-9.40437,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "好了，下面就是自由活动时间，半个小时后还在雕像下集合，千万别走太远了。",
            ["ContentFR"] = "Bien, c’est l’heure d’une courte pause. On se retrouve dans une demi-heure sous la statue. Ne vous éloignez pas trop.",
            ["DialogueId"] = 510035041,
            ["GUID"] = "510035041.0",
            ["NextDialogue"] = 510035042,
            ["SpeakNpcId"] = 700086,
            ["TalkActionId"] = {
                [1] = "700086:Sigh_End",
                [2] = "700086:Explain01_Start",
                },
            },
        [510035042] = {
            ["Camera"] = "-344.113281,-49.567139,176.708252,0.000003,-0.399996,158.596222,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "（纪念活动结束后，艾玛还是一个人发呆，时不时喃喃自语着什么。）",
            ["ContentFR"] = "La cérémonie achevée, Emma reste en retrait. Elle marmonne dans le vide, le regard perdu.",
            ["DialogueId"] = 510035042,
            ["GUID"] = "510035042.0",
            ["TalkActionId"] = {
                [1] = "700016:Confident_Start",
                },
            },
        [510035051] = {
            ["Content"] = "这么敷衍老师可不行，当心被她记小本本哦。",
            ["ContentFR"] = "Rêvasser comme ça, c’est prendre le risque qu’elle te note dans son carnet.",
            ["DialogueId"] = 510035051,
            ["GUID"] = "510035051.0",
            ["ImprPlusId"] = 1001,
            ["NextDialogue"] = 510035054,
            },
        [510035052] = {
            ["Content"] = "你是不是有比参加纪念仪式更想去做的事呀？",
            ["ContentFR"] = "<I>Y a-t-il quelque chose que tu préférerais faire plutôt que de participer à cette cérémonie ?</>",
            ["DialogueId"] = 510035052,
            ["GUID"] = "510035052.0",
            ["ImprPlusId"] = 1004,
            ["NextDialogue"] = 510035055,
            },
        [510035053] = {
            ["Content"] = "在这种正式场合走神是对被纪念者的不敬。",
            ["ContentFR"] = "<I>S’absenter dans un moment comme celui-ci, c’est manquer de respect aux disparus.</>",
            ["DialogueId"] = 510035053,
            ["GUID"] = "510035053.0",
            ["ImprPlusId"] = 1002,
            ["NextDialogue"] = 510035056,
            },
        [510035054] = {
            ["Content"] = "老师才不会呢！虽然啰嗦，但对我们她可有耐心了！",
            ["ContentFR"] = "Mais non ! Elle est râleuse, d’accord, mais elle a beaucoup de patience avec nous !",
            ["DialogueId"] = 510035054,
            ["GUID"] = "510035054",
            ["LookAt"] = {
                [1] = "700016:n(0)",
                },
            ["NextDialogue"] = 51003506,
            ["SpeakNpcId"] = 700016,
            },
        [510035055] = {
