            ["ContentFR"] = "Hein ? Oh, ça se voit tant que ça ?",
            ["DialogueId"] = 510035055,
            ["GUID"] = "510035055",
            ["NextDialogue"] = 51003506,
            ["SpeakNpcId"] = 700016,
            },
        [510035056] = {
