            ["ContentFR"] = "Oui, servez-vous. Quelle surprise ! J’étais persuadé que seuls les riches de la cité intérieure se donnaient la peine d’acheter à manger pour leurs animaux.",
            ["DialogueId"] = 710002101,
            ["GUID"] = "710002101.0",
            ["SpeakNpcId"] = 700106,
            },
        [710002201] = {
            ["Content"] = "（野猫围着你的食物转了两圈后才放下戒备，吃了起来。看着它满足的表情，你的内心也得到了极大的治愈。）",
            ["ContentFR"] = "Le chat tourne deux fois autour de la ration, hésitant, puis baisse sa garde et commence à manger. En voyant son air comblé, une douce chaleur apaise votre cœur.",
            ["DialogueId"] = 710002201,
            ["GUID"] = "710002201.0",
            ["SpeakNpcId"] = 800006,
            },
        [710007210] = {
            ["Content"] = "好吧。",
            ["ContentFR"] = "<I>D’accord, je m’en charge.</>",
            ["DialogueId"] = 710007210,
            ["GUID"] = "710007210.0",
            ["NextDialogue"] = 71000741,
            ["Scripts"] = "SetOutport{FinishType{2},OptionIdx{1}}",
            },
        [710007211] = {
            ["Content"] = "抱歉，我还有其他事。",
            ["ContentFR"] = "<I>{性别:Désolé|Désolée}, j’ai d’autres obligations.</>",
            ["DialogueId"] = 710007211,
            ["GUID"] = "710007211.0",
            ["Scripts"] = "SetOutport{FinishType{2},OptionIdx{2}}",
            },
        [710008021] = {
            ["Content"] = "（接受。）",
            ["ContentFR"] = "<I>Accepter</>",
            ["DialogueId"] = 710008021,
            ["GUID"] = "710008021.0",
            ["Scripts"] = "SetOutport{FinishType{2},OptionIdx{1}}",
            },
        [710008022] = {
            ["Content"] = "（拒绝。）",
            ["ContentFR"] = "<I>Refuser</>",
            ["DialogueId"] = 710008022,
            ["GUID"] = "710008022.0",
            ["NextDialogue"] = 71000805,
            ["Scripts"] = "SetOutport{FinishType{2},OptionIdx{2}}",
            },
        [710009060] = {
            ["Content"] = "唉，就陪你们玩一小会儿。",
            ["ContentFR"] = "<I>Bon... d’accord, je joue un peu avec vous.</>",
            ["DialogueId"] = 710009060,
            ["Duration"] = 3,
            ["GUID"] = "710009060.0",
            },
        [710009061] = {
            ["Content"] = "（假装看不见，快步走开。）",
            ["ContentFR"] = "<I>Faire semblant de ne pas les voir et partir rapidement</>",
            ["DialogueId"] = 710009061,
            ["GUID"] = "710009061.0",
            },
        [710010020] = {
            ["Content"] = "（尝试拿走月髓能源装置。）",
            ["ContentFR"] = "<I>Tenter de s’emparer du réservoir de Phoxichor</>",
            ["DialogueId"] = 710010020,
            ["GUID"] = "710010020.0",
            },
        [710010021] = {
            ["Content"] = "（抵抗诱惑。）",
            ["ContentFR"] = "<I>Résister à la tentation</>",
            ["DialogueId"] = 710010021,
            ["GUID"] = "710010021.0",
            },
        [710014041] = {
            ["Content"] = "（卖给本地商人。）",
            ["ContentFR"] = "<I>Vendre au marchand local</>",
            ["DialogueId"] = 710014041,
            ["GUID"] = "710014041.0",
            ["NextDialogue"] = 71001406,
            ["Scripts"] = "SetOutport{FinishType{2},OptionIdx{1}}",
            },
        [710014042] = {
