            ["DialogueId"] = 710014042,
            ["GUID"] = "710014042.0",
            ["Scripts"] = "SetOutport{FinishType{2},OptionIdx{2}}",
            },
        [710014051] = {
            ["Content"] = "（卖给外地商人。）",
            ["ContentFR"] = "<I>Vendre au marchand venu de l’extérieur</>",
