        [710035041] = {
            ["Content"] = "道歉有用还要我的拳头做什么。今天就给你们好好长长记性。",
            ["ContentFR"] = "<I>Si « désolé » suffisait, je n’aurais pas besoin de mon épée. Laissez-moi plutôt vous donner une bonne leçon.</>",
            ["DialogueId"] = 710035041,
            ["GUID"] = "710035041.0",
            },
        [710035042] = {
            ["Content"] = "同样的话我听很多人说过，但我愿意给你们一次机会。以后别再做这种事了。",
            ["ContentFR"] = "<I>J’ai déjà entendu ça des dizaines de fois... Mais je vais vous laisser une chance. Ne recommencez plus.</>",
            ["DialogueId"] = 710035042,
            ["GUID"] = "710035042.0",
            },
        [710037041] = {
            ["Content"] = "收到收到，嗷呜嗷呜嗷呜。",
            ["ContentFR"] = "<I>Pas de problème. Bam ! Boum !</>",
            ["DialogueId"] = 710037041,
            ["GUID"] = "710037021.0",
            ["NextDialogue"] = 71003705,
            },
        [710037042] = {
            ["Content"] = "你又在被工作压榨得说气话了。",
            ["ContentFR"] = "<I>Tu râles encore parce que le boulot te retombe dessus.</>",
