        [800202092] = {
            ["Content"] = "太危险了。",
            ["ContentFR"] = "Ça a l’air terriblement dangereux.",
            ["DialogueId"] = 800202092,
            ["GUID"] = "800202092.0",
            ["NextDialogue"] = 80020211,
            },
        [800202161] = {
            ["Content"] = "听起来有些浪漫。",
            ["ContentFR"] = "Ça sonne comme une aventure pleine de charme.",
            ["DialogueId"] = 800202161,
            ["GUID"] = "800202161.0",
            ["NextDialogue"] = 80020217,
            },
        [800202162] = {
            ["Content"] = "听起来很辛苦。",
            ["ContentFR"] = "Ça semble être un métier difficile.",
            ["DialogueId"] = 800202162,
            ["GUID"] = "800202162.0",
            ["NextDialogue"] = 80020218,
            },
        [800203021] = {
            ["Content"] = "我可以一起吗？",
            ["ContentFR"] = "Je peux venir avec toi ?",
            ["DialogueId"] = 800203021,
            ["GUID"] = "800203021.0",
            ["NextDialogue"] = 80020303,
            },
        [800203022] = {
            ["Content"] = "你也会逛街吗？",
            ["ContentFR"] = "Toi, faire les boutiques ?",
            ["DialogueId"] = 800203022,
            ["GUID"] = "800203022.0",
            ["NextDialogue"] = 80020304,
            },
        [800203121] = {
            ["Content"] = "真的这么神奇？",
            ["ContentFR"] = "C’est vraiment si efficace que ça ?",
            ["DialogueId"] = 800203121,
            ["GUID"] = "800203121.0",
            ["NextDialogue"] = 80020313,
            },
        [800203122] = {
            ["Content"] = "听上去确实会很好看。",
            ["ContentFR"] = "Ça a l’air vraiment élégant.",
            ["DialogueId"] = 800203122,
            ["GUID"] = "800203122.0",
            ["NextDialogue"] = 80020314,
            },
        [800203161] = {
            ["Content"] = "王子？",
            ["ContentFR"] = "Un prince ?",
            ["DialogueId"] = 800203161,
            ["GUID"] = "800203161.0",
            ["NextDialogue"] = 80020317,
            },
        [800204021] = {
            ["Content"] = "听起来心情不错？",
            ["ContentFR"] = "Tu sembles de bonne humeur.",
            ["DialogueId"] = 800204021,
            ["GUID"] = "800204021.0",
            ["NextDialogue"] = 80020403,
            },
        [800204022] = {
            ["Content"] = "这才更像是女仆的工作啊。",
            ["ContentFR"] = "Voilà un vrai travail de servante.",
            ["DialogueId"] = 800204022,
            ["GUID"] = "800204022.0",
            ["NextDialogue"] = 80020404,
            },
        [800204091] = {
            ["Content"] = "那么你是遇到了什么烦心事？",
            ["ContentFR"] = "Alors, qu’est-ce qui te tracasse ?",
            ["DialogueId"] = 800204091,
            ["GUID"] = "800204091.0",
            ["NextDialogue"] = 80020410,
            },
        [800204092] = {
            ["Content"] = "展开讲讲你的前同僚们？",
            ["ContentFR"] = "Tu peux m’en dire plus sur tes anciens collègues ?",
            ["DialogueId"] = 800204092,
            ["GUID"] = "800204092.0",
            ["NextDialogue"] = 80020411,
            },
        [800204171] = {
            ["Content"] = "好奇的话，不如直接去见她？",
            ["ContentFR"] = "Si tu te poses la question, pourquoi ne pas aller la voir ?",
            ["DialogueId"] = 800204171,
            ["GUID"] = "800204171.0",
            ["NextDialogue"] = 80020418,
            },
        [800205011] = {
            ["Content"] = "啊？只是巧合而已。",
            ["ContentFR"] = "Ah ? Ce n’est qu’une coïncidence.",
            ["DialogueId"] = 800205011,
            ["GUID"] = "800205011.0",
            ["NextDialogue"] = 80020503,
            },
        [800205012] = {
            ["Content"] = "你的头发那么显眼，很难不注意到。",
            ["ContentFR"] = "Avec des cheveux aussi voyants que les tiens, c’est difficile de ne pas te remarquer.",
            ["DialogueId"] = 800205012,
            ["GUID"] = "800205012.0",
            ["NextDialogue"] = 80020503,
            },
        [800205071] = {
            ["Content"] = "听起来像是解开了心结？",
            ["ContentFR"] = "On dirait que tu as fait la paix.",
            ["DialogueId"] = 800205071,
            ["GUID"] = "800205071.0",
            ["NextDialogue"] = 80020508,
            },
        [800205072] = {
            ["Content"] = "不会觉得可惜吗？",
            ["ContentFR"] = "Tu ne ressens pas un peu de regret ?",
            ["DialogueId"] = 800205072,
            ["GUID"] = "800205072.0",
            ["NextDialogue"] = 80020509,
            },
        [800205121] = {
            ["Content"] = "当我尚在犹豫之时，她毫不迟疑地想要去完成任务——甚至把我也视为必要时可以除去的阻碍。",
            ["ContentFR"] = "Quand j’hésitais encore, elle, elle ne doutait pas et voulait accomplir sa mission, me voyant même comme un obstacle à éliminer si besoin.",
            ["DialogueId"] = 800205121,
            ["GUID"] = "C852AD41",
            ["NextDialogue"] = 80020513,
            ["SpeakNpcId"] = 93102,
            ["TalkActionId"] = {
                [1] = "93102:Sit_Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xier/005/C852AD41",
            },
        [800205141] = {
            ["Content"] = "你还恨着她吗？",
            ["ContentFR"] = "Est-ce que tu la détestes encore ?",
            ["DialogueId"] = 800205141,
            ["GUID"] = "C852AD6C",
            ["NextDialogue"] = 800205143,
            },
        [800205142] = {
            ["Content"] = "你还爱着她吗？",
            ["ContentFR"] = "Est-ce que tu l’aimes toujours ?",
            ["DialogueId"] = 800205142,
            ["GUID"] = "C852AD6D",
            ["NextDialogue"] = 800205143,
            },
        [800205143] = {
            ["Content"] = "坦白说，我不知道。我对她只是有些气恼，有些委屈，还有些想念。对于两个密探来说，你提到的爱和恨，都太奢侈了。",
            ["ContentFR"] = "Honnêtement, je ne sais pas. Je ressens surtout de la colère, un peu de tristesse, et de la nostalgie. Pour des agents comme nous, aimer ou haïr est un luxe qu’on ne peut pas se permettre.",
            ["DialogueId"] = 800205143,
            ["FacialId"] = {
                [1] = "93102:Unhappy01",
                },
            ["GUID"] = "C852AD94",
            ["NextDialogue"] = 80020515,
            ["SpeakNpcId"] = 93102,
            ["TalkActionId"] = {
                [1] = "93102:Sit_DisagreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Xier/005/C852AD94",
            },
        [800205181] = {
            ["Content"] = "嗯？你刚才说了“谢谢”吧？",
            ["ContentFR"] = "Pardon ? Tu viens de dire « merci » ?",
            ["DialogueId"] = 800205181,
            ["GUID"] = "800205181.0",
            ["NextDialogue"] = 80020522,
            },
        [800205182] = {
            ["Content"] = "没听清，再说一遍。",
