            ["DialogueId"] = 800205182,
            ["GUID"] = "800205182.0",
            ["NextDialogue"] = 80020522,
            },
        [800301051] = {
            ["Content"] = "兰迪在这些方面可真有原则啊。",
            ["ContentFR"] = "Franchement, là-dessus, t’as des principes en béton.",
            ["DialogueId"] = 800301051,
            ["GUID"] = "800301051.0",
            ["NextDialogue"] = 80030106,
            },
        [800301052] = {
            ["Content"] = "兰迪总是偷懒呢。",
            ["ContentFR"] = "T’es toujours en train de glander, Randy.",
            ["DialogueId"] = 800301052,
            ["GUID"] = "800301052.0",
            ["NextDialogue"] = 80030107,
            },
        [800302051] = {
            ["Content"] = "为了休假编谎，这也能叫绅士？",
            ["ContentFR"] = "Mentir pour avoir des congés, ça, c’est un gentleman ?",
            ["DialogueId"] = 800302051,
            ["GUID"] = "800302051.0",
            ["NextDialogue"] = 80030206,
            },
        [800302052] = {
            ["Content"] = "嗯，对对，风度翩翩，绅士极了。",
            ["ContentFR"] = "Oui, oui, sans aucun doute, t’es un vrai gentleman.",
            ["DialogueId"] = 800302052,
            ["GUID"] = "800302052.0",
            ["NextDialogue"] = 80030207,
            },
        [800302091] = {
            ["Content"] = "姐姐们？听起来应该也都是淑女。",
            ["ContentFR"] = "Tes sœurs ? Ça devait être de vraies dames, alors.",
            ["DialogueId"] = 800302091,
            ["GUID"] = "800302091.0",
            ["NextDialogue"] = 80030210,
            },
        [800302092] = {
            ["Content"] = "无法想象你还是小男孩的时候。",
