            ["DialogueId"] = 800302092,
            ["GUID"] = "800302092.0",
            ["NextDialogue"] = 80030211,
            },
        [800302131] = {
            ["Content"] = "“关爱”？听上去并不坏啊。",
            ["ContentFR"] = "Bienveillance ? Ça sonne plutôt pas mal.",
            ["DialogueId"] = 800302131,
            ["GUID"] = "800302131.0",
            ["NextDialogue"] = 80030214,
            },
        [800302132] = {
            ["Content"] = "“关爱”？听起来和“绅士”是差不多的用法，辛苦你了。",
            ["ContentFR"] = "Bienveillance ? Ça me rappelle le sens sarcastique de \"gentleman\". Tu as dû souffrir, dis donc.",
            ["DialogueId"] = 800302132,
            ["GUID"] = "800302132.0",
            ["NextDialogue"] = 80030215,
            },
        [800304031] = {
            ["Content"] = "是不是遇到什么烦心事了？你平时不这样。",
            ["ContentFR"] = "Quelque chose te tracasse ? Tu n’es pas comme ça d’habitude.",
            ["DialogueId"] = 800304031,
            ["GUID"] = "800304031.0",
            ["NextDialogue"] = 80030404,
            },
        [800304032] = {
            ["Content"] = "这么急着走，是被人约了跳舞吗？",
            ["ContentFR"] = "T’es pressé... t’as une autre danse de prévue, c’est ça ?",
            ["DialogueId"] = 800304032,
            ["GUID"] = "800304032.0",
            ["NextDialogue"] = 80030406,
            },
        [800304071] = {
            ["Content"] = "噩梦？",
