            ["NextDialogue"] = 80100323,
            },
        [801003321] = {
            ["Content"] = "我怎么感觉你乐在其中？",
            ["ContentFR"] = "Pourquoi ai-je l’impression que tu aimes ça ?",
            ["DialogueId"] = 801003321,
            ["GUID"] = "801003321.0",
            ["NextDialogue"] = 80100333,
            },
        [801003331] = {
            ["Content"] = "命定之人？",
            ["ContentFR"] = "{性别:Destiné|Destinée} à toi ?",
            ["DialogueId"] = 801003331,
            ["GUID"] = "801003331.0",
            ["NextDialogue"] = 80100334,
            },
        [801004011] = {
            ["Content"] = "是遇到了什么烦心事吗？",
            ["ContentFR"] = "Tu sembles contrariée... Quelque chose te tracasse ?",
            ["DialogueId"] = 801004011,
            ["GUID"] = "801004011.0",
            ["NextDialogue"] = 80100402,
            },
        [801004012] = {
            ["Content"] = "看来我邀请你的时间不合时宜。",
            ["ContentFR"] = "Je suppose que je ne t’ai pas invitée au bon moment.",
            ["DialogueId"] = 801004012,
            ["GUID"] = "801004012.0",
            ["NextDialogue"] = 80100403,
            },
        [801004121] = {
            ["Content"] = "你在逃避真实的自己。",
            ["ContentFR"] = "Tu fuis ce que tu ressens vraiment.",
            ["DialogueId"] = 801004121,
            ["GUID"] = "801004121.0",
            ["NextDialogue"] = 80100413,
            },
        [801004122] = {
            ["Content"] = "演技真差！",
            ["ContentFR"] = "Ton jeu d’actrice laisse à désirer.",
            ["DialogueId"] = 801004122,
            ["GUID"] = "801004122.0",
            ["NextDialogue"] = 80100415,
            },
        [801101021] = {
            ["Content"] = "看来还是军团好吃好喝的太多了。",
            ["ContentFR"] = "On dirait que la Légion est plutôt bien lotie côté repas et boissons.",
            ["DialogueId"] = 801101021,
            ["GUID"] = "801101021.0",
            ["NextDialogue"] = 80110103,
            },
        [801101051] = {
            ["Content"] = "我听说军团好像得到了一个叫“零号”的宝贝……",
            ["ContentFR"] = "Il paraît que la Légion a récupéré un certain \"n° 0\"...",
            ["DialogueId"] = 801101051,
            ["GUID"] = "801101051.0",
            ["NextDialogue"] = 80110106,
            },
        [801101052] = {
            ["Content"] = "你想太多了，就是单纯请你喝杯酒而已。",
            ["ContentFR"] = "Tu te fais des films, je veux juste t’offrir un verre.",
            ["DialogueId"] = 801101052,
            ["GUID"] = "801101052.0",
            ["NextDialogue"] = 80110112,
            },
        [801101141] = {
            ["Content"] = "原来你也做过狩月人。",
            ["ContentFR"] = "Tu étais aussi une Chasseuse de Phoxène ?",
            ["DialogueId"] = 801101141,
            ["GUID"] = "801101141.0",
            ["NextDialogue"] = 80110115,
            },
        [801101142] = {
            ["Content"] = "原来你是冰湖城本地人。",
            ["ContentFR"] = "Tu viens de Givrelac, alors ?",
            ["DialogueId"] = 801101142,
            ["GUID"] = "801101142.0",
            ["NextDialogue"] = 80110115,
            },
        [801101161] = {
            ["Content"] = "你好像很害怕说错话？",
            ["ContentFR"] = "Tu as l’air de faire attention à ce que tu dis.",
            ["DialogueId"] = 801101161,
            ["GUID"] = "801101161.0",
            ["NextDialogue"] = 80110117,
            },
        [801101201] = {
            ["Content"] = "那你在军团不会觉得很拘束吗？",
            ["ContentFR"] = "Tu ne te sens pas un peu à l’étroit, dans la Légion ?",
            ["DialogueId"] = 801101201,
            ["GUID"] = "801101201.0",
            ["NextDialogue"] = 80110121,
            },
        [801101202] = {
            ["Content"] = "看不出来，我看你还挺威风的。",
            ["ContentFR"] = "Pourtant, on dirait que tu t’y fais plutôt bien, non ?",
            ["DialogueId"] = 801101202,
            ["GUID"] = "801101202.0",
            ["NextDialogue"] = 80110122,
            },
        [801101261] = {
            ["Content"] = "这是我可以听的吗？",
            ["ContentFR"] = "… Je suis {性别:censé|censée} écouter ça ?",
            ["DialogueId"] = 801101261,
            ["GUID"] = "801101261.0",
            ["NextDialogue"] = 80110127,
            },
        [801101301] = {
            ["Content"] = "我就开个玩笑！",
            ["ContentFR"] = "Ouah, je plaisantais !",
            ["DialogueId"] = 801101301,
            ["GUID"] = "801101301.0",
            ["NextDialogue"] = 80110131,
            },
        [801101361] = {
            ["Content"] = "这……也是我可以听的吗？",
            ["ContentFR"] = "Je note rien, promis. Mais t’es sûre de vouloir finir grillée ?",
            ["DialogueId"] = 801101361,
            ["GUID"] = "801101361.0",
            ["NextDialogue"] = 80110137,
            },
        [801102021] = {
            ["Content"] = "是的。在卡米拉女士那里。",
            ["ContentFR"] = "Oui, chez Madame Camilla.",
            ["DialogueId"] = 801102021,
            ["GUID"] = "801102021.0",
            ["NextDialogue"] = 80110203,
            },
        [801102031] = {
            ["Content"] = "还有杀人越货的委托？！",
            ["ContentFR"] = "Quoi ? Y’a carrément des missions de pillage et d’assassinat dans le coin ?",
            ["DialogueId"] = 801102031,
            ["GUID"] = "801102031.0",
            ["NextDialogue"] = 80110204,
            },
        [801102051] = {
            ["Content"] = "不，她挺和善的。",
            ["ContentFR"] = "Non, maintenant elle est super gentille.",
            ["DialogueId"] = 801102051,
            ["GUID"] = "801102051.0",
            ["NextDialogue"] = 80110206,
            },
        [801102052] = {
            ["Content"] = "没错，很是凶恶。",
            ["ContentFR"] = "Oh que oui, toujours aussi féroce.",
            ["DialogueId"] = 801102052,
            ["GUID"] = "801102052.0",
            ["NextDialogue"] = 80110207,
            },
        [801102071] = {
            ["Content"] = "……你长官是谁？",
            ["ContentFR"] = "… C’est qui, ta supérieure ?",
            ["DialogueId"] = 801102071,
            ["GUID"] = "801102071.0",
            ["NextDialogue"] = 80110208,
            },
        [801102091] = {
            ["Content"] = "我觉得你好像也差不多……",
            ["ContentFR"] = "Franchement... t’as un peu le même genre d’aura.",
            ["DialogueId"] = 801102091,
            ["GUID"] = "801102091.0",
            ["NextDialogue"] = 80110210,
            },
        [801102151] = {
            ["Content"] = "……看来你长官还是有不少有趣的事的？能多和我讲讲吗？",
            ["ContentFR"] = "... Elle a l’air plutôt particulière, ta supérieure. Tu peux m’en dire plus ?",
            ["DialogueId"] = 801102151,
            ["GUID"] = "801102151.0",
            ["NextDialogue"] = 80110216,
            },
        [801102211] = {
            ["Content"] = "请继续说下去。宝贝找到了吗？现在在哪儿？",
            ["ContentFR"] = "Et alors ? Ils l’ont trouvé, ce trésor ? Il est où maintenant ?",
            ["DialogueId"] = 801102211,
            ["GUID"] = "801102211.0",
            ["NextDialogue"] = 80110222,
            },
        [801103021] = {
            ["Content"] = "包裹里是什么？",
            ["ContentFR"] = "Qu’est-ce qu’il y a dans le colis ?",
            ["DialogueId"] = 801103021,
            ["GUID"] = "801103021.0",
            ["NextDialogue"] = 80110303,
            },
        [801103031] = {
            ["Content"] = "我得确认包裹里有没有危险品。",
            ["ContentFR"] = "Faut bien que je vérifie qu’il n’y a rien de dangereux.",
            ["DialogueId"] = 801103031,
            ["GUID"] = "801103031.0",
            ["NextDialogue"] = 80110304,
            },
        [801103032] = {
            ["Content"] = "我也怕送了什么不该送的，会被电死。",
            ["ContentFR"] = "Je ne veux pas livrer quelque chose d'illégal et finir {性别:grillé|grillée}.",
            ["DialogueId"] = 801103032,
            ["GUID"] = "801103032.0",
            ["NextDialogue"] = 80110304,
            },
        [801103051] = {
            ["Content"] = "打一下试试！",
            ["ContentFR"] = "Allez, je teste !",
            ["DialogueId"] = 801103051,
            ["GUID"] = "801103051.0",
            ["NextDialogue"] = 80110306,
            },
        [801103081] = {
            ["Content"] = "这把枪是……一件礼物吗？",
            ["ContentFR"] = "C’est un cadeau, alors ?",
            ["DialogueId"] = 801103081,
            ["GUID"] = "801103081.0",
            ["NextDialogue"] = 80110309,
            },
        [801103101] = {
            ["Content"] = "可以是可以。但既然是给朋友礼物，为什么不自己去呢？",
            ["ContentFR"] = "Ça va, je m’en occupe. Mais si c’est pour une amie, pourquoi tu ne vas pas lui remettre toi-même ?",
            ["DialogueId"] = 801103101,
            ["GUID"] = "801103101.0",
            ["NextDialogue"] = 80110311,
            },
        [801103111] = {
            ["Content"] = "为什么？",
            ["ContentFR"] = "Pourquoi ?",
            ["DialogueId"] = 801103111,
            ["GUID"] = "801103111.0",
            ["NextDialogue"] = 80110312,
            },
        [801103112] = {
            ["Content"] = "大城市待久了，瞧不上冰湖城了？",
            ["ContentFR"] = "Tu t’es trop habituée à la grande ville pour encore supporter Givrelac, c’est ça ?",
            ["DialogueId"] = 801103112,
            ["GUID"] = "801103112.0",
            ["NextDialogue"] = 80110312,
            },
        [801103161] = {
            ["Content"] = "你觉得这一切正常吗？",
            ["ContentFR"] = "Tu trouves ça normal ?",
            ["DialogueId"] = 801103161,
            ["GUID"] = "801103161.0",
            ["NextDialogue"] = 80110317,
            },
        [801103271] = {
            ["Content"] = "你的家人也会怕你吗？",
            ["ContentFR"] = "Ta famille a peur de toi ?",
            ["DialogueId"] = 801103271,
            ["GUID"] = "801103271.0",
            ["NextDialogue"] = 80110328,
            },
        [801103301] = {
            ["Content"] = "我觉得这一切都不正常。",
            ["ContentFR"] = "Je ne pense pas que ce soit normal, justement.",
            ["DialogueId"] = 801103301,
            ["GUID"] = "801103301.0",
            ["NextDialogue"] = 80110331,
            },
        [801201101] = {
            ["Content"] = "你还好吗？",
            ["ContentFR"] = "Tu vas bien ?",
            ["DialogueId"] = 801201101,
            ["GUID"] = "801201101.0",
            ["NextDialogue"] = 80120111,
            },
        [801201102] = {
            ["Content"] = "（拍拍玛尔洁的肩膀）",
            ["ContentFR"] = "Tapoter l’épaule de Margie",
            ["DialogueId"] = 801201102,
            ["GUID"] = "801201102.0",
            ["NextDialogue"] = 80120111,
            },
        [801201161] = {
            ["Content"] = "所以刚刚那只“小狗”是……？",
            ["ContentFR"] = "Alors ce « p’tit chien », c’était qui ?",
            ["DialogueId"] = 801201161,
            ["GUID"] = "801201161.0",
            ["NextDialogue"] = 80120117,
            },
        [801201211] = {
            ["Content"] = "意外之喜？",
            ["ContentFR"] = "Tiré le gros lot ? Pourquoi ?",
            ["DialogueId"] = 801201211,
            ["GUID"] = "801201211.0",
            ["NextDialogue"] = 80120122,
            },
        [801201271] = {
            ["Content"] = "介意我伸出援手吗？",
            ["ContentFR"] = "Tu veux un coup de main ?",
            ["DialogueId"] = 801201271,
            ["GUID"] = "801201271.0",
            ["NextDialogue"] = 80120128,
            },
        [801201272] = {
            ["Content"] = "见者有份，我也分点。",
            ["ContentFR"] = "Qui trouve garde... mais je me prends une part aussi.",
            ["DialogueId"] = 801201272,
            ["GUID"] = "801201272.0",
            ["NextDialogue"] = 80120129,
            },
        [801202041] = {
            ["Content"] = "听上去是空心的？",
            ["ContentFR"] = "Ça sonne creux, non ?",
            ["DialogueId"] = 801202041,
            ["GUID"] = "801202041.0",
            ["NextDialogue"] = 80120205,
            },
        [801202042] = {
            ["Content"] = "声音很好听，是好木板。",
            ["ContentFR"] = "Joli son. C’est du bon bois.",
            ["DialogueId"] = 801202042,
            ["GUID"] = "801202042.0",
            ["NextDialogue"] = 80120206,
            },
        [801202111] = {
            ["Content"] = "这一页夹了张纸条，上面写了些什么？",
            ["ContentFR"] = "Il y a un mot coincé dans la page. Qu’est-ce qu’il dit ?",
            ["DialogueId"] = 801202111,
            ["GUID"] = "801202111.0",
            ["NextDialogue"] = 80120212,
            },
        [801202181] = {
            ["Content"] = "他终究还是被时间改变了。",
            ["ContentFR"] = "Le temps a fini par le changer.",
            ["DialogueId"] = 801202181,
            ["GUID"] = "801202181.0",
            ["NextDialogue"] = 80120219,
            },
        [801202182] = {
            ["Content"] = "也许他从未改变，所以他故意留下了这份乐谱。",
            ["ContentFR"] = "Ou alors, il n’a jamais changé. Il a fait exprès de laisser cette partition.",
            ["DialogueId"] = 801202182,
            ["GUID"] = "801202182.0",
            ["NextDialogue"] = 80120220,
            },
        [801203021] = {
            ["Content"] = "虽然加了糖，但玛尔洁还喝不惯咖啡呢。",
            ["ContentFR"] = "Même avec du sucre, notre Margie ne s’habitue toujours pas au café.",
            ["DialogueId"] = 801203021,
            ["GUID"] = "801203021.0",
            ["NextDialogue"] = 80120303,
            },
        [801203031] = {
            ["Content"] = "玛尔洁更喜欢清凉爽口或者甜滋滋的味道吗？",
            ["ContentFR"] = "Tu préfères les boissons fraîches ou sucrées, c’est ça ?",
            ["DialogueId"] = 801203031,
            ["GUID"] = "801203031.0",
            ["NextDialogue"] = 80120304,
            },
        [801203041] = {
            ["Content"] = "“你家臭老头”是……？",
            ["ContentFR"] = "« Ton vieux crétin », c’est qui ?",
            ["DialogueId"] = 801203041,
            ["GUID"] = "801203041.0",
            ["NextDialogue"] = 80120305,
            },
        [801203071] = {
            ["Content"] = "收到！缄默侦探小姐！",
            ["ContentFR"] = "Compris ! Mademoiselle Détective Taciturne !",
            ["DialogueId"] = 801203071,
            ["GUID"] = "801203071.0",
            ["NextDialogue"] = 80120308,
            },
        [801203081] = {
            ["Content"] = "收到！史上最帅气、智慧、可靠的“垃圾桶公主”殿下！",
            ["ContentFR"] = "Compris ! La plus cool, la plus intelligente et la plus fiable des « Princesse des Déchets » !",
            ["DialogueId"] = 801203081,
            ["GUID"] = "801203081.0",
            ["NextDialogue"] = 80120309,
            },
        [801203101] = {
            ["Content"] = "之前好像没听你提过父亲？",
            ["ContentFR"] = "Je ne t’ai jamais entendue parler de ton père avant ?",
            ["DialogueId"] = 801203101,
            ["GUID"] = "801203101.0",
            ["NextDialogue"] = 80120311,
            },
        [801203111] = {
            ["Content"] = "那不是彼此彼此吗！",
            ["ContentFR"] = "C’est un peu pareil pour vous deux, non ?",
            ["DialogueId"] = 801203111,
            ["GUID"] = "801203111.0",
            ["NextDialogue"] = 80120312,
            },
        [801203121] = {
            ["Content"] = "要不怎么你俩是父女呢。",
            ["ContentFR"] = "Tel père, telle fille, hein ?",
            ["DialogueId"] = 801203121,
            ["GUID"] = "801203121.0",
            ["NextDialogue"] = 80120313,
            },
        [801203161] = {
            ["Content"] = "……你刚才是不是说了什么很不妙的东西？！",
            ["ContentFR"] = "Hein ? Tu viens de balancer un truc super louche, là ?!",
            ["DialogueId"] = 801203161,
            ["GUID"] = "801203161.0",
            ["NextDialogue"] = 80120317,
            },
        [801203181] = {
            ["Content"] = "但是，既然马丁带着你离开了老家，那他也不喜欢那里吧。",
            ["ContentFR"] = "Mais puisqu’il t’a emmenée loin de là-bas, il n’aimait sûrement pas vraiment cet endroit, non ?",
            ["DialogueId"] = 801203181,
            ["GUID"] = "801203181.0",
            ["NextDialogue"] = 80120319,
            },
        [801203211] = {
            ["Content"] = "还有这事？当时你是怎么说话的，能不能再表演一下？",
            ["ContentFR"] = "Ah ouais ? Comment tu parlais exactement ? Tu peux me faire une petite démo ?",
            ["DialogueId"] = 801203211,
            ["GUID"] = "801203211.0",
            ["NextDialogue"] = 80120322,
            },
        [801203221] = {
            ["Content"] = "拜托了，尊敬的缄默侦探小姐，我愿意用你最爱喝的饮料交换！",
            ["ContentFR"] = "S’il te plaît Mademoiselle Détective Réticente, je t’échange ta boisson préférée contre une démonstration !",
            ["DialogueId"] = 801203221,
            ["GUID"] = "801203221.0",
            ["NextDialogue"] = 80120323,
            },
        [801203231] = {
            ["Content"] = "不说的话，那我只有……垃圾桶公主殿下——",
            ["ContentFR"] = "Si tu refuses, je serai obligé de... Princesse des Déchets, votre altesse...",
            ["DialogueId"] = 801203231,
            ["GUID"] = "801203231.0",
            ["NextDialogue"] = 80120324,
            },
        [801203261] = {
            ["Content"] = "（忍笑。）",
            ["ContentFR"] = "Tenter de ne pas éclater de rire",
            ["DialogueId"] = 801203261,
            ["GUID"] = "801203261.0",
            ["NextDialogue"] = 80120327,
            },
        [801203271] = {
            ["Content"] = "（忍不住了！）",
            ["ContentFR"] = "Ne parvient plus à se retenir",
            ["DialogueId"] = 801203271,
            ["GUID"] = "801203271.0",
            ["NextDialogue"] = 80120328,
            },
        [801203281] = {
            ["Content"] = "（不忍了！）",
            ["ContentFR"] = "Exploser de rire !",
            ["DialogueId"] = 801203281,
            ["GUID"] = "801203281.0",
            ["NextDialogue"] = 80120329,
            },
        [801203361] = {
            ["Content"] = "嘲讽？",
            ["ContentFR"] = "Il s’est moqué de toi ? Comment ça ?",
            ["DialogueId"] = 801203361,
            ["GUID"] = "801203361.0",
            ["NextDialogue"] = 80120337,
            },
        [801203431] = {
            ["Content"] = "用锅子做头盔……老马丁真是品味独特。",
            ["ContentFR"] = "Un casque fait d’une marmite... Martin a vraiment un style unique.",
            ["DialogueId"] = 801203431,
            ["GUID"] = "801203431.0",
            ["NextDialogue"] = 80120344,
            },
        [801203432] = {
            ["Content"] = "原来这是生日礼物……看来老马丁很爱你。",
            ["ContentFR"] = "C’était un cadeau d’anniversaire... On dirait que Martin tient vraiment à toi.",
            ["DialogueId"] = 801203432,
            ["GUID"] = "801203432.0",
            ["NextDialogue"] = 80120344,
            },
        [801204011] = {
            ["Content"] = "你怎么眼泪汪汪的！破案了要笑啊！",
            ["ContentFR"] = "Pourquoi tu pleures ? Tu devrais sourire, c’est une bonne nouvelle !",
            ["DialogueId"] = 801204011,
            ["GUID"] = "801204011.0",
            ["NextDialogue"] = 80120402,
            },
        [801204021] = {
            ["Content"] = "喝杯水，慢慢说。",
            ["ContentFR"] = "Tiens, bois un peu d’eau, raconte-moi tranquillement.",
            ["DialogueId"] = 801204021,
            ["GUID"] = "801204021.0",
            ["NextDialogue"] = 80120403,
            },
        [801204041] = {
            ["Content"] = "“胖尾巴”是什么？",
            ["ContentFR"] = "Touffu ? C’est quoi ?",
            ["DialogueId"] = 801204041,
            ["GUID"] = "801204041.0",
            ["NextDialogue"] = 80120405,
            },
        [801204111] = {
            ["Content"] = "哦~可怜的侦探，被“胖尾巴”玩弄于股掌之间！",
            ["ContentFR"] = "Oh, pauvre détective, complètement manipulée par Touffu !",
            ["DialogueId"] = 801204111,
            ["GUID"] = "801204111.0",
            ["NextDialogue"] = 80120412,
            },
        [801204131] = {
            ["Content"] = "喵喵喵！侦探小姐，我有重大发现！",
            ["ContentFR"] = "Miaou miaou ! Mademoiselle l’enquêtrice, j’ai une piste sérieuse !",
            ["DialogueId"] = 801204131,
            ["GUID"] = "801204131.0",
            ["NextDialogue"] = 80120414,
            },
        [801204141] = {
            ["Content"] = "不仅对垃圾桶了如指掌，甚至组建起了猫猫情报网，不愧是行走于冰湖城背面的缄默侦探小姐！",
            ["ContentFR"] = "Tu connais les poubelles comme ta poche, et tu as monté un réseau d’infos chez les chats errants. Mademoiselle Détective Taciturne de Givrelac, chapeau !",
            ["DialogueId"] = 801204141,
            ["GUID"] = "801204141.0",
            ["NextDialogue"] = 80120415,
            },
        [801204221] = {
            ["Content"] = "你不也慢慢不再需要老马丁的照顾，和胖尾巴一样，照顾着那些需要帮助的人。",
            ["ContentFR"] = "Toi aussi tu as grandi, tu n’as plus besoin du vieux Martin et tu prends soin de ceux qui ont besoin d’aide, comme Touffu.",
            ["DialogueId"] = 801204221,
            ["GUID"] = "801204221.0",
            ["NextDialogue"] = 80120423,
            },
        [801204251] = {
            ["Content"] = "为什么会这么想？",
            ["ContentFR"] = "Pourquoi pensais-tu ça ?",
            ["DialogueId"] = 801204251,
            ["GUID"] = "801204251.0",
            ["NextDialogue"] = 80120426,
            },
        [801204281] = {
            ["Content"] = "你居然不选择和老马丁在一起，他听到会哭的。",
            ["ContentFR"] = "Tu as choisi Touffu plutôt que le vieux Martin, il va pleurer s’il l’apprend.",
            ["DialogueId"] = 801204281,
            ["GUID"] = "801204281.0",
            ["NextDialogue"] = 80120429,
            },
        [801204291] = {
            ["Content"] = "但以你当时的年纪，回到雪原很不安全。",
            ["ContentFR"] = "Mais tu étais trop jeune, retourner dans les champs enneigés n’aurait pas été sûr.",
            ["DialogueId"] = 801204291,
            ["GUID"] = "801204291.0",
            ["NextDialogue"] = 80120430,
            },
        [801204391] = {
            ["Content"] = "胖尾巴很通人性。",
            ["ContentFR"] = "Touffu est vraiment intelligente.",
            ["DialogueId"] = 801204391,
            ["GUID"] = "801204391.0",
            ["NextDialogue"] = 80120440,
            },
        [801204401] = {
            ["Content"] = "猫叫你回家，猫好。你害猫担心，你坏。",
            ["ContentFR"] = "Le chat t’a rappelée à la maison, c’est bien. Mais tu l’as inquiétée, et ça, c’est pas bien.",
            ["DialogueId"] = 801204401,
            ["GUID"] = "801204401.0",
            ["NextDialogue"] = 80120441,
            },
        [801204471] = {
            ["Content"] = "都长大了——指今天又哭着鼻子跑了过来？",
            ["ContentFR"] = "Oui, grandi... et aujourd’hui encore, tu es venue en pleurant.",
            ["DialogueId"] = 801204471,
            ["GUID"] = "801204471.0",
            ["NextDialogue"] = 80120448,
            },
        [801301051] = {
            ["Content"] = "这么急？",
            ["ContentFR"] = "Tu pars déjà ?",
            ["DialogueId"] = 801301051,
            ["GUID"] = "801301051.0",
            ["NextDialogue"] = 80130106,
            },
        [801301052] = {
            ["Content"] = "（这小孩内向过头了……）",
            ["ContentFR"] = "– Ce gamin est vraiment trop timide...",
            ["DialogueId"] = 801301052,
            ["GUID"] = "801301052.0",
            ["NextDialogue"] = 80130107,
            },
        [801301111] = {
            ["Content"] = "啊呜！我要吃小孩了！",
            ["ContentFR"] = "Awooo ! Je vais te manger tout cru !",
            ["DialogueId"] = 801301111,
            ["GUID"] = "801301111.0",
            ["NextDialogue"] = 80130112,
            },
        [801301112] = {
            ["Content"] = "我是治愈系狩月人，不要害怕。",
            ["ContentFR"] = "Je suis {性别:un Chasseur de Phoxène|une Chasseuse de Phoxène} au grand cœur, n’aie pas peur.",
            ["DialogueId"] = 801301112,
            ["GUID"] = "801301112.0",
            ["NextDialogue"] = 80130114,
            },
        [801301181] = {
            ["Content"] = "呃，可是为什么要和我说这些。",
            ["ContentFR"] = "Euh... pourquoi tu me dis tout ça ?",
            ["DialogueId"] = 801301181,
            ["GUID"] = "801301181.0",
            ["NextDialogue"] = 80130119,
            },
        [801301182] = {
            ["Content"] = "听起来很有意思的，那么在哪里能买到呢？",
            ["ContentFR"] = "Ça a l’air amusant. Où peut-on les acheter ?",
            ["DialogueId"] = 801301182,
            ["GUID"] = "801301182.0",
            ["NextDialogue"] = 80130120,
            },
        [801302021] = {
            ["Content"] = "记得，还记得你好像不太敢和陌生人说话。",
            ["ContentFR"] = "Bien sûr. Je me rappelle surtout que tu n’étais pas très à l’aise avec les inconnus.",
            ["DialogueId"] = 801302021,
            ["GUID"] = "801302021.0",
            ["NextDialogue"] = 80130203,
            },
        [801302022] = {
            ["Content"] = "还记得你的伙伴奥利弗哦。",
            ["ContentFR"] = "Je me souviens aussi de ton partenaire, Oliver.",
            ["DialogueId"] = 801302022,
            ["GUID"] = "801302022.0",
            ["NextDialogue"] = 80130204,
            },
        [801302111] = {
            ["Content"] = "这个老爷爷也太不负责任了。",
            ["ContentFR"] = "Il est juste parti comme ça ? C’est un peu irresponsable.",
            ["DialogueId"] = 801302111,
            ["GUID"] = "801302111.0",
            ["NextDialogue"] = 80130212,
            },
        [801302112] = {
            ["Content"] = "能够一直坚持下来已经很了不起了。",
            ["ContentFR"] = "C’est déjà impressionnant que tu sois parvenu à tenir la boutique tout seul.",
            ["DialogueId"] = 801302112,
            ["GUID"] = "801302112.0",
            ["NextDialogue"] = 80130213,
            },
        [801302211] = {
            ["Content"] = "想要和他问明白怎么回事？",
            ["ContentFR"] = "Tu veux connaître la vérité ?",
            ["DialogueId"] = 801302211,
            ["GUID"] = "801302211.0",
            ["NextDialogue"] = 80130222,
            },
        [801302212] = {
            ["Content"] = "想要把“噼里啪啦”还给他？",
            ["ContentFR"] = "Tu penses lui rendre Crac’n’Pop ?",
            ["DialogueId"] = 801302212,
            ["GUID"] = "801302212.0",
            ["NextDialogue"] = 80130223,
            },
        [801302271] = {
            ["Content"] = "为什么不找奥利弗商量呢？",
            ["ContentFR"] = "Pourquoi tu n’en parles pas à Oliver ?",
            ["DialogueId"] = 801302271,
            ["GUID"] = "801302271.0",
            ["NextDialogue"] = 80130229,
            },
        [801303021] = {
            ["Content"] = "你怎么了，耶尔？",
            ["ContentFR"] = "Qu’est-ce qui se passe, Yale ?",
            ["DialogueId"] = 801303021,
            ["GUID"] = "801303021.0",
            ["NextDialogue"] = 80130303,
            },
        [801303022] = {
            ["Content"] = "你不是耶尔。",
            ["ContentFR"] = "Tu n’es pas Yale.",
            ["DialogueId"] = 801303022,
            ["GUID"] = "801303022.0",
            ["NextDialogue"] = 80130304,
            },
        [801303071] = {
            ["Content"] = "虽然不知道发生了什么，但是你这并不是请求人的态度。",
            ["ContentFR"] = "Je sais pas ce qui se passe, mais t’as pas l’air de demander un service.",
            ["DialogueId"] = 801303071,
            ["GUID"] = "801303071.0",
            ["NextDialogue"] = 80130308,
            },
        [801303072] = {
            ["Content"] = "你先告诉我耶尔去哪儿了，否则免谈。",
            ["ContentFR"] = "Dis-moi où est Yale, ensuite nous pourrons discuter.",
            ["DialogueId"] = 801303072,
            ["GUID"] = "801303072.0",
            ["NextDialogue"] = 80130309,
            },
        [801303231] = {
            ["Content"] = "抱歉……我没太听明白……",
            ["ContentFR"] = "{性别:Désolé|Désolée}... j’ai pas tout suivi.",
            ["DialogueId"] = 801303231,
            ["GUID"] = "801303231.0",
            ["NextDialogue"] = 80130324,
            },
        [801303232] = {
            ["Content"] = "琼斯做了不能被原谅的事情……",
            ["ContentFR"] = "Jones a fait quelque chose d’impardonnable...",
            ["DialogueId"] = 801303232,
            ["GUID"] = "801303232.0",
            ["NextDialogue"] = 80130325,
            },
        [801303401] = {
            ["Content"] = "他说了一个关于“噼里啪啦”的……故事。",
            ["ContentFR"] = "Il a parlé d’une histoire à propos de Crac’n’Pop... du propriétaire.",
            ["DialogueId"] = 801303401,
            ["GUID"] = "801303401.0",
            ["NextDialogue"] = 80130341,
            },
        [801303431] = {
            ["Content"] = "看来你确实忘记怎么说脏话了。",
            ["ContentFR"] = "On dirait que t’as vraiment oublié comment jurer.",
            ["DialogueId"] = 801303431,
            ["GUID"] = "801303431.0",
            ["NextDialogue"] = 80130344,
            },
        [801303432] = {
            ["Content"] = "看来你其实已经能够和他友好相处了。",
            ["ContentFR"] = "On dirait bien que vous arrivez à vous entendre, finalement.",
            ["DialogueId"] = 801303432,
            ["GUID"] = "801303432.0",
            ["NextDialogue"] = 80130345,
            },
        [801304041] = {
            ["Content"] = "是奥利弗把你带来的。",
            ["ContentFR"] = "C’est Oliver qui t’a amené ici.",
            ["DialogueId"] = 801304041,
            ["GUID"] = "801304041.0",
            ["NextDialogue"] = 80130405,
            },
        [801304101] = {
            ["Content"] = "在争夺指挥权吗？",
            ["ContentFR"] = "Vous êtes en train de vous battre pour savoir qui commande ?",
            ["DialogueId"] = 801304101,
            ["GUID"] = "801304101.0",
            ["NextDialogue"] = 80130411,
            },
        [801304102] = {
            ["Content"] = "有什么话别憋在心里，直接讲出来吧。",
            ["ContentFR"] = "Si t’as un truc à dire, dis-le franchement. ",
            ["DialogueId"] = 801304102,
            ["GUID"] = "801304102.0",
            ["NextDialogue"] = 80130414,
            },
        [801304411] = {
            ["Content"] = "谢谢，有空常来玩，你们俩一起。",
            ["ContentFR"] = "Merci. Repassez me voir un jour, tous les deux.",
            ["DialogueId"] = 801304411,
            ["GUID"] = "801304411.0",
            },
        [801501021] = {
            ["Content"] = "嘿！猜猜我是谁！",
            ["ContentFR"] = "Hé ! Devine qui c’est !",
            ["DialogueId"] = 801501021,
            ["GUID"] = "801501021.0",
            ["NextDialogue"] = 80150103,
            },
        [801501022] = {
            ["Content"] = "黎瑟，你在做什么呢？",
            ["ContentFR"] = "Rhythm, qu’est-ce que tu fais ?",
            ["DialogueId"] = 801501022,
            ["GUID"] = "801501022.0",
            ["NextDialogue"] = 80150108,
            },
        [801501151] = {
            ["Content"] = "这也太辛苦了……",
            ["ContentFR"] = "C’est un boulot éreintant...",
            ["DialogueId"] = 801501151,
            ["GUID"] = "801501151.0",
            ["NextDialogue"] = 80150116,
            },
        [801501152] = {
            ["Content"] = "你为冰湖城贡献了很多！",
            ["ContentFR"] = "Tu as tant fait pour Givrelac !",
            ["DialogueId"] = 801501152,
            ["GUID"] = "801501152.0",
            ["NextDialogue"] = 80150116,
            },
        [801501251] = {
            ["Content"] = "……那次事件，我也在现场。",
            ["ContentFR"] = "... J’étais là, ce jour-là.",
            ["DialogueId"] = 801501251,
            ["GUID"] = "801501251.0",
            ["NextDialogue"] = 80150126,
            },
        [801501252] = {
            ["Content"] = "你在自己力所能及的范围内做到了最好。",
            ["ContentFR"] = "Tu as fait tout ce que tu pouvais.",
            ["DialogueId"] = 801501252,
            ["GUID"] = "801501252.0",
            ["NextDialogue"] = 80150128,
            },
        [801502021] = {
            ["Content"] = "嘿！猜猜我是谁！",
            ["ContentFR"] = "Hé ! Devine qui c’est !",
            ["DialogueId"] = 801502021,
            ["GUID"] = "801502021.0",
            ["NextDialogue"] = 80150203,
            },
        [801502022] = {
            ["Content"] = "黎瑟，我来了。",
            ["ContentFR"] = "Rhythm, je suis là.",
            ["DialogueId"] = 801502022,
            ["GUID"] = "801502022.0",
            ["NextDialogue"] = 80150207,
            },
        [801502081] = {
            ["Content"] = "其实不用这么认真的……",
            ["ContentFR"] = "Tu sais, ce n’était pas si grave...",
            ["DialogueId"] = 801502081,
            ["GUID"] = "801502081.0",
            ["NextDialogue"] = 80150209,
            },
        [801502082] = {
            ["Content"] = "我该付给你清洁费了。",
            ["ContentFR"] = "À ce rythme, je vais devoir te payer comme femme de ménage.",
            ["DialogueId"] = 801502082,
            ["GUID"] = "801502082.0",
            ["NextDialogue"] = 80150210,
            },
        [801502121] = {
            ["Content"] = "为什么要这么努力？",
            ["ContentFR"] = "Pourquoi te donner autant de mal ?",
            ["DialogueId"] = 801502121,
            ["GUID"] = "801502121.0",
            ["NextDialogue"] = 80150213,
            },
        [801502122] = {
            ["Content"] = "偶尔偷懒也没关系吧。",
            ["ContentFR"] = "Tu as le droit de lever le pied, parfois.",
            ["DialogueId"] = 801502122,
            ["GUID"] = "801502122.0",
            ["NextDialogue"] = 80150213,
            },
        [801502161] = {
            ["Content"] = "不，我相信你会在无法回头前停下的。",
            ["ContentFR"] = "Je suis {性别:certain|certaine} que tu aurais su t’arrêter avant ça.",
            ["DialogueId"] = 801502161,
            ["GUID"] = "801502161.0",
            ["NextDialogue"] = 80150217,
            },
        [801502162] = {
            ["Content"] = "这正是你和其他人不一样的地方。",
            ["ContentFR"] = "C’est justement ce qui te rend différente des autres.",
            ["DialogueId"] = 801502162,
            ["GUID"] = "801502162.0",
            ["NextDialogue"] = 80150218,
            },
        [801502201] = {
            ["Content"] = "有想说的话，还是说出来比较好哦，既然离开军团了，就不应该还是这么拘谨。",
            ["ContentFR"] = "Si tu as quelque chose à dire, vas-y. Tu n’es plus dans la Légion. Plus besoin d’être aussi réservée.",
            ["DialogueId"] = 801502201,
            ["GUID"] = "801502201.0",
            ["NextDialogue"] = 80150221,
            },
        [801502261] = {
            ["Content"] = "那你来给我打工吧。",
            ["ContentFR"] = "Tu pourrais venir travailler pour moi.",
            ["DialogueId"] = 801502261,
            ["GUID"] = "801502261.0",
            ["NextDialogue"] = 80150227,
            },
        [801502262] = {
            ["Content"] = "那就先继续打零工，目标会自然产生的。",
            ["ContentFR"] = "Continue les petits boulots pour l’instant. L’objectif viendra de lui-même.",
            ["DialogueId"] = 801502262,
            ["GUID"] = "801502262.0",
            ["NextDialogue"] = 80150230,
            },
        [801503031] = {
            ["Content"] = "黎瑟？",
            ["ContentFR"] = "Rhythm ?",
            ["DialogueId"] = 801503031,
            ["GUID"] = "801503031.0",
            ["NextDialogue"] = 80150304,
            },
        [801503091] = {
            ["Content"] = "我觉得你吹得不错。",
            ["ContentFR"] = "Je trouve que tu joues plutôt bien.",
            ["DialogueId"] = 801503091,
            ["GUID"] = "801503091.0",
            ["NextDialogue"] = 80150310,
            },
        [801503092] = {
            ["Content"] = "你可以在这里慢慢练习的。",
            ["ContentFR"] = "Tu peux t’entraîner ici, je suis là quand tu veux.",
            ["DialogueId"] = 801503092,
            ["GUID"] = "801503092.0",
            ["NextDialogue"] = 80150310,
            },
        [801503141] = {
            ["Content"] = "是另一种意义上的厉害啊……",
            ["ContentFR"] = "C’est une forme de talent à part entière...",
            ["DialogueId"] = 801503141,
            ["GUID"] = "801503141.0",
            ["NextDialogue"] = 80150315,
            },
        [801503142] = {
            ["Content"] = "每个人学习的方法不一样，这没什么大不了的。",
            ["ContentFR"] = "Chacun apprend à sa manière, c’est normal.",
            ["DialogueId"] = 801503142,
            ["GUID"] = "801503142.0",
            ["NextDialogue"] = 80150315,
            },
        [801503161] = {
            ["Content"] = "没问题！",
            ["ContentFR"] = "Pas de problème !",
            ["DialogueId"] = 801503161,
            ["GUID"] = "801503161.0",
            ["NextDialogue"] = 80150317,
            },
        [801503162] = {
            ["Content"] = "我也不太会看乐谱……",
            ["ContentFR"] = "Je ne sais pas bien lire les partitions non plus...",
            ["DialogueId"] = 801503162,
            ["GUID"] = "801503162.0",
            ["NextDialogue"] = 80150318,
            },
        [801601021] = {
            ["Content"] = "？您走错了吧。",
            ["ContentFR"] = "Vous ne vous êtes pas trompée d’endroit, par hasard ?",
            ["DialogueId"] = 801601021,
            ["GUID"] = "801601021.0",
            ["NextDialogue"] = 80160103,
            },
        [801601022] = {
            ["Content"] = "不好意思，这里不是酒馆。想来一杯的话，我知道城里有那么一家。",
            ["ContentFR"] = "{性别:Désolé|Désolée}, ici ce n’est pas une taverne. Si vous cherchez un vrai verre, je connais un bon endroit en ville.",
            ["DialogueId"] = 801601022,
            ["GUID"] = "801601022.0",
            ["NextDialogue"] = 80160106,
            },
        [801601071] = {
            ["Content"] = "……怎么证明是卡米拉女士让你来的？",
            ["ContentFR"] = "... Comment pouvez-vous prouver que c’est bien Madame Scarlet qui vous a envoyée ?",
            ["DialogueId"] = 801601071,
            ["GUID"] = "801601071.0",
            ["NextDialogue"] = 80160108,
            },
        [801602011] = {
            ["Content"] = "抱歉，让你久等了。这瓶酒实在被藏得太深了，稍等，我来醒酒。",
            ["ContentFR"] = "Veuillez m’excuser pour l’attente. Cette bouteille était vraiment bien cachée... Donnez-moi un instant, je vais la laisser respirer.",
            ["DialogueId"] = 801602011,
            ["GUID"] = "801602011",
            ["NextDialogue"] = 80160202,
            },
        [801602041] = {
            ["Content"] = "不至于吧……",
            ["ContentFR"] = "Est-ce vraiment nécessaire... ?",
            ["DialogueId"] = 801602041,
            ["GUID"] = "801602041.0",
            ["NextDialogue"] = 80160205,
            },
        [801602042] = {
            ["Content"] = "有什么不妥吗？",
            ["ContentFR"] = "Vous avez remarqué quelque chose d’anormal dans la maison ?",
            ["DialogueId"] = 801602042,
            ["GUID"] = "801602042.0",
            ["NextDialogue"] = 80160205,
            },
        [801602061] = {
            ["Content"] = "？？？",
            ["ContentFR"] = "?!",
            ["DialogueId"] = 801602061,
            ["GUID"] = "801602061.0",
            ["NextDialogue"] = 80160207,
            },
        [801602062] = {
            ["Content"] = "不是，女士，你做什么工作的？",
            ["ContentFR"] = "Pardon... Puis-je vous demander ce que vous faites dans la vie ?",
            ["DialogueId"] = 801602062,
            ["GUID"] = "801602062.0",
            ["NextDialogue"] = 80160207,
            },
        [801602081] = {
            ["Content"] = "这个……过会一定……",
            ["ContentFR"] = "Je... Je tâcherai d’y penser.",
            ["DialogueId"] = 801602081,
            ["GUID"] = "801602081.0",
            ["NextDialogue"] = 80160209,
            },
        [801602082] = {
            ["Content"] = "过会一定！",
            ["ContentFR"] = "Dès demain matin, je fouille tout de fond en comble.",
            ["DialogueId"] = 801602082,
            ["GUID"] = "801602082.0",
            ["NextDialogue"] = 80160209,
            },
        [801602141] = {
            ["Content"] = "她已经……离开了吗？",
            ["ContentFR"] = "« Était » ? Elle n’est donc plus à vos côtés ?",
            ["DialogueId"] = 801602141,
            ["GUID"] = "801602141.0",
            ["NextDialogue"] = 80160215,
            },
        [801602201] = {
            ["Content"] = "你最好的同僚被她害死了？",
            ["ContentFR"] = "Cette femme... a tué votre collègue ?",
            ["DialogueId"] = 801602201,
            ["GUID"] = "801602201.0",
            ["NextDialogue"] = 80160221,
            },
        [801602202] = {
            ["Content"] = "你最好的同僚就是告密者？",
            ["ContentFR"] = "Votre collègue... c’est elle, la taupe ?",
            ["DialogueId"] = 801602202,
            ["GUID"] = "801602202.0",
            ["NextDialogue"] = 80160222,
            },
        [801602241] = {
            ["Content"] = "没有立刻去处理公务，而是在这喝酒……",
            ["ContentFR"] = "Vous buvez tranquillement ici au lieu de la juger ?",
            ["DialogueId"] = 801602241,
            ["GUID"] = "801602241.0",
            ["NextDialogue"] = 80160225,
            },
        [801602242] = {
            ["Content"] = "你犹豫了吧？",
            ["ContentFR"] = "Vous hésitez, pas vrai ?",
            ["DialogueId"] = 801602242,
            ["GUID"] = "801602242.0",
            ["NextDialogue"] = 80160225,
            },
        [801603051] = {
            ["Content"] = "你喝得太多了。",
            ["ContentFR"] = "Vous avez déjà trop bu.",
            ["DialogueId"] = 801603051,
            ["GUID"] = "801603051.0",
            ["NextDialogue"] = 80160306,
            },
        [801603052] = {
            ["Content"] = "给我留点。",
            ["ContentFR"] = "Gardez-m’en un peu.",
            ["DialogueId"] = 801603052,
            ["GUID"] = "801603052.0",
            ["NextDialogue"] = 80160307,
            },
        [801603071] = {
            ["Content"] = "……还是想些高兴的事情吧，就算是女士您，也会有一些美好的回忆吧？",
            ["ContentFR"] = "... Peut-être vaudrait-il mieux penser à des choses plus joyeuses. Même quelqu’un d’aussi impassible que vous doit bien avoir un souvenir heureux ?",
            ["DialogueId"] = 801603071,
            ["GUID"] = "801603071.0",
            ["NextDialogue"] = 80160308,
